INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1254A}/[H1254]', 'lemma', 'heb', 'בָּרָא', '["bârâʼ"]', '["I created","[I am] about to create","[am] about to create","[the one who] created","[the] creator of","[who will] be created","[who] created","create","created","did he create","have you created","he created","he had created","he has created","he will create","make","make [it]","they have been created","you were created"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/[H433]', 'lemma', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["<of> God","God","God of","O God","O God of","[am] God","[am] [the] God of","[am] a god","[are] God","[are] [the] God of","[is] God","[is] [the] God of","[is] a God","[is] a God of","[is] a god","[is] a god of","[the] God","[the] God of","[the] god","[the] god of","[the] judges","a God","a god"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
