INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/[H5920]', 'lemma', 'heb', 'עַל', '["ʻal"]', '["<on>","[am] on","[are] on","[are] over","[are] towards","[be] on","[be] over","[had been] over","[is] above","[is] at","[is] on","[is] over","[is] to","[is] towards","[was] above","[was] at","[was] on","[was] over","[was] towards","[were] at","[were] on","[were] over","[were] with","[will be] above","[will be] at","[will be] on","[will be] over","about","above","at","because","because of","beside","concerning","on","over","there-","to","toward","towards","with"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440J}/[H6437]', 'lemma', 'heb', 'פָּנִים', '["pânîym"]', '["[the] face","[the] face of","[the] presence of","[the] surface of"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8415}/[H1949]', 'lemma', 'heb', 'תְּהוֹם', '["tᵉhôwm"]', '["[are] [the] deep","[the] deep","[the] deeps","[the] depths","[were] [the] deeps","deep"]', '["n"]', 'an abyss (as a surging mass of water), especially the deep (the main sea or the subterranean watersupply) deep (place), depth.', 'or תְּהֹם; (usually feminine) from 1949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7307G}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ [the] spirit of","and/ a spirit","and/ a wind","and/ spirit"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7363B}/[H7363]', 'lemma', 'heb', 'רָחַף', '["râchaph"]', '["[was] hovering","it hovers"]', '["v"]', 'to brood; by implication, to be relaxed flutter, move, shake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4325G}/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["<the>/ water","the/ water","the/ water<s>","the/ waters"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0559}/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["and/ <she> said","and/ I have said","and/ I said","and/ I thought","and/ I will say","and/ did he say?","and/ he had said","and/ he has said","and/ he has spoken","and/ he said","and/ he says","and/ he spoke","and/ he thought","and/ he will say","and/ it has said","and/ it said","and/ it was told","and/ it will say","and/ people said","and/ people will say","and/ she said","and/ she says","and/ she spoke","and/ she will say","and/ someone said","and/ someone says","and/ someone will say","and/ they [fem] said","and/ they had said","and/ they have said","and/ they said","and/ they say","and/ they will say","and/ we said","and/ we will say","and/ you have said","and/ you said","and/ you say","and/ you will say","and/ you will speak"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0216}/[H215]', 'lemma', 'heb', 'אוֹר', '["ʼôwr"]', '["<of> [the] light","<of> [the] lights","[is] a light","[is] light","[the] light","[the] light of","[will be] light","a light","light"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1961}/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["and/ <it> became","and/ I became","and/ I have become","and/ I have been","and/ I was","and/ I will be","and/ I will become","and/ he became","and/ he has become","and/ he has been","and/ he is","and/ he was","and/ he will be","and/ he will become","and/ he will belong","and/ it be[longed]","and/ it be[longs]","and/ it became","and/ it belonged","and/ it belongs","and/ it came","and/ it happened","and/ it has become","and/ it has been","and/ it has belonged","and/ it has happened","and/ it is","and/ it was","and/ it will be","and/ it will be[long]","and/ it will become","and/ it will belong","and/ it will happen","and/ it will occur","and/ people were","and/ she became","and/ she belonged","and/ she was","and/ she will be","and/ she will become","and/ she will belong","and/ there was","and/ they are","and/ they became","and/ they become","and/ they belonged","and/ they have become","and/ they have been","and/ they were","and/ they will be","and/ they will become","and/ they will belong","and/ they will happen","and/ we have become","and/ we were","and/ we will be","and/ we will become","and/ you became","and/ you belonged","and/ you have become","and/ you were","and/ you will be","and/ you will become"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200G}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ I appeared","and/ I considered","and/ I looked","and/ I saw","and/ I saw [it]","and/ I will look","and/ I will see","and/ he appeared","and/ he has seen","and/ he looked","and/ he presented himself","and/ he saw","and/ he saw [it]","and/ he saw [them]","and/ he showed","and/ he will appear","and/ he will present himself","and/ he will see","and/ it appeared","and/ it appears","and/ it saw","and/ it was seen","and/ it will be seen","and/ it will be shown to","and/ it will be visible","and/ it will see","and/ she has seen","and/ she saw","and/ they appeared","and/ they had seen","and/ they looked at one another","and/ they saw","and/ they see","and/ they were visible","and/ they will look","and/ they will see","and/ they will see [it]","and/ you saw","and/ you will look","and/ you will see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0216}/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["<the>/ light","the/ light"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3588A}/[H3588]', 'lemma', 'heb', 'כִּי', '["kîy"]', '["deed","for","if","that","that [if]","thatr"]', '["conj"]', '(by implication) very widely used as a relative conjunction or adverb (as below); often largely modified by other particles annexed and, (forasmuch, inasmuch, where-) as, assured(-ly), but, certainly, doubtless, else, even, except, for, how, (because, in, so, than) that, nevertheless, now, rightly, seeing, since, surely, then, therefore, (al-) though, till, truly, until, when, whether, while, whom, yea, yet.', 'a primitive particle (the full form of the prepositional prefix) indicating causal relations of all kinds, antecedent or consequent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2895}/[H2895]', 'lemma', 'heb', 'טוֹב', '["ṭôwb"]', '["[he is] good","[is] good","[it is] good","[it was] good","good","it has been good","it is good","it was good","it was well","they are good","was well","you did well","you have done well"]', '["v"]', 'to be (transitively, do or make) good (or well) in the widest sense be (do) better, cheer, be (do, seem) good, (make) goodly, × please, (be, do, go, play) well.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0914}/[H914]', 'inflected', 'heb', 'בָּדַל', '["bâdal"]', '["and/ I have separated","and/ he separated","and/ he was separated","and/ it will separate","and/ they separated","and/ they separated themselves","and/ you will separate"]', '["v"]', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0996G}/[H995]', 'lemma', 'heb', 'בֵּין', '["bêyn"]', '["[is] between","[it is] between","[was] between","[were] between","between"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0996G}/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["and/ [is] between","and/ between"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2822}/[H2821]', 'inflected', 'heb', 'חֹשֶׁךְ', '["chôshek"]', '["<the>/ darkness","the/ darkness"]', '["n-m"]', 'the dark; hence (literally) darkness; figuratively, misery, destruction, death, ignorance, sorrow, wickedness dark(-ness), night, obscurity.', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7121H}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ he called","and/ he was called","and/ it has been called","and/ it will be called","and/ people will call","and/ she called","and/ she will call","and/ someone called","and/ someone had called","and/ they called","and/ they will call","and/ you will call"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0216}/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["<into> <the>/ light","<into>/ a light of","<to> the/ light","for the/ light","for/ light","into/ light","to the/ light","to/ light"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["[are] [the] days of","[is] [the] day of","[is] a day of","[the] day","[the] day of","[the] days","[the] days of","[were the] days of","[will be] a day","[will be] a day of","[will be] days","[will] [the] day of","a day","a day of","day","day[s]","days","days of","two days"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2822}/[H2821]', 'inflected', 'heb', 'חֹשֶׁךְ', '["chôshek"]', '["and/ <to> the/ darkness"]', '["n-m"]', 'the dark; hence (literally) darkness; figuratively, misery, destruction, death, ignorance, sorrow, wickedness dark(-ness), night, obscurity.', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121H}/[H7122]', 'lemma', 'heb', 'קָרָא', '["qârâʼ"]', '["<it> will be called","I call","I called","anyone will call","call","did someone call","do you call","he called","he calls","he had called","he has called","he is called","he will call","it had been called","it has been called","it has been named","it is called","it was called","it will be called","it will be named","let it be called","people call","people called","people have called","people will call","she called","she had called","someone called","they call","they called","they have called themselves","they were named","they will be called","will he call","you call","you will be called","you will call"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3915}/[H3883]', 'lemma', 'heb', 'לַיִל', '["layil"]', '["[the] night","[was] a night of","a night","night","night[s]","nights"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6153}/[H6150]', 'lemma', 'heb', 'עֶרֶב', '["ʻereb"]', '["[the] evening","evening"]', '["n-m"]', 'dusk day, even(-ing, tide), night.', 'from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1242}/[H1239]', 'lemma', 'heb', 'בֹּקֶר', '["bôqer"]', '["[is] morning","[the] morning","morning"]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0259}\/[H258]', 'inflected', 'heb', 'אֶחָד', '["ʼechâd"]', '["one"]', '["a"]', 'properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,', 'a numeral from 258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7549}/[H7554]', 'lemma', 'heb', 'רָקִיעַ', '["râqîyaʻ"]', '["[the] firmament of","a firmament","an expanse"]', '["n-m"]', 'properly, an expanse, i.e. the firmament or (apparently) visible arch of the sky firmament.', 'from 7554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8432>', 'inflected', 'heb', 'בתוך', '["ba./Ta.vekh","be./Tokh","be./toKh","be./tokh","ve./tokh"]', '["[are] in/ [the] midst of","[is] in/ [the] middle of","[is] in/ [the] midst of","[is] in/ among","[they were] in/ [the] midst of","[was] in/ [the] middle of","[was] in/ among","[will be] in the/ middle","[will be] in/ [the] middle of","in the/ middle","in/ [the] middle of","in/ [the] midst","in/ [the] midst of","in/ among","in/ between","in/ midst of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1961}/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["and/ be","and/ become","and/ he may be","and/ it has been","and/ it may be","and/ it may become","and/ it was","and/ it will be","and/ let her be","and/ let him be","and/ let it be","and/ let them be","and/ may he be","and/ may it be","and/ may they be","and/ they may be","and/ they may become","and/ you are","and/ you be","so/ I may be","so/ it may be","so/ may he be","so/ may he become","so/ may it be","so/ may it belong","so/ may she be","so/ she may become","so/ they may be","so/ they may become","so/ we may be"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0914}/[H914]', 'lemma', 'heb', 'בָּדַל', '["bâdal"]', '["I have separated","certainly <to separate>","he has set apart","he set apart","he will be separated","he will separate [it]","separate yourselves","separating","they have made a distinction","they have separated themselves","they separated themselves","they will set apart","you will set apart"]', '["v"]', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4325G}/[H4325]', 'lemma', 'heb', 'מַיִם', '["mayim"]', '["<of> [the] water of","[are] waters","[is] [the] water of","[is] water","[the] water","[the] water of","[the] waters","[the] waters of","[was] water","[were] [the] waters of","water","water of","waters","waters of"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4325G}/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["<into>/ water","<to> the/ waters","<to>/ [the] water of","<to>/ [the] waters of","for <the>/ water","for/ [the] water of","to the/ waters","to/ [the] waters of","to/ water of","to/ waters"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6213H}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ I made","and/ I will make","and/ did it produce","and/ he acquired","and/ he appointed","and/ he had made","and/ he has made","and/ he made","and/ he prepared","and/ he will do","and/ he will make","and/ he will observe","and/ it has made","and/ it produced","and/ it will make","and/ it will produce","and/ she prepared","and/ she will make","and/ they appointed","and/ they did","and/ they have made","and/ they made","and/ they observed","and/ they prepared","and/ they prepared [it]","and/ they will make","and/ you have appointed","and/ you have made","and/ you made","and/ you will make","and/ you will observe"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7549}/[H7554]', 'inflected', 'heb', 'רָקִיעַ', '["râqîyaʻ"]', '["the/ expanse","the/ firmament"]', '["n-m"]', 'properly, an expanse, i.e. the firmament or (apparently) visible arch of the sky firmament.', 'from 7554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0834A}/[H834]', 'lemma', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["<of> that","<of> where","<of> which","O [you] who","[I] who","[and] this:","[anyone] whom","[are that] which","[are things] which","[are those] which","[are those] whom","[he heard] this:","[he] who","[he] whom","[is [the] one] who","[is one] which","[is that] which","[is] how","[one] who","[one] whom","[places] where","[that] which","[the one] which","[the one] who","[the one] whom","[the things] which","[they heard] this:","[things] which","[those] which","[those] who","[those] whom","[was [the] one] which","[was [the] one] who","[was] when","[were those] who","[you] who","[you] whom","how","that","this","this:","what","when","where","which","who","whom","why"]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8478G}/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["<from>/ beneath","<from>/ under","[were] <from>/ under","[were] from/ under","from/ below","from/ under"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7549}/[H7554]', 'inflected', 'heb', 'רָקִיעַ', '["râqîyaʻ"]', '["<to> the/ expanse","<to> the/ firmament","to the/ firmament"]', '["n-m"]', 'properly, an expanse, i.e. the firmament or (apparently) visible arch of the sky firmament.', 'from 7554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5921A}/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["<from>/ above","<from>/ on","<from>/ over","[are] <from>/ above","[were] from/ <above>","from/ above","from/ against","from/ at","from/ on","from/ over","from/ with"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3651C}/[H3559]', 'lemma', 'heb', 'כֵּן', '["kên"]', '["-fore","[am] thus","[are] so","[are] thus","[be] so","[is] so","[is] thus","[it is] thus","[was] so","[was] thus","[will be] so","fore","so","thus"]', '["adv"]', 'properly, set upright; hence (figuratively as adjective) just; but usually (as adverb or conjunction) rightly or so (in various applications to manner, time and relation; often with other particles) after that (this, -ward, -wards), as... as, (for-) asmuch as yet, be (for which) cause, following, howbeit, in (the) like (manner, -wise), × the more, right, (even) so, state, straightway, such (thing), surely, there (where) -fore, this, thus, true, well, × you.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8064>', 'opaque', 'heb', 'שָׁמַיִם', '["shâmayim"]', '["<of> [the] heavens","O heaven","O heaven of","O heavens","[are] heavens","[the] heavens","[the] heavens of","heaven","heavens","heavens of"]', '["n-m"]', 'the sky (as aloft; the dual perhaps alluding to the visible arch in which the clouds move, as well as to the higher ether where the celestial bodies revolve) air, × astrologer, heaven(-s).', 'dual of an unused singular שָׁמֶה; from an unused root meaning to be lofty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8145}\/[H8138]', 'inflected', 'heb', 'שֵׁנִי', '["shênîy"]', '["second"]', '["n"]', 'properly, double, i.e. second; also adverbially, again again, either (of them), (an-) other, second (time).', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6960B}/[H6960]', 'lemma', 'heb', 'קָוָה', '["qâvâh"]', '["let them gather","they will wait"]', '["v"]', 'to bind together (perhaps by twisting), i.e. collect; (figuratively) to expect gather (together), look, patiently, tarry, wait (for, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/[H413]', 'lemma', 'heb', 'אֵל', '["ʼêl"]', '["<to>","[am] against","[are] against","[are] to","[be] to","[is] against","[is] to","[is] with","[was] to","[were] to","[were] with","[which are] to","[which] to","[will be] to","against","against [where]","because of","concerning","in","into","may [you] not","on","to","with"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4725}/[H6965]', 'lemma', 'heb', 'מָקוֹם', '["mâqôwm"]', '["[are] a place of","[is the] place","[is the] place of","[is] room","[the] place","[the] place of","[the] places of","[was] a place of","[was] room","a place","a place of","place","room"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0259}/[H258]', 'lemma', 'heb', 'אֶחָד', '["ʼechâd"]', '["<of> one","<of> one of","[is the] one","[is] one","[is] one [daughter]","[is] one [plus]","[was] one","[was] one [person]","[were] one","[whom] one","one","one [bird]","one [city]","one [loaf]","one [man]","one [person]","one [plus]","one [portion]","one [thing]","one [time]","one of","one<s>"]', '["a"]', 'properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,', 'a numeral from 258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7200G}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ I may appear?","and/ I saw","and/ [one who] looks","and/ [when] I may look","and/ he will see","and/ it may appear","and/ let it appear","and/ look","and/ look for","and/ may he see","and/ see","and/ she will see","and/ they may appear","and/ we may see","so/ I may see","so/ he may see","so/ they may see","so/ we may look"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3004}/[H3001]', 'inflected', 'heb', 'יַבָּשָׁה', '["yabbâshâh"]', '["the/ dry ground","the/ dry land"]', '["n-f"]', 'dry ground dry (ground, land).', 'from 3001;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3004}/[H3001]', 'inflected', 'heb', 'יַבָּשָׁה', '["yabbâshâh"]', '["<to> the/ dry ground","into/ dry land"]', '["n-f"]', 'dry ground dry (ground, land).', 'from 3001;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776G>', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["<of> earth","O earth","O land","O land of","[are] a land","[is] a land","[is] a land of","[the] earth","[the] earth of","[the] ground","[the] land","[the] land of","[the] lands of","[was] [the] land of","a land","a land of","earth","land","land of","lands","lands of"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4723C}/[H6960]', 'inflected', 'heb', 'מִקְוֶה', '["miqveh"]', '["and/ <to>/ [the] collection of"]', '["n-pr-m n-m"]', 'something waited for, i.e. confidence (objective or subjective); also a collection, i.e. (of water) a pond, or (of men and horses) a caravan or drove abiding, gathering together, hope, linen yarn, plenty (of water), pool.', 'or מִקְוֵה; (1 Kings 10:28), or מִקְוֵאlemma מִּקְוֵא extra dagesh, corrected to מִקְוֵא; (2 Chronicles 1:16), from 6960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3220G>', 'opaque', 'heb', 'יָם', '["yâm"]', '["<of> [the] sea","<of> [the] sea of","[is] [the] Sea of","[the] Sea of","[the] sea","[the] sea of","[the] seas","[the] west","sea","seas"]', '["n-m"]', 'a sea (as breaking in noisy surf) or large body of water; specifically (with the article), the Mediterranean Sea; sometimes a large river, or an artifical basin; locally, the west, or (rarely) the south sea (× -faring man, (-shore)), south, west (-ern, side, -ward).', 'from an unused root meaning to roar;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1876}/[H1876]', 'lemma', 'heb', 'דָּשָׁא', '["dâshâʼ"]', '["let it sprout"]', '["v"]', 'to sprout bring forth, spring.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1877}/[H1876]', 'lemma', 'heb', 'דֶּשֶׁא', '["desheʼ"]', '["grass","vegetation"]', '["n-m"]', 'a sprout; by analogy, grass (tender) grass, green, (tender) herb.', 'from 1876;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6212>', 'opaque', 'heb', 'עֶשֶׂב', '["ʻeseb"]', '["<the> vegetation of","[is] vegetation","[the] vegetation","[the] vegetation of","[the] vegetation<s> of","grass","plant","plant[s]","vegetation"]', '["n-m"]', 'grass (or any tender shoot) grass, herb.', 'from an unused root meaning to glisten (or be green);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2232}/[H2232]', 'lemma', 'heb', 'זָרַע', '["zâraʻ"]', '["O [those who] sow","[is] sown","[one who] sows","[the] sower","[which] bears seed","he will sow","it is sown","it sowed","it will be sown","let me sow","people have sown","she will bear a child","sow","sown","they have been sown","they sow","we will sow","you have sown","you must sow","you sow","you sowed","you will sow"]', '["v"]', 'to sow; figuratively, to disseminate, plant, fructify bear, conceive seed, set with sow(-er), yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2233G}/[H2232]', 'lemma', 'heb', 'זֶרַע', '["zeraʻ"]', '["[is] seed","[the] seed of","[was] [the] seed of","[was] seed of","seed","seed of"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6086H}/[H6095]', 'lemma', 'heb', 'עֵץ', '["ʻêts"]', '["<the> tree of","[am] a tree","[is] [the] tree of","[is] a tree of","[the] tree","[the] tree of","[the] tree[s] of","[the] trees of","a tree","a tree of","tree","tree of","tree[s]","tree[s] of","trees","trees of","wood","wood<s>","wood<s> of"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6529}/[H6509]', 'lemma', 'heb', 'פְּרִי', '["pᵉrîy"]', '["[is the] fruit of","[the] fruit of","fruit","fruit of"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213H}/[H6213]', 'lemma', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["I had made","I have made","I made","I made [it]","I was made","I will make","I will offer","I will prepare","[am] about to make","[are] doing","[he is] making","[he] made","[he] makes","[is the] maker of","[is] about to do","[is] making","[it was] done","[one who] makes","[one who] works","[people are] making","[that] it has been made","[the] maker of","[they were] done","[was] made","[was] making","[were] made","[were] making","[were] working","[which] he has made","[which] they made","[who] brings about","[who] made","[will be] making","are you making","certainly <to make>","did we make","did you do?","doers of","doing","he appointed","he did","he had done","he had made","he had prepared","he has done","he has made","he made","he makes","he will make","he will provide","it had been made","it has been done","it has done","it has made [it]","it is made","it made","it makes","it was made","it will be done","it will be made","let anyone make","let people make","let us act","let us make","made","make","maker of","makers of","making","observe","people had made","prepare","prepared","producing","she had made","she had prepared","she made","she makes","someone will make","they did","they had done","they had made","they had used","they have done","they have made","they have produced","they made","they should make","they were made","they will do","they will make","to make","we have made","we will make","will I make?","you did","you had made","you have acquired","you have appointed","you have done","you have made","you made","you make","you must do","you must make","you will do","you will make","you will make [them]","you will prepare"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H4327>/H9023', 'inflected', 'heb', 'למינהו', '["le./mi.N/o","le./mi.Ne./hu"]', '["to/ kind/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2233G}/H9023/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["seed/ its"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9033}', 'inflected', 'arc', 'בו', '["Be/h","Ve/h","b/o","be/h","bo/h","bo/v","v/o","vo/v"]', '["<in> <the>/ him","<in> <the>/ it","<in>/ him","<in>/ it","<on>/ him","[are] on <the>/ him","[is] among <the>/ him","[is] in <the>/ him","[is] in <the>/ it","[is] in/ him","[is] in/ it","[is] on <the>/ him","[is] over/ it","[is] with/ it","[was] in <the>/ him","[was] in <the>/ it","[was] in/ him","[was] in/ it","[was] on <the>/ it","[was] on/ it","[were] in <the>/ it","[will be] on <the>/ him","against <the>/ him","against <the>/ it","against/ him","among/ him","among/ it","at/ it","by <the>/ him","by <the>/ it","by/ him","by/ it","for/ himself","for/ it","in <the>/ him","in <the>/ it","in/ him","in/ it","of/ him","on <the>/ him","on <the>/ it","on/ him","on/ it","over <the>/ him","over <the>/ it","over/ it","to/ him","with <the>/ him","with <the>/ it","with/ him","with/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318M}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ <it> brought forth","and/ he brought out","and/ he came out","and/ it came out","and/ it had put forth","and/ they will come out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6086H}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["and/ [is] a tree of","and/ [the] tree of","and/ [the] tree[s] of","and/ tree[s]","and/ tree[s] of","and/ trees of","and/ wood<s> of"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7992}\/[H7969]', 'inflected', 'heb', 'שְׁלִישִׁי', '["shᵉlîyshîy"]', '["third"]', '["a"]', 'third; feminine a third (part); by extension, a third (day, year or time); specifically, a third-story cell) third (part, rank, time), three (years old).', 'ordinal from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3974}/[H215]', 'lemma', 'heb', 'מָאוֹר', '["mâʼôwr"]', '["[the] luminaries of","a luminary","light of","luminaries"]', '["n-m"]', 'properly, a luminous body or luminary, i.e. (abstractly) light (as an element); figuratively, brightness, i.e.cheerfulness; specifically, a chandelier bright, light.', 'or מָאֹר; also (in plural) feminine מְאוֹרָה; or מְאֹרָה; from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7549}/[H7554]', 'inflected', 'heb', 'רָקִיעַ', '["râqîyaʻ"]', '["in/ [the] firmament of"]', '["n-m"]', 'properly, an expanse, i.e. the firmament or (apparently) visible arch of the sky firmament.', 'from 7554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0914}/[H914]', 'inflected', 'heb', 'בָּדַל', '["bâdal"]', '["to/ make a distinction","to/ separate"]', '["v"]', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3117G>', 'inflected', 'heb', 'הימים', '["Hai./yom","hai./Yom","hai./yOm","hai./ya.Mim","hai./ya.Min","hai./yoM"]', '["<the>/ day","<the>/ days","[is] the/ day","the/ day","the/ day of","the/ day[s]","the/ days","this/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3915}/[H3883]', 'inflected', 'heb', 'לַיִל', '["layil"]', '["the/ night","the/ night[s]","the/ nights","this/ night"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0226H}/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["<into>/ a sign","<into>/ a sign of","<into>/ signs","for/ a sign","into/ a sign"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4150G}/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["and/ <into>/ appointed times"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H3117G>', 'inflected', 'heb', 'ולימים', '["u./le./Yom","u./le./ya.Mim"]', '["and/ <into>/ days","and/ to/ [the] day of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8141}/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["and/ [the] year of","and/ [the] years of","and/ a year","and/ year","and/ years","and/ years of"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3974}/[H215]', 'inflected', 'heb', 'מָאוֹר', '["mâʼôwr"]', '["<into>/ luminaries","for the/ light","for/ light","to/ [the] light of"]', '["n-m"]', 'properly, a luminous body or luminary, i.e. (abstractly) light (as an element); figuratively, brightness, i.e.cheerfulness; specifically, a chandelier bright, light.', 'or מָאֹר; also (in plural) feminine מְאוֹרָה; or מְאֹרָה; from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0215}/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["to/ be lighted up","to/ give light","to/ light up"]', '["v"]', 'to be (causative, make) luminous (literally and metaphorically) × break of day, glorious, kindle, (be, en-, give, show) light (-en, -ened), set on fire, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8147}/[H8145]', 'lemma', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["<the> two","[are] [the] two","[are] two [plus]","[is] two","[is] two [plus]","[the] two","[the] two [plus]","[was] two","[was] two [plus]","[were] two","[were] two [plus]","[will be] two","both of","two","two [leaves]","two [people]","two [plus]","two [sons]","two [things]","two [times]","two [wings]","two of","twofold"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3974}/[H215]', 'inflected', 'heb', 'מָאוֹר', '["mâʼôwr"]', '["the/ light","the/ luminaries","the/ luminary"]', '["n-m"]', 'properly, a luminous body or luminary, i.e. (abstractly) light (as an element); figuratively, brightness, i.e.cheerfulness; specifically, a chandelier bright, light.', 'or מָאֹר; also (in plural) feminine מְאוֹרָה; or מְאֹרָה; from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1419A}/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["<the>/ great","<the>/ great [person]","<the>/ large","the/ great","the/ great [people]","the/ great [things]"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4475}/[H4474]', 'inflected', 'heb', 'מֶמְשָׁלָה', '["memshâlâh"]', '["for/ [the] dominion of","for/ dominion","for/ dominion<s>"]', '["n-f"]', 'rule; also (concretely in plural) a realm or a ruler dominion, government, power, to rule.', 'feminine of 4474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6996B}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["<the>/ small","the/ little","the/ small"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3556}/[H3522]', 'inflected', 'heb', 'כּוֹכָב', '["kôwkâb"]', '["the/ stars"]', '["n-m"]', 'a star (as round or as shining); figuratively, a prince star(-gazer).', 'probably from the same as 3522 (in the sense of rolling) or 3554 (in the sense of blazing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414H}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I appointed","and/ I gave","and/ I put","and/ I will give","and/ I will make","and/ I will place [it]","and/ I will put","and/ I will set","and/ he appointed","and/ he assigned","and/ he gave","and/ he gave [them]","and/ he put","and/ he put [it]","and/ he put [them]","and/ he put out","and/ he set","and/ he set [it]","and/ he was put","and/ he will give [it]","and/ he will make","and/ he will put","and/ he will put [it]","and/ he will put [them]","and/ it set","and/ people put","and/ she put","and/ someone assigned","and/ they appointed","and/ they gave","and/ they made","and/ they put","and/ they set","and/ they will make","and/ they will put","and/ they will put [it]","and/ they will put [them]","and/ they will set","and/ they will set up","and/ you will make","and/ you will put","and/ you will put [it]","and/ you will put [them]","and/ you will set","and/ you will set up"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0853}/H9038/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["<obj.>/ them","<obj.>/ themselves"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4910}/[H4910]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["and/ to/ rule"]', '["v"]', 'to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3117G>', 'inflected', 'heb', 'בימים', '["Ba/i.yom","Bi./mei","ba/i.Yom","ba/i.yOm","ba/i.ya.Mim","ba/i.yom","be./Yom","be./yOm","be./ya.Mim","be./yom","bi./Mei","va/i.Yom","va/i.yOm","va/i.ya.Mim","va/i.yom","ve./yom","vi./Mei"]', '["[is] on the/ day","[were] in/ [the] days of","[will be] on the/ day","among/ [the] days of","in <the>/ day","in the/ day","in the/ days","in/ [the] day of","in/ [the] days of","in/ a day","in/ a day of","in/ days","in/ days of","on the/ day","on/ [the] day","on/ [the] day of","on/ a day","on/ a day of","on/ day","over the/ day","over/ [the] day of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3915}/[H3883]', 'inflected', 'heb', 'לַיִל', '["layil"]', '["and/ in <the>/ night","and/ in the/ night","and/ over the/ night"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0914}/[H914]', 'inflected', 'heb', 'בָּדַל', '["bâdal"]', '["and/ to/ separate"]', '["v"]', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7243}\/[H7251]', 'inflected', 'heb', 'רְבִיעִי', '["rᵉbîyʻîy"]', '["fourth"]', '["a"]', 'fourth; also (fractionally) a fourth foursquare, fourth (part).', 'or רְבִעִי; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8317}/[H8317]', 'lemma', 'heb', 'שָׁרַץ', '["shârats"]', '["it swarmed","it swarms","let them swarm","swarm","they swarmed"]', '["v"]', 'to wriggle, i.e. (by implication) swarm or abound breed (bring forth, increase) abundantly (in abundance), creep, move.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8318}/[H8317]', 'lemma', 'heb', 'שֶׁרֶץ', '["sherets"]', '["<the> swarming thing of","a swarming thing","swarming thing","swarming thing[s]"]', '["n-m"]', 'a swarm, i.e. active mass of minute animals creep(-ing thing), move(-ing creature).', 'from 8317;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315K}/[H5314]', 'lemma', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["a creature","creature","creature[s]"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416A}/[H2421]', 'lemma', 'heb', 'חַי', '["chay"]', '["[am] alive","[am] living","[are] alive","[by] [the] life","[by] [the] life of","[is] alive","[is] living","[the] living","[was] alive","[were] alive","[will be] alive","alive","animal","he lives","life","living","living [people]","living [person]","living [thing]","raw"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5775}/[H5774]', 'inflected', 'heb', 'עוֹף', '["ʻôwph"]', '["and/ [the] bird[s] of","and/ bird[s]"]', '["n-m"]', 'a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5774A}/[H5775]', 'lemma', 'heb', 'עוּף', '["ʻûwph"]', '["I want to fly away","[which] it will fly","flying","he flew","he will fly away","it flies","it flies away","it will fly away","let it fly","they fly","to fly"]', '["v n-f"]', 'to fly; also (by implication of dimness) to faint (from the darkness of swooning) brandish, be (wax) faint, flee away, fly (away), × set, shine forth, weary.', 'a primitive root; to cover (with wings or obscurity); hence (as denominative from 5775)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1254A}/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["and/ he created","and/ he will create","and/ you will cut down"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8577N}/[H8565]', 'inflected', 'heb', 'תַּנִּין', '["tannîyn"]', '["the/ sea monster","the/ sea monsters"]', '["n-m"]', 'a marine or land monster, i.e. sea-serpent or jackal dragon, sea-monster, serpent, whale.', 'or תַּנִּים; (Ezekiel 29:3), intensive from the same as 8565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3605}/[H3634]', 'lemma', 'heb', 'כֹּל', '["kôl"]', '["<of> [whom] all","O all","O every","[are] all","[is] all","[is] any","[is] anything","[is] every","[was] every","[were] all","all","all of","any","any of","anything","every","every [one]","everyone","everything","like"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2416A}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["<the>/ life","<the>/ living","<the>/ living [thing]","[is] the/ living one","the/ living","the/ living [ones]","the/ living one"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7430}/[H7430]', 'inflected', 'heb', 'רָמַשׂ', '["râmas"]', '["which/ creeps","which/ crept","which/ moves"]', '["v"]', 'properly, to glide swiftly, i.e. to crawl or move with short steps; by analogy to swarm creep, move.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H4327>/H9028', 'inflected', 'heb', 'למינהם', '["le./mi.ne./Hem"]', '["to/ kind/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5775}/[H5774]', 'lemma', 'heb', 'עוֹף', '["ʻôwph"]', '["<the> bird of","[the] bird[s] of","a bird","bird of","bird[s]","bird[s] of","insect"]', '["n-m"]', 'a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3671}/[H3670]', 'lemma', 'heb', 'כָּנָף', '["kânâph"]', '["<of> wings","[the] corners of","[the] skirt","[the] skirt of","[the] wing of","[the] wings of","a wing","a wing of","of wings","wing","wings","wings of"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1288}/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["and/ I blessed","and/ I will bless","and/ he blessed","and/ he has blessed","and/ he knelt down","and/ he made kneel","and/ he will bless","and/ he will bless himself","and/ they blessed","and/ they have blessed","and/ they will be blessed","and/ they will bless themselves","and/ you will bless"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0559}/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["<to>/ say","<to>/ saying","to/ say","to/ speak"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6509}/[H6509]', 'lemma', 'heb', 'פָּרָה', '["pârâh"]', '["a fruit-bearer","be fruitful","bearing fruit","fruit-bearing","fruitful","it will bear fruit","they were fruitful","you will be fruitful"]', '["v"]', 'to bear fruit (literally or figuratively) bear, bring forth (fruit), (be, cause to be, make) fruitful, grow, increase.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7235A}/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["and/ I had reared","and/ [may be] many","and/ [who] had many","and/ certainly <to increase>","and/ great","and/ he multiplies","and/ multiply","and/ you increase","so/ I may increase","so/ it may increase","so/ they may increase","so/ you may increase"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4390}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["and/ fill","and/ may it be filled","so/ <it> may be filled","so/ may he fill?","so/ they may be filled"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3220G>', 'inflected', 'heb', 'בימים', '["ba/i.Yam","ba/i.ya.Mim","be./yam","va/i.Yam","ve./yam"]', '["<in>/ [the] sea of","[are] in the/ sea","[is] in the/ sea","[was] in the/ sea","at the/ sea","at/ [the] sea of","in the/ sea","in the/ seas","in/ [the] sea of","on the/ sea"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5775}/[H5774]', 'inflected', 'heb', 'עוֹף', '["ʻôwph"]', '["and/ the/ bird[s]"]', '["n-m"]', 'a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7235A}/[H7235]', 'lemma', 'heb', 'רָבָה', '["râbâh"]', '["I multiplied","I will increase","[are] many","[are] multiplying","[is] increasing","[is] much","[one which] multiplies","[one who] increases","[surely] a multitude","[surely] many","[surely] much","[were] multiplying","[will be] great","certainly <to increase>","great","greatly","he has increased","he has multiplied","he increased","he increases","he is great","he multiplied","he multiplies","he will increase","he will make much","he will multiply","increase","it has been great","it increased","it increases","it should increase","it will be [too] great","it will be great","it will be numerous of","it will increase","let it multiply","make great","make numerous","many","may you increase","much","multiply","she had increased","she reared","they grow","they had increased","they had many","they have increased","they have multiplied","they increase","they increased","they may increase","they multiplied","they were numerous","they will increase","to be many","to increase","to make many","we have increased","you have increased","you have made great","you have multiplied","you increased","you multiply","you will increase","you will make great","you will multiply"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0776G>', 'inflected', 'heb', 'בארצות', '["Ba./''a.retz","ba./''A.retz","ba./''a.Retz","ba./''a.ra.Tzot","be./''E.retz","be./''ar.Tzot","be./''e.Retz","be./''e.retz","va./''A.retz","va./''a.Retz","va./''a.ra.Tzot","ve./''e.retz"]', '["<in> the/ earth","<in>/ [the] land of","[are] in the/ land","[are] in/ [the] land of","[are] on the/ earth","[is] in the/ land","[is] in/ [the] land of","[is] on the/ earth","[is] on/ [the] land of","[was] in the/ land","[was] in/ [the] land of","[was] on the/ ground","[were] in/ [the] land of","[will be] in the/ land","[will be] in/ [the] land of","among the/ lands","in <the>/ land","in the/ ground","in the/ land","in the/ lands","in/ [the] earth","in/ [the] earth of","in/ [the] land of","in/ [the] lands of","in/ a land","in/ a land of","in/ lands","on the/ earth","on the/ land","on/ lands","over the/ earth","over the/ land"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2549}\/[H2568]', 'inflected', 'heb', 'חֲמִישִׁי', '["chămîyshîy"]', '["fifth"]', '["a"]', 'fifth; also a fifth fifth (part).', 'or חֲמִשִּׁי; ordinal from 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318M}/[H3318]', 'lemma', 'heb', 'יָצָא', '["yâtsâʼ"]', '["I came forth","I came out","[which] it brings forth","[who] came out of","[will be] abortion","did I come forth","he came out","he went out","he will come forth","he will come out","it brings forth","it came forth","it comes forth","it will bring forth","let it produce","someone will go out","they came forth","they will come out","you came forth"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0776H>', 'inflected', 'heb', 'הארץ', '["Ha./''a.retz","ha./''A.retz"]', '["the/ earth","the/ ground","the/ land"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H4327>/H9024', 'inflected', 'heb', 'למינה', '["le./mi.Na/h"]', '["to/ kind/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0929>', 'opaque', 'heb', 'בְּהֵמָה', '["bᵉhêmâh"]', '["<the> animal of","[are] animal[s]","[the] animal[s] of","[the] animals","[the] animals of","[the] livestock of","an animal","animal","animal[s]","animals","cattle","livestock"]', '["n-f"]', 'properly, a dumb beast; especially any large quadruped or animal (often collective) beast, cattle.', 'from an unused root (probably meaning to be mute);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7431}/[H7430]', 'inflected', 'heb', 'רֶמֶשׂ', '["remes"]', '["and/ [the] creeping thing[s] of","and/ creeping thing[s]"]', '["n-m"]', 'a reptile or any other rapidly moving animal that creepeth, creeping (moving) thing.', 'from 7430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2416C}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["and/ [the] animal of","and/ [the] animal[s] of","and/ [the] life of","and/ animal[s]","and/ animal[s] of"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776H>', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["O earth","[the] earth","[the] ground","[the] land","ground"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416C}/[H2421]', 'lemma', 'heb', 'חַי', '["chay"]', '["<the> animal of","[the] animal of","[the] animal[s] of","[the] life of","an animal","animal","animal of","animal[s]","living creature of","living creatures"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0929>', 'inflected', 'heb', 'הבהמה', '["ha./be.he.Mah"]', '["<the>/ animal","<the>/ animal[s]","<the>/ livestock","[is] the/ animal","the/ animal","the/ animal[s]","the/ cattle","the/ livestock"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7431}/[H7430]', 'lemma', 'heb', 'רֶמֶשׂ', '["remes"]', '["<the> creeping thing of","creeping thing","creeping thing[s]","moving thing[s]"]', '["n-m"]', 'a reptile or any other rapidly moving animal that creepeth, creeping (moving) thing.', 'from 7430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0127G}/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["<of> the/ ground","the/ earth","the/ ground","the/ land"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0120G}/[H119]', 'lemma', 'heb', 'אָדָם', '["ʼâdâm"]', '["<of> a person","O humankind","[are] a human being","[is] a man","[is] a person","[is] anyone","[is] humankind","[was] a person","a human","a human being","a man","a person","a person of","anyone","everyone","human being","human[s]","humankind","humankind [is]","man","person","person[s]","someone"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6754>/H9025', 'inflected', 'heb', 'בצלמנו', '["be./tzal.Me./nu"]', '["in/ image/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1823}/H9025/[H1819]', 'inflected', 'heb', 'דְּמוּת', '["dᵉmûwth"]', '["according to/ likeness/ our"]', '["n-f"]', 'resemblance; concretely, model, shape; adverbially, like fashion, like (-ness, as), manner, similitude.', 'from 1819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7287A}/[H7287]', 'inflected', 'heb', 'רָדָה', '["râdâh"]', '["and/ he will rule","and/ may he rule","and/ rule","and/ they may rule"]', '["v"]', 'to tread down, i.e. subjugate; specifically, to crumble off (come to, make to) have dominion, prevail against, reign, (bear, make to) rule,(-r, over), take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1710}/[H1709]', 'inflected', 'heb', 'דָּגָה', '["dâgâh"]', '["over/ [the] fish of"]', '["n-f"]', 'fish.', 'feminine of 1709, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3220G>', 'inflected', 'heb', 'הימים', '["Hai./yom","hai./Yam","hai./ya.Mim"]', '["<of> the/ sea","O/ sea","[is] the/ sea","the/ sea","the/ seas"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5775}/[H5774]', 'inflected', 'heb', 'עוֹף', '["ʻôwph"]', '["and/ among/ [the] bird[s] of","and/ by <the>/ bird[s]","and/ over/ [the] bird[s] of"]', '["n-m"]', 'a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H0929>', 'inflected', 'heb', 'ובבהמה', '["u./va./be.he.Mah","u./vi/v.he.Mah"]', '["and/ among <the>/ animal[s]","and/ among the/ livestock","and/ on the/ livestock","and/ over the/ livestock","and/ with <the>/ cattle","and/ with/ cattle"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3605}/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["and/ <in>/ all","and/ [were] in/ every","and/ [will be] in/ all","and/ [will be] on/ all","and/ among/ all","and/ among/ every","and/ by/ all","and/ for/ all","and/ for/ every","and/ in/ all","and/ in/ any","and/ in/ every","and/ on/ all","and/ on/ every","and/ over/ all","and/ over/ every","and/ to/ all","and/ with/ all"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7431}/[H7430]', 'inflected', 'heb', 'רֶמֶשׂ', '["remes"]', '["<the>/ creeping thing","the/ creeping thing[s]"]', '["n-m"]', 'a reptile or any other rapidly moving animal that creepeth, creeping (moving) thing.', 'from 7430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0120G}/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["<the>/ everyone","<the>/ human","<the>/ humankind","<the>/ man","<the>/ people","<the>/ person","[is] the/ person","[was] <the>/ humankind","[who was] the/ man","the/ humankind","the/ people","the/ person"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6754>/H9023', 'inflected', 'heb', 'בצלמו', '["be./tzal.M/o"]', '["in/ own image/ his"]', NULL, NULL, NULL);
