INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3533}/H9034/[H3533]', 'inflected', 'heb', 'כָּבַשׁ', '["kâbash"]', '["and/ subdue/ it"]', '["v"]', 'to tread down; hence, negatively, to disregard; positively, to conquer, subjugate, violate bring into bondage, force, keep under, subdue, bring into subjection.', 'a primitive root;');
