INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947I}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ he took","and/ they took"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0802H}/[H376]', 'lemma', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["O wife of","O wives of","[am] a woman","[are] [the] wife of","[is] [the] wife of","[the] wife of","[the] wives of","a wife","a wife of","a woman","wife","wives","women"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
