INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4735}/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["and/ [the] livestock of","and/ livestock","and/ livestock of"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3106}/[H2986]', 'lemma', 'heb', 'יוּבַל', '["Yûwbal"]', '["[was] Jubal"]', '["n-pr-m"]', 'Jubal, an antediluvian Jubal.', 'from 2986; stream;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8610}/[H8610]', 'lemma', 'heb', 'תָּפַשׂ', '["tâphas"]', '["O occupant of","[is] sheathed","[those who] wield","[those] skilled of","[who] wield","certainly <to capture>","he caught","he seized","he will seize","it has been captured","it was caught","it will be seized","player of","seize","she was caught","they are caught","they captured","they have been seized","to capture","wielders of","you have taken hold of","you were caught","you will be captured","you will grasp"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3658>', 'opaque', 'heb', 'כִּנּוֹר', '["kinnôwr"]', '["[the] harp","a harp","harp"]', '["n-m"]', 'a harp harp.', 'from a unused root meaning to twang;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5748}/[H5689]', 'inflected', 'heb', 'עוּגָב', '["ʻûwgâb"]', '["and/ flute"]', '["n-m"]', 'a reed-instrument of music organ.', 'or עֻגָּב; from 5689 in the original sense of breathing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6741}/[H6738]', 'inflected', 'heb', 'צִלָּה', '["Tsillâh"]', '["and/ Zillah"]', '["n-pr-f"]', 'Tsillah, an antediluvian woman Zillah.', 'feminine of 6738;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8423}/[H2986]', 'lemma', 'heb', 'תּוּבַל קַיִן', '["Tûwbal Qayin"]', '["Cain","Tubal-"]', '["n-pr-m"]', 'Tubal-Kajin, an antidiluvian patriarch Tubal-cain.', 'apparently from 2986 (compare 2981) and 7014; offspring of Cain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3913}/[H3913]', 'lemma', 'heb', 'לָטַשׁ', '["lâṭash"]', '["a sharpener of","he sharpens","he will sharpen","sharpened"]', '["v"]', 'properly, to hammer out (an edge), i.e. to sharpen instructer, sharp(-en), whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2790A}/[H2790]', 'lemma', 'heb', 'חָרַשׁ', '["chârash"]', '["[he is] devising","[is] engraved","[the] plowman","[was] plotting","[was] plowing","[which] devises","a worker","devisers of","does anyone plow","does he plow","he plows","it will be plowed","it will plow","plowers of","plowing","plowmen","they have plowed","worker of","you devise","you had plowed","you have plowed","you will plow"]', '["v"]', 'to scratch, i.e. (by implication) to engrave, plough; hence (from the use of tools) to fabricate (of any material); figuratively, to devise (in a bad sense); hence (from the idea of secrecy) to be silent, to let alone; hence (by implication) to be deaf (as an accompaniment of dumbness) × altogether, cease, conceal, be deaf, devise, ear, graven, imagine, leave off speaking, hold peace, plow(-er, man), be quiet, rest, practise secretly, keep silence, be silent, speak not a word, be still, hold tongue, worker.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5178A}/[H5154]', 'lemma', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["[are] copper","[was] bronze","[were] bronze","[will be] bronze","bronze","copper","of bronze"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1270}/[H1269]', 'inflected', 'heb', 'בַּרְזֶל', '["barzel"]', '["and/ iron"]', '["n-m"]', 'iron (as cutting); by extension, an iron implement (ax) head, iron.', 'perhaps from the root of 1269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0269}/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["and/ [are] [the] sister of","and/ [the] sister of","and/ [was] [the] sister of"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5279G}/[H5277]', 'lemma', 'heb', 'נַעֲמָה', '["Naʻămâh"]', '["Naamah"]', '["n-pr-f n-pr-loc"]', 'Naamah, the name of an antediluvian woman, of an Ammonitess, and of a place in Palestine Naamah.', 'feminine of 5277; pleasantness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0802H}/H9023/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ wife/ his","of/ wife/ his","to/ wife/ his","to/ wives/ his"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963A>/H9020', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["voice/ my"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0238}/[H241]', 'lemma', 'heb', 'אָזַן', '["ʼâzan"]', '["I gave ear","[is] giving ear","give ear","give ear to","he gave ear","he gave ear to","people have given ear","they gave ear","they give ear","will he give ear to"]', '["v"]', 'to broaden out the ear (with the hand), i.e. (by implication) to listen give (perceive by the) ear, hear(-ken). See 239.', 'a primitive root; probably to expand; but used only as a denominative from 241;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0565A}/H9020/[H561]', 'inflected', 'heb', 'אִמְרָה', '["ʼimrâh"]', '["speech/ my","utterance/ my"]', '["n-f"]', 'commandment, speech, word.', 'or אֶמְרָה; feminine of 561, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6482}/H9020/[H6481]', 'inflected', 'heb', 'פֶּצַע', '["petsaʻ"]', '["for/ bruise/ my"]', '["n-m"]', 'a wound wound(-ing).', 'from 6481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3206}/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["and/ a child of","and/ a young man","and/ children","and/ children of"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2250}/H9020/[H2266]', 'inflected', 'heb', 'חַבּוּרָה', '["chabbûwrâh"]', '["for/ wound/ my"]', '["n-f"]', 'properly, bound (with stripes), i.e. a weal (or black-and-blue mark itself) blueness, bruise, hurt, stripe, wound.', 'or חַבֻּרָה; or חֲבֻרָה; from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3929G>', 'inflected', 'heb', 'ולמך', '["ve./Le.mekh"]', '["and/ Lamech"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7657}/[H7651]', 'lemma', 'heb', 'שִׁבְעִים', '["shibʻîym"]', '["[are] seventy","[was] seventy","[were] seventy","seventy"]', '["n"]', 'seventy seventy, threescore and ten ( -teen).', 'multiple of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7651}/[H7650]', 'inflected', 'heb', 'שֶׁבַע', '["shebaʻ"]', '["and/ [are] seven","and/ [the] seven","and/ seven","and/ seven-"]', '["n"]', 'seven (as the sacred full one); also (adverbially) seven times; by implication, a week; by extension, an indefinite number ( by) seven(-fold),-s, (-teen, -teenth), -th, times). Compare 7658.', 'or (masculine) (שִׁבְעָה); from 7650; a primitive cardinal number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0121G}/[H120]', 'lemma', 'heb', 'אָדָם', '["ʼÂdâm"]', '["Adam"]', '["n-pr-m"]', 'Adam the name of the first man, also of a place in Palestine Adam.', 'the same as 120;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5750}/[H5749]', 'lemma', 'heb', 'עוֹד', '["ʻôwd"]', '["[am] yet","[be] again","[is] still more","[is] yet","[it is] still","again","more","still","yet"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8352}/[H7896]', 'lemma', 'heb', 'שֵׁת', '["Shêth"]', '["Seth","Sheth"]', '["n-pr-m"]', 'Sheth, third son of Adam Seth, Sheth.', 'from 7896; put, i.e. substituted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896I}/[H7896]', 'lemma', 'heb', 'שִׁית', '["shîyth"]', '["he has appointed","someone will fix","you will set"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2233H}/[H2232]', 'lemma', 'heb', 'זֶרַע', '["zeraʻ"]', '["O offspring of","[are] offspring","[the] offspring of","[will be] [the] offspring of","[will be] offspring of","offspring","offspring of","seed","spring","spring of"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0312}/[H309]', 'lemma', 'heb', 'אַחֵר', '["ʼachêr"]', '["[is] another","[the] other","[those who] another [god]","another","another [person]","another [woman]","other","others"]', '["a"]', 'properly, hinder; generally, next, other, etc. (an-) other man, following, next, strange.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478H}/[H8430]', 'lemma', 'heb', 'תַּחַת', '["tachath"]', '["[who] in place of","for","in place of","under"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2026}/H9033/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["he killed/ him","it slays/ him","she killed/ him","you will kill/ him"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8352}/[H7896]', 'inflected', 'heb', 'שֵׁת', '["Shêth"]', '["and/ to/ Seth"]', '["n-pr-m"]', 'Sheth, third son of Adam Seth, Sheth.', 'from 7896; put, i.e. substituted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0583}/[H582]', 'lemma', 'heb', 'אֱנוֹשׁ', '["ʼĔnôwsh"]', '["Enosh"]', '["n-pr-m"]', 'Enosh, a son of Seth Enos.', 'the same as 582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0227A}/[H227]', 'lemma', 'heb', 'אָז', '["ʼâz"]', '["then"]', '["adv"]', 'at that time or place; also as a conjunction, therefore beginning, for, from, hitherto, now, of old, once, since, then, at which time, yet.', 'a demonstrative adverb;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2490C}/[H2470]', 'lemma', 'heb', 'חָלַל', '["châlal"]', '["<it> began","I have begun","I will begin","[am] beginning","[when] it began","[when] they began","begin","beginning","did I begin?","he began","he will begin","it began","it had begun","it has begun","it was begun","they began","they had begun","you have begun","you will begin"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7121G}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ call","to/ call out","to/ summon"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8034}/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["<in>/ [the] name of","[is] in/ [the] name of","by/ [the] name of","by/ name","by/ names","in/ [the] name of","on/ [the] name of","with/ [the] name of"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3068G}\/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["O Yahweh","Yahweh","[am] Yahweh","[is] Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2088}/[H2088]', 'lemma', 'heb', 'זֶה', '["zeh"]', '["<of> which","[is] this","[was] this","this","this [man]","this [one]","this one","what","which","who"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5612H}/[H9]', 'lemma', 'heb', 'סֵפֶר', '["çêpher"]', '["[is] [the] record of","[the] book","[the] book of","[the] document of","[the] scroll of","[the] writing","a book","a document","a document of","a scroll","books","writing"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1823}/[H1819]', 'inflected', 'heb', 'דְּמוּת', '["dᵉmûwth"]', '["in/ [the] likeness of"]', '["n-f"]', 'resemblance; concretely, model, shape; adverbially, like fashion, like (-ness, as), manner, similitude.', 'from 1819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1254A}/H9038/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["he created/ them","you created/ them"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8034}/H9028/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["[are] names/ their","name/ their","names/ their"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1254A}/H9048\/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["were created/ they"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7970}/[H7969]', 'lemma', 'heb', 'שְׁלוֹשִׁים', '["shᵉlôwshîym"]', '["[are] thirty","[was] thirty","[were] thirty","[will be] thirty","thirty"]', '["n-m"]', 'thirty; or (ordinal) thirtieth thirty, thirtieth. Compare 7991.', 'or שְׁלֹשִׁים; multiple of 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3967}/[H3967]', 'inflected', 'heb', 'מֵאָה', '["mêʼâh"]', '["and/ [the] hundred of","and/ a hundred","and/ one hundred","and/ two hundred","and/ two hundred [cubits]","and/ two hundred [shekels]"]', '["n-f"]', 'a hundred; also as a multiplicative and a fraction hundred((-fold), -th), sixscore.', 'or מֵאיָה; properly, a primitive numeral');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8141}/[H8138]', 'lemma', 'heb', 'שָׁנֶה', '["shâneh"]', '["[are] [the] years of","[the] year","[the] year of","[the] years","[the] years of","[was] [the] year","[was] year","a year","a year of","two years","year","year[s]","years","years of"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1823}/H9023/[H1819]', 'inflected', 'heb', 'דְּמוּת', '["dᵉmûwth"]', '["in/ own likeness/ his"]', '["n-f"]', 'resemblance; concretely, model, shape; adverbially, like fashion, like (-ness, as), manner, similitude.', 'from 1819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H6754>/H9023', 'inflected', 'heb', 'כצלמו', '["ke./tzal.M/o"]', '["according to/ image/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310A}/[H309]', 'lemma', 'heb', 'אַחַר', '["ʼachar"]', '["[is] after","[is] behind","[the] back<s> of","[was] after","[was] behind","[were] behind","after","behind"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3205}/H9043/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["being born/ he","fathered/ he"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8083}/[H8082]', 'lemma', 'heb', 'שְׁמֹנֶה', '["shᵉmôneh"]', '["[was] eight","[was] eight-","[will be] eight","[will be] eight-","eight","eight [sons]","eight of","eight-"]', '["n"]', 'a cardinal number, eight (as if a surplus above the ''perfect'' seven); also (as ordinal) eighth eight(-een, -eenth), eighth.', 'or שְׁמוֹנֶה; feminine שְׁמֹנָה; or שְׁמוֹנָה; apparently from 8082 through the idea of plumpness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3967}/[H3967]', 'lemma', 'heb', 'מֵאָה', '["mêʼâh"]', '["<the> hundred<s>","[the] one hundred","[was] a hundred","[was] one hundred","[were] one hundred","[were] two hundred","[will be] one hundred","a hundred","a hundred [times]","hundred [cubits]","hundred<s>","hundreds","one hundred","one hundred [children]","two hundred"]', '["n-f"]', 'a hundred; also as a multiplicative and a fraction hundred((-fold), -th), sixscore.', 'or מֵאיָה; properly, a primitive numeral');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1323G}/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ [the] daughter of","and/ [the] daughters of","and/ [was] [the] daughter of","and/ a daughter","and/ a daughter of","and/ daughters","and/ daughters of"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2421}/[H2331]', 'lemma', 'heb', 'חָיָה', '["châyâh"]', '["<he> will live","I preserved alive","I will live","I will preserve [them] alive","[are] preserving alive","[who] he will live","certainly <live>","certainly <to live>","do they live","he had restored to life","he has let live","he has preserved alive","he let live","he lived","he lives","he preserves alive","he restored","he restored to life","he will let live","he will live","he will preserve alive","it preserves alive","it will live","let him live","let it live","let them live","live","may he live","may it live","people live","preserve alive","she will live","they had preserved alive","they lived","they will cause to grow","they will let live","they will live","we will live","will he live","will we live","will you preserve alive?","you had let live","you may live","you will let live","you will live"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8672}/[H8159]', 'lemma', 'heb', 'תֵּשַׁע', '["têshaʻ"]', '["[was] nine","[were] nine","nine","nine-"]', '["n"]', 'nine or (ordinal) ninth nine ( -teen, -teenth, -th).', 'or (masculine) תִּשְׁעָה; perhaps from 8159 through the idea of a turn to the next or full number ten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7970}/[H7969]', 'inflected', 'heb', 'שְׁלוֹשִׁים', '["shᵉlôwshîym"]', '["and/ [was] thirty","and/ [was] thirty [cubits]","and/ [will be] thirty","and/ thirty"]', '["n-m"]', 'thirty; or (ordinal) thirtieth thirty, thirtieth. Compare 7991.', 'or שְׁלֹשִׁים; multiple of 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4191}\/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ he died","and/ he will die","and/ they will die"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2568}/[H2568]', 'lemma', 'heb', 'חָמֵשׁ', '["châmêsh"]', '["[the] five","[was] five","[were] fif-","[were] five","[will be] five","fif-","five","five [bars]","five of"]', '["n"]', 'five fif(-teen), fifth, five (× apiece).', 'masculine חֲמִשָּׁה; a primitive numeral;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7651}/[H7650]', 'lemma', 'heb', 'שֶׁבַע', '["shebaʻ"]', '["[are] seven","[the] seven","[was] seven","[were] seven","seven","seven [children]","seven [times]","seven of","seven-","sevenfold"]', '["n"]', 'seven (as the sacred full one); also (adverbially) seven times; by implication, a week; by extension, an indefinite number ( by) seven(-fold),-s, (-teen, -teenth), -th, times). Compare 7658.', 'or (masculine) (שִׁבְעָה); from 7650; a primitive cardinal number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8083}/[H8082]', 'inflected', 'heb', 'שְׁמֹנֶה', '["shᵉmôneh"]', '["and/ [was] eight","and/ eight","and/ eight-"]', '["n"]', 'a cardinal number, eight (as if a surplus above the ''perfect'' seven); also (as ordinal) eighth eight(-een, -eenth), eighth.', 'or שְׁמוֹנֶה; feminine שְׁמֹנָה; or שְׁמוֹנָה; apparently from 8082 through the idea of plumpness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6240}/[H6235]', 'lemma', 'heb', 'עָשָׂר', '["ʻâsâr"]', '["teen","teen [cubits]","teenth","ten","ten [cubits]"]', '["n"]', 'ten (only in combination), i.e. -teen; also (ordinal) -teenth (eigh-, fif-, four-, nine-, seven-, six-, thir-) teen(-th), + eleven(-th), + sixscore thousand, + twelve(-th).', 'for 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8672}/[H8159]', 'inflected', 'heb', 'תֵּשַׁע', '["têshaʻ"]', '["and/ nine"]', '["n"]', 'nine or (ordinal) ninth nine ( -teen, -teenth, -th).', 'or (masculine) תִּשְׁעָה; perhaps from 8159 through the idea of a turn to the next or full number ten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8673}/[H8672]', 'lemma', 'heb', 'תִּשְׁעִים', '["tishʻîym"]', '["[was] ninety","ninety"]', '["n"]', 'ninety ninety.', 'multiple from 8672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7018}/[H7064]', 'lemma', 'heb', 'קֵינָן', '["Qêynân"]', '["Kenan"]', '["n-pr-m"]', 'Kenan, an antediluvian Cainan, Kenan.', 'from the same as 7064; fixed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4111G}/[H4110]', 'lemma', 'heb', 'מַהֲלַלְאֵל', '["Mahălalʼêl"]', '["Mahalalel"]', '["n-pr-m"]', 'Mahalalel, the name of an antediluvian patriarch and of an Israelite Mahalaleel.', 'from 4110 and 410; praise of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0705}/[H702]', 'lemma', 'heb', 'אַרְבָּעִים', '["ʼarbâʻîym"]', '["[the] forty","[was] forty [cubits]","[were] forty","[will be] forty","forty","forty [times]"]', '["n"]', 'forty forty.', 'multiple of 702;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6235}/[H6237]', 'lemma', 'heb', 'עֶשֶׂר', '["ʻeser"]', '["[is] ten","[the] ten","[was] ten","[was] ten of","[were] ten","[will be] ten","ten","tens"]', '["n"]', 'ten (as an accumulation to the extent of the digits) ten, (fif-, seven-) teen.', 'masculine of term עֲשָׂרָה; from 6237;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8346}/[H8337]', 'inflected', 'heb', 'שִׁשִּׁים', '["shishshîym"]', '["and/ sixty"]', '["n"]', 'sixty sixty, three score.', 'multiple of 8337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3382G}/[H3381]', 'lemma', 'heb', 'יֶרֶד', '["Yered"]', '["Jared"]', '["n-pr-m"]', 'Jered, the name of an antediluvian, and of an Israelite Jared.', 'from 3381; a descent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8673}/[H8672]', 'inflected', 'heb', 'תִּשְׁעִים', '["tishʻîym"]', '["and/ ninety"]', '["n"]', 'ninety ninety.', 'multiple from 8672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2585H}/[H2596]', 'lemma', 'heb', 'חֲנוֹךְ', '["Chănôwk"]', '["Enoch"]', '["n-pr-m n-pr-loc"]', 'Chanok, an antediluvian patriach Enoch.', 'from 2596; initiated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4968}/[H4962]', 'lemma', 'heb', 'מְתוּשֶׁלַח', '["Mᵉthûwshelach"]', '["Methuselah"]', '["n-pr-m"]', 'Methushelach, an antediluvian patriarch Methuselah.', 'from 4962 and 7973; man of a dart;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1980I}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ I made walk","and/ I walk about","and/ I will cause to walk","and/ I will walk","and/ I will walk about","and/ he walked","and/ he walked about","and/ he went","and/ he will go","and/ he will walk about","and/ it went","and/ it went about","and/ she went","and/ they had walked","and/ they have walked","and/ they walked","and/ they went","and/ they went about","and/ they will walk","and/ we walked","and/ you have walked","and/ you will walk"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0430G}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["<of the>/ God","<the>/ God","O/ God","[are] <the>/ God","[is] <the>/ God","[was] <the>/ God","of <the>/ God","the/ God","the/ god","the/ judges"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7969}/[H7969]', 'lemma', 'heb', 'שָׁלוֹשׁ', '["shâlôwsh"]', '["<the> three","[are] three","[the] three","[the] three of","[was] three","[were] thir-","[were] three","[will be] three","thir-","three","three [plus]","three [sons]","three [things]","three [times]","three of"]', '["n"]', 'three; occasionally (ordinal) third, or (multiple) thrice fork, often(-times), third, thir(-teen, -teenth), three, thrice. Compare 7991.', 'or שָׁלֹשׁ; masculine שְׁלוֹשָׁה; or שְׁלֹשָׁה; a primitive number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7969}/[H7969]', 'inflected', 'heb', 'שָׁלוֹשׁ', '["shâlôwsh"]', '["and/ [the] three","and/ [was] three","and/ [will be] three","and/ thir-","and/ three","and/ three [years]","and/ three of"]', '["n"]', 'three; occasionally (ordinal) third, or (multiple) thrice fork, often(-times), third, thir(-teen, -teenth), three, thrice. Compare 7991.', 'or שָׁלֹשׁ; masculine שְׁלוֹשָׁה; or שְׁלֹשָׁה; a primitive number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0369}/H9043/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["and/ not [was]/ he","and/ not/ he","and/ there not [is]/ he","and/ there not [is]/ it","and/ there not [will be]/ he","and/ there not [will be]/ it"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}\/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8084}/[H8083]', 'inflected', 'heb', 'שְׁמֹנִים', '["shᵉmônîym"]', '["and/ eighty"]', '["a"]', 'eighty, also eightieth eighty(-ieth), fourscore.', 'or שְׁמוֹנִים; multiple from 8083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3929H>', 'opaque', 'heb', 'לֶמֶךְ', '["Lemek"]', '["Lamech"]', '["n-pr-m"]', 'Lemek, the name of two antediluvian patriarchs Lamech.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5146}/[H5118]', 'lemma', 'heb', 'נֹחַ', '["Nôach"]', '["Noah"]', '["n-pr-m"]', 'Noach, the patriarch of the flood Noah.', 'the same as 5118; rest;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5162G}/H9035/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["he will comfort/ us"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4639G}/H9025/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["from/ work/ our"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6093}/[H6087]', 'inflected', 'heb', 'עִצָּבוֹן', '["ʻitstsâbôwn"]', '["and/ from/ [the] pain of"]', '["n-m"]', 'worrisomeness, i.e. labor or pain sorrow, toil.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}/H9025/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hands/ our"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0779}/H9034/[H779]', 'inflected', 'heb', 'אָרַר', '["ʼârar"]', '["I have cursed/ it","he has cursed/ it"]', '["v"]', 'to execrate × bitterly curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2568}/[H2568]', 'inflected', 'heb', 'חָמֵשׁ', '["châmêsh"]', '["and/ [was] five","and/ [will be] fif-","and/ five"]', '["n"]', 'five fif(-teen), fifth, five (× apiece).', 'masculine חֲמִשָּׁה; a primitive numeral;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7657}/[H7651]', 'inflected', 'heb', 'שִׁבְעִים', '["shibʻîym"]', '["and/ [was] seventy","and/ seventy"]', '["n"]', 'seventy seventy, threescore and ten ( -teen).', 'multiple of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121L}/[H1129]', 'lemma', 'heb', 'בֵּן', '["bên"]', '["[am] a son of","[the] descendants of","[the] son of","[the] sons of","[was] a son of","a son of","son of","sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8035}/[H8034]', 'lemma', 'heb', 'שֵׁם', '["Shêm"]', '["Shem"]', '["n-pr-m"]', 'Shem, a son of Noah (often includ. his posterity) Sem, Shem.', 'the same as 8034; name;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2526G}/[H2525]', 'lemma', 'heb', 'חָם', '["Châm"]', '["Ham"]', '["n-pr-m n-pr-loc"]', 'Cham, a son of Noah; also (as a patronymic) his descendants or their country Ham.', 'the same as 2525; hot (from the tropical habitat);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3315}/[H6601]', 'lemma', 'heb', 'יֶפֶת', '["Yepheth"]', '["Japheth"]', '["n-pr-m"]', 'Jepheth, a son of Noah; also his posterity Japheth.', 'from 6601; expansion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7231}/[H7241]', 'inflected', 'heb', 'רָבַב', '["râbab"]', '["to/ become numerous"]', '["v"]', 'properly, to cast together , i.e. increase, especially in number; to multiply by the myriad increase, be many(-ifold), be more, multiply, ten thousands.', 'a primitive root; (compare 7241); also as denominative from 7233;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121I}/[H1129]', 'lemma', 'heb', 'בֵּן', '["bên"]', '["O sons of","[is] a son of","[the] children of","[the] son of","[the] sons of","a son of","son of","sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1323G}/[H1129]', 'lemma', 'heb', 'בַּת', '["bath"]', '["<of> [the] daughter of","O daughter","O daughter of","O daughters","O daughters of","[am] [the] daughter of","[are] [the] daughter of","[is] a daughter","[the] daughter of","[the] daughters of","[was] a daughter of","a daughter","a daughter of","daughter","daughter of","daughters","daughters of","inlaid in","of [the] daughter of"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2007}/[H2004]', 'lemma', 'heb', 'הֵנָּה', '["hênnâh"]', '["[are] they","[were] they","they","those"]', '["p"]', 'themselves (often used emphatic for the copula, also in indirect relation) × in, × such (and such things), their, (into) them, thence, therein, these, they (had), on this side, whose, wherein.', 'prolongation for 2004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0977}/[H977]', 'lemma', 'heb', 'בָּחַר', '["bâchar"]', '["I chose","I have chosen","I will choose","[are] choosing","[is [the] one whom] you choose","[is to be] chosen","[is] chosen","[one who] he chooses","[the] chosen [men]","[the] chosen [men] of","[which] he has chosen","[which] he will choose","[whom] I have chosen","a chosen [one]","choose","chosen","chosen [man]","he chooses","he chose","he had chosen","he has chosen","he will choose","it chose","let me choose","let us choose","they chose","they have chosen","you choose","you chose","you have chosen","you will choose"]', '["v"]', 'properly, to try, i.e. (by implication) select acceptable, appoint, choose (choice), excellent, join, be rather, require.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1777}/[H1777]', 'lemma', 'heb', 'דִּין', '["dîyn"]', '["<it> will remain","[is one who] pleads","[will be] judging","he defended","he judges","he vindicates","he will judge","judge","let him judge","quarrelling","they have pleaded","you will govern"]', '["v"]', 'to rule; by implication to judge (as umpire); also to strive (as at law) contend contend execute (judgment) judge minister judgment plead (the cause) at strife strive.', 'or (Genesis 6:3) דּוּן; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307G}/H9020/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["spirit/ my"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0120G}/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["<in>/ anyone","among <the>/ humankind","among/ humankind","by <the>/ humankind","for <the>/ person","in <the>/ humankind","on <the>/ humankind","on <the>/ person","on/ anyone","over <the>/ humankind","over/ a person"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/H9007/<H1571>', 'inflected', 'heb', 'בשגם', '["be./sha./Gam"]', '["in/ that/ also"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/H9023', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["[are] days?/ his","day/ his","days/ his"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6242}/[H6235]', 'inflected', 'heb', 'עֶשְׂרִים', '["ʻesrîym"]', '["and/ [was] twenty","and/ twenty"]', '["n"]', 'twenty; also (ordinal) twentieth (six-) score, twenty(-ieth).', 'from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5303}/[H5307]', 'inflected', 'heb', 'נְפִיל', '["nᵉphîyl"]', '["the/ Nephilim"]', '["n-m"]', 'properly, a feller, i.e. a bully or tyrant giant.', 'or נְפִל; from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1992}/[H1931]', 'inflected', 'heb', 'הֵם', '["hêm"]', '["<the>/ those"]', '["p"]', 'they (only used when emphatic) it, like, × (how, so) many (soever, more as) they (be), (the) same, × so, × such, their, them, these, they, those, which, who, whom, withal, ye.', 'or (prolonged) הֵמָּה; masculine plural from 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1571>', 'inflected', 'heb', 'וגם', '["Ve./gam","ve./Gam","ve./gam"]', '["<and>/ as well as","and/ [are] also","and/ [are] both","and/ also"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/[H935]', 'lemma', 'heb', 'בּוֹא', '["bôwʼ"]', '["<he> came","I came","I go","I had gone","I have come","I should come","I went","I will come","I will enter","I will go","[am] about to bring","[am] about to come","[am] about to go","[am] bringing","[am] coming","[are] about to come","[are] about to go","[are] being brought","[are] coming","[are] going","[have] come","[have] gone","[he is] about to come","[he is] coming","[is] about to come","[is] about to go","[is] coming","[is] going","[it is] coming","[one who] comes","[one who] he will come","[people are] coming","[someone is] coming","[they are] coming","[those who were] entering","[those who] came","[those who] come","[was] coming","[was] going","[were] bringing","[were] coming","[which was] about to go","[which] they went","[who] come","[who] come of","[who] they came","[who] were coming of","[will be] coming","actually <come>","anyone go","anyone will go","are they coming","are you coming","came","certainly <come>","certainly <go>","come","comes","coming","did I come","did he come","do you come","does he go?","does it come","everyone will go","go","goes","going","has he come","have I come","have they come","have you come","have you gone","he came","he come","he comes","he goes","he had come","he had gone","he has come","he has gone","he is coming","he should come","he went","he will come","he will go","indeed <come>","it came","it come","it comes","it enter","it go","it goes","it had come","it had gone","it has come","it has gone","it set","it went","it will come","it will go","let her come","let him come","let it come","let me go","let them come","let us go","may it come","people will go","she came","she comes","she let come [anyone]","she went","she will come","she will go","someone came","someone will come","they brought","they came","they come","they go","they had come","they had gone","they have come","they have gone","they should come","they went","they will come","they will go","to come","to go","we came","we have come","we have gone","we went","we will come","we will enter","we will go","went","will I go","will I go?","will he come","will it come","will they come","will they go","will we come","will you come","you came","you come","you enter","you go","you had come","you have come","you have gone","you may go","you must go","you will bring","you will come","you will enter","you will go"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1368}/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["<the>/ mighty","O/ mighty [man]","[were] the/ mighty [men]","the/ mighty [men]","the/ mighty [person]","the/ warrior","the/ warriors"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5769J}/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["[are] from/ long ago","[is] from/ antiquity","[were] from/ long ago","from/ a long time","from/ long ago"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0582}/[H605]', 'lemma', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["<the> person of","O people of","[are] human being[s]","[are] men","[are] men of","[is the] person","[is] a person","[is] humankind","[the] men","[the] men of","[the] people","[the] people of","[was] men","[were] [the] men of","[were] men","[were] men of","a man","a person","human[s]","humankind","humankind of","man","men","men of","people","people of"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8034}\/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["<the>/ name"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7227A}/[H7231]', 'lemma', 'heb', 'רַב', '["rab"]', '["O great [one] of","[are] great","[are] many","[is too] great","[is too] numerous","[is] enough","[is] great","[is] great of","[is] many","[is] numerous","[it is] many","[one] great","[the] great [amount] of","[the] greatness of","[the] many","[too] great","[too] much","[was too] much","[was] great","[was] much","[was] numerous","[were] many","[were] numerous","[will be] great of","[will be] many","abundance of","enough","great","great [people]","great of","greatness of","many","many [bones]","many [people]","many [things]","much","numerous"]', '["a n-m"]', 'abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent).', 'by contracted from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451I}/[H7489]', 'lemma', 'heb', 'רַע', '["raʻ"]', '["<of> evil","[is] an evil","[is] evil","[the] evil of","[the] harm of","[the] wicked deeds of","[the] wickedness of","an evil thing","calamities","calamity","displeasure","evil","evil things","harm","trouble","troubles"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3336}/[H3335]', 'lemma', 'heb', 'יֵצֶר', '["yêtser"]', '["<the> inclination of","[the] inclination of","an inclination","inclination of"]', '["n-m"]', 'a form; figuratively, conception (i.e. purpose) frame, thing framed, imagination, mind, work.', 'from 3335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4284}/[H2803]', 'lemma', 'heb', 'מַחֲשָׁבָה', '["machăshâbâh"]', '["[are] thoughts of","[the] plan of","[the] plans of","[the] thoughts of","a plan","a purpose","design","designs","invention of","plans","plans of","thoughts"]', '["n-f"]', 'a contrivance, i.e. (concretely) a texture, machine, or (abstractly) intention, plan (whether bad, a plot; or good, advice) cunning (work), curious work, device(-sed), imagination, invented, means, purpose, thought.', 'or מַחֲשֶׁבֶת; from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9023/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart/ his","heart/ its","of heart/ his","own heart/ his"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7535}/[H7534]', 'lemma', 'heb', 'רַק', '["raq"]', '["certainly","only"]', '["adv"]', 'properly, leanness, i.e. (figuratively) limitation; only adverbial, merely, or conjunctional, although but, even, except, howbeit howsoever, at the least, nevertheless, nothing but, notwithstanding, only, save, so (that), surely, yet (so), in any wise.', 'the same as 7534 as a noun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451H}/[H7489]', 'lemma', 'heb', 'רַע', '["raʻ"]', '["<of> evil","<the> displeasing of","[are] displeasing","[are] evil","[is it] evil","[is] evil","[the] wicked deeds of","[was] displeasing","[was] evil","[were] displeasing","[were] wicked","a [person] evil of","an evil [person]","bad","displeasing of","evil","evil [people]","evil [things]","evil deeds","evil of","evil things","wicked","wicked [people]"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3117J>', 'inflected', 'heb', 'הימים', '["hai./Yom","hai./yOm","hai./ya.Mim"]', '["<the>/ day","the/ day","the/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5162H}/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["and/ I repent","and/ I will relent","and/ I will repent","and/ he regretted","and/ he relented","and/ he repented","and/ he will relent"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6087A}/[H6087]', 'inflected', 'heb', 'עָצַב', '["ʻâtsab"]', '["and/ he was pained","and/ they were indignant"]', '["v"]', 'properly, to carve, i.e. fabricate or fashion; hence (in a bad sense) to worry, pain or anger displease, grieve, hurt, make, be sorry, vex, worship, wrest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4229A}/[H4229]', 'lemma', 'heb', 'מָחָה', '["mâchâh"]', '["I have wiped out","I will wipe","I will wipe out","[who is] wiping out","certainly <to wipe out>","he wipes [it] clean","it be wiped out","it will be wiped away","it will be wiped out","may it be wiped out","may they be wiped out","someone wipes clean","wipe out","you have wiped out","you will wipe out","you wipe out"]', '["v"]', 'properly, to stroke or rub; by implication, to erase; also to smooth (as if with oil), i.e. grease or make fat; also to touch, i.e. reach to abolish, blot out, destroy, full of marrow, put out, reach unto, × utterly, wipe (away, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0120G}/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["[are] from/ humankind","from/ a man","from/ everyone","from/ humankind"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5704}/[H5703]', 'inflected', 'heb', 'עַד', '["ʻad"]', '["and/ [is] to","and/ [will be] until","and/ to","and/ until","and/ unto"]', '["prep"]', 'as far (or long, or much) as, whether of space (even unto) or time (during, while, until) or degree (equally with) against, and, as, at, before, by (that), even (to), for(-asmuch as), (hither-) to, how long, into, as long (much) as, (so) that, till, toward, until, when, while, ( as) yet.', 'properly, the same as 5703 (used as a preposition, adverb or conjunction; especially with a preposition);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5162H}/[H5162]', 'lemma', 'heb', 'נָחַם', '["nâcham"]', '["I am grieved","I have repented","I regret","I relented","I repented","I will have pity","[who] relents","he regretted","he relented","he will regret","he will repent","it should regret","to relent","will I relent"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213H}/H9038/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["I have made/ them","[those who] make/ them","you made/ them"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5146}/[H5118]', 'inflected', 'heb', 'נֹחַ', '["Nôach"]', '["and/ Noah"]', '["n-pr-m"]', 'Noach, the patriarch of the flood Noah.', 'the same as 5118; rest;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2580}/[H2603]', 'lemma', 'heb', 'חֵן', '["chên"]', '["[are] favor","[the] favor of","[the] grace of","favor","grace"]', '["n-m"]', 'graciousness, i.e. subjective (kindness, favor) or objective (beauty) favour, grace(-ious), pleasant, precious, (well-) favoured.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869A}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["for/ eye","in/ [the] eyes of","in/ eye"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6662}/[H6663]', 'lemma', 'heb', 'צַדִּיק', '["tsaddîyq"]', '["<of> [the] righteous","O righteous [people]","[are] righteous","[are] righteous [people]","[has been] righteous","[is] a righteous [person]","[is] righteous","[is] righteous [person]","[the] righteous","[the] righteous [one]","[was] righteous","[will be] righteous","a [person] righteous","a righteous [person]","a righteous [son]","correct","righteous","righteous [people]"]', '["a"]', 'just just, lawful, righteous (man).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8549H}/[H8552]', 'lemma', 'heb', 'תָּמִים', '["tâmîym"]', '["<of> blameless","[are people] blameless of","[people] blameless of","[were] blameless","a blameless [person]","blameless","blameless [people]"]', '["a"]', 'entire (literally, figuratively or morally); also (as noun) integrity, truth without blemish, complete, full, perfect, sincerely (-ity), sound, without spot, undefiled, upright(-ly), whole.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1755}/H9023/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["in/ generations/ his"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7843}/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["and/ <it> was corrupt","and/ I destroy","and/ he destroyed","and/ he spoiled","and/ he will destroy","and/ it was spoiled","and/ she acted corruptly","and/ they acted corruptly","and/ they destroyed","and/ they will destroy","and/ you behaved corruptly","and/ you will act corruptly","and/ you will destroy","and/ you will spoil"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440G}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before","<to>/ forwards","[are] <to>/ before","[is] <to>/ before","[was] <to>/ before","[were] <to>/ before","[which] <to>/ before","[will be] <to>/ before","to/ [the] face","to/ [the] front of","to/ front of"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4390}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["and/ <it> was filled","and/ I have filled","and/ I will confirm","and/ I will fill","and/ he completed","and/ he filled","and/ he has filled","and/ he was filled","and/ it filled","and/ it has been filled","and/ it was completed","and/ it was filled","and/ it will be full","and/ people filled","and/ she filled","and/ they filled","and/ they have filled","and/ they were completed","and/ they will be full","and/ they will fill","and/ you have filled","and/ you were filled","and/ you will fill"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2555}/[H2554]', 'lemma', 'heb', 'חָמָס', '["châmâç"]', '["[is] violence","[the] violence of","injustice","violence","violence<s>"]', '["n-m"]', 'violence; by implication, wrong; by metonymy unjust gain cruel(-ty), damage, false, injustice, × oppressor, unrighteous, violence (against, done), violent (dealing), wrong.', 'from 2554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7843}/[H7843]', 'lemma', 'heb', 'שָׁחַת', '["shâchath"]', '["<it> had corrupted","I should ruin","I will destroy","I will destroy [it]","I will ruin","[are] about to destroy","[are] destroyers","[is] about to destroy","[one who] destroys","[were] about to destroy","[were] behaving corruptly","[were] destroying","[who] behave corruptly","a blemished [animal]","a destroyer","certainly <to act corruptly>","destroyed","destroyers","destroying","destruction","he destroyed [them]","he has ruined","he ruins","he will destroy","he will ruin","it has acted corruptly","it has behaved corruptly","it was corrupt","it was ruined","it will destroy","let us destroy","ruined","they act corruptly","they corrupted","they destroyed","they had ruined","they have dealt corruptly","they have ruined","they will destroy","to destroy","you destroy","you have corrupted","you have ruined","you perverted","you will destroy","you will trim"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870G}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["<of> ways/ his","conduct/ his","own way/ his","way/ his","way/ its","ways/ his","ways/ its"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0776G>\', 'inflected', 'heb', 'הארצות פ', '["ha./''A.retz","ha./''a.ra.Tzot"]', '["the/ earth","the/ land","the/ lands"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5146}/[H5118]', 'inflected', 'heb', 'נֹחַ', '["Nôach"]', '["to/ Noah"]', '["n-pr-m"]', 'Noach, the patriarch of the flood Noah.', 'the same as 5118; rest;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7093}/[H7112]', 'lemma', 'heb', 'קֵץ', '["qêts"]', '["[is] an end","[the] end","[the] end of","[was] an end","[will be] [the] end of","[will be] an end","an end"]', '["n-m"]', 'an extremity; adverbially (with prepositional prefix) after after, (utmost) border, end, (in-) finite, × process.', 'contracted from 7112;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935M}/[H935]', 'lemma', 'heb', 'בּוֹא', '["bôwʼ"]', '["[am] about to bring","[is] coming","[which] comes","it comes","it has come","it will come","surely <come>","they will come"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440G}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ me","[is] <to>/ before/ me","[was] <to>/ before/ me","[were] <to>/ before/ me"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4390}/[H4390]', 'lemma', 'heb', 'מָלֵא', '["mâlêʼ"]', '["<it> is full","<of> will be completed","I am full","I fill","I filled","I will be filled","I will complete","I will fill","[am] about to fill","[is] filled","[was] overflowing","[were] filling","[which] they complete","are completed","complete","fill","fill [it]","filled","filling","he filled","he fills","he had filled","he has filled","he has fulfilled","he will arm himself","he will complete","he will fill","is completed","is full","it filled","it had filled","it has been completed","it has filled","it is filled","it is full","it was filled","it was full","it will be completed","it will be filled","it will be full","let me fill","may he fulfill","may you fill","people filled","someone will fill","they are filled","they are full","they filled","they have been completed","they have filled","they were completed","they were full","they will be completed","they will be filled","they will fill","was full","we filled","we will fill","were completed","will you fill?","you are full","you fill","you filled","you have filled","you have fulfilled","you will be filled","you will fill"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440I}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<from>/ because of/ them"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2005}/H9040/[H2005]', 'inflected', 'heb', 'הֵן', '["hên"]', '["and/ here [am]/ I","and/ here/ I"]', '["prt"]', 'lo!; also (as expressing surprise) if behold, if, lo, though.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7843}/H9038/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["I will destroy/ them","about to destroy/ them","to destroy/ them"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8392}/[H8392]', 'lemma', 'heb', 'תֵּבָה', '["têbâh"]', '["a basket of","an ark of"]', '["n-f"]', 'a box ark.', 'perhaps of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6086G}/[H6095]', 'lemma', 'heb', 'עֵץ', '["ʻêts"]', '["[is] wood","[the] wood of","[the] wood<s> of","[was] wood","[were] wood","a tree","tree","wood","wood of","wood<s>","wood<s> of"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1613>', 'opaque', 'heb', 'גֹּפֶר', '["gôpher"]', '["gopher"]', '["n-m"]', 'a kind of tree or wood (as used for building), apparently the cypress gopher.', 'from an unused root, probably meaning to house in;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7064}/[H7077]', 'lemma', 'heb', 'קֵן', '["qên"]', '["a nest","a nest of","nests"]', '["n-m"]', 'a nest (as fixed), sometimes including the nestlings; figuratively, a chamber or dwelling nest, room.', 'contracted from 7077;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8392}/[H8392]', 'inflected', 'heb', 'תֵּבָה', '["têbâh"]', '["the/ ark","the/ basket"]', '["n-f"]', 'a box ark.', 'perhaps of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3722B}/[H3722]', 'inflected', 'heb', 'כָּפַר', '["kâphar"]', '["and/ you will cover"]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0853}/H9034/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["<obj.>/ her","<obj.>/ it"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004O}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[are] from/ inside","[was] from/ inside","from/ inside"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H2351>', 'inflected', 'heb', 'ומחצות', '["u./me./chu.tzOt","u./mi./Chutz"]', '["and/ from/ [the] outside","and/ from/ [the] streets of","and/ from/ outside"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3724B}/[H3722]', 'inflected', 'heb', 'כֹּפֶר', '["kôpher"]', '["with <the>/ pitch"]', '["n-m"]', 'properly, a cover, i.e. (literally) a village (as covered in); (specifically) bitumen (as used for coating), and the henna plant (as used for dyeing); figuratively, a redemption-price bribe, camphire, pitch, ransom, satisfaction, sum of money, village.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2088}/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["and/ this","and/ this [one]","and/ this one","and/ what","and/ whom"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0520A}/[H517]', 'lemma', 'heb', 'אַמָּה', '["ʼammâh"]', '["[is] a cubit","[the] cubit of","[was] a cubit","[was] cubits","[was] two cubits","[will be] a cubit","[will be] two cubits","a cubit","cubit[s]","cubits"]', '["n-f"]', 'properly, a mother (i.e. unit of measure, or the fore-arm (below the elbow), i.e. a cubit; also a door-base (as a bond of the entrance) cubit, + hundred (by exchange for 3967), measure, post.', 'prolonged from 517;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0753}/[H748]', 'lemma', 'heb', 'אֹרֶךְ', '["ʼôrek"]', '["[the] length","[the] length of","a length","length","length of"]', '["n-m"]', 'length forever, length, long.', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2572}/[H2568]', 'lemma', 'heb', 'חֲמִשִּׁים', '["chămishshîym"]', '["[are] fifty","[was] fifty","[were] fifty","[will be] fifty","a fifty","fifties","fifty","fifty [measures]","fifty [men]"]', '["n"]', 'fifty fifty.', 'multiple of 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7341}/H9024/[H7337]', 'inflected', 'heb', 'רֹחַב', '["rôchab"]', '["[is] breadth/ its","breadth/ its"]', '["n-m"]', 'width (literally or figuratively) breadth, broad, largeness, thickness, wideness.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6967}/H9024/[H6965]', 'inflected', 'heb', 'קוֹמָה', '["qôwmâh"]', '["height/ its"]', '["n-f"]', 'height × along, height, high, stature, tall.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6672B}/[H6671]', 'lemma', 'heb', 'צֹהַר', '["tsôhar"]', '["a roof"]', '["n-m"]', 'a light (i.e. window); dual double light, i.e. noon midday, noon(-day, -tide), window.', 'from 6671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8392}/[H8392]', 'inflected', 'heb', 'תֵּבָה', '["têbâh"]', '["for the/ ark"]', '["n-f"]', 'a box ark.', 'perhaps of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615G}/H9034/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["you will finish/ it"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H4605}/H9011/[H5927]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["from/ to/ above/ <towards>"]', '["adv"]', 'properly,the upper part, used only adverbially with prefix upward, above, overhead, from the top, etc. above, exceeding(-ly), forward, on (× very) high, over, up(-on, -ward), very.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6607}/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["and/ [the] entrance of","and/ an entrance"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6654>/H9024', 'inflected', 'heb', 'בצדה', '["be./tzi.Da/h"]', '["in/ side/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760A}/[H7760]', 'lemma', 'heb', 'שׂוּם', '["sûwm"]', '["I had put","I have made","I have ordained","I have set","I have set up","I make","I performed","I will make","I will set","[am] about to make","[am] about to put","[am] about to set","[who] made","[will be] set","cause to set","did he appoint","did he make","do you appoint","does he make","he charges","he had appointed","he had put","he has made","he has put","he made","he puts","he set","he set up","he will establish","he will make","he will put","he will set","it has made","it makes","it will make","make","place","put","put [it]","set","set [it]","someone has set","they formed","they had set","they have put","they have set","they made","they make","they put","they set","they set up","they will set","they will set up","we have made","will he appoint","you appointed","you have made","you have set","you have set up","you made","you performed","you set","you will make","you will put","you will set"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8482}/[H8478]', 'lemma', 'heb', 'תַּחְתִּי', '["tachtîy"]', '["O lower parts of","[the] lowest parts","lower","lower [decks]","lowest","lowest parts"]', '["a"]', 'lowermost; as noun (feminine plural) the depths (figuratively, a pit, the womb) low (parts, -er, -er parts, -est), nether (part).', 'from 8478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8145}/[H8138]', 'lemma', 'heb', 'שֵׁנִי', '["shênîy"]', '["[is] a second [person]","[was] a second","a second","a second [time]","second","second [decks]","second [thing]"]', '["n"]', 'properly, double, i.e. second; also adverbially, again again, either (of them), (an-) other, second (time).', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7992}/[H7969]', 'inflected', 'heb', 'שְׁלִישִׁי', '["shᵉlîyshîy"]', '["and/ [the] third of","and/ third","and/ third [decks]"]', '["a"]', 'third; feminine a third (part); by extension, a third (day, year or time); specifically, a third-story cell) third (part, rank, time), three (years old).', 'ordinal from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213A}/H9034/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["I will do/ it","he does/ it","he will do/ it","they do/ it","you have done/ it","you will make/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0589}/[H595]', 'inflected', 'heb', 'אֲנִי', '["ʼănîy"]', '["<and>/ I","and/ I"]', '["p"]', 'I I, (as for) me, mine, myself, we, × which, × who.', 'contracted from 595;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2009}/H9040/[H2005]', 'inflected', 'heb', 'הִנֵּה', '["hinnêh"]', '["here [am]/ I","here/ I"]', '["dp"]', 'lo! behold, lo, see.', 'prolongation for 2005;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3999}/[H2986]', 'inflected', 'heb', 'מַבּוּל', '["mabbûwl"]', '["the/ flood"]', '["n-m"]', 'a deluge flood.', 'from 2986 in the sense of flowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7843}/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["<to>/ behaved corruptly","to/ destroy"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307H}/[H7306]', 'lemma', 'heb', 'רוּחַ', '["rûwach"]', '["[are] a wind","[is] a breath","[is] breath","[the] breath of","[the] wind","[the] wind of","[the] winds of","[which] [the] wind of","a wind","a wind of","breath","wind","wind of","winds"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1478}/[H1478]', 'lemma', 'heb', 'גָּוַע', '["gâvaʻ"]', '["<it> will die","I expired","I will expire","did he die?","he had died","it will expire","they perished","they will perish","we had died","we will die"]', '["v"]', 'to breathe out, i.e. (by implication) expire die, be dead, give up the ghost, perish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6965I}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ I have arisen","and/ I raised up","and/ I will carry out","and/ I will establish","and/ I will raise up","and/ he arose","and/ he established","and/ he has carried out","and/ he has established","and/ he set","and/ he set up","and/ he stood","and/ he will confirm","and/ he will raise up","and/ it was confirmed","and/ it will be established","and/ it will stand","and/ people set up","and/ they arose","and/ they set up","and/ they stood","and/ they will stand","and/ you fulfilled","and/ you will set up"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1285}/H9020/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["<of> covenant/ my","[is] covenant/ my","covenant of/ my","covenant/ my"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9031/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["[am] with/ you","[are] with/ you","[is] with/ you","[will be] with/ you","with <the>/ you","with/ you"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ I came","and/ I have come","and/ I went","and/ I will go","and/ [is] coming","and/ he brought","and/ he came","and/ he goes","and/ he went","and/ he will come","and/ he will go","and/ it came","and/ it goes","and/ it has come","and/ it went","and/ it will come","and/ it will go","and/ people came","and/ people will go","and/ she came","and/ she went","and/ they came","and/ they have come","and/ they went","and/ they will come","and/ they will go","and/ we came","and/ we went","and/ we will come","and/ you [masc] have come","and/ you came","and/ you had come","and/ you will bring","and/ you will come","and/ you will go"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121A}/H9021/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ child/ your","and/ children/ your","and/ son/ your","and/ sons/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0802H}/H9021/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ wife/ your","and/ wives/ your"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0802H}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ [the] wife of","and/ [the] wives of","and/ a wife of","and/ a woman","and/ wives"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121A}/H9021/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["[am] son/ your","child/ your","children/ your","son/ your","sons/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2421}/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["by/ preserving alive","to/ let live","to/ live","to/ preserve alive","to/ restore"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5775}/[H5774]', 'inflected', 'heb', 'עוֹף', '["ʻôwph"]', '["of/ the/ bird[s]"]', '["n-m"]', 'a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4480A}/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["and/ from","and/ from when","and/ of","and/ one of","and/ some of"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/H9031/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["[am] against/ you","[are] to/ you","against/ you","to/ you","to/ yourself"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3978}/[H398]', 'lemma', 'heb', 'מַאֲכָל', '["maʼăkâl"]', '["[the] food of","food","food of"]', '["n-m"]', 'an eatable (includ. provender, flesh and fruit) food, fruit, (bake-)meat(-s), victual.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0622}/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["and/ I will gather","and/ he gathered","and/ he gathered himself","and/ he has gathered","and/ he removed","and/ he was gathered","and/ he will deliver","and/ he will gather","and/ it gathered","and/ it will be gathered","and/ it will be removed","and/ they are gathered","and/ they gathered","and/ they gathered themselves","and/ they were gathered","and/ they will be gathered","and/ they will gather","and/ you will be gathered","and/ you will gather","and/ you will gather [it]"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H9038}', 'inflected', 'heb', 'ולהם', '["ve./la./Hem"]', '["and/ [belonged] to/ them","and/ for <the>/ them","and/ for <the>/ themselves","and/ to <the>/ them","and/ to/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6213A}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ I acted","and/ I did","and/ I will act","and/ I will bring about","and/ I will deal with","and/ I will do","and/ did he do?","and/ did you do?","and/ he acted","and/ he appointed","and/ he dealt with","and/ he did","and/ he has done","and/ he made","and/ he observed","and/ he will act","and/ he will do","and/ he will observe","and/ he will offer","and/ he will use [them]","and/ it did","and/ it produced","and/ it will act","and/ it will do","and/ she did","and/ she will attend to","and/ she worked","and/ someone did","and/ they acted","and/ they celebrated","and/ they did","and/ they had done","and/ they made","and/ they observed","and/ they produced","and/ they will act","and/ they will bring about","and/ they will deal with","and/ they will do","and/ they will observe [them]","and/ they worked","and/ we did","and/ we have done","and/ we will do","and/ we will do [it]","and/ will it be made?","and/ you did","and/ you have done","and/ you will act","and/ you will do","and/ you will do [them]","and/ you will observe","and/ you will observe [them]"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3605}/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["[is] like/ all","[will be] like/ all","according to/ all","according to/ every","like <the>/ everyone","like/ all","like/ every"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6680}/[H6680]', 'lemma', 'heb', 'צָוָה', '["tsâvâh"]', '["I appointed","I commanded","I had been commanded","I have appointed","I have been commanded","I have commanded","I was commanded","I will command","[am] about to command","[am] about to give command","[am] commanding","[is] commanding","[which] he commanded","command","has he commanded","have I commanded","have you commanded","he commanded","he commanded [it]","he commands","he had been commanded","he had commanded","he has commanded","he has ordained","he may command","he ordained","he was commanded","he will command","it has commanded","ordain","she had commanded","someone appointed","will he command","you are commanded","you commanded","you had commanded","you have commanded","you have given command","you will command"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213A}\/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["do","he did","let him do","they did","they will do","we will act","will I do","you have done","you will do"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004M}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["house/ your","household/ your","own house/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0853}/H9031/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["<obj.>/ you"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200G}/[H7200]', 'lemma', 'heb', 'רָאָה', '["râʼâh"]', '["<of> [which] we saw","I had seen","I have seen","I look","I looked","I looked at","I may see","I saw","I see","I see [him]","I should look","I will appear","I will look","I will present myself","I will see","I will see [him]","[am] about to show","[am] seeing","[are] about to see","[are] being shown","[are] seeing","[are] seeing [it]","[is] seeing","[one who] looks","[those who] see","[was one who] saw","[was] seeing","[was] visible","[were] looking","[were] seeing","[which] I have seen","[which] sees","[who] he has seen","[who] saw","[who] sees","[will be] looking","[will be] seeing","anyone will see","appears","are you looking at one another","certainly <to see>","certainly [if] <to see>","consider","continually <to see>","did they see","did you see","do you see","does he see","has he seen","have I seen","have you seen","have you seen?","he appeared","he be seen","he had appeared","he had seen","he had shown","he has appeared","he has looked","he has seen","he has shown","he look","he presents himself","he saw","he sees","he should see","he showed","he was seen","he will appear","he will look","he will present himself","he will see","he will show","it appeared","it has appeared","it has been seen","it has looked","it has presented itself","it has seen","it look","it saw","it sees","it should see","it was seen","it will appear","it will be seen","it will see","let it be visible","let me see","let them see","let us look at one another","let us see","look at","may he look","may he see","may it appear","people have seen","people see","people will present themselves","present yourself","see","seeing","seeing [him]","she had seen","she saw","she will see","they had been seen","they had looked","they had seen","they have appeared","they have seen","they look","they may see","they saw","they see","they see [it]","they were seen","they were visible","they will look","they will present themselves","they will see","to see","we have seen","we may see","we saw","we see","we will see","will I see","will he see","will you look","you considered","you have been shown","you have made see","you have seen","you look","you saw","you see","you were shown","you will look","you will see","you will see [it]"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1755}/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["<in>/ a generation","[are] in/ a generation of","[is] with/ a generation","in the/ generation","in/ a generation"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2088}/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["<the>/ this"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2889}/[H2891]', 'inflected', 'heb', 'טָהוֹר', '["ṭâhôwr"]', '["<the>/ clean","<the>/ pure","the/ clean [person]","the/ clean [thing]","the/ pure [thing]"]', '["a"]', 'pure (in a physical, chemical, ceremonial or moral sense) clean, fair, pure(-ness).', 'or טָהֹר; from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2889}/[H2891]', 'lemma', 'heb', 'טָהוֹר', '["ṭâhôwr"]', '["[is] clean","[is] pure","[was] pure","[were] pure","a clean [thing]","a pure","clean","clean [person]","pure","pure [person]","pure of"]', '["a"]', 'pure (in a physical, chemical, ceremonial or moral sense) clean, fair, pure(-ness).', 'or טָהֹר; from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5775}/[H5774]', 'inflected', 'heb', 'עוֹף', '["ʻôwph"]', '["from/ [the] bird[s] of","of/ [the] bird[s] of"]', '["n-m"]', 'a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3117G>', 'inflected', 'heb', 'לימים', '["Le./yom","la/i.Yom","la/i.yOm","la/i.ya.Mim","le./Yom","le./ya.Mim","li./Mei"]', '["<to> the/ days","<to>/ a day","<to>/ a day of","[belongs] to/ a day","[is] for the/ days","[is] of/ days","[it is] for/ days","for the/ day","for/ [the] day","for/ [the] day of","for/ a day","for/ a day of","for/ days","into/ a day","into/ day","to the/ day","to the/ days","to/ [the] day of","to/ [the] days of","to/ a day","to/ a day of","to/ day","to/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0705}/[H702]', 'inflected', 'heb', 'אַרְבָּעִים', '["ʼarbâʻîym"]', '["and/ forty"]', '["n"]', 'forty forty.', 'multiple of 702;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4229A}/[H4229]', 'inflected', 'heb', 'מָחָה', '["mâchâh"]', '["and/ I will wipe","and/ I will wipe clean","and/ he will wipe [them] off","and/ he will wipe away","and/ he will wipe out","and/ he wiped out","and/ they were wiped out","and/ they will be wiped out"]', '["v"]', 'properly, to stroke or rub; by implication, to erase; also to smooth (as if with oil), i.e. grease or make fat; also to touch, i.e. reach to abolish, blot out, destroy, full of marrow, put out, reach unto, × utterly, wipe (away, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3351}/[H6965]', 'inflected', 'heb', 'יְקוּם', '["yᵉqûwm"]', '["the/ existence","the/ substance"]', '["n-m"]', 'properly, standing (extant), i.e. by implication, a living thing (living) substance.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6680}/H9033/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["I commanded/ him","I will command/ him","he commanded/ him","he had commanded/ him","you will command/ him"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8337}/[H7797]', 'lemma', 'heb', 'שֵׁשׁ', '["shêsh"]', '["[are] six","[the] six","[was] six","[were] six","[were] six-","[will be] six","six","six [sons]","six [things]","six of","six-"]', '["n"]', 'six (as an overplus beyond five or the fingers of the hand); as ordinal sixth six(-teen, -teenth), sixth.', 'masculine שִׁשָּׁה; a primitive number; see 7797');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3999}/[H2986]', 'inflected', 'heb', 'מַבּוּל', '["mabbûwl"]', '["and/ the/ flood"]', '["n-m"]', 'a deluge flood.', 'from 2986 in the sense of flowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121A}/H9023/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ descendants/ his","and/ son/ his","and/ sons/ his"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9033/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["<obj.>/ him","[are] with/ him","[is] with/ him","[was] with/ him","[was] with/ it","[were] with/ him","[who were] with <the>/ him","with <the>/ him","with/ him","with/ it"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440G}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<from>/ because of","[away] from/ before","[is] away from/ [the] face of","from/ before"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0369}/H9044/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["[was] not/ it","not [was]/ it","not/ it"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5775}/[H5774]', 'inflected', 'heb', 'עוֹף', '["ʻôwph"]', '["<the>/ bird","<the>/ wing","the/ bird[s]","the/ insect"]', '["n-m"]', 'a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0834D}/[H834]', 'inflected', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["<as>/ since","<just>/ when","[are] just/ as","[is] just/ as","[was] just/ as","according to/ [that] which","as/ [the one] who","just/ as","just/ when"]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7651}/[H7650]', 'inflected', 'heb', 'שֶׁבַע', '["shebaʻ"]', '["<into>/ seven","for/ [the] seven","for/ seven","for/ seven-","into/ seven","to/ [the] seven","to/ seven"]', '["n"]', 'seven (as the sacred full one); also (adverbially) seven times; by implication, a week; by extension, an indefinite number ( by) seven(-fold),-s, (-teen, -teenth), -th, times). Compare 7658.', 'or (masculine) (שִׁבְעָה); from 7650; a primitive cardinal number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4325G}/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["and/ [is] water","and/ [the] waters","and/ [the] waters of","and/ water","and/ waters of"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8141}/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["in the/ year","in the/ years","in/ [the] year","in/ [the] year of","in/ a year","in/ year"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2416E}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["[is] <to>/ life","[is] to/ life","for <the>/ life","for/ life","of/ [the] life of","to/ life","to/ life of"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2320G}/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["[is] in the/ month","by/ month","in the/ month","in/ [the] month of"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7651}/[H7650]', 'inflected', 'heb', 'שֶׁבַע', '["shebaʻ"]', '["in/ seven","on/ [day] seven","on/ [the] seven","on/ [the] seven-","with/ seven"]', '["n"]', 'seven (as the sacred full one); also (adverbially) seven times; by implication, a week; by extension, an indefinite number ( by) seven(-fold),-s, (-teen, -teenth), -th, times). Compare 7658.', 'or (masculine) (שִׁבְעָה); from 7650; a primitive cardinal number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2320G}/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["for the/ month","for/ [the] months of","of the/ month","of/ [the] month","of/ [the] month of","of/ [the] months of","of/ month","to/ month"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1234}/[H1234]', 'lemma', 'heb', 'בָּקַע', '["bâqaʻ"]', '["[one who] cleaves","[who] split open","broken into","he split open","he splits open","it is hatched","it is split open","it was broken into","it will be split open","it will break forth","it will break through [the wall]","they have hatched","they have split","they were split open","they will be cleft","they will burst forth","you broke open","you split open","you will rip open"]', '["v"]', 'to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4599}/[H5869]', 'lemma', 'heb', 'מַעְיָן', '["maʻyân"]', '["[the] spring of","[the] springs of","[were] springs","a spring","a spring of","spring of","springs"]', '["n-m"]', 'a fountain (also collectively), figuratively, a source (of satisfaction) fountain, spring, well.', 'or מַעְיְנוֹ; (Psalm 114:8), or (feminine) מַעְיָנָה; from 5869 (as a denominative in the sense of a spring);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0699}/[H693]', 'inflected', 'heb', 'אֲרֻבָּה', '["ʼărubbâh"]', '["and/ [the] floodgates of"]', '["n-f"]', 'a lattice; (by implication) a window, dovecot (because of the pigeon-holes), chimney (with its apertures for smoke), sluice (with openings for water) chimney, window.', 'feminine participle passive of 693 (as if for lurking);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6605A}/[H6605]', 'lemma', 'heb', 'פָּתַח', '["pâthach"]', '["I open","I opened","I will loosen","I will open","[am] about to open","[is one who] opens","[is] drawn","[is] opened","[was] opening","[will be one who] opens","[you are] opening","certainly <to open>","did he loosen","does he loosen?","has he opened","he has loosened","he has opened","he loosens","he opened","he opens","he will open","it has been opened","it has opened","it is opened","it opened","it will be let loose","it will be opened","let it open up","let me open","loosen for yourself","open","opened","she opens","they have been opened","they have drawn","they have opened","they were opened","they will be opened","they will be unstopped","to loosen","will you loosen","you have loosened","you loosened","you open","you will open"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1653}/[H1652]', 'inflected', 'heb', 'גֶּשֶׁם', '["geshem"]', '["<the>/ rain","the/ rain"]', '["n-m"]', 'a shower rain, shower.', 'from 1652;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6106H}/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["on/ [the] substance of"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8035}/[H8034]', 'inflected', 'heb', 'שֵׁם', '["Shêm"]', '["and/ Shem"]', '["n-pr-m"]', 'Shem, a son of Noah (often includ. his posterity) Sem, Shem.', 'the same as 8034; name;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2526G}/[H2525]', 'inflected', 'heb', 'חָם', '["Châm"]', '["and/ Ham"]', '["n-pr-m n-pr-loc"]', 'Cham, a son of Noah; also (as a patronymic) his descendants or their country Ham.', 'the same as 2525; hot (from the tropical habitat);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3315}/[H6601]', 'inflected', 'heb', 'יֶפֶת', '["Yepheth"]', '["and/ Japheth"]', '["n-pr-m"]', 'Jepheth, a son of Noah; also his posterity Japheth.', 'from 6601; expansion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9038/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["[am] with/ them","[are] <obj.>/ them","[will be] with/ them","with/ them"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2416C}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["<the>/ animal","<the>/ living creature","O/ animal[s]","[is] the/ living creature","[was] the/ living creature","the/ animal[s]","the/ living creature","the/ living creatures"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6833}/[H6852]', 'lemma', 'heb', 'צִפּוֹר', '["tsippôwr"]', '["[the] bird[s] of","a bird","bird","bird of","bird[s]","birds"]', '["n-f"]', 'a little bird (as hopping) bird, fowl, sparrow.', 'or צִפֹּר; from 6852;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1320}/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["<the>/ flesh","[are] the/ meat","the/ flesh","the/ meat"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ the/ [one who] comes","and/ the/ [one who] goes","and/ the/ [ones who] came","and/ those/ [which] came"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1157}/H9033/[H5704]', 'inflected', 'heb', 'בְּעַד', '["bᵉʻad"]', '["behind/ him","for/ him","for/ himself"]', '["prep"]', 'in up to or over against; generally at, beside, among, behind, for, etc. about, at by (means of), for, over, through, up (-on), within.', 'from 5704 with prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7235A}/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["and/ I increased","and/ I will increase","and/ I will multiply","and/ he has multiplied","and/ he increased","and/ he increases","and/ it increased","and/ it was great","and/ she increased","and/ they became great","and/ they increased","and/ they multiplied","and/ they will increase","and/ they will multiply","and/ you grew","and/ you have increased","and/ you increased","and/ you will increase"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375H}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ I carried","and/ I will forgive","and/ he carried","and/ he will bear","and/ he will carry off","and/ it will be carried","and/ it will be carried off","and/ it will bear","and/ she lifted [it] up","and/ she lifted up","and/ someone took","and/ someone will carry away","and/ they brought","and/ they carried","and/ they carried [it]","and/ they carried [them]","and/ they carried off","and/ they carried off [things]","and/ they have borne","and/ they lifted","and/ they took","and/ they will bear","and/ they will carry","and/ they will cause to bring","and/ you will carry"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7311A}/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["and/ he contributed","and/ he has raised up","and/ he lifted up","and/ he raised","and/ he took up","and/ he will lift up","and/ it lifted up","and/ it rose","and/ it was exalted","and/ it was lifted up","and/ it will be lifted up","and/ you have raised up","and/ you will offer up","and/ you will raise"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1396}/[H1396]', 'inflected', 'heb', 'גָּבַר', '["gâbar"]', '["and/ I will make strong","and/ he will make strong","and/ it prevailed","and/ they increased"]', '["v"]', 'to be strong; by implication, to prevail, act insolently exceed, confirm, be great, be mighty, prevail, put to more (strength), strengthen, be stronger, be valiant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4325G}/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["and/ the/ water","and/ the/ waters"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1396}/[H1396]', 'lemma', 'heb', 'גָּבַר', '["gâbar"]', '["do they become strong?","he behaves proudly","he has prevailed","he was strong","he will make strong","he will prevail","it is strong","they are [too] strong","they are strong","they have prevailed","they increased","they prevailed","they were behaving proudly","they were strong","we will make strong"]', '["v"]', 'to be strong; by implication, to prevail, act insolently exceed, confirm, be great, be mighty, prevail, put to more (strength), strengthen, be stronger, be valiant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3680}/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["and/ I covered","and/ I will cover","and/ he covered","and/ he covered himself","and/ he will cover","and/ it covered","and/ it has covered","and/ it will cover","and/ she covered","and/ she covered [it]","and/ she covered herself","and/ they covered","and/ they were covered","and/ they will cover","and/ we will conceal","and/ you have covered","and/ you will cover"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2022G}/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["<the>/ mountain","O/ mountains","the/ hill","the/ hill country","the/ hills","the/ mountain","the/ mountains"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1364}/[H1361]', 'inflected', 'heb', 'גָּבֹהַּ', '["gâbôahh"]', '["<the>/ high"]', '["a"]', 'elevated (or elated), powerful, arrogant haughty, height, high(-er), lofty, proud, × exceeding proudly.', 'or גָּבוֹהַּ; (fully) from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478G}/[H8430]', 'lemma', 'heb', 'תַּחַת', '["tachath"]', '["[are] under","[is] under","[was] under","[were] under","[will be] under","beneath","under"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1478}/[H1478]', 'inflected', 'heb', 'גָּוַע', '["gâvaʻ"]', '["and/ he expired","and/ it died"]', '["v"]', 'to breathe out, i.e. (by implication) expire die, be dead, give up the ghost, perish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5775}/[H5774]', 'inflected', 'heb', 'עוֹף', '["ʻôwph"]', '["among the/ bird[s]"]', '["n-m"]', 'a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2416C}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["and/ among the/ animal[s]"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8318}/[H8317]', 'inflected', 'heb', 'שֶׁרֶץ', '["sherets"]', '["<the>/ swarming thing"]', '["n-m"]', 'a swarm, i.e. active mass of minute animals creep(-ing thing), move(-ing creature).', 'from 8317;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8317}/[H8317]', 'inflected', 'heb', 'שָׁרַץ', '["shârats"]', '["which/ swarms"]', '["v"]', 'to wriggle, i.e. (by implication) swarm or abound breed (bring forth, increase) abundantly (in abundance), creep, move.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2724}/[H2720]', 'inflected', 'heb', 'חָרָבָה', '["chârâbâh"]', '["[was] on the/ dry ground","on the/ dry ground"]', '["n-f"]', 'a desert dry (ground, land).', 'feminine of 2720;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7604}/[H7604]', 'inflected', 'heb', 'שָׁאַר', '["shâʼar"]', '["and/ I will leave","and/ he was left","and/ it will be left","and/ she was left","and/ they had remained","and/ they survived","and/ you will be left"]', '["v"]', 'properly, to swell up, i.e. be (causatively, make) redundant leave, (be) left, let, remain, remnant, reserve, the rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0389}/[H403]', 'lemma', 'heb', 'אַךְ', '["ʼak"]', '["[are] only","[is] only","just as","nevertheless","only","surely"]', '["adv"]', 'a particle of affirmation, surely; hence (by limitation) only also, in any wise, at least, but, certainly, even, howbeit, nevertheless, notwithstanding, only, save, surely, of a surety, truly, verily, wherefore, yet (but).', 'akin to 403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0834A}/[H834]', 'inflected', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["and/ [one] who","and/ [that] which","and/ [the one] who","and/ [the one] whom","and/ [the things] which","and/ [those] which","and/ [those] who","and/ [those] whom","and/ that","and/ which","and/ who","and/ whom"]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8392}/[H8392]', 'inflected', 'heb', 'תֵּבָה', '["têbâh"]', '["in the/ ark"]', '["n-f"]', 'a box ark.', 'perhaps of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2142}/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["and/ I have remembered","and/ I will remember","and/ he remembered","and/ it remembered","and/ they remembered","and/ they will remember","and/ you will be remembered","and/ you will remember"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5674A}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["and/ I passed by","and/ I passed on","and/ I will make pass","and/ I will make to pass","and/ I will pass","and/ he caused to pass","and/ he has passed on","and/ he made pass","and/ he made pass by","and/ he made to pass","and/ he made to pass away","and/ he passed","and/ he passed away","and/ he passed by","and/ he passed on","and/ he passed over","and/ he passed through","and/ he sent over","and/ he will pass","and/ he will pass over","and/ he will pass through","and/ it passed","and/ it passed by","and/ it passed on","and/ it passed over","and/ it passes by","and/ it passes on","and/ it will pass","and/ it will pass on","and/ it will pass over","and/ they caused to pass","and/ they have passed through","and/ they made pass","and/ they passed","and/ they passed by","and/ they passed on","and/ they passed over","and/ they passed through","and/ they will cause to pass","and/ they will pass","and/ they will pass by","and/ we passed along","and/ we passed away","and/ we passed over","and/ we will pass on","and/ you passed over","and/ you will cause to pass through","and/ you will make [it] pass","and/ you will make pass over","and/ you will pass over"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7918}/[H7918]', 'inflected', 'heb', 'שָׁכַךְ', '["shâkak"]', '["and/ I will put an end to","and/ they subsided"]', '["v"]', 'to weave (i.e. lay) a trap; figuratively, (through the idea of secreting) to allay (passions; physically, abate a flood) appease, assuage, make to cease, pacify, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5534}/[H5534]', 'inflected', 'heb', 'סָכַר', '["çâkar"]', '["and/ I will hand over","and/ they were shut up"]', '["v"]', 'to shut up; by implication, to surrender stop, give over. See also 5462, 7936.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3607}/[H3607]', 'inflected', 'heb', 'כָּלָא', '["kâlâʼ"]', '["and/ it was restrained","and/ they were restrained"]', '["v"]', 'to restrict, by act (hold back or in) or word (prohibit) finish, forbid, keep (back), refrain, restrain, retain, shut up, be stayed, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725G}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I brought back","and/ I returned","and/ I turned back","and/ I will bring back","and/ I will return","and/ I will turn","and/ he brought back","and/ he had returned","and/ he has returned","and/ he restored","and/ he returned","and/ he took back","and/ he turned","and/ he turned back","and/ he was brought back","and/ he went back","and/ he will bring back","and/ he will repay","and/ he will return","and/ he will turn back","and/ it returned","and/ it turned back","and/ it turns back","and/ it went back","and/ it will return","and/ it will turn","and/ she returned","and/ she will return","and/ they brought back","and/ they put back","and/ they returned","and/ they returned of","and/ they took back","and/ they turned back","and/ they went back","and/ they will return","and/ we returned","and/ you returned","and/ you went back","and/ you will return","and/ you will take back","and/ you will turn","and/ you will turn back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980L}/[H3212]', 'lemma', 'heb', 'הָלַךְ', '["hâlak"]', '["I have walked","I will go","[am] going","[is] going","[was] going","[were] going","[which] goes","continuously <to go>","continuously <to walk>","going","it goes","they walk","they will go","walking","you go","you will go"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725J}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ come back","and/ it will return","and/ return","and/ turning back","and/ we will return","and/ you return"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2637}/[H2637]', 'inflected', 'heb', 'חָסֵר', '["châçêr"]', '["and/ they decreased"]', '["v"]', 'to lack; by implication, to fail, want, lessen be abated, bereave, decrease, (cause to) fail, (have) lack, make lower, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7097A}/[H7096]', 'inflected', 'heb', 'קָצֶה', '["qâtseh"]', '["[is] from/ [the] end of","from/ [the] end","from/ [the] end of","from/ an end of"]', '["n-m"]', 'an extremity × after, border, brim, brink, edge, end, (in-) finite, frontier, outmost coast, quarter, shore, (out-) side, × some, ut(-ter-) most (part).', 'or (negative only) קֵצֶה; from 7096; (used in a great variety of applications and idioms; compare 7093)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5117}/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["and/ I will give rest","and/ I will give rest to","and/ I will set [it]","and/ I will set down","and/ has he given rest?","and/ he deposited","and/ he gave rest","and/ he had given rest","and/ he has given rest","and/ he left","and/ he placed","and/ he placed [them]","and/ he rested","and/ he set [it]","and/ he will deposit [them]","and/ he will give rest","and/ it rested","and/ it settled down","and/ it will be placed","and/ it will rest","and/ she placed","and/ they leave","and/ they left","and/ they placed [them]","and/ they rested","and/ they will set down","and/ they will settle","and/ we will set","and/ you will deposit [it]","and/ you will leave","and/ you will set down"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2022G}/[H2042]', 'lemma', 'heb', 'הַר', '["har"]', '["O mountain","O mountain of","O mountains","O mountains of","[the] hill country of","[the] mount of","[the] mountain","[the] mountain of","[the] mountains","[the] mountains of","[were] mountains of","a mountain","hill","mountain","mountains","mountains of"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0780>', 'opaque', 'heb', 'אֲרָרַט', '["ʼĂrâraṭ"]', '["Ararat"]', '["n-pr-loc"]', 'Ararat (or rather Armenia) Ararat, Armenia.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2637}/[H2637]', 'inflected', 'heb', 'חָסֵר', '["châçêr"]', '["and/ decreasing","and/ depriving"]', '["v"]', 'to lack; by implication, to fail, want, lessen be abated, bereave, decrease, (cause to) fail, (have) lack, make lower, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2320G}/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["[was] the/ month","the/ month","the/ new moon"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6224}/[H6235]', 'inflected', 'heb', 'עֲשִׂירִי', '["ʻăsîyrîy"]', '["<the>/ tenth","[was] the/ tenth","the/ tenth","the/ tenth [month]"]', '["a"]', 'tenth; by abbreviation, tenth month or (feminine) part tenth (part).', 'from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6224}/[H6235]', 'inflected', 'heb', 'עֲשִׂירִי', '["ʻăsîyrîy"]', '["in the/ tenth [month]"]', '["a"]', 'tenth; by abbreviation, tenth month or (feminine) part tenth (part).', 'from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0259}/[H258]', 'inflected', 'heb', 'אֶחָד', '["ʼechâd"]', '["[is] <in>/ one","at/ one","at/ one of","in/ one","in/ one [plus]","in/ one of","on/ [day] one","on/ one","on/ one [occasion]","on/ one [trumpet]","on/ one of","with/ [the] one","with/ one"]', '["a"]', 'properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,', 'a numeral from 258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218I>', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["[the] best","[the] chief of","[the] choicest of","[the] heads of","[the] top","[the] top of","[the] tops of","head of"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6605A}/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["and/ I opened","and/ he had opened","and/ he opened","and/ he opened [it]","and/ he unharnessed","and/ he will open","and/ it opened","and/ it was opened","and/ it will open","and/ she opened","and/ she opened [it]","and/ someone will open","and/ they opened","and/ they opened [them]","and/ they will be open","and/ you will loosen","and/ you will open"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2474}/[H2474]', 'lemma', 'heb', 'חַלּוֹן', '["challôwn"]', '["[the] window of","windows of"]', '["n"]', 'a window (as perforated) window.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971G}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ I sent","and/ I will send","and/ I will send forth","and/ he had sent","and/ he had sent off","and/ he has sent","and/ he sent","and/ he sent [it]","and/ he sent [them]","and/ he sent away","and/ he sent off","and/ he sent out","and/ he stretched out","and/ he will let go","and/ he will send [it] away","and/ it had sent","and/ it sent","and/ it sent out","and/ people sent","and/ she sent","and/ they let down","and/ they sent","and/ they sent [them]","and/ they sent away","and/ they sent out","and/ they will send","and/ you sent","and/ you will send","and/ you will send away"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6158}/[H6150]', 'inflected', 'heb', 'עֹרֵב', '["ʻôrêb"]', '["the/ raven","the/ ravens"]', '["n-m"]', 'a raven (from its dusky hue) raven.', 'or עוֹרֵב; from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318G}/[H3318]', 'lemma', 'heb', 'יָצָא', '["yâtsâʼ"]', '["I came out","I have come forth","I have come out","I should come out","I went out","I went outside","I will come forth","I will go out","[am] about to go forth","[am] about to go out","[any] escaping","[are] about to come out","[are] about to go out","[are] coming out","[are] going out","[he is] going out","[he was] coming out","[is] about to go forth","[is] coming out","[the] going out of","[those which] came out of","[those who] go out","[those who] went out","[those who] went out of","[was one] going out","[was] coming out","[was] going out","[were] coming forth","[were] going forth","[were] going out","[which] it goes forth","[who] were going out of","came out","certainly <to go out>","come out","coming out","continuously <to come>","continuously <to go out>","do you come out","does it come forth","does it goes forth?","ever <to go out>","get out","go forth","go out","going forth","going out","has he come out","has he gone out","has it gone out","he came out","he come out","he go out","he goes out","he had come forth","he had gone out","he has come out","he has gone out","he went forth","he went forward","he went out","he will come forth","he will come out","he will go forth","he will go out","him go out","it came out","it comes forth","it comes out","it goes forth","it had come forth","it has come out","it has gone forth","it has gone out","it will come out","it will go forth","it will go out","let him come forth","let him go out","let it go forth","let us go","may it come forth","one going out","send out","she came forth","she will go out","they came out","they go forth","they go out","they had gone out","they have come out","they have gone out","they went out","they will come forth","they will come out","they will go out","to go out","went out","will we go out","you came out","you go out","you have gone out","you must go out","you went out","you will go out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725G}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I will bring back","and/ I will return","and/ I will turn","and/ [one who] returns","and/ [was] returning","and/ he will return","and/ he will turn","and/ it will return","and/ let him return","and/ let us return","and/ repay","and/ return","and/ returned","and/ take back","and/ they were returning","and/ will you return?","so/ I may return","so/ he may return","so/ let me return","so/ let us return","so/ let us turn back","so/ may he return","so/ may it return","so/ may it turn back","so/ they may bring back","so/ they may return","so/ they may turn back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3001}/[H3001]', 'lemma', 'heb', 'יָבֵשׁ', '["yâbêsh"]', '["<it> was dry","I am withering","I make dry","I will dry up","I will make dry","completely <to wither>","dried up","he dried up","he had dried up","he has been put to shame","it dried up","it dries up","it has dried up","it has withered","it is dried up","it was dried up","it will be dry","it will dry up","it will wither","they are dried up","they have become dry","they have dried up","totally <wither>","will it be dried up","will it wither","you dried up"]', '["v"]', 'to be ashamed, confused or disappointed; also (as failing) to dry up (as water) or wither (as herbage) be ashamed, clean, be confounded, (make) dry (up), (do) shame(-fully), × utterly, wither (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3123}/[H3196]', 'inflected', 'heb', 'יוֹנָה', '["yôwnâh"]', '["the/ dove"]', '["n-f"]', 'a dove (apparently from the warmth of their mating) dove, pigeon.', 'probably from the same as 3196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0854}/H9033/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["from / with <the>/ him","from/ with <the>/ him"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7043}/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["¿/ is it [too] trifling","¿/ trifling","¿/ was it trifling","¿/ were they abated"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4494}/[H5117]', 'lemma', 'heb', 'מָנוֹחַ', '["mânôwach"]', '["a resting place"]', '["n-m"]', 'quiet, i.e. (concretely) a settled spot, or (figuratively) a home (place of) rest.', 'from 5117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3709H}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["for/ [the] sole of","to/ [the] sole of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7272}/H9024/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["feet/ her","feet/ its","foot/ her","foot/ its"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/H9033/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["<to>/ him","<to>/ himself","<to>/ it","[was] to/ him","against/ him","against/ it","concerning/ him","concerning/ it","into/ it","to/ him","to/ himself","to/ it","with/ him","with/ it"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971K}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ I will stretch out","and/ he sent","and/ he stretched out","and/ she will stretch out","and/ they stretched out"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947G}/H9034/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ fetched it/ she","and/ he fetched/ it","and/ he took/ her","and/ he took/ it"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2342K}/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["and/ he waited","and/ they writhed"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971G}/[H7971]', 'lemma', 'heb', 'שָׁלַח', '["shâlach"]', '["I have been sent","I have sent","I send","I sent","I will cast out","I will send","I will shoot","[am] about to send","[am] about to send away","[am] sending","[are] being sent","[are] sending","[are] sending [him]","[has been] sent","[have been] sending","[have been] sent","[is] deserted","[is] sending","[one who] sends","[the] stretching out of","[was] sent","[which has] been sent","[whoever] you will send","[whom] I will send","[you are] about to send away","certainly <to send>","did I send","has he sent","he had sent","he has been sent","he has sent","he is caught","he sends","he sends out","he sent","he sent away","he stretched out","he was sent","he will be sent","he will send","he will stretch out","it sends out","it sent","it sent out","it stretched out","let him send","let us send","let us send out","may he send","send","send [them]","send [them] away","send away","sending","sent","sent away","she had sent","she has sent out","she sent","they have sent","they have sent away","they send forth","they sent","they were sent off","they will let loose","to send","to send out","we sent","will I send","you have sent","you have sent away","you must send","you send away","you send forth","you sent","you sent forth","you stretch out","you will send","you will send away","you will send out"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6256}/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["[is] for/ [the] time of","for/ [the] time of","for/ a time","for/ a time of","of the/ times","to/ [the] time of","to/ a time","to/ a time of","to/ times","to/ times of"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2132H>', 'opaque', 'heb', 'זַיִת', '["zayith"]', '["[the] olive tree","an olive tree","olive","olive tree of","olive tree[s]","olive trees","olive[s]"]', '["n-m"]', 'an olive (as yielding illuminating oil), the tree, the branch or the berry olive (tree, -yard), Olivet.', 'probably from an unused root (akin to 2099);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2965}/[H2963]', 'lemma', 'heb', 'טָרָף', '["ṭârâph"]', '["[the] fresh [things] of","freshly plucked"]', '["a"]', 'recently torn off, i.e. fresh pluckt off.', 'from 2963;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6310G}/H9024/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["[was] in/ mouth/ its","in/ mouth/ her"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7043}/[H7043]', 'lemma', 'heb', 'קָלַל', '["qâlal"]', '["I am insignificant","[one who] curses","[were] bringing a curse","a trifling [thing]","curse","he cursed","he has cursed","he has shaken","he has sharpened","he is cursing","he treated with contempt","he will be cursed","he will curse","he will lighten","it curses","it is [too] trifling","it is cursed","it is trifling","lighten","they are swift","they curse","they have been swift","they have treated with contempt","they shook to and fro","they were abated","they were swift","they will be insignificant","they will curse","they will prove swift","will he curse","you curse","you have cursed","you must curse","you will curse"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3176G}/[H3176]', 'inflected', 'heb', 'יָחַל', '["yâchal"]', '["and/ he waited","and/ they waited","and/ will I wait?"]', '["v"]', 'to wait; by implication, to be patient, hope (cause to, have, make to) hope, be pained, stay, tarry, trust, wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8337}/[H7797]', 'inflected', 'heb', 'שֵׁשׁ', '["shêsh"]', '["and/ [was] six","and/ six","and/ six-"]', '["n"]', 'six (as an overplus beyond five or the fingers of the hand); as ordinal sixth six(-teen, -teenth), sixth.', 'masculine שִׁשָּׁה; a primitive number; see 7797');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7223G}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["[will be] at the/ first [place]","at <the>/ first","at the/ first","at the/ first [time]","at the/ former [time]","in the/ first","in the/ first [month]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2717A}/[H2717]', 'lemma', 'heb', 'חָרַב', '["chârab"]', '["I dry up","be dried up","it dries up","it will become dry","they had been dried","they have been dried","they were dried up"]', '["v"]', 'to parch (through drought) i.e. (by analogy,) to desolate, destroy, kill decay, (be) desolate, destroy(-er), (be) dry (up), slay, × surely, (lay, lie, make) waste.', 'or חֲרֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5493G}/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["and/ I removed","and/ I will remove","and/ he has removed","and/ he removed","and/ he turned aside","and/ he will remove","and/ it will be removed","and/ it will come to an end","and/ she removed","and/ she will remove","and/ they removed","and/ they will abolish","and/ they will remove","and/ you will remove"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4372}/[H3680]', 'lemma', 'heb', 'מִכְסֶה', '["mikçeh"]', '["[the] covering of","a covering","a covering of"]', '["n-m"]', 'a covering, i.e. weatherboarding covering.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2320G}/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["and/ [will be] in the/ month","and/ in the/ month"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1696G}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ I have spoken","and/ I said","and/ I spoke","and/ I will speak","and/ has he spoken?","and/ he had spoken","and/ he speaks","and/ he spoke","and/ he will speak","and/ it spoke","and/ it will speak","and/ she spoke","and/ they spoke","and/ they will say","and/ they will speak","and/ you have spoken","and/ you said","and/ you spoke","and/ you will say","and/ you will speak"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318H}/[H3318]', 'lemma', 'heb', 'יָצָא', '["yâtsâʼ"]', '["I brought [it] out","I brought out","I have brought out","I will bring out","[are] about to be brought out","[he is] bringing out","[people will] bring out","[was being] brought out","bring out","he brings out","he brought out","he had brought out","he has brought forth","he has sent forth","he will bring forth","he will bring out","it had been brought out","it will go forth","it will go out","let me bring out","people will bring out","send out","someone will bring out","they brought [them] out","they brought out","they had brought out","to take [them] out","you brought out","you go forth","you have brought out","you must bring out","you will bring [it] out","you will bring out","you will take out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8317}/[H8317]', 'inflected', 'heb', 'שָׁרַץ', '["shârats"]', '["and/ it will swarm","and/ they swarmed","and/ they will swarm"]', '["v"]', 'to wriggle, i.e. (by implication) swarm or abound breed (bring forth, increase) abundantly (in abundance), creep, move.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6509}/[H6509]', 'inflected', 'heb', 'פָּרָה', '["pârâh"]', '["and/ I will make fruitful","and/ he made fruitful","and/ they were fruitful","and/ they will be fruitful","and/ we will be fruitful","and/ you will be fruitful"]', '["v"]', 'to bear fruit (literally or figuratively) bear, bring forth (fruit), (be, cause to be, make) fruitful, grow, increase.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4940}/H9028/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["to/ clans/ their","to/ families/ their"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4196}/[H2076]', 'lemma', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["O altar","[is the] altar","[the] altar","[the] altar of","[the] altars of","altar","altars","an altar","an altar of"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5927I}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ I have offered up","and/ I offered up","and/ he offered [it] up","and/ he offered up","and/ he will offer up","and/ they offered up","and/ they will offer up","and/ you will offer up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5930A}/[H5927]', 'lemma', 'heb', 'עֹלָה', '["ʻôlâh"]', '["[is the] burnt offering of","[is] a burnt offering","[the] burnt offering","[the] burnt offering of","[the] burnt offerings of","[was] a burnt offering","a burnt offering","a burnt offering of","burnt offering","burnt offering[s]","burnt offerings","burnt offerings of"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4196}/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["<in> the/ altar","on the/ altar"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7306}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ he smelled"]', '["v"]', 'properly, to blow, i.e. breathe; only (literally) to smell or (by implication, perceive (figuratively, to anticipate, enjoy) accept, smell, × touch, make of quick understanding.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7381}/[H7306]', 'lemma', 'heb', 'רֵיחַ', '["rêyach"]', '["[is] an odor of","[the] odor of","[the] smell of","an odor","an odor of","odor"]', '["n-m"]', 'odor (as if blown) savour, scent, smell.', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5207}/[H5117]', 'inflected', 'heb', 'נִיחוֹחַ', '["nîychôwach"]', '["<the>/ soothing"]', '["n-m"]', 'properly, restful, i.e. pleasant; abstractly, delight sweet (odour).', 'or נִיחֹחַ; from 5117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7043}/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["to/ curse","to/ lighten","to/ treat with contempt"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5668}/[H5674]', 'inflected', 'heb', 'עָבוּר', '["ʻâbûwr"]', '["<in>/ because","for/ sake of","for/sake of","in/ order","in/order that"]', '["prep"]', 'properly, crossed, i.e. (abstractly) transit; used only adverbially, on account of, in order that because of, for (...''s sake), (intent) that, to.', 'or עָבֻר; passive participle of 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/[H3824]', 'lemma', 'heb', 'לֵב', '["lêb"]', '["<of> [the] heart","[is] a heart","[is] heart","[the] heart","[the] heart of","a heart","a heart of","heart"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5271A}/H9023/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["since/ youth<s>/ his","since/ youth<s>/ its"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5221}/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["to/ [one who] struck down","to/ [those who] struck [it]","to/ strike","to/ strike down"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7105A}/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["and/ [the] harvest of","and/ harvest"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7120}/[H7119]', 'inflected', 'heb', 'קֹר', '["qôr"]', '["and/ cold"]', '["n-m"]', 'cold cold.', 'from the same as 7119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2527}/[H2552]', 'inflected', 'heb', 'חֹם', '["chôm"]', '["and/ heat"]', '["n-m"]', 'heat heat, to be hot (warm).', 'from 2552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7019}/[H6972]', 'inflected', 'heb', 'קַיִץ', '["qayits"]', '["and/ summer","and/ summer fruit"]', '["n-m"]', 'harvest (as the crop), whether the product (grain or fruit) or the (dry) season summer (fruit, house).', 'from 6972;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2779}/[H2778]', 'inflected', 'heb', 'חֹרֶף', '["chôreph"]', '["and/ winter"]', '["n-m"]', 'properly, the crop gathered, i.e. (by implication) the autumn (and winter) season; figuratively, ripeness of age cold, winter (-house), youth.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3117G>', 'inflected', 'heb', 'וימים', '["va./Yom","ve./Yom","ve./ya.Mim","vi./Mei"]', '["and/ [the] day","and/ [the] day of","and/ [the] days of","and/ a day","and/ a day of","and/ day","and/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3915}/[H3883]', 'inflected', 'heb', 'לַיִל', '["layil"]', '["and/ [will be] night","and/ night","and/ nights of"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4172A}/H9026/[H3372]', 'inflected', 'heb', 'מוֹרָא', '["môwrâʼ"]', '["and/ fear/ your"]', '["n-m"]', 'fear; by implication, a fearful thing or deed dread, (that ought to be) fear(-ed), terribleness, terror.', 'or מֹרָא; or מוֹרָהxlit môrâh corrected to môwrâh; (Psalm 9:20), from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2844A}/H9026/[H2865]', 'inflected', 'heb', 'חַת', '["chath"]', '["and/ dread/ your"]', '["n-m"]', 'concretely, crushed; also afraid; abstractly, terror broken, dismayed, dread, fear.', 'from 2865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5921A}/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["<and>/ [were] over","and/ [are] on","and/ [be] over","and/ [is] on","and/ [was] on","and/ [was] over","and/ [were] on","and/ [were] with","and/ [which] at","and/ [will be] on","and/ [will be] over","and/ at","and/ because","and/ concerning","and/ on","and/ over","and/ to","and/ towards","and/ with"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3605}/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["<in>/ all","<in>/ any","<in>/ every","[are] in/ all","[are] in/ every","[is] among/ all","[is] in <the>/ everything","[is] in/ every","[is] on/ all","[was] in/ all","[were] in/ all","[were] in/ every","[will be] in/ all","[will be] on <the>/ everyone","against/ all","among/ all","among/ every","at/ all","at/ any","at/ every","by/ all","by/ any","for/ all","in <the>/ everything","in/ all","in/ all of","in/ any","in/ every","on/ all","on/ every","over <the>/ all","over <the>/ everything","over/ all","over/ every","with <the>/ everything","with/ all","with/ any","with/ every"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1709H}/[H1711]', 'lemma', 'heb', 'דָּג', '["dâg"]', '["[the] fish of","a fish","fish","fish<es>"]', '["n-m"]', 'a fish (often used collectively) fish.', 'or (fully) דָּאג; (Nehemiah 13:16), from 1711; a fish (as prolific); or perhaps rather from 1672 (as timid); but still better from 1672 (in the sense of squirming, i.e. moving by the vibratory action of the tail);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027G}/H9026/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[am] in/ hand/ your","[are] in/ hand/ your","[is] in/ hand/ your","in/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3418}/[H3417]', 'inflected', 'heb', 'יֶרֶק', '["yereq"]', '["like/ [the] greenery of"]', '["n-m"]', 'properly, pallor, i.e. hence, the yellowish green of young and sickly vegetation; concretely, verdure, i.e. grass or vegetation grass, green (thing).', 'from 3417 (in the sense of vacuity of color);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315H}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["[is] <in>/ life/ its","[is] for/ life/ his","by/ own life/ his","with/ life/ his","with/ life/ its"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1818}/H9023/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["[is] blood/ its","blood/ his","blood/ its","blood<s>/ his","blood<s>/ its"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0389}/[H403]', 'inflected', 'heb', 'אַךְ', '["ʼak"]', '["and/ nevertheless","and/ only","and/ surely"]', '["adv"]', 'a particle of affirmation, surely; hence (by limitation) only also, in any wise, at least, but, certainly, even, howbeit, nevertheless, notwithstanding, only, save, surely, of a surety, truly, verily, wherefore, yet (but).', 'akin to 403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1818}/H9026/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["blood of/ your"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315H}/H9026/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["of/ lives/ you"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1875}/[H1875]', 'lemma', 'heb', 'דָּרַשׁ', '["dârash"]', '["I have sought","I let myself be consulted","I sought","I will let myself be consulted","I will let myself be sought","I will require","I will seek","O [you who] seek","[is one who] cares","[is one who] searches","[is] being required","[is] caring for","[is] searching","[is] seeking","[one who] seeks","[one] sought out","[they are] studied","carefully <to seek>","certainly <to require>","consult","have you required","have you sought","he consulted","he seeks","he sought","he will seek","it searches","requiring","seek","seeking","seeks","she seeks","they care for","they had sought","they have searched for","they have sought","they seek","they were investigated","they will seek","we have sought","we seek","we sought [him]","will I let myself be consulted","will I let myself be consulted?","will it consult","you must seek","you seek","you should enquire","you will resort","you will search","you will seek"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027K}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[will be] from/ [the] hand of","from/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1875}/H9033/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["I will seek/ it","[those who] seek/ him","[who] it will seek/ him","he care for/ it","he will require/ it","they have sought/ him","they seek/ him","we sought/ him","we sought/ it","you will seek/ him"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3027K}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ from/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0376I>', 'opaque', 'heb', 'אִישׁ', '["ʼîysh"]', '["<of> anyone","[is] anyone","[was] a person","[was] anyone","anyone","each","each man","each one","everyone","everyone [masc]","everyone of","someone"]', '["n-m"]', 'a man as an individual or a male person; often used as an adjunct to a more definite term (and in such cases frequently not expressed in translation) also, another, any (man), a certain, champion, consent, each, every (one), fellow, (foot-, husband-) man, (good-, great, mighty) man, he, high (degree), him (that is), husband, man(-kind), none, one, people, person, steward, what (man) soever, whoso(-ever), worthy. Compare 802.', 'contracted for 582 (or perhaps rather from an unused root meaning to be extant);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251I}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["brother/ his","brother/ its","brothers/ his","countryman/ his","countrymen/ his","relatives/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8210H}/[H8210]', 'lemma', 'heb', 'שָׁפַךְ', '["shâphak"]', '["<it> will be shed","[the] [one who] sheds","[which] shed","[which] sheds","[who] sheds","[women who] shed","he had shed","he has shed","he shed","it was shed","it will be shed","they had poured out","they shed","to shed","you have shed","you shed"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0859D}/[H859]', 'inflected', 'heb', 'אַתָּה', '["ʼattâh"]', '["and/ [are] you?","and/ you"]', '["p"]', 'thou and thee, or (plural) ye and you thee, thou, ye, you.', 'or (shortened); אַתָּ; or אַת; feminine (irregular) sometimes אַתִּי; plural masculine אַתֶּם; feminine אַתֶּן; or אַתֵּנָהlemma אתֵּנָה missing vowel, corrected to אַתֵּנָה; or אַתֵּנָּה; a primitive pronoun of the second person;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9034}\', 'inflected', 'heb', 'בה ס', '["Ba/h","Va/h"]', '["<in> <the>/ it","[was] in <the>/ it","[will be] on <the>/ it","by <the>/ it","in <the>/ it","in/ it","on <the>/ it","on/ her","with <the>/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2005}/H9040/[H2005]', 'inflected', 'heb', 'הֵן', '["hên"]', '["here [am]/ I","here/ I","if [was]/ I"]', '["prt"]', 'lo!; also (as expressing surprise) if behold, if, lo, though.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965I}/[H6965]', 'lemma', 'heb', 'קוּם', '["qûwm"]', '["I established","I have carried out","I have established","I have stood","I will carry out","I will establish","I will raise up","[one who] raises up","[who] establishes","about to establish","arise","certainly <to be established>","certainly <to carry out>","establish","fulfill","has he set up","he had imposed","he has carried out","he has confirmed","he may establish","he raised","he set up","he will arise","he will carry out","he will raise up","he will stand","it confirmed","it endures","it is established","it was carried out","it was set","it will be fulfilled","it will endure","it will rise","it will stand","may he carry out","set up","station","they had imposed","they have carried out","they imposed","they were fixed","they will be established","they will raise up","they will stand","to carry out","to establish","will he stand","will it be established","you will carry out","you will raise up","you will set up"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9036/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["[am] with/ you","[are] with/ you","[is] with/ you","[will be] with/ you","with/ you"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0854}/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ <obj.>","and/ [is] with","and/ with"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2233H}/H9026/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["offspring/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310A}/H9036/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["after/ you","behind/ you"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0929>', 'inflected', 'heb', 'בבהמות', '["ba./be.he.Mah","be./va.ha.Mot","be./ve.he.Mat","bi/v.he.Mah"]', '["<in>/ livestock","among the/ animal[s]","among the/ livestock","among/ [the] animals of","among/ [the] livestock of","among/ livestock","by <the>/ animal[s]","for/ an animal","in/ an animal"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3772I}/[H3772]', 'lemma', 'heb', 'כָּרַת', '["kârath"]', '["<it> will be cut off","I have cut off","I will cut off","certainly <cut off>","cut off","he had cut off","he has cut off","he may be cut off","he will be cut off","he will cut off","it is cut off","it may be cut off","it was chewed","it will be cut off","may he cut off","they cut off","they will be cut off","to cut off","were cut off","you cut off","you must cut off","you will cut off"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4325G}/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["any of/ [the] water of","from/ [the] waters of","from/ waters","some of/ [the] water of"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3999}/[H2986]', 'lemma', 'heb', 'מַבּוּל', '["mabbûwl"]', '["a flood"]', '["n-m"]', 'a deluge flood.', 'from 2986 in the sense of flowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1285}/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["[is] the/ covenant","of the/ covenant","the/ covenant"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0589}/[H595]', 'lemma', 'heb', 'אֲנִי', '["ʼănîy"]', '["I","I [am]","[am] I","[am] I?","[it is] I","[was it] I","[was] I","[which] I","[will] I","me","of me"]', '["p"]', 'I I, (as for) me, mine, myself, we, × which, × who.', 'contracted from 595;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414I}/[H5414]', 'lemma', 'heb', 'נָתַן', '["nâthan"]', '["I have made","I make","I will make","[am] about to make","[am] making","give","he gave","he has made","he has put","he is made","he made","he will give","he will make","may he make","people have made","they have made","you give","you have given","you have made","you will make"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0996G}/H9030/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["[be] between/ me","[is] between/ me","[will be] between/ me","between/ me"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0996G}/H9036/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["and/ between/ you"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1755}/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["[is] to/ a generation","for/ a generation","for/ generations of","of/ a generation","to the/ generation","to/ a generation","to/ a generation of","to/ generation"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5769G}/[H5956]', 'lemma', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["[is] forever","antiquity","everlastingness<es>","everlastingness<es> of","forever","perpetuity"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7198}/H9020/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["bow/ my"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414H}/[H5414]', 'lemma', 'heb', 'נָתַן', '["nâthan"]', '["I gave","I have appointed","I have given","I have put","I have set","I put","I set","I will give","I will put","I will set","[am] about to give","[am] about to put","[am] putting","[am] setting","[he is] putting","[was] appointed","[were] assigned","[which] he has given","assign","gave","he appointed","he gave","he gives","he had put","he has given","he has put","he has set","he put","he put [them]","he set","he sets","he will give","he will put","it has been put","it is put","it makes","it was made","it was put","it will be put","it will put","let him put","let us appoint","people will put","put","putting","set","she will put","they assigned","they had appointed","they had put","they have been put","they have put","they have set","they may set","they put","to put","will I put","will he give","you gave","you give","you had set","you have appointed","you have put","you have set up","you must make","you put","you will appoint","you will give","you will give [him]","you will put"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6051}/[H6049]', 'inflected', 'heb', 'עָנָן', '["ʻânân"]', '["by the/ cloud","in the/ cloud","in the/ cloud[s]","with <the>/ cloud"]', '["n-m"]', 'a cloud (as covering the sky), i.e. the nimbus or thunder-cloud cloud(-y).', 'from 6049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1285}/[H1262]', 'lemma', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["<of> [the] covenant of","[is] a covenant of","[the] covenant","[the] covenant of","a covenant","a covenant of","covenant of"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6049A}/H9040/[H6051]', 'inflected', 'heb', 'עָנַן', '["ʻânan"]', '["when/ bring cloud/ I"]', '["v"]', 'figuratively, to act covertly, i.e. practise magic × bring, enchanter, Meonemin, observe(-r of) times, soothsayer, sorcerer.', 'a primitive root; to cover; used only as a denominative from 6051, to cloud over;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6051}/[H6049]', 'lemma', 'heb', 'עָנָן', '["ʻânân"]', '["[the] cloud","[the] cloud of","a cloud","cloud","cloud[s]"]', '["n-m"]', 'a cloud (as covering the sky), i.e. the nimbus or thunder-cloud cloud(-y).', 'from 6049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7198}/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["<the>/ rainbow","the/ bow"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3999}/[H2986]', 'inflected', 'heb', 'מַבּוּל', '["mabbûwl"]', '["<into>/ a flood","to the/ flood"]', '["n-m"]', 'a deluge flood.', 'from 2986 in the sense of flowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200G}/H9034/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ I will see/ it","and/ he saw/ her"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2142}/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["to/ bring to remembrance","to/ make remembrance","to/ remember"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3318G}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["<the>/ [one who] goes out","[is] the/ [thing which] is going forth","that/ is coming out","those/ [which] are going out","those/ [who] had gone out","whatever/ comes out","which/ came out","which/ goes forth","which/ goes out","which/ had come out","which/ has come out","which/ is going forth","which/ was coming out","which/ was going out","who/ came forth","who/ came out","who/ went out","who/ will come out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3667G}/[H3665]', 'lemma', 'heb', 'כְּנַעַן', '["Kᵉnaʻan"]', '["Canaan"]', '["n-pr-m n-pr-loc n-m"]', 'Kenaan, a son a Ham; also the country inhabited by him Canaan, merchant, traffick.', 'from 3665; humiliated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0428}/[H411]', 'inflected', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["and/ from/ these"]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5310B}/[H5310]', 'lemma', 'heb', 'נָפַץ', '["nâphats"]', '["<it> dispersed","it was scattered","they scatter"]', '["v"]', 'to dash to pieces, or scatter be beaten in sunder, break (in pieces), broken, dash (in pieces), cause to be discharged, dispersed, be overspread, scatter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2490C}/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["and/ he began","and/ it began","and/ she began","and/ they began","and/ they have begun"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3754>', 'opaque', 'heb', 'כֶּרֶם', '["kerem"]', '["[the] vineyard of","[the] vineyards","[the] vineyards of","a vineyard","a vineyard of","vineyard","vineyards","vineyards of"]', '["n-m"]', 'a garden or vineyard vines, (increase of the) vineyard(-s), vintage. See also 1021.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8354}/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["and/ I drank","and/ I will drink","and/ he drank","and/ he will drink","and/ it drank","and/ it will drink","and/ they drank","and/ they will drink","and/ you drank","and/ you will drink"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3196>', 'inflected', 'heb', 'היין', '["Hai./yain","hai./Ya.yin"]', '["<the>/ wine","the/ wine"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7937}/[H7937]', 'inflected', 'heb', 'שָׁכַר', '["shâkar"]', '["and/ I will make drunk","and/ he became drunk","and/ they became drunk"]', '["v"]', 'to become tipsy; in a qualified sense, to satiate with a stimulating drink or (figuratively) influence (be filled with) drink (abundantly), (be, make) drunk(-en), be merry. (Superlative of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1540I}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["and/ I will uncover","and/ he uncovered","and/ he uncovered himself","and/ he will uncover","and/ it was uncovered","and/ it will be uncovered","and/ she uncovered","and/ they were uncovered","and/ you will uncover"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0168G}/H9023/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["tent/ his","tent/ its"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6172}/[H6168]', 'lemma', 'heb', 'עֶרְוָה', '["ʻervâh"]', '["[is] [the] nakedness of","[the] nakedness of","nakedness"]', '["n-f"]', 'nudity, literally (especially the pudenda) or figuratively (disgrace, blemish) nakedness, shame, unclean(-ness).', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5046}/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["and/ I declared [them]","and/ I have told","and/ I tell","and/ I told","and/ I will tell","and/ he declared","and/ he reported","and/ he tells","and/ he told","and/ he told [it]","and/ he will tell","and/ it was told","and/ it will be told","and/ people told","and/ she told","and/ someone told","and/ they declared","and/ they told","and/ they will declare","and/ they will tell","and/ we told","and/ you will tell"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8147}/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["<into>/ [the] two","<into>/ two","<to>/ [the] two","[belonged] to/ [the] two","for/ [the] two","for/ [the] two [plus]","for/ two","for/ two [plus]","into/ two","into/ two [pieces]","into/ two [plus]","to/ [the] two","to/ two","to/ two [plus]"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2351>', 'inflected', 'heb', 'בחוצות', '["Ba./chutz","ba./Chutz","ba./chu.Tzot","be./chu.Tzot","va./Chutz"]', '["[is] in the/ street","[is] on the/ outside","[will be] in the/ streets","in the/ street","in the/ streets","in/ [the] streets of","on the/ outside"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8071}/[H5566]', 'inflected', 'heb', 'שִׂמְלָה', '["simlâh"]', '["the/ garment"]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7926}/[H7925]', 'lemma', 'heb', 'שְׁכֶם', '["shᵉkem"]', '["[the] shoulder of","a shoulder"]', '["n-m"]', 'the neck (between the shoulders) as the place of burdens; figuratively, the spur of a hill back, × consent, portion, shoulder.', 'from 7925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0322}/[H268]', 'lemma', 'heb', 'אֲחֹרַנִּית', '["ʼăchôrannîyth"]', '["[were] backwards","backwards"]', '["adv"]', 'backwards back (-ward, again).', 'prolonged from 268;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9028/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["[is] father/ their","ancestor/ their","ancestors/ their","father/ their","fathers/ their","parents/ their"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440H}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ faces/ their"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6172}/[H6168]', 'inflected', 'heb', 'עֶרְוָה', '["ʻervâh"]', '["and/ [the] nakedness of"]', '["n-f"]', 'nudity, literally (especially the pudenda) or figuratively (disgrace, blemish) nakedness, shame, unclean(-ness).', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3364}/[H3364]', 'inflected', 'heb', 'יָקַץ', '["yâqats"]', '["and/ I awoke","and/ he awoke"]', '["v"]', 'to awake (intransitive) (be) awake(-d).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3196>/H9023', 'inflected', 'heb', 'מיינו', '["mi./yei.N/o"]', '["from/ wine/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6996A}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["<the>/ little","<the>/ small","<the>/ young","[was] the/ young","the/ small","the/ young [one]"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5650}/[H5647]', 'lemma', 'heb', 'עֶבֶד', '["ʻebed"]', '["O servants of","[am] [the] servant of","[are] a servant","[are] servants","[are] slaves","[male] slaves","[the] servant of","[the] servants of","[was] [the] servant of","[were] servants","a [male] slave","a servant","a slave","a slave of","a subject","servant","servants","slave","slave of","slaves","subject","subjects"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251G}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["for/ brother/ his","of/ brothers/ his","to/ brother/ his","to/ brothers/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1288}/[H1288]', 'lemma', 'heb', 'בָּרַךְ', '["bârak"]', '["I will bless","O [one] blessed of","[are] blessed of","[be] blessed","[be] blessed of","[is] blessed","[one who] blesses","[surely] blessing","[those] blessed of","[whom] he has blessed","[will be] blessed","actually <bless>","at all <bless>","bless","blessed","certainly <bless>","continuously <to bless>","he blessed","he blesses","he had blessed","he has blessed","he will be blessed","he will bless","he will bless himself","it blesses","it will be blessed","it will bless","let us kneel","may he bless","really <bless>","she will be blessed","surely <bless>","they bless","they blessed","we bless","we will bless","you bless","you have blessed","you will bless"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6601A}/[H6601]', 'lemma', 'heb', 'פָּתָה', '["pâthâh"]', '["may he make spacious"]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3315}/[H6601]', 'inflected', 'heb', 'יֶפֶת', '["Yepheth"]', '["<to>/ Japheth"]', '["n-pr-m"]', 'Jepheth, a son of Noah; also his posterity Japheth.', 'from 6601; expansion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7931}/[H7901]', 'inflected', 'heb', 'שָׁכַן', '["shâkan"]', '["and/ I want to settle down","and/ [those who] dwell","and/ dwell","and/ let him dwell","so/ I may dwell","so/ let me cause to dwell","so/ they may dwell"]', '["v"]', 'to reside or permanently stay (literally or figuratively) abide, continue, (cause to, make to) dwell(-er), have habitation, inhabit, lay, place, (cause to) remain, rest, set (up).', 'a primitive root (apparently akin (by transmission) to 7901 through the idea of lodging; compare 5531, 7925);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0168G}/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["<in>/ [the] tent of","[is] in the/ tent","[is] in/ [the] tent of","[is] in/ [the] tents of","[were] in the/ tent","at the/ tent","at/ [the] tent of","in <the>/ tents","in the/ tent","in/ [the] tent of","in/ [the] tents of","in/ a tent","in/ tents"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2572}/[H2568]', 'inflected', 'heb', 'חֲמִשִּׁים', '["chămishshîym"]', '["and/ [was] fifty","and/ fifty"]', '["n"]', 'fifty fifty.', 'multiple of 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0428}/[H411]', 'inflected', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["and/ these","and/ these [children]","and/ these [men]","and/ these [things]","and/ these [tribes]"]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1586G}/[H1584]', 'lemma', 'heb', 'גֹּמֶר', '["Gômer"]', '["Gomer","[were] Gomer"]', '["n-pr-m n-pr-f"]', 'Gomer, the name of a son of Japheth and of his descendants; also of a Hebrewess Gomer.', 'from 1584; completion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4031G}/[H1463]', 'inflected', 'heb', 'מָגוֹג', '["Mâgôwg"]', '["and/ Magog"]', '["n-pr-m n-pr-loc"]', 'Magog, a son of Japheth; also a barbarous northern region Magog.', 'from 1463;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4074G}/[H4074]', 'inflected', 'heb', 'מָדַי', '["Mâday"]', '["and/ Madai"]', '["n-pr-m n-pr-loc"]', 'Madai, a country of central Asia Madai, Medes, Media.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3120G}/[H3196]', 'inflected', 'heb', 'יָוָן', '["Yâvân"]', '["and/ Javan"]', '["n-pr-m n-pr-loc"]', 'Javan, the name of a son of Joktan, and of the race (Ionians, i.e. Greeks) descended from him, with their territory; also of a place in Arabia Javan.', 'probably from the same as 3196; effervescing (i.e. hot and active);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8422G}/[H8422]', 'inflected', 'heb', 'תּוּבַל', '["Tûwbal"]', '["and/ Tubal"]', '["n-pr-m"]', 'Tubal, a postdiluvian patriarch and his posterity Tubal.', 'or תֻּבַל; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4902G}/[H4901]', 'inflected', 'heb', 'מֶשֶׁךְ', '["Meshek"]', '["and/ Meshech"]', '["n-pr-m"]', 'Meshek, a son of Japheth, and the people descended from him Mesech, Meshech.', 'the same in form as 4901, but probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8494}/[H8494]', 'inflected', 'heb', 'תִּירָס', '["Tîyrâç"]', '["and/ Tiras"]', '["n-pr-m"]', 'Tiras, a son of Japheth Tiras.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121A}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ [the] child of","and/ [the] children of","and/ [the] descendant of","and/ [the] descendants of","and/ [the] people of","and/ [the] son of","and/ [the] sons","and/ [the] sons of","and/ a child of","and/ a son","and/ a son of","and/ children","and/ children of","and/ sons","and/ sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0813G>', 'opaque', 'heb', 'אַשְׁכְּנַז', '["ʼAshkᵉnaz"]', '["Ashkenaz","[were] Ashkenaz"]', '["n-pr-m"]', 'Ashkenaz, a Japhethite, also his descendants Ashkenaz.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7384B>', 'inflected', 'heb', 'וריפת', '["ve./ri.Fat"]', '["and/ Riphath"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8425G}/[H8425]', 'inflected', 'heb', 'תּוֹגַרְמָה', '["Tôwgarmâh"]', '["and/ Togarmah"]', '["n-pr"]', 'Togarmah, a son of Gomer and his posterity Togarmah.', 'or תֹּגַרְמָה; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3120G}/[H3196]', 'lemma', 'heb', 'יָוָן', '["Yâvân"]', '["Javan"]', '["n-pr-m n-pr-loc"]', 'Javan, the name of a son of Joktan, and of the race (Ionians, i.e. Greeks) descended from him, with their territory; also of a place in Arabia Javan.', 'probably from the same as 3196; effervescing (i.e. hot and active);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0473G}/[H473]', 'lemma', 'heb', 'אֱלִישָׁה', '["ʼĔlîyshâh"]', '["[were] Elishah"]', '["n-pr-m"]', 'Elishah, a son of Javan Elishah.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8659G}/[H8658]', 'inflected', 'heb', 'תַּרְשִׁישׁ', '["Tarshîysh"]', '["and/ Tarshish"]', '["n-pr-m n-pr-loc"]', 'Tarshish, a place on the Mediterranean, hence, the ephithet of a merchant vessel (as if for or from that port); also the name of a Persian and of an Israelite Tarshish, Tharshish.', 'probably the same as 8658 (as the region of the stone, or the reverse);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3794G}/[H3794]', 'lemma', 'heb', 'כִּתִּי', '["Kittîy"]', '["Kittim"]', '["a"]', 'a Kittite or Cypriote; hence, an islander in general, i.e. the Greeks or Romans on the shores opposite Palestine Chittim, Kittim.', 'or כִּתִּיִּי; patrial from an unused name denoting Cyprus (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1721>', 'inflected', 'heb', 'ודדנים', '["ve./do.da.Nim"]', '["and/ Dodanim"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0428}/[H411]', 'inflected', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["for/ these [things]","from/ these","from/ these [things]","more than/ these","of/ these [things]"]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0339}/[H183]', 'lemma', 'heb', 'אִי', '["ʼîy"]', '["O islands","[the] coastland","[the] coastland of","[the] coastlands of","[the] coasts of","[the] islands of","islands"]', '["n-m"]', 'properly, a habitable spot (as desirable); dry land, a coast, an island country, isle, island.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1471A}/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["O/ nation","O/ nations","[are] the/ nations","[is] the/ nation","the/ nation","the/ nations"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0776G>/H9028', 'inflected', 'heb', 'בארצתם', '["be./''ar.Tza/m","be./''ar.tzo.Ta/m"]', '["[is] in/ land/ their","[was] in/ land/ their","in/ land/ their","in/ lands/ their","in/ own lands/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3956H}/H9023/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["to/ own language/ its"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1471A}/H9028/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["in/ nations/ their"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3568G>', 'opaque', 'heb', 'כּוּשׁ', '["Kûwsh"]', '["Cush","[were] Cush"]', '["n-pr-m n-pr-loc"]', 'Cush (or Ethiopia), the name of a son of Ham, and of his territory; also of an Israelite Chush, Cush, Ethiopia.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4714H}/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["and/ Mizraim"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
