INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3667G}/[H3665]', 'inflected', 'heb', 'כְּנַעַן', '["Kᵉnaʻan"]', '["and/ Canaan"]', '["n-pr-m n-pr-loc n-m"]', 'Kenaan, a son a Ham; also the country inhabited by him Canaan, merchant, traffick.', 'from 3665; humiliated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5434G>', 'opaque', 'heb', 'סְבָא', '["Çᵉbâʼ"]', '["Seba","[were] Seba"]', '["n-pr-m n-pr-loc"]', 'Seba, a son of Cush, and the country settled by him Seba.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2341H}/[H2342]', 'inflected', 'heb', 'חֲוִילָה', '["Chăvîylâh"]', '["and/ Havilah"]', '["n-pr-loc n-pr-m"]', 'Chavilah, the name of two or three eastern regions; also perhaps of two men Havilah.', 'probably from 2342; circular;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5454}/[H5454]', 'inflected', 'heb', 'סַבְתָּא', '["Çabtâʼ"]', '["and/ Sabta","and/ Sabtah"]', '["n-pr-m"]', 'Sabta or Sabtah, the name of a son of Cush, and the country occupied by his posterity Sabta, Sabtah.', 'or סַבְתָּה; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7484G}/[H7483]', 'inflected', 'heb', 'רַעְמָה', '["Raʻmâh"]', '["and/ Raamah"]', '["n-pr-m n-pr-loc"]', 'Ramah, the name of a grandson of Ham, and of a place (perhaps founded by him) Raamah.', 'the same as 7483;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5455}/[H5455]', 'inflected', 'heb', 'סַבְתְּכָא', '["Çabtᵉkâʼ"]', '["and/ Sabteca"]', '["n-pr-m"]', 'Sabteca, the name of a son of Cush, and the region settled by him Sabtecha, Sabtechah.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7484G}/[H7483]', 'lemma', 'heb', 'רַעְמָה', '["Raʻmâh"]', '["Raamah"]', '["n-pr-m n-pr-loc"]', 'Ramah, the name of a grandson of Ham, and of a place (perhaps founded by him) Raamah.', 'the same as 7483;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7614G>', 'opaque', 'heb', 'שְׁבָא', '["Shᵉbâʼ"]', '["Sabean[s]","Sheba","[were] Sheba"]', '["n-pr-m n-pr-loc"]', 'Sheba, the name of three early progenitors of tribes and of an Ethiopian district Sheba, Sabeans.', 'of foreign origin;');
