INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1961}/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["[is] to/ be","to/ be","to/ become","to/ belong"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1368}/[H1397]', 'lemma', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["<the> mighty [men] of","<the> warrior of","O mighty [man] of","O mighty [one]","O mighty [ones] of","[are] warriors","[is] a warrior","[is] mighty","[men] mighty","[the] mighty [men] of","[the] mighty [ones]","[the] mighty [ones] of","[the] warriors of","[was] [the] mighty [man] of","[was] a mighty [man] of","[were] mighty [men] of","[were] warriors","a mighty [man]","a mighty [man] of","a warrior","mighty","mighty [man] of","mighty [men] of","mighty of","warrior","warriors"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6718A}/[H6679]', 'lemma', 'heb', 'צַיִד', '["tsayid"]', '["hunted game of","hunting","wild game"]', '["n-m"]', 'the chase; also game (thus taken) × catcheth, food, × hunter, (that which he took in) hunting, venison, victuals.', 'from a form of 6679 and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H5248>', 'inflected', 'heb', 'כנמרד', '["ke./nim.Rod"]', '["like/ Nimrod"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7225G}/[H7218]', 'lemma', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["<the> first [fruit] of","[is the] beginning of","[is] [the] beginning of","[is] [the] first of","[is] first","[the] beginning","[the] beginning of","[the] choicest of","[the] first of","[was the] beginning of","[was the] first of","first [fruit]"]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4467}/H9023/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["kingdom/ his"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0894}/[H1101]', 'lemma', 'heb', 'בָּבֶל', '["Bâbel"]', '["Babel","Babylon","O Babylon"]', '["n-pr-loc"]', 'Babel (i.e. Babylon), including Babylonia and the Babylonian empire Babel, Babylon.', 'from 1101; confusion;');
