INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8152}/[H8152]', 'lemma', 'heb', 'שִׁנְעָר', '["Shinʻâr"]', '["Shinar"]', '["n-pr-loc"]', 'Shinar, a plain in Babylonia Shinar.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5210>', 'opaque', 'heb', 'נִינְוֵה', '["Nîynᵉvêh"]', '["Nineveh"]', '["n-pr-loc"]', 'Nineveh, the capital of Assyria Nineveh.', 'of foreign origin;');
