INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7449}/[H7448]', 'lemma', 'heb', 'רֶסֶן', '["Reçen"]', '["Resen"]', '["n-pr-loc"]', 'Resen, a place in Assyrian Resen.', 'the same as 7448;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3866G}/[H3865]', 'lemma', 'heb', 'לוּדִי', '["Lûwdîy"]', '["[the] Ludites"]', '["a"]', 'a Ludite or inhabitants of Lud (only in plural) Ludim. Lydians.', 'or לוּדִיִּי; patrial from 3865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6047}/[H6047]', 'lemma', 'heb', 'עֲנָמִים', '["ʻĂnâmîym"]', '["[the] Anamites"]', '["n"]', 'Anamim, a son of Mizraim and his descendants, with their country Anamim.', 'as if plural of some Egyptian word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3853}/[H3851]', 'lemma', 'heb', 'לְהָבִים', '["Lᵉhâbîym"]', '["[the] Lehabites"]', '["n-m"]', 'Lehabim, a son of Mizraim, and his descendants Lehabim.', 'plural of 3851; flames;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5320>', 'opaque', 'heb', 'נַפְתֻּחִים', '["Naphtuchîym"]', '["[the] Naphtuhites"]', '["n-pr-loc"]', 'Naphtuchim, an Egyptian tribe Naptuhim.', 'plural of foreign origin,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6625}/[H6624]', 'lemma', 'heb', 'פַּתְרֻסִי', '["Pathruçîy"]', '["[the] Pathrusites"]', '["a"]', 'a Pathrusite, or inhabitant of Pathros Pathrusim.', 'patrial from 6624;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3695}/[H3695]', 'lemma', 'heb', 'כַּסְלֻחִים', '["Kaçluchîym"]', '["[the] Casluhites"]', '["n"]', 'Casluchim, a people cognate to the Egyptians Casluhim.', 'a plural probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6430H}/[H6429]', 'lemma', 'heb', 'פְּלִשְׁתִּי', '["Pᵉlishtîy"]', '["[the] Philistines"]', '["a"]', 'a Pelishtite or inhabitant of Pelesheth Philistine.', 'patrial from 6429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3732}\/[H3731]', 'inflected', 'heb', 'כַּפְתֹּרִי', '["Kaphtôrîy"]', '["[the] Caphtorites"]', '["a"]', 'a Caphtorite (collectively) or native of Caphtor Caphthorim, Caphtorim(-s).', 'patrial from 3731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6721G}/[H6679]', 'lemma', 'heb', 'צִידוֹן', '["Tsîydôwn"]', '["Sidon"]', '["n-pr-loc"]', 'Tsidon, the name of a son of Canaan, and of a place in Palestine Sidon, Zidon.', 'or צִידֹן; from 6679 in the sense of catching fish; fishery;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1060}/H9023/[H1069]', 'inflected', 'heb', 'בְּכוֹר', '["bᵉkôwr"]', '["firstborn/ his"]', '["n-m"]', 'first-born; hence, chief eldest (son), firstborn(-ling).', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2845}/[H2865]', 'lemma', 'heb', 'חֵת', '["Chêth"]', '["Heth"]', '["n-pr-m"]', 'Cheth, an aboriginal Canaanite Heth.', 'from 2865; terror;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2983G}/[H2982]', 'inflected', 'heb', 'יְבוּסִי', '["Yᵉbûwçîy"]', '["the/ Jebusite","the/ Jebusite[s]"]', '["n-m"]', 'a Jebusite or inhabitant of Jebus Jebusite(-s).', 'patrial from 2982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0567}/[H559]', 'inflected', 'heb', 'אֱמֹרִי', '["ʼĔmôrîy"]', '["[was] <the>/ Amorite","the/ Amorite","the/ Amorite[s]","the/ Amorites"]', '["n-m"]', 'an Emorite, one of the Canaanitish tribes Amorite.', 'probably a patronymic from an unused name derived from 559 in the sense of publicity, i.e. prominence; thus, a mountaineer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1622>', 'inflected', 'heb', 'הגרגשי', '["ha./gir.ga.Shi"]', '["the/ Girgashite[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2340}/[H2333]', 'inflected', 'heb', 'חִוִּי', '["Chivvîy"]', '["the/ Hivite","the/ Hivite[s]"]', '["n-m"]', 'a Chivvite, one of the aboriginal tribes of Palestine Hivite.', 'perhaps from 2333; a villager;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6208}/[H6208]', 'inflected', 'heb', 'עַרְקִי', '["ʻArqîy"]', '["the/ Arkite[s]"]', '["a"]', 'an Arkite or inhabitant of Erek Arkite.', 'patrial from an unused name meaning a tush;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5513}/[H5513]', 'inflected', 'heb', 'סִינִי', '["Çîynîy"]', '["the/ Sinite[s]"]', '["a"]', 'a Sinite, or descendant of one of the sons of Canaan Sinite.', 'from an otherwise unknown name of a man;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0721}/[H719]', 'inflected', 'heb', 'אַרְוָדִי', '["ʼArvâdîy"]', '["the/ Arvadite[s]"]', '["a"]', 'an Arvadite or citizen of Arvad Arvadite.', 'patrial from 719;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6786}/[H6786]', 'inflected', 'heb', 'צְמָרִי', '["Tsᵉmârîy"]', '["the/ Zemarite[s]"]', '["a"]', 'a Tsemarite or branch of the Canaanites Zemarite.', 'patrial from an unused name of a place in Palestine;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2577}/[H2574]', 'inflected', 'heb', 'חֲמָתִי', '["Chămâthîy"]', '["the/ Hamathite[s]"]', '["n-m"]', 'a Chamathite or native of Chamath Hamathite.', 'patrial from 2574;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0310A}/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["and/ [was] after","and/ after","and/ behind"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6327A}/[H6327]', 'lemma', 'heb', 'פּוּץ', '["pûwts"]', '["I will scatter","[where] it scatters","be scattered","he scatters","it will scatter","may they be scattered","scatter","scattered","they have been scattered","they were scattered","they will be scattered","we should be scattered","you have been scattered","you have scattered"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4940}/[H8192]', 'lemma', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["O clans of","[are] [the] clans of","[the] clan","[the] clan of","[the] clans of","[the] family of","[were] [the] clans of","a clan","clan","clans","families","kinds"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3669A}/[H3667]', 'inflected', 'heb', 'כְּנַעַנִי', '["Kᵉnaʻanîy"]', '["the/ Canaanite","the/ Canaanite [woman]","the/ Canaanite[s]","the/ Canaanites"]', '["n-m"]', 'a Kenaanite or inhabitant of Kenaan; by implication, a pedlar (the Canaanites standing for their neighbors the Ishmaelites, who conducted mercantile caravans) Canaanite, merchant, trafficker.', 'patrial from 3667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366H}/[H1379]', 'lemma', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["[the] border of","[the] territory of","a territory of"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6721H}/[H6679]', 'inflected', 'heb', 'צִידוֹן', '["Tsîydôwn"]', '["from/ Sidon"]', '["n-pr-loc"]', 'Tsidon, the name of a son of Canaan, and of a place in Palestine Sidon, Zidon.', 'or צִידֹן; from 6679 in the sense of catching fish; fishery;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935I}/H9041/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["coming/ you","going/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1642}/H9011/[H1641]', 'inflected', 'heb', 'גְּרָר', '["Gᵉrâr"]', '["Gerar/ towards"]', '["n-pr-loc"]', 'Gerar, a Philistine city Gerar.', 'probably from 1641; a rolling country;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5804}/[H5794]', 'lemma', 'heb', 'עַזָּה', '["ʻAzzâh"]', '["Ayyah","Gaza"]', '["n-f"]', 'Azzah, a place in Palestine Azzah, Gaza.', 'feminine of 5794; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5467>/H9011', 'opaque', 'heb', 'סְדֹם', '["Çᵉdôm"]', '["Sodom/ towards"]', '["n-pr-loc"]', 'Sedom, a place near the Dead Sea Sodom.', 'from an unused root meaning to scorch; burnt (i.e. volcanic or bituminous) district;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6017}/[H6014]', 'inflected', 'heb', 'עֲמֹרָה', '["ʻĂmôrâh"]', '["and/ Gomorrah"]', '["n-pr-loc"]', 'Amorah, a place in Palestine Gomorrah.', 'from 6014; a (ruined) heap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0126}/[H127]', 'inflected', 'heb', 'אַדְמָה', '["ʼAdmâh"]', '["and/ Admah"]', '["n-pr-loc"]', 'Admah, a place near the Dead Sea Admah.', 'contracted for 127; earthy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6636}/[H6643]', 'inflected', 'heb', 'צְבֹאִים', '["Tsᵉbôʼîym"]', '["and/ Zeboiim"]', '["n-pr-loc"]', 'Tseboim or Tsebijim, a place in Palestine Zeboiim, Zeboim.', 'or (more correctly) צְבִיִּים; or צְבִיִּם; plural of 6643; gazelles;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3962>', 'opaque', 'heb', 'לֶשַׁע', '["Leshaʻ"]', '["Lasha"]', '["n-pr-loc"]', 'Lesha, a place probably East of the Jordan Lasha.', 'from an unused root thought to mean to break through; a boiling spring;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3956H}/H9028/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["to/ languages/ their"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1471A}/H9028\/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["in/ nations/ their"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8035}/[H8034]', 'inflected', 'heb', 'שֵׁם', '["Shêm"]', '["and/ to/ Shem"]', '["n-pr-m"]', 'Shem, a son of Noah (often includ. his posterity) Sem, Shem.', 'the same as 8034; name;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5677G}/[H5676]', 'lemma', 'heb', 'עֵבֵר', '["ʻÊbêr"]', '["Eber"]', '["n-pr-m"]', 'Eber, the name of two patriarchs and four Israelites Eber, Heber.', 'the same as 5676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251G}/[H251]', 'lemma', 'heb', 'אָח', '["ʼâch"]', '["[are] brothers","[did] a brother","[does] a brother","[is] a brother","[the] brother of","[the] brothers of","a brother","brother","brothers"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1419K}/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["<the>/ elder","<the>/ old","the/ old [one]"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5867C}/[H5956]', 'lemma', 'heb', 'עֵילָם', '["ʻÊylâm"]', '["Elam","[were] Elam"]', '["n-pr-m n-pr-loc"]', 'Elam, a son of Shem and his descendants, with their country; also of six Israelites Elam.', 'or עוֹלָם; (Ezra 10:2; Jeremiah 49:36), probably from 5956; hidden, i.e. distant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0804H}/[H833]', 'inflected', 'heb', 'אַשּׁוּר', '["ʼAshshûwr"]', '["and/ Asshur"]', '["n-pr-m n-pr-loc"]', 'Ashshur, the second son of Shem; also his descendants and the country occupied by them (i.e. Assyria), its region and its empire Asshur, Assur, Assyria, Assyrians. See 838.', 'or אַשֻּׁר; apparently from 833 (in the sense of successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0775>', 'inflected', 'heb', 'וארפכשד', '["ve./''ar.pakh.Shad"]', '["and/ Arphaxad"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3865}/[H3865]', 'inflected', 'heb', 'לוּד', '["Lûwd"]', '["and/ Lud"]', '["n-pr"]', 'Lud, the name of two nations Lud, Lydia.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0758G}/[H759]', 'inflected', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["and/ Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0758G}/[H759]', 'lemma', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5780G}/[H5779]', 'lemma', 'heb', 'עוּץ', '["ʻÛwts"]', '["[were] Uz"]', '["n-pr-m n-pr-loc"]', 'Uts, a son of Aram, also a Seirite, and the regions settled by them. Uz.', 'apparently from 5779; consultation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2343}/[H2342]', 'inflected', 'heb', 'חוּל', '["Chûwl"]', '["and/ Hul"]', '["n-pr-m"]', 'Chul, a son of Aram; also the region settled by him Hul.', 'from 2342; a circle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1666>', 'inflected', 'heb', 'וגתר', '["ve./Ge.ter"]', '["and/ Gether"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4851}/[H4851]', 'inflected', 'heb', 'מַשׁ', '["Mash"]', '["and/ Mash"]', '["n-pr-m"]', 'Mash, a son of Aram, and the people descended from him Mash.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7974}/[H7973]', 'lemma', 'heb', 'שֶׁלַח', '["Shelach"]', '["Shelah"]', '["n-pr-m"]', 'Shelach, a postdiluvian patriarch Salah, Shelah. Compare 7975.', 'the same as 7973;');
