INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3355}/[H6994]', 'lemma', 'heb', 'יׇקְטָן', '["Yoqṭân"]', '["Joktan","[was] Joktan"]', '["n-pr-m"]', 'Joktan, an Arabian patriarch Joktan.', 'from 6994; he will be made little;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3355}/[H6994]', 'inflected', 'heb', 'יׇקְטָן', '["Yoqṭân"]', '["and/ Joktan"]', '["n-pr-m"]', 'Joktan, an Arabian patriarch Joktan.', 'from 6994; he will be made little;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0486}/[H486]', 'lemma', 'heb', 'אַלְמוֹדָד', '["ʼAlmôwdâd"]', '["Almodad"]', '["n-pr-m"]', 'Almodad, a son of Joktan Almodad.', 'probably of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8026}/[H8025]', 'lemma', 'heb', 'שֶׁלֶף', '["sheleph"]', '["Sheleph"]', '["n-pr-m"]', 'Sheleph, a son of Jokthan Sheleph.', 'from 8025; extract;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2700}/[H2691]', 'lemma', 'heb', 'חֲצַרְמָוֶת', '["Chătsarmâveth"]', '["Hazarmaveth"]', '["n-pr-m"]', 'Chatsarmaveth, a place in Arabia Hazarmaveth.', 'from 2691 and 4194; village of death;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3392}/[H3391]', 'lemma', 'heb', 'יֶרַח', '["Yerach"]', '["Jerah"]', '["n-pr-m"]', 'Jerach, an Arabian patriarch Jerah.', 'the same as 3391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1913A}/[H1913]', 'lemma', 'heb', 'הֲדוֹרָם', '["Hădôwrâm"]', '["Hadoram"]', '["n-pr-m"]', 'Hadoram, a son of Joktan, and the tribe descended from him Hadoram.', 'or הֲדֹרָם; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0187G>', 'opaque', 'heb', 'אוּזָל', '["ʼÛwzâl"]', '["Uzal"]', '["n-pr-m"]', 'Uzal, a son of Joktan Uzal.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1853>', 'opaque', 'heb', 'דִּקְלָה', '["Diqlâh"]', '["Diklah"]', '["n-pr-m n-pr-loc"]', 'Diklah, a region of Arabia Diklah.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5745}/[H5745]', 'lemma', 'heb', 'עוֹבָל', '["ʻÔwbâl"]', '["Obal"]', '["n-pr-m"]', 'Obal, a son of Joktan Obal.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0039}/[H1]', 'lemma', 'heb', 'אֲבִימָאֵל', '["ʼĂbîymâʼêl"]', '["Abimael"]', '["n-pr-m"]', 'Abimael, a son of Joktan Abimael.', 'from 1 and an elsewhere unused (probably foreign) word; father of Mael (apparently some Arab tribe);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7614H>', 'opaque', 'heb', 'שְׁבָא', '["Shᵉbâʼ"]', '["Sheba"]', '["n-pr-m n-pr-loc"]', 'Sheba, the name of three early progenitors of tribes and of an Ethiopian district Sheba, Sabeans.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0211G>', 'opaque', 'heb', 'אוֹפִיר', '["ʼÔwphîyr"]', '["Ophir"]', '["n-pr-m"]', 'Ophir, the name of a son of Joktan, and of a gold region in the East Ophir.', 'or (shortened) אֹפִיר; and אוֹפִר; of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2341I}/[H2342]', 'lemma', 'heb', 'חֲוִילָה', '["Chăvîylâh"]', '["Havilah"]', '["n-pr-loc n-pr-m"]', 'Chavilah, the name of two or three eastern regions; also perhaps of two men Havilah.', 'probably from 2342; circular;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3103G}/[H2980]', 'lemma', 'heb', 'יוֹבָב', '["Yôwbâb"]', '["Jobab"]', '["n-pr-m"]', 'Jobab, the name of two Israelites and of three foreigners Jobab.', 'from 2980; howler;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4186}/H9028/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["[was] dwelling places/ their","[were] dwelling places/ their","dwelling place/ their","dwelling places/ their"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4852}/[H4852]', 'inflected', 'heb', 'מֵשָׁא', '["Mêshâʼ"]', '["from/ Mesha"]', '["n-pr-loc"]', 'Mesha, a place in Arabia Mesha.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5611}/H9011/[H5610]', 'inflected', 'heb', 'סְפָר', '["Çᵉphâr"]', '["Sephar/ towards"]', '["n-pr-loc"]', 'Sephar, a place in Arabia Sephar.', 'the same as 5610;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2022H}/[H2042]', 'lemma', 'heb', 'הַר', '["har"]', '["[the] hill country","[the] hill country of","[the] mountain of"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6924G}/[H6923]', 'inflected', 'heb', 'קֶדֶם', '["qedem"]', '["the/ east"]', '["n-m adv"]', 'the front, of place (absolutely, the fore part, relatively the East) or time (antiquity); often used adverbially (before, anciently, eastward) aforetime, ancient (time), before, east (end, part, side, -ward), eternal, × ever(-lasting), forward, old, past. Compare 6926.', 'or קֵדְמָה; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1471A}/H9028/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["to/ nations/ their"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8435}/H9028/[H3205]', 'inflected', 'heb', 'תּוֹלְדָה', '["tôwlᵉdâh"]', '["to/ descendants/ their","to/ generations/ their"]', '["n-f"]', '(plural only) descent, i.e. family; (figuratively) history birth, generations.', 'or תֹּלְדָה; from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3999}\/[H2986]', 'inflected', 'heb', 'מַבּוּל', '["mabbûwl"]', '["the/ flood"]', '["n-m"]', 'a deluge flood.', 'from 2986 in the sense of flowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193K}/[H5595]', 'lemma', 'heb', 'שָׂפָה', '["sâphâh"]', '["[the] language of","a language","language"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1697G}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ [is] a word","and/ [the] word of","and/ a word","and/ a word of","and/ word","and/ words","and/ words of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5265}/H9048/[H5265]', 'inflected', 'heb', 'נָסַע', '["nâçaʻ"]', '["when/ set out/ they"]', '["v"]', 'properly, to pull up, especially the tent-pins, i.e. start on a journey cause to blow, bring, get, (make to) go (away, forth, forward, onward, out), (take) journey, march, remove, set aside (forward), × still, be on his (go their) way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4672}/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["and/ I found","and/ I will let myself be found","and/ he found","and/ he let himself be found","and/ he will be found","and/ he will find","and/ it has found","and/ it was found","and/ it will find","and/ someone found","and/ someone will find","and/ they brought forward","and/ they found","and/ they were found","and/ they will be found","and/ they will find","and/ you found","and/ you will find","and/ you will find [him]","and/ you will find [it] out","and/ you will find [me]"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1237K}/[H1234]', 'lemma', 'heb', 'בִּקְעָה', '["biqʻâh"]', '["a plain","valleys"]', '["n-f"]', 'properly, a split, i.e. a wide level valley between mountains plain, valley.', 'from 1234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7453}/H9023/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["<of> neighbor/ his","[is] friend/ his","companion/ his","companion/ its","companions/ his","friend/ his","friends/ his","neighbor [masc]/ his","neighbor/ his","neighbor/ its"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3051}/H9012/[H3051]', 'inflected', 'heb', 'יָהַב', '["yâhab"]', '["give/ !"]', '["v"]', 'to give (whether literal or figurative); generally, to put; imperatively (reflexive) come ascribe, bring, come on, give, go, set, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3835B}/[H3843]', 'lemma', 'heb', 'לָבַן', '["lâban"]', '["let us make bricks"]', '["v"]', 'to be (or become) white; to make bricks make brick, be (made, make) white(-r).', 'a primitive root; also as denominative from 3843');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3843}/[H3835]', 'lemma', 'heb', 'לְבֵנָה', '["lᵉbênâh"]', '["<the> pavement of","a brick","bricks"]', '["n-f"]', 'a brick (from the whiteness of the clay) (altar of) brick, tile.', 'from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8313}/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["and/ let us burn [them]","so/ she may be burned"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8316}/[H8313]', 'inflected', 'heb', 'שְׂרֵפָה', '["sᵉrêphâh"]', '["<into>/ a burning of","for/ burning","to/ burning"]', '["n-f"]', 'cremation burning.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3843}/[H3835]', 'inflected', 'heb', 'לְבֵנָה', '["lᵉbênâh"]', '["<the>/ brick","the/ bricks"]', '["n-f"]', 'a brick (from the whiteness of the clay) (altar of) brick, tile.', 'from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0068G}/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["<into>/ stone","<to> the/ stones","<to>/ stones of","to/ a stone of","to/ stone"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2564}/[H2560]', 'inflected', 'heb', 'חֵמָר', '["chêmâr"]', '["and/ <the>/ bitumen"]', '["n-m"]', 'bitumen (as rising to the surface) slime(-pit).', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2563A}/[H2560]', 'inflected', 'heb', 'חֹמֶר', '["chômer"]', '["to <the>/ mortar","to the/ mud"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9035}', 'inflected', 'arc', 'לנו', '["La./na''","La./nu","l/nu","la./Nu","la./nu"]', '["<for>/ ourselves","<to> <the>/ us","<to>/ us","[belong] to <the>/ us","[belong] to/ us","[belonging] to <the>/ us","[belongs] to <the>/ us","[belongs] to/ us","[will belong] to <the>/ us","by/ us","for <the>/ ourselves","for <the>/ us","for/ ourselves","for/ us","of/ us","to <the>/ us","to/ us"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4026M}/[H1431]', 'inflected', 'heb', 'מִגְדָּל', '["migdâl"]', '["and/ a tower","and/ a tower of","and/ towers"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7218I>/H9023', 'inflected', 'heb', 'וראשו', '["ve./ro.Sh/o"]', '["and/ top/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8064>', 'inflected', 'heb', 'בשמים', '["Ba./sha.ma.yim","ba./sha.Ma.yim","ba./sha.ma.Yim","bi/sh.Mei","va./sha.Ma.yim"]', '["[is] in the/ heavens","[will be] in the/ heavens","in the/ heavens","in/ [the] heavens of","on the/ heavens"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6213H}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ I may make","and/ [it was] done","and/ [was] made","and/ [who] makes","and/ [women who] make","and/ let us make","and/ make","and/ make [them]","and/ people will make","and/ prepare","and/ prepare [it]","and/ they made","and/ they may make","and/ we may make","so/ I may make","so/ I may prepare"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3381}/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["and/ I came down","and/ I have come down","and/ I went down","and/ I will bring down","and/ I will come down","and/ I will go down","and/ has he come down?","and/ he brought down","and/ he came down","and/ he made to flow down","and/ he went down","and/ he will bring down","and/ he will come down","and/ it came down","and/ it goes down","and/ it was taken down","and/ it will be brought down","and/ it will come down","and/ it will go down","and/ she came down","and/ she has come down","and/ she let down","and/ she put down","and/ she went down","and/ they brought [it] down","and/ they brought down","and/ they came down","and/ they took down","and/ they went down","and/ they will bring down","and/ they will come down","and/ they will go down","and/ they will take down","and/ we have come down","and/ we will go down","and/ you will be brought down","and/ you will bring down","and/ you will cause to go down","and/ you will go down","and/ you will take down"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4026M}/[H1431]', 'inflected', 'heb', 'מִגְדָּל', '["migdâl"]', '["the/ tower","the/ towers"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971A}/[H6004]', 'lemma', 'heb', 'עַם', '["ʻam"]', '["O people","O people of","O peoples","[am] a people","[are the] people","[are] [the] people of","[are] a people","[is] a people","[is] a people of","[the] people","[the] people of","[the] peoples","[the] peoples of","[was] a people","a people","a people of","people","peoples"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8193K}/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["and/ a language"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3605}/H9028/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["<to>/ all of/ them","[belongs] to/ all of/ them","of/ all of/ them","to/ all of/ them"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2490C}/H9048/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["[is] beginning/ they"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6213A}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["[is] to/ do","by/ celebrating","by/ doing","by/ making","by/ observing","for the/ [one who] acts","to/ [one who] does","to/ [the] doer of","to/ [the] doers of","to/ act","to/ be done","to/ celebrate","to/ do","to/ do [it]","to/ execute","to/ observe","to/ observe [them]","to/ produce","to/ work"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1219}/[H1210]', 'lemma', 'heb', 'בָּצַר', '["bâtsar"]', '["[are] fortified","fortified","grape gatherers","he humbles","it is withheld","it will be withheld","it will fortify","you will gather grapes"]', '["v"]', 'to gather grapes; also to be isolated (i.e. inaccessible by height or fortification) cut off, (de-) fenced, fortify, (grape) gather(-er), mighty things, restrain, strong, wall (up), withhold.', 'a primitive root; to clip off; specifically (as denominative from 1210)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H9038}', 'inflected', 'heb', 'מהמה', '["me./He.mah","me./Hem"]', '["[were] some of <the>/ them","any of <the>/ them","any of/ them","for/ them","from <the>/ them","from/ them","more than/ them","of <the>/ them","of/ them","some of <the>/ them","some of/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2161}/[H2161]', 'lemma', 'heb', 'זָמַם', '["zâmam"]', '["I have planned","I have resolved","I planned","[is] plotting","he has purposed","he planned","he purposed","she considers","they plotted","they will plan","you have plotted"]', '["v"]', 'to plan, usually in a bad sense consider, devise, imagine, plot, purpose, think (evil).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3381}/[H3381]', 'lemma', 'heb', 'יָרַד', '["yârad"]', '["I went down","I will go down","O [those who] go down","[am] about to come down","[are] coming down","[are] going down","[he is] bringing down","[is] coming down","[is] going down","[one who] has gone down","[those who are] about to go down of","[those who] go down","[those who] go down of","[those who] have gone down of","[those who] went down","[was] coming down","[were] going down","[which] go down","[who] go down","bring down","certainly <to come down>","come down","coming down","go down","going down","have you come down","have you gone down","he came down","he had been brought down","he had come down","he had gone down","he has gone down","he took down","he went down","he will come down","he will go down","it came down","it comes down","it goes down","it had gone down","it has been brought down","it has come down","it went down","it will come down","it will go down","let it come down","let them go down","let them run down","let us go down","may they go down","running down","send down","take down","they brought down","they came down","they go down","they have brought down","they have come down","they have gone down","they went down","they will bring [them] down","they will come down","they will go down","they will take down","we came down","we have brought down","we have come down","we will go down","will he go down","will they go down?","you came down","you go down","you have been brought down","you have come down","you must bring down","you will come down","you will go down"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1101A}/[H1098]', 'inflected', 'heb', 'בָּלַל', '["bâlal"]', '["and/ let us confuse"]', '["v"]', 'to overflow (specifically with oil.); by implication, to mix; to fodder anoint, confound, × fade, mingle, mix (self), give provender, temper.', 'a primitive root; (also denominatively from 1098) to fodder');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193K}/H9028/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["language/ their"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085J}/[H8085]', 'lemma', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["[are] understanding","[was] hearing","[which] listens","they will hear","you hear","you will understand"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193H}/[H5595]', 'lemma', 'heb', 'שָׂפָה', '["sâphâh"]', '["[the] language of","a lip","a lip of","lip","lips","lips of"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6327A}/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["and/ I scattered","and/ I will scatter","and/ does he scatter","and/ he scattered","and/ he will scatter","and/ it scattered","and/ they have been scattered","and/ they have been shattered","and/ they were scattered","and/ will they be scattered"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2308}/[H2308]', 'inflected', 'heb', 'חָדַל', '["châdal"]', '["and/ he ceased","and/ he refrained","and/ he will cease","and/ she ceased","and/ they ceased","and/ you will refrain"]', '["v"]', 'properly, to be flabby, i.e. (by implication) desist; (figuratively) be lacking or idle cease, end, fall, forbear, forsake, leave (off), let alone, rest, be unoccupied, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1129}/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["by/ building","to/ be rebuilt","to/ build","to/ build up","to/ rebuild"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8034}/H9024/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["[is] name/ its","name/ her","name/ its"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1101A}/[H1098]', 'lemma', 'heb', 'בָּלַל', '["bâlal"]', '["I have been anointed","he confused","he mixes himself","mixed"]', '["v"]', 'to overflow (specifically with oil.); by implication, to mix; to fodder anoint, confound, × fade, mingle, mix (self), give provender, temper.', 'a primitive root; (also denominatively from 1098) to fodder');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6327A}/H9038/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["I have scattered/ them","I will scatter/ them","he scattered/ them"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0775>', 'opaque', 'heb', 'אַרְפַּכְשַׁד', '["ʼArpakshad"]', '["Arphaxad"]', '["n-pr-m"]', 'Arpakshad, a son of Noah; also the region settled by him Arphaxad.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1323G}\/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ daughters"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0702}/[H7251]', 'inflected', 'heb', 'אַרְבַּע', '["ʼarbaʻ"]', '["and/ [the] four","and/ [was] four","and/ four","and/ four [things]"]', '["n"]', 'four four.', 'masculine אַרְבָּעָה; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0702}/[H7251]', 'lemma', 'heb', 'אַרְבַּע', '["ʼarbaʻ"]', '["[are] [the] four","[are] four","[is] four","[is] four-","[the] four","[the] four-","[was] four","[was] four-","[were] four","[will be] four","four","four [feet]","four [horns]","four [legs]","four [things]","four of","four-"]', '["n"]', 'four four.', 'masculine אַרְבָּעָה; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7466}/[H7471]', 'lemma', 'heb', 'רְעוּ', '["Rᵉʻûw"]', '["Reu"]', '["n-pr-m"]', 'Reu, a postdiluvian patriarch Reu.', 'for 7471 in the sense of 7453; friend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8286}/[H8276]', 'lemma', 'heb', 'שְׂרוּג', '["Sᵉrûwg"]', '["Serug"]', '["n-pr-m"]', 'Serug, a postdiluvian patriarch Serug.', 'from 8276; tendril;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5152G}/[H5170]', 'lemma', 'heb', 'נָחוֹר', '["Nâchôwr"]', '["Nahor"]', '["n-pr-m"]', 'Nachor, the name of the grandfather and a brother of Abraham Nahor.', 'from the same as 5170; snorer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8646G>', 'opaque', 'heb', 'תֶּרַח', '["Terach"]', '["Terah"]', '["n-pr-m n-pr-loc"]', 'Terach, the father of Abraham; also a place in the Desert Tarah, Terah.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0087}/[H48]', 'lemma', 'heb', 'אַבְרָם', '["ʼAbrâm"]', '["Abram","O Abram"]', '["n-pr-m"]', 'Abram, the original name of Abraham Abram.', 'contracted from 48; high father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5152H}/[H5170]', 'lemma', 'heb', 'נָחוֹר', '["Nâchôwr"]', '["Nahor"]', '["n-pr-m"]', 'Nachor, the name of the grandfather and a brother of Abraham Nahor.', 'from the same as 5170; snorer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2039G}/[H2022]', 'lemma', 'heb', 'הָרָן', '["Hârân"]', '["Haran"]', '["n-pr-m n-pr-loc"]', 'Haran, the name of two men Haran.', 'perhaps from 2022; mountaineer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2039G}/[H2022]', 'inflected', 'heb', 'הָרָן', '["Hârân"]', '["and/ Haran"]', '["n-pr-m n-pr-loc"]', 'Haran, the name of two men Haran.', 'perhaps from 2022; mountaineer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3876}/[H3875]', 'lemma', 'heb', 'לוֹט', '["Lôwṭ"]', '["Lot"]', '["n-pr-m"]', 'Lot, Abraham''s nephew Lot.', 'the same as 3875;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4191}/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ I will die","and/ I will put to death","and/ he caused to die","and/ he died","and/ he had died","and/ he has died","and/ he killed","and/ he put to death","and/ he will be put to death","and/ he will die","and/ it died","and/ it will die","and/ it will kill","and/ she died","and/ she was put to death","and/ she will die","and/ they died","and/ they have died","and/ they killed","and/ they will die","and/ we will die","and/ you will die","and/ you will kill","and/ you will put to death"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440H}/[H6437]', 'lemma', 'heb', 'פָּנִים', '["pânîym"]', '["<of> [the] face of","[the] face","[the] face of","[the] faces of","[the] presence of","[the] surface of","[was the] face of","[was] [the] face of","[will be] faces of","a face","face","faces","of face"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4138}/H9023/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["kindred/ his"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0218B}/[H217]', 'inflected', 'heb', 'אוּר', '["ʼÛwr"]', '["in/ Ur"]', '["n-pr-m n-pr-loc"]', 'Ur, a place in Chaldaea; also an Israelite Ur.', 'the same as 217;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3778}/[H3777]', 'lemma', 'heb', 'כַּשְׂדִּי', '["Kasdîy"]', '["Chaldea","[the] Chaldeans","of [the] Chaldeans"]', '["n-pr-loc n-pr-m"]', 'a Kasdite, or descendant of Kesed; by implication, a Chaldaean (as if so descended); also an astrologer (as if proverbial of that people Chaldeans, Chaldees, inhabitants of Chaldea.', '(occasionally with enclitic) כַּשְׂדִּימָה; towards the Kasdites into Chaldea), patronymically from 3777 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5152H}/[H5170]', 'inflected', 'heb', 'נָחוֹר', '["Nâchôwr"]', '["and/ Nahor"]', '["n-pr-m"]', 'Nachor, the name of the grandfather and a brother of Abraham Nahor.', 'from the same as 5170; snorer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8297}/[H8269]', 'lemma', 'heb', 'שָׂרַי', '["Sâray"]', '["Sarai","[was] Sarai"]', '["n-pr-f"]', 'Sarai, the wife of Abraham Sarai.', 'from 8269; dominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4435G}/[H4436]', 'lemma', 'heb', 'מִלְכָּה', '["Milkâh"]', '["Milcah","[was] Milcah"]', '["n-pr-f"]', 'Milcah, the name of a Hebrewess and of an Israelite Milcah.', 'a form of 4436; queen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0001G}/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ [the] ancestors of","and/ [the] father of","and/ a parent"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3252>', 'opaque', 'heb', 'יִסְכָּה', '["Yiçkâh"]', '["Iscah"]', '["n-pr-f"]', 'Jiskah, sister of Lot Iscah.', 'from an unused root meaning to watch; observant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6135}/[H6131]', 'lemma', 'heb', 'עָקָר', '["ʻâqâr"]', '["O barren [woman]","[are] barren","[the] barren [woman] of","[was] barren","a barren [woman]","a sterile [male]","barren"]', '["a"]', 'sterile (as if extirpated in the generative organs) (× male or female) barren (woman).', 'from 6131;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9034}', 'inflected', 'arc', 'לה', '["La/h","la/h","le/h"]', '["<for>/ itself","<to> <the>/ her","<to> <the>/ it","<to>/ her","<to>/ it","[belong] to/ her","[belonged] to <the>/ her","[belonged] to/ her","[belonged] to/ it","[belonging] to/ it","[belongs] to <the>/ her","[belongs] to/ her","[belongs] to/ it","[were] to/ it","by <the>/ her","by/ her","for <the>/ her","for <the>/ herself","for <the>/ it","for/ her","for/ herself","for/ it","for/ itself","of <the>/ her","of <the>/ it","of/ her","of/ it","to <the>/ her","to <the>/ herself","to <the>/ it","to/ her","to/ him","to/ it","to/ itself"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2056}/[H3206]', 'lemma', 'heb', 'וָלָד', '["vâlâd"]', '["a child"]', '["n-m"]', 'a boy child.', 'for 3206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3618H}/H9023/[H3634]', 'inflected', 'heb', 'כַּלָּה', '["kallâh"]', '["[was] daughter-in-law/ his","daughter-in-law/ his"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0218B}/[H217]', 'inflected', 'heb', 'אוּר', '["ʼÛwr"]', '["from/ Ur"]', '["n-pr-m n-pr-loc"]', 'Ur, a place in Chaldaea; also an Israelite Ur.', 'the same as 217;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1980G}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["[about] to/ go","by/ going","for/ one [who] is about to go away","to/ go","to/ walk"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776G>/H9011', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["[the] earth/ towards","[the] ground/ towards","[the] land of/ <towards>","[the] land of/ towards"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3667A}/[H3665]', 'lemma', 'heb', 'כְּנַעַן', '["Kᵉnaʻan"]', '["Canaan","O Canaan"]', '["n-pr-m n-pr-loc n-m"]', 'Kenaan, a son a Ham; also the country inhabited by him Canaan, merchant, traffick.', 'from 3665; humiliated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2771A}/[H2787]', 'lemma', 'heb', 'חָרָן', '["Chârân"]', '["Haran"]', '["n-pr-m n-pr-loc"]', 'Charan, the name of a man and also of a place Haran.', 'from 2787; parched;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2771A}\/[H2787]', 'inflected', 'heb', 'חָרָן', '["Chârân"]', '["in/ Haran"]', '["n-pr-m n-pr-loc"]', 'Charan, the name of a man and also of a place Haran.', 'from 2787; parched;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0776G>/H9021', 'inflected', 'heb', 'מארצך', '["me./''ar.tze./Kha"]', '["from/ land/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4138}/H9021/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["and/ from/ kindred/ your"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1004M}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ from/ [the] household of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9021/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["ancestor/ your","ancestors/ your","father/ your","fathers/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200G}/H9031/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["I have let see [it]/ you","I have seen/ you","I will see/ you","I will show/ you","[those who] saw/ you","[those who] see/ you","he showed/ you","it has seen/ you","they have seen/ you","they saw/ you","to show/ you"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6213H}/H9031/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["so/ I may make/ you"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1471A}/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["<into>/ a nation","<into>/ nations","<to> the/ nations","for the/ nations","for/ nations","into/ a nation","into/ nations","to the/ nation","to the/ nations"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1288}/H9031/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["and/ I will bless/ you","and/ [those who] bless/ you","and/ he will bless/ you","so/ I may bless/ you"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1431}/[H1434]', 'inflected', 'heb', 'גָּדַל', '["gâdal"]', '["and/ I will make great","and/ becoming great","and/ he may magnify himself","and/ it may be great","and/ may he make great","so/ it may be great"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8034}/H9021/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["<of> name/ your","[is] name/ your","name/ your"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1293}/[H1288]', 'lemma', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["[the] blessing of","[the] blessings of","a blessing","blessing","blessing of","blessings","blessings of"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1288}/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["and/ I will bless","and/ [be] blessed","and/ [it is] blessed","and/ [will be] blessed","and/ bless","and/ he has blessed","and/ may he bless","and/ may people bless","and/ may they bless themselves","so/ it may bless","so/ let me bless"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1288}/H9031/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["I will bless/ you","[those who] bless/ you","he has blessed/ you","he may bless/ you","he will bless/ you","it may bless/ you","may he bless/ you","they will bless/ you"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7043}/H9031/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["and/ [one who] disdains/ you"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9031}', 'inflected', 'arc', 'בכה', '["Ba/kh","Be./kha","Va/kh","Ve./kha","be./Kha","be./Khah","be./kha","bo/Kh","va/kh","ve./Kha","ve./Khah","ve./kha"]', '["<in> <the>/ you","<in>/ you","[is] in <the>/ you","[is] in/ you","against <the>/ you","against/ you","among <the>/ you","among/ you","by <the>/ you","by <the>/ yourself","by/ you","in <the>/ you","in/ you","on <the>/ you","on/ you","to/ you","with <the>/ you","with/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0127I}/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["the/ earth","the/ ground","the/ land"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1980G}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ I have gone","and/ I went","and/ I will go","and/ he came","and/ he had gone","and/ he has gone","and/ he walked","and/ he went","and/ he went about","and/ he will go","and/ it goes","and/ it has gone","and/ it went","and/ it will go","and/ people went","and/ she went","and/ she will go","and/ they dispersed","and/ they had gone","and/ they have gone","and/ they have gone away","and/ they have walked","and/ they went","and/ they went about","and/ they will go","and/ we will go","and/ will I go","and/ you have gone","and/ you will come","and/ you will go","and/ you will walk"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1696G}/[H1696]', 'lemma', 'heb', 'דָבַר', '["dâbar"]', '["<of> [when] he spoke","I had spoken","I have spoken","I said","I speak","I spoke","I will say","I will speak","[am] about to speak","[am] speaking","[anyone was] speaking","[are] speaking","[is] saying","[is] speaking","[is] spoken","[one who] speaks","[one who] spoke","[those who] speak","[was] speaking","[were] speaking","[when] I spoke","[when] he spoke","[which] speaks","[who] speak","[who] speaks","[will be] speaking","are you speaking","did I speak","did he say","did you say","does he speak","does it say","has he spoken","have they said","have we spoken together","have you spoken","he had said","he had spoken","he has spoken","he said","he says","he speak","he speaks","he spoke","he will say","he will speak","it has spoken","it speaks","it will speak","let her speak","let him speak","let me speak","let them speak","may he speak","may you speak","people speak","saying","she spoke","someone speaks","speak","speaking","spoken","surely <speak>","they had spoken","they have spoken","they speak","they speak together","they spoke","they spoke together","they will speak","to speak","we have spoken","we spoke","we will speak","well <speak>","will I say","will I speak","will he speak","will it speak","will they speak","will we speak","will you speak","will you speak?","you are speaking","you had spoken","you have said","you have spoken","you must speak","you said","you should speak","you speak","you spoke","you will say","you will speak"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0087}/[H48]', 'inflected', 'heb', 'אַבְרָם', '["ʼAbrâm"]', '["and/ Abram"]', '["n-pr-m"]', 'Abram, the original name of Abraham Abram.', 'contracted from 48; high father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3318G}/H9043/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ came out/ he","when/ goes out/ he","when/ went out/ he"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2771A}/[H2787]', 'inflected', 'heb', 'חָרָן', '["Chârân"]', '["[are] from/ Haran","from/ Haran"]', '["n-pr-m n-pr-loc"]', 'Charan, the name of a man and also of a place Haran.', 'from 2787; parched;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7399}/H9028/[H7408]', 'inflected', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["possession[s]/ their"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7408}/[H7408]', 'lemma', 'heb', 'רָכַשׁ', '["râkash"]', '["he had accumulated","they had accumulated"]', '["v"]', 'to lay up, i.e. collect gather, get.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5315J}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["<the>/ person","the/ people","the/ person","the/ person[s]","the/ persons"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213I}/[H6213]', 'lemma', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["<of> [which] he acquired","I acquired","I do","[one who] makes","[which] it has made","[which] they made","[who] have acquired","[will be] doing","has it been done","he had done","he has acquired","he has done","he made","he offered","he will offer","he will provide","it has acquired","it will be offered","make","offering","producing of","she made","they had acquired","they make","they will offer","will I work","you do","you have done","you will do","you will make","you will observe","you will offer","you will offer [it]","you will offer [them]"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2771A}/[H2787]', 'inflected', 'heb', 'חָרָן', '["Chârân"]', '["in/ Haran"]', '["n-pr-m n-pr-loc"]', 'Charan, the name of a man and also of a place Haran.', 'from 2787; parched;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7927G}/[H7926]', 'lemma', 'heb', 'שְׁכֶם', '["Shᵉkem"]', '["Shechem","[is] Shechem"]', '["n-pr-m n-pr-loc"]', 'Shekem, a place in Palestine Shechem.', 'the same as 7926; ridge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0436H}/[H352]', 'lemma', 'heb', 'אֵלוֹן', '["ʼêlôwn"]', '["[the] great tree","[the] great tree of","[the] great trees of"]', '["n-m"]', 'an oak or other strong tree plain. See also 356.', 'prolonged from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4176G}/[H4175]', 'lemma', 'heb', 'מוֹרֶה', '["Môwreh"]', '["Moreh"]', '["n-m"]', 'Moreh, a Canaanite; also a hill (perhaps named from him) Moreh.', 'or מֹרֶה; the same as 4175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3669A}/[H3667]', 'inflected', 'heb', 'כְּנַעַנִי', '["Kᵉnaʻanîy"]', '["and/ the/ Canaanite[s]"]', '["n-m"]', 'a Kenaanite or inhabitant of Kenaan; by implication, a pedlar (the Canaanites standing for their neighbors the Ishmaelites, who conducted mercantile caravans) Canaanite, merchant, trafficker.', 'patrial from 3667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2233H}/H9021/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["to/ offspring/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2063}/[H2088]', 'inflected', 'heb', 'זֹאת', '["zôʼth"]', '["<the>/ this"]', '["d"]', 'this (often used adverb) hereby (-in, -with), it, likewise, the one (other, same), she, so (much), such (deed), that, therefore, these, this (thing), thus.', 'irregular feminine of 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7200G}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["<the>/ [one who] saw","[are] the/ [ones which] have seen","[are] the/ [ones which] saw","the/ [one who] sees","the/ [one] which it appeared","the/ [women who] look","who/ <he> had appeared","who/ appeared","who/ had appeared","who/ saw","who/ were looking"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6275}/[H6275]', 'inflected', 'heb', 'עָתַק', '["ʻâthaq"]', '["and/ he moved on"]', '["v"]', 'to remove (intransitive or transitive) figuratively, to grow old; specifically, to transcribe copy out, leave off, become (wax) old, remove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2022H}/H9011/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["the/ hill country/ towards"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1008G}/[H1004]', 'inflected', 'heb', 'בֵּית־אֵל', '["Bêyth-ʼÊl"]', '["[will belong] to/ Beth-","of/ Beth-","to/ Beth-"]', '["n-pr-loc"]', 'Beth-El, a place in Palestine Beth-el.', 'from 1004 and 410; house of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1008G}/[H1004]', 'lemma', 'heb', 'בֵּית־אֵל', '["Bêyth-ʼÊl"]', '["-el","Beth-","O Beth-","[is] Beth-","[were at] Beth-","[were] Beth-"]', '["n-pr-loc"]', 'Beth-El, a place in Palestine Beth-el.', 'from 1004 and 410; house of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5186}/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["and/ I have stretched out","and/ I will stretch out","and/ he bent down","and/ he bowed","and/ he extended","and/ he had pitched","and/ he has extended","and/ he has stretched out","and/ he pitched","and/ he stretched out","and/ he turned","and/ he turned aside","and/ he will spread out","and/ he will stretch out","and/ it had turned aside","and/ it turned aside","and/ they have turned aside","and/ they pitched","and/ they turned aside"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3220H>', 'inflected', 'heb', 'מים', '["mi./Yam"]', '["[was] from/ [the] west","from/ [the] west"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5857G}/[H5856]', 'inflected', 'heb', 'עַי', '["ʻAy"]', '["and/ <the>/ Ai"]', '["n-pr-loc"]', 'Ai, Aja or Ajath, a place in Palestine Ai, Aija, Aijath, Hai.', 'or (feminine) עַיָּא; (Nehemiah 11:31), or עַיָּת; (Isaiah 10:28), for 5856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5265}/[H5265]', 'inflected', 'heb', 'נָסַע', '["nâçaʻ"]', '["and/ he departed","and/ he has uprooted","and/ he journeyed","and/ he led out","and/ he pulled out","and/ he set out","and/ it set out","and/ it will set out","and/ they departed","and/ they quarried","and/ they set out","and/ they will journey","and/ they will set out","and/ we set out"]', '["v"]', 'properly, to pull up, especially the tent-pins, i.e. start on a journey cause to blow, bring, get, (make to) go (away, forth, forward, onward, out), (take) journey, march, remove, set aside (forward), × still, be on his (go their) way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5265}/[H5265]', 'inflected', 'heb', 'נָסַע', '["nâçaʻ"]', '["and/ journeying","and/ set out","so/ they may set out"]', '["v"]', 'properly, to pull up, especially the tent-pins, i.e. start on a journey cause to blow, bring, get, (make to) go (away, forth, forward, onward, out), (take) journey, march, remove, set aside (forward), × still, be on his (go their) way.', 'a primitive root;');
