INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7458}/[H7456]', 'lemma', 'heb', 'רָעָב', '["râʻâb"]', '["a famine","famine","hunger"]', '["n-m"]', 'hunger (more or less extensive) dearth, famine, famished, hunger.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4714G}/H9011/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["Egypt/ <towards>","Egypt/ towards"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1481A}/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["to/ sojourn"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3515}/[H3513]', 'lemma', 'heb', 'כָּבֵד', '["kâbêd"]', '["[am] heavy of","[is too] heavy","[is] heavy","[it is too] heavy","[it was] heavy","[was] heavy","[was] wealthy","[were] heavy","[will be] heavy","heavy","heavy of","massive","numerous"]', '["a"]', 'heavy; figuratively in a good sense (numerous) or in a bad sense (severe, difficult, stupid) (so) great, grievous, hard(-ened), (too) heavy(-ier), laden, much, slow, sore, thick.', 'from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7458}/[H7456]', 'inflected', 'heb', 'רָעָב', '["râʻâb"]', '["<the>/ famine","the/ famine"]', '["n-m"]', 'hunger (more or less extensive) dearth, famine, famished, hunger.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7126G}/[H7126]', 'lemma', 'heb', 'קָרַב', '["qârab"]', '["I have brought near","[who] she brings near","bring near","draw near","he drew near","he had drawn near","he may draw near","he will draw near","it drew near","it has drawn near","it will draw near","let us draw near","may it draw near","she will draw near","they bring near","they draw near","they drew near","they have brought near","they have drawn near","they will draw near","to draw near","we will draw near","you draw near","you drew near","you will draw near"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["[about] to/ go","[were] to/ come","by/ coming","by/ going","of/ [the] coming of","to <the>/ [those who] go","to/ cause to come","to/ come","to/ coming","to/ enter","to/ go"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4994}/[H4994]', 'lemma', 'heb', 'נָא', '["nâʼ"]', '["please"]', '["inj"]', '''I pray'', ''now'', or ''then''; added mostly to verbs (in the Imperative or Future), or to interjections, occasionally to an adverb or conjunction I beseech (pray) thee (you), go to, now, oh.', 'a primitive particle of incitement and entreaty, which may usually be rendered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3303}/[H3302]', 'lemma', 'heb', 'יָפֶה', '["yâpheh"]', '["<the> good looking of","[are] beautiful","[is] beautiful","[it is] beautiful of","[one] beautiful of","[was] beautiful","[was] beautiful of","a beautiful","beautiful","beautiful of","good looking of","handsome","handsome of"]', '["a"]', 'beautiful (literally or figuratively) beautiful, beauty, comely, fair(-est, one), goodly, pleasant, well.', 'from 3302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4758}/[H7200]', 'lemma', 'heb', 'מַרְאֶה', '["marʼeh"]', '["[the] appearance of","[the] appearance of of","[the] sight of","[was] [the] appearance of","appearance"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0859C}/[H859]', 'lemma', 'heb', 'אַתָּה', '["ʼattâh"]', '["[are] you","you"]', '["p"]', 'thou and thee, or (plural) ye and you thee, thou, ye, you.', 'or (shortened); אַתָּ; or אַת; feminine (irregular) sometimes אַתִּי; plural masculine אַתֶּם; feminine אַתֶּן; or אַתֵּנָהlemma אתֵּנָה missing vowel, corrected to אַתֵּנָה; or אַתֵּנָּה; a primitive pronoun of the second person;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0853}/H9032/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["<obj.>/ you"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4713}/[H4714]', 'inflected', 'heb', 'מִצְרִי', '["Mitsrîy"]', '["<the>/ Egyptian","the/ Egyptian","the/ Egyptian[s]","the/ Egyptians"]', '["a"]', 'a Mitsrite, or inhabitant of Mitsrajim Egyptian, of Egypt.', 'from 4714;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2026}/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["and/ I will kill","and/ he has killed","and/ he killed","and/ he will slay","and/ they killed","and/ they will kill","and/ you have killed","and/ you will kill"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0853}/H9032/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ <obj.>/ you"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0269}/H9020/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["O sister/ my","[are] sister/ my","[is] sister/ my","sister/ my","sisters/ my"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4616}/[H6030]', 'lemma', 'heb', 'מַעַן', '["maʻan"]', '["for [the] sake of","on account of","so as","so that"]', '["prt"]', 'properly, heed, i.e. purpose; used only adverbially, on account of (as a motive or an aim), teleologically, in order that because of, to the end (intent) that, for (to,... ''s sake), lest, that, to.', 'from 6030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5668}/H9032/[H5674]', 'inflected', 'heb', 'עָבוּר', '["ʻâbûwr"]', '["for/ sake of/ you"]', '["prep"]', 'properly, crossed, i.e. (abstractly) transit; used only adverbially, on account of, in order that because of, for (...''s sake), (intent) that, to.', 'or עָבֻר; passive participle of 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315H}/H9020/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["<of> life/ my","life/ my","self/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1558}/H9032/[H1556]', 'inflected', 'heb', 'גָּלָל', '["gâlâl"]', '["on/ account of/ you"]', '["n-m"]', 'a circumstance (as rolled around); only used adverbially, on account of because of, for (sake).', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["as/ goes","when/ came","when/ comes","when/ entered","when/ went"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8269}/[H8323]', 'lemma', 'heb', 'שַׂר', '["sar"]', '["[am] [the] commander of","[the] chief of","[the] commander of","[the] commanders of","[the] governor of","[the] leader of","[the] leaders","[the] leaders of","[the] official of","[the] officials of","[the] prince of","[the] princes of","[was] [the] commander of","[was] an official of","[were] [the] commanders of","[were] [the] leaders of","[were] [the] officials of","[were] princes","[will be] a prince","a chief","a commander of","a leader","a prince of","chiefs","commander of","commanders","commanders of","icials","icials of","leaders","leaders of","officials","officials of","overseers of","prince of","princes"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6547G}/[H6547]', 'lemma', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1984B}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["and/ they praised","and/ they will praise"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004M}/[H1129]', 'lemma', 'heb', 'בַּיִת', '["bayith"]', '["O house of","[are] a house of","[is] [the] house of","[the] house","[the] house of","[the] household","[the] household of","[the] houses of","a house","a house of","house","households"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0087}/[H48]', 'inflected', 'heb', 'אַבְרָם', '["ʼAbrâm"]', '["and/ to/ Abram"]', '["n-pr-m"]', 'Abram, the original name of Abraham Abram.', 'contracted from 48; high father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5668}/H9034/[H5674]', 'inflected', 'heb', 'עָבוּר', '["ʻâbûwr"]', '["for/ sake of/ her"]', '["prep"]', 'properly, crossed, i.e. (abstractly) transit; used only adverbially, on account of, in order that because of, for (...''s sake), (intent) that, to.', 'or עָבֻר; passive participle of 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1241}/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["and/ a herd","and/ cattle","and/ herd","and/ herd[s]","and/ ox[en]"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2543}/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["and/ [male] donkeys","and/ [the] donkey","and/ [the] donkey of","and/ a donkey","and/ donkey[s]","and/ donkeys"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5650}/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["and/ [is] a servant","and/ [male] servant[s]","and/ [male] servants","and/ [the] servants of","and/ [will be] a servant","and/ a servant","and/ a slave","and/ male servants","and/ servants"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H8198>', 'inflected', 'heb', 'ושפחות', '["u./she.fa.Chot","u./she.fa.choT","ve./shif.Chah"]', '["and/ a female servant","and/ female servant[s]","and/ female servants","and/ female slaves","and/ maidservants"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0860}/[H386]', 'inflected', 'heb', 'אָתוֹן', '["ʼâthôwn"]', '["and/ female donkeys"]', '["n-f"]', 'a female donkey (from its docility) (she) ass.', 'probably from the same as 386 (in the sense of patience);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1581}/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["and/ camels"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5060}/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["and/ he made [it] touch","and/ he struck","and/ he touched","and/ he will touch","and/ it arrived","and/ it reached","and/ it touched","and/ it will reach","and/ she made [it] touch","and/ she touched","and/ they reached","and/ they were struck","and/ they will arrive","and/ you will make touch"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5061}/[H5060]', 'lemma', 'heb', 'נֶגַע', '["negaʻ"]', '["<the> plague of","[is] a plague","[is] a plague of","[the] plague of","[the] plagued [person] of","a plague","a plague of","a wound","plague","plagues","wound"]', '["n-m"]', 'a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound.', 'from 5060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004M}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["house/ his","household/ his","own house/ his","own household/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697M}/[H1696]', 'lemma', 'heb', 'דָּבָר', '["dâbâr"]', '["[is] [the] word of","[the] matter of","[the] thing","[the] thing of","[the] words of","a matter of","a thing","a word","a word of","things of","words of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0087}/[H48]', 'inflected', 'heb', 'אַבְרָם', '["ʼAbrâm"]', '["<to>/ Abram","to/ Abram"]', '["n-pr-m"]', 'Abram, the original name of Abraham Abram.', 'contracted from 48; high father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0802H}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["<into>/ a wife","<into>/ wife","<into>/ wives","for/ wives","to/ [the] wife of","to/ a wife","to/ wives"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1980G}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ I may go","and/ I will go","and/ [those who] were going","and/ come","and/ go","and/ let me go","and/ let us go","and/ they may go","and/ we will go","so/ I may go","so/ he may go","so/ let me go","so/ let us go","so/ they may go","so/ we may go"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9033/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["<on>/ him","[is] at/ it","[is] on/ him","[is] on/ it","[is] over/ it","[was] at/ it","[was] on/ him","[was] on/ it","[will be] on/ it","above/ him","against/ him","at/ him","at/ it","on/ him","on/ himself","on/ it","on/ itself","over/ him","over/ himself","over/ it","to/ him","to/ it","towards/ him","with/ him","with/ it"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5927G}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ I caused to go up","and/ I went up","and/ I will bring up","and/ I will go up","and/ did it come up","and/ he brought up","and/ he came up","and/ he grew up","and/ he made come up","and/ he offered up","and/ he went up","and/ he will rise","and/ it came up","and/ it goes up","and/ it rises","and/ it went up","and/ it will go up","and/ it will grow up","and/ it will rise","and/ she came up","and/ she went up","and/ she will go up","and/ they brought up","and/ they came up","and/ they grew up","and/ they had taken themselves up","and/ they have gone up","and/ they took themselves up","and/ they went up","and/ they will go up","and/ we went up","and/ we will go up","and/ you have been taken up","and/ you have gone up","and/ you went up","and/ you will come up","and/ you will go up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4714G}/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["[was] from/ Egypt","from/ Egypt","since/ Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3876}/[H3875]', 'inflected', 'heb', 'לוֹט', '["Lôwṭ"]', '["and/ Lot"]', '["n-pr-m"]', 'Lot, Abraham''s nephew Lot.', 'the same as 3875;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/H9033/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[are] with/ him","[be] with/ him","[is] with/ him","[was] with/ him","[was] with/ it","[were] with/ him","[will be] with/ him","with/ him","with/ himself","with/ it"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5045G>/H9011', 'inflected', 'heb', 'הנגבה', '["ha./Neg.ba/h"]', '["the/ Negev/ towards"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4735}/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["in <the>/ livestock"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3701G}/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["<in>/ silver","for <the>/ money","for <the>/ silver","for/ money","for/ silver","in <the>/ silver","with <the>/ silver","with/ money","with/ silver"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H2091>', 'inflected', 'heb', 'ובזהב', '["u./va./za.Hav","u./ve./za.Hav"]', '["and/ in <the>/ gold","and/ with <the>/ gold","and/ with/ gold"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4550}/H9023/[H5265]', 'inflected', 'heb', 'מַסַּע', '["maççaʻ"]', '["to/ journeyings/ his"]', '["n-m"]', 'a departure (from striking the tents), i.e. march (not necessarily a single day''s travel); by implication, a station (or point of departure) journey(-ing).', 'from 5265;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H5045G>', 'inflected', 'heb', 'מנגב', '["mi./Ne.gev"]', '["from/ [the] Negev","from/ [the] south"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4725}/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["<the>/ place","[is] the/ place","the/ place","the/ places"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8462}/[H2490]', 'inflected', 'heb', 'תְּחִלָּה', '["tᵉchillâh"]', '["[will be] at the/ first","at the/ beginning","at the/ first","at/ [the] beginning of"]', '["n-f"]', 'a commencement; relatively original (adverb, -ly) begin(-ning), first (time).', 'from 2490 in the sense of opening;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5857G}/[H5856]', 'inflected', 'heb', 'עַי', '["ʻAy"]', '["<the>/ Ai"]', '["n-pr-loc"]', 'Ai, Aja or Ajath, a place in Palestine Ai, Aija, Aijath, Hai.', 'or (feminine) עַיָּא; (Nehemiah 11:31), or עַיָּת; (Isaiah 10:28), for 5856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4196}/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["the/ altar","the/ altar of","the/ altars"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3876}/[H3875]', 'inflected', 'heb', 'לוֹט', '["Lôwṭ"]', '["to/ Lot"]', '["n-pr-m"]', 'Lot, Abraham''s nephew Lot.', 'the same as 3875;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1980G}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["[are] the/ [ones] going","[is] the/ [one who] goes","[were] the/ [ones who] went","that/ is going","those/ [who] went","which/ walks","who/ go","who/ had been going","who/ had gone","who/ was traveling","who/ went"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0168G}/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["and/ [the] tent of","and/ tents"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375K}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["[are] lending","[is] lifting up","[were] supporting","it supported","they carry"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3427}/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["by/ marrying","for the/ [one who] sits","for/ [the] inhabitant[s] of","of/ [the] dwelling of","of/ [the] inhabitant[s] of","of/ [the] inhabitants of","to <the>/ [those who] dwell","to/ [the] dwelling of","to/ [the] inhabitant[s] of","to/ [the] inhabitants of","to/ cause [them] to dwell","to/ dwell","to/ dwell in","to/ make [him] sit","to/ remain","to/ sit"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3162B}/[H3161]', 'lemma', 'heb', 'יַחַד', '["yachad"]', '["[were] together","alike","all together","altogether","together"]', '["n-m"]', 'properly, a unit, i.e. (adverb) unitedly alike, at all (once), both, likewise, only, (al-) together, withal.', 'from 3161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3201}/[H3201]', 'lemma', 'heb', 'יָכֹל', '["yâkôl"]', '["I am able","I am able to endure","I have prevailed","I was able","I will be able","I will prevail","am I able","anyone will be able","certainly <to prevail>","have I been able","he is able","he prevailed","he was able","he will be able","is he able","it has been able","it is able","it was able","it will be able","it will prevail","people were able","she was able","they are able","they had been able","they have been able","they have prevailed","they were able","they will be able","they will prevail","they will succeed","was able","we are able","we will be able","we will prevail","were they able","will I be able","will they be able","will we prevail","you are able","you will be able","you will prevail"]', '["v"]', 'to be able, literally (can, could) or morally (may, might) be able, any at all (ways), attain, can (away with, (-not)), could, endure, might, overcome, have power, prevail, still, suffer.', 'or (fuller) יָכוֹל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7379}/[H7378]', 'lemma', 'heb', 'רִיב', '["rîyb"]', '["[the] case of","[the] cases of","[the] quarrel of","a case at law","a controversy","a dispute","case at law","cases at law","dispute","quarreling","strife"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4735}/[H7069]', 'lemma', 'heb', 'מִקְנֶה', '["miqneh"]', '["[the] livestock of","livestock","livestock of"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6522}/[H6521]', 'inflected', 'heb', 'פְּרִזִּי', '["Pᵉrizzîy"]', '["and/ the/ Perizzite[s]"]', '["a"]', 'a Perizzite, one of the Canaanitish tribes Perizzite.', 'for 6521; inhabitant of the open country;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0408}/[H3808]', 'lemma', 'heb', 'אַל', '["ʼal"]', '["[let] not","do not","mau not","may [we] not","may [you] not","may not","may not [it be so]","may not [it be to]","may not [it be]","not"]', '["adv"]', 'not (the qualified negation, used as a deprecative); once (Job 24:25) as a noun, nothing nay, neither, + never, no, nor, not, nothing (worth), rather than.', 'a negative particle (akin to 3808);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4808}/[H7378]', 'lemma', 'heb', 'מְרִיבָה', '["mᵉrîybâh"]', '["strife"]', '["n-f"]', 'quarrel provocation, strife.', 'from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0996G}/H9031/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["and/ between/ you"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7462B}/H9020/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["[is] shepherd/ my","herdsmen/ my","shepherd of/ my","shepherd/ my","shepherds/ my"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7462B}/H9021/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["herdsmen/ your"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251H}/[H251]', 'lemma', 'heb', 'אָח', '["ʼâch"]', '["[are] [the] brothers of","[the] brother of","[the] brothers of","[the] relatives of","[was] [the] relative of","brothers"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0587}/[H595]', 'lemma', 'heb', 'אֲנַחְנוּ', '["ʼănachnûw"]', '["[are] we","we"]', '["p"]', 'we ourselves, us, we.', 'apparently from 595;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440G}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ you","[are] <to>/ before/ you","[is] <to>/ before/ you","[were] <to>/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5921A}/H9030/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["from / with <the>/ me","from/ on <the>/ me","from/ on/ me","from/ with <the>/ me"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8040G}/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["the/ left","the/ left [hand]"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3231}/[H3225]', 'inflected', 'heb', 'יָמַן', '["yâman"]', '["so/ let me go right"]', '["v"]', 'to be right-handed or take the right-hand side go (turn) to (on, use) the right hand.', 'a primitive root; to be (physically) right (i.e. firm); but used only as denominative from 3225 and transitive,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3225G}/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["the/ right","the/ right [side]"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8041}/[H8040]', 'inflected', 'heb', 'שָׂמַאל', '["sâmaʼl"]', '["and/ I will go left","and/ using left [hand]"]', '["v"]', 'to use the left hand or pass in that direction (go, turn) (on the, to the) left.', 'a primitive root (denominative from 8040);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375M}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ I lifted up","and/ have you lifted up?","and/ he lifted up","and/ she lifted up","and/ they lifted up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869A}/H9023/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eye/ his","eye/ its","eyes/ his","eyes/ its","own eyes/ his"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3603H}/[H3769]', 'lemma', 'heb', 'כִּכָּר', '["kikkâr"]', '["[the] talent[s] of","[the] valley of","[was] a talent of","a round cover of","a round loaf of","a talent","a talent of","round loaves of","talent[s]","talent[s] of","talents","talents of","two talents"]', '["n-f"]', 'a circle, i.e. (by implication) a circumjacent tract or region, especially the Ghor or valley of the Jordan; also a (round) loaf; also a talent (or large [round] coin) loaf, morsel, piece, plain, talent.', 'from 3769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3383}/[H3381]', 'inflected', 'heb', 'יַרְדֵּן', '["Yardên"]', '["O/ Jordan","the/ Jordan"]', '["n-pr"]', 'Jarden, the principal river of Palestine Jordan.', 'from 3381; a descender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3605}/H9024/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["all of/ it"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4945B}/[H8248]', 'lemma', 'heb', 'מַשְׁקֶה', '["mashqeh"]', '["[the] drink of","[was] well-watered","drink"]', '["n-m"]', 'properly, causing to drink, i.e. a butler; by implication (intransitively), drink (itself); figuratively, a well-watered region butler(-ship), cupbearer, drink(-ing), fat pasture, watered.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5467>', 'opaque', 'heb', 'סְדֹם', '["Çᵉdôm"]', '["Sodom","[was] Sodom"]', '["n-pr-loc"]', 'Sedom, a place near the Dead Sea Sodom.', 'from an unused root meaning to scorch; burnt (i.e. volcanic or bituminous) district;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6017}/[H6014]', 'lemma', 'heb', 'עֲמֹרָה', '["ʻĂmôrâh"]', '["Gomorrah"]', '["n-pr-loc"]', 'Amorah, a place in Palestine Gomorrah.', 'from 6014; a (ruined) heap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1588M}/[H1598]', 'inflected', 'heb', 'גַּן', '["gan"]', '["like <the>/ garden","like/ [the] garden of","like/ a garden"]', '["n"]', 'a garden (as fenced) garden.', 'from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H0776G>', 'inflected', 'heb', 'כארץ', '["ke./''E.retz","ke./''e.retz","kha./''A.retz","khe./''E.retz"]', '["[is] like/ [the] land of","like the/ ground","like/ [the] earth","like/ [the] land of","like/ a land"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4714G}/[H4693]', 'lemma', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["<of> Egypt","Egypt","O Egypt","of Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6820}/[H6819]', 'lemma', 'heb', 'צֹעַר', '["Tsôʻar"]', '["Zoar","[is] Zoar"]', '["n-pr-loc"]', 'Tsoar, a place East of the Jordan Zoar.', 'from 6819; little;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0977}/[H977]', 'inflected', 'heb', 'בָּחַר', '["bâchar"]', '["and/ I have chosen","and/ he chose","and/ he has chosen","and/ he will choose","and/ it chose","and/ it will be chosen","and/ they choose","and/ you will choose"]', '["v"]', 'properly, to try, i.e. (by implication) select acceptable, appoint, choose (choice), excellent, join, be rather, require.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6504}/[H6504]', 'inflected', 'heb', 'פָּרַד', '["pârad"]', '["and/ they separated"]', '["v"]', 'to break through, i.e. spread or separate (oneself) disperse, divide, be out of joint, part, scatter (abroad), separate (self), sever self, stretch, sunder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5892B}/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["<in>/ a city","[are] in/ [the] cities of","[is] in the/ city","[was] in the/ city","[were] in the/ cities","[were] in/ [the] cities of","against the/ city","against/ city","among/ [the] cities of","by/ city","in the/ cities","in the/ city","in/ [the] cities of","in/ [the] city of","in/ a city","in/ a city of","on the/ city","on/ [the] cities of","over/ [the] cities of"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3603H}/[H3769]', 'inflected', 'heb', 'כִּכָּר', '["kikkâr"]', '["the/ district","the/ plain","the/ surrounding region","the/ talent[s]","the/ valley"]', '["n-f"]', 'a circle, i.e. (by implication) a circumjacent tract or region, especially the Ghor or valley of the Jordan; also a (round) loaf; also a talent (or large [round] coin) loaf, morsel, piece, plain, talent.', 'from 3769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0167}/[H168]', 'inflected', 'heb', 'אָהַל', '["ʼâhal"]', '["and/ he moved tent"]', '["v"]', 'to tent pitch (remove) a tent.', 'a denominative from 168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0582}/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["and/ O men of","and/ [the] men","and/ [the] men of","and/ [the] people of","and/ men","and/ men of","and/ people","and/ people of"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2400}/[H2398]', 'inflected', 'heb', 'חַטָּא', '["chaṭṭâʼ"]', '["and/ sinful","and/ sinners"]', '["n-m"]', 'a criminal, or one accounted guilty offender, sinful, sinner.', 'intensively from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3068G}/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["and/ O Yahweh","and/ Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5973B}/H9033/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["from / with <the>/ him","from/ with <the>/ him","more than/ with/ him"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375M}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["I have lifted up","he has lifted up","lift up","they are lifted up","you lift up","you will lift up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869A}/H9021/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["[are] eyes/ your","eye/ your","eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6828G}/H9011/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["[the] north/ towards","[will be] north/ -ward","north/ -ward"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5045H>/H9011', 'inflected', 'heb', 'ונגבה', '["va./Neg.ba/h","ve./Neg.ba/h"]', '["and/ south/ -ward"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6924B}/H9011/[H6923]', 'inflected', 'heb', 'קֶדֶם', '["qedem"]', '["and/ east/ -ward"]', '["n-m adv"]', 'the front, of place (absolutely, the fore part, relatively the East) or time (antiquity); often used adverbially (before, anciently, eastward) aforetime, ancient (time), before, east (end, part, side, -ward), eternal, × ever(-lasting), forward, old, past. Compare 6926.', 'or קֵדְמָה; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3220H>/H9011', 'inflected', 'heb', 'וימה', '["va./Ya.ma/h","ve./Ya.ma/h"]', '["and/ west/ -ward"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414G}/H9034/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["I gave/ her","I give/ it","I have given/ it","I will give/ her","I will give/ it","give/ it","he gave/ it","he has given/ it","let him give/ it","you will give/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2233H}/H9021/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ for/ offspring/ your","and/ to/ offspring/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760A}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ I have made","and/ I have put","and/ I set in place","and/ I will establish","and/ I will make","and/ I will perform","and/ I will set","and/ he established","and/ he made","and/ he makes","and/ he placed","and/ he put","and/ he put [it]","and/ he set","and/ he set [them]","and/ he set up","and/ he will make","and/ he will set [it] up","and/ it set","and/ they made","and/ they put","and/ they put [them]","and/ they set","and/ they set up","and/ you made","and/ you will make","and/ you will place","and/ you will put","and/ you will put [it]","and/ you will set [him]"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6083}/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["like <the>/ dust","like the/ dust","like/ [the] dust of","like/ dust"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4487}/[H4487]', 'inflected', 'heb', 'מָנָה', '["mânâh"]', '["to/ be numbered","to/ count"]', '["v"]', 'properly, to weigh out; by implication, to allot or constitute officially; also to enumerate or enroll appoint, count, number, prepare, set, tell.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4487}/[H4487]', 'lemma', 'heb', 'מָנָה', '["mânâh"]', '["[he is] counting","[one who] counts","[were] appointed","appoint","count","has he counted","he had assigned","he has assigned","he was numbered","it will be numbered","it will numbered","people have allotted","they were numbered","you will muster"]', '["v"]', 'properly, to weigh out; by implication, to allot or constitute officially; also to enumerate or enroll appoint, count, number, prepare, set, tell.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965B}/[H6965]', 'lemma', 'heb', 'קוּם', '["qûwm"]', '["<of> to rise","<you> arise","I arise","I arose","I will arise","[am] about to raise up","[surely] to rise","anyone will arise","arise","do they stand up?","does it rise","get up","he arose","he has arisen","he has raised up","he raises up","he rises","he rose up","he stood up","he will arise","he will stand","it arose","it has risen up","it rises","it will arise","it will rise","let him arise","let me arise","let them arise","let us arise","may he arise","stand up","they arise","they arose","they have arisen","they rise up","they rose","they will arise","they will rise","they will stand","to establish","to rise","we arise","we will arise","will I arise","will he rise up","will they arise","will you rise","you arose","you have risen up","you will arise","you will rise"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0753}/H9024/[H748]', 'inflected', 'heb', 'אֹרֶךְ', '["ʼôrek"]', '["to/ length/ its"]', '["n-m"]', 'length forever, length, long.', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7341}/H9024/[H7337]', 'inflected', 'heb', 'רֹחַב', '["rôchab"]', '["and/ to/ breadth/ its"]', '["n-m"]', 'width (literally or figuratively) breadth, broad, largeness, thickness, wideness.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0436H}/[H352]', 'inflected', 'heb', 'אֵלוֹן', '["ʼêlôwn"]', '["at/ [the] great trees of"]', '["n-m"]', 'an oak or other strong tree plain. See also 356.', 'prolonged from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4471G}/[H4754]', 'lemma', 'heb', 'מַמְרֵא', '["Mamrêʼ"]', '["Mamre"]', '["n-pr-m n-pr-loc"]', 'Mamre, an Amorite Mamre.', 'from 4754 (in the sense of vigor); lusty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2275A}/[H2267]', 'inflected', 'heb', 'חֶבְרוֹן', '["Chebrôwn"]', '["[are] at/ Hebron","[were] in/ Hebron","at/ Hebron","in/ Hebron"]', '["n-pr-loc n-pr-m"]', 'Chebron, a place in Palestine, also the name of two Israelites Hebron.', 'from 2267; seat of association;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3068G}\/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["<to>/ Yahweh","[belongs] to/ Yahweh","to/ Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0569}/[H569]', 'lemma', 'heb', 'אַמְרָפֶל', '["ʼAmrâphel"]', '["Amraphel"]', '["n-pr-m"]', 'Amraphel, a king of Shinar Amraphel.', 'of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428G}/[H4427]', 'lemma', 'heb', 'מֶלֶךְ', '["melek"]', '["<of> kings","<the> kings of","O king of","O kings","O kings of","[am] a king","[am] king","[are] [the] kings of","[are] kings of","[is] [the] king of","[is] [the] kings of","[is] king","[the] king","[the] king of","[the] kings","[the] kings of","[was] [the] king of","[was] a king","[was] king","[will be] a king","[will be] king","a king","king","king[s]","kings","kings of"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0746A>', 'opaque', 'heb', 'אֲרְיוֹךְ', '["ʼĂryôwk"]', '["Arioch"]', '["n-pr-m"]', 'Arjok, the name of two Babylonians Arioch.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0495}/[H495]', 'lemma', 'heb', 'אֶלָּסָר', '["ʼEllâçâr"]', '["Ellasar"]', '["n-pr-loc"]', 'Ellasar, an early country of Asia Ellasar.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3540>', 'opaque', 'heb', 'כְּדׇרְלָעֹמֶר', '["Kᵉdorlâʻômer"]', '["Kedor-laomer","Kedorlaomer"]', '["n-pr-m"]', 'Kedorlaomer, an early Persian king Chedorlaomer.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5867A}/[H5956]', 'lemma', 'heb', 'עֵילָם', '["ʻÊylâm"]', '["Elam","O Elam"]', '["n-pr-m n-pr-loc"]', 'Elam, a son of Shem and his descendants, with their country; also of six Israelites Elam.', 'or עוֹלָם; (Ezra 10:2; Jeremiah 49:36), probably from 5956; hidden, i.e. distant;');
