INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5127}/[H5127]', 'inflected', 'heb', 'נוּס', '["nûwç"]', '["and/ <it> will flee","and/ he fled","and/ he had fled","and/ he will flee","and/ it fled","and/ it will flee","and/ she fled","and/ they fled","and/ they will flee","and/ we will flee","and/ you will flee"]', '["v"]', 'to flit, i.e. vanish away (subside, escape; causatively, chase, impel, deliver) × abate, away, be displayed, (make to) flee (away, -ing), put to flight, × hide, lift up a standard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8033G}/H9011/[H834]', 'inflected', 'heb', 'שָׁם', '["shâm"]', '["[are] there/ <towards>","[is] there/ <towards>","[was] there/ <towards>","there/ <towards>","there/ towards"]', '["adv"]', 'there (transferring to time) then; often thither, or thence in it, thence, there (-in, of, out), thither, whither.', 'a primitive particle (rather from the relative pronoun, 834);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7604}/[H7604]', 'inflected', 'heb', 'שָׁאַר', '["shâʼar"]', '["and/ the/ [one who] is left alive","and/ the/ [ones who] survive","and/ the/ remainder","and/ those/ [which] survive","and/ those/ [who] remain","and/ those/ [who] survived"]', '["v"]', 'properly, to swell up, i.e. be (causatively, make) redundant leave, (be) left, let, remain, remnant, reserve, the rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2022H}/H9011/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["[the] hill country/ towards"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5127}/[H5127]', 'lemma', 'heb', 'נוּס', '["nûwç"]', '["I have fled","[a man who] flees","[one who] flees","[they are] fleeing","[those who] flee","[were] fleeing","certainly [if] <to flee>","flee","fugitives","he fled","he flee","he flees","he had fled","he made to flee","he will flee","it fled","it had fled","it has fled","it will drive","let me flee","let us flee","they fled","they flee","they had fled","they will flee","we fled","we will flee","will they put to flight?","will you flee","you fled","you will flee"]', '["v"]', 'to flit, i.e. vanish away (subside, escape; causatively, chase, impel, deliver) × abate, away, be displayed, (make to) flee (away, -ing), put to flight, × hide, lift up a standard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7399}/[H7408]', 'lemma', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["[the] possession[s] of","[the] property","property"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0400}/H9028/[H398]', 'inflected', 'heb', 'אֹכֶל', '["ʼôkel"]', '["food/ their"]', '["n-m"]', 'food eating, food, meal(-time), meat, prey, victuals.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1980M}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ he went","and/ they went"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7399}/H9023/[H7408]', 'inflected', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["own property/ his","possession[s]/ his","property/ his"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5467>', 'inflected', 'heb', 'בסדם', '["bi/s.Dom","vi/s.Dom"]', '["in/ Sodom"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6412A}/[H6403]', 'inflected', 'heb', 'פָּלִיט', '["pâlîyṭ"]', '["the/ escapee","the/ fugitive"]', '["n-m"]', 'a refugee (that have) escape(-d, -th), fugitive.', 'or פָּלֵיט; or פָּלֵט; from 6403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5680}/[H5677]', 'inflected', 'heb', 'עִבְרִי', '["ʻIbrîy"]', '["<the>/ Hebrew","<the>/ Hebrew [fem]","<the>/ Hebrew [masc]","[are] the/ Hebrews","the/ Hebrew","the/ Hebrew [women]","the/ Hebrews"]', '["n-pr"]', 'an Eberite (i.e. Hebrew) or descendant of Eber Hebrew(-ess, woman).', 'patronymic from 5677;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7931}/[H7901]', 'lemma', 'heb', 'שָׁכַן', '["shâkan"]', '["I caused to dwell","I dwell","I have dwelt","I will dwell","O [one who] dwells","O [those who] dwell of","O dweller","[am] dwelling","[he is] dwelling","[the one who] dwells","[the one who] dwelt","[those who] dwell of","[was] dwelling","[where] it dwells","[which] he had pitched","[who] dwell","[who] dwells","dwell","dwelling","he dwells","he dwelt","he will dwell","it dwells","it dwelt","it had settled down","it has dwelt","it settled down","it will dwell","it will settle","let it settle down","may he lay","they dwell","they dwelt","they stay","they will dwell","they will dwell in","will he dwell","you cause to dwell","you have dwelt"]', '["v"]', 'to reside or permanently stay (literally or figuratively) abide, continue, (cause to, make to) dwell(-er), have habitation, inhabit, lay, place, (cause to) remain, rest, set (up).', 'a primitive root (apparently akin (by transmission) to 7901 through the idea of lodging; compare 5531, 7925);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4471H}/[H4754]', 'lemma', 'heb', 'מַמְרֵא', '["Mamrêʼ"]', '["Mamre"]', '["n-pr-m n-pr-loc"]', 'Mamre, an Amorite Mamre.', 'from 4754 (in the sense of vigor); lusty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0812G}/[H811]', 'lemma', 'heb', 'אֶשְׁכֹּל', '["ʼEshkôl"]', '["Eshcol"]', '["n-pr"]', 'Eshcol, the name of an Amorite, also of a valley in Palestine Eshcol.', 'the same as 811;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251G}/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ [the] brother of","and/ a brother"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6063G}/[H5288]', 'lemma', 'heb', 'עָנֵר', '["ʻÂnêr"]', '["Aner"]', '["n-pr-m n-pr-loc"]', 'Aner, a Amorite, also a place in Palestine Aner.', 'probably for 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1992}/[H1931]', 'inflected', 'heb', 'הֵם', '["hêm"]', '["and/ they"]', '["p"]', 'they (only used when emphatic) it, like, × (how, so) many (soever, more as) they (be), (the) same, × so, × such, their, them, these, they, those, which, who, whom, withal, ye.', 'or (prolonged) הֵמָּה; masculine plural from 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1167I}/[H1166]', 'lemma', 'heb', 'בַּעַל', '["baʻal"]', '["[are] a master of","[is] a master of","[the] citizens of","[the] master of","[were] [the] partners of","a husband","a master of"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7617}/[H7617]', 'lemma', 'heb', 'שָׁבָה', '["shâbâh"]', '["he had been taken captive","he had taken captive","it has been taken captive","it was captured","taking captive","they had been taken captive","they have been taken captive","they have taken captive","they took captive","took captive","you have taken captive","you took captive"]', '["v"]', 'to transport into captivity (bring away, carry, carry away, lead, lead away, take) captive(-s), drive (take) away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251H}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["brother/ his","brothers/ his","relative/ his","relatives/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7324}/[H7324]', 'inflected', 'heb', 'רוּק', '["rûwq"]', '["and/ I will draw","and/ I will pour out","and/ he drew out","and/ they will draw"]', '["v"]', 'to pour out (literally or figuratively), i.e. empty × arm, cast out, draw (out), (make) empty, pour forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2593}/H9023/[H2596]', 'inflected', 'heb', 'חָנִיךְ', '["chânîyk"]', '["trained men/ his"]', '["a"]', 'initiated; i.e. practiced trained.', 'from 2596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3211}/[H3205]', 'lemma', 'heb', 'יָלִיד', '["yâlîyd"]', '["[the] one born of","one born of","those born of"]', '["a"]', 'born (home-) born, child, son.', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7291}/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["and/ I will pursue","and/ he harassed","and/ he pursued","and/ he will pursue","and/ it will be chased","and/ it will pursue","and/ she will pursue","and/ they pursued","and/ they will pursue","and/ you will pursue"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1835G}/[H1777]', 'lemma', 'heb', 'דָּן', '["Dân"]', '["Dan","O Dan"]', '["n-pr-m"]', 'Dan, one of the sons of Jacob; also the tribe descended from him, and its territory; likewise a place in Palestine colonized by them Daniel', 'from 1777; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2505A}/[H2505]', 'inflected', 'heb', 'חָלַק', '["châlaq"]', '["and/ divided himself","and/ he apportioned","and/ he distributed","and/ it will be divided","and/ they apportioned","and/ they divided","and/ they will divide among themselves","and/ you will divide"]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9038/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["<on>/ them","[is] on/ them","[was] above/ them","[was] on/ them","[was] over/ them","[were] on/ them","above/ them","at/ them","on/ him","on/ them","on/ themselves","over/ them","over/ themselves","to/ them","towards/ them","with/ them"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5650}/H9023/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["and/ [male] servant/ his","and/ servants/ his"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5221}/H9038/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["and/ he attacked/ them","and/ he defeated/ them","and/ he had defeated/ them","and/ he struck down/ them","and/ he struck/ them","and/ he will strike down/ them","and/ they defeated/ them","and/ they struck down/ them","and/ they struck/ them","and/ we defeated/ them","and/ you will strike down/ them"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7291}/H9038/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["and/ he pursued/ them","and/ it pursued/ them","and/ they pursued/ them"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2327}/[H2247]', 'lemma', 'heb', 'חוֹבָה', '["chôwbâh"]', '["Hobah"]', '["n-pr-loc"]', 'Chobah, a place in Syria Hobah.', 'feminine active participle of 2247; hiding place;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8040H}/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["[is] from/ [the] north","from/ [the] north"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1834>', 'inflected', 'heb', 'לדמשק', '["le./da.Ma.sek","le./da.Me.sek"]', '["<to>/ Damascus","of/ Damascus"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7399}/[H7408]', 'inflected', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["the/ possession[s]","the/ property"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7399}/H9023/[H7408]', 'inflected', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["and/ possession[s]/ his"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5971A}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["<of> the/ people","<the>/ people","[is] the/ people","of the/ peoples","the/ people","the/ people of","the/ peoples"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428L}/[H4427]', 'lemma', 'heb', 'מֶלֶךְ', '["melek"]', '["[the] king of"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122G}/H9033/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ him"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725G}/H9043/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["returned/ he"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5221}/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["from/ defeating","from/ striking down","more than/ striking"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4428L}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["the/ king","the/ kings"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6010O}/[H6009]', 'lemma', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["[is] [the] valley of","[the] valley of"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7740}/[H7737]', 'lemma', 'heb', 'שָׁוֵה', '["Shâvêh"]', '["Shaveh"]', '["n-pr-loc"]', 'Shaveh, a place in Palestine Shaveh.', 'from 7737; plain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4442}/[H4428]', 'inflected', 'heb', 'מַלְכִּי־צֶדֶק', '["Malkîy-Tsedeq"]', '["and/ Melchi-"]', '["n-pr-m"]', 'Malki-Tsedek, an early king in Palestine Melchizedek.', 'from 4428 and 6664; king of right;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4442}/[H4428]', 'lemma', 'heb', 'מַלְכִּי־צֶדֶק', '["Malkîy-Tsedeq"]', '["-zedek","Melchi-"]', '["n-pr-m"]', 'Malki-Tsedek, an early king in Palestine Melchizedek.', 'from 4428 and 6664; king of right;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8004}/[H8003]', 'lemma', 'heb', 'שָׁלֵם', '["Shâlêm"]', '["Salem"]', '["n-pr-loc"]', 'Shalem, an early name of Jerusalem Salem.', 'the same as 8003; peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3196>', 'inflected', 'heb', 'ויין', '["Ve./ya.yin","va./Ya.yin","ve./Ya.yin","ve./Yein","ve./ya.yin"]', '["and/ [the] wine of","and/ wine","and/ wine of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3548}/[H3547]', 'lemma', 'heb', 'כֹּהֵן', '["kôhên"]', '["<of> a priest","[are] a priest","[the] priest of","[the] priests of","[was] a priest","[were] priests","a priest","priest","priests","priests of"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0410J}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["by/ God","of/ God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5945H}/[H5927]', 'lemma', 'heb', 'עֶלְיוֹן', '["ʻelyôwn"]', '["Most High"]', '["n-m a"]', 'an elevation, i.e. (adj.) lofty (compar.); as title, the Supreme (Most, on) high(-er, -est), upper(-most).', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1288}/H9033/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["and/ I blessed/ him","and/ he blessed/ him"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0776G>', 'inflected', 'heb', 'וארץ', '["va./''A.retz","ve./''E.retz"]', '["and/ [the] earth","and/ [the] land of","and/ a land","and/ an earth","and/ earth","and/ land"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0410J}/[H352]', 'lemma', 'heb', 'אֵל', '["ʼêl"]', '["God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4042}/[H4043]', 'lemma', 'heb', 'מָגַן', '["mâgan"]', '["he has delivered"]', '["v"]', 'properly, to shield; encompass with; figuratively, to rescue, to hand safely over (i.e. surrender) deliver.', 'a denominative from 4043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6862C}/H9021/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["opponents/ your"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027H}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[are] in/ hand/ your","in/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4643}/[H6240]', 'lemma', 'heb', 'מַעֲשֵׂר', '["maʻăsêr"]', '["[the] tenth of","[the] tenth part of","[the] tithe of","[will be] [the] tenth part of","a tenth","a tithe","a tithe of","tithe"]', '["n-m"]', 'a tenth; especially a tithe tenth (part), tithe(-ing).', 'or מַעֲשַׂר; and (in plural) feminine מַעַשְׂרָה; from 6240;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7399}/[H7408]', 'inflected', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["and/ the/ possession[s]"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9032}', 'inflected', 'heb', 'לך', '["La/kh","la/kh","le./khi","lo/Kh"]', '["<for>/ yourself","<to the>/ yourself","<to> <the>/ you","<to>/ you","<to>/ yourself","[be] to <the>/ you","[belong] to <the>/ you","[belong] to/ you","[belong] to/ you?","[belonging] to/ you","[belongs] to <the>/ you","[belongs] to/ you","[is] to <the>/ you","[is] to/ you","for <the>/ you","for <the>/ yourself","for/ you","for/ yourself","of <the>/ you","of/ you","to <the>/ you","to <the>/ yourself","to/ you","to/ yourself"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7311A}/[H7311]', 'lemma', 'heb', 'רוּם', '["rûwm"]', '["I have raised","I have raised up","I raise","I raised","I will be exalted","I will exalt myself","I will raise","[are] high","[is] exalted","[is] exalting","[is] lifting up","[the] high [one]","[the] high [things]","[those who] contributed","[which] it is high","exalt","exaltation","exalted [ones]","haughty","haughty [people]","have you lifted up","have you raised","he contributed","he has lifted up","he is rising up","he lifted up","he lifts up","he raised","he will be high","he will exalt [them]","he will lift up","high","it exalts","it is exalted","it is lifted up","it is raised","it sets on high","it was raised","it was removed","it will be exalted","it will rise","lift [it]","lift [it] up","lift up","may it be lifted up","raise","raised","remove","they are exalted","they are high","they are raised","they be exalted","they contributed","they have been uplifted","they raised","they will arise","they will be lifted up","they will lift up","they will offer up","to be high","uplifted","will he be exalted","you have exalted","you lift up","you will contribute","you will exalt [them]","you will offer up"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ my","hands/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0518H}/[H518]', 'lemma', 'heb', 'אִם', '["ʼim"]', '["<if>","<if>?","if","or","or?","whether"]', '["prt"]', 'used very widely as demonstrative, lo!; interrogative, whether?; or conditional, if, although; also Oh that!, when; hence, as a negative, not (and, can-, doubtless, if, that) (not), + but, either, + except, + more(-over if, than), neither, nevertheless, nor, oh that, or, + save (only, -ing), seeing, since, sith, + surely (no more, none, not), though, + of a truth, + unless, + verily, when, whereas, whether, while, + yet.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2339>', 'inflected', 'heb', 'מחוט', '["mi./Chut"]', '["from/ a thread"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8288}/[H8308]', 'lemma', 'heb', 'שְׂרוֹךְ', '["sᵉrôwk"]', '["a thong of"]', '["n-m"]', 'a thong (as laced or tied) (shoe-)latchet.', 'from 8308;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5275}/[H5274]', 'lemma', 'heb', 'נַעַל', '["naʻal"]', '["a pair of sandals","a sandal"]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0518H}/[H518]', 'inflected', 'heb', 'אִם', '["ʼim"]', '["and/ if","and/ or?"]', '["prt"]', 'used very widely as demonstrative, lo!; interrogative, whether?; or conditional, if, although; also Oh that!, when; hence, as a negative, not (and, can-, doubtless, if, that) (not), + but, either, + except, + more(-over if, than), neither, nevertheless, nor, oh that, or, + save (only, -ing), seeing, since, sith, + surely (no more, none, not), though, + of a truth, + unless, + verily, when, whereas, whether, while, + yet.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6238}/[H6238]', 'lemma', 'heb', 'עָשַׁר', '["ʻâshar"]', '["I have become rich","I made rich","[is one who] enriches himself","he will be rich","he will become rich","he will gain riches","he will gain wealth","it gains riches","it makes rich","you made rich"]', '["v"]', 'properly, to accumulate; chiefly (specifically) to grow (causatively, make) rich be(-come, en-, make, make self, wax) rich, make (1 Kings 22:48 marg). See 6240.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1107}/H9030/[H1077]', 'inflected', 'heb', 'בִּלְעֲדֵי', '["bilʻădêy"]', '["[is] apart from/ me","apart from/ me"]', '["prt"]', 'except, without, besides beside, not (in), save, without.', 'or בַּלְעֲדֵי; constructive plural from 1077 and 5703, not till, i.e. (as preposition or adverb)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5288}/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["O/ youth","[is] the/ young man","[is] the/ youth","the/ lad","the/ lads","the/ servant","the/ servants","the/ young man","the/ young men","the/ youth[s]","the/ youths"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2506A}/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["and/ [the] share of","and/ a portion","and/ a share"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0582}/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["<the>/ men","[are] the/ men","[are] the/ people","the/ men","the/ people"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9030/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["[are] with/ me","[is] with/ me","[was] with/ me","with <the>/ me","with/ me"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4471G}/[H4754]', 'inflected', 'heb', 'מַמְרֵא', '["Mamrêʼ"]', '["and/ Mamre"]', '["n-pr-m n-pr-loc"]', 'Mamre, an Amorite Mamre.', 'from 4754 (in the sense of vigor); lusty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2506A}/H9028\/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["portions/ their","share/ their"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1697I}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<the>/ matter","<the>/ thing","<the>/ things","<the>/ word","[are] the/ things","[are] the/ words","[is] the/ thing","[is] the/ word","[was] the/ word","the/ matter","the/ matters","the/ thing","the/ things","the/ word","the/ words"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0428}/[H411]', 'inflected', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["<the>/ these","the/ these"]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697G}/[H1696]', 'lemma', 'heb', 'דָּבָר', '["dâbâr"]', '["<the> words of","[are] [the] words of","[are] words","[is] [the] word of","[is] a word","[the] edict of","[the] matters of","[the] word","[the] word of","[the] words of","[was] [the] word of","[was] words of","a matter","a promise","a word","a word of","anything","matters of","word","words","words of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4236}/[H2372]', 'inflected', 'heb', 'מַחֲזֶה', '["machăzeh"]', '["in the/ vision"]', '["n-m"]', 'a vision vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3372G}/[H3372]', 'lemma', 'heb', 'יָרֵא', '["yârêʼ"]', '["I am afraid","I feared","I may be afraid","I was afraid","I will be afraid","I will fear","[are] to be feared","[he is] to be feared","[were] making afraid","[when] I will fear","feared","he feared","he fears","he was afraid","he will be afraid","it feared","it was afraid","it will fear","making afraid","people will be afraid","she is afraid","she was afraid","they are afraid","they feared","they were afraid","they will be afraid","to be feared","was he fearing","we will fear","were you afraid","will I fear","will he be afraid","will they fear","you be afraid","you fear","you have feared","you must be afraid","you must fear","you were afraid","you will be afraid","you will fear"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4043}/[H1598]', 'lemma', 'heb', 'מָגֵן', '["mâgên"]', '["<of> a shield","<of> shield","[am] a shield","[are] a shield","[is] a shield","[the] shield of","[the] shields of","a shield","shield","shields","shields of"]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7939}/H9021/[H7936]', 'inflected', 'heb', 'שָׂכָר', '["sâkâr"]', '["reward/ your","wage[s]/ your"]', '["n-m"]', 'payment of contract; concretely, salary, fare, maintenance; by implication, compensation, benefit hire, price, reward(-ed), wages, worth.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0136}/[H113]', 'lemma', 'heb', 'אֲדֹנָי', '["ʼĂdônây"]', '["O Lord","[am the] Lord","[are the] Lord","[the] Lord","[the] lord of"]', '["n-m"]', 'the Lord (used as a proper name of God only) (my) Lord.', 'an emphatic form of 113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3069}/[H3068]', 'lemma', 'heb', 'יְהֹוִה', '["Yᵉhôvih"]', '["O Yahweh","Yahweh"]', '["n-pr"]', 'God.', 'a variation of 3068 [used after 136, and pronounced by Jews as 430, in order to prevent the repetition of the same sound, since they elsewhere pronounce 3068 as 136]');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0595}/[H595]', 'inflected', 'heb', 'אָנֹכִי', '["ʼânôkîy"]', '["and/ I"]', '["p"]', 'I I, me, × which.', 'sometimes, אָנֹכִי; a primitive pronoun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6185}/[H6209]', 'lemma', 'heb', 'עֲרִירִי', '["ʻărîyrîy"]', '["childless"]', '["a"]', 'bare, i.e. destitute (of children) childless.', 'from 6209;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121J}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ [the] son of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4943>', 'opaque', 'heb', 'מֶשֶׁק', '["mesheq"]', '["[the] acquisition of"]', '["n-m"]', 'possession steward.', 'from an unused root meaning to hold;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004M}/H9020/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[is] house/ my","[is] house?/ my","house/ my","household/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1834>', 'opaque', 'heb', 'דַּמֶּשֶׂק', '["Dammeseq"]', '["Damascus","[is] Damascus"]', '["n-pr-loc"]', 'Damascus, a city of Syria Damascus.', 'or דּוּמֶשֶׂק; or דַּרְמֶשֶׂק; of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0461G}/[H410]', 'lemma', 'heb', 'אֱלִיעֶזֶר', '["ʼĔlîyʻezer"]', '["Eliezer"]', '["n-pr-m"]', 'Eliezer, the name of a Damascene and of ten Israelites Eliezer.', 'from 410 and 5828; God of help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423G}/[H3423]', 'lemma', 'heb', 'יָרַשׁ', '["yârash"]', '["[does] an heir","[is] inheriting","[one] possessing","[the] possessor of","[who] possesses","he will inherit","it will possess","they may dispossess","they may possess","they possessed","they will possess","will you possess?","you may possess"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423G}/H9031/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["he will cause to possess/ you","he will inherit/ you"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3588B}/[H3588]', 'lemma', 'heb', 'כִּי', '["kîy"]', '["for","that"]', '["conj"]', '(by implication) very widely used as a relative conjunction or adverb (as below); often largely modified by other particles annexed and, (forasmuch, inasmuch, where-) as, assured(-ly), but, certainly, doubtless, else, even, except, for, how, (because, in, so, than) that, nevertheless, now, rightly, seeing, since, surely, then, therefore, (al-) though, till, truly, until, when, whether, while, whom, yea, yet.', 'a primitive particle (the full form of the prepositional prefix) indicating causal relations of all kinds, antecedent or consequent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0518B}/[H518]', 'lemma', 'heb', 'אִם', '["ʼim"]', '["except","if"]', '["prt"]', 'used very widely as demonstrative, lo!; interrogative, whether?; or conditional, if, although; also Oh that!, when; hence, as a negative, not (and, can-, doubtless, if, that) (not), + but, either, + except, + more(-over if, than), neither, nevertheless, nor, oh that, or, + save (only, -ing), seeing, since, sith, + surely (no more, none, not), though, + of a truth, + unless, + verily, when, whereas, whether, while, + yet.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H4578>/H9021', 'inflected', 'heb', 'ממעיך', '["mi./me.''Ei./kha"]', '["from/ inward parts/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318H}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ I brought out","and/ I will bring out","and/ he brought [them] out","and/ he brought out","and/ he has brought out","and/ he led out","and/ he made go out","and/ he sent out","and/ he took","and/ he will bring forth","and/ he will bring out","and/ he will go out","and/ he will send forth","and/ he will take [them] out","and/ he will take out","and/ it came out","and/ it will go out","and/ she took [it] out","and/ they brought out","and/ they will bring forth","and/ they will bring out","and/ you brought out","and/ you will bring [it] out","and/ you will bring out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2351>/H9011', 'inflected', 'heb', 'החוצה', '["ha./Chu.tza/h"]', '["the/ outside/ <towards>","the/ outside/ towards"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5027}/[H5027]', 'lemma', 'heb', 'נָבַט', '["nâbaṭ"]', '["I will look","I will look at","I will pay attention to","do you look at","do you look at?","does he see","he has looked","he has looked at","he looks","he sees","it will look","let them look","look","look at","pay attention","people look","they look","they pay attention to","to look","you look","you looked","you pay attention","you will look"]', '["v"]', 'to scan, i.e. look intently at; by implication, to regard with pleasure, favor or care (cause to) behold, consider, look (down), regard, have respect, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H8064>/H9011', 'inflected', 'heb', 'השמימה', '["ha./sha.Ma.ye.ma/h","ha./sha.May.ma/h"]', '["the/ heavens/ towards"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5608A}/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["and/ I may recount","and/ I will recount","and/ count","and/ let them recount","and/ may they recount [them]","and/ they may recount","so/ let me recount","so/ let us recount"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5608A}/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["to/ count","to/ measure [it]","to/ recount"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3541}/[H1931]', 'lemma', 'heb', 'כֹּה', '["kôh"]', '["[is] thus","there","thus"]', '["prt"]', 'properly, like this, i.e. by implication, (of manner) thus (or so); also (of place) here (or hither); or (of time) now also, here, hitherto, like, on the other side, so (and much), such, on that manner, (on) this (manner, side, way, way and that way), mean while, yonder.', 'from the prefix k and 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0539}/[H541]', 'inflected', 'heb', 'אָמַן', '["ʼâman"]', '["and/ he believed","and/ he trusted","and/ it believed","and/ it will be established","and/ they believed","and/ they will believe"]', '["v"]', 'properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right.', 'a primitive root; (Isaiah 30:21; interchangeable with 541, to go to the right hand)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3068G}/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["<in>/ Yahweh","[are] in/ Yahweh","[is] in/ Yahweh","against/ Yahweh","by/ Yahweh","for/ Yahweh","in/ Yahweh","on/ Yahweh","to/ Yahweh","with/ Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2803H}/H9034/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ he credited/ it"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6666}/[H6663]', 'lemma', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["<of> righteousness","<of> righteousness<es>","[the] righteousness of","[the] righteousness<es> of","righteousness","righteousness<es>"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318H}/H9031/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["I brought out/ you","he brought out/ you"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5414G}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["[was] to/ be given","by/ giving","by/ paying","to/ distribute","to/ give","to/ give [it]","to/ grant","to/ put","to/ requite"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3423H}/H9034/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["to/ take possession of/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4100}/[H4100]', 'inflected', 'heb', 'מָה', '["mâh"]', '["<in>/ how?","in/ what?","on/ what?","on/ whatever","with/ what?"]', '["i"]', 'properly, interrogative what? (including how? why? when?); but also exclamation, what! (including how!), or indefinitely what (including whatever, and even relatively, that which); often used with prefixes in various adverbial or conjunctive senses how (long, oft, (-soever)), (no-) thing, what (end, good, purpose, thing), whereby(-fore, -in, -to, -with), (for) why.', 'or מַה; or מָ; or מַ; also מֶה; a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423H}/H9034/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["I will take possession of/ it","he will dispossess/ it","it will take possession of/ it","they will take possession of/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947J}/H9012/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["bring/ !"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5697A}/[H5695]', 'lemma', 'heb', 'עֶגְלָה', '["ʻeglâh"]', '["[is] a heifer","[was] a heifer","a heifer","a heifer of"]', '["n-f"]', 'a (female) calf, especially one nearly grown (i.e. a heifer) calf, cow, heifer.', 'feminine of 5695;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8027}/[H7969]', 'lemma', 'heb', 'שָׁלַשׁ', '["shâlash"]', '["[were] divided into three parts","do a third time","three years old"]', '["v"]', 'to be (causatively, make) triplicate (by restoration, in portions, strands, days or years) do the third time, (divide into, stay) three (days, -fold, parts, years old).', 'a primitive root perhaps originally to intensify, i.e. treble; but apparently used only as denominative from 7969,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5795}/[H5810]', 'inflected', 'heb', 'עֵז', '["ʻêz"]', '["and/ a goat","and/ goat hair<s>"]', '["n-f"]', 'a she-goat (as strong), but masculine in plural (which also is used elliptically for goat''s hair) (she) goat, kid.', 'from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0352A}/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["and/ [the] rams of","and/ a ram","and/ rams"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8449}/[H8447]', 'inflected', 'heb', 'תּוֹר', '["tôwr"]', '["and/ a turtle-dove"]', '["n-f"]', 'a ring-dove, often (figuratively) as a term of endearment (turtle) dove.', 'or תֹּר; probably the same as 8447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1469}/[H1497]', 'inflected', 'heb', 'גּוֹזָל', '["gôwzâl"]', '["and/ a young pigeon"]', '["n-m"]', 'a nestling (as being comparatively nude of feathers) young (pigeon).', 'or (shortened) גֹזָלlemma גזָל missing vowel, corrected to גֹזָל; from 1497;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947J}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ I will fetch","and/ he brought","and/ he took","and/ it will be taken","and/ people took [it]","and/ she took","and/ they took","and/ they took [it]","and/ you will take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1334}/[H1334]', 'inflected', 'heb', 'בָּתַר', '["bâthar"]', '["and/ he cut in pieces"]', '["v"]', 'to chop up divide.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1335}/H9023/[H1334]', 'inflected', 'heb', 'בֶּתֶר', '["bether"]', '["piece/ its","pieces/ its"]', '["n-m"]', 'a section part, piece.', 'from 1334;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122H}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6833}/[H6852]', 'inflected', 'heb', 'צִפּוֹר', '["tsippôwr"]', '["<the>/ bird","the/ bird","the/ bird[s]"]', '["n-f"]', 'a little bird (as hopping) bird, fowl, sparrow.', 'or צִפֹּר; from 6852;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1334}/[H1334]', 'lemma', 'heb', 'בָּתַר', '["bâthar"]', '["he cut in two"]', '["v"]', 'to chop up divide.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5861}/[H5860]', 'inflected', 'heb', 'עַיִט', '["ʻayiṭ"]', '["the/ bird[s] of prey"]', '["n-m"]', 'a hawk or other bird of prey bird, fowl, ravenous (bird).', 'from 5860;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6297}/[H6296]', 'inflected', 'heb', 'פֶּגֶר', '["peger"]', '["the/ carcasses","the/ corpse[s]","the/ corpses"]', '["n-m"]', 'a carcase (as limp), whether of man or beast; figuratively, an idolatrous image carcase, corpse, dead body.', 'from 6296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5380}/[H5380]', 'inflected', 'heb', 'נָשַׁב', '["nâshab"]', '["and/ he drove away"]', '["v"]', 'to blow; by implication, to disperse (cause to) blow, drive away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H8121>', 'inflected', 'heb', 'השמש', '["Ha./she.mesh","ha./Sha.mesh","ha./She.mesh","ha./she.Mesh"]', '["<of> the/ sun","the/ sun"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8639}/[H7290]', 'inflected', 'heb', 'תַּרְדֵּמָה', '["tardêmâh"]', '["and/ a deep sleep"]', '["n-f"]', 'a lethargy or (by implication) trance deep sleep.', 'from 7290;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0367}/[H366]', 'lemma', 'heb', 'אֵימָה', '["ʼêymâh"]', '["[is] terror","[the] terror of","dread","terror","terrors"]', '["n-f"]', 'fright; concrete, an idol (as a bugbear) dread, fear, horror, idol, terrible, terror.', 'or (shortened) אֵמָה; from the same as 366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2825}/[H2821]', 'lemma', 'heb', 'חֲשֵׁכָה', '["chăshêkâh"]', '["darkness","darkness<es>"]', '["n-f"]', 'darkness; figuratively, misery darkness.', 'or חֲשֵׁיכָהxlit chăshêkâh corrected to chăshêykâh; from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1616}/[H1481]', 'lemma', 'heb', 'גֵּר', '["gêr"]', '["<of> a sojourner","[am] a sojourner","[are] sojourners","[the] sojourner","a sojourner","sojourners"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5647G}/H9038/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ they served/ them","and/ they will serve/ them","and/ you will serve/ them"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6031B}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ they will afflict","and/ you will afflict","and/ you will humble"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7399}/[H7408]', 'inflected', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["with <the>/ property","with/ possession[s]","with/ property"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7965G}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["in/ peace","in/ safety","with <the>/ peace"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6912}/[H6912]', 'lemma', 'heb', 'קָבַר', '["qâbar"]', '["I buried","I will be buried","[is] buried","[was one who] buried [them]","[were] burying","[who] bury","[will be one who] buries [her]","a burier","being buried","bury","certainly <to bury>","he buried","he was buried","he will be buried","people buried","people will bury","they buried","they have buried","they will be buried","you will be buried"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7872}/[H7869]', 'inflected', 'heb', 'שֵׂיבָה', '["sêybâh"]', '["in/ old age"]', '["n-f"]', 'old age (be) gray (grey hoar,-y) hairs (head,-ed), old age.', 'feminine of 7869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1755}/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["and/ [the] generation","and/ a generation","and/ generation"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7243}/[H7251]', 'lemma', 'heb', 'רְבִיעִי', '["rᵉbîyʻîy"]', '["<the> fourth of","[the] fourth [generation]","[the] fourth of","[will be] [the] fourth of","a fourth","a fourth [generation]","fourth"]', '["a"]', 'fourth; also (fractionally) a fourth foursquare, fourth (part).', 'or רְבִעִי; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2008}/[H2004]', 'lemma', 'heb', 'הֵנָּה', '["hênnâh"]', '["<of> them","here","hither","now"]', '["adv"]', 'hither or thither (but used both of place and time) here, hither(-to), now, on this (that) side, since, this (that) way, thitherward, thus far, to...fro, yet.', 'from 2004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8003}/[H7999]', 'lemma', 'heb', 'שָׁלֵם', '["shâlêm"]', '["[are] at peace","[is] complete","[was] complete","complete","full","perfect","safe"]', '["a"]', 'complete (literally or figuratively); especially friendly full, just, made ready, peaceable, perfect(-ed), quiet, Shalem (by mistake for a name), whole.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771G}/[H5753]', 'lemma', 'heb', 'עָוֺן', '["ʻâvôn"]', '["[are] iniquities","[is] iniquity","[the] guilt of","[the] iniquities of","[the] iniquity of","iniquities","iniquity","iniquity of"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5939>', 'inflected', 'heb', 'ועלטה', '["va./''a.la.Tah"]', '["and/ darkness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8574H}/[H5216]', 'lemma', 'heb', 'תַּנּוּר', '["tannûwr"]', '["a fire pot of","an oven"]', '["n-m"]', 'a fire-pot furnace, oven.', 'from 5216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6227}/[H6225]', 'lemma', 'heb', 'עָשָׁן', '["ʻâshân"]', '["[are] smoke","[the] smoke of","smoke"]', '["n-m"]', 'smoke, literally or figuratively (vapor, dust, anger) smoke(-ing).', 'from 6225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3940>', 'inflected', 'heb', 'ולפדים', '["ve./la.Pid","ve./la.pi.Dim"]', '["and/ a torch of","and/ torches"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0784}/[H784]', 'lemma', 'heb', 'אֵשׁ', '["ʼêsh"]', '["<of> a fire","O fire","[is] a fire","[is] fire","[the] fire of","a fire","a fire of","fire"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674A}/[H5674]', 'lemma', 'heb', 'עָבַר', '["ʻâbar"]', '["I passed","I passed by","I passed on","I passed over","I will cause to pass","I will cause to pass away","I will cause to pass by","I will pass","I will pass beyond","I will pass by","I will pass over","[am] about to pass over","[are] about to pass","[are] about to pass over","[are] passing","[is] about to pass on","[is] about to pass over","[is] to pass","[one who] makes pass","[one who] passed by","[one who] passes by","[one who] passes by of","[one who] passes through","[one who] will send through","[that which] passes through","[those who] pass","[those who] pass by","[those who] pass by of","[was one who] passed through","[was] passing","[was] passing by","[was] passing over","[were] passing along","[were] passing by","[were] passing on","[were] passing over","[which are] spreading","[which] it passed","[which] passes away","[which] they have passed away","[which] they pass away","[who] pass","[who] passed over","[who] passes by","[who] passes through","[who] was passing by","[will be one who] passes","cause to pass away","certainly <to pass over>","did it pass on","did you pass over","flowing","he had passed away","he had passed over","he has let pass by","he has passed","he he passed on","he made pass","he passed","he passed by","he passed on","he passed over","he passes on","he will pass","he will pass by","he will pass on","he will pass over","it had passed","it has passed","it has passed away","it has passed by","it has passed over","it has passed through","it impregnates","it passed","it passed beyond","it passed on","it passed over","it passes","it passes away","it passes by","it passes on","it was passed through","it will pass","it will pass away","it will pass by","it will pass on","let him pass on","let him pass over","let it pass","let me pass","let me pass over","let me pass through","let us pass","one will make pass over","pass","pass on","pass over","pass through","passing","passing along","passing by","passing on","they have passed","they have passed over","they made pass through","they pass on","they pass over","they passed","they passed away","they passed on","they passed over","they will pass","they will pass away","they will pass over","to pass","to pass by","to pass on","we passed","we passed over","we will pass","we will pass over","we will pass through","will he pass over","will it pass","you have passed","you have passed by","you must pass on","you must pass over","you pass along","you pass by","you pass over","you passed through","you will cause to pass","you will make pass","you will pass","you will pass beyond","you will pass on","you will pass over","you will pass through"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1506}/[H1504]', 'inflected', 'heb', 'גֶּזֶר', '["gezer"]', '["the/ pieces"]', '["n-m"]', 'something cut off; a portion part, piece.', 'from 1504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3772H}/[H3772]', 'lemma', 'heb', 'כָּרַת', '["kârath"]', '["I cut","I had made","I have made","I made","I will make","[am] about to make","[am] making","[are] making","[is] making","[those who] made","he had made","he has made","he made","let us make","made","make","they are making","they had made","they have made","they made","we have made","will I make","you must make","you should make","you will make"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5104H}/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["from/ [the] river of"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5104H}/[H5102]', 'lemma', 'heb', 'נָהָר', '["nâhâr"]', '["[the] river","[the] river of","[the] rivers","[the] rivers of","a river","rivers","rivers of"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7017}/[H7014]', 'inflected', 'heb', 'קֵינִי', '["Qêynîy"]', '["the/ Kenite","the/ Kenite[s]","the/ Kenites"]', '["a"]', 'a Kenite or member of the tribe of Kajin Kenite.', 'or קִינִי; (1 Chronicles 2:55), patronymic from 7014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7074G}/[H7073]', 'inflected', 'heb', 'קְנִזִּי', '["Qᵉnizzîy"]', '["the/ Kenizzite[s]"]', '["n-pr-m"]', 'a Kenizzite or descendant of Kenaz Kenezite, Kenizzites.', 'patronymic from 7073,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6935}/[H6931]', 'inflected', 'heb', 'קַדְמֹנִי', '["Qadmônîy"]', '["the/ Kadmonite[s]"]', '["a"]', 'Kadmonite (collectively), the name of a tribe in Palestine Kadmonites.', 'the same as 6931; ancient, i.e. aboriginal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2850}/[H2845]', 'inflected', 'heb', 'חִתִּי', '["Chittîy"]', '["the/ Hethite","the/ Hittite","the/ Hittite[s]","the/ Hittites"]', '["n-m"]', 'a Chittite, or descendant of Cheth Hittite, Hittities.', 'patronymically from 2845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6522}/[H6521]', 'inflected', 'heb', 'פְּרִזִּי', '["Pᵉrizzîy"]', '["the/ Perizzite[s]"]', '["a"]', 'a Perizzite, one of the Canaanitish tribes Perizzite.', 'for 6521; inhabitant of the open country;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7497B}/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["the/ Rephaites"]', '["n-pr-m"]', 'a giant giant, Rapha, Rephaim(-s). See also 1051.', 'or רָפָה; from 7495 in the sense of invigorating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2983G}\/[H2982]', 'inflected', 'heb', 'יְבוּסִי', '["Yᵉbûwçîy"]', '["the/ Jebusite","the/ Jebusite[s]"]', '["n-m"]', 'a Jebusite or inhabitant of Jebus Jebusite(-s).', 'patrial from 2982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8297}/[H8269]', 'inflected', 'heb', 'שָׂרַי', '["Sâray"]', '["and/ Sarai"]', '["n-pr-f"]', 'Sarai, the wife of Abraham Sarai.', 'from 8269; dominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H9034}', 'inflected', 'arc', 'ולה', '["ve./La/h"]', '["and/ [belonged] to <the>/ her","and/ [belonged] to <the>/ it","and/ to <the>/ her","and/ to/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8198>', 'opaque', 'heb', 'שִׁפְחָה', '["shiphchâh"]', '["[is] a female slave","[the] maidservant of","a female slave","a maidservant"]', '["n-f"]', 'a female slave (as a member of the household) (bond-, hand-) maid(-en, -servant), wench, bondwoman, womanservant.', 'feminine from an unused root meaning to spread out (as a family; see 4940);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4713}/[H4714]', 'lemma', 'heb', 'מִצְרִי', '["Mitsrîy"]', '["Egypt","Egyptian","an Egyptian"]', '["a"]', 'a Mitsrite, or inhabitant of Mitsrajim Egyptian, of Egypt.', 'from 4714;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8034}/H9024/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["and/ name/ her"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1904}/[H1904]', 'lemma', 'heb', 'הָגָר', '["Hâgâr"]', '["Hagar","O Hagar","[was] Hagar"]', '["n-pr-f"]', 'Hagar, the mother of Ishmael Hagar.', 'of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6113}/H9030/[H6113]', 'inflected', 'heb', 'עָצָר', '["ʻâtsâr"]', '["he has restrained/ me","you will detain/ me"]', '["v"]', 'to inclose; by analogy, to hold back; also to maintain, rule, assemble × be able, close up, detain, fast, keep (self close, still), prevail, recover, refrain, × reign, restrain, retain, shut (up), slack, stay, stop, withhold (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3205}/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["from/ bearing children","from/ child bearing"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8198>/H9020', 'opaque', 'heb', 'שִׁפְחָה', '["shiphchâh"]', '["maidservant/ my"]', '["n-f"]', 'a female slave (as a member of the household) (bond-, hand-) maid(-en, -servant), wench, bondwoman, womanservant.', 'feminine from an unused root meaning to spread out (as a family; see 4940);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0194}/[H176]', 'lemma', 'heb', 'אוּלַי', '["ʼûwlay"]', '["perhaps"]', '["adv"]', 'if not; hence perhaps if so be, may be, peradventure, unless.', 'or (shortened) אֻלַי; from 176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8198>/H9024', 'opaque', 'heb', 'שִׁפְחָה', '["shiphchâh"]', '["maidservant/ her"]', '["n-f"]', 'a female slave (as a member of the household) (bond-, hand-) maid(-en, -servant), wench, bondwoman, womanservant.', 'feminine from an unused root meaning to spread out (as a family; see 4940);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0376H>/H9024', 'opaque', 'heb', 'אִישׁ', '["ʼîysh"]', '["[am] husband/ her","husband/ her"]', '["n-m"]', 'a man as an individual or a male person; often used as an adjunct to a more definite term (and in such cases frequently not expressed in translation) also, another, any (man), a certain, champion, consent, each, every (one), fellow, (foot-, husband-) man, (good-, great, mighty) man, he, high (degree), him (that is), husband, man(-kind), none, one, people, person, steward, what (man) soever, whoso(-ever), worthy. Compare 802.', 'contracted for 582 (or perhaps rather from an unused root meaning to be extant);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2029}/[H2029]', 'lemma', 'heb', 'הָרָה', '["hârâh"]', '["did I conceive","he has been conceived","she had conceived","they conceive","we have conceived","we were pregnant","you will conceive"]', '["v"]', 'to be (or become) pregnant, conceive (literally or figuratively) been, be with child, conceive, progenitor.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7043}/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["and/ I have become insignificant","and/ I will demean myself","and/ he cursed","and/ it will be trifling","and/ it will curse","and/ she became insignificant","and/ they are swift","and/ they cursed"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1404}/H9024/[H1376]', 'inflected', 'heb', 'גְּבֶרֶת', '["gᵉbereth"]', '["mistress/ her"]', '["n-f"]', 'mistress lady, mistress.', 'feminine of 1376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869H}/H9024/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ her"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2555}/H9020/[H2554]', 'inflected', 'heb', 'חָמָס', '["châmâç"]', '["injustice/ my","violence/ my"]', '["n-m"]', 'violence; by implication, wrong; by metonymy unjust gain cruel(-ty), damage, false, injustice, × oppressor, unrighteous, violence (against, done), violent (dealing), wrong.', 'from 2554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9031/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["[am] on/ you","[are] on/ you","[is] on/ you","[is] towards/ you","[will be] on/ you","above/ you","against/ you","at/ you","on/ you","on/ yourself","over/ you","over/ yourself","to/ you","towards/ you","with/ you"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2436G>/H9021', 'inflected', 'heb', 'בחיקך', '["be./chei.Ke./cha","ve./chei.Ke./cha"]', '["in/ bosom/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8199}/[H8199]', 'lemma', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["I entered into judgment","I will enter into judgment","I will judge","O judge of","O rulers of","[am] about to enter into judgment with","[am] about to judge","[is one who] enters into judgment","[is the] judge","[is] a judge","[is] about to enter into judgment","[is] judge","[one who] judges","[the] judge of","[the] judges of","[the] judging of","[was] judging","[who] enters into judgment","[who] judges","[will] enter into judgment","a judge","continuously <to judge>","do you judge?","give judgment for","he gave judgment","he gives judgment","he had judged","he judged","he judges","he will judge","judge","judges","judges of","judging","let them be judged","let us enter into judgment","may he judge","may they judge","rulers of","they have judged","they judge","they judged","they vindicate","they will judge","vindicate","will he judge","will you enter into judgment","will you judge","you judge","you will judge"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8198>/H9022', 'opaque', 'heb', 'שִׁפְחָה', '["shiphchâh"]', '["maidservant/ your"]', '["n-f"]', 'a female slave (as a member of the household) (bond-, hand-) maid(-en, -servant), wench, bondwoman, womanservant.', 'feminine from an unused root meaning to spread out (as a family; see 4940);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027H}/H9022/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[is] in/ hand/ your","in/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2896A}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["<the>/ fine","<the>/ good","the/ good","the/ good [thing]"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869I}/H9022/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6031B}/H9034/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ he humbled/ her","and/ he humiliated/ her","and/ she afflicted/ her"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1272}/[H1272]', 'inflected', 'heb', 'בָּרַח', '["bârach"]', '["and/ he fled","and/ he ran away","and/ she fled","and/ they fled","and/ they had fled","and/ they put to flight"]', '["v"]', 'to bolt, i.e. figuratively, to flee suddenly chase (away); drive away, fain, flee (away), put to flight, make haste, reach, run away, shoot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440G}/H9024/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ before/ her"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4672}/H9034/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["and/ he found/ her","and/ he found/ it","and/ he will find/ her","and/ you will find/ it"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4397H>', 'opaque', 'heb', 'מַלְאָךְ', '["malʼâk"]', '["<the> angel of","[is] an angel","[the] angel of","[the] angels of","[was] [the] angel","[was] [the] angel of","an angel","angels of"]', '["n-m"]', 'a messenger; specifically, of God, i.e. an angel (also a prophet, priest or teacher) ambassador, angel, king, messenger.', 'from an unused root meaning to despatch as a deputy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869M}/[H5869]', 'lemma', 'heb', 'עַיִן', '["ʻayin"]', '["[the] spring of","[the] springs of","a spring","springs","springs of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4057B}/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["[is] in the/ wilderness","[is] in/ [the] wilderness of","[was] in/ [the] wilderness of","[were] in/ [the] wilderness of","in the/ wilderness","in/ [the] wilderness of"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5869M}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["the/ spring","the/ springs"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870K}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["<in> the/ way","[is] in the/ road","by the/ way","by/ a way","in the/ road","in the/ way","in/ a direction","on the/ journey","on the/ road","on the/ way","on/ [the] way of","on/ a path"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7793}/[H7791]', 'lemma', 'heb', 'שׁוּר', '["Shûwr"]', '["Shur"]', '["n-pr-loc"]', 'Shur, a region of the Desert Shur.', 'the same as 7791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2088}/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["from/ here","from/ this","from/ this [field]","more than/ this","more than/ this one","some of/ this"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0575}/[H370]', 'inflected', 'heb', 'אָן', '["ʼân"]', '["and/ where?"]', '["adv"]', 'where?; hence, whither?, when?; also hither and thither any (no) whither, now, where, whither(-soever).', 'or אָנָה; contracted from 370;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440L}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ <the face of>","from/ before","of/ <the face of>"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1404}/H9020/[H1376]', 'inflected', 'heb', 'גְּבֶרֶת', '["gᵉbereth"]', '["mistress/ my"]', '["n-f"]', 'mistress lady, mistress.', 'feminine of 1376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1272}/[H1272]', 'lemma', 'heb', 'בָּרַח', '["bârach"]', '["[am] fleeing","[is] fleeing","[was] fleeing","[will be] passing through","certainly","flee","hasten","he drives away","he fled","he had fled","he has fled","he will flee","it had fled","they fled","they had fled","they have fled","they put to flight","will I flee","will he flee"]', '["v"]', 'to bolt, i.e. figuratively, to flee suddenly chase (away); drive away, fain, flee (away), put to flight, make haste, reach, run away, shoot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1404}/H9022/[H1376]', 'inflected', 'heb', 'גְּבֶרֶת', '["gᵉbereth"]', '["mistress/ your"]', '["n-f"]', 'mistress lady, mistress.', 'feminine of 1376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6031B}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ afflict","and/ afflicted","and/ humble yourself","so/ I may afflicted"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027K}/H9024/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hands/ her"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2233H}/H9022/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["offspring/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5608A}/[H5608]', 'lemma', 'heb', 'סָפַר', '["çâphar"]', '["I count","I may recount","I recount","I recounted","I will recount","I will speak","[are] recounting","[is one who] counted","[was] recounting","[which] they speak","count","does he count?","he had counted","he will count","it had been recounted","it will be counted","it will be recounted","it will recount","let him recount","people recount","people will count","recount","recount [it]","recounting","they have recounted","they may recount","they recount","they recounted","they speak","they were counted","to recount","we will recount","will he count","will you count?","you counted","you have taken account of","you may recount","you may recount [it]","you will count"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7230}/[H7231]', 'inflected', 'heb', 'רֹב', '["rôb"]', '["from/ [the] abundance of","from/ [the] greatness of","from/ [the] multitude of","from/ a multitude of","from/ abundance","from/ abundance of","from/ greatness of","from/ multitude","more than/ greatness of"]', '["n-m"]', 'abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age).', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2009}/H9042/[H2005]', 'inflected', 'heb', 'הִנֵּה', '["hinnêh"]', '["here/ you"]', '["dp"]', 'lo! behold, lo, see.', 'prolongation for 2005;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2030A}/[H2029]', 'lemma', 'heb', 'הָרֶה', '["hâreh"]', '["[am] pregnant","[are] pregnant","[she is] pregnant","[the] pregnant","[the] pregnant [women] of","[was] pregnant","[was] pregnant of","[will be] pregnant","a pregnant [woman]","pregnant"]', '["a-f"]', 'pregnant (be, woman) with child, conceive, × great.', 'or הָרִי; (Hosea 14:1), from 2029;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3205}/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["and/ [one who] begets","and/ [one] giving birth","and/ [will] bear","and/ father","and/ he fathered","and/ they bring forth","and/ they give birth to","and/ you will bear","so/ she may bear children","so/ they may bear"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3458G}/[H8085]', 'lemma', 'heb', 'יִשְׁמָעֵאל', '["Yishmâʻêʼl"]', '["Ishmael"]', '["n-pr-m"]', 'Jishmael, the name of Abraham''s oldest son, and of five Israelites Ishmael.', 'from 8085 and 410; God will hear;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6040}/H9022/[H6031]', 'inflected', 'heb', 'עֳנִי', '["ʻŏnîy"]', '["affliction/ your"]', '["n-m"]', 'depression, i.e. misery afflicted(-ion), trouble.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6501}/[H6500]', 'lemma', 'heb', 'פֶּרֶא', '["pereʼ"]', '["[the] wild donkey","a wild donkey","a wild donkey of","wild donkeys"]', '["n-m"]', 'the onager wild (ass).', 'or פֶּרֶה; (Jeremiah 2:24), from 6500 in the secondary sense of running wild;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3027G}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ [the] hand of","and/ [the] hands of","and/ a hand","and/ hands"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440G}/[H6437]', 'lemma', 'heb', 'פָּנִים', '["pânîym"]', '["[the] face","[the] face of","[the] faces of","[the] presence of","[the] surface of","before","face","presence"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1696G}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["[is] the/ [one which] speaks","[were] the/ [ones who] were speaking","the/ [one who] speaks","which/ speak","who/ are speaking together","who/ is speaking","who/ spoke","who/ was speaking"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/H9034/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["<to>/ her","against/ it","into/ her","into/ it","to/ her","to/ it"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0410G}/[H352]', 'lemma', 'heb', 'אֵל', '["ʼêl"]', '["<of> God","El","God","God of","O God","O God of","[am] God","[am] a God","[are] God","[are] a God","[are] a God of","[is] God","[is] a God","[is] a God of","[the] God","[the] God of","a God","a God of","of God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7210}/[H7200]', 'lemma', 'heb', 'רֳאִי', '["rŏʼîy"]', '["seeing","sight"]', '["n-m"]', 'sight, whether abstractly (vision) or concretely (a spectacle) gazingstock, look to, (that) see(-th).', 'from 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/<H1571>', 'inflected', 'heb', 'הגם', '["Ha./gam","ha./Gam","ha./gam"]', '["¿/ also"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1988}/[H1973]', 'lemma', 'heb', 'הֲלֹם', '["hălôm"]', '["here"]', '["adv"]', 'hither here, hither(-(to)), thither.', 'from the article (see 1973);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200G}/H9030/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["[is one who] sees/ me","[the] [one who] sees/ me","[those who] see/ me","do you make see/ me","he has shown/ me","he showed/ me","he will let look/ me","he will see/ me","he will show/ me","it saw/ me","let see/ me","may they see/ me","show/ me","they saw/ me","they see/ me","you have made see/ me","you look at/ me","you see/ me","you showed/ me"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0875}/[H874]', 'inflected', 'heb', 'בְּאֵר', '["bᵉʼêr"]', '["<to> the/ well","to/ [the] pit of"]', '["n-f"]', 'a pit; especially a well pit, well.', 'from 874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0883}/[H875]', 'lemma', 'heb', 'בְּאֵר לַחַי רֹאִי', '["Bᵉʼêr la-Chay Rôʼîy"]', '["Beer","Lahai","Roi"]', '["n-pr-loc"]', 'Beer-Lachai-Roi, a place in the Desert Beer-lahai-roi.', 'from 875 and 2416 (with prefix) and 7203; well of a living (One) my Seer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1260G}/[H1258]', 'lemma', 'heb', 'בֶּרֶד', '["Bered"]', '["Bered"]', '["n-pr-m n-pr-loc"]', 'Bered, the name of a place south of Palestine, also of an Israelite Bered.', 'from 1258; hail;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8084}/[H8083]', 'lemma', 'heb', 'שְׁמֹנִים', '["shᵉmônîym"]', '["[was] eighty","[were] eighty","eighty"]', '["a"]', 'eighty, also eightieth eighty(-ieth), fourscore.', 'or שְׁמוֹנִים; multiple from 8083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3205}/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["when/ bore","when/ fathered","when/ was born"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0087}\/[H48]', 'inflected', 'heb', 'אַבְרָם', '["ʼAbrâm"]', '["to/ Abram"]', '["n-pr-m"]', 'Abram, the original name of Abraham Abram.', 'contracted from 48; high father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7706}/[H7703]', 'lemma', 'heb', 'שַׁדַּי', '["Shadday"]', '["Almighty","[is the] Almighty","[the] Almighty"]', '["n-m"]', 'the Almighty Almighty.', 'from 7703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5414I}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ give over","so/ let me make"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3966}/[H181]', 'inflected', 'heb', 'מְאֹד', '["mᵉʼôd"]', '["with/ muchness"]', '["a"]', 'properly, vehemence, i.e. (with or without preposition) vehemently; by implication, wholly, speedily, etc. (often with other words as an intensive or superlative; especially when repeated) diligently, especially, exceeding(-ly), far, fast, good, great(-ly), × louder and louder, might(-ily, -y), (so) much, quickly, (so) sore, utterly, very ( much, sore), well.', 'from the same as 181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440H}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ his","face/ its","faces/ its","presence/ his"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0001G}/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["<into>/ a father","<into>/ a father of","<to>/ a father","for/ a father","of/ fathers","to/ [the] father of","to/ a father"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1995A}/[H1993]', 'lemma', 'heb', 'הָמוֹן', '["hâmôwn"]', '["[are] a multitude","[the] abundance of","[the] din of","[the] multitude of","[the] noise of","[the] tumult of","a multitude","a multitude of","a tumult","a tumult of","tumult"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1471A}/[H1465]', 'lemma', 'heb', 'גּוֹי', '["gôwy"]', '["<of> a nation","O nations","[are] a nation","[is] a nation","[the] nation","[the] nation of","[the] nations","[the] nations of","a nation","a nation of","nation","nations"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0085>', 'opaque', 'heb', 'אַבְרָהָם', '["ʼAbrâhâm"]', '["Abraham","O Abraham"]', '["n-pr-m"]', 'Abraham, the later name of Abram Abraham.', 'contracted from 1 and an unused root (probably meaning to be populous); father of a multitude;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414I}/H9031/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["I appoint/ you","I have appointed/ you","I have made/ you","I will make/ you","[am] about to make/ you","have we made/ you","he has made/ you","will I make/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414I}/H9031/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I made/ you","and/ I will make/ you","and/ he has appointed/ you","and/ he will make/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4480A}/H9031/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["[are] from/ you","[is] from/ you","for/ you","from/ you","from/ yourself","more than/ you","some of/ you"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310A}/H9031/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["[am] after/ you","after/ you","behind/ you"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1755}/H9028/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["for/ generations/ their","to/ generations/ their"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1285}/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["<into>/ a covenant of","to the/ covenant","to/ a covenant of"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0430G}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["<into>/ God","<into>/ a god","<to>/ [the] God of","[belong] to/ God","[belongs] to/ God","for/ God","for/ [the] God of","into/ god","of/ [the] God of","to/ God","to/ [the] God of"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4033}/H9021/[H1481]', 'inflected', 'heb', 'מָגוּר', '["mâgûwr"]', '["sojournings/ your"]', '["n-m"]', 'a temporary abode; by extension, a permanent residence dwelling, pilgrimage, where sojourn, be a stranger. Compare 4032.', 'or מָגֻר; from 1481 in the sense of lodging;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0272}/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["to/ a possession","to/ a possession of"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104G}/[H8104]', 'lemma', 'heb', 'שָׁמַר', '["shâmar"]', '["I have kept","I keep","I may keep","I will keep","[are those who] observe","[are] keeping","[one who] keeps","[the] keeper","[the] keepers of","[was] watching","[were] keeping","[which] keeps","[who] keeps","have you kept","he has kept","he kept","he observed","it keeps","it kept","keep","observe","people keep","she will keep","they have kept","they keep","they kept","they kept [it]","they may keep","they observe","they took care","they will keep","they will observe","to keep","we have kept","will you keep","you have kept","you have kept [them]","you have observed","you keep","you kept","you will keep","you will observe"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2233H}/H9021/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ offspring/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4135A}/[H4135]', 'lemma', 'heb', 'מוּל', '["mûwl"]', '["[are] circumcised","[man] circumcised","circumcise yourselves","circumcised","definitely <be circumcised>","he circumcised","he was circumcised","he will be circumcised","it will be circumcised","it withers","people had circumcised","they were circumcised","they will be circumcised"]', '["v"]', 'to cut short, i.e. curtail (specifically the prepuce, i.e. to circumcise); by implication, to blunt; figuratively, to destroy circumcise(-ing), selves), cut down (in pieces), destroy, × must needs.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4135A}/[H4135]', 'inflected', 'heb', 'מוּל', '["mûwl"]', '["and/ he circumcised","and/ he will circumcise","and/ they were circumcised","and/ you will be circumcised","and/ you will circumcise"]', '["v"]', 'to cut short, i.e. curtail (specifically the prepuce, i.e. to circumcise); by implication, to blunt; figuratively, to destroy circumcise(-ing), selves), cut down (in pieces), destroy, × must needs.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6190H}/H9026/[H6189]', 'inflected', 'heb', 'עׇרְלָה', '["ʻorlâh"]', '["foreskin/ your"]', '["n-f"]', 'the prepuce foreskin, uncircumcised.', 'feminine of 6189;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121L}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ a son of","and/ a young one of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1755}/H9026/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["for/ generations/ your","to/ generations/ your"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4736}/[H4735]', 'inflected', 'heb', 'מִקְנָה', '["miqnâh"]', '["and/ [the] purchase of","and/ a purchase of"]', '["n-f"]', 'properly, a buying, i.e. acquisition; concretely, a piece of property (land or living); also the sum paid (he that is) bought, possession, piece, purchase.', 'feminine of 4735;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3701G}/[H3700]', 'lemma', 'heb', 'כֶּסֶף', '["keçeph"]', '["[are] silver","[is] silver","[the] money","[the] money of","[the] silver of","[was] silver","[were] silver","[will be] silver","money","money of","silver","silver of"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5236}/[H5234]', 'lemma', 'heb', 'נֵכָר', '["nêkâr"]', '["<the> foreignness of","foreignness"]', '["n-m"]', 'foreign, or (concretely) a foreigner, or (abstractly) heathendom alien, strange ( -er).', ''' from 5234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2233H}/H9021/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["[is] one of/ offspring/ your","from/ offspring/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3701G}/H9021/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["silver/ your"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1320}/H9026/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["in/ flesh/ your"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6189}/[H6188]', 'inflected', 'heb', 'עָרֵל', '["ʻârêl"]', '["and/ an uncircumcised","and/ uncircumcised of"]', '["a"]', 'properly, exposed, i.e. projecting loose (as to the prepuce); used only technically, uncircumcised (i.e. still having the prepuce uncurtailed) uncircumcised (person).', 'from 6188;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6190H}/H9023/[H6189]', 'inflected', 'heb', 'עׇרְלָה', '["ʻorlâh"]', '["foreskin/ his","foreskin/ its"]', '["n-f"]', 'the prepuce foreskin, uncircumcised.', 'feminine of 6189;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3772I}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ I cut off","and/ I will cut off","and/ he cut off","and/ he will be cut off","and/ it has been cut off","and/ it will be cut off","and/ it will cut off","and/ they cut off","and/ they will be cut off","and/ they will cut off","and/ you will be cut off"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5971B}/H9024/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["from/ kinspeople<s>/ its"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6565A}\/[H6565]', 'inflected', 'heb', 'פָּרַר', '["pârar"]', '["he has broken"]', '["v"]', 'to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8283}/[H8282]', 'lemma', 'heb', 'שָׂרָה', '["Sârâh"]', '["Sarah","[is] Sarah"]', '["n-pr-f"]', 'Sarah, Abraham''s wife Sarah.', 'the same as 8282;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1288}/H9034/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["and/ I will bless/ her"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6711}/[H6711]', 'inflected', 'heb', 'צָחַק', '["tsâchaq"]', '["and/ he laughed","and/ he made sport","and/ she laughed"]', '["v"]', 'to laugh outright (in merriment or scorn); by implication, to sport laugh, mock, play, make sport.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3820A}/H9023/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["[are] in/ heart/ his","[is] in/ heart/ his","in/ heart/ his","in/ own heart/ his"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H1121L}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["¿/ to/ a son of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1323G}/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["¿/ a daughter of"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3863}/[H3863]', 'lemma', 'heb', 'לוּא', '["lûwʼ"]', '["<if>","if"]', '["conj"]', 'a conditional particle; if; by implication (interj. as a wish) would that! if (haply), peradventure, I pray thee, though, I would, would God (that).', 'or לֻא; or לוּ;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0061}/[H56]', 'lemma', 'heb', 'אֲבָל', '["ʼăbâl"]', '["but","indeed"]', '["adv"]', 'nay, i.e. truly or yet but, indeed, nevertheless, verily.', 'apparently from 56 through the idea of negation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3327}/[H6711]', 'lemma', 'heb', 'יִצְחָק', '["Yitschâq"]', '["Isaac"]', '["n-pr-m"]', 'Jitschak (or Isaac), son of Abraham Isaac. Compare 3446.', 'from 6711; laughter (i.e. mochery);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2233H}/H9023/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["for/ offspring/ his","to/ offspring/ his"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310A}/H9033/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["[was] after/ him","[was] behind/ him","[were] after/ him","after/ him","after/ it","behind/ him","behind/ it"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3458G}/[H8085]', 'inflected', 'heb', 'יִשְׁמָעֵאל', '["Yishmâʻêʼl"]', '["and/ to/ Ishmael"]', '["n-pr-m"]', 'Jishmael, the name of Abraham''s oldest son, and of five Israelites Ishmael.', 'from 8085 and 410; God will hear;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085G}/H9031/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["I had heard of/ you","I have heard/ you","I will cause to hear/ you","he caused to hear/ you"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5387A}/[H5375]', 'lemma', 'heb', 'נָשִׂיא', '["nâsîyʼ"]', '["O princes of","[are] a prince of","[the] chief of","[the] leader","[the] leader of","[the] leaders of","[the] prince of","[the] princes of","[was] a leader","[were] [the] leaders of","[were] leaders","[will be] prince","a leader","a leader of","leader","leaders","leaders of","prince","prince of","princes","ruler"]', '["n-m"]', 'properly, an exalted one, i.e. a king or sheik; also a rising mist captain, chief, cloud, governor, prince, ruler, vapour.', 'or נָשִׂא; from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414I}/H9033/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will make/ him","and/ he made/ him"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4150G}/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["[is] for the/ appointed time","[is] to the/ appointed time","[it is] for/ [the] appointed time of","for/ appointed times","to the/ appointed place","to the/ appointed time","to the/ time","to/ [the] appointed time of","to/ a time"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0312}/[H309]', 'inflected', 'heb', 'אַחֵר', '["ʼachêr"]', '["<the>/ following","<the>/ other"]', '["a"]', 'properly, hinder; generally, next, other, etc. (an-) other man, following, next, strange.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1696G}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["by/ speaking","to/ speak","to/ speak [them]"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4736}/[H4735]', 'lemma', 'heb', 'מִקְנָה', '["miqnâh"]', '["[the] purchase of"]', '["n-f"]', 'properly, a buying, i.e. acquisition; concretely, a piece of property (land or living); also the sum paid (he that is) bought, possession, piece, purchase.', 'feminine of 4735;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3701G}/H9023/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["[is] money/ his","money/ his","silver/ his","silver/ its"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0582}/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["<in>/ a person","among the/ men","among/ [the] men of","among/ [the] people of","among/ men","among/ people of","in/ a person","of/ people of","with the/ men"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6190H}/H9028/[H6189]', 'inflected', 'heb', 'עׇרְלָה', '["ʻorlâh"]', '["foreskin/ their","foreskins/ their"]', '["n-f"]', 'the prepuce foreskin, uncircumcised.', 'feminine of 6189;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0085>', 'inflected', 'heb', 'ואברהם', '["ve./''Av.ra.Ham","ve./''av.ra.Ham"]', '["and/ Abraham"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4135A}/H9043/[H4135]', 'inflected', 'heb', 'מוּל', '["mûwl"]', '["when/ was circumcised/ he"]', '["v"]', 'to cut short, i.e. curtail (specifically the prepuce, i.e. to circumcise); by implication, to blunt; figuratively, to destroy circumcise(-ing), selves), cut down (in pieces), destroy, × must needs.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3458G}/[H8085]', 'inflected', 'heb', 'יִשְׁמָעֵאל', '["Yishmâʻêʼl"]', '["and/ Ishmael"]', '["n-pr-m"]', 'Jishmael, the name of Abraham''s oldest son, and of five Israelites Ishmael.', 'from 8085 and 410; God will hear;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0854}/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["[is] from/ with","from/ with"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9033\/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["with/ him"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6607}/[H6605]', 'lemma', 'heb', 'פֶּתַח', '["pethach"]', '["O doors of","[is at] [the] entrance of","[is] [the] entrance of","[the] door","[the] doors of","[the] doorway of","[the] doorways","[the] entrance","[the] entrance of","[the] opening of","[the] openings of","[were at] [the] entrance of","[were] [the] entrance of","an entrance","an opening","entrance"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0168G}/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["the/ tent"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2527}/[H2552]', 'inflected', 'heb', 'חֹם', '["chôm"]', '["like/ [the] heat of","like/ heat","when/ [the] heat of"]', '["n-m"]', 'heat heat, to be hot (warm).', 'from 2552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5324}/[H5324]', 'lemma', 'heb', 'נָצַב', '["nâtsab"]', '["[am] standing","[am] stationed","[are] standing","[he has] taken a stand","[he was] setting up","[he was] standing","[is] standing","[is] standing firm","[is] taking his stand","[was] placed","[was] standing","[were] standing","[which] stands","[will be] standing","a deputy","chief","he fixed","he set up","he will set up","it stood upright","overseers","set up","she stands","she stations herself","standing","they set","they stood up","you established","you have set"]', '["v"]', 'to station, in various applications (literally or figuratively) appointed, deputy, erect, establish, × Huzzah (by mistake for a proper name), lay, officer, pillar, present, rear up, set (over, up), settle, sharpen, establish, (make to) stand(-ing, still, up, upright), best state.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7323G}/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["and/ he ran","and/ it ran","and/ she ran","and/ they brought [them] quickly","and/ they ran","and/ they will run"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122G}/H9038/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ them"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6607}/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["from/ [the] door of","from/ [the] entrance of","from/ [the] opening of"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7812}/[H7812]', 'inflected', 'heb', 'שָׁחָה', '["shâchâh"]', '["and/ I bowed down","and/ I will bow down","and/ he bowed down","and/ he has bowed down","and/ he will bow down","and/ she bowed down","and/ they bowed down","and/ they have bowed down","and/ they will bow down","and/ you will bow down"]', '["v"]', 'to depress, i.e. prostrate (especially reflexive, in homage to royalty or God) bow (self) down, crouch, fall down (flat), humbly beseech, do (make) obeisance, do reverence, make to stoop, worship.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776H>/H9011', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["[the] earth/ towards","[the] ground/ towards","[was] ground/ towards"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0113>/H9020', 'opaque', 'heb', 'אָדוֹן', '["ʼâdôwn"]', '["Lord/ my","O lord/ my","O lords/ my","[is] lord/ my","[is] master/ my","lord/ my","master/ my"]', '["n-m"]', 'sovereign, i.e. controller (human or divine) lord, master, owner. Compare also names beginning with ''Adoni-''.', 'or (shortened) אָדֹן; from an unused root (meaning to rule);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869H}/H9021/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5650}/H9021/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["[am] servant/ your","[are] servants/ your","[is] servant/ your","[male] servant/ your","[will be] servant/ your","servant/ your","servants/ your"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947J}/[H3947]', 'lemma', 'heb', 'לָקַח', '["lâqach"]', '["I took","fetch","fetch [them]","get","it will seize","let it be brought","let us bring","take","you will take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4592}/[H4591]', 'lemma', 'heb', 'מְעַט', '["mᵉʻaṭ"]', '["[are] few","[is] a little","[the] fewness of","[the] little","[were] few","a few","a little","a little of","few","fewness","little"]', '["n-m"]', 'a little or few (often adverbial or comparative) almost (some, very) few(-er, -est), lightly, little (while), (very) small (matter, thing), some, soon, × very.', 'or מְעָט; from 4591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7364}/[H7364]', 'inflected', 'heb', 'רָחַץ', '["râchats"]', '["and/ wash"]', '["v"]', 'to lave (the whole or a part of a thing) bathe (self), wash (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7272}/H9026/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["feet/ your","foot/ your"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8172}/[H8172]', 'inflected', 'heb', 'שָׁעַן', '["shâʻan"]', '["and/ let him depend","and/ support yourself","so/ I may lean","so/ he may support himself"]', '["v"]', 'to support one''s self lean, lie, rely, rest (on, self), stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3947J}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ fetch","so/ he may fetch","so/ let me bring","so/ they may bring"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6595A}/[H6626]', 'lemma', 'heb', 'פַּת', '["path"]', '["a morsel","a morsel of","a piece of","crumbs"]', '["n-f"]', 'a bit meat, morsel, piece.', 'from 6626;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5582}/[H5582]', 'inflected', 'heb', 'סָעַד', '["çâʻad"]', '["and/ sustain <you>"]', '["v"]', 'to support (mostly figurative) comfort, establish, hold up, refresh self, strengthen, be upholden.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9026/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart/ your"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3588C}/[H3588]', 'lemma', 'heb', 'כִּי', '["kîy"]', '["for"]', '["conj"]', '(by implication) very widely used as a relative conjunction or adverb (as below); often largely modified by other particles annexed and, (forasmuch, inasmuch, where-) as, assured(-ly), but, certainly, doubtless, else, even, except, for, how, (because, in, so, than) that, nevertheless, now, rightly, seeing, since, surely, then, therefore, (al-) though, till, truly, until, when, whether, while, whom, yea, yet.', 'a primitive particle (the full form of the prepositional prefix) indicating causal relations of all kinds, antecedent or consequent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921B}/[H5920]', 'lemma', 'heb', 'עַל', '["ʻal"]', '["since"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3651B}/[H3559]', 'lemma', 'heb', 'כֵּן', '["kên"]', '["<thus>"]', '["adv"]', 'properly, set upright; hence (figuratively as adjective) just; but usually (as adverb or conjunction) rightly or so (in various applications to manner, time and relation; often with other particles) after that (this, -ward, -wards), as... as, (for-) asmuch as yet, be (for which) cause, following, howbeit, in (the) like (manner, -wise), × the more, right, (even) so, state, straightway, such (thing), surely, there (where) -fore, this, thus, true, well, × you.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5650}/H9026/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["[are] servants/ your","[male] servants/ your","servant/ your"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4116A}/[H4116]', 'inflected', 'heb', 'מָהַר', '["mâhar"]', '["and/ he hastened","and/ he hurried","and/ he made haste","and/ she hurried","and/ she made haste","and/ they hastened","and/ they hurried","and/ you will hurry"]', '["v"]', 'properly, to be liquid or flow easily, i.e. (by implication); to hurry (in a good or a bad sense); often used (with another verb) adverbially, promptly be carried headlong, fearful, (cause to make, in, make) haste(-n, -ily), (be) hasty, (fetch, make ready) × quickly, rash, × shortly, (be so) × soon, make speed, × speedily, × straightway, × suddenly, swift.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0168G}/H9011/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["the/ tent of/ towards","the/ tent/ towards"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4116A}/[H4116]', 'lemma', 'heb', 'מָהַר', '["mâhar"]', '["[surely] quickly","[which] hurry","bring quickly","did you hurry","hastening","hasty [people]","have you hastened","he hurried","he should hurry","he will hasten","hurry","it hasten","it is hasty","it will hasten","let it hurry","they acted quickly","they have made haste","they hurried after","they made haste","you had made haste","you will do quickly"]', '["v"]', 'properly, to be liquid or flow easily, i.e. (by implication); to hurry (in a good or a bad sense); often used (with another verb) adverbially, promptly be carried headlong, fearful, (cause to make, in, make) haste(-n, -ily), (be) hasty, (fetch, make ready) × quickly, rash, × shortly, (be so) × soon, make speed, × speedily, × straightway, × suddenly, swift.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5429>', 'opaque', 'heb', 'סְאָה', '["çᵉʼâh"]', '["a seah of","seahs","seahs of","two seahs"]', '["n-f"]', 'a seah, or certain measure (as determinative) for grain measure.', 'from an unused root meaning to define;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7058>', 'opaque', 'heb', 'קֶמַח', '["qemach"]', '["flour","flour of"]', '["n-m"]', 'flour flour, meal.', 'from an unused root probably meaning to grind;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5560>', 'opaque', 'heb', 'סֹלֶת', '["çôleth"]', '["fine flour","fine flour of"]', '["n-f"]', 'flour (as chipped off) (fine) flour, meal.', 'from an unused root meaning to strip;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3888}/[H3888]', 'lemma', 'heb', 'לוּשׁ', '["lûwsh"]', '["[are] kneading","knead [it]"]', '["v"]', 'to knead knead.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5692}/[H5746]', 'lemma', 'heb', 'עֻגָּה', '["ʻuggâh"]', '["a bread cake","a bread cake of","bread cakes"]', '["n-f"]', 'an ashcake (as round) cake (upon the hearth).', 'from 5746;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1241}/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["<the>/ cattle","the/ cattle","the/ herd","the/ herd[s]","the/ ox[en]"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7323G}/[H7323]', 'lemma', 'heb', 'רוּץ', '["rûwts"]', '["I run","I will run","[are] running","[is] running","[one who] ran","[was] running","[were] running","[who] ran","a runner","he may run","he ran","he runs","he will run","it runs","it will cause to run","let me run","let us run","run","running","they ran","they run","they will run","you have run","you will run"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121H}/[H1129]', 'lemma', 'heb', 'בֵּן', '["bên"]', '["[is] a son of","[the] son of","[the] sons of","[the] young of","[the] young one of","[the] young ones of","a son of","a young one of","sons of","young ones of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1241}/[H1239]', 'lemma', 'heb', 'בָּקָר', '["bâqâr"]', '["[the] cattle of","[the] herd","[were] cattle","cattle","herd","herd[s]","ox[en]","oxen"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7390}/[H7401]', 'lemma', 'heb', 'רַךְ', '["rak"]', '["[am] weak","[are] weak","[were] weak","a tender [shoot]","soft","soft [words]","tender"]', '["a"]', 'tender (literally or figuratively); by implication, weak faint((-hearted), soft, tender ((-hearted), one), weak.', 'from 7401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6213H}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["by/ making","to/ [one who] made","to/ do","to/ make","to/ prepare","to/ produce"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2529A}/[H2346]', 'lemma', 'heb', 'חֶמְאָה', '["chemʼâh"]', '["butter","curd<s>","curd<s> of"]', '["n-f"]', 'curdled milk or cheese butter.', 'or (shortened) חֵמָה; from the same root as 2346;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2461}/[H2459]', 'inflected', 'heb', 'חָלָב', '["châlâb"]', '["and/ milk","and/ milk of"]', '["n-m"]', 'milk (as the richness of kine) cheese, milk, sucking.', 'from the same as 2459;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121H}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ [the] young of","and/ [the] young one of","and/ sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440G}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ them","[is] <to>/ before/ them","[was] <to>/ before/ them","[were] <to>/ before/ them"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5975G}/[H5975]', 'lemma', 'heb', 'עָמַד', '["ʻâmad"]', '["I had set up","I have stood","I remained","I stand","I stationed","I stood up","I will stand","[am] standing","[are] standing","[he was] standing","[is] continuing","[is] enduring","[is] standing","[it was] standing","[was] holding upright","[was] standing","[were] standing","[were] staying","[who] will stand","[will be one who] stands","[will be] standing","[will] endure","are you standing","do you stand","enduring","has he stood","he had stood","he has stood","he has stopped","he remained","he remains","he stands","he stood","he will arise","he will make a stand","he will present himself","he will remain","he will stand","it endures","it has remained","it has stayed","it has stood","it has stood still","it remained","it remains","it stands","it stood still","it stopped","it will endure","it will remain","it will remain standing","it will stand","it will stay","let him stand","let them stand","let them stand up","let us stand","placed","remain","she had stopped","stand","stand still","standing","station","they had stood","they have remained","they have stood","they may remain","they remained","they stand","they stand forth","they stood","they stood still","they stood up","they will remain","they will stand","they will stand their ground","to endure","we will stand","will he stand","will we stand","you delay","you have appointed","you have stood","you made stand","you stand","you stand still","you stood","you stop","you will endure","you will stand"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0346}/[H335]', 'lemma', 'heb', 'אַיֵּה', '["ʼayêh"]', '["where?"]', '["adv"]', 'where? where.', 'prolonged from 335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6256}/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["about <the>/ this time","about the/ time","about/ [the] time of","like the/ time"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8283}/[H8282]', 'inflected', 'heb', 'שָׂרָה', '["Sârâh"]', '["[will belong] to/ Sarah","for/ Sarah","to/ Sarah"]', '["n-pr-f"]', 'Sarah, Abraham''s wife Sarah.', 'the same as 8282;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8283}/[H8282]', 'inflected', 'heb', 'שָׂרָה', '["Sârâh"]', '["and/ Sarah"]', '["n-pr-f"]', 'Sarah, Abraham''s wife Sarah.', 'the same as 8282;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2205H}/[H2204]', 'lemma', 'heb', 'זָקֵן', '["zâqên"]', '["<the> old of","[the] old","[were] old","an old [man]","an old [person]","old","old [man]","old [men]","old [people]"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935J}/[H935]', 'lemma', 'heb', 'בּוֹא', '["bôwʼ"]', '["I have come","[having] come","he had come","he had gone","you have come"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3117I>', 'inflected', 'heb', 'בימים', '["ba/i.ya.Mim","va/i.ya.Mim"]', '["in <the>/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2308}/[H2308]', 'lemma', 'heb', 'חָדַל', '["châdal"]', '["I will cease","cease","he ceased","he has ceased","he should cease","he will cease","it ceases","it had ceased","it has stopped","it will fail","let him refrain","refrain","they cease","they ceased","they have ceased","they will cease","they will refrain","we ceased","will I cease","will I desist","will I refrain","will we refrain","you will refrain"]', '["v"]', 'properly, to be flabby, i.e. (by implication) desist; (figuratively) be lacking or idle cease, end, fall, forbear, forsake, leave (off), let alone, rest, be unoccupied, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0734}/[H732]', 'lemma', 'heb', 'אֹרַח', '["ʼôrach"]', '["[is] a path","[the] caravans of","[the] path","[the] path of","[the] paths of","[the] way","[the] way of","a path","a way","path","path of","paths of","roads"]', '["n-m"]', 'a well-trodden road (literally or figuratively); also a caravan manner, path, race, rank, traveller, troop, (by-, high-) way.', 'from 732;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0802G}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["[are] like the/ women","like <the>/ women","like/ a woman"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130G}/H9024/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["[are] in/ midst/ its","[is] in/ midst/ its","in/ inner being/ her","in/ inward part[s]/ her","in/ midst/ its"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1086}/H9040/[H1086]', 'inflected', 'heb', 'בָּלָה', '["bâlâh"]', '["am worn out/ I"]', '["v"]', 'to fail; by implication to wear out, decay (causatively, consume, spend) consume, enjoy long, become (make, wax) old, spend, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5730B}/[H5727]', 'lemma', 'heb', 'עֵדֶן', '["ʻêden"]', '["pleasure"]', '["n-m"]', 'pleasure delicate, delight, pleasure. See also 1040.', 'or (feminine) עֶדְנָה; from 5727;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0113>/H9020', 'inflected', 'heb', 'ואדני', '["va./do.N/i"]', '["and/ lord/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2204}/[H2204]', 'lemma', 'heb', 'זָקֵן', '["zâqên"]', '["I am [too] old","I am old","he is old","he was old","he will be old","it will grow old","she is old","you are old","you have become old"]', '["v"]', 'to be old aged man, be (wax) old (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6711}/[H6711]', 'lemma', 'heb', 'צָחַק', '["tsâchaq"]', '["I laughed","[was] playing","did she laugh","he will laugh","mocking","you laughed"]', '["v"]', 'to laugh outright (in merriment or scorn); by implication, to sport laugh, mock, play, make sport.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0637}/[H637]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["¿/ also","¿/ even"]', '["prt"]', 'meaning accession (used as an adverb or conjunction); also or yea; adversatively though also, + although, and (furthermore, yet), but, even, + how much less (more, rather than), moreover, with, yea.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0552}/[H551]', 'lemma', 'heb', 'אֻמְנָם', '["ʼumnâm"]', '["really"]', '["adv"]', 'in (very) deed; of a surety.', 'an orthographical variation of 551');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6381}/[H6381]', 'inflected', 'heb', 'פָּלָא', '["pâlâʼ"]', '["¿/ is it [too] difficult"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3068G}/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["[are] from/ Yahweh","[is] from/ Yahweh","[was] from/ Yahweh","for/ Yahweh","from/ Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697I}/[H1696]', 'lemma', 'heb', 'דָּבָר', '["dâbâr"]', '["<the> matter of","[is] a thing","[is] anything","[the] matter","[the] matter of","[the] matter<s> of","[the] matters of","[the] thing of","[the] word of","[the] words of","a matter","a matter of","a thing","a thing of","a word","anything","matter","matter of","something","thing","things","words"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8283}/[H8282]', 'inflected', 'heb', 'שָׂרָה', '["Sârâh"]', '["and/ [will belong] to/ Sarah","and/ to/ Sarah"]', '["n-pr-f"]', 'Sarah, Abraham''s wife Sarah.', 'the same as 8282;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3584}/[H3584]', 'inflected', 'heb', 'כָּחַשׁ', '["kâchash"]', '["and/ I will deny","and/ he will deny","and/ it will deny","and/ she denied"]', '["v"]', 'to be untrue, in word (to lie, feign, disown) or deed (to disappoint, fail, cringe) deceive, deny, dissemble, fail, deal falsely, be found liars, (be-) lie, lying, submit selves.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8259}/[H8259]', 'inflected', 'heb', 'שָׁקַף', '["shâqaph"]', '["and/ he looked down","and/ she looked down","and/ they looked down"]', '["v"]', 'properly, to lean out (of a window), i.e. (by implication) peep or gaze (passively, be a spectacle) appear, look (down, forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/H9038/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[are] with/ them","[was] with <the>/ them","[were] with/ them","[will be] with/ them","with/ them"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7971G}/H9038/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["to/ send away/ them","to/ send off/ them"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3680}/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["¿/ [be] concealing"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0085>', 'inflected', 'heb', 'מאברהם', '["me./''av.ra.Ham"]', '["from/ Abraham"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6099}/[H6105]', 'inflected', 'heb', 'עָצוּם', '["ʻâtsûwm"]', '["and/ [are] numerous","and/ mighty","and/ numerous"]', '["a"]', 'powerful (specifically, a paw); by implication, numerous feeble, great, mighty, must, strong.', 'or עָצֻם; passive participle of 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9033/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["I have known/ him","[one who] knew/ him","[those who] knew/ him","acknowledge/ him","he knew/ him","it knows/ it","they knew/ it","will he inform?/ him","will he know/ it","you know/ him"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8104G}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ he kept","and/ he will keep","and/ they kept","and/ they will keep","and/ they will observe","and/ you have kept","and/ you will keep","and/ you will observe","and/ you will take care"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870G}/[H1869]', 'lemma', 'heb', 'דֶּרֶךְ', '["derek"]', '["[are] ways of","[is the] ways of","[is] [the] ways of","[is] a way","[the] way","[the] way of","[the] ways of","a way","a way of","of two ways","two ways","way","way of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4941H}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ [the] justice of","and/ a judgment","and/ judgments","and/ justice"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1696I}/[H1696]', 'lemma', 'heb', 'דָבַר', '["dâbar"]', '["I have spoken","I spoke","I will speak","[am] speaking","has he spoken","he had spoken","he has spoken","he said","he spoke","speak","you have spoken","you spoke"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2201}/[H2199]', 'lemma', 'heb', 'זַעַק', '["zaʻaq"]', '["[the] outcry of","a cry","a cry of","a cry of distress"]', '["n-f"]', 'a shriek or outcry cry(-ing).', 'and (feminine) זְעָקָהxlit zᵉâqâh corrected to zᵉʻâqâh; from 2199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7231}/[H7241]', 'lemma', 'heb', 'רָבַב', '["râbab"]', '["it is great","producing ten thousands","they abound","they are many","they have become many","they increase","they were many","they will be many"]', '["v"]', 'properly, to cast together , i.e. increase, especially in number; to multiply by the myriad increase, be many(-ifold), be more, multiply, ten thousands.', 'a primitive root; (compare 7241); also as denominative from 7233;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2403B}/H9028/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ sin/ their"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3513H}/[H3513]', 'lemma', 'heb', 'כָּבַד', '["kâbad"]', '["I have made heavy","I will make heavy","he has made heavy","he made heavy","it is heavy","it was heavy","it will be heavy","let it be heavy","make heavy","they are [too] heavy","they hardened","they made heavy","we will be heavy","will you harden","you made heavy"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9004/{H6818}/H9024/[H6817]', 'inflected', 'heb', 'צַעֲקָה', '["tsaʻăqâh"]', '["¿/ according to/ outcry/ its"]', '["n-f"]', 'a shriek cry(-ing).', 'from 6817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["<the>/ [one who] comes","<the>/ [one who] goes","<the>/ [one who] went","<the>/ [thing which] has come","<the>/ [thing which] was coming","<the>/ coming","[am] the/ [one who] comes","[are] the/ [ones who] go","[were] the/ [ones who] came","that/ <it> has come","that/ are coming","that/ it had come","that/ it went","the/ [one who] comes","the/ [one who] goes","the/ [one] bringing","the/ [ones who] were coming","the/ coming [things]","the/ coming [times]","those/ [who] are coming","those/ [who] go","those/ [who] had come","those/ coming","which/ came","which/ come","which/ goes","which/ had gone","which/ is coming","which/ was coming","which/ were coming","who/ are coming","who/ came","who/ come","who/ go","who/ had come","who/ had gone","who/ have come","who/ is about to come","who/ is coming","who/ went","who/ were coming"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3617}/[H3615]', 'lemma', 'heb', 'כָּלָה', '["kâlâh"]', '["complete destruction","completely","completion"]', '["n-f"]', 'a completion; adverb, completely; also destruction altogether, (be, utterly) consume(-d), consummation(-ption), was determined, (full, utter) end, riddance.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6437G}/[H6437]', 'inflected', 'heb', 'פָּנָה', '["pânâh"]', '["and/ I turned","and/ I will turn","and/ he turned","and/ he will make clear","and/ it turned","and/ it will turn","and/ people will make clear","and/ she turned","and/ they turned","and/ they turned away","and/ we turned","and/ you will turn"]', '["v"]', 'to turn; by implication, to face, i.e. appear, look, etc. appear, at (even-) tide, behold, cast out, come on, × corner, dawning, empty, go away, lie, look, mark, pass away, prepare, regard, (have) respect (to), (re-) turn (aside, away, back, face, self), × right (early).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5750}/H9043/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["still [was]/ he","still/ he","still/ it"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5066G}/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["and/ he approached","and/ he drew near","and/ he will approach","and/ he will come near","and/ he will draw near","and/ she approached","and/ she will draw near","and/ they approached","and/ they drew near","and/ they will draw near"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5595}/[H5595]', 'lemma', 'heb', 'סָפָה', '["çâphâh"]', '["I will be swept away","I will catch up","[is what] is swept away","being swept away","it has dwindled away","to add","to sweep away","will you sweep [it] away","will you sweep away","you should be swept away"]', '["v"]', 'properly, to scrape (literally, to shave; but usually figuratively) together (i.e. to accumulate or increase) or away (i.e. to scatter, remove, or ruin; intransitively, to perish) add, augment, consume, destroy, heap, join, perish, put.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/[H6004]', 'lemma', 'heb', 'עִם', '["ʻim"]', '["[is] beside","[is] near","[is] with","[was] near","[was] with","[were] near","[were] with","[will be] with","beside","near","with"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7563}/[H7561]', 'lemma', 'heb', 'רָשָׁע', '["râshâʻ"]', '["<of> a wicked [person]","O wicked [person]","[are] wicked [people]","[is the] wicked","[is] a wicked [person]","[is] guilty","[the] wicked","[the] wicked [people]","[the] wicked [people] of","[the] wicked [person]","[will be the] wicked","[will be] wicked","a guilty [person]","a wicked [person]","guilty","wicked","wicked [one]","wicked [people]","wicked [person]"]', '["a"]', 'morally wrong; concretely, an (actively) bad person condemned, guilty, ungodly, wicked (man), that did wrong.', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3426>', 'opaque', 'heb', 'יֵשׁ', '["yêsh"]', '["[is] there","[is] there?","[that] there","substance","there","there is"]', '["prt"]', 'there is or are (or any other form of the verb to be, as may suit the connection) (there) are, (he, it, shall, there, there may, there shall, there should) be, thou do, had, hast, (which) hath, (I, shalt, that) have, (he, it, there) is, substance, it (there) was, (there) were, ye will, thou wilt, wouldest.', 'perhaps from an unused root meaning to stand out, or exist; entity; used adverbially or as a copula for the substantive verb (1961);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375H}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["I bore","I have borne","I have taken","I lifted [it] up","I will bear","I will carry off","O bearers of","[the] bearer of","[the] bearers of","[those who] carry","[was] bearing","[were] carrying","[who] bore","[who] carried","[who] carry","[who] were carrying","[will be] carrying","bear","bearers of","bearing","carry","carrying","certainly <to carry>","he bore","he carries","he had supported","he had taken away","he takes away","he will bear","he will carry","he will carry [them]","he will lift up","he will raise up","it carried","it has borne [fruit]","it took up","it will carry away","lift up","people will raise","someone will carry off","they are carried","they carried","they carry","they lift","they will be carried","they will bear","they will carry","they will carry off","to bear","to bear [them]","to bear up","to carry","will I bear","will you forgive?","you carried","you carry","you have borne","you may bear","you will be carried","you will bear","you will bear [it]","you will carry [it]"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4725}/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["<to> the/ place","of the/ place","to the/ place"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6662}/[H6663]', 'inflected', 'heb', 'צַדִּיק', '["tsaddîyq"]', '["<the>/ righteous [people]","[is] the/ righteous [one]","the/ righteous","the/ righteous [one]","the/ righteous [people]","the/ righteous [person]"]', '["a"]', 'just just, lawful, righteous (man).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2486}/[H2490]', 'lemma', 'heb', 'חָלִילָה', '["châlîylâh"]', '["far be it"]', '["inj"]', 'literal for a profaned thing; used (interj.) far be it! be far, (× God) forbid.', 'or חָלִלָה; a directive from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6213A}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["from/ acting","from/ doing"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1697O}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["according to the/ manner","according to the/ things","according to the/ word","according to the/ words","like the/ thing"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4191}/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["<to>/ die","by/ killing","by/ putting to death","for/ [the] dead","of/ killing","to <the>/ [those who] bring death","to/ [the] dead","to/ a dead [person]","to/ die","to/ kill","to/ put to [them] death","to/ put to death"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6662}/[H6663]', 'inflected', 'heb', 'צַדִּיק', '["tsaddîyq"]', '["as the/ righteous [person]"]', '["a"]', 'just just, lawful, righteous (man).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7563}/[H7561]', 'inflected', 'heb', 'רָשָׁע', '["râshâʻ"]', '["as the/ wicked [person]","like/ a wicked [person]"]', '["a"]', 'morally wrong; concretely, an (actively) bad person condemned, guilty, ungodly, wicked (man), that did wrong.', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H8199}/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["¿/ [the] judge of","¿/ will you judge"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941H}/[H8199]', 'lemma', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["<of> justice","[are] justice","[is] justice","[the] cause of","[the] claim of","[the] justice of","[the] ordinance of","[the] right of","[was] [the] appearance of","[was] justice","a case","judgment","judgment of","judgments of","justice","justice of"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5668}/H9038/[H5674]', 'inflected', 'heb', 'עָבוּר', '["ʻâbûwr"]', '["because/ of/ them","for/ sake of/ them"]', '["prep"]', 'properly, crossed, i.e. (abstractly) transit; used only adverbially, on account of, in order that because of, for (...''s sake), (intent) that, to.', 'or עָבֻר; passive participle of 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6030B}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ I answered","and/ he answered","and/ he had answered","and/ it answered","and/ it will testify","and/ she answered","and/ she will answer","and/ they answered","and/ they will answer","and/ you answered","and/ you will answer"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2974}/[H2973]', 'lemma', 'heb', 'יָאַל', '["yâʼal"]', '["I have undertaken","be willing","he undertook","he was determined","we had been willing","you have determined"]', '["v"]', 'properly, to yield, especially assent; hence (pos.) to undertake as an act of volition assay, begin, be content, please, take upon, × willingly, would.', 'a primitive root (probably rather the same as 2973 through the idea of mental weakness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0665>', 'inflected', 'heb', 'ואפר', '["va./''E.fer"]', '["and/ ash[es]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2637}/H9013/[H2637]', 'inflected', 'heb', 'חָסֵר', '["châçêr"]', '["they will lack/ !"]', '["v"]', 'to lack; by implication, to fail, want, lessen be abated, bereave, decrease, (cause to) fail, (have) lack, make lower, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7843}/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["¿/ about to destroy","¿/ will you destroy"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2568}/[H2568]', 'inflected', 'heb', 'חָמֵשׁ', '["châmêsh"]', '["[is] on/ [the] fif-","by/ five","for/ fif-","for/ five","on/ [day] fif-","on/ [day] five","on/ [the] fif-","on/ fif-"]', '["n"]', 'five fif(-teen), fifth, five (× apiece).', 'masculine חֲמִשָּׁה; a primitive numeral;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4672}/H9013/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["they will be found/ !","you will find/ !"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0705}/[H702]', 'inflected', 'heb', 'אַרְבָּעִים', '["ʼarbâʻîym"]', '["<the>/ forty","the/ forty"]', '["n"]', 'forty forty.', 'multiple of 702;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0136}/[H113]', 'inflected', 'heb', 'אֲדֹנָי', '["ʼĂdônây"]', '["[belong] to/ [the] Lord","[belongs] to/ [the] Lord","for/ [the] Lord","of/ [the] Lord","to/ [the] Lord"]', '["n-m"]', 'the Lord (used as a proper name of God only) (my) Lord.', 'an emphatic form of 113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1696G}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ I will speak","and/ [one who] speaks","and/ [the] speaking of","and/ let her speak","and/ let me speak","and/ speak","and/ speaking","and/ they may speak","and/ they speak","and/ to speak","and/ you spoke","so/ I may speak","so/ let me speak","so/ you may declare?","so/ you may speak"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6242}/[H6235]', 'lemma', 'heb', 'עֶשְׂרִים', '["ʻesrîym"]', '["[is] twenty","[was] twenty","[were] twenty","[will be] twenty","twenty","twenty [measures]"]', '["n"]', 'twenty; also (ordinal) twentieth (six-) score, twenty(-ieth).', 'from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6242}/[H6235]', 'inflected', 'heb', 'עֶשְׂרִים', '["ʻesrîym"]', '["the/ twenty","the/ twenty [cubits]"]', '["n"]', 'twenty; also (ordinal) twentieth (six-) score, twenty(-ieth).', 'from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6235}/[H6237]', 'inflected', 'heb', 'עֶשֶׂר', '["ʻeser"]', '["the/ ten"]', '["n"]', 'ten (as an accumulation to the extent of the digits) ten, (fif-, seven-) teen.', 'masculine of term עֲשָׂרָה; from 6237;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615G}/[H3615]', 'lemma', 'heb', 'כָּלָה', '["kâlâh"]', '["I had finished","complete","finished","have you completed","he finished","he had finished","he has finished","it had finished","it has come to an end","it is exhausted","it was complete","it will cease","they are finished","they come to an end","they complete","they had finished","they have completed","they have finished","they will be finished","they will bring to an end","was complete","we come to an end","we finish","you will finish"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4725}/H9023/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["to/ own place/ his","to/ own place/ its","to/ place/ his","to/ place/ its"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4397H>', 'inflected', 'heb', 'המלאכים', '["ha./mal.''Akh","ha./mal.''a.Khim","ha./mal.''oKh"]', '["the/ angel","the/ angels"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6153}/[H6150]', 'inflected', 'heb', 'עֶרֶב', '["ʻereb"]', '["in the/ evening","in/ [the] evening of"]', '["n-m"]', 'dusk day, even(-ing, tide), night.', 'from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8179G}/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["[is] at the/ gate","[was] at the/ gate","[was] at/ [the] gate of","[were] at/ [the] gate of","[will be] at the/ gate","[will be] at/ [the] gate of","at the/ gate","at the/ gates","at/ [the] gate of","at/ [the] gates of","by/ [the] gate of","in the/ gate","in the/ gates","in/ [the] gate of","in/ [the] gates of","in/ a gate"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639I}/[H599]', 'lemma', 'heb', 'אַף', '["ʼaph"]', '["double","face","faces"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5493I}/[H5493]', 'lemma', 'heb', 'סוּר', '["çûwr"]', '["I have turned aside","I turn aside","I will turn aside","[are those who] turn aside of","does it turn aside","he had turned aside","he has caused to deviate","he has turned aside","he left undone","he turned aside","he turns aside","he will turn aside","it turns aside","it will turn aside","remove","they have turned aside","they turn aside","they turned aside","to turn aside","turn aside","we will turn aside","will he turn aside","you had turned aside","you have turned aside","you must turn aside","you turn aside","you will remove","you will turn aside"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/[H1129]', 'lemma', 'heb', 'בַּיִת', '["bayith"]', '["<of> a house","<the> house of","[are] [the] house of","[is the] house of","[is] [the] house of","[the] house","[the] house of","[the] household of","[the] houses of","[was] [the] house of","[was] a house","a home","a house","a house of","house","house of","houses","houses of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3885A}/[H3885]', 'inflected', 'heb', 'לוּן', '["lûwn"]', '["and/ it may pass [the] night","and/ spend [the] night","and/ stay [the] night","so/ we may spend [the] night"]', '["v"]', 'to stop (usually over night); by implication, to stay permanently; hence (in a bad sense) to be obstinate (especially in words, to complain) abide (all night), continue, dwell, endure, grudge, be left, lie all night, (cause to) lodge (all night, in, -ing, this night), (make to) murmur, remain, tarry (all night, that night).', 'or לִין; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7925}/[H7926]', 'inflected', 'heb', 'שָׁכַם', '["shâkam"]', '["and/ he rose early","and/ they rose early","and/ you will rise early"]', '["v"]', 'literally, to load up (on the back of man or beast), i.e. to start early in the morning (arise, be up, get (oneself) up, rise up) early (betimes), morning.', 'a primitive root; properly, to incline (the shoulder to a burden); but used only as denominative from 7926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1870L}/H9026/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["for/ journey/ your","to/ way/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7339}/[H7337]', 'inflected', 'heb', 'רְחֹב', '["rᵉchôb"]', '["in the/ open place","in the/ open places","in the/ open square","in the/ public square","in/ [the] open place of","in/ [the] open places of","in/ [the] open square of"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3885A}/[H3885]', 'lemma', 'heb', 'לוּן', '["lûwn"]', '["I want to lodge","I will lodge","[was] staying [the] night","he passed [the] night","he remains","he will lodge","he will pass [the] night","it lodged","it lodges","it passes [the] night","it will remain","it will remain overnight","let them spend [the] night","let us pass [the] night","lodge","may it dwell","passing [the] night","someone will pass [the] night","spend [the] night","stay","they spend [the] night","they spent [the] night","they will spend [the] night","we will stay [the] night","will it pass [the] night","will it remain","you pass [the] night","you spend [the] night","you will lodge","you will stay"]', '["v"]', 'to stop (usually over night); by implication, to stay permanently; hence (in a bad sense) to be obstinate (especially in words, to complain) abide (all night), continue, dwell, endure, grudge, be left, lie all night, (cause to) lodge (all night, in, -ing, this night), (make to) murmur, remain, tarry (all night, that night).', 'or לִין; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6484}/[H6484]', 'inflected', 'heb', 'פָּצַר', '["pâtsar"]', '["and/ he urged","and/ they urged"]', '["v"]', 'to peck at, i.e. (figuratively) stun or dull press, urge, stubbornness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9038}', 'inflected', 'arc', 'בהמה', '["Ba/m","Va/m","ba./He.mah","ba./Hem","ba/m","be./Hon","be./hOn","va./He.mah","va./Hem","va/m","ve./hOn"]', '["<in> <the>/ them","<in>/ them","[are] on <the>/ them","[is] among/ them","[is] in <the>/ them","[is] in/ them","[is] on/ them","[there was] in <the>/ them","[was] in <the>/ them","[was] in/ them","[will be] among <the>/ them","against <the>/ them","against/ them","among <the>/ them","among/ them","at/ them","by <the>/ them","by/ them","for/ them","in <the>/ them","in/ them","on <the>/ them","on/ them","over <the>/ them","over/ them","to/ them","with <the>/ them","with/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5493I}/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["and/ he turned aside","and/ they put aside","and/ they turned aside","and/ you will turn aside"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["home/ its","house/ his","house/ its","household/ his","houses/ its","own house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4960}/[H8354]', 'lemma', 'heb', 'מִשְׁתֶּה', '["mishteh"]', '["[the] feast of","a feast","a feast of","feast"]', '["n-m"]', 'drink, by implication, drinking (the act); also (by implication) a banquet or (generally) feast banquet, drank, drink, feast((-ed), -ing).', 'from 8354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4682}/[H4711]', 'inflected', 'heb', 'מַצָּה', '["matstsâh"]', '["and/ unleavened bread<s>"]', '["n-f"]', 'properly, sweetness; concretely, sweet (i.e. not soured or bittered with yeast); specifically, an unfermented cake or loaf, or (elliptically) the festival of Passover (because no leaven was then used) unleaved (bread, cake), without leaven.', 'from 4711 in the sense of greedily devouring for sweetness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0644}/[H644]', 'lemma', 'heb', 'אָפָה', '["ʼâphâh"]', '["I baked","a baker","bake","he baked","it will be baked","they will bake","they will be baked","you will bake"]', '["v"]', 'to cook, especially to bake bake(-r, (-meats)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7901G}/[H7901]', 'lemma', 'heb', 'שָׁכַב', '["shâkab"]', '["I lay down","I lie with","I will lie down","[are] about to lie down","[are] lying","[they] lie down","[was] lying","[was] lying down","[were] lying","[will be] lying","he lay","he lay down","he lies down","he made lie down","he will lie down","it lay down","it lies","it will lie down","laid","let us lie down","lie","lie down","she lay","she made lie","she will lie","she will lie down","they have lain down","they lay down","they will lie","they will lie down","will he make to lie down","will you lie down","you lay down","you will lie","you will lie down"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5437H}/[H5437]', 'lemma', 'heb', 'סָבַב', '["çâbab"]', '["[they were] surrounding","[was] surrounding","circling around","go around","going round","he had caused to go round","he removed","it went round","she will surround","surrounded","they surround","they surrounded","they went round","you will go round"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1004B}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["<of> the/ house","the/ house","the/ houses"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5288}/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["from/ a youth","from/ young man","one of/ [the] young men of"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7121I}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ I called out","and/ I proclaimed","and/ I will proclaim","and/ he called","and/ he called out","and/ he proclaimed","and/ people will call","and/ people will call out","and/ she called out","and/ they called","and/ they called out","and/ they proclaim","and/ they proclaimed","and/ they proclaimed [it]","and/ they will proclaim","and/ you will proclaim"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318H}/H9038/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["I had brought out/ them","[is] bringing out/ them","bring/ them","he brought out/ them","he led out/ them","he will lead out/ them","they took out/ them"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/H9035/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["against/ us","to/ ourselves","to/ us"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3045}/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["<and>/ [were] leading","and/ O [those who] know","and/ [is] known","and/ [one who] knows","and/ [the] [one who] knows","and/ [those who] know","and/ a [man] acquainted of","and/ he knows","and/ he will make known","and/ know","and/ knowing","and/ known","and/ let him acknowledge","and/ let us know","and/ observe","and/ they may know","and/ to know","so/ he may know","so/ let me consider","so/ let me know","so/ let us know","so/ let us make known to","so/ they may know","so/ we may know","so/ you may know","so/ you may observe"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/H9038/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["<to>/ them","[which] to/ them","against/ them","to/ them","to/ themselves"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6607}/H9011/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["the/ entrance/ towards"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1817C}/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["and/ the/ door"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5462}/[H5462]', 'lemma', 'heb', 'סָגַר', '["çâgar"]', '["<of> [which] he has shut up","[was] shut","[was] shutting","[will be one who] shuts","gold plate","he closed","he closed up","he delivered up","he had closed","he has delivered up","he has shut himself up","he shuts","it has been shut up","it has shut","it shut","it will be shut","people closed","pure gold","she will be shut up","shut","shut up","shut yourself up","they closed","they have been shut up","they have closed up","they shut","they will be shut","they will deliver up","you deliver up","you will deliver up"]', '["v"]', 'to shut up; figuratively, to surrender close up, deliver (up), give over (up), inclose, × pure, repair, shut (in, self, out, up, up together), stop, × straitly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7489A}/[H7489]', 'lemma', 'heb', 'רָעַע', '["râʻaʻ"]', '["<of> to do evil","I have done evil","I have done harm to","I will do harm","O evil-doers","[is] displeasing","[it is] displeasing","[it was] displeasing","[who] do evil","an evil-doer","did you do harm","evil-doers","have you done harm","he has done evil","he has done harm","he has done harm to","he is harmed","he will be bad","he will be harmed","he will do harm","is displeasing","it be displeasing","it will be bad","it will be evil","it will sadden","she is bad","still <do evil>","they did evil","they do harm","they have done evil","they have made evil","they will do harm","to do evil","we will do harm","will they be sad","you did harm to","you do evil","you do harm","you have done evil","you will do evil"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0853}/H9039/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["<obj.>/ them"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/H9036/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["<to>/ you","[am] against/ you","[am] with/ you","[be] to/ you","[is] to/ you","to/ you"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6213A}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["<and>/ let them observe","and/ I may act","and/ [are] doing","and/ [he is] doing","and/ [one who] does","and/ [who] does","and/ act","and/ certainly <to perform>","and/ do","and/ doers of","and/ doing","and/ has he accomplished [it]?","and/ he will do","and/ it may be done","and/ make","and/ observed","and/ offer","and/ work","so/ I may do","so/ I may do [it]","so/ it may be done","so/ may he do","so/ they may work"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9039}', 'inflected', 'heb', 'להנה', '["la./He.nah","la./Hen"]', '["<to> <the>/ them","<to>/ them","[belonged] to/ them","[belongs] to/ them","for/ them","to <the>/ them","to/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2896A}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["according to the/ good","as the/ good [person]"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869I}/H9026/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0582}/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["<into>/ husbands","<into>/ men","[belong] to/ humankind","for/ [the] men","for/ men","to the/ men","to/ [the] men of","to/ [the] people of","to/ a person","to/ husbands","to/ men"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0411}/[H411]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["<the>/ these"]', '["d"]', 'these or those these, those. Compare 428.', 'a demonstrative particle (but only in a plural sense)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6738}/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["[is] <in>/ a shade","in the/ shade","in/ [the] shade of","in/ [the] shadow of"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6982}/H9020/[H6979]', 'inflected', 'heb', 'קוֹרָה', '["qôwrâh"]', '["roof/ my"]', '["n-f"]', 'a rafter (forming trenches as it were); by implication, a roof beam, roof.', 'or קֹרָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5066G}/[H5066]', 'lemma', 'heb', 'נָגַשׁ', '["nâgash"]', '["approach","did you draw near","draw near","he approached","he drew near","he will draw near","it has drawn near","it will bring near","it will draw near","let him draw near","let them approach","they draw near","they drew near","they will draw near","you draw near"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1973}/[H1973]', 'lemma', 'heb', 'הָלְאָה', '["hâlᵉʼâh"]', '["beyond"]', '["adv"]', 'to the distance, i.e. far away; also (of time) thus far back, beyond, (hence,-) forward, hitherto, thence, forth, yonder.', 'from the primitive form of the article (hal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8199}/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["and/ I judge","and/ I will enter into judgment","and/ I will judge","and/ he has judged","and/ he judged","and/ he will judge","and/ they judged","and/ they will judge","and/ you will judge"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6258}/[H6256]', 'lemma', 'heb', 'עַתָּה', '["ʻattâh"]', '["now"]', '["adv"]', 'at this time, whether adverb, conjunction or expletive henceforth, now, straightway, this time, whereas.', 'from 6256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0376G>', 'inflected', 'heb', 'באיש', '["ba./''Ish","be./''Ish","be./''ish","va./''Ish","ve./''Ish"]', '["<in> the/ man","<in>/ a person","among/ [the] man of","for the/ man","in/ a person","of/ a person of","on the/ man","on the/ person","on/ a man"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3876}/[H3875]', 'inflected', 'heb', 'לוֹט', '["Lôwṭ"]', '["<in>/ Lot"]', '["n-pr-m"]', 'Lot, Abraham''s nephew Lot.', 'the same as 3875;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7665}/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["<to>/ [people] broken of","<to>/ [the people] broken of","to/ [people] broken of","to/ be broken","to/ break","to/ break down"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1817C}/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["the/ door","the/ doors"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ their","hands/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1004B}/H9011/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["the/ house/ towards"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5575>', 'inflected', 'heb', 'בסנורים', '["ba./san.ve.Rim"]', '["with <the>/ sudden blindness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6996B}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["from/ [the] small","from/ small"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3811}/[H3811]', 'inflected', 'heb', 'לָאָה', '["lâʼâh"]', '["and/ I will be weary","and/ they became weary","and/ they will be weary","and/ you have become impatient"]', '["v"]', 'to tire; (figuratively) to be (or make) disgusted faint, grieve, lothe, (be, make) weary (selves).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4672}/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["[is] to/ find","to/ [those who] find","to/ find","to/ find [it]","to/ find out"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6607}/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["the/ doorway","the/ entrance","the/ openings"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6311}/[H1931]', 'lemma', 'heb', 'פֹּה', '["pôh"]', '["[is] here","here"]', '["adv"]', 'this place (French ici), i.e. here or hence here, hither, the one (other, this, that) side.', 'or פֹּא; (Job 38:11), or פּוֹ; probably from a primitive inseparable particle ''p'' (of demonstrative force) and 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2860}/[H2859]', 'lemma', 'heb', 'חָתָן', '["châthân"]', '["[are] a bridegroom of","[the] son-in-law of","[was] [the] son-in-law of","[was] a son-in-law","a bridegroom","a bridegroom of","a son-in-law"]', '["n-m"]', 'a relative by marriage (especially through the bride); figuratively, a circumcised child (as a species of religious espousal) bridegroom, husband, son in law.', 'from 2859;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1323G}/H9021/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ daughter/ your","and/ daughters/ your"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1431}/[H1434]', 'lemma', 'heb', 'גָּדַל', '["gâdal"]', '["I have brought up","I have made great","I made great","I will be great","I will make great","[he is] making great","[who] were bringing up","[whom] she has brought up","did he bring up","does it magnify itself","full grown","he became great","he did great things","he had grown up","he has done great things","he has made great","he is great","he made great","he magnified himself","he will be great","he will become great","he will grow up","he will magnify himself","he will make great","he will make grow","it has magnified itself","it is great","it magnified itself","it makes [it] grow","it was great","it will be great","magnify","may he be great","may it be great","they are great","they had grown up","they have become great","they magnified themselves","they will bring up","they will grow up","you are great","you have made great","you make big","you will magnify","you will magnify yourselves"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6818}/H9028/[H6817]', 'inflected', 'heb', 'צַעֲקָה', '["tsaʻăqâh"]', '["cry of distress/ their","outcry/ their"]', '["n-f"]', 'a shriek cry(-ing).', 'from 6817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971G}/H9035/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ he has sent/ us"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7843}/H9034/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["[is] to/ destroy/ it","to/ destroy/ it"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2860}/H9023/[H2859]', 'inflected', 'heb', 'חָתָן', '["châthân"]', '["son-in-law/ his","sons-in-law/ his"]', '["n-m"]', 'a relative by marriage (especially through the bride); figuratively, a circumcised child (as a species of religious espousal) bridegroom, husband, son in law.', 'from 2859;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947I}/[H3947]', 'lemma', 'heb', 'לָקַח', '["lâqach"]', '["I took","[is] taking","[who were] about to take","get","he had taken","he has taken","he took","he will take","take","they will take","we will take","you must take","you will take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1323G}/H9023/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["<of> daughters/ his","daughter/ his","daughters/ his"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6711}/[H6711]', 'inflected', 'heb', 'צָחַק', '["tsâchaq"]', '["like/ [one who] jests"]', '["v"]', 'to laugh outright (in merriment or scorn); by implication, to sport laugh, mock, play, make sport.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869I}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ [the] eyes of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3644G}/[H3651]', 'inflected', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["and/ like","and/ when"]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7837}/[H7836]', 'inflected', 'heb', 'שַׁחַר', '["shachar"]', '["the/ dawn"]', '["n-m"]', 'dawn (literal, figurative or adverbial) day(-spring), early, light, morning, whence riseth.', 'from 7836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927L}/[H5927]', 'lemma', 'heb', 'עָלָה', '["ʻâlâh"]', '["came up","it came up","it has come up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0213}/[H213]', 'inflected', 'heb', 'אוּץ', '["ʼûwts"]', '["and/ they urged"]', '["v"]', 'to press; (by implication) to be close, hurry, withdraw (make) haste(-n, -y), labor, be narrow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1323G}/H9021/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["daughter/ your","daughters/ your"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4672}/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["<the>/ [one who] is found","<the>/ [one who] was found","that/ [which] may be found","the/ [ones who] found","the/ [things that] had found","those/ [who] were found","which/ had been found","which/ is found","which/ was found","which/ were found","who/ are found","who/ were found"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771I}/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["in/ [the] punishment of"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4102}/[H4100]', 'inflected', 'heb', 'מָהַהּ', '["mâhahh"]', '["and/ delay","and/ he delayed"]', '["v"]', 'properly, to question or hesitate, i.e. (by implication) to be reluctant delay, linger, stay selves, tarry.', 'apparently a denominative from 4100;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2388H}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ I took hold","and/ he took hold","and/ he took hold of","and/ he will take hold","and/ it was firm","and/ she takes hold","and/ she took hold","and/ she will take hold","and/ they took hold","and/ they will take hold","and/ they will take hold of"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027G}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["<in>/ hands/ his","[are] in/ hand/ his","[is] in/ hand/ his","[was] in/ hand/ his","[were] in/ hand/ his","[who are] in/ hand/ his","[will be] in/ hand/ his","by/ hand/ his","in/ hand/ his","on/ hand/ his","with/ hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3027G}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ [was] in/ [the] hand of","and/ in/ [the] hand of","and/ on/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2551}/[H2550]', 'inflected', 'heb', 'חֶמְלָה', '["chemlâh"]', '["in/ [the] mercy of"]', '["n-f"]', 'commiseration merciful, pity.', 'from 2550;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318H}/H9033/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ they brought out/ him","and/ they brought out/ it","and/ they took out/ him","and/ you brought out/ him"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2351>', 'inflected', 'heb', 'מחוץ', '["mi./Chutz"]', '["[was] from/ [the] outside","[were] from/ [the] outside","[will be] from/ [the] outside","from/ [the] outside","from/ [the] street","from/ [the] street of","from/ outside"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5892B}/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["<to> the/ city","for the/ cities","for the/ city","for/ a city","into/ a city of","of the/ city","of/ [the] city of","to the/ cities","to the/ city","to/ [the] cities of","to/ [the] city"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3318H}/H9048/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ brought out/ they"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4422}/[H4422]', 'lemma', 'heb', 'מָלַט', '["mâlaṭ"]', '["I have escaped","I rescued","I will escape","[are] delivering","[who] he will deliver","certainly <rescue>","escape","he delivered","he delivers","he escape","he escaped","he escapes","he had escaped","he will be delivered","he will deliver","he will escape","he will save","it delivers","it has escaped","it will be delivered","it will escape","it will rescue","let me escape","let me slip away","really <escape>","save","they escape","they escaped","they will escape","to rescue","we have escaped","will it escape","will we escape","you will escape"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315H}/H9021/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["<of> life/ your","life/ your","self/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0408}/[H3808]', 'inflected', 'heb', 'אַל', '["ʼal"]', '["and/ may not","and/ may not [he meet]","and/ may not [it be]","and/ may not [it incline]","and/ may not [you take]"]', '["adv"]', 'not (the qualified negation, used as a deprecative); once (Job 24:25) as a noun, nothing nay, neither, + never, no, nor, not, nothing (worth), rather than.', 'a negative particle (akin to 3808);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2022G}/H9011/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["the/ hill country/ towards","the/ mountain/ towards"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1431}/[H1434]', 'inflected', 'heb', 'גָּדַל', '["gâdal"]', '["and/ I became great","and/ I will show myself great","and/ he became great","and/ he grew up","and/ he has become great","and/ he made great","and/ it became great","and/ it grew up","and/ it has become great","and/ it magnified itself","and/ they grew up","and/ they have magnified themselves","and/ they magnified themselves","and/ you grew up","and/ you have made great","and/ you have magnified yourselves"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2617A}/H9021/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["[are] covenant loyalti<es>/ your","[is] covenant loyalty/ your","covenant loyalti<es>/ your","covenant loyalty/ your","loyalty/ your"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4422}/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["to/ escape"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1692}/H9030/[H1692]', 'inflected', 'heb', 'דָּבַק', '["dâbaq"]', '["it should cling to/ me"]', '["v"]', 'properly, to impinge, i.e. cling or adhere; figuratively, to catch by pursuit abide fast, cleave (fast together), follow close (hard after), be joined (together), keep (fast), overtake, pursue hard, stick, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7451C}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<the>/ calamity","<the>/ evil","<the>/ harm","the/ calamity","the/ distress","the/ evil","the/ harm","the/ trouble","the/ troubles"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7138}/[H7126]', 'lemma', 'heb', 'קָרוֹב', '["qârôwb"]', '["O near [ones]","[are] near","[is] close","[is] near","[one] near","[was] near","[were] near","[were] warriors","near","warriors"]', '["a"]', 'near (in place, kindred or time) allied, approach, at hand, any of kin, kinsfold(-sman), (that is) near (of kin), neighbour, (that is) next, (them that come) nigh (at hand), more ready, short(-ly).', 'or קָרֹב; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5127}/[H5127]', 'inflected', 'heb', 'נוּס', '["nûwç"]', '["to/ flee","to/ hide [it]"]', '["v"]', 'to flit, i.e. vanish away (subside, escape; causatively, chase, impel, deliver) × abate, away, be displayed, (make to) flee (away, -ing), put to flight, × hide, lift up a standard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4705}/[H6819]', 'lemma', 'heb', 'מִצְעָר', '["mitsʻâr"]', '["[is] a small place","a small place","a small thing"]', '["n-m"]', 'petty (in size or number); adverbially, a short (time) little one (while), small.', 'from 6819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2421}/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["and/ I may restore to life","and/ [is] restoring to life","and/ live","and/ may he live","and/ may it live","and/ we may live","and/ we will let live","so/ I may live","so/ he may live","so/ it may live","so/ may it live","so/ they may live","so/ we may live","so/ we may preserve alive"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375Q}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["I lift up","I will lift up","[am] lifting up","bearing","he lifted","he lifted up","he lifts up","he will lift up","it will lift up","lift up","may he lift up","she bore","they have lifted","they lifted up","to lift up","will I lift up","will you lift up","you will lift up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440N}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1697I}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<to> the/ matter","to the/ matter","to the/ thing"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2015}/H9040/[H2015]', 'inflected', 'heb', 'הָפַךְ', '["hâphak"]', '["to overthrow/ I"]', '["v"]', 'to turn about or over; by implication, to change, overturn, return, pervert × become, change, come, be converted, give, make (a bed), overthrow (-turn), perverse, retire, tumble, turn (again, aside, back, to the contrary, every way).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9041/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["[are] coming/ you","[are] coming?/ you","coming in/ you","coming/ you","going/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318K}/[H3318]', 'lemma', 'heb', 'יָצָא', '["yâtsâʼ"]', '["it came out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6820}/H9011/[H6819]', 'inflected', 'heb', 'צֹעַר', '["Tsôʻar"]', '["Zoar/ towards"]', '["n-pr-loc"]', 'Tsoar, a place East of the Jordan Zoar.', 'from 6819; little;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1614}/[H1613]', 'lemma', 'heb', 'גׇּפְרִית', '["gophrîyth"]', '["[is] sulfur","sulfur"]', '["n-f"]', 'properly, cypress-resin; by analogy, sulphur (as equally inflammable) brimstone.', 'probably feminine of 1613;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0784}/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["and/ [the] fire of","and/ fire"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2015}/[H2015]', 'inflected', 'heb', 'הָפַךְ', '["hâphak"]', '["and/ I will overthrow","and/ I will turn","and/ have they been changed?","and/ he changed","and/ he changed himself","and/ he overthrew","and/ he overthrows [them]","and/ he turned","and/ he turned around","and/ it was changed","and/ it will be turned","and/ she turned","and/ they turned round","and/ they were changed","and/ they will be changed","and/ you change","and/ you will be changed"]', '["v"]', 'to turn about or over; by implication, to change, overturn, return, pervert × become, change, come, be converted, give, make (a bed), overthrow (-turn), perverse, retire, tumble, turn (again, aside, back, to the contrary, every way).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6780}/[H6779]', 'inflected', 'heb', 'צֶמַח', '["tsemach"]', '["and/ [the] growth of"]', '["n-m"]', 'a sprout (usually concrete), literal or figurative branch, bud, that which (where) grew (upon), spring(-ing).', 'from 6779;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5027}/[H5027]', 'inflected', 'heb', 'נָבַט', '["nâbaṭ"]', '["and/ he looked","and/ it has looked","and/ she looked","and/ someone will look","and/ they looked","and/ they will look","and/ you looked","and/ you will look at"]', '["v"]', 'to scan, i.e. look intently at; by implication, to regard with pleasure, favor or care (cause to) behold, consider, look (down), regard, have respect, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0310A}/H9033/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["<from>/ behind/ it","from/ after/ him","from/ behind/ him"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5333}/[H5324]', 'lemma', 'heb', 'נְצִיב', '["nᵉtsîyb"]', '["[the] garrison of","[the] garrisons of","a pillar of","garrisons"]', '["n-m"]', 'something stationary, i.e. a prefect, a military post, a statue garrison, officer, pillar.', 'or נְצִב; from 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4417M}/[H4414]', 'lemma', 'heb', 'מֶלַח', '["melach"]', '["[the] salt of","salt","salt of"]', '["n-m"]', 'properly, powder, i.e. (specifically) salt (as easily pulverized and dissolved) salt(-pit).', 'from 4414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1242}/[H1239]', 'inflected', 'heb', 'בֹּקֶר', '["bôqer"]', '["in the/ morning"]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7008}/[H6999]', 'lemma', 'heb', 'קִיטוֹר', '["qîyṭôwr"]', '["[the] smoke of"]', '["n-m"]', 'a fume, i.e. cloud smoke, vapour.', 'or קִיטֹר; from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7008}/[H6999]', 'inflected', 'heb', 'קִיטוֹר', '["qîyṭôwr"]', '["like/ [the] smoke of"]', '["n-m"]', 'a fume, i.e. cloud smoke, vapour.', 'or קִיטֹר; from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3536}/[H3533]', 'inflected', 'heb', 'כִּבְשָׁן', '["kibshân"]', '["<the>/ furnace","the/ furnace"]', '["n-m"]', 'a smelting furnace (as reducing metals) furnace.', 'from 3533;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7843}/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["when/ destroyed"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H8432>', 'inflected', 'heb', 'מתוך', '["mi./Tokh","mi./toKh","mi./tokh"]', '["from/ [the] middle of","from/ [the] midst of","from/ among"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2018}/[H2016]', 'inflected', 'heb', 'הֲפֵכָה', '["hăphêkâh"]', '["the/ overthrow"]', '["n-f"]', 'destruction overthrow.', 'feminine of 2016;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2015}/[H2015]', 'inflected', 'heb', 'הָפַךְ', '["hâphak"]', '["when/ overthrew"]', '["v"]', 'to turn about or over; by implication, to change, overturn, return, pervert × become, change, come, be converted, give, make (a bed), overthrow (-turn), perverse, retire, tumble, turn (again, aside, back, to the contrary, every way).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9039}', 'inflected', 'heb', 'בהנה', '["ba./He.nah","ba./Hen","va./He.nah","va./Hen"]', '["[is] in <the>/ them","by/ them","for/ them","in <the>/ them","in/ them","on <the>/ them","with <the>/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6820}/[H6819]', 'inflected', 'heb', 'צֹעַר', '["Tsôʻar"]', '["from/ Zoar"]', '["n-pr-loc"]', 'Tsoar, a place East of the Jordan Zoar.', 'from 6819; little;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2022G}/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["<in> the/ mountain","<in> the/ mountains","[are] in the/ mountains","[are] on/ [the] mountain of","[is] on the/ mountains","among the/ mountains","at the/ mountain","at/ [the] mountain of","in the/ hill country","in the/ mountains","in/ [the] hill country of","in/ [the] mountain of","in/ [the] mountains of","on the/ mountain","on/ [the] hill of","on/ [the] hills of","on/ [the] mountain of","on/ [the] mountains of","over/ [the] mountain of"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8147}/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["and/ [the] two","and/ two","and/ two [people]","and/ two [plus]","and/ two [times]","and/ two [wings]","and/ two [years]","and/ two of"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6820}/[H6819]', 'inflected', 'heb', 'צֹעַר', '["Tsôʻar"]', '["in/ Zoar"]', '["n-pr-loc"]', 'Tsoar, a place East of the Jordan Zoar.', 'from 6819; little;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4631}/[H5783]', 'inflected', 'heb', 'מְעָרָה', '["mᵉʻârâh"]', '["in <the>/ caves","in the/ cave","in/ [the] cave of","in/ caves of"]', '["n-f"]', 'a cavern (as dark) cave, den, hole.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1067}/[H1069]', 'inflected', 'heb', 'בְּכִירָה', '["bᵉkîyrâh"]', '["the/ firstborn"]', '["n-f"]', 'the eldest daughter firstborn.', 'feminine from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6810}/[H6819]', 'inflected', 'heb', 'צָעִיר', '["tsâʻîyr"]', '["[am] the/ insignificant","[was] the/ young","the/ insignificant","the/ young","the/ young [one]"]', '["a"]', 'little; (in number) few; (in age) young, (in value) ignoble least, little (one), small (one), young(-er, -est).', 'or צָעוֹר; from 6819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9025/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["[are] father/ our","ancestor/ our","ancestors/ our","father/ our","fathers/ our"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0376G>', 'inflected', 'heb', 'ואיש', '["Ve./''ish","va./''Ish","ve./''Ish","ve./''ish"]', '["and/ O man of","and/ [is] a man","and/ [the] man of","and/ [the] person of","and/ a man","and/ a man of","and/ a person","and/ a person of","and/ man","and/ man of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9035/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["<on>/ us","[are] on/ us","at/ us","on/ ourselves","on/ us","over/ us","to/ us","toward/ us","towards/ us","with/ us"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1870G}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["according to/ [the] way of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980K}/H9012/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["come/ !","go/ !"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8248H}/[H8248]', 'lemma', 'heb', 'שָׁקָה', '["shâqâh"]', '["[one who] makes drink","he will make drink","let us make drink","people will give to drink","you have given to drink"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3196>', 'opaque', 'heb', 'יַיִן', '["yayin"]', '["[the] wine","[will be] wine","wine","wine of"]', '["n-m"]', 'wine (as fermented); by implication, intoxication banqueting, wine, wine(-bibber).', 'from an unused root meaning to effervesce;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7901I}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ let us lie"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0001G}/H9025/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["from/ father of/ our","from/ father/ our"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8248H}/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["and/ I made drink","and/ he gave [them] to drink","and/ he made drink [it]","and/ he will make drink","and/ she gave a drink to","and/ they made drink","and/ you made drink","and/ you will give drink to","and/ you will give to drink","and/ you will make drink"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9029/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["father/ their"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3915}/[H3883]', 'inflected', 'heb', 'לַיִל', '["layil"]', '["at/ night","in the/ night","in the/ nights","in/ a night","on the/ night"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7901I}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ he lay","and/ he lay with","and/ he will lie","and/ he will lie with","and/ she lay","and/ she lay with"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9024/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["father/ her"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7901I}/H9044/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["when/ lay down/ she"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6965B}/H9044/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ when/ arose/ she"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4283}/[H4279]', 'inflected', 'heb', 'מׇחֳרָת', '["mochŏrâth"]', '["from/ [the] next day","from/ [the] next day of"]', '["n-f"]', 'the morrow or (adverbially) tomorrow morrow, next day.', 'or מׇחֳרָתָם; (1 Samuel 30:17), feminine from the same as 4279;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7901I}/[H7901]', 'lemma', 'heb', 'שָׁכַב', '["shâkab"]', '["<he> lay","I lay with","[one who] lies","certainly <to lie>","have you been lain with","he has lain with","he lay with","he will lie","he will lie with","lie","lying","they had lain with","they will be lain with","you will lie with"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0570}/[H570]', 'lemma', 'heb', 'אֶמֶשׁ', '["ʼemesh"]', '["last night","yesterday","yesterday of"]', '["adv"]', 'yesterday or last night former time, yesterday(-night)', 'time past, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9020/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["O father/ my","[are] father/ my","[is] father/ my","ancestor/ my","ancestors/ my","father/ my","fathers/ my"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8248H}/H9033/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["give to drink/ him","let us make drink/ him"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ <he> coming","and/ I went","and/ I will go","and/ [are] going","and/ [was] coming","and/ come","and/ coming","and/ go","and/ he may come","and/ it may come","and/ it may come?","and/ it will come","and/ they may come","and/ to come","and/ to go","or/ one coming in","so/ I may come","so/ I may go","so/ he may come","so/ he may go","so/ it may come","so/ it may enter","so/ let us go","so/ they may come","so/ they may go","so/ we may go"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0001G}/H9029/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["from/ father/ their"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4124H}/[H1]', 'lemma', 'heb', 'מוֹאָב', '["Môwʼâb"]', '["Moab"]', '["n-pr-m n-pr-loc"]', 'Moab, an incestuous son of Lot; also his territory and descendants Moab.', 'from a prolonged form of the prepositional prefix m- and 1; from (her [the mother''s]) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3117L>', 'inflected', 'heb', 'הימים', '["hai./Yom","hai./yOm","hai./ya.Mim"]', '["the/ day","the/ days","this/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6810}/[H6819]', 'inflected', 'heb', 'צָעִיר', '["tsâʻîyr"]', '["and/ the/ little","and/ the/ young","and/ the/ young [brother]"]', '["a"]', 'little; (in number) few; (in age) young, (in value) ignoble least, little (one), small (one), young(-er, -est).', 'or צָעוֹר; from 6819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1151}/[H1121]', 'lemma', 'heb', 'בֶּן־עַמִּי', '["Ben-ʻAmmîy"]', '["Ammi","Ben-"]', '["n-pr-m"]', 'Ben-Ammi, a son of Lot Ben-ammi.', 'from 1121 and 5971 with pronomial suffix; son of my people;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121G}/[H1129]', 'lemma', 'heb', 'בֵּן', '["bên"]', '["O children","O children of","O descendants of","O people of","O sons of","[are] [the] children of","[are] [the] descendants of","[are] sons of","[is] [the] son of","[is] a son of","[the] children of","[the] descendant of","[the] descendants of","[the] people","[the] people of","[the] son of","[the] sons of","[was] [the] son of","[was] a son of","[were] [the] descendants of","[were] [the] sons of","[were] sons of","a child of","a son","a son of","children","children of","descendants of","son of","sons","sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5983}/[H5971]', 'lemma', 'heb', 'עַמּוֹן', '["ʻAmmôwn"]', '["Ammon"]', '["n-pr-m"]', 'Ammon, a son of Lot; also his posterity and their country Ammon, Ammonites.', 'from 5971; tribal, i.e. inbred;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3117L>\', 'inflected', 'heb', 'היום ס', '["hai./Yom"]', '["this/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5045G>', 'inflected', 'heb', 'הנגב', '["ha./Ne.gev"]', '["the/ Negev","the/ south"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1481A}/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["and/ he sojourned","and/ it will sojourn","and/ she sojourned"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1642}/[H1641]', 'inflected', 'heb', 'גְּרָר', '["Gᵉrâr"]', '["in/ Gerar"]', '["n-pr-loc"]', 'Gerar, a Philistine city Gerar.', 'probably from 1641; a rolling country;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0040G}/[H1]', 'lemma', 'heb', 'אֲבִימֶלֶךְ', '["ʼĂbîymelek"]', '["Abimelech"]', '["n-pr-m"]', 'Abimelek, the name of two Philistine kings and of two Israelites Abimelech.', 'from 1 and 4428; father of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1642}/[H1641]', 'lemma', 'heb', 'גְּרָר', '["Gᵉrâr"]', '["Gerar"]', '["n-pr-loc"]', 'Gerar, a Philistine city Gerar.', 'probably from 1641; a rolling country;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2472}/[H2492]', 'inflected', 'heb', 'חֲלוֹם', '["chălôwm"]', '["by <the>/ a dream","by <the>/ dreams","by/ dreams","in/ [the] dream of","in/ a dream"]', '["n-m"]', 'a dream dream(-er).', 'or (shortened) חֲלֹם; from 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2009}/H9041/[H2005]', 'inflected', 'heb', 'הִנֵּה', '["hinnêh"]', '["here/ you"]', '["dp"]', 'lo! behold, lo, see.', 'prolongation for 2005;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1166I}/[H1167]', 'lemma', 'heb', 'בָּעַל', '["bâʻal"]', '["I am husband","I was a husband","[is] married of","a married [woman]","he marries","it will be married","married of","she will be married"]', '["v"]', 'to be master; hence, to marry have dominion (over), be husband, marry(-ried, × wife).', 'a primitive root; also as denominative from 1167');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0040G}/[H1]', 'inflected', 'heb', 'אֲבִימֶלֶךְ', '["ʼĂbîymelek"]', '["and/ Abimelech"]', '["n-pr-m"]', 'Abimelek, the name of two Philistine kings and of two Israelites Abimelech.', 'from 1 and 4428; father of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1471A}/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["¿/ a nation"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8537}/[H8552]', 'inflected', 'heb', 'תֹּם', '["tôm"]', '["in <the>/ integrity","in/ [the] integrity of","in/ integrity of"]', '["n-m"]', 'completeness; figuratively, prosperity; usually (morally) innocence full, integrity, perfect(-ion), simplicity, upright(-ly, -ness), at a venture. See 8550.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3824}/H9020/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["heart/ my"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5356A}/[H5352]', 'inflected', 'heb', 'נִקָּיוֹן', '["niqqâyôwn"]', '["and/ in/ [the] innocence of"]', '["n-m"]', 'clearness (literally or figuratively) cleanness, innocency.', 'or נִקָּיֹן; from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709G}/H9020/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["hands/ my","palm/ my","palms/ my"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3824}/H9021/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["heart/ your"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2820}/[H2821]', 'inflected', 'heb', 'חָשַׂךְ', '["châsak"]', '["and/ I have restrained"]', '["v"]', 'to restrain or (reflex.) refrain; by implication, to refuse, spare, preserve; to observe assuage, × darken, forbear, hinder, hold back, keep (back), punish, refrain, reserve, spare, withhold.', 'a primitive root; also interchangeable with 2821');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2398}/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["from/ cleansing [it] from sin","from/ sinning"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414K}/H9031/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["I have permitted/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5060}/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["to/ touch","to/ touch [them]"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0376G>', 'inflected', 'heb', 'האיש', '["Ha./''ish","ha./''Ish"]', '["<the>/ man","<the>/ person","[are] the/ man","[is] the/ man","[is] the/ person","the/ man","the/ person"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5030}/[H5012]', 'lemma', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["[am] a prophet","[are] prophets","[is] a prophet","[the] prophets","[the] prophets of","[were] prophets","a prophet","prophet","prophets"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6419}/[H6419]', 'inflected', 'heb', 'פָּלַל', '["pâlal"]', '["and/ [may] someone pray","and/ [those who] pray","and/ [was] praying","and/ he may pray","and/ pray","and/ praying","so/ I may pray","so/ he may pray","so/ they may pray"]', '["v"]', 'to judge (officially or mentally); by extension, to intercede, pray intreat, judge(-ment), (make) pray(-er, -ing), make supplication.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1157}/H9031/[H5704]', 'inflected', 'heb', 'בְּעַד', '["bᵉʻad"]', '["behind/ you","for/ you","for/ yourself"]', '["prep"]', 'in up to or over against; generally at, beside, among, behind, for, etc. about, at by (means of), for, over, through, up (-on), within.', 'from 5704 with prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0369}/H9041/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["not [are]/ you","not/ you"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5650}/H9023/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["[male] slave/ his","own servants/ his","servant/ his","servants/ his","slave/ his"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241I}/H9028/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["in/ ears/ their"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0085>', 'inflected', 'heb', 'לאברהם', '["le./''av.ra.Ham"]', '["<to>/ Abraham","[belonged] to/ Abraham","to/ Abraham"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4100}/[H4100]', 'inflected', 'heb', 'מָה', '["mâh"]', '["and/ how!","and/ what!","and/ what?","and/ whatever","and/ why?"]', '["i"]', 'properly, interrogative what? (including how? why? when?); but also exclamation, what! (including how!), or indefinitely what (including whatever, and even relatively, that which); often used with prefixes in various adverbial or conjunctive senses how (long, oft, (-soever)), (no-) thing, what (end, good, purpose, thing), whereby(-fore, -in, -to, -with), (for) why.', 'or מַה; or מָ; or מַ; also מֶה; a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2398}/[H2398]', 'lemma', 'heb', 'חָטָא', '["châṭâʼ"]', '["I have sinned","I sinned","I will sin","[are] sinning","[is] missing","[is] sinning","[those who] cause to sin","[those who] they have sinned","[which] sins","a sinner","did he sin","have I sinned","he caused to sin","he had sinned","he has caused to sin","he has sinned","he sin","he sinned","he sins","he will purify himself","he will sin","it has sinned","it sinned","it will purify itself","it will sin","she has sinned","they are bewildered","they caused to sin","they cleansed [it] from sin","they had sinned","they have sinned","they should cause to sin","they sinned","they will sin","to cause to sin","to sin","we have sinned","will he sin","will you sin","you had sinned","you have sinned","you sin","you sinned","you will cause to sin","you will miss","you will purify yourselves","you will sin"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9030/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["<on>/ me","[are] on/ me","[be] on/ me","[is] on/ me","above/ me","at/ me","on <the>/ me","on/ me","on/ myself","over/ me","over/ myself","to/ me","towards/ me","with/ me"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4467}/H9020/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["kingdom/ my"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2401}/[H2399]', 'lemma', 'heb', 'חֲטָאָה', '["chăṭâʼâh"]', '["a sin","sin"]', '["n-f"]', 'an offence, or a sacrifice for it sin (offering).', 'feminine of 2399;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639K}/[H6213]', 'lemma', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["<the> deed of","[the] deed of","[the] deed[s] of","[the] deeds of","[the] work of","a deed","deed","deeds"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3374}/[H3373]', 'lemma', 'heb', 'יִרְאָה', '["yirʼâh"]', '["[is] [the] fear of","[the] fear of","a fear","fear","fear of"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4725}/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["<in> the/ place","at the/ place","for the/ place","in the/ place","in/ [the] place","in/ [the] place of","in/ a place","in/ a place of","on the/ place"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2026}/H9030/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["and/ he will kill/ me","and/ they will kill/ me"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0802H}/H9020/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["[is] wife/ my","wife/ my","wives/ my"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0546}/[H544]', 'lemma', 'heb', 'אׇמְנָה', '["ʼomnâh"]', '["truly"]', '["adv"]', 'adverb, surely indeed.', 'feminine form of 544 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0517}/H9020/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["O mother/ my","mother/ my"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8582}/[H8582]', 'lemma', 'heb', 'תָּעָה', '["tâʻâh"]', '["I have gone astray","[are] misleading","[he was] wandering","[is] leading astray","[those who] go astray of","[which] leads astray","[who] go astray of","[who] wanders","do they go astray","he has been led astray","it go astray","it has misled","it has wandered","misleading","they caused to wander","they go astray","they have misled","they have wandered","they staggered","they wandered","they wandered about","they went astray","they will wander","they will wander about","wandering off","we have gone astray","you caused to err"]', '["v"]', 'to vacillate, i.e. reel or stray (literally or figuratively); also causative of both (cause to) go astray, deceive, dissemble, (cause to, make to) err, pant, seduce, (make to) stagger, (cause to) wander, be out of the way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004B}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ [the] house of","from/ [the] household of","from/ a house of","from/ between","from/ house","from/ inside","more than/ a house"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2617A}/H9022/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["[is] loyalty/ your","loyalty/ your"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776G>/H9020', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["land/ my","own land/ my"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2896A}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["for/ good","in the/ [place] good","in the/ good [place]"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869I}/H9021/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ own eyes/ your","in/ view/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0505G}/[H504]', 'lemma', 'heb', 'אֶלֶף', '["ʼeleph"]', '["<the> thousand","[are] [the] thousands of","[the] families of","[the] one thousand","[was] two thousand","a thousand","a thousand [cubits]","one thousand","thousand","thousand [cubits]","thousand<s>","thousands","thousands of","two thousand"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251G}/H9022/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["to/ brother/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3682}/[H3680]', 'lemma', 'heb', 'כְּסוּת', '["kᵉçûwth"]', '["[is] a covering of","[is] covering","a covering","covering"]', '["n-f"]', 'a cover (garment); figuratively, a veiling covering, raiment, vesture.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9032/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["[are] with/ you","[is] with/ you","with <the>/ you","with/ you"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3198}/[H3198]', 'inflected', 'heb', 'יָכַח', '["yâkach"]', '["<and>/ [you are] vindicated","and/ [one who] reproves","and/ he may argue","and/ to argue","and/ to reprove","and/ you may argue","so/ let us argue our case together","so/ they may decide"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6419}/[H6419]', 'inflected', 'heb', 'פָּלַל', '["pâlal"]', '["and/ I prayed","and/ he mediated","and/ he prayed","and/ he will pray","and/ she prayed","and/ they will pray","and/ we prayed","and/ you will pray"]', '["v"]', 'to judge (officially or mentally); by extension, to intercede, pray intreat, judge(-ment), (make) pray(-er, -ing), make supplication.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7495}/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["and/ he healed","and/ he repaired","and/ it will be healed","and/ someone will heal","and/ they have been healed","and/ they have healed","and/ they will be healed"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0519}/H9023/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["and/ female servant/ his","and/ female slaves/ his"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6113}/[H6113]', 'lemma', 'heb', 'עָצָר', '["ʻâtsâr"]', '["<he> had shut up","I have retained","I retained","I will shut up","[am] shut up","[is] shut up","[is] withheld","[was] detained","[was] shut up","certainly <to shut up>","he holds back","he retain","he retained","he will rule","kept back","let us detain","she will retain","shut up","they restrained","they retained","we will retain","will he retain","you hold back"]', '["v"]', 'to inclose; by analogy, to hold back; also to maintain, rule, assemble × be able, close up, detain, fast, keep (self close, still), prevail, recover, refrain, × reign, restrain, retain, shut (up), slack, stay, stop, withhold (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1157}/[H5704]', 'lemma', 'heb', 'בְּעַד', '["bᵉʻad"]', '["[the] price","behind","for","through"]', '["prep"]', 'in up to or over against; generally at, beside, among, behind, for, etc. about, at by (means of), for, over, through, up (-on), within.', 'from 5704 with prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7358}/[H7355]', 'lemma', 'heb', 'רֶחֶם', '["rechem"]', '["[the] womb","a womb","womb"]', '["n-m"]', 'the womb matrix, womb.', 'from 7355; (compare 7356)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004M}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["<into>/ a house of","[are] for/ [the] household of","by/ [the] house of","for the/ household","for/ [the] house of","for/ [the] household of","for/ a household of","of/ [the] house of","of/ [the] household of","of/ a house of","to the/ households","to/ [the] house of","to/ [the] household of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0085>\', 'opaque', 'heb', 'אַבְרָהָם', '["ʼAbrâhâm"]', '["Abraham","[is] Abraham"]', '["n-pr-m"]', 'Abraham, the later name of Abram Abraham.', 'contracted from 1 and an unused root (probably meaning to be populous); father of a multitude;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485I}/[H6485]', 'lemma', 'heb', 'פָּקַד', '["pâqad"]', '["I have observed","I will give attention to","I will visit [judgment]","[am] about to visit","[who] visits","attend to","certainly <to observe>","certainly <to visit>","he had observed","he had visited","he visited","he visits","he will be visited","he will visit","it will be visited","visiting","you have paid attention to","you have visited","you visit","you will be visited","you will pay attention"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2208}/H9023/[H2204]', 'inflected', 'heb', 'זָקֻן', '["zâqun"]', '["of/ old age<s>/ his"]', '["n-m"]', 'old age old age.', 'properly, passive participle of 2204 (used only in the plural as a noun);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3205}/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["the/ [one who] causes to bring forth","the/ [ones] born","the/ [woman who] gives birth","the/ child","the/ midwife","the/ midwives","who/ bore","who/ fathered","who/ had been born","who/ is about to be born","who/ were born"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6712}/[H6711]', 'lemma', 'heb', 'צְחֹק', '["tsᵉchôq"]', '["laughter"]', '["n-m"]', 'laughter (in pleasure or derision) laugh(-ed to scorn).', 'from 6711;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8085G}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["O those/ [who] hear","the/ [one who] hears","those/ [who] heard","which/ is being heard","who/ hear","who/ heard","who/ hears"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4448A}/[H4448]', 'lemma', 'heb', 'מָלַל', '["mâlal"]', '["has he said","they speak","will he tell","will you say"]', '["v"]', 'to speak (mostly poetical) or say say, speak, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3243H}/[H3243]', 'lemma', 'heb', 'יָנַק', '["yânaq"]', '["she has suckled","suckling","they suckle"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3206}/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["<of the>/ children","the/ [male] children","the/ boy","the/ child","the/ children","the/ lad","the/ young men","the/ youth","the/ youths"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1580}/[H1580]', 'inflected', 'heb', 'גָּמַל', '["gâmal"]', '["and/ he was weaned","and/ it had ripened","and/ she weaned"]', '["v"]', 'to treat a person (well or ill), i.e. benefit or requite; by implication (of toil), to ripen, i.e. (specifically) to wean bestow on, deal bountifully, do (good), recompense, requite, reward, ripen, serve, mean, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1580}/[H1580]', 'lemma', 'heb', 'גָּמַל', '["gâmal"]', '["I have repaid","[are] repaying","[is] dealing bountifully with","[those] weaned","a weaned [child]","deal bountifully","do you repay","he has dealt bountifully","he has repaid","he will be weaned","ripening","they have done","was weaned","we dealt out to","you deal bountifully"]', '["v"]', 'to treat a person (well or ill), i.e. benefit or requite; by implication (of toil), to ripen, i.e. (specifically) to wean bestow on, deal bountifully, do (good), recompense, requite, reward, ripen, serve, mean, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1644H}/[H1644]', 'lemma', 'heb', 'גָּרַשׁ', '["gârash"]', '["divorced","drive out"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0519}/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["the/ maidservants","the/ slave woman"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121A}/H9024/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["[is] son/ her","[was] son/ her","[were] sons/ her","children/ her","son/ her","sons/ her","young ones/ its"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121A}/H9020/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["O child/ my","O son/ my","O sons/ my","[are] children/ my","[are] son/ my","[are] sons/ my","[is] son/ my","children/ my","son/ my","sons/ my"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7489A}/[H7489]', 'inflected', 'heb', 'רָעַע', '["râʻaʻ"]', '["and/ he did evil","and/ he will do harm","and/ it was bad","and/ it was displeasing","and/ it was evil","and/ it will be bad","and/ it will be displeasing","and/ it will be evil","and/ they did harm","and/ they did harm to","and/ you have done evil"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0182}/[H181]', 'lemma', 'heb', 'אוֹדוֹת', '["ʼôwdôwth"]', '["[the] causes of","causes"]', '["n-f"]', 'turnings (i.e. occasions); (adverb) on account of (be-) cause, concerning, sake.', 'or (shortened) אֹדוֹת (only thus in the plural); from the same as 181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0519}/H9021/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["female slave/ your","maidservant/ your","slave woman/ your"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085H}/[H8085]', 'lemma', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["I have heard","I have listened","I listened","I will listen","[are] listening","[is] listening","carefully <to listen>","certainly [if] <listen>","certainly [if] <to listen>","certainly [if] <to obey>","did you listen","he listened","he will obey","listen","she has listened","they became obedient","they become obedient","they had listened","they have listened","they have obeyed","they listened","they may hear","to listen","to obey","we have listened","we listened","we will listen","you have listened","you have listened to","you listened","you will listen","you will listen to","you will obey"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963A>/H9024', 'inflected', 'heb', 'בקולה', '["be./ko.La/h"]', '["to/ voice/ her","with/ voice/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3327}/[H6711]', 'inflected', 'heb', 'יִצְחָק', '["Yitschâq"]', '["in/ Isaac"]', '["n-pr-m"]', 'Jitschak (or Isaac), son of Abraham Isaac. Compare 3446.', 'from 6711; laughter (i.e. mochery);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760A}/H9033/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["I have appointed/ him","I will make/ him","I will make/ it","he appointed/ him","he established/ it","he has made/ it","it placed/ it","she made/ it"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2573}/[H2346]', 'inflected', 'heb', 'חֵמֶת', '["chêmeth"]', '["and/ a skin of"]', '["n-m"]', 'a skin bottle (as tied up) bottle.', 'from the same as 2346;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760H}/[H7760]', 'lemma', 'heb', 'שׂוּם', '["sûwm"]', '["I appointed","I have put","I put","I will make","I will put","I will set","[those who] make","[who] puts","[who] puts [it]","did he put","he had put","he had stationed","he has appointed","he made","he performed","he put","he put [them] out","he puts","he set","he will place","he will put","it set","let them give","let them put","let us put","make","may he appoint","placing","put","really <set>","set","she put","someone puts","they have made","they have put","they have put [them]","they performed","they put","they will put","they will set","to establish","will I put?","you have made","you have put","you put","you put [it]","you will place","you will put","you will set"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7926}/H9024/[H7925]', 'inflected', 'heb', 'שְׁכֶם', '["shᵉkem"]', '["shoulder/ her"]', '["n-m"]', 'the neck (between the shoulders) as the place of burdens; figuratively, the spur of a hill back, × consent, portion, shoulder.', 'from 7925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971I}/H9034/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ he sent away/ her","and/ he will send away/ her"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8582}/[H8582]', 'inflected', 'heb', 'תָּעָה', '["tâʻâh"]', '["and/ he misled","and/ she wandered","and/ they caused to err","and/ they have misled"]', '["v"]', 'to vacillate, i.e. reel or stray (literally or figuratively); also causative of both (cause to) go astray, deceive, dissemble, (cause to, make to) err, pant, seduce, (make to) stagger, (cause to) wander, be out of the way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0884}/[H875]', 'lemma', 'heb', 'בְּאֵר שֶׁבַע', '["Bᵉʼêr Shebaʻ"]', '["Beer","Sheba","[is] Beer"]', '["n-pr-loc"]', 'Beer-Sheba, a place in Palestine Beer-shebah.', 'from 875 and 7651 (in the sense of 7650); well of an oath;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3615J}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["and/ I will complete","and/ he brought to an end","and/ it will be spent","and/ they have come to an end","and/ they were finished"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2573}/[H2346]', 'inflected', 'heb', 'חֵמֶת', '["chêmeth"]', '["the/ skin"]', '["n-m"]', 'a skin bottle (as tied up) bottle.', 'from the same as 2346;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7993}/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["and/ I threw","and/ I will cast out","and/ have they been thrown?","and/ he threw","and/ he threw [it]","and/ he threw [them]","and/ he threw down","and/ he will throw","and/ he will throw [them]","and/ it was thrown down","and/ she threw","and/ they threw","and/ they threw [it]","and/ they threw [them]","and/ they threw [them] out","and/ they threw down","and/ they will throw","and/ you have thrown","and/ you were thrown out","and/ you will throw"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7880}/[H7878]', 'inflected', 'heb', 'שִׂיחַ', '["sîyach"]', '["the/ bushes"]', '["n-m"]', 'a shoot (as if uttered or put forth), i.e. (generally) shrubbery bush, plant, shrub.', 'from 7878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5048}/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["from/ before","from/ in front"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7368}/[H7368]', 'lemma', 'heb', 'רָחַק', '["râchaq"]', '["I want to be far away","at a distance","be distant","certainly <to be far away>","far away","he has put far away","he has removed far away","he is far","he will be far","it has made far away","it is far","it is far away","it will be [too] far","it will be far","let them put far away","make far away","put far away","they are distant","they became distant","they had gone far","they had gone far away","to remove far away","you be distant","you be far","you go far away","you have extended","you have removed far away","you must be far away","you will be distant","you will remove"]', '["v"]', 'to widen (in any direction), i.e. (intransitively) recede or (transitively) remove (literally or figuratively, of place or relation) (a-, be, cast, drive, get, go, keep (self), put, remove, be too, (wander), withdraw) far (away, off), loose, × refrain, very, (be) a good way (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2909}/[H2909]', 'inflected', 'heb', 'טָחָה', '["ṭâchâh"]', '["like/ [the] shooters of"]', '["v"]', 'to stretch a bow, as an archer (bow-) shot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7198}/[H7185]', 'lemma', 'heb', 'קֶשֶׁת', '["qesheth"]', '["<of> a bow","Bow","[the] bow of","a bow","a bow of","bow","bow of","bow[s]","bowmen"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4194}/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["at/ [the] death of","by <the>/ death","in <the>/ death","in/ [the] death of","on/ [the] death of"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375N}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ he lifted up","and/ it lifted up","and/ she lifted up","and/ they lifted up","and/ they raised","and/ you will lift up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963A>/H9024', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["voice/ her"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1058}/[H1058]', 'inflected', 'heb', 'בָּכָה', '["bâkâh"]', '["and/ I wept","and/ he wept","and/ he wept for","and/ she wept","and/ she will weep for","and/ they wept","and/ they wept for","and/ they will weep","and/ you have wept","and/ you wept"]', '["v"]', 'to weep; generally to bemoan × at all, bewail, complain, make lamentation, × more, mourn, × sore, × with tears, weep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0834B}/[H834]', 'inflected', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["<in>/ [that] which","at/ where","because/ <which>","in/ [that] which","in/ that","in/ where","in/ which"]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375G}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["I lift up","I will lift myself up","I will lift up","I will rise up","I will take","I will take up","[thing] lifted up","[was] raised","he will carry","he will lift up","he will take","it arises","it has lifted","it lifts itself up","it will be lifted up","let them take","lift up","lifted up","pick [him] up","raise","raise yourself","raise yourself up","take up","taking away","they have lifted","they have lifted up","they lift up","they lifted","they lifted up","they were lifted up","they will carry","they will exalt themselves","to exalt itself","will I take","you must take","you should lift up","you will carry [them] away","you will lift [it] up","you will take"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2388H}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ I may take hold","and/ [one who] takes hold","and/ [they are] keeping hold","and/ [those who] keep hold","and/ take hold"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}/H9022/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your","hands/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869A}/H9024/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eye/ her","eyes/ her"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7235B}/[H7235]', 'lemma', 'heb', 'רָבָה', '["râbâh"]', '["a shooter"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7199}/[H7198]', 'lemma', 'heb', 'קַשָּׁת', '["qashshâth"]', '["a bowman"]', '["n-m"]', 'a bowman × archer.', 'intensive (as denominative) from 7198;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6290G}/[H6286]', 'lemma', 'heb', 'פָּארָן', '["Pâʼrân"]', '["Paran"]', '["n-pr-loc"]', 'Paran, a desert of Arabia Paran.', 'from 6286; ornamental;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0776G>', 'inflected', 'heb', 'מארצות', '["me./''A.retz","me./''E.retz","me./''ar.Tzot","me./''e.retz"]', '["[is] from/ [the] land of","[were] from/ [the] land of","any of/ [the] land of","from/ [the] earth","from/ [the] ground","from/ [the] land","from/ [the] land of","from/ [the] lands of","from/ a land","from/ a land of","more than/ [the] earth"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4714G}\/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["Egypt","of Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6256}/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["at the/ appropriate time","at the/ time","at/ [the] time","at/ [the] time of","at/ a time of","at/ times","in the/ times","in/ [the] time of","in/ a time","in/ a time of"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6369}/[H6310]', 'inflected', 'heb', 'פִּיכֹל', '["Pîykôl"]', '["and/ Phicol"]', '["n-pr-m"]', 'Picol, a Philistine Phichol.', 'apparently from 6310 and 3605; mouth of all;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635A}/H9023/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["army/ his","army/ its","hosts/ his","military group/ its"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/H9031/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[am] with/ you","[has been] with/ you","[is] with/ you","[will be] with/ you","with/ you"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7650}/H9012/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["swear an oath/ !","swear/ !"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0430G}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["[is] in/ God","against/ God","against/ [the] God of","by/ God","by/ [the] God of","in/ God","in/ [the] God of"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8266}/[H8266]', 'lemma', 'heb', 'שָׁקַר', '["shâqar"]', '["I will deal falsely","he will deal falsely","they will deal falsely","we had dealt falsely","you will deal falsely"]', '["v"]', 'to cheat, i.e. be untrue (usually in words) fail, deal falsely, lie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5209}/H9020/[H5125]', 'inflected', 'heb', 'נִין', '["nîyn"]', '["and/ to/ posterity/ my"]', '["n-m"]', 'progeny son.', 'from 5125;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H5220>/H9020', 'inflected', 'heb', 'ולנכדי', '["u./le./nekh.D/i"]', '["and/ to/ progeny/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2617A}/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["according to the/ loyalty"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5973A}/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["and/ [was] with","and/ beside","and/ with"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1481A}/[H1481]', 'lemma', 'heb', 'גּוּר', '["gûwr"]', '["I have sojourned","[am] staying as a sojourner","[are] sojourning","[is] sojourning","[the] sojourners of","[was] sojourning","a sojourner","did he sojourn","he had sojourned","he has sojourned","he sojourned","he sojourns","he will sojourn","let me sojourn","let them sojourn","sojourn","sojourners","sojourning","they sojourned","will he sojourn","you have sojourned","you will sojourn"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9034}', 'inflected', 'arc', 'בה', '["Ba/h","Va/h","ba/h","be/h","va/h"]', '["<in> <the>/ her","<in> <the>/ it","<in>/ her","<in>/ it","[are] in <the>/ it","[are] in/ it","[are] on <the>/ it","[is] in <the>/ it","[is] in/ it","[was] in <the>/ it","[was] in/ her","[was] in/ it","[were] in <the>/ it","[were] in/ it","[will be] in/ it","against <the>/ her","against <the>/ it","against/ it","at/ it","by <the>/ her","by <the>/ it","by/ it","for/ her","for/ it","in <the>/ her","in <the>/ it","in/ her","in/ it","on <the>/ her","on <the>/ it","on/ her","on/ it","to/ her","with <the>/ her","with <the>/ it","with/ her","with/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7650}/[H7651]', 'lemma', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["I adjure","I have sworn an oath","I swear","I swore","I swore an oath","I will swear","[which] you swore an oath","certainly <to make swear>","certainly <to swear an oath>","did you swear an oath","he had made swear","he had sworn","he has sworn","he has sworn an oath","he made to swear an oath","he swears","he swears an oath","he swore","he swore an oath","he will swear","he will swear an oath","it will swear","it will swear an oath","let him swear","oaths of","swear","they are swearing oaths","they had sworn","they had sworn an oath","they have sworn","they swore","they swore an oath","we have sworn","we have sworn an oath","we swore","you had sworn","you must cause to swear","you swear","you swore","you swore an oath","you will swear an oath","you will swear oaths"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3198}/[H3198]', 'inflected', 'heb', 'יָכַח', '["yâkach"]', '["and/ he decided","and/ he is chastened","and/ he rebuked","and/ he will decide","and/ he will rebuke"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1497}/[H1497]', 'lemma', 'heb', 'גָּזַל', '["gâzal"]', '["I stole","[one who] has been robbed","[one who] robs","[will be] seized","a stolen [animal]","he has robbed","he has seized","he robbed","people tear away","tearers away of","they had seized","they seize","they seized","they snatch away","you rob","you should tear away","you will rob [him]"]', '["v"]', 'to pluck off; specifically to flay, strip or rob catch, consume, exercise (robbery), pluck (off), rob, spoil, take away (by force, violence), tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1115}/[H1086]', 'lemma', 'heb', 'בִּלְתִּי', '["biltîy"]', '["<of> not","[is] except","[is] not","except","not"]', '["np"]', 'properly, a failure of, i.e. (used only as a negative particle, usually with a prepositional prefix) not, except, without, unless, besides, because not, until, etc. because un(satiable), beside, but, continual, except, from, lest, neither, no more, none, not, nothing, save, that no, without.', 'constructive feminine of 1086 (equivalent to 1097);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0040G}/[H1]', 'inflected', 'heb', 'אֲבִימֶלֶךְ', '["ʼĂbîymelek"]', '["to/ Abimelech"]', '["n-pr-m"]', 'Abimelek, the name of two Philistine kings and of two Israelites Abimelech.', 'from 1 and 4428; father of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3772H}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ I will make","and/ he made","and/ it made","and/ they made","and/ you have cut off","and/ you made"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5324}/[H5324]', 'inflected', 'heb', 'נָצַב', '["nâtsab"]', '["and/ he had set up","and/ he made to stand up","and/ he set","and/ he set up","and/ they erected","and/ they set up","and/ they stood","and/ you will stand","and/ you will station yourself"]', '["v"]', 'to station, in various applications (literally or figuratively) appointed, deputy, erect, establish, × Huzzah (by mistake for a proper name), lay, officer, pillar, present, rear up, set (over, up), settle, sharpen, establish, (make to) stand(-ing, still, up, upright), best state.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3535}/[H3532]', 'lemma', 'heb', 'כִּבְשָׂה', '["kibsâh"]', '["[the] ewe-lamb of","a ewe-lamb","ewe-lambs","ewe-lambs of"]', '["n-f"]', 'a ewe (ewe) lamb.', 'or כַּבְשָׂה; feminine of 3532;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6629G>', 'inflected', 'heb', 'הצאן', '["ha./Tzon","ha./tzoN"]', '["<of> the/ flock","<the>/ flock[s]","the/ flock","the/ flock[s]","the/ sheep"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0905H}/H9039/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["to/ alone/ them"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027G}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5713A}/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["<into>/ a witness"]', '["n-f"]', 'testimony testimony, witness. Compare 5712.', 'feminine of 5707 in its techn. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2658}/[H2658]', 'lemma', 'heb', 'חָפַר', '["châphar"]', '["I dug","[one who] digs","it spies out","people had dug","they had dug","they have dug","they paw"]', '["v"]', 'properly, to pry into; by implication, to delve, to explore dig, paw, search out, seek.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0875}/[H874]', 'inflected', 'heb', 'בְּאֵר', '["bᵉʼêr"]', '["[is] the/ well","the/ well","the/ wells"]', '["n-f"]', 'a pit; especially a well pit, well.', 'from 874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0884}/[H875]', 'inflected', 'heb', 'בְּאֵר שֶׁבַע', '["Bᵉʼêr Shebaʻ"]', '["at/ Beer","in/ Beer"]', '["n-pr-loc"]', 'Beer-Sheba, a place in Palestine Beer-shebah.', 'from 875 and 7651 (in the sense of 7650); well of an oath;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6430G}/[H6429]', 'lemma', 'heb', 'פְּלִשְׁתִּי', '["Pᵉlishtîy"]', '["O Philistines","Philistines","[the] Philistines","of [the] Philistines"]', '["a"]', 'a Pelishtite or inhabitant of Pelesheth Philistine.', 'patrial from 6429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0815}/[H815]', 'lemma', 'heb', 'אֵשֶׁל', '["ʼêshel"]', '["a tamarisk tree"]', '["n-m"]', 'a tamarisk tree; by extension, a grove of any kind grove, tree.', 'from a root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5769H}/[H5956]', 'lemma', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["perpetuity"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7227A}\/[H7231]', 'inflected', 'heb', 'רַב', '["rab"]', '["many","much"]', '["a n-m"]', 'abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent).', 'by contracted from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0430G}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ <the>/ God"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5254G}/[H5254]', 'lemma', 'heb', 'נָסָה', '["nâçâh"]', '["I have put to [the] test","I will put to [the] test","[is] putting to [the] test","he had put to [the] test","he put to [the] test","let me put to [the] test","put to [the] test","to put to [the] test","you put [him] to [the] test","you will put to [the] test"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3173}/H9021/[H3161]', 'inflected', 'heb', 'יָחִיד', '["yâchîyd"]', '["only [son]/ your"]', '["a"]', 'properly, united, i.e. sole; by implication, beloved; also lonely; (feminine) the life (as not to be replaced) darling, desolate, only (child, son), solitary.', 'from 3161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157G}/[H157]', 'lemma', 'heb', 'אָהַב', '["ʼâhab"]', '["I have loved","I love","O [you who] love","[am] loving","[he is] loving","[is] loved","[is] loving","[one who] loves","[they] love","[those who] love","[was] loving","[were] loving","[which] loved","[who] is loved of","[who] loves","[who] loves?","a friend","he loved","he loves","love","loving","they have loved","they love","will you love","will you love?","you have loved","you love","you loved"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4179}/[H7200]', 'inflected', 'heb', 'מוֹרִיָּה', '["Môwrîyâh"]', '["<the>/ Moriah"]', '["n-pr-loc"]', 'Morijah, a hill in Palestine Moriah.', 'or מֹרִיָּה; from 7200 and 3050; seen of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5927I}/H9033/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ offer up/ him"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5930A}/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["[is] for/ [the] burnt offering of","[was] for the/ burnt offerings","[were] for/ a burnt offering","for the/ burnt offering","for the/ burnt offerings","for/ [the] burnt offerings of","for/ a burnt offering","for/ burnt offering","of the/ burnt offering","to the/ burnt offering","to/ a burnt offering"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2280}/[H2280]', 'inflected', 'heb', 'חָבַשׁ', '["châbash"]', '["and/ he bound on","and/ he saddled","and/ she saddled","and/ they saddled","and/ they saddled [it]","and/ you will bind on"]', '["v"]', 'to wrap firmly (especially a turban, compress, or saddle); figuratively, to stop, to rule bind (up), gird about, govern, healer, put, saddle, wrap about.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2543}/H9023/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["donkey/ his","donkey[s]/ his"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5288}/H9023/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["servant/ his","servants/ his","young man/ his"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1234}/[H1234]', 'inflected', 'heb', 'בָּקַע', '["bâqaʻ"]', '["and/ I will make break out","and/ he cut","and/ he split open","and/ it was broken into","and/ it was split open","and/ it will be split open","and/ it will hatch","and/ they broke through","and/ they split","and/ they tore in pieces","and/ they were divided","and/ you broke"]', '["v"]', 'to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7350}/[H7368]', 'inflected', 'heb', 'רָחוֹק', '["râchôwq"]', '["from/ a distance","from/ a distant [land]","from/ distant [time]"]', '["a"]', 'remote, literally or figuratively, of place or time; specifically, precious; often used adverbially (with preposition) (a-) far (abroad, off), long ago, of old, space, great while to come.', 'or רָחֹק; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2543}/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["<the>/ donkeys","the/ donkey","the/ donkeys"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5288}/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["and/ the/ lad"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7812}/[H7812]', 'inflected', 'heb', 'שָׁחָה', '["shâchâh"]', '["and/ [they were] bowing down","and/ bow down","and/ bowing down","and/ may they bow down","and/ they may bow down","so/ I may bow down","so/ he may bow down","so/ may they bow down","so/ they may bow down","so/ we may bow down"]', '["v"]', 'to depress, i.e. prostrate (especially reflexive, in homage to royalty or God) bow (self) down, crouch, fall down (flat), humbly beseech, do (make) obeisance, do reverence, make to stoop, worship.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5930A}/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["<the>/ burnt offering","the/ burnt offering","the/ burnt offering[s]","the/ burnt offerings"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0784}/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["<the>/ fire","the/ fire"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3979}/[H398]', 'inflected', 'heb', 'מַאֲכֶלֶת', '["maʼăkeleth"]', '["the/ knife"]', '["n-f"]', 'something to eat with, i.e. a knife knife.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6086G}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["and/ the/ wood<s>"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0346}/[H335]', 'inflected', 'heb', 'אַיֵּה', '["ʼayêh"]', '["and/ where?"]', '["adv"]', 'where? where.', 'prolonged from 335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7716}/[H7582]', 'inflected', 'heb', 'שֶׂה', '["seh"]', '["<the>/ lamb","[is] the/ sheep","the/ lamb","the/ sheep"]', '["n-m"]', 'a member of a flock, i.e. a sheep or goat (lesser, small) cattle, ewe, goat, lamb, sheep. Compare 2089.', 'or שֵׂי; probably from 7582 through the idea of pushing out to graze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200J}/[H7200]', 'lemma', 'heb', 'רָאָה', '["râʼâh"]', '["I had considered","I have seen","consider","he will see","let him see","look"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6086G}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["the/ wood<s>"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6123}/[H6123]', 'inflected', 'heb', 'עָקַד', '["ʻâqad"]', '["and/ he bound"]', '["v"]', 'to tie with thongs bind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4605}/[H5927]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["<from>/ above","[was] from/ above","from/ above"]', '["adv"]', 'properly,the upper part, used only adverbially with prefix upward, above, overhead, from the top, etc. above, exceeding(-ly), forward, on (× very) high, over, up(-on, -ward), very.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6086G}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["<to> the/ wood<s>","for the/ wood<s>","to <the>/ wood","to/ wood of"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7819A}/[H7819]', 'inflected', 'heb', 'שָׁחַט', '["shâchaṭ"]', '["to/ slaughter"]', '["v n-f"]', 'to slaughter (in sacrifice or massacre) kill, offer, shoot out, slay, slaughter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[is] hand/ your","hand/ your","hands/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3972}/[H3971]', 'lemma', 'heb', 'מְאוּמָה', '["mᵉʼûwmâh"]', '["[is] anything","anything"]', '["x"]', 'properly, a speck or point, i.e. (by implication) something; with negative, nothing fault, no(-ught), ought, somewhat, any (no-)thing.', 'apparently a form of 3971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3373}/[H3372]', 'lemma', 'heb', 'יָרֵא', '["yârêʼ"]', '["<the> fearing","O [those] fearing","[am] fearing","[are one] fearing","[are] afraid","[are] fearful","[are] fearing","[is one] fearing","[is] fearful","[is] fearing","[one] fearing","[those] fearing","fearing","he has feared"]', '["a"]', 'fearing; morally, reverent afraid, fear (-ful).', 'from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2820}/[H2821]', 'lemma', 'heb', 'חָשַׂךְ', '["châsak"]', '["I have kept back","I will restrain","[one who] restrains","anyone restrained","he has restrained","he has withheld","he is spared","he keeps back","he kept back","he restrained","he will keep back","it will be restrained","it will restrain","it will withhold","keep back","they have restrained","they have withheld","you have withheld","you refrain","you will restrain"]', '["v"]', 'to restrain or (reflex.) refrain; by implication, to refuse, spare, preserve; to observe assuage, × darken, forbear, hinder, hold back, keep (back), punish, refrain, reserve, spare, withhold.', 'a primitive root; also interchangeable with 2821');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4480A}/H9030/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["for/ me","from/ me","more than/ I","more than/ me"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0352A}/[H193]', 'lemma', 'heb', 'אַיִל', '["ʼayil"]', '["[is] a ram of","[the] ram of","[the] rams of","a ram","a ram of","rams"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0270}/[H270]', 'lemma', 'heb', 'אָחַז', '["ʼâchaz"]', '["I will take hold","[are] grasped of","[he] covers","[one who] holds","[person] drawn","[was] held","[was] holding","[were] attached","drawn","he has taken hold","it has seized","it has taken hold","it takes hold","it was caught","seize","supports","they had possessions","they take hold of","to have hold","you held","you take hold","you will take hold"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5442}/[H5440]', 'inflected', 'heb', 'סְבָךְ', '["çᵉbâk"]', '["<in>/ [the] thickets of","in the/ thicket","in/ a thicket of"]', '["n-m"]', 'a copse thick(-et).', 'from 5440,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7161A}/H9023/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["by/ horns/ its"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0352A}/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["the/ ram","the/ rams"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5927I}/H9033/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ I will offer up/ it","and/ he offered up/ him","and/ he offered up/ it"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200N}/[H7200]', 'lemma', 'heb', 'רָאָה', '["râʼâh"]', '["he will see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9030}', 'inflected', 'arc', 'בי', '["B/i","V/i","b/i","bi/","v/i","vi/"]', '["<in> <the>/ me","<in>/ me","<on> <the>/ me","[be] on <the>/ me","[is] in <the>/ me","[is] in/ me","[will be] on/ me","against <the>/ me","against/ me","by <the>/ me","by <the>/ myself","by/ me","by/ myself","for/ me","in <the>/ me","in/ me","in/ myself","on <the>/ me","on/ me","over/ me","to/ me","with <the>/ me","with/ me"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5002}/[H5001]', 'lemma', 'heb', 'נְאֻם', '["nᵉʼum"]', '["[the] utterance of","an utterance"]', '["n-m"]', 'an oracle (hath) said, saith.', 'from 5001;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3282>', 'opaque', 'heb', 'יַעַן', '["yaʻan"]', '["because","because of"]', '["conj"]', 'properly, heed; by implication, purpose (sake or account); used adverbially to indicate the reason or cause because (that), forasmuch ( as), seeing then, that, whereas, why.', 'from an unused root meaning to pay attention;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3556}/[H3522]', 'inflected', 'heb', 'כּוֹכָב', '["kôwkâb"]', '["[are] like/ [the] stars of","like the/ stars","like/ [the] stars of"]', '["n-m"]', 'a star (as round or as shining); figuratively, a prince star(-gazer).', 'probably from the same as 3522 (in the sense of rolling) or 3554 (in the sense of blazing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H2344}/[H2342]', 'inflected', 'heb', 'חוֹל', '["chôwl"]', '["and/ like <the>/ sand","and/ like the/ sand","and/ like/ [the] sand of"]', '["n-m"]', 'sand (as round or whirling particles) sand.', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193J}/[H5595]', 'lemma', 'heb', 'שָׂפָה', '["sâphâh"]', '["[the] bank of","[the] shore of"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3423H}/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["and/ certainly <to dispossess>","and/ take possession of","and/ they may take possession of","so/ <it> may take possession of","so/ may it take possession of"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8179G}/[H8176]', 'lemma', 'heb', 'שַׁעַר', '["shaʻar"]', '["<of> [the] gate of","Gate","O gate","O gates","[is] [the] gate of","[the] gate","[the] gate of","[the] gates","[the] gates of","a gate","gate","gates"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0341}/H9023/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["enemies/ his","enemies/ its","enemy/ his","enemy/ its"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2233H}/H9021/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["by/ offspring/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6118}/[H6117]', 'lemma', 'heb', 'עֵקֶב', '["ʻêqeb"]', '["[the] consequence of","consequence","end"]', '["n-m"]', 'a heel, i.e. (figuratively) the last of anything (used adverbially, for ever); also result, i.e. compensation; and so (adverb with preposition or relatively) on account of × because, by, end, for, if, reward.', 'from 6117 in the sense of 6119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963A>/H9020', 'inflected', 'heb', 'בקולי', '["be./ko.L/i","ve./Ko.L/i","ve./ko.L/i"]', '["to/ voice/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0884}\/[H875]', 'inflected', 'heb', 'בְּאֵר שֶׁבַע', '["Bᵉʼêr Shebaʻ"]', '["Sheba"]', '["n-pr-loc"]', 'Beer-Sheba, a place in Palestine Beer-shebah.', 'from 875 and 7651 (in the sense of 7650); well of an oath;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5152H}/[H5170]', 'inflected', 'heb', 'נָחוֹר', '["Nâchôwr"]', '["to/ Nahor"]', '["n-pr-m"]', 'Nachor, the name of the grandfather and a brother of Abraham Nahor.', 'from the same as 5170; snorer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5780H}/[H5779]', 'lemma', 'heb', 'עוּץ', '["ʻÛwts"]', '["Uz"]', '["n-pr-m n-pr-loc"]', 'Uts, a son of Aram, also a Seirite, and the regions settled by them. Uz.', 'apparently from 5779; consultation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0938G}/[H937]', 'lemma', 'heb', 'בּוּז', '["Bûwz"]', '["Buz"]', '["n-pr-m"]', 'Buz, the name of a son of Nahor, and of an Israelite Buz.', 'the same as 937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7055G}/[H6965]', 'lemma', 'heb', 'קְמוּאֵל', '["Qᵉmûwʼêl"]', '["Kemuel"]', '["n-pr-m"]', 'Kemuel, the name of a relative of Abraham, and of two Israelites Kemuel.', 'from 6965 and 410; raised of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0758H}/[H759]', 'lemma', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3777>', 'opaque', 'heb', 'כֶּשֶׂד', '["Kesed"]', '["Kesed"]', '["n-pr-m"]', 'Kesed, a relative of Abraham Chesed.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2375}/[H2372]', 'lemma', 'heb', 'חֲזוֹ', '["Chăzôw"]', '["Hazo"]', '["n-pr-m"]', 'Chazo, a nephew of Abraham Hazo.', 'from 2372; seer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6394>', 'opaque', 'heb', 'פִּלְדָּשׁ', '["Pildâsh"]', '["Pildash"]', '["n-pr-m"]', 'Pildash, a relative of Abraham Pildash.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3044}/[H1811]', 'lemma', 'heb', 'יִדְלָף', '["Yidlâph"]', '["Jidlaph"]', '["n-pr-m"]', 'Jidlaph, a Mesopotamian Jidlaph.', 'from 1811; tearful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1328A}/[H1326]', 'lemma', 'heb', 'בְּתוּאֵל', '["Bᵉthûwʼêl"]', '["Bethuel"]', '["n-pr-m n-pr-loc"]', 'Bethuel, the name of a nephew of Abraham, and of a place in Palestine Bethuel. Compare 1329.', 'apparently from the same as 1326 and 410; destroyed of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1328A}/[H1326]', 'inflected', 'heb', 'בְּתוּאֵל', '["Bᵉthûwʼêl"]', '["and/ Bethuel"]', '["n-pr-m n-pr-loc"]', 'Bethuel, the name of a nephew of Abraham, and of a place in Palestine Bethuel. Compare 1329.', 'apparently from the same as 1326 and 410; destroyed of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7259>', 'opaque', 'heb', 'רִבְקָה', '["Ribqâh"]', '["Rebekah"]', '["n-pr-f"]', 'Ribkah, the wife of Isaac Rebekah.', 'from an unused root probably meaning to clog by tying up the fetlock; fettering (by beauty);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6370>/H9023', 'inflected', 'heb', 'ופילגשהו', '["u./Fi.lag.Sha/v","u./fi.lag.Sh/o","u./fi.lag.She./hu"]', '["and/ concubine/ his","and/ concubines/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7208}/[H7213]', 'lemma', 'heb', 'רְאוּמָה', '["Rᵉʼûwmâh"]', '["[was] Reumah"]', '["n-pr-f"]', 'Reumah, a Syrian woman Reumah.', 'feminine passive participle of 7213; raised;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2875}/[H2874]', 'lemma', 'heb', 'טֶבַח', '["Ṭebach"]', '["Tebah"]', '["n-pr-m"]', 'Tebach, the name of a Mesopotamian and of an Israelite Tebah.', 'the same as 2874; massacre;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1514>', 'opaque', 'heb', 'גַּחַם', '["Gacham"]', '["Gaham"]', '["n-pr-m"]', 'Gacham, a son of Nahor Gaham.', 'from an unused root meaning to burn; flame;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8477}/[H8476]', 'lemma', 'heb', 'תַּחַשׁ', '["Tachash"]', '["Tahash"]', '["n-pr-m"]', 'Tachash, a relative of Abraham Thahash.', 'the same as 8476;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4601G}\/[H4600]', 'inflected', 'heb', 'מַעֲכָה', '["Maʻăkâh"]', '["Maacah"]', '["n-pr"]', 'Maakah (or Maakath), the name of a place in Syria, also of a Mesopotamian, of three Israelites, and of four Israelitesses and one Syrian woman Maachah, Maachathites. See also 1038.', 'or מַעֲכָת; (Joshua 13:13), from 4600; depression;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7153}/[H7151]', 'inflected', 'heb', 'קִרְיַת אַרְבַּע', '["Qiryath ʼArbaʻ"]', '["at/ Kiriath","in/ Kiriath"]', '["n-pr-loc"]', 'Kirjath-Arba or Kirjath-ha-Arba, a place in Palestine Kirjath-arba.', 'or (with the article interposed) קִרְיַת הָאַרְבַּע; (Nehemiah 11:25), from 7151 and 704 or 702; city of Arba, or city of the four (giants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7153}/[H7151]', 'lemma', 'heb', 'קִרְיַת אַרְבַּע', '["Qiryath ʼArbaʻ"]', '["<the> Arba","Arba","Kiriath","[was] Kiriath"]', '["n-pr-loc"]', 'Kirjath-Arba or Kirjath-ha-Arba, a place in Palestine Kirjath-arba.', 'or (with the article interposed) קִרְיַת הָאַרְבַּע; (Nehemiah 11:25), from 7151 and 704 or 702; city of Arba, or city of the four (giants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2275A}/[H2267]', 'lemma', 'heb', 'חֶבְרוֹן', '["Chebrôwn"]', '["Hebron","[is] Hebron"]', '["n-pr-loc n-pr-m"]', 'Chebron, a place in Palestine, also the name of two Israelites Hebron.', 'from 2267; seat of association;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5594}/[H5594]', 'inflected', 'heb', 'סָפַד', '["çâphad"]', '["to/ lament","to/ mourn"]', '["v"]', 'properly, to tear the hair and beat the breasts (as Orientals do in grief); generally to lament; by implication, to wail lament, mourn(-er), wail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1058}/H9034/[H1058]', 'inflected', 'heb', 'בָּכָה', '["bâkâh"]', '["and/ to/ weep for/ her"]', '["v"]', 'to weep; generally to bemoan × at all, bewail, complain, make lamentation, × more, mourn, × sore, × with tears, weep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9023/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["dead/ his"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8453A}/[H3427]', 'inflected', 'heb', 'תּוֹשָׁב', '["tôwshâb"]', '["and/ a resident alien","and/ resident aliens"]', '["n-m"]', 'a dweller but not outlandish [5237]; especially (as distinguished from a native citizen [active participle of 3427] and a temporary inmate [1616] or mere lodger [3885]) resident alien foreigner, inhabitant, sojourner, stranger.', 'or תֹּשָׁב; (1 Kings 17:1), from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/H9036/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[are] with/ you","[be] with/ you","[is] with/ you","[will be] with/ you","with/ you"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0272}/[H270]', 'lemma', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["[is] a possession of","[the] possession of","a possession","a possession of","possession of"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6913}/[H6912]', 'lemma', 'heb', 'קֶבֶר', '["qeber"]', '["[is] a grave","[the] burial site of","[the] grave","[the] grave of","[the] graves of","[the] tombs of","[were] graves","a burial site","a grave","a tomb","grave<s>"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6912}/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["and/ bury","so/ I may bury","so/ let me bury"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9020/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["dead/ my"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H6440H}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ to/ before/ me"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085G}/H9035/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["listen to/ us"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
