INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3607}/[H3607]', 'lemma', 'heb', 'כָּלָא', '["kâlâʼ"]', '["I have restrained","I restrain","[I am] shut up","he will withhold","it has withheld","shut up","they have withheld","they shut up","you will withhold","you withhold"]', '["v"]', 'to restrict, by act (hold back or in) or word (prohibit) finish, forbid, keep (back), refrain, restrain, retain, shut up, be stayed, withhold.', 'a primitive root;');
