INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5971A}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["<into>/ a people","<into>/ a people of","<to> the/ people","[belonged] to the/ people","[belongs] to the/ people","[is] for the/ people","[is] to the/ people","[was] for the/ people","for the/ people","for/ peoples","into/ a people","of the/ people","to the/ people","to/ [the] people","to/ [the] people of","to/ [the] peoples of","to/ a people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121G}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["<into>/ a son of","<to>/ [the] people of","[and belonged] to/ [the] descendants of","[belong] to/ [the] descendants of","[belonged] to/ [the] descendants of","[belonged] to/ [the] people of","[that belongs] to/ [the] people of","for/ [the] children of","for/ [the] descendants of","for/ [the] people of","for/ [the] son of","for/ [the] sons of","of/ [the] descendants","of/ [the] descendants of","of/ [the] people of","of/ [the] sons of","to/ [the] children of","to/ [the] descendants of","to/ [the] people","to/ [the] people of","to/ [the] son of","to/ [the] sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315L}/H9026/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["appetite/ your","desire/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6912}/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["to/ bury"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085G}/H9030/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["cause to hear [it]/ me","cause to hear/ me","he will hear/ me","listen to/ me","make hear/ me","will he listen to/ me","you will make hear/ me"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6293}/[H6293]', 'inflected', 'heb', 'פָּגַע', '["pâgaʻ"]', '["and/ entreat","and/ fall"]', '["v"]', 'to impinge, by accident or violence, or (figuratively) by importunity come (betwixt), cause to entreat, fall (upon), make intercession, intercessor, intreat, lay, light (upon), meet (together), pray, reach, run.', 'a primitive root;');
