INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5414G}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I may give","and/ I will give","and/ I will give [it]","and/ give","and/ giving","and/ he may give","and/ let him give","and/ let me give","and/ let people give","and/ let them give","and/ let them put","and/ may he give","and/ they gave","so/ I may give","so/ he may give","so/ he may give [it]","so/ he may give up","so/ it may be given","so/ let me give","so/ let me give [it]","so/ let people give","so/ may he give","so/ she may be given up","so/ they may be given","sp/ it may be given"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
