INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704G>/H9023', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["field/ his"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
