INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947H}/[H3947]', 'lemma', 'heb', 'לָקַח', '["lâqach"]', '["I have received","I received","I will accept","I will take","[is] receiving","accept","does he receive","he accepted","he accepts","he receives","he will accept","it has accepted","it has received","she takes","take","take [it]","take [them]","they accepted","they had received","they have received","they have taken","they took","they took [them]","they will receive","they will take","to accept","will you accept","you may receive","you took","you will accept","you will receive","you will take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8255}/[H8254]', 'lemma', 'heb', 'שֶׁקֶל', '["sheqel"]', '["a shekel","a shekel of","shekel[s]","shekel[s] of","shekels","shekels of"]', '["n-m"]', 'probably a weight; used as a commercial standard shekel.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8254}/[H8254]', 'inflected', 'heb', 'שָׁקַל', '["shâqal"]', '["and/ I weighed out","and/ has he weighed?","and/ he weighed","and/ he weighed out","and/ they weighed out"]', '["v"]', 'to suspend or poise (especially in trade) pay, receive(-r), spend, × throughly, weigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6085G}/[H6081]', 'inflected', 'heb', 'עֶפְרוֹן', '["ʻEphrôwn"]', '["for/ Ephron"]', '["n-pr-m n-pr-loc"]', 'Ephron, the name of a Canaanite and of two places in Palestine Ephron, Ephrain (from the margin).', 'from the same as 6081; fawn-like;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3701G}/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["<the>/ money","<the>/ silver","the/ money","the/ silver"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5503}/[H5503]', 'inflected', 'heb', 'סָחַר', '["çâchar"]', '["to the/ trader"]', '["v"]', 'to travel round (specifically as a pedlar); intensively, to palpitate go about, merchant(-man), occupy with, pant, trade, traffick.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4375}/[H3717]', 'inflected', 'heb', 'מַכְפֵּלָה', '["Makpêlâh"]', '["[was] in <the>/ Machpelah"]', '["n-pr-loc"]', 'Makpelah, a place in Palestine Machpelah.', 'from 3717; a fold;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440K}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["[was] <to>/ before"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366H}/H9023/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["border/ its","own territory/ its","territory/ its"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439I}/[H5437]', 'lemma', 'heb', 'סָבִיב', '["çâbîyb"]', '["all around","round about"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4736}/[H4735]', 'inflected', 'heb', 'מִקְנָה', '["miqnâh"]', '["to/ a possession"]', '["n-f"]', 'properly, a buying, i.e. acquisition; concretely, a piece of property (land or living); also the sum paid (he that is) bought, possession, piece, purchase.', 'feminine of 4735;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869J}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ [the] eyes of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440K}/[H6437]', 'lemma', 'heb', 'פָּנִים', '["pânîym"]', '["[the] face of"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2845}\/[H2865]', 'inflected', 'heb', 'חֵת', '["Chêth"]', '["Heth"]', '["n-pr-m"]', 'Cheth, an aboriginal Canaanite Heth.', 'from 2865; terror;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4910}/[H4910]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["the/ ruler","the/ rulers","who/ was ruling"]', '["v"]', 'to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027X}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478L}/[H8430]', 'lemma', 'heb', 'תַּחַת', '["tachath"]', '["under"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3409>/H9020', 'opaque', 'heb', 'יָרֵךְ', '["yârêk"]', '["thigh/ my"]', '["n-f"]', 'the thigh (from its fleshy softness); by euphemistically the generative parts; figuratively, a shank, flank, side × body, loins, shaft, side, thigh.', 'from an unused root meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7650}/H9031/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["so/ I may make swear/ you"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0430G}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ God","and/ [the] God of"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121A}/H9020/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["<to>/ son/ my","for/ son/ my","to/ son/ my"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1323G}/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["any of/ [the] daughters of","from/ [the] daughter of","from/ [the] daughters of","one of/ [the] daughters of"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130G}/H9023/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["<in>/ within/ it","[am] in/ midst/ its","[are] in/ midst/ its","[is] <in>/ within/ him","[is] <in>/ within/ it","[was] <in>/ within/ him","[was] in/ midst/ its","in/ inward part[s]/ his","in/ midst/ his","in/ midst/ its"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4138}/H9020/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["kindred/ my"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3327}/[H6711]', 'inflected', 'heb', 'יִצְחָק', '["Yitschâq"]', '["<to>/ Isaac","for/ Isaac","to/ Isaac"]', '["n-pr-m"]', 'Jitschak (or Isaac), son of Abraham Isaac. Compare 3446.', 'from 6711; laughter (i.e. mochery);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5650}/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["the/ [male] slaves","the/ servant","the/ slave"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0014}/[H14]', 'lemma', 'heb', 'אָבָה', '["ʼâbâh"]', '["I was willing","[are] willing","he was willing","he will be willing","it was willing","it yielded","she will be willing","they have been willing","they were willing","they will be willing","they yielded","you be willing","you must be willing","you were willing","you will be willing","you will yield","you yielded to"]', '["v"]', 'to breathe after, i.e. (figuratively) to be acquiescent consent, rest content will, be willing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1980N}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["by/ walking","to/ go","to/ walk"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310A}/H9030/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["[were] behind/ me","after/ me","behind/ me"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7725G}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["¿/ really <to take back>","¿/ will he return"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104J}/[H8104]', 'lemma', 'heb', 'שָׁמַר', '["shâmar"]', '["[one who] keeps","certainly <to keep>","he has kept","he took care","keep","she will take care","take care","take heed","they kept","they will guard","they will keep","they will take care","we will take care","will I take care","you may take care","you will keep","you will take care","you will take heed"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947G}/H9030/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["he took hold of/ me","he took/ me","you take away/ me"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004M}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ [the] house of","from/ [the] household of","from/ a house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H0776G>', 'inflected', 'heb', 'ומארצות', '["u./me./''E.retz","u./me./''a.ra.Tzot"]', '["and/ from/ [the] land of","and/ from/ [the] lands"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4397H>/H9023', 'opaque', 'heb', 'מַלְאָךְ', '["malʼâk"]', '["O angels/ his","angel/ his","angels/ his"]', '["n-m"]', 'a messenger; specifically, of God, i.e. an angel (also a prophet, priest or teacher) ambassador, angel, king, messenger.', 'from an unused root meaning to despatch as a deputy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5352}/[H5352]', 'inflected', 'heb', 'נָקָה', '["nâqâh"]', '["and/ I will be acquitted","and/ he will be free","and/ he will be free from guilt","and/ it will be emptied","and/ she will be free","and/ you will be free"]', '["v"]', 'to be (or make) clean (literally or figuratively); by implication (in an adverse sense) to be bare, i.e. extirpated acquit × at all, × altogether, be blameless, cleanse, (be) clear(-ing), cut off, be desolate, be free, be (hold) guiltless, be (hold) innocent, × by no means, be quit, be (leave) unpunished, × utterly, × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7621}/H9020/[H7650]', 'inflected', 'heb', 'שְׁבוּעָה', '["shᵉbûwʻâh"]', '["from/ oath/ my"]', '["n-f"]', 'properly, something sworn, i.e. an oath curse, oath, × sworn.', 'feminine passive participle of 7650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027X}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3409>', 'opaque', 'heb', 'יָרֵךְ', '["yârêk"]', '["[the] side of","[the] thigh of","[the] thighs","a thigh","thigh"]', '["n-f"]', 'the thigh (from its fleshy softness); by euphemistically the generative parts; figuratively, a shank, flank, side × body, loins, shaft, side, thigh.', 'from an unused root meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0113>/H9023', 'opaque', 'heb', 'אָדוֹן', '["ʼâdôwn"]', '["lord<s>/ his","master<s>/ his","masters/ his"]', '["n-m"]', 'sovereign, i.e. controller (human or divine) lord, master, owner. Compare also names beginning with ''Adoni-''.', 'or (shortened) אָדֹן; from an unused root (meaning to rule);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7650}/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["and/ I swore","and/ I swore an oath","and/ he administered an oath","and/ he made swear","and/ he made to swear an oath","and/ he swore","and/ he swore an oath","and/ he will make swear","and/ he will swear an oath","and/ they have sworn","and/ they swore [the] oath","and/ they swore an oath","and/ you will swear"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1581}/[H1580]', 'lemma', 'heb', 'גָּמָל', '["gâmâl"]', '["a camel","camel[s]","camels"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1581}/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["from/ [the] camels of","from/ a camel"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2898}/[H2895]', 'lemma', 'heb', 'טוּב', '["ṭûwb"]', '["<the> good thing of","[the] good thing[s] of","[the] goodness of","good thing","goodness","goodness of"]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027K}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[was] in/ hand/ his","in/ hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0763G}/[H758]', 'lemma', 'heb', 'אֲרַם נַהֲרַיִם', '["ʼĂram Nahărayim"]', '["Aram","Naharaim"]', '["n-pr-loc"]', 'Aram of (the) two rivers (Euphrates and Tigris) or Mesopotamia Aram-naharaim, Mesopotamia.', 'from 758 and the dual of 5104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1581}/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["<the>/ camels","the/ camel","the/ camels"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7579}/[H7579]', 'inflected', 'heb', 'שָׁאַב', '["shâʼab"]', '["the/ [women who] draw water"]', '["v"]', 'to bale up water (woman to) draw(-er, water).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7136A}/[H7136]', 'lemma', 'heb', 'קָרָה', '["qârâh"]', '["I found myself","I will meet","he has met","he made happen","he will meet","it happens to","it will happen","it will happen to","make happen","they will happen"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440L}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ me"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2617A}/[H2616]', 'lemma', 'heb', 'חֶסֶד', '["cheçed"]', '["[are] covenant loyalty","[is] covenant loyalty","[the] covenant loyalti<es> of","[the] covenant loyalty of","covenant loyalty","favor","loyalty","of covenant loyalty"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7579}/[H7579]', 'inflected', 'heb', 'שָׁאַב', '["shâʼab"]', '["to/ draw","to/ draw water"]', '["v"]', 'to bale up water (woman to) draw(-er, water).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5291}/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["the/ girl","the/ servant girls","the/ young woman"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5186}/[H5186]', 'lemma', 'heb', 'נָטָה', '["nâṭâh"]', '["I have stretched out","I have turned","I have turned aside","I inclined","I offered","I stretched out","I will incline","I will stretch out","[am] about to extend","[am] about to stretch out","[am] holding out","[he] stretches out","[is one who] pitches","[is] stretched out","[one who] stretches out","[one who] turns aside","[was] stretched out","[which] they are stretched out","[who] he has turned aside","[who] stretched out","[you are] stretching out","bend down","bent down","declines","did he stretch out","extended","he had pitched","he had stretched out","he had turned aside","he has extended","he has inclined","he has stretched out","he stretched out","he stretches out","he turned aside","he will stretch out","incline","it extends","it had turned aside","it turned aside","it will be stretched out","it will stretch out","may people stretch out","outstretched","spread out","stretch out","stretched out","they are stretched out","they had turned aside","they have extended","they have turned aside","they inclined","they stretch out","they stretched out","they thrust aside","they turn aside","they turned aside","they will turn aside","turn aside","we will turn aside","you inclined","you must turn aside","you stretched out","you turn","you turn aside","you will incline","you will turn aside"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3537>/H9022', 'opaque', 'heb', 'כַּד', '["kad"]', '["jar/ your"]', '["n-f"]', 'properly, a pail; but generally of earthenware; a jar for domestic purposes barrel, pitcher.', 'from an unused root meaning to deepen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8354}/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["and/ I have drunk","and/ [were] drinking","and/ did he drink?","and/ drink","and/ drinking","and/ they are drinking","and/ they may drink","and/ to drink","and/ we will drink","so/ I may drink","so/ he may drink","so/ we may drink"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8354}/[H8354]', 'lemma', 'heb', 'שָׁתָה', '["shâthâh"]', '["I drank","I have drunk","I will drink","[he is] drinking","[is] drinking","[one who] drinks","[was] drinking","[which] you are drinking","[who] drinks","certainly <drink>","certainly <to drink>","completely <to drink>","do I drink?","drink","drinkers of","drinking","had drunk","he drank","he drinks","he had drunk","he should drink","he will drink","it drank","it drinks","it is drunk","it will drink","let him drink","people will drink","she drink","they drank","they drink","they have drunk","they will drink","they will drink [it]","to drink","we drink","we have drunk","we will drink","will I drink","will we drink","you drank","you drink","you have drunk","you must drink","you will drink","you will drink [it]"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1581}/H9021/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["camels/ your"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8248G}/[H8248]', 'lemma', 'heb', 'שָׁקָה', '["shâqâh"]', '["I will give a drink to","[he is] watering","it is watered","people watered","she gave a drink","they give drink to","water"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3198}/[H3198]', 'lemma', 'heb', 'יָכַח', '["yâkach"]', '["I will argue","[is] an arbiter","[one who] corrects","[one who] reproves","[was one who] rebuked","[who] reproves","[will be] reasoning","certainly <to rebuke>","completely <to prove>","does he argue?","does he rebuke","does it prove","he has appointed","he reprove","he reproves","he should rebuke","he will argue","he will decide","he will rebuke","reproof","reprove","you have appointed","you reprove","you will rebuke"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5650}/H9021/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["<to>/ servant/ your","<to>/ servants/ your","[belong] to/ servant/ your","[belongs] to/ servant/ your","[belongs] to/ servants/ your","for/ servant/ your","to/ servant/ your","to/ servants/ your"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H9034}', 'inflected', 'heb', 'ובה', '["u./Va/h"]', '["and/ [was] in/ it","and/ by <the>/ it","and/ in/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1328A}/[H1326]', 'inflected', 'heb', 'בְּתוּאֵל', '["Bᵉthûwʼêl"]', '["to/ Bethuel"]', '["n-pr-m n-pr-loc"]', 'Bethuel, the name of a nephew of Abraham, and of a place in Palestine Bethuel. Compare 1329.', 'apparently from the same as 1326 and 410; destroyed of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3537>/H9024', 'inflected', 'heb', 'וכדה', '["ve./kha.Da/h"]', '["and/ jar/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5291}/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["and/ the/ young woman"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1330>', 'opaque', 'heb', 'בְּתוּלָה', '["bᵉthûwlâh"]', '["O virgin of","[the] virgin of","[the] virgins of","[was] a virgin","a virgin","a young woman","virgin","virgin[s]","virgins","young woman","young women"]', '["n-f"]', 'a virgin (from her privacy); sometimes (by continuation) a bride; also (figuratively) a city or state maid, virgin.', 'feminine passive participle of an unused root meaning to separate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9034/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["I know/ it","do you know/ it","he had known/ her","he knew/ her"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5869M}/H9011/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["the/ spring/ towards"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3537>/H9024', 'opaque', 'heb', 'כַּד', '["kad"]', '["jar/ her"]', '["n-f"]', 'properly, a pail; but generally of earthenware; a jar for domestic purposes barrel, pitcher.', 'from an unused root meaning to deepen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122G}/H9034/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ her"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1572}/H9030/[H1572]', 'inflected', 'heb', 'גָּמָא', '["gâmâʼ"]', '["give to drink/ me"]', '["v"]', 'to absorb swallow, drink.', 'a primitive root (literally or figuratively) to absorb');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3537>/H9022', 'inflected', 'heb', 'מכדך', '["mi./ka.De/kh"]', '["from/ jar/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}/H9024/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ her","hands/ her","hands/ its"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8248H}/H9033/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["and/ she gave a drink/ him","and/ they gave to drink/ him"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8248H}/H9033/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["to/ give a drink/ him"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1581}/H9021/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["for/ camels/ your"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7579}/[H7579]', 'lemma', 'heb', 'שָׁאַב', '["shâʼab"]', '["I will draw water","[the] drawer of"]', '["v"]', 'to bale up water (woman to) draw(-er, water).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0518J}/[H518]', 'lemma', 'heb', 'אִם', '["ʼim"]', '["<if>","if","or?"]', '["prt"]', 'used very widely as demonstrative, lo!; interrogative, whether?; or conditional, if, although; also Oh that!, when; hence, as a negative, not (and, can-, doubtless, if, that) (not), + but, either, + except, + more(-over if, than), neither, nevertheless, nor, oh that, or, + save (only, -ing), seeing, since, sith, + surely (no more, none, not), though, + of a truth, + unless, + verily, when, whereas, whether, while, + yet.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8354}/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["[is] to/ drink","[was] to/ drink","for/ drinking","to/ drink"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6168}/[H6168]', 'inflected', 'heb', 'עָרָה', '["ʻârâh"]', '["and/ she emptied"]', '["v"]', 'to be (causatively, make) bare; hence, to empty, pour out, demolish leave destitute, discover, empty, make naked, pour (out), rase, spread self, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8268}/[H8248]', 'inflected', 'heb', 'שֹׁקֶת', '["shôqeth"]', '["the/ watering channel"]', '["n-f"]', 'a trough (for watering) trough.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7579}/[H7579]', 'inflected', 'heb', 'שָׁאַב', '["shâʼab"]', '["and/ she drew water","and/ they drew","and/ you will draw"]', '["v"]', 'to bale up water (woman to) draw(-er, water).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1581}/H9023/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["camels/ his"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H0376G>', 'inflected', 'heb', 'והאיש', '["ve./ha./''Ish"]', '["and/ the/ man","and/ the/ person"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7583}/[H7583]', 'lemma', 'heb', 'שָׁאָה', '["shâʼâh"]', '["[was] gazing"]', '["v"]', 'to stun, i.e. (intransitively) be astonished wonder.', 'a primitive root (identical with through the idea of whirling to giddiness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2790B}/[H2790]', 'lemma', 'heb', 'חָרַשׁ', '["chârash"]', '["I have kept silent","I kept quiet","I kept silent","I will keep silent","[who] keeps silent","are you silent?","be silent","being silent","certainly <to be silent>","certainly <to keep quiet>","certainly [if] <to be silent>","he be silent","he keeps quiet","he kept silent","he will be silent","he will keep silent","keep quiet","keep silent","keeping silent","they will be deaf","will they silence?","you be deaf","you be silent","you keep silent","you will keep quiet"]', '["v"]', 'to scratch, i.e. (by implication) to engrave, plough; hence (from the use of tools) to fabricate (of any material); figuratively, to devise (in a bad sense); hence (from the idea of secrecy) to be silent, to let alone; hence (by implication) to be deaf (as an accompaniment of dumbness) × altogether, cease, conceal, be deaf, devise, ear, graven, imagine, leave off speaking, hold peace, plow(-er, man), be quiet, rest, practise secretly, keep silence, be silent, speak not a word, be still, hold tongue, worker.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6743B}/[H6743]', 'inflected', 'heb', 'צָלַח', '["tsâlach"]', '["¿/ had he made successful","¿/ is it successful","¿/ will he prosper","¿/ will it prosper","¿/ will it succeed"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870L}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["journey/ his","way/ his","ways/ his"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5141>', 'opaque', 'heb', 'נֶזֶם', '["nezem"]', '["<the> earring of","[the] earrings of","[the] rings of","a ring","a ring of","an earring of","earrings of"]', '["n-m"]', 'a nose-ring earring, jewel.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2091>', 'opaque', 'heb', 'זָהָב', '["zâhâb"]', '["[is] gold","[the] gold of","[was] [the] gold of","[was] gold","[were] gold","[whom] gold","[will be] gold","gold"]', '["n-m"]', 'gold, figuratively, something gold-colored (i.e. yellow), as oil, a clear sky gold(-en), fair weather.', 'from an unused root meaning to shimmer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1235}/[H1234]', 'lemma', 'heb', 'בֶּקַע', '["beqaʻ"]', '["[was] a beka","a beka"]', '["n-m"]', 'a section (half) of a shekel, i.e. a beka (a weight and a coin) bekah, half a shekel.', 'from 1234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4948}/H9023/[H8254]', 'inflected', 'heb', 'מִשְׁקָל', '["mishqâl"]', '["weight/ its"]', '["n-m"]', 'weight (numerically estimated); hence, weighing (the act) (full) weight.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6781A}/[H6775]', 'lemma', 'heb', 'צָמִיד', '["tsâmîyd"]', '["bracelets"]', '["n-m"]', 'a bracelet or arm-clasp; generally, a lid bracelet, covering.', 'or צָמִד; from 6775;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027X}/H9024/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hands/ her"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4948}/H9028/[H8254]', 'inflected', 'heb', 'מִשְׁקָל', '["mishqâl"]', '["weight/ their"]', '["n-m"]', 'weight (numerically estimated); hence, weighing (the act) (full) weight.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/<H3426>', 'inflected', 'heb', 'היש', '["ha./Yesh","ha./yesh"]', '["¿/ [are] there","¿/ [does] there","¿/ [is] there"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9022/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["father/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3885A}/[H3885]', 'inflected', 'heb', 'לוּן', '["lûwn"]', '["to/ spend [the] night","to/ stay [the] night"]', '["v"]', 'to stop (usually over night); by implication, to stay permanently; hence (in a bad sense) to be obstinate (especially in words, to complain) abide (all night), continue, dwell, endure, grudge, be left, lie all night, (cause to) lodge (all night, in, -ing, this night), (make to) murmur, remain, tarry (all night, that night).', 'or לִין; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8401}/[H1129]', 'lemma', 'heb', 'תֶּבֶן', '["teben"]', '["straw"]', '["n-m"]', 'properly, material, i.e. (specifically) refuse haum or stalks of grain (as chopped in threshing and used for fodder) chaff, straw, stubble.', 'probably from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4554>', 'opaque', 'heb', 'מִסְפּוֹא', '["miçpôwʼ"]', '["fodder"]', '["n-m"]', 'fodder provender.', 'from an unused root meaning to collect;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/H9035/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[is] with/ us","which [is] with/ us","with/ us"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6915}/[H6915]', 'inflected', 'heb', 'קָדַד', '["qâdad"]', '["and/ I bowed low","and/ he bowed low","and/ it bowed low","and/ she bowed low","and/ they bowed low"]', '["v"]', 'to shrivel up, i.e. contract or bend the body (or neck) in deference bow (down) (the) head, stoop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2617A}/H9023/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["covenant loyalti<es>/ his","covenant loyalty of/ his","covenant loyalty/ his","loyalty/ his","loyalty/ its"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0571G}/H9023/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["and/ faithfulness/ his"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5973B}/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[is] from/ with","away from/ with","from/ with"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870L}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["[are] in the/ way","[were] on the/ way","by the/ way","in the/ road","in the/ way","in/ [the] way","in/ [the] way of","on the/ journey","on the/ road","on the/ way","on/ [the] journey of","on/ [the] way","on/ [the] way of","on/ a journey"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5148}/H9030/[H5148]', 'inflected', 'heb', 'נָחָה', '["nâchâh"]', '["has he led/ me","he guides/ me","he had led/ me","he has led/ me","he led/ me","it will lead/ me","lead/ me","may it lead/ me","may they lead/ me","will he lead/ me","you guide/ me","you will lead/ me"]', '["v"]', 'to guide; by implication, to transport (into exile, or as colonists) bestow, bring, govern, guide, lead (forth), put, straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0517}/H9024/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["mother/ her"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1697I}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["according to the/ things","according to the/ words","like the/ thing"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H7259>', 'inflected', 'heb', 'ולרבקה', '["u./le./riv.Kah"]', '["and/ [belonged] to/ Rebekah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8034}/H9023/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["and/ name/ his"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3837A}/[H3836]', 'lemma', 'heb', 'לָבָן', '["Lâbân"]', '["Laban","[was] Laban"]', '["n-pr-m n-pr-loc"]', 'Laban, a Mesopotamian; also a place in the Desert Laban.', 'the same as 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7200G}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["as/ sees","like/ seeing","when/ saw"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5141>', 'inflected', 'heb', 'הנזמים', '["ha./Ne.zem","ha./ne.za.Mim"]', '["the/ ring","the/ rings"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6781A}/[H6775]', 'inflected', 'heb', 'צָמִיד', '["tsâmîyd"]', '["the/ bracelets"]', '["n-m"]', 'a bracelet or arm-clasp; generally, a lid bracelet, covering.', 'or צָמִד; from 6775;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["[are] [the] hands of","[the] hand of","[the] hands of","a hand","hand","hand of","hands","pair of hands"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0269}/H9023/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["sister/ his","sisters/ his"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H8085G}/H9043/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ just as/ heard/ he"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6437G}/[H6437]', 'lemma', 'heb', 'פָּנָה', '["pânâh"]', '["I have made clear","[are] turning","[is] faced","[is] turning away","[it is] turning","[was] facing","[were] turning","anyone turns","be turned back","has he turned","he has cleared away","he has turned","he turned","he turns","it has turned","it turned","it will turn","it will turn away","it will turn back","make clear","they have turned","they have turned back","they turn","they will turn","they will turn back","to face","turn","turning","we have turned","will you turn","you have turned","you made clear","you turn","you turned to look","you will turn"]', '["v"]', 'to turn; by implication, to face, i.e. appear, look, etc. appear, at (even-) tide, behold, cast out, come on, × corner, dawning, empty, go away, lie, look, mark, pass away, prepare, regard, (have) respect (to), (re-) turn (aside, away, back, face, self), × right (early).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4725}/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["and/ [the] place of","and/ a place"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1581}/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["for the/ camels","to the/ camels"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4554>', 'inflected', 'heb', 'ומספוא', '["u./mis.pO''"]', '["and/ fodder"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7364}/[H7364]', 'inflected', 'heb', 'רָחַץ', '["râchats"]', '["for/ washing","to/ bathe","to/ wash"]', '["v"]', 'to lave (the whole or a part of a thing) bathe (self), wash (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7272}/H9023/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["feet/ his","feet/ its","foot/ his"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7272}/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["and/ [the] feet of","and/ [the] foot of","and/ [was] feet","and/ a foot"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440G}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ him","<to>/ before/ it","[are] <to>/ before/ him","[is] <to>/ before/ him","[was] <to>/ before/ him","[were] <to>/ before/ him"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0398}/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["[are] to/ eat","[is] to/ eat","by/ eating","for/ devouring","for/ eating","to the/ eater","to/ consume","to/ devour","to/ eat","to/ eat [it]"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697H}/H9020/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["word/ my","words/ my"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3701G}/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["and/ [the] silver","and/ [the] silver of","and/ money of","and/ silver","and/ silver of"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0113>/H9020', 'inflected', 'heb', 'לאדני', '["La./do.N/i","la./do.N/i"]', '["[belong] to/ lord/ my","for/ lord/ my","of/ lord/ my","to/ lord/ my","to/ master/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2209}/H9024/[H2205]', 'inflected', 'heb', 'זִקְנָה', '["ziqnâh"]', '["old age/ her"]', '["n-f"]', 'old age old (age).', 'feminine of 2205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7650}/H9030/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["and/ he made swear an oath/ me"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0776G>/H9023', 'inflected', 'heb', 'בארצו', '["be./''ar.Tz/o","ve./''ar.Tz/o"]', '["in/ land/ his","in/ land/ its","in/ own land/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0518I}/[H518]', 'lemma', 'heb', 'אִם', '["ʼim"]', '["<if>","<if>?","if","or","or?","though","whether"]', '["prt"]', 'used very widely as demonstrative, lo!; interrogative, whether?; or conditional, if, although; also Oh that!, when; hence, as a negative, not (and, can-, doubtless, if, that) (not), + but, either, + except, + more(-over if, than), neither, nevertheless, nor, oh that, or, + save (only, -ing), seeing, since, sith, + surely (no more, none, not), though, + of a truth, + unless, + verily, when, whereas, whether, while, + yet.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4940}/H9020/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["family/ my"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980N}/[H3212]', 'lemma', 'heb', 'הָלַךְ', '["hâlak"]', '["I have walked","[are] walking","[he is] walking","[one who] walks","[was] going","[was] walking","[were] going","come","go","going","going about","he walked","it will go","let us go","let us walk","she will go","they had gone","they have walked","they moved","they walked","they will walk","to go","to walk","walk","we will walk","you must walk","you walk"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6743B}/[H6743]', 'inflected', 'heb', 'צָלַח', '["tsâlach"]', '["and/ he prospered","and/ he was successful","and/ he will make successful","and/ he will succeed","and/ it has prospered","and/ it will succeed","and/ you prospered","and/ you will be successful"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870L}/H9021/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["journey/ your","way/ your","ways/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4940}/H9020/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["from/ family/ my"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5352}/[H5352]', 'lemma', 'heb', 'נָקָה', '["nâqâh"]', '["I am innocent","I will be free","be free","certainly <to exempt from punishment>","completely <exempt from punishment>","he leaves unpunished","he will be purged","he will go unpunished","he will leave unpunished","will you be exempt from punishment?","you will be exempt from punishment","you will be free"]', '["v"]', 'to be (or make) clean (literally or figuratively); by implication (in an adverse sense) to be bare, i.e. extirpated acquit × at all, × altogether, be blameless, cleanse, (be) clear(-ing), cut off, be desolate, be free, be (hold) guiltless, be (hold) innocent, × by no means, be quit, be (leave) unpunished, × utterly, × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0423}/H9020/[H422]', 'inflected', 'heb', 'אָלָה', '["ʼâlâh"]', '["from/ oath/ my"]', '["n-f"]', 'an imprecation curse, cursing, execration, oath, swearing.', 'from 422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5355A}/[H5352]', 'lemma', 'heb', 'נָקִי', '["nâqîy"]', '["[am] innocent","[the] innocent","[was] an exempt [person]","[will be] free","[will be] free from guilt","a [person] innocent of","an innocent [person]","free","innocent","innocent [ones]"]', '["a"]', 'innocent blameless, clean, clear, exempted, free, guiltless, innocent, quit.', 'or נָקִיא; (Joel 4:19; Jonah 1:14), from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3426>/H9041', 'opaque', 'heb', 'יֵשׁ', '["yêsh"]', '["[are] there/ you","there/ you"]', '["prt"]', 'there is or are (or any other form of the verb to be, as may suit the connection) (there) are, (he, it, shall, there, there may, there shall, there should) be, thou do, had, hast, (which) hath, (I, shalt, that) have, (he, it, there) is, substance, it (there) was, (there) were, ye will, thou wilt, wouldest.', 'perhaps from an unused root meaning to stand out, or exist; entity; used adverbially or as a copula for the substantive verb (1961);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6743B}/[H6743]', 'lemma', 'heb', 'צָלַח', '["tsâlach"]', '["[are] making successful","[was] making successful","does it prosper","he has made successful","he will grant success","he will prosper","it is profitable","it succeeds","it was profitable","it will prosper","it will succeed","prosper","successful","will it prosper?","you will be successful","you will make successful","you will prosper","you will succeed"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870L}/H9020/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["journey/ my","ways/ my"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9034/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["<on>/ it","[are] on/ her","[are] on/ it","[is] on/ her","[is] on/ it","[was] on/ her","[was] on/ it","[were] at/ it","at/ it","on/ her","on/ it","on/ itself","over/ her","over/ it","to/ her","to/ it","with/ her"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5959}/[H5958]', 'inflected', 'heb', 'עַלְמָה', '["ʻalmâh"]', '["the/ young woman"]', '["n-f"]', 'a lass (as veiled or private) damsel, maid, virgin.', 'feminine of 5958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8248H}/H9030/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["give a drink/ me","give to drink/ me","they gave to drink/ me","will he give to drink/ me"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121A}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["<into>/ a son","<to>/ [the] children of","<to>/ [the] son of","<to>/ [the] sons of","[belonged] to/ [the] descendants of","[is] to/ [the] children of","by/ [the] children of","for/ [the] children of","for/ [the] son of","for/ [the] sons of","for/ a son","of/ [the] descendants of","of/ [the] sons of","to/ [the] children of","to/ [the] descendants of","to/ [the] son of","to/ [the] sons of","to/ a son","to/ children"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9020/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart/ my"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5921A}/H9034/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["from/ <the> with/ her","from/ on <the>/ her","from/ on <the>/ it","from/ with <the>/ her"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7592}/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["and/ I asked","and/ he asked","and/ he asks","and/ he enquired","and/ he sought","and/ he will enquire","and/ she will ask","and/ they asked","and/ they enquired","and/ they will ask","and/ they will beg","and/ you asked","and/ you have asked for","and/ you will ask","and/ you will enquire"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639H}/H9024/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["nose/ her"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6781A}/[H6775]', 'inflected', 'heb', 'צָמִיד', '["tsâmîyd"]', '["and/ the/ bracelets"]', '["n-m"]', 'a bracelet or arm-clasp; generally, a lid bracelet, covering.', 'or צָמִד; from 6775;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0571H}/[H539]', 'lemma', 'heb', 'אֶמֶת', '["ʼemeth"]', '["[is] truth","[was] truth","faithfulness","reliability","truth"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3947G}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["to/ fetch","to/ seize","to/ take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121A}/H9023/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["<to>/ son/ his","[belongs] to/ sons/ his","for/ children/ his","for/ son/ his","for/ sons/ his","to/ son/ his","to/ sons/ his"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3426>/H9046', 'opaque', 'heb', 'יֵשׁ', '["yêsh"]', '["[are] there/ you"]', '["prt"]', 'there is or are (or any other form of the verb to be, as may suit the connection) (there) are, (he, it, shall, there, there may, there shall, there should) be, thou do, had, hast, (which) hath, (I, shalt, that) have, (he, it, there) is, substance, it (there) was, (there) were, ye will, thou wilt, wouldest.', 'perhaps from an unused root meaning to stand out, or exist; entity; used adverbially or as a copula for the substantive verb (1961);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0571G}/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["and/ [the] faithfulness of","and/ faithfulness","and/ truth"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6437G}/[H6437]', 'inflected', 'heb', 'פָּנָה', '["pânâh"]', '["so/ I may turn"]', '["v"]', 'to turn; by implication, to face, i.e. appear, look, etc. appear, at (even-) tide, behold, cast out, come on, × corner, dawning, empty, go away, lie, look, mark, pass away, prepare, regard, (have) respect (to), (re-) turn (aside, away, back, face, self), × right (early).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3225G}/[H3231]', 'lemma', 'heb', 'יָמִין', '["yâmîyn"]', '["[is] a right [hand] of","[the] right [hand] of","[the] right [side]","[the] right [side] of","[the] right of","right","right [hand]"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0176A}/[H185]', 'lemma', 'heb', 'אוֹ', '["ʼôw"]', '["or","or?"]', '["conj"]', 'desire (and so probably in Proverbs 31:4); hence (by way of alternative) or, also if also, and, either, if, at the least, × nor, or, otherwise, then, whether.', 'presumed to be the ''constructive'' or genitival form of אַו ; short for 185;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8040G}/[H8071]', 'lemma', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["[the] left [side]","[the] left [side] of","left"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451A}/[H7489]', 'lemma', 'heb', 'רַע', '["raʻ"]', '["[are] bad","[the] evil of","[was] evil","a bad thing","an evil","bad","calamities","evil","harmful","sad","wild"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0113>/H9021', 'opaque', 'heb', 'אָדוֹן', '["ʼâdôwn"]', '["master<s>/ your"]', '["n-m"]', 'sovereign, i.e. controller (human or divine) lord, master, owner. Compare also names beginning with ''Adoni-''.', 'or (shortened) אָדֹן; from an unused root (meaning to rule);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697G}/H9028/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["words/ their"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3627}/[H3615]', 'lemma', 'heb', 'כְּלִי', '["kᵉlîy"]', '["<the> article of","[are] weapons of","[is] a vessel","[the] armor<s> of","[the] articles of","[the] equipment of","[the] equipment<s> of","[the] garment[s] of","[the] instruments of","[the] things of","[the] utensils of","[the] vessel of","[the] vessels of","[the] weapon of","[the] weapons of","a vessel","a vessel of","a weapon","an article of","armor<s>","article","article of","articles","articles of","baggage<s> of","instruments of","of [the] weapons of","vessel","vessel of","vessels","weapon","weapons of"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3627}/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["and/ [are] an article of","and/ [the] articles of","and/ [the] equipment<s> of","and/ [the] instruments of","and/ [the] vessels of","and/ [the] weapons of","and/ a vessel of","and/ article of","and/ articles of","and/ equipment<s>","and/ utensils","and/ vessels","and/ vessels of"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0899B}/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["and/ [the] garments of","and/ clothes","and/ clothing","and/ garments"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7259>', 'inflected', 'heb', 'לרבקה', '["le./riv.Kah"]', '["<to>/ Rebekah","to/ Rebekah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4030}/[H4022]', 'inflected', 'heb', 'מִגְדָּנָה', '["migdânâh"]', '["and/ excellent things","and/ precious gifts"]', '["n-f"]', 'preciousness, i.e. a gem precious thing, present.', 'from the same as 4022;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251G}/H9024/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["to/ brother/ her"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0517}/H9024/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["and/ to/ mother/ her"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0582}/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["and/ the/ men"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3885A}/[H3885]', 'inflected', 'heb', 'לוּן', '["lûwn"]', '["and/ he passed [the] night","and/ he spent [the] night","and/ he stayed","and/ he stayed [the] night","and/ it will lodge","and/ they passed [the] night","and/ they spent [the] night","and/ they stayed","and/ they stayed [the] night","and/ we will spend [the] night"]', '["v"]', 'to stop (usually over night); by implication, to stay permanently; hence (in a bad sense) to be obstinate (especially in words, to complain) abide (all night), continue, dwell, endure, grudge, be left, lie all night, (cause to) lodge (all night, in, -ing, this night), (make to) murmur, remain, tarry (all night, that night).', 'or לִין; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971G}/H9030/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["[the] [one who] sent/ me","did you send/ me","has he sent/ me","he has sent/ me","he sent/ me","let go/ me","send away/ me","send off/ me","send/ me","you sent away/ me","you will send/ me"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251G}/H9024/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["brother/ her","brothers/ her"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0517}/H9024/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["and/ mother/ her"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9035/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["[are] with/ us","[is] with/ us","with <the>/ us","with/ us"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6218}/[H6235]', 'lemma', 'heb', 'עָשׂוֹר', '["ʻâsôwr"]', '["a ten","ten"]', '["n-m"]', 'ten; by abbreviated form ten strings, and so a decachord (instrument of) ten (strings, -th).', 'or עָשֹׂר; from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0309}/[H309]', 'lemma', 'heb', 'אָחַר', '["ʼâchar"]', '["[those who] delay","[who] delay","have they delayed","he delayed","he delays","it will delay","you delay","you must delay","you will delay"]', '["v"]', 'to loiter (i.e. be behind); by implication to procrastinate continue, defer, delay, hinder, be late (slack), stay (there), tarry (longer).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121G}/[H7122]', 'lemma', 'heb', 'קָרָא', '["qârâʼ"]', '["I call","I call out","I call out to","I called","I called out","I called out to","I have been summoned","I have called","I have called [you]","I have invited","I have summoned","I summoned","I will call","I will call out","[am] calling","[am] invited","[am] summoning","[is one who] calls","[is] calling","[one who] called","[one who] calls","[someone is] calling","[the] calling of","[they were] calling out","[those who] were invited","[was] calling","[was] summoning","[were those] called","[when] I called out","[when] I will call out","[who] you have called out","call","calling forth","did I call?","did you invite","have you called","he called","he calls","he has called","he has invited","he has proclaimed","he has summoned","he invited","he is summoned","he summoned","he summons","he will call","he will call out","he will summon","invite","it calls","it calls out","it is called","it is summoned","it will be called","it will call","let us summon","named","people called","people will call","people will call out","proclaim","summon","they call","they call on","they called","they have called","they summoned","they will call","they will summon","to call","to call out","to summon","we will call","will he call on?","you called out","you have called on","you have summoned","you summoned","you will call","you will invite"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5291}/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["<to> the/ young woman","[belongs] to the/ young woman","for the/ young woman"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7592}/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["and/ [one who] consults","and/ [you] enquired","and/ ask","and/ let us ask","so/ they may ask"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1980G}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["¿/ will I go","¿/ will we go","¿/ will you go"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0269}/H9028/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["[was] sister/ their","sister/ their","sisters/ their"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3243I}/H9024/[H3243]', 'inflected', 'heb', 'יָנַק', '["yânaq"]', '["suckling-nurse/ her"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0582}/H9023/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["men/ his"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0269}/H9025/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["O sister/ our","sister/ our"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0505G}/[H504]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["<into>/ thousands of","[were] of/ [the] thousands of","for/ a thousand","to <the>/ thousands","to the/ thousand","to/ a thousand","to/ thousands"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7233}/[H7231]', 'lemma', 'heb', 'רְבָבָה', '["rᵉbâbâh"]', '["[are] [the] ten thousands of","[the] ten thousands of","ten thousand","ten thousands"]', '["n-f"]', 'abundance (in number), i.e. (specifically) a myriad (whether definite or indefinite) many, million, × multiply, ten thousand.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8130}/H9033/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["I hate/ him","[those who] hate/ him","[those who] hate/ it","they hate/ him"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5291}/H9024/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["and/ female attendants/ her","and/ maids/ her"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7392}/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["and/ he made ride","and/ he rode","and/ he rode in a chariot","and/ she rode","and/ they caused to ride","and/ they have caused to ride","and/ they made ride","and/ they made to ride","and/ they mounted","and/ they rode","and/ you will cause to ride"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1980N}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ he walked","and/ he went","and/ she went","and/ they had gone","and/ they have walked","and/ they walked","and/ they went","and/ you have walked","and/ you will go","and/ you will walk"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3327}/[H6711]', 'inflected', 'heb', 'יִצְחָק', '["Yitschâq"]', '["and/ Isaac"]', '["n-pr-m"]', 'Jitschak (or Isaac), son of Abraham Isaac. Compare 3446.', 'from 6711; laughter (i.e. mochery);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["from/ coming","from/ entering","from/ going"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7742}/[H7742]', 'inflected', 'heb', 'שׂוּחַ', '["sûwach"]', '["to/ meditate"]', '["v"]', 'to muse pensively meditate.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6437G}/[H6437]', 'inflected', 'heb', 'פָּנָה', '["pânâh"]', '["to/ [the] turning of","to/ turn"]', '["v"]', 'to turn; by implication, to face, i.e. appear, look, etc. appear, at (even-) tide, behold, cast out, come on, × corner, dawning, empty, go away, lie, look, mark, pass away, prepare, regard, (have) respect (to), (re-) turn (aside, away, back, face, self), × right (early).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1976}/[H1973]', 'lemma', 'heb', 'הַלָּזֶה', '["hallâzeh"]', '["this"]', '["d"]', 'this very this.', 'from the article (see 1973) and 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122G}/H9035/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ us"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6809>', 'inflected', 'heb', 'הצעיף', '["ha./tza.''If"]', '["the/ veil"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5608A}/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["and/ he counted","and/ he recounted","and/ he recounted [it]","and/ he will count","and/ she recounted","and/ she will count","and/ they recounted","and/ they were counted","and/ we recounted","and/ you will count"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0157G}/H9034/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ he loved/ her"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5162G}/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["and/ I have comforted myself","and/ I will gain relief","and/ he comforted","and/ he was comforted","and/ he will be comforted","and/ he will comfort","and/ they comforted","and/ they had compassion","and/ they were comforted","and/ they will comfort","and/ you will be comforted"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0517}/H9023\/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["mother/ his","mother/ its"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3254H}/[H3254]', 'inflected', 'heb', 'יָסַף', '["yâçaph"]', '["and/ I increased","and/ I will add","and/ he increased","and/ he repeated","and/ he will add","and/ it will be added","and/ they increased","and/ you will add"]', '["v"]', 'to add or augment (often adverbial, to continue to do a thing) add, × again, × any more, × cease, × come more, conceive again, continue, exceed, × further, × gather together, get more, give more-over, × henceforth, increase (more and more), join, × longer (bring, do, make, much, put), × (the, much, yet) more (and more), proceed (further), prolong, put, be (strong-) er, × yet, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6989}/[H6999]', 'lemma', 'heb', 'קְטוּרָה', '["Qᵉṭûwrâh"]', '["Keturah","[was] Keturah"]', '["n-pr-f"]', 'Keturah, a wife of Abraham Keturah.', 'feminine passive participle of 6999; perfumed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2175}/[H2167]', 'lemma', 'heb', 'זִמְרָן', '["Zimrân"]', '["Zimran"]', '["n-pr-m"]', 'Zimran, a son of Abraham by Keturah Zimran.', 'from 2167; musical;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3370}/[H3369]', 'lemma', 'heb', 'יׇקְשָׁן', '["Yoqshân"]', '["Jokshan"]', '["n-pr-m"]', 'Jokshan, an Arabian patriarch Jokshan.', 'from 3369; insidious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4091}/[H4090]', 'lemma', 'heb', 'מְדָן', '["Mᵉdân"]', '["Medan"]', '["n-pr-m"]', 'Medan, a son of Abraham Medan.', 'the same as 4090;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4080G}/[H4079]', 'lemma', 'heb', 'מִדְיָן', '["Midyân"]', '["Midian"]', '["n-pr-m n-pr-loc"]', 'Midjan, a son of Abraham; also his country and (collectively) his descendants Midian, Midianite.', 'the same as 4079;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3435>', 'opaque', 'heb', 'יִשְׁבָּק', '["Yishbâq"]', '["Ishbak"]', '["n-pr-m"]', 'Jishbak, a son of Abraham Ishbak.', 'from an unused root corresponding to 7662; he will leave;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7744}/[H7743]', 'lemma', 'heb', 'שׁוּחַ', '["Shûwach"]', '["Shuah"]', '["n-pr-m"]', 'Shuach, a son of Abraham Shuah.', 'from 7743; dell;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3370}/[H3369]', 'inflected', 'heb', 'יׇקְשָׁן', '["Yoqshân"]', '["and/ Jokshan"]', '["n-pr-m"]', 'Jokshan, an Arabian patriarch Jokshan.', 'from 3369; insidious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7614I>', 'opaque', 'heb', 'שְׁבָא', '["Shᵉbâʼ"]', '["Sheba"]', '["n-pr-m n-pr-loc"]', 'Sheba, the name of three early progenitors of tribes and of an Ethiopian district Sheba, Sabeans.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1719C>', 'opaque', 'heb', 'דְּדָן', '["Dᵉdân"]', '["Dedan"]', '["n-pr-m n-pr-loc"]', 'Dedan, the name of two Cushites and of their territory Dedan.', 'or (prolonged) דְּדָנֶה; (Ezekiel 25:13), of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121G}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ [are] [the] children of","and/ [the] descendants of","and/ [the] people of","and/ [the] sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0805A}/[H804]', 'lemma', 'heb', 'אֲשׁוּרִי', '["ʼĂshûwrîy"]', '["Asshurites"]', '["n-pr-m a"]', 'an Ashurite (collectively) or inhabitant of Ashur, a district in Palestine Asshurim, Ashurites.', 'or אַשּׁוּרִי; from a patrial word of the same form as 804;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3912}/[H3913]', 'inflected', 'heb', 'לְטוּשִׁם', '["Lᵉṭûwshim"]', '["and/ Letushites"]', '["n"]', 'Letushim, an Arabian tribe Letushim.', 'masculine plural of passive participle of 3913; hammered (i.e. oppressed) ones;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3817}/[H3816]', 'inflected', 'heb', 'לְאֻמִּים', '["Lᵉʼummîym"]', '["and/ Leummites"]', '["n-m"]', 'Leummim, an Arabian Leummim.', 'plural of 3816; communities;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5891G}/[H5890]', 'lemma', 'heb', 'עֵיפָה', '["ʻÊyphâh"]', '["Ephah","[were] Ephah"]', '["n-pr-m n-pr-f"]', 'Ephah, the name of a son of Midian, and of the region settled by him; also of an Israelite and of an Israelitess Ephah.', 'the same as 5890;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6081G}/[H6082]', 'inflected', 'heb', 'עֵפֶר', '["ʻÊpher"]', '["and/ Epher"]', '["n-pr-m"]', 'Epher, the name of an Arabian and of two Israelites Epher.', 'probably a variation of 6082; gazelle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2585I}/[H2596]', 'inflected', 'heb', 'חֲנוֹךְ', '["Chănôwk"]', '["and/ Hanoch"]', '["n-pr-m n-pr-loc"]', 'Chanok, an antediluvian patriach Enoch.', 'from 2596; initiated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0028}/[H1]', 'inflected', 'heb', 'אֲבִידָע', '["ʼĂbîydâʻ"]', '["and/ Abida"]', '["n-pr-m"]', 'Abida, a son of Abraham by Keturah Abida, Abidah.', 'from 1 and 3045; father of knowledge (i.e. knowing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0420}/[H410]', 'inflected', 'heb', 'אֶלְדָּעָה', '["ʼEldâʻâh"]', '["and/ Eldaah"]', '["n-pr-m"]', 'Eldaah, a son of Midian Eldaah.', 'from 410 and 3045; God of knowledge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1121A}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ [belonged] to/ [the] descendants of","and/ [is] for/ a child of","and/ for/ [the] sons of","and/ for/ a son","and/ of/ [the] descendants of","and/ to/ [the] children of","and/ to/ [the] descendants of","and/ to/ [the] sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6370>', 'inflected', 'heb', 'הפילגשים', '["ha./pi.lag.Shim"]', '["of the/ concubines","the/ concubines"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4979}/[H4976]', 'lemma', 'heb', 'מַתָּנָה', '["mattânâh"]', '["[the] gifts of","a bribe","a gift","gifts"]', '["n-f"]', 'a present; specifically (in a good sense), a sacrificial offering, (in a bad sense) a bribe gift.', 'feminine of 4976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971G}/H9038/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ he let down/ them","and/ he let go/ them","and/ he sent away/ them","and/ he sent off/ them","and/ he sent out/ them","and/ he sent/ them","and/ she sent off/ them","and/ they sent away/ them","and/ you will send/ them"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5750}/H9043/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["while/ still [was]/ he"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6924B}/H9011/[H6923]', 'inflected', 'heb', 'קֶדֶם', '["qedem"]', '["[were] east/ -ward","east/ -ward"]', '["n-m adv"]', 'the front, of place (absolutely, the fore part, relatively the East) or time (antiquity); often used adverbially (before, anciently, eastward) aforetime, ancient (time), before, east (end, part, side, -ward), eternal, × ever(-lasting), forward, old, past. Compare 6926.', 'or קֵדְמָה; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6924G}/[H6923]', 'lemma', 'heb', 'קֶדֶם', '["qedem"]', '["[the] east"]', '["n-m adv"]', 'the front, of place (absolutely, the fore part, relatively the East) or time (antiquity); often used adverbially (before, anciently, eastward) aforetime, ancient (time), before, east (end, part, side, -ward), eternal, × ever(-lasting), forward, old, past. Compare 6926.', 'or קֵדְמָה; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7649}/[H7646]', 'inflected', 'heb', 'שָׂבֵעַ', '["sâbêaʻ"]', '["and/ satisfied","and/ satisfied of","and/ surfeited of"]', '["a"]', 'satiated (in a pleasant or disagreeable sense) full (of), satisfied (with).', 'from 7646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971B}/H9023/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["kinspeople<s>/ his","people/ his","people<s>/ his","peoples/ his"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6912}/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["and/ he buried","and/ he was buried","and/ people buried","and/ people will bury","and/ she was buried","and/ someone buried","and/ they buried","and/ they buried [it]","and/ they buried [them]","and/ they will bury","and/ they will bury [them]","and/ you have buried","and/ you will bury"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4194}/[H4191]', 'lemma', 'heb', 'מָוֶת', '["mâveth"]', '["O death","[the] death of","[the] deaths of","death"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0883}\/[H875]', 'inflected', 'heb', 'בְּאֵר לַחַי רֹאִי', '["Bᵉʼêr la-Chay Rôʼîy"]', '["Roi"]', '["n-pr-loc"]', 'Beer-Lachai-Roi, a place in the Desert Beer-lahai-roi.', 'from 875 and 2416 (with prefix) and 7203; well of a living (One) my Seer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8034}/H9028/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["by/ name/ their","by/ names/ their","with/ names/ their"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1060}/[H1069]', 'lemma', 'heb', 'בְּכוֹר', '["bᵉkôwr"]', '["<the> firstborn of","[the] firstborn of","[the] firstborn<s> of","[was] [the] firstborn of","a firstborn","firstborn","firstborn of"]', '["n-m"]', 'first-born; hence, chief eldest (son), firstborn(-ling).', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5032}/[H5107]', 'lemma', 'heb', 'נְבָיוֹת', '["Nᵉbâyôwth"]', '["Nebaioth","[was] Nebaioth"]', '["n-pr-f"]', 'Nebajoth, a son of Ismael, and the country settled by him Nebaioth, Nebajoth.', 'or נְבָיֹת; feminine plural from 5107; fruitfulnesses;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6938}/[H6937]', 'inflected', 'heb', 'קֵדָר', '["Qêdâr"]', '["and/ Kedar"]', '["n-pr"]', 'Kedar, a son of Ishmael; also (collectively) Bedouin (as his descendants or representatives) Kedar.', 'from 6937; dusky (of the skin or the tent);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0110}/[H109]', 'inflected', 'heb', 'אַדְבְּאֵל', '["ʼAdbᵉʼêl"]', '["and/ Adbeel"]', '["n-pr-m"]', 'Adbeel, a son of Ishmael Adbeel.', 'probably from 109 (in the sense of chastisement) and 410; disciplined of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4017G}/[H1314]', 'inflected', 'heb', 'מִבְשָׂם', '["Mibsâm"]', '["and/ Mibsam"]', '["n-pr-m"]', 'Mibsam, the name of an Ishmaelite and of an Israelite Mibsam.', 'from the same as 1314; fragrant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4927G}/[H4926]', 'inflected', 'heb', 'מִשְׁמָע', '["Mishmâʻ"]', '["and/ Mishma"]', '["n-pr-m"]', 'Mishma, the name of a son of Ishmael, and of an Israelite Mishma.', 'the same as 4926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1746G}/[H1745]', 'inflected', 'heb', 'דּוּמָה', '["Dûwmâh"]', '["and/ Dumah"]', '["n-pr-m n-pr-loc"]', 'Dumah, a tribe and region of Arabia Dumah.', 'the same as 1745;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4854}/[H4853]', 'inflected', 'heb', 'מַשָּׂא', '["Massâʼ"]', '["and/ Massa"]', '["n-pr-m"]', 'Massa, a son of Ishmael Massa.', 'the same as 4853; burden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2301}/[H2300]', 'lemma', 'heb', 'חֲדַד', '["Chădad"]', '["Hadad"]', '["n-pr-m"]', 'Chadad, an Ishmaelite Hadad.', 'from 2300; fierce;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8485G}/[H8485]', 'inflected', 'heb', 'תֵּימָא', '["Têymâʼ"]', '["and/ Tema"]', '["n-pr-m n-pr-loc"]', 'Tema, a son of Ishmael, and the region settled by him Tema.', 'or תֵּמָא; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3195G}/[H2905]', 'lemma', 'heb', 'יְטוּר', '["Yᵉṭûwr"]', '["Jetur"]', '["n-pr-m"]', 'Jetur, a son of Ishmael Jetur.', 'probably from the same as 2905; encircled (i.e. inclosed);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5305}/[H5314]', 'lemma', 'heb', 'נָפִישׁ', '["Nâphîysh"]', '["Naphish"]', '["n-pr-m"]', 'Naphish, a son of Ishmael, and his posterity Naphish.', 'from 5314; refreshed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6929}/[H6923]', 'inflected', 'heb', 'קֵדְמָה', '["Qêdᵉmâh"]', '["and/ Kedemah"]', '["n-pr-m"]', 'Kedemah, a son of Ishmael Kedemah.', 'from 6923; precedence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2691B}/H9028/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["[was] in/ villages/ their","by/ villages/ their","in/ villages/ their"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2918}/H9028/[H2905]', 'inflected', 'heb', 'טִירָה', '["ṭîyrâh"]', '["and/ by/ encampments/ their"]', '["n-f"]', 'a wall; hence, a fortress or a hamlet (goodly) castle, habitation, palace, row.', 'feminine of (an equivalent to) 2905;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0523}/H9028/[H517]', 'inflected', 'heb', 'אֻמַּה', '["ʼummah"]', '["to/ tribes/ their"]', '["n-f"]', 'a collection, i.e. community of persons nation, people.', 'from the same as 517;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2341J}/[H2342]', 'inflected', 'heb', 'חֲוִילָה', '["Chăvîylâh"]', '["from/ Havilah"]', '["n-pr-loc n-pr-m"]', 'Chavilah, the name of two or three eastern regions; also perhaps of two men Havilah.', 'probably from 2342; circular;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0804G}/H9011/[H833]', 'inflected', 'heb', 'אַשּׁוּר', '["ʼAshshûwr"]', '["Asshur/ towards","Assyria/ towards"]', '["n-pr-m n-pr-loc"]', 'Ashshur, the second son of Shem; also his descendants and the country occupied by them (i.e. Assyria), its region and its empire Asshur, Assur, Assyria, Assyrians. See 838.', 'or אַשֻּׁר; apparently from 833 (in the sense of successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307G}\/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["he fell"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3947I}/H9043/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["when/ took/ he"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0761J}/[H758]', 'inflected', 'heb', 'אֲרַמִּי', '["ʼĂrammîy"]', '["the/ Aramean"]', '["a"]', 'an Aramite or Aramaean Syrian, Aramitess.', 'patrial from 758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6307>', 'inflected', 'heb', 'מפדן', '["mi./pa.Dan"]', '["from/ Paddan"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0758L}/[H759]', 'lemma', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0269}/[H251]', 'lemma', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["O sister","[the] sister of","a sister"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6279}/[H6281]', 'inflected', 'heb', 'עָתַר', '["ʻâthar"]', '["and/ I will pray","and/ he prayed","and/ he was entreated","and/ he will be entreated"]', '["v"]', 'to burn incense in worship, i.e. intercede (reciprocally, listen to prayer) intreat, (make) pray(-er).', 'a primitive root (rather denominative from 6281);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5227}/[H5226]', 'inflected', 'heb', 'נֹכַח', '["nôkach"]', '["<to>/ before","to/ before"]', '["adv"]', 'properly, the front part; used adverbially (especially with preposition), opposite, in front of, forward, in behalf of (over) against, before, direct(-ly), for, right (on).', 'from the same as 5226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7533}/[H7533]', 'inflected', 'heb', 'רָצַץ', '["râtsats"]', '["and/ he crushed","and/ it crushed","and/ it will be crushed","and/ they crushed","and/ they struggled together"]', '["v"]', 'to crack in pieces, literally or figuratively break, bruise, crush, discourage, oppress, struggle together.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1121A}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["<the>/ son","the/ child","the/ children","the/ son","the/ sons"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1875}/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["to/ consult","to/ enquire","to/ investigate","to/ seek","to/ study"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0990H>/H9022', 'inflected', 'heb', 'בבטנך', '["be./vit.Ne/kh"]', '["[are] in/ womb/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3816>', 'opaque', 'heb', 'לְאֹם', '["lᵉʼôm"]', '["O peoples","[the] nations","[the] peoples","a people","nations","peoples","peoples of","to a people"]', '["n-m"]', 'a community nation, people.', 'or לְאוֹם; from an unused root meaning to gather;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H4578>/H9022', 'inflected', 'heb', 'ממעיך', '["mi./me.''A.yi/kh"]', '["from/ inward parts/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3816>', 'inflected', 'heb', 'ולאמים', '["u./le.''Om","u./le.''u.Mim"]', '["and/ O peoples","and/ a people","and/ nations","and/ peoples"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3816>', 'inflected', 'heb', 'מלאם', '["mi/l.''Om"]', '["more than/ a people"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0553}/[H553]', 'lemma', 'heb', 'אָמַץ', '["ʼâmats"]', '["[is] making firm","[was] determined","[whom] you have made strong","[whom] you made strong","he proved himself strong","he will make firm","it will be strong","make firm","they are [too] strong","they were [too] strong","you strengthened","you will harden"]', '["v"]', 'to be alert, physically (on foot) or mentally (in courage) confirm, be courageous (of good courage, stedfastly minded, strong, stronger), establish, fortify, harden, increase, prevail, strengthen (self), make strong (obstinate, speed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7227A}/[H7231]', 'inflected', 'heb', 'רַב', '["rab"]', '["and/ [a woman] many of","and/ [is too] much","and/ [is] great","and/ [the] great [one]","and/ [the] great of","and/ [the] greatness of","and/ [will be] great","and/ [will be] many","and/ great","and/ great of","and/ many","and/ many [people]","and/ numerous"]', '["a n-m"]', 'abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent).', 'by contracted from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6810}/[H6819]', 'lemma', 'heb', 'צָעִיר', '["tsâʻîyr"]', '["[am] insignificant","[am] young","[are] insignificant","[people] young","[the] young [one]","[the] young [ones] of","insignificant"]', '["a"]', 'little; (in number) few; (in age) young, (in value) ignoble least, little (one), small (one), young(-er, -est).', 'or צָעוֹר; from 6819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/H9024', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days/ her"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8380}/[H8382]', 'lemma', 'heb', 'תָּאוֹם', '["tâʼôwm"]', '["twins","twins of"]', '["n-m"]', 'a twin (in plural only), literally or figuratively twins.', 'or תָּאֹם; from 8382;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0990H>/H9024', 'inflected', 'heb', 'בבטנה', '["be./vit.Na/h"]', '["[were] in/ womb/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7223G}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["<the>/ first","<the>/ former","the/ first","the/ first [lion]","the/ first [one]","the/ former"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0132}/[H119]', 'lemma', 'heb', 'אַדְמֹנִי', '["ʼadmônîy"]', '["[was] red","red"]', '["a"]', 'reddish (of the hair or the complexion) red, ruddy.', 'or (fully) אַדְמוֹנִי ; from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3605}/H9023/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["all of/ him","all of/ it"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0155}/[H117]', 'inflected', 'heb', 'אַדֶּרֶת', '["ʼaddereth"]', '["[was] like/ a cloak of"]', '["n-f"]', 'something ample (as a large vine, a wide dress) garment, glory, goodly, mantle, robe.', 'feminine of 117; ; also the same as 145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8181}/[H8175]', 'lemma', 'heb', 'שֵׂעָר', '["sêʻâr"]', '["[is] hair","[the] hair","[the] hair of","hair"]', '["n-m"]', 'hair (as if tossed or bristling) hair(-y), × rough.', 'or שַׂעַר; (Isaiah 7:20), from 8175 in the sense of dishevelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6215G}/[H6213]', 'lemma', 'heb', 'עֵשָׂו', '["ʻÊsâv"]', '["Esau","[am] Esau"]', '["n-pr-m"]', 'Esav, a son of Isaac, including his posterity Esau.', 'apparently a form of the passive participle of 6213 in the original sense of handling; rough (i.e. sensibly felt);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3027G}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ [is] hand/ his","and/ hand/ his","and/ hands/ his","and/ own hands/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6119}/[H6117]', 'inflected', 'heb', 'עָקֵב', '["ʻâqêb"]', '["in/ [the] footprints of","on/ [the] heel of","on/ a heel"]', '["n-m"]', 'a heel (as protuberant); hence, a track; figuratively, the rear (of an army) heel, (horse-) hoof, last, lier in wait (by mistake for 6120), (foot-) step.', 'or (feminine) עִקְּבָה; from 6117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3290}/[H6117]', 'lemma', 'heb', 'יַעֲקֹב', '["Yaʻăqôb"]', '["Jacob","O Jacob","[is] Jacob"]', '["n-pr-m"]', 'Jaakob, the Israelitish patriarch Jacob.', 'from 6117; heel-catcher (i.e. supplanter);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8346}/[H8337]', 'lemma', 'heb', 'שִׁשִּׁים', '["shishshîym"]', '["[are] sixty","[was] sixty","[were] sixty","sixty"]', '["n"]', 'sixty sixty, three score.', 'multiple of 8337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3290}/[H6117]', 'inflected', 'heb', 'יַעֲקֹב', '["Yaʻăqôb"]', '["and/ Jacob"]', '["n-pr-m"]', 'Jaakob, the Israelitish patriarch Jacob.', 'from 6117; heel-catcher (i.e. supplanter);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8535}/[H8552]', 'lemma', 'heb', 'תָּם', '["tâm"]', '["[am] blameless","[the] blameless","a blameless [person]","blameless","complete","quiet"]', '["a"]', 'complete; usually (morally) pious; specifically, gentle, dear coupled together, perfect, plain, undefiled, upright.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0157G}/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ I loved","and/ he loved","and/ she loved","and/ you will love"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6310G}/H9023/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["[is] in/ mouth/ his","[was] in/ mouth/ his","in/ mouth/ his","with/ mouth/ his","with/ mouth/ its"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7259>', 'inflected', 'heb', 'ורבקה', '["ve./riv.Kah"]', '["and/ Rebekah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2102}/[H2102]', 'inflected', 'heb', 'זוּד', '["zûwd"]', '["and/ he had cooked","and/ you acted presumptuously"]', '["v"]', 'to seethe; figuratively, to be insolent be proud, deal proudly, presume, (come) presumptuously, sod.', 'or (by permutation) זִיד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5138}/[H2102]', 'lemma', 'heb', 'נָזִיד', '["nâzîyd"]', '["cooked food"]', '["n-m"]', 'something boiled, i.e. soup pottage.', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5889}/[H5888]', 'lemma', 'heb', 'עָיֵף', '["ʻâyêph"]', '["[am] exhausted","[are] exhausted","[he is] faint","[is] a weary [one]","[the] weary","[was] exhausted","[were] exhausted","exhausted","weary"]', '["a"]', 'languid faint, thirsty, weary.', 'from 5888;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3938}/H9030/[H3938]', 'inflected', 'heb', 'לָעַט', '["lâʻaṭ"]', '["let swallow/ me"]', '["v"]', 'to swallow greedily; causatively, to feed feed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0122B}/[H119]', 'inflected', 'heb', 'אָדֹם', '["ʼâdôm"]', '["the/ red [stew]"]', '["a n-m"]', 'rosy red, ruddy.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0123H}/[H122]', 'lemma', 'heb', 'אֱדֹם', '["ʼĔdôm"]', '["Edom","[is] Edom"]', '["n-pr-m"]', 'Edom, the elder twin-brother of Jacob; hence the region (Idumaea) occupied by him Edom, Edomites, Idumea.', 'or (fully) אֱדוֹם ; from 122; red (see Genesis 25:25);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4376}/H9012/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["sell/ !"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3117L>', 'inflected', 'heb', 'כיום', '["ka/i.Yom","ka/i.yOm","khai./Yom","khai./yOm"]', '["as the/ day","like the/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1062}/H9021/[H1060]', 'inflected', 'heb', 'בְּכוֹרָה', '["bᵉkôwrâh"]', '["birthright/ your"]', '["n-f"]', 'the firstling of man or beast; abstractly primogeniture birthright, firstborn(-ling).', 'or (short) בְּכֹרָה; feminine of 1060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1062}/[H1060]', 'lemma', 'heb', 'בְּכוֹרָה', '["bᵉkôwrâh"]', '["[is] a birthright"]', '["n-f"]', 'the firstling of man or beast; abstractly primogeniture birthright, firstborn(-ling).', 'or (short) בְּכֹרָה; feminine of 1060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4376}/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["and/ I will sell","and/ he sold","and/ he will be sold","and/ he will sell","and/ he will sell himself","and/ it will be sold","and/ she sold","and/ they sold","and/ they sold themselves","and/ they were sold","and/ they will sell","and/ you will sell yourselves"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1062}/H9023/[H1060]', 'inflected', 'heb', 'בְּכוֹרָה', '["bᵉkôwrâh"]', '["birthright/ his"]', '["n-f"]', 'the firstling of man or beast; abstractly primogeniture birthright, firstborn(-ling).', 'or (short) בְּכֹרָה; feminine of 1060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3290}/[H6117]', 'inflected', 'heb', 'יַעֲקֹב', '["Yaʻăqôb"]', '["<to>/ Jacob","[belong] to/ Jacob","[belonged] to/ Jacob","[belonging] to/ Jacob","for/ Jacob","of/ Jacob","to/ Jacob"]', '["n-pr-m"]', 'Jaakob, the Israelitish patriarch Jacob.', 'from 6117; heel-catcher (i.e. supplanter);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6215G}/[H6213]', 'inflected', 'heb', 'עֵשָׂו', '["ʻÊsâv"]', '["for/ Esau","to/ Esau"]', '["n-pr-m"]', 'Esav, a son of Isaac, including his posterity Esau.', 'apparently a form of the passive participle of 6213 in the original sense of handling; rough (i.e. sensibly felt);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5138}/[H2102]', 'inflected', 'heb', 'נָזִיד', '["nâzîyd"]', '["and/ cooked food of"]', '["n-m"]', 'something boiled, i.e. soup pottage.', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5742>', 'opaque', 'heb', 'עָדָשׁ', '["ʻâdâsh"]', '["lentils","of lentils"]', '["n-f"]', 'a lentil lentile.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0959}/[H959]', 'inflected', 'heb', 'בָּזָה', '["bâzâh"]', '["and/ he despised","and/ she despised","and/ they despised"]', '["v"]', 'to disesteem despise, disdain, contemn(-ptible), think to scorn, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1062}\/[H1060]', 'inflected', 'heb', 'בְּכוֹרָה', '["bᵉkôwrâh"]', '["the/ birthright"]', '["n-f"]', 'the firstling of man or beast; abstractly primogeniture birthright, firstborn(-ling).', 'or (short) בְּכֹרָה; feminine of 1060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H0905J}/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["<from>/ <to>/ besides"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7223H}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["<the>/ first","<the>/ former","the/ former","the/ former [things]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7621}/[H7650]', 'inflected', 'heb', 'שְׁבוּעָה', '["shᵉbûwʻâh"]', '["the/ oath"]', '["n-f"]', 'properly, something sworn, i.e. an oath curse, oath, × sworn.', 'feminine passive participle of 7650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4931}/H9020/[H4929]', 'inflected', 'heb', 'מִשְׁמֶרֶת', '["mishmereth"]', '["charge/ my","duty/ my","post/ my"]', '["n-f"]', 'watch, i.e. the act (custody), or (concretely) the sentry, the post; objectively preservation, or (concretely) safe; figuratively observance, i.e. (abstractly) duty or (objectively) a usage or party charge, keep, or to be kept, office, ordinace, safeguard, ward, watch.', 'feminine of 4929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4687}/H9020/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["commandments/ my"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2708}/H9020/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["statutes/ my"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8451}/H9020/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["and/ instruction/ my","and/ law/ my","and/ laws/ my"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0748}/[H748]', 'lemma', 'heb', 'אָרַךְ', '["ʼârak"]', '["I will make long","I will prolong","[who] prolongs","do you make long?","he may prolong","he will prolong","it makes long","it will last long","make long","they are long","they had become long","they have made long","they made long","they may be long","you may prolong","you will prolong"]', '["v"]', 'to be (causative, make) long (literally or figuratively) defer, draw out, lengthen, (be, become, make, pro-) long, (out-, over-) live, tarry (long).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2474}/[H2474]', 'inflected', 'heb', 'חַלּוֹן', '["challôwn"]', '["the/ window","the/ windows"]', '["n"]', 'a window (as perforated) window.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0349A}/[H335]', 'inflected', 'heb', 'אֵיךְ', '["ʼêyk"]', '["and/ how!","and/ how?"]', '["adv"]', 'how? or how!; also where how, what.', 'also אֵיכָה ; and אֵיכָכָה ; prolonged from 335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4592}/[H4591]', 'inflected', 'heb', 'מְעַט', '["mᵉʻaṭ"]', '["[is] like/ a little","like/ a few","like/ a little","like/ a little of"]', '["n-m"]', 'a little or few (often adverbial or comparative) almost (some, very) few(-er, -est), lightly, little (while), (very) small (matter, thing), some, soon, × very.', 'or מְעָט; from 4591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0817}/[H816]', 'lemma', 'heb', 'אָשָׁם', '["ʼâshâm"]', '["[is] a guilt offering","a guilt offering","guilt","guilt offering"]', '["n-m"]', 'guilt; by implication, a fault; also a sin-offering guiltiness, (offering for) sin, trespass (offering).', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5060}/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["<the>/ [one who] touches","<the>/ [thing which] touches","the/ [one who] touched","the/ [one who] touches","who/ [-ever] touches","who/ touch","who/ touches","who/ touches [it]"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0802H}/H9023/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ <in>/ wife/ his"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2232}/[H2232]', 'inflected', 'heb', 'זָרַע', '["zâraʻ"]', '["and/ I will sow","and/ he sowed","and/ she will be impregnated","and/ they sowed","and/ you will be sown","and/ you will sow"]', '["v"]', 'to sow; figuratively, to disseminate, plant, fructify bear, conceive seed, set with sow(-er), yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8180}/[H8176]', 'lemma', 'heb', 'שַׁעַר', '["shaʻar"]', '["measures"]', '["n-m"]', 'a measure (as a section) (hundred-) fold.', 'from 8176;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1980L}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ he went","and/ it went","and/ she will go"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1432}/[H1431]', 'inflected', 'heb', 'גָּדֵל', '["gâdêl"]', '["and/ [was] becoming great","and/ [was] growing up","and/ becoming great"]', '["a"]', 'large (literally or figuratively) great, grew.', 'from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5657}/[H5647]', 'inflected', 'heb', 'עֲבֻדָּה', '["ʻăbuddâh"]', '["and/ service"]', '["n-f"]', 'something wrought, i.e. (concretely) service household, store of servants.', 'passive participle of 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7065}/[H7065]', 'inflected', 'heb', 'קָנָא', '["qânâʼ"]', '["and/ I will be zealous","and/ he will be jealous of","and/ she was jealous","and/ they envied","and/ they made jealous","and/ they were envious","and/ they were jealous"]', '["v"]', 'to be (causatively, make) zealous, i.e. (in a bad sense) jealous or envious (be) envy(-ious), be (move to, provoke to) jealous(-y), × very, (be) zeal(-ous).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5640A}/H9038/[H5640]', 'inflected', 'heb', 'סָתַם', '["çâtham"]', '["they stopped up/ them"]', '["v"]', 'to stop up; by implication, to repair; figuratively, to keep secret closed up, hidden, secret, shut out (up), stop.', 'or שָׂתַם; (Numbers 24:15), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4390}/H9038/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["and/ people gave in full/ them","and/ they filled/ them"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5973B}/H9035/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["from/ with <the>/ us"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6105A}/[H6106]', 'lemma', 'heb', 'עָצַם', '["ʻâtsam"]', '["they are [too] numerous","they are numerous","they are vast","you have become [too] powerful"]', '["v"]', 'to bind fast, i.e. close (the eyes); intransitively, to be (causatively, make) powerful or numerous; to crunch the bones break the bones, close, be great, be increased, be (wax) mighty(-ier), be more, shut, be(-come, make) strong(-er).', 'a primitive root; also denominatively (from 6106)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2583}/[H2603]', 'inflected', 'heb', 'חָנָה', '["chânâh"]', '["and/ I will encamp","and/ he camped","and/ he encamped","and/ it encamped","and/ they encamped","and/ they have encamped","and/ they will encamp","and/ we encamped"]', '["v"]', 'properly, to incline; by implication, to decline (of the slanting rays of evening); specifically, to pitch a tent; generally to encamp (for abode or siege) abide (in tents), camp, dwell, encamp, grow to an end, lie, pitch (tent), rest in tent.', 'a primitive root (compare 2603);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5158N}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["[is] in the/ wadi","at/ [the] wadi of","in the/ wadi","in the/ wadis","in/ [the] wadi of","in/ [the] wadis of"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725J}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I returned","and/ he returned","and/ he turned back","and/ he will bring back","and/ he will return","and/ he would return","and/ it will return","and/ they have returned","and/ they returned","and/ they turned back","and/ they will turn back","and/ we have brought back","and/ you will return"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2658}/[H2658]', 'inflected', 'heb', 'חָפַר', '["châphar"]', '["and/ I dug","and/ he dug","and/ they dug","and/ you will be well protected","and/ you will dig"]', '["v"]', 'properly, to pry into; by implication, to delve, to explore dig, paw, search out, seek.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5640A}/H9038/[H5640]', 'inflected', 'heb', 'סָתַם', '["çâtham"]', '["and/ they had stopped up/ them"]', '["v"]', 'to stop up; by implication, to repair; figuratively, to keep secret closed up, hidden, secret, shut out (up), stop.', 'or שָׂתַם; (Numbers 24:15), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7378}/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["and/ I contended","and/ [one who] contends","and/ he quarreled","and/ it quarreled","and/ they disputed"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6230}/[H6229]', 'lemma', 'heb', 'עֵשֶׂק', '["ʻêseq"]', '["Esek"]', '["n"]', 'strife Esek.', 'from 6229;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6229}/[H6231]', 'lemma', 'heb', 'עָשַׂק', '["ʻâsaq"]', '["they quarreled"]', '["v"]', 'to press upon, i.e. quarrel strive with.', 'a primitive root (identical with 6231);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7856}/[H7855]', 'lemma', 'heb', 'שִׂטְנָה', '["Siṭnâh"]', '["Sitnah"]', '["n-pr-m"]', 'Sitnah, the name of a well in Pal Sitnah.', 'the same as 7855;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7378}/[H7378]', 'lemma', 'heb', 'רִיב', '["rîyb"]', '["I bring a case","I will conduct a case","I will contend","I will oppose","[am] about to conduct","[one who] contends","[who] he conducts a case for","certainly <conduct>","conduct","conduct a case","conduct a case for","did he quarrel","do you contend","have you contended","he bring a case","he contended","he has conducted","he will conduct","he will conduct a case","let him conduct a case","they disputed","they quarreled","will he conduct a case","will he contend","you contend","you have conducted"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7344G}/[H7339]', 'lemma', 'heb', 'רְחֹבוֹת', '["Rᵉchôbôwth"]', '["Rehoboth"]', '["n-pr-loc"]', 'Rechoboth, a place in Assyria and one in Palestine Rehoboth.', 'or רְחֹבֹת; plural of 7339; streets;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7337}/[H7337]', 'lemma', 'heb', 'רָחַב', '["râchab"]', '["[one who] enlarges","do you make wide","enlarge","he has made large","he has made space","he will enlarge","it has opened wide","it makes space","it will enlarge","make large","roomy","someone has made [it] large","they have made wide","to enlarge","you enlarge","you have enlarged","you have made wide"]', '["v"]', 'to broaden (intransitive or transitive, literal or figurative) be an en-(make) large(-ing), make room, make (open) wide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1288}/H9031/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["and/ I will bless/ you","and/ he will bless/ you"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5650}/H9020/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["O servant/ my","[are] servant/ my","[are] servants/ my","male servant/ my","servant/ my","servants/ my"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3738B}/[H3738]', 'inflected', 'heb', 'כָּרָה', '["kârâh"]', '["and/ they dug"]', '["v"]', 'properly, to dig; figuratively, to plot; generally, to bore or open dig, × make (a banquet), open.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1642}/[H1641]', 'inflected', 'heb', 'גְּרָר', '["Gᵉrâr"]', '["from/ Gerar"]', '["n-pr-loc"]', 'Gerar, a Philistine city Gerar.', 'probably from 1641; a rolling country;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0276}/[H272]', 'inflected', 'heb', 'אֲחֻזַּת', '["ʼĂchuzzath"]', '["and/ Ahuzzah"]', '["n-pr-m"]', 'Achuzzath, a Philistine Ahuzzath.', 'a variation of 272; possession;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4828}/H9023/[H7462]', 'inflected', 'heb', 'מֵרֵעַ', '["mêrêaʻ"]', '["close friend/ his","friend[s]/ his"]', '["n-m"]', 'a friend companion, friend.', 'from 7462 in the sense of companionship;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4069}/[H4100]', 'lemma', 'heb', 'מַדּוּעַ', '["maddûwaʻ"]', '["why?"]', '["adv"]', 'what (is) known?; i.e. (by implication) (adverbially) why? how, wherefore, why.', 'or מַדֻּעַ; from 4100 and the passive participle of 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8130}/[H8130]', 'lemma', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["I hate","I hated","[I am] hating","[am] hated","[is] hated","[is] hating","[is] to hate","[one who] hated","[one who] hates","[those who] hate","[was] hated","[was] hating","[who are] hated","[who] hate","a hated [woman]","certainly <to hate>","did you hate","do I hate","hate","haters of","hating","he hated","he hates","he is hated","it hates","they hate","they hated","to hate","will they hate?","you hate","you hated","you have hated","you will hate"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971G}/H9030/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ he sent/ me","and/ you sent away/ me"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0854}/H9036/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["from/ with <the>/ you"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/H9032/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[am] with/ you","[be] with/ you","[have been] with/ you","[is anyone] with/ you","[is] with/ you","[was] with/ you","[will be] with/ you","with/ you","with/ yourself"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0423}/[H422]', 'lemma', 'heb', 'אָלָה', '["ʼâlâh"]', '["[the] oath","[the] oaths of","a curse","an oath"]', '["n-f"]', 'an imprecation curse, cursing, execration, oath, swearing.', 'from 422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0996G}/H9035/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["between/ us"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3772H}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ I will make","and/ let us make","and/ you made","so/ they may make"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451C}/[H7489]', 'lemma', 'heb', 'רַע', '["raʻ"]', '["[the] trouble of","[the] troubles of","a calamity","adversity","an evil","calamities","calamity","evil","harm","trouble"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5060}/H9031/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["we have touched/ you"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0834D}/[H834]', 'inflected', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["and/ <as>/ since","and/ just/ as","and/ just/ when"]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971G}/H9031/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ I sent away/ you","and/ I will send away/ you","and/ he sent/ you","and/ we sent away/ you"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7656}/[H7651]', 'lemma', 'heb', 'שִׁבְעָה', '["Shibʻâh"]', '["Shibah"]', '["n-pr-loc"]', 'Shebah, a well in Palestine Shebah.', 'masculine of 7651; seven(-th);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2088}\/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["<the>/ this"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3067}/[H3066]', 'lemma', 'heb', 'יְהוּדִית', '["Yᵉhûwdîyth"]', '["Judith"]', '["n-pr-f"]', 'Jehudith, a Canaanitess Judith.', 'the same as 3066; Jewess;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0882G}/[H875]', 'lemma', 'heb', 'בְּאֵרִי', '["Bᵉʼêrîy"]', '["Beeri"]', '["n-pr-m"]', 'Beeri, the name of a Hittite and of an Israelite Beeri.', 'from 875; fountained;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1315H}/[H1314]', 'lemma', 'heb', 'בׇּשְׂמַת', '["Bosmath"]', '["Basemath"]', '["n-pr-f"]', 'Bosmath, the name of a wife of Esau, and of a daughter of Solomon Bashemath, Basmath.', 'feminine of 1314 (the second form); fragrance;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0356G}/[H352]', 'lemma', 'heb', 'אֵילוֹן', '["ʼÊylôwn"]', '["Elon"]', '["n-pr"]', 'Elon, the name of a place in Palestine, and also of one Hittite, two Israelites Elon.', 'or (shortened) אֵלוֹן ; or אֵילֹן ; from 352; oak-grove;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4786}/[H4843]', 'lemma', 'heb', 'מֹרָה', '["môrâh"]', '["bitterness of"]', '["n-f"]', 'bitterness, i.e. (figuratively) trouble grief.', 'from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307G}/[H7306]', 'lemma', 'heb', 'רוּחַ', '["rûwach"]', '["[are] a spirit","[is the] spirit","[the] spirit of","a spirit","a spirit of","a wind","spirit","spirits"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H7259>\', 'inflected', 'heb', 'ולרבקה ס', '["u./le./riv.Kah"]', '["and/ to/ Rebekah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3543A}/[H3543]', 'inflected', 'heb', 'כָּהָה', '["kâhâh"]', '["and/ it has grown dim","and/ it will grow faint","and/ they were [too] dim"]', '["v"]', 'to be weak, i.e. (figuratively) to despond (causatively, rebuke), or (of light, the eye) to grow dull darken, be dim, fail, faint, restrain, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7200G}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["for/ seeing","from/ looking","from/ looking at","from/ seeing"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4194}/H9020/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["death/ my"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3627}/H9021/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["baggage<s>/ your","vessel/ your","weapons/ your"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8522}/H9021/[H8518]', 'inflected', 'heb', 'תְּלִי', '["tᵉlîy"]', '["quiver/ your"]', '["n-m"]', 'a quiver (as slung) quiver.', 'probably from 8518;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7198}/H9021/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["and/ bow/ your"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3318G}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ [was] going out","and/ come out","and/ go out","and/ let us go out","so/ <it> may go out","so/ he may go out","so/ it may go out","so/ let me go out","so/ they may go forth","so/ they may go out","so/ we may go out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6679A}/H9012/[H6718]', 'inflected', 'heb', 'צוּד', '["tsûwd"]', '["and/ hunt/ !"]', '["v"]', 'to lie alongside (i.e. in wait); by implication, to catch an animal (figuratively, men); to victual (for a journey) chase, hunt, sore, take (provision).', 'a primitive root; also denominative from 6718');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4303}/[H2938]', 'lemma', 'heb', 'מַטְעַם', '["maṭʻam"]', '["savory food<s>"]', '["n-m"]', 'a delicacy dainty (meat), savoury meat.', 'or (feminine) מַטְעַמָּה; from 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0935P}/H9012/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ bring [it]/ !"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0398}/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ I may eat","and/ [is] eating","and/ [those who] eat","and/ certainly <eat>","and/ eat","and/ eating","and/ let him eat","and/ let it consume","so/ I may eat [it]","so/ he may eat","so/ it may consume","so/ it may eat","so/ let me eat","so/ let me eat [it]","so/ let us eat","so/ they may eat","so/ we may eat"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315I}/H9020/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["O self/ my","life/ my","self/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2962>', 'inflected', 'heb', 'בטרם', '["be./Te.rem","be./te.Rem","bi/t.rom"]', '["<in>/ before"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1696G}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["when/ speak","when/ spoke"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6679A}/[H6718]', 'inflected', 'heb', 'צוּד', '["tsûwd"]', '["to/ hunt"]', '["v"]', 'to lie alongside (i.e. in wait); by implication, to catch an animal (figuratively, men); to victual (for a journey) chase, hunt, sore, take (provision).', 'a primitive root; also denominative from 6718');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0935P}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["by/ bringing","to/ bring","to/ bring [it]","to/ bring [them]","to/ take"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935P}/H9012/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["bring/ !"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0834A}/[H834]', 'inflected', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["<to>/ [those] whom","[will belong] to/ [that] which","and/ [one] who","for/ [those] who","for/ whom","to/ [that] which","to/ [the one] who","to/ [the one] whom","to/ [those] who","to/ [those] whom"]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1423}/[H1415]', 'lemma', 'heb', 'גְּדִי', '["gᵉdîy"]', '["[the] kid of","[the] kids of","a kid","a kid of","kid","kids","kids of"]', '["n-m"]', 'a young goat (from browsing) kid.', 'from the same as 1415;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5795}/[H5810]', 'lemma', 'heb', 'עֵז', '["ʻêz"]', '["[is] a goat","a female goat","a goat","female goats","goat hair<s>","goats"]', '["n-f"]', 'a she-goat (as strong), but masculine in plural (which also is used elliptically for goat''s hair) (she) goat, kid.', 'from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0001G}/H9021/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["[belongs] to/ father/ your","for/ father/ your","to/ ancestors/ your","to/ father/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4194}/H9023/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["death/ his"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8163A}/[H8175]', 'lemma', 'heb', 'שָׂעִיר', '["sâʻîyr"]', '["hairy"]', '["a n-m"]', 'shaggy; as noun, a he-goat; by analogy, a faun devil, goat, hairy, kid, rough, satyr.', 'or שָׂעִר; from 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2509}/[H2505]', 'lemma', 'heb', 'חָלָק', '["châlâq"]', '["flattering","flattery","smooth"]', '["a"]', 'smooth (especially of tongue) flattering, smooth.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4959}/H9030/[H4959]', 'inflected', 'heb', 'מָשַׁשׁ', '["mâshash"]', '["he will feel/ me"]', '["v"]', 'to feel of; by implication, to grope feel, grope, search.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869I}/H9023/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ eyes/ his","in/ own eyes/ his","in/ view/ his"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8591}/[H8591]', 'inflected', 'heb', 'תָּעַע', '["tâʻaʻ"]', '["like/ a mocker"]', '["v"]', 'to cheat; by analogy, to maltreat deceive, misuse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7045}/[H7043]', 'lemma', 'heb', 'קְלָלָה', '["qᵉlâlâh"]', '["[is] a curse of","[the] curse of","a curse"]', '["n-f"]', 'vilification (ac-) curse(-d, -ing).', 'from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7045}/H9021/[H7043]', 'inflected', 'heb', 'קְלָלָה', '["qᵉlâlâh"]', '["curse/ your"]', '["n-f"]', 'vilification (ac-) curse(-d, -ing).', 'from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0517}/H9023/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["for/ mother/ his","to/ mother/ his"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0899B}/[H898]', 'lemma', 'heb', 'בֶּגֶד', '["beged"]', '["[are] garments of","[the] clothes of","[the] clothing of","[the] garment of","[the] garments of","a covering of","a garment","clothes","clothes of","clothing","garment","garments","garments of"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2532B}/[H2531]', 'inflected', 'heb', 'חֶמְדָּה', '["chemdâh"]', '["the/ desirableness<es>"]', '["n-f"]', 'delight desire, goodly, pleasant, precious.', 'feminine of 2531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9034/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["[is] with/ her","[were] with/ her","with <the>/ her","with <the>/ it","with/ her","with/ it"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004B}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["<in>/ a house","[be] in/ [the] house of","[is] in the/ house","[is] in/ a house of","[is] on/ [the] house of","[was] in/ [the] house of","[were] in the/ house","[were] in the/ houses","[were] in/ [the] house of","[will be] at/ [the] house of","at/ [the] house of","in the/ house","in the/ houses","in/ [the] house of","in/ [the] houses of","in/ a house","in/ a house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3847}/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["and/ he clothed","and/ he put on","and/ he was clothed","and/ he will put on","and/ he will wear","and/ she clothed","and/ she put on","and/ they will clothe","and/ they will put on","and/ they wore","and/ you will clothe"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5795}/[H5810]', 'inflected', 'heb', 'עֵז', '["ʻêz"]', '["<the>/ goat hair<s>","<the>/ she-goats","the/ female goats","the/ goat hair<s>","the/ goats"]', '["n-f"]', 'a she-goat (as strong), but masculine in plural (which also is used elliptically for goat''s hair) (she) goat, kid.', 'from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3847}/[H3847]', 'lemma', 'heb', 'לָבַשׁ', '["lâbash"]', '["<the> clothed of","I clothe","I put on","I will clothe","[is] clothed","[the] [man] clothed of","[was] clothed","[were] fully clothed","clothed","clothed of","fully clothed","he has worn","he is clothed","he will put on","he will wear","he will wear [it]","he wore","it clothed","it is clothed","it will clothe [them]","let them be clothed","may they be clothed","put on","she clothed","they are clothed","they clothed","they will be clothed","they will wear","they wore","we will wear","wear","you are clothed","you are dressing","you clothe yourselves","you have dressed","you will be clothed","you will put on","you will wear"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2513B}/[H2506]', 'lemma', 'heb', 'חֶלְקָה', '["chelqâh"]', '["[the] smooth part of","flatteri<es>","flattering [words]"]', '["n-f"]', 'properly, smoothness; figuratively, flattery; also an allotment field, flattering(-ry), ground, parcel, part, piece of land (ground), plat, portion, slippery place, smooth (thing).', 'feminine of 2506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6677A}/H9023/[H6696]', 'inflected', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["neck/ his","neck/ its","neck<s>/ his"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4303}/[H2938]', 'inflected', 'heb', 'מַטְעַם', '["maṭʻam"]', '["the/ savory food<s>"]', '["n-m"]', 'a delicacy dainty (meat), savoury meat.', 'or (feminine) מַטְעַמָּה; from 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3899H}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["<the>/ bread","[is] the/ bread","[is] the/ food","the/ bread","the/ food"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027H}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[are] in/ [the] hand of","[is] in/ [the] hand of","[was] in/ [the] hand of","by/ [the] hand of","by/ a hand","in/ [the] hand of","in/ [the] hands of","in/ a hand","on/ [the] hand of","with/ a hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1060}/H9021/[H1069]', 'inflected', 'heb', 'בְּכוֹר', '["bᵉkôwr"]', '["firstborn/ your"]', '["n-m"]', 'first-born; hence, chief eldest (son), firstborn(-ling).', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3427}/H9012/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["remain/ !","sit/ !"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0398}/H9012/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ eat/ !"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6718A}/H9020/[H6679]', 'inflected', 'heb', 'צַיִד', '["tsayid"]', '["some of/ wild game/ my"]', '["n-m"]', 'the chase; also game (thus taken) × catcheth, food, × hunter, (that which he took in) hunting, venison, victuals.', 'from a form of 6679 and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1288}/H9030/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["<it> may bless/ me","bless/ me","he has blessed/ me","they blessed/ me","you have blessed/ me","you will bless/ me"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315I}/H9021/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["appetite/ your","self/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9021/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ your","[am] God/ your","[is] God/ your","[is] god/ your","god/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5066G}/H9012/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["draw near/ !"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4184}/H9031/[H4184]', 'inflected', 'heb', 'מוּשׁ', '["mûwsh"]', '["so/ I may feel/ you"]', '["v"]', 'to touch feel, handle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0859A}/[H859]', 'inflected', 'heb', 'אַתָּה', '["ʼattâh"]', '["¿/ [are] you","¿/ you"]', '["p"]', 'thou and thee, or (plural) ye and you thee, thou, ye, you.', 'or (shortened); אַתָּ; or אַת; feminine (irregular) sometimes אַתִּי; plural masculine אַתֶּם; feminine אַתֶּן; or אַתֵּנָהlemma אתֵּנָה missing vowel, corrected to אַתֵּנָה; or אַתֵּנָּה; a primitive pronoun of the second person;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4959}/H9033/[H4959]', 'inflected', 'heb', 'מָשַׁשׁ', '["mâshash"]', '["and/ he felt/ him"]', '["v"]', 'to feel of; by implication, to grope feel, grope, search.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6963A>', 'inflected', 'heb', 'הקול', '["ha./Kol","ha./kOl"]', '["the/ sound","the/ voice"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3027G}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ the/ hands"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5234A}/H9033/[H5234]', 'inflected', 'heb', 'נָכַר', '["nâkar"]', '["he recognized/ him","it will acknowledge/ him","it will recognize/ it","they recognized/ him"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3027G}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["like/ [the] hands of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5066H}/H9012/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["bring [it] near/ !","bring near/ !"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6718A}/[H6679]', 'inflected', 'heb', 'צַיִד', '["tsayid"]', '["some of/ [the] wild game of"]', '["n-m"]', 'the chase; also game (thus taken) × catcheth, food, × hunter, (that which he took in) hunting, venison, victuals.', 'from a form of 6679 and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5066H}/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["and/ he brought [it] near","and/ he brought [them] near","and/ he brought near","and/ she brought [them]","and/ she brought [them] near","and/ they brought near"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5401A}/H9012/[H5400]', 'inflected', 'heb', 'נָשַׁק', '["nâshaq"]', '["and/ kiss/ !"]', '["v"]', 'to kiss, literally or figuratively (touch); also (as a mode of attachment), to equip with weapons armed (men), rule, kiss, that touched.', 'a primitive root (identical with 5400, through the idea of fastening up; compare 2388, 2836);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5401A}/[H5400]', 'inflected', 'heb', 'נָשַׁק', '["nâshaq"]', '["and/ he kissed","and/ it kissed","and/ she kissed","and/ she kisses","and/ they kissed"]', '["v"]', 'to kiss, literally or figuratively (touch); also (as a mode of attachment), to equip with weapons armed (men), rule, kiss, that touched.', 'a primitive root (identical with 5400, through the idea of fastening up; compare 2388, 2836);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0899B}/H9023/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["clothes/ his","clothing/ his","garment/ his","garments/ his"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7381}/[H7306]', 'inflected', 'heb', 'רֵיחַ', '["rêyach"]', '["[is] like/ [the] odor of","[is] like/ [the] smell of"]', '["n-m"]', 'odor (as if blown) savour, scent, smell.', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1288}/H9033/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["he had blessed/ him","he has blessed/ it","he will bless/ it","may someone bless/ him","you must bless/ him","you will bless/ it"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2919}/[H2926]', 'inflected', 'heb', 'טַל', '["ṭal"]', '["from/ [the] dew","from/ dew","some of/ [the] dew of"]', '["n-m"]', 'dew (as covering vegetation) dew.', 'from 2926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4924A}/[H8080]', 'inflected', 'heb', 'מַשְׁמָן', '["mashmân"]', '["and/ some of/ [the] fatness<es> of"]', '["n-m"]', 'fat, i.e. (literally and abstractly) fatness; but usually (figuratively and concretely) a rich dish, a fertile field, a robust man fat (one, -ness, -test, -test place).', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7230}/[H7231]', 'inflected', 'heb', 'רֹב', '["rôb"]', '["and/ [the] multitude of","and/ abundance of","and/ greatness of"]', '["n-m"]', 'abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age).', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1715}/[H1711]', 'lemma', 'heb', 'דָּגָן', '["dâgân"]', '["[are] grain","grain"]', '["n-m"]', 'properly, increase, i.e. grain corn (floor), wheat.', 'from 1711;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8492}/[H3423]', 'inflected', 'heb', 'תִּירוֹשׁ', '["tîyrôwsh"]', '["and/ new wine"]', '["n-m"]', 'must or fresh grape-juice (as just squeezed out); by implication (rarely) fermented wine (new, sweet) wine.', 'or תִּירֹשׁ; from 3423 in the sense of expulsion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647G}/H9031/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["I have served/ you","I served/ you","I will serve/ you","he has served/ you","may they serve/ you","to serve/ you"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1933B}/[H183]', 'lemma', 'heb', 'הָוָא', '["hâvâʼ"]', '["[are] about to become","[is] becoming","be","it will be"]', '["v"]', 'to be (in the sense of existence) be, × have.', 'or הָוָה; a primitive root (compare 183, 1961) supposed to mean properly, to breathe;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1376}/[H1396]', 'lemma', 'heb', 'גְּבִיר', '["gᵉbîyr"]', '["lord"]', '["n-m"]', 'a master lord.', 'from 1396;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251G}/H9021/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["for/ brother/ your","to/ brothers/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0517}/H9021/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["[is] mother/ your","[was] mother/ your","mother/ your"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0779}/H9031/[H779]', 'inflected', 'heb', 'אָרַר', '["ʼârar"]', '["[those who] curse/ you"]', '["v"]', 'to execrate × bitterly curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1288}/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["to/ bless"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6215G}/[H6213]', 'inflected', 'heb', 'עֵשָׂו', '["ʻÊsâv"]', '["and/ Esau"]', '["n-pr-m"]', 'Esav, a son of Isaac, including his posterity Esau.', 'apparently a form of the passive participle of 6213 in the original sense of handling; rough (i.e. sensibly felt);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6718A}/H9023/[H6679]', 'inflected', 'heb', 'צַיִד', '["tsayid"]', '["from/ hunting/ his"]', '["n-m"]', 'the chase; also game (thus taken) × catcheth, food, × hunter, (that which he took in) hunting, venison, victuals.', 'from a form of 6679 and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0001G}/H9023/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["[belong] to/ father/ his","for/ father/ his","of/ father/ his","to/ ancestors/ its","to/ father/ his"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2729}/[H2729]', 'inflected', 'heb', 'חָרַד', '["chârad"]', '["and/ I will terrify","and/ he trembled","and/ it trembled","and/ it will tremble","and/ they trembled","and/ they will tremble"]', '["v"]', 'to shudder with terror; hence, to fear; also to hasten (with anxiety) be (make) afraid, be careful, discomfit, fray (away), quake, tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2731}/[H2730]', 'lemma', 'heb', 'חֲרָדָה', '["chărâdâh"]', '["fear","fear of","terror","trembling","trembling<s>"]', '["n-f"]', 'fear, anxiety care, × exceedingly, fear, quaking, trembling.', 'feminine of 2730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0645}/[H6311]', 'lemma', 'heb', 'אֵפוֹ', '["ʼêphôw"]', '["then"]', '["prt"]', 'strictly a demonstrative particle, here; but used of time, now or then here, now, where?', 'or אֵפוֹא; from 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6679A}/[H6718]', 'inflected', 'heb', 'צוּד', '["tsûwd"]', '["who/ hunted"]', '["v"]', 'to lie alongside (i.e. in wait); by implication, to catch an animal (figuratively, men); to victual (for a journey) chase, hunt, sore, take (provision).', 'a primitive root; also denominative from 6718');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8085G}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["when/ heard"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6817}/[H6817]', 'inflected', 'heb', 'צָעַק', '["tsâʻaq"]', '["and/ he called together","and/ he cried","and/ he cried out","and/ he was summoned","and/ it cried out","and/ it was summoned","and/ they cried out","and/ they were summoned","and/ we cried out","and/ you cried out"]', '["v"]', 'to shriek; (by implication) to proclaim (an assembly) × at all, call together, cry (out), gather (selves) (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6818}/[H6817]', 'lemma', 'heb', 'צַעֲקָה', '["tsaʻăqâh"]', '["<the> cry of distress of","[the] calling out","[the] cry of distress of","[the] crys of","[the] outcry of","a cry","a cry of distress"]', '["n-f"]', 'a shriek cry(-ing).', 'from 6817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4751}/[H4843]', 'inflected', 'heb', 'מַר', '["mar"]', '["and/ [are] bitter of","and/ bitter"]', '["a-m"]', 'bitter (literally or figuratively); also (as noun) bitterness, or (adverbially) bitterly angry, bitter(-ly, -ness), chafed, discontented, × great, heavy.', 'or (feminine) מָרָה; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4820}/[H7411]', 'inflected', 'heb', 'מִרְמָה', '["mirmâh"]', '["on/ deceit","with/ deceit"]', '["n-f"]', 'fraud craft, deceit(-ful, -fully), false, feigned, guile, subtilly, treachery.', 'from 7411 in the sense of deceiving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1293}/H9021/[H1288]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["blessing/ your"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3588A}/[H3588]', 'inflected', 'heb', 'כִּי', '["kîy"]', '["¿/ for"]', '["conj"]', '(by implication) very widely used as a relative conjunction or adverb (as below); often largely modified by other particles annexed and, (forasmuch, inasmuch, where-) as, assured(-ly), but, certainly, doubtless, else, even, except, for, how, (because, in, so, than) that, nevertheless, now, rightly, seeing, since, surely, then, therefore, (al-) though, till, truly, until, when, whether, while, whom, yea, yet.', 'a primitive particle (the full form of the prepositional prefix) indicating causal relations of all kinds, antecedent or consequent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6117}/H9030/[H6119]', 'inflected', 'heb', 'עָקַב', '["ʻâqab"]', '["and/ he has supplanted/ me"]', '["v"]', 'to seize by the heel; figuratively, to circumvent (as if tripping up the heels); also to restrain (as if holding by the heel) take by the heel, stay, supplant, × utterly.', 'a primitive root; properly, to swell out or up; used only as denominative from 6119,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6471}/[H6470]', 'lemma', 'heb', 'פַּעַם', '["paʻam"]', '["[the] footsteps of","[the] hoof-beats of","a time","an anvil","time","times","two times"]', '["n-f"]', 'a stroke, literally or figuratively (in various applications, as follow) anvil, corner, foot(-step), going, (hundred-) fold, × now, (this) once, order, rank, step, thrice, (often-), second, this, two) time(-s), twice, wheel.', 'or (feminine) פַּעֲמָה; from 6470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1062}/H9020/[H1060]', 'inflected', 'heb', 'בְּכוֹרָה', '["bᵉkôwrâh"]', '["birthright/ my"]', '["n-f"]', 'the firstling of man or beast; abstractly primogeniture birthright, firstborn(-ling).', 'or (short) בְּכֹרָה; feminine of 1060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1293}/H9020/[H1288]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["blessing/ my"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0680}/[H680]', 'lemma', 'heb', 'אָצַל', '["ʼâtsal"]', '["I withheld","have you reserved","it was shortened"]', '["v"]', 'properly, to join; used only as a denominative from 681; to separate; hence, to select, refuse, contract keep, reserve, straiten, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5650}/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["<into>/ [male] slaves","<into>/ a servant","<into>/ a servant of","<into>/ servants","<into>/ slaves","<into>/ subjects","[belongs] to/ a servant","for/ [male] slaves","for/ a slave","into/ slaves","of/ [the] servant of","to/ [male] servants","to/ [male] slaves","to/ a servant of","to/ a slave","to/ a slave of","to/ male slaves","to/ servants","to/ slaves","to/ subjects"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1715}/[H1711]', 'inflected', 'heb', 'דָּגָן', '["dâgân"]', '["and/ [the] grain of","and/ grain"]', '["n-m"]', 'properly, increase, i.e. grain corn (floor), wheat.', 'from 1711;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5564}/H9033/[H5564]', 'inflected', 'heb', 'סָמַךְ', '["çâmak"]', '["I have sustained/ him","it sustained/ him"]', '["v"]', 'to prop (literally or figuratively); reflexively, to lean upon or take hold of (in a favorable or unfavorable sense) bear up, establish, (up-) hold, lay, lean, lie hard, put, rest self, set self, stand fast, stay (self), sustain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H9031}', 'inflected', 'arc', 'ולכה', '["u./le./Kha","u./le./Khah","u./le./kha","va./La/kh","ve./La/kh"]', '["and/ <obj.>/ you","and/ [belongs] to <the>/ you","and/ [belongs] to/ you","and/ [will belong] to <the>/ you","and/ for <the>/ you","and/ to <the>/ you","and/ to/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1293}/[H1288]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["¿/ [does] a blessing"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963A>/H9023', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["voice/ his","voice/ its"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4924A}/[H8080]', 'inflected', 'heb', 'מַשְׁמָן', '["mashmân"]', '["away from/ [the] fatness<es> of"]', '["n-m"]', 'fat, i.e. (literally and abstractly) fatness; but usually (figuratively and concretely) a rich dish, a fertile field, a robust man fat (one, -ness, -test, -test place).', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4186}/H9021/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["dwelling/ your","seat/ your"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2919}/[H2926]', 'inflected', 'heb', 'טַל', '["ṭal"]', '["and/ away from/ [the] dew of"]', '["n-m"]', 'dew (as covering vegetation) dew.', 'from 2926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2719}/H9021/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["sword/ your","tool/ your"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7300}/[H7300]', 'lemma', 'heb', 'רוּד', '["rûwd"]', '["I am restless","it has roamed","we have roamed","you will be restless"]', '["v"]', 'to tramp about, i.e. ramble (free or disconsolate) have the dominion, be lord, mourn, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6561}/[H6561]', 'inflected', 'heb', 'פָּרַק', '["pâraq"]', '["and/ they tore off from themselves","and/ you will tear off"]', '["v"]', 'to break off or crunch; figuratively, to deliver break (off), deliver, redeem, rend (in pieces), tear in pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5923}/H9023/[H5953]', 'inflected', 'heb', 'עֹל', '["ʻôl"]', '["yoke/ his","yoke/ its"]', '["n-m"]', 'a yoke (as imposed on the neck), literally or figuratively yoke.', 'or עוֹל; from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6677A}/H9021/[H6696]', 'inflected', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["neck/ your"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7852}/[H7852]', 'inflected', 'heb', 'שָׂטַם', '["sâṭam"]', '["and/ he bore a grudge against"]', '["v"]', 'properly, to lurk for, i.e. persecute hate, oppose self against.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1293}/[H1288]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["<the>/ blessing","[is] the/ blessing","the/ blessing","the/ blessings"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0060}/[H56]', 'lemma', 'heb', 'אֵבֶל', '["ʼêbel"]', '["[is] mourning","[the] mourning of","mourning"]', '["n-m"]', 'lamentation mourning.', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2026}/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["and/ I will kill","and/ kill","and/ they killed"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5162G}/[H5162]', 'lemma', 'heb', 'נָחַם', '["nâcham"]', '["I will ease myself","[are] comforters of","[is] comforting himself","a comforter","comfort","comforters","he had compassion","he has comforted","he has compassion","he was comforted","he will comfort","he will have compassion","it had compassion","it has been comforted","someone comforts","to be comforted","you will be comforted"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2026}/H9031/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["by/ killing/ you","to/ kill/ you"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6965B}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ I will arise","and/ arise","and/ rise up","for/ someone may arise","so/ let us arise"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2771A}/H9011/[H2787]', 'inflected', 'heb', 'חָרָן', '["Chârân"]', '["Haran/ towards"]', '["n-pr-m n-pr-loc"]', 'Charan, the name of a man and also of a place Haran.', 'from 2787; parched;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725I}/[H7725]', 'lemma', 'heb', 'שׁוּב', '["shûwb"]', '["I will turn","[is] turning","[who] turns back","certainly [if] <to turn back>","does anyone turn away","has it turned away","he has turned away","he has turned back","he may turn","he return","he returned","he turned away","he will turn back","it has turned away","it has turned back","it turned back","it turns away","it will turn back","let it turn back","may it turn back","they have returned","they have turned away","they turn away","they turned back","turn","turn away","turn back","turns back","will you turn back","you have turned back","you must return","you turn away","you turned back","you will turn","you will turn away"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2534}/[H3179]', 'lemma', 'heb', 'חֵמָה', '["chêmâh"]', '["[is the] rage of","[is the] venom of","[is] [the] anger of","[the] anger of","[the] rage of","[the] venom of","anger<s>","fever","rage","rage<s>","venom"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639G}/[H599]', 'lemma', 'heb', 'אַף', '["ʼaph"]', '["[the] anger of","anger","anger<s>"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7911}/[H7911]', 'inflected', 'heb', 'שָׁכַח', '["shâkach"]', '["and/ [will be] forgotten","and/ he has forgotten","and/ he will forget","and/ it has forgotten","and/ it will be forgotten","and/ they forgot","and/ you forgot","and/ you have forgotten","and/ you will forget"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947J}/H9031/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ I will fetch/ you"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7921A}/[H7921]', 'lemma', 'heb', 'שָׁכֹל', '["shâkôl"]', '["I have been bereaved","I have made childless","[which] miscarry","it has bereaved","it has made childless","it miscarries","it will make childless","it will prove barren","miscarrying","she will become childless","they have miscarried","will I be bereaved","you are making childless","you will bereave"]', '["v"]', 'properly, to miscarry, i.e. suffer abortion; by analogy, to bereave (literally or figuratively) bereave (of children), barren, cast calf (fruit, young), be (make) childless, deprive, destroy, × expect, lose children, miscarry, rob of children, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8147}/H9026/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["both of/ you"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6973}/[H6962]', 'lemma', 'heb', 'קוּץ', '["qûwts"]', '["I loathe","[are] feeling dread","it loathes","you loath"]', '["v"]', 'to be (causatively, make) disgusted or anxious abhor, be distressed, be grieved, loathe, vex, be weary.', 'a primitive root (identical with through the idea of severing oneself from (compare 6962));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2416E}/H9020/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["<in>/ life/ my","in/ life/ my"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440I}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<from>/ because","<from>/ because of","[away] from/ before"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0428}/[H411]', 'inflected', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["[is] like/ these","like/ these","like/ these [things]"]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6680}/H9033/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["and/ he commanded/ him","and/ he commissioned/ him","and/ he has appointed/ him","and/ she commanded/ him"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6307>/H9011', 'opaque', 'heb', 'פַּדָּן', '["Paddân"]', '["Paddan/ towards"]', '["n-pr-loc"]', 'Paddan or Paddan-Aram, a region of Syria Padan, Padan-aram.', 'from an unused root meaning to extend; a plateau; or פַּדַּן אֲרָם; from the same and 758; the table-land of Aram;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004M}/H9011/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[the] house of/ towards"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3947G}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ [one who] takes","and/ acquire","and/ fetch","and/ let us get","and/ let us take","and/ take","and/ take [it]","and/ they may take","and/ we will get","and/ we will take","so/ I may take [him] away","so/ they may take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0410G}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["and/ God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6509}/H9031/[H6509]', 'inflected', 'heb', 'פָּרָה', '["pârâh"]', '["and/ may he make fruitful/ you"]', '["v"]', 'to bear fruit (literally or figuratively) bear, bring forth (fruit), (be, cause to be, make) fruitful, grow, increase.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7235A}/H9031/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["and/ may he multiply/ you"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6951}/[H6950]', 'inflected', 'heb', 'קָהָל', '["qâhâl"]', '["<into>/ a company of","for the/ assembly","to/ [the] assembly"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3423H}/H9031/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["to/ take possession of/ you"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3947I}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["to/ take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1288}/H9043/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["when/ blessed/ he"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8085H}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ I listened","and/ he had listened","and/ he listened","and/ they listened","and/ they obeyed","and/ we have listened","and/ we have obeyed","and/ you have listened","and/ you will hear","and/ you will listen","and/ you will obey"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4258G}/[H4257]', 'lemma', 'heb', 'מַחֲלַת', '["Machălath"]', '["Mahalath"]', '["n-pr-f"]', 'Machalath, the name of an Ishmaelitess and of an Israelitess Mahalath.', 'the same as 4257; sickness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0802H}\/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["<into>/ a wife","<into>/ wives","to/ a wife"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318I}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ he went out","and/ it goes out","and/ it went out","and/ it will go out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0884}/[H875]', 'inflected', 'heb', 'בְּאֵר שֶׁבַע', '["Bᵉʼêr Shebaʻ"]', '["from/ Beer"]', '["n-pr-loc"]', 'Beer-Sheba, a place in Palestine Beer-shebah.', 'from 875 and 7651 (in the sense of 7650); well of an oath;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6293}/[H6293]', 'inflected', 'heb', 'פָּגַע', '["pâgaʻ"]', '["and/ he fell","and/ he reached","and/ it touches","and/ they met","and/ you will meet"]', '["v"]', 'to impinge, by accident or violence, or (figuratively) by importunity come (betwixt), cause to entreat, fall (upon), make intercession, intercessor, intreat, lay, light (upon), meet (together), pray, reach, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935K}/[H935]', 'lemma', 'heb', 'בּוֹא', '["bôwʼ"]', '["[the] going of","it had gone","it will go","went"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0068G}/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["from/ stone[s]","one of/ [the] stones of"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4763}/H9023/[H4761]', 'inflected', 'heb', 'מְרַאֲשָׁה', '["mᵉraʼăshâh"]', '["[is the] place of head/ his","[the] place of head/ his","[the] place of head/ its","[was the] place of head/ his","[was] [the] place of head/ his"]', '["n-f"]', 'properly, a headpiece, i.e. (plural for adverbial) at (or as) the head-rest (or pillow) bolster, head, pillow. Compare 4772.', 'formed like 4761;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7901H}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ he lay down","and/ he will lie down"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2492B}/[H2492]', 'inflected', 'heb', 'חָלַם', '["châlam"]', '["and/ he dreamed","and/ they dreamed"]', '["v"]', 'properly, to bind firmly, i.e. (by implication) to be (causatively to make) plump; also (through the figurative sense of dumbness) to dream (cause to) dream(-er), be in good liking, recover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5551}/[H5549]', 'lemma', 'heb', 'סֻלָּם', '["çullâm"]', '["a stairway"]', '["n-m"]', 'a stair-case ladder.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3381}/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["and/ I may bring down","and/ [is] bringing down","and/ [was] going down","and/ [were] going down","and/ go down","and/ it may run down","and/ take down","so/ I may bring down","so/ he may come down","so/ they may run down","so/ you may come down"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6555}/[H6555]', 'inflected', 'heb', 'פָּרַץ', '["pârats"]', '["and/ he distributed","and/ he increased","and/ he made a breach","and/ he made a breach in","and/ he urged","and/ it broke out","and/ it has increased","and/ it will break down","and/ they urged","and/ you will spread out"]', '["v"]', 'to break out (in many applications, direct and indirect, literal and figurative) × abroad, (make a) breach, break (away, down, -er, forth, in, up), burst out, come (spread) abroad, compel, disperse, grow, increase, open, press, scatter, urge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3220H>/H9011', 'opaque', 'heb', 'יָם', '["yâm"]', '["[will be] west/ -ward","west-/ -ward","west/ -ward"]', '["n-m"]', 'a sea (as breaking in noisy surf) or large body of water; specifically (with the article), the Mediterranean Sea; sometimes a large river, or an artifical basin; locally, the west, or (rarely) the south sea (× -faring man, (-shore)), south, west (-ern, side, -ward).', 'from an unused root meaning to roar;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6828G}/H9011/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["and/ north/ -ward"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2233H}/H9021/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ among/ offspring/ your","and/ by/ offspring/ your","and/ to/ offspring/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8104H}/H9031/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ I will protect/ you"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725G}/H9031/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I will bring back/ you","and/ I will turn around/ you","and/ I will turn back/ you","and/ he will make return/ you"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800A}/H9031/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["I will abandon/ you","I will leave/ you","[those who] forsake/ you","he will forsake/ you","they leave/ you"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8142}/H9023/[H3462]', 'inflected', 'heb', 'שֵׁנָה', '["shênâh"]', '["from/ sleep/ his"]', '["n-f"]', 'sleep sleep.', 'or שֵׁנָא; (Psalm 127:2), from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0403}/[H3559]', 'lemma', 'heb', 'אָכֵן', '["ʼâkên"]', '["nevertheless","truly"]', '["adv"]', 'firmly; figuratively, surely; also (adversative) but but, certainly, nevertheless, surely, truly, verily.', 'from 3559 (compare 3651);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3372H}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["and/ did you fear?","and/ he was afraid","and/ it feared","and/ they feared","and/ they had feared","and/ they were afraid","and/ they will fear","and/ you will fear"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3372H}/[H3372]', 'lemma', 'heb', 'יָרֵא', '["yârêʼ"]', '["I fear","[is] awesome","[is] feared","[is] to be feared","[who is] awesome of","[will be] awesome","awesome","awesome [deeds]","awesome of","do you fear","fear","has he feared","let them fear","let us fear","they fear","they feared","they had feared","they have feared","to fear","we fear","will I be afraid","you fear","you may be feared","you may fear","you must fear","you will fear"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0068G}/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["<the>/ stone","<the>/ stone<s>","[are] the/ stones","the/ stone","the/ stone<s>","the/ stones"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4676}/[H5324]', 'lemma', 'heb', 'מַצֵּבָה', '["matstsêbâh"]', '["[the] sacred pillar of","[the] sacred pillars of","[will be] a pillar","a pillar","a sacred pillar","pillar[s]","sacred pillars"]', '["n-f"]', 'something stationed, i.e. a column or (memorial stone); by analogy, an idol garrison, (standing) image, pillar.', 'feminine (causatively) participle of 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3332G}/[H3332]', 'inflected', 'heb', 'יָצַק', '["yâtsaq"]', '["and/ he poured","and/ he poured [it]","and/ he will pour","and/ he will pour [it]","and/ it flowed","and/ they poured [it] out","and/ you will pour","and/ you will pour [it]","and/ you will pour out"]', '["v"]', 'properly, to pour out (transitive or intransitive); by implication, to melt or cast as metal; by extension, to place firmly, to stiffen or grow hard cast, cleave fast, be (as) firm, grow, be hard, lay out, molten, overflow, pour (out), run out, set down, stedfast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8081}/[H8080]', 'lemma', 'heb', 'שֶׁמֶן', '["shemen"]', '["[is] [the] oil of","[is] oil","[the] oil of","fat things","fatness","fatness<es>","oil","oil of","oils","olive"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218I>/H9024', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["top/ its"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0199}/[H194]', 'inflected', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["and/ but"]', '["adv"]', 'however or on the contrary as for, but, howbeit, in very deed, surely, truly, wherefore.', 'apparently a variation of 194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3870H}/[H3869]', 'lemma', 'heb', 'לוּז', '["Lûwz"]', '["[was] Luz"]', '["n-pr-loc"]', 'Luz, the name of two places in Palestine Luz.', 'probably from 3869 (as growing there);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7223G}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["to the/ former [time]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5087}/[H5087]', 'inflected', 'heb', 'נָדַר', '["nâdar"]', '["and/ he vowed","and/ it vowed","and/ she vowed","and/ they vowed","and/ they will vow"]', '["v"]', 'to promise (pos., to do or give something to God) (make a) vow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5088}/[H5087]', 'lemma', 'heb', 'נֶדֶר', '["neder"]', '["[is] a vow","[the] vow of","[the] vows","a vow","a vow of","vow","vows"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8104H}/H9030/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ he will protect/ me"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3847}/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["to/ clothe","to/ wear"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0068G}/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["and/ the/ stone","and/ the/ stones"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6237}/[H6238]', 'lemma', 'heb', 'עָשַׂר', '["ʻâsar"]', '["fully <tithe>","he will take a tenth","you will tithe"]', '["v"]', 'to tithe, i.e. to take or give a tenth × surely, give (take) the tenth, (have, take) tithe(-ing, -s), × truly.', 'a primitive root (identical with 6238); to accumulate; but used only as denominative from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6237}/H9033/[H6238]', 'inflected', 'heb', 'עָשַׂר', '["ʻâsar"]', '["I will tithe/ it"]', '["v"]', 'to tithe, i.e. to take or give a tenth × surely, give (take) the tenth, (have, take) tithe(-ing, -s), × truly.', 'a primitive root (identical with 6238); to accumulate; but used only as denominative from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375T}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ he lifted up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1980H}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ I will come","and/ he came","and/ he went","and/ they went","and/ they will come","and/ you came","and/ you will come"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5739}/[H5737]', 'lemma', 'heb', 'עֵדֶר', '["ʻêder"]', '["[the] flock of","[the] flocks","[the] flocks of","a herd","flock[s]","flocks","flocks of","herd","herds"]', '["n-m"]', 'an arrangement, i.e. muster (of animals) drove, flock, herd.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5739}/[H5737]', 'inflected', 'heb', 'עֵדֶר', '["ʻêder"]', '["[is] the/ flock","the/ flocks","the/ herds"]', '["n-m"]', 'an arrangement, i.e. muster (of animals) drove, flock, herd.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310G}/[H6284]', 'lemma', 'heb', 'פֶּה', '["peh"]', '["[the] mouth","[the] mouth of","a mouth","mouth"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1556}/[H1556]', 'inflected', 'heb', 'גָּלַל', '["gâlal"]', '["and/ he rolled","and/ people will roll","and/ they rolled","and/ they will be rolled up"]', '["v"]', 'to roll (literally or figuratively) commit, remove, roll (away, down, together), run down, seek occasion, trust, wallow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4725}/H9024/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["to/ place/ its"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0370}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["from/ whence?","from/ where","from/ where?"]', '["adv"]', 'where? (only in connection with prepositional prefix, whence) whence, where.', 'probably identical with 369 in the sense of query (compare 336)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0859D}/[H859]', 'lemma', 'heb', 'אַתָּה', '["ʼattâh"]', '["O you","[are] you","[are] you?","[will] you","you"]', '["p"]', 'thou and thee, or (plural) ye and you thee, thou, ye, you.', 'or (shortened); אַתָּ; or אַת; feminine (irregular) sometimes אַתִּי; plural masculine אַתֶּם; feminine אַתֶּן; or אַתֵּנָהlemma אתֵּנָה missing vowel, corrected to אַתֵּנָה; or אַתֵּנָּה; a primitive pronoun of the second person;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3045}/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["¿/ do I know","¿/ do you know","¿/ really <to know>","¿/ will it be known"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7965I}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["¿/ [does] health","¿/ [does] peace","¿/ health","¿/ peace"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965I}/[H7999]', 'lemma', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["[are] safety","[does] peace?","[is] health","[the] welfare of","[the] well-being of","health","peace","safety","well-being"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7354}/[H7353]', 'lemma', 'heb', 'רָחֵל', '["Râchêl"]', '["Rachel","[was] Rachel"]', '["n-pr-f"]', 'Rachel, a wife of Jacob Rachel.', 'the same as 7353;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6256}/[H5703]', 'lemma', 'heb', 'עֵת', '["ʻêth"]', '["[is] a time","[is] a time of","[is] an appropriate time","[it is] [the] time","[the] time","[the] time of","[was] a time of","[will be] a time","a time","a time of","an appropriate time","time","times"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0622}/[H622]', 'lemma', 'heb', 'אָסַף', '["ʼâçaph"]', '["I have gathered","I have withdrawn","I will gather","[am] about to be gathered","[are] being removed","[the] being gathered of","[those] gathered of","[was] receiving","[were] gathering","[who] they were gathered","a rearguard","certainly <to be gathered>","gather","gather up","gather yourself","gather yourselves","gathered","gathering","has he gathered","he gathered","he has removed","he is removed","he was gathered","he will be gathered","he will be removed","he will deliver","he will gather","it will be gathered","it will be removed","it will gather","let it be gathered","remove","she will be received","surely <gather>","they gathered","they had gathered","they have gathered","they were gathered","they will be gathered","they will be removed","utterly <destroy>","was received","we will gather","will it be gathered","withdraw","you remove","you will be gathered","you will gather","you withdraw","you withdrew"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4735}/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["the/ livestock"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7354}/[H7353]', 'inflected', 'heb', 'רָחֵל', '["Râchêl"]', '["and/ Rachel"]', '["n-pr-f"]', 'Rachel, a wife of Jacob Rachel.', 'the same as 7353;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0001G}/H9024/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["[belonged] to/ father/ her","to/ father/ her"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7354}/[H7353]', 'inflected', 'heb', 'רָחֵל', '["Râchêl"]', '["<to>/ Rachel","to/ Rachel"]', '["n-pr-f"]', 'Rachel, a wife of Jacob Rachel.', 'the same as 7353;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8088B}/[H8085]', 'lemma', 'heb', 'שֵׁמַע', '["shêmaʻ"]', '["[the] report of","a report","a report of"]', '["n-m"]', 'something heard, i.e. a sound, rumor, announcement; abstractly, audience bruit, fame, hear(-ing), loud, report, speech, tidings.', 'from 8085;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2263}/[H2263]', 'inflected', 'heb', 'חָבַק', '["châbaq"]', '["and/ he embraced"]', '["v"]', 'to clasp (the hands or in embrace) embrace, fold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0935P}/H9033/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ I will bring/ him","and/ I will take/ him","and/ he brought/ him","and/ he brought/ it","and/ it brought/ it","and/ she brought/ him","and/ she took/ him","and/ they brought/ him","and/ they brought/ it","and/ they took/ him","and/ you will bring/ him"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3837A}/[H3836]', 'inflected', 'heb', 'לָבָן', '["Lâbân"]', '["[belonged] to/ Laban","to/ Laban"]', '["n-pr-m n-pr-loc"]', 'Laban, a Mesopotamian; also a place in the Desert Laban.', 'the same as 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6106G}/H9020/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["[are] bone/ my","bone/ my","bone[s]/ my","bones/ my"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1320}/H9020/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["and/ flesh/ my"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2320G}/[H2318]', 'lemma', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["[is] [the] month of","[the] month of","[the] months of","[was the] month","[was] [the] month of","a month","a month of","month","month[s]","months"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251H}/H9020/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["relative/ my","relatives/ my"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5647G}/H9030/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ you will serve/ me"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2600}/[H2580]', 'lemma', 'heb', 'חִנָּם', '["chinnâm"]', '["for nothing","in vain","without cause","without paying"]', '["adv"]', 'gratis, i.e. devoid of cost, reason or advantage without a cause (cost, wages), causeless, to cost nothing, free(-ly), innocent, for nothing (nought, in vain.', 'from 2580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5046}/H9012/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["tell/ !"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4909}/H9021/[H7936]', 'inflected', 'heb', 'מַשְׂכֹּרֶת', '["maskôreth"]', '["[is] wage[s]/ your"]', '["n-f"]', 'wages or a reward reward, wages.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3837A}/[H3836]', 'inflected', 'heb', 'לָבָן', '["Lâbân"]', '["and/ [belonged] to/ Laban"]', '["n-pr-m n-pr-loc"]', 'Laban, a Mesopotamian; also a place in the Desert Laban.', 'the same as 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3812}/[H3811]', 'lemma', 'heb', 'לֵאָה', '["Lêʼâh"]', '["Leah","[was] Leah"]', '["n-pr-f"]', 'Leah, a wife of Jacob Leah.', 'from 3811; weary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5869A}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ [are] eyes","and/ [the] eye of","and/ [the] eyes of","and/ an eye","and/ eyes"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8389}/[H8388]', 'lemma', 'heb', 'תֹּאַר', '["tôʼar"]', '["appearance","form","shape"]', '["n-m"]', 'outline, i.e. figure or appearance beautiful, × comely, countenance, fair, × favoured, form, × goodly, × resemble, visage.', 'from 8388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3303}/[H3302]', 'inflected', 'heb', 'יָפֶה', '["yâpheh"]', '["and/ beautiful of","and/ good looking of","and/ handsome of"]', '["a"]', 'beautiful (literally or figuratively) beautiful, beauty, comely, fair(-est, one), goodly, pleasant, well.', 'from 3302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7354}/[H7353]', 'inflected', 'heb', 'רָחֵל', '["Râchêl"]', '["for/ Rachel","on/ Rachel"]', '["n-pr-f"]', 'Rachel, a wife of Jacob Rachel.', 'the same as 7353;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414G}/H9040/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["gave/ I","to give/ I"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5414G}/H9040/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["more than/ to give/ I","than/ to give/ I"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0376G>', 'inflected', 'heb', 'לאיש', '["La./''ish","la./''Ish","le./''Ish","le./''ish"]', '["<into>/ a man","<into>/ a person","<to> the/ man","<to> the/ person","[belong] to/ a man","[belongs] to <the>/ person","[belongs] to the/ man","[belongs] to the/ person","[belongs] to/ a person","[belongs] to/ a person of","[is] for/ a person","and/ a person","for the/ man","for/ a man","for/ a person","for/ a person of","into/ a man","of/ a man","of/ a person","of/ a person of","to <the>/ person","to the/ man","to the/ person","to/ [the] man","to/ [the] man of","to/ a husband","to/ a man","to/ a person"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5647G}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ he served","and/ they compelled to labor","and/ they have served","and/ they served","and/ they will serve","and/ they will work","and/ we have served","and/ you will serve"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3117G>', 'inflected', 'heb', 'כימים', '["Ki./mei","ka/i.Yom","ka/i.ya.Mim","ke./Yom","ke./ya.Mim","khai./Yom","khai./ya.Mim","khe./Yom","khi./Mei","ki./Mei","ki./Mot","ki./mei"]', '["[are] like/ a day of","[will be] like/ [the] days of","[will be] like/ a day","about/ a day","according to/ [the] days","according to/ [the] days of","as the/ day","as the/ days","like <the>/ this day","like the/ day","like the/ days","like/ [the] day","like/ [the] day of","like/ [the] days","like/ [the] days of","like/ days","like/ days of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0160}/H9023/[H158]', 'inflected', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["in/ love/ his"]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/H9020', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["[are] days/ my","days/ my"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2153>', 'opaque', 'heb', 'זִלְפָּה', '["Zilpâh"]', '["Zilpah"]', '["n-pr-f"]', 'Zilpah, Leah''s maid Zilpah.', '; from an unused root apparently meaning to trickle, as myrrh; fragrant dropping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8198>/H9023', 'opaque', 'heb', 'שִׁפְחָה', '["shiphchâh"]', '["female slave/ his","maidservant/ his","maidservants/ his"]', '["n-f"]', 'a female slave (as a member of the household) (bond-, hand-) maid(-en, -servant), wench, bondwoman, womanservant.', 'feminine from an unused root meaning to spread out (as a family; see 4940);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3812}/[H3811]', 'inflected', 'heb', 'לֵאָה', '["Lêʼâh"]', '["to/ Leah"]', '["n-pr-f"]', 'Leah, a wife of Jacob Leah.', 'from 3811; weary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7411B}/H9030/[H7411]', 'inflected', 'heb', 'רָמָה', '["râmâh"]', '["have you deceived/ me","he betrayed/ me","they deceived/ me"]', '["v"]', 'to hurl; specifically, to shoot; figuratively, to delude or betray (as if causing to fall) beguile, betray, (bow-) man, carry, deceive, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4725}/H9025/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["in/ place/ our"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5414O}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["to/ give"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7620H}/[H7650]', 'lemma', 'heb', 'שָׁבוּעַ', '["shâbûwaʻ"]', '["[the] week of","[the] weeks of","two weeks","weeks"]', '["n-m"]', 'literally, sevened, i.e. a week (specifically, of years) seven, week.', 'or שָׁבֻעַ; also (feminine) שְׁבֻעָה; properly, passive participle of 7650 as a denominative of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414O}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will give","and/ he gave","and/ he has given","and/ they gave","and/ we will give","so/ let us give"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5656G}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["for/ [the] service","in/ [the] work of","with/ labor"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1090A}/[H1089]', 'lemma', 'heb', 'בִּלְהָה', '["Bilhâh"]', '["Bilhah"]', '["n-pr-f n-pr-loc"]', 'Bilhah, the name of one of Jacob''s concubines; also of a place in Palestine Bilhah.', 'from 1089; timid;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H8198>', 'inflected', 'heb', 'לשפחה', '["le./shif.Chah"]', '["to/ [be] a maidservant","to/ a maid"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3812}/[H3811]', 'inflected', 'heb', 'לֵאָה', '["Lêʼâh"]', '["more than/ Leah"]', '["n-pr-f"]', 'Leah, a wife of Jacob Leah.', 'from 3811; weary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7358}/H9024/[H7355]', 'inflected', 'heb', 'רֶחֶם', '["rechem"]', '["womb/ her"]', '["n-m"]', 'the womb matrix, womb.', 'from 7355; (compare 7356)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7205}/[H7200]', 'lemma', 'heb', 'רְאוּבֵן', '["Rᵉʼûwbên"]', '["O Reuben","Reuben"]', '["n-pr-m"]', 'Reuben, a son of Jacob Reuben.', 'from the imperative of 7200 and 1121; see ye a son;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6040}/H9020/[H6031]', 'inflected', 'heb', 'עֳנִי', '["ʻŏnîy"]', '["in/ affliction/ my","on/ affliction/ my"]', '["n-m"]', 'depression, i.e. misery afflicted(-ion), trouble.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157G}/H9030/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["[those who] love/ me","he will love/ me","lovers/ my","you love/ me"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0376H>/H9020', 'opaque', 'heb', 'אִישׁ', '["ʼîysh"]', '["husband/ my"]', '["n-m"]', 'a man as an individual or a male person; often used as an adjunct to a more definite term (and in such cases frequently not expressed in translation) also, another, any (man), a certain, champion, consent, each, every (one), fellow, (foot-, husband-) man, (good-, great, mighty) man, he, high (degree), him (that is), husband, man(-kind), none, one, people, person, steward, what (man) soever, whoso(-ever), worthy. Compare 802.', 'contracted for 582 (or perhaps rather from an unused root meaning to be extant);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8095G}/[H8085]', 'lemma', 'heb', 'שִׁמְעוֹן', '["Shimʻôwn"]', '["Simeon"]', '["n-pr-m"]', 'Shimon, one of Jacob''s sons, also the tribe descended from him Simeon.', 'from 8085; hearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3867A}/[H3867]', 'lemma', 'heb', 'לָוָה', '["lâvâh"]', '["he will join himself","it has joined itself"]', '["v"]', 'properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3878}/[H3867]', 'lemma', 'heb', 'לֵוִי', '["Lêvîy"]', '["Levi"]', '["n-pr-m"]', 'Levi, a son of Jacob Levi. See also 3879, 3881.', 'from 3867; attached;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3034}/[H3027]', 'lemma', 'heb', 'יָדָה', '["yâdâh"]', '["I will confess","I will give thanks to","I will praise","[are] giving thanks","[they were] confessing","give thanks","give thanks to","he gave thanks","let them give thanks","let them give thanks to","shoot","they will give thanks","to give thanks","we give thanks","we will give thanks","we will praise","will he give thanks"]', '["v"]', 'physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving).', 'a primitive root; used only as denominative from 3027; literally, to use (i.e. hold out) the hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3063G}/[H3034]', 'lemma', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["Judah","O Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5975G}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ I had set up","and/ I stood","and/ I will stand","and/ he appointed","and/ he made stand","and/ he rose up","and/ he set","and/ he set up","and/ he stationed","and/ he stood","and/ he stood up","and/ he stopped","and/ he will make stand","and/ he will stand","and/ he will stand firm","and/ he will station","and/ it endures","and/ it stood","and/ it stood forth","and/ it stood still","and/ it stopped","and/ it took its stand","and/ she has stayed","and/ she stood","and/ she stopped","and/ she will stand","and/ they erected","and/ they made stand","and/ they remained","and/ they set up","and/ they stood","and/ they stood still","and/ they stopped","and/ they took their stand","and/ they will stand","and/ we stationed","and/ we will remain","and/ you will make stand","and/ you will stand"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0269}/H9024/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["of/ sister/ her"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0518I}/[H518]', 'inflected', 'heb', 'אִם', '["ʼim"]', '["and/ <if>?","and/ if","and/ or?"]', '["prt"]', 'used very widely as demonstrative, lo!; interrogative, whether?; or conditional, if, although; also Oh that!, when; hence, as a negative, not (and, can-, doubtless, if, that) (not), + but, either, + except, + more(-over if, than), neither, nevertheless, nor, oh that, or, + save (only, -ing), seeing, since, sith, + surely (no more, none, not), though, + of a truth, + unless, + verily, when, whereas, whether, while, + yet.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H8478H}/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["¿/ in place of"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4513}/[H4513]', 'lemma', 'heb', 'מָנַע', '["mânaʻ"]', '["I restrained","I will withhold","I withheld","I withheld [them]","[one who] withholds","he has withheld","he withholds","let yourself be restrained","restrain","they have withheld","you have withheld","you withheld","you withhold","you withhold [them]"]', '["v"]', 'to debar (negatively or positively) from benefit or injury deny, keep (back), refrain, restrain, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4480A}/H9032/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["from/ you","more than/ you"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990H>', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["[the] belly","[the] womb","a belly"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0519}/H9020/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["maidservant/ my"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1290}/H9020/[H1288]', 'inflected', 'heb', 'בֶּרֶךְ', '["berek"]', '["knees/ my"]', '["n-f"]', 'a knee knee.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1129}/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["and/ [the] builders of","and/ [were] building","and/ build","and/ let him build","and/ rebuild","so/ I may be built up","so/ I may build","so/ he may rebuild","so/ we may rebuild"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1777}/H9030/[H1777]', 'inflected', 'heb', 'דִּין', '["dîyn"]', '["he has vindicated/ me","you will vindicate/ me"]', '["v"]', 'to rule; by implication to judge (as umpire); also to strive (as at law) contend contend execute (judgment) judge minister judgment plead (the cause) at strife strive.', 'or (Genesis 6:3) דּוּן; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1835H}/[H1777]', 'lemma', 'heb', 'דָּן', '["Dân"]', '["Dan"]', '["n-pr-m"]', 'Dan, one of the sons of Jacob; also the tribe descended from him, and its territory; likewise a place in Palestine colonized by them Daniel', 'from 1777; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5319}/[H6617]', 'lemma', 'heb', 'נַפְתּוּל', '["naphtûwl"]', '["wrestling<s> of"]', '["n-m"]', 'properly, wrestled; but used (in the plural) transitively, a struggle wrestling.', 'from 6617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6617}/[H6617]', 'lemma', 'heb', 'פָּתַל', '["pâthal"]', '["I have wrestled","[is] a twisted [thing]","tortuous [people]","you show yourself twisted"]', '["v"]', 'to twine, i.e. (literally) to struggle or (figuratively) be (morally) tortuous (shew self) froward, shew self unsavoury, wrestle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5321G}/[H6617]', 'lemma', 'heb', 'נַפְתָּלִי', '["Naphtâlîy"]', '["Naphtali"]', '["n-pr-m n-pr-loc"]', 'Naphtali, a son of Jacob, with the tribe descended from him, and its territory Naphtali.', 'from 6617; my wrestling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}//{H1409}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["it has come//good fortune"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1410G}/[H1464]', 'lemma', 'heb', 'גָּד', '["Gâd"]', '["Gad"]', '["n-pr-m"]', 'Gad, a son of Jacob, including his tribe and its territory; also a prophet Gad.', 'from 1464;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0837}/H9020/[H833]', 'inflected', 'heb', 'אֹשֶׁר', '["ʼôsher"]', '["in/ happiness/ my"]', '["n-m"]', 'happiness happy.', 'from 833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0833}/H9030/[H833]', 'inflected', 'heb', 'אָשַׁר', '["ʼâshar"]', '["they will call happy/ me"]', '["v"]', 'to be straight (used in the widest sense, especially to be level, right, happy); figuratively, to go forward, be honest, prosper (call, be) bless(-ed, happy), go, guide, lead, relieve.', 'or אָשֵׁר; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0836}/[H833]', 'lemma', 'heb', 'אָשֵׁר', '["ʼÂshêr"]', '["Asher"]', '["n-pr"]', 'Asher, a son of Jacob, and the tribe descended from him, with its territory; also a place in Palestine Asher', 'from 833, happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7105A}/[H7114]', 'lemma', 'heb', 'קָצִיר', '["qâtsîyr"]', '["[is] [the] harvest of","[the] harvest","[the] harvest of","a harvest","a harvest of","harvest"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2406>', 'opaque', 'heb', 'חִטָּה', '["chiṭṭâh"]', '["<of> wheat<s>","[the] wheat","wheat","wheat<s>"]', '["n-f"]', 'wheat, whether the grain or the plant wheat(-en).', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1736}/[H1731]', 'lemma', 'heb', 'דּוּדַי', '["dûwday"]', '["[the] mandrakes of","mandrakes"]', '["n-m"]', 'a boiler or basket; also the mandrake (as an aphrodisiac) basket, mandrake.', 'from 1731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1736}/[H1731]', 'inflected', 'heb', 'דּוּדַי', '["dûwday"]', '["some of/ [the] mandrakes of"]', '["n-m"]', 'a boiler or basket; also the mandrake (as an aphrodisiac) basket, mandrake.', 'from 1731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121A}/H9022/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["[is] son/ your","children/ your","son/ your","sons/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4592}/[H4591]', 'inflected', 'heb', 'מְעַט', '["mᵉʻaṭ"]', '["¿/ [is it too] small","¿/ [is it] small","¿/ [too] little","¿/ few","¿/ little","¿/ small"]', '["n-m"]', 'a little or few (often adverbial or comparative) almost (some, very) few(-er, -est), lightly, little (while), (very) small (matter, thing), some, soon, × very.', 'or מְעָט; from 4591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947G}/H9042/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["taking/ you"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3947G}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ to/ take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7936B}/[H3739]', 'lemma', 'heb', 'שָׂכַר', '["sâkar"]', '["[is] earning wages","[was] hired","certainly <to hire>","he has hired","he hired","hiring","they hire","they hire themselves out"]', '["v"]', 'to hire earn wages, hire (out self), reward, × surely.', 'or (by permutation) סָכַר; (Ezra 4:5), a primitive root (apparently akin (by prosthesis) to 3739 through the idea of temporary purchase; compare 7937);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7936B}/H9031/[H3739]', 'inflected', 'heb', 'שָׂכַר', '["sâkar"]', '["I have hired/ you"]', '["v"]', 'to hire earn wages, hire (out self), reward, × surely.', 'or (by permutation) סָכַר; (Ezra 4:5), a primitive root (apparently akin (by prosthesis) to 3739 through the idea of temporary purchase; compare 7937);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1736}/[H1731]', 'inflected', 'heb', 'דּוּדַי', '["dûwday"]', '["for/ [the] mandrakes of"]', '["n-m"]', 'a boiler or basket; also the mandrake (as an aphrodisiac) basket, mandrake.', 'from 1731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2549}/[H2568]', 'lemma', 'heb', 'חֲמִישִׁי', '["chămîyshîy"]', '["[the] fifth part of","a fifth","fifth"]', '["a"]', 'fifth; also a fifth fifth (part).', 'or חֲמִשִּׁי; ordinal from 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7939}/H9020/[H7936]', 'inflected', 'heb', 'שָׂכָר', '["sâkâr"]', '["reward/ my","wage[s]/ my"]', '["n-m"]', 'payment of contract; concretely, salary, fare, maintenance; by implication, compensation, benefit hire, price, reward(-ed), wages, worth.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0376H>/H9020', 'inflected', 'heb', 'לאישי', '["le./''i.Sh/i"]', '["for/ husband/ my","to/ husband/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3485G}/[H5375]', 'lemma', 'heb', 'יִשָּׂשכָר', '["Yissâˢkâr"]', '["Issachar"]', '["n-pr"]', 'Jissaskar, a son of Jacob Issachar.', '(strictly yis-saws-kawr''); from 5375 and 7939; he will bring a reward;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8345}/[H8337]', 'lemma', 'heb', 'שִׁשִּׁי', '["shishshîy"]', '["<the> sixth of","[the] sixth [part] of","sixth"]', '["n"]', 'sixth, ordinal or (feminine) fractional sixth (part).', 'from 8337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2064}/H9030/[H2064]', 'inflected', 'heb', 'זָבַד', '["zâbad"]', '["he has endowed/ me"]', '["v"]', 'to confer endure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2065}/[H2064]', 'lemma', 'heb', 'זֶבֶד', '["zebed"]', '["an endowment"]', '["n-m"]', 'a gift dowry.', 'from 2064;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2082}/H9030/[H2082]', 'inflected', 'heb', 'זָבַל', '["zâbal"]', '["he will honor/ me"]', '["v"]', 'to reside dwell with.', 'a primitive root; apparently properly, to inclose, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2074}/[H2082]', 'lemma', 'heb', 'זְבוּלוּן', '["Zᵉbûwlûwn"]', '["O Zebulun","Zebulun"]', '["n-pr-m n-pr-loc"]', 'Zebulon, a son of Jacob; also his territory and tribe Zebulun.', 'or זְבֻלוּן; or זְבוּלֻן; from 2082; habitation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1783}/[H1779]', 'lemma', 'heb', 'דִּינָה', '["Dîynâh"]', '["Dinah"]', '["n-pr-f"]', 'Dinah, the daughter of Jacob Dinah.', 'feminine of 1779; justice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2781}/H9020/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["disgrace/ my","reproach/ my"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3130G}/[H3254]', 'lemma', 'heb', 'יוֹסֵף', '["Yôwçêph"]', '["Joseph","[am] Joseph"]', '["n-pr-m"]', 'Joseph, the name of seven Israelites Joseph. Compare 3084.', 'future of 3254; let him add (or perhaps simply active participle adding);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3254H}/[H3254]', 'lemma', 'heb', 'יָסַף', '["yâçaph"]', '["I will add","I will increase","I will repeat","[are] increasing","add","added [things]","he added","he adds","he has added","he will add","he will increase","he will repeat","it adds","it increases","it was added","let him add","may he add","may they add","she increases","they increase","they will add","we have added","will anyone add","will he add","will he increase","you add","you have added","you must add","you will add"]', '["v"]', 'to add or augment (often adverbial, to continue to do a thing) add, × again, × any more, × cease, × come more, conceive again, continue, exceed, × further, × gather together, get more, give more-over, × henceforth, increase (more and more), join, × longer (bring, do, make, much, put), × (the, much, yet) more (and more), proceed (further), prolong, put, be (strong-) er, × yet, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4725}/H9020/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["own place/ my","place/ my"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0776G>/H9020', 'inflected', 'heb', 'ולארצי', '["u./le./''ar.Tz/i"]', '["and/ to/ land/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414G}/H9012/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["give/ !","put/ !"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3206}/H9020/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["children/ my"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5656G}/H9020/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["service/ my"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5172}/[H5172]', 'lemma', 'heb', 'נָחַשׁ', '["nâchash"]', '["I have learned by divination","he practices divination","indeed <divine>","they observed [the] signs","you will practice divination"]', '["v"]', 'properly, to hiss, i.e. whisper a (magic) spell; generally, to prognosticate × certainly, divine, enchanter, (use) × enchantment, learn by experience, × indeed, diligently observe.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1288}/H9030/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["and/ he has blessed/ me"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1558}/H9031/[H1556]', 'inflected', 'heb', 'גָּלָל', '["gâlâl"]', '["on/ account of/ you"]', '["n-m"]', 'a circumstance (as rolled around); only used adverbially, on account of because of, for (sake).', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5344A}/H9012/[H5344]', 'inflected', 'heb', 'נָקַב', '["nâqab"]', '["designate/ !"]', '["v"]', 'to puncture, literally (to perforate, with more or less violence) or figuratively (to specify, designate, libel) appoint, blaspheme, bore, curse, express, with holes, name, pierce, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5414N}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["so/ let me give [it]"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4735}/H9021/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["livestock/ your"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7230}/[H7231]', 'inflected', 'heb', 'רֹב', '["rôb"]', '["for/ abundance","for/ multitude","to/ [the] multitude of","to/ abundance","to/ multitude"]', '["n-m"]', 'abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age).', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7272}/H9020/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["for/ feet/ my","for/ foot/ my","to/ foot/ my"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4970>', 'opaque', 'heb', 'מָתַי', '["mâthay"]', '["when?"]', '["adv"]', 'properly, extent (of time); but used only adverbially (especially with other particle prefixes), when (either relative or interrogative) long, when.', 'from an unused root meaning to extend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004M}/H9020/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["for/ own household/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725J}/[H7725]', 'lemma', 'heb', 'שׁוּב', '["shûwb"]', '["I have returned","I returned","I will repeat","I will return","certainly [if] <to return>","go back","he will return","he will turn","he will turn back","it will return","return","they returned","turn back","will you return","you will return","you will turn"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6629G>/H9021', 'opaque', 'heb', 'צֹאן', '["tsôʼn"]', '["flock/ your","flock[s]/ your","sheep/ your"]', '["n-f"]', 'a collective name for a flock (of sheep or goats); also figuratively (of men) (small) cattle, flock ( -s), lamb ( -s), sheep(-cote, -fold, -shearer, -herds).', 'or צאוֹן; (Psalm 144:13), from an unused root meaning to migrate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104H}/[H8104]', 'lemma', 'heb', 'שָׁמַר', '["shâmar"]', '["I have guarded","I have watched","I will guard","I will keep","I will protect [it]","O watchman","[he is] keeping","[he is] protecting","[is] guarding","[is] keeping","[is] protecting","[is] watching over","[it was] kept","[one who] guards","[one who] keeps","[the] keeper","[the] keeper of","[the] keepers of","[the] protector of","[the] watchman","[the] watchmen of","[was] being kept","[were] [the] keepers of","[who] keep","[who] kept of","a watchman","did you guard","guard","guarding","he keeps","he kept [flocks]","he was kept","he will preserve","he will protect","he will watch over","it has kept","it will watch","keep","keeping","preserve","protect","take care","they are preserved","they have kept themselves","they will preserve","watching","watchmen","you watched","you will guard","you will keep"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5493G}/[H5493]', 'lemma', 'heb', 'סוּר', '["çûwr"]', '["I have turned aside","I removed","I removed [it]","I will put aside","I will remove","[he is] removing","[is] about to remove","[the] removing of","[when] it was abolished","[who] he has taken away","depart","did he remove","he had removed","he has removed","he has taken away","he removed","he turned aside","he will remove","it departed","it has departed","it is removed","it was removed","it will be removed","it will depart","let him remove","remove","they removed","they take away","they were removed","they will be removed","they will remove","to remove","turn away","you will remove"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7716}/[H7582]', 'lemma', 'heb', 'שֶׂה', '["seh"]', '["[is] sheep","[the] sheep of","a lamb","a sheep","an animal of","sheep"]', '["n-m"]', 'a member of a flock, i.e. a sheep or goat (lesser, small) cattle, ewe, goat, lamb, sheep. Compare 2089.', 'or שֵׂי; probably from 7582 through the idea of pushing out to graze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5348>', 'opaque', 'heb', 'נָקֹד', '["nâqôd"]', '["speckled","speckled [ones]"]', '["a"]', 'spotted speckled.', 'from an unused root meaning to mark (by puncturing or branding);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2921}/[H2921]', 'inflected', 'heb', 'טָלָא', '["ṭâlâʼ"]', '["and/ [the] spotted","and/ patched","and/ spotted","and/ spotted [ones]"]', '["v"]', 'properly, to cover with pieces; i.e. (by implication) to spot or variegate (as tapestry) clouted, with divers colours, spotted.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2345>', 'opaque', 'heb', 'חוּם', '["chûwm"]', '["dark","dark [one]"]', '["a"]', 'sunburnt or swarthy (blackish) brown.', 'from an unused root meaning to be warm, i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3775}/[H3532]', 'inflected', 'heb', 'כֶּשֶׂב', '["keseb"]', '["among the/ lambs","among the/ young rams"]', '["n-m"]', 'a young sheep lamb.', 'apparently by transposition for 3532;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5348>', 'inflected', 'heb', 'ונקד', '["ve./na.Kod"]', '["and/ [the] speckled"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5795}/[H5810]', 'inflected', 'heb', 'עֵז', '["ʻêz"]', '["among the/ goats","among the/ kids"]', '["n-f"]', 'a she-goat (as strong), but masculine in plural (which also is used elliptically for goat''s hair) (she) goat, kid.', 'from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6666}/H9020/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["righteousness/ my"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4279}/[H309]', 'lemma', 'heb', 'מָחָר', '["mâchâr"]', '["[is] tomorrow","[will be] tomorrow","in future time","tomorrow"]', '["n-m"]', 'properly, deferred, i.e. the morrow; usually (adverbially) tomorrow; indefinitely, hereafter time to come, tomorrow.', 'probably from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440L}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0369}/H9043/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["not [is]/ he","not [is]/ it","not [was]/ he","not/ he","not/ it","there not [is]/ it","there not [was]/ he","there not/ he"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2345>', 'inflected', 'heb', 'וחום', '["ve./Chum"]', '["and/ dark"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1589}/[H1589]', 'lemma', 'heb', 'גָּנַב', '["gânab"]', '["I was stolen","[is] stolen","[one] stolen of","[who] steal","certainly <to be stolen>","certainly <to steal>","did you steal","he will steal","it acts stealthily","it was brought secretly","it will be stolen","stealing","stolen","they had stolen","they have stolen","will they steal","will we steal","you will steal"]', '["v"]', 'to thieve (literally or figuratively); by implication, to deceive carry away, × indeed, secretly bring, steal (away), get by stealth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1697H}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["according to/ word/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H8495>', 'inflected', 'heb', 'התישים', '["ha./te.ya.Shim"]', '["the/ male goats"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6124}/[H6123]', 'inflected', 'heb', 'עָקֹד', '["ʻâqôd"]', '["<the>/ striped"]', '["a"]', 'striped (with bands) ring straked.', 'from 6123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2921}/[H2921]', 'inflected', 'heb', 'טָלָא', '["ṭâlâʼ"]', '["and/ <the>/ spotted"]', '["v"]', 'properly, to cover with pieces; i.e. (by implication) to spot or variegate (as tapestry) clouted, with divers colours, spotted.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5348>', 'inflected', 'heb', 'הנקדות', '["ha./ne.ku.Dot"]', '["<the>/ speckled"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3836}/[H3835]', 'lemma', 'heb', 'לָבָן', '["lâbân"]', '["[is] white","white"]', '["a"]', 'white white.', 'or (Genesis 49:12) לָבֵן; from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870L}/[H1869]', 'lemma', 'heb', 'דֶּרֶךְ', '["derek"]', '["[is] [the] way of","[is] [the] ways of","[is] a journey of","[the] road","[the] way","[the] way of","[was] a way","a journey","a journey of","a road","a way","way"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0996G}/H9033/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["[was] between/ it","between/ himself"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3498}/[H3498]', 'inflected', 'heb', 'יָתַר', '["yâthar"]', '["<the>/ [one who] remains","<the>/ remaining","<the>/ what is left over","the/ [ones who] remained","those/ [which] are left","those/ [who] remain","those/ [who] remained","which/ remain","which/ remain over","which/ remained","which/ remains","which/ were left","who/ remained"]', '["v"]', 'to jut over or exceed; by implication, to excel; (intransitively) to remain or be left; causatively to leave, cause to abound, preserve excel, leave (a remnant), left behind, too much, make plenteous, preserve, (be, let) remain(-der, -ing, -nant), reserve, residue, rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4731>', 'opaque', 'heb', 'מַקֵּל', '["maqqêl"]', '["a branch of","a staff of","branch[es] of","staffs"]', '["n-m"]', 'a shoot, i.e. stick (with leaves on, or for walking, striking, guiding, divining) rod, (hand-)staff.', 'or (feminine) מַקְּלָה; from an unused root meaning apparently to germinate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3839}/[H3835]', 'lemma', 'heb', 'לִבְנֶה', '["libneh"]', '["poplar"]', '["n-m"]', 'some sort of whitish tree, perhaps the storax poplar.', 'from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3892>', 'opaque', 'heb', 'לַח', '["lach"]', '["fresh","freshly cut","moist"]', '["a"]', 'fresh, i.e. unused or undried green, moist.', 'from an unused root meaning to be new;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3869>', 'inflected', 'heb', 'ולוז', '["ve./Luz"]', '["and/ almond"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6196}/[H6191]', 'inflected', 'heb', 'עַרְמוֹן', '["ʻarmôwn"]', '["and/ plane tree","and/ plane trees"]', '["n-m"]', 'the plane tree (from its smooth and shed bark) chestnut tree.', 'probably from 6191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6478}/[H6478]', 'inflected', 'heb', 'פָּצַל', '["pâtsal"]', '["and/ he stripped"]', '["v"]', 'to peel pill.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6479}/[H6478]', 'lemma', 'heb', 'פְּצָלָה', '["pᵉtsâlâh"]', '["strips"]', '["n-f"]', 'a peeling strake.', 'from 6478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4286}/[H2834]', 'lemma', 'heb', 'מַחְשֹׂף', '["machsôph"]', '["[the] peeling of"]', '["n-m"]', 'a peeling made appear.', 'from 2834;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3836}/[H3835]', 'inflected', 'heb', 'לָבָן', '["lâbân"]', '["the/ white [wood]"]', '["a"]', 'white white.', 'or (Genesis 49:12) לָבֵן; from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4731>', 'inflected', 'heb', 'המקלות', '["ha./mak.Lot","ha./mak.loT"]', '["the/ branches"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3322}/[H3322]', 'inflected', 'heb', 'יָצַג', '["yâtsag"]', '["and/ he placed","and/ they placed","and/ they set"]', '["v"]', 'to place permanently establish, leave, make, present, put, set, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6478}/[H6478]', 'lemma', 'heb', 'פָּצַל', '["pâtsal"]', '["he had stripped"]', '["v"]', 'to peel pill.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7298A>', 'inflected', 'heb', 'ברהטים', '["bo./ro.ha.Tim"]', '["in the/ drinking troughs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8268}/[H8248]', 'inflected', 'heb', 'שֹׁקֶת', '["shôqeth"]', '["in/ [the] watering channels of"]', '["n-f"]', 'a trough (for watering) trough.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3179}/[H3179]', 'inflected', 'heb', 'יָחַם', '["yâcham"]', '["and/ they mated"]', '["v"]', 'probably to be hot; figuratively, to conceive get heat, be hot, conceive, be warm.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0935G}/H9049/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ came/ they"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6124}/[H6123]', 'lemma', 'heb', 'עָקֹד', '["ʻâqôd"]', '["[are] striped","[the] striped","[were] striped","striped [ones]"]', '["a"]', 'striped (with bands) ring straked.', 'from 6123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3775}/[H3532]', 'inflected', 'heb', 'כֶּשֶׂב', '["keseb"]', '["and/ the/ lambs"]', '["n-m"]', 'a young sheep lamb.', 'apparently by transposition for 3532;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6629G>', 'inflected', 'heb', 'בצאן', '["ba./Tzon","be./Tzon","va./Tzon"]', '["<in> the/ flock","<on> the/ sheep","[is] with the/ flock","among/ [the] flock of","in the/ flock","on/ [the] sheep of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7896G}/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["and/ I will fix","and/ he made","and/ he put","and/ he set","and/ he will make [it]","and/ they have made","and/ you put"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896H}/H9038/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["he put/ them"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3179}/[H3179]', 'lemma', 'heb', 'יָחַם', '["yâcham"]', '["[the] being in heat of","mated"]', '["v"]', 'probably to be hot; figuratively, to conceive get heat, be hot, conceive, be warm.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7194}/[H7194]', 'inflected', 'heb', 'קָשַׁר', '["qâshar"]', '["<the>/ vigorous [female]","[are] the/ [ones who] conspired","those/ [who] had conspired"]', '["v"]', 'to tie, physically (gird, confine, compact) or mentally (in love, league) bind (up), (make a) conspire(-acy, -ator), join together, knit, stronger, work (treason).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3179}/H9034/[H3179]', 'inflected', 'heb', 'יָחַם', '["yâcham"]', '["to/ mate /her"]', '["v"]', 'probably to be hot; figuratively, to conceive get heat, be hot, conceive, be warm.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4731>', 'inflected', 'heb', 'במקלות', '["ba./ma.Kel","ba./mak.Lot"]', '["at the/ branches","with <the>/ sticks","with the/ stick"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5848C}/[H5848]', 'inflected', 'heb', 'עָטַף', '["ʻâṭaph"]', '["and/ when/ was feeble"]', '["v"]', 'to shroud, i.e. clothe (whether transitive or reflex.); hence (from the idea of darkness) to languish cover (over), fail, faint, feebler, hide self, be overwhelmed, swoon.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5848C}/[H5848]', 'inflected', 'heb', 'עָטַף', '["ʻâṭaph"]', '["the/ enfeebled ones","the/ ones enfeebled"]', '["v"]', 'to shroud, i.e. clothe (whether transitive or reflex.); hence (from the idea of darkness) to languish cover (over), fail, faint, feebler, hide self, be overwhelmed, swoon.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7194}/[H7194]', 'inflected', 'heb', 'קָשַׁר', '["qâshar"]', '["and/ the/ vigorous [ones]"]', '["v"]', 'to tie, physically (gird, confine, compact) or mentally (in love, league) bind (up), (make a) conspire(-acy, -ator), join together, knit, stronger, work (treason).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0001G}/H9025/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["[belonged] to/ father/ our","to/ ancestors/ our","to/ father/ our","to/ fathers/ our"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0834C}/[H834]', 'inflected', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["<and>/ from/ [that] which","and/ from/ [that] which"]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3519}/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["<the>/ glory","the/ abundance"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440L}/[H6437]', 'lemma', 'heb', 'פָּנִים', '["pânîym"]', '["[the] face of","[the] presence of","face"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8543}/[H865]', 'inflected', 'heb', 'תְּמוֹל', '["tᵉmôwl"]', '["as/ yesterday"]', '["adv"]', 'properly, ago, i.e. a (short or long) time since; especially yesterday, or day before yesterday before (-time), these (three) days, heretofore, time past, yesterday.', 'or תְּמֹל; probably for 865; sometimes with 8032');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8032}/[H8028]', 'lemma', 'heb', 'שִׁלְשׁוֹם', '["shilshôwm"]', '["[the] third day","three days ago"]', '["adv"]', 'trebly, i.e. (in time) day before yesterday before (that time, -time), excellent things (from the margin), heretofore, three days, time past.', 'or שִׁלְשֹׁם; from the same as 8028;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4138}/H9021/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["and/ to/ kindred/ your"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3812}/[H3811]', 'inflected', 'heb', 'לֵאָה', '["Lêʼâh"]', '["and/ <to>/ Leah"]', '["n-pr-f"]', 'Leah, a wife of Jacob Leah.', 'from 3811; weary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9027/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["father/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0859E}/[H859]', 'inflected', 'heb', 'אַתָּה', '["ʼattâh"]', '["and/ you"]', '["p"]', 'thou and thee, or (plural) ye and you thee, thou, ye, you.', 'or (shortened); אַתָּ; or אַת; feminine (irregular) sometimes אַתִּי; plural masculine אַתֶּם; feminine אַתֶּן; or אַתֵּנָהlemma אתֵּנָה missing vowel, corrected to אַתֵּנָה; or אַתֵּנָּה; a primitive pronoun of the second person;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3581B>/H9020', 'opaque', 'heb', 'כֹּחַ', '["kôach"]', '["[is] strength/ my","power/ my","strength/ my"]', '["n-m"]', 'vigor, literally (force, in a good or a bad sense) or figuratively (capacity, means, produce); also (from its hardiness) a large lizard ability, able, chameleon, force, fruits, might, power(-ful), strength, substance, wealth.', 'or (Daniel 11:6) כּוֹחַ; from an unused root meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0001G}/H9027/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ father/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2048B}/[H2048]', 'lemma', 'heb', 'הָתַל', '["hâthal"]', '["[which] it is deceived","he has deceived","they deceive","to deceive","will you deceive","you have deceived"]', '["v"]', 'to deride; by implication, to cheat deal deceitfully, deceive, mock.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2498}/[H2498]', 'inflected', 'heb', 'חָלַף', '["châlaph"]', '["and/ he changed","and/ he has changed","and/ it sprouts up","and/ it will pass on","and/ she pierced","and/ you changed","and/ you will pass on"]', '["v"]', 'properly, to slide by, i.e. (by implication) to hasten away, pass on, spring up, pierce or change abolish, alter, change, cut off, go on forward, grow up, be over, pass (away, on, through), renew, sprout, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4909}/H9020/[H7936]', 'inflected', 'heb', 'מַשְׂכֹּרֶת', '["maskôreth"]', '["wage[s]/ my"]', '["n-f"]', 'wages or a reward reward, wages.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4489}/[H4487]', 'lemma', 'heb', 'מֹנֶה', '["môneh"]', '["times"]', '["n-m"]', 'properly, something weighed out, i.e. (figuratively) a portion of time, i.e. an instance time.', 'from 4487;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414K}/H9033/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["he has permitted/ him","he permitted/ him","it permitted/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7489A}/[H7489]', 'inflected', 'heb', 'רָעַע', '["râʻaʻ"]', '["to/ do evil","to/ do harm"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5337}/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ I delivered","and/ I rescued [it]","and/ I will deliver","and/ I will take away","and/ he delivered","and/ he has taken away","and/ he rescued","and/ he will deliver [us]","and/ he will rescue [it]","and/ he will tear out","and/ it has been delivered","and/ they plundered","and/ they stripped themselves","and/ they will deliver","and/ you have delivered","and/ you will deliver","and/ you will plunder"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9026/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["[is] father/ your","ancestor/ your","ancestors/ your","father/ your","fathers/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869A}/H9020/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eye/ my","eyes/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6260}/[H6257]', 'inflected', 'heb', 'עַתּוּד', '["ʻattûwd"]', '["the/ leaders","the/ male goats"]', '["n-m"]', 'prepared, i.e. full grown; spoken only (in plural) of he-goats, or (figuratively) leaders of the people chief one, (he) goat, ram.', 'or עַתֻּד; from 6257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5927K}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["which/ are going up","which/ were going up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1261}/[H1258]', 'inflected', 'heb', 'בָּרֹד', '["bârôd"]', '["and/ mottled"]', '["a"]', 'spotted (as if with hail) grisled.', 'from 1258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0410G}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["<the>/ God","[am] the/ God","[am] the/ God of","[are] the/ God","the/ God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4886}/[H4886]', 'lemma', 'heb', 'מָשַׁח', '["mâshach"]', '["[are] anointing","he had been anointed","he has anointed","is anointed","people had anointed","smear","smeared","someone had anointed","someone will anoint","they have anointed","they smear","was anointed","we anointed","you anointed","you will anoint"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5087}/[H5087]', 'lemma', 'heb', 'נָדַר', '["nâdar"]', '["I have vowed","I vowed","he had vowed","he vowed","he will vow","make vows","she has vowed","she will vow","we have vowed","you have vowed","you vowed","you will vow"]', '["v"]', 'to promise (pos., to do or give something to God) (make a) vow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4138}/H9021/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["kindred/ your"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3812}/[H3811]', 'inflected', 'heb', 'לֵאָה', '["Lêʼâh"]', '["and/ Leah"]', '["n-pr-f"]', 'Leah, a wife of Jacob Leah.', 'from 3811; weary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5750}/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["¿/ still"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2506A}/[H2505]', 'lemma', 'heb', 'חֵלֶק', '["chêleq"]', '["[does] a share","[is the] portion of","[is] [the] portion of","[the] portion of","[the] portions","[will be] [the] portion of","a portion","a share","portion","portions"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5159}/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["and/ [the] inheritance of","and/ an inheritance"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004M}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["<in>/ [the] house of","[is] in the/ house","[was] in the/ house","against/ [the] house of","in the/ household","in/ [the] house of","in/ [the] household of","on/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5237}/[H5235]', 'lemma', 'heb', 'נׇכְרִי', '["nokrîy"]', '["[am] a foreigner","[are] a foreigner","[is] alien","a foreign [woman]","a foreigner","alien","foreign","foreigners"]', '["a"]', 'strange, in a variety of degrees and applications (foreign, non-relative, adulterous, different, wonderful) alien, foreigner, outlandish, strange(-r, woman).', 'from 5235 (second form);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2803H}/[H2803]', 'lemma', 'heb', 'חָשַׁב', '["châshab"]', '["I am reckoned","[it was] reckoned","[was] esteemed","anyone has valued","are we accounted","he reckon","he reckons","it is reckoned","it reckons itself","it will be accounted for","it will be reckoned","they are considered","they are regarded","they settled accounts","they value","they were thought","we have been regarded"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4376}/H9035/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["he has sold/ us"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3701G}/H9025/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["money/ our","silver/ our"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6239}/[H6238]', 'inflected', 'heb', 'עֹשֶׁר', '["ʻôsher"]', '["the/ wealth"]', '["n-m"]', 'wealth × far (richer), riches.', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5337}/[H5337]', 'lemma', 'heb', 'נָצַל', '["nâtsal"]', '["I will deliver [it]","[is] a deliverer","[is] delivering","[one who] delivers","[was one] delivering","[was] a deliverer","[when] he delivered","[will be] a deliverer","certainly <to deliver>","deliver","deliver yourself","delivering","did you recover [them]","have they delivered","he delivered","he delivers","he has delivered","he has taken away","he is delivered","he rescued","he will deliver","he will deliver himself","it delivers","may I be delivered","plucked out","rescue [them]","they delivered","they have delivered","they will be delivered","they will deliver","they will rescue","to rescue","we are delivered","we have recovered","will you be delivered?","you have delivered","you take away","you will be delivered","you will deliver","you will rescue","you will rescue [them]"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1121A}/H9025/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ to/ children/ our","and/ to/ descendants/ our"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375G}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ I took","and/ he lifted up","and/ he lifted up [some]","and/ he picked up","and/ he will be lifted up","and/ he will impose","and/ he will lift up","and/ it carried","and/ it carried away","and/ it carried off","and/ it has been lifted up","and/ it lifted up","and/ it will be carried off","and/ people lifted up","and/ she took up","and/ someone will take away","and/ they carried","and/ they carried [them]","and/ they lifted","and/ they lifted up","and/ they picked up","and/ they take [them]","and/ they took","and/ they took up","and/ they will take up","and/ you have taken","and/ you will lift up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5090A}/[H5090]', 'inflected', 'heb', 'נָהַג', '["nâhag"]', '["and/ he drove","and/ he drove away","and/ he lead out","and/ he led forth","and/ he led out","and/ they had driven them away","and/ you have led away"]', '["v"]', 'to drive forth (a person, an animal or chariot), i.e. lead, carry away; reflexively, to proceed (i.e. impel or guide oneself); also (from the panting induced by effort), to sigh acquaint, bring (away), carry away, drive (away), lead (away, forth), (be) guide, lead (away, forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4735}/H9023/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["livestock/ his"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7075}/H9023/[H7069]', 'inflected', 'heb', 'קִנְיָן', '["qinyân"]', '["acquisition/ his","possession/ his","possession[s]/ his"]', '["n-m"]', 'creation, i.e. (concretely) creatures; also acquisition, purchase, wealth getting, goods, × with money, riches, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6307>', 'inflected', 'heb', 'בפדן', '["be./fa.Dan"]', '["in/ Paddan"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3837A}/[H3836]', 'inflected', 'heb', 'לָבָן', '["Lâbân"]', '["and/ Laban"]', '["n-pr-m n-pr-loc"]', 'Laban, a Mesopotamian; also a place in the Desert Laban.', 'the same as 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1494}/[H1468]', 'inflected', 'heb', 'גָּזַז', '["gazâz"]', '["to/ shear"]', '["v"]', 'to cut off; specifically to shear a flock or shave the hair; figuratively to destroy an enemy cut off (down), poll, shave, (sheep-) shear(-er).', 'a primitive root (akin to 1468);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1589}/[H1589]', 'inflected', 'heb', 'גָּנַב', '["gânab"]', '["and/ I will steal","and/ did you steal?","and/ he stole","and/ it acted stealthily","and/ it will be stolen","and/ she stole","and/ you have stolen"]', '["v"]', 'to thieve (literally or figuratively); by implication, to deceive carry away, × indeed, secretly bring, steal (away), get by stealth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8655}/[H7495]', 'inflected', 'heb', 'תְּרָפִים', '["tᵉrâphîym"]', '["the/ teraphim"]', '["n-m"]', 'Teraphim (singular or plural) a family idol idols(-atry), images, teraphim.', 'plural from 7495; a healer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1097}/[H1086]', 'lemma', 'heb', 'בְּלִי', '["bᵉlîy"]', '["[which] not","destruction","not"]', '["np"]', 'properly, failure, i.e. nothing or destruction; usually (with preposition) without, not yet, because not, as long as, etc. corruption, ig(norantly), for lack of, where no...is, so that no, none, not, un(awares), without.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5104G}/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["the/ River","the/ river"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440L}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ his","presence/ his"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1568G}/[H1567]', 'inflected', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["<the>/ Gilead"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2022H}/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["[is] in/ [the] hill country of","in the/ hill country","in/ [the] hill country of","in/ [the] mountains of"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2896A}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["from/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5381}/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["and/ he overtook","and/ it will reach","and/ they overtook"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8628}/[H8628]', 'lemma', 'heb', 'תָּקַע', '["tâqaʻ"]', '["[is] striking","[who] give a blast on","blow","he gave a blast","he had pitched","he pitched tent","he will give a blast","is it blown","it will be blown","strike","they fixed","they gave a blast","they have given a blast","they will give a blast","they will pitch","those striking hands","will he strike himself","you have struck","you will give a blast"]', '["v"]', 'to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1323G}/H9020/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["O daughter/ my","O daughters/ my","[are] daughters/ my","daughter/ my","daughters/ my"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7617}/[H7617]', 'inflected', 'heb', 'שָׁבָה', '["shâbâh"]', '["like/ captives of"]', '["v"]', 'to transport into captivity (bring away, carry, carry away, lead, lead away, take) captive(-s), drive (take) away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2719}/[H2717]', 'lemma', 'heb', 'חֶרֶב', '["chereb"]', '["O sword","[are] swords","[is] [the] sword of","[is] a sword","[is] a sword of","[the] sword","[the] sword of","[were] a sword","a sword","a sword of","knives of","sword","swords"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2244}/[H2245]', 'lemma', 'heb', 'חָבָא', '["châbâʼ"]', '["[has] hidden himself","[is] hiding himself","[was] hiding himself","[were] hiding themselves","did you hide yourself","he hides himself","hidden","hiding","hiding himself","she hid","they are hidden","they are made to hide themselves","they become hard","they had hidden themselves","they have hidden themselves","they were hidden","they will hide themselves","you will be hidden"]', '["v"]', 'to secrete × held, hide (self), do secretly.', 'a primitive root (compare 2245);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1272}/[H1272]', 'inflected', 'heb', 'בָּרַח', '["bârach"]', '["to/ flee","to/ pass through"]', '["v"]', 'to bolt, i.e. figuratively, to flee suddenly chase (away); drive away, fain, flee (away), put to flight, make haste, reach, run away, shoot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8057}/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["in/ [the] joy of","in/ joy","with/ [the] joy of","with/ gladness","with/ joy","with/ joy of","with/ joy<s>","with/ pleasure","with/ rejoicing"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7892A}/[H7891]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["and/ with/ song","and/ with/ songs"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8596}/[H8608]', 'inflected', 'heb', 'תֹּף', '["tôph"]', '["[will be] with/ tambourines","with/ tambourine","with/ tambourines"]', '["n-m"]', 'a tambourine tabret, timbrel.', 'from 8608 contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H3658>', 'inflected', 'heb', 'ובכנרות', '["u./ve./khi.Nor","u./ve./khi.no.Rot","u./ve./khi.no.rOt"]', '["and/ on/ harps","and/ with/ harp","and/ with/ harps"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5203}/H9030/[H5203]', 'inflected', 'heb', 'נָטַשׁ', '["nâṭash"]', '["did you allow?/ me","you abandon/ me"]', '["v"]', 'properly, to pound, i.e. smite; by implication (as if beating out, and thus expanding) to disperse; also, to thrust off, down, out or upon (inclusively, reject, let alone, permit, remit, etc.) cast off, drawn, let fall, forsake, join (battle), leave (off), lie still, loose, spread (self) abroad, stretch out, suffer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5401A}/[H5400]', 'inflected', 'heb', 'נָשַׁק', '["nâshaq"]', '["to/ kiss"]', '["v"]', 'to kiss, literally or figuratively (touch); also (as a mode of attachment), to equip with weapons armed (men), rule, kiss, that touched.', 'a primitive root (identical with 5400, through the idea of fastening up; compare 2388, 2836);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121G}/H9020/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["<to>/ sons/ my"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1323G}/H9020/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ <to>/ daughters/ my","and/ for/ daughters/ my"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5528}/[H3688]', 'lemma', 'heb', 'סָכַל', '["çâkal"]', '["I have acted foolishly","I have behaved foolishly","he makes foolish","make foolish","you have acted foolishly","you have behaved foolishly"]', '["v"]', 'to be silly do (make, play the, turn into) fool(-ish, -ishly, -ishness).', 'for 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0410L}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["[belongs] to/ [the] power of","[is] to/ [the] power of","[it is] to/ [the] power of","to/ [the] power of"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027H}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451B}/[H7489]', 'lemma', 'heb', 'רַע', '["raʻ"]', '["<of> evil","[is] an evil","[the] evil of","an evil [person]","bad","calamity","distress","evil","harm","harmful","trouble"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1696G}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["from/ speaking","more than/ speaking"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3700}/[H3700]', 'lemma', 'heb', 'כָּסַף', '["kâçaph"]', '["[which] it longs","ashamed","certainly <to long for>","it has longed","you longed","you will long"]', '["v"]', 'properly, to become pale, i.e. (by implication) to pine after; also to fear (have) desire, be greedy, long, sore.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430J}/H9020/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["gods/ my"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5973B}/H9030/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["from/ with <the>/ me"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430J}/H9021/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["[are] gods/ your","gods/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5048}/[H5046]', 'lemma', 'heb', 'נֶגֶד', '["neged"]', '["[are] before","[is] before","[was] before","before"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251H}/H9025/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["relatives/ our"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5234A}/[H5234]', 'lemma', 'heb', 'נָכַר', '["nâkar"]', '["I recognized","I will regard","[one who] recognizes","[were] knowing","[were] recognizing","do you recognize?","he acknowledges","he is acquainted with","he makes himself known","he recognized","he regards","he will acknowledge","investigate","they are recognized","they paid regard","they pay regard to","they recognized","to pay regard to","you will pay regard to"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1589}/H9038/[H1589]', 'inflected', 'heb', 'גָּנַב', '["gânab"]', '["she had stolen/ them"]', '["v"]', 'to thieve (literally or figuratively); by implication, to deceive carry away, × indeed, secretly bring, steal (away), get by stealth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0168G}/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["and/ in/ [the] tent of"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0168G}/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["from/ [the] tent of","from/ [the] tents of","from/ a tent","from/ tent"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760H}/H9038/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ she had put/ them","and/ you will appoint/ them","and/ you will put/ them"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3733A}/[H3769]', 'inflected', 'heb', 'כַּר', '["kar"]', '["in/ [the] saddlebag of"]', '["n-m"]', 'a ram (as full-grown and fat), including a battering-ram (as butting); hence, a meadow (as for sheep); also a pad or camel''s saddle (as puffed out) captain, furniture, lamb, (large) pasture, ram. See also 1033, 3746.', 'from 3769 in the sense of plumpness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4959}/[H4959]', 'inflected', 'heb', 'מָשַׁשׁ', '["mâshash"]', '["and/ he searched"]', '["v"]', 'to feel of; by implication, to grope feel, grope, search.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6965B}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["to/ arise","to/ rise"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440G}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<from>/ because of/ you","from/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2664}/[H2664]', 'inflected', 'heb', 'חָפַשׂ', '["châphas"]', '["and/ I will search out","and/ he disguised himself","and/ he searched","and/ it searched","and/ they will search"]', '["v"]', 'to seek; causatively, to conceal oneself (i.e. let be sought), or mask change, (make) diligent (search), disquise self, hide, search (for, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3837A}/[H3836]', 'inflected', 'heb', 'לָבָן', '["Lâbân"]', '["with/ Laban"]', '["n-pr-m n-pr-loc"]', 'Laban, a Mesopotamian; also a place in the Desert Laban.', 'the same as 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6588}/H9020/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["[is] transgression/ my","transgression/ my","transgressions/ my"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403B}/H9020/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["[is] sin/ my","sin/ my","sins/ my"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1814}/[H1814]', 'lemma', 'heb', 'דָּלַק', '["dâlaq"]', '["burning","he hotly pursues","kindle","you have hotly pursued"]', '["v"]', 'to flame (literally or figuratively) burning, chase, inflame, kindle, persecute(-or), pursue hotly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4959}/[H4959]', 'lemma', 'heb', 'מָשַׁשׁ', '["mâshash"]', '["groping","he gropes","they grope","you have searched"]', '["v"]', 'to feel of; by implication, to grope feel, grope, search.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3627}/H9020/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["baggage<s>/ my","things/ my","weapons/ my"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251H}/H9021/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ relatives/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8147}/H9025/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["[the] two of/ us"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7353>/H9021', 'opaque', 'heb', 'רָחֵל', '["râchêl"]', '["ewes/ your"]', '["n-f"]', 'a ewe [the females being the predominant element of a flock] (as a good traveller) ewe, sheep.', 'from an unused root meaning to journey;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5795}/H9021/[H5810]', 'inflected', 'heb', 'עֵז', '["ʻêz"]', '["and/ female goats/ your"]', '["n-f"]', 'a she-goat (as strong), but masculine in plural (which also is used elliptically for goat''s hair) (she) goat, kid.', 'from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2966}/[H2964]', 'lemma', 'heb', 'טְרֵפָה', '["ṭᵉrêphâh"]', '["a torn animal"]', '["n-f"]', 'prey, i.e. flocks devoured by animals ravin, (that which was) torn (of beasts, in pieces).', 'feminine (collectively) of 2964;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2398}/H9034/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["I bore [the] loss of/ it"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1245}/H9034/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["[those who] seek/ it","you sought/ it","you will seek/ it"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1589}/[H1589]', 'inflected', 'heb', 'גָּנַב', '["gânab"]', '["and/ [one who] will steal","and/ [one] stolen of","and/ stealing"]', '["v"]', 'to thieve (literally or figuratively); by implication, to deceive carry away, × indeed, secretly bring, steal (away), get by stealth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0398}/H9030/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["he devoured/ me","it consumed/ me","it has consumed/ me"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2721A}/[H2719]', 'lemma', 'heb', 'חֹרֶב', '["chôreb"]', '["a drought","dryness","heat"]', '["n-m"]', 'drought or desolation desolation, drought, dry, heat, × utterly, waste.', 'a collaterally form of 2719;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7140}/[H7139]', 'inflected', 'heb', 'קֶרַח', '["qerach"]', '["and/ frost"]', '["n-m"]', 'ice (as if bald, i.e. smooth); hence, hail; by resemblance, rock crystal crystal, frost, ice.', 'or קֹרַח; from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5074}/[H5074]', 'inflected', 'heb', 'נָדַד', '["nâdad"]', '["and/ it fled"]', '["v"]', 'properly, to wave to and fro (rarely to flap up and down); figuratively, to rove, flee, or (causatively) to drive away chase (away), × could not, depart, flee (× apace, away), (re-) move, thrust away, wander (abroad, -er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8142}/H9020/[H3462]', 'inflected', 'heb', 'שֵׁנָה', '["shênâh"]', '["sleep/ my"]', '["n-f"]', 'sleep sleep.', 'or שֵׁנָא; (Psalm 127:2), from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5869A}/H9020/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["from/ eyes/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004M}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["among/ household/ your","in/ house/ your","in/ household/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8147}/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["<in>/ two","<on>/ [the] two","[was] with/ two [plus]","by <the>/ twofold","by/ two [plus]","for/ [the] two","in/ [the] two","in/ two","in/ two [plus]","in/ two [times]","on/ [day] two [plus]","on/ two","with/ two","with/ two [wings]"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6629G>/H9021', 'inflected', 'heb', 'בצאנך', '["be./tzo.Ne./kha"]', '["for/ flock[s]/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3884}/[H3863]', 'lemma', 'heb', 'לוּלֵא', '["lûwlêʼ"]', '["if not"]', '["conj"]', 'if not except, had not, if (...not), unless, were it not that.', 'or לוּלֵי; from 3863 and 3808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6343}/[H6342]', 'inflected', 'heb', 'פַּחַד', '["pachad"]', '["and/ [the] fear of","and/ a dread","and/ dread"]', '["n-m"]', 'a (sudden) alarm (properly, the object feared, by implication, the feeling) dread(-ful), fear, (thing) great (fear, -ly feared), terror.', 'from 6342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7387}/[H7386]', 'lemma', 'heb', 'רֵיקָם', '["rêyqâm"]', '["emptily","empty","in vain","with empty hands","without cause"]', '["adv"]', 'emptily; figuratively (objective) ineffectually, (subjective) undeservedly without cause, empty, in vain, void.', 'from 7386;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6040}/H9020/[H6031]', 'inflected', 'heb', 'עֳנִי', '["ʻŏnîy"]', '["affliction/ my"]', '["n-m"]', 'depression, i.e. misery afflicted(-ion), trouble.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3018}/[H3021]', 'lemma', 'heb', 'יְגִיעַ', '["yᵉgîyaʻ"]', '["[the] produce of","[the] product of","[the] toil of"]', '["n-m"]', 'toil; hence, a work, produce, property (as the result of labor) labour, work.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1323G}/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["<the>/ daughter","<the>/ daughters","O/ daughter","O/ daughter of","the/ daughters"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1121A}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ the/ child","and/ the/ children"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H6629G>', 'inflected', 'heb', 'והצאן', '["ve./ha./Tzon"]', '["and/ the/ flock","and/ the/ flock[s]","and/ the/ sheep"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6629G>/H9020', 'opaque', 'heb', 'צֹאן', '["tsôʼn"]', '["O flock/ my","[are] flock/ my","[is] flock/ my","flock/ my"]', '["n-f"]', 'a collective name for a flock (of sheep or goats); also figuratively (of men) (small) cattle, flock ( -s), lamb ( -s), sheep(-cote, -fold, -shearer, -herds).', 'or צאוֹן; (Psalm 144:13), from an unused root meaning to migrate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0428}/[H411]', 'inflected', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["[belong] to/ these","[belonged] to/ these","for/ these","of/ these [things]","to/ these"]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121A}/H9029/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["for/ children/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5707}/[H5749]', 'inflected', 'heb', 'עֵד', '["ʻêd"]', '["<into>/ a witness","<into>/ a witness of","for/ booty","to/ a witness"]', '["n-m"]', 'concretely, a witness; abstractly, testimony; specifically, a recorder, i.e. prince witness.', 'contracted from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0068G}/[H1129]', 'lemma', 'heb', 'אֶבֶן', '["ʼeben"]', '["O stones of","[is] a stone of","[the] stone of","[the] stones of","[were] stones","[were] stones of","a stone","a stone of","stone","stone<s>","stone[s]","stones","stones of"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7311A}/H9034/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["and/ he raised up/ it"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251H}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["<to>/ relatives/ his","to/ relatives/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3950}/[H3950]', 'lemma', 'heb', 'לָקַט', '["lâqaṭ"]', '["[are] gathering","did you glean","gather","gathering up","let me glean","she had gleaned","she will glean","they gathered","they had gathered","they will gather","you will be gathered","you will gather"]', '["v"]', 'properly, to pick up, i.e. (generally) to gather; specifically, to glean gather (up), glean.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1530G}/[H1556]', 'lemma', 'heb', 'גַּל', '["gal"]', '["a heap","a heap of","heaps"]', '["n-m"]', 'something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1530G}/[H1556]', 'inflected', 'heb', 'גַּל', '["gal"]', '["the/ heap"]', '["n-m"]', 'something rolled, i.e. a heap of stone or dung (plural ruins), by analogy, a spring of water (plural waves) billow, heap, spring, wave.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3026A>', 'opaque', 'heb', 'יְגַר שַׂהֲדוּתָא', '["Yᵉgar Sahădûwthâʼ"]', '["Jegar"]', '["n-pr-loc"]', 'Jegar-Sahadutha, a cairn East of the Jordan Jegar-Sahadutha.', '(Aramaic) from a word derived from an unused root (meaning to gather) and a derivation of a root corresponding to 7717; heap of the testimony;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3026B>', 'opaque', 'heb', 'יְגַר שַׂהֲדוּתָא', '["Yᵉgar Sahădûwthâʼ"]', '["Sahadutha"]', '["n-pr-loc"]', 'Jegar-Sahadutha, a cairn East of the Jordan Jegar-Sahadutha.', '(Aramaic) from a word derived from an unused root (meaning to gather) and a derivation of a root corresponding to 7717; heap of the testimony;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1567}/[H1530]', 'lemma', 'heb', 'גַּלְעֵד', '["Galʻêd"]', '["Galeed"]', '["n-pr-loc"]', 'Galed, a memorial cairn East of the Jordan Galeed.', 'from 1530 and 5707; heap of testimony;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5707}/[H5749]', 'lemma', 'heb', 'עֵד', '["ʻêd"]', '["[are] witnesses","[is] a witness","[is] a witness of","[was] a witness","[we are] witnesses","a witness","a witness of","evidence","testimony of","witnesses","witnesses of"]', '["n-m"]', 'concretely, a witness; abstractly, testimony; specifically, a recorder, i.e. prince witness.', 'contracted from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4709H}/[H4708]', 'inflected', 'heb', 'מִצְפָּה', '["Mitspâh"]', '["and/ <the>/ Mizpah"]', '["n-pr-f"]', 'Mitspah, the name of two places in Palestine Mitspah. (This seems rather to be only an orthographic variation of 4708 when ''in pause''.)', 'feminine of 4708;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6822}/[H6822]', 'lemma', 'heb', 'צָפָה', '["tsâphâh"]', '["I will watch","[is] watching","[she is] watching over","[was] a watchman","[which] watches","a watchman","may he keep watch","they keep watch","watching","watchmen","we watched"]', '["v"]', 'properly, to lean forward, i.e. to peer into the distance; by implication, to observe, await behold, espy, look up (well), wait for, (keep the) watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7453}/H9023/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["from/ friend/ his","from/ neighbor/ his"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6031B}/[H6030]', 'lemma', 'heb', 'עָנָה', '["ʻânâh"]', '["I am afflicted","I have been afflicted","I humbled","I was afflicted","[is] keeping busy","[the] afflicted","[was] afflicted","certainly [if] <to afflict>","have we humbled?","he had humbled","he has afflicted","he has humbled","he has humiliated","he violates","he was afflicted","it cringes","it will humble [itself]","men have humiliated","people afflicted","they abused","they afflict","they are afflicted","they have humiliated","they were afflicted","to humble","you have afflicted [me]","you were afflicted","you will afflict","you will mistreat"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4676}/[H5324]', 'inflected', 'heb', 'מַצֵּבָה', '["matstsêbâh"]', '["the/ pillar","the/ sacred pillars"]', '["n-f"]', 'something stationed, i.e. a column or (memorial stone); by analogy, an idol garrison, (standing) image, pillar.', 'feminine (causatively) participle of 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3384B}/[H3384]', 'lemma', 'heb', 'יָרָה', '["yârâh"]', '["I have set up","I will instruct","[he is] pointing","[who] teaches","he teaches","teaching","they teach","they will instruct","they will teach","will he teach","will it teach?"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5713A}/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["and/ [is] a witness"]', '["n-f"]', 'testimony testimony, witness. Compare 5712.', 'feminine of 5707 in its techn. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7451C}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["for/ evil","for/ harm"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6343}/[H6342]', 'inflected', 'heb', 'פַּחַד', '["pachad"]', '["by/ [the] fear of"]', '["n-m"]', 'a (sudden) alarm (properly, the object feared, by implication, the feeling) dread(-ful), fear, (thing) great (fear, -ly feared), terror.', 'from 6342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2076}/[H2076]', 'inflected', 'heb', 'זָבַח', '["zâbach"]', '["and/ he has sacrificed","and/ he sacrificed","and/ he slaughtered","and/ he will sacrifice","and/ they have sacrificed","and/ they sacrificed","and/ they will sacrifice","and/ we will sacrifice","and/ you will sacrifice","and/ you will slaughter"]', '["v"]', 'to slaughter an animal (usually in sacrifice) kill, offer, (do) sacrifice, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2077}/[H2076]', 'lemma', 'heb', 'זֶבַח', '["zebach"]', '["[is] a sacrifice of","[the] sacrifice","[the] sacrifice of","[the] sacrifices of","[will be] sacrifice","a sacrifice","a sacrifice of","sacrifice","sacrifice[s]","sacrifices","sacrifices of"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121G}/H9023/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["<to>/ sons/ his","to/ sons/ his"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1323G}/H9023/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ <to>/ daughters/ his","and/ for/ daughter/ his"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1870L}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["on/ way/ his","to/ way/ his"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200G}/H9038/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["I showed/ them","I will show/ them","[those who] see/ them","he had shown/ them","he saw/ them","he showed/ them","to let to see/ them"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4264}/[H2583]', 'lemma', 'heb', 'מַחֲנֶה', '["machăneh"]', '["[is] [the] camp of","[the] army of","[the] camp of","[the] camps of","a camp","an army","armies","camps"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4266}\/[H4264]', 'inflected', 'heb', 'מַחֲנַיִם', '["Machănayim"]', '["Mahanaim"]', '["n-pr-loc"]', 'Machanajim, a place in Palestine Mahanaim.', 'dual of 4264; double camp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4397G>', 'opaque', 'heb', 'מַלְאָךְ', '["malʼâk"]', '["O messengers","[is] [the] messenger of","[is] messengers of","[the] messenger of","[the] messengers of","a messenger","messengers","messengers of"]', '["n-m"]', 'a messenger; specifically, of God, i.e. an angel (also a prophet, priest or teacher) ambassador, angel, king, messenger.', 'from an unused root meaning to despatch as a deputy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0123G}/[H122]', 'lemma', 'heb', 'אֱדֹם', '["ʼĔdôm"]', '["Edom"]', '["n-pr-m"]', 'Edom, the elder twin-brother of Jacob; hence the region (Idumaea) occupied by him Edom, Edomites, Idumea.', 'or (fully) אֱדוֹם ; from 122; red (see Genesis 25:25);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0559}/H9013/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["you must say/ !","you will say/ !"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0309}/[H309]', 'inflected', 'heb', 'אָחַר', '["ʼâchar"]', '["and/ I have delayed","and/ he was delayed"]', '["v"]', 'to loiter (i.e. be behind); by implication to procrastinate continue, defer, delay, hinder, be late (slack), stay (there), tarry (longer).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7794}/[H7788]', 'lemma', 'heb', 'שׁוֹר', '["shôwr"]', '["[is] an ox","[the] ox of","[was] an ox","[will be] an ox","a cow","an ox","bulls","ox","ox[en]"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971G}/H9012/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ I have sent/ !","and/ I sent/ !"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5046}/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["by/ telling","to/ [those who] told","to/ declare","to/ tell"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4397G>', 'inflected', 'heb', 'המלאכים', '["ha./mal.''Akh","ha./mal.''a.Khim","ha./mal.''oKh"]', '["the/ messenger","the/ messengers"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980H}/[H3212]', 'lemma', 'heb', 'הָלַךְ', '["hâlak"]', '["I will go","[he is] coming","[was] coming","come","coming","continually <to go>","continuously <to come>","continuously <to go>","did you come","going","it will come","they will go","to come","you went"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122G}/H9031/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ you"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3334}/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["and/ it was distress","and/ they caused distress"]', '["v"]', 'to press (intransitive), i.e. be narrow; figuratively, be in distress be distressed, be narrow, be straitened (in straits), be vexed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2673}/[H2086]', 'inflected', 'heb', 'חָצָה', '["châtsâh"]', '["and/ he divided","and/ they were divided","and/ they will divide","and/ you will divide"]', '["v"]', 'to cut or split in two; to halve divide, × live out half, reach to the midst, participle', 'a primitive root (compare 2086));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1581}/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["and/ the/ camels"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4264}/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["the/ army","the/ camp","the/ camps","the/ company","the/ two groups"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5221}/H9033/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["and/ I struck/ it","and/ I will strike down/ him","and/ he attacked/ him","and/ he had defeated/ him","and/ he has struck/ it","and/ he struck down/ him","and/ he struck/ him","and/ he will attack/ it","and/ he will strike/ him","and/ he will strike/ it","and/ it struck down/ him","and/ it struck/ him","and/ it struck/ it","and/ someone will strike/ him","and/ they struck/ him","and/ we struck down/ him"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7604}/[H7604]', 'inflected', 'heb', 'שָׁאַר', '["shâʼar"]', '["<the>/ [one who] remains","<the>/ remaining","[is] the/ [one who] remains","[those] who/ remain","the/ [part which] remains","the/ remnant","the/ survivors","those/ [who] remain","those/ [who] remained","which/ remain","which/ remained","which/ remains","who/ remain","who/ remained","who/ remains"]', '["v"]', 'properly, to swell up, i.e. be (causatively, make) redundant leave, (be) left, let, remain, remnant, reserve, the rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6413}/[H6412]', 'inflected', 'heb', 'פְּלֵיטָה', '["pᵉlêyṭâh"]', '["<into>/ an escaped remnant","<to>/ a deliverance","<to>/ deliverance","[will be] for/ [the] escaped remnant of","for/ [the] escaped remnant of"]', '["n-f"]', 'deliverance; concretely, an escaped portion deliverance, (that is) escape(-d), remnant.', 'or פְּלֵטָה; feminine of 6412;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0559}/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["O those/[who] say","[is] the/ [one who] said","[she] who/ says","that/ are saying","the/ [one who] says","the/ [one who] speaks","those/ [who] say","which/ says","who/ are saying","who/ said","who/ say","who/ says","who/ were saying"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0776G>/H9021', 'inflected', 'heb', 'לארצך', '["le./''ar.Tze./kha","le./''ar.tze./Kha"]', '["for/ land/ your","to/ land/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3190}/[H3190]', 'inflected', 'heb', 'יָטַב', '["yâṭab"]', '["and/ [are] doing good","and/ [one who] does well","and/ make good","so/ it may be good","so/ it may go well","so/ let me do good"]', '["v"]', 'to be (causative) make well, literally (sound, beautiful) or figuratively (happy, successful, right) be accepted, amend, use aright, benefit, be (make) better, seem best, make cheerful, be comely, be content, diligent(-ly), dress, earnestly, find favour, give, be glad, do (be, make) good(-ness), be (make) merry, please ( well), shew more (kindness), skilfully, × very small, surely, make sweet, thoroughly, tire, trim, very, be (can, deal, entreat, go, have) well (said, seen).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6994}/[H6996]', 'lemma', 'heb', 'קָטֹן', '["qâṭôn"]', '["I am [too] insignificant"]', '["v"]', 'to diminish, i.e. be (causatively, make) diminutive or (figuratively) of no account be a (make) small (thing), be not worthy.', 'a primitive root (rather denominative from 6996);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2617A}/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["<the>/ covenant loyalty","the/ covenant loyalti<es>","the/ covenant loyalty","the/ loyalty"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0571G}/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["<the>/ faithfulness","the/ faithfulness"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4731>/H9020', 'inflected', 'heb', 'במקלי', '["ve./mak.L/i"]', '["with/ staff/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5337}/H9030/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["deliver/ me","he delivered/ me","he has delivered/ me","he rescued/ me","he will deliver/ me","you have rescued/ me","you rescue/ me","you will rescue/ me"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027H}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[is] from/ [the] hand of","from/ [the] hand of","from/ [the] hands of","from/ a hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5221}/H9030/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["and/ he will attack/ me","and/ he will strike down/ me","and/ they will attack/ me"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2344}/[H2342]', 'inflected', 'heb', 'חוֹל', '["chôwl"]', '["like <the>/ sand","like the/ sand","like/ [the] sand of"]', '["n-m"]', 'sand (as round or whirling particles) sand.', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0935P}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["which/ came","which/ had been brought","which/ has been brought","which/ was brought","who/ will bring"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4503H>', 'opaque', 'heb', 'מִנְחָה', '["minchâh"]', '["[is] a gift","a gift","an offering","tribute"]', '["n-f"]', 'a donation; euphemistically, tribute; specifically a sacrificial offering (usually bloodless and voluntary) gift, oblation, (meat) offering, present, sacrifice.', 'from an unused root meaning to apportion, i.e. bestow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H8495>', 'inflected', 'heb', 'ותישים', '["u./te.ya.Shim"]', '["and/ male goats"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7353>', 'opaque', 'heb', 'רָחֵל', '["râchêl"]', '["ewes"]', '["n-f"]', 'a ewe [the females being the predominant element of a flock] (as a good traveller) ewe, sheep.', 'from an unused root meaning to journey;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121H}/H9028/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ young/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6510}/[H6499]', 'lemma', 'heb', 'פָּרָה', '["pârâh"]', '["O cows of","a heifer","cows"]', '["n-f"]', 'a heifer cow, heifer, kine.', 'feminine of 6499;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6499}/[H6565]', 'inflected', 'heb', 'פַּר', '["par"]', '["and/ [the] young bull","and/ a bull","and/ a young bull","and/ a young bull of","and/ bulls","and/ young bulls"]', '["n-m"]', 'a bullock (apparently as breaking forth in wild strength, or perhaps as dividing the hoof) ( young) bull(-ock), calf, ox.', 'or פָּר; from 6565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0860}/[H386]', 'lemma', 'heb', 'אָתוֹן', '["ʼâthôwn"]', '["female donkeys"]', '["n-f"]', 'a female donkey (from its docility) (she) ass.', 'probably from the same as 386 (in the sense of patience);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5895}/[H5782]', 'inflected', 'heb', 'עַיִר', '["ʻayir"]', '["and/ a male donkey of","and/ male donkeys"]', '["n-m"]', 'properly, a young ass (as just broken to a load); hence an ass-colt (ass) colt, foal, young ass.', 'from 5782 in the sense of raising (i.e. bearing a burden);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027K}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[are] at/ [the] hand of","[was] by/ [the] hand of","by/ [the] hand of","in/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7305}/[H7304]', 'inflected', 'heb', 'רֶוַח', '["revach"]', '["and/ a space"]', '["n-m"]', 'room, literally (an interval) or figuratively (deliverance) enlargement, space.', 'from 7304;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6298}/H9031/[H6298]', 'inflected', 'heb', 'פָּגַשׁ', '["pâgash"]', '["he will meet/ you"]', '["v"]', 'to come in contact with, whether by accident or violence; figuratively, to concur meet (with, together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7592}/H9031/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["and/ he will ask/ you"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4310}/[H4100]', 'inflected', 'heb', 'מִי', '["mîy"]', '["<to>/ whom?","[belong] to/ whom?","[belongs] to/ whom?","of/ whom?","to/ whom?"]', '["i"]', 'who? (occasionally, by a peculiar idiom, of things); also (indefinitely) whoever; often used in oblique construction with prefix or suffix any (man), × he, × him, O that! what, which, who(-m, -se, -soever), would to God.', 'an interrogative pronoun of persons, as 4100 is of things,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4310}/[H4100]', 'inflected', 'heb', 'מִי', '["mîy"]', '["and/ [belong] to/ whom?","and/ [belongs] to/ whom?","and/ for/ whom?"]', '["i"]', 'who? (occasionally, by a peculiar idiom, of things); also (indefinitely) whoever; often used in oblique construction with prefix or suffix any (man), × he, × him, O that! what, which, who(-m, -se, -soever), would to God.', 'an interrogative pronoun of persons, as 4100 is of things,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310A}/H9035/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["[is] behind/ us","after/ us"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1980N}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["who/ go about","who/ walk","who/ walked","who/ were going"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1696G}/H9013/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["you will speak/ !"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4672}/H9046/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["when/ find/ you"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3722A}/[H3722]', 'lemma', 'heb', 'כָּפַר', '["kâphar"]', '["I will atone","I will cover","he atoned for","he will make atonement","he will make atonement for","it is atoned for","it makes atonement","it was atoned","it will be atoned","it will be atoned for","make atonement","may he make atonement","they will make atonement for","will I make amends","you atone","you will make atonement"]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4503H>', 'inflected', 'heb', 'במנחה', '["Be./min.chah","ba./min.Chah"]', '["by the/ gift","with/ a gift"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440N}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ my"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4503H>', 'inflected', 'heb', 'המנחה', '["ha./min.Chah"]', '["the/ gift"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440G}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ his","face/ its","presence/ his"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4264}/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["<in>/ [the] camp of","[is] in the/ camp","[was] in the/ camp","[was] in/ [the] camp of","[were] in the/ camp","in the/ camp","in the/ camps","in/ [the] camp of"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3206}/H9023/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["children/ its","sons/ his","young ones/ its"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4569A}/[H5674]', 'lemma', 'heb', 'מַעֲבָר', '["maʻăbâr"]', '["[the] ford of","[the] pass of","blow of"]', '["n-m"]', 'a crossing-place (of a river, a ford; of a mountain, a pass); abstractly, a transit, i.e. (figuratively) overwhelming ford, place where...pass, passage.', 'or feminine מַעֲבָרָה; from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2999}/[H1238]', 'lemma', 'heb', 'יַבֹּק', '["Yabbôq"]', '["Jabbok"]', '["n-pr-loc"]', 'Jabbok, a river east of the Jordan Jabbok.', 'probably from 1238; pouring forth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947G}/H9038/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ I took/ them","and/ I will take/ them","and/ he took/ them","and/ it took/ them","and/ they took/ them","and/ they will take/ them"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5674A}/H9038/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["and/ he sent over/ them"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5158A}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["the/ river","the/ rivers","the/ wadi"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3498}/[H3498]', 'inflected', 'heb', 'יָתַר', '["yâthar"]', '["and/ I am left","and/ I will leave over","and/ he left","and/ he remained","and/ he was left","and/ she had excess","and/ she has been left","and/ they had more than enough","and/ they left over","and/ they remained"]', '["v"]', 'to jut over or exceed; by implication, to excel; (intransitively) to remain or be left; causatively to leave, cause to abound, preserve excel, leave (a remnant), left behind, too much, make plenteous, preserve, (be, let) remain(-der, -ing, -nant), reserve, residue, rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0079}/[H80]', 'inflected', 'heb', 'אָבַק', '["ʼâbaq"]', '["and/ he wrestled"]', '["v"]', 'to bedust, i.e. grapple wrestle.', 'a primitive root, probably to float away (as vapor), but used only as denominative from 80;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3709I}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["<in>/ [the] socket of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3409>/H9023', 'opaque', 'heb', 'יָרֵךְ', '["yârêk"]', '["thigh/ his"]', '["n-f"]', 'the thigh (from its fleshy softness); by euphemistically the generative parts; figuratively, a shank, flank, side × body, loins, shaft, side, thigh.', 'from an unused root meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3363}/[H3363]', 'inflected', 'heb', 'יָקַע', '["yâqaʻ"]', '["and/ it was alienated","and/ it was dislocated"]', '["v"]', 'properly, to sever oneself, i.e. (by implication) to be dislocated; figuratively, to abandon; causatively, to impale (and thus allow to drop to pieces by rotting) be alienated, depart, hang (up), be out of joint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709I}/[H3721]', 'lemma', 'heb', 'כַּף', '["kaph"]', '["[the] hollow of","[the] pans of","[the] socket of","a pan","fronds of","pans of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0079}/H9043/[H80]', 'inflected', 'heb', 'אָבַק', '["ʼâbaq"]', '["when/ wrestled/ he"]', '["v"]', 'to bedust, i.e. grapple wrestle.', 'a primitive root, probably to float away (as vapor), but used only as denominative from 80;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971H}/H9030/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["let go/ me","you will let go/ me"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971H}/H9031/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["I will let go/ you"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3478}/[H8280]', 'lemma', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["Israel","O Israel","[is] Israel","[of] Israel","[were] Israel","of Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8280}/[H8280]', 'lemma', 'heb', 'שָׂרָה', '["sârâh"]', '["he struggled","you have struggled"]', '["v"]', 'to prevail have power (as a prince).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3201}/[H3201]', 'inflected', 'heb', 'יָכֹל', '["yâkôl"]', '["and/ he prevailed","and/ you have prevailed","and/ you prevailed","and/ you will be able"]', '["v"]', 'to be able, literally (can, could) or morally (may, might) be able, any at all (ways), attain, can (away with, (-not)), could, endure, might, overcome, have power, prevail, still, suffer.', 'or (fuller) יָכוֹל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7592}/[H7592]', 'lemma', 'heb', 'שָׁאַל', '["shâʼal"]', '["I ask","I asked","I have asked","I requested leave of absence","I will ask","[am] about to ask","[am] asking","[is] asked","[is] asking","[was] asked","are you asking","ask","ask for","asking","carefully <to ask>","certainly <to ask>","do you ask","enquire","have you asked","he asked","he asked for","he asked for himself","he enquires","he had asked","he had asked for","he has enquired","he will ask","let me ask","she asked","someone asked","they asked","they had asked","they have asked for","they have consulted","they will ask","they will ask for","you asked","you asked for","you have asked","you have asked for"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8034}/H9020/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["for/ name/ my","to/ name/ my"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6439G}/[H6437]', 'lemma', 'heb', 'פְּנוּאֵל', '["Pᵉnûwʼêl"]', '["Peniel","Penuel"]', '["n-pr-m n-pr-loc"]', 'Penuel or Peniel, a place East of Jordan; also (as Penuel) the name of two Israelites Peniel, Penuel.', 'or (more properly,) פְּנִיאֵל; from 6437 and 410; face of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2224}/[H2224]', 'inflected', 'heb', 'זָרַח', '["zârach"]', '["and/ it rises","and/ it rose","and/ it will rise"]', '["v"]', 'properly, to irradiate (or shoot forth beams), i.e. to rise (as the sun); specifically, to appear (as a symptom of leprosy) arise, rise (up), as soon as it is up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6760}/[H6763]', 'lemma', 'heb', 'צָלַע', '["tsâlaʻ"]', '["[was] limping"]', '["v"]', 'to limp (as if one-sided) halt.', 'a primitive root; probably to curve; used only as denominative from 6763,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1517}/[H1464]', 'lemma', 'heb', 'גִּיד', '["gîyd"]', '["[the] sinew of","[the] sinews of","sinews"]', '["n-m"]', 'a thong (as compressing); by analogy, a tendon sinew.', 'probably from 1464;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5384}/[H5382]', 'inflected', 'heb', 'נָשֶׁה', '["nâsheh"]', '["the/ tendon"]', '["n-m"]', 'rheumatic or crippled (from the incident to Jacob) which shrank.', 'from 5382, in the sense of failure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3409>', 'inflected', 'heb', 'הירך', '["hai./ya.Rekh"]', '["the/ thigh"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1517}/[H1464]', 'inflected', 'heb', 'גִּיד', '["gîyd"]', '["<in>/ [the] sinew of"]', '["n-m"]', 'a thong (as compressing); by analogy, a tendon sinew.', 'probably from 1464;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5973A}/H9033/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["and/ [were] with/ him","and/ with/ him"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H8198>', 'inflected', 'heb', 'השפחות', '["ha./she.fa.Chot","ha./shif.Chah"]', '["the/ female slaves","the/ maidservant","the/ maidservants"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3206}/H9029/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["children/ their","own children/ their","young/ their"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7223G}/[H7221]', 'lemma', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["[am] first","[will be] first","a first [one]","first","foremost"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3206}/H9024/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["and/ children/ her"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0314}/[H309]', 'lemma', 'heb', 'אַחֲרוֹן', '["ʼachărôwn"]', '["[am] last","[the] last","[the] last [ones]","[the] last [people]","[those] behind","behind","future","later"]', '["a"]', 'hinder; generally, late or last; specifically (as facing the east) western after (-ward), to come, following, hind(-er, -ermost, -most), last, latter, rereward, ut(ter) most.', 'or (shortened) אַחֲרֹן; from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5066G}/H9043/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["drew near/ he"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2263}/H9033/[H2263]', 'inflected', 'heb', 'חָבַק', '["châbaq"]', '["and/ he embraced/ him"]', '["v"]', 'to clasp (the hands or in embrace) embrace, fold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5401A}/H9033/[H5400]', 'inflected', 'heb', 'נָשַׁק', '["nâshaq"]', '["and/ he kissed/ him"]', '["v"]', 'to kiss, literally or figuratively (touch); also (as a mode of attachment), to equip with weapons armed (men), rule, kiss, that touched.', 'a primitive root (identical with 5400, through the idea of fastening up; compare 2388, 2836);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2603A}/[H2583]', 'lemma', 'heb', 'חָנַן', '["chânan"]', '["I have sought favor","I seek favor","I sought favor","I will seek favor","I will show favor","[he is] showing favor","[is] showing favor","[one who] shows favor","[one who] shows favor to","[who] shows favor","certainly <to show favor>","he has shown favor to","he is shown favor","he will make favorable","he will show favor to","it will show favor to","they show favor to","to have compassion","you have sought favor","you show favor to","you will seek favor"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3206}/H9029/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["and/ children/ their"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6298}/[H6298]', 'lemma', 'heb', 'פָּגַשׁ', '["pâgash"]', '["I have met","may he meet","they meet","they meet together"]', '["v"]', 'to come in contact with, whether by accident or violence; figuratively, to concur meet (with, together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869H}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ [the] eyes of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947H}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ I will accept","and/ he brought","and/ he took","and/ he took [it]","and/ he took [them]","and/ he will accept [it]","and/ it received","and/ they received","and/ you will accept","and/ you will take","and/ you will take [them]"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4503H>/H9020', 'opaque', 'heb', 'מִנְחָה', '["minchâh"]', '["gift/ my"]', '["n-f"]', 'a donation; euphemistically, tribute; specifically a sacrificial offering (usually bloodless and voluntary) gift, oblation, (meat) offering, present, sacrifice.', 'from an unused root meaning to apportion, i.e. bestow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7521}/H9030/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["and/ you have accepted favorably/ me"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2603A}/H9030/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["he has shown favor to/ me","show favor to/ me"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5265}/[H5265]', 'lemma', 'heb', 'נָסַע', '["nâçaʻ"]', '["[are] about to set out","[one who] quarries","[was] marching","[was] setting out","anyone will pull out","has it been pulled up","he had departed","he has set out","he led out","he set out","it has been pulled up","it set out","let us set out","set out","they have departed","they have set out","they set out","they will set out","you uprooted","you will set aside","you will set out"]', '["v"]', 'properly, to pull up, especially the tent-pins, i.e. start on a journey cause to blow, bring, get, (make to) go (away, forth, forward, onward, out), (take) journey, march, remove, set aside (forward), × still, be on his (go their) way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1980M}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ let us go"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5048}/H9031/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["to/ before/ you"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1241}/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["and/ the/ bull[s]","and/ the/ cattle"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5763}/[H5763]', 'lemma', 'heb', 'עוּל', '["ʻûwl"]', '["[are] nursing","nursing","nursing [ewes]","nursing [sheep]"]', '["v"]', 'to suckle, i.e. give milk milch, (ewe great) with young.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1849}/H9038/[H1849]', 'inflected', 'heb', 'דָּפַק', '["dâphaq"]', '["and/ people will drive hard/ them"]', '["v"]', 'to knock; by analogy, to press severely beat, knock, overdrive.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5095}/[H5095]', 'lemma', 'heb', 'נָהַל', '["nâhal"]', '["I will journey on","[is one who] leads","you have led [them]"]', '["v"]', 'properly, to run with a sparkle, i.e. flow; hence (transitively), to conduct, and (by inference) to protect, sustain carry, feed, guide, lead (gently, on).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0328B>/H9020', 'inflected', 'heb', 'לאטי', '["le./''i.T/i"]', '["to/ gentleness/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7272}/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["to/ [the] foot of"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4399}/[H4397]', 'inflected', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["<of> the/ work","the/ property","the/ work"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7272}/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["and/ to/ [the] foot of"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8165A}/H9011/[H8163]', 'inflected', 'heb', 'שֵׂעִיר', '["Sêʻîyr"]', '["Seir/ towards"]', '["n-pr"]', 'Seir, a mountain of Idumaea and its aboriginal occupants, also one in Palestine Seir.', 'formed like 8163; rough;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3322}/[H3322]', 'lemma', 'heb', 'יָצַג', '["yâtsag"]', '["[am] placing","it will be detained","let me place","to place","you will set"]', '["v"]', 'to place permanently establish, leave, make, present, put, set, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1870K}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["to/ way/ his"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5523G}/H9011/[H5521]', 'inflected', 'heb', 'סֻכּוֹת', '["Çukkôwth"]', '["Succoth/ towards"]', '["n-pr-loc"]', 'Succoth, the name of a place in Egypt and of three in Palestine Succoth.', 'or סֻכֹּת; plural of 5521; booths;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4735}/H9023/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["and/ for/ livestock/ his"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5521}/[H5520]', 'lemma', 'heb', 'סֻכָּה', '["çukkâh"]', '["[the] booth of","a shelter","booths","shelters"]', '["n-f"]', 'a hut or lair booth, cottage, covert, pavilion, tabernacle, tent.', 'feminine of 5520;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5523G}\/[H5521]', 'inflected', 'heb', 'סֻכּוֹת', '["Çukkôwth"]', '["Succoth"]', '["n-pr-loc"]', 'Succoth, the name of a place in Egypt and of three in Palestine Succoth.', 'or סֻכֹּת; plural of 5521; booths;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0935G}/H9043/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ came/ he","when/ comes/ he","when/ goes/ he","when/ went/ he"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7069}/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["and/ I bought","and/ he bought","and/ it will be bought","and/ you will buy"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2513A}/[H2506]', 'lemma', 'heb', 'חֶלְקָה', '["chelqâh"]', '["[the] portion of","[the] portion of land of","a portion of ground","portion of land"]', '["n-f"]', 'properly, smoothness; figuratively, flattery; also an allotment field, flattering(-ry), ground, parcel, part, piece of land (ground), plat, portion, slippery place, smooth (thing).', 'feminine of 2506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2544}/[H2543]', 'lemma', 'heb', 'חֲמוֹר', '["Chămôwr"]', '["Hamor"]', '["n-pr-m"]', 'Chamor, a Canaanite Hamor.', 'the same as 2543; donkey;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7927H}/[H7926]', 'lemma', 'heb', 'שְׁכֶם', '["Shᵉkem"]', '["Shechem"]', '["n-pr-m n-pr-loc"]', 'Shekem, a place in Palestine Shechem.', 'the same as 7926; ridge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3967}/[H3967]', 'inflected', 'heb', 'מֵאָה', '["mêʼâh"]', '["for/ a hundred","for/ one hundred"]', '["n-f"]', 'a hundred; also as a multiplicative and a fraction hundred((-fold), -th), sixscore.', 'or מֵאיָה; properly, a primitive numeral');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7192>', 'opaque', 'heb', 'קְשִׂיטָה', '["qᵉsîyṭâh"]', '["a piece of money","piece[s] of money"]', '["n-f"]', 'an ingot (as definitely estimated and stamped for a coin) piece of money (silver).', 'from an unused root (probably meaning to weigh out);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0410I}/[H352]', 'lemma', 'heb', 'אֵל', '["ʼêl"]', '["El"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430H}/[H433]', 'lemma', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["Elohe"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3290}\/[H6117]', 'inflected', 'heb', 'יַעֲקֹב', '["Yaʻăqôb"]', '["Israel","Jacob"]', '["n-pr-m"]', 'Jaakob, the Israelitish patriarch Jacob.', 'from 6117; heel-catcher (i.e. supplanter);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1323G}/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["among/ [the] daughters of","in/ [the] daughter of","on/ [the] daughters of"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315G}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["<of> self/ his","appetite/ his","being/ his","being/ its","life/ his","own self/ his","self/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1783}/[H1779]', 'inflected', 'heb', 'דִּינָה', '["Dîynâh"]', '["to/ Dinah"]', '["n-pr-f"]', 'Dinah, the daughter of Jacob Dinah.', 'feminine of 1779; justice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3207}/[H3206]', 'inflected', 'heb', 'יַלְדָּה', '["yaldâh"]', '["the/ girl"]', '["n-f"]', 'a lass damsel, girl.', 'feminine of 3206;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2930A}/[H2930]', 'lemma', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["I have made myself unclean","[are] making yourselves unclean","[has been] made unclean","he had defiled","he has defiled","he has made unclean","he is unclean","he made unclean","he will be unclean","he will make himself unclean","it has become unclean","it has made itself unclean","it is unclean","it will be unclean","it will become unclean","make unclean","making yourselves unclean","people had defiled","she had made herself unclean","she has been declared unclean","she has made herself unclean","she made herself unclean","she will be unclean","surely <declare unclean>","they have made themselves unclean","they have made unclean","they will defile","they will make themselves unclean","they will make unclean","to make unclean","you defile yourselves","you have become unclean","you have defiled","you have made unclean","you have made yourself unclean","you have made yourselves unclean","you made yourself unclean","you make yourselves unclean","you must make unclean","you must make yourselves unclean","you will make unclean","you will make yourselves unclean"]', '["v"]', 'to be foul, especially in a ceremial or moral sense (contaminated) defile (self), pollute (self), be (make, make self, pronounce) unclean, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2790B}/[H2790]', 'inflected', 'heb', 'חָרַשׁ', '["chârash"]', '["and/ he kept silent","and/ he will keep silent","and/ they kept silent","and/ they were silent"]', '["v"]', 'to scratch, i.e. (by implication) to engrave, plough; hence (from the use of tools) to fabricate (of any material); figuratively, to devise (in a bad sense); hence (from the idea of secrecy) to be silent, to let alone; hence (by implication) to be deaf (as an accompaniment of dumbness) × altogether, cease, conceal, be deaf, devise, ear, graven, imagine, leave off speaking, hold peace, plow(-er, man), be quiet, rest, practise secretly, keep silence, be silent, speak not a word, be still, hold tongue, worker.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9048/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["came/ they"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8085G}/H9048/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["when/ heard/ they"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5039}/[H5036]', 'lemma', 'heb', 'נְבָלָה', '["nᵉbâlâh"]', '["a disgraceful folly","disgraceful folly","folly","punishment for folly"]', '["n-f"]', 'foolishness, i.e. (morally) wickedness; concretely, a crime; by extension, punishment folly, vile, villany.', 'feminine of 5036;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3478}/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["<in>/ Israel","[is] in/ Israel","[was] in/ Israel","against/ Israel","among/ Israel","in/ Israel","on/ Israel","over/ Israel","with/ Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7901I}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["by/ lying with","to/ lie"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3651C}/[H3559]', 'inflected', 'heb', 'כֵּן', '["kên"]', '["<and>/ thus","and/ [is] thus","and/ so","and/ thus"]', '["adv"]', 'properly, set upright; hence (figuratively as adjective) just; but usually (as adverb or conjunction) rightly or so (in various applications to manner, time and relation; often with other particles) after that (this, -ward, -wards), as... as, (for-) asmuch as yet, be (for which) cause, following, howbeit, in (the) like (manner, -wise), × the more, right, (even) so, state, straightway, such (thing), surely, there (where) -fore, this, thus, true, well, × you.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2836A}/[H2820]', 'lemma', 'heb', 'חָשַׁק', '["châshaq"]', '["he desired","he loved","he loves","it loves","you loved"]', '["v"]', 'to cling, i.e. join, (figuratively) to love, delight in; elliptically; to deliver have a delight, (have a) desire, fillet, long, set (in) love.', 'a primitive root; also interchangeable for 2820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1323G}/H9026/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["<in>/ daughter/ your"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414O}/[H5414]', 'lemma', 'heb', 'נָתַן', '["nâthan"]', '["I gave","I will give","[one who] gives","gave","give","he had given","he will give","it was given","let it be given","she had been given","she was given","they gave","to give","we will give","you gave [them]","you give","you will give"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2859B}/[H2859]', 'inflected', 'heb', 'חָתַן', '["châthan"]', '["and/ intermarry with"]', '["v"]', 'to give (a daughter) away in marriage; hence (generally) to contract affinity by marriage join in affinity, father in law, make marriages, mother in law, son in law.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1323G}/H9026/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["daughters/ your"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1323G}/H9025/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["daughter/ our","daughters/ our"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0854}/H9035/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ <with the>/ us","and/ [will be] with/ us","and/ with/ us"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440G}/H9026/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ you","[was] <to>/ before/ you","[were] <to>/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5503}/H9034/[H5503]', 'inflected', 'heb', 'סָחַר', '["çâchar"]', '["and/ go about in/ it"]', '["v"]', 'to travel round (specifically as a pedlar); intensively, to palpitate go about, merchant(-man), occupy with, pant, trade, traffick.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0270}/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["and/ bolt [them]","and/ drawn","and/ have possessions","and/ he may hold","and/ hold","and/ it may seize","and/ seize","and/ take hold","so/ it may take hold"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869A}/H9026/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ your","with/ own eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4119}/[H4117]', 'lemma', 'heb', 'מֹהַר', '["môhar"]', '["a bride price"]', '["n-m"]', 'a price (for a wife) dowry.', 'from 4117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4976}/[H5414]', 'inflected', 'heb', 'מַתָּן', '["mattân"]', '["and/ a gift"]', '["n-m"]', 'a present gift, to give, reward.', 'from 5414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6190H}/[H6189]', 'lemma', 'heb', 'עׇרְלָה', '["ʻorlâh"]', '["[the] foreskin of","[the] foreskins of","a foreskin","foreskins of"]', '["n-f"]', 'the prepuce foreskin, uncircumcised.', 'feminine of 6189;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2781}/[H2778]', 'lemma', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["[is] a reproach","[the] reproach of","a reproach","a reproach of","reproach","scorn"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2063}/[H2088]', 'inflected', 'heb', 'זֹאת', '["zôʼth"]', '["by/ this","in/ this","in/ this [battle]","with/ this"]', '["d"]', 'this (often used adverb) hereby (-in, -with), it, likewise, the one (other, same), she, so (much), such (deed), that, therefore, these, this (thing), thus.', 'irregular feminine of 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0225}/[H225]', 'lemma', 'heb', 'אוּת', '["ʼûwth"]', '["let us agree","they will agree","we will agree"]', '["v"]', 'properly, to come, i.e. (implied) to assent consent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3644G}/H9035/[H3651]', 'inflected', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["like/ us"]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4135A}/[H4135]', 'inflected', 'heb', 'מוּל', '["mûwl"]', '["by/ being circumcised","to/ be circumcised"]', '["v"]', 'to cut short, i.e. curtail (specifically the prepuce, i.e. to circumcise); by implication, to blunt; figuratively, to destroy circumcise(-ing), selves), cut down (in pieces), destroy, × must needs.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3190}/[H3190]', 'inflected', 'heb', 'יָטַב', '["yâṭab"]', '["and/ I will do good","and/ he did good","and/ he will do good","and/ it was good","and/ she made good","and/ she was good","and/ they were good","and/ we will do good"]', '["v"]', 'to be (causative) make well, literally (sound, beautiful) or figuratively (happy, successful, right) be accepted, amend, use aright, benefit, be (make) better, seem best, make cheerful, be comely, be content, diligent(-ly), dress, earnestly, find favour, give, be glad, do (be, make) good(-ness), be (make) merry, please ( well), shew more (kindness), skilfully, × very small, surely, make sweet, thoroughly, tire, trim, very, be (can, deal, entreat, go, have) well (said, seen).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5869I}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ in/ [the] eyes of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2654A}/[H2654]', 'lemma', 'heb', 'חָפֵץ', '["châphêts"]', '["I am pleased","I delight","I desire","I desired","I take pleasure","do I take pleasure in","does he delight","he delighted","he delights","he delights in","he desired","he desires","he had desired","he has delighted","he was pleased","he will be willing","he will desire","it has delighted","someone desires","they delight","they delight in","we desire","will he delight","you delight","you desire","you desired","you pleased","you will delight in"]', '["v"]', 'properly, to incline to; by implication (literally but rarely) to bend; figuratively, to be pleased with, desire × any at all, (have, take) delight, desire, favour, like, move, be (well) pleased, have pleasure, will, would.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3513G}/[H3513]', 'lemma', 'heb', 'כָּבַד', '["kâbad"]', '["<he> will be honored","I will be honored","I will gain glory","I will glorify","I will honor","[he was] honored","[is] honored","[the] honored [people] of","[was he] honored","[was] honored","[were the] honored [people] of","be honored","glorify","glorious [things]","he has honored himself","he honors","he is honored","he will be honored","he will honor","he will make honored","honor","honorable","honored","people honor","surely <honor>","they are honored","you are honored","you have gained glory"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7927H}/[H7926]', 'inflected', 'heb', 'שְׁכֶם', '["Shᵉkem"]', '["and/ Shechem"]', '["n-pr-m n-pr-loc"]', 'Shekem, a place in Palestine Shechem.', 'the same as 7926; ridge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5892B}/H9028/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["[were] cities/ their","cities/ their","city/ their"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3427}/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ I sat","and/ [the one who] sits","and/ [the] inhabitant[s] of","and/ [the] inhabitants","and/ [the] inhabitants of","and/ [those who] dwell","and/ dwell","and/ let them dwell","and/ make sit","and/ remain","and/ remaining","and/ sit","and/ sitting","and/ they may dwell","so/ I may dwell","so/ I may sit","so/ let me dwell","so/ they may sit"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5503}/[H5503]', 'inflected', 'heb', 'סָחַר', '["çâchar"]', '["and/ [the] traders of","and/ let them go about in"]', '["v"]', 'to travel round (specifically as a pedlar); intensively, to palpitate go about, merchant(-man), occupy with, pant, trade, traffick.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7342H}/[H7337]', 'lemma', 'heb', 'רָחָב', '["râchâb"]', '["[is] broad","[is] broad of","[was] broad of","broad of","wide"]', '["a"]', 'roomy, in any (or every) direction, literally or figuratively broad, large, at liberty, proud, wide.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027K}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["[the] hand","[the] hand of","[the] hands of","[the] side of","both hands","hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1323G}/H9028/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["daughters/ their"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4135A}/[H4135]', 'inflected', 'heb', 'מוּל', '["mûwl"]', '["when/ has been circumcised"]', '["v"]', 'to cut short, i.e. curtail (specifically the prepuce, i.e. to circumcise); by implication, to blunt; figuratively, to destroy circumcise(-ing), selves), cut down (in pieces), destroy, × must needs.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4735}/H9028/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["livestock/ their"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7075}/H9028/[H7069]', 'inflected', 'heb', 'קִנְיָן', '["qinyân"]', '["and/ possession[s]/ their"]', '["n-m"]', 'creation, i.e. (concretely) creatures; also acquisition, purchase, wealth getting, goods, × with money, riches, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0929>/H9028', 'opaque', 'heb', 'בְּהֵמָה', '["bᵉhêmâh"]', '["animal[s]/ their","cattle/ their","livestock/ their"]', '["n-f"]', 'properly, a dumb beast; especially any large quadruped or animal (often collective) beast, cattle.', 'from an unused root (probably meaning to be mute);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3510}/[H3510]', 'lemma', 'heb', 'כָּאַב', '["kâʼab"]', '["[which] causes pain","he causes pain","in pain","it is in pain","you will spoil"]', '["v"]', 'properly, to feel pain; by implication, to grieve; figuratively, to spoil grieving, mar, have pain, make sad (sore), (be) sorrowful.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3878}/[H3867]', 'inflected', 'heb', 'לֵוִי', '["Lêvîy"]', '["and/ Levi"]', '["n-pr-m"]', 'Levi, a son of Jacob Levi. See also 3879, 3881.', 'from 3867; attached;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2719}/H9023/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["sword/ his"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0983}/[H982]', 'lemma', 'heb', 'בֶּטַח', '["beṭach"]', '["security"]', '["n-m"]', 'properly, a place of refuge; abstract, safety, both the fact (security) and the feeling (trust); often (adverb with or without preposition) safely assurance, boldly, (without) care(-less), confidence, hope, safe(-ly, -ty), secure, surely.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6310G}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["<into>/ a mouth","<to>/ a mouth of","to/ [the] mouth","to/ [the] mouth of","to/ a mouth"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2491A}/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["the/ [one] slain","the/ [ones] slain"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0962}/[H962]', 'inflected', 'heb', 'בָּזַז', '["bâzaz"]', '["and/ he will take as spoil","and/ they plundered","and/ they will be plundered","and/ they will take as spoil"]', '["v"]', 'to plunder catch, gather, (take) for a prey, rob(-ber), spoil, take (away, spoil), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6629G>/H9028', 'opaque', 'heb', 'צֹאן', '["tsôʼn"]', '["flock/ their","flock[s]/ their"]', '["n-f"]', 'a collective name for a flock (of sheep or goats); also figuratively (of men) (small) cattle, flock ( -s), lamb ( -s), sheep(-cote, -fold, -shearer, -herds).', 'or צאוֹן; (Psalm 144:13), from an unused root meaning to migrate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1241}/H9028/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["herd[s]/ their"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2543}/H9028/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["donkeys/ their"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428H}/H9028/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["wealth/ their","wealth<s>/ their"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2945}/H9028/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["little one[s]/ their"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0802H}/H9028/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["wives/ their"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5916}/[H5916]', 'lemma', 'heb', 'עָכַר', '["ʻâkar"]', '["I have troubled","O [one who] troubles","[is] troubling","[one who] troubles","[who] troubled","he has troubled","it was stirred up","trouble","you have troubled"]', '["v"]', 'properly, to roil water; figuratively, to disturb or affict trouble, stir.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0887}/H9030/[H887]', 'inflected', 'heb', 'בָּאַשׁ', '["bâʼash"]', '["by/ making odious/ me"]', '["v"]', 'to smell bad; figuratively, to be offensive morally (make to) be abhorred (had in abomination, loathsome, odious), (cause a, make to) stink(-ing savour), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3427}/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["among/ [the] inhabitant[s] of","when/ dwell","when/ dwelt","with/ [the] inhabitants of"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3669A}/[H3667]', 'inflected', 'heb', 'כְּנַעַנִי', '["Kᵉnaʻanîy"]', '["against the/ Canaanite[s]","among the/ Canaanite[s]"]', '["n-m"]', 'a Kenaanite or inhabitant of Kenaan; by implication, a pedlar (the Canaanites standing for their neighbors the Ishmaelites, who conducted mercantile caravans) Canaanite, merchant, trafficker.', 'patrial from 3667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6522}/[H6521]', 'inflected', 'heb', 'פְּרִזִּי', '["Pᵉrizzîy"]', '["and/ among the/ Perizzite[s]"]', '["a"]', 'a Perizzite, one of the Canaanitish tribes Perizzite.', 'for 6521; inhabitant of the open country;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4962}/[H4970]', 'lemma', 'heb', 'מַת', '["math"]', '["O men of","[am] men of","[the] men of","[will be] men of","men","men of"]', '["n-m"]', 'properly, an adult (as of full length); by implication, a man (only in the plural) few, × friends, men, persons, × small.', 'from the same as 4970;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4557}/[H5608]', 'lemma', 'heb', 'מִסְפָּר', '["miçpâr"]', '["[are] [the] number of","[are] [the] numbers of","[is] a number","[is] number","[the] number","[the] number of","[the] recounting of","[was] a measure","[was] a number","[was] number","[were] [the] number of","a number","a number of","number"]', '["n-m"]', 'a number, definite (arithmetical) or indefinite (large, innumerable; small, a few); also (abstractly) narration abundance, account, × all, × few, (in-) finite, (certain) number(-ed), tale, telling, time.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8045}/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["and/ I destroyed","and/ I will be destroyed","and/ I will destroy","and/ he destroyed","and/ it will be destroyed","and/ they will be destroyed"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004M}/H9020/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ household/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9004/{H2181}/[H2181]', 'inflected', 'heb', 'זָנָה', '["zânâh"]', '["¿/ like/ a prostitute"]', '["v"]', 'to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish.', 'a primitive root [highly fed and therefore wanton];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0269}/H9025\/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["sister/ our"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0410G}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["<to> <the>/ God","for <the>/ God","for/ [the] God","to <the>/ God","to the/ God","to/ God","to/ [the] God of"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1272}/H9041/[H1272]', 'inflected', 'heb', 'בָּרַח', '["bârach"]', '["when/ fleeing/ you"]', '["v"]', 'to bolt, i.e. figuratively, to flee suddenly chase (away); drive away, fain, flee (away), put to flight, make haste, reach, run away, shoot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430J}/[H433]', 'lemma', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["[are] gods","[the] gods","[the] gods of","[were] [the] gods of","[were] gods","gods","gods of"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5236}/[H5234]', 'inflected', 'heb', 'נֵכָר', '["nêkâr"]', '["<the>/ foreignness"]', '["n-m"]', 'foreign, or (concretely) a foreigner, or (abstractly) heathendom alien, strange ( -er).', ''' from 5234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2891}/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["and/ [one who] purifies","and/ be clean","and/ purify yourselves","so/ I may be pure"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2498}/[H2498]', 'inflected', 'heb', 'חָלַף', '["châlaph"]', '["and/ change","and/ he may pass on","and/ they may pass away"]', '["v"]', 'properly, to slide by, i.e. (by implication) to hasten away, pass on, spring up, pierce or change abolish, alter, change, cut off, go on forward, grow up, be over, pass (away, on, through), renew, sprout, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8071}/H9026/[H5566]', 'inflected', 'heb', 'שִׂמְלָה', '["simlâh"]', '["clothes/ your"]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5927G}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ bring up","and/ come up","and/ go up","and/ he may go up","and/ let him go up","and/ we may go up","so/ he may go up","so/ may it come up","so/ they may come up","so/ we may go up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6030B}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["who/ answered","who/ had answered"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6869B}/H9020/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["distress/ my","trouble/ my"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027I}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[were] in/ hand/ their","by/ hand/ their","in/ hand/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241G}/H9028/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["[were] in/ ears/ their","[were] on/ ears/ their"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2934}/[H2934]', 'inflected', 'heb', 'טָמַן', '["ṭâman"]', '["and/ he hid","and/ they hid [them]"]', '["v"]', 'to hide (by covering over) hide, lay privily, in secret.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0424}/[H352]', 'inflected', 'heb', 'אֵלָה', '["ʼêlâh"]', '["the/ oak"]', '["n-f"]', 'an oak or other strong tree elm, oak, teil-tree.', 'feminine of 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2847}/[H2865]', 'lemma', 'heb', 'חִתָּה', '["chittâh"]', '["[the] terror of"]', '["n-f"]', 'fear terror.', 'from 2865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439G}/H9038/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["[was] around/ them","[were] around/ them","around/ them"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7291}/[H7291]', 'lemma', 'heb', 'רָדַף', '["râdaph"]', '["I pursued","I will pursue","O [those who] pursue","[am] pursuing","[is one who] pursues","[one who] pursues","[those who] pursue","[was] pursuing","[what] was pursued","he has pursued","he pursued","he puts to flight","he should pursue","he will pursue","it pursues","let me pursue","let us pursue","may he pursue","people pursued","pursue","pursuing","someone pursues","they have harassed","they pursue","they pursued","they will pursue","we have been pursued","will I pursue?","will he pursue","will we persecute","will you pursue?","you will pursue","you will pursue [them]"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3870H}/H9011/[H3869]', 'inflected', 'heb', 'לוּז', '["Lûwz"]', '["Luz/ <towards>","Luz/ towards"]', '["n-pr-loc"]', 'Luz, the name of two places in Palestine Luz.', 'probably from 3869 (as growing there);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0416}/[H410]', 'lemma', 'heb', 'אֵל בֵּית־אֵל', '["ʼÊl Bêyth-ʼÊl"]', '["-el","Beth-","El"]', '["n-pr-loc"]', 'El-Bethel, the title given to a consecrated spot by Jacob El-beth-el.', 'from 410 and 1008; the God of Bethel;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1540H}/[H1540]', 'lemma', 'heb', 'גָּלָה', '["gâlâh"]', '["I have made known","I will uncover","[he is] revealing","[is one who] opens","[is] revealing","[is] uncovering","did I reveal myself","has it been revealed","he had uncovered","he has revealed","he revealed himself","he uncovers","he will make known","it has been revealed","it was revealed","it was uncovered","it will be revealed","they had revealed themselves","they uncovered","they will reveal","you expose","you have uncovered","you reveal"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1272}/H9043/[H1272]', 'inflected', 'heb', 'בָּרַח', '["bârach"]', '["when/ fled/ he"]', '["v"]', 'to bolt, i.e. figuratively, to flee suddenly chase (away); drive away, fain, flee (away), put to flight, make haste, reach, run away, shoot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1683G}/[H1682]', 'lemma', 'heb', 'דְּבּוֹרָה', '["Dᵉbôwrâh"]', '["Deborah"]', '["n-pr-f"]', 'Deborah, the name of two Hebrewesses Deborah.', 'or (shortened) דְּבֹרָה; the same as 1682;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3243I}/[H3243]', 'lemma', 'heb', 'יָנַק', '["yânaq"]', '["[the] suckling-nurse of","a suckling-nurse"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0437}/[H436]', 'inflected', 'heb', 'אַלּוֹן', '["ʼallôwn"]', '["the/ oak"]', '["n-m"]', 'oak.', 'a variation of 436');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0439}/[H437]', 'lemma', 'heb', 'אַלּוֹן בָּכוּת', '["ʼAllôwn Bâkûwth"]', '["Allon"]', '["n-pr-loc"]', 'Allon-Bakuth, a monumental tree Allon-bachuth.', 'from 437 and a variation of 1068; oak of weeping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0439}\/[H437]', 'inflected', 'heb', 'אַלּוֹן בָּכוּת', '["ʼAllôwn Bâkûwth"]', '["Bacuth"]', '["n-pr-loc"]', 'Allon-Bakuth, a monumental tree Allon-bachuth.', 'from 437 and a variation of 1068; oak of weeping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6951}/[H6950]', 'inflected', 'heb', 'קָהָל', '["qâhâl"]', '["and/ a company","and/ a company of"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2504}/H9021/[H2502]', 'inflected', 'heb', 'חָלָץ', '["châlâts"]', '["from/ loins/ your"]', '["n-f"]', 'the loins (as the seat of vigor) loins, reins.', 'from 2502 (in the sense of strength); only in the dual;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3327}/[H6711]', 'inflected', 'heb', 'יִצְחָק', '["Yitschâq"]', '["and/ to/ Isaac"]', '["n-pr-m"]', 'Jitschak (or Isaac), son of Abraham Isaac. Compare 3446.', 'from 6711; laughter (i.e. mochery);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5921A}/H9033/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["from/ on <the>/ him","from/ on <the>/ himself","from/ on <the>/ it","from/ towards <the>/ him","from/ with <the>/ him"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4678}/[H5324]', 'lemma', 'heb', 'מַצֶּבֶת', '["matstsebeth"]', '["[is] [the] pillar of","a pillar","a pillar of","a stump"]', '["n-f"]', 'something stationary, i.e. a monumental stone; also the stock of a tree pillar, substance.', 'from 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5258A}/[H5258]', 'inflected', 'heb', 'נָסַךְ', '["nâçak"]', '["and/ he poured out","and/ they poured out"]', '["v"]', 'to pour out, especially a libation, or to cast (metal); by analogy, to anoint a king cover, melt, offer, (cause to) pour (out), set (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5262}/[H5258]', 'lemma', 'heb', 'נֶסֶךְ', '["neçek"]', '["a drink offering","a drink offering of","drink offerings"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1008G}/[H1004]', 'inflected', 'heb', 'בֵּית־אֵל', '["Bêyth-ʼÊl"]', '["from/ Beth-"]', '["n-pr-loc"]', 'Beth-El, a place in Palestine Beth-el.', 'from 1004 and 410; house of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3530}/[H3528]', 'lemma', 'heb', 'כִּבְרָה', '["kibrâh"]', '["[the] distance of","a distance of"]', '["n-f"]', 'properly, length, i.e. a measure (of uncertain dimension) × little.', 'feminine of 3528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0935I}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["to/ [the] entrance of","to/ go"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0672H}/[H6509]', 'lemma', 'heb', 'אֶפְרָת', '["ʼEphrâth"]', '["Ephrath","Ephrathah"]', '["n-pr"]', 'Ephrath, another name for Bethlehem; once (Psalm 132:6) perhaps for Ephraim; also of an Israelitish woman; Ephrath, Ephratah.', 'or אֶפְרָתָה; from 6509; fruitfulness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7185}/[H7185]', 'inflected', 'heb', 'קָשָׁה', '["qâshâh"]', '["and/ he made stiff","and/ it was hard","and/ she had difficulties","and/ they stiffened"]', '["v"]', 'properly, to be dense, i.e. tough or severe (in various applications) be cruel, be fiercer, make grievous, be ((ask a), be in, have, seem, would) hard(-en, (labour), -ly, thing), be sore, (be, make) stiff(-en, (-necked)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3205}/H9044/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["when/ bore/ she","when/ gave birth/ she"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7185}/H9044/[H7185]', 'inflected', 'heb', 'קָשָׁה', '["qâshâh"]', '["when/ had difficulties/ she"]', '["v"]', 'properly, to be dense, i.e. tough or severe (in various applications) be cruel, be fiercer, make grievous, be ((ask a), be in, have, seem, would) hard(-en, (labour), -ly, thing), be sore, (be, make) stiff(-en, (-necked)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3318G}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ came out","when/ had gone out","when/ went out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315G}/H9024/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["life/ her"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1126}/[H1121]', 'lemma', 'heb', 'בֶּן־אוֹנִי', '["Ben-ʼÔwnîy"]', '["Ben-","Oni"]', '["n-pr-m"]', 'Ben-Oni, the original name of Benjamin Ben-oni.', 'from 1121 and 205; son of my sorrow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0001G}/H9023/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ father/ his"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1144G}/[H1121]', 'lemma', 'heb', 'בִּנְיָמִין', '["Binyâmîyn"]', '["Benjamin","O Benjamin","of Benjamin"]', '["n-pr-m"]', 'Binjamin, youngest son of Jacob; also the tribe descended from him, and its territory Benjamin.', 'from 1121 and 3225; son of (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1035G}/[H1004]', 'lemma', 'heb', 'בֵּית לֶחֶם', '["Bêyth Lechem"]', '["-lehem","Beth-","O Beth-","[is] Beth-","[was] Beth-"]', '["n-pr-loc"]', 'Beth-Lechem, a place in Palestine Bethlehem.', 'from 1004 and 3899; house of bread;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6900}/H9024/[H6912]', 'inflected', 'heb', 'קְבוּרָה', '["qᵉbûwrâh"]', '["grave/ her","grave/ its"]', '["n-f"]', 'sepulture; (concretely) a sepulchre burial, burying place, grave, sepulchre.', 'or קְבֻרָה; feminine passive participle of 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6900}/[H6912]', 'lemma', 'heb', 'קְבוּרָה', '["qᵉbûwrâh"]', '["[the] burial of","[the] grave of","[the] tomb of","burial"]', '["n-f"]', 'sepulture; (concretely) a sepulchre burial, burying place, grave, sepulchre.', 'or קְבֻרָה; feminine passive participle of 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1973}/[H1973]', 'inflected', 'heb', 'הָלְאָה', '["hâlᵉʼâh"]', '["from/ beyond"]', '["adv"]', 'to the distance, i.e. far away; also (of time) thus far back, beyond, (hence,-) forward, hitherto, thence, forth, yonder.', 'from the primitive form of the article (hal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4029}/[H4026]', 'inflected', 'heb', 'מִגְדַּל־עֵדֶר', '["Migdal-ʻÊder"]', '["<to>/ Migdal"]', '["n"]', 'Migdal-Eder, a place in Palestine Migdal-eder, tower of the flock.', 'from 4026 and 5739; tower of a flock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4029}/[H4026]', 'lemma', 'heb', 'מִגְדַּל־עֵדֶר', '["Migdal-ʻÊder"]', '["Eder","O Migdal"]', '["n"]', 'Migdal-Eder, a place in Palestine Migdal-eder, tower of the flock.', 'from 4026 and 5739; tower of a flock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7931}/[H7901]', 'inflected', 'heb', 'שָׁכַן', '["shâkan"]', '["when/ dwelt"]', '["v"]', 'to reside or permanently stay (literally or figuratively) abide, continue, (cause to, make to) dwell(-er), have habitation, inhabit, lay, place, (cause to) remain, rest, set (up).', 'a primitive root (apparently akin (by transmission) to 7901 through the idea of lodging; compare 5531, 7925);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6370>', 'opaque', 'heb', 'פִּילֶגֶשׁ', '["pîylegesh"]', '["[the] concubine of","[the] concubines of","a concubine","concubines"]', '["n-f"]', 'a concubine; also (masculine) a paramour concubine, paramour.', 'or פִּלֶגֶשׁ; of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3478}\/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8095G}/[H8085]', 'inflected', 'heb', 'שִׁמְעוֹן', '["Shimʻôwn"]', '["and/ Simeon"]', '["n-pr-m"]', 'Shimon, one of Jacob''s sons, also the tribe descended from him Simeon.', 'from 8085; hearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3063G}/[H3034]', 'inflected', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["and/ Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3485G}/[H5375]', 'inflected', 'heb', 'יִשָּׂשכָר', '["Yissâˢkâr"]', '["and/ Issachar"]', '["n-pr"]', 'Jissaskar, a son of Jacob Issachar.', '(strictly yis-saws-kawr''); from 5375 and 7939; he will bring a reward;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2074}/[H2082]', 'inflected', 'heb', 'זְבוּלוּן', '["Zᵉbûwlûwn"]', '["and/ Zebulun"]', '["n-pr-m n-pr-loc"]', 'Zebulon, a son of Jacob; also his territory and tribe Zebulun.', 'or זְבֻלוּן; or זְבוּלֻן; from 2082; habitation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1144G}/[H1121]', 'inflected', 'heb', 'בִּנְיָמִין', '["Binyâmîyn"]', '["and/ Benjamin"]', '["n-pr-m"]', 'Binjamin, youngest son of Jacob; also the tribe descended from him, and its territory Benjamin.', 'from 1121 and 3225; son of (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5321G}/[H6617]', 'inflected', 'heb', 'נַפְתָּלִי', '["Naphtâlîy"]', '["and/ Naphtali"]', '["n-pr-m n-pr-loc"]', 'Naphtali, a son of Jacob, with the tribe descended from him, and its territory Naphtali.', 'from 6617; my wrestling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0836}/[H833]', 'inflected', 'heb', 'אָשֵׁר', '["ʼÂshêr"]', '["and/ Asher"]', '["n-pr"]', 'Asher, a son of Jacob, and the tribe descended from him, with its territory; also a place in Palestine Asher', 'from 833, happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121A}/H9023\/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["son/ his","sons/ his"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5711H}/[H5710]', 'lemma', 'heb', 'עָדָה', '["ʻÂdâh"]', '["Adah"]', '["n-pr-f"]', 'Adah, the name of two women Adah.', 'from 5710; ornament;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0173}/[H168]', 'lemma', 'heb', 'אׇהֳלִיבָמָה', '["ʼOhŏlîybâmâh"]', '["Oholibamah"]', '["n"]', 'Oholibamah, a wife of Esau Aholibamah.', 'from 168 and 1116; tent of (the) height;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6034}/[H6030]', 'lemma', 'heb', 'עֲנָה', '["ʻĂnâh"]', '["Anah","[was] Anah"]', '["n-pr-m n-pr-f"]', 'Anah, the name of two Edomites and one Edomitess Anah.', 'probably from 6030; an answer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6649G}/[H6648]', 'lemma', 'heb', 'צִבְעוֹן', '["Tsibʻôwn"]', '["Zibeon"]', '["n-pr-m"]', 'Tsibon, an Idumaean Zibeon.', 'from the same as 6648; variegated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1315I}/[H1314]', 'lemma', 'heb', 'בׇּשְׂמַת', '["Bosmath"]', '["Basemath"]', '["n-pr-f"]', 'Bosmath, the name of a wife of Esau, and of a daughter of Solomon Bashemath, Basmath.', 'feminine of 1314 (the second form); fragrance;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0464G}/[H410]', 'lemma', 'heb', 'אֱלִיפַז', '["ʼĔlîyphaz"]', '["Eliphaz"]', '["n-pr-m"]', 'Eliphaz, the name of one of Job''s friends, and of a son of Esau Eliphaz.', 'from 410 and 6337; God of gold;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1315I}/[H1314]', 'inflected', 'heb', 'בׇּשְׂמַת', '["Bosmath"]', '["and/ Basemath"]', '["n-pr-f"]', 'Bosmath, the name of a wife of Esau, and of a daughter of Solomon Bashemath, Basmath.', 'feminine of 1314 (the second form); fragrance;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7467G}/[H7466]', 'lemma', 'heb', 'רְעוּאֵל', '["Rᵉʻûwʼêl"]', '["Reuel"]', '["n-pr-m"]', 'Reuel, the name of Moses'' father-in-law, also of an Edomite and an Israelite Raguel, Reuel.', 'from the same as 7466 and 410; friend of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0173}/[H168]', 'inflected', 'heb', 'אׇהֳלִיבָמָה', '["ʼOhŏlîybâmâh"]', '["and/ Oholibamah"]', '["n"]', 'Oholibamah, a wife of Esau Aholibamah.', 'from 168 and 1116; tent of (the) height;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3266G}/[H5789]', 'lemma', 'heb', 'יְעוּשׁ', '["Yᵉʻûwsh"]', '["Jeush"]', '["n-pr-m"]', 'Jeush, the name of an Edomite and of four Israelites Jehush, Jeush. Compare 3274.', 'from 5789; hasty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3281}/[H5956]', 'lemma', 'heb', 'יַעְלָם', '["Yaʻlâm"]', '["Jalam"]', '["n-pr-m"]', 'Jalam, an Edomite Jalam.', 'from 5956; occult;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7141G}/[H7139]', 'lemma', 'heb', 'קֹרַח', '["Qôrach"]', '["Korah"]', '["n-pr-m"]', 'Korach, the name of two Edomites and three Israelites Korah.', 'from 7139; ice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315J}/[H5314]', 'lemma', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["<of> a person","<the> person of","[the] people of","[were] person[s]","a life","a person","a person of","an appetite","anyone","life","life of","people","person","person[s]","persons","persons of","self"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0929>/H9023', 'opaque', 'heb', 'בְּהֵמָה', '["bᵉhêmâh"]', '["animal[s]/ his","animals/ his"]', '["n-f"]', 'properly, a dumb beast; especially any large quadruped or animal (often collective) beast, cattle.', 'from an unused root (probably meaning to be mute);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3427}/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["for/ [the] inhabitant[s]","for/ dwelling","from/ [the] inhabitants of","from/ dwelling","of/ [the] inhabitants of"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4033}/H9028/[H1481]', 'inflected', 'heb', 'מָגוּר', '["mâgûwr"]', '["sojournings/ their"]', '["n-m"]', 'a temporary abode; by extension, a permanent residence dwelling, pilgrimage, where sojourn, be a stranger. Compare 4032.', 'or מָגֻר; from 1481 in the sense of lodging;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5375K}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["to/ support"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8487G}/[H8486]', 'lemma', 'heb', 'תֵּימָן', '["Têymân"]', '["Teman"]', '["n-pr-m n-pr-loc"]', 'Teman, the name of two Edomites, and of the region and descendant of one of them south, Teman.', 'or תֵּמָן; the same as 8486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0201}/[H559]', 'lemma', 'heb', 'אוֹמָר', '["ʼÔwmâr"]', '["Omar"]', '["n-pr-m"]', 'Omar, a grandson of Esau Omar.', 'from 559; talkative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6825}/[H6822]', 'lemma', 'heb', 'צְפוֹ', '["Tsᵉphôw"]', '["Zephi","Zepho"]', '["n-pr-m"]', 'Tsepho or Tsephi, an Idumaean Zephi, Zepho.', 'or צְפִי; from 6822; observant;');
