INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4427A}/[H4427]', 'lemma', 'heb', 'מָלַךְ', '["mâlak"]', '["I have made king","I will become king","I will reign","[was] reigning","[who] reigns","certainly <to reign>","has he become king","he became king","he had become king","he had been made king","he had made king","he has become king","he has made king","he is king","he made king","he reigned","he reigns","he will become king","he will reign","reign","reigned","she will reign","they have made kings","they reign","they reigned","we will make king","will he reign?","will you reign","you have made king","you have reigned","you will reign"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4427A}/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["and/ I have made king","and/ he became king","and/ he made king","and/ he reigned","and/ he will reign","and/ they made king","and/ they reigned","and/ you have made king","and/ you will make king","and/ you will reign"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0123G}/[H122]', 'inflected', 'heb', 'אֱדֹם', '["ʼĔdôm"]', '["in/ Edom","on/ Edom","with/ Edom"]', '["n-pr-m"]', 'Edom, the elder twin-brother of Jacob; hence the region (Idumaea) occupied by him Edom, Edomites, Idumea.', 'or (fully) אֱדוֹם ; from 122; red (see Genesis 25:25);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1106G}/[H1105]', 'lemma', 'heb', 'בֶּלַע', '["Belaʻ"]', '["Bela"]', '["n-pr-m n-pr-loc"]', 'Bela, the name of a place, also of an Edomite and of two Israelites Bela.', 'the same as 1105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1160G}/[H1197]', 'lemma', 'heb', 'בְּעוֹר', '["Bᵉʻôwr"]', '["Beor"]', '["n-pr-m"]', 'Beor, the name of the father of an Edomitish king; also of that of Balaam Beor.', 'from 1197 (in the sense of burning); a lamp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1838>', 'opaque', 'heb', 'דִּנְהָבָה', '["Dinhâbâh"]', '["[was] Dinhabah"]', '["n-pr-loc"]', 'Dinhabah, an Edomitish town Dinhaban.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478H}/H9033/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["in place of/ him","in place of/ it","in place/ his"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3103H}/[H2980]', 'lemma', 'heb', 'יוֹבָב', '["Yôwbâb"]', '["Jobab"]', '["n-pr-m"]', 'Jobab, the name of two Israelites and of three foreigners Jobab.', 'from 2980; howler;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2226H}/[H2225]', 'lemma', 'heb', 'זֶרַח', '["Zerach"]', '["Zerah"]', '["n-pr-m"]', 'Zerach, the name of three Israelites, also of an Idumaean and an Ethiopian prince Zarah, Zerah.', 'the same as 2225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1224G}/[H1223]', 'inflected', 'heb', 'בׇּצְרָה', '["Botsrâh"]', '["from/ Bozrah"]', '["n-pr-loc"]', 'Botsrah, a place in Edom Bozrah.', 'the same as 1223;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2367}/[H2363]', 'lemma', 'heb', 'חוּשָׁם', '["Chûwshâm"]', '["Husham"]', '["n-pr-m"]', 'Chusham, an Idumaean Husham.', 'or חֻשָׁם; from 2363; hastily;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8489}/[H8487]', 'inflected', 'heb', 'תֵּימָנִי', '["Têymânîy"]', '["the/ Temanite","the/ Temanite[s]"]', '["n-pr-m"]', 'a Temanite or descendant of Teman Temani, Temanite.', 'patronymically from 8487;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1908G>', 'opaque', 'heb', 'הֲדַד', '["Hădad"]', '["Hadad"]', '["n-pr-m"]', 'Hadad, the name of an idol, and of several kings of Edom Hadad.', 'probably of foreign origin (compare 111);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0911}/[H909]', 'lemma', 'heb', 'בְּדַד', '["Bᵉdad"]', '["Bedad"]', '["n-pr-m"]', 'Bedad, an Edomite Bedad.', 'from 909; separation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5221}/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["the/ [one who] struck","those/ [who] had struck down","which/ had defeated","who/ defeated","who/ had struck down","who/ struck","who/ struck down","who/ was striking down","who/ was struck down"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4080H}/[H4079]', 'lemma', 'heb', 'מִדְיָן', '["Midyân"]', '["Midian"]', '["n-pr-m n-pr-loc"]', 'Midjan, a son of Abraham; also his country and (collectively) his descendants Midian, Midianite.', 'the same as 4079;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4124G}/[H1]', 'lemma', 'heb', 'מוֹאָב', '["Môwʼâb"]', '["Moab","O Moab","of Moab"]', '["n-pr-m n-pr-loc"]', 'Moab, an incestuous son of Lot; also his territory and descendants Moab.', 'from a prolonged form of the prepositional prefix m- and 1; from (her [the mother''s]) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5762}/[H5857]', 'lemma', 'heb', 'עֲוִית', '["ʻĂvîyth"]', '["[was] Avith"]', '["n-pr-loc"]', 'Avvith (or Avvoth), a place in Palestine Avith.', 'or perhaps (עַיּוֹת (as if plural of 5857) (עַיוּת; from 5753; ruin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8072}/[H8071]', 'lemma', 'heb', 'שַׂמְלָה', '["Samlâh"]', '["Samlah"]', '["n-pr-m"]', 'Samlah, an Edomite Samlah.', 'probably for the same as 8071;');
