INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5907G}/[H5909]', 'lemma', 'heb', 'עַכְבּוֹר', '["ʻAkbôwr"]', '["Achbor"]', '["n-pr-m"]', 'Akbor, the name of an Idumaean and of two Israelites Achbor.', 'probably for 5909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1924}/[H1926]', 'lemma', 'heb', 'הֲדַר', '["Hădar"]', '["Hadar"]', '["n-pr-m"]', 'Hadar, an Edomite Hadar.', 'the same as 1926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6464}/[H6463]', 'lemma', 'heb', 'פָּעוּ', '["Pâʻûw"]', '["[was] Pai","[was] Pau"]', '["n-pr-loc"]', 'Pau or Pai, a place in Edom Pai, Pau.', 'or פָּעִי; from 6463; screaming;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4105G}/[H3190]', 'lemma', 'heb', 'מְהֵיטַבְאֵל', '["Mᵉhêyṭabʼêl"]', '["[was] Mehetabel"]', '["n-pr-m n-pr-f"]', 'Mehetabel, the name of an Edomitish man and woman Mehetabeel, Mehetabel.', 'from 3190 (augmented) and 410; bettered of God;');
