INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4314}/[H4325]', 'lemma', 'heb', 'מֵי זָהָב', '["Mêy Zâhâb"]', '["Me-","Zahab"]', '["n-pr-m"]', 'Me-Zahab, an Edomite Mezahab.', 'from 4325 and 2091, water of gold;');
