INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4725}/H9028/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["to/ own place/ their","to/ place/ their","to/ places/ their"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5933}/[H5932]', 'lemma', 'heb', 'עַלְוָה', '["ʻAlvâh"]', '["Alvah"]', '["n-pr-m"]', 'Alvah or Aljah, an Idumaean Aliah, Alvah.', 'or עַליָה; the same as 5932;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3509>', 'opaque', 'heb', 'יְתֵת', '["Yᵉthêth"]', '["Jetheth"]', '["n-pr-m"]', 'Jetheth, an Edomite Jetheth.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0425G}/[H424]', 'lemma', 'heb', 'אֵלָה', '["ʼÊlâh"]', '["Elah"]', '["n-pr"]', 'Elah, the name of an Edomite, of four Israelites, and also of a place in Palestine Elah.', 'the same as 424;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6373}/[H6325]', 'lemma', 'heb', 'פִּינֹן', '["pîynôn"]', '["Pinon"]', '["n-pr-m"]', 'Pinon, an Idumaean Pinon.', 'probably the same as 6325;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4014}/[H4013]', 'lemma', 'heb', 'מִבְצָר', '["Mibtsâr"]', '["Mibzar"]', '["n-pr-m"]', 'Mibtsar, an Idumaean Mibzar.', 'the same as 4013;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4025}/[H4022]', 'lemma', 'heb', 'מַגְדִּיאֵל', '["Magdîyʼêl"]', '["Magdiel"]', '["n-pr-m"]', 'Magdiel, an Idumaean Magdiel.', 'from 4022 and 410; preciousness of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5902}/[H5892]', 'lemma', 'heb', 'עִירָם', '["ʻÎyrâm"]', '["Iram"]', '["n-pr-m"]', 'Iram, an Idumaean Iram.', 'from 5892; city-wise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4186}/H9028/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["to/ dwelling places/ their"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0272}/H9028/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["[am] possession/ their","[is] possession/ their","[will be] possession/ their","possession/ their"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0123G}\/[H122]', 'inflected', 'heb', 'אֱדֹם', '["ʼĔdôm"]', '["Edom"]', '["n-pr-m"]', 'Edom, the elder twin-brother of Jacob; hence the region (Idumaea) occupied by him Edom, Edomites, Idumea.', 'or (fully) אֱדוֹם ; from 122; red (see Genesis 25:25);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4033}/[H1481]', 'lemma', 'heb', 'מָגוּר', '["mâgûwr"]', '["[the] sojournings of"]', '["n-m"]', 'a temporary abode; by extension, a permanent residence dwelling, pilgrimage, where sojourn, be a stranger. Compare 4032.', 'or מָגֻר; from 1481 in the sense of lodging;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5288}/[H5287]', 'lemma', 'heb', 'נַעַר', '["naʻar"]', '["[am] a lad","[am] a young man","[am] a youth","[are] a youth","[is] a youth","[the] lad of","[the] servant of","[the] servants of","[the] young men of","[was] a lad","[was] a young man","[was] a youth","a lad","a young man","a youth","young man","young men","youth","youths"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1681}/H9028/[H1680]', 'inflected', 'heb', 'דִּבָּה', '["dibbâh"]', '["report/ their"]', '["n-f"]', 'slander defaming, evil report, infamy, slander.', 'from 1680 (in the sense of furtive motion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3478}/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["and/ Israel","and/ O Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2208}/[H2204]', 'lemma', 'heb', 'זָקֻן', '["zâqun"]', '["old age<s>"]', '["n-m"]', 'old age old age.', 'properly, passive participle of 2204 (used only in the plural as a noun);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6446}/[H6461]', 'lemma', 'heb', 'פַּס', '["paç"]', '["palms and soles"]', '["n-m"]', 'a long and sleeved tunic (perhaps simply a wide one; from the original sense of the root, i.e. of many breadths) (divers) colours.', 'from 6461; properly, the palm (of the hand) or sole (of the foot) (compare 6447); by implication (plural)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8130}/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["and/ I hated","and/ they hated","and/ you have hated"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1696G}/H9033/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["he has spoken/ it","to speak to/ him"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7965G}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["for/ peace","of/ peace","to/ peace","to/ welfare"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2472}/[H2492]', 'lemma', 'heb', 'חֲלוֹם', '["chălôwm"]', '["<of> dreams of","[is] dream","[it was] a dream","[the] dream","[the] dream of","a dream","dreams"]', '["n-m"]', 'a dream dream(-er).', 'or (shortened) חֲלֹם; from 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2472}/[H2492]', 'inflected', 'heb', 'חֲלוֹם', '["chălôwm"]', '["<the>/ dreams","[is] the/ dream","the/ dream","the/ dreams"]', '["n-m"]', 'a dream dream(-er).', 'or (shortened) חֲלֹם; from 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2492B}/[H2492]', 'lemma', 'heb', 'חָלַם', '["châlam"]', '["I have dreamed","[are] dreaming","[the] dreamer of","[was] dreaming","a dreamer of","he dreamed","he dreams","he had dreamed","we dreamed","you have dreamed"]', '["v"]', 'properly, to bind firmly, i.e. (by implication) to be (causatively to make) plump; also (through the figurative sense of dumbness) to dream (cause to) dream(-er), be in good liking, recover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0481}/[H481]', 'lemma', 'heb', 'אָלַם', '["ʼâlam"]', '["I am dumb","I was dumb","[were] binding","it is dumb","may they be dumb","you will be dumb"]', '["v"]', 'to tie fast; hence (of the mouth) to be tongue-tied bind, be dumb, put to silence.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0485}/[H481]', 'lemma', 'heb', 'אֲלֻמָּה', '["ʼălummâh"]', '["sheaves"]', '["n-f"]', 'something bound; a sheaf sheaf.', 'or (masculine) אָלֻם; passive participle of 481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0485}/H9020/[H481]', 'inflected', 'heb', 'אֲלֻמָּה', '["ʼălummâh"]', '["sheaf/ my"]', '["n-f"]', 'something bound; a sheaf sheaf.', 'or (masculine) אָלֻם; passive participle of 481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5437G}/[H5437]', 'lemma', 'heb', 'סָבַב', '["çâbab"]', '["I have turned","I turned","changed","go around","he turned","he turned round","he will turn","it has been turned over","it is turned","it turned around","it turns","it went round","it will change","it will come round","it will go about","let it go round","surrounded","they gathered round","they had brought round","they have brought round","they turned","turn","turn round","turning","we will turn round","you have turned around","you will turn around"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0485}/H9026/[H481]', 'inflected', 'heb', 'אֲלֻמָּה', '["ʼălummâh"]', '["sheaves/ your"]', '["n-f"]', 'something bound; a sheaf sheaf.', 'or (masculine) אָלֻם; passive participle of 481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0485}/H9020/[H481]', 'inflected', 'heb', 'אֲלֻמָּה', '["ʼălummâh"]', '["to/ sheaf/ my"]', '["n-f"]', 'something bound; a sheaf sheaf.', 'or (masculine) אָלֻם; passive participle of 481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4427A}/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["¿/ are you king","¿/ really <to reign>"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9035}', 'inflected', 'heb', 'בנו', '["Ba./nu","Va./nu","ba./nu"]', '["<in> <the>/ us","<in>/ us","[are] among/ us","against <the>/ us","against/ us","among <the>/ us","by <the>/ us","in <the>/ us","in/ us","on <the>/ us","on/ us","over <the>/ us","over/ us","with/ us"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2472}/H9023/[H2492]', 'inflected', 'heb', 'חֲלוֹם', '["chălôwm"]', '["dream/ his","dreams/ his","own dream/ his"]', '["n-m"]', 'a dream dream(-er).', 'or (shortened) חֲלֹם; from 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697G}/H9023/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<of> word/ his","own word/ his","word/ his","words/ his"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3394}/[H3391]', 'inflected', 'heb', 'יָרֵחַ', '["yârêach"]', '["and/ the/ moon"]', '["n-m"]', 'the moon moon. Yrechow. See 3405.', 'from the same as 3391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0259}/[H258]', 'inflected', 'heb', 'אֶחָד', '["ʼechâd"]', '["and/ one","and/ one [hand]","and/ one [plus]","and/ one [time]","and/ one of"]', '["a"]', 'properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,', 'a numeral from 258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3556}/[H3522]', 'lemma', 'heb', 'כּוֹכָב', '["kôwkâb"]', '["[the] star of","[the] stars","[the] stars of","a star","stars"]', '["n-m"]', 'a star (as round or as shining); figuratively, a prince star(-gazer).', 'probably from the same as 3522 (in the sense of rolling) or 3554 (in the sense of blazing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7812}/[H7812]', 'lemma', 'heb', 'שָׁחָה', '["shâchâh"]', '["I bow down","I will bow down","[are] bowing down","[was] bowing down","[were] bowing down","bow down","he bowed down","let us bow down","lie down","they bow down","they bowed down","they will bow down","you must bow down","you will bow down"]', '["v"]', 'to depress, i.e. prostrate (especially reflexive, in homage to royalty or God) bow (self) down, crouch, fall down (flat), humbly beseech, do (make) obeisance, do reverence, make to stoop, worship.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1605}/[H1605]', 'inflected', 'heb', 'גָּעַר', '["gâʻar"]', '["and/ I will rebuke","and/ he rebuked","and/ he will rebuke"]', '["v"]', 'to chide corrupt, rebuke, reprove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["¿/ has he come","¿/ have you gone","¿/ really <come>","¿/ will it come"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0517}/H9021/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["and/ mother/ your"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251G}/H9021/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ brothers/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7812}/[H7812]', 'inflected', 'heb', 'שָׁחָה', '["shâchâh"]', '["to/ bow down"]', '["v"]', 'to depress, i.e. prostrate (especially reflexive, in homage to royalty or God) bow (self) down, crouch, fall down (flat), humbly beseech, do (make) obeisance, do reverence, make to stoop, worship.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1697G}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<the>/ word","[are] the/ words","[is] the/ thing","[is] the/ word","the/ matter","the/ thing","the/ things","the/ word","the/ words"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7462B}/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["<into>/ a shepherd","to the/ shepherds","to/ graze","to/ pasture","to/ shepherd"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7927G}/[H7926]', 'inflected', 'heb', 'שְׁכֶם', '["Shᵉkem"]', '["[was] in/ Shechem","at/ Shechem","in/ Shechem"]', '["n-pr-m n-pr-loc"]', 'Shekem, a place in Palestine Shechem.', 'the same as 7926; ridge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7971G}/H9031/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ I will send/ you","so/ I may send away/ you"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725G}/H9030/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ bring to/ me"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6010K}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["from/ [the] valley of"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2275H}/[H2267]', 'lemma', 'heb', 'חֶבְרוֹן', '["Chebrôwn"]', '["Hebron"]', '["n-pr-loc n-pr-m"]', 'Chebron, a place in Palestine, also the name of two Israelites Hebron.', 'from 2267; seat of association;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7927G}/H9011/[H7926]', 'inflected', 'heb', 'שְׁכֶם', '["Shᵉkem"]', '["Shechem/ towards"]', '["n-pr-m n-pr-loc"]', 'Shekem, a place in Palestine Shechem.', 'the same as 7926; ridge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4672}/H9033/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["and/ he found/ him","and/ it met/ him","and/ they found/ him","and/ they will come upon/ it"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7592}/H9033/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["and/ he asked/ him","and/ he enquired of/ him"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1245}/[H1245]', 'lemma', 'heb', 'בָּקַשׁ', '["bâqash"]', '["<he> sought","I sought","I will require","I will seek","[am] seeking","[are] requesting","[are] seeking","[is one who] seeks","[is] seeking","[one who] seeks","[one who] sought","[those who] seek","[was] seeking","[were] seeking","are you seeking","did he require","does he seek","he has sought","he seeks","he sought","he will seek","it has sought","it seeks","it will be sought","let people seek","let them seek","may he require","people sought","people will seek","requesting","seek","seekers of","seeking","she requested","they are seeking","they had sought","they have sought","they searched","they seek","they sought","they will seek","we will require [it]","will I require","will I seek","will you seek?","you are seeking","you have sought","you seek [them]","you will seek"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0375}/[H335]', 'lemma', 'heb', 'אֵיפֹה', '["ʼêyphôh"]', '["where?"]', '["adv"]', 'what place?; also (of time) when?; or (of means) how? what manner, where.', 'from 335 and 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1886>/H9011', 'opaque', 'heb', 'דֹּתָן', '["Dôthân"]', '["Dothan/ towards"]', '["n-pr-loc"]', 'Dothan, a place in Palestine Dothan. h', 'or (Aramaic dual) דֹּתַיִן; (Genesis 37:17), of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4672}/H9038/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["and/ he found/ them"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1886>', 'inflected', 'heb', 'בדתן', '["be./do.Tan","ve./do.Tan"]', '["at/ Dothan","in/ Dothan"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H2962>', 'inflected', 'heb', 'ובטרם', '["u./ve./Te.rem"]', '["and/ <in>/ before","and/ just/ before"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5230}/[H5230]', 'inflected', 'heb', 'נָכַל', '["nâkal"]', '["and/ they dealt deceptively with"]', '["v"]', 'to defraud, i.e. act treacherously beguile, conspire, deceiver, deal subtilly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4191}/H9033/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["to/ kill/ him","to/ put to death/ him"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1167K}/[H1166]', 'lemma', 'heb', 'בַּעַל', '["baʻal"]', '["[is] [the] master of","[the] citizens of","[the] master of","a captain of","master of","masters of","owner","owner of"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980K}/[H3212]', 'lemma', 'heb', 'הָלַךְ', '["hâlak"]', '["come","go"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2026}/H9033/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["and/ let us kill/ him"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7993}/H9033/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["and/ it throws down/ him","and/ let us throw/ him"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0953A}/[H952]', 'inflected', 'heb', 'בּוֹר', '["bôwr"]', '["the/ cistern","the/ cistern of","the/ pit","the/ pits","the/ well"]', '["n-m"]', 'a pit hole (especially one used as a cistern or a prison) cistern, dungeon, fountain, pit, well.', 'from 952 (in the sense of 877);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0398}/H9033/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["[those who] devour/ it","[those who] eat/ it","[which] it eats/ it","eat/ it","give to eat/ him","he devoured/ it","he eats/ it","he will eat/ it","it consumed/ it","it has consumed/ it","it has eaten/ him","it will consume/ him","it will consume/ it","it will eat/ it","they will eat/ it","you must eat/ it","you will eat/ it"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5337}/H9033/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ he rescued/ him"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027G}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5221}/H9033/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["I will strike/ it","[the] [one who] is striking/ him","[the] [one who] struck/ it","did he strike/ him","did you strike down/ him","has he struck/ it","he struck down/ him","he will strike down/ him","he will strike/ him","let me strike/ him","let us strike/ him","strike down/ him","they had wounded/ him","they struck down/ him","they wounded/ him","you will strike/ him"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7993}/[H7993]', 'lemma', 'heb', 'שָׁלַךְ', '["shâlak"]', '["I cast out","I threw","I throw","I was cast","I will throw","I will throw away","[is] about to be thrown","[one who] casts","[the one who] throws","[those who] cast","cast","did she throw","he has thrown","he threw","it was thrown down","it will throw away","people have cast down","someone will throw","they had thrown away","they have thrown","they threw","they threw away","they will be thrown out","they will throw","throw","throw away","thrown down","thrown out","you have been thrown out","you have cast","you threw","you threw away"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725H}/H9033/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["to/ restore/ him"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6584}/[H6584]', 'inflected', 'heb', 'פָּשַׁט', '["pâshaṭ"]', '["and/ he stripped himself","and/ he stripped off","and/ he will skin","and/ he will strip off","and/ they had made a raid","and/ they made a raid","and/ they made raids","and/ they stripped","and/ they stripped off","and/ they will strip off","and/ you will make a raid"]', '["v"]', 'to spread out (i.e. deploy in hostile array); by analogy, to strip (i.e. unclothe, plunder, flay, etc.) fall upon, flay, invade, make an invasion, pull off, put off, make a road, run upon, rush, set, spoil, spread selves (abroad), strip (off, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3801>/H9023', 'opaque', 'heb', 'כְּתֹנֶת', '["kᵉthôneth"]', '["long garment/ his","tunic/ his"]', '["n-f"]', 'a shirt coat, garment, robe.', 'or כֻּתֹּנֶת; from an unused root meaning to cover (compare 3802);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6446}/[H6461]', 'inflected', 'heb', 'פַּס', '["paç"]', '["the/ palms and soles"]', '["n-m"]', 'a long and sleeved tunic (perhaps simply a wide one; from the original sense of the root, i.e. of many breadths) (divers) colours.', 'from 6461; properly, the palm (of the hand) or sole (of the foot) (compare 6447); by implication (plural)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947G}/H9033/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ he took/ him","and/ it took/ him","and/ they took/ him"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0953A}/H9011/[H952]', 'inflected', 'heb', 'בּוֹר', '["bôwr"]', '["the/ pit/ towards"]', '["n-m"]', 'a pit hole (especially one used as a cistern or a prison) cistern, dungeon, fountain, pit, well.', 'from 952 (in the sense of 877);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0953A}/[H952]', 'inflected', 'heb', 'בּוֹר', '["bôwr"]', '["and/ the/ cistern","and/ the/ pit"]', '["n-m"]', 'a pit hole (especially one used as a cistern or a prison) cistern, dungeon, fountain, pit, well.', 'from 952 (in the sense of 877);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7386}/[H7324]', 'lemma', 'heb', 'רֵיק', '["rêyq"]', '["[too] empty","[was] empty","empty","empty [things]","unprincipled","worthless things"]', '["a"]', 'empty; figuratively, worthless emptied(-ty), vain (fellow, man).', 'or (shorter) רֵק; from 7324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899G}/[H3898]', 'lemma', 'heb', 'לֶחֶם', '["lechem"]', '["[is] food","[is] food of","[the] food of","bread","food","food of"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869H}/H9028/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eyes/ their"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0736}/[H732]', 'lemma', 'heb', 'אֹרְחָה', '["ʼôrᵉchâh"]', '["O caravans of","a caravan of"]', '["n-f"]', 'a caravan (travelling) company.', 'feminine active participle of 732;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3459}/[H3458]', 'lemma', 'heb', 'יִשְׁמָעֵאלִי', '["Yishmâʻêʼlîy"]', '["Ishmaelites","[were] Ishmaelites"]', '["a"]', 'a Jishmaelite or descendant of Jishmael Ishmaelite.', 'patronymically from 3458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1568G}/[H1567]', 'inflected', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["from/ Gilead"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1581}/H9028/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["and/ camels/ their"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5219}/[H5218]', 'lemma', 'heb', 'נְכֹאת', '["nᵉkôʼth"]', '["spice"]', '["n-f"]', 'properly, a smiting, i.e. (concretely) an aromatic gum (perhaps styrax) (as powdered) spicery(-ces).', 'from 5218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6875>', 'inflected', 'heb', 'וצרי', '["u./tze.Ri","va./Tzo.ri"]', '["and/ balm"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3910}/[H3874]', 'inflected', 'heb', 'לֹט', '["lôṭ"]', '["and/ myrrh"]', '["n-m"]', 'a gum (from its sticky nature), probably ladanum myrrh.', 'probably from 3874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980M}/[H3212]', 'lemma', 'heb', 'הָלַךְ', '["hâlak"]', '["continuously <to go>","go","traveling"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3381}/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["to/ come down","to/ go down","to/ take [them] down"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1215}/[H1214]', 'lemma', 'heb', 'בֶּצַע', '["betsaʻ"]', '["<of> unjust gain","[is the] profit","profit","profit of","unjust gain"]', '["n-m"]', 'plunder; by extension, gain (usually unjust) covetousness, (dishonest) gain, lucre, profit.', 'from 1214;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251G}/H9025/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["[is] brother/ our","brother/ our","brothers/ our"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4376}/H9033/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["and/ let us sell/ him"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3459}/[H3458]', 'inflected', 'heb', 'יִשְׁמָעֵאלִי', '["Yishmâʻêʼlîy"]', '["to the/ Ishmaelites"]', '["a"]', 'a Jishmaelite or descendant of Jishmael Ishmaelite.', 'patronymically from 3458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3027G}/H9025/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ hand/ our"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1320}/H9025/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["flesh/ our"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4084}/[H4080]', 'lemma', 'heb', 'מִדְיָנִי', '["Midyânîy"]', '["Midianite[s]"]', '["a"]', 'a Midjanite or descendant (native) of Midjan Midianite. Compare 4092.', 'patronymical or patrial from 4080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5503}/[H5503]', 'lemma', 'heb', 'סָחַר', '["çâchar"]', '["[the] trader of","[the] traders of","[were] [the] traders of","a trader","it palpitates","they have gone about","traders","you will go about in"]', '["v"]', 'to travel round (specifically as a pedlar); intensively, to palpitate go about, merchant(-man), occupy with, pant, trade, traffick.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4900}/[H4900]', 'inflected', 'heb', 'מָשַׁךְ', '["mâshak"]', '["and/ I will draw","and/ he drags off","and/ he marched","and/ they drew","and/ they drew out","and/ you prolonged","and/ you will march"]', '["v"]', 'to draw, used in a great variety of applications (including to sow, to sound, to prolong, to develop, to march, to remove, to delay, to be tall, etc.) draw (along, out), continue, defer, extend, forbear, × give, handle, make (pro-, sound) long, × sow, scatter, stretch out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5927H}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ I caused to go up","and/ I will bring up","and/ he brought up","and/ he has brought up","and/ he lifted up","and/ he put up","and/ he raised","and/ he will bring up","and/ it came up","and/ it was taken up","and/ it will go up","and/ it will lift up","and/ she brought it up","and/ she brought up","and/ they brought [him] up","and/ they brought up","and/ they made go up","and/ they took up","and/ you brought up","and/ you will bring up","and/ you will lift up","and/ you will take up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6242}/[H6235]', 'inflected', 'heb', 'עֶשְׂרִים', '["ʻesrîym"]', '["for/ twenty","in/ twenty","on/ [day] twenty"]', '["n"]', 'twenty; also (ordinal) twentieth (six-) score, twenty(-ieth).', 'from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0953A}/[H952]', 'inflected', 'heb', 'בּוֹר', '["bôwr"]', '["[was] in the/ pit","in the/ pit","in/ a pit of"]', '["n-m"]', 'a pit hole (especially one used as a cistern or a prison) cistern, dungeon, fountain, pit, well.', 'from 952 (in the sense of 877);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7167}/[H7167]', 'inflected', 'heb', 'קָרַע', '["qâraʻ"]', '["and/ I tore away","and/ I will tear away","and/ he has torn","and/ he tore","and/ he will tear","and/ it tore","and/ she tore","and/ they tore","and/ you tore"]', '["v"]', 'to rend, literally or figuratively (revile, paint the eyes, as if enlarging them) cut out, rend, × surely, tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0575}/[H370]', 'lemma', 'heb', 'אָן', '["ʼân"]', '["when?","where?"]', '["adv"]', 'where?; hence, whither?, when?; also hither and thither any (no) whither, now, where, whither(-soever).', 'or אָנָה; contracted from 370;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7819A}/[H7819]', 'inflected', 'heb', 'שָׁחַט', '["shâchaṭ"]', '["and/ he cut [the] throat of","and/ he cut [the] throat of [it]","and/ he slaughtered","and/ he will cut [the] throat of","and/ people slaughtered","and/ someone will cut [the] throat of","and/ someone will slaughter","and/ they slaughtered","and/ they slaughtered [it]","and/ they slaughtered [them]","and/ they will slaughter","and/ you slaughtered","and/ you will slaughter","and/ you will slaughter [it]"]', '["v n-f"]', 'to slaughter (in sacrifice or massacre) kill, offer, shoot out, slay, slaughter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8163B}/[H8175]', 'lemma', 'heb', 'שָׂעִיר', '["sâʻîyr"]', '["[the] goats of","[the] male goat of","a male goat of","male goats of"]', '["a n-m"]', 'shaggy; as noun, a he-goat; by analogy, a faun devil, goat, hairy, kid, rough, satyr.', 'or שָׂעִר; from 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2881}/[H2881]', 'inflected', 'heb', 'טָבַל', '["ṭâbal"]', '["and/ he dipped","and/ he dipped [it]","and/ he will dip","and/ he will dip [it]","and/ they dipped","and/ you will dip","and/ you will dip [it]"]', '["v"]', 'to dip, to immerse dip, plunge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3801>', 'inflected', 'heb', 'הכתנת', '["ha./ka.te.Not","ha./ke.To.net","ha./ku.To.net"]', '["the/ long garment","the/ tunic","the/ tunics"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1818}/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["<in>/ blood<s>","[is] in the/ blood","against/ blood","by the/ blood","by the/ blood<s>","by/ [the] blood of","by/ blood","by/ blood<s>","for/ [the] blood","in <the>/ blood","in the/ blood","in/ [the] blood of","in/ [the] blood<s> of","in/ blood","in/ blood<s>","with <the>/ blood","with/ [the] blood of","with/ blood<s>"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/<H3801>', 'inflected', 'heb', 'הכתנת', '["ha./ke.To.net"]', '["¿/ [the] long garment of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5234A}/H9034/[H5234]', 'inflected', 'heb', 'נָכַר', '["nâkar"]', '["and/ he recognized/ it"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2963}/[H2963]', 'lemma', 'heb', 'טָרַף', '["ṭâraph"]', '["I should tear to pieces","I will tear to pieces","O [one who] tears","[which] it tears to pieces","certainly <to tear>","certainly [if] <to tear>","he has been torn to pieces","he has torn to pieces","he should tear to pieces","he will be torn in pieces","it has torn [me]","it will be torn in pieces","tearing"]', '["v"]', 'to pluck off or pull to pieces; causatively to supply with food (as in morsels) catch, × without doubt, feed, ravin, rend in pieces, × surely, tear (in pieces).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8071}/H9023/[H5566]', 'inflected', 'heb', 'שִׂמְלָה', '["simlâh"]', '["[is] cloak/ his","clothes/ his","garments/ his"]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8242}/[H8264]', 'lemma', 'heb', 'שַׂק', '["saq"]', '["[was] sackcloth","sackcloth","sackcloth<s>","sacks"]', '["n-m"]', 'properly, a mesh (as allowing a liquid to run through), i.e. coarse loose cloth or sacking (used in mourning and for bagging); hence, a bag (for grain, etc.) sack(-cloth, -clothes).', 'from 8264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4975>/H9023', 'inflected', 'heb', 'במתניו', '["be./ma.te.Na/v","ve./ma.te.Na/v"]', '["[is] in/ loins/ its","[was] at/ hips/ his","[was] on/ loins/ his","on/ loins/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0056}/[H56]', 'inflected', 'heb', 'אָבַל', '["ʼâbal"]', '["and/ he has caused to mourn","and/ he mourned","and/ he will mourn","and/ they mourn","and/ they mourned","and/ they will dry up","and/ they will mourn"]', '["v"]', 'to bewail lament, mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5162G}/H9033/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["to/ comfort/ him"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3985}/[H3985]', 'inflected', 'heb', 'מָאֵן', '["mâʼên"]', '["and/ he refused","and/ it refused","and/ she refused","and/ they refused","and/ you refused"]', '["v"]', 'to refuse refuse, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5162G}/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["to/ be comforted","to/ comfort"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0057}/[H56]', 'lemma', 'heb', 'אָבֵל', '["ʼâbêl"]', '["[are] mourning","mourners","mourning"]', '["a"]', 'lamenting mourn(-er, -ing).', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7585}/H9011/[H7592]', 'inflected', 'heb', 'שְׁאוֹל', '["shᵉʼôwl"]', '["Sheol/ towards"]', '["n-f"]', 'hades or the world of the dead (as if a subterranean retreat), including its accessories and inmates grave, hell, pit.', 'or שְׁאֹל; from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4092}/[H4084]', 'inflected', 'heb', 'מְדָנִי', '["Mᵉdânîy"]', '["and/ the/ Medanites"]', '["a"]', 'Midianite.', 'a variation of 4084');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4376}/[H4376]', 'lemma', 'heb', 'מָכַר', '["mâkar"]', '["I sold","[is] selling","he has sold","he has sold himself","he sold [it]","he sold himself","he was sold","he will sell","he will sell [it]","he will sell himself","it will be sold","sell","she has sold","they sold","they will be sold","they will sell","we had been sold","we have been sold","you have sold","you sell [it]","you sold","you were sold","you will sell","you will sell it"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6318}/[H6318]', 'inflected', 'heb', 'פּוֹטִיפַר', '["Pôwṭîyphar"]', '["to/ Potiphar"]', '["n-pr-m"]', 'Potiphar, an Egyptian Potiphar.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5631>', 'opaque', 'heb', 'סָרִיס', '["çârîyç"]', '["[the] eunuch of","[the] eunuchs of","[the] official of","[the] officials of","a court-official","an official of","court-officials","eunuchs"]', '["n-m"]', 'a eunuch; by implication, valet (especially of the female apartments), and thus, a minister of state chamberlain, eunuch, officer. Compare 7249.', 'or סָרִס; from an unused root meaning to castrate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6547H}/[H6547]', 'lemma', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["Pharaoh","[am] Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2876}\/[H2873]', 'inflected', 'heb', 'טַבָּח', '["ṭabbâch"]', '["the/ bodyguards"]', '["n-m"]', 'properly, a butcher; hence, a lifeguardsman (because he was acting as an executioner); also a cook (usually slaughtering the animal for food) cook, guard.', 'from 2873;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5726}/[H5725]', 'lemma', 'heb', 'עֲדֻלָּמִי', '["ʻĂdullâmîy"]', '["an Adullamite"]', '["a"]', 'an Adullamite or native of Adullam Adullamite.', 'patrial from 5725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2437}/[H2357]', 'lemma', 'heb', 'חִירָה', '["Chîyrâh"]', '["[was] Hirah"]', '["n-pr-m"]', 'Chirah, an Adullamite Hirah.', 'from 2357 in the sense of splendor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3669A}/[H3667]', 'lemma', 'heb', 'כְּנַעַנִי', '["Kᵉnaʻanîy"]', '["[will be] Canaanites","a Canaanite"]', '["n-m"]', 'a Kenaanite or inhabitant of Kenaan; by implication, a pedlar (the Canaanites standing for their neighbors the Ishmaelites, who conducted mercantile caravans) Canaanite, merchant, trafficker.', 'patrial from 3667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7770}/[H7769]', 'lemma', 'heb', 'שׁוּעַ', '["Shûwaʻ"]', '["-shua","Shua","[was] Shua"]', '["n-pr-m"]', 'Shua, a Canaanite Shua, Shuah.', 'the same as 7769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947I}/H9034/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ he took/ her","and/ he will take/ her"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6147G}/[H5782]', 'lemma', 'heb', 'עֵר', '["ʻÊr"]', '["Er","[were] Er"]', '["n-pr-m"]', 'Er, the name of two Israelites Er.', 'from 5782; watchful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0209}/[H207]', 'lemma', 'heb', 'אוֹנָן', '["ʼÔwnân"]', '["Onan"]', '["n-pr-m"]', 'Onan, a son of Judah Onan.', 'a variation of 207; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7956}/[H7596]', 'lemma', 'heb', 'שֵׁלָה', '["Shêlâh"]', '["Shelah"]', '["n-pr-m"]', 'Shelah, the name of a postdiluvian patriarch and of an Israelite Shelah.', 'the same as 7596 (shortened); request;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3580}/[H3576]', 'inflected', 'heb', 'כְּזִיב', '["Kᵉzîyb"]', '["in/ Kezib"]', '["n-pr-loc"]', 'Kezib, a place in Palestine Chezib.', 'from 3576; falsified;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6147G}/[H5782]', 'inflected', 'heb', 'עֵר', '["ʻÊr"]', '["for/ Er"]', '["n-pr-m"]', 'Er, the name of two Israelites Er.', 'from 5782; watchful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8559G}/[H8558]', 'lemma', 'heb', 'תָּמָר', '["Tâmâr"]', '["Tamar","[was] Tamar"]', '["n-pr"]', 'Tamar, the name of three women and a place Tamar.', 'the same as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4191}/H9033/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ I killed/ it","and/ he killed/ him","and/ he put to death/ him","and/ it has killed/ him","and/ it killed/ him","and/ they killed/ him","and/ they put to death/ him"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0209}/[H207]', 'inflected', 'heb', 'אוֹנָן', '["ʼÔwnân"]', '["to/ Onan"]', '["n-pr-m"]', 'Onan, a son of Judah Onan.', 'a variation of 207; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2992}/[H2993]', 'inflected', 'heb', 'יָבַם', '["yâbam"]', '["and/ act as a husband''s brother for"]', '["v"]', 'to marry a (deceased) brother''s widow perform the duty of a husband''s brother, marry.', 'a primitive root of doubtful meaning; used only as a denominative from 2993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6965I}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ [one who] raises","and/ it may be fulfilled","and/ raise up","and/ they may arise"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2233H}/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["the/ offspring"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8559G}/[H8558]', 'inflected', 'heb', 'תָּמָר', '["Tâmâr"]', '["to/ Tamar"]', '["n-pr"]', 'Tamar, the name of three women and a place Tamar.', 'the same as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0490}/[H488]', 'lemma', 'heb', 'אַלְמָנָה', '["ʼalmânâh"]', '["[the] widow","a widow","widow","widows"]', '["n-f"]', 'a widow; also a desolate place desolate house (palace), widow.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0251G}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["like/ brother/ his","like/ brothers/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1494}/[H1468]', 'lemma', 'heb', 'גָּזַז', '["gazâz"]', '["[the] shearers of","[was] shearing","cut off","shearers","you will shear"]', '["v"]', 'to cut off; specifically to shear a flock or shave the hair; figuratively to destroy an enemy cut off (down), poll, shave, (sheep-) shear(-er).', 'a primitive root (akin to 1468);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2437}/[H2357]', 'inflected', 'heb', 'חִירָה', '["Chîyrâh"]', '["and/ Hirah"]', '["n-pr-m"]', 'Chirah, an Adullamite Hirah.', 'from 2357 in the sense of splendor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5726}/[H5725]', 'inflected', 'heb', 'עֲדֻלָּמִי', '["ʻĂdullâmîy"]', '["the/ Adullamite"]', '["a"]', 'an Adullamite or native of Adullam Adullamite.', 'patrial from 5725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8553G}/H9011/[H4487]', 'inflected', 'heb', 'תִּמְנָה', '["Timnâh"]', '["Timnah/ <towards>","Timnah/ towards"]', '["n-pr-loc"]', 'Timnah, the name of two places in Palestine Timnah, Timnath, Thimnathah.', 'from 4487; a portion assigned;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2524}/H9022/[H2346]', 'inflected', 'heb', 'חָם', '["châm"]', '["father-in-law/ your"]', '["n-m"]', 'a father-in-law (as in affinity) father in law.', 'from the same as 2346;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0491}/H9024/[H488]', 'inflected', 'heb', 'אַלְמָנוּת', '["ʼalmânûwth"]', '["widowhood/ her"]', '["n-f"]', 'concrete, a widow; abstract, widowhood widow, widowhood.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6809>', 'inflected', 'heb', 'בצעיף', '["ba./tza.''If"]', '["with the/ veil"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5968}/[H5968]', 'inflected', 'heb', 'עָלַף', '["ʻâlaph"]', '["and/ he became faint","and/ she wrapped herself up"]', '["v"]', 'to veil or cover; figuratively, to be languid faint, overlaid, wrap self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6607}/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["[is] at/ [the] entrance of","[were] at/ [the] entrance of","at the/ entrance","at/ [the] entrance of","at/ [the] entrances of","in the/ entrance"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5879G}/[H5869]', 'lemma', 'heb', 'עֵינַיִם', '["ʻÊynayim"]', '["Enaim"]', '["n-pr-loc"]', 'Enajim or Enam, a place in Palestine Enaim, openly (Genesis 38:21).', 'or עֵינָם; dual of 5869; double fountain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2803J}/H9034/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ he considered/ her"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2181}/[H2181]', 'inflected', 'heb', 'זָנָה', '["zânâh"]', '["<into>/ a prostitute","by/ acting as a prostitute","by/ acting as prostitutes","to/ a prostitute","to/ act as a prostitute","to/ commit fornication"]', '["v"]', 'to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish.', 'a primitive root [highly fed and therefore wanton];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3680}/[H3680]', 'lemma', 'heb', 'כָּסָה', '["kâçâh"]', '["I covered","I have concealed","I have covered","I will cover","[is one who] is covered of","[is] concealing","[one who] conceals","[was] covering himself","[were] covered","[were] covering","[which] they cover","covered","covering","he covered","he covers","he has covered","he will cover","it conceals","it covered","it covers","it covers itself","it has covered","it is covered","it will be covered","it will cover","people will cover themselves","she had covered","they were covered","to cover","you cover","you covered","you will cover"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440H}/H9024/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ her","face/ its"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1870K}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["[is] the/ way","the/ direction of","the/ journey","the/ road","the/ roads","the/ way"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/H9032/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["[am] against/ you","[is] with/ you","against/ you","because of/ you","concerning/ you","into/ you","to/ you"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6162}/[H6148]', 'lemma', 'heb', 'עֲרָבוֹן', '["ʻărâbôwn"]', '["a pledge"]', '["n-m"]', 'a pawn (given as security) pledge.', 'from 6148 (in the sense of exchange);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971G}/H9041/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["sending [it]/ you"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6162}/[H6148]', 'inflected', 'heb', 'עֲרָבוֹן', '["ʻărâbôwn"]', '["[is] the/ pledge","the/ pledge"]', '["n-m"]', 'a pawn (given as security) pledge.', 'from 6148 (in the sense of exchange);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2368}/H9021/[H2856]', 'inflected', 'heb', 'חוֹתָם', '["chôwthâm"]', '["seal/ your"]', '["n-m"]', 'a signature-ring seal, signet.', 'or חֹתָם; from 2856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6616}/H9021/[H6617]', 'inflected', 'heb', 'פָּתִיל', '["pâthîyl"]', '["and/ cord/ your"]', '["n-m"]', 'twine bound, bracelet, lace, line, ribband, thread, wire.', 'from 6617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4294G}/H9021/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["and/ staff/ your"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027G}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[are] in/ hand/ your","[is] in/ hand/ your","in/ hand/ your","on/ hand/ your","to/ hand/ your","with/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6809>/H9024', 'opaque', 'heb', 'צָעִיף', '["tsâʻîyph"]', '["veil/ her"]', '["n-m"]', 'a veil vail.', 'from an unused root meaning to wrap over;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027G}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[is] in/ [the] hand of","[was] in/ [the] hand of","[were] in/ [the] hand of","by/ [the] hand of","by/ a hand","by/ hand","for/ hand","in/ [the] hand of","in/ [two] hands","in/ a hand","on/ [the] hand of","with/ a hand","with/ hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027G}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ [the] hand of","from/ [the] hands of","from/ a hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4672}/H9034/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["I found/ her","he found/ her","they will find/ it","we found/ it","you found/ her"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4725}/H9024/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["place/ her","place/ its"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6948}/[H6945]', 'inflected', 'heb', 'קְדֵשָׁה', '["qᵉdêshâh"]', '["[is] the/ cult prostitute","the/ cult prostitutes"]', '["n-f"]', 'a female devotee (i.e. prostitute) harlot, whore.', 'feminine of 6945;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5879G}/[H5869]', 'inflected', 'heb', 'עֵינַיִם', '["ʻÊynayim"]', '["[was] at <the>/ Enaim"]', '["n-pr-loc"]', 'Enajim or Enam, a place in Palestine Enaim, openly (Genesis 38:21).', 'or עֵינָם; dual of 5869; double fountain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2088}/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["<in>/ this one","in/ this [place]","on/ this"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6948}/[H6945]', 'lemma', 'heb', 'קְדֵשָׁה', '["qᵉdêshâh"]', '["a cult prostitute","a female cult prostitute"]', '["n-f"]', 'a female devotee (i.e. prostitute) harlot, whore.', 'feminine of 6945;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0937}/[H936]', 'inflected', 'heb', 'בּוּז', '["bûwz"]', '["<into>/ contempt"]', '["n-m"]', 'disrespect contempt(-uously), despised, shamed.', 'from 936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1423}/[H1415]', 'inflected', 'heb', 'גְּדִי', '["gᵉdîy"]', '["<the>/ kid","the/ kid"]', '["n-m"]', 'a young goat (from browsing) kid.', 'from the same as 1415;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9006/{H7969}/[H7969]', 'inflected', 'heb', 'שָׁלוֹשׁ', '["shâlôwsh"]', '["when/ from/ three"]', '["n"]', 'three; occasionally (ordinal) third, or (multiple) thrice fork, often(-times), third, thir(-teen, -teenth), three, thrice. Compare 7991.', 'or שָׁלֹשׁ; masculine שְׁלוֹשָׁה; or שְׁלֹשָׁה; a primitive number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3063G}/[H3034]', 'inflected', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["[belonged] to/ Judah","[belongs] to/ Judah","for/ Judah","of/ Judah","to/ Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2181}/[H2181]', 'lemma', 'heb', 'זָנָה', '["zânâh"]', '["O prostitute","[are] acting as prostitutes","[are] prostituting themselves","[are] prostituting yourself","[one who] acts as a prostitute","a prostitute","acting as prostitutes","certainly <to prostitute themselves>","continually <prostitute itself>","it prostitutes itself","it was approached for prostitution","it will prostitute itself","prostitutes","she acted as a prostitute","she has acted as a prostitute","she has prostituted herself","she will be a prostitute","they acted as prostitutes","they have prostituted themselves","they prostitute themselves","they will act as a prostitutes","they will prostitute themselves","you have acted as a prostitute","you have prostituted yourself","you must prostitute yourself"]', '["v"]', 'to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish.', 'a primitive root [highly fed and therefore wanton];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3618H}/H9021/[H3634]', 'inflected', 'heb', 'כַּלָּה', '["kallâh"]', '["daughter-in-law/ your"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2183}/[H2181]', 'inflected', 'heb', 'זָנוּן', '["zânûwn"]', '["to/ prostitution<s>"]', '["n-m"]', 'adultery; figuratively, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318H}/H9034/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["I will send forth/ it","bring out/ her","send out/ it","take out/ it"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2524}/H9024/[H2346]', 'inflected', 'heb', 'חָם', '["châm"]', '["father-in-law/ her"]', '["n-m"]', 'a father-in-law (as in affinity) father in law.', 'from the same as 2346;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2858}/[H2856]', 'inflected', 'heb', 'חֹתֶמֶת', '["chôthemeth"]', '["the/ seal"]', '["n-f"]', 'a seal signet.', 'feminine active participle of 2856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6616}/[H6617]', 'inflected', 'heb', 'פָּתִיל', '["pâthîyl"]', '["and/ the/ cord"]', '["n-m"]', 'twine bound, bracelet, lace, line, ribband, thread, wire.', 'from 6617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4294G}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["and/ the/ staff"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5234A}/[H5234]', 'inflected', 'heb', 'נָכַר', '["nâkar"]', '["and/ he recognized","and/ he recognized [them]"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6663}/[H6663]', 'lemma', 'heb', 'צָדַק', '["tsâdaq"]', '["I am in [the] right","I am righteous","I will declare right","I will declare righteous","[one who] justifies","[those who] justify","he is righteous","he will be righteous","he will justify","she has made appear righteous","she is righteous","they are righteous","they will be justified","vindicate","will he be acquitted","will he be justified","will he be righteous","will we justify ourselves","you are in [the] right","you are righteous","you have been righteous","you may be just","you may be justified"]', '["v"]', 'to be (causatively, make) right (in a moral or forensic sense) cleanse, clear self, (be, do) just(-ice, -ify, -ify self), (be turn to) righteous(-ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7956}/[H7596]', 'inflected', 'heb', 'שֵׁלָה', '["Shêlâh"]', '["of/ Shelah","to/ Shelah"]', '["n-pr-m"]', 'Shelah, the name of a postdiluvian patriarch and of an Israelite Shelah.', 'the same as 7596 (shortened); request;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3045}/H9034/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["to/ know/ her"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3205}/H9044/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["gave birth/ she","was born/ she"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7194}/[H7194]', 'inflected', 'heb', 'קָשַׁר', '["qâshar"]', '["and/ he conspired","and/ it was joined together","and/ people conspired","and/ she bound","and/ she tied","and/ they conspired","and/ you will tie"]', '["v"]', 'to tie, physically (gird, confine, compact) or mentally (in love, league) bind (up), (make a) conspire(-acy, -ator), join together, knit, stronger, work (treason).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8144>', 'opaque', 'heb', 'שָׁנִי', '["shânîy"]', '["[the] scarlet of","a scarlet thread","scarlet","scarlet<s>"]', '["n-m"]', 'crimson, properly, the insect or its color, also stuff dyed with it crimson, scarlet (thread).', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7725G}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["as/ returns","when/ [he was] withdrawing"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6555}/[H6555]', 'lemma', 'heb', 'פָּרַץ', '["pârats"]', '["I will break down","[has been] broken down","broken into","have you broken down","he breaks open","he burst out","he had broken out","he has burst out against","he has burst through","he should break out","he will break","it has spread out","it spread","let us spread out","people have broken out","they had broken into","they spread out","they will break through","they will increase","you have broken through","you have made a breach","you will spread out"]', '["v"]', 'to break out (in many applications, direct and indirect, literal and figurative) × abroad, (make a) breach, break (away, down, -er, forth, in, up), burst out, come (spread) abroad, compel, disperse, grow, increase, open, press, scatter, urge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6556}/[H6555]', 'lemma', 'heb', 'פֶּרֶץ', '["perets"]', '["[the] breach of","[will be] a breach","a breach","a breaking out"]', '["n-m"]', 'a break (literally or figuratively) breach, breaking forth (in), × forth, gap.', 'from 6555;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6557}/[H6556]', 'lemma', 'heb', 'פֶּרֶץ', '["Perets"]', '["Perez"]', '["n-pr-m"]', 'Perets, the name of two Israelites Perez, Pharez.', 'the same as 6556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H8144>', 'inflected', 'heb', 'השני', '["ha./sha.Ni"]', '["<the>/ scarlet","the/ scarlet","the/ scarlet thread"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2226I}\/[H2225]', 'inflected', 'heb', 'זֶרַח', '["Zerach"]', '["Zerah"]', '["n-pr-m"]', 'Zerach, the name of three Israelites, also of an Idumaean and an Ethiopian prince Zarah, Zerah.', 'the same as 2225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3130G}/[H3254]', 'inflected', 'heb', 'יוֹסֵף', '["Yôwçêph"]', '["and/ Joseph"]', '["n-pr-m"]', 'Joseph, the name of seven Israelites Joseph. Compare 3084.', 'future of 3254; let him add (or perhaps simply active participle adding);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7069}/H9033/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["and/ he bought/ him"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6318}/[H6318]', 'lemma', 'heb', 'פּוֹטִיפַר', '["Pôwṭîyphar"]', '["Potiphar"]', '["n-pr-m"]', 'Potiphar, an Egyptian Potiphar.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2876}/[H2873]', 'inflected', 'heb', 'טַבָּח', '["ṭabbâch"]', '["the/ bodyguards","the/ cook"]', '["n-m"]', 'properly, a butcher; hence, a lifeguardsman (because he was acting as an executioner); also a cook (usually slaughtering the animal for food) cook, guard.', 'from 2873;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3459}/[H3458]', 'inflected', 'heb', 'יִשְׁמָעֵאלִי', '["Yishmâʻêʼlîy"]', '["the/ Ishmaelite","the/ Ishmaelites"]', '["a"]', 'a Jishmaelite or descendant of Jishmael Ishmaelite.', 'patronymically from 3458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3381}/H9033/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["bring down/ him","they had brought down/ him"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869H}/H9023/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ eye/ his","in/ view/ his"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8334}/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["and/ he served","and/ he will serve","and/ they will serve"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6485J}/H9033/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ he appointed/ him"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027H}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[is] in/ hand/ his","[was] in/ hand/ his","[were] in/ hand/ his","[will be] in/ hand/ his","by/ hand/ his","in/ hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0227B}/[H227]', 'inflected', 'heb', 'אָז', '["ʼâz"]', '["from/ then"]', '["adv"]', 'at that time or place; also as a conjunction, therefore beginning, for, from, hitherto, now, of old, once, since, then, at which time, yet.', 'a demonstrative adverb;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485J}/[H6485]', 'lemma', 'heb', 'פָּקַד', '["pâqad"]', '["I entrust","I have appointed","I have visited","I will appoint","[the] officers of","[were] appointed","appoint","did he assign","has he assigned","he appointed","he had appointed","he has appointed","he will appoint","it was entrusted","let him appoint","you will appoint"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004M}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["in/ house/ his","in/ household/ his","in/ own household/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1558}/[H1556]', 'inflected', 'heb', 'גָּלָל', '["gâlâl"]', '["on/ account of"]', '["n-m"]', 'a circumstance (as rolled around); only used adverbially, on account of because of, for (sake).', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H7704G>', 'inflected', 'heb', 'ובשדה', '["u./va./sa.Deh","u./vi/s.Dei"]', '["and/ in the/ field","and/ in/ [the] fields of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5800A}/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["and/ he abandoned","and/ he forsook","and/ he has forsaken","and/ he left","and/ he will leave","and/ they abandoned","and/ they forsook","and/ they leave","and/ they left","and/ you left","and/ you will forsake","and/ you will leave [them]"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3899G}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["the/ food"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7901I}/H9012/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["lie/ !"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/H9030/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[are] with/ me","[is] with/ me","[was] with/ me","[will be] with/ me","with/ me"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027H}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["by/ hand/ my","in/ hand/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7451I}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<the>/ evil","[is] the/ evil","the/ calamities","the/ calamity","the/ evil","the/ harm","the/ trouble","the/ wicked things"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2398}/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["and/ I will be culpable","and/ I will sin","and/ he cleansed from sin","and/ he has caused to sin","and/ he will cleanse from sin","and/ it will sin","and/ they made a sin offering","and/ they purified themselves","and/ they will cleanse from sin","and/ we sinned","and/ you have caused to sin","and/ you sinned","and/ you will cleanse from sin","and/ you will make a sin offering","and/ you will sin"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1696G}/H9044/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["when/ spoke/ she"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117J>', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["a day","day"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0681}/H9034/[H680]', 'inflected', 'heb', 'אֵצֶל', '["ʼêtsel"]', '["beside/ her","beside/ it"]', '["n-m"]', 'a side; (as a preposition) near at, (hard) by, (from) (beside), near (unto), toward, with. See also 1018.', 'from 680 (in the sense of joining);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9009/<H3117G>', 'inflected', 'heb', 'כהיום', '["ke./hai./Yom"]', '["as/ the/ day","as/ this/ day","when/ the/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0369}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["and/ not","and/ not?","and/ nothing","and/ there [are] not","and/ there [is] not","and/ there not"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0582}/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["away from/ humankind","from/ [the] men of","from/ a person","from/ humankind","more than/ a human","one of/ [the] men of"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8610}/H9033/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["and/ she seized/ him"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0899B}/H9023/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["by/ clothing/ his","on/ clothes/ his","on/ garments/ his"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027H}/H9024/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["in/ hand/ her"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7200G}/H9044/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["when/ saw/ she"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027G}/H9024/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["<in>/ hands/ its","in/ hand/ her","on/ hand/ her","with/ hands/ her"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004M}/H9024/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["household/ her"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200I}/[H7200]', 'lemma', 'heb', 'רָאָה', '["râʼâh"]', '["consider","look","see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5680}/[H5677]', 'lemma', 'heb', 'עִבְרִי', '["ʻIbrîy"]', '["Hebrew","Hebrews","[am] a Hebrew","a Hebrew"]', '["n-pr"]', 'an Eberite (i.e. Hebrew) or descendant of Eber Hebrew(-ess, woman).', 'patronymic from 5677;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6711}/[H6711]', 'inflected', 'heb', 'צָחַק', '["tsâchaq"]', '["to/ mock"]', '["v"]', 'to laugh outright (in merriment or scorn); by implication, to sport laugh, mock, play, make sport.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963A>', 'inflected', 'heb', 'בקול', '["be./Kol","be./kOl","be./kol","ve./kol"]', '["<in>/ [the] sound of","<in>/ [the] voice of","<in>/ a sound of","to/ [the] sound of","to/ [the] voice of","to/ a voice","with/ [the] sound of","with/ [the] voice of","with/ a sound of","with/ a voice","with/ a voice of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8085G}/H9043/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["just as/ heard/ he","when/ heard/ he","when/ hears/ he"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0681}/H9030/[H680]', 'inflected', 'heb', 'אֵצֶל', '["ʼêtsel"]', '["[was] beside/ me","beside/ me"]', '["n-m"]', 'a side; (as a preposition) near at, (hard) by, (from) (beside), near (unto), toward, with. See also 1018.', 'from 680 (in the sense of joining);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1697G}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["according to the/ words","according to/ [the] word of","like/ [the] word of","like/ [the] words of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7311A}/H9040/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["when/ raised/ I"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639G}/H9023/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["anger/ his"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0113>', 'opaque', 'heb', 'אָדוֹן', '["ʼâdôwn"]', '["O lord","[am] a master<s>","[is] master","[the] lord","[the] lord of","[the] lord<s> of","[the] master<s> of","[the] owner<s> of","a master<s>","lords","master","masters"]', '["n-m"]', 'sovereign, i.e. controller (human or divine) lord, master, owner. Compare also names beginning with ''Adoni-''.', 'or (shortened) אָדֹן; from an unused root (meaning to rule);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414H}/H9033/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ he had put/ it","and/ he put/ him","and/ it put/ it","and/ they put/ it","and/ you put/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5470}/[H5469]', 'inflected', 'heb', 'סֹהַר', '["çôhar"]', '["the/ prison"]', '["n-m"]', 'a dungeon (as surrounded by walls) prison.', 'from the same as 5469;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0615}/[H631]', 'lemma', 'heb', 'אָסִיר', '["ʼâçîyr"]', '["O prisoners of","[the] prisoners of","prisoner[s]","prisoners","prisoners of"]', '["n-m"]', 'bound, i.e. a captive (those which are) bound, prisoner.', 'from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0631}/[H631]', 'lemma', 'heb', 'אָסַר', '["ʼâçar"]', '["[is] bound","[they are] bound","[was] bound","[was] imprisoned","[were] bound","[were] girded","[were] imprisoned","be imprisoned","bind","binding","certainly <to bind>","certainly [if] <to bind>","harness","let him be imprisoned","prisoners","she bound","she has bound","they have been captured","they were captured","tied up","will he begin","will you be bound"]', '["v"]', 'to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2580}/H9023/[H2603]', 'inflected', 'heb', 'חֵן', '["chên"]', '["favor/ his"]', '["n-m"]', 'graciousness, i.e. subjective (kindness, favor) or objective (beauty) favour, grace(-ious), pleasant, precious, (well-) favoured.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0615}/[H631]', 'inflected', 'heb', 'אָסִיר', '["ʼâçîyr"]', '["the/ prisoners"]', '["n-m"]', 'bound, i.e. a captive (those which are) bound, prisoner.', 'from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6743B}\/[H6743]', 'inflected', 'heb', 'צָלַח', '["tsâlach"]', '["[was] making successful","he made successful","you will succeed"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4945A}/[H8248]', 'lemma', 'heb', 'מַשְׁקֶה', '["mashqeh"]', '["[the] cup bearer of","cup bearer"]', '["n-m"]', 'properly, causing to drink, i.e. a butler; by implication (intransitively), drink (itself); figuratively, a well-watered region butler(-ship), cupbearer, drink(-ing), fat pasture, watered.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0644}/[H644]', 'inflected', 'heb', 'אָפָה', '["ʼâphâh"]', '["and/ the/ baker"]', '["v"]', 'to cook, especially to bake bake(-r, (-meats)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0113>/H9028', 'inflected', 'heb', 'לאדניהם', '["la./''a.do.nei./Hem"]', '["to/ master<s>/ their","to/ masters/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4428G}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["<into>/ king","<to> the/ king","[belonged] to the/ king","[belonged] to the/ kings","[belonged] to/ [the] king of","[belongs] to the/ king","[had belonged] to the/ king","by the/ king","by/ [the] kings of","for <the>/ kings","for the/ king","for the/ kings","of the/ king","of/ [the] king of","of/ [the] kings of","to <the>/ kings","to the/ king","to the/ kings","to/ [the] king","to/ [the] king of","to/ [the] kings of","to/ a king","to/ king"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7107}/[H7107]', 'inflected', 'heb', 'קָצַף', '["qâtsaph"]', '["and/ he was angry","and/ it will be enraged","and/ they provoked to anger","and/ they were angry"]', '["v"]', 'to crack off, i.e. (figuratively) burst out in rage (be) anger(-ry), displease, fret self, (provoke to) wrath (come), be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5631>/H9023', 'opaque', 'heb', 'סָרִיס', '["çârîyç"]', '["court-officials/ his","officials/ his"]', '["n-m"]', 'a eunuch; by implication, valet (especially of the female apartments), and thus, a minister of state chamberlain, eunuch, officer. Compare 7249.', 'or סָרִס; from an unused root meaning to castrate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4945A}/[H8248]', 'inflected', 'heb', 'מַשְׁקֶה', '["mashqeh"]', '["the/ cup bearer","the/ cup bearers"]', '["n-m"]', 'properly, causing to drink, i.e. a butler; by implication (intransitively), drink (itself); figuratively, a well-watered region butler(-ship), cupbearer, drink(-ing), fat pasture, watered.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0644}/[H644]', 'inflected', 'heb', 'אָפָה', '["ʼâphâh"]', '["the/ bakers"]', '["v"]', 'to cook, especially to bake bake(-r, (-meats)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4929}/[H8104]', 'inflected', 'heb', 'מִשְׁמָר', '["mishmâr"]', '["in <the>/ custody","in/ [the] custody of","in/ custody"]', '["n-m"]', 'a guard (the man, the post or the prison); a deposit (figuratively); also (as observed) a usage (abstractly), or an example (concretely) diligence, guard, office, prison, ward, watch.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6485J}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ I will appoint","and/ he appointed","and/ he entrusted [them]","and/ they deposited","and/ they had been appointed","and/ they were appointed","and/ they will appoint","and/ you will assign"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6623}/[H6622]', 'inflected', 'heb', 'פִּתְרוֹן', '["pithrôwn"]', '["according to/ [the] interpretation of"]', '["n-m"]', 'interpretation (of a dream) interpretation.', 'or פִּתְרֹן; from 6622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2005}/H9048/[H2005]', 'inflected', 'heb', 'הֵן', '["hên"]', '["and/ [were]/ they","and/ there!/ they","and/ there/ they"]', '["prt"]', 'lo!; also (as expressing surprise) if behold, if, lo, though.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2196}/[H2196]', 'lemma', 'heb', 'זָעַף', '["zâʻaph"]', '["it rages","looking dejected","looking thin"]', '["v"]', 'properly, to boil up, i.e. (figuratively) to be peevish or angry fret, sad, worse liking, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440H}/H9026/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["[are] faces/ your","faces/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6622}/[H6622]', 'inflected', 'heb', 'פָּתַר', '["pâthar"]', '["and/ [is one who] interprets"]', '["v"]', 'to open up, i.e. (figuratively) interpret (a dream) interpret(-ation, -er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6623}/[H6622]', 'lemma', 'heb', 'פִּתְרוֹן', '["pithrôwn"]', '["[do] interpretations"]', '["n-m"]', 'interpretation (of a dream) interpretation.', 'or פִּתְרֹן; from 6622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3130G}/[H3254]', 'inflected', 'heb', 'יוֹסֵף', '["Yôwçêph"]', '["<to>/ Joseph","for/ Joseph","to/ Joseph"]', '["n-pr-m"]', 'Joseph, the name of seven Israelites Joseph. Compare 3084.', 'future of 3254; let him add (or perhaps simply active participle adding);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2472}/H9020/[H2492]', 'inflected', 'heb', 'חֲלוֹם', '["chălôwm"]', '["in/ dream/ my"]', '["n-m"]', 'a dream dream(-er).', 'or (shortened) חֲלֹם; from 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1612>', 'opaque', 'heb', 'גֶּפֶן', '["gephen"]', '["[the] vine","[the] vine[s] of","[was] a vine","a vine","a vine of","vine","vine[s]"]', '["n-m"]', 'a vine (as twining), especially the grape vine, tree.', 'from an unused root meaning to bend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H1612>', 'inflected', 'heb', 'ובגפן', '["u./va./Ge.fen"]', '["and/ [were] on the/ vine"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8299}/[H8276]', 'lemma', 'heb', 'שָׂרִיג', '["sârîyg"]', '["branches"]', '["n-m"]', 'a tendril (as entwining) branch.', 'from 8276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6524A}/[H6524]', 'inflected', 'heb', 'פָּרַח', '["pârach"]', '["when/ [it was] budding"]', '["v"]', 'to break forth as a bud, i.e. bloom; generally, to spread; specifically, to fly (as extending the wings); figuratively, to flourish × abroad, × abundantly, blossom, break forth (out), bud, flourish, make fly, grow, spread, spring (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5322A}/H9024/[H5340]', 'inflected', 'heb', 'נֵץ', '["nêts"]', '["blossom/ its"]', '["n-m"]', 'a flower (from its brilliancy); also a hawk (from it flashing speed) blossom, hawk.', 'from 5340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1310}/[H1310]', 'lemma', 'heb', 'בָּשַׁל', '["bâshal"]', '["being boiled","boil","boiled","it was boiled","it will be boiled","they boiled","they have boiled","they have cooked","they ripened","they will boil","you must boil","you will boil"]', '["v"]', 'properly, to boil up; hence, to be done in cooking; figuratively to ripen bake, boil, bring forth, roast, seethe, sod (be sodden).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0811}/H9024/[H810]', 'inflected', 'heb', 'אֶשְׁכּוֹל', '["ʼeshkôwl"]', '["clusters/ its"]', '["n-m"]', 'a bunch of grapes or other fruit cluster (of grapes).', 'or אֶשְׁכֹּל; probably prolonged from 810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6025>', 'opaque', 'heb', 'עֵנָב', '["ʻênâb"]', '["[are] grapes of","[the] grapes","[will be] grapes","grape[s]","grapes"]', '["n-m"]', 'a grape (ripe) grape, wine.', 'from an unused root probably meaning to bear fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3563A>', 'inflected', 'heb', 'וכסות', '["ve./Khos","ve./kho.Sot"]', '["and/ [the] cup of","and/ cups"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027G}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[are] in/ hand/ my","[is] in/ hand/ my","[was] in/ hand/ my","[were] in/ hand/ my","[will be] in/ hand/ my","in/ hand/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6025>', 'inflected', 'heb', 'הענבים', '["ha./''a.na.Vim"]', '["the/ grapes"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7818}/[H7818]', 'inflected', 'heb', 'שָׂחַט', '["sâchaṭ"]', '["and/ I squeezed"]', '["v"]', 'to tread out, i.e. squeeze (grapes) press.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3563A>', 'opaque', 'heb', 'כּוֹס', '["kôwç"]', '["[is] a cup of","[the] cup of","[was] a cup of","a cup","a cup of"]', '["n-f"]', 'a cup (as a container), often figuratively, a lot (as if a potion); also some unclean bird, probably an owl (perhaps from the cup-like cavity of its eye) cup, (small) owl. Compare 3599.', 'from an unused root meaning to hold together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3563A>', 'inflected', 'heb', 'הכוס', '["ha./Kos","ha./kOs"]', '["the/ cup"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709G}/[H3721]', 'lemma', 'heb', 'כַּף', '["kaph"]', '["<of> a palm","[the] handles of","[the] hands of","[the] palm of","[the] palms of","a palm","a palm of","both hands","hand of","hands","palm","palms","palms of hands"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6623}/H9023/[H6622]', 'inflected', 'heb', 'פִּתְרוֹן', '["pithrôwn"]', '["[is] interpretation/ its"]', '["n-m"]', 'interpretation (of a dream) interpretation.', 'or פִּתְרֹן; from 6622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8299}/[H8276]', 'inflected', 'heb', 'שָׂרִיג', '["sârîyg"]', '["the/ branches"]', '["n-m"]', 'a tendril (as entwining) branch.', 'from 8276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5750}/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["at/ yet","in/ again","in/ yet","when/ still","while/ still"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218A>/H9021', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ your"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725H}/H9031/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ he will restore/ you"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3653}/H9021/[H3651]', 'inflected', 'heb', 'כֵּן', '["kên"]', '["office/ your"]', '["n-m"]', 'a stand, i.e. pedestal or station base, estate, foot, office, place, well.', 'the same as 3651, used as a noun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4941J}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["according to the/ custom","according to the/ customs","according to/ [the] custom of","according to/ custom"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4945A}/H9023/[H8248]', 'inflected', 'heb', 'מַשְׁקֶה', '["mashqeh"]', '["cup bearer/ his","cup bearing/ his"]', '["n-m"]', 'properly, causing to drink, i.e. a butler; by implication (intransitively), drink (itself); figuratively, a well-watered region butler(-ship), cupbearer, drink(-ing), fat pasture, watered.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2142}/H9030/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["cause to remember/ me","remember/ me","they will remember/ me","you have remembered/ me"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2142}/H9030/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["and/ you will bring to remembrance/ me","and/ you will remember/ me"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318H}/H9030/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ he brought out/ me","and/ you will bring out/ me","and/ you will take out/ me"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6622}/[H6622]', 'lemma', 'heb', 'פָּתַר', '["pâthar"]', '["[was one who] interpreted","he had interpreted","he interpreted"]', '["v"]', 'to open up, i.e. (figuratively) interpret (a dream) interpret(-ation, -er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5536}/[H5549]', 'lemma', 'heb', 'סַל', '["çal"]', '["[the] basket of","a basket","baskets of"]', '["n-m"]', 'properly, a willow twig (as pendulous), i.e. an osier; but only as woven into a basket basket.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2751}/[H2353]', 'lemma', 'heb', 'חֹרִי', '["chôrîy"]', '["white bread"]', '["n-m"]', 'white bread white.', 'from the same as 2353;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218A>/H9020', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ my"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5536}/[H5549]', 'inflected', 'heb', 'סַל', '["çal"]', '["and/ [was] in the/ basket"]', '["n-m"]', 'properly, a willow twig (as pendulous), i.e. an osier; but only as woven into a basket basket.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5945A}/[H5927]', 'inflected', 'heb', 'עֶלְיוֹן', '["ʻelyôwn"]', '["<the>/ upper","the/ upper [story]"]', '["n-m a"]', 'an elevation, i.e. (adj.) lofty (compar.); as title, the Supreme (Most, on) high(-er, -est), upper(-most).', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639G}/[H6213]', 'lemma', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["[are the] work of","[are] products of","[is the] work of","[is] work","[the] achievement of","[the] product of","[the] work","[the] work of","[the] works","[the] works of","[was] [the] work of","[were] [the] work of","[were] a work of","a thing made","a work","a work of","product of","work","work of"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5536}/[H5549]', 'inflected', 'heb', 'סַל', '["çal"]', '["the/ basket","the/ baskets"]', '["n-m"]', 'properly, a willow twig (as pendulous), i.e. an osier; but only as woven into a basket basket.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5921A}/H9031/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["from/ on <the>/ you","from/ on <the>/ yourself","from/ with <the>/ you"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8518}/[H8518]', 'inflected', 'heb', 'תָּלָה', '["tâlâh"]', '["and/ he will hang","and/ people will hang","and/ they hanged","and/ they hanged [them]","and/ they were hanged","and/ they will hang","and/ you will hang"]', '["v"]', 'to suspend (especially to gibbet) hang (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1320}/H9021/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["flesh/ your"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725H}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I will restore","and/ I will turn back","and/ he brought back","and/ he restored","and/ he returned","and/ he will repay","and/ he will restore","and/ he will turn back","and/ it came back","and/ it returned","and/ they went back","and/ they will return","and/ you took back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8518}/[H8518]', 'lemma', 'heb', 'תָּלָה', '["tâlâh"]', '["[he] hangs","[is] hung","[one who] is hanged","hanged","he hanged","hung up","let them hang","people hanged","they have been hanged","they have hanged","they hung up","we hung up"]', '["v"]', 'to suspend (especially to gibbet) hang (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2142}/[H2145]', 'lemma', 'heb', 'זָכַר', '["zâkar"]', '["I have remembered","I remember","I remember [this]","I remembered","I will bring to remembrance","I will cause to be remembered","I will remember","[am] bringing to remembrance","[he is] remembering","[one who] offers as a memorial","[was the] recorder","[was] recorder","[were] remembered","[which] brings to remembrance","[will] bring to remembrance","bring to remembrance","bringing to remembrance","carefully <to remember>","certainly <to remember>","continually <remember>","did he remember","he has brought to remembrance","he has remembered","he is remembered","he remembered","he remembers","he will remember","it is remembered","it remembers","it will be remembered","let him remember","let us bring to remembrance","make known","may he remember","may it be remembered","people will remember","remember","she has remembered","she remembered","someone will bring to remembrance","they bring to remembrance","they remembered","they will be remembered","they will remember","to cause to be remembered","we bring to remembrance","we remember","you have remembered","you may be remembered","you may remember","you must bring to remembrance","you remember","you remembered","you will be remembered","you will bring to remembrance","you will remember","you will remember [it]"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7911}/H9033\/[H7911]', 'inflected', 'heb', 'שָׁכַח', '["shâkach"]', '["and/ he forgot/ him"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117I>', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["[are] [the] days of","[the] days of","days"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6547H}/[H6547]', 'inflected', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["and/ Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2975G}/[H2975]', 'inflected', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["the/ River","the/ canals"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1277}/[H1254]', 'inflected', 'heb', 'בָּרִיא', '["bârîyʼ"]', '["and/ [is] fat","and/ fat of"]', '["a"]', 'fatted or plump fat ((fleshed), -ter), fed, firm, plenteous, rank.', 'from 1254 (in the sense of 1262);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7462B}/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["and/ I shepherded","and/ he will shepherd","and/ it will graze","and/ they grazed","and/ they have pastured [them]","and/ they have shepherded","and/ they will graze","and/ they will shepherd"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0260}/[H260]', 'inflected', 'heb', 'אָחוּ', '["ʼâchûw"]', '["among the/ reed[s]"]', '["n-m"]', 'a bulrush or any marshy grass (particularly that along the Nile) flag, meadow.', 'of uncertain (perhaps Egyptian) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310A}/H9039/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["after/ them","behind/ them"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1851}/[H1854]', 'inflected', 'heb', 'דַּק', '["daq"]', '["and/ [the] thin of","and/ thin of"]', '["a"]', 'crushed, i.e. (by implication) small or thin dwarf, lean(-fleshed), very little thing, small, thin.', 'from 1854;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0681}/[H680]', 'lemma', 'heb', 'אֵצֶל', '["ʼêtsel"]', '["[he was] beside","[is] beside","[was] beside","[were] beside","[will be] beside","beside"]', '["n-m"]', 'a side; (as a preposition) near at, (hard) by, (from) (beside), near (unto), toward, with. See also 1018.', 'from 680 (in the sense of joining);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6510}/[H6499]', 'inflected', 'heb', 'פָּרָה', '["pârâh"]', '["the/ cows","the/ heifer"]', '["n-f"]', 'a heifer cow, heifer, kine.', 'feminine of 6499;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4758}/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["<the>/ appearance","the/ appearance","the/ sight","the/ vision"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1277}/[H1254]', 'inflected', 'heb', 'בָּרִיא', '["bârîyʼ"]', '["and/ <the>/ fat"]', '["a"]', 'fatted or plump fat ((fleshed), -ter), fed, firm, plenteous, rank.', 'from 1254 (in the sense of 1262);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7641B}/[H7640]', 'lemma', 'heb', 'שִׁבֹּל', '["shibbôl"]', '["[the] clusters of","ears of grain","grain"]', '["n-f"]', 'a stream (as flowing); also an ear of grain (as growing out); by analogy, a branch branch, channel, ear (of corn), (water-)flood, Shibboleth. Compare 5451.', 'or (feminine) שִׁבֹּלֶת; from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7070H}/[H7069]', 'inflected', 'heb', 'קָנֶה', '["qâneh"]', '["by/ [the] reed of","on/ a stalk","with/ [the] reed of"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1277}/[H1254]', 'lemma', 'heb', 'בָּרִיא', '["bârîyʼ"]', '["[is] fat","fat","fat of"]', '["a"]', 'fatted or plump fat ((fleshed), -ter), fed, firm, plenteous, rank.', 'from 1254 (in the sense of 1262);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1851}/[H1854]', 'lemma', 'heb', 'דַּק', '["daq"]', '["a [man] thin","fine","soft","thin","thin [stuff]"]', '["a"]', 'crushed, i.e. (by implication) small or thin dwarf, lean(-fleshed), very little thing, small, thin.', 'from 1854;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7710}/[H7710]', 'inflected', 'heb', 'שָׁדַף', '["shâdaph"]', '["and/ scorched of"]', '["v"]', 'to scorch blast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6921}/[H6923]', 'lemma', 'heb', 'קָדִים', '["qâdîym"]', '["[the] east","[the] east wind","[was] east","an east wind","east","east wind"]', '["n-m"]', 'the fore or front part; hence (by orientation) the East (often adverbially, eastward, for brevity the east wind) east(-ward, wind).', 'or קָדִם; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1104}/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["and/ he will swallow up","and/ it swallowed","and/ it swallowed up","and/ it will swallow","and/ they swallowed"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7641B}/[H7640]', 'inflected', 'heb', 'שִׁבֹּל', '["shibbôl"]', '["the/ ears of grain"]', '["n-f"]', 'a stream (as flowing); also an ear of grain (as growing out); by analogy, a branch branch, channel, ear (of corn), (water-)flood, Shibboleth. Compare 5451.', 'or (feminine) שִׁבֹּלֶת; from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1851}/[H1854]', 'inflected', 'heb', 'דַּק', '["daq"]', '["<the>/ thin"]', '["a"]', 'crushed, i.e. (by implication) small or thin dwarf, lean(-fleshed), very little thing, small, thin.', 'from 1854;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1277}/[H1254]', 'inflected', 'heb', 'בָּרִיא', '["bârîyʼ"]', '["<the>/ fat","the/ fat [sheep]"]', '["a"]', 'fatted or plump fat ((fleshed), -ter), fed, firm, plenteous, rank.', 'from 1254 (in the sense of 1262);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4392}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["and/ <the>/ full","and/ the/ full [one]"]', '["a"]', 'full (literally or figuratively) or filling (literally); also (concretely) fulness; adverbially, fully × she that was with child, fill(-ed, -ed with), full(-ly), multitude, as is worth.', 'from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6470}/[H6470]', 'inflected', 'heb', 'פָּעַם', '["pâʻam"]', '["and/ it was troubled"]', '["v"]', 'to tap, i.e. beat regularly; hence (generally) to impel or agitate move, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307G}/H9023/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["spirit/ his","spirit/ its"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2748}/[H2747]', 'lemma', 'heb', 'חַרְטֹם', '["charṭôm"]', '["[the] diviner priests of","[the] magicians of"]', '["n-m"]', 'a horoscopist (as drawing magical lines or circles) magician.', 'from the same as 2747;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2450}/H9024/[H2449]', 'inflected', 'heb', 'חָכָם', '["châkâm"]', '["wise [men]/ its","wise [people]/ its"]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6547H}/[H6547]', 'inflected', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["[belongs] to/ Pharaoh","for/ Pharaoh","of/ Pharaoh","to/ Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2399}/H9020/[H2398]', 'inflected', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["sins/ my"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7107}/[H7107]', 'lemma', 'heb', 'קָצַף', '["qâtsaph"]', '["I was angry","I will be angry","[am] angry","he was angry","he will be angry","provoking to anger","will he be angry","you are angry","you be angry","you provoked to anger","you were angry"]', '["v"]', 'to crack off, i.e. (figuratively) burst out in rage (be) anger(-ry), displease, fret self, (provoke to) wrath (come), be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2492B}/H9012/[H2492]', 'inflected', 'heb', 'חָלַם', '["châlam"]', '["and/ we dreamed/ !"]', '["v"]', 'properly, to bind firmly, i.e. (by implication) to be (causatively to make) plump; also (through the figurative sense of dumbness) to dream (cause to) dream(-er), be in good liking, recover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8033G}/[H834]', 'inflected', 'heb', 'שָׁם', '["shâm"]', '["and/ [is] there","and/ [was] there","and/ [were] there","and/ [will be] there","and/ there"]', '["adv"]', 'there (transferring to time) then; often thither, or thence in it, thence, there (-in, of, out), thither, whither.', 'a primitive particle (rather from the relative pronoun, 834);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8269}/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["<into>/ a commander","into/ princes","of/ [the] commander of","to/ [the] commander of","to/ [the] commanders of","to/ [the] leaders of"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6622}/[H6622]', 'inflected', 'heb', 'פָּתַר', '["pâthar"]', '["and/ he interpreted"]', '["v"]', 'to open up, i.e. (figuratively) interpret (a dream) interpret(-ation, -er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2472}/H9025/[H2492]', 'inflected', 'heb', 'חֲלוֹם', '["chălôwm"]', '["dreams/ our"]', '["n-m"]', 'a dream dream(-er).', 'or (shortened) חֲלֹם; from 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2472}/H9023/[H2492]', 'inflected', 'heb', 'חֲלוֹם', '["chălôwm"]', '["according to/ dream/ his"]', '["n-m"]', 'a dream dream(-er).', 'or (shortened) חֲלֹם; from 2492;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725H}/[H7725]', 'lemma', 'heb', 'שׁוּב', '["shûwb"]', '["I will cause to turn back","I will restore","I will return","I will turn back","[am] about to turn back","[are] bringing back","[one who] restores","anyone will return [it]","bring [it] back","certainly <to return>","he had brought back","he restored","he restores","he returned","he turned back","he will return","it had turned back","it will return","may he bring back","restore","restored","restoring","they will return","we will return [it]","you turned back","you will restore","you will return"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3653}/H9020/[H3651]', 'inflected', 'heb', 'כֵּן', '["kên"]', '["office/ my"]', '["n-m"]', 'a stand, i.e. pedestal or station base, estate, foot, office, place, well.', 'the same as 3651, used as a noun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0853}/H9033/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ <obj.>/ him","and/ <obj.>/ it"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7323G}/H9033/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["and/ people brought quickly/ him"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1548}/[H1548]', 'inflected', 'heb', 'גָּלַח', '["gâlach"]', '["and/ he shaved","and/ he will shave","and/ he will shave himself","and/ she shaved off","and/ she will shave"]', '["v"]', 'properly, to be bald, i.e. (causatively) to shave; figuratively to lay waste poll, shave (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6622}/[H6622]', 'inflected', 'heb', 'פָּתַר', '["pâthar"]', '["to/ interpret"]', '["v"]', 'to open up, i.e. (figuratively) interpret (a dream) interpret(-ation, -er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6030B}/[H6030]', 'lemma', 'heb', 'עָנָה', '["ʻânâh"]', '["I am answered","I will answer","I will let myself give an answer","[was one who] answered","[who] testifies","[will be one who] answers","[will] let myself give an answer","answer","did he answer","does he answer","he answered","he answers","he has testified","he will answer","he will be answered","he will testify","it answers","it has testified","it testifies","it will answer","she answered","testify","they answered","they had answered","they have answered","they have testified","they testify","they will answer","will anyone answer","will it be answered","will you answer","you answer","you answered","you did answer","you must testify","you will answer"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965G}/[H7999]', 'lemma', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["<of> peace","[am] peace","[are] well-being","[in] peace","[is] peace","[is] safety","[the] peace of","[the] welfare of","[was] peace","peace","peace of","well-being"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1803B}/[H1802]', 'lemma', 'heb', 'דַּלָּה', '["dallâh"]', '["[the] poor people of","weak"]', '["n-f"]', 'properly, something dangling, i.e. a loose thread or hair; figuratively, indigent hair, pining sickness, poor(-est sort).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7451H}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["and/ [the] evil","and/ displeasing","and/ displeasing of","and/ evil [people]"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7534}/[H7556]', 'inflected', 'heb', 'רַק', '["raq"]', '["and/ thin of"]', '["a"]', 'emaciated (as if flattened out) lean(-fleshed), thin.', 'from 7556 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H9039}', 'inflected', 'heb', 'כהנה', '["ka./He.nah","ka./Hen","kha./He.nah"]', '["like/ them","like/ those"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7455}/[H7489]', 'inflected', 'heb', 'רֹעַ', '["rôaʻ"]', '["to <the>/ badness"]', '["n-m"]', 'badness (as marring), physically or morally × be so bad, badness, (× be so) evil, naughtiness, sadness, sorrow, wickedness.', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7534}/[H7556]', 'inflected', 'heb', 'רַק', '["raq"]', '["<the>/ thin"]', '["a"]', 'emaciated (as if flattened out) lean(-fleshed), thin.', 'from 7556 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7451A}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["and/ <the>/ displeasing","and/ the/ bad [figs]"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7130G}/H9029/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["inward part[s]/ their"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4758}/H9029/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["and/ appearance/ their"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6798}/[H6798]', 'lemma', 'heb', 'צָנַם', '["tsânam"]', '["withered"]', '["v"]', 'to blast or shrink withered.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7710}/[H7710]', 'lemma', 'heb', 'שָׁדַף', '["shâdaph"]', '["<the> scorched of","scorched of"]', '["v"]', 'to scorch blast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310A}/H9038/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["[was] behind/ them","after/ them","behind/ them"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2748}/[H2747]', 'inflected', 'heb', 'חַרְטֹם', '["charṭôm"]', '["the/ diviner priests","the/ magicians","the/ soothsayer-priests"]', '["n-m"]', 'a horoscopist (as drawing magical lines or circles) magician.', 'from the same as 2747;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5927G}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["[are] the/ [ones who] came up","[are] who/ came up","that/ is going up","that/ were coming up","the/ [ones who] came up","those/ [who] had gone up","which/ goes up","which/ have gone up","who/ brought up","who/ came up","who/ comes up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7386}/[H7324]', 'inflected', 'heb', 'רֵיק', '["rêyq"]', '["<the>/ empty","the/ worthless [men]"]', '["a"]', 'empty; figuratively, worthless emptied(-ty), vain (fellow, man).', 'or (shorter) רֵק; from 7324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6921}/[H6923]', 'inflected', 'heb', 'קָדִים', '["qâdîym"]', '["the/ east","the/ east wind"]', '["n-m"]', 'the fore or front part; hence (by orientation) the East (often adverbially, eastward, for brevity the east wind) east(-ward, wind).', 'or קָדִם; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7647}/[H7646]', 'lemma', 'heb', 'שָׂבָע', '["sâbâʻ"]', '["plenty"]', '["n-m"]', 'copiousness abundance, plenteous(-ness, -ly).', 'from 7646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7647}/[H7646]', 'inflected', 'heb', 'שָׂבָע', '["sâbâʻ"]', '["<the>/ plenty","the/ plenty"]', '["n-m"]', 'copiousness abundance, plenteous(-ness, -ly).', 'from 7646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3615H}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["and/ I made an end of","and/ he will make an end of","and/ it will bring to an end","and/ it will destroy","and/ it will put an end to","and/ you will come to an end"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8138B}/[H8138]', 'lemma', 'heb', 'שָׁנָה', '["shânâh"]', '["I will repeat","[the] being repeated of","[who] repeats","do again","he repeated","they repeated","you will do [it] again"]', '["v"]', 'to fold, i.e. duplicate (literally or figuratively); by implication, to transmute (transitive or intransitive) do (speak, strike) again, alter, double, (be given to) change, disguise, (be) diverse, pervert, prefer, repeat, return, do the second time.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559H}/[H3559]', 'lemma', 'heb', 'כּוּן', '["kûwn"]', '["I will establish","[has been] established","[is] certain","[is] established","[is] steadfast","[was] established","[was] steadfast","[were] established","a certain [thing]","direct","established","firmly","he directs","he established","he had appointed","he had directed","he had prepared","he has directed","he has established","he has prepared","he is established","he will be established","he will establish","it directed","it is established","it was established","it will be established","it will be steadfast","let him be established","let them be steadfast","they are established","they directed","they have established","they prepared","they will be steadfast","to make firm","you establish","you have established","you prepared","you will be established","you will direct"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4116A}/[H4116]', 'inflected', 'heb', 'מָהַר', '["mâhar"]', '["and/ [is] hurrying","and/ they may hasten","and/ they may make haste"]', '["v"]', 'properly, to be liquid or flow easily, i.e. (by implication); to hurry (in a good or a bad sense); often used (with another verb) adverbially, promptly be carried headlong, fearful, (cause to make, in, make) haste(-n, -ily), (be) hasty, (fetch, make ready) × quickly, rash, × shortly, (be so) × soon, make speed, × speedily, × straightway, × suddenly, swift.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6213A}/H9033/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["to/ do/ it","to/ observe/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0995}/[H995]', 'lemma', 'heb', 'בִּין', '["bîyn"]', '["I consider","I considered","I gain understanding","I have understanding","I observed","I perceive","I showed myself attentive","I understood","I will consider carefully","I will perceive","[are] having understanding","[he is] understanding","[is one who] understands","[is] a discerning [person]","[is] to understand","[is] understanding","[it is] giving understanding to","[one who] has understanding","[one who] understands","[one who] understood","[one who] was skilled","[was] a teacher","[were] causing to understand","a discerning [person]","anyone understands","carefully <consider>","consider","discerning","discerning [people]","discerning?","do you understand?","does he perceive","does it discern","explain","have you shown yourself attentive?","have you understood","he considers","he has understood","he perceives","he shows himself attentive","he understands","he understood","he will pay attention","he will perceive","he will understand","it considers carefully","it understands","it will understand","observing","teacher","teachers","they consider","they had understood","they understand","they will consider carefully","they will give understanding","they will perceive","they will understand","to understand","understand","understanding","will I look carefully","will he discern","will he make understand","will he understand","you consider","you understand","you will consider","you will discern","you will understand"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2450}/[H2449]', 'inflected', 'heb', 'חָכָם', '["châkâm"]', '["and/ [the] skillful [people] of","and/ a wise [person]","and/ skillful [one] of","and/ wise","and/ wise [people]"]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7896G}/H9033/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["and/ I will make/ it","and/ let him set/ him"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6485J}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ appoint","and/ let him appoint"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6496}/[H6485]', 'lemma', 'heb', 'פָּקִיד', '["pâqîyd"]', '["[was] an officer","[was] overseer","[were] overseers","an officer","appointees","overseers"]', '["n-m"]', 'a superintendent (civil, military or religious) which had the charge, governor, office, overseer, (that) was set.', 'from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2567}/[H2568]', 'inflected', 'heb', 'חָמַשׁ', '["châmash"]', '["and/ he will take a fifth of"]', '["v"]', 'to tax a fifth take up the fifth participle', 'a denominative from 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6908}/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["and/ [one who] gathers","and/ collect","and/ let me gather","and/ let them gather","so/ they may gather together"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0400}/[H398]', 'lemma', 'heb', 'אֹכֶל', '["ʼôkel"]', '["[the] food of","food"]', '["n-m"]', 'food eating, food, meal(-time), meat, prey, victuals.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8141}/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["<the>/ years","[was] the/ year","the/ year","the/ years","this/ year"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6651}/[H6651]', 'inflected', 'heb', 'צָבַר', '["tsâbar"]', '["and/ let them store up"]', '["v"]', 'to aggregate gather (together), heap (up), lay up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1250A}/[H1305]', 'lemma', 'heb', 'בָּר', '["bâr"]', '["grain"]', '["n-m"]', 'grain of any kind (even while standing in the field); by extension the open country corn, wheat.', 'or בַּר; from 1305 (in the sense of winnowing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478I}/[H8430]', 'lemma', 'heb', 'תַּחַת', '["tachath"]', '["in","under"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027H}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["[the] hand of","[the] hands of","a hand","hand","hands"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8104H}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ I have kept myself","and/ he has kept","and/ he took care","and/ he will keep","and/ people watched","and/ they will keep","and/ they will keep [it]","and/ you will keep","and/ you will keep yourself","and/ you will take heed"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0400}/[H398]', 'inflected', 'heb', 'אֹכֶל', '["ʼôkel"]', '["the/ food","the/ meal"]', '["n-m"]', 'food eating, food, meal(-time), meat, prey, victuals.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6487}/[H6485]', 'inflected', 'heb', 'פִּקָּדוֹן', '["piqqâdôwn"]', '["<into>/ a store"]', '["n-m"]', 'a deposit that which was delivered (to keep), store.', 'from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0776G>', 'inflected', 'heb', 'לארץ', '["La./''a.retz","la./''A.Retz","la./''A.retz","le./''E.retz","le./''e.retz"]', '["<to> the/ earth","[are] to the/ earth","for the/ earth","for the/ land","of/ [the] land of","to the/ earth","to the/ ground","to the/ land","to/ [the] land of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7458}/[H7456]', 'inflected', 'heb', 'רָעָב', '["râʻâb"]', '["by <the>/ famine","by the/ famine","by/ hunger","in <the>/ famine","in the/ famine","in/ famine","in/ hunger","with <the>/ famine"]', '["n-m"]', 'hunger (more or less extensive) dearth, famine, famished, hunger.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4672}/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["¿/ has he been found"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2088}/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["[is] like/ this [one]","like/ this","like/ this one"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3644G}/H9031/[H3651]', 'inflected', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["[is] like/ you","as/ you","like/ you","like/ yourself"]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310I}/H9021/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["mouth/ your"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5401A}/[H5400]', 'lemma', 'heb', 'נָשַׁק', '["nâshaq"]', '["I want to kiss","he kisses","it has kissed","it will kiss","kiss","they kiss","touching closely"]', '["v"]', 'to kiss, literally or figuratively (touch); also (as a mode of attachment), to equip with weapons armed (men), rule, kiss, that touched.', 'a primitive root (identical with 5400, through the idea of fastening up; compare 2388, 2836);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3678G}/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["the/ throne"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2885}/H9023/[H2883]', 'inflected', 'heb', 'טַבַּעַת', '["ṭabbaʻath"]', '["signet-ring/ his"]', '["n-m"]', 'properly, a seal (as sunk into the wax), i.e. signet (for sealing); hence (generally) a ring of any kind ring.', 'from 2883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8336B}/[H4897]', 'lemma', 'heb', 'שֵׁשׁ', '["shêsh"]', '["[is] fine linen","[was] fine linen","[were] fine linen","fine linen"]', '["n-m"]', 'bleached stuff, i.e. white linen or (by analogy) marble × blue, fine (twined) linen, marble, silk.', 'or (for alliteration with 4897) שְׁשִׁי; for 7893;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7242}/[H7234]', 'lemma', 'heb', 'רָבִיד', '["râbîyd"]', '["[the] chain of"]', '["n-m"]', 'a collar (as spread around the neck) chain.', 'from 7234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4818}/[H4817]', 'inflected', 'heb', 'מֶרְכָּבָה', '["merkâbâh"]', '["[were] with the/ chariot","in the/ chariot","in/ [the] chariot of"]', '["n-f"]', 'a chariot chariot. See also 1024.', 'feminine of 4817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4932H}/[H8138]', 'inflected', 'heb', 'מִשְׁנֶה', '["mishneh"]', '["<the>/ second","[was] the/ second","the/ second","the/ second in rank","the/ second rank"]', '["n-m"]', 'properly, a repetition, i.e. a duplicate (copy of a document), or a double (in amount); by implication, a second (in order, rank, age, quality or location) college, copy, double, fatlings, next, second (order), twice as much.', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0086}/[H86]', 'lemma', 'heb', 'אַבְרֵךְ', '["ʼabrêk"]', '["bend [the] knee"]', '["v"]', 'kneel bow the knee.', 'probably an Egyptian word meaning');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5414H}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I have given","and/ he put","and/ put"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1107}/H9031/[H1077]', 'inflected', 'heb', 'בִּלְעֲדֵי', '["bilʻădêy"]', '["and/ apart from/ you"]', '["prt"]', 'except, without, besides beside, not (in), save, without.', 'or בַּלְעֲדֵי; constructive plural from 1077 and 5703, not till, i.e. (as preposition or adverb)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6847}/[H6847]', 'lemma', 'heb', 'צׇפְנַת פַּעְנֵחַ', '["Tsophnath Paʻnêach"]', '["Paneah","Zaphenath-"]', '["n-pr-m"]', 'Tsophnath-Paneach, Joseph''s Egyptian name Zaphnath-paaneah.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0621}/[H621]', 'lemma', 'heb', 'אָסְנַת', '["ʼÂçᵉnath"]', '["Asenath"]', '["n-pr-f"]', 'Asenath, the wife of Joseph Asenath.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6319}/[H6319]', 'lemma', 'heb', 'פּוֹטִי פֶרַע', '["Pôwṭîy Pheraʻ"]', '["-phera","Poti-"]', '["n-pr-m"]', 'Poti-Phera, an Egyptian Poti-pherah.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0204}/[H204]', 'lemma', 'heb', 'אוֹן', '["ʼÔwn"]', '["On"]', '["n-pr-loc"]', 'On, a city of Egypt On.', 'or (shortened); אֹן; of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5975H}/H9043/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["when/ stood/ he"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H6440G}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ to/ before","from/ to/ faces"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7062}/[H7061]', 'inflected', 'heb', 'קֹמֶץ', '["qômets"]', '["to/ handfuls"]', '["n-m"]', 'a grasp, i.e. handful handful.', 'from 7061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6908}/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["and/ I will gather","and/ he assembled","and/ he gathered","and/ he has assembled","and/ they assembled","and/ they gathered","and/ they gathered together","and/ they will be gathered","and/ you gathered"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439G}/H9034/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["[are] around/ it","[was] around/ it","around/ it"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8432>/H9024', 'inflected', 'heb', 'בתוכה', '["be./to.Kha/h","ve./to.Kha/h"]', '["[is] in/ [the] midst of/ it","[will be] in/ [the] midst of/ it","in/ [the] midst of/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6651}/[H6651]', 'inflected', 'heb', 'צָבַר', '["tsâbar"]', '["and/ he stored up","and/ it heaped up","and/ people piled up"]', '["v"]', 'to aggregate gather (together), heap (up), lay up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3130G}/[H3254]', 'inflected', 'heb', 'יוֹסֵף', '["Yôwçêph"]', '["and/ of/ Joseph","and/ to/ Joseph"]', '["n-pr-m"]', 'Joseph, the name of seven Israelites Joseph. Compare 3084.', 'future of 3254; let him add (or perhaps simply active participle adding);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1060}/[H1069]', 'inflected', 'heb', 'בְּכוֹר', '["bᵉkôwr"]', '["<the>/ firstborn","[is] the/ firstborn","[was] the/ firstborn","the/ firstborn"]', '["n-m"]', 'first-born; hence, chief eldest (son), firstborn(-ling).', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4519G}/[H5382]', 'lemma', 'heb', 'מְנַשֶּׁה', '["Mᵉnashsheh"]', '["Manasseh"]', '["n-pr-m"]', 'Menashsheh, a grandson of Jacob, also the tribe descended from him, and its territory Manasseh.', 'from 5382; causing to forget;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5382}/H9030/[H5382]', 'inflected', 'heb', 'נָשָׁה', '["nâshâh"]', '["he has made forget/ me","you will be forgotten by/ me"]', '["v"]', 'to forget; figuratively, to neglect; causatively, to remit, remove forget, deprive, exact.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5999}/H9020/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["toil/ my","trouble/ my"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0669G}/[H672]', 'lemma', 'heb', 'אֶפְרַיִם', '["ʼEphrayim"]', '["Ephraim","O Ephraim","[is] Ephraim"]', '["n-pr-m"]', 'Ephrajim, a son of Joseph; also the tribe descended from him, and its territory Ephraim, Ephraimites.', 'dual of masculine form of 672; double fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6509}/H9030/[H6509]', 'inflected', 'heb', 'פָּרָה', '["pârâh"]', '["he has made fruitful/ me"]', '["v"]', 'to bear fruit (literally or figuratively) bear, bring forth (fruit), (be, cause to be, make) fruitful, grow, increase.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7456}/[H7456]', 'inflected', 'heb', 'רָעֵב', '["râʻêb"]', '["and/ it was hungry"]', '["v"]', 'to hunger (suffer to) famish, (be, have, suffer, suffer to) hunger(-ry).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3899H}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["for <the>/ bread","for <the>/ food","for/ [the] bread of","into/ bread","to the/ bread"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7458}/[H7456]', 'inflected', 'heb', 'רָעָב', '["râʻâb"]', '["and/ <the>/ famine","and/ the/ famine"]', '["n-m"]', 'hunger (more or less extensive) dearth, famine, famished, hunger.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7666}/[H7668]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["and/ he bought grain"]', '["v"]', 'to deal in grain buy, sell.', 'denominative from 7668;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4714G}/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["[is] to/ Egypt","for/ Egypt","of/ Egypt","to/ Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2388G}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ I will make strong","and/ I will strengthen","and/ he encouraged","and/ he made strong","and/ he repaired","and/ he strengthened","and/ he strengthened himself","and/ he was strong","and/ it showed itself strong","and/ it urged","and/ it was severe","and/ it was strong","and/ they have strengthened","and/ they repaired","and/ they strengthened","and/ they will be strong","and/ you will be strong","and/ you will show yourselves strong","and/ you will strengthen"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7666}/[H7668]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["to/ buy","to/ buy grain"]', '["v"]', 'to deal in grain buy, sell.', 'denominative from 7668;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388G}/[H2388]', 'lemma', 'heb', 'חָזַק', '["châzaq"]', '["I strengthened","I strengthened myself","I will make strong","[am] about to make strong","[are] holding","[the] repairers of","[who] shows himself strong","be strong","encourage","he displayed strength","he has strengthened","he keeps hold of","he repaired","he strengthened himself","he was strong","he will be strong","it became strong","it was severe","it was strong","it will be [too] strong","let them be strong","make strong","repairing","she strengthened","show yourselves strong","strengthen","strengthen yourself","strengthening himself","they became strong","they encouraged","they had repaired","they have been strong","they made strong","they may be strong","they repaired","they should become strong","they strengthened","they were strong","they will be [too] strong","they will be strong","they will repair","they will strengthen themselves","to repair","we will be strong","will they be strong","you have strengthened","you may be strong","you strengthened"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200H}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ I will see","and/ he saw","and/ we saw"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7668}/[H7667]', 'lemma', 'heb', 'שֶׁבֶר', '["sheber"]', '["[is] grain","[the] grain of","[was] grain","grain"]', '["n-m"]', 'grain (as if broken into kernels) corn, victuals.', 'the same as 7667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4714G}/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["[are] in/ Egypt","[is] in/ Egypt","[was] in/ Egypt","against/ Egypt","in/ Egypt","on/ Egypt","with/ Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7666}/[H7668]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["and/ buy grain","and/ we will buy","so/ we may sell grain"]', '["v"]', 'to deal in grain buy, sell.', 'denominative from 7668;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7122I}/H9033/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["it should happen to/ him"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0611>', 'opaque', 'heb', 'אָסוֹן', '["ʼâçôwn"]', '["harm"]', '["n-m"]', 'hurt mischief.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7989}/[H7980]', 'inflected', 'heb', 'שַׁלִּיט', '["shallîyṭ"]', '["[was] the/ ruler","the/ ruler"]', '["a"]', 'potent; concretely, a prince or warrior governor, mighty, that hath power, ruler.', 'from 7980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7666}/[H7668]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["[was] the/ [one who] sold grain"]', '["v"]', 'to deal in grain buy, sell.', 'denominative from 7668;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5234A}/H9038/[H5234]', 'inflected', 'heb', 'נָכַר', '["nâkar"]', '["and/ he recognized/ them"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5234B}/[H5234]', 'inflected', 'heb', 'נָכַר', '["nâkar"]', '["and/ he acted as a stranger","and/ they have treated as foreign"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7186}/[H7185]', 'lemma', 'heb', 'קָשֶׁה', '["qâsheh"]', '["[are too] hard","[are] stern of","[is] severe","[was] hard","[were] stubborn","a hard [thing]","cruel","hard","hard of","harsh","severe","stiff of"]', '["a"]', 'severe (in various applications) churlish, cruel, grievous, hard((-hearted), thing), heavy, impudent, obstinate, prevailed, rough(-ly), sore, sorrowful, stiff(necked), stubborn, in trouble.', 'from 7185;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7270}/[H7272]', 'lemma', 'heb', 'רָגַל', '["râgal"]', '["[are] spies","he takes slander","spies"]', '["v"]', 'to walk along; but only in specifically, applications, to reconnoiter, to be a tale-bearer (i.e. slander); to lead about backbite, search, slander, (e-) spy (out), teach to go, view.', 'a primitive root; also as denominative from 7272');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5650}/H9021/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["and/ [male] servant/ your","and/ [male] slave/ your","and/ servant/ your","and/ servants/ your"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3605}/H9025/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["all of/ us"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5168}/[H587]', 'lemma', 'heb', 'נַחְנוּ', '["nachnûw"]', '["we"]', '["p"]', 'we we.', 'for 587;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3651A}/[H3559]', 'lemma', 'heb', 'כֵּן', '["kên"]', '["[are] honest","right","thus","true"]', '["adv"]', 'properly, set upright; hence (figuratively as adjective) just; but usually (as adverb or conjunction) rightly or so (in various applications to manner, time and relation; often with other particles) after that (this, -ward, -wards), as... as, (for-) asmuch as yet, be (for which) cause, following, howbeit, in (the) like (manner, -wise), × the more, right, (even) so, state, straightway, such (thing), surely, there (where) -fore, this, thus, true, well, × you.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6996H}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["<the>/ young","the/ young [brother]"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0259}/[H258]', 'inflected', 'heb', 'אֶחָד', '["ʼechâd"]', '["and/ the/ one","and/ the/ one [tooth]"]', '["a"]', 'properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,', 'a numeral from 258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0974}/[H974]', 'lemma', 'heb', 'בָּחַן', '["bâchan"]', '["[am] testing","[are] testing","[who] tests","does it test","he tests","he will be tested","it has been tested","it tests","they have tested","they test","you have tested","you will be tested"]', '["v"]', 'to test (especially metals); generally and figuratively, to investigate examine, prove, tempt, try (trial).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ came","when/ comes","when/ go","when/ goes","when/ will come"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251G}/H9026/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["brother/ your","relatives/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H9036}', 'inflected', 'heb', 'מכם', '["mi./Kem"]', '["any of <the>/ you","for/ you","from <the>/ you","from/ you","more than/ you","of <the>/ you","of <the>/ yourselves","of/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0974}/[H974]', 'inflected', 'heb', 'בָּחַן', '["bâchan"]', '["and/ [is] testing","and/ [who] tests","so/ they may be tested"]', '["v"]', 'to test (especially metals); generally and figuratively, to investigate examine, prove, tempt, try (trial).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697G}/H9026/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0571H}/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["¿/ [is] truth"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4929}/[H8104]', 'lemma', 'heb', 'מִשְׁמָר', '["mishmâr"]', '["a guard","custody","division","guard","guarding"]', '["n-m"]', 'a guard (the man, the post or the prison); a deposit (figuratively); also (as observed) a usage (abstractly), or an example (concretely) diligence, guard, office, prison, ward, watch.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4929}/H9026/[H8104]', 'inflected', 'heb', 'מִשְׁמָר', '["mishmâr"]', '["custody/ your"]', '["n-m"]', 'a guard (the man, the post or the prison); a deposit (figuratively); also (as observed) a usage (abstractly), or an example (concretely) diligence, guard, office, prison, ward, watch.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7459}/[H7456]', 'lemma', 'heb', 'רְעָבוֹן', '["rᵉʻâbôwn"]', '["[the] hunger of","famine"]', '["n-m"]', 'famine famine.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004M}/H9026/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["households/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0539}/[H541]', 'inflected', 'heb', 'אָמַן', '["ʼâman"]', '["and/ a [person] faithful of","and/ faithful","and/ it may be established","and/ lasting","and/ you may believe","so/ they may be verified","so/ you may be established"]', '["v"]', 'properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right.', 'a primitive root; (Isaiah 30:21; interchangeable with 541, to go to the right hand)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0818}/[H816]', 'lemma', 'heb', 'אָשֵׁם', '["ʼâshêm"]', '["[are] guilty"]', '["a"]', 'guilty; hence, presenting a sin-offering one which is faulty, guilty.', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6869B}/[H6862]', 'lemma', 'heb', 'צָרָה', '["tsârâh"]', '["[the] distress of","[the] troubles of","distress","trouble","troubles"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2603A}/H9043/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["when/ sought favor/ he"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6869B}/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["the/ distress","the/ troubles"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3206}/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["against the/ boy"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3887}/[H3887]', 'inflected', 'heb', 'לוּץ', '["lûwts"]', '["the/ interpreter"]', '["v"]', 'properly, to make mouths at, i.e. to scoff; hence (from the effort to pronounce a foreign language) to interpret, or (generally) intercede ambassador, have in derision, interpreter, make a mock, mocker, scorn(-er, -ful), teacher.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0996G}/H9038/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["[was] between/ them","between/ them"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5437G}/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["and/ I turned","and/ I will turn around","and/ he brought round","and/ he caused to go around","and/ he had turned","and/ he turned","and/ he turned around","and/ he turned away","and/ he turned over","and/ he turned round","and/ he went around","and/ it has turned round","and/ it surrounded","and/ it turns","and/ it will turn","and/ they brought round","and/ they surrounded","and/ they turned","and/ they turned round","and/ they went around","and/ they will go about"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5921A}/H9038/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["<from>/ above <the>/ them","from/ <the> on/ them","from/ <the> with/ them","from/ on <the>/ them","from/ on/ them","from/ over <the>/ them","from/ with <the>/ them"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0854}/H9038/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["from/ with <the>/ them","from/ with/ them"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0631}/[H631]', 'inflected', 'heb', 'אָסַר', '["ʼâçar"]', '["and/ he bound","and/ he harnessed","and/ she will bind","and/ someone harnessed","and/ you will harness"]', '["v"]', 'to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869J}/H9028/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ their"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3627}/H9028/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["[is] vessels/ their","articles/ their","equipment<s>/ their","vessels/ their"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7725G}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ to/ return"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3701G}/H9028/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["silver/ their","silver<s>/ their"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8242}/H9023/[H8264]', 'inflected', 'heb', 'שַׂק', '["saq"]', '["sack/ his","sackcloth/ his"]', '["n-m"]', 'properly, a mesh (as allowing a liquid to run through), i.e. coarse loose cloth or sacking (used in mourning and for bagging); hence, a bag (for grain, etc.) sack(-cloth, -clothes).', 'from 8264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5414G}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["<and>/ to/ give","and/ by/ giving","and/ to/ deliver up","and/ to/ give"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6720}/[H6718]', 'lemma', 'heb', 'צֵידָה', '["tsêydâh"]', '["food","provision[s]"]', '["n-f"]', 'food meat, provision, venison, victuals.', 'or צֵדָה; feminine of 6718;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1870L}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["for the/ journey","to/ [the] journey of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7668}/H9028/[H7667]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["grain/ their"]', '["n-m"]', 'grain (as if broken into kernels) corn, victuals.', 'the same as 7667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2543}/H9023/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["for/ donkey/ his","to/ donkey/ his"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4411}/[H3885]', 'inflected', 'heb', 'מָלוֹן', '["mâlôwn"]', '["at the/ lodging place"]', '["n-m"]', 'a lodgment, i.e. caravanserai or encampment inn, place where...lodge, lodging (place).', 'from 3885;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6310G}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["[is] in/ [the] mouth of","[was] in/ [the] mouth of","by/ [the] mouth","by/ [the] mouth of","in/ [the] mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0572}/H9023/[H4969]', 'inflected', 'heb', 'אַמְתַּחַת', '["ʼamtachath"]', '["sack/ his"]', '["n-f"]', 'properly, something expansive, i.e. a bag sack.', 'from 4969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3701G}/H9020/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["silver/ my"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0572}/H9020/[H4969]', 'inflected', 'heb', 'אַמְתַּחַת', '["ʼamtachath"]', '["in/ sack/ my"]', '["n-f"]', 'properly, something expansive, i.e. a bag sack.', 'from 4969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318P}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ it went out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9028/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart/ their","hearts/ their","own heart/ their"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7136A}/[H7136]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["the/ [things which] had happened to"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414I}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I made","and/ I will give","and/ I will make","and/ I will put","and/ he appointed","and/ he has made","and/ he made","and/ they made","and/ they will make","and/ you gave","and/ you have made","and/ you made"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0853}/H9035/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["<obj.>/ us"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7270}/[H7272]', 'inflected', 'heb', 'רָגַל', '["râgal"]', '["like/ [those who] spy out"]', '["v"]', 'to walk along; but only in specifically, applications, to reconnoiter, to be a tale-bearer (i.e. slander); to lead about backbite, search, slander, (e-) spy (out), teach to go, view.', 'a primitive root; also as denominative from 7272');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6996H}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["and/ the/ young [brother]"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5117}/[H5117]', 'lemma', 'heb', 'נוּחַ', '["nûwach"]', '["I am at rest","I will be quiet","[is] giving rest","[is] permitting","[was] free space","give rest","gives rest","he gave rest","he had given rest","he had left","he has given rest","he left","he may rest","he permitted","he placed","he will give rest","he will leave","he will place","he will rest","he will thrust [it] down","it has been given rest","it has rested","it has stood","it is at rest","it may rest","it rests","it settles","it will be rest","it will cause to rest","it will rest","leave","leave alone","place","they had rest","they have caused to rest","they rest","they set down","they thrust down","they will rest","they will set down","you give rest to","you leave"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0935P}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ [some who] brought","and/ [some who] brought [them]","and/ [those who] bring","and/ bring","and/ bring [it]","and/ bring [them]","and/ you have brought","so/ we may bring"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7324}/[H7324]', 'lemma', 'heb', 'רוּק', '["rûwq"]', '["I will draw","[were] emptying","[which] it is poured out","it has been poured","they will empty out","they will pour [it] out","will he empty"]', '["v"]', 'to pour out (literally or figuratively), i.e. empty × arm, cast out, draw (out), (make) empty, pour forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8242}/H9028/[H8264]', 'inflected', 'heb', 'שַׂק', '["saq"]', '["sacks/ their"]', '["n-m"]', 'properly, a mesh (as allowing a liquid to run through), i.e. coarse loose cloth or sacking (used in mourning and for bagging); hence, a bag (for grain, etc.) sack(-cloth, -clothes).', 'from 8264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6872A}/[H6887]', 'lemma', 'heb', 'צְרוֹר', '["tsᵉrôwr"]', '["[is] [the] bag of","[the] bag of","[the] bags of","a bag"]', '["n-m"]', 'a parcel (as packed up); also a kernel or particle (as if a package) bag, × bendeth, bundle, least grain, small stone.', 'or (shorter) צְרֹר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8242}/H9023/[H8264]', 'inflected', 'heb', 'שַׂק', '["saq"]', '["[was] in/ sack/ his"]', '["n-m"]', 'properly, a mesh (as allowing a liquid to run through), i.e. coarse loose cloth or sacking (used in mourning and for bagging); hence, a bag (for grain, etc.) sack(-cloth, -clothes).', 'from 8264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0001G}/H9028/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ ancestors/ their","and/ father/ their"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3605}/H9029/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["all of/ them"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935P}/H9033/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["I have brought/ him","I will bring/ him","I will bring/ it","he brings/ it","he brought/ him","he has brought/ it","he will bring/ it","they brought/ him","they brought/ it","will he bring/ him","you will bring/ him"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414H}/H9012/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["put/ !","set/ !"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725G}/H9033/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["I will bring back/ him","bring back/ him","he had brought back/ him","will he turn back/ him","you will return/ it"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7604}/[H7604]', 'lemma', 'heb', 'שָׁאַר', '["shâʼar"]', '["I remained","I was left behind","I will leave","I will leave as a remnant","[is] remaining","anyone was left","he had left","he has left","he left","he left behind","he remained","he remains","he spared","he survived","he was left","it has remained","it is left","it left over","it remained","it remains","it was left","it will have left","it will leave","it will remain","they are left","they had survived","they have survived","they left","they remained","they will be left","they will leave over","they will remain","we are left","we spared","we will leave","will they leave","will they leave?"]', '["v"]', 'properly, to swell up, i.e. be (causatively, make) redundant leave, (be) left, let, remain, remnant, reserve, the rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7122I}/H9033/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ it will happen to/ him"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7872}/H9020/[H7869]', 'inflected', 'heb', 'שֵׂיבָה', '["sêybâh"]', '["gray hair/ my"]', '["n-f"]', 'old age (be) gray (grey hoar,-y) hairs (head,-ed), old age.', 'feminine of 7869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3015}/[H3013]', 'inflected', 'heb', 'יָגוֹן', '["yâgôwn"]', '["in/ sorrow"]', '["n-m"]', 'affliction grief, sorrow.', 'from 3013;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615J}/[H3615]', 'lemma', 'heb', 'כָּלָה', '["kâlâh"]', '["I caused to fail","I have caused to fail","I have come to an end","I will use up","he has completed","it had come to an end","it has been completed","it has wasted away","it is exhausted","it vanishes","it was at an end","it will be at an end","it will end","it will fail","they are faint","they failed","they finished","they have come to an end","they have failed","they have wasted away","they will come to an end","they will fail","you will finish"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7668}/[H7667]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["the/ grain"]', '["n-m"]', 'grain (as if broken into kernels) corn, victuals.', 'the same as 7667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7666}/[H7668]', 'lemma', 'heb', 'שָׁבַר', '["shâbar"]', '["[one who] sells grain","[were] buying grain","buy","buy grain","we will sell grain","you will buy"]', '["v"]', 'to deal in grain buy, sell.', 'denominative from 7668;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5749B}/[H5749]', 'lemma', 'heb', 'עוּד', '["ʻûwd"]', '["I call as witnesses","I have warned","I testify","I warned","[am] warning","certainly <to warn>","he has testified","he warned","they had warned","warn","you admonished","you warned","you will warn"]', '["v"]', 'to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440H}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ my","presence/ my"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4138}/H9025/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["and/ of/ kindred/ our"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310K}/[H6284]', 'lemma', 'heb', 'פֶּה', '["peh"]', '["[the] mouth of","a mouth","a mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971G}/H9012/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["send/ !"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2945}/H9025/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["little one[s]/ our"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6148}/H9033/[H6148]', 'inflected', 'heb', 'עָרַב', '["ʻârab"]', '["I will stand surety for/ him"]', '["v"]', 'to braid, i.e. intermix; technically, to traffic (as if by barter); also or give to be security (as a kind of exchange) engage, (inter-) meddle (with), mingle (self), mortgage, occupy, give pledges, be(-come, put in) surety, undertake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1245}/H9033/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["I sought/ him","I will seek/ it","[those who] seek/ him","they had sought/ him","they have sought/ him","you will require/ him"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3322}/H9033/[H3322]', 'inflected', 'heb', 'יָצַג', '["yâtsag"]', '["and/ I will set/ him"]', '["v"]', 'to place permanently establish, leave, make, present, put, set, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3117K>', 'inflected', 'heb', 'הימים', '["Hai./yom","hai./Yom","hai./ya.Mim"]', '["the/ day","the/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4102}/[H4100]', 'lemma', 'heb', 'מָהַהּ', '["mâhahh"]', '["I have delayed","[will] delay","delay","it will delay","we had delayed"]', '["v"]', 'properly, to question or hesitate, i.e. (by implication) to be reluctant delay, linger, stay selves, tarry.', 'apparently a denominative from 4100;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2173}/[H2168]', 'inflected', 'heb', 'זִמְרָה', '["zimrâh"]', '["some of/ [the] best products of"]', '["n-f"]', 'pruned (i.e. choice) fruit best fruit.', 'from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3627}/H9026/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["in/ vessels/ your"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6875>', 'opaque', 'heb', 'צְרִי', '["tsᵉrîy"]', '["balm"]', '["n-m"]', 'distillation, i.e. balsam balm.', 'or צֳרִי; from an unused root meaning to crack (as by pressure), hence, to leak;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4592}/[H4591]', 'inflected', 'heb', 'מְעַט', '["mᵉʻaṭ"]', '["and/ a little of","and/ little"]', '["n-m"]', 'a little or few (often adverbial or comparative) almost (some, very) few(-er, -est), lightly, little (while), (very) small (matter, thing), some, soon, × very.', 'or מְעָט; from 4591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1706>', 'opaque', 'heb', 'דְּבַשׁ', '["dᵉbash"]', '["honey"]', '["n-m"]', 'honey (from its stickiness); by analogy, syrup honey(-comb).', 'from an unused root meaning to be gummy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0992}/[H990]', 'lemma', 'heb', 'בֹּטֶן', '["bôṭen"]', '["pistachio nuts"]', '["n-m"]', '(only in plural) a pistachio-nut (from its form) nut.', 'from 990;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8247}/[H8245]', 'inflected', 'heb', 'שָׁקֵד', '["shâqêd"]', '["and/ almonds"]', '["n-m"]', 'the almond (tree or nut; as being the earliest in bloom) almond (tree).', 'from 8245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4932H}/[H8138]', 'lemma', 'heb', 'מִשְׁנֶה', '["mishneh"]', '["<the> copy of","[the] double of","[the] second","[the] second of","[was] second","[was] second in command","double","second","second order"]', '["n-m"]', 'properly, a repetition, i.e. a duplicate (copy of a document), or a double (in amount); by implication, a second (in order, rank, age, quality or location) college, copy, double, fatlings, next, second (order), twice as much.', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027I}/H9026/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["in/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7725G}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["that/ was returned","which/ had returned","which/ returned","who/ <she> returned","who/ had returned","who/ returned"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0572}/H9026/[H4969]', 'inflected', 'heb', 'אַמְתַּחַת', '["ʼamtachath"]', '["sacks/ your"]', '["n-f"]', 'properly, something expansive, i.e. a bag sack.', 'from 4969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4870}/[H7686]', 'lemma', 'heb', 'מִשְׁגֶּה', '["mishgeh"]', '["[was] a mistake"]', '["n-m"]', 'an error oversight.', 'from 7686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7356B}/[H7355]', 'lemma', 'heb', 'רַחַם', '["racham"]', '["compassion<s>"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4932H}/[H8138]', 'inflected', 'heb', 'מִשְׁנֶה', '["mishneh"]', '["and/ double"]', '["n-m"]', 'properly, a repetition, i.e. a duplicate (copy of a document), or a double (in amount); by implication, a second (in order, rank, age, quality or location) college, copy, double, fatlings, next, second (order), twice as much.', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027K}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[was] in/ hand/ their","in/ hand/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2873}/[H2873]', 'inflected', 'heb', 'טָבַח', '["ṭâbach"]', '["and/ slaughter"]', '["v"]', 'to slaughter (animals or men) kill, (make) slaughter, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2874}/[H2873]', 'lemma', 'heb', 'טֶבַח', '["ṭebach"]', '["[the] slaughter","a slaughter"]', '["n-m"]', 'properly, something slaughtered; hence, a beast (or meat, as butchered); abstractly butchery (or concretely, a place of slaughter) × beast, slaughter, × slay, × sore.', 'from 2873;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3559A}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["<and>/ to direct","and/ prepare","and/ prepare [it]","and/ they may be established","and/ to prepare"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6672A}/[H6671]', 'inflected', 'heb', 'צֹהַר', '["tsôhar"]', '["at <the>/ noon<s>","at the/ noontide<s>","in the/ noontide<s>"]', '["n-m"]', 'a light (i.e. window); dual double light, i.e. noon midday, noon(-day, -tide), window.', 'from 6671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9011/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[the] house of/ towards","a household/ <towards>","home/ towards"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0572}/H9025/[H4969]', 'inflected', 'heb', 'אַמְתַּחַת', '["ʼamtachath"]', '["in/ sacks/ our"]', '["n-f"]', 'properly, something expansive, i.e. a bag sack.', 'from 4969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1556}/[H1556]', 'inflected', 'heb', 'גָּלַל', '["gâlal"]', '["to/ roll himself"]', '["v"]', 'to roll (literally or figuratively) commit, remove, roll (away, down, together), run down, seek occasion, trust, wallow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5307G}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ to/ make fall","and/ to/ throw himself"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2543}/H9025/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["donkeys/ our"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0994}/[H1158]', 'lemma', 'heb', 'בִּי', '["bîy"]', '["pardon me","pardon us"]', '["prt"]', 'oh that!; with leave, or if it please alas, O, oh.', 'perhaps from 1158 (in the sense of asking); properly, a request; used only adverbially (always with ''my Lord'');');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4411}/[H3885]', 'inflected', 'heb', 'מָלוֹן', '["mâlôwn"]', '["the/ lodging place"]', '["n-m"]', 'a lodgment, i.e. caravanserai or encampment inn, place where...lodge, lodging (place).', 'from 3885;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6605A}/H9012/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["and/ we opened/ !"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0572}/H9025/[H4969]', 'inflected', 'heb', 'אַמְתַּחַת', '["ʼamtachath"]', '["sacks/ our"]', '["n-f"]', 'properly, something expansive, i.e. a bag sack.', 'from 4969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4948}/H9023/[H8254]', 'inflected', 'heb', 'מִשְׁקָל', '["mishqâl"]', '["in/ weight/ its"]', '["n-m"]', 'weight (numerically estimated); hence, weighing (the act) (full) weight.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027I}/H9025/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["in/ hand/ our"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9026/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ your","[am] God/ your","god/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4301}/[H2934]', 'lemma', 'heb', 'מַטְמוֹן', '["maṭmôwn"]', '["treasure","treasures"]', '["n-m"]', 'a secret storehouse; hence, a secreted valuable (buried); generally money hidden riches, (hid) treasure(-s).', 'or מַטְמֹן; or מַטְמֻן; from 2934;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0572}/H9026/[H4969]', 'inflected', 'heb', 'אַמְתַּחַת', '["ʼamtachath"]', '["in/ sacks/ your"]', '["n-f"]', 'properly, something expansive, i.e. a bag sack.', 'from 4969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3701G}/H9026/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["silver/ your"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7364}/[H7364]', 'inflected', 'heb', 'רָחַץ', '["râchats"]', '["and/ I have washed","and/ he bathed","and/ he washed","and/ he will wash","and/ they washed","and/ they will wash","and/ you will wash"]', '["v"]', 'to lave (the whole or a part of a thing) bathe (self), wash (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7272}/H9028/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["feet/ their","foot/ their"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2543}/H9028/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["for/ donkeys/ their","to/ donkeys/ their"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3559A}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["and/ I prepared","and/ he prepared","and/ it was arranged","and/ it will be prepared","and/ they prepared","and/ they prepared [them]","and/ they will prepare"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7965I}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["for/ welfare","to/ peace","to/ welfare"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2205H}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["<the>/ old","the/ elders"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5750}/H9043/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["¿/ [is] still/ he"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2088}/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["¿/ [is] this","¿/ this","¿/ this one"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2603A}/H9031/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["he will show favor to/ you","may he show favor to/ you"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3648}/[H3648]', 'lemma', 'heb', 'כָּמַר', '["kâmar"]', '["they grew warm","they had grown warm","they have grown hot","they have grown warm"]', '["v"]', 'properly, to intertwine or contract, i.e. (by implication) to shrivel (as with heat); figuratively, to be deeply affected with passion (love or pity) be black, be kindled, yearn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7356B}/H9023/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["compassion<s>/ his"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1245}/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["and/ I sought","and/ he had sought","and/ he requested","and/ he sought","and/ he sought to find","and/ he will require","and/ it was sought","and/ they have sought","and/ they searched","and/ they sought","and/ they sought [them]","and/ they will seek","and/ you will seek","but/ you seek"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1058}/[H1058]', 'inflected', 'heb', 'בָּכָה', '["bâkâh"]', '["to/ weep"]', '["v"]', 'to weep; generally to bemoan × at all, bewail, complain, make lamentation, × more, mourn, × sore, × with tears, weep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2315}/H9011/[H2314]', 'inflected', 'heb', 'חֶדֶר', '["cheder"]', '["the/ chamber/ towards","the/ inner room/ towards","the/ room/ towards"]', '["n-m"]', 'an apartment (usually literal) ((bed) inner) chamber, innermost(-ward) part, parlour, south, × within.', 'from 2314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0662}/[H662]', 'inflected', 'heb', 'אָפַק', '["ʼâphaq"]', '["and/ I forced myself","and/ he restrained himself"]', '["v"]', 'to contain, i.e. (reflex.) abstain force (oneself), restrain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0905H}/H9038/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["to/ alone/ them"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4713}/[H4714]', 'inflected', 'heb', 'מִצְרִי', '["Mitsrîy"]', '["and/ for the/ Egyptians"]', '["a"]', 'a Mitsrite, or inhabitant of Mitsrajim Egyptian, of Egypt.', 'from 4714;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0398}/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["the/ [one who] eats","the/ [ones who] eat","the/ [ones] eating","which/ is eaten","who/ are eating","who/ eat","who/ eats","who/ were eating"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3201}/H9013/[H3201]', 'inflected', 'heb', 'יָכֹל', '["yâkôl"]', '["they are able/ !","they were able/ !"]', '["v"]', 'to be able, literally (can, could) or morally (may, might) be able, any at all (ways), attain, can (away with, (-not)), could, endure, might, overcome, have power, prevail, still, suffer.', 'or (fuller) יָכוֹל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8441}/[H8581]', 'lemma', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["<the> abomination of","[are] [the] abomination of","[is] [the] abomination of","[is] an abomination","[is] an abomination of","[the] abomination of","[the] abominations of","[the] disgusting thing of","abomination","abominations","an abomination","disgusting thing"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4713}/[H4714]', 'inflected', 'heb', 'מִצְרִי', '["Mitsrîy"]', '["to/ Egypt"]', '["a"]', 'a Mitsrite, or inhabitant of Mitsrajim Egyptian, of Egypt.', 'from 4714;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1062}/H9023/[H1060]', 'inflected', 'heb', 'בְּכוֹרָה', '["bᵉkôwrâh"]', '["according to/ birthright/ his"]', '["n-f"]', 'the firstling of man or beast; abstractly primogeniture birthright, firstborn(-ling).', 'or (short) בְּכֹרָה; feminine of 1060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6812}/H9023/[H6810]', 'inflected', 'heb', 'צְעִירָה', '["tsᵉʻîyrâh"]', '["according to/ youth/ his"]', '["n-f"]', 'smallness (of age), i.e. juvenility youth.', 'feminine of 6810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8539}/[H8539]', 'inflected', 'heb', 'תָּמַהּ', '["tâmahh"]', '["and/ they looked in astonishment"]', '["v"]', 'to be in consternation be amazed, be astonished, marvel(-lously), wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4864}/[H5375]', 'lemma', 'heb', 'מַשְׂאֵת', '["masʼêth"]', '["[the] gift of","[the] portion of","[the] raising of","[the] rising of","[the] tax of","a signal","portions","tribute"]', '["n-f"]', 'properly, (abstractly) a raising (as of the hands in prayer), or rising (of flame); figuratively, an utterance; concretely, a beacon (as raised); a present (as taken), mess, or tribute; figuratively, a reproach (as a burden) burden, collection, sign of fire, (great) flame, gift, lifting up, mess, oblation, reward.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4864}/[H5375]', 'inflected', 'heb', 'מַשְׂאֵת', '["masʼêth"]', '["more than/ [the] portions of"]', '["n-f"]', 'properly, (abstractly) a raising (as of the hands in prayer), or rising (of flame); figuratively, an utterance; concretely, a beacon (as raised); a present (as taken), mess, or tribute; figuratively, a reproach (as a burden) burden, collection, sign of fire, (great) flame, gift, lifting up, mess, oblation, reward.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3605}/H9028/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["[do] all of/ them","all of of/ them","all of/ them"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027L}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["hands"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0572}/[H4969]', 'lemma', 'heb', 'אַמְתַּחַת', '["ʼamtachath"]', '["[the] sack of","[the] sacks of"]', '["n-f"]', 'properly, something expansive, i.e. a bag sack.', 'from 4969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7760H}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ appoint","and/ he will set","and/ let us put","and/ may he appoint","and/ put","and/ put [them]","and/ set","and/ they may put","and/ you put"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1375>/H9020', 'opaque', 'heb', 'גְּבִיעַ', '["gᵉbîyaʻ"]', '["cup/ my"]', '["n-m"]', 'a goblet; by analogy, the calyx of a flower house, cup, pot.', 'from an unused root (meaning to be convex);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1375>', 'opaque', 'heb', 'גְּבִיעַ', '["gᵉbîyaʻ"]', '["[the] cup of","bowls","cups"]', '["n-m"]', 'a goblet; by analogy, the calyx of a flower house, cup, pot.', 'from an unused root (meaning to be convex);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7668}/H9023/[H7667]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["grain/ his"]', '["n-m"]', 'grain (as if broken into kernels) corn, victuals.', 'the same as 7667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1242}/[H1239]', 'inflected', 'heb', 'בֹּקֶר', '["bôqer"]', '["the/ morning","this/ morning"]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0215}/[H215]', 'lemma', 'heb', 'אוֹר', '["ʼôwr"]', '["[are] lighted up","[are] setting light to","[is] giving light to","enlightening","it gave light","it gives light","it makes shine","it shines","it was light","it will give light","it will shine","make shine","may he make shine","shine","they brightened","they light up","they lit up","they will give light","you light","you will set light to"]', '["v"]', 'to be (causative, make) luminous (literally and metaphorically) × break of day, glorious, kindle, (be, en-, give, show) light (-en, -ened), set on fire, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2543}/H9028/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["and/ donkeys/ their"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5381}/H9038/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["and/ he overtook/ them","and/ you will overtake/ them"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7999A}/[H7999]', 'lemma', 'heb', 'שָׁלַם', '["shâlam"]', '["I have paid","I will fulfill","I will pay","I will repay","[is] about to repay","certainly <make compensation>","certainly <make restitution>","fully <repay>","have you repaid","he has repaid","he is rewarded","he performs","he repays","he will be rewarded","he will make compensation","he will make restitution","he will perform","he will repay","he will restore","it rewards","it will be paid","let him repay","may he repay","may he reward","pay","repay","repaying","will he repay","you repay","you will pay"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2896C}/[H2895]', 'lemma', 'heb', 'טוֹב', '["ṭôwb"]', '["a good thing","good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5650}/H9021/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["from/ servant/ your","from/ servants/ your","of/ servants/ your"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1697H}/H9026/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["according to/ words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1419K}/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["with the/ old [brother]"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6996H}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["and/ with the/ young [brother]"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1375>', 'inflected', 'heb', 'הגביע', '["ha./ga.Vi.a''"]', '["the/ cup"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0572}/[H4969]', 'inflected', 'heb', 'אַמְתַּחַת', '["ʼamtachath"]', '["in/ [the] sack of"]', '["n-f"]', 'properly, something expansive, i.e. a bag sack.', 'from 4969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8071}/H9028/[H5566]', 'inflected', 'heb', 'שִׂמְלָה', '["simlâh"]', '["clothes/ their"]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6006}/[H6006]', 'inflected', 'heb', 'עָמַס', '["ʻâmaç"]', '["and/ he loaded"]', '["v"]', 'to load, i.e. impose a burden (or figuratively, infliction) be borne, (heavy) burden (self), lade, load, put.', 'or עָמַשׂ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5892B}/H9011/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["the/ city/ towards"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251G}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ brother/ his","and/ brothers/ his","and/ relative/ his","and/ relatives/ its"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5307J}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ he fell","and/ he will fall","and/ it fell","and/ it will fall","and/ she fell","and/ they fell","and/ they had fallen","and/ they will fall","and/ you will fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4639K}/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["<the>/ deed","[is] the/ deed","the/ activity","the/ deed","the/ deeds"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3644G}/H9030/[H3651]', 'inflected', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["[is] like/ me","as/ I","as/ me","like/ me"]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771H}/[H5753]', 'lemma', 'heb', 'עָוֺן', '["ʻâvôn"]', '["[is] iniquity","[the] guilt of","[the] iniquity of","guilt","iniquities","iniquity"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2005}/H9045/[H2005]', 'inflected', 'heb', 'הֵן', '["hên"]', '["here [are]/ we","here/ we"]', '["prt"]', 'lo!; also (as expressing surprise) if behold, if, lo, though.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9026\/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["ancestors/ your","father/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241I}/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["in/ [the] ears of"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639G}/H9021/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["[is] anger/ your","anger/ your"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5650}/H9021/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["<in>/ servant/ your","in/ servant/ your","on/ servant/ your"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6547H}/[H6547]', 'inflected', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["as/ Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6996A}/[H6962]', 'lemma', 'heb', 'קָטָן', '["qâṭân"]', '["[are] small [things] of","a small [thing]","insignificant","small","small [things]","young"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157G}/H9033/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["[those who] love/ him","he loved/ him","he loves/ him","she loved/ him"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7760A}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ [is] set","and/ [one who] sets","and/ he may make","and/ he will set","and/ it will make","and/ put","and/ put [it]","and/ set","so/ let me set","so/ they may put"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5800A}/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["[is] for/ [one who] forsakes","to/ leave"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3254G}/H9013/[H3254]', 'inflected', 'heb', 'יָסַף', '["yâçaph"]', '["you will increase/ !","you will repeat/ !"]', '["v"]', 'to add or augment (often adverbial, to continue to do a thing) add, × again, × any more, × cease, × come more, conceive again, continue, exceed, × further, × gather together, get more, give more-over, × henceforth, increase (more and more), join, × longer (bring, do, make, much, put), × (the, much, yet) more (and more), proceed (further), prolong, put, be (strong-) er, × yet, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251G}/H9025/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ brother/ our"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0854}/H9030/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["from <the>/ with/ myself","from/ with <the>/ me","from/ with/ me"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200G}/H9033/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["I have seen/ him","I saw/ him","I see/ him","I will let look/ him","I will see/ him","I will show/ him","[those who] saw/ him","has he seen/ him","he saw/ him","you will see/ it"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440G}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ my","presence/ my"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7136A}/H9033/[H7136]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["and/ it will happen to/ him"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7451I}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<in> the/ evil thing","in/ calamity","in/ evil","with/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0935G}/H9040/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ come/ I"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315H}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ life/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7194}/[H7194]', 'lemma', 'heb', 'קָשַׁר', '["qâshar"]', '["I conspired","[is] bound","[is] bound up","have you conspired","he conspired","he has conspired","it was bound","they conspired","you have conspired","you will bind","you will tie"]', '["v"]', 'to tie, physically (gird, confine, compact) or mentally (in love, league) bind (up), (make a) conspire(-acy, -ator), join together, knit, stronger, work (treason).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7200G}/H9043/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["when/ saw/ he","when/ sees/ he"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7872}/[H7869]', 'lemma', 'heb', 'שֵׂיבָה', '["sêybâh"]', '["[is] gray hair","[the] gray hair of","gray hair"]', '["n-f"]', 'old age (be) gray (grey hoar,-y) hairs (head,-ed), old age.', 'feminine of 7869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6148}/[H6148]', 'lemma', 'heb', 'עָרַב', '["ʻârab"]', '["[are] mortgaging","[is] pledging","has he pledged","he shares","he stands surety for","he stood surety for","make a wager","stand surety for","you get involved","you have stood surety","you will get involved"]', '["v"]', 'to braid, i.e. intermix; technically, to traffic (as if by barter); also or give to be security (as a kind of exchange) engage, (inter-) meddle (with), mingle (self), mortgage, occupy, give pledges, be(-come, put in) surety, undertake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0001G}/H9020/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["<to>/ father/ my","of/ father/ my","to/ father/ my"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0349A}/[H335]', 'lemma', 'heb', 'אֵיךְ', '["ʼêyk"]', '["how!","how?"]', '["adv"]', 'how? or how!; also where how, what.', 'also אֵיכָה ; and אֵיכָכָה ; prolonged from 335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7451B}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<in> the/ evil","[is] on/ evil","in/ distress","in/ trouble","on the/ calamity","on/ evil","with/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0662}/[H662]', 'inflected', 'heb', 'אָפַק', '["ʼâphaq"]', '["to/ restrain himself"]', '["v"]', 'to contain, i.e. (reflex.) abstain force (oneself), restrain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5324}/[H5324]', 'inflected', 'heb', 'נָצַב', '["nâtsab"]', '["the/ [one which] stands firm","the/ overseers","those/ [who] were standing","those/ standing","who/ stood","who/ was appointed","who/ were standing"]', '["v"]', 'to station, in various applications (literally or figuratively) appointed, deputy, erect, establish, × Huzzah (by mistake for a proper name), lay, officer, pillar, present, rear up, set (over, up), settle, sharpen, establish, (make to) stand(-ing, still, up, upright), best state.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3045}/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["when/ made himself known"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414M}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ he gave","and/ they gave forth","and/ they have given forth"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1065}/[H1058]', 'inflected', 'heb', 'בְּכִי', '["Bᵉkîy"]', '["in <the>/ weeping","in/ weeping","with <the>/ weeping","with/ [the] weeping of","with/ weeping"]', '["n-m"]', 'a weeping; by analogy, a dripping overflowing, × sore, (continual) weeping, wept.', 'from 1058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6030B}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["to/ answer","to/ testify"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0926}/[H926]', 'lemma', 'heb', 'בָּהַל', '["bâhal"]', '["I am terrified","[is] hastening","a terrible [thing]","disturbed","hastened","hastily gained","he was terrified","it is disturbed","they are disturbed","they are terrified","they were terrified","they will be terrified","we are terrified","you be hasty"]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440H}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ before/ him","of/ <before> / him","of/ <before>/ him"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6087A}/[H6087]', 'lemma', 'heb', 'עָצַב', '["ʻâtsab"]', '["he is grieved","he should be grieved","he was grieved","he will be hurt","they twist","you be grieved"]', '["v"]', 'properly, to carve, i.e. fabricate or fashion; hence (in a bad sense) to worry, pain or anger displease, grieve, hurt, make, be sorry, vex, worship, wrest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4241}/[H2421]', 'inflected', 'heb', 'מִחְיָה', '["michyâh"]', '["for/ preservation of life"]', '["n-f"]', 'preservation of life; hence, sustenance; also the live flesh, i.e. the quick preserve life, quick, recover selves, reviving, sustenance, victuals.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130G}/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["[are] in/ [the] midst of","[has been] in/ [the] midst of","[is] in/ [the] midst of","in/ [the] middle of","in/ [the] midst","in/ [the] midst of"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5750}/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["and/ again","and/ still","and/ yet"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2758}/[H2790]', 'lemma', 'heb', 'חָרִישׁ', '["chârîysh"]', '["[will be] plowing"]', '["n-m"]', 'ploughing or its season earing (time), ground.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7760H}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["by/ putting","to/ make","to/ put"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7611}/[H7604]', 'lemma', 'heb', 'שְׁאֵרִית', '["shᵉʼêrîyth"]', '["O remnant of","[the] remainder of","[the] remnant of","[the] rest of","[will be] a remnant","a remnant"]', '["n-f"]', 'a remainder or residual (surviving, final) portion that had escaped, be left, posterity, remain(-der), remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2421}/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["and/ by/ preserving alive","and/ to/ preserve alive","and/ to/ restore","and/ to/ restore to life"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760A}/H9030/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ he has appointed/ me","and/ he made/ me"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0113>', 'inflected', 'heb', 'ולאדון', '["u./le./''a.dOn"]', '["and/ to/ lord"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4910}/[H4910]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["and/ [he is] ruling","and/ [one who] rules","and/ [who] ruled","and/ ruler","and/ ruling"]', '["v"]', 'to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760A}/H9030/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["have you set/ me","he has appointed/ me","he has made/ me","it set/ me","put/ me","they made/ me","will he make/ me","you appointed/ me","you make/ me","you must appoint/ me"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0113>', 'inflected', 'heb', 'לאדון', '["la./''a.Don","la./''a.do.Nei","le./''a.Don"]', '["to/ [the] lord of","to/ [the] lord<s> of","to/ lord"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3381}/H9012/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["come down/ !","go down/ !"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1657G}/[H1657]', 'lemma', 'heb', 'גֹּשֶׁן', '["Gôshen"]', '["Goshen"]', '["n-pr-loc"]', 'Goshen, the residence of the Israelites in Egypt; also a place in Palestine Goshen.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6629G>/H9021', 'inflected', 'heb', 'וצאנך', '["ve./tzo.Ne./kha","ve./tzo.ne./Kha"]', '["and/ flock/ your","and/ sheep/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1241}/H9021/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["and/ cattle/ your","and/ herd/ your","and/ herd[s]/ your"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3557}/[H3557]', 'inflected', 'heb', 'כּוּל', '["kûwl"]', '["and/ I will provide for","and/ I will supply","and/ he provided for","and/ they supplied"]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423I}/[H3423]', 'lemma', 'heb', 'יָרַשׁ', '["yârash"]', '["I should become impoverished","[is] making poor","he will become impoverished","you should become impoverished"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004M}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ house/ your","and/ household/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310G}/H9020/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["mouth/ my","own mouth/ my"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3519}/H9020/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["O honor/ my","[is] honor/ my","[will] honor/ my","glory/ my","honor/ my"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6677A}/[H6696]', 'lemma', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["[the] neck","[the] neck of","[the] neck<s> of","[the] necks of","neck"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1058}/[H1058]', 'lemma', 'heb', 'בָּכָה', '["bâkâh"]', '["I weep","I will weep","[am] weeping","[is] weeping","[was] crying","[were] weeping","at all <weep>","bewailing","bitterly <weep>","certainly <weep>","continually <to weep>","did I weep","do you weep","he wept","it will weep","she weeps","she wept","they are weeping","they wept","they will weep","they will weep for","we wept","weep","weepers","weeping","you have wept","you must weep","you weep","you will weep"]', '["v"]', 'to weep; generally to bemoan × at all, bewail, complain, make lamentation, × more, mourn, × sore, × with tears, weep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H6963J>', 'inflected', 'heb', 'והקל', '["ve./ha./Kol"]', '["and/ the/ sound"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2943}/[H2943]', 'lemma', 'heb', 'טָעַן', '["ṭâʻan"]', '["load"]', '["v"]', 'to load a beast lade.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1165}/H9026/[H1197]', 'inflected', 'heb', 'בְּעִיר', '["bᵉʻîyr"]', '["animal[s]/ your"]', '["n-m"]', 'cattle beast, cattle.', 'from 1197 (in the sense of eating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2459>', 'opaque', 'heb', 'חֶלֶב', '["cheleb"]', '["[the] best of","[the] fat","[the] fat of","[the] fat<s> of","fat","fat of"]', '["n-m"]', 'fat, whether literally or figuratively; hence, the richest or choice part × best, fat(-ness), × finest, grease, marrow.', 'or חֵלֶב; from an unused root meaning to be fat;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5699}/[H5696]', 'lemma', 'heb', 'עֲגָלָה', '["ʻăgâlâh"]', '["a cart","carts","carts of"]', '["n-f"]', 'something revolving, i.e. a wheeled vehicle cart, chariot, wagon', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2945}/H9026/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["for/ little one[s]/ your"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0802H}/H9026/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ for/ wives/ your"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5869A}/H9026/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ eye/ your","and/ eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2347}/[H2347]', 'lemma', 'heb', 'חוּס', '["chûwç"]', '["I will have compassion","I will have mercy","he will have compassion","he will have mercy","it look with regret","it looked with compassion","it will look with compassion","it will look with pity","let it look with compassion","will I have compassion?","you had compassion"]', '["v"]', 'properly, to cover, i.e. (figuratively) to compassionate pity, regard, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3627}/H9026/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["things/ your"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310I}/[H6284]', 'lemma', 'heb', 'פֶּה', '["peh"]', '["[the] mouth of","mouth"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0376I>', 'inflected', 'heb', 'לאיש', '["la./''Ish","le./''Ish"]', '["<to>/ anyone","<to>/ each","[belonged] to/ each","for/ anyone","to <the>/ each","to <the>/ everyone","to/ anyone","to/ each","to/ everyone","to/ everyone of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2487}/[H2498]', 'lemma', 'heb', 'חֲלִיפָה', '["chălîyphâh"]', '["changes","changes of","relays"]', '["n-f"]', 'alternation change, course.', 'from 2498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8071}/[H5566]', 'lemma', 'heb', 'שִׂמְלָה', '["simlâh"]', '["[is] a cloak","[the] clothing of","a cloak","clothes"]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1144G}/[H1121]', 'inflected', 'heb', 'בִּנְיָמִין', '["Binyâmîyn"]', '["and/ to/ Benjamin"]', '["n-pr-m"]', 'Binjamin, youngest son of Jacob; also the tribe descended from him, and its territory Benjamin.', 'from 1121 and 3225; son of (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0001G}/H9023/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ for/ father/ his","and/ to/ father/ his"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2063}/[H2088]', 'inflected', 'heb', 'זֹאת', '["zôʼth"]', '["according to/ this","like/ this"]', '["d"]', 'this (often used adverb) hereby (-in, -with), it, likewise, the one (other, same), she, so (much), such (deed), that, therefore, these, this (thing), thus.', 'irregular feminine of 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2543}/[H2560]', 'lemma', 'heb', 'חֲמוֹר', '["chămôwr"]', '["[is] a donkey of","[the] donkey of","a donkey","donkeys"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2898}/[H2895]', 'inflected', 'heb', 'טוּב', '["ṭûwb"]', '["from/ goodness of","some of/ [the] good thing[s] of"]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6235}/[H6237]', 'inflected', 'heb', 'עֶשֶׂר', '["ʻeser"]', '["and/ [the] ten","and/ [was] ten","and/ ten"]', '["n"]', 'ten (as an accumulation to the extent of the digits) ten, (fif-, seven-) teen.', 'masculine of term עֲשָׂרָה; from 6237;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3899H}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["and/ [the] bread of","and/ [will be] food","and/ bread","and/ bread of","and/ food","and/ food of"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4202}/[H2109]', 'inflected', 'heb', 'מָזוֹן', '["mâzôwn"]', '["and/ food"]', '["n-m"]', 'food meat, victual.', 'from 2109;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7264}/[H7264]', 'lemma', 'heb', 'רָגַז', '["râgaz"]', '["I trembled","I will make tremble","[who] made tremble","be agitated","he has made tremble","he will rage","it is excited","it quakes","it trembled","it will be agitated","let them tremble","they trembled","they will quake","tremble","will it tremble","you stir up","you will be agitated"]', '["v"]', 'to quiver (with any violent emotion, especially anger or fear) be afraid, stand in awe, disquiet, fall out, fret, move, provoke, quake, rage, shake, tremble, trouble, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6313}/[H6313]', 'inflected', 'heb', 'פּוּג', '["pûwg"]', '["and/ it grew numb"]', '["v"]', 'to be sluggish cease, be feeble, faint, be slacked.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0539}/[H541]', 'lemma', 'heb', 'אָמַן', '["ʼâman"]', '["I believe","I believed","I had believed","I trust","Trustworthy","[are] reliable","[is] faithful","[is] reliable","[something] trustworthy","[was being] established","[were] trusting","[will be] reliable","anyone trusts","enduring","faithful","firm","has he believed","he believed","he believes","he trust","he trusted","he trusts","it stands firm","it was faithful","let it be established","raising","reliable","sure","they are reliable","they believed","they may believe","they trusted","they were faithful","they will be carried","they will believe","they will trust","trust","will they believe","you believe","you believed","you trust","you will believe","you will trust"]', '["v"]', 'properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right.', 'a primitive root; (Isaiah 30:21; interchangeable with 541, to go to the right hand)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5699}/[H5696]', 'inflected', 'heb', 'עֲגָלָה', '["ʻăgâlâh"]', '["<the>/ cart","the/ cart","the/ carts"]', '["n-f"]', 'something revolving, i.e. a wheeled vehicle cart, chariot, wagon', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5375H}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["[is] to/ carry","to/ bear","to/ carry","to/ carry [them]","to/ carry away","to/ endure"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7200G}/H9033/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ I will let look/ him","and/ we will look at/ him","so/ I may see/ him"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0884}+/H9011/[H875]', 'inflected', 'heb', 'בְּאֵר שֶׁבַע', '["Bᵉʼêr Shebaʻ"]', '["Beer/ towards"]', '["n-pr-loc"]', 'Beer-Sheba, a place in Palestine Beer-shebah.', 'from 875 and 7651 (in the sense of 7650); well of an oath;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3478}/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["<to>/ Israel","[belong] to/ Israel","[belonged] to/ Israel","[belongs] to/ Israel","for/ Israel","of/ Israel","to/ Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4759A}/[H4758]', 'inflected', 'heb', 'מַרְאָה', '["marʼâh"]', '["by <the>/ vision","in/ [the] visions of","in/ visions of","on the/ vision"]', '["n-f"]', 'a vision; also (causatively) a mirror looking glass, vision.', 'feminine of 4758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3381}/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["from/ going down"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760A}/H9031/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["I will make/ you","did he appoint/ you","he has made/ you","may he make/ you","they have set/ you","will I make?/ you"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927H}/H9031/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["I brought up/ you","I will bring up/ you","he brought up/ you","they brought up/ you"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927H}/[H5927]', 'lemma', 'heb', 'עָלָה', '["ʻâlâh"]', '["I brought up","I will bring up","I will lift up","[is] about to bring up","[the] taking up of","[was] bringing up","[were] bringing up","[will] bring up","bring up","completely <to go up>","did I bring up","has it come up","he brings up","he brought up","he had brought up","he is exalted","he lifted up","he raised","he will bring up","it brought up","it raises","it was recorded","it was taken up","take up","they brought up","they had brought up","they have brought up","they have caused to rise","they have come up","they will bring up","were led up","will I bring up","you are exalted","you brought up","you have brought up","you have offered up","you will take up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027H}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ his","monument/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5699}/[H5696]', 'inflected', 'heb', 'עֲגָלָה', '["ʻăgâlâh"]', '["<in> the/ cart","in the/ carts","on the/ cart"]', '["n-f"]', 'something revolving, i.e. a wheeled vehicle cart, chariot, wagon', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2233H}/H9023/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["offspring/ his","offspring/ its"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4714G}/H9011\/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["Egypt/ towards"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2585J}/[H2596]', 'lemma', 'heb', 'חֲנוֹךְ', '["Chănôwk"]', '["Hanoch","[were] Hanoch"]', '["n-pr-m n-pr-loc"]', 'Chanok, an antediluvian patriach Enoch.', 'from 2596; initiated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6396}/[H6395]', 'inflected', 'heb', 'פַּלּוּא', '["Pallûwʼ"]', '["and/ Pallu"]', '["n-pr-m"]', 'Pallu, an Israelite Pallu, Phallu.', 'from 6395; distinguished;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2696G}/[H2691]', 'inflected', 'heb', 'חֶצְרוֹן', '["Chetsrôwn"]', '["and/ Hezron"]', '["n-pr-m n-pr-loc"]', 'Chetsron, the name of a place in Palestine; also of two Israelites Hezron.', 'from 2691; court-yard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3756G}/[H3754]', 'inflected', 'heb', 'כַּרְמִי', '["Karmîy"]', '["and/ Carmi"]', '["n-pr-m"]', 'Karmi, the name of three Israelites Carmi.', 'from 3754; gardener;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3223}/[H3117]', 'lemma', 'heb', 'יְמוּאֵל', '["Yᵉmûwʼêl"]', '["Jemuel","[were] Jemuel"]', '["n-pr-m"]', 'Jemuel, an Israelite Jemuel.', 'from 3117 and 410; day of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3226G}/[H3225]', 'inflected', 'heb', 'יָמִין', '["Yâmîyn"]', '["and/ Jamin"]', '["n-pr-m"]', 'Jamin, the name of three Israelites Jamin. See also 1144.', 'the same as 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0161>', 'inflected', 'heb', 'ואהד', '["ve./''O.had"]', '["and/ Ohad"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3199G}/[H3559]', 'inflected', 'heb', 'יָכִין', '["Yâkîyn"]', '["and/ Jakin"]', '["n-pr"]', 'Jakin, the name of three Israelites and of a temple pillar Jachin.', 'from 3559; he (or it) will establish;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6714H}/[H6713]', 'inflected', 'heb', 'צֹחַר', '["Tsôchar"]', '["and/ Zohar"]', '["n-pr-m"]', 'Tsochar, the name of a Hittite and of an Israelite Zohar. Compare 3328.', 'from the same as 6713; whiteness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7586H}/[H7592]', 'inflected', 'heb', 'שָׁאוּל', '["Shâʼûwl"]', '["and/ Shaul"]', '["n-pr-m"]', 'Shaul, the name of an Edomite and two Israelites Saul, Shaul.', 'passive participle of 7592; asked;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3669G}/[H3667]', 'inflected', 'heb', 'כְּנַעַנִי', '["Kᵉnaʻanîy"]', '["<the>/ Canaanite [woman]","the/ Canaanite [woman]"]', '["n-m"]', 'a Kenaanite or inhabitant of Kenaan; by implication, a pedlar (the Canaanites standing for their neighbors the Ishmaelites, who conducted mercantile caravans) Canaanite, merchant, trafficker.', 'patrial from 3667;');
