INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7657}\/[H7651]', 'inflected', 'heb', 'שִׁבְעִים', '["shibʻîym"]', '["[was] seventy"]', '["n"]', 'seventy seventy, threescore and ten ( -teen).', 'multiple of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3384B}/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["to/ show","to/ teach"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1657G}/H9011/[H1657]', 'inflected', 'heb', 'גֹּשֶׁן', '["Gôshen"]', '["Goshen/ towards"]', '["n-pr-loc"]', 'Goshen, the residence of the Israelites in Egypt; also a place in Palestine Goshen.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4818}/H9023/[H4817]', 'inflected', 'heb', 'מֶרְכָּבָה', '["merkâbâh"]', '["chariot/ his","chariots/ his","chariots/ its"]', '["n-f"]', 'a chariot chariot. See also 1024.', 'feminine of 4817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122G}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200G}/H9040/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["have seen/ I"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5750}/H9041/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["[are] still?/ you","still/ you"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5046}/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["and/ I will tell","and/ [one who] tells","and/ a messenger","and/ declare","and/ did I declare","and/ let us tell","and/ may he tell","and/ tell","and/ they may declare","and/ they may tell","so/ he may declare","so/ it may tell","so/ let me tell","so/ may he tell","so/ they may tell","so/ you may tell"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0559}/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["and/ I will say","and/ [one who] says","and/ [you were] saying","and/ he may say","and/ he says","and/ let people say","and/ may they say","and/ say","and/ saying","and/ she says","and/ they may say","and/ you say","so/ I may say","so/ he may say","so/ may someone say?","so/ they may say","so/ we may say"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004M}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ O house of","and/ [the] house of","and/ [the] household of","and/ a house"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6629G>/H9028', 'inflected', 'heb', 'וצאנם', '["ve./tzo.Na/m"]', '["and/ flock[s]/ their","and/ sheep/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1241}/H9028/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["and/ cattle/ their","and/ herd[s]/ their"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639G}/H9026/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["[are] work<s>/ your","products/ your","work<s>/ your"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5271A}/H9025/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["since/ youth<s>/ our"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251G}/H9020/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ brothers/ my"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7097A}/[H7096]', 'inflected', 'heb', 'קָצֶה', '["qâtseh"]', '["and/ from/ [the] end of"]', '["n-m"]', 'an extremity × after, border, brim, brink, edge, end, (in-) finite, frontier, outmost coast, quarter, shore, (out-) side, × some, ut(-ter-) most (part).', 'or (negative only) קֵצֶה; from 7096; (used in a great variety of applications and idioms; compare 7093)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3322}/H9038/[H3322]', 'inflected', 'heb', 'יָצַג', '["yâtsag"]', '["and/ he presented/ them"]', '["v"]', 'to place permanently establish, leave, make, present, put, set, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4829}/[H7462]', 'lemma', 'heb', 'מִרְעֶה', '["mirʻeh"]', '["[is] pasture","a pasture of","pasture"]', '["n-m"]', 'pasture (the place or the act); also the haunt of wild animals feeding place, pasture.', 'from 7462 in the sense of feeding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6629G>', 'inflected', 'heb', 'לצאן', '["la./tzoN"]', '["for the/ sheep"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4315}/[H3190]', 'inflected', 'heb', 'מֵיטָב', '["mêyṭâb"]', '["in/ [the] best of"]', '["n-m"]', 'the best part best.', 'from 3190;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3426>', 'inflected', 'heb', 'ויש', '["va./Yesh","ve./Yesh","ve./yesh"]', '["and/ [is] there?","and/ there","and/ there is"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428G}/[H2342]', 'lemma', 'heb', 'חַיִל', '["chayil"]', '["<the> ability of","ability","of strength","strength","wealth"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5975G}/H9033/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ he made stand/ him","and/ he will station/ him"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4100}/[H4100]', 'inflected', 'heb', 'מָה', '["mâh"]', '["how/ long?","how/ many?","how/ much?","how/ often!","how/ often?"]', '["i"]', 'properly, interrogative what? (including how? why? when?); but also exclamation, what! (including how!), or indefinitely what (including whatever, and even relatively, that which); often used with prefixes in various adverbial or conjunctive senses how (long, oft, (-soever)), (no-) thing, what (end, good, purpose, thing), whereby(-fore, -in, -to, -with), (for) why.', 'or מַה; or מָ; or מַ; also מֶה; a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4033}/H9020/[H1481]', 'inflected', 'heb', 'מָגוּר', '["mâgûwr"]', '["sojournings/ my"]', '["n-m"]', 'a temporary abode; by extension, a permanent residence dwelling, pilgrimage, where sojourn, be a stranger. Compare 4032.', 'or מָגֻר; from 1481 in the sense of lodging;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416E}/H9020/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["life/ my"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5381}/[H5381]', 'lemma', 'heb', 'נָשַׂג', '["nâsag"]', '["I will overtake","[is] reaching","[was one who] reached","certainly <to overtake>","did they overtake","it has reached","it will overtake","it will reach","people reach","she will overtake","they have reached","they reach","they will overtake [them]","you will overtake [it]"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7486G}/[H7486]', 'lemma', 'heb', 'רַעְמְסֵס', '["Raʻmᵉçêç"]', '["Rameses"]', '["n-pr-loc"]', 'Rameses or Raamses, a place in Egypt Raamses, Rameses.', 'or רַעַמְסֵס; of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6310K}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["to/ [the] mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2945}/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["the/ little one[s]"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3899G}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["and/ [was] food","and/ food"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3856A}/[H3856]', 'inflected', 'heb', 'לָהַהּ', '["lâhahh"]', '["and/ it languished"]', '["v"]', 'to be rabid (figuratively, insane); also (from the exhaustion of frenzy) to languish faint, mad.', 'a primitive root meaning properly, to burn, i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3950}/[H3950]', 'inflected', 'heb', 'לָקַט', '["lâqaṭ"]', '["and/ he gathered","and/ he gathered up","and/ he picked up","and/ she gleaned","and/ she will glean","and/ they gathered","and/ they gathered [it]","and/ they joined themselves","and/ they will gather"]', '["v"]', 'properly, to pick up, i.e. (generally) to gather; specifically, to glean gather (up), glean.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H0776G>', 'inflected', 'heb', 'ובארץ', '["u./va./''A.retz","u./ve./''E.retz"]', '["and/ in/ [the] land","and/ in/ [the] land of","and/ in/ a land of","and/ on the/ earth"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7668}/[H7667]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["for the/ grain"]', '["n-m"]', 'grain (as if broken into kernels) corn, victuals.', 'the same as 7667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004P}/H9011/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[the] house of/ towards"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8552}/[H8552]', 'inflected', 'heb', 'תָּמַם', '["tâmam"]', '["and/ I will make an end of","and/ it was complete","and/ it was finished","and/ it will be consumed","and/ they were completed","and/ they will meet their end"]', '["v"]', 'to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5048}/H9031/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["[are] before/ you","[is] before/ you","before/ you"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0656}/[H656]', 'lemma', 'heb', 'אָפֵס', '["ʼâphêç"]', '["he will come to an end","it has come to an end"]', '["v"]', 'to disappear, i.e. cease be clean gone (at an end, brought to nought), fail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3051}/[H3051]', 'lemma', 'heb', 'יָהַב', '["yâhab"]', '["ascribe","give","provide","set"]', '["v"]', 'to give (whether literal or figurative); generally, to put; imperatively (reflexive) come ascribe, bring, come on, give, go, set, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4735}/H9026/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["livestock/ your"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4735}/H9026/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["for/ livestock/ your"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5483M>', 'inflected', 'heb', 'בסוסים', '["ba./su.Sim","be./Sus","be./su.Sim","va./su.Sim"]', '["<in> <the>/ horses","by/ horses","for the/ horses","on <the>/ horses","on the/ horses","with/ horse[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4735}/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["and/ for/ [the] livestock of","and/ with/ livestock"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2543}/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["and/ for the/ donkeys","and/ with/ a donkey"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5095}/H9038/[H5095]', 'inflected', 'heb', 'נָהַל', '["nâhal"]', '["and/ he led/ them","and/ he refreshed/ them","and/ they led/ them"]', '["v"]', 'properly, to run with a sparkle, i.e. flow; hence (transitively), to conduct, and (by inference) to protect, sustain carry, feed, guide, lead (gently, on).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3899G}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["<in> the/ food","for <the>/ food","with <the>/ food"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3582}/[H3582]', 'lemma', 'heb', 'כָּחַד', '["kâchad"]', '["I have hidden","I will hide","destroyed","he has been destroyed","he hid [them]","it is hidden","it was hidden","let it be destroyed","they are hidden","they have hidden","they have hidden [it]","we will hide","were they destroyed","you hide","you hide [it]","you will hide"]', '["v"]', 'to secrete, by act or word; hence (intensively) to destroy conceal, cut down (off), desolate, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0113>/H9020', 'inflected', 'heb', 'מאדני', '["me./''a.do.N/i"]', '["from/ lord/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8552}/[H8552]', 'lemma', 'heb', 'תָּמַם', '["tâmam"]', '["I will be blameless","are finished","complete","is finished","it had finished","it has been finished","it may be consumed","it will be finished","it will finish","let them be destroyed","they are finished","they ceased","they had finished","they have come to an end","they were complete","they will be finished","they will come to an end","they will meet their end","was consumed","was finished","we have finished","we have met our end","will we complete","you make blameless","you show yourself blameless"]', '["v"]', 'to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1472}/H9025/[H1465]', 'inflected', 'heb', 'גְּוִיָּה', '["gᵉvîyâh"]', '["bodies/ our","body/ our"]', '["n-f"]', 'a body, whether alive or dead (dead) body, carcase, corpse.', 'prolonged for 1465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0127G}/H9025/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["and/ land/ our"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869J}/H9021/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0127G}/H9025/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["ground/ our","land/ our"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0127G}/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["and/ the/ ground","and/ the/ land"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3456}/[H3456]', 'lemma', 'heb', 'יָשַׁם', '["yâsham"]', '["it may be desolate","it will be desolate","they will be desolate"]', '["v"]', 'to lie waste be desolate.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674C}/[H5674]', 'lemma', 'heb', 'עָבַר', '["ʻâbar"]', '["I have taken away","a passer by","at all <brought over>","have you brought over","he brought in","he had taken away","he has taken away","take away","they brought over"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7097A}/H9023/[H7096]', 'inflected', 'heb', 'קָצֶה', '["qâtseh"]', '["end/ its","outskirt[s]/ its"]', '["n-m"]', 'an extremity × after, border, brim, brink, edge, end, (in-) finite, frontier, outmost coast, quarter, shore, (out-) side, × some, ut(-ter-) most (part).', 'or (negative only) קֵצֶה; from 7096; (used in a great variety of applications and idioms; compare 7093)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3548}/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["O/ priests","[are] the/ priests","the/ priest","the/ priests"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706H}/[H2710]', 'lemma', 'heb', 'חֹק', '["chôq"]', '["a limit","a prescribed portion of","an allowance"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3548}/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["<into>/ a priest","<to> the/ priests","[belonged] to the/ priests","[belongs] to the/ priest","[is] for the/ priests","[was] for the/ priests","for the/ priest","for the/ priests","of the/ priests","to <the>/ priests","to the/ priest","to the/ priests","to/ a priest","to/ priest"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706H}/H9028/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["allowance/ their"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0127G}/H9028/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["ground/ their","land/ their","own land/ their"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0853}/H9036/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["<obj.>/ you"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0127G}/H9026/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["ground/ your","land/ your","own land/ your"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1887}/[H1887]', 'lemma', 'heb', 'הֵא', '["hêʼ"]', '["here!","there!"]', '["inj"]', 'lo! behold, lo.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8393}/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["at the/ harvest<s>"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3027L}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["the/ hands"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2233G}/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["to/ [the] seed of"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0400}/H9026/[H398]', 'inflected', 'heb', 'אֹכֶל', '["ʼôkel"]', '["and/ to/ food/ your"]', '["n-m"]', 'food eating, food, meal(-time), meat, prey, victuals.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0834A}/[H834]', 'inflected', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["and/ for/ [those] who","and/ to/ [one] who","and/ to/ [those] who"]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004M}/H9026/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[are] in/ households/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0398}/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ to/ eat"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2421}/H9035/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["he will restore to life/ us","they will let live/ us","will you give life?/ us","you have preserved alive/ us","you will give life/ us"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2706G}/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["and/ statutes","into/ a decree","into/ a statute","to/ a decree","to/ a statute"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2569}/[H2567]', 'inflected', 'heb', 'חֹמֶשׁ', '["chômesh"]', '["to the/ fifth part"]', '["n-m"]', 'a fifth tax fifth participle', 'from 2567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0270}/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["and/ I took hold","and/ he covered","and/ he took hold","and/ it takes hold of","and/ it took hold","and/ she took hold","and/ they had possessions","and/ they seized","and/ they will have possessions"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416E}/H9023/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["life/ his"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7126G}/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["and/ I drew near","and/ I will draw near","and/ he brought near","and/ he drew near","and/ he will be brought near","and/ he will bring [him] near","and/ he will bring near","and/ it drew near","and/ she drew near","and/ she will draw near","and/ they brought near","and/ they drew near","and/ they will draw near","and/ you will draw near"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6912}/H9030/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["you bury/ me","you will bury/ me"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7901G}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ I will lie down","and/ he had lain down","and/ he lay","and/ he lay down","and/ he lay with","and/ he will lie","and/ she lay down","and/ she will lie","and/ they lay down","and/ you will lie down"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375H}/H9030/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ you will carry/ me"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6912}/H9030/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["and/ you will bury/ me"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6900}/H9028/[H6912]', 'inflected', 'heb', 'קְבוּרָה', '["qᵉbûwrâh"]', '["in/ grave/ their"]', '["n-f"]', 'sepulture; (concretely) a sepulchre burial, burying place, grave, sepulchre.', 'or קְבֻרָה; feminine passive participle of 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1697G}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["according to/ word/ your","according to/ words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4296}\/[H5186]', 'inflected', 'heb', 'מִטָּה', '["miṭṭâh"]', '["the/ bed"]', '["n-f"]', 'a bed (as extended) for sleeping or eating; by analogy, a sofa, litter or bier bed(-chamber), bier.', 'from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2470H}/[H2342]', 'lemma', 'heb', 'חָלָה', '["châlâh"]', '["I am sick","I have been wounded","I was sick","I will make sick","[am] weak of","[are] sick","[is] making sick","[is] sick","[was] being ill","[was] sick","he became sick","he had been sick","he has made sick","he was sick","they became sick"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4296}/[H5186]', 'inflected', 'heb', 'מִטָּה', '["miṭṭâh"]', '["the/ bed","the/ beds","the/ bier","the/ couch"]', '["n-f"]', 'a bed (as extended) for sleeping or eating; by analogy, a sofa, litter or bier bed(-chamber), bier.', 'from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3870H}/[H3869]', 'inflected', 'heb', 'לוּז', '["Lûwz"]', '["at/ Luz"]', '["n-pr-loc"]', 'Luz, the name of two places in Palestine Luz.', 'probably from 3869 (as growing there);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6509}/H9031/[H6509]', 'inflected', 'heb', 'פָּרָה', '["pârâh"]', '["[am] about to make fruitful/ you"]', '["v"]', 'to bear fruit (literally or figuratively) bear, bring forth (fruit), (be, cause to be, make) fruitful, grow, increase.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7235A}/H9031/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["and/ I will multiply/ you","and/ he will increase/ you","and/ he will make great/ you"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9040/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["came/ I","come/ I"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4519G}/[H5382]', 'inflected', 'heb', 'מְנַשֶּׁה', '["Mᵉnashsheh"]', '["and/ Manasseh"]', '["n-pr-m"]', 'Menashsheh, a grandson of Jacob, also the tribe descended from him, and its territory Manasseh.', 'from 5382; causing to forget;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7205}/[H7200]', 'inflected', 'heb', 'רְאוּבֵן', '["Rᵉʼûwbên"]', '["like/ Reuben"]', '["n-pr-m"]', 'Reuben, a son of Jacob Reuben.', 'from the imperative of 7200 and 1121; see ye a son;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4138}/H9021/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["and/ offspring/ your"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251G}/H9028/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["brother/ their","brothers/ their","relatives/ their"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5159}/H9028/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["<in>/ inheritance/ their","in/ inheritance/ their"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0935G}/H9040/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ came/ I"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6912}/H9034/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["and/ I buried/ her"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947J}/H9038/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["fetch/ them"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1288}/H9038/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["so/ I may bless/ them"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3513J}/[H3513]', 'lemma', 'heb', 'כָּבַד', '["kâbad"]', '["it is [too] heavy","they made heavy","they were heavy"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2207}/[H2204]', 'inflected', 'heb', 'זֹקֶן', '["zôqen"]', '["from/ old age"]', '["n-m"]', 'old age age.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6419}/[H6419]', 'lemma', 'heb', 'פָּלַל', '["pâlal"]', '["I judged","I pray","I prayed","[am] about to pray","[am] praying","[is] praying","he had prayed","he will pray","let him pray","pray","they will pray","will he intercede","you have mediated","you have prayed","you pray","you prayed"]', '["v"]', 'to judge (officially or mentally); by extension, to intercede, pray intreat, judge(-ment), (make) pray(-er, -ing), make supplication.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1290}/H9023/[H1288]', 'inflected', 'heb', 'בֶּרֶךְ', '["berek"]', '["knees/ his"]', '["n-f"]', 'a knee knee.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0639I}/H9023/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["to/ face/ his"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3225G}/H9023/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["at/ right [hand]/ his","by/ right [hand]/ his","in/ right [hand]/ his","on/ right [hand]/ his"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8040G}/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["from/ [the] left","from/ [the] left of"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8040G}/H9023/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["at/ left [hand]/ his","in/ left [hand]/ his"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3225G}/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["from/ [the] right [side]","from/ [the] right [side] of","from/ [the] right of"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3225G}/H9023/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["right [hand]/ his","right [side]/ his","right/ his"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7896H}/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["and/ he put [it]","and/ you have put"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8040G}/H9023/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["left [hand]/ his","left/ his"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7919B}/[H7919]', 'lemma', 'heb', 'שָׂכַל', '["sâkal"]', '["he laid cross-wise"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7462B}/[H7462]', 'inflected', 'heb', 'רָעָה', '["râʻâh"]', '["<the>/ shepherds","O/ shepherds","the/ shepherd","the/ shepherds","which/ graze","which/ grazed","who/ [is] grazing","who/ are shepherding","who/ shepherded"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5750}/H9020/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["from/ duration/ my"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1350A}/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["the/ kinsman-redeemer","who/ has redeemed","who/ redeems"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7121H}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ called [ones]","and/ may it be called","and/ may it be proclaimed","and/ proclaim"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8034}/H9020/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["<of> name/ my","[is] name/ my","name/ my"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1711}/[H1709]', 'inflected', 'heb', 'דָּגָה', '["dâgâh"]', '["and/ may they multiply"]', '["v"]', 'to spawn, i.e. become numerous grow.', 'a primitive root; to move rapidly; used only as a denominative from 1709;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8551}/[H8551]', 'inflected', 'heb', 'תָּמַךְ', '["tâmak"]', '["and/ he grasped"]', '["v"]', 'to sustain; by implication, to obtain, keep fast; figuratively, to help, follow close (take, up-) hold (up), maintain, retain, stay (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5493G}/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["to/ remove","to/ remove [it]","to/ turn aside"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3225G}/H9021/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["right [hand]/ your","right/ your"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218A>/H9023', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ his","head/ its","heads/ its","own head/ his","top/ its"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2233H}/H9023/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ offspring/ his","and/ offspring/ its"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4393}/[H4390]', 'lemma', 'heb', 'מְלֹא', '["mᵉlôʼ"]', '["<the> fullness of","[the] fullness of","[was] [the] fullness of","a multitude of","fullness of"]', '["n-m"]', 'fulness (literally or figuratively) × all along, × all that is (there-) in, fill, (× that whereof...was) full, fulness, (hand-) full, multitude.', 'rarely מְלוֹא; or מְלוֹ; (Ezekiel 41:8), from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1288}/H9038/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["and/ he blessed/ them"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0669G}/[H672]', 'inflected', 'heb', 'אֶפְרַיִם', '["ʼEphrayim"]', '["like/ Ephraim"]', '["n-pr-m"]', 'Ephrajim, a son of Joseph; also the tribe descended from him, and its territory Ephraim, Ephraimites.', 'dual of masculine form of 672; double fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4519G}/[H5382]', 'inflected', 'heb', 'מְנַשֶּׁה', '["Mᵉnashsheh"]', '["and/ like/ Manasseh"]', '["n-pr-m"]', 'Menashsheh, a grandson of Jacob, also the tribe descended from him, and its territory Manasseh.', 'from 5382; causing to forget;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2719}/H9020/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["by/ sword/ my"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7198}/H9020\/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["and/ by/ bow/ my"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7122I}/[H7122]', 'lemma', 'heb', 'קָרָא', '["qârâʼ"]', '["[surely] by chance","he was met","it has happened to","it will be met","it will happen to","they will happen"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0319}/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["at/ [the] end of"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6908}/[H6908]', 'lemma', 'heb', 'קָבַץ', '["qâbats"]', '["I will assemble","I will gather","I will gather together","[am] about to gather","[one who] gathers together","[were] assembled","[who] gathers","[will be one who] gathers","assemble","gather","gather together","gathered together","he gathered","he will assemble","he will gather","it gathered [them]","it gathers","let them gather together","surely <assemble>","they gathered","they had gathered together","they have assembled","they have gathered together","they will be gathered","they will gather","you will assemble","you will be gathered","you will gather"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8085G}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ [one who] hears","and/ [one who] heeds","and/ [one who] listens","and/ [who] hear","and/ he may hear","and/ he may listen?","and/ hear","and/ it may hear","and/ listen","and/ make heard","and/ they may hear","and/ they may listen","so/ he may listen","so/ let me hear","so/ let us hear","so/ let us listen","so/ they may hear","so/ you may hear"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1060}/H9020/[H1069]', 'inflected', 'heb', 'בְּכוֹר', '["bᵉkôwr"]', '["[are] firstborn/ my","[is] firstborn/ my","firstborn/ my"]', '["n-m"]', 'first-born; hence, chief eldest (son), firstborn(-ling).', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7225G}/[H7218]', 'inflected', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["and/ [the] beginning of","and/ [the] best of","and/ [the] first of"]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0202}/H9020/[H205]', 'inflected', 'heb', 'אוֹן', '["ʼôwn"]', '["manly vigor/ my"]', '["n-m"]', 'ability, power, (figuratively) wealth force, goods, might, strength, substance.', 'probably from the same as 205 (in the sense of effort, but successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3499A}/[H3498]', 'lemma', 'heb', 'יֶתֶר', '["yether"]', '["[the] remainder of","[the] rest of","abundance","excellence","excellence of","excess"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3499A}/[H3498]', 'inflected', 'heb', 'יֶתֶר', '["yether"]', '["and/ [the] remainder of","and/ [the] rest of","and/ [the] rest ofK:","and/ excellence of","and/ the rest of"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5794}/[H5810]', 'lemma', 'heb', 'עַז', '["ʻaz"]', '["[are] mighty of","[is] strong","[the] strong","[was] strong","fierce","fierce [people]","fierce of","mighty","mighty [ones]","power","strength","strong","strong [words]"]', '["a"]', 'strong, vehement, harsh fierce, greedy, mighty, power, roughly, strong.', 'from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6349}/[H6348]', 'lemma', 'heb', 'פַּחַז', '["pachaz"]', '["destructiveness"]', '["n-m"]', 'ebullition, i.e. froth (figuratively, lust) unstable.', 'from 6348;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4325G}/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["like <the>/ water","like <the>/ waters","like the/ waters","like/ water","like/ waters"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3498}/[H3498]', 'lemma', 'heb', 'יָתַר', '["yâthar"]', '["I am left","I remained behind","I will leave behind","he had left","he has been left","he is left","he was left","him leave over","it had left over","it was left","it was left behind","it will be left","it will be left behind","it will be left over","it will remain","leave over","she had left over","they remained","they were left","they will remain","to leave","we will leave","you excel","you have been left","you will leave","you will leave over"]', '["v"]', 'to jut over or exceed; by implication, to excel; (intransitively) to remain or be left; causatively to leave, cause to abound, preserve excel, leave (a remnant), left behind, too much, make plenteous, preserve, (be, let) remain(-der, -ing, -nant), reserve, residue, rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4904}/[H7901]', 'lemma', 'heb', 'מִשְׁכָּב', '["mishkâb"]', '["[the] bed<s> of","[the] lying of","[the] lyings of","a bed","bed[s]","lying of"]', '["n-m"]', 'a bed (figuratively, a bier); abstractly, sleep; by euphemism, carnal intercourse bed(-chamber), couch, lieth (lying) with.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2490H}/[H2470]', 'lemma', 'heb', 'חָלַל', '["châlal"]', '["I profaned","I will let be profaned","I will violate","[am] about to profane","[are] profaning","[is] profaning","he has profaned","he violated","he will profane","he will violate","it has profaned","it was profaned","she will profane herself","they had profaned","they have profaned","they profane","they profaned","they will profane","they will violate","to be profaned","to profane","will it be profaned","you have profaned","you profane","you profaned","you profaned [it]","you will profane"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3326A}/H9020/[H3331]', 'inflected', 'heb', 'יָצוּעַ', '["yâtsûwaʻ"]', '["beds/ my","couch/ my"]', '["n-m"]', 'spread, i.e. a bed; (architecture) an extension, i.e. wing or lean-to (a single story or collectively) bed, chamber, couch.', 'passive participle of 3331;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927G}\/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["he went up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4380}/H9028/[H3564]', 'inflected', 'heb', 'מְכֵרָה', '["mᵉkêrâh"]', '["swords/ their"]', '["n-f"]', 'a sword habitation.', 'probably from the same as 3564 in the sense of stabbing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5475}/H9028/[H3245]', 'inflected', 'heb', 'סוֹד', '["çôwd"]', '["in/ council/ their"]', '["n-m"]', 'a session, i.e. company of persons (in close deliberation); by implication, intimacy, consultation, a secret assembly, consel, inward, secret (counsel).', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315G}/H9020/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["O self/ my","O soul/ my","being/ my","desire/ my","life/ my","self/ my","soul/ my","throat/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6951}/H9028/[H6950]', 'inflected', 'heb', 'קָהָל', '["qâhâl"]', '["in/ assembly/ their"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3161}/[H3161]', 'lemma', 'heb', 'יָחַד', '["yâchad"]', '["it be united","unite","you will be united"]', '["v"]', 'to be (or become) one join, unite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0639G}/H9028/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["in/ anger/ their"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7522}/H9028/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["and/ for/ pleasure/ their"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6131B}/[H6131]', 'lemma', 'heb', 'עָקַר', '["ʻâqar"]', '["he hamstrung","they hamstrung","you will hamstring"]', '["v"]', 'to pluck up (especially by the roots); specifically, to hamstring; figuratively, to exterminate dig down, hough, pluck up, root up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639G}/H9028/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["anger/ their"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5678}/H9028/[H5676]', 'inflected', 'heb', 'עֶבְרָה', '["ʻebrâh"]', '["and/ wrath/ their"]', '["n-f"]', 'an outburst of passion anger, rage, wrath.', 'feminine of 5676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7185}/[H7185]', 'lemma', 'heb', 'קָשָׁה', '["qâshâh"]', '["I will make stubborn","[one who] hardens","hard pressed","has he shown stubbornness","he had made stubborn","he made hard","he made stubborn","it is hard","it will be [too] hard","it will be hard","they have stiffened","they stiffened","you harden","you have made difficult","you will make stiff"]', '["v"]', 'properly, to be dense, i.e. tough or severe (in various applications) be cruel, be fiercer, make grievous, be ((ask a), be in, have, seem, would) hard(-en, (labour), -ly, thing), be sore, (be, make) stiff(-en, (-necked)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2505A}/H9038/[H2505]', 'inflected', 'heb', 'חָלַק', '["châlaq"]', '["I will divide/ them","it scattered/ them"]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3290}/[H6117]', 'inflected', 'heb', 'יַעֲקֹב', '["Yaʻăqôb"]', '["<in>/ Jacob","[is] in/ Jacob","in/ Jacob","over/ Jacob"]', '["n-pr-m"]', 'Jaakob, the Israelitish patriarch Jacob.', 'from 6117; heel-catcher (i.e. supplanter);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6327A}/H9038/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["and/ I will scatter/ them","and/ you will scatter/ them"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3478}\/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["[was] in/ Israel","in/ Israel","over/ Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3034}/H9031/[H3027]', 'inflected', 'heb', 'יָדָה', '["yâdâh"]', '["I will give thanks to/ you","I will give thanks/ you","I will praise/ you","he gives thanks to/ you","it gives thanks to/ you","it will praise/ you","may they praise/ you","they will give thanks to/ you","they will praise/ you","will they give thanks to?/ you"]', '["v"]', 'physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving).', 'a primitive root; used only as denominative from 3027; literally, to use (i.e. hold out) the hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6203}/[H6202]', 'inflected', 'heb', 'עֹרֶף', '["ʻôreph"]', '["[will be] on/ [the] neck of"]', '["n-m"]', 'the nape or back of the neck (as declining); hence, the back generally (whether literal or figurative) back ((stiff-) neck((-ed).', 'from 6202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0341}/H9021/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["enemies/ your","enemy/ your"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1482}/[H1481]', 'lemma', 'heb', 'גּוּר', '["gûwr"]', '["[is] a cub of"]', '["n-m"]', 'a cub (as still abiding in the lair), especially of the lion whelp, young one.', 'or (shortened) גֻּר; perhaps from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0738B}/[H717]', 'lemma', 'heb', 'אֲרִי', '["ʼărîy"]', '["a lion"]', '["n-m"]', 'a lion (young) lion, pierce (from the margin).', 'or (prolonged) אַרְיֵה; from 717 (in the sense of violence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2964}/[H2963]', 'inflected', 'heb', 'טֶרֶף', '["ṭereph"]', '["from/ prey"]', '["n-m"]', 'something torn, i.e. a fragment, e.g. a fresh leaf, prey, food leaf, meat, prey, spoil.', 'from 2963;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3766}/[H3766]', 'lemma', 'heb', 'כָּרַע', '["kâraʻ"]', '["[was] kneeling","[were] kneeling","anyone kneeled down","bending","certainly <to bring low>","he bowed down","he bows down","he has bowed down","he knelt","he made bow down","he will bow down","it crouched","it will bow down","they bow down","they bowed down","they have bowed down","they kneel down","they will bow down","you made bow down","you make bow down","you will bow down"]', '["v"]', 'to bend the knee; by implication, to sink, to prostrate bow (down, self), bring down (low), cast down, couch, fall, feeble, kneeling, sink, smite (stoop) down, subdue, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0738B}/[H717]', 'inflected', 'heb', 'אֲרִי', '["ʼărîy"]', '["[is] like/ a lion","like/ a lion"]', '["n-m"]', 'a lion (young) lion, pierce (from the margin).', 'or (prolonged) אַרְיֵה; from 717 (in the sense of violence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H3833C>', 'inflected', 'heb', 'וכלביא', '["u./khe./la.Vi''"]', '["and/ like/ a lion"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965B}/H9033/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["will he rouse/ him","will he rouse/ it"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5493H}/[H5493]', 'lemma', 'heb', 'סוּר', '["çûwr"]', '["[is] about to be removed","[is] to turn aside","[one who] turns aside","depart","departed","he had departed","he had turned aside","he has turned aside","he turned aside","he will depart","he will turn aside","it departed","it has come to an end","it has departed","it has turned aside","it will be removed","it will depart","let him turn aside","they should depart","they turned aside","to turn aside","turn aside","turn away","turning aside","we will depart","you depart"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7626G>', 'opaque', 'heb', 'שֵׁבֶט', '["shêbeṭ"]', '["[is] a scepter of","[the] rod of","[the] scepter of","[the] tribe of","[the] tribes of","a rod","a rod of","a scepter","scepters of"]', '["n-m"]', 'a scion, i.e. (literally) a stick (for punishing, writing, fighting, ruling, walking, etc.) or (figuratively) a clan × correction, dart, rod, sceptre, staff, tribe.', 'from an unused root probably meaning to branch off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3063G}/[H3034]', 'inflected', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["from/ Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2710}/[H2710]', 'inflected', 'heb', 'חָקַק', '["châqaq"]', '["and/ a ruler''s staff","so/ they may be inscribed"]', '["v"]', 'properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0996G}/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["from/ between"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7886}/[H7951]', 'lemma', 'heb', 'שִׁילֹה', '["Shîylôh"]', '["Shiloh"]', '["n-pr-m"]', 'Shiloh, an epithet of the Messiah Shiloh.', 'from 7951; tranquil;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H9033}', 'inflected', 'arc', 'ולו', '["ve./L/o","ve./Le/h","ve./l/o","ve./lo/v"]', '["and/ [belong] to/ him","and/ [belonged] to <the>/ him","and/ [belonged] to/ him","and/ [belonged] to/ it","and/ [belongs] to <the>/ him","and/ [will belong] to/ him","and/ for/ him","and/ of/ him","and/ to <the>/ him","and/ to/ him","and/ to/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3349}/[H3348]', 'lemma', 'heb', 'יִקָּהָה', '["yiqqâhâh"]', '["[the] obedience of"]', '["n-f"]', 'obedience gathering, to obey.', 'from the same as 3348;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1612>', 'inflected', 'heb', 'לגפן', '["la./Ga.fen","la./Ge.fen","le./Ge.fen"]', '["<into>/ a vine","<into>/ a vine of","to the/ vine"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5895}/H9023/[H5782]', 'inflected', 'heb', 'עַיִר', '["ʻayir"]', '["donkey/ his"]', '["n-m"]', 'properly, a young ass (as just broken to a load); hence an ass-colt (ass) colt, foal, young ass.', 'from 5782 in the sense of raising (i.e. bearing a burden);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8321B}/[H8319]', 'inflected', 'heb', 'שֹׂרֵק', '["sôrêq"]', '["and/ to the/ choice vine"]', '["n-m"]', 'a vine stock (properly, one yielding purple grapes, the richest variety) choice(-st, noble) wine. Compare 8291.', 'or שׂוֹרֵק; and (feminine) שֹׂרֵקָה; from 8319 in the sense of redness (compare 8320);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0860}/H9023/[H386]', 'inflected', 'heb', 'אָתוֹן', '["ʼâthôwn"]', '["donkey/ his"]', '["n-f"]', 'a female donkey (from its docility) (she) ass.', 'probably from the same as 386 (in the sense of patience);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3526H}/[H3526]', 'lemma', 'heb', 'כָּבַס', '["kâbaç"]', '["he had washed","he will wash","was washed out","wash","washers","you will wash"]', '["v"]', 'to trample; hence, to wash (properly, by stamping with the feet), whether literal (including the fulling process) or figurative fuller, wash(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3196>', 'inflected', 'heb', 'ביין', '["ba/i.Ya.yin","be./Ya.yin","be./Yein"]', '["by the/ wine","for/ [the] wine of","in <the>/ wine","in/ [the] wine","with <the>/ wine","with the/ wine"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3830}/H9023/[H3847]', 'inflected', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["clothing/ his","clothing/ its"]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1818}/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["and/ by/ blood","and/ in/ [the] blood of"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5497}/H9023/[H4533]', 'inflected', 'heb', 'סוּת', '["çûwth"]', '["robe/ his"]', '["n-m"]', 'covering, i.e. clothing clothes.', 'probably from the same root as 4533;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2447>', 'opaque', 'heb', 'חַכְלִיל', '["chaklîyl"]', '["dark of"]', '["a-m"]', 'darkly flashing (only of the eyes); in a good sense, brilliant (as stimulated by wine) red.', 'by reduplication from an unused root apparently meaning to be dark;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3196>', 'inflected', 'heb', 'מיין', '["mi./Ya.yin"]', '["from/ wine","more than/ wine","some of/ [the] wine of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3836}/[H3835]', 'inflected', 'heb', 'לָבָן', '["lâbân"]', '["and/ white","and/ white of"]', '["a"]', 'white white.', 'or (Genesis 49:12) לָבֵן; from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8127G}/[H8150]', 'lemma', 'heb', 'שֵׁן', '["shên"]', '["[the] teeth of","[the] tooth of","a tooth","teeth","tooth"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2461}\/[H2459]', 'inflected', 'heb', 'חָלָב', '["châlâb"]', '["more than/ milk"]', '["n-m"]', 'milk (as the richness of kine) cheese, milk, sucking.', 'from the same as 2459;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2348>', 'inflected', 'heb', 'לחוף', '["le./Chof"]', '["to/ [the] coast of","to/ a harbor of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0591}/[H590]', 'lemma', 'heb', 'אֳנִיָּה', '["ʼŏnîyâh"]', '["<the> ships of","O ships of","[the] ships","[the] ships of","a ship","ships","ships of"]', '["n-f"]', 'a ship ship(-men).', 'feminine of 590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3411}/H9023/[H3409]', 'inflected', 'heb', 'יְרֵכָה', '["yᵉrêkâh"]', '["and/ side/ his"]', '["n-f"]', 'properly, the flank; but used only figuratively, the rear or recess border, coast, part, quarter, side.', 'feminine of 3409;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6721H}\/[H6679]', 'inflected', 'heb', 'צִידוֹן', '["Tsîydôwn"]', '["Sidon"]', '["n-pr-loc"]', 'Tsidon, the name of a son of Canaan, and of a place in Palestine Sidon, Zidon.', 'or צִידֹן; from 6679 in the sense of catching fish; fishery;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1634}/[H1633]', 'lemma', 'heb', 'גֶּרֶם', '["gerem"]', '["[the] bone of","bone","bone[s]"]', '["n-m"]', 'a bone (as the skeleton of the body); hence, self, i.e. (figuratively) very bone, strong, top.', 'from 1633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4942}/[H8192]', 'inflected', 'heb', 'מִשְׁפָּת', '["mishpâth"]', '["the/ fire-places","the/ two campfires"]', '["n-m"]', 'a stall for cattle (only dual) burden, sheepfold.', 'from 8192;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4496H}/[H4495]', 'lemma', 'heb', 'מְנוּחָה', '["mᵉnûwchâh"]', '["a resting place","rest","rest<s>"]', '["n-f"]', 'repose or (adverbially) peacefully; figuratively, consolation (specifically, matrimony); hence (concretely) an abode comfortable, ease, quiet, rest(-ing place), still.', 'or מְנֻחָה; feminine of 4495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5276}/[H5276]', 'lemma', 'heb', 'נָעֵם', '["nâʻêm"]', '["are you lovely","it is delightful","it was pleasant","it will be pleasant","they are pleasant","you are lovely","you were pleasant"]', '["v"]', 'to be agreeable (literally or figuratively) pass in beauty, be delight, be pleasant, be sweet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7926}/H9023/[H7925]', 'inflected', 'heb', 'שְׁכֶם', '["shᵉkem"]', '["shoulder/ his","shoulder/ its"]', '["n-m"]', 'the neck (between the shoulders) as the place of burdens; figuratively, the spur of a hill back, × consent, portion, shoulder.', 'from 7925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5445}/[H5445]', 'inflected', 'heb', 'סָבַל', '["çâbal"]', '["to/ carry a load"]', '["v"]', 'to carry (literally or figuratively), or (reflexively) be burdensome; specifically, to be gravid bear, be a burden, carry, strong to labour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4522}/[H4549]', 'inflected', 'heb', 'מַס', '["maç"]', '["<into>/ a slave gang of","<into>/ forced labor","<into>/ forced labor of","into/ forced labor","to/ forced labor","to/ forced labor of"]', '["n-m"]', 'properly, a burden (as causing to faint), i.e. a tax in the form of forced labor discomfited, levy, task(-master), tribute(-tary).', 'or מִס; from 4549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647G}\/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["laboring"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971A}/H9023/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["<of> people/ his","[is] people/ his","own people/ his","people/ his","people/ its"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7626H>', 'opaque', 'heb', 'שֵׁבֶט', '["shêbeṭ"]', '["[are] [the] tribes of","[is] [the] tribe of","[the] tribe of","[the] tribes of","a tribe","tribe[s]","tribes"]', '["n-m"]', 'a scion, i.e. (literally) a stick (for punishing, writing, fighting, ruling, walking, etc.) or (figuratively) a clan × correction, dart, rod, sceptre, staff, tribe.', 'from an unused root probably meaning to branch off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5175}/[H5172]', 'lemma', 'heb', 'נָחָשׁ', '["nâchâsh"]', '["[the] snake","[the] snake of","a snake","a snake of","snake","snakes"]', '["n-m"]', 'a snake (from its hiss) serpent.', 'from 5172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8207>', 'opaque', 'heb', 'שְׁפִיפֹן', '["shᵉphîyphôn"]', '["a viper"]', '["n-m"]', 'a kind of serpent (as snapping), probably the cerastes or horned adder adder.', 'from an unused root meaning the same as 7779;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5391A}/[H5391]', 'inflected', 'heb', 'נָשַׁךְ', '["nâshak"]', '["<the>/ [one who] is bitten","the/ [one which] bites","who/ bite"]', '["v"]', 'to strike with a sting (as a serpent); figuratively, to oppress with interest on a loan bite, lend upon usury.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6119}/[H6117]', 'lemma', 'heb', 'עָקֵב', '["ʻâqêb"]', '["[the] footprints of","[the] heels of","a heel"]', '["n-m"]', 'a heel (as protuberant); hence, a track; figuratively, the rear (of an army) heel, (horse-) hoof, last, lier in wait (by mistake for 6120), (foot-) step.', 'or (feminine) עִקְּבָה; from 6117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5483M>', 'opaque', 'heb', 'סוּס', '["çûwç"]', '["<the> horse of","[the] horse","[the] horse[s] of","a horse","horse","horse[s]","horses"]', '["n-m"]', 'a horse (as leaping); also a swallow (from its rapid flight) crane, horse (-back, -hoof). Compare 6571.', 'or סֻס; from an unused root meaning to skip (properly, for joy);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7392}/H9023/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["rider/ its"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0268}/[H299]', 'lemma', 'heb', 'אָחוֹר', '["ʼâchôwr"]', '["[the] rear of","back part","backward","backwards"]', '["n-m"]', 'the hinder part; hence (adverb) behind, backward; also (as facing north) the West after(-ward), back (part, -side, -ward), hereafter, (be-) hind(-er part), time to come, without.', 'or (shortened) אָחֹר ; from 299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3444}/H9021/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["for/ deliverance/ your","for/ salvation/ your"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6960A}/[H6960]', 'lemma', 'heb', 'קָוָה', '["qâvâh"]', '["I have waited for","I wait eagerly","I wait for","I waited for","I will hope for","[who] he longs for","certainly <to wait>","did I wait","do I wait for","it waits","let it wait","they have waited","they have waited for","they look eagerly","they will wait","wait","we have waited","we wait eagerly","we waited eagerly","we were looking for"]', '["v"]', 'to bind together (perhaps by twisting), i.e. collect; (figuratively) to expect gather (together), look, patiently, tarry, wait (for, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1416}/[H1413]', 'lemma', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["[the] marauding bands of","a marauding band","marauding bands","troop[s]","troops of"]', '["n-m"]', 'a crowd (especially of soldiers) army, band (of men), company, troop (of robbers).', 'from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1464}/H9033/[H1413]', 'inflected', 'heb', 'גּוּד', '["gûwd"]', '["[which] attacks us/ it","it will attack/ him"]', '["v"]', 'to crowd upon, i.e. attack invade, overcome.', 'a primitive root (akin to 1413);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1464}/[H1413]', 'lemma', 'heb', 'גּוּד', '["gûwd"]', '["he will attack"]', '["v"]', 'to crowd upon, i.e. attack invade, overcome.', 'a primitive root (akin to 1413);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0836}/[H833]', 'inflected', 'heb', 'אָשֵׁר', '["ʼÂshêr"]', '["from/ Asher"]', '["n-pr"]', 'Asher, a son of Jacob, and the tribe descended from him, with its territory; also a place in Palestine Asher', 'from 833, happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8082}/[H8080]', 'lemma', 'heb', 'שָׁמֵן', '["shâmên"]', '["[is] fat","[will be] rich","fertile","rich","stout [person]"]', '["a"]', 'greasy, i.e. gross; figuratively, rich fat, lusty, plenteous.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899G}/H9023/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["[is] food/ his","food/ his","food/ its"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4574}/[H5727]', 'lemma', 'heb', 'מַעֲדָן', '["maʻădân"]', '["delicacies of","delights"]', '["n-m"]', 'a delicacy or (abstractly) pleasure (adverbially, cheerfully) dainty, delicately, delight.', 'or (feminine) מַעֲדַנָּה; from 5727;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428G}\/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["a king"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0355}/[H354]', 'lemma', 'heb', 'אַיָּלָה', '["ʼayâlâh"]', '["[is] a doe","[the] doe of","a doe","a doe of","does"]', '["n-f"]', 'a doe or female deer hind.', 'feminine of 354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971H}/[H7971]', 'lemma', 'heb', 'שָׁלַח', '["shâlach"]', '["I will let go","I will set free","O [those who] let loose","[are] letting go","certainly <let go>","did he let loose","he let go","he sent","he will let go","let go","let loose","really <let go>","send away","set free","they had let go","they let go","they send forth","to let go","we have let go","you had let go","you have let go","you let loose","you will let go"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5414G}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["[is] the/ [one who] gives","[is] the/ [one who] has given","the/ [one which] utters","the/ [one who] gives","which/ is put","who/ gives"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0561}/[H559]', 'lemma', 'heb', 'אֵמֶר', '["ʼêmer"]', '["<of> [the] words of","[the] words of","words","words of"]', '["n-m"]', 'something said answer, × appointed unto him, saying, speech, word.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8233}\/[H8231]', 'inflected', 'heb', 'שֶׁפֶר', '["shepher"]', '["beauty"]', '["n-m"]', 'beauty × goodly.', 'from 8231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6805}/[H6805]', 'lemma', 'heb', 'צָעַד', '["tsâʻad"]', '["he strode","she will climb","they had stepped","they walk","you march"]', '["v"]', 'to pace, i.e. step regularly; (upward) to mount; (along) to march; (down and causatively) to hurl bring, go, march (through), run over.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7791A}/[H7788]', 'lemma', 'heb', 'שׁוּר', '["shûwr"]', '["a wall"]', '["n-m"]', 'a wall (as going about) wall.', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4843}/H9033/[H4752]', 'inflected', 'heb', 'מָרַר', '["mârar"]', '["and/ they showed bitterness to/ him"]', '["v"]', 'to be (causatively, make) bitter (literally or figuratively) (be, be in, deal, have, make) bitter(-ly, -ness), be moved with choler, (be, have sorely, it) grieved(-eth), provoke, vex.', 'a primitive root; properly, to trickle (see 4752); but used only as a denominative from 4751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7232}/[H7231]', 'inflected', 'heb', 'רָבַב', '["râbab"]', '["and/ they shot"]', '["v"]', 'to shoot an arrow shoot.', 'a primitive root (rather identical with 7231 through the idea of projection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7852}/H9033/[H7852]', 'inflected', 'heb', 'שָׂטַם', '["sâṭam"]', '["and/ they bear a grudge/ him"]', '["v"]', 'properly, to lurk for, i.e. persecute hate, oppose self against.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2671}/[H2686]', 'lemma', 'heb', 'חֵץ', '["chêts"]', '["[is] an arrow","[the] arrows of","an arrow","an arrow of","arrows","arrows of"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0386>', 'inflected', 'heb', 'באיתן', '["be./''ei.Tan"]', '["in/ permanence"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7198}/H9023/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["bow/ his","bows/ its"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6339}/[H6338]', 'inflected', 'heb', 'פָּזַז', '["pâzaz"]', '["and/ they were agile"]', '["v"]', 'to solidify (as if by refining); also to spring (as if separating the limbs) leap, be made strong.', 'a primitive root (identical with 6338);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2220}/[H2232]', 'lemma', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["O arm of","[does] an arm","[the] arm","[the] arm of","[the] arms of","an arm","an arm of","arm","arms of"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0046}/[H82]', 'lemma', 'heb', 'אָבִיר', '["ʼâbîyr"]', '["[the] mighty one of"]', '["a-m"]', 'mighty (spoken of God) mighty (one).', 'from 82;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0410G}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["[is] more than/ God","from/ God","from/ [the] God of"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5826}/H9031/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["and/ he will help/ you"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7699A}/[H7736]', 'lemma', 'heb', 'שַׁד', '["shad"]', '["[the] breasts of","a breast","breasts"]', '["n-m"]', 'the breast of a woman or animal (as bulging) breast, pap, teat.', 'or שֹׁד; probably from 7736 (in its original sense) contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7356A}/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["and/ womb"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2029}/H9030/[H2029]', 'inflected', 'heb', 'הָרָה', '["hârâh"]', '["[the men who] conceived/ me","[the one who] conceived/ me"]', '["v"]', 'to be (or become) pregnant, conceive (literally or figuratively) been, be with child, conceive, progenitor.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8379}/[H8376]', 'lemma', 'heb', 'תַּאֲוָה', '["taʼăvâh"]', '["desire of"]', '["n-f"]', 'a limit, i.e. full extent utmost bound.', 'from 8376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1389I}/[H1387]', 'lemma', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["O hills","[the] hill of","[the] hills","[the] hills of","a hill","hill","hills","hills of"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7218A>', 'inflected', 'heb', 'לראש', '["le./Rosh","le./roSh"]', '["<into>/ [the] head of","[belong] to/ [the] head of","[belongs] to/ [the] head of","for/ [the] head of","into/ [the] head","to/ [the] head of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6936}/[H6915]', 'inflected', 'heb', 'קׇדְקֹד', '["qodqôd"]', '["and/ to the/ scalp","and/ to/ [the] scalp of"]', '["n-m"]', 'the crown of the head (as the part most bowed) crown (of the head), pate, scalp, top of the head.', 'from 6915;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5139}/[H5144]', 'lemma', 'heb', 'נָזִיר', '["nâzîyr"]', '["[am] a Nazirite of","[the] consecrated one of","[the] prince of","a Nazirite","a Nazirite of"]', '["n-m"]', 'separate, i.e. consecrated (as prince, a Nazirite); hence (figuratively from the latter) an unpruned vine (like an unshorn Nazirite) Nazarite (by a false alliteration with Nazareth), separate(-d), vine undressed.', 'or נָזִר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251G}/H9023\/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["brother/ his","brothers/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2061>', 'opaque', 'heb', 'זְאֵב', '["zᵉʼêb"]', '["[are] wolves of","[is] a wolf","a wolf of","wolf"]', '["n-m"]', 'a wolf wolf.', 'from an unused root meaning to be yellow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5706}/[H5703]', 'lemma', 'heb', 'עַד', '["ʻad"]', '["booty","booty of"]', '["n-m"]', 'booty prey.', 'the same as 5703 in the sense of the aim of an attack;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6153}/[H6150]', 'inflected', 'heb', 'עֶרֶב', '["ʻereb"]', '["and/ for the/ evening","and/ of the/ evening","and/ to the/ evening"]', '["n-m"]', 'dusk day, even(-ing, tide), night.', 'from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2505A}/[H2505]', 'lemma', 'heb', 'חָלַק', '["châlaq"]', '["I will allot a portion","I will divide","I will divide up","[one who] has shares","[where] it is divided","apportion","are they dividing up?","divide","does he apportion?","he apportions","he divides","he gave a share","he had assigned","he had plundered","he has assigned","he will apportion","he will divide up","he will share","it was divided","it will be divided","she divides","they distribute","they had divided","you will divide"]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7998}/[H7997]', 'lemma', 'heb', 'שָׁלָל', '["shâlâl"]', '["<of> plunder","[is] [the] booty of","[the] booty of","[the] plunder","[the] plunder of","booty","plunder","plunder of"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2063}/[H2088]', 'inflected', 'heb', 'זֹאת', '["zôʼth"]', '["and/ this","and/ this [one]"]', '["d"]', 'this (often used adverb) hereby (-in, -with), it, likewise, the one (other, same), she, so (much), such (deed), that, therefore, these, this (thing), thus.', 'irregular feminine of 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1293}/H9023/[H1288]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["according to/ blessing/ his"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971B}/H9020/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["own people/ my","people/ my"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4631}/[H5783]', 'inflected', 'heb', 'מְעָרָה', '["mᵉʻârâh"]', '["the/ cave","the/ caves"]', '["n-f"]', 'a cavern (as dark) cave, den, hole.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8033G}/H9011/[H834]', 'inflected', 'heb', 'שָׁם', '["shâm"]', '["and/ [were] there/ <towards>","and/ there/ <towards>","and/ there/ towards"]', '["adv"]', 'there (transferring to time) then; often thither, or thence in it, thence, there (-in, of, out), thither, whither.', 'a primitive particle (rather from the relative pronoun, 834);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6680}/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["to/ appoint","to/ command"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7495}/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["the/ physicians","who/ [is] healing","who/ heals"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2590A}/[H2590]', 'inflected', 'heb', 'חָנַט', '["chânaṭ"]', '["to/ embalm"]', '["v"]', 'to spice; by implication, to embalm; also to ripen embalm, put forth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2590A}/[H2590]', 'inflected', 'heb', 'חָנַט', '["chânaṭ"]', '["and/ people embalmed","and/ they embalmed"]', '["v"]', 'to spice; by implication, to embalm; also to ripen embalm, put forth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2590B}/[H2590]', 'inflected', 'heb', 'חָנַט', '["chânaṭ"]', '["the/ embalming<s>"]', '["v"]', 'to spice; by implication, to embalm; also to ripen embalm, put forth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1068}/H9023/[H1058]', 'inflected', 'heb', 'בְּכִית', '["bᵉkîyth"]', '["weeping/ his"]', '["n-f"]', 'a weeping mourning.', 'from 1058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7650}/H9030/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["he made swear an oath/ me"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6913}/H9020/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["in/ grave/ my"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3738B}/[H3738]', 'lemma', 'heb', 'כָּרָה', '["kârâh"]', '["I dug","[is] digging up","[one who] digs","he digs","he had dug","he will dig","it will be dug","they dug","they have dug","you dug"]', '["v"]', 'properly, to dig; figuratively, to plot; generally, to bore or open dig, × make (a banquet), open.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7650}/H9031/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["did I make swear/ you","he made swear/ you","make swear/ you"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2205G}/[H2204]', 'lemma', 'heb', 'זָקֵן', '["zâqên"]', '["[are] [the] elders of","[the] elders","[the] elders of","an old [man]","elders"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7393G}/[H7392]', 'lemma', 'heb', 'רֶכֶב', '["rekeb"]', '["[the] chariot of","[the] chariotry of","a chariot","a chariot of","a rider","a rider of","chariot[s]","chariot[s] of","charioteer[s]","chariotry","chariotry of"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6571B}/[H6567]', 'lemma', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["a horseman","horsemen","horses","warhorses"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1637>', 'opaque', 'heb', 'גֹּרֶן', '["gôren"]', '["[the] threshing floor","[the] threshing floor of","a threshing floor","threshing floor","threshing floors of"]', '["n-m"]', 'a threshing-floor (as made even); by analogy, any open area (barn, corn, threshing-) floor, (threshing-, void) place.', 'from an unused root meaning to smooth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0329G>', 'inflected', 'heb', 'האטד', '["ha./''a.Tad"]', '["<the>/ Atad"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5676H}/[H5674]', 'inflected', 'heb', 'עֵבֶר', '["ʻêber"]', '["[is] on/ [the] other side of","[was] on/ [the] other side of","[were] on/ [the] other side of","on/ [the] other side of","on/ [the] other sides"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5594}/[H5594]', 'inflected', 'heb', 'סָפַד', '["çâphad"]', '["and/ it will mourn","and/ people mourned","and/ she mourned","and/ they had mourned","and/ they lamented","and/ they mourned","and/ they will mourn"]', '["v"]', 'properly, to tear the hair and beat the breasts (as Orientals do in grief); generally to lament; by implication, to wail lament, mourn(-er), wail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4553}/[H5594]', 'lemma', 'heb', 'מִסְפֵּד', '["miçpêd"]', '["[the] lament of","a lament","wailing","wailing of"]', '["n-m"]', 'a lamentation lamentation, one mourneth, mourning, wailing.', 'from 5594;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3515}/[H3513]', 'inflected', 'heb', 'כָּבֵד', '["kâbêd"]', '["and/ heavy","and/ heavy of"]', '["a"]', 'heavy; figuratively in a good sense (numerous) or in a bad sense (severe, difficult, stupid) (so) great, grievous, hard(-ened), (too) heavy(-ier), laden, much, slow, sore, thick.', 'from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0060}/[H56]', 'inflected', 'heb', 'אֵבֶל', '["ʼêbel"]', '["the/ mourning"]', '["n-m"]', 'lamentation mourning.', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1637>', 'inflected', 'heb', 'בגרן', '["ba./Go.ren","be./Go.ren"]', '["at/ [the] threshing floor","at/ [the] threshing floor of","on the/ threshing floor","on/ [the] threshing floor of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0067}/[H58]', 'lemma', 'heb', 'אָבֵל מִצְרַיִם', '["ʼÂbêl Mitsrayim"]', '["Abel","Mizraim"]', '["n-pr-loc"]', 'Abel-Mitsrajim, a place in Palestine Abel-mizraim.', 'from 58 and 4714; meadow of Egypt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6680}/H9038/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["I appointed/ them","I commanded/ them","I had commanded/ them","I have commanded/ them","he commanded/ them","he commands/ them","he had commanded/ them","it commanded/ them","you will command/ them"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6912}/H9043/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["buried/ he","had buried/ he"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7852}/H9035/[H7852]', 'inflected', 'heb', 'שָׂטַם', '["sâṭam"]', '["he will bear a grudge/ us"]', '["v"]', 'properly, to lurk for, i.e. persecute hate, oppose self against.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725K}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ certainly <to repay>"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725K}/[H7725]', 'lemma', 'heb', 'שׁוּב', '["shûwb"]', '["<of> to repay","I will repay","I will return","he has brought back","he has repaid","he repaid","he will repay","he will return","repay","they brought","they will give back","they will pay","will I give back","you will repay"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0577}/[H160]', 'lemma', 'heb', 'אָנָּא', '["ʼânnâʼ"]', '["I beg you","we beg you"]', '["inj"]', 'oh now! I (me) beseech (pray) thee, O.', 'or אָנָּה; apparent contracted from 160 and 4994;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375I}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["I will forgive","[is one who] is forgiven of","[who] forgives","[will be] forgiven of","certainly <forgive>","forgive","forgiving","he will forgive","it will carry","will you forgive","you forgave","you forgive","you have forgiven","you will forgive"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6588}/[H6586]', 'lemma', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["<the> transgressions of","[is] [the] transgression of","[is] a transgression","[the] transgression of","[the] transgressions of","a transgression","transgression","transgression of","transgressions"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1580}/H9031/[H1580]', 'inflected', 'heb', 'גָּמַל', '["gâmal"]', '["I have dealt out to/ you","he has dealt out to/ you","they dealt out to/ you"]', '["v"]', 'to treat a person (well or ill), i.e. benefit or requite; by implication (of toil), to ripen, i.e. (specifically) to wean bestow on, deal bountifully, do (good), recompense, requite, reward, ripen, serve, mean, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6588}/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["to/ [the] transgression of"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1696G}/H9048/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["when/ spoke/ they"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2009}/H9045/[H2005]', 'inflected', 'heb', 'הִנֵּה', '["hinnêh"]', '["here/ we"]', '["dp"]', 'lo! behold, lo, see.', 'prolongation for 2005;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2803I}/[H2803]', 'lemma', 'heb', 'חָשַׁב', '["châshab"]', '["I had planned","[am] planning","[are] planning","[one who] plans","[those who] plan","[those who] plot","[were] planning","have you planned","he had planned","he has planned","he has purposed","he planned","he plans","he will plan","it planned","it plans","it plots","it thought","may he think","people have planned","people will plan","they had planned","they have planned","they plan","they plot","you plan","you planned"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2803I}/H9034/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["he planned/ it"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2896C}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["<to>/ good","for/ good","of/ goodness","to/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3557}/[H3557]', 'lemma', 'heb', 'כּוּל', '["kûwl"]', '["I will provide for","[will] endure","he had supplied","he maintains","he will sustain","it contained","it will endure","they contain","they will endure","to hold [it] in"]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2945}/H9026/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["little one[s]/ your"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0669G}/[H672]', 'inflected', 'heb', 'אֶפְרַיִם', '["ʼEphrayim"]', '["<to>/ Ephraim","[belonged] to/ Ephraim","[belongs] to/ Ephraim","for/ Ephraim","of/ Ephraim","to/ Ephraim"]', '["n-pr-m"]', 'Ephrajim, a son of Joseph; also the tribe descended from him, and its territory Ephraim, Ephraimites.', 'dual of masculine form of 672; double fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8029}/[H8027]', 'lemma', 'heb', 'שִׁלֵּשׁ', '["shillêsh"]', '["a third generation"]', '["a"]', 'a descendant of the third degree, i.e. great grandchild third (generation).', 'from 8027;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4353G}/[H4376]', 'lemma', 'heb', 'מָכִיר', '["Mâkîyr"]', '["Makir"]', '["n-pr-m"]', 'Makir, an Israelite Machir.', 'from 4376; salesman;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1290}/[H1288]', 'lemma', 'heb', 'בֶּרֶךְ', '["berek"]', '["[the] knees of","knee","knees"]', '["n-f"]', 'a knee knee.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3290}/[H6117]', 'inflected', 'heb', 'יַעֲקֹב', '["Yaʻăqôb"]', '["and/ <to>/ Jacob","and/ to/ Jacob"]', '["n-pr-m"]', 'Jaakob, the Israelitish patriarch Jacob.', 'from 6117; heel-catcher (i.e. supplanter);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3455}/[H3455]', 'inflected', 'heb', 'יָשַׂם', '["yâsam"]', '["and/ he was put"]', '["v"]', 'to place; intransitively, to be placed be put (set).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0727}/[H717]', 'inflected', 'heb', 'אָרוֹן', '["ʼârôwn"]', '["[was] in the/ ark","[was] in the/ chest","in the/ ark","in the/ coffin","in/ [the] ark of"]', '["n-m"]', 'a box ark, chest, coffin.', 'or אָרֹן; from 717 (in the sense of gathering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004M}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ household/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1755}/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["O/ generation","the/ generation","the/ generations"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6105A}/[H6106]', 'inflected', 'heb', 'עָצַם', '["ʻâtsam"]', '["and/ he will become mighty","and/ it will be mighty","and/ they became mighty"]', '["v"]', 'to bind fast, i.e. close (the eyes); intransitively, to be (causatively, make) powerful or numerous; to crunch the bones break the bones, close, be great, be increased, be (wax) mighty(-ier), be more, shut, be(-come, make) strong(-er).', 'a primitive root; also denominatively (from 6106)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9038\/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["with/ them"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2319H}/[H2318]', 'lemma', 'heb', 'חָדָשׁ', '["châdâsh"]', '["[is] new","[the] new [harvest]","[they are] new","a new","a new [thing]","a new [weapon]","new","new [gods]","new [thing]","new [things]"]', '["a"]', 'new fresh, new thing.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2449}/[H2449]', 'lemma', 'heb', 'חָכַם', '["châkam"]', '["be wise","have I become wise","he becomes wise","he is wise","he taught wisdom","he will become wise","it is wise","let me be wise","let us deal wisely","made wise","making wise","skillful","they are wise","they were wise","you are wise","you make yourself wise","you may become wise"]', '["v"]', 'to be wise (in mind, word or act) × exceeding, teach wisdom, be (make self, shew self) wise, deal (never so) wisely, make wiser.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8130}/H9035/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["[those who] hate/ us"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3898A}/[H3898]', 'inflected', 'heb', 'לָחַם', '["lâcham"]', '["and/ I will fight","and/ he engaged in battle","and/ he fought","and/ he waged war","and/ he will engage in battle","and/ he will fight","and/ it joined battle","and/ it will fight","and/ people will fight","and/ they did battle","and/ they engaged in battle","and/ they fought","and/ they waged war","and/ they will fight","and/ we will fight","and/ you will fight","and/ you will wage war"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760L}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ I will appoint","and/ I will designate","and/ I will establish","and/ he appointed","and/ he will appoint [them]","and/ she appointed","and/ they appointed","and/ they will appoint"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4522}/[H4549]', 'lemma', 'heb', 'מַס', '["maç"]', '["a tax","forced labor","slave gangs"]', '["n-m"]', 'properly, a burden (as causing to faint), i.e. a tax in the form of forced labor discomfited, levy, task(-master), tribute(-tary).', 'or מִס; from 4549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6031B}/H9033/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["he will afflict/ him","to afflict/ it"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5450}/H9028/[H5447]', 'inflected', 'heb', 'סְבָלָה', '["çᵉbâlâh"]', '["on/ forced labor/ their","with/ forced labor/ their"]', '["n-f"]', 'porterage burden.', 'from 5447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4543}/[H3664]', 'lemma', 'heb', 'מִסְכְּנָה', '["miçkᵉnâh"]', '["[the] stores of","storage"]', '["n-f"]', 'a magazine store(-house), treasure.', 'by transp. from 3664;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6547I}/[H6547]', 'inflected', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["for/ Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6619}/[H6619]', 'lemma', 'heb', 'פִּתֹם', '["Pithôm"]', '["Pithom"]', '["n-pr-loc"]', 'Pithom, a place in Egypt Pithom.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7486H}/[H7486]', 'lemma', 'heb', 'רַעְמְסֵס', '["Raʻmᵉçêç"]', '["Rameses"]', '["n-pr-loc"]', 'Rameses or Raamses, a place in Egypt Raamses, Rameses.', 'or רַעַמְסֵס; of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6973}/[H6962]', 'inflected', 'heb', 'קוּץ', '["qûwts"]', '["and/ I loathed","and/ he loathed","and/ it felt dread","and/ people felt dread"]', '["v"]', 'to be (causatively, make) disgusted or anxious abhor, be distressed, be grieved, loathe, vex, be weary.', 'a primitive root (identical with through the idea of severing oneself from (compare 6962));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6531>', 'inflected', 'heb', 'בפרך', '["be./Fa.rekh","be./Fe.rekh"]', '["with/ harshness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4843}/[H4752]', 'inflected', 'heb', 'מָרַר', '["mârar"]', '["and/ it was enraged","and/ they made bitter"]', '["v"]', 'to be (causatively, make) bitter (literally or figuratively) (be, be in, deal, have, make) bitter(-ly, -ness), be moved with choler, (be, have sorely, it) grieved(-eth), provoke, vex.', 'a primitive root; properly, to trickle (see 4752); but used only as a denominative from 4751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416E}/H9028/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["lives/ their"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2563A}/[H2560]', 'inflected', 'heb', 'חֹמֶר', '["chômer"]', '["in/ mortar","with the/ clay"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3843}/[H3835]', 'inflected', 'heb', 'לְבֵנָה', '["lᵉbênâh"]', '["and/ in/ bricks"]', '["n-f"]', 'a brick (from the whiteness of the clay) (altar of) brick, tile.', 'from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5656I}/[H5647]', 'lemma', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["[the] Work of","[the] service of","labor","servitude"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5656I}/H9028/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["labor/ their","service/ their"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8236}/[H8235]', 'lemma', 'heb', 'שִׁפְרָה', '["Shiphrâh"]', '["[was] Shiphrah"]', '["n-pr-f"]', 'Shiphrah, an Israelitess Shiphrah.', 'the same as 8235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6326>', 'opaque', 'heb', 'פּוּעָה', '["Pûwʻâh"]', '["[was] Puah"]', '["n-pr-f"]', 'Puah, an Israelitess Puah.', 'from an unused root meaning to glitter; brilliancy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3205}/H9047/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["when/ assist as midwife/ you"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0070}/[H68]', 'inflected', 'heb', 'אֹבֶן', '["ʼôben"]', '["the/ stones"]', '["n-m"]', 'a pair of stones (only dual); a potter''s wheel or a midwife''s stool (consisting alike of two horizontal disks with a support between) wheel, stool.', 'from the same as 68;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/H9039/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["to/ them"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6547I}/[H6547]', 'lemma', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2422}/[H2421]', 'lemma', 'heb', 'חָיֶה', '["châyeh"]', '["[are] vigorous"]', '["a"]', 'vigorous lively.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6213I}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ he appointed","and/ he made","and/ he prepared","and/ he will offer","and/ he will provide","and/ they will offer","and/ we will offer [them]","and/ you have acquired","and/ you will make","and/ you will offer"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3209}/[H3205]', 'inflected', 'heb', 'יִלּוֹד', '["yillôwd"]', '["<the>/ born","the/ [ones] born"]', '["a"]', 'born born.', 'passive from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2975G}/H9011/[H2975]', 'inflected', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["the/ River/ towards"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7993}/H9033/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["throw/ him","throw/ it","you will throw/ him"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2421}/H9013\/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["you will let live/ !"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6845}/H9033/[H6845]', 'inflected', 'heb', 'צָפַן', '["tsâphan"]', '["and/ she hid/ him"]', '["v"]', 'to hide (by covering over); by implication, to hoard or reserve; figuratively to deny; specifically (favorably) to protect, (unfavorably) to lurk esteem, hide(-den one, self), lay up, lurk (be set) privily, (keep) secret(-ly, place).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3391>', 'opaque', 'heb', 'יֶרַח', '["yerach"]', '["[the] months","a month of","months","months of"]', '["n-m"]', 'a lunation, i.e. month month, moon.', 'from a unused root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6845}/H9033/[H6845]', 'inflected', 'heb', 'צָפַן', '["tsâphan"]', '["to hide/ him"]', '["v"]', 'to hide (by covering over); by implication, to hoard or reserve; figuratively to deny; specifically (favorably) to protect, (unfavorably) to lurk esteem, hide(-den one, self), lay up, lurk (be set) privily, (keep) secret(-ly, place).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1573}/[H1572]', 'lemma', 'heb', 'גֹּמֶא', '["gômeʼ"]', '["papyrus"]', '["n-m"]', 'properly, an absorbent, i.e. the bulrush (from its porosity); specifically the papyrus (bul-) rush.', 'from 1572;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2560B}/H9034/[H2564]', 'inflected', 'heb', 'חָמַר', '["châmar"]', '["and/ sealed it/ she"]', '["v"]', 'properly, to boil up; hence, to ferment (with scum); to glow (with redness); to smear with pitch daub, befoul, be red, trouble.', 'a primitive root; also as denominative (from 2564)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2564}/[H2560]', 'inflected', 'heb', 'חֵמָר', '["chêmâr"]', '["with <the>/ bitumen"]', '["n-m"]', 'bitumen (as rising to the surface) slime(-pit).', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H2203>', 'inflected', 'heb', 'ובזפת', '["u./va./Za.fet"]', '["and/ with <the>/ pitch"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5488H}/[H5488]', 'inflected', 'heb', 'סוּף', '["çûwph"]', '["among the/ rush[es]"]', '["n-m"]', 'a reed, especially the papyrus flag, Red (sea), weed. Compare 5489.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3320}/[H3320]', 'inflected', 'heb', 'יָצַב', '["yâtsab"]', '["and/ he presented himself","and/ he stood","and/ he took his stand","and/ she stood","and/ they presented themselves","and/ they stood","and/ they took their stand","and/ they will present themselves"]', '["v"]', 'to place (any thing so as to stay); reflexively, to station, offer, continue present selves, remaining, resort, set (selves), (be able to, can, with-) stand (fast, forth, -ing, still, up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5488H}/[H5488]', 'inflected', 'heb', 'סוּף', '["çûwph"]', '["the/ rush[es]"]', '["n-m"]', 'a reed, especially the papyrus flag, Red (sea), weed. Compare 5489.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0519}/H9024/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["maid/ her"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200G}/H9033/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ I saw/ it","and/ he saw/ him","and/ he showed/ him","and/ he will see/ it","and/ she saw/ him","and/ they saw/ him"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2550}/[H2550]', 'inflected', 'heb', 'חָמַל', '["châmal"]', '["and/ I showed pity","and/ I will have compassion","and/ he had compassion","and/ he spared","and/ she had compassion"]', '["v"]', 'to commiserate; by implication, to spare have compassion, (have) pity, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3206}/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["[is] one of/ [the] children of"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3243H}/[H3243]', 'inflected', 'heb', 'יָנַק', '["yânaq"]', '["so/ she may suckle"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980J}/[H3212]', 'lemma', 'heb', 'הָלַךְ', '["hâlak"]', '["[he is] leading away","he led away","he will lead","he will take","it will carry","take","taking","will I bring"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3243H}/H9033/[H3243]', 'inflected', 'heb', 'יָנַק', '["yânaq"]', '["and/ suckle/ him"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7939}/H9022/[H7936]', 'inflected', 'heb', 'שָׂכָר', '["sâkâr"]', '["wage[s]/ your"]', '["n-m"]', 'payment of contract; concretely, salary, fare, maintenance; by implication, compensation, benefit hire, price, reward(-ed), wages, worth.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3243H}/H9033/[H3243]', 'inflected', 'heb', 'יָנַק', '["yânaq"]', '["and/ he suckled/ him","and/ she suckled/ him"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1323G}/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["for/ [the] daughter of","for/ a daughter","for/ daughters of","of/ [the] daughters of","of/ daughters of","to/ [the] daughter of","to/ a daughter","to/ daughters"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4872}/[H4871]', 'lemma', 'heb', 'מֹשֶׁה', '["Môsheh"]', '["Moses","O Moses","[were] Moses"]', '["n-pr-m"]', 'Mosheh, the Israelite lawgiver Moses.', 'from 4871; drawing out (of the water), i.e. rescued;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4871}/H9033/[H4871]', 'inflected', 'heb', 'מָשָׁה', '["mâshâh"]', '["I drew/ him"]', '["v"]', 'to pull out (literally or figuratively) draw(out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0251I}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["any of/ countrymen/ his","from/ brother/ his","more than/ countrymen/ his","one of/ brothers/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3541}/[H1931]', 'inflected', 'heb', 'כֹּה', '["kôh"]', '["and/ [is] thus","and/ thus"]', '["prt"]', 'properly, like this, i.e. by implication, (of manner) thus (or so); also (of place) here (or hither); or (of time) now also, here, hitherto, like, on the other side, so (and much), such, on that manner, (on) this (manner, side, way, way and that way), mean while, yonder.', 'from the prefix k and 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2934}/H9033/[H2934]', 'inflected', 'heb', 'טָמַן', '["ṭâman"]', '["and/ I hid/ it","and/ he hid/ him"]', '["v"]', 'to hide (by covering over) hide, lay privily, in secret.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2344}/[H2342]', 'inflected', 'heb', 'חוֹל', '["chôwl"]', '["in the/ sand"]', '["n-m"]', 'sand (as round or whirling particles) sand.', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5327A}/[H5327]', 'lemma', 'heb', 'נָצָה', '["nâtsâh"]', '["[were] struggling together","they struggled","they will be struggling together","they will struggle together"]', '["v"]', 'properly, to go forth, i.e. (by implication) to be expelled, and (consequently) desolate; causatively, to lay waste; also (specifically), to quarrel be laid waste, runinous, strive (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7563}/[H7561]', 'inflected', 'heb', 'רָשָׁע', '["râshâʻ"]', '["<to>/ a wicked [person]","[belong] to <the>/ wicked [person]","and/ a wicked [person]","for the/ wicked","to <the>/ wicked [person]","to the/ guilty [one]","to the/ wicked","to the/ wicked [person]","to/ [the] wicked","to/ a guilty [person]","to/ a wicked [person]"]', '["a"]', 'morally wrong; concretely, an (actively) bad person condemned, guilty, ungodly, wicked (man), that did wrong.', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7453}/H9021/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["companion/ your","friend/ your","friends/ your","neighbor/ your"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8199}/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["and/ a judge","and/ judges","and/ may he judge","so/ let me enter into judgment"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H2026}/H9030/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["¿/ to/ kill/ me"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2026}/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["by/ killing","to/ kill"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3548}/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["and/ <into>/ a priest","and/ <to> the/ priests","and/ [belonged] to/ [the] priest of","and/ for the/ priests","and/ to the/ priests"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1802}/[H1809]', 'inflected', 'heb', 'דָּלָה', '["dâlâh"]', '["and/ they drew"]', '["v"]', 'properly, to dangle, i.e. to let down a bucket (for drawing out water); figuratively, to deliver draw (out), × enough, lift up.', 'a primitive root (compare 1809);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7298A>', 'inflected', 'heb', 'הרהטים', '["ha./re.ha.Tim"]', '["the/ drinking troughs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1644G}/H9038/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["and/ they drove away/ them","and/ you will drive out/ them"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3467}/H9039/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ he delivered/ them"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7467J}/[H7466]', 'lemma', 'heb', 'רְעוּאֵל', '["Rᵉʻûwʼêl"]', '["Reuel"]', '["n-pr-m"]', 'Reuel, the name of Moses'' father-in-law, also of an Edomite and an Israelite Raguel, Reuel.', 'from the same as 7466 and 410; friend of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5337}/H9035/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["deliver/ us","he delivered/ us","he rescued/ us","he will deliver/ us","will he deliver/ us"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1802}/[H1809]', 'lemma', 'heb', 'דָּלָה', '["dâlâh"]', '["carefully <to draw>","he drew"]', '["v"]', 'properly, to dangle, i.e. to let down a bucket (for drawing out water); figuratively, to deliver draw (out), × enough, lift up.', 'a primitive root (compare 1809);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0335}/H9043/[H370]', 'inflected', 'heb', 'אַי', '["ʼay"]', '["and/ where [is]?/ he"]', '["adv"]', 'where? hence how? how, what, whence, where, whether, which (way).', 'perhaps from 370;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2974}/[H2973]', 'inflected', 'heb', 'יָאַל', '["yâʼal"]', '["and/ he fell short","and/ he was determined","and/ he was willing","and/ it was determined"]', '["v"]', 'properly, to yield, especially assent; hence (pos.) to undertake as an act of volition assay, begin, be content, please, take upon, × willingly, would.', 'a primitive root (probably rather the same as 2973 through the idea of mental weakness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6855}/[H6833]', 'lemma', 'heb', 'צִפֹּרָה', '["Tsippôrâh"]', '["Zipporah"]', '["n-pr-f"]', 'Tsipporah, Moses’ wife Zipporah.', 'feminine of 6833; bird;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4872}/[H4871]', 'inflected', 'heb', 'מֹשֶׁה', '["Môsheh"]', '["<to>/ Moses","for/ Moses","of/ Moses","to/ Moses"]', '["n-pr-m"]', 'Mosheh, the Israelite lawgiver Moses.', 'from 4871; drawing out (of the water), i.e. rescued;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1647G}/[H1648]', 'lemma', 'heb', 'גֵּרְשֹׁם', '["Gêrᵉshôm"]', '["Gershom","[was] Gershom"]', '["n-pr-m"]', 'Gereshom, the name of four Israelites Gershom.', 'for 1648;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5237}\/[H5235]', 'inflected', 'heb', 'נׇכְרִי', '["nokrîy"]', '["foreign"]', '["a"]', 'strange, in a variety of degrees and applications (foreign, non-relative, adulterous, different, wonderful) alien, foreigner, outlandish, strange(-r, woman).', 'from 5235 (second form);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7227A}/[H7231]', 'inflected', 'heb', 'רַב', '["rab"]', '["<of> the/ many [people]","<the>/ great","<the>/ many","[are] the/ many","the/ many","the/ many [people]"]', '["a n-m"]', 'abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent).', 'by contracted from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0584}/[H584]', 'inflected', 'heb', 'אָנַח', '["ʼânach"]', '["and/ they groaned"]', '["v"]', 'to sigh groan, mourn, sigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5656G}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["[is] the/ service","the/ labor","the/ service"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2199}/[H2199]', 'inflected', 'heb', 'זָעַק', '["zâʻaq"]', '["and/ I cried out","and/ I summoned","and/ he called out to","and/ he cried","and/ he cried out","and/ he had a proclamation made","and/ he summoned","and/ he was called together","and/ it cried out","and/ it has cried out","and/ it was called together","and/ she cried out","and/ they cried for help","and/ they cried out","and/ they were called together","and/ they will cry out","and/ you will cry out"]', '["v"]', 'to shriek (from anguish or danger); by analogy, (as a herald) to announce or convene publicly assemble, call (together), (make a) cry (out), come with such a company, gather (together), cause to be proclaimed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7775}/H9028/[H7773]', 'inflected', 'heb', 'שַׁוְעָה', '["shavʻâh"]', '["cry for help/ their"]', '["n-f"]', 'a hallooing crying.', 'feminine of 7773;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5009}/H9028/[H5008]', 'inflected', 'heb', 'נְאָקָה', '["nᵉʼâqâh"]', '["groaning/ their"]', '["n-f"]', 'a groan groaning.', 'from 5008;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1285}/H9023/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["<of> covenant/ his","covenant/ his"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4872}/[H4871]', 'inflected', 'heb', 'מֹשֶׁה', '["Môsheh"]', '["and/ Moses"]', '["n-pr-m"]', 'Mosheh, the Israelite lawgiver Moses.', 'from 4871; drawing out (of the water), i.e. rescued;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3503}/[H3499]', 'lemma', 'heb', 'יִתְרוֹ', '["Yithrôw"]', '["Jethro"]', '["n-pr-m"]', 'Jethro, Moses'' father-in-law Jethro. Compare 3500.', 'from 3499 with pron. suffix; his excellence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2859A}/H9023/[H2859]', 'inflected', 'heb', 'חָתַן', '["châthan"]', '["father-in-law/ his","mother-in-law/ his"]', '["v"]', 'to give (a daughter) away in marriage; hence (generally) to contract affinity by marriage join in affinity, father in law, make marriages, mother in law, son in law.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2722}/H9011/[H2717]', 'inflected', 'heb', 'חֹרֵב', '["Chôrêb"]', '["Horeb/ towards"]', '["n-pr-loc"]', 'Choreb, a (generic) name for the Sinaitic mountains Horeb.', 'from 2717; desolate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3827}/[H3852]', 'inflected', 'heb', 'לַבָּה', '["labbâh"]', '["in/ a flame of"]', '["n-f"]', 'flame flame.', 'for 3852;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5572>', 'inflected', 'heb', 'הסנה', '["ha./se.Neh"]', '["the/ bush"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1197A}/[H1198]', 'lemma', 'heb', 'בָּעַר', '["bâʻar"]', '["[are] kindling","[is] about to burn","[is] burning","[was] burning","[was] kindled","[which] it burns","[which] you have kindled","burning","he destroyed","is it burning","it burned","it burns","it had burned","it has burned","it will burn","people have burned","someone sweeps away","they burned","they will kindle","will it burn?","you must kindle","you will burn"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0784}/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["[was] in the/ fire","by <the>/ fire","in <the>/ fire","in the/ fire","in/ [the] fire of","in/ a fire","on/ a fire of","with <the>/ fire","with/ [the] fire of"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H5572>', 'inflected', 'heb', 'והסנה', '["ve./ha./se.Neh"]', '["and/ the/ bush"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5394}/[H5394]', 'lemma', 'heb', 'נָשַׁל', '["nâshal"]', '["it will drop off","take off"]', '["v"]', 'to pluck off, i.e. divest, eject or drop cast (out), drive, loose, put off (out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5275}/H9021/[H5274]', 'inflected', 'heb', 'נַעַל', '["naʻal"]', '["sandal/ your","sandals/ your"]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7272}/H9021/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["feet/ your","foot/ your"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6944G}/[H6942]', 'lemma', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["<the> holiness of","[are] a holy thing","[are] holiness","[are] holy person[s]","[are] holy thing[s]","[is] a holy place","[is] a holy portion","[is] a holy thing","[is] a holy thing of","[is] holiness of","[it is] a holy place","[it is] a holy thing","[the] holiness of","[the] holy gifts of","[the] holy thing of","[the] holy things of","[the] sanctuary","[the] sanctuary of","[was] a holy thing","[will be] a holy place","[will be] a holy place of","[will be] a holy portion","[will be] a holy thing of","[will be] holy","a holy one of","a holy place","a holy place of","a holy portion","a holy thing","a holy thing of","holiness","holiness of","holiness<es>","holy one[s]","holy ones","holy places","holy thing","holy things"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5641}/[H5641]', 'inflected', 'heb', 'סָתַר', '["çâthar"]', '["and/ I hid","and/ I will hide","and/ I will hide myself","and/ he hid","and/ he hid himself","and/ he hides himself","and/ it hid","and/ she will be undiscovered","and/ they hid","and/ you will hide yourself"]', '["v"]', 'to hide (by covering), literally or figuratively be absent, keep close, conceal, hide (self), (keep) secret, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5027}/[H5027]', 'inflected', 'heb', 'נָבַט', '["nâbaṭ"]', '["from/ looking"]', '["v"]', 'to scan, i.e. look intently at; by implication, to regard with pleasure, favor or care (cause to) behold, consider, look (down), regard, have respect, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6040}/[H6031]', 'lemma', 'heb', 'עֳנִי', '["ʻŏnîy"]', '["[the] affliction of","affliction"]', '["n-m"]', 'depression, i.e. misery afflicted(-ion), trouble.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5065}/H9033/[H5065]', 'inflected', 'heb', 'נָגַשׂ', '["nâgas"]', '["oppressors/ its","taskmasters/ its"]', '["v"]', 'to drive (an animal, a workman, a debtor, an army); by implication, to tax, harass, tyrannize distress, driver, exact(-or), oppress(-or), × raiser of taxes, taskmaster.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4341}/H9023/[H3510]', 'inflected', 'heb', 'מַכְאֹב', '["makʼôb"]', '["pains/ its"]', '["n-m"]', 'anguish or (figuratively) affliction grief, pain, sorrow.', 'sometimes מַכְאוֹב; also (feminine Isaiah 53:3) מַכְאֹבָה; from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5337}/H9033/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["to/ deliver/ it"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5927H}/H9033/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ to/ bring up/ it"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7342H}/[H7337]', 'inflected', 'heb', 'רָחָב', '["râchâb"]', '["and/ [the] wide of","and/ broad","and/ extensive","and/ spacious","and/ wide of"]', '["a"]', 'roomy, in any (or every) direction, literally or figuratively broad, large, at liberty, proud, wide.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2100G}/[H2100]', 'lemma', 'heb', 'זוּב', '["zûwb"]', '["[is] flowing","[is] flowing of","flowing of"]', '["v"]', 'to flow freely (as water), i.e. (specifically) to have a (sexual) flux; figuratively, to waste away; also to overflow flow, gush out, have a (running) issue, pine away, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2461}/[H2459]', 'lemma', 'heb', 'חָלָב', '["châlâb"]', '["[the] milk of","milk"]', '["n-m"]', 'milk (as the richness of kine) cheese, milk, sucking.', 'from the same as 2459;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1706>', 'inflected', 'heb', 'ודבש', '["u./de.Vash"]', '["and/ honey"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2850}/[H2845]', 'inflected', 'heb', 'חִתִּי', '["Chittîy"]', '["and/ the/ Hittite[s]"]', '["n-m"]', 'a Chittite, or descendant of Cheth Hittite, Hittities.', 'patronymically from 2845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0567}/[H559]', 'inflected', 'heb', 'אֱמֹרִי', '["ʼĔmôrîy"]', '["and/ the/ Amorite[s]"]', '["n-m"]', 'an Emorite, one of the Canaanitish tribes Amorite.', 'probably a patronymic from an unused name derived from 559 in the sense of publicity, i.e. prominence; thus, a mountaineer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2340}/[H2333]', 'inflected', 'heb', 'חִוִּי', '["Chivvîy"]', '["and/ the/ Hivite[s]"]', '["n-m"]', 'a Chivvite, one of the aboriginal tribes of Palestine Hivite.', 'perhaps from 2333; a villager;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2983G}/[H2982]', 'inflected', 'heb', 'יְבוּסִי', '["Yᵉbûwçîy"]', '["and/ the/ Jebusite[s]"]', '["n-m"]', 'a Jebusite or inhabitant of Jebus Jebusite(-s).', 'patrial from 2982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3906}/[H3905]', 'inflected', 'heb', 'לַחַץ', '["lachats"]', '["the/ oppression"]', '["n-m"]', 'distress affliction, oppression.', 'from 3905;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3905}/[H3905]', 'lemma', 'heb', 'לָחַץ', '["lâchats"]', '["[are] oppressing","he had oppressed","he oppressed","oppressors","they oppressed","you must oppress"]', '["v"]', 'properly, to press, i.e. (figuratively) to distress afflict, crush, force, hold fast, oppress(-or), thrust self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6547J}/[H6547]', 'lemma', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3318H}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ [were] brought out","and/ bring out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0226G}/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["[will be] the/ sign","the/ sign","the/ signs"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971G}/H9031/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["I had sent/ you","I sent/ you","I will let go/ you","I will send/ you","[am] about to cast out/ you","[am] sending/ you","have I sent/ you","he has sent away/ you","he has sent/ you","he sent/ you","he will send/ you","they will send away/ you"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3318H}/H9041/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ bringing out/ you"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647H}/H9013/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["will you serve/ !","you will serve/ !"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2143}/H9020/[H2142]', 'inflected', 'heb', 'זֵכֶר', '["zêker"]', '["[is] memorial/ my"]', '["n-m"]', 'a memento, abstractly recollection (rarely if ever); by implication, commemoration memorial, memory, remembrance, scent.', 'or זֶכֶר; from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1755}/[H1752]', 'lemma', 'heb', 'דּוֹר', '["dôwr"]', '["[are] a generation of","[is] [the] generation of","[the] generation of","[the] generations of","a generation","generation","generation of","generation[s]","generations","generations of"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6213A}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["<the>/ [one who] does","that/ was used","the/ [one who] does","the/ [thing] done","the/ worker","which/ had done","who/ did","who/ do [them]","who/ were doing","who/ were working on"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6040}/[H6031]', 'inflected', 'heb', 'עֳנִי', '["ʻŏnîy"]', '["from/ [the] affliction of","from/ affliction","more than/ affliction"]', '["n-m"]', 'depression, i.e. misery afflicted(-ion), trouble.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6963A>/H9021', 'inflected', 'heb', 'לקלך', '["le./ko.Le./cha"]', '["to/ voice/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2205G}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["and/ [the] elders of","and/ elder","and/ elders"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2076}/[H2076]', 'inflected', 'heb', 'זָבַח', '["zâbach"]', '["and/ I will sacrifice","and/ [one who] sacrifices","and/ [who] sacrificed","and/ let them sacrifice","and/ let us sacrifice","so/ they may sacrifice"]', '["v"]', 'to slaughter an animal (usually in sacrifice) kill, offer, (do) sacrifice, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9025/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ our","O God/ our","[are] God/ our","[is] God/ our","god/ our"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414K}/[H5414]', 'lemma', 'heb', 'נָתַן', '["nâthan"]', '["I have permitted","[surely] permitting","he had permitted","he has permitted","he permit","he permitted","he will permit","she permitted","they permit","they permitted","will he give","you permit","you permitted","you will give","you will permit"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2389}/[H2388]', 'lemma', 'heb', 'חָזָק', '["châzâq"]', '["[am] strong","[are] hard of","[is] mighty","[is] strong","[one too] strong","[the] strong","[was] severe","[were too] strong","a mighty [one]","hard","mighty","severe","strong"]', '["a"]', 'strong (usu. in a bad sense, hard, bold, violent) harder, hottest, impudent, loud, mighty, sore, stiff(-hearted), strong(-er).', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6381}/H9020/[H6381]', 'inflected', 'heb', 'פָּלָא', '["pâlâʼ"]', '["wonders/ my"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980G}/H9013/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["they go about/ !","you will go/ !"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7934}/H9024/[H7931]', 'inflected', 'heb', 'שָׁכֵן', '["shâkên"]', '["from/ [female] neighbor/ her"]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1481A}/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["and/ from/ [the] [female] sojourner of"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9024/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["home/ its","house/ her","own house/ her"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8071}/[H5566]', 'inflected', 'heb', 'שִׂמְלָה', '["simlâh"]', '["and/ cloak","and/ clothes","and/ clothing"]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121A}/H9026/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["children/ your","sons/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2005}/[H2005]', 'inflected', 'heb', 'הֵן', '["hên"]', '["and/ here!"]', '["prt"]', 'lo!; also (as expressing surprise) if behold, if, lo, though.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4100}/H9014/{H2088}/[H4100]', 'inflected', 'heb', 'מָה', '["mâh"]', '["what/ /[is] this?"]', '["i"]', 'properly, interrogative what? (including how? why? when?); but also exclamation, what! (including how!), or indefinitely what (including whatever, and even relatively, that which); often used with prefixes in various adverbial or conjunctive senses how (long, oft, (-soever)), (no-) thing, what (end, good, purpose, thing), whereby(-fore, -in, -to, -with), (for) why.', 'or מַה; or מָ; or מַ; also מֶה; a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4294G}/[H5186]', 'lemma', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["O tribe","[the] rod of","[the] staff of","a rod","a staff","a staff of","rods"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7993}/H9033/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["and/ I threw/ it","and/ he threw/ it","and/ it has cast/ him","and/ it threw/ it","and/ you will throw/ it"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5175}/[H5172]', 'inflected', 'heb', 'נָחָשׁ', '["nâchâsh"]', '["<into>/ a snake","into/ a snake"]', '["n-m"]', 'a snake (from its hiss) serpent.', 'from 5172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440G}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ before/ him","from/ before/ it"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2180}/H9023/[H2179]', 'inflected', 'heb', 'זָנָב', '["zânâb"]', '["on/ tail/ its"]', '["n-m"]', 'the tail (literally or figuratively) tail.', 'from 2179 (in the original sense of flapping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4294G}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["<into>/ a staff","to/ a rod of"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3709G}/H9023/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["[is] in/ hand/ his","in/ hand/ his","in/ palm/ his"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2436H>/H9021', 'inflected', 'heb', 'בחיקך', '["be./chei.Ke./cha"]', '["in/ bosom/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2436H>/H9023', 'inflected', 'heb', 'בחיקו', '["be./chei.K/o"]', '["in/ bosom/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318H}/H9034/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ he brought out/ it"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6879}/[H6879]', 'lemma', 'heb', 'צָרַע', '["tsâraʻ"]', '["[is] having a serious skin disease","[one who] has a skin disease","[people] having a skin disease","[was] leprous","[who] has a serious skin disease","having a skin disease","leprous"]', '["v"]', 'to scourge, i.e. (intransitive and figurative) to be stricken with leprosy leper, leprous.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7950}/[H7949]', 'inflected', 'heb', 'שֶׁלֶג', '["sheleg"]', '["like <the>/ snow"]', '["n-m"]', 'snow (probably from its whiteness) snow(-y).', 'from 7949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2436H>/H9021', 'opaque', 'heb', 'חֵיק', '["chêyq"]', '["bosom/ your"]', '["n-m"]', 'the bosom (literally or figuratively) bosom, bottom, lap, midst, within.', 'or חֵק; and חוֹק; from an unused root, apparently meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2436H>/H9023', 'opaque', 'heb', 'חֵיק', '["chêyq"]', '["bosom/ his"]', '["n-m"]', 'the bosom (literally or figuratively) bosom, bottom, lap, midst, within.', 'or חֵק; and חוֹק; from an unused root, apparently meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2436H>/H9023', 'inflected', 'heb', 'מחיקו', '["me./chei.K/o"]', '["from/ bosom/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1320}/H9023/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["like/ flesh/ his"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6963K>', 'inflected', 'heb', 'לקל', '["le./Kol"]', '["to/ [the] voice of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6963J>', 'inflected', 'heb', 'לקול', '["le./Kol"]', '["<to>/ [the] voice of","to/ [the] sound of","to/ [the] voice of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0314}/[H309]', 'inflected', 'heb', 'אַחֲרוֹן', '["ʼachărôwn"]', '["<the>/ last","<the>/ later","<the>/ latter","<the>/ western","the/ last [lion]","the/ subsequent [people]"]', '["a"]', 'hinder; generally, late or last; specifically (as facing the east) western after (-ward), to come, following, hind(-er, -ermost, -most), last, latter, rereward, ut(ter) most.', 'or (shortened) אַחֲרֹן; from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085G}/H9013/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["they hear/ !","they will hear/ !","they will listen/ !","you will hear/ !","you will listen/ !"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8210G}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["and/ I have poured out","and/ I poured out","and/ I will pour out","and/ he poured out","and/ he will pour out","and/ it was poured out","and/ it will be poured out","and/ they had poured out","and/ they poured [it] out","and/ they shed","and/ they will pour out","and/ you will pour [it] out"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1818}/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["<into>/ blood","and/ blood","for/ blood","for/ blood<s>","into/ blood","to the/ blood","to/ [the] blood of","to/ blood"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3006}/[H3004]', 'inflected', 'heb', 'יַבֶּשֶׁת', '["yabbesheth"]', '["on the/ dry ground"]', '["n-f"]', 'dry ground dry land.', 'a variation of 3004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697H}/[H1696]', 'lemma', 'heb', 'דָּבָר', '["dâbâr"]', '["[the] word of","[the] words of","a matter","a word","word","words"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8543}/[H865]', 'inflected', 'heb', 'תְּמוֹל', '["tᵉmôwl"]', '["from/ yesterday"]', '["adv"]', 'properly, ago, i.e. a (short or long) time since; especially yesterday, or day before yesterday before (-time), these (three) days, heretofore, time past, yesterday.', 'or תְּמֹל; probably for 865; sometimes with 8032');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8032}/[H8028]', 'inflected', 'heb', 'שִׁלְשׁוֹם', '["shilshôwm"]', '["from/ three days ago"]', '["adv"]', 'trebly, i.e. (in time) day before yesterday before (that time, -time), excellent things (from the margin), heretofore, three days, time past.', 'or שִׁלְשֹׁם; from the same as 8028;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1696G}/H9041/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["speaking/ you"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956G}/[H3960]', 'lemma', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["O tongue","[the] tongue","[the] tongue of","a tongue","a tongue of","tongue","tongues"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0120G}/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["[belong] to/ a person","[belongs] to <the>/ humankind","[belongs] to <the>/ person","[is] for/ a human person","for <the>/ person","for/ humankind","of <the>/ person","to <the>/ humankind","to <the>/ person","to the/ person","to/ a person","to/ anyone","to/ humankind"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0483}/[H481]', 'lemma', 'heb', 'אִלֵּם', '["ʼillêm"]', '["a dumb [person]","dumb"]', '["a"]', 'speechless dumb (man).', 'from 481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2795}/[H2790]', 'lemma', 'heb', 'חֵרֵשׁ', '["chêrêsh"]', '["a deaf [person]","deaf","deaf [people]"]', '["a"]', 'deaf (whether literally or spiritual) deaf.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6493}/[H6491]', 'lemma', 'heb', 'פִּקֵּחַ', '["piqqêach"]', '["clear-sighted [people]","seeing"]', '["a"]', 'clear-sighted; figuratively, intelligent seeing, wise.', 'from 6491;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5787}/[H5786]', 'lemma', 'heb', 'עִוֵּר', '["ʻivvêr"]', '["[are] blind","[is] blind","[the] blind","a blind [animal]","a blind [person]","blind","blind [people]"]', '["a"]', 'blind (literally or figuratively) blind (men, people).', 'intensive from 5786;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310G}/H9021/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["[is] mouth/ your","mouth/ your","own mouth/ your"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3384B}/H9031/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["and/ I will teach/ you"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4872}/[H4871]', 'inflected', 'heb', 'מֹשֶׁה', '["Môsheh"]', '["against/ Moses","by/ Moses","on/ Moses"]', '["n-pr-m"]', 'Mosheh, the Israelite lawgiver Moses.', 'from 4871; drawing out (of the water), i.e. rescued;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0175>', 'opaque', 'heb', 'אַהֲרוֹן', '["ʼAhărôwn"]', '["Aaron","[is] Aaron"]', '["n-pr-m"]', 'Aharon, the brother of Moses Aaron.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3881}/[H3878]', 'inflected', 'heb', 'לֵוִיִּי', '["Lêvîyîy"]', '["<the>/ Levite","O/ Levites","[were] the/ Levites","the/ Levite","the/ Levite[s]","the/ Levites"]', '["a"]', 'a Levite or descendant of Levi Leviite.', 'or לֵוִי; patronymically from 3878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200G}/H9031/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ he will see/ you"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8055}/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["and/ he has caused to rejoice","and/ he rejoiced","and/ he was glad","and/ he was pleased","and/ he will be glad","and/ he will cause to rejoice","and/ it rejoiced","and/ it will be glad","and/ they rejoiced","and/ they were glad","and/ they will be glad","and/ they will rejoice","and/ you rejoiced","and/ you will rejoice"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310G}/H9023/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["mouth/ his","mouth/ its"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3384B}/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["and/ I will teach"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213A}/H9013/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["are you doing/ !","may they do/ !","they did/ !","they will do/ !","you must do/ !","you will do/ !"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4294G}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["the/ rod","the/ rods","the/ staff"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0226G}\/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["the/ signs"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3500L}/[H3499]', 'lemma', 'heb', 'יֶתֶר', '["Yether"]', '["Jethro"]', '["n-pr-m"]', 'Jether, the name of five or six Israelites and of one Midianite Jether, Jethro. Compare 3503.', 'the same as 3499;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5750}/H9048/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["¿/ [are] still/ they"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4080H}/[H4079]', 'inflected', 'heb', 'מִדְיָן', '["Midyân"]', '["against/ Midian","in/ Midian","on/ Midian"]', '["n-pr-m n-pr-loc"]', 'Midjan, a son of Abraham; also his country and (collectively) his descendants Midian, Midianite.', 'the same as 4079;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1245}/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["who/ are seeking","who/ sought"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7392}/H9038/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["and/ he made ride/ them"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1980G}/H9041/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["by/ going/ you","when/ going/ you"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725G}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["<to>/ turn back","by/ bringing back","by/ turning back","to/ bring back","to/ return","to/ turn","to/ turn back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4159}/[H3302]', 'inflected', 'heb', 'מוֹפֵת', '["môwphêth"]', '["[is] the/ sign","the/ sign","the/ wonders"]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6213A}/H9038/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ you will do/ them"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5647H}/H9030/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["so/ he may serve/ me","so/ they may serve/ me"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7971H}/H9033/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["to/ let go/ him"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6298}/H9033/[H6298]', 'inflected', 'heb', 'פָּגַשׁ', '["pâgash"]', '["and/ he met/ him"]', '["v"]', 'to come in contact with, whether by accident or violence; figuratively, to concur meet (with, together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9033/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["did they put to death/ him","he will put to death/ him","it kills/ him","putting to death/ him","she killed/ him","to kill/ him","to put to death/ him","you kill/ him","you must kill/ him"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6864}/[H6696]', 'lemma', 'heb', 'צֹר', '["tsôr"]', '["a flint"]', '["n-m"]', 'a stone (as if pressed hard or to a point); (by implication, of use) a knife flint, sharp stone.', 'from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3772G}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ I will cut down","and/ I will cut off","and/ he cut down","and/ he cut off","and/ he will cut off","and/ she cut off","and/ they cut down","and/ they cut off","and/ they will cut down","and/ you will cut down"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7272}/H9023/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["<to>/ feet/ his","<to>/ feet/ its","to/ feet/ his","to/ foot/ his"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7503}/[H7503]', 'inflected', 'heb', 'רָפָה', '["râphâh"]', '["and/ he withdrew","and/ they dropped","and/ they hung limp","and/ they will hang limp"]', '["v"]', 'to slacken (in many applications, literal or figurative) abate, cease, consume, draw (toward evening), fail, (be) faint, be (wax) feeble, forsake, idle, leave, let alone (go, down), (be) slack, stay, be still, be slothful, (be) weak(-en). See 7495.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4139}\/[H4135]', 'inflected', 'heb', 'מוּלָה', '["mûwlâh"]', '["to the/ circumcision"]', '["n-f"]', 'circumcision circumcision.', 'from 4135;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4057B}/H9011/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["the/ wilderness/ towards"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0175>', 'inflected', 'heb', 'לאהרן', '["le./''a.ha.Ron"]', '["<to>/ Aaron","[belong] to/ Aaron","[belongs] to/ Aaron","for/ Aaron","of/ Aaron","to/ Aaron"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971G}/H9033/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["I sent/ him","I sent/ it","did you send away/ him","he had sent away/ him","he had sent/ him","he has sent/ him","he has sent/ it","he sent/ him","he will send forth/ him","they sent away/ him","will we send/ it"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0175>', 'inflected', 'heb', 'ואהרן', '["ve./''a.ha.Ron"]', '["and/ Aaron"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6040}/H9028/[H6031]', 'inflected', 'heb', 'עֳנִי', '["ʻŏnîy"]', '["affliction/ their"]', '["n-m"]', 'depression, i.e. misery afflicted(-ion), trouble.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2287}/[H2283]', 'inflected', 'heb', 'חָגַג', '["châgag"]', '["and/ celebrating","so/ they may celebrate a festival"]', '["v"]', 'properly, to move in a circle, i.e. (specifically) to march in a sacred procession, to observe a festival; by implication, to be giddy celebrate, dance, (keep, hold) a (solemn) feast (holiday), reel to and fro.', 'a primitive root (compare 2283, 2328);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963A>/H9023', 'inflected', 'heb', 'בקולו', '["be./ko.L/o","be./ko.l/o","ve./ko.L/o"]', '["to/ voice/ his","with/ voice/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7971H}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["by/ letting go","to/ let [them] go","to/ let go"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7122G}/[H7122]', 'lemma', 'heb', 'קָרָא', '["qârâʼ"]', '["he has met"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6293}/H9035/[H6293]', 'inflected', 'heb', 'פָּגַע', '["pâgaʻ"]', '["he should fall on/ us"]', '["v"]', 'to impinge, by accident or violence, or (figuratively) by importunity come (betwixt), cause to entreat, fall (upon), make intercession, intercessor, intreat, lay, light (upon), meet (together), pray, reach, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1698}/[H1696]', 'inflected', 'heb', 'דֶּבֶר', '["deber"]', '["by <the>/ pestilence","by the/ pestilence","by/ a pestilence","by/ pestilence","with <the>/ pestilence"]', '["n-m"]', 'a pestilence murrain, pestilence, plague.', 'from 1696 (in the sense of destroying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2719}/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["by <the>/ sword","by the/ sword","by/ [the] sword","by/ [the] sword of","by/ [the] swords of","by/ a sword","by/ sword","to the/ sword","with <the>/ swords","with the/ sword","with/ [the] sword of","with/ sword"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6544B}/[H6544]', 'lemma', 'heb', 'פָּרַע', '["pâraʻ"]', '["I will refrain","[one who] ignores","[was] running wild","are you causing to refrain","he had allowed lack of restraint","he will let loose","it is let loose","let loose","you let loose","you neglect [it]"]', '["v"]', 'to loosen; by implication, to expose, dismiss; figuratively, absolve, begin avenge, avoid, bare, go back, let, (make) naked, set at nought, perish, refuse, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4639G}/H9023/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["from/ work<s>/ its"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5450}/H9026/[H5447]', 'inflected', 'heb', 'סְבָלָה', '["çᵉbâlâh"]', '["to/ forced labor/ your"]', '["n-f"]', 'porterage burden.', 'from 5447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5450}/H9028/[H5447]', 'inflected', 'heb', 'סְבָלָה', '["çᵉbâlâh"]', '["from/ forced labor/ their"]', '["n-f"]', 'porterage burden.', 'from 5447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5065}/[H5065]', 'inflected', 'heb', 'נָגַשׂ', '["nâgas"]', '["the/ [one who] oppresses","the/ taskmasters"]', '["v"]', 'to drive (an animal, a workman, a debtor, an army); by implication, to tax, harass, tyrannize distress, driver, exact(-or), oppress(-or), × raiser of taxes, taskmaster.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5971A}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["<in> the/ people","<on> the/ people","among the/ people","among the/ peoples","among/ a people","on the/ people","over the/ people","with/ [the] peoples of"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7860>/H9023', 'opaque', 'heb', 'שֹׁטֵר', '["shôṭêr"]', '["foremen/ its"]', '["n-m"]', 'properly, a scribe, i.e. (by analogy or implication) an official superintendent or magistrate officer, overseer, ruler.', 'active participle of an otherwise unused root probably meaning to write;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3835B}/[H3843]', 'inflected', 'heb', 'לָבַן', '["lâban"]', '["by/ making bricks","to/ make bricks"]', '["v"]', 'to be (or become) white; to make bricks make brick, be (made, make) white(-r).', 'a primitive root; also as denominative from 3843');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7197A}/[H7179]', 'inflected', 'heb', 'קָשַׁשׁ', '["qâshash"]', '["and/ they may gather"]', '["v"]', 'to forage for straw, stubble or wood; figuratively, to assemble gather (selves) (together).', 'a primitive root; to become sapless through drought; used only as denominative from 7179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4971}/[H8505]', 'lemma', 'heb', 'מַתְכֹנֶת', '["mathkôneth"]', '["[the] measurement of"]', '["n-f"]', 'proportion (in size, number or ingredients) composition, measure, state, tale.', 'or מַתְכֻנֶת; from 8505 in the transferred sense of measuring;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8543}/[H865]', 'lemma', 'heb', 'תְּמוֹל', '["tᵉmôwl"]', '["[are] yesterday","[was] yesterday","yesterday"]', '["adv"]', 'properly, ago, i.e. a (short or long) time since; especially yesterday, or day before yesterday before (-time), these (three) days, heretofore, time past, yesterday.', 'or תְּמֹל; probably for 865; sometimes with 8032');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1639}/[H1639]', 'lemma', 'heb', 'גָּרַע', '["gâraʻ"]', '["I will shave [you]","[is] diminished","[will be] clipped","are we restrained","he draws up","he will reduce","he withdraws","it will be withdrawn","will it be withdrawn","you hold back","you must diminish","you will diminish"]', '["v"]', 'to scrape off; by implication, to shave, remove, lessen, withhold abate, clip, (di-) minish, do (take) away, keep back, restrain, make small, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7503}/[H7503]', 'lemma', 'heb', 'רָפָה', '["râphâh"]', '["[are] idle","[be] showing yourself slack","[is] making drop","[one who] shows himself idle","[were] making slack","be quiet","he loosens","idle","it is sinking","it relaxed","it sinks down","it will be disheartened","let drop","refrain","they drop","they hung limp","they let drop","they will drop","you abandon","you have shown yourself without courage","you let drop","you let go"]', '["v"]', 'to slacken (in many applications, literal or figurative) abate, cease, consume, draw (toward evening), fail, (be) faint, be (wax) feeble, forsake, idle, leave, let alone (go, down), (be) slack, stay, be still, be slothful, (be) weak(-en). See 7495.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2076}/[H2076]', 'lemma', 'heb', 'זָבַח', '["zâbach"]', '["I have sacrificed","I will sacrifice","[am] sacrificing","[are] sacrificing","[have been] sacrificing","[is] sacrificing","[one who] sacrifices","[those who] offer sacrifice of","[those who] sacrifice","[was] sacrificing","[were] sacrificing","[who] sacrifice","[who] was sacrificing","he sacrificed","he sacrifices","let us sacrifice","sacrifice","sacrificing","they have sacrificed","they sacrifice","they sacrificed","they will sacrifice","to sacrifice [them]","we will sacrifice","you must sacrifice","you slaughter","you will sacrifice","you will sacrifice [it]","you will slaughter"]', '["v"]', 'to slaughter an animal (usually in sacrifice) kill, offer, (do) sacrifice, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0430G}/H9025/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["for/ God/ our","of/ God/ our","to/ God/ our"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5656I}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["the/ labor","the/ service"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1697G}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<in> the/ word","<in> the/ words","<in>/ [the] word of","at/ [the] word of","at/ [the] words of","by the/ words","by/ [the] word of","by/ [the] words of","by/ words","in the/ words","to/ words of","with/ [the] words of","with/ a word"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8267}/[H8266]', 'lemma', 'heb', 'שֶׁקֶר', '["sheqer"]', '["<of> falsehood","[are] falsehood","[is] a vain hope","[is] deception","[is] falsehood","a lie","deception","falsehood","falsehood of","lies"]', '["n-m"]', 'an untruth; by implication, a sham (often adverbial) without a cause, deceit(-ful), false(-hood, -ly), feignedly, liar, lie, lying, vain (thing), wrongfully.', 'from 8266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5065}/[H5065]', 'lemma', 'heb', 'נָגַשׂ', '["nâgas"]', '["[the] oppressor","[the] taskmasters of","a driver","a taskmaster","an oppressor","he exacted","he was hard pressed","he was oppressed","he will press","it was hard pressed","ruler","you drive hard","you will press"]', '["v"]', 'to drive (an animal, a workman, a debtor, an army); by implication, to tax, harass, tyrannize distress, driver, exact(-or), oppress(-or), × raiser of taxes, taskmaster.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7860>/H9023', 'inflected', 'heb', 'ושטריו', '["ve./Sho.te.Ra/v","ve./sho.te.Ra/v"]', '["and/ foremen/ its","and/ officials/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0369}/H9040/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["not/ I"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0834C}/[H834]', 'inflected', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["<from>/ because","from/ [that] which","from/ [the one] who","from/ [the things] which","from/ [those] who","from/ that","from/ where","more than/ [those] who","more than/ [those] whom","more than/ that","some of/ [that] which"]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5656I}/H9026/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["from/ labor/ your"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7197A}/[H7179]', 'inflected', 'heb', 'קָשַׁשׁ', '["qâshash"]', '["to/ gather"]', '["v"]', 'to forage for straw, stubble or wood; figuratively, to assemble gather (selves) (together).', 'a primitive root; to become sapless through drought; used only as denominative from 7179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7179}/[H7197]', 'lemma', 'heb', 'קַשׁ', '["qash"]', '["chaff","stubble"]', '["n-m"]', 'straw (as dry) stubble.', 'from 7197;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8401}/[H1129]', 'inflected', 'heb', 'תֶּבֶן', '["teben"]', '["[belongs] to the/ straw","for the/ straw","to/ straw"]', '["n-m"]', 'properly, material, i.e. (specifically) refuse haum or stalks of grain (as chopped in threshing and used for fodder) chaff, straw, stubble.', 'probably from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5065}/[H5065]', 'inflected', 'heb', 'נָגַשׂ', '["nâgas"]', '["and/ the/ taskmasters"]', '["v"]', 'to drive (an animal, a workman, a debtor, an army); by implication, to tax, harass, tyrannize distress, driver, exact(-or), oppress(-or), × raiser of taxes, taskmaster.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0213}/[H213]', 'lemma', 'heb', 'אוּץ', '["ʼûwts"]', '["I have hastened","[were] pressing [them]","hasty","hasty [person]","it hastened","it is narrow","you insist"]', '["v"]', 'to press; (by implication) to be close, hurry, withdraw (make) haste(-n, -y), labor, be narrow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1961}/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["when/ are","when/ belong","when/ belongs","when/ came","when/ is","when/ was"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8401}/[H1129]', 'inflected', 'heb', 'תֶּבֶן', '["teben"]', '["the/ straw"]', '["n-m"]', 'properly, material, i.e. (specifically) refuse haum or stalks of grain (as chopped in threshing and used for fodder) chaff, straw, stubble.', 'probably from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7860>', 'opaque', 'heb', 'שֹׁטֵר', '["shôṭêr"]', '["[the] foremen of","[the] officers of","icer"]', '["n-m"]', 'properly, a scribe, i.e. (by analogy or implication) an official superintendent or magistrate officer, overseer, ruler.', 'active participle of an otherwise unused root probably meaning to write;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760L}/[H7760]', 'lemma', 'heb', 'שׂוּם', '["sûwm"]', '["he appointed","he had appointed","indeed <appoint>","let me appoint","they had appointed","you will appoint"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706G}/H9026/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["prescribed portion/ your"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3843}/[H3835]', 'inflected', 'heb', 'לְבֵנָה', '["lᵉbênâh"]', '["and/ bricks"]', '["n-f"]', 'a brick (from the whiteness of the clay) (altar of) brick, tile.', 'from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2398}/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["and/ [you have] sinned","and/ a sinner","and/ you have sinned"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971A}/H9021/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["[are] people/ your","[is] people/ your","people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8401}/[H1129]', 'inflected', 'heb', 'תֶּבֶן', '["teben"]', '["and/ straw"]', '["n-m"]', 'properly, material, i.e. (specifically) refuse haum or stalks of grain (as chopped in threshing and used for fodder) chaff, straw, stubble.', 'probably from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8506}/[H8505]', 'inflected', 'heb', 'תֹּכֶן', '["tôken"]', '["and/ [the] measurement of"]', '["n-m"]', 'a fixed quantity measure, tale.', 'from 8505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3843}/H9026/[H3835]', 'inflected', 'heb', 'לְבֵנָה', '["lᵉbênâh"]', '["from/ bricks/ your"]', '["n-f"]', 'a brick (from the whiteness of the clay) (altar of) brick, tile.', 'from 3835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3318G}/H9048/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ came out/ they","when/ went out/ they"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9036/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["[be] on/ you","[is] on/ you","[will be] over/ you","on <the>/ yourselves","on/ you","on/ yourselves","over/ you","to/ you","towards/ you"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0887}/[H887]', 'lemma', 'heb', 'בָּאַשׁ', '["bâʼash"]', '["certainly <to become odious>","he acts odiously","he has become odious","it causes to stink","it has made itself odious","it stank","it will stink","they had made themselves odious","they stink","you have made stink","you have made yourself odious"]', '["v"]', 'to smell bad; figuratively, to be offensive morally (make to) be abhorred (had in abomination, loathsome, odious), (cause a, make to) stink(-ing savour), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7381}/H9025/[H7306]', 'inflected', 'heb', 'רֵיחַ', '["rêyach"]', '["odor/ our"]', '["n-m"]', 'odor (as if blown) savour, scent, smell.', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5414H}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["to/ distribute","to/ give","to/ put","to/ put [it]","to/ set"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027G}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["<in>/ hands/ their","[be] in/ hand/ their","[is] in/ hands/ their","[is] in/ own hand/ their","[were] in/ hand/ their","by/ hand/ their","in/ hand/ their","on/ hand/ their","with/ hand/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2026}/H9035/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["to/ kill/ us"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0227B}/[H227]', 'inflected', 'heb', 'אָז', '["ʼâz"]', '["and/ from/ then"]', '["adv"]', 'at that time or place; also as a conjunction, therefore beginning, for, from, hitherto, now, of old, once, since, then, at which time, yet.', 'a demonstrative adverb;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8034}/H9021/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["at/ name/ your","by/ name/ your","in/ name/ your","in/ own name/ your","on/ name/ your"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5337}/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ certainly <to deliver>","and/ certainly <to rescue>","and/ deliver","and/ deliver yourself","so/ may he deliver"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6547J}/[H6547]', 'inflected', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["for/ Pharaoh","of/ Pharaoh","to/ Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971G}/H9038/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["I sent/ them","he has sent/ them","he sent away/ them","he will let go/ them","you will send away/ them","you will send/ them"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3027H}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ by/ [the] hand of","and/ by/ a hand","and/ in/ [the] hand of","and/ with/ a hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1644G}/H9038/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["he will drive out/ them"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0776G>/H9023\', 'inflected', 'heb', 'מארצו ס', '["me./''ar.Tz/o"]', '["from/ land/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0410G}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["<in>/ God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8034}/H9020/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["and/ name/ my"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5009}/[H5008]', 'lemma', 'heb', 'נְאָקָה', '["nᵉʼâqâh"]', '["[the] groaning of","[the] groans of"]', '["n-f"]', 'a groan groaning.', 'from 5008;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5450}/[H5447]', 'lemma', 'heb', 'סְבָלָה', '["çᵉbâlâh"]', '["[the] forced labor of"]', '["n-f"]', 'porterage burden.', 'from 5447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5656G}/H9028/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["from/ labor/ their"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1350A}/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["and/ I will redeem","and/ he will redeem","and/ he will redeem himself"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2220}/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["by/ an arm","with/ [the] arm of"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8201}/[H8199]', 'inflected', 'heb', 'שֶׁפֶט', '["shepheṭ"]', '["and/ with/ acts of judgment"]', '["n-m"]', 'a sentence, i.e. infliction judgment.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3318H}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["<the>/ about to be led out","[were] the/ [one who] led out","the/ [one who] brings out","the/ [one who] led out","who/ brought out","who/ sent out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375P}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["I had lifted up","I lift up","I lifted up","I will lift up","lift up","they will bear","you had lifted"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027S}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ my","hands/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4181}/[H4180]', 'lemma', 'heb', 'מוֹרָשָׁה', '["môwrâshâh"]', '["a possession"]', '["n-f"]', 'a possession heritage, inheritance, possession.', 'feminine of 4180;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7115}/[H7114]', 'inflected', 'heb', 'קֹצֶר', '["qôtser"]', '["from/ shortness of"]', '["n-m"]', 'shortness (of spirit), i.e. impatience anguish.', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5656G}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["and/ from/ labor"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7186}\/[H7185]', 'inflected', 'heb', 'קָשֶׁה', '["qâsheh"]', '["hard"]', '["a"]', 'severe (in various applications) churlish, cruel, grievous, hard((-hearted), thing), heavy, impudent, obstinate, prevailed, rough(-ly), sore, sorrowful, stiff(necked), stubborn, in trouble.', 'from 7185;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7971H}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ I will let go","and/ to let go","so/ he may let go","so/ they may send away"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
