INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6189}/[H6188]', 'lemma', 'heb', 'עָרֵל', '["ʻârêl"]', '["[am] uncircumcised of","[are] uncircumcised","[are] uncircumcised of","[is] uncircumcised","an uncircumcised [man]","uncircumcised","uncircumcised [man]","uncircumcised [men]","uncircumcised of"]', '["a"]', 'properly, exposed, i.e. projecting loose (as to the prepuce); used only technically, uncircumcised (i.e. still having the prepuce uncurtailed) uncircumcised (person).', 'from 6188;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193G}\/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["lips"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6680}/H9038/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["and/ he commanded/ them"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3318H}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["to/ bring [it] out","to/ bring forth","to/ bring out","to/ send out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218H>', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["O chiefs of","[are] [the] chiefs of","[are] [the] heads of","[are] [the] leaders of","[as] chief","[is the] head","[is] [the] head of","[the] chief","[the] chief of","[the] chiefs of","[the] head of","[the] heads of","[the] leader of","[the] leaders of","[was] [the] chief","[was] [the] chief of","[was] [the] head of","[was] a leader of","[was] chief","[were the] chiefs of","[were] [the] chiefs of","[were] [the] heads of","[were] [the] leaders of","[were] chiefs of","[who were] [the] heads of","a chief","a leader","chief","chief[s]","chiefs","chiefs of","heads","heads of","leader[s]","leaders","leaders of"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
