INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5030}/H9021/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["prophet/ your","prophets/ your"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971H}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ I will set free","and/ he sent","and/ he sent [them]","and/ he sent away","and/ he stretched out","and/ he will let go","and/ they let [them] go","and/ you have let go"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0226G}/H9020/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["signs/ my"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4159}/H9020/[H3302]', 'inflected', 'heb', 'מוֹפֵת', '["môwphêth"]', '["wonders/ my"]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635A}/H9020/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["hosts/ my"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8201}/[H8199]', 'inflected', 'heb', 'שֶׁפֶט', '["shepheṭ"]', '["with/ acts of judgment"]', '["n-m"]', 'a sentence, i.e. infliction judgment.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5186}/H9040/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["when/ stretch out/ I"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H8432>/H9028', 'inflected', 'heb', 'מתוכם', '["mi./to.Kha/m"]', '["from/ among/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4159}/[H3302]', 'lemma', 'heb', 'מוֹפֵת', '["môwphêth"]', '["a sign","a wonder","sign"]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4294G}/H9021/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["staff/ your"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7993}/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["and/ he threw [it]","and/ he will shed","and/ he will throw [it]","and/ it will throw down","and/ let us throw","and/ people will throw out","and/ throw [it]","and/ throw [it] away","so/ you may cast"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8577M}/[H8565]', 'inflected', 'heb', 'תַּנִּין', '["tannîyn"]', '["<into>/ a serpent","<into>/ serpents"]', '["n-m"]', 'a marine or land monster, i.e. sea-serpent or jackal dragon, sea-monster, serpent, whale.', 'or תַּנִּים; (Ezekiel 29:3), intensive from the same as 8565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4294G}/H9023/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["rod/ his","staff/ his"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6440G}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ <to>/ before","and/ [is] <to>/ before","and/ [was] <to>/ before"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2450}/[H2449]', 'inflected', 'heb', 'חָכָם', '["châkâm"]', '["<to> the/ wise men","<to>/ a wise [person]","[belong] to/ wise [people]","[belongs] to <the>/ wise [people]","[belongs] to the/ wise person","of the/ wise man","of/ [the] wise of","to <the>/ wise men","to the/ wise [person]","to/ [the] wise of","to/ a wise [person]"]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3784}/[H3784]', 'inflected', 'heb', 'כָּשַׁף', '["kâshaph"]', '["and/ <to> the/ sorcerers"]', '["v"]', 'properly, to whisper a spell, i.e. to inchant or practise magic sorcerer, (use) witch(-craft).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3814}/H9028/[H3813]', 'inflected', 'heb', 'לָאט', '["lâʼṭ"]', '["by/ enchantments/ their"]', '["n-m"]', 'properly, muffled, i.e. silently softly.', 'from 3813 (or perhaps for active participle of 3874);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4294G}/H9028/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["rods/ their","staffs/ their"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3985}/[H3985]', 'lemma', 'heb', 'מָאֵן', '["mâʼên"]', '["absolutely <refuse>","have you refused","he has refused","he refused","he will refuse","it has refused","it refused","it refuses","she has refused","they have refused","they refuse","they refused","they will refuse","you refused","you will refuse"]', '["v"]', 'to refuse refuse, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4325G}/H9011/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["the/ water/ towards"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2015}/[H2015]', 'lemma', 'heb', 'הָפַךְ', '["hâphak"]', '["I overthrew","I will restore","[is] about to be overturned","[is] turning every way","[someone] overthrows","[was] tumbling","have you changed yourself","he overthrew","he overturns","he turned","it has been changed","it has been overturned","it has been turned","it has been turned over","it has turned","it is changed","it is turned over","it turned back","it was changed","it will be turned over","they are changed","they changed","they have turned","they turned","they turned back","turn around","turned over","you change yourself","you have changed","you have turned","you turned","you will turn yourself"]', '["v"]', 'to turn about or over; by implication, to change, overturn, return, pervert × become, change, come, be converted, give, make (a bed), overthrow (-turn), perverse, retire, tumble, turn (again, aside, back, to the contrary, every way).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4294G}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["<in> the/ staff","with the/ staff"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2975G}/[H2975]', 'inflected', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["[is] in the/ River","[was] in the/ River","in the/ River"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1710}/[H1709]', 'inflected', 'heb', 'דָּגָה', '["dâgâh"]', '["and/ the/ fish"]', '["n-f"]', 'fish.', 'feminine of 1709, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0887}/[H887]', 'inflected', 'heb', 'בָּאַשׁ', '["bâʼash"]', '["and/ it stank","and/ it will stink"]', '["v"]', 'to smell bad; figuratively, to be offensive morally (make to) be abhorred (had in abomination, loathsome, odious), (cause a, make to) stink(-ing savour), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2975G}\/[H2975]', 'inflected', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["the/ River"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5186}/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["and/ I incline","and/ [those who] thrust aside","and/ he may stretch out","and/ incline","and/ stretch out","and/ turn"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5104H}/H9028/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["rivers/ their"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2975G}/H9028/[H2975]', 'inflected', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["canals/ their"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0098>/H9028', 'opaque', 'heb', 'אֲגַם', '["ʼăgam"]', '["ponds/ their"]', '["n-m"]', 'a marsh; hence a rush (as growing in swamps); hence a stockade of reeds pond, pool, standing (water).', 'from an unused root (meaning to collect as water);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4723C}/[H6960]', 'lemma', 'heb', 'מִקְוֶה', '["miqveh"]', '["<the> reservoir of","a reservoir of"]', '["n-pr-m n-m"]', 'something waited for, i.e. confidence (objective or subjective); also a collection, i.e. (of water) a pond, or (of men and horses) a caravan or drove abiding, gathering together, hope, linen yarn, plenty (of water), pool.', 'or מִקְוֵה; (1 Kings 10:28), or מִקְוֵאlemma מִּקְוֵא extra dagesh, corrected to מִקְוֵא; (2 Chronicles 1:16), from 6960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4325G}/H9028/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["water/ their","waters/ their"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6086G}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["and/ in <the>/ wood<s>","and/ in the/ wood<s>","and/ in/ wood<s> of","and/ with/ [the] wood of","and/ with/ wood<s> of"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0068G}/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["and/ in the/ stone<s>","and/ with <the>/ stones","and/ with the/ stone","and/ with/ stone"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5869H}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ to/ [the] eyes of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1818}/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["<the>/ blood","<the>/ blood<s>","[is] the/ blood","the/ blood"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3909}/H9028/[H3814]', 'inflected', 'heb', 'לָט', '["lâṭ"]', '["by/ enchantments/ their"]', '["n-m"]', 'properly, covered, i.e. secret; by implication, incantation; also secrecy or (adverb) covertly enchantment, privily, secretly, softly.', 'a form of 3814 or else participle from 3874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896K}/[H7896]', 'lemma', 'heb', 'שִׁית', '["shîyth"]', '["I set","he set","set","she set","will I set","you set"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439H}/[H5437]', 'lemma', 'heb', 'סָבִיב', '["çâbîyb"]', '["all around","around"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3986}/[H3985]', 'lemma', 'heb', 'מָאֵן', '["mâʼên"]', '["[are] refusing"]', '["a"]', 'unwilling refuse.', 'from 3985;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5062}/[H5062]', 'lemma', 'heb', 'נָגַף', '["nâgaph"]', '["I will strike down","[am] about to strike","[are] defeated","[is] about to strike","[is] defeated","certainly <to defeated>","defeated","he defeated","he will strike","it was defeated","it will be defeated","it will strike","striking","they had been defeated","they were defeated","they will stumble","you should strike","you will be defeated"]', '["v"]', 'to push, gore, defeat, stub (the toe), inflict (a disease) beat, dash, hurt, plague, slay, smite (down), strike, stumble, × surely, put to the worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366H}/H9021/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["territories/ your","territory/ your"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6854}/[H6852]', 'inflected', 'heb', 'צְפַרְדֵּעַ', '["tsᵉphardêaʻ"]', '["with <the>/ frogs"]', '["n-f"]', 'a marsh-leaper, i.e. frog frog.', 'from 6852 and a word elsewhere unused meaning a swamp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6854}/[H6852]', 'lemma', 'heb', 'צְפַרְדֵּעַ', '["tsᵉphardêaʻ"]', '["frogs"]', '["n-f"]', 'a marsh-leaper, i.e. frog frog.', 'from 6852 and a word elsewhere unused meaning a swamp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004B}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[is] in/ house/ your","at/ home/ your","in/ house/ your","on/ house/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2315}/[H2314]', 'inflected', 'heb', 'חֶדֶר', '["cheder"]', '["and/ in/ [the] chamber of","and/ in/ [the] chambers of"]', '["n-m"]', 'an apartment (usually literal) ((bed) inner) chamber, innermost(-ward) part, parlour, south, × within.', 'from 2314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4904}/H9021/[H7901]', 'inflected', 'heb', 'מִשְׁכָּב', '["mishkâb"]', '["bed/ your","lying down/ your"]', '["n-m"]', 'a bed (figuratively, a bier); abstractly, sleep; by euphemism, carnal intercourse bed(-chamber), couch, lieth (lying) with.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4296}/H9021/[H5186]', 'inflected', 'heb', 'מִטָּה', '["miṭṭâh"]', '["bed/ your"]', '["n-f"]', 'a bed (as extended) for sleeping or eating; by analogy, a sofa, litter or bier bed(-chamber), bier.', 'from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1004B}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ in/ [the] house of","and/ in/ houses of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5971A}/H9021/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ on/ people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8574H}/H9021/[H5216]', 'inflected', 'heb', 'תַּנּוּר', '["tannûwr"]', '["and/ in/ ovens/ your"]', '["n-m"]', 'a fire-pot furnace, oven.', 'from 5216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4863}/H9021/[H7604]', 'inflected', 'heb', 'מִשְׁאֶרֶת', '["mishʼereth"]', '["and/ in/ kneading troughs/ your"]', '["n-f"]', 'a kneading-trough (in which the dough rises) kneading trough, store.', 'from 7604 in the original sense of swelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H9031}', 'inflected', 'heb', 'ובכה', '["u./ve./Kha","u./ve./Khah","va./Va/kh"]', '["and/ <in> <the>/ you","and/ against <the>/ you","and/ in <the>/ you","and/ on/ you","and/ over <the>/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6854}/[H6852]', 'inflected', 'heb', 'צְפַרְדֵּעַ', '["tsᵉphardêaʻ"]', '["the/ frog[s]","the/ frogs"]', '["n-f"]', 'a marsh-leaper, i.e. frog frog.', 'from 6852 and a word elsewhere unused meaning a swamp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4294G}/H9021/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["with/ staff/ your"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0098>', 'inflected', 'heb', 'האגמים', '["ha./''a.ga.Mim"]', '["the/ ponds","the/ reed-marshes"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0175>', 'inflected', 'heb', 'ולאהרן', '["u./le./''a.ha.Ron"]', '["and/ <to>/ Aaron"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6279}/[H6281]', 'lemma', 'heb', 'עָתַר', '["ʻâthar"]', '["he prays","pray","will I pray","you will pray"]', '["v"]', 'to burn incense in worship, i.e. intercede (reciprocally, listen to prayer) intreat, (make) pray(-er).', 'a primitive root (rather denominative from 6281);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5493G}/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["and/ I may remove","and/ I will remove","and/ [who] turns aside from","and/ let her remove","and/ let me remove","and/ people may remove","and/ remove","and/ thrust away","so/ may he remove"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5971A}/H9020/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ from/ people/ my"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6286A}/[H6288]', 'lemma', 'heb', 'פָּאַר', '["pâʼar"]', '["I will beautify","I will get glory for myself","he glorifies","honor yourself","it should glorify itself"]', '["v"]', 'to gleam, i.e. (causatively) embellish; figuratively, to boast; also to explain (i.e. make clear) oneself; to shake a tree beautify, boast self, go over the boughs, glorify (self), glory, vaunt self.', 'a primitive root; also denominative from 6288,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H4970>', 'inflected', 'heb', 'למתי', '["le./ma.Tai"]', '["to/ when?"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5650}/H9021/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["and/ [belongs] to/ servants/ your","and/ for/ servants/ your","and/ to/ [male] slave/ your","and/ to/ servants/ your"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5971A}/H9021/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ for/ people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3772I}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["to/ cut off"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1004B}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ from/ houses/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4279}/[H309]', 'inflected', 'heb', 'מָחָר', '["mâchâr"]', '["for/ tomorrow","to/ tomorrow"]', '["n-m"]', 'properly, deferred, i.e. the morrow; usually (adverbially) tomorrow; indefinitely, hereafter time to come, tomorrow.', 'probably from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3068G}/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["[is] like/ Yahweh","like/ Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5493H}/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["and/ he will turn aside","and/ it departed","and/ it will be removed","and/ it will come to an end","and/ it will depart","and/ it will turn aside","and/ they will depart"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5650}/H9021/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["and/ from/ servants/ your"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5971A}/H9021/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ from/ people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2691A}/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["the/ court","the/ courts","the/ courtyard","the/ courtyards","the/ villages"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2563B}/[H2560]', 'lemma', 'heb', 'חֹמֶר', '["chômer"]', '["a heap of","heaps"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7309}/[H7305]', 'inflected', 'heb', 'רְוָחָה', '["rᵉvâchâh"]', '["the/ respite"]', '["n-f"]', 'relief breathing, respite.', 'feminine of 7305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3513H}/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["and/ [one who] makes heavy","and/ he made heavy"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5221}/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["and/ [one who] strikes down","and/ [one who] will strike","and/ he struck down","and/ it may strike","and/ let me strike down","and/ strike","and/ they may attack","and/ they struck down","so/ we may attack"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3654}/[H3661]', 'inflected', 'heb', 'כֵּן', '["kên"]', '["<into>/ gnats"]', '["n-m"]', 'a gnat lice, × manner.', 'from 3661 in the sense of fastening; (from infixing its sting; used only in plural (and irregular in Exodus 8:17,18; Hebrews 13:14))');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4294G}/H9023/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["with/ rod/ his","with/ staff/ his"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3654}/[H3661]', 'inflected', 'heb', 'כֵּן', '["kên"]', '["the/ gnat[s]","the/ gnats"]', '["n-m"]', 'a gnat lice, × manner.', 'from 3661 in the sense of fastening; (from infixing its sting; used only in plural (and irregular in Exodus 8:17,18; Hebrews 13:14))');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3654}/[H3661]', 'lemma', 'heb', 'כֵּן', '["kên"]', '["gnat[s]","gnats"]', '["n-m"]', 'a gnat lice, × manner.', 'from 3661 in the sense of fastening; (from infixing its sting; used only in plural (and irregular in Exodus 8:17,18; Hebrews 13:14))');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3318L}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["to/ bring forth"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0676}/[H6648]', 'lemma', 'heb', 'אֶצְבַּע', '["ʼetsbaʻ"]', '["[is] [the] finger of","a finger","fingers"]', '["n-f"]', 'something to sieze with, i.e. a finger; by analogy, a toe finger, toe.', 'from the same as 6648 (in the sense of grasping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7925}/[H7926]', 'lemma', 'heb', 'שָׁכַם', '["shâkam"]', '["[those who] rise early","[who] rise early","let us rise early","rise early","rising early","they rose early","you will rise early"]', '["v"]', 'literally, to load up (on the back of man or beast), i.e. to start early in the morning (arise, be up, get (oneself) up, rise up) early (betimes), morning.', 'a primitive root; properly, to incline (the shoulder to a burden); but used only as denominative from 7926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3320}/[H3320]', 'inflected', 'heb', 'יָצַב', '["yâtsab"]', '["and/ I will take my stand","and/ present yourself","and/ present yourselves","and/ take your stand","so/ they may stand forth"]', '["v"]', 'to place (any thing so as to stay); reflexively, to station, offer, continue present selves, remaining, resort, set (selves), (be able to, can, with-) stand (fast, forth, -ing, still, up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5650}/H9021/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["and/ on/ servants/ your"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1004B}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ on/ houses/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6157}/[H6148]', 'inflected', 'heb', 'עָרֹב', '["ʻârôb"]', '["the/ swarm"]', '["n-m"]', 'a mosquito (from its swarming) divers sorts of flies, swarm.', 'from 6148;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6395}/[H6395]', 'inflected', 'heb', 'פָּלָה', '["pâlâh"]', '["and/ I will separate","and/ he will separate","and/ we will be distinguished"]', '["v"]', 'to distinguish (literally or figuratively) put a difference, show marvellous, separate, set apart, sever, make wonderfully.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6157}/[H6148]', 'lemma', 'heb', 'עָרֹב', '["ʻârôb"]', '["a swarm","a swarm of flies"]', '["n-m"]', 'a mosquito (from its swarming) divers sorts of flies, swarm.', 'from 6148;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6304}/[H6929]', 'lemma', 'heb', 'פְּדוּת', '["pᵉdûwth"]', '["a ransom","redemption"]', '["n-f"]', 'distinction; also deliverance division, redeem, redemption.', 'or פְּדֻת; from 6929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004B}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ [is the] house of","and/ [is] a house of","and/ [the] house of","and/ [the] household of","and/ [the] houses of","and/ a house","and/ a house of","and/ houses"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0430G}/H9026/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["<to>/ God/ your","to/ God/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559K}/[H3559]', 'lemma', 'heb', 'כּוּן', '["kûwn"]', '["[is] a reliable [thing]","[is] certain","[is] established","a certain [thing]","a reliable [thing]","he gave attention","prepare","steadfast","you will establish"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5619}/H9035/[H5619]', 'inflected', 'heb', 'סָקַל', '["çâqal"]', '["will they stone?/ us"]', '["v"]', 'properly, to be weighty; but used only in the sense of lapidation or its contrary (as if a delapidation) (cast, gather out, throw) stone(-s), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1157}/H9030/[H5704]', 'inflected', 'heb', 'בְּעַד', '["bᵉʻad"]', '["[were] behind/ me","behind/ me","for/ me"]', '["prep"]', 'in up to or over against; generally at, beside, among, behind, for, etc. about, at by (means of), for, over, through, up (-on), within.', 'from 5704 with prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5973B}/H9031/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["from/ with <the>/ you"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6547J}/[H6547]', 'inflected', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["from/ Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5650}/H9023/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["from/ servants/ his","of/ servants/ his"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5971A}/H9023/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ from/ people/ his"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2076}/[H2076]', 'inflected', 'heb', 'זָבַח', '["zâbach"]', '["to/ sacrifice","to/ sacrifice [them]"]', '["v"]', 'to slaughter an animal (usually in sacrifice) kill, offer, (do) sacrifice, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3513H}/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["and/ he made heavy","and/ it was heavy","and/ it was unresponsive","and/ it will be heavy","and/ you were honored"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6471}/[H6470]', 'inflected', 'heb', 'פַּעַם', '["paʻam"]', '["at the/ time","at/ a time","on/ time"]', '["n-f"]', 'a stroke, literally or figuratively (in various applications, as follow) anvil, corner, foot(-step), going, (hundred-) fold, × now, (this) once, order, rank, step, thrice, (often-), second, this, two) time(-s), twice, wheel.', 'or (feminine) פַּעֲמָה; from 6470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5971A}\/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["the/ people","the/ peoples"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5750}/H9041/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["and/ still/ you"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388H}/[H2388]', 'lemma', 'heb', 'חָזַק', '["châzaq"]', '["I have kept hold","I have taken hold","[are] keeping hold","[is one who] takes hold","[is] keeping hold","[one who] takes hold","[was] holding","[were] holding","[were] keeping hold","[who] he takes hold","[who] takes hold of","he kept hold","he takes hold","holding","it takes hold","it was secure","it will take hold","keeping hold","let anyone take hold","take hold","take hold of","they have kept hold","they make firm","they strengthen","they take hold of","they will take hold","they will take hold of"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4735}/H9021/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["on/ livestock/ your"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2543}/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["on <the>/ donkeys","on the/ donkeys","on/ donkeys"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1581}/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["on the/ camels"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1241}/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["among the/ cattle","for <the>/ cattle","in the/ herd","on the/ cattle","with <the>/ oxen"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H6629G>', 'inflected', 'heb', 'ובצאן', '["u./va./Tzon"]', '["and/ for <the>/ sheep","and/ on the/ sheep"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1698}/[H1696]', 'lemma', 'heb', 'דֶּבֶר', '["deber"]', '["a pestilence","pestilence"]', '["n-m"]', 'a pestilence murrain, pestilence, plague.', 'from 1696 (in the sense of destroying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4150G}/[H3259]', 'lemma', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["[the] appointed time","[the] time of","an appointed time","appointed meeting","times"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4735}/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["and/ of/ [the] livestock of"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4735}/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["any of/ [the] livestock of"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2651>/H9026', 'opaque', 'heb', 'חֹפֶן', '["chôphen"]', '["hands/ your"]', '["n-m"]', 'a fist (only in the dual) fists, (both) hands, hand(-ful).', 'from an unused root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6368}/[H6315]', 'lemma', 'heb', 'פִּיחַ', '["pîyach"]', '["[the] soot of","soot of"]', '["n-m"]', 'a powder (as easily puffed away), i.e. ashes or dust ashes.', 'from 6315;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3536}/[H3533]', 'lemma', 'heb', 'כִּבְשָׁן', '["kibshân"]', '["a furnace"]', '["n-m"]', 'a smelting furnace (as reducing metals) furnace.', 'from 3533;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2236}/H9033/[H2236]', 'inflected', 'heb', 'זָרַק', '["zâraq"]', '["and/ he sprinkled/ it","and/ he will sprinkle/ it"]', '["v"]', 'to sprinkle (fluid or solid particles) be here and there, scatter, sprinkle, strew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0080}/[H79]', 'inflected', 'heb', 'אָבָק', '["ʼâbâq"]', '["<into>/ dust"]', '["n-m"]', 'light particles (as volatile) (small) dust, powder.', 'from root of 79;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7822>', 'inflected', 'heb', 'לשחין', '["li/sh.Chin"]', '["<into>/ boil[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6524B}/[H6524]', 'lemma', 'heb', 'פָּרַח', '["pârach"]', '["[which is] breaking out","breaking out","certainly <to break out>","it has broken out","it will break out"]', '["v"]', 'to break forth as a bud, i.e. bloom; generally, to spread; specifically, to fly (as extending the wings); figuratively, to flourish × abroad, × abundantly, blossom, break forth (out), bud, flourish, make fly, grow, spread, spring (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0076>', 'opaque', 'heb', 'אֲבַעְבֻּעָה', '["ʼăbaʻbuʻâh"]', '["blisters"]', '["n-f"]', 'an inflammatory pustule (as eruption) blains.', '(by reduplication) from an unused root (meaning to belch forth);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2236}/[H2236]', 'inflected', 'heb', 'זָרַק', '["zâraq"]', '["and/ I will sprinkle","and/ he sprinkled","and/ he sprinkled [it]","and/ he sprinkled [them]","and/ he will sprinkle","and/ they sprinkled","and/ they sprinkled [it]","and/ they will sprinkle","and/ you will sprinkle","and/ you will sprinkle [it]"]', '["v"]', 'to sprinkle (fluid or solid particles) be here and there, scatter, sprinkle, strew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7822>', 'opaque', 'heb', 'שְׁחִין', '["shᵉchîyn"]', '["a boil","boil[s]"]', '["n-m"]', 'inflammation, i.e. an ulcer boil, botch.', 'from an unused root probably meaning to burn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5975G}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["to/ fulfill","to/ stand","to/ stay"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7822>', 'inflected', 'heb', 'השחין', '["ha./she.Chin"]', '["the/ boil","the/ boil[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2748}/[H2747]', 'inflected', 'heb', 'חַרְטֹם', '["charṭôm"]', '["on the/ magicians"]', '["n-m"]', 'a horoscopist (as drawing magical lines or circles) magician.', 'from the same as 2747;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4872}\/[H4871]', 'inflected', 'heb', 'מֹשֶׁה', '["Môsheh"]', '["Moses"]', '["n-pr-m"]', 'Mosheh, the Israelite lawgiver Moses.', 'from 4871; drawing out (of the water), i.e. rescued;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4046}/H9020/[H5062]', 'inflected', 'heb', 'מַגֵּפָה', '["maggêphâh"]', '["plagues/ my"]', '["n-f"]', 'a pestilence; by analogy, defeat (× be) plague(-d), slaughter, stroke.', 'from 5062;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9021/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart of/ your","heart/ your"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3582}/[H3582]', 'inflected', 'heb', 'כָּחַד', '["kâchad"]', '["and/ I annihilated","and/ he annihilated","and/ you were destroyed"]', '["v"]', 'to secrete, by act or word; hence (intensively) to destroy conceal, cut down (off), desolate, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5975H}/H9031/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["I have caused to stand/ you"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200G}/H9041/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["seeing/ you","to see/ you"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4616}/[H6030]', 'inflected', 'heb', 'מַעַן', '["maʻan"]', '["and/ for [the] sake of","and/ so as","and/ so that"]', '["prt"]', 'properly, heed, i.e. purpose; used only adverbially, on account of (as a motive or an aim), teleologically, in order that because of, to the end (intent) that, for (to,... ''s sake), lest, that, to.', 'from 6030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5549}/[H5549]', 'lemma', 'heb', 'סָלַל', '["çâlal"]', '["[are] exalting yourself","[is] cast up","build up","built up","lift up"]', '["v"]', 'to mound up (especially a turnpike); figurative, to exalt; reflexively, to oppose (as by a dam) cast up, exalt (self), extol, make plain, raise up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5971A}/H9020/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["among/ people/ my","in/ people/ my","on/ people/ my","over/ people/ my"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971H}/H9038/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["to let go/ them"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1259}/[H1258]', 'lemma', 'heb', 'בָּרָד', '["bârâd"]', '["hail"]', '["n-m"]', 'hail hail(stones).', 'from 1258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3644G}/H9033/[H3651]', 'inflected', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["[is] as/ it","[is] like/ him","[is] like/ it","like/ him","like/ his","like/ it"]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4480A}/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["<to>/ from"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3245}/H9044/[H3245]', 'inflected', 'heb', 'יָסַד', '["yâçad"]', '["was founded/ it"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5756}/[H5756]', 'lemma', 'heb', 'עוּז', '["ʻûwz"]', '["bring to refuge","flee for refuge","take refuge","they have taken refuge"]', '["v"]', 'to be strong; causatively, to strengthen, i.e. (figuratively) to save (by flight) gather (self, self to flee), retire.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H0929>', 'inflected', 'heb', 'והבהמה', '["ve./ha./be.he.Mah"]', '["and/ the/ cattle","and/ the/ livestock"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1259}/[H1258]', 'inflected', 'heb', 'בָּרָד', '["bârâd"]', '["the/ hail"]', '["n-m"]', 'hail hail(stones).', 'from 1258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3373}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["<the>/ fearful","the/ [one] fearing"]', '["a"]', 'fearing; morally, reverent afraid, fear (-ful).', 'from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5650}/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["[be] any of/ [the] servants of","from/ [the] servants of","of/ [the] servants of","one of/ [the] servants of","some of/ [the] servants of"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7704G>\', 'inflected', 'heb', 'בשדה פ', '["ba./sa.Deh"]', '["in the/ field"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414M}/[H5414]', 'lemma', 'heb', 'נָתַן', '["nâthan"]', '["does she give forth?","give forth","he gave","he gave forth","he gives","he will give forth","it has given","it will be given","people have given forth","people will give","she gives","they gave forth","they have given","you will give"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963I>', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["[the] thunder claps of","a sound","thunder claps"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1259}/[H1258]', 'inflected', 'heb', 'בָּרָד', '["bârâd"]', '["and/ [the] hail","and/ hail"]', '["n-m"]', 'hail hail(stones).', 'from 1258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4305}/[H4305]', 'inflected', 'heb', 'מָטַר', '["mâṭar"]', '["and/ I sent rain","and/ he rained down"]', '["v"]', 'to rain (cause to) rain (upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947L}/[H3947]', 'lemma', 'heb', 'לָקַח', '["lâqach"]', '["[was] flashing","flashing"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7665}/[H7665]', 'lemma', 'heb', 'שָׁבַר', '["shâbar"]', '["I broke off","I have been broken","I have broken","I was crushed","I will break","[am] about to break","[has been] broken","[is] breaking","being broken","break","broke","broken","do I bring to [the] birth","he breaks","he breaks down","he broke","he broke in pieces","he has broken","he shattered","he will be broken","he will break","it had mauled","it has been broken","it has broken","it is broken","it shattered","it was broken","it was maimed","it will be broken","it will be broken up","it will break","let it be broken","she has been broken","someone breaks","someone has broken","they are broken off","they break","they broke","they had been broken","they had broken off","they have been broken","they were broken","they will be broken","they will break","you have broken","you shatter","you shattered","you were broken","you will be broken","you will break","you will shatter","you will shatter into pieces"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5971A}/H9020/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ people/ my"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7563}/[H7561]', 'inflected', 'heb', 'רָשָׁע', '["râshâʻ"]', '["<the>/ wicked","<the>/ wicked [people]","[are] the/ guilty [ones]","the/ guilty [one]","the/ wicked","the/ wicked [people]","the/ wicked [person]"]', '["a"]', 'morally wrong; concretely, an (actively) bad person condemned, guilty, ungodly, wicked (man), that did wrong.', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1961}/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["for/ being","for/ belonging","from/ being","from/ belonging","from/ when was"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3318G}/H9040/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ have gone out/ I"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6566}/[H6566]', 'lemma', 'heb', 'פָּרַשׂ', '["pâras"]', '["I have scattered","I have spread out","I spread out","I will spread","I will spread out","[is] spreading","[one who] breaks [it]","[were] spread out","[were] spreading out","does it spread out?","he has spread out","he spread out","he spreads [them] out","he spreads out","it has spread out","it spreads out","she is spreading out","she spreads out","spread out","spreading out","they have spread","they have spread out","they will be scattered","they will spread out"]', '["v"]', 'to break apart, disperse, etc. break, chop in pieces, lay open, scatter, spread (abroad, forth, selves, out), stretch (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6963I>', 'inflected', 'heb', 'הקלות', '["ha./ko.Lot","ha./ko.lOt"]', '["the/ thunder claps"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2308}/H9013/[H2308]', 'inflected', 'heb', 'חָדַל', '["châdal"]', '["they will cease/ !"]', '["v"]', 'properly, to be flabby, i.e. (by implication) desist; (figuratively) be lacking or idle cease, end, fall, forbear, forsake, leave (off), let alone, rest, be unoccupied, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1259}/[H1258]', 'inflected', 'heb', 'בָּרָד', '["bârâd"]', '["and/ the/ hail"]', '["n-m"]', 'hail hail(stones).', 'from 1258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3372H}/H9013/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["you fear/ !"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6594}/[H6593]', 'inflected', 'heb', 'פִּשְׁתָּה', '["pishtâh"]', '["and/ the/ flax"]', '["n-f"]', 'flax; by implication, a wick flax, tow.', 'feminine of 6593;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8184}/[H8175]', 'inflected', 'heb', 'שְׂעֹרָה', '["sᵉʻôrâh"]', '["and/ the/ barley","and/ the/ barley<s>"]', '["n-f"]', 'barley (as villose) barley.', 'or שְׂעוֹרָה (feminine meaning the plant); and (masculine meaning the grain); also שְׂעֹר; or שְׂעוֹר; from 8175 in the sense of roughness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8184}/[H8175]', 'inflected', 'heb', 'שְׂעֹרָה', '["sᵉʻôrâh"]', '["the/ barley","the/ barley<s>"]', '["n-f"]', 'barley (as villose) barley.', 'or שְׂעוֹרָה (feminine meaning the plant); and (masculine meaning the grain); also שְׂעֹר; or שְׂעוֹר; from 8175 in the sense of roughness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0024>', 'opaque', 'heb', 'אָבִיב', '["ʼâbîyb"]', '["[was] young barley ear[s]","young barley ear[s]"]', '["n-m"]', 'green, i.e. a young ear of grain; hence, the name of the month Abib or Nisan Abib, ear, green ears of corn (not maize).', 'from an unused root (meaning to be tender);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1392}/[H1375]', 'lemma', 'heb', 'גִּבְעֹל', '["gibʻôl"]', '["[was] bud"]', '["n-m"]', 'the calyx of a flower bolled.', 'prolonged from 1375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H2406>', 'inflected', 'heb', 'והחטים', '["ve./ha./chi.Tah","ve./ha./chi.Tim"]', '["and/ the/ wheat","and/ the/ wheat<s>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3698}/[H3697]', 'inflected', 'heb', 'כֻּסֶּמֶת', '["kuççemeth"]', '["and/ the/ spelt"]', '["n-f"]', 'spelt (from its bristliness as if just shorn) fitches, rie.', 'from 3697;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0648}/[H651]', 'lemma', 'heb', 'אָפִיל', '["ʼâphîyl"]', '["[are] late [crops]"]', '["a"]', 'unripe not grown up.', 'from the same as 651 (in the sense of weakness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6566}/[H6566]', 'inflected', 'heb', 'פָּרַשׂ', '["pâras"]', '["and/ I spread out","and/ I will spread","and/ he spread [it] out","and/ he spread out","and/ he will spread out","and/ it will spread out","and/ she spread out","and/ they spread out","and/ they will spread out","and/ we had spread out","and/ you will spread out"]', '["v"]', 'to break apart, disperse, etc. break, chop in pieces, lay open, scatter, spread (abroad, forth, selves, out), stretch (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709G}/H9023/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["hand/ his","hands/ his","palm/ his","palms/ his"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4306}/[H4305]', 'inflected', 'heb', 'מָטַר', '["mâṭar"]', '["and/ rain","and/ rain of"]', '["n-m"]', 'rain rain.', 'from 4305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5413}/[H5413]', 'lemma', 'heb', 'נָתַךְ', '["nâthak"]', '["[are] about to be poured out","it has been poured out","it was poured out","it will be poured forth","it will pour forth","it will pour out","they have poured out","you will be melted"]', '["v"]', 'to flow forth (literally or figuratively); by implication, to liquify drop, gather (together), melt, pour (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4306}/[H4305]', 'inflected', 'heb', 'מָטַר', '["mâṭar"]', '["the/ rain"]', '["n-m"]', 'rain rain.', 'from 4305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H6963I>', 'inflected', 'heb', 'והקלת', '["ve./ha./ko.Lot"]', '["and/ the/ thunder claps"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2398}/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["for/ sinning","to/ cause to sin","to/ cleanse from sin","to/ sin"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027J}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["by/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896G}/H9040/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["to perform/ I"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121G}/H9021/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["children/ your","descendants/ your","son/ your","sons/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5953A}/[H5953]', 'lemma', 'heb', 'עָלַל', '["ʻâlal"]', '["I have dealt ruthlessly","have you dealt severely","he dealt wantonly","it has been done","it has dealt severely","you have dealt severely","you have dealt wantonly"]', '["v"]', 'to effect thoroughly; specifically, to glean (also figuratively); by implication (in a bad sense) to overdo, i.e. maltreat, be saucy to, pain, impose (also literal) abuse, affect, × child, defile, do, glean, mock, practise, thoroughly, work (wonderfully).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6031B}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["to/ humble","to/ humble ourselves","to/ humble yourself"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440G}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ before/ me"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0697}/[H7235]', 'lemma', 'heb', 'אַרְבֶּה', '["ʼarbeh"]', '["a locust","locust[s]"]', '["n-m"]', 'a locust (from its rapid increase) grasshopper, locust.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1366H}/H9021/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["in/ territory/ your"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869J}/[H5869]', 'lemma', 'heb', 'עַיִן', '["ʻayin"]', '["[the] eye of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6413}/[H6412]', 'inflected', 'heb', 'פְּלֵיטָה', '["pᵉlêyṭâh"]', '["the/ escaped remnant","the/ escaped thing"]', '["n-f"]', 'deliverance; concretely, an escaped portion deliverance, (that is) escape(-d), remnant.', 'or פְּלֵטָה; feminine of 6412;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6779}/[H6779]', 'inflected', 'heb', 'צָמַח', '["tsâmach"]', '["that/ is sprouting","who/ causes to sprout"]', '["v"]', 'to sprout (transitive or intransitive, literal or figurative) bear, bring forth, (cause to, make to) bud (forth), (cause to, make to) grow (again, up), (cause to) spring (forth, up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["house/ your","houses/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3117G>', 'inflected', 'heb', 'מימים', '["Mi./mei","mi./Mei","mi./Yom","mi./mei","mi./yOm","mi./ya.Mim","mi./yo.Ma.yim","mi./yom"]', '["[which is] from/ days of","from/ [the] day","from/ [the] days of","from/ day","from/ days","from/ days of","from/ two days","more than/ [the] day of","since/ [the] days of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1961}/H9048/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["being/ they","have been/ they","were/ they"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4170}/[H3369]', 'inflected', 'heb', 'מוֹקֵשׁ', '["môwqêsh"]', '["<into>/ a snare"]', '["n-m"]', 'a noose (for catching animals) (literally or figuratively); by implication, a hook (for the nose) be ensnared, gin, (is) snare(-d), trap.', 'or מֹקֵשׁ; from 3369;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5647H}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ let us serve","and/ serve","and/ they may serve [him]","so/ they may serve"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9028/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ their","[is] God/ their","god/ their"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/<H2962>', 'inflected', 'heb', 'הטרם', '["ha./Te.rem"]', '["¿/ not yet"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0006}/[H6]', 'lemma', 'heb', 'אָבַד', '["ʼâbad"]', '["I have destroyed","I have perished","I perished","I will destroy","[is] about to destroy","[is] perishing","[one who] was perishing","[one] about to perish","[which] is destroyed","[who] are causing to stray","[who] perishes","certainly <destroy>","certainly <to perish>","did he perish","has he perished","has it been destroyed","has it been lost?","he destroys","he had destroyed","he has destroyed","he has perished","he will destroy","he will perish","it had perished","it has been lost","it has perished","it is lost","it perished","it perishes","it was lost","it will be lost","it will perish","let it perish","let us perish","lost","may they perish","perish","perishing","they have perished","they perish","they will be lost","they will perish","to destroy","wandering","we will perish","you destroy","you have destroyed","you have perished","you will destroy","you will perish"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647H}/[H5647]', 'lemma', 'heb', 'עָבַד', '["ʻâbad"]', '["I served","[are] serving","[one who] serves","[those who] serve","do they serve","he had served","he served","he will serve","serve","serving","they have served","they served","to serve","we will serve","will I serve","will we serve","you have served","you will serve"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4310}/[H4100]', 'inflected', 'heb', 'מִי', '["mîy"]', '["and/ who?","and/ whoever"]', '["i"]', 'who? (occasionally, by a peculiar idiom, of things); also (indefinitely) whoever; often used in oblique construction with prefix or suffix any (man), × he, × him, O that! what, which, who(-m, -se, -soever), would to God.', 'an interrogative pronoun of persons, as 4100 is of things,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5288}/H9025/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["with/ young men/ our"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2205H}/H9025/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["and/ with/ old [men]/ our"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1121A}/H9025/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["with/ sons/ our"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1323G}/H9025/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ with/ daughters/ our"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6629G>/H9025', 'inflected', 'heb', 'בצאננו', '["be./tzo.Ne./nu"]', '["with/ flock[s]/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1241}/H9025/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["and/ with/ herds/ our"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2282}/[H2287]', 'lemma', 'heb', 'חַג', '["chag"]', '["<the> festival of","[the] feast of","[the] festival of","a festival","a festival of","a festival sacrifice","festivals"]', '["n-m"]', 'a festival, or a victim therefor (solemn) feast (day), sacrifice, solemnity.', 'or חָג; from 2287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440G}/H9026/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["faces/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1397}/[H1396]', 'inflected', 'heb', 'גֶּבֶר', '["geber"]', '["[am] the/ man","[is] the/ man","the/ man","the/ men"]', '["n-m"]', 'properly, a valiant man or warrior; generally, a person simply every one, man, × mighty.', 'from 1396;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0697}/[H7235]', 'inflected', 'heb', 'אַרְבֶּה', '["ʼarbeh"]', '["for the/ locust[s]"]', '["n-m"]', 'a locust (from its rapid increase) grasshopper, locust.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5090A}/[H5090]', 'lemma', 'heb', 'נָהַג', '["nâhag"]', '["O [you who] lead","[was] guiding","[were] leading","[will be] leading","[will be] led","he drives","he drove","he has driven","he will drive away","he will lead away","lead on","they drive away","they drove [them]","you led"]', '["v"]', 'to drive forth (a person, an animal or chariot), i.e. lead, carry away; reflexively, to proceed (i.e. impel or guide oneself); also (from the panting induced by effort), to sigh acquaint, bring (away), carry away, drive (away), lead (away, forth), (be) guide, lead (away, forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7307H}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ [the] breath of","and/ [the] wind","and/ [the] wind of","and/ [was] breath","and/ [will be] a wind","and/ [will be] a wind of","and/ a breath","and/ a wind","and/ a wind of","and/ breath","and/ wind"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0697}/[H7235]', 'inflected', 'heb', 'אַרְבֶּה', '["ʼarbeh"]', '["the/ locust","the/ locust[s]"]', '["n-m"]', 'a locust (from its rapid increase) grasshopper, locust.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0310A}/H9033/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["and/ [was] after/ him","and/ [were] behind/ him","and/ [will be] after/ it","and/ after/ him","and/ after/ it"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2821}/[H2821]', 'inflected', 'heb', 'חָשַׁךְ', '["châshak"]', '["and/ I will make dark","and/ he made dark","and/ it grew dark","and/ it will grow dark","and/ they will grow dim"]', '["v"]', 'to be dark (as withholding light); transitively, to darken be black, be (make) dark, darken, cause darkness, be dim, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6086H}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["among/ [the] tree[s] of","among/ [the] trees of","on the/ tree[s]"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H6212>', 'inflected', 'heb', 'ובעשב', '["u./ve./''E.sev"]', '["and/ on/ [the] vegetation of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H9036}', 'inflected', 'arc', 'ולכם', '["u./le./Khom","ve./la./Khem"]', '["and/ [belongs] to/ you","and/ for <the>/ yourselves","and/ to <the>/ you","and/ to/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6279}/[H6281]', 'inflected', 'heb', 'עָתַר', '["ʻâthar"]', '["and/ being entreated","and/ he was entreated","and/ pray"]', '["v"]', 'to burn incense in worship, i.e. intercede (reciprocally, listen to prayer) intreat, (make) pray(-er).', 'a primitive root (rather denominative from 6281);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4194}/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["<the>/ death","the/ death"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3220H>', 'opaque', 'heb', 'יָם', '["yâm"]', '["[the] west","west"]', '["n-m"]', 'a sea (as breaking in noisy surf) or large body of water; specifically (with the article), the Mediterranean Sea; sometimes a large river, or an artifical basin; locally, the west, or (rarely) the south sea (× -faring man, (-shore)), south, west (-ern, side, -ward).', 'from an unused root meaning to roar;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8628}/H9033/[H8628]', 'inflected', 'heb', 'תָּקַע', '["tâqaʻ"]', '["and/ I will drive/ him","and/ it blew/ it"]', '["v"]', 'to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3220G>/H9011', 'opaque', 'heb', 'יָם', '["yâm"]', '["[the] sea of/ towards","[the] sea/ towards","west/ -ward"]', '["n-m"]', 'a sea (as breaking in noisy surf) or large body of water; specifically (with the article), the Mediterranean Sea; sometimes a large river, or an artifical basin; locally, the west, or (rarely) the south sea (× -faring man, (-shore)), south, west (-ern, side, -ward).', 'from an unused root meaning to roar;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5488G}/[H5488]', 'lemma', 'heb', 'סוּף', '["çûwph"]', '["reed[s]"]', '["n-m"]', 'a reed, especially the papyrus flag, Red (sea), weed. Compare 5489.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2822}/[H2821]', 'lemma', 'heb', 'חֹשֶׁךְ', '["chôshek"]', '["[be] darkness","[is] darkness","[will be] darkness","darkness","darkness of"]', '["n-m"]', 'the dark; hence (literally) darkness; figuratively, misery, destruction, death, ignorance, sorrow, wickedness dark(-ness), night, obscurity.', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4959}/[H4959]', 'inflected', 'heb', 'מָשַׁשׁ', '["mâshash"]', '["so/ they may feel"]', '["v"]', 'to feel of; by implication, to grope feel, grope, search.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0653}/[H651]', 'lemma', 'heb', 'אֲפֵלָה', '["ʼăphêlâh"]', '["darkness"]', '["n-f"]', 'duskiness, figuratively, misfortune; concrete, concealment dark, darkness, gloominess, × thick.', 'feminine of 651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8478I}/H9033/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["from/ under/ him"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4186}/H9028/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["in/ dwelling places/ their"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6629G>/H9026', 'opaque', 'heb', 'צֹאן', '["tsôʼn"]', '["flock[s]/ your"]', '["n-f"]', 'a collective name for a flock (of sheep or goats); also figuratively (of men) (small) cattle, flock ( -s), lamb ( -s), sheep(-cote, -fold, -shearer, -herds).', 'or צאוֹן; (Psalm 144:13), from an unused root meaning to migrate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1241}/H9026/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["and/ herd[s]/ your"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027H}/H9025/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[were] in/ hand/ our","in/ hand/ our"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5930A}/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["and/ [the] burnt offering of","and/ a burnt offering","and/ a burnt offering of","and/ burnt offering[s]","and/ burnt offerings"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4735}/H9025/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["livestock/ our"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6541}/[H6538]', 'lemma', 'heb', 'פַּרְסָה', '["parçâh"]', '["<of> a hoof","[the] hooves of","a hoof","hooves"]', '["n-f"]', 'a claw or split hoof claw, (cloven-) footed, hoof.', 'feminine of 6538;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5647H}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["by/ serving","to/ [those who] serve","to/ serve"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0587}/[H595]', 'inflected', 'heb', 'אֲנַחְנוּ', '["ʼănachnûw"]', '["and/ we"]', '["p"]', 'we ourselves, us, we.', 'apparently from 595;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9045/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["go/ we"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7971H}/H9038/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["to/ let go/ them"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440H}/H9021\/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7971H}/H9043/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["when/ lets [you] go/ he"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0802G}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ [the] wife of","and/ a woman","and/ everyone [fem]","and/ woman","and/ women"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7468}/H9024/[H7462]', 'inflected', 'heb', 'רְעוּת', '["rᵉʻûwth"]', '["[female] neighbor/ its","companion/ its","neighbor [fem]/ her","neighbor/ her"]', '["n-f"]', 'a female associate; generally an additional one another, mate, neighbour.', 'from 7462 in the sense of 7453;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5869H}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ in/ [the] eyes of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2676}/[H2673]', 'inflected', 'heb', 'חָצוֹת', '["châtsôwth"]', '["about/ [the] middle of"]', '["n-f"]', 'the middle (of the night) mid(-night).', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3678G}/H9023/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["throne/ his"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7347>', 'inflected', 'heb', 'הרחים', '["ha./re.Cha.yim"]', '["the/ hand-mill"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3644G}/H9033/[H3651]', 'inflected', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["and/ like/ him","and/ like/ it"]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2782}/[H2782]', 'lemma', 'heb', 'חָרַץ', '["chârats"]', '["[are] determined","[has been] decided","[what has been] decreed","he sharpened","it will sharpen","you have decided","you will act decisively"]', '["v"]', 'properly, to point sharply, i.e. (literally) to wound; figuratively, to be alert, to decide bestir self, decide, decree, determine, maim, move.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3611>', 'opaque', 'heb', 'כֶּלֶב', '["keleb"]', '["[are] dogs","[the] dogs of","a dog","dogs"]', '["n-m"]', 'a dog; hence (by euphemism) a male prostitute dog.', 'from an unused root means. to yelp, or else to attack;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956G}/H9023/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["tongue/ his","tongue/ its"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/<H0376G>', 'inflected', 'heb', 'למאיש', '["le./me./''Ish"]', '["<to>/ from/ man","to/ from/ a human","to/ from/ a man"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9013/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["they had known/ !","they know/ !","they may know/ !","they will know/ !","you may know/ !","you will know/ !"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6395}/[H6395]', 'lemma', 'heb', 'פָּלָה', '["pâlâh"]', '["I am wonderful","he has set apart","he separates","make wonderful"]', '["v"]', 'to distinguish (literally or figuratively) put a difference, show marvellous, separate, set apart, sever, make wonderfully.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7272}/H9021/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["[is] at/ feet/ your","on/ feet/ your","with/ feet/ your","with/ foot/ your"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2750}/[H2734]', 'inflected', 'heb', 'חֳרִי', '["chŏrîy"]', '["by/ [the] heat of","in/ [the] heat of","with/ heat of"]', '["n-m"]', 'a burning (i.e. intense) anger fierce, × great, heat.', 'from 2734;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639G}\/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["anger"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5712}/[H5707]', 'lemma', 'heb', 'עֵדָה', '["ʻêdâh"]', '["O congregation","[the] company of","[the] congregation","[the] congregation of","a company of","a herd of","a swarm of"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6218}/[H6235]', 'inflected', 'heb', 'עָשׂוֹר', '["ʻâsôwr"]', '["on the/ ten"]', '["n-m"]', 'ten; by abbreviated form ten strings, and so a decachord (instrument of) ten (strings, -th).', 'or עָשֹׂר; from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4591}/[H4591]', 'lemma', 'heb', 'מָעַט', '["mâʻaṭ"]', '["[the] being small of","he made few","he will make little","it be small","it will be [too] small","it will become small","they have become few","they will be few","they will diminish","you diminish","you make few","you will decrease","you will make small"]', '["v"]', 'properly, to pare off, i.e. lessen; intransitively, to be (or causatively, to make) small or few (or figuratively, ineffective) suffer to decrease, diminish, (be, × borrow a, give, make) few (in number, -ness), gather least (little), be (seem) little, (× give the) less, be minished, bring to nothing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1004M}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["the/ house","the/ household"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7716}/[H7582]', 'inflected', 'heb', 'שֶׂה', '["seh"]', '["for/ a lamb"]', '["n-m"]', 'a member of a flock, i.e. a sheep or goat (lesser, small) cattle, ewe, goat, lamb, sheep. Compare 2089.', 'or שֵׂי; probably from 7582 through the idea of pushing out to graze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7934}/H9023/[H7931]', 'inflected', 'heb', 'שָׁכֵן', '["shâkên"]', '["and/ neighbor/ his","and/ neighbors/ its"]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7138}/[H7126]', 'inflected', 'heb', 'קָרוֹב', '["qârôwb"]', '["<the>/ near","the/ [nations] nearby","the/ [people] near"]', '["a"]', 'near (in place, kindred or time) allied, approach, at hand, any of kin, kinsfold(-sman), (that is) near (of kin), neighbour, (that is) next, (them that come) nigh (at hand), more ready, short(-ly).', 'or קָרֹב; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4373}/[H4371]', 'inflected', 'heb', 'מִכְסָה', '["mikçâh"]', '["by/ [the] number of"]', '["n-f"]', 'an enumeration; by implication, a valuation number, worth.', 'feminine of 4371;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0400}/H9023/[H398]', 'inflected', 'heb', 'אֹכֶל', '["ʼôkel"]', '["food/ his","food/ its"]', '["n-m"]', 'food eating, food, meal(-time), meat, prey, victuals.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3699}/[H3699]', 'lemma', 'heb', 'כָּסַס', '["kâçaç"]', '["you will estimate"]', '["v"]', 'to estimate make count.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8549G}/[H8552]', 'lemma', 'heb', 'תָּמִים', '["tâmîym"]', '["[is] blameless","[is] perfect","[one] complete of","unblemished"]', '["a"]', 'entire (literally, figuratively or morally); also (as noun) integrity, truth without blemish, complete, full, perfect, sincerely (-ity), sound, without spot, undefiled, upright(-ly), whole.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3532>', 'inflected', 'heb', 'הכבשים', '["ha./Ke.ves","ha./ke.va.Sim"]', '["the/ lamb","the/ lambs","the/ male lamb"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4931}/[H4929]', 'inflected', 'heb', 'מִשְׁמֶרֶת', '["mishmereth"]', '["<into>/ something kept","[will be] for/ keeping","for/ keeping","for/ safekeeping","to/ [the] duty of","to/ duties","to/ guards"]', '["n-f"]', 'watch, i.e. the act (custody), or (concretely) the sentry, the post; objectively preservation, or (concretely) safe; figuratively observance, i.e. (abstractly) duty or (objectively) a usage or party charge, keep, or to be kept, office, ordinace, safeguard, ward, watch.', 'feminine of 4929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6951}/[H6950]', 'lemma', 'heb', 'קָהָל', '["qâhâl"]', '["[the] assembly","[the] assembly of","[the] company","a company","an assembly","an assembly of"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6153}/[H6150]', 'inflected', 'heb', 'עֶרֶב', '["ʻereb"]', '["the/ evening","the/ evenings","the/ two evenings"]', '["n-m"]', 'dusk day, even(-ing, tide), night.', 'from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4201}/[H2123]', 'inflected', 'heb', 'מְזוּזָה', '["mᵉzûwzâh"]', '["the/ doorpost","the/ doorposts"]', '["n-f"]', 'a door-post (as prominent) (door, side) post.', 'or מְזֻזָה; from the same as 2123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4947}/[H8259]', 'inflected', 'heb', 'מַשְׁקוֹף', '["mashqôwph"]', '["the/ lintels"]', '["n-m"]', 'a lintel lintel.', 'from 8259 in its original sense of overhanging;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6748}/[H6740]', 'lemma', 'heb', 'צָלִי', '["tsâlîy"]', '["roasted meat","roasted of"]', '["n-m"]', 'roasted roast.', 'passive participle of 6740;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4844}/[H4843]', 'lemma', 'heb', 'מְרֹר', '["mᵉrôr"]', '["bitter herbs"]', '["n-m"]', 'a bitter herb bitter(-ness).', 'or מְרוֹר; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4995}/[H5106]', 'lemma', 'heb', 'נָא', '["nâʼ"]', '["raw"]', '["a"]', 'properly, tough, i.e. uncooked (flesh) raw.', 'apparently from 5106 in the sense of harshness from refusal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1311}/[H1310]', 'inflected', 'heb', 'בָּשֵׁל', '["bâshêl"]', '["and/ boiled"]', '["a"]', 'boiled × at all, sodden.', 'from 1310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4325G}/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["<in> the/ waters","<in>/ [the] water of","[is] in the/ water","[is] in the/ waters","[was] in/ waters","[will be] in/ waters","at the/ waters","at/ [the] waters of","by/ [the] water of","in <the>/ water","in the/ water","in the/ waters","in/ [the] waters","in/ [the] waters of","in/ water of","in/ waters","on the/ waters","on/ [the] waters","on/ waters","with <the>/ water","with/ water"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3767}/H9023/[H3766]', 'inflected', 'heb', 'כָּרָע', '["kârâʻ"]', '["legs/ its"]', '["n-f"]', 'the leg (from the knee to the ankle) of men or locusts (only in the dual) leg.', 'from 3766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7130H}/H9023/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["entrails/ its"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3498}/[H3498]', 'inflected', 'heb', 'יָתַר', '["yâthar"]', '["and/ <the>/ [one who is] left behind","and/ <the>/ [what] remains","and/ the/ remainder","and/ those/ [who] were left behind","and/ what/ is left over"]', '["v"]', 'to jut over or exceed; by implication, to excel; (intransitively) to remain or be left; causatively to leave, cause to abound, preserve excel, leave (a remnant), left behind, too much, make plenteous, preserve, (be, let) remain(-der, -ing, -nant), reserve, residue, rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8313}/[H8313]', 'lemma', 'heb', 'שָׂרַף', '["sâraph"]', '["I burned","[are] burned","[have been] burned","[it is] burned","[it was] burned","[were] burning","burned","certainly <to burn>","he burned","he burns","he had burned","he has burned","he will be burned","he will burn","it had been burned","it will be burned","it will burn","people will burn","they burn","they burned","they have burned","they will be burned","they will burn","to burn","we had burned","we should burn","we will burn","will they be burned?","you burned","you will burn"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3602}/[H3541]', 'inflected', 'heb', 'כָּכָה', '["kâkâh"]', '["and/ thus"]', '["adv"]', 'just so, referring to the previous or following context after that (this) manner, this matter, (even) so, in such a case, thus.', 'from 3541;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4975>/H9026', 'opaque', 'heb', 'מֹתֶן', '["môthen"]', '["loins/ your"]', '["n-m"]', 'properly, the waist or small of the back; only in plural the loins greyhound, loins, side.', 'from an unused root meaning to be slender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2296}/[H2296]', 'lemma', 'heb', 'חָגַר', '["châgar"]', '["[one who] girds on","[was] girded","[were] girded","gird","gird on","gird up","gird yourself","gird yourselves","girded","he will gird himself","she girds","they gird on","they have girded on","they will gird themselves","you will gird on"]', '["v"]', 'to gird on (as a belt, armor, etc.) be able to put on, be afraid, appointed, gird, restrain, × on every side.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5275}/H9026/[H5274]', 'inflected', 'heb', 'נַעַל', '["naʻal"]', '["sandals/ your"]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7272}/H9026/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["[will be] on/ feet/ your","on/ feet/ your","with/ feet/ your"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4731>/H9026', 'inflected', 'heb', 'ומקלכם', '["u./ma.kel./Khem"]', '["and/ staff/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2649}/[H2468]', 'inflected', 'heb', 'חִפָּזוֹן', '["chippâzôwn"]', '["in/ haste"]', '["n-m"]', 'hasty flight haste.', 'from 2468;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6453}/[H6452]', 'lemma', 'heb', 'פֶּסַח', '["peçach"]', '["[is] a passover","a passover","passover"]', '["n-m"]', 'a pretermission, i.e. exemption; used only techically of the Jewish Passover (the festival or the victim) passover (offering).', 'from 6452;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8201}/[H8199]', 'lemma', 'heb', 'שֶׁפֶט', '["shepheṭ"]', '["acts of judgment","judgment<s>","judgments"]', '["n-m"]', 'a sentence, i.e. infliction judgment.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6452A}/[H6452]', 'inflected', 'heb', 'פָּסַח', '["pâçach"]', '["and/ I will pass over","and/ he will pass over"]', '["v"]', 'to hop, i.e. (figuratively) skip over (or spare); by implication, to hesitate; also (literally) to limp, to dance halt, become lame, leap, pass over.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9036}', 'inflected', 'heb', 'בכם', '["Ba./khem","ba./Khem","va./Khem"]', '["<in> <the>/ you","<in>/ you","[be] among <the>/ you","[is] among/ you","against <the>/ you","against/ you","among <the>/ you","among/ you","by/ you","in <the>/ you","in <the>/ yourselves","in/ you","on <the>/ you","on <the>/ yourselves","on/ you","over <the>/ you","with <the>/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5063}/[H5062]', 'lemma', 'heb', 'נֶגֶף', '["negeph"]', '["a plague","striking"]', '["n-m"]', 'a trip (of the foot); figuratively, an infliction (of disease) plague, stumbling.', 'from 5062;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4889}/[H7843]', 'inflected', 'heb', 'מַשְׁחִית', '["mashchîyth"]', '["for/ destruction","into/ destruction","to/ destruction"]', '["n-m"]', 'destructive, i.e. (as noun) destruction, literally (specifically a snare) or figuratively (corruption) corruption, (to) destroy(-ing), destruction, trap, × utterly.', 'from 7843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5221}/H9040/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["when/ strike down/ I","when/ strike/ I"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2146}/[H2142]', 'inflected', 'heb', 'זִכְרוֹן', '["zikrôwn"]', '["<into>/ a memorial","<into>/ a reminder","to/ a memorial"]', '["n-m"]', 'a memento (or memorable thing, day or writing) memorial, record.', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2287}/[H2283]', 'inflected', 'heb', 'חָגַג', '["châgag"]', '["and/ you will celebrate a festival"]', '["v"]', 'properly, to move in a circle, i.e. (specifically) to march in a sacred procession, to observe a festival; by implication, to be giddy celebrate, dance, (keep, hold) a (solemn) feast (holiday), reel to and fro.', 'a primitive root (compare 2283, 2328);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2708}/[H2706]', 'lemma', 'heb', 'חֻקָּה', '["chuqqâh"]', '["<the> statute of","[are] [the] statutes of","[is] [the] statute of","[it will be] a statute of","[the] appointments of","[the] customs of","[the] fixed order<s> of","[the] statutes of","a prescribed portion of","a statute","a statute of","statutes of"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2287}/H9033/[H2283]', 'inflected', 'heb', 'חָגַג', '["châgag"]', '["you will celebrate as a festival/ it"]', '["v"]', 'properly, to move in a circle, i.e. (specifically) to march in a sacred procession, to observe a festival; by implication, to be giddy celebrate, dance, (keep, hold) a (solemn) feast (holiday), reel to and fro.', 'a primitive root (compare 2283, 2328);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4682}/[H4711]', 'lemma', 'heb', 'מַצָּה', '["matstsâh"]', '["unleavened bread","unleavened bread<s>"]', '["n-f"]', 'properly, sweetness; concretely, sweet (i.e. not soured or bittered with yeast); specifically, an unfermented cake or loaf, or (elliptically) the festival of Passover (because no leaven was then used) unleaved (bread, cake), without leaven.', 'from 4711 in the sense of greedily devouring for sweetness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7603}/[H7604]', 'lemma', 'heb', 'שְׂאֹר', '["sᵉʼôr"]', '["leaven"]', '["n-m"]', 'barm or yeast-cake (as swelling by fermentation) leaven.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004B}/H9026/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ houses/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2557A}/[H2556]', 'lemma', 'heb', 'חָמֵץ', '["châmêts"]', '["leaven"]', '["n-m"]', 'ferment, (figuratively) extortion leaven, leavened (bread).', 'from 2556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3478}/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["[are] from/ Israel","[were] from/ Israel","from/ Israel","of/ Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H3117G>', 'inflected', 'heb', 'ובימים', '["u./vai./Yom","u./vai./yOm","u./vai./ya.Mim","u./ve./Yom","u./ve./yOm","u./vi./Mei","u/v./ya.Mim"]', '["and/ [is] on the/ day","and/ [will be] on the/ day","and/ in the/ days","and/ in/ [the] day of","and/ in/ [the] days","and/ in/ [the] days of","and/ in/ days","and/ in/ days of","and/ on the/ day","and/ on/ [the] day","and/ on/ [the] day of","and/ on/ a day of","and/ on/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4744}/[H7121]', 'lemma', 'heb', 'מִקְרָא', '["miqrâʼ"]', '["a convocation of","convocation[s]","convocations of"]', '["n-m"]', 'something called out, i.e. a public meeting (the act, the persons, or the place); also a rehearsal assembly, calling, convocation, reading.', 'from 7121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4399}/[H4397]', 'lemma', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["<of> business","[the] work","[the] work of","[the] workmanship of","[the] works of","a work","work","work of","workmanship","workmanship of"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4682}/[H4711]', 'inflected', 'heb', 'מַצָּה', '["matstsâh"]', '["<the>/ unleavened bread<s>","the/ unleavened bread<s>"]', '["n-f"]', 'properly, sweetness; concretely, sweet (i.e. not soured or bittered with yeast); specifically, an unfermented cake or loaf, or (elliptically) the festival of Passover (because no leaven was then used) unleaved (bread, cake), without leaven.', 'from 4711 in the sense of greedily devouring for sweetness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635A}/H9026/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["hosts/ your"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0702}/[H7251]', 'inflected', 'heb', 'אַרְבַּע', '["ʼarbaʻ"]', '["<in>/ [the] four","[were] in/ [the] four","by/ four-","in/ four-","on/ [day] four","on/ [day] four-","on/ [the] four","on/ [the] four-","on/ four-"]', '["n"]', 'four four.', 'masculine אַרְבָּעָה; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004B}/H9026/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[is] in/ houses/ your","in/ houses/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2556A}/[H2556]', 'lemma', 'heb', 'חָמֵץ', '["châmêts"]', '["a thing leavened","it was embittered","it was leavened","thing leavened"]', '["v"]', 'to be pungent; i.e. in taste (sour, i.e. literally fermented, or figuratively, harsh), in color (dazzling) cruel (man), dyed, be grieved, leavened.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5712}/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["from/ [the] congregation of"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1616}/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["in the/ sojourner"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0249}/[H2224]', 'inflected', 'heb', 'אֶזְרָח', '["ʼezrâch"]', '["and/ in/ [the] native-born of"]', '["n-m"]', 'a spontaneous growth, i.e. native (tree or persons) bay tree, (home-) born (in the land), of the (one''s own) country (nation).', 'from 2224 (in the sense of springing up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4186}/H9026/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["dwelling places/ your"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4682}\/[H4711]', 'inflected', 'heb', 'מַצָּה', '["matstsâh"]', '["unleavened bread<s>"]', '["n-f"]', 'properly, sweetness; concretely, sweet (i.e. not soured or bittered with yeast); specifically, an unfermented cake or loaf, or (elliptically) the festival of Passover (because no leaven was then used) unleaved (bread, cake), without leaven.', 'from 4711 in the sense of greedily devouring for sweetness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4900}/[H4900]', 'lemma', 'heb', 'מָשַׁךְ', '["mâshak"]', '["[one who] prolongs","[those who] draw","[those who] draw along","[those who] march","deferred","draw","he drew","he stretched out","he will follow","it has dragged","it will be postponed","prolong","tall","they have drawn down","they will be prolonged","will you draw out?","will you prolong?"]', '["v"]', 'to draw, used in a great variety of applications (including to sow, to sound, to prolong, to develop, to march, to remove, to delay, to be tall, etc.) draw (along, out), continue, defer, extend, forbear, × give, handle, make (pro-, sound) long, × sow, scatter, stretch out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4940}/H9026/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["to/ clans/ your"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7819A}/[H7819]', 'inflected', 'heb', 'שָׁחַט', '["shâchaṭ"]', '["and/ slaughter","and/ they are slaughtering"]', '["v n-f"]', 'to slaughter (in sacrifice or massacre) kill, offer, shoot out, slay, slaughter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6453}/[H6452]', 'inflected', 'heb', 'פֶּסַח', '["peçach"]', '["the/ passover","the/ passovers"]', '["n-m"]', 'a pretermission, i.e. exemption; used only techically of the Jewish Passover (the festival or the victim) passover (offering).', 'from 6452;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0092>', 'opaque', 'heb', 'אֲגֻדָּה', '["ʼăguddâh"]', '["[the] bindings of","a bunch of"]', '["n-f"]', 'a band, bundle, knot, or arch bunch, burden, troop.', 'feminine passive participle of an unused root (meaning to bind);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0231}/[H231]', 'lemma', 'heb', 'אֵזוֹב', '["ʼêzôwb"]', '["hyssop"]', '["n-m"]', 'hyssop hyssop.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5592A}/[H5605]', 'inflected', 'heb', 'סַף', '["çaph"]', '["[is] in the/ basin"]', '["n-m"]', 'a vestibule (as a limit); also a dish (for holding blood or wine) bason, bowl, cup, door (post), gate, post, threshold.', 'from 5605, in its original sense of containing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5062}/[H5062]', 'inflected', 'heb', 'נָגַף', '["nâgaph"]', '["to/ strike","to/ strike [you]"]', '["v"]', 'to push, gore, defeat, stub (the toe), inflict (a disease) beat, dash, hurt, plague, slay, smite (down), strike, stumble, × surely, put to the worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7843}/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["<the>/ corrupt","<the>/ destroying","the/ destroyer","which/ are ruining","who/ destroys"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9026/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["houses/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1121G}/H9021/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ for/ children/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6452A}/[H6452]', 'lemma', 'heb', 'פָּסַח', '["pâçach"]', '["he passed over","he will pass over [it]"]', '["v"]', 'to hop, i.e. (figuratively) skip over (or spare); by implication, to hesitate; also (literally) to limp, to dance halt, become lame, leap, pass over.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5062}/H9043/[H5062]', 'inflected', 'heb', 'נָגַף', '["nâgaph"]', '["when/ struck/ he"]', '["v"]', 'to push, gore, defeat, stub (the toe), inflict (a disease) beat, dash, hurt, plague, slay, smite (down), strike, stumble, × surely, put to the worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9025/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["houses/ our"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2677}/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["at the/ middle","in the/ middle","in/ [the] middle of"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7628A}/[H7618]', 'inflected', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["<the>/ captivity","the/ captive[s]","the/ captivity","the/ prisoner"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1696G}/H9046/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["as/ said/ you"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1241}/H9026/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["herd[s]/ your"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4116A}/[H4116]', 'inflected', 'heb', 'מָהַר', '["mâhar"]', '["to/ [people] hasty of","to/ hurry"]', '["v"]', 'properly, to be liquid or flow easily, i.e. (by implication); to hurry (in a good or a bad sense); often used (with another verb) adverbially, promptly be carried headlong, fearful, (cause to make, in, make) haste(-n, -ily), (be) hasty, (fetch, make ready) × quickly, rash, × shortly, (be so) × soon, make speed, × speedily, × straightway, × suddenly, swift.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1217}/H9023/[H1216]', 'inflected', 'heb', 'בָּצֵק', '["bâtsêq"]', '["dough/ its"]', '["n-m"]', 'dough (as swelling by fermentation) dough, flour.', 'from 1216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4863}/H9028/[H7604]', 'inflected', 'heb', 'מִשְׁאֶרֶת', '["mishʼereth"]', '["kneading troughs/ their"]', '["n-f"]', 'a kneading-trough (in which the dough rises) kneading trough, store.', 'from 7604 in the original sense of swelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6887B}/[H6887]', 'lemma', 'heb', 'צָרַר', '["tsârar"]', '["[he] binds up","[is] bound up","[were] bound up","bind up","bound up","harassed","has he wrapped","he will lay siege","it has wrapped","it is distress","it is narrow","locked up"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8071}/H9028/[H5566]', 'inflected', 'heb', 'שִׂמְלָה', '["simlâh"]', '["in/ clothes/ their"]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7926}/H9028/[H7925]', 'inflected', 'heb', 'שְׁכֶם', '["shᵉkem"]', '["shoulder/ their"]', '["n-m"]', 'the neck (between the shoulders) as the place of burdens; figuratively, the spur of a hill back, × consent, portion, shoulder.', 'from 7925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7592}/H9038/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["and/ I asked/ them","and/ they granted [the] request/ them"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7486G}/[H7486]', 'inflected', 'heb', 'רַעְמְסֵס', '["Raʻmᵉçêç"]', '["from/ Rameses"]', '["n-pr-loc"]', 'Rameses or Raamses, a place in Egypt Raamses, Rameses.', 'or רַעַמְסֵס; of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5523H}/H9011/[H5521]', 'inflected', 'heb', 'סֻכּוֹת', '["Çukkôwth"]', '["Succoth/ towards"]', '["n-pr-loc"]', 'Succoth, the name of a place in Egypt and of three in Palestine Succoth.', 'or סֻכֹּת; plural of 5521; booths;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8337}/[H7797]', 'inflected', 'heb', 'שֵׁשׁ', '["shêsh"]', '["[was] about/ six","[were] about/ six","about/ six"]', '["n"]', 'six (as an overplus beyond five or the fingers of the hand); as ordinal sixth six(-teen, -teenth), sixth.', 'masculine שִׁשָּׁה; a primitive number; see 7797');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7273}/[H7272]', 'lemma', 'heb', 'רַגְלִי', '["raglîy"]', '["foot soldier[s]","foot soldiers","on foot"]', '["a"]', 'a footman (soldier) (on) foot(-man).', 'from 7272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0905H}/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["<to>/ alone","<to>/ apart","<to>/ only"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2945}/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["from/ little one[s]"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6154M}/[H6148]', 'lemma', 'heb', 'עֵרֶב', '["ʻêreb"]', '["a mixed company","person of mixed ancestry"]', '["n-m"]', 'the web (or transverse threads of cloth); also a mixture, (or mongrel race) Arabia, mingled people, mixed (multitude), woof.', 'or עֶרֶב; (1 Kings 10:15), (with the article prefix), from 6148;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6629G>', 'inflected', 'heb', 'וצאן', '["va./Tzon","ve./Tzon","ve./tzoN"]', '["and/ [the] flock","and/ [the] flock of","and/ [the] sheep of","and/ flock[s]","and/ sheep"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0644}/[H644]', 'inflected', 'heb', 'אָפָה', '["ʼâphâh"]', '["and/ he bakes","and/ they baked","and/ they will bake","and/ you will bake"]', '["v"]', 'to cook, especially to bake bake(-r, (-meats)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1217}/[H1216]', 'inflected', 'heb', 'בָּצֵק', '["bâtsêq"]', '["the/ dough"]', '["n-m"]', 'dough (as swelling by fermentation) dough, flour.', 'from 1216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4102}/[H4100]', 'inflected', 'heb', 'מָהַהּ', '["mâhahh"]', '["to/ delay"]', '["v"]', 'properly, to question or hesitate, i.e. (by implication) to be reluctant delay, linger, stay selves, tarry.', 'apparently a denominative from 4100;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4186}/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["and/ [the] dwelling of","and/ [the] seating of"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635A}/[H6633]', 'lemma', 'heb', 'צָבָא', '["tsâbâʼ"]', '["[are] a host","[the] armies of","[the] army","[the] army of","[the] host of","[the] hosts of","[the] military group of","an army of","armies","war of"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8107}/[H8104]', 'lemma', 'heb', 'שִׁמֻּר', '["shimmur"]', '["vigil<s>"]', '["n-m"]', 'an observance × be (much) observed.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3318H}/H9038/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["by/ bringing out/ them","to/ bring out/ them"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1755}/H9028\/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["to/ generations/ their"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8453A}/[H3427]', 'lemma', 'heb', 'תּוֹשָׁב', '["tôwshâb"]', '["a resident alien","a resident alien of"]', '["n-m"]', 'a dweller but not outlandish [5237]; especially (as distinguished from a native citizen [active participle of 3427] and a temporary inmate [1616] or mere lodger [3885]) resident alien foreigner, inhabitant, sojourner, stranger.', 'or תֹּשָׁב; (1 Kings 17:1), from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7916}/[H7936]', 'inflected', 'heb', 'שָׂכִיר', '["sâkîyr"]', '["and/ a hired laborer"]', '["a"]', 'a man at wages by the day or year hired (man, servant), hireling.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2351>/H9011', 'opaque', 'heb', 'חוּץ', '["chûwts"]', '["[the] outside/ towards"]', '["n-m"]', 'properly, separate by a wall, i.e. outside, outdoors abroad, field, forth, highway, more, out(-side, -ward), street, without.', 'or (shortened) חֻץ; (both forms feminine in the plural) from an unused root meaning to sever;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6106G}/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["and/ [the] bones of","and/ a bone","and/ bones of"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0227A}/[H227]', 'inflected', 'heb', 'אָז', '["ʼâz"]', '["and/ then"]', '["adv"]', 'at that time or place; also as a conjunction, therefore beginning, for, from, hitherto, now, of old, once, since, then, at which time, yet.', 'a demonstrative adverb;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0249}/[H2224]', 'inflected', 'heb', 'אֶזְרָח', '["ʼezrâch"]', '["as the/ native","as the/ native-born","like/ [the] native-born","like/ [the] native-born of","like/ a native tree"]', '["n-m"]', 'a spontaneous growth, i.e. native (tree or persons) bay tree, (home-) born (in the land), of the (one''s own) country (nation).', 'from 2224 (in the sense of springing up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8451}/[H3384]', 'lemma', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["<of> [the] law","[is] [the] law of","[is] [the] legal [procedure] of","[is] instruction","[the] instruction","[the] instruction of","[the] law","[the] law of","[the] legal [procedure] of","a law","a legal [procedure]","instruction","instruction of","law","laws"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0249}/[H2224]', 'inflected', 'heb', 'אֶזְרָח', '["ʼezrâch"]', '["to the/ native-born"]', '["n-m"]', 'a spontaneous growth, i.e. native (tree or persons) bay tree, (home-) born (in the land), of the (one''s own) country (nation).', 'from 2224 (in the sense of springing up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1616}/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["and/ for the/ sojourner","and/ to the/ sojourner"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1481A}/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["who/ are sojourning","who/ sojourn","who/ sojourns"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635A}/H9028\/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["hosts/ their"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942H}/[H6942]', 'lemma', 'heb', 'קָדַשׁ', '["qâdash"]', '["I consecrate","[were] setting apart","certainly <to consecrate>","consecrate","he consecrated","he had consecrated","he will set apart as holy","they consecrated","they had consecrated","you will consecrate"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6363A}/[H6362]', 'lemma', 'heb', 'פֶּטֶר', '["peṭer"]', '["[the] firstborn of","firstborn of"]', '["n-m"]', 'a fissure, i.e. (concretely) firstling (as opening the matrix) firstling, openeth, such as open.', 'or פִּטְרָה; from 6362;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1121G}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["against/ [the] people of","among/ [the] people of","among/ [the] sons of","on/ [the] people of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2392}/[H2388]', 'inflected', 'heb', 'חֹזֶק', '["chôzeq"]', '["with/ strength of"]', '["n-m"]', 'power strength.', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0024>', 'inflected', 'heb', 'האביב', '["ha./''a.Viv"]', '["<the>/ Abib"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935P}/H9031/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["I will bring/ you","[will] bring/ you","bring/ you","did he bring/ you","he will bring/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5647H}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ I will serve","and/ he has served","and/ he made to serve","and/ he served","and/ he will serve","and/ it served","and/ they served","and/ they will serve","and/ we have served","and/ you have served","and/ you served","and/ you will serve"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121A}/H9021/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["for/ son/ your","for/ sons/ your","of/ children/ your","to/ child/ your","to/ children/ your","to/ son/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3318G}/H9040/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ came out/ I","when/ go out/ I","when/ went out/ I"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2146}/[H2142]', 'inflected', 'heb', 'זִכְרוֹן', '["zikrôwn"]', '["and/ <into>/ a reminder"]', '["n-m"]', 'a memento (or memorable thing, day or writing) memorial, record.', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6310G}/H9021/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["in/ mouth/ your","with/ mouth/ your"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2708}/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["the/ statute"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4150G}/H9024/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["to/ appointed time/ its"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3117I>', 'inflected', 'heb', 'מימים', '["mi./ya.Mim"]', '["from/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117I>/H9011\', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days/ towards"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0001G}/H9021/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ to/ ancestors/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414G}/H9034/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I gave/ it","and/ I give/ it","and/ I will give/ it","and/ he gave/ it","and/ he had given/ it","and/ he has given/ it","and/ he will give/ it","and/ we gave/ it","and/ you gave/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5674C}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["and/ he took away","and/ he took off","and/ they brought over","and/ you will dedicate","and/ you will take over"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7698>', 'opaque', 'heb', 'שֶׁגֶר', '["sheger"]', '["[the] offspring of","[the] young of"]', '["n-f"]', 'the fœtus (as finally expelled) that cometh of, increase.', 'from an unused root probably meaning to eject;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2145}/[H2142]', 'inflected', 'heb', 'זָכָר', '["zâkâr"]', '["the/ male","the/ males"]', '["n-m"]', 'properly, remembered, i.e. a male (of man or animals, as being the most noteworthy sex) × him, male, man(child, -kind).', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6299}/[H6299]', 'lemma', 'heb', 'פָּדָה', '["pâdâh"]', '["I redeem","[is] redeeming","certainly <to ransom>","certainly <to redeem>","he has ransomed","he redeemed","he will be redeemed","he will ransom","he will redeem","it will be redeemed","redeem","she had been released","you had redeemed","you have redeemed","you ransomed","you redeemed","you will redeem","you will redeem [it]"]', '["v"]', 'to sever, i.e. ransom; generally to release, preserve × at all, deliver, × by any means, ransom, (that are to be, let be) redeem(-ed), rescue, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7716}/[H7582]', 'inflected', 'heb', 'שֶׂה', '["seh"]', '["with/ a sheep"]', '["n-m"]', 'a member of a flock, i.e. a sheep or goat (lesser, small) cattle, ewe, goat, lamb, sheep. Compare 2089.', 'or שֵׂי; probably from 7582 through the idea of pushing out to graze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6202}/H9033/[H6203]', 'inflected', 'heb', 'עָרַף', '["ʻâraph"]', '["and/ you will break neck/ its"]', '["v"]', 'to break the neck; hence (figuratively) to destroy that is beheaded, break down, break (cut off, strike off) neck.', 'a primitive root (identical with through the idea of slopping); properly, to bend downward; but used only as a denominative from 6203,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1121A}/H9021/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["among/ sons/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7592}/H9031/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["I will ask/ you","he will ask/ you","it will ask/ you"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318H}/H9035/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["he brought out/ us","you brought out/ us"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7971H}/H9035/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["to/ let go/ us"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H2903>', 'inflected', 'heb', 'ולטוטפת', '["u./le./to.ta.Fot"]', '["and/ <into>/ marks"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4714G}\/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["from/ Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7971H}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["when/ let go"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5148}/H9038/[H5148]', 'inflected', 'heb', 'נָחָה', '["nâchâh"]', '["he led/ them","it guides/ them","will you guide?/ them","you guide/ them","you led/ them"]', '["v"]', 'to guide; by implication, to transport (into exile, or as colonists) bestow, bring, govern, guide, lead (forth), put, straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7200G}/H9048/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["when/ saw/ they","when/ see/ they"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2571}/[H2570]', 'inflected', 'heb', 'חָמֻשׁ', '["châmush"]', '["and/ arrayed for battle"]', '["a"]', 'staunch, i.e. able-bodied soldiers armed (men), harnessed.', 'passive participle of the same as 2570;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5523H}/[H5521]', 'inflected', 'heb', 'סֻכּוֹת', '["Çukkôwth"]', '["from/ Succoth"]', '["n-pr-loc"]', 'Succoth, the name of a place in Egypt and of three in Palestine Succoth.', 'or סֻכֹּת; plural of 5521; booths;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0864}/[H864]', 'inflected', 'heb', 'אֵתָם', '["ʼÊthâm"]', '["at/ Etham"]', '["n-pr-loc"]', 'Etham, a place in the Desert Etham.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3119}/[H3117]', 'lemma', 'heb', 'יוֹמָם', '["yôwmâm"]', '["by day","daytime"]', '["adv"]', 'daily daily, (by, in the) day(-time).', 'from 3117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5982G}/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["in/ a pillar of"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5148}/H9038/[H5148]', 'inflected', 'heb', 'נָחָה', '["nâchâh"]', '["to/ guide/ them","to/ lead/ them"]', '["v"]', 'to guide; by implication, to transport (into exile, or as colonists) bestow, bring, govern, guide, lead (forth), put, straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1870L}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["the/ journey","the/ way"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1980I}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["by/ walking","to <the>/ [those who] walk","to/ [those who] walk of","to/ go","to/ go about","to/ walk"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4185}/[H4184]', 'lemma', 'heb', 'מוּשׁ', '["mûwsh"]', '["I have ceased","he departed","he removes [it]","it departed","it departs","it will be removed","it will cease","it will depart","they departed","they will be removed","they will depart","you depart","you will remove"]', '["v"]', 'to withdraw (both literally and figuratively, whether intransitive or transitive) cease, depart, go back, remove, take away.', 'a primitive root (perhaps rather the same as 4184 through the idea of receding by contact);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5982G}/[H5975]', 'lemma', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["[are] pillars of","[the] pillar of","[the] pillars of","a pillar of","columns","pillars","pillars of"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6051}/[H6049]', 'inflected', 'heb', 'עָנָן', '["ʻânân"]', '["<the>/ cloud","the/ cloud"]', '["n-m"]', 'a cloud (as covering the sky), i.e. the nimbus or thunder-cloud cloud(-y).', 'from 6049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5982G}/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["and/ [the] pillar of","and/ [the] pillars of","and/ columns","and/ pillars","and/ pillars of"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2583}/[H2603]', 'inflected', 'heb', 'חָנָה', '["chânâh"]', '["and/ encamp","and/ they may encamp"]', '["v"]', 'properly, to incline; by implication, to decline (of the slanting rays of evening); specifically, to pitch a tent; generally to encamp (for abode or siege) abide (in tents), camp, dwell, encamp, grow to an end, lie, pitch (tent), rest in tent.', 'a primitive root (compare 2603);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6367}/[H6310]', 'lemma', 'heb', 'פִּי הַחִירֹת', '["Pîy ha-Chîyrôth"]', '["Pi-","hahiroth"]', '["n-pr-loc"]', 'Pi-ha-Chiroth, a place in Egypt Pi-hahiroth. (In Numbers 14:19 without Pi-.)', 'from 6310 and the feminine plural of a noun (from the same root as 2356), with the article interpolated; mouth of the gorges;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4024B}/[H4024]', 'lemma', 'heb', 'מִגְדּוֹל', '["Migdôwl"]', '["Migdol"]', '["n-pr-m n-m"]', 'Migdol, a place in Egypt Migdol, tower.', 'or מִגְדֹּל; probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1189}/[H1168]', 'lemma', 'heb', 'בַּעַל צְפוֹן', '["Baʻal Tsᵉphôwn"]', '["Baal-","Zephon"]', '["n-pr-loc"]', 'Baal-Tsephon, a place in Eqypt Baal-zephon.', 'from 1168 and 6828 (in the sense of cold) (according to others an Egyptian form of Typhon, the destroyer); Baal of winter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5227}/H9033/[H5226]', 'inflected', 'heb', 'נֹכַח', '["nôkach"]', '["opposite/ it"]', '["adv"]', 'properly, the front part; used adverbially (especially with preposition), opposite, in front of, forward, in behalf of (over) against, before, direct(-ly), for, right (on).', 'from the same as 5226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2583}/[H2603]', 'lemma', 'heb', 'חָנָה', '["chânâh"]', '["<of> [where] he camped","[are] encamping","[is] encamping","[was] encamped","[were] encamped","encamp","encamped","he had encamped","it will encamp","they camped","they encamped","they will encamp","to decline","you will encamp"]', '["v"]', 'properly, to incline; by implication, to decline (of the slanting rays of evening); specifically, to pitch a tent; generally to encamp (for abode or siege) abide (in tents), camp, dwell, encamp, grow to an end, lie, pitch (tent), rest in tent.', 'a primitive root (compare 2603);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0943}/[H943]', 'lemma', 'heb', 'בּוּךְ', '["bûwk"]', '["[are] wandering in confusion"]', '["v"]', 'to involve (literally or figuratively) be entangled, (perplexed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3513G}/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["and/ I may be honored","and/ I will gain honor","and/ I will glorify","and/ honored","so/ let me be honored","so/ they may glorify"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6547J}/[H6547]', 'inflected', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["by/ Pharaoh","on/ Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428A}/H9023/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["army/ his"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3824}/[H3823]', 'lemma', 'heb', 'לֵבָב', '["lêbâb"]', '["[the] heart","[the] heart of","[which the] heart of","a heart","a heart of","heart","heart of","hearts"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5647G}/H9035/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["from/ serving/ us"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7393G}/H9023/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["chariot/ his","chariot[s]/ its","chariotry/ his","chariotry/ its"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971K}/H9023/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["people/ his"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7991C}/[H7969]', 'inflected', 'heb', 'שָׁלִישׁ', '["shâlîysh"]', '["and/ officers"]', '["n-m"]', 'a triple, i.e. (as a musical instrument) a triangle (or perhaps rather three-stringed lute); also (as an indefinite, great quantity) a three-fold measure (perhaps a treble ephah); also (as an officer) a general of the third rank (upward, i.e. the highest) captain, instrument of musick, (great) lord, (great) measure, prince, three (from the margin).', 'or שָׁלוֹשׁ; (1 Chronicles 11:11; 1 Chronicles 12:18), or שָׁלֹשׁ; (2 Samuel 23:13), from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6571B}/H9023/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["and/ horsemen/ his","and/ horsemen/ its"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2428A}/H9023/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["and/ army/ his"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6547J}/[H6547]', 'inflected', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["and/ Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869A}/H9028/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eye/ their","eyes/ their"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9006/{H1097}/[H1086]', 'inflected', 'heb', 'בְּלִי', '["bᵉlîy"]', '["¿/ becasue/ not","¿/ because/ not"]', '["np"]', 'properly, failure, i.e. nothing or destruction; usually (with preposition) without, not yet, because not, as long as, etc. corruption, ig(norantly), for lack of, where no...is, so that no, none, not, un(awares), without.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947G}/H9035/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["you brought/ us"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3318H}/H9035/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["by/ bringing out/ us"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5647G}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ [were] serving","and/ serve","so/ let us serve"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4191}/H9045/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["than/ to die/ us"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3320}/[H3320]', 'lemma', 'heb', 'יָצַב', '["yâtsab"]', '["he takes his stand","he will stand","he will take his stand","present yourselves","stand","stand firm","take your stand","they take their stand","they took their stand","they will take their stand","will he stand","will he take his stand","you will stand"]', '["v"]', 'to place (any thing so as to stay); reflexively, to station, offer, continue present selves, remaining, resort, set (selves), (be able to, can, with-) stand (fast, forth, -ing, still, up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3444}/[H3467]', 'lemma', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["[is] deliverance","[the] deliverance of","[the] salvation of","[the] salvation<s> of","[the] victories of","[the] victory of","deliverance<s>","of [the] salvation<s> of","rescue","salvation","salvation<s>"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7200G}/H9038/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["to/ see/ them"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3898A}/[H3898]', 'lemma', 'heb', 'לָחַם', '["lâcham"]', '["I have fought","[are] fighting","[is] fighting","[is] waging war","[one who] fights","[was] fighting","[were] fighting","did he wage war","ever <to wage war>","fight","fighting","he fought","he had fought","he had waged war","he waged war","he will fight","it will fight","let us do battle","they fought","they waged war","you do battle","you must do battle","you must fight","you will fight"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2790B}/H9013\/[H2790]', 'inflected', 'heb', 'חָרַשׁ', '["chârash"]', '["you will keep quiet/ !"]', '["v"]', 'to scratch, i.e. (by implication) to engrave, plough; hence (from the use of tools) to fabricate (of any material); figuratively, to devise (in a bad sense); hence (from the idea of secrecy) to be silent, to let alone; hence (by implication) to be deaf (as an accompaniment of dumbness) × altogether, cease, conceal, be deaf, devise, ear, graven, imagine, leave off speaking, hold peace, plow(-er, man), be quiet, rest, practise secretly, keep silence, be silent, speak not a word, be still, hold tongue, worker.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1234}/H9033/[H1234]', 'inflected', 'heb', 'בָּקַע', '["bâqaʻ"]', '["and/ divide/ it"]', '["v"]', 'to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3004}/[H3001]', 'inflected', 'heb', 'יַבָּשָׁה', '["yabbâshâh"]', '["on the/ dry ground"]', '["n-f"]', 'dry ground dry (ground, land).', 'from 3001;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7393G}/H9023/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["by/ chariot[s]/ his","in/ chariot/ his","with/ chariot[s]/ his"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6571B}/H9023/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["and/ by/ horsemen/ his","and/ with/ horsemen/ his"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3513G}/H9040/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["when/ gain honor/ I"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0310A}/H9038/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["<from>/ behind/ them","[was] from/ behind/ them","from/ after/ them","from/ behind/ them"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440G}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<from>/ because of/ them","from/ before/ them"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2822}/[H2821]', 'inflected', 'heb', 'חֹשֶׁךְ', '["chôshek"]', '["and/ the/ darkness"]', '["n-m"]', 'the dark; hence (literally) darkness; figuratively, misery, destruction, death, ignorance, sorrow, wickedness dark(-ness), night, obscurity.', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0215}/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["and/ he has given light","and/ it became light","and/ it lit up","and/ it will be light","and/ it will give light","and/ they brightened"]', '["v"]', 'to be (causative, make) luminous (literally and metaphorically) × break of day, glorious, kindle, (be, en-, give, show) light (-en, -ened), set on fire, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1980O}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ he drove"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7307H}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["[was] in the/ wind","by/ [the] breath of","by/ a wind","with/ a wind of"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2724}/[H2720]', 'inflected', 'heb', 'חָרָבָה', '["chârâbâh"]', '["into <the>/ dry ground"]', '["n-f"]', 'a desert dry (ground, land).', 'feminine of 2720;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2346G>', 'opaque', 'heb', 'חוֹמָה', '["chôwmâh"]', '["O wall of","[is] a wall","[the] wall","[the] wall of","[the] walls of","[was] a wall","a wall","a wall of","wall","walls"]', '["n-f"]', 'a wall of protection wall, walled.', 'feminine active participle of an unused root apparently meaning to join;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3225G}/H9028/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["from/ right/ their"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8040G}/H9028/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["and/ from/ left/ their"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8432>', 'opaque', 'heb', 'תָּוֶךְ', '["tâvek"]', '["[the] middle of","[the] midst of"]', '["n-m"]', 'a bisection, i.e. (by implication) the centre among(-st), × between, half, × (there-, where-), in(-to), middle, mid(-night), midst (among), × out (of), × through, × with(-in).', 'from an unused root meaning to sever;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0821}/[H8104]', 'inflected', 'heb', 'אַשְׁמֻרָה', '["ʼashmurâh"]', '["in/ [the] night-watches","in/ [the] watch of"]', '["n-f"]', 'a night watch watch.', 'or אַשׁמוּרָה; or אַשׁמֹרֶת; (feminine) from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6051}/[H6049]', 'inflected', 'heb', 'עָנָן', '["ʻânân"]', '["and/ [the] cloud of","and/ a cloud","and/ cloud"]', '["n-m"]', 'a cloud (as covering the sky), i.e. the nimbus or thunder-cloud cloud(-y).', 'from 6049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2000}/[H1949]', 'inflected', 'heb', 'הָמַם', '["hâmam"]', '["and/ I will confuse","and/ he confused","and/ he routed","and/ he routed [them]","and/ he sets in motion"]', '["v"]', 'properly, to put in commotion; by implication, to disturb, drive, destroy break, consume, crush, destroy, discomfit, trouble, vex.', 'a primitive root (compare 1949, 1993);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0212>', 'opaque', 'heb', 'אוֹפָן', '["ʼôwphân"]', '["<the> wheel of","[the] wheel[s] of","a wheel","wheels","wheels of"]', '["n-m"]', 'a wheel wheel.', 'or (shortened) אֹפָן; from an unused root meaning to revolve;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5090A}/H9033/[H5090]', 'inflected', 'heb', 'נָהַג', '["nâhag"]', '["and/ he caused to drive/ it"]', '["v"]', 'to drive forth (a person, an animal or chariot), i.e. lead, carry away; reflexively, to proceed (i.e. impel or guide oneself); also (from the panting induced by effort), to sigh acquaint, bring (away), carry away, drive (away), lead (away, forth), (be) guide, lead (away, forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3517}/[H3515]', 'inflected', 'heb', 'כְּבֵדֻת', '["kᵉbêduth"]', '["with/ difficulty"]', '["n-f"]', 'difficulty × heavily.', 'feminine of 3515;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4714G}\/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["against/ Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6571B}/H9023/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["horsemen/ its","warhorses/ its"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0386>/H9023', 'inflected', 'heb', 'לאיתנו', '["le./''Ei.ta.N/o"]', '["to/ normal [state]/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4714G}/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["and/ Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122H}/H9033/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ him","to/ meet/ it"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5287}/[H5286]', 'inflected', 'heb', 'נָעַר', '["nâʻar"]', '["and/ he shook off"]', '["v"]', 'to tumble about shake (off, out, self), overthrow, toss up and down.', 'a primitive root (probably identical with 5286, through the idea of the rustling of mane, which usually accompanies the lion''s roar);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7393G}/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["<the>/ chariotry","O/ chariotry","the/ chariot","the/ chariot[s]","the/ chariotry"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6571B}/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["the/ horsemen","the/ horses"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428A}/[H2342]', 'lemma', 'heb', 'חַיִל', '["chayil"]', '["[the] army","[the] army of","an army","an army of","an escort","armies","army","army of","strength","strength<s>"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3467}/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ I will save","and/ he delivered","and/ he gave victory","and/ he gave victory to","and/ he saved","and/ he will deliver","and/ he will save","and/ it gave victory","and/ you will be delivered","and/ you will deliver"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3027H}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["the/ hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4872}/[H4871]', 'inflected', 'heb', 'מֹשֶׁה', '["Môsheh"]', '["and/ against/ Moses","and/ in/ Moses"]', '["n-pr-m"]', 'Mosheh, the Israelite lawgiver Moses.', 'from 4871; drawing out (of the water), i.e. rescued;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5650}/H9023\/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["servant/ his","servants/ his"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7891}/[H7788]', 'lemma', 'heb', 'שִׁיר', '["shîyr"]', '["I will sing","[male] singers","[those who] sang","[was] singing","he sang","it sang","it will be sung","it will sing","let me sing","male singers","sing","singers","they have sung","they sang","they sing","we will sing","will we sing"]', '["v"]', 'to sing behold (by mistake for 7789), sing(-er, -ing man, -ing woman).', 'or (the original form) שׁוּר; (1 Samuel 18:6), a primitive root (rather identical with 7788 through the idea of strolling minstrelsy);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7892B}/[H7891]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["the/ song"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1342}/[H1342]', 'lemma', 'heb', 'גָּאָה', '["gâʼâh"]', '["certainly <to exalted>","he is exalted","they had risen"]', '["v"]', 'to mount up; hence, in general, to rise, (figuratively) be majestic gloriously, grow up, increase, be risen, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7392}/H9023/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["and/ rider/ its","and/ rider[s]/ its"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7411A}/[H7411]', 'lemma', 'heb', 'רָמָה', '["râmâh"]', '["he has thrown","shooters of"]', '["v"]', 'to hurl; specifically, to shoot; figuratively, to delude or betray (as if causing to fall) beguile, betray, (bow-) man, carry, deceive, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5797}/H9020/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["O strength/ my","[is] might/ my","[is] strength/ my","strength/ my"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2176}/[H2167]', 'inflected', 'heb', 'זִמְרָת', '["zimrâth"]', '["and/ strength"]', '["n-f"]', 'instrumental music; by implication, praise song.', 'from 2167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3050}/[H3068]', 'lemma', 'heb', 'יָהּ', '["Yâhh"]', '["O Yahweh","Yahweh"]', '["n-pr"]', 'Jah, the sacred name Jah, the Lord, most vehement. Compare names in ''-iah,'' ''-jah.''', 'contraction for 3068, and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3444}/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["<into>/ deliverance","<into>/ salvation","[will be] for/ deliverance","for/ deliverance","for/ salvation"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0410G}/H9020/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["God/ my","O God/ my","[are] God/ my","[have been] God/ my","[is] God/ my"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5115A}/H9033/[H5116]', 'inflected', 'heb', 'נָוָה', '["nâvâh"]', '["and/ I will glorify/ him"]', '["v"]', 'to rest (as at home); causatively (through the implied idea of beauty), to celebrate (with praises) keep at home, prepare an habitation.', 'a primitive root; (compare 5116)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7311A}/H9033/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["and/ I will exalt/ him","and/ let them exalt/ him"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4818}/[H4817]', 'lemma', 'heb', 'מֶרְכָּבָה', '["merkâbâh"]', '["[the] chariots of","a chariot","chariotry","chariots"]', '["n-f"]', 'a chariot chariot. See also 1024.', 'feminine of 4817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3384A}/[H3384]', 'lemma', 'heb', 'יָרָה', '["yârâh"]', '["I will shoot","[am] about to shoot","[which] it waters","certainly <to shot>","did he lay","he had shot","he has thrown","he shot","he will be given water","he will be shot","he will shoot","shoot","they will shoot"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4005}/[H977]', 'inflected', 'heb', 'מִבְחָר', '["mibchâr"]', '["and/ [the] choicest of"]', '["n-m"]', 'select, i.e. best choice(-st), chosen.', 'from 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7991C}/H9023/[H7969]', 'inflected', 'heb', 'שָׁלִישׁ', '["shâlîysh"]', '["officer/ his","officers/ his"]', '["n-m"]', 'a triple, i.e. (as a musical instrument) a triangle (or perhaps rather three-stringed lute); also (as an indefinite, great quantity) a three-fold measure (perhaps a treble ephah); also (as an officer) a general of the third rank (upward, i.e. the highest) captain, instrument of musick, (great) lord, (great) measure, prince, three (from the margin).', 'or שָׁלוֹשׁ; (1 Chronicles 11:11; 1 Chronicles 12:18), or שָׁלֹשׁ; (2 Samuel 23:13), from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2883}/[H2883]', 'lemma', 'heb', 'טָבַע', '["ṭâbaʻ"]', '["I have sunk","I sink","they are sunk","they have been sunk","they have sunk","they were planted","were they sunk"]', '["v"]', 'to sink drown, fasten, settle, sink.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3680}/H9038/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["it covered/ them","may it cover/ them","they have covered/ them"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4688}/[H6683]', 'inflected', 'heb', 'מְצוֹלָה', '["mᵉtsôwlâh"]', '["in/ [the] deep","in/ [the] depths","in/ [the] depths of"]', '["n-f"]', 'a deep place (of water or mud) bottom, deep, depth.', 'or מְצֹלָה; also מְצוּלָה; or מְצֻלָה; from the same as 6683;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3644G}/[H3651]', 'lemma', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["[are] like","[be] like","[was] like","as","like"]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0142}/[H142]', 'lemma', 'heb', 'אָדַר', '["ʼâdar"]', '["[was] glorious","glorious"]', '["v"]', 'to expand, i.e. be great or (figuratively) magnificent (become) glorious, honourable.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3581B>', 'inflected', 'heb', 'בכח', '["ba./Ko.ach","be./Kho.ach","va./Ko.ach","ve./Kho.ach"]', '["[is] by/ [the] strength of","[is] with <the>/ strength","by/ [the] strength of","by/ power","by/ strength","in <the>/ power","in/ [the] strength of","in/ strength","with <the>/ strength","with/ power","with/ power of","with/ strength"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7492}/[H7492]', 'lemma', 'heb', 'רָעַץ', '["râʻats"]', '["it shattered"]', '["v"]', 'to break in pieces; figuratively, harass dash in pieces, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0341}/[H340]', 'lemma', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["[are the] enemies of","[the] enemies of","[the] enemy","[was] an enemy","an enemy","enemies"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7230}/[H7231]', 'inflected', 'heb', 'רֹב', '["rôb"]', '["and/ by/ [the] greatness of","and/ in/ [the] abundance of","and/ in/ [the] greatness of","and/ with/ multitude of"]', '["n-m"]', 'abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age).', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1347}/H9021/[H1342]', 'inflected', 'heb', 'גָּאוֹן', '["gâʼôwn"]', '["majesty/ your","pride/ your"]', '["n-m"]', 'the same as 1346 arrogancy, excellency(-lent), majesty, pomp, pride, proud, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2040}/[H2040]', 'lemma', 'heb', 'הָרַס', '["hâraç"]', '["I will tear [them] down","I will tear [you] down","I will tear down","[am] about to tear down","break away","completely <tear down>","he has torn down","he tears down","he tore down","it is torn down","it was broken down","it will be torn down","they break through","they have torn down","they should break through","they tore down","they will be torn down","you threw down"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965J}/H9031/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["[those who] rise against/ you","[those who] rose against/ you"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2740}/H9021/[H2734]', 'inflected', 'heb', 'חָרוֹן', '["chârôwn"]', '["anger/ your","anger<s>/ your"]', '["n-m"]', 'a burning of anger sore displeasure, fierce(-ness), fury, (fierce) wrath(-ful).', 'or (shortened) חָרֹן; from 2734;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0398}/H9038/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["[am] about to feed/ them","it consumed/ them","it will consume/ them","it will devour/ them","it will eat/ them","she will eat/ them","they devoured/ them","they will eat/ them","you have fed/ them","you must eat/ them"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7179}/[H7197]', 'inflected', 'heb', 'קַשׁ', '["qash"]', '["like <the>/ chaff","like <the>/ stubble","like/ chaff"]', '["n-m"]', 'straw (as dry) stubble.', 'from 7197;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7307H}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ by/ [the] breath of","and/ with/ [the] breath of"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639H}/H9021/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["nostril[s]/ your","nostrils/ your"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6192}/[H6192]', 'lemma', 'heb', 'עָרַם', '["ʻâram"]', '["they were piled up"]', '["v"]', 'to pile up gather together.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5067}/[H5110]', 'lemma', 'heb', 'נֵד', '["nêd"]', '["a heap"]', '["n-m"]', 'a mound, i.e. wave heap.', 'from 5110 in the sense of piling up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5140}/[H5140]', 'lemma', 'heb', 'נָזַל', '["nâzal"]', '["flowing","he caused to flow","it will flow","let them flow","may it distil","streams","they flow","they flowed","they may flow"]', '["v"]', 'to drip, or shed by trickling distil, drop, flood, (cause to) flow(-ing), gush out, melt, pour (down), running water, stream.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7087A}/[H7087]', 'lemma', 'heb', 'קָפָא', '["qâphâʼ"]', '["they congealed"]', '["v n-m"]', 'to shrink, i.e. thicken (as unracked wine, curdled milk, clouded sky, frozen water) congeal, curdle, dark, settle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3820A}/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["[are] in/ [the] heart of","[is] in/ [the] heart of","[were] in/ [the] heart of","in/ [the] heart","in/ [the] heart of","with/ a heart"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4390}/H9038/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["it will be full of/ them"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315L}/H9020/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["appetite/ my","desire/ my","self/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2719}/H9020/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["sword/ my"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423H}/H9038/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["I will dispossess/ them","[is] dispossessing/ them","it will dispossess/ them","they dispossessed/ them","to dispossess/ them"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5398}/[H5398]', 'lemma', 'heb', 'נָשַׁף', '["nâshaph"]', '["he blows","you blew"]', '["v"]', 'to breeze, i.e. blow up fresh (as the wind) blow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7307H}/H9021/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["with/ breath/ your"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6749}/[H6749]', 'lemma', 'heb', 'צָלַל', '["tsâlal"]', '["they sank"]', '["v"]', 'properly, to tumble down, i.e. settle by a waving motion sink. Compare 6750, 6751.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5777}/[H6080]', 'inflected', 'heb', 'עוֹפֶרֶת', '["ʻôwphereth"]', '["like <the>/ lead"]', '["n-m"]', 'lead (from its dusty color) lead.', 'or עֹפֶרֶת; feminine participle active of 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0117}/[H142]', 'lemma', 'heb', 'אַדִּיר', '["ʼaddîyr"]', '["O noble [ones] of","[are] majestic","[is] majestic","[the] noble [ones] of","[will be] majestic","majestic","majestic [trees]","mighty","nobles"]', '["a"]', 'wide or (generally) large; figuratively, powerful excellent, famous, gallant, glorious, goodly, lordly, mighty(-ier one), noble, principal, worthy.', 'from 142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0410K}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["among the/ gods"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6944G}/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["<in>/ [the] holy thing of","[is] in <the>/ holiness","in <the>/ holiness","in the/ holy place","in the/ holy things","in the/ sanctuary","in/ [the] holy place of","with/ [the] holy place"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8416}/[H1984]', 'lemma', 'heb', 'תְּהִלָּה', '["tᵉhillâh"]', '["[is] praise","[the] praise of","[the] praises of","[will be] [the] praise of","of praises","praise"]', '["n-f"]', 'laudation; specifically (concretely) a hymn praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6382}/[H6381]', 'lemma', 'heb', 'פֶּלֶא', '["peleʼ"]', '["<of> wonder[s]","[are] wonders","a wonder","wonder[s]","wonders"]', '["n-m"]', 'a miracle marvellous thing, wonder(-ful, -fully).', 'from 6381;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1104}/H9038/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["he will swallow up/ them","it swallowed up/ them","let us engulf/ them"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5148}/[H5148]', 'lemma', 'heb', 'נָחָה', '["nâchâh"]', '["it will guide","lead","you have guided","you led"]', '["v"]', 'to guide; by implication, to transport (into exile, or as colonists) bestow, bring, govern, guide, lead (forth), put, straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2617A}/H9021/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["in/ covenant loyalty/ your"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2098}/[H2088]', 'lemma', 'heb', 'זוּ', '["zûw"]', '["[the one] who","this","which","who","whom"]', '["d"]', 'this or that that, this, × wherein, which, whom.', 'for 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/[H1350]', 'lemma', 'heb', 'גָּאַל', '["gâʼal"]', '["I will redeem","[am] a kinsman-redeemer","[are] a kinsman-redeemer","[is] a kinsman-redeemer","[the] redeemed of","[the] redeemer of","[which] you redeemed","a kinsman-redeemer","a redeemer","certainly [if] <to redeem>","he has redeemed","he will be redeemed","he will redeem","it will be redeemed","let him redeem","redeem","redeemed [people]","you have redeemed","you redeemed","you will be redeemed","you will redeem"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5797}/H9021/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["by/ strength/ your","in/ strength/ your"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5116A}/[H5115]', 'lemma', 'heb', 'נָוֶה', '["nâveh"]', '["O abode of","[the] abode of","[the] habitation of","[the] pastureland","a habitation","a habitation of","pasture of","pastureland of","pastures of"]', '["n"]', '(adjectively) at home; hence (by implication of satisfaction) lovely; also (noun) a home, of God (temple), men (residence), flocks (pasture), or wild animals (den) comely, dwelling (place), fold, habitation, pleasant place, sheepcote, stable, tarried.', 'or (feminine) נָוָה; from 5115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6944G}/H9021/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["holiness/ your","holy things/ your"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7264}/H9013/[H7264]', 'inflected', 'heb', 'רָגַז', '["râgaz"]', '["they tremble/ !"]', '["v"]', 'to quiver (with any violent emotion, especially anger or fear) be afraid, stand in awe, disquiet, fall out, fret, move, provoke, quake, rage, shake, tremble, trouble, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2427A}/[H2342]', 'lemma', 'heb', 'חִיל', '["chîyl"]', '["anguish"]', '["n-m"]', 'a throe (expectant of childbirth) pain, pang, sorrow.', 'and (feminine) חִילָה; from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6429}/[H6428]', 'lemma', 'heb', 'פְּלֶשֶׁת', '["Pᵉlesheth"]', '["O Philistia","Philistia"]', '["n"]', 'Pelesheth, a region of Syria Palestina, Palestine, Philistia, Philistines.', 'from 6428; rolling, i.e. migratory;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0352C}/[H193]', 'lemma', 'heb', 'אַיִל', '["ʼayil"]', '["[the] leaders of","a leader of"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0270}/H9038/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["it has seized/ them","it seized/ them"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7461A}/[H7460]', 'lemma', 'heb', 'רַעַד', '["raʻad"]', '["trembling"]', '["n-m n-f"]', 'a shudder trembling.', 'or (feminine) רְעָדָהxlit rᵉâdâh corrected to rᵉʻâdâh; from 7460;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4127}/[H4127]', 'lemma', 'heb', 'מוּג', '["mûwg"]', '["[are] melting away","it melted","it melted away","melt away","they have melted away","they will flow with [it]","they will melt away"]', '["v"]', 'to melt, i.e. literally (to soften, flow down, disappear), or figuratively (to fear, faint) consume, dissolve, (be) faint(-hearted), melt (away), make soft.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1419A}/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["in/ [things too] great","on/ [the] greatness of"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2220}/H9021/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["arm/ your","strength/ your"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1826A}/[H1724]', 'lemma', 'heb', 'דָּמַם', '["dâmam"]', '["be still","it be still","they have become still","they have been still","they were still"]', '["v"]', 'to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait.', 'a primitive root (compare 1724, 1820);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0068G}/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["like <the>/ stone","like <the>/ stone<s>","like <the>/ stones","like/ a stone of","like/ stones of"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935P}/H9038/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["I will bring/ them","he will bring/ them","people brought/ them","they brought/ them","we have brought/ them","you will bring/ them"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5193}/H9038/[H5193]', 'inflected', 'heb', 'נָטַע', '["nâṭaʻ"]', '["and/ you will plant/ them"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5159}/H9021/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["inheritance/ your"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4349}/[H3559]', 'lemma', 'heb', 'מָכוֹן', '["mâkôwn"]', '["[the] foundation of","[the] place","[the] place of","a place"]', '["n-m"]', 'properly, a fixture, i.e. a basis; generally a place, especially as an abode foundation, habitation, (dwelling-, settled) place.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3427}/H9031/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["to/ dwell in/ you","to/ dwell/ you"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6466}/[H6466]', 'lemma', 'heb', 'פָּעַל', '["pâʻal"]', '["I act","I have done","[I am] about to do","[those who] do","[which] he made","[which] you did","[which] you have done","[who] do","[who] does","do I do","do you do","doers of","does he do","has he done","has he done [it]","he did","he does","he makes","he will make","they do","they have done","will he do","will you do","you have acted","you have done","you have made"]', '["v"]', 'to do or make (systematically and habitually), especially to practise commit, (evil-) do(-er), make(-r), ordain, work(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4720}/[H6942]', 'lemma', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["[is] a sanctuary of","[the] holy places of","[the] sanctuari<es> of","[the] sanctuary of","a sanctuary","sanctuaries"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5703}/[H5710]', 'inflected', 'heb', 'עַד', '["ʻad"]', '["and/ ever"]', '["n-m"]', 'properly, a (peremptory) terminus, i.e. (by implication) duration, in the sense of advance or perpetuity (substantially as a noun, either with or without a preposition) eternity, ever(-lasting, -more), old, perpetually, world without end.', 'from 5710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3220G>\', 'inflected', 'heb', 'הים פ', '["hai./Yam"]', '["the/ sea"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4813G}/[H4805]', 'lemma', 'heb', 'מִרְיָם', '["Miryâm"]', '["Miriam"]', '["n-pr-f"]', 'Mirjam, the name of two Israelitesses Miriam.', 'from 4805; rebelliously;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5031}/[H5030]', 'inflected', 'heb', 'נְבִיאָה', '["nᵉbîyʼâh"]', '["the/ prophetess"]', '["n-f"]', 'a prophetess or (generally) inspired woman; by implication, a poetess; by association a prophet''s wife prophetess.', 'feminine of 5030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8596}/[H8608]', 'inflected', 'heb', 'תֹּף', '["tôph"]', '["the/ tambourine"]', '["n-m"]', 'a tambourine tabret, timbrel.', 'from 8608 contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310A}/H9034/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["[was] behind/ it","after/ her","behind/ her","behind/ it"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4246}/[H4234]', 'inflected', 'heb', 'מְחֹלָה', '["mᵉchôlâh"]', '["and/ with/ dancing"]', '["n-f"]', 'a dance company, dances(-cing).', 'feminine of 4234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6030C}/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ she sang","and/ they sang","and/ they will sing"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3220G>\', 'inflected', 'heb', 'בים ס', '["ba/i.Yam","va/i.Yam"]', '["[is] in the/ sea","in the/ sea"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3220G>', 'inflected', 'heb', 'מימים', '["mi./Yam","mi./ya.Mim","mi./yam"]', '["[will be] from/ sea","from/ [the] sea","from/ [the] sea of","from/ [the] seas","from/ sea"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4057B}/[H1696]', 'lemma', 'heb', 'מִדְבָּר', '["midbâr"]', '["[the] wilderness","[the] wilderness of","a wilderness","wilderness"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4785}/H9011/[H4751]', 'inflected', 'heb', 'מָרָה', '["Mârâh"]', '["Marah/ towards"]', '["n-pr-f"]', 'Marah, a place in the Desert Marah.', 'the same as 4751 feminine; bitter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4785}/[H4751]', 'inflected', 'heb', 'מָרָה', '["Mârâh"]', '["from/ Marah"]', '["n-pr-f"]', 'Marah, a place in the Desert Marah.', 'the same as 4751 feminine; bitter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4751}/[H4843]', 'lemma', 'heb', 'מַר', '["mar"]', '["[is] bitter","[the] bitterness of","[was] bitter of","[were] bitter","bitter","bitter [thing]","bitter of","bitterly"]', '["a-m"]', 'bitter (literally or figuratively); also (as noun) bitterness, or (adverbially) bitterly angry, bitter(-ly, -ness), chafed, discontented, × great, heavy.', 'or (feminine) מָרָה; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4785}/[H4751]', 'lemma', 'heb', 'מָרָה', '["Mârâh"]', '["Marah"]', '["n-pr-f"]', 'Marah, a place in the Desert Marah.', 'the same as 4751 feminine; bitter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3885B}/[H3885]', 'inflected', 'heb', 'לוּן', '["lûwn"]', '["and/ it grumbled","and/ they caused to grumble","and/ they grumbled","and/ they passed [the] night"]', '["v"]', 'to stop (usually over night); by implication, to stay permanently; hence (in a bad sense) to be obstinate (especially in words, to complain) abide (all night), continue, dwell, endure, grudge, be left, lie all night, (cause to) lodge (all night, in, -ing, this night), (make to) murmur, remain, tarry (all night, that night).', 'or לִין; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3384B}/H9033/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["and/ he showed/ him"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6086I}/[H6095]', 'lemma', 'heb', 'עֵץ', '["ʻêts"]', '["[the] piece of wood of","a piece of wood","a tree","wood of","wood<s>"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4985}/[H4985]', 'inflected', 'heb', 'מָתַק', '["mâthaq"]', '["and/ they became sweet"]', '["v"]', 'to suck, by implication, to relish, or (intransitively) be sweet be (made, × take) sweet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706G}/[H2710]', 'lemma', 'heb', 'חֹק', '["chôq"]', '["[is] a decree","[the] decree","[the] decree of","[the] statutes of","a custom","a decree","a decree of","a prescribed portion of","decree","statutes"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4941G}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ [the] judgment of","and/ [the] judgments of","and/ a custom","and/ a judgment","and/ judgment","and/ judgment of","and/ judgments","and/ justice of"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5254G}/H9033/[H5254]', 'inflected', 'heb', 'נָסָה', '["nâçâh"]', '["I should put to [the] test/ it","he put to [the] test/ it","you put to [the] test/ him"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3477G}/[H3474]', 'inflected', 'heb', 'יָשָׁר', '["yâshâr"]', '["and/ the/ right","and/ the/ upright"]', '["a"]', 'straight (literally or figuratively) convenient, equity, Jasher, just, meet(-est), pleased well right(-eous), straight, (most) upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0238}/[H241]', 'inflected', 'heb', 'אָזַן', '["ʼâzan"]', '["and/ he will give ear","and/ you will give ear"]', '["v"]', 'to broaden out the ear (with the hand), i.e. (by implication) to listen give (perceive by the) ear, hear(-ken). See 239.', 'a primitive root; probably to expand; but used only as a denominative from 241;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4687}/H9023/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["to/ commandments/ his"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706G}/H9023/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["decrees/ his","statutes/ his"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4245B}/[H2470]', 'inflected', 'heb', 'מַחֲלֶה', '["machăleh"]', '["<the>/ sickness"]', '["n-m"]', 'sickness disease, infirmity, sickness.', 'or (feminine) מַחֲלָה; from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7495}/H9031\/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["[who] heals/ you"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0362}/H9011/[H352]', 'inflected', 'heb', 'אֵילִם', '["ʼÊylim"]', '["Elim/ towards"]', '["n-pr-loc"]', 'Elim, a place in the Desert Elim.', 'plural of 352; palm-trees;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8558>', 'opaque', 'heb', 'תָּמָר', '["tâmâr"]', '["palm trees"]', '["n-m"]', 'a palm tree palm (tree).', 'from an unused root meaning to be erect;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0362}/[H352]', 'inflected', 'heb', 'אֵילִם', '["ʼÊylim"]', '["from/ Elim"]', '["n-pr-loc"]', 'Elim, a place in the Desert Elim.', 'plural of 352; palm-trees;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5512B>', 'opaque', 'heb', 'סִין', '["Çîyn"]', '["Sin"]', '["n-pr-loc"]', 'Sin the name of an Egyptian town and (probably) desert adjoining Sin.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0362}/[H352]', 'lemma', 'heb', 'אֵילִם', '["ʼÊylim"]', '["Elim"]', '["n-pr-loc"]', 'Elim, a place in the Desert Elim.', 'plural of 352; palm-trees;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5514G>', 'opaque', 'heb', 'סִינַי', '["Çîynay"]', '["Sinai"]', '["n-pr-loc"]', 'Sinai, mountain of Arabia Sinai.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3318G}/H9038/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["of/ going out/ their"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414Q}/[H5414]', 'lemma', 'heb', 'נָתַן', '["nâthan"]', '["I set","I will make","let it be permitted","will he give"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9045/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["died/ we"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3427}/H9045/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["when/ sat/ we"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5518A}/[H5518]', 'lemma', 'heb', 'סִיר', '["çîyr"]', '["[is] [the] pot of","[the] pot of","a pot","pot"]', '["n-m"]', 'a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn.', 'or (feminine) סִירָה; or סִרָה; (Jeremiah 52:18), from a primitive root meaning to boil up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0398}/H9045/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["when/ ate/ we"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7648}/[H7646]', 'inflected', 'heb', 'שֹׂבַע', '["sôbaʻ"]', '["to/ [the] satiety of","to/ abundance","to/ satiety"]', '["n-m"]', 'satisfaction (of food or [figuratively] joy) fill, full(-ness), satisfying, be satisfied.', 'from 7646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6951}/[H6950]', 'inflected', 'heb', 'קָהָל', '["qâhâl"]', '["the/ assembly","the/ company"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7458}\/[H7456]', 'inflected', 'heb', 'רָעָב', '["râʻâb"]', '["by <the>/ hunger"]', '["n-m"]', 'hunger (more or less extensive) dearth, famine, famished, hunger.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697N}/[H1696]', 'lemma', 'heb', 'דָּבָר', '["dâbâr"]', '["[the] matter of","a matter of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1980I}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["¿/ do they walk","¿/ will it walk"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8451}/H9020/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["in/ law/ my"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8345}/[H8337]', 'inflected', 'heb', 'שִׁשִּׁי', '["shishshîy"]', '["<the>/ sixth","[was] the/ sixth","the/ sixth"]', '["n"]', 'sixth, ordinal or (feminine) fractional sixth (part).', 'from 8337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117J>\', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["day"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1242}/[H1239]', 'inflected', 'heb', 'בֹּקֶר', '["bôqer"]', '["and/ morning"]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3519}/[H3513]', 'lemma', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["[is] [the] glory of","[is] an honor","[is] honor","[the] abundance of","[the] glory","[the] glory of","[the] honor of","[the] splendor of","[with the] glory of","glory","honor","splendor"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8085G}/H9043/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["because/ has heard/ he","when/ heard/ he","when/ hears/ he"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8519}/H9026/[H3885]', 'inflected', 'heb', 'תְּלוּנָה', '["tᵉlûwnâh"]', '["grumblings/ your"]', '["n-f"]', 'a grumbling murmuring.', 'or תּלֻנָּה; from 3885 in the sense of obstinacy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5168}/[H587]', 'inflected', 'heb', 'נַחְנוּ', '["nachnûw"]', '["and/ [are] we"]', '["p"]', 'we we.', 'for 587;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3885B}/[H3885]', 'lemma', 'heb', 'לוּן', '["lûwn"]', '["[are] grumbling","you have grumbled","you will cause to grumble"]', '["v"]', 'to stop (usually over night); by implication, to stay permanently; hence (in a bad sense) to be obstinate (especially in words, to complain) abide (all night), continue, dwell, endure, grudge, be left, lie all night, (cause to) lodge (all night, in, -ing, this night), (make to) murmur, remain, tarry (all night, that night).', 'or לִין; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5414G}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["when/ gives"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7646}/[H7646]', 'inflected', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["to/ be satisfied","to/ satisfy"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8085G}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["because/ has heard"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1696G}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["as/ had spoken","as/ speaks","when/ spoke"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6051}\/[H6049]', 'inflected', 'heb', 'עָנָן', '["ʻânân"]', '["in the/ cloud"]', '["n-m"]', 'a cloud (as covering the sky), i.e. the nimbus or thunder-cloud cloud(-y).', 'from 6049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8519}/[H3885]', 'lemma', 'heb', 'תְּלוּנָה', '["tᵉlûwnâh"]', '["[the] grumblings of"]', '["n-f"]', 'a grumbling murmuring.', 'or תּלֻנָּה; from 3885 in the sense of obstinacy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1242}/[H1239]', 'inflected', 'heb', 'בֹּקֶר', '["bôqer"]', '["and/ in the/ morning"]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7646}/[H7646]', 'lemma', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["I have been surfeited","I should be satisfied","I will be satisfied","I will satisfy","[one who] is satisfied","are you satisfied?","be satisfied","he is satisfied","he satisfies","he will be satisfied","it has been surfeited","it is satisfied","it is surfeited","it was satisfied","it will be satisfied","let him be sated","may we be satisfied","they are satisfied","they should be satisfied","they were satisfied","they will be satisfied","they will be surfeited","they will satisfy","we have been surfeited","you are satisfied","you satisfied","you were satisfied","you will be satisfied","you will satisfy"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7958}/[H7951]', 'inflected', 'heb', 'שְׂלָו', '["sᵉlâv"]', '["the/ quail"]', '["n-f"]', 'the quail collectively (as slow in flight from its weight) quails.', 'or שְׂלָיו; by orthographical variation from 7951 through the idea of sluggishness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7902}/[H7901]', 'lemma', 'heb', 'שְׁכָבָה', '["shᵉkâbâh"]', '["[the] layer of","a laying of"]', '["n-f"]', 'a lying down (of dew, or for the sexual act) × carnally, copulation, × lay, seed.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2919}/[H2926]', 'inflected', 'heb', 'טַל', '["ṭal"]', '["<the>/ dew","the/ dew"]', '["n-m"]', 'dew (as covering vegetation) dew.', 'from 2926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439G}/[H5437]', 'lemma', 'heb', 'סָבִיב', '["çâbîyb"]', '["[are] around","[is] around","[the] circuit","[was] all around","[were] all around","[were] around","all around","around","round about"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4264}/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["<to> the/ camp","of the/ camp","of/ [the] camp of","of/ [the] camps of","to the/ army","to the/ camp","to/ a camp"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2636>', 'opaque', 'heb', 'חַסְפַּס', '["chaçpaç"]', '["flake-like"]', '["v"]', 'a shred or scale round thing.', 'reduplicated from an unused root meaning apparently to peel;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3713B}/[H3722]', 'inflected', 'heb', 'כְּפוֹר', '["kᵉphôwr"]', '["like <the>/ frost"]', '["n-m"]', 'properly, a cover, i.e. (by implication) a tankard (or covered goblet); also white frost (as covering the ground) bason, hoar(-y) frost.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4478B}/[H4100]', 'lemma', 'heb', 'מָן', '["mân"]', '["what?"]', '["n-m"]', 'literally a whatness (so to speak), i.e. manna (so called from the question about it) manna.', 'from 4100;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6016B}/[H6014]', 'lemma', 'heb', 'עֹמֶר', '["ʻômer"]', '["an omer"]', '["n-m"]', 'properly, a heap, i.e. a sheaf; also an omer, as a dry measure omer, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1538}/[H1556]', 'inflected', 'heb', 'גֻּלְגֹּלֶת', '["gulgôleth"]', '["for the/ head"]', '["n-f"]', 'a skull (as round); by implication, a head (in enumeration of persons) head, every man, poll, skull.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315J}/H9026/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["people/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0168G}/H9023/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["[are] in/ tent/ his","in/ tent/ his"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7235A}/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["the/ [one who] increases","the/ [one who] made much"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4591}/[H4591]', 'inflected', 'heb', 'מָעַט', '["mâʻaṭ"]', '["and/ the/ [one who] made little"]', '["v"]', 'properly, to pare off, i.e. lessen; intransitively, to be (or causatively, to make) small or few (or figuratively, ineffective) suffer to decrease, diminish, (be, × borrow a, give, make) few (in number, -ness), gather least (little), be (seem) little, (× give the) less, be minished, bring to nothing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4058}/[H4058]', 'inflected', 'heb', 'מָדַד', '["mâdad"]', '["and/ I will measure","and/ he measured","and/ he measured off","and/ he measured out","and/ he stretched himself","and/ it will continue","and/ they measured [it]","and/ they will measure","and/ you will measure"]', '["v"]', 'properly, to stretch; by implication, to measure (as if by stretching a line); figuratively, to be extended measure, mete, stretch self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6016B}/[H6014]', 'inflected', 'heb', 'עֹמֶר', '["ʻômer"]', '["by the/ omer"]', '["n-m"]', 'properly, a heap, i.e. a sheaf; also an omer, as a dry measure omer, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5736}/[H5736]', 'lemma', 'heb', 'עֲדַף', '["ʻădaph"]', '["he had a surplus"]', '["v"]', 'to be (causatively have) redundant be more, odd number, be (have) over (and above), overplus, remain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2637}/[H2637]', 'lemma', 'heb', 'חָסֵר', '["châçêr"]', '["I lack","he deprives","he had a lack","he lacks","he will lack","is lacking","it be lacking","it lack","it was lacking","it will be lacking","they lack","they may lack","they were lacking","we have lacked","you have lacked","you will lack"]', '["v"]', 'to lack; by implication, to fail, want, lessen be abated, bereave, decrease, (cause to) fail, (have) lack, make lower, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7311B}/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["and/ it became rotten"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8438A}/[H3216]', 'lemma', 'heb', 'תּוֹלָע', '["tôwlâʻ"]', '["crimson","worms"]', '["n-m n-f"]', 'a maggot (as voracious); specifically (often with ellipsis of 8144) the crimson-grub, but used only (in this connection) of the color from it, and cloths dyed therewith crimson, scarlet, worm.', 'and (feminine) תּוֹלֵעָה; or תּוֹלַעַת; or תֹּלַעַת; from 3216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6310K}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["according to/ [the] mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2552}/[H2552]', 'inflected', 'heb', 'חָמַם', '["châmam"]', '["and/ he became warm","and/ it became warm","and/ it was warm","and/ it will be warm"]', '["v"]', 'to be hot (literally or figuratively) enflame self, get (have) heat, be (wax) hot, (be, wax) warm (self, at).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4549}/[H4549]', 'inflected', 'heb', 'מָסַס', '["mâçaç"]', '["and/ he will melt away","and/ it melted","and/ it will melt","and/ they dropped off","and/ they will melt","and/ they will melt away"]', '["v"]', 'to liquefy; figuratively, to waste (with disease), to faint (with fatigue, fear or grief) discourage, faint, be loosed, melt (away), refuse, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6016B}/[H6014]', 'inflected', 'heb', 'עֹמֶר', '["ʻômer"]', '["<the>/ omer[s]","the/ omer"]', '["n-m"]', 'properly, a heap, i.e. a sheaf; also an omer, as a dry measure omer, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0259}/[H258]', 'inflected', 'heb', 'אֶחָד', '["ʼechâd"]', '["<into>/ one<s>","<to>/ one","[belonged] to/ one","for the/ one","for/ one","to/ one"]', '["a"]', 'properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,', 'a numeral from 258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5712}/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["[of] the/ congregation","the/ company","the/ congregation"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7677}/[H7676]', 'lemma', 'heb', 'שַׁבָּתוֹן', '["shabbâthôwn"]', '["a sabbath observance","sabbath observance"]', '["n-m"]', 'a sabbatism or special holiday rest, sabbath.', 'from 7676;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7676}/[H7673]', 'lemma', 'heb', 'שַׁבָּת', '["shabbâth"]', '["[is] a sabbath","[is] a sabbath of","[the] sabbath","[the] sabbath of","[the] sabbaths of","a sabbath","a sabbath of","sabbath","sabbaths","sabbaths of"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5736}/[H5736]', 'inflected', 'heb', 'עֲדַף', '["ʻădaph"]', '["the/ surplus","those/ [who] are in excess","those/ [who] were in excess","which/ is surplus","who/ are in excess"]', '["v"]', 'to be (causatively have) redundant be more, odd number, be (have) over (and above), overplus, remain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7415}/[H7426]', 'inflected', 'heb', 'רִמָּה', '["rimmâh"]', '["and/ a maggot"]', '["n-f"]', 'a maggot (as rapidly bred), literally or figuratively worm.', 'from 7426 in the sense of breeding (compare 7311);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3950}/H9033/[H3950]', 'inflected', 'heb', 'לָקַט', '["lâqaṭ"]', '["you will gather/ it"]', '["v"]', 'properly, to pick up, i.e. (generally) to gather; specifically, to glean gather (up), glean.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3950}/[H3950]', 'inflected', 'heb', 'לָקַט', '["lâqaṭ"]', '["to/ gather","to/ gather [it]","to/ glean"]', '["v"]', 'properly, to pick up, i.e. (generally) to gather; specifically, to glean gather (up), glean.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4672}\/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["I have found","they found [it]","they may find"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8104G}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["by/ observing","to/ [the] keepers of","to/ [those who] keep","to/ keep","to/ take care"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7676}/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["<of> the/ sabbath","the/ sabbath","the/ sabbaths"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478I}/H9033/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["in place of/ himself","in place/ his","in place/ its","in/ it","under/ it"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4725}/H9023/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["from/ own place/ his","from/ place/ his","from/ place/ its"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4478A}/[H4100]', 'lemma', 'heb', 'מָן', '["mân"]', '["manna"]', '["n-m"]', 'literally a whatness (so to speak), i.e. manna (so called from the question about it) manna.', 'from 4100;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2233G}/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["[was] like/ [the] seed of","[was] like/ seed of"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1407}/[H1413]', 'lemma', 'heb', 'גַּד', '["gad"]', '["coriander"]', '["n-m"]', 'coriander seed (from its furrows) coriander.', 'from 1413 (in the sense of cutting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2940}/H9023/[H2938]', 'inflected', 'heb', 'טַעַם', '["ṭaʻam"]', '["and/ taste/ its"]', '["n-m"]', 'properly, a taste, i.e. (figuratively) perception; by implication, intelligence; transitively, a mandate advice, behaviour, decree, discretion, judgment, reason, taste, understanding.', 'from 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6838}/[H6835]', 'inflected', 'heb', 'צַפִּיחִת', '["tsappîychith"]', '["[was] like/ a wafer"]', '["n-f"]', 'a flat thin cake wafer.', 'from the same as 6835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1706>', 'inflected', 'heb', 'בדבש', '["bi/d.Vash"]', '["with/ honey"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3318H}/H9040/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ bring out/ I","when/ brought out/ I"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6803}/[H6791]', 'lemma', 'heb', 'צִנְצֶנֶת', '["tsintseneth"]', '["a jar"]', '["n-f"]', 'a vase (probably a vial tapering at the top) pot.', 'from the same as 6791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5414Q}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ put"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5117}/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["and/ deposit","and/ set [them]","and/ they rested","so/ people may set down","so/ you may rest"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5715}/[H5707]', 'inflected', 'heb', 'עֵדוּת', '["ʻêdûwth"]', '["the/ testimony"]', '["n-f"]', 'testimony testimony, witness.', 'feminine of 5707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4478A}/[H4100]', 'inflected', 'heb', 'מָן', '["mân"]', '["the/ manna"]', '["n-m"]', 'literally a whatness (so to speak), i.e. manna (so called from the question about it) manna.', 'from 4100;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7097A}/[H7096]', 'lemma', 'heb', 'קָצֶה', '["qâtseh"]', '["[the] border of","[the] edge of","[the] end of","[the] outskirt[s] of"]', '["n-m"]', 'an extremity × after, border, brim, brink, edge, end, (in-) finite, frontier, outmost coast, quarter, shore, (out-) side, × some, ut(-ter-) most (part).', 'or (negative only) קֵצֶה; from 7096; (used in a great variety of applications and idioms; compare 7093)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6016B}/[H6014]', 'inflected', 'heb', 'עֹמֶר', '["ʻômer"]', '["and/ the/ omer"]', '["n-m"]', 'properly, a heap, i.e. a sheaf; also an omer, as a dry measure omer, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6224}/[H6235]', 'lemma', 'heb', 'עֲשִׂירִי', '["ʻăsîyrîy"]', '["<the> tenth of","[is] [the] tenth [part] of","a tenth [part]","tenth"]', '["a"]', 'tenth; by abbreviation, tenth month or (feminine) part tenth (part).', 'from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0374}/[H374]', 'inflected', 'heb', 'אֵיפָה', '["ʼêyphâh"]', '["<the>/ ephah","[is] the/ ephah","the/ ephah"]', '["n-f"]', 'an ephah or measure for grain; hence, a measure in general ephah, (divers) measure(-s).', 'or (shortened) אֵפָה ; of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1931}\/[H1931]', 'inflected', 'heb', 'הוּא', '["hûwʼ"]', '["[is] he","he","it","she","that"]', '["p"]', 'he (she or it); only expressed when emphatic or without a verb; also (intensively) self, or (especially with the article) the same; sometimes (as demonstrative) this or that; occasionally (instead of copula) as or are he, as for her, him(-self), it, the same, she (herself), such, that (...it), these, they, this, those, which (is), who.', 'of which the feminine (beyond the Pentateuch) is הִיא; he a primitive word, the third person pronoun singular;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4057B}/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["from/ [the] wilderness","from/ [the] wilderness of","more than/ [the] wilderness of"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4550}/H9028/[H5265]', 'inflected', 'heb', 'מַסַּע', '["maççaʻ"]', '["for/ settings out/ their","to/ journeyings/ their","to/ settings out/ their"]', '["n-m"]', 'a departure (from striking the tents), i.e. march (not necessarily a single day''s travel); by implication, a station (or point of departure) journey(-ing).', 'from 5265;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7508}/[H7507]', 'inflected', 'heb', 'רְפִידִים', '["Rᵉphîydîym"]', '["at/ Rephidim"]', '["n-pr-m"]', 'Rephidim, a place in the Desert Rephidim.', 'plural of the masculine of the same as 7507; ballusters;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7378}/H9013/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["are you quarreling/ !","they will quarrel/ !","will you argue a case/ !","will you conduct a case/ !"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5254G}/H9013/[H5254]', 'inflected', 'heb', 'נָסָה', '["nâçâh"]', '["are you putting to [the] test/ !"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6770}/[H6770]', 'inflected', 'heb', 'צָמֵא', '["tsâmêʼ"]', '["and/ he was thirsty","and/ it was thirsty","and/ they were thirsty","and/ you will be thirsty"]', '["v"]', 'to thirst (literally or figuratively) (be a-, suffer) thirst(-y).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927H}/H9035/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["did he bring up/ us","did you bring up/ us","have you brought up/ us","he brought up/ us","you bring up/ us","you have brought up/ us"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4735}/H9020/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["livestock/ my"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6772}/[H6770]', 'inflected', 'heb', 'צָמָא', '["tsâmâʼ"]', '["by <the>/ thirst","in <the>/ thirst","with <the>/ thirst"]', '["n-m"]', 'thirst (literally or figuratively) thirst(-y).', 'from 6770;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5619}/H9030/[H5619]', 'inflected', 'heb', 'סָקַל', '["çâqal"]', '["and/ they will stone/ me"]', '["v"]', 'properly, to be weighty; but used only in the sense of lapidation or its contrary (as if a delapidation) (cast, gather out, throw) stone(-s), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2205G}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["from/ [the] elders of","from/ elders","of/ [the] elders of","some of/ [the] elders of"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6697H}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["the/ rock","the/ rocks"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2722}/[H2717]', 'inflected', 'heb', 'חֹרֵב', '["Chôrêb"]', '["at/ Horeb"]', '["n-pr-loc"]', 'Choreb, a (generic) name for the Sinaitic mountains Horeb.', 'from 2717; desolate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6697H}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["<on> the/ rock","at/ [the] rock of","in the/ rock","in the/ rocks","on/ a rock"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4532}/[H4531]', 'lemma', 'heb', 'מַסָּה', '["Maççâh"]', '["Massah"]', '["n-pr-loc"]', 'Massah, a place in the Desert Massah.', 'the same as 4531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4809G}/[H4808]', 'inflected', 'heb', 'מְרִיבָה', '["Mᵉrîybâh"]', '["and/ Meribah"]', '["n-pr-loc"]', 'Meribah, the name of two places in the Desert Meribah.', 'the same as 4808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5254G}/H9048/[H5254]', 'inflected', 'heb', 'נָסָה', '["nâçâh"]', '["put to [the] test/ they"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130G}/H9025/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["[are] in/ midst/ our","in/ midst/ our"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0369}\/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["not"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6002G>', 'opaque', 'heb', 'עֲמָלֵק', '["ʻĂmâlêq"]', '["Amalek"]', '["n-pr-m"]', 'Amalek, a descendant of Esau; also his posterity and their country Amalek.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3091G}/[H3068]', 'lemma', 'heb', 'יְהוֹשׁוּעַ', '["Yᵉhôwshûwaʻ"]', '["Joshua"]', '["n-pr-m"]', 'Jehoshua (i.e. Joshua), the Jewish leader Jehoshua, Jehoshuah, Joshua. Compare 1954, 3442.', 'or יְהוֹשֻׁעַ; from 3068 and 3467; Jehovah-saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6002G>', 'inflected', 'heb', 'בעמלק', '["ba./''a.ma.Lek"]', '["[was] in/ Amalek","against/ Amalek","on/ Amalek","with/ Amalek"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1389I}/[H1387]', 'inflected', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["<the>/ hill","the/ hill","the/ hills"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4294G}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["and/ [is] a staff","and/ [the] rod of","and/ [the] staff of"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3898A}/[H3898]', 'inflected', 'heb', 'לָחַם', '["lâcham"]', '["by/ fighting","by/ waging war","to/ do battle","to/ engage in battle","to/ fight","to/ wage war"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2354G}/[H2353]', 'inflected', 'heb', 'חוּר', '["Chûwr"]', '["and/ Hur"]', '["n-pr-m"]', 'Chur, the name of four Israelites and one Midianite Hur.', 'the same as 2353 or 2352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478G}/H9033/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["[was] under/ him","under/ him","under/ it"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8551}/[H8551]', 'lemma', 'heb', 'תָּמַךְ', '["tâmak"]', '["[are] holding","[whom] I support","he will attain","he will be held","it supports","let it hold fast to","people support","she lays hold of","they grasp","they have held firm","they supported","they take hold of","they take hold of [you]","they will attain","you have supported"]', '["v"]', 'to sustain; by implication, to obtain, keep fast; figuratively, to help, follow close (take, up-) hold (up), maintain, retain, stay (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2088}/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["and/ from/ this"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0530}/[H529]', 'lemma', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["[are] faithfulness","[the] steadiness of","[were] steadiness","faithfulness","faithfulness<es>"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2522}/[H2522]', 'inflected', 'heb', 'חָלַשׁ', '["châlash"]', '["and/ he defeated","and/ he was weak"]', '["v"]', 'to prostrate; by implication, to overthrow, decay discomfit, waste away, weaken.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6310H}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["to/ [the] mouth of","to/ [the] opening of","to/ mouth"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2719}\/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["[the] sword","a sword"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3789}/[H3789]', 'lemma', 'heb', 'כָּתַב', '["kâthab"]', '["I have written","I wrote","[are] written","[is] inscribed","[is] written","[it is] written","[it was] written","[was] writing","[was] written","[were] recorded","[were] written","[which] he had written","did you write","have I written","he had written","he has written","he will write","he wrote","inscribed","let it be written","record","recorded","they be written down","they were written","they will be written down","they wrote","write","write down","written","you have written","you will describe in writing","you will write","you write"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2146}/[H2142]', 'lemma', 'heb', 'זִכְרוֹן', '["zikrôwn"]', '["[is] remembrance","a memorial","a remembrance of","a reminder","remembrance","reminder"]', '["n-m"]', 'a memento (or memorable thing, day or writing) memorial, record.', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5612H}/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["in the/ book","in the/ scroll","in the/ scrolls","in/ [the] book of","in/ [the] scroll of","on the/ scroll"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241G}/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["[are] on/ [the] ears of","in/ [the] ears of","on/ [the] ears of"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2143}/[H2142]', 'lemma', 'heb', 'זֵכֶר', '["zêker"]', '["[the] memory of","[the] remembrance of","remembrance"]', '["n-m"]', 'a memento, abstractly recollection (rarely if ever); by implication, commemoration memorial, memory, remembrance, scent.', 'or זֶכֶר; from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5251G}/H9020/[H5264]', 'inflected', 'heb', 'נֵס', '["nêç"]', '["[is] standard/ my"]', '["n-m"]', 'a flag; also a sail; by implication, a flagstaff; generally a signal; figuratively, a token banner, pole, sail, (en-) sign, standard.', 'from 5264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3676}/[H3678]', 'lemma', 'heb', 'כֵּס', '["kêç"]', '["[the] throne of"]', '["n-m"]', 'sworn.', 'apparently a contraction for 3678, but probably by erroneous transcription for 5251');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1755}/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["from/ generation"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1755}\/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["generation","generations"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2859A}/[H2859]', 'lemma', 'heb', 'חָתַן', '["châthan"]', '["[the] father-in-law of"]', '["v"]', 'to give (a daughter) away in marriage; hence (generally) to contract affinity by marriage join in affinity, father in law, make marriages, mother in law, son in law.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3478}/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["and/ <to>/ Israel","and/ for/ Israel","and/ of/ Israel","and/ to/ Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7964}/H9024/[H7971]', 'inflected', 'heb', 'שִׁלּוּחַ', '["shillûwach"]', '["dismissal<s>/ her"]', '["n-m"]', '(only in plural) a dismissal, i.e. (of a wife) divorce (especially the document); also (of a daughter) dower presents, have sent back.', 'or שִׁלֻּחַ; from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0461H}/[H410]', 'lemma', 'heb', 'אֱלִיעֶזֶר', '["ʼĔlîyʻezer"]', '["Eliezer","[was] Eliezer"]', '["n-pr-m"]', 'Eliezer, the name of a Damascene and of ten Israelites Eliezer.', 'from 410 and 5828; God of help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5828}/H9020/[H5826]', 'inflected', 'heb', 'עֵזֶר', '["ʻêzer"]', '["[has been] <in>/ help/ my"]', '["n-m"]', 'aid help.', 'from 5826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5337}/H9030/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ he has delivered/ me"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2719}/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["from/ [the] sword","from/ [the] sword of","from/ a sword"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2859A}/H9021/[H2859]', 'inflected', 'heb', 'חָתַן', '["châthan"]', '["father-in-law/ your"]', '["v"]', 'to give (a daughter) away in marriage; hence (generally) to contract affinity by marriage join in affinity, father in law, make marriages, mother in law, son in law.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7453}/H9023/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["<to>/ neighbor/ his","by/ neighbor/ his","for/ companion/ his","of/ neighbor/ his","to/ friend/ his","to/ neighbor/ his"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2859A}/H9023/[H2859]', 'inflected', 'heb', 'חָתַן', '["châthan"]', '["to/ father-in-law/ his"]', '["v"]', 'to give (a daughter) away in marriage; hence (generally) to contract affinity by marriage join in affinity, father in law, make marriages, mother in law, son in law.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4714G}/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["and/ to/ Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8513}/[H3811]', 'inflected', 'heb', 'תְּלָאָה', '["tᵉlâʼâh"]', '["the/ hardship"]', '["n-f"]', 'distress travail, travel, trouble.', 'from 3811;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4672}/H9038/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["[those who] found/ them","it had come upon/ them","you found/ them","you will find/ them"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5337}/H9038/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ I will deliver/ them","and/ he had delivered/ them","and/ he will rescue/ them"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2302}/[H2302]', 'inflected', 'heb', 'חָדָה', '["châdâh"]', '["and/ he rejoiced"]', '["v"]', 'to rejoice make glad, be joined, rejoice.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2896C}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["<the>/ good","the/ good","the/ good thing"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5337}/H9033/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["he delivers/ him","he had delivered/ it","it will deliver/ him","let him deliver/ him"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027W}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3027W}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ from/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8478K}/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["from/ under"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027W}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["[the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0430J}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["[are] the/ gods","the/ gods"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1697M}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["by the/ thing","in the/ matter"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2102}/[H2102]', 'lemma', 'heb', 'זוּד', '["zûwd"]', '["he will act presumptuously","it has defied proudly","they acted presumptuously","they had acted presumptuously","they have acted presumptuously"]', '["v"]', 'to seethe; figuratively, to be insolent be proud, deal proudly, presume, (come) presumptuously, sod.', 'or (by permutation) זִיד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2077}/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["and/ sacrifice","and/ sacrifices"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8199}/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["to/ judge","to/ rule","to/ vindicate"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0905H}/H9031/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["to/ alone/ you"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697L}/[H1696]', 'lemma', 'heb', 'דָּבָר', '["dâbâr"]', '["[the] case of","[the] thing","[the] words of","[will be] [the] case of","a matter","a thing","matter","matter of","matters","matters of","words"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8451}/H9023/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["laws/ his","laws/ its"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5034B}/[H5034]', 'lemma', 'heb', 'נָבֵל', '["nâbêl"]', '["<of> withering","[which is] withering","certainly <to wear out>","it crumbles away","it has withered","it will wither","it withers","they wither","they withered","withering","you will wear yourself out"]', '["v"]', 'to wilt; generally, to fall away, fail, faint; figuratively, to be foolish or (morally) wicked; causatively, to despise, disgrace disgrace, dishounour, lightly esteem, fade (away, -ing), fall (down, -ling, off), do foolishly, come to nought, × surely, make vile, wither.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213A}/H9033/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["people have done/ it","to do/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3289}/H9031/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["I will advise/ you","I will counsel/ you","let me advise/ you"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4136}/[H4135]', 'lemma', 'heb', 'מוּל', '["mûwl"]', '["[the] front of","in front of","opposite to"]', '["n-m"]', 'properly, abrupt, i.e. a precipice; by implication, the front; used only adverbially (with prepositional prefix) opposite (over) against, before, (fore-) front, from, (God-) ward, toward, with.', 'or מוֹל; (Deuteronomy 1:1), or מוֹאל; (Nehemiah 12:38), or מֻל; (Numbers 22:5), from 4135;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1697L}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<the>/ matter","the/ matter","the/ matters","the/ word"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2094B}/[H2094]', 'inflected', 'heb', 'זָהַר', '["zâhar"]', '["and/ he will warn","and/ you will warn"]', '["v"]', 'to gleam; figuratively, to enlighten (by caution) admonish, shine, teach, (give) warn(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2706G}/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["[are] the/ statutes","the/ fixed order<s>","the/ statutes"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8451}/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["<of> the/ law","[is] the/ law","[is] the/ legal [procedure]","the/ instruction","the/ law","the/ laws"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1870G}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["<the>/ way","the/ way"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4639G}/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["<the>/ work","the/ work","the/ works"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2372}/[H2372]', 'lemma', 'heb', 'חָזָה', '["châzâh"]', '["I have seen","I see [him]","I will see","[is] seeing","[that which] I see","[they are] seeing","do you see?","have they seen?","have you seen","he has seen","he saw","he sees","it sees","look at","may they see","see","they have looked","they have seen","they see","they will behold","they will see","will you look","you have seen","you must see","you see","you will provide","you will see"]', '["v"]', 'to gaze at; mentally to perceive, contemplate (with pleasure); specifically, to have a vision of behold, look, prophesy, provide, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0571G}/[H539]', 'lemma', 'heb', 'אֶמֶת', '["ʼemeth"]', '["[are] faithfulness","[is] faithfulness","faithfulness","reliability","truth"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8269}/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["and/ [the] commanders of","and/ [the] leaders of","and/ [the] officials of","and/ [the] prince of","and/ [was the] commander of","and/ [was] [the] commander of","and/ commander","and/ commanders of","and/ leaders","and/ leaders of","and/ officials","and/ officials of","and/ princes"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7043}/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["and/ [one who] will curse","and/ cursing","and/ lighten","so/ he may curse"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6680}/H9031/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["and/ he will appoint/ you","and/ he will command/ you"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4725}/H9023/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["[is] place/ its","place/ his","place/ its"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7186}/[H7185]', 'inflected', 'heb', 'קָשֶׁה', '["qâsheh"]', '["<the>/ difficult","<the>/ fierce","<the>/ hard","<the>/ stiff","<the>/ stubborn"]', '["a"]', 'severe (in various applications) churlish, cruel, grievous, hard((-hearted), thing), heavy, impudent, obstinate, prevailed, rough(-ly), sore, sorrowful, stiff(necked), stubborn, in trouble.', 'from 7185;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935P}/H9013/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["they brought/ !"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776G>/H9023\', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["land/ his"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2320H}/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["at the/ new moon","in the/ month"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3318G}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["[belonged] to the/ [one who] went out","of/ [the] coming out of","of/ [the] going out of","to/ come out","to/ go forth","to/ go out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5514H>', 'opaque', 'heb', 'סִינַי', '["Çîynay"]', '["Sinai"]', '["n-pr-loc"]', 'Sinai, mountain of Arabia Sinai.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7508}/[H7507]', 'inflected', 'heb', 'רְפִידִים', '["Rᵉphîydîym"]', '["from/ Rephidim"]', '["n-pr-m"]', 'Rephidim, a place in the Desert Rephidim.', 'plural of the masculine of the same as 7507; ballusters;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5404>', 'opaque', 'heb', 'נֶשֶׁר', '["nesher"]', '["an eagle","eagles"]', '["n-m"]', 'the eagle (or other large bird of prey) eagle.', 'from an unused root meaning to lacerate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5459>', 'opaque', 'heb', 'סְגֻלָּה', '["çᵉgullâh"]', '["a possession","possession","treasure"]', '["n-f"]', 'wealth (as closely shut up) jewel, peculiar (treasure), proper good, special.', 'feminine passive participle of an unused root meaning to shut up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4467}/[H4427]', 'lemma', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["O kingdoms of","[the] kingdom","[the] kingdom of","[the] kingdoms of","[the] reign of","a kingdom","a kingdom of","kingdom","kingdoms","kingdoms of","kingship"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1471A}/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["and/ a nation","and/ nations"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6918G}/[H6942]', 'lemma', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["O holy [one] of","[am] holy","[are] holy","[is] a holy [one]","[is] holy","[the] holy [one<s>]","[the] holy [one]","[the] holy [one] of","[the] holy [ones]","[the] holy [place] of","holy","holy [one]","holy [ones]","of [the] holy [one] of"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2205G}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["<to>/ [the] elders of","to the/ elders","to/ [the] elders of"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725M}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I brought back","and/ I sent back to","and/ he brought back","and/ they brought back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5645}/[H5743]', 'inflected', 'heb', 'עָב', '["ʻâb"]', '["in the/ thickets","in/ [the] dark cloud of","on the/ clouds","with/ clouds"]', '["n-m"]', 'properly, an envelope, i.e. darkness (or density, 2 Chronicles 4:17); specifically, a (scud) cloud; also a copse clay, (thick) cloud, × thick, thicket. Compare 5672.', '(masculine and feminine); from 5743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1696G}/H9040/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["when/ speak/ I"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6942G}/H9038/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["and/ he sanctified/ them","and/ you will consecrate/ them"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4279}/[H309]', 'inflected', 'heb', 'מָחָר', '["mâchâr"]', '["and/ tomorrow"]', '["n-m"]', 'properly, deferred, i.e. the morrow; usually (adverbially) tomorrow; indefinitely, hereafter time to come, tomorrow.', 'probably from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3526H}/[H3526]', 'inflected', 'heb', 'כָּבַס', '["kâbaç"]', '["and/ he will wash","and/ it will be washed","and/ they washed","and/ they will wash","and/ you will wash"]', '["v"]', 'to trample; hence, to wash (properly, by stamping with the feet), whether literal (including the fulling process) or figurative fuller, wash(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559A}/[H3559]', 'lemma', 'heb', 'כּוּן', '["kûwn"]', '["I have prepared","I prepared","I will prepare","[am] prepared","[has been] prepared","[is] prepared","[that] I have prepared","[the] established [part] of","[where] I have prepared","be prepared","does he prepare","establish","he appointed","he had prepared","he has prepared","he prepared","he will prepare","he will prepare [it]","it has been prepared","it prepares","prepare","prepared","they are prepared","they had prepared","they have prepared","they prepared","they were firm","they were prepared","they will be prepared","we have prepared","will he prepare","you have directed","you prepare","you prepared","you will prepare"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1379}/[H1366]', 'inflected', 'heb', 'גָּבַל', '["gâbal"]', '["and/ you will set a boundary for"]', '["v"]', 'properly, to twist as a rope; to bound (as by a line) be border, set (bounds about).', 'a primitive root; also as a denominative from 1366');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5060}/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["and/ [one who] touches","and/ he may arrive","and/ let him approach","and/ to touch","and/ touch"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7097A}/H9023/[H7096]', 'inflected', 'heb', 'קָצֶה', '["qâtseh"]', '["<in>/ edge/ its"]', '["n-m"]', 'an extremity × after, border, brim, brink, edge, end, (in-) finite, frontier, outmost coast, quarter, shore, (out-) side, × some, ut(-ter-) most (part).', 'or (negative only) קֵצֶה; from 7096; (used in a great variety of applications and idioms; compare 7093)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5619}/[H5619]', 'lemma', 'heb', 'סָקַל', '["çâqal"]', '["certainly <to stone>","clear [it]","he had been stoned","he has been stoned","he will be stoned to death","it will be stoned to death"]', '["v"]', 'properly, to be weighty; but used only in the sense of lapidation or its contrary (as if a delapidation) (cast, gather out, throw) stone(-s), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4900}/[H4900]', 'inflected', 'heb', 'מָשַׁךְ', '["mâshak"]', '["<in>/ [the] sower of","when/ blow","when/ sounds"]', '["v"]', 'to draw, used in a great variety of applications (including to sow, to sound, to prolong, to develop, to march, to remove, to delay, to be tall, etc.) draw (along, out), continue, defer, extend, forbear, × give, handle, make (pro-, sound) long, × sow, scatter, stretch out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3104}/[H2986]', 'inflected', 'heb', 'יוֹבֵל', '["yôwbêl"]', '["<the>/ ram''s horn","<the>/ rams'' horns","the/ jubilee","the/ ram''s horn"]', '["n-m"]', 'the blast of a horn (from its continuous sound); specifically, the signal of the silver trumpets; hence, the instrument itself and the festival thus introduced jubile, ram''s horn, trumpet.', 'or יֹבֵל; apparently from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7969}/[H7969]', 'inflected', 'heb', 'שָׁלוֹשׁ', '["shâlôwsh"]', '["<to>/ [the] three","for/ [the] three","for/ thir-","for/ three","into/ three","to/ [the] three","to/ three"]', '["n"]', 'three; occasionally (ordinal) third, or (multiple) thrice fork, often(-times), third, thir(-teen, -teenth), three, thrice. Compare 7991.', 'or שָׁלֹשׁ; masculine שְׁלוֹשָׁה; or שְׁלֹשָׁה; a primitive number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1300B}/[H1299]', 'inflected', 'heb', 'בָּרָק', '["bârâq"]', '["and/ lightning","and/ lightning flashes","and/ lightning<s>"]', '["n-m"]', 'lightning; by analogy, a gleam; concretely, a flashing sword bright, glitter(-ing sword), lightning.', 'from 1299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6963H>', 'inflected', 'heb', 'וקול', '["ve./Kol","ve./kOl"]', '["and/ [the] sound of","and/ a sound of","and/ noise"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7782}/[H8231]', 'lemma', 'heb', 'שׁוֹפָר', '["shôwphâr"]', '["<the> trumpets of","[the] trumpets of","a horn","a ram''s horn","a ram''s horn of","a trumpet","trumpet","trumpets","trumpets of"]', '["n-m"]', 'a cornet (as giving a clear sound) or curved horn cornet, trumpet.', 'or שֹׁפָר; from 8231 in the original sense of incising;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8482}/[H8478]', 'inflected', 'heb', 'תַּחְתִּי', '["tachtîy"]', '["at/ [the] lower part of","in/ [the] lower parts of"]', '["a"]', 'lowermost; as noun (feminine plural) the depths (figuratively, a pit, the womb) low (parts, -er, -er parts, -est), nether (part).', 'from 8478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2022G}/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["and/ [the] mountain of","and/ mountain"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6225}/[H6225]', 'lemma', 'heb', 'עָשַׁן', '["ʻâshan"]', '["does it smoke?","have you smoked","it was smoking","it will smoke"]', '["v"]', 'to smoke, whether literal or figurative be angry (be on a) smoke.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6227}/H9023/[H6225]', 'inflected', 'heb', 'עָשָׁן', '["ʻâshân"]', '["smoke/ its"]', '["n-m"]', 'smoke, literally or figuratively (vapor, dust, anger) smoke(-ing).', 'from 6225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6227}/[H6225]', 'inflected', 'heb', 'עָשָׁן', '["ʻâshân"]', '["like <the>/ smoke","like/ [the] smoke of"]', '["n-m"]', 'smoke, literally or figuratively (vapor, dust, anger) smoke(-ing).', 'from 6225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7782}/[H8231]', 'inflected', 'heb', 'שׁוֹפָר', '["shôwphâr"]', '["<of> the/ trumpets","the/ ram''s horn","the/ trumpet","the/ trumpets"]', '["n-m"]', 'a cornet (as giving a clear sound) or curved horn cornet, trumpet.', 'or שֹׁפָר; from 8231 in the original sense of incising;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2390}/[H2388]', 'inflected', 'heb', 'חָזֵק', '["châzêq"]', '["and/ strong"]', '["a"]', 'powerful × wax louder, stronger.', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6030B}/H9033/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["I will answer/ him","[was] answering/ him","he answered/ him","he answers/ him","he had answered/ him","he will answer/ him","you must answer/ him"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963I>', 'inflected', 'heb', 'בקול', '["ve./Kol"]', '["with/ a voice"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5066G}/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["who/ draw near"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942G}/[H6942]', 'lemma', 'heb', 'קָדַשׁ', '["qâdash"]', '["I have consecrated","I set apart","I will consecrate","I will show myself holy","[am] sanctifying","[are] setting apart as holy","[was] purifying herself","[will] show himself holy","being consecrated of","consecrate","consecrate yourselves","he consecrated","he had consecrated","he has consecrated","it is holy","it will be holy","keep holy","sanctify yourselves","they are holy","they consecrated","they had consecrated themselves","they will consecrate","they will make themselves holy","they will regard as holy","they will sanctify","they will set apart as holy","you honored as holy","you will regard as holy"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5927G}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["for <the>/ [one who] goes up","to/ come up","to/ go up","to/ stir up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1379}/[H1366]', 'lemma', 'heb', 'גָּבַל', '["gâbal"]', '["[which] it borders","it borders","set a boundary for","they set bounds"]', '["v"]', 'properly, to twist as a rope; to bound (as by a line) be border, set (bounds about).', 'a primitive root; also as a denominative from 1366');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6942G}/H9033/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["and/ he set apart as holy/ it","and/ he will set apart as holy/ it","and/ you will consecrate/ it","and/ you will set apart as holy/ him"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3548}/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["and/ the/ priest","and/ the/ priests"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5971A}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ the/ people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/H9038\/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["to/ them"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0559}\/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["<to>/ saying"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6459}/[H6458]', 'lemma', 'heb', 'פֶּסֶל', '["peçel"]', '["<of> an idol","<of> an image","[the] carved image of","[the] idol of","[the] image of","a carved image","an idol","an image","an image of"]', '["n-m"]', 'an idol carved (graven) image.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8544}/[H4327]', 'lemma', 'heb', 'תְּמוּנָה', '["tᵉmûwnâh"]', '["a form","a form of","form"]', '["n-f"]', 'something portioned (i.e. fashioned) out, as a shape, i.e. (indefinitely) phantom, or (specifically) embodiment, or (figuratively) manifestation (of favor) image, likeness, similitude.', 'or תְּמֻנָה; from 4327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647H}/H9038/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["they served/ them","you must be enticed to serve/ them","you must serve/ them"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7067H}/[H7065]', 'lemma', 'heb', 'קַנָּא', '["qannâʼ"]', '["jealous"]', '["a"]', 'jealous jealous. Compare 7072.', 'from 7065;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7256}/[H7251]', 'lemma', 'heb', 'רִבֵּעַ', '["ribbêaʻ"]', '["a fourth generation"]', '["a"]', 'a descendant of the fourth generation, i.e. great great grandchild fourth.', 'from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8130}/H9030/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["of/ [those who] hate/ me"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0157G}/H9030/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["of/ [those who] love/ me","to <the>/ lovers/ my","to/ [those who] love/ me"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8104G}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ of/ [those who] keep","and/ to/ [those who] keep","and/ to/ keep","and/ to/ take care"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4687}/H9020\/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["commandments/ my"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7723H}/[H7722]', 'inflected', 'heb', 'שָׁוְא', '["shâvᵉʼ"]', '["for <the>/ emptiness","for <the>/ vanity","to <the>/ falsehood"]', '["n-m"]', 'evil (as destructive), literally (ruin) or morally (especially guile); figuratively idolatry (as false, subjective), uselessness (as deceptive, objective; also adverbially, in vain) false(-ly), lie, lying, vain, vanity.', 'or שַׁו; from the same as 7722 in the sense of desolating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7723H}\/[H7722]', 'inflected', 'heb', 'שָׁוְא', '["shâvᵉʼ"]', '["for <the>/ emptiness"]', '["n-m"]', 'evil (as destructive), literally (ruin) or morally (especially guile); figuratively idolatry (as false, subjective), uselessness (as deceptive, objective; also adverbially, in vain) false(-ly), lie, lying, vain, vanity.', 'or שַׁו; from the same as 7722 in the sense of desolating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6942G}/H9033/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["to/ consecrate/ him","to/ consecrate/ it","to/ set apart as holy/ him","to/ set apart as holy/ it"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4399}/H9021/[H4397]', 'inflected', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["[is] occupation/ your","work/ your","works/ your"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0519}/H9021/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["and/ female servant/ your","and/ female slave/ your","and/ maidservant/ your"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0929>/H9021', 'inflected', 'heb', 'ובהמתך', '["u./ve.hem.Te./kha"]', '["and/ livestock/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1616}/H9021/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["and/ sojourner/ your"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8179G}/H9021/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["[is] in/ gates/ your"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6942G}/H9033\/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["and/ he set apart as holy/ it"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0748}/H9013/[H748]', 'inflected', 'heb', 'אָרַךְ', '["ʼârak"]', '["they may be long/ !","they may grow long/ !","you will prolong/ !"]', '["v"]', 'to be (causative, make) long (literally or figuratively) defer, draw out, lengthen, (be, become, make, pro-) long, (out-, over-) live, tarry (long).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/H9021', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["[are] days/ your","day/ your","days/ your"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9031}\', 'inflected', 'arc', 'לך ס', '["La/kh"]', '["[will be] to/ you","for <the>/ yourself","for/ yourself","to <the>/ you","to/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7523}\/[H7523]', 'inflected', 'heb', 'רָצַח', '["râtsach"]', '["you must murder"]', '["v"]', 'properly, to dash in pieces, i.e. kill (a human being), especially to murder put to death, kill, (man-) slay(-er), murder(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5003}\/[H5003]', 'inflected', 'heb', 'נָאַף', '["nâʼaph"]', '["you must commit adultery"]', '["v"]', 'to commit adultery; figuratively, to apostatize adulterer(-ess), commit(-ing) adultery, woman that breaketh wedlock.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1589}\/[H1589]', 'inflected', 'heb', 'גָּנַב', '["gânab"]', '["you must steal"]', '["v"]', 'to thieve (literally or figuratively); by implication, to deceive carry away, × indeed, secretly bring, steal (away), get by stealth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7453}/H9021/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["against/ neighbor/ your","in/ neighbor/ your","to/ neighbor/ your"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8267}\/[H8266]', 'inflected', 'heb', 'שֶׁקֶר', '["sheqer"]', '["falsehood"]', '["n-m"]', 'an untruth; by implication, a sham (often adverbial) without a cause, deceit(-ful), false(-hood, -ly), feignedly, liar, lie, lying, vain (thing), wrongfully.', 'from 8266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7794}/H9023/[H7788]', 'inflected', 'heb', 'שׁוֹר', '["shôwr"]', '["and/ ox/ his"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2543}/H9023/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["and/ donkey/ his"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7453}/H9021\/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["[belongs] to/ neighbor/ your"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3940>', 'inflected', 'heb', 'הלפידם', '["ha./la.pi.Dim"]', '["<the>/ torches","the/ lightning"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6226}/[H6225]', 'lemma', 'heb', 'עָשֵׁן', '["ʻâshên"]', '["smoking"]', '["a"]', 'smoky smoking.', 'from 6225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5128}/[H5128]', 'inflected', 'heb', 'נוּעַ', '["nûwaʻ"]', '["and/ I will shake","and/ it shook","and/ people will stagger","and/ they have shaken","and/ they shook","and/ they staggered","and/ they trembled","and/ they will tremble"]', '["v"]', 'to waver, in a great variety of applications, literally and figuratively (as subjoined) continually, fugitive, × make, to (go) up and down, be gone away, (be) move(-able, -d), be promoted, reel, remove, scatter, set, shake, sift, stagger, to and fro, be vagabond, wag, (make) wander (up and down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9003/{H5668}/[H5674]', 'inflected', 'heb', 'עָבוּר', '["ʻâbûwr"]', '["<to>/ in/ order"]', '["prep"]', 'properly, crossed, i.e. (abstractly) transit; used only adverbially, on account of, in order that because of, for (...''s sake), (intent) that, to.', 'or עָבֻר; passive participle of 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5668}/[H5674]', 'inflected', 'heb', 'עָבוּר', '["ʻâbûwr"]', '["and/ in/ order","and/ in/order that"]', '["prep"]', 'properly, crossed, i.e. (abstractly) transit; used only adverbially, on account of, in order that because of, for (...''s sake), (intent) that, to.', 'or עָבֻר; passive participle of 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3374}/H9023/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["fear/ his"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6205}/[H6201]', 'inflected', 'heb', 'עֲרָפֶל', '["ʻărâphel"]', '["the/ thick darkness"]', '["n-m"]', 'gloom (as of a lowering sky) (gross, thick) dark (cloud, -ness).', 'probably from 6201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0430G}\/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["<the>/ God","[is] <the>/ God"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213H}/H9013/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["they will produce/ !","you must make/ !"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0430J}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ gods","and/ gods of"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5930A}/H9021/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["burnt offering/ your","burnt offerings/ your"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8002}/H9021/[H7999]', 'inflected', 'heb', 'שֶׁלֶם', '["shelem"]', '["peace offerings/ your"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1241}/H9021/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["cattle/ your","herd/ your"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1496}/[H1491]', 'lemma', 'heb', 'גָּזִית', '["gâzîyth"]', '["hewn [stone]"]', '["n-f"]', 'something cut, i.e. dressed stone hewed, hewn stone, wrought.', 'from 1491;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5130B}/[H5130]', 'lemma', 'heb', 'נוּף', '["nûwph"]', '["I brandished","[am] about to brandish","[is] brandishing","anyone has wielded","he waved","he will shake","it was waved","wave","you have wielded","you will wield"]', '["v"]', 'to quiver (i.e. vibrate up and down, or rock to and fro); used in a great variety of applications (including sprinkling, beckoning, rubbing, bastinadoing, sawing, waving, etc.) lift up, move, offer, perfume, send, shake, sift, strike, wave.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2490H}/H9034/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["and/ you have profaned/ it"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4609B}/[H4608]', 'inflected', 'heb', 'מַעֲלָה', '["maʻălâh"]', '["on the/ steps","on/ [the] steps of","on/ steps"]', '["n-f"]', 'elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story.', 'feminine of 4608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4196}/H9020/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["altar/ my"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1540I}/[H1540]', 'lemma', 'heb', 'גָּלָה', '["gâlâh"]', '["I will uncover","has he uncovered","he has uncovered","he has uncovered himself","he will uncover","it will be uncovered","let it be uncovered","reveal yourselves","shamelessly <uncover>","she has uncovered","someone has uncovered","they have been uncovered","they have made known","they uncovered","they were uncovered","uncover","uncovered","you have uncovered","you will uncover"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6172}/H9021/[H6168]', 'inflected', 'heb', 'עֶרְוָה', '["ʻervâh"]', '["[are] own nakedness/ your","nakedness/ your"]', '["n-f"]', 'nudity, literally (especially the pudenda) or figuratively (disgrace, blemish) nakedness, shame, unclean(-ness).', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9033\/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["on/ it"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4941G}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["<the>/ judgment","[are] the/ judgments","the/ judgment","the/ judgments","the/ place of judgment","the/ verdict"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7637}/[H7657]', 'inflected', 'heb', 'שְׁבִיעִי', '["shᵉbîyʻîy"]', '["and/ in the/ seventh [month]","and/ in the/ seventh [year]"]', '["a"]', 'seventh seventh (time).', 'or שְׁבִעִי; ordinal from 7657;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2670}/[H2666]', 'inflected', 'heb', 'חׇפְשִׁי', '["chophshîy"]', '["to <the>/ free [person]"]', '["a"]', 'exempt (from bondage, tax or care) free, liberty.', 'from 2666;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1610>/H9023', 'inflected', 'heb', 'בגפו', '["be./ga.P/o","ve./ga.P/o"]', '["with/ body/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1167H}/[H1166]', 'lemma', 'heb', 'בַּעַל', '["baʻal"]', '["[is the] husband of","[the] husband of","a husband"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0802H}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["O/ wife","the/ wife","the/ woman","the/ women"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0113>/H9024', 'inflected', 'heb', 'לאדניה', '["la./do.Nei./ha"]', '["to/ master<s>/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2670}/[H2666]', 'lemma', 'heb', 'חׇפְשִׁי', '["chophshîy"]', '["[is] free","a [person] set free","a free [person]","free","free [people]"]', '["a"]', 'exempt (from bondage, tax or care) free, liberty.', 'from 2666;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5066H}/H9033/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["and/ he will bring near/ him"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7527}/[H7527]', 'inflected', 'heb', 'רָצַע', '["râtsaʻ"]', '["and/ he will pierce"]', '["v"]', 'to pierce bore.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0241G}/H9023/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["ear/ his","ear/ its","ears/ his"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4836}/[H7527]', 'inflected', 'heb', 'מַרְצֵעַ', '["martsêaʻ"]', '["with the/ awl"]', '["n-m"]', 'an awl aul.', 'from 7527;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5647G}/H9033/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ he will serve/ him","and/ it will serve/ him","and/ they served/ him","and/ they will serve/ him"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5769G}\/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["for/ ever"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0519}/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["to/ a female slave"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3318G}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ go out","when/ went out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0113>/H9024', 'opaque', 'heb', 'אָדוֹן', '["ʼâdôwn"]', '["master<s>/ her"]', '["n-m"]', 'sovereign, i.e. controller (human or divine) lord, master, owner. Compare also names beginning with ''Adoni-''.', 'or (shortened) אָדֹן; from an unused root (meaning to rule);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3259}/H9034/[H3259]', 'inflected', 'heb', 'יָעַד', '["yâʻad"]', '["he appointed/ it","he designated/ her","he will designate/ her"]', '["v"]', 'to fix upon (by agreement or appointment); by implication, to meet (at a stated time), to summon (to trial), to direct (in a certain quarter or position), to engage (for marriage) agree,(maxke an) appoint(-ment, a time), assemble (selves), betroth, gather (selves, together), meet (together), set (a time).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6299}/H9034/[H6299]', 'inflected', 'heb', 'פָּדָה', '["pâdâh"]', '["and/ he will let be ransomed/ her"]', '["v"]', 'to sever, i.e. ransom; generally to release, preserve × at all, deliver, × by any means, ransom, (that are to be, let be) redeem(-ed), rescue, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4376}/H9034/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["to/ sell/ her"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0898}/H9043/[H898]', 'inflected', 'heb', 'בָּגַד', '["bâgad"]', '["because/ has dealt treacherously/ he"]', '["v"]', 'to cover (with a garment); figuratively, to act covertly; by implication, to pillage deal deceitfully (treacherously, unfaithfully), offend, transgress(-or), (depart), treacherous (dealer, -ly, man), unfaithful(-ly, man), × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4941H}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["according to/ [the] custom of"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7607}/H9024/[H7604]', 'inflected', 'heb', 'שְׁאֵר', '["shᵉʼêr"]', '["food/ her"]', '["n-m"]', 'flesh (as swelling out), as living or for food; generally food of any kind; figuratively, kindred by blood body, flesh, food, (near) kin(-sman, -swoman), near (nigh) (of kin).', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3682}/H9024/[H3680]', 'inflected', 'heb', 'כְּסוּת', '["kᵉçûwth"]', '["covering/ her"]', '["n-f"]', 'a cover (garment); figuratively, a veiling covering, raiment, vesture.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5772>/H9024', 'inflected', 'heb', 'וענתה', '["ve./''o.na.Ta/h"]', '["and/ right to intercourse/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3701G}\/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["money"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6658A}/[H6658]', 'lemma', 'heb', 'צָדָה', '["tsâdâh"]', '["[are] lying in wait for","he was lying in wait"]', '["v"]', 'to chase; by implication, to desolate destroy, hunt, lie in wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0579}/[H578]', 'lemma', 'heb', 'אָנָה', '["ʼânâh"]', '["[is] seeking an opportunity","he allowed to happen","it happens","it will happen"]', '["v"]', 'to approach; hence, to meet in various senses befall, deliver, happen, seek a quarrel.', 'a primitive root (perhaps rather identical with 578 through the idea of contraction in anguish);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3027H}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["to/ hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8033G}/H9011\/[H834]', 'inflected', 'heb', 'שָׁם', '["shâm"]', '["there/ <towards>","there/ towards"]', '["adv"]', 'there (transferring to time) then; often thither, or thence in it, thence, there (-in, of, out), thither, whither.', 'a primitive particle (rather from the relative pronoun, 834);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2026}/H9033/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["to/ kill/ him"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6195}/[H6193]', 'inflected', 'heb', 'עׇרְמָה', '["ʻormâh"]', '["with/ cunning"]', '["n-f"]', 'trickery; or (in a good sense) discretion guile, prudence, subtilty, wilily, wisdom.', 'feminine of 6193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947G}/H9033/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["I took/ it","fetch/ it","he takes/ it","it takes/ it","let it take/ it","take/ him","will anyone take?/ it","will you take?/ it","you will take/ him","you will take/ it"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4191}\/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["to/ die"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0517}/H9023/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["and/ mother/ his"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4376}/H9033/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["and/ he will sell/ him"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}\/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["he died","he had died","he has died","he will be put to death","he will die","it will die","they died","they will be put to death","they will die","you will die"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0068G}/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["by/ [the] stones of","in <the>/ stone<s>","on <the>/ stone","with <the>/ stone[s]","with <the>/ stones","with the/ stone","with/ a stone","with/ a stone of"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0106}/[H1640]', 'inflected', 'heb', 'אֶגְרֹף', '["ʼegrôph"]', '["with/ a fist","with/ a fist of"]', '["n-m"]', 'the clenched hand fist.', 'from 1640 (in the sense of grasping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4904}/[H7901]', 'inflected', 'heb', 'מִשְׁכָּב', '["mishkâb"]', '["to/ [the] lying of","to/ a bed","to/ a bed of","to/ lying of"]', '["n-m"]', 'a bed (figuratively, a bier); abstractly, sleep; by euphemism, carnal intercourse bed(-chamber), couch, lieth (lying) with.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4938B}/H9023/[H4937]', 'inflected', 'heb', 'מִשְׁעֵנָה', '["mishʻênâh"]', '["staff/ his"]', '["n-f"]', 'support (abstractly), i.e. (figuratively) sustenance or (concretely) a walking-stick staff.', 'or מִשְׁעֶנֶת; feminine of 4937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7674}/H9023/[H7673]', 'inflected', 'heb', 'שֶׁבֶת', '["shebeth"]', '["sitting still/ his"]', '["n-f"]', 'rest, interruption, cessation cease, sit still, loss of time.', 'from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7495}/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["and/ certainly <to heal>","and/ healing","so/ I may be healed","so/ I may heal","so/ they may be healed"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7495}\/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["he will have [him] healed","he will heal"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0519}/H9023/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["female slave/ his","maidservant/ his"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7626G>', 'inflected', 'heb', 'בשבט', '["ba./Sha.vet","ba./She.vet","be./She.vet","va./She.vet","ve./She.vet"]', '["by/ [the] rod of","with <the>/ rod","with the/ club","with the/ rod","with the/ staff","with/ [the] rod of","with/ [the] staff of","with/ a rod","with/ a rod of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478K}/[H8430]', 'lemma', 'heb', 'תַּחַת', '["tachath"]', '["[will be] under","under"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027W}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5062}/[H5062]', 'inflected', 'heb', 'נָגַף', '["nâgaph"]', '["and/ I struck","and/ he defeated","and/ he struck","and/ he was defeated","and/ he will strike","and/ it was defeated","and/ they were defeated","and/ they will strike","and/ you will be defeated"]', '["v"]', 'to push, gore, defeat, stub (the toe), inflict (a disease) beat, dash, hurt, plague, slay, smite (down), strike, stumble, × surely, put to the worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3206}/H9024/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["children/ her"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6064}/[H6064]', 'lemma', 'heb', 'עָנַשׁ', '["ʻânash"]', '["certainly <to fine>","fines","he will be fined","they are punished","to impose a fine"]', '["v"]', 'properly, to urge; by implication, to inflict a penalty, specifically, to fine amerce, condemn, punish, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896G}/[H7896]', 'lemma', 'heb', 'שִׁית', '["shîyth"]', '["I have made","I will make","I will set","certainly <to take a stand>","he made","he sets","he will impose","it will be imposed","it will make","make","they have set","they have taken a stand","they set","they took a stand","you make","you set","you will set"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414N}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will requite","and/ he gave","and/ he will give","and/ people will requite","and/ they paid","and/ they will give","and/ you will give"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6414}/[H6419]', 'inflected', 'heb', 'פָּלִיל', '["pâlîyl"]', '["for/ [the] estimate"]', '["n-m"]', 'a magistrate judge.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7272}/[H7270]', 'lemma', 'heb', 'רֶגֶל', '["regel"]', '["<of> feet","[the] feet of","[the] foot","[the] foot of","[was] a foot","a foot","a foot of","both feet","feet","foot"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3555}/[H3554]', 'lemma', 'heb', 'כְּוִיָּה', '["kᵉvîyâh"]', '["burning"]', '["n-f"]', 'a branding burning.', 'from 3554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6482}/[H6481]', 'lemma', 'heb', 'פֶּצַע', '["petsaʻ"]', '["[the] wounds of","bruise","bruise[s]","wounds"]', '["n-m"]', 'a wound wound(-ing).', 'from 6481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2250}/[H2266]', 'lemma', 'heb', 'חַבּוּרָה', '["chabbûwrâh"]', '["wound","wounds of"]', '["n-f"]', 'properly, bound (with stripes), i.e. a weal (or black-and-blue mark itself) blueness, bruise, hurt, stripe, wound.', 'or חַבֻּרָה; or חֲבֻרָה; from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2250}\/[H2266]', 'inflected', 'heb', 'חַבּוּרָה', '["chabbûwrâh"]', '["wound"]', '["n-f"]', 'properly, bound (with stripes), i.e. a weal (or black-and-blue mark itself) blueness, bruise, hurt, stripe, wound.', 'or חַבֻּרָה; or חֲבֻרָה; from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7843}/H9034/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["and/ he will destroy/ it"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971H}/H9033/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["he will set free/ him","you will let go/ him"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478J}/[H8430]', 'lemma', 'heb', 'תַּחַת', '["tachath"]', '["because","for","in place of"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869A}/H9023\/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eye/ his"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307H}/[H5307]', 'lemma', 'heb', 'נָפַל', '["nâphal"]', '["[am] falling","[are] falling","he will fall","he will knock out","she has made fall","they fell","they had fallen","they have fallen","you will cast"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8127G}/H9023\/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["teeth/ his","tooth/ his"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5055}/[H5055]', 'lemma', 'heb', 'נָגַח', '["nâgach"]', '["he will gore","he will wage war","it will gore","thrusting","we gore","you thrust at","you will gore"]', '["v"]', 'to butt with the horns; figuratively, to war against gore, push (down, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7794}/[H7788]', 'inflected', 'heb', 'שׁוֹר', '["shôwr"]', '["<the>/ ox","the/ ox"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1320}/H9023/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["body/ his","flesh/ his","flesh/ its","meat/ its","own flesh/ his"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1167G}/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["and/ [the] owner of"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5056}/[H5055]', 'lemma', 'heb', 'נַגָּח', '["naggâch"]', '["prone to gore"]', '["a"]', 'butting, i.e. vicious used (wont) to push.', 'from 5055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5749B}/[H5749]', 'inflected', 'heb', 'עוּד', '["ʻûwd"]', '["and/ I caused to witness [it]","and/ I protested","and/ did I warn?","and/ he admonished","and/ he warned","and/ it has been protested","and/ they warned","and/ you warned"]', '["v"]', 'to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1167G}/H9023/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["on/ owner<s>/ its"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104I}/H9033/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["he guarded/ it","he will guard/ it"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1167G}/H9023/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["owner<s>/ its","owners/ its"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3724A}/[H3722]', 'lemma', 'heb', 'כֹּפֶר', '["kôpher"]', '["[is] a ransom","[the] ransom","[the] ransom of","a ransom","ransom"]', '["n-m"]', 'properly, a cover, i.e. (literally) a village (as covered in); (specifically) bitumen (as used for coating), and the henna plant (as used for dyeing); figuratively, a redemption-price bribe, camphire, pitch, ransom, satisfaction, sum of money, village.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6306B}/[H6299]', 'lemma', 'heb', 'פִּדְיוֹם', '["pidyôwm"]', '["[the] ransom of"]', '["n-m"]', 'a ransom ransom, that were redeemed, redemption.', 'or פִּדְיֹם; also פִּדְיוֹן; or פִּדְיֹן; from 6299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315H}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["<of> life/ his","breath/ its","life/ his","life/ its","own self/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4941G}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["according to the/ judgment","according to the/ ordinance","according to/ [the] ordinance of"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0519}/[H519]', 'lemma', 'heb', 'אָמָה', '["ʼâmâh"]', '["[the] maidservants of","a female slave"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0113>/H9023', 'inflected', 'heb', 'לאדניו', '["la./do.Na/v"]', '["to/ master<s>/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7794}/[H7788]', 'inflected', 'heb', 'שׁוֹר', '["shôwr"]', '["and/ the/ ox"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5619}\/[H5619]', 'inflected', 'heb', 'סָקַל', '["çâqal"]', '["it will be stoned to death"]', '["v"]', 'properly, to be weighty; but used only in the sense of lapidation or its contrary (as if a delapidation) (cast, gather out, throw) stone(-s), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0953A}/[H952]', 'lemma', 'heb', 'בּוֹר', '["bôwr"]', '["<of> [the] pit","[the] pit","[the] pit of","a cistern","a pit","wells"]', '["n-m"]', 'a pit hole (especially one used as a cistern or a prison) cistern, dungeon, fountain, pit, well.', 'from 952 (in the sense of 877);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3680}/H9033/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["I will cover/ it","he will cover/ it","it covered/ it","you covered/ it"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1167G}/[H1166]', 'lemma', 'heb', 'בַּעַל', '["baʻal"]', '["O citizens of","[the] citizens of","[the] master of","[the] owner of","rulers of"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1167G}/H9023/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["by/ owner<s>/ its","to/ owner<s>/ its"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4191}/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ the/ [one who] dies","and/ the/ dead","and/ the/ dead [animal]"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9033}\', 'inflected', 'heb', 'לו ס', '["l/o"]', '["<to>/ it","[belong] to <the>/ him","[belonged] to/ him","for/ him","to <the>/ him","to <the>/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3701H}/H9023/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["silver/ its"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4191}/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["<the>/ dead","[is] the/ dead [one]","the/ [one which] dies","the/ [one who] dies","the/ [ones who] died","the/ dead","the/ dead [animal]","the/ dead [man]","the/ dead [one]","those/ [who] died","who/ were about to be put to death","who/ were being put to death"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2673}/H9013/[H2086]', 'inflected', 'heb', 'חָצָה', '["châtsâh"]', '["they will divide/ !"]', '["v"]', 'to cut or split in two; to halve divide, × live out half, reach to the midst, participle', 'a primitive root (compare 2086));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2873}/H9033/[H2873]', 'inflected', 'heb', 'טָבַח', '["ṭâbach"]', '["and/ he will slaughter/ it"]', '["v"]', 'to slaughter (animals or men) kill, (make) slaughter, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4376}/H9033/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["he has sold/ it"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4290}/[H2864]', 'inflected', 'heb', 'מַחְתֶּרֶת', '["machtereth"]', '["in <the>/ breaking in"]', '["n-m"]', 'a burglary; figuratively, unexpected examination breaking up, secret search.', 'from 2864;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1590}/[H1589]', 'inflected', 'heb', 'גַּנָּב', '["gannâb"]', '["the/ thief"]', '["n-m"]', 'a stealer thief.', 'from 1589;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2224}/[H2224]', 'lemma', 'heb', 'זָרַח', '["zârach"]', '["[is] rising","[when] it dawns","he will dawn","it arose","it has dawned","it has risen","it rises","it shines","it shone"]', '["v"]', 'properly, to irradiate (or shoot forth beams), i.e. to rise (as the sun); specifically, to appear (as a symptom of leprosy) arise, rise (up), as soon as it is up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1591}/H9023/[H1589]', 'inflected', 'heb', 'גְּנֵבָה', '["gᵉnêbâh"]', '["for/ theft/ his"]', '["n-f"]', 'stealing, i.e. (concretely) something stolen theft.', 'from 1589;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1591}/[H1589]', 'inflected', 'heb', 'גְּנֵבָה', '["gᵉnêbâh"]', '["the/ thing stolen"]', '["n-f"]', 'stealing, i.e. (concretely) something stolen theft.', 'from 1589;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7794}/[H7788]', 'inflected', 'heb', 'שׁוֹר', '["shôwr"]', '["from/ [the] ox of","from/ an ox","more than/ an ox"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7999A}\/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["he will make compensation","he will make restitution"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1197B}/[H1198]', 'lemma', 'heb', 'בָּעַר', '["bâʻar"]', '["O stupid [ones]","brutish","foolish","he is stupid","he will cause to be grazed over","they are stupid","they have behaved stupidly"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1165}/H9023/[H1197]', 'inflected', 'heb', 'בְּעִיר', '["bᵉʻîyr"]', '["cattle/ his"]', '["n-m"]', 'cattle beast, cattle.', 'from 1197 (in the sense of eating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1197B}/[H1198]', 'inflected', 'heb', 'בָּעַר', '["bâʻar"]', '["and/ it will graze"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4315}/[H3190]', 'lemma', 'heb', 'מֵיטָב', '["mêyṭâb"]', '["[the] best of"]', '["n-m"]', 'the best part best.', 'from 3190;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4315}/[H3190]', 'inflected', 'heb', 'מֵיטָב', '["mêyṭâb"]', '["and/ [the] best of"]', '["n-m"]', 'the best part best.', 'from 3190;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3754>/H9023', 'opaque', 'heb', 'כֶּרֶם', '["kerem"]', '["vineyard/ his"]', '["n-m"]', 'a garden or vineyard vines, (increase of the) vineyard(-s), vintage. See also 1021.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6975}/[H6972]', 'lemma', 'heb', 'קוֹץ', '["qôwts"]', '["<the> thorns of","[the] thorns of","thorn[s]","thornbush[es]","thornbushes","thorns"]', '["n-m"]', 'a thorn thorn.', 'or קֹץ; from 6972 (in the sense of pricking);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1430A>', 'opaque', 'heb', 'גָּדִישׁ', '["gâdîysh"]', '["a heap of sheaves"]', '["n-m"]', 'a stack of sheaves; by analogy, a tomb shock (stack) (of corn), tomb.', 'from an unused root (meaning to heap up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7054}/[H6965]', 'inflected', 'heb', 'קָמָה', '["qâmâh"]', '["the/ standing grain"]', '["n-f"]', 'something that rises, i.e. a stalk of grain (standing) corn, grown up, stalk.', 'feminine of active participle of 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1197A}/[H1198]', 'inflected', 'heb', 'בָּעַר', '["bâʻar"]', '["the/ [one who] kindled"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1200}\/[H1197]', 'inflected', 'heb', 'בְּעֵרָה', '["bᵉʻêrâh"]', '["the/ fire"]', '["n-f"]', 'a burning fire.', 'from 1197;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4399}/[H4397]', 'inflected', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["<in> the/ work","[are] in the/ work","in the/ work","in/ [the] work of","on/ [the] property of","on/ [the] work of"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8008}/[H8071]', 'lemma', 'heb', 'שַׂלְמָה', '["salmâh"]', '["[the] cloak of","a garment"]', '["n-f"]', 'a dress clothes, garment, raiment.', 'transp. for 8071;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0009}/[H6]', 'lemma', 'heb', 'אֲבֵדָה', '["ʼăbêdâh"]', '["<the> thing lost of","a thing lost","thing lost"]', '["n-f"]', 'concrete, something lost; abstract, destruction, i.e. Hades lost.', 'from 6; Compare 10.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7561}/H9013/[H7561]', 'inflected', 'heb', 'רָשַׁע', '["râshaʻ"]', '["they will condemn as guilty/ !"]', '["v"]', 'to be (causatively, do or declare) wrong; by implication, to disturb, violate condemn, make trouble, vex, be (commit, deal, depart, do) wicked(-ly, -ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7453}/H9023\/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["to/ neighbor/ his"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7621}/[H7650]', 'lemma', 'heb', 'שְׁבוּעָה', '["shᵉbûwʻâh"]', '["[the] oath of","an oath","oath","oath of","oaths","oaths of"]', '["n-f"]', 'properly, something sworn, i.e. an oath curse, oath, × sworn.', 'feminine passive participle of 7650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2966}/[H2964]', 'inflected', 'heb', 'טְרֵפָה', '["ṭᵉrêphâh"]', '["the/ torn animal"]', '["n-f"]', 'prey, i.e. flocks devoured by animals ravin, (that which was) torn (of beasts, in pieces).', 'feminine (collectively) of 2964;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7665}/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["and/ I broke","and/ I will break","and/ he broke","and/ he broke down","and/ he broke in pieces","and/ he will break","and/ it broke","and/ it has been broken","and/ it was broken","and/ it will be maimed","and/ they broke","and/ they were broken","and/ they will be broken","and/ they will be shattered","and/ you will break","and/ you will shatter"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7916}/[H7936]', 'lemma', 'heb', 'שָׂכִיר', '["sâkîyr"]', '["[was] hired","a hired laborer"]', '["a"]', 'a man at wages by the day or year hired (man, servant), hireling.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7939}/H9023\/[H7936]', 'inflected', 'heb', 'שָׂכָר', '["sâkâr"]', '["for/ hire/ its"]', '["n-m"]', 'payment of contract; concretely, salary, fare, maintenance; by implication, compensation, benefit hire, price, reward(-ed), wages, worth.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6601B}/[H6601]', 'lemma', 'heb', 'פָּתָה', '["pâthâh"]', '["I have deceived","entice","he deceives","he will be deceived","he will be persuaded","he will seduce","it has been deceived","it should be deceived","silly","will he deceive","you will deceive"]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0781}/[H781]', 'lemma', 'heb', 'אָרַשׂ', '["ʼâras"]', '["I betrothed","betrothed","he has betrothed","she is betrothed","she was betrothed","you will betroth"]', '["v"]', 'to engage for matrimony betroth, espouse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4117}/[H4116]', 'lemma', 'heb', 'מָהַר', '["mâhar"]', '["certainly <to pay [the] bride-price>"]', '["v"]', 'to bargain (for a wife), i.e. to wed endow, × surely.', 'a primitive root (perhaps rather the same as 4116 through the idea of readiness in assent);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4117}/H9034/[H4116]', 'inflected', 'heb', 'מָהַר', '["mâhar"]', '["he will pay [the] bride-price for/ her"]', '["v"]', 'to bargain (for a wife), i.e. to wed endow, × surely.', 'a primitive root (perhaps rather the same as 4116 through the idea of readiness in assent);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5414G}/H9034/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["to/ give/ her","to/ give/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8254}/[H8254]', 'lemma', 'heb', 'שָׁקַל', '["shâqal"]', '["I will weigh out","[is one who] weighed","[were] weighing","certainly [if] <to weigh>","do you weigh out","he will weigh out","it was weighed out","it will be weighed","it will be weighed out","they weigh out","you will weigh [them] out","you will weigh out"]', '["v"]', 'to suspend or poise (especially in trade) pay, receive(-r), spend, × throughly, weigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4119}/[H4117]', 'inflected', 'heb', 'מֹהַר', '["môhar"]', '["according to/ [the] bride-price of"]', '["n-m"]', 'a price (for a wife) dowry.', 'from 4117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1330>\', 'inflected', 'heb', 'הבתולת ס', '["ha./be.tu.Lot"]', '["<the>/ virgins"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3784}/[H3784]', 'lemma', 'heb', 'כָּשַׁף', '["kâshaph"]', '["a sorceress"]', '["v"]', 'properly, to whisper a spell, i.e. to inchant or practise magic sorcerer, (use) witch(-craft).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2421}\/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["you will let live"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0430J}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["<to>/ gods","to the/ gods","to/ [the] gods of","to/ gods"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2763A}/[H2763]', 'lemma', 'heb', 'חָרַם', '["châram"]', '["I totally destroyed","certainly <to totally destroy>","he had totally destroyed","he totally destroyed","he will be dedicated to destruction","he will dedicate to destruction","it will be forfeited","they totally destroyed","they totally destroyed [them]","totally destroy","we totally destroyed","you should totally destroy","you totally destroyed","you will totally destroy"]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1616}/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["and/ [the] sojourner","and/ a sojourner","and/ sojourner"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3238}/[H3238]', 'lemma', 'heb', 'יָנָה', '["yânâh"]', '["he has oppressed","he oppressed","they have maltreated","they will oppress","you maltreat","you must maltreat","you will maltreat"]', '["v"]', 'to rage or be violent; by implication, to suppress, to maltreat destroy, (thrust out by) oppress(-ing, -ion, -or), proud, vex, do violence.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3905}/H9033/[H3905]', 'inflected', 'heb', 'לָחַץ', '["lâchats"]', '["[those who] oppress/ it","you must oppress/ him"]', '["v"]', 'properly, to press, i.e. (figuratively) to distress afflict, crush, force, hold fast, oppress(-or), thrust self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3490>', 'inflected', 'heb', 'ויתומים', '["ve./ya.Tom","vi./to.Mim"]', '["and/ [the] fatherless","and/ a fatherless one","and/ fatherless ones"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6031B}/H9013/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["you must afflict/ !"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6818}/H9023/[H6817]', 'inflected', 'heb', 'צַעֲקָה', '["tsaʻăqâh"]', '["cry of distress/ his","cry of distress/ its"]', '["n-f"]', 'a shriek cry(-ing).', 'from 6817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639G}/H9020/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["anger/ my"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0802H}/H9026/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["wives/ your"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121A}/H9026/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ children/ your","and/ sons/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3490>\', 'opaque', 'heb', 'יָתוֹם', '["yâthôwm"]', '["fatherless ones"]', '["n-m"]', 'a bereaved person fatherless (child), orphan.', 'from an unused root meaning to be lonely;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3867B}/[H3867]', 'lemma', 'heb', 'לָוָה', '["lâvâh"]', '["[is] borrowing","[is] lending to","a borrower","a lender","we have borrowed","you will borrow","you will lend to"]', '["v"]', 'properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6041}/[H6031]', 'inflected', 'heb', 'עָנִי', '["ʻânîy"]', '["the/ poor","the/ poor [people]","the/ poor [person]"]', '["a"]', 'depressed, in mind or circumstances afflicted, humble, lowly, needy, poor.', 'from 6031; (practically the same as 6035, although the margin constantly disputes this, making 6035 subjective and objective);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5383}/[H5382]', 'inflected', 'heb', 'נָשָׁה', '["nâshâh"]', '["as the/ creditor","like/ a creditor"]', '["v"]', 'to lend or (by reciprocity) borrow on security or interest creditor, exact, extortioner, lend, usurer, lend on (taker on) usury.', 'a primitive root (rather identical with 5382, in the sense of 5378);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760I}/H9013/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["you must put/ !"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5392}/[H5391]', 'lemma', 'heb', 'נֶשֶׁךְ', '["neshek"]', '["interest","interest of"]', '["n-m"]', 'interest on a debt usury.', 'from 5391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2254A}/[H2254]', 'lemma', 'heb', 'חָבַל', '["châbal"]', '["anyone will take as pledge","certainly [if] <to take as pledge>","he has taken as pledge","taken in pledge","they take as pledge","they take pledges","you have held in pledge","you will take as pledge"]', '["v"]', 'to wind tightly (as a rope), i.e. to bind; specifically, by a pledge; figuratively, to pervert, destroy; also to writhe in pain (especially of parturition) × at all, band, bring forth, (deal) corrupt(-ly), destroy, offend, lay to (take a) pledge, spoil, travail, × very, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3682}/H9023/[H3680]', 'inflected', 'heb', 'כְּסוּת', '["kᵉçûwth"]', '["[is] covering/ his"]', '["n-f"]', 'a cover (garment); figuratively, a veiling covering, raiment, vesture.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0905H}/H9034/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["to/ alone/ it"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5785}/H9023/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["for/ skin/ his"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7901H}/[H7901]', 'lemma', 'heb', 'שָׁכַב', '["shâkab"]', '["[was] lying","he will lie down","it rests","will he lie down","you will lie down"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2587}/[H2603]', 'lemma', 'heb', 'חַנּוּן', '["channûwn"]', '["[am] gracious","[is] gracious","[the] gracious","gracious"]', '["a"]', 'gracious gracious.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0589}\/[H595]', 'inflected', 'heb', 'אֲנִי', '["ʼănîy"]', '["I"]', '["p"]', 'I I, (as for) me, mine, myself, we, × which, × who.', 'contracted from 595;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5387A}/[H5375]', 'inflected', 'heb', 'נָשִׂיא', '["nâsîyʼ"]', '["and/ [the] leader","and/ [the] leader of","and/ [the] leaders of","and/ [the] prince","and/ a leader","and/ a prince"]', '["n-m"]', 'properly, an exalted one, i.e. a king or sheik; also a rising mist captain, chief, cloud, governor, prince, ruler, vapour.', 'or נָשִׂא; from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5971A}/H9021/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["among/ kinspeople<s>/ your","among/ people/ your","in/ people/ your","on/ people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4395}/H9021/[H4392]', 'inflected', 'heb', 'מְלֵאָה', '["mᵉlêʼâh"]', '["full produce/ your"]', '["n-f"]', 'something fulfilled, i.e. abundance (of produce) (first of ripe) fruit, fulness.', 'feminine of 4392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1831}/H9021/[H1830]', 'inflected', 'heb', 'דֶּמַע', '["demaʻ"]', '["and/ juice/ your"]', '["n-m"]', 'a tear; figuratively, juice liquor.', 'from 1830;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7794}/H9021/[H7788]', 'inflected', 'heb', 'שׁוֹר', '["shôwr"]', '["to/ ox/ your"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6629G>/H9021', 'inflected', 'heb', 'לצאנך', '["le./tzo.Ne./kha"]', '["to/ sheep/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8066}/[H8083]', 'inflected', 'heb', 'שְׁמִינִי', '["shᵉmîynîy"]', '["<the>/ eighth","[was] the/ eighth","the/ eighth"]', '["a"]', 'eight eight.', 'from 8083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414G}/H9033/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["I have assigned/ it","I have given/ it","I will give/ him","[am] about to give/ it","give/ it","he gave/ him","he will give/ it","they gave/ it","to give/ him","you gave/ it","you give/ him","you will give/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1961}/H9013/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["you will be/ !"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3611>', 'inflected', 'heb', 'לכלב', '["la./Ke.lev","le./Khe.lev"]', '["to the/ dog[s]","to/ a dog"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7993}/H9013/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["you will throw/ !"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0853}/H9033\/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["<obj.>/ him","<obj.>/ it"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375N}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["[am] lifting up","he lifted up","he lifts up","he will lift up","let them lift up","someone will lift up","take up","they will lift up","to take up","will they lift up","you lift up","you must bear"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7723G}/[H7722]', 'lemma', 'heb', 'שָׁוְא', '["shâvᵉʼ"]', '["deceitfulness","falsehood","worthlessness"]', '["n-m"]', 'evil (as destructive), literally (ruin) or morally (especially guile); figuratively idolatry (as false, subjective), uselessness (as deceptive, objective; also adverbially, in vain) false(-ly), lie, lying, vain, vanity.', 'or שַׁו; from the same as 7722 in the sense of desolating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2555}\/[H2554]', 'inflected', 'heb', 'חָמָס', '["châmâç"]', '["injustice"]', '["n-m"]', 'violence; by implication, wrong; by metonymy unjust gain cruel(-ty), damage, false, injustice, × oppressor, unrighteous, violence (against, done), violent (dealing), wrong.', 'from 2554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7451I}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["for/ evil","for/ harm","into/ an evil","to <the>/ evil","to/ wicked deeds"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5186}/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["by/ turning aside","to/ bend down","to/ incline","to/ stretch out","to/ thrust aside","to/ turn aside"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1800}/[H1809]', 'inflected', 'heb', 'דַּל', '["dal"]', '["and/ a poor [person]","and/ poor"]', '["a"]', 'properly, dangling, i.e. (by implication) weak or thin lean, needy, poor (man), weaker.', 'from 1809;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1921}/[H1921]', 'lemma', 'heb', 'הָדַר', '["hâdar"]', '["[is] adorned","they have been honored","you claim honor","you must show partiality","you will honor"]', '["v"]', 'to swell up (literally or figuratively, active or passive); by implication, to favor or honour, be high or proud countenance, crooked place, glorious, honour, put forth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7379}/H9023\/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["in/ case at law/ his"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6293}/[H6293]', 'lemma', 'heb', 'פָּגַע', '["pâgaʻ"]', '["I will cause to plead","I will meet","[was one who] interposed","fall","he fell","he has caused to touch","it touches","let them entreat","people will molest","they had made entreaty","they should fall","they should meet","we will entreat","you entreat","you meet","you will meet"]', '["v"]', 'to impinge, by accident or violence, or (figuratively) by importunity come (betwixt), cause to entreat, fall (upon), make intercession, intercessor, intreat, lay, light (upon), meet (together), pray, reach, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8130}/H9031/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["[one who] hates/ you","[those who] hate/ you","he should hate/ you"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4853A}/H9023/[H5375]', 'inflected', 'heb', 'מַשָּׂא', '["massâʼ"]', '["burden/ his","load/ its"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5800A}/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["from/ forsaking","from/ leaving"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800C}/[H5800]', 'lemma', 'heb', 'עָזַב', '["ʻâzab"]', '["I will let loose","[was] freed","certainly <to let loose>","you will let [it] loose"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/H9033\/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[was] with/ him","with/ him"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0034}/H9021/[H14]', 'inflected', 'heb', 'אֶבְיוֹן', '["ʼebyôwn"]', '["needy [person]/ your"]', '["a-m"]', 'destitute beggar, needy, poor (man).', 'from 14, in the sense of want (especially in feeling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7379}/H9023/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["in/ case at law/ his","in/ case/ his"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1697G}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["any of/ [the] word of","from/ [the] words of","from/ a word of","more than/ [the] word of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5355A}/[H5352]', 'inflected', 'heb', 'נָקִי', '["nâqîy"]', '["and/ [the] innocent","and/ an innocent [person]"]', '["a"]', 'innocent blameless, clean, clear, exempted, free, guiltless, innocent, quit.', 'or נָקִיא; (Joel 4:19; Jonah 1:14), from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6662}/[H6663]', 'inflected', 'heb', 'צַדִּיק', '["tsaddîyq"]', '["and/ [the] righteous","and/ a righteous [person]","and/ righteous","and/ righteous [people]"]', '["a"]', 'just just, lawful, righteous (man).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7810}/[H7809]', 'inflected', 'heb', 'שַׁחַד', '["shachad"]', '["and/ a bribe"]', '["n-m"]', 'a donation (venal or redemptive) bribe(-ry), gift, present, reward.', 'from 7809;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7810}/[H7809]', 'inflected', 'heb', 'שַׁחַד', '["shachad"]', '["<the>/ bribe","the/ bribe"]', '["n-m"]', 'a donation (venal or redemptive) bribe(-ry), gift, present, reward.', 'from 7809;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5786}/[H5785]', 'lemma', 'heb', 'עָוַר', '["ʻâvar"]', '["he made blind","it makes blind"]', '["v"]', 'to blind blind, put out. See also 5895.', 'a primitive root (rather denominatively from 5785 through the idea of a film over the eyes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5557}/[H5557]', 'inflected', 'heb', 'סָלַף', '["çâlaph"]', '["so/ it may pervert"]', '["v"]', 'properly, to wrench, i.e. (figuratively) to subvert overthrow, pervert.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315G}/[H5314]', 'lemma', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["<of> life","[the] appetite of","[the] life","[the] life of","[the] self of","[the] soul of","[the] throat of","a person","a throat","being","emotion","of [the] self of","people","person","persons","self","soul"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1616}/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["the/ sojourner","the/ sojourner[s]","the/ sojourners"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776G>/H9021', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["[is] land/ your","land/ your","own land/ your"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8393}/H9024/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["gain/ her","produce/ its","revenue/ her"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7637}/[H7657]', 'inflected', 'heb', 'שְׁבִיעִי', '["shᵉbîyʻîy"]', '["and/ the/ seventh [year]"]', '["a"]', 'seventh seventh (time).', 'or שְׁבִעִי; ordinal from 7657;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8058}/H9034/[H8058]', 'inflected', 'heb', 'שָׁמַט', '["shâmaṭ"]', '["let fall/ her","you will let rest/ it"]', '["v"]', 'to fling down; incipiently to jostle; figuratively, to let alone, desist, remit discontinue, overthrow, release, let rest, shake, stumble, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5203}/H9034/[H5203]', 'inflected', 'heb', 'נָטַשׁ', '["nâṭash"]', '["and/ you will leave fallow/ it"]', '["v"]', 'properly, to pound, i.e. smite; by implication (as if beating out, and thus expanding) to disperse; also, to thrust off, down, out or upon (inclusively, reject, let alone, permit, remit, etc.) cast off, drawn, let fall, forsake, join (battle), leave (off), lie still, loose, spread (self) abroad, stretch out, suffer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0034}/[H14]', 'lemma', 'heb', 'אֶבְיוֹן', '["ʼebyôwn"]', '["[the] needy","[the] needy [people] of","a needy [person]","needy [people]"]', '["a-m"]', 'destitute beggar, needy, poor (man).', 'from 14, in the sense of want (especially in feeling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3499A}/H9028/[H3498]', 'inflected', 'heb', 'יֶתֶר', '["yether"]', '["and/ abundance/ their","and/ excess/ their"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3754>/H9021', 'inflected', 'heb', 'לכרמך', '["le./khar.me./Kha"]', '["to/ vineyard/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2132H>/H9021', 'inflected', 'heb', 'לזיתך', '["le./zei.Te./kha"]', '["to/ olive grove/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639G}/H9021/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["work/ your","work<s>/ your","works/ your"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7794}/H9021/[H7788]', 'inflected', 'heb', 'שׁוֹר', '["shôwr"]', '["ox/ your","ox[en]/ your"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2543}/H9021/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["and/ donkey/ your"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5314}/[H5314]', 'inflected', 'heb', 'נָפַשׁ', '["nâphash"]', '["so/ he may refresh himself"]', '["v"]', 'to breathe; passively, to be breathed upon , i.e. (figuratively) refreshed (as if by a current of air) (be) refresh selves (-ed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1616}/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["and/ the/ sojourner","and/ the/ sojourner[s]","and/ the/ sojourners"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2287}/[H2283]', 'lemma', 'heb', 'חָגַג', '["châgag"]', '["celebrating a festival","they staggered","you will celebrate a festival","you will celebrate as a festival"]', '["v"]', 'properly, to move in a circle, i.e. (specifically) to march in a sacred procession, to observe a festival; by implication, to be giddy celebrate, dance, (keep, hold) a (solemn) feast (holiday), reel to and fro.', 'a primitive root (compare 2283, 2328);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2282}/[H2287]', 'inflected', 'heb', 'חַג', '["chag"]', '["and/ [the] festival of"]', '["n-m"]', 'a festival, or a victim therefor (solemn) feast (day), sacrifice, solemnity.', 'or חָג; from 2287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7105A}/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["the/ harvest"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1061}/[H1069]', 'lemma', 'heb', 'בִּכּוּר', '["bikkûwr"]', '["[the] first-fruits of","first-fruits"]', '["n-m"]', 'the first-fruits of the crop first fruit (-ripe (figuratively)), hasty fruit.', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0614}/[H622]', 'inflected', 'heb', 'אָסִיף', '["ʼâçîyph"]', '["the/ ingathering"]', '["n-m"]', 'gathered, i.e. (abstractly) a gathering in of crops ingathering.', 'or אָסִף; from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3318I}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ goes out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0622}/H9041/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["when/ gathering/ you"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2138}/H9021/[H2142]', 'inflected', 'heb', 'זָכוּר', '["zâkûwr"]', '["male/ your"]', '["n-m"]', 'a male (of man or animals) males, men-children.', 'properly, passive participle of 2142, but used for 2145;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0113>', 'inflected', 'heb', 'האדנים', '["ha./''a.Don","ha./''a.dOn","ha./''a.do.Nim"]', '["the/ lord","the/ lords"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2077}/H9020/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["sacrifice/ my"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2282}/H9020/[H2287]', 'inflected', 'heb', 'חַג', '["chag"]', '["festival sacrifice/ my"]', '["n-m"]', 'a festival, or a victim therefor (solemn) feast (day), sacrifice, solemnity.', 'or חָג; from 2287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7225H}/[H7218]', 'lemma', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["[the] beginning of","[the] choicest","[the] choicest of","[the] first of"]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0127G}/H9021/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["ground/ your","land/ your"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004Q}/[H1129]', 'lemma', 'heb', 'בַּיִת', '["bayith"]', '["[is the] house","[is] [the] house","[the] house of","[the] houses of","[were] [the] house of","a house","a house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2461}/[H2459]', 'inflected', 'heb', 'חָלָב', '["châlâb"]', '["in <the>/ milk","in/ [the] milk of"]', '["n-m"]', 'milk (as the richness of kine) cheese, milk, sucking.', 'from the same as 2459;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8104H}/H9031/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["to/ guard/ you","to/ keep/ you"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0935P}/H9031/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ to/ bring/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8085H}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ listen","and/ we may obey"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4843}/[H4752]', 'lemma', 'heb', 'מָרַר', '["mârar"]', '["I will show bitterness","[who] he has made bitter","he has caused bitterness","it is bitter","it was bitter","it will be bitter","you cause bitterness"]', '["v"]', 'to be (causatively, make) bitter (literally or figuratively) (be, be in, deal, have, make) bitter(-ly, -ness), be moved with choler, (be, have sorely, it) grieved(-eth), provoke, vex.', 'a primitive root; properly, to trickle (see 4752); but used only as a denominative from 4751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6588}/H9026/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["to/ transgression/ your"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0340}/[H340]', 'inflected', 'heb', 'אָיַב', '["ʼâyab"]', '["and/ I will be an enemy to"]', '["v"]', 'to hate (as one of an opposite tribe or party); hence to be hostile be an enemy.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6696B}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["and/ I will be a foe to"]', '["v"]', 'to cramp, i.e. confine (in many applications, literally and figuratively, formative or hostile) adversary, assault, beset, besiege, bind (up), cast, distress, fashion, fortify, inclose, lay siege, put up in bags.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6887D}/H9031/[H6887]', 'inflected', 'heb', 'צָרַר', '["tsârar"]', '["opposers/ your"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4397H>/H9020', 'opaque', 'heb', 'מַלְאָךְ', '["malʼâk"]', '["angel/ my"]', '["n-m"]', 'a messenger; specifically, of God, i.e. an angel (also a prophet, priest or teacher) ambassador, angel, king, messenger.', 'from an unused root meaning to despatch as a deputy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0935P}/H9031/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ I will bring/ you","and/ he will bring/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3582}/H9033/[H3582]', 'inflected', 'heb', 'כָּחַד', '["kâchad"]', '["and/ I will annihilate/ it"]', '["v"]', 'to secrete, by act or word; hence (intensively) to destroy conceal, cut down (off), desolate, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0430J}/H9028/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["for/ gods/ their","of/ gods/ their","to/ gods/ their"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4639G}/H9028/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["like/ works/ their"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2040}/H9038/[H2040]', 'inflected', 'heb', 'הָרַס', '["hâraç"]', '["he will tear down/ them","you will tear down/ them"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7665}/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["and/ breaking","and/ he has broken","and/ totally <shatter>","so/ it may be broken","so/ they may be broken"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4676}/H9028/[H5324]', 'inflected', 'heb', 'מַצֵּבָה', '["matstsêbâh"]', '["sacred pillars/ their"]', '["n-f"]', 'something stationed, i.e. a column or (memorial stone); by analogy, an idol garrison, (standing) image, pillar.', 'feminine (causatively) participle of 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899H}/H9021/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["bread/ your","food/ your"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4325G}/H9021/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["water/ your","waters/ your"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4245B}/[H2470]', 'lemma', 'heb', 'מַחֲלֶה', '["machăleh"]', '["sickness"]', '["n-m"]', 'sickness disease, infirmity, sickness.', 'or (feminine) מַחֲלָה; from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7130G}/H9021/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["from/ midst/ your"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6135}/[H6131]', 'inflected', 'heb', 'עָקָר', '["ʻâqâr"]', '["and/ a barren [female]","and/ barren"]', '["a"]', 'sterile (as if extirpated in the generative organs) (× male or female) barren (woman).', 'from 6131;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0776G>/H9021', 'inflected', 'heb', 'בארצך', '["be./''Ar.tze./kha","be./''ar.Tze./kha","be./''ar.tze./Kha","ve./''ar.Tze./kha","ve./''ar.tze./Kha"]', '["[is] in/ land/ your","in/ land/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0367}/H9020/[H366]', 'inflected', 'heb', 'אֵימָה', '["ʼêymâh"]', '["dread of/ me","terror/ my"]', '["n-f"]', 'fright; concrete, an idol (as a bugbear) dread, fear, horror, idol, terrible, terror.', 'or (shortened) אֵמָה; from the same as 366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6203}/[H6202]', 'lemma', 'heb', 'עֹרֶף', '["ʻôreph"]', '["[the] neck","a back","a neck","back","neck"]', '["n-m"]', 'the nape or back of the neck (as declining); hence, the back generally (whether literal or figurative) back ((stiff-) neck((-ed).', 'from 6202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6880}/[H6879]', 'inflected', 'heb', 'צִרְעָה', '["tsirʻâh"]', '["the/ hornet"]', '["n-f"]', 'a wasp (as stinging) hornet.', 'from 6879;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H6440G}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ to/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1644G}/H9033/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["I drove out/ it","I will drive out/ it"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8077A}/[H8076]', 'lemma', 'heb', 'שְׁמָמָה', '["shᵉmâmâh"]', '["[is] a desolation","a desolation","a waste","desolate","desolation","desolations of","wastes of"]', '["n-f"]', 'devastation; figuratively, astonishment (laid, × most) desolate(-ion), waste.', 'or שִׁמָמָה; feminine of 8076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7231}/[H7241]', 'inflected', 'heb', 'רָבַב', '["râbab"]', '["and/ it will become great","and/ it will become many","and/ they have been many","and/ they will be many"]', '["v"]', 'properly, to cast together , i.e. increase, especially in number; to multiply by the myriad increase, be many(-ifold), be more, multiply, ten thousands.', 'a primitive root; (compare 7241); also as denominative from 7233;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7704I>', 'inflected', 'heb', 'השדה', '["ha./sa.Deh"]', '["the/ field"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5157}/[H5157]', 'inflected', 'heb', 'נָחַל', '["nâchal"]', '["and/ I will give as an inheritance","and/ he will inherit","and/ they received their inheritance","and/ they will possess [it]","and/ you will divide as possession","and/ you will give [it] as inheritance","and/ you will give as an inheritance","and/ you will inherit","and/ you will possess"]', '["v"]', 'to inherit (as a (figurative) mode of descent), or (generally) to occupy; causatively, to bequeath, or (generally) distribute, instate divide, have (inheritance), take as a heritage, (cause to, give to, make to) inherit, (distribute for, divide (for, for an, by), give for, have, leave for, take (for)) inheritance, (have in, cause to, be made to) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366G}/H9021/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["border/ your","territory/ your"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6430I}/[H6429]', 'lemma', 'heb', 'פְּלִשְׁתִּי', '["Pᵉlishtîy"]', '["[the] Philistines"]', '["a"]', 'a Pelishtite or inhabitant of Pelesheth Philistine.', 'patrial from 6429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4057B}/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["and/ from/ [the] wilderness"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027H}/H9026/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["in/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0430J}/H9028/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ to/ gods/ their"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430J}/H9028/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["[are] gods/ their","gods/ their","own gods/ their"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4170}\/[H3369]', 'inflected', 'heb', 'מוֹקֵשׁ', '["môwqêsh"]', '["<into>/ a snare"]', '["n-m"]', 'a noose (for catching animals) (literally or figuratively); by implication, a hook (for the nose) be ensnared, gin, (is) snare(-d), trap.', 'or מֹקֵשׁ; from 3369;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0030}/[H1]', 'inflected', 'heb', 'אֲבִיהוּא', '["ʼĂbîyhûwʼ"]', '["and/ Abihu"]', '["n-pr-m"]', 'Abihu, a son of Aaron Abihu.', 'from 1 and 1931; father (i.e. worshipper) of Him (i.e. God);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3789}/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["and/ I will write","and/ I wrote","and/ he will write","and/ he wrote","and/ he wrote down","and/ it was written","and/ it was written down","and/ she wrote","and/ they inscribed","and/ you will write"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8002}/[H7999]', 'lemma', 'heb', 'שֶׁלֶם', '["shelem"]', '["[the] peace offerings of","peace offering<s>","peace offerings"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6499}/[H6565]', 'lemma', 'heb', 'פַּר', '["par"]', '["[the] bull of","[the] young bull of","a bull","a young bull","bulls","young bulls"]', '["n-m"]', 'a bullock (apparently as breaking forth in wild strength, or perhaps as dividing the hoof) ( young) bull(-ock), calf, ox.', 'or פָּר; from 6565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2677}/[H2673]', 'lemma', 'heb', 'חֵצִי', '["chêtsîy"]', '["<the> half of","[is] [the] half of","[the] half of","[the] middle of","half"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0101}/[H5059]', 'inflected', 'heb', 'אַגָּן', '["ʼaggân"]', '["in <the>/ bowls"]', '["n-m"]', 'a bowl (as pounded out hollow) basin, cup, goblet.', 'probably from 5059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2677}/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["and/ [the] half of","and/ [the] middle of","and/ a half"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2236}/[H2236]', 'lemma', 'heb', 'זָרַק', '["zâraq"]', '["[were] sprinkling","does he sprinkle?","he sprinkled","he will sprinkle","it has been sprinkled","it has sneaked in","it was sprinkled","you will sprinkle"]', '["v"]', 'to sprinkle (fluid or solid particles) be here and there, scatter, sprinkle, strew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7121J}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ he read [it] aloud","and/ he read aloud","and/ he will read","and/ they read aloud","and/ you will read aloud"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8478G}/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["and/ [was] under","and/ under"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4639G}/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["[was] like/ [the] work of","according to/ [the] work of","like the/ workmanship","like/ [the] work of","like/ [the] working of"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5601}/[H5608]', 'inflected', 'heb', 'סַפִּיר', '["çappîyr"]', '["<the>/ sapphire"]', '["n-m"]', 'a gem (perhaps used for scratching other substances), probably the sapphire sapphire.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6106H}/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["and/ like/ [the] substance of"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2892A}/[H2891]', 'inflected', 'heb', 'טֹהַר', '["ṭôhar"]', '["to/ purity"]', '["n-m"]', 'literally brightness; ceremonially purification clearness, glory, purifying.', 'from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0678}/[H680]', 'lemma', 'heb', 'אָצִיל', '["ʼâtsîyl"]', '["[the] nobles of"]', '["n-m"]', 'an extremity (Isaiah 41:9), also a noble chief man, noble.', 'from 680 (in its secondary sense of separation);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2372}/[H2372]', 'inflected', 'heb', 'חָזָה', '["châzâh"]', '["and/ I saw","and/ they have seen","and/ they saw","and/ you have seen"]', '["v"]', 'to gaze at; mentally to perceive, contemplate (with pleasure); specifically, to have a vision of behold, look, prophesy, provide, see.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8354}\/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["and/ they drank"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3871}/[H3871]', 'lemma', 'heb', 'לוּחַ', '["lûwach"]', '["[the] tablet of","[the] tablets of","a board of","a tablet","boards","planks","tablets","tablets of"]', '["n-m"]', 'probably meaning to glisten; a tablet (as polished), of stone, wood or metal board, plate, table.', 'or לֻחַ; from a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8451}/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["and/ the/ law","and/ the/ legal [procedures]"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4687}/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["and/ the/ commandment"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3384B}/H9038/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["to/ teach/ them"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3091G}/[H3068]', 'inflected', 'heb', 'יְהוֹשׁוּעַ', '["Yᵉhôwshûwaʻ"]', '["and/ Joshua"]', '["n-pr-m"]', 'Jehoshua (i.e. Joshua), the Jewish leader Jehoshua, Jehoshuah, Joshua. Compare 1954, 3442.', 'or יְהוֹשֻׁעַ; from 3068 and 3467; Jehovah-saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8334}/H9033/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["[who were] serving/ him","[who] served/ him","servant/ his","servants/ his","they will serve/ it"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2205G}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["<the>/ old","the/ elders","the/ old [men]"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3680}/H9033/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["and/ he will cover/ it","and/ it covered/ it","and/ she covered/ him","and/ they covered/ him","and/ you will cover/ him"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4758}/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["and/ [the] appearance of","and/ [the] vision of","and/ a vision"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0784}/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["[is] like/ [the] fire of","[is] like/ a fire","[was] like/ a fire","like <the>/ fire","like/ a fire","like/ a fire of"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7218I>', 'inflected', 'heb', 'בראשי', '["be./Rosh","be./ra.Shei","be./rosh"]', '["<in>/ [the] chief of","<in>/ [the] top of","at/ [the] beginning of","at/ [the] head of","at/ [the] top of","for/ [the] best of","in/ [the] tops of","on/ [the] top of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3915}\/[H3883]', 'inflected', 'heb', 'לַיִל', '["layil"]', '["night[s]","nights"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8641}/[H7311]', 'lemma', 'heb', 'תְּרוּמָה', '["tᵉrûwmâh"]', '["<the> contribution of","[is] a contribution","[the] contribution of","[the] contributions of","a contribution","a contribution of","contribution","contribution of","contributions"]', '["n-f"]', 'a present (as offered up), especially in sacrifice or as tribute gift, heave offering (shoulder), oblation, offered(-ing).', 'or תְּרֻמָה; (Deuteronomy 12:11), from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5068}/H9033/[H5068]', 'inflected', 'heb', 'נָדַב', '["nâdab"]', '["it will impel/ him"]', '["v"]', 'to impel; hence, to volunteer (as a soldier), to present spontaneously offer freely, be (give, make, offer self) willing(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8641}/H9020/[H7311]', 'inflected', 'heb', 'תְּרוּמָה', '["tᵉrûwmâh"]', '["contribution/ my","contributions/ my"]', '["n-f"]', 'a present (as offered up), especially in sacrifice or as tribute gift, heave offering (shoulder), oblation, offered(-ing).', 'or תְּרֻמָה; (Deuteronomy 12:11), from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8641}/[H7311]', 'inflected', 'heb', 'תְּרוּמָה', '["tᵉrûwmâh"]', '["[is] the/ contribution","[will be] the/ contribution","the/ contribution"]', '["n-f"]', 'a present (as offered up), especially in sacrifice or as tribute gift, heave offering (shoulder), oblation, offered(-ing).', 'or תְּרֻמָה; (Deuteronomy 12:11), from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5178A}/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["and/ [the] bronze of","and/ bronze","and/ copper"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8504}/[H7827]', 'inflected', 'heb', 'תְּכֵלֶת', '["tᵉkêleth"]', '["and/ violet","and/ violet material","and/ violet stuff"]', '["n-f"]', 'the cerulean mussel, i.e. the color (violet) obtained therefrom or stuff dyed therewith blue.', 'probably for 7827;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0713>', 'inflected', 'heb', 'וארגמן', '["ve./''ar.ga.Man"]', '["and/ purple"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8438A}/[H3216]', 'inflected', 'heb', 'תּוֹלָע', '["tôwlâʻ"]', '["and/ scarlet stuff of"]', '["n-m n-f"]', 'a maggot (as voracious); specifically (often with ellipsis of 8144) the crimson-grub, but used only (in this connection) of the color from it, and cloths dyed therewith crimson, scarlet, worm.', 'and (feminine) תּוֹלֵעָה; or תּוֹלַעַת; or תֹּלַעַת; from 3216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8336B}/[H4897]', 'inflected', 'heb', 'שֵׁשׁ', '["shêsh"]', '["and/ fine linen"]', '["n-m"]', 'bleached stuff, i.e. white linen or (by analogy) marble × blue, fine (twined) linen, marble, silk.', 'or (for alliteration with 4897) שְׁשִׁי; for 7893;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5785}/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["and/ hides of"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0119}/[H119]', 'lemma', 'heb', 'אָדַם', '["ʼâdam"]', '["dyed red","it will be red","they are red","they were red"]', '["v"]', 'to show blood (in the face), i.e. flush or turn rosy be (dyed, made) red (ruddy).', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8476}/[H8476]', 'lemma', 'heb', 'תַּחַשׁ', '["tachash"]', '["dolphin","dolphins","leather"]', '["n-m"]', 'a (clean) animal with fur, probably a species of antelope badger.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6086G}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["and/ [the] wood of","and/ wood of","and/ wood<s>","and/ wood<s> of"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7848}/[H7850]', 'lemma', 'heb', 'שִׁטָּה', '["shiṭṭâh"]', '["acacia","acacia tree[s]"]', '["n-f"]', 'the acacia (from its scourging thorns) shittah, shittim. See also 1029.', 'feminine of a derivative (only in the plural שִׁטִּים; meaning the sticks of wood) from the same as 7850;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1314}/[H1313]', 'lemma', 'heb', 'בֶּשֶׂם', '["besem"]', '["perfume","spice","spices"]', '["n-m"]', 'fragrance; by implication, spicery; also the balsam plant smell, spice, sweet (odour).', 'or בֹּשֶׂם; from the same as 1313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8081}/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["for/ [the] oil of"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4888A}/[H4886]', 'inflected', 'heb', 'מִשְׁחָה', '["mishchâh"]', '["<the>/ anointing","the/ anointing"]', '["n-f"]', 'unction (the act); by implication, a consecratory gift (to be) anointed(-ing), ointment.', 'or מׇשְׁחָה; from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7004}/[H6999]', 'inflected', 'heb', 'קְטֹרֶת', '["qᵉṭôreth"]', '["and/ for/ [the] incense of"]', '["n-f"]', 'a fumigation (sweet) incense, perfume.', 'from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5561>', 'inflected', 'heb', 'הסמים', '["ha./sa.Mim"]', '["the/ perfume<s>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7718>', 'opaque', 'heb', 'שֹׁהַם', '["shôham"]', '["an onyx","onyx"]', '["n-m"]', 'a gem, probably the beryl (from its pale green color) onyx.', 'from an unused root probably mean to blanch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4394}/[H4390]', 'lemma', 'heb', 'מִלֻּא', '["milluʼ"]', '["[were] installation offerings","installation offering<s>","setting<s>"]', '["n-m"]', 'a fulfilling (only in plural), i.e. (literally) a setting (of gems), or (technically) consecration (also concretely, a dedicatory sacrifice) consecration, be set.', 'from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0646}/[H646]', 'inflected', 'heb', 'אֵפוֹד', '["ʼêphôwd"]', '["for the/ ephod","into/ an ephod"]', '["n-m"]', 'a girdle; specifically the ephod or highpriest''s shoulder-piece; also generally, an image ephod.', 'rarely אֵפֹד; probably of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H2833>', 'inflected', 'heb', 'ולחשן', '["ve./la./Cho.shen"]', '["and/ for the/ breastpiece"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8432>/H9028', 'inflected', 'heb', 'בתוכם', '["be./to.Kha/m","ve./to.Kha/m"]', '["[are] in/ midst of/ them","[is] among/ midst of/ them","[is] in/ midst of/ them","[was] in/ midst of/ them","[were] in/ midst of/ them","[will be] in/ between/ them","[will be] in/ midst of/ them","in/ midst of/ them","in/ midst/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8403}/[H1129]', 'lemma', 'heb', 'תַּבְנִית', '["tabnîyth"]', '["[the] copy of","[the] form of","[the] pattern of","[the] structure of","a likeness of","form of"]', '["n-f"]', 'structure; by implication, a model, resemblance figure, form, likeness, pattern, similitude.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4908}/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["[was] the/ tabernacle","the/ tabernacle"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3627}/H9023/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["<of> armor<s>/ his","armor/ his","armor<s>/ his","articles/ its","baggage<s>/ his","utensils/ its","weapons/ his"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213H}\/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["they have done","they will do","you will make [it]"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0727}/[H717]', 'lemma', 'heb', 'אָרוֹן', '["ʼârôwn"]', '["<of> [the] ark of","[the] ark of","a chest","an ark of"]', '["n-m"]', 'a box ark, chest, coffin.', 'or אָרֹן; from 717 (in the sense of gathering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0753}/H9023/[H748]', 'inflected', 'heb', 'אֹרֶךְ', '["ʼôrek"]', '["length/ its"]', '["n-m"]', 'length forever, length, long.', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0520A}/[H517]', 'inflected', 'heb', 'אַמָּה', '["ʼammâh"]', '["and/ [is] a cubit","and/ [was] a cubit","and/ [was] cubits","and/ [was] two cubits","and/ [will be] a cubit","and/ [will be] two cubits"]', '["n-f"]', 'properly, a mother (i.e. unit of measure, or the fore-arm (below the elbow), i.e. a cubit; also a door-base (as a bond of the entrance) cubit, + hundred (by exchange for 3967), measure, post.', 'prolonged from 517;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7341}/H9023/[H7337]', 'inflected', 'heb', 'רֹחַב', '["rôchab"]', '["breadth/ its"]', '["n-m"]', 'width (literally or figuratively) breadth, broad, largeness, thickness, wideness.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6967}/H9023/[H6965]', 'inflected', 'heb', 'קוֹמָה', '["qôwmâh"]', '["height/ its","stature/ his","stature/ its"]', '["n-f"]', 'height × along, height, high, stature, tall.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6823}/[H6822]', 'inflected', 'heb', 'צָפָה', '["tsâphâh"]', '["and/ he overlaid","and/ he overlaid [them]","and/ they overlaid","and/ you will overlay"]', '["v"]', 'to sheet over (especially with metal) cover, overlay.', 'a primitive root (probably identical with 6822 through the idea of expansion in outlook, transferring to action);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6823}/H9033/[H6822]', 'inflected', 'heb', 'צָפָה', '["tsâphâh"]', '["you will overlay/ it"]', '["v"]', 'to sheet over (especially with metal) cover, overlay.', 'a primitive root (probably identical with 6822 through the idea of expansion in outlook, transferring to action);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2213}/[H2237]', 'lemma', 'heb', 'זֵר', '["zêr"]', '["a molding","a molding of"]', '["n-m"]', 'a chaplet (as spread around the top), i.e. (specifically) a border moulding crown.', 'from 2237 (in the sense of scattering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3332H}/[H3332]', 'inflected', 'heb', 'יָצַק', '["yâtsaq"]', '["and/ he cast","and/ you will cast"]', '["v"]', 'properly, to pour out (transitive or intransitive); by implication, to melt or cast as metal; by extension, to place firmly, to stiffen or grow hard cast, cleave fast, be (as) firm, grow, be hard, lay out, molten, overflow, pour (out), run out, set down, stedfast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2885}/[H2883]', 'lemma', 'heb', 'טַבַּעַת', '["ṭabbaʻath"]', '["[the] rings of","a signet-ring","rings","rings of"]', '["n-m"]', 'properly, a seal (as sunk into the wax), i.e. signet (for sealing); hence (generally) a ring of any kind ring.', 'from 2883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6471}/H9023/[H6470]', 'inflected', 'heb', 'פַּעַם', '["paʻam"]', '["feet/ his","feet/ its","footsteps/ his"]', '["n-f"]', 'a stroke, literally or figuratively (in various applications, as follow) anvil, corner, foot(-step), going, (hundred-) fold, × now, (this) once, order, rank, step, thrice, (often-), second, this, two) time(-s), twice, wheel.', 'or (feminine) פַּעֲמָה; from 6470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6763}/H9023/[H6760]', 'inflected', 'heb', 'צֵלָע', '["tsêlâʻ"]', '["side/ its","sides/ its"]', '["n-f"]', 'a rib (as curved), literally (of the body) or figuratively (of a door, i.e. leaf); hence, a side, literally (of a person) or figuratively (of an object or the sky, i.e. quarter); architecturally, a (especially floor or ceiling) timber or plank (single or collective, i.e. a flooring) beam, board, chamber, corner, leaf, plank, rib, side (chamber).', 'or (feminine) צַלְעָה; from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0905G}/[H909]', 'lemma', 'heb', 'בַּד', '["bad"]', '["[the] parts of","[the] poles of","poles","poles of","shoots"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0905G}/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["the/ poles"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2885}/[H2883]', 'inflected', 'heb', 'טַבַּעַת', '["ṭabbaʻath"]', '["in the/ rings","in/ [the] rings of","with/ [the] signet-ring of"]', '["n-m"]', 'properly, a seal (as sunk into the wax), i.e. signet (for sealing); hence (generally) a ring of any kind ring.', 'from 2883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6763}/[H6760]', 'lemma', 'heb', 'צֵלָע', '["tsêlâʻ"]', '["[the] side of","[the] side-chambers","[the] sides of","side-chamber","side-chambers","sides"]', '["n-f"]', 'a rib (as curved), literally (of the body) or figuratively (of a door, i.e. leaf); hence, a side, literally (of a person) or figuratively (of an object or the sky, i.e. quarter); architecturally, a (especially floor or ceiling) timber or plank (single or collective, i.e. a flooring) beam, board, chamber, corner, leaf, plank, rib, side (chamber).', 'or (feminine) צַלְעָה; from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0727}/[H717]', 'inflected', 'heb', 'אָרוֹן', '["ʼârôwn"]', '["[was] the/ ark","the/ ark","the/ chest"]', '["n-m"]', 'a box ark, chest, coffin.', 'or אָרֹן; from 717 (in the sense of gathering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3727}/[H3722]', 'lemma', 'heb', 'כַּפֹּרֶת', '["kappôreth"]', '["an atonement cover","an atonement cover of"]', '["n-f"]', 'a lid (used only of the cover of the sacred Ark) mercy seat.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0753}/H9024/[H748]', 'inflected', 'heb', 'אֹרֶךְ', '["ʼôrek"]', '["[is] length/ its","length/ its"]', '["n-m"]', 'length forever, length, long.', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3742>', 'opaque', 'heb', 'כְּרוּב', '["kᵉrûwb"]', '["O cherub","[were] a cherub of","[were] cherubim","a cherub","cherubim"]', '["n-m"]', 'a cherub or imaginary figure cherub, (plural) cherubims.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4749}/[H4748]', 'lemma', 'heb', 'מִקְשָׁה', '["miqshâh"]', '["[was] hammered work","[will be] hammered work","hammered work"]', '["n-f"]', 'rounded work, i.e. moulded by hammering (repoussé) beaten (out of one piece, work), upright, whole piece.', 'feminine of 4748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8147}/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["from/ [the] two","from/ both","more than/ two [plus]"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7098}/[H7097]', 'lemma', 'heb', 'קָצָה', '["qâtsâh"]', '["[are] [the] ends of","[the] ends of"]', '["n"]', 'a termination coast, corner, (selv-) edge, lowest, (uttermost) participle', 'feminine of 7097; (used like 7097)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3727}/[H3722]', 'inflected', 'heb', 'כַּפֹּרֶת', '["kappôreth"]', '["the/ atonement cover"]', '["n-f"]', 'a lid (used only of the cover of the sacred Ark) mercy seat.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7098}/[H7097]', 'inflected', 'heb', 'קָצָה', '["qâtsâh"]', '["[was] from/ an end","from/ [the] ends of","from/ an end"]', '["n"]', 'a termination coast, corner, (selv-) edge, lowest, (uttermost) participle', 'feminine of 7097; (used like 7097)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3742>', 'inflected', 'heb', 'וכרובים', '["u./khe.ru.Vim","u./khe.ruv"]', '["and/ a cherub","and/ cherubim"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7098}/H9023/[H7097]', 'inflected', 'heb', 'קָצָה', '["qâtsâh"]', '["ends/ its","extremities/ its"]', '["n"]', 'a termination coast, corner, (selv-) edge, lowest, (uttermost) participle', 'feminine of 7097; (used like 7097)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4605}/H9011/[H5927]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["<to>/ upwards/ <towards>","[is] <to>/ upwards/ <towards>","[were] <to>/ upwards/ <towards>"]', '["adv"]', 'properly,the upper part, used only adverbially with prefix upward, above, overhead, from the top, etc. above, exceeding(-ly), forward, on (× very) high, over, up(-on, -ward), very.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5526B}/[H5526]', 'lemma', 'heb', 'סָכַךְ', '["çâkak"]', '["[is] covering","covering","he provoked","he will cover","you cover","you have covered","you have covered yourself"]', '["v"]', 'properly, to entwine as a screen; by implication, to fence in, cover over, (figuratively) protect cover, defence, defend, hedge in, join together, set, shut up.', 'or שָׂכַךְ; (Exodus 33:22), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3671}/H9028/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["[was] in/ wings/ their","with/ wings/ their"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3259}/[H3259]', 'inflected', 'heb', 'יָעַד', '["yâʻad"]', '["and/ I will meet","and/ they gathered","and/ they met by appointment","and/ they will gather together"]', '["v"]', 'to fix upon (by agreement or appointment); by implication, to meet (at a stated time), to summon (to trial), to direct (in a certain quarter or position), to engage (for marriage) agree,(maxke an) appoint(-ment, a time), assemble (selves), betroth, gather (selves, together), meet (together), set (a time).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7979}/[H7971]', 'lemma', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["[the] table of","[the] tables","a table","tables"]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4526}/[H5462]', 'lemma', 'heb', 'מִסְגֶּרֶת', '["miçgereth"]', '["a rim of","rims"]', '["n-f"]', 'something enclosing, i.e. a margin (of a region, of a panel); concretely, a stronghold border, close place, hole.', 'from 5462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2948}/[H2946]', 'lemma', 'heb', 'טֹפַח', '["ṭôphach"]', '["a hand breadth"]', '["n-m"]', '(the same as 2947) hand-breadth (broad).', 'from 2946');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4526}/H9023/[H5462]', 'inflected', 'heb', 'מִסְגֶּרֶת', '["miçgereth"]', '["for/ rim/ its"]', '["n-f"]', 'something enclosing, i.e. a margin (of a region, of a panel); concretely, a stronghold border, close place, hole.', 'from 5462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2885}/[H2883]', 'inflected', 'heb', 'טַבַּעַת', '["ṭabbaʻath"]', '["the/ ring","the/ rings","the/ signet-rings"]', '["n-m"]', 'properly, a seal (as sunk into the wax), i.e. signet (for sealing); hence (generally) a ring of any kind ring.', 'from 2883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6285}/[H6311]', 'inflected', 'heb', 'פֵּאָה', '["pêʼâh"]', '["the/ corners"]', '["n-f"]', 'properly, mouth in a figurative sense, i.e. direction, region, extremity corner, end, quarter, side.', 'feminine of 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5980}/[H6004]', 'inflected', 'heb', 'עֻמָּה', '["ʻummâh"]', '["<to>/ close to","<to>/ corresponding to","<to>/ correspondingly","<to>/ exactly as","along/ side"]', '["n-f"]', 'conjunction, i.e. society; mostly adverb or preposition (with prepositional prefix), near, beside, along with (over) against, at, beside, hard by, in points.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4526}/[H5462]', 'inflected', 'heb', 'מִסְגֶּרֶת', '["miçgereth"]', '["the/ rim","the/ rims","the/ rims of"]', '["n-f"]', 'something enclosing, i.e. a margin (of a region, of a panel); concretely, a stronghold border, close place, hole.', 'from 5462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004N}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["<into>/ holders","for/ holders"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0905G}/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["for the/ poles","for/ poles"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7979}/[H7971]', 'inflected', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["[is] the/ table","the/ table","the/ tables"]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7086}/H9023/[H7167]', 'inflected', 'heb', 'קְעָרָה', '["qᵉʻârâh"]', '["dishes/ its"]', '["n-f"]', 'a bowl (as cut out hollow) charger, dish.', 'probably from 7167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3709I}/H9023/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["and/ pans/ its"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7184>/H9023', 'inflected', 'heb', 'וקשותיו', '["u./ke.so.Ta/v"]', '["and/ jugs/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4518}/H9023/[H5352]', 'inflected', 'heb', 'מְנַקִּית', '["mᵉnaqqîyth"]', '["and/ bowls/ its"]', '["n-f"]', 'a sacrificial basin (for holding blood) bowl.', 'from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5258A}/[H5258]', 'lemma', 'heb', 'נָסַךְ', '["nâçak"]', '["I will pour out","has he cast?","he has cast","he has poured out","it was poured out","it will be poured out","pour out","they will pour out","you must pour out"]', '["v"]', 'to pour out, especially a libation, or to cast (metal); by analogy, to anoint a king cover, melt, offer, (cause to) pour (out), set (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8548>\', 'opaque', 'heb', 'תָּמִיד', '["tâmîyd"]', '["continually","continuity"]', '["n-m"]', 'properly, continuance (as indefinite extension); but used only (attributively as adjective) constant (or adverbially, constantly); elliptically the regular (daily) sacrifice alway(-s), continual (employment, -ly), daily, (n-)ever(-more), perpetual.', 'from an unused root meaning to stretch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4501}/[H4500]', 'lemma', 'heb', 'מְנוֹרָה', '["mᵉnôwrâh"]', '["[the] lampstand of","[the] lampstands of","a lampstand","a lampstand of","lampstand"]', '["n-f"]', 'a chandelier candlestick.', 'or מְנֹרָה; feminine of 4500 (in the original sense of 5216);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4501}/[H4500]', 'inflected', 'heb', 'מְנוֹרָה', '["mᵉnôwrâh"]', '["the/ lampstand","the/ lampstands"]', '["n-f"]', 'a chandelier candlestick.', 'or מְנֹרָה; feminine of 4500 (in the original sense of 5216);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3409>/H9024', 'opaque', 'heb', 'יָרֵךְ', '["yârêk"]', '["base/ its","thigh/ her"]', '["n-f"]', 'the thigh (from its fleshy softness); by euphemistically the generative parts; figuratively, a shank, flank, side × body, loins, shaft, side, thigh.', 'from an unused root meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7070H}/H9024/[H7069]', 'inflected', 'heb', 'קָנֶה', '["qâneh"]', '["and/ shaft/ its"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1375>/H9024', 'opaque', 'heb', 'גְּבִיעַ', '["gᵉbîyaʻ"]', '["cups/ its"]', '["n-m"]', 'a goblet; by analogy, the calyx of a flower house, cup, pot.', 'from an unused root (meaning to be convex);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3730>/H9024', 'opaque', 'heb', 'כַּפְתֹּר', '["kaphtôr"]', '["bulbs/ its"]', '["n-m"]', 'a chaplet; but used only in an architectonic sense, i.e. the capital of a column, or a wreath-like button or disk on the candelabrum knop, (upper) lintel.', 'or (Amos 9:1) כַּפְתּוֹר; probably from an unused root meaning to encircle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6525}/H9024/[H6524]', 'inflected', 'heb', 'פֶּרַח', '["perach"]', '["and/ blossoms/ its"]', '["n-m"]', 'a calyx (natural or artificial); generally, bloom blossom, bud, flower.', 'from 6524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7070G}/[H7069]', 'lemma', 'heb', 'קָנֶה', '["qâneh"]', '["branches","branches of"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6654>/H9024', 'inflected', 'heb', 'מצדיה', '["mi./tzi.Da/h","mi./tzi.Dei./ha"]', '["[were] from/ side/ its","[will be] from/ side/ its","from/ sides/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8246}/[H8247]', 'lemma', 'heb', 'שָׁקַד', '["shâqad"]', '["shaped like almond blossoms"]', '["v"]', 'to be (intensively, make) almond-shaped make like (unto, after the fashion of) almonds.', 'a denominative from 8247;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7070G}/[H7069]', 'inflected', 'heb', 'קָנֶה', '["qâneh"]', '["[were] on the/ branch","[were] on/ a branch","[will be] on the/ branch"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3730>', 'opaque', 'heb', 'כַּפְתֹּר', '["kaphtôr"]', '["a bulb"]', '["n-m"]', 'a chaplet; but used only in an architectonic sense, i.e. the capital of a column, or a wreath-like button or disk on the candelabrum knop, (upper) lintel.', 'or (Amos 9:1) כַּפְתּוֹר; probably from an unused root meaning to encircle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6525}/[H6524]', 'inflected', 'heb', 'פֶּרַח', '["perach"]', '["and/ a blossom"]', '["n-m"]', 'a calyx (natural or artificial); generally, bloom blossom, bud, flower.', 'from 6524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8337}/[H7797]', 'inflected', 'heb', 'שֵׁשׁ', '["shêsh"]', '["for/ [the] six","for/ six-","to/ six"]', '["n"]', 'six (as an overplus beyond five or the fingers of the hand); as ordinal sixth six(-teen, -teenth), sixth.', 'masculine שִׁשָּׁה; a primitive number; see 7797');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7070G}/[H7069]', 'inflected', 'heb', 'קָנֶה', '["qâneh"]', '["the/ branches"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3318L}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["<the>/ projecting","those/ [which] were brought out","which/ came out","which/ come out","which/ projects","who/ brought forth"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4501}/[H4500]', 'inflected', 'heb', 'מְנוֹרָה', '["mᵉnôwrâh"]', '["and/ [were] on the/ lampstand","and/ [will be] on the/ lampstand"]', '["n-f"]', 'a chandelier candlestick.', 'or מְנֹרָה; feminine of 4500 (in the original sense of 5216);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3730>', 'inflected', 'heb', 'וכפתר', '["ve./khaf.Tor"]', '["and/ a bulb"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3730>/H9028', 'opaque', 'heb', 'כַּפְתֹּר', '["kaphtôr"]', '["bulbs/ their"]', '["n-m"]', 'a chaplet; but used only in an architectonic sense, i.e. the capital of a column, or a wreath-like button or disk on the candelabrum knop, (upper) lintel.', 'or (Amos 9:1) כַּפְתּוֹר; probably from an unused root meaning to encircle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7070G}/H9028/[H7069]', 'inflected', 'heb', 'קָנֶה', '["qâneh"]', '["and/ branches/ their"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5216A}/H9024/[H5214]', 'inflected', 'heb', 'נִיר', '["nîyr"]', '["lamp/ her","lamps/ its"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5676H}/[H5674]', 'lemma', 'heb', 'עֵבֶר', '["ʻêber"]', '["[the] other side of","[the] side of"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440G}/H9024/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ its"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4457}/H9024/[H3947]', 'inflected', 'heb', 'מֶלְקָח', '["melqâch"]', '["and/ tongs/ its"]', '["n-m"]', '(only in dual) tweezers snuffers, tongs.', 'or מַלְקָח; from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4289}/H9024/[H4288]', 'inflected', 'heb', 'מַחְתָּה', '["machtâh"]', '["and/ fire-pans/ its"]', '["n-f"]', 'a pan for live coals censer, firepan, snuffdish.', 'the same as 4288 in the sense of removal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3627}/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["<the>/ article","the/ article","the/ articles","the/ bag","the/ baggage<s>","the/ equipment<s>","the/ utensils","the/ vessel","the/ vessels"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8403}/H9028/[H1129]', 'inflected', 'heb', 'תַּבְנִית', '["tabnîyth"]', '["in/ pattern/ their"]', '["n-f"]', 'structure; by implication, a model, resemblance figure, form, likeness, pattern, similitude.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2022G}\/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["on the/ mountain"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3407}/[H3415]', 'lemma', 'heb', 'יְרִיעָה', '["yᵉrîyʻâh"]', '["[the] curtains of","[the] tent curtains of","curtains","curtains of","tent curtains"]', '["n-f"]', 'a hanging (as tremulous) curtain.', 'from 3415;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7806}/[H7806]', 'lemma', 'heb', 'שָׁזַר', '["shâzar"]', '["twisted"]', '["v"]', 'to twist (a thread of straw) twine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8438B}/[H3216]', 'inflected', 'heb', 'תּוֹלָע', '["tôwlâʻ"]', '["and/ [the] scarlet stuff of","and/ scarlet stuff of"]', '["n-m n-f"]', 'a maggot (as voracious); specifically (often with ellipsis of 8144) the crimson-grub, but used only (in this connection) of the color from it, and cloths dyed therewith crimson, scarlet, worm.', 'and (feminine) תּוֹלֵעָה; or תּוֹלַעַת; or תֹּלַעַת; from 3216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2803G}/[H2803]', 'lemma', 'heb', 'חָשַׁב', '["châshab"]', '["a skillful worker","an inventor","he had planned","they have devised"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3407}/[H3415]', 'inflected', 'heb', 'יְרִיעָה', '["yᵉrîyʻâh"]', '["the/ curtain","the/ curtains","the/ tent curtain"]', '["n-f"]', 'a hanging (as tremulous) curtain.', 'from 3415;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0520A}/[H517]', 'inflected', 'heb', 'אַמָּה', '["ʼammâh"]', '["by <the>/ cubits","by the/ cubit","by/ a cubit of"]', '["n-f"]', 'properly, a mother (i.e. unit of measure, or the fore-arm (below the elbow), i.e. a cubit; also a door-base (as a bond of the entrance) cubit, + hundred (by exchange for 3967), measure, post.', 'prolonged from 517;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7341}/[H7337]', 'inflected', 'heb', 'רֹחַב', '["rôchab"]', '["and/ [the] breadth","and/ [the] breadth of","and/ a breadth","and/ breadth of"]', '["n-m"]', 'width (literally or figuratively) breadth, broad, largeness, thickness, wideness.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4060A}/[H4055]', 'lemma', 'heb', 'מִדָּה', '["middâh"]', '["[are] [the] measurements of","[the] measurement","[the] measurements of","a measured portion","a measurement","measurement","measurements","size","size<s>","stature","stature<s>"]', '["n-f"]', 'properly, extension, i.e. height or breadth; also a measure (including its standard); hence a portion (as measured) or a vestment; specifically, tribute (as measured) garment, measure(-ing, meteyard, piece, size, (great) stature, tribute, wide.', 'feminine of 4055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0802I}/[H376]', 'lemma', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["[each] woman","each"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0269}/H9024/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["[is] sister/ her","sister/ her","sister/ its"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3924}/[H3883]', 'lemma', 'heb', 'לֻלָאָה', '["lulâʼâh"]', '["loops","loops of"]', '["n-f"]', 'a loop loop.', 'from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8504}/[H7827]', 'lemma', 'heb', 'תְּכֵלֶת', '["tᵉkêleth"]', '["[is] violet stuff","blue","violet","violet stuff"]', '["n-f"]', 'the cerulean mussel, i.e. the color (violet) obtained therefrom or stuff dyed therewith blue.', 'probably for 7827;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193I}/[H5595]', 'lemma', 'heb', 'שָׂפָה', '["sâphâh"]', '["[the] border of","[the] edge of","[the] lip of","an edge"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2279}/[H2266]', 'inflected', 'heb', 'חֹבֶרֶת', '["chôbereth"]', '["in the/ joined set"]', '["n-f"]', 'a joint which coupleth, coupling.', 'feminine active participle of 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8193I}/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["on/ [the] edge of"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7020}/[H6972]', 'inflected', 'heb', 'קִיצוֹן', '["qîytsôwn"]', '["<the>/ outermost"]', '["a"]', 'terminal out-(utter-) most.', 'from 6972;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4225}/[H2266]', 'inflected', 'heb', 'מַחְבֶּרֶת', '["machbereth"]', '["[is] in the/ joined set","[was] in the/ joined set","in the/ joined set"]', '["n-f"]', 'a junction, i.e. seam or sewed piece coupling.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3407}/[H3415]', 'inflected', 'heb', 'יְרִיעָה', '["yᵉrîyʻâh"]', '["in/ [the] curtains of","on the/ curtain"]', '["n-f"]', 'a hanging (as tremulous) curtain.', 'from 3415;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6901}/[H6901]', 'lemma', 'heb', 'קָבַל', '["qâbal"]', '["[were] opposite","[will be] opposite","he accepted [them]","take","will we accept?"]', '["v"]', 'to admit, i.e. take (literally or figuratively) choose, (take) hold, receive, (under-) take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3924}/[H3883]', 'inflected', 'heb', 'לֻלָאָה', '["lulâʼâh"]', '["the/ loops"]', '["n-f"]', 'a loop loop.', 'from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7165}/[H7164]', 'lemma', 'heb', 'קֶרֶס', '["qereç"]', '["hooks of"]', '["n-m"]', 'a knob or belaying-pin (from its swelling form) tache.', 'from 7164;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2266}/[H2266]', 'inflected', 'heb', 'חָבַר', '["châbar"]', '["and/ he joined","and/ it will be joined together","and/ you will join"]', '["v"]', 'to join (literally or figuratively); specifically (by means of spells) to fascinate charm(-er), be compact, couple (together), have fellowship with, heap up, join (self, together), league.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7165}/[H7164]', 'inflected', 'heb', 'קֶרֶס', '["qereç"]', '["with the/ hooks"]', '["n-m"]', 'a knob or belaying-pin (from its swelling form) tache.', 'from 7164;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0168G}/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["<to>/ [the] tent of","[was] to/ [the] tent of","for the/ tent","for/ [the] tent of","into/ a tent","of the/ tent","of/ [the] tent of","to/ [the] tent of"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6249}/[H6247]', 'lemma', 'heb', 'עַשְׁתֵּי', '["ʻashtêy"]', '["[the] one [plus]","[was] one [plus]","one [plus]"]', '["n"]', 'eleven or (ordinal) eleventh eleven(-th).', 'apparently masculine plural construction of 6247 in the sense of an afterthought (used only in connection with 6240 in lieu of 259)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6249}/[H6247]', 'inflected', 'heb', 'עַשְׁתֵּי', '["ʻashtêy"]', '["[belonged] to/ one [plus]","[will belong] to/ one [plus]","for/ [the] one [plus]","of/ one [plus]"]', '["n"]', 'eleven or (ordinal) eleventh eleven(-th).', 'apparently masculine plural construction of 6247 in the sense of an afterthought (used only in connection with 6240 in lieu of 259)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3717}/[H3717]', 'inflected', 'heb', 'כָּפַל', '["kâphal"]', '["and/ you will fold double"]', '["v"]', 'to fold together; figuratively, to repeat double.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2279}/[H2266]', 'inflected', 'heb', 'חֹבֶרֶת', '["chôbereth"]', '["the/ joined set"]', '["n-f"]', 'a joint which coupleth, coupling.', 'feminine active participle of 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7165}/[H7164]', 'inflected', 'heb', 'קֶרֶס', '["qereç"]', '["the/ hooks"]', '["n-m"]', 'a knob or belaying-pin (from its swelling form) tache.', 'from 7164;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3924}/[H3883]', 'inflected', 'heb', 'לֻלָאָה', '["lulâʼâh"]', '["in the/ loops"]', '["n-f"]', 'a loop loop.', 'from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5629}/[H5628]', 'inflected', 'heb', 'סֶרַח', '["çerach"]', '["and/ [the] overhanging of"]', '["n-m"]', 'a redundancy remnant.', 'from 5628;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5628}/[H5628]', 'lemma', 'heb', 'סָרַח', '["çârach"]', '["has it been corrupted?","it will overhang","overhung of","projecting","spreading"]', '["v"]', 'to extend (even to excess) exceeding, hand, spread, stretch self, banish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0520A}/[H517]', 'inflected', 'heb', 'אַמָּה', '["ʼammâh"]', '["and/ the/ cubit"]', '["n-f"]', 'properly, a mother (i.e. unit of measure, or the fore-arm (below the elbow), i.e. a cubit; also a door-base (as a bond of the entrance) cubit, + hundred (by exchange for 3967), measure, post.', 'prolonged from 517;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5736}/[H5736]', 'inflected', 'heb', 'עֲדַף', '["ʻădaph"]', '["in the/ surplus"]', '["v"]', 'to be (causatively have) redundant be more, odd number, be (have) over (and above), overplus, remain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0753}/[H748]', 'inflected', 'heb', 'אֹרֶךְ', '["ʼôrek"]', '["by/ length of","in the/ length","in/ [the] length of"]', '["n-m"]', 'length forever, length, long.', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6654>', 'opaque', 'heb', 'צַד', '["tsad"]', '["[the] sides of","a hip"]', '["n-m"]', 'a side; figuratively, an adversary (be-) side.', 'contr. from an unused root meaning to sidle off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3680}/H9033/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["to/ cover/ it"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4372}/[H3680]', 'inflected', 'heb', 'מִכְסֶה', '["mikçeh"]', '["and/ [the] covering of","and/ a covering of"]', '["n-m"]', 'a covering, i.e. weatherboarding covering.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H4605}/H9011\/[H5927]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["from/ to/ above/ <towards>"]', '["adv"]', 'properly,the upper part, used only adverbially with prefix upward, above, overhead, from the top, etc. above, exceeding(-ly), forward, on (× very) high, over, up(-on, -ward), very.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7175>', 'inflected', 'heb', 'הקרשים', '["ha./Ka.resh","ha./Ke.resh","ha./ke.ra.Shim"]', '["the/ frame","the/ frame[s]","the/ frames"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4908}/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["<to> the/ tabernacle","<to>/ [the] dwelling place of","<to>/ [the] tabernacle of","for the/ tabernacle","of the/ tabernacle"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5975I}/[H5975]', 'lemma', 'heb', 'עָמַד', '["ʻâmad"]', '["[are] about to arise","he establishes","he will arise","he will stand","it will arise","standing upright","they may stand","they will arise"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0520A}/[H517]', 'inflected', 'heb', 'אַמָּה', '["ʼammâh"]', '["<the>/ cubit","[is] the/ cubit","the/ cubit"]', '["n-f"]', 'properly, a mother (i.e. unit of measure, or the fore-arm (below the elbow), i.e. a cubit; also a door-base (as a bond of the entrance) cubit, + hundred (by exchange for 3967), measure, post.', 'prolonged from 517;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7341}/[H7337]', 'lemma', 'heb', 'רֹחַב', '["rôchab"]', '["[the] breadth","[the] breadth of","breadth"]', '["n-m"]', 'width (literally or figuratively) breadth, broad, largeness, thickness, wideness.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7175>', 'inflected', 'heb', 'לקרשי', '["la./Ke.resh","le./kar.Shei"]', '["[belonged] to the/ frame","for/ [the] frames of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7947}/[H7947]', 'lemma', 'heb', 'שָׁלַב', '["shâlab"]', '["joined"]', '["v"]', 'to space off; intensive (evenly) to make equi-distant equally distant, set in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7175>', 'opaque', 'heb', 'קֶרֶשׁ', '["qeresh"]', '["[the] frames of","[was] [the] frames of","frame[s]","frames"]', '["n-m"]', 'a slab or plank; by implication, a deck of a ship bench, board.', 'from an unused root meaning to split off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6285}/[H6311]', 'inflected', 'heb', 'פֵּאָה', '["pêʼâh"]', '["for/ [the] side of","of the/ side","of/ [the] side of","to/ [the] side of","to/ a corner"]', '["n-f"]', 'properly, mouth in a figurative sense, i.e. direction, region, extremity corner, end, quarter, side.', 'feminine of 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5045H>/H9011', 'opaque', 'heb', 'נֶגֶב', '["negeb"]', '["[the] south/ <towards>","[the] south/ towards","south/ -ward"]', '["n-m"]', 'the south (from its drought); specifically, the Negeb or southern district of Judah, occasionally, Egypt (as south to Palestine) south (country, side, -ward).', 'from an unused root meaning to be parched;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8486}/H9011/[H3225]', 'inflected', 'heb', 'תֵּימָן', '["têymân"]', '["[will be] south/ -ward","south/ -ward"]', '["n-f"]', 'the south (as being on the right hand of a person facing the east) south (side, -ward, wind).', 'or תֵּמָן; denominative from 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0134}/[H113]', 'lemma', 'heb', 'אֶדֶן', '["ʼeden"]', '["[the] bases of","bases","bases of"]', '["n-m"]', 'a basis (of a building, a column, etc.) foundation, socket.', 'from the same as 113 (in the sense of strength);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6763}/[H6760]', 'inflected', 'heb', 'צֵלָע', '["tsêlâʻ"]', '["and/ for/ [the] side of"]', '["n-f"]', 'a rib (as curved), literally (of the body) or figuratively (of a door, i.e. leaf); hence, a side, literally (of a person) or figuratively (of an object or the sky, i.e. quarter); architecturally, a (especially floor or ceiling) timber or plank (single or collective, i.e. a flooring) beam, board, chamber, corner, leaf, plank, rib, side (chamber).', 'or (feminine) צַלְעָה; from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6828G}/[H6845]', 'lemma', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["O north wind","[the] north"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0134}/H9028/[H113]', 'inflected', 'heb', 'אֶדֶן', '["ʼeden"]', '["bases/ their"]', '["n-m"]', 'a basis (of a building, a column, etc.) foundation, socket.', 'from the same as 113 (in the sense of strength);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3411}/[H3409]', 'inflected', 'heb', 'יְרֵכָה', '["yᵉrêkâh"]', '["and/ for/ [the] innermost parts of"]', '["n-f"]', 'properly, the flank; but used only figuratively, the rear or recess border, coast, part, quarter, side.', 'feminine of 3409;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4742}/[H7106]', 'inflected', 'heb', 'מְקֻצְעָה', '["mᵉqutsʻâh"]', '["for/ [the] corners of"]', '["n-f"]', 'an angle corner.', 'from 7106 in the denominative sense of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3411}/[H3409]', 'inflected', 'heb', 'יְרֵכָה', '["yᵉrêkâh"]', '["[is] in/ [the] innermost parts of","in the/ innermost parts","in the/ remotest parts","in/ [the] innermost parts of","in/ [the] remotest parts of"]', '["n-f"]', 'properly, the flank; but used only figuratively, the rear or recess border, coast, part, quarter, side.', 'feminine of 3409;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H4295}/[H5786]', 'inflected', 'heb', 'מַטָּה', '["maṭṭâh"]', '["from/ to/ downwards"]', '["adv"]', 'downward, below or beneath; often adverbially with or without prefixes beneath, down(-ward), less, very low, under(-neath).', 'from 5786 with directive enclitic appended;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3162B}/[H3161]', 'inflected', 'heb', 'יַחַד', '["yachad"]', '["and/ together"]', '["n-m"]', 'properly, a unit, i.e. (adverb) unitedly alike, at all (once), both, likewise, only, (al-) together, withal.', 'from 3161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218I>/H9023', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["top/ its"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8147}/H9028/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["for/ [the] two of/ them","for/ both of/ them"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4740H}/[H7106]', 'inflected', 'heb', 'מַקְצוֹעַ', '["maqtsôwaʻ"]', '["the/ buttress","the/ corners"]', '["n-m"]', 'an angle or recess corner, turning.', 'or מַקְצֹעַ; or (feminine) מַקְצֹעָה; from 7106 in the denominative sense of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0134}/H9028/[H113]', 'inflected', 'heb', 'אֶדֶן', '["ʼeden"]', '["and/ bases/ their"]', '["n-m"]', 'a basis (of a building, a column, etc.) foundation, socket.', 'from the same as 113 (in the sense of strength);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1280}/[H1272]', 'lemma', 'heb', 'בְּרִיחַ', '["bᵉrîyach"]', '["[the] bar of","[the] bars of","a bar","bars","bars of"]', '["n-m"]', 'a bolt bar, fugitive.', 'from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3411}/[H3409]', 'inflected', 'heb', 'יְרֵכָה', '["yᵉrêkâh"]', '["for the/ innermost parts"]', '["n-f"]', 'properly, the flank; but used only figuratively, the rear or recess border, coast, part, quarter, side.', 'feminine of 3409;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1280}/[H1272]', 'inflected', 'heb', 'בְּרִיחַ', '["bᵉrîyach"]', '["and/ the/ bar"]', '["n-m"]', 'a bolt bar, fugitive.', 'from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8484}/[H8432]', 'inflected', 'heb', 'תִּיכוֹן', '["tîykôwn"]', '["<the>/ middle","the/ middle"]', '["a"]', 'central middle(-most), midst.', 'or תִּיכֹן; from 8432;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7097A}/[H7096]', 'inflected', 'heb', 'קָצֶה', '["qâtseh"]', '["the/ end"]', '["n-m"]', 'an extremity × after, border, brim, brink, edge, end, (in-) finite, frontier, outmost coast, quarter, shore, (out-) side, × some, ut(-ter-) most (part).', 'or (negative only) קֵצֶה; from 7096; (used in a great variety of applications and idioms; compare 7093)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6823}/[H6822]', 'lemma', 'heb', 'צָפָה', '["tsâphâh"]', '["he had overlaid","he overlaid","overlaid","they are spreading out","you will overlay"]', '["v"]', 'to sheet over (especially with metal) cover, overlay.', 'a primitive root (probably identical with 6822 through the idea of expansion in outlook, transferring to action);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2885}/H9028/[H2883]', 'inflected', 'heb', 'טַבַּעַת', '["ṭabbaʻath"]', '["rings/ their"]', '["n-m"]', 'properly, a seal (as sunk into the wax), i.e. signet (for sealing); hence (generally) a ring of any kind ring.', 'from 2883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004N}/[H1129]', 'lemma', 'heb', 'בַּיִת', '["bayith"]', '["containers","holders"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1280}/[H1272]', 'inflected', 'heb', 'בְּרִיחַ', '["bᵉrîyach"]', '["for the/ bars"]', '["n-m"]', 'a bolt bar, fugitive.', 'from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1280}/[H1272]', 'inflected', 'heb', 'בְּרִיחַ', '["bᵉrîyach"]', '["the/ bar","the/ bars"]', '["n-m"]', 'a bolt bar, fugitive.', 'from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6965H}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ I will raise","and/ he raised up","and/ he set up","and/ he will raise up","and/ they set up","and/ we will raise up","and/ you will set up"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4941J}/H9023/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["according to/ plan/ its"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6532}/[H6531]', 'lemma', 'heb', 'פֹּרֶכֶת', '["pôreketh"]', '["[the] curtain of","a curtain"]', '["n-f"]', 'a separatrix, i.e. (the sacred) screen vail.', 'feminine active participle of the same as 6531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2053}/H9028/[H2053]', 'inflected', 'heb', 'וָו', '["vâv"]', '["hooks/ their"]', '["n-m"]', 'a hook (the name of the sixth Hebrew letter) hook.', 'probably');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6532}/[H6531]', 'inflected', 'heb', 'פֹּרֶכֶת', '["pôreketh"]', '["the/ curtain"]', '["n-f"]', 'a separatrix, i.e. (the sacred) screen vail.', 'feminine active participle of the same as 6531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6532}/[H6531]', 'inflected', 'heb', 'פֹּרֶכֶת', '["pôreketh"]', '["of the/ curtain","of/ [the] curtain of","to the/ curtain"]', '["n-f"]', 'a separatrix, i.e. (the sacred) screen vail.', 'feminine active participle of the same as 6531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6944J}/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["<the>/ holiness","the/ holiness","the/ holy place","the/ holy places"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6944J}/[H6942]', 'lemma', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["[the] holy place of"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6944G}/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["<the>/ holiness","<the>/ holy thing","the/ holiness","the/ holy gifts","the/ holy place","the/ holy places","the/ holy thing","the/ holy thing[s]","the/ holy things"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5227}/[H5226]', 'lemma', 'heb', 'נֹכַח', '["nôkach"]', '["[is] before","[is] opposite","before","opposite","opposite to"]', '["adv"]', 'properly, the front part; used adverbially (especially with preposition), opposite, in front of, forward, in behalf of (over) against, before, direct(-ly), for, right (on).', 'from the same as 5226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7979}/[H7971]', 'inflected', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["and/ the/ table"]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4539}/[H5526]', 'lemma', 'heb', 'מָסָךְ', '["mâçâk"]', '["[the] covering of","[the] screen of","a screen"]', '["n-m"]', 'a cover, i.e. veil covering, curtain, hanging.', 'from 5526;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7551}/[H7551]', 'lemma', 'heb', 'רָקַם', '["râqam"]', '["I was formed","a worker in colors"]', '["v"]', 'to variegate color, i.e. embroider; by implication, to fabricate embroiderer, needlework, curiously work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4539}/[H5526]', 'inflected', 'heb', 'מָסָךְ', '["mâçâk"]', '["for the/ screen","to/ a covering"]', '["n-m"]', 'a cover, i.e. veil covering, curtain, hanging.', 'from 5526;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5178A}\/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["[were] bronze","[will be] bronze","bronze"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7251}/[H7250]', 'lemma', 'heb', 'רָבַע', '["râbaʻ"]', '["[were] square","a square","square"]', '["v"]', 'to be quadrate (four-) square(-d).', 'a primitive root (rather identical with 7250 through the idea of sprawling ''at all fours'' (or possibly the reverse is the order of deriv.); compare 702); properly, to be four (sided); used only as denominative of 7253;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7161A}/H9023/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["horn/ his","horns/ his","horns/ its"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6438H}/H9023/[H6434]', 'inflected', 'heb', 'פִּנָּה', '["pinnâh"]', '["corners/ its"]', '["n-f"]', 'an angle; by implication, a pinnacle; figuratively, a chieftain bulwark, chief, corner, stay, tower.', 'feminine of 6434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5518A}/H9023/[H5518]', 'inflected', 'heb', 'סִיר', '["çîyr"]', '["pots/ its"]', '["n-m"]', 'a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn.', 'or (feminine) סִירָה; or סִרָה; (Jeremiah 52:18), from a primitive root meaning to boil up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1878}/H9033/[H1880]', 'inflected', 'heb', 'דָּשֵׁן', '["dâshên"]', '["to/ take away ashes/ its"]', '["v"]', 'to be fat; transitively, to fatten (or regard as fat); specifically to anoint; figuratively, to satisfy; to remove (fat) ashes (of sacrifices) accept, anoint, take away the (receive) ashes (from), make (wax) fat.', 'a primitive root; also denominatively (from 1880)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3257}/H9023/[H3261]', 'inflected', 'heb', 'יָע', '["yâʻ"]', '["and/ shovels/ its"]', '["n-m"]', 'a shovel shovel.', 'from 3261;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4219}/H9023/[H2236]', 'inflected', 'heb', 'מִזְרָק', '["mizrâq"]', '["and/ bowls/ its"]', '["n-m"]', 'a bowl (as if for sprinkling) bason, bowl.', 'from 2236;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4207B>/H9023', 'inflected', 'heb', 'ומזלגתיו', '["u./miz.le.go.Ta/v"]', '["and/ forks/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4289}/H9023/[H4288]', 'inflected', 'heb', 'מַחְתָּה', '["machtâh"]', '["and/ fire-pans/ its"]', '["n-f"]', 'a pan for live coals censer, firepan, snuffdish.', 'the same as 4288 in the sense of removal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4345}/[H3527]', 'lemma', 'heb', 'מַכְבֵּר', '["makbêr"]', '["[the] grating of","a grating"]', '["n-m"]', 'a grate grate.', 'from 3527 in the sense of covering (compare 3531);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7568}/[H3423]', 'lemma', 'heb', 'רֶשֶׁת', '["resheth"]', '["a net","a net of"]', '["n-f"]', 'a net (as catching animals) net(-work).', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7568}/[H3423]', 'inflected', 'heb', 'רֶשֶׁת', '["resheth"]', '["the/ net"]', '["n-f"]', 'a net (as catching animals) net(-work).', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3749}/[H3522]', 'lemma', 'heb', 'כַּרְכֹּב', '["karkôb"]', '["[the] ledge of"]', '["n-m"]', 'a rim or top margin compass.', 'expanded from the same as 3522;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4196}/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["<to> the/ altar","<to> the/ altars","for the/ altar","of the/ altar","to the/ altar","to/ [the] altar of"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0905G}/H9023/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["parts/ his","poles/ its"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5375H}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["when/ carry"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5014}/[H5014]', 'lemma', 'heb', 'נָבַב', '["nâbab"]', '["hollow","hollow of"]', '["v"]', 'to pierce; to be hollow, or (figuratively) foolish hollow, vain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2691A}/[H2690]', 'lemma', 'heb', 'חָצֵר', '["châtsêr"]', '["[the] court","[the] court of","[the] courtyard of","[the] courtyards of","a courtyard","courtyards"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5045H>', 'opaque', 'heb', 'נֶגֶב', '["negeb"]', '["[the] south","[the] south of","[the] southward","south of"]', '["n-m"]', 'the south (from its drought); specifically, the Negeb or southern district of Judah, occasionally, Egypt (as south to Palestine) south (country, side, -ward).', 'from an unused root meaning to be parched;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7050B}/[H7049]', 'lemma', 'heb', 'קֶלַע', '["qelaʻ"]', '["[the] curtains of","curtains"]', '["n-m"]', 'a sling; also a (door) screen (as if slung across), or the valve (of the door) itself hanging, leaf, sling.', 'from 7049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2691A}/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["[belonged] to the/ courtyard","[belongs] to/ [the] courtyard of","[were] to the/ courtyard","for the/ courtyard","for/ [the] courts of","of the/ courtyard","to the/ courtyard","to/ [the] court of"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5982G}/H9023/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["and/ pillars/ its"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2053}/[H2053]', 'lemma', 'heb', 'וָו', '["vâv"]', '["[the] hooks of","hooks"]', '["n-m"]', 'a hook (the name of the sixth Hebrew letter) hook.', 'probably');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5982G}/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["the/ pillar","the/ pillars"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2838}/H9028/[H2836]', 'inflected', 'heb', 'חָשֻׁק', '["châshuq"]', '["and/ bands/ their"]', '["n-m"]', 'attached, i.e. a fence-rail or rod connecting the posts or pillars fillet.', 'or חָשׁוּק; past participle of 2836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5982G}/H9028/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["pillars/ their"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4217H}/H9011/[H2224]', 'inflected', 'heb', 'מִזְרָח', '["mizrâch"]', '["[the] rising of/ towards","east/ -ward","east/ -wards"]', '["n-m"]', 'sunrise, i.e. the east east (side, -ward), (sun-) rising (of the sun).', 'from 2224;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3802>', 'inflected', 'heb', 'לכתף', '["la./ka.Tef","le./Khe.tef"]', '["[were] to/ [the] side of","for the/ side"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H3802>', 'inflected', 'heb', 'ולכתף', '["ve./la./ka.Tef"]', '["and/ for the/ side"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8179G}/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["and/ for/ [the] gate of"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2836B}/[H2820]', 'lemma', 'heb', 'חָשַׁק', '["châshaq"]', '["[were] furnished with bands","[will be] furnished with bands"]', '["v"]', 'to cling, i.e. join, (figuratively) to love, delight in; elliptically; to deliver have a delight, (have a) desire, fillet, long, set (in) love.', 'a primitive root; also interchangeable for 2820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2572}/[H2568]', 'inflected', 'heb', 'חֲמִשִּׁים', '["chămishshîym"]', '["for/ fifty","on/ fifty"]', '["n"]', 'fifty fifty.', 'multiple of 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6967}/[H6965]', 'inflected', 'heb', 'קוֹמָה', '["qôwmâh"]', '["and/ [the] height","and/ [the] height of"]', '["n-f"]', 'height × along, height, high, stature, tall.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5656H}/H9023/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["service/ his","service/ its"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3489>/H9023', 'opaque', 'heb', 'יָתֵד', '["yâthêd"]', '["tent pegs/ its"]', '["n-f"]', 'a peg nail, paddle, pin, stake.', 'from an unused root meaning to pin through or fast;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3489>', 'opaque', 'heb', 'יָתֵד', '["yâthêd"]', '["[the] peg of","[the] tent pegs of","a peg","a tent peg"]', '["n-f"]', 'a peg nail, paddle, pin, stake.', 'from an unused root meaning to pin through or fast;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2134}/[H2141]', 'lemma', 'heb', 'זַךְ', '["zak"]', '["[am] pure","[are] pure","[is] pure","pure"]', '["a"]', 'clear clean, pure.', 'from 2141;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3795}/[H3807]', 'lemma', 'heb', 'כָּתִית', '["kâthîyth"]', '["pressed"]', '["a"]', 'beaten, i.e. pure (oil) beaten.', 'from 3807;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5927I}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["<to>/ goes up","to/ lift up","to/ offer up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5216A}/[H5214]', 'lemma', 'heb', 'נִיר', '["nîyr"]', '["[is] a lamp","[the] lamp of","[the] lamps of","a lamp"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8548>', 'opaque', 'heb', 'תָּמִיד', '["tâmîyd"]', '["[which] continually","continually","continuity"]', '["n-m"]', 'properly, continuance (as indefinite extension); but used only (attributively as adjective) constant (or adverbially, constantly); elliptically the regular (daily) sacrifice alway(-s), continual (employment, -ly), daily, (n-)ever(-more), perpetual.', 'from an unused root meaning to stretch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4150I}/[H3259]', 'lemma', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["[the] appointed meeting","[the] appointed places of","an appointed meeting","appointed meeting","meeting","meeting of"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6186A}/[H6186]', 'lemma', 'heb', 'עָרַךְ', '["ʻârak"]', '["I arrange","I have arranged","I have set in order","[is] arranged","[those who] prepare of","[was] arranged","arranged","he drew up in formation","he has arranged","he will arrange","is he comparable","let me set in order","line up","preparing of","set in order","she has arranged","they are arranging","they had deployed","to compare","we will set in order","will you compare","you arrange"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6153}/[H6150]', 'inflected', 'heb', 'עֶרֶב', '["ʻereb"]', '["from/ evening"]', '["n-m"]', 'dusk day, even(-ing, tide), night.', 'from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7126H}/[H7126]', 'lemma', 'heb', 'קָרַב', '["qârab"]', '["[are] presenting","[is] presenting","[when] he presented","[who] were bringing near","bring near","he brought near","he presented","he will bring near","he will present","it will present","people will present","she brought near","someone will present","they brought near","they had brought near","they have presented","they will bring near","they will present","to bring near","you must present","you will bring near","you will present"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3547}/H9033/[H3548]', 'inflected', 'heb', 'כָּהַן', '["kâhan"]', '["to/ serve as priest/ he"]', '["v"]', 'to officiate as a priest; figuratively, to put on regalia deck, be (do the office of a, execute the, minister in the) priest(''s office).', 'a primitive root, apparently meaning to mediate in religious services; but used only as denominative from 3548;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0385}/[H339]', 'inflected', 'heb', 'אִיתָמָר', '["ʼÎythâmâr"]', '["and/ Ithamar"]', '["n-pr-m"]', 'Ithamar, a son of Aaron Ithamar.', 'from 339 and 8558; coast of the palm-tree;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3519}/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["for/ glory","for/ honor"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8597}/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["and/ <into>/ honor","and/ for/ beauty","and/ for/ honor"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2450}/[H2449]', 'lemma', 'heb', 'חָכָם', '["châkâm"]', '["O wise [men]","[are] skillful","[are] wise","[are] wise [things]","[is] wise","[people] skillful of","[people] wise","[people] wise of","[person] skillful of","[the] wise [people] of","[the] wise [women] of","a prudent [one]","a wise [person]","a wise [person] of","a wise [son]","learned ones","shrewd","skillful","skillful [people]","skillful [person]","skillful of","wise","wise [people]","wise [women] of","wise of","wise people"]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4390}/H9033/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["I have filled/ it","it has filled/ him"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2451}/[H2449]', 'lemma', 'heb', 'חׇכְמָה', '["chokmâh"]', '["[is] wisdom","[the] wisdom of","of wisdom","skill","wisdom","wisdom of","wisdom<s>"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0899B}/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["<the>/ clothing","[are] the/ garments","of the/ garments","the/ clothing","the/ garment","the/ garments"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2833>', 'opaque', 'heb', 'חֹשֶׁן', '["chôshen"]', '["[the] breastpiece of","a breastpiece","a breastpiece of"]', '["n-m"]', 'perhaps a pocket (as holding the Urim and Thummim), or rich (as containing gems), used only of the gorget of the highpriest breastplate.', 'from an unused root probably meaning to contain or sparkle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0646}/[H646]', 'inflected', 'heb', 'אֵפוֹד', '["ʼêphôwd"]', '["and/ an ephod"]', '["n-m"]', 'a girdle; specifically the ephod or highpriest''s shoulder-piece; also generally, an image ephod.', 'rarely אֵפֹד; probably of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4598}/[H4603]', 'inflected', 'heb', 'מְעִיל', '["mᵉʻîyl"]', '["and/ a robe"]', '["n-m"]', 'a robe (i.e. upper and outer garment) cloke, coat, mantle, robe.', 'from 4603 in the sense of covering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3801>', 'inflected', 'heb', 'וכתנת', '["u./khe.To.net","ve./kha.te.Not"]', '["and/ [the] long garment of","and/ a tunic of","and/ tunics of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8665}/[H7660]', 'lemma', 'heb', 'תַּשְׁבֵּץ', '["tashbêts"]', '["checkered work"]', '["n-m"]', 'checkered stuff (as reticulated) broidered.', 'from 7660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4701}/[H6801]', 'lemma', 'heb', 'מִצְנֶפֶת', '["mitsnepheth"]', '["a turban","a turban of"]', '["n-f"]', 'a tiara, i.e. official turban (of a king or high priest) diadem, mitre.', 'from 6801;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0073>', 'inflected', 'heb', 'ואבנט', '["ve./''av.Net"]', '["and/ a sash"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1121A}/H9023/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ <to>/ sons/ his","and/ for/ son/ his","and/ for/ sons/ his","and/ of/ sons/ his","and/ to/ children/ his","and/ to/ son/ his","and/ to/ sons/ his"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8504}/[H7827]', 'inflected', 'heb', 'תְּכֵלֶת', '["tᵉkêleth"]', '["the/ violet stuff"]', '["n-f"]', 'the cerulean mussel, i.e. the color (violet) obtained therefrom or stuff dyed therewith blue.', 'probably for 7827;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0713>', 'inflected', 'heb', 'הארגמן', '["ha./''ar.ga.Man"]', '["<the>/ purple","the/ purple"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8438B}/[H3216]', 'lemma', 'heb', 'תּוֹלָע', '["tôwlâʻ"]', '["O worm of","[am] a worm","[are] worm[s]","[the] scarlet stuff of","a worm","scarlet stuff","scarlet stuff of"]', '["n-m n-f"]', 'a maggot (as voracious); specifically (often with ellipsis of 8144) the crimson-grub, but used only (in this connection) of the color from it, and cloths dyed therewith crimson, scarlet, worm.', 'and (feminine) תּוֹלֵעָה; or תּוֹלַעַת; or תֹּלַעַת; from 3216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8336B}\/[H4897]', 'inflected', 'heb', 'שֵׁשׁ', '["shêsh"]', '["the/ fine linen"]', '["n-m"]', 'bleached stuff, i.e. white linen or (by analogy) marble × blue, fine (twined) linen, marble, silk.', 'or (for alliteration with 4897) שְׁשִׁי; for 7893;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0646}/[H646]', 'inflected', 'heb', 'אֵפוֹד', '["ʼêphôwd"]', '["the/ ephod"]', '["n-m"]', 'a girdle; specifically the ephod or highpriest''s shoulder-piece; also generally, an image ephod.', 'rarely אֵפֹד; probably of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3802>', 'opaque', 'heb', 'כָּתֵף', '["kâthêph"]', '["[the] shoulder of","[the] shoulder-pieces of","[the] side of","[the] sides of","[the] slope","[the] slope of","a shoulder","shoulder","shoulder-pieces","supports"]', '["n-f"]', 'the shoulder (proper, i.e. upper end of the arm; as being the spot where the garments hang); figuratively, side-piece or lateral projection of anything arm, corner, shoulder(-piece), side, undersetter.', 'from an unused root meaning to clothe;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2805}/[H2803]', 'inflected', 'heb', 'חֵשֶׁב', '["chêsheb"]', '["and/ [the] girdle of"]', '["n-m"]', 'a belt or strap (as being interlaced) curious girdle.', 'from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0642}/H9023/[H646]', 'inflected', 'heb', 'אֵפֻדָּה', '["ʼêphuddâh"]', '["ephod/ its"]', '["n-f"]', 'a girding on (of the ephod); hence, generally, a plating (of metal) ephod, ornament.', 'feminine of 646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4639G}/H9023/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["[will be] like/ workmanship/ its"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6605B}/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["and/ he engraved","and/ you will engrave"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8034}/H9028/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["of/ names/ their"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8337}/[H7797]', 'inflected', 'heb', 'שֵׁשׁ', '["shêsh"]', '["the/ six"]', '["n"]', 'six (as an overplus beyond five or the fingers of the hand); as ordinal sixth six(-teen, -teenth), sixth.', 'masculine שִׁשָּׁה; a primitive number; see 7797');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8435}/H9028/[H3205]', 'inflected', 'heb', 'תּוֹלְדָה', '["tôwlᵉdâh"]', '["according to/ genealogies/ their"]', '["n-f"]', '(plural only) descent, i.e. family; (figuratively) history birth, generations.', 'or תֹּלְדָה; from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2796}/[H2790]', 'lemma', 'heb', 'חָרָשׁ', '["chârâsh"]', '["a craftsman","a craftsman of","an engraver","an engraver of","craftsmen","craftsmen of"]', '["n-m"]', 'a fabricator or any material artificer, ( ) carpenter, craftsman, engraver, maker, mason, skilful, ( ) smith, worker, workman, such as wrought.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6603}/[H6605]', 'lemma', 'heb', 'פִּתּוּחַ', '["pittûwach"]', '["[the] engravings of","[was the] engravings of","engraving","engravings","engravings of"]', '["n-m"]', 'sculpture (in low or high relief or even intaglio) carved (work) (are, en-) grave(-ing, -n).', 'or פִּתֻּחַ ; passive participle of 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2368}/[H2856]', 'lemma', 'heb', 'חוֹתָם', '["chôwthâm"]', '["a seal","a signet-ring"]', '["n-m"]', 'a signature-ring seal, signet.', 'or חֹתָם; from 2856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6605B}/[H6605]', 'lemma', 'heb', 'פָּתַח', '["pâthach"]', '["[am] about to engrave","engraved","you will engrave"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4865}/[H7660]', 'lemma', 'heb', 'מִשְׁבְּצָה', '["mishbᵉtsâh"]', '["filigree settings of"]', '["n-f"]', 'a brocade; by analogy, a (reticulated) setting of a gem ouch, wrought.', 'from 7660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3802>/H9023', 'opaque', 'heb', 'כָּתֵף', '["kâthêph"]', '["shoulder-pieces/ his","shoulders/ his"]', '["n-f"]', 'the shoulder (proper, i.e. upper end of the arm; as being the spot where the garments hang); figuratively, side-piece or lateral projection of anything arm, corner, shoulder(-piece), side, undersetter.', 'from an unused root meaning to clothe;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2146}\/[H2142]', 'inflected', 'heb', 'זִכְרוֹן', '["zikrôwn"]', '["to/ a reminder"]', '["n-m"]', 'a memento (or memorable thing, day or writing) memorial, record.', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8333}/[H8327]', 'lemma', 'heb', 'שַׁרְשְׁרָה', '["sharshᵉrâh"]', '["[the] chains of","chains","chains of"]', '["n-f"]', 'a chain; (architectural) probably a garland chain.', 'from 8327 (compare 8331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4020}/[H1379]', 'lemma', 'heb', 'מִגְבָּלָה', '["migbâlâh"]', '["twisted cords"]', '["n-f"]', 'a border end.', 'from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5688}/[H5687]', 'lemma', 'heb', 'עֲבֹת', '["ʻăbôth"]', '["[the] cords of","[the] rope of","branches","cordage","ropes"]', '["n"]', 'something intwined, i.e. a string, wreath or foliage band, cord, rope, thick bough (branch), wreathen (chain).', 'or עֲבוֹת; or (feminine) עֲבֹתָה; the same as 5687;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5688}/[H5687]', 'inflected', 'heb', 'עֲבֹת', '["ʻăbôth"]', '["the/ cords","the/ ropes"]', '["n"]', 'something intwined, i.e. a string, wreath or foliage band, cord, rope, thick bough (branch), wreathen (chain).', 'or עֲבוֹת; or (feminine) עֲבֹתָה; the same as 5687;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4865}\/[H7660]', 'inflected', 'heb', 'מִשְׁבְּצָה', '["mishbᵉtsâh"]', '["the/ filigree settings"]', '["n-f"]', 'a brocade; by analogy, a (reticulated) setting of a gem ouch, wrought.', 'from 7660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941G}/[H8199]', 'lemma', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["<the> judgment of","[the] judgment of","[the] judgments of","[the] ordinance of","a case","a sentence of","an ordinance","judgment","judgment of","judgments","judgments of","justice","justice of"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0646}/[H646]', 'lemma', 'heb', 'אֵפוֹד', '["ʼêphôwd"]', '["[are] an ephod","[the] ephod","[will be] an ephod","an ephod","an ephod of"]', '["n-m"]', 'a girdle; specifically the ephod or highpriest''s shoulder-piece; also generally, an image ephod.', 'rarely אֵפֹד; probably of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213H}/H9033/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["I made/ him","I made/ it","[the] [one who] made/ it","[who] he made/ him","did he make/ him","he made/ it","he makes/ it","he works/ it","maker/ his","you will make/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3717}/[H3717]', 'lemma', 'heb', 'כָּפַל', '["kâphal"]', '["folded double"]', '["v"]', 'to fold together; figuratively, to repeat double.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2239}/[H2219]', 'lemma', 'heb', 'זֶרֶת', '["zereth"]', '["[was] a span","[will be] a span","a span"]', '["n-f"]', 'the spread of the fingers, i.e. a span span.', 'from 2219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2239}/[H2219]', 'inflected', 'heb', 'זֶרֶת', '["zereth"]', '["and/ [was] a span","and/ [will be] a span","and/ a span"]', '["n-f"]', 'the spread of the fingers, i.e. a span span.', 'from 2219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4396}/[H4394]', 'lemma', 'heb', 'מִלֻּאָה', '["milluʼâh"]', '["a setting of"]', '["n-f"]', 'a filling, i.e. setting (of gems) enclosing, setting.', 'feminine of 4394;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2905>', 'opaque', 'heb', 'טוּר', '["ṭûwr"]', '["[was] a row of","[will be] a row of","rows","rows of"]', '["n-m"]', 'a row; hence, a wall row.', 'from an unused root meaning to range in a regular manner;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0124}/[H119]', 'lemma', 'heb', 'אֹדֶם', '["ʼôdem"]', '["a ruby","ruby"]', '["n-f"]', 'redness, i.e. the ruby, garnet, or some other red gem sardius.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6357}/[H6357]', 'lemma', 'heb', 'פִּטְדָה', '["piṭdâh"]', '["<the> topaz of","a topaz","topaz"]', '["n-f"]', 'a gem, probably the topaz topaz.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1304A}/[H1300]', 'inflected', 'heb', 'בָּרֶקֶת', '["bâreqeth"]', '["and/ a beryl"]', '["n-f"]', 'a gem (as flashing), perhaps the emerald carbuncle.', 'or בָּרְקַתxlit bârᵉkath corrected to bârᵉqath; from 1300;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2905>', 'inflected', 'heb', 'הטור', '["ha./Tur"]', '["the/ row"]', NULL, NULL, NULL);
