INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5306>', 'opaque', 'heb', 'נֹפֶךְ', '["nôphek"]', '["[was] a turquoise","[will be] a turquoise","turquoise"]', '["n-m"]', 'shining; a gem, probably the garnet emerald.', 'from an unused root meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5601}/[H5608]', 'lemma', 'heb', 'סַפִּיר', '["çappîyr"]', '["[was] sapphire","a sapphire","sapphire","sapphires"]', '["n-m"]', 'a gem (perhaps used for scratching other substances), probably the sapphire sapphire.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3095}/[H1986]', 'inflected', 'heb', 'יַהֲלֹם', '["yahălôm"]', '["and/ an emerald","and/ emerald"]', '["n-m"]', 'a precious stone, probably onyx diamond.', 'from 1986 (in the sense of hardness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3958>', 'opaque', 'heb', 'לֶשֶׁם', '["leshem"]', '["[was] a jacinth","[will be] a jacinth"]', '["n-m"]', 'a gem, perhaps the jacinth ligure.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7618>', 'opaque', 'heb', 'שְׁבוּ', '["shᵉbûw"]', '["an agate"]', '["n-f"]', 'a gem (from its sparkle), probably the agate agate.', 'from an unused root (probably identical with that of 7617 through the idea of subdivision into flashes or streamers (compare 7632) meaning to flame;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0306}/[H2492]', 'inflected', 'heb', 'אַחְלָמָה', '["ʼachlâmâh"]', '["and/ an amethyst"]', '["n-f"]', 'a gem, probably the amethyst amethyst.', 'perhaps from 2492 (and thus dream-stone);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8658}/[H8659]', 'lemma', 'heb', 'תַּרְשִׁישׁ', '["tarshîysh"]', '["[was] a chrysolite","[will be] a chrysolite","chrysolite"]', '["n-m"]', 'a gem, perhaps the topaz beryl.', 'probably of foreign derivation (compare 8659);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7718>', 'inflected', 'heb', 'ושהם', '["ve./Sho.ham"]', '["and/ an onyx"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3471>', 'inflected', 'heb', 'וישפה', '["ve./Ya.she.Peh","ve./ya.she.Peh"]', '["and/ a jasper","and/ jasper"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7660}/[H7660]', 'lemma', 'heb', 'שָׁבַץ', '["shâbats"]', '["set"]', '["v"]', 'to interweave (colored) threads in squares; by implication (of reticulation) to inchase gems in gold embroider, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4396}/H9028/[H4394]', 'inflected', 'heb', 'מִלֻּאָה', '["milluʼâh"]', '["in/ settings/ their"]', '["n-f"]', 'a filling, i.e. setting (of gems) enclosing, setting.', 'feminine of 4394;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2833>', 'inflected', 'heb', 'החשן', '["Ha./cho.shen","ha./Cho.shen"]', '["the/ breastpiece"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8331}/[H8327]', 'lemma', 'heb', 'שַׁרְשָׁה', '["sharshâh"]', '["chains of"]', '["n-f"]', 'a chain (as rooted, i.e. linked) chain. Compare 8333.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1383}/[H1379]', 'lemma', 'heb', 'גַּבְלֻת', '["gabluth"]', '["twisting"]', '["n-f"]', 'a twisted chain or lace end.', 'from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4865}/[H7660]', 'inflected', 'heb', 'מִשְׁבְּצָה', '["mishbᵉtsâh"]', '["the/ filigree settings"]', '["n-f"]', 'a brocade; by analogy, a (reticulated) setting of a gem ouch, wrought.', 'from 7660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193I}/H9023/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["edge/ its","lip/ its"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5676G}/[H5674]', 'lemma', 'heb', 'עֵבֶר', '["ʻêber"]', '["[the] other side of","[the] side of","beyond"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004O}/H9011/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[the] inside/ towards","[were] inside/ towards"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4136}/[H4135]', 'inflected', 'heb', 'מוּל', '["mûwl"]', '["from/ [the] front of","from/ in front of"]', '["n-m"]', 'properly, abrupt, i.e. a precipice; by implication, the front; used only adverbially (with prepositional prefix) opposite (over) against, before, (fore-) front, from, (God-) ward, toward, with.', 'or מוֹל; (Deuteronomy 1:1), or מוֹאל; (Nehemiah 12:38), or מֻל; (Numbers 22:5), from 4135;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4225}/H9023/[H2266]', 'inflected', 'heb', 'מַחְבֶּרֶת', '["machbereth"]', '["joining/ its"]', '["n-f"]', 'a junction, i.e. seam or sewed piece coupling.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2805}/[H2803]', 'inflected', 'heb', 'חֵשֶׁב', '["chêsheb"]', '["<to>/ [the] girdle of"]', '["n-m"]', 'a belt or strap (as being interlaced) curious girdle.', 'from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7405}/[H7405]', 'inflected', 'heb', 'רָכַס', '["râkaç"]', '["so/ they may bind"]', '["v"]', 'to tie bind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2885}/H9023/[H2883]', 'inflected', 'heb', 'טַבַּעַת', '["ṭabbaʻath"]', '["from/ rings/ its"]', '["n-m"]', 'properly, a seal (as sunk into the wax), i.e. signet (for sealing); hence (generally) a ring of any kind ring.', 'from 2883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6616}/[H6617]', 'inflected', 'heb', 'פָּתִיל', '["pâthîyl"]', '["with/ a cord of"]', '["n-m"]', 'twine bound, bracelet, lace, line, ribband, thread, wire.', 'from 6617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2805}/[H2803]', 'lemma', 'heb', 'חֵשֶׁב', '["chêsheb"]', '["[the] girdle of"]', '["n-m"]', 'a belt or strap (as being interlaced) curious girdle.', 'from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2118}/[H2118]', 'lemma', 'heb', 'זָחַח', '["zâchach"]', '["it was displaced","it will be displaced"]', '["v"]', 'to shove or displace loose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2833>', 'inflected', 'heb', 'בחשן', '["be./Cho.shen"]', '["on/ [the] breastpiece of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0224}/[H217]', 'inflected', 'heb', 'אוּרִים', '["ʼÛwrîym"]', '["the/ Urim"]', '["n-m"]', 'Urim, the oracular brilliancy of the figures in the high-priest''s breastplate Urim.', 'plural of 217; lights;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8550}/[H8537]', 'inflected', 'heb', 'תֻּמִּים', '["Tummîym"]', '["the/ Thummim"]', '["n-pr-m"]', 'perfections, i.e. (techn.) one of the epithets of the objects in the high-priest''s breastplate as an emblem of complete Truth Thummim.', 'plural of 8537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4598}/[H4603]', 'lemma', 'heb', 'מְעִיל', '["mᵉʻîyl"]', '["[the] robe of","a robe","a robe of","robes"]', '["n-m"]', 'a robe (i.e. upper and outer garment) cloke, coat, mantle, robe.', 'from 4603 in the sense of covering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3632}/[H3634]', 'lemma', 'heb', 'כָּלִיל', '["kâlîyl"]', '["[am] perfect of","[the] entirety of","[was] perfect","a whole offering","an entirety of","completely","perfect of"]', '["a"]', 'complete; as noun, the whole (specifically, a sacrifice entirely consumed); as adverb, fully all, every whit, flame, perfect(-ion), utterly, whole burnt offering (sacrifice), wholly.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310J}/[H6284]', 'lemma', 'heb', 'פֶּה', '["peh"]', '["[the] opening of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8432>/H9023', 'inflected', 'heb', 'בתוכו', '["be./to.Kh/o","be./to.kh/o"]', '["[is] in/ [the] midst of/ it","[was] in/ [the] middle of/ it","in/ [the] middle of/ it","in/ [the] midst of/ him"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6310J}/H9023/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["[belonged] to/ opening/ its","to/ opening/ its"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0707}/[H707]', 'lemma', 'heb', 'אָרַג', '["ʼârag"]', '["[were] weaving","a weaver","they weave","weavers","you will weave"]', '["v"]', 'to plait or weave weaver(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6310J}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["like/ [the] opening of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8473}/[H2734]', 'lemma', 'heb', 'תַּחֲרָא', '["tachărâʼ"]', '["a collar"]', '["n-m"]', 'a linen corslet (as white or hollow) habergeon.', 'from 2734 in the original sense of 2352 or 2353;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7167}/[H7167]', 'lemma', 'heb', 'קָרַע', '["qâraʻ"]', '["I tore","I will tear away","[am] about to tear","[is] about to be torn apart","[was] torn","[were] torn","certainly <to tear>","did you tear","he had torn","he has torn","he tore","it was torn","it was torn apart","it will be torn","she tore","tear","they tore","torn of","you tear open","you tore"]', '["v"]', 'to rend, literally or figuratively (revile, paint the eyes, as if enlarging them) cut out, rend, × surely, tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7757>/H9023', 'opaque', 'heb', 'שׁוּל', '["shûwl"]', '["skirt/ its"]', '["n-m"]', 'a skirt; by implication, a bottom edge hem, skirt, train.', 'from an unused root meaning to hang down;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7416}/[H7426]', 'lemma', 'heb', 'רִמּוֹן', '["rimmôwn"]', '["pomegranates","pomegranates of"]', '["n-m"]', 'a pomegranate, the tree (from its upright growth) or the fruit (also an artificial ornament) pomegranate.', 'or רִמֹּן; from 7426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6472}/[H6471]', 'inflected', 'heb', 'פַּעֲמֹן', '["paʻămôn"]', '["and/ bells of"]', '["n-m"]', 'a bell (as struck) bell.', 'from 6471;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6472}/[H6471]', 'lemma', 'heb', 'פַּעֲמֹן', '["paʻămôn"]', '["a bell","a bell of","bells of"]', '["n-m"]', 'a bell (as struck) bell.', 'from 6471;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7416}/[H7426]', 'inflected', 'heb', 'רִמּוֹן', '["rimmôwn"]', '["and/ a pomegranate","and/ pomegranate","and/ pomegranates"]', '["n-m"]', 'a pomegranate, the tree (from its upright growth) or the fruit (also an artificial ornament) pomegranate.', 'or רִמֹּן; from 7426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7757>', 'opaque', 'heb', 'שׁוּל', '["shûwl"]', '["[the] skirts of"]', '["n-m"]', 'a skirt; by implication, a bottom edge hem, skirt, train.', 'from an unused root meaning to hang down;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4598}/[H4603]', 'inflected', 'heb', 'מְעִיל', '["mᵉʻîyl"]', '["the/ robe"]', '["n-m"]', 'a robe (i.e. upper and outer garment) cloke, coat, mantle, robe.', 'from 4603 in the sense of covering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8334}/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["to/ serve"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963H>/H9023', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["sound/ its"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3318G}/H9043/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ when/ comes out/ he","and/ when/ goes out/ he"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6731A}/[H6692]', 'lemma', 'heb', 'צִיץ', '["tsîyts"]', '["[the] plate of","a flower","a plate of","blossom","flowers"]', '["n-m"]', 'properly, glistening, i.e. a burnished plate; also a flower (as bright colored); a wing (as gleaming in the air) blossom, flower, plate, wing.', 'or צִץ; from 6692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6616}/[H6617]', 'lemma', 'heb', 'פָּתִיל', '["pâthîyl"]', '["<the> thread of","a cord","a cord of","threads"]', '["n-m"]', 'twine bound, bracelet, lace, line, ribband, thread, wire.', 'from 6617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4701}/[H6801]', 'inflected', 'heb', 'מִצְנֶפֶת', '["mitsnepheth"]', '["the/ turban"]', '["n-f"]', 'a tiara, i.e. official turban (of a king or high priest) diadem, mitre.', 'from 6801;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4696>', 'opaque', 'heb', 'מֵצַח', '["mêtsach"]', '["[the] forehead of","[the] foreheads of","forehead"]', '["n-m"]', 'the forehead (as open and prominent) brow, forehead, impudent.', 'from an unused root meaning to be clear, i.e. conspicuous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375J}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ he will bear","and/ it will bear","and/ they will bear","and/ they will cause to bear","and/ you will bear"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6944G}/H9028/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["holiness<es>/ their","holy things/ their"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4696>/H9023', 'opaque', 'heb', 'מֵצַח', '["mêtsach"]', '["forehead/ his"]', '["n-m"]', 'the forehead (as open and prominent) brow, forehead, impudent.', 'from an unused root meaning to be clear, i.e. conspicuous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7522}/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["[are] for/ acceptance","[will be] for/ acceptance","for/ acceptance"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7660}/[H7660]', 'inflected', 'heb', 'שָׁבַץ', '["shâbats"]', '["and/ you will weave"]', '["v"]', 'to interweave (colored) threads in squares; by implication (of reticulation) to inchase gems in gold embroider, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0073>', 'opaque', 'heb', 'אַבְנֵט', '["ʼabnêṭ"]', '["a sash","sashes"]', '["n-m"]', 'a belt girdle.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4021}/[H1389]', 'inflected', 'heb', 'מִגְבָּעָה', '["migbâʻâh"]', '["and/ headdresses"]', '["n-f"]', 'a cap (as hemispherical) bonnet.', 'from the same as 1389;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4886}/[H4886]', 'inflected', 'heb', 'מָשַׁח', '["mâshach"]', '["and/ he anointed","and/ he will anoint","and/ they anointed","and/ they anointed [him]","and/ they have anointed","and/ you will anoint"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027R}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3547}/[H3548]', 'inflected', 'heb', 'כָּהַן', '["kâhan"]', '["and/ he served as priest","and/ he will serve as a priest","and/ they served as priests","and/ they will serve as priests"]', '["v"]', 'to officiate as a priest; figuratively, to put on regalia deck, be (do the office of a, execute the, minister in the) priest(''s office).', 'a primitive root, apparently meaning to mediate in religious services; but used only as denominative from 3548;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4370}/[H3647]', 'lemma', 'heb', 'מִכְנָס', '["miknâç"]', '["[the] undergarments of","undergarments of"]', '["n-m"]', '(only in dual) drawers (from concealing the private parts) breeches.', 'from 3647 in the sense of hiding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0906}/[H909]', 'lemma', 'heb', 'בַּד', '["bad"]', '["linen","linen of","linen<s>"]', '["n-m"]', 'flaxen thread or yarn; hence, a linen garment linen.', 'perhaps from 909 (in the sense of divided fibres);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3680}/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["[about] to/ cover","to/ cover"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H4975>', 'inflected', 'heb', 'ממתנים', '["mi./ma.te.Na.yim","mi./ma.te.Nei"]', '["from/ [the] hips","more than/ [the] loins of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121G}/H9023/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["son/ his","sons/ his"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0935G}/H9048/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ came/ they","when/ come/ they","when/ go/ they","when/ went/ they"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5066G}/H9048/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["when/ draw near/ they"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6944J}/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["in the/ holy place"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375J}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["I will bear","[is] bearing","bear","has he borne","he bore","he will bear","it will bear","she will bear","they will bear","you will bear"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2233H}/H9023/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ for/ offspring/ his","and/ to/ offspring/ his"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310A}/H9033\/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["after/ him"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6942G}/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["to/ consecrate","to/ consecrate [them]","to/ consecrate themselves","to/ keep holy","to/ set apart as holy"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3547}/[H3548]', 'inflected', 'heb', 'כָּהַן', '["kâhan"]', '["to/ serve as priest","to/ serve as priests"]', '["v"]', 'to officiate as a priest; figuratively, to put on regalia deck, be (do the office of a, execute the, minister in the) priest(''s office).', 'a primitive root, apparently meaning to mediate in religious services; but used only as denominative from 3548;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2471}/[H2490]', 'inflected', 'heb', 'חַלָּה', '["challâh"]', '["and/ a cake of","and/ a round perforated bread of","and/ cakes of"]', '["n-f"]', 'a cake (as usually punctured) cake.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8081}/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["in <the>/ oil","in the/ oil","with <the>/ oil","with/ [the] oil of","with/ oil"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7550}/[H7556]', 'inflected', 'heb', 'רָקִיק', '["râqîyq"]', '["and/ a thin bread","and/ a wafer","and/ a wafer of","and/ thin breads of","and/ wafers of"]', '["n-m"]', 'a thin cake cake, wafer.', 'from, 7556 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7126H}/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["and/ he brought near","and/ he has brought near","and/ he presented","and/ he will bring [them] near","and/ he will bring near","and/ he will present","and/ it will bring near","and/ they brought near","and/ they presented","and/ they will present","and/ we have brought near","and/ you have brought near","and/ you will bring near","and/ you will bring yourselves near","and/ you will present"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5536}/[H5549]', 'inflected', 'heb', 'סַל', '["çal"]', '["[is] in the/ basket","[is] in/ [the] basket of","in the/ basket"]', '["n-m"]', 'properly, a willow twig (as pendulous), i.e. an osier; but only as woven into a basket basket.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6499}/[H6565]', 'inflected', 'heb', 'פַּר', '["par"]', '["the/ bull","the/ young bull","the/ young bulls"]', '["n-m"]', 'a bullock (apparently as breaking forth in wild strength, or perhaps as dividing the hoof) ( young) bull(-ock), calf, ox.', 'or פָּר; from 6565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0640}/[H646]', 'inflected', 'heb', 'אָפַד', '["ʼâphad"]', '["and/ he girded [the] ephod","and/ you will gird [the] ephod"]', '["v"]', 'to gird on (the ephod) bind, gird.', 'a primitive root [rather a denominative from 646];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2805}/[H2803]', 'inflected', 'heb', 'חֵשֶׁב', '["chêsheb"]', '["with/ [the] girdle of"]', '["n-m"]', 'a belt or strap (as being interlaced) curious girdle.', 'from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5145H}/[H5144]', 'lemma', 'heb', 'נֶזֶר', '["nezer"]', '["[the] consecration of","[the] crown of","a crown"]', '["n-m"]', 'properly, something set apart, i.e. (abstractly) dedication (of a priet or Nazirite); hence (concretely) unshorn locks; also (by implication) a chaplet (especially of royalty) consecration, crown, hair, separation.', 'or נֵזֶר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3847}/H9038/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["and/ he clothed/ them","and/ he will put on/ them","and/ they clothed/ them","and/ you will clothe with/ them","and/ you will clothe/ them"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2296}/[H2296]', 'inflected', 'heb', 'חָגַר', '["châgar"]', '["and/ he girded","and/ he girded on","and/ they girded","and/ they girded on","and/ they will gird themselves","and/ you girded on","and/ you will gird"]', '["v"]', 'to gird on (as a belt, armor, etc.) be able to put on, be afraid, appointed, gird, restrain, × on every side.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4021}/[H1389]', 'lemma', 'heb', 'מִגְבָּעָה', '["migbâʻâh"]', '["headdresses"]', '["n-f"]', 'a cap (as hemispherical) bonnet.', 'from the same as 1389;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3550}/[H3547]', 'lemma', 'heb', 'כְּהֻנָּה', '["kᵉhunnâh"]', '["[is] [the] priesthood of","priesthood","priesthood of"]', '["n-f"]', 'priesthood priesthood, priest''s office.', 'from 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2708}/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["<into>/ a statute of","to/ a statute of"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027R}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["[the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3027R}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5564}/[H5564]', 'inflected', 'heb', 'סָמַךְ', '["çâmak"]', '["and/ he laid","and/ he leaned","and/ he leans","and/ he supported himself","and/ he will lay","and/ he will lean","and/ they laid","and/ they leaned","and/ they supported themselves","and/ they will lay","and/ they will lean","and/ you will lay"]', '["v"]', 'to prop (literally or figuratively); reflexively, to lean upon or take hold of (in a favorable or unfavorable sense) bear up, establish, (up-) hold, lay, lean, lie hard, put, rest self, set self, stand fast, stay (self), sustain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1818}/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["from/ [the] blood of","from/ [the] blood<s> of","from/ blood","from/ blood<s>","some of/ [the] blood of"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7161A}/[H7160]', 'lemma', 'heb', 'קֶרֶן', '["qeren"]', '["<the> horn of","[the] horn of","[the] horns of","a horn","a horn of","horns","horns of","two horns"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0676}/H9021/[H6648]', 'inflected', 'heb', 'אֶצְבַּע', '["ʼetsbaʻ"]', '["with/ finger/ your"]', '["n-f"]', 'something to sieze with, i.e. a finger; by analogy, a toe finger, toe.', 'from the same as 6648 (in the sense of grasping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8210G}/[H8210]', 'lemma', 'heb', 'שָׁפַךְ', '["shâphak"]', '["I have been poured out","I have poured out","I pour out","I will pour out","[he is] pouring","[he was] pouring out","he has poured out","he pours out","he will pour out","it has been poured out","it pours itself out","it will be poured out","pour [it] out","pour out","poured out","they have poured out","was poured out","you have poured out","you will pour out"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3247H}/[H3245]', 'lemma', 'heb', 'יְסוֹד', '["yᵉçôwd"]', '["[is] a foundation of","[the] base of","foundation[s]"]', '["n-f"]', 'a foundation (literally or figuratively) bottom, foundation, repairing', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2459>', 'inflected', 'heb', 'החלבים', '["ha./Che.lev","ha./cha.la.Vim","ha./che.Lev"]', '["<the>/ fat<s>","the/ fat","the/ fat<s>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3680}/[H3680]', 'inflected', 'heb', 'כָּסָה', '["kâçâh"]', '["which/ covers","who/ covers"]', '["v"]', 'properly, to plump, i.e. fill up hollows; by implication, to cover (for clothing or secrecy) clad self, close, clothe, conceal, cover (self), (flee to) hide, overwhelm. Compare 3780.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7130H}/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["the/ entrails"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3508}/[H3498]', 'inflected', 'heb', 'יֹתֶרֶת', '["yôthereth"]', '["the/ lobe"]', '["n-f"]', 'the lobe or flap of the liver (as if redundant or outhanging) caul.', 'feminine active participle of 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3516}/[H3515]', 'inflected', 'heb', 'כָּבֵד', '["kâbêd"]', '["the/ liver"]', '["n-f"]', 'the liver (as the heaviest of the viscera) liver.', 'the same as 3515;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3629}/[H3627]', 'inflected', 'heb', 'כִּלְיָה', '["kilyâh"]', '["the/ kidneys"]', '["n-f"]', 'a kidney (as an essential organ); figuratively, the mind (as the interior self) kidneys, reins.', 'feminine of 3627 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9039/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["[is] on/ them","on/ them"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6999A}/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["and/ he made [it] smoke","and/ he made [them] smoke","and/ he made smoke","and/ he will make [it] smoke","and/ he will make smoke","and/ they will make smoke","and/ you will make [them] smoke","and/ you will make smoke"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4196}/H9011/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["the/ altar/ towards"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5785}/H9023/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["hide/ its","skin/ his"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6569}/H9023/[H6567]', 'inflected', 'heb', 'פֶּרֶשׁ', '["peresh"]', '["offal/ its"]', '["n-m"]', 'excrement (as eliminated) dung.', 'from 6567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403H}/[H2398]', 'lemma', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["[is] [the] sin offering of","[is] a sin offering","[the] sin offering of","a sin offering","sin offering","sin offerings"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5408}/[H5408]', 'lemma', 'heb', 'נָתַח', '["nâthach"]', '["he cut in pieces","you will cut in pieces"]', '["v"]', 'to dismember cut (in pieces), divide, hew in pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5409}/H9023/[H5408]', 'inflected', 'heb', 'נֵתַח', '["nêthach"]', '["into/ pieces/ its"]', '["n-m"]', 'a fragment part, piece.', 'from 5408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3767}/H9023/[H3766]', 'inflected', 'heb', 'כָּרָע', '["kârâʻ"]', '["and/ legs/ its"]', '["n-f"]', 'the leg (from the knee to the ankle) of men or locusts (only in the dual) leg.', 'from 3766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5409}/H9023/[H5408]', 'inflected', 'heb', 'נֵתַח', '["nêthach"]', '["pieces/ its"]', '["n-m"]', 'a fragment part, piece.', 'from 5408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5207}/[H5117]', 'lemma', 'heb', 'נִיחוֹחַ', '["nîychôwach"]', '["soothing"]', '["n-m"]', 'properly, restful, i.e. pleasant; abstractly, delight sweet (odour).', 'or נִיחֹחַ; from 5117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0801}/[H800]', 'lemma', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["[is] a fire offering","[the] fire offerings of","[was] a fire offering","a fire offering","a fire offering of"]', '["n-m"]', 'properly, a burnt-offering; but occasionally of any sacrifice (offering, sacrifice), (made) by fire.', 'the same as 800, but used in a liturgical sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1818}/H9023/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["some of/ blood/ its"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8571}/[H594]', 'lemma', 'heb', 'תְּנוּךְ', '["tᵉnûwk"]', '["[the] lobe of"]', '["n-m"]', 'a pinnacle, i.e. extremity tip.', 'perhaps from the same as 594 through the idea of protraction;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0241G}/[H238]', 'lemma', 'heb', 'אֹזֶן', '["ʼôzen"]', '["[the] ear","[the] ear of","an ear","ear","ears"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3233G}/[H3231]', 'inflected', 'heb', 'יְמָנִי', '["yᵉmânîy"]', '["<the>/ right"]', '["a"]', 'right (i.e. at the right hand) (on the) right (hand).', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0931>', 'opaque', 'heb', 'בֹּהֶן', '["bôhen"]', '["[the] big toe of","[the] thumb of","[the] thumbs of"]', '["n-f"]', 'the thumb of the hand or great toe of the foot thumb, great toe.', 'from an unused root apparently meaning to be thick;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8081}/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["and/ some of/ [the] oil of"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5137A}/[H5137]', 'inflected', 'heb', 'נָזָה', '["nâzâh"]', '["and/ he spattered","and/ he spattered [it]","and/ he will spatter","and/ he will spatter [it]","and/ it spattered","and/ you will spatter [it]"]', '["v"]', 'to spirt, i.e. besprinkle (especially in expiation) sprinkle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0899B}/H9023/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["and/ garments/ his"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0451}/[H422]', 'inflected', 'heb', 'אַלְיָה', '["ʼalyâh"]', '["and/ the/ fat tail"]', '["n-f"]', 'the stout part, i.e. the fat tail of the Oriental sheep rump.', 'from 422 (in the original sense of strength);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3508}/[H3498]', 'lemma', 'heb', 'יֹתֶרֶת', '["yôthereth"]', '["[the] lobe of"]', '["n-f"]', 'the lobe or flap of the liver (as if redundant or outhanging) caul.', 'feminine active participle of 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7785}/[H7783]', 'lemma', 'heb', 'שׁוֹק', '["shôwq"]', '["[the] thigh of","a leg","leg","legs"]', '["n-f"]', 'the (lower) leg (as a runner) hip, leg, shoulder, thigh.', 'from 7783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3603H}/[H3769]', 'inflected', 'heb', 'כִּכָּר', '["kikkâr"]', '["and/ a round loaf of","and/ a talent of"]', '["n-f"]', 'a circle, i.e. (by implication) a circumjacent tract or region, especially the Ghor or valley of the Jordan; also a (round) loaf; also a talent (or large [round] coin) loaf, morsel, piece, plain, talent.', 'from 3769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5536}/[H5549]', 'inflected', 'heb', 'סַל', '["çal"]', '["from/ [the] basket of"]', '["n-m"]', 'properly, a willow twig (as pendulous), i.e. an osier; but only as woven into a basket basket.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3605}/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["<of the>/ everything","<the>/ all","<the>/ anything","<the>/ every one","<the>/ everyone","<the>/ everything","[are] <the>/ all","the/ whole"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5130B}/[H5130]', 'inflected', 'heb', 'נוּף', '["nûwph"]', '["and/ he waved","and/ he will brandish","and/ he will wave","and/ you will wave"]', '["v"]', 'to quiver (i.e. vibrate up and down, or rock to and fro); used in a great variety of applications (including sprinkling, beckoning, rubbing, bastinadoing, sawing, waving, etc.) lift up, move, offer, perfume, send, shake, sift, strike, wave.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8573}/[H5130]', 'lemma', 'heb', 'תְּנוּפָה', '["tᵉnûwphâh"]', '["[the] brandishing of","[the] wave-offerings of","a wave-offering","a wave-offering of","brandishing"]', '["n-f"]', 'a brandishing (in threat); by implication, tumult; specifically, the official undulation of sacrificial offerings offering, shaking, wave (offering).', 'from 5130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7381}/[H7306]', 'inflected', 'heb', 'רֵיחַ', '["rêyach"]', '["to/ an odor of","to/ odor"]', '["n-m"]', 'odor (as if blown) savour, scent, smell.', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2373}/[H2372]', 'inflected', 'heb', 'חָזֶה', '["châzeh"]', '["the/ breast","the/ breasts"]', '["n-m"]', 'the breast (as most seen in front) breast.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0352A}/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["from/ [the] ram of"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4394}/[H4390]', 'inflected', 'heb', 'מִלֻּא', '["milluʼ"]', '["<the>/ installation offering<s>","the/ installation offering<s>","the/ setting<s>"]', '["n-m"]', 'a fulfilling (only in plural), i.e. (literally) a setting (of gems), or (technically) consecration (also concretely, a dedicatory sacrifice) consecration, be set.', 'from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4490}/[H4487]', 'inflected', 'heb', 'מָנָה', '["mânâh"]', '["to/ a portion"]', '["n-f"]', 'properly, something weighed out, i.e. (generally) a division; specifically (of food) a ration; also a lot such things as belonged, part, portion.', 'from 4487;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2373}/[H2372]', 'lemma', 'heb', 'חָזֶה', '["châzeh"]', '["[the] breast of"]', '["n-m"]', 'the breast (as most seen in front) breast.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8573}/[H5130]', 'inflected', 'heb', 'תְּנוּפָה', '["tᵉnûwphâh"]', '["the/ wave-offering"]', '["n-f"]', 'a brandishing (in threat); by implication, tumult; specifically, the official undulation of sacrificial offerings offering, shaking, wave (offering).', 'from 5130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2706H}/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["to/ a prescribed portion of"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8641}/[H7311]', 'inflected', 'heb', 'תְּרוּמָה', '["tᵉrûwmâh"]', '["and/ [the] contribution of","and/ a contribution"]', '["n-f"]', 'a present (as offered up), especially in sacrifice or as tribute gift, heave offering (shoulder), oblation, offered(-ing).', 'or תְּרֻמָה; (Deuteronomy 12:11), from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2077}/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["from/ [the] sacrifice of","from/ [the] sacrifices of","more than/ sacrifice"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8002}/H9028/[H7999]', 'inflected', 'heb', 'שֶׁלֶם', '["shelem"]', '["peace offerings/ their"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8641}/H9028/[H7311]', 'inflected', 'heb', 'תְּרוּמָה', '["tᵉrûwmâh"]', '["contribution/ their"]', '["n-f"]', 'a present (as offered up), especially in sacrifice or as tribute gift, heave offering (shoulder), oblation, offered(-ing).', 'or תְּרֻמָה; (Deuteronomy 12:11), from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4888A}/[H4886]', 'inflected', 'heb', 'מִשְׁחָה', '["mishchâh"]', '["for/ anointing"]', '["n-f"]', 'unction (the act); by implication, a consecratory gift (to be) anointed(-ing), ointment.', 'or מׇשְׁחָה; from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4390}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["and/ to/ fill"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3847}/H9038/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["he will wear/ them"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1121A}/H9023/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["from/ sons/ his","of/ sons/ his","one of/ sons/ his"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1310}/[H1310]', 'inflected', 'heb', 'בָּשַׁל', '["bâshal"]', '["and/ she cooked","and/ they boiled","and/ they cooked","and/ they will boil","and/ we cooked","and/ you will boil","and/ you will cook [it]"]', '["v"]', 'properly, to boil up; hence, to be done in cooking; figuratively to ripen bake, boil, bring forth, roast, seethe, sod (be sodden).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4390}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["[about] to/ fill","to/ complete","to/ fill","to/ fulfill"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2114A}/[H2114]', 'inflected', 'heb', 'זוּר', '["zûwr"]', '["and/ a stranger"]', '["v"]', 'to turn aside (especially for lodging); hence to be a foreigner, strange, profane; specifically (active participle) to commit adultery (come from) another (man, place), fanner, go away, (e-) strange(-r, thing, woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1320}/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["any of/ [the] flesh of","any of/ [the] meat of","of/ [the] meat of","some of/ [the] meat of"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8313}/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["and/ I burned","and/ he burned","and/ he burned [it]","and/ he burned [them]","and/ he will burn","and/ people will burn","and/ they burned","and/ they had burned","and/ they were burned","and/ they will burn","and/ you will burn"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3602}/[H3541]', 'lemma', 'heb', 'כָּכָה', '["kâkâh"]', '["thus"]', '["adv"]', 'just so, referring to the previous or following context after that (this) manner, this matter, (even) so, in such a case, thus.', 'from 3541;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3725}/[H3722]', 'inflected', 'heb', 'כִּפֻּר', '["kippur"]', '["<the>/ atonement<s>"]', '["n-m"]', 'expiation (only in plural) atonement.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3722A}/H9041/[H3722]', 'inflected', 'heb', 'כָּפַר', '["kâphar"]', '["when/ making atonement/ you"]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942G}\/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["he will be holy","it will be holy"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3532>', 'opaque', 'heb', 'כֶּבֶשׂ', '["kebes"]', '["[the] male lamb of","a lamb","a male lamb","lamb","lambs","male lambs"]', '["n-m"]', 'a ram (just old enough to butt) lamb, sheep.', 'from an unused root meaning to dominate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3117J>', 'inflected', 'heb', 'ליום', '["la/i.Yom","la/i.yOm","le./Yom"]', '["for the/ day","to the/ day","to/ a day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6241}/[H6235]', 'inflected', 'heb', 'עִשָּׂרוֹן', '["ʻissârôwn"]', '["and/ a tenth","and/ a tenth [of an ephah]","and/ a tenth of"]', '["n-m"]', '(fractional) a tenth part tenth deal.', 'or עִשָּׂרֹן; from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7253}/[H7251]', 'lemma', 'heb', 'רֶבַע', '["rebaʻ"]', '["<the> fourth part of","a fourth part of"]', '["n-m"]', 'a fourth (part or side) fourth part, side, square.', 'from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1969}/[H1969]', 'inflected', 'heb', 'הִין', '["hîyn"]', '["<the>/ hin"]', '["n-m"]', 'a hin or liquid measure hin.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5262}/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ a drink offering","and/ drink offerings"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3532>', 'inflected', 'heb', 'לכבש', '["la./Ke.ves"]', '["for the/ lamb"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H4503G>', 'inflected', 'heb', 'כמנחת', '["ke./min.Chat"]', '["like/ [the] grain offering of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5262}/H9024/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ like/ drink offering/ its"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3259}/[H3259]', 'lemma', 'heb', 'יָעַד', '["yâʻad"]', '["I meet","I will meet","[were] set","let us meet","set","they assembled","they have met by appointment"]', '["v"]', 'to fix upon (by agreement or appointment); by implication, to meet (at a stated time), to summon (to trial), to direct (in a certain quarter or position), to engage (for marriage) agree,(maxke an) appoint(-ment, a time), assemble (selves), betroth, gather (selves, together), meet (together), set (a time).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3519}/H9020/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["by/ glory/ my"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7931}/H9030/[H7901]', 'inflected', 'heb', 'שָׁכַן', '["shâkan"]', '["to/ dwell/ I"]', '["v"]', 'to reside or permanently stay (literally or figuratively) abide, continue, (cause to, make to) dwell(-er), have habitation, inhabit, lay, place, (cause to) remain, rest, set (up).', 'a primitive root (apparently akin (by transmission) to 7901 through the idea of lodging; compare 5531, 7925);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9028\/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ their"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4729}/[H6999]', 'lemma', 'heb', 'מִקְטָר', '["miqṭâr"]', '["a place of smoke of"]', '["n-m"]', 'something to fume (incense) on i.e. a hearth place to burn...upon.', 'from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7004}/[H6999]', 'lemma', 'heb', 'קְטֹרֶת', '["qᵉṭôreth"]', '["[the] incense of","[the] smoke of","incense","incense of"]', '["n-f"]', 'a fumigation (sweet) incense, perfume.', 'from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1406}/H9023/[H1342]', 'inflected', 'heb', 'גָּג', '["gâg"]', '["own roof/ his","top/ its"]', '["n-m"]', 'a roof; by analogy, the top of an altar roof (of the house), (house) top (of the house).', 'probably by reduplication from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7023}/H9023/[H6979]', 'inflected', 'heb', 'קִיר', '["qîyr"]', '["sides/ its"]', '["n-m"]', 'a wall (as built in a trench) mason, side, town, × very, wall.', 'or קִר; (Isaiah 22:5), or (feminine) קִירָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2213}/H9023/[H2237]', 'inflected', 'heb', 'זֵר', '["zêr"]', '["to/ molding/ its"]', '["n-m"]', 'a chaplet (as spread around the top), i.e. (specifically) a border moulding crown.', 'from 2237 (in the sense of scattering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6654>/H9023', 'opaque', 'heb', 'צַד', '["tsad"]', '["sides/ its"]', '["n-m"]', 'a side; figuratively, an adversary (be-) side.', 'contr. from an unused root meaning to sidle off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5561>', 'opaque', 'heb', 'סַם', '["çam"]', '["perfume<s>","spices"]', '["n-m"]', 'an aroma sweet (spice).', 'from an unused root meaning to smell sweet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3190}/H9043/[H3190]', 'inflected', 'heb', 'יָטַב', '["yâṭab"]', '["when/ makes good/ he"]', '["v"]', 'to be (causative) make well, literally (sound, beautiful) or figuratively (happy, successful, right) be accepted, amend, use aright, benefit, be (make) better, seem best, make cheerful, be comely, be content, diligent(-ly), dress, earnestly, find favour, give, be glad, do (be, make) good(-ness), be (make) merry, please ( well), shew more (kindness), skilfully, × very small, surely, make sweet, thoroughly, tire, trim, very, be (can, deal, entreat, go, have) well (said, seen).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5216A}/[H5214]', 'inflected', 'heb', 'נִיר', '["nîyr"]', '["the/ lamps"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6999A}/H9034/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["he will make smoke/ it"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5927H}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ when/ lifts up","and/ when/ was taken up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927I}/[H5927]', 'lemma', 'heb', 'עָלָה', '["ʻâlâh"]', '["I will offer up","[one who] offers up","[who] offers up","ering up of","he had brought up","he offered up","he went up","he will offer up","it had been offered up","offering up","people will offer up","they offered up","they will go up","they will offer up","you must offer up","you should offer up","you will offer up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2114A}/[H2114]', 'lemma', 'heb', 'זוּר', '["zûwr"]', '["[is] strange","[was] a strange [god]","[was] a stranger","a strange [thing]","a strange [woman]","a stranger","estranged","strange","strange [gods]","strange [things]","strange [women]","stranger","strangers","they had become estranged","they have become estranged","they turn aside"]', '["v"]', 'to turn aside (especially for lodging); hence to be a foreigner, strange, profane; specifically (active participle) to commit adultery (come from) another (man, place), fanner, go away, (e-) strange(-r, thing, woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4503G>', 'inflected', 'heb', 'ומנחה', '["u./min.Chah","u./min.Chat"]', '["and/ [the] grain offering of","and/ a grain offering","and/ an offering","and/ grain offering","and/ grain offering[s]","and/ offering"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3722A}/[H3722]', 'inflected', 'heb', 'כָּפַר', '["kâphar"]', '["and/ he has made atonement","and/ he made atonement","and/ he will make atonement","and/ he will make atonement for","and/ it will be annulled","and/ it will be atoned for","and/ you will make atonement for"]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375V}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["he took","lift up","they have lifted up","you will lift up","you will take"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218L>', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["[the] head of","[the] sum of"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6485A}/H9028/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["of/ enrolled [men]/ them","to/ [men] enrolled/ their","to/ enrolled [men]/ their"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6485A}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["when/ enroll"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5674A}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["<the>/ [one who] passed over","<the>/ [one who] passes over","[is] the/ [one who] is about to pass over","those/ [who] pass","those/ [who] pass by","those/ [who] pass through","who/ passed"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6485A}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["[were] the/ enrolled [men]","the/ enrolled [men]","those/ [who] are enrolled","those/ [who] were enrolled","those/ enrolled"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4276}/[H2673]', 'lemma', 'heb', 'מַחֲצִית', '["machătsîyth"]', '["<the> half of","[the] half of","[the] middle of"]', '["n-f"]', 'a halving or the middle half (so much), mid(-day).', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8255}/[H8254]', 'inflected', 'heb', 'שֶׁקֶל', '["sheqel"]', '["the/ shekel"]', '["n-m"]', 'probably a weight; used as a commercial standard shekel.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8255}/[H8254]', 'inflected', 'heb', 'שֶׁקֶל', '["sheqel"]', '["by/ [the] shekel of","for/ a shekel"]', '["n-m"]', 'probably a weight; used as a commercial standard shekel.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1626}/[H1641]', 'lemma', 'heb', 'גֵּרָה', '["gêrâh"]', '["gerah[s]"]', '["n-f"]', 'a gerah or small weight (and coin) gerah.', 'from 1641 (as in 1625); properly, (like 1620) a kernel (round as if scraped), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1121L}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["from/ a son of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4605}/H9011/[H5927]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["and/ on/ -wards","and/ up/ -wards"]', '["adv"]', 'properly,the upper part, used only adverbially with prefix upward, above, overhead, from the top, etc. above, exceeding(-ly), forward, on (× very) high, over, up(-on, -ward), very.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6223}/[H6238]', 'inflected', 'heb', 'עָשִׁיר', '["ʻâshîyr"]', '["<the>/ rich","the/ rich [person]"]', '["n-m"]', 'rich, whether literal or figurative (noble) rich (man).', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1800}/[H1809]', 'inflected', 'heb', 'דַּל', '["dal"]', '["and/ the/ poor [person]"]', '["a"]', 'properly, dangling, i.e. (by implication) weak or thin lean, needy, poor (man), weaker.', 'from 1809;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4276}/[H2673]', 'inflected', 'heb', 'מַחֲצִית', '["machătsîyth"]', '["from/ [the] half of","more than/ [the] half of"]', '["n-f"]', 'a halving or the middle half (so much), mid(-day).', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3722A}/[H3722]', 'inflected', 'heb', 'כָּפַר', '["kâphar"]', '["to/ make atonement"]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315H}/H9026/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["life/ your","selves/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5656H}/[H5647]', 'lemma', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["[is] [the] service of","[the] service of","a service","a service of","service"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315H}/H9026\/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["selves/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3595}/[H3564]', 'lemma', 'heb', 'כִּיּוֹר', '["kîyôwr"]', '["a laver","a laver of","a platform of","lavers"]', '["n-m"]', 'properly, something round (as excavated or bored), i.e. a chafing-dish for coals or a caldron for cooking; hence (from similarity of form) a washbowl; also (for the same reason) a pulpit or platform hearth, laver, pan, scaffold.', 'or כִּיֹּר; from the same as 3564;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3653}/H9023/[H3651]', 'inflected', 'heb', 'כֵּן', '["kên"]', '["and/ base of/ its"]', '["n-m"]', 'a stand, i.e. pedestal or station base, estate, foot, office, place, well.', 'the same as 3651, used as a noun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7364}/[H7364]', 'lemma', 'heb', 'רָחַץ', '["râchats"]', '["I have washed","I wash","I washed myself","bathing","he has washed","he has washed away","he washed","he will bathe","he will wash","it has been washed","they bathed","they washed","they will wash","wash","washing","will I wash","you bathed","you were washed"]', '["v"]', 'to lave (the whole or a part of a thing) bathe (self), wash (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6999A}/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["to/ make smoke"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7272}/H9028/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["and/ feet/ their"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4753}/[H4843]', 'lemma', 'heb', 'מֹר', '["môr"]', '["[are] myrrh","myrrh","myrrh of"]', '["n-m"]', 'myrrh (as distilling in drops, and also as bitter) myrrh.', 'or מוֹר; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1865>', 'opaque', 'heb', 'דְּרוֹר', '["dᵉrôwr"]', '["flowing","liberty"]', '["n-m"]', 'freedom; hence, spontaneity of outflow, and so clear liberty, pure.', 'from an unused root (meaning to move rapidly);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7076>', 'inflected', 'heb', 'וקנמון', '["ve./ki.na.Mon","ve./ki.ne.mon"]', '["and/ cinnamon","and/ cinnamon of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4276}/H9023/[H2673]', 'inflected', 'heb', 'מַחֲצִית', '["machătsîyth"]', '["half/ its"]', '["n-f"]', 'a halving or the middle half (so much), mid(-day).', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7070H}/[H7069]', 'inflected', 'heb', 'קָנֶה', '["qâneh"]', '["and/ [the] cane","and/ [the] reed of","and/ a reed","and/ cane of"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6916}/[H6915]', 'inflected', 'heb', 'קִדָּה', '["qiddâh"]', '["and/ cassia"]', '["n-f"]', 'cassia bark (as in shrivelled rolls) cassia.', 'from 6915;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8081}/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["and/ [the] oil of","and/ oil","and/ oil of"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1969}/[H1969]', 'lemma', 'heb', 'הִין', '["hîyn"]', '["a hin"]', '["n-m"]', 'a hin or liquid measure hin.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4888A}/[H4886]', 'lemma', 'heb', 'מִשְׁחָה', '["mishchâh"]', '["<the> anointing of","[is] [the] share of","[the] anointing of","anointing of"]', '["n-f"]', 'unction (the act); by implication, a consecratory gift (to be) anointed(-ing), ointment.', 'or מׇשְׁחָה; from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7545}/[H7543]', 'lemma', 'heb', 'רֹקַח', '["rôqach"]', '["perfume","perfume of"]', '["n-m"]', 'an aromatic confection, ointment.', 'from 7543;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4842}/[H7543]', 'lemma', 'heb', 'מִרְקַחַת', '["mirqachath"]', '["an ointment-pot"]', '["n-f"]', 'an aromatic unguent; also an unguent-pot prepared by the apothecaries'' art, compound, ointment.', 'from 7543;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7543}/[H7543]', 'lemma', 'heb', 'רָקַח', '["râqach"]', '["[were those who] mixed","a perfumer","he will mix","mixed"]', '["v"]', 'to perfume apothecary, compound, make (ointment), prepare, spice.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3627}/H9024/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["articles/ its","equipment<s>/ its","ornaments/ her"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7004}/[H6999]', 'inflected', 'heb', 'קְטֹרֶת', '["qᵉṭôreth"]', '["<the>/ incense","the/ incense"]', '["n-f"]', 'a fumigation (sweet) incense, perfume.', 'from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3595}/[H3564]', 'inflected', 'heb', 'כִּיּוֹר', '["kîyôwr"]', '["the/ laver","the/ lavers"]', '["n-m"]', 'properly, something round (as excavated or bored), i.e. a chafing-dish for coals or a caldron for cooking; hence (from similarity of form) a washbowl; also (for the same reason) a pulpit or platform hearth, laver, pan, scaffold.', 'or כִּיֹּר; from the same as 3564;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3653}/H9023/[H3651]', 'inflected', 'heb', 'כֵּן', '["kên"]', '["base/ its","place/ his","place/ its"]', '["n-m"]', 'a stand, i.e. pedestal or station base, estate, foot, office, place, well.', 'the same as 3651, used as a noun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3251}/[H3251]', 'lemma', 'heb', 'יָסַךְ', '["yâçak"]', '["it will be poured"]', '["v"]', 'to pour (intransitive) be poured.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4971}/H9023/[H8505]', 'inflected', 'heb', 'מַתְכֹנֶת', '["mathkôneth"]', '["and/ in/ proportion[s]/ its"]', '["n-f"]', 'proportion (in size, number or ingredients) composition, measure, state, tale.', 'or מַתְכֻנֶת; from 8505 in the transferred sense of measuring;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5971A}/H9023\/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["from/ kinspeople<s>/ his"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5198B}/[H5197]', 'lemma', 'heb', 'נָטָף', '["nâṭâph"]', '["stacte"]', '["n-m"]', 'a drop; specifically, an aromatic gum (probably stacte) drop, stacte.', 'from 5197;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7827}/[H7826]', 'inflected', 'heb', 'שְׁחֵלֶת', '["shᵉchêleth"]', '["and/ onycha"]', '["n-f"]', 'a scale or shell, i.e. the aromatic mussel. onycha.', 'apparently from the same as 7826 through some obscure idea, perhaps that of peeling off by concussion of sound;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2464}/[H2459]', 'inflected', 'heb', 'חֶלְבְּנָה', '["chelbᵉnâh"]', '["and/ galbanum"]', '["n-f"]', 'galbanam, an odorous gum (as if fatty) galbanum.', 'from 2459;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3828}/[H3836]', 'inflected', 'heb', 'לְבוֹנָה', '["lᵉbôwnâh"]', '["and/ frankincense"]', '["n-f"]', 'frankincense (from its whiteness or perhaps that of its smoke) (frank-) incense.', 'or לְבֹנָה; from 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0905I}/[H909]', 'lemma', 'heb', 'בַּד', '["bad"]', '["a part"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0905I}/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["in/ a part"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4414B}/[H4417]', 'lemma', 'heb', 'מָלַח', '["mâlach"]', '["salted","you were rubbed with salt","you will salt"]', '["v"]', 'properly, to rub to pieces or pulverize; intransitively, to disappear as dust; also to salt whether internally (to season with salt) or externally (to rub with salt) × at all, salt, season, temper together, vanish away.', 'a primitive root; also as denominative from 4417');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7833}/[H7833]', 'inflected', 'heb', 'שָׁחַק', '["shâchaq"]', '["and/ you will beat fine"]', '["v"]', 'to comminate (by trituration or attrition) beat, wear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1854}/[H1915]', 'lemma', 'heb', 'דָּקַק', '["dâqaq"]', '["finely <pulverize>","he crushed [it]","it is crushed","it was fine"]', '["v"]', 'to crush (or intransitively) crumble beat in pieces (small), bruise, make dust, (into) × powder, (be, very) small, stamp (small).', 'a primitive root (compare 1915);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7004}/[H6999]', 'inflected', 'heb', 'קְטֹרֶת', '["qᵉṭôreth"]', '["and/ the/ incense"]', '["n-f"]', 'a fumigation (sweet) incense, perfume.', 'from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4971}/H9024/[H8505]', 'inflected', 'heb', 'מַתְכֹנֶת', '["mathkôneth"]', '["in/ proportion[s]/ its"]', '["n-f"]', 'proportion (in size, number or ingredients) composition, measure, state, tale.', 'or מַתְכֻנֶת; from 8505 in the transferred sense of measuring;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3644G}/H9034/[H3651]', 'inflected', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["[is] like/ it","according to/ it","like/ it"]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7306}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["to/ smell"]', '["v"]', 'properly, to blow, i.e. breathe; only (literally) to smell or (by implication, perceive (figuratively, to anticipate, enjoy) accept, smell, × touch, make of quick understanding.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1212G}/[H6738]', 'lemma', 'heb', 'בְּצַלְאֵל', '["Bᵉtsalʼêl"]', '["Bezalel"]', '["n-pr-m"]', 'Betsalel, the name of two Israelites Bezaleel.', 'probably from 6738 and 410 with a prepositional prefix; in (the) shadow (i.e. protection) of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0221G}/[H217]', 'lemma', 'heb', 'אוּרִי', '["ʼÛwrîy"]', '["Uri"]', '["n-pr-m"]', 'Uri, the name of three Israelites Uri.', 'from 217; fiery;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2354G}/[H2353]', 'lemma', 'heb', 'חוּר', '["Chûwr"]', '["Hur"]', '["n-pr-m"]', 'Chur, the name of four Israelites and one Midianite Hur.', 'the same as 2353 or 2352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4294H}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["for/ [the] tribe of","of/ [the] tribe of","of/ [the] tribes of","to the/ tribe","to/ [the] tribe of","to/ [the] tribes of","to/ tribe"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2451}/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["[was] with/ wisdom","by <the>/ wisdom","by/ wisdom","in/ wisdom","with <the>/ skill","with <the>/ wisdom","with/ skill","with/ wisdom"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8394}/[H995]', 'inflected', 'heb', 'תָּבוּן', '["tâbûwn"]', '["and/ by/ understanding","and/ with/ [the] skill of","and/ with/ understanding"]', '["n-m"]', 'intelligence; by implication, an argument; by extension, caprice discretion, reason, skilfulness, understanding, wisdom.', 'and (feminine) תְּבוּנָה; or תּוֹבֻנָה; from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1847}/[H3045]', 'inflected', 'heb', 'דַּעַת', '["daʻath"]', '["and/ by/ knowledge","and/ with/ knowledge"]', '["n"]', 'knowledge cunning, (ig-) norantly, know(-ledge), (un-) awares (wittingly).', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2803G}/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["to/ design"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2091>', 'inflected', 'heb', 'בזהב', '["ba./za.Hav","ba./za.hov","be./za.Hav"]', '["in <the>/ gold","with <the>/ gold","with/ gold"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3701G}/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["and/ in <the>/ silver","and/ with/ silver"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5178A}/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["and/ in <the>/ bronze","and/ with/ bronze"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2799}/[H2790]', 'inflected', 'heb', 'חֲרֹשֶׁת', '["chărôsheth"]', '["and/ in/ carving of"]', '["n-f"]', 'mechanical work carving, cutting.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0171}/[H168]', 'lemma', 'heb', 'אׇהֳלִיאָב', '["ʼOhŏlîyʼâb"]', '["Oholiab"]', '["n-pr-m"]', 'Oholiab, an Israelite Aholiab.', 'from 168 and 1; tent of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0294}/[H251]', 'lemma', 'heb', 'אֲחִיסָמָךְ', '["ʼĂchîyçâmâk"]', '["Ahisamach"]', '["n-pr-m"]', 'Achisamak, an Israelite Ahisamach.', 'from 251 and 5564; brother of support;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3820A}/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["and/ in/ [the] heart of","and/ with/ a heart"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5715}/[H5707]', 'inflected', 'heb', 'עֵדוּת', '["ʻêdûwth"]', '["of the/ testimony"]', '["n-f"]', 'testimony testimony, witness.', 'feminine of 5707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8278}/[H8277]', 'inflected', 'heb', 'שְׂרָד', '["sᵉrâd"]', '["the/ woven material"]', '["n-m"]', 'stitching (as pierced with a needle) service.', 'from 8277;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6944J}/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["for the/ holy place"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7676}/H9020/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["sabbaths/ my"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942G}/H9036/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["[who] sets apart as holy/ you","[who] sets apart/ you"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2490H}/H9034/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["[those who] profane/ it"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7130G}/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["from/ [the] midst","from/ [the] midst of","from/ among"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971B}/H9024/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["kinspeople<s>/ its","people/ its"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5314}\/[H5314]', 'inflected', 'heb', 'נָפַשׁ', '["nâphash"]', '["and/ he refreshed himself"]', '["v"]', 'to breathe; passively, to be breathed upon , i.e. (figuratively) refreshed (as if by a current of air) (be) refresh selves (-ed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3615G}/H9043/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["when/ finished/ he"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0676}/[H6648]', 'inflected', 'heb', 'אֶצְבַּע', '["ʼetsbaʻ"]', '["by/ [the] finger of"]', '["n-f"]', 'something to sieze with, i.e. a finger; by analogy, a toe finger, toe.', 'from the same as 6648 (in the sense of grasping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6950}/[H6950]', 'inflected', 'heb', 'קָהַל', '["qâhal"]', '["and/ he assembled","and/ he called together","and/ it assembled","and/ it was assembled","and/ they assembled","and/ they made assemble","and/ you will assemble"]', '["v"]', 'to convoke assemble (selves) (together), gather (selves) (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440G}/H9025/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ us","[is] <to>/ before/ us"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6561}/[H6561]', 'lemma', 'heb', 'פָּרַק', '["pâraq"]', '["[is one who] rescues","[was] tearing","tear [it] off from yourselves","tear off","tearing","they were torn off"]', '["v"]', 'to break off or crunch; figuratively, to deliver break (off), deliver, redeem, rend (in pieces), tear in pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1323G}/H9026/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ daughters/ your"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027I}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6696C}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["and/ he fashioned"]', '["v"]', 'to cramp, i.e. confine (in many applications, literally and figuratively, formative or hostile) adversary, assault, beset, besiege, bind (up), cast, distress, fashion, fortify, inclose, lay siege, put up in bags.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2747}/[H2747]', 'inflected', 'heb', 'חֶרֶט', '["chereṭ"]', '["with <the>/ tool","with/ a stylus of"]', '["n-m"]', 'a chisel or graver; also a style for writing graving tool, pen.', 'from a primitive root meaning to engrave;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6213H}/H9033/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ I will prepare/ it","and/ he made/ it","and/ someone made/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5695}/[H5696]', 'lemma', 'heb', 'עֵגֶל', '["ʻêgel"]', '["[the] calf of","[the] calves of","[the] male calf of","a calf","a calf of","a male calf","calves","calves of"]', '["n-m"]', 'a (male) calf (as frisking round), especially one nearly grown (i.e. a steer) bullock, calf.', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4541A}/[H5258]', 'lemma', 'heb', 'מַסֵּכָה', '["maççêkâh"]', '["[the] molten image of","a libation","a molten image","molten images","molten metal"]', '["n-f"]', 'properly, a pouring over, i.e. fusion of metal (especially a cast image); by implication, a libation, i.e. league; concretely a coverlet (as if poured out) covering, molten (image), vail.', 'from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6711}\/[H6711]', 'inflected', 'heb', 'צָחַק', '["tsâchaq"]', '["to/ play"]', '["v"]', 'to laugh outright (in merriment or scorn); by implication, to sport laugh, mock, play, make sport.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4118B}/[H4116]', 'lemma', 'heb', 'מַהֵר', '["mahêr"]', '["quickly"]', '["a adv"]', 'properly, hurrying; hence (adverbially) in a hurry hasteth, hastily, at once, quickly, soon, speedily, suddenly.', 'from 4116;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5117}/H9012/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["leave alone/ !","permit/ !"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2734}/[H2787]', 'inflected', 'heb', 'חָרָה', '["chârâh"]', '["so/ may it burn"]', '["v"]', 'to glow or grow warm; figuratively (usually) to blaze up, of anger, zeal, jealousy be angry, burn, be displeased, × earnestly, fret self, grieve, be (wax) hot, be incensed, kindle, × very, be wroth. See 8474.', 'a primitive root (compare 2787);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3615H}/H9038/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["so/ I may make an end of/ them"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2470B}/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["and/ did he entreat","and/ he entreated","and/ they will entreat"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9023/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["<of> God/ its","God/ his","God/ its","[is] God/ its","god/ his","own god/ his"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3615H}/H9038/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["and/ to/ make an end of/ them"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2740}/[H2734]', 'inflected', 'heb', 'חָרוֹן', '["chârôwn"]', '["from/ [the] burning of"]', '["n-m"]', 'a burning of anger sore displeasure, fierce(-ness), fury, (fierce) wrath(-ful).', 'or (shortened) חָרֹן; from 2734;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5162H}/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["and/ [who] relents","and/ relent","so/ he may change his mind","so/ he may repent"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5971A}/H9021/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["<to>/ people/ your","for/ people/ your","to/ people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2233H}/H9026/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["to/ offspring/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5971A}/H9023\/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["to/ people/ his"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5676G}/H9028/[H5674]', 'inflected', 'heb', 'עֵבֶר', '["ʻêber"]', '["sides/ their"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3871}/[H3871]', 'inflected', 'heb', 'לוּחַ', '["lûwach"]', '["and/ the/ tablets"]', '["n-m"]', 'probably meaning to glisten; a tablet (as polished), of stone, wood or metal board, plate, table.', 'or לֻחַ; from a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4385}/[H3789]', 'inflected', 'heb', 'מִכְתָּב', '["miktâb"]', '["and/ the/ writing"]', '["n-m"]', 'a thing written, the characters, or a document (letter, copy, edict, poem) writing.', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4385}/[H3789]', 'lemma', 'heb', 'מִכְתָּב', '["miktâb"]', '["[was] [the] writing of","a writing","an inscription of"]', '["n-m"]', 'a thing written, the characters, or a document (letter, copy, edict, poem) writing.', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2801}/[H2801]', 'lemma', 'heb', 'חָרַת', '["chârath"]', '["engraved"]', '["v"]', 'to engrave graven.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3871}/[H3871]', 'inflected', 'heb', 'לוּחַ', '["lûwach"]', '["the/ plates of","the/ tablets"]', '["n-m"]', 'probably meaning to glisten; a tablet (as polished), of stone, wood or metal board, plate, table.', 'or לֻחַ; from a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7452}/H9023/[H7321]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["in/ shouting/ its"]', '["n"]', 'a crash (of thunder), noise (of war), shout (of joy) × aloud, noise, shouted.', 'from 7321;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6030C}/[H6030]', 'lemma', 'heb', 'עָנָה', '["ʻânâh"]', '["do people sing","he will sing","may it sing","people sing","sing","singing","singing of"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1369}/[H1368]', 'lemma', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["[the] mighty deeds of","strength","strength<s>"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2476}/[H2522]', 'lemma', 'heb', 'חֲלוּשָׁה', '["chălûwshâh"]', '["weakness"]', '["n-f"]', 'defeat being overcome.', 'feminine passive participle of 2522;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5695}/[H5696]', 'inflected', 'heb', 'עֵגֶל', '["ʻêgel"]', '["the/ calf"]', '["n-m"]', 'a (male) calf (as frisking round), especially one nearly grown (i.e. a steer) bullock, calf.', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4246}/[H4234]', 'inflected', 'heb', 'מְחֹלָה', '["mᵉchôlâh"]', '["and/ dancing"]', '["n-f"]', 'a dance company, dances(-cing).', 'feminine of 4234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027G}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ his","from/ hands/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2912}/[H2912]', 'inflected', 'heb', 'טָחַן', '["ṭâchan"]', '["and/ he ground [it]","and/ they ground"]', '["v"]', 'to grind meal; hence, to be a concubine (that being their employment) grind(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2219}/[H2114]', 'inflected', 'heb', 'זָרָה', '["zârâh"]', '["and/ I will disperse","and/ I will spread","and/ he scattered [it]","and/ they were dispersed"]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6544B}/H9033/[H6544]', 'inflected', 'heb', 'פָּרַע', '["pâraʻ"]', '["avoid/ it","had let [it] run wild/ he"]', '["v"]', 'to loosen; by implication, to expose, dismiss; figuratively, absolve, begin avenge, avoid, bare, go back, let, (make) naked, set at nought, perish, refuse, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8103}/[H8102]', 'inflected', 'heb', 'שִׁמְצָה', '["shimtsâh"]', '["for/ derision"]', '["n-f"]', 'scornful whispering (of hostile spectators) shame.', 'feminine of 8102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6965J}/H9038/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["among/ [those who] rise against/ them"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8179G}/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["from/ [the] gate","from/ [the] gate of","from/ [the] gates of","from/ gate"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8179G}/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["<to>/ [the] gates of","[were] to the/ gate","[were] to/ a gate","and/ [the] gate of","for/ [the] gate of","for/ a gate","of the/ gate","of/ [the] gate of","to the/ gate","to the/ gates","to/ [the] gate of","to/ gate"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0376I>', 'inflected', 'heb', 'ואיש', '["ve./''Ish"]', '["and/ [is] anyone","and/ anyone","and/ each","and/ each one","and/ everyone","and/ everyone of","and/ someone"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7138}/H9023/[H7126]', 'inflected', 'heb', 'קָרוֹב', '["qârôwb"]', '["kinsman/ his","kinsmen/ his","neighbor/ his"]', '["a"]', 'near (in place, kindred or time) allied, approach, at hand, any of kin, kinsfold(-sman), (that is) near (of kin), neighbour, (that is) next, (them that come) nigh (at hand), more ready, short(-ly).', 'or קָרֹב; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7969}/[H7969]', 'inflected', 'heb', 'שָׁלוֹשׁ', '["shâlôwsh"]', '["about/ three"]', '["n"]', 'three; occasionally (ordinal) third, or (multiple) thrice fork, often(-times), third, thir(-teen, -teenth), three, thrice. Compare 7991.', 'or שָׁלֹשׁ; masculine שְׁלוֹשָׁה; or שְׁלֹשָׁה; a primitive number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027R}/H9026/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1121A}/H9023/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["[was] on/ son/ his","among/ sons/ his"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0251I}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ on/ brother/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5414H}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ to/ [the] setting up of","and/ to/ put"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403B}/H9026/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sin/ your","sins/ your"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403B}/H9028/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sin offering/ their","sin/ their","sins/ their"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4229A}/H9030/[H4229]', 'inflected', 'heb', 'מָחָה', '["mâchâh"]', '["wipe out/ me"]', '["v"]', 'properly, to stroke or rub; by implication, to erase; also to smooth (as if with oil), i.e. grease or make fat; also to touch, i.e. reach to abolish, blot out, destroy, full of marrow, put out, reach unto, × utterly, wipe (away, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5612H}/H9021/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["from/ book/ your"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4229A}/H9033/[H4229]', 'inflected', 'heb', 'מָחָה', '["mâchâh"]', '["I will wipe out/ him"]', '["v"]', 'properly, to stroke or rub; by implication, to erase; also to smooth (as if with oil), i.e. grease or make fat; also to touch, i.e. reach to abolish, blot out, destroy, full of marrow, put out, reach unto, × utterly, wipe (away, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5612H}/H9020/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["from/ book/ my"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485I}/H9040/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["give attention to/ I","visit/ I"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6485I}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ I will appoint","and/ I will visit","and/ he visited","and/ you have visited","and/ you sought"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0175>\', 'opaque', 'heb', 'אַהֲרוֹן', '["ʼAhărôwn"]', '["Aaron"]', '["n-pr-m"]', 'Aharon, the brother of Moses Aaron.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130G}/H9021/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["[are] in/ midst/ your","[is] in/ midst/ your","[will be] in/ midst/ your","in/ midst/ your"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615H}/H9031/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["I should make an end of/ you"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7451A}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<the>/ bad","<the>/ harmful","<the>/ wicked"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5716}/H9023/[H5710]', 'inflected', 'heb', 'עֲדִי', '["ʻădîy"]', '["ornament[s]/ his","ornament[s]/ its","trapping[s]/ its"]', '["n-m"]', 'finery; generally an outfit; specifically, a headstall × excellent, mouth, ornament.', 'from 5710 in the sense of trappings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7281}/[H7280]', 'lemma', 'heb', 'רֶגַע', '["regaʻ"]', '["a moment"]', '["n-m"]', 'a wink (of the eyes), i.e. a very short space of time instant, moment, space, suddenly.', 'from 7280.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3615H}/H9031/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["and/ I will make an end of/ you"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5716}/H9021/[H5710]', 'inflected', 'heb', 'עֲדִי', '["ʻădîy"]', '["ornament[s]/ your"]', '["n-m"]', 'finery; generally an outfit; specifically, a headstall × excellent, mouth, ornament.', 'from 5710 in the sense of trappings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5716}/H9028/[H5710]', 'inflected', 'heb', 'עֲדִי', '["ʻădîy"]', '["ornament[s]/ their"]', '["n-m"]', 'finery; generally an outfit; specifically, a headstall × excellent, mouth, ornament.', 'from 5710 in the sense of trappings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2022G}/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["from/ [the] hill country of","from/ [the] mountain of","from/ [the] mountains of","from/ mount","from/ mountain"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2722}/[H2717]', 'lemma', 'heb', 'חֹרֵב', '["Chôrêb"]', '["Horeb"]', '["n-pr-loc"]', 'Choreb, a (generic) name for the Sinaitic mountains Horeb.', 'from 2717; desolate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9043/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["came/ he","comes/ he","coming/ he","goes/ he","went/ he"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8334}/H9033/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["and/ servant/ his"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5126}/[H5125]', 'lemma', 'heb', 'נוּן', '["Nûwn"]', '["Nun"]', '["n-pr-m"]', 'Nun or Non, the father of Joshua Non, Nun.', 'or נוֹן; (1 Chronicles 7:27), from 5125; perpetuity,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0168G}\/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["the/ tent"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9030/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["he made known to/ me","make known to/ me","show/ me","they knew/ me","you cause to know/ me","you have made know/ me","you know/ me","you will make known to/ me"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9031/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["I knew/ you","I know/ you","I made known to/ you","I teach/ you","I will make known to/ you","[am] making known to/ you","[those who] knew/ you","they have known/ you","they know/ you","to make know/ you","we know/ you"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869H}/H9020/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ eyes/ my","in/ view/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870G}/H9021/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["own ways/ your","way/ your","ways/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3045}/H9031/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["so/ I may know/ you"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7200H}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ consider","and/ see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4100}/[H4100]', 'inflected', 'heb', 'מָה', '["mâh"]', '["and/ <in>/ how?"]', '["i"]', 'properly, interrogative what? (including how? why? when?); but also exclamation, what! (including how!), or indefinitely what (including whatever, and even relatively, that which); often used with prefixes in various adverbial or conjunctive senses how (long, oft, (-soever)), (no-) thing, what (end, good, purpose, thing), whereby(-fore, -in, -to, -with), (for) why.', 'or מַה; or מָ; or מַ; also מֶה; a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5971A}/H9021/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0127I}\/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["the/ ground"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3045}/H9031/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["and/ I have known/ you"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3519}/H9021/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["glory/ your","honor/ your","splendor/ your"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2898}/H9020/[H2895]', 'inflected', 'heb', 'טוּב', '["ṭûwb"]', '["good thing[s]/ my","goodness/ my"]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440G}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ your","presence/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2603A}/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["and/ I sought favor","and/ I will show favor to","and/ he showed favor to","and/ he sought favor","and/ she sought favor","and/ they will seek favor"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7355}/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["and/ I will have compassion on","and/ he will have compassion","and/ he will have compassion on"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7355}/[H7355]', 'lemma', 'heb', 'רָחַם', '["râcham"]', '["I will have compassion","I will have compassion on","Ruhamah","[is] compassionate","he has compassion","he has compassion on","he is shown compassion","he will be shown mercy","he will have compassion","he will have compassion on","she is Shown Compassion","surely <have compassion>","they have mercy","they will have compassion on","they will have mercy","to have compassion","will you have compassion on","you will have compassion on"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5674A}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["when/ made pass through","when/ make pass","when/ passes by"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760H}/H9031/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ I will put/ you"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5366}/[H5365]', 'inflected', 'heb', 'נְקָרָה', '["nᵉqârâh"]', '["in/ [the] cleft of","in/ [the] crevices of"]', '["n-f"]', 'a fissure cleft, clift.', 'from 5365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5526E}/[H5526]', 'inflected', 'heb', 'סָכַךְ', '["çâkak"]', '["and/ I will hold"]', '["v"]', 'properly, to entwine as a screen; by implication, to fence in, cover over, (figuratively) protect cover, defence, defend, hedge in, join together, set, shut up.', 'or שָׂכַךְ; (Exodus 33:22), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674A}/H9040/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["have passed by/ I","to pass over/ I"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0268}/H9020/[H299]', 'inflected', 'heb', 'אָחוֹר', '["ʼâchôwr"]', '["back parts/ my"]', '["n-m"]', 'the hinder part; hence (adverb) behind, backward; also (as facing north) the West after(-ward), back (part, -side, -ward), hereafter, (be-) hind(-er part), time to come, without.', 'or (shortened) אָחֹר ; from 299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440H}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ face/ my"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200G}\/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["I saw","he saw","they will be visible","we have seen"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6458}/[H6458]', 'lemma', 'heb', 'פָּסַל', '["pâçal"]', '["cut out"]', '["v"]', 'to carve, whether wood or stone grave, hew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7223G}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["like the/ first [offering]","like the/ former [tablets]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1242}/[H1239]', 'inflected', 'heb', 'בֹּקֶר', '["bôqer"]', '["[has been] to the/ mornings","for the/ morning","into <the>/ morning","of the/ morning","to the/ morning","to the/ mornings","to/ mornings"]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6458}/[H6458]', 'inflected', 'heb', 'פָּסַל', '["pâçal"]', '["and/ I cut out","and/ he cut out","and/ they cut [them] to shape"]', '["v"]', 'to carve, whether wood or stone grave, hew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7349}/[H7355]', 'lemma', 'heb', 'רַחוּם', '["rachûwm"]', '["[is] compassionate","[was] compassionate","compassionate"]', '["a"]', 'compassionate full of compassion, merciful.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2587}/[H2603]', 'inflected', 'heb', 'חַנּוּן', '["channûwn"]', '["and/ gracious"]', '["a"]', 'gracious gracious.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0750}/[H748]', 'lemma', 'heb', 'אָרֵךְ', '["ʼârêk"]', '["<the> long of","[is] long of","a [person] long of","a [person] patient of","long of"]', '["a"]', 'long long(-suffering, -winged), patient, slow (to anger).', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5341}/[H5341]', 'lemma', 'heb', 'נָצַר', '["nâtsar"]', '["I have observed","I observe","I will observe","O watcher of","[are those who] observe","[is] preserving","[one who] guards","[one who] keeps","a watchman","besieged","besiegers","guard","it preserves","keep","let it keep","let them observe","maintaining","they may observe","they observed","they preserve","they will observe","watchmen","you will keep","you will preserve"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6588}/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["and/ transgression"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2403A}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ sin"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5352}/[H5352]', 'inflected', 'heb', 'נָקָה', '["nâqâh"]', '["and/ certainly <to leave unpunished>"]', '["v"]', 'to be (or make) clean (literally or figuratively); by implication (in an adverse sense) to be bare, i.e. extirpated acquit × at all, × altogether, be blameless, cleanse, (be) clear(-ing), cut off, be desolate, be free, be (hold) guiltless, be (hold) innocent, × by no means, be quit, be (leave) unpunished, × utterly, × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5545}/[H5545]', 'inflected', 'heb', 'סָלַח', '["çâlach"]', '["<and>/ you will forgive","and/ I will forgive","and/ it will be forgiven","and/ you will forgive"]', '["v"]', 'to forgive forgive, pardon, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5771G}/H9025/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["<to>/ iniquity/ our"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2403B}/H9025/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ <to>/ sin/ our"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5157}/H9035/[H5157]', 'inflected', 'heb', 'נָחַל', '["nâchal"]', '["and/ you will take as a possession/ us"]', '["v"]', 'to inherit (as a (figurative) mode of descent), or (generally) to occupy; causatively, to bequeath, or (generally) distribute, instate divide, have (inheritance), take as a heritage, (cause to, give to, make to) inherit, (distribute for, divide (for, for an, by), give for, have, leave for, take (for)) inheritance, (have in, cause to, be made to) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6381}/[H6381]', 'lemma', 'heb', 'פָּלָא', '["pâlâʼ"]', '["<of> wonders","[are] wonderful","[is too] difficult","[the] wonders of","[things too] wonderful","extraordinary [things]","he has made wonderful","he made wonderful","he will make hard","highly <deal wonderfully>","is it [too] difficult","it is [too] difficult","it is wonderful","it was wonderful","it will be [too] difficult","it will be difficult","they are [too] wonderful","will it be difficult?","wonderful [things]","wonders","you show yourself wonderful"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4196}/H9028/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["altars/ their"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5422}/H9013/[H5422]', 'inflected', 'heb', 'נָתַץ', '["nâthats"]', '["you will pull down/ !"]', '["v"]', 'to tear down beat down, break down (out), cast down, destroy, overthrow, pull down, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7665}/H9013/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["you will break down/ !"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0842}/H9023/[H833]', 'inflected', 'heb', 'אֲשֵׁרָה', '["ʼăshêrâh"]', '["Asherah poles/ its"]', '["n-pr-f"]', 'Asherah (or Astarte) a Phoenician goddess; also an image of the same grove. Compare 6253.', 'or אֲשֵׁירָה; from 833; happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3772G}/H9013/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["they will be cut off/ !","you will cut down/ !"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0410K}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["<into>/ a god","to/ a god","to/ a god of"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7067G}/[H7065]', 'lemma', 'heb', 'קַנָּא', '["qannâʼ"]', '["[is] jealous"]', '["a"]', 'jealous jealous. Compare 7072.', 'from 7065;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2181}/[H2181]', 'inflected', 'heb', 'זָנָה', '["zânâh"]', '["and/ he made prostitute [themselves]","and/ it will act [the] prostitute","and/ it will act as a prostitute","and/ she acted as a prostitute","and/ she has acted as a prostitute","and/ she has played [the] prostitute","and/ she was angry","and/ they acted as prostitutes","and/ they have prostituted themselves","and/ they played [the] prostitute","and/ they will make prostitute [themselves]","and/ they will prostitute themselves","and/ you acted as a prostitute","and/ you have made prostitute [themselves]"]', '["v"]', 'to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish.', 'a primitive root [highly fed and therefore wanton];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2077}/H9023/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["some of/ sacrifice/ his"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1323G}/H9023/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["some of/ daughters/ his"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430J}/H9029/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["gods/ their"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7716}/[H7582]', 'inflected', 'heb', 'שֶׂה', '["seh"]', '["and/ a sheep","and/ an animal of","and/ sheep"]', '["n-m"]', 'a member of a flock, i.e. a sheep or goat (lesser, small) cattle, ewe, goat, lamb, sheep. Compare 2089.', 'or שֵׂי; probably from 7582 through the idea of pushing out to graze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6363A}/[H6362]', 'inflected', 'heb', 'פֶּטֶר', '["peṭer"]', '["and/ [the] firstborn of"]', '["n-m"]', 'a fissure, i.e. (concretely) firstling (as opening the matrix) firstling, openeth, such as open.', 'or פִּטְרָה; from 6362;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2758}/[H2790]', 'inflected', 'heb', 'חָרִישׁ', '["chârîysh"]', '["at <the>/ plowing time"]', '["n-m"]', 'ploughing or its season earing (time), ground.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7105A}/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["and/ at <the>/ harvest time"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7620G}/[H7650]', 'lemma', 'heb', 'שָׁבוּעַ', '["shâbûwaʻ"]', '["weeks"]', '["n-m"]', 'literally, sevened, i.e. a week (specifically, of years) seven, week.', 'or שָׁבֻעַ; also (feminine) שְׁבֻעָה; properly, passive participle of 7650 as a denominative of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8622}/[H5362]', 'lemma', 'heb', 'תְּקוּפָה', '["tᵉqûwphâh"]', '["[the] circuit of"]', '["n-f"]', 'a revolution, i.e. (of the sun) course, (of time) lapse circuit, come about, end.', 'or תְּקֻפָה; from 5362;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423H}/[H3423]', 'lemma', 'heb', 'יָרַשׁ', '["yârash"]', '["I will dispossess","[are] about to dispossess","[is] about to dispossess","did you dispossess","has he dispossessed","have you taken possession?","he dispossessed","he had dispossessed","he has dispossessed","he will dispossess","he will take possession of","it dispossessed","it took possession of","it will take possession of","let us take possession of","she will dispossess","take possession","take possession of","take possession of [it]","they dispossessed","they took possession of","they will take possession of","we took possession of","we will take possession of","will you take possession of","you dispossessed","you will dispossess","you will take possession of"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7337}/[H7337]', 'inflected', 'heb', 'רָחַב', '["râchab"]', '["and/ I will enlarge","and/ it was broad","and/ it will be enlarged","and/ they have opened wide"]', '["v"]', 'to broaden (intransitive or transitive, literal or figurative) be an en-(make) large(-ing), make room, make (open) wide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5927G}/H9041/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["when/ going up/ you"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7819A}/[H7819]', 'lemma', 'heb', 'שָׁחַט', '["shâchaṭ"]', '["[one who] slaughters","[who] slaughter","beaten","he slaughtered","he will cut [the] throat of","he will cut [the] throat of [it]","it has its throat cut","it will have its throat cut","people cut [the] throat of","people slaughter","people slaughtered","people will cut [the] throat of","someone cuts [the] throat of","they slaughtered","they will slaughter","will it be slaughtered","you must cut [the] throat of","you must slaughter"]', '["v n-f"]', 'to slaughter (in sacrifice or massacre) kill, offer, shoot out, slay, slaughter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3381}/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["when/ came down","when/ comes down"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3381}/H9043/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["when/ came down/ he"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7160}/[H7161]', 'lemma', 'heb', 'קָרַן', '["qâran"]', '["having horns","it shone"]', '["v"]', 'to shoot out horns; figuratively, rays have horns, shine.', 'a primitive root; to push or gore; used only as denominative from 7161,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1696G}/H9043/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["because/ had spoken/ he","when/ said/ he","when/ speaks/ he","when/ spoke/ he","when/ turned aside/ he","when/ was speaking/ he"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5066G}/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["from/ drawing near"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5387A}/[H5375]', 'inflected', 'heb', 'נָשִׂיא', '["nâsîyʼ"]', '["[is] the/ prince","the/ leaders","the/ prince"]', '["n-m"]', 'properly, an exalted one, i.e. a king or sheik; also a rising mist captain, chief, cloud, governor, prince, ruler, vapour.', 'or נָשִׂא; from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5712}/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["among the/ congregation","among/ [the] congregation of","in/ [the] company of","in/ [the] congregation of"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4533>', 'opaque', 'heb', 'מַסְוֶה', '["maçveh"]', '["a veil"]', '["n-m"]', 'a veil vail.', 'apparently from an unused root meaning to cover;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ when/ comes","and/ when/ went"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4533>', 'inflected', 'heb', 'המסוה', '["ha./mas.Veh"]', '["the/ veil"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318G}/H9043/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["came out/ he","comes out/ he","has gone out/ he"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7676}\/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["the/ sabbath"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5081G}/[H5068]', 'lemma', 'heb', 'נָדִיב', '["nâdîyb"]', '["<the> [person] willing of","[person] willing of","willing","willing [person]"]', '["a"]', 'properly, voluntary, i.e. generous; hence, magnanimous; as noun, a grandee (sometimes a tyrant) free, liberal (things), noble, prince, willing (hearted).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935P}/H9034/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["I have brought/ it","he will bring/ it","let him bring/ it","you will bring/ it"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1314}/[H1313]', 'inflected', 'heb', 'בֶּשֶׂם', '["besem"]', '["and/ spices"]', '["n-m"]', 'fragrance; by implication, spicery; also the balsam plant smell, spice, sweet (odour).', 'or בֹּשֶׂם; from the same as 1313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4372}/H9023/[H3680]', 'inflected', 'heb', 'מִכְסֶה', '["mikçeh"]', '["covering/ its"]', '["n-m"]', 'a covering, i.e. weatherboarding covering.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7165}/H9023/[H7164]', 'inflected', 'heb', 'קֶרֶס', '["qereç"]', '["hooks/ its"]', '["n-m"]', 'a knob or belaying-pin (from its swelling form) tache.', 'from 7164;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7175>/H9023', 'opaque', 'heb', 'קֶרֶשׁ', '["qeresh"]', '["frames/ its"]', '["n-m"]', 'a slab or plank; by implication, a deck of a ship bench, board.', 'from an unused root meaning to split off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1280}/H9023/[H1272]', 'inflected', 'heb', 'בְּרִיחַ', '["bᵉrîyach"]', '["bars/ its"]', '["n-m"]', 'a bolt bar, fugitive.', 'from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5982G}/H9023/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["pillar/ his","pillars/ its","posts/ its"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0134}/H9023/[H113]', 'inflected', 'heb', 'אֶדֶן', '["ʼeden"]', '["bases/ its"]', '["n-m"]', 'a basis (of a building, a column, etc.) foundation, socket.', 'from the same as 113 (in the sense of strength);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4539}/[H5526]', 'inflected', 'heb', 'מָסָךְ', '["mâçâk"]', '["the/ covering","the/ screen"]', '["n-m"]', 'a cover, i.e. veil covering, curtain, hanging.', 'from 5526;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6440H}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["[were] the/ faces","the/ face","the/ presence"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5178A}/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["<the>/ bronze","the/ bronze"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0134}/H9024/[H113]', 'inflected', 'heb', 'אֶדֶן', '["ʼeden"]', '["bases/ its"]', '["n-m"]', 'a basis (of a building, a column, etc.) foundation, socket.', 'from the same as 113 (in the sense of strength);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4340}/H9028/[H3498]', 'inflected', 'heb', 'מֵיתָר', '["mêythâr"]', '["ropes/ their"]', '["n-m"]', 'a cord (of a tent); or the string (of a bow) cord, string.', 'from 3498; (compare 3499)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375S}/H9033/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["it lifted/ him"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5068}/[H5068]', 'lemma', 'heb', 'נָדַב', '["nâdab"]', '["I have made a contribution","[is] making a contribution","[one who] offered","it impelled","they had made a contribution","they offered freewill offerings"]', '["v"]', 'to impel; hence, to volunteer (as a soldier), to present spontaneously offer freely, be (give, make, offer self) willing(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4399}/[H4397]', 'inflected', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["[were] for the/ work","for the/ work","for/ [the] work of","for/ a product","into/ a product"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5656G}/H9023/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["service/ its"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0899B}/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["and/ for/ [the] garments of"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2397}/[H2336]', 'lemma', 'heb', 'חָח', '["châch"]', '["hooks","nose ring[s]"]', '["n-m"]', 'a ring for the nose (or lips) bracelet, chain, hook.', 'once (Ezekiel 29:4) חָחִי; from the same as 2336;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5141>', 'inflected', 'heb', 'ונזמי', '["va./Ne.zem","ve./niz.Mei"]', '["and/ [the] rings of","and/ earring[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2885}/[H2883]', 'inflected', 'heb', 'טַבַּעַת', '["ṭabbaʻath"]', '["and/ finger ring[s]"]', '["n-m"]', 'properly, a seal (as sunk into the wax), i.e. signet (for sealing); hence (generally) a ring of any kind ring.', 'from 2883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3558>', 'inflected', 'heb', 'וכומז', '["ve./khu.Maz"]', '["and/ an ornament","and/ ornament[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2901}/[H2901]', 'lemma', 'heb', 'טָוָה', '["ṭâvâh"]', '["they spun"]', '["v"]', 'to spin spin.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4299}/[H2901]', 'lemma', 'heb', 'מַטְוֶה', '["maṭveh"]', '["that which was spun"]', '["n-m"]', 'something spun spun.', 'from 2901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8336B}/[H4897]', 'inflected', 'heb', 'שֵׁשׁ', '["shêsh"]', '["the/ fine linen"]', '["n-m"]', 'bleached stuff, i.e. white linen or (by analogy) marble × blue, fine (twined) linen, marble, silk.', 'or (for alliteration with 4897) שְׁשִׁי; for 7893;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375S}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["it lifted"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9029/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart/ their"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5387A}/[H5375]', 'inflected', 'heb', 'נָשִׂיא', '["nâsîyʼ"]', '["and/ the/ leaders","and/ the/ prince"]', '["n-m"]', 'properly, an exalted one, i.e. a king or sheik; also a rising mist captain, chief, cloud, governor, prince, ruler, vapour.', 'or נָשִׂא; from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1314}/[H1313]', 'inflected', 'heb', 'בֶּשֶׂם', '["besem"]', '["<the>/ spice","the/ spice","the/ spices"]', '["n-m"]', 'fragrance; by implication, spicery; also the balsam plant smell, spice, sweet (odour).', 'or בֹּשֶׂם; from the same as 1313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8081}/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["<the>/ oil","the/ oil"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8081}/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["and/ for/ [the] oil of"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5071}/[H5068]', 'lemma', 'heb', 'נְדָבָה', '["nᵉdâbâh"]', '["[are] a freewill offering","[the] freewill offerings of","[will be] freewill offerings","a freewill offering","a freewill offering of","freewill offerings","voluntariness","voluntariness<es>"]', '["n-f"]', 'properly (abstractly) spontaneity, or (adjectively) spontaneous; also (concretely) a spontaneous or (by inference, in plural) abundant gift free(-will) offering, freely, plentiful, voluntary(-ily, offering), willing(-ly), offering).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8394}/[H995]', 'inflected', 'heb', 'תָּבוּן', '["tâbûwn"]', '["by/ understanding","in/ understanding","with/ understanding"]', '["n-m"]', 'intelligence; by implication, an argument; by extension, caprice discretion, reason, skilfulness, understanding, wisdom.', 'and (feminine) תְּבוּנָה; or תּוֹבֻנָה; from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2803G}/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ to/ design"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3384B}/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["and/ to/ teach"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0171}/[H168]', 'inflected', 'heb', 'אׇהֳלִיאָב', '["ʼOhŏlîyʼâb"]', '["and/ Oholiab"]', '["n-pr-m"]', 'Oholiab, an Israelite Aholiab.', 'from 168 and 1; tent of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2803G}/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ a skillful worker","and/ designers of"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7551}/[H7551]', 'inflected', 'heb', 'רָקַם', '["râqam"]', '["and/ a worker in colors"]', '["v"]', 'to variegate color, i.e. embroider; by implication, to fabricate embroiderer, needlework, curiously work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8504}/[H7827]', 'inflected', 'heb', 'תְּכֵלֶת', '["tᵉkêleth"]', '["in <the>/ violet","in the/ violet stuff"]', '["n-f"]', 'the cerulean mussel, i.e. the color (violet) obtained therefrom or stuff dyed therewith blue.', 'probably for 7827;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H0713>', 'inflected', 'heb', 'ובארגמן', '["u./va./''ar.ga.Man"]', '["and/ in the/ purple"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8438B}/[H3216]', 'inflected', 'heb', 'תּוֹלָע', '["tôwlâʻ"]', '["in/ [the] scarlet stuff of"]', '["n-m n-f"]', 'a maggot (as voracious); specifically (often with ellipsis of 8144) the crimson-grub, but used only (in this connection) of the color from it, and cloths dyed therewith crimson, scarlet, worm.', 'and (feminine) תּוֹלֵעָה; or תּוֹלַעַת; or תֹּלַעַת; from 3216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8336B}/[H4897]', 'inflected', 'heb', 'שֵׁשׁ', '["shêsh"]', '["and/ in the/ fine linen"]', '["n-m"]', 'bleached stuff, i.e. white linen or (by analogy) marble × blue, fine (twined) linen, marble, silk.', 'or (for alliteration with 4897) שְׁשִׁי; for 7893;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0707}/[H707]', 'inflected', 'heb', 'אָרַג', '["ʼârag"]', '["and/ [those who] weave","and/ a weaver"]', '["v"]', 'to plait or weave weaver(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213J}/[H6213]', 'lemma', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["[one who] does","[the] doer of","[the] doers of","[those who] do","[was] doing","are you doing?","doers of","doing","made","maker[s] of","they made","will you do","you have made","you will do"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8394}/[H995]', 'inflected', 'heb', 'תָּבוּן', '["tâbûwn"]', '["and/ understanding"]', '["n-m"]', 'intelligence; by implication, an argument; by extension, caprice discretion, reason, skilfulness, understanding, wisdom.', 'and (feminine) תְּבוּנָה; or תּוֹבֻנָה; from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7126G}/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["to/ bring near","to/ draw near"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H6440L}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ to/ before"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2450}/[H2449]', 'inflected', 'heb', 'חָכָם', '["châkâm"]', '["<the>/ wise","the/ skillful [people]","the/ skillful [women]","the/ wise [person]"]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4399}/H9023/[H4397]', 'inflected', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["from/ work/ his"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1767>', 'inflected', 'heb', 'מדי', '["mi./Dei","mi./dei"]', '["as/ often as","more than/ sufficiency of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5656H}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["the/ service"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963J>', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["a proclamation"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8641}/[H7311]', 'inflected', 'heb', 'תְּרוּמָה', '["tᵉrûwmâh"]', '["for the/ contributions","for/ [the] contribution of","of/ [the] contribution of"]', '["n-f"]', 'a present (as offered up), especially in sacrifice or as tribute gift, heave offering (shoulder), oblation, offered(-ing).', 'or תְּרֻמָה; (Deuteronomy 12:11), from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0935P}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["from/ bringing"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4399}/[H4397]', 'inflected', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["and/ the/ business","and/ the/ work"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1767>/H9028', 'opaque', 'heb', 'דַּי', '["day"]', '["sufficiency/ their"]', '["prep"]', 'enough (as noun or adverb), used chiefly with preposition in phrases able, according to, after (ability), among, as (oft as), (more than) enough, from, in, since, (much as is) sufficient(-ly), too much, very, when.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3498}\/[H3498]', 'inflected', 'heb', 'יָתַר', '["yâthar"]', '["and/ it was more than enough"]', '["v"]', 'to jut over or exceed; by implication, to excel; (intransitively) to remain or be left; causatively to leave, cause to abound, preserve excel, leave (a remnant), left behind, too much, make plenteous, preserve, (be, let) remain(-der, -ing, -nant), reserve, residue, rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6213J}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["among/ [those who] did","of/ [those who] do"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2266}/[H2266]', 'inflected', 'heb', 'חָבַר', '["châbar"]', '["to/ join together"]', '["v"]', 'to join (literally or figuratively); specifically (by means of spells) to fascinate charm(-er), be compact, couple (together), have fellowship with, heap up, join (self, together), league.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6823}/H9038/[H6822]', 'inflected', 'heb', 'צָפָה', '["tsâphâh"]', '["and/ he overlaid/ them"]', '["v"]', 'to sheet over (especially with metal) cover, overlay.', 'a primitive root (probably identical with 6822 through the idea of expansion in outlook, transferring to action);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218I>/H9028', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["tops/ their"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6823}/H9033/[H6822]', 'inflected', 'heb', 'צָפָה', '["tsâphâh"]', '["and/ he overlaid/ it"]', '["v"]', 'to sheet over (especially with metal) cover, overlay.', 'a primitive root (probably identical with 6822 through the idea of expansion in outlook, transferring to action);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3742>\', 'inflected', 'heb', 'הכרבים פ', '["ha./ke.ru.Vim"]', '["the/ cherubim"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709I}/H9023/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["pans/ its"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4518}/H9023/[H5352]', 'inflected', 'heb', 'מְנַקִּית', '["mᵉnaqqîyth"]', '["bowls/ its"]', '["n-f"]', 'a sacrificial basin (for holding blood) bowl.', 'from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7184>', 'inflected', 'heb', 'הקשות', '["ha./ke.sa.Vot"]', '["the/ jugs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2889}\/[H2891]', 'inflected', 'heb', 'טָהוֹר', '["ṭâhôwr"]', '["clean","pure"]', '["a"]', 'pure (in a physical, chemical, ceremonial or moral sense) clean, fair, pure(-ness).', 'or טָהֹר; from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3627}/H9024\/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["articles/ its"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7543}\/[H7543]', 'inflected', 'heb', 'רָקַח', '["râqach"]', '["a perfumer"]', '["v"]', 'to perfume apothecary, compound, make (ointment), prepare, spice.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5518A}/[H5518]', 'inflected', 'heb', 'סִיר', '["çîyr"]', '["[is] the/ pot","the/ pot","the/ pots"]', '["n-m"]', 'a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn.', 'or (feminine) סִירָה; or סִרָה; (Jeremiah 52:18), from a primitive root meaning to boil up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3257}/[H3261]', 'inflected', 'heb', 'יָע', '["yâʻ"]', '["the/ shovels"]', '["n-m"]', 'a shovel shovel.', 'from 3261;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4219}/[H2236]', 'inflected', 'heb', 'מִזְרָק', '["mizrâq"]', '["the/ bowl","the/ bowls"]', '["n-m"]', 'a bowl (as if for sprinkling) bason, bowl.', 'from 2236;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4207B>', 'inflected', 'heb', 'המזלגות', '["ha./miz.la.Got","ha./miz.la.goyT"]', '["the/ forks"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4289}/[H4288]', 'inflected', 'heb', 'מַחְתָּה', '["machtâh"]', '["<the>/ censer","the/ censer","the/ censers","the/ fire-pans"]', '["n-f"]', 'a pan for live coals censer, firepan, snuffdish.', 'the same as 4288 in the sense of removal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3749}/H9023/[H3522]', 'inflected', 'heb', 'כַּרְכֹּב', '["karkôb"]', '["ledge/ its"]', '["n-m"]', 'a rim or top margin compass.', 'expanded from the same as 3522;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2677}/H9023/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["half of/ it","middle/ its"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7117}/[H7096]', 'inflected', 'heb', 'קְצָת', '["qᵉtsâth"]', '["the/ ends"]', '["n-f"]', 'a termination (literally or figuratively); also (by implication) a portion; adverbially (with prepositional prefix) after end, part, × some.', 'from 7096;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4345}/[H3527]', 'inflected', 'heb', 'מַכְבֵּר', '["makbêr"]', '["for/ [the] grating of"]', '["n-m"]', 'a grate grate.', 'from 3527 in the sense of covering (compare 3531);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4759B}/[H4758]', 'inflected', 'heb', 'מַרְאָה', '["marʼâh"]', '["with/ [the] mirrors of"]', '["n-f"]', 'a vision; also (causatively) a mirror looking glass, vision.', 'feminine of 4758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6633}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["the/ serving [women]","which/ wage war","who/ had gone to war","who/ mustered","who/ were serving"]', '["v"]', 'to mass (an army or servants) assemble, fight, perform, muster, wait upon, war.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6633}/[H6633]', 'lemma', 'heb', 'צָבָא', '["tsâbâʼ"]', '["they have waged war","they served"]', '["v"]', 'to mass (an army or servants) assemble, fight, perform, muster, wait upon, war.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4150I}\/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["meeting"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6285}/[H6311]', 'inflected', 'heb', 'פֵּאָה', '["pêʼâh"]', '["and/ for/ [the] side of"]', '["n-f"]', 'properly, mouth in a figurative sense, i.e. direction, region, extremity corner, end, quarter, side.', 'feminine of 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3802>', 'inflected', 'heb', 'הכתפת', '["ha./ka.Tef","ha./ke.te.Fot"]', '["the/ side","the/ supports"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0134}/[H113]', 'inflected', 'heb', 'אֶדֶן', '["ʼeden"]', '["and/ the/ bases"]', '["n-m"]', 'a basis (of a building, a column, etc.) foundation, socket.', 'from the same as 113 (in the sense of strength);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5982G}/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["[belonged] to the/ pillar","for the/ pillars"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6826}/[H6823]', 'inflected', 'heb', 'צִפּוּי', '["tsippûwy"]', '["and/ [the] overlay of"]', '["n-m"]', 'encasement (with metal) covering, overlaying.', 'from 6823;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4539}/[H5526]', 'inflected', 'heb', 'מָסָךְ', '["mâçâk"]', '["and/ [the] screen of"]', '["n-m"]', 'a cover, i.e. veil covering, curtain, hanging.', 'from 5526;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7341}/[H7337]', 'inflected', 'heb', 'רֹחַב', '["rôchab"]', '["in the/ breadth","in/ [the] breadth of","in/ breadth"]', '["n-m"]', 'width (literally or figuratively) breadth, broad, largeness, thickness, wideness.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5982G}/H9028/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["and/ pillars/ their"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3489>', 'inflected', 'heb', 'היתדת', '["ha/y.Tad","ha/y.te.Dot","hai./ya.Ted"]', '["the/ peg","the/ pin of","the/ tent peg","the/ tent pegs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2691A}/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["and/ for the/ courtyard","and/ to/ [the] court of"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485B}/[H6485]', 'lemma', 'heb', 'פָּקַד', '["pâqad"]', '["[were] [the] expenses of"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4908}/[H7931]', 'lemma', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["[are] [the] dwelling places of","[the] dwelling of","[the] dwelling place of","[the] dwelling places of","[the] dwellings of","[the] tabernacle of","a dwelling","dwelling place<s>","dwellings"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485A}/[H6485]', 'lemma', 'heb', 'פָּקַד', '["pâqad"]', '["I have paid attention to","[is] mustering","[those who] were enrolled of","[those] enrolled of","[were] [the] [men] enrolled of","[were] [the] enrolled [men] of","[who] they were mustered","enroll","he enrolled","he mustered","it was recorded","muster","someone enrolled","they enrolled","they had enrolled","they were enrolled","they were mustered","you will assign","you will be mustered","you will enroll"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1212G}/[H6738]', 'inflected', 'heb', 'בְּצַלְאֵל', '["Bᵉtsalʼêl"]', '["and/ Bezalel"]', '["n-pr-m"]', 'Betsalel, the name of two Israelites Bezaleel.', 'probably from 6738 and 410 with a prepositional prefix; in (the) shadow (i.e. protection) of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0854}/H9033/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ <with>/ him","and/ [was] with/ him","and/ [were] with/ him","and/ with/ him"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8438B}/[H3216]', 'inflected', 'heb', 'תּוֹלָע', '["tôwlâʻ"]', '["and/ in/ [the] scarlet stuff of"]', '["n-m n-f"]', 'a maggot (as voracious); specifically (often with ellipsis of 8144) the crimson-grub, but used only (in this connection) of the color from it, and cloths dyed therewith crimson, scarlet, worm.', 'and (feminine) תּוֹלֵעָה; or תּוֹלַעַת; or תֹּלַעַת; from 3216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8336B}\/[H4897]', 'inflected', 'heb', 'שֵׁשׁ', '["shêsh"]', '["and/ in the/ fine linen"]', '["n-m"]', 'bleached stuff, i.e. white linen or (by analogy) marble × blue, fine (twined) linen, marble, silk.', 'or (for alliteration with 4897) שְׁשִׁי; for 7893;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0505G}/[H504]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["and/ a thousand","and/ one thousand","and/ two thousand"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3332H}/[H3332]', 'inflected', 'heb', 'יָצַק', '["yâtsaq"]', '["to/ cast"]', '["v"]', 'properly, to pour out (transitive or intransitive); by implication, to melt or cast as metal; by extension, to place firmly, to stiffen or grow hard cast, cleave fast, be (as) firm, grow, be hard, lay out, molten, overflow, pour (out), run out, set down, stedfast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3967}/[H3967]', 'inflected', 'heb', 'מֵאָה', '["mêʼâh"]', '["for/ [the] one hundred","of/ one hundred","to the/ hundred","to/ [the] one hundred","to/ a hundred","to/ hundreds"]', '["n-f"]', 'a hundred; also as a multiplicative and a fraction hundred((-fold), -th), sixscore.', 'or מֵאיָה; properly, a primitive numeral');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0134}/[H113]', 'inflected', 'heb', 'אֶדֶן', '["ʼeden"]', '["for <the>/ base"]', '["n-m"]', 'a basis (of a building, a column, etc.) foundation, socket.', 'from the same as 113 (in the sense of strength);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0505G}/[H504]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["the/ one thousand","the/ thousand","the/ thousand [shekels]","the/ thousands"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3967}/[H3967]', 'inflected', 'heb', 'מֵאָה', '["mêʼâh"]', '["<the>/ hundred<s>","the/ hundred","the/ hundred<s>","the/ hundreds","the/ two hundred"]', '["n-f"]', 'a hundred; also as a multiplicative and a fraction hundred((-fold), -th), sixscore.', 'or מֵאיָה; properly, a primitive numeral');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2836B}/[H2820]', 'inflected', 'heb', 'חָשַׁק', '["châshaq"]', '["and/ he furnished with bands"]', '["v"]', 'to cling, i.e. join, (figuratively) to love, delight in; elliptically; to deliver have a delight, (have a) desire, fillet, long, set (in) love.', 'a primitive root; also interchangeable for 2820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H0713>', 'inflected', 'heb', 'והארגמן', '["ve./ha./''ar.ga.Man"]', '["and/ the/ purple"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8278}/[H8277]', 'lemma', 'heb', 'שְׂרָד', '["sᵉrâd"]', '["woven material"]', '["n-m"]', 'stitching (as pierced with a needle) service.', 'from 8277;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7554}/[H7554]', 'inflected', 'heb', 'רָקַע', '["râqaʻ"]', '["and/ they hammered out"]', '["v"]', 'to pound the earth (as a sign of passion); by analogy to expand (by hammering); by implication, to overlay (with thin sheets of metal) beat, make broad, spread abroad (forth, over, out, into plates), stamp, stretch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6341B}/[H6351]', 'lemma', 'heb', 'פַּח', '["pach"]', '["[the] thin plates of","thin plates"]', '["n-m"]', 'a (metallic) sheet (as pounded thin); also a spring net (as spread out like a lamina) gin, (thin) plate, snare.', 'from 6351;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7112}/[H7112]', 'inflected', 'heb', 'קָצַץ', '["qâtsats"]', '["and/ he cut [them] up","and/ he cut off","and/ he cut up","and/ he cuts in two","and/ they cut off","and/ you will cut off"]', '["v"]', 'to chop off (literally or figuratively) cut (asunder, in pieces, in sunder, off), × utmost.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H8432>', 'inflected', 'heb', 'ובתוך', '["u./ve./Tokh","u./ve./toKh"]', '["and/ in/ [the] middle of","and/ in/ among"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414H}/H9038/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will give/ them","and/ he appointed/ them","and/ he had put/ them","and/ he put/ them","and/ he will set/ them","and/ they put/ them","and/ you will put/ them"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7405}/[H7405]', 'inflected', 'heb', 'רָכַס', '["râkaç"]', '["and/ they bound"]', '["v"]', 'to tie bind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6310J}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["and/ [the] opening of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6472}/[H6471]', 'inflected', 'heb', 'פַּעֲמֹן', '["paʻămôn"]', '["the/ bells"]', '["n-m"]', 'a bell (as struck) bell.', 'from 6471;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7416}/[H7426]', 'inflected', 'heb', 'רִמּוֹן', '["rimmôwn"]', '["<the>/ pomegranate","<the>/ pomegranate tree","the/ pomegranates"]', '["n-m"]', 'a pomegranate, the tree (from its upright growth) or the fruit (also an artificial ornament) pomegranate.', 'or רִמֹּן; from 7426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6287}/[H6286]', 'lemma', 'heb', 'פְּאֵר', '["pᵉʼêr"]', '["[the] head-wrap of","a turban","head-dresses of"]', '["n-m"]', 'an embellishment, i.e. fancy head-dress beauty, bonnet, goodly, ornament, tire.', 'from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4021}/[H1389]', 'inflected', 'heb', 'מִגְבָּעָה', '["migbâʻâh"]', '["the/ headdresses"]', '["n-f"]', 'a cap (as hemispherical) bonnet.', 'from the same as 1389;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0906}/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["<the>/ linen","<the>/ linen<s>","the/ linen<s>"]', '["n-m"]', 'flaxen thread or yarn; hence, a linen garment linen.', 'perhaps from 909 (in the sense of divided fibres);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0073>', 'inflected', 'heb', 'האבנט', '["ha./''av.Net"]', '["the/ sash"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0134}/H9023/[H113]', 'inflected', 'heb', 'אֶדֶן', '["ʼeden"]', '["and/ bases/ its"]', '["n-m"]', 'a basis (of a building, a column, etc.) foundation, socket.', 'from the same as 113 (in the sense of strength);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0119}/[H119]', 'inflected', 'heb', 'אָדַם', '["ʼâdam"]', '["that/ was dyed red"]', '["v"]', 'to show blood (in the face), i.e. flush or turn rosy be (dyed, made) red (ruddy).', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8476}/[H8476]', 'inflected', 'heb', 'תַּחַשׁ', '["tachash"]', '["the/ dolphin","the/ dolphins"]', '["n-m"]', 'a (clean) animal with fur, probably a species of antelope badger.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4634}/[H4633]', 'inflected', 'heb', 'מַעֲרָכָה', '["maʻărâkâh"]', '["the/ battle line","the/ row"]', '["n-f"]', 'an arrangement; concretely, a pile; specifically a military array army, fight, be set in order, ordered place, rank, row.', 'feminine of 4633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5982G}/H9024/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["pillars/ her","pillars/ its"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4340}/H9023/[H3498]', 'inflected', 'heb', 'מֵיתָר', '["mêythâr"]', '["ropes/ its"]', '["n-m"]', 'a cord (of a tent); or the string (of a bow) cord, string.', 'from 3498; (compare 3499)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3489>/H9024', 'inflected', 'heb', 'ויתדתיה', '["vi./te.do.Tei./ha"]', '["and/ tent pegs/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965H}/[H6965]', 'lemma', 'heb', 'קוּם', '["qûwm"]', '["[am] about to raise up","[he is] raising","[he is] raising up","[who] he was raised up","certainly <to raise>","he raised up","he will raise","it has arisen","it has made rise","it was set up","raise up","they raised up","you must set up","you will raise [it] up","you will set up"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5526B}/[H5526]', 'inflected', 'heb', 'סָכַךְ', '["çâkak"]', '["and/ I will provoke","and/ he covered","and/ they covered","and/ you will cover"]', '["v"]', 'properly, to entwine as a screen; by implication, to fence in, cover over, (figuratively) protect cover, defence, defend, hedge in, join together, set, shut up.', 'or שָׂכַךְ; (Exodus 33:22), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6187}/H9023/[H6186]', 'inflected', 'heb', 'עֵרֶךְ', '["ʻêrek"]', '["arrangement/ its","valuation/ his"]', '["n-m"]', 'a pile, equipment, estimate equal, estimation, (things that are set in) order, price, proportion, × set at, suit, taxation, × valuest.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7004}/[H6999]', 'inflected', 'heb', 'קְטֹרֶת', '["qᵉṭôreth"]', '["for/ incense"]', '["n-f"]', 'a fumigation (sweet) incense, perfume.', 'from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4888A}/H9028/[H4886]', 'inflected', 'heb', 'מִשְׁחָה', '["mishchâh"]', '["anointing/ their"]', '["n-f"]', 'unction (the act); by implication, a consecratory gift (to be) anointed(-ing), ointment.', 'or מׇשְׁחָה; from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3550}/[H3547]', 'inflected', 'heb', 'כְּהֻנָּה', '["kᵉhunnâh"]', '["<into>/ a priesthood of"]', '["n-f"]', 'priesthood priesthood, priest''s office.', 'from 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6187}/[H6186]', 'lemma', 'heb', 'עֵרֶךְ', '["ʻêrek"]', '["an arrangement of"]', '["n-m"]', 'a pile, equipment, estimate equal, estimation, (things that are set in) order, price, proportion, × set at, suit, taxation, × valuest.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4503G>', 'inflected', 'heb', 'המנחה', '["ha./min.Chah"]', '["<the>/ grain offering","the/ grain offering","the/ offering"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7126G}/H9048/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["and/ when/ drew near/ they"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4196}/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["and/ <to> the/ altar","and/ for/ [the] altar of"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4399}\/[H4397]', 'inflected', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["the/ work"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3519}/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["and/ [is the] glory of","and/ [the] glory of","and/ [the] splendor of","and/ honor"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4550}/H9028/[H5265]', 'inflected', 'heb', 'מַסַּע', '["maççaʻ"]', '["[are] settings out/ their","journeyings/ their"]', '["n-m"]', 'a departure (from striking the tents), i.e. march (not necessarily a single day''s travel); by implication, a station (or point of departure) journey(-ing).', 'from 5265;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927H}/H9043/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["was taken up/ it"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7133A}/[H7126]', 'lemma', 'heb', 'קׇרְבָּן', '["qorbân"]', '["[is] [the] present of","[the] offering of","[the] present of","[was] [the] offering of","a present","a present of","present","present of"]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7133A}/H9026/[H7126]', 'inflected', 'heb', 'קׇרְבָּן', '["qorbân"]', '["present/ your"]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7133A}/H9023/[H7126]', 'inflected', 'heb', 'קׇרְבָּן', '["qorbân"]', '["offering/ his","present/ his"]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7126H}/H9033/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["bring near/ it","he will present/ it"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7522}/H9023/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["for/ acceptance/ its"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7521}/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["and/ I will accept","and/ it will accept","and/ it will be accepted","and/ you were pleased"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5408}/[H5408]', 'inflected', 'heb', 'נָתַח', '["nâthach"]', '["and/ he cut it in pieces","and/ he will cut in pieces"]', '["v"]', 'to dismember cut (in pieces), divide, hew in pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5409}/H9024/[H5408]', 'inflected', 'heb', 'נֵתַח', '["nêthach"]', '["into/ pieces/ its","to/ piece of meat/ its","to/ pieces/ its"]', '["n-m"]', 'a fragment part, piece.', 'from 5408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5409}/[H5408]', 'inflected', 'heb', 'נֵתַח', '["nêthach"]', '["the/ pieces"]', '["n-m"]', 'a fragment part, piece.', 'from 5408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7218A>', 'inflected', 'heb', 'הראש', '["ha./Rosh","ha./roSh"]', '["the/ head"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6309>', 'inflected', 'heb', 'הפדר', '["ha./Pa.der"]', '["the/ suet"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7130H}/H9023/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["and/ entrails/ its"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3775}/[H3532]', 'inflected', 'heb', 'כֶּשֶׂב', '["keseb"]', '["the/ young ram","the/ young rams"]', '["n-m"]', 'a young sheep lamb.', 'apparently by transposition for 3532;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6309>/H9023', 'opaque', 'heb', 'פֶּדֶר', '["peder"]', '["suet/ its"]', '["n-m"]', 'suet fat.', 'from an unused root meaning to be greasy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7130H}/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["and/ the/ entrails"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3767}/[H3766]', 'inflected', 'heb', 'כָּרָע', '["kârâʻ"]', '["and/ the/ legs"]', '["n-f"]', 'the leg (from the knee to the ankle) of men or locusts (only in the dual) leg.', 'from 3766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8449}/[H8447]', 'inflected', 'heb', 'תּוֹר', '["tôwr"]', '["the/ turtle-dove","the/ turtle-doves"]', '["n-f"]', 'a ring-dove, often (figuratively) as a term of endearment (turtle) dove.', 'or תֹּר; probably the same as 8447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7126H}/H9033/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["and/ he will present/ it"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4454}/[H4454]', 'inflected', 'heb', 'מָלַק', '["mâlaq"]', '["and/ he will nip off"]', '["v"]', 'to crack a joint; by implication, to wring the neck of a fowl (without separating it) wring off.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4680}/[H4680]', 'inflected', 'heb', 'מָצָה', '["mâtsâh"]', '["and/ he drained","and/ it will be drained out","and/ you will drain [it]"]', '["v"]', 'to suck out; by implication, to drain, to squeeze out suck, wring (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7023}/[H6979]', 'lemma', 'heb', 'קִיר', '["qîyr"]', '["[the] side of","[the] wall of","[the] walls of","a wall","a wall of"]', '["n-m"]', 'a wall (as built in a trench) mason, side, town, × very, wall.', 'or קִר; (Isaiah 22:5), or (feminine) קִירָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4760}/H9023/[H7200]', 'inflected', 'heb', 'מֻרְאָה', '["murʼâh"]', '["craw/ its"]', '["n-f"]', 'something conspicuous, i.e. the craw of a bird (from its prominence) crop.', 'apparently feminine passive causative participle of 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5133}/H9024/[H5327]', 'inflected', 'heb', 'נוֹצָה', '["nôwtsâh"]', '["with/ feather[s]/ its"]', '["n-f"]', 'a pinion (or wing feather); often (collectively) plumage feather(-s), ostrich.', 'or נֹצָה; feminine active participle of 5327 in the sense of flying;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1880}/[H1878]', 'inflected', 'heb', 'דֶּשֶׁן', '["deshen"]', '["the/ fatty ash"]', '["n-m"]', 'the fat; abstractly fatness, i.e. (figuratively) abundance; specifically the (fatty) ashes of sacrifices ashes, fatness.', 'from 1878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8156}/[H8156]', 'inflected', 'heb', 'שָׁסַע', '["shâçaʻ"]', '["and/ he reprimanded","and/ he will tear apart"]', '["v"]', 'to split or tear; figuratively, to upbraid cleave, (be) cloven (footed), rend, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3671}/H9023/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["by/ wings/ its","with/ skirt/ his"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315J}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ [the] person[s] of","and/ a person of","and/ an appetite","and/ anyone","and/ person[s] of"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3828}/[H3836]', 'lemma', 'heb', 'לְבוֹנָה', '["lᵉbôwnâh"]', '["frankincense"]', '["n-f"]', 'frankincense (from its whiteness or perhaps that of its smoke) (frank-) incense.', 'or לְבֹנָה; from 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7061}/[H7061]', 'inflected', 'heb', 'קָמַץ', '["qâmats"]', '["and/ he will take a handful"]', '["v"]', 'to grasp with the hand take an handful.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7062}/H9023/[H7061]', 'inflected', 'heb', 'קֹמֶץ', '["qômets"]', '["handful/ his"]', '["n-m"]', 'a grasp, i.e. handful handful.', 'from 7061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H5560>/H9024', 'inflected', 'heb', 'מסלתה', '["mi./sal.Ta/h"]', '["from/ fine flour/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8081}/H9024/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["and/ of/ oil/ its","and/ some of/ oil/ its"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3828}/H9024/[H3836]', 'inflected', 'heb', 'לְבוֹנָה', '["lᵉbôwnâh"]', '["frankincense/ its"]', '["n-f"]', 'frankincense (from its whiteness or perhaps that of its smoke) (frank-) incense.', 'or לְבֹנָה; from 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0234}/H9024/[H2142]', 'inflected', 'heb', 'אַזְכָּרָה', '["ʼazkârâh"]', '["memorial offering/ its"]', '["n-f"]', 'a reminder; specifically remembrance-offering memorial.', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0801}/[H800]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["from/ [the] fire offerings of","of/ [the] fire offerings of"]', '["n-m"]', 'properly, a burnt-offering; but occasionally of any sacrifice (offering, sacrifice), (made) by fire.', 'the same as 800, but used in a liturgical sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3989}/[H644]', 'lemma', 'heb', 'מַאֲפֶה', '["maʼăpheh"]', '["a baked item of"]', '["n-m"]', 'something baked, i.e. a batch baken.', 'from 644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2471}/[H2490]', 'lemma', 'heb', 'חַלָּה', '["challâh"]', '["a cake","a cake of","a round perforated bread of","cakes","round perforated breads","round perforated breads of"]', '["n-f"]', 'a cake (as usually punctured) cake.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8081}\/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["with <the>/ oil"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4227}/[H2281]', 'inflected', 'heb', 'מַחֲבַת', '["machăbath"]', '["the/ baking tray"]', '["n-f"]', 'a pan for baking in pan.', 'from the same as 2281;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7133A}/H9021/[H7126]', 'inflected', 'heb', 'קׇרְבָּן', '["qorbân"]', '["present/ your"]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6626}/[H6626]', 'lemma', 'heb', 'פָּתַת', '["pâthath"]', '["you will crumble"]', '["v"]', 'to open, i.e. break participle x', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4802}/[H7370]', 'lemma', 'heb', 'מַרְחֶשֶׁת', '["marchesheth"]', '["a baking pan"]', '["n-f"]', 'a stewpan fryingpan.', 'from 7370;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7126H}/H9034/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["and/ he will present/ it"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5066H}/H9034/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["and/ he will bring near/ it"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6999A}/[H6999]', 'lemma', 'heb', 'קָטַר', '["qâṭar"]', '["he made smoke","he will make smoke","it will be made to smoke","make smoke","people made smoke","surely <make smoke>","they made smoke","you must make to smoke","you will make smoke"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4503G>/H9021', 'opaque', 'heb', 'מִנְחָה', '["minchâh"]', '["grain offering/ your","offerings/ your"]', '["n-f"]', 'a donation; euphemistically, tribute; specifically a sacrificial offering (usually bloodless and voluntary) gift, oblation, (meat) offering, present, sacrifice.', 'from an unused root meaning to apportion, i.e. bestow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4417M}/[H4414]', 'inflected', 'heb', 'מֶלַח', '["melach"]', '["with <the>/ salt"]', '["n-m"]', 'properly, powder, i.e. (specifically) salt (as easily pulverized and dissolved) salt(-pit).', 'from 4414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4417M}\/[H4414]', 'inflected', 'heb', 'מֶלַח', '["melach"]', '["salt"]', '["n-m"]', 'properly, powder, i.e. (specifically) salt (as easily pulverized and dissolved) salt(-pit).', 'from 4414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7033}/[H7034]', 'lemma', 'heb', 'קָלָה', '["qâlâh"]', '["burning [pain]","roasted"]', '["v"]', 'to toast, i.e. scorch partially or slowly dried, loathsome, parch, roast.', 'a primitive root (rather identical with 7034 through the idea of shrinkage by heat);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1643>', 'opaque', 'heb', 'גֶּרֶשׂ', '["geres"]', '["groats of"]', '["n-m"]', 'a kernel (collectively), i.e. grain beaten corn.', 'from an unused root meaning to husk;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3759}/[H3754]', 'lemma', 'heb', 'כַּרְמֶל', '["karmel"]', '["a garden-land","new corn"]', '["n-m"]', 'a planted field (garden, orchard, vineyard or park); by implication, garden produce full (green) ears (of corn), fruitful field (place), plentiful (field).', 'from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1061}/H9021/[H1069]', 'inflected', 'heb', 'בִּכּוּר', '["bikkûwr"]', '["first-fruits/ your"]', '["n-m"]', 'the first-fruits of the crop first fruit (-ripe (figuratively)), hasty fruit.', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1643>/H9024', 'inflected', 'heb', 'מגרשה', '["mi./gir.Sa/h"]', '["some of/ groats/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5347}/[H5344]', 'lemma', 'heb', 'נְקֵבָה', '["nᵉqêbâh"]', '["[is] female","a female","female"]', '["n-f"]', 'female (from the sexual form) female.', 'from 5344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7819A}/H9033/[H7819]', 'inflected', 'heb', 'שָׁחַט', '["shâchaṭ"]', '["and/ he cut throat/ its","and/ he will cut throat/ its","and/ they slaughtered/ him"]', '["v n-f"]', 'to slaughter (in sacrifice or massacre) kill, offer, shoot out, slay, slaughter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8002}/[H7999]', 'inflected', 'heb', 'שֶׁלֶם', '["shelem"]', '["the/ peace offering<s>","the/ peace offerings"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3689}/[H3688]', 'inflected', 'heb', 'כֶּסֶל', '["keçel"]', '["the/ loins"]', '["n-m"]', 'properly, fatness, i.e. by implication (literally) the loin (as the seat of the leaf fat) or (generally) the viscera; also (figuratively) silliness or (in a good sense) trust confidence, flank, folly, hope, loin.', 'from 3688;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5493G}/H9034/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["he removed/ her","he will remove/ it"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2077}/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["for the/ sacrifice","for/ sacrifice","to the/ sacrifice","to/ [the] sacrifices of","to/ a sacrifice of"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3775}/[H3532]', 'lemma', 'heb', 'כֶּשֶׂב', '["keseb"]', '["a sheep","a young ram","sheep<s>"]', '["n-m"]', 'a young sheep lamb.', 'apparently by transposition for 3532;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2459>/H9023', 'opaque', 'heb', 'חֶלֶב', '["cheleb"]', '["best of/ its","best/ its","fat/ its"]', '["n-m"]', 'fat, whether literally or figuratively; hence, the richest or choice part × best, fat(-ness), × finest, grease, marrow.', 'or חֵלֶב; from an unused root meaning to be fat;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0451}/[H422]', 'inflected', 'heb', 'אַלְיָה', '["ʼalyâh"]', '["the/ fat tail"]', '["n-f"]', 'the stout part, i.e. the fat tail of the Oriental sheep rump.', 'from 422 (in the original sense of strength);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8549I}/[H8552]', 'lemma', 'heb', 'תָּמִים', '["tâmîym"]', '["complete"]', '["a"]', 'entire (literally, figuratively or morally); also (as noun) integrity, truth without blemish, complete, full, perfect, sincerely (-ity), sound, without spot, undefiled, upright(-ly), whole.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6096}/[H6095]', 'inflected', 'heb', 'עָצֶה', '["ʻâtseh"]', '["the/ backbone"]', '["n-m"]', 'the spine (as giving firmness to the body) backbone.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6999A}/H9033/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["and/ he will make smoke/ it"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6999A}/H9038/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["and/ he will make smoke/ them"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0398}\/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["it will be eaten","you must eat","you will eat"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7684}/[H7683]', 'inflected', 'heb', 'שְׁגָגָה', '["shᵉgâgâh"]', '["by/ inadvertence"]', '["n-f"]', 'a mistake or inadvertent transgression error, ignorance, at unawares; unwittingly.', 'from 7683;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4687}/[H6680]', 'lemma', 'heb', 'מִצְוָה', '["mitsvâh"]', '["<of> a commandment","[the] command of","[the] commandment","[the] commandment of","[the] commandments of","[was] [the] command of","[was] [the] commandment of","a command","a commandment","a commandment of","commandments"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0259}/[H258]', 'inflected', 'heb', 'אֶחָד', '["ʼechâd"]', '["[is] from/ one of","any/ one","any/ one of","from/ one of"]', '["a"]', 'properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,', 'a numeral from 258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H9039}', 'inflected', 'heb', 'מהנה', '["me./He.nah","me./Hen"]', '["from/ them","more than/ them","of/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4899}/[H4886]', 'inflected', 'heb', 'מָשִׁיחַ', '["mâshîyach"]', '["<the>/ anointed"]', '["n-m"]', 'anointed; usually a consecrated person (as a king, priest, or saint); specifically, the Messiah anointed, Messiah.', 'from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0819}/[H817]', 'inflected', 'heb', 'אַשְׁמָה', '["ʼashmâh"]', '["<into>/ guilt","to/ [the] guilt of","to/ guilt"]', '["n-f"]', 'guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering).', 'feminine of 817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403B}/H9023/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sin/ his","sin/ its","sins/ his"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2403H}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["[is] for the/ sin offering","for/ a sin offering","to/ a sin offering"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0676}/H9023/[H6648]', 'inflected', 'heb', 'אֶצְבַּע', '["ʼetsbaʻ"]', '["finger/ his","fingers/ his"]', '["n-f"]', 'something to sieze with, i.e. a finger; by analogy, a toe finger, toe.', 'from the same as 6648 (in the sense of grasping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2403H}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["the/ sin offering"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6569}/H9023/[H6567]', 'inflected', 'heb', 'פֶּרֶשׁ', '["peresh"]', '["and/ offal/ its"]', '["n-m"]', 'excrement (as eliminated) dung.', 'from 6567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8211}/[H8210]', 'lemma', 'heb', 'שֶׁפֶךְ', '["shephek"]', '["[the] pouring out of"]', '["n-m"]', 'an emptying place, e.g. an ash-heap are poured out.', 'from 8210;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8313}\/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["it will be burned","she will be burned"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7686}/[H7686]', 'lemma', 'heb', 'שָׁגָה', '["shâgâh"]', '["I have erred","[one who] leads astray","[one who] staggers","[those who] go astray","[who] errs","have I erred","may you be intoxicated","they reeled","they wander","they will go astray","will you go astray","you will err"]', '["v"]', 'to stray (causatively, mislead), usually (figuratively) to mistake, especially (morally) to transgress; by extension (through the idea of intoxication) to reel, (figuratively) be enraptured (cause to) go astray, deceive, err, be ravished, sin through ignorance, (let, make to) wander.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5956}/[H5956]', 'inflected', 'heb', 'עָלַם', '["ʻâlam"]', '["and/ it has been concealed","and/ it will be hidden","and/ you will hide yourself"]', '["v"]', 'to veil from sight, i.e. conceal (literally or figuratively) × any ways, blind, dissembler, hide (self), secret (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5869A}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["from/ [the] eyes of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0816}/[H816]', 'inflected', 'heb', 'אָשַׁם', '["ʼâsham"]', '["and/ he became guilty","and/ he is guilty","and/ he will be guilty","and/ it will be guilty","and/ they have become guilty","and/ they have been held guilty","and/ they will be guilty","and/ you will be held guilty"]', '["v"]', 'to be guilty; by implication to be punished or perish × certainly, be(-come, made) desolate, destroy, × greatly, be(-come, found, hold) guilty, offend (acknowledge offence), trespass.', 'or אָשֵׁם; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2403B}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["the/ sin"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6499}/[H6565]', 'inflected', 'heb', 'פַּר', '["par"]', '["for the/ young bull","for the/ young bulls","to the/ bull","to the/ young bull","to/ [the] bull of"]', '["n-m"]', 'a bullock (apparently as breaking forth in wild strength, or perhaps as dividing the hoof) ( young) bull(-ock), calf, ox.', 'or פָּר; from 6565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8163B}/[H8175]', 'inflected', 'heb', 'שָׂעִיר', '["sâʻîyr"]', '["<the>/ hairy","the/ male goat","the/ male goats"]', '["a n-m"]', 'shaggy; as noun, a he-goat; by analogy, a faun devil, goat, hairy, kid, rough, satyr.', 'or שָׂעִר; from 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0676}/H9023/[H6648]', 'inflected', 'heb', 'אֶצְבַּע', '["ʼetsbaʻ"]', '["on/ finger/ his","with/ finger/ his","with/ fingers/ his"]', '["n-f"]', 'something to sieze with, i.e. a finger; by analogy, a toe finger, toe.', 'from the same as 6648 (in the sense of grasping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H2459>', 'inflected', 'heb', 'כחלב', '["ka./Che.lev","ke./Che.lev"]', '["like <the>/ fat","like/ [the] fat of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2403B}/H9023/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["from/ sin/ his"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5971A}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["from/ [the] people","from/ [the] people of","from/ [the] peoples of","from/ a people","from/ peoples","of/ [the] peoples of","one of/ [the] people of"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6213A}/H9044/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["when/ does/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4687}/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["of/ [the] commandments of"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8166}/[H8163]', 'lemma', 'heb', 'שְׂעִירָה', '["sᵉʻîyrâh"]', '["a female goat of"]', '["n-f"]', 'a she-goat kid.', 'feminine of 8163;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1818}/H9024/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["any of/ blood/ its","some of/ blood/ her","some of/ blood/ its"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1818}/H9024/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["blood/ her","blood/ its","blood<s>/ her","blood<s>/ its"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2459>/H9024', 'opaque', 'heb', 'חֶלֶב', '["cheleb"]', '["fat/ its"]', '["n-m"]', 'fat, whether literally or figuratively; hence, the richest or choice part × best, fat(-ness), × finest, grease, marrow.', 'or חֵלֶב; from an unused root meaning to be fat;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963K>', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["[the] sound of","a voice"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771G}/H9023/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquities/ his","iniquities/ its","iniquity/ his"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2931}/[H2930]', 'lemma', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["O unclean of","[are] unclean","[is] unclean","[person] unclean","[the] [woman] unclean of","[the] unclean","[thing] unclean of","a [person] unclean","a [person] unclean of","an unclean [thing]","unclean","unclean [food]","unclean [thing]","unclean of","unclean!"]', '["a"]', 'foul in a religious sense defiled, infamous, polluted(-tion), unclean.', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5038}/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["<in>/ a carcass of","with/ [the] corpse[s] of"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2932}/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["<in>/ [the] uncleanness of"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2932}/H9023/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["[is] uncleanness/ his","uncleanness/ his"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0981}/[H981]', 'inflected', 'heb', 'בָּטָא', '["bâṭâʼ"]', '["by/ speaking rashly"]', '["v"]', 'to babble; hence, to vociferate angrily pronounce, speak (unadvisedly).', 'or בָּטָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8193G}/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["on/ [the] lips of","with/ a lip","with/ lips"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3190}/[H3190]', 'inflected', 'heb', 'יָטַב', '["yâṭab"]', '["to/ do [it] well","to/ do good","to/ do good to"]', '["v"]', 'to be (causative) make well, literally (sound, beautiful) or figuratively (happy, successful, right) be accepted, amend, use aright, benefit, be (make) better, seem best, make cheerful, be comely, be content, diligent(-ly), dress, earnestly, find favour, give, be glad, do (be, make) good(-ness), be (make) merry, please ( well), shew more (kindness), skilfully, × very small, surely, make sweet, thoroughly, tire, trim, very, be (can, deal, entreat, go, have) well (said, seen).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0981}/[H981]', 'lemma', 'heb', 'בָּטָא', '["bâṭâʼ"]', '["[is one who] speaks rashly","he will speak rashly"]', '["v"]', 'to babble; hence, to vociferate angrily pronounce, speak (unadvisedly).', 'or בָּטָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7621}/[H7650]', 'inflected', 'heb', 'שְׁבוּעָה', '["shᵉbûwʻâh"]', '["by/ an oath","in/ an oath","with/ [the] oath of"]', '["n-f"]', 'properly, something sworn, i.e. an oath curse, oath, × sworn.', 'feminine passive participle of 7650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0816}/[H816]', 'lemma', 'heb', 'אָשַׁם', '["ʼâsham"]', '["certainly <to be guilty>","continually <be guilty>","he was guilty","he will be guilty","it become guilty","it will be held guilty","they will be guilty","they will be held guilty","we are guilty","you have become guilty","you will be guilty"]', '["v"]', 'to be guilty; by implication to be punished or perish × certainly, be(-come, made) desolate, destroy, × greatly, be(-come, found, hold) guilty, offend (acknowledge offence), trespass.', 'or אָשֵׁם; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3034}/[H3027]', 'inflected', 'heb', 'יָדָה', '["yâdâh"]', '["and/ I confessed","and/ he will confess","and/ they confessed","and/ they threw down","and/ they will confess","and/ they will praise"]', '["v"]', 'physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving).', 'a primitive root; used only as denominative from 3027; literally, to use (i.e. hold out) the hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0817}/H9023/[H816]', 'inflected', 'heb', 'אָשָׁם', '["ʼâshâm"]', '["compensation/ its","guilt offering/ his"]', '["n-m"]', 'guilt; by implication, a fault; also a sin-offering guiltiness, (offering for) sin, trespass (offering).', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3776}/[H3775]', 'lemma', 'heb', 'כִּשְׂבָּה', '["kisbâh"]', '["a ewe lamb"]', '["n-f"]', 'a young ewe lamb.', 'feminine of 3775;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027I}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ his","hands/ his","own hand/ his","side/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1767>', 'opaque', 'heb', 'דַּי', '["day"]', '["[is] sufficiency of","sufficiency","sufficiency of"]', '["prep"]', 'enough (as noun or adverb), used chiefly with preposition in phrases able, according to, after (ability), among, as (oft as), (more than) enough, from, in, since, (much as is) sufficient(-ly), too much, very, when.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8449}/[H8447]', 'lemma', 'heb', 'תּוֹר', '["tôwr"]', '["a turtle-dove","turtle-doves"]', '["n-f"]', 'a ring-dove, often (figuratively) as a term of endearment (turtle) dove.', 'or תֹּר; probably the same as 8447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3123}/[H3196]', 'lemma', 'heb', 'יוֹנָה', '["yôwnâh"]', '["[are] doves","a dove"]', '["n-f"]', 'a dove (apparently from the warmth of their mating) dove, pigeon.', 'probably from the same as 3196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6203}/H9023/[H6202]', 'inflected', 'heb', 'עֹרֶף', '["ʻôreph"]', '["neck/ his","neck/ its"]', '["n-m"]', 'the nape or back of the neck (as declining); hence, the back generally (whether literal or figurative) back ((stiff-) neck((-ed).', 'from 6202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4680}/[H4680]', 'lemma', 'heb', 'מָצָה', '["mâtsâh"]', '["it will be drained out","they are drained","they will drain","you have drained"]', '["v"]', 'to suck out; by implication, to drain, to squeeze out suck, wring (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027T}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H4503G>\', 'inflected', 'heb', 'כמנחה ס', '["ka./min.Chah"]', '["like the/ grain offering"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4603}/[H4603]', 'lemma', 'heb', 'מָעַל', '["mâʻal"]', '["did he act unfaithfully","he acted unfaithfully","he had acted unfaithfully","he has acted unfaithfully","it will act unfaithfully","they acted unfaithfully","they had acted unfaithfully","they have acted unfaithfully","unfaithfulness","we have acted unfaithfully","you acted unfaithfully","you have acted unfaithfully","you will act unfaithfully"]', '["v"]', 'properly, to cover up; used only figuratively, to act covertly, i.e. treacherously transgress, (commit, do a) trespass(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4604}/[H4603]', 'lemma', 'heb', 'מַעַל', '["maʻal"]', '["[the] unfaithfulness of","unfaithfulness"]', '["n-m"]', 'treachery, i.e. sin falsehood, grievously, sore, transgression, trespass, × very.', 'from 4603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6944G}/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["any of/ [the] holy thing of","from/ [the] holy thing of","from/ [the] holy things of","from/ [the] sanctuary"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6187}/H9021/[H6186]', 'inflected', 'heb', 'עֵרֶךְ', '["ʻêrek"]', '["by/ valuation of/ your","by/ valuation/ your"]', '["n-m"]', 'a pile, equipment, estimate equal, estimation, (things that are set in) order, price, proportion, × set at, suit, taxation, × valuest.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0817}/[H816]', 'inflected', 'heb', 'אָשָׁם', '["ʼâshâm"]', '["to/ a guilt offering"]', '["n-m"]', 'guilt; by implication, a fault; also a sin-offering guiltiness, (offering for) sin, trespass (offering).', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2549}/H9023/[H2568]', 'inflected', 'heb', 'חֲמִישִׁי', '["chămîyshîy"]', '["fifth/ its"]', '["a"]', 'fifth; also a fifth fifth (part).', 'or חֲמִשִּׁי; ordinal from 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0352A}/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["by/ [the] ram of","in the/ ram"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0817}/[H816]', 'inflected', 'heb', 'אָשָׁם', '["ʼâshâm"]', '["[is] the/ guilt offering","the/ compensation","the/ guilt offering"]', '["n-m"]', 'guilt; by implication, a fault; also a sin-offering guiltiness, (offering for) sin, trespass (offering).', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7684}/H9023/[H7683]', 'inflected', 'heb', 'שְׁגָגָה', '["shᵉgâgâh"]', '["inadvertence/ his"]', '["n-f"]', 'a mistake or inadvertent transgression error, ignorance, at unawares; unwittingly.', 'from 7683;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7683}/[H7683]', 'lemma', 'heb', 'שָׁגַג', '["shâgag"]', '["[one who] goes astray","[was] going astray","he has gone astray"]', '["v"]', 'to stray, i.e. (figuratively) sin (with more or less apology) × also for that, deceived, err, go astray, sin ignorantly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4603}/[H4603]', 'inflected', 'heb', 'מָעַל', '["mâʻal"]', '["and/ he acted unfaithfully","and/ it will act unfaithfully","and/ she has acted unfaithfully","and/ she will act unfaithfully","and/ they acted unfaithfully"]', '["v"]', 'properly, to cover up; used only figuratively, to act covertly, i.e. treacherously transgress, (commit, do a) trespass(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5997}/H9023/[H5997]', 'inflected', 'heb', 'עָמִית', '["ʻâmîyth"]', '["<in>/ fellow citizen/ his","on/ fellow citizen/ his","with/ fellow citizen/ his"]', '["n-m"]', 'companionship; hence (concretely) a comrade or kindred man another, fellow, neighbour.', 'from a primitive root meaning to associate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6487}/[H6485]', 'inflected', 'heb', 'פִּקָּדוֹן', '["piqqâdôwn"]', '["<in>/ an item entrusted"]', '["n-m"]', 'a deposit that which was delivered (to keep), store.', 'from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8667}/[H7760]', 'inflected', 'heb', 'תְּשׂוּמֶת', '["tᵉsûwmeth"]', '["<in>/ deposited property of"]', '["n-f"]', 'a deposit, i.e. pledging fellowship.', 'from 7760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1498}/[H1497]', 'inflected', 'heb', 'גָּזֵל', '["gâzêl"]', '["<in>/ a robbery"]', '["n-m"]', 'robbery, or (concretely) plunder robbery, thing taken away by violence.', 'from 1497;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6231}/[H6229]', 'lemma', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["[are] oppressed","[is] oppressed","[one who] oppresses","[the] oppressor","[those who] are oppressed","an oppressor","have I oppressed","he has extorted","he has oppressed","he oppressed","it is violent","oppressed","they have oppressed","you must oppress","you oppress","you will oppress"]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5997}/H9023/[H5997]', 'inflected', 'heb', 'עָמִית', '["ʻâmîyth"]', '["fellow citizen/ his"]', '["n-m"]', 'companionship; hence (concretely) a comrade or kindred man another, fellow, neighbour.', 'from a primitive root meaning to associate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1500}/[H1498]', 'inflected', 'heb', 'גְּזֵלָה', '["gᵉzêlâh"]', '["the/ thing robbed"]', '["n-f"]', 'that (he had robbed) (which he took violently away), spoil, violence.', 'feminine of 1498 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6233}/[H6231]', 'inflected', 'heb', 'עֹשֶׁק', '["ʻôsheq"]', '["<the>/ oppression","the/ oppression"]', '["n-m"]', 'injury, fraud, (subjectively) distress, (concretely) unjust gain cruelly, extortion, oppression, thing (deceitfully gotten).', 'from 6231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6487}/[H6485]', 'inflected', 'heb', 'פִּקָּדוֹן', '["piqqâdôwn"]', '["the/ item entrusted"]', '["n-m"]', 'a deposit that which was delivered (to keep), store.', 'from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0009}/[H6]', 'inflected', 'heb', 'אֲבֵדָה', '["ʼăbêdâh"]', '["the/ thing lost"]', '["n-f"]', 'concrete, something lost; abstract, destruction, i.e. Hades lost.', 'from 6; Compare 10.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8267}/[H8266]', 'inflected', 'heb', 'שֶׁקֶר', '["sheqer"]', '["into <the>/ falsehood","to <the>/ deception","to <the>/ falsehood"]', '["n-m"]', 'an untruth; by implication, a sham (often adverbial) without a cause, deceit(-ful), false(-hood, -ly), feignedly, liar, lie, lying, vain (thing), wrongfully.', 'from 8266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7999A}/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["and/ I will repay","and/ he completed","and/ he has remained unharmed","and/ he will repay","and/ he will restore","and/ it was complete","and/ they made peace","and/ they will be complete","and/ they will pay [it]"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7218J>/H9023', 'inflected', 'heb', 'בראשו', '["be./ro.Sh/o"]', '["in/ sum/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2549}/H9023/[H2568]', 'inflected', 'heb', 'חֲמִישִׁי', '["chămîyshîy"]', '["and/ fifth/ its","and/ fifth<s>/ its"]', '["a"]', 'fifth; also a fifth fifth (part).', 'or חֲמִשִּׁי; ordinal from 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0819}/H9023/[H817]', 'inflected', 'heb', 'אַשְׁמָה', '["ʼashmâh"]', '["guilt/ his"]', '["n-f"]', 'guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering).', 'feminine of 817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4169}/[H4168]', 'lemma', 'heb', 'מוֹקְדָה', '["môwqᵉdâh"]', '["[the] hearth"]', '["n-f"]', 'fuel burning.', 'feminine of 4168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3344}/[H3344]', 'lemma', 'heb', 'יָקַד', '["yâqad"]', '["[which] burns","it will burn"]', '["v"]', 'to burn (be) burn(-ing), × from the hearth, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4055}/H9023/[H4058]', 'inflected', 'heb', 'מַד', '["mad"]', '["garment/ his","garments/ his","robe/ his"]', '["n-m"]', 'properly, extent, i.e. height; also a measure; by implication, a vesture (as measured); also a carpet armour, clothes, garment, judgment, measure, raiment, stature.', 'or מֵד; from 4058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4370}/[H3647]', 'inflected', 'heb', 'מִכְנָס', '["miknâç"]', '["and/ undergarments of"]', '["n-m"]', '(only in dual) drawers (from concealing the private parts) breeches.', 'from 3647 in the sense of hiding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760H}/H9033/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ he will place/ it","and/ you will put/ it"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0784}/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["and/ the/ fire"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3518}/[H3518]', 'lemma', 'heb', 'כָּבָה', '["kâbâh"]', '["[one who] extinguishes [it]","[will be one who] extinguishes","it is extinguished","it was extinguished","it will be extinguished","it will be quenched","they were quenched","you will extinguish"]', '["v"]', 'to expire or (causatively) to extinguish (fire, light, anger) go (put) out, quench.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1197A}/[H1198]', 'inflected', 'heb', 'בָּעַר', '["bâʻar"]', '["and/ I will sweep away","and/ he burned","and/ he has burned","and/ he kindled","and/ he will kindle","and/ it burned","and/ it burned up","and/ it will burn","and/ they will burn","and/ they will kindle"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3518}\/[H3518]', 'inflected', 'heb', 'כָּבָה', '["kâbâh"]', '["[will be one who] extinguishes","it will be extinguished","it will be quenched"]', '["v"]', 'to expire or (causatively) to extinguish (fire, light, anger) go (put) out, quench.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7062}/H9023/[H7061]', 'inflected', 'heb', 'קֹמֶץ', '["qômets"]', '["in/ handful/ his"]', '["n-m"]', 'a grasp, i.e. handful handful.', 'from 7061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H5560>', 'inflected', 'heb', 'מסלת', '["mi./So.let"]', '["some of/ [the] fine flour of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3828}/[H3836]', 'inflected', 'heb', 'לְבוֹנָה', '["lᵉbôwnâh"]', '["<the>/ frankincense","the/ frankincense"]', '["n-f"]', 'frankincense (from its whiteness or perhaps that of its smoke) (frank-) incense.', 'or לְבֹנָה; from 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2691A}/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["[is] in the/ court","[was] in/ [the] courtyard of","[were] in the/ courtyard","[will be] in/ [the] courts of","in the/ court","in/ [the] court of","in/ [the] courts of","in/ [the] courtyard of","in/ [the] courtyards of"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2506A}/H9028/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["[whom] portion/ their","portion/ their","share/ their"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0801}/H9020/[H800]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["from/ fire offerings/ my"]', '["n-m"]', 'properly, a burnt-offering; but occasionally of any sacrifice (offering, sacrifice), (made) by fire.', 'the same as 800, but used in a liturgical sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2403H}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["as the/ sin offering","like the/ sin offering"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0817}/[H816]', 'inflected', 'heb', 'אָשָׁם', '["ʼâshâm"]', '["and/ like the/ guilt offering"]', '["n-m"]', 'guilt; by implication, a fault; also a sin-offering guiltiness, (offering for) sin, trespass (offering).', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4276}/H9024/[H2673]', 'inflected', 'heb', 'מַחֲצִית', '["machătsîyth"]', '["half/ its"]', '["n-f"]', 'a halving or the middle half (so much), mid(-day).', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4276}/H9024/[H2673]', 'inflected', 'heb', 'מַחֲצִית', '["machătsîyth"]', '["and/ half/ its"]', '["n-f"]', 'a halving or the middle half (so much), mid(-day).', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4227}/[H2281]', 'lemma', 'heb', 'מַחֲבַת', '["machăbath"]', '["a baking tray","a baking tray of"]', '["n-f"]', 'a pan for baking in pan.', 'from the same as 2281;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7246}/[H7246]', 'lemma', 'heb', 'רָבַךְ', '["râbak"]', '["mixed","mixed [dough]"]', '["v"]', 'to soak (bread in oil) baken, (that which is) fried.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8601}/[H644]', 'lemma', 'heb', 'תֻּפִין', '["tuphîyn"]', '["broken pieces of"]', '["n-m"]', 'cookery, i.e. (concretely) a cake baked piece.', 'from 644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2398}/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["which/ sins","who/ makes a sin offering"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1320}/H9024/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["<in>/ meat/ its","in/ flesh/ her"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5137A}/[H5137]', 'lemma', 'heb', 'נָזָה', '["nâzâh"]', '["he will spatter","spatter"]', '["v"]', 'to spirt, i.e. besprinkle (especially in expiation) sprinkle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2789}/[H2775]', 'lemma', 'heb', 'חֶרֶשׂ', '["cheres"]', '["a potsherd","earthenware","potsherd[s]","potsherds of"]', '["n-m"]', 'a piece of pottery earth(-en), (pot-) sherd, stone.', 'a collateral form mediating between 2775 and 2791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3627}/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["in <the>/ vessel","in the/ vessel","in/ [the] bag of","in/ a vessel","in/ a vessel of","in/ instruments of","in/ vessels of","with <the>/ instruments","with/ [the] instruments of","with/ [the] weapons of","with/ an instrument of","with/ instruments of","with/ vessels of"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4838}/[H4838]', 'inflected', 'heb', 'מָרַק', '["mâraq"]', '["and/ it will be scoured"]', '["v"]', 'to polish; by implication, to sharpen; also to rinse bright, furbish, scour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7857}/[H7857]', 'inflected', 'heb', 'שָׁטַף', '["shâṭaph"]', '["and/ I washed off","and/ he will overflow","and/ it will be rinsed","and/ it will overflow","and/ someone washed off"]', '["v"]', 'to gush; by implication, to inundate, cleanse; by analogy, to gallop, conquer drown, (over-) flow(-whelm, rinse, run, rush, (throughly) wash (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3548}/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["among the/ priests","on the/ priests","on/ [the] priests of"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0817}/[H816]', 'inflected', 'heb', 'אָשָׁם', '["ʼâshâm"]', '["as the/ guilt offering"]', '["n-m"]', 'guilt; by implication, a fault; also a sin-offering guiltiness, (offering for) sin, trespass (offering).', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7126H}/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["the/ [one who] brings near","the/ [one who] brought near","the/ [one who] presents","who/ presents"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8574H}/[H5216]', 'inflected', 'heb', 'תַּנּוּר', '["tannûwr"]', '["in <the>/ oven","in/ an oven"]', '["n-m"]', 'a fire-pot furnace, oven.', 'from 5216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4802}/[H7370]', 'inflected', 'heb', 'מַרְחֶשֶׁת', '["marchesheth"]', '["in <the>/ baking pan"]', '["n-f"]', 'a stewpan fryingpan.', 'from 7370;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2720A}/[H2717]', 'inflected', 'heb', 'חָרֵב', '["chârêb"]', '["and/ dry"]', '["a"]', 'parched or ruined desolate, dry, waste.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0251I}/H9023\/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["like/ brother/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8426}/[H3034]', 'lemma', 'heb', 'תּוֹדָה', '["tôwdâh"]', '["<of> a thank-offering","[the] thanksgiving of","a thank-offering","confession","praise","thank-offerings","thanksgiving","thanksgiving choirs"]', '["n-f"]', 'properly, an extension of the hand, i.e. (by implication) avowal, or (usually) adoration; specifically, a choir of worshippers confession, (sacrifice of) praise, thanks(-giving, offering).', 'from 3034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8426}/[H3034]', 'inflected', 'heb', 'תּוֹדָה', '["tôwdâh"]', '["<the>/ thanksgiving","the/ thanksgiving choirs"]', '["n-f"]', 'properly, an extension of the hand, i.e. (by implication) avowal, or (usually) adoration; specifically, a choir of worshippers confession, (sacrifice of) praise, thanks(-giving, offering).', 'from 3034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5560>', 'inflected', 'heb', 'וסלת', '["ve./So.let"]', '["and/ fine flour"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8002}/H9023/[H7999]', 'inflected', 'heb', 'שֶׁלֶם', '["shelem"]', '["peace offering<s>/ his","peace offerings/ his"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2236}/[H2236]', 'inflected', 'heb', 'זָרַק', '["zâraq"]', '["who/ sprinkles"]', '["v"]', 'to sprinkle (fluid or solid particles) be here and there, scatter, sprinkle, strew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7126H}/H9043/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["presents/ he"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2077}/H9023/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["sacrifice/ his"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4283}/[H4279]', 'inflected', 'heb', 'מׇחֳרָת', '["mochŏrâth"]', '["and/ from/ [the] next day"]', '["n-f"]', 'the morrow or (adverbially) tomorrow morrow, next day.', 'or מׇחֳרָתָם; (1 Samuel 30:17), feminine from the same as 4279;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2077}/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["<of> the/ sacrifice","the/ sacrifice","the/ sacrifices"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7521}/[H7521]', 'lemma', 'heb', 'רָצָה', '["râtsâh"]', '["I will accept","I will accept [them]","[is] taking pleasure","[is] taking pleasure in","[the] favored [one] of","[whom] he is pleased with","[whom] it is pleased with","accept","be pleased","he has taken pleasure in","he takes pleasure","he takes pleasure in","he took pleasure","he will be accepted","it has accepted","it has been accepted","it will accept","it will be accepted","they are pleased with","they take delight","they take pleasure in","they will accept","they will be accepted","they will seek [the] favor of","will he make himself acceptable","you are pleased with","you showed favor to","you will be pleased with"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6292>', 'opaque', 'heb', 'פִּגּוּל', '["piggûwl"]', '["[is] unclean meat","unclean meat","unclean meat<s>"]', '["n-m"]', 'properly, fetid, i.e. (figuratively) unclean (ceremonially) abominable(-tion, thing).', 'or פִּגֻּל; from an unused root meaning to stink;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5315I}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ the/ person"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771G}/H9024/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["guilt/ her","iniquity/ its"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1320}/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["and/ the/ flesh","and/ the/ meat"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5315J}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ the/ person"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2932}/H9023/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["and/ uncleanness/ his"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8263}/[H8262]', 'lemma', 'heb', 'שֶׁקֶץ', '["sheqets"]', '["[are] a detestable thing","[are] detestable thing[s]","[is] a detestable thing","detestable thing"]', '["n-m"]', 'filth, i.e. (figuratively and specifically) an idolatrous object abominable(-tion).', 'from 8262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5971B}/H9024\/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["from/ kinspeople<s>/ its"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3775}/[H3532]', 'inflected', 'heb', 'כֶּשֶׂב', '["keseb"]', '["and/ a young ram"]', '["n-m"]', 'a young sheep lamb.', 'apparently by transposition for 3532;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2459>', 'inflected', 'heb', 'וחלב', '["ve./Che.lev"]', '["and/ [the] fat","and/ [the] fat of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5038}/[H5034]', 'lemma', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["[the] corpse of","[the] corpse[s] of","a carcass","carcass"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5775}/[H5774]', 'inflected', 'heb', 'עוֹף', '["ʻôwph"]', '["for/ [the] bird[s] of","of <the>/ bird[s]","to/ [the] bird[s] of"]', '["n-m"]', 'a bird (as covered with feathers, or rather as covering with wings), often collectively bird, that flieth, flying, fowl.', 'from 5774;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0929>', 'inflected', 'heb', 'ולבהמה', '["u./le./ve.he.Mat","ve./la./be.he.Mah"]', '["and/ for/ [the] animal[s] of","and/ of <the>/ livestock","and/ to the/ animal[s]","and/ to the/ cattle","and/ to/ [the] animal[s] of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315I}/[H5314]', 'lemma', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["[the] self of","a person","a person of","life","person","self","soul"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5130B}/[H5130]', 'inflected', 'heb', 'נוּף', '["nûwph"]', '["for/ shaking","to/ wave"]', '["v"]', 'to quiver (i.e. vibrate up and down, or rock to and fro); used in a great variety of applications (including sprinkling, beckoning, rubbing, bastinadoing, sawing, waving, etc.) lift up, move, offer, perfume, send, shake, sift, strike, wave.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8002}/H9026/[H7999]', 'inflected', 'heb', 'שֶׁלֶם', '["shelem"]', '["peace offerings/ your"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1121A}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["[were] of/ [the] descendants of","any of/ [the] sons of","from/ [the] children of","from/ [the] descendants of","from/ [the] sons of","more than/ [the] children of","more than/ [the] sons","more than/ sons","of/ [the] sons of","one of/ [the] sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4888A}/[H4886]', 'inflected', 'heb', 'מִשְׁחָה', '["mishchâh"]', '["and/ [the] share of"]', '["n-f"]', 'unction (the act); by implication, a consecratory gift (to be) anointed(-ing), ointment.', 'or מׇשְׁחָה; from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4886}/H9043/[H4886]', 'inflected', 'heb', 'מָשַׁח', '["mâshach"]', '["anointed/ he"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H4503G>', 'inflected', 'heb', 'למנחה', '["la./min.Chah","le./min.Chah","le./min.Chat"]', '["<to>/ [the] offering of","for the/ grain offering","for/ a grain offering","for/ grain offering","to the/ grain offering","to/ a grain offering"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2403H}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ for the/ sin offerings","and/ to the/ sin offering"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0817}/[H816]', 'inflected', 'heb', 'אָשָׁם', '["ʼâshâm"]', '["and/ to the/ guilt offering"]', '["n-m"]', 'guilt; by implication, a fault; also a sin-offering guiltiness, (offering for) sin, trespass (offering).', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4394}/[H4390]', 'inflected', 'heb', 'מִלֻּא', '["milluʼ"]', '["and/ to the/ installation offering<s>"]', '["n-m"]', 'a fulfilling (only in plural), i.e. (literally) a setting (of gems), or (technically) consecration (also concretely, a dedicatory sacrifice) consecration, be set.', 'from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2077}/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["and/ for/ sacrifice","and/ to/ [the] sacrifice of"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6680}/H9043/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["commanded/ he"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7126H}/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["to/ bring near","to/ present"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7133A}/H9028/[H7126]', 'inflected', 'heb', 'קׇרְבָּן', '["qorbân"]', '["offering/ their","presents/ their"]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4057G}/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["in/ [the] wilderness of"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5514G>\', 'opaque', 'heb', 'סִינַי', '["Çîynay"]', '["Sinai"]', '["n-pr-loc"]', 'Sinai, mountain of Arabia Sinai.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6950}/[H6950]', 'lemma', 'heb', 'קָהַל', '["qâhal"]', '["assemble","have you assembled","he called together","they assembled","they summoned"]', '["v"]', 'to convoke assemble (selves) (together), gather (selves) (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0073>', 'inflected', 'heb', 'באבנט', '["ba./''av.Net"]', '["with the/ sash"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6942G}/H9038/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["to/ set apart as holy/ them"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8081}/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["from/ fatness","from/ oil","more than/ oil","more than/ ointment","some of/ [the] oil of"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3332G}/[H3332]', 'lemma', 'heb', 'יָצַק', '["yâtsaq"]', '["I will pour out","[has been] poured out","[was] pouring out","he poured","he will pour","he will pour out","it has been poured","it was poured","it was poured out","pour","pour [it] out"]', '["v"]', 'properly, to pour out (transitive or intransitive); by implication, to melt or cast as metal; by extension, to place firmly, to stiffen or grow hard cast, cleave fast, be (as) firm, grow, be hard, lay out, molten, overflow, pour (out), run out, set down, stedfast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2459>/H9029', 'opaque', 'heb', 'חֶלֶב', '["cheleb"]', '["fat/ their"]', '["n-m"]', 'fat, whether literally or figuratively; hence, the richest or choice part × best, fat(-ness), × finest, grease, marrow.', 'or חֵלֶב; from an unused root meaning to be fat;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3767}/[H3766]', 'inflected', 'heb', 'כָּרָע', '["kârâʻ"]', '["the/ legs"]', '["n-f"]', 'the leg (from the knee to the ankle) of men or locusts (only in the dual) leg.', 'from 3766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0241G}/H9028/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["ear/ their","ears/ their"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5536}/[H5549]', 'inflected', 'heb', 'סַל', '["çal"]', '["and/ from/ [the] basket of"]', '["n-m"]', 'properly, a willow twig (as pendulous), i.e. an osier; but only as woven into a basket basket.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709G}/H9028/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["hands/ their","palms/ their"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5130B}/H9033/[H5130]', 'inflected', 'heb', 'נוּף', '["nûwph"]', '["and/ he waved/ it"]', '["v"]', 'to quiver (i.e. vibrate up and down, or rock to and fro); used in a great variety of applications (including sprinkling, beckoning, rubbing, bastinadoing, sawing, waving, etc.) lift up, move, offer, perfume, send, shake, sift, strike, wave.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1320}/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["<in> the/ meat","<in>/ [the] flesh of","in the/ meat"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3899H}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["and/ in the/ bread"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6607}/[H6605]', 'inflected', 'heb', 'פֶּתַח', '["pethach"]', '["and/ from/ [the] entrance of"]', '["n-m"]', 'an opening (literally), i.e. door (gate) or entrance way door, entering (in), entrance (-ry), gate, opening, place.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4394}/H9026/[H4390]', 'inflected', 'heb', 'מִלֻּא', '["milluʼ"]', '["installation/ your"]', '["n-m"]', 'a fulfilling (only in plural), i.e. (literally) a setting (of gems), or (technically) consecration (also concretely, a dedicatory sacrifice) consecration, be set.', 'from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3117L>', 'inflected', 'heb', 'ביום', '["Ba/i.yom","ba/i.Yom"]', '["on the/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4931}/[H4929]', 'lemma', 'heb', 'מִשְׁמֶרֶת', '["mishmereth"]', '["<of> [the] charge of","<of> [the] service of","<the> guards of","[are] in good care","[is] [the] duty of","[the] charge of","[the] duty of","[the] service of","[the] watch of","a duty","confinement","duties","duty"]', '["n-f"]', 'watch, i.e. the act (custody), or (concretely) the sentry, the post; objectively preservation, or (concretely) safe; figuratively observance, i.e. (abstractly) duty or (objectively) a usage or party charge, keep, or to be kept, office, ordinace, safeguard, ward, watch.', 'feminine of 4929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2205G}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["and/ <to>/ [the] elders of"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7126H}/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["and/ present [them]"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5695}/[H5696]', 'inflected', 'heb', 'עֵגֶל', '["ʻêgel"]', '["and/ a male calf","and/ calf","and/ calves"]', '["n-m"]', 'a (male) calf (as frisking round), especially one nearly grown (i.e. a steer) bullock, calf.', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3532>', 'inflected', 'heb', 'וכבשים', '["u./khe.va.Sim","va./Khe.ves","ve./Khe.ves"]', '["and/ a lamb","and/ a male lamb","and/ lambs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7794}/[H7788]', 'inflected', 'heb', 'שׁוֹר', '["shôwr"]', '["and/ an ox","and/ ox[en]"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8002}/[H7999]', 'inflected', 'heb', 'שֶׁלֶם', '["shelem"]', '["to/ a peace offering<s>","to/ peace offerings"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6213I}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ offer","so/ we may prepare"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403H}/H9021/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sin offering/ your"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3722A}/[H3722]', 'inflected', 'heb', 'כָּפַר', '["kâphar"]', '["and/ atone","and/ make atonement"]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1157}/[H5704]', 'inflected', 'heb', 'בְּעַד', '["bᵉʻad"]', '["and/ behind","and/ for"]', '["prep"]', 'in up to or over against; generally at, beside, among, behind, for, etc. about, at by (means of), for, over, through, up (-on), within.', 'from 5704 with prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1157}/H9038/[H5704]', 'inflected', 'heb', 'בְּעַד', '["bᵉʻad"]', '["behind/ them","for/ them"]', '["prep"]', 'in up to or over against; generally at, beside, among, behind, for, etc. about, at by (means of), for, over, through, up (-on), within.', 'from 5704 with prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5785}/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["<the>/ hide","the/ hide","the/ skin"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2398}/H9033/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["and/ he made a sin offering/ it","and/ he will cleanse from sin/ him"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6213I}/H9034/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ he offered/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4374}/[H3680]', 'inflected', 'heb', 'מְכַסֶּה', '["mᵉkaççeh"]', '["and/ the/ covering"]', '["n-m"]', 'a covering, i.e. garment; specifically, a coverlet (for a bed), an awning (from the sun); also the omentum (as covering the intestines) clothing, to cover, that which covereth.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3629}/[H3627]', 'inflected', 'heb', 'כִּלְיָה', '["kilyâh"]', '["and/ the/ kidneys"]', '["n-f"]', 'a kidney (as an essential organ); figuratively, the mind (as the interior self) kidneys, reins.', 'feminine of 3627 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3508}/[H3498]', 'inflected', 'heb', 'יֹתֶרֶת', '["yôthereth"]', '["and/ [the] lobe of"]', '["n-f"]', 'the lobe or flap of the liver (as if redundant or outhanging) caul.', 'feminine active participle of 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375P}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ I lifted up","and/ he lifted up","and/ he raised","and/ they will bear"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027S}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ his","hands/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6213I}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["from/ when offered"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5930A}/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["and/ the/ burnt offering","and/ the/ burnt offerings"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8002}/[H7999]', 'inflected', 'heb', 'שֶׁלֶם', '["shelem"]', '["and/ the/ peace offerings"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318L}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ he brought out","and/ he went out","and/ it came out","and/ it went out","and/ it will go forth","and/ they came out","and/ you will bring out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7442B}/[H7442]', 'inflected', 'heb', 'רָנַן', '["rânan"]', '["and/ they shouted","and/ they will cry out for joy"]', '["v"]', 'properly, to creak (or emit a stridulous sound), i.e. to shout (usually for joy) aloud for joy, cry out, be joyful (greatly, make to) rejoice, (cause to) shout (for joy), (cause to) sing (aloud, for joy, out), triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440H}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["faces/ their"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4289}/H9023/[H4288]', 'inflected', 'heb', 'מַחְתָּה', '["machtâh"]', '["censer/ his"]', '["n-f"]', 'a pan for live coals censer, firepan, snuffdish.', 'the same as 4288 in the sense of removal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7138}/H9020/[H7126]', 'inflected', 'heb', 'קָרוֹב', '["qârôwb"]', '["in/ midst/ my"]', '["a"]', 'near (in place, kindred or time) allied, approach, at hand, any of kin, kinsfold(-sman), (that is) near (of kin), neighbour, (that is) next, (them that come) nigh (at hand), more ready, short(-ly).', 'or קָרֹב; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1826H}/[H1724]', 'inflected', 'heb', 'דָּמַם', '["dâmam"]', '["and/ I was silent","and/ he was silent"]', '["v"]', 'to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait.', 'a primitive root (compare 1724, 1820);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0469G}/[H410]', 'lemma', 'heb', 'אֱלִיצָפָן', '["ʼĔlîytsâphân"]', '["Elizaphan","Elzaphan","[was] Elizaphan"]', '["n-pr-m"]', 'Elitsaphan or Eltsaphan, an Israelite Elizaphan, Elzaphan.', 'or (shortened) אֶלְצָפָן; from 410 and 6845; God of treasure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730I>', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["[the] uncle of"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375H}/H9038/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ he carried off/ them","and/ he carried/ them","and/ they carried/ them"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3801>/H9028', 'inflected', 'heb', 'בכתנתם', '["be./khu.to.no.Ta/m"]', '["in/ tunics/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0499G}/[H410]', 'inflected', 'heb', 'אֶלְעָזָר', '["ʼElʻâzâr"]', '["and/ to/ Eleazar"]', '["n-pr-m"]', 'Elazar, the name of seven Israelites Eleazar.', 'from 410 and 5826; God (is) helper;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0385}/[H339]', 'inflected', 'heb', 'אִיתָמָר', '["ʼÎythâmâr"]', '["and/ to/ Ithamar"]', '["n-pr-m"]', 'Ithamar, a son of Aaron Ithamar.', 'from 339 and 8558; coast of the palm-tree;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218A>/H9026', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ your","heads/ your"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0899B}/H9026/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["and/ garments/ your"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6533}/[H6533]', 'lemma', 'heb', 'פָּרַם', '["pâram"]', '["he will tear","torn","you must tear"]', '["v"]', 'to tear rend.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251G}/H9026/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ relatives/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8316}/[H8313]', 'inflected', 'heb', 'שְׂרֵפָה', '["sᵉrêphâh"]', '["the/ burning"]', '["n-f"]', 'cremation burning.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7941}/[H7937]', 'inflected', 'heb', 'שֵׁכָר', '["shêkâr"]', '["and/ strong drink"]', '["n-m"]', 'an intoxicant, i.e. intensely alcoholic liquor strong drink, drunkard, strong wine.', 'from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0935G}/H9046/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ come/ you","when/ go/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2455}/[H2490]', 'inflected', 'heb', 'חֹל', '["chôl"]', '["the/ profane thing"]', '["n-m"]', 'properly, exposed; hence, profane common, profane (place), unholy.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2931}/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["<the>/ unclean","<the>/ unclean [thing]","[are] the/ unclean","[is] the/ unclean","the/ unclean","the/ unclean [person]","the/ unclean [thing]","the/ unclean [things]"]', '["a"]', 'foul in a religious sense defiled, infamous, polluted(-tion), unclean.', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0398}/H9034/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ eat/ it","and/ they will eat/ it"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706H}/H9021/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["[is] prescribed portion/ your","prescribed portion/ your"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2706H}/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["and/ [the] prescribed portion of","and/ an allotted portion"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2373}/[H2372]', 'inflected', 'heb', 'חָזֶה', '["châzeh"]', '["and/ [the] breast of"]', '["n-m"]', 'the breast (as most seen in front) breast.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1121A}/H9021/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ for/ children/ your","and/ for/ sons/ your","and/ of/ children/ your","and/ to/ son/ your","and/ to/ sons/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0853}/H9034/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ <obj.>/ her","and/ <obj.>/ it"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5375J}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["to/ bear"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6441}/[H6440]', 'lemma', 'heb', 'פְּנִימָה', '["pᵉnîymâh"]', '["within"]', '["adv"]', 'faceward, i.e. indoors (with-) in(-ner part, -ward).', 'from 6440 with directive enclitic;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5930A}/H9028/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["burnt offering/ their","burnt offerings/ their"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7122I}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ it will happen to","and/ they have happened to","and/ you have caused to happen to"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3190}/[H3190]', 'inflected', 'heb', 'יָטַב', '["yâṭab"]', '["¿/ rightly <do well>","¿/ will it be good"]', '["v"]', 'to be (causative) make well, literally (sound, beautiful) or figuratively (happy, successful, right) be accepted, amend, use aright, benefit, be (make) better, seem best, make cheerful, be comely, be content, diligent(-ly), dress, earnestly, find favour, give, be glad, do (be, make) good(-ness), be (make) merry, please ( well), shew more (kindness), skilfully, × very small, surely, make sweet, thoroughly, tire, trim, very, be (can, deal, entreat, go, have) well (said, seen).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869I}/H9023\/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ his"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6536}/[H6536]', 'lemma', 'heb', 'פָּרַס', '["pâraç"]', '["[is it] to break","[is] dividing","[is] dividing in two","[one which] divides in two","[which] divides","having hooves","it divides in two","people will break","they divide"]', '["v"]', 'to break in pieces, i.e. (usually without violence) to split, distribute deal, divide, have hoofs, part, tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8156}/[H8156]', 'inflected', 'heb', 'שָׁסַע', '["shâçaʻ"]', '["and/ [is] cleaving","and/ [which] cleaves"]', '["v"]', 'to split or tear; figuratively, to upbraid cleave, (be) cloven (footed), rend, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8157}/[H8156]', 'lemma', 'heb', 'שֶׁסַע', '["sheçaʻ"]', '["<of> a cleft of","a cleft of"]', '["n-m"]', 'a fissure cleft, clovenfooted.', 'from 8156;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927M}/[H5927]', 'lemma', 'heb', 'עָלָה', '["ʻâlâh"]', '["[is] bringing up","[which] brings up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1625}/[H1641]', 'lemma', 'heb', 'גֵּרָה', '["gêrâh"]', '["<of> cud","cud"]', '["n-f"]', 'the cud (as scraping the throat) cud.', 'from 1641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5927M}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["any of/ [those which] bring up","from/ [those which] bring up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1625}/[H1641]', 'inflected', 'heb', 'גֵּרָה', '["gêrâh"]', '["<of> the/ cud"]', '["n-f"]', 'the cud (as scraping the throat) cud.', 'from 1641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6536}/[H6536]', 'inflected', 'heb', 'פָּרַס', '["pâraç"]', '["and/ [any] of/ those dividing","and/ from/ [those which] divide in two"]', '["v"]', 'to break in pieces, i.e. (usually without violence) to split, distribute deal, divide, have hoofs, part, tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6541}/[H6538]', 'inflected', 'heb', 'פַּרְסָה', '["parçâh"]', '["<of> the/ hoof"]', '["n-f"]', 'a claw or split hoof claw, (cloven-) footed, hoof.', 'feminine of 6538;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6541}/[H6538]', 'inflected', 'heb', 'פַּרְסָה', '["parçâh"]', '["and/ a hoof","and/ hooves of"]', '["n-f"]', 'a claw or split hoof claw, (cloven-) footed, hoof.', 'feminine of 6538;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8227A}/[H8226]', 'inflected', 'heb', 'שָׁפָן', '["shâphân"]', '["the/ rock badger"]', '["n-m n-pr-m"]', 'a species of rock-rabbit (from its hiding), i.e. probably the hyrax coney.', 'from 8226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0768>', 'inflected', 'heb', 'הארנבת', '["ha./''ar.Ne.vet"]', '["the/ hare"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2386>', 'inflected', 'heb', 'החזיר', '["Ha./cha.zir","ha./cha.Zir"]', '["the/ pig"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1641}/[H1641]', 'lemma', 'heb', 'גָּרַר', '["gârar"]', '["it ruminates","sawn","staying as a sojourner","they assemble themselves"]', '["v"]', 'to drag off roughly; by implication, to bring up the cud (i.e. ruminate); by analogy, to saw catch, chew, × continuing, destroy, saw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1320}/H9028/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["any of/ meat/ their","from/ flesh/ their"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5038}/H9028/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["and/ <in>/ carcass/ their"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5579>', 'opaque', 'heb', 'סְנַפִּיר', '["çᵉnappîyr"]', '["fin"]', '["n-m"]', 'a fin (collectively) fins.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7193>', 'inflected', 'heb', 'וקשקשת', '["ve./kas.Ke.set"]', '["and/ scale"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5158A}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["and/ in the/ wadis"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8263}/[H8262]', 'inflected', 'heb', 'שֶׁקֶץ', '["sheqets"]', '["and/ detestable thing[s]"]', '["n-m"]', 'filth, i.e. (figuratively and specifically) an idolatrous object abominable(-tion).', 'from 8262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5038}/H9028/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["carcass/ their","corpse/ their","corpse[s]/ their"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8262}/[H8262]', 'lemma', 'heb', 'שָׁקַץ', '["shâqats"]', '["he has detested","utterly <detest>","you make detestable","you will consider detestable","you will make detestable"]', '["v"]', 'to be filthy, i.e. (intensively) to loathe, pollute abhor, make abominable, have in abomination, detest, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5404>', 'inflected', 'heb', 'הנשר', '["ha./Na.sher","ha./Ne.sher"]', '["<the>/ eagle","the/ eagle"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6538}/[H6536]', 'inflected', 'heb', 'פֶּרֶס', '["pereç"]', '["the/ bearded vulture"]', '["n-m"]', 'a claw; also a kind of eagle claw, ossifrage.', 'from 6536;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5822}/[H5797]', 'inflected', 'heb', 'עׇזְנִיָּה', '["ʻoznîyâh"]', '["the/ osprey"]', '["n-f"]', 'probably the sea-eagle (from its strength) ospray.', 'probably feminine of 5797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1676}/[H1675]', 'inflected', 'heb', 'דָּאָה', '["dâʼâh"]', '["the/ black kite"]', '["n-f"]', 'the kite (from its rapid flight) vulture. See 7201.', 'from 1675;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0344}/[H337]', 'inflected', 'heb', 'אַיָּה', '["ʼayâh"]', '["the/ hawk"]', '["n-f"]', 'the screamer, i.e. a hawk kite, vulture.', 'perhaps from 337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6158}/[H6150]', 'lemma', 'heb', 'עֹרֵב', '["ʻôrêb"]', '["[the] ravens of","a raven","raven"]', '["n-m"]', 'a raven (from its dusky hue) raven.', 'or עוֹרֵב; from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3284}/[H3283]', 'inflected', 'heb', 'יַעֲנָה', '["yaʻănâh"]', '["the/ ostrich"]', '["n-f"]', 'owl.', 'feminine of 3283, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8464}/[H2554]', 'inflected', 'heb', 'תַּחְמָס', '["tachmâç"]', '["the/ screech owl"]', '["n-m"]', 'a species of unclean bird (from its violence), perhaps an owl night hawk.', 'from 2554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7828>', 'inflected', 'heb', 'השחף', '["ha./Sha.chaf"]', '["the/ gull"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5322B}/[H5340]', 'inflected', 'heb', 'נֵץ', '["nêts"]', '["the/ falcon"]', '["n-m"]', 'a flower (from its brilliancy); also a hawk (from it flashing speed) blossom, hawk.', 'from 5340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3563B>', 'inflected', 'heb', 'הכוס', '["ha./Kos"]', '["the/ little owl"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7994}/[H7993]', 'inflected', 'heb', 'שָׁלָךְ', '["shâlâk"]', '["the/ cormorant"]', '["n-m"]', 'bird of prey, usually thought to be the pelican (from casting itself into the sea) cormorant.', 'from 7993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3244}/[H5398]', 'inflected', 'heb', 'יַנְשׁוּף', '["yanshûwph"]', '["the/ great owl"]', '["n-m"]', 'an unclean (acquatic) bird; probably the heron (perhaps from its blowing cry, or because the nightheron is meant) (great) owl.s', 'or יַנְשׁוֹף; apparently from 5398; (compare 5399)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8580}/[H5395]', 'inflected', 'heb', 'תַּנְשֶׁמֶת', '["tanshemeth"]', '["the/ barn owl"]', '["n-f"]', 'properly, a hard breather, i.e. the name of two unclean creatures, a lizard and a bird (both perhaps from changing color through their irascibility), probably the tree-toad and the water-hen mole, swan.', 'from 5395;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6893}/[H6958]', 'inflected', 'heb', 'קָאַת', '["qâʼath"]', '["the/ desert owl"]', '["n-f"]', 'probably the pelican (from vomiting) cormorant.', 'from 6958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7360}/[H7355]', 'inflected', 'heb', 'רָחָם', '["râchâm"]', '["the/ Egyptian vulture"]', '["n-m"]', 'a kind of vulture (supposed to be tender towards its young) gier-eagle.', 'or (feminine) רָחָמָה; from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2624}/[H2623]', 'inflected', 'heb', 'חֲסִידָה', '["chăçîydâh"]', '["<the>/ stork","the/ stork"]', '["n-f"]', 'the kind (maternal) bird, i.e. a stork × feather, stork.', 'feminine of 2623;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0601}/[H599]', 'inflected', 'heb', 'אֲנָפָה', '["ʼănâphâh"]', '["the/ heron"]', '["n-f"]', 'an unclean bird, perhaps the parrot (from its irascibility) heron.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1744>', 'inflected', 'heb', 'הדוכיפת', '["ha./du.khi.Fat"]', '["the/ hoopoe"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5847>', 'inflected', 'heb', 'העטלף', '["ha./''a.ta.Lef"]', '["the/ bat"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9036}\', 'inflected', 'heb', 'לכם ס', '["la./Khem"]', '["[belongs] to <the>/ you","for <the>/ you","for/ you","of <the>/ you","of/ you","to <the>/ you","to/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3767}/[H3766]', 'lemma', 'heb', 'כָּרָע', '["kârâʻ"]', '["legs"]', '["n-f"]', 'the leg (from the knee to the ankle) of men or locusts (only in the dual) leg.', 'from 3766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5425A}/[H5425]', 'inflected', 'heb', 'נָתַר', '["nâthar"]', '["to/ hop"]', '["v"]', 'to jump, i.e. be violently agitated; causatively, to terrify, shake off, untie drive asunder, leap, (let) loose, × make, move, undo.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5556}/[H5553]', 'inflected', 'heb', 'סׇלְעָם', '["çolʻâm"]', '["the/ locust"]', '["n-m"]', 'a kind of locust (from its destructiveness) bald locust.', 'apparently from the same as 5553 in the sense of crushing as with a rock, i.e. consuming;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2728}/[H2727]', 'inflected', 'heb', 'חָרְגֹּל', '["chârᵉgôl"]', '["the/ locust"]', '["n-m"]', 'the leaping insect, i.e. a locust beetle.', 'from 2727;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2284>', 'inflected', 'heb', 'החגב', '["he./cha.Gav"]', '["the/ grasshopper"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0428}/[H411]', 'inflected', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["and/ to/ these"]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5038}/H9028/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["<in>/ carcass/ their"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5375H}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["<the>/ [one who] carries","those/ [who] carry","who/ carry","who/ have been borne","who/ were carrying"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5038}/H9028/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["any of/ carcass/ their"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2930A}/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["and/ I made unclean","and/ he made unclean","and/ he will be unclean","and/ he will declare unclean","and/ he will make unclean","and/ it became unclean","and/ it will be unclean","and/ she became unclean","and/ she will be unclean","and/ she will make herself unclean","and/ they became unclean","and/ they defiled","and/ they made unclean","and/ they will be unclean","and/ you made unclean","and/ you will make unclean","and/ you will make yourselves unclean"]', '["v"]', 'to be foul, especially in a ceremial or moral sense (contaminated) defile (self), pollute (self), be (make, make self, pronounce) unclean, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8157}/[H8156]', 'inflected', 'heb', 'שֶׁסַע', '["sheçaʻ"]', '["and/ a cleft"]', '["n-m"]', 'a fissure cleft, clovenfooted.', 'from 8156;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8156}/[H8156]', 'lemma', 'heb', 'שָׁסַע', '["shâçaʻ"]', '["[is] cleaving"]', '["v"]', 'to split or tear; figuratively, to upbraid cleave, (be) cloven (footed), rend, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1625}/[H1641]', 'inflected', 'heb', 'גֵּרָה', '["gêrâh"]', '["and/ cud"]', '["n-f"]', 'the cud (as scraping the throat) cud.', 'from 1641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709H}/H9023/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["paws/ its"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5375H}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ the/ [ones who] were carrying","and/ who/ [-ever] carries"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8318}/[H8317]', 'inflected', 'heb', 'שֶׁרֶץ', '["sherets"]', '["among the/ swarming thing[s]"]', '["n-m"]', 'a swarm, i.e. active mass of minute animals creep(-ing thing), move(-ing creature).', 'from 8317;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2467}/[H2465]', 'inflected', 'heb', 'חֹלֶד', '["chôled"]', '["the/ weasel"]', '["n-m"]', 'a weasel (from its gliding motion) weasel.', 'from the same as 2465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5909}/[H5908]', 'inflected', 'heb', 'עַכְבָּר', '["ʻakbâr"]', '["and/ the/ mouse"]', '["n-m"]', 'a mouse (as nibbling) mouse.', 'probably from the same as 5908 in the secondary sense of attacking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H6632B>', 'inflected', 'heb', 'והצב', '["ve./ha./Tzav"]', '["and/ the/ great lizard"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0604}/[H603]', 'inflected', 'heb', 'אֲנָקָה', '["ʼănâqâh"]', '["and/ the/ gecko"]', '["n-f"]', 'some kind of lizard, probably the gecko (from its wail) ferret.', 'the same as 603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H3581A>', 'inflected', 'heb', 'והכח', '["ve./ha./Ko.ach"]', '["and/ the/ monitor lizard"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H3911>', 'inflected', 'heb', 'והלטאה', '["ve./ha./le.ta.''Ah"]', '["and/ the/ wall lizard"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H2546>', 'inflected', 'heb', 'והחמט', '["ve./ha./Cho.met"]', '["and/ the/ skink"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8580}/[H5395]', 'inflected', 'heb', 'תַּנְשֶׁמֶת', '["tanshemeth"]', '["and/ the/ barn owl","and/ the/ chameleon"]', '["n-f"]', 'properly, a hard breather, i.e. the name of two unclean creatures, a lizard and a bird (both perhaps from changing color through their irascibility), probably the tree-toad and the water-hen mole, swan.', 'from 5395;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4194}/H9028/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["by/ death/ their","in/ death/ their"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2891}/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["and/ I will be clean","and/ I will cleanse","and/ he cleansed","and/ he was clean","and/ he will be clean","and/ he will be pure","and/ he will declare pure","and/ he will purify","and/ it will be pure","and/ people purified","and/ she will be pure","and/ they purified","and/ they purified themselves","and/ they will cleanse","and/ they will purify","and/ they will purify themselves","and/ you will be pure","and/ you will purify"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8432>/H9023', 'opaque', 'heb', 'תָּוֶךְ', '["tâvek"]', '["[the] middle of/ it","middle/ its"]', '["n-m"]', 'a bisection, i.e. (by implication) the centre among(-st), × between, half, × (there-, where-), in(-to), middle, mid(-night), midst (among), × out (of), × through, × with(-in).', 'from an unused root meaning to sever;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3600}/[H3564]', 'inflected', 'heb', 'כִּיר', '["kîyr"]', '["and/ a stove"]', '["n-m"]', 'a cooking range (consisting of two parallel stones, across which the boiler is set) ranges for pots.', 'a form for 3564 (only in the dual);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5422}/[H5422]', 'lemma', 'heb', 'נָתַץ', '["nâthats"]', '["I will tear down","break off","he had pulled down","he has torn down","he pulled down","he tore down","he will break down","it was torn down","it will be broken up","someone has torn down","they broke down","they had been pulled down","they will pull down","you will break down"]', '["v"]', 'to tear down beat down, break down (out), cast down, destroy, overthrow, pull down, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2931}/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["and/ an unclean [person]","and/ unclean","and/ unclean!"]', '["a"]', 'foul in a religious sense defiled, infamous, polluted(-tion), unclean.', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0953A}/[H952]', 'inflected', 'heb', 'בּוֹר', '["bôwr"]', '["and/ a cistern","and/ wells"]', '["n-m"]', 'a pit hole (especially one used as a cistern or a prison) cistern, dungeon, fountain, pit, well.', 'from 952 (in the sense of 877);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2221}/[H2232]', 'lemma', 'heb', 'זֵרוּעַ', '["zêrûwaʻ"]', '["sowing"]', '["n-m"]', 'something sown, i.e. a plant sowing, thing that is sown.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5038}/H9024/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["<in>/ carcass/ its"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0398}/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ [who/ [-ever] eats","and/ the/ [one who] eats"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5038}/H9024/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["any of/ carcass/ its"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5038}/H9024/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["carcass/ its"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1512}/[H1518]', 'lemma', 'heb', 'גָּחוֹן', '["gâchôwn"]', '["belly"]', '["n-m"]', 'the external abdomen, belly (as the source of the faetus) belly.', 'probably from 1518; (compare 1521)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315I}/H9026/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["[is] mind/ your","[were] self/ your","self/ your","selves/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5927H}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["[is] the/ [one who] brought up","who/ brought up","who/ had brought up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5079}/[H5074]', 'lemma', 'heb', 'נִדָּה', '["niddâh"]', '["[is] impurity","impurity","menstrous impurity of","menstruation"]', '["n-f"]', 'properly, rejection; by implication, impurity, especially personal (menstruation) or moral (idolatry, incest) × far, filthiness, × flowers, menstruous (woman), put apart, × removed (woman), separation, set apart, unclean(-ness, thing, with filthiness).', 'from 5074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1738}/H9044/[H1738]', 'inflected', 'heb', 'דָּוָה', '["dâvâh"]', '["being unwell/ she"]', '["v"]', 'to be sick (as if in menstruation) infirmity.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2892A}/[H2891]', 'lemma', 'heb', 'טֹהַר', '["ṭôhar"]', '["purification"]', '["n-m"]', 'literally brightness; ceremonially purification clearness, glory, purifying.', 'from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4720}/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["<of> the/ sanctuary","the/ sanctuary"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2892A}/H9024/[H2891]', 'inflected', 'heb', 'טֹהַר', '["ṭôhar"]', '["purification/ her"]', '["n-m"]', 'literally brightness; ceremonially purification clearness, glory, purifying.', 'from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5079}/H9024/[H5074]', 'inflected', 'heb', 'נִדָּה', '["niddâh"]', '["like/ menstruous impurity/ her"]', '["n-f"]', 'properly, rejection; by implication, impurity, especially personal (menstruation) or moral (idolatry, incest) × far, filthiness, × flowers, menstruous (woman), put apart, × removed (woman), separation, set apart, unclean(-ness, thing, with filthiness).', 'from 5074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4390}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["and/ when/ are completed","and/ when/ were completed"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8141}/H9023/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["year/ its","years/ his"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4726}/[H6979]', 'inflected', 'heb', 'מָקוֹר', '["mâqôwr"]', '["from/ [the] fountain of","from/ [the] spring of"]', '["n-m"]', 'properly, something dug, i.e. a (general) source (of water, even when naturally flowing; also of tears, blood (by euphemism, of the female pudenda); figuratively, of happiness, wisdom, progeny) fountain, issue, spring, well(-spring).', 'or מָקֹר; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2145}/[H2142]', 'inflected', 'heb', 'זָכָר', '["zâkâr"]', '["for <the>/ male","for the/ male","of/ males","to/ males"]', '["n-m"]', 'properly, remembered, i.e. a male (of man or animals, as being the most noteworthy sex) × him, male, man(child, -kind).', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5347}/[H5344]', 'inflected', 'heb', 'נְקֵבָה', '["nᵉqêbâh"]', '["for <the>/ female"]', '["n-f"]', 'female (from the sexual form) female.', 'from 5344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2891}\/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["and/ he will be clean","and/ she will be pure"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5785}/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["[are] on/ [the] skin of","[is] in the/ skin","in the/ hide","in the/ skin","in/ [the] skin of","in/ a hide","on the/ skin","on/ [the] skin of","with/ [the] skin of"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5597}/[H5596]', 'lemma', 'heb', 'סַפַּחַת', '["çappachath"]', '["flaking skin"]', '["n-f"]', 'the mange (as making the hair fall off) scab.', 'from 5596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0934}/[H925]', 'lemma', 'heb', 'בֹּהֶרֶת', '["bôhereth"]', '["[is] a bright spot","a bright spot","bright spots"]', '["n-f"]', 'a whitish spot on the skin bright spot.', 'feminine active participle of the same as 925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5061}/[H5060]', 'inflected', 'heb', 'נֶגַע', '["negaʻ"]', '["<into>/ a plague of","and/ wound"]', '["n-m"]', 'a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound.', 'from 5060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6883}/[H6879]', 'lemma', 'heb', 'צָרַעַת', '["tsâraʻath"]', '["[is] a serious disease","[is] a serious skin disease","[is] a serious skin disease of","[the] serious disease of","a serious disease","a serious skin disease","a serious skin disease of"]', '["n-f"]', 'leprosy leprosy.', 'from 6879;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5061}/[H5060]', 'inflected', 'heb', 'נֶגַע', '["negaʻ"]', '["the/ plague","the/ plagued [person]"]', '["n-m"]', 'a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound.', 'from 5060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8181}/[H8175]', 'inflected', 'heb', 'שֵׂעָר', '["sêʻâr"]', '["and/ [is] hair","and/ [the] hair","and/ [the] hair of","and/ hair"]', '["n-m"]', 'hair (as if tossed or bristling) hair(-y), × rough.', 'or שַׂעַר; (Isaiah 7:20), from 8175 in the sense of dishevelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5061}/[H5060]', 'inflected', 'heb', 'נֶגַע', '["negaʻ"]', '["in the/ plague","to/ [the] plague of"]', '["n-m"]', 'a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound.', 'from 5060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6013}/[H6009]', 'lemma', 'heb', 'עָמֹק', '["ʻâmôq"]', '["[is] deep","deep","unfathomable [things]"]', '["a"]', 'deep (literally or figuratively) (× exceeding) deep (thing).', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5785}/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["more than/ [the] skin of"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6013}/[H6009]', 'inflected', 'heb', 'עָמֹק', '["ʻâmôq"]', '["and/ [is] deep","and/ deep"]', '["a"]', 'deep (literally or figuratively) (× exceeding) deep (thing).', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4758}/H9024/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["appearance/ its"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8181}/H9024/[H8175]', 'inflected', 'heb', 'שֵׂעָר', '["sêʻâr"]', '["and/ hair/ its"]', '["n-m"]', 'hair (as if tossed or bristling) hair(-y), × rough.', 'or שַׂעַר; (Isaiah 7:20), from 8175 in the sense of dishevelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869A}/H9023/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["by/ eyes/ its","in/ own eyes/ his","in/ own eyes/ its","in/ view/ his","with/ eyes/ his","with/ eyes/ its"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6581}/[H6581]', 'lemma', 'heb', 'פָּשָׂה', '["pâsâh"]', '["certainly <to spread>","certainly [if] <to spread>","it has spread","it will spread"]', '["v"]', 'to spread spread.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5462}/H9033/[H5462]', 'inflected', 'heb', 'סָגַר', '["çâgar"]', '["and/ he will shut up/ him","and/ he will shut up/ it"]', '["v"]', 'to shut up; figuratively, to surrender close up, deliver (up), give over (up), inclose, × pure, repair, shut (in, self, out, up, up together), stop, × straitly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3543A}/[H3543]', 'lemma', 'heb', 'כָּהָה', '["kâhâh"]', '["certainly <to dim>","he will grow dim","it had grown dim","it has become dull"]', '["v"]', 'to be weak, i.e. (figuratively) to despond (causatively, rebuke), or (of light, the eye) to grow dull darken, be dim, fail, faint, restrain, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2891}/H9033/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["and/ he will declare pure/ him","and/ he will purify/ it"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4556}/[H5596]', 'lemma', 'heb', 'מִסְפַּחַת', '["miçpachath"]', '["[is] a skin rash"]', '["n-f"]', 'scruf (as spreading over the surface) scab.', 'from 5596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4556}/[H5596]', 'inflected', 'heb', 'מִסְפַּחַת', '["miçpachath"]', '["the/ skin rash"]', '["n-f"]', 'scruf (as spreading over the surface) scab.', 'from 5596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200G}/H9043/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["he has presented/ himself"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2893}/H9023/[H2892]', 'inflected', 'heb', 'טׇהֳרָה', '["ṭohŏrâh"]', '["for/ purification/ his"]', '["n-f"]', 'ceremonial purification; moral purity × is cleansed, cleansing, purification(-fying).', 'feminine of 2892;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2930A}/H9033/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["and/ he made unclean/ it","and/ he will declare unclean/ him"]', '["v"]', 'to be foul, especially in a ceremial or moral sense (contaminated) defile (self), pollute (self), be (make, make self, pronounce) unclean, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4241}/[H2421]', 'inflected', 'heb', 'מִחְיָה', '["michyâh"]', '["and/ a raw spot of"]', '["n-f"]', 'preservation of life; hence, sustenance; also the live flesh, i.e. the quick preserve life, quick, recover selves, reviving, sustenance, victuals.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7613}/[H5375]', 'inflected', 'heb', 'שְׂאֵת', '["sᵉʼêth"]', '["[is] in the/ swelling"]', '["n-f"]', 'an elevation or leprous scab; figuratively, elation or cheerfulness; exaltation in rank or character be accepted, dignity, excellency, highness, raise up self, rising.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3462}/[H3462]', 'lemma', 'heb', 'יָשֵׁן', '["yâshên"]', '["I should sleep","I slept","anyone will sleep","do you sleep","growing old","grown old","he will sleep","they will sleep"]', '["v"]', 'properly, to be slack or languid, i.e. (by implication) sleep (figuratively, to die); also to grow old, stale or inveterate old (store), remain long, (make to) sleep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5462}/H9033/[H5462]', 'inflected', 'heb', 'סָגַר', '["çâgar"]', '["he will shut up/ him","to deliver up/ him"]', '["v"]', 'to shut up; figuratively, to surrender close up, deliver (up), give over (up), inclose, × pure, repair, shut (in, self, out, up, up together), stop, × straitly.', 'a primitive root;');
