INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1548}/[H1548]', 'lemma', 'heb', 'גָּלַח', '["gâlach"]', '["I was shaved","he shaved","he will shave","shaven of","they will shave"]', '["v"]', 'properly, to be bald, i.e. (causatively) to shave; figuratively to lay waste poll, shave (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4758}/H9023/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["and/ appearance/ his","and/ appearance/ its"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2893}/H9023/[H2892]', 'inflected', 'heb', 'טׇהֳרָה', '["ṭohŏrâh"]', '["purification/ his"]', '["n-f"]', 'ceremonial purification; moral purity × is cleansed, cleansing, purification(-fying).', 'feminine of 2892;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1239}/[H1239]', 'lemma', 'heb', 'בָּקַר', '["bâqar"]', '["I will seek","he will scrutinize","he will seek"]', '["v"]', 'properly, to plough, or (generally) break forth, i.e. (figuratively) to inspect, admire, care for, consider (make) inquire (-ry), (make) search, seek out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8181}/[H8175]', 'inflected', 'heb', 'שֵׂעָר', '["sêʻâr"]', '["for the/ hair"]', '["n-m"]', 'hair (as if tossed or bristling) hair(-y), × rough.', 'or שַׂעַר; (Isaiah 7:20), from 8175 in the sense of dishevelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6669}/[H6668]', 'inflected', 'heb', 'צָהֹב', '["tsâhôb"]', '["<the>/ yellow"]', '["a"]', 'golden in color yellow.', 'from 6668;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7495}/[H7495]', 'lemma', 'heb', 'רָפָא', '["râphâʼ"]', '["I have healed","I heal","I will heal","[am] about to heal","[are] physicians of","a physician","he will heal","heal","it has been healed","it was healed","it will be healed","they heal","they will be healed","to be healed","we healed","will he heal","you have healed","you will be healed"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1320}/H9028/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["body/ their","flesh/ their","own flesh/ their"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0933>', 'opaque', 'heb', 'בֹּהַק', '["bôhaq"]', '["[is] a skin rash"]', '["n-m"]', 'white scurf freckled spot.', 'from an unused root meaning to be pale;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4803}/[H4803]', 'lemma', 'heb', 'מָרַט', '["mâraṭ"]', '["[is] polished","[was] made bare","it has been polished","it will become bare","polished"]', '["v"]', 'to polish; by implication, to make bald (the head), to gall (the shoulder); also, to sharpen bright, furbish, (have his) hair (be) fallen off, peeled, pluck off (hair).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7142}/[H7139]', 'lemma', 'heb', 'קֵרֵחַ', '["qêrêach"]', '["O bald [man]","[is] bald"]', '["a"]', 'bald (on the back of the head) bald (head).', 'from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6285}/[H6311]', 'inflected', 'heb', 'פֵּאָה', '["pêʼâh"]', '["from/ [the] side of"]', '["n-f"]', 'properly, mouth in a figurative sense, i.e. direction, region, extremity corner, end, quarter, side.', 'feminine of 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1371>', 'opaque', 'heb', 'גִּבֵּחַ', '["gibbêach"]', '["[is] bald"]', '["a"]', 'bald in the forehead forehead bald.', 'from an unused root meaning to be high (in the forehead);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7146}/[H7139]', 'inflected', 'heb', 'קָרַחַת', '["qârachath"]', '["on the/ bald spot"]', '["n-f"]', 'a bald spot (on the back of the head); figuratively, a threadbare spot (on the back side of the cloth) bald head, bare within.', 'from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1372}/[H1371]', 'inflected', 'heb', 'גַּבַּחַת', '["gabbachath"]', '["on the/ bald forehead"]', '["n-f"]', 'baldness in the forehead; by analogy, a bare spot on the right side of cloth bald forehead, × without.', 'from the same as 1371;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7146}/H9023/[H7139]', 'inflected', 'heb', 'קָרַחַת', '["qârachath"]', '["on/ bald spot/ his","on/ bald spot/ its"]', '["n-f"]', 'a bald spot (on the back of the head); figuratively, a threadbare spot (on the back side of the cloth) bald head, bare within.', 'from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1372}/H9023/[H1371]', 'inflected', 'heb', 'גַּבַּחַת', '["gabbachath"]', '["on/ bald forehead/ his","on/ bald forehead/ its"]', '["n-f"]', 'baldness in the forehead; by analogy, a bare spot on the right side of cloth bald forehead, × without.', 'from the same as 1371;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4758}/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["[was] like the/ appearance","[was] like the/ vision","[was] like/ [the] appearance of","like the/ appearance","like the/ vision","like/ [the] appearance of"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2930A}/H9033/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["he will declare unclean/ him"]', '["v"]', 'to be foul, especially in a ceremial or moral sense (contaminated) defile (self), pollute (self), be (make, make self, pronounce) unclean, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7218A>/H9023', 'inflected', 'heb', 'בראשו', '["be./ro.Sh/o","ve./ro.Sh/o"]', '["[are] in/ head/ his","[is] on/ head/ his","[will be] on/ own head/ his","on/ head/ his","on/ head/ its","on/ own head/ his","with/ head/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5061}/H9023/[H5060]', 'inflected', 'heb', 'נֶגַע', '["negaʻ"]', '["own plague/ his","plague/ his"]', '["n-m"]', 'a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound.', 'from 5060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6879}/[H6879]', 'inflected', 'heb', 'צָרַע', '["tsâraʻ"]', '["<and>/ the/ [one who] has a serious skin disease"]', '["v"]', 'to scourge, i.e. (intransitive and figurative) to be stricken with leprosy leper, leprous.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7218A>/H9023', 'inflected', 'heb', 'וראשו', '["ve./ro.Sh/o"]', '["and/ head/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8222}/[H8193]', 'lemma', 'heb', 'שָׂפָם', '["sâphâm"]', '["a moustache"]', '["n-m"]', 'the beard (as a lip-piece) beard, (upper) lip.', 'from 8193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5844A}/[H5844]', 'lemma', 'heb', 'עָטָה', '["ʻâṭâh"]', '["[is] wrapped","[which] he wraps himself","[you are] wrapping yourself","he delouses","he will cover","it covers [it]","may they cover themselves","you have wrapped","you must cover"]', '["v"]', 'to wrap, i.e. cover, veil, clothe, or roll array self, be clad, (put a) cover (-ing, self), fill, put on, × surely, turn aside.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121I}/[H7122]', 'lemma', 'heb', 'קָרָא', '["qârâʼ"]', '["I call","I called out","I have called out","I proclaim","I will proclaim","[am] about to proclaim","[is] calling","[when] I will call out","[when] they will call out","[which] you proclaimed","call","call out","does she call out","he called out","he had proclaimed","he proclaimed","he proclaims","he will call out","it has been proclaimed","it proclaims","let him proclaim [it]","people called out","proclaim","she calls out","someone has proclaimed","they call out","they have called out","they proclaimed","will I proclaim","you will call","you will proclaim"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0910}/[H909]', 'lemma', 'heb', 'בָּדָד', '["bâdâd"]', '["[is] alone","alone"]', '["n-m"]', 'separate; adverb, separately alone, desolate, only, solitary.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4186}/H9023\/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["dwelling/ his"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0899B}/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["and/ the/ clothing","and/ the/ garment"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0899B}/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["for/ clothes of","in the/ clothing","in the/ garment","in/ clothing of","with <the>/ clothes"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6785>', 'opaque', 'heb', 'צֶמֶר', '["tsemer"]', '["wool"]', '["n-m"]', 'wool wool(-len).', 'from an unused root probably meaning to be shaggy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6593}/[H6580]', 'lemma', 'heb', 'פִּשְׁתֶּה', '["pishteh"]', '["flax<es>","linen<s>"]', '["n-f"]', 'linen (i.e. the thread, as carded) flax, linen.', 'from the same as 6580 as in the sense of comminuting;');
