INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6154B}/[H6148]', 'inflected', 'heb', 'עֵרֶב', '["ʻêreb"]', '["in the/ woof","in/ woof"]', '["n-m"]', 'the web (or transverse threads of cloth); also a mixture, (or mongrel race) Arabia, mingled people, mixed (multitude), woof.', 'or עֶרֶב; (1 Kings 10:15), (with the article prefix), from 6148;');
