INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3422}/[H3418]', 'lemma', 'heb', 'יְרַקְרַק', '["yᵉraqraq"]', '["greenish"]', '["a"]', 'yellowishness greenish, yellow.', 'from the same as 3418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3992}/[H3992]', 'lemma', 'heb', 'מָאַר', '["mâʼar"]', '["[which] pricks","malignant"]', '["v"]', 'to be bitter or (causatively) to embitter, i.e. be painful fretting, picking.', 'a primitive root;');
