INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869I}/H9023/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eye/ his","eye/ its"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5061}/[H5060]', 'inflected', 'heb', 'נֶגַע', '["negaʻ"]', '["and/ the/ plague"]', '["n-m"]', 'a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound.', 'from 5060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8313}/H9033/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["you will burn/ it"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6356}/[H6354]', 'lemma', 'heb', 'פְּחֶתֶת', '["pᵉchetheth"]', '["[is] a mildew"]', '["n-f"]', 'a hole (by mildew in a garment) fret inward.', 'from the same as 6354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6524A}/[H6524]', 'lemma', 'heb', 'פָּרַח', '["pârach"]', '["[is] breaking out","completely <to bud>","he will flourish","it buds","it had budded","it has budded","it will blossom","it will bud","it will flourish","it will show buds","they will bud","they will flourish","they will sprout","you cause to sprout"]', '["v"]', 'to break forth as a bud, i.e. bloom; generally, to spread; specifically, to fly (as extending the wings); figuratively, to flourish × abroad, × abundantly, blossom, break forth (out), bud, flourish, make fly, grow, spread, spring (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6785>', 'inflected', 'heb', 'הצמר', '["ha./Tze.mer"]', '["<the>/ wool","the/ wool"]', NULL, NULL, NULL);
