INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2891}/H9033/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["to/ declare pure/ it"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2930A}/H9033\/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["to/ declare unclean/ it"]', '["v"]', 'to be foul, especially in a ceremial or moral sense (contaminated) defile (self), pollute (self), be (make, make self, pronounce) unclean, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6879}/[H6879]', 'inflected', 'heb', 'צָרַע', '["tsâraʻ"]', '["the/ [one who] had a serious skin disease","the/ [one who] has a serious skin disease","the/ [one] having a skin disease","the/ [people] having a skin disease"]', '["v"]', 'to scourge, i.e. (intransitive and figurative) to be stricken with leprosy leper, leprous.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2891}/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["for the/ [one] purifying himself","to/ cleanse","to/ cleanse [it]","to/ purify"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0730}/[H729]', 'lemma', 'heb', 'אֶרֶז', '["ʼerez"]', '["[are] cedar<s>","[the] cedars of","[was] a cedar","[was] cedar","a cedar","cedar","cedar<s>","cedar[s]","cedars"]', '["n-m"]', 'a cedar tree (from the tenacity of its roots) cedar (tree).', 'from 729;');
