INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7819A}/[H7819]', 'inflected', 'heb', 'שָׁחַט', '["shâchaṭ"]', '["[which] had the/ throat cut"]', '["v n-f"]', 'to slaughter (in sacrifice or massacre) kill, offer, shoot out, slay, slaughter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2891}/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["the/ [one] purifying himself","who/ declares pure","who/ is purifying himself"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8181}/H9023/[H8175]', 'inflected', 'heb', 'שֵׂעָר', '["sêʻâr"]', '["hair/ his"]', '["n-m"]', 'hair (as if tossed or bristling) hair(-y), × rough.', 'or שַׂעַר; (Isaiah 7:20), from 8175 in the sense of dishevelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0168G}/H9023/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["of/ tent/ his","to/ tent/ his","to/ tents/ his","to/ tents/ its"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2206}/H9023/[H2204]', 'inflected', 'heb', 'זָקָן', '["zâqân"]', '["beard/ his"]', '["n-m"]', 'the beard (as indicating age) beard.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1354>', 'opaque', 'heb', 'גַב', '["gab"]', '["[is] [the] mound of","[the] bosses of","[the] eyebrows of","a mound"]', '["n"]', 'the back (as rounded); by analogy, the top or rim, a boss, a vault, arch of eye, bulwarks, etc. back, body, boss, eminent (higher) place, (eye) brows, nave, ring.', 'from an unused root meaning to hollow or curve; (compare 1460 and 1479)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3535}/[H3532]', 'inflected', 'heb', 'כִּבְשָׂה', '["kibsâh"]', '["and/ a ewe-lamb"]', '["n-f"]', 'a ewe (ewe) lamb.', 'or כַּבְשָׂה; feminine of 3532;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8141}/H9024/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["year/ its"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6241}/[H6235]', 'lemma', 'heb', 'עִשָּׂרוֹן', '["ʻissârôwn"]', '["a tenth","a tenth [of an ephah]","one tenth [of an ephah]","tenths","tenths [of an ephah]"]', '["n-m"]', '(fractional) a tenth part tenth deal.', 'or עִשָּׂרֹן; from 6235;');
