INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3849>', 'opaque', 'heb', 'לֹג', '["lôg"]', '["[the] log of"]', '["n-m"]', 'a log or measure for liquids log (of oil).', 'from an unused root apparently meaning to deepen or hollow (like 3537);');
