INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3499A}/[H3498]', 'inflected', 'heb', 'יֶתֶר', '["yether"]', '["and/ some of/ [the] remainder of"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2932}/H9023/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["from/ uncleanness/ his"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1800}/[H1809]', 'lemma', 'heb', 'דַּל', '["dal"]', '["[are] poor [people]","[is] poor","[the] poor","a poor [person]","poor","poor [people]","weak"]', '["a"]', 'properly, dangling, i.e. (by implication) weak or thin lean, needy, poor (man), weaker.', 'from 1809;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8573}/[H5130]', 'inflected', 'heb', 'תְּנוּפָה', '["tᵉnûwphâh"]', '["to/ a wave-offering"]', '["n-f"]', 'a brandishing (in threat); by implication, tumult; specifically, the official undulation of sacrificial offerings offering, shaking, wave (offering).', 'from 5130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2893}/H9023\/[H2892]', 'inflected', 'heb', 'טׇהֳרָה', '["ṭohŏrâh"]', '["for/ purification/ his"]', '["n-f"]', 'ceremonial purification; moral purity × is cleansed, cleansing, purification(-fying).', 'feminine of 2892;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0272}/H9026/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["possession/ your"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5061}/[H5060]', 'inflected', 'heb', 'נֶגַע', '["negaʻ"]', '["like/ a plague"]', '["n-m"]', 'a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound.', 'from 5060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7023}/[H6979]', 'inflected', 'heb', 'קִיר', '["qîyr"]', '["<in> the/ wall","[is] in/ [the] walls of","[was] in the/ wall","[was] in/ [the] wall of","in the/ wall","in/ [the] wall of","in/ [the] walls of","on the/ wall","on/ a wall"]', '["n-m"]', 'a wall (as built in a trench) mason, side, town, × very, wall.', 'or קִר; (Isaiah 22:5), or (feminine) קִירָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8258}/[H8257]', 'lemma', 'heb', 'שְׁקַעְרוּרָה', '["shᵉqaʻrûwrâh"]', '["depressions"]', '["n-f"]', 'a depression hollow strake.', 'from 8257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7023}/[H6979]', 'inflected', 'heb', 'קִיר', '["qîyr"]', '["<the>/ wall","[is] the/ wall","the/ wall","the/ walls"]', '["n-m"]', 'a wall (as built in a trench) mason, side, town, × very, wall.', 'or קִר; (Isaiah 22:5), or (feminine) קִירָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2502A}/[H2502]', 'inflected', 'heb', 'חָלַץ', '["châlats"]', '["and/ people will tear out","and/ she will draw off"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7106A}/[H7106]', 'lemma', 'heb', 'קָצַע', '["qâtsaʻ"]', '["he will scrape"]', '["v"]', 'to strip off, i.e. (partially) scrape; by implication, to segregate (as an angle) cause to scrape, corner.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6083}/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["<the>/ debris","the/ dust"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7096}/[H7096]', 'lemma', 'heb', 'קָצָה', '["qâtsâh"]', '["[one who] cuts off","by cutting off","has scraped","they have scraped off"]', '["v"]', 'to cut off; (figuratively) to destroy; (partially) to scrape off cut off, cut short, scrape (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2902A}/[H2902]', 'inflected', 'heb', 'טוּחַ', '["ṭûwach"]', '["and/ he will plaster"]', '["v"]', 'to smear, especially with lime daub, overlay, plaister, smut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6524B}/[H6524]', 'inflected', 'heb', 'פָּרַח', '["pârach"]', '["and/ it will break out"]', '["v"]', 'to break forth as a bud, i.e. bloom; generally, to spread; specifically, to fly (as extending the wings); figuratively, to flourish × abroad, × abundantly, blossom, break forth (out), bud, flourish, make fly, grow, spread, spring (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2502A}/[H2502]', 'lemma', 'heb', 'חָלַץ', '["châlats"]', '["[is] delivered","[the] [one] drawn off of","he has withdrawn","he rescues","tears out","they are delivered","they draw out","you have rescued","you will take off"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2902A}/[H2902]', 'lemma', 'heb', 'טוּחַ', '["ṭûwach"]', '["[are] plastering","[the] plasterers of","they have plastered","was plastered","you plastered"]', '["v"]', 'to smear, especially with lime daub, overlay, plaister, smut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5422}/[H5422]', 'inflected', 'heb', 'נָתַץ', '["nâthats"]', '["and/ he broke down","and/ he pulled down","and/ he will pull down","and/ people pulled down","and/ they pulled down","and/ they will be broken down","and/ you pulled down","and/ you will break down"]', '["v"]', 'to tear down beat down, break down (out), cast down, destroy, overthrow, pull down, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0068G}/H9023/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["stone/ his","stone<s>/ its","stones/ its"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6086G}/H9023/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["wood<s>/ its"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7901H}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ the/ [one who] lies down"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4325G}/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["and/ in <the>/ water","and/ in the/ water","and/ in/ waters","and/ on/ waters","and/ with <the>/ water","and/ with the/ water","and/ with/ water"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6833}/[H6852]', 'inflected', 'heb', 'צִפּוֹר', '["tsippôwr"]', '["and/ with the/ bird"]', '["n-f"]', 'a little bird (as hopping) bird, fowl, sparrow.', 'or צִפֹּר; from 6852;');
