INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1004B}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ for the/ house","and/ for/ [the] house of","and/ to <the>/ house","and/ to the/ house"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7613}/[H5375]', 'inflected', 'heb', 'שְׂאֵת', '["sᵉʼêth"]', '["and/ to <the>/ swelling"]', '["n-f"]', 'an elevation or leprous scab; figuratively, elation or cheerfulness; exaltation in rank or character be accepted, dignity, excellency, highness, raise up self, rising.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5597}/[H5596]', 'inflected', 'heb', 'סַפַּחַת', '["çappachath"]', '["and/ to <the>/ flaking skin"]', '["n-f"]', 'the mange (as making the hair fall off) scab.', 'from 5596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0934}/[H925]', 'inflected', 'heb', 'בֹּהֶרֶת', '["bôhereth"]', '["and/ to <the>/ bright spot"]', '["n-f"]', 'a whitish spot on the skin bright spot.', 'feminine active participle of the same as 925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6883}\/[H6879]', 'inflected', 'heb', 'צָרַעַת', '["tsâraʻath"]', '["<the>/ serious skin disease"]', '["n-f"]', 'leprosy leprosy.', 'from 6879;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2100H}/[H2100]', 'lemma', 'heb', 'זוּב', '["zûwb"]', '["[is] discharging","[one who] has a discharge","[one who] suffers a discharge","discharging","it will discharge","she will discharge"]', '["v"]', 'to flow freely (as water), i.e. (specifically) to have a (sexual) flux; figuratively, to waste away; also to overflow flow, gush out, have a (running) issue, pine away, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1320}/H9023/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["from/ flesh/ his","from/ meat/ his"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2101}/H9023/[H2100]', 'inflected', 'heb', 'זוֹב', '["zôwb"]', '["discharge/ his"]', '["n-m"]', 'a seminal or menstrual flux issue.', 'from 2100;');
