INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7325}/[H7325]', 'lemma', 'heb', 'רוּר', '["rûwr"]', '["it has secreted"]', '["v"]', 'to slaver (with spittle), i.e. (by analogy) to emit a fluid (ulcerous or natural) run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2856}/[H2856]', 'lemma', 'heb', 'חָתַם', '["châtham"]', '["[is] sealed","[were one who] seals","[will be] sealed up","he puts a seal","he will seal","it has been obstructed","seal up","sealed up","they seal up"]', '["v"]', 'to close up; especially to seal make an end, mark, seal (up), stop.', 'a primitive root;');
