INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2100H}/[H2100]', 'inflected', 'heb', 'זוּב', '["zûwb"]', '["the/ [one] discharging"]', '["v"]', 'to flow freely (as water), i.e. (specifically) to have a (sexual) flux; figuratively, to waste away; also to overflow flow, gush out, have a (running) issue, pine away, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4904}/H9023/[H7901]', 'inflected', 'heb', 'מִשְׁכָּב', '["mishkâb"]', '["<in>/ bed/ his","on/ bed/ his"]', '["n-m"]', 'a bed (figuratively, a bier); abstractly, sleep; by euphemism, carnal intercourse bed(-chamber), couch, lieth (lying) with.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3427}/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ the/ inhabitants","and/ those/ [who] dwell","and/ who/ [-ever] sits","and/ who/ were dwelling"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5060}/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["and/ the/ [one who] touches","and/ who/ [-ever] touches"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7556}/[H7556]', 'lemma', 'heb', 'רָקַק', '["râqaq"]', '["he will spit"]', '["v"]', 'to spit spit.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2889}/[H2891]', 'inflected', 'heb', 'טָהוֹר', '["ṭâhôwr"]', '["on <the>/ pure [person]"]', '["a"]', 'pure (in a physical, chemical, ceremonial or moral sense) clean, fair, pure(-ness).', 'or טָהֹר; from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4817}/[H7392]', 'inflected', 'heb', 'מֶרְכָּב', '["merkâb"]', '["<the>/ saddle"]', '["n-m"]', 'a chariot; also a seat (in a vehicle) chariot, covering, saddle.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7392}/[H7392]', 'lemma', 'heb', 'רָכַב', '["râkab"]', '["I will cause to draw","O riders of","[is] riding","[the] rider of","[the] riders of","[was] riding","[were] riding","[who] ride","[who] rides","[who] rode","a rider of","he has ridden","he will ride","make ride","ride forth","riders","riders of","they ride","they rode","they will ride","we will ride","you have made ride","you have ridden","you will ride"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7857}/[H7857]', 'lemma', 'heb', 'שָׁטַף', '["shâṭaph"]', '["[is] about to overflow","[which] rushes","he has rinsed","it washes off","it will be rinsed","it will overflow","overflowing","they overflowed","they will be swept away","they will overflow"]', '["v"]', 'to gush; by implication, to inundate, cleanse; by analogy, to gallop, conquer drown, (over-) flow(-whelm, rinse, run, rush, (throughly) wash (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2891}/[H2891]', 'lemma', 'heb', 'טָהֵר', '["ṭâhêr"]', '["I am pure","I will purify","[is] cleansed","he will be pure","purifying themselves","she has become pure","she will be pure","they had purified themselves","to cleanse","we have cleansed","we have cleansed ourselves","will he be pure","you are clean","you will be clean","you will be pure"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414G}/H9038/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I gave/ them","and/ I will give/ them","and/ he gave/ them","and/ he will deliver up/ them","and/ he will give/ them","and/ will you deliver up/ them","and/ will you give?/ them","and/ you gave/ them","and/ you will make/ them"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
