INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2930A}/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["to/ be unclean","to/ become unclean","to/ declare unclean"]', '["v"]', 'to be foul, especially in a ceremial or moral sense (contaminated) defile (self), pollute (self), be (make, make self, pronounce) unclean, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1739}/[H1738]', 'inflected', 'heb', 'דָּוֶה', '["dâveh"]', '["and/ the/ menstruating [woman]"]', '["a"]', 'sick (especially in menstruation) faint, menstruous cloth, she that is sick, having sickness.', 'from 1738;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2100H}/[H2100]', 'inflected', 'heb', 'זוּב', '["zûwb"]', '["and/ the/ [one] discharging"]', '["v"]', 'to flow freely (as water), i.e. (specifically) to have a (sexual) flux; figuratively, to waste away; also to overflow flow, gush out, have a (running) issue, pine away, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5347}/[H5344]', 'inflected', 'heb', 'נְקֵבָה', '["nᵉqêbâh"]', '["and/ for the/ female","and/ of the/ female"]', '["n-f"]', 'female (from the sexual form) female.', 'from 5344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0376G>', 'inflected', 'heb', 'ולאיש', '["u./le./''Ish","ve./la./''Ish"]', '["and/ for/ a man","and/ to the/ man"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2931}\/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["an unclean [woman]"]', '["a"]', 'foul in a religious sense defiled, infamous, polluted(-tion), unclean.', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7126G}/H9048/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["when/ drew near/ they"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6499}/[H6565]', 'inflected', 'heb', 'פַּר', '["par"]', '["by the/ young bull","with/ a bull","with/ a young bull","with/ young bulls"]', '["n-m"]', 'a bullock (apparently as breaking forth in wild strength, or perhaps as dividing the hoof) ( young) bull(-ock), calf, ox.', 'or פָּר; from 6565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H0073>', 'inflected', 'heb', 'ובאבנט', '["u./ve./''av.Net"]', '["and/ with/ a sash of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4701}/[H6801]', 'inflected', 'heb', 'מִצְנֶפֶת', '["mitsnepheth"]', '["and/ with/ a turban of"]', '["n-f"]', 'a tiara, i.e. official turban (of a king or high priest) diadem, mitre.', 'from 6801;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6801}/[H6801]', 'lemma', 'heb', 'צָנַף', '["tsânaph"]', '["certainly <to wind up>","he will wind"]', '["v"]', 'to wrap, i.e. roll or dress be attired, × surely, violently turn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0854}/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ from/ with","and/ from/ with <the>"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414L}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will put","and/ he will put","and/ they have put","and/ they put"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1486>', 'opaque', 'heb', 'גּוֹרָל', '["gôwrâl"]', '["[the] allotted portion of","[the] lot of","a lot","lots"]', '["n-m"]', 'properly, a pebble, i.e. a lot (small stones being used for that purpose); figuratively, a portion or destiny (as if determined by lot) lot.', 'or (shortened) גֹּרָל; from an unused root meaning to be rough (as stone);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1486>', 'inflected', 'heb', 'וגורל', '["ve./go.Ral"]', '["and/ [the] lot","and/ a lot"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5799}/[H5795]', 'inflected', 'heb', 'עֲזָאזֵל', '["ʻăzâʼzêl"]', '["for/ [the] escape goat","to/ [the] escape goat"]', '["n-m"]', 'goat of departure; the scapegoat scapegoat.', 'from 5795 and 235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1486>', 'inflected', 'heb', 'הגורל', '["ha./go.Ral"]', '["[is] the/ lot","the/ lot"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6213A}/H9033/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ I will do/ it","and/ he will offer/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8163B}/[H8175]', 'inflected', 'heb', 'שָׂעִיר', '["sâʻîyr"]', '["and/ the/ male goat"]', '["a n-m"]', 'shaggy; as noun, a he-goat; by analogy, a faun devil, goat, hairy, kid, rough, satyr.', 'or שָׂעִר; from 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5975H}/[H5975]', 'lemma', 'heb', 'עָמַד', '["ʻâmad"]', '["I appointed","[are] standing guard","[was] standing","he appointed","he had made stand","he stood","it will be stationed","will arise"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7971G}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["by/ sending","by/ sending away","to/ send","to/ send [them]"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1513>', 'opaque', 'heb', 'גֶּחֶל', '["gechel"]', '["[will be] coal","burning coals","burning coals of","coals","coals of"]', '["n-f"]', 'an ember (burning) coal.', 'or (feminine) גַּחֶלֶת; from an unused root meaning to glow or kindle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4393}/[H4390]', 'inflected', 'heb', 'מְלֹא', '["mᵉlôʼ"]', '["and/ [the] fullness of"]', '["n-m"]', 'fulness (literally or figuratively) × all along, × all that is (there-) in, fill, (× that whereof...was) full, fulness, (hand-) full, multitude.', 'rarely מְלוֹא; or מְלוֹ; (Ezekiel 41:8), from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2651>/H9023', 'opaque', 'heb', 'חֹפֶן', '["chôphen"]', '["hands/ his"]', '["n-m"]', 'a fist (only in the dual) fists, (both) hands, hand(-ful).', 'from an unused root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2932}/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["from/ [the] uncleanness of","from/ [the] uncleanness<es> of"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6588}/H9028/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["and/ from/ transgressions/ their"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7931}/[H7901]', 'inflected', 'heb', 'שָׁכַן', '["shâkan"]', '["those/ [who] dwell","which/ dwells","who/ dwell","who/ dwells"]', '["v"]', 'to reside or permanently stay (literally or figuratively) abide, continue, (cause to, make to) dwell(-er), have habitation, inhabit, lay, place, (cause to) remain, rest, set (up).', 'a primitive root (apparently akin (by transmission) to 7901 through the idea of lodging; compare 5531, 7925);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2932}/H9028/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["uncleanness<es>/ their"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1818}/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["and/ some of/ [the] blood of"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3722A}/[H3722]', 'inflected', 'heb', 'כָּפַר', '["kâphar"]', '["from/ making atonement for"]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6588}/H9028/[H6586]', 'inflected', 'heb', 'פֶּשַׁע', '["peshaʻ"]', '["transgression/ their","transgressions/ their"]', '["n-m"]', 'a revolt (national, moral or religious) rebellion, sin, transgression, trespass.', 'from 6586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6261}/[H6256]', 'lemma', 'heb', 'עִתִּי', '["ʻittîy"]', '["ready"]', '["a"]', 'timely fit.', 'from 6256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771G}/H9028/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquities/ their","iniquity/ their"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1509}/[H1504]', 'lemma', 'heb', 'גְּזֵרָה', '["gᵉzêrâh"]', '["infertile"]', '["n-f"]', 'a desert (as separated) not inhabited.', 'from 1504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5117}/H9038/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["and/ he placed/ them","and/ he will give rest/ them","and/ he will leave/ them","and/ they put/ them","and/ they set down/ them","and/ you will deposit/ them"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5930A}/H9023/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["burnt offering/ his"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7971H}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ the/ [one who] let go"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1818}/H9028/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["blood/ their","blood<s>/ their","own blood/ their"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5785}/H9028/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["hides/ their","skin/ their"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6569}/H9028/[H6567]', 'inflected', 'heb', 'פֶּרֶשׁ', '["peresh"]', '["offal/ their"]', '["n-m"]', 'excrement (as eliminated) dung.', 'from 6567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8313}/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["and/ the/ [one who] burns"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0249}/[H2224]', 'inflected', 'heb', 'אֶזְרָח', '["ʼezrâch"]', '["<the>/ native-born","the/ native-born"]', '["n-m"]', 'a spontaneous growth, i.e. native (tree or persons) bay tree, (home-) born (in the land), of the (one''s own) country (nation).', 'from 2224 (in the sense of springing up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027R}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ his","hands/ its","own hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2077}/H9028/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["sacrifices/ their"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0935P}/H9038/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ I brought/ them","and/ I will bring/ them","and/ he brought/ them","and/ they brought/ them","and/ they will bring/ them","and/ you brought/ them","and/ you will bring/ them"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8163C}/[H8175]', 'inflected', 'heb', 'שָׂעִיר', '["sâʻîyr"]', '["to the/ goat idols"]', '["a n-m"]', 'shaggy; as noun, a he-goat; by analogy, a faun devil, goat, hairy, kid, rough, satyr.', 'or שָׂעִר; from 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0413}/H9038/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["and/ into/ them","and/ to/ them"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6213I}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["to/ acquire","to/ make","to/ offer"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5971B}/H9023/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["from/ kinspeople<s>/ his"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315J}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["against/ anyone","on the/ person"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315G}/H9026/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["being/ your","self/ your","selves/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315H}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["[which] by the/ life","by/ [the] life of","for/ [the] life of","for/ life","with/ soul"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1818}\/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["blood","blood<s>"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1121G}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["[are] of/ [the] people of","[were] from/ [the] people of","[were] of/ [the] descendants of","[were] of/ [the] people of","any of/ [the] people of","from/ [the] descendants of","from/ [the] people of","from/ [the] sons of","more than/ [the] sons of","of/ [the] descendants of","of/ [the] sons of","one of/ [the] descendants of","some of/ [the] children of","some of/ [the] descendants of","some of/ [the] people of","some of/ [the] sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6679A}/[H6718]', 'lemma', 'heb', 'צוּד', '["tsûwd"]', '["[are] hunting","certainly <to hunt>","he will hunt","they hunt","they hunted","will you hunt"]', '["v"]', 'to lie alongside (i.e. in wait); by implication, to catch an animal (figuratively, men); to victual (for a journey) chase, hunt, sore, take (provision).', 'a primitive root; also denominative from 6718');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6083}/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["[is] in the/ dust","in the/ dust","with <the>/ dust"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2966}/[H2964]', 'inflected', 'heb', 'טְרֵפָה', '["ṭᵉrêphâh"]', '["and/ a torn animal","and/ torn flesh"]', '["n-f"]', 'prey, i.e. flocks devoured by animals ravin, (that which was) torn (of beasts, in pieces).', 'feminine (collectively) of 2964;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0249}/[H2224]', 'inflected', 'heb', 'אֶזְרָח', '["ʼezrâch"]', '["among the/ native-born"]', '["n-m"]', 'a spontaneous growth, i.e. native (tree or persons) bay tree, (home-) born (in the land), of the (one''s own) country (nation).', 'from 2224 (in the sense of springing up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1616}/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["and/ among the/ sojourner"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1320}/H9023/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["and/ body/ his"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771G}/H9023\/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquity/ his"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4639K}/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["according to/ [the] deed[s] of"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4639K}/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["and/ according to/ [the] deed[s] of"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2708}/H9028/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["and/ in/ statutes/ their"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941G}/H9020/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["case/ my","judgment/ my","judgments/ my","justice/ my"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7607}/[H7604]', 'lemma', 'heb', 'שְׁאֵר', '["shᵉʼêr"]', '["[is] a relative of","[the] flesh of","meat","relative of"]', '["n-m"]', 'flesh (as swelling out), as living or for food; generally food of any kind; figuratively, kindred by blood body, flesh, food, (near) kin(-sman, -swoman), near (nigh) (of kin).', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1540I}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["to/ uncover"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6172}/H9024\/[H6168]', 'inflected', 'heb', 'עֶרְוָה', '["ʻervâh"]', '["nakedness/ her"]', '["n-f"]', 'nudity, literally (especially the pudenda) or figuratively (disgrace, blemish) nakedness, shame, unclean(-ness).', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0269}/H9021/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["[is] sister/ your","sister/ your"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4138}/[H3205]', 'lemma', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["one born","one born of"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2351>', 'opaque', 'heb', 'חוּץ', '["chûwts"]', '["<of> outside","[the] open places","[the] outside","[the] street","[the] streets","[the] streets of","outside","streets"]', '["n-m"]', 'properly, separate by a wall, i.e. outside, outdoors abroad, field, forth, highway, more, out(-side, -ward), street, without.', 'or (shortened) חֻץ; (both forms feminine in the plural) from an unused root meaning to sever;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6172}/H9029\/[H6168]', 'inflected', 'heb', 'עֶרְוָה', '["ʻervâh"]', '["nakedness/ their"]', '["n-f"]', 'nudity, literally (especially the pudenda) or figuratively (disgrace, blemish) nakedness, shame, unclean(-ness).', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6172}/H9029/[H6168]', 'inflected', 'heb', 'עֶרְוָה', '["ʻervâh"]', '["nakedness/ their"]', '["n-f"]', 'nudity, literally (especially the pudenda) or figuratively (disgrace, blemish) nakedness, shame, unclean(-ness).', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2007}\/[H2004]', 'inflected', 'heb', 'הֵנָּה', '["hênnâh"]', '["they"]', '["p"]', 'themselves (often used emphatic for the copula, also in indirect relation) × in, × such (and such things), their, (into) them, thence, therein, these, they (had), on this side, whose, wherein.', 'prolongation for 2004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1733}/H9021/[H1730]', 'inflected', 'heb', 'דּוֹדָה', '["dôwdâh"]', '["[is] aunt/ your"]', '["n-f"]', 'an aunt aunt, father''s sister, uncle''s wife.', 'feminine of 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1323G}/H9024/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ daughter/ her","and/ daughters/ her","and/ daughters/ its"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1323G}/H9024/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["daughter/ her"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6172}/H9024/[H6168]', 'inflected', 'heb', 'עֶרְוָה', '["ʻervâh"]', '["nakedness/ her"]', '["n-f"]', 'nudity, literally (especially the pudenda) or figuratively (disgrace, blemish) nakedness, shame, unclean(-ness).', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7608}/[H7607]', 'lemma', 'heb', 'שַׁאֲרָה', '["shaʼărâh"]', '["[are] relative[s]"]', '["n-f"]', 'female kindred by blood near kinswomen.', 'feminine of 7607;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2154}/[H2161]', 'lemma', 'heb', 'זִמָּה', '["zimmâh"]', '["<of> wickedness","[is] wickedness","[the] licentiousness of","[the] wickedness of","a plan of","evil purposes","licentiousness","wickedness"]', '["n-f"]', 'a plan, especially a bad one heinous crime, lewd(-ly, -ness), mischief, purpose, thought, wicked (device, mind, -ness).', 'or זַמָּה; from 2161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6887E}/[H6887]', 'inflected', 'heb', 'צָרַר', '["tsârar"]', '["to/ make [her] a rival wife"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2416E}/H9024/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["in/ life/ her"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5079}/[H5074]', 'inflected', 'heb', 'נִדָּה', '["niddâh"]', '["by/ [the] impurity of","in/ [the] menstruous impurity of"]', '["n-f"]', 'properly, rejection; by implication, impurity, especially personal (menstruation) or moral (idolatry, incest) × far, filthiness, × flowers, menstruous (woman), put apart, × removed (woman), separation, set apart, unclean(-ness, thing, with filthiness).', 'from 5074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5997}/H9021/[H5997]', 'inflected', 'heb', 'עָמִית', '["ʻâmîyth"]', '["fellow citizen/ your"]', '["n-m"]', 'companionship; hence (concretely) a comrade or kindred man another, fellow, neighbour.', 'from a primitive root meaning to associate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7903}/H9021/[H7901]', 'inflected', 'heb', 'שְׁכֹבֶת', '["shᵉkôbeth"]', '["copulation/ your"]', '["n-f"]', 'a (sexual) lying with × lie.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2233I}/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["for/ seed"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2233H}/H9021/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ any of/ offspring/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5674A}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["to/ [those who] pass by of","to/ cause to pass","to/ make pass","to/ make pass through","to/ pass","to/ pass out","to/ pass over","to/ pass through"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4432}/[H4427]', 'inflected', 'heb', 'מֹלֶךְ', '["Môlek"]', '["to <the>/ Molech"]', '["n-pr-m"]', 'Molek (i.e. king), the chief deity of the Ammonites Molech. Compare 4445.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5975J}/[H5975]', 'lemma', 'heb', 'עָמַד', '["ʻâmad"]', '["she will stand"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7250}/H9034/[H7250]', 'inflected', 'heb', 'רָבַע', '["râbaʻ"]', '["to/ stretch out with/ it"]', '["v"]', 'to squat or lie out flat, i.e. (specifically) in copulation let gender, lie down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8397}/[H1101]', 'lemma', 'heb', 'תֶּבֶל', '["tebel"]', '["[is] confusion","confusion"]', '["n-m"]', 'mixture, i.e. unnatural bestiality confusion.', 'apparently from 1101;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440G}/H9026/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6485H}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ I visited","and/ I will punish","and/ I will visit","and/ I will visit [judgment]","and/ I will visit [them]"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6958}/[H6958]', 'inflected', 'heb', 'קוֹא', '["qôwʼ"]', '["and/ it vomited up"]', '["v"]', 'to vomit spue (out), vomit (out, up, up again).', 'or קָיָה; (Jeremiah 25:27), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3427}/H9024/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["inhabitants/ its"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8441}/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["<the>/ abomination","the/ abomination","the/ abominations","the/ abominations of"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6958}/[H6958]', 'lemma', 'heb', 'קוֹא', '["qôwʼ"]', '["it vomited up","it will vomit up"]', '["v"]', 'to vomit spue (out), vomit (out, up, up again).', 'or קָיָה; (Jeremiah 25:27), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2930A}/H9046/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["when/ make unclean/ you"]', '["v"]', 'to be foul, especially in a ceremial or moral sense (contaminated) defile (self), pollute (self), be (make, make self, pronounce) unclean, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971B}/H9028/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["people/ their"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2708}/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["any of/ [the] customs of"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9026\/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0457}/[H408]', 'inflected', 'heb', 'אֱלִיל', '["ʼĕlîyl"]', '["<the>/ worthless idols","<the>/ worthlessness","the/ idol","the/ idols"]', '["a-m"]', 'good for nothing, by analogy vain or vanity; specifically an idol idol, no value, thing of nought.', 'apparently from 408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7522}/H9026/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["for/ acceptance/ your"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2076}/H9033/[H2076]', 'inflected', 'heb', 'זָבַח', '["zâbach"]', '["you will sacrifice/ it"]', '["v"]', 'to slaughter an animal (usually in sacrifice) kill, offer, (do) sacrifice, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2077}/H9026/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["sacrifice/ your","sacrifices/ your"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0398}/H9033/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ [those who] eat/ it","and/ feed/ him","so/ we may eat/ him"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7114B}/H9046/[H7114]', 'inflected', 'heb', 'קָצַר', '["qâtsar"]', '["and/ when/ harvest/ you"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776G>/H9026', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["land/ your"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6285}/[H6311]', 'lemma', 'heb', 'פֵּאָה', '["pêʼâh"]', '["[is the] side of","[the] corner","[the] corners of","[the] forehead of","[the] side","[the] side of"]', '["n-f"]', 'properly, mouth in a figurative sense, i.e. direction, region, extremity corner, end, quarter, side.', 'feminine of 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704G>/H9021', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["field/ your","fields/ your"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7114B}/[H7114]', 'inflected', 'heb', 'קָצַר', '["qâtsar"]', '["to the/ harvesters","to/ harvest"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3951}/[H3950]', 'inflected', 'heb', 'לֶקֶט', '["leqeṭ"]', '["and/ [the] remnant of"]', '["n-m"]', 'the gleaning gleaning.', 'from 3950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7105A}/H9021/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["harvest/ your"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3754>/H9021', 'inflected', 'heb', 'וכרמך', '["ve./khar.me./Kha"]', '["and/ vineyard/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5953B}/[H5953]', 'lemma', 'heb', 'עָלַל', '["ʻâlal"]', '["people will glean","thoroughly <glean>","you will glean"]', '["v"]', 'to effect thoroughly; specifically, to glean (also figuratively); by implication (in a bad sense) to overdo, i.e. maltreat, be saucy to, pain, impose (also literal) abuse, affect, × child, defile, do, glean, mock, practise, thoroughly, work (wonderfully).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6528}/[H6527]', 'inflected', 'heb', 'פֶּרֶט', '["pereṭ"]', '["and/ [the] fallen grape[s] of"]', '["n-m"]', 'a stray or single berry grape.', 'from 6527;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3754>/H9021', 'opaque', 'heb', 'כֶּרֶם', '["kerem"]', '["vineyard/ your"]', '["n-m"]', 'a garden or vineyard vines, (increase of the) vineyard(-s), vintage. See also 1021.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6041}/[H6031]', 'inflected', 'heb', 'עָנִי', '["ʻânîy"]', '["[belongs] to the/ poor [person]","for <the>/ poor [person]","for the/ poor [person]","of/ an afflicted [person]","to <the>/ poor [person]"]', '["a"]', 'depressed, in mind or circumstances afflicted, humble, lowly, needy, poor.', 'from 6031; (practically the same as 6035, although the margin constantly disputes this, making 6035 subjective and objective);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3584}/[H3584]', 'lemma', 'heb', 'כָּחַשׁ', '["kâchash"]', '["I denied","he lied","it fails","it has become lean","it will fail","they cringe","they cringed","they have deceived","they have denied","they will cringe","to deceive","you will deceive"]', '["v"]', 'to be untrue, in word (to lie, feign, disown) or deed (to disappoint, fail, cringe) deceive, deny, dissemble, fail, deal falsely, be found liars, (be-) lie, lying, submit selves.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8034}/H9020/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["by/ name/ my","by/ own name/ my","in/ name/ my","on/ name/ my"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2490H}/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["and/ I have been profaned","and/ they have profaned","and/ they profaned","and/ they will be profaned","and/ they will profane","and/ you have profaned","and/ you profaned","and/ you will be profaned","and/ you will profane"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6468}/[H6466]', 'lemma', 'heb', 'פְּעֻלָּה', '["pᵉʻullâh"]', '["[be] [the] wage[s] of","[the] deeds of","[the] reward of","[the] wage[s] of","wage[s] of"]', '["n-f"]', '(abstractly) work labour, reward, wages, work.', 'feminine passive participle of 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4383}/[H3782]', 'lemma', 'heb', 'מִכְשׁוֹל', '["mikshôwl"]', '["[the] stumbling block of","a stumbling block","an obstacle","obstacle[s]","stumbling","stumbling blocks"]', '["n-m"]', 'a stumbling-block, literally or figuratively (obstacle, enticement (specifically an idol), scruple) caused to fall, offence, × (no-) thing offered, ruin, stumbling-block.', 'or מִכְשֹׁל; masculine from 3782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0430G}/H9021/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["from/ God/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5766A}/[H5765]', 'lemma', 'heb', 'עֶוֶל', '["ʻevel"]', '["[is] injustice","[is] unrighteousness","injustice","unrighteousness"]', '["n-m"]', '(moral) evil iniquity, perverseness, unjust(-ly), unrighteousness(-ly); wicked(-ness).', 'or עָוֶל; and (feminine) עַוְלָה; or עוֹלָה; or עֹלָה; from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4941G}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["by/ [the] judgment of","in <the>/ judgment","in the/ judgment","in/ judgment","on/ judgment"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440N}/[H6437]', 'lemma', 'heb', 'פָּנִים', '["pânîym"]', '["[the] face of","[the] faces of","face","faces"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6664G}/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["[are] <in>/ righteousness","in <the>/ righteousness","in/ righteousness","with/ righteousness"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7400}/[H7402]', 'lemma', 'heb', 'רָכִיל', '["râkîyl"]', '["a slanderer","slander"]', '["n-m"]', 'a scandal-monger (as travelling about) slander, carry tales, talebearer.', 'from 7402');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251I}/H9021/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["[is] brother/ your","[is] countryman/ your","[is] relative/ your","brother/ your","brothers/ your","countryman/ your","countrymen/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3824}/H9021/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["[is] in/ heart/ your","[was] in/ heart/ your","in/ heart/ your"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2399}/[H2398]', 'lemma', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["[is] sin","[the] sin of","[the] sins of","a sin of","sin","sin of","sins"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5201}/[H5201]', 'lemma', 'heb', 'נָטַר', '["nâṭar"]', '["I have kept","I will maintain","[one who] keeps","he will keep","you will keep"]', '["v"]', 'to guard; figuratively, to cherish (anger) bear grudge, keep(-er), reserve.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7453}/H9021/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["<to>/ neighbor/ your","for/ fellow-citizen/ your","to/ neighbor/ your"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0929>/H9021', 'opaque', 'heb', 'בְּהֵמָה', '["bᵉhêmâh"]', '["livestock/ your"]', '["n-f"]', 'properly, a dumb beast; especially any large quadruped or animal (often collective) beast, cattle.', 'from an unused root (probably meaning to be mute);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7250}/[H7250]', 'lemma', 'heb', 'רָבַע', '["râbaʻ"]', '["you will make lie"]', '["v"]', 'to squat or lie out flat, i.e. (specifically) in copulation let gender, lie down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3610}/[H3608]', 'lemma', 'heb', 'כִּלְאַיִם', '["kilʼayim"]', '["two kinds"]', '["n-m"]', 'two heterogeneities divers seeds (-e kinds), mingled (seed).', 'dual of 3608 in the original sense of separation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8162}/[H8162]', 'lemma', 'heb', 'שַׁעַטְנֵז', '["shaʻaṭnêz"]', '["mixed stuff"]', '["n-m"]', 'linsey-woolsey, i.e. cloth of linen and wool carded and spun together garment of divers sorts, linen and wollen.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9031\/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["on/ you"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2778C}/[H2779]', 'lemma', 'heb', 'חָרַף', '["châraph"]', '["intended"]', '["v"]', 'to pull off, i.e. (by implication) to expose (as by stripping); specifically, to betroth (as if a surrender); figuratively, to carp at, i.e. defame; to spend the winter betroth, blaspheme, defy, jeopard, rail, reproach, upbraid.', 'a primitive root; also denominative (from 2779)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6299}/[H6299]', 'inflected', 'heb', 'פָּדָה', '["pâdâh"]', '["and/ [the] [people] ransomed of","and/ certainly <to be released>"]', '["v"]', 'to sever, i.e. ransom; generally to release, preserve × at all, deliver, × by any means, ransom, (that are to be, let be) redeem(-ed), rescue, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2668}/[H2666]', 'lemma', 'heb', 'חֻפְשָׁה', '["chuphshâh"]', '["freedom"]', '["n-f"]', 'liberty (from slavery) freedom.', 'from 2666;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1244}/[H1239]', 'lemma', 'heb', 'בִּקֹּרֶת', '["biqqôreth"]', '["compensation"]', '["n-f"]', 'properly, examination, i.e. (by implication) punishment scourged.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2666}/[H2666]', 'lemma', 'heb', 'חָפַשׁ', '["châphash"]', '["she had been given freedom"]', '["v"]', 'to spread loose; figuratively, to manumit be free.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2398}\/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["he has sinned","he missed","you will purify yourselves"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6188}/[H6189]', 'inflected', 'heb', 'עָרֵל', '["ʻârêl"]', '["and/ you will regard as uncircumcised"]', '["v"]', 'to expose or remove the prepuce, whether literal (to go naked) or figurative (to refrain from using) count uncircumcised, foreskin to be uncovered.', 'a primitive root; properly, to strip; but used as denominative from 6189;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6529}/H9023/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["fruit/ his","fruit/ its"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8141}/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["and/ in the/ year","and/ in/ a year of","and/ in/ year"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1974}/[H1984]', 'lemma', 'heb', 'הִלּוּל', '["hillûwl"]', '["praise offerings","rejoicings"]', '["n-m"]', 'a celebration of thanksgiving for harvest merry, praise.', 'from 1984 (in the sense of rejoicing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2549}/[H2568]', 'inflected', 'heb', 'חֲמִישִׁי', '["chămîyshîy"]', '["<the>/ fifth","[was] the/ fifth","the/ fifth","the/ fifth [month]"]', '["a"]', 'fifth; also a fifth fifth (part).', 'or חֲמִשִּׁי; ordinal from 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3254H}/[H3254]', 'inflected', 'heb', 'יָסַף', '["yâçaph"]', '["to/ add"]', '["v"]', 'to add or augment (often adverbial, to continue to do a thing) add, × again, × any more, × cease, × come more, conceive again, continue, exceed, × further, × gather together, get more, give more-over, × henceforth, increase (more and more), join, × longer (bring, do, make, much, put), × (the, much, yet) more (and more), proceed (further), prolong, put, be (strong-) er, × yet, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8393}/H9023/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["produce/ his","produce/ its"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6049B}/[H6051]', 'lemma', 'heb', 'עָנַן', '["ʻânan"]', '["a soothsayer","soothsayers","you will practice soothsaying"]', '["v"]', 'figuratively, to act covertly, i.e. practise magic × bring, enchanter, Meonemin, observe(-r of) times, soothsayer, sorcerer.', 'a primitive root; to cover; used only as a denominative from 6051, to cloud over;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5362B}/[H5362]', 'lemma', 'heb', 'נָקַף', '["nâqaph"]', '["[they were] surrounding","he has closed","it encircled [it]","it has gone around","let them go around","surrounding","they had gone round","they have surrounded","they surround","you will encircle","you will round off"]', '["v"]', 'to strike with more or less violence (beat, fell, corrode); by implication (of attack) to knock together, i.e. surround or circulate compass (about, -ing), cut down, destroy, go round (about), inclose, round.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2206}/H9021/[H2204]', 'inflected', 'heb', 'זָקָן', '["zâqân"]', '["beard/ your"]', '["n-m"]', 'the beard (as indicating age) beard.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8296A}/[H8295]', 'inflected', 'heb', 'שֶׂרֶט', '["sereṭ"]', '["and/ cut[s]"]', '["n-m n-f"]', 'an incision cutting.', 'and שָׂרֶטֶת; from 8295;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315M}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["for/ a corpse","to/ a corpse","to/ a corpse of"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3793}/[H3789]', 'inflected', 'heb', 'כְּתֹבֶת', '["kᵉthôbeth"]', '["and/ [the] inscription of"]', '["n-f"]', 'a letter or other mark branded on the skin × any (mark).', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7085}/[H6970]', 'lemma', 'heb', 'קַעֲקַע', '["qaʻăqaʻ"]', '["an incision"]', '["n-m"]', 'an incision or gash mark.', 'from the same as 6970;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414P}/[H5414]', 'lemma', 'heb', 'נָתַן', '["nâthan"]', '["I will give","he makes [them]","he will give","he will make","it will give","they give forth","you give","you will give","you will make"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2181}/H9034/[H2181]', 'inflected', 'heb', 'זָנָה', '["zânâh"]', '["by/ making prostitute [herself]/ her"]', '["v"]', 'to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish.', 'a primitive root [highly fed and therefore wanton];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4720}/H9020/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["and/ sanctuary/ my"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0178}/[H1]', 'inflected', 'heb', 'אוֹב', '["ʼôwb"]', '["the/ necromancers"]', '["n-m"]', 'properly, a mumble, i.e. a water-skin (from its hollow sound); hence a necromancer (ventriloquist, as from a jar) bottle, familiar spirit.', 'from the same as 1 (apparently through the idea of prattling a father''s name);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3049}/[H3045]', 'inflected', 'heb', 'יִדְּעֹנִי', '["yiddᵉʻônîy"]', '["the/ soothsayer","the/ soothsayers"]', '["n-m"]', 'properly, a knowing one; specifically, a conjurer; (by impl) a ghost wizard.', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1921}/[H1921]', 'inflected', 'heb', 'הָדַר', '["hâdar"]', '["and/ you will honor"]', '["v"]', 'to swell up (literally or figuratively, active or passive); by implication, to favor or honour, be high or proud countenance, crooked place, glorious, honour, put forth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0776G>/H9026', 'inflected', 'heb', 'בארצכם', '["be./''ar.tze./Khem"]', '["in/ land/ your","in/ own land/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4060A}/[H4055]', 'inflected', 'heb', 'מִדָּה', '["middâh"]', '["by <the>/ measurement","by the/ measurement","in <the>/ measurement","with/ a measure"]', '["n-f"]', 'properly, extension, i.e. height or breadth; also a measure (including its standard); hence a portion (as measured) or a vestment; specifically, tribute (as measured) garment, measure(-ing, meteyard, piece, size, (great) stature, tribute, wide.', 'feminine of 4055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4948}/[H8254]', 'inflected', 'heb', 'מִשְׁקָל', '["mishqâl"]', '["by <the>/ weight","by the/ weight","by/ weight","by/ weight of","in <the>/ weight"]', '["n-m"]', 'weight (numerically estimated); hence, weighing (the act) (full) weight.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H4884>', 'inflected', 'heb', 'ובמשורה', '["u./va./me.su.Rah"]', '["and/ in <the>/ volume"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3976}/[H239]', 'lemma', 'heb', 'מֹאזֵן', '["môʼzên"]', '["balances of","scales","scales of"]', '["n-m"]', '(only in the dual) a pair of scales balances.', 'from 239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6664G}/[H6663]', 'lemma', 'heb', 'צֶדֶק', '["tsedeq"]', '["<of> righteousness","[are] righteousness","[is] righteousness","righteousness","righteousness of"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0068H}/[H1129]', 'lemma', 'heb', 'אֶבֶן', '["ʼeben"]', '["[the] weight of","[the] weights of","a weight","weights of"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0374}/[H374]', 'lemma', 'heb', 'אֵיפָה', '["ʼêyphâh"]', '["[the] ephah of","[will be] an ephah","a measure","an ephah","an ephah of"]', '["n-f"]', 'an ephah or measure for grain; hence, a measure in general ephah, (divers) measure(-s).', 'or (shortened) אֵפָה ; of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1969}/[H1969]', 'inflected', 'heb', 'הִין', '["hîyn"]', '["and/ a hin of"]', '["n-m"]', 'a hin or liquid measure hin.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2233H}/H9023/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["any of/ offspring/ his","one of/ offspring/ his"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7275}/H9033/[H7263]', 'inflected', 'heb', 'רָגַם', '["râgam"]', '["they will stone/ him"]', '["v"]', 'to cast together (stones), i.e. to lapidate × certainly, stone.', 'a primitive root (compare 7263, 7321, 7551);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4720}/H9020/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["sanctuary/ my"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2490H}/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["and/ to/ profane"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6944G}/H9020/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["holiness/ my","holy things/ my"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5956}/[H5956]', 'lemma', 'heb', 'עָלַם', '["ʻâlam"]', '["I will hide","[is] concealing","[those who] conceal themselves","certainly <to hide>","do you hide?","he has hidden","hidden","hidden thing","it hides itself","it was concealed","they have hidden","they will hide","you hide","you hide yourself","you will hide yourself"]', '["v"]', 'to veil from sight, i.e. conceal (literally or figuratively) × any ways, blind, dissembler, hide (self), secret (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5414G}/H9043/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["when/ gives/ he"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4940}/H9023/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["and/ on/ clan/ his"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2181}/[H2181]', 'inflected', 'heb', 'זָנָה', '["zânâh"]', '["[which] play the/ prostitute","[which] plays the/ prostitute","the/ prostitute","the/ prostitutes","those/ [who] act as prostitutes"]', '["v"]', 'to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish.', 'a primitive root [highly fed and therefore wanton];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4432}/[H4427]', 'inflected', 'heb', 'מֹלֶךְ', '["Môlek"]', '["<the>/ Molech"]', '["n-pr-m"]', 'Molek (i.e. king), the chief deity of the Ammonites Molech. Compare 4445.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971A}/H9028/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["own people/ their","people/ their"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5003}/[H5003]', 'lemma', 'heb', 'נָאַף', '["nâʼaph"]', '["[are] adulterers","[are] adulteresses","[one who] commits adultery","adulterers","adulteresses","adulterous","an adulterer","he will commit adultery","she committed adultery","they commit adultery","they have committed adultery"]', '["v"]', 'to commit adultery; figuratively, to apostatize adulterer(-ess), commit(-ing) adultery, woman that breaketh wedlock.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5003}/[H5003]', 'inflected', 'heb', 'נָאַף', '["nâʼaph"]', '["<the>/ adulterous","the/ adulterer"]', '["v"]', 'to commit adultery; figuratively, to apostatize adulterer(-ess), commit(-ing) adultery, woman that breaketh wedlock.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5003}/[H5003]', 'inflected', 'heb', 'נָאַף', '["nâʼaph"]', '["and/ the/ adulteress"]', '["v"]', 'to commit adultery; figuratively, to apostatize adulterer(-ess), commit(-ing) adultery, woman that breaketh wedlock.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0853}/H9039/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ <obj.>/ them"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7903}/H9023/[H7901]', 'inflected', 'heb', 'שְׁכֹבֶת', '["shᵉkôbeth"]', '["copulation/ his"]', '["n-f"]', 'a (sexual) lying with × lie.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7250}/[H7250]', 'inflected', 'heb', 'רָבַע', '["râbaʻ"]', '["to/ stretch out with"]', '["v"]', 'to squat or lie out flat, i.e. (specifically) in copulation let gender, lie down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6172}/H9023/[H6168]', 'inflected', 'heb', 'עֶרְוָה', '["ʻervâh"]', '["nakedness/ his"]', '["n-f"]', 'nudity, literally (especially the pudenda) or figuratively (disgrace, blemish) nakedness, shame, unclean(-ness).', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2617B}/[H2616]', 'lemma', 'heb', 'חֶסֶד', '["cheçed"]', '["[is] a shame"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1739}/[H1738]', 'lemma', 'heb', 'דָּוֶה', '["dâveh"]', '["a menstrual [rag]","faint","menstruating"]', '["a"]', 'sick (especially in menstruation) faint, menstruous cloth, she that is sick, having sickness.', 'from 1738;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4726}/H9024/[H6979]', 'inflected', 'heb', 'מָקוֹר', '["mâqôwr"]', '["spring/ her","spring/ its"]', '["n-m"]', 'properly, something dug, i.e. a (general) source (of water, even when naturally flowing; also of tears, blood (by euphemism, of the female pudenda); figuratively, of happiness, wisdom, progeny) fountain, issue, spring, well(-spring).', 'or מָקֹר; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6168}/[H6168]', 'lemma', 'heb', 'עָרָה', '["ʻârâh"]', '["he has made naked","he poured out","he will lay bare","it uncovered","it will be poured out","lay bare","you have laid bare","you lay bare"]', '["v"]', 'to be (causatively, make) bare; hence, to empty, pour out, demolish leave destitute, discover, empty, make naked, pour (out), rase, spread self, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4726}/[H6979]', 'lemma', 'heb', 'מָקוֹר', '["mâqôwr"]', '["[is] a fountain of","[the] spring of","[was] a fountain of","a fountain","a fountain of","a spring of"]', '["n-m"]', 'properly, something dug, i.e. a (general) source (of water, even when naturally flowing; also of tears, blood (by euphemism, of the female pudenda); figuratively, of happiness, wisdom, progeny) fountain, issue, spring, well(-spring).', 'or מָקֹר; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7607}/H9023/[H7604]', 'inflected', 'heb', 'שְׁאֵר', '["shᵉʼêr"]', '["body/ his","relative/ his"]', '["n-m"]', 'flesh (as swelling out), as living or for food; generally food of any kind; figuratively, kindred by blood body, flesh, food, (near) kin(-sman, -swoman), near (nigh) (of kin).', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730I>/H9023', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["loved one/ his","uncle/ his"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2399}/H9028/[H2398]', 'inflected', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["sin/ their"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2708}/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["in/ [the] customs of","in/ [the] statutes of"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3423H}/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["by/ dispossessing","to/ [those who] dispossess","to/ dispossess","to/ take possession of"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2931}/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["and <the>/ unclean","for the/ unclean [person]"]', '["a"]', 'foul in a religious sense defiled, infamous, polluted(-tion), unclean.', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2889}/[H2891]', 'inflected', 'heb', 'טָהוֹר', '["ṭâhôwr"]', '["and <the>/ pure","and/ a clean [thing]"]', '["a"]', 'pure (in a physical, chemical, ceremonial or moral sense) clean, fair, pure(-ness).', 'or טָהֹר; from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0178}/[H1]', 'lemma', 'heb', 'אוֹב', '["ʼôwb"]', '["a necromancer","necromancer","necromancy"]', '["n-m"]', 'properly, a mumble, i.e. a water-skin (from its hollow sound); hence a necromancer (ventriloquist, as from a jar) bottle, familiar spirit.', 'from the same as 1 (apparently through the idea of prattling a father''s name);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3049}/[H3045]', 'lemma', 'heb', 'יִדְּעֹנִי', '["yiddᵉʻônîy"]', '["a soothsayer"]', '["n-m"]', 'properly, a knowing one; specifically, a conjurer; (by impl) a ghost wizard.', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7275}/[H7263]', 'lemma', 'heb', 'רָגַם', '["râgam"]', '["certainly <to stone>","it will stone","people will stone","they will stone"]', '["v"]', 'to cast together (stones), i.e. to lapidate × certainly, stone.', 'a primitive root (compare 7263, 7321, 7551);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9038}\', 'inflected', 'heb', 'בהם ס', '["Ba/m","Va/m","ba./Hem","va./Hem"]', '["<in> <the>/ them","[are] on <the>/ them","among <the>/ them","in/ them","on/ them","with <the>/ them","with/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5971B}/H9023/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["among/ kinspeople<s>/ his"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7607}/H9023/[H7604]', 'inflected', 'heb', 'שְׁאֵר', '["shᵉʼêr"]', '["for/ relative/ his","to/ relative/ his"]', '["n-m"]', 'flesh (as swelling out), as living or for food; generally food of any kind; figuratively, kindred by blood body, flesh, food, (near) kin(-sman, -swoman), near (nigh) (of kin).', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0251G}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ [belonged] to/ brothers/ his","and/ for/ brother/ his","and/ to/ brother/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0269}/H9023/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["and/ for/ sister/ his"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1330>', 'inflected', 'heb', 'הבתולה', '["ha./be.tu.Lah","ha./be.tu.Lot"]', '["the/ virgin","the/ virgins"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0376H>', 'inflected', 'heb', 'לאיש', '["le./''Ish"]', '["to/ a husband","to/ a man"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2490H}/H9033/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["to/ profane/ himself","to/ profane/ it"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7139}/[H7139]', 'lemma', 'heb', 'קָרַח', '["qârach"]', '["[was] made bald","anyone will make himself bald","make bald","they will make bald"]', '["v"]', 'to depilate make (self) bald.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7144}/[H7139]', 'lemma', 'heb', 'קׇרְחָה', '["qorchâh"]', '["[will be] baldness","baldness"]', '["n-f"]', 'baldness bald(-ness), × utterly.', 'or קׇרְחָא; (Ezekiel 27:31), from 7139;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7218A>/H9028', 'inflected', 'heb', 'בראשיהם', '["be./Ra.shei./Hem","be./ra.shei./Hem","be./ro.Sha/m"]', '["on/ head/ their","on/ heads/ their","on/ own head/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6285}/[H6311]', 'inflected', 'heb', 'פֵּאָה', '["pêʼâh"]', '["and/ [the] side of","and/ [will be the] side of"]', '["n-f"]', 'properly, mouth in a figurative sense, i.e. direction, region, extremity corner, end, quarter, side.', 'feminine of 6311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2206}/H9028/[H2204]', 'inflected', 'heb', 'זָקָן', '["zâqân"]', '["beard/ their"]', '["n-m"]', 'the beard (as indicating age) beard.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1320}/H9028/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["and/ in/ flesh/ their"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8295}/[H8295]', 'lemma', 'heb', 'שָׂרַט', '["sâraṭ"]', '["severely <injure>","they will cut","they will injure themselves"]', '["v"]', 'to gash cut in pieces, make [cuttings] pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8296B}/[H8295]', 'lemma', 'heb', 'שֶׂרֶט', '["sereṭ"]', '["cut[s]"]', '["n-m n-f"]', 'an incision cutting.', 'and שָׂרֶטֶת; from 8295;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0430G}/H9028/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["to/ God/ their"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2491B}/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["and/ a [woman] profaned"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0376H>/H9024', 'inflected', 'heb', 'מאישה', '["me./''i.Sha/h"]', '["from/ husband/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0430G}/H9023/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["<to>/ God/ his","by/ God/ his","for/ God/ his","to/ God/ his"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0251H}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["from/ brothers/ his","more than/ brothers/ his","of/ brothers/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315M}/[H5314]', 'lemma', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["a corpse","corpse of","corpses of"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0517}/H9023/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["and/ for/ mother/ his","and/ of/ mother/ his","and/ to/ mother/ his"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1331}/H9024/[H1330]', 'inflected', 'heb', 'בְּתוּלִים', '["bᵉthûwlîym"]', '["in/ virginiti<es>/ her"]', '["n-f"]', '(collectively and abstractly) virginity; by implication and concretely, the tokens of it × maid, virginity.', 'masculine plural of the same as 1330;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1644H}/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["and/ a divorced [woman]"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942G}/H9033\/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["[who] sets apart as holy/ him"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3971B>', 'opaque', 'heb', 'מאוּם', '["mʼûwm"]', '["[is] a blemish","a blemish","blemish"]', '["n-m"]', 'a blemish (physically or morally) blemish, blot, spot.', 'usually מוּם; as if passive participle from an unused root probably meaning to stain');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6455}/[H6452]', 'lemma', 'heb', 'פִּסֵּחַ', '["piççêach"]', '["[is] lame","[was] lame","a lame [animal]","a lame [person]","lame","lame [people]"]', '["a"]', 'lame lame.', 'from 6452;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2763B}/[H2763]', 'lemma', 'heb', 'חָרַם', '["châram"]', '["[having] a slit nose"]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8311}/[H8311]', 'lemma', 'heb', 'שָׂרַע', '["sâraʻ"]', '["[having] something enlarged"]', '["v"]', 'to prolong, i.e. (reflex) be deformed by excess of members stretch out self, (have any) superfluous thing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7667}/[H7665]', 'lemma', 'heb', 'שֶׁבֶר', '["sheber"]', '["[is] brokenness","[the] brokenness of","[the] fracture of","[the] ruin of","a breaking","a fracture","a fracture of","breaking","destruction","ruin","shattering"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1384>', 'opaque', 'heb', 'גִּבֵּן', '["gibbên"]', '["a [man] hunchbacked"]', '["a"]', 'hunch-backed crookbackt.', 'from an unused root meaning to be arched or contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8400}/[H1101]', 'lemma', 'heb', 'תְּבַּלֻּל', '["tᵉballul"]', '["a defect"]', '["n-m"]', 'a cataract (in the eye) blemish.', 'from 1101 in the original sense of flowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1618>', 'opaque', 'heb', 'גָּרָב', '["gârâb"]', '["eczema"]', '["n-m"]', 'scurf (from itching) scab, scurvy.', 'from an unused root meaning to scratch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3217>', 'opaque', 'heb', 'יַלֶּפֶת', '["yallepheth"]', '["scabs"]', '["n-f"]', 'scurf or tetter scabbed.', 'from an unused root apparently meaning to stick or scrape;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4790}/[H4799]', 'lemma', 'heb', 'מְרוֹחַ', '["mᵉrôwach"]', '["a [man] crushed of"]', '["n-m"]', 'bruised, i.e. emasculated broken.', 'from 4799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0810>', 'opaque', 'heb', 'אֶשֶׁךְ', '["ʼeshek"]', '["testicle"]', '["n-m"]', 'a testicle (as a lump) stone.', 'from an unused root (probably meaning to bunch together);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2233H}/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["[are] of/ [the] offspring of","[is] one of/ [the] offspring of","[was] one of/ [the] offspring","from/ [the] offspring of","one of/ [the] descendant[s] of","one of/ [the] offspring of"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942G}/H9038/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["[who] sanctified/ them","[who] sets apart as holy/ them"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5144A}/[H5144]', 'inflected', 'heb', 'נָזַר', '["nâzar"]', '["so/ he may separate himself","so/ they may separate themselves"]', '["v"]', 'to hold aloof, i.e. (intransitivey) abstain (from food and drink, from impurity, and even from divine worship (i.e. apostatize)); specifically, to set apart (to sacred purposes), i.e. devote consecrate, separate(-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2490H}/H9033/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["they had profaned/ it","they will profane/ it"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3548}/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["and/ [we are] priests","and/ a priest"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7075}/[H7069]', 'lemma', 'heb', 'קִנְיָן', '["qinyân"]', '["[the] acquisition of"]', '["n-m"]', 'creation, i.e. (concretely) creatures; also acquisition, purchase, wealth getting, goods, × with money, riches, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3211}/[H3205]', 'inflected', 'heb', 'יָלִיד', '["yâlîyd"]', '["and/ [the] one born of"]', '["a"]', 'born (home-) born, child, son.', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3899G}/H9023/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["in/ food/ his","with/ bread/ its"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8641}/[H7311]', 'inflected', 'heb', 'תְּרוּמָה', '["tᵉrûwmâh"]', '["in/ [the] contribution of"]', '["n-f"]', 'a present (as offered up), especially in sacrifice or as tribute gift, heave offering (shoulder), oblation, offered(-ing).', 'or תְּרֻמָה; (Deuteronomy 12:11), from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2233H}/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ [the] offspring of","and/ offspring"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5271A}/H9024/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["like/ youth<s>/ her"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3899G}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["any of/ [the] food of"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9033}\', 'inflected', 'heb', 'בו ס', '["b/o","v/o"]', '["against <the>/ him","in <the>/ it","in/ it","on/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0819}/[H817]', 'lemma', 'heb', 'אַשְׁמָה', '["ʼashmâh"]', '["[are] guilt<s>","[the] guilt of","guilt"]', '["n-f"]', 'guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering).', 'feminine of 817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0398}/H9048/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["when/ ate/ they","when/ eat/ they"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942G}/H9038\/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["[who] sets apart as holy/ them"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5088}/H9028/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["vows/ their"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5071}/H9028/[H5068]', 'inflected', 'heb', 'נְדָבָה', '["nᵉdâbâh"]', '["freewill offerings/ their"]', '["n-f"]', 'properly (abstractly) spontaneity, or (adjectively) spontaneous; also (concretely) a spontaneous or (by inference, in plural) abundant gift free(-will) offering, freely, plentiful, voluntary(-ily, offering), willing(-ly), offering).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5795}/[H5810]', 'inflected', 'heb', 'עֵז', '["ʻêz"]', '["and/ among the/ goats"]', '["n-f"]', 'a she-goat (as strong), but masculine in plural (which also is used elliptically for goat''s hair) (she) goat, kid.', 'from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6381}/[H6381]', 'inflected', 'heb', 'פָּלָא', '["pâlâʼ"]', '["to/ deal wonderfully with","to/ fulfill"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5071}/[H5068]', 'inflected', 'heb', 'נְדָבָה', '["nᵉdâbâh"]', '["to/ a freewill offering"]', '["n-f"]', 'properly (abstractly) spontaneity, or (adjectively) spontaneous; also (concretely) a spontaneous or (by inference, in plural) abundant gift free(-will) offering, freely, plentiful, voluntary(-ily, offering), willing(-ly), offering).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5788B}/[H5787]', 'lemma', 'heb', 'עִוָּרוֹן', '["ʻivvârôwn"]', '["blindness"]', '["n-m"]', 'blindness blind(-ness).', 'and (feminine) עַוֶּרֶת; from 5787;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2742A}/[H2782]', 'lemma', 'heb', 'חֲרוּץ', '["chărûwts"]', '["a diligent [person]","a mutilation","a threshing sledge","diligent","diligent [people]","sharp"]', '["a"]', 'properly, incised or (active) incisive; hence (as noun masculine or feminine) a trench (as dug), gold (as mined), a threshing-sledge (having sharp teeth); (figuratively) determination; also eager decision, diligent, (fine) gold, pointed things, sharp, threshing instrument, wall.', 'or חָרֻץ; passive participle of 2782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2990}/[H2986]', 'lemma', 'heb', 'יַבֵּל', '["yabbêl"]', '["a wart"]', '["n-m"]', 'having running sores wen.', 'from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0801}/[H800]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ a fire offering"]', '["n-m"]', 'properly, a burnt-offering; but occasionally of any sacrifice (offering, sacrifice), (made) by fire.', 'the same as 800, but used in a liturgical sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7038}/[H7038]', 'inflected', 'heb', 'קָלַט', '["qâlaṭ"]', '["and/ [having] something stunted"]', '["v"]', 'to maim lacking in his parts.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5088}/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["and/ for/ a vow"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4600}/[H4600]', 'inflected', 'heb', 'מָעַךְ', '["mâʻak"]', '["and/ [one which] is squashed"]', '["v"]', 'to press, i.e. to pierce, emasculate, handle bruised, stuck, be pressed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3807}/[H3807]', 'inflected', 'heb', 'כָּתַת', '["kâthath"]', '["and/ [one which] is crushed"]', '["v"]', 'to bruise or violently strike beat (down, to pieces), break in pieces, crushed, destroy, discomfit, smite, stamp. l', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5423}/[H5423]', 'inflected', 'heb', 'נָתַק', '["nâthaq"]', '["and/ [one which] is torn"]', '["v"]', 'to tear off break (off), burst, draw (away), lift up, pluck (away, off), pull (out), root out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3772G}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ [one which] is cut","and/ [one who] is cut off of","so/ I may cut down","so/ they may cut"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H0776G>/H9026', 'inflected', 'heb', 'ובארצכם', '["u./ve./''ar.tze./Khem"]', '["and/ in/ land/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4893B}/H9028/[H7843]', 'inflected', 'heb', 'מִשְׁחָת', '["mishchâth"]', '["disfigurement/ their"]', '["n-m"]', 'disfigurement corruption, marred.', 'or מׇשְׁחָת; from 7843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H3117G>', 'inflected', 'heb', 'ומיום', '["u./mi./Yom"]', '["and/ from/ [the] day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1973}/[H1973]', 'inflected', 'heb', 'הָלְאָה', '["hâlᵉʼâh"]', '["and/ beyond","and/ onwards"]', '["adv"]', 'to the distance, i.e. far away; also (of time) thus far back, beyond, (hence,-) forward, hitherto, thence, forth, yonder.', 'from the primitive form of the article (hal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7133A}/[H7126]', 'inflected', 'heb', 'קׇרְבָּן', '["qorbân"]', '["to/ a present of"]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121H}/H9023/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["young/ its"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4150H}/[H3259]', 'lemma', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["<of> an appointed feast","[are] [the] appointed feasts of","[the] appointed feasts of","[the] appointed times of","an appointed feast","appointed feast"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4150H}/H9020/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["[are] appointed feasts/ my","appointed times/ my"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4186}/H9026\/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["dwelling places/ your"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4150G}/H9028/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["at/ appointed time/ their"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2568}/[H2568]', 'inflected', 'heb', 'חָמֵשׁ', '["châmêsh"]', '["and/ [is] on/ [the] fif-","and/ [will be] on/ [the] fif-","and/ on/ [the] fif-"]', '["n"]', 'five fif(-teen), fifth, five (× apiece).', 'masculine חֲמִשָּׁה; a primitive numeral;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7114B}/[H7114]', 'inflected', 'heb', 'קָצַר', '["qâtsar"]', '["and/ you will harvest"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7105A}/H9024/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["harvest/ its"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6016A}/[H6014]', 'lemma', 'heb', 'עֹמֶר', '["ʻômer"]', '["<the> sheaf of","[the] sheaf of","a sheaf"]', '["n-m"]', 'properly, a heap, i.e. a sheaf; also an omer, as a dry measure omer, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7105A}/H9026/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["harvest/ your"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6016A}/[H6014]', 'inflected', 'heb', 'עֹמֶר', '["ʻômer"]', '["the/ sheaf","the/ sheaves"]', '["n-m"]', 'properly, a heap, i.e. a sheaf; also an omer, as a dry measure omer, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5130B}/H9033/[H5130]', 'inflected', 'heb', 'נוּף', '["nûwph"]', '["[the] [one who] wields/ it","he will wave/ it"]', '["v"]', 'to quiver (i.e. vibrate up and down, or rock to and fro); used in a great variety of applications (including sprinkling, beckoning, rubbing, bastinadoing, sawing, waving, etc.) lift up, move, offer, perfume, send, shake, sift, strike, wave.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5130B}/H9046/[H5130]', 'inflected', 'heb', 'נוּף', '["nûwph"]', '["wave/ you"]', '["v"]', 'to quiver (i.e. vibrate up and down, or rock to and fro); used in a great variety of applications (including sprinkling, beckoning, rubbing, bastinadoing, sawing, waving, etc.) lift up, move, offer, perfume, send, shake, sift, strike, wave.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4503G>/H9023', 'inflected', 'heb', 'ומנחתו', '["u./min.cha.T/o"]', '["and/ grain offering/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5262}/H9023/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ drink offering/ its"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7039}/[H7033]', 'inflected', 'heb', 'קָלִי', '["qâlîy"]', '["and/ roasted grain"]', '["n-m"]', 'roasted ears of grain parched corn.', 'or קָלִיא; from 7033;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3759}/[H3754]', 'inflected', 'heb', 'כַּרְמֶל', '["karmel"]', '["and/ new corn"]', '["n-m"]', 'a planted field (garden, orchard, vineyard or park); by implication, garden produce full (green) ears (of corn), fruitful field (place), plentiful (field).', 'from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6106H}/[H6105]', 'lemma', 'heb', 'עֶצֶם', '["ʻetsem"]', '["[the] substance of"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935P}/H9046/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["bring/ you","brought/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4186}/H9026/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["from/ dwelling places/ your"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4503G>/H9028', 'inflected', 'heb', 'ומנחתם', '["u./Min.cha.Ta/m","u./min.cha.Ta/m"]', '["and/ grain offering/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5262}/H9028/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ drink offerings/ their"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1061}/[H1069]', 'inflected', 'heb', 'בִּכּוּר', '["bikkûwr"]', '["the/ first-fruits"]', '["n-m"]', 'the first-fruits of the crop first fruit (-ripe (figuratively)), hasty fruit.', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7114B}/H9041/[H7114]', 'inflected', 'heb', 'קָצַר', '["qâtsar"]', '["when/ harvesting/ you"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8643}/[H7321]', 'lemma', 'heb', 'תְּרוּעָה', '["tᵉrûwʻâh"]', '["<of> a shout of joy","[the] shout of","[the] sound of a loud blast","a shout","a shout of","a shout of joy","a sound of a loud blast","an alarm","shouting"]', '["n-f"]', 'clamor, i.e. acclamation of joy or a battle-cry; especially clangor of trumpets, as an alarum alarm, blow(-ing) (of, the) (trumpets), joy, jubile, loud noise, rejoicing, shout(-ing), (high, joyful) sound(-ing).', 'from 7321;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3725}/[H3722]', 'lemma', 'heb', 'כִּפֻּר', '["kippur"]', '["atonement<s>"]', '["n-m"]', 'expiation (only in plural) atonement.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5315I}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["<the>/ person"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0006}/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["and/ I will destroy","and/ he will destroy","and/ he will perish","and/ it has been lost","and/ it perishes","and/ it was lost","and/ it will be destroyed","and/ it will be lost","and/ it will perish","and/ she destroyed","and/ they have perished","and/ they perished","and/ they were lost","and/ they will perish","and/ will it perish","and/ will it perish?","and/ you have destroyed","and/ you will destroy","and/ you will perish"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971A}/H9024/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["people/ her","people/ its"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8672}/[H8159]', 'inflected', 'heb', 'תֵּשַׁע', '["têshaʻ"]', '["on/ [day] nine"]', '["n"]', 'nine or (ordinal) ninth nine ( -teen, -teenth, -th).', 'or (masculine) תִּשְׁעָה; perhaps from 8159 through the idea of a turn to the next or full number ten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7673B}/[H7673]', 'lemma', 'heb', 'שָׁבַת', '["shâbath"]', '["you will cease"]', '["v"]', 'to repose, i.e. desist from exertion; used in many implied relations (causative, figurative or specific) (cause to, let, make to) cease, celebrate, cause (make) to fail, keep (sabbath), suffer to be lacking, leave, put away (down), (make to) rest, rid, still, take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7676}/H9026\/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["sabbath/ your"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5521}/[H5520]', 'inflected', 'heb', 'סֻכָּה', '["çukkâh"]', '["<the>/ Tabernacles","<the>/ booths","the/ booths"]', '["n-f"]', 'a hut or lair booth, cottage, covert, pavilion, tabernacle, tent.', 'feminine of 5520;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6116}/[H6113]', 'lemma', 'heb', 'עֲצָרָה', '["ʻătsârâh"]', '["[is] a solemn assembly","an assembly","an assembly of"]', '["n-f"]', 'an assembly, especially on a festival or holiday (solemn) assembly (meeting).', 'or עֲצֶרֶת; from 6113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3117J>/H9023', 'inflected', 'heb', 'ביומו', '["be./yo.M/o"]', '["in/ day/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/H9005/{H0905J}/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["and/ <from>/ <to>/ besides"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4979}/H9026/[H4976]', 'inflected', 'heb', 'מַתָּנָה', '["mattânâh"]', '["gifts/ your"]', '["n-f"]', 'a present; specifically (in a good sense), a sacrificial offering, (in a bad sense) a bribe gift.', 'feminine of 4976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5088}/H9026/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["votive offerings/ your","vows/ your"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5071}/H9026/[H5068]', 'inflected', 'heb', 'נְדָבָה', '["nᵉdâbâh"]', '["freewill offerings/ your"]', '["n-f"]', 'properly (abstractly) spontaneity, or (adjectively) spontaneous; also (concretely) a spontaneous or (by inference, in plural) abundant gift free(-will) offering, freely, plentiful, voluntary(-ily, offering), willing(-ly), offering).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0622}/H9046/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["when/ have gathered/ you"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8393}/[H935]', 'lemma', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["[the] produce of","[the] produce<s> of","[the] yield of","gains","income","produce","produce of","produce<s>"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1926}/[H1921]', 'lemma', 'heb', 'הָדָר', '["hâdâr"]', '["[is] honor","[the] majesty of","[the] splendor of","splendor"]', '["n-m"]', 'magnificence, i.e. ornament or splendor beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6057>', 'inflected', 'heb', 'וענף', '["va./''a.Naf","ve./''a.Naf"]', '["and/ branch","and/ branch[es] of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5687}/[H5686]', 'lemma', 'heb', 'עָבֹת', '["ʻâbôth"]', '["leafy"]', '["a"]', 'intwined, i.e. dense thick.', 'or עָבוֹת; from 5686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6155H}/[H6148]', 'inflected', 'heb', 'עָרָב', '["ʻârâb"]', '["and/ poplars of"]', '["n-f"]', 'a willow (from the use of osiers as wattles) willow.', 'from 6148;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5158A}/[H5157]', 'lemma', 'heb', 'נַחַל', '["nachal"]', '["[the] wadi","[the] wadi of","a river","a shaft","a wadi","a wadi of","torrents of","two rivers","wadis"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5521}/[H5520]', 'inflected', 'heb', 'סֻכָּה', '["çukkâh"]', '["in <the>/ booths","in <the>/ thicket","in the/ booths","in/ a shelter"]', '["n-f"]', 'a hut or lair booth, cottage, covert, pavilion, tabernacle, tent.', 'feminine of 5520;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1755}/H9026/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["generations/ your"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1696I}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ I will speak","and/ he spoke","and/ it spoke","and/ they spoke","and/ you have spoken"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2471}/[H2490]', 'inflected', 'heb', 'חַלָּה', '["challâh"]', '["the/ round perforated bread"]', '["n-f"]', 'a cake (as usually punctured) cake.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4635}/[H6186]', 'lemma', 'heb', 'מַעֲרֶכֶת', '["maʻăreketh"]', '["rows"]', '["n-f"]', 'an arrangement, i.e. (concretely) a pile (of loaves) row, shewbread.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4635}/[H6186]', 'inflected', 'heb', 'מַעֲרֶכֶת', '["maʻăreketh"]', '["the/ row"]', '["n-f"]', 'an arrangement, i.e. (concretely) a pile (of loaves) row, shewbread.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0234}/[H2142]', 'inflected', 'heb', 'אַזְכָּרָה', '["ʼazkârâh"]', '["to/ a memorial offering"]', '["n-f"]', 'a reminder; specifically remembrance-offering memorial.', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6186A}/H9033/[H6186]', 'inflected', 'heb', 'עָרַךְ', '["ʻârak"]', '["he will arrange/ it"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0398}/H9033/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ he fed/ him","and/ he will eat/ it","and/ they have consumed/ him","and/ they will eat/ it","and/ we ate/ him","and/ we will eat/ it"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5769G}\/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["perpetuity"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3481H}/[H3478]', 'lemma', 'heb', 'יִשְׂרְאֵלִי', '["Yisrᵉʼêlîy"]', '["Israelite"]', '["a"]', 'a Jisreelite or descendant of Jisrael of Israel, Israelite.', 'patronymically from 3478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5327A}/[H5327]', 'inflected', 'heb', 'נָצָה', '["nâtsâh"]', '["and/ they struggled together"]', '["v"]', 'properly, to go forth, i.e. (by implication) to be expelled, and (consequently) desolate; causatively, to lay waste; also (specifically), to quarrel be laid waste, runinous, strive (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3481H}/[H3478]', 'inflected', 'heb', 'יִשְׂרְאֵלִי', '["Yisrᵉʼêlîy"]', '["<the>/ Israelite","the/ Israelite [woman]","the/ Israelite[s]"]', '["a"]', 'a Jisreelite or descendant of Jisrael of Israel, Israelite.', 'patronymically from 3478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5344A}/[H5344]', 'inflected', 'heb', 'נָקַב', '["nâqab"]', '["and/ he bored","and/ he slandered"]', '["v"]', 'to puncture, literally (to perforate, with more or less violence) or figuratively (to specify, designate, libel) appoint, blaspheme, bore, curse, express, with holes, name, pierce, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8034}/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["<the>/ name","the/ name"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8019B}/[H7965]', 'lemma', 'heb', 'שְׁלֹמִית', '["Shᵉlômîyth"]', '["[was] Shelomith"]', '["n-pr-m n-pr-f"]', 'Shelomith, the name of five Israelites and three Israelitesses Shelomith.', 'or שׁלוֹמִית; (Ezra 8:10), from 7965; peaceableness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1704}/[H1697]', 'lemma', 'heb', 'דִּבְרִי', '["Dibrîy"]', '["Dibri"]', '["n-pr-m"]', 'Dibri, an Israelite Dibri.', 'from 1697; wordy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6567A}/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["to/ decide"]', '["v"]', 'to separate, literally (to disperse) or figuratively (to specify); also (by implication) to wound scatter, declare, distinctly, shew, sting.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7043}/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["the/ [one who] cursed","the/ [one who] had cursed"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7275}/[H7263]', 'inflected', 'heb', 'רָגַם', '["râgam"]', '["and/ they stoned","and/ they will stone"]', '["v"]', 'to cast together (stones), i.e. to lapidate × certainly, stone.', 'a primitive root (compare 7263, 7321, 7551);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2399}/H9023/[H2398]', 'inflected', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["sin/ his"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5344B}/[H5344]', 'inflected', 'heb', 'נָקַב', '["nâqab"]', '["and/ [one who] slanders"]', '["v"]', 'to puncture, literally (to perforate, with more or less violence) or figuratively (to specify, designate, libel) appoint, blaspheme, bore, curse, express, with holes, name, pierce, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1616}/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["as the/ sojourner","like/ a sojourner"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5344B}/H9043/[H5344]', 'inflected', 'heb', 'נָקַב', '["nâqab"]', '["when/ slanders/ he"]', '["v"]', 'to puncture, literally (to perforate, with more or less violence) or figuratively (to specify, designate, libel) appoint, blaspheme, bore, curse, express, with holes, name, pierce, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7999A}/H9034/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["he will repay/ it","will he repay/ it"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7673B}/[H7673]', 'inflected', 'heb', 'שָׁבַת', '["shâbath"]', '["and/ it will cease"]', '["v"]', 'to repose, i.e. desist from exertion; used in many implied relations (causative, figurative or specific) (cause to, let, make to) cease, celebrate, cause (make) to fail, keep (sabbath), suffer to be lacking, leave, put away (down), (make to) rest, rid, still, take away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2168}/[H2167]', 'lemma', 'heb', 'זָמַר', '["zâmar"]', '["it will be pruned","you will prune"]', '["v"]', 'to trim (a vine) prune.', 'a primitive root (compare 2167, 5568, 6785);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5599B}/[H5596]', 'lemma', 'heb', 'סָפִיחַ', '["çâphîyach"]', '["[the] self-sown grain of","self-sown grain"]', '["n-m"]', 'something (spontaneously) falling off, i.e. a self-sown crop; figuratively, a freshet (such) things as (which) grow (of themselves), which groweth of its own accord (itself).', 'from 5596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7114B}/[H7114]', 'lemma', 'heb', 'קָצַר', '["qâtsar"]', '["[were] harvesting","a reaper","he will reap","reap","someone will reap","they harvest","they have reaped","they will reap","you have reaped","you will harvest","you will reap"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5139}/H9021/[H5144]', 'inflected', 'heb', 'נָזִיר', '["nâzîyr"]', '["untrimmed vines/ your"]', '["n-m"]', 'separate, i.e. consecrated (as prince, a Nazirite); hence (figuratively from the latter) an unpruned vine (like an unshorn Nazirite) Nazarite (by a false alliteration with Nazareth), separate(-d), vine undressed.', 'or נָזִר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0519}/H9021/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["and/ for/ maidservant/ your","and/ to/ female slave/ your"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7916}/H9021/[H7936]', 'inflected', 'heb', 'שָׂכִיר', '["sâkîyr"]', '["and/ to/ hired laborer/ your"]', '["a"]', 'a man at wages by the day or year hired (man, servant), hireling.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8453A}/H9021/[H3427]', 'inflected', 'heb', 'תּוֹשָׁב', '["tôwshâb"]', '["and/ to/ resident alien/ your"]', '["n-m"]', 'a dweller but not outlandish [5237]; especially (as distinguished from a native citizen [active participle of 3427] and a temporary inmate [1616] or mere lodger [3885]) resident alien foreigner, inhabitant, sojourner, stranger.', 'or תֹּשָׁב; (1 Kings 17:1), from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0929>/H9021', 'inflected', 'heb', 'ולבהמתך', '["ve./Li/v.hem.te./kha"]', '["and/ to/ livestock/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2416C}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["and/ to the/ animal[s]","and/ to/ [the] animal[s] of"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0398}\/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["to/ eat"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2572}/[H2568]', 'inflected', 'heb', 'חֲמִשִּׁים', '["chămishshîym"]', '["the/ fifties","the/ fifty"]', '["n"]', 'fifty fifty.', 'multiple of 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3104}/[H2986]', 'lemma', 'heb', 'יוֹבֵל', '["yôwbêl"]', '["[is] a jubilee","a jubilee","rams'' horns"]', '["n-m"]', 'the blast of a horn (from its continuous sound); specifically, the signal of the silver trumpets; hence, the instrument itself and the festival thus introduced jubile, ram''s horn, trumpet.', 'or יֹבֵל; apparently from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0272}/H9023/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["possession/ his"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4940}/H9023/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["clan/ his","family/ his"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5599B}/H9024/[H5596]', 'inflected', 'heb', 'סָפִיחַ', '["çâphîyach"]', '["self-sown grain/ its"]', '["n-m"]', 'something (spontaneously) falling off, i.e. a self-sown crop; figuratively, a freshet (such) things as (which) grow (of themselves), which groweth of its own accord (itself).', 'from 5596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5139}/H9024/[H5144]', 'inflected', 'heb', 'נָזִיר', '["nâzîyr"]', '["ones of high rank/ its","untrimmed vines/ its"]', '["n-m"]', 'separate, i.e. consecrated (as prince, a Nazirite); hence (figuratively from the latter) an unpruned vine (like an unshorn Nazirite) Nazarite (by a false alliteration with Nazareth), separate(-d), vine undressed.', 'or נָזִר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4465}/[H4376]', 'lemma', 'heb', 'מִמְכָּר', '["mimkâr"]', '["[the] sale of","[the] thing sold of","a thing sold","merchandise"]', '["n-m"]', 'merchandise; abstractly, a selling × ought, (that which cometh of) sale, that which...sold, ware.', 'from 4376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5997}/H9021/[H5997]', 'inflected', 'heb', 'עָמִית', '["ʻâmîyth"]', '["to/ fellow citizen/ your"]', '["n-m"]', 'companionship; hence (concretely) a comrade or kindred man another, fellow, neighbour.', 'from a primitive root meaning to associate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4557}/[H5608]', 'inflected', 'heb', 'מִסְפָּר', '["miçpâr"]', '["by/ [the] number of","by/ number","by/ number of","in/ [the] number of","in/ number"]', '["n-m"]', 'a number, definite (arithmetical) or indefinite (large, innumerable; small, a few); also (abstractly) narration abundance, account, × all, × few, (in-) finite, (certain) number(-ed), tale, telling, time.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7230}/[H7231]', 'lemma', 'heb', 'רֹב', '["rôb"]', '["[the] abundance of","[the] greatness of","[the] multitude of","[the] numerous things of","a multitude of","abundance of"]', '["n-m"]', 'abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age).', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4736}/H9023/[H4735]', 'inflected', 'heb', 'מִקְנָה', '["miqnâh"]', '["purchase price/ its","purchase/ his"]', '["n-f"]', 'properly, a buying, i.e. acquisition; concretely, a piece of property (land or living); also the sum paid (he that is) bought, possession, piece, purchase.', 'feminine of 4735;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6310K}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["and/ to/ [the] mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0983}/[H982]', 'inflected', 'heb', 'בֶּטַח', '["beṭach"]', '["to/ security"]', '["n-m"]', 'properly, a place of refuge; abstract, safety, both the fact (security) and the feeling (trust); often (adverb with or without preposition) safely assurance, boldly, (without) care(-less), confidence, hope, safe(-ly, -ty), secure, surely.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6529}/H9024/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["[is] fruit/ its","fruit/ its"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8393}/H9025/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["produce/ our"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8393}/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["the/ produce"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3465H}/[H3462]', 'lemma', 'heb', 'יָשָׁן', '["yâshân"]', '["old","old harvest"]', '["a"]', 'old old.', 'from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8671}/[H8672]', 'inflected', 'heb', 'תְּשִׁיעִי', '["tᵉshîyʻîy"]', '["<of the>/ ninth","<the>/ ninth","[was] the/ ninth","the/ ninth"]', '["a"]', 'ninth ninth.', 'ordinal from 8672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6783}/[H6789]', 'inflected', 'heb', 'צְמִיתֻת', '["tsᵉmîythuth"]', '["to <the>/ perpetuity","to/ perpetuity"]', '["n-f"]', 'excision, i.e. destruction; used only (adverbially) with prepositional prefix to extinction, i.e. perpetually ever.', 'or צְמִתֻת; from 6789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1353}/[H1350]', 'lemma', 'heb', 'גְּאֻלָּה', '["gᵉʼullâh"]', '["[the] right of redemption","a right of redemption","a right of redemption of"]', '["n-f"]', 'redemption (including the right and the object); by implication, relationship kindred, redeem, redemption, right.', 'feminine passive participle of 1350;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0776G>\', 'inflected', 'heb', 'לארץ ס', '["la./''A.retz"]', '["of the/ land","to the/ land"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4134}/[H4134]', 'lemma', 'heb', 'מוּךְ', '["mûwk"]', '["[is too] impoverished","he will become impoverished"]', '["v"]', 'to become thin, i.e. (figuratively) be impoverished be (waxen) poor(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0272}/H9023/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["from/ possession/ his","some of/ own possession/ his","some of/ possession/ his"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/H9023/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["kinsman-redeemer/ his"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H1767>', 'inflected', 'heb', 'כדי', '["ke./Dei","khe./dei"]', '["according to/ [the] abundance of","according to/ [the] sufficiency","according to/ [the] sufficiency of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1353}/H9023/[H1350]', 'inflected', 'heb', 'גְּאֻלָּה', '["gᵉʼullâh"]', '["redemption/ his","redemption/ its","right of redemption/ its"]', '["n-f"]', 'redemption (including the right and the object); by implication, relationship kindred, redeem, redemption, right.', 'feminine passive participle of 1350;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2803H}/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ he will calculate","and/ it was reckoned","and/ it will be reckoned"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4465}/H9023/[H4376]', 'inflected', 'heb', 'מִמְכָּר', '["mimkâr"]', '["sale/ his","sale/ its","sales/ his","thing sold/ his"]', '["n-m"]', 'merchandise; abstractly, a selling × ought, (that which cometh of) sale, that which...sold, ware.', 'from 4376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0272}/H9023/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["to/ possession/ his"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7069}/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["the/ [one who] bought","the/ buyer"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3104}/[H2986]', 'inflected', 'heb', 'יוֹבֵל', '["yôwbêl"]', '["in the/ jubilee"]', '["n-m"]', 'the blast of a horn (from its continuous sound); specifically, the signal of the silver trumpets; hence, the instrument itself and the festival thus introduced jubile, ram''s horn, trumpet.', 'or יֹבֵל; apparently from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4186}/[H3427]', 'lemma', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["<the> resident of","[the] habitable places of","[the] location of","[the] seat of","dwelling","dwelling of"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7069}/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["to the/ [one who] bought","to/ acquire","to/ buy","to/ buy [it]"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1755}/H9023/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["to/ generations/ his"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2691B}/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["the/ villages"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3104}/[H2986]', 'inflected', 'heb', 'יוֹבֵל', '["yôwbêl"]', '["and/ in the/ jubilee"]', '["n-m"]', 'the blast of a horn (from its continuous sound); specifically, the signal of the silver trumpets; hence, the instrument itself and the festival thus introduced jubile, ram''s horn, trumpet.', 'or יֹבֵל; apparently from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5892B}/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["and/ [the] cities of","and/ [the] city of","and/ a city","and/ a city of","and/ cities","and/ cities of","and/ city"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5769I}/[H5956]', 'lemma', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["perpetuity"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3881}/[H3878]', 'inflected', 'heb', 'לֵוִיִּי', '["Lêvîyîy"]', '["[is] to the/ Levites","[will belong] to the/ Levites","for the/ Levites","of the/ Levites","to <the>/ Levites","to the/ Levite","to the/ Levites","to/ Levi"]', '["a"]', 'a Levite or descendant of Levi Leviite.', 'or לֵוִי; patronymically from 3878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7704G>', 'inflected', 'heb', 'ושדות', '["u./se.Deh","u./se.Dei","ve./sa.Deh","ve./sa.Dot"]', '["and/ [the] field of","and/ a field","and/ field","and/ fields","and/ fields of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4054}/[H1644]', 'lemma', 'heb', 'מִגְרָשׁ', '["migrâsh"]', '["[the] pasture land of","[the] pasture lands of","open land","pasturelands"]', '["n-m"]', 'a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb.', 'also (in plural) feminine (Ezekiel 27:28) מִגְרָשָׁה; from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9038}\', 'inflected', 'arc', 'להון פ', '["la./Hem","le./Hon"]', '["<obj.>/ them","[belonged] to/ them","[belongs] to <the>/ them","by/ them","for <the>/ them","to <the>/ them","to/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4131}/[H4131]', 'inflected', 'heb', 'מוֹט', '["môwṭ"]', '["and/ it will slip"]', '["v"]', 'to waver; by implication, to slip, shake, fall be carried, cast, be out of course, be fallen in decay, × exceedingly, fall(-ing down), be (re-) moved, be ready, shake, slide, slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8636}/[H7235]', 'inflected', 'heb', 'תַּרְבִּית', '["tarbîyth"]', '["and/ interest","and/ profit","and/ usury"]', '["n-f"]', 'multiplication, i.e. percentage or bonus in addition to principal increase, unjust gain.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5392}/[H5391]', 'inflected', 'heb', 'נֶשֶׁךְ', '["neshek"]', '["by/ interest","for <the>/ interest","for/ interest"]', '["n-m"]', 'interest on a debt usury.', 'from 5391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4768}/[H7235]', 'inflected', 'heb', 'מַרְבִּית', '["marbîyth"]', '["and/ for/ profit"]', '["n-f"]', 'a multitude; also offspring; specifically interest (on capital) greatest part, greatness, increase, multitude.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0400}/H9021/[H398]', 'inflected', 'heb', 'אֹכֶל', '["ʼôkel"]', '["food/ your"]', '["n-m"]', 'food eating, food, meal(-time), meat, prey, victuals.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0430G}\/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["<into>/ God","to/ God"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5656G}/[H5647]', 'lemma', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["[is] [the] service of","[the] labor of","servitude"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7916}/[H7936]', 'inflected', 'heb', 'שָׂכִיר', '["sâkîyr"]', '["like/ a hired laborer","like/ a hired laborer of"]', '["a"]', 'a man at wages by the day or year hired (man, servant), hireling.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8453A}/[H3427]', 'inflected', 'heb', 'תּוֹשָׁב', '["tôwshâb"]', '["like/ a resident alien"]', '["n-m"]', 'a dweller but not outlandish [5237]; especially (as distinguished from a native citizen [active participle of 3427] and a temporary inmate [1616] or mere lodger [3885]) resident alien foreigner, inhabitant, sojourner, stranger.', 'or תֹּשָׁב; (1 Kings 17:1), from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5973B}/H9032/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["from/ with <the>/ you"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4466}/[H4465]', 'lemma', 'heb', 'מִמְכֶּרֶת', '["mimkereth"]', '["a sale of"]', '["n-f"]', 'a sale sold as.', 'feminine of 4465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7287A}/[H7287]', 'lemma', 'heb', 'רָדָה', '["râdâh"]', '["[was] ruling","[which] ruled","he subdues","rule","to rule","you have ruled","you will rule"]', '["v"]', 'to tread down, i.e. subjugate; specifically, to crumble off (come to, make to) have dominion, prevail against, reign, (bear, make to) rule,(-r, over), take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439G}/H9036/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["[are] around/ you","around/ you"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0519}/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["and/ a female slave"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8453A}/[H3427]', 'inflected', 'heb', 'תּוֹשָׁב', '["tôwshâb"]', '["the/ resident aliens"]', '["n-m"]', 'a dweller but not outlandish [5237]; especially (as distinguished from a native citizen [active participle of 3427] and a temporary inmate [1616] or mere lodger [3885]) resident alien foreigner, inhabitant, sojourner, stranger.', 'or תֹּשָׁב; (1 Kings 17:1), from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4940}/H9028/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["and/ from/ clan/ their"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121A}/H9026/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["<to>/ sons/ your","for/ sons/ your","to/ sons/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3423G}/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["to/ possess","to/ take possession of"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0251G}/H9026/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ over/ brothers/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0251I}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["against/ brother/ his","against/ countryman/ his","on/ brother/ his","on/ brother/ its","over/ brother/ his","with/ brother/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6531>\', 'inflected', 'heb', 'בפרך ס', '["be./Fa.rekh"]', '["with/ harshness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027I}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["[the] hand of","[the] hands of","[the] monument of","a hand","a monument"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4134}/[H4134]', 'inflected', 'heb', 'מוּךְ', '["mûwk"]', '["and/ he will become impoverished"]', '["v"]', 'to become thin, i.e. (figuratively) be impoverished be (waxen) poor(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1616}/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["to the/ sojourner","to/ a sojourner"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6133}/[H6131]', 'inflected', 'heb', 'עֵקֶר', '["ʻêqer"]', '["to/ a member of"]', '["n-m"]', 'figuratively, a transplanted person, i.e. naturalized citizen stock.', 'from 6131;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/H9033/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["he will redeem/ him","let them reclaim/ it"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7607}/[H7604]', 'inflected', 'heb', 'שְׁאֵר', '["shᵉʼêr"]', '["any of/ [the] relative[s] of"]', '["n-m"]', 'flesh (as swelling out), as living or for food; generally food of any kind; figuratively, kindred by blood body, flesh, food, (near) kin(-sman, -swoman), near (nigh) (of kin).', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4940}/H9023/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["from/ clan/ his","from/ own clan/ his"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7069}/H9033/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["[the] [one who] bought/ him","he bought/ it","owner/ its"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8141}/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["from/ [the] year","from/ [the] year of","from/ year"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4376}/H9043/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["he sold/ himself"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6310K}/H9029/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["to/ mouth/ their"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3701H}/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["some of/ [the] silver of"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7287A}/H9033/[H7287]', 'inflected', 'heb', 'רָדָה', '["râdâh"]', '["he will rule over/ him"]', '["v"]', 'to tread down, i.e. subjugate; specifically, to crumble off (come to, make to) have dominion, prevail against, reign, (bear, make to) rule,(-r, over), take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869H}/H9021/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0428}/[H411]', 'inflected', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["<in>/ these","by/ these [things]","in/ these","in/ these [things]","in/ these [ways]","in/ these things","with/ these"]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0457}/[H408]', 'lemma', 'heb', 'אֱלִיל', '["ʼĕlîyl"]', '["[are] worthless idols","[the] idols of","idols","worthless idols","worthlessness"]', '["a-m"]', 'good for nothing, by analogy vain or vanity; specifically an idol idol, no value, thing of nought.', 'apparently from 408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6459}/[H6458]', 'inflected', 'heb', 'פֶּסֶל', '["peçel"]', '["and/ a carved image","and/ an idol"]', '["n-m"]', 'an idol carved (graven) image.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4676}/[H5324]', 'inflected', 'heb', 'מַצֵּבָה', '["matstsêbâh"]', '["and/ [the] pillars of","and/ a pillar","and/ a sacred pillar","and/ sacred pillars"]', '["n-f"]', 'something stationed, i.e. a column or (memorial stone); by analogy, an idol garrison, (standing) image, pillar.', 'feminine (causatively) participle of 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4906}/[H7906]', 'lemma', 'heb', 'מַשְׂכִּית', '["maskîyth"]', '["[the] imaginations of","a carved image"]', '["n-f"]', 'a figure (carved on stone, the wall, or any object); figuratively, imagination conceit, image(-ry), picture, × wish.', 'from the same as 7906;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2708}/H9020/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["<in>/ statutes/ my","in/ statutes/ my"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1653}/H9026/[H1652]', 'inflected', 'heb', 'גֶּשֶׁם', '["geshem"]', '["rains/ your"]', '["n-m"]', 'a shower rain, shower.', 'from 1652;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6256}/H9028/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["at/ appropriate time/ their","at/ time/ their"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2981}/H9024/[H2986]', 'inflected', 'heb', 'יְבוּל', '["yᵉbûwl"]', '["produce/ its"]', '["n-m"]', 'produce, i.e. a crop or (figuratively) wealth fruit, increase.', 'from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1786}/[H1758]', 'lemma', 'heb', 'דַּיִשׁ', '["dayish"]', '["threshing"]', '["n-m"]', 'threshing-time threshing.', 'from 1758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1210}/[H1219]', 'lemma', 'heb', 'בָּצִיר', '["bâtsîyr"]', '["[the] grape harvest","grape harvest"]', '["n-m"]', 'clipped, i.e. the grape crop vintage.', 'from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1210}/[H1219]', 'inflected', 'heb', 'בָּצִיר', '["bâtsîyr"]', '["and/ grape harvest"]', '["n-m"]', 'clipped, i.e. the grape crop vintage.', 'from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899H}/H9026/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["bread/ your"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2729}/[H2729]', 'lemma', 'heb', 'חָרַד', '["chârad"]', '["[will be one who] disturbs","[will be one who] disturbs [them]","[will be one who] terrifies","he routed","it has trembled","it trembles","they tremble","they trembled","they will tremble","tremble","you have taken care"]', '["v"]', 'to shudder with terror; hence, to fear; also to hasten (with anxiety) be (make) afraid, be careful, discomfit, fray (away), quake, tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2719}/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["and/ [the] sword of","and/ [was] a sword","and/ a sword","and/ a sword of","and/ sword"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0341}/H9026/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["enemies/ your"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2719}/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["[are] for the/ sword","to the/ sword"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3465H}/[H3462]', 'inflected', 'heb', 'יָשָׁן', '["yâshân"]', '["and/ old harvest"]', '["a"]', 'old old.', 'from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1602}/[H1602]', 'lemma', 'heb', 'גָּעַל', '["gâʻal"]', '["[who] loathed","does it abhor","it abhorred","it fails","it was defiled","it will abhor","they loathed"]', '["v"]', 'to detest; by implication, to reject abhor, fail, lothe, vilely cast away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4133}/[H4132]', 'lemma', 'heb', 'מוֹטָה', '["môwṭâh"]', '["[the] bars of","[the] yoke-bar","[the] yoke-bars of","yoke-bar","yoke-bars of"]', '["n-f"]', 'a pole; by implication, an ox-bow; hence, a yoke (either literal or figurative) bands, heavy, staves, yoke.', 'feminine of 4132;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5923}/H9026/[H5953]', 'inflected', 'heb', 'עֹל', '["ʻôl"]', '["yoke/ your"]', '["n-m"]', 'a yoke (as imposed on the neck), literally or figuratively yoke.', 'or עוֹל; from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6968}\/[H6965]', 'inflected', 'heb', 'קוֹמְמִיּוּת', '["qôwmᵉmîyûwth"]', '["upright"]', '["n-f"]', 'elevation, i.e. (adverbially) erectly (figuratively) upright.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4687}/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["[are] the/ commandments","[is] the/ commandment","the/ command","the/ commandment","the/ commandments","the/ order"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3988A}/[H3988]', 'lemma', 'heb', 'מָאַס', '["mâʼaç"]', '["I reject","I rejected","I will reject","[is] rejecting","[one who] rejects","[which] they rejected","a rejected [person]","certainly <to reject>","have you rejected","he has rejected","he rejects","it has rejected","rejected","rejecting","she is rejected","someone has rejected","they had rejected","they have rejected","they reject","they rejected","to reject","you have rejected","you reject","you rejected","you will reject"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6565A}/H9036/[H6565]', 'inflected', 'heb', 'פָּרַר', '["pârar"]', '["to/ break/ you"]', '["v"]', 'to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0928}/[H926]', 'lemma', 'heb', 'בֶּהָלָה', '["behâlâh"]', '["sudden terror"]', '["n-f"]', 'panic, destruction terror, trouble.', 'from 926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7829}/[H7828]', 'inflected', 'heb', 'שַׁחֶפֶת', '["shachepheth"]', '["<the>/ consumption"]', '["n-f"]', 'emaciation consumption.', 'from the same as 7828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6920}/[H6919]', 'inflected', 'heb', 'קַדַּחַת', '["qaddachath"]', '["<the>/ fever"]', '["n-f"]', 'inflammation, i.e. febrile disease burning ague, fever.', 'from 6919;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615H}/[H3615]', 'lemma', 'heb', 'כָּלָה', '["kâlâh"]', '["I made an end of","[is] bringing to an end","[which] cause to fail","[will be] bringing to an end","destroy","it wastes away","it will bring to an end","make an end","may they come to an end","they come to an end","they will come to an end","you have come to an end"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1727}/[H1727]', 'inflected', 'heb', 'דּוּב', '["dûwb"]', '["and/ [which] make pine away"]', '["v"]', 'to mope, i.e. (figuratively) pine sorrow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7385}/[H7324]', 'inflected', 'heb', 'רִיק', '["rîyq"]', '["[is] to/ emptiness","to <the>/ emptiness","to/ emptiness"]', '["n-m"]', 'emptiness; figuratively, a worthless thing; adverbially, in vain empty, to no purpose, (in) vain (thing), vanity.', 'from 7324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2233G}/H9026/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["seed/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7287A}/[H7287]', 'inflected', 'heb', 'רָדָה', '["râdâh"]', '["and/ they ruled","and/ they will rule"]', '["v"]', 'to tread down, i.e. subjugate; specifically, to crumble off (come to, make to) have dominion, prevail against, reign, (bear, make to) rule,(-r, over), take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8130}/H9036/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["[those who] hate/ you","[who] hate/ you"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0853}/H9036\/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["<obj.>/ you"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3256}/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["to/ discipline"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1347}/[H1342]', 'lemma', 'heb', 'גָּאוֹן', '["gâʼôwn"]', '["[the] pride of","[the] thicket[s] of","majesty","pride"]', '["n-m"]', 'the same as 1346 arrogancy, excellency(-lent), majesty, pomp, pride, proud, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5797}/H9026/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["strength/ your"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8064>/H9026', 'opaque', 'heb', 'שָׁמַיִם', '["shâmayim"]', '["heavens/ your"]', '["n-m"]', 'the sky (as aloft; the dual perhaps alluding to the visible arch in which the clouds move, as well as to the higher ether where the celestial bodies revolve) air, × astrologer, heaven(-s).', 'dual of an unused singular שָׁמֶה; from an unused root meaning to be lofty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1270}/[H1269]', 'inflected', 'heb', 'בַּרְזֶל', '["barzel"]', '["like <the>/ iron"]', '["n-m"]', 'iron (as cutting); by extension, an iron implement (ax) head, iron.', 'perhaps from the root of 1269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776H>/H9026', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["land/ your"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5154}/[H5153]', 'inflected', 'heb', 'נְחוּשָׁה', '["nᵉchûwshâh"]', '["like <the>/ bronze"]', '["n-f"]', 'copper brass, steel. Compare 5176.', 'or נְחֻשָׁה; feminine of 5153;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3581B>/H9026', 'opaque', 'heb', 'כֹּחַ', '["kôach"]', '["strength/ your"]', '["n-m"]', 'vigor, literally (force, in a good or a bad sense) or figuratively (capacity, means, produce); also (from its hardiness) a large lizard ability, able, chameleon, force, fruits, might, power(-ful), strength, substance, wealth.', 'or (Daniel 11:6) כּוֹחַ; from an unused root meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7147}/[H7136]', 'lemma', 'heb', 'קְרִי', '["qᵉrîy"]', '["contrariness"]', '["n-m"]', 'hostile encounter contrary.', 'from 7136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8085G}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["for/ hearing","to/ hear","to/ listen","to/ listen to","to/ make heard"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4347}/[H5221]', 'lemma', 'heb', 'מַכָּה', '["makkâh"]', '["[the] blow of","[the] plagues of","a blow","a defeat","a plague","a slaughter","a striking","a striking down of","a wound","defeat","plague","plagues","striking","wounds"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2403B}/H9026/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["according to/ sins/ your"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7921A}/[H7921]', 'inflected', 'heb', 'שָׁכֹל', '["shâkôl"]', '["and/ it will make childless"]', '["v"]', 'properly, to miscarry, i.e. suffer abortion; by analogy, to bereave (literally or figuratively) bereave (of children), barren, cast calf (fruit, young), be (make) childless, deprive, destroy, × expect, lose children, miscarry, rob of children, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0929>/H9026', 'opaque', 'heb', 'בְּהֵמָה', '["bᵉhêmâh"]', '["livestock/ your"]', '["n-f"]', 'properly, a dumb beast; especially any large quadruped or animal (often collective) beast, cattle.', 'from an unused root (probably meaning to be mute);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4591}/[H4591]', 'inflected', 'heb', 'מָעַט', '["mâʻaṭ"]', '["and/ it will diminish","and/ they became few"]', '["v"]', 'properly, to pare off, i.e. lessen; intransitively, to be (or causatively, to make) small or few (or figuratively, ineffective) suffer to decrease, diminish, (be, × borrow a, give, make) few (in number, -ness), gather least (little), be (seem) little, (× give the) less, be minished, bring to nothing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8074G}/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["and/ I will devastate","and/ they will be desolate","and/ they will be made desolate","and/ we have devastated"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870K}/H9026/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["roads/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3256}/[H3256]', 'lemma', 'heb', 'יָסַר', '["yâçar"]', '["I instructed [them]","I will discipline","[one who] admonishes","an instructor","certainly <to discipline>","discipline","he disciplined","he disciplines","he will let himself be instructed","let yourself be instructed","let yourselves be instructed","you have disciplined","you have instructed","you will let yourself be disciplined"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7147}/[H7136]', 'inflected', 'heb', 'קְרִי', '["qᵉrîy"]', '["in/ contrariness"]', '["n-m"]', 'hostile encounter contrary.', 'from 7136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5359}/[H5358]', 'lemma', 'heb', 'נָקָם', '["nâqâm"]', '["vengeance","vengeance of"]', '["n-m"]', 'revenge avenged, quarrel, vengeance.', 'from 5358;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5892B}/H9026/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["cities/ your"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7665}/H9040/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["when/ break/ I"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4294K}/[H5186]', 'lemma', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["[the] staff of","staff of"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725K}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ he has repaid","and/ he repaid","and/ he returned","and/ he will repay","and/ they will bring back","and/ will he repay?"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7646}\/[H7646]', 'inflected', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["you will be satisfied"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2534}/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["in/ [the] rage of","in/ [the] wrath of","in/ a rage","in/ anger","in/ anger of","in/ rage","with/ rage"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3256}/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["and/ I was disciplined","and/ I will discipline","and/ they will be warned","and/ they will discipline","and/ they will punish"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1116>/H9026', 'opaque', 'heb', 'בָּמָה', '["bâmâh"]', '["high places/ your"]', '["n-f"]', 'an elevation height, high place, wave.', 'from an unused root (meaning to be high);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2553}/H9026/[H2535]', 'inflected', 'heb', 'חַמָּן', '["chammân"]', '["incense altars/ your"]', '["n-m"]', 'a sun-pillar idol, image.', 'from 2535;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6297}/H9026/[H6296]', 'inflected', 'heb', 'פֶּגֶר', '["peger"]', '["corpses/ your"]', '["n-m"]', 'a carcase (as limp), whether of man or beast; figuratively, an idolatrous image carcase, corpse, dead body.', 'from 6296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6297}/[H6296]', 'lemma', 'heb', 'פֶּגֶר', '["peger"]', '["[the] corpse[s] of","[the] corpses of","[were] corpses"]', '["n-m"]', 'a carcase (as limp), whether of man or beast; figuratively, an idolatrous image carcase, corpse, dead body.', 'from 6296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1544}/H9026/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["idols/ your"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1602}/[H1602]', 'inflected', 'heb', 'גָּעַל', '["gâʻal"]', '["and/ it will abhor"]', '["v"]', 'to detest; by implication, to reject abhor, fail, lothe, vilely cast away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2723}/[H2721]', 'lemma', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["O waste places of","[are] a ruin","[the] ruins","[the] ruins of","[the] waste places","a desolation","a ruin","a waste place","ruins","waste places"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4720}/H9026/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["sanctuaries/ your"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7306}/[H7306]', 'lemma', 'heb', 'רוּחַ', '["rûwach"]', '["I delight","I will smell","it smells","may he smell"]', '["v"]', 'properly, to blow, i.e. breathe; only (literally) to smell or (by implication, perceive (figuratively, to anticipate, enjoy) accept, smell, × touch, make of quick understanding.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7381}/[H7306]', 'inflected', 'heb', 'רֵיחַ', '["rêyach"]', '["<in>/ [the] odor of","<in>/ an odor of"]', '["n-m"]', 'odor (as if blown) savour, scent, smell.', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5207}/H9026/[H5117]', 'inflected', 'heb', 'נִיחוֹחַ', '["nîychôwach"]', '["soothing/ your"]', '["n-m"]', 'properly, restful, i.e. pleasant; abstractly, delight sweet (odour).', 'or נִיחֹחַ; from 5117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8074H}/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["and/ I was appalled","and/ I will make appalled","and/ he was appalled","and/ they will be appalled"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0853}/H9036/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ <obj.>/ you"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2219}/[H2114]', 'lemma', 'heb', 'זָרָה', '["zârâh"]', '["I will disperse","I will scatter","[is] spread out","[is] winnowing","[someone has been] winnowing","[the] [one who] scattered of","[will be] winnowing","it is scattered","scatter","they scatter","they scattered","you sift","you will disperse"]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1471A}/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["[are] among the/ nations","against the/ nations","among the/ nations","by/ a nation","by/ nation","on the/ nations","on/ a nation","over the/ nations","over/ nations","with the/ nations"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5892B}/H9026/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["and/ cities/ your"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7676}/H9024/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["sabbaths/ its"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8074G}/H9044/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["being made desolate/ it"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7676}/H9026/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["in/ sabbaths/ your"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3427}/H9046/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["when/ dwelt/ you"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4816}/[H7401]', 'lemma', 'heb', 'מֹרֶךְ', '["môrek"]', '["despair"]', '["n-m"]', 'softness, i.e. (figuratively) fear faintness.', 'perhaps from 7401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3824}/H9028/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["[are] in/ heart/ their","[is] in/ heart/ their","in/ heart/ their"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0341}/H9028/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["enemies/ their"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5086}/[H5086]', 'lemma', 'heb', 'נָדַף', '["nâdaph"]', '["driven about","it will be driven about","may you drive [them] about"]', '["v"]', 'to shove asunder, i.e. disperse drive (away, to and fro), thrust down, shaken, tossed to and fro.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4499}/[H4498]', 'lemma', 'heb', 'מְנוּסָה', '["mᵉnûwçâh"]', '["a flight of"]', '["n-f"]', 'retreat fleeing, flight.', 'or מְנֻסָה; feminine of 4498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3782}/[H3782]', 'inflected', 'heb', 'כָּשַׁל', '["kâshal"]', '["and/ he will stumble","and/ it will stumble","and/ they will stumble","and/ you will stumble"]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9006/{H6440G}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["as/ from/ before"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7291}/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["and/ I will pursue","and/ [is one who] pursues","and/ [is] pursuing","and/ [one who] pursues","and/ pursue","and/ pursuing"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8617}/[H6965]', 'lemma', 'heb', 'תְּקוּמָה', '["tᵉqûwmâh"]', '["power to stand"]', '["n-f"]', 'resistfulness power to stand.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4743}/[H4743]', 'lemma', 'heb', 'מָקַק', '["mâqaq"]', '["[are] wasting away","he will cause to rot","it will rot","they fester","they will rot","they will rot away"]', '["v"]', 'to melt; figuratively, to flow, dwindle, vanish consume away, be corrupt, dissolve, pine away.', ''' a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771G}/H9028/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["by/ iniquity/ their","for/ iniquity/ their","in/ iniquity/ their"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0637}/[H637]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["and/ also","and/ even","and/ indeed?"]', '["prt"]', 'meaning accession (used as an adverb or conjunction); also or yea; adversatively though also, + although, and (furthermore, yet), but, even, + how much less (more, rather than), moreover, with, yea.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771G}/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["for/ [the] iniquity","for/ [the] iniquity of","in/ [the] iniquities of","in/ [the] iniquity of","in/ iniquity","with <the>/ iniquity"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4604}/H9028/[H4603]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["by/ unfaithfulness/ their","in/ unfaithfulness/ their"]', '["n-m"]', 'treachery, i.e. sin falsehood, grievously, sore, transgression, trespass, × very.', 'from 4603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3665}/[H3665]', 'lemma', 'heb', 'כָּנַע', '["kânaʻ"]', '["I will subdue","he had humbled","he has humbled himself","he humbled himself","it will humble itself","they had humbled themselves","they have humbled themselves","they humbled themselves","you will subdue"]', '["v"]', 'properly, to bend the knee; hence, to humiliate, vanquish bring down (low), into subjection, under, humble (self), subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3824}/H9028/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["[those who] heart/ their","heart/ their"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6189}/[H6188]', 'inflected', 'heb', 'עָרֵל', '["ʻârêl"]', '["<the>/ uncircumcised","the/ uncircumcised","the/ uncircumcised [men]","the/ uncircumcised [men]?"]', '["a"]', 'properly, exposed, i.e. projecting loose (as to the prepuce); used only technically, uncircumcised (i.e. still having the prepuce uncurtailed) uncircumcised (person).', 'from 6188;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7521}/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["and/ it may accept","and/ was acceptable","so/ I may take pleasure"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8074G}/H9044/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["when/ is made desolate/ it"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H3282>', 'inflected', 'heb', 'וביען', '["u./ve./Ya.''an"]', '["and/ by/ cause"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4941G}/H9020/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["<in>/ judgments/ my","by/ judgments/ my"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315I}/H9028/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["life/ their","self/ their","soul/ their","throat/ their"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3988A}/H9038/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["I will reject/ them","he has rejected/ them","he will reject/ them"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1602}/H9038/[H1602]', 'inflected', 'heb', 'גָּעַל', '["gâʻal"]', '["I will abhor/ them"]', '["v"]', 'to detest; by implication, to reject abhor, fail, lothe, vilely cast away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3615H}/H9038/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["to/ make an end of/ them"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6565A}/[H6565]', 'inflected', 'heb', 'פָּרַר', '["pârar"]', '["by/ breaking","to/ break","to/ frustrate"]', '["v"]', 'to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7223H}/[H7221]', 'lemma', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["[the] forefathers","ancestors","first","former","former [things]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4941G}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ the/ judgments"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6187}/H9021/[H6186]', 'inflected', 'heb', 'עֵרֶךְ', '["ʻêrek"]', '["valuation of/ your","valuation/ your"]', '["n-m"]', 'a pile, equipment, estimate equal, estimation, (things that are set in) order, price, proportion, × set at, suit, taxation, × valuest.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6187}/H9021/[H6186]', 'inflected', 'heb', 'עֵרֶךְ', '["ʻêrek"]', '["for/ valuation/ your","from/ valuation/ your"]', '["n-m"]', 'a pile, equipment, estimate equal, estimation, (things that are set in) order, price, proportion, × set at, suit, taxation, × valuest.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6186B}/[H6186]', 'inflected', 'heb', 'עָרַךְ', '["ʻârak"]', '["and/ he will evaluate"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027T}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["[the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5087}/[H5087]', 'inflected', 'heb', 'נָדַר', '["nâdar"]', '["the/ [one who] vows"]', '["v"]', 'to promise (pos., to do or give something to God) (make a) vow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6186B}/H9033/[H6186]', 'inflected', 'heb', 'עָרַךְ', '["ʻârak"]', '["he will evaluate/ him"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2498}/H9033/[H2498]', 'inflected', 'heb', 'חָלַף', '["châlaph"]', '["he will substitute/ it","it will cut through/ him"]', '["v"]', 'properly, to slide by, i.e. (by implication) to hasten away, pass on, spring up, pierce or change abolish, alter, change, cut off, go on forward, grow up, be over, pass (away, on, through), renew, sprout, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4171}/[H4171]', 'lemma', 'heb', 'מוּר', '["mûwr"]', '["I will exchange","anyone will exchange","ever <to exchange>","he changes","he exchanges","he will exchange","it has exchanged"]', '["v"]', 'to alter; by implication, to barter, to dispose of × at all, (ex-) change, remove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7451A}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["for/ bad"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8545}/H9023/[H4171]', 'inflected', 'heb', 'תְּמוּרָה', '["tᵉmûwrâh"]', '["and/ substitute/ its"]', '["n-f"]', 'barter, compensation (ex-) change(-ing), recompense, restitution.', 'from 4171;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6187}/H9021/[H6186]', 'inflected', 'heb', 'עֵרֶךְ', '["ʻêrek"]', '["according to/ valuation of/ your","according to/ valuation/ your"]', '["n-m"]', 'a pile, equipment, estimate equal, estimation, (things that are set in) order, price, proportion, × set at, suit, taxation, × valuest.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/H9034/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["he will redeem/ it","redeem/ it"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6186B}/H9033/[H6186]', 'inflected', 'heb', 'עָרַךְ', '["ʻârak"]', '["and/ he will evaluate/ it"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6186B}/[H6186]', 'lemma', 'heb', 'עָרַךְ', '["ʻârak"]', '["he taxed","he will evaluate"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6942H}/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["<the>/ [one who] consecrated","that/ he had consecrated","the/ [one who] set apart as holy","the/ [one who] sets apart as holy","which/ were consecrated"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H7704G>', 'inflected', 'heb', 'משדה', '["mi./se.Deh","mi./se.Dei"]', '["[is] from/ [the] field of","from/ [the] region of","from/ [the] region<s> of","some of/ [the] field of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2563C}/[H2560]', 'lemma', 'heb', 'חֹמֶר', '["chômer"]', '["[are] a homer","a homer","a homer of","homers","mud"]', '["n-m"]', 'properly, a bubbling up, i.e. of water, a wave; of earth, mire or clay (cement); also a heap; hence, a chomer or dry measure clay, heap, homer, mire, motion.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8184}/[H8175]', 'lemma', 'heb', 'שְׂעֹרָה', '["sᵉʻôrâh"]', '["barley","barley<s>"]', '["n-f"]', 'barley (as villose) barley.', 'or שְׂעוֹרָה (feminine meaning the plant); and (masculine meaning the grain); also שְׂעֹר; or שְׂעוֹר; from 8175 in the sense of roughness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3701H}/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["the/ money"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1639}/[H1639]', 'inflected', 'heb', 'גָּרַע', '["gâraʻ"]', '["and/ I diminished","and/ it will be deducted","and/ it will be withdrawn"]', '["v"]', 'to scrape off; by implication, to shave, remove, lessen, withhold abate, clip, (di-) minish, do (take) away, keep back, restrain, make small, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3318H}/H9043/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ brought out/ he","when/ goes out/ it"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H7704G>', 'inflected', 'heb', 'כשדה', '["ki/s.Deh"]', '["like/ [the] field of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2764A}/[H2763]', 'inflected', 'heb', 'חֵרֶם', '["chêrem"]', '["<the>/ total destruction","the/ devoted thing[s]","the/ object[s] for destruction"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4373}/[H4371]', 'lemma', 'heb', 'מִכְסָה', '["mikçâh"]', '["[the] amount of"]', '["n-f"]', 'an enumeration; by implication, a valuation number, worth.', 'feminine of 4371;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6187}/H9021/[H6186]', 'inflected', 'heb', 'עֵרֶךְ', '["ʻêrek"]', '["<the>/ valuation/ your"]', '["n-m"]', 'a pile, equipment, estimate equal, estimation, (things that are set in) order, price, proportion, × set at, suit, taxation, × valuest.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8255}\/[H8254]', 'inflected', 'heb', 'שֶׁקֶל', '["sheqel"]', '["the/ shekel"]', '["n-m"]', 'probably a weight; used as a commercial standard shekel.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1069}/[H1061]', 'lemma', 'heb', 'בָּכַר', '["bâkar"]', '["it will be born a firstling","it will bear early fruit"]', '["v"]', 'to give the birthright make firstborn, be firstling, bring forth first child (new fruit).', 'a primitive root; properly, to burst the womb, i.e. (causatively) bear or make early fruit (of woman or tree); also (as denominative from 1061)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6299}/[H6299]', 'inflected', 'heb', 'פָּדָה', '["pâdâh"]', '["and/ he will redeem [it]","and/ they redeemed"]', '["v"]', 'to sever, i.e. ransom; generally to release, preserve × at all, deliver, × by any means, ransom, (that are to be, let be) redeem(-ed), rescue, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2764A}/[H2763]', 'lemma', 'heb', 'חֵרֶם', '["chêrem"]', '["[is] an object for destruction","a devoted thing","an object for destruction","dedicated person","devoted thing","devoted thing[s]","total destruction"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0929>', 'inflected', 'heb', 'ובהמה', '["u./ve.he.Mah"]', '["and/ an animal","and/ animal","and/ animal[s]","and/ livestock"]', NULL, NULL, NULL);
