INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0299}/[H251]', 'lemma', 'heb', 'אֲחִירַע', '["ʼĂchîyraʻ"]', '["Ahira","[was] Ahira"]', '["n-pr-m"]', 'Achira, an Israelite Ahira.', 'from 251 and 7451; brother of wrong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5881}/[H5869]', 'lemma', 'heb', 'עֵינָן', '["ʻÊynân"]', '["Enan"]', '["n-pr-m"]', 'Enan, an Israelite Enan. Compare 2704.', 'from 5869; having eyes;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4294H}/[H5186]', 'lemma', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["[the] tribe of","[the] tribes of","[will be] [the] tribe of","rods","tribe","tribes"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0505H}/[H504]', 'lemma', 'heb', 'אֶלֶף', '["ʼeleph"]', '["[the] families of","[the] thousands of"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5344A}/[H5344]', 'lemma', 'heb', 'נָקַב', '["nâqab"]', '["[the] distinguished [people] of","they had been designated","will anyone pierce?","will you pierce?","you pierced"]', '["v"]', 'to puncture, literally (to perforate, with more or less violence) or figuratively (to specify, designate, libel) appoint, blaspheme, bore, curse, express, with holes, name, pierce, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4940}/H9028/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["clan/ their","clans/ their"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6485A}/H9038/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ he enrolled/ them","and/ he mustered/ them"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5514H>\', 'opaque', 'heb', 'סִינַי', '["Çîynay"]', '["Sinai"]', '["n-pr-loc"]', 'Sinai, mountain of Arabia Sinai.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8435}/H9028/[H3205]', 'inflected', 'heb', 'תּוֹלְדָה', '["tôwlᵉdâh"]', '["[were] generations/ their","genealogies/ their"]', '["n-f"]', '(plural only) descent, i.e. family; (figuratively) history birth, generations.', 'or תֹּלְדָה; from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485A}/H9028/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["enrolled [men]/ their"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3967}\/[H3967]', 'inflected', 'heb', 'מֵאָה', '["mêʼâh"]', '["hundred<s>","one hundred","two hundred"]', '["n-f"]', 'a hundred; also as a multiplicative and a fraction hundred((-fold), -th), sixscore.', 'or מֵאיָה; properly, a primitive numeral');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485A}/H9023/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["enrolled [men]/ his","enrolled [men]/ its"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2572}\/[H2568]', 'inflected', 'heb', 'חֲמִשִּׁים', '["chămishshîym"]', '["and/ fifty"]', '["n"]', 'fifty fifty.', 'multiple of 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3967}\/[H3967]', 'inflected', 'heb', 'מֵאָה', '["mêʼâh"]', '["and/ one hundred","and/ two hundred"]', '["n-f"]', 'a hundred; also as a multiplicative and a fraction hundred((-fold), -th), sixscore.', 'or מֵאיָה; properly, a primitive numeral');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3881}/[H3878]', 'inflected', 'heb', 'לֵוִיִּי', '["Lêvîyîy"]', '["and/ the/ Levite","and/ the/ Levites"]', '["a"]', 'a Levite or descendant of Levi Leviite.', 'or לֵוִי; patronymically from 3878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8432>/H9028\', 'inflected', 'heb', 'בתוכם פ', '["be./to.Kha/m","ve./to.Kha/m"]', '["in/ midst of/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218L>/H9028', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ their"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5439G}/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["and/ around"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5265}/[H5265]', 'inflected', 'heb', 'נָסַע', '["nâçaʻ"]', '["and/ when/ sets out"]', '["v"]', 'properly, to pull up, especially the tent-pins, i.e. start on a journey cause to blow, bring, get, (make to) go (away, forth, forward, onward, out), (take) journey, march, remove, set aside (forward), × still, be on his (go their) way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2583}/[H2603]', 'inflected', 'heb', 'חָנָה', '["chânâh"]', '["and/ when/ encamps"]', '["v"]', 'properly, to incline; by implication, to decline (of the slanting rays of evening); specifically, to pitch a tent; generally to encamp (for abode or siege) abide (in tents), camp, dwell, encamp, grow to an end, lie, pitch (tent), rest in tent.', 'a primitive root (compare 2603);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2114A}/[H2114]', 'inflected', 'heb', 'זוּר', '["zûwr"]', '["and/ the/ stranger"]', '["v"]', 'to turn aside (especially for lodging); hence to be a foreigner, strange, profane; specifically (active participle) to commit adultery (come from) another (man, place), fanner, go away, (e-) strange(-r, thing, woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7131}/[H7126]', 'inflected', 'heb', 'קָרֵב', '["qârêb"]', '["<the>/ [person] approaching","<the>/ approaching"]', '["a"]', 'near approach, come (near, nigh), draw near.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4264}/H9023/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["army/ his","camp/ his"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1714}/H9023/[H1713]', 'inflected', 'heb', 'דֶּגֶל', '["degel"]', '["standard/ his"]', '["n-m"]', 'a flag banner, standard.', 'from 1713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7110A}/[H7107]', 'lemma', 'heb', 'קֶצֶף', '["qetseph"]', '["[the] wrath of","anger","wrath"]', '["n-m"]', 'a splinter (as chipped off); figuratively, rage or strife foam, indignation, × sore, wrath.', 'from 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0226H}/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["with/ [the] signs"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2583}/[H2603]', 'inflected', 'heb', 'חָנָה', '["chânâh"]', '["and/ those/ [who] encamp"]', '["v"]', 'properly, to incline; by implication, to decline (of the slanting rays of evening); specifically, to pitch a tent; generally to encamp (for abode or siege) abide (in tents), camp, dwell, encamp, grow to an end, lie, pitch (tent), rest in tent.', 'a primitive root (compare 2603);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1714}/[H1713]', 'lemma', 'heb', 'דֶּגֶל', '["degel"]', '["[the] standard of","[will be] [the] standard of"]', '["n-m"]', 'a flag banner, standard.', 'from 1713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6635A}/H9023/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["and/ military group/ his"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6485A}/H9028/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ enrolled [men]/ their"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6485A}/H9023/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ enrolled [men]/ his"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5265}\/[H5265]', 'inflected', 'heb', 'נָסַע', '["nâçaʻ"]', '["they will set out"]', '["v"]', 'properly, to pull up, especially the tent-pins, i.e. start on a journey cause to blow, bring, get, (make to) go (away, forth, forward, onward, out), (take) journey, march, remove, set aside (forward), × still, be on his (go their) way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4294H}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["and/ [the] tribe of"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7467I}/[H7466]', 'lemma', 'heb', 'רְעוּאֵל', '["Rᵉʻûwʼêl"]', '["Reuel"]', '["n-pr-m"]', 'Reuel, the name of Moses'' father-in-law, also of an Edomite and an Israelite Raguel, Reuel.', 'from the same as 7466 and 410; friend of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8145}/[H8138]', 'inflected', 'heb', 'שֵׁנִי', '["shênîy"]', '["and/ second"]', '["n"]', 'properly, double, i.e. second; also adverbially, again again, either (of them), (an-) other, second (time).', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1714}/H9028\/[H1713]', 'inflected', 'heb', 'דֶּגֶל', '["degel"]', '["to/ standards/ their"]', '["n-m"]', 'a flag banner, standard.', 'from 1713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5921A}/H9033/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["and/ [was] on/ it","and/ [will be] on/ him","and/ on/ him","and/ on/ it","and/ over/ it","and/ with/ him"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0314}/[H309]', 'inflected', 'heb', 'אַחֲרוֹן', '["ʼachărôwn"]', '["of the/ subsequent [things]","to the/ last"]', '["a"]', 'hinder; generally, late or last; specifically (as facing the east) western after (-ward), to come, following, hind(-er, -ermost, -most), last, latter, rereward, ut(ter) most.', 'or (shortened) אַחֲרֹן; from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1714}/H9028/[H1713]', 'inflected', 'heb', 'דֶּגֶל', '["degel"]', '["to/ standards/ their"]', '["n-m"]', 'a flag banner, standard.', 'from 1713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4940}/H9023/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["to/ clans/ his","to/ clans/ its","to/ families/ its"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4886}/[H4886]', 'inflected', 'heb', 'מָשַׁח', '["mâshach"]', '["<the>/ anointed"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7126H}/H9048/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["when/ brought near/ they"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9028\/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["ancestors/ their","father/ their"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4931}/H9023/[H4929]', 'inflected', 'heb', 'מִשְׁמֶרֶת', '["mishmereth"]', '["charge/ his","command/ his","duty/ his"]', '["n-f"]', 'watch, i.e. the act (custody), or (concretely) the sentry, the post; objectively preservation, or (concretely) safe; figuratively observance, i.e. (abstractly) duty or (objectively) a usage or party charge, keep, or to be kept, office, ordinace, safeguard, ward, watch.', 'feminine of 4929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3550}/H9028/[H3547]', 'inflected', 'heb', 'כְּהֻנָּה', '["kᵉhunnâh"]', '["priesthood/ their"]', '["n-f"]', 'priesthood priesthood, priest''s office.', 'from 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5221}/H9040/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["struck/ I"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485A}/H9038/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["you will enroll/ them"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6485A}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ he enrolled","and/ he mustered","and/ it was mustered","and/ they mustered","and/ they were mustered","and/ you will visit"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2275B}/[H2267]', 'lemma', 'heb', 'חֶבְרוֹן', '["Chebrôwn"]', '["Hebron"]', '["n-pr-loc n-pr-m"]', 'Chebron, a place in Palestine, also the name of two Israelites Hebron.', 'from 2267; seat of association;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1648}/[H1644]', 'inflected', 'heb', 'גֵּרְשׁוֹן', '["Gêrᵉshôwn"]', '["[belonged] to/ Gershon","of/ Gershon","to/ Gershon"]', '["n-pr-m"]', 'Gereshon or Gereshom, an Israelite Gershon, Gershom.', 'or גֵּרְשׁוֹם; from 1644; a refugee;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3846}/[H3845]', 'inflected', 'heb', 'לִבְנִי', '["Libnîy"]', '["the/ Libnite[s]"]', '["a"]', 'a Libnite or descendants of Libni (collectively) Libnites.', 'patronymically from 3845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4940}/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["and/ [the] clan of","and/ [the] clans of","and/ clan"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8097}/[H8096]', 'inflected', 'heb', 'שִׁמְעִי', '["Shimʻîy"]', '["the/ Shimeite[s]"]', '["n-pr-m"]', 'a Shimite (collectively) or descendants of Shimi of Shimi, Shimites.', 'patronymically from 8096;');
