INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4931}/[H4929]', 'inflected', 'heb', 'מִשְׁמֶרֶת', '["mishmereth"]', '["and/ [the] duty of","and/ [the] service of"]', '["n-f"]', 'watch, i.e. the act (custody), or (concretely) the sentry, the post; objectively preservation, or (concretely) safe; figuratively observance, i.e. (abstractly) duty or (objectively) a usage or party charge, keep, or to be kept, office, ordinace, safeguard, ward, watch.', 'feminine of 4929;');
