INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7657}/[H7651]', 'inflected', 'heb', 'שִׁבְעִים', '["shibʻîym"]', '["and/ the/ seventy"]', '["n"]', 'seventy seventy, threescore and ten ( -teen).', 'multiple of 7651;');
