INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6306A}/[H6299]', 'inflected', 'heb', 'פִּדְיוֹם', '["pidyôwm"]', '["the/ ransom"]', '["n-m"]', 'a ransom ransom, that were redeemed, redemption.', 'or פִּדְיֹם; also פִּדְיוֹן; or פִּדְיֹן; from 6299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6302}/[H6299]', 'inflected', 'heb', 'פָּדוּי', '["pâdûwy"]', '["the/ ransom<s>"]', '["n-m"]', 'as abstractly (in plural masculine) a ransom (that are) to be (that were) redeemed.', 'passive participle of 6299. ransomed (and so occurring under 6299);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6635I}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["for the/ service"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5265}/[H5265]', 'inflected', 'heb', 'נָסַע', '["nâçaʻ"]', '["when/ set out","when/ sets out"]', '["v"]', 'properly, to pull up, especially the tent-pins, i.e. start on a journey cause to blow, bring, get, (make to) go (away, forth, forward, onward, out), (take) journey, march, remove, set aside (forward), × still, be on his (go their) way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3681}/[H3680]', 'lemma', 'heb', 'כָּסוּי', '["kâçûwy"]', '["a covering of"]', '["n-m"]', 'properly, covered, i.e. (as noun) a covering covering.', 'passive participle of 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7086}/[H7167]', 'inflected', 'heb', 'קְעָרָה', '["qᵉʻârâh"]', '["the/ dish","the/ dishes"]', '["n-f"]', 'a bowl (as cut out hollow) charger, dish.', 'probably from 7167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3709I}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["the/ pan","the/ pans"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4518}/[H5352]', 'inflected', 'heb', 'מְנַקִּית', '["mᵉnaqqîyth"]', '["the/ bowls"]', '["n-f"]', 'a sacrificial basin (for holding blood) bowl.', 'from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7184>', 'opaque', 'heb', 'קָשָׂה', '["qâsâh"]', '["[the] jugs of"]', '["n-f"]', 'a jug (from its shape) cover, cup.', 'or קַשְׂוָה; from an unused root meaning to be round;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5262}/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["the/ drink offering"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H8548>', 'inflected', 'heb', 'התמיד', '["Ha./ta.mid","ha./ta.Mid"]', '["<the>/ continuity","<the>/ regularity","the/ perpetual [offering]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4372}/[H3680]', 'inflected', 'heb', 'מִכְסֶה', '["mikçeh"]', '["with/ a covering of"]', '["n-m"]', 'a covering, i.e. weatherboarding covering.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4457}/H9024/[H3947]', 'inflected', 'heb', 'מֶלְקָח', '["melqâch"]', '["tongs/ its"]', '["n-m"]', '(only in dual) tweezers snuffers, tongs.', 'or מַלְקָח; from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4289}/H9024/[H4288]', 'inflected', 'heb', 'מַחְתָּה', '["machtâh"]', '["fire-pans/ its"]', '["n-f"]', 'a pan for live coals censer, firepan, snuffdish.', 'the same as 4288 in the sense of removal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8081}/H9024/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["oil/ its"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4132}/[H4131]', 'inflected', 'heb', 'מוֹט', '["môwṭ"]', '["the/ carrying frame"]', '["n-m"]', 'a wavering, i.e. fall; by implication, a pole (as shaking); hence, a yoke (as essentially a bent pole) bar, be moved, staff, yoke.', 'from 4131;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8335}/[H8334]', 'inflected', 'heb', 'שָׁרֵת', '["shârêth"]', '["<the>/ service"]', '["n-m"]', 'service (in the Temple) minister(-ry).', 'infinitive of 8334;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1878}/[H1880]', 'inflected', 'heb', 'דָּשֵׁן', '["dâshên"]', '["and/ it will grow fat","and/ they will take away [the] ashes from"]', '["v"]', 'to be fat; transitively, to fatten (or regard as fat); specifically to anoint; figuratively, to satisfy; to remove (fat) ashes (of sacrifices) accept, anoint, take away the (receive) ashes (from), make (wax) fat.', 'a primitive root; also denominatively (from 1880)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0713>', 'opaque', 'heb', 'אַרְגָּמָן', '["ʼargâmân"]', '["purple","purple cloth","purple wool"]', '["n-m"]', 'purple (the color or the dyed stuff) purple.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4853A}/[H5375]', 'lemma', 'heb', 'מַשָּׂא', '["massâʼ"]', '["[are] [the] burden of","[the] burden of","[the] load of","[the] uplifting of","[was] carrying","a burden","a load","an oracle","carrying","load"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7004}/[H6999]', 'inflected', 'heb', 'קְטֹרֶת', '["qᵉṭôreth"]', '["and/ [the] incense of","and/ incense","and/ incense of","and/ perfume"]', '["n-f"]', 'a fumigation (sweet) incense, perfume.', 'from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3627}/H9023\/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["and/ with/ equipment<s>/ its"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1104}/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["as/ a swallowing"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6633}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["to/ serve","to/ wage war"]', '["v"]', 'to mass (an army or servants) assemble, fight, perform, muster, wait upon, war.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635I}/[H6633]', 'lemma', 'heb', 'צָבָא', '["tsâbâʼ"]', '["[does] service","service"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5647G}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["to/ compel to labor","to/ serve"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4853A}/[H5375]', 'inflected', 'heb', 'מַשָּׂא', '["massâʼ"]', '["and/ for/ carrying"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5656H}/H9028/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["service/ their"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4853A}/H9028/[H5375]', 'inflected', 'heb', 'מַשָּׂא', '["massâʼ"]', '["carrying/ their"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4931}/[H4929]', 'inflected', 'heb', 'מִשְׁמֶרֶת', '["mishmereth"]', '["<in>/ a duty"]', '["n-f"]', 'watch, i.e. the act (custody), or (concretely) the sentry, the post; objectively preservation, or (concretely) safe; figuratively observance, i.e. (abstractly) duty or (objectively) a usage or party charge, keep, or to be kept, office, ordinace, safeguard, ward, watch.', 'feminine of 4929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8034}/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["and/ <in>/ [the] name of","and/ by/ names","and/ in/ [the] name of","and/ on/ [the] name of","and/ with/ [the] name of"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1004M}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ [belonged] to/ [the] house of","and/ of/ [the] house of","and/ to/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5656H}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["for/ [the] service of","for/ [the] work of","for/ labor","for/ service","of/ [the] service of"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5647H}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["<the>/ [one who] serves"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6485A}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ [the] enrolled [men] of","and/ enroll"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5656H}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["and/ a service of","and/ labor","and/ service"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2145}/[H2142]', 'inflected', 'heb', 'זָכָר', '["zâkâr"]', '["from/ male"]', '["n-m"]', 'properly, remembered, i.e. a male (of man or animals, as being the most noteworthy sex) × him, male, man(child, -kind).', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4264}/H9028/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["armies/ their","camps/ their"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4603}/[H4603]', 'inflected', 'heb', 'מָעַל', '["mâʻal"]', '["by/ acting unfaithfully","to/ act unfaithfully"]', '["v"]', 'properly, to cover up; used only figuratively, to act covertly, i.e. treacherously transgress, (commit, do a) trespass(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350I}/[H1350]', 'lemma', 'heb', 'גָּאַל', '["gâʼal"]', '["a kinsman-redeemer"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725H}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["<into>/ [one who] restores","to/ repay","to/ restore","to/ turn back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7725H}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["which/ is repaid"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6944G}/H9023/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["holiness/ his","holy things/ his","own holy things/ his"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1961}\/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["he was","it will be","it will belong","they belonged","they have become","they were","you will be"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7847}/[H7847]', 'lemma', 'heb', 'שָׂטָה', '["sâṭâh"]', '["it turn aside","she will turn aside","turn aside","you have turned aside"]', '["v"]', 'to deviate from duty decline, go aside, turn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5707}/[H5749]', 'inflected', 'heb', 'עֵד', '["ʻêd"]', '["and/ [is] a witness","and/ [was] a witness","and/ a witness","and/ a witness of"]', '["n-m"]', 'concretely, a witness; abstractly, testimony; specifically, a recorder, i.e. prince witness.', 'contracted from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7068}/[H7065]', 'lemma', 'heb', 'קִנְאָה', '["qinʼâh"]', '["[is] envy of","[the] jealousy of","[the] zeal of","jealousi<es>","jealousy","zeal"]', '["n-f"]', 'jealousy or envy envy(-ied), jealousy, × sake, zeal.', 'from 7065;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7133A}/H9024/[H7126]', 'inflected', 'heb', 'קׇרְבָּן', '["qorbân"]', '["offering/ her"]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5975G}/H9034/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ he will make stand/ her"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7172}/[H7167]', 'inflected', 'heb', 'קַרְקַע', '["qarqaʻ"]', '["at/ [the] bottom of","on/ [the] floor of"]', '["n-m"]', 'floor (as if a pavement of pieces or tesseræ), of a building or the sea bottom, (× one side of the) floor.', 'from 7167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6544B}/[H6544]', 'inflected', 'heb', 'פָּרַע', '["pâraʻ"]', '["and/ he will let loose","and/ you ignored"]', '["v"]', 'to loosen; by implication, to expose, dismiss; figuratively, absolve, begin avenge, avoid, bare, go back, let, (make) naked, set at nought, perish, refuse, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709G}/H9024/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["hand/ her","hands/ her","palm/ her"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2146}/[H2142]', 'inflected', 'heb', 'זִכְרוֹן', '["zikrôwn"]', '["<the>/ remembrance","the/ reminders"]', '["n-m"]', 'a memento (or memorable thing, day or writing) memorial, record.', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4751}/[H4843]', 'inflected', 'heb', 'מַר', '["mar"]', '["<the>/ bitter","<the>/ bitter [things]"]', '["a-m"]', 'bitter (literally or figuratively); also (as noun) bitterness, or (adverbially) bitterly angry, bitter(-ly, -ness), chafed, discontented, × great, heavy.', 'or (feminine) מָרָה; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0779}/[H779]', 'inflected', 'heb', 'אָרַר', '["ʼârar"]', '["the/ accursed [woman]","which/ bring a curse"]', '["v"]', 'to execrate × bitterly curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2932}/[H2930]', 'lemma', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["uncleanness"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0859C}/[H859]', 'inflected', 'heb', 'אַתָּה', '["ʼattâh"]', '["and/ you"]', '["p"]', 'thou and thee, or (plural) ye and you thee, thou, ye, you.', 'or (shortened); אַתָּ; or אַת; feminine (irregular) sometimes אַתִּי; plural masculine אַתֶּם; feminine אַתֶּן; or אַתֵּנָהlemma אתֵּנָה missing vowel, corrected to אַתֵּנָה; or אַתֵּנָּה; a primitive pronoun of the second person;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9032}', 'inflected', 'heb', 'בך', '["Ba/kh","Va/kh","ba/kh","bo/Kh","va/kh","vo/Kh"]', '["<in> <the>/ you","<in>/ you","[are] in/ you","[be] in/ you","[is] among/ you","[were] in/ you","among/ you","by/ yourself","in <the>/ you","in/ you","on <the>/ you","on/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1107}/[H1077]', 'inflected', 'heb', 'בִּלְעֲדֵי', '["bilʻădêy"]', '["<from>/ except","from/ except"]', '["prt"]', 'except, without, besides beside, not (in), save, without.', 'or בַּלְעֲדֵי; constructive plural from 1077 and 5703, not till, i.e. (as preposition or adverb)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0423}/[H422]', 'inflected', 'heb', 'אָלָה', '["ʼâlâh"]', '["<the>/ oath","[is] the/ curse","the/ curse","the/ curses","the/ oath","the/ oaths"]', '["n-f"]', 'an imprecation curse, cursing, execration, oath, swearing.', 'from 422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0423}/[H422]', 'inflected', 'heb', 'אָלָה', '["ʼâlâh"]', '["<into>/ a curse","<into>/ an curse","into/ a curse"]', '["n-f"]', 'an imprecation curse, cursing, execration, oath, swearing.', 'from 422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7621}/[H7650]', 'inflected', 'heb', 'שְׁבוּעָה', '["shᵉbûwʻâh"]', '["and/ into/ a oath"]', '["n-f"]', 'properly, something sworn, i.e. an oath curse, oath, × sworn.', 'feminine passive participle of 7650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971A}/H9022/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5414I}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["when/ makes"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3409>/H9022', 'opaque', 'heb', 'יָרֵךְ', '["yârêk"]', '["thigh/ your","thighs/ your"]', '["n-f"]', 'the thigh (from its fleshy softness); by euphemistically the generative parts; figuratively, a shank, flank, side × body, loins, shaft, side, thigh.', 'from an unused root meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990J>/H9022', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["belly/ your"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6639}/[H6638]', 'lemma', 'heb', 'צָבֶה', '["tsâbeh"]', '["swollen"]', '["a"]', 'turgid swell.', 'from 6638;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4578>/H9022', 'inflected', 'heb', 'במעיך', '["be./me.''A.yi/kh"]', '["in/ inward parts/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6638}/[H6638]', 'inflected', 'heb', 'צָבָה', '["tsâbâh"]', '["to/ make swell"]', '["v"]', 'to amass, i.e. grow turgid; specifically, to array an army against fight swell.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0543}/[H539]', 'lemma', 'heb', 'אָמֵן', '["ʼâmên"]', '["amen","surely"]', '["adv"]', 'sure; abstract, faithfulness; adverb, truly Amen, so be it, truth.', 'from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4751}/[H4843]', 'inflected', 'heb', 'מַר', '["mar"]', '["to/ [people] bitter of","to/ bitter [things]"]', '["a-m"]', 'bitter (literally or figuratively); also (as noun) bitterness, or (adverbially) bitterly angry, bitter(-ly, -ness), chafed, discontented, × great, heavy.', 'or (feminine) מָרָה; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7068}/[H7065]', 'inflected', 'heb', 'קִנְאָה', '["qinʼâh"]', '["<the>/ jealousi<es>","<the>/ jealousy"]', '["n-f"]', 'jealousy or envy envy(-ied), jealousy, × sake, zeal.', 'from 7065;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8248H}/H9034/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["and/ he will make drink/ her"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0376H>/H9024', 'inflected', 'heb', 'באישה', '["be./''i.Sha/h"]', '["against/ husband/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6638}/[H6638]', 'inflected', 'heb', 'צָבָה', '["tsâbâh"]', '["and/ it will swell"]', '["v"]', 'to amass, i.e. grow turgid; specifically, to array an army against fight swell.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990H>/H9024', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["belly/ her","womb/ her"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2889}/[H2891]', 'inflected', 'heb', 'טָהוֹר', '["ṭâhôwr"]', '["and/ [are] clean","and/ [is] pure","and/ [the] clean of"]', '["a"]', 'pure (in a physical, chemical, ceremonial or moral sense) clean, fair, pure(-ness).', 'or טָהֹר; from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5771G}/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["from/ iniquity"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0802G}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ <the>/ women","and/ the/ woman","and/ the/ women"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771G}/H9024\/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquity/ her"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5087}/[H5087]', 'inflected', 'heb', 'נָדַר', '["nâdar"]', '["to/ make a vow","to/ vow"]', '["v"]', 'to promise (pos., to do or give something to God) (make a) vow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5144B}/[H5144]', 'inflected', 'heb', 'נָזַר', '["nâzar"]', '["to/ be a Nazirite"]', '["v"]', 'to hold aloof, i.e. (intransitivey) abstain (from food and drink, from impurity, and even from divine worship (i.e. apostatize)); specifically, to set apart (to sacred purposes), i.e. devote consecrate, separate(-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5144B}/[H5144]', 'lemma', 'heb', 'נָזַר', '["nâzar"]', '["he will be a Nazirite","he will keep separate"]', '["v"]', 'to hold aloof, i.e. (intransitivey) abstain (from food and drink, from impurity, and even from divine worship (i.e. apostatize)); specifically, to set apart (to sacred purposes), i.e. devote consecrate, separate(-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2558}/[H2556]', 'lemma', 'heb', 'חֹמֶץ', '["chômets"]', '["vinegar","vinegar of"]', '["n-m"]', 'vinegar vinegar.', 'from 2556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2558}/[H2556]', 'inflected', 'heb', 'חֹמֶץ', '["chômets"]', '["and/ vinegar of"]', '["n-m"]', 'vinegar vinegar.', 'from 2556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7941}/[H7937]', 'lemma', 'heb', 'שֵׁכָר', '["shêkâr"]', '["strong drink"]', '["n-m"]', 'an intoxicant, i.e. intensely alcoholic liquor strong drink, drunkard, strong wine.', 'from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4952}/[H8281]', 'lemma', 'heb', 'מִשְׁרָה', '["mishrâh"]', '["juice of"]', '["n-f"]', 'maceration, i.e. steeped juice liquor.', 'from 8281 in the sense of loosening;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6025>', 'inflected', 'heb', 'וענבים', '["va./''a.na.Vim"]', '["and/ grapes"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3002}/[H3001]', 'inflected', 'heb', 'יָבֵשׁ', '["yâbêsh"]', '["and/ dried"]', '["a"]', 'dry dried (away), dry.', 'from 3001;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5145G}/H9023/[H5144]', 'inflected', 'heb', 'נֶזֶר', '["nezer"]', '["Nazirite vow/ his"]', '["n-m"]', 'properly, something set apart, i.e. (abstractly) dedication (of a priet or Nazirite); hence (concretely) unshorn locks; also (by implication) a chaplet (especially of royalty) consecration, crown, hair, separation.', 'or נֵזֶר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1612>', 'inflected', 'heb', 'מגפן', '["mi./Ge.fen"]', '["[is] from/ [the] vine of","from/ [the] vine of","from/ a vine"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2785}/[H2782]', 'inflected', 'heb', 'חַרְצַן', '["chartsan"]', '["from/ seeds"]', '["n-m"]', 'a sour grape (as sharp in taste) kernel.', 'from 2782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2085>', 'opaque', 'heb', 'זָג', '["zâg"]', '["skin"]', '["n-m"]', 'the skin of a grape husk.', 'from an unused root probably meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8593}/[H6168]', 'lemma', 'heb', 'תַּעַר', '["taʻar"]', '["<the> razor of","a razor"]', '["n"]', 'a knife or razor (as making bare); also a scabbard (as being bare, i.e. empty) (pen-) knife, razor, scabbard, shave, sheath.', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6545}/[H6544]', 'lemma', 'heb', 'פֶּרַע', '["peraʻ"]', '["[the] lock[s] of"]', '["n-m"]', 'the hair (as dishevelled) locks.', 'from 6544;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5144B}/H9043/[H5144]', 'inflected', 'heb', 'נָזַר', '["nâzar"]', '["being a Nazirite/ he"]', '["v"]', 'to hold aloof, i.e. (intransitivey) abstain (from food and drink, from impurity, and even from divine worship (i.e. apostatize)); specifically, to set apart (to sacred purposes), i.e. devote consecrate, separate(-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5145G}/[H5144]', 'lemma', 'heb', 'נֶזֶר', '["nezer"]', '["[the] Nazirite vow of"]', '["n-m"]', 'properly, something set apart, i.e. (abstractly) dedication (of a priet or Nazirite); hence (concretely) unshorn locks; also (by implication) a chaplet (especially of royalty) consecration, crown, hair, separation.', 'or נֵזֶר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6621>', 'inflected', 'heb', 'בפתע', '["be./Fe.ta''"]', '["in/ an instant"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6597}/[H6621]', 'lemma', 'heb', 'פִּתְאוֹם', '["pithʼôwm"]', '["suddenly"]', '["adv"]', 'instantly straightway, sudden(-ly).', 'or פִּתְאֹם; from 6621;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1548}/H9033/[H1548]', 'inflected', 'heb', 'גָּלַח', '["gâlach"]', '["he will shave/ it"]', '["v"]', 'properly, to be bald, i.e. (causatively) to shave; figuratively to lay waste poll, shave (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5315M}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["the/ corpse"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5144B}/[H5144]', 'inflected', 'heb', 'נָזַר', '["nâzar"]', '["and/ he will be a Nazirite"]', '["v"]', 'to hold aloof, i.e. (intransitivey) abstain (from food and drink, from impurity, and even from divine worship (i.e. apostatize)); specifically, to set apart (to sacred purposes), i.e. devote consecrate, separate(-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H3117G>', 'inflected', 'heb', 'והימים', '["ve./Hai./ya.Mim","ve./hai./Yom","ve./hai./ya.Mim"]', '["and/ <the>/ day","and/ the/ day","and/ the/ days","and/ this/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307J}/[H5307]', 'lemma', 'heb', 'נָפַל', '["nâphal"]', '["I will make fall","[was] falling","[was] lying","falling","he fell","he will fall","it will fall","lying","they fell","they have fallen","they will fall","you will fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5139}/[H5144]', 'inflected', 'heb', 'נָזִיר', '["nâzîyr"]', '["the/ Nazirite","the/ Nazirites"]', '["n-m"]', 'separate, i.e. consecrated (as prince, a Nazirite); hence (figuratively from the latter) an unpruned vine (like an unshorn Nazirite) Nazarite (by a false alliteration with Nazareth), separate(-d), vine undressed.', 'or נָזִר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5536}/[H5549]', 'inflected', 'heb', 'סַל', '["çal"]', '["and/ a basket of"]', '["n-m"]', 'properly, a willow twig (as pendulous), i.e. an osier; but only as woven into a basket basket.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403H}/H9023/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sin offering/ his"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5262}/H9023/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["drink offering/ his","drink offering/ its","molten image/ his"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2220}/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["the/ arm"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1311}/[H1310]', 'lemma', 'heb', 'בָּשֵׁל', '["bâshêl"]', '["boiled"]', '["a"]', 'boiled × at all, sodden.', 'from 1310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1548}/H9043/[H1548]', 'inflected', 'heb', 'גָּלַח', '["gâlach"]', '["he has shaved/ himself"]', '["v"]', 'properly, to be bald, i.e. (causatively) to shave; figuratively to lay waste poll, shave (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5088}/H9023/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["vow/ his"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5145G}/H9023\/[H5144]', 'inflected', 'heb', 'נֶזֶר', '["nezer"]', '["Nazirite vow/ his"]', '["n-m"]', 'properly, something set apart, i.e. (abstractly) dedication (of a priet or Nazirite); hence (concretely) unshorn locks; also (by implication) a chaplet (especially of royalty) consecration, crown, hair, separation.', 'or נֵזֶר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8104H}/H9031\/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ may he keep/ you"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2603A}/H9031\/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["and/ may he show favor to/ you"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965G}\/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["peace"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1288}/H9038\/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["I will bless/ them"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6965H}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["to/ set up"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4886}/H9038/[H4886]', 'inflected', 'heb', 'מָשַׁח', '["mâshach"]', '["and/ he anointed/ them"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4294H}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["the/ tribe","the/ tribes"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5975H}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["[were] the/ [ones who] stood","those/ [who] stood","who/ stands","who/ were standing"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6632A>', 'opaque', 'heb', 'צָב', '["tsâb"]', '["covering"]', '["n-m"]', 'a palanquin or canopy (as a fixture); also a species of lizard (probably as clinging fast) covered, litter, tortoise.', 'from an unused root meaning to establish;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3802>', 'inflected', 'heb', 'בכתף', '["ba./ka.Tef","ve./kha.Tef"]', '["on the/ shoulder","on/ [the] shoulder"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2598}/[H2596]', 'lemma', 'heb', 'חֲנֻכָּה', '["chănukkâh"]', '["[the] dedication of","[was] [the] dedication of","dedication"]', '["n-f"]', 'initiation, i.e. consecration dedicating(-tion).', 'from 2596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2598}/[H2596]', 'inflected', 'heb', 'חֲנֻכָּה', '["chănukkâh"]', '["for/ [the] dedication of"]', '["n-f"]', 'initiation, i.e. consecration dedicating(-tion).', 'from 2596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4196}\/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["the/ altar"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7133A}/H9023/[H7126]', 'inflected', 'heb', 'קׇרְבָּן', '["qorbân"]', '["and/ offering/ his"]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7086}/[H7167]', 'lemma', 'heb', 'קְעָרָה', '["qᵉʻârâh"]', '["[was] a dish of","a dish of","dishes of"]', '["n-f"]', 'a bowl (as cut out hollow) charger, dish.', 'probably from 7167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4948}/H9024/[H8254]', 'inflected', 'heb', 'מִשְׁקָל', '["mishqâl"]', '["weight/ its"]', '["n-m"]', 'weight (numerically estimated); hence, weighing (the act) (full) weight.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4219}/[H2236]', 'lemma', 'heb', 'מִזְרָק', '["mizrâq"]', '["a bowl","bowls","bowls of"]', '["n-m"]', 'a bowl (as if for sprinkling) bason, bowl.', 'from 2236;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6260}/[H6257]', 'lemma', 'heb', 'עַתּוּד', '["ʻattûwd"]', '["[the] leaders of","goats"]', '["n-m"]', 'prepared, i.e. full grown; spoken only (in plural) of he-goats, or (figuratively) leaders of the people chief one, (he) goat, ram.', 'or עַתֻּד; from 6257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5992G}\/[H5971]', 'inflected', 'heb', 'עַמִּינָדָב', '["ʻAmmîynâdâb"]', '["Amminadab"]', '["n-pr-m"]', 'Amminadab, the name of four Israelites Amminadab.', 'from 5971 and 5068; people of liberality;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6686}\/[H6819]', 'inflected', 'heb', 'צוּעָר', '["Tsûwʻâr"]', '["Zuar"]', '["n-pr-m"]', 'Tsuär, an Israelite Zuar.', 'from 6819; small;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2497}\/[H2428]', 'inflected', 'heb', 'חֵלֹן', '["Chêlôn"]', '["Helon"]', '["n-pr-m"]', 'Chelon, an Israelite Helon.', 'from 2428; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7707}\/[H7704]', 'inflected', 'heb', 'שְׁדֵיאוּר', '["Shᵉdêyʼûwr"]', '["Shedeur"]', '["n-pr-m"]', 'Shedejur, an Israelite Shedeur.', 'from the same as 7704 and 217; spreader of light;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6701}\/[H6697]', 'inflected', 'heb', 'צוּרִישַׁדַּי', '["Tsûwrîyshadday"]', '["Zurishaddai"]', '["n-pr-m"]', 'Tsurishaddai, an Israelite Zurishaddai.', 'from 6697 and 7706; rock of (the) Almighty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1845}\/[H3045]', 'inflected', 'heb', 'דְּעוּאֵל', '["Dᵉʻûwʼêl"]', '["Deuel"]', '["n-pr-m"]', 'Deuel, an Israelite Deuel.', 'from 3045 and 410; known of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5989G}\/[H5971]', 'inflected', 'heb', 'עַמִּיהוּד', '["ʻAmmîyhûwd"]', '["Ammihud"]', '["n-pr-m"]', 'Ammihud, the name of three Israelites Ammihud.', 'from 5971 and 1935; people of splendor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6301}+/ /{H6301}\/[H6299]', 'inflected', 'heb', 'פְּדָהצוּר', '["Pᵉdâhtsûwr"]', '["Pedah/ /zur"]', '["n-pr-m"]', 'Pedahtsur, an Israelite Pedahzur.', 'from 6299 and 6697; a rock (i.e. God) has ransomed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1441}\/[H1438]', 'inflected', 'heb', 'גִּדְעֹנִי', '["Gidʻônîy"]', '["Gideoni"]', '["n-pr-m"]', 'Gidoni, an Israelite Gideoni.', 'from 1438; warlike (compare 1439);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5996}\/[H5971]', 'inflected', 'heb', 'עַמִּישַׁדַּי', '["ʻAmmîyshadday"]', '["Ammishaddai"]', '["n-pr-m"]', 'Ammishaddai, an Israelite Ammishaddai.', 'from 5971 and 7706; people of (the) Almighty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5918}\/[H5916]', 'inflected', 'heb', 'עׇכְרָן', '["ʻOkrân"]', '["Ocran"]', '["n-pr-m"]', 'Okran, an Israelite Ocran.', 'from 5916; muddler;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5881}\/[H5869]', 'inflected', 'heb', 'עֵינָן', '["ʻÊynân"]', '["Enan"]', '["n-pr-m"]', 'Enan, an Israelite Enan. Compare 2704.', 'from 5869; having eyes;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8163B}/[H8175]', 'inflected', 'heb', 'שָׂעִיר', '["sâʻîyr"]', '["and/ a male goat of","and/ male goats of"]', '["a n-m"]', 'shaggy; as noun, a he-goat; by analogy, a faun devil, goat, hairy, kid, rough, satyr.', 'or שָׂעִר; from 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/H9033\/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["against/ him","to/ him","to/ himself"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5927H}/H9041/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["when/ lifting up/ you"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6525}/H9024/[H6524]', 'inflected', 'heb', 'פֶּרַח', '["perach"]', '["blossom/ its"]', '["n-m"]', 'a calyx (natural or artificial); generally, bloom blossom, bud, flower.', 'from 6524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4501}\/[H4500]', 'inflected', 'heb', 'מְנוֹרָה', '["mᵉnôwrâh"]', '["the/ lampstand"]', '["n-f"]', 'a chandelier candlestick.', 'or מְנֹרָה; feminine of 4500 (in the original sense of 5216);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2891}/H9038/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["to/ purify/ them"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403I}/[H2398]', 'lemma', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["[the] punishment for sin of","sin offering"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0899B}/H9028/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["clothes/ their"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5564}/[H5564]', 'lemma', 'heb', 'סָמַךְ', '["çâmak"]', '["I have supported myself","[is] supported","[is] supporting","[is] sustaining","[the] supporters of","[they are] sustained","[was] a sustainer","firm","he had laid","he has leaned","he will support himself","it has lain","they have supported themselves","they will lay"]', '["v"]', 'to prop (literally or figuratively); reflexively, to lean upon or take hold of (in a favorable or unfavorable sense) bear up, establish, (up-) hold, lay, lean, lie hard, put, rest self, set self, stand fast, stay (self), sustain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6363B}/[H6362]', 'lemma', 'heb', 'פֶּטֶר', '["peṭer"]', '["[the] firstborn of"]', '["n-m"]', 'a fissure, i.e. (concretely) firstling (as opening the matrix) firstling, openeth, such as open.', 'or פִּטְרָה; from 6362;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414G}/H9012/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I gave [it]/ !","and/ I gave/ !","and/ I have given/ !"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3722A}/[H3722]', 'inflected', 'heb', 'כָּפַר', '["kâphar"]', '["and/ to/ atone for","and/ to/ make atonement"]', '["v"]', 'to cover (specifically with bitumen); figuratively, to expiate or condone, to placate or cancel appease, make (an atonement, cleanse, disannul, forgive, be merciful, pacify, pardon, purge (away), put off, (make) reconcile(-liation).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5066G}/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["when/ draw near"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5656H}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["in/ [the] service of"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1121L}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ from/ a son of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6635I}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["from/ [the] service of","from/ [the] war of"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4931}/H9028\/[H4929]', 'inflected', 'heb', 'מִשְׁמֶרֶת', '["mishmereth"]', '["in/ duties/ their"]', '["n-f"]', 'watch, i.e. the act (custody), or (concretely) the sentry, the post; objectively preservation, or (concretely) safe; figuratively observance, i.e. (abstractly) duty or (objectively) a usage or party charge, keep, or to be kept, office, ordinace, safeguard, ward, watch.', 'feminine of 4929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4150G}/H9023/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["at/ appointed time/ its"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2708}/H9023/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["statutes/ his","statutes/ its"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3605}/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["and/ according to/ all"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941G}/H9023/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["decision/ its","judgments/ his","judgments/ its"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7350}/[H7368]', 'lemma', 'heb', 'רָחוֹק', '["râchôwq"]', '["O distant [ones]","[are] distant","[are] far","[is] far","[is] far away","[was] far","a distance","distant","far away"]', '["a"]', 'remote, literally or figuratively, of place or time; specifically, precious; often used adverbially (with preposition) (a-) far (abroad, off), long ago, of old, space, great while to come.', 'or רָחֹק; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4844}/[H4843]', 'inflected', 'heb', 'מְרֹר', '["mᵉrôr"]', '["and/ bitter herbs"]', '["n-m"]', 'a bitter herb bitter(-ness).', 'or מְרוֹר; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1870L}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ on/ a journey"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2308}/[H2308]', 'inflected', 'heb', 'חָדַל', '["châdal"]', '["and/ I will cease","and/ cease","and/ he failed","so/ he may cease"]', '["v"]', 'properly, to be flabby, i.e. (by implication) desist; (figuratively) be lacking or idle cease, end, fall, forbear, forsake, leave (off), let alone, rest, be unoccupied, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2708}/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["according to/ [the] statute of"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4941G}/H9023/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ according to/ judgment/ its"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0249}/[H2224]', 'inflected', 'heb', 'אֶזְרָח', '["ʼezrâch"]', '["and/ to/ [the] native-born of"]', '["n-m"]', 'a spontaneous growth, i.e. native (tree or persons) bay tree, (home-) born (in the land), of the (one''s own) country (nation).', 'from 2224 (in the sense of springing up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6153}/[H6150]', 'inflected', 'heb', 'עֶרֶב', '["ʻereb"]', '["and/ in the/ evening"]', '["n-m"]', 'dusk day, even(-ing, tide), night.', 'from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4725}/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["and/ in the/ place","and/ in/ [the] place","and/ in/ [the] place of"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0748}/[H748]', 'inflected', 'heb', 'אָרַךְ', '["ʼârak"]', '["and/ when/ made long"]', '["v"]', 'to be (causative, make) long (literally or figuratively) defer, draw out, lengthen, (be, become, make, pro-) long, (out-, over-) live, tarry (long).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0748}/[H748]', 'inflected', 'heb', 'אָרַךְ', '["ʼârak"]', '["when/ made long"]', '["v"]', 'to be (causative, make) long (literally or figuratively) defer, draw out, lengthen, (be, become, make, pro-) long, (out-, over-) live, tarry (long).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7931}/[H7901]', 'inflected', 'heb', 'שָׁכַן', '["shâkan"]', '["to/ cause to dwell","to/ dwell"]', '["v"]', 'to reside or permanently stay (literally or figuratively) abide, continue, (cause to, make to) dwell(-er), have habitation, inhabit, lay, place, (cause to) remain, rest, set (up).', 'a primitive root (apparently akin (by transmission) to 7901 through the idea of lodging; compare 5531, 7925);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5927H}/H9043/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ when/ was taken up/ it"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2689}/[H2690]', 'lemma', 'heb', 'חֲצֹצְרָה', '["chătsôtsᵉrâh"]', '["a trumpet","trumpets","trumpets of"]', '["n-f"]', 'a trumpet (from its sundered or quavering note) trumpet(-er).', 'by reduplication from 2690;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4744}/[H7121]', 'inflected', 'heb', 'מִקְרָא', '["miqrâʼ"]', '["for/ [the] convocation of"]', '["n-m"]', 'something called out, i.e. a public meeting (the act, the persons, or the place); also a rehearsal assembly, calling, convocation, reading.', 'from 7121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4550}/[H5265]', 'inflected', 'heb', 'מַסַּע', '["maççaʻ"]', '["and/ for/ breaking"]', '["n-m"]', 'a departure (from striking the tents), i.e. march (not necessarily a single day''s travel); by implication, a station (or point of departure) journey(-ing).', 'from 5265;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8628}/[H8628]', 'inflected', 'heb', 'תָּקַע', '["tâqaʻ"]', '["and/ I will give a blast","and/ he gave a blast","and/ he will give a blast","and/ she drove","and/ she thrust","and/ they gave a blast","and/ they gave blasts","and/ they will give a blast","and/ you will give a blast","and/ you will strike"]', '["v"]', 'to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2583}/[H2603]', 'inflected', 'heb', 'חָנָה', '["chânâh"]', '["that/ were encamping","which/ encamp"]', '["v"]', 'properly, to incline; by implication, to decline (of the slanting rays of evening); specifically, to pitch a tent; generally to encamp (for abode or siege) abide (in tents), camp, dwell, encamp, grow to an end, lie, pitch (tent), rest in tent.', 'a primitive root (compare 2603);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6950}/[H6950]', 'inflected', 'heb', 'קָהַל', '["qâhal"]', '["and/ when/ summon"]', '["v"]', 'to convoke assemble (selves) (together), gather (selves) (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7321}/[H7321]', 'lemma', 'heb', 'רוּעַ', '["rûwaʻ"]', '["I shout in triumph","[were] shouting","anything will be shouted","do you shout","he shouts in triumph","he will raise a war-cry","let us shout for joy","people shout","shout","shout for joy","shout in triumph","shout out","sound an alarm","they are shouting","they shout for joy","they shouted","they will shout","you must shout","you will give an alarm"]', '["v"]', 'to mar (especially by breaking); figuratively, to split the ears (with sound), i.e. shout (for alarm or joy) blow an alarm, cry (alarm, aloud, out), destroy, make a joyful noise, smart, shout (for joy), sound an alarm, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2689}/[H2690]', 'inflected', 'heb', 'חֲצֹצְרָה', '["chătsôtsᵉrâh"]', '["on/ trumpets","with <the>/ trumpets","with/ trumpets"]', '["n-f"]', 'a trumpet (from its sundered or quavering note) trumpet(-er).', 'by reduplication from 2690;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6862C}/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["the/ foe","the/ opponent"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6887D}/[H6887]', 'inflected', 'heb', 'צָרַר', '["tsârar"]', '["who/ opposes"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7321}/[H7321]', 'inflected', 'heb', 'רוּעַ', '["rûwaʻ"]', '["and/ it shouted","and/ they shouted","and/ they shouted a war cry","and/ they shouted in distress","and/ they sounded [the] battle signal","and/ you will give an alarm","and/ you will shout"]', '["v"]', 'to mar (especially by breaking); figuratively, to split the ears (with sound), i.e. shout (for alarm or joy) blow an alarm, cry (alarm, aloud, out), destroy, make a joyful noise, smart, shout (for joy), sound an alarm, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0341}/H9026/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["from/ enemies/ your"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8057}/H9026/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["rejoicing/ your"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4150H}/H9026/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["and/ at/ appointed feasts/ your"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H7218J>', 'inflected', 'heb', 'ובראשי', '["u./ve./ra.Shei"]', '["and/ at/ [the] beginnings of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2320G}/H9026/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["months/ your"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5930A}/H9026/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["burnt offerings/ your"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4908}\/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["the/ tabernacle"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9048\/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["came/ they"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4550}/[H5265]', 'lemma', 'heb', 'מַסַּע', '["maççaʻ"]', '["[are] [the] settings out of"]', '["n-m"]', 'a departure (from striking the tents), i.e. march (not necessarily a single day''s travel); by implication, a station (or point of departure) journey(-ing).', 'from 5265;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5265}\/[H5265]', 'inflected', 'heb', 'נָסַע', '["nâçaʻ"]', '["and/ they set out"]', '["v"]', 'properly, to pull up, especially the tent-pins, i.e. start on a journey cause to blow, bring, get, (make to) go (away, forth, forward, onward, out), (take) journey, march, remove, set aside (forward), × still, be on his (go their) way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2246}/[H2245]', 'inflected', 'heb', 'חֹבָב', '["Chôbâb"]', '["to/ Hobab"]', '["n-pr-m"]', 'Chobab, father-in-law of Moses Hobab.', 'from 2245; cherished;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4084}/[H4080]', 'inflected', 'heb', 'מִדְיָנִי', '["Midyânîy"]', '["the/ Midianite","the/ Midianite [woman]","the/ Midianites"]', '["a"]', 'a Midjanite or descendant (native) of Midjan Midianite. Compare 4092.', 'patronymical or patrial from 4080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980H}/H9012/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["come there/ !","come/ !"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2583}/H9045/[H2603]', 'inflected', 'heb', 'חָנָה', '["chânâh"]', '["encamping/ we"]', '["v"]', 'properly, to incline; by implication, to decline (of the slanting rays of evening); specifically, to pitch a tent; generally to encamp (for abode or siege) abide (in tents), camp, dwell, encamp, grow to an end, lie, pitch (tent), rest in tent.', 'a primitive root (compare 2603);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2896B}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["<the>/ good","the/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0727}/[H717]', 'inflected', 'heb', 'אָרוֹן', '["ʼârôwn"]', '["and/ [the] ark of"]', '["n-m"]', 'a box ark, chest, coffin.', 'or אָרֹן; from 717 (in the sense of gathering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8446}/[H8446]', 'inflected', 'heb', 'תּוּר', '["tûwr"]', '["to/ seek out","to/ spy out"]', '["v"]', 'to meander (causatively, guide) about, especially for trade or reconnoitring chap(-man), sent to descry, be excellent, merchant(-man), search (out), seek, (e-) spy (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4264}\ \/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["the/ camp"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965B}/H9012/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["arise/ !","rise up/ !"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6327A}/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["and/ [who are] scattering","and/ they may be scattered","so/ they may be scattered"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5127}/[H5127]', 'inflected', 'heb', 'נוּס', '["nûwç"]', '["<and>/ flee","and/ they may flee"]', '["v"]', 'to flit, i.e. vanish away (subside, escape; causatively, chase, impel, deliver) × abate, away, be displayed, (make to) flee (away, -ing), put to flight, × hide, lift up a standard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5117}/H9043/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["and/ when/ rested/ it"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725G}/H9012/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["return/ !"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3478}\ \/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0596}/[H596]', 'inflected', 'heb', 'אָנַן', '["ʼânan"]', '["like/ [those who] complain"]', '["v"]', 'to mourn, i.e. complain complain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8257}/[H8257]', 'inflected', 'heb', 'שָׁקַע', '["shâqaʻ"]', '["and/ it died out","and/ it sinks","and/ it will sink"]', '["v"]', 'to subside; by implication, to be overflowed, cease; causatively, to abate, subdue make deep, let down, drown, quench, sink.', '(abbreviated Amos 8:8); a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8404}/[H1197]', 'lemma', 'heb', 'תַּבְעֵרָה', '["Tabʻêrâh"]', '["Taberah"]', '["n-pr-loc"]', 'Taberah, a place in the Desert Taberah.', 'from 1197; burning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0628}/[H624]', 'inflected', 'heb', 'אֲסְפְּסֻף', '["ʼăçpᵉçuph"]', '["and/ the/ rabble"]', '["n-m"]', 'gathered up together, i.e. a promiscuous assemblage (of people) mixt multitude.', 'by reduplication from 624;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0183}/[H183]', 'lemma', 'heb', 'אָוָה', '["ʼâvâh"]', '["I have desired","[is] coveting","he craves","he desires","it craves","it desires","it has desired","it will desire","they craved","you crave","you desire","you must desire"]', '["v"]', 'to wish for covet, (greatly) desire, be desirous, long, lust (after).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0398}/H9035/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["it will consume/ us","will he cause to eat/ us"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1710}/[H1709]', 'inflected', 'heb', 'דָּגָה', '["dâgâh"]', '["the/ fish"]', '["n-f"]', 'fish.', 'feminine of 1709, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7180>', 'inflected', 'heb', 'הקשאים', '["ha./ki.shu.''Im"]', '["the/ cucumbers"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0020>', 'inflected', 'heb', 'האבטחים', '["ha./''a.va.ti.Chim"]', '["the/ watermelons"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2682B}/[H2681]', 'inflected', 'heb', 'חָצִיר', '["châtsîyr"]', '["the/ leek[s]"]', '["n-m"]', 'grass; also a leek (collectively) grass, hay, herb, leek.', 'perhaps originally the same as 2681, from the greenness of a courtyard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1211>', 'inflected', 'heb', 'הבצלים', '["ha./be.tza.Lim"]', '["the/ onions"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7762>', 'inflected', 'heb', 'השומים', '["ha./shu.Mim"]', '["the/ garlic<s>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315L}/H9025/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["appetite/ our"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3002}/[H3001]', 'lemma', 'heb', 'יָבֵשׁ', '["yâbêsh"]', '["[is] dry","[they were] dry","dry"]', '["a"]', 'dry dried (away), dry.', 'from 3001;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869H}/H9025/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eyes/ our"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4478A}/[H4100]', 'inflected', 'heb', 'מָן', '["mân"]', '["and/ the/ manna"]', '["n-m"]', 'literally a whatness (so to speak), i.e. manna (so called from the question about it) manna.', 'from 4100;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5869I}/H9023/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ appearance/ its"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5869I}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["[was] like/ [the] appearance of","[were] like/ [the] appearance of","like/ [the] appearance of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7751A}/[H7751]', 'lemma', 'heb', 'שׁוּט', '["shûwṭ"]', '["[are] roving about","go about","rove about","they went about","they will rove about"]', '["v"]', 'properly, to push forth; (but used only figuratively) to lash, i.e. (the sea with oars) to row; by implication, to travel go (about, through, to and fro), mariner, rower, run to and fro.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7347>', 'inflected', 'heb', 'ברחים', '["va./re.Cha.yim"]', '["in <the>/ hand-mill"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1743}/[H1743]', 'lemma', 'heb', 'דּוּךְ', '["dûwk"]', '["they pounded"]', '["v"]', 'to bruise in a mortar beat.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4085}/[H1743]', 'inflected', 'heb', 'מְדֹכָה', '["mᵉdôkâh"]', '["in <the>/ mortar"]', '["n-f"]', 'a mortar mortar.', 'from 1743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6517}/[H6565]', 'inflected', 'heb', 'פָּרוּר', '["pârûwr"]', '["in <the>/ pot","in the/ pot"]', '["n-m"]', 'a skillet (as flat or deep) pan, pot.', 'passive participle of 6565 in the sense of spreading out (compare 6524);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2940}/H9023/[H2938]', 'inflected', 'heb', 'טַעַם', '["ṭaʻam"]', '["sense/ his","taste/ its"]', '["n-m"]', 'properly, a taste, i.e. (figuratively) perception; by implication, intelligence; transitively, a mandate advice, behaviour, decree, discretion, judgment, reason, taste, understanding.', 'from 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2940}/[H2938]', 'inflected', 'heb', 'טַעַם', '["ṭaʻam"]', '["like/ [the] taste of"]', '["n-m"]', 'properly, a taste, i.e. (figuratively) perception; by implication, intelligence; transitively, a mandate advice, behaviour, decree, discretion, judgment, reason, taste, understanding.', 'from 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3955>', 'opaque', 'heb', 'לְשַׁד', '["lᵉshad"]', '["<the> cake of"]', '["n-m"]', '(figuratively) vigor; also a sweet or fat cake fresh, moisture.', 'from an unused root of uncertain meaning; apparently juice, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3381}/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["and/ when/ came down"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0595}/[H595]', 'inflected', 'heb', 'אָנֹכִי', '["ʼânôkîy"]', '["¿/ I"]', '["p"]', 'I I, me, × which.', 'sometimes, אָנֹכִי; a primitive pronoun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3205}/H9033/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["[who] begot/ him","did I give birth to/ it","does he give birth to/ it","she has given birth to/ him"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375H}/H9033/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["I will carry/ it","carry/ him","carry/ it","it carries/ it","it has carried off/ him","it will lift up/ him","to carry/ it"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0539}/[H541]', 'inflected', 'heb', 'אָמַן', '["ʼâman"]', '["<the>/ faithful","<the>/ foster-father","<the>/ reliable","the/ [one who] trusts","the/ [ones] brought up","the/ guardians"]', '["v"]', 'properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right.', 'a primitive root; (Isaiah 30:21; interchangeable with 541, to go to the right hand)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3243J}/[H3243]', 'inflected', 'heb', 'יָנַק', '["yânaq"]', '["the/ suckling-child"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0905H}/H9030/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["to/ alone/ me"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7451C}/H9020\/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["on/ distress/ my"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0622}/H9012/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["gather/ !"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0680}/[H680]', 'inflected', 'heb', 'אָצַל', '["ʼâtsal"]', '["and/ I will share","and/ he shared"]', '["v"]', 'properly, to join; used only as a denominative from 681; to separate; hence, to select, refuse, contract keep, reserve, straiten, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7307G}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["the/ spirit","the/ spirits","the/ wind"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4853A}/[H5375]', 'inflected', 'heb', 'מַשָּׂא', '["massâʼ"]', '["in the/ lifting up","in/ [the] burden of","in/ a lifting up"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0398}/H9013/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["they eat/ !","they will eat/ !","you will eat/ !"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0639H}/H9026/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["from/ nose/ your"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2214}/[H2114]', 'inflected', 'heb', 'זָרָא', '["zârâʼ"]', '["<into>/ a loathsome thing"]', '["n-m"]', 'disgust loathsome.', 'from 2114 (in the sense of estrangement) (compare 2219);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130G}/H9026/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["[are] in/ midst/ your","[is] in/ midst/ your","[will be] in/ midst/ your","in/ inner being/ your","in/ midst/ your"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/<H6629G>', 'inflected', 'heb', 'הצאן', '["ha./Tzon"]', '["¿/ a flock"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3027H}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["¿/ [is] [the] hand of","¿/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7114A}/[H7114]', 'lemma', 'heb', 'קָצַר', '["qâtsar"]', '["[were] short","he has cut short","is it short","it is [too] short","they will be short","was it [too] short","will it be short","you have made short"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7136A}/H9031/[H7136]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["¿/ will it happen to/ you"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697G}/H9020/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<of> words/ my","[is] word/ my","word/ my","words/ my"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5975J}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ I stationed","and/ he stationed"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5117}/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["when/ rest","when/ rested"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5012}/[H5012]', 'inflected', 'heb', 'נָבָא', '["nâbâʼ"]', '["and/ I prophesied","and/ he prophesied","and/ they prophesied","and/ you will prophesy"]', '["v"]', 'to prophesy, i.e. speak (or sing) by inspiration (in prediction or simple discourse) prophesy(-ing), make self a prophet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0419}/[H410]', 'lemma', 'heb', 'אֶלְדָּד', '["ʼEldâd"]', '["Eldad","[was] Eldad"]', '["n-pr-m"]', 'Eldad, an Israelite Eldad.', 'from 410 and 1730; God has loved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4312}/[H3032]', 'lemma', 'heb', 'מֵידָד', '["Mêydâd"]', '["[was] Medad"]', '["n-pr-m"]', 'Medad, an Israelite Medad.', 'from 3032 in the sense of loving; affectionate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3789}/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["among those/ written","when/ records"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4312}/[H3032]', 'inflected', 'heb', 'מֵידָד', '["Mêydâd"]', '["and/ Medad"]', '["n-pr-m"]', 'Medad, an Israelite Medad.', 'from 3032 in the sense of loving; affectionate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5012}/[H5012]', 'lemma', 'heb', 'נָבָא', '["nâbâʼ"]', '["[are] prophesying","[he is] prophesying","[is] prophesying","[those who] prophesy","[were] prophesying","[who] prophesy","[will be] prophesying","have you prophesied","he has prophesied","he prophesied","he prophesies","he will prophesy","prophesy","prophesying","they have prophesied","they prophesied","will he prophesy","you have prophesied","you must prophesy","you prophesied","you will prophesy"]', '["v"]', 'to prophesy, i.e. speak (or sing) by inspiration (in prediction or simple discourse) prophesy(-ing), make self a prophet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0979}/H9023/[H970]', 'inflected', 'heb', 'בְּחֻרוֹת', '["bᵉchurôwth"]', '["from/ youth<s>/ his"]', '["n-f"]', 'youth (collectively and abstractly) young men, youth.', 'or בְּחוּרוֹת; feminine plural of 970; also (masculine plural) בְּחֻרִים;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3607}/H9038/[H3607]', 'inflected', 'heb', 'כָּלָא', '["kâlâʼ"]', '["restrain/ them"]', '["v"]', 'to restrict, by act (hold back or in) or word (prohibit) finish, forbid, keep (back), refrain, restrain, retain, shut up, be stayed, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7065}/[H7065]', 'inflected', 'heb', 'קָנָא', '["qânâʼ"]', '["¿/ zealous"]', '["v"]', 'to be (causatively, make) zealous, i.e. (in a bad sense) jealous or envious (be) envy(-ious), be (move to, provoke to) jealous(-y), × very, (be) zeal(-ous).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1468}/[H1494]', 'inflected', 'heb', 'גּוּז', '["gûwz"]', '["and/ it brought"]', '["v"]', 'properly, to shear off; but used only in the (figuratively) sense of passing rapidly bring, cut off.', 'a primitive root (compare 1494);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7958}/[H7951]', 'lemma', 'heb', 'שְׂלָו', '["sᵉlâv"]', '["quail","quails"]', '["n-f"]', 'the quail collectively (as slow in flight from its weight) quails.', 'or שְׂלָיו; by orthographical variation from 7951 through the idea of sluggishness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5203}/[H5203]', 'inflected', 'heb', 'נָטַשׁ', '["nâṭash"]', '["and/ I will abandon","and/ he abandoned","and/ he has abandoned","and/ he left","and/ it left [them]","and/ it spread out","and/ they were spread out"]', '["v"]', 'properly, to pound, i.e. smite; by implication (as if beating out, and thus expanding) to disperse; also, to thrust off, down, out or upon (inclusively, reject, let alone, permit, remit, etc.) cast off, drawn, let fall, forsake, join (battle), leave (off), lie still, loose, spread (self) abroad, stretch out, suffer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1870L}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["about/ a journey of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H1870L}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ about/ a journey of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0520A}/[H517]', 'inflected', 'heb', 'אַמָּה', '["ʼammâh"]', '["and/ about/ two cubits"]', '["n-f"]', 'properly, a mother (i.e. unit of measure, or the fore-arm (below the elbow), i.e. a cubit; also a door-base (as a bond of the entrance) cubit, + hundred (by exchange for 3967), measure, post.', 'prolonged from 517;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4283}/[H4279]', 'inflected', 'heb', 'מׇחֳרָת', '["mochŏrâth"]', '["the/ next day"]', '["n-f"]', 'the morrow or (adverbially) tomorrow morrow, next day.', 'or מׇחֳרָתָם; (1 Samuel 30:17), feminine from the same as 4279;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4591}/[H4591]', 'inflected', 'heb', 'מָעַט', '["mâʻaṭ"]', '["the/ [one who] did little"]', '["v"]', 'properly, to pare off, i.e. lessen; intransitively, to be (or causatively, to make) small or few (or figuratively, ineffective) suffer to decrease, diminish, (be, × borrow a, give, make) few (in number, -ness), gather least (little), be (seem) little, (× give the) less, be minished, bring to nothing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7849}/[H7849]', 'inflected', 'heb', 'שָׁטַח', '["shâṭach"]', '["and/ she spread","and/ they spread [them] out"]', '["v"]', 'to expand all abroad, enlarge, spread, stretch out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7849}/[H7849]', 'lemma', 'heb', 'שָׁטַח', '["shâṭach"]', '["I have spread out","[he is] spreading out","completely <to spread out>"]', '["v"]', 'to expand all abroad, enlarge, spread, stretch out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8127G}/H9028/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["teeth/ their"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0639G}/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["and/ [the] anger of"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6914}/[H6913]', 'lemma', 'heb', 'קִבְרוֹת הַתַּאֲוָה', '["Qibrôwth hat-Taʼă-vâh"]', '["Hattaavah","Kibroth"]', '["n-pr"]', 'Kibroth-hat-Taavh, a place in the Desert Kibroth-hattaavah.', 'from the feminine plural of 6913 and 8378 with the article interposed; graves of the longing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0183}/[H183]', 'inflected', 'heb', 'אָוָה', '["ʼâvâh"]', '["those/ [who] desire","who/ craved"]', '["v"]', 'to wish for covet, (greatly) desire, be desirous, long, lust (after).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6914}/[H6913]', 'inflected', 'heb', 'קִבְרוֹת הַתַּאֲוָה', '["Qibrôwth hat-Taʼă-vâh"]', '["from/ Kibroth"]', '["n-pr"]', 'Kibroth-hat-Taavh, a place in the Desert Kibroth-hattaavah.', 'from the feminine plural of 6913 and 8378 with the article interposed; graves of the longing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2698}/[H2691]', 'lemma', 'heb', 'חֲצֵרוֹת', '["Chătsêrôwth"]', '["Hazeroth"]', '["n-pr-loc"]', 'Chatseroth, a place in Palestine Hazeroth.', 'feminine plural of 2691; yards;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2698}\/[H2691]', 'inflected', 'heb', 'חֲצֵרוֹת', '["Chătsêrôwth"]', '["at/ Hazeroth"]', '["n-pr-loc"]', 'Chatseroth, a place in Palestine Hazeroth.', 'feminine plural of 2691; yards;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3569G}/[H3568]', 'inflected', 'heb', 'כּוּשִׁי', '["Kûwshîy"]', '["<the>/ Cushite","the/ Cushite","the/ Cushites"]', '["a"]', 'a Cushite, or descendant of Cush Cushi, Cushite, Ethiopian(-s).', 'patronymically from 3568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3569G}/[H3568]', 'lemma', 'heb', 'כּוּשִׁי', '["Kûwshîy"]', '["Cushite","O Cushites","[the] Cushite","[the] Cushites","a Cushite"]', '["a"]', 'a Cushite, or descendant of Cush Cushi, Cushite, Ethiopian(-s).', 'patronymically from 3568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7535}/[H7534]', 'inflected', 'heb', 'רַק', '["raq"]', '["¿/ only"]', '["adv"]', 'properly, leanness, i.e. (figuratively) limitation; only adverbial, merely, or conjunctional, although but, even, except, howbeit howsoever, at the least, nevertheless, nothing but, notwithstanding, only, save, so (that), surely, yet (so), in any wise.', 'the same as 7534 as a noun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6035}/[H6041]', 'lemma', 'heb', 'עָנָו', '["ʻânâv"]', '["[the] humble [people] of","[the] poor [people] of","[was] humble","humble [people]"]', '["n-m"]', 'depressed (figuratively), in mind (gentle) or circumstances (needy, especially saintly) humble, lowly, meek, poor. Compare 6041.', 'or (by intermixture with 6041) עָנָיו; from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7969}/H9026/[H7969]', 'inflected', 'heb', 'שָׁלוֹשׁ', '["shâlôwsh"]', '["O [the] three of/ you"]', '["n"]', 'three; occasionally (ordinal) third, or (multiple) thrice fork, often(-times), third, thir(-teen, -teenth), three, thrice. Compare 7991.', 'or שָׁלֹשׁ; masculine שְׁלוֹשָׁה; or שְׁלֹשָׁה; a primitive number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7969}/H9028/[H7969]', 'inflected', 'heb', 'שָׁלוֹשׁ', '["shâlôwsh"]', '["[the] three of/ them"]', '["n"]', 'three; occasionally (ordinal) third, or (multiple) thrice fork, often(-times), third, thir(-teen, -teenth), three, thrice. Compare 7991.', 'or שָׁלֹשׁ; masculine שְׁלוֹשָׁה; or שְׁלֹשָׁה; a primitive number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4813G}/[H4805]', 'inflected', 'heb', 'מִרְיָם', '["Miryâm"]', '["and/ Miriam"]', '["n-pr-f"]', 'Mirjam, the name of two Israelitesses Miriam.', 'from 4805; rebelliously;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5030}/H9026/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["[are] prophets/ your","prophet of/ your","prophets/ your"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2420}/[H2330]', 'inflected', 'heb', 'חִידָה', '["chîydâh"]', '["by/ difficult matters","by/ riddles"]', '["n-f"]', 'a puzzle, hence, a trick, conundrum, sententious maxim dark saying (sentence, speech), hard question, proverb, riddle.', 'from 2330;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8544}/[H4327]', 'inflected', 'heb', 'תְּמוּנָה', '["tᵉmûwnâh"]', '["and/ [the] form of","and/ a form"]', '["n-f"]', 'something portioned (i.e. fashioned) out, as a shape, i.e. (indefinitely) phantom, or (specifically) embodiment, or (figuratively) manifestation (of favor) image, likeness, similitude.', 'or תְּמֻנָה; from 4327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4069}/[H4100]', 'inflected', 'heb', 'מַדּוּעַ', '["maddûwaʻ"]', '["and/ why?"]', '["adv"]', 'what (is) known?; i.e. (by implication) (adverbially) why? how, wherefore, why.', 'or מַדֻּעַ; from 4100 and the passive participle of 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5650}/H9020/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["against/ servant/ my"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6051}/[H6049]', 'inflected', 'heb', 'עָנָן', '["ʻânân"]', '["and/ the/ cloud"]', '["n-m"]', 'a cloud (as covering the sky), i.e. the nimbus or thunder-cloud cloud(-y).', 'from 6049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896J}/[H7896]', 'lemma', 'heb', 'שִׁית', '["shîyth"]', '["may put"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2973}/[H2973]', 'lemma', 'heb', 'יָאַל', '["yâʼal"]', '["they have acted foolishly","they have become fools","we have acted foolishly"]', '["v"]', 'properly, to be slack, i.e. (figuratively) to be foolish dote, be (become, do) foolish(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4191}/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["like <the>/ dead [people]","like <the>/ dead [person]","like/ a dead [person]","like/ dead [people] of","like/ dead people of"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3318M}/H9043/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ came forth/ he"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7358}/[H7355]', 'inflected', 'heb', 'רֶחֶם', '["rechem"]', '["from/ [the] womb","from/ [the] womb of"]', '["n-m"]', 'the womb matrix, womb.', 'from 7355; (compare 7356)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9034}\', 'inflected', 'heb', 'לה פ', '["La/h"]', '["<to> <the>/ her","[belonged] to <the>/ her","for <the>/ it","to/ her","to/ it"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0001G}/H9024/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ father/ her"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3417}/[H3417]', 'lemma', 'heb', 'יָרָק', '["yârâq"]', '["certainly <to spit>","he had spat"]', '["v"]', 'to spit × but, spit.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6440H}/H9024/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["in/ face/ her"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3637}/[H3637]', 'lemma', 'heb', 'כָּלַם', '["kâlam"]', '["I have been humiliated","I was humiliated","[is one who] puts to shame","[was one] putting to shame","he shames","humiliated","they are ashamed","they be humiliated","they were ashamed","they will be put to shame","to be ashamed","to exhibit shame","we were humiliated","will she be put to shame","you be ashamed","you will be put to shame"]', '["v"]', 'properly, to wound; but only figuratively, to taunt or insult be (make) ashamed, blush, be confounded, be put to confusion, hurt, reproach, (do, put to) shame.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2698}/[H2691]', 'inflected', 'heb', 'חֲצֵרוֹת', '["Chătsêrôwth"]', '["from/ Hazeroth"]', '["n-pr-loc"]', 'Chatseroth, a place in Palestine Hazeroth.', 'feminine plural of 2691; yards;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6290G}\/[H6286]', 'inflected', 'heb', 'פָּארָן', '["Pâʼrân"]', '["Paran"]', '["n-pr-loc"]', 'Paran, a desert of Arabia Paran.', 'from 6286; ornamental;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8446}/[H8446]', 'inflected', 'heb', 'תּוּר', '["tûwr"]', '["so/ they may spy out"]', '["v"]', 'to meander (causatively, guide) about, especially for trade or reconnoitring chap(-man), sent to descry, be excellent, merchant(-man), search (out), seek, (e-) spy (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8051G}/[H8074]', 'lemma', 'heb', 'שַׁמּוּעַ', '["Shammûwaʻ"]', '["Shammua"]', '["n-pr-m"]', 'Shammua, the name of four Israelites Shammua, Shammuah.', 'from 8074; renowned;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2139G}/[H2142]', 'lemma', 'heb', 'זַכּוּר', '["Zakkûwr"]', '["Zaccur"]', '["n-pr-m"]', 'Zakkur, the name of seven Israelites Zaccur, Zacchur.', 'from 2142; mindful;');
