INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2753G}/[H2752]', 'lemma', 'heb', 'חֹרִי', '["Chôrîy"]', '["Hori"]', '["n-pr-m"]', 'Chori, the name of two men Hori.', 'or חוֹרִי; the same as 2752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3612G}/[H3611]', 'lemma', 'heb', 'כָּלֵב', '["Kâlêb"]', '["Caleb"]', '["n-pr-m"]', 'Caleb, the name of three Israelites Caleb.', 'perhaps a form of 3611, or else from the same root in the sense of forcible;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3312G}/[H6437]', 'lemma', 'heb', 'יְפֻנֶּה', '["Yᵉphunneh"]', '["Jephunneh"]', '["n-pr-m"]', 'Jephunneh, the name of two Israelites Jephunneh.', 'from 6437; he will be prepared;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3008G}/[H1350]', 'lemma', 'heb', 'יִגְאָל', '["Yigʼâl"]', '["Igal"]', '["n-pr-m"]', 'Jigal, the name of three Israelites Igal, Igeal.', 'from 1350; avenger;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3130H}/[H3254]', 'lemma', 'heb', 'יוֹסֵף', '["Yôwçêph"]', '["Joseph"]', '["n-pr-m"]', 'Joseph, the name of seven Israelites Joseph. Compare 3084.', 'future of 3254; let him add (or perhaps simply active participle adding);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1954K}/[H3467]', 'lemma', 'heb', 'הוֹשֵׁעַ', '["Hôwshêaʻ"]', '["Hoshea"]', '["n-pr-m"]', 'Hoshea, the name of five Israelites Hosea, Hoshea, Oshea.', 'from 3467; deliverer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6406G}/[H6403]', 'lemma', 'heb', 'פַּלְטִי', '["Palṭîy"]', '["Palti"]', '["n-pr-m"]', 'Palti, the name of two Israelites Palti, Phalti.', 'from 6403; delivered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7505}/[H7495]', 'lemma', 'heb', 'רָפוּא', '["Râphûwʼ"]', '["Raphu"]', '["n-pr-m"]', 'Raphu, an Israelite Raphu.', 'passive participle of 7495; cured;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1427}/[H1409]', 'lemma', 'heb', 'גַּדִּיאֵל', '["Gaddîyʼêl"]', '["Gaddiel"]', '["n-pr-m"]', 'Gaddiel, an Israelite Gaddiel.', 'from 1409 and 410; fortune of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5476}/[H5475]', 'lemma', 'heb', 'סוֹדִי', '["Çôwdîy"]', '["Sodi"]', '["n-pr-m"]', 'Sodi, an Israelite Sodi.', 'from 5475; a confidant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1426}/[H1424]', 'lemma', 'heb', 'גַּדִּי', '["Gaddîy"]', '["Gaddi"]', '["n-pr-m"]', 'Gaddi, an Israelite Gaddi.', 'intensive for 1424;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5485}/[H5483]', 'lemma', 'heb', 'סוּסִי', '["Çûwçîy"]', '["Susi"]', '["n-pr-m"]', 'Susi, an Israelite Susi.', 'from 5483; horse-like;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5988G}/[H5971]', 'lemma', 'heb', 'עַמִּיאֵל', '["ʻAmmîyʼêl"]', '["Ammiel"]', '["n-pr-m"]', 'Ammiel, the name of three or four Israelites Ammiel.', 'from 5971 and 410; people of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1582}/[H1581]', 'lemma', 'heb', 'גְּמַלִּי', '["Gᵉmallîy"]', '["Gemalli"]', '["n-pr-m"]', 'Gemalli, an Israelite Gemalli.', 'probably from 1581; cameldriver;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5639}/[H5641]', 'lemma', 'heb', 'סְתוּר', '["Çᵉthûwr"]', '["Sethur"]', '["n-pr-m"]', 'Sethur, an Israelite Sethur.', 'from 5641; hidden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4317G}/[H4310]', 'lemma', 'heb', 'מִיכָאֵל', '["Mîykâʼêl"]', '["Michael"]', '["n-pr-m"]', 'Mikael, the name of an archangel and of nine Israelites Michael.', 'from 4310 and (the prefix derivative from) 3588 and 410; who (is) like God?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5147}/[H2247]', 'lemma', 'heb', 'נַחְבִּי', '["Nachbîy"]', '["Nahbi"]', '["n-pr-m"]', 'Nachbi, an Israelite Nakbi.', 'from 2247; occult;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2058}/[H3254]', 'lemma', 'heb', 'וׇפְסִי', '["Vophçîy"]', '["Vopshi"]', '["n-pr-m"]', 'Vophsi, an Israelite Vophsi.', 'probably from 3254; additional;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1345}/[H1342]', 'lemma', 'heb', 'גְּאוּאֵל', '["Gᵉʼûwʼêl"]', '["Geuel"]', '["n-pr-m"]', 'Geuel, an Israelite Geuel.', 'from 1342 and 410; majesty of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4352}/[H4134]', 'lemma', 'heb', 'מָכִי', '["Mâkîy"]', '["Maki"]', '["n-pr-m"]', 'Maki, an Israelite Machi.', 'probably from 4134; pining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1954K}/[H3467]', 'inflected', 'heb', 'הוֹשֵׁעַ', '["Hôwshêaʻ"]', '["<to>/ Hoshea"]', '["n-pr-m"]', 'Hoshea, the name of five Israelites Hosea, Hoshea, Oshea.', 'from 3467; deliverer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5045G>', 'inflected', 'heb', 'בנגב', '["ba./Ne.gev","be./Ne.gev","va./ne.Gev"]', '["[is] in/ [the] Negev","in the/ Negev","in the/ south"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2022H}/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["of the/ hill country","the/ hill country"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2389}/[H2388]', 'inflected', 'heb', 'חָזָק', '["châzâq"]', '["¿/ strong"]', '["a"]', 'strong (usu. in a bad sense, hard, bold, violent) harder, hottest, impudent, loud, mighty, sore, stiff(-hearted), strong(-er).', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7504}/[H7503]', 'inflected', 'heb', 'רָפֶה', '["râpheh"]', '["¿/ feeble"]', '["a"]', 'slack (in body or mind) weak. raphah, Raphah. See 7497, 7498. riphah. See 7383.', 'from 7503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2896A}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["¿/ [are they] good","¿/ [is it] good","¿/ [will it be] good","¿/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9003/{H4264}/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["¿/ in/ camps"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4013}/[H1219]', 'inflected', 'heb', 'מִבְצָר', '["mibtsâr"]', '["in/ fortresses"]', '["n-m"]', 'a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold).', 'also (in plural) feminine (Daniel 11:l5) מִבְצָרָה; from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H8082}/[H8080]', 'inflected', 'heb', 'שָׁמֵן', '["shâmên"]', '["¿/ fat"]', '["a"]', 'greasy, i.e. gross; figuratively, rich fat, lusty, plenteous.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7330}/[H7329]', 'lemma', 'heb', 'רָזֶה', '["râzeh"]', '["lean"]', '["a"]', 'thin lean.', 'from 7329;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8446}/[H8446]', 'inflected', 'heb', 'תּוּר', '["tûwr"]', '["and/ they caused to spy out","and/ they spied out"]', '["v"]', 'to meander (causatively, guide) about, especially for trade or reconnoitring chap(-man), sent to descry, be excellent, merchant(-man), search (out), seek, (e-) spy (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6790>', 'opaque', 'heb', 'צִן', '["Tsin"]', '["Zin"]', '["n-pr-loc"]', 'Tsin, a part of the Desert Zin.', 'from an unused root meaning to prick; a crag;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7340K}/[H7339]', 'lemma', 'heb', 'רְחֹב', '["Rᵉchôb"]', '["Rehob"]', '["n-pr-m n-pr-loc"]', 'Rechob, the name of a place in Syria, also of a Syrian and an Israelite Rehob.', 'or רְחוֹב; the same as 7339;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935H}/[H935]', 'lemma', 'heb', 'בּוֹא', '["bôwʼ"]', '["Lebo"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2574G}/[H2346]', 'lemma', 'heb', 'חֲמָת', '["Chămâth"]', '["Hamath","[is] Hamath"]', '["n-pr-loc n-pr-m"]', 'Chamath, a place in Syria Hamath, Hemath.', 'from the same as 2346; walled;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0289G}/[H251]', 'lemma', 'heb', 'אֲחִימַן', '["ʼĂchîyman"]', '["Ahiman"]', '["n-pr-m"]', 'Achiman, the name of an Anakite and of an Israelite Ahiman.', 'or אֲחִימָן ; from 251 and 4480; brother of a portion (i.e. gift);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8344}/[H8343]', 'lemma', 'heb', 'שֵׁשַׁי', '["Shêshay"]', '["Sheshai"]', '["n-pr-m"]', 'Sheshai, a Canaanite Sheshai.', 'probably for 8343;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8526G}/[H8525]', 'inflected', 'heb', 'תַּלְמַי', '["Talmay"]', '["and/ Talmai"]', '["n-pr-m"]', 'Talmai, the name of a Canaanite and a Syrian Talmai.', 'from 8525; ridged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6061}/[H6060]', 'inflected', 'heb', 'עָנָק', '["ʻÂnâq"]', '["<the>/ Anak"]', '["n-pr-m"]', 'Anak, a Canaanite Anak.', 'the same as 6060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2275A}/[H2267]', 'inflected', 'heb', 'חֶבְרוֹן', '["Chebrôwn"]', '["and/ Hebron"]', '["n-pr-loc n-pr-m"]', 'Chebron, a place in Palestine, also the name of two Israelites Hebron.', 'from 2267; seat of association;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6814}/[H6814]', 'lemma', 'heb', 'צֹעַן', '["Tsôʻan"]', '["Zoan"]', '["n-pr-loc"]', 'Tsoän, a place in Egypt Zoan.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5158H}/[H5157]', 'lemma', 'heb', 'נַחַל', '["nachal"]', '["[the] wadi of"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0812H}/[H811]', 'lemma', 'heb', 'אֶשְׁכֹּל', '["ʼEshkôl"]', '["Eshcol"]', '["n-pr"]', 'Eshcol, the name of an Amorite, also of a valley in Palestine Eshcol.', 'the same as 811;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2156}/[H2168]', 'lemma', 'heb', 'זְמוֹרָה', '["zᵉmôwrâh"]', '["a branch"]', '["n"]', 'a twig (as pruned) vine, branch, slip.', 'or זְמֹרָה (feminine); and זְמֹר (masculine); from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0811}/[H810]', 'inflected', 'heb', 'אֶשְׁכּוֹל', '["ʼeshkôwl"]', '["and/ a cluster of"]', '["n-m"]', 'a bunch of grapes or other fruit cluster (of grapes).', 'or אֶשְׁכֹּל; probably prolonged from 810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375H}/H9033/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ she lifted/ him","and/ they carried/ him","and/ they carried/ it"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4132}/[H4131]', 'inflected', 'heb', 'מוֹט', '["môwṭ"]', '["on the/ pole"]', '["n-m"]', 'a wavering, i.e. fall; by implication, a pole (as shaking); hence, a yoke (as essentially a bent pole) bar, be moved, staff, yoke.', 'from 4131;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8384}/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["the/ fig tree","the/ figs"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0811}/[H810]', 'inflected', 'heb', 'אֶשְׁכּוֹל', '["ʼeshkôwl"]', '["the/ cluster"]', '["n-m"]', 'a bunch of grapes or other fruit cluster (of grapes).', 'or אֶשְׁכֹּל; probably prolonged from 810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3772G}/[H3772]', 'lemma', 'heb', 'כָּרַת', '["kârath"]', '["cut down","he has cut down","he will be cut off","it was cut down","it was cut off","it will be cut down","it will be cut off","they cut","they cut down","they were cut off","they will cut down","we will cut","you will cut down"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8446}/[H8446]', 'inflected', 'heb', 'תּוּר', '["tûwr"]', '["from/ spying out"]', '["v"]', 'to meander (causatively, guide) about, especially for trade or reconnoitring chap(-man), sent to descry, be excellent, merchant(-man), search (out), seek, (e-) spy (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6946G}/H9011/[H6945]', 'inflected', 'heb', 'קָדֵשׁ', '["Qâdêsh"]', '["Kadesh/ towards"]', '["n-pr-loc"]', 'Kadesh, a place in the Desert Kadesh. Compare 6947.', 'the same as 6945; sanctuary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200G}/H9038/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ he saw/ them","and/ he showed/ them","and/ they showed/ them"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971G}/H9035/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["he has sent/ us","you sent/ us","you will send/ us"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0657A}/[H656]', 'lemma', 'heb', 'אֶפֶס', '["ʼepheç"]', '["[are] nothing","[the] ends of","nevertheless","no","not","nothing","only","there not"]', '["n-m"]', 'cessation, i.e. an end (especially of the earth); often used adverb, no further; also the ankle (in the dual), as being the extremity of the leg or foot ankle, but (only), end, howbeit, less than nothing, nevertheless (where), no, none (beside), not (any, -withstanding), thing of nought, save(-ing), there, uttermost part, want, without (cause).', 'from 656; (sometimes like 6466)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5892B}/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["and/ the/ cities","and/ the/ city","and/ the/ city of"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027P}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["[the] side of","[the] sides of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2013}/[H2013]', 'inflected', 'heb', 'הָסָה', '["hâçâh"]', '["and/ he silenced"]', '["v"]', 'to hush hold peace (tongue), (keep) silence, be silent, still.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3423H}/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["and/ he dispossessed","and/ he has dispossessed","and/ he will dispossess","and/ it dispossessed","and/ it took possession of","and/ it will dispossess","and/ they took possession of","and/ they will take possession of","and/ we will take possession of","and/ you took possession of","and/ you will dispossess","and/ you will take possession of"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1681}/[H1680]', 'lemma', 'heb', 'דִּבָּה', '["dibbâh"]', '["<of> [the] unfavorable report of","<the> bad report of","[the] slander of","[the] whispering of","a bad report","an evil report"]', '["n-f"]', 'slander defaming, evil report, infamy, slander.', 'from 1680 (in the sense of furtive motion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8446}/[H8446]', 'lemma', 'heb', 'תּוּר', '["tûwr"]', '["I had selected","I searched","he makes a search","it explores","they had spied out","you spied out","you will go about"]', '["v"]', 'to meander (causatively, guide) about, especially for trade or reconnoitring chap(-man), sent to descry, be excellent, merchant(-man), search (out), seek, (e-) spy (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6061}/[H6060]', 'lemma', 'heb', 'עָנָק', '["ʻÂnâq"]', '["Anak"]', '["n-pr-m"]', 'Anak, a Canaanite Anak.', 'the same as 6060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869I}/H9025/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ own eyes/ our"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H2284>', 'inflected', 'heb', 'כחגבים', '["ka./cha.ga.Vim"]', '["[are] like/ grasshoppers","like/ grasshoppers"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869I}/H9028/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ own eyes/ their","in/ view/ their"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963H>/H9028', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["sound/ their","voice/ their"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5307J}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["[is] to/ fall","to/ fall","to/ make fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0802H}/H9025/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["wives/ our"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2945}/H9025/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["and/ little one[s]/ our"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0957}/[H962]', 'inflected', 'heb', 'בַּז', '["baz"]', '["<into>/ plunder","<into>/ prey","<into>/ spoil","[becomes] <into>/ spoil","as/ spoil","into/ spoil","to/ plunder","to/ spoil"]', '["n-m"]', 'plunder booty, prey, spoil(-ed).', 'from 962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3612G}/[H3611]', 'inflected', 'heb', 'כָּלֵב', '["Kâlêb"]', '["and/ Caleb"]', '["n-pr-m"]', 'Caleb, the name of three Israelites Caleb.', 'perhaps a form of 3611, or else from the same root in the sense of forcible;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8446}/[H8446]', 'inflected', 'heb', 'תּוּר', '["tûwr"]', '["the/ merchants","those/ [who] spied out"]', '["v"]', 'to meander (causatively, guide) about, especially for trade or reconnoitring chap(-man), sent to descry, be excellent, merchant(-man), search (out), seek, (e-) spy (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899H}/H9025/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["[will be] bread/ our","bread/ our","own food/ our"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6738}/H9028/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["shade/ their"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3372G}/H9038/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["you fear/ them","you must fear/ them"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7275}/[H7263]', 'inflected', 'heb', 'רָגַם', '["râgam"]', '["to/ stone"]', '["v"]', 'to cast together (stones), i.e. to lapidate × certainly, stone.', 'a primitive root (compare 7263, 7321, 7551);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5006}/H9030/[H5006]', 'inflected', 'heb', 'נָאַץ', '["nâʼats"]', '["[those who] have spurned/ me","will they spurn/ me"]', '["v"]', 'to scorn; or (in Ecclesiastes 12:5), by interchange for 5132, to bloom abhor, (give occasion to) blaspheme, contemn, despise, flourish, × great, provoke.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3423H}/H9033/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["and/ I will dispossess/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3581B>/H9021', 'inflected', 'heb', 'בכחך', '["be./kho.cha./Kha","ve./kho.cha./Kha"]', '["by/ strength/ your","in/ strength/ your","with/ strength/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7130G}/H9023/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["from/ [the] midst/ its","from/ midst/ its"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6051}/H9021/[H6049]', 'inflected', 'heb', 'עָנָן', '["ʻânân"]', '["and/ cloud/ your"]', '["n-m"]', 'a cloud (as covering the sky), i.e. the nimbus or thunder-cloud cloud(-y).', 'from 6049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5982G}/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["and/ in/ a pillar of"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H0376G>', 'inflected', 'heb', 'כאיש', '["Ke./''ish","ke./''Ish","kha./''Ish"]', '["[is] like the/ man","[was] like/ a man of","like/ a man","like/ a man of","like/ a person"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8088B}/H9021/[H8085]', 'inflected', 'heb', 'שֵׁמַע', '["shêmaʻ"]', '["report/ your"]', '["n-m"]', 'something heard, i.e. a sound, rumor, announcement; abstractly, audience bruit, fame, hear(-ing), loud, report, speech, tidings.', 'from 8085;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1115}/[H1086]', 'inflected', 'heb', 'בִּלְתִּי', '["biltîy"]', '["<from>/ because not","from/ not"]', '["np"]', 'properly, a failure of, i.e. (used only as a negative particle, usually with a prepositional prefix) not, except, without, unless, besides, because not, until, etc. because un(satiable), beside, but, continual, except, from, lest, neither, no more, none, not, nothing, save, that no, without.', 'constructive feminine of 1086 (equivalent to 1097);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7819A}/H9038/[H7819]', 'inflected', 'heb', 'שָׁחַט', '["shâchaṭ"]', '["and/ he has slaughtered/ them","and/ he slaughtered/ them","and/ they slaughtered/ them"]', '["v n-f"]', 'to slaughter (in sacrifice or massacre) kill, offer, shoot out, slay, slaughter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3581B>', 'opaque', 'heb', 'כֹּחַ', '["kôach"]', '["[is] ability","[is] strength","[the] power of","[the] strength of","[will be] strength","ability","power","strength","strength of"]', '["n-m"]', 'vigor, literally (force, in a good or a bad sense) or figuratively (capacity, means, produce); also (from its hardiness) a large lizard ability, able, chameleon, force, fruits, might, power(-ful), strength, substance, wealth.', 'or (Daniel 11:6) כּוֹחַ; from an unused root meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5545}/[H5545]', 'lemma', 'heb', 'סָלַח', '["çâlach"]', '["I have forgiven [them]","I will forgive","forgive","he will forgive","may he forgive","to forgive","will I forgive"]', '["v"]', 'to forgive forgive, pardon, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5771G}/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["<to>/ [the] iniquity of"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1433}/[H1431]', 'inflected', 'heb', 'גֹּדֶל', '["gôdel"]', '["according to/ [the] greatness of"]', '["n-m"]', 'magnitude (literally or figuratively) greatness, stout(-ness).', 'from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4057B}/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["and/ in the/ wilderness"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5254G}/[H5254]', 'inflected', 'heb', 'נָסָה', '["nâçâh"]', '["and/ they have put to [the] test","and/ they put to [the] test"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0001G}/H9028/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["to/ ancestors/ their","to/ father/ their","to/ fathers/ their"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5650}/H9020/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["and/ servant/ my","and/ servants/ my"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6003}/[H6002]', 'inflected', 'heb', 'עֲמָלֵקִי', '["ʻĂmâlêqîy"]', '["and/ the/ Amalekite[s]"]', '["a"]', 'an Amalekite (or collectively the Amalekites) or descendants of Amalek Amalekite(-s).', 'patronymically from 6002;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6010R}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["[was] in the/ valley","in the/ valley","in the/ valley[s]","in the/ valleys","in/ [the] valley"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5488G}\/[H5488]', 'inflected', 'heb', 'סוּף', '["çûwph"]', '["reed[s]"]', '["n-m"]', 'a reed, especially the papyrus flag, Red (sea), weed. Compare 5489.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5712}/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["for the/ congregation","for/ [the] congregation of","to the/ congregation"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7451H}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<the>/ bad","<the>/ evil","<the>/ harmful","<the>/ wicked","<the>/ wicked things","<the>/ wicked women","the/ evil","the/ harm"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241H}/H9020/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["in/ ears/ my"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485A}/H9026/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["enrolled [men]/ your"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4557}/H9026/[H5608]', 'inflected', 'heb', 'מִסְפָּר', '["miçpâr"]', '["number/ your"]', '["n-m"]', 'a number, definite (arithmetical) or indefinite (large, innumerable; small, a few); also (abstractly) narration abundance, account, × all, × few, (in-) finite, (certain) number(-ed), tale, telling, time.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2945}/H9026/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["and/ little one[s]/ your"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6297}/H9026/[H6296]', 'inflected', 'heb', 'פֶּגֶר', '["peger"]', '["and/ corpses/ your"]', '["n-m"]', 'a carcase (as limp), whether of man or beast; figuratively, an idolatrous image carcase, corpse, dead body.', 'from 6296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2184}/H9026/[H2181]', 'inflected', 'heb', 'זְנוּת', '["zᵉnûwth"]', '["prostitution/ your"]', '["n-f"]', 'adultery, i.e. (figuratively) infidelity, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8141}/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["for the/ year","for/ years","of/ year","to/ two years"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771G}/H9026/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquities/ your"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8569}/H9020/[H5106]', 'inflected', 'heb', 'תְּנוּאָה', '["tᵉnûwʼâh"]', '["opposition/ my"]', '["n-f"]', 'alienation; by implication, enmity breach of promise, occasion.', 'from 5106;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3259}/[H3259]', 'inflected', 'heb', 'יָעַד', '["yâʻad"]', '["[are] the/ [ones who] have gathered","which/ gathered","which/ has gathered","who/ were gathered"]', '["v"]', 'to fix upon (by agreement or appointment); by implication, to meet (at a stated time), to summon (to trial), to direct (in a certain quarter or position), to engage (for marriage) agree,(maxke an) appoint(-ment, a time), assemble (selves), betroth, gather (selves, together), meet (together), set (a time).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3318O}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["by/ bringing out","to/ bring forth"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318O}/[H3318]', 'lemma', 'heb', 'יָצָא', '["yâtsâʼ"]', '["[who] brought out","he sends forth","it came out","it goes out","it has come out","it has gone out","it went forth","it will go forth","it will go out","sending out","they went out","will they bring forth?","you will bring forth"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4046}/[H5062]', 'inflected', 'heb', 'מַגֵּפָה', '["maggêphâh"]', '["by <the>/ plague","by the/ plague","with/ a blow"]', '["n-f"]', 'a pestilence; by analogy, defeat (× be) plague(-d), slaughter, stroke.', 'from 5062;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674D}/[H5674]', 'lemma', 'heb', 'עָבַר', '["ʻâbar"]', '["I have transgressed","I will transgress","he has transgressed","it will transgress","they have transgressed","they will transgress","transgressing"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0310A}/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["<from>/ behind","[was] <from>/ behind","from/ after","from/ behind"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6075B}/[H6075]', 'inflected', 'heb', 'עָפַל', '["ʻâphal"]', '["and/ they presumed"]', '["v"]', 'to swell; figuratively, be elated be lifted up, presume.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3807}/H9038/[H3807]', 'inflected', 'heb', 'כָּתַת', '["kâthath"]', '["and/ they scattered/ them"]', '["v"]', 'to bruise or violently strike beat (down, to pieces), break in pieces, crushed, destroy, discomfit, smite, stamp. l', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2767}\/[H2763]', 'inflected', 'heb', 'חׇרְמָה', '["Chormâh"]', '["<the>/ Hormah"]', '["n-pr-loc"]', 'Chormah, a place in Palestine Hormah.', 'from 2763; devoted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5071}/[H5068]', 'inflected', 'heb', 'נְדָבָה', '["nᵉdâbâh"]', '["<in>/ a freewill offering","in/ voluntariness"]', '["n-f"]', 'properly (abstractly) spontaneity, or (adjectively) spontaneous; also (concretely) a spontaneous or (by inference, in plural) abundant gift free(-will) offering, freely, plentiful, voluntary(-ily, offering), willing(-ly), offering).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4150H}/H9026/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["at/ appointed feasts/ your"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7243}/[H7251]', 'inflected', 'heb', 'רְבִיעִי', '["rᵉbîyʻîy"]', '["in the/ fourth [month]","with/ [the] fourth of"]', '["a"]', 'fourth; also (fractionally) a fourth foursquare, fourth (part).', 'or רְבִעִי; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5262}/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["for the/ drink offering"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0352A}/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["<to> the/ ram","and <the>/ rams","for the/ ram","for the/ rams","to the/ ram"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7992}/[H7969]', 'lemma', 'heb', 'שְׁלִישִׁי', '["shᵉlîyshîy"]', '["<the> third of","Shelishiyah","[the] third of","a third","a third [part]","third"]', '["a"]', 'third; feminine a third (part); by extension, a third (day, year or time); specifically, a third-story cell) third (part, rank, time), three (years old).', 'ordinal from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7794}/[H7788]', 'inflected', 'heb', 'שׁוֹר', '["shôwr"]', '["for the/ bull"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7716}/[H7582]', 'inflected', 'heb', 'שֶׂה', '["seh"]', '["and/ a sheep","for the/ small livestock"]', '["n-m"]', 'a member of a flock, i.e. a sheep or goat (lesser, small) cattle, ewe, goat, lamb, sheep. Compare 2089.', 'or שֵׂי; probably from 7582 through the idea of pushing out to graze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3532>', 'inflected', 'heb', 'בכבשים', '["va./ke.va.Sim"]', '["among the/ lambs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4557}/[H5608]', 'inflected', 'heb', 'מִסְפָּר', '["miçpâr"]', '["according to the/ number","according to/ [the] number of"]', '["n-m"]', 'a number, definite (arithmetical) or indefinite (large, innumerable; small, a few); also (abstractly) narration abundance, account, × all, × few, (in-) finite, (certain) number(-ed), tale, telling, time.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4557}/H9028/[H5608]', 'inflected', 'heb', 'מִסְפָּר', '["miçpâr"]', '["according to/ number/ their"]', '["n-m"]', 'a number, definite (arithmetical) or indefinite (large, innumerable; small, a few); also (abstractly) narration abundance, account, × all, × few, (in-) finite, (certain) number(-ed), tale, telling, time.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H9036}', 'inflected', 'heb', 'ככם', '["ka./Khem","kha./Khem"]', '["as <the>/ you","like / you","like <the>/ you","like/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0854}/H9036\/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["with/ you"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0398}/H9046/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["when/ eat/ you"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3899H}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["from/ [the] food of"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6182>/H9026', 'opaque', 'heb', 'עֲרִיסָה', '["ʻărîyçâh"]', '["dough<s>/ your"]', '["n-f"]', 'meal dough.', 'from an unused root meaning to comminute;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8641}/[H7311]', 'inflected', 'heb', 'תְּרוּמָה', '["tᵉrûwmâh"]', '["like/ a contribution of"]', '["n-f"]', 'a present (as offered up), especially in sacrifice or as tribute gift, heave offering (shoulder), oblation, offered(-ing).', 'or תְּרֻמָה; (Deuteronomy 12:11), from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7225G}/[H7218]', 'inflected', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["from/ [the] beginning","from/ [the] beginning of","some of/ [the] first of"]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1755}/H9026\/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["to/ generations/ your"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5869I}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["away from/ [the] eyes of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7684}/[H7683]', 'inflected', 'heb', 'שְׁגָגָה', '["shᵉgâgâh"]', '["to/ inadvertence"]', '["n-f"]', 'a mistake or inadvertent transgression error, ignorance, at unawares; unwittingly.', 'from 7683;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7684}/[H7683]', 'lemma', 'heb', 'שְׁגָגָה', '["shᵉgâgâh"]', '["[was] inadvertence"]', '["n-f"]', 'a mistake or inadvertent transgression error, ignorance, at unawares; unwittingly.', 'from 7683;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2403H}/H9028/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ sin offering/ their"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7684}/H9028/[H7683]', 'inflected', 'heb', 'שְׁגָגָה', '["shᵉgâgâh"]', '["inadvertence/ their"]', '["n-f"]', 'a mistake or inadvertent transgression error, ignorance, at unawares; unwittingly.', 'from 7683;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7684}\/[H7683]', 'inflected', 'heb', 'שְׁגָגָה', '["shᵉgâgâh"]', '["by/ inadvertence"]', '["n-f"]', 'a mistake or inadvertent transgression error, ignorance, at unawares; unwittingly.', 'from 7683;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7683}/[H7683]', 'inflected', 'heb', 'שָׁגַג', '["shâgag"]', '["who/ has gone astray"]', '["v"]', 'to stray, i.e. (figuratively) sin (with more or less apology) × also for that, deceived, err, go astray, sin ignorantly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2398}/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["by/ sin"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1442}/[H1442]', 'lemma', 'heb', 'גָּדַף', '["gâdaph"]', '["[is] blaspheming","they blasphemed","they have blasphemed"]', '["v"]', 'to hack (with words), i.e. revile blaspheme, reproach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0959}/[H959]', 'lemma', 'heb', 'בָּזָה', '["bâzâh"]', '["[he was] despised","[is] despicable","[is] despised","[is] despising","[the] [one who] despises","[who] despise","[will be] despised","a despicable [person]","despised","have we despised","have you despised","he despised","he despises","he has despised","she has despised","you despise","you despised","you have despised","you will despise"]', '["v"]', 'to disesteem despise, disdain, contemn(-ptible), think to scorn, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4687}/H9023/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["<of> commandments/ his","commandment/ his","commandments/ his"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6565A}/[H6565]', 'lemma', 'heb', 'פָּרַר', '["pârar"]', '["I will break","[who] frustrates","actually <break>","break","he broke","he has broken","he will break","it will be broken","people have broken","someone has broken","they broke","they go wrong","they have broken","will he frustrate [it]","will you annul","you annul","you break","you will break"]', '["v"]', 'to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7197A}/[H7179]', 'lemma', 'heb', 'קָשַׁשׁ', '["qâshash"]', '["[am] gathering","[was] gathering","gathering"]', '["v"]', 'to forage for straw, stubble or wood; figuratively, to assemble gather (selves) (together).', 'a primitive root; to become sapless through drought; used only as denominative from 7179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6567A}/[H6567]', 'lemma', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["it had been decided","making clear","separated"]', '["v"]', 'to separate, literally (to disperse) or figuratively (to specify); also (by implication) to wound scatter, declare, distinctly, shew, sting.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6734}/[H6731]', 'lemma', 'heb', 'צִיצִת', '["tsîytsith"]', '["[the] tassel[s] of","tassel[s]"]', '["n-f"]', 'a floral or wing-like projection, i.e. a fore-lock of hair, a tassel fringe, lock.', 'feminine of 6731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3671}/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["<the>/ wings","the/ corner"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6734}/[H6731]', 'inflected', 'heb', 'צִיצִת', '["tsîytsith"]', '["<into>/ tassel[s]"]', '["n-f"]', 'a floral or wing-like projection, i.e. a fore-lock of hair, a tassel fringe, lock.', 'feminine of 6731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3824}/H9026/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["heart/ your","own heart/ your"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1885>', 'inflected', 'heb', 'ודתן', '["ve./da.Tan"]', '["and/ Dathan"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0048G}/[H1]', 'inflected', 'heb', 'אֲבִירָם', '["ʼĂbîyrâm"]', '["and/ Abiram"]', '["n-pr-m"]', 'Abiram, the name of two Israelites Abiram.', 'from 1 and 7311; father of height (i.e. lofty);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0446H}/[H410]', 'lemma', 'heb', 'אֱלִיאָב', '["ʼĔlîyʼâb"]', '["Eliab"]', '["n-pr-m"]', 'Eliab, the name of six Israelites Eliab.', 'from 410 and 1; God of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0203}/[H202]', 'inflected', 'heb', 'אוֹן', '["ʼÔwn"]', '["and/ On"]', '["n-pr-m"]', 'On, an Israelite On.', 'the same as 202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6431G>', 'opaque', 'heb', 'פֶּלֶת', '["Peleth"]', '["Peleth"]', '["n-pr-m"]', 'Peleth, the name of two Israelites Peleth.', 'from an unused root meaning to flee; swiftness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7148}/[H7121]', 'lemma', 'heb', 'קָרִיא', '["qârîyʼ"]', '["[the] [people] called of","called of"]', '["a"]', 'called, i.e. select famous, renowned.', 'from 7121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H8432>/H9028', 'inflected', 'heb', 'ובתוכם', '["u./ve./to.Kha/m"]', '["and/ [is] among/ midst of/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375L}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["[was] exalted","[was] exalting himself","do you exalt yourselves","he had exalted","he lifted up","it will exalt itself"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5712}/H9023/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["company/ his"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6918G}/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["<the>/ holy","the/ holy [person]"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4289}/[H4288]', 'lemma', 'heb', 'מַחְתָּה', '["machtâh"]', '["[the] censers of","censers"]', '["n-f"]', 'a pan for live coals censer, firepan, snuffdish.', 'the same as 4288 in the sense of removal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6918H}/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["[will be] the/ holy [person]"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5975G}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ by/ establishing","and/ to/ make a stand","and/ to/ stand"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8334}/H9038/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["to/ serve/ them"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251H}/H9021/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["brothers/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5712}/H9021/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["company/ your","congregation/ your"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1885>', 'inflected', 'heb', 'לדתן', '["le./da.Tan"]', '["<to>/ Dathan","to/ Dathan"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0048G}/[H1]', 'inflected', 'heb', 'אֲבִירָם', '["ʼĂbîyrâm"]', '["and/ <to>/ Abiram","and/ to/ Abiram"]', '["n-pr-m"]', 'Abiram, the name of two Israelites Abiram.', 'from 1 and 7311; father of height (i.e. lofty);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4191}/H9035/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["to/ kill/ us"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8323A}/[H8323]', 'lemma', 'heb', 'שָׂרַר', '["sârar"]', '["really <make yourself ruler>","ruler","they rule","they will rule","you will make yourself ruler"]', '["v"]', 'to have (transitively, exercise; reflexively, get) dominion × altogether, make self a prince, (bear) rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935P}/H9035/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["you have brought/ us"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5159}/[H5157]', 'lemma', 'heb', 'נַחֲלָה', '["nachălâh"]', '["[are] an inheritance of","[is] [the] inheritance of","[the] inheritance","[the] inheritance of","[was] [the] inheritance of","an inheritance","an inheritance of","inheritance","inheritances"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3754>', 'inflected', 'heb', 'וכרמים', '["u./khe.ra.Mim","va./Kha.rem","ve./Khe.rem"]', '["and/ [the] vineyard of","and/ a vineyard","and/ vineyard","and/ vineyards"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5869A}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["¿/ [do] eyes of","¿/ [the] eyes of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5365}/[H5365]', 'lemma', 'heb', 'נָקַר', '["nâqar"]', '["[which] you were dug out","he has pierced","will you put out"]', '["v"]', 'to bore (penetrate, quarry) dig, pick out, pierce, put (thrust) out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4503G>/H9028', 'opaque', 'heb', 'מִנְחָה', '["minchâh"]', '["grain offering/ their","offering/ their"]', '["n-f"]', 'a donation; euphemistically, tribute; specifically a sacrificial offering (usually bloodless and voluntary) gift, oblation, (meat) offering, present, sacrifice.', 'from an unused root meaning to apportion, i.e. bestow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5712}\/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["the/ congregation"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3615H}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["so/ I may consume","so/ I may make an end of"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7281}/[H7280]', 'inflected', 'heb', 'רֶגַע', '["regaʻ"]', '["like/ a moment"]', '["n-m"]', 'a wink (of the eyes), i.e. a very short space of time instant, moment, space, suddenly.', 'from 7280.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/<H0376G>', 'inflected', 'heb', 'האיש', '["ha./''Ish"]', '["¿/ a man"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7107}\/[H7107]', 'inflected', 'heb', 'קָצַף', '["qâtsaph"]', '["will you be angry?"]', '["v"]', 'to crack off, i.e. (figuratively) burst out in rage (be) anger(-ry), displease, fret self, (provoke to) wrath (come), be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5439G}/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["[are] from/ round about","from/ all around","from/ round about"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1885>', 'opaque', 'heb', 'דָּתָן', '["Dâthân"]', '["Dathan","[was the] Dathan"]', '["n-pr-m"]', 'Dathan, an Israelite Dathan.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0168G}/H9028/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["tents/ their"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0802H}/H9028/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ wives/ their"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121A}/H9028/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ children/ their","and/ descendants/ their","and/ sons/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2945}/H9028/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["and/ little one[s]/ their"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3820A}/H9020/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["from/ own heart/ my"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4194}/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["[is] like <the>/ death","like <the>/ death","like/ [the] death of","when/ died"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1278}/[H1254]', 'lemma', 'heb', 'בְּרִיאָה', '["bᵉrîyʼâh"]', '["a creation"]', '["n-f"]', 'a creation, i.e. a novelty new thing.', 'feminine from 1254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6475}/[H6475]', 'inflected', 'heb', 'פָּצָה', '["pâtsâh"]', '["and/ it will open"]', '["v"]', 'to rend, i.e. open (especially the mouth) deliver, gape, open, rid, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5006}/[H5006]', 'lemma', 'heb', 'נָאַץ', '["nâʼats"]', '["[is] reviled","has he spurned","he spurns","indeed <declare contemptible>","it spurned","they had spurned","they have spurned","they spurned","they treated with contempt","will he spurn?","you have declared contemptible","you spurn"]', '["v"]', 'to scorn; or (in Ecclesiastes 12:5), by interchange for 5132, to bloom abhor, (give occasion to) blaspheme, contemn, despise, flourish, × great, provoke.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478G}/H9038/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["[was] under/ them","under/ them"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004M}/H9028/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["households/ their","houses/ their"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7141I}/[H7139]', 'inflected', 'heb', 'קֹרַח', '["Qôrach"]', '["[belonged] to/ Korah"]', '["n-pr-m"]', 'Korach, the name of two Edomites and three Israelites Korah.', 'from 7139; ice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6963A>/H9028', 'inflected', 'heb', 'לקלם', '["le./ko.La/m"]', '["to/ voice/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1104}/H9035/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["it should swallow/ us","they had swallowed up/ us"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7004}\/[H6999]', 'inflected', 'heb', 'קְטֹרֶת', '["qᵉṭôreth"]', '["<of> the/ incense"]', '["n-f"]', 'a fumigation (sweet) incense, perfume.', 'from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7311A}/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["and/ I have raised","and/ [is] exalted","and/ [may it] be exalted","and/ [the one who] lifts up","and/ [the] exalted [ones] of","and/ he may be high","and/ he will exalt","and/ it will be lifted up","and/ lofty","and/ lofty [thing]","and/ may he be exalted","and/ take up","and/ to lift off","so/ he may exalt himself","so/ let us exalt","so/ may he take up"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2400}/[H2398]', 'inflected', 'heb', 'חַטָּא', '["chaṭṭâʼ"]', '["<the>/ sinful","the/ sinners"]', '["n-m"]', 'a criminal, or one accounted guilty offender, sinful, sinner.', 'intensively from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315H}/H9028/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["by/ lives/ their","with/ lives/ their"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7555}/[H7554]', 'lemma', 'heb', 'רִקֻּעַ', '["riqquaʻ"]', '["beaten out of"]', '["n-m"]', 'beaten out, i.e. a (metallic) plate broad.', 'from 7554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6826}/[H6823]', 'lemma', 'heb', 'צִפּוּי', '["tsippûwy"]', '["[the] plating of","overlay"]', '["n-m"]', 'encasement (with metal) covering, overlaying.', 'from 6823;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7126H}/H9038/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["they brought near/ them"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8313}/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["the/ [ones who] were burned"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7554}/H9038/[H7554]', 'inflected', 'heb', 'רָקַע', '["râqaʻ"]', '["and/ people beat out/ them"]', '["v"]', 'to pound the earth (as a sign of passion); by analogy to expand (by hammering); by implication, to overlay (with thin sheets of metal) beat, make broad, spread abroad (forth, over, out, into plates), stamp, stretch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7141I}/[H7139]', 'inflected', 'heb', 'קֹרַח', '["Qôrach"]', '["like/ Korah"]', '["n-pr-m"]', 'Korach, the name of two Edomites and three Israelites Korah.', 'from 7139; ice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5712}/H9023/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["and/ like/ company/ his"]', '["n-f"]', 'a stated assemblage (specifically, a concourse, or generally, a family or crowd) assembly, company, congregation, multitude, people, swarm. Compare 5713.', 'feminine of 5707 in the original sense of fixture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6950}/[H6950]', 'inflected', 'heb', 'קָהַל', '["qâhal"]', '["when/ assembled"]', '["v"]', 'to convoke assemble (selves) (together), gather (selves) (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7426}/[H7426]', 'lemma', 'heb', 'רָמַם', '["râmam"]', '["[is] exalting","get away","they are exalted","they rose"]', '["v"]', 'to rise (literally or figuratively) exalt, get (oneself) up, lift up (self), mount up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1980J}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ take [it]","so/ let me lead"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4120}/[H4118]', 'lemma', 'heb', 'מְהֵרָה', '["mᵉhêrâh"]', '["quickly"]', '["n-f"]', 'properly, a hurry; hence (adverbially) promptly hastily, quickly, shortly, soon, make (with) speed(-ily), swiftly.', 'feminine of 4118;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7110A}/[H7107]', 'inflected', 'heb', 'קֶצֶף', '["qetseph"]', '["<the>/ wrath"]', '["n-m"]', 'a splinter (as chipped off); figuratively, rage or strife foam, indignation, × sore, wrath.', 'from 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5063}/[H5062]', 'inflected', 'heb', 'נֶגֶף', '["negeph"]', '["the/ plague"]', '["n-m"]', 'a trip (of the foot); figuratively, an infliction (of disease) plague, stumbling.', 'from 5062;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6113}/[H6113]', 'inflected', 'heb', 'עָצָר', '["ʻâtsâr"]', '["and/ do I restrain?","and/ he will shut up","and/ it was restrained"]', '["v"]', 'to inclose; by analogy, to hold back; also to maintain, rule, assemble × be able, close up, detain, fast, keep (self close, still), prevail, recover, refrain, × reign, restrain, retain, shut (up), slack, stay, stop, withhold (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4046}/[H5062]', 'inflected', 'heb', 'מַגֵּפָה', '["maggêphâh"]', '["the/ plague","the/ slaughter"]', '["n-f"]', 'a pestilence; by analogy, defeat (× be) plague(-d), slaughter, stroke.', 'from 5062;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4046}/[H5062]', 'inflected', 'heb', 'מַגֵּפָה', '["maggêphâh"]', '["and/ the/ plague"]', '["n-f"]', 'a pestilence; by analogy, defeat (× be) plague(-d), slaughter, stroke.', 'from 5062;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6113}\/[H6113]', 'inflected', 'heb', 'עָצָר', '["ʻâtsâr"]', '["it had been restrained"]', '["v"]', 'to inclose; by analogy, to hold back; also to maintain, rule, assemble × be able, close up, detain, fast, keep (self close, still), prevail, recover, refrain, × reign, restrain, retain, shut (up), slack, stay, stop, withhold (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5387A}/H9028/[H5375]', 'inflected', 'heb', 'נָשִׂיא', '["nâsîyʼ"]', '["leaders/ their"]', '["n-m"]', 'properly, an exalted one, i.e. a king or sheik; also a rising mist captain, chief, cloud, governor, prince, ruler, vapour.', 'or נָשִׂא; from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7218H>', 'inflected', 'heb', 'לראשי', '["la./Rosh","le./Rosh","le./ra.Shei","le./roSh"]', '["<into>/ [the] head","<into>/ a chief","<into>/ a head","<into>/ chief","[is] for/ [the] head of","into/ chief","to the/ chief","to/ [the] chiefs of","to/ [the] head of","to/ chief","to/ head"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5387A}/[H5375]', 'inflected', 'heb', 'נָשִׂיא', '["nâsîyʼ"]', '["[will belong] to the/ prince","for the/ prince","for/ a leader","to the/ prince"]', '["n-m"]', 'properly, an exalted one, i.e. a king or sheik; also a rising mist captain, chief, cloud, governor, prince, ruler, vapour.', 'or נָשִׂא; from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6525}/[H6524]', 'lemma', 'heb', 'פֶּרַח', '["perach"]', '["[the] blossom of","bud[s]"]', '["n-m"]', 'a calyx (natural or artificial); generally, bloom blossom, bud, flower.', 'from 6524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6692A}/[H6692]', 'inflected', 'heb', 'צוּץ', '["tsûwts"]', '["and/ it had blossomed","and/ they blossomed"]', '["v"]', 'to twinkle, i.e. glance; by analogy, to blossom (figuratively, flourish) bloom, blossom, flourish, shew self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8247}/[H8245]', 'lemma', 'heb', 'שָׁקֵד', '["shâqêd"]', '["almonds","an almond tree"]', '["n-m"]', 'the almond (tree or nut; as being the earliest in bloom) almond (tree).', 'from 8245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4294G}/H9023\/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["rod/ his"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121H}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["for/ [the] sons of","to/ [the] young ones of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4805H}/[H4784]', 'lemma', 'heb', 'מְרִי', '["mᵉrîy"]', '["[are] rebellious","[the] rebellion of","rebellion","rebellious"]', '["n-m"]', 'bitterness, i.e. (figuratively) rebellion; concretely, bitter, or rebellious bitter, (most) rebel(-lion, -lious).', 'from 4784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3615G}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["and/ ending","and/ may you put an end to","so/ they may complete"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8519}/H9028/[H3885]', 'inflected', 'heb', 'תְּלוּנָה', '["tᵉlûwnâh"]', '["grumblings/ their"]', '["n-f"]', 'a grumbling murmuring.', 'or תּלֻנָּה; from 3885 in the sense of obstinacy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0518H}/[H518]', 'inflected', 'heb', 'אִם', '["ʼim"]', '["¿/ if","¿/ or"]', '["prt"]', 'used very widely as demonstrative, lo!; interrogative, whether?; or conditional, if, although; also Oh that!, when; hence, as a negative, not (and, can-, doubtless, if, that) (not), + but, either, + except, + more(-over if, than), neither, nevertheless, nor, oh that, or, + save (only, -ing), seeing, since, sith, + surely (no more, none, not), though, + of a truth, + unless, + verily, when, whereas, whether, while, + yet.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1478}\/[H1478]', 'inflected', 'heb', 'גָּוַע', '["gâvaʻ"]', '["to/ die"]', '["v"]', 'to breathe out, i.e. (by implication) expire die, be dead, give up the ghost, perish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3550}/H9026/[H3547]', 'inflected', 'heb', 'כְּהֻנָּה', '["kᵉhunnâh"]', '["priesthood/ your"]', '["n-f"]', 'priesthood priesthood, priest''s office.', 'from 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3867A}/[H3867]', 'inflected', 'heb', 'לָוָה', '["lâvâh"]', '["so/ they may join themselves"]', '["v"]', 'properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8334}/H9031/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["so/ they may serve/ you"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4931}/H9021/[H4929]', 'inflected', 'heb', 'מִשְׁמֶרֶת', '["mishmereth"]', '["service/ your"]', '["n-f"]', 'watch, i.e. the act (custody), or (concretely) the sentry, the post; objectively preservation, or (concretely) safe; figuratively observance, i.e. (abstractly) duty or (objectively) a usage or party charge, keep, or to be kept, office, ordinace, safeguard, ward, watch.', 'feminine of 4929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3867A}/[H3867]', 'inflected', 'heb', 'לָוָה', '["lâvâh"]', '["and/ he will join himself","and/ they will join themselves"]', '["v"]', 'properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251H}/H9026/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["[is] brother/ your","brothers/ your","countrymen/ your","relatives/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/H9006/{H1004O}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ to/ from/ inside"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414G}/H9038/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["I give/ them","I have given/ them","he gave/ them","he has given/ them","he will deliver up/ them","to give/ them"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4888B}/[H4886]', 'inflected', 'heb', 'מִשְׁחָה', '["mishchâh"]', '["to/ a portion"]', '["n-f"]', 'unction (the act); by implication, a consecratory gift (to be) anointed(-ing), ointment.', 'or מׇשְׁחָה; from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403H}/H9028/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sin offering/ their"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0817}/H9028/[H816]', 'inflected', 'heb', 'אָשָׁם', '["ʼâshâm"]', '["guilt offering/ their"]', '["n-m"]', 'guilt; by implication, a fault; also a sin-offering guiltiness, (offering for) sin, trespass (offering).', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4976}/H9028/[H5414]', 'inflected', 'heb', 'מַתָּן', '["mattân"]', '["gift/ their"]', '["n-m"]', 'a present gift, to give, reward.', 'from 5414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1323G}/H9021/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ to/ daughters/ your"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3323}/[H6671]', 'lemma', 'heb', 'יִצְהָר', '["yitshâr"]', '["[the] fresh oil","fresh oil"]', '["n-m"]', 'oil (as producing light); figuratively, anointing anointed oil.', 'from 6671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8492}/[H3423]', 'lemma', 'heb', 'תִּירוֹשׁ', '["tîyrôwsh"]', '["[the] new wine","new wine"]', '["n-m"]', 'must or fresh grape-juice (as just squeezed out); by implication (rarely) fermented wine (new, sweet) wine.', 'or תִּירֹשׁ; from 3423 in the sense of expulsion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7225G}/H9028/[H7218]', 'inflected', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["first [fruit]/ their"]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6299}/H9023/[H6299]', 'inflected', 'heb', 'פָּדָה', '["pâdâh"]', '["and/ redemption price/ its"]', '["v"]', 'to sever, i.e. ransom; generally to release, preserve × at all, deliver, × by any means, ransom, (that are to be, let be) redeem(-ed), rescue, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2459>/H9028', 'opaque', 'heb', 'חֶלֶב', '["cheleb"]', '["fat/ their"]', '["n-m"]', 'fat, whether literally or figuratively; hence, the richest or choice part × best, fat(-ness), × finest, grease, marrow.', 'or חֵלֶב; from an unused root meaning to be fat;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1320}/H9028/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["and/ meat/ their"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2373}/[H2372]', 'inflected', 'heb', 'חָזֶה', '["châzeh"]', '["like/ [the] breast of"]', '["n-m"]', 'the breast (as most seen in front) breast.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7785}/[H7783]', 'inflected', 'heb', 'שׁוֹק', '["shôwq"]', '["and/ like/ [the] thigh of"]', '["n-f"]', 'the (lower) leg (as a runner) hip, leg, shoulder, thigh.', 'from 7783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5157}/[H5157]', 'lemma', 'heb', 'נָחַל', '["nâchal"]', '["I gave as an inheritance","I have been allotted","I have inherited","[is] giving as an inheritance","have inherited","he gave as a possession","he leaves an inheritance to","he will cause to inherit","he will give as an inheritance","he will inherit","they gave as a possession","they inherit","they inherited","they possessed","they will give as inheritance","they will inherit","we will inherit","you have an inheritance","you will cause to inherit","you will give as possession","you will have an inheritance","you will inherit"]', '["v"]', 'to inherit (as a (figurative) mode of descent), or (generally) to occupy; causatively, to bequeath, or (generally) distribute, instate divide, have (inheritance), take as a heritage, (cause to, give to, make to) inherit, (distribute for, divide (for, for an, by), give for, have, leave for, take (for)) inheritance, (have in, cause to, be made to) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2506A}/H9021/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["[am] share/ your","[is] portion/ your","portion/ your"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5159}/H9021/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["and/ inheritance/ your"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1121G}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ [belonged] to/ [the] descendants of","and/ for/ [the] people of","and/ to/ [the] descendants of","and/ to/ [the] sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5159}/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["<into>/ an inheritance","for/ an inheritance","to/ [the] inheritance of","to/ an inheritance"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2500}/[H2498]', 'lemma', 'heb', 'חֵלֶף', '["chêleph"]', '["in return for"]', '["n-m"]', 'properly, exchange; hence (as preposition) instead of × for.', 'from 2498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5159}\/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["an inheritance"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4643}/[H6240]', 'inflected', 'heb', 'מַעֲשֵׂר', '["maʻăsêr"]', '["the/ tithe"]', '["n-m"]', 'a tenth; especially a tithe tenth (part), tithe(-ing).', 'or מַעֲשַׂר; and (in plural) feminine מַעַשְׂרָה; from 6240;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5159}/H9026/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["<in>/ inheritance/ your"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8641}/H9026/[H7311]', 'inflected', 'heb', 'תְּרוּמָה', '["tᵉrûwmâh"]', '["contribution/ your","contributions/ your"]', '["n-f"]', 'a present (as offered up), especially in sacrifice or as tribute gift, heave offering (shoulder), oblation, offered(-ing).', 'or תְּרֻמָה; (Deuteronomy 12:11), from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1715}/[H1711]', 'inflected', 'heb', 'דָּגָן', '["dâgân"]', '["like the/ grain"]', '["n-m"]', 'properly, increase, i.e. grain corn (floor), wheat.', 'from 1711;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1637>', 'inflected', 'heb', 'הגרנות', '["ha./Go.ren","ha./go.ra.Not"]', '["the/ threshing floor","the/ threshing floors"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4395}/[H4392]', 'inflected', 'heb', 'מְלֵאָה', '["mᵉlêʼâh"]', '["and/ like the/ full produce"]', '["n-f"]', 'something fulfilled, i.e. abundance (of produce) (first of ripe) fruit, fulness.', 'feminine of 4392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3342>', 'inflected', 'heb', 'היקב', '["hai./Ya.kev","hai./Ye.kev"]', '["the/ wine vat","the/ wine-press"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4643}/H9026/[H6240]', 'inflected', 'heb', 'מַעֲשֵׂר', '["maʻăsêr"]', '["tithes/ your"]', '["n-m"]', 'a tenth; especially a tithe tenth (part), tithe(-ing).', 'or מַעֲשַׂר; and (in plural) feminine מַעַשְׂרָה; from 6240;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4720}/H9023/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["sacred part of/ its","sanctuary/ his","sanctuary/ its"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7311A}/H9046/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["when/ offer up/ you"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8393}/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["like/ [the] produce of"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H8393}/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["and/ like/ [the] produce of"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3342>', 'opaque', 'heb', 'יֶקֶב', '["yeqeb"]', '["[the] wine-presses of","a wine-press","a wine-vat","wine-presses"]', '["n-m"]', 'a trough (as dug out); specifically, a wine-vat (whether the lower one, into which the juice drains; or the upper, in which the grapes are crushed) fats, presses, press-fat, wine(-press).', 'from an unused root meaning to excavate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004M}/H9026/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ household/ your","and/ households/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7939}/[H7936]', 'lemma', 'heb', 'שָׂכָר', '["sâkâr"]', '["<of> [the] hire of","[is] a reward","[is] reward","[is] wage[s]","[the] hire of","[the] wage[s] of","[will be] a reward","a reward","wage[s]"]', '["n-m"]', 'payment of contract; concretely, salary, fare, maintenance; by implication, compensation, benefit hire, price, reward(-ed), wages, worth.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5656H}/H9026/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["service/ your"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0122A}/[H119]', 'lemma', 'heb', 'אָדֹם', '["ʼâdôm"]', '["[does] redness","red"]', '["a n-m"]', 'rosy red, ruddy.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5923}/[H5953]', 'lemma', 'heb', 'עֹל', '["ʻôl"]', '["<of> a yoke","[the] yoke","[the] yoke of","a yoke","a yoke of"]', '["n-m"]', 'a yoke (as imposed on the neck), literally or figuratively yoke.', 'or עוֹל; from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869H}/H9023/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ his"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5785}/H9024/[H5783]', 'inflected', 'heb', 'עוֹר', '["ʻôwr"]', '["skin/ its"]', '["n-m"]', 'skin (as naked); by implication, hide, leather hide, leather, skin.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1320}/H9024/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["flesh/ its"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6569}/H9024/[H6567]', 'inflected', 'heb', 'פֶּרֶשׁ', '["peresh"]', '["offal/ its"]', '["n-m"]', 'excrement (as eliminated) dung.', 'from 6567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8316}/[H8313]', 'lemma', 'heb', 'שְׂרֵפָה', '["sᵉrêphâh"]', '["[the] burning of","a burning","a burning waste","burning"]', '["n-f"]', 'cremation burning.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0665>', 'opaque', 'heb', 'אֵפֶר', '["ʼêpher"]', '["[the] ash[es] of","ash[es]"]', '["n-m"]', 'ashes ashes.', 'from an unused root meaning to bestrew;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0622}/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["the/ [one who] gathers"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4191}/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["<in> the/ dead [body]","<in>/ a dead [body]","among the/ dead","when/ died"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315M}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["<in>/ [the] corpse of"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6781B}/[H6775]', 'lemma', 'heb', 'צָמִיד', '["tsâmîyd"]', '["[is] a cover of"]', '["n-m"]', 'a bracelet or arm-clasp; generally, a lid bracelet, covering.', 'or צָמִד; from 6775;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2491A}/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["<in> the/ [one] slain","<in>/ [one] slain of"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6106G}/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["<in> the/ bone","<in>/ [the] bones of","<in>/ a bone of","with/ limb[s] of"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6913}/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["<in> the/ grave","<in>/ a grave","among the/ graves","in the/ grave","in/ [the] grave of","in/ [the] graves of","in/ [the] tomb of"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6083}/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["from/ [the] dust","some of/ [the] dust of"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5137A}/[H5137]', 'inflected', 'heb', 'נָזָה', '["nâzâh"]', '["and/ [the] [one who] spatters","and/ it spattered"]', '["v"]', 'to spirt, i.e. besprinkle (especially in expiation) sprinkle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5079}/[H5074]', 'inflected', 'heb', 'נִדָּה', '["niddâh"]', '["<the>/ impurity","<the>/ menstruation","the/ impurity","the/ menstruation"]', '["n-f"]', 'properly, rejection; by implication, impurity, especially personal (menstruation) or moral (idolatry, incest) × far, filthiness, × flowers, menstruous (woman), put apart, × removed (woman), separation, set apart, unclean(-ness, thing, with filthiness).', 'from 5074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6946G}/[H6945]', 'inflected', 'heb', 'קָדֵשׁ', '["Qâdêsh"]', '["[are] in/ Kadesh","at/ Kadesh","in/ Kadesh"]', '["n-pr-loc"]', 'Kadesh, a place in the Desert Kadesh. Compare 6947.', 'the same as 6945; sanctuary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3863}/[H3863]', 'inflected', 'heb', 'לוּא', '["lûwʼ"]', '["and/ if"]', '["conj"]', 'a conditional particle; if; by implication (interj. as a wish) would that! if (haply), peradventure, I pray thee, though, I would, would God (that).', 'or לֻא; or לוּ;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1478}/[H1478]', 'inflected', 'heb', 'גָּוַע', '["gâvaʻ"]', '["when/ died"]', '["v"]', 'to breathe out, i.e. (by implication) expire die, be dead, give up the ghost, perish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251I}/H9025/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["brothers/ our","countrymen/ our","relatives/ our"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1165}/H9025/[H1197]', 'inflected', 'heb', 'בְּעִיר', '["bᵉʻîyr"]', '["and/ livestock/ our"]', '["n-m"]', 'cattle beast, cattle.', 'from 1197 (in the sense of eating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927G}/H9035/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["have you brought up/ us"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8384}/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["and/ fig tree","and/ figs"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1612>', 'inflected', 'heb', 'וגפן', '["ve./Ge.fen"]', '["and/ vine"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6950}/[H6950]', 'inflected', 'heb', 'קָהַל', '["qâhal"]', '["and/ assemble","so/ he may summon an assembly"]', '["v"]', 'to convoke assemble (selves) (together), gather (selves) (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5553H>', 'inflected', 'heb', 'הסלעים', '["ha./Sa.la''","ha./Se.la''","ha./se.la.''Im"]', '["the/ cliffs","the/ crags","the/ rock","the/ rocks"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869A}/H9028/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ their"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4325G}/H9023/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["water/ his","water/ its","waters/ his","waters/ its"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1165}/H9028/[H1197]', 'inflected', 'heb', 'בְּעִיר', '["bᵉʻîyr"]', '["cattle/ their","livestock/ their"]', '["n-m"]', 'cattle beast, cattle.', 'from 1197 (in the sense of eating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4784}/[H4784]', 'inflected', 'heb', 'מָרָה', '["mârâh"]', '["O/ rebels"]', '["v"]', 'to be (causatively, make) bitter (or unpleasant); (figuratively) to rebel (or resist; causatively, to provoke) bitter, change, be disobedient, disobey, grievously, provocation, provoke(-ing), (be) rebel (against, -lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1165}/H9028\/[H1197]', 'inflected', 'heb', 'בְּעִיר', '["bᵉʻîyr"]', '["and/ livestock/ their"]', '["n-m"]', 'cattle beast, cattle.', 'from 1197 (in the sense of eating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6942G}/H9030/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["to/ treat as holy/ me"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4809H}/[H4808]', 'lemma', 'heb', 'מְרִיבָה', '["Mᵉrîybâh"]', '["Meribah","Meribath"]', '["n-pr-loc"]', 'Meribah, the name of two places in the Desert Meribah.', 'the same as 4808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6946G}/[H6945]', 'inflected', 'heb', 'קָדֵשׁ', '["Qâdêsh"]', '["from/ Kadesh"]', '["n-pr-loc"]', 'Kadesh, a place in the Desert Kadesh. Compare 6947.', 'the same as 6945; sanctuary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4672}/H9035/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["has it found/ us","it has come upon/ us"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0001G}/H9025/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ to/ ancestors/ our"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963A>/H9025', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["voice/ our"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318H}/H9035/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ he brought out/ us","and/ you have brought out/ us"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H3754>', 'inflected', 'heb', 'ובכרמים', '["u./va./ke.ra.Mim","u./ve./Khe.rem"]', '["and/ in the/ vineyards","and/ in/ a vineyard"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870I}/[H1869]', 'lemma', 'heb', 'דֶּרֶךְ', '["derek"]', '["[the] way of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4428I}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["the/ king"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8040G}/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["and/ left","and/ left [hand]"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122H}/H9031/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ you"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4546}/[H5549]', 'inflected', 'heb', 'מְסִלָּה', '["mᵉçillâh"]', '["[is] on/ [the] highway of","in the/ highways","on the/ highway","on/ [the] highway of","on/ a highway"]', '["n-f"]', 'a thoroughfare (as turnpiked), literally or figuratively; specifically a viaduct, a staircase causeway, course, highway, path, terrace.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4735}/H9020/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["and/ livestock/ my"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414P}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will give","and/ he made"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4377}/H9028/[H4376]', 'inflected', 'heb', 'מֶכֶר', '["meker"]', '["price/ their"]', '["n-m"]', 'merchandise; also value pay, price, ware.', 'from 4376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7272}/H9020/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["[is] at/ feet/ my","on/ feet/ my"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5971K}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["with/ a people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1366H}/H9023/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["in/ territory/ his","in/ territory/ its"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5921A}/H9033\/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["from/ on <the>/ it"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2023G}/[H2022]', 'lemma', 'heb', 'הֹר', '["Hôr"]', '["Hor"]', '["n-pr-loc"]', 'Hor, the name of a peak in Idumaea and of one in Syria Hor.', 'another form of 2022; mountain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2023G}/[H2022]', 'inflected', 'heb', 'הֹר', '["Hôr"]', '["at/ Hor","on/ Hor"]', '["n-pr-loc"]', 'Hor, the name of a peak in Idumaea and of one in Syria Hor.', 'another form of 2022; mountain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366G}/[H1379]', 'lemma', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["<of> a boundary","[is the] border of","[is the] boundary","[is] [the] border of","[is] [the] boundary of","[the] border","[the] border of","[the] boundary","[the] boundary of","[the] territory of","[was] [the] border of","a barrier","a boundary","a boundary of","border of"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4784}/[H4784]', 'lemma', 'heb', 'מָרָה', '["mârâh"]', '["I have been rebellious","extremely <be rebellious>","he was disobedient to","he will rebel toward","it has been rebellious against","it has rebelled","it was bitter","rebelling","rebellious","they had rebelled against","they have rebelled","they rebelled","they rebelled against","they rebelled toward","you have been disobedient to","you rebelled against","you will rebel against"]', '["v"]', 'to be (causatively, make) bitter (or unpleasant); (figuratively) to rebel (or resist; causatively, to provoke) bitter, change, be disobedient, disobey, grievously, provocation, provoke(-ing), (be) rebel (against, -lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310I}/H9020/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["mouth/ my"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5927H}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ [am] about to bring up","and/ bring up","and/ he will bring up","so/ they may bring up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6584}/[H6584]', 'inflected', 'heb', 'פָּשַׁט', '["pâshaṭ"]', '["and/ strip off"]', '["v"]', 'to spread out (i.e. deploy in hostile array); by analogy, to strip (i.e. unclothe, plunder, flay, etc.) fall upon, flay, invade, make an invasion, pull off, put off, make a road, run upon, rush, set, spoil, spread selves (abroad), strip (off, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6166A>', 'opaque', 'heb', 'עֲרָד', '["ʻĂrâd"]', '["Arad"]', '["n-pr-loc"]', 'Arad, the name of a place near Palestine, also of a Canaanite and an Israelite Arad.', 'from an unused root meaning to sequester itself; fugitive;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0871>', 'inflected', 'heb', 'האתרים', '["ha./''a.ta.Rim"]', '["the/ Atharim"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7617}/[H7617]', 'inflected', 'heb', 'שָׁבָה', '["shâbâh"]', '["and/ he took captive","and/ they had taken captive","and/ they took captive","and/ you will take captive"]', '["v"]', 'to transport into captivity (bring away, carry, carry away, lead, lead away, take) captive(-s), drive (take) away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7628A}/[H7618]', 'lemma', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["[the] captive[s] of","[the] capture of","a captive of","captive[s]","captivity"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2763A}/[H2763]', 'inflected', 'heb', 'חָרַם', '["châram"]', '["and/ I will dedicate to destruction","and/ I will totally destroy","and/ he totally destroyed","and/ he will divide","and/ it totally destroyed","and/ they totally destroyed","and/ we totally destroyed","and/ you will totally destroy"]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2767}\/[H2763]', 'inflected', 'heb', 'חׇרְמָה', '["Chormâh"]', '["Hormah"]', '["n-pr-loc"]', 'Chormah, a place in Palestine Hormah.', 'from 2763; devoted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2023G}/[H2022]', 'inflected', 'heb', 'הֹר', '["Hôr"]', '["from/ Hor"]', '["n-pr-loc"]', 'Hor, the name of a peak in Idumaea and of one in Syria Hor.', 'another form of 2022; mountain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5437H}/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["to/ go around"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7114A}/[H7114]', 'inflected', 'heb', 'קָצַר', '["qâtsar"]', '["and/ it became short","and/ it was short"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315I}/H9025/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ self/ our"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7052}/[H7043]', 'inflected', 'heb', 'קְלֹקֵל', '["qᵉlôqêl"]', '["<the>/ worthless"]', '["a"]', 'insubstantial light.', 'from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8314A}/[H8313]', 'inflected', 'heb', 'שָׂרָף', '["sârâph"]', '["the/ saraphs"]', '["n-m"]', 'burning, i.e. (figuratively) poisonous (serpent); specifically, a saraph or symbolical creature (from their copper color) fiery (serpent), seraph.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5391A}/[H5391]', 'inflected', 'heb', 'נָשַׁךְ', '["nâshak"]', '["and/ they bit","and/ they will bite"]', '["v"]', 'to strike with a sting (as a serpent); figuratively, to oppress with interest on a loan bite, lend upon usury.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5921A}/H9035/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["from/ on <the>/ us"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8314A}/[H8313]', 'lemma', 'heb', 'שָׂרָף', '["sârâph"]', '["[will be] a serpent","a saraph","fiery"]', '["n-m"]', 'burning, i.e. (figuratively) poisonous (serpent); specifically, a saraph or symbolical creature (from their copper color) fiery (serpent), seraph.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5251H}/[H5264]', 'lemma', 'heb', 'נֵס', '["nêç"]', '["[the] sail","a standard"]', '["n-m"]', 'a flag; also a sail; by implication, a flagstaff; generally a signal; figuratively, a token banner, pole, sail, (en-) sign, standard.', 'from 5264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760A}/H9033/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ I will make/ him","and/ he appointed/ him","and/ he had appointed/ him","and/ he put/ it","and/ they made/ it"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5251H}/[H5264]', 'inflected', 'heb', 'נֵס', '["nêç"]', '["the/ standard"]', '["n-m"]', 'a flag; also a sail; by implication, a flagstaff; generally a signal; figuratively, a token banner, pole, sail, (en-) sign, standard.', 'from 5264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5391A}/[H5391]', 'lemma', 'heb', 'נָשַׁךְ', '["nâshak"]', '["it had bitten","it will bite"]', '["v"]', 'to strike with a sting (as a serpent); figuratively, to oppress with interest on a loan bite, lend upon usury.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0088}/[H178]', 'inflected', 'heb', 'אֹבֹת', '["ʼôbôth"]', '["at/ Oboth","in/ Oboth"]', '["n-pr-loc"]', 'Oboth, a place in the Desert Oboth.', 'plural of 178; water-skins;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0088}/[H178]', 'inflected', 'heb', 'אֹבֹת', '["ʼôbôth"]', '["from/ Oboth"]', '["n-pr-loc"]', 'Oboth, a place in the Desert Oboth.', 'plural of 178; water-skins;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5863}/[H5856]', 'inflected', 'heb', 'עִיֵּי הָעֲבָרִים', '["ʻÎyêy hâ-ʻĂbârîym"]', '["at/ Iye"]', '["n-pr-loc"]', 'Ije-ha-Abarim, a place near Palestine Ije-abarim.', 'from the plural of 5856 and the plural of the active participle of 5674 with the article interposed; ruins of the passers;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5863}/[H5856]', 'inflected', 'heb', 'עִיֵּי הָעֲבָרִים', '["ʻÎyêy hâ-ʻĂbârîym"]', '["<the>/ Abarim"]', '["n-pr-loc"]', 'Ije-ha-Abarim, a place near Palestine Ije-abarim.', 'from the plural of 5856 and the plural of the active participle of 5674 with the article interposed; ruins of the passers;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4217H}/[H2224]', 'inflected', 'heb', 'מִזְרָח', '["mizrâch"]', '["from/ [the] east","from/ [the] rising of","from/ east"]', '["n-m"]', 'sunrise, i.e. the east east (side, -ward), (sun-) rising (of the sun).', 'from 2224;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2218>', 'opaque', 'heb', 'זֶרֶד', '["Zered"]', '["Zered"]', '["n-pr-loc"]', 'Zered, a brook East of the Dead Sea Zared, Zered.', 'from an unused root meaning to be exuberant in growth; lined with shrubbery;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5676G}/[H5674]', 'inflected', 'heb', 'עֵבֶר', '["ʻêber"]', '["[is] from/ [the] other side","[is] from/ [the] other side of","[were] from/ [the] side of","from/ [the] other side","from/ [the] other side of"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0769}/[H7442]', 'lemma', 'heb', 'אַרְנוֹן', '["ʼArnôwn"]', '["Arnon","[the] Arnon"]', '["n-pr-loc"]', 'the Arnon, a river east of the Jordan, also its territory Arnon.', 'or אַרְנֹןlemma אַרְנן missing vowel, corrected to אַרְנֹן; from 7442; a brawling stream;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3318I}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["which/ goes out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1366G}/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["from/ [the] border","from/ [the] border of"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2052>', 'opaque', 'heb', 'וָהֵב', '["Vâhêb"]', '["Waheb"]', '["n-pr-loc"]', 'Vaheb, a place in Moab what he did.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5492B}/[H5486]', 'inflected', 'heb', 'סוּפָה', '["çûwphâh"]', '["in/ Suphah"]', '["n-f n-pr-loc"]', 'a hurricane Red Sea, storm, tempest, whirlwind, Red sea.', 'from 5486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5158N}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["the/ wadi","the/ wadis"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0793>', 'inflected', 'heb', 'ואשד', '["ve./''E.shed"]', '["and/ [the] slope of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6144}/[H5892]', 'lemma', 'heb', 'עָר', '["ʻÂr"]', '["Ar"]', '["n-pr-loc"]', 'Ar, a place in Moab Ar.', 'the same as 5892; a city;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8172}/[H8172]', 'inflected', 'heb', 'שָׁעַן', '["shâʻan"]', '["and/ it leans","and/ it will depend","and/ you have depended"]', '["v"]', 'to support one''s self lean, lie, rely, rest (on, self), stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1366G}/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["<to>/ [the] border of","for/ [the] border of","of/ [the] border of","to/ [the] border of"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0876G}/H9011/[H875]', 'inflected', 'heb', 'בְּאֵר', '["Bᵉʼêr"]', '["Beer/ towards"]', '["n-pr-loc"]', 'Beer, a place in the Desert, also one in Palestine Beer.', 'the same as 875;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4325G}\/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["water"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2658}/H9034/[H2658]', 'inflected', 'heb', 'חָפַר', '["châphar"]', '["[which] they dug/ it"]', '["v"]', 'properly, to pry into; by implication, to delve, to explore dig, paw, search out, seek.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3738B}/H9034/[H3738]', 'inflected', 'heb', 'כָּרָה', '["kârâh"]', '["[which] they dug/ it"]', '["v"]', 'properly, to dig; figuratively, to plot; generally, to bore or open dig, × make (a banquet), open.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5081H}/[H5068]', 'lemma', 'heb', 'נָדִיב', '["nâdîyb"]', '["[the] noble [people] of","a noble [person]","noble","noble [people]","noble [people] of","noble deeds"]', '["a"]', 'properly, voluntary, i.e. generous; hence, magnanimous; as noun, a grandee (sometimes a tyrant) free, liberal (things), noble, prince, willing (hearted).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2710}/[H2710]', 'inflected', 'heb', 'חָקַק', '["châqaq"]', '["with/ a ruler''s staff"]', '["v"]', 'properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4938B}/H9028/[H4937]', 'inflected', 'heb', 'מִשְׁעֵנָה', '["mishʻênâh"]', '["with/ staffs/ their"]', '["n-f"]', 'support (abstractly), i.e. (figuratively) sustenance or (concretely) a walking-stick staff.', 'or מִשְׁעֶנֶת; feminine of 4937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4980}/[H4979]', 'lemma', 'heb', 'מַתָּנָה', '["Mattânâh"]', '["Mattanah"]', '["n-pr-loc"]', 'Mattanah, a place in the Desert Mattanah.', 'the same as 4979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4980}/[H4979]', 'inflected', 'heb', 'מַתָּנָה', '["Mattânâh"]', '["and/ from/ Mattanah"]', '["n-pr-loc"]', 'Mattanah, a place in the Desert Mattanah.', 'the same as 4979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5160}/[H5158]', 'lemma', 'heb', 'נַחֲלִיאֵל', '["Nachălîyʼêl"]', '["Nahaliel"]', '["n-pr-loc"]', 'Nachaliël, a place in the Desert Nahaliel.', 'from 5158 and 410; valley of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5160}/[H5158]', 'inflected', 'heb', 'נַחֲלִיאֵל', '["Nachălîyʼêl"]', '["and/ from/ Nahaliel"]', '["n-pr-loc"]', 'Nachaliël, a place in the Desert Nahaliel.', 'from 5158 and 410; valley of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1120G}/[H1116]', 'lemma', 'heb', 'בָּמוֹת', '["Bâmôwth"]', '["Bamoth"]', '["n-pr-loc"]', 'Bamoth or Bamoth-Baal, a place East of the Jordan Bamoth, Bamoth-baal.', 'plural of 1116; heights; or (fully) בָּמוֹת בַּעַל; from the same and 1168; heights of Baal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1120G}/[H1116]', 'inflected', 'heb', 'בָּמוֹת', '["Bâmôwth"]', '["and/ from/ Bamoth"]', '["n-pr-loc"]', 'Bamoth or Bamoth-Baal, a place East of the Jordan Bamoth, Bamoth-baal.', 'plural of 1116; heights; or (fully) בָּמוֹת בַּעַל; from the same and 1168; heights of Baal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1516R}/[H1466]', 'inflected', 'heb', 'גַּיְא', '["gayʼ"]', '["the/ valley","the/ valleys"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6449}/[H6448]', 'inflected', 'heb', 'פִּסְגָּה', '["Piçgâh"]', '["<the>/ Pisgah"]', '["n-pr-loc"]', 'Pisgah, a Mountain East of Jordan Pisgah.', 'from 6448; a cleft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8259}/[H8259]', 'inflected', 'heb', 'שָׁקַף', '["shâqaph"]', '["and/ it looked down"]', '["v"]', 'properly, to lean out (of a window), i.e. (by implication) peep or gaze (passively, be a spectacle) appear, look (down, forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3452H}\/[H3456]', 'inflected', 'heb', 'יְשִׁימוֹן', '["yᵉshîymôwn"]', '["the/ desolate place"]', '["n-m"]', 'a desolation desert, Jeshimon, solitary, wilderness.', 'from 3456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5511}/[H5477]', 'lemma', 'heb', 'סִיחוֹן', '["Çîychôwn"]', '["Sihon"]', '["n-pr-m"]', 'Sichon, an Amoritish king Sihon.', 'or סִיחֹן; from the same as 5477; tempestuous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870I}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["on/ [the] way of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3096>/H9011', 'opaque', 'heb', 'יַהַץ', '["Yahats"]', '["Jahaz/ <towards>","Jahaz/ towards"]', '["n-pr-loc"]', 'Jahats or Jahtsah, a place East of the Jordan Jahaz, Jahazah, Jahzah.', 'or יַהְצָה; or (feminine) יַהְצָה; from an unused root meaning to stamp; perhaps threshing-floor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776G>/H9023', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["earth/ his","land/ his","land/ its","own land/ his"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0769}/[H7442]', 'inflected', 'heb', 'אַרְנוֹן', '["ʼArnôwn"]', '["from/ Arnon","from/ [the] Arnon"]', '["n-pr-loc"]', 'the Arnon, a river east of the Jordan, also its territory Arnon.', 'or אַרְנֹןlemma אַרְנן missing vowel, corrected to אַרְנֹן; from 7442; a brawling stream;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2809}/[H2808]', 'inflected', 'heb', 'חֶשְׁבּוֹן', '["Cheshbôwn"]', '["in/ Heshbon"]', '["n-pr-loc"]', 'Cheshbon, a place East of the Jordan Heshbon.', 'the same as 2808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1323H}/H9024/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["daughters/ its"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2809}/[H2808]', 'lemma', 'heb', 'חֶשְׁבּוֹן', '["Cheshbôwn"]', '["Heshbon","O Heshbon"]', '["n-pr-loc"]', 'Cheshbon, a place East of the Jordan Heshbon.', 'the same as 2808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4428G}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["<in> <the>/ kings","against the/ king","against/ [the] king of","among the/ kings","in the/ king","on the/ king","to the/ king","with the/ king","with/ [the] king of"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027H}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ his","from/ hand/ its"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4911B}/[H4912]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["<the>/ [one who] speaks a proverb","those/ [who] speak proverbs"]', '["v"]', 'to liken, i.e. (transitively) to use figurative language (an allegory, adage, song or the like); intransitively, to resemble be(-come) like, compare, use (as a) proverb, speak (in proverbs), utter.', 'denominative from 4912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3559I}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["and/ it may be established"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2809}/[H2808]', 'inflected', 'heb', 'חֶשְׁבּוֹן', '["Cheshbôwn"]', '["from/ Heshbon"]', '["n-pr-loc"]', 'Cheshbon, a place East of the Jordan Heshbon.', 'the same as 2808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3852}/[H3851]', 'lemma', 'heb', 'לֶהָבָה', '["lehâbâh"]', '["[the] flame","[the] flame of","[will be] a flame","a flame","flame","flames","flames of"]', '["n-f"]', 'flame(-ming), head (of a spear).', 'or לַהֶבֶת; feminine of 3851, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7151}/[H7136]', 'inflected', 'heb', 'קִרְיָה', '["qiryâh"]', '["[is] more than/ a town of","from/ [the] town","from/ [the] town of"]', '["n-f"]', 'a city city.', 'from 7136 in the sense of flooring, i.e. building;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1116>', 'opaque', 'heb', 'בָּמָה', '["bâmâh"]', '["[are] [the] high places of","[the] high places","[the] high places of","a high place","high places"]', '["n-f"]', 'an elevation height, high place, wave.', 'from an unused root (meaning to be high);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0188}/[H183]', 'lemma', 'heb', 'אוֹי', '["ʼôwy"]', '["woe","woe!"]', '["inj"]', 'lamentation; also interjectionally Oh! alas, woe.', 'probably from 183 (in the sense of crying out after);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3645>', 'opaque', 'heb', 'כְּמוֹשׁ', '["Kᵉmôwsh"]', '["Chemosh"]', '["n-pr"]', 'Kemosh, the god of the Moabites Chemosh.', 'or (Jeremiah 48:7) כְּמִישׁ; from an unused root meaning to subdue; the powerful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6412B}/[H6403]', 'lemma', 'heb', 'פָּלִיט', '["pâlîyṭ"]', '["O escapees","fugitives","survivors"]', '["n-m"]', 'a refugee (that have) escape(-d, -th), fugitive.', 'or פָּלֵיט; or פָּלֵט; from 6403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7622}/[H7617]', 'inflected', 'heb', 'שְׁבוּת', '["shᵉbûwth"]', '["in <the>/ captivity"]', '["n-f"]', 'exile, concretely, prisoners; figuratively, a former state of prosperity captive(-ity).', 'or שְׁבִית; from 7617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0567}/[H559]', 'lemma', 'heb', 'אֱמֹרִי', '["ʼĔmôrîy"]', '["[the] Amorite[s]","[was] an Amorite"]', '["n-m"]', 'an Emorite, one of the Canaanitish tribes Amorite.', 'probably a patronymic from an unused name derived from 559 in the sense of publicity, i.e. prominence; thus, a mountaineer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3384A}/H9038/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["and/ he shot at/ them","and/ we shot at/ them"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1769G}/[H1727]', 'lemma', 'heb', 'דִּיבוֹן', '["Dîybôwn"]', '["Dibon"]', '["n-pr-loc"]', 'Dibon, the name of three places in Palestine Dibon. (Also, with 1410 added, Dibon-gad.)', 'or (shortened) דִּיבֹן; from 1727; pining:—');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5302}/[H5301]', 'lemma', 'heb', 'נֹפַח', '["Nôphach"]', '["Nophah"]', '["n-pr-loc"]', 'Nophach, a place in Moab Nophah.', 'from 5301; a gust;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4311}/[H4325]', 'lemma', 'heb', 'מֵידְבָא', '["Mêydᵉbâʼ"]', '["Medeba"]', '["n-pr-loc"]', 'Medeba, a place in Palestine Medeba.', 'from 4325 and 1679; water of quiet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7270}/[H7272]', 'inflected', 'heb', 'רָגַל', '["râgal"]', '["to/ spy out"]', '["v"]', 'to walk along; but only in specifically, applications, to reconnoiter, to be a tale-bearer (i.e. slander); to lead about backbite, search, slander, (e-) spy (out), teach to go, view.', 'a primitive root; also as denominative from 7272');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3270G}/[H5826]', 'lemma', 'heb', 'יַעֲזֵיר', '["Yaʻăzêyr"]', '["Jazer"]', '["n-pr-loc"]', 'Jaazer or Jazer, a place East of the Jordan Jaazer, Jazer.', 'or יַעְזֵר; from 5826; helpful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3920}/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["and/ he captured","and/ he had captured","and/ he took","and/ he was taken by lot","and/ he will capture","and/ it captured","and/ it was taken by lot","and/ it will be captured","and/ they captured","and/ they had captured","and/ they have been captured","and/ they will be captured","and/ we captured"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1316>', 'inflected', 'heb', 'הבשן', '["ha./ba.Shan"]', '["<the>/ Bashan"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5747}/[H5746]', 'lemma', 'heb', 'עוֹג', '["ʻÔwg"]', '["Og"]', '["n-pr-m"]', 'Og, a king of Bashan Og.', 'probably from 5746; round;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122H}/H9038/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ them"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4421}/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["[are] for <the>/ war","[was] for / war","for <the>/ battle","for <the>/ war","for the/ battle","for/ battle","of/ war","to <the>/ battle","to <the>/ war","to the/ battle"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0154}/[H153]', 'lemma', 'heb', 'אֶדְרֶעִי', '["ʼedreʻîy"]', '["Edrei"]', '["n-pr-loc"]', 'Edrei, the name of two places in Palestine Edrei.', 'from the equivalent of 153; mighty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5511}/[H5477]', 'inflected', 'heb', 'סִיחוֹן', '["Çîychôwn"]', '["to/ Sihon"]', '["n-pr-m"]', 'Sichon, an Amoritish king Sihon.', 'or סִיחֹן; from the same as 5477; tempestuous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8300}/[H8277]', 'lemma', 'heb', 'שָׂרִיד', '["sârîyd"]', '["[is] a survivor","[the] survivor[s]","[the] survivors of","a survivor","survivor","survivor[s]"]', '["n-m"]', 'a survivor × alive, left, remain(-ing), remnant, rest.', 'from 8277;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6160I}/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["in/ [the] desert plains of","in/ [the] plains of"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4124I}/[H1]', 'lemma', 'heb', 'מוֹאָב', '["Môwʼâb"]', '["Moab"]', '["n-pr-m n-pr-loc"]', 'Moab, an incestuous son of Lot; also his territory and descendants Moab.', 'from a prolonged form of the prepositional prefix m- and 1; from (her [the mother''s]) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5676H}/[H5674]', 'inflected', 'heb', 'עֵבֶר', '["ʻêber"]', '["[is] from/ [the] other side","[was] from/ [the] other side of","[were] from/ [the] other side of","from/ [the] other side","from/ [the] other side of"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3383}/[H3381]', 'inflected', 'heb', 'יַרְדֵּן', '["Yardên"]', '["of the/ Jordan","of/ [the] Jordan"]', '["n-pr"]', 'Jarden, the principal river of Palestine Jordan.', 'from 3381; a descender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3405G}\/[H3394]', 'inflected', 'heb', 'יְרִיחוֹ', '["Yᵉrîychôw"]', '["Jericho","of Jericho"]', '["n-pr-loc"]', 'Jericho or Jerecho, a place in Palestine Jericho.', 'or יְרֵחוֹ; or variation (1 Kings 16:34) יְרִיחֹה; perhaps from 3394; its month; or else from 7306; fragrant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1111}/[H1110]', 'lemma', 'heb', 'בָּלָק', '["Bâlâq"]', '["Balak","O Balak"]', '["n-pr-m"]', 'Balak, a Moabitish king Balak.', 'from 1110; waster;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6834}/[H6833]', 'lemma', 'heb', 'צִפּוֹר', '["Tsippôwr"]', '["Zippor"]', '["n-pr-m"]', 'Tsippor, a Moabite Zippor.', 'the same as 6833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0567}/[H559]', 'inflected', 'heb', 'אֱמֹרִי', '["ʼĔmôrîy"]', '["to the/ Amorite[s]"]', '["n-m"]', 'an Emorite, one of the Canaanitish tribes Amorite.', 'probably a patronymic from an unused name derived from 559 in the sense of publicity, i.e. prominence; thus, a mountaineer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1481C}/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["and/ he was afraid","and/ it was afraid"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3897}/[H3897]', 'lemma', 'heb', 'לָחַךְ', '["lâchak"]', '["it licked up","they will lick up"]', '["v"]', 'to lick lick (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439G}/H9035/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["[were] around/ us","around/ us"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3897}/[H3897]', 'inflected', 'heb', 'לָחַךְ', '["lâchak"]', '["as/ licks up"]', '["v"]', 'to lick lick (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1111}/[H1110]', 'inflected', 'heb', 'בָּלָק', '["Bâlâq"]', '["and/ Balak"]', '["n-pr-m"]', 'Balak, a Moabitish king Balak.', 'from 1110; waster;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4124G}/[H1]', 'inflected', 'heb', 'מוֹאָב', '["Môwʼâb"]', '["for/ Moab","of/ Moab","to/ Moab"]', '["n-pr-m n-pr-loc"]', 'Moab, an incestuous son of Lot; also his territory and descendants Moab.', 'from a prolonged form of the prepositional prefix m- and 1; from (her [the mother''s]) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1109A}/[H1077]', 'lemma', 'heb', 'בִּלְעָם', '["Bilʻâm"]', '["Balaam"]', '["n-pr-m n-pr-loc"]', 'Bilam, a Mesopotamian prophet; also a place in Palestine Balaam, Bileam.', 'probably from 1077 and 5971; not (of the) people, i.e. foreigner;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1160H}/[H1197]', 'lemma', 'heb', 'בְּעוֹר', '["Bᵉʻôwr"]', '["Beor"]', '["n-pr-m"]', 'Beor, the name of the father of an Edomitish king; also of that of Balaam Beor.', 'from 1197 (in the sense of burning); a lamp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6604>/H9011', 'opaque', 'heb', 'פְּתוֹר', '["Pᵉthôwr"]', '["Pethor/ towards"]', '["n-pr-loc"]', 'Pethor, a place in Mesopotamia Pethor.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4136}/H9030/[H4135]', 'inflected', 'heb', 'מוּל', '["mûwl"]', '["from/ in front of/ me"]', '["n-m"]', 'properly, abrupt, i.e. a precipice; by implication, the front; used only adverbially (with prepositional prefix) opposite (over) against, before, (fore-) front, from, (God-) ward, toward, with.', 'or מוֹל; (Deuteronomy 1:1), or מוֹאל; (Nehemiah 12:38), or מֻל; (Numbers 22:5), from 4135;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0779}/H9012/[H779]', 'inflected', 'heb', 'אָרַר', '["ʼârar"]', '["curse/ !"]', '["v"]', 'to execrate × bitterly curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6099}/[H6105]', 'lemma', 'heb', 'עָצוּם', '["ʻâtsûwm"]', '["[is too] mighty","mighty","mighty [ones]","mighty [people]","numerous"]', '["a"]', 'powerful (specifically, a paw); by implication, numerous feeble, great, mighty, must, strong.', 'or עָצֻם; passive participle of 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1644G}/H9033/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["and/ I will drive out/ it"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7081}/[H7080]', 'inflected', 'heb', 'קֶסֶם', '["qeçem"]', '["and/ divination","and/ divination of","and/ divinations"]', '["n-m"]', 'a lot; also divination (including its fee), oracle (reward of) divination, divine sentence, witchcraft.', 'from 7080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027H}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[were] in/ hand/ their","by/ hand/ their","in/ hand/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6895}/H9012/[H6895]', 'inflected', 'heb', 'קָבַב', '["qâbab"]', '["curse/ !"]', '["v"]', 'to scoop out, i.e. (figuratively) to malign or execrate (i.e. stab with words) × at all, curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1644G}/H9033/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["and/ I will drive out/ it","and/ he drove away/ him"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5414K}/H9030/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["to/ permit/ me"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1980H}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["from/ coming"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3513G}/H9031/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["I will honor/ you","she will honor/ you","they will honor/ you","to honor/ you"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1980K}/H9012/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ come/ !"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5674D}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["by/ transgressing","to/ transgress"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9020/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ my","O God/ my","[are] God/ my","[was] God/ my","[will be] God/ my"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7854}/[H7853]', 'inflected', 'heb', 'שָׂטָן', '["sâṭân"]', '["<into>/ an adversary","to/ an adversary"]', '["n-m"]', 'an opponent; especially (with the article prefixed) Satan, the arch-enemy of good adversary, Satan, withstand.', 'from 7853;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0860}/[H386]', 'inflected', 'heb', 'אָתוֹן', '["ʼâthôwn"]', '["the/ donkey","the/ donkeys","the/ she-asses"]', '["n-f"]', 'a female donkey (from its docility) (she) ass.', 'probably from the same as 386 (in the sense of patience);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2719}/H9023/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["and/ sword/ his"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8025}/[H8025]', 'lemma', 'heb', 'שָׁלַף', '["shâlaph"]', '["[was] drawing","[was] drawn","[were] drawers of","[who] drew","[who] drew out","draw","draw out","drawn","he drew","he drew out","he took off","he will draw [it] out","it has shot up"]', '["v"]', 'to pull out, up or off draw (off), grow up, pluck off.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5186}/H9034/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["to/ turn/ it"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4934}/[H8168]', 'inflected', 'heb', 'מִשְׁעוֹל', '["mishʻôwl"]', '["in/ [the] narrow way of"]', '["n-m"]', 'a hollow, i.e. a narrow passage path.', 'from the same as 8168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3754>', 'inflected', 'heb', 'הכרמים', '["ha./Ke.rem","ha./ke.ra.Mim"]', '["the/ vineyard","the/ vineyards"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1447}/[H1443]', 'lemma', 'heb', 'גָּדֵר', '["gâdêr"]', '["a fence","a wall"]', '["n-m"]', 'a circumvallation; by implication, an inclosure fence, hedge, wall.', 'from 1443;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1447}/[H1443]', 'inflected', 'heb', 'גָּדֵר', '["gâdêr"]', '["and/ [the] wall","and/ a wall"]', '["n-m"]', 'a circumvallation; by implication, an inclosure fence, hedge, wall.', 'from 1443;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3905}/[H3905]', 'inflected', 'heb', 'לָחַץ', '["lâchats"]', '["and/ it squeezed","and/ it squeezed itself","and/ they pressed","and/ they will oppress","and/ you will push"]', '["v"]', 'properly, to press, i.e. (figuratively) to distress afflict, crush, force, hold fast, oppress(-or), thrust self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5221}/H9034/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["to/ strike/ it"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6862A}/[H6887]', 'lemma', 'heb', 'צַר', '["tsar"]', '["[is] narrow","[the] distress of","it is [too] cramped","it is cramped","narrow","tight"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7257}/[H7257]', 'inflected', 'heb', 'רָבַץ', '["râbats"]', '["and/ it lay down","and/ it will lie down","and/ they will lie down","and/ you will lie down"]', '["v"]', 'to crouch (on all four legs folded, like a recumbent animal); by implication, to recline, repose, brood, lurk, imbed crouch (down), fall down, make a fold, lay, (cause to, make to) lie (down), make to rest, sit.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1109A}/[H1077]', 'inflected', 'heb', 'בִּלְעָם', '["Bilʻâm"]', '["<to>/ Balaam","to/ Balaam"]', '["n-pr-m n-pr-loc"]', 'Bilam, a Mesopotamian prophet; also a place in Palestine Balaam, Bileam.', 'probably from 1077 and 5971; not (of the) people, i.e. foreigner;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5221}/H9030/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["strike/ me","they struck/ me","you have struck/ me"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0860}/[H386]', 'inflected', 'heb', 'אָתוֹן', '["ʼâthôwn"]', '["to the/ donkey"]', '["n-f"]', 'a female donkey (from its docility) (she) ass.', 'probably from the same as 386 (in the sense of patience);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2026}/H9032/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["I killed/ you"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0860}/H9021/[H386]', 'inflected', 'heb', 'אָתוֹן', '["ʼâthôwn"]', '["donkey/ your","female donkey/ your"]', '["n-f"]', 'a female donkey (from its docility) (she) ass.', 'probably from the same as 386 (in the sense of patience);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5750}/H9021/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["from/ duration/ your"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5532}/[H5532]', 'inflected', 'heb', 'סָכַן', '["çâkan"]', '["¿/ really <to have [the] habit>"]', '["v"]', 'to be familiar with; by implication, to minister to, be serviceable to, to cherish, be customary acquaint (self), be advantage, × ever, (be, (un-)) profit(-able), treasurer, be wont.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5532}/[H5532]', 'lemma', 'heb', 'סָכַן', '["çâkan"]', '["a nurse","be reconciled","have I had [the] habit","it is of use","it profits","will he be of use","will he be of use?","will it be of use","you know intimately"]', '["v"]', 'to be familiar with; by implication, to minister to, be serviceable to, to cherish, be customary acquaint (self), be advantage, × ever, (be, (un-)) profit(-able), treasurer, be wont.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3399A}/[H3399]', 'lemma', 'heb', 'יָרַט', '["yâraṭ"]', '["it is precipitate"]', '["v"]', 'to precipitate or hurl (rush) headlong; (intransitively) to be rash be perverse, turn over.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5048}/H9030/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["[are] to/ before/ me","[have been] to/ before/ me","[is] to/ before/ me","to/ before/ me"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200G}/H9030/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ he has shown/ me","and/ he saw/ me","and/ he showed/ me","and/ he will show/ me","and/ it saw/ me","and/ you have seen/ me"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122H}/H9030/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ me"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0657A}/[H656]', 'inflected', 'heb', 'אֶפֶס', '["ʼepheç"]', '["and/ only","and/ there not"]', '["n-m"]', 'cessation, i.e. an end (especially of the earth); often used adverb, no further; also the ankle (in the dual), as being the extremity of the leg or foot ankle, but (only), end, howbeit, less than nothing, nevertheless (where), no, none (beside), not (any, -withstanding), thing of nought, save(-ing), there, uttermost part, want, without (cause).', 'from 656; (sometimes like 6466)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1366G}/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["the/ border","the/ territory"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0552}/[H551]', 'inflected', 'heb', 'אֻמְנָם', '["ʼumnâm"]', '["¿/ really"]', '["adv"]', 'in (very) deed; of a surety.', 'an orthographical variation of 551');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3201}/[H3201]', 'inflected', 'heb', 'יָכֹל', '["yâkôl"]', '["¿/ am I able","¿/ certainly <to able>","¿/ is he able","¿/ really <to be able>"]', '["v"]', 'to be able, literally (can, could) or morally (may, might) be able, any at all (ways), attain, can (away with, (-not)), could, endure, might, overcome, have power, prevail, still, suffer.', 'or (fuller) יָכוֹל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6310G}/H9020/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["[will be] in/ mouth/ my","in/ mouth/ my","with/ mouth/ my"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7155}/[H7151]', 'lemma', 'heb', 'קִרְיַת חֻצוֹת', '["Qiryath Chutsôwth"]', '["Kiriath-","huzoth"]', '["n-pr-loc"]', 'Kirjath-Chutsoth, a place in Moab Kirjath-huzoth.', 'from 7151 and the feminine plural of 2351; city of streets;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8269}/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["and/ <into>/ a commander","and/ <to>/ [the] commanders of","and/ <to>/ [the] leaders of","and/ to the/ leaders","and/ to/ [the] commanders of","and/ to/ rulers"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5927H}/H9033/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ he brought up/ him","and/ he took up/ him","and/ they brought up/ him"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1120H}/[H1116]', 'lemma', 'heb', 'בָּמוֹת', '["Bâmôwth"]', '["Bamoth"]', '["n-pr-loc"]', 'Bamoth or Bamoth-Baal, a place East of the Jordan Bamoth, Bamoth-baal.', 'plural of 1116; heights; or (fully) בָּמוֹת בַּעַל; from the same and 1168; heights of Baal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1168I}/[H1167]', 'lemma', 'heb', 'בַּעַל', '["Baʻal"]', '["Baal"]', '["n-pr-m n-pr-loc"]', 'Baal, a Phoenician deity Baal, (plural) Baalim.', 'the same as 1167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1109A}/[H1077]', 'inflected', 'heb', 'בִּלְעָם', '["Bilʻâm"]', '["and/ Balaam"]', '["n-pr-m n-pr-loc"]', 'Bilam, a Mesopotamian prophet; also a place in Palestine Balaam, Bileam.', 'probably from 1077 and 5971; not (of the) people, i.e. foreigner;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1111}/[H1110]', 'inflected', 'heb', 'בָּלָק', '["Bâlâq"]', '["to/ Balak"]', '["n-pr-m"]', 'Balak, a Moabitish king Balak.', 'from 1110; waster;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122G}/H9030/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ me"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1697I}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ [the] matter of","and/ [the] word of","and/ anything"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8205}/[H8192]', 'lemma', 'heb', 'שְׁפִי', '["shᵉphîy"]', '["[the] bare heights","a bare height","bare heights"]', '["n-m"]', 'bareness; concretely, a bare hill or plain high place, stick out.', 'from 8192;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7136A}/[H7136]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["and/ he met","and/ it chanced on","and/ you will make happen"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4912}/H9023/[H4910]', 'inflected', 'heb', 'מָשָׁל', '["mâshâl"]', '["discourse/ his","oracle/ his"]', '["n-m"]', 'properly, a pithy maxim, usually of metaphorical nature; hence, a simile (as an adage, poem, discourse) byword, like, parable, proverb.', 'apparently from 4910 in some original sense of superiority in mental action;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2042>', 'inflected', 'heb', 'מהררי', '["me./ha.Rei","me./ha.rei"]', '["from/ [the] mountains of","more than/ mountains of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2194}/H9012/[H2194]', 'inflected', 'heb', 'זָעַם', '["zâʻam"]', '["denounce/ !"]', '["v"]', 'properly, to foam at the mouth, i.e. to be enraged abhor, abominable, (be) angry, defy, (have) indignation.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6895}/[H6895]', 'lemma', 'heb', 'קָבַב', '["qâbab"]', '["at all <curse>","will I curse"]', '["v"]', 'to scoop out, i.e. (figuratively) to malign or execrate (i.e. stab with words) × at all, curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6895}/H9033/[H6895]', 'inflected', 'heb', 'קָבַב', '["qâbab"]', '["he has cursed/ him","let them curse/ it","they curse/ him","they will curse/ him","you will curse/ it"]', '["v"]', 'to scoop out, i.e. (figuratively) to malign or execrate (i.e. stab with words) × at all, curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2194}/[H2194]', 'lemma', 'heb', 'זָעַם', '["zâʻam"]', '["[is] indignant","[one who] is cursed of","accursed","he has denounced","he was indignant","indignant","will I denounce","you have been indignant"]', '["v"]', 'properly, to foam at the mouth, i.e. to be enraged abhor, abominable, (be) angry, defy, (have) indignation.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H7218I>', 'inflected', 'heb', 'מראשי', '["me./Rosh","me./ra.Shei","me./rosh"]', '["from/ [the] top of","from/ [the] tops of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6697H}/[H6696]', 'lemma', 'heb', 'צוּר', '["tsûwr"]', '["O rock of","[is] [the] rock of","[is] a rock","[the] flint of","[the] rock","[the] rock of","[the] rocks","a rock","a rock of","flint<s>","rock","rocks"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1389I}/[H1387]', 'inflected', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["and/ from/ [the] hills"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7789}/H9033/[H7789]', 'inflected', 'heb', 'שׁוּר', '["shûwr"]', '["I observe/ him","it will see/ him","will he observe/ him","you observe/ him"]', '["v"]', 'to spy out, i.e. (generally) survey, (for evil) lurk for, (for good) care for behold, lay wait, look, observe, perceive, regard, see.', 'a primitive root (identical with through the idea of going round for inspection);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0910}/[H909]', 'inflected', 'heb', 'בָּדָד', '["bâdâd"]', '["<of>/ alone","<to>/ alone","[which] <to>/ alone"]', '["n-m"]', 'separate; adverb, separately alone, desolate, only, solitary.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1471A}/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["and/ among the/ nations"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4557}/[H5608]', 'inflected', 'heb', 'מִסְפָּר', '["miçpâr"]', '["and/ [the] number of","and/ a number"]', '["n-m"]', 'a number, definite (arithmetical) or indefinite (large, innumerable; small, a few); also (abstractly) narration abundance, account, × all, × few, (in-) finite, (certain) number(-ed), tale, telling, time.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7255}/[H7251]', 'lemma', 'heb', 'רֹבַע', '["rôbaʻ"]', '["[the] fourth part of"]', '["n-m"]', 'a quarter fourth participle', 'from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3477G}/[H3474]', 'lemma', 'heb', 'יָשָׁר', '["yâshâr"]', '["O upright [one]","[are] upright","[is] right","[is] upright","[it would be] right","[people] upright of","[the] upright","[were] upright of","a [person] upright of","an upright [person]","of [people] upright of","right","straight","upright","upright [people]","upright [things]"]', '["a"]', 'straight (literally or figuratively) convenient, equity, Jasher, just, meet(-est), pleased well right(-eous), straight, (most) upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0319}/H9020/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["end/ my"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6895}/[H6895]', 'inflected', 'heb', 'קָבַב', '["qâbab"]', '["to/ curse"]', '["v"]', 'to scoop out, i.e. (figuratively) to malign or execrate (i.e. stab with words) × at all, curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0341}/H9020/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["O enemy/ my","enemies/ my","enemy/ my"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947G}/H9031/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["I took/ you","I will take/ you","does it carry away/ you","he will bring/ you","let me take/ you","she capture/ you"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3605}/H9023/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["and/ all of/ him","and/ all of/ it"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6895}/H9030/[H6895]', 'inflected', 'heb', 'קָבַב', '["qâbab"]', '["and/ curse/ it"]', '["v"]', 'to scoop out, i.e. (figuratively) to malign or execrate (i.e. stab with words) × at all, curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6839}/[H6822]', 'lemma', 'heb', 'צֹפִים', '["Tsôphîym"]', '["Zophim"]', '["n-pr-loc"]', 'Tsophim, a place East of the Jordan Zophim.', 'plural of active participle of 6822; watchers;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2009}/H9043/[H2005]', 'inflected', 'heb', 'הִנֵּה', '["hinnêh"]', '["and/ there/ he"]', '["dp"]', 'lo! behold, lo, see.', 'prolongation for 2005;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0238}/H9012/[H241]', 'inflected', 'heb', 'אָזַן', '["ʼâzan"]', '["give ear to/ !","give ear/ !"]', '["v"]', 'to broaden out the ear (with the hand), i.e. (by implication) to listen give (perceive by the) ear, hear(-ken). See 239.', 'a primitive root; probably to expand; but used only as a denominative from 241;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5704}/H9030/[H5703]', 'inflected', 'heb', 'עַד', '["ʻad"]', '["to/ me"]', '["prep"]', 'as far (or long, or much) as, whether of space (even unto) or time (during, while, until) or degree (equally with) against, and, as, at, before, by (that), even (to), for(-asmuch as), (hither-) to, how long, into, as long (much) as, (so) that, till, toward, until, when, while, ( as) yet.', 'properly, the same as 5703 (used as a preposition, adverb or conjunction; especially with a preposition);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3576}/[H3576]', 'inflected', 'heb', 'כָּזַב', '["kâzab"]', '["so/ he may lie"]', '["v"]', 'to lie (i.e. deceive), literally or figuratively fail, (be found a, make a) liar, lie, lying, be in vain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1931}/[H1931]', 'inflected', 'heb', 'הוּא', '["hûwʼ"]', '["¿/ he"]', '["p"]', 'he (she or it); only expressed when emphatic or without a verb; also (intensively) self, or (especially with the article) the same; sometimes (as demonstrative) this or that; occasionally (instead of copula) as or are he, as for her, him(-self), it, the same, she (herself), such, that (...it), these, they, this, those, which (is), who.', 'of which the feminine (beyond the Pentateuch) is הִיא; he a primitive word, the third person pronoun singular;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965I}/H9034/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["will he fulfill?/ it"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725I}/H9034/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["I will turn back/ it","will he turn back/ it"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0205H>', 'opaque', 'heb', 'אָוֶן', '["ʼâven"]', '["[are] deception","disaster","hardship","mourning<s>","trouble"]', '["n-m"]', 'strictly nothingness; also trouble, vanity, wickedness; specifically an idol affliction, evil, false, idol, iniquity, mischief, mourners(-ing), naught, sorrow, unjust, unrighteous, vain, vanity, wicked(-ness). Compare 369.', 'from an unused root perhaps meaning properly, to pant (hence, to exert oneself, usually in vain; to come to naught);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5999}/[H5998]', 'lemma', 'heb', 'עָמָל', '["ʻâmâl"]', '["[is] toil","[the] mischief of","[the] toil","[the] toil of","[was] trouble","[who] trouble","mischief","toil","trouble"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8643}/[H7321]', 'inflected', 'heb', 'תְּרוּעָה', '["tᵉrûwʻâh"]', '["and/ [the] battle-cry","and/ a shout of","and/ a shout of alarm","and/ battle-cry"]', '["n-f"]', 'clamor, i.e. acclamation of joy or a battle-cry; especially clangor of trumpets, as an alarum alarm, blow(-ing) (of, the) (trumpets), joy, jubile, loud noise, rejoicing, shout(-ing), (high, joyful) sound(-ing).', 'from 7321;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8443}/[H3286]', 'inflected', 'heb', 'תּוֹעָפָה', '["tôwʻâphâh"]', '["like/ [the] horns of"]', '["n-f"]', '(only in plural collective) weariness, i.e. (by implication) toil (treasure so obtained) or speed plenty, strength.', 'from 3286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7214}/[H7213]', 'lemma', 'heb', 'רְאֵם', '["rᵉʼêm"]', '["[the] wild ox","a wild ox","wild oxen"]', '["n-m"]', 'a wild bull (from its conspicuousness) unicorn.', 'or רְאֵיםlemma רְאיֵם second vowel, corrected to רְאֵים; or רֵים; or רֵם; from 7213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5173}/[H5172]', 'lemma', 'heb', 'נַחַשׁ', '["nachash"]', '["enchantment","omens"]', '["n-m"]', 'an incantation or augury enchantment.', 'from 5172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7081}/[H7080]', 'lemma', 'heb', 'קֶסֶם', '["qeçem"]', '["divination","divinations"]', '["n-m"]', 'a lot; also divination (including its fee), oracle (reward of) divination, divine sentence, witchcraft.', 'from 7080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3833C>', 'inflected', 'heb', 'כלביא', '["ka./la.Vi''","ke./la.Vi''"]', '["[is] like <the>/ lion","like/ a lion"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0738A}/[H717]', 'inflected', 'heb', 'אֲרִי', '["ʼărîy"]', '["and/ like/ a lion"]', '["n-m"]', 'a lion (young) lion, pierce (from the margin).', 'or (prolonged) אַרְיֵה; from 717 (in the sense of violence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2964}/[H2963]', 'lemma', 'heb', 'טֶרֶף', '["ṭereph"]', '["<of> prey","[the] prey","food","prey"]', '["n-m"]', 'something torn, i.e. a fragment, e.g. a fresh leaf, prey, food leaf, meat, prey, spoil.', 'from 2963;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1818}/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["and/ [the] blood of","and/ [the] blood<s> of","and/ blood","and/ blood of","and/ blood<s>"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2491A}/[H2490]', 'lemma', 'heb', 'חָלָל', '["châlâl"]', '["[are those] slain of","[are] slain","[are] slain of","[is] slain","[one] slain","[the] slain","[those] fatally wounded","[those] slain","[those] slain [are]","[those] slain of","fatally wounded","slain","slain [ones]"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3474}/[H3474]', 'lemma', 'heb', 'יָשַׁר', '["yâshar"]', '["I approve","I will make smooth","he makes straight","he will make straight","it is pleasing","it is upright","it makes straight","it was pleasing","it will be pleasing","let them look straight","made smooth","make straight","she is pleasing","they were pleasing"]', '["v"]', 'to be straight or even; figuratively, to be (causatively, to make) right, pleasant, prosperous direct, fit, seem good (meet), please (will), be (esteem, go) right (on), bring (look, make, take the) straight (way), be upright(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6895}/H9033/[H6895]', 'inflected', 'heb', 'קָבַב', '["qâbab"]', '["and/ you will curse/ it"]', '["v"]', 'to scoop out, i.e. (figuratively) to malign or execrate (i.e. stab with words) × at all, curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6465}/[H6473]', 'inflected', 'heb', 'פְּעוֹר', '["Pᵉʻôwr"]', '["<the>/ Peor"]', '["n-pr"]', 'Peör, a mountain East of Jordan; Baal Peor, (for a deity worshipped there Peor. See also 1047.', 'from 6473; a gap; also 1187)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8259}/[H8259]', 'inflected', 'heb', 'שָׁקַף', '["shâqaph"]', '["[is] the/ [one who] looks down","which/ looks down"]', '["v"]', 'properly, to lean out (of a window), i.e. (by implication) peep or gaze (passively, be a spectacle) appear, look (down, forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3452H}/[H3456]', 'inflected', 'heb', 'יְשִׁימוֹן', '["yᵉshîymôwn"]', '["the/ desolate place"]', '["n-m"]', 'a desolation desert, Jeshimon, solitary, wilderness.', 'from 3456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6471}/[H6470]', 'inflected', 'heb', 'פַּעַם', '["paʻam"]', '["as/ time"]', '["n-f"]', 'a stroke, literally or figuratively (in various applications, as follow) anvil, corner, foot(-step), going, (hundred-) fold, × now, (this) once, order, rank, step, thrice, (often-), second, this, two) time(-s), twice, wheel.', 'or (feminine) פַּעֲמָה; from 6470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7626H>/H9023', 'inflected', 'heb', 'לשבטיו', '["le./shiv.T/o","li/sh.va.Ta/v"]', '["to/ tribe/ his","to/ tribes/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5002}/[H5001]', 'inflected', 'heb', 'נְאֻם', '["nᵉʼum"]', '["and/ [the] utterance of"]', '["n-m"]', 'an oracle (hath) said, saith.', 'from 5001;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8365}/[H8365]', 'lemma', 'heb', 'שָׁתַם', '["shâtham"]', '["<the> opened of"]', '["v"]', 'to unveil (figuratively) be open.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5869A}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["the/ eye"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4236}/[H2372]', 'lemma', 'heb', 'מַחֲזֶה', '["machăzeh"]', '["<the> vision of","a vision of"]', '["n-m"]', 'a vision vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1540I}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["and/ [who] is uncovered of","and/ he uncovers"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0168G}/H9021/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["tent/ your","tents/ your"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4908}/H9021/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["[are] dwelling place<s>/ your","dwelling place<s>/ your","dwelling places/ your"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5158B}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["like/ wadis"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1593}/[H1588]', 'inflected', 'heb', 'גַּנָּה', '["gannâh"]', '["like/ gardens"]', '["n-f"]', 'a garden garden.', 'feminine of 1588;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H0174>', 'inflected', 'heb', 'כאהלים', '["ka./''a.ha.Lim"]', '["like/ aloes"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5193}/[H5193]', 'lemma', 'heb', 'נָטַע', '["nâṭaʻ"]', '["I have planted","I planted","[what] is planted","[which] he has planted","firmly fixed","he has planted","he planted","he plants","it planted","planters","she plants","they have been planted","they will plant","you had planted","you have planted","you must plant","you plant","you planted","you will plant"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0730}/[H729]', 'inflected', 'heb', 'אֶרֶז', '["ʼerez"]', '["like <the>/ cedars","like/ a cedar","like/ cedars"]', '["n-m"]', 'a cedar tree (from the tenacity of its roots) cedar (tree).', 'from 729;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1805}/H9023/[H1802]', 'inflected', 'heb', 'דְּלִי', '["dᵉlîy"]', '["from/ buckets/ its"]', '["n-m"]', 'a pail or jar (for drawing water) bucket.', 'or דֳּלִי; from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0090G>', 'inflected', 'heb', 'מאגג', '["me./''a.Gag"]', '["more than/ Agag"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428G}/H9023/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["[will be] king/ his","king/ his","king/ its"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5375L}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ [the] exalted [one]","so/ it may be exalted"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4438}/H9023/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["kingdom/ his","kingdom/ its","reign/ his","royalty/ his"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318H}/H9033/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["[is] bringing out/ it"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6862C}/H9023/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["[will be] opponents/ his","opponents/ his","opponents/ its"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6106G}/H9028/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["and/ bones/ their"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1633B}/[H1634]', 'lemma', 'heb', 'גָּרַם', '["gâram"]', '["it will break","you will break"]', '["v"]', '(causative) to bone, i.e. denude (by extensive, craunch) the bones gnaw the bones, break.', 'a primitive root; to be spare or skeleton-like; used only as a denominative from 1634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2671}/H9023/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["and/ arrows/ its"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4272}/[H4272]', 'lemma', 'heb', 'מָחַץ', '["mâchats"]', '["I wound","he shattered","he shatters","he will shatter","it may smash","it will wound [them]","shatter","you have shattered"]', '["v"]', 'to dash asunder; by implication, to crush, smash or violently plunge; figuratively, to subdue or destroy dip, pierce (through), smite (through), strike through, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0738A}/[H717]', 'inflected', 'heb', 'אֲרִי', '["ʼărîy"]', '["like <the>/ lion","like/ a lion"]', '["n-m"]', 'a lion (young) lion, pierce (from the margin).', 'or (prolonged) אַרְיֵה; from 717 (in the sense of violence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0779}/H9031/[H779]', 'inflected', 'heb', 'אָרַר', '["ʼârar"]', '["and/ [those who] curse/ you"]', '["v"]', 'to execrate × bitterly curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5606A}/[H5606]', 'inflected', 'heb', 'סָפַק', '["çâphaq"]', '["and/ he clapped","and/ it will splash"]', '["v"]', 'to clap the hands (in token of compact, derision, grief, indignation, or punishment); by implication of satisfaction, to be enough; by implication of excess, to vomit clap, smite, strike, suffice, wallow.', 'or שָׂפַק; (1 Kings 20:10; Job 27:23; Isaiah 2:6), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121G}/H9031/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["I call out to/ you","I called/ you","I have called out to/ you","I have called/ you","I summoned/ you","[those who] call out to/ you","[when] I called on/ you"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4725}/H9021/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["place/ your"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4513}/H9031/[H4513]', 'inflected', 'heb', 'מָנַע', '["mânaʻ"]', '["he has restrained/ you","he has withheld/ you"]', '["v"]', 'to debar (negatively or positively) from benefit or injury deny, keep (back), refrain, restrain, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3519}/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["from/ honor","more than/ honor"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4397G>/H9021', 'opaque', 'heb', 'מַלְאָךְ', '["malʼâk"]', '["messengers/ your"]', '["n-m"]', 'a messenger; specifically, of God, i.e. an angel (also a prophet, priest or teacher) ambassador, angel, king, messenger.', 'from an unused root meaning to despatch as a deputy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5971A}/H9020/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["for/ people/ my","of/ people/ my","to/ people/ my"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1847}/[H3045]', 'lemma', 'heb', 'דַּעַת', '["daʻath"]', '["<of> [the] knowledge of","<of> knowledge","[is] knowledge of","knowledge","knowledge of"]', '["n"]', 'knowledge cunning, (ig-) norantly, know(-ledge), (un-) awares (wittingly).', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5945B}/[H5927]', 'lemma', 'heb', 'עֶלְיוֹן', '["ʻelyôwn"]', '["Most High","O Most High","[the] Most High"]', '["n-m a"]', 'an elevation, i.e. (adj.) lofty (compar.); as title, the Supreme (Most, on) high(-er, -est), upper(-most).', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1869}/[H1869]', 'lemma', 'heb', 'דָּרַךְ', '["dârak"]', '["<of> [those who] bend","I have trodden","I will bend","[are] bent","[one who] treads","[some who] trod","[those who] bend","[who] bent","anyone will tread","bent","he bend","he has bent","he has trodden","he leads","he will tread","it trod","it will march forth","it will tread","may he bend","they bend","they have trodden","they tread","you trod","you will march","you will tread"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3290}/[H6117]', 'inflected', 'heb', 'יַעֲקֹב', '["Yaʻăqôb"]', '["from/ Jacob"]', '["n-pr-m"]', 'Jaakob, the Israelitish patriarch Jacob.', 'from 6117; heel-catcher (i.e. supplanter);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4272}/[H4272]', 'inflected', 'heb', 'מָחַץ', '["mâchats"]', '["and/ it will shatter","and/ she smashed"]', '["v"]', 'to dash asunder; by implication, to crush, smash or violently plunge; figuratively, to subdue or destroy dip, pierce (through), smite (through), strike through, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6979C}/[H7023]', 'inflected', 'heb', 'קוּר', '["qûwr"]', '["and/ it will destroy"]', '["v"]', 'to trench; by implication, to throw forth; to wall up, whether literal (to build a wall) or figurative (to estop) break down, cast out, destroy, dig.', 'a primitive root; also denominative from 7023');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3424}/[H3423]', 'lemma', 'heb', 'יְרֵשָׁה', '["yᵉrêshâh"]', '["a possession"]', '["n-f"]', 'occupancy possession.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5892B}/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["[are] any of/ [the] cities of","from/ [the] cities of","from/ [the] city","from/ [the] city of","from/ a city","from/ a city of","from/ city"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0319}/H9023/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["and/ end/ his","and/ end/ its"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0008}/[H6]', 'lemma', 'heb', 'אֹבֵד', '["ʼôbêd"]', '["destruction"]', '["n-m"]', '(concrete) wretched or (abstract) destruction perish.', 'active of participle of 6;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0386>', 'opaque', 'heb', 'אֵיתָן', '["ʼêythân"]', '["[is] constant","[is] enduring","an ever-flowing [stream]","enduring","ever-flowing"]', '["a"]', 'permanence; hence (concrete) permanent; specifically a chieftain hard, mighty, rough, strength, strong.', 'or (shortened) אֵתָן ; from an unused root (meaning to continue);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5553H>', 'inflected', 'heb', 'בסלע', '["ba./Se.la''","be./Se.la''","va./Se.la''"]', '["[were] at/ [the] rock of","among the/ rock[s]","at/ [the] rock of","in the/ rock","in the/ rock[s]","on the/ crag[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7064}/H9021/[H7077]', 'inflected', 'heb', 'קֵן', '["qên"]', '["nest/ your"]', '["n-m"]', 'a nest (as fixed), sometimes including the nestlings; figuratively, a chamber or dwelling nest, room.', 'contracted from 7077;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1197A}/[H1198]', 'inflected', 'heb', 'בָּעַר', '["bâʻar"]', '["<into>/ burning","<into>/ consuming","to/ burn","to/ burn [it]"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7014A}/[H7013]', 'lemma', 'heb', 'קַיִן', '["Qayin"]', '["[the] Kenite[s]"]', '["n-pr-m"]', 'Kajin, the name of the first child, also of a place in Palestine, and of an Oriental tribe Cain, Kenite(-s).', 'the same as 7013 (with a play upon the affinity to 7069);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7617}/H9031/[H7617]', 'inflected', 'heb', 'שָׁבָה', '["shâbâh"]', '["will it take captive/ you"]', '["v"]', 'to transport into captivity (bring away, carry, carry away, lead, lead away, take) captive(-s), drive (take) away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7760A}/H9033/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["from/ when ordains/ it"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6716}/[H6680]', 'inflected', 'heb', 'צִי', '["tsîy"]', '["and/ a ship","and/ ships"]', '["n-m"]', 'a ship (as a fixture) ship.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3794H}/[H3794]', 'lemma', 'heb', 'כִּתִּי', '["Kittîy"]', '["Cyprus","Kittim"]', '["a"]', 'a Kittite or Cypriote; hence, an islander in general, i.e. the Greeks or Romans on the shores opposite Palestine Chittim, Kittim.', 'or כִּתִּיִּי; patrial from an unused name denoting Cyprus (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1870L}/H9023\/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["to/ way/ his"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7851G}/[H7848]', 'inflected', 'heb', 'שִׁטִּים', '["Shiṭṭîym"]', '["in <the>/ Shittim"]', '["n-pr-loc"]', 'Shittim, a place East of the Jordan Shittim.', 'the same as the plural of 7848; acacia trees;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0430J}/H9029/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["to/ gods/ their"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6775}/[H6775]', 'inflected', 'heb', 'צָמַד', '["tsâmad"]', '["and/ it joined itself","and/ they joined themselves"]', '["v"]', 'to link, i.e. gird; figuratively, to serve, (mentally) contrive fasten, frame, join (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1187}/[H1168]', 'inflected', 'heb', 'בַּעַל פְּעוֹר', '["Baʻal Pᵉʻôwr"]', '["to/ Baal"]', '["n-pr-m"]', 'Baal-Peor, a Moabitish deity Baal-peor.', 'from 1168 and 6465; Baal of Peor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1187}/[H1168]', 'lemma', 'heb', 'בַּעַל פְּעוֹר', '["Baʻal Pᵉʻôwr"]', '["Baal","Peor"]', '["n-pr-m"]', 'Baal-Peor, a Moabitish deity Baal-peor.', 'from 1168 and 6465; Baal of Peor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3363}/[H3363]', 'inflected', 'heb', 'יָקַע', '["yâqaʻ"]', '["and/ impale"]', '["v"]', 'properly, to sever oneself, i.e. (by implication) to be dislocated; figuratively, to abandon; causatively, to impale (and thus allow to drop to pieces by rotting) be alienated, depart, hang (up), be out of joint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725I}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ it may turn back","and/ turn back","so/ may it turn away"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2740}/[H2734]', 'lemma', 'heb', 'חָרוֹן', '["chârôwn"]', '["[the] anger of","[the] burning of","anger","burning"]', '["n-m"]', 'a burning of anger sore displeasure, fierce(-ness), fury, (fierce) wrath(-ful).', 'or (shortened) חָרֹן; from 2734;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6775}/[H6775]', 'inflected', 'heb', 'צָמַד', '["tsâmad"]', '["who/ have joined themselves"]', '["v"]', 'to link, i.e. gird; figuratively, to serve, (mentally) contrive fasten, frame, join (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7420>', 'opaque', 'heb', 'רֹמַח', '["rômach"]', '["a spear","spear"]', '["n-m"]', 'a lance (as thrown); especially the iron point buckler, javelin, lancet, spear.', 'from an unused root meaning to hurl;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6898}/[H6895]', 'inflected', 'heb', 'קֻבָּה', '["qubbâh"]', '["the/ tent"]', '["n-f"]', 'a pavilion (as a domed cavity) tent.', 'from 6895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1856}/[H1856]', 'inflected', 'heb', 'דָּקַר', '["dâqar"]', '["and/ he pierced through"]', '["v"]', 'to stab; by analogy, to starve; figuratively, to revile pierce, strike (thrust) through, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6897}/H9024/[H6895]', 'inflected', 'heb', 'קֹבָה', '["qôbâh"]', '["belly/ her"]', '["n-f"]', 'the abdomen (as a cavity) belly.', 'from 6895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2534}/H9020/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["anger/ my","rage/ my"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7065}/H9043/[H7065]', 'inflected', 'heb', 'קָנָא', '["qânâʼ"]', '["because/ was zealous/ he"]', '["v"]', 'to be (causatively, make) zealous, i.e. (in a bad sense) jealous or envious (be) envy(-ious), be (move to, provoke to) jealous(-y), × very, (be) zeal(-ous).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7068}/H9020/[H7065]', 'inflected', 'heb', 'קִנְאָה', '["qinʼâh"]', '["jealousy/ my","zeal/ my"]', '["n-f"]', 'jealousy or envy envy(-ied), jealousy, × sake, zeal.', 'from 7065;');
