INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7065}/[H7065]', 'lemma', 'heb', 'קָנָא', '["qânâʼ"]', '["I am jealous","I have been zealous","I was jealous","certainly <to be zealous>","he was zealous","it be jealous","it will be jealous of","you be jealous"]', '["v"]', 'to be (causatively, make) zealous, i.e. (in a bad sense) jealous or envious (be) envy(-ious), be (move to, provoke to) jealous(-y), × very, (be) zeal(-ous).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2174G}/[H2167]', 'lemma', 'heb', 'זִמְרִי', '["Zimrîy"]', '["[was] Zimri"]', '["n-pr-m"]', 'Zimri, the name of five Israelites, and of an Arabian tribe Zimri.', 'from 2167; musical;');
