INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5159}/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["<in> the/ inheritance","<in>/ an inheritance","in/ [the] inheritance of","on/ [the] inheritance of"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7227A}/[H7231]', 'inflected', 'heb', 'רַב', '["rab"]', '["by <the>/ many [people]","for the/ many","for/ many","for/ many [people]","to <the>/ many [people]","to the/ many [people]"]', '["a n-m"]', 'abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent).', 'by contracted from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5159}/H9023/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["[is] inheritance/ his","[was] inheritance/ its","[will be] inheritance/ his","inheritance/ his","inheritance/ its"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4592}/[H4591]', 'inflected', 'heb', 'מְעַט', '["mᵉʻaṭ"]', '["and/ for the/ few"]', '["n-m"]', 'a little or few (often adverbial or comparative) almost (some, very) few(-er, -est), lightly, little (while), (very) small (matter, thing), some, soon, × very.', 'or מְעָט; from 4591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1486>', 'inflected', 'heb', 'בגורלות', '["ba./go.Ral","be./go.Ral","be./go.ra.Lot","va./go.Ral"]', '["by the/ lot","by/ [the] allotted portion of","by/ lot","by/ lots"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8034}/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["<into>/ a name","<into>/ a name of","<to>/ [the] name of","for/ [the] name of","for/ a name","for/ name","to/ [the] name of","to/ [the] names of"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4592}\/[H4591]', 'inflected', 'heb', 'מְעַט', '["mᵉʻaṭ"]', '["and/ [the] few"]', '["n-m"]', 'a little or few (often adverbial or comparative) almost (some, very) few(-er, -est), lightly, little (while), (very) small (matter, thing), some, soon, × very.', 'or מְעָט; from 4591;');
