INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4848}/[H4847]', 'inflected', 'heb', 'מְרָרִי', '["Mᵉrârîy"]', '["the/ Merarite[s]"]', '["a"]', 'a Merarite (collectively), or descendants of Merari Merarites.', 'from 4847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3878}/[H3867]', 'inflected', 'heb', 'לֵוִי', '["Lêvîy"]', '["for/ Levi","to/ Levi"]', '["n-pr-m"]', 'Levi, a son of Jacob Levi. See also 3879, 3881.', 'from 3867; attached;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6019G}/[H5971]', 'inflected', 'heb', 'עַמְרָם', '["ʻAmrâm"]', '["to/ Amram"]', '["n-pr-m"]', 'Amram, the name of two Israelites Amram.', 'probably from 5971 and 7311; high people;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0428}/[H411]', 'inflected', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["and/ among/ these"]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6485A}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["from/ [the] enrolled [men] of"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5126}\/[H5125]', 'inflected', 'heb', 'נוּן', '["Nûwn"]', '["Nun"]', '["n-pr-m"]', 'Nun or Non, the father of Joshua Non, Nun.', 'or נוֹן; (1 Chronicles 7:27), from 5125; perpetuity,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5270}/[H5128]', 'lemma', 'heb', 'נֹעָה', '["Nôʻâh"]', '["Noah"]', '["n-pr-f"]', 'Noah, an Israelitess Noah.', 'from 5128; movement;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2295>', 'inflected', 'heb', 'וחגלה', '["ve./cha.ge.Lah"]', '["and/ Hoglah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4435H}/[H4436]', 'inflected', 'heb', 'מִלְכָּה', '["Milkâh"]', '["and/ Milcah"]', '["n-pr-f"]', 'Milcah, the name of a Hebrewess and of an Israelite Milcah.', 'a form of 4436; queen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2399}/H9023/[H2398]', 'inflected', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["for/ own sin/ his","in/ own sin/ his"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941H}/H9029/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["case/ their"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1323G}/H9023/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ daughter/ his","to/ daughter/ his","to/ daughters/ his"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251G}/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["for/ a brother","to/ [the] brothers of"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3423G}/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["and/ he possessed","and/ he will take possession of","and/ you will cause to inherit [it]"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5682}/[H5676]', 'inflected', 'heb', 'עֲבָרִים', '["ʻĂbârîym"]', '["the/ Abarim"]', '["n-pr-loc"]', 'Abarim, a place in Palestine Abarim, passages.', 'plural of 5676; regions beyond;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971B}/H9021/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["people<s>/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4808}/[H7378]', 'inflected', 'heb', 'מְרִיבָה', '["mᵉrîybâh"]', '["in/ [the] strife of"]', '["n-f"]', 'quarrel provocation, strife.', 'from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6790>\', 'opaque', 'heb', 'צִן', '["Tsin"]', '["Zin"]', '["n-pr-loc"]', 'Tsin, a part of the Desert Zin.', 'from an unused root meaning to prick; a crag;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H6629G>', 'inflected', 'heb', 'כצאן', '["Kha./tzon","ka./Tzon","ke./Tzon","kha./Tzon"]', '["like <the>/ flock","like <the>/ sheep","like/ [the] flock of","like/ [the] sheep of","like/ sheep","like/ sheep of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027H}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869H}/H9028/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ their"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1935>/H9021', 'inflected', 'heb', 'מהודך', '["me./hod./Kha"]', '["some of/ majesty/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310I}/H9023/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["mouth/ his"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7133A}/H9020/[H7126]', 'inflected', 'heb', 'קׇרְבָּן', '["qorbân"]', '["offering/ my"]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899G}/H9020/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["food/ my"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0801}/H9020/[H800]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["for/ fire offerings/ my"]', '["n-m"]', 'properly, a burnt-offering; but occasionally of any sacrifice (offering, sacrifice), (made) by fire.', 'the same as 800, but used in a liturgical sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5207}/H9020/[H5117]', 'inflected', 'heb', 'נִיחוֹחַ', '["nîychôwach"]', '["soothing/ my"]', '["n-m"]', 'properly, restful, i.e. pleasant; abstractly, delight sweet (odour).', 'or נִיחֹחַ; from 5117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0801}/[H800]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["[is] the/ fire offering"]', '["n-m"]', 'properly, a burnt-offering; but occasionally of any sacrifice (offering, sacrifice), (made) by fire.', 'the same as 800, but used in a liturgical sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6224}/[H6235]', 'inflected', 'heb', 'עֲשִׂירִי', '["ʻăsîyrîy"]', '["and/ [the] tenth [part] of","and/ [the] tenth of"]', '["a"]', 'tenth; by abbreviation, tenth month or (feminine) part tenth (part).', 'from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6213I}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["which/ was instituted"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5262}/H9023/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ like/ drink offering/ its"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7676}/H9023/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["in/ sabbath/ its","on/ sabbath/ its"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5262}/H9024\/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ drink offering/ its","and/ drink offerings/ its"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7243}/[H7251]', 'inflected', 'heb', 'רְבִיעִי', '["rᵉbîyʻîy"]', '["and/ [the] fourth of","and/ a fourth"]', '["a"]', 'fourth; also (fractionally) a fourth foursquare, fourth (part).', 'or רְבִעִי; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2320G}/H9023/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["in/ month/ its"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5262}/H9023\/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ drink offering/ its"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7126H}/H9046/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["when/ bring near/ you","when/ brought near/ you"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7620G}/H9026/[H7650]', 'inflected', 'heb', 'שָׁבוּעַ', '["shâbûwaʻ"]', '["at/ weeks/ your"]', '["n-m"]', 'literally, sevened, i.e. a week (specifically, of years) seven, week.', 'or שָׁבֻעַ; also (feminine) שְׁבֻעָה; properly, passive participle of 7650 as a denominative of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5262}/H9028\/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ drink offerings/ their"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2320H}/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["and/ at the/ new moons","and/ in the/ month","and/ on the/ new moons"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2320H}/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["the/ new moon","the/ new moons"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4503G>/H9024', 'inflected', 'heb', 'ומנחתה', '["u./min.cha.Ta/h"]', '["and/ grain offering/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4941G}/H9028/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["according to/ ordinance/ their"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6218}/[H6235]', 'inflected', 'heb', 'עָשׂוֹר', '["ʻâsôwr"]', '["and/ on the/ ten"]', '["n-m"]', 'ten; by abbreviated form ten strings, and so a decachord (instrument of) ten (strings, -th).', 'or עָשֹׂר; from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4503G>/H9024', 'opaque', 'heb', 'מִנְחָה', '["minchâh"]', '["grain offering/ its"]', '["n-f"]', 'a donation; euphemistically, tribute; specifically a sacrificial offering (usually bloodless and voluntary) gift, oblation, (meat) offering, present, sacrifice.', 'from an unused root meaning to apportion, i.e. bestow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H3532>', 'inflected', 'heb', 'ולכבשים', '["ve./La./ke.va.Sim","ve./la./ke.va.Sim"]', '["and/ for the/ lambs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4557}/H9028/[H5608]', 'inflected', 'heb', 'מִסְפָּר', '["miçpâr"]', '["by/ number/ their"]', '["n-m"]', 'a number, definite (arithmetical) or indefinite (large, innumerable; small, a few); also (abstractly) narration abundance, account, × all, × few, (in-) finite, (certain) number(-ed), tale, telling, time.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4941I}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["according to the/ ordinance","according to/ [the] ordinance"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4941I}/H9028/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["according to/ ordinance/ their"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5262}/H9024/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ drink offering/ its"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0905J}/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["<to>/ apart","<to>/ besides"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5088}/H9026/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["from/ votive offerings/ your"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5071}/H9026/[H5068]', 'inflected', 'heb', 'נְדָבָה', '["nᵉdâbâh"]', '["and/ freewill offerings/ your"]', '["n-f"]', 'properly (abstractly) spontaneity, or (adjectively) spontaneous; also (concretely) a spontaneous or (by inference, in plural) abundant gift free(-will) offering, freely, plentiful, voluntary(-ily, offering), willing(-ly), offering).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5930A}/H9026/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["to/ burnt offerings/ your"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H4503G>/H9026', 'inflected', 'heb', 'ולמנחתיכם', '["u./le./min.Cho.tei./Khem"]', '["and/ to/ grain offerings/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5262}/H9026/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ to/ drink offerings/ your"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8002}/H9026/[H7999]', 'inflected', 'heb', 'שֶׁלֶם', '["shelem"]', '["and/ to/ peace offerings/ your"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0631}/[H631]', 'inflected', 'heb', 'אָסַר', '["ʼâçar"]', '["to/ [the] prisoners","to/ bind"]', '["v"]', 'to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0632}/[H631]', 'lemma', 'heb', 'אֱסָר', '["ʼĕçâr"]', '["an obligation","obligation"]', '["n-m"]', 'an obligation or vow (of abstinence) binding, bond.', 'or אִסָּר; from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315I}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["life/ his","own self/ his","own self/ its","self/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3318O}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["<the>/ [thing which] has gone out","which/ is about to go forth"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310G}/H9023/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["[which] from/ mouth/ his","from/ mouth/ his","from/ mouth/ its"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5271A}/H9024/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["in/ youth<s>/ her"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5088}/H9024/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["vow/ her","vows/ her"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0632}/H9024/[H631]', 'inflected', 'heb', 'אֱסָר', '["ʼĕçâr"]', '["and/ obligation/ her","and/ obligations/ her"]', '["n-m"]', 'an obligation or vow (of abstinence) binding, bond.', 'or אִסָּר; from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315I}/H9024/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["breath/ her","self/ her","self/ its"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5106}/[H5106]', 'lemma', 'heb', 'נוּא', '["nûwʼ"]', '["he forbade","he frustrates","he will forbid","it refuse"]', '["v"]', 'to refuse, forbid, dissuade, or neutralize break, disallow, discourage, make of none effect.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085G}/H9043/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["has heard/ he","heard/ he","hears/ he"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5088}/H9024/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["and/ vows/ her"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4008}/[H981]', 'lemma', 'heb', 'מִבְטָא', '["mibṭâʼ"]', '["[the] rash utterance of"]', '["n-m"]', 'a rash utterance (hasty vow) (that which...) uttered (out of).', 'from 981;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193G}/H9024/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["lips/ her"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6565A}/[H6565]', 'inflected', 'heb', 'פָּרַר', '["pârar"]', '["and/ he had frustrated","and/ he will break","and/ it was broken","and/ it will break","and/ they broke","and/ will he break?","and/ you will frustrate"]', '["v"]', 'to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5088}/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["and/ [the] vow of"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4161}/[H3318]', 'lemma', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["<the> utterance of","[is] a mine","[the] exits of","[the] going forth of","[the] going<s> out of","[the] outlet of","[the] utterance of","a going forth of"]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5088}/H9024/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["to/ vows/ her"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0632}/[H631]', 'inflected', 'heb', 'אֱסָר', '["ʼĕçâr"]', '["and/ to/ [the] obligation of"]', '["n-m"]', 'an obligation or vow (of abstinence) binding, bond.', 'or אִסָּר; from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6565A}/H9038/[H6565]', 'inflected', 'heb', 'פָּרַר', '["pârar"]', '["he has broken/ them"]', '["v"]', 'to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965I}/H9033/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["he will confirm/ it","you have raised up/ him"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0376H>/H9024', 'inflected', 'heb', 'ואישה', '["ve./''i.Sha/h"]', '["and/ husband/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6565A}/H9033/[H6565]', 'inflected', 'heb', 'פָּרַר', '["pârar"]', '["he will break/ it"]', '["v"]', 'to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0632}/H9024/[H631]', 'inflected', 'heb', 'אֱסָר', '["ʼĕçâr"]', '["obligations/ her"]', '["n-m"]', 'an obligation or vow (of abstinence) binding, bond.', 'or אִסָּר; from 631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9024\/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["father/ her"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5360}/[H5359]', 'lemma', 'heb', 'נְקָמָה', '["nᵉqâmâh"]', '["[is] [the] vengeance of","[the] vengeance of","vengeance","vengeance<s>"]', '["n-f"]', 'avengement, whether the act or the passion avenge, revenge(-ing), vengeance.', 'feminine of 5359;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2502B}/[H2502]', 'lemma', 'heb', 'חָלַץ', '["châlats"]', '["<the> armed [men] of","[men] equipped of","[the] armed [men] of","armed [men] of","be equipped","equipped","equipped [man]","equipped [man] of","he will strengthen","we will equip ourselves","you will equip yourselves"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6635H}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["for <the>/ war","to <the>/ war"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4560}/[H4560]', 'inflected', 'heb', 'מָסַר', '["mâçar"]', '["and/ they were selected"]', '["v"]', 'to sunder, i.e. (transitively) set apart, or (reflex.) apostatize commit, deliver.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0505G}/[H504]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["from/ [the] thousands of","more than/ a thousand","more than/ thousands of","of/ a thousand"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2689}/[H2690]', 'inflected', 'heb', 'חֲצֹצְרָה', '["chătsôtsᵉrâh"]', '["and/ [the] trumpets of"]', '["n-f"]', 'a trumpet (from its sundered or quavering note) trumpet(-er).', 'by reduplication from 2690;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8643}/[H7321]', 'inflected', 'heb', 'תְּרוּעָה', '["tᵉrûwʻâh"]', '["the/ alarm","the/ shout"]', '["n-f"]', 'clamor, i.e. acclamation of joy or a battle-cry; especially clangor of trumpets, as an alarum alarm, blow(-ing) (of, the) (trumpets), joy, jubile, loud noise, rejoicing, shout(-ing), (high, joyful) sound(-ing).', 'from 7321;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6633}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["and/ they waged war"]', '["v"]', 'to mass (an army or servants) assemble, fight, perform, muster, wait upon, war.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2491A}/H9028/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["slain [ones]/ their"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0189}/[H183]', 'lemma', 'heb', 'אֱוִי', '["ʼĔvîy"]', '["Evi"]', '["n-pr-m"]', 'Evi, a Midianitish chief Evi.', 'probably from 183; desirous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7552G}/[H7551]', 'lemma', 'heb', 'רֶקֶם', '["Reqem"]', '["Rekem"]', '["n-pr-m n-pr-loc"]', 'Rekem, the name of a place in Palestine, also of a Midianite and an Israelite Rekem.', 'from 7551; versicolor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6698H}/[H6697]', 'lemma', 'heb', 'צוּר', '["Tsûwr"]', '["Zur"]', '["n-pr-m"]', 'Tsur, the name of a Midianite and of an Israelite Zur.', 'the same as 6697; rock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2354H}/[H2353]', 'lemma', 'heb', 'חוּר', '["Chûwr"]', '["Hur"]', '["n-pr-m"]', 'Chur, the name of four Israelites and one Midianite Hur.', 'the same as 2353 or 2352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7254}/[H7253]', 'lemma', 'heb', 'רֶבַע', '["Rebaʻ"]', '["Reba"]', '["n-m"]', 'Reba, a Midianite Reba.', 'the same as 7253;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0962}/[H962]', 'lemma', 'heb', 'בָּזַז', '["bâzaz"]', '["despoiled","it will be plundered","plundering","they had plundered","they had taken plunder","they plundered","they will plunder","they will take as spoil","we plundered","you will plunder"]', '["v"]', 'to plunder catch, gather, (take) for a prey, rob(-ber), spoil, take (away, spoil), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2918}/H9028/[H2905]', 'inflected', 'heb', 'טִירָה', '["ṭîyrâh"]', '["encampment/ their","encampments/ their"]', '["n-f"]', 'a wall; hence, a fortress or a hamlet (goodly) castle, habitation, palace, row.', 'feminine of (an equivalent to) 2905;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7998}/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["the/ booty","the/ plunder"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4455A}/[H3947]', 'inflected', 'heb', 'מַלְקוֹחַ', '["malqôwach"]', '["the/ booty"]', '["n-m"]', 'transitively (in dual) the jaws (as taking food); intransitively, spoil [and captives] (as taken) booty, jaws, prey.', 'from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6160I}/[H6150]', 'lemma', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["[the] plains of"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2428A}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["the/ armies","the/ army"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4421}/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["<the>/ war","[of] the/ battle","the/ battle","the/ war","the/ wars"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2421}/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["¿/ have you let live","¿/ will I live","¿/ will he live","¿/ will they live","¿/ will they restore"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4560}/[H4560]', 'inflected', 'heb', 'מָסַר', '["mâçar"]', '["to/ offer"]', '["v"]', 'to sunder, i.e. (transitively) set apart, or (reflex.) apostatize commit, deliver.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2945}/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["among the/ little one[s]"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0802G}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["among <the>/ women","among the/ women"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7628A}/H9026/[H7618]', 'inflected', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["and/ captive[s]/ your"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6635A}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["<the>/ hosts","the/ army","the/ army of","the/ host"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1270}/[H1269]', 'inflected', 'heb', 'בַּרְזֶל', '["barzel"]', '["<the>/ iron","the/ iron","the/ iron [axe]"]', '["n-m"]', 'iron (as cutting); by extension, an iron implement (ax) head, iron.', 'perhaps from the root of 1269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0913}/[H914]', 'inflected', 'heb', 'בְּדִיל', '["bᵉdîyl"]', '["<the>/ tin","the/ tin"]', '["n-m"]', 'alloy (because removed by smelting); by analogy, tin plummet, tin.', 'from 914;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5777}/[H6080]', 'inflected', 'heb', 'עוֹפֶרֶת', '["ʻôwphereth"]', '["<the>/ lead","the/ lead"]', '["n-m"]', 'lead (from its dusty color) lead.', 'or עֹפֶרֶת; feminine participle active of 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0899B}/H9026/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["clothes/ your","garments/ your"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4264}\/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["the/ army","the/ camp"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4455A}/[H3947]', 'lemma', 'heb', 'מַלְקוֹחַ', '["malqôwach"]', '["[the] booty of","booty"]', '["n-m"]', 'transitively (in dual) the jaws (as taking food); intransitively, spoil [and captives] (as taken) booty, jaws, prey.', 'from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7218H>', 'inflected', 'heb', 'וראשי', '["ve./Rosh","ve./ra.Shei"]', '["and/ [is] [the] head of","and/ [the] heads of","and/ [the] leaders of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4371>', 'opaque', 'heb', 'מֶכֶס', '["mekeç"]', '["[the] tax of","a tax"]', '["n-m"]', 'an assessment (as based upon a census) tribute.', 'probably from an unused root meaning to enumerate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2568}/[H2568]', 'inflected', 'heb', 'חָמֵשׁ', '["châmêsh"]', '["from/ [the] five"]', '["n"]', 'five fif(-teen), fifth, five (× apiece).', 'masculine חֲמִשָּׁה; a primitive numeral;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4276}/H9028/[H2673]', 'inflected', 'heb', 'מַחֲצִית', '["machătsîyth"]', '["from/ half/ their"]', '["n-f"]', 'a halving or the middle half (so much), mid(-day).', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0499G}/[H410]', 'inflected', 'heb', 'אֶלְעָזָר', '["ʼElʻâzâr"]', '["for/ Eleazar","to/ Eleazar"]', '["n-pr-m"]', 'Elazar, the name of seven Israelites Eleazar.', 'from 410 and 5826; God (is) helper;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4276}/[H2673]', 'inflected', 'heb', 'מַחֲצִית', '["machătsîyth"]', '["and/ from/ [the] half of"]', '["n-f"]', 'a halving or the middle half (so much), mid(-day).', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0957}/[H962]', 'inflected', 'heb', 'בַּז', '["baz"]', '["the/ plunder"]', '["n-m"]', 'plunder booty, prey, spoil(-ed).', 'from 962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971K}/[H6004]', 'lemma', 'heb', 'עַם', '["ʻam"]', '["[the] people of","a people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4275}/[H2673]', 'inflected', 'heb', 'מֶחֱצָה', '["mechĕtsâh"]', '["the/ half"]', '["n-f"]', 'a halving half.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6635A}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["in the/ army","with the/ army"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4371>', 'inflected', 'heb', 'המכס', '["ha./Me.khes"]', '["the/ tax"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4371>/H9028', 'inflected', 'heb', 'ומכסם', '["u./mikh.Sa/m"]', '["and/ tax/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2673}/[H2086]', 'lemma', 'heb', 'חָצָה', '["châtsâh"]', '["he had divided","it reaches","they will be divided","they will divide in half"]', '["v"]', 'to cut or split in two; to halve divide, × live out half, reach to the midst, participle', 'a primitive root (compare 2086));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4275}/[H2673]', 'lemma', 'heb', 'מֶחֱצָה', '["mechĕtsâh"]', '["[the] half of"]', '["n-f"]', 'a halving half.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0270}/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["that/ are caught","those/ drawn"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6485J}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["the/ officers","those/ [who] were appointed","who/ were appointed"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485K}/[H6485]', 'lemma', 'heb', 'פָּקַד', '["pâqad"]', '["certainly [if] <to miss>","he be missing","he is missing","he will be missing","indeed <be missing>","it has been missing","it will be empty","people will miss [it]","they will be missing","they will miss","we missed"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0685}/[H6807]', 'lemma', 'heb', 'אֶצְעָדָה', '["ʼetsʻâdâh"]', '["an armlet"]', '["n-f"]', 'properly, a step-chain; by analogy, a bracelet bracelet, chain.', 'a variation from 6807;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6781A}/[H6775]', 'inflected', 'heb', 'צָמִיד', '["tsâmîyd"]', '["and/ a bracelet"]', '["n-m"]', 'a bracelet or arm-clasp; generally, a lid bracelet, covering.', 'or צָמִד; from 6775;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5694}/[H5696]', 'lemma', 'heb', 'עָגִיל', '["ʻâgîyl"]', '["an earring"]', '["n-m"]', 'something round, i.e. a ring (for the ears) earring.', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315I}/H9025/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["self/ our","selves/ our"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1568G}/[H1567]', 'lemma', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["Gilead","O Gilead","[are] Gilead","[is] Gilead","of Gilead"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5852G}/[H5850]', 'lemma', 'heb', 'עֲטָרוֹת', '["ʻĂṭârôwth"]', '["Ataroth"]', '["n-pr-loc"]', 'Ataroth, the name (thus simply) of two places in Palestine Ataroth.', 'or עֲטָרֹת; plural of 5850;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1769G}/[H1727]', 'inflected', 'heb', 'דִּיבוֹן', '["Dîybôwn"]', '["and/ Dibon"]', '["n-pr-loc"]', 'Dibon, the name of three places in Palestine Dibon. (Also, with 1410 added, Dibon-gad.)', 'or (shortened) דִּיבֹן; from 1727; pining:—');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3270G}/[H5826]', 'inflected', 'heb', 'יַעֲזֵיר', '["Yaʻăzêyr"]', '["and/ Jazer"]', '["n-pr-loc"]', 'Jaazer or Jazer, a place East of the Jordan Jaazer, Jazer.', 'or יַעְזֵר; from 5826; helpful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5247}/[H5246]', 'inflected', 'heb', 'נִמְרָה', '["Nimrâh"]', '["and/ Nimrah"]', '["n-pr-loc"]', 'Nimrah, a place East of the Jordan Nimrah. See also 1039, 5249.', 'from the same as 5246; clear water;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2809}/[H2808]', 'inflected', 'heb', 'חֶשְׁבּוֹן', '["Cheshbôwn"]', '["and/ Heshbon"]', '["n-pr-loc"]', 'Cheshbon, a place East of the Jordan Heshbon.', 'the same as 2808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0500}/[H410]', 'inflected', 'heb', 'אֶלְעָלֵא', '["ʼElʻâlêʼ"]', '["and/ Elealeh"]', '["n-pr-loc"]', 'Elale or Elaleh, a place east of the Jordan Elealeh.', 'or (more properly) אֶלְעָלֵה; from 410 and 5927; God (is) going up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7643G}/[H1313]', 'inflected', 'heb', 'שְׂבָם', '["Sᵉbâm"]', '["and/ Sebam"]', '["n-pr-loc"]', 'Sebam or Sibmah, a place in Moab Shebam, Shibmah, Sibmah.', 'or (feminine) שִׂבְמָה; probably from 1313; spice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5015A}/[H5015]', 'inflected', 'heb', 'נְבוֹ', '["Nᵉbôw"]', '["and/ Nebo"]', '["n-pr-m n-pr-loc"]', 'Nebo, the name of a Babylonian deity, also of a mountain in Moab, and of a place in Palestine Nebo.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1194}/[H1010]', 'inflected', 'heb', 'בְּעֹן', '["Bᵉʻôn"]', '["and/ Beon"]', '["n-pr-loc"]', 'Beön, a place East of the Jordan Beon.', 'probably a contraction of 1010;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4735}\/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["livestock"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674A}/H9035/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["to let pass/ us","you make pass over/ us"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0251I}/H9026/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["¿/ brothers/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5106}/H9013/[H5106]', 'inflected', 'heb', 'נוּא', '["nûwʼ"]', '["do you discourage/ !"]', '["v"]', 'to refuse, forbid, dissuade, or neutralize break, disallow, discourage, make of none effect.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5674A}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["for/ passing over","from/ [one who] passes by","from/ [one who] passes through","from/ [those who] pass by","from/ passing","from/ passing away","from/ passing by","from/ passing on","from/ passing over","from/ passing through"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7971G}/H9040/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["when/ sent/ I","when/ shoot/ I"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6947}/[H6946]', 'inflected', 'heb', 'קָדֵשׁ בַּרְנֵעַ', '["Qâdêsh Barnêaʻ"]', '["from/ Kadesh"]', '["n-pr-loc"]', 'Kadesh-Barnea, a place in the Desert Kadeshbarnea.', 'from the same as 6946 and an otherwise unused word (apparently compounded of a correspondent to 1251 and a derivative of 5128) meaning desert of a fugitive; Kadesh of (the) Wilderness of Wandering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6947}/[H6946]', 'lemma', 'heb', 'קָדֵשׁ בַּרְנֵעַ', '["Qâdêsh Barnêaʻ"]', '["Barnea","Kadesh"]', '["n-pr-loc"]', 'Kadesh-Barnea, a place in the Desert Kadeshbarnea.', 'from the same as 6946 and an otherwise unused word (apparently compounded of a correspondent to 1251 and a derivative of 5128) meaning desert of a fugitive; Kadesh of (the) Wilderness of Wandering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5106}/[H5106]', 'inflected', 'heb', 'נוּא', '["nûwʼ"]', '["and/ they discouraged"]', '["v"]', 'to refuse, forbid, dissuade, or neutralize break, disallow, discourage, make of none effect.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7074H}/[H7073]', 'inflected', 'heb', 'קְנִזִּי', '["Qᵉnizzîy"]', '["the/ Kenizzite"]', '["n-pr-m"]', 'a Kenizzite or descendant of Kenaz Kenezite, Kenizzites.', 'patronymic from 7073,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5128}/H9038/[H5128]', 'inflected', 'heb', 'נוּעַ', '["nûwaʻ"]', '["and/ he made wander/ them"]', '["v"]', 'to waver, in a great variety of applications, literally and figuratively (as subjoined) continually, fugitive, × make, to (go) up and down, be gone away, (be) move(-able, -d), be promoted, reel, remove, scatter, set, shake, sift, stagger, to and fro, be vagabond, wag, (make) wander (up and down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8635}/[H7235]', 'lemma', 'heb', 'תַּרְבּוּת', '["tarbûwth"]', '["a brood of"]', '["n-f"]', 'multiplication, i.e. progeny increase.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2400}/[H2398]', 'lemma', 'heb', 'חַטָּא', '["chaṭṭâʼ"]', '["[the] sinners of","sinful","sinners"]', '["n-m"]', 'a criminal, or one accounted guilty offender, sinful, sinner.', 'intensively from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5595}/[H5595]', 'inflected', 'heb', 'סָפָה', '["çâphâh"]', '["to/ add"]', '["v"]', 'properly, to scrape (literally, to shave; but usually figuratively) together (i.e. to accumulate or increase) or away (i.e. to scatter, remove, or ruin; intransitively, to perish) add, augment, consume, destroy, heap, join, perish, put.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725I}/H9013/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["you will turn away/ !","you will turn back/ !"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5117}/H9033/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["to/ leave/ it"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1448}/[H1447]', 'lemma', 'heb', 'גְּדֵרָה', '["gᵉdêrâh"]', '["[the] folds of","folds of"]', '["n-f"]', 'inclosure (especially for flocks) (sheep-) cote (fold) hedge, wall.', 'feminine of 1447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4735}/H9025/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["for/ livestock/ our"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2945}/H9025/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["for/ little one[s]/ our"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2363A}/[H2363]', 'lemma', 'heb', 'חוּשׁ', '["chûwsh"]', '["I have made haste","I want to make haste","he will make haste","hurried","making haste","they made haste"]', '["v"]', 'to hurry; figuratively, to be eager with excitement or enjoyment (make) haste(-n), ready.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4725}/H9028/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["place/ their","places/ their"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4013}/[H1219]', 'inflected', 'heb', 'מִבְצָר', '["mibtsâr"]', '["<the>/ fortification"]', '["n-m"]', 'a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold).', 'also (in plural) feminine (Daniel 11:l5) מִבְצָרָה; from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5159}/H9025/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["inheritance/ our"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4217H}/H9011\/[H2224]', 'inflected', 'heb', 'מִזְרָח', '["mizrâch"]', '["east/ -ward"]', '["n-m"]', 'sunrise, i.e. the east east (side, -ward), (sun-) rising (of the sun).', 'from 2224;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423H}/H9043/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["has dispossessed/ he"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3533}/[H3533]', 'inflected', 'heb', 'כָּבַשׁ', '["kâbash"]', '["and/ it has been subdued","and/ it will be subdued","and/ they will subdue","and/ you subjugated"]', '["v"]', 'to tread down; hence, negatively, to disregard; positively, to conquer, subjugate, violate bring into bondage, force, keep under, subdue, bring into subjection.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3478}/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["and/ from/ Israel","and/ of/ Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1448}/[H1447]', 'inflected', 'heb', 'גְּדֵרָה', '["gᵉdêrâh"]', '["and/ folds","and/ folds of"]', '["n-f"]', 'inclosure (especially for flocks) (sheep-) cote (fold) hedge, wall.', 'feminine of 1447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6792}/H9026/[H6629]', 'inflected', 'heb', 'צֹנֵא', '["tsônêʼ"]', '["for/ sheep/ your"]', '["n-m"]', 'a flock sheep.', 'or צֹנֶה; for 6629;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3318O}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ the/ [thing which] has gone out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310G}/H9026/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["from/ mouth/ your"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0929>/H9025', 'opaque', 'heb', 'בְּהֵמָה', '["bᵉhêmâh"]', '["cattle/ our"]', '["n-f"]', 'properly, a dumb beast; especially any large quadruped or animal (often collective) beast, cattle.', 'from an unused root (probably meaning to be mute);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2677}/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["and/ <to>/ [the] half of","and/ to/ [the] half of"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5892B}/H9024/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["to/ cities/ its"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1367}/[H1366]', 'inflected', 'heb', 'גְּבוּלָה', '["gᵉbûwlâh"]', '["with/ territories"]', '["n-f"]', 'a boundary, region border, bound, coast, landmark. place.', 'or גְּבֻלָה; (shortened) feminine of 1366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6177G}/[H6176]', 'lemma', 'heb', 'עֲרוֹעֵר', '["ʻĂrôwʻêr"]', '["Aroer"]', '["n-pr-loc"]', 'Aroër, the name of three places in or near Palestine Aroer.', 'or עֲרֹעֵר; or עַרְעוֹר; the same as 6176; nudity of situation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5855}/[H5852]', 'lemma', 'heb', 'עַטְרוֹת שׁוֹפָן', '["ʻAṭrôwth Shôwphân"]', '["Atroth","Shophan"]', '["n-pr-loc"]', 'Atroth-Shophan, a place in Palestine Atroth, Shophan (as if two places).', 'from the same as 5852 and a name otherwise unused (being from the same as 8226) meaning hidden; crowns of Shophan;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3011}/[H1361]', 'inflected', 'heb', 'יׇגְבְּהָה', '["Yogbᵉhâh"]', '["and/ Jogbehah"]', '["n-f"]', 'Jogbehah, a place East of the Jordan Jogbehah.', 'feminine from 1361; hillock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1039}/[H1004]', 'lemma', 'heb', 'בֵּית נִמְרָה', '["Bêyth Nimrâh"]', '["Beth","Nimrah"]', '["n-pr-loc"]', 'Beth-Nimrah, a place east of the Jordan Beth-Nimrah. Compare 5247.', 'from 1004 and the feminine of 5246; house of (the) leopard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1028}/[H1027]', 'lemma', 'heb', 'בֵּית הָרָן', '["Bêyth hâ-Rân"]', '["Beth","Haran"]', '["n-pr-loc"]', 'Beth-ha-Ran, a place East of the Jordan Beth-haran.', 'probably for 1027;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4013}/[H1219]', 'lemma', 'heb', 'מִבְצָר', '["mibtsâr"]', '["[the] fortifications of","[the] fortress of","a fortress","fortification","fortification of","fortifications","fortress","strongholds"]', '["n-m"]', 'a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold).', 'also (in plural) feminine (Daniel 11:l5) מִבְצָרָה; from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0500}/[H410]', 'lemma', 'heb', 'אֶלְעָלֵא', '["ʼElʻâlêʼ"]', '["Elealeh"]', '["n-pr-loc"]', 'Elale or Elaleh, a place east of the Jordan Elealeh.', 'or (more properly) אֶלְעָלֵה; from 410 and 5927; God (is) going up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5015A}/[H5015]', 'lemma', 'heb', 'נְבוֹ', '["Nᵉbôw"]', '["Nebo"]', '["n-pr-m n-pr-loc"]', 'Nebo, the name of a Babylonian deity, also of a mountain in Moab, and of a place in Palestine Nebo.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1186}/[H1168]', 'lemma', 'heb', 'בַּעַל מְעוֹן', '["Baʻal Mᵉʻôwn"]', '["Baal","Meon"]', '["n-pr-loc"]', 'Baal-Meon, a place East of the Jordan Baal-meon.', 'from 1168 and 4583; Baal of (the) habitation (of) (compare 1010);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7643H}/[H1313]', 'lemma', 'heb', 'שְׂבָם', '["Sᵉbâm"]', '["Sibmah"]', '["n-pr-loc"]', 'Sebam or Sibmah, a place in Moab Shebam, Shibmah, Sibmah.', 'or (feminine) שִׂבְמָה; probably from 1313; spice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1568G}/H9011/[H1567]', 'inflected', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["Gilead/ towards"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3920}/H9034/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["and/ he captured/ it","and/ he will capture/ it","and/ it captured/ it","and/ they captured/ it","and/ they will capture/ it"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2971G}/[H215]', 'inflected', 'heb', 'יָאִיר', '["Yâʼîyr"]', '["and/ Jair"]', '["n-pr-m"]', 'Jair, the name of four Israelites Jair.', 'from 215; enlightener;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2333}/H9028/[H2332]', 'inflected', 'heb', 'חַוָּה', '["chavvâh"]', '["villages/ their"]', '["n-f"]', 'by implication, an encampment or village (small) town.', 'properly, the same as 2332 (life-giving, i.e. living-place);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2334}/[H2333]', 'lemma', 'heb', 'חַוּוֹת יָעִיר', '["Chavvôwth Yâʻîyr"]', '["Havvoth","Jair","[the] villages of"]', '["n-pr-loc"]', 'hamlets of Jair, a region of Palestine (Bashan-) Havoth-jair.', 'from the plural of 2333 and a modification of 3265;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5025G}/[H5024]', 'inflected', 'heb', 'נֹבַח', '["Nôbach"]', '["and/ Nobah"]', '["n-pr-m n-pr-loc"]', 'Nobach, the name of an Israelite, and of a place East of the Jordan Nobah.', 'from 5024; a bark;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7079}/[H7069]', 'lemma', 'heb', 'קְנָת', '["Qᵉnâth"]', '["Kenath"]', '["n-pr-loc"]', 'Kenath, a place East of the Jordan Kenath.', 'from 7069; possession;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5025G}/[H5024]', 'lemma', 'heb', 'נֹבַח', '["Nôbach"]', '["Nobah"]', '["n-pr-m n-pr-loc"]', 'Nobach, the name of an Israelite, and of a place East of the Jordan Nobah.', 'from 5024; a bark;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8034}/H9023\/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["by/ own name/ his"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4161}/H9028/[H3318]', 'inflected', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["points of departure/ their"]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4161}/H9028/[H3318]', 'inflected', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["to/ points of departure/ their"]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4713}/[H4714]', 'inflected', 'heb', 'מִצְרִי', '["Mitsrîy"]', '["and/ Egypt"]', '["a"]', 'a Mitsrite, or inhabitant of Mitsrajim Egyptian, of Egypt.', 'from 4714;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0430J}/H9028/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ on/ gods/ their"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5523H}/[H5521]', 'inflected', 'heb', 'סֻכּוֹת', '["Çukkôwth"]', '["at/ Succoth"]', '["n-pr-loc"]', 'Succoth, the name of a place in Egypt and of three in Palestine Succoth.', 'or סֻכֹּת; plural of 5521; booths;');
