INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6754>', 'opaque', 'heb', 'צֶלֶם', '["tselem"]', '["[the] images of","images of"]', '["n-m"]', 'a phantom, i.e. (figuratively) illusion, resemblance; hence, a representative figure, especially an idol image, vain shew.', 'from an unused root meaning to shade;');
