INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1116>/H9028', 'opaque', 'heb', 'בָּמָה', '["bâmâh"]', '["high places/ their"]', '["n-f"]', 'an elevation height, high place, wave.', 'from an unused root (meaning to be high);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8045}/[H8045]', 'lemma', 'heb', 'שָׁמַד', '["shâmad"]', '["I destroyed","I will destroy","certainly <to be destroying>","destroy","destruction","he destroyed","he had destroyed","he will destroy","it will be destroyed","she is destroyed","they destroyed","they were destroyed","they will be destroyed","they will destroy","utterly <destroyed>","we were destroyed","you will demolish","you will destroy"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318J}/[H3318]', 'lemma', 'heb', 'יָצָא', '["yâtsâʼ"]', '["it came out","it will come out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7899}/[H5526]', 'inflected', 'heb', 'שֵׂךְ', '["sêk"]', '["<into>/ thorns"]', '["n-m"]', 'a brier (as of a hedge) prick.', 'from 5526 in the sense of 7753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6796}/[H6791]', 'inflected', 'heb', 'צָנִין', '["tsânîyn"]', '["and/ <into>/ pricks","and/ <into>/ thorns"]', '["n-m"]', 'a thorn thorn.', 'or צָנִן; from the same as 6791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6654>/H9026', 'inflected', 'heb', 'בצדיכם', '["be./tzi.dei./Khem"]', '["in/ sides/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6887D}/[H6887]', 'inflected', 'heb', 'צָרַר', '["tsârar"]', '["and/ they will oppose"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1819}/[H1819]', 'lemma', 'heb', 'דָּמָה', '["dâmâh"]', '["I am like","I gave parables","I have intended","I intended","I resemble","I will make myself like","[is] like","are you like","be like","he intended","he is like","he planned","is he like?","it is like","it was like","they intended","they were like","we have reflected on","will I liken","you became like","you imagine","you imagined"]', '["v"]', 'to compare; by implication, to resemble, liken, consider compare, devise, (be) like(-n), mean, think, use similitudes.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307I}/[H5307]', 'lemma', 'heb', 'נָפַל', '["nâphal"]', '["I have made fall","he has cast","it had fallen","it will fall","make fall","someone cast","they cast","they will fall","we have cast","you will make fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1367}/H9024/[H1366]', 'inflected', 'heb', 'גְּבוּלָה', '["gᵉbûwlâh"]', '["to/ borders/ its"]', '["n-f"]', 'a boundary, region border, bound, coast, landmark. place.', 'or גְּבֻלָה; (shortened) feminine of 1366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H5045H>', 'inflected', 'heb', 'מנגב', '["mi./Ne.gev"]', '["[is] from/ [the] south","[was] from/ [the] south","from/ [the] south"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4610}/[H4608]', 'inflected', 'heb', 'מַעֲלֵה עַקְרַבִּים', '["Maʻălêh ʻAqrabbîym"]', '["to/ [the] ascent of"]', '["n-pr-loc"]', 'Steep of Scorpions, a place in the Desert Maaleh-accrabim, the ascent (going up) of Akrabbim.', 'from 4608 and (the plural of) 6137;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4610}/[H4608]', 'lemma', 'heb', 'מַעֲלֵה עַקְרַבִּים', '["Maʻălêh ʻAqrabbîym"]', '["scorpions"]', '["n-pr-loc"]', 'Steep of Scorpions, a place in the Desert Maaleh-accrabim, the ascent (going up) of Akrabbim.', 'from 4608 and (the plural of) 6137;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6790>/H9011', 'opaque', 'heb', 'צִן', '["Tsin"]', '["Zin/ towards"]', '["n-pr-loc"]', 'Tsin, a part of the Desert Zin.', 'from an unused root meaning to prick; a crag;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8444}/H9023/[H3318]', 'inflected', 'heb', 'תּוֹצָאָה', '["tôwtsâʼâh"]', '["extremities/ its"]', '["n-f"]', '(only in plural collective) exit, i.e. (geographical) boundary, or (figuratively) deliverance, (actively) source border(-s), going(-s) forth (out), issues, outgoings.', 'or תֹּצָאָה; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6947}/[H6946]', 'inflected', 'heb', 'קָדֵשׁ בַּרְנֵעַ', '["Qâdêsh Barnêaʻ"]', '["of/ Kadesh"]', '["n-pr-loc"]', 'Kadesh-Barnea, a place in the Desert Kadeshbarnea.', 'from the same as 6946 and an otherwise unused word (apparently compounded of a correspondent to 1251 and a derivative of 5128) meaning desert of a fugitive; Kadesh of (the) Wilderness of Wandering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2692}/[H2691]', 'lemma', 'heb', 'חֲצַר אַדָּר', '["Chătsar ʼAddâr"]', '["Addar","Hazar"]', '["n-pr-loc"]', 'Chatsar-Addar, a place in Palestine Hazar-addar.', 'from 2691 and 146; (the) village of Addar;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6111}/H9011/[H6107]', 'inflected', 'heb', 'עַצְמוֹן', '["ʻAtsmôwn"]', '["Azmon/ towards"]', '["n-pr-loc"]', 'Atsmon, a place near Palestine Azmon.', 'or עַצְמֹן; from 6107; bone-like;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6111}/[H6107]', 'inflected', 'heb', 'עַצְמוֹן', '["ʻAtsmôwn"]', '["from/ Azmon"]', '["n-pr-loc"]', 'Atsmon, a place near Palestine Azmon.', 'or עַצְמֹן; from 6107; bone-like;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5158L}/H9011/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["[the] wadi of/ towards"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4714J}/[H4693]', 'lemma', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
