INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1366G}/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["and/ [the] border","and/ [the] border of","and/ [the] territory of","and/ a barrier","and/ a border","and/ a territory","and/ territory"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1419J}/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["<the>/ great"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8376}/[H8376]', 'lemma', 'heb', 'תָּאָה', '["tâʼâh"]', '["you will mark out"]', '["v"]', 'to mark off, i.e. (intensively) designate point out.', 'a primitive root;');
