INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8444}/[H3318]', 'lemma', 'heb', 'תּוֹצָאָה', '["tôwtsâʼâh"]', '["[the] extremities of","[the] sources of","[will be] [the] exits of","escapes"]', '["n-f"]', '(only in plural collective) exit, i.e. (geographical) boundary, or (figuratively) deliverance, (actively) source border(-s), going(-s) forth (out), issues, outgoings.', 'or תֹּצָאָה; from 3318;');
