INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4229B}/[H4229]', 'inflected', 'heb', 'מָחָה', '["mâchâh"]', '["and/ it will reach"]', '["v"]', 'properly, to stroke or rub; by implication, to erase; also to smooth (as if with oil), i.e. grease or make fat; also to touch, i.e. reach to abolish, blot out, destroy, full of marrow, put out, reach unto, × utterly, wipe (away, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3672G}/[H3658]', 'lemma', 'heb', 'כִּנְּרוֹת', '["Kinnᵉrôwth"]', '["Kinnereth"]', '["n-pr-loc"]', 'Kinneroth or Kinnereth, a place in Palestine Chinnereth, Chinneroth, Cinneroth.', 'or כִּנֶּרֶתlemma כִּנֶרֶת missing dagesh, corrected to כִּנֶּרֶת; respectively plural and singular feminine from the same as 3658; perhaps harp-shaped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3383}/H9011/[H3381]', 'inflected', 'heb', 'יַרְדֵּן', '["Yardên"]', '["the/ Jordan/ towards"]', '["n-pr"]', 'Jarden, the principal river of Palestine Jordan.', 'from 3381; a descender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8672}/[H8159]', 'inflected', 'heb', 'תֵּשַׁע', '["têshaʻ"]', '["for/ [the] nine","for/ nine-","to/ [the] nine"]', '["n"]', 'nine or (ordinal) ninth nine ( -teen, -teenth, -th).', 'or (masculine) תִּשְׁעָה; perhaps from 8159 through the idea of a turn to the next or full number ten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1425}/[H1410]', 'inflected', 'heb', 'גָּדִי', '["Gâdîy"]', '["the/ Gadite[s]"]', '["a"]', 'a Gadite (collectively) or descendants of Gad Gadites, children of Gad.', 'patronymically from 1410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5159}/H9028/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["[am] inheritance/ their","[was] inheritance/ their","inheritance/ their"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4294H}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["[were] from/ [the] tribe of","from/ [the] tribe of","from/ [the] tribes of","from/ a tribe","from/ tribe","of/ [the] tribe of"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5157}/[H5157]', 'inflected', 'heb', 'נָחַל', '["nâchal"]', '["to/ apportion as an inheritance to","to/ divide for possession","to/ give as an inheritance","to/ give as inheritance"]', '["v"]', 'to inherit (as a (figurative) mode of descent), or (generally) to occupy; causatively, to bequeath, or (generally) distribute, instate divide, have (inheritance), take as a heritage, (cause to, give to, make to) inherit, (distribute for, divide (for, for an, by), give for, have, leave for, take (for)) inheritance, (have in, cause to, be made to) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4294H}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["and/ of/ [the] tribe of"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8050H}/[H8085]', 'lemma', 'heb', 'שְׁמוּאֵל', '["Shᵉmûwʼêl"]', '["Shemuel"]', '["n-pr-m"]', 'Shemuël, the name of three Israelites Samuel, Shemuel.', 'from the passive participle of 8085 and 410; heard of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5989H}/[H5971]', 'lemma', 'heb', 'עַמִּיהוּד', '["ʻAmmîyhûwd"]', '["Ammihud"]', '["n-pr-m"]', 'Ammihud, the name of three Israelites Ammihud.', 'from 5971 and 1935; people of splendor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0449}/[H419]', 'lemma', 'heb', 'אֱלִידָד', '["ʼĔlîydâd"]', '["Elidad"]', '["n-pr-m"]', 'Elidad, an Israelite Elidad.', 'from the same as 419; God of (his) love;');
