INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6535>', 'opaque', 'heb', 'פַּרְנַךְ', '["Parnak"]', '["Parnach"]', '["n-pr-m"]', 'Parnak, an Israelite Parnach.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6409G}/[H6404]', 'lemma', 'heb', 'פַּלְטִיאֵל', '["Palṭîyʼêl"]', '["Paltiel"]', '["n-pr-m"]', 'Paltiel, the name of two Israelites Paltiel, Phaltiel.', 'from the same as 6404 and 410; deliverance of God;');
