INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0282}/[H251]', 'lemma', 'heb', 'אֲחִיהוּד', '["ʼĂchîyhûwd"]', '["Ahihud"]', '["n-pr-m"]', 'Achihud, an Israelite Ahihud.', 'from 251 and 1935; brother (i.e. possessor) of renown;');
