INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6300}/[H6299]', 'lemma', 'heb', 'פְּדַהְאֵל', '["Pᵉdahʼêl"]', '["Pedahel"]', '["n-pr-m"]', 'Pedahel, an Israelite Pedahel.', 'from 6299 and 410; God has ransomed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5989I}/[H5971]', 'lemma', 'heb', 'עַמִּיהוּד', '["ʻAmmîyhûwd"]', '["Ammihud"]', '["n-pr-m"]', 'Ammihud, the name of three Israelites Ammihud.', 'from 5971 and 1935; people of splendor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3667A}\/[H3665]', 'inflected', 'heb', 'כְּנַעַן', '["Kᵉnaʻan"]', '["Canaan"]', '["n-pr-m n-pr-loc n-m"]', 'Kenaan, a son a Ham; also the country inhabited by him Canaan, merchant, traffick.', 'from 3665; humiliated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5159}/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["any of/ [the] inheritance of","from/ [the] inheritance","from/ [the] inheritance of","some of/ [the] inheritance of"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4054}/[H1644]', 'inflected', 'heb', 'מִגְרָשׁ', '["migrâsh"]', '["and/ [the] pasture lands of","and/ pasture land"]', '["n-m"]', 'a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb.', 'also (in plural) feminine (Ezekiel 27:28) מִגְרָשָׁה; from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4054}/H9028/[H1644]', 'inflected', 'heb', 'מִגְרָשׁ', '["migrâsh"]', '["and/ pasture lands/ their"]', '["n-m"]', 'a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb.', 'also (in plural) feminine (Ezekiel 27:28) מִגְרָשָׁה; from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0929>/H9028', 'inflected', 'heb', 'לבהמתם', '["li/v.hem.Ta/m"]', '["for/ cattle/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7399}/H9028/[H7408]', 'inflected', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["and/ for/ property/ their"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416C}/H9028/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["animal/ their","life/ their"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7023}/[H6979]', 'inflected', 'heb', 'קִיר', '["qîyr"]', '["[will be] from/ [the] wall of","from/ [the] wall"]', '["n-m"]', 'a wall (as built in a trench) mason, side, town, × very, wall.', 'or קִר; (Isaiah 22:5), or (feminine) קִירָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2351>/H9011', 'inflected', 'heb', 'וחוצה', '["va./Chu.tza/h"]', '["and/ [the] outside/ towards"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4733}/[H7038]', 'inflected', 'heb', 'מִקְלָט', '["miqlâṭ"]', '["<the>/ refuge"]', '["n-m"]', 'an asylum (as a receptacle) refuge.', 'from 7038 in the sense of taking in;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7523}/[H7523]', 'inflected', 'heb', 'רָצַח', '["râtsach"]', '["<the>/ murdered","the/ killer","the/ murderer"]', '["v"]', 'properly, to dash in pieces, i.e. kill (a human being), especially to murder put to death, kill, (man-) slay(-er), murder(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5921A}/H9038/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["and/ [was] on/ them","and/ [was] over/ them","and/ [were] on/ them","and/ on/ them","and/ over/ them","and/ to/ them","and/ with/ them"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4054}/H9029/[H1644]', 'inflected', 'heb', 'מִגְרָשׁ', '["migrâsh"]', '["pasture lands/ their"]', '["n-m"]', 'a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb.', 'also (in plural) feminine (Ezekiel 27:28) מִגְרָשָׁה; from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0272}/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["from/ [the] possession of"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4592}/[H4591]', 'inflected', 'heb', 'מְעַט', '["mᵉʻaṭ"]', '["[were] the/ few","the/ few"]', '["n-m"]', 'a little or few (often adverbial or comparative) almost (some, very) few(-er, -est), lightly, little (while), (very) small (matter, thing), some, soon, × very.', 'or מְעָט; from 4591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5892B}/H9023/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["from/ cities/ its","from/ city/ his","some of/ cities/ its"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3881}\/[H3878]', 'inflected', 'heb', 'לֵוִיִּי', '["Lêvîyîy"]', '["to the/ Levites"]', '["a"]', 'a Levite or descendant of Levi Leviite.', 'or לֵוִי; patronymically from 3878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4733}/[H7038]', 'lemma', 'heb', 'מִקְלָט', '["miqlâṭ"]', '["<the> refuge of","refuge"]', '["n-m"]', 'an asylum (as a receptacle) refuge.', 'from 7038 in the sense of taking in;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7523}/[H7523]', 'lemma', 'heb', 'רָצַח', '["râtsach"]', '["I will be killed","[is] a killer","a killer","a murderer","he will kill","killer","murderers","someone will kill","they murder","will you murder?","you will be murdered"]', '["v"]', 'properly, to dash in pieces, i.e. kill (a human being), especially to murder put to death, kill, (man-) slay(-er), murder(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4733}/[H7038]', 'inflected', 'heb', 'מִקְלָט', '["miqlâṭ"]', '["<into>/ a refuge"]', '["n-m"]', 'an asylum (as a receptacle) refuge.', 'from 7038 in the sense of taking in;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1350H}/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["from/ [the] avenger of","from/ an avenger"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5975G}/H9043/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["stands/ he"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4941G}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["for <the>/ judgment","for/ [the] judgment of","for/ judgment","to <the>/ judgment","to/ judgment"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8453A}/[H3427]', 'inflected', 'heb', 'תּוֹשָׁב', '["tôwshâb"]', '["and/ for the/ resident alien"]', '["n-m"]', 'a dweller but not outlandish [5237]; especially (as distinguished from a native citizen [active participle of 3427] and a temporary inmate [1616] or mere lodger [3885]) resident alien foreigner, inhabitant, sojourner, stranger.', 'or תֹּשָׁב; (1 Kings 17:1), from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1270}/[H1269]', 'lemma', 'heb', 'בַּרְזֶל', '["barzel"]', '["[are] iron","[will be] iron","iron"]', '["n-m"]', 'iron (as cutting); by extension, an iron implement (ax) head, iron.', 'perhaps from the root of 1269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027O}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350H}/[H1350]', 'lemma', 'heb', 'גָּאַל', '["gâʼal"]', '["[the] avenger of"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6293}/H9043/[H6293]', 'inflected', 'heb', 'פָּגַע', '["pâgaʻ"]', '["when/ meets/ he"]', '["v"]', 'to impinge, by accident or violence, or (figuratively) by importunity come (betwixt), cause to entreat, fall (upon), make intercession, intercessor, intreat, lay, light (upon), meet (together), pray, reach, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8135}/[H8130]', 'inflected', 'heb', 'שִׂנְאָה', '["sinʼâh"]', '["in/ [the] hatred of","in/ hatred"]', '["n-f"]', 'hate exceedingly, hate(-ful, -red).', 'from 8130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1920}/H9033/[H1920]', 'inflected', 'heb', 'הָדַף', '["hâdaph"]', '["he pushed/ him","he will push/ him","people drive/ him"]', '["v"]', 'to push away or down cast away (out), drive, expel, thrust (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6660}/[H6658]', 'inflected', 'heb', 'צְדִיָּה', '["tsᵉdîyâh"]', '["with/ lying in wait"]', '["n-f"]', 'design lying in wait.', 'from 6658; (compare 6656)');
