INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0342}/[H340]', 'lemma', 'heb', 'אֵיבָה', '["ʼêybâh"]', '["enmity","enmity of"]', '["n-f"]', 'hostility emnity, hatred.', 'from 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6660}/[H6658]', 'lemma', 'heb', 'צְדִיָּה', '["tsᵉdîyâh"]', '["lying in wait"]', '["n-f"]', 'design lying in wait.', 'from 6658; (compare 6656)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451C}/H9023/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["harm/ his"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4733}/H9023/[H7038]', 'inflected', 'heb', 'מִקְלָט', '["miqlâṭ"]', '["refuge/ his"]', '["n-m"]', 'an asylum (as a receptacle) refuge.', 'from 7038 in the sense of taking in;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318I}/[H3318]', 'lemma', 'heb', 'יָצָא', '["yâtsâʼ"]', '["[the] going out of","he will go out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7523}/[H7523]', 'inflected', 'heb', 'רָצַח', '["râtsach"]', '["and/ he will kill"]', '["v"]', 'properly, to dash in pieces, i.e. kill (a human being), especially to murder put to death, kill, (man-) slay(-er), murder(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6310I}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["to/ [the] mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315H}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["for/ [the] life of"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2610}/[H2610]', 'lemma', 'heb', 'חָנֵף', '["chânêph"]', '["certainly <to be polluted>","he will pollute","it has been polluted","it pollutes","let her be polluted","they are polluted","will it be polluted","you will pollute"]', '["v"]', 'to soil, especially in a moral sense corrupt, defile, × greatly, pollute, profane.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0776G>', 'inflected', 'heb', 'ולארץ', '["ve./la./''A.retz"]', '["and/ for the/ land"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8210H}/H9033/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["[the] [one who] shed/ it"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0001G}/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["the/ ancestors","the/ fathers","the/ parent"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4940}/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["[was] from/ [the] clan of","from/ [the] clan of","from/ [the] clans of","from/ [the] tribe of","from/ a clan","of/ [the] clan of","of/ [the] clans of","of/ [the] tribe of","one of/ [the] clans of"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5159}/H9029/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["inheritance/ their"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H1486>', 'inflected', 'heb', 'ומגרל', '["u./mi./go.Ral"]', '["and/ from/ [the] lot of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5159}/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["and/ from/ [the] inheritance of"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2896A}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["<into>/ good","for/ good","to the/ good","to the/ good [people]","to/ [the] good [place] of","to/ a [person] good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1692}/[H1692]', 'lemma', 'heb', 'דָּבַק', '["dâbaq"]', '["I have clung","I have made cling","I will make stick","[has been] made to cling to","he cleaved","he clung","he will make cling","it clings","it has cleaved","it has clung","it has stuck","it stuck","it will cling","it will pursue closely","may it cleave","she clung","they are joined together","they cling","they clung","they will hold","you will cleave","you will cling"]', '["v"]', 'properly, to impinge, i.e. cling or adhere; figuratively, to catch by pursuit abide fast, cleave (fast together), follow close (hard after), be joined (together), keep (fast), overtake, pursue hard, stick, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5159}/H9023/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["on/ own inheritance/ his","on/ own inheritance/ its"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8656G}/[H7521]', 'lemma', 'heb', 'תִּרְצָה', '["Tirtsâh"]', '["Tirzah"]', '["n-pr-f"]', 'Tirtsah, a place in Palestine; also an Israelitess Tirzah.', 'from 7521; delightsomeness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1730I>/H9029', 'opaque', 'heb', 'דּוֹד', '["dôwd"]', '["uncles/ their"]', '["n-m"]', '(figuratively) to love; by implication, a love-token, lover, friend; specifically an uncle (well-) beloved, father''s brother, love, uncle.', 'or (shortened) דֹּד; from an unused root meaning properly, to boil, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6160G}/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["in the/ Arabah","in the/ desert plain"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5489}/[H5488]', 'lemma', 'heb', 'סוּף', '["Çûwph"]', '["Suph"]', '["n-pr-loc"]', 'the Reed (Sea) Red Sea.', 'for 5488 (by ellipsis of 3220);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8603}/[H8602]', 'lemma', 'heb', 'תֹּפֶל', '["Tôphel"]', '["Tophel"]', '["n-pr-loc"]', 'Tophel, a place near the Desert Tophel.', 'from the same as 8602; quagmire;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3837B}/[H3836]', 'inflected', 'heb', 'לָבָן', '["Lâbân"]', '["and/ Laban"]', '["n-pr-m n-pr-loc"]', 'Laban, a Mesopotamian; also a place in the Desert Laban.', 'the same as 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2698}/[H2691]', 'inflected', 'heb', 'חֲצֵרוֹת', '["Chătsêrôwth"]', '["and/ Hazeroth"]', '["n-pr-loc"]', 'Chatseroth, a place in Palestine Hazeroth.', 'feminine plural of 2691; yards;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1774}/[H1768]', 'inflected', 'heb', 'דִּי זָהָב', '["Dîy zâhâb"]', '["and/ Di"]', '["n-pr-loc"]', 'Dizahab, a place in the Desert Dizahab.', 'as if from 1768 and 2091; of gold;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1774}/[H1768]', 'lemma', 'heb', 'דִּי זָהָב', '["Dîy zâhâb"]', '["Zahab"]', '["n-pr-loc"]', 'Dizahab, a place in the Desert Dizahab.', 'as if from 1768 and 2091; of gold;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2722}/[H2717]', 'inflected', 'heb', 'חֹרֵב', '["Chôrêb"]', '["from/ Horeb"]', '["n-pr-loc"]', 'Choreb, a (generic) name for the Sinaitic mountains Horeb.', 'from 2717; desolate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8165G}/[H8163]', 'lemma', 'heb', 'שֵׂעִיר', '["Sêʻîyr"]', '["Seir"]', '["n-pr"]', 'Seir, a mountain of Idumaea and its aboriginal occupants, also one in Palestine Seir.', 'formed like 8163; rough;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0705}/[H702]', 'inflected', 'heb', 'אַרְבָּעִים', '["ʼarbâʻîym"]', '["among/ forty","in/ forty"]', '["n"]', 'forty forty.', 'multiple of 702;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6249}/[H6247]', 'inflected', 'heb', 'עַשְׁתֵּי', '["ʻashtêy"]', '["in/ [the] one [plus]","in/ one [plus]"]', '["n"]', 'eleven or (ordinal) eleventh eleven(-th).', 'apparently masculine plural construction of 6247 in the sense of an afterthought (used only in connection with 6240 in lieu of 259)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5221}/H9043/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["had defeated/ he"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6252H}/[H6251]', 'inflected', 'heb', 'עַשְׁתָּרוֹת', '["ʻAshtârôwth"]', '["[was] in/ Ashtaroth","in/ Ashtaroth"]', '["n-pr-f"]', 'Ashtaroth, the name of a Sidonian deity, and of a place East of the Jordan Asharoth, Astaroth. See also 1045, 6253, 6255.', 'or עַשְׁתָּרֹת; plural of 6251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0154}/[H153]', 'inflected', 'heb', 'אֶדְרֶעִי', '["ʼedreʻîy"]', '["in/ Edrei"]', '["n-pr-loc"]', 'Edrei, the name of two places in Palestine Edrei.', 'from the equivalent of 153; mighty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0874}/[H874]', 'lemma', 'heb', 'בָּאַר', '["bâʼar"]', '["he made clear","surely clearly"]', '["v"]', 'to dig; by analogy, to engrave; figuratively, to explain declare, (make) plain(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7934}/H9023/[H7931]', 'inflected', 'heb', 'שָׁכֵן', '["shâkên"]', '["neighbors/ its"]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8219}/[H8213]', 'inflected', 'heb', 'שְׁפֵלָה', '["shᵉphêlâh"]', '["and/ in the/ Shephelah"]', '["n-f"]', 'Lowland, i.e. (with the article) the maritime slope of Palestine low country, (low) plain, vale(-ley).', 'from 8213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H5045G>', 'inflected', 'heb', 'ובנגב', '["u./va./Ne.gev"]', '["and/ in the/ Negev"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H2348>', 'inflected', 'heb', 'ובחוף', '["u./ve./Chof"]', '["and/ on/ [the] coast of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3844G}/[H3825]', 'inflected', 'heb', 'לְבָנוֹן', '["Lᵉbânôwn"]', '["and/ <the>/ Lebanon","and/ the/ Lebanon"]', '["n-pr-loc"]', 'Lebanon, a mountain range in Palestine Lebanon.', 'from 3825; (the) white mountain (from its snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0001G}/H9026/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["for/ ancestors/ your","to/ ancestors/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2233H}/H9028/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ to/ offspring/ their"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2009}/H9046/[H2005]', 'inflected', 'heb', 'הִנֵּה', '["hinnêh"]', '["and/ here/ you"]', '["dp"]', 'lo! behold, lo, see.', 'prolongation for 2005;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0349B}/[H335]', 'lemma', 'heb', 'אֵיךְ', '["ʼêyk"]', '["how!","how?","where?"]', '["adv"]', 'how? or how!; also where how, what.', 'also אֵיכָה ; and אֵיכָכָה ; prolonged from 335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2960}/H9026/[H2959]', 'inflected', 'heb', 'טֹרַח', '["ṭôrach"]', '["burden/ your"]', '["n-m"]', 'a burden cumbrance, trouble.', 'from 2959;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4853A}/H9026/[H5375]', 'inflected', 'heb', 'מַשָּׂא', '["massâʼ"]', '["and/ burden/ your"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7379}/H9026/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["and/ dispute[s]/ your"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0995}/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["and/ I want to understand","and/ [one] discerning of","and/ a discerning [one]","and/ consider carefully","and/ consider diligently","and/ he may understand","and/ he will pay attention","and/ let him understand","and/ let them consider carefully","and/ understand","and/ understanding","and/ understanding [one] of","and/ you may perceive"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7626H>/H9026', 'inflected', 'heb', 'לשבטיכם', '["le./shiv.tei./Khem"]', '["for/ tribes/ your","of/ tribes/ your","to/ tribes/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7760L}/H9038/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["so/ I may appoint/ them"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7218H>/H9026', 'inflected', 'heb', 'בראשיכם', '["be./ra.shei./Khem"]', '["<in>/ chiefs/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7626H>/H9026', 'opaque', 'heb', 'שֵׁבֶט', '["shêbeṭ"]', '["tribes/ your"]', '["n-m"]', 'a scion, i.e. (literally) a stick (for punishing, writing, fighting, ruling, walking, etc.) or (figuratively) a clan × correction, dart, rod, sceptre, staff, tribe.', 'from an unused root probably meaning to branch off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7860>', 'inflected', 'heb', 'ושטרים', '["ve./sho.te.Rim"]', '["and/ [will be] officials","and/ officials"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8199}/H9036/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["judges/ your"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251I}/H9026/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["brothers/ your","countrymen/ your","relatives/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1616}/H9023/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["sojourner/ his"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6996B}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["as the/ small"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1419A}/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["as the/ great"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1481C}/[H1481]', 'lemma', 'heb', 'גּוּר', '["gûwr"]', '["I was afraid","be afraid","let them be afraid","they are afraid","they will be afraid","you will be afraid"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1697L}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ the/ matter"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7126H}/H9013/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["you will bring near/ !"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8085G}/H9033/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ I will hear/ it"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3372G}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["and/ <the>/ awesome"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2865}/[H2865]', 'lemma', 'heb', 'חָתַת', '["châthath"]', '["I be dismayed","[which] it is cracked","he was in awe","it has been shattered","it is dismayed","it will be shattered","let them be dismayed","they are dismayed","they were dismayed","they will be dismayed","they will be shattered","they will be terrified","you be dismayed","you must be dismayed","you will shatter"]', '["v"]', 'properly, to prostrate; hence, to break down, either (literally) by violence, or (figuratively) by confusion and fear abolish, affright, be (make) afraid, amaze, beat down, discourage, (cause to) dismay, go down, scare, terrify.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7126G}/H9013/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["and/ you drew near/ !"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3605}/H9026/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["O all of/ you","all of/ you"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2658}/[H2658]', 'inflected', 'heb', 'חָפַר', '["châphar"]', '["so/ they may spy out"]', '["v"]', 'properly, to pry into; by implication, to delve, to explore dig, paw, search out, seek.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869I}/H9020/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7626H>', 'inflected', 'heb', 'לשבטי', '["la./Sha.vet","le./She.vet","le./shiv.Tei"]', '["of/ [the] tribe of","of/ a tribe","to the/ tribe","to/ [the] tribe of","to/ [the] tribes of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7270}/[H7272]', 'inflected', 'heb', 'רָגַל', '["râgal"]', '["and/ he has slandered","and/ they spied out"]', '["v"]', 'to walk along; but only in specifically, applications, to reconnoiter, to be a tale-bearer (i.e. slander); to lead about backbite, search, slander, (e-) spy (out), teach to go, view.', 'a primitive root; also as denominative from 7272');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4784}/[H4784]', 'inflected', 'heb', 'מָרָה', '["mârâh"]', '["and/ it has rebelled against","and/ they rebelled","and/ they rebelled against","and/ they were disobedient","and/ you rebelled against","and/ you rebelled toward","and/ you will rebel","and/ you will rebel against"]', '["v"]', 'to be (causatively, make) bitter (or unpleasant); (figuratively) to rebel (or resist; causatively, to provoke) bitter, change, be disobedient, disobey, grievously, provocation, provoke(-ing), (be) rebel (against, -lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7279}/[H7279]', 'inflected', 'heb', 'רָגַן', '["râgan"]', '["and/ they murmured","and/ you murmured"]', '["v"]', 'to grumble, i.e. rebel murmur.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0168G}/H9026/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["in/ tents/ your"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8045}/H9035/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["to/ destroy/ us"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4549}/[H4549]', 'lemma', 'heb', 'מָסַס', '["mâçaç"]', '["he will melt","it has melted","it will be melted","it will melt","surely <melt>","they have made melt","they melt"]', '["v"]', 'to liquefy; figuratively, to waste (with disease), to faint (with fatigue, fear or grief) discourage, faint, be loosed, melt (away), refuse, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3824}/H9025/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["heart/ our"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1219}/[H1210]', 'inflected', 'heb', 'בָּצַר', '["bâtsar"]', '["and/ fortified","and/ incomprehensible [things]"]', '["v"]', 'to gather grapes; also to be isolated (i.e. inaccessible by height or fortification) cut off, (de-) fenced, fortify, (grape) gather(-er), mighty things, restrain, strong, wall (up), withhold.', 'a primitive root; to clip off; specifically (as denominative from 1210)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6062}/[H6061]', 'lemma', 'heb', 'עֲנָקִי', '["ʻĂnâqîy"]', '["Anakites","[the] Anakites"]', '["a"]', 'an Anakite or descendant of Anak Anakim.', 'patronymically from 6061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6206}/H9013/[H6206]', 'inflected', 'heb', 'עָרַץ', '["ʻârats"]', '["you must be terrified/ !"]', '["v"]', 'to awe or (intransitive) to dread; hence, to harass be affrighted (afraid, dread, feared, terrified), break, dread, fear, oppress, prevail, shake terribly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3372G}/H9013/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["you must be afraid/ !"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869J}/H9026/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375H}/H9031/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["he carried/ you","it will carry away/ you"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9046/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["came/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1697G}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ by the/ word","and/ in the/ thing"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0369}/H9046/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["[are] not/ you","not/ you"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2583}/H9036/[H2603]', 'inflected', 'heb', 'חָנָה', '["chânâh"]', '["to/ camp/ you"]', '["v"]', 'properly, to incline; by implication, to decline (of the slanting rays of evening); specifically, to pitch a tent; generally to encamp (for abode or siege) abide (in tents), camp, dwell, encamp, grow to an end, lie, pitch (tent), rest in tent.', 'a primitive root (compare 2603);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7200G}/H9036/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["to/ show/ you"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6051}/[H6049]', 'inflected', 'heb', 'עָנָן', '["ʻânân"]', '["and/ in the/ cloud"]', '["n-m"]', 'a cloud (as covering the sky), i.e. the nimbus or thunder-cloud cloud(-y).', 'from 6049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2108}/[H2107]', 'lemma', 'heb', 'זוּלָה', '["zûwlâh"]', '["except"]', '["n-f"]', 'probably scattering, i.e. removal; used adverbially, except beside, but, only, save.', 'from 2107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1121G}/H9023/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ to/ descendants/ his","and/ to/ sons/ his"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0599}/[H599]', 'lemma', 'heb', 'אָנַף', '["ʼânaph"]', '["he should be angry","he was angry","will you be angry","will you be angry?","you have been angry","you were angry"]', '["v"]', 'to breathe hard, i.e. be enraged be angry (displeased).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1558}/H9036/[H1556]', 'inflected', 'heb', 'גָּלָל', '["gâlâl"]', '["on/ account of/ you"]', '["n-m"]', 'a circumstance (as rolled around); only used adverbially, on account of because of, for (sake).', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5975G}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["[is] the/ [one who will] stand","[were] the/ [ones who] stood","the/ [one] standing","those/ [who] are standing","those/ [who] were standing","which/ were standing","who/ stand","who/ stands","who/ stood","who/ was standing","who/ were standing","who/ were standing by"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5157}/H9034/[H5157]', 'inflected', 'heb', 'נָחַל', '["nâchal"]', '["he will give as an inheritance/ it","they will inherit/ it","you will give as an inheritance/ it"]', '["v"]', 'to inherit (as a (figurative) mode of descent), or (generally) to occupy; causatively, to bequeath, or (generally) distribute, instate divide, have (inheritance), take as a heritage, (cause to, give to, make to) inherit, (distribute for, divide (for, for an, by), give for, have, leave for, take (for)) inheritance, (have in, cause to, be made to) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870J}/[H1869]', 'lemma', 'heb', 'דֶּרֶךְ', '["derek"]', '["[is] [the] direction","[is] [the] direction of","[the] direction","[the] direction of","[the] road","[the] road of","[the] way","[the] way of","[was] [the] direction","[was] [the] direction of","[were] [the] direction of","[will be] [the] direction of","a way of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6680}/H9035/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["he commanded/ us","he has commanded/ us","you have commanded/ us"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4421}/H9023/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["war/ his","warfare/ his","wars/ his"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1951}/[H1951]', 'inflected', 'heb', 'הוּן', '["hûwn"]', '["and/ you regarded as easy"]', '["v"]', 'properly, to be naught, i.e. (figuratively) to be (causatively, act) light be ready.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122H}/H9036/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ you"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1682}/[H1696]', 'inflected', 'heb', 'דְּבוֹרָה', '["dᵉbôwrâh"]', '["<the>/ bees"]', '["n-f"]', 'the bee (from its systematic instincts) bee.', 'or (shortened) דְּבֹרָה; from 1696 (in the sense of orderly motion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3807}/[H3807]', 'inflected', 'heb', 'כָּתַת', '["kâthath"]', '["and/ I crushed","and/ I will crush","and/ he crushed to pieces","and/ they scattered","and/ they were crushed","and/ they will beat","and/ they will crush"]', '["v"]', 'to bruise or violently strike beat (down, to pieces), break in pieces, crushed, destroy, discomfit, smite, stamp. l', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8165A}/[H8163]', 'inflected', 'heb', 'שֵׂעִיר', '["Sêʻîyr"]', '["in/ Seir"]', '["n-pr"]', 'Seir, a mountain of Idumaea and its aboriginal occupants, also one in Palestine Seir.', 'formed like 8163; rough;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2767}/[H2763]', 'lemma', 'heb', 'חׇרְמָה', '["Chormâh"]', '["Hormah"]', '["n-pr-loc"]', 'Chormah, a place in Palestine Hormah.', 'from 2763; devoted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963A>/H9026', 'inflected', 'heb', 'בקלכם', '["be./Ko.le./Khem","ve./ko.le./Khem"]', '["to/ voice/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5437H}/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["and/ he caused to go around","and/ he surrounded","and/ he went around","and/ he went round","and/ it turns","and/ it went around","and/ they surrounded","and/ they surrounded [him]","and/ they surrounded [it]","and/ they turned round","and/ they went around","and/ they went round","and/ they will surround","and/ we went around","and/ you will go around"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3372G}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["and/ [is] to be feared","and/ awesome","and/ they may fear","so/ it may be afraid","so/ they may be afraid","so/ you may fear"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8104J}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ they will take care","and/ you have kept","and/ you will keep","and/ you will take care","and/ you will take heed"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1624}/[H1624]', 'lemma', 'heb', 'גָּרָה', '["gârâh"]', '["he stirs up","he will get ready","they engage in strife","they will wage war","will you engage in strife","you engage in strife","you engaged in strife"]', '["v"]', 'properly, to grate, i.e. (figuratively) to anger contend, meddle, stir up, strive.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0776G>/H9028', 'inflected', 'heb', 'מארצם', '["me./''ar.Tza/m"]', '["any of/ land/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4096}/[H1869]', 'lemma', 'heb', 'מִדְרָךְ', '["midrâk"]', '["a treading place of"]', '["n-m"]', 'a treading, i.e. a place for stepping on (foot-) breadth.', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3709H}/[H3721]', 'lemma', 'heb', 'כַּף', '["kaph"]', '["[the] sole of","[the] soles of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3425}/[H3423]', 'lemma', 'heb', 'יְרֻשָּׁה', '["yᵉrushshâh"]', '["[the] possession of","a possession","a possession of"]', '["n-f"]', 'something occupied; a conquest; also a patrimony heritage, inheritance, possession.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6215H}/[H6213]', 'inflected', 'heb', 'עֵשָׂו', '["ʻÊsâv"]', '["to/ Esau"]', '["n-pr-m"]', 'Esav, a son of Isaac, including his posterity Esau.', 'apparently a form of the passive participle of 6213 in the original sense of handling; rough (i.e. sensibly felt);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3739A}/[H3738]', 'lemma', 'heb', 'כָּרָה', '["kârâh"]', '["will they bargain?","you will buy"]', '["v"]', 'to purchase buy, prepare.', 'usually assigned as a primitive root, but probably only a special application of 3738 (through the common idea of planning implied in a bargain);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980G}/H9041/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["walking/ you"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1870K}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["from/ [the] path","from/ [the] road","from/ [the] way of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6160G}/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["the/ Arabah","the/ desert plain"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0359A}/[H352]', 'inflected', 'heb', 'אֵילוֹת', '["ʼÊylôwth"]', '["from/ Elath"]', '["n-pr-loc"]', 'Eloth or Elath, a place on the Red Sea Elath, Eloth.', 'or אֵילַת ; from 352; trees or a grove (i.e. palms);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6100}/[H6096]', 'inflected', 'heb', 'עֶצְיוֹן גֶּבֶר', '["ʻEtsyôwn Geber"]', '["and/ from/ Ezion"]', '["n-pr-loc"]', 'Etsjon-Geber, a place on the Red Sea Ezion-geber.', 'from 6096 and 1397; backbone-like of a man;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6100}\/[H6096]', 'inflected', 'heb', 'עֶצְיוֹן גֶּבֶר', '["ʻEtsyôwn Geber"]', '["Geber"]', '["n-pr-loc"]', 'Etsjon-Geber, a place on the Red Sea Ezion-geber.', 'from 6096 and 1397; backbone-like of a man;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6696B}/[H6696]', 'lemma', 'heb', 'צוּר', '["tsûwr"]', '["you may provoke"]', '["v"]', 'to cramp, i.e. confine (in many applications, literally and figuratively, formative or hostile) adversary, assault, beset, besiege, bind (up), cast, distress, fashion, fortify, inclose, lay siege, put up in bags.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6062}/[H6061]', 'inflected', 'heb', 'עֲנָקִי', '["ʻĂnâqîy"]', '["like the/ Anakites"]', '["a"]', 'an Anakite or descendant of Anak Anakim.', 'patronymically from 6061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2803J}/[H2803]', 'lemma', 'heb', 'חָשַׁב', '["châshab"]', '["I have thought about","I thought about","anyone considers","are we regarded","do you consider","do you plan","he is considered","it considers","it was regarded","it will be considered","they are regarded","they were regarded","to be accounted","will he be regarded"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4125}/[H4124]', 'inflected', 'heb', 'מוֹאָבִי', '["Môwʼâbîy"]', '["and/ the/ Moabites"]', '["a"]', 'a Moabite or Moabitess, i.e. a descendant from Moab (woman) of Moab, Moabite(-ish, -ss).', 'feminine מוֹאָבִיָּה; or מוֹאָבִיתxlit Môwâbîyth corrected to Môwʼâbîyth; patronymical from 4124;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0368}/[H367]', 'lemma', 'heb', 'אֵימִים', '["ʼÊymîym"]', '["Emites"]', '["n-pr-m"]', 'Emim, an early Canaanitish (or Maobitish) tribe Emims.', 'plural of 367; terrors;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8165A}/[H8163]', 'inflected', 'heb', 'שֵׂעִיר', '["Sêʻîyr"]', '["and/ in/ Seir"]', '["n-pr"]', 'Seir, a mountain of Idumaea and its aboriginal occupants, also one in Palestine Seir.', 'formed like 8163; rough;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8045}/H9038/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["and/ I destroyed/ them","and/ he destroyed/ them","and/ they destroyed/ them","and/ you have destroyed/ them"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478H}/H9038/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["in place of/ them"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3425}/H9023/[H3423]', 'inflected', 'heb', 'יְרֻשָּׁה', '["yᵉrushshâh"]', '["possession/ its"]', '["n-f"]', 'something occupied; a conquest; also a patrimony heritage, inheritance, possession.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5674A}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["and/ [who] passes","and/ let him pass over","and/ let it pass","and/ pass on","and/ pass over","and/ they may cause to pass","so/ he may pass on","so/ let us pass over","so/ let us pass over [you]","so/ they may pass away"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5158N}/[H5157]', 'lemma', 'heb', 'נַחַל', '["nachal"]', '["[the] wadi","[the] wadi of","a wadi"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2000}/H9038/[H1949]', 'inflected', 'heb', 'הָמַם', '["hâmam"]', '["to/ disturb/ them","to/ trouble/ them"]', '["v"]', 'properly, to put in commotion; by implication, to disturb, drive, destroy break, consume, crush, destroy, discomfit, trouble, vex.', 'a primitive root (compare 1949, 1993);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8552}/H9048/[H8552]', 'inflected', 'heb', 'תָּמַם', '["tâmam"]', '["are finished/ they","were complete/ they","were finished/ they"]', '["v"]', 'to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6696B}/H9038/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["you provoke/ them"]', '["v"]', 'to cramp, i.e. confine (in many applications, literally and figuratively, formative or hostile) adversary, assault, beset, besiege, bind (up), cast, distress, fashion, fortify, inclose, lay siege, put up in bags.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5984H}/[H5983]', 'inflected', 'heb', 'עַמּוֹנִי', '["ʻAmmôwnîy"]', '["and/ the/ Ammonites"]', '["a"]', 'an Ammonite or (the adjective) Ammonitish Ammonite(-s).', 'patronymically from 5983;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2157}/[H2161]', 'lemma', 'heb', 'זַמְזֹם', '["Zamzôm"]', '["Zamzummites"]', '["n-pr-m"]', 'a Zamzumite, or native tribe of Palestine Zamzummim.', 'from 2161; intriguing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3423H}/H9038/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["and/ I will dispossess/ them","and/ he had dispossessed/ them","and/ they dispossessed/ them","and/ you will dispossess/ them"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5761G}/[H5757]', 'inflected', 'heb', 'עַוִּים', '["ʻAvvîym"]', '["and/ the/ Avvite[s]","and/ the/ Avvites"]', '["n-pr-m n-pr-loc"]', 'Avvim (as inhabited by Avvites), a place in Palestine (with the article prefix) Avim.', 'plural of 5757;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2691B}/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["in/ [the] villages of","in/ villages"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3732}/[H3731]', 'lemma', 'heb', 'כַּפְתֹּרִי', '["Kaphtôrîy"]', '["[the] Caphtorites"]', '["a"]', 'a Caphtorite (collectively) or native of Caphtor Caphthorim, Caphtorim(-s).', 'patrial from 3731;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3731}/[H3730]', 'inflected', 'heb', 'כַּפְתֹּר', '["Kaphtôr"]', '["from/ Caphtor"]', '["n-pr-loc"]', 'Caphtor (i.e. a wreath-shaped island), the original seat of the Philistines Caphtor.', 'or (Amos 9:7) כַּפְתּוֹר; apparently the same as 3730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8045}/H9038/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["he will destroy/ them","they destroyed/ them","to destroy/ them"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1624}/[H1624]', 'inflected', 'heb', 'גָּרָה', '["gârâh"]', '["and/ engage in strife","so/ it may wage war"]', '["v"]', 'properly, to grate, i.e. (figuratively) to anger contend, meddle, stir up, strive.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6343}/H9021/[H6342]', 'inflected', 'heb', 'פַּחַד', '["pachad"]', '["dread/ your"]', '["n-m"]', 'a (sudden) alarm (properly, the object feared, by implication, the feeling) dread(-ful), fear, (thing) great (fear, -ly feared), terror.', 'from 6342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3374}/H9021/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["and/ fear/ your"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7264}/[H7264]', 'inflected', 'heb', 'רָגַז', '["râgaz"]', '["and/ he rages","and/ he was agitated","and/ it quaked","and/ it trembled","and/ they have quaked","and/ they will tremble","and/ to cause disquiet","and/ you were enraged"]', '["v"]', 'to quiver (with any violent emotion, especially anger or fear) be afraid, stand in awe, disquiet, fall out, fret, move, provoke, quake, rage, shake, tremble, trouble, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2342I}/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["and/ he was in severe pain","and/ it writhed","and/ they will be in anguish"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6932}/[H6923]', 'lemma', 'heb', 'קְדֵמוֹת', '["Qᵉdêmôwth"]', '["Kedemoth"]', '["n-pr-loc"]', 'Kedemoth, a place in eastern Palestine Kedemoth.', 'from 6923; beginnings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7666}/H9030/[H7668]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["you will sell/ me"]', '["v"]', 'to deal in grain buy, sell.', 'denominative from 7668;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6144}/[H5892]', 'inflected', 'heb', 'עָר', '["ʻÂr"]', '["in/ Ar"]', '["n-pr-loc"]', 'Ar, a place in Moab Ar.', 'the same as 5892; a city;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0553}/[H553]', 'inflected', 'heb', 'אָמַץ', '["ʼâmats"]', '["and/ he had made obstinate","and/ he made hard","and/ he strengthened [it]","and/ she strengthened","and/ they proved themselves strong","and/ they strengthened","and/ they were strong"]', '["v"]', 'to be alert, physically (on foot) or mentally (in courage) confirm, be courageous (of good courage, stedfastly minded, strong, stronger), establish, fortify, harden, increase, prevail, strengthen (self), make strong (obstinate, speed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3824}/H9023/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["[one who] heart/ his","heart/ his","heart/ its","own heart/ his"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122H}/H9035/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ us"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414G}/H9033/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will give/ him","and/ I will give/ it","and/ he delivered up/ him","and/ he gave/ him","and/ he gave/ it","and/ he has given/ him","and/ he will give/ him","and/ she gave/ it","and/ they have put/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2945}/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["and/ the/ little one[s]"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7998}/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["and/ [the] booty of","and/ [the] plunder of","and/ booty","and/ gain","and/ plunder"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3920}/[H3920]', 'lemma', 'heb', 'לָכַד', '["lâkad"]', '["I have captured","I should take","[who] catches","he captured","he had captured","he had taken","he is captured","he was captured","he will be caught","it catches [something]","it had captured","it has been captured","it has been caught","it has caught [something]","it was captured","it will be captured","they are caught","they catch","they freeze","they grasp one another","they may capture","they will be caught","we had captured","you have been caught","you were caught","you will be captured"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6177H}/[H6176]', 'inflected', 'heb', 'עֲרוֹעֵר', '["ʻĂrôwʻêr"]', '["from/ Aroer"]', '["n-pr-loc"]', 'Aroër, the name of three places in or near Palestine Aroer.', 'or עֲרֹעֵר; or עַרְעוֹר; the same as 6176; nudity of situation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7151}/[H7136]', 'lemma', 'heb', 'קִרְיָה', '["qiryâh"]', '["O town","[is] [the] town of","[is] a town of","[the] town","[the] town of","a town","a town of"]', '["n-f"]', 'a city city.', 'from 7136 in the sense of flooring, i.e. building;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7682}/[H7682]', 'lemma', 'heb', 'שָׂגַב', '["sâgab"]', '["[is] exalted","he is exalted","he will be set on high","high","it is set on high","it was [too] high","set on high","they are high"]', '["v"]', 'to be (causatively, make) lofty, especially inaccessible; by implication, safe, strong; used literally and figuratively defend, exalt, be excellent, (be, set on) high, lofty, be safe, set up (on high), be too strong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440L}/H9025/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ us"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2256M}/[H2254]', 'lemma', 'heb', 'חֶבֶל', '["chebel"]', '["[is] [the] measured portion of","[the] allotted portions of","[the] cord of","[the] cords of","[the] portion of","[the] region","[the] region of","[the] ropes of","a company of","a cord of","a measuring-line","boundary lines","measured portions","measuring-lines","ropes"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0709G}/[H7263]', 'lemma', 'heb', 'אַרְגֹּב', '["ʼArgôb"]', '["Argob"]', '["n-pr-loc n-pr-m"]', 'Argob, a district of Palestine Argob.', 'from the same as 7263; stony;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1316>', 'inflected', 'heb', 'בבשן', '["ba./ba.Shan","va./ba.Shan"]', '["[are] in <the>/ Bashan","[is] in <the>/ Bashan","in <the>/ Bashan"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1364}/[H1361]', 'lemma', 'heb', 'גָּבֹהַּ', '["gâbôahh"]', '["[he was] tall","[person] haughty of","[the] haughty of","[the] height of","[was] high","[were] high","a high [one]","exalted [one]","haughty","high","proud [people]","tall"]', '["a"]', 'elevated (or elated), powerful, arrogant haughty, height, high(-er), lofty, proud, × exceeding proudly.', 'or גָּבוֹהַּ; (fully) from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1817C}/[H1802]', 'lemma', 'heb', 'דֶּלֶת', '["deleth"]', '["[is] a door","[the] doors","[the] doors of","a pair of gates","doors","doors of","gates","gates of","leaves"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1280}/[H1272]', 'inflected', 'heb', 'בְּרִיחַ', '["bᵉrîyach"]', '["and/ bar[s]","and/ bar[s] of","and/ bars","and/ bars of"]', '["n-m"]', 'a bolt bar, fugitive.', 'from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6521}/[H6519]', 'inflected', 'heb', 'פְּרָזִי', '["pᵉrâzîy"]', '["the/ hamlet-dweller[s]","the/ rural villagers"]', '["n-m"]', 'a rustic village.', 'or פְּרוֹזִי; from 6519;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5158N}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["from/ [the] wadi of"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2768}/[H2763]', 'lemma', 'heb', 'חֶרְמוֹן', '["Chermôwn"]', '["Hermon","[is] Hermon"]', '["n-pr-m"]', 'Chermon, a mount of Palestine Hermon.', 'from 2763; abrupt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6722}/[H6721]', 'lemma', 'heb', 'צִידֹנִי', '["Tsîydônîy"]', '["Sidonian [women]","[the] Sidonian[s]","[the] Sidonians"]', '["a"]', 'a Tsidonian or inhabitant of Tsidon Sidonian, of Sidon, Zidonian.', 'patrial from 6721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2768}/[H2763]', 'inflected', 'heb', 'חֶרְמוֹן', '["Chermôwn"]', '["<to>/ Hermon"]', '["n-pr-m"]', 'Chermon, a mount of Palestine Hermon.', 'from 2763; abrupt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8303}/[H8302]', 'lemma', 'heb', 'שִׁרְיוֹן', '["Shiryôwn"]', '["Sirion"]', '["n-pr-loc"]', 'Shirjon or Sirjon, a peak of the Lebanon Sirion.', 'and שִׂרְיֹן; the same as 8302 (i.e. sheeted with snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8149>', 'opaque', 'heb', 'שְׁנִיר', '["Shᵉnîyr"]', '["Senir"]', '["n-pr"]', 'Shenir or Senir, a summit of Lebanon Senir, Shenir.', 'or שְׂנִיר; from an unused root meaning to be pointed; peak;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4334}/[H3474]', 'inflected', 'heb', 'מִישׁוֹר', '["mîyshôwr"]', '["the/ plain"]', '["n-m"]', 'a level, i.e. a plain (often used (with the article prefix) as a proper name of certain districts); figuratively, concord; also straightness, i.e. (figuratively) justice (sometimes adverbially, justly) equity, even place, plain, right(-eously), (made) straight, uprightness.', 'or מִישֹׁר; from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5548>', 'opaque', 'heb', 'סַלְכָה', '["Çalkâh"]', '["Salecah"]', '["n-pr-loc"]', 'Salcah, a place East of the Jordan Salcah, Salchah.', 'from an unused root. meaning to walk; walking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0154}/[H153]', 'inflected', 'heb', 'אֶדְרֶעִי', '["ʼedreʻîy"]', '["and/ Edrei"]', '["n-pr-loc"]', 'Edrei, the name of two places in Palestine Edrei.', 'from the equivalent of 153; mighty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3499A}/[H3498]', 'inflected', 'heb', 'יֶתֶר', '["yether"]', '["from/ [the] remnant of","one of/ [the] remnant of"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6210>/H9023', 'opaque', 'heb', 'עֶרֶשׂ', '["ʻeres"]', '["sarcophagus/ his"]', '["n-f"]', 'a couch (properly, with a canopy) bed(-stead), couch.', 'from an unused root meaning perhaps to arch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6210>', 'opaque', 'heb', 'עֶרֶשׂ', '["ʻeres"]', '["[the] couch of","[was] a sarcophagus of","a couch","a couch of"]', '["n-f"]', 'a couch (properly, with a canopy) bed(-stead), couch.', 'from an unused root meaning perhaps to arch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7237}/[H7227]', 'inflected', 'heb', 'רַבָּה', '["Rabbâh"]', '["against/ Rabbah","against/ Rabbah of","in/ Rabbah of"]', '["n-pr-loc"]', 'Rabbah, the name of two places in Palestine, East and West Rabbah, Rabbath.', 'feminine of 7227; great;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5892B}/H9023/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["and/ cities/ its"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7206}/[H7205]', 'inflected', 'heb', 'רְאוּבֵנִי', '["Rᵉʼûwbênîy"]', '["<to> the/ Reubenite[s]","for the/ Reubenite[s]","of the/ Reubenite[s]","to the/ Reubenite[s]"]', '["a"]', 'a Reubenite or descendant of Reuben children of Reuben, Reubenites.', 'patronymic from 7205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1425}/[H1410]', 'inflected', 'heb', 'גָּדִי', '["Gâdîy"]', '["and/ <to> the/ Gadite[s]","and/ to the/ Gadite[s]"]', '["a"]', 'a Gadite (collectively) or descendants of Gad Gadites, children of Gad.', 'patronymically from 1410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2677}/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["for/ [the] half of","into the/ half","to/ [the] half of"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4519G}/[H5382]', 'inflected', 'heb', 'מְנַשֶּׁה', '["Mᵉnashsheh"]', '["<the>/ Manasseh"]', '["n-pr-m"]', 'Menashsheh, a grandson of Jacob, also the tribe descended from him, and its territory Manasseh.', 'from 5382; causing to forget;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0709G}/[H7263]', 'inflected', 'heb', 'אַרְגֹּב', '["ʼArgôb"]', '["<the>/ Argob"]', '["n-pr-loc n-pr-m"]', 'Argob, a district of Palestine Argob.', 'from the same as 7263; stony;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2971G}/[H215]', 'lemma', 'heb', 'יָאִיר', '["Yâʼîyr"]', '["Jair"]', '["n-pr-m"]', 'Jair, the name of four Israelites Jair.', 'from 215; enlightener;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1651}/[H1650]', 'inflected', 'heb', 'גְּשׁוּרִי', '["Gᵉshûwrîy"]', '["the/ Geshurite[s]"]', '["a"]', 'a Geshurite (also collectively) or inhabitants of Geshur Geshuri, Geshurites.', 'patrial from 1650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4602}/[H4601]', 'inflected', 'heb', 'מַעֲכָתִי', '["Maʻăkâthîy"]', '["and/ the/ Maacathite[s]"]', '["a"]', 'a Maakathite, or inhabitant of Maakah Maachathite.', 'patrial from 4601;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4353G}/[H4376]', 'inflected', 'heb', 'מָכִיר', '["Mâkîyr"]', '["and/ to/ Makir"]', '["n-pr-m"]', 'Makir, an Israelite Machir.', 'from 4376; salesman;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7206}/[H7205]', 'inflected', 'heb', 'רְאוּבֵנִי', '["Rᵉʼûwbênîy"]', '["and/ to the/ Reubenite[s]"]', '["a"]', 'a Reubenite or descendant of Reuben children of Reuben, Reubenites.', 'patronymic from 7205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6160G}/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["and/ the/ Arabah"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3383}/[H3381]', 'inflected', 'heb', 'יַרְדֵּן', '["Yardên"]', '["and/ the/ Jordan"]', '["n-pr"]', 'Jarden, the principal river of Palestine Jordan.', 'from 3381; a descender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3672G}/[H3658]', 'inflected', 'heb', 'כִּנְּרוֹת', '["Kinnᵉrôwth"]', '["from/ Kinnereth"]', '["n-pr-loc"]', 'Kinneroth or Kinnereth, a place in Palestine Chinnereth, Chinneroth, Cinneroth.', 'or כִּנֶּרֶתlemma כִּנֶרֶת missing dagesh, corrected to כִּנֶּרֶת; respectively plural and singular feminine from the same as 3658; perhaps harp-shaped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0798}/[H794]', 'lemma', 'heb', 'אַשְׁדּוֹת הַפִּסְגָּה', '["ʼAshdôwth hap-Piçgâh"]', '["[the] slopes of"]', '["n-pr-loc"]', 'Ashdoth-Pisgah, a place east of the Jordan Ashdoth-pisgah.', 'from the plural of 794 and 6449 with the article interposed; ravines of the Pisgah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4735}/H9026/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["and/ livestock/ your"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5892B}/H9026/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["in/ cities/ your"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251I}/H9026/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["for/ countrymen/ your","of/ countrymen/ your","to/ brothers/ your","to/ countrymen/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3425}/H9023/[H3423]', 'inflected', 'heb', 'יְרֻשָּׁה', '["yᵉrushshâh"]', '["to/ possession/ his"]', '["n-f"]', 'something occupied; a conquest; also a patrimony heritage, inheritance, possession.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4467}/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["<the>/ kingdoms","<the>/ royalty","the/ kingdom","the/ kingdoms","the/ kingdoms of"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3898A}/[H3898]', 'inflected', 'heb', 'לָחַם', '["lâcham"]', '["[is] the/ [one who] fights","[is] the/ [one who] has been fighting","[is] the/ [one who] will fight","who/ are fighting"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1433}/H9021/[H1431]', 'inflected', 'heb', 'גֹּדֶל', '["gôdel"]', '["greatness/ your"]', '["n-m"]', 'magnitude (literally or figuratively) greatness, stout(-ness).', 'from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2389}/[H2388]', 'inflected', 'heb', 'חָזָק', '["châzâq"]', '["<the>/ mighty","<the>/ severe","<the>/ strong","the/ strong [one]"]', '["a"]', 'strong (usu. in a bad sense, hard, bold, violent) harder, hottest, impudent, loud, mighty, sore, stiff(-hearted), strong(-er).', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4639G}/H9021/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["[are] like/ works/ your","like/ works/ your"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H1369}/H9021/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["and/ like/ mighty deeds/ your"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5674B}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["and/ he was furious"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4616}/H9036/[H6030]', 'inflected', 'heb', 'מַעַן', '["maʻan"]', '["for sake/ your","on account of/ you"]', '["prt"]', 'properly, heed, i.e. purpose; used only adverbially, on account of (as a motive or an aim), teleologically, in order that because of, to the end (intent) that, for (to,... ''s sake), lest, that, to.', 'from 6030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1697I}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<in>/ a matter","by the/ matter","in the/ matter","in the/ thing","in/ [the] matter of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5375M}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ lift up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8486}/H9011/[H3225]', 'inflected', 'heb', 'תֵּימָן', '["têymân"]', '["and/ south/ -ward"]', '["n-f"]', 'the south (as being on the right hand of a person facing the east) south (side, -ward, wind).', 'or תֵּמָן; denominative from 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4217H}/H9011/[H2224]', 'inflected', 'heb', 'מִזְרָח', '["mizrâch"]', '["and/ east/ -ward"]', '["n-m"]', 'sunrise, i.e. the east east (side, -ward), (sun-) rising (of the sun).', 'from 2224;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869A}/H9021/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ own eyes/ your","in/ view/ your","with/ eyes/ your","with/ own eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6680}/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["and/ a commander of","and/ command","and/ commission"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2388G}/H9033/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ encourage/ him"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0553}/H9033/[H553]', 'inflected', 'heb', 'אָמַץ', '["ʼâmats"]', '["and/ strengthen/ him"]', '["v"]', 'to be alert, physically (on foot) or mentally (in courage) confirm, be courageous (of good courage, stedfastly minded, strong, stronger), establish, fortify, harden, increase, prevail, strengthen (self), make strong (obstinate, speed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1516R}/[H1466]', 'inflected', 'heb', 'גַּיְא', '["gayʼ"]', '["[are] in/ [the] valley of","in the/ valley","in/ [the] valley of","in/ a valley of"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1047}/[H1004]', 'lemma', 'heb', 'בֵּית פְּעוֹר', '["Bêyth Pᵉʻôwr"]', '["Beth","Peor"]', '["n-pr-loc"]', 'Beth-Peor, a place East of the Jordan Bethpeor.', 'from 1004 and 6465; house of Peor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1047}\/[H1004]', 'inflected', 'heb', 'בֵּית פְּעוֹר', '["Bêyth Pᵉʻôwr"]', '["Peor"]', '["n-pr-loc"]', 'Beth-Peor, a place East of the Jordan Bethpeor.', 'from 1004 and 6465; house of Peor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3925G}/[H3925]', 'lemma', 'heb', 'לָמַד', '["lâmad"]', '["I have taught","I will teach","[am] about to teach","[are] trained of","[he has] trained","[which] has been taught","he taught","it had been trained","they have taught","they may teach","they will learn","they will teach","trained","trained of","will anyone teach","you have taught","you taught"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1187}/[H1168]', 'inflected', 'heb', 'בַּעַל פְּעוֹר', '["Baʻal Pᵉʻôwr"]', '["at/ Baal"]', '["n-pr-m"]', 'Baal-Peor, a Moabitish deity Baal-peor.', 'from 1168 and 6465; Baal of Peor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8045}/H9033/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["he destroyed/ him","he had destroyed/ him","he had destroyed/ it"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1695}/[H1692]', 'inflected', 'heb', 'דָּבֵק', '["dâbêq"]', '["who/ were clinging"]', '["a"]', 'adhering cleave, joining, stick closer.', 'from 1692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6680}/H9030/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["he commanded/ me","you command/ me","you have commanded/ me"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2451}/H9026/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["[will be] wisdom/ your"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0998}/H9026/[H995]', 'inflected', 'heb', 'בִּינָה', '["bîynâh"]', '["and/ understanding/ your"]', '["n-f"]', 'understanding knowledge, meaning, × perfectly, understanding, wisdom.', 'from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121G}/H9045/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["call out/ we","calling/ we"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8104G}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ I will keep","and/ [one who] keeps","and/ [those who] keep","and/ [who] keeps","and/ guard","and/ keep","so/ <it> may be kept","so/ let me keep","so/ they may keep"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315G}/H9021/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["being/ your","desire/ your","life/ your","self/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7911}/[H7911]', 'lemma', 'heb', 'שָׁכַח', '["shâkach"]', '["I forget","I have been forgotten","I have forgotten","I have forgotten [them]","I will forget","O [those who] forget","[those who] forget","certainly [if] <to forget>","do you forget?","forgotten","he has caused to be forgotten","he has forgotten","he will be forgotten","he will forget","it has been forgotten","it is forgotten","it will be forgotten","may it forget","she forgets","she forgot","they forgot","they have forgotten","they should forget","they will be forgotten","they will forget","we had forgotten","you forget","you have forgotten","you must forget","you should forget","you will forget"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6435}/[H6437]', 'inflected', 'heb', 'פֵּן', '["pên"]', '["and/ lest"]', '["conj"]', 'properly, removal; used only (in the construction) adverb as conjunction, lest (lest) (peradventure), that...not.', 'from 6437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3824}/H9021/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["from/ heart/ your"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3045}/H9038/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["and/ we have known/ them","and/ you will make known/ them"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0559}/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["in/ [those who] said","when/ said","when/ say"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8085G}/H9038/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["so/ I may make hear/ them"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3925H}/H9013/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["they will learn/ !"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3372H}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["to/ fear"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121A}/H9028/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["children/ their","sons/ their","young/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3925G}/H9013/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["they will teach/ !"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5975G}/H9013/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ you stood/ !"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2022G}/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["and/ the/ mountain","and/ the/ mountains"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6205}/[H6201]', 'inflected', 'heb', 'עֲרָפֶל', '["ʻărâphel"]', '["and/ thick darkness"]', '["n-m"]', 'gloom (as of a lowering sky) (gross, thick) dark (cloud, -ness).', 'probably from 6201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3789}/H9038/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["and/ he inscribed/ them","and/ he recorded/ them","and/ you will write/ them"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0853}/H9030/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ <obj.>/ me"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3925G}/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["to/ teach"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6213A}/H9036/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["to/ observe/ you"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315I}/H9026/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["to/ selves/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7843}/H9013/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["you should act corruptly/ !","you will act corruptly/ !"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5566>', 'opaque', 'heb', 'סֶמֶל', '["çemel"]', '["[the] idol of","figure"]', '["n-m"]', 'a likeness figure, idol, image.', 'or סֵמֶל; from an unused root meaning to resemble;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0127G}/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["in the/ land","on the/ ground"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1710}/[H1709]', 'lemma', 'heb', 'דָּגָה', '["dâgâh"]', '["[the] fish of","fish"]', '["n-f"]', 'fish.', 'feminine of 1709, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3394}/[H3391]', 'inflected', 'heb', 'יָרֵחַ', '["yârêach"]', '["the/ moon"]', '["n-m"]', 'the moon moon. Yrechow. See 3405.', 'from the same as 3391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5080}/[H5080]', 'inflected', 'heb', 'נָדַח', '["nâdach"]', '["and/ I will drive out","and/ he enticed away","and/ he thrust aside","and/ he will thrust","and/ it will be impelled","and/ they have thrust aside","and/ you will be drawn aside","and/ you will be driven away"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5647H}/H9038/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ he served/ them","and/ they served/ them","and/ they will serve/ them","and/ you will serve/ them"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3564>', 'inflected', 'heb', 'מכור', '["mi./Kur"]', '["from/ [the] furnace of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697M}/H9026/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1115}/[H1086]', 'inflected', 'heb', 'בִּלְתִּי', '["biltîy"]', '["and/ to/ not"]', '["np"]', 'properly, a failure of, i.e. (used only as a negative particle, usually with a prepositional prefix) not, except, without, unless, besides, because not, until, etc. because un(satiable), beside, but, continual, except, from, lest, neither, no more, none, not, nothing, save, that no, without.', 'constructive feminine of 1086 (equivalent to 1097);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7067H}\/[H7065]', 'inflected', 'heb', 'קַנָּא', '["qannâʼ"]', '["jealous"]', '["a"]', 'jealous jealous. Compare 7072.', 'from 7065;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3707}/H9033/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["to/ provoke to anger/ him"]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0006}/H9013/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["you will destroy/ !","you will perish/ !"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117L>', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["[is] a day of","day","days"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8045}/H9013/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["you will be destroyed/ !"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200G}/H9013/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["they see/ !"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7306}/H9013/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["they smell/ !"]', '["v"]', 'properly, to blow, i.e. breathe; only (literally) to smell or (by implication, perceive (figuratively, to anticipate, enjoy) accept, smell, × touch, make of quick understanding.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6862B}/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["in <the>/ distress","in the/ distress","in/ [the] distress of","in/ distress","when <the>/ it is distress","when <the>/ it was distress"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4672}/H9031/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["and/ I have found/ you","and/ they will come upon/ you","and/ they will find/ you"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7503}/H9031/[H7503]', 'inflected', 'heb', 'רָפָה', '["râphâh"]', '["I will abandon/ you","he will abandon/ you"]', '["v"]', 'to slacken (in many applications, literal or figurative) abate, cease, consume, draw (toward evening), fail, (be) faint, be (wax) feeble, forsake, idle, leave, let alone (go, down), (be) slack, stay, be still, be slothful, (be) weak(-en). See 7495.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7843}/H9031/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["he destroy/ you","he will destroy/ you","it will destroy/ you","to destroy/ you"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/H9006/{H7097A}/[H7096]', 'inflected', 'heb', 'קָצֶה', '["qâtseh"]', '["and/ to/ from/ [the] end of"]', '["n-m"]', 'an extremity × after, border, brim, brink, edge, end, (in-) finite, frontier, outmost coast, quarter, shore, (out-) side, × some, ut(-ter-) most (part).', 'or (negative only) קֵצֶה; from 7096; (used in a great variety of applications and idioms; compare 7093)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1961}/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["¿/ has it happened","¿/ will it happen"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H8085G}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["¿/ has it been heard","¿/ has it heard","¿/ is it heard"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5254H}/[H5254]', 'inflected', 'heb', 'נָסָה', '["nâçâh"]', '["¿/ did someone attempt","¿/ has it attempted"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4531B}/[H5254]', 'inflected', 'heb', 'מַסָּה', '["maççâh"]', '["by/ trials"]', '["n-f"]', 'a testing, of men (judicial) or of God (querulous) temptation, trial.', 'from 5254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0226G}/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["by/ signs"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4159}/[H3302]', 'inflected', 'heb', 'מוֹפֵת', '["môwphêth"]', '["and/ by/ wonders"]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4421}/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["and/ by/ battle","and/ in/ battle","and/ with/ battles of"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2220}/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["and/ by/ [the] arm of","and/ by/ an arm"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4172A}/[H3372]', 'inflected', 'heb', 'מוֹרָא', '["môwrâʼ"]', '["and/ by/ terror","and/ by/ terrors","and/ with/ terror"]', '["n-m"]', 'fear; by implication, a fearful thing or deed dread, (that ought to be) fear(-ed), terribleness, terror.', 'or מֹרָא; or מוֹרָהxlit môrâh corrected to môwrâh; (Psalm 9:20), from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H0905J}/H9033/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["from/ to/ alone/ him"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3256}/H9031/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["to/ discipline/ you"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0784}/H9023/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["fire/ his"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1697G}/H9023/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ words/ his"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8478J}/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["and/ because"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2233H}/H9023/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["<in>/ offspring/ his"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318H}/H9031/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ he brought out/ you"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6440H}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["by/ own presence/ his","in/ face/ his","in/ face/ its","with/ face/ his"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3581B>/H9023', 'inflected', 'heb', 'בכחו', '["be./kho.Ch/o","be./kho.ch/o","ve./kho.Ch/o"]', '["by/ own power/ his","by/ power/ his","by/ strength/ his","in/ power/ his","with/ power/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0935P}/H9031/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["to/ bring in/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776G>/H9028', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["land/ their"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725N}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ they will bring back","and/ you will bring [them] back","and/ you will bring back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3117G>\', 'inflected', 'heb', 'הימים פ', '["hai./Yom","hai./ya.Mim"]', '["the/ day","the/ days","this/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8121>', 'opaque', 'heb', 'שֶׁמֶשׁ', '["shemesh"]', '["O sun","[is] a sun","[the] sun","a sun of","sun"]', '["n"]', 'the sun; by implication, the east; figuratively, a ray, i.e. (architectural) a notched battlement east side(-ward), sun (rising), west(-ward), window. See also 1053.', 'from an unused root meaning to be brilliant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1097}/[H1086]', 'inflected', 'heb', 'בְּלִי', '["bᵉlîy"]', '["with/ no","with/ not"]', '["np"]', 'properly, failure, i.e. nothing or destruction; usually (with preposition) without, not yet, because not, as long as, etc. corruption, ig(norantly), for lack of, where no...is, so that no, none, not, un(awares), without.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1221G}/[H1220]', 'lemma', 'heb', 'בֶּצֶר', '["Betser"]', '["Bezer"]', '["n-pr-m n-pr-loc"]', 'Betser, a place in Palestine; also an Israelite Bezer.', 'the same as 1220, an inaccessible spot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7216H}/[H7215]', 'lemma', 'heb', 'רָאמוֹת', '["Râʼmôwth"]', '["Ramoth"]', '["n-pr-loc"]', 'Ramoth, the name of two places in Palestine Ramoth.', 'or רָאמֹתxlit Râmôth corrected to Râʼmôth; plural of 7215; heights;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1568G}/[H1567]', 'inflected', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["[are] in <the>/ Gilead","[is] in <the>/ Gilead","in <the>/ Gilead","in/ Gilead"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1425}/[H1410]', 'inflected', 'heb', 'גָּדִי', '["Gâdîy"]', '["for the/ Gadite[s]"]', '["a"]', 'a Gadite (collectively) or descendants of Gad Gadites, children of Gad.', 'patronymically from 1410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1474}/[H1473]', 'lemma', 'heb', 'גּוֹלָן', '["Gôwlân"]', '["Golan"]', '["n-pr-loc"]', 'Golan, a place east of the Jordan Golan.', 'from 1473; captive;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4520}/[H4519]', 'inflected', 'heb', 'מְנַשִּׁי', '["Mᵉnashshîy"]', '["for the/ Manassite[s]"]', '["a"]', 'a Menashshite or descendant of Menashsheh of Manasseh, Manassites.', 'from 4519;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5713B}/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["[are] the/ testimonies"]', '["n-f"]', 'testimony testimony, witness. Compare 5712.', 'feminine of 5707 in its techn. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2706G}/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["and/ the/ conditions","and/ the/ statutes"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4217H}/[H2224]', 'lemma', 'heb', 'מִזְרָח', '["mizrâch"]', '["[the] east","[the] east of","[the] rising of","east"]', '["n-m"]', 'sunrise, i.e. the east east (side, -ward), (sun-) rising (of the sun).', 'from 2224;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7865}/[H7863]', 'lemma', 'heb', 'שִׂיאֹן', '["Sîyʼôn"]', '["Siyon"]', '["n-pr"]', 'Sion, the summit of Mount Hermon Sion.', 'from 7863; peak;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6449}\/[H6448]', 'inflected', 'heb', 'פִּסְגָּה', '["Piçgâh"]', '["<the>/ Pisgah"]', '["n-pr-loc"]', 'Pisgah, a Mountain East of Jordan Pisgah.', 'from 6448; a cleft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241H}/H9026/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["in/ ears/ your"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3925H}/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["and/ it learned","and/ they learned","and/ they will learn","and/ you will learn"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6213A}/H9038/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["to/ do/ them","to/ observe/ them"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6440H}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["on/ face"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7794}/H9021/[H7788]', 'inflected', 'heb', 'שׁוֹר', '["shôwr"]', '["and/ ox/ your"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7723G}\/[H7722]', 'inflected', 'heb', 'שָׁוְא', '["shâvᵉʼ"]', '["falsehood"]', '["n-m"]', 'evil (as destructive), literally (ruin) or morally (especially guile); figuratively idolatry (as false, subjective), uselessness (as deceptive, objective; also adverbially, in vain) false(-ly), lie, lying, vain, vanity.', 'or שַׁו; from the same as 7722 in the sense of desolating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7453}/H9021\/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["neighbor/ your"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7794}/H9023/[H7788]', 'inflected', 'heb', 'שׁוֹר', '["shôwr"]', '["bull/ his","ox/ his","ox[en]/ his"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6951}/H9026/[H6950]', 'inflected', 'heb', 'קָהָל', '["qâhâl"]', '["assembly/ your"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6205}/[H6201]', 'inflected', 'heb', 'עֲרָפֶל', '["ʻărâphel"]', '["and/ the/ thick darkness"]', '["n-m"]', 'gloom (as of a lowering sky) (gross, thick) dark (cloud, -ness).', 'probably from 6201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8085G}/H9046/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["just as/ hear/ you","when/ hear/ you","when/ heard/ you"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2205G}/H9026/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["and/ elders/ your"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200G}/H9035/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["[is] seeing/ us","he has shown/ us","he showed/ us","show/ us","will he show/ us"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3519}/H9023/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["[is] glory/ his","glory/ his","glory/ its","honor/ his"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1433}/H9023/[H1431]', 'inflected', 'heb', 'גֹּדֶל', '["gôdel"]', '["greatness/ his"]', '["n-m"]', 'magnitude (literally or figuratively) greatness, stout(-ness).', 'from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1696G}/H9046/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["when/ spoke/ you"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1121G}/H9028/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ for/ children/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0168G}/H9026/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["to/ tents/ your"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3925G}/H9038/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["I will teach/ them","they taught/ them","you will teach/ them"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2421}/H9013/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["you may live/ !"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2895}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["and/ it will be good","and/ will be good"]', '["v"]', 'to be (transitively, do or make) good (or well) in the widest sense be (do) better, cheer, be (do, seem) good, (make) goodly, × please, (be, do, go, play) well.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0748}/[H748]', 'inflected', 'heb', 'אָרַךְ', '["ʼârak"]', '["and/ I will make long","and/ they became long","and/ they were long","and/ you will prolong"]', '["v"]', 'to be (causative, make) long (literally or figuratively) defer, draw out, lengthen, (be, become, make, pro-) long, (out-, over-) live, tarry (long).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117K>', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["[the] days of","day","days"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423H}/H9013/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["you will take possession of/ !"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4687}/H9023/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["and/ commandments/ his"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7235A}/H9013/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["they will be numerous/ !","they will increase/ !","you will increase/ !"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1706>\', 'inflected', 'heb', 'ודבש פ', '["u./de.Vash"]', '["and/ honey"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3966}/H9021/[H181]', 'inflected', 'heb', 'מְאֹד', '["mᵉʼôd"]', '["strength/ your"]', '["a"]', 'properly, vehemence, i.e. (with or without preposition) vehemently; by implication, wholly, speedily, etc. (often with other words as an intensive or superlative; especially when repeated) diligently, especially, exceeding(-ly), far, fast, good, great(-ly), × louder and louder, might(-ily, -y), (so) much, quickly, (so) sore, utterly, very ( much, sore), well.', 'from the same as 181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8150}/H9038/[H8150]', 'inflected', 'heb', 'שָׁנַן', '["shânan"]', '["and/ you will repeat/ them"]', '["v"]', 'to point (transitive or intransitive); intensively, to pierce; figuratively, to inculcate prick, sharp(-en), teach diligently, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3427}/H9041/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["when/ sitting down/ you","when/ sitting/ you"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1980I}/H9041/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ when/ walking/ you"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7901G}/H9041/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ when/ lying down/ you"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6965B}/H9041/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ when/ rising up/ you"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7194}/H9038/[H7194]', 'inflected', 'heb', 'קָשַׁר', '["qâshar"]', '["and/ you will tie/ them"]', '["v"]', 'to tie, physically (gird, confine, compact) or mentally (in love, league) bind (up), (make a) conspire(-acy, -ator), join together, knit, stronger, work (treason).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2903>', 'inflected', 'heb', 'לטוטפת', '["le./to.ta.Fot"]', '["for/ marks"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4201}/[H2123]', 'lemma', 'heb', 'מְזוּזָה', '["mᵉzûwzâh"]', '["[the] doorpost of","[the] doorposts of","a doorpost of","doorposts of"]', '["n-f"]', 'a door-post (as prominent) (door, side) post.', 'or מְזֻזָה; from the same as 2123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8179G}/H9021\/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["and/ on/ gates/ your"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2672}/[H2672]', 'lemma', 'heb', 'חָצַב', '["châtsab"]', '["I will cut [them] in pieces","[is] striking","[which] you were dug","digging out","dug out","he dug out","she has hewn","stone cutters","stone-cutter[s]","you dug","you have dug out","you will dig"]', '["v"]', 'to cut or carve (wood, stone or other material); by implication, to hew, split, square, quarry, engrave cut, dig, divide, grave, hew (out, -er), made, mason.', 'or חָצֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2132H>', 'inflected', 'heb', 'וזיתים', '["ve./zei.Tim"]', '["and/ olive trees"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7646}/[H7646]', 'inflected', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["and/ I satisfied","and/ I will be surfeited","and/ I will satisfy","and/ he was satisfied","and/ he will satisfy","and/ it will be satisfied","and/ she was satisfied","and/ they were satisfied","and/ they will be satisfied","and/ we were satisfied","and/ you will be satisfied"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8034}/H9023/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["and/ in/ name/ his"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980N}/H9013/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["you will walk/ !"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0430J}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["any of/ [the] gods of","some of/ [the] gods of"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8045}/H9031/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["and/ he will destroy/ you"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4532}/[H4531]', 'inflected', 'heb', 'מַסָּה', '["Maççâh"]', '["at <the>/ Massah","at/ Massah"]', '["n-pr-loc"]', 'Massah, a place in the Desert Massah.', 'the same as 4531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104G}/H9013/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["you will keep/ !"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5713B}/H9023/[H5707]', 'inflected', 'heb', 'עֵדָה', '["ʻêdâh"]', '["and/ testimonies/ his"]', '["n-f"]', 'testimony testimony, witness. Compare 5712.', 'feminine of 5707 in its techn. sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2706G}/H9023/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["and/ statutes/ his"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3477G}/[H3474]', 'inflected', 'heb', 'יָשָׁר', '["yâshâr"]', '["<the>/ [place] right","the/ [place] right","the/ right","the/ upright [person]"]', '["a"]', 'straight (literally or figuratively) convenient, equity, Jasher, just, meet(-est), pleased well right(-eous), straight, (most) upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2896A}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["and/ the/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1920}/[H1920]', 'inflected', 'heb', 'הָדַף', '["hâdaph"]', '["to/ drive out"]', '["v"]', 'to push away or down cast away (out), drive, expel, thrust (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0226G}/[H225]', 'lemma', 'heb', 'אוֹת', '["ʼôwth"]', '["[will be the] sign","[will be] a sign","a sign","signs"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4159}/[H3302]', 'inflected', 'heb', 'מוֹפֵת', '["môwphêth"]', '["and/ a portent","and/ a sign","and/ wonders"]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7451A}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["and/ bad","and/ calamities"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869J}/H9025/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ our"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0853}/H9035/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ <obj.>/ us"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6680}/H9035/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["and/ he commanded/ us"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2896B}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["for/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2421}/H9035/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["to/ preserve alive/ us"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9009/<H3117L>', 'inflected', 'heb', 'כהיום', '["ke./hai./Yom","khe./hai./Yom"]', '["as/ the/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6666}/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["and/ [the] righteousness of","and/ a right","and/ righteousness"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6680}/H9035\/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["he commanded/ us"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5394}/[H5394]', 'inflected', 'heb', 'נָשַׁל', '["nâshal"]', '["and/ he cleared out","and/ he will clear away","and/ it will slip off"]', '["v"]', 'to pluck off, i.e. divest, eject or drop cast (out), drive, loose, put off (out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H1622>', 'inflected', 'heb', 'והגרגשי', '["ve./ha./gir.ga.Shi"]', '["and/ the/ Girgashite[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2603A}/H9038/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["you will show favor to/ them"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2859B}/[H2859]', 'lemma', 'heb', 'חָתַן', '["châthan"]', '["[is] to be son-in-law","be son-in-law","you will be a son-in-law","you will intermarry"]', '["v"]', 'to give (a daughter) away in marriage; hence (generally) to contract affinity by marriage join in affinity, father in law, make marriages, mother in law, son in law.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0310A}/H9030/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["from/ after/ me"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4676}/H9028/[H5324]', 'inflected', 'heb', 'מַצֵּבָה', '["matstsêbâh"]', '["and/ sacred pillars/ their"]', '["n-f"]', 'something stationed, i.e. a column or (memorial stone); by analogy, an idol garrison, (standing) image, pillar.', 'feminine (causatively) participle of 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0842}/H9028/[H833]', 'inflected', 'heb', 'אֲשֵׁרָה', '["ʼăshêrâh"]', '["and/ Asherah poles/ their"]', '["n-pr-f"]', 'Asherah (or Astarte) a Phoenician goddess; also an image of the same grove. Compare 6253.', 'or אֲשֵׁירָה; from 833; happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1438}/H9013/[H1438]', 'inflected', 'heb', 'גָּדַע', '["gâdaʻ"]', '["you will cut down/ !"]', '["v"]', 'to fell a tree; generally, to destroy anything cut (asunder, in sunder, down, off), hew down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6456}/H9028/[H6458]', 'inflected', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["and/ images/ their"]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8313}/H9013/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["you will burn/ !"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7231}/H9046/[H7241]', 'inflected', 'heb', 'רָבַב', '["râbab"]', '["because /were numerous/ you"]', '["v"]', 'properly, to cast together , i.e. increase, especially in number; to multiply by the myriad increase, be many(-ifold), be more, multiply, ten thousands.', 'a primitive root; (compare 7241); also as denominative from 7233;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0160}/[H158]', 'inflected', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["from/ [the] love of","more than/ [the] love","more than/ [the] love of","more than/ love"]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8104G}/H9043/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ <from>/ because kept/ he"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6299}/H9031/[H6299]', 'inflected', 'heb', 'פָּדָה', '["pâdâh"]', '["and/ I will ransom/ you","and/ he redeemed/ you"]', '["v"]', 'to sever, i.e. ransom; generally to release, preserve × at all, deliver, × by any means, ransom, (that are to be, let be) redeem(-ed), rescue, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2617A}/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["and/ <the>/ covenant loyalty"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0157G}/H9033/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["to/ [those who] love/ him"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7999A}/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["and/ I may repay","and/ I may restore","and/ [is] repaying","and/ [those who] repay","and/ [who] pays back","and/ [who] repays","and/ pay","and/ pay [them]","so/ I may pay","so/ let me repay","so/ let us pay"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8130}/H9033/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["to/ [the] [one who] hates/ him","to/ [those who] hate/ him"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0006}/H9033/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["by/ destroying/ him","to/ destroy/ it"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6213A}/H9038\/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["to/ observe/ them"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0157G}/H9031/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ he will love/ you"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0990H>/H9021', 'opaque', 'heb', 'בֶּטֶן', '["beṭen"]', '["womb/ your"]', '["n-f"]', 'the belly, especially the womb; also the bosom or body of anything belly, body, as they be born, within, womb.', 'from an unused root probably meaning to be hollow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6529}/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["and/ [the] fruit of"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1715}/H9021/[H1711]', 'inflected', 'heb', 'דָּגָן', '["dâgân"]', '["grain/ your"]', '["n-m"]', 'properly, increase, i.e. grain corn (floor), wheat.', 'from 1711;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8492}/H9021/[H3423]', 'inflected', 'heb', 'תִּירוֹשׁ', '["tîyrôwsh"]', '["and/ new wine/ your"]', '["n-m"]', 'must or fresh grape-juice (as just squeezed out); by implication (rarely) fermented wine (new, sweet) wine.', 'or תִּירֹשׁ; from 3423 in the sense of expulsion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3323}/H9021/[H6671]', 'inflected', 'heb', 'יִצְהָר', '["yitshâr"]', '["and/ fresh oil/ your"]', '["n-m"]', 'oil (as producing light); figuratively, anointing anointed oil.', 'from 6671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0504}/H9021/[H502]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["cattle<s>/ your"]', '["n-m"]', 'a family; also (from the sense of yoking or taming) an ox or cow family, kine, oxen.', 'from 502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6251}/[H6238]', 'inflected', 'heb', 'עַשְׁתְּרָה', '["ʻashtᵉrâh"]', '["and/ [the] young ones of"]', '["n-f"]', 'increase flock.', 'probably from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H0929>/H9021', 'inflected', 'heb', 'ובבהמתך', '["u./vi/v.hem.Te./kha"]', '["and/ among/ livestock/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2483}/[H2470]', 'lemma', 'heb', 'חֳלִי', '["chŏlîy"]', '["[is] a sickness","sickness"]', '["n-m"]', 'malady, anxiety, calamity disease, grief, (is) sick(-ness).', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4064}/[H1738]', 'lemma', 'heb', 'מַדְוֶה', '["madveh"]', '["<the> disease of","[the] diseases of"]', '["n-m"]', 'sickness disease.', 'from 1738;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760H}/H9038/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["he will put/ them"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4170}/[H3369]', 'lemma', 'heb', 'מוֹקֵשׁ', '["môwqêsh"]', '["[are] [the] snare of","[the] snares of","[will be] a snare","a snare","a snare of","snares"]', '["n-m"]', 'a noose (for catching animals) (literally or figuratively); by implication, a hook (for the nose) be ensnared, gin, (is) snare(-d), trap.', 'or מֹקֵשׁ; from 3369;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3423H}/H9038/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["to/ dispossess/ them"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4531B}/[H5254]', 'inflected', 'heb', 'מַסָּה', '["maççâh"]', '["the/ trials"]', '["n-f"]', 'a testing, of men (judicial) or of God (querulous) temptation, trial.', 'from 5254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0226G}/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["and/ the/ signs"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4159}/[H3302]', 'inflected', 'heb', 'מוֹפֵת', '["môwphêth"]', '["and/ the/ wonder","and/ the/ wonders"]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3027H}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ the/ hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2220}/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["and/ the/ arm"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5186}/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["<the>/ outstretched","the/ [one who] stretched out","the/ [one] stretched out","which/ is stretched out"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440L}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["of/ <before>/ them"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5641}/[H5641]', 'inflected', 'heb', 'סָתַר', '["çâthar"]', '["and/ [those] who/ hide themselves"]', '["v"]', 'to hide (by covering), literally or figuratively be absent, keep close, conceal, hide (self), (keep) secret, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440L}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6206}/[H6206]', 'lemma', 'heb', 'עָרַץ', '["ʻârats"]', '["I feared","[is] awesome","they will regard with awe","will you terrify","you be terrified","you must be terrified","you must regard with awe","you will inspire awe"]', '["v"]', 'to awe or (intransitive) to dread; hence, to harass be affrighted (afraid, dread, feared, terrified), break, dread, fear, oppress, prevail, shake terribly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3372H}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["and/ awesome","and/ awesome [deeds]","and/ fearing","and/ they may be afraid","and/ they may fear","and/ to be feared","so/ they may fear"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615G}/H9038/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["to make an end of/ them"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2000}/H9038/[H1949]', 'inflected', 'heb', 'הָמַם', '["hâmam"]', '["and/ he routed/ them","and/ he will confuse/ them"]', '["v"]', 'properly, to put in commotion; by implication, to disturb, drive, destroy break, consume, crush, destroy, discomfit, trouble, vex.', 'a primitive root (compare 1949, 1993);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4103}/[H1949]', 'lemma', 'heb', 'מְהוּמָה', '["mᵉhûwmâh"]', '["a panic of","confusion","consternation","disturbances","panic","panic of"]', '["n-f"]', 'confusion or uproar destruction, discomfiture, trouble, tumult, vexation, vexed.', 'from 1949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8045}/H9048/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["are destroyed/ they","had destroyed/ they","have been destroyed/ they"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428G}/H9028/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["king/ their","kings/ their"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6440G}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["in/ face/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8045}/H9041/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["being destroyed/ you","destroying/ you"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6456}/[H6458]', 'lemma', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["[the] images of","idols"]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3369}/[H3369]', 'lemma', 'heb', 'יָקֹשׁ', '["yâqôsh"]', '["I set a trap","[are] ensnared","[which] they have laid","fowlers","you have been ensnared","you should be ensnared"]', '["v"]', 'to ensnare (literally or figuratively) fowler (lay a) snare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8262}/H9033/[H8262]', 'inflected', 'heb', 'שָׁקַץ', '["shâqats"]', '["you will detest/ it"]', '["v"]', 'to be filthy, i.e. (intensively) to loathe, pollute abhor, make abominable, have in abomination, detest, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8581}/[H8581]', 'inflected', 'heb', 'תַּעָב', '["taʻâb"]', '["and/ I abhor","and/ they act abominably","and/ utterly <abhor>"]', '["v"]', 'to loathe, i.e. (morally) detest (make to be) abhor(-red), (be, commit more, do) abominable(-y), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8581}/H9033/[H8581]', 'inflected', 'heb', 'תַּעָב', '["taʻâb"]', '["you will abhor/ it"]', '["v"]', 'to loathe, i.e. (morally) detest (make to be) abhor(-red), (be, commit more, do) abominable(-y), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104J}/H9013/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["you will take care/ !"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980J}/H9031/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["he led/ you"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6031B}/H9031/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["to humble/ you"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5254G}/H9031/[H5254]', 'inflected', 'heb', 'נָסָה', '["nâçâh"]', '["to/ put to [the] test/ you"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H8104G}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["¿/ will you keep"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6031B}/H9031/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ he humbled/ you"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7456}/H9031/[H7456]', 'inflected', 'heb', 'רָעֵב', '["râʻêb"]', '["and/ he caused to hunger/ you"]', '["v"]', 'to hunger (suffer to) famish, (be, have, suffer, suffer to) hunger(-ry).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0398}/H9031/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ I will feed/ you","and/ he caused to eat/ you"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8071}/H9021/[H5566]', 'inflected', 'heb', 'שִׂמְלָה', '["simlâh"]', '["clothing/ your"]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1086}/[H1086]', 'lemma', 'heb', 'בָּלָה', '["bâlâh"]', '["he has made to waste away","he wears out","it will wear out","it wore out","they became worn out","they have worn out","they will use to [the] full","they will wear out","they wore out"]', '["v"]', 'to fail; by implication to wear out, decay (causatively, consume, spend) consume, enjoy long, become (make, wax) old, spend, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7272}/H9021/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["and/ feet/ your","and/ foot/ your"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1216}/[H1216]', 'lemma', 'heb', 'בָּצֵק', '["bâtsêq"]', '["it swelled","they became swollen"]', '["v"]', 'perhaps to swell up, i.e. blister swell.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3256}/H9031/[H3256]', 'inflected', 'heb', 'יָסַר', '["yâçar"]', '["[is] disciplining/ you"]', '["v"]', 'to chastise, literally (with blows) or figuratively (with words); hence, to instruct bind, chasten, chastise, correct, instruct, punish, reform, reprove, sore, teach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870G}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["in/ ways/ his"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3372H}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["and/ by/ fearing","and/ to/ fear"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8415}/[H1949]', 'inflected', 'heb', 'תְּהוֹם', '["tᵉhôwm"]', '["and/ deeps"]', '["n"]', 'an abyss (as a surging mass of water), especially the deep (the main sea or the subterranean watersupply) deep (place), depth.', 'or תְּהֹם; (usually feminine) from 1949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1237K}/[H1234]', 'inflected', 'heb', 'בִּקְעָה', '["biqʻâh"]', '["[which] in the/ valley","in the/ valley","in/ [the] plain of","in/ [the] valley of","on the/ plain"]', '["n-f"]', 'properly, a split, i.e. a wide level valley between mountains plain, valley.', 'from 1234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2022G}/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["and/ in/ [the] hill country of","and/ on the/ mountain","and/ on/ [the] mountain of","and/ on/ [the] mountains of"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8184}/[H8175]', 'inflected', 'heb', 'שְׂעֹרָה', '["sᵉʻôrâh"]', '["and/ barley","and/ barley<s>"]', '["n-f"]', 'barley (as villose) barley.', 'or שְׂעוֹרָה (feminine meaning the plant); and (masculine meaning the grain); also שְׂעֹר; or שְׂעוֹר; from 8175 in the sense of roughness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4544}/[H4542]', 'inflected', 'heb', 'מִסְכֵּנֻת', '["miçkênuth"]', '["in/ scarcity"]', '["n-f"]', 'indigence scarceness.', 'from 4542;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0068G}/H9024/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["stones/ its"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H2042>/H9024', 'inflected', 'heb', 'ומהרריה', '["u./me./ha.ra.Rei./ha"]', '["and/ from/ hills/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4941G}/H9023/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ judgments/ his"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2708}/H9023/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["and/ statutes/ his"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3318H}/H9031/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["who/ brought out/ you"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1980J}/H9031/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["who/ led/ you"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6137>', 'inflected', 'heb', 'ועקרב', '["ve./''ak.Rav"]', '["and/ scorpion"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6774}/[H6771]', 'inflected', 'heb', 'צִמָּאוֹן', '["tsimmâʼôwn"]', '["and/ thirsty ground"]', '["n-m"]', 'a thirsty place, i.e. desert drought, dry ground, thirsty land.', 'from 6771;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6697H}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["from/ [the] rock of","from/ a rock"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2496}/[H2492]', 'inflected', 'heb', 'חַלָּמִישׁ', '["challâmîysh"]', '["<the>/ flint"]', '["n-m"]', 'flint flint(-y), rock.', 'probably from 2492 (in the sense of hardness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0398}/H9031/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["who/ caused to eat/ you"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5254G}/H9031/[H5254]', 'inflected', 'heb', 'נָסָה', '["nâçâh"]', '["let me put to [the] test/ you","to put to [the] test/ you"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3190}/H9031/[H3190]', 'inflected', 'heb', 'יָטַב', '["yâṭab"]', '["to/ do good to/ you"]', '["v"]', 'to be (causative) make well, literally (sound, beautiful) or figuratively (happy, successful, right) be accepted, amend, use aright, benefit, be (make) better, seem best, make cheerful, be comely, be content, diligent(-ly), dress, earnestly, find favour, give, be glad, do (be, make) good(-ness), be (make) merry, please ( well), shew more (kindness), skilfully, × very small, surely, make sweet, thoroughly, tire, trim, very, be (can, deal, entreat, go, have) well (said, seen).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0319}/H9021/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["at/ end/ your","in/ end/ your"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6108}/[H6105]', 'inflected', 'heb', 'עֹצֶם', '["ʻôtsem"]', '["and/ [the] might of"]', '["n-m"]', 'power; hence, body might, strong, substance.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2428H}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["<the>/ wealth","the/ wealth"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428H}/[H2342]', 'lemma', 'heb', 'חַיִל', '["chayil"]', '["[the] wealth of","wealth"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1471A}/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["like the/ nations","like/ a nation"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085H}/H9013/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["you will listen/ !"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3665}/H9038/[H3665]', 'inflected', 'heb', 'כָּנַע', '["kânaʻ"]', '["he will subdue/ them"]', '["v"]', 'properly, to bend the knee; hence, to humiliate, vanquish bring down (low), into subjection, under, humble (self), subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0006}/H9038/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["and/ he destroyed/ them","and/ they destroyed/ them","and/ they have destroyed/ them","and/ you will destroy/ them"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1920}/[H1920]', 'inflected', 'heb', 'הָדַף', '["hâdaph"]', '["when/ drives out"]', '["v"]', 'to push away or down cast away (out), drive, expel, thrust (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6666}/H9020/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["in/ righteousness/ my","on/ righteousness/ my"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935P}/H9030/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["he brought/ me","he has brought/ me","may they bring/ me","you have brought/ me"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7564}/[H7562]', 'inflected', 'heb', 'רִשְׁעָה', '["rishʻâh"]', '["and/ in/ [the] wickedness of"]', '["n-f"]', 'wrong (especially moral) fault, wickedly(-ness).', 'feminine of 7562;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6666}/H9021/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["in/ righteousness/ your"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3476}/[H3474]', 'inflected', 'heb', 'יֹשֶׁר', '["yôsher"]', '["and/ in/ [the] uprightness of","and/ in/ uprightness"]', '["n-m"]', 'the right equity, meet, right, upright(-ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7564}/[H7562]', 'inflected', 'heb', 'רִשְׁעָה', '["rishʻâh"]', '["in/ [the] wickedness of"]', '["n-f"]', 'wrong (especially moral) fault, wickedly(-ness).', 'feminine of 7562;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2722}/[H2717]', 'inflected', 'heb', 'חֹרֵב', '["Chôrêb"]', '["and/ at/ Horeb"]', '["n-pr-loc"]', 'Choreb, a (generic) name for the Sinaitic mountains Horeb.', 'from 2717; desolate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0599}/[H599]', 'inflected', 'heb', 'אָנַף', '["ʼânaph"]', '["and/ he was angry","and/ you will be angry"]', '["v"]', 'to breathe hard, i.e. be enraged be angry (displeased).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8045}/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["to/ annihilate","to/ destroy"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5927G}/H9040/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["when/ went up/ I"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8045}/H9038/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["and/ you will destroy/ them","so/ I may destroy/ them"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4229A}/[H4229]', 'inflected', 'heb', 'מָחָה', '["mâchâh"]', '["and/ I may wipe out","and/ she wipes clean"]', '["v"]', 'properly, to stroke or rub; by implication, to erase; also to smooth (as if with oil), i.e. grease or make fat; also to touch, i.e. reach to abolish, blot out, destroy, full of marrow, put out, reach unto, × utterly, wipe (away, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8610}/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["and/ I seized","and/ I will seize","and/ he arrested","and/ he seized","and/ he will be caught","and/ it has been seized","and/ they seized","and/ they will seize"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7993}/H9038/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["and/ I threw/ them","and/ he threw out/ them","and/ they threw/ them"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7665}/H9038/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["and/ I broke/ them"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7223H}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["as the/ former [time]","like the/ former [time]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3025}/[H3025]', 'lemma', 'heb', 'יָגֹר', '["yâgôr"]', '["I dread","I dreaded","I was afraid","you were afraid"]', '["v"]', 'to fear be afraid, fear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0639G}/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["the/ anger"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2534}/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["and/ the/ rage"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H0175>', 'inflected', 'heb', 'ובאהרן', '["u./ve./''a.ha.Ron"]', '["and/ with/ Aaron"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8045}/H9033/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["to/ destroy/ him"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2912}/[H2912]', 'lemma', 'heb', 'טָחַן', '["ṭâchan"]', '["grinding","grinding [it]","let her grind","you grind"]', '["v"]', 'to grind meal; hence, to be a concubine (that being their employment) grind(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6083}/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["<into>/ dust","to the/ dust","to/ dust"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6083}/H9023/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["dust/ its"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3381}/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["that/ are coming down","that/ is going down","the/ [one who] went down","those/ [who] go down","which/ came down","which/ go down","which/ goes down","which/ was coming down"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8404}/[H1197]', 'inflected', 'heb', 'תַּבְעֵרָה', '["Tabʻêrâh"]', '["and/ at/ Taberah"]', '["n-pr-loc"]', 'Taberah, a place in the Desert Taberah.', 'from 1197; burning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4532}/[H4531]', 'inflected', 'heb', 'מַסָּה', '["Maççâh"]', '["and/ at/ Massah"]', '["n-pr-loc"]', 'Massah, a place in the Desert Massah.', 'the same as 4531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6914}/[H6913]', 'inflected', 'heb', 'קִבְרוֹת הַתַּאֲוָה', '["Qibrôwth hat-Taʼă-vâh"]', '["and/ at/ Kibroth"]', '["n-pr"]', 'Kibroth-hat-Taavh, a place in the Desert Kibroth-hattaavah.', 'from the feminine plural of 6913 and 8378 with the article interposed; graves of the longing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7971G}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ when/ sent"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9040/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["knew/ I","was instructed/ I"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1433}/H9021/[H1431]', 'inflected', 'heb', 'גֹּדֶל', '["gôdel"]', '["by/ greatness/ your","in/ greatness/ your"]', '["n-m"]', 'magnitude (literally or figuratively) greatness, stout(-ness).', 'from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7190}/[H7185]', 'lemma', 'heb', 'קְשִׁי', '["qᵉshîy"]', '["[the] stubbornness of"]', '["n-m"]', 'obstinacy stubbornness.', 'from 7185;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7562}/H9023/[H7561]', 'inflected', 'heb', 'רֶשַׁע', '["reshaʻ"]', '["wickedness/ his","wickedness/ its"]', '["n-m"]', 'a wrong (especially moral) iniquity, wicked(-ness).', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1097}/[H1086]', 'inflected', 'heb', 'בְּלִי', '["bᵉlîy"]', '["because/ not"]', '["np"]', 'properly, failure, i.e. nothing or destruction; usually (with preposition) without, not yet, because not, as long as, etc. corruption, ig(norantly), for lack of, where no...is, so that no, none, not, un(awares), without.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0935P}/H9038/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["to/ bring/ them"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8135}/H9023/[H8130]', 'inflected', 'heb', 'שִׂנְאָה', '["sinʼâh"]', '["and/ from/ hatred/ his"]', '["n-f"]', 'hate exceedingly, hate(-ful, -red).', 'from 8130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4191}/H9038/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["to/ put to death/ them"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2220}/H9021/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["and/ by/ arm/ your"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5186}\/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["<the>/ outstretched"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3789}/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["and/ [it was] written","and/ [was] written","and/ [what] was written","and/ describe in writing","and/ let it be written","and/ they will write","and/ write","and/ writers","and/ writing","so/ I may inscribe","so/ they may describe in writing"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4385}/[H3789]', 'inflected', 'heb', 'מִכְתָּב', '["miktâb"]', '["like the/ writing"]', '["n-m"]', 'a thing written, the characters, or a document (letter, copy, edict, poem) writing.', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0881H}/[H875]', 'inflected', 'heb', 'בְּאֵרוֹת', '["Bᵉʼêrôwth"]', '["from/ Beeroth"]', '["n-pr-loc"]', 'Beeroth, a place in Palestine Beeroth.', 'feminine plural of 875; wells;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1142H}/[H1121]', 'lemma', 'heb', 'בְּנֵי יַעֲקָן', '["Bᵉnêy Yaʻăqân"]', '["Bene-","Yaaqan"]', '["n-pr-loc"]', 'Bene-Jaakan, a place in the Desert Bene-jaakan.', 'from the plural of 1121 and 3292; sons of Yaakan;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4149A}/[H4147]', 'lemma', 'heb', 'מוֹסֵרָה', '["Môwçêrâh"]', '["Moserah"]', '["n-pr-f"]', 'Moserah, a place in the Desert Mosera.', 'or (plural) מֹסְרוֹת feminine of 4147; correction or corrections;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1412}/H9011/[H1413]', 'inflected', 'heb', 'גֻּדְגֹּדָה', '["Gudgôdâh"]', '["<the>/ Gudgodah/ towards"]', '["n-pr-loc"]', 'Gudgodah, a place in the Desert Gudgodah.', 'by reduplication from 1413 (in the sense of cutting) cleft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3193}/[H3192]', 'lemma', 'heb', 'יׇטְבָתָה', '["Yoṭbâthâh"]', '["Jotbathah"]', '["n-pr-loc"]', 'Jotbathah, a place in the Desert Jotbath, Jotbathah.', 'from 3192;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8334}/H9033/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["to/ serve/ him"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1288}/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["and/ to/ bless"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8034}/H9023/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["<in>/ name/ his","in/ name/ his","on/ name/ his"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4550}/[H5265]', 'inflected', 'heb', 'מַסַּע', '["maççaʻ"]', '["to/ journeying"]', '["n-m"]', 'a departure (from striking the tents), i.e. march (not necessarily a single day''s travel); by implication, a station (or point of departure) journey(-ing).', 'from 5265;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0157G}/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ to/ love"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5647G}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ to/ serve"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0001G}/H9021/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["<in>/ ancestors/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0157G}/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["[belongs] to/ [those who] love","by/ loving","to/ [those who] love","to/ love"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2233H}/H9028/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["<in>/ offspring/ their"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6203}/H9026/[H6202]', 'inflected', 'heb', 'עֹרֶף', '["ʻôreph"]', '["and/ neck/ your"]', '["n-m"]', 'the nape or back of the neck (as declining); hence, the back generally (whether literal or figurative) back ((stiff-) neck((-ed).', 'from 6202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0113>', 'inflected', 'heb', 'ואדני', '["va./''a.do.Nei"]', '["and/ [the] lord<s> of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3372H}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["and/ <the>/ awesome"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7810}/[H7809]', 'lemma', 'heb', 'שַׁחַד', '["shachad"]', '["a bribe","a gift"]', '["n-m"]', 'a donation (venal or redemptive) bribe(-ry), gift, present, reward.', 'from 7809;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3490>', 'opaque', 'heb', 'יָתוֹם', '["yâthôwm"]', '["[the] fatherless","a fatherless one","fatherless","fatherless one","fatherless ones"]', '["n-m"]', 'a bereaved person fatherless (child), orphan.', 'from an unused root meaning to be lonely;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0490}/[H488]', 'inflected', 'heb', 'אַלְמָנָה', '["ʼalmânâh"]', '["and/ [the] widow","and/ a widow","and/ widow","and/ widow[s]","and/ widows"]', '["n-f"]', 'a widow; also a desolate place desolate house (palace), widow.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0157G}/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ [are] loving","and/ [he is] loving","and/ [one who] loves","and/ [those who] love","and/ love","and/ loved","and/ lovers of","and/ to love"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8416}/H9021/[H1984]', 'inflected', 'heb', 'תְּהִלָּה', '["tᵉhillâh"]', '["[is] praise/ your","praise/ your","praises/ your"]', '["n-f"]', 'laudation; specifically (concretely) a hymn praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3372H}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["<the>/ awesome","the/ awesome [deeds]"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7657}/[H7651]', 'inflected', 'heb', 'שִׁבְעִים', '["shibʻîym"]', '["<in>/ seventy"]', '["n"]', 'seventy seventy, threescore and ten ( -teen).', 'multiple of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4148G}/[H3256]', 'lemma', 'heb', 'מוּסָר', '["mûwçâr"]', '["[am] discipline","[the] chastening of","[the] correction of","[the] discipline of","[the] training of","a warning","correction","discipline"]', '["n-m"]', 'properly, chastisement; figuratively, reproof, warning or instruction; also restraint bond, chastening(-eth), chastisement, check, correction, discipline, doctrine, instruction, rebuke.', 'from 3256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2220}/H9023/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["<and>/ arm/ his","and/ arm/ his","and/ arm/ its","and/ arms/ his"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0226G}/H9023/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["signs/ his"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639K}/H9023/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["[are] work/ his","deed/ his","deed/ its","deeds/ his","works/ his"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2428A}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["<to>/ an army","to/ [the] army of"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H5483M>/H9023', 'inflected', 'heb', 'לסוסיו', '["le./su.Sa/v"]', '["to/ horses/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7393G}/H9023/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["and/ to/ chariotry/ its"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6687}/[H6687]', 'lemma', 'heb', 'צוּף', '["tsûwph"]', '["he caused to flow","they overflowed"]', '["v"]', 'to overflow (make to over-) flow, swim.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440L}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["faces/ their"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7291}/H9048/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["when/ pursued/ they"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1104}/H9038/[H1104]', 'inflected', 'heb', 'בָּלַע', '["bâlaʻ"]', '["and/ it swallowed/ them"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7272}/H9028/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["[was] at/ feet/ their","[were] on/ feet/ their"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2233G}/H9021/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["seed/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3419}/[H3418]', 'inflected', 'heb', 'יָרָק', '["yârâq"]', '["<the>/ vegetable[s]"]', '["n-m"]', 'properly, green; concretely, a vegetable green, herbs.', 'from the same as 3418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1237K}/[H1234]', 'inflected', 'heb', 'בִּקְעָה', '["biqʻâh"]', '["and/ valleys"]', '["n-f"]', 'properly, a split, i.e. a wide level valley between mountains plain, valley.', 'from 1234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4306}/[H4305]', 'inflected', 'heb', 'מָטַר', '["mâṭar"]', '["for the/ rain","to/ [the] rain of"]', '["n-m"]', 'rain rain.', 'from 4305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0319}/[H310]', 'lemma', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["[is] a future","[the] end","[the] end of","[the] future of","[the] last of","[the] latter part of","[will be] [the] latter part of","a future"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8141}\/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["a year","year[s]","years"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5647G}/H9033/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ to/ serve/ him"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4306}/[H4305]', 'lemma', 'heb', 'מָטַר', '["mâṭar"]', '["[the] rain of","[the] rains of","rain"]', '["n-m"]', 'rain rain.', 'from 4305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6256}/H9023/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["at/ appropriate time/ its","in/ time/ its"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3138}/[H3384]', 'lemma', 'heb', 'יוֹרֶה', '["yôwreh"]', '["autumn rain"]', '["n-m"]', 'sprinkling; hence, a sprinkling (or autumnal showers) first rain, former (rain).', 'active participle of 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4456}/[H3953]', 'inflected', 'heb', 'מַלְקוֹשׁ', '["malqôwsh"]', '["and/ spring rain"]', '["n-m"]', 'the spring rain; figuratively, eloquence latter rain.', 'from 3953; (compare 3954)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7704G>/H9021', 'inflected', 'heb', 'בשדך', '["be./sa.de./Kha","ve./sa.De./kha"]', '["in/ field/ your","in/ field[s]/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0929>/H9021', 'inflected', 'heb', 'לבהמתך', '["li/v.hem.Te./kha"]', '["for/ cattle/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}/H9026/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your","hands/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3925G}/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["and/ they taught","and/ you will teach"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8179G}/H9021/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["and/ on/ gates/ your"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/H9026', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days/ your"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6213A}/H9034/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["to/ do/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1692}/[H1692]', 'inflected', 'heb', 'דָּבַק', '["dâbaq"]', '["and/ by/ cleaving","and/ to/ cleave"]', '["v"]', 'properly, to impinge, i.e. cling or adhere; figuratively, to catch by pursuit abide fast, cleave (fast together), follow close (hard after), be joined (together), keep (fast), overtake, pursue hard, stick, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H6440G}/H9026/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ to/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5104G}/[H5102]', 'lemma', 'heb', 'נָהָר', '["nâhâr"]', '["<of> [the] River","[the] River","[the] river","[the] river of"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366H}/H9026/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["territory/ your"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6440G}/H9026/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["in/ faces/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6343}/H9026/[H6342]', 'inflected', 'heb', 'פַּחַד', '["pachad"]', '["dread/ your"]', '["n-m"]', 'a (sudden) alarm (properly, the object feared, by implication, the feeling) dread(-ful), fear, (thing) great (fear, -ly feared), terror.', 'from 6342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7045}/[H7043]', 'inflected', 'heb', 'קְלָלָה', '["qᵉlâlâh"]', '["and/ a curse"]', '["n-f"]', 'vilification (ac-) curse(-d, -ing).', 'from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7045}/[H7043]', 'inflected', 'heb', 'קְלָלָה', '["qᵉlâlâh"]', '["and/ <the>/ curse","and/ the/ curse"]', '["n-f"]', 'vilification (ac-) curse(-d, -ing).', 'from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}\/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["[is] knowing","she knows","they know","you have known"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1630}/[H1629]', 'lemma', 'heb', 'גְּרִזִים', '["Gᵉrizîym"]', '["Gerizim"]', '["n-pr-loc"]', 'Gerizim, a mountain of Palestine Gerizim.', 'plural of an unused noun from 1629 (compare 1511), cut up (i.e. rocky);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7045}/[H7043]', 'inflected', 'heb', 'קְלָלָה', '["qᵉlâlâh"]', '["<the>/ curse","the/ curse","the/ curses"]', '["n-f"]', 'vilification (ac-) curse(-d, -ing).', 'from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5858C>', 'opaque', 'heb', 'עֵיבָל', '["ʻÊybâl"]', '["Ebal"]', '["n-pr-m"]', 'Ebal, a mountain of Palestine Ebal.', 'perhaps from an unused root probably meaning to be bald; bare;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3996}/[H935]', 'lemma', 'heb', 'מָבוֹא', '["mâbôwʼ"]', '["[the] entrance of","[the] setting of","an entrance"]', '["n-m"]', 'an entrance (the place or the act); specifically sunset or the west; also (adverb with preposition) towards by which came, as cometh, in coming, as men enter into, entering, entrance into, entry, where goeth, going down, westward. Compare 4126.', 'from 935; (with or without 8121)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1537G}/[H1536]', 'inflected', 'heb', 'גִּלְגָּל', '["Gilgâl"]', '["<the>/ Gilgal"]', '["n-pr-loc"]', 'Gilgal, the name of three places in Palestine Gilgal. See also 1019.', 'the same as 1536 (with the article as a properly, noun);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7311A}/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["<the>/ high","that/ are lofty","which/ they had offered"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7488B>', 'opaque', 'heb', 'רַעֲנָן', '["raʻănân"]', '["[is] luxuriant","fresh","luxuriant"]', '["v a"]', 'verdant; by analogy, new; figuratively, prosperous green, flourishing.', 'from an unused root meaning to be green;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6456}/[H6458]', 'inflected', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["and/ [the] images of"]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213I}/H9013/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["you will do/ !"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7931}/H9023/[H7901]', 'inflected', 'heb', 'שָׁכַן', '["shâkan"]', '["to/ dwelling/ its"]', '["v"]', 'to reside or permanently stay (literally or figuratively) abide, continue, (cause to, make to) dwell(-er), have habitation, inhabit, lay, place, (cause to) remain, rest, set (up).', 'a primitive root (apparently akin (by transmission) to 7901 through the idea of lodging; compare 5531, 7925);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2077}/H9026/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["and/ sacrifices/ your"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027I}/H9026/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your","hands/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5088}/H9026/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["and/ votive offerings/ your"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1060}/[H1069]', 'inflected', 'heb', 'בְּכוֹר', '["bᵉkôwr"]', '["and/ [the] firstborn<s> of"]', '["n-m"]', 'first-born; hence, chief eldest (son), firstborn(-ling).', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6629G>/H9026', 'inflected', 'heb', 'וצאנכם', '["ve./tzo.ne./Khem"]', '["and/ flock[s]/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4916A}/[H7971]', 'lemma', 'heb', 'מִשְׁלוֹחַ', '["mishlôwach"]', '["<the> undertaking of"]', '["n-m"]', 'a sending out, i.e. (abstractly) presentation (favorable), or seizure (unfavorable); also (concretely) a place of dismissal, or a business to be discharged to lay, to put, sending (forth), to set.', 'or מִשְׁלֹחַ; also מִשְׁלָח; from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027U}/H9026/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4496H}/[H4495]', 'inflected', 'heb', 'מְנוּחָה', '["mᵉnûwchâh"]', '["[is] <the>/ resting place","[is] the/ resting place","the/ resting place"]', '["n-f"]', 'repose or (adverbially) peacefully; figuratively, consolation (specifically, matrimony); hence (concretely) an abode comfortable, ease, quiet, rest(-ing place), still.', 'or מְנֻחָה; feminine of 4495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5159}/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["[are] the/ inheritances","the/ inheritance"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4005}/[H977]', 'lemma', 'heb', 'מִבְחָר', '["mibchâr"]', '["[the] choicest","[the] choicest of","[were] [the] choicest of"]', '["n-m"]', 'select, i.e. best choice(-st), chosen.', 'from 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5650}/H9026/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["and/ [male] servants/ your"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0519}/H9026/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["and/ female servants/ your"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8179H}/H9026/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["[is] in/ gates/ your"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7626H>/H9021', 'opaque', 'heb', 'שֵׁבֶט', '["shêbeṭ"]', '["tribes/ your"]', '["n-m"]', 'a scion, i.e. (literally) a stick (for punishing, writing, fighting, ruling, walking, etc.) or (figuratively) a clan × correction, dart, rod, sceptre, staff, tribe.', 'from an unused root probably meaning to branch off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0185}/[H183]', 'lemma', 'heb', 'אַוָּה', '["ʼavvâh"]', '["[the] desire","[the] desire of"]', '["n-f"]', 'longing desire, lust after, pleasure.', 'from 183;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1293}/[H1288]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["according to/ [the] blessing of"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8179H}/H9021/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["gates/ your"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2889}/[H2891]', 'inflected', 'heb', 'טָהוֹר', '["ṭâhôwr"]', '["and/ the/ clean"]', '["a"]', 'pure (in a physical, chemical, ceremonial or moral sense) clean, fair, pure(-ness).', 'or טָהֹר; from 2891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6643B}/[H6638]', 'inflected', 'heb', 'צְבִי', '["tsᵉbîy"]', '["like <the>/ gazelle","like/ a gazelle"]', '["n-m"]', 'splendor (as conspicuous) beautiful(-ty), glorious (-ry), goodly, pleasant, roe(-buck).', 'from 6638 in the sense of prominence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0354}/[H352]', 'inflected', 'heb', 'אַיָּל', '["ʼayâl"]', '["and/ like <the>/ deer"]', '["n-m"]', 'a stag or male deer hart.', 'an intensive form of 352 (in the sense of ram);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8210G}/H9033/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["it poured out/ it","you will pour out/ it"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8179H}/H9021/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["[are] in/ gates/ your","[is] in/ gates/ your","in/ gates/ your"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5088}/H9021/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["votive offerings/ your","vows/ your"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5071}/H9021/[H5068]', 'inflected', 'heb', 'נְדָבָה', '["nᵉdâbâh"]', '["and/ freewill offerings/ your"]', '["n-f"]', 'properly (abstractly) spontaneity, or (adjectively) spontaneous; also (concretely) a spontaneous or (by inference, in plural) abundant gift free(-will) offering, freely, plentiful, voluntary(-ily, offering), willing(-ly), offering).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027I}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027U}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800H}/[H5800]', 'lemma', 'heb', 'עָזַב', '["ʻâzab"]', '["has it been neglected","he has neglected","we will neglect","you neglect","you should neglect"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117K>/H9021', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days/ your"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0127G}/H9021\/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["land/ your"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315L}/H9021/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["appetite/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1241}/H9021/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["some of/ herd/ your"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H6629G>/H9021', 'inflected', 'heb', 'ומצאנך', '["u./mi./tzo.ne./Kha"]', '["and/ some of/ flock/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6643B}/[H6638]', 'inflected', 'heb', 'צְבִי', '["tsᵉbîy"]', '["the/ gazelle","the/ gazelles"]', '["n-m"]', 'splendor (as conspicuous) beautiful(-ty), glorious (-ry), goodly, pleasant, roe(-buck).', 'from 6638 in the sense of prominence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0354}/[H352]', 'inflected', 'heb', 'אַיָּל', '["ʼayâl"]', '["the/ deer","the/ deer<s>"]', '["n-m"]', 'a stag or male deer hart.', 'an intensive form of 352 (in the sense of ram);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388I}/[H2388]', 'lemma', 'heb', 'חָזַק', '["châzaq"]', '["be strong"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5315H}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["[is] the/ life","the/ breath","the/ life","the/ throat"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5088}/H9021/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["and/ votive offerings/ your","and/ vows/ your"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1818}/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["and/ the/ blood"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2077}/H9021/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["sacrifices/ your"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9021\/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5367}/[H5367]', 'lemma', 'heb', 'נָקַשׁ', '["nâqash"]', '["[he is] striking down","may he strike","setting traps","you should be ensnared"]', '["v"]', 'to entrap (with a noose), literally or figuratively catch (lay a) snare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4480A}/H9033\/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["from/ him","from/ it"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9038/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["I know/ them","I will make know/ them","[am] about to make know/ them","make known to/ them","they had known/ them","they have known/ them","they knew/ them","they will make known to/ them","we know/ them","you have known/ them"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5647H}/H9038/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ let us be enticed to serve/ them"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5030}/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["<the>/ prophets","the/ prophet","the/ prophets"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/<H3426>/H9046', 'inflected', 'heb', 'הישכם', '["ha./yish./Khem"]', '["¿/ [are] there/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H6963A>/H9023', 'inflected', 'heb', 'ובקולו', '["u./ve./ko.L/o"]', '["and/ to/ voice/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1692}/H9013/[H1692]', 'inflected', 'heb', 'דָּבַק', '["dâbaq"]', '["you will cleave/ !","you will stay/ !"]', '["v"]', 'properly, to impinge, i.e. cling or adhere; figuratively, to catch by pursuit abide fast, cleave (fast together), follow close (hard after), be joined (together), keep (fast), overtake, pursue hard, stick, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5030}/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["and/ the/ prophet","and/ the/ prophets"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5627}/[H5493]', 'lemma', 'heb', 'סָרָה', '["çârâh"]', '["ceasing","rebellion"]', '["n-f"]', 'apostasy, crime; figuratively, remission × continual, rebellion, revolt(-ed), turn away, wrong.', 'from 5493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6299}/H9031/[H6299]', 'inflected', 'heb', 'פָּדָה', '["pâdâh"]', '["and/ who/ redeemed/ you"]', '["v"]', 'to sever, i.e. ransom; generally to release, preserve × at all, deliver, × by any means, ransom, (that are to be, let be) redeem(-ed), rescue, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5080}/H9031/[H5080]', 'inflected', 'heb', 'נָדַח', '["nâdach"]', '["to/ thrust aside/ you"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1197I}/[H1198]', 'inflected', 'heb', 'בָּעַר', '["bâʻar"]', '["and/ you will remove"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7451B}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<the>/ evil","the/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5496}/H9031/[H7898]', 'inflected', 'heb', 'סוּת', '["çûwth"]', '["he has allured/ you","he has incited/ you","he will entice/ you","it should entice/ you","they misled/ you"]', '["v"]', 'properly, to prick, i.e. (figuratively) stimulate; by implication, to seduce entice, move, persuade, provoke, remove, set on, stir up, take away.', 'perhaps denominative from 7898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2436G>/H9021', 'opaque', 'heb', 'חֵיק', '["chêyq"]', '["bosom/ your"]', '["n-m"]', 'the bosom (literally or figuratively) bosom, bottom, lap, midst, within.', 'or חֵק; and חוֹק; from an unused root, apparently meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5315G}/H9021/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["[is] like/ self/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5643A}/[H5641]', 'inflected', 'heb', 'סֵתֶר', '["çêther"]', '["in <the>/ secrecy","in <the>/ secret","in the/ hiding place","in the/ secret place","in/ [the] cover of","in/ [the] hiding place of","in/ [the] shelter of","in/ a hiding place of"]', '["n-m"]', 'a cover (in a good or a bad, a literal or a figurative sense) backbiting, covering, covert, × disguise(-th), hiding place, privily, protection, secret(-ly, place).', 'or (feminine) סִתְרָה; (Deuteronomy 32:38), from 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0001G}/H9021/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ ancestors/ your","and/ father/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7350}/[H7368]', 'inflected', 'heb', 'רָחוֹק', '["râchôwq"]', '["<the>/ distant","<the>/ far","O/ [people] distant","the/ distant [person]"]', '["a"]', 'remote, literally or figuratively, of place or time; specifically, precious; often used adverbially (with preposition) (a-) far (abroad, off), long ago, of old, space, great while to come.', 'or רָחֹק; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2550}/[H2550]', 'lemma', 'heb', 'חָמַל', '["châmal"]', '["I will have compassion","I will show pity","anyone will spare","he had compassion","he has compassion","he has spared","he showed pity","he spares","he will have compassion","he will show pity","it had compassion","it relents","they spared","will he have compassion","you have had compassion","you have spared","you must have compassion","you show pity","you spare","you will spare [him]"]', '["v"]', 'to commiserate; by implication, to spare have compassion, (have) pity, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3027H}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0314}/[H309]', 'inflected', 'heb', 'אַחֲרוֹן', '["ʼachărôwn"]', '["at the/ last"]', '["a"]', 'hinder; generally, late or last; specifically (as facing the east) western after (-ward), to come, following, hind(-er, -ermost, -most), last, latter, rereward, ut(ter) most.', 'or (shortened) אַחֲרֹן; from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5619}/H9033/[H5619]', 'inflected', 'heb', 'סָקַל', '["çâqal"]', '["and/ he cleared of stones/ it","and/ they stoned/ him","and/ you will stone/ him"]', '["v"]', 'properly, to be weighty; but used only in the sense of lapidation or its contrary (as if a delapidation) (cast, gather out, throw) stone(-s), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3372G}/H9013/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["and/ they will fear/ !"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130G}/H9021\/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["[is] in/ midst/ your","in/ midst/ your"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5892B}/H9021/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["cities/ your","city/ your"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1100G}/[H1097]', 'lemma', 'heb', 'בְּלִיַּעַל', '["bᵉlîyaʻal"]', '["worthlessness"]', '["n-m"]', 'without profit, worthlessness; by extension, destruction, wickedness Belial, evil, naughty, ungodly (men), wicked.', 'from 1097 and 3276;(often in connection with 376, 802, 1121, etc.)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1875}/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["and/ I will search for","and/ I will seek","and/ he enquired","and/ they investigated","and/ they will consult","and/ they will investigate","and/ they will seek","and/ you will consult","and/ you will enquire","and/ you will investigate"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2713}/[H2713]', 'inflected', 'heb', 'חָקַר', '["châqar"]', '["and/ he searched out","and/ you will search"]', '["v"]', 'properly, to penetrate; hence, to examine intimately find out, (make) search (out), seek (out), sound, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1697J}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<the>/ word","the/ matter","the/ word"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0929>/H9024', 'opaque', 'heb', 'בְּהֵמָה', '["bᵉhêmâh"]', '["livestock/ its"]', '["n-f"]', 'properly, a dumb beast; especially any large quadruped or animal (often collective) beast, cattle.', 'from an unused root (probably meaning to be mute);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7998}/H9024/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["booty/ its","plunder/ its"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7339}/H9024/[H7337]', 'inflected', 'heb', 'רְחֹב', '["rᵉchôb"]', '["open place/ its"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8510}/[H8524]', 'lemma', 'heb', 'תֵּל', '["têl"]', '["a mound of"]', '["n-m"]', 'a mound heap, × strength.', 'by contraction from 8524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7355}/H9031/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["and/ he will have compassion on/ you"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1413}/[H1464]', 'lemma', 'heb', 'גָּדַד', '["gâdad"]', '["anyone will cut himself","they band together","they cut themselves","you will cut yourself","you will cut yourselves"]', '["v"]', 'to crowd; also to gash (as if by pressing into) assemble (selves by troops), gather (selves together, self in troops), cut selves.', 'a primitive root (compare 1464);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0354}/[H352]', 'lemma', 'heb', 'אַיָּל', '["ʼayâl"]', '["a deer"]', '["n-m"]', 'a stag or male deer hart.', 'an intensive form of 352 (in the sense of ram);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6643B}/[H6638]', 'inflected', 'heb', 'צְבִי', '["tsᵉbîy"]', '["and/ a gazelle","and/ gazelle"]', '["n-m"]', 'splendor (as conspicuous) beautiful(-ty), glorious (-ry), goodly, pleasant, roe(-buck).', 'from 6638 in the sense of prominence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3180}/[H2560]', 'inflected', 'heb', 'יַחְמוּר', '["yachmûwr"]', '["and/ a roe-deer","and/ roe-deer"]', '["n-m"]', 'a kind of deer fallow deer.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0689}/[H602]', 'inflected', 'heb', 'אַקּוֹ', '["ʼaqqôw"]', '["and/ a wild goat"]', '["n-m"]', 'slender, i.e. the ibex wild goat.', 'probably from 602;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1788}/[H1758]', 'inflected', 'heb', 'דִּישֹׁן', '["dîyshôn"]', '["and/ an ibex"]', '["n-m"]', 'the leaper, i.e. an antelope pygarg.', 'from 1758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8377}/[H8376]', 'inflected', 'heb', 'תְּאוֹ', '["tᵉʼôw"]', '["and/ an antelope"]', '["n-m"]', 'a species of antelope (probably from the white stripe on the cheek) wild bull (ox).', 'and תּוֹא; (the original form), from 8376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2169}/[H2167]', 'inflected', 'heb', 'זֶמֶר', '["zemer"]', '["and/ a mountain sheep"]', '["n-m"]', 'a gazelle (from its lightly touching the ground) chamois.', 'apparently from 2167 or 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8156}/[H8156]', 'inflected', 'heb', 'שָׁסַע', '["shâçaʻ"]', '["<the>/ cloven"]', '["v"]', 'to split or tear; figuratively, to upbraid cleave, (be) cloven (footed), rend, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5060}\/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["you will touch"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6538}/[H6536]', 'inflected', 'heb', 'פֶּרֶס', '["pereç"]', '["and/ the/ bearded vulture"]', '["n-m"]', 'a claw; also a kind of eagle claw, ossifrage.', 'from 6536;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5822}/[H5797]', 'inflected', 'heb', 'עׇזְנִיָּה', '["ʻoznîyâh"]', '["and/ the/ osprey"]', '["n-f"]', 'probably the sea-eagle (from its strength) ospray.', 'probably feminine of 5797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7201}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ the/ red kite"]', '["n-f"]', 'a bird of prey (probably the vulture, from its sharp sight) glede. Compare 1676.', 'from 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1772}/[H1675]', 'inflected', 'heb', 'דַּיָּה', '["dayâh"]', '["and/ the/ black kite"]', '["n-f"]', 'a falcon (from its rapid flight) vulture.', 'intensive from 1675;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6893}/[H6958]', 'inflected', 'heb', 'קָאַת', '["qâʼath"]', '["and/ the/ desert owl"]', '["n-f"]', 'probably the pelican (from vomiting) cormorant.', 'from 6958;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7360}/H9011/[H7355]', 'inflected', 'heb', 'רָחָם', '["râchâm"]', '["the/ Egyptian vulture/ <towards>"]', '["n-m"]', 'a kind of vulture (supposed to be tender towards its young) gier-eagle.', 'or (feminine) רָחָמָה; from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2624}/[H2623]', 'inflected', 'heb', 'חֲסִידָה', '["chăçîydâh"]', '["and/ the/ stork"]', '["n-f"]', 'the kind (maternal) bird, i.e. a stork × feather, stork.', 'feminine of 2623;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0601}/[H599]', 'inflected', 'heb', 'אֲנָפָה', '["ʼănâphâh"]', '["and/ the/ heron"]', '["n-f"]', 'an unclean bird, perhaps the parrot (from its irascibility) heron.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H1744>', 'inflected', 'heb', 'והדוכיפת', '["ve./ha./du.khi.Fat"]', '["and/ the/ hoopoe"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H5847>', 'inflected', 'heb', 'והעטלף', '["ve./ha./''a.ta.Lef"]', '["and/ the/ bat"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0398}/H9034/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ he will eat/ it"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5237}/[H5235]', 'inflected', 'heb', 'נׇכְרִי', '["nokrîy"]', '["to the/ foreigner","to/ a foreigner","to/ foreigners"]', '["a"]', 'strange, in a variety of degrees and applications (foreign, non-relative, adulterous, different, wonderful) alien, foreigner, outlandish, strange(-r, woman).', 'from 5235 (second form);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3318M}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["which/ comes out","who/ comes out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8492}/H9021/[H3423]', 'inflected', 'heb', 'תִּירוֹשׁ', '["tîyrôwsh"]', '["new wine/ your"]', '["n-m"]', 'must or fresh grape-juice (as just squeezed out); by implication (rarely) fermented wine (new, sweet) wine.', 'or תִּירֹשׁ; from 3423 in the sense of expulsion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3925H}/[H3925]', 'lemma', 'heb', 'לָמַד', '["lâmad"]', '["<you> learn","I have learned","I may learn","certainly [if] <learn>","he learns","he may learn","they learn","they may learn","they taught","they will learn","you learn","you may learn","you will learn"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7760A}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["to/ make","to/ put","to/ set","to/ set up"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6696A}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["and/ I will lay siege","and/ he besieged","and/ he laid siege","and/ he secured","and/ they laid siege","and/ they tied up","and/ you will confine","and/ you will lay siege","and/ you will secure"]', '["v"]', 'to cramp, i.e. confine (in many applications, literally and figuratively, formative or hostile) adversary, assault, beset, besiege, bind (up), cast, distress, fashion, fortify, inclose, lay siege, put up in bags.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H3196>', 'inflected', 'heb', 'וביין', '["u./vai./Ya.yin","u./ve./Yein"]', '["and/ for <the>/ wine","and/ with/ [the] wine of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7941}/[H7937]', 'inflected', 'heb', 'שֵׁכָר', '["shêkâr"]', '["and/ for <the>/ strong drink","and/ with <the>/ strong drink"]', '["n-m"]', 'an intoxicant, i.e. intensely alcoholic liquor strong drink, drunkard, strong wine.', 'from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800H}/H9033/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["you will neglect/ him"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/H9031\/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[is] with/ you","with/ you"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8393}/H9021/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["produce/ your"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H3490>', 'inflected', 'heb', 'והיתום', '["ve./hai./ya.Tom"]', '["and/ the/ fatherless one"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0490}/[H488]', 'inflected', 'heb', 'אַלְמָנָה', '["ʼalmânâh"]', '["and/ the/ widow"]', '["n-f"]', 'a widow; also a desolate place desolate house (palace), widow.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8059}/[H8058]', 'lemma', 'heb', 'שְׁמִטָּה', '["shᵉmiṭṭâh"]', '["a remission"]', '["n-f"]', 'remission (of debt) or suspension of labor) release.', 'from 8058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697O}/[H1696]', 'lemma', 'heb', 'דָּבָר', '["dâbâr"]', '["[is] [the] manner of","[the] manner of","[the] matters of","[the] words of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8059}/[H8058]', 'inflected', 'heb', 'שְׁמִטָּה', '["shᵉmiṭṭâh"]', '["the/ remission"]', '["n-f"]', 'remission (of debt) or suspension of labor) release.', 'from 8058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8058}/[H8058]', 'lemma', 'heb', 'שָׁמַט', '["shâmaṭ"]', '["he will remit","let it release","they had stumbled","they have been thrown down","they stumbled"]', '["v"]', 'to fling down; incipiently to jostle; figuratively, to let alone, desist, remit discontinue, overthrow, release, let rest, shake, stumble, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4874}/[H5383]', 'lemma', 'heb', 'מַשֶּׁה', '["mashsheh"]', '["[the] loan of"]', '["n-m"]', 'a debt creditor.', 'from 5383;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5383}/[H5382]', 'lemma', 'heb', 'נָשָׁה', '["nâshâh"]', '["I have lent","[are] lending","a creditor","he will lend","people have lent","you will lend"]', '["v"]', 'to lend or (by reciprocity) borrow on security or interest creditor, exact, extortioner, lend, usurer, lend on (taker on) usury.', 'a primitive root (rather identical with 5382, in the sense of 5378);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7453}/H9023/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["<in>/ neighbor/ his","against/ neighbor/ his","by/ fellow-citizen/ his","in/ neighbor/ his","on/ neighbor/ his","to/ neighbor/ his"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5237}/[H5235]', 'inflected', 'heb', 'נׇכְרִי', '["nokrîy"]', '["<the>/ foreign","the/ foreigner"]', '["a"]', 'strange, in a variety of degrees and applications (foreign, non-relative, adulterous, different, wonderful) alien, foreigner, outlandish, strange(-r, woman).', 'from 5235 (second form);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3423G}/H9034/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["to/ take possession of/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8104J}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["to/ keep","to/ take care"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5670}/[H5670]', 'inflected', 'heb', 'עָבַט', '["ʻâbaṭ"]', '["and/ you will lend to"]', '["v"]', 'to pawn; causatively, to lend (on security); figuratively, to entangle borrow, break (ranks), fetch (a pledge), lend, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5670}/[H5670]', 'lemma', 'heb', 'עָבַט', '["ʻâbaṭ"]', '["you will borrow"]', '["v"]', 'to pawn; causatively, to lend (on security); figuratively, to entangle borrow, break (ranks), fetch (a pledge), lend, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4910}/[H4910]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["and/ he will exercise dominion","and/ he will have dominion","and/ he will rule","and/ they ruled","and/ you will rule"]', '["v"]', 'to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4910}\/[H4910]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["they will rule"]', '["v"]', 'to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7092}/[H7092]', 'lemma', 'heb', 'קָפַץ', '["qâphats"]', '["[is] bounding","has he shut off","it shuts","they will shut","you will shut"]', '["v"]', 'to draw together, i.e. close; by implication, to leap (by contracting the limbs); specifically, to die (from gathering up the feet) shut (up), skip, stop, take out of the way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0251I}/H9021/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["from/ countryman/ your","one of/ countrymen/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0034}/[H14]', 'inflected', 'heb', 'אֶבְיוֹן', '["ʼebyôwn"]', '["<the>/ needy"]', '["a-m"]', 'destitute beggar, needy, poor (man).', 'from 14, in the sense of want (especially in feeling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5670}/[H5670]', 'inflected', 'heb', 'עָבַט', '["ʻâbaṭ"]', '["and/ certainly <to lend>"]', '["v"]', 'to pawn; causatively, to lend (on security); figuratively, to entangle borrow, break (ranks), fetch (a pledge), lend, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5670}/H9033/[H5670]', 'inflected', 'heb', 'עָבַט', '["ʻâbaṭ"]', '["you will lend to/ him"]', '["v"]', 'to pawn; causatively, to lend (on security); figuratively, to entangle borrow, break (ranks), fetch (a pledge), lend, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4270}/H9023/[H2637]', 'inflected', 'heb', 'מַחְסוֹר', '["machçôwr"]', '["lack/ his"]', '["n-m"]', 'deficiency; hence, impoverishment lack, need, penury, poor, poverty, want.', 'or מַחְסֹר; from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1100I}/[H1097]', 'lemma', 'heb', 'בְּלִיַּעַל', '["bᵉlîyaʻal"]', '["worthless person","worthlessness"]', '["n-m"]', 'without profit, worthlessness; by extension, destruction, wickedness Belial, evil, naughty, ungodly (men), wicked.', 'from 1097 and 3276;(often in connection with 376, 802, 1121, etc.)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7651}/[H7650]', 'inflected', 'heb', 'שֶׁבַע', '["shebaʻ"]', '["<the>/ seven [children]","the/ seven"]', '["n"]', 'seven (as the sacred full one); also (adverbially) seven times; by implication, a week; by extension, an indefinite number ( by) seven(-fold),-s, (-teen, -teenth), -th, times). Compare 7658.', 'or (masculine) (שִׁבְעָה); from 7650; a primitive cardinal number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0251I}/H9021/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["on/ countryman/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5414G}/H9041/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["when/ giving/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1697M}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["[is] the/ reason","the/ matter","the/ thing"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251I}/H9021/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["to/ countryman/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6041}/H9021/[H6031]', 'inflected', 'heb', 'עָנִי', '["ʻânîy"]', '["to/ poor [person]/ your"]', '["a"]', 'depressed, in mind or circumstances afflicted, humble, lowly, needy, poor.', 'from 6031; (practically the same as 6035, although the margin constantly disputes this, making 6035 subjective and objective);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0034}/H9021/[H14]', 'inflected', 'heb', 'אֶבְיוֹן', '["ʼebyôwn"]', '["and/ to/ needy [person]/ your"]', '["a-m"]', 'destitute beggar, needy, poor (man).', 'from 14, in the sense of want (especially in feeling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0776G>/H9021\', 'inflected', 'heb', 'בארצך ס', '["be./''ar.Tze./kha"]', '["in/ land/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5647G}/H9031/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ I will make serve/ you","and/ he will serve/ you","and/ they will serve/ you"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6059}/[H6060]', 'lemma', 'heb', 'עָנַק', '["ʻânaq"]', '["certainly <to provide>","you will provide"]', '["v"]', 'to collar, i.e. adorn with a necklace; figuratively, to fit out with supplies compass about as a chain, furnish, liberally.', 'a primitive root; properly, to choke; used only as denominative from 6060,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6629G>/H9021', 'inflected', 'heb', 'מצאנך', '["mi./Tzo.ne./kha"]', '["from/ flock/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H1637>/H9021', 'inflected', 'heb', 'ומגרנך', '["u./mi./ga.re.ne./Kha"]', '["and/ from/ threshing floor/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H3342>/H9021', 'inflected', 'heb', 'ומיקבך', '["u./mi./yik.Ve./cha"]', '["and/ from/ wine-press/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157G}/H9031/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["I love/ you","[those who] love/ you","he loved/ you","he loves/ you","they love/ you"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4836}/[H7527]', 'inflected', 'heb', 'מַרְצֵעַ', '["martsêaʻ"]', '["the/ awl"]', '["n-m"]', 'an awl aul.', 'from 7527;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241G}/H9023/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["[is] in/ ears/ his","[was] in/ ears/ his","in/ ear/ his","in/ ears/ his"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1817C}/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["and/ in the/ door"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0519}/H9021/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["to/ maidservant of/ your","to/ maidservant/ your"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7971H}/H9041/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["when/ letting go/ you"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1241}/H9021/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["in/ herd/ your"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H6629G>/H9021', 'inflected', 'heb', 'ובצאנך', '["u./ve./tzo.ne./Kha"]', '["and/ in/ flock/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1060}/[H1069]', 'inflected', 'heb', 'בְּכוֹר', '["bᵉkôwr"]', '["by/ [the] firstborn of"]', '["n-m"]', 'first-born; hence, chief eldest (son), firstborn(-ling).', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4325G}\/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["like <the>/ water"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318G}/H9041/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["coming out/ you","going out/ you"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0935K}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ goes","when/ went"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0168G}/H9021/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["to/ tents/ your"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4399}\/[H4397]', 'inflected', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["work"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2490C}/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["from/ when began","from/ when begins"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2770}/[H2763]', 'lemma', 'heb', 'חֶרְמֵשׁ', '["chermêsh"]', '["a sickle"]', '["n-m"]', 'a sickle (as cutting) sickle.', 'from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7054}/[H6965]', 'inflected', 'heb', 'קָמָה', '["qâmâh"]', '["among/ [the] standing grain<s> of","in the/ standing grain","in/ [the] standing grain of"]', '["n-f"]', 'something that rises, i.e. a stalk of grain (standing) corn, grown up, stalk.', 'feminine of active participle of 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4530}/[H4549]', 'lemma', 'heb', 'מִסָּה', '["miççâh"]', '["a sufficiency of"]', '["n"]', 'abundance, i.e. (adverbially) liberally tribute.', 'from 4549 (in the sense of flowing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0428}\/[H411]', 'inflected', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["<the>/ these"]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1637>/H9021', 'inflected', 'heb', 'מגרנך', '["mi./ga.re.ne./Kha"]', '["from/ threshing floor/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2282}/H9021/[H2287]', 'inflected', 'heb', 'חַג', '["chag"]', '["at/ festival/ your"]', '["n-m"]', 'a festival, or a victim therefor (solemn) feast (day), sacrifice, solemnity.', 'or חָג; from 2287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8056}/[H8055]', 'lemma', 'heb', 'שָׂמֵחַ', '["sâmêach"]', '["[a person] joyful","[the people] joyful of","[the] [people] joyful of","[was] joyful","joyful"]', '["a"]', 'blithe or gleeful (be) glad, joyful, (making) merry((-hearted), -ily), rejoice(-ing).', 'from 8055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2282}/[H2287]', 'inflected', 'heb', 'חַג', '["chag"]', '["at the/ festival","at the/ festivals","at/ [the] festival of"]', '["n-m"]', 'a festival, or a victim therefor (solemn) feast (day), sacrifice, solemnity.', 'or חָג; from 2287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2282}/[H2287]', 'inflected', 'heb', 'חַג', '["chag"]', '["and/ at the/ festivals","and/ at/ [the] festival of"]', '["n-m"]', 'a festival, or a victim therefor (solemn) feast (day), sacrifice, solemnity.', 'or חָג; from 2287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7620G}/[H7650]', 'inflected', 'heb', 'שָׁבוּעַ', '["shâbûwaʻ"]', '["the/ weeks"]', '["n-m"]', 'literally, sevened, i.e. a week (specifically, of years) seven, week.', 'or שָׁבֻעַ; also (feminine) שְׁבֻעָה; properly, passive participle of 7650 as a denominative of 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4979}/[H4976]', 'inflected', 'heb', 'מַתָּנָה', '["mattânâh"]', '["according to/ [the] gift of"]', '["n-f"]', 'a present; specifically (in a good sense), a sacrificial offering, (in a bad sense) a bribe gift.', 'feminine of 4976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7626H>/H9021', 'inflected', 'heb', 'לשבטיך', '["li/sh.va.Tei./kha"]', '["for/ tribes/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0842}/[H833]', 'lemma', 'heb', 'אֲשֵׁרָה', '["ʼăshêrâh"]', '["Asherah poles","[the] Asherah pole","an Asherah pole"]', '["n-pr-f"]', 'Asherah (or Astarte) a Phoenician goddess; also an image of the same grove. Compare 6253.', 'or אֲשֵׁירָה; from 833; happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H8121>', 'inflected', 'heb', 'ולשמש', '["ve./la./She.mesh"]', '["and/ to the/ sun"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3394}/[H3391]', 'inflected', 'heb', 'יָרֵחַ', '["yârêach"]', '["to the/ moon"]', '["n-m"]', 'the moon moon. Yrechow. See 3405.', 'from the same as 3391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8179G}/H9021/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["gates/ your"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5619}/H9038/[H5619]', 'inflected', 'heb', 'סָקַל', '["çâqal"]', '["and/ you will stone/ them"]', '["v"]', 'properly, to be weighty; but used only in the sense of lapidation or its contrary (as if a delapidation) (cast, gather out, throw) stone(-s), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5707}/[H5749]', 'inflected', 'heb', 'עֵד', '["ʻêd"]', '["the/ witness","the/ witnesses"]', '["n-m"]', 'concretely, a witness; abstractly, testimony; specifically, a recorder, i.e. prince witness.', 'contracted from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7130G}/H9021\/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["from/ midst/ your"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1779}/[H1777]', 'lemma', 'heb', 'דִּין', '["dîyn"]', '["[the] case","[the] case of","[the] cause of","a cause","dispute","judgment"]', '["n-m"]', 'judgement (the suit, justice, sentence or tribunal); by implication also strife cause, judgement, plea, strife.', 'or (Job 19:29) דּוּן; from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1779}/[H1777]', 'inflected', 'heb', 'דִּין', '["dîyn"]', '["and/ dispute"]', '["n-m"]', 'judgement (the suit, justice, sentence or tribunal); by implication also strife cause, judgement, plea, strife.', 'or (Job 19:29) דּוּן; from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8199}/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["the/ judge","the/ judges"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697J}/[H1696]', 'lemma', 'heb', 'דָּבָר', '["dâbâr"]', '["[the] word of","[the] words of","[was] [the] word of","a word","thing"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3384B}/H9031/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["I taught/ you","they will instruct/ you","will they instruct/ you"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2087}/[H2102]', 'inflected', 'heb', 'זָדוֹן', '["zâdôwn"]', '["with/ presumption","with/ pride"]', '["n-m"]', 'arrogance presumptuously, pride, proud (man).', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2102}/H9013/[H2102]', 'inflected', 'heb', 'זוּד', '["zûwd"]', '["they will act presumptuously/ !"]', '["v"]', 'to seethe; figuratively, to be insolent be proud, deal proudly, presume, (come) presumptuously, sod.', 'or (by permutation) זִיד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5750}\/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["again","still","yet"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3423H}/H9034/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["and/ they took possession of/ it","and/ they will take possession of/ it","and/ we will take possession of/ it","and/ you will take possession of/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439G}/H9030/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["[are] around/ me","[were] around/ me","around/ me"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3427}/H9043/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["when/ sat/ he","when/ sits/ he"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3678G}/[H3680]', 'lemma', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["[is] a throne","[is] a throne of","[the] throne","[the] throne of","a throne","a throne of","thrones"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121G}/H9023/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ descendants/ his","and/ sons/ his"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5159}/H9023/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["and/ inheritance/ his"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941J}/[H8199]', 'lemma', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["[the] manner of","[the] right of","[the] right[s] of"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H3895H>', 'inflected', 'heb', 'והלחיים', '["ve./ha./le.cha.Ya.yim"]', '["and/ the/ two cheeks"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6896}/[H6895]', 'inflected', 'heb', 'קֵבָה', '["qêbâh"]', '["and/ the/ stomach"]', '["n-f"]', 'the paunch (as a cavity) or first stomach of ruminants maw.', 'from 6895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1488}/[H1494]', 'lemma', 'heb', 'גֵּז', '["gêz"]', '["[the] fleece of","[the] mowings of","mown grass"]', '["n-m"]', 'a fleece (as shorn); also mown grass fleece, mowing, mown grass.', 'from 1494;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315L}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["appetite/ his","appetite/ its","desire/ his","desire/ its","self/ his","throat/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2506A}/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["like/ [the] share of","like/ a portion"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0001G}\/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["the/ fathers"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8441}/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["according to/ [the] abominations of"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7080}/[H7080]', 'lemma', 'heb', 'קָסַם', '["qâçam"]', '["[one who] divines","divine","diviners","they divine","you will divine"]', '["v"]', 'properly, to distribute, i.e. determine by lot or magical scroll; by implication, to divine divine(-r, -ation), prudent, soothsayer, use (divination).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5172}/[H5172]', 'inflected', 'heb', 'נָחַשׁ', '["nâchash"]', '["and/ an augurer"]', '["v"]', 'properly, to hiss, i.e. whisper a (magic) spell; generally, to prognosticate × certainly, divine, enchanter, (use) × enchantment, learn by experience, × indeed, diligently observe.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3784}/[H3784]', 'inflected', 'heb', 'כָּשַׁף', '["kâshaph"]', '["and/ a sorcerer"]', '["v"]', 'properly, to whisper a spell, i.e. to inchant or practise magic sorcerer, (use) witch(-craft).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2266}/[H2266]', 'inflected', 'heb', 'חָבַר', '["châbar"]', '["and/ [one who] casts"]', '["v"]', 'to join (literally or figuratively); specifically (by means of spells) to fascinate charm(-er), be compact, couple (together), have fellowship with, heap up, join (self, together), league.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2267}/[H2266]', 'lemma', 'heb', 'חֶבֶר', '["cheber"]', '["a spell","spells"]', '["n-m"]', 'a society; also a spell charmer(-ing), company, enchantment, × wide.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3049}/[H3045]', 'inflected', 'heb', 'יִדְּעֹנִי', '["yiddᵉʻônîy"]', '["and/ a familiar spirit","and/ soothsayer","and/ soothsayers"]', '["n-m"]', 'properly, a knowing one; specifically, a conjurer; (by impl) a ghost wizard.', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1875}/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["and/ [one who] enquires","and/ [one who] seeks","and/ [one who] seeks carefully","and/ [those who] seek","and/ let us consult","and/ seek","so/ I may consult","so/ we may enquire"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1558}/[H1556]', 'inflected', 'heb', 'גָּלָל', '["gâlâl"]', '["and/ on/ account of"]', '["n-m"]', 'a circumstance (as rolled around); only used adverbially, on account of because of, for (sake).', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251I}/H9028/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["brothers/ their","countrymen/ their","relatives/ their"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5892B}/H9028/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["[were] in/ cities/ their","in/ cities/ their","in/ own cities/ their"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1004B}/H9028/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ in/ houses/ their"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8027}/[H7969]', 'inflected', 'heb', 'שָׁלַשׁ', '["shâlash"]', '["and/ they did a third time","and/ you will divide into three","and/ you will do three times"]', '["v"]', 'to be (causatively, make) triplicate (by restoration, in portions, strands, days or years) do the third time, (divide into, stay) three (days, -fold, parts, years old).', 'a primitive root perhaps originally to intensify, i.e. treble; but apparently used only as denominative from 7969,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5157}/H9031/[H5157]', 'inflected', 'heb', 'נָחַל', '["nâchal"]', '["he will give as an inheritance/ you"]', '["v"]', 'to inherit (as a (figurative) mode of descent), or (generally) to occupy; causatively, to bequeath, or (generally) distribute, instate divide, have (inheritance), take as a heritage, (cause to, give to, make to) inherit, (distribute for, divide (for, for an, by), give for, have, leave for, take (for)) inheritance, (have in, cause to, be made to) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3293A>', 'inflected', 'heb', 'ביערים', '["ba/i.Ya.''ar","ba/i.ye.''a.Rim","va/i.Ya.''ar","va/i.ya.''Ar"]', '["in the/ forest","in the/ forests","in the/ thicket[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2404}/[H2404]', 'inflected', 'heb', 'חָטַב', '["châṭab"]', '["to the/ wood-cutters","to/ cut"]', '["v"]', 'to chop or carve wood cut down, hew(-er), polish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1631}/[H1629]', 'inflected', 'heb', 'גַּרְזֶן', '["garzen"]', '["by the/ axe"]', '["n-m"]', 'an axe ax.', 'from 1629;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3772G}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["to/ [the] cutters of","to/ cut","to/ cut down"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6086J}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["the/ gallows","the/ tree"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2552}/[H2552]', 'lemma', 'heb', 'חָמַם', '["châmam"]', '["I am warm","he is warm","he warmed himself","is hot","it became hot","it keeps [them] warm","it may grow warm","it was warm","it will be hot","they are hot","will it be warm"]', '["v"]', 'to be hot (literally or figuratively) enflame self, get (have) heat, be (wax) hot, (be, wax) warm (self, at).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5381}/H9033/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["and/ he will overtake/ him"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1980I}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ to/ walk"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0693}/[H693]', 'inflected', 'heb', 'אָרַב', '["ʼârab"]', '["and/ he lay in wait","and/ he will lie in wait","and/ they lay in wait","and/ you will lie in wait"]', '["v"]', 'to lurk (lie in) ambush(-ment), lay (lie in) wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6965J}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ I will arise","and/ he will rise up","and/ it has risen up","and/ they rose up"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5355A}/[H5352]', 'inflected', 'heb', 'נָקִי', '["nâqîy"]', '["<the>/ innocent","the/ innocent","the/ innocent [person]"]', '["a"]', 'innocent blameless, clean, clear, exempted, free, guiltless, innocent, quit.', 'or נָקִיא; (Joel 4:19; Jonah 1:14), from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5253}/[H5253]', 'lemma', 'heb', 'נָסַג', '["nâçag"]', '["[one who] displaces","it will be turned back","you displace","you will displace"]', '["v"]', 'to retreat departing away, remove, take (hold), turn away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5159}/H9021/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["in/ inheritance/ your"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3423H}/H9034\/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["to/ take possession of/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0376I>', 'inflected', 'heb', 'באיש', '["be./''Ish","ve./''Ish"]', '["among/ everyone of","in/ anyone"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7379}/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["the/ dispute"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8199}/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["and/ the/ judge","and/ the/ judges"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251I}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["to/ countryman/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8127G}/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["for/ tooth"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7272}\/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["for/ foot"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7393G}/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["and/ chariot","and/ chariot[s]","and/ charioteer","and/ chariotry","and/ chariotry of"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5927G}/H9031/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["who/ brought up/ you"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7126G}/H9046/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["when/ draw near/ you"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7131}/[H7126]', 'lemma', 'heb', 'קָרֵב', '["qârêb"]', '["[are] approaching"]', '["a"]', 'near approach, come (near, nigh), draw near.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7401}/[H7401]', 'lemma', 'heb', 'רָכַךְ', '["râkak"]', '["be timid","he has made faint","it be weak","it has been softened","it should be weak","it was soft","they were soft"]', '["v"]', 'to soften (intransitively or transitively), used figuratively (be) faint(-hearted), mollify, (be, make) soft(-er), be tender.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2648}/[H2648]', 'lemma', 'heb', 'חָפַז', '["châphaz"]', '["hurrying away","it is alarmed","they hurried away","you make haste"]', '["v"]', 'properly, to start up suddenly, i.e. (by implication) to hasten away, to fear (make) haste (away), tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3467}/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["<into>/ a deliverer","to/ deliver","to/ give victory","to/ save","to/ save [him]"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7860>', 'inflected', 'heb', 'השטרים', '["ha./sho.Ter","ha./sho.te.Rim"]', '["the/ officers","the/ official","the/ officials"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2596}/H9033/[H2614]', 'inflected', 'heb', 'חָנַךְ', '["chânak"]', '["he has dedicated/ it","he will dedicate/ it"]', '["v"]', 'properly, to narrow; figuratively, to initiate or discipline dedicate, train up.', 'a primitive root; (compare 2614)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004B}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["of/ household/ his","to/ house/ his","to/ own house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4421}/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["in <the>/ battle","in the/ battle","in/ battle"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2490I}/H9033/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["he has put to use/ it","he will put to use/ it","you will put to use/ it"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947I}/H9034/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["he had taken/ her","he has taken/ her","he will take/ her"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7390}/[H7401]', 'inflected', 'heb', 'רַךְ', '["rak"]', '["and/ [the] weak of","and/ weak","and/ weak of"]', '["a"]', 'tender (literally or figuratively); by implication, weak faint((-hearted), soft, tender ((-hearted), one), weak.', 'from 7401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3824}/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["<the>/ heart"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3824}/H9023/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["according to/ own heart/ his","like/ heart/ his"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3615G}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["when/ finish","when/ finished","when/ had finished"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7218H>', 'inflected', 'heb', 'בראשי', '["be./Rosh","be./ra.Shei","va./Rosh"]', '["<in>/ [the] chiefs of","at the/ head","at/ [the] head of","on/ [the] chief of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6030B}/H9031/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["I answered/ you","I will answer/ you","[one who] answers/ you","did he answer/ you","he will answer/ you","it will answer/ you","may he answer/ you","they will answer/ you","will he answer/ you"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7999B}/[H7999]', 'lemma', 'heb', 'שָׁלַם', '["shâlam"]', '["[am] [the] peaceful [ones] of","he causes to be at peace","he performs","it has made peace","it made peace","it will be at peace","it will make peace","they had made peace"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2138}/H9024/[H2142]', 'inflected', 'heb', 'זָכוּר', '["zâkûwr"]', '["male/ its"]', '["n-m"]', 'a male (of man or animals) males, men-children.', 'properly, passive participle of 2142, but used for 2145;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2763A}/H9038/[H2763]', 'inflected', 'heb', 'חָרַם', '["châram"]', '["he totally destroyed/ them","he will totally destroy/ them","to totally destroy/ them","you will totally destroy/ them"]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8441}/H9028/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["abominations/ their"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6696A}/[H6696]', 'lemma', 'heb', 'צוּר', '["tsûwr"]', '["[are] shutting up","[they were] laying siege","[were] laying siege","he will lay siege","lay siege","we will shut up","you will lay siege"]', '["v"]', 'to cramp, i.e. confine (in many applications, literally and figuratively, formative or hostile) adversary, assault, beset, besiege, bind (up), cast, distress, fashion, fortify, inclose, lay siege, put up in bags.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8610}/H9034/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["to/ capture/ it"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6086H}/H9024/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["tree[s]/ its"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5080}/[H5080]', 'inflected', 'heb', 'נָדַח', '["nâdach"]', '["by/ wielding","to/ thrust [him] down"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1631}/[H1629]', 'lemma', 'heb', 'גַּרְזֶן', '["garzen"]', '["an axe"]', '["n-m"]', 'an axe ax.', 'from 1629;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0120G}/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["¿/ human"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0935N}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["to/ go"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4692}/[H6696]', 'inflected', 'heb', 'מָצוֹר', '["mâtsôwr"]', '["in <the>/ state of siege","in the/ siege","in/ [the] siege","in/ siege"]', '["n-m"]', 'something hemming in, i.e. (objectively) a mound (of besiegers), (abstractly) a siege, (figuratively) distress; or (subjectively) a fastness besieged, bulwark, defence, fenced, fortress, siege, strong (hold), tower.', 'or מָצוּר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4692}/[H6696]', 'lemma', 'heb', 'מָצוֹר', '["mâtsôwr"]', '["[the] fortification","[the] siege of","a fortification","a siege","fortification","siege","siege work[s]"]', '["n-m"]', 'something hemming in, i.e. (objectively) a mound (of besiegers), (abstractly) a siege, (figuratively) distress; or (subjectively) a fastness besieged, bulwark, defence, fenced, fortress, siege, strong (hold), tower.', 'or מָצוּר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3381}/H9044\/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["falls/ it"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2205G}/H9021/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["elders/ your","old [people]/ your"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8199}/H9031/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["and/ judges/ your","and/ rulers/ your"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5923}/[H5953]', 'inflected', 'heb', 'עֹל', '["ʻôl"]', '["by/ a yoke","in/ [the] yoke of"]', '["n-m"]', 'a yoke (as imposed on the neck), literally or figuratively yoke.', 'or עוֹל; from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5697A}/[H5695]', 'inflected', 'heb', 'עֶגְלָה', '["ʻeglâh"]', '["the/ heifer"]', '["n-f"]', 'a (female) calf, especially one nearly grown (i.e. a heifer) calf, cow, heifer.', 'feminine of 5695;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6202}/[H6203]', 'inflected', 'heb', 'עָרַף', '["ʻâraph"]', '["and/ they will break [the] neck of"]', '["v"]', 'to break the neck; hence (figuratively) to destroy that is beheaded, break down, break (cut off, strike off) neck.', 'a primitive root (identical with through the idea of slopping); properly, to bend downward; but used only as a denominative from 6203,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310I}/H9028/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["mouth/ their"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6202}/[H6203]', 'inflected', 'heb', 'עָרַף', '["ʻâraph"]', '["<the>/ broken necked"]', '["v"]', 'to break the neck; hence (figuratively) to destroy that is beheaded, break down, break (cut off, strike off) neck.', 'a primitive root (identical with through the idea of slopping); properly, to bend downward; but used only as a denominative from 6203,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5869A}/H9025/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ eyes/ our"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1197I}/[H1198]', 'lemma', 'heb', 'בָּעַר', '["bâʻar"]', '["I have removed","[am] about to sweep away","he removed","you will remove"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7628A}/H9023/[H7618]', 'inflected', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["captive[s]/ his"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7633}/[H7628]', 'inflected', 'heb', 'שִׁבְיָה', '["shibyâh"]', '["among the/ [female] captive[s]","in <the>/ captivity","on the/ group of captives"]', '["n-f"]', 'exile (abstractly or concretely and collectively) captives(-ity).', 'feminine of 7628;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2836A}/[H2820]', 'inflected', 'heb', 'חָשַׁק', '["châshaq"]', '["and/ you will love"]', '["v"]', 'to cling, i.e. join, (figuratively) to love, delight in; elliptically; to deliver have a delight, (have a) desire, fillet, long, set (in) love.', 'a primitive root; also interchangeable for 2820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218A>/H9024', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ her"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6856}/H9024/[H6852]', 'inflected', 'heb', 'צִפֹּרֶן', '["tsippôren"]', '["finger-nails/ her"]', '["n-m"]', 'properly, a claw, i.e. (human) nail; also the point of a style (or pen, tipped with adamant) nail, point.', 'from 6852 (in the denominative sense (from 6833) of scratching);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7628A}/H9024/[H7618]', 'inflected', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["captivity/ her"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1167H}/H9034/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["and/ you will be husband/ her"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971H}/H9034/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ they let go/ her","and/ you will let go/ her"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315L}/H9024/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["for/ self/ her"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4376}/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["and/ [the] sellers of","and/ [were] selling [it]","and/ certainly <sell>"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4376}/H9034/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["you will sell/ her"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6014B}/[H6016]', 'lemma', 'heb', 'עָמַר', '["ʻâmar"]', '["you will treat as a slave"]', '["v"]', 'properly, apparently to heap; figuratively, to chastise (as if piling blows); to gather grain bind sheaves, make merchandise of.', 'a primitive root; specifically (as denominative from 6016)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6031B}/H9034\/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["you have humiliated/ her"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0157G}/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["<the>/ lovable","the/ loved [one]"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8130}/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["and/ the/ hated [one]"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8146}/[H8130]', 'inflected', 'heb', 'שָׂנִיא', '["sânîyʼ"]', '["to the/ hated [wife]"]', '["a"]', 'hated hated.', 'from 8130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5157}/H9043/[H5157]', 'inflected', 'heb', 'נָחַל', '["nâchal"]', '["causes to inherit/ he"]', '["v"]', 'to inherit (as a (figurative) mode of descent), or (generally) to occupy; causatively, to bequeath, or (generally) distribute, instate divide, have (inheritance), take as a heritage, (cause to, give to, make to) inherit, (distribute for, divide (for, for an, by), give for, have, leave for, take (for)) inheritance, (have in, cause to, be made to) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1069}/[H1061]', 'inflected', 'heb', 'בָּכַר', '["bâkar"]', '["to/ treat as firstborn"]', '["v"]', 'to give the birthright make firstborn, be firstling, bring forth first child (new fruit).', 'a primitive root; properly, to burst the womb, i.e. (causatively) bear or make early fruit (of woman or tree); also (as denominative from 1061)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8130}/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["the/ hated [one]"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0202}/H9023/[H205]', 'inflected', 'heb', 'אוֹן', '["ʼôwn"]', '["manly vigor/ his","trouble/ his","vigor/ his","wealth/ his"]', '["n-m"]', 'ability, power, (figuratively) wealth force, goods, might, strength, substance.', 'probably from the same as 205 (in the sense of effort, but successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5637}/[H5637]', 'lemma', 'heb', 'סָרַר', '["çârar"]', '["[are] rebellious","[are] rebels","[is] stubborn","[who are] rebellious","it is stubborn","rebellious","rebellious [people]","rebels","stubborn"]', '["v"]', 'to turn away, i.e. (morally) be refractory × away, backsliding, rebellious, revolter(-ing), slide back, stubborn, withdrew.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4784}/[H4784]', 'inflected', 'heb', 'מָרָה', '["mârâh"]', '["and/ rebellious","and/ we have rebelled"]', '["v"]', 'to be (causatively, make) bitter (or unpleasant); (figuratively) to rebel (or resist; causatively, to provoke) bitter, change, be disobedient, disobey, grievously, provocation, provoke(-ing), (be) rebel (against, -lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H6963A>', 'inflected', 'heb', 'ובקול', '["u./ve./Kol"]', '["and/ to/ [the] voice of","and/ with/ a voice"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121A}/H9025/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["children/ our","son/ our","sons/ our"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963A>/H9025', 'inflected', 'heb', 'בקולנו', '["be./ko.Le./nu"]', '["to/ voice/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2151B}/[H2107]', 'lemma', 'heb', 'זָלַל', '["zâlal"]', '["a glutton","gluttons"]', '["v"]', 'to shake (as in the wind), i.e. to quake; figuratively, to be loose morally, worthless or prodigal blow down, glutton, riotous (eater), vile.', 'a primitive root (compare 2107);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5433B}/[H5433]', 'inflected', 'heb', 'סָבָא', '["çâbâʼ"]', '["and/ a drunkard"]', '["v"]', 'to quaff to satiety, i.e. become tipsy drunkard, fill self, Sabean, (wine-) bibber.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7275}/H9033/[H7263]', 'inflected', 'heb', 'רָגַם', '["râgam"]', '["and/ they stoned/ him","and/ they will stone/ him"]', '["v"]', 'to cast together (stones), i.e. to lapidate × certainly, stone.', 'a primitive root (compare 7263, 7321, 7551);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3372G}\/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["and/ they may fear"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5038}/H9023/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["corpse/ his"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6912}/H9033/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["they buried/ him","you will bury/ him"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7716}/H9023/[H7582]', 'inflected', 'heb', 'שֶׂה', '["seh"]', '["sheep/ his"]', '["n-m"]', 'a member of a flock, i.e. a sheep or goat (lesser, small) cattle, ewe, goat, lamb, sheep. Compare 2089.', 'or שֵׂי; probably from 7582 through the idea of pushing out to graze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5080}/[H5080]', 'lemma', 'heb', 'נָדַח', '["nâdach"]', '["I banished","I have banished","[it is] thrust out","[the] banished [men] of","[the] banished [ones] of","[the] outcasts of","a banished [one]","an outcast","going astray","have you driven out","he will be cast out","hunted","it has been banished","outcasts","they had been driven away","they have driven away"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725G}/H9038/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["you will return/ them"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0622}/H9033/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["and/ he gathered/ him","and/ you will deliver/ him","and/ you will gather/ it"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725H}/H9033/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ you will return/ it"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8071}/H9023/[H5566]', 'inflected', 'heb', 'שִׂמְלָה', '["simlâh"]', '["for/ clothing/ his"]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5956}\/[H5956]', 'inflected', 'heb', 'עָלַם', '["ʻâlam"]', '["to/ hide yourself"]', '["v"]', 'to veil from sight, i.e. conceal (literally or figuratively) × any ways, blind, dissembler, hide (self), secret (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1397}/[H1396]', 'lemma', 'heb', 'גֶּבֶר', '["geber"]', '["O man","[is the] man","[is] a man","[the] man of","a man","man","men"]', '["n-m"]', 'properly, a valiant man or warrior; generally, a person simply every one, man, × mighty.', 'from 1396;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0428}\/[H411]', 'inflected', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["<of> these [things]","these [things]"]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0667}/[H6524]', 'lemma', 'heb', 'אֶפְרֹחַ', '["ʼephrôach"]', '["young ones"]', '["n-m"]', 'the brood of a bird young (one).', 'from 6524 (in the sense of bursting the shell);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1000}/[H948]', 'lemma', 'heb', 'בֵּיצָה', '["bêytsâh"]', '["eggs","eggs of"]', '["n-f"]', 'an egg (from its whiteness) egg.', 'from the same as 948;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0517}/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["and/ the/ mother"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0667}/[H6524]', 'inflected', 'heb', 'אֶפְרֹחַ', '["ʼephrôach"]', '["the/ young ones"]', '["n-m"]', 'the brood of a bird young (one).', 'from 6524 (in the sense of bursting the shell);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1000}/[H948]', 'inflected', 'heb', 'בֵּיצָה', '["bêytsâh"]', '["the/ eggs"]', '["n-f"]', 'an egg (from its whiteness) egg.', 'from the same as 948;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0517}/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["the/ mother"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1121H}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["the/ young ones"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117K>\', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4624>', 'opaque', 'heb', 'מַעֲקֶה', '["maʻăqeh"]', '["a parapet"]', '["n-m"]', 'a parapet battlement.', 'from an unused root meaning to repress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1406}/H9021/[H1342]', 'inflected', 'heb', 'גָּג', '["gâg"]', '["for/ roof/ your"]', '["n-m"]', 'a roof; by analogy, the top of an altar roof (of the house), (house) top (of the house).', 'probably by reduplication from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5307G}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["<the>/ [one who] falls","<the>/ falling","those/ [who] fall","those/ [who] had fallen","those/ [who] have fallen","which/ fell"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942I}/[H6942]', 'lemma', 'heb', 'קָדַשׁ', '["qâdash"]', '["it should be set apart"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4395}/[H4392]', 'inflected', 'heb', 'מְלֵאָה', '["mᵉlêʼâh"]', '["the/ full produce"]', '["n-f"]', 'something fulfilled, i.e. abundance (of produce) (first of ripe) fruit, fulness.', 'feminine of 4392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2233G}/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["<the>/ seed","[is] the/ seed","the/ seed"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8393}/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["and/ [the] produce of"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3754>\', 'inflected', 'heb', 'הכרם ס', '["ha./Ka.rem"]', '["the/ vineyard"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7794}/[H7788]', 'inflected', 'heb', 'שׁוֹר', '["shôwr"]', '["with/ an ox"]', '["n-m"]', 'a bullock (as a traveller) bull(-ock), cow, ox, wall (by mistake for 7791).', 'from 7788;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3162B}\/[H3161]', 'inflected', 'heb', 'יַחַד', '["yachad"]', '["together"]', '["n-m"]', 'properly, a unit, i.e. (adverb) unitedly alike, at all (once), both, likewise, only, (al-) together, withal.', 'from 3161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6593}/[H6580]', 'inflected', 'heb', 'פִּשְׁתֶּה', '["pishteh"]', '["and/ flax<es>","and/ linen<s>"]', '["n-f"]', 'linen (i.e. the thread, as carded) flax, linen.', 'from the same as 6580 as in the sense of comminuting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1434}/[H1431]', 'lemma', 'heb', 'גְּדִל', '["gᵉdil"]', '["festoons","tassels"]', '["n-m"]', 'thread, i.e. a tassel or festoon fringe, wreath.', 'from 1431 (in the sense of twisting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3682}/H9021/[H3680]', 'inflected', 'heb', 'כְּסוּת', '["kᵉçûwth"]', '["covering/ your"]', '["n-f"]', 'a cover (garment); figuratively, a veiling covering, raiment, vesture.', 'from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8130}/H9034/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["and/ he hated/ her","and/ he will hate/ her"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760J}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ he will make"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5949}/[H5953]', 'lemma', 'heb', 'עֲלִילָה', '["ʻălîylâh"]', '["deed","deed[s]","deeds","deeds of","practices"]', '["n-f"]', 'an exploit (of God), or a performance (of man, often in a bad sense); by implication, an opportunity act(-ion), deed, doing, invention, occasion, work.', 'or עֲלִלָה; from 5953 in the sense of effecting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1331}/[H1330]', 'lemma', 'heb', 'בְּתוּלִים', '["bᵉthûwlîym"]', '["[are] [the] virginiti<es> of","[the] virginiti<es> of","virginiti<es>"]', '["n-f"]', '(collectively and abstractly) virginity; by implication and concretely, the tokens of it × maid, virginity.', 'masculine plural of the same as 1330;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8179G}/H9011/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["the/ gate/ towards"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760J}/[H7760]', 'lemma', 'heb', 'שׂוּם', '["sûwm"]', '["he has made"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1323G}/H9021/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["to/ daughter/ your"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6064}/[H6064]', 'inflected', 'heb', 'עָנַשׁ', '["ʻânash"]', '["and/ he imposed a fine on","and/ they are punished","and/ they will fine"]', '["v"]', 'properly, to urge; by implication, to inflict a penalty, specifically, to fine amerce, condemn, punish, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7971I}/H9034/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["to/ send away/ her"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/H9023\', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["day/ his","days/ his"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5619}/H9034/[H5619]', 'inflected', 'heb', 'סָקַל', '["çâqal"]', '["and/ they will stone/ her"]', '["v"]', 'properly, to be weighty; but used only in the sense of lapidation or its contrary (as if a delapidation) (cast, gather out, throw) stone(-s), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5892B}/H9024/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["cities/ its","city/ her"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7901I}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["who/ lay"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3478}\/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["from/ Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5291}/[H5288]', 'lemma', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["[is] a young woman","[the] maids of","a girl","a young woman","girl","young woman","young women"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5619}/[H5619]', 'inflected', 'heb', 'סָקַל', '["çâqal"]', '["and/ he stoned","and/ he stoned [them]","and/ they stoned","and/ you will stone"]', '["v"]', 'properly, to be weighty; but used only in the sense of lapidation or its contrary (as if a delapidation) (cast, gather out, throw) stone(-s), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0781}/[H781]', 'inflected', 'heb', 'אָרַשׂ', '["ʼâras"]', '["<the>/ betrothed"]', '["v"]', 'to engage for matrimony betroth, espouse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5291}/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["and/ to the/ young woman"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965J}/[H6965]', 'lemma', 'heb', 'קוּם', '["qûwm"]', '["[am] about to raise up","[are] rising up","[is] arising","[which] it will arise","[will] rise up","arise","he has raised up","he will arise","they have arisen","they have risen up","you have risen up"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7523}/H9033/[H7523]', 'inflected', 'heb', 'רָצַח', '["râtsach"]', '["and/ he will kill/ him"]', '["v"]', 'properly, to dash in pieces, i.e. kill (a human being), especially to murder put to death, kill, (man-) slay(-er), murder(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3467}/[H3467]', 'lemma', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["I am delivered","I will deliver","I will save","O deliverer","[am] about to save","[are] about to deliver","[is one who] delivers","[is] a deliverer","[is] saved","[was] a deliverer","[were] a deliverer","[which] it has been saved","[who] he will give victory","[will be] a deliverer","a deliverer","deliverer","deliverers","he delivers","he saved","he saves","he will be delivered","he will be saved","he will save","it has been saved","it has delivered","it has given victory","it saved","it will be saved","it will save","let them deliver","save","they will deliver","to deliver","we have been saved","will I deliver","you deliver","you delivered","you have saved","you may be saved","you save","you will deliver"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8610}/H9034/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["and/ he seized/ it","and/ he will seize/ her"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6031B}/H9034/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["he has humiliated/ her"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971I}/H9034/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["I sent away/ her","he sent away/ her","to send away/ her"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9023\/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["ancestors/ his","father/ his"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6481}/[H6481]', 'lemma', 'heb', 'פָּצַע', '["pâtsaʻ"]', '["[one who] is wounded of"]', '["v"]', 'to split, i.e. wound wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1795}/[H1794]', 'lemma', 'heb', 'דַּכָּה', '["dakkâh"]', '["crushing"]', '["n-f"]', 'mutilated wounded.', 'from 1794 like 1793;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8212}/[H8210]', 'lemma', 'heb', 'שׇׁפְכָה', '["shophkâh"]', '["penis"]', '["n-f"]', 'a pipe (for pouring forth, e.g. wine), i.e. the penis privy member.', 'feminine of a derivative from 8210;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6951}/[H6950]', 'inflected', 'heb', 'קָהָל', '["qâhâl"]', '["among the/ assembly","by/ a company of","in the/ assembly","in/ [the] assembly","in/ [the] assembly of"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4464>', 'opaque', 'heb', 'מַמְזֵר', '["mamzêr"]', '["a bastard","a mixed population"]', '["n-m"]', 'a mongrel, i.e. born of a Jewish father and a heathen mother bastard.', 'from an unused root meaning to alienate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5984H}/[H5983]', 'lemma', 'heb', 'עַמּוֹנִי', '["ʻAmmôwnîy"]', '["Ammonite","Ammonite [women]","[the] Ammonites","an Ammonite"]', '["a"]', 'an Ammonite or (the adjective) Ammonitish Ammonite(-s).', 'patronymically from 5983;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4125}/[H4124]', 'inflected', 'heb', 'מוֹאָבִי', '["Môwʼâbîy"]', '["and/ a Moabite"]', '["a"]', 'a Moabite or Moabitess, i.e. a descendant from Moab (woman) of Moab, Moabite(-ish, -ss).', 'feminine מוֹאָבִיָּה; or מוֹאָבִיתxlit Môwâbîyth corrected to Môwʼâbîyth; patronymical from 4124;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6923}/[H6923]', 'lemma', 'heb', 'קָדַם', '["qâdam"]', '["I am early","I did [the] first time","let us approach","they anticipate","they come to meet","they had met","they met","they went in front","will I come to meet"]', '["v"]', 'to project (one self), i.e. precede; hence, to anticipate, hasten, meet (usually for help) come (go, (flee)) before, disappoint, meet, prevent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3899H}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["for <the>/ food","with <the>/ food"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3318G}/H9046/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ came out/ you"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6604>', 'inflected', 'heb', 'מפתור', '["mi./pe.Tor"]', '["from/ Pethor"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7043}/H9031/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["to/ curse/ you"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1293}/[H1288]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["[become] <into>/ a blessing","[is] for/ a blessing","into/ blessing"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965G}/H9028/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["peace/ their"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2896C}/H9028/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["and/ good/ their"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8581}/[H8581]', 'lemma', 'heb', 'תַּעָב', '["taʻâb"]', '["[one who] is abhorrent","abhorred","he abhors","it loathed","it was abhorred","they abhor","they do abominably","you have acted abominably","you will abhor"]', '["v"]', 'to loathe, i.e. (morally) detest (make to be) abhor(-red), (be, commit more, do) abominable(-y), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0130}/[H123]', 'lemma', 'heb', 'אֱדֹמִי', '["ʼĔdômîy"]', '["Edomite","Edomite [women]","[the] Edomites","an Edomite"]', '["a"]', 'an Edomite, or descendants from (or inhabitants of) Edom Edomite.', 'or (fully) אֱדוֹמִי ; patronymic from 123; See 726.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7137}/[H7136]', 'inflected', 'heb', 'קָרֶה', '["qâreh"]', '["from/ a happening of"]', '["n-m"]', 'an (unfortunate) occurrence, i.e. some accidental (ceremonial) disqualification uncleanness that chanceth.', 'from 7136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0935K}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ just as/ goes"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3027M}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ a hand","and/ a monument"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3489>', 'inflected', 'heb', 'ויתד', '["ve./ya.Ted"]', '["and/ a spade"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0240}/H9021/[H238]', 'inflected', 'heb', 'אָזֵן', '["ʼâzên"]', '["equipment/ your"]', '["n-m"]', 'a spade or paddle (as having a broad end) weapon.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6627}/H9021/[H3318]', 'inflected', 'heb', 'צָאָה', '["tsâʼâh"]', '["excrement/ your"]', '["n-f"]', 'issue, i.e. (human) excrement that (which) cometh from (out).', 'from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4264}/H9021/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["camp/ your","camps/ your"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5337}/H9031/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["to/ deliver/ you"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725I}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I turned back","and/ I will turn","and/ he turned back","and/ he will turn","and/ he will turn away","and/ he will turn back","and/ it turned back","and/ it will return","and/ it will turn away","and/ they turned back","and/ you turned back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0310A}/H9031\/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["from/ after/ you"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3238}/H9033\/[H3238]', 'inflected', 'heb', 'יָנָה', '["yânâh"]', '["you will maltreat/ him"]', '["v"]', 'to rage or be violent; by implication, to suppress, to maltreat destroy, (thrust out by) oppress(-ing, -ion, -or), proud, vex, do violence.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6945}/[H6942]', 'lemma', 'heb', 'קָדֵשׁ', '["qâdêsh"]', '["a male cult prostitute","cult prostitute[s]"]', '["n-m"]', 'a (quasi) sacred person, i.e. (technically) a (male) devotee (by prostitution) to licentious idolatry sodomite, unclean.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0868}/[H866]', 'lemma', 'heb', 'אֶתְנַן', '["ʼethnan"]', '["[the] hire of","[the] hire of a prostitute","[the] price of"]', '["n-m"]', 'a gift (as the price of harlotry or idolatry) hire, reward.', 'the same as 866;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4242>', 'inflected', 'heb', 'ומחיר', '["u./me.Chir"]', '["and/ [the] hire of","and/ [the] price of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5391B}/[H5391]', 'lemma', 'heb', 'נָשַׁךְ', '["nâshak"]', '["someone will pay interest","you will charge interest"]', '["v"]', 'to strike with a sting (as a serpent); figuratively, to oppress with interest on a loan bite, lend upon usury.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0251I}/H9021/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ to/ countryman/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7999A}/H9033/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["to/ pay/ it"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8193G}/H9021/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["lips/ your","own lips/ your"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6310G}/H9021\/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["with/ mouth/ your"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3754>', 'inflected', 'heb', 'בכרמים', '["ba./ke.ra.Mim","be./Khe.rem","be./khar.Mei","ve./Kha.rem"]', '["[he is] in/ [the] vineyard of","in the/ vineyards","in/ [the] vineyard of","in/ [the] vineyards of","in/ a vineyard"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5315L}/H9021/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["according to/ appetite/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7648}/H9021/[H7646]', 'inflected', 'heb', 'שֹׂבַע', '["sôbaʻ"]', '["satiety/ your"]', '["n-m"]', 'satisfaction (of food or [figuratively] joy) fill, full(-ness), satisfying, be satisfied.', 'from 7646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414H}\/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["you will put [them]"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6998}/[H6998]', 'inflected', 'heb', 'קָטַף', '["qâṭaph"]', '["and/ you will pluck off"]', '["v"]', 'to strip off crop off, cut down (up), pluck.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4425}/[H4448]', 'lemma', 'heb', 'מְלִילָה', '["mᵉlîylâh"]', '["ears of corn"]', '["n-f"]', 'a head of grain (as cut off) ear.', 'from 4448number 4449, corrected to 4448b (in the sense of cropping (compare 4135));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2770}/[H2763]', 'inflected', 'heb', 'חֶרְמֵשׁ', '["chermêsh"]', '["and/ a sickle"]', '["n-m"]', 'a sickle (as cutting) sickle.', 'from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7054}/[H6965]', 'lemma', 'heb', 'קָמָה', '["qâmâh"]', '["[the] standing grain","[the] standing grain of","standing grain"]', '["n-f"]', 'something that rises, i.e. a stalk of grain (standing) corn, grown up, stalk.', 'feminine of active participle of 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1166I}/H9034/[H1167]', 'inflected', 'heb', 'בָּעַל', '["bâʻal"]', '["and/ he will marry/ her"]', '["v"]', 'to be master; hence, to marry have dominion (over), be husband, marry(-ried, × wife).', 'a primitive root; also as denominative from 1167');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5612A}/[H9]', 'lemma', 'heb', 'סֵפֶר', '["çêpher"]', '["[is] [the] document of","[the] document","[the] document of","a document","a document of","a letter","documents","letters"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3748}/[H3772]', 'lemma', 'heb', 'כְּרִיתוּת', '["kᵉrîythûwth"]', '["[the] divorce of","divorce"]', '["n-f"]', 'a cutting (of the matrimonial bond), i.e. divorce divorce(-ment).', 'from 3772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004B}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004M}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947G}/H9034/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["he has taken/ her","he took/ her","take/ it","you will take/ it"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1167H}/H9024/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["husband/ her"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725J}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["to/ return"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3947I}/H9034/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["to/ take/ her"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947I}\/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["he has taken"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7347>', 'opaque', 'heb', 'רֵחֶה', '["rêcheh"]', '["a hand-mill"]', '["n-m"]', 'a mill-stone mill (stone).', 'from an unused root meaning to pulverize;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7393H}/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["and/ an upper millstone"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2254A}\/[H2254]', 'inflected', 'heb', 'חָבַל', '["châbal"]', '["[is] taking as pledge"]', '["v"]', 'to wind tightly (as a rope), i.e. to bind; specifically, by a pledge; figuratively, to pervert, destroy; also to writhe in pain (especially of parturition) × at all, band, bring forth, (deal) corrupt(-ly), destroy, offend, lay to (take a) pledge, spoil, travail, × very, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6014B}/[H6016]', 'inflected', 'heb', 'עָמַר', '["ʻâmar"]', '["and/ he will treat as a slave"]', '["v"]', 'properly, apparently to heap; figuratively, to chastise (as if piling blows); to gather grain bind sheaves, make merchandise of.', 'a primitive root; specifically (as denominative from 6016)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6213A}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ to/ do","and/ to/ do [it]","and/ to/ make","and/ to/ observe"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4813G}/[H4805]', 'inflected', 'heb', 'מִרְיָם', '["Miryâm"]', '["to/ Miriam"]', '["n-pr-f"]', 'Mirjam, the name of two Israelitesses Miriam.', 'from 4805; rebelliously;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4859}/[H4855]', 'lemma', 'heb', 'מַשָּׁאָה', '["mashshâʼâh"]', '["a loan of","debts"]', '["n-f"]', 'a loan × any(-thing), debt.', 'feminine of 4855;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5670}/[H5670]', 'inflected', 'heb', 'עָבַט', '["ʻâbaṭ"]', '["to/ take as pledge"]', '["v"]', 'to pawn; causatively, to lend (on security); figuratively, to entangle borrow, break (ranks), fetch (a pledge), lend, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5667}/H9023/[H5670]', 'inflected', 'heb', 'עֲבוֹט', '["ʻăbôwṭ"]', '["pledge/ his"]', '["n-m"]', 'a pawn pledge.', 'or עֲבֹט; from 5670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5667}/[H5670]', 'inflected', 'heb', 'עֲבוֹט', '["ʻăbôwṭ"]', '["the/ pledge"]', '["n-m"]', 'a pawn pledge.', 'or עֲבֹט; from 5670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6041}/[H6031]', 'lemma', 'heb', 'עָנִי', '["ʻânîy"]', '["O afflicted [one]","[am] afflicted","[am] poor","[have been] afflicted","[is] poor","[the] afflicted","[the] afflicted [ones] of","[the] afflicted [people] of","[the] poor","[the] poor [people] of","a poor [person]","afflicted","afflicted [people]","an afflicted [person]","poor","poor [people]","poor [person]"]', '["a"]', 'depressed, in mind or circumstances afflicted, humble, lowly, needy, poor.', 'from 6031; (practically the same as 6035, although the margin constantly disputes this, making 6035 subjective and objective);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5667}/H9023/[H5670]', 'inflected', 'heb', 'עֲבוֹט', '["ʻăbôwṭ"]', '["in/ pledge/ his"]', '["n-m"]', 'a pawn pledge.', 'or עֲבֹט; from 5670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8008}/H9023/[H8071]', 'inflected', 'heb', 'שַׂלְמָה', '["salmâh"]', '["in/ garment/ his"]', '["n-f"]', 'a dress clothes, garment, raiment.', 'transp. for 8071;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0034}/[H14]', 'inflected', 'heb', 'אֶבְיוֹן', '["ʼebyôwn"]', '["and/ [the] needy","and/ needy","and/ needy [people]","and/ needy [people] of"]', '["a-m"]', 'destitute beggar, needy, poor (man).', 'from 14, in the sense of want (especially in feeling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1616}/H9021/[H1481]', 'inflected', 'heb', 'גֵּר', '["gêr"]', '["one of/ sojourner[s]/ your"]', '["n-m"]', 'properly, a guest; by implication, a foreigner alien, sojourner, stranger.', 'or (fully) geyr (gare); from 1481;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7939}/H9023/[H7936]', 'inflected', 'heb', 'שָׂכָר', '["sâkâr"]', '["reward/ his","wage[s]/ his"]', '["n-m"]', 'payment of contract; concretely, salary, fare, maintenance; by implication, compensation, benefit hire, price, reward(-ed), wages, worth.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0413}/H9033/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["and/ to/ it"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2399}\/[H2398]', 'inflected', 'heb', 'חֵטְא', '["chêṭᵉʼ"]', '["sin"]', '["n-m"]', 'a crime or its penalty fault, × grievously, offence, (punishment of) sin.', 'from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3947G}/H9033/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["to/ fetch/ it"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3490>', 'inflected', 'heb', 'ליתום', '["la/i.ya.Tom"]', '["to the/ fatherless one"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0490}/[H488]', 'inflected', 'heb', 'אַלְמָנָה', '["ʼalmânâh"]', '["and/ to the/ widow"]', '["n-f"]', 'a widow; also a desolate place desolate house (palace), widow.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2251}/[H2251]', 'lemma', 'heb', 'חָבַט', '["châbaṭ"]', '["[was] beating out","he will beat out","it is beaten out","you will beat"]', '["v"]', 'to knock out or off beat (off, out), thresh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2132H>/H9021', 'opaque', 'heb', 'זַיִת', '["zayith"]', '["olive tree/ your","olive[s]/ your"]', '["n-m"]', 'an olive (as yielding illuminating oil), the tree, the branch or the berry olive (tree, -yard), Olivet.', 'probably from an unused root (akin to 2099);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6286B}/[H6288]', 'lemma', 'heb', 'פָּאַר', '["pâʼar"]', '["you will go over [the] boughs"]', '["v"]', 'to gleam, i.e. (causatively) embellish; figuratively, to boast; also to explain (i.e. make clear) oneself; to shake a tree beautify, boast self, go over the boughs, glorify (self), glory, vaunt self.', 'a primitive root; also denominative from 6288,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8199}/H9038/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["and/ they will judge/ them"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6663}/[H6663]', 'inflected', 'heb', 'צָדַק', '["tsâdaq"]', '["and/ I have been righteous","and/ it will be put right","and/ they will declare righteous","and/ you have made appear righteous"]', '["v"]', 'to be (causatively, make) right (in a moral or forensic sense) cleanse, clear self, (be, do) just(-ice, -ify, -ify self), (be turn to) righteous(-ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7561}/[H7561]', 'inflected', 'heb', 'רָשַׁע', '["râshaʻ"]', '["and/ they had condemned as guilty","and/ they will act wickedly","and/ they will condemn as guilty"]', '["v"]', 'to be (causatively, do or declare) wrong; by implication, to disturb, violate condemn, make trouble, vex, be (commit, deal, depart, do) wicked(-ly, -ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5307G}/H9033/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ he will make lie down/ him"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440H}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ him","to/ face/ its"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7564}/H9023/[H7562]', 'inflected', 'heb', 'רִשְׁעָה', '["rishʻâh"]', '["wickedness/ his"]', '["n-f"]', 'wrong (especially moral) fault, wickedly(-ness).', 'feminine of 7562;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5221}/H9033/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["to/ [the] [one who] strikes/ him","to/ strike/ him"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7034}/[H7034]', 'inflected', 'heb', 'קָלָה', '["qâlâh"]', '["and/ he will be dishonored","and/ it will be lightly esteemed"]', '["v"]', 'to be light (as implied in rapid motion), but figuratively, only (be [causatively, hold] in contempt) base, contemn, despise, lightly esteem, set light, seem vile.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869H}/H9021\/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2629}/[H2629]', 'lemma', 'heb', 'חָסַם', '["châçam"]', '["you will muzzle"]', '["v"]', 'to muzzle; by analogy, to stop the nose muzzle, stop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1758}/H9043\/[H1758]', 'inflected', 'heb', 'דּוּשׁ', '["dûwsh"]', '["when/ threshes/ it"]', '["v"]', 'to trample or thresh break, tear, thresh, tread out (down), at grass (Jeremiah 50:11, by mistake for 1877).', 'or דּוֹשׁ; or דִּישׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2993}/H9024/[H2992]', 'inflected', 'heb', 'יָבָם', '["yâbâm"]', '["husband''s brother/ her"]', '["n-m"]', 'a brother-in-law husband''s brother.', 'from (the orig. of) 2992;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2992}/H9034/[H2993]', 'inflected', 'heb', 'יָבַם', '["yâbam"]', '["and/ he will act as a husband''s brother for/ her"]', '["v"]', 'to marry a (deceased) brother''s widow perform the duty of a husband''s brother, marry.', 'a primitive root of doubtful meaning; used only as a denominative from 2993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2994}/H9023/[H2992]', 'inflected', 'heb', 'יְבֵמֶת', '["Yᵉbêmeth"]', '["brother''s wife/ his"]', '["n-f"]', 'a sister-in-law brother''s wife, sister in law.', 'feminine participle of 2992;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2993}/H9020/[H2992]', 'inflected', 'heb', 'יָבָם', '["yâbâm"]', '["husband''s brother/ my"]', '["n-m"]', 'a brother-in-law husband''s brother.', 'from (the orig. of) 2992;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6965I}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["by/ raising up","to/ confirm","to/ establish","to/ fulfill","to/ impose","to/ raise up","to/ stand"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2992}/H9030/[H2993]', 'inflected', 'heb', 'יָבַם', '["yâbam"]', '["to act as a husband''s brother for/ me"]', '["v"]', 'to marry a (deceased) brother''s widow perform the duty of a husband''s brother, marry.', 'a primitive root of doubtful meaning; used only as a denominative from 2993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5275}/H9023/[H5274]', 'inflected', 'heb', 'נַעַל', '["naʻal"]', '["sandal/ his","sandals/ its"]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3417}/[H3417]', 'inflected', 'heb', 'יָרָק', '["yârâq"]', '["and/ she will spit"]', '["v"]', 'to spit × but, spit.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5275}\/[H5274]', 'inflected', 'heb', 'נַעַל', '["naʻal"]', '["the/ sandal"]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251I}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ brother/ his","and/ brothers/ his","and/ countryman/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5337}/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["to/ be delivered","to/ deliver","to/ deliver himself","to/ rescue"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4016}/H9023/[H954]', 'inflected', 'heb', 'מָבֻשׁ', '["mâbush"]', '["on/ genitals/ his"]', '["n-m"]', '(plural) the (male) pudenda secrets.', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869A}/H9021\/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eye/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3599}/H9021/[H3563]', 'inflected', 'heb', 'כִּיס', '["kîyç"]', '["in/ bag/ your"]', '["n-m"]', 'a cup; also a bag for money or weights bag, cup, purse.', 'a form for 3563;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0068H}/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["and/ a weight"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6996A}\/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["and/ small"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0374}/[H374]', 'inflected', 'heb', 'אֵיפָה', '["ʼêyphâh"]', '["and/ a measure","and/ an ephah","and/ an ephah of"]', '["n-f"]', 'an ephah or measure for grain; hence, a measure in general ephah, (divers) measure(-s).', 'or (shortened) אֵפָה ; of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6996A}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["and/ insignificant [people]","and/ small"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6664G}/[H6663]', 'inflected', 'heb', 'צֶדֶק', '["tsedeq"]', '["and/ righteousness"]', '["n-m"]', 'the right (natural, moral or legal); also (abstractly) equity or (figuratively) prosperity × even, (× that which is altogether) just(-ice), (un-)right(-eous) (cause, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5766A}\/[H5765]', 'inflected', 'heb', 'עֶוֶל', '["ʻevel"]', '["<of> injustice"]', '["n-m"]', '(moral) evil iniquity, perverseness, unjust(-ly), unrighteousness(-ly); wicked(-ness).', 'or עָוֶל; and (feminine) עַוְלָה; or עוֹלָה; or עֹלָה; from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7136A}/H9031/[H7136]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["it met/ you"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2179}/[H2180]', 'inflected', 'heb', 'זָנַב', '["zânab"]', '["and/ it attacked in [the] rear","and/ you will attack in [the] rear"]', '["v"]', 'to curtail, i.e. cut off the rear smite the hindmost.', 'a primitive root meaning to wag; used only as a denominative from 2180;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2826}/[H2826]', 'inflected', 'heb', 'חָשַׁל', '["châshal"]', '["the/ stragglers"]', '["v"]', 'to make (intrans. be) unsteady, i.e. weak feeble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3023}/[H3021]', 'inflected', 'heb', 'יָגֵעַ', '["yâgêaʻ"]', '["and/ weary"]', '["a"]', 'tired; hence (transitive) tiresome full of labour, weary.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5117}/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["when/ gives rest"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7911}\/[H7911]', 'inflected', 'heb', 'שָׁכַח', '["shâkach"]', '["it will be forgotten","you will forget"]', '["v"]', 'to mislay, i.e. to be oblivious of, from want of memory or attention × at all, (cause to) forget.', 'or שָׁכֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2935>', 'inflected', 'heb', 'בטנא', '["va./Te.ne''"]', '["in the/ basket"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2935>', 'inflected', 'heb', 'הטנא', '["ha./Te.ne''"]', '["the/ basket"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0761J}/[H758]', 'lemma', 'heb', 'אֲרַמִּי', '["ʼĂrammîy"]', '["[was] an Aramean"]', '["a"]', 'an Aramite or Aramaean Syrian, Aramitess.', 'patrial from 758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4962}/[H4970]', 'inflected', 'heb', 'מַת', '["math"]', '["<in>/ men of"]', '["n-m"]', 'properly, an adult (as of full length); by implication, a man (only in the plural) few, × friends, men, persons, × small.', 'from the same as 4970;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6031B}/H9035/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ they afflicted/ us"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6040}/H9025/[H6031]', 'inflected', 'heb', 'עֳנִי', '["ʻŏnîy"]', '["affliction/ our"]', '["n-m"]', 'depression, i.e. misery afflicted(-ion), trouble.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5999}/H9025/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["toil/ our"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3906}/H9025/[H3905]', 'inflected', 'heb', 'לַחַץ', '["lachats"]', '["oppression/ our"]', '["n-m"]', 'distress affliction, oppression.', 'from 3905;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0226G}/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["and/ by/ signs"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0935P}/H9035/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ he brought/ us"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1004B}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ to/ household/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6237}/[H6238]', 'inflected', 'heb', 'עָשַׂר', '["ʻâsar"]', '["to/ tithe"]', '["v"]', 'to tithe, i.e. to take or give a tenth × surely, give (take) the tenth, (have, take) tithe(-ing, -s), × truly.', 'a primitive root (identical with 6238); to accumulate; but used only as denominative from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4687}/H9021/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["commandment/ your","commandments/ your"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4687}/H9021/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["any of/ commandments/ your","from/ commandments/ your"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0205H>/H9020', 'inflected', 'heb', 'באני', '["ve./''o.N/i"]', '["in/ mourning/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2931}/[H2930]', 'inflected', 'heb', 'טָמֵא', '["ṭâmêʼ"]', '["<in>/ unclean"]', '["a"]', 'foul in a religious sense defiled, infamous, polluted(-tion), unclean.', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8259}/H9012/[H8259]', 'inflected', 'heb', 'שָׁקַף', '["shâqaph"]', '["look down/ !"]', '["v"]', 'properly, to lean out (of a window), i.e. (by implication) peep or gaze (passively, be a spectacle) appear, look (down, forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4583}/[H5772]', 'inflected', 'heb', 'מָעוֹן', '["mâʻôwn"]', '["from/ [the] dwelling place of","from/ [the] habitation of"]', '["n-m"]', 'an abode, of God (the Tabernacle or the Temple), men (their home) or animals (their lair); hence, a retreat (asylum) den, dwelling((-) place), habitation.', 'or מָעִין; (1 Chronicles 4:41), from the same as 5772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8085H}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ to/ listen"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0559}/H9031/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["he has declared/ you","they speak of/ you"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5414H}/H9031/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ to/ set/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5945A}/[H5927]', 'lemma', 'heb', 'עֶלְיוֹן', '["ʻelyôwn"]', '["[are] most high","most high"]', '["n-m a"]', 'an elevation, i.e. (adj.) lofty (compar.); as title, the Supreme (Most, on) high(-er, -est), upper(-most).', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8416}/[H1984]', 'inflected', 'heb', 'תְּהִלָּה', '["tᵉhillâh"]', '["<into>/ praise","for/ praise"]', '["n-f"]', 'laudation; specifically (concretely) a hymn praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8034}/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["and/ <into>/ a name","and/ for/ a name"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1961}/H9031/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["and/ to/ be/ you"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1696I}\/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["he spoke"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7874}/[H7736]', 'inflected', 'heb', 'שִׂיד', '["sîyd"]', '["and/ you will whitewash"]', '["v"]', 'to plaster plaister.', 'a primitive root probably meaning to boil up (compare 7736); used only as denominative from 7875;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7875}/[H7874]', 'inflected', 'heb', 'שִׂיד', '["sîyd"]', '["with <the>/ lime"]', '["n-m"]', 'lime (as boiling when slacked) lime, plaister.', 'from 7874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5674A}/H9041/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["when/ passing over/ you"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5674A}/H9046/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["when/ have passed over/ you"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3190}\/[H3190]', 'inflected', 'heb', 'יָטַב', '["yâṭab"]', '["doing well"]', '["v"]', 'to be (causative) make well, literally (sound, beautiful) or figuratively (happy, successful, right) be accepted, amend, use aright, benefit, be (make) better, seem best, make cheerful, be comely, be content, diligent(-ly), dress, earnestly, find favour, give, be glad, do (be, make) good(-ness), be (make) merry, please ( well), shew more (kindness), skilfully, × very small, surely, make sweet, thoroughly, tire, trim, very, be (can, deal, entreat, go, have) well (said, seen).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5535}/[H5535]', 'lemma', 'heb', 'סָכַת', '["çâkath"]', '["keep silent"]', '["v"]', 'by implication, to observe quietly take heed.', 'a primitive root to be silent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7311A}\/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["high"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4541A}/[H5258]', 'inflected', 'heb', 'מַסֵּכָה', '["maççêkâh"]', '["and/ a molten image","and/ molten images"]', '["n-f"]', 'properly, a pouring over, i.e. fusion of metal (especially a cast image); by implication, a libation, i.e. league; concretely a coverlet (as if poured out) covering, molten (image), vail.', 'from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0543}\/[H539]', 'inflected', 'heb', 'אָמֵן', '["ʼâmên"]', '["amen"]', '["adv"]', 'sure; abstract, faithfulness; adverb, truly Amen, so be it, truth.', 'from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7034}/[H7034]', 'lemma', 'heb', 'קָלָה', '["qâlâh"]', '["[one who] dishonors","a lightly esteemed [person]"]', '["v"]', 'to be light (as implied in rapid motion), but figuratively, only (be [causatively, hold] in contempt) base, contemn, despise, lightly esteem, set light, seem vile.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414H}/H9031/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I appointed/ you","and/ I made/ you","and/ he will set/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5381}/H9031/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["and/ they will overtake/ you"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2935>/H9021', 'opaque', 'heb', 'טֶנֶא', '["ṭeneʼ"]', '["basket/ your"]', '["n-m"]', 'a basket (of interlaced osiers) basket.', 'from an unused root probably meaning to weave;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4863}/H9021/[H7604]', 'inflected', 'heb', 'מִשְׁאֶרֶת', '["mishʼereth"]', '["and/ kneading trough/ your"]', '["n-f"]', 'a kneading-trough (in which the dough rises) kneading trough, store.', 'from 7604 in the original sense of swelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0935G}/H9041/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ coming/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3318G}/H9041/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["when/ going out/ you"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6965J}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["those/ [who] rose up","who/ are rising up","who/ will arise"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7651}/[H7650]', 'inflected', 'heb', 'שֶׁבַע', '["shebaʻ"]', '["and/ in/ seven"]', '["n"]', 'seven (as the sacred full one); also (adverbially) seven times; by implication, a week; by extension, an indefinite number ( by) seven(-fold),-s, (-teen, -teenth), -th, times). Compare 7658.', 'or (masculine) (שִׁבְעָה); from 7650; a primitive cardinal number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0618>/H9021', 'inflected', 'heb', 'באסמיך', '["ba./''a.sa.Mei./kha"]', '["in/ barns/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965I}/H9031/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["he will establish/ you"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3498}/H9031/[H3498]', 'inflected', 'heb', 'יָתַר', '["yâthar"]', '["and/ he will make abound/ you"]', '["v"]', 'to jut over or exceed; by implication, to excel; (intransitively) to remain or be left; causatively to leave, cause to abound, preserve excel, leave (a remnant), left behind, too much, make plenteous, preserve, (be, let) remain(-der, -ing, -nant), reserve, residue, rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6529}/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["in/ [the] fruit of"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6529}/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["and/ in/ [the] fruit of"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0214}/H9023/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["armory/ his","storehouse/ his"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3867B}/[H3867]', 'inflected', 'heb', 'לָוָה', '["lâvâh"]', '["and/ you will lend to"]', '["v"]', 'properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2180}/[H2179]', 'inflected', 'heb', 'זָנָב', '["zânâb"]', '["into/ [the] tail"]', '["n-m"]', 'the tail (literally or figuratively) tail.', 'from 2179 (in the original sense of flapping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4295}/[H5786]', 'inflected', 'heb', 'מַטָּה', '["maṭṭâh"]', '["<to>/ downwards"]', '["adv"]', 'downward, below or beneath; often adverbially with or without prefixes beneath, down(-ward), less, very low, under(-neath).', 'from 5786 with directive enclitic appended;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5647H}/H9038\/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["to/ serve/ them"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0779}/[H779]', 'inflected', 'heb', 'אָרַר', '["ʼârar"]', '["and/ [be] cursed","and/ [is] cursed","and/ [will be] cursed"]', '["v"]', 'to execrate × bitterly curse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3994}/[H779]', 'inflected', 'heb', 'מְאֵרָה', '["mᵉʼêrâh"]', '["the/ curse"]', '["n-f"]', 'an execration curse.', 'from 779;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4103}/[H1949]', 'inflected', 'heb', 'מְהוּמָה', '["mᵉhûwmâh"]', '["<the>/ confusion","<the>/ turmoil"]', '["n-f"]', 'confusion or uproar destruction, discomfiture, trouble, tumult, vexation, vexed.', 'from 1949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4045}/[H1605]', 'inflected', 'heb', 'מִגְעֶרֶת', '["migʻereth"]', '["<the>/ rebuke"]', '["n-f"]', 'reproof (i.e. curse) rebuke.', 'from 1605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0006}/H9041/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["perishing/ you"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7455}/[H7489]', 'lemma', 'heb', 'רֹעַ', '["rôaʻ"]', '["[the] wickedness of","sadness of"]', '["n-m"]', 'badness (as marring), physically or morally × be so bad, badness, (× be so) evil, naughtiness, sadness, sorrow, wickedness.', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4611}/H9021/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["deeds/ your"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800A}/H9030/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["have you forsaken/ me","he has forsaken/ me","it has abandoned/ me","it has left/ me","they have forsaken/ me","you forsake/ me","you have forsaken/ me"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1698}/[H1696]', 'inflected', 'heb', 'דֶּבֶר', '["deber"]', '["<the>/ pestilence","the/ pestilence"]', '["n-m"]', 'a pestilence murrain, pestilence, plague.', 'from 1696 (in the sense of destroying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615H}/H9043/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["has destroyed/ he"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5221}/H9031/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["[by] striking/ you","he will strike/ you","it will strike/ you","will I strike/ you","will he strike/ you","will people strike down/ you"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7829}/[H7828]', 'inflected', 'heb', 'שַׁחֶפֶת', '["shachepheth"]', '["with <the>/ consumption"]', '["n-f"]', 'emaciation consumption.', 'from the same as 7828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6920}/[H6919]', 'inflected', 'heb', 'קַדַּחַת', '["qaddachath"]', '["and/ with <the>/ fever"]', '["n-f"]', 'inflammation, i.e. febrile disease burning ague, fever.', 'from 6919;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1816}/[H1814]', 'inflected', 'heb', 'דַּלֶּקֶת', '["dalleqeth"]', '["and/ with <the>/ inflammation"]', '["n-f"]', 'a burning fever inflammation.', '; from 1814;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2746}/[H2787]', 'inflected', 'heb', 'חַרְחֻר', '["charchur"]', '["and/ with <the>/ feverish heat"]', '["n-m"]', 'fever (as hot) extreme burning.', 'from 2787;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2719}/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["and/ by the/ sword","and/ by/ sword","and/ with the/ sword"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7711B}/[H7710]', 'inflected', 'heb', 'שְׁדֵפָה', '["shᵉdêphâh"]', '["and/ with <the>/ blight"]', '["n-f n-m"]', 'blight blasted(-ing).', 'or שִׁדָּפוֹן; from 7710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3420}/[H3418]', 'inflected', 'heb', 'יֵרָקוֹן', '["yêrâqôwn"]', '["and/ with <the>/ mildew"]', '["n-m"]', 'paleness, whether of persons (from fright), or of plants (from drought) greenish, yellow.', 'from 3418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7291}/H9031/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["and/ they will pursue/ you"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8064>/H9021', 'opaque', 'heb', 'שָׁמַיִם', '["shâmayim"]', '["heavens/ your"]', '["n-m"]', 'the sky (as aloft; the dual perhaps alluding to the visible arch in which the clouds move, as well as to the higher ether where the celestial bodies revolve) air, × astrologer, heaven(-s).', 'dual of an unused singular שָׁמֶה; from an unused root meaning to be lofty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H0776H>', 'inflected', 'heb', 'והארץ', '["ve./ha./''A.retz"]', '["and/ the/ ground","and/ the/ land"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478G}/H9031/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["[is] under/ you","under/ you"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0080}/[H79]', 'lemma', 'heb', 'אָבָק', '["ʼâbâq"]', '["dust"]', '["n-m"]', 'light particles (as volatile) (small) dust, powder.', 'from root of 79;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414G}/H9031/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["I will give/ you","he gave/ you","he will make/ you","will I give up/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2189}/[H2113]', 'inflected', 'heb', 'זַעֲוָה', '["zaʻăvâh"]', '["<into>/ a terror","into/ a terror","to/ terror"]', '["n-f"]', 'agitation, maltreatment × removed, trouble.', 'by transposition for 2113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5038}/H9021/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["corpse/ your"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H2914>', 'inflected', 'heb', 'ובטחרים', '["u./vo./''o.fa.lim"]', '["and/ with <the>/ tumors"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H1618>', 'inflected', 'heb', 'ובגרב', '["u./va./ga.Rav"]', '["and/ with <the>/ eczema"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H2775B>', 'inflected', 'heb', 'ובחרס', '["u./ve./Cha.res"]', '["and/ with <the>/ scabies"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7495}/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["to/ be healed","to/ be repaired","to/ get himself healed","to/ heal"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7697}/[H7696]', 'inflected', 'heb', 'שִׁגָּעוֹן', '["shiggâʻôwn"]', '["with <the>/ madness","with/ madness"]', '["n-m"]', 'craziness furiously, madness.', 'from 7696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5788A}/[H5787]', 'inflected', 'heb', 'עִוָּרוֹן', '["ʻivvârôwn"]', '["and/ with/ blindness"]', '["n-m"]', 'blindness blind(-ness).', 'and (feminine) עַוֶּרֶת; from 5787;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8541}/[H8539]', 'inflected', 'heb', 'תִּמָּהוֹן', '["timmâhôwn"]', '["and/ with/ bewilderment of"]', '["n-m"]', 'consternation astonishment.', 'from 8539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5787}/[H5786]', 'inflected', 'heb', 'עִוֵּר', '["ʻivvêr"]', '["<the>/ blind [person]","the/ blind [people]"]', '["a"]', 'blind (literally or figuratively) blind (men, people).', 'intensive from 5786;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0653}/[H651]', 'inflected', 'heb', 'אֲפֵלָה', '["ʼăphêlâh"]', '["in <the>/ gloom<s>","in the/ darkness"]', '["n-f"]', 'duskiness, figuratively, misfortune; concrete, concealment dark, darkness, gloominess, × thick.', 'feminine of 651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1497}/[H1497]', 'inflected', 'heb', 'גָּזַל', '["gâzal"]', '["and/ robbed"]', '["v"]', 'to pluck off; specifically to flay, strip or rob catch, consume, exercise (robbery), pluck (off), rob, spoil, take away (by force, violence), tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7901I}/H9034/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["he will lie with/ her"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2873}/[H2873]', 'lemma', 'heb', 'טָבַח', '["ṭâbach"]', '["I have slaughtered","[will be] slaughtered","she has slaughtered","to slaughter","you have slaughtered"]', '["v"]', 'to slaughter (animals or men) kill, (make) slaughter, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2543}/H9021/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["donkey/ your"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H6440H}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ to/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0341}/H9021/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["to/ enemies/ your"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5869A}/H9021/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3616}/[H3615]', 'inflected', 'heb', 'כָּלֶה', '["kâleh"]', '["and/ longing"]', '["a"]', 'pining fail.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3018}/H9021/[H3021]', 'inflected', 'heb', 'יְגִיעַ', '["yᵉgîyaʻ"]', '["[the] result of toil/ your","toil/ your"]', '["n-m"]', 'toil; hence, a work, produce, property (as the result of labor) labour, work.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7533}/[H7533]', 'inflected', 'heb', 'רָצַץ', '["râtsats"]', '["and/ crushed","so/ it may be crushed"]', '["v"]', 'to crack in pieces, literally or figuratively break, bruise, crush, discourage, oppress, struggle together.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7696}/[H7696]', 'lemma', 'heb', 'שָׁגַע', '["shâgaʻ"]', '["[is] mad","[who] is mad","behaving like a madman","driven mad","madmen"]', '["v"]', 'to rave through insanity (be, play the) mad (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4758}/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["[was] from/ [the] appearance of","from/ [the] appearance of","from/ [the] sight[s] of"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1290}/[H1288]', 'inflected', 'heb', 'בֶּרֶךְ', '["berek"]', '["the/ knees"]', '["n-f"]', 'a knee knee.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7785}/[H7783]', 'inflected', 'heb', 'שׁוֹק', '["shôwq"]', '["the/ legs","the/ thigh"]', '["n-f"]', 'the (lower) leg (as a runner) hip, leg, shoulder, thigh.', 'from 7783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3709H}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["from/ [the] sole of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6936}/H9021/[H6915]', 'inflected', 'heb', 'קׇדְקֹד', '["qodqôd"]', '["scalp/ your"]', '["n-m"]', 'the crown of the head (as the part most bowed) crown (of the head), pate, scalp, top of the head.', 'from 6915;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428G}/H9021/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["[is] king/ your","king/ your"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8047H}/[H8074]', 'inflected', 'heb', 'שַׁמָּה', '["shammâh"]', '["<into>/ a horror","<into>/ a waste","into/ a horror","into/ a waste"]', '["n-f"]', 'ruin; by implication, consternation astonishment, desolate(-ion), waste, wonderful thing.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4912}/[H4910]', 'inflected', 'heb', 'מָשָׁל', '["mâshâl"]', '["<into>/ a byword","<into>/ a proverb","into/ a byword","to/ a proverb"]', '["n-m"]', 'properly, a pithy maxim, usually of metaphorical nature; hence, a simile (as an adage, poem, discourse) byword, like, parable, proverb.', 'apparently from 4910 in some original sense of superiority in mental action;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8148}/[H8150]', 'inflected', 'heb', 'שְׁנִינָה', '["shᵉnîynâh"]', '["and/ <into>/ a taunt","and/ into/ a taunt"]', '["n-f"]', 'something pointed, i.e. a gibe byword, taunt.', 'from 8150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5090A}/H9031/[H5090]', 'inflected', 'heb', 'נָהַג', '["nâhag"]', '["I will lead/ you","he will drive away/ you"]', '["v"]', 'to drive forth (a person, an animal or chariot), i.e. lead, carry away; reflexively, to proceed (i.e. impel or guide oneself); also (from the panting induced by effort), to sigh acquaint, bring (away), carry away, drive (away), lead (away, forth), (be) guide, lead (away, forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2628}/H9033/[H2628]', 'inflected', 'heb', 'חָסַל', '["châçal"]', '["it will consume/ it"]', '["v"]', 'to eat off consume.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5647I}/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ you will be tilled","and/ you will labor","and/ you will work"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0103}/[H103]', 'lemma', 'heb', 'אָגַר', '["ʼâgar"]', '["[one who] gathers","it gathers","you will gather"]', '["v"]', 'to harvest gather.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8438A}/[H3216]', 'inflected', 'heb', 'תּוֹלָע', '["tôwlâʻ"]', '["the/ worm[s]"]', '["n-m n-f"]', 'a maggot (as voracious); specifically (often with ellipsis of 8144) the crimson-grub, but used only (in this connection) of the color from it, and cloths dyed therewith crimson, scarlet, worm.', 'and (feminine) תּוֹלֵעָה; or תּוֹלַעַת; or תֹּלַעַת; from 3216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5480}/[H5480]', 'lemma', 'heb', 'סוּךְ', '["çûwk"]', '["I anointed myself","you anoint yourself","you will anoint yourself"]', '["v"]', 'properly, to smear over (with oil), i.e. anoint anoint (self), × at all.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7628A}/[H7618]', 'inflected', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["[are] in <the>/ captivity","by <the>/ captivity","by/ captivity","in <the>/ captivity"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6086H}/H9021/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["tree/ your"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6767C}/[H6750]', 'inflected', 'heb', 'צְלָצַל', '["tsᵉlâtsal"]', '["the/ locust[s]"]', '["n-m"]', 'a clatter, i.e. (abstractly) whirring (of wings); (concretely) a cricket; also a harpoon (as rattling),a cymbal (as clanging) cymbal, locust, shadowing, spear.', 'from 6750 reduplicated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4605}/H9011/[H5927]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["up/ -wards"]', '["adv"]', 'properly,the upper part, used only adverbially with prefix upward, above, overhead, from the top, etc. above, exceeding(-ly), forward, on (× very) high, over, up(-on, -ward), very.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4295}/[H5786]', 'lemma', 'heb', 'מַטָּה', '["maṭṭâh"]', '["beneath","downwards"]', '["adv"]', 'downward, below or beneath; often adverbially with or without prefixes beneath, down(-ward), less, very low, under(-neath).', 'from 5786 with directive enclitic appended;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3867B}/H9031/[H3867]', 'inflected', 'heb', 'לָוָה', '["lâvâh"]', '["he will lend to/ you"]', '["v"]', 'properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3867B}/H9033/[H3867]', 'inflected', 'heb', 'לָוָה', '["lâvâh"]', '["you will lend to/ him"]', '["v"]', 'properly, to twine, i.e. (by implication) to unite, to remain; also to borrow (as a form of obligation) or (caus.) to lend abide with, borrow(-er), cleave, join (self), lend(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0226G}/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["<into>/ a sign","for/ signs"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4159}/[H3302]', 'inflected', 'heb', 'מוֹפֵת', '["môwphêth"]', '["and/ <into>/ a wonder","and/ for/ portents"]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2898}/[H2895]', 'inflected', 'heb', 'טוּב', '["ṭûwb"]', '["and/ with/ goodness of"]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6772}/[H6770]', 'inflected', 'heb', 'צָמָא', '["tsâmâʼ"]', '["and/ by/ thirst","and/ in/ thirst"]', '["n-m"]', 'thirst (literally or figuratively) thirst(-y).', 'from 6770;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5903}/[H6191]', 'inflected', 'heb', 'עֵירֹם', '["ʻêyrôm"]', '["and/ in/ nakedness"]', '["a"]', 'nudity naked(-ness).', 'or עֵרֹם; from 6191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2640}/[H2637]', 'inflected', 'heb', 'חֹסֶר', '["chôçer"]', '["and/ in/ lack of"]', '["n-m"]', 'poverty in want of.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8045}/H9043/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["has destroyed/ he"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1675}/[H1675]', 'lemma', 'heb', 'דָּאָה', '["dâʼâh"]', '["it swoops down","someone will swoop down"]', '["v"]', 'to dart, i.e. fly rapidly fly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956H}/H9023/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["language/ its"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2205H}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["for/ an old [person]"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5288}/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["and/ a child","and/ a lad","and/ a youth","and/ lads","and/ young man","and/ young men"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3323}/[H6671]', 'inflected', 'heb', 'יִצְהָר', '["yitshâr"]', '["and/ fresh oil"]', '["n-m"]', 'oil (as producing light); figuratively, anointing anointed oil.', 'from 6671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0006}/H9043/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["destroys/ it"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6887B}/[H6887]', 'inflected', 'heb', 'צָרַר', '["tsârar"]', '["and/ I will cause distress","and/ he harassed","and/ it will lay siege"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2346G>/H9021', 'opaque', 'heb', 'חוֹמָה', '["chôwmâh"]', '["walls/ your"]', '["n-f"]', 'a wall of protection wall, walled.', 'feminine active participle of an unused root apparently meaning to join;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1219}/[H1210]', 'inflected', 'heb', 'בָּצַר', '["bâtsar"]', '["and/ <the>/ fortified"]', '["v"]', 'to gather grapes; also to be isolated (i.e. inaccessible by height or fortification) cut off, (de-) fenced, fortify, (grape) gather(-er), mighty things, restrain, strong, wall (up), withhold.', 'a primitive root; to clip off; specifically (as denominative from 1210)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0982}/[H982]', 'lemma', 'heb', 'בָּטַח', '["bâṭach"]', '["I have trusted","I rely","I trust","I trusted","I will trust","O confident [women]","[are] falling to [the] ground","[are] relying","[are] trusting","[he is] trusting","[is] secure","[is] trusting","[one who] trusts","[they are] trusting","[who] trusts","[whom] I trust","[will be] trusting","confident","do you rely","he had been confident","he is confident","he make trust","he relies","he trusted","he trusts","it has trusted","it is confident","it trusts","let him trust","relying","secure","they trusted","trust","trusting","we trust","you have made rely","you have trusted","you rely","you trust","you trusted"]', '["v"]', 'properly, to hie for refuge (but not so precipitately as 2620); figuratively, to trust, be confident or sure be bold (confident, secure, sure), careless (one, woman), put confidence, (make to) hope, (put, make to) trust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4689}/[H6693]', 'inflected', 'heb', 'מָצוֹק', '["mâtsôwq"]', '["and/ in/ [the] distress"]', '["n-m"]', 'a narrow place, i.e. (abstractly and figuratively) confinement or disability anguish, distress, straitness.', 'from 6693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6693}/[H6693]', 'lemma', 'heb', 'צוּק', '["tsûwq"]', '["he will bring distress","she pressed","they will press"]', '["v"]', 'to compress, i.e. (figuratively) oppress, distress constrain, distress, lie sore, (op-) press(-or), straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7390}/[H7401]', 'inflected', 'heb', 'רַךְ', '["rak"]', '["<the>/ gentle","the/ gentle [woman]"]', '["a"]', 'tender (literally or figuratively); by implication, weak faint((-hearted), soft, tender ((-hearted), one), weak.', 'from 7401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6028}/[H6026]', 'inflected', 'heb', 'עָנֹג', '["ʻânôg"]', '["and/ <the>/ delicate","and/ the/ delicate [woman]"]', '["a"]', 'luxurious delicate.', 'from 6026;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0802H}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ for/ a wife","and/ on/ [the] wife of","and/ with/ [the] wife of"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2436G>/H9023', 'opaque', 'heb', 'חֵיק', '["chêyq"]', '["bosom/ his"]', '["n-m"]', 'the bosom (literally or figuratively) bosom, bottom, lap, midst, within.', 'or חֵק; and חוֹק; from an unused root, apparently meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3499A}/[H3498]', 'inflected', 'heb', 'יֶתֶר', '["yether"]', '["and/ on/ [the] remainder of"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5414G}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["from/ giving","more than/ giving"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5254H}/[H5254]', 'lemma', 'heb', 'נָסָה', '["nâçâh"]', '["she has attempted"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6026}/[H6026]', 'inflected', 'heb', 'עָנַג', '["ʻânag"]', '["because /was delicate"]', '["v"]', 'to be soft or pliable, i.e. (figuratively) effeminate or luxurious delicate(-ness), (have) delight (self), sport self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7391}/[H7401]', 'inflected', 'heb', 'רֹךְ', '["rôk"]', '["and/ from/ gentleness"]', '["n-m"]', 'softness (figuratively) tenderness.', 'from 7401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0376H>', 'inflected', 'heb', 'באיש', '["be./''Ish"]', '["on/ [the] husband of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2436G>/H9024', 'opaque', 'heb', 'חֵיק', '["chêyq"]', '["bosom/ her"]', '["n-m"]', 'the bosom (literally or figuratively) bosom, bottom, lap, midst, within.', 'or חֵק; and חוֹק; from an unused root, apparently meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1121A}/H9024/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ on/ children/ her","and/ on/ son/ her"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1323G}/H9024/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ on/ daughter/ her"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7988}/H9024/[H7953]', 'inflected', 'heb', 'שִׁלְיָה', '["shilyâh"]', '["and/ on/ afterbirth/ her"]', '["n-f"]', 'a fetus or babe (as extruded in birth) young one.', 'feminine from 7953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2640}/[H2637]', 'inflected', 'heb', 'חֹסֶר', '["chôçer"]', '["in/ lack of"]', '["n-m"]', 'poverty in want of.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3789}/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["<the>/ [one] recorded","<the>/ [thing] written","that/ is written","which/ are written","which/ was written","which/ were written","who/ were written","who/ wrote"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3372G}/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["to/ be afraid","to/ fear"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3513G}/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["<the>/ glorious"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6381}/[H6381]', 'inflected', 'heb', 'פָּלָא', '["pâlâʼ"]', '["and/ he will make extraordinary","and/ it was difficult"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4347}/H9021/[H5221]', 'inflected', 'heb', 'מַכָּה', '["makkâh"]', '["plagues/ your"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2483}/[H2470]', 'inflected', 'heb', 'חֳלִי', '["chŏlîy"]', '["and/ [is] an affliction","and/ sicknesses"]', '["n-m"]', 'malady, anxiety, calamity disease, grief, (is) sick(-ness).', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927H}/H9038/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["he will bring up/ them","she had taken up/ them"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7797}/[H7797]', 'lemma', 'heb', 'שׂוּשׂ', '["sûws"]', '["I exult","I will rejoice","[am] rejoicing","[one who] rejoices","certainly <to rejoice>","exult","he rejoiced","he will rejoice","it rejoices","it will exult","may they exult","rejoice","they exult","they rejoiced","we will rejoice"]', '["v"]', 'to be bright, i.e. cheerful be glad, × greatly, joy, make mirth, rejoice.', 'or שִׂישׂ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7235A}/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["and/ to/ increase"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0006}/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["to/ [one who] is perishing","to/ count as lost","to/ destroy"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8045}/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["and/ to/ destroy","and/ to/ destroy [it]","and/ to/ destroy [them]"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5255}/[H5255]', 'inflected', 'heb', 'נָסַח', '["nâçach"]', '["and/ you will be torn away"]', '["v"]', 'to tear away destroy, pluck, root.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6327A}/H9031/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["and/ he will scatter/ you"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7280B}/[H7280]', 'lemma', 'heb', 'רָגַע', '["râgaʻ"]', '["I will make suddenly","it will rest","rest","to give rest to","you will rest"]', '["v"]', 'properly, to toss violently and suddenly (the sea with waves, the skin with boils); figuratively (in a favorable manner) to settle, i.e. quiet; specifically, to wink (from the motion of the eye-lids) break, divide, find ease, be a moment, (cause, give, make to) rest, make suddenly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7268}/[H7264]', 'lemma', 'heb', 'רַגָּז', '["raggâz"]', '["trembling"]', '["a"]', 'timid trembling.', 'intensive from 7264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3631}/[H3615]', 'inflected', 'heb', 'כִּלָּיוֹן', '["killâyôwn"]', '["and/ failing of"]', '["n-m"]', 'pining, destruction consumption, failing.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1671}/[H1669]', 'inflected', 'heb', 'דְּאָבוֹן', '["dᵉʼâbôwn"]', '["and/ despair of"]', '["n-m"]', 'pining sorrow.', 'from 1669;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8511}/[H8511]', 'lemma', 'heb', 'תָּלָא', '["tâlâʼ"]', '["[is] hung up","hung up"]', '["v"]', 'to suspend; figuratively (through hesitation) to be uncertain; by implication (of mental dependence) to habituate be bent, hang (in doubt).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6342}/[H6342]', 'inflected', 'heb', 'פָּחַד', '["pâchad"]', '["and/ it will be in awe","and/ it will be in dread","and/ they will be in awe","and/ they will be in dread","and/ you have been in dread","and/ you will be in dread"]', '["v"]', 'to be startled (by a sudden alarm); hence, to fear in general be afraid, stand in awe, (be in) fear, make to shake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3119}/[H3117]', 'inflected', 'heb', 'יוֹמָם', '["yôwmâm"]', '["and/ by day"]', '["adv"]', 'daily daily, (by, in the) day(-time).', 'from 3117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2416E}/H9021/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["in/ life/ your"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6343}/[H6342]', 'inflected', 'heb', 'פַּחַד', '["pachad"]', '["from/ [the] dread of","from/ dread","from/ dread of","from/ fear","from/ terror"]', '["n-m"]', 'a (sudden) alarm (properly, the object feared, by implication, the feeling) dread(-ful), fear, (thing) great (fear, -ly feared), terror.', 'from 6342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6342}/[H6342]', 'lemma', 'heb', 'פָּחַד', '["pâchad"]', '["I feared","I will be in dread","[who] fears","he will be in dread","it caused to tremble","it is in dread","let them be in dread","they are in dread","they fear","they feared","they were afraid","they were in dread","they will be in dread","will I be in dread","you be in dread","you will dread","you will fear"]', '["v"]', 'to be startled (by a sudden alarm); hence, to fear in general be afraid, stand in awe, (be in) fear, make to shake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4758}/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["and/ from/ [the] appearance of","and/ from/ [the] sight[s] of"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0591}/[H590]', 'inflected', 'heb', 'אֳנִיָּה', '["ʼŏnîyâh"]', '["[were] in the/ ship","in/ [the] ships","in/ ships"]', '["n-f"]', 'a ship ship(-men).', 'feminine of 590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7200G}/H9034/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["to/ see/ it"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H8198>', 'inflected', 'heb', 'ולשפחות', '["ve./li/sh.fa.Chot"]', '["and/ to/ female servants","and/ to/ female slaves"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7069}\/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["[will be] a buyer"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3772H}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["to/ make"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2722}\/[H2717]', 'inflected', 'heb', 'חֹרֵב', '["Chôrêb"]', '["at/ Horeb"]', '["n-pr-loc"]', 'Choreb, a (generic) name for the Sinaitic mountains Horeb.', 'from 2717; desolate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0241G}/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["and/ [the] ear of","and/ [the] ears of","and/ ears"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1980J}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ I led","and/ I will lead","and/ he brought","and/ he has made walk","and/ he led","and/ they brought"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8008}/H9026/[H8071]', 'inflected', 'heb', 'שַׂלְמָה', '["salmâh"]', '["clothes/ your"]', '["n-f"]', 'a dress clothes, garment, raiment.', 'transp. for 8071;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5921A}/H9036/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["from/ on <the>/ you","from/ with <the>/ you"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5275}/H9021/[H5274]', 'inflected', 'heb', 'נַעַל', '["naʻal"]', '["and/ sandal/ your","and/ sandal[s]/ your","and/ sandals/ your"]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5747}/[H5746]', 'inflected', 'heb', 'עוֹג', '["ʻÔwg"]', '["and/ Og"]', '["n-pr-m"]', 'Og, a king of Bashan Og.', 'probably from 5746; round;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4520}/[H4519]', 'inflected', 'heb', 'מְנַשִּׁי', '["Mᵉnashshîy"]', '["the/ Manassite[s]"]', '["a"]', 'a Menashshite or descendant of Menashsheh of Manasseh, Manassites.', 'from 4519;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7919A}/[H7919]', 'lemma', 'heb', 'שָׂכַל', '["sâkal"]', '["I have insight","I will give attention","[is one who] considers","[is] acting prudently","[is] giving attention","[one who] acts prudently","[one who] gives attention","[was] successful","[who] acts prudently","a wise [person]","act prudently","he has insight","he made clear","he prospered","he prospers","he was successful","he will prosper","insight","it gives insight to","prudent","skillful","successful","they considered","they have prospered","they will comprehend","they will consider","they will succeed","will you have insight","you may cause to prosper","you may prosper","you will be successful"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213A}/H9013\/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["you will do/ !"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218H>/H9026', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["chiefs/ your"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2205G}/H9026/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["elders/ your"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7860>/H9026', 'inflected', 'heb', 'ושטריכם', '["ve./Sho.te.rei./Khem","ve./sho.te.rei./Khem"]', '["and/ officials/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2404}/[H2404]', 'inflected', 'heb', 'חָטַב', '["châṭab"]', '["from/ [the] cutter of"]', '["v"]', 'to chop or carve wood cut down, hew(-er), polish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6086G}/H9021/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["wood<s>/ your"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5674A}/H9031/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["to/ pass on/ you"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1285}/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["in <the>/ covenant","in the/ covenant","in/ [the] covenant of","in/ a covenant","with the/ covenant"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0423}/H9023/[H422]', 'inflected', 'heb', 'אָלָה', '["ʼâlâh"]', '["and/ in/ oath/ his"]', '["n-f"]', 'an imprecation curse, cursing, execration, oath, swearing.', 'from 422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0905H}/H9036/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["to/ alone/ you"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3426>/H9043', 'opaque', 'heb', 'יֵשׁ', '["yêsh"]', '["is/ it","there/ he","there/ it"]', '["prt"]', 'there is or are (or any other form of the verb to be, as may suit the connection) (there) are, (he, it, shall, there, there may, there shall, there should) be, thou do, had, hast, (which) hath, (I, shalt, that) have, (he, it, there) is, substance, it (there) was, (there) were, ye will, thou wilt, wouldest.', 'perhaps from an unused root meaning to stand out, or exist; entity; used adverbially or as a copula for the substantive verb (1961);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8251}/H9028/[H8262]', 'inflected', 'heb', 'שִׁקּוּץ', '["shiqqûwts"]', '["detestable things/ their"]', '["n-m"]', 'disgusting, i.e. filthy; especially idolatrous or (concretely) an idol abominable filth (idol, -ation), detestable (thing).', 'or שִׁקֻּץ; from 8262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1544}/H9028/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["idols/ their"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8328}/[H8327]', 'lemma', 'heb', 'שֶׁרֶשׁ', '["sheresh"]', '["[the] root of","[the] roots of","a root","root"]', '["n-m"]', 'a root (literally or figuratively) bottom, deep, heel, root.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7219}/[H7218]', 'lemma', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["[the] poison of","poison"]', '["n-m"]', 'a poisonous plant, probably the poppy (from its conspicuous head); generally poison (even of serpents) gall, hemlock, poison, venom.', 'or רוֹשׁ; (Deuteronomy 32:32), apparently the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3939>', 'inflected', 'heb', 'ולענה', '["ve./la.''a.Nah"]', '["and/ wormwood"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3824}/H9023/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["[is] in/ heart/ his","in/ heart/ his"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8307}/[H8324]', 'inflected', 'heb', 'שְׁרִירוּת', '["shᵉrîyrûwth"]', '["in/ [the] stubbornness of"]', '["n-f"]', 'obstinacy imagination, lust.', 'from 8324 in the sense of twisted, i.e. firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7302}/[H7301]', 'inflected', 'heb', 'רָוֶה', '["râveh"]', '["the/ watered [ground]"]', '["a"]', 'sated (with drink) drunkenness, watered.', 'from 7301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6771}/[H6770]', 'inflected', 'heb', 'צָמֵא', '["tsâmêʼ"]', '["the/ thirsty [ground]","the/ thirsty [person]"]', '["a"]', 'thirsty (literally or figuratively) (that) thirst(-eth, -y).', 'from 6770;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7068}/H9023/[H7065]', 'inflected', 'heb', 'קִנְאָה', '["qinʼâh"]', '["and/ jealousy/ his"]', '["n-f"]', 'jealousy or envy envy(-ied), jealousy, × sake, zeal.', 'from 7065;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0914}/H9033/[H914]', 'inflected', 'heb', 'בָּדַל', '["bâdal"]', '["and/ he will separate/ him"]', '["v"]', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0310A}/H9036/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["from/ after/ you"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5237}/[H5235]', 'inflected', 'heb', 'נׇכְרִי', '["nokrîy"]', '["and/ the/ foreigner"]', '["a"]', 'strange, in a variety of degrees and applications (foreign, non-relative, adulterous, different, wonderful) alien, foreigner, outlandish, strange(-r, woman).', 'from 5235 (second form);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8463}/H9024/[H2456]', 'inflected', 'heb', 'תַּחֲלוּא', '["tachălûwʼ"]', '["diseases/ its"]', '["n-m"]', 'a malady disease, × grievous, (that are) sick(-ness).', 'or תַּחֲלֻא; from 2456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4417M}/[H4414]', 'inflected', 'heb', 'מֶלַח', '["melach"]', '["and/ salt"]', '["n-m"]', 'properly, powder, i.e. (specifically) salt (as easily pulverized and dissolved) salt(-pit).', 'from 4414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776G>/H9024', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["land/ its"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4114}/[H2015]', 'inflected', 'heb', 'מַהְפֵּכָה', '["mahpêkâh"]', '["[is] like/ [the] overthrow of","like/ [the] overthrow of"]', '["n-f"]', 'a destruction when...overthrew, overthrow(-n).', 'from 2015;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0639G}/H9023/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["[is] in/ anger/ his","in/ anger/ his"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2534}/H9023/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["and/ in/ rage/ his"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2750}/[H2734]', 'lemma', 'heb', 'חֳרִי', '["chŏrîy"]', '["[is] [the] heat of"]', '["n-m"]', 'a burning (i.e. intense) anger fierce, × great, heat.', 'from 2734;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5428}/H9038/[H5428]', 'inflected', 'heb', 'נָתַשׁ', '["nâthash"]', '["and/ I will pluck up/ them","and/ he plucked up/ them"]', '["v"]', 'to tear away destroy, forsake, pluck (out, up, by the roots), pull up, root out (up), × utterly. s', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0639G}/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["in <the>/ anger","in/ anger","in/ anger<s>","with <the>/ anger"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2534}/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["and/ in/ rage","and/ with/ rage"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7110A}/[H7107]', 'inflected', 'heb', 'קֶצֶף', '["qetseph"]', '["and/ in/ wrath"]', '["n-m"]', 'a splinter (as chipped off); figuratively, rage or strife foam, indignation, × sore, wrath.', 'from 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5641}/[H5641]', 'inflected', 'heb', 'סָתַר', '["çâthar"]', '["the/ hidden [things]","who/ is hiding"]', '["v"]', 'to hide (by covering), literally or figuratively be absent, keep close, conceal, hide (self), (keep) secret, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1540H}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["and/ the/ revealed [things]"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2063}\/[H2088]', 'inflected', 'heb', 'זֹאת', '["zôʼth"]', '["<the>/ this"]', '["d"]', 'this (often used adverb) hereby (-in, -with), it, likewise, the one (other, same), she, so (much), such (deed), that, therefore, these, this (thing), thus.', 'irregular feminine of 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5080}/H9031/[H5080]', 'inflected', 'heb', 'נָדַח', '["nâdach"]', '["I have driven away/ you","banished [one]/ your","he has banished/ you"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7622}/H9021/[H7617]', 'inflected', 'heb', 'שְׁבוּת', '["shᵉbûwth"]', '["captivity/ your"]', '["n-f"]', 'exile, concretely, prisoners; figuratively, a former state of prosperity captive(-ity).', 'or שְׁבִית; from 7617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6908}/H9031/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["and/ he will gather/ you"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6327A}/H9031/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["I have scattered/ you","he has scattered/ you"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6908}/H9031/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["I will gather/ you","he will gather/ you"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3190}/H9031/[H3190]', 'inflected', 'heb', 'יָטַב', '["yâṭab"]', '["and/ he will do good to/ you"]', '["v"]', 'to be (causative) make well, literally (sound, beautiful) or figuratively (happy, successful, right) be accepted, amend, use aright, benefit, be (make) better, seem best, make cheerful, be comely, be content, diligent(-ly), dress, earnestly, find favour, give, be glad, do (be, make) good(-ness), be (make) merry, please ( well), shew more (kindness), skilfully, × very small, surely, make sweet, thoroughly, tire, trim, very, be (can, deal, entreat, go, have) well (said, seen).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0001G}/H9021/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["more than/ ancestors/ your","more than/ father/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7291}/H9031/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["[will be] pursuing/ you","it will pursue/ you","they have persecuted/ you"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7797}/[H7797]', 'inflected', 'heb', 'שׂוּשׂ', '["sûws"]', '["to/ rejoice"]', '["v"]', 'to be bright, i.e. cheerful be glad, × greatly, joy, make mirth, rejoice.', 'or שִׂישׂ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315G}/H9021\/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["being/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3947J}/H9034/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["so/ he may fetch/ it"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8085G}/H9035/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["so/ he may make hear/ us"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6213A}/H9034/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["so/ we may do/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3220G>', 'inflected', 'heb', 'לים', '["la/i.Yam","le./yam"]', '["<to> the/ sea","for the/ sea","of the/ sea","to/ [the] sea of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3824}/H9021/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["and/ in/ heart/ your"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6213A}/H9033\/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["to/ do/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4194}/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["and/ <the>/ death"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2416E}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["<in> <the>/ life","[is] in <the>/ life","[is] in the/ life","in <the>/ life"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8085H}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["by/ listening","by/ obeying","to/ listen","to/ obey"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0753}/[H748]', 'inflected', 'heb', 'אֹרֶךְ', '["ʼôrek"]', '["and/ [is with] length of","and/ [the] length","and/ [the] length of","and/ length"]', '["n-m"]', 'length forever, length, long.', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ to the/ [one who] came","and/ to the/ [one who] came in","and/ to/ come","and/ to/ go"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5747}/[H5746]', 'inflected', 'heb', 'עוֹג', '["ʻÔwg"]', '["and/ to/ Og"]', '["n-pr-m"]', 'Og, a king of Bashan Og.', 'probably from 5746; round;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0776G>/H9028', 'inflected', 'heb', 'ולארצם', '["u./le./''ar.Tza/m"]', '["and/ to/ land/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0553}/[H553]', 'inflected', 'heb', 'אָמַץ', '["ʼâmats"]', '["and/ be bold","and/ be brave","and/ be courageous","so/ may it show strength"]', '["v"]', 'to be alert, physically (on foot) or mentally (in courage) confirm, be courageous (of good courage, stedfastly minded, strong, stronger), establish, fortify, harden, increase, prevail, strengthen (self), make strong (obstinate, speed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800A}/H9031\/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["he will forsake/ you"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3091G}/[H3068]', 'inflected', 'heb', 'יְהוֹשׁוּעַ', '["Yᵉhôwshûwaʻ"]', '["<to>/ Joshua","to/ Joshua"]', '["n-pr-m"]', 'Jehoshua (i.e. Joshua), the Jewish leader Jehoshua, Jehoshuah, Joshua. Compare 1954, 3442.', 'or יְהוֹשֻׁעַ; from 3068 and 3467; Jehovah-saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4150G}/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["at/ [the] appointed time of"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121J}/[H7122]', 'lemma', 'heb', 'קָרָא', '["qârâʼ"]', '["[one who] reads","he has read","he proclaimed","he read aloud","it was read aloud","people have read aloud","read aloud","you have read aloud","you will read aloud"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241H}/H9028/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["in/ ears/ their"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6680}/H9033/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["so/ I may commission/ him"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5800A}/H9030/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["and/ he abandoned/ me","and/ it will forsake/ me","and/ they have forsaken/ me"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5800A}/H9038/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["and/ I will forsake/ them","and/ you abandoned/ them"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6869B}/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["and/ trouble","and/ troubles"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130G}/H9020/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["<in>/ within/ me","[is] in/ midst/ my","in/ inner being/ my","in/ midst/ my"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3925G}/H9034/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["and/ teach/ it"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760H}/H9034/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["put/ it"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6310G}/H9028/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["<in>/ mouth/ their","[was] in/ mouth/ their","in/ mouth/ their","with/ mouth/ their"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5006}/H9030/[H5006]', 'inflected', 'heb', 'נָאַץ', '["nâʼats"]', '["and/ they will spurn/ me"]', '["v"]', 'to scorn; or (in Ecclesiastes 12:5), by interchange for 5132, to bloom abhor, (give occasion to) blaspheme, contemn, despise, flourish, × great, provoke.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310G}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["from/ [the] mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3336}/H9023/[H3335]', 'inflected', 'heb', 'יֵצֶר', '["yêtser"]', '["form/ his","intention/ its"]', '["n-m"]', 'a form; figuratively, conception (i.e. purpose) frame, thing framed, imagination, mind, work.', 'from 3335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3925G}/H9034/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["and/ he taught/ it"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3789}/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["for/ him","to/ describe in writing","to/ write down"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6654>', 'inflected', 'heb', 'מצד', '["mi./Tzad"]', '["[is] from/ [the] side of","[were] from/ [the] side of","from/ [the] side of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4805H}/H9021/[H4784]', 'inflected', 'heb', 'מְרִי', '["mᵉrîy"]', '["rebellion/ your"]', '["n-m"]', 'bitterness, i.e. (figuratively) rebellion; concretely, bitter, or rebellious bitter, (most) rebel(-lion, -lious).', 'from 4784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6203}/H9021/[H6202]', 'inflected', 'heb', 'עֹרֶף', '["ʻôreph"]', '["neck/ your"]', '["n-m"]', 'the nape or back of the neck (as declining); hence, the back generally (whether literal or figurative) back ((stiff-) neck((-ed).', 'from 6202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5750}/H9040/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["when/ still/ I"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5749B}/[H5749]', 'inflected', 'heb', 'עוּד', '["ʻûwd"]', '["and/ I will call as witness","and/ I will warn","and/ cause to witness [it]","and/ warn","and/ warning","and/ will I warn?","so/ I may call as witnesses","so/ let me warn"]', '["v"]', 'to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4639G}/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["by/ [the] work of","in/ [the] works of","on/ [the] work of","over/ [the] works of"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8552}/H9048\/[H8552]', 'inflected', 'heb', 'תָּמַם', '["tâmam"]', '["were complete/ they"]', '["v"]', 'to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6201}/[H6201]', 'lemma', 'heb', 'עָרַף', '["ʻâraph"]', '["may it drop","they drop"]', '["v"]', 'to droop; hence, to drip drop (down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4306}/[H4305]', 'inflected', 'heb', 'מָטַר', '["mâṭar"]', '["like the/ rain","like/ rain"]', '["n-m"]', 'rain rain.', 'from 4305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3948}/H9020/[H3947]', 'inflected', 'heb', 'לֶקַח', '["leqach"]', '["teaching/ my"]', '["n-m"]', 'properly, something received, i.e. (mentally) instruction (whether on the part of the teacher or hearer); also (in an active and sinister sense) inveiglement doctrine, learning, fair speech.', 'from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2919}/[H2926]', 'inflected', 'heb', 'טַל', '["ṭal"]', '["like the/ dew","like/ [the] dew of","like/ dew"]', '["n-m"]', 'dew (as covering vegetation) dew.', 'from 2926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8164}/[H8163]', 'inflected', 'heb', 'שָׂעִיר', '["sâʻîyr"]', '["like/ showers of rain"]', '["n-m"]', 'a shower (as tempestuous) small rain.', 'formed the same as 8163;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7241}/[H7231]', 'inflected', 'heb', 'רָבִיב', '["râbîyb"]', '["and/ like/ copious showers"]', '["n-m"]', 'a rain (as an accumulation of drops) shower.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1433}/[H1431]', 'lemma', 'heb', 'גֹּדֶל', '["gôdel"]', '["[the] greatness of","greatness"]', '["n-m"]', 'magnitude (literally or figuratively) greatness, stout(-ness).', 'from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6467}/H9023/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["activity/ his","wage[s]/ his","work/ his"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3477G}/[H3474]', 'inflected', 'heb', 'יָשָׁר', '["yâshâr"]', '["and/ [are] upright","and/ [is] an upright [person]","and/ an upright [person]","and/ upright","and/ upright [people]","and/ upright [things]","and/ upright[ness]"]', '["a"]', 'straight (literally or figuratively) convenient, equity, Jasher, just, meet(-est), pleased well right(-eous), straight, (most) upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3971B>/H9028', 'opaque', 'heb', 'מאוּם', '["mʼûwm"]', '["blemish/ their"]', '["n-m"]', 'a blemish (physically or morally) blemish, blot, spot.', 'usually מוּם; as if passive participle from an unused root probably meaning to stain');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6141}/[H6140]', 'lemma', 'heb', 'עִקֵּשׁ', '["ʻiqqêsh"]', '["[a person] twisted of","[are] twisted","a perverse [person]","perverse","perverse [people] of"]', '["a"]', 'distorted; hence, false crooked, froward, perverse.', 'from 6140;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6618}/[H6617]', 'inflected', 'heb', 'פְּתַלְתֹּל', '["pᵉthaltôl"]', '["and/ crooked"]', '["a"]', 'tortuous (i.e. crafty) crooked.', 'from 6617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H9008}', 'inflected', 'heb', 'ה', '["hă"]', '["¿"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5036}/[H5034]', 'lemma', 'heb', 'נָבָל', '["nâbâl"]', '["[the] foolish","a fool","foolish"]', '["a"]', 'stupid; wicked (especially impious) fool(-ish, -ish man, -ish woman), vile person.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7069}/H9031/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["he created/ you"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6213H}/H9031/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["I will appoint/ you","[who] made/ you","he made/ you"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3559I}/H9031/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["and/ he established/ you"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5769J}/[H5956]', 'lemma', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["ancient time","antiquiti<es>","antiquity","long duration"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5046}/H9031/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["so/ he will tell/ you"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5157}/[H5157]', 'inflected', 'heb', 'נָחַל', '["nâchal"]', '["when/ gave inheritances to"]', '["v"]', 'to inherit (as a (figurative) mode of descent), or (generally) to occupy; causatively, to bequeath, or (generally) distribute, instate divide, have (inheritance), take as a heritage, (cause to, give to, make to) inherit, (distribute for, divide (for, for an, by), give for, have, leave for, take (for)) inheritance, (have in, cause to, be made to) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6504}/H9043/[H6504]', 'inflected', 'heb', 'פָּרַד', '["pârad"]', '["when/ separated/ he"]', '["v"]', 'to break through, i.e. spread or separate (oneself) disperse, divide, be out of joint, part, scatter (abroad), separate (self), sever self, stretch, sunder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1367}/[H1366]', 'lemma', 'heb', 'גְּבוּלָה', '["gᵉbûwlâh"]', '["[the] boundaries of","boundaries","boundaries of"]', '["n-f"]', 'a boundary, region border, bound, coast, landmark. place.', 'or גְּבֻלָה; (shortened) feminine of 1366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4557}/[H5608]', 'inflected', 'heb', 'מִסְפָּר', '["miçpâr"]', '["to/ [the] number of"]', '["n-m"]', 'a number, definite (arithmetical) or indefinite (large, innumerable; small, a few); also (abstractly) narration abundance, account, × all, × few, (in-) finite, (certain) number(-ed), tale, telling, time.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H8414>', 'inflected', 'heb', 'ובתהו', '["u./ve./To.hu"]', '["and/ in/ a wasteland of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3214}/[H3213]', 'lemma', 'heb', 'יְלֵל', '["yᵉlêl"]', '["howling of"]', '["n-m"]', 'howl a howling.', 'from 3213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3452H}/[H3456]', 'lemma', 'heb', 'יְשִׁימוֹן', '["yᵉshîymôwn"]', '["a desolate place"]', '["n-m"]', 'a desolation desert, Jeshimon, solitary, wilderness.', 'from 3456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5437H}/H9033/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["he surrounded/ it","it goes round/ it","it will surround/ him","they had surrounded/ him","they surround/ it"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0995}/H9033/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["he took care of/ it","understanding [people]/ its"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5341}/H9033/[H5341]', 'inflected', 'heb', 'נָצַר', '["nâtsar"]', '["he guarded/ it","they will preserve/ him","you will guard/ him"]', '["v"]', 'to guard, in a good sense (to protect, maintain, obey, etc.) or a bad one (to conceal, etc.) besieged, hidden thing, keep(-er, -ing), monument, observe, preserve(-r), subtil, watcher(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0380}/[H376]', 'inflected', 'heb', 'אִישׁוֹן', '["ʼîyshôwn"]', '["like/ [the] pupil of"]', '["n-m"]', 'the little man of the eye; the pupil or ball; hence, the middle (of night) apple (of the eye), black, obscure.', 'diminutive from 376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H5404>', 'inflected', 'heb', 'כנשרים', '["ka./Ne.sher","ka./ne.sha.Rim","ke./Ne.sher","kha./Ne.sher"]', '["like <the>/ eagle","like <the>/ eagles","like/ an eagle"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5782}/[H5782]', 'lemma', 'heb', 'עוּר', '["ʻûwr"]', '["I have stirred up","I will waken","[am] about to rouse","[one who] rouses himself","[one whom] he had stirred up","[was] awake","[which] it stirs up","a protector","awake","has he stirred up","he awakens","he has roused","he has roused himself","he is roused","he stirred","he stirred up","he wielded","he will awake","he will rouse himself","he will stir up","it has roused","it stirs up","it will be roused","rouse yourself","stirring up","they rouse","they will be roused","to rouse","will you arouse","will you awaken","you will arouse","you will awaken"]', '["v"]', 'to wake (literally or figuratively) (a-) wake(-n, up), lift up (self), × master, raise (up), stir up (self).', 'a primitive root (rather identical with through the idea of opening the eyes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7064}/H9023/[H7077]', 'inflected', 'heb', 'קֵן', '["qên"]', '["nest/ his","nest/ its"]', '["n-m"]', 'a nest (as fixed), sometimes including the nestlings; figuratively, a chamber or dwelling nest, room.', 'contracted from 7077;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1469}/H9023/[H1497]', 'inflected', 'heb', 'גּוֹזָל', '["gôwzâl"]', '["young ones/ its"]', '["n-m"]', 'a nestling (as being comparatively nude of feathers) young (pigeon).', 'or (shortened) גֹזָלlemma גזָל missing vowel, corrected to גֹזָל; from 1497;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3671}/H9023/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["wings/ his","wings/ its"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0084}/H9023/[H83]', 'inflected', 'heb', 'אֶבְרָה', '["ʼebrâh"]', '["pinion/ its"]', '["n-f"]', 'feather, wing.', 'feminine of 83');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5148}/H9033/[H5148]', 'inflected', 'heb', 'נָחָה', '["nâchâh"]', '["he guided/ it","it leads/ him"]', '["v"]', 'to guide; by implication, to transport (into exile, or as colonists) bestow, bring, govern, guide, lead (forth), put, straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0410K}/[H352]', 'lemma', 'heb', 'אֵל', '["ʼêl"]', '["[am] a god","[is] a god","[was] a god of","a god","a god of","god","gods","mighty ones"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7392}/H9033/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["he caused to ride/ it"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8570}/[H5107]', 'lemma', 'heb', 'תְּנוּבָה', '["tᵉnûwbâh"]', '["fruits of"]', '["n-f"]', 'produce fruit, increase.', 'from 5107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704M>', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["<of> a field","[the] field","[the] field[s]","a field"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H5553H>', 'inflected', 'heb', 'מסלע', '["mi./Sa.la''","mi./Se.la''"]', '["from/ a rock","more than/ rock"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2496}/[H2492]', 'inflected', 'heb', 'חַלָּמִישׁ', '["challâmîysh"]', '["from/ flint of"]', '["n-m"]', 'flint flint(-y), rock.', 'probably from 2492 (in the sense of hardness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3733C}/[H3769]', 'lemma', 'heb', 'כַּר', '["kar"]', '["a lamb","battering-rams","lambs"]', '["n-m"]', 'a ram (as full-grown and fat), including a battering-ram (as butting); hence, a meadow (as for sheep); also a pad or camel''s saddle (as puffed out) captain, furniture, lamb, (large) pasture, ram. See also 1033, 3746.', 'from 3769 in the sense of plumpness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1316>', 'opaque', 'heb', 'בָּשָׁן', '["Bâshân"]', '["Bashan"]', '["n-pr-loc"]', 'Bashan (often with the article), a region East of the Jordan Bashan.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6260}/[H6257]', 'inflected', 'heb', 'עַתּוּד', '["ʻattûwd"]', '["and/ goats"]', '["n-m"]', 'prepared, i.e. full grown; spoken only (in plural) of he-goats, or (figuratively) leaders of the people chief one, (he) goat, ram.', 'or עַתֻּד; from 6257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3629}/[H3627]', 'lemma', 'heb', 'כִּלְיָה', '["kilyâh"]', '["[the] kidneys","[the] kidneys of","kidneys"]', '["n-f"]', 'a kidney (as an essential organ); figuratively, the mind (as the interior self) kidneys, reins.', 'feminine of 3627 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2561}/[H2560]', 'lemma', 'heb', 'חֶמֶר', '["chemer"]', '["wine"]', '["n-m"]', 'wine (as fermenting) × pure, red wine.', 'from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8080}/[H8080]', 'inflected', 'heb', 'שָׁמַן', '["shâman"]', '["and/ he grew fat","and/ they grew fat"]', '["v"]', 'to shine, i.e. (by analogy) be (causatively, make) oily or gross become (make, wax) fat.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3484}/[H3474]', 'lemma', 'heb', 'יְשֻׁרוּן', '["Yᵉshurûwn"]', '["Jeshurun","O Jeshurun"]', '["n-pr-m"]', 'Jeshurun, a symbolic name for Israel Jeshurun.', 'from 3474; upright;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1163}/[H1163]', 'inflected', 'heb', 'בָּעַט', '["bâʻaṭ"]', '["and/ he kicked"]', '["v"]', 'to trample down, i.e. (figuratively) despise kick.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8080}/[H8080]', 'lemma', 'heb', 'שָׁמַן', '["shâman"]', '["make fat","they have become fat","you have grown fat"]', '["v"]', 'to shine, i.e. (by analogy) be (causatively, make) oily or gross become (make, wax) fat.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5666}/[H5666]', 'lemma', 'heb', 'עָבָה', '["ʻâbâh"]', '["it is thick","you have become bloated"]', '["v"]', 'to be dense be (grow) thick(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3780}/[H3780]', 'lemma', 'heb', 'כָּשָׂה', '["kâsâh"]', '["you have become gorged"]', '["v"]', 'to grow fat (i.e. be covered with flesh) be covered. Compare 3680.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0433}/[H410]', 'lemma', 'heb', 'אֱלוֹהַּ', '["ʼĕlôwahh"]', '["<of> God","<of> [when] God","God","O God","[are] God","[are] a God","[is] God","[the] God of","a god","a god of","god","god of"]', '["n-m"]', 'a deity or the Deity God, god. See 430.', 'rarely (shortened) אֱלֹהַּ; probably prolonged (emphatic) from 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5034A}/[H5034]', 'inflected', 'heb', 'נָבֵל', '["nâbêl"]', '["and/ he treated with contempt"]', '["v"]', 'to wilt; generally, to fall away, fail, faint; figuratively, to be foolish or (morally) wicked; causatively, to despise, disgrace disgrace, dishounour, lightly esteem, fade (away, -ing), fall (down, -ling, off), do foolishly, come to nought, × surely, make vile, wither.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3444}/H9023/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["salvation/ his"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7065}/H9033/[H7065]', 'inflected', 'heb', 'קָנָא', '["qânâʼ"]', '["they made jealous/ him"]', '["v"]', 'to be (causatively, make) zealous, i.e. (in a bad sense) jealous or envious (be) envy(-ious), be (move to, provoke to) jealous(-y), × very, (be) zeal(-ous).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2114A}/[H2114]', 'inflected', 'heb', 'זוּר', '["zûwr"]', '["by/ strange [gods]","with/ a strange [woman]"]', '["v"]', 'to turn aside (especially for lodging); hence to be a foreigner, strange, profane; specifically (active participle) to commit adultery (come from) another (man, place), fanner, go away, (e-) strange(-r, thing, woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8441}/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["by/ abominations"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3707}/H9033/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["he had provoked to anger/ him","they provoked to anger/ him"]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7700}/[H7736]', 'inflected', 'heb', 'שֵׁד', '["shêd"]', '["to <the>/ demons","to the/ demons"]', '["n-m"]', 'a dæmon (as malignant) devil.', 'from 7736;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7138}/[H7126]', 'inflected', 'heb', 'קָרוֹב', '["qârôwb"]', '["[is] from/ near","[which] from/ near","from/ near","from/ near [future]"]', '["a"]', 'near (in place, kindred or time) allied, approach, at hand, any of kin, kinsfold(-sman), (that is) near (of kin), neighbour, (that is) next, (them that come) nigh (at hand), more ready, short(-ly).', 'or קָרֹב; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8175C}/H9038/[H8175]', 'inflected', 'heb', 'שָׂעַר', '["sâʻar"]', '["they had known about/ them"]', '["v"]', 'to storm; by implication, to shiver, i.e. fear be (horribly) afraid, fear, hurl as a storm, be tempestuous, come like (take away as with) a whirlwind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3205}/H9031/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["I have begotten/ you","[the] [one who] bore/ you","[which] he fathered/ you","he begot/ you","she bore/ you"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7876}/[H7876]', 'lemma', 'heb', 'שָׁיָה', '["shâyâh"]', '["you forgot"]', '["v"]', 'to keep in memory be unmindful. (Render Deuteronomy 32:18, ''A Rock bore thee, thou must recollect; and (yet) thou hast forgotten,'' etc.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2342H}/H9031/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["[who] gave birth to/ you"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5006}/[H5006]', 'inflected', 'heb', 'נָאַץ', '["nâʼats"]', '["and/ he has spurned","and/ he spurned"]', '["v"]', 'to scorn; or (in Ecclesiastes 12:5), by interchange for 5132, to bloom abhor, (give occasion to) blaspheme, contemn, despise, flourish, × great, provoke.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3708A}/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["from/ [the] provocation of","from/ grief"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0319}/H9028/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["[will be] end/ their"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8419}/[H2015]', 'lemma', 'heb', 'תַּהְפֻּכָה', '["tahpukâh"]', '["perverse things","perversiti<es>","perversities"]', '["n-f"]', 'a perversity or fraud (very) froward(-ness, thing), perverse thing.', 'from 2015;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0529}/[H539]', 'lemma', 'heb', 'אֵמוּן', '["ʼêmûwn"]', '["[the] faithful [ones] of","faithful [people]","faithfulness","faithfulness<es>"]', '["n-m"]', 'established, i.e. (figuratively) trusty; also (abstractly) trustworthiness faith(-ful), truth.', 'from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7065}/H9030/[H7065]', 'inflected', 'heb', 'קָנָא', '["qânâʼ"]', '["they have made jealous/ me"]', '["v"]', 'to be (causatively, make) zealous, i.e. (in a bad sense) jealous or envious (be) envy(-ious), be (move to, provoke to) jealous(-y), × very, (be) zeal(-ous).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3707}/H9030/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["have they provoked to anger/ me","they have provoked to anger/ me","to provoke to anger/ me"]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1892}/H9028/[H1891]', 'inflected', 'heb', 'הֶבֶל', '["hebel"]', '["by/ vanities/ their","with/ vanities/ their"]', '["n-m"]', 'emptiness or vanity; figuratively, something transitory and unsatisfactory; often used as an adverb × altogether, vain, vanity.', 'or (rarely in the abs.) הֲבֵל; from 1891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7065}/H9038/[H7065]', 'inflected', 'heb', 'קָנָא', '["qânâʼ"]', '["I will make jealous/ them"]', '["v"]', 'to be (causatively, make) zealous, i.e. (in a bad sense) jealous or envious (be) envy(-ious), be (move to, provoke to) jealous(-y), × very, (be) zeal(-ous).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3707}/H9038/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["I will provoke to anger/ them"]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6919}/[H6919]', 'lemma', 'heb', 'קָדַח', '["qâdach"]', '["[who] kindle","it has been kindled","you have kindled"]', '["v"]', 'to inflame burn, kindle.', 'a primitive root to inflame');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0639G}/H9020/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["by/ anger/ my","in/ anger/ my"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3344}/[H3344]', 'inflected', 'heb', 'יָקַד', '["yâqad"]', '["and/ it has burned"]', '["v"]', 'to burn (be) burn(-ing), × from the hearth, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7585}/[H7592]', 'lemma', 'heb', 'שְׁאוֹל', '["shᵉʼôwl"]', '["O Sheol","Sheol","[as] Sheol"]', '["n-f"]', 'hades or the world of the dead (as if a subterranean retreat), including its accessories and inmates grave, hell, pit.', 'or שְׁאֹל; from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2981}/H9024/[H2986]', 'inflected', 'heb', 'יְבוּל', '["yᵉbûwl"]', '["and/ produce/ its"]', '["n-m"]', 'produce, i.e. a crop or (figuratively) wealth fruit, increase.', 'from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3857}/[H3857]', 'inflected', 'heb', 'לָהַט', '["lâhaṭ"]', '["and/ it has set ablaze","and/ it will set ablaze"]', '["v"]', 'properly, to lick, i.e. (by implication) to blaze burn (up), set on fire, flaming, kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4144}/[H3245]', 'lemma', 'heb', 'מוֹסָד', '["môwçâd"]', '["[the] foundations of"]', '["n-m"]', 'a foundation foundation.', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2671}/H9020/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["arrow/ my","arrows/ my"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4198>', 'opaque', 'heb', 'מָזֶה', '["mâzeh"]', '["[people] weakened of"]', '["a"]', 'exhausted burnt.', 'from an unused root meaning to suck out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3898B}/[H3898]', 'inflected', 'heb', 'לָחַם', '["lâcham"]', '["and/ [people] consumed of"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7565}/[H8313]', 'lemma', 'heb', 'רֶשֶׁף', '["resheph"]', '["[are] flashes of","flame","flames of","lightning","plague"]', '["n-m"]', 'a live coal; by analogy lightning; figuratively, an arrow, (as flashing through the air); specifically, fever arrow, (burning) coal, burning heat, spark, hot thunderbolt.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6986>', 'inflected', 'heb', 'וקטב', '["ve./Ke.tev"]', '["and/ destruction"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4815}/[H4843]', 'lemma', 'heb', 'מְרִירִי', '["mᵉrîyrîy"]', '["bitter"]', '["a"]', 'bitter, i.e. poisonous bitter.', 'from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8127G}/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["and/ [the] teeth of","and/ tooth of"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2119A}/[H2119]', 'lemma', 'heb', 'זָחַל', '["zâchal"]', '["[things which] crawl of"]', '["v"]', 'to crawl; by implication, to fear be afraid, serpent, worm.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2315}/[H2314]', 'inflected', 'heb', 'חֶדֶר', '["cheder"]', '["and/ [will be] from/ inner rooms"]', '["n-m"]', 'an apartment (usually literal) ((bed) inner) chamber, innermost(-ward) part, parlour, south, × within.', 'from 2314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0970}/[H977]', 'lemma', 'heb', 'בָּחוּר', '["bâchûwr"]', '["O young man","O young men","[the] young men of","[were] young men of","a young man","young man","young men","young men of"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3243J}/[H3243]', 'lemma', 'heb', 'יָנַק', '["yânaq"]', '["[the] suckling-child of","a suckling-child","suckling-child"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6284}/H9038/[H6284]', 'inflected', 'heb', 'פָּאָה', '["pâʼâh"]', '["I will cut in pieces/ them"]', '["v"]', 'to puff, i.e. blow away scatter into corners.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2143}/H9028/[H2142]', 'inflected', 'heb', 'זֵכֶר', '["zêker"]', '["memory/ their"]', '["n-m"]', 'a memento, abstractly recollection (rarely if ever); by implication, commemoration memorial, memory, remembrance, scent.', 'or זֶכֶר; from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3708A}/[H3707]', 'lemma', 'heb', 'כַּעַס', '["kaʻaç"]', '["[is] grief","[the] provocation of","anger","frustration","provocation","vexation"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5234B}/[H5234]', 'lemma', 'heb', 'נָכַר', '["nâkar"]', '["[will be] acted as a stranger","acting as a stranger","he disguises himself","he has alienated","they should misconstrue"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6862C}/H9028/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["opponents/ their"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027H}/H9025/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ our","hands/ our"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6098}/[H3289]', 'lemma', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["[are] a plan","[is] counsel","[the] counsel of","[the] counselors of","[the] plan of","a plan","counsel","counsel of","counsel<s>","of counsel<s>","plans"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8394}/[H995]', 'lemma', 'heb', 'תָּבוּן', '["tâbûwn"]', '["[is] understanding","[will be] understanding<s>","understanding","understanding<s>"]', '["n-m"]', 'intelligence; by implication, an argument; by extension, caprice discretion, reason, skilfulness, understanding, wisdom.', 'and (feminine) תְּבוּנָה; or תּוֹבֻנָה; from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0319}/H9028/[H310]', 'inflected', 'heb', 'אַחֲרִית', '["ʼachărîyth"]', '["<to>/ end/ their"]', '["n-f"]', 'the last or end, hence, the future; also posterity (last, latter) end (time), hinder (utter) -most, length, posterity, remnant, residue, reward.', 'from 310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6697H}/H9028/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["[was] rock/ their","rock/ their"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4376}/H9038/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["he had sold/ them"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5462}/H9038/[H5462]', 'inflected', 'heb', 'סָגַר', '["çâgar"]', '["he had delivered up/ them"]', '["v"]', 'to shut up; figuratively, to surrender close up, deliver (up), give over (up), inclose, × pure, repair, shut (in, self, out, up, up together), stop, × straitly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6697H}/H9025/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["[is] like/ rock/ our"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0341}/H9025/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["and/ enemies/ our"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6414}/[H6419]', 'lemma', 'heb', 'פָּלִיל', '["pâlîyl"]', '["assessments","judges"]', '["n-m"]', 'a magistrate judge.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1612>/H9028', 'opaque', 'heb', 'גֶּפֶן', '["gephen"]', '["vine/ their","vine[s]/ their"]', '["n-m"]', 'a vine (as twining), especially the grape vine, tree.', 'from an unused root meaning to bend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7709}/[H7704]', 'inflected', 'heb', 'שְׁדֵמָה', '["shᵉdêmâh"]', '["and/ from/ [the] terraced fields of"]', '["n-f"]', 'a cultivated field blasted, field.', 'apparently from 7704;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6025>/H9028', 'opaque', 'heb', 'עֵנָב', '["ʻênâb"]', '["grapes/ their"]', '["n-m"]', 'a grape (ripe) grape, wine.', 'from an unused root probably meaning to bear fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0811}/[H810]', 'lemma', 'heb', 'אֶשְׁכּוֹל', '["ʼeshkôwl"]', '["[is] [the] cluster of","[is] a cluster of grapes","clusters"]', '["n-m"]', 'a bunch of grapes or other fruit cluster (of grapes).', 'or אֶשְׁכֹּל; probably prolonged from 810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4846}/[H4843]', 'lemma', 'heb', 'מְרֹרָה', '["mᵉrôrâh"]', '["[are] bitter","bitter things","venom of"]', '["n-f"]', 'properly, bitterness; concretely, a bitter thing; specifically bile; also venom (of a serpent) bitter (thing), gall.', 'or מְרוֹרָה; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8577M}/[H8565]', 'lemma', 'heb', 'תַּנִּין', '["tannîyn"]', '["serpents"]', '["n-m"]', 'a marine or land monster, i.e. sea-serpent or jackal dragon, sea-monster, serpent, whale.', 'or תַּנִּים; (Ezekiel 29:3), intensive from the same as 8565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3196>/H9028', 'opaque', 'heb', 'יַיִן', '["yayin"]', '["wine/ their"]', '["n-m"]', 'wine (as fermented); by implication, intoxication banqueting, wine, wine(-bibber).', 'from an unused root meaning to effervesce;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7219}/[H7218]', 'inflected', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["and/ [the] poison of","and/ poison"]', '["n-m"]', 'a poisonous plant, probably the poppy (from its conspicuous head); generally poison (even of serpents) gall, hemlock, poison, venom.', 'or רוֹשׁ; (Deuteronomy 32:32), apparently the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6620>', 'opaque', 'heb', 'פֶּתֶן', '["pethen"]', '["a cobra","cobras"]', '["n-m"]', 'an asp (from its contortions) adder.', 'from an unused root meaning to twist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0393>', 'opaque', 'heb', 'אַכְזָר', '["ʼakzâr"]', '["cruel","fierce"]', '["a"]', 'violent; by implication deadly; also (in a good sense) brave cruel, fierce.', 'from an unused root (apparently meaning to act harshly);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3647}/[H3647]', 'lemma', 'heb', 'כָּמַס', '["kâmaç"]', '["stored up"]', '["v"]', 'to store away, i.e. (figuratively) in the memory lay up in store.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0214}/H9020/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["in/ storehouses/ my"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8005}/[H7999]', 'inflected', 'heb', 'שִׁלֵּם', '["shillêm"]', '["and/ retribution"]', '["n-m"]', 'requital recompense.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4131}/[H4131]', 'lemma', 'heb', 'מוֹט', '["môwṭ"]', '["I am shaken","I will be shaken","[when] it will slip","[who] sways","certainly <to shake>","he will be shaken","it has been shaken","it has slipped","it is moved","it is shaking","it will be shaken","it will shake","may they be dropped","they are shaken","they drop","they have been shaken","they shook","they will shake","to shake"]', '["v"]', 'to waver; by implication, to slip, shake, fall be carried, cast, be out of course, be fallen in decay, × exceedingly, fall(-ing down), be (re-) moved, be ready, shake, slide, slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0343}/H9028/[H181]', 'inflected', 'heb', 'אֵיד', '["ʼêyd"]', '["calamity/ their","disaster/ their"]', '["n-m"]', 'oppression; by implication misfortune, ruin calamity, destruction.', 'from the same as 181 (in the sense of bending down);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2363A}/[H2363]', 'inflected', 'heb', 'חוּשׁ', '["chûwsh"]', '["and/ it has made haste","and/ it will make haste"]', '["v"]', 'to hurry; figuratively, to be eager with excitement or enjoyment (make) haste(-n), ready.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6264}/[H6257]', 'lemma', 'heb', 'עָתִיד', '["ʻâthîyd"]', '["impending [things]","ready"]', '["a"]', 'prepared; by implication, skilful; feminine plural the future; also treasure things that shall come, ready, treasures.', 'from 6257;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0235}/[H235]', 'lemma', 'heb', 'אָזַל', '["ʼâzal"]', '["do you treat lightly","it has been used up","they disappear"]', '["v"]', 'to go away, hence, to disappear fail, gad about, go to and fro (but in Ezekiel 27:19 the word is rendered by many ''from Uzal,'' by others ''yarn''), be gone (spent).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5800C}/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["and/ freed"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2620}/[H982]', 'lemma', 'heb', 'חָסָה', '["châçâh"]', '["I have sought refuge","I have taken refuge","I take refuge","[those who] seek refuge","[which] they sought refuge","[who] he takes refuge","[whom] I take refuge","it takes refuge","let me take refuge","of [those who] take refuge","take refuge","they have taken refuge","they will take refuge","you will take refuge"]', '["v"]', 'to flee for protection; figuratively, to confide in have hope, make refuge, (put) trust.', 'a primitive root; (compare 982)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5257A}/H9028/[H5258]', 'inflected', 'heb', 'נְסִיךְ', '["nᵉçîyk"]', '["drink-offering/ their","molten images/ their"]', '["n-m"]', 'properly, something poured out, i.e. a libation; also a molten image; by implication, a prince (as anointed) drink offering, duke, prince(-ipal).', 'from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5826}/H9036/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["and/ let them help/ you"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5643B}/[H5641]', 'lemma', 'heb', 'סֵתֶר', '["çêther"]', '["a shelter"]', '["n-m"]', 'a cover (in a good or a bad, a literal or a figurative sense) backbiting, covering, covert, × disguise(-th), hiding place, privily, protection, secret(-ly, place).', 'or (feminine) סִתְרָה; (Deuteronomy 32:38), from 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027H}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8150}/[H8150]', 'lemma', 'heb', 'שָׁנַן', '["shânan"]', '["I sharpen","I was pierced","[are] sharpened","sharpened","they sharpen"]', '["v"]', 'to point (transitive or intransitive); intensively, to pierce; figuratively, to inculcate prick, sharp(-en), teach diligently, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1300B}/[H1299]', 'lemma', 'heb', 'בָּרָק', '["bârâq"]', '["[the] lightning flash of","[the] lightning of","[with] lightning","lightning","lightning flashes","lightning<s>"]', '["n-m"]', 'lightning; by analogy, a gleam; concretely, a flashing sword bright, glitter(-ing sword), lightning.', 'from 1299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6862C}/H9020/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["to/ foes/ my"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8130}/H9030/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["and/ to/ [those who] hate/ me"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7937}/[H7937]', 'lemma', 'heb', 'שָׁכַר', '["shâkar"]', '["I will make drunk","making drunk","people have become drunk","you make [them] drunk","you will become drunk"]', '["v"]', 'to become tipsy; in a qualified sense, to satiate with a stimulating drink or (figuratively) influence (be filled with) drink (abundantly), (be, make) drunk(-en), be merry. (Superlative of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2719}/H9020/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["and/ sword/ my"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7633}/[H7628]', 'inflected', 'heb', 'שִׁבְיָה', '["shibyâh"]', '["and/ [the] captive"]', '["n-f"]', 'exile (abstractly or concretely and collectively) captives(-ity).', 'feminine of 7628;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H7218A>', 'inflected', 'heb', 'מראש', '["me./Rosh"]', '["from/ [the] head of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6546}/[H6545]', 'lemma', 'heb', 'פַּרְעָה', '["parʻâh"]', '["[the] leaders of","heads"]', '["n-m"]', 'leadership (plural concretely, leaders) avenging, revenge.', 'feminine of 6545 (in the sense of beginning);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7442B}/[H7442]', 'lemma', 'heb', 'רָנַן', '["rânan"]', '["I made sing for joy","I shout for joy","I sing for joy","anything will be sung","certainly <shout>","cry out","it cries aloud","it will shout for joy","let them shout for joy","let them sing for joy","let us sing for joy","may they shout for joy","shout for joy","sing for joy","they cry aloud","they shout for joy","they will shout for joy","they will sing for joy","we will shout for joy","you make shout for joy"]', '["v"]', 'properly, to creak (or emit a stridulous sound), i.e. to shout (usually for joy) aloud for joy, cry out, be joyful (greatly, make to) rejoice, (cause to) shout (for joy), (cause to) sing (aloud, for joy, out), triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5359}/[H5358]', 'inflected', 'heb', 'נָקָם', '["nâqâm"]', '["and/ vengeance"]', '["n-m"]', 'revenge avenged, quarrel, vengeance.', 'from 5358;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6862C}/H9023/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["to/ foes/ his","to/ opponents/ his"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0127G}/H9023/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["land/ his","land/ its","own land/ his"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971A}/H9023\/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["people/ his"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1954K}/[H3467]', 'inflected', 'heb', 'הוֹשֵׁעַ', '["Hôwshêaʻ"]', '["and/ Hoshea"]', '["n-pr-m"]', 'Hoshea, the name of five Israelites Hosea, Hoshea, Oshea.', 'from 3467; deliverer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760K}/[H7760]', 'lemma', 'heb', 'שׂוּם', '["sûwm"]', '["[are] putting","[one who] sets","he set","he sets","he will appoint","he will put","it put [it]","set","they set","they will set","you will put"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416E}/H9026/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["[is] lives/ your"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5015H}/[H5015]', 'lemma', 'heb', 'נְבוֹ', '["Nᵉbôw"]', '["Nebo"]', '["n-pr-m n-pr-loc"]', 'Nebo, the name of a Babylonian deity, also of a mountain in Moab, and of a place in Palestine Nebo.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4191}/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ certainly <to kill>","and/ die","and/ it will die","and/ put to death","so/ I may die","so/ may he die"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0622}/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["and/ be gathered","and/ it has been removed","and/ they gathered","so/ they may gather"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6946H}/[H6945]', 'lemma', 'heb', 'קָדֵשׁ', '["Qâdêsh"]', '["Kadesh"]', '["n-pr-loc"]', 'Kadesh, a place in the Desert Kadesh. Compare 6947.', 'the same as 6945; sanctuary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H5514G>', 'inflected', 'heb', 'מסיני', '["mi./si.Nai"]', '["from/ Sinai"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2224}/[H2224]', 'inflected', 'heb', 'זָרַח', '["zârach"]', '["and/ he dawned"]', '["v"]', 'properly, to irradiate (or shoot forth beams), i.e. to rise (as the sun); specifically, to appear (as a symptom of leprosy) arise, rise (up), as soon as it is up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8165A}/[H8163]', 'inflected', 'heb', 'שֵׂעִיר', '["Sêʻîyr"]', '["from/ Seir"]', '["n-pr"]', 'Seir, a mountain of Idumaea and its aboriginal occupants, also one in Palestine Seir.', 'formed like 8163; rough;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3313}/[H3313]', 'lemma', 'heb', 'יָפַע', '["yâphaʻ"]', '["he has shone forth","he shone forth","it shine forth","shine forth","you have shone forth"]', '["v"]', 'to shine be light, shew self, (cause to) shine (forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6290H}/[H6286]', 'lemma', 'heb', 'פָּארָן', '["Pâʼrân"]', '["Paran"]', '["n-pr-loc"]', 'Paran, a desert of Arabia Paran.', 'from 6286; ornamental;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0857}/[H225]', 'inflected', 'heb', 'אָתָה', '["ʼâthâh"]', '["and/ he came","and/ he has come"]', '["v"]', 'to arrive (be-, things to) come (upon), bring.', 'or אָתָא; a primitive root (collateral to 225 contraction);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7233}/[H7231]', 'inflected', 'heb', 'רְבָבָה', '["rᵉbâbâh"]', '["from/ ten thousands of","more than/ ten thousand"]', '["n-f"]', 'abundance (in number), i.e. (specifically) a myriad (whether definite or indefinite) many, million, × multiply, ten thousand.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3225G}/H9023/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["[were] from/ right/ his","from/ right [hand]/ his","from/ right/ his"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0784}//{H1881}/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["fire of// law"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2245}/[H2244]', 'lemma', 'heb', 'חָבַב', '["châbab"]', '["[he is] loving"]', '["v"]', 'properly, to hide (as in the bosom), i.e. to cherish (with affection) love.', 'a primitive root (compare 2244, 2247);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6918H}/H9023/[H6942]', 'inflected', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["O holy [ones]/ his","holy [ones]/ his"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8497}/[H8497]', 'lemma', 'heb', 'תָּכָה', '["tâkâh"]', '["they were led"]', '["v"]', 'to strew, i.e. encamp sit down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7272}/H9021/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["for/ feet/ your","to/ foot/ your"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375T}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["he will take"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1703}/H9021/[H1696]', 'inflected', 'heb', 'דַּבָּרָה', '["dabbârâh"]', '["from/ words/ your"]', '["n-f"]', 'a word word.', 'intensive from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6952}/[H6950]', 'lemma', 'heb', 'קְהִלָּה', '["qᵉhillâh"]', '["[the] assembly of","an assembly"]', '["n-f"]', 'an assemblage assembly, congregation.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3484}/[H3474]', 'inflected', 'heb', 'יְשֻׁרוּן', '["Yᵉshurûwn"]', '["in/ Jeshurun"]', '["n-pr-m"]', 'Jeshurun, a symbolic name for Israel Jeshurun.', 'from 3474; upright;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0622}/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["when/ gathered themselves"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3162A}/[H3161]', 'lemma', 'heb', 'יַחַד', '["yachad"]', '["alike","altogether","together"]', '["n-m"]', 'properly, a unit, i.e. (adverb) unitedly alike, at all (once), both, likewise, only, (al-) together, withal.', 'from 3161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4962}/H9023/[H4970]', 'inflected', 'heb', 'מַת', '["math"]', '["men/ his"]', '["n-m"]', 'properly, an adult (as of full length); by implication, a man (only in the plural) few, × friends, men, persons, × small.', 'from the same as 4970;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4557}\/[H5608]', 'inflected', 'heb', 'מִסְפָּר', '["miçpâr"]', '["number"]', '["n-m"]', 'a number, definite (arithmetical) or indefinite (large, innumerable; small, a few); also (abstractly) narration abundance, account, × all, × few, (in-) finite, (certain) number(-ed), tale, telling, time.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5828}/[H5826]', 'inflected', 'heb', 'עֵזֶר', '["ʻêzer"]', '["and/ a help"]', '["n-m"]', 'aid help.', 'from 5826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6862C}/H9023/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["from/ foes/ his","from/ opponents/ his","more than/ foes/ its"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3878}/[H3867]', 'inflected', 'heb', 'לֵוִי', '["Lêvîy"]', '["and/ of/ Levi"]', '["n-pr-m"]', 'Levi, a son of Jacob Levi. See also 3879, 3881.', 'from 3867; attached;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8550}/H9021/[H8537]', 'inflected', 'heb', 'תֻּמִּים', '["Tummîym"]', '["Thummim/ your"]', '["n-pr-m"]', 'perfections, i.e. (techn.) one of the epithets of the objects in the high-priest''s breastplate as an emblem of complete Truth Thummim.', 'plural of 8537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0224}/H9021/[H217]', 'inflected', 'heb', 'אוּרִים', '["ʼÛwrîym"]', '["and/ Urim/ your"]', '["n-m"]', 'Urim, the oracular brilliancy of the figures in the high-priest''s breastplate Urim.', 'plural of 217; lights;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2623}/H9021/[H2616]', 'inflected', 'heb', 'חָסִיד', '["châçîyd"]', '["faithful [one]/ your","faithful [people]/ your"]', '["a"]', 'properly, kind, i.e. (religiously) pious (a saint) godly (man), good, holy (one), merciful, saint, (un-) godly.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7378}/H9033/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["[those who] contend against/ him","you contended with/ him"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4809G}/[H4808]', 'lemma', 'heb', 'מְרִיבָה', '["Mᵉrîybâh"]', '["Meribah"]', '["n-pr-loc"]', 'Meribah, the name of two places in the Desert Meribah.', 'the same as 4808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0565A}/H9021/[H561]', 'inflected', 'heb', 'אִמְרָה', '["ʼimrâh"]', '["word/ your"]', '["n-f"]', 'commandment, speech, word.', 'or אֶמְרָה; feminine of 561, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1285}/H9021/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["and/ covenant/ your"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941G}/H9021/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["judgments/ your","sentence/ your"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8451}/H9021/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["and/ law/ your"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6988}/[H6999]', 'lemma', 'heb', 'קְטוֹרָה', '["qᵉṭôwrâh"]', '["incense"]', '["n-m"]', 'perfume incense.', 'from 6999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0639I}/H9021/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["in/ nose/ your"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3632}/[H3634]', 'inflected', 'heb', 'כָּלִיל', '["kâlîyl"]', '["and/ [the] whole offering","and/ perfect of","and/ whole offering"]', '["a"]', 'complete; as noun, the whole (specifically, a sacrifice entirely consumed); as adverb, fully all, every whit, flame, perfect(-ion), utterly, whole burnt offering (sacrifice), wholly.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4196}/H9021/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["altar/ your","altars/ your"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428H}/H9023/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["wealth/ his"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6467}/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["and/ [the] work of","and/ deed[s] of"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4975>', 'opaque', 'heb', 'מֹתֶן', '["môthen"]', '["[the] loins of","loins"]', '["n-m"]', 'properly, the waist or small of the back; only in plural the loins greyhound, loins, side.', 'from an unused root meaning to be slender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965J}/H9033/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["[those who] rise against/ him"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8130}/H9033/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["and/ [those who] hate/ him"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965J}/H9013\/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["they will rise/ !"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3039A}/[H1730]', 'lemma', 'heb', 'יְדִיד', '["yᵉdîyd"]', '["[the] beloved [one] of","lovely"]', '["a n-f"]', 'loved amiable, (well-) beloved, loves.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2653}/[H2645]', 'lemma', 'heb', 'חׇפַף', '["chophaph"]', '["[who] covers"]', '["v"]', 'to cover (in protection) cover.', 'a primitive root (compare 2645, 3182);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7931}\/[H7901]', 'inflected', 'heb', 'שָׁכַן', '["shâkan"]', '["he dwells"]', '["v"]', 'to reside or permanently stay (literally or figuratively) abide, continue, (cause to, make to) dwell(-er), have habitation, inhabit, lay, place, (cause to) remain, rest, set (up).', 'a primitive root (apparently akin (by transmission) to 7901 through the idea of lodging; compare 5531, 7925);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H4022>', 'inflected', 'heb', 'ממגד', '["mi./Me.ged"]', '["from/ [the] excellent gift of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8415}/[H1949]', 'inflected', 'heb', 'תְּהוֹם', '["tᵉhôwm"]', '["and/ from/ [the] deep","and/ from/ [the] depths of"]', '["n"]', 'an abyss (as a surging mass of water), especially the deep (the main sea or the subterranean watersupply) deep (place), depth.', 'or תְּהֹם; (usually feminine) from 1949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H4022>', 'inflected', 'heb', 'וממגד', '["u./mi./Me.ged"]', '["and/ from/ [the] excellent gift of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1645}/[H1644]', 'lemma', 'heb', 'גֶּרֶשׁ', '["geresh"]', '["[the] yield of"]', '["n-m"]', 'produce (as if expelled) put forth.', 'from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H7218I>', 'inflected', 'heb', 'ומראש', '["u./me./Rosh"]', '["and/ from/ [the] top of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2042>', 'opaque', 'heb', 'הָרָר', '["hârâr"]', '["[the] mountains of","mountains of"]', '["n-m"]', 'a mountain hill, mount(-ain).', 'from an unused root meaning to loom up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6924H}/[H6923]', 'lemma', 'heb', 'קֶדֶם', '["qedem"]', '["[the] beginning of","ancient time","antiquity","long ago"]', '["n-m adv"]', 'the front, of place (absolutely, the fore part, relatively the East) or time (antiquity); often used adverbially (before, anciently, eastward) aforetime, ancient (time), before, east (end, part, side, -ward), eternal, × ever(-lasting), forward, old, past. Compare 6926.', 'or קֵדְמָה; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4393}/H9024/[H4390]', 'inflected', 'heb', 'מְלֹא', '["mᵉlôʼ"]', '["and/ what fills/ it"]', '["n-m"]', 'fulness (literally or figuratively) × all along, × all that is (there-) in, fill, (× that whereof...was) full, fulness, (hand-) full, multitude.', 'rarely מְלוֹא; or מְלוֹ; (Ezekiel 41:8), from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7522}/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["and/ [the] favor of"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5572>', 'opaque', 'heb', 'סְנֶה', '["çᵉneh"]', '["<of> [the] bush"]', '["n-m"]', 'a bramble bush.', 'from an unused root meaning to prick;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935I}/H9012/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["may it come/ !"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7161A}/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["and/ [are the] horns of","and/ [the] horn of"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4519G}\/[H5382]', 'inflected', 'heb', 'מְנַשֶּׁה', '["Mᵉnashsheh"]', '["Manasseh"]', '["n-pr-m"]', 'Menashsheh, a grandson of Jacob, also the tribe descended from him, and its territory Manasseh.', 'from 5382; causing to forget;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2074}/[H2082]', 'inflected', 'heb', 'זְבוּלוּן', '["Zᵉbûwlûwn"]', '["and/ of/ Zebulun"]', '["n-pr-m n-pr-loc"]', 'Zebulon, a son of Jacob; also his territory and tribe Zebulun.', 'or זְבֻלוּן; or זְבוּלֻן; from 2082; habitation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8055}/[H8055]', 'lemma', 'heb', 'שָׂמַח', '["sâmach"]', '["I rejoice","I rejoiced","I will rejoice","[which] it makes glad","he makes glad","he rejoice","he rejoiced","he rejoices","he will be happy","he will rejoice","it is glad","it makes glad","it rejoices","it was glad","it will rejoice","let him be glad","let him be take pleasure","let him rejoice","let it rejoice","let them rejoice","let us rejoice","make glad","making glad","may he rejoice","may they be glad","may they rejoice","rejoice","she will rejoice","surely <make rejoice>","they have rejoiced","they make glad","they rejoice","they rejoiced","they should rejoice","they will rejoice","you are rejoicing","you have allowed to rejoice","you have made to rejoice","you rejoice"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0168G}/H9021/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["in/ tent/ your","in/ tents/ your"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8228>', 'opaque', 'heb', 'שֶׁפַע', '["shephaʻ"]', '["[the] abundance of"]', '["n-m"]', 'resources abundance.', 'from an unused root meaning to abound;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3243G}/[H3243]', 'lemma', 'heb', 'יָנַק', '["yânaq"]', '["I will suckle","he sucks","they will suck","you may suck","you will suck"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8226}/[H8226]', 'inflected', 'heb', 'שָׂפַן', '["sâphan"]', '["and/ hidden [things] of"]', '["v"]', 'to conceal (as a valuable) treasure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2934}/[H2934]', 'lemma', 'heb', 'טָמַן', '["ṭâman"]', '["I have hidden","[are] hidden","[is] hidden","[it was] hidden","he hid","he hides","hidden","hidden [things] of","people have hidden","they had hidden","they have hidden"]', '["v"]', 'to hide (by covering over) hide, lay privily, in secret.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2344}\/[H2342]', 'inflected', 'heb', 'חוֹל', '["chôwl"]', '["sand"]', '["n-m"]', 'sand (as round or whirling particles) sand.', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1410G}/[H1464]', 'inflected', 'heb', 'גָּד', '["Gâd"]', '["and/ of/ Gad"]', '["n-pr-m"]', 'Gad, a son of Jacob, including his tribe and its territory; also a prophet Gad.', 'from 1464;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2963}/[H2963]', 'inflected', 'heb', 'טָרַף', '["ṭâraph"]', '["and/ he tears"]', '["v"]', 'to pluck off or pull to pieces; causatively to supply with food (as in morsels) catch, × without doubt, feed, ravin, rend in pieces, × surely, tear (in pieces).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6936}/[H6915]', 'lemma', 'heb', 'קׇדְקֹד', '["qodqôd"]', '["a scalp","scalp","scalp of"]', '["n-m"]', 'the crown of the head (as the part most bowed) crown (of the head), pate, scalp, top of the head.', 'from 6915;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200J}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ he saw","and/ you will see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2710}/[H2710]', 'lemma', 'heb', 'חָקַק', '["châqaq"]', '["[what] is decreed","a commander","commanders","cutting","inscribed","they enact"]', '["v"]', 'properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5603}/[H5603]', 'lemma', 'heb', 'סָפַן', '["çâphan"]', '["[was] reserved","covered"]', '["v"]', 'to hide by covering; specifically, to roof (passive participle as noun, a roof) or wainscot; figuratively, to reserve cieled, cover, seated.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1835G}/[H1777]', 'inflected', 'heb', 'דָּן', '["Dân"]', '["and/ of/ Dan"]', '["n-pr-m"]', 'Dan, one of the sons of Jacob; also the tribe descended from him, and its territory; likewise a place in Palestine colonized by them Daniel', 'from 1777; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2187}/[H2187]', 'lemma', 'heb', 'זָנַק', '["zânaq"]', '["he leaps forth"]', '["v"]', 'properly, to draw together the feet (as an animal about to dart upon its prey), i.e. to spring forward leap.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5321G}/[H6617]', 'inflected', 'heb', 'נַפְתָּלִי', '["Naphtâlîy"]', '["and/ of/ Naphtali"]', '["n-pr-m n-pr-loc"]', 'Naphtali, a son of Jacob, with the tribe descended from him, and its territory Naphtali.', 'from 6617; my wrestling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7649}/[H7646]', 'lemma', 'heb', 'שָׂבֵעַ', '["sâbêaʻ"]', '["[is] satisfied of","satisfied","satisfied [people]","satisfied of","surfeited of"]', '["a"]', 'satiated (in a pleasant or disagreeable sense) full (of), satisfied (with).', 'from 7646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7522}/[H7521]', 'lemma', 'heb', 'רָצוֹן', '["râtsôwn"]', '["[are the] delight of","[the] desire of","[the] favor of","acceptance","desire","favor","pleasure"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4392}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["and/ full"]', '["a"]', 'full (literally or figuratively) or filling (literally); also (concretely) fulness; adverbially, fully × she that was with child, fill(-ed, -ed with), full(-ly), multitude, as is worth.', 'from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1864>', 'inflected', 'heb', 'ודרום', '["ve./da.Rom"]', '["and/ [the] south"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423H}/H9012\/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["take possession of/ !"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0836}/[H833]', 'inflected', 'heb', 'אָשֵׁר', '["ʼÂshêr"]', '["and/ of/ Asher"]', '["n-pr"]', 'Asher, a son of Jacob, and the tribe descended from him, with its territory; also a place in Palestine Asher', 'from 833, happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2881}/[H2881]', 'inflected', 'heb', 'טָבַל', '["ṭâbal"]', '["and/ [one who] dips"]', '["v"]', 'to dip, to immerse dip, plunge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4515}/H9021/[H5274]', 'inflected', 'heb', 'מִנְעָל', '["minʻâl"]', '["bolts/ your"]', '["n-m"]', 'a bolt shoe.', 'from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H3117G>/H9021', 'inflected', 'heb', 'וכימיך', '["u./khe./ya.Mei./kha"]', '["and/ [will be] like/ days/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1679>/H9021', 'opaque', 'heb', 'דֹּבֶא', '["dôbeʼ"]', '["strength/ your"]', '["n-m"]', 'quiet strength.', 'from an unused root (compare 1680) (probably meaning to be sluggish, i.e. restful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0410G}/[H352]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["[is] like <the>/ God","like <the>/ God"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5828}/H9021/[H5826]', 'inflected', 'heb', 'עֵזֶר', '["ʻêzer"]', '["for/ help/ your","in/ helper/ your"]', '["n-m"]', 'aid help.', 'from 5826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1346}/H9023/[H1342]', 'inflected', 'heb', 'גַּאֲוָה', '["gaʼăvâh"]', '["and/ in/ majesty/ his"]', '["n-f"]', 'arrogance or majesty; by implication, (concretely) ornament excellency, haughtiness, highness, pride, proudly, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7834}/[H7833]', 'lemma', 'heb', 'שַׁחַק', '["shachaq"]', '["[the] clouds","clouds"]', '["n-m"]', 'a powder (as beaten small); by analogy, a thin vapor; by extension, the firmament cloud, small dust, heaven, sky.', 'from 7833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4585}/[H4583]', 'lemma', 'heb', 'מְעוֹנָה', '["mᵉʻôwnâh"]', '["[is] a hiding place"]', '["n-f"]', 'den, habitation, (dwelling) place, refuge.', 'or מְעֹנָה; feminine of 4583, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8478G}/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["and/ [are] <from>/ beneath","and/ [was] from/ under","and/ [were] from/ under"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8064>/H9023', 'opaque', 'heb', 'שָׁמַיִם', '["shâmayim"]', '["heavens/ his"]', '["n-m"]', 'the sky (as aloft; the dual perhaps alluding to the visible arch in which the clouds move, as well as to the higher ether where the celestial bodies revolve) air, × astrologer, heaven(-s).', 'dual of an unused singular שָׁמֶה; from an unused root meaning to be lofty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2919}/[H2926]', 'lemma', 'heb', 'טַל', '["ṭal"]', '["[the] dew of","[will be the] dew of","dew"]', '["n-m"]', 'dew (as covering vegetation) dew.', 'from 2926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0835}/H9031/[H833]', 'inflected', 'heb', 'אֶשֶׁר', '["ʼesher"]', '["how blessed [are]!/ you"]', '["n-m"]', 'happiness; only in masculine plural construction as interjection, how happy! blessed, happy.', 'from 833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5828}/H9021/[H5826]', 'inflected', 'heb', 'עֵזֶר', '["ʻêzer"]', '["help/ your"]', '["n-m"]', 'aid help.', 'from 5826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1346}/H9021/[H1342]', 'inflected', 'heb', 'גַּאֲוָה', '["gaʼăvâh"]', '["eminence/ your"]', '["n-f"]', 'arrogance or majesty; by implication, (concretely) ornament excellency, haughtiness, highness, pride, proudly, swelling.', 'from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3584}/[H3584]', 'inflected', 'heb', 'כָּחַשׁ', '["kâchash"]', '["and/ deceiving","and/ we have denied","so/ they may cringe"]', '["v"]', 'to be untrue, in word (to lie, feign, disown) or deed (to disappoint, fail, cringe) deceive, deny, dissemble, fail, deal falsely, be found liars, (be-) lie, lying, submit selves.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1869}\/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["you will tread"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6160I}/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["from/ [the] desert plains of"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3603G}/[H3769]', 'inflected', 'heb', 'כִּכָּר', '["kikkâr"]', '["the/ district"]', '["n-f"]', 'a circle, i.e. (by implication) a circumjacent tract or region, especially the Ghor or valley of the Jordan; also a (round) loaf; also a talent (or large [round] coin) loaf, morsel, piece, plain, talent.', 'from 3769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1237G}/[H1234]', 'lemma', 'heb', 'בִּקְעָה', '["biqʻâh"]', '["in [the] valley of"]', '["n-f"]', 'properly, a split, i.e. a wide level valley between mountains plain, valley.', 'from 1234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3405H}/[H3394]', 'lemma', 'heb', 'יְרִיחוֹ', '["Yᵉrîychôw"]', '["Jericho"]', '["n-pr-loc"]', 'Jericho or Jerecho, a place in Palestine Jericho.', 'or יְרֵחוֹ; or variation (1 Kings 16:34) יְרִיחֹה; perhaps from 3394; its month; or else from 7306; fragrant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5899}/[H5892]', 'lemma', 'heb', 'עִיר הַתְּמָרִים', '["ʻÎyr hat-Tᵉmârîym"]', '["[the] city of"]', '["n-pr-loc"]', 'Ir-hat-Temarim, a place in Palestine the city of palmtrees.', 'from 5892 and the plural of 8558 with the article interpolated; city of the palmtrees;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5899}/[H5892]', 'inflected', 'heb', 'עִיר הַתְּמָרִים', '["ʻÎyr hat-Tᵉmârîym"]', '["the/ palm trees"]', '["n-pr-loc"]', 'Ir-hat-Temarim, a place in Palestine the city of palmtrees.', 'from 5892 and the plural of 8558 with the article interpolated; city of the palmtrees;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6900}/H9023/[H6912]', 'inflected', 'heb', 'קְבוּרָה', '["qᵉbûwrâh"]', '["burial place/ his"]', '["n-f"]', 'sepulture; (concretely) a sepulchre burial, burying place, grave, sepulchre.', 'or קְבֻרָה; feminine passive participle of 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3893}/H9023/[H3892]', 'inflected', 'heb', 'לֵחַ', '["lêach"]', '["vigor/ his"]', '["n-m"]', 'freshness, i.e. vigor natural force.', 'from the same as 3892;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1065}/[H1058]', 'lemma', 'heb', 'בְּכִי', '["Bᵉkîy"]', '["[the] weeping of","a weeping","weeping","weeping of"]', '["n-m"]', 'a weeping; by analogy, a dripping overflowing, × sore, (continual) weeping, wept.', 'from 1058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4872}/[H4871]', 'inflected', 'heb', 'מֹשֶׁה', '["Môsheh"]', '["like/ Moses"]', '["n-pr-m"]', 'Mosheh, the Israelite lawgiver Moses.', 'from 4871; drawing out (of the water), i.e. rescued;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4172A}/[H3372]', 'inflected', 'heb', 'מוֹרָא', '["môwrâʼ"]', '["the/ terror"]', '["n-m"]', 'fear; by implication, a fearful thing or deed dread, (that ought to be) fear(-ed), terribleness, terror.', 'or מֹרָא; or מוֹרָהxlit môrâh corrected to môwrâh; (Psalm 9:20), from 3372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H4057B}/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["from/ the/ wilderness"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310G}/H9021/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["from/ mouth/ your"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1897}/[H1901]', 'inflected', 'heb', 'הָגָה', '["hâgâh"]', '["and/ I will meditate","and/ you will meditate"]', '["v"]', 'to murmur (in pleasure or anger); by implication, to ponder imagine, meditate, mourn, mutter, roar, × sore, speak, study, talk, utter.', 'a primitive root (compare 1901);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980G}\/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["it has gone","you will go"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2571}/[H2570]', 'lemma', 'heb', 'חָמֻשׁ', '["châmush"]', '["arrayed for battle"]', '["a"]', 'staunch, i.e. able-bodied soldiers armed (men), harnessed.', 'passive participle of the same as 2570;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2428G}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["<the>/ strength","<the>/ strength<s>","the/ army"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5826}/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["and/ I was helped","and/ he helped","and/ they helped","and/ they were helped","and/ you will help"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3425}/H9026/[H3423]', 'inflected', 'heb', 'יְרֻשָּׁה', '["yᵉrushshâh"]', '["possession/ your"]', '["n-f"]', 'something occupied; a conquest; also a patrimony heritage, inheritance, possession.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697G}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["word/ your","words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0553}\/[H553]', 'inflected', 'heb', 'אָמַץ', '["ʼâmats"]', '["and/ be bold"]', '["v"]', 'to be alert, physically (on foot) or mentally (in courage) confirm, be courageous (of good courage, stedfastly minded, strong, stronger), establish, fortify, harden, increase, prevail, strengthen (self), make strong (obstinate, speed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7851G}/[H7848]', 'inflected', 'heb', 'שִׁטִּים', '["Shiṭṭîym"]', '["<the>/ Shittim"]', '["n-pr-loc"]', 'Shittim, a place East of the Jordan Shittim.', 'the same as the plural of 7848; acacia trees;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2791A}/[H2790]', 'lemma', 'heb', 'חֶרֶשׁ', '["cheresh"]', '["secretly"]', '["adv"]', 'magical craft; also silence cunning, secretly.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7343}/[H7342]', 'lemma', 'heb', 'רָחָב', '["Râchâb"]', '["Rahab","[was] Rahab"]', '["n-pr-f"]', 'Rachab, a Canaanitess Rahab.', 'the same as 7342; proud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2658}/[H2658]', 'inflected', 'heb', 'חָפַר', '["châphar"]', '["to/ spy out"]', '["v"]', 'properly, to pry into; by implication, to delve, to explore dig, paw, search out, seek.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004B}/H9022/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["to/ house/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8179G}/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["the/ gate","the/ gates"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5462}/[H5462]', 'inflected', 'heb', 'סָגַר', '["çâgar"]', '["[about] to/ shut","to/ deliver up [them]"]', '["v"]', 'to shut up; figuratively, to surrender close up, deliver (up), give over (up), inclose, × pure, repair, shut (in, self, out, up, up together), stop, × straitly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2822}/[H2821]', 'inflected', 'heb', 'חֹשֶׁךְ', '["chôshek"]', '["[are] in <the>/ darkness","at <the>/ darkness","in <the>/ darkness","in the/ darkness"]', '["n-m"]', 'the dark; hence (literally) darkness; figuratively, misery, destruction, death, ignorance, sorrow, wickedness dark(-ness), night, obscurity.', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5381}/H9038/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["may it overtake/ them","will it overtake?/ them","you will overtake/ them"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1406}/H9011/[H1342]', 'inflected', 'heb', 'גָּג', '["gâg"]', '["the/ roof/ towards"]', '["n-m"]', 'a roof; by analogy, the top of an altar roof (of the house), (house) top (of the house).', 'probably by reduplication from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2934}/H9038/[H2934]', 'inflected', 'heb', 'טָמַן', '["ṭâman"]', '["and/ she had hidden/ them","and/ you will hide/ them"]', '["v"]', 'to hide (by covering over) hide, lay privily, in secret.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6086I}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["the/ pieces of wood","the/ tree","the/ wood<s>"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6186A}/[H6186]', 'inflected', 'heb', 'עָרַךְ', '["ʻârak"]', '["that/ had been arranged","who/ arrange"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1406}/[H1342]', 'inflected', 'heb', 'גָּג', '["gâg"]', '["the/ roof","the/ roof of","the/ roofs"]', '["n-m"]', 'a roof; by analogy, the top of an altar roof (of the house), (house) top (of the house).', 'probably by reduplication from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4569B}/[H5674]', 'inflected', 'heb', 'מַעֲבָר', '["maʻăbâr"]', '["the/ fords","the/ passes"]', '["n-m"]', 'a crossing-place (of a river, a ford; of a mountain, a pass); abstractly, a transit, i.e. (figuratively) overwhelming ford, place where...pass, passage.', 'or feminine מַעֲבָרָה; from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8179G}/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["and/ the/ gate"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7291}/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["the/ pursuer","the/ pursuers"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7901G}/H9013/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["they had lain down/ !","you will lie down/ !"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0367}/H9026/[H366]', 'inflected', 'heb', 'אֵימָה', '["ʼêymâh"]', '["dread/ your"]', '["n-f"]', 'fright; concrete, an idol (as a bugbear) dread, fear, horror, idol, terrible, terror.', 'or (shortened) אֵמָה; from the same as 366;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440I}/H9026/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<from>/ because of/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0571I}/[H539]', 'lemma', 'heb', 'אֶמֶת', '["ʼemeth"]', '["[are] truth","[is] truth","faithfulness","reliability","truth"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315H}/H9025/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["life/ our","lives/ our"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4194}/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["from/ death","more than/ death"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478H}/H9036/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["for/ you"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697I}/H9025/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["business/ our"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3381}/H9038/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["and/ he brought down/ them","and/ people took down/ them","and/ she let down/ them"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2256M}/[H2254]', 'inflected', 'heb', 'חֶבֶל', '["chebel"]', '["by/ a measuring-line of","for/ ropes","in/ cords of","with <the>/ measuring-line","with <the>/ rope","with/ [the] cords of","with/ cords of","with/ ropes"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2346G>', 'inflected', 'heb', 'החמתים', '["ha./Cho.mo.Ta.yim","ha./cho.Mah","ha./cho.Mot","ha./cho.mo.Ta.yim"]', '["the/ city wall","the/ two walls","the/ wall","the/ walls"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H2346G>', 'inflected', 'heb', 'ובחומה', '["u./va./cho.Mah","u./ve./cho.Mat"]', '["and/ in the/ city wall","and/ on/ [the] wall of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2247}/[H2245]', 'inflected', 'heb', 'חָבָה', '["châbâh"]', '["and/ it will hide itself","and/ you will hide yourselves"]', '["v"]', 'to secrete hide (self).', 'a primitive root (compare 2245);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7621}/H9022/[H7650]', 'inflected', 'heb', 'שְׁבוּעָה', '["shᵉbûwʻâh"]', '["from/ oath/ your"]', '["n-f"]', 'properly, something sworn, i.e. an oath curse, oath, × sworn.', 'feminine passive participle of 7650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7650}/H9035/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["you have adjured/ us","you made swear/ us"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8615A}/[H6960]', 'lemma', 'heb', 'תִּקְוָה', '["tiqvâh"]', '["[the] cord of"]', '["n-f"]', 'literally a cord (as an attachment); figuratively, expectancy expectation(-ted), hope, live, thing that I long for.', 'from 6960; (compare 6961)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2339>', 'opaque', 'heb', 'חוּט', '["chûwṭ"]', '["[the] thread of"]', '["n-m"]', 'a string; by implication, a measuring tape cord, fillet, line, thread.', 'from an unused root probably meaning to sew;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2474}/[H2474]', 'inflected', 'heb', 'חַלּוֹן', '["challôwn"]', '["at/ [the] window of","in the/ window"]', '["n"]', 'a window (as perforated) window.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3381}/H9035/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["you let down/ us"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0517}/H9022/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["mother/ your"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251G}/H9022/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["[is] brother/ your","brother/ your","brothers/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1817C}/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["from/ [the] doors of"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9022/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["house/ your","houses/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7218A>/H9025', 'inflected', 'heb', 'בראשינו', '["be./ra.Shei./nu","be./ro.She./nu","ve./ro.She./nu"]', '["[will be] on/ head/ our","by/ heads/ our","on/ head/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1697G}/H9026/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["according to/ words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H2022G}/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["from/ the/ hill country"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440I}/H9025\/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<from>/ because of/ us"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H7851G}/[H7848]', 'inflected', 'heb', 'שִׁטִּים', '["Shiṭṭîym"]', '["from/ <the>/ Shittim"]', '["n-pr-loc"]', 'Shittim, a place East of the Jordan Shittim.', 'the same as the plural of 7848; acacia trees;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7200G}/H9046/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["when/ see/ you"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4725}/H9026/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["from/ place/ your"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0996G}/H9036/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["between/ you"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0996G}/H9033/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["and/ between/ it"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0505G}/[H504]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["about/ a thousand","about/ two thousand"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8032}\/[H8028]', 'inflected', 'heb', 'שִׁלְשׁוֹם', '["shilshôwm"]', '["three days ago"]', '["adv"]', 'trebly, i.e. (in time) day before yesterday before (that time, -time), excellent things (from the margin), heretofore, three days, time past.', 'or שִׁלְשֹׁם; from the same as 8028;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1431}/H9031/[H1434]', 'inflected', 'heb', 'גָּדַל', '["gâdal"]', '["to make great/ you"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0935G}/H9046/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ come/ you","when/ go/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3383}/[H3381]', 'inflected', 'heb', 'יַרְדֵּן', '["Yardên"]', '["in the/ Jordan"]', '["n-pr"]', 'Jarden, the principal river of Palestine Jordan.', 'from 3381; a descender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5975G}\/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["[were] standing","you will stand still"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H7626H>', 'inflected', 'heb', 'משבטי', '["mi./Sha.vet","mi./shiv.Tei"]', '["from/ [the] tribes of","from/ a tribe"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5975G}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ [is] standing","and/ [who will] stand","and/ he may set up","and/ stand","and/ standing","and/ they made a stand","and/ you may arise","so/ he may set up","so/ he may stand","so/ it may stand","so/ they may stand"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0168G}/H9028/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["from/ tents/ their"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0935G}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ just as/ came"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2881}/[H2881]', 'lemma', 'heb', 'טָבַל', '["ṭâbal"]', '["they were dipped"]', '["v"]', 'to dip, to immerse dip, plunge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1415>/H9023', 'opaque', 'heb', 'גָּדָה', '["gâdâh"]', '["banks/ its"]', '["n-f"]', 'a border of a river (as cut into by the stream) bank.', 'from an unused root (meaning to cut off);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0121H}/[H120]', 'inflected', 'heb', 'אָדָם', '["ʼÂdâm"]', '["from/ Adam"]', '["n-pr-m"]', 'Adam the name of the first man, also of a place in Palestine Adam.', 'the same as 120;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6891}/[H6868]', 'lemma', 'heb', 'צָרְתָן', '["Tsârᵉthân"]', '["Zarethan"]', '["n-pr-loc"]', 'Tsarethan, a place in Palestine Zarthan.', 'perhaps for 6868;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3381}/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["and/ which/ went down"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6160K}/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["the/ Arabah"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3383}\/[H3381]', 'inflected', 'heb', 'יַרְדֵּן', '["Yardên"]', '["the/ Jordan"]', '["n-pr"]', 'Jarden, the principal river of Palestine Jordan.', 'from 3381; a descender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4673}/[H5324]', 'inflected', 'heb', 'מַצָּב', '["matstsâb"]', '["from/ [the] standing-place of"]', '["n-m"]', 'a fixed spot; figuratively, an office, a military post garrison, station, place where...stood.', 'from 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3915}\/[H3883]', 'inflected', 'heb', 'לַיִל', '["layil"]', '["this/ night"]', '["n-m"]', 'properly, a twist (away of the light), i.e. night; figuratively, adversity (mid-)night (season).', 'or (Isaiah 21:11) לֵיל; also לַיְלָה; from the same as 3883;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6240}/[H6235]', 'inflected', 'heb', 'עָשָׂר', '["ʻâsâr"]', '["the/ ten"]', '["n"]', 'ten (only in combination), i.e. -teen; also (ordinal) -teenth (eigh-, fif-, four-, nine-, seven-, six-, thir-) teen(-th), + eleven(-th), + sixscore thousand, + twelve(-th).', 'for 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7592}/H9013/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["they will ask/ !"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5674A}/H9043/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["when/ passed on/ it","when/ passed/ he"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5674C}/H9038/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["and/ he brought through/ them","and/ they took over/ them"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4673}/[H5324]', 'lemma', 'heb', 'מַצָּב', '["matstsâb"]', '["[the] garrison of","[the] standing-place of"]', '["n-m"]', 'a fixed spot; figuratively, an office, a military post garrison, station, place where...stood.', 'from 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0705}/[H702]', 'inflected', 'heb', 'אַרְבָּעִים', '["ʼarbâʻîym"]', '["about/ forty"]', '["n"]', 'forty forty.', 'multiple of 702;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6635H}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["<the>/ war","the/ war"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6160L}/[H6150]', 'lemma', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["[the] desert plain","[the] plains of","a desert plain","desert plain","desert plains"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416E}/H9023\/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["life/ his"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5927G}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["just as/ came up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5423}/[H5423]', 'lemma', 'heb', 'נָתַק', '["nâthaq"]', '["I tore off","I will tear apart","he is torn away","he tore apart","it has been torn apart","it is torn apart","it will be torn apart","let us tear off","they had torn off","they have been separated","they have been snapped","they have been torn apart","they were drawn away","they were drawn out","they will be torn apart","will it pull up","you will tear apart","you will tear out"]', '["v"]', 'to tear off break (off), burst, draw (away), lift up, pluck (away, off), pull (out), root out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2724}/[H2720]', 'inflected', 'heb', 'חָרָבָה', '["chârâbâh"]', '["the/ dry ground"]', '["n-f"]', 'a desert dry (ground, land).', 'feminine of 2720;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1537G}/[H1536]', 'inflected', 'heb', 'גִּלְגָּל', '["Gilgâl"]', '["[is] in <the>/ Gilgal","[was] at <the>/ Gilgal","at <the>/ Gilgal","in <the>/ Gilgal"]', '["n-pr-loc"]', 'Gilgal, the name of three places in Palestine Gilgal. See also 1019.', 'the same as 1536 (with the article as a properly, noun);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121G}/H9026/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["children/ your","descendants/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674A}/H9046/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["had passed over/ you"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440G}/H9025/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ before/ us"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674A}/H9045/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["had passed over/ we"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3117K>\', 'inflected', 'heb', 'הימים ס', '["hai./ya.Mim"]', '["the/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674A}/H9048/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["passing over/ they"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4135B}/[H4135]', 'lemma', 'heb', 'מוּל', '["mûwl"]', '["circumcise","let them be cut off"]', '["v"]', 'to cut short, i.e. curtail (specifically the prepuce, i.e. to circumcise); by implication, to blunt; figuratively, to destroy circumcise(-ing), selves), cut down (in pieces), destroy, × must needs.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1389H}/[H1387]', 'lemma', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["[the] hill of"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6190G}/[H6189]', 'inflected', 'heb', 'עׇרְלָה', '["ʻorlâh"]', '["<the>/ foreskins"]', '["n-f"]', 'the prepuce foreskin, uncircumcised.', 'feminine of 6189;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478I}/H9038/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["in place of/ them","in place/ their"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2421}/H9048\/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["lived/ they"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1556}/[H1556]', 'lemma', 'heb', 'גָּלַל', '["gâlal"]', '["I have rolled away","[was] wallowing","roll","roll away","rolled","they have rolled themselves"]', '["v"]', 'to roll (literally or figuratively) commit, remove, roll (away, down, together), run down, seek occasion, trust, wallow.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1537G}/[H1536]', 'lemma', 'heb', 'גִּלְגָּל', '["Gilgâl"]', '["Gilgal"]', '["n-pr-loc"]', 'Gilgal, the name of three places in Palestine Gilgal. See also 1019.', 'the same as 1536 (with the article as a properly, noun);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6160L}/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["at/ [the] desert plains of","in the/ clouds","in the/ desert plain","in/ [the] desert plains of","in/ [the] plains of","on/ [the] plains of"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5669}/[H5668]', 'inflected', 'heb', 'עָבוּר', '["ʻâbûwr"]', '["some of/ [the] produce of"]', '["n-m"]', 'passed, i.e. kept over; used only of stored grain old corn.', 'the same as 5668;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7033}/[H7034]', 'inflected', 'heb', 'קָלָה', '["qâlâh"]', '["and/ roasted [grain]"]', '["v"]', 'to toast, i.e. scorch partially or slowly dried, loathsome, parch, roast.', 'a primitive root (rather identical with 7034 through the idea of shrinkage by heat);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8393}/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["some of/ [the] produce of"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1931}\/[H1931]', 'inflected', 'heb', 'הוּא', '["hûwʼ"]', '["<the>/ that"]', '["p"]', 'he (she or it); only expressed when emphatic or without a verb; also (intensively) self, or (especially with the article) the same; sometimes (as demonstrative) this or that; occasionally (instead of copula) as or are he, as for her, him(-self), it, the same, she (herself), such, that (...it), these, they, this, those, which (is), who.', 'of which the feminine (beyond the Pentateuch) is הִיא; he a primitive word, the third person pronoun singular;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3405G}/[H3394]', 'inflected', 'heb', 'יְרִיחוֹ', '["Yᵉrîychôw"]', '["<on>/ Jericho","[were] at/ Jericho","at/ Jericho","in/ Jericho"]', '["n-pr-loc"]', 'Jericho or Jerecho, a place in Palestine Jericho.', 'or יְרֵחוֹ; or variation (1 Kings 16:34) יְרִיחֹה; perhaps from 3394; its month; or else from 7306; fragrant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5048}/H9033/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["to/ before/ him"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H9035}', 'inflected', 'heb', 'הלנו', '["ha./La./nu"]', '["¿/ for <the>/ us"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6862C}/H9025/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["for/ foes/ our"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3405G}/[H3394]', 'inflected', 'heb', 'יְרִיחוֹ', '["Yᵉrîychôw"]', '["and/ Jericho"]', '["n-pr-loc"]', 'Jericho or Jerecho, a place in Palestine Jericho.', 'or יְרֵחוֹ; or variation (1 Kings 16:34) יְרִיחֹה; perhaps from 3394; its month; or else from 7306; fragrant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5462}/[H5462]', 'inflected', 'heb', 'סָגַר', '["çâgar"]', '["and/ he may shut up","and/ lance","and/ let us close","and/ shut","and/ shut up","so/ he may shut"]', '["v"]', 'to shut up; figuratively, to surrender close up, deliver (up), give over (up), inclose, × pure, repair, shut (in, self, out, up, up together), stop, × straitly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}\/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["[it is] coming","[was one] coming","he came","it came"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428G}/H9024/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["[is] king/ its","king/ its","kings/ its"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7782}/[H8231]', 'inflected', 'heb', 'שׁוֹפָר', '["shôwphâr"]', '["on the/ ram''s horn","on the/ trumpet","on the/ trumpets","on/ a trumpet"]', '["n-m"]', 'a cornet (as giving a clear sound) or curved horn cornet, trumpet.', 'or שֹׁפָר; from 8231 in the original sense of incising;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7161A}/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["on/ [the] horn of","on/ [the] horns of","on/ a horn of"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5048}/H9033/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["before/ him","before/ himself","before/ it","before/ itself"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5437H}/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["and/ I go around","and/ I will go around","and/ go round","and/ let us surround [them]","so/ they may go around"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2502B}/[H2502]', 'inflected', 'heb', 'חָלַץ', '["châlats"]', '["and/ the/ armed [man]"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0559}/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["when/ had said"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8628}/[H8628]', 'inflected', 'heb', 'תָּקַע', '["tâqaʻ"]', '["and/ [was] giving a blast","and/ giving blasts","and/ they gave a blast"]', '["v"]', 'to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0622}/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["and/ the/ rearguard"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963A>/H9026', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["voice/ your"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0559}/H9040/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["say/ I","to say/ I"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4264}\/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["in the/ camp"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5927L}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["just as/ came up","when/ came up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7535}/[H7534]', 'inflected', 'heb', 'רַק', '["raq"]', '["and/ only"]', '["adv"]', 'properly, leanness, i.e. (figuratively) limitation; only adverbial, merely, or conjunctional, although but, even, except, howbeit howsoever, at the least, nevertheless, nothing but, notwithstanding, only, save, so (that), surely, yet (so), in any wise.', 'the same as 7534 as a noun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2764A}/[H2763]', 'inflected', 'heb', 'חֵרֶם', '["chêrem"]', '["<into>/ a devoted thing","into/ a devoted thing","to <the>/ total destruction"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5916}/[H5916]', 'inflected', 'heb', 'עָכַר', '["ʻâkar"]', '["and/ you will trouble"]', '["v"]', 'properly, to roil water; figuratively, to disturb or affict trouble, stir.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0214}/[H686]', 'lemma', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["[the] storehouses of","[the] storerooms","[the] treasures of","[the] treasury of","treasure","treasures","treasures of"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478J}/H9034/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["in place/ its"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8147}/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["and/ to/ two"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7270}/[H7272]', 'inflected', 'heb', 'רָגַל', '["râgal"]', '["who/ had spied out"]', '["v"]', 'to walk along; but only in specifically, applications, to reconnoiter, to be a tale-bearer (i.e. slander); to lead about backbite, search, slander, (e-) spy (out), teach to go, view.', 'a primitive root; also as denominative from 7272');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0834D}/[H834]', 'lemma', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["[one] who"]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4940}/H9024/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["famili<es>/ her"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H2091>', 'inflected', 'heb', 'והזהב', '["ve./ha./za.Hav"]', '["and/ the/ gold"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1270}/[H1269]', 'inflected', 'heb', 'בַּרְזֶל', '["barzel"]', '["and/ <the>/ iron"]', '["n-m"]', 'iron (as cutting); by extension, an iron implement (ax) head, iron.', 'perhaps from the root of 1269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1060}/H9023/[H1069]', 'inflected', 'heb', 'בְּכוֹר', '["bᵉkôwr"]', '["with/ firstborn/ his"]', '["n-m"]', 'first-born; hence, chief eldest (son), firstborn(-ling).', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3245}/H9034/[H3245]', 'inflected', 'heb', 'יָסַד', '["yâçad"]', '["[which] he founded/ it","he founded/ it","he has founds/ it","he will found/ it","it allocated/ it"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6810}/H9023/[H6819]', 'inflected', 'heb', 'צָעִיר', '["tsâʻîyr"]', '["and/ with/ young [son]/ his"]', '["a"]', 'little; (in number) few; (in age) young, (in value) ignoble least, little (one), small (one), young(-er, -est).', 'or צָעוֹר; from 6819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1817C}/H9024/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["gates/ its"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8089}/H9023/[H8085]', 'inflected', 'heb', 'שֹׁמַע', '["shômaʻ"]', '["[the] report of/ him","[the] report of/ it"]', '["n-m"]', 'a report fame.', 'from 8085;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2764A}/[H2763]', 'inflected', 'heb', 'חֵרֶם', '["chêrem"]', '["in the/ devoted thing[s]","with the/ devoted thing[s]"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5912>', 'opaque', 'heb', 'עָכָן', '["ʻÂkân"]', '["Achan"]', '["n-pr-m"]', 'Akan, an Israelite Achan. Compare 5917.', 'from an unused root meaning to trouble; troublesome;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3756H}/[H3754]', 'lemma', 'heb', 'כַּרְמִי', '["Karmîy"]', '["Carmi"]', '["n-pr-m"]', 'Karmi, the name of three Israelites Carmi.', 'from 3754; gardener;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2067G}/[H2065]', 'lemma', 'heb', 'זַבְדִּי', '["Zabdîy"]', '["Zabdi"]', '["n-pr-m"]', 'Zabdi, the name of four Israelites Zabdi.', 'from 2065; giving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2226I}/[H2225]', 'lemma', 'heb', 'זֶרַח', '["Zerach"]', '["Zerah"]', '["n-pr-m"]', 'Zerach, the name of three Israelites, also of an Idumaean and an Ethiopian prince Zarah, Zerah.', 'the same as 2225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3405G}/[H3394]', 'inflected', 'heb', 'יְרִיחוֹ', '["Yᵉrîychôw"]', '["from/ Jericho"]', '["n-pr-loc"]', 'Jericho or Jerecho, a place in Palestine Jericho.', 'or יְרֵחוֹ; or variation (1 Kings 16:34) יְרִיחֹה; perhaps from 3394; its month; or else from 7306; fragrant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1007}/[H1004]', 'lemma', 'heb', 'בֵּית אָוֶן', '["Bêyth ʼÂven"]', '["Aven","Beth"]', '["n-pr-loc"]', 'Beth-Aven, a place in Palestine Beth-aven.', 'from 1004 and 205; house of vanity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7270}/[H7272]', 'inflected', 'heb', 'רָגַל', '["râgal"]', '["and/ spy out"]', '["v"]', 'to walk along; but only in specifically, applications, to reconnoiter, to be a tale-bearer (i.e. slander); to lead about backbite, search, slander, (e-) spy (out), teach to go, view.', 'a primitive root; also as denominative from 7272');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3021}/[H3021]', 'lemma', 'heb', 'יָגַע', '["yâgaʻ"]', '["I am weary","I have become weary","I have labored","did we weary [him]","he becomes weary","it was weary","they will become weary","they will labor","we have become weary","will I labor","you became weary","you had labored","you have grown weary","you have labored","you have wearied","you labor","you make go wearily"]', '["v"]', 'properly, to gasp; hence, to be exhausted, to tire, to toil faint, (make to) labour, (be) weary.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7970}/[H7969]', 'inflected', 'heb', 'שְׁלוֹשִׁים', '["shᵉlôwshîym"]', '["[were] about/ thirty","about/ thirty"]', '["n-m"]', 'thirty; or (ordinal) thirtieth thirty, thirtieth. Compare 7991.', 'or שְׁלֹשִׁים; multiple of 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7671}/[H7667]', 'inflected', 'heb', 'שְׁבָרִים', '["Shᵉbârîym"]', '["<the>/ Shebarim"]', '["n-pr-loc"]', 'Shebarim, a place in Palestine Shebarim.', 'plural of 7667; ruins;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4174}/[H3381]', 'inflected', 'heb', 'מוֹרָד', '["môwrâd"]', '["[were] at/ [the] descent of","at the/ descent","on/ [the] descent of","on/ a slope"]', '["n-m"]', 'a descent; as architecture, an ornamental appendage, perhaps a festoon going down, steep place, thin work.', 'from 3381;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218A>/H9028', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ their","heads/ their","own head/ their"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0162}/[H162]', 'lemma', 'heb', 'אֲהָהּ', '["ʼăhâhh"]', '["alas!"]', '["inj"]', 'Oh! ah, alas.', 'apparently a primitive word expressing pain exclamatorily;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0006}/H9035/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["to/ destroy/ us"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8034}/H9025/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["name/ our"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8034}/H9021/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["<to>/ name/ your","[is] for/ name/ your","for/ name/ your","to/ name/ your"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1419A}\/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["<the>/ great"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3627}/H9028/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["among/ things/ their"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7130G}/H9026/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["from/ midst/ your"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5493G}/H9046/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["remove/ you"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7626H>', 'inflected', 'heb', 'השבטים', '["ha./She.vet","ha./she.Vet","ha./she.va.Tim"]', '["the/ tribe","the/ tribes"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3920}/H9033/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["he will take/ it","may it catch/ him","they will seize/ him"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4940}/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["and/ the/ family"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3920}/H9034/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["he will take/ it"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1004M}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ the/ household"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1397}/[H1396]', 'inflected', 'heb', 'גֶּבֶר', '["geber"]', '["for <the>/ man","for/ a man","to the/ men","to/ a man","to/ men"]', '["n-m"]', 'properly, a valiant man or warrior; generally, a person simply every one, man, × mighty.', 'from 1396;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3920}/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["the/ [one who] is taken by lot"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H2063}/[H2088]', 'inflected', 'heb', 'זֹאת', '["zôʼth"]', '["and/ like/ this"]', '["d"]', 'this (often used adverb) hereby (-in, -with), it, likewise, the one (other, same), she, so (much), such (deed), that, therefore, these, this (thing), thus.', 'irregular feminine of 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7998}/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["among the/ booty"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0155}/[H117]', 'lemma', 'heb', 'אַדֶּרֶת', '["ʼaddereth"]', '["<the> cloak of","[the] cloak of","a cloak of"]', '["n-f"]', 'something ample (as a large vine, a wide dress) garment, glory, goodly, mantle, robe.', 'feminine of 117; ; also the same as 145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3956I}/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["and/ a wedge of"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2530A}/H9038/[H2530]', 'inflected', 'heb', 'חָמַד', '["châmad"]', '["and/ I desired/ them"]', '["v"]', 'to delight in beauty, greatly beloved, covet, delectable thing, (× great) delight, desire, goodly, lust, (be) pleasant (thing), precious (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2009}/H9048/[H2005]', 'inflected', 'heb', 'הִנֵּה', '["hinnêh"]', '["and/ here/ they","and/ there/ they"]', '["dp"]', 'lo! behold, lo, see.', 'prolongation for 2005;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0776H>', 'inflected', 'heb', 'בארץ', '["ba./''A.retz","be./''E.retz","va./''A.retz"]', '["<in> the/ earth","in the/ ground","in the/ land","in/ a land of","on the/ ground","on the/ land"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0168G}/H9020/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["<the>/ tent/ my"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3701G}/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["and/ <the>/ money","and/ <the>/ silver","and/ the/ silver"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478G}/H9034/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["[is] under/ it","[was] under/ it","[were] under/ it","under/ it"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3332I}/H9038/[H3332]', 'inflected', 'heb', 'יָצַק', '["yâtsaq"]', '["and/ they poured out/ them"]', '["v"]', 'properly, to pour out (transitive or intransitive); by implication, to melt or cast as metal; by extension, to place firmly, to stiffen or grow hard cast, cleave fast, be (as) firm, grow, be hard, lay out, molten, overflow, pour (out), run out, set down, stedfast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0155}/[H117]', 'inflected', 'heb', 'אַדֶּרֶת', '["ʼaddereth"]', '["the/ cloak"]', '["n-f"]', 'something ample (as a large vine, a wide dress) garment, glory, goodly, mantle, robe.', 'feminine of 117; ; also the same as 145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956I}/[H3960]', 'lemma', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["[the] bay of","[the] tongue of","[the] wedge of"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6010G}/[H6009]', 'lemma', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["[the] valley of"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5911}/[H5916]', 'lemma', 'heb', 'עָכוֹר', '["ʻÂkôwr"]', '["Achor"]', '["n-m"]', 'Akor, the name of a place in Palestine Achor.', 'from 5916; troubled;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5916}/H9035/[H5916]', 'inflected', 'heb', 'עָכַר', '["ʻâkar"]', '["have you brought trouble to/ us"]', '["v"]', 'properly, to roil water; figuratively, to disturb or affict trouble, stir.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5916}/H9031/[H5916]', 'inflected', 'heb', 'עָכַר', '["ʻâkar"]', '["he will bring trouble to/ you"]', '["v"]', 'properly, to roil water; figuratively, to disturb or affict trouble, stir.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5857G}/[H5856]', 'inflected', 'heb', 'עַי', '["ʻAy"]', '["<to>/ Ai","of <the>/ Ai","to <the>/ Ai"]', '["n-pr-loc"]', 'Ai, Aja or Ajath, a place in Palestine Ai, Aija, Aijath, Hai.', 'or (feminine) עַיָּא; (Nehemiah 11:31), or עַיָּת; (Isaiah 10:28), for 5856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4428G}/H9024/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["and/ to/ king/ its"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3405G}/[H3394]', 'inflected', 'heb', 'יְרִיחוֹ', '["Yᵉrîychôw"]', '["to/ Jericho"]', '["n-pr-loc"]', 'Jericho or Jerecho, a place in Palestine Jericho.', 'or יְרֵחוֹ; or variation (1 Kings 16:34) יְרִיחֹה; perhaps from 3394; its month; or else from 7306; fragrant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0929>/H9024', 'inflected', 'heb', 'ובהמתה', '["u./ve.hem.Ta/h"]', '["and/ livestock/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0693}/[H693]', 'lemma', 'heb', 'אָרַב', '["ʼârab"]', '["I have lain in wait","[are] lying in wait","[are] to lie in wait for","ambushers","an ambush","he lies in wait","let us lie in wait","lying in wait","she lies in wait","they lay in wait","they lie in wait","you lie in wait"]', '["v"]', 'to lurk (lie in) ambush(-ment), lay (lie in) wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0310A}/H9034/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["<from>/ behind/ it"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7223H}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["at the/ first [time]","at the/ former [time]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5423}/H9045/[H5423]', 'inflected', 'heb', 'נָתַק', '["nâthaq"]', '["have drawn out/ we"]', '["v"]', 'to tear off break (off), burst, draw (away), lift up, pluck (away, off), pull (out), root out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H0693}/[H693]', 'inflected', 'heb', 'אָרַב', '["ʼârab"]', '["from/ the/ ambush"]', '["v"]', 'to lurk (lie in) ambush(-ment), lay (lie in) wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8610}/H9046/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["when/ have captured/ you"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3341}/[H3341]', 'lemma', 'heb', 'יָצַת', '["yâtsath"]', '["[am] about to kindle","has it become desolate?","have they set on fire","he has kindled","it has been kindled","they are burnt","they are left desolate","they have been burned","they will be kindled","they will be set on fire","you will set on fire"]', '["v"]', 'to burn or set on fire; figuratively, to desolate burn (up), be desolate, set (on) fire (fire), kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3993}/[H693]', 'inflected', 'heb', 'מַאֲרָב', '["maʼărâb"]', '["the/ ambush"]', '["n-m"]', 'an ambuscade lie in ambush, ambushment, lurking place, lying in wait.', 'from 693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5971K}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["the/ people","the/ people of"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0935I}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ they came","and/ you will come"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6828G}/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["[is] from/ [the] north","[was] from/ [the] north","[were] from/ [the] north","from/ [the] north","from/ [the] north of","from/ north"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1516R}/[H1466]', 'inflected', 'heb', 'גַּיְא', '["gayʼ"]', '["and/ the/ valley"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2568}/[H2568]', 'inflected', 'heb', 'חָמֵשׁ', '["châmêsh"]', '["about/ fif-","about/ five"]', '["n"]', 'five fif(-teen), fifth, five (× apiece).', 'masculine חֲמִשָּׁה; a primitive numeral;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6119}/H9023/[H6117]', 'inflected', 'heb', 'עָקֵב', '["ʻâqêb"]', '["rearguard/ its"]', '["n-m"]', 'a heel (as protuberant); hence, a track; figuratively, the rear (of an army) heel, (horse-) hoof, last, lier in wait (by mistake for 6120), (foot-) step.', 'or (feminine) עִקְּבָה; from 6117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6010R}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["the/ valley","the/ valley of","the/ valleys"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5857G}/[H5856]', 'inflected', 'heb', 'עַי', '["ʻAy"]', '["[was] in <the>/ Ai","in <the>/ Ai"]', '["n-pr-loc"]', 'Ai, Aja or Ajath, a place in Palestine Ai, Aija, Aijath, Hai.', 'or (feminine) עַיָּא; (Nehemiah 11:31), or עַיָּת; (Isaiah 10:28), for 5856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7291}/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["to/ pursue"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5423}/[H5423]', 'inflected', 'heb', 'נָתַק', '["nâthaq"]', '["and/ he tore apart","and/ they were drawn out"]', '["v"]', 'to tear off break (off), burst, draw (away), lift up, pluck (away, off), pull (out), root out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1008G}/[H1004]', 'inflected', 'heb', 'בֵּית־אֵל', '["Bêyth-ʼÊl"]', '["and/ Beth-"]', '["n-pr-loc"]', 'Beth-El, a place in Palestine Beth-el.', 'from 1004 and 410; house of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3591}/[H3589]', 'inflected', 'heb', 'כִּידוֹן', '["kîydôwn"]', '["with the/ javelin"]', '["n-m"]', 'properly, something to strike with, i.e. a dart lance, shield, spear, target.', 'from the same as 3589; (perhaps smaller than 2595)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0693}/[H693]', 'inflected', 'heb', 'אָרַב', '["ʼârab"]', '["and/ the/ ambush","and/ the/ ambusher"]', '["v"]', 'to lurk (lie in) ambush(-ment), lay (lie in) wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5186}/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["when/ stretched out"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3341}/[H3341]', 'inflected', 'heb', 'יָצַת', '["yâtsath"]', '["and/ I will kindle","and/ he has kindled","and/ it has kindled","and/ it will be kindled","and/ it will be made desolate","and/ they set on fire","and/ they will set on fire"]', '["v"]', 'to burn or set on fire; figuratively, to desolate burn (up), be desolate, set (on) fire (fire), kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200I}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ they saw"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2008}/[H2004]', 'inflected', 'heb', 'הֵנָּה', '["hênnâh"]', '["and/ hither","and/ them"]', '["adv"]', 'hither or thither (but used both of place and time) here, hither(-to), now, on this (that) side, since, this (that) way, thitherward, thus far, to...fro, yet.', 'from 2004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5127}/[H5127]', 'inflected', 'heb', 'נוּס', '["nûwç"]', '["the/ [one who] flees","which/ was fleeing"]', '["v"]', 'to flit, i.e. vanish away (subside, escape; causatively, chase, impel, deliver) × abate, away, be displayed, (make to) flee (away, -ing), put to flight, × hide, lift up a standard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0693}/[H693]', 'inflected', 'heb', 'אָרַב', '["ʼârab"]', '["the/ ambush","the/ ambusher","the/ ambushers"]', '["v"]', 'to lurk (lie in) ambush(-ment), lay (lie in) wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6412A}/[H6403]', 'inflected', 'heb', 'פָּלִיט', '["pâlîyṭ"]', '["and/ a fugitive","and/ an escapee","and/ escapees of"]', '["n-m"]', 'a refugee (that have) escape(-d, -th), fugitive.', 'or פָּלֵיט; or פָּלֵט; from 6403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7291}/H9038/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["he pursues/ them","pursuers/ their","pursuing/ them","they had pursued/ them","you will pursue/ them"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5307J}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["those/ [who] fell"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760A}/H9034/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ I will make/ her","and/ I will make/ it","and/ he made/ it","and/ he will make/ it"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0935N}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ just as/ went"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3789}/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["according to <the>/ [what] is written"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440H}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before","to the/ face"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2205G}/H9023/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["and/ elders/ his","and/ elders/ its"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8199}/H9033/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["and/ judges/ its"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0727}/[H717]', 'inflected', 'heb', 'אָרוֹן', '["ʼârôwn"]', '["for the/ ark","for/ [the] ark of","of the/ ark","to the/ chest","to/ [the] ark of"]', '["n-m"]', 'a box ark, chest, coffin.', 'or אָרֹן; from 717 (in the sense of gathering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2677}/H9023/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["and/ <the>/ half of/ it"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130G}/H9028\/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["in/ midst/ their"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2348>', 'opaque', 'heb', 'חוֹף', '["chôwph"]', '["[the] coast of"]', '["n-m"]', 'a cove (as a sheltered bay) coast (of the sea), haven, shore, (sea-) side.', 'from an unused root meaning to cover;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3844G}/[H3825]', 'inflected', 'heb', 'לְבָנוֹן', '["Lᵉbânôwn"]', '["<the>/ Lebanon"]', '["n-pr-loc"]', 'Lebanon, a mountain range in Palestine Lebanon.', 'from 3825; (the) white mountain (from its snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1391}/[H1387]', 'lemma', 'heb', 'גִּבְעוֹן', '["Gibʻôwn"]', '["Gibeon","[were] Gibeon"]', '["n-pr-loc"]', 'Gibon, a place in Palestine Gibeon.', 'from the same as 1387; hilly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5857G}/[H5856]', 'inflected', 'heb', 'עַי', '["ʻAy"]', '["and/ to <the>/ Ai"]', '["n-pr-loc"]', 'Ai, Aja or Ajath, a place in Palestine Ai, Aija, Aijath, Hai.', 'or (feminine) עַיָּא; (Nehemiah 11:31), or עַיָּת; (Isaiah 10:28), for 5856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6737}/[H6735]', 'inflected', 'heb', 'צָיַר', '["tsâyar"]', '["and/ they acted as ambassadors"]', '["v"]', 'to make an errand, i.e. betake oneself make as if...had been ambassador.', 'a denominative from 6735 in the sense of ambassador;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1087}/[H1086]', 'lemma', 'heb', 'בָּלֶה', '["bâleh"]', '["worn out"]', '["a"]', 'worn out old.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4997>', 'inflected', 'heb', 'ונאדות', '["ve./Nod","ve./no.Dot"]', '["and/ a skin-bottle of","and/ skin-bottles of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1234}/[H1234]', 'inflected', 'heb', 'בָּקַע', '["bâqaʻ"]', '["and/ [who] breaks up","and/ split"]', '["v"]', 'to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6887B}/[H6887]', 'inflected', 'heb', 'צָרַר', '["tsârar"]', '["and/ tied up"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5275}/[H5274]', 'inflected', 'heb', 'נַעַל', '["naʻal"]', '["and/ sandals"]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8008}/[H8071]', 'inflected', 'heb', 'שַׂלְמָה', '["salmâh"]', '["and/ garments"]', '["n-f"]', 'a dress clothes, garment, raiment.', 'transp. for 8071;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6718B}/H9028/[H6679]', 'inflected', 'heb', 'צַיִד', '["tsayid"]', '["provision[s]/ their"]', '["n-m"]', 'the chase; also game (thus taken) × catcheth, food, × hunter, (that which he took in) hunting, venison, victuals.', 'from a form of 6679 and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5350}/[H5348]', 'lemma', 'heb', 'נִקֻּד', '["niqqud"]', '["crumbs"]', '["n-m"]', 'a crumb (as broken to spots); also a biscuit (as pricked) cracknel, mouldy.', 'from the same as 5348;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0370}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["and/ from/ where?"]', '["adv"]', 'where? (only in connection with prepositional prefix, whence) whence, where.', 'probably identical with 369 in the sense of query (compare 336)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2205G}/H9025/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["elders/ our"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776G>/H9025', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["land/ our"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2525}/[H2552]', 'lemma', 'heb', 'חָם', '["châm"]', '["[are] hot","warm"]', '["a"]', 'hot hot, warm.', 'from 2552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6679B}/[H6718]', 'lemma', 'heb', 'צוּד', '["tsûwd"]', '["we took as our provisions"]', '["v"]', 'to lie alongside (i.e. in wait); by implication, to catch an animal (figuratively, men); to victual (for a journey) chase, hunt, sore, take (provision).', 'a primitive root; also denominative from 6718');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004B}/H9025/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ homes/ our"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318G}/H9045/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["came out/ we"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1980H}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["to/ come"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4997>', 'opaque', 'heb', 'נֹאד', '["nôʼd"]', '["[the] skin-bottle of","[the] skin-bottles of"]', '["n-m"]', 'a (skin or leather) bag (for fluids) bottle.', 'or נאוֹדlemma נֹאוד vowel, corrected to נאוֹדxlit nôʼwd corrected to nʼôwd; also (feminine) נֹאדָה; from an unused root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8008}/H9025/[H8071]', 'inflected', 'heb', 'שַׂלְמָה', '["salmâh"]', '["garments/ our"]', '["n-f"]', 'a dress clothes, garment, raiment.', 'transp. for 8071;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5275}/H9025/[H5274]', 'inflected', 'heb', 'נַעַל', '["naʻal"]', '["and/ sandals/ our"]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6718B}/H9028/[H6679]', 'inflected', 'heb', 'צַיִד', '["tsayid"]', '["some of/ provision[s]/ their"]', '["n-m"]', 'the chase; also game (thus taken) × catcheth, food, × hunter, (that which he took in) hunting, venison, victuals.', 'from a form of 6679 and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2421}/H9038/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["to/ let live/ them"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7130G}/H9023/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["and/ in/ inner being/ his","and/ in/ midst/ his"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5892B}/H9028/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["and/ cities/ their"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3716}/[H3715]', 'inflected', 'heb', 'כְּפִירָה', '["Kᵉphîyrâh"]', '["and/ <the>/ Kephirah"]', '["n-pr-loc"]', 'Kephirah, a place in Palestine Chephirah.', 'feminine of 3715; the village (always with the art.);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0881G}/[H875]', 'inflected', 'heb', 'בְּאֵרוֹת', '["Bᵉʼêrôwth"]', '["and/ Beeroth"]', '["n-pr-loc"]', 'Beeroth, a place in Palestine Beeroth.', 'feminine plural of 875; wells;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7157}/[H7151]', 'inflected', 'heb', 'קִרְיַת יְעָרִים', '["Qiryath Yᵉʻârîym"]', '["and/ Kiriath"]', '["n-pr-loc"]', 'Kirjath-Jearim or Kirjath-Arim, a place in Palestine Kirjath, Kirjath-jearim, Kirjath-arim.', 'or (Jeremiah 26:20) with the article interposed; or (Joshua 18:28) simply the former part of the word; or קִרְיַת עָרִים; from 7151 and the plural of 3293 or 5892; city of forests, or city of towns;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7157}/[H7151]', 'lemma', 'heb', 'קִרְיַת יְעָרִים', '["Qiryath Yᵉʻârîym"]', '["Arim","Jearim","Kiriath","[is] Kiriath"]', '["n-pr-loc"]', 'Kirjath-Jearim or Kirjath-Arim, a place in Palestine Kirjath, Kirjath-jearim, Kirjath-arim.', 'or (Jeremiah 26:20) with the article interposed; or (Joshua 18:28) simply the former part of the word; or קִרְיַת עָרִים; from 7151 and the plural of 3293 or 5892; city of forests, or city of towns;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5221}/H9038/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["it will attack/ them","it will strike/ them","strike down/ them","they attacked/ them","they defeated/ them"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2404}/[H2404]', 'lemma', 'heb', 'חָטַב', '["châṭab"]', '["carved","cutters of","they will cut [it]"]', '["v"]', 'to chop or carve wood cut down, hew(-er), polish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7579}/[H7579]', 'inflected', 'heb', 'שָׁאַב', '["shâʼab"]', '["and/ drawers of"]', '["v"]', 'to bale up water (woman to) draw(-er, water).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7411B}/[H7411]', 'lemma', 'heb', 'רָמָה', '["râmâh"]', '["[who] he deceives","did you deceive"]', '["v"]', 'to hurl; specifically, to shoot; figuratively, to delude or betray (as if causing to fall) beguile, betray, (bow-) man, carry, deceive, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2404}/[H2404]', 'inflected', 'heb', 'חָטַב', '["châṭab"]', '["and/ cutters of"]', '["v"]', 'to chop or carve wood cut down, hew(-er), polish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004Q}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["<to>/ [the] house of","[belonged] to/ [the] house of","for/ [the] house of","of the/ house","of/ [the] house of","to/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5315H}/H9025/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["for/ lives/ our"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3477G}/[H3474]', 'inflected', 'heb', 'יָשָׁר', '["yâshâr"]', '["and/ according to the/ right"]', '["a"]', 'straight (literally or figuratively) convenient, equity, Jasher, just, meet(-est), pleased well right(-eous), straight, (most) upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2026}/H9038/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["I will kill/ them","he killed/ them","it will ruin/ them","they killed/ them","you kill/ them"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414I}/H9038/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will make/ them","and/ he has made/ them","and/ he made/ them","and/ they made/ them"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0977}\/[H977]', 'inflected', 'heb', 'בָּחַר', '["bâchar"]', '["chosen","he will choose","they chose","you chose"]', '["v"]', 'properly, to try, i.e. (by implication) select acceptable, appoint, choose (choice), excellent, join, be rather, require.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0139}/[H113]', 'lemma', 'heb', 'אֲדֹנִי־צֶדֶק', '["ʼĂdônîy-Tsedeq"]', '["Adoni-","Zedek"]', '["n-pr-m"]', 'Adoni-Tsedek, a Canaanitish king Adonizedec.', 'from 113 and 6664; lord of justice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3389}/[H3390]', 'lemma', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["Jerusalem","O Jerusalem","[is it] Jerusalem","[is] Jerusalem","of Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2763A}/H9034/[H2763]', 'inflected', 'heb', 'חָרַם', '["châram"]', '["and/ he had totally destroyed/ it"]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7130G}/H9028/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["[is] in/ inner being/ their","in/ inner being/ their","in/ midst/ their"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0582}/H9024/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["men/ its"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1944>', 'opaque', 'heb', 'הוֹהָם', '["Hôwhâm"]', '["Hoham"]', '["n-pr-m"]', 'Hoham, a Canaanitish king Hoham.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6502}/[H6501]', 'lemma', 'heb', 'פִּרְאָם', '["Pirʼâm"]', '["Piram"]', '["n-pr-m"]', 'Piram, a Canaanite Piram.', 'from 6501; wildly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3412G}/[H7311]', 'lemma', 'heb', 'יַרְמוּת', '["Yarmûwth"]', '["Jarmuth"]', '["n-pr-loc"]', 'Jarmuth, the name of two places in Palestine Jarmuth.', 'from 7311; elevation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3309G}/[H3313]', 'lemma', 'heb', 'יָפִיעַ', '["Yâphîyaʻ"]', '["Japhia"]', '["n-pr-loc n-pr-m"]', 'Japhia, the name of a Canaanite, an Israelite, and a place in Palestine Japhia.', 'from 3313; bright;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3923>', 'opaque', 'heb', 'לָכִישׁ', '["Lâkîysh"]', '["Lachish"]', '["n-pr-loc"]', 'Lakish, a place in Palestine Lachish.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1688H}/[H3810]', 'lemma', 'heb', 'דְּבִיר', '["Dᵉbîyr"]', '["Debir"]', '["n-pr-m n-pr-loc"]', 'Debir, the name of an Amoritish king and of two places in Palestine Debir.', 'or (shortened) דְּבִר; (Joshua 13:26 (but see 3810)), the same as 1687;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5700G}/[H5695]', 'lemma', 'heb', 'עֶגְלוֹן', '["ʻEglôwn"]', '["Eglon"]', '["n-pr-m n-pr-loc"]', 'Eglon, the name of a place in Palestine and of a Moabitish king Eglon.', 'from 5695; vituline;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5826}/H9030/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["and/ help/ me","and/ they will help/ me"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1537G}/H9011/[H1536]', 'inflected', 'heb', 'גִּלְגָּל', '["Gilgâl"]', '["<the>/ Gilgal/ towards"]', '["n-pr-loc"]', 'Gilgal, the name of three places in Palestine Gilgal. See also 1019.', 'the same as 1536 (with the article as a properly, noun);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3467}/H9012/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ save/ !"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5826}/H9035/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["and/ help/ us"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2428G}\/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["<the>/ strength"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1391}/[H1387]', 'inflected', 'heb', 'גִּבְעוֹן', '["Gibʻôwn"]', '["[is] in/ Gibeon","[was] at/ Gibeon","[was] in/ Gibeon","at/ Gibeon","in/ Gibeon"]', '["n-pr-loc"]', 'Gibon, a place in Palestine Gibeon.', 'from the same as 1387; hilly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4608}/[H5927]', 'lemma', 'heb', 'מַעֲלֶה', '["maʻăleh"]', '["[the] ascent of","[the] platform of"]', '["n-m"]', 'an elevation, i.e. (concretely) acclivity or platform; abstractly (the relation or state) a rise or (figuratively) priority ascent, before, chiefest, cliff, that goeth up, going up, hill, mounting up, stairs.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1032G}/[H1004]', 'lemma', 'heb', 'בֵּית חוֹרוֹן', '["Bêyth Chôwrôwn"]', '["Beth","Horon"]', '["n-pr-loc"]', 'Beth-Choron, the name of two adjoining places in Palestine Beth-horon.', 'from 1004 and 2356; house of hollowness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5825}/[H5823]', 'lemma', 'heb', 'עֲזֵקָה', '["ʻĂzêqâh"]', '["Azekah"]', '["n-pr-loc"]', 'Azekah, a place in Palestine Azekah.', 'from 5823; tilled;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4719}/[H5348]', 'lemma', 'heb', 'מַקֵּדָה', '["Maqqêdâh"]', '["Makkedah"]', '["n-pr-loc"]', 'Makkedah, a place in Palestine Makkedah.', 'from the same as 5348 in the denominative sense of herding (compare 5349); fold;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5127}/H9048/[H5127]', 'inflected', 'heb', 'נוּס', '["nûwç"]', '["when/ fled/ they","when/ flee/ they"]', '["v"]', 'to flit, i.e. vanish away (subside, escape; causatively, chase, impel, deliver) × abate, away, be displayed, (make to) flee (away, -ing), put to flight, × hide, lift up a standard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2719}\/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["<on> the/ sword","by the/ sword","with the/ sword"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3394}/[H3391]', 'inflected', 'heb', 'יָרֵחַ', '["yârêach"]', '["and/ O moon","and/ [the] moon","and/ moon"]', '["n-m"]', 'the moon moon. Yrechow. See 3405.', 'from the same as 3391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0357}/[H354]', 'lemma', 'heb', 'אַיָּלוֹן', '["ʼAyâlôwn"]', '["Aijalon"]', '["n-pr-loc"]', 'Ajalon, the name of five places in Palestine Aijalon, Ajalon.', 'from 354; deer-field;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1826A}/[H1724]', 'inflected', 'heb', 'דָּמַם', '["dâmam"]', '["and/ it was still"]', '["v"]', 'to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait.', 'a primitive root (compare 1724, 1820);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3477H}/[H3474]', 'inflected', 'heb', 'יָשָׁר', '["yâshâr"]', '["<the>/ Jashar","the/ Jashar"]', '["a"]', 'straight (literally or figuratively) convenient, equity, Jasher, just, meet(-est), pleased well right(-eous), straight, (most) upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0935K}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["to/ go"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3478}\/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["for/ Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4719}/[H5348]', 'inflected', 'heb', 'מַקֵּדָה', '["Maqqêdâh"]', '["at/ Makkedah"]', '["n-pr-loc"]', 'Makkedah, a place in Palestine Makkedah.', 'from the same as 5348 in the denominative sense of herding (compare 5349); fold;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8104H}/H9038/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["to/ guard/ them"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414K}/H9038/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["he permitted/ them","you permit/ them"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5221}/H9038/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["to/ strike down/ them"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8300}/[H8277]', 'inflected', 'heb', 'שָׂרִיד', '["sârîyd"]', '["and/ the/ survivors"]', '["n-m"]', 'a survivor × alive, left, remain(-ing), remnant, rest.', 'from 8277;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8277}/[H8279]', 'lemma', 'heb', 'שָׂרַד', '["sârad"]', '["they survived"]', '["v"]', 'properly, to puncture, i.e. (figuratively through the idea of slipping out) to escape or survive remain.', 'a primitive root; (compare 8279)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7965I}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["in <the>/ peace","in/ peace","in/ safety"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7101}/[H7096]', 'lemma', 'heb', 'קָצִין', '["qâtsîyn"]', '["O rulers of","[is] commander of","[the] commanders of","a commander","a ruler","a ruler of"]', '["n-m"]', 'a magistrate (as deciding) or other leader captain, guide, prince, ruler. Compare 6278.', 'from 7096 in the sense of determining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6677A}/H9028/[H6696]', 'inflected', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["neck/ their","necks/ their"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4191}/H9038/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ he killed/ them","and/ he put to death/ them"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8518}/H9038/[H8518]', 'inflected', 'heb', 'תָּלָה', '["tâlâh"]', '["and/ he hanged/ them"]', '["v"]', 'to suspend (especially to gibbet) hang (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5221}/H9034/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["and/ he struck/ it","and/ they struck/ it"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4719}/[H5348]', 'inflected', 'heb', 'מַקֵּדָה', '["Maqqêdâh"]', '["from/ Makkedah"]', '["n-pr-loc"]', 'Makkedah, a place in Palestine Makkedah.', 'from the same as 5348 in the denominative sense of herding (compare 5349); fold;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3841H}/[H3839]', 'lemma', 'heb', 'לִבְנָה', '["Libnâh"]', '["Libnah"]', '["n-pr-loc"]', 'Libnah, a place in the Desert and one in Palestine Libnah.', 'the same as 3839;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4428G}/H9024/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["to/ king/ its"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3841H}/[H3839]', 'inflected', 'heb', 'לִבְנָה', '["Libnâh"]', '["from/ Libnah"]', '["n-pr-loc"]', 'Libnah, a place in the Desert and one in Palestine Libnah.', 'the same as 3839;');
