INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3841H}\/[H3839]', 'inflected', 'heb', 'לִבְנָה', '["Libnâh"]', '["to/ Libnah"]', '["n-pr-loc"]', 'Libnah, a place in the Desert and one in Palestine Libnah.', 'the same as 3839;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2036>', 'opaque', 'heb', 'הֹרָם', '["Hôrâm"]', '["Horam"]', '["n-pr-m"]', 'Horam, a Canaanitish king Horam.', 'from an unused root (meaning to tower up); high;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1507}/[H1506]', 'lemma', 'heb', 'גֶּזֶר', '["Gezer"]', '["Gezer"]', '["n-pr-loc"]', 'Gezer, a place in Palestine Gazer, Gezer.', 'the same as 1506;');
