INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1688A}/H9011/[H3810]', 'inflected', 'heb', 'דְּבִיר', '["Dᵉbîyr"]', '["to/ Debir/ <towards>"]', '["n-pr-m n-pr-loc"]', 'Debir, the name of an Amoritish king and of two places in Palestine Debir.', 'or (shortened) דְּבִר; (Joshua 13:26 (but see 3810)), the same as 1687;');
