INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0407}/[H3784]', 'lemma', 'heb', 'אַכְשָׁף', '["ʼAkshâph"]', '["Acshaph"]', '["n-pr-loc"]', 'Acshaph, a place in Palestine Achshaph.', 'from 3784; fascination;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6160G}/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["and/ in the/ Arabah"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3672H}/[H3658]', 'lemma', 'heb', 'כִּנְּרוֹת', '["Kinnᵉrôwth"]', '["Kinnereth"]', '["n-pr-loc"]', 'Kinneroth or Kinnereth, a place in Palestine Chinnereth, Chinneroth, Cinneroth.', 'or כִּנֶּרֶתlemma כִּנֶרֶת missing dagesh, corrected to כִּנֶּרֶת; respectively plural and singular feminine from the same as 3658; perhaps harp-shaped;');
