INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4601R}/[H4600]', 'inflected', 'heb', 'מַעֲכָה', '["Maʻăkâh"]', '["and/ Maacah"]', '["n-pr"]', 'Maakah (or Maakath), the name of a place in Syria, also of a Mesopotamian, of three Israelites, and of four Israelitesses and one Syrian woman Maachah, Maachathites. See also 1038.', 'or מַעֲכָת; (Joshua 13:13), from 4600; depression;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1366H}/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["the/ territory"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4334}/[H3474]', 'inflected', 'heb', 'מִישׁוֹר', '["mîyshôwr"]', '["[are] in the/ plain","in the/ plain","on the/ level ground","on/ level ground","with/ uprightness"]', '["n-m"]', 'a level, i.e. a plain (often used (with the article prefix) as a proper name of certain districts); figuratively, concord; also straightness, i.e. (figuratively) justice (sometimes adverbially, justly) equity, even place, plain, right(-eously), (made) straight, uprightness.', 'or מִישֹׁר; from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1120H}/[H1116]', 'inflected', 'heb', 'בָּמוֹת', '["Bâmôwth"]', '["and/ Bamoth"]', '["n-pr-loc"]', 'Bamoth or Bamoth-Baal, a place East of the Jordan Bamoth, Bamoth-baal.', 'plural of 1116; heights; or (fully) בָּמוֹת בַּעַל; from the same and 1168; heights of Baal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004L}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ Beth"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3096>/H9011', 'inflected', 'heb', 'ויהצה', '["ve./Yah.tza/h"]', '["and/ Jahaz/ <towards>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6932}/[H6923]', 'inflected', 'heb', 'קְדֵמוֹת', '["Qᵉdêmôwth"]', '["and/ Kedemoth"]', '["n-pr-loc"]', 'Kedemoth, a place in eastern Palestine Kedemoth.', 'from 6923; beginnings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4158}/[H3313]', 'inflected', 'heb', 'מוֹפַעַת', '["Môwphaʻath"]', '["and/ Mephaath"]', '["n-pr-loc"]', 'Mophaath or Mephaath, a place in Palestine Mephaath.', '(Jeremiah 48:21) or מֵיפַעַת; or מֵפַעַת; from 3313; illuminative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7156G}/[H7151]', 'inflected', 'heb', 'קִרְיָתַיִם', '["Qiryâthayim"]', '["and/ Kiriathaim"]', '["n-pr-loc"]', 'Kirjathaim, the name of two placed in Palestine Kiriathaim, Kirjathaim.', 'dual of 7151; double city;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7643H}/[H1313]', 'inflected', 'heb', 'שְׂבָם', '["Sᵉbâm"]', '["and/ Sibmah"]', '["n-pr-loc"]', 'Sebam or Sibmah, a place in Moab Shebam, Shibmah, Sibmah.', 'or (feminine) שִׂבְמָה; probably from 1313; spice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6890}/[H6889]', 'inflected', 'heb', 'צֶרֶת הַשַּׁחַר', '["Tsereth hash-Shachar"]', '["and/ Zereth"]', '["n-pr-loc"]', 'Tsereth-hash-Shachar, a place in Palestine Zareth-shahar.', 'from the same as 6889 and 7837 with the article interposed; splendor of the dawn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6890}/[H6889]', 'inflected', 'heb', 'צֶרֶת הַשַּׁחַר', '["Tsereth hash-Shachar"]', '["<the>/ Shahar"]', '["n-pr-loc"]', 'Tsereth-hash-Shachar, a place in Palestine Zareth-shahar.', 'from the same as 6889 and 7837 with the article interposed; splendor of the dawn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1047}/[H1004]', 'inflected', 'heb', 'בֵּית פְּעוֹר', '["Bêyth Pᵉʻôwr"]', '["and/ Beth"]', '["n-pr-loc"]', 'Beth-Peor, a place East of the Jordan Bethpeor.', 'from 1004 and 6465; house of Peor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0798}/[H794]', 'inflected', 'heb', 'אַשְׁדּוֹת הַפִּסְגָּה', '["ʼAshdôwth hap-Piçgâh"]', '["and/ [the] slopes of"]', '["n-pr-loc"]', 'Ashdoth-Pisgah, a place east of the Jordan Ashdoth-pisgah.', 'from the plural of 794 and 6449 with the article interposed; ravines of the Pisgah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1020}/[H1004]', 'inflected', 'heb', 'בֵּית הַיְשִׁימוֹת', '["Bêyth ha-Yshîy-môwth"]', '["and/ Beth"]', '["n-pr-loc"]', 'Beth-ha-Jeshimoth, a town East of the Jordan Beth-jeshimoth.', 'from 1004 and the plural of 3451 with the article interposed; house of the deserts;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5257B}/[H5258]', 'lemma', 'heb', 'נְסִיךְ', '["nᵉçîyk"]', '["[the] princes of","princes of"]', '["n-m"]', 'properly, something poured out, i.e. a libation; also a molten image; by implication, a prince (as anointed) drink offering, duke, prince(-ipal).', 'from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7080}/[H7080]', 'inflected', 'heb', 'קָסַם', '["qâçam"]', '["the/ diviner","those/ [who] divine"]', '["v"]', 'properly, to distribute, i.e. determine by lot or magical scroll; by implication, to divine divine(-r, -ation), prudent, soothsayer, use (divination).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2691B}/H9029\/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["and/ villages/ their"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7237}/[H7227]', 'lemma', 'heb', 'רַבָּה', '["Rabbâh"]', '["Rabbah","Rabbah of"]', '["n-pr-loc"]', 'Rabbah, the name of two places in Palestine, East and West Rabbah, Rabbath.', 'feminine of 7227; great;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2809}/[H2808]', 'inflected', 'heb', 'חֶשְׁבּוֹן', '["Cheshbôwn"]', '["and/ from/ Heshbon"]', '["n-pr-loc"]', 'Cheshbon, a place East of the Jordan Heshbon.', 'the same as 2808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7434}/[H7413]', 'lemma', 'heb', 'רָמַת הַמִּצְפֶּה', '["Râmath ham-Mit-speh"]', '["Ramath"]', '["n-pr-loc"]', 'Ramath-ham-Mitspeh, a place in Palestine Ramath-mizpeh.', 'from 7413 and 4707 with the article interpolated; height of the watch-tower;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7434}/[H7413]', 'inflected', 'heb', 'רָמַת הַמִּצְפֶּה', '["Râmath ham-Mit-speh"]', '["<the>/ Mizpah"]', '["n-pr-loc"]', 'Ramath-ham-Mitspeh, a place in Palestine Ramath-mizpeh.', 'from 7413 and 4707 with the article interpolated; height of the watch-tower;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0993}/[H992]', 'inflected', 'heb', 'בְּטֹנִים', '["Bᵉṭônîym"]', '["and/ Betonim"]', '["n-pr-loc"]', 'Betonim, a place in Palestine Betonim.', 'probably plural from 992; hollows;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4266}/[H4264]', 'inflected', 'heb', 'מַחֲנַיִם', '["Machănayim"]', '["and/ from/ Mahanaim"]', '["n-pr-loc"]', 'Machanajim, a place in Palestine Mahanaim.', 'dual of 4264; double camp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1688B}/[H3810]', 'lemma', 'heb', 'דְּבִיר', '["Dᵉbîyr"]', '["Lo Debar"]', '["n-pr-m n-pr-loc"]', 'Debir, the name of an Amoritish king and of two places in Palestine Debir.', 'or (shortened) דְּבִר; (Joshua 13:26 (but see 3810)), the same as 1687;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6010R}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["and/ in the/ valley"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1027}/[H1004]', 'lemma', 'heb', 'בֵּית הָרָם', '["Bêyth hâ-Râm"]', '["Beth","Haram"]', '["n-pr-loc"]', 'Beth-ha-Ram, a place East of the Jordan Beth-aram.', 'from 1004 and 7311 with the article interposed; house of the height;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1039}/[H1004]', 'inflected', 'heb', 'בֵּית נִמְרָה', '["Bêyth Nimrâh"]', '["and/ Beth"]', '["n-pr-loc"]', 'Beth-Nimrah, a place east of the Jordan Beth-Nimrah. Compare 5247.', 'from 1004 and the feminine of 5246; house of (the) leopard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5523G}/[H5521]', 'inflected', 'heb', 'סֻכּוֹת', '["Çukkôwth"]', '["and/ Succoth"]', '["n-pr-loc"]', 'Succoth, the name of a place in Egypt and of three in Palestine Succoth.', 'or סֻכֹּת; plural of 5521; booths;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6829}/[H6828]', 'inflected', 'heb', 'צָפוֹן', '["Tsâphôwn"]', '["and/ Zaphon"]', '["n-pr-loc"]', 'Tsaphon, a place in Palestine Zaphon.', 'the same as 6828; boreal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2691B}/H9028/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["and/ villages/ their"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366H}/H9028/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["[is] territory/ their","border/ their","territory/ their"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4266}/[H4264]', 'inflected', 'heb', 'מַחֲנַיִם', '["Machănayim"]', '["from/ Mahanaim"]', '["n-pr-loc"]', 'Machanajim, a place in Palestine Mahanaim.', 'dual of 4264; double camp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2333}/[H2332]', 'lemma', 'heb', 'חַוָּה', '["chavvâh"]', '["[the] villages of"]', '["n-f"]', 'by implication, an encampment or village (small) town.', 'properly, the same as 2332 (life-giving, i.e. living-place);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2971H}/[H215]', 'lemma', 'heb', 'יָאִיר', '["Yâʼîyr"]', '["Jair"]', '["n-pr-m"]', 'Jair, the name of four Israelites Jair.', 'from 215; enlightener;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6252H}/[H6251]', 'inflected', 'heb', 'עַשְׁתָּרוֹת', '["ʻAshtârôwth"]', '["and/ Ashtaroth"]', '["n-pr-f"]', 'Ashtaroth, the name of a Sidonian deity, and of a place East of the Jordan Asharoth, Astaroth. See also 1045, 6253, 6255.', 'or עַשְׁתָּרֹת; plural of 6251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H7626H>', 'inflected', 'heb', 'ולשבט', '["u./le./She.vet"]', '["and/ to/ [the] tribe of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3881}/[H3878]', 'inflected', 'heb', 'לֵוִיִּי', '["Lêvîyîy"]', '["and/ <to> the/ Levites","and/ for the/ Levites","and/ of the/ Levites","and/ to the/ Levites"]', '["a"]', 'a Levite or descendant of Levi Leviite.', 'or לֵוִי; patronymically from 3878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4735}/H9028/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["for/ livestock/ their"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7075}/H9028/[H7069]', 'inflected', 'heb', 'קִנְיָן', '["qinyân"]', '["and/ for/ possession[s]/ their"]', '["n-m"]', 'creation, i.e. (concretely) creatures; also acquisition, purchase, wealth getting, goods, × with money, riches, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0182}/H9020/[H181]', 'inflected', 'heb', 'אוֹדוֹת', '["ʼôwdôwth"]', '["causes/ my"]', '["n-f"]', 'turnings (i.e. occasions); (adverb) on account of (be-) cause, concerning, sake.', 'or (shortened) אֹדוֹת (only thus in the plural); from the same as 181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0182}/H9021/[H181]', 'inflected', 'heb', 'אוֹדוֹת', '["ʼôwdôwth"]', '["causes/ your"]', '["n-f"]', 'turnings (i.e. occasions); (adverb) on account of (be-) cause, concerning, sake.', 'or (shortened) אֹדוֹת (only thus in the plural); from the same as 181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6947}/[H6946]', 'inflected', 'heb', 'קָדֵשׁ בַּרְנֵעַ', '["Qâdêsh Barnêaʻ"]', '["at/ Kadesh"]', '["n-pr-loc"]', 'Kadesh-Barnea, a place in the Desert Kadeshbarnea.', 'from the same as 6946 and an otherwise unused word (apparently compounded of a correspondent to 1251 and a derivative of 5128) meaning desert of a fugitive; Kadesh of (the) Wilderness of Wandering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7971G}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["when/ sent"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251I}/H9020/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ brothers/ my"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4529}/[H4529]', 'lemma', 'heb', 'מָסָה', '["mâçâh"]', '["I melt","they melted"]', '["v"]', 'to dissolve make to consume away, (make to) melt, water.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5750}/H9040/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["still/ I"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3581B>/H9020', 'inflected', 'heb', 'ככחי', '["ke./Kho.ch/i"]', '["as/ strength/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H3581B>/H9020', 'inflected', 'heb', 'וככחי', '["u./khe./Kho.ch/i"]', '["and/ as/ strength/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3318G}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ [belonged] to the/ [one who] went out","and/ to/ go out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3612G}/[H3611]', 'inflected', 'heb', 'כָּלֵב', '["Kâlêb"]', '["of/ Caleb","to/ Caleb"]', '["n-pr-m"]', 'Caleb, the name of three Israelites Caleb.', 'perhaps a form of 3611, or else from the same root in the sense of forcible;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6062}/[H6061]', 'inflected', 'heb', 'עֲנָקִי', '["ʻĂnâqîy"]', '["among the/ Anakites"]', '["a"]', 'an Anakite or descendant of Anak Anakim.', 'patronymically from 6061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8486}/[H3225]', 'lemma', 'heb', 'תֵּימָן', '["têymân"]', '["O south wind","[the] south","a south wind"]', '["n-f"]', 'the south (as being on the right hand of a person facing the east) south (side, -ward, wind).', 'or תֵּמָן; denominative from 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3956I}/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["the/ bay"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6437G}/[H6437]', 'inflected', 'heb', 'פָּנָה', '["pânâh"]', '["which/ faces","which/ were facing"]', '["v"]', 'to turn; by implication, to face, i.e. appear, look, etc. appear, at (even-) tide, behold, cast out, come on, × corner, dawning, empty, go away, lie, look, mark, pass away, prepare, regard, (have) respect (to), (re-) turn (aside, away, back, face, self), × right (early).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4608}/[H5927]', 'inflected', 'heb', 'מַעֲלֶה', '["maʻăleh"]', '["of/ [the] ascent of","to/ [the] ascent of"]', '["n-m"]', 'an elevation, i.e. (concretely) acclivity or platform; abstractly (the relation or state) a rise or (figuratively) priority ascent, before, chiefest, cliff, that goeth up, going up, hill, mounting up, stairs.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2696J}/[H2691]', 'lemma', 'heb', 'חֶצְרוֹן', '["Chetsrôwn"]', '["Hezron"]', '["n-pr-m n-pr-loc"]', 'Chetsron, the name of a place in Palestine; also of two Israelites Hezron.', 'from 2691; court-yard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0146G}/H9011/[H142]', 'inflected', 'heb', 'אַדָּר', '["ʼAddâr"]', '["Addar/ towards"]', '["n-pr-m"]', 'Addar, a place in Palestine; also an Israelite Addar.', 'intensive from 142; ample;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7173}/H9011/[H7172]', 'inflected', 'heb', 'קַרְקַע', '["Qarqaʻ"]', '["<the>/ Karka/ towards"]', '["n-pr-loc"]', 'Karka (with the article prefix), a place in Palestine Karkaa.', 'the same as 7172; ground-floor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5158L}/[H5157]', 'lemma', 'heb', 'נַחַל', '["nachal"]', '["[the] wadi of"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3956I}/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["[is] from/ [the] bay of"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1031}/[H1004]', 'lemma', 'heb', 'בֵּית חׇגְלָה', '["Bêyth Choglâh"]', '["Beth","Hoglah"]', '["n-pr-loc"]', 'Beth-Choglah, a place in Palestine Beth-hoglah.', 'from 1004 and the same as 2295; house of a partridge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1026}/[H1004]', 'inflected', 'heb', 'בֵּית הָעֲרָבָה', '["Bêyth hâ-ʻĂrâbâh"]', '["of/ Beth"]', '["n-pr-loc"]', 'Beth-ha-Arabah, a place in Palestine Beth-arabah.', 'from 1004 and 6160 with the article interposed; house of the Desert;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1026}/[H1004]', 'inflected', 'heb', 'בֵּית הָעֲרָבָה', '["Bêyth hâ-ʻĂrâbâh"]', '["<the>/ Arabah"]', '["n-pr-loc"]', 'Beth-ha-Arabah, a place in Palestine Beth-arabah.', 'from 1004 and 6160 with the article interposed; house of the Desert;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0932}/[H931]', 'lemma', 'heb', 'בֹּהַן', '["Bôhan"]', '["Bohan"]', '["n-pr-m"]', 'thumb, Bohan, an Israelite Bohan.', 'an orthographical variation of 931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1688G}/H9011/[H3810]', 'inflected', 'heb', 'דְּבִיר', '["Dᵉbîyr"]', '["Debir/ towards"]', '["n-pr-m n-pr-loc"]', 'Debir, the name of an Amoritish king and of two places in Palestine Debir.', 'or (shortened) דְּבִר; (Joshua 13:26 (but see 3810)), the same as 1687;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6010G}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["from/ [the] valley of"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0131}/[H121]', 'lemma', 'heb', 'אֲדֻמִּים', '["ʼĂdummîym"]', '["Adummim"]', '["n-pr-loc"]', 'Adummim, a pass in Palestine Adummim.', 'plural of 121; red spots;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5158N}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["of the/ wadi","to/ [the] wadi of"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5885}/[H5869]', 'lemma', 'heb', 'עֵין שֶׁמֶשׁ', '["ʻÊyn Shemesh"]', '["En","Shemesh"]', '["n-pr-loc"]', 'En-Shemesh, a place in Palestine Enshemesh.', 'from 5869 and 8121; fountain of the sun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5883}/[H5869]', 'lemma', 'heb', 'עֵין רֹגֵל', '["ʻÊyn Rôgêl"]', '["En","Rogel"]', '["n-pr-loc"]', 'En-Rogel, a place near Jerusalem En-rogel.', 'from 5869 and the active participle of 7270; fountain of a traveller;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1516Q}/[H1466]', 'lemma', 'heb', 'גַּיְא', '["gayʼ"]', '["[the] valley of"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2011H>', 'opaque', 'heb', 'הִנֹּם', '["Hinnôm"]', '["Hinnom","[Ben] Hinnom"]', '["n-pr-loc"]', 'Hinnom, apparently a Jebusite Hinnom.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2983H}/[H2982]', 'inflected', 'heb', 'יְבוּסִי', '["Yᵉbûwçîy"]', '["the/ Jebusite[s]"]', '["n-m"]', 'a Jebusite or inhabitant of Jebus Jebusite(-s).', 'patrial from 2982;');
