INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7497G}/[H7495]', 'lemma', 'heb', 'רָפָא', '["râphâʼ"]', '["Rephaim","[the] Rephaites"]', '["n-pr-m"]', 'a giant giant, Rapha, Rephaim(-s). See also 1051.', 'or רָפָה; from 7495 in the sense of invigorating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8388A}/[H8388]', 'inflected', 'heb', 'תָּאַר', '["tâʼar"]', '["and/ it turns"]', '["v"]', 'to delineate; reflex. to extend be drawn, mark out, (Rimmon-) methoar (by union with 7417).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5318}/[H6605]', 'lemma', 'heb', 'נֶפְתּוֹחַ', '["Nephtôwach"]', '["Nephtoah"]', '["n-pr-loc"]', 'Nephtoach, a place in Palestine Neptoah.', 'from 6605; opened, i.e. a spring;');
