INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1173I}/[H1172]', 'lemma', 'heb', 'בַּעֲלָה', '["Baʻălâh"]', '["Baalah"]', '["n-pr-loc"]', 'Baalah, the name of three places in Palestine Baalah.', 'the same as 1172;');
