INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8165H}/[H8163]', 'lemma', 'heb', 'שֵׂעִיר', '["Sêʻîyr"]', '["Seir"]', '["n-pr"]', 'Seir, a mountain of Idumaea and its aboriginal occupants, also one in Palestine Seir.', 'formed like 8163; rough;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3297}/[H3293]', 'lemma', 'heb', 'יְעָרִים', '["Yᵉʻârîym"]', '["Jearim"]', '["n-pr-loc"]', 'Jearim, a place in Palestine Jearim. Compare 7157.', 'plural of 3293; forests;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6828G}/H9011/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["[is] from/ north/ -ward","from/ north/ -ward"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3693}/[H3688]', 'lemma', 'heb', 'כְּסָלוֹן', '["Kᵉçâlôwn"]', '["[is] Kesalon"]', '["n-pr-loc"]', 'Kesalon, a place in Palestine Chesalon.', 'from 3688; fertile;');
