INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8553G}/[H4487]', 'lemma', 'heb', 'תִּמְנָה', '["Timnâh"]', '["Timnah"]', '["n-pr-loc"]', 'Timnah, the name of two places in Palestine Timnah, Timnath, Thimnathah.', 'from 4487; a portion assigned;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7942}/H9011/[H7943]', 'inflected', 'heb', 'שִׁכְּרוֹן', '["Shikkᵉrôwn"]', '["Shikkeron/ towards"]', '["n-pr-loc"]', 'drunkenness, Shikkeron, a place in Palestine Shicron.', 'for 7943;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1173G}/[H1172]', 'inflected', 'heb', 'בַּעֲלָה', '["Baʻălâh"]', '["<the>/ Baalah"]', '["n-pr-loc"]', 'Baalah, the name of three places in Palestine Baalah.', 'the same as 1172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2995G}/[H1129]', 'lemma', 'heb', 'יַבְנְאֵל', '["Yabnᵉʼêl"]', '["Jabneel"]', '["n-pr-loc"]', 'Jabneel, the name of two places in Palestine Jabneel.', 'from 1129 and 410; built of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3612G}/[H3611]', 'inflected', 'heb', 'כָּלֵב', '["Kâlêb"]', '["and/ to/ Caleb"]', '["n-pr-m"]', 'Caleb, the name of three Israelites Caleb.', 'perhaps a form of 3611, or else from the same root in the sense of forcible;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8526G}/[H8525]', 'lemma', 'heb', 'תַּלְמַי', '["Talmay"]', '["Talmai"]', '["n-pr-m"]', 'Talmai, the name of a Canaanite and a Syrian Talmai.', 'from 8525; ridged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7158}/[H7151]', 'lemma', 'heb', 'קִרְיַת סַנָּה', '["Qiryath Çannâh"]', '["Kiriath","Sannah","Sepher","[was] Kiriath"]', '["n-pr-loc"]', 'Kirjath-Sannah or Kirjath-Sepher, a place in Palestine Kirjath-sannah, Kirjath-sepher.', 'or קִרְיַת סֵפֶר; from 7151 and a simpler feminine from the same as 5577, or (for the latter name) 5612; city of branches, or of a book;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5915G}/[H5914]', 'lemma', 'heb', 'עַכְסָה', '["ʻAkçâh"]', '["Achsah"]', '["n-pr-f"]', 'Aksah, an Israelitess Achsah.', 'feminine of 5914; anklet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6274}/[H6273]', 'lemma', 'heb', 'עׇתְנִיאֵל', '["ʻOthnîyʼêl"]', '["Othniel"]', '["n-pr-m"]', 'Othniel, an Israelite Othniel.', 'from the same as 6273 and 410; force of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7073I>', 'opaque', 'heb', 'קְנַז', '["Qᵉnaz"]', '["Kenaz"]', '["n-pr-m"]', 'Kenaz, the name of an Edomite and of two Israelites Kenaz.', 'probably from an unused root meaning to hunt; hunter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0935G}/H9044/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ came/ she","when/ comes/ it"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5496}/H9033/[H7898]', 'inflected', 'heb', 'סוּת', '["çûwth"]', '["and/ he incited/ him","and/ she incited/ him"]', '["v"]', 'properly, to prick, i.e. (figuratively) stimulate; by implication, to seduce entice, move, persuade, provoke, remove, set on, stir up, take away.', 'perhaps denominative from 7898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7592}/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["by/ asking","by/ asking for","by/ requesting","to/ ask","to/ consult","to/ enquire"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6795}/[H6795]', 'inflected', 'heb', 'צָנַח', '["tsânach"]', '["and/ it went down","and/ she went down"]', '["v"]', 'to alight; (transitive) to cause to descend, i.e. drive down fasten, light (from off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414G}/H9030/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["he has given/ me","you give/ me","you have given to/ me"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1543}/[H1556]', 'lemma', 'heb', 'גֻּלָּה', '["gullâh"]', '["[the] bowl of","[the] bowls of","springs","springs of"]', '["n-f"]', 'a fountain, bowl or globe (all as round) bowl, pommel, spring.', 'feminine from 1556;');
