INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5292A}/H9011/[H5291]', 'inflected', 'heb', 'נַעֲרָה', '["Naʻărâh"]', '["and/ Naarah/ towards"]', '["n-pr-loc n-pr-f"]', 'Naarah, the name of an Israelitess, and of a place in Palestine Naarah, Naarath.', 'the same as 5291;');
