INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1507}/[H1506]', 'inflected', 'heb', 'גֶּזֶר', '["Gezer"]', '["at/ Gezer","in/ Gezer"]', '["n-pr-loc"]', 'Gezer, a place in Palestine Gazer, Gezer.', 'the same as 1506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647I}\/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["laboring"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1568H}/[H1567]', 'inflected', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["<the>/ Gilead"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
