INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2507}/[H2506]', 'lemma', 'heb', 'חֵלֶק', '["Chêleq"]', '["Helek"]', '["n-pr-m"]', 'Chelek, an Israelite Helek.', 'the same as 2506; portion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0844G}/[H840]', 'lemma', 'heb', 'אַשְׂרִיאֵל', '["ʼAsrîyʼêl"]', '["Asriel"]', '["n-pr-m"]', 'Asriel, the name of two Israelites Ashriel, Asriel.', 'an orthographical variation for 840;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7928G}/[H7926]', 'lemma', 'heb', 'שֶׁכֶם', '["Shekem"]', '["Shechem"]', '["n-pr-m"]', 'Shekem, the name of a Hivite and two Israelites Shechem.', 'for 7926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8061}/[H8034]', 'lemma', 'heb', 'שְׁמִידָע', '["Shᵉmîydâʻ"]', '["Shemida"]', '["n-pr-m"]', 'Shemida, an Israelite Shemida, Shemidah.', 'apparently from 8034 and 3045; name of knowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6765}/[H6764]', 'inflected', 'heb', 'צְלׇפְחָד', '["Tsᵉlophchâd"]', '["and/ to/ Zelophehad"]', '["n-pr-m"]', 'Tselophchad, an Israelite Zelophehad.', 'from the same as 6764 and 259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3225H}/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["<the>/ south","the/ south"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5887}/[H5869]', 'lemma', 'heb', 'עֵין תַּפּוּחַ', '["ʻÊyn Tappûwach"]', '["En","Tappuah"]', '["n-pr-loc"]', 'En-Tappuach, a place in Palestine En-tappuah.', 'from 5869 and 8598; fountain of an apple-tree;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8599B}/[H8598]', 'inflected', 'heb', 'תַּפּוּחַ', '["Tappûwach"]', '["and/ Tappuah"]', '["n-pr-m"]', 'Tappuach, the name of two places in Palestine, also of an Israelite Tappuah.', 'the same as 8598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5158A}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["<into>/ a torrent","of the/ wadi","to the/ wadi"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366G}/H9023/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["border/ its"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0836}/[H833]', 'inflected', 'heb', 'אָשֵׁר', '["ʼÂshêr"]', '["and/ <on>/ Asher","and/ in/ Asher"]', '["n-pr"]', 'Asher, a son of Jacob, and the tribe descended from him, with its territory; also a place in Palestine Asher', 'from 833, happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6293}/H9013/[H6293]', 'inflected', 'heb', 'פָּגַע', '["pâgaʻ"]', '["they touch/ !","you should fall/ !"]', '["v"]', 'to impinge, by accident or violence, or (figuratively) by importunity come (betwixt), cause to entreat, fall (upon), make intercession, intercessor, intreat, lay, light (upon), meet (together), pray, reach, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3485G}/[H5375]', 'inflected', 'heb', 'יִשָּׂשכָר', '["Yissâˢkâr"]', '["and/ <on>/ Issachar"]', '["n-pr"]', 'Jissaskar, a son of Jacob Issachar.', '(strictly yis-saws-kawr''); from 5375 and 7939; he will bring a reward;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3485G}/[H5375]', 'inflected', 'heb', 'יִשָּׂשכָר', '["Yissâˢkâr"]', '["in/ Issachar"]', '["n-pr"]', 'Jissaskar, a son of Jacob Issachar.', '(strictly yis-saws-kawr''); from 5375 and 7939; he will bring a reward;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1052}/[H1004]', 'lemma', 'heb', 'בֵּית שְׁאָן', '["Bêyth Shᵉʼân"]', '["Beth","Shan","Shean"]', '["n-pr-loc"]', 'Beth-Shean or Beth-Shan, a place in Palestine Beth-shean, Beth-Shan.', 'or בֵּית שָׁן; from 1004 and 7599; house of ease;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2991}/[H1104]', 'inflected', 'heb', 'יִבְלְעָם', '["Yiblᵉʻâm"]', '["and/ Ibleam"]', '["n-pr-loc"]', 'Jibleam, a place in Palestine Ibleam.', 'from 1104 and 5971; devouring people;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5874}/[H5869]', 'lemma', 'heb', 'עֵין־דֹּאר', '["ʻÊyn-Dôʼr"]', '["-dor","En-"]', '["n-pr-loc"]', 'En-Dor, a place in Palestine En-dor.', 'or עֵין דּוֹר; or עֵין־דֹּר; from 5869 and 1755; fountain of dwelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5316G}/[H5299]', 'inflected', 'heb', 'נֶפֶת', '["nepheth"]', '["<the>/ Napheth"]', '["n-f"]', 'a height country.', 'for 5299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423H}/H9033\/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["he dispossessed/ him","it dispossessed/ him","it dispossessed/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2256M}/[H2254]', 'inflected', 'heb', 'חֶבֶל', '["chebel"]', '["and/ a portion","and/ ropes"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3293A>/H9011', 'inflected', 'heb', 'היערה', '["hai./Ya''.ra/h"]', '["the/ forest/ towards"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7497B}/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["and/ the/ Rephaites"]', '["n-pr-m"]', 'a giant giant, Rapha, Rephaim(-s). See also 1051.', 'or רָפָה; from 7495 in the sense of invigorating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6010M}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["the/ valley"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1052}/[H1004]', 'inflected', 'heb', 'בֵּית שְׁאָן', '["Bêyth Shᵉʼân"]', '["[are] in/ Beth"]', '["n-pr-loc"]', 'Beth-Shean or Beth-Shan, a place in Palestine Beth-shean, Beth-Shan.', 'or בֵּית שָׁן; from 1004 and 7599; house of ease;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6010M}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["[are] in/ [the] valley of","in/ [the] valley of"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3157L}/[H2232]', 'lemma', 'heb', 'יִזְרְעֵאל', '["Yizrᵉʻêʼl"]', '["Jezreel"]', '["n-pr-m n-pr-loc"]', 'Jizreel, the name of two places in Palestine and of two Israelites Jezreel.', 'from 2232 and 410; God will sow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4519G}/[H5382]', 'inflected', 'heb', 'מְנַשֶּׁה', '["Mᵉnashsheh"]', '["and/ to/ Manasseh"]', '["n-pr-m"]', 'Menashsheh, a grandson of Jacob, also the tribe descended from him, and its territory Manasseh.', 'from 5382; causing to forget;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3581B>', 'inflected', 'heb', 'וכח', '["ve./Kho.ach"]', '["and/ [is] strength","and/ strength"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3293A>', 'opaque', 'heb', 'יַעַר', '["yaʻar"]', '["O forest","[is] forest","[the] forest","[the] forest of","a forest","forests"]', '["n-m"]', 'a copse of bushes; hence, a forest; hence, honey in the comb (as hived in trees) (honey-) comb, forest, wood.', 'from an unused root probably meaning to thicken with verdure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1254A}/H9033/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["and/ you will cut down/ it"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7887}/[H7886]', 'lemma', 'heb', 'שִׁילֹה', '["Shîylôh"]', '["Shiloh"]', '["n-pr-loc"]', 'Shiloh, a place in Palestine Shiloh.', 'or שִׁלֹה; or שִׁילוֹ; or שִׁלוֹ; from the same as 7886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3533}/[H3533]', 'lemma', 'heb', 'כָּבַשׁ', '["kâbash"]', '["[are] bringing into bondage","being brought into bondage","he had subdued","he will subdue","it was subdued"]', '["v"]', 'to tread down; hence, negatively, to disregard; positively, to conquer, subjugate, violate bring into bondage, force, keep under, subdue, bring into subjection.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7971G}/H9038/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ he lets loose/ them","so/ I may send/ them"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1980I}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ I will walk about","and/ O walkers","and/ [one who] walks","and/ they have walked","and/ walk","and/ walk about","and/ walkers of","so/ let us walk","so/ they may walk","so/ we may walk"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3384A}/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["and/ I will throw","and/ he shot","and/ they shot arrows"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1410G}/[H1464]', 'inflected', 'heb', 'גָּד', '["Gâd"]', '["and/ Gad"]', '["n-pr-m"]', 'Gad, a son of Jacob, including his tribe and its territory; also a prophet Gad.', 'from 1464;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7205}/[H7200]', 'inflected', 'heb', 'רְאוּבֵן', '["Rᵉʼûwbên"]', '["and/ Reuben"]', '["n-pr-m"]', 'Reuben, a son of Jacob Reuben.', 'from the imperative of 7200 and 1121; see ye a son;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6311}/[H1931]', 'inflected', 'heb', 'פֹּה', '["pôh"]', '["and/ here"]', '["adv"]', 'this place (French ici), i.e. here or hence here, hither, the one (other, this, that) side.', 'or פֹּא; (Job 38:11), or פּוֹ; probably from a primitive inseparable particle ''p'' (of demonstrative force) and 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7887}/[H7886]', 'inflected', 'heb', 'שִׁילֹה', '["Shîylôh"]', '["[is] in/ Shiloh","[was] in/ Shiloh","at/ Shiloh","in/ Shiloh"]', '["n-pr-loc"]', 'Shiloh, a place in Palestine Shiloh.', 'or שִׁלֹה; or שִׁילוֹ; or שִׁלוֹ; from the same as 7886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3789}/H9034/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["and/ they described in writing/ it"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4256}/H9028\/[H2505]', 'inflected', 'heb', 'מַחֲלֹקֶת', '["machălôqeth"]', '["according to/ divisions/ their"]', '["n-f"]', 'a section (of Levites, people or soldiers) company, course, division, portion. See also 5555.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318J}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ it came out","and/ it went out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1486>/H9028', 'opaque', 'heb', 'גּוֹרָל', '["gôwrâl"]', '["lot/ their"]', '["n-m"]', 'properly, a pebble, i.e. a lot (small stones being used for that purpose); figuratively, a portion or destiny (as if determined by lot) lot.', 'or (shortened) גֹּרָל; from an unused root meaning to be rough (as stone);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4057B}/H9011/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["[the] wilderness of/ towards","[the] wilderness/ <towards>","[the] wilderness/ towards"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1032I}/[H1004]', 'inflected', 'heb', 'בֵּית חוֹרוֹן', '["Bêyth Chôwrôwn"]', '["of/ Beth"]', '["n-pr-loc"]', 'Beth-Choron, the name of two adjoining places in Palestine Beth-horon.', 'from 1004 and 2356; house of hollowness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6010P}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["[is] in/ [the] valley of","in/ [the] valley of"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1516G}/[H1466]', 'lemma', 'heb', 'גַּיְא', '["gayʼ"]', '["[the] valley of","[the] valley of [Ben]"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2011G>', 'opaque', 'heb', 'הִנֹּם', '["Hinnôm"]', '["Hinnom","[Ben] Hinnom"]', '["n-pr-loc"]', 'Hinnom, apparently a Jebusite Hinnom.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1553}/[H1552]', 'lemma', 'heb', 'גְּלִילוֹת', '["Gᵉlîylôwth"]', '["Geliloth"]', '["n-pr-loc"]', 'Geliloth, a place in Palestine Geliloth.', 'plural of 1552; circles;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6160J}/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["the/ Arabah"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6160J}/H9011/[H6150]', 'inflected', 'heb', 'עֲרָבָה', '["ʻărâbâh"]', '["the/ Arabah/ towards"]', '["n-f"]', 'a desert; especially (with the article prefix) the (generally) sterile valley of the Jordan and its continuation to the Red Sea Arabah, champaign, desert, evening, heaven, plain, wilderness. See also 1026.', 'from 6150 (in the sense of sterility);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1031}/[H1004]', 'inflected', 'heb', 'בֵּית חׇגְלָה', '["Bêyth Choglâh"]', '["and/ Beth"]', '["n-pr-loc"]', 'Beth-Choglah, a place in Palestine Beth-hoglah.', 'from 1004 and the same as 2295; house of a partridge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6010J}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["and/ Emek"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
