INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1026}/[H1004]', 'inflected', 'heb', 'בֵּית הָעֲרָבָה', '["Bêyth hâ-ʻĂrâbâh"]', '["and/ Beth"]', '["n-pr-loc"]', 'Beth-ha-Arabah, a place in Palestine Beth-arabah.', 'from 1004 and 6160 with the article interposed; house of the Desert;');
