INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5871H}/[H5869]', 'lemma', 'heb', 'עַיִן', '["ʻAyin"]', '["Ain"]', '["n-pr-loc"]', 'Ajin, the name (thus simply) of two places in Palestine Ain.', 'the same as 5869; fountain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7417I}/[H7416]', 'lemma', 'heb', 'רִמּוֹן', '["Rimmôwn"]', '["Rimmon"]', '["n-pr-m n-pr-loc"]', 'Rimmon, the name of a Syrian deity, also of five places in Palestine Remmon, Rimmon.', 'or (shorter) (רִמֹּן; or רִמּוֹנוֹ; (1 Chronicles 6:62 (77)), the same as 7416; in Joshua 19:13: הַמְּתֹאָר is mistaken for part of a name; article with the passive participle of 8388; the (one) marked off, i.e. which pertains).');
