INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8556B}/[H8553]', 'lemma', 'heb', 'תִּמְנַת חֶרֶס', '["Timnath Chereç"]', '["Serah","Timnath"]', '["n-pr-loc"]', 'Timnath-Cheres, a place in Palestine Timnath-heres, Timnath-serah.', 'or תִּמְנַת סֶרַח; from 8553 and 2775; portion of (the) sun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2505A}/[H2505]', 'inflected', 'heb', 'חָלַק', '["châlaq"]', '["from/ apportioning","more than/ dividing"]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5892B}/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["[were] from/ the/ cities","from/ the/ cities","from/ the/ city","of/ the/ cities"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697L}/H9023/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["affairs/ his","words/ his"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6942J}/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["and/ I will consecrate","and/ they consecrate","and/ they set apart"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1551}/[H1550]', 'inflected', 'heb', 'גָּלִיל', '["Gâlîyl"]', '["in <the>/ Galilee"]', '["n-pr-loc"]', 'Galil (as a special circuit) in the North of Palestine Galilee.', 'or (prolonged) גָּלִילָה; the same as 1550; a circle (with the article);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5676H}/[H5674]', 'inflected', 'heb', 'עֵבֶר', '["ʻêber"]', '["and/ from/ [the] other side"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4152}/[H3259]', 'inflected', 'heb', 'מוּעָדָה', '["mûwʻâdâh"]', '["<the>/ appointing"]', '["n-f"]', 'an appointed place, i.e. asylum appointed.', 'from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4054}/H9029/[H1644]', 'inflected', 'heb', 'מִגְרָשׁ', '["migrâsh"]', '["and/ pasture lands/ their"]', '["n-m"]', 'a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb.', 'also (in plural) feminine (Ezekiel 27:28) מִגְרָשָׁה; from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0929>/H9025', 'inflected', 'heb', 'לבהמתנו', '["li/v.hem.Te./nu"]', '["for/ livestock/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5159}/H9028/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["some of/ inheritance/ their"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4294H}/[H5186]', 'inflected', 'heb', 'מַטֶּה', '["maṭṭeh"]', '["and/ from/ [the] tribe of"]', '["n-m"]', 'a branch (as extending); figuratively, a tribe; also a rod, whether for chastising (figuratively, correction), ruling (a sceptre), throwing (a lance), or walking (a staff; figuratively, a support of life, e.g. bread) rod, staff, tribe.', 'or (feminine) מַטָּה; from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6240}\/[H6235]', 'inflected', 'heb', 'עָשָׂר', '["ʻâsâr"]', '["teen","ten"]', '["n"]', 'ten (only in combination), i.e. -teen; also (ordinal) -teenth (eigh-, fif-, four-, nine-, seven-, six-, thir-) teen(-th), + eleven(-th), + sixscore thousand, + twelve(-th).', 'for 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2677}/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["and/ from/ [the] half of","and/ of/ [the] half of"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6235}\/[H6237]', 'inflected', 'heb', 'עֶשֶׂר', '["ʻeser"]', '["ten"]', '["n"]', 'ten (as an accumulation to the extent of the digits) ten, (fif-, seven-) teen.', 'masculine of term עֲשָׂרָה; from 6237;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1486>\', 'inflected', 'heb', 'בגורל פ', '["ba./go.Ral"]', '["by the/ lot"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4054}/H9024/[H1644]', 'inflected', 'heb', 'מִגְרָשׁ', '["migrâsh"]', '["pasture lands/ its","pastureland/ its"]', '["n-m"]', 'a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb.', 'also (in plural) feminine (Ezekiel 27:28) מִגְרָשָׁה; from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2691B}/H9024/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["villages/ its"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0272}/H9023\/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["<in>/ possession/ his"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
