INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0851}/[H8085]', 'lemma', 'heb', 'אֶשְׁתְּמֹעַ', '["ʼEshtᵉmôaʻ"]', '["Eshtemoa"]', '["n-pr"]', 'Eshtemoa or Eshtemoh, a place in Palestine Eshtemoa, Eshtemoh.', 'or אֶשְׁתְּמוֹעַ; or אֶשְׁתְּמֹה; from 8085 (in the sense of obedience);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2473G}/[H2344]', 'lemma', 'heb', 'חֹלוֹן', '["Chôlôwn"]', '["Holon"]', '["n-pr-loc"]', 'Cholon, the name of two places in Palestine Holon.', 'or (shortened) חֹלֹן; probably from 2344; sandy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3194}/[H5186]', 'lemma', 'heb', 'יֻטָּה', '["Yuṭṭâh"]', '["Juttah"]', '["n-pr-loc"]', 'Juttah (or Jutah), a place in Palestine Juttah.', 'or יוּטָה; from 5186; extended;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1387G}/[H1375]', 'lemma', 'heb', 'גֶּבַע', '["Gebaʻ"]', '["Geba"]', '["n-pr-loc"]', 'Geba, a place in Palestine Gaba, Geba, Gibeah.', 'from the same as 1375, a hillock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6068G}/[H6067]', 'lemma', 'heb', 'עֲנָתוֹת', '["ʻĂnâthôwth"]', '["Anathoth"]', '["n-pr-m n-pr-loc"]', 'Anathoth, the name of two Israelites, also of a place in Pal Anathoth.', 'plural of 6067;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5960}/[H5956]', 'lemma', 'heb', 'עַלְמוֹן', '["ʻAlmôwn"]', '["Almon"]', '["n-pr-loc"]', 'Almon, a place in Palestine Almon', 'from 5956; hidden; See also 5963.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4054}/H9029\/[H1644]', 'inflected', 'heb', 'מִגְרָשׁ', '["migrâsh"]', '["and/ pasture lands/ their"]', '["n-m"]', 'a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb.', 'also (in plural) feminine (Ezekiel 27:28) מִגְרָשָׁה; from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4940}/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["and/ of/ a clan","and/ to/ [the] clans of"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6911}/[H6908]', 'lemma', 'heb', 'קִבְצַיִם', '["Qibtsayim"]', '["Kibzaim"]', '["n-pr-loc"]', 'Kibtsajim, a place in Palestine Kibzaim.', 'dual from 6908; a double heap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0702}\/[H7251]', 'inflected', 'heb', 'אַרְבַּע', '["ʼarbaʻ"]', '["four"]', '["n"]', 'four four.', 'masculine אַרְבָּעָה; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0514>', 'opaque', 'heb', 'אֶלְתְּקֵא', '["ʼEltᵉqêʼ"]', '["Eltekeh"]', '["n-pr-loc"]', 'Eltekeh or Elteke, a place in Palestine Eltekeh.', 'or (more properly) אֶלְתְּקֵה; of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1405}/[H1389]', 'lemma', 'heb', 'גִּבְּתוֹן', '["Gibbᵉthôwn"]', '["Gibbethon"]', '["n-pr-loc"]', 'Gibbethon, a place in Palestine Gibbethon.', 'intensive from 1389; a hilly spot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1667H}/[H1660]', 'lemma', 'heb', 'גַּת־רִמּוֹן', '["Gath-Rimmôwn"]', '["Gath","Rimmon"]', '["n-pr-loc"]', 'Gath-Rimmon, a place in Palestine Gath-rimmon. d', 'from 1660 and 7416; wine-press of (the) pomegranate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3498}\/[H3498]', 'inflected', 'heb', 'יָתַר', '["yâthar"]', '["which/ remained"]', '["v"]', 'to jut over or exceed; by implication, to excel; (intransitively) to remain or be left; causatively to leave, cause to abound, preserve excel, leave (a remnant), left behind, too much, make plenteous, preserve, (be, let) remain(-der, -ing, -nant), reserve, residue, rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2677}/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["from/ [the] half of"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1203}/[H6251]', 'lemma', 'heb', 'בְּעֶשְׁתְּרָה', '["Bᵉʻeshtᵉrâh"]', '["Beeshtarah"]', '["n-pr-loc"]', 'Beeshterah, a place East of the Jordan Beeshterah.', 'from 6251 (as singular of 6252) with a prepositional prefix; with Ashtoreth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8147}\/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["two"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7191}/[H7190]', 'lemma', 'heb', 'קִשְׁיוֹן', '["Qishyôwn"]', '["Kishion"]', '["n-pr-loc"]', 'Kishjon, a place in Palestine Kishion, Keshon.', 'from 7190; hard ground;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1705}/[H1697]', 'lemma', 'heb', 'דֲּבְרַת', '["Dăbrath"]', '["Daberath"]', '["n-pr-loc"]', 'Daberath, a place in Palestine Dabareh, Daberath.', 'from 1697 (perhaps in the sense of 1699);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3412H}/[H7311]', 'lemma', 'heb', 'יַרְמוּת', '["Yarmûwth"]', '["Jarmuth"]', '["n-pr-loc"]', 'Jarmuth, the name of two places in Palestine Jarmuth.', 'from 7311; elevation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4861}/[H7592]', 'lemma', 'heb', 'מִשְׁאָל', '["Mishʼâl"]', '["Mishal"]', '["n-pr-loc"]', 'Mishal, a place in Palestine Mishal, Misheal. Compare 4913.', 'from 7592; request;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5658G}/[H5647]', 'lemma', 'heb', 'עַבְדוֹן', '["ʻAbdôwn"]', '["Abdon"]', '["n-pr-m n-pr-loc"]', 'Abdon, the name of a place in Palestine and of four Israelites Abdon. Compare 5683.', 'from 5647; servitude;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7340H}/[H7339]', 'lemma', 'heb', 'רְחֹב', '["Rᵉchôb"]', '["Rehob"]', '["n-pr-m n-pr-loc"]', 'Rechob, the name of a place in Syria, also of a Syrian and an Israelite Rehob.', 'or רְחוֹב; the same as 7339;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2576}/[H2535]', 'lemma', 'heb', 'חַמֹּת דֹּאר', '["Chammôth Dôʼr"]', '["Dor","Hammoth"]', '["n-pr-loc"]', 'Chammath-Dor, a place in Palestine Hamath-Dor.', 'from the plural of 2535 and 1756; hot springs of Dor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7178}/[H7176]', 'lemma', 'heb', 'קַרְתָּן', '["Qartân"]', '["Kartan"]', '["n-pr-loc"]', 'Kartan, a place in Palestine Kartan.', 'from 7176; city-plot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7177}/[H7176]', 'lemma', 'heb', 'קַרְתָּה', '["Qartâh"]', '["Kartah"]', '["n-pr-loc"]', 'Kartah, a place in Palestine Kartah.', 'from 7176; city;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1829}/[H1828]', 'lemma', 'heb', 'דִּמְנָה', '["Dimnâh"]', '["Dimnah"]', '["n-pr-loc"]', 'Dimnah, a place in Palestine Dimnah.', 'feminine from the same as 1828; a dung-heap;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5096}/[H5097]', 'lemma', 'heb', 'נַהֲלָל', '["Nahălâl"]', '["Nahalal","Nahalol"]', '["n-pr-loc"]', 'Nahalal or Nahalol, a place in Palestine Nahalal, Nahallal, Nahalol.', 'or נַהֲלֹל; the same as 5097;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4158}/[H3313]', 'lemma', 'heb', 'מוֹפַעַת', '["Môwphaʻath"]', '["Mephaath"]', '["n-pr-loc"]', 'Mophaath or Mephaath, a place in Palestine Mephaath.', '(Jeremiah 48:21) or מֵיפַעַת; or מֵפַעַת; from 3313; illuminative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7433}/[H7413]', 'lemma', 'heb', 'רָמֹת גִּלעָד', '["Râmôth Gilʻâd"]', '["Ramoth"]', '["n-pr-m n-pr-loc"]', 'Ramoth-Gilad, a place East of the Jordan Ramoth-gilead, Ramoth in Gilead. See also 7216.', 'or רָמוֹת גִּלעָד; (2 Chronicles 22:5), from the plural of 7413 and 1568; heights of Gilad;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4266}/[H4264]', 'lemma', 'heb', 'מַחֲנַיִם', '["Machănayim"]', '["Mahanaim"]', '["n-pr-loc"]', 'Machanajim, a place in Palestine Mahanaim.', 'dual of 4264; double camp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4054}/H9024/[H1644]', 'inflected', 'heb', 'מִגְרָשׁ', '["migrâsh"]', '["and/ pasture lands/ its"]', '["n-m"]', 'a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb.', 'also (in plural) feminine (Ezekiel 27:28) מִגְרָשָׁה; from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5439H}/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["[is] from/ around about","[is] from/ round about","[will be] from/ round about","from/ round about"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6440H}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["in/ faces/ their"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307L}/[H5307]', 'lemma', 'heb', 'נָפַל', '["nâphal"]', '["it fall","it fell","it has fallen"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5647H}/H9033/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ to/ serve/ him"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0168G}/H9028\/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["tents/ their"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2677}/H9023/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["and/ to/ half of/ it"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0168H}/H9028/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["tents/ their"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5233>', 'inflected', 'heb', 'בנכסים', '["bi/n.kha.Sim"]', '["with/ riches"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0168G}/H9026/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["tents/ your"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1270}/[H1269]', 'inflected', 'heb', 'בַּרְזֶל', '["barzel"]', '["and/ in <the>/ iron","and/ with/ iron"]', '["n-m"]', 'iron (as cutting); by extension, an iron implement (ax) head, iron.', 'perhaps from the root of 1269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8008}/[H8071]', 'inflected', 'heb', 'שַׂלְמָה', '["salmâh"]', '["and/ with/ garments"]', '["n-f"]', 'a dress clothes, garment, raiment.', 'transp. for 8071;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251I}/H9026\/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["countrymen/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7887}/[H7886]', 'inflected', 'heb', 'שִׁילֹה', '["Shîylôh"]', '["from/ Shiloh"]', '["n-pr-loc"]', 'Shiloh, a place in Palestine Shiloh.', 'or שִׁלֹה; or שִׁילוֹ; or שִׁלוֹ; from the same as 7886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5927J}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["to/ go up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6635H}\/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["for <the>/ war"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0505H}/[H504]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["<into>/ [the] thousand","[belong] to/ [the] families of"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4604}/[H4603]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["[is] the/ unfaithfulness","the/ unfaithfulness"]', '["n-m"]', 'treachery, i.e. sin falsehood, grievously, sore, transgression, trespass, × very.', 'from 4603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1129}/H9046/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["when/ build/ you","when/ built/ you"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4775}/H9036/[H4775]', 'inflected', 'heb', 'מָרַד', '["mârad"]', '["by/ rebelling/ your"]', '["v"]', 'to rebel rebel(-lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3068G}/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["and/ against/ Yahweh","and/ in/ Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5771G}/H9023\/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["for/ iniquity/ his"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4777}/[H4775]', 'inflected', 'heb', 'מֶרֶד', '["mered"]', '["in/ rebellion"]', '["n-m"]', 'rebellion rebellion.', 'from 4775;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4604}/[H4603]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["in the/ unfaithfulness","in/ unfaithfulness"]', '["n-m"]', 'treachery, i.e. sin falsehood, grievously, sore, transgression, trespass, × very.', 'from 4603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3467}/H9035/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["he will deliver/ us","it will save/ us","save/ us","will he deliver/ us","you have delivered/ us","you have saved/ us","you save/ us"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725I}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["by/ turning away","to/ bring back","to/ revoke","to/ turn back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1674}/[H1672]', 'inflected', 'heb', 'דְּאָגָה', '["dᵉʼâgâh"]', '["from/ anxiety"]', '["n-f"]', 'anxiety care(-fulness), fear, heaviness, sorrow.', 'from 1672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1697I}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["from/ a matter"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121G}/H9025/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["to/ descendants/ our"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3068G}/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["and/ [belongs] to/ Yahweh","and/ to/ Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121G}/H9025/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["descendants/ our","sons/ our"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1755}/H9025/[H1752]', 'inflected', 'heb', 'דּוֹר', '["dôwr"]', '["generations/ our"]', '["n-m"]', 'properly, a revolution of time, i.e. an age or generation; also a dwelling age, × evermore, generation, (n-) ever, posterity.', 'or (shortened) דֹּר; from 1752;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5930A}/H9025/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["with/ burnt offerings/ our"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2077}/H9025/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["and/ with/ sacrifices/ our"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8002}/H9025/[H7999]', 'inflected', 'heb', 'שֶׁלֶם', '["shelem"]', '["and/ with/ peace offerings/ our"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4775}/[H4775]', 'inflected', 'heb', 'מָרַד', '["mârad"]', '["to/ rebel"]', '["v"]', 'to rebel rebel(-lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7725I}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ to/ turn back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4908}/H9023\/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["tabernacle/ his"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869A}/H9028/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ own eyes/ their","in/ view/ their"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2205G}/H9023/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["<to>/ elders/ its"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H7218H>/H9023', 'inflected', 'heb', 'ולראשיו', '["u./le./ra.Sha/v"]', '["and/ <to>/ leaders/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8199}/H9033/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["and/ <to>/ judges/ its"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H7860>/H9023', 'inflected', 'heb', 'ולשטריו', '["u./le./Sho.te.Ra/v","u./le./sho.te.Ra/v"]', '["and/ <to>/ officials/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1920}/H9038/[H1920]', 'inflected', 'heb', 'הָדַף', '["hâdaph"]', '["he will drive out/ them"]', '["v"]', 'to push away or down cast away (out), drive, expel, thrust (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3499A}/[H3498]', 'inflected', 'heb', 'יֶתֶר', '["yether"]', '["to/ [the] remainder of"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2859B}/[H2859]', 'inflected', 'heb', 'חָתַן', '["châthan"]', '["and/ he became son-in-law","and/ you will intermarry"]', '["v"]', 'to give (a daughter) away in marriage; hence (generally) to contract affinity by marriage join in affinity, father in law, make marriages, mother in law, son in law.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0935L}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ he went","and/ they went","and/ you will go"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6341A}/[H6351]', 'inflected', 'heb', 'פַּח', '["pach"]', '["<into>/ a trap"]', '["n-m"]', 'a (metallic) sheet (as pounded thin); also a spring net (as spread out like a lamina) gin, (thin) plate, snare.', 'from 6351;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4170}/[H3369]', 'inflected', 'heb', 'מוֹקֵשׁ', '["môwqêsh"]', '["and/ <into>/ a snare"]', '["n-m"]', 'a noose (for catching animals) (literally or figuratively); by implication, a hook (for the nose) be ensnared, gin, (is) snare(-d), trap.', 'or מֹקֵשׁ; from 3369;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H7850>', 'inflected', 'heb', 'ולשטט', '["u./le./sho.Tet"]', '["and/ <into>/ a scourge"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0006}/H9046/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["perish/ you"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5674D}/H9046/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["when/ transgress/ you"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7393G}/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["<in> <the>/ chariotry","among/ [the] chariots of","in <the>/ chariot[s]","with/ chariotry","with/ chariotry of"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6571B}/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["and/ by/ horsemen","and/ with/ horsemen"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3990}/[H651]', 'lemma', 'heb', 'מַאֲפֵל', '["maʼăphêl"]', '["darkness"]', '["n-m"]', 'something opaque darkness.', 'from the same as 651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2719}/H9021/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["by/ sword/ your"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7198}/H9021/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["by/ bow/ your"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8549H}/[H8552]', 'inflected', 'heb', 'תָּמִים', '["tâmîym"]', '["in/ blamelessness","in/ integrity"]', '["a"]', 'entire (literally, figuratively or morally); also (as noun) integrity, truth without blemish, complete, full, perfect, sincerely (-ity), sound, without spot, undefiled, upright(-ly), whole.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0571G}/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["and/ in/ faithfulness"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4714G}/[H4693]', 'inflected', 'heb', 'מִצְרַיִם', '["Mitsrayim"]', '["and/ in/ Egypt"]', '["n-pr"]', 'Mitsrajim, i.e. Upper and Lower Egypt Egypt, Egyptians, Mizraim.', 'dual of 4693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869H}/H9025/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ our"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8104H}/H9035/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ he kept/ us"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9025\/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ our","[are] god/ our","[is] God/ our"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7072}/[H7067]', 'lemma', 'heb', 'קַנּוֹא', '["qannôwʼ"]', '["jealous"]', '["a"]', 'jealous or angry jealous.', 'for 7067;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2403B}/H9026/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ <to>/ sins/ your"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6965I}/H9034/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ he set up/ it"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0427}/[H424]', 'inflected', 'heb', 'אַלָּה', '["ʼallâh"]', '["the/ oak"]', '["n-m"]', 'oak.', 'A variation of 424');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4720}/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["[was] at/ [the] sanctuary of","in/ [the] sanctuary of"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3584}/H9013/[H3584]', 'inflected', 'heb', 'כָּחַשׁ', '["kâchash"]', '["you should deny/ !"]', '["v"]', 'to be untrue, in word (to lie, feign, disown) or deed (to disappoint, fail, cringe) deceive, deny, dissemble, fail, deal falsely, be found liars, (be-) lie, lying, submit selves.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0430G}/H9026/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["<in>/ God/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5159}/H9023\/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["to/ own inheritance/ his"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8556B}/[H8553]', 'inflected', 'heb', 'תִּמְנַת חֶרֶס', '["Timnath Chereç"]', '["at/ Timnath"]', '["n-pr-loc"]', 'Timnath-Cheres, a place in Palestine Timnath-heres, Timnath-serah.', 'or תִּמְנַת סֶרַח; from 8553 and 2775; portion of (the) sun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2022G}/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["<to>/ [the] mountain of","and/ [the] mountain of","into/ a mountain of","of/ [the] mountain of","to the/ mountains","to/ [the] mountain of"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1608}/[H1607]', 'lemma', 'heb', 'גַּעַשׁ', '["Gaʻash"]', '["Gaash"]', '["n-pr-loc"]', 'Gaash, a hill in Palestine Gaash.', 'from 1607; a quaking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2513A}/[H2506]', 'inflected', 'heb', 'חֶלְקָה', '["chelqâh"]', '["in/ [the] portion of","in/ [the] portion of land of","on the/ portion of land"]', '["n-f"]', 'properly, smoothness; figuratively, flattery; also an allotment field, flattering(-ry), ground, parcel, part, piece of land (ground), plat, portion, slippery place, smooth (thing).', 'feminine of 2506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1390H}/[H1389]', 'inflected', 'heb', 'גִּבְעָה', '["Gibʻâh"]', '["[are] in <the>/ Gibeah","at <the>/ Gibeah","at/ Gibeah of","in <the>/ Gibeah"]', '["n-pr-loc"]', 'Gibah; the name of three places in Palestine Gibeah, the hill.', 'the same as 1389;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1486>/H9020', 'inflected', 'heb', 'בגורלי', '["ve./go.ra.L/i"]', '["in/ lot/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3898A}/[H3898]', 'inflected', 'heb', 'לָחַם', '["lâcham"]', '["and/ fight","and/ let us fight","so/ let us fight"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1486>/H9021', 'inflected', 'heb', 'בגורלך', '["be./go.ra.Le./kha"]', '["in/ lot/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0966G}/[H965]', 'inflected', 'heb', 'בֶּזֶק', '["Bezeq"]', '["at/ Bezek"]', '["n-pr-loc"]', 'Bezek, a place in Palestine Bezek.', 'from 965; lightning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0137}/[H113]', 'lemma', 'heb', 'אֲדֹנִי־בֶזֶק', '["ʼĂdônîy-Bezeq"]', '["Adoni-","Bezek"]', '["n-pr-m"]', 'Adoni-Bezek; a Canaanitish king Adonibezek.', 'from 113 and 966; lord of Bezek;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7272}/H9023/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["and/ feet/ his"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7112}/[H7112]', 'lemma', 'heb', 'קָצַץ', '["qâtsats"]', '["[those who] are cut off of","cut off","he cut off","he has cut off"]', '["v"]', 'to chop off (literally or figuratively) cut (asunder, in pieces, in sunder, off), × utmost.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7979}/H9020/[H7971]', 'inflected', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["table/ my"]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8033G}\/[H834]', 'inflected', 'heb', 'שָׁם', '["shâm"]', '["there"]', '["adv"]', 'there (transferring to time) then; often thither, or thence in it, thence, there (-in, of, out), thither, whither.', 'a primitive particle (rather from the relative pronoun, 834);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971L}/[H7971]', 'lemma', 'heb', 'שָׁלַח', '["shâlach"]', '["they sent","you will send"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414H}/H9030/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["you have given to/ me"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7017}/[H7014]', 'lemma', 'heb', 'קֵינִי', '["Qêynîy"]', '["[the] Kenite","[the] Kenite[s]"]', '["a"]', 'a Kenite or member of the tribe of Kajin Kenite.', 'or קִינִי; (1 Chronicles 2:55), patronymic from 7014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5899}/[H5892]', 'inflected', 'heb', 'עִיר הַתְּמָרִים', '["ʻÎyr hat-Tᵉmârîym"]', '["from/ [the] city of"]', '["n-pr-loc"]', 'Ir-hat-Temarim, a place in Palestine the city of palmtrees.', 'from 5892 and the plural of 8558 with the article interpolated; city of the palmtrees;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6857}/[H6822]', 'lemma', 'heb', 'צְפַת', '["Tsᵉphath"]', '["of Zephath"]', '["n-pr-loc"]', 'Tsephath, a place in Palestine Zephath.', 'from 6822; watch-tower;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366H}/H9024/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["territories/ its","territory/ its"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0831}/[H8254]', 'lemma', 'heb', 'אַשְׁקְלוֹן', '["ʼAshqᵉlôwn"]', '["Ashkelon"]', '["n-pr-loc"]', 'Ashkelon, a place in Palestine Ashkelon, Askalon.', 'probably from 8254 in the sense of weighing-place (i.e. mart);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1008G}/[H1004]', 'inflected', 'heb', 'בֵּית־אֵל', '["Bêyth-ʼÊl"]', '["[is] in/ Beth-","[was] at/ Beth-","at/ Beth-","in/ Beth-"]', '["n-pr-loc"]', 'Beth-El, a place in Palestine Beth-el.', 'from 1004 and 410; house of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8104I}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["those/ [who] keep","those/ [who] watched","who/ were watching"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3870G}/[H3869]', 'lemma', 'heb', 'לוּז', '["Lûwz"]', '["Luz"]', '["n-pr-loc"]', 'Luz, the name of two places in Palestine Luz.', 'probably from 3869 (as growing there);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2991}/[H1104]', 'lemma', 'heb', 'יִבְלְעָם', '["Yiblᵉʻâm"]', '["Ibleam"]', '["n-pr-loc"]', 'Jibleam, a place in Palestine Ibleam.', 'from 1104 and 5971; devouring people;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1507}\/[H1506]', 'inflected', 'heb', 'גֶּזֶר', '["Gezer"]', '["in/ Gezer"]', '["n-pr-loc"]', 'Gezer, a place in Palestine Gazer, Gezer.', 'the same as 1506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7003}/[H6999]', 'lemma', 'heb', 'קִטְרוֹן', '["Qiṭrôwn"]', '["Kitron"]', '["n-pr-loc"]', 'Kitron, a place in Palestine Kitron.', 'from 6999; fumigative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4522}\/[H4549]', 'inflected', 'heb', 'מַס', '["maç"]', '["<into>/ forced labor"]', '["n-m"]', 'properly, a burden (as causing to faint), i.e. a tax in the form of forced labor discomfited, levy, task(-master), tribute(-tary).', 'or מִס; from 4549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5910>', 'opaque', 'heb', 'עַכּוֹ', '["ʻAkkôw"]', '["Acco"]', '["n-pr-loc"]', 'Akko (from its situation on a bay) Accho.', 'apparently from an unused root meaning to hem in;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6721H}/[H6679]', 'lemma', 'heb', 'צִידוֹן', '["Tsîydôwn"]', '["O Sidon","Sidon"]', '["n-pr-loc"]', 'Tsidon, the name of a son of Canaan, and of a place in Palestine Sidon, Zidon.', 'or צִידֹן; from 6679 in the sense of catching fish; fishery;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0303}/[H2459]', 'lemma', 'heb', 'אַחְלָב', '["ʼAchlâb"]', '["Ahlab"]', '["n-pr-loc"]', 'Achlab, a place in Palestine Ahlab.', 'from the same root as 2459; fatness (i.e. fertile);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0392H}/[H391]', 'lemma', 'heb', 'אַכְזִיב', '["ʼAkzîyb"]', '["Aczib"]', '["n-pr-loc"]', 'Akzib, the name of two places in Palestine Achzib.', 'from 391; deceitful (in the sense of a winter-torrent which fails in summer);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2462}/[H2459]', 'lemma', 'heb', 'חֶלְבָּה', '["Chelbâh"]', '["Helbah"]', '["n-pr-loc"]', 'Chelbah, a place in Palestine Helbah.', 'feminine of 2459; fertility;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0663H}/[H662]', 'lemma', 'heb', 'אֲפֵק', '["ʼĂphêq"]', '["Aphek"]', '["n-pr-loc"]', 'Aphek (or Aphik), the name of three places in Palestine Aphek, Aphik.', 'or אֲפִיק; from 662 (in the sense of strength); fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0843}/[H836]', 'inflected', 'heb', 'אָשֵׁרִי', '["ʼÂshêrîy"]', '["the/ Asherite[s]"]', '["a"]', 'an Asherite (collectively) or descendant of Asher Asherites.', 'patronymic from 836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6010R}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["to the/ valley"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2776H}/[H2775]', 'lemma', 'heb', 'חֶרֶס', '["Chereç"]', '["Heres"]', '["n-pr-loc"]', 'Cheres, a mountain in Palestine Heres.', 'the same as 2775; shining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0357}/[H354]', 'inflected', 'heb', 'אַיָּלוֹן', '["ʼAyâlôwn"]', '["in/ Aijalon"]', '["n-pr-loc"]', 'Ajalon, the name of five places in Palestine Aijalon, Ajalon.', 'from 354; deer-field;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8169}/[H7776]', 'inflected', 'heb', 'שַׁעַלְבִים', '["Shaʻalbîym"]', '["and/ in/ Shaalbim"]', '["n-pr-loc"]', 'Shaalbim or Shaalabbin, a place in Palestine Shaalabbin, Shaalbim.', 'or שַׁעֲלַבִּין; plural from 7776; fox-holes;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4608}/[H5927]', 'inflected', 'heb', 'מַעֲלֶה', '["maʻăleh"]', '["[was] from/ [the] ascent of"]', '["n-m"]', 'an elevation, i.e. (concretely) acclivity or platform; abstractly (the relation or state) a rise or (figuratively) priority ascent, before, chiefest, cliff, that goeth up, going up, hill, mounting up, stairs.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5554}/[H5553]', 'inflected', 'heb', 'סֶלַע', '["Çelaʻ"]', '["from/ <the>/ Sela"]', '["n-pr-loc"]', 'Sela, the rock-city of Idumaea rock, Sela(-h).', 'the same as 5553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4605}/H9011\/[H5927]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["and/ up/ -wards"]', '["adv"]', 'properly,the upper part, used only adverbially with prefix upward, above, overhead, from the top, etc. above, exceeding(-ly), forward, on (× very) high, over, up(-on, -ward), very.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1066}\/[H1058]', 'inflected', 'heb', 'בֹּכִים', '["Bôkîym"]', '["<the>/ Bokim"]', '["n-pr-loc"]', 'Bo-kim, a place in Palestine Bochim.', 'plural active participle of 1058; (with the article) the weepers;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6654>', 'inflected', 'heb', 'לצדים', '["le./tzi.Dim"]', '["<into>/ sides"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0430J}/H9028/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ gods/ their"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963A>/H9028', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["voice/ their"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1066}/[H1058]', 'lemma', 'heb', 'בֹּכִים', '["Bôkîym"]', '["Bokim"]', '["n-pr-loc"]', 'Bo-kim, a place in Palestine Bochim.', 'plural active participle of 1058; (with the article) the weepers;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5159}/H9023/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["to/ inheritance/ his","to/ own inheritance/ his"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1366G}/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["in/ [the] territory of"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8556A}/[H8553]', 'inflected', 'heb', 'תִּמְנַת חֶרֶס', '["Timnath Chereç"]', '["in/ Timnath"]', '["n-pr-loc"]', 'Timnath-Cheres, a place in Palestine Timnath-heres, Timnath-serah.', 'or תִּמְנַת סֶרַח; from 8553 and 2775; portion of (the) sun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8556A}/[H8553]', 'lemma', 'heb', 'תִּמְנַת חֶרֶס', '["Timnath Chereç"]', '["Heres"]', '["n-pr-loc"]', 'Timnath-Cheres, a place in Palestine Timnath-heres, Timnath-serah.', 'or תִּמְנַת סֶרַח; from 8553 and 2775; portion of (the) sun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1168A}/[H1167]', 'inflected', 'heb', 'בַּעַל', '["Baʻal"]', '["<of the>/ Baal","<the>/ Baal","O/ Baal","the/ Baals"]', '["n-pr-m n-pr-loc"]', 'Baal, a Phoenician deity Baal, (plural) Baalim.', 'the same as 1167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3707}/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["and/ I will disturb","and/ he is vexed","and/ he provoked","and/ he provoked to anger","and/ he was angry","and/ he will be angry","and/ they provoked to anger"]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1168A}/[H1167]', 'inflected', 'heb', 'בַּעַל', '["Baʻal"]', '["<to> the/ Baal","<to> the/ Baals","for <the>/ Baal","for the/ Baals","into <the>/ Baal","to <the>/ Baal","to the/ Baals"]', '["n-pr-m n-pr-loc"]', 'Baal, a Phoenician deity Baal, (plural) Baalim.', 'the same as 1167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6252G}/[H6251]', 'inflected', 'heb', 'עַשְׁתָּרוֹת', '["ʻAshtârôwth"]', '["and/ <to> the/ Ashtaroth"]', '["n-pr-f"]', 'Ashtaroth, the name of a Sidonian deity, and of a place East of the Jordan Asharoth, Astaroth. See also 1045, 6253, 6255.', 'or עַשְׁתָּרֹת; plural of 6251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8154}/[H8154]', 'lemma', 'heb', 'שָׁסָה', '["shâçâh"]', '["I have plundered","O plunderers of","[are] plundering","it will plunder","plunderers","they have plundered"]', '["v"]', 'to plunder destroyer, rob, spoil(-er).', 'or שָׁשָׂה; (Isaiah 10:13), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8155}/[H8155]', 'inflected', 'heb', 'שָׁסַס', '["shâçaç"]', '["and/ they plundered","and/ they will be plundered"]', '["v"]', 'to plunder rifle, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4376}/H9038/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["and/ he sold/ them"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3467}/H9038/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ I will save/ them","and/ he delivered/ them","and/ he saved/ them","and/ he will deliver/ them","and/ they delivered/ them"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8154}/H9038/[H8154]', 'inflected', 'heb', 'שָׁסָה', '["shâçâh"]', '["plunderers/ their"]', '["v"]', 'to plunder destroyer, rob, spoil(-er).', 'or שָׁשָׂה; (Isaiah 10:13), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8199}/H9038/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["I judged/ them","I will judge/ them","judges/ their","rulers/ their"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5009}/H9028/[H5008]', 'inflected', 'heb', 'נְאָקָה', '["nᵉʼâqâh"]', '["from/ groaning/ their"]', '["n-f"]', 'a groan groaning.', 'from 5008;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3905}/H9038/[H3905]', 'inflected', 'heb', 'לָחַץ', '["lâchats"]', '["[those who] oppressed/ them"]', '["v"]', 'properly, to press, i.e. (figuratively) to distress afflict, crush, force, hold fast, oppress(-or), thrust self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1766}/H9038/[H1766]', 'inflected', 'heb', 'דָּחַק', '["dâchaq"]', '["and/ [those who] oppressed/ them"]', '["v"]', 'to press, i.e. oppress thrust, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0001G}/H9028/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["from/ ancestors/ their","more than/ ancestors/ their","more than/ fathers/ their"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5647H}/H9038/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["to/ serve/ them"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7812}/[H7812]', 'inflected', 'heb', 'שָׁחָה', '["shâchâh"]', '["and/ to/ bow down"]', '["v"]', 'to depress, i.e. prostrate (especially reflexive, in homage to royalty or God) bow (self) down, crouch, fall down (flat), humbly beseech, do (make) obeisance, do reverence, make to stoop, worship.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4611}/H9028/[H5953]', 'inflected', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["any of/ deeds/ their","from/ deeds/ their"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1870G}/H9028/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ any of/ way/ their"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6963A>/H9020', 'inflected', 'heb', 'לקולי', '["le./ko.L/i"]', '["to/ voice/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H8104J}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["¿/ [be] keeping"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3091G}\/[H3068]', 'inflected', 'heb', 'יְהוֹשׁוּעַ', '["Yᵉhôwshûwaʻ"]', '["Joshua"]', '["n-pr-m"]', 'Jehoshua (i.e. Joshua), the Jewish leader Jehoshua, Jehoshuah, Joshua. Compare 1954, 3442.', 'or יְהוֹשֻׁעַ; from 3068 and 3467; Jehovah-saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5254G}/[H5254]', 'inflected', 'heb', 'נָסָה', '["nâçâh"]', '["to/ put to [the] test"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3925G}/H9038/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["to/ teach/ them"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6722}/[H6721]', 'inflected', 'heb', 'צִידֹנִי', '["Tsîydônîy"]', '["and/ the/ Sidonian[s]"]', '["a"]', 'a Tsidonian or inhabitant of Tsidon Sidonian, of Sidon, Zidonian.', 'patrial from 6721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3844H}/[H3825]', 'inflected', 'heb', 'לְבָנוֹן', '["Lᵉbânôwn"]', '["<the>/ Lebanon"]', '["n-pr-loc"]', 'Lebanon, a mountain range in Palestine Lebanon.', 'from 3825; (the) white mountain (from its snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1179}/[H1167]', 'lemma', 'heb', 'בַּעַל חֶרְמוֹן', '["Baʻal Chermôwn"]', '["Baal","Hermon"]', '["n-pr-loc"]', 'Baal-Chermon, a place in Palestine Baal-hermon.', 'from 1167 and 2768; possessor of Hermon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H8085H}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["¿/ will they obey"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121A}/H9028/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["to/ children/ their","to/ sons/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430J}/H9028\/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["gods/ their"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0842}/[H833]', 'inflected', 'heb', 'אֲשֵׁרָה', '["ʼăshêrâh"]', '["<the>/ Asherah","<the>/ Asherah pole","the/ Asherah pole","the/ Asherah poles"]', '["n-pr-f"]', 'Asherah (or Astarte) a Phoenician goddess; also an image of the same grove. Compare 6253.', 'or אֲשֵׁירָה; from 833; happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3573}/[H3572]', 'lemma', 'heb', 'כּוּשַׁן רִשְׁעָתַיִם', '["Kûwshan Rishʻâthayim"]', '["Cushan-","Rishathaim"]', '["n-pr-m"]', 'Cushan-Rishathajim, a Mesopotamian king Chushan-rishathayim.', 'apparently from 3572 and the dual of 7564; Cushan of double wickedness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0758N}/[H759]', 'lemma', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5810}/[H5810]', 'inflected', 'heb', 'עָזַז', '["ʻâzaz"]', '["and/ it prevailed"]', '["v"]', 'to be stout (literally or figuratively) harden, impudent, prevail, strengthen (self), be strong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8252}/[H8252]', 'inflected', 'heb', 'שָׁקַט', '["shâqaṭ"]', '["and/ I will be at peace","and/ he will be undisturbed","and/ it was at peace"]', '["v"]', 'to repose (usually figurative) appease, idleness, (at, be at, be in, give) quiet(-ness), (be at, be in, give, have, take) rest, settle, be still.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7073I>\', 'opaque', 'heb', 'קְנַז', '["Qᵉnaz"]', '["Kenaz"]', '["n-pr-m"]', 'Kenaz, the name of an Edomite and of two Israelites Kenaz.', 'probably from an unused root meaning to hunt; hunter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5700H}/[H5695]', 'lemma', 'heb', 'עֶגְלוֹן', '["ʻEglôwn"]', '["Eglon"]', '["n-pr-m n-pr-loc"]', 'Eglon, the name of a place in Palestine and of a Moabitish king Eglon.', 'from 5695; vituline;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6002G>', 'inflected', 'heb', 'ועמלק', '["va./''a.ma.Lek"]', '["and/ Amalek"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0164G}/[H161]', 'lemma', 'heb', 'אֵהוּד', '["ʼÊhûwd"]', '["Ehud"]', '["n-pr-m"]', 'Ehud, the name of two or three Israelites Ehud.', 'from the same as 161; united;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1145}/[H376]', 'lemma', 'heb', 'בֶּן־יְמִינִי', '["Ben-yᵉmîynîy"]', '["O Ben-","[the] Ben-","[were] Ben-","a Ben-","a Jaminite","jaminite","jaminites"]', '["a"]', 'a Benjaminite, or descendent of Benjamin Benjamite, of Benjamin.', 'sometimes (with the article inserted) בֵּן־הַיּמִינִי; with 376 inserted (1 Samuel 9:1) בֶּן־אִישׁ ימִינִי; son of a man of Jemini; or shortened אִישׁ יְמִינִי; (1 Samuel 9:4; Esther 2:5) a man of Jemini, or (1 Samuel 20:1) simply יְמִינִיxlit Yᵉmînîy corrected to Yᵉmîynîy; a Jeminite; (plural) בְּנֵי יְמִינִיxlit Bᵉnîy corrected to Bᵉnêy; patron from 1144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1145}/[H376]', 'inflected', 'heb', 'בֶּן־יְמִינִי', '["Ben-yᵉmîynîy"]', '["<the>/ jaminite"]', '["a"]', 'a Benjaminite, or descendent of Benjamin Benjamite, of Benjamin.', 'sometimes (with the article inserted) בֵּן־הַיּמִינִי; with 376 inserted (1 Samuel 9:1) בֶּן־אִישׁ ימִינִי; son of a man of Jemini; or shortened אִישׁ יְמִינִי; (1 Samuel 9:4; Esther 2:5) a man of Jemini, or (1 Samuel 20:1) simply יְמִינִיxlit Yᵉmînîy corrected to Yᵉmîynîy; a Jeminite; (plural) בְּנֵי יְמִינִיxlit Bᵉnîy corrected to Bᵉnêy; patron from 1144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0334}/[H332]', 'lemma', 'heb', 'אִטֵּר', '["ʼiṭṭêr"]', '["impeded"]', '["a"]', 'shut up, i.e. impeded (as to the use of the right hand) left-handed.', 'from 332;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027J}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["by/ hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4503I>', 'opaque', 'heb', 'מִנְחָה', '["minchâh"]', '["<of> tribute","tribute"]', '["n-f"]', 'a donation; euphemistically, tribute; specifically a sacrificial offering (usually bloodless and voluntary) gift, oblation, (meat) offering, present, sacrifice.', 'from an unused root meaning to apportion, i.e. bestow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5700H}/[H5695]', 'inflected', 'heb', 'עֶגְלוֹן', '["ʻEglôwn"]', '["to/ Eglon"]', '["n-pr-m n-pr-loc"]', 'Eglon, the name of a place in Palestine and of a Moabitish king Eglon.', 'from 5695; vituline;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6366}/[H6310]', 'lemma', 'heb', 'פֵּיָה', '["pêyâh"]', '["lips"]', '["n-f"]', 'an edge (two-) edge(-d).', 'or פִּיָּה; feminine of 6310;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1574>', 'opaque', 'heb', 'גֹּמֶד', '["gômed"]', '["[was] a cubit"]', '["n-m"]', 'properly, a span cubit.', 'from an unused root apparently meaning to grasp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4055}/H9023/[H4058]', 'inflected', 'heb', 'מַד', '["mad"]', '["<to>/ garments/ his","to/ garments/ his"]', '["n-m"]', 'properly, extent, i.e. height; also a measure; by implication, a vesture (as measured); also a carpet armour, clothes, garment, judgment, measure, raiment, stature.', 'or מֵד; from 4058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4503I>', 'inflected', 'heb', 'המנחה', '["ha./min.Chah"]', '["<of> the/ tribute","the/ tribute"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5700H}/[H5695]', 'inflected', 'heb', 'עֶגְלוֹן', '["ʻEglôwn"]', '["and/ Eglon"]', '["n-pr-m n-pr-loc"]', 'Eglon, the name of a place in Palestine and of a Moabitish king Eglon.', 'from 5695; vituline;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6456}/[H6458]', 'inflected', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["the/ idols"]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5643A}/[H5641]', 'lemma', 'heb', 'סֵתֶר', '["çêther"]', '["[are] a hiding place","a shelter","secrecy","secret places"]', '["n-m"]', 'a cover (in a good or a bad, a literal or a figurative sense) backbiting, covering, covert, × disguise(-th), hiding place, privily, protection, secret(-ly, place).', 'or (feminine) סִתְרָה; (Deuteronomy 32:38), from 5641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2013}/[H2013]', 'lemma', 'heb', 'הָסָה', '["hâçâh"]', '["hush!"]', '["v"]', 'to hush hold peace (tongue), (keep) silence, be silent, still.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0164G}/[H161]', 'inflected', 'heb', 'אֵהוּד', '["ʼÊhûwd"]', '["and/ Ehud"]', '["n-pr-m"]', 'Ehud, the name of two or three Israelites Ehud.', 'from the same as 161; united;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5944}/[H5927]', 'inflected', 'heb', 'עֲלִיָּה', '["ʻălîyâh"]', '["in/ [the] roof chamber of"]', '["n-f"]', 'something lofty, i.e. a stair-way; also a second-story room (or even one on the roof); figuratively, the sky ascent, (upper) chamber, going up, loft, parlour.', 'feminine from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4747}/[H7119]', 'inflected', 'heb', 'מְקֵרָה', '["mᵉqêrâh"]', '["the/ coolness"]', '["n-f"]', 'a cooling off × summer.', 'from the same as 7119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8628}/H9034/[H8628]', 'inflected', 'heb', 'תָּקַע', '["tâqaʻ"]', '["and/ he thrust/ it"]', '["v"]', 'to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0990G>/H9023', 'inflected', 'heb', 'בבטנו', '["be./vit.N/o"]', '["in/ belly/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5325}/[H5324]', 'inflected', 'heb', 'נִצָּב', '["nitstsâb"]', '["the/ hilt"]', '["n-m"]', 'fixed, i.e. a handle haft.', 'passive participle of 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3851}/[H3851]', 'inflected', 'heb', 'לַהַב', '["lahab"]', '["the/ blade","the/ flame"]', '["n-m"]', 'a flash; figuratively, a sharply polished blade or point of a weapon blade, bright, flame, glittering.', 'from an usused root meaning to gleam;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0990G>/H9023', 'inflected', 'heb', 'מבטנו', '["mi./bit.N/o"]', '["from/ belly/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6574}/H9011/[H6567]', 'inflected', 'heb', 'פַּרְשְׁדֹן', '["parshᵉdôn"]', '["the/ hole/ towards"]', '["n-m"]', 'the crotch (or anus) dirt.', 'perhaps by compounding 6567 and 6504 (in the sense of straddling) (compare 6576);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4528}/H9011/[H5468]', 'inflected', 'heb', 'מִסְדְּרוֹן', '["miçdᵉrôwn"]', '["the/ porch/ towards"]', '["n-m"]', 'a colonnade or internal portico (from its rows of pillars) porch.', 'from the same as 5468;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5944}/[H5927]', 'inflected', 'heb', 'עֲלִיָּה', '["ʻălîyâh"]', '["the/ roof chamber","the/ upper room"]', '["n-f"]', 'something lofty, i.e. a stair-way; also a second-story room (or even one on the roof); figuratively, the sky ascent, (upper) chamber, going up, loft, parlour.', 'feminine from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5274A}/[H5275]', 'inflected', 'heb', 'נָעַל', '["nâʻal"]', '["and/ he locked","and/ he locked [them]"]', '["v"]', 'properly, to fasten up, i.e. with a bar or cord; hence, to sandal, i.e. furnish with slippers bolt, inclose, lock, shoe, shut up.', 'a primitive root; also denominative from 5275');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5274A}/[H5275]', 'lemma', 'heb', 'נָעַל', '["nâʻal"]', '["[were] locked","locked"]', '["v"]', 'properly, to fasten up, i.e. with a bar or cord; hence, to sandal, i.e. furnish with slippers bolt, inclose, lock, shoe, shut up.', 'a primitive root; also denominative from 5275');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2315}/[H2314]', 'inflected', 'heb', 'חֶדֶר', '["cheder"]', '["in the/ chamber","in/ [the] chamber of","in/ [the] rooms of","in/ a room"]', '["n-m"]', 'an apartment (usually literal) ((bed) inner) chamber, innermost(-ward) part, parlour, south, × within.', 'from 2314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4668}/[H6605]', 'inflected', 'heb', 'מַפְתֵּחַ', '["maphtêach"]', '["the/ key"]', '["n-m"]', 'an opener, i.e. a key key.', 'from 6605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0113>/H9028', 'opaque', 'heb', 'אָדוֹן', '["ʼâdôwn"]', '["lord<s>/ their","master<s>/ their","masters/ their","to lord<s>/ their"]', '["n-m"]', 'sovereign, i.e. controller (human or divine) lord, master, owner. Compare also names beginning with ''Adoni-''.', 'or (shortened) אָדֹן; from an unused root (meaning to rule);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4102}/H9048/[H4100]', 'inflected', 'heb', 'מָהַהּ', '["mâhahh"]', '["delayed/ they"]', '["v"]', 'properly, to question or hesitate, i.e. (by implication) to be reluctant delay, linger, stay selves, tarry.', 'apparently a denominative from 4100;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4422}/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["and/ I will be delivered","and/ he delivered","and/ he escaped","and/ he has escaped","and/ he will be delivered","and/ he will deliver [it]","and/ it laid eggs","and/ she delivered","and/ they have escaped","and/ they left undisturbed","and/ will he escape?"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8167}/H9011/[H8166]', 'inflected', 'heb', 'שְׂעִירָה', '["Sᵉʻîyrâh"]', '["<the>/ Seirah/ towards"]', '["n-pr-loc"]', 'Seirah, a place in Palestine Seirath.', 'formed as 8166; roughness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4569B}/[H5674]', 'lemma', 'heb', 'מַעֲבָר', '["maʻăbâr"]', '["[the] fords","[the] fords of","[the] pass"]', '["n-m"]', 'a crossing-place (of a river, a ford; of a mountain, a pass); abstractly, a transit, i.e. (figuratively) overwhelming ford, place where...pass, passage.', 'or feminine מַעֲבָרָה; from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6235}/[H6237]', 'inflected', 'heb', 'עֶשֶׂר', '["ʻeser"]', '["about/ [the] ten","about/ ten"]', '["n"]', 'ten (as an accumulation to the extent of the digits) ten, (fif-, seven-) teen.', 'masculine of term עֲשָׂרָה; from 6237;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3665}/[H3665]', 'inflected', 'heb', 'כָּנַע', '["kânaʻ"]', '["and/ I will subdue","and/ he humbled","and/ he humbled himself","and/ he subdued","and/ it was subdued","and/ they humbled themselves","and/ they were humbled","and/ they were subdued","and/ you humbled yourself","and/ you subdued"]', '["v"]', 'properly, to bend the knee; hence, to humiliate, vanquish bring down (low), into subjection, under, humble (self), subdue.', 'a primitive root;');
