INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2674G}/[H2691]', 'inflected', 'heb', 'חָצוֹר', '["Châtsôwr"]', '["in/ Hazor"]', '["n-pr-loc"]', 'Chatsor, the name (thus simply) of two places in Palestine and of one in Arabia Hazor.', 'a collective form of 2691; village;');
