INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2800}/[H2799]', 'inflected', 'heb', 'חֲרֹשֶׁת', '["Chărôsheth"]', '["in/ Harosheth"]', '["n-pr-loc"]', 'Charosheth, a place in Palestine Harosheth.', 'the same as 2799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1471H}/[H1465]', 'lemma', 'heb', 'גּוֹי', '["gôwy"]', '["Haggoyim"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2394}/[H2392]', 'inflected', 'heb', 'חׇזְקָה', '["chozqâh"]', '["by/ force","with/ force","with/ strength"]', '["n-f"]', 'vehemence (usually in a bad sense) force, mightily, repair, sharply.', 'feminine of 2392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1683H}/[H1682]', 'inflected', 'heb', 'דְּבּוֹרָה', '["Dᵉbôwrâh"]', '["and/ Deborah"]', '["n-pr-f"]', 'Deborah, the name of two Hebrewesses Deborah.', 'or (shortened) דְּבֹרָה; the same as 1682;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5031}/[H5030]', 'lemma', 'heb', 'נְבִיאָה', '["nᵉbîyʼâh"]', '["a prophetess"]', '["n-f"]', 'a prophetess or (generally) inspired woman; by implication, a poetess; by association a prophet''s wife prophetess.', 'feminine of 5030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3941}/[H3940]', 'lemma', 'heb', 'לַפִּידוֹת', '["Lappîydôwth"]', '["Lappidoth"]', '["n-pr-f"]', 'Lappidoth, the husband of Deborah Lappidoth.', 'feminine plural of 3940;');
