INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1683H}/[H1682]', 'lemma', 'heb', 'דְּבּוֹרָה', '["Dᵉbôwrâh"]', '["Deborah","O Deborah"]', '["n-pr-f"]', 'Deborah, the name of two Hebrewesses Deborah.', 'or (shortened) דְּבֹרָה; the same as 1682;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7414G}/[H7413]', 'inflected', 'heb', 'רָמָה', '["Râmâh"]', '["<the>/ Ramah"]', '["n-pr-loc"]', 'Ramah, the name of four places in Palestine Ramah.', 'the same as 7413;');
