INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0042}/[H1]', 'lemma', 'heb', 'אֲבִינֹעַם', '["ʼĂbîynôʻam"]', '["Abinoam"]', '["n-pr-m"]', 'Abinoam, an Israelite Abinoam.', 'from 1 and 5278; father of pleasantness (i.e. gracious);');
