INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1121G}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ any of/ [the] descendants of","and/ any of/ [the] people of","and/ from/ [the] people of","and/ of/ [the] descendants of","and/ of/ [the] sons of","and/ some of/ [the] descendants of","and/ some of/ [the] sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7028}/[H6983]', 'lemma', 'heb', 'קִישׁוֹן', '["Qîyshôwn"]', '["Kishon"]', '["n-pr-loc"]', 'Kishon, a river of Palestine Kishon, Kison.', 'from 6983; winding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1995A}/H9023/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["multitude/ his"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1301}/[H1300]', 'lemma', 'heb', 'בָּרָק', '["Bârâq"]', '["Barak","O Barak"]', '["n-pr-m"]', 'Barak, an Israelite Barak.', 'the same as 1300;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8597}/H9021/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["honor/ your","splendor/ your"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
