INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7272}/H9023/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["[was] on/ feet/ his","at/ feet/ his","at/ foot/ his","by/ feet/ his","in/ feet/ his","on/ feet/ his","with/ feet/ his"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
