INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5493I}/H9012/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["turn aside/ !"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8063}/[H5564]', 'inflected', 'heb', 'שְׂמִיכָה', '["sᵉmîykâh"]', '["with the/ covering"]', '["n-f"]', 'a run (as sustaining the Oriental sitter) mantle.', 'from 5564;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6770}/[H6770]', 'lemma', 'heb', 'צָמֵא', '["tsâmêʼ"]', '["I am thirsty","it is thirsty","it thirsts","they were thirsty","they will be thirsty","you will be thirsty"]', '["v"]', 'to thirst (literally or figuratively) (be a-, suffer) thirst(-y).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2461}/[H2459]', 'inflected', 'heb', 'חָלָב', '["châlâb"]', '["<the>/ milk"]', '["n-m"]', 'milk (as the richness of kine) cheese, milk, sucking.', 'from the same as 2459;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7592}/H9032/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["and/ he will ask/ you"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760I}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ he imposed","and/ he put","and/ she put","and/ they [masc] had made","and/ they set themselves"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4718A}/[H5344]', 'inflected', 'heb', 'מַקֶּבֶת', '["maqqebeth"]', '["the/ hammer"]', '["n-f"]', 'properly, a perforator, i.e. a hammer (as piercing); also (intransitively) a perforation, i.e. a quarry hammer, hole.', 'from 5344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3814}/[H3813]', 'inflected', 'heb', 'לָאט', '["lâʼṭ"]', '["in <the>/ secrecy"]', '["n-m"]', 'properly, muffled, i.e. silently softly.', 'from 3813 (or perhaps for active participle of 3874);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7541}/H9023/[H7534]', 'inflected', 'heb', 'רַקָּה', '["raqqâh"]', '["[was] in/ temple/ his","in/ temple/ his"]', '["n-f"]', 'properly, thinness, i.e. the side of the head temple.', 'feminine of 7534;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7290}/[H7290]', 'lemma', 'heb', 'רָדַם', '["râdam"]', '["I was dazed","[one who] sleeps","[was] sleeping","[were] sleeping","dazed","sleeping"]', '["v"]', 'to stun, i.e. stupefy (with sleep or death) (be fast a-, be in a deep, cast into a dead, that) sleep(-er, -eth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5888}/[H5888]', 'inflected', 'heb', 'עָיֵף', '["ʻâyêph"]', '["and/ he was weary","and/ it was weary"]', '["v"]', 'to languish be wearied.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7200G}/H9031/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ I will show/ you"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H3489>', 'inflected', 'heb', 'והיתד', '["ve./hai./ya.Ted"]', '["and/ the/ peg"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7186}/[H7185]', 'inflected', 'heb', 'קָשֶׁה', '["qâsheh"]', '["and/ hard","and/ stern of"]', '["a"]', 'severe (in various applications) churlish, cruel, grievous, hard((-hearted), thing), heavy, impudent, obstinate, prevailed, rough(-ly), sore, sorrowful, stiff(necked), stubborn, in trouble.', 'from 7185;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7891}/[H7788]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["and/ she sang"]', '["v"]', 'to sing behold (by mistake for 7789), sing(-er, -ing man, -ing woman).', 'or (the original form) שׁוּר; (1 Samuel 18:6), a primitive root (rather identical with 7788 through the idea of strolling minstrelsy);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6544A}/[H6544]', 'inflected', 'heb', 'פָּרַע', '["pâraʻ"]', '["when/ acted as leaders"]', '["v"]', 'to loosen; by implication, to expose, dismiss; figuratively, absolve, begin avenge, avoid, bare, go back, let, (make) naked, set at nought, perish, refuse, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5068}/[H5068]', 'inflected', 'heb', 'נָדַב', '["nâdab"]', '["when/ volunteers"]', '["v"]', 'to impel; hence, to volunteer (as a soldier), to present spontaneously offer freely, be (give, make, offer self) willing(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7336}/[H7336]', 'lemma', 'heb', 'רָזַן', '["râzan"]', '["O rulers","rulers"]', '["v"]', 'probably to be heavy, i.e. (figuratively) honorable prince, ruler.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2167}/[H2168]', 'lemma', 'heb', 'זָמַר', '["zâmar"]', '["I will make music","I will sing praise","I will sing praises","I will sing praises to","let them make music","make music","sing praises","sing praises to","they sing praises to","to sing praises to"]', '["v"]', 'properly, to touch the strings or parts of a musical instrument, i.e. play upon it; to make music, accompanied by the voice; hence to celebrate in song and music give praise, sing forth praises, psalms.', 'a primitive root (perhaps identical with 2168 through the idea of striking with the fingers);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6805}/H9041/[H6805]', 'inflected', 'heb', 'צָעַד', '["tsâʻad"]', '["when/ marching/ you"]', '["v"]', 'to pace, i.e. step regularly; (upward) to mount; (along) to march; (down and causatively) to hurl bring, go, march (through), run over.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7493}/[H7493]', 'lemma', 'heb', 'רָעַשׁ', '["râʻash"]', '["I caused to tremble","[am] about to shake","[they were] quaking","[who] made shake","it has shaken","it quaked","it shakes","it shook","it will quake","it will shake","may it wave","they will quake","they will shake","will they quake","you have made quake"]', '["v"]', 'to undulate (as the earth, the sky, etc.; also a field of grain), particularly through fear; specifically, to spring (as a locust) make afraid, (re-) move, quake, (make to) shake, (make to) tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5197}/[H5197]', 'lemma', 'heb', 'נָטַף', '["nâṭaph"]', '["I will prophesy","[the] prophesier of","dripping","it dropped","they drip","they dripped","they dropped","they will prophesy","you must prophesy","you prophesy"]', '["v"]', 'to ooze, i.e. distil gradually; by implication, to fall in drops; figuratively, to speak by inspiration drop(-ping), prophesy(-et).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5645}/[H5743]', 'lemma', 'heb', 'עָב', '["ʻâb"]', '["[the] cloud[s]","[the] clouds","[the] dark cloud[s]","a cloud","clouds","dark cloud","dark clouds of"]', '["n-m"]', 'properly, an envelope, i.e. darkness (or density, 2 Chronicles 4:17); specifically, a (scud) cloud; also a copse clay, (thick) cloud, × thick, thicket. Compare 5672.', '(masculine and feminine); from 5743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5410B>', 'opaque', 'heb', 'נָתִיב', '["nâthîyb"]', '["[the] paths of","[the] pathways","[the] pathways of","a path","paths"]', '["n-m"]', 'a (beaten) track path(-way), × travel(-ler), way.', 'or (feminine) נְתִיבָה; or נְתִבָה; (Jeremiah 6:16), from an unused root meaning to tramp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6128}/[H6127]', 'lemma', 'heb', 'עֲקַלְקַל', '["ʻăqalqal"]', '["twisting"]', '["a"]', 'winding by(-way), crooked way.', 'from 6127;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6520}/[H6518]', 'lemma', 'heb', 'פְּרָזוֹן', '["pᵉrâzôwn"]', '["rural people"]', '["n-m"]', 'magistracy, i.e. leadership (also concretely, chieftains) village.', 'from the same as 6518;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H6965B}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["that/ I arose"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3901}/[H3898]', 'lemma', 'heb', 'לָחֶם', '["lâchem"]', '["bread"]', '["n-m"]', 'battle war.', 'from 3898,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7420>', 'inflected', 'heb', 'ורמחים', '["u./re.ma.Chim","va./Ro.mach","va./ro.Mach"]', '["and/ a spear","and/ spear","and/ spear[s]","and/ spears"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2710}/[H2710]', 'inflected', 'heb', 'חָקַק', '["châqaq"]', '["[is] for/ [the] commanders of"]', '["v"]', 'properly, to hack, i.e. engrave (Judges 5:14, to be a scribe simply); by implication, to enact (laws being cut in stone or metal tablets in primitive times) or (gen.) prescribe appoint, decree, governor, grave, lawgiver, note, pourtray, print, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5068}/[H5068]', 'inflected', 'heb', 'נָדַב', '["nâdab"]', '["those/ [who] volunteered","who/ volunteered"]', '["v"]', 'to impel; hence, to volunteer (as a soldier), to present spontaneously offer freely, be (give, make, offer self) willing(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6715}/[H6713]', 'lemma', 'heb', 'צָחֹר', '["tsâchôr"]', '["tawny"]', '["a"]', 'white white.', 'from the same as 6713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4055}/[H4058]', 'lemma', 'heb', 'מַד', '["mad"]', '["cloth garments"]', '["n-m"]', 'properly, extent, i.e. height; also a measure; by implication, a vesture (as measured); also a carpet armour, clothes, garment, judgment, measure, raiment, stature.', 'or מֵד; from 4058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7878}/[H7878]', 'lemma', 'heb', 'שִׂיחַ', '["sîyach"]', '["I meditate","I will complain","I will meditate","I will meditate on","complain","he meditates","tell","tell out","they speak","will he consider"]', '["v"]', 'to ponder, i.e. (by implication) converse (with oneself, and hence, aloud) or (transitively) utter commune, complain, declare, meditate, muse, pray, speak, talk (with).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6963H>', 'inflected', 'heb', 'מקלות', '["Mi./kol","mi./Kol","mi./kOl","mi./ko.Lot"]', '["from/ [the] sound","from/ [the] sound of","more than/ [the] sounds of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2686B}/[H2673]', 'lemma', 'heb', 'חָצַץ', '["châtsats"]', '["archers"]', '["v"]', 'properly, to chop into, pierce or sever; hence, to curtail, to distribute (into ranks); to shoot an arrow archer, × bands, cut off in the midst.', 'a primitive root (compare 2673); also as denominative from 2671');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4857}/[H7579]', 'lemma', 'heb', 'מַשְׁאָב', '["mashʼâb"]', '["[the] places for drawing water"]', '["n-m"]', 'a trough for cattle to drink from place of drawing water.', 'from 7579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8567}/[H8567]', 'lemma', 'heb', 'תָּנָה', '["tânâh"]', '["they will recount"]', '["v"]', 'to ascribe (praise), i.e. celebrate, commemorate lament, rehearse.', 'a primitive root (identical with through the idea of attributing honor);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6520}/H9023/[H6518]', 'inflected', 'heb', 'פְּרָזוֹן', '["pᵉrâzôwn"]', '["rural people/ his"]', '["n-m"]', 'magistracy, i.e. leadership (also concretely, chieftains) village.', 'from the same as 6518;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7892A}/[H7891]', 'lemma', 'heb', 'שִׁיר', '["shîyr"]', '["<the> song of","[the] song of","a song","a song of","song","songs of"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7617}/[H7617]', 'inflected', 'heb', 'שָׁבָה', '["shâbâh"]', '["and/ take captive"]', '["v"]', 'to transport into captivity (bring away, carry, carry away, lead, lead away, take) captive(-s), drive (take) away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7628B}/H9021/[H7618]', 'inflected', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["captive[s]/ your"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0117}/[H142]', 'inflected', 'heb', 'אַדִּיר', '["ʼaddîyr"]', '["of/ [the] nobles"]', '["a"]', 'wide or (generally) large; figuratively, powerful excellent, famous, gallant, glorious, goodly, lordly, mighty(-ier one), noble, principal, worthy.', 'from 142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1368}/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["[were] among the/ warriors","among the/ mighty [ones]","among the/ warriors","on the/ mighty [ones]","over/ warrior"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8328}/H9028/[H8327]', 'inflected', 'heb', 'שֶׁרֶשׁ', '["sheresh"]', '["root/ their"]', '["n-m"]', 'a root (literally or figuratively) bottom, deep, heel, root.', 'from 8327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5971B}/H9021/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["[was] among/ people<s>/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2074}/[H2082]', 'inflected', 'heb', 'זְבוּלוּן', '["Zᵉbûwlûwn"]', '["and/ from/ Zebulun"]', '["n-pr-m n-pr-loc"]', 'Zebulon, a son of Jacob; also his territory and tribe Zebulun.', 'or זְבֻלוּן; or זְבוּלֻן; from 2082; habitation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5608B}/[H5608]', 'lemma', 'heb', 'סָפַר', '["çâphar"]', '["[the] Sophrites","[the] scribe of","[was the] scribe","[was] a scribe","[was] secretary","[were] scribes","a muster-officer","a scribe","scribes"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8269}/H9020/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["and/ princes/ my"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6391}/[H6385]', 'inflected', 'heb', 'פְּלֻגָּה', '["pᵉluggâh"]', '["among/ [the] divisions of"]', '["n-f"]', 'a section division.', 'from 6385;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2711}/[H2710]', 'lemma', 'heb', 'חֵקֶק', '["chêqeq"]', '["decrees of","resolves of"]', '["n-m"]', 'an enactment, a resolution decree, thought.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0996H}/[H995]', 'lemma', 'heb', 'בֵּין', '["bêyn"]', '["among","between"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8292}/[H8319]', 'lemma', 'heb', 'שְׁרוּקָה', '["shᵉrûwqâh"]', '["[the] whistling of","whistling of"]', '["n-f"]', 'a whistling (in scorn); by analogy, a piping bleating, hissing.', 'or (by permutation) שְׁרִיקָה; feminine passive participle of 8319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6391}/[H6385]', 'inflected', 'heb', 'פְּלֻגָּה', '["pᵉluggâh"]', '["to/ [the] divisions of"]', '["n-f"]', 'a section division.', 'from 6385;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2714}/[H2713]', 'lemma', 'heb', 'חֵקֶר', '["chêqer"]', '["[is] inquiry","inquiry","searchings of"]', '["n-m"]', 'examination, enumeration, deliberation finding out, number, (un-) search(-able, -ed, out, -ing).', 'from 2713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1835G}/[H1777]', 'inflected', 'heb', 'דָּן', '["Dân"]', '["and/ Dan"]', '["n-pr-m"]', 'Dan, one of the sons of Jacob; also the tribe descended from him, and its territory; likewise a place in Palestine colonized by them Daniel', 'from 1777; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4664}/H9023/[H6555]', 'inflected', 'heb', 'מִפְרָץ', '["miphrâts"]', '["landing places/ his"]', '["n-m"]', 'a break (in the shore), i.e. a haven breach.', 'from 6555;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2778A}/[H2779]', 'lemma', 'heb', 'חָרַף', '["châraph"]', '["I defy","[one who] taunts","[which] it despised","have you taunted","he has defied","he reproaches","he taunted","he will reproach","it reproaches","they have reproached","they reproached","will he taunt","you have defied","you have taunted","you taunted"]', '["v"]', 'to pull off, i.e. (by implication) to expose (as by stripping); specifically, to betroth (as if a surrender); figuratively, to carp at, i.e. defame; to spend the winter betroth, blaspheme, defy, jeopard, rail, reproach, upbraid.', 'a primitive root; also denominative (from 2779)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4791}/[H7311]', 'lemma', 'heb', 'מָרוֹם', '["mârôwm"]', '["[are] height","[the] height","[the] height of","[the] height[s] of","[the] heights","[the] heights of","[the] noble[s] of","[to the] height of","a high place","height","high place","high places"]', '["n-m"]', 'altitude, i.e. concretely (an elevated place), abstractly (elevation, figuratively (elation), or adverbially (aloft) (far) above, dignity, haughty, height, (most, on) high (one, place), loftily, upward.', 'from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8590>', 'inflected', 'heb', 'בתענך', '["be./ta''.Nakh"]', '["at/ Taanach"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4546}/H9028/[H5549]', 'inflected', 'heb', 'מְסִלָּה', '["mᵉçillâh"]', '["from/ highways/ their"]', '["n-f"]', 'a thoroughfare (as turnpiked), literally or figuratively; specifically a viaduct, a staircase causeway, course, highway, path, terrace.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1640}/H9038/[H1640]', 'inflected', 'heb', 'גָּרַף', '["gâraph"]', '["it swept away/ them"]', '["v"]', 'to bear off violently sweep away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6917}/[H6923]', 'lemma', 'heb', 'קָדוּם', '["qâdûwm"]', '["ancient times"]', '["n-m"]', 'a pristine hero ancient.', 'passive participle of 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5797}/[H5810]', 'lemma', 'heb', 'עֹז', '["ʻôz"]', '["[is] strength","[the] strength of","[who] strength","strength"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1986}/[H1986]', 'lemma', 'heb', 'הָלַם', '["hâlam"]', '["[those] struck down of","a striker of","they have struck down","they struck"]', '["v"]', 'to strike down; by implication, to hammer, stamp, conquer, disband beat (down), break (down), overcome, smite (with the hammer).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1726}/[H1725]', 'inflected', 'heb', 'דַּהֲהַר', '["dahăhar"]', '["from/ [the] galloping"]', '["n-f"]', 'a gallop pransing.', 'by reduplication from 1725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1726}/[H1725]', 'lemma', 'heb', 'דַּהֲהַר', '["dahăhar"]', '["[the] galloping of"]', '["n-f"]', 'a gallop pransing.', 'by reduplication from 1725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0047H}/H9023/[H46]', 'inflected', 'heb', 'אַבִּיר', '["ʼabbîyr"]', '["mighty [horses]/ his","mighty [horses]/ its"]', '["a-m"]', 'angel, bull, chiefest, mighty (one), stout(-hearted), strong (one), valiant.', 'for 46');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4789>', 'opaque', 'heb', 'מֵרוֹז', '["Mêrôwz"]', '["Meroz"]', '["n-pr-loc"]', 'Meroz, a place in Palestine Meroz.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5833}/[H5828]', 'inflected', 'heb', 'עֶזְרָה', '["ʻezrâh"]', '["for/ help","to/ [the] help of","to/ help"]', '["n-f"]', 'aid help(-ed, -er).', 'or עֶזְרָת; (Psalm 60:11 (13); Psalm 108:12 (13)), feminine of 5828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0802G}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["from/ [the] women of","from/ a woman","from/ a woman of","from/ women","more than/ a woman of","more than/ women"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5602>', 'inflected', 'heb', 'בספל', '["be./Se.fel"]', '["in/ a bowl of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3489>', 'inflected', 'heb', 'ליתד', '["la/i.ya.Ted"]', '["to the/ peg"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3225G}/H9024/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["and/ right [hand]/ her"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1989}/[H1986]', 'inflected', 'heb', 'הַלְמוּת', '["halmûwth"]', '["to/ a hammer of"]', '["n-f"]', 'a hammer (or mallet) hammer.', 'from 1986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6001A}/[H5998]', 'lemma', 'heb', 'עָמֵל', '["ʻâmêl"]', '["a laborer","a sufferer","workmen"]', '["n-m a"]', 'toiling; concretely, a laborer; figuratively, sorrowful that laboureth, that is a misery, had taken (labour), wicked, workman.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1986}/[H1986]', 'inflected', 'heb', 'הָלַם', '["hâlam"]', '["and/ she struck"]', '["v"]', 'to strike down; by implication, to hammer, stamp, conquer, disband beat (down), break (down), overcome, smite (with the hammer).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4277}/[H4277]', 'lemma', 'heb', 'מָחַק', '["mâchaq"]', '["she shattered"]', '["v"]', 'to crush smite off.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7541}/H9023/[H7534]', 'inflected', 'heb', 'רַקָּה', '["raqqâh"]', '["temple/ his"]', '["n-f"]', 'properly, thinness, i.e. the side of the head temple.', 'feminine of 7534;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7703}/[H7703]', 'lemma', 'heb', 'שָׁדַד', '["shâdad"]', '["<of> [which] it was devastated","O devastated [one]","[have been] destroyed","[is] about to destroy","[is] about to devastate","[is] destroying","[one who] assaults","[the] destroyer","[the] destroyer of","a destroyer","destroyed","destroyers","destroyers of","destroying","he will destroy","it has been devastated","it will be devastated","they have been devastated","utterly <devastate>","we are devastated","we have been devastated","you devastate","you will be destroyed"]', '["v"]', 'properly, to be burly, i.e. (figuratively) powerful (passively, impregnable); by implication, to ravage dead, destroy(-er), oppress, robber, spoil(-er), × utterly, (lay) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8259}/[H8259]', 'lemma', 'heb', 'שָׁקַף', '["shâqaph"]', '["I looked down","he has looked down","he looks down","he will look down","it has looked down","it looks down","she looked down"]', '["v"]', 'properly, to lean out (of a window), i.e. (by implication) peep or gaze (passively, be a spectacle) appear, look (down, forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2980}/[H2980]', 'inflected', 'heb', 'יָבַב', '["yâbab"]', '["and/ she lamented"]', '["v"]', 'to bawl cry out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0822>', 'inflected', 'heb', 'האשנב', '["ha./''esh.Nav"]', '["the/ widow-lattice"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8282}/H9024/[H8269]', 'inflected', 'heb', 'שָׂרָה', '["sârâh"]', '["noble ladies/ her"]', '["n-f"]', 'a mistress, i.e. female noble lady, princess, queen.', 'feminine of 8269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725M}/[H7725]', 'lemma', 'heb', 'שׁוּב', '["shûwb"]', '["[one who] bring back","[one who] brings back","[who] bring back","she brought back","will I bring back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0561}/H9024/[H559]', 'inflected', 'heb', 'אֵמֶר', '["ʼêmer"]', '["[who] words/ her","sayings/ her","words/ her"]', '["n-m"]', 'something said answer, × appointed unto him, saying, speech, word.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7356A}/[H7355]', 'lemma', 'heb', 'רַחַם', '["racham"]', '["[the] womb","a womb","two wombs"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6648>', 'opaque', 'heb', 'צֶבַע', '["tsebaʻ"]', '["colored cloth","colored cloth<s>"]', '["n-m"]', 'a dye divers, colours.', 'from an unused root meaning to dip (into coloring fluid);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7553}/[H7551]', 'lemma', 'heb', 'רִקְמָה', '["riqmâh"]', '["embroidered material","embroidered material<s>","multicolored cloth"]', '["n-f"]', 'variegation of color; specifically, embroidery broidered (work), divers colours, (raiment of) needlework (on both sides).', 'from 7551;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6677A}/[H6696]', 'inflected', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["for/ [the] necks of"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0157H}/H9033/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ [those who] love/ him"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3318K}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["[be] as/ [the] going out of"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1369}/H9023/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["by/ might/ his","for/ mighty deeds/ his","in/ might/ his","in/ strength/ its"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4492}/[H5102]', 'inflected', 'heb', 'מִנְהָרָה', '["minhârâh"]', '["the/ dens"]', '["n-f"]', 'properly, a channel or fissure, i.e. (by implication) a cavern den.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4679}/[H6679]', 'inflected', 'heb', 'מְצַד', '["mᵉtsad"]', '["the/ strongholds"]', '["n-f"]', 'a fastness (as a covert of ambush) castle, fort, (strong) hold, munition.', 'or מְצָד; or (feminine) מְצָדָה; from 6679;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6924A}/[H6923]', 'lemma', 'heb', 'קֶדֶם', '["qedem"]', '["[the] east"]', '["n-m adv"]', 'the front, of place (absolutely, the fore part, relatively the East) or time (antiquity); often used adverbially (before, anciently, eastward) aforetime, ancient (time), before, east (end, part, side, -ward), eternal, × ever(-lasting), forward, old, past. Compare 6926.', 'or קֵדְמָה; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2981}/[H2986]', 'lemma', 'heb', 'יְבוּל', '["yᵉbûwl"]', '["[is] produce","[the] produce of"]', '["n-m"]', 'produce, i.e. a crop or (figuratively) wealth fruit, increase.', 'from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4735}/H9028/[H7069]', 'inflected', 'heb', 'מִקְנֶה', '["miqneh"]', '["and/ livestock/ their"]', '["n-m"]', 'something bought, i.e. property, but only live stock; abstractly, acquisition cattle, flock, herd, possession, purchase, substance.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0168G}/H9028/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["and/ tents/ their"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1581}/H9028/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["and/ [belonged] to/ camels/ their","and/ to/ camels/ their"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1809}/[H1802]', 'inflected', 'heb', 'דָּלַל', '["dâlal"]', '["and/ it became low"]', '["v"]', 'to slacken or be feeble; figuratively, to be oppressed bring low, dry up, be emptied, be not equal, fail, be impoverished, be made thin.', 'a primitive root (compare 1802);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2199}/[H2199]', 'lemma', 'heb', 'זָעַק', '["zâʻaq"]', '["I cry out","I will cry out","cry out","do you cry out","it cried out","it cries out","it will cry out","people cry out","she cries out","summon","they cried out","they cry out","they had cried out","they have cried out","they were called together","they will cry out","you have been called together"]', '["v"]', 'to shriek (from anguish or danger); by analogy, (as a herald) to announce or convene publicly assemble, call (together), (make a) cry (out), come with such a company, gather (together), cause to be proclaimed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3027H}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ from/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3905}/H9036/[H3905]', 'inflected', 'heb', 'לָחַץ', '["lâchats"]', '["[those who] oppressed/ you"]', '["v"]', 'properly, to press, i.e. (figuratively) to distress afflict, crush, force, hold fast, oppress(-or), thrust self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0559}/H9012/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["and/ I said/ !"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963A>/H9020\', 'inflected', 'heb', 'בקולי פ', '["be./ko.L/i"]', '["to/ voice/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6084H}/[H6082]', 'inflected', 'heb', 'עׇפְרָה', '["ʻOphrâh"]', '["[is] in/ Ophrah","[was] in/ Ophrah","in/ Ophrah"]', '["n-pr-m n-pr-loc"]', 'Ophrah, the name of an Israelite and of two places in Palestine Ophrah.', 'feminine of 6082; female fawn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3101G}/[H3060]', 'inflected', 'heb', 'יוֹאָשׁ', '["Yôwʼâsh"]', '["[belonged] to/ Joash"]', '["n-pr-m"]', 'Joash, the name of six Israelites Joash.', 'or יֹאָשׁ; (2 Chronicles 24:1), a form of 3060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0033}/[H44]', 'lemma', 'heb', 'אֲבִי הָעֶזְרִי', '["ʼĂbîy hâ-ʻEzrîy"]', '["[the] Abi-","of [the] Abi-"]', '["n-pr-m"]', 'an Abiezrite or descendant of Abiezer Abiezrite.', 'from 44 with the article inserted; father of the Ezrite;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0033}/[H44]', 'inflected', 'heb', 'אֲבִי הָעֶזְרִי', '["ʼĂbîy hâ-ʻEzrîy"]', '["<the>/ -ezrite"]', '["n-pr-m"]', 'an Abiezrite or descendant of Abiezer Abiezrite.', 'from 44 with the article inserted; father of the Ezrite;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1439}/[H1438]', 'inflected', 'heb', 'גִּדְעוֹן', '["Gidʻôwn"]', '["and/ Gideon"]', '["n-pr-m"]', 'Gidon, an Israelite Gideon.', 'from 1438; feller (i.e. warrior);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1660}/[H5059]', 'inflected', 'heb', 'גַּת', '["gath"]', '["in the/ winepress","in/ a winepress"]', '["n-f"]', 'a wine-press (or vat for holding the grapes in pressing them) (wine-) press (fat).', 'probably from 5059 (in the sense of treading out grapes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200L}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ he appeared"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1439}/[H1438]', 'lemma', 'heb', 'גִּדְעוֹן', '["Gidʻôwn"]', '["Gideon","[is] Gideon"]', '["n-pr-m"]', 'Gidon, an Israelite Gideon.', 'from 1438; feller (i.e. warrior);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6381}/H9023/[H6381]', 'inflected', 'heb', 'פָּלָא', '["pâlâʼ"]', '["wonders/ his"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5203}/H9035/[H5203]', 'inflected', 'heb', 'נָטַשׁ', '["nâṭash"]', '["he abandon/ us","he has abandoned/ us"]', '["v"]', 'properly, to pound, i.e. smite; by implication (as if beating out, and thus expanding) to disperse; also, to thrust off, down, out or upon (inclusively, reject, let alone, permit, remit, etc.) cast off, drawn, let fall, forsake, join (battle), leave (off), lie still, loose, spread (self) abroad, stretch out, suffer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414G}/H9035/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ he has given/ us"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3709G}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["by the/ hand","in the/ palm","in/ [the] hand","in/ [the] hand of","in/ [the] palm of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3709G}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["from/ [the] hand of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0505H}/H9020/[H504]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["family/ my"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1800}/[H1809]', 'inflected', 'heb', 'דַּל', '["dal"]', '["<the>/ poor","[is] the/ weak"]', '["a"]', 'properly, dangling, i.e. (by implication) weak or thin lean, needy, poor (man), weaker.', 'from 1809;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4519G}/[H5382]', 'inflected', 'heb', 'מְנַשֶּׁה', '["Mᵉnashsheh"]', '["in/ Manasseh"]', '["n-pr-m"]', 'Menashsheh, a grandson of Jacob, also the tribe descended from him, and its territory Manasseh.', 'from 5382; causing to forget;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H0859A}/[H859]', 'inflected', 'heb', 'אַתָּה', '["ʼattâh"]', '["that/ you"]', '["p"]', 'thou and thee, or (plural) ye and you thee, thou, ye, you.', 'or (shortened); אַתָּ; or אַת; feminine (irregular) sometimes אַתִּי; plural masculine אַתֶּם; feminine אַתֶּן; or אַתֵּנָהlemma אתֵּנָה missing vowel, corrected to אַתֵּנָה; or אַתֵּנָּה; a primitive pronoun of the second person;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4839}/[H4838]', 'inflected', 'heb', 'מָרָק', '["mârâq"]', '["and/ the/ broth"]', '["n-m"]', 'soup (as if a rinsing) broth. See also 6564.', 'from 4838;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5066H}\/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["and/ he brought [them] near"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1975}/[H1976]', 'lemma', 'heb', 'הַלָּז', '["hallâz"]', '["this"]', '["d"]', 'this or that side, that, this.', 'from 1976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4839}/[H4838]', 'inflected', 'heb', 'מָרָק', '["mârâq"]', '["the/ broth"]', '["n-m"]', 'soup (as if a rinsing) broth. See also 6564.', 'from 4838;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4938B}/[H4937]', 'inflected', 'heb', 'מִשְׁעֵנָה', '["mishʻênâh"]', '["the/ staff"]', '["n-f"]', 'support (abstractly), i.e. (figuratively) sustenance or (concretely) a walking-stick staff.', 'or מִשְׁעֶנֶת; feminine of 4937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4682}/[H4711]', 'inflected', 'heb', 'מַצָּה', '["matstsâh"]', '["and/ <in> the/ unleavened bread<s>"]', '["n-f"]', 'properly, sweetness; concretely, sweet (i.e. not soured or bittered with yeast); specifically, an unfermented cake or loaf, or (elliptically) the festival of Passover (because no leaven was then used) unleaved (bread, cake), without leaven.', 'from 4711 in the sense of greedily devouring for sweetness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4397H>', 'inflected', 'heb', 'ומלאך', '["u./mal.''Akh"]', '["and/ [the] angel of","and/ an angel"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5869H}/H9023/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["from/ eyes/ his"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965H}/[H7999]', 'lemma', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["[is] peace"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0033}\/[H44]', 'inflected', 'heb', 'אֲבִי הָעֶזְרִי', '["ʼĂbîy hâ-ʻEzrîy"]', '["<the>/ -ezrite[s]"]', '["n-pr-m"]', 'an Abiezrite or descendant of Abiezer Abiezrite.', 'from 44 with the article inserted; father of the Ezrite;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2040}/[H2040]', 'inflected', 'heb', 'הָרַס', '["hâraç"]', '["and/ I will tear down","and/ they will be thrown down","and/ they will be torn down","and/ they will tear down","and/ you will tear down"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4581}/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["the/ place of refuge","the/ stronghold"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4634}/[H4633]', 'inflected', 'heb', 'מַעֲרָכָה', '["maʻărâkâh"]', '["in the/ battle line","in the/ row"]', '["n-f"]', 'an arrangement; concretely, a pile; specifically a military array army, fight, be set in order, ordered place, rank, row.', 'feminine of 4633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6086G}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["among/ wood<s>","in/ wood<s> of","with <the>/ wood","with/ [the] wood<s> of","with/ wood<s> of"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0842}/[H833]', 'inflected', 'heb', 'אֲשֵׁרָה', '["ʼăshêrâh"]', '["and/ the/ Asherah pole","and/ the/ Asherah poles"]', '["n-pr-f"]', 'Asherah (or Astarte) a Phoenician goddess; also an image of the same grove. Compare 6253.', 'or אֲשֵׁירָה; from 833; happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1129}/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["that/ will be built","the/ [ones who] rebuilt","the/ builders","which/ had been built","which/ was built","who/ builds","who/ were rebuilding"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3101G}/[H3060]', 'lemma', 'heb', 'יוֹאָשׁ', '["Yôwʼâsh"]', '["Joash"]', '["n-pr-m"]', 'Joash, the name of six Israelites Joash.', 'or יֹאָשׁ; (2 Chronicles 24:1), a form of 3060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0859D}/[H859]', 'inflected', 'heb', 'אַתָּה', '["ʼattâh"]', '["¿/ you"]', '["p"]', 'thou and thee, or (plural) ye and you thee, thou, ye, you.', 'or (shortened); אַתָּ; or אַת; feminine (irregular) sometimes אַתִּי; plural masculine אַתֶּם; feminine אַתֶּן; or אַתֵּנָהlemma אתֵּנָה missing vowel, corrected to אַתֵּנָה; or אַתֵּנָּה; a primitive pronoun of the second person;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3467}/H9013/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["will you deliver/ !","you will be delivered/ !"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4196}/H9023/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["altar/ his","altars/ his","altars/ its"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3378}/[H7378]', 'lemma', 'heb', 'יְרֻבַּעַל', '["Yᵉrubbaʻal"]', '["Jerub-Baal"]', '["n-pr-m"]', 'Jerubbaal, a symbolic name of Gideon Jerubbaal.', 'from 7378 and 1168; Baal will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4196}/H9023\/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["altar/ his"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4397G>', 'inflected', 'heb', 'ומלאכים', '["u./mal.''Akh","u./mal.''a.Khim"]', '["and/ [the] messenger of","and/ a messenger","and/ messengers"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0836}/[H833]', 'inflected', 'heb', 'אָשֵׁר', '["ʼÂshêr"]', '["in/ Asher"]', '["n-pr"]', 'Asher, a son of Jacob, and the tribe descended from him, with its territory; also a place in Palestine Asher', 'from 833, happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2074}/[H2082]', 'inflected', 'heb', 'זְבוּלוּן', '["Zᵉbûwlûwn"]', '["and/ in/ Zebulun"]', '["n-pr-m n-pr-loc"]', 'Zebulon, a son of Jacob; also his territory and tribe Zebulun.', 'or זְבֻלוּן; or זְבוּלֻן; from 2082; habitation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5321G}/[H6617]', 'inflected', 'heb', 'נַפְתָּלִי', '["Naphtâlîy"]', '["and/ in/ Naphtali"]', '["n-pr-m n-pr-loc"]', 'Naphtali, a son of Jacob, with the tribe descended from him, and its territory Naphtali.', 'from 6617; my wrestling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1492}/[H1494]', 'lemma', 'heb', 'גָּזַּה', '["gâzzah"]', '["[the] fleece of"]', '["n-f"]', 'a fleece fleece.', 'feminine from 1494;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1492}/[H1494]', 'inflected', 'heb', 'גָּזַּה', '["gâzzah"]', '["the/ fleece"]', '["n-f"]', 'a fleece fleece.', 'feminine from 1494;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2115}/[H6695]', 'inflected', 'heb', 'זוּר', '["zûwr"]', '["and/ he squeezed out"]', '["v"]', 'to press together, tighten close, rush, thrust together.', 'a primitive root (compare 6695);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5602>', 'inflected', 'heb', 'הספל', '["ha./Se.fel"]', '["the/ bowl"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1492}/[H1494]', 'inflected', 'heb', 'גָּזַּה', '["gâzzah"]', '["by the/ fleece"]', '["n-f"]', 'a fleece fleece.', 'feminine from 1494;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2919}\/[H2926]', 'inflected', 'heb', 'טַל', '["ṭal"]', '["dew"]', '["n-m"]', 'dew (as covering vegetation) dew.', 'from 2926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5878}/[H5869]', 'lemma', 'heb', 'עֵין חֲרֹד', '["ʻÊyn Chărôd"]', '["En","Harod"]', '["n-pr-loc"]', 'En-Charod, a place in Palestine well of Harod.', 'from 5869 and a derivative of 2729; fountain of trembling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4264}/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["and/ [the] camp of"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1389I}/[H1387]', 'inflected', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["from/ [the] hill of","from/ [the] hills","more than/ [the] hills"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4176H}/[H4175]', 'inflected', 'heb', 'מוֹרֶה', '["Môwreh"]', '["<the>/ Moreh"]', '["n-m"]', 'Moreh, a Canaanite; also a hill (perhaps named from him) Moreh.', 'or מֹרֶה; the same as 4175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2730}/[H2729]', 'inflected', 'heb', 'חָרֵד', '["chârêd"]', '["and/ a [person] trembling","and/ trembling"]', '["a"]', 'fearful; also reverential afraid, trembling.', 'from 2729;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6852}/[H6852]', 'inflected', 'heb', 'צָפַר', '["tsâphar"]', '["and/ he may go"]', '["v"]', 'to skip about, i.e. return depart early.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1568K}/[H1567]', 'inflected', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["<the>/ Gilead"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7604}\/[H7604]', 'inflected', 'heb', 'שָׁאַר', '["shâʼar"]', '["they remained"]', '["v"]', 'properly, to swell up, i.e. be (causatively, make) redundant leave, (be) left, let, remain, remnant, reserve, the rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6884}/H9033/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["so/ I may test/ it"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4325G}\/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["the/ water"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3952}/[H3952]', 'lemma', 'heb', 'לָקַק', '["lâqaq"]', '["he will lap up","it laps up","they licked up","they will lick up"]', '["v"]', 'to lick or lap lap, lick.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3956G}/H9023/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["in/ tongue/ his","with/ tongue/ his"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3611>', 'inflected', 'heb', 'הכלבים', '["ha./Ke.lev","ha./ke.la.Vim"]', '["the/ dog","the/ dogs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3952}/[H3952]', 'inflected', 'heb', 'לָקַק', '["lâqaq"]', '["those/ [who] lapped","who/ lapped"]', '["v"]', 'to lick or lap lap, lick.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310G}/H9028/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["mouth/ their"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1290}/H9028/[H1288]', 'inflected', 'heb', 'בֶּרֶךְ', '["berek"]', '["knees/ their"]', '["n-f"]', 'a knee knee.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7969}/[H7969]', 'inflected', 'heb', 'שָׁלוֹשׁ', '["shâlôwsh"]', '["[was] among/ three","among the/ three","among/ three","by/ three","in/ thir-","in/ three","on/ [day] thir-","on/ [day] three","on/ thir-","with the/ three","with/ three"]', '["n"]', 'three; occasionally (ordinal) third, or (multiple) thrice fork, often(-times), third, thir(-teen, -teenth), three, thrice. Compare 7991.', 'or שָׁלֹשׁ; masculine שְׁלוֹשָׁה; or שְׁלֹשָׁה; a primitive number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7782}/H9028/[H8231]', 'inflected', 'heb', 'שׁוֹפָר', '["shôwphâr"]', '["trumpets/ their"]', '["n-m"]', 'a cornet (as giving a clear sound) or curved horn cornet, trumpet.', 'or שֹׁפָר; from 8231 in the original sense of incising;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7969}/[H7969]', 'inflected', 'heb', 'שָׁלוֹשׁ', '["shâlôwsh"]', '["and/ on/ [the] three","and/ on/ three"]', '["n"]', 'three; occasionally (ordinal) third, or (multiple) thrice fork, often(-times), third, thir(-teen, -teenth), three, thrice. Compare 7991.', 'or שָׁלֹשׁ; masculine שְׁלוֹשָׁה; or שְׁלֹשָׁה; a primitive number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6010R}\/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["in the/ valley"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6513}/[H6288]', 'inflected', 'heb', 'פֻּרָה', '["Purâh"]', '["and/ Purah"]', '["n-pr-m"]', 'Purah, an Israelite Phurah.', 'for 6288; foliage;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5288}/H9021/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["own young men/ your","servant/ your"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2571}/[H2570]', 'inflected', 'heb', 'חָמֻשׁ', '["châmush"]', '["those/ arrayed for battle"]', '["a"]', 'staunch, i.e. able-bodied soldiers armed (men), harnessed.', 'passive participle of the same as 2570;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4080H}/[H4079]', 'inflected', 'heb', 'מִדְיָן', '["Midyân"]', '["and/ Midian"]', '["n-pr-m n-pr-loc"]', 'Midjan, a son of Abraham; also his country and (collectively) his descendants Midian, Midianite.', 'the same as 4079;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0697}/[H7235]', 'inflected', 'heb', 'אַרְבֶּה', '["ʼarbeh"]', '["like <the>/ locust","like <the>/ locust[s]"]', '["n-m"]', 'a locust (from its rapid increase) grasshopper, locust.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5921A}/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["that/ [is] on","that/ [were] on"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6742}/[H6749]', 'lemma', 'heb', 'צְלוּל', '["tsᵉlûwl"]', '["a round loaf of"]', '["n-m"]', 'a (round or flattened) cake cake.', 'from 6749 in the sense of rolling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2015}/H9033/[H2015]', 'inflected', 'heb', 'הָפַךְ', '["hâphak"]', '["and/ it overturned/ it"]', '["v"]', 'to turn about or over; by implication, to change, overturn, return, pervert × become, change, come, be converted, give, make (a bed), overthrow (-turn), perverse, retire, tumble, turn (again, aside, back, to the contrary, every way).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7667}/H9023/[H7665]', 'inflected', 'heb', 'שֶׁבֶר', '["sheber"]', '["interpretation/ its"]', '["n-m"]', 'a fracture, figuratively, ruin; specifically, a solution (of a dream) affliction, breach, breaking, broken(-footed, -handed), bruise, crashing, destruction, hurt, interpretation, vexation.', 'or שֵׁבֶר; from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218K>', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["[the] chiefs of","[the] head of","companies"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3537>', 'inflected', 'heb', 'וכדים', '["ve./kha.Dim"]', '["and/ jars"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3537>', 'inflected', 'heb', 'הכדים', '["ha./ka.Dim"]', '["the/ jars"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1439}\/[H1438]', 'inflected', 'heb', 'גִּדְעוֹן', '["Gidʻôwn"]', '["and/ for/ Gideon"]', '["n-pr-m"]', 'Gidon, an Israelite Gideon.', 'from 1438; feller (i.e. warrior);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0821}/[H8104]', 'inflected', 'heb', 'אַשְׁמֻרָה', '["ʼashmurâh"]', '["the/ watch"]', '["n-f"]', 'a night watch watch.', 'or אַשׁמוּרָה; or אַשׁמֹרֶת; (feminine) from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965K}/[H6965]', 'lemma', 'heb', 'קוּם', '["qûwm"]', '["certainly <to station>","they had stationed"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8104H}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["the/ watchmen","who/ guarded","who/ kept watch"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5310A}/[H5310]', 'inflected', 'heb', 'נָפַץ', '["nâphats"]', '["and/ they smashed"]', '["v"]', 'to dash to pieces, or scatter be beaten in sunder, break (in pieces), broken, dash (in pieces), cause to be discharged, dispersed, be overspread, scatter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7218K>', 'inflected', 'heb', 'הראשים', '["ha./Rosh","ha./ra.Shim"]', '["the/ companies","the/ company"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8040G}/H9028/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["left/ their"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3940>', 'inflected', 'heb', 'בלפידים', '["ba./la.pi.Dim"]', '["on the/ torches"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3225G}/H9028/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["right/ their"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8628}/[H8628]', 'inflected', 'heb', 'תָּקַע', '["tâqaʻ"]', '["to/ give a blast"]', '["v"]', 'to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1439}/[H1438]', 'inflected', 'heb', 'גִּדְעוֹן', '["Gidʻôwn"]', '["and/ for/ Gideon","and/ to/ Gideon"]', '["n-pr-m"]', 'Gidon, an Israelite Gideon.', 'from 1438; feller (i.e. warrior);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1029}/[H1004]', 'lemma', 'heb', 'בֵּית הַשִּׁטָּה', '["Bêyth hash-Shiṭṭâh"]', '["Beth"]', '["n-pr-loc"]', 'Beth-hash-Shittah, a place in Palestine Beth-shittah.', 'from 1004 and 7848 with the article interposed; house of the acacia;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1029}/[H1004]', 'inflected', 'heb', 'בֵּית הַשִּׁטָּה', '["Bêyth hash-Shiṭṭâh"]', '["<of the>/ Shittah"]', '["n-pr-loc"]', 'Beth-hash-Shittah, a place in Palestine Beth-shittah.', 'from 1004 and 7848 with the article interposed; house of the acacia;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6888}/[H6868]', 'lemma', 'heb', 'צְרֵרָה', '["Tsᵉrêrâh"]', '["towards Zererah"]', '["n-pr-loc"]', 'Tsererah for Tseredah Zererath.', 'apparently by erroneous transcription for 6868;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0065}/[H58]', 'lemma', 'heb', 'אָבֵל מְחוֹלָה', '["ʼÂbêl Mᵉchôwlâh"]', '["Abel","Meholah"]', '["n-pr-loc"]', 'Abel-Mecholah, a place in Palestine Abel-meholah.', 'from 58 and 4246; meadow of dancing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2888>', 'opaque', 'heb', 'טַבַּת', '["Ṭabbath"]', '["Tabbath"]', '["n-pr-loc"]', 'Tabbath, a place East of the Jordan Tabbath.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5321G}/[H6617]', 'inflected', 'heb', 'נַפְתָּלִי', '["Naphtâlîy"]', '["from/ Naphtali"]', '["n-pr-m n-pr-loc"]', 'Naphtali, a son of Jacob, with the tribe descended from him, and its territory Naphtali.', 'from 6617; my wrestling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3920}/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["and/ capture","and/ let them be caught","and/ surely <catch>"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1012}/[H1004]', 'lemma', 'heb', 'בֵּית בָּרָה', '["Bêyth Bârâh"]', '["Barah","Beth"]', '["n-pr-loc"]', 'Beth-Barah, a place in Palestine Beth-barah.', 'probably from 1004 and 5679; house of (the) ford;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6159}/[H6158]', 'lemma', 'heb', 'עֹרֵב', '["ʻÔrêb"]', '["Oreb"]', '["n-pr-m n-pr-loc"]', 'Oreb, the name of a Midianite and of the cliff near the Jordan Oreb.', 'or עוֹרֵב; the same as 6158;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2062}/[H2061]', 'lemma', 'heb', 'זְאֵב', '["Zᵉʼêb"]', '["Zeeb"]', '["n-pr-m"]', 'Zeeb, a Midianitish prince Zeeb.', 'the same as 2061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3342>', 'inflected', 'heb', 'ביקבים', '["ba/y.ka.Vim","ve./ye.kev"]', '["at/ [the] winepress of","in the/ wine-presses"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7218A>', 'inflected', 'heb', 'וראש', '["ve./Rosh","ve./rosh"]', '["and/ [the] head of","and/ head"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2062}/[H2061]', 'inflected', 'heb', 'זְאֵב', '["Zᵉʼêb"]', '["and/ Zeeb"]', '["n-pr-m"]', 'Zeeb, a Midianitish prince Zeeb.', 'the same as 2061;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7378}/H9013/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["and/ they quarreled/ !"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5955}/[H5953]', 'lemma', 'heb', 'עֹלֵלָה', '["ʻôlêlâh"]', '["[are] [the] gleanings of","gleanings"]', '["n-f"]', 'only in plural gleanings; by extension gleaning-time (gleaning) (of the) grapes, grapegleanings.', 'feminine active participle of 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1210}/[H1219]', 'inflected', 'heb', 'בָּצִיר', '["bâtsîyr"]', '["more than/ [the] grape harvest of"]', '["n-m"]', 'clipped, i.e. the grape crop vintage.', 'from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307J}/H9028/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["spirit/ their"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5523G}/[H5521]', 'lemma', 'heb', 'סֻכּוֹת', '["Çukkôwth"]', '["Succoth"]', '["n-pr-loc"]', 'Succoth, the name of a place in Egypt and of three in Palestine Succoth.', 'or סֻכֹּת; plural of 5521; booths;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5971K}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["for the/ people","to the/ people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2078}/[H2077]', 'lemma', 'heb', 'זֶבַח', '["Zebach"]', '["Zebah"]', '["n-pr-m"]', 'Zebach, a Midianitish prince Zebah.', 'the same as 2077; sacrifice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6759}/[H6738]', 'inflected', 'heb', 'צַלְמֻנָּע', '["Tsalmunnâʻ"]', '["and/ Zalmunna"]', '["n-pr-m"]', 'Tsalmunna, a Midianite Zalmunna.', 'from 6738 and 4513; shade has been denied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3709G}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["¿/ [is] [the] hand of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6635A}/H9021/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["to/ army/ your"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6759}/[H6738]', 'lemma', 'heb', 'צַלְמֻנָּע', '["Tsalmunnâʻ"]', '["Zalmunna"]', '["n-pr-m"]', 'Tsalmunna, a Midianite Zalmunna.', 'from 6738 and 4513; shade has been denied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1758}/[H1758]', 'inflected', 'heb', 'דּוּשׁ', '["dûwsh"]', '["and/ I will thresh","and/ it will be trampled down"]', '["v"]', 'to trample or thresh break, tear, thresh, tread out (down), at grass (Jeremiah 50:11, by mistake for 1877).', 'or דּוֹשׁ; or דִּישׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1320}/H9026/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["flesh/ your"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1303}/[H1300]', 'inflected', 'heb', 'בַּרְקָן', '["barqân"]', '["<the>/ briers","the/ briers"]', '["n-m"]', 'a thorn (perhaps as burning brightly) brier.', 'from 1300;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7725G}/H9040/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["when/ bring back/ I","when/ had returned/ I","when/ return/ I"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2078}/[H2077]', 'inflected', 'heb', 'זֶבַח', '["Zebach"]', '["and/ Zebah"]', '["n-pr-m"]', 'Zebach, a Midianitish prince Zebah.', 'the same as 2077; sacrifice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7174}/[H6979]', 'inflected', 'heb', 'קַרְקֹר', '["Qarqôr"]', '["[were] in <the>/ Karkor"]', '["n-pr-loc"]', 'Karkor, a place East of the Jordan Karkor.', 'from 6979; foundation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4264}/H9028/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["and/ armies/ their"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5307J}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ those/ [who] fell"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5025H}/[H5024]', 'inflected', 'heb', 'נֹבַח', '["Nôbach"]', '["of/ Nobah"]', '["n-pr-m n-pr-loc"]', 'Nobach, the name of an Israelite, and of a place East of the Jordan Nobah.', 'from 5024; a bark;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4264}/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["and/ the/ army"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H4608}/[H5927]', 'inflected', 'heb', 'מַעֲלֶה', '["maʻăleh"]', '["from/ to/ [the] ascent of"]', '["n-m"]', 'an elevation, i.e. (concretely) acclivity or platform; abstractly (the relation or state) a rise or (figuratively) priority ascent, before, chiefest, cliff, that goeth up, going up, hill, mounting up, stairs.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2776G}/[H2775]', 'inflected', 'heb', 'חֶרֶס', '["Chereç"]', '["<the>/ Heres"]', '["n-pr-loc"]', 'Cheres, a mountain in Palestine Heres.', 'the same as 2775; shining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2205G}/H9024/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["elders/ its"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0582}/H9021/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["to/ men/ your"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3287}/[H3286]', 'inflected', 'heb', 'יָעֵף', '["yâʻêph"]', '["<the>/ weary","the/ weary [person]"]', '["a"]', 'fatigued; figuratively, exhausted faint, weary.', 'from 3286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4026M}/[H1431]', 'lemma', 'heb', 'מִגְדָּל', '["migdâl"]', '["[is] a tower of","[the] tower of","a high platform of","a tower","a tower of","tower","towers","towers of"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3644G}/H9038/[H3651]', 'inflected', 'heb', 'כְּמוֹ', '["kᵉmôw"]', '["like/ them"]', '["prt"]', 'as, thus, so according to, (such) as (it were, well as), in comparison of, like (as, to, unto), thus, when, worth.', 'or כָּמוֹ; a form of the prefix k, but used separately [compare 3651];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8389}/[H8388]', 'inflected', 'heb', 'תֹּאַר', '["tôʼar"]', '["[was] like/ [the] appearance of"]', '["n-m"]', 'outline, i.e. figure or appearance beautiful, × comely, countenance, fair, × favoured, form, × goodly, × resemble, visage.', 'from 8388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3500G}/[H3499]', 'inflected', 'heb', 'יֶתֶר', '["Yether"]', '["to/ Jether"]', '["n-pr-m"]', 'Jether, the name of five or six Israelites and of one Midianite Jether, Jethro. Compare 3503.', 'the same as 3499;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1369}/H9023/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["might/ his","mighty deeds/ his","strength/ his"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7720}/[H5469]', 'inflected', 'heb', 'שַׂהֲרֹן', '["sahărôn"]', '["the/ ornaments"]', '["n-m"]', 'a round pendant for the neck ornament, round tire like the moon.', 'from the same as 5469;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6677A}/[H6696]', 'inflected', 'heb', 'צַוָּאר', '["tsavvâʼr"]', '["[were] on/ [the] necks of","with/ a neck"]', '["n-m"]', 'the back of the neck (as that on which burdens are bound) neck.', 'or צַוָּר; (Nehemiah 3:5), or צַוָּרֹןlemma צַוָּרן missing vowel, corrected to צַוָּרֹן; (Song of Solomon 4:9), or (feminine) צַוָּארָה; (Micah 2:3), intensively from 6696 in the sense of binding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1581}/H9028/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["camels/ their"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7596}/[H7592]', 'lemma', 'heb', 'שְׁאֵלָה', '["shᵉʼêlâh"]', '["a petition"]', '["n-f"]', 'a petition; by implication, a loan loan, petition, request.', 'or שֵׁלָה; (1 Samuel 1:17), from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7998}/H9023/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["plunder/ his"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4948}/[H8254]', 'lemma', 'heb', 'מִשְׁקָל', '["mishqâl"]', '["[the] weight of","[was] weight","weight","weight of"]', '["n-m"]', 'weight (numerically estimated); hence, weighing (the act) (full) weight.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5188}/[H5197]', 'inflected', 'heb', 'נְטִיפָה', '["nᵉṭîyphâh"]', '["and/ the/ pendants"]', '["n-f"]', 'a pendant for the ears (especially of pearls) chain, collar.', 'from 5197;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0905H}/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["and/ <to>/ apart"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6060B}/[H6059]', 'inflected', 'heb', 'עָנָק', '["ʻânâq"]', '["the/ necklaces"]', '["n-m"]', 'a necklace (as if strangling) chain.', 'from 6059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5892B}/H9023/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["[were] in/ city/ his","in/ cities/ his","in/ cities/ its","in/ city/ his","on/ cities/ his"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1439}/[H1438]', 'inflected', 'heb', 'גִּדְעוֹן', '["Gidʻôwn"]', '["for/ Gideon"]', '["n-pr-m"]', 'Gidon, an Israelite Gideon.', 'from 1438; feller (i.e. warrior);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1004M}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ for/ household/ his","and/ to/ house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5375G}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["to/ lift up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1439}\/[H1438]', 'inflected', 'heb', 'גִּדְעוֹן', '["Gidʻôwn"]', '["Gideon"]', '["n-pr-m"]', 'Gidon, an Israelite Gideon.', 'from 1438; feller (i.e. warrior);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004B}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[are] in/ house/ his","[is] in/ house/ his","at/ house/ his","in/ home/ his","in/ house/ his","in/ own house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0040H}/[H1]', 'lemma', 'heb', 'אֲבִימֶלֶךְ', '["ʼĂbîymelek"]', '["Abimelech","[is] Abimelech"]', '["n-pr-m"]', 'Abimelek, the name of two Philistine kings and of two Israelites Abimelech.', 'from 1 and 4428; father of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1170}/[H1168]', 'lemma', 'heb', 'בַּעַל בְּרִית', '["Baʻal Bᵉrîyth"]', '["Baal-","Berith"]', '["n-pr-m"]', 'Baal-Berith, a special deity of the Shechemites Baal-berith.', 'from 1168 and 1285; Baal of (the) covenant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5337}/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["who/ delivered"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4910}/[H4910]', 'inflected', 'heb', 'מָשַׁל', '["mâshal"]', '["¿/ to rule"]', '["v"]', 'to rule (have, make to have) dominion, governor, × indeed, reign, (bear, cause to, have) rule(-ing, -r), have power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6106G}/H9026/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["[am] bone/ your","bones/ your"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1320}/H9026/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["and/ flesh/ your"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7936B}/[H3739]', 'inflected', 'heb', 'שָׂכַר', '["sâkar"]', '["and/ he had hired","and/ he hired","and/ they hired"]', '["v"]', 'to hire earn wages, hire (out self), reward, × surely.', 'or (by permutation) סָכַר; (Ezra 4:5), a primitive root (apparently akin (by prosthesis) to 3739 through the idea of temporary purchase; compare 7937);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6348}/[H6348]', 'inflected', 'heb', 'פָּחַז', '["pâchaz"]', '["and/ undisciplined"]', '["v"]', 'to bubble up or froth (as boiling water), i.e. (figuratively) to be unimportant light.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6084H}/H9011/[H6082]', 'inflected', 'heb', 'עׇפְרָה', '["ʻOphrâh"]', '["Ophrah/ towards"]', '["n-pr-m n-pr-loc"]', 'Ophrah, the name of an Israelite and of two places in Palestine Ophrah.', 'feminine of 6082; female fawn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3147G}/[H3068]', 'lemma', 'heb', 'יוֹתָם', '["Yôwthâm"]', '["Jotham"]', '["n-pr-m"]', 'Jotham, the name of three Israelites Jotham.', 'from 3068 and 8535; Jehovah (is) perfect;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2244}\/[H2245]', 'inflected', 'heb', 'חָבָא', '["châbâʼ"]', '["he hid himself"]', '["v"]', 'to secrete × held, hide (self), do secretly.', 'a primitive root (compare 2245);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1037}/[H1004]', 'lemma', 'heb', 'בֵּית מִלּוֹא', '["Bêyth Millôwʼ"]', '["Beth","Beth-","Millo"]', '["n-pr-loc"]', 'Beth-Millo, the name of two citadels house of Millo.', 'or בֵּית מִלֹּא; from 1004 and 4407; house of (the) rampart;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3147G}/[H3068]', 'inflected', 'heb', 'יוֹתָם', '["Yôwthâm"]', '["to/ Jotham"]', '["n-pr-m"]', 'Jotham, the name of three Israelites Jotham.', 'from 3068 and 8535; Jehovah (is) perfect;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4886}/[H4886]', 'inflected', 'heb', 'מָשַׁח', '["mâshach"]', '["to/ anoint"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2132H>', 'inflected', 'heb', 'לזית', '["la./Za.yit"]', '["to the/ olive tree"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4427A}/H9012/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["reign/ !"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2132H>', 'inflected', 'heb', 'הזיתים', '["ha./Za.yit","ha./zei.Tim"]', '["the/ olive","the/ olive tree","the/ olive trees"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2308}/[H2308]', 'inflected', 'heb', 'חָדַל', '["châdal"]', '["¿/ will I cease"]', '["v"]', 'properly, to be flabby, i.e. (by implication) desist; (figuratively) be lacking or idle cease, end, fall, forbear, forsake, leave (off), let alone, rest, be unoccupied, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1880}/H9020/[H1878]', 'inflected', 'heb', 'דֶּשֶׁן', '["deshen"]', '["fatness/ my"]', '["n-m"]', 'the fat; abstractly fatness, i.e. (figuratively) abundance; specifically the (fatty) ashes of sacrifices ashes, fatness.', 'from 1878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5128}/[H5128]', 'inflected', 'heb', 'נוּעַ', '["nûwaʻ"]', '["to/ sway","to/ wander"]', '["v"]', 'to waver, in a great variety of applications, literally and figuratively (as subjoined) continually, fugitive, × make, to (go) up and down, be gone away, (be) move(-able, -d), be promoted, reel, remove, scatter, set, shake, sift, stagger, to and fro, be vagabond, wag, (make) wander (up and down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8384}/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["to the/ fig tree"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4987}/H9020/[H4985]', 'inflected', 'heb', 'מֹתֶק', '["môtheq"]', '["sweetness/ my"]', '["n-m"]', 'sweetness sweetness.', 'from 4985;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8570}/H9020/[H5107]', 'inflected', 'heb', 'תְּנוּבָה', '["tᵉnûwbâh"]', '["fruit/ my"]', '["n-f"]', 'produce fruit, increase.', 'from 5107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1612>', 'inflected', 'heb', 'הגפן', '["ha./Ge.fen"]', '["<the>/ vine","O/ vine of","the/ vine"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8492}/H9020/[H3423]', 'inflected', 'heb', 'תִּירוֹשׁ', '["tîyrôwsh"]', '["new wine/ my"]', '["n-m"]', 'must or fresh grape-juice (as just squeezed out); by implication (rarely) fermented wine (new, sweet) wine.', 'or תִּירֹשׁ; from 3423 in the sense of expulsion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8055}/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["which/ makes glad"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0329H>', 'inflected', 'heb', 'האטד', '["ha./''a.Tad"]', '["the/ thorn bush"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0571G}/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["in/ [the] faithfulness of","in/ faithfulness","in/ truth"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6738}/H9020/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["in/ shade/ my"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8549H}/[H8552]', 'inflected', 'heb', 'תָּמִים', '["tâmîym"]', '["and/ in/ integrity"]', '["a"]', 'entire (literally, figuratively or morally); also (as noun) integrity, truth without blemish, complete, full, perfect, sincerely (-ity), sound, without spot, undefiled, upright(-ly), whole.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1576}/[H1580]', 'inflected', 'heb', 'גְּמוּל', '["gᵉmûwl"]', '["according to/ [the] benefit","according to/ [the] dealing of"]', '["n-m"]', 'treatment, i.e. an act (of good or ill); by implication, service or requital as hast served, benefit, desert, deserving, that which he hath given, recompense, reward.', 'from 1580;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0040H}/[H1]', 'inflected', 'heb', 'אֲבִימֶלֶךְ', '["ʼĂbîymelek"]', '["against/ Abimelech","in/ Abimelech","with/ Abimelech"]', '["n-pr-m"]', 'Abimelek, the name of two Philistine kings and of two Israelites Abimelech.', 'from 1 and 4428; father of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8055}/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["and/ I will be glad","and/ he rejoices","and/ it rejoiced","and/ let them rejoice","and/ let us be glad","and/ let us rejoice","and/ make glad","and/ rejoice","and/ they may rejoice","so/ he may rejoice","so/ they may rejoice"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0040H}/[H1]', 'inflected', 'heb', 'אֲבִימֶלֶךְ', '["ʼĂbîymelek"]', '["from/ Abimelech"]', '["n-pr-m"]', 'Abimelek, the name of two Philistine kings and of two Israelites Abimelech.', 'from 1 and 4428; father of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3318L}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ let it go out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1167G}/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["from/ [the] citizens of"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1037}/[H1004]', 'inflected', 'heb', 'בֵּית מִלּוֹא', '["Bêyth Millôwʼ"]', '["and/ from/ Beth"]', '["n-pr-loc"]', 'Beth-Millo, the name of two citadels house of Millo.', 'or בֵּית מִלֹּא; from 1004 and 4407; house of (the) rampart;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0876H}/H9011/[H875]', 'inflected', 'heb', 'בְּאֵר', '["Bᵉʼêr"]', '["Beer/ towards"]', '["n-pr-loc"]', 'Beer, a place in the Desert, also one in Palestine Beer.', 'the same as 875;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7786}/[H7786]', 'inflected', 'heb', 'שׂוּר', '["sûwr"]', '["and/ he ruled","and/ he struggled"]', '["v"]', 'properly, to vanquish; by implication, to rule (causatively, crown) make princes, have power, reign. See 5493.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0898}/[H898]', 'inflected', 'heb', 'בָּגַד', '["bâgad"]', '["and/ they acted treacherously","and/ they dealt treacherously"]', '["v"]', 'to cover (with a garment); figuratively, to act covertly; by implication, to pillage deal deceitfully (treacherously, unfaithfully), offend, transgress(-or), (depart), treacherous (dealer, -ly, man), unfaithful(-ly, man), × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1818}/H9028/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["and/ blood/ their"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1497}/[H1497]', 'inflected', 'heb', 'גָּזַל', '["gâzal"]', '["and/ he seized","and/ he tore away","and/ it is taken away","and/ they have robbed","and/ they robbed","and/ they seize [them]"]', '["v"]', 'to pluck off; specifically to flay, strip or rob catch, consume, exercise (robbery), pluck (off), rob, spoil, take away (by force, violence), tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0040H}\/[H1]', 'inflected', 'heb', 'אֲבִימֶלֶךְ', '["ʼĂbîymelek"]', '["to/ Abimelech"]', '["n-pr-m"]', 'Abimelek, the name of two Philistine kings and of two Israelites Abimelech.', 'from 1 and 4428; father of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1603}/[H1602]', 'lemma', 'heb', 'גַּעַל', '["Gaʻal"]', '["Gaal"]', '["n-pr-m"]', 'Gaal, an Israelite Gaal.', 'from 1602; loathing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5651G}/[H5650]', 'lemma', 'heb', 'עֶבֶד', '["ʻEbed"]', '["Ebed"]', '["n-pr-m"]', 'Ebed, the name of two Israelites Ebed.', 'the same as 5650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251H}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ brothers/ his","and/ relatives/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0982}/[H982]', 'inflected', 'heb', 'בָּטַח', '["bâṭach"]', '["and/ he has made rely","and/ he trusted","and/ they have relied","and/ they trusted","and/ you have been relying","and/ you have trusted","and/ you trusted","and/ you will be secure"]', '["v"]', 'properly, to hie for refuge (but not so precipitately as 2620); figuratively, to trust, be confident or sure be bold (confident, secure, sure), careless (one, woman), put confidence, (make to) hope, (put, make to) trust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1219}/[H1210]', 'inflected', 'heb', 'בָּצַר', '["bâtsar"]', '["and/ they gathered grapes"]', '["v"]', 'to gather grapes; also to be isolated (i.e. inaccessible by height or fortification) cut off, (de-) fenced, fortify, (grape) gather(-er), mighty things, restrain, strong, wall (up), withhold.', 'a primitive root; to clip off; specifically (as denominative from 1210)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3754>/H9028', 'opaque', 'heb', 'כֶּרֶם', '["kerem"]', '["vineyards/ their"]', '["n-m"]', 'a garden or vineyard vines, (increase of the) vineyard(-s), vintage. See also 1021.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1869}/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["and/ he will make walk","and/ he will tread","and/ they have bent","and/ they trod [them]"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647G}/H9033/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["he served/ him","we will serve/ him","will we serve/ him"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2083}/[H2073]', 'inflected', 'heb', 'זְבֻל', '["Zᵉbul"]', '["and/ [is] Zebul?"]', '["n-pr-m"]', 'Zebul, an Israelite Zebul. Compare 2073.', 'the same as 2073; dwelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6496}/H9023/[H6485]', 'inflected', 'heb', 'פָּקִיד', '["pâqîyd"]', '["deputy/ his"]', '["n-m"]', 'a superintendent (civil, military or religious) which had the charge, governor, office, overseer, (that) was set.', 'from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0040H}/[H1]', 'inflected', 'heb', 'אֲבִימֶלֶךְ', '["ʼĂbîymelek"]', '["of/ Abimelech","to/ Abimelech"]', '["n-pr-m"]', 'Abimelek, the name of two Philistine kings and of two Israelites Abimelech.', 'from 1 and 4428; father of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635A}/H9021/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["army/ your"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3318G}/H9012/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ come out/ !"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2083}/[H2073]', 'lemma', 'heb', 'זְבֻל', '["Zᵉbul"]', '["Zebul"]', '["n-pr-m"]', 'Zebul, an Israelite Zebul. Compare 2073.', 'the same as 2073; dwelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8649A}/[H7411]', 'inflected', 'heb', 'תׇּרְמָה', '["tormâh"]', '["in/ treachery"]', '["n-f"]', 'fraud deceit(-ful), privily.', 'and תַּרְמוּת; or תַּרְמִית; from 7411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5971K}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ the/ people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0693}/[H693]', 'inflected', 'heb', 'אָרַב', '["ʼârab"]', '["and/ [the] ambusher of","and/ from an ambusher","and/ lie in wait"]', '["v"]', 'to lurk (lie in) ambush(-ment), lay (lie in) wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2224}/[H2224]', 'inflected', 'heb', 'זָרַח', '["zârach"]', '["when/ arose","when/ rises"]', '["v"]', 'properly, to irradiate (or shoot forth beams), i.e. to rise (as the sun); specifically, to appear (as a symptom of leprosy) arise, rise (up), as soon as it is up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027G}/H9021\/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6738}/[H6751]', 'lemma', 'heb', 'צֵל', '["tsêl"]', '["[are] a shadow","[the] shadow of","a shade","shade"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0582}\/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["like <the>/ men"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2872>', 'opaque', 'heb', 'טַבּוּר', '["ṭabbûwr"]', '["[the] center of"]', '["n-m"]', 'properly, accumulated; i.e. (by implication) a summit middle, midst.', 'from an unused root meaning to pile up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7218K>', 'inflected', 'heb', 'וראש', '["ve./rosh"]', '["and/ a company"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1870J}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["from/ [the] direction of","from/ direction of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0436G}/[H352]', 'lemma', 'heb', 'אֵלוֹן', '["ʼêlôwn"]', '["[the] great tree of"]', '["n-m"]', 'an oak or other strong tree plain. See also 356.', 'prolonged from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6049G}/[H6051]', 'lemma', 'heb', 'עָנַן', '["ʻânan"]', '["[the] soothsayer"]', '["v"]', 'figuratively, to act covertly, i.e. practise magic × bring, enchanter, Meonemin, observe(-r of) times, soothsayer, sorcerer.', 'a primitive root; to cover; used only as a denominative from 6051, to cloud over;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7291}/H9033/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["and/ he pursued/ him"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0725}/[H7316]', 'inflected', 'heb', 'אֲרוּמָה', '["ʼĂrûwmâh"]', '["at <the>/ Arumah"]', '["n-pr-loc"]', 'Arumah, a place in Palestine Arumah.', 'a variation of 7316; height;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2673}/H9038/[H2086]', 'inflected', 'heb', 'חָצָה', '["châtsâh"]', '["and/ he divided/ them"]', '["v"]', 'to cut or split in two; to halve divide, × live out half, reach to the midst, participle', 'a primitive root (compare 2086));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0040H}/[H1]', 'inflected', 'heb', 'אֲבִימֶלֶךְ', '["ʼĂbîymelek"]', '["and/ Abimelech"]', '["n-pr-m"]', 'Abimelek, the name of two Philistine kings and of two Israelites Abimelech.', 'from 1 and 4428; father of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H7218K>', 'inflected', 'heb', 'והראשים', '["ve./ha./Rosh","ve./ha./ra.Shim"]', '["and/ the/ companies","and/ the/ company"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6584}/[H6584]', 'lemma', 'heb', 'פָּשַׁט', '["pâshaṭ"]', '["I have taken off","[were] skinning [them]","[were] stripping off","did you make a raid","he has stripped off","it attacks","strip off","they had made a raid","they have made a raid","they have stripped off","they made a raid","they will strip off","they will take off","we had made a raid","you have stripped off"]', '["v"]', 'to spread out (i.e. deploy in hostile array); by analogy, to strip (i.e. unclothe, plunder, flay, etc.) fall upon, flay, invade, make an invasion, pull off, put off, make a road, run upon, rush, set, spoil, spread selves (abroad), strip (off, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2232}/H9034/[H2232]', 'inflected', 'heb', 'זָרַע', '["zâraʻ"]', '["and/ I will sow/ her","and/ he sowed/ it"]', '["v"]', 'to sow; figuratively, to disseminate, plant, fructify bear, conceive seed, set with sow(-er), yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6877}/[H6873]', 'lemma', 'heb', 'צְרִיחַ', '["tsᵉrîyach"]', '["[the] underground chamber of"]', '["n-m"]', 'a citadel high place, hold.', 'from 6873 in the sense of clearness of vision;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0410H}/[H352]', 'lemma', 'heb', 'אֵל', '["ʼêl"]', '["El-"]', '["n-m"]', 'strength; as adjective, mighty; especially the Almighty (but used also of any deity) God (god), × goodly, × great, idol, might(-y one), power, strong. Compare names in ''-el.''', 'shortened from 352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1286}/[H1285]', 'lemma', 'heb', 'בְּרִית', '["Bᵉrîyth"]', '["Berith"]', '["n-pr-m"]', 'Berith, a Shechemitish deity Berith.', 'the same as 1285;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6756A}/[H6754]', 'lemma', 'heb', 'צַלְמוֹן', '["Tsalmôwn"]', '["Zalmon"]', '["n-pr-m n-pr-loc"]', 'Tsalmon, the name of a place in Palestine and of an Israelite Zalmon.', 'from 6754; shady;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7134}/[H6923]', 'inflected', 'heb', 'קַרְדֹּם', '["qardôm"]', '["the/ axes"]', '["n-m"]', 'an axe ax.', 'perhaps from 6923 in the sense of striking upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7754B}/[H7753]', 'lemma', 'heb', 'שׂוֹךְ', '["sôwk"]', '["a branch of"]', '["n-m n-f"]', 'a branch (as interleaved) bough.', 'or (feminine) שׂוֹכָה; from 7753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375G}/H9034/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ he lifted up/ it"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7754A}/H9023/[H7753]', 'inflected', 'heb', 'שׂוֹךְ', '["sôwk"]', '["own branch/ his"]', '["n-m n-f"]', 'a branch (as interleaved) bough.', 'or (feminine) שׂוֹכָה; from 7753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6877}/[H6873]', 'inflected', 'heb', 'צְרִיחַ', '["tsᵉrîyach"]', '["the/ underground chamber"]', '["n-m"]', 'a citadel high place, hold.', 'from 6873 in the sense of clearness of vision;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0802G}\/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ woman"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8405}/[H948]', 'lemma', 'heb', 'תֵּבֵץ', '["Têbêts"]', '["Thebez"]', '["n-pr-loc"]', 'Tebets, a place in Palestine Thebez.', 'from the same as 948; whiteness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8405}/[H948]', 'inflected', 'heb', 'תֵּבֵץ', '["Têbêts"]', '["at/ Thebez","in/ Thebez"]', '["n-pr-loc"]', 'Tebets, a place in Palestine Thebez.', 'from the same as 948; whiteness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1406}/[H1342]', 'lemma', 'heb', 'גָּג', '["gâg"]', '["[the] roof of","[the] roofs of","a roof","roofs"]', '["n-m"]', 'a roof; by analogy, the top of an altar roof (of the house), (house) top (of the house).', 'probably by reduplication from 1342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8313}/H9033/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["to/ burn/ it"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6400}/[H6398]', 'lemma', 'heb', 'פֶּלַח', '["pelach"]', '["a mill-stone","a mill-stone of","a slice of"]', '["n-f"]', 'a slice piece.', 'from 6398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7393H}/[H7392]', 'lemma', 'heb', 'רֶכֶב', '["rekeb"]', '["an upper mill-stone"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1538}/H9023/[H1556]', 'inflected', 'heb', 'גֻּלְגֹּלֶת', '["gulgôleth"]', '["skull/ his"]', '["n-f"]', 'a skull (as round); by implication, a head (in enumeration of persons) head, every man, poll, skull.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375W}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["[the] bearer","[the] bearer of","[the] bearers of","[who] carried","bearer of","carrier[s]"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4191}/H9030/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ kill/ me"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1856}/H9033/[H1856]', 'inflected', 'heb', 'דָּקַר', '["dâqar"]', '["and/ he pierced through/ him","and/ they will pierce through/ him"]', '["v"]', 'to stab; by analogy, to starve; figuratively, to revile pierce, strike (thrust) through, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3378}\/[H7378]', 'inflected', 'heb', 'יְרֻבַּעַל', '["Yᵉrubbaʻal"]', '["Jerub-Baal"]', '["n-pr-m"]', 'Jerubbaal, a symbolic name of Gideon Jerubbaal.', 'from 7378 and 1168; Baal will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8439H}/[H8438]', 'lemma', 'heb', 'תּוֹלָע', '["Tôwlâʻ"]', '["Tola"]', '["n-pr-m"]', 'Tola, the name of two Israelites Tola.', 'the same as 8438; worm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6312H}/[H6284]', 'lemma', 'heb', 'פּוּאָה', '["Pûwʼâh"]', '["Puah"]', '["n-pr-m"]', 'Puah or Puvvah, the name of two Israelites Phuvah, Pua, Puah.', 'or פֻּוָּה; from 6284; a blast;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1734G}/[H1730]', 'lemma', 'heb', 'דּוֹדוֹ', '["Dôwdôw"]', '["Dodo"]', '["n-pr-m"]', 'Dodo, the name of three Israelites Dodo.', 'from 1730; loving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8069H}/[H8068]', 'inflected', 'heb', 'שָׁמִיר', '["Shâmîyr"]', '["in/ Shamir"]', '["n-pr"]', 'Shamir, the name of two places in Palestine Shamir. Compare 8053.', 'the same as 8068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8069H}\/[H8068]', 'inflected', 'heb', 'שָׁמִיר', '["Shâmîyr"]', '["in/ Shamir"]', '["n-pr"]', 'Shamir, the name of two places in Palestine Shamir. Compare 8053.', 'the same as 8068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2971I}/[H215]', 'lemma', 'heb', 'יָאִיר', '["Yâʼîyr"]', '["Jair"]', '["n-pr-m"]', 'Jair, the name of four Israelites Jair.', 'from 215; enlightener;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5895}/[H5782]', 'lemma', 'heb', 'עַיִר', '["ʻayir"]', '["a male donkey","donkeys"]', '["n-m"]', 'properly, a young ass (as just broken to a load); hence an ass-colt (ass) colt, foal, young ass.', 'from 5782 in the sense of raising (i.e. bearing a burden);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7056}\/[H6965]', 'inflected', 'heb', 'קָמוֹן', '["Qâmôwn"]', '["in/ Kamon"]', '["n-pr-loc"]', 'Kamon, a place East of the Jordan Camon.', 'from 6965; an elevation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6252G}/[H6251]', 'inflected', 'heb', 'עַשְׁתָּרוֹת', '["ʻAshtârôwth"]', '["the/ Ashtaroth"]', '["n-pr-f"]', 'Ashtaroth, the name of a Sidonian deity, and of a place East of the Jordan Asharoth, Astaroth. See also 1045, 6253, 6255.', 'or עַשְׁתָּרֹת; plural of 6251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0758I}/[H759]', 'lemma', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647H}/H9033/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["[those who] serve/ him","he will serve/ him","it will serve/ him","they served/ him","they will serve/ him","we will serve/ him"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7492}/[H7492]', 'inflected', 'heb', 'רָעַץ', '["râʻats"]', '["and/ they shattered"]', '["v"]', 'to break in pieces; figuratively, harass dash in pieces, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3063G}/[H3034]', 'inflected', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["<in>/ Judah","[is] in/ Judah","[was] in/ Judah","[were] in/ Judah","against/ Judah","among/ Judah","in/ Judah","on/ Judah","over/ Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1144G}/[H1121]', 'inflected', 'heb', 'בִּנְיָמִין', '["Binyâmîyn"]', '["and/ against/ Benjamin","and/ in/ Benjamin"]', '["n-pr-m"]', 'Binjamin, youngest son of Jacob; also the tribe descended from him, and its territory Benjamin.', 'from 1121 and 3225; son of (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1004M}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ against/ [the] house of","and/ among/ [the] house of","and/ on/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1168A}\/[H1167]', 'inflected', 'heb', 'בַּעַל', '["Baʻal"]', '["the/ Baals"]', '["n-pr-m n-pr-loc"]', 'Baal, a Phoenician deity Baal, (plural) Baalim.', 'the same as 1167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6722}/[H6721]', 'inflected', 'heb', 'צִידֹנִי', '["Tsîydônîy"]', '["and/ [the] Sidonians"]', '["a"]', 'a Tsidonian or inhabitant of Tsidon Sidonian, of Sidon, Zidonian.', 'patrial from 6721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4584G}/[H4583]', 'inflected', 'heb', 'מָעוֹן', '["Mâʻôwn"]', '["and/ Maon"]', '["n-pr-m n-pr-loc"]', 'Maon, the name of an Israelite and of a place in Palestine Maon, Maonites. Compare 1010, 4586.', 'the same as 4583; a residence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3467}/H9012/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ I delivered/ !"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027H}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2199}/[H2199]', 'inflected', 'heb', 'זָעַק', '["zâʻaq"]', '["and/ cry out","so/ they may cry out","so/ we may cry out"]', '["v"]', 'to shriek (from anguish or danger); by analogy, (as a herald) to announce or convene publicly assemble, call (together), (make a) cry (out), come with such a company, gather (together), cause to be proclaimed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6869B}/H9026/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["distress/ your"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7130G}/H9028/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["from/ midst/ their"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5999}/[H5998]', 'inflected', 'heb', 'עָמָל', '["ʻâmâl"]', '["[are] in/ [the] trouble of","at/ [the] trouble of","with <the>/ trouble"]', '["n"]', 'toil, i.e. wearing effort; hence, worry, whether of body or mind grievance(-vousness), iniquity, labour, mischief, miserable(-sery), pain(-ful), perverseness, sorrow, toil, travail, trouble, wearisome, wickedness.', 'from 5998;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4709H}/[H4708]', 'inflected', 'heb', 'מִצְפָּה', '["Mitspâh"]', '["at <the>/ Mizpah"]', '["n-pr-f"]', 'Mitspah, the name of two places in Palestine Mitspah. (This seems rather to be only an orthographic variation of 4708 when ''in pause''.)', 'feminine of 4708;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1568G}\/[H1567]', 'inflected', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["Gilead"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3316H}/[H6605]', 'inflected', 'heb', 'יִפְתָּח', '["Yiphtâch"]', '["and/ Jephthah"]', '["n-pr-m n-pr-loc"]', 'Jiphtach, an Israelite; also a place in Palestine Jephthah, Jiphtah.', 'from 6605; he will open;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1568I}/[H1567]', 'lemma', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["Gilead"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3316H}/[H6605]', 'lemma', 'heb', 'יִפְתָּח', '["Yiphtâch"]', '["Jephthah"]', '["n-pr-m n-pr-loc"]', 'Jiphtach, an Israelite; also a place in Palestine Jephthah, Jiphtah.', 'from 6605; he will open;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1644H}/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["and/ they drove out"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2897}/[H2896]', 'lemma', 'heb', 'טוֹב', '["Ṭôwb"]', '["Tob"]', '["n-pr-loc"]', 'Tob, a region apparently East of the Jordan Tob.', 'the same as 2896; good;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3947J}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["to/ bring","to/ fetch","to/ get [it]","to/ take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3316H}/[H6605]', 'inflected', 'heb', 'יִפְתָּח', '["Yiphtâch"]', '["to/ Jephthah"]', '["n-pr-m n-pr-loc"]', 'Jiphtach, an Israelite; also a place in Palestine Jephthah, Jiphtah.', 'from 6605; he will open;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7101}/[H7096]', 'inflected', 'heb', 'קָצִין', '["qâtsîyn"]', '["<into>/ a commander"]', '["n-m"]', 'a magistrate (as deciding) or other leader captain, guide, prince, ruler. Compare 6278.', 'from 7096 in the sense of determining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1644G}/H9030/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["and/ did you drive out?/ me"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6862B}/[H6887]', 'lemma', 'heb', 'צַר', '["tsar"]', '["[is] distress","[the] distresses of","anxiety","distress","distress of","it is distress","it was distress"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085K}/[H8085]', 'lemma', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["hearing"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7101}/[H7096]', 'inflected', 'heb', 'קָצִין', '["qâtsîyn"]', '["and/ into/ commander"]', '["n-m"]', 'a magistrate (as deciding) or other leader captain, guide, prince, ruler. Compare 6278.', 'from 7096 in the sense of determining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4709H}\/[H4708]', 'inflected', 'heb', 'מִצְפָּה', '["Mitspâh"]', '["in <the>/ Mizpah"]', '["n-pr-f"]', 'Mitspah, the name of two places in Palestine Mitspah. (This seems rather to be only an orthographic variation of 4708 when ''in pause''.)', 'feminine of 4708;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H9032}', 'inflected', 'heb', 'ולך', '["va./La/kh","ve./La/kh","ve./lo/Kh"]', '["and/ for/ yourself","and/ to <the> [why]/ you","and/ to <the>/ you","and/ to/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0776G>/H9020', 'inflected', 'heb', 'בארצי', '["be./''ar.Tz/i"]', '["against/ land/ my","in/ land/ my","in/ own land/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5927G}/H9043/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["when/ came up/ it"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2999}/[H1238]', 'inflected', 'heb', 'יַבֹּק', '["Yabbôq"]', '["the/ Jabbok"]', '["n-pr-loc"]', 'Jabbok, a river east of the Jordan Jabbok.', 'probably from 1238; pouring forth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725H}/H9012/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["bring back/ !","restore/ !","turn back/ !"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5927G}/H9048/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["when/ came up/ they"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2583}/H9013/[H2603]', 'inflected', 'heb', 'חָנָה', '["chânâh"]', '["and/ they encamped/ !"]', '["v"]', 'properly, to incline; by implication, to decline (of the slanting rays of evening); specifically, to pitch a tent; generally to encamp (for abode or siege) abide (in tents), camp, dwell, encamp, grow to an end, lie, pitch (tent), rest in tent.', 'a primitive root (compare 2603);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3096>/H9011', 'inflected', 'heb', 'ביהצה', '["be./Ya.he.tza/h"]', '["at/ Jahaz/ <towards>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423H}/H9033/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["[those who] dispossessed/ it","he drives out/ it","will you take possession of?/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2895}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["¿/ really <good>"]', '["v"]', 'to be (transitively, do or make) good (or well) in the widest sense be (do) better, cheer, be (do, seem) good, (make) goodly, × please, (be, do, go, play) well.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1111}/[H1110]', 'inflected', 'heb', 'בָּלָק', '["Bâlâq"]', '["more than/ Balak"]', '["n-pr-m"]', 'Balak, a Moabitish king Balak.', 'from 1110; waster;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7378}/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["¿/ really <to quarrel>","¿/ will he contend"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1323H}/H9024/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ in/ daughters/ its"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6177H}/[H6176]', 'inflected', 'heb', 'עֲרוֹעֵר', '["ʻĂrôwʻêr"]', '["and/ in/ Aroer"]', '["n-pr-loc"]', 'Aroër, the name of three places in or near Palestine Aroer.', 'or עֲרֹעֵר; or עַרְעוֹר; the same as 6176; nudity of situation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4708K}/[H4707]', 'lemma', 'heb', 'מִצְפֶּה', '["Mitspeh"]', '["Mizpah of"]', '["n-pr-loc"]', 'Mitspeh, the name of five places in Palestine Mizpeh, watch tower. Compare 4709.', 'the same as 4707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4708K}/[H4707]', 'inflected', 'heb', 'מִצְפֶּה', '["Mitspeh"]', '["and/ from/ Mizpah of"]', '["n-pr-loc"]', 'Mitspeh, the name of five places in Palestine Mizpeh, watch tower. Compare 4709.', 'the same as 4707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9020/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["home/ my","house/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5930A}\/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["a burnt offering","burnt offering"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6177G}/[H6176]', 'inflected', 'heb', 'עֲרוֹעֵר', '["ʻĂrôwʻêr"]', '["from/ Aroer"]', '["n-pr-loc"]', 'Aroër, the name of three places in or near Palestine Aroer.', 'or עֲרֹעֵר; or עַרְעוֹר; the same as 6176; nudity of situation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4511}/[H4482]', 'lemma', 'heb', 'מִנִּית', '["Minnîyth"]', '["Minnith"]', '["n-pr-loc"]', 'Minnith, a place East of the Jordan Minnith.', 'from the same as 4482; enumeration;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0064}/[H58]', 'lemma', 'heb', 'אָבֵל כְּרָמִים', '["ʼÂbêl Kᵉrâmîym"]', '["Abel","Keramim"]', '["n-pr-loc"]', 'Abel-Keramim, a place in Palestine plain of the vineyards.', 'from 58 and the plural of 3754; meadow of vineyards;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4709H}/[H4708]', 'inflected', 'heb', 'מִצְפָּה', '["Mitspâh"]', '["<the>/ Mizpah"]', '["n-pr-f"]', 'Mitspah, the name of two places in Palestine Mitspah. (This seems rather to be only an orthographic variation of 4708 when ''in pause''.)', 'feminine of 4708;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3173}/[H3161]', 'lemma', 'heb', 'יָחִיד', '["yâchîyd"]', '["[am] solitary","[was] an only [child]","an only [child]","an only [son]","solitary [people]"]', '["a"]', 'properly, united, i.e. sole; by implication, beloved; also lonely; (feminine) the life (as not to be replaced) darling, desolate, only (child, son), solitary.', 'from 3161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3766}/H9030/[H3766]', 'inflected', 'heb', 'כָּרַע', '["kâraʻ"]', '["you have brought low/ me"]', '["v"]', 'to bend the knee; by implication, to sink, to prostrate bow (down, self), bring down (low), cast down, couch, fall, feeble, kneeling, sink, smite (stoop) down, subdue, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5916}/H9030/[H5916]', 'inflected', 'heb', 'עָכַר', '["ʻâkar"]', '["among/ [those who] trouble/ me"]', '["v"]', 'properly, to roil water; figuratively, to disturb or affict trouble, stir.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0341}/H9021/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["from/ enemies/ your"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1058}/[H1058]', 'inflected', 'heb', 'בָּכָה', '["bâkâh"]', '["and/ utterly <to weep>","and/ weeping","and/ wept","so/ I may bewail","so/ I may weep"]', '["v"]', 'to weep; generally to bemoan × at all, bewail, complain, make lamentation, × more, mourn, × sore, × with tears, weep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1331}/H9020/[H1330]', 'inflected', 'heb', 'בְּתוּלִים', '["bᵉthûwlîym"]', '["virginiti<es>/ my"]', '["n-f"]', '(collectively and abstractly) virginity; by implication and concretely, the tokens of it × maid, virginity.', 'masculine plural of the same as 1330;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7464}/H9020/[H7453]', 'inflected', 'heb', 'רֵעָה', '["rêʻâh"]', '["and/ companions/ my"]', '["n-f"]', 'a female associate companion, fellow.', 'feminine of 7453;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7464}/H9024/[H7453]', 'inflected', 'heb', 'רֵעָה', '["rêʻâh"]', '["and/ companions/ her"]', '["n-f"]', 'a female associate companion, fellow.', 'feminine of 7453;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1331}/H9024/[H1330]', 'inflected', 'heb', 'בְּתוּלִים', '["bᵉthûwlîym"]', '["virginiti<es>/ her"]', '["n-f"]', '(collectively and abstractly) virginity; by implication and concretely, the tokens of it × maid, virginity.', 'masculine plural of the same as 1330;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117I>/H9011', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days/ towards"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8567}/[H8567]', 'inflected', 'heb', 'תָּנָה', '["tânâh"]', '["to/ recount"]', '["v"]', 'to ascribe (praise), i.e. celebrate, commemorate lament, rehearse.', 'a primitive root (identical with through the idea of attributing honor);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8141}\/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["in the/ year","in/ a year"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6828H}/H9011/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["Zaphon/ towards"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H9035}', 'inflected', 'heb', 'ולנו', '["va./La./nu","ve./La./nu"]', '["and/ <to> <the>/ us","and/ [belongs] to <the>/ us","and/ [belongs] to/ us","and/ for / us"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760I}/H9012/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ I put/ !"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3709G}/H9020/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["[is] in/ hand/ my","[is] in/ hands/ my","in/ hands/ my","in/ palm/ my"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5674A}/H9012/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["and/ I passed over/ !"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6412A}/[H6403]', 'lemma', 'heb', 'פָּלִיט', '["pâlîyṭ"]', '["O fugitives of","[are] fugitives of","[the] fugitives of","an escapee","escapees of"]', '["n-m"]', 'a refugee (that have) escape(-d, -th), fugitive.', 'or פָּלֵיט; or פָּלֵט; from 6403;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0673G}/[H672]', 'inflected', 'heb', 'אֶפְרָתִי', '["ʼEphrâthîy"]', '["¿/ an Ephrathite"]', '["a"]', 'an Ephrathite or an Ephraimite Ephraimite, Ephrathite.', 'patrial from 672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7641H}/[H7640]', 'lemma', 'heb', 'שִׁבֹּל', '["shibbôl"]', '["Shibboleth"]', '["n-f"]', 'a stream (as flowing); also an ear of grain (as growing out); by analogy, a branch branch, channel, ear (of corn), (water-)flood, Shibboleth. Compare 5451.', 'or (feminine) שִׁבֹּלֶת; from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5451}/[H7641]', 'lemma', 'heb', 'סִבֹּלֶת', '["çibbôleth"]', '["Sibboleth"]', '["n-f"]', 'an ear of grain Sibboleth.', 'for 7641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0669G}/[H672]', 'inflected', 'heb', 'אֶפְרַיִם', '["ʼEphrayim"]', '["from/ Ephraim","of/ Ephraim"]', '["n-pr-m"]', 'Ephrajim, a son of Joseph; also the tribe descended from him, and its territory Ephraim, Ephraimites.', 'dual of masculine form of 672; double fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0078}/[H76]', 'lemma', 'heb', 'אִבְצָן', '["ʼIbtsân"]', '["Ibzan"]', '["n-pr-m"]', 'Ibtsan, an Israelite Ibzan.', 'from the same as 76; splendid;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1035G}/[H1004]', 'inflected', 'heb', 'בֵּית לֶחֶם', '["Bêyth Lechem"]', '["from/ Beth-"]', '["n-pr-loc"]', 'Beth-Lechem, a place in Palestine Bethlehem.', 'from 1004 and 3899; house of bread;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971J}/[H7971]', 'lemma', 'heb', 'שָׁלַח', '["shâlach"]', '["he sent away"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2351>', 'inflected', 'heb', 'החוץ', '["ha./Chutz"]', '["<the>/ outside","the/ outside"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1035G}/[H1004]', 'inflected', 'heb', 'בֵּית לֶחֶם', '["Bêyth Lechem"]', '["[was] at/ Beth-","in/ Beth-"]', '["n-pr-loc"]', 'Beth-Lechem, a place in Palestine Bethlehem.', 'from 1004 and 3899; house of bread;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1035G}\/[H1004]', 'inflected', 'heb', 'בֵּית לֶחֶם', '["Bêyth Lechem"]', '["-lehem"]', '["n-pr-loc"]', 'Beth-Lechem, a place in Palestine Bethlehem.', 'from 1004 and 3899; house of bread;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0356J}/[H352]', 'lemma', 'heb', 'אֵילוֹן', '["ʼÊylôwn"]', '["Elon"]', '["n-pr"]', 'Elon, the name of a place in Palestine, and also of one Hittite, two Israelites Elon.', 'or (shortened) אֵלוֹן ; or אֵילֹן ; from 352; oak-grove;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2074}\/[H2082]', 'inflected', 'heb', 'זְבוּלוּן', '["Zᵉbûwlûwn"]', '["Zebulun"]', '["n-pr-m n-pr-loc"]', 'Zebulon, a son of Jacob; also his territory and tribe Zebulun.', 'or זְבֻלוּן; or זְבוּלֻן; from 2082; habitation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5658H}/[H5647]', 'lemma', 'heb', 'עַבְדוֹן', '["ʻAbdôwn"]', '["Abdon"]', '["n-pr-m n-pr-loc"]', 'Abdon, the name of a place in Palestine and of four Israelites Abdon. Compare 5683.', 'from 5647; servitude;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1985}/[H1984]', 'lemma', 'heb', 'הִלֵּל', '["Hillêl"]', '["Hillel"]', '["n-pr-m"]', 'Hillel, an Israelite Hillel.', 'from 1984; praising (namely God);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6553}/[H6552]', 'inflected', 'heb', 'פִּרְעָתוֹנִי', '["Pirʻâthôwnîy"]', '["the/ Pirathonite"]', '["a"]', 'a Pirathonite or inhabitant of Pirathon Pirathonite.', 'or פִּרְעָתֹנִי; patrial from 6552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6552}/[H6546]', 'inflected', 'heb', 'פִּרְעָתוֹן', '["Pirʻâthôwn"]', '["at/ Pirathon"]', '["n-pr-loc"]', 'Pirathon, a place in Palestine Pirathon.', 'from 6546; chieftaincy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6003}\/[H6002]', 'inflected', 'heb', 'עֲמָלֵקִי', '["ʻĂmâlêqîy"]', '["the/ Amalekite[s]"]', '["a"]', 'an Amalekite (or collectively the Amalekites) or descendants of Amalek Amalekite(-s).', 'patronymically from 6002;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6881}/[H6880]', 'inflected', 'heb', 'צׇרְעָה', '["Tsorʻâh"]', '["from/ Zorah"]', '["n-pr-loc"]', 'Tsorah, a place in Palestine Zareah, Zorah, Zoreah.', 'apparently another form for 6880;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1839}/[H1835]', 'inflected', 'heb', 'דָּנִי', '["Dânîy"]', '["the/ Danite[s]"]', '["a"]', 'a Danite (often collectively) or descendants (or inhabitants) of Dan Danites, of Daniel', 'patronymically from 1835;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4495}/[H4494]', 'lemma', 'heb', 'מָנוֹחַ', '["Mânôwach"]', '["Manoah","[was] Manoah"]', '["n-pr-m"]', 'Manoach, an Israelite Manoah.', 'the same as 4494; rest;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4177}/[H4171]', 'inflected', 'heb', 'מוֹרָה', '["môwrâh"]', '["and/ a razor"]', '["n-m"]', 'a razor razor.', 'from 4171 in the sense of shearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0990H>', 'inflected', 'heb', 'הבטן', '["ha./Ba.ten","ha./Be.ten"]', '["the/ womb"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7592}/H9033/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["I asked for/ him","I asked/ him","I entrust/ him"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4194}/H9023\/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["death/ his"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3384B}/H9035/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["so/ he may teach/ us"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5288}/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["<to> the/ lad","<to> the/ youth","[belong] to the/ young man","for the/ children","for the/ lad","to the/ lad","to the/ servant","to the/ young man","to the/ young men","to/ a youth"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4495}/[H4494]', 'inflected', 'heb', 'מָנוֹחַ', '["Mânôwach"]', '["and/ Manoah"]', '["n-pr-m"]', 'Manoach, an Israelite Manoah.', 'the same as 4494; rest;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200L}/[H7200]', 'lemma', 'heb', 'רָאָה', '["râʼâh"]', '["I saw","he has presented himself","you must see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4639G}/H9023/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["and/ business/ his","and/ work/ his"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6680}/H9034/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["I commanded/ her","she had commanded/ her"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3899G}/H9021/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["in/ food/ your"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927I}/H9034/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["you will offer up/ it"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3513G}/H9031/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["and/ we will honor/ you"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6383}\/[H6381]', 'inflected', 'heb', 'פִּלְאִי', '["pilʼîy"]', '["[is] incomprehensible"]', '["a"]', 'remarkable secret, wonderful.', 'or פָּלִיא; from 6381;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6381}/[H6381]', 'inflected', 'heb', 'פָּלָא', '["pâlâʼ"]', '["and/ act wonderfully","and/ an extraordinary thing","and/ wonders"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5927G}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["when/ came up","when/ had taken itself up","when/ went up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3851}/[H3851]', 'inflected', 'heb', 'לַהַב', '["lahab"]', '["in/ [the] flame of","with/ flames of"]', '["n-m"]', 'a flash; figuratively, a sharply polished blade or point of a weapon blade, bright, flame, glittering.', 'from an usused root meaning to gleam;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7200L}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["to/ appear"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027G}/H9025/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ our"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6256}/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["and/ about <the>/ this time","and/ about/ [the] time of"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085I}/H9035/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["he caused to hear/ us","proclaim to/ us","will they proclaim to?/ us"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8123}/[H8121]', 'lemma', 'heb', 'שִׁמְשׁוֹן', '["Shimshôwn"]', '["O Samson","Samson"]', '["n-pr-m"]', 'Shimshon, an Israelite Samson.', 'from 8121; sunlight;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6470}/H9033/[H6470]', 'inflected', 'heb', 'פָּעַם', '["pâʻam"]', '["to/ stir/ him"]', '["v"]', 'to tap, i.e. beat regularly; hence (generally) to impel or agitate move, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4265}/[H4264]', 'inflected', 'heb', 'מַחֲנֵה־דָן', '["Machănêh-Dân"]', '["in/ Mahaneh"]', '["n-pr-loc"]', 'Machaneh-Dan, a place in Palestine Mahaneh-dan.', 'from 4264 and 1835; camp of Dan;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4265}/[H4264]', 'lemma', 'heb', 'מַחֲנֵה־דָן', '["Machănêh-Dân"]', '["Dan","Mahaneh"]', '["n-pr-loc"]', 'Machaneh-Dan, a place in Palestine Mahaneh-dan.', 'from 4264 and 1835; camp of Dan;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0847}\/[H7592]', 'inflected', 'heb', 'אֶשְׁתָּאֹל', '["ʼEshtâʼôl"]', '["Eshtaol"]', '["n-pr-loc"]', 'Eshtaol, a place in Palestine Eshtaol.', 'or אֶשְׁתָּאוֹל; probably from 7592; intreaty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8553G}/H9011/[H4487]', 'inflected', 'heb', 'תִּמְנָה', '["Timnâh"]', '["in/ Timnah/ <towards>"]', '["n-pr-loc"]', 'Timnah, the name of two places in Palestine Timnah, Timnath, Thimnathah.', 'from 4487; a portion assigned;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0369}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["¿/ [is] there not"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6430G}/[H6429]', 'inflected', 'heb', 'פְּלִשְׁתִּי', '["Pᵉlishtîy"]', '["from/ [the] Philistines"]', '["a"]', 'a Pelishtite or inhabitant of Pelesheth Philistine.', 'patrial from 6429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869A}/H9020/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ own eyes/ my","in/ view/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8385B}/[H579]', 'lemma', 'heb', 'תַּאֲנָה', '["taʼănâh"]', '["an occasion"]', '["n-f"]', 'an opportunity or (subjectively) purpose occasion.', 'or תֹּאֲנָה; from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6256}/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["and/ at the/ time","and/ at/ [the] time","and/ at/ [the] time of","and/ in the/ times","and/ in/ [the] time of","and/ in/ a time of"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3715A}/[H3722]', 'lemma', 'heb', 'כְּפִיר', '["kᵉphîyr"]', '["a young lion","a young lion of","young lions"]', '["n-m"]', 'a village (as covered in by walls); also a young lion (perhaps as covered with a mane) (young) lion, village. Compare 3723.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0738A}/[H717]', 'lemma', 'heb', 'אֲרִי', '["ʼărîy"]', '["[are] lions","[which] lions","a lion","lions"]', '["n-m"]', 'a lion (young) lion, pierce (from the margin).', 'or (prolonged) אַרְיֵה; from 717 (in the sense of violence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7580}/[H7580]', 'lemma', 'heb', 'שָׁאַג', '["shâʼag"]', '["I roar","[are] roaring","[was] roaring","certainly <to roar>","he will roar","it has roared","it roars","it will roar","roaring","they have been roaring","they roar","they roared"]', '["v"]', 'to rumble or moan × mightily, roar.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6743A}/[H6743]', 'inflected', 'heb', 'צָלַח', '["tsâlach"]', '["and/ it rushed","and/ it will rush","and/ they rushed ahead"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8156}/H9033/[H8156]', 'inflected', 'heb', 'שָׁסַע', '["shâçaʻ"]', '["and/ he tore apart/ it"]', '["v"]', 'to split or tear; figuratively, to upbraid cleave, (be) cloven (footed), rend, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8156}/[H8156]', 'inflected', 'heb', 'שָׁסַע', '["shâçaʻ"]', '["as/ tears apart"]', '["v"]', 'to split or tear; figuratively, to upbraid cleave, (be) cloven (footed), rend, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3972}/[H3971]', 'inflected', 'heb', 'מְאוּמָה', '["mᵉʼûwmâh"]', '["and/ [was] anything","and/ anything"]', '["x"]', 'properly, a speck or point, i.e. (by implication) something; with negative, nothing fault, no(-ught), ought, somewhat, any (no-)thing.', 'apparently a form of 3971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3474}/[H3474]', 'inflected', 'heb', 'יָשַׁר', '["yâshar"]', '["and/ it was pleasing","and/ she was pleasing","and/ they were straight"]', '["v"]', 'to be straight or even; figuratively, to be (causatively, to make) right, pleasant, prosperous direct, fit, seem good (meet), please (will), be (esteem, go) right (on), bring (look, make, take the) straight (way), be upright(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4658}/[H5307]', 'lemma', 'heb', 'מַפֶּלֶת', '["mappeleth"]', '["[the] carcass of"]', '["n-f"]', 'fall, i.e. decadence; concretely, a ruin; specifically a carcase carcase, fall, ruin.', 'from 5307;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0738B}/[H717]', 'inflected', 'heb', 'אֲרִי', '["ʼărîy"]', '["<the>/ lion","the/ lion"]', '["n-m"]', 'a lion (young) lion, pierce (from the margin).', 'or (prolonged) אַרְיֵה; from 717 (in the sense of violence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1682}/[H1696]', 'lemma', 'heb', 'דְּבוֹרָה', '["dᵉbôwrâh"]', '["bees"]', '["n-f"]', 'the bee (from its systematic instincts) bee.', 'or (shortened) דְּבֹרָה; from 1696 (in the sense of orderly motion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1472}/[H1465]', 'inflected', 'heb', 'גְּוִיָּה', '["gᵉvîyâh"]', '["[was] in/ [the] carcass of"]', '["n-f"]', 'a body, whether alive or dead (dead) body, carcase, corpse.', 'prolonged for 1465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7287B}/H9033/[H7287]', 'inflected', 'heb', 'רָדָה', '["râdâh"]', '["and/ he scraped out/ it"]', '["v"]', 'to tread down, i.e. subjugate; specifically, to crumble off (come to, make to) have dominion, prevail against, reign, (bear, make to) rule,(-r, over), take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1472}/[H1465]', 'inflected', 'heb', 'גְּוִיָּה', '["gᵉvîyâh"]', '["from/ [the] carcass of"]', '["n-f"]', 'a body, whether alive or dead (dead) body, carcase, corpse.', 'prolonged for 1465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7287B}/[H7287]', 'lemma', 'heb', 'רָדָה', '["râdâh"]', '["he had scraped out","they are ruling"]', '["v"]', 'to tread down, i.e. subjugate; specifically, to crumble off (come to, make to) have dominion, prevail against, reign, (bear, make to) rule,(-r, over), take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1706>', 'inflected', 'heb', 'הדבש', '["ha./de.Vash"]', '["the/ honey"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0970}/[H977]', 'inflected', 'heb', 'בָּחוּר', '["bâchûwr"]', '["the/ young men"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7200G}/H9048/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["when/ saw/ they"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4828}/[H7462]', 'lemma', 'heb', 'מֵרֵעַ', '["mêrêaʻ"]', '["companions"]', '["n-m"]', 'a friend companion, friend.', 'from 7462 in the sense of companionship;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2330}/[H2330]', 'lemma', 'heb', 'חוּד', '["chûwd"]', '["ask a riddle","let me ask a riddle","you have asked [the] riddle"]', '["v"]', 'properly, to tie a knot, i.e. (figuratively) to propound a riddle put forth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2420}/[H2330]', 'lemma', 'heb', 'חִידָה', '["chîydâh"]', '["a riddle","of intrigue<s>","riddles"]', '["n-f"]', 'a puzzle, hence, a trick, conundrum, sententious maxim dark saying (sentence, speech), hard question, proverb, riddle.', 'from 2330;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4960}/[H8354]', 'inflected', 'heb', 'מִשְׁתֶּה', '["mishteh"]', '["the/ feast"]', '["n-m"]', 'drink, by implication, drinking (the act); also (by implication) a banquet or (generally) feast banquet, drank, drink, feast((-ed), -ing).', 'from 8354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5466>', 'opaque', 'heb', 'סָדִין', '["çâdîyn"]', '["linen garment[s]","linen garments"]', '["n-m"]', 'a wrapper, i.e. shirt fine linen, sheet.', 'from an unused root meaning to envelop;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2330}/H9012/[H2330]', 'inflected', 'heb', 'חוּד', '["chûwd"]', '["ask [the] riddle/ !"]', '["v"]', 'properly, to tie a knot, i.e. (figuratively) to propound a riddle put forth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2420}/H9021/[H2330]', 'inflected', 'heb', 'חִידָה', '["chîydâh"]', '["riddle/ your"]', '["n-f"]', 'a puzzle, hence, a trick, conundrum, sententious maxim dark saying (sentence, speech), hard question, proverb, riddle.', 'from 2330;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8085G}/H9034/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["so/ we may hear/ it"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H0398}/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["from/ the/ eater"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5794}/[H5810]', 'inflected', 'heb', 'עַז', '["ʻaz"]', '["and/ from/ a strong [one]"]', '["a"]', 'strong, vehement, harsh fierce, greedy, mighty, power, roughly, strong.', 'from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4966}/[H4985]', 'lemma', 'heb', 'מָתוֹק', '["mâthôwq"]', '["[is] sweet","[was] sweet","a sweet [thing]"]', '["a"]', 'sweet sweet(-er, -ness).', 'or מָתוּק; from 4985;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2420}/[H2330]', 'inflected', 'heb', 'חִידָה', '["chîydâh"]', '["<of> the/ riddle","the/ riddle"]', '["n-f"]', 'a puzzle, hence, a trick, conundrum, sententious maxim dark saying (sentence, speech), hard question, proverb, riddle.', 'from 2330;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H3423I}/H9035/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["¿/ to/ impoverish/ us"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8130}/H9030/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["[one who] hated/ me","[one who] hates/ me","[those who] hate/ me","they have hated/ me","you hate/ me"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H9030}', 'inflected', 'arc', 'ולי', '["ve./L/i"]', '["and/ <obj.>/ me","and/ <to>/ me","and/ [belongs] to/ me","and/ to <the>/ me","and/ to/ me"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0517}/H9020/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["and/ <to>/ mother/ my","and/ to/ mother/ my"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6693}/H9033/[H6693]', 'inflected', 'heb', 'צוּק', '["tsûwq"]', '["she pressed/ him"]', '["v"]', 'to compress, i.e. (figuratively) oppress, distress constrain, distress, lie sore, (op-) press(-or), straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2775A>/H9011', 'inflected', 'heb', 'החרסה', '["ha./Char.sa/h"]', '["the/ sun/ <towards>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1706>', 'inflected', 'heb', 'מדבש', '["mi./de.Vash"]', '["more than/ honey"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0738A}/[H717]', 'inflected', 'heb', 'אֲרִי', '["ʼărîy"]', '["more than/ a lion","more than/ lions"]', '["n-m"]', 'a lion (young) lion, pierce (from the margin).', 'or (prolonged) אַרְיֵה; from 717 (in the sense of violence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5697A}/H9020/[H5695]', 'inflected', 'heb', 'עֶגְלָה', '["ʻeglâh"]', '["with/ heifer/ my"]', '["n-f"]', 'a (female) calf, especially one nearly grown (i.e. a heifer) calf, cow, heifer.', 'feminine of 5695;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2420}/H9020/[H2330]', 'inflected', 'heb', 'חִידָה', '["chîydâh"]', '["riddle/ my"]', '["n-f"]', 'a puzzle, hence, a trick, conundrum, sententious maxim dark saying (sentence, speech), hard question, proverb, riddle.', 'from 2330;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2488}/H9028/[H2503]', 'inflected', 'heb', 'חֲלִיצָה', '["chălîytsâh"]', '["spoils/ their"]', '["n-f"]', 'spoil armour.', 'from 2503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2487}/[H2498]', 'inflected', 'heb', 'חֲלִיפָה', '["chălîyphâh"]', '["the/ changes"]', '["n-f"]', 'alternation change, course.', 'from 2498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4828}/H9023/[H7462]', 'inflected', 'heb', 'מֵרֵעַ', '["mêrêaʻ"]', '["to/ companion/ his"]', '["n-m"]', 'a friend companion, friend.', 'from 7462 in the sense of companionship;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7462D}/[H7462]', 'lemma', 'heb', 'רָעָה', '["râʻâh"]', '["he was a special friend"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1423}/[H1415]', 'inflected', 'heb', 'גְּדִי', '["gᵉdîy"]', '["with/ a kid of"]', '["n-m"]', 'a young goat (from browsing) kid.', 'from the same as 1415;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8130}/H9034/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["I hate/ it","he hated/ her","you hated/ her"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414O}/H9034/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I gave/ her","and/ he has given/ her"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4828}/H9021/[H7462]', 'inflected', 'heb', 'מֵרֵעַ', '["mêrêaʻ"]', '["to/ companion/ your"]', '["n-m"]', 'a friend companion, friend.', 'from 7462 in the sense of companionship;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7776}/[H8168]', 'lemma', 'heb', 'שׁוּעָל', '["shûwʻâl"]', '["a fox","foxes"]', '["n-m"]', 'a jackal (as a burrower) fox.', 'or שֻׁעָל; from the same as 8168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3940>', 'opaque', 'heb', 'לַפִּיד', '["lappîyd"]', '["a torch","torches"]', '["n-m"]', 'a flambeau, lamp or flame (fire-) brand, (burning) lamp, lightning, torch.', 'or לַפִּד; from an unused root probably meaning to shine;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2180}/[H2179]', 'lemma', 'heb', 'זָנָב', '["zânâb"]', '["[the] stumps of","tail"]', '["n-m"]', 'the tail (literally or figuratively) tail.', 'from 2179 (in the original sense of flapping);');
