INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5585}/[H5586]', 'inflected', 'heb', 'סָעִיף', '["çâʻîyph"]', '["in/ [the] cleft of"]', '["n-m"]', 'a fissure (of rocks); also a bough (as subdivided) (outmost) branch, clift, top.', 'from 5586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5553H>', 'opaque', 'heb', 'סֶלַע', '["çelaʻ"]', '["[the] rock of","a rock","cliffs","crags","rock","rocks"]', '["n-m"]', 'a craggy rock, literally or figuratively (a fortress) (ragged) rock, stone(-ny), strong hold.', 'from an unused root meaning to be lofty;');
