INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5414G}/H9031/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will give/ you","and/ we will give/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9031/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["I will put to death/ you","we will kill/ you","we will put to death/ you"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0631}/H9033/[H631]', 'inflected', 'heb', 'אָסַר', '["ʼâçar"]', '["and/ he bound/ him","and/ he confined/ him","and/ she bound/ him","and/ they bound/ him","and/ we will bind/ him"]', '["v"]', 'to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3896}/[H3895]', 'lemma', 'heb', 'לֶחִי', '["Lechîy"]', '["Lehi"]', '["n-pr-loc"]', 'Lechi, a place in Palestine Lehi. Compare also 7437.', 'a form of 3895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6430G}/[H6429]', 'inflected', 'heb', 'פְּלִשְׁתִּי', '["Pᵉlishtîy"]', '["and/ Philistines","and/ [the] Philistines"]', '["a"]', 'a Pelishtite or inhabitant of Pelesheth Philistine.', 'patrial from 6429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2220}/H9023/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["arm/ his","arms/ his","own arm/ his","strength/ his"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6593}/[H6580]', 'inflected', 'heb', 'פִּשְׁתֶּה', '["pishteh"]', '["like <the>/ flax<es>"]', '["n-f"]', 'linen (i.e. the thread, as carded) flax, linen.', 'from the same as 6580 as in the sense of comminuting;');
