INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3895H>', 'opaque', 'heb', 'לְחִי', '["lᵉchîy"]', '["[the] jaws of","a cheek","a jawbone of","jaw"]', '["n-m"]', 'the cheek (from its fleshiness); hence, the jaw-bone cheek (bone), jaw (bone).', 'from an unused root meaning to be soft;');
