INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8668H}/[H7768]', 'inflected', 'heb', 'תְּשׁוּעָה', '["tᵉshûwʻâh"]', '["the/ deliverance","the/ victory"]', '["n-f"]', 'rescue (literal or figurative, persons, national or spiritual) deliverance, help, safety, salvation, victory.', 'or תְּשֻׁעָה; from 7768 in the sense of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4388}/[H3806]', 'inflected', 'heb', 'מַכְתֵּשׁ', '["maktêsh"]', '["the/ deep hollow"]', '["n-m"]', 'a mortar; by analogy, a socket (of a tooth) hollow place, mortar.', 'from 3806;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3895G>', 'inflected', 'heb', 'בלחי', '["ba./Le.chi"]', '["[is] at <the>/ Lehi"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5875}/[H5869]', 'lemma', 'heb', 'עֵין הַקּוֹרֵא', '["ʻÊyn haq-Qôwrêʼ"]', '["En","Hakkore"]', '["n-pr-loc"]', 'En-hak-Kore, a place near Palestine En-hakhore.', 'from 5869 and the active participle of 7121; fountain of One calling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5804}/H9011/[H5794]', 'inflected', 'heb', 'עַזָּה', '["ʻAzzâh"]', '["Gaza/ towards"]', '["n-f"]', 'Azzah, a place in Palestine Azzah, Gaza.', 'feminine of 5794; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5841}/[H5804]', 'inflected', 'heb', 'עַזָּתִי', '["ʻAzzâthîy"]', '["to the/ Gazites"]', '["a"]', 'an Azzathite or inhabitant of Azzah Gazathite, Gazite.', 'patrial from 5804;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1817C}/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["on/ [the] doors of","with the/ door","with/ doors"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8147}/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["and/ in/ two [plus]","and/ on/ [the] two","and/ on/ two [occasions]","and/ with/ two [wings]"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5265}/H9038/[H5265]', 'inflected', 'heb', 'נָסַע', '["nâçaʻ"]', '["and/ he pulled up/ them"]', '["v"]', 'properly, to pull up, especially the tent-pins, i.e. start on a journey cause to blow, bring, get, (make to) go (away, forth, forward, onward, out), (take) journey, march, remove, set aside (forward), × still, be on his (go their) way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5927H}/H9038/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ I will bring up/ them","and/ he brought up/ them","and/ he carried up/ them","and/ he raised/ them"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2275A}\/[H2267]', 'inflected', 'heb', 'חֶבְרוֹן', '["Chebrôwn"]', '["Hebron"]', '["n-pr-loc n-pr-m"]', 'Chebron, a place in Palestine, also the name of two Israelites Hebron.', 'from 2267; seat of association;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5158J}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["in/ [the] valley of"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7796}/[H8321]', 'lemma', 'heb', 'שׂוֹרֵק', '["Sôwrêq"]', '["Sorek"]', '["n-pr-loc"]', 'Sorek, a valley in Palestine Sorek.', 'the same as 8321; a vine;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1807}/[H1809]', 'lemma', 'heb', 'דְּלִילָה', '["Dᵉlîylâh"]', '["Delilah","[was] Delilah"]', '["n-pr-f"]', 'Delilah, a Philistine woman Delilah.', 'from 1809; languishing');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3581B>/H9023', 'opaque', 'heb', 'כֹּחַ', '["kôach"]', '["[is] strength/ his","power/ his","strength/ his","strength/ its"]', '["n-m"]', 'vigor, literally (force, in a good or a bad sense) or figuratively (capacity, means, produce); also (from its hardiness) a large lizard ability, able, chameleon, force, fruits, might, power(-ful), strength, substance, wealth.', 'or (Daniel 11:6) כּוֹחַ; from an unused root meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6031B}/H9033/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["to/ afflict/ it","to/ humble/ him"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3581B>/H9021', 'opaque', 'heb', 'כֹּחַ', '["kôach"]', '["[is] strength/ your","strength/ your"]', '["n-m"]', 'vigor, literally (force, in a good or a bad sense) or figuratively (capacity, means, produce); also (from its hardiness) a large lizard ability, able, chameleon, force, fruits, might, power(-ful), strength, substance, wealth.', 'or (Daniel 11:6) כּוֹחַ; from an unused root meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6031B}/H9031/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["to/ humble/ you"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0631}/H9030/[H631]', 'inflected', 'heb', 'אָסַר', '["ʼâçar"]', '["people will bind/ me","they will bind/ me"]', '["v"]', 'to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3499B}/[H3498]', 'lemma', 'heb', 'יֶתֶר', '["yether"]', '["[the] string","cords"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2470A}/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["and/ I will be weak"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3499B}/[H3498]', 'inflected', 'heb', 'יֶתֶר', '["yether"]', '["the/ cords"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5296}/[H5287]', 'inflected', 'heb', 'נְעֹרֶת', '["nᵉʻôreth"]', '["<the>/ tow"]', '["n-f"]', 'something shaken out, i.e. tow (as the refuse of flax) tow.', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7306}/H9043/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["when/ smells/ it"]', '["v"]', 'properly, to blow, i.e. breathe; only (literally) to smell or (by implication, perceive (figuratively, to anticipate, enjoy) accept, smell, × touch, make of quick understanding.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3577}/[H3576]', 'lemma', 'heb', 'כָּזָב', '["kâzâb"]', '["<of> falsehood","[are] falsehood","falsehood","lies"]', '["n-m"]', 'falsehood; literally (untruth) or figuratively (idol) deceitful, false, leasing, liar, lie, lying.', 'from 3576;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5688}/[H5687]', 'inflected', 'heb', 'עֲבֹת', '["ʻăbôth"]', '["with/ ropes","with/ ropes of"]', '["n"]', 'something intwined, i.e. a string, wreath or foliage band, cord, rope, thick bough (branch), wreathen (chain).', 'or עֲבוֹת; or (feminine) עֲבֹתָה; the same as 5687;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5423}/H9038/[H5423]', 'inflected', 'heb', 'נָתַק', '["nâthaq"]', '["and/ he tore apart/ them"]', '["v"]', 'to tear off break (off), burst, draw (away), lift up, pluck (away, off), pull (out), root out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H2339>', 'inflected', 'heb', 'כחוט', '["ka./Chut","ke./Chut"]', '["[are] like/ [the] thread of","like <the>/ thread"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4253}/[H2498]', 'lemma', 'heb', 'מַחְלָפָה', '["machlâphâh"]', '["[the] plaits","[the] plaits of"]', '["n-f"]', 'a ringlet of hair (as gliding over each other) lock.', 'from 2498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4545}/[H5259]', 'inflected', 'heb', 'מַסֶּכֶת', '["maççeketh"]', '["the/ web"]', '["n-f"]', 'something expanded, i.e. the warp in a loom (as stretched out to receive the woof) web.', 'from 5259 in the sense of spreading out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3489>', 'inflected', 'heb', 'ביתד', '["ba/i.ya.Ted","be./ya.Ted"]', '["with the/ pin","with/ a pin"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3462}/H9033/[H3462]', 'inflected', 'heb', 'יָשֵׁן', '["yâshên"]', '["and/ she made sleep/ him"]', '["v"]', 'properly, to be slack or languid, i.e. (by implication) sleep (figuratively, to die); also to grow old, stale or inveterate old (store), remain long, (make to) sleep.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0707}/[H707]', 'inflected', 'heb', 'אָרַג', '["ʼârag"]', '["and/ she wove"]', '["v"]', 'to plait or weave weaver(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0708}/[H707]', 'inflected', 'heb', 'אֶרֶג', '["ʼereg"]', '["the/ loom"]', '["n-m"]', 'a weaving; a braid; also a shuttle beam, weaver''s shuttle.', 'from 707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157G}/H9032/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["I have loved/ you","I love/ you","[those who] love/ you","lovers/ your","she loves/ you"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3820A}/H9021/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["and/ heart/ your"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1697G}/H9024/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["with/ words/ her"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0509}/H9033/[H509]', 'inflected', 'heb', 'אָלַץ', '["ʼâlats"]', '["and/ she urged/ him"]', '["v"]', 'to press urge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4177}/[H4171]', 'lemma', 'heb', 'מוֹרָה', '["môwrâh"]', '["a razor"]', '["n-m"]', 'a razor razor.', 'from 4171 in the sense of shearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0990H>', 'inflected', 'heb', 'מבטן', '["mi./Ba.ten","mi./Be.ten"]', '["from/ [the] belly","from/ [the] belly of","from/ [the] womb","from/ [the] womb of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H5633A>', 'inflected', 'heb', 'לסרני', '["le./sar.Nei"]', '["<to>/ [the] rulers of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1290}/H9024/[H1288]', 'inflected', 'heb', 'בֶּרֶךְ', '["berek"]', '["knees/ her"]', '["n-f"]', 'a knee knee.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5287}/[H5286]', 'inflected', 'heb', 'נָעַר', '["nâʻar"]', '["and/ [is] shaking off","so/ I may shake myself free","so/ they may be shaken"]', '["v"]', 'to tumble about shake (off, out, self), overthrow, toss up and down.', 'a primitive root (probably identical with 5286, through the idea of the rustling of mane, which usually accompanies the lion''s roar);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0270}/H9033/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["and/ they seized/ him"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5365}/[H5365]', 'inflected', 'heb', 'נָקַר', '["nâqar"]', '["and/ they gouged out"]', '["v"]', 'to bore (penetrate, quarry) dig, pick out, pierce, put (thrust) out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5178A}/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["in <the>/ bronze","with <the>/ bronze","with <the>/ bronze fetters"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0631}/[H631]', 'inflected', 'heb', 'אָסַר', '["ʼâçar"]', '["the/ prisoners","those/ imprisoned"]', '["v"]', 'to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6779}/[H6779]', 'inflected', 'heb', 'צָמַח', '["tsâmach"]', '["to/ grow back"]', '["v"]', 'to sprout (transitive or intransitive, literal or figurative) bear, bring forth, (cause to, make to) bud (forth), (cause to, make to) grow (again, up), (cause to) spring (forth, up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1548}\/[H1548]', 'inflected', 'heb', 'גָּלַח', '["gâlach"]', '["it had been shaved"]', '["v"]', 'properly, to be bald, i.e. (causatively) to shave; figuratively to lay waste poll, shave (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5633A>', 'inflected', 'heb', 'וסרני', '["ve./sar.Nei"]', '["and/ [the] rulers of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1712}/[H1709]', 'inflected', 'heb', 'דָּגוֹן', '["Dâgôwn"]', '["to/ Dagon"]', '["n-pr-m"]', 'Dagon, a Philistine deity Dagon.', 'from 1709; the fish-god;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8057}/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["and/ <into>/ [the] delight of","and/ <into>/ gladness","and/ for/ joy","and/ of/ pleasure"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0341}/H9025/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["enemies/ our","enemy/ our"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2717B}/[H2717]', 'lemma', 'heb', 'חָרַב', '["chârab"]', '["I have made desolate","I will lay waste","[the] desolator of","be desolate","certainly <to be desolate>","desolate","it has been laid waste","it laid waste","it will be desolate","laid waste","made waste","they have made desolate","they may be waste","they will be waste","they will become desolate"]', '["v"]', 'to parch (through drought) i.e. (by analogy,) to desolate, destroy, kill decay, (be) desolate, destroy(-er), (be) dry (up), slay, × surely, (lay, lie, make) waste.', 'or חֲרֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2491A}/H9025/[H2490]', 'inflected', 'heb', 'חָלָל', '["châlâl"]', '["slain [ones]/ our"]', '["n-m"]', 'pierced (especially to death); figuratively, polluted kill, profane, slain (man), × slew, (deadly) wounded.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2895}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["like/ good","when/ is good","when/ was good"]', '["v"]', 'to be (transitively, do or make) good (or well) in the widest sense be (do) better, cheer, be (do, seem) good, (make) goodly, × please, (be, do, go, play) well.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7832}/[H7832]', 'inflected', 'heb', 'שָׂחַק', '["sâchaq"]', '["and/ let them play","and/ making merry","so/ he may make sport","so/ it may laugh"]', '["v"]', 'to laugh (in pleasure or detraction); by implication, to play deride, have in derision, laugh, make merry, mock(-er), play, rejoice, (laugh to) scorn, be in (make) sport.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2388H}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["who/ kept hold"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4184}/H9030/[H4184]', 'inflected', 'heb', 'מוּשׁ', '["mûwsh"]', '["and/ let feel/ me"]', '["v"]', 'to touch feel, handle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1004B}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ the/ house"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7832}/[H7832]', 'inflected', 'heb', 'שָׂחַק', '["sâchaq"]', '["when/ sported"]', '["v"]', 'to laugh (in pleasure or detraction); by implication, to play deride, have in derision, laugh, make merry, mock(-er), play, rejoice, (laugh to) scorn, be in (make) sport.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2388G}/H9030/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ strengthen/ me"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5358}/[H5358]', 'inflected', 'heb', 'נָקַם', '["nâqam"]', '["and/ I will avenge myself","and/ an avenger","and/ avenge yourself","and/ avenging yourself","so/ let me avenge myself"]', '["v"]', 'to grudge, i.e. avenge or punish avenge(-r, self), punish, revenge (self), × surely, take vengeance.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3943}/[H3943]', 'inflected', 'heb', 'לָפַת', '["lâphath"]', '["and/ he grasped","and/ he twisted"]', '["v"]', 'properly, to bend, i.e. (by implication) to clasp; also (reflexively) to turn around or aside take hold, turn aside (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H8432>', 'inflected', 'heb', 'התוך', '["ha./Ta.vekh"]', '["the/ middle"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5633A>', 'inflected', 'heb', 'הסרנים', '["ha./se.ra.Nim"]', '["the/ rulers"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4194}/H9023/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["at/ death/ his","in/ death/ his","in/ death<s>/ his"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2416E}/H9023/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["in/ life/ his"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2022H}/[H2042]', 'inflected', 'heb', 'הַר', '["har"]', '["[was] from/ [the] hill country of","from/ [the] hill country of","from/ [the] mountain of"]', '["n-m"]', 'a mountain or range of hills (sometimes used figuratively) hill (country), mount(-ain), × promotion.', 'a shortened form of 2042;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4321I}/[H4322]', 'lemma', 'heb', 'מִיכָיְהוּ', '["Mîykâyᵉhûw"]', '["Micaiah","[was] Micaiah"]', '["n-pr-m"]', 'Mikajah, the name of three Israelites Micah, Micaiah, Michaiah.', 'or מִכָיְהוּ; (Jeremiah 36:11), abbreviated form for 4322;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0422}/[H422]', 'lemma', 'heb', 'אָלָה', '["ʼâlâh"]', '["cursing","he will swear an oath","they have sworn an oath","you cursed"]', '["v"]', 'properly, to adjure, i.e. (usually in a bad sense) imprecate adjure, curse, swear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241I}/H9020/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["in/ ears/ my"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725H}/H9033/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["I will return/ it"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6884}/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["for the/ metalsmith","to the/ silversmith","to/ refine"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4318G}/[H4320]', 'lemma', 'heb', 'מִיכָה', '["Mîykâh"]', '["Micah"]', '["n-pr-m"]', 'Micah, the name of seven Israelites Micah, Micaiah, Michah.', 'an abbreviated form of 4320;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8655}/[H7495]', 'inflected', 'heb', 'תְּרָפִים', '["tᵉrâphîym"]', '["and/ teraphim"]', '["n-m"]', 'Teraphim (singular or plural) a family idol idols(-atry), images, teraphim.', 'plural from 7495; a healer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6213J}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["to/ [the] doers of","to/make"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3117I>', 'inflected', 'heb', 'לימים', '["Le./ya.mim","la/i.ya.Mim","le./ya.Mim"]', '["of/ days","to the/ days","to/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6187}/[H6186]', 'inflected', 'heb', 'עֵרֶךְ', '["ʻêrek"]', '["and/ an order of"]', '["n-m"]', 'a pile, equipment, estimate equal, estimation, (things that are set in) order, price, proportion, × set at, suit, taxation, × valuest.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4241}/H9021/[H2421]', 'inflected', 'heb', 'מִחְיָה', '["michyâh"]', '["and/ sustenance/ your"]', '["n-f"]', 'preservation of life; hence, sustenance; also the live flesh, i.e. the quick preserve life, quick, recover selves, reviving, sustenance, victuals.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5159}\/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["<in>/ an inheritance"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4940}/H9028/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["from/ tribe/ their"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7098}/H9028/[H7097]', 'inflected', 'heb', 'קָצָה', '["qâtsâh"]', '["from/ among/ themselves","from/ ends/ their"]', '["n"]', 'a termination coast, corner, (selv-) edge, lowest, (uttermost) participle', 'feminine of 7097; (used like 7097)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0847}/[H7592]', 'inflected', 'heb', 'אֶשְׁתָּאֹל', '["ʼEshtâʼôl"]', '["and/ from/ Eshtaol"]', '["n-pr-loc"]', 'Eshtaol, a place in Palestine Eshtaol.', 'or אֶשְׁתָּאוֹל; probably from 7592; intreaty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2713}/H9034/[H2713]', 'inflected', 'heb', 'חָקַר', '["châqar"]', '["and/ to/ explore/ it"]', '["v"]', 'properly, to penetrate; hence, to examine intimately find out, (make) search (out), seek (out), sound, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2713}/[H2713]', 'lemma', 'heb', 'חָקַר', '["châqar"]', '["I will sound out","[am] searching","[is] searching for","explore","he will examine","it was ascertained","it will be searched","they will make a search","to explore","to search out","will he search out"]', '["v"]', 'properly, to penetrate; hence, to examine intimately find out, (make) search (out), seek (out), sound, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2090}/[H2088]', 'inflected', 'heb', 'זֹה', '["zôh"]', '["like/ this"]', '["d"]', 'this or that as well as another, it, this, that, thus and thus.', 'for 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H2088}/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["and/ like/ this"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7936B}/H9030/[H3739]', 'inflected', 'heb', 'שָׂכַר', '["sâkar"]', '["and/ he has hired/ me"]', '["v"]', 'to hire earn wages, hire (out self), reward, × surely.', 'or (by permutation) סָכַר; (Ezra 4:5), a primitive root (apparently akin (by prosthesis) to 3739 through the idea of temporary purchase; compare 7937);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870L}/H9025/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["journey/ our"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870L}/H9026/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["way/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3919A}/H9011/[H3918]', 'inflected', 'heb', 'לַיִשׁ', '["Layish"]', '["Laish/ towards"]', '["n-pr-m n-pr-loc"]', 'Laish, the name of two places in Palestine Laish. Compare 3889.', 'the same as 3918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0982}/[H982]', 'inflected', 'heb', 'בָּטַח', '["bâṭach"]', '["and/ [is] confident","and/ [one who] relies","and/ [one who] trusts","and/ rely","and/ secure","and/ they may trust","and/ trust","so/ they may trust"]', '["v"]', 'properly, to hie for refuge (but not so precipitately as 2620); figuratively, to trust, be confident or sure be bold (confident, secure, sure), careless (one, woman), put confidence, (make to) hope, (put, make to) trust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6114}/[H6113]', 'lemma', 'heb', 'עֶצֶר', '["ʻetser"]', '["oppression"]', '["n-m"]', 'restraint magistrate.', 'from 6113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7350}/[H7368]', 'inflected', 'heb', 'רָחוֹק', '["râchôwq"]', '["and/ [is] far","and/ [were] far","and/ distant","and/ distant [ones]"]', '["a"]', 'remote, literally or figuratively, of place or time; specifically, precious; often used adverbially (with preposition) (a-) far (abroad, off), long ago, of old, space, great while to come.', 'or רָחֹק; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6722}/[H6721]', 'inflected', 'heb', 'צִידֹנִי', '["Tsîydônîy"]', '["from/ [the] Sidonians"]', '["a"]', 'a Tsidonian or inhabitant of Tsidon Sidonian, of Sidon, Zidonian.', 'patrial from 6721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2814}/[H2814]', 'lemma', 'heb', 'חָשָׁה', '["châshâh"]', '["I have been silent","I was silent","I will be silent","[are] inactive","[are] silent","[were] making quiet","be silent","silent","they will be silent","will you be silent?","you should be silent"]', '["v"]', 'to hush or keep quiet hold peace, keep silence, be silent, (be) still.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6101}/[H6101]', 'lemma', 'heb', 'עָצַל', '["ʻâtsal"]', '["you hesitate"]', '["v"]', 'to lean idly, i.e. to be indolent or slack be slothful.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027Q}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["both hands"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4270}/[H2637]', 'lemma', 'heb', 'מַחְסוֹר', '["machçôwr"]', '["[is] lack","[is] lack of","lack","poverty"]', '["n-m"]', 'deficiency; hence, impoverishment lack, need, penury, poor, poverty, want.', 'or מַחְסֹר; from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7157}/[H7151]', 'inflected', 'heb', 'קִרְיַת יְעָרִים', '["Qiryath Yᵉʻârîym"]', '["at/ Kiriath"]', '["n-pr-loc"]', 'Kirjath-Jearim or Kirjath-Arim, a place in Palestine Kirjath, Kirjath-jearim, Kirjath-arim.', 'or (Jeremiah 26:20) with the article interposed; or (Joshua 18:28) simply the former part of the word; or קִרְיַת עָרִים; from 7151 and the plural of 3293 or 5892; city of forests, or city of towns;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3919A}/[H3918]', 'lemma', 'heb', 'לַיִשׁ', '["Layish"]', '["Laish","[was] Laish"]', '["n-pr-m n-pr-loc"]', 'Laish, the name of two places in Palestine Laish. Compare 3889.', 'the same as 3918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4421}/H9028/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["war/ their"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6459}/[H6458]', 'inflected', 'heb', 'פֶּסֶל', '["peçel"]', '["the/ carved image","the/ idol"]', '["n-m"]', 'an idol carved (graven) image.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4541A}/[H5258]', 'inflected', 'heb', 'מַסֵּכָה', '["maççêkâh"]', '["the/ molten image"]', '["n-f"]', 'properly, a pouring over, i.e. fusion of metal (especially a cast image); by implication, a libation, i.e. league; concretely a coverlet (as if poured out) covering, molten (image), vail.', 'from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2296}/[H2296]', 'inflected', 'heb', 'חָגַר', '["châgar"]', '["<the>/ girded"]', '["v"]', 'to gird on (as a belt, armor, etc.) be able to put on, be afraid, appointed, gird, restrain, × on every side.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1980H}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ come"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1961}/H9041/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["[is] being/ you","being/ you"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004B}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["<into>/ a house of","<to> the/ house","[belonged] to the/ house","[belongs] to the/ house","for the/ house","for/ [the] house of","for/ a house of","for/ houses","into/ [the] house of","of the/ house","of/ [the] house of","to the/ house","to/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3520B}/[H3513]', 'inflected', 'heb', 'כְּבוּדָּה', '["kᵉbûwddâh"]', '["the/ valuable[s]"]', '["n-f"]', 'weightiness, i.e. magnificence, wealth carriage, all glorious, stately.', 'irregular feminine passive participle of 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4318G}/[H4320]', 'inflected', 'heb', 'מִיכָה', '["Mîykâh"]', '["to/ Micah"]', '["n-pr-m"]', 'Micah, the name of seven Israelites Micah, Micaiah, Michah.', 'an abbreviated form of 4320;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963A>/H9021', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["voice/ your"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315L}/[H5314]', 'lemma', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["[the] appetite of","appetite","desire"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315H}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ [the] life of","and/ [the] lives of","and/ person[s] of"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1870L}/H9028/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["to/ way/ their"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1050}/[H1004]', 'inflected', 'heb', 'בֵּית רְחוֹב', '["Bêyth Rᵉchôwb"]', '["[belongs] to/ Beth"]', '["n-pr-loc"]', 'Beth-Rechob, a place in Palestine Beth-rehob.', 'from 1004 and 7339; house of (the) street;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1050}/[H1004]', 'lemma', 'heb', 'בֵּית רְחוֹב', '["Bêyth Rᵉchôwb"]', '["Beth","Rehob"]', '["n-pr-loc"]', 'Beth-Rechob, a place in Palestine Beth-rehob.', 'from 1004 and 7339; house of (the) street;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3083G}/[H3068]', 'inflected', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["and/ Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4519K}/[H5382]', 'lemma', 'heb', 'מְנַשֶּׁה', '["Mᵉnashsheh"]', '["Manasseh"]', '["n-pr-m"]', 'Menashsheh, a grandson of Jacob, also the tribe descended from him, and its territory Manasseh.', 'from 5382; causing to forget;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1540K}/[H1540]', 'lemma', 'heb', 'גָּלָה', '["gâlâh"]', '["I have sent into exile","I sent into exile","[are] an exile","[those who] go into exile","certainly <go into exile>","gone into exile","he had been taken into exile","he had taken into exile","he took into exile","it disappears","it had been taken into exile","it has been taken into exile","it has departed","it has gone into exile","it will depart","it will go into exile","she has gone into exile","they had been taken into exile","they had taken into exile","they took into exile","they went into exile","they were taken into exile","they will go into exile","took into exile","went into exile","went into exile of","you took into exile"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7887}\/[H7886]', 'inflected', 'heb', 'שִׁילֹה', '["Shîylôh"]', '["at/ Shiloh","in/ Shiloh"]', '["n-pr-loc"]', 'Shiloh, a place in Palestine Shiloh.', 'or שִׁלֹה; or שִׁילוֹ; or שִׁלוֹ; from the same as 7886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6370>/H9023', 'opaque', 'heb', 'פִּילֶגֶשׁ', '["pîylegesh"]', '["concubine/ his"]', '["n-f"]', 'a concubine; also (masculine) a paramour concubine, paramour.', 'or פִּלֶגֶשׁ; of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9024/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart/ her"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725H}/H9034/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["to/ bring back/ her"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5288}/H9023/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["and/ servant/ his"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6776}/[H6776]', 'inflected', 'heb', 'צֶמֶד', '["tsemed"]', '["and/ a pair of"]', '["n-m"]', 'a yoke or team (i.e. pair); hence, an acre (i.e. day''s task for a yoke of cattle to plough) acre, couple, × together, two (donkeys), yoke (of oxen).', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5582}/[H5582]', 'lemma', 'heb', 'סָעַד', '["çâʻad"]', '["it sustains","sustain"]', '["v"]', 'to support (mostly figurative) comfort, establish, hold up, refresh self, strengthen, be upholden.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6150}/[H6148]', 'inflected', 'heb', 'עָרַב', '["ʻârab"]', '["to/ become evening"]', '["v"]', 'to grow dusky at sundown be darkened, (toward) evening.', 'a primitive root (rather identical with 6148 through the idea of covering with a texture);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0168H}/H9021/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["to/ tent/ your"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2982}/[H947]', 'lemma', 'heb', 'יְבוּס', '["Yᵉbûwç"]', '["Jebus","[was] Jebus"]', '["n-pr-loc"]', 'Jebus, the original name of Jerusalem Jebus.', 'from 947; trodden, i.e. threshing-place;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6776}/[H6776]', 'lemma', 'heb', 'צֶמֶד', '["tsemed"]', '["[the] pair of","a pair of","acres of","an acre of","pair[s] of","pairs"]', '["n-m"]', 'a yoke or team (i.e. pair); hence, an acre (i.e. day''s task for a yoke of cattle to plough) acre, couple, × together, two (donkeys), yoke (of oxen).', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2280}/[H2280]', 'lemma', 'heb', 'חָבַשׁ', '["châbash"]', '["I will bind up","[is] wrapped round","[were] saddled","a wrapper","bind","bind up","binds up","bound","he restrains","it has been bound up","let me saddle","saddle","saddled","they have been bound up","will he govern","you have bound up"]', '["v"]', 'to wrap firmly (especially a turban, compress, or saddle); figuratively, to stop, to rule bind (up), gird about, govern, healer, put, saddle, wrap about.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5493I}/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["and/ [one who] turns aside","and/ [who] turns aside","and/ they have turned aside","and/ to turn","and/ turning aside","and/ we have turned aside","so/ let us turn aside"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1390H}/[H1389]', 'lemma', 'heb', 'גִּבְעָה', '["Gibʻâh"]', '["Gibeah","Gibeah of"]', '["n-pr-loc"]', 'Gibah; the name of three places in Palestine Gibeah, the hill.', 'the same as 1389;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5288}/H9023/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["to/ lad/ his","to/ servant/ his"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980N}/H9012/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["come/ !"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7126G}/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["and/ bring near","and/ draw near","and/ it may draw near","and/ you may bring [him] near","so/ let us drew near"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7414G}/[H7413]', 'inflected', 'heb', 'רָמָה', '["Râmâh"]', '["in <the>/ Ramah","in/ Ramah"]', '["n-pr-loc"]', 'Ramah, the name of four places in Palestine Ramah.', 'the same as 7413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1390H}/[H1389]', 'inflected', 'heb', 'גִּבְעָה', '["Gibʻâh"]', '["<the>/ Gibeah"]', '["n-pr-loc"]', 'Gibah; the name of three places in Palestine Gibeah, the hill.', 'the same as 1389;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4639G}/H9023/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["work/ his","work/ its","works/ his"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0732}/[H732]', 'inflected', 'heb', 'אָרַח', '["ʼârach"]', '["who/ was traveling"]', '["v"]', 'to travel go, wayfaring (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3411}/[H3409]', 'lemma', 'heb', 'יְרֵכָה', '["yᵉrêkâh"]', '["[the] innermost parts of","[the] remotest parts of"]', '["n-f"]', 'properly, the flank; but used only figuratively, the rear or recess border, coast, part, quarter, side.', 'feminine of 3409;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2543}/H9025/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["for/ donkeys/ our"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5288}/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["and/ for the/ servant"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4270}/H9021/[H2637]', 'inflected', 'heb', 'מַחְסוֹר', '["machçôwr"]', '["lack/ your"]', '["n-m"]', 'deficiency; hence, impoverishment lack, need, penury, poor, poverty, want.', 'or מַחְסֹר; from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1101B}/[H1098]', 'inflected', 'heb', 'בָּלַל', '["bâlal"]', '["and/ he fed"]', '["v"]', 'to overflow (specifically with oil.); by implication, to mix; to fodder anoint, confound, × fade, mingle, mix (self), give provender, temper.', 'a primitive root; (also denominatively from 1098) to fodder');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2543}/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["<to> the/ donkeys","for <the>/ a donkey"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1849}/[H1849]', 'lemma', 'heb', 'דָּפַק', '["dâphaq"]', '["beating violently","knocking"]', '["v"]', 'to knock; by analogy, to press severely beat, knock, overdrive.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3045}/H9033/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["and/ [those who] know/ him","so/ we may know/ him"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0251I}/H9020/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["O brother/ my","O brothers/ my","[is] brother/ my","brother/ my"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5039}/[H5036]', 'inflected', 'heb', 'נְבָלָה', '["nᵉbâlâh"]', '["<the>/ disgraceful folly","the/ disgraceful folly"]', '["n-f"]', 'foolishness, i.e. (morally) wickedness; concretely, a crime; by extension, punishment folly, vile, villany.', 'feminine of 5036;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6370>/H9023', 'inflected', 'heb', 'בפילגשו', '["be./Fi.lag.Sh/o","be./fi.lag.Sh/o"]', '["on/ concubine/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5953A}/[H5953]', 'inflected', 'heb', 'עָלַל', '["ʻâlal"]', '["and/ they abused","and/ they will deal wantonly"]', '["v"]', 'to effect thoroughly; specifically, to glean (also figuratively); by implication (in a bad sense) to overdo, i.e. maltreat, be saucy to, pain, impose (also literal) abuse, affect, × child, defile, do, glean, mock, practise, thoroughly, work (wonderfully).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3027G}/H9024/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ hands/ her"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5592B}/[H5605]', 'inflected', 'heb', 'סַף', '["çaph"]', '["the/ threshold","the/ thresholds"]', '["n-m"]', 'a vestibule (as a limit); also a dish (for holding blood or wine) bason, bowl, cup, door (post), gate, post, threshold.', 'from 5605, in its original sense of containing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947J}/H9034/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ he took/ her"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5408}/H9034/[H5408]', 'inflected', 'heb', 'נָתַח', '["nâthach"]', '["and/ I cut in pieces/ her","and/ he cut in pieces/ her"]', '["v"]', 'to dismember cut (in pieces), divide, hew in pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6106G}/H9024/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["to/ bones/ her"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5409}/[H5408]', 'lemma', 'heb', 'נֵתַח', '["nêthach"]', '["piece of meat","pieces"]', '["n-m"]', 'a fragment part, piece.', 'from 5408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971G}/H9034/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ I sent off/ her","and/ he sent out/ her"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/<H3117G>', 'inflected', 'heb', 'למיום', '["le./Mi./mei","le./mi./Mei","le./mi./Yom"]', '["<to>/ from/ [the] day","<to>/ from/ [the] days of","<to>/ from/ days of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5779}/[H5779]', 'lemma', 'heb', 'עוּץ', '["ʻûwts"]', '["plan","take counsel"]', '["v"]', 'to consult take advice ((counsel) together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1696G}\/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ speak"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/{H1835G}/[H1777]', 'inflected', 'heb', 'דָּן', '["Dân"]', '["<to>/ from/ Dan"]', '["n-pr-m"]', 'Dan, one of the sons of Jacob; also the tribe descended from him, and its territory; likewise a place in Palestine colonized by them Daniel', 'from 1777; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4709G}/[H4708]', 'inflected', 'heb', 'מִצְפָּה', '["Mitspâh"]', '["<the>/ Mizpah"]', '["n-pr-f"]', 'Mitspah, the name of two places in Palestine Mitspah. (This seems rather to be only an orthographic variation of 4708 when ''in pause''.)', 'feminine of 4708;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6438H}/[H6434]', 'lemma', 'heb', 'פִּנָּה', '["pinnâh"]', '["[the] corner","[the] corner of","[the] corners of","a corner","a corner of","corner"]', '["n-f"]', 'an angle; by implication, a pinnacle; figuratively, a chieftain bulwark, chief, corner, stay, tower.', 'feminine of 6434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0376H>', 'opaque', 'heb', 'אִישׁ', '["ʼîysh"]', '["[the] husband of","a husband","a man"]', '["n-m"]', 'a man as an individual or a male person; often used as an adjunct to a more definite term (and in such cases frequently not expressed in translation) also, another, any (man), a certain, champion, consent, each, every (one), fellow, (foot-, husband-) man, (good-, great, mighty) man, he, high (degree), him (that is), husband, man(-kind), none, one, people, person, steward, what (man) soever, whoso(-ever), worthy. Compare 802.', 'contracted for 582 (or perhaps rather from an unused root meaning to be extant);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1390H}/H9011/[H1389]', 'inflected', 'heb', 'גִּבְעָה', '["Gibʻâh"]', '["<the>/ Gibeah/ towards"]', '["n-pr-loc"]', 'Gibah; the name of three places in Palestine Gibeah, the hill.', 'the same as 1389;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6370>/H9020', 'inflected', 'heb', 'ופילגשי', '["u./fi.lag.Sh/i"]', '["and/ concubine/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6370>/H9020', 'opaque', 'heb', 'פִּילֶגֶשׁ', '["pîylegesh"]', '["concubine/ my"]', '["n-f"]', 'a concubine; also (masculine) a paramour concubine, paramour.', 'or פִּלֶגֶשׁ; of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6370>/H9020', 'inflected', 'heb', 'בפילגשי', '["be./fi.lag.Sh/i"]', '["on/ concubine/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5039}/[H5036]', 'inflected', 'heb', 'נְבָלָה', '["nᵉbâlâh"]', '["and/ disgraceful folly"]', '["n-f"]', 'foolishness, i.e. (morally) wickedness; concretely, a crime; by extension, punishment folly, vile, villany.', 'feminine of 5036;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6098}/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["and/ [the] counsel of","and/ [the] purpose of","and/ a counsel of","and/ counsel"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1390H}/[H1389]', 'inflected', 'heb', 'גִּבְעָה', '["Gibʻâh"]', '["to <the>/ Gibeah"]', '["n-pr-loc"]', 'Gibah; the name of three places in Palestine Gibeah, the hill.', 'the same as 1389;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7233}/[H7231]', 'inflected', 'heb', 'רְבָבָה', '["rᵉbâbâh"]', '["to the/ ten thousand"]', '["n-f"]', 'abundance (in number), i.e. (specifically) a myriad (whether definite or indefinite) many, million, × multiply, ten thousand.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0935G}/H9038/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["of/ coming/ their","to/ coming/ their"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1387H}/[H1375]', 'inflected', 'heb', 'גֶּבַע', '["Gebaʻ"]', '["to/ Geba"]', '["n-pr-loc"]', 'Geba, a place in Palestine Gaba, Geba, Gibeah.', 'from the same as 1375, a hillock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2270}\/[H2266]', 'inflected', 'heb', 'חָבֵר', '["châbêr"]', '["united"]', '["n-m"]', 'an associate companion, fellow, knit together.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4191}/H9038/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["so/ we may put to death/ them"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1197I}/[H1198]', 'inflected', 'heb', 'בָּעַר', '["bâʻar"]', '["and/ let us remove"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0014}//{H1121G}/[H14]', 'inflected', 'heb', 'אָבָה', '["ʼâbâh"]', '["they were willing// [the] descendants"]', '["v"]', 'to breathe after, i.e. (figuratively) to be acquiescent consent, rest content will, be willing.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7049A}/[H7049]', 'lemma', 'heb', 'קָלַע', '["qâlaʻ"]', '["[am] about to hurl forth","[was] slinging"]', '["v"]', 'to sling; also to carve (as if a circular motion, or into light forms) carve, sling (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8185}/[H8181]', 'inflected', 'heb', 'שַׂעֲרָה', '["saʻărâh"]', '["the/ single hair"]', '["n-f"]', 'hairiness hair.', 'feminine of 8181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1144G}/[H1121]', 'inflected', 'heb', 'בִּנְיָמִין', '["Binyâmîyn"]', '["from/ Benjamin","of/ Benjamin"]', '["n-pr-m"]', 'Binjamin, youngest son of Jacob; also the tribe descended from him, and its territory Benjamin.', 'from 1121 and 3225; son of (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1390H}\/[H1389]', 'inflected', 'heb', 'גִּבְעָה', '["Gibʻâh"]', '["<the>/ Gibeah"]', '["n-pr-loc"]', 'Gibah; the name of three places in Palestine Gibeah, the hill.', 'the same as 1389;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6186A}/[H6186]', 'inflected', 'heb', 'עָרַךְ', '["ʻârak"]', '["to/ arrange","to/ deploy"]', '["v"]', 'to set in a row, i.e. arrange, put in order (in a very wide variety of applications) put (set) (the battle, self) in array, compare, direct, equal, esteem, estimate, expert (in war), furnish, handle, join (battle), ordain, (lay, put, reckon up, set) (in) order, prepare, tax, value.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3254G}/[H3254]', 'inflected', 'heb', 'יָסַף', '["yâçaph"]', '["¿/ will I repeat"]', '["v"]', 'to add or augment (often adverbial, to continue to do a thing) add, × again, × any more, × cease, × come more, conceive again, continue, exceed, × further, × gather together, get more, give more-over, × henceforth, increase (more and more), join, × longer (bring, do, make, much, put), × (the, much, yet) more (and more), proceed (further), prolong, put, be (strong-) er, × yet, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5066G}/[H5066]', 'inflected', 'heb', 'נָגַשׁ', '["nâgash"]', '["to/ draw near"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6684}/[H6684]', 'inflected', 'heb', 'צוּם', '["tsûwm"]', '["and/ he fasted","and/ they fasted"]', '["v"]', 'to cover over (the mouth), i.e. to fast × at all, fast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8002}/[H7999]', 'inflected', 'heb', 'שֶׁלֶם', '["shelem"]', '["and/ [the] peace offering of","and/ peace offerings"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6372G}/[H6310]', 'inflected', 'heb', 'פִּינְחָס', '["Pîynᵉchâç"]', '["and/ Phinehas"]', '["n-pr-m"]', 'Pinechas, the name of three Israelites Phinehas.', 'apparently from 6310 and a variation of 5175; mouth of a serpent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439G}\/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["all around","round about"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5971K}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["some of/ the/ people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1390H}/H9011/[H1389]', 'inflected', 'heb', 'גִּבְעָה', '["Gibʻâh"]', '["Gibeah/ towards"]', '["n-pr-loc"]', 'Gibah; the name of three places in Palestine Gibeah, the hill.', 'the same as 1389;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9003/{H7223G}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["as/ at the/ former [time]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5423}/H9033/[H5423]', 'inflected', 'heb', 'נָתַק', '["nâthaq"]', '["and/ we will draw away/ him"]', '["v"]', 'to tear off break (off), burst, draw (away), lift up, pluck (away, off), pull (out), root out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4546}/[H5549]', 'inflected', 'heb', 'מְסִלָּה', '["mᵉçillâh"]', '["the/ highway","the/ highways"]', '["n-f"]', 'a thoroughfare (as turnpiked), literally or figuratively; specifically a viaduct, a staircase causeway, course, highway, path, terrace.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1193}/[H1167]', 'inflected', 'heb', 'בַּעַל תָּמָר', '["Baʻal Tâmâr"]', '["at/ Baal"]', '["n-pr-loc"]', 'Baal-Tamar, a place in Palestine Baal-tamar.', 'from 1167 and 8558; possessor of (the) palm-tree;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1193}/[H1167]', 'lemma', 'heb', 'בַּעַל תָּמָר', '["Baʻal Tâmâr"]', '["Tamar"]', '["n-pr-loc"]', 'Baal-Tamar, a place in Palestine Baal-tamar.', 'from 1167 and 8558; possessor of (the) palm-tree;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1518}/[H1518]', 'lemma', 'heb', 'גִּיחַ', '["gîyach"]', '["[was] bursting forth","it bursts forth"]', '["v"]', 'to gush forth (as water), generally to issue break forth, labor to bring forth, come forth, draw up, take out.', 'or (shortened) גֹּחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4629G}/[H6168]', 'inflected', 'heb', 'מַעֲרֶה', '["maʻăreh"]', '["from/ [the] open place of"]', '["n-m"]', 'a nude place, i.e. a common meadows.', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1387J}/[H1375]', 'lemma', 'heb', 'גֶּבַע', '["Gebaʻ"]', '["Geba"]', '["n-pr-loc"]', 'Geba, a place in Palestine Gaba, Geba, Gibeah.', 'from the same as 1375, a hillock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4421}/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["and/ the/ battle"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7451C}\/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<the>/ calamity"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1144G}/[H1121]', 'inflected', 'heb', 'בִּנְיָמִין', '["Binyâmîyn"]', '["among/ Benjamin"]', '["n-pr-m"]', 'Binjamin, youngest son of Jacob; also the tribe descended from him, and its territory Benjamin.', 'from 1121 and 3225; son of (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4150J}/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["and/ the/ appointed signal"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5927G}/H9038/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["to/ cause to go up/ they"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6227}/[H6225]', 'inflected', 'heb', 'עָשָׁן', '["ʻâshân"]', '["the/ smoke"]', '["n-m"]', 'smoke, literally or figuratively (vapor, dust, anger) smoke(-ing).', 'from 6225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4421}/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["like the/ battle"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4864}/[H5375]', 'inflected', 'heb', 'מַשְׂאֵת', '["masʼêth"]', '["and/ the/ rising"]', '["n-f"]', 'properly, (abstractly) a raising (as of the hands in prayer), or rising (of flame); figuratively, an utterance; concretely, a beacon (as raised); a present (as taken), mess, or tribute; figuratively, a reproach (as a burden) burden, collection, sign of fire, (great) flame, gift, lifting up, mess, oblation, reward.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0926}/[H926]', 'inflected', 'heb', 'בָּהַל', '["bâhal"]', '["and/ he hastened","and/ he was terrified","and/ they made haste","and/ they will be terrified","and/ you have become dismayed"]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1692}/H9033/[H1692]', 'inflected', 'heb', 'דָּבַק', '["dâbaq"]', '["it overtook/ him","they overtook/ him"]', '["v"]', 'properly, to impinge, i.e. cling or adhere; figuratively, to catch by pursuit abide fast, cleave (fast together), follow close (hard after), be joined (together), keep (fast), overtake, pursue hard, stick, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3803}/[H3803]', 'lemma', 'heb', 'כָּתַר', '["kâthar"]', '["[is] surrounding","they surround","they surrounded","they will surround","wait"]', '["v"]', 'to enclose; hence (in a friendly sense) to crown, (in a hostile one) to besiege; also to wait (as restraining oneself) beset round, compass about, be crowned, inclose round, suffer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7291}/H9033/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["he will pursue/ him","they pursued/ him"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4496G}/[H4495]', 'lemma', 'heb', 'מְנוּחָה', '["mᵉnûwchâh"]', '["rest"]', '["n-f"]', 'repose or (adverbially) peacefully; figuratively, consolation (specifically, matrimony); hence (concretely) an abode comfortable, ease, quiet, rest(-ing place), still.', 'or מְנֻחָה; feminine of 4495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1869}/H9033/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["they tread/ it","they trod down/ him"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7417C}/[H7416]', 'inflected', 'heb', 'רִמּוֹן', '["Rimmôwn"]', '["<the>/ Rimmon"]', '["n-pr-m n-pr-loc"]', 'Rimmon, the name of a Syrian deity, also of five places in Palestine Remmon, Rimmon.', 'or (shorter) (רִמֹּן; or רִמּוֹנוֹ; (1 Chronicles 6:62 (77)), the same as 7416; in Joshua 19:13: הַמְּתֹאָר is mistaken for part of a name; article with the passive participle of 8388; the (one) marked off, i.e. which pertains).');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5953B}/H9033/[H5953]', 'inflected', 'heb', 'עָלַל', '["ʻâlal"]', '["and/ they gleaned/ him"]', '["v"]', 'to effect thoroughly; specifically, to glean (also figuratively); by implication (in a bad sense) to overdo, i.e. maltreat, be saucy to, pain, impose (also literal) abuse, affect, × child, defile, do, glean, mock, practise, thoroughly, work (wonderfully).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1440}/[H1438]', 'lemma', 'heb', 'גִּדְעֹם', '["Gidʻôm"]', '["Gidom"]', '["n-pr-loc"]', 'Gidom, a place in Palestine Gidom.', 'from 1438; a cutting (i.e. desolation);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7417C}/[H7416]', 'lemma', 'heb', 'רִמּוֹן', '["Rimmôwn"]', '["Rimmon"]', '["n-pr-m n-pr-loc"]', 'Rimmon, the name of a Syrian deity, also of five places in Palestine Remmon, Rimmon.', 'or (shorter) (רִמֹּן; or רִמּוֹנוֹ; (1 Chronicles 6:62 (77)), the same as 7416; in Joshua 19:13: הַמְּתֹאָר is mistaken for part of a name; article with the passive participle of 8388; the (one) marked off, i.e. which pertains).');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4974}/[H8552]', 'lemma', 'heb', 'מְתֹם', '["mᵉthôm"]', '["[is] soundness","soundness"]', '["n-m"]', 'wholesomeness; also (adverb) completely men (by reading 4962), soundness.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4709G}/[H4708]', 'inflected', 'heb', 'מִצְפָּה', '["Mitspâh"]', '["[was] in <the>/ Mizpah","at <the>/ Mizpah"]', '["n-pr-f"]', 'Mitspah, the name of two places in Palestine Mitspah. (This seems rather to be only an orthographic variation of 4708 when ''in pause''.)', 'feminine of 4708;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6485K}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["to/ be missing"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8002}\/[H7999]', 'inflected', 'heb', 'שֶׁלֶם', '["shelem"]', '["and/ peace offerings"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1438}/[H1438]', 'lemma', 'heb', 'גָּדַע', '["gâdaʻ"]', '["I will cut off","I will cut through","[will be] cut down","he cut down","he cuts down","he has cut off","it has been cut off","it will be cut off","they have been cut down","you have been cut down"]', '["v"]', 'to fell a tree; generally, to destroy anything cut (asunder, in sunder, down, off), hew down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3498}/[H3498]', 'inflected', 'heb', 'יָתַר', '["yâthar"]', '["for <the>/ [those who] remain"]', '["v"]', 'to jut over or exceed; by implication, to excel; (intransitively) to remain or be left; causatively to leave, cause to abound, preserve excel, leave (a remnant), left behind, too much, make plenteous, preserve, (be, let) remain(-der, -ing, -nant), reserve, residue, rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1323G}/H9025/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["[are] some of/ daughters/ our","any of/ daughters/ our"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3003I}/[H3002]', 'inflected', 'heb', 'יָבֵשׁ', '["Yâbêsh"]', '["from/ Jabesh"]', '["n-pr-loc n-pr-m"]', 'Jobesh, the name of an Israelite and of a place in Palestine Jobesh (-Gilead).', 'the same as 3002 (also יָבֵישׁ; often with the addition of 1568, i.e. Jabesh of Gilad);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1568L}/[H1567]', 'lemma', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["Gilead"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3003I}/[H3002]', 'lemma', 'heb', 'יָבֵשׁ', '["Yâbêsh"]', '["Jabesh"]', '["n-pr-loc n-pr-m"]', 'Jobesh, the name of an Israelite and of a place in Palestine Jobesh (-Gilead).', 'the same as 3002 (also יָבֵישׁ; often with the addition of 1568, i.e. Jabesh of Gilad);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1121K}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["from/ [the] sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3003G}/[H3002]', 'lemma', 'heb', 'יָבֵשׁ', '["Yâbêsh"]', '["Jabesh"]', '["n-pr-loc n-pr-m"]', 'Jobesh, the name of an Israelite and of a place in Palestine Jobesh (-Gilead).', 'the same as 3002 (also יָבֵישׁ; often with the addition of 1568, i.e. Jabesh of Gilad);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7626H>', 'inflected', 'heb', 'בשבטי', '["be./shiv.Tei","va./She.vet"]', '["among/ [the] tribes of","in the/ tribe","in/ [the] tribes of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6413}/[H6412]', 'lemma', 'heb', 'פְּלֵיטָה', '["pᵉlêyṭâh"]', '["[the] escaped remnant","[the] escaped remnant of","[was] an escaped remnant","an escape","an escaped remnant","deliverance","escape"]', '["n-f"]', 'deliverance; concretely, an escaped portion deliverance, (that is) escape(-d), remnant.', 'or פְּלֵטָה; feminine of 6412;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1144G}\/[H1121]', 'inflected', 'heb', 'בִּנְיָמִין', '["Binyâmîyn"]', '["[belonged] to/ Benjamin","to/ Benjamin"]', '["n-pr-m"]', 'Binjamin, youngest son of Jacob; also the tribe descended from him, and its territory Benjamin.', 'from 1121 and 3225; son of (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4546}/[H5549]', 'inflected', 'heb', 'מְסִלָּה', '["mᵉçillâh"]', '["for the/ highway","of/ [the] highway","to the/ highway"]', '["n-f"]', 'a thoroughfare (as turnpiked), literally or figuratively; specifically a viaduct, a staircase causeway, course, highway, path, terrace.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H5045H>', 'inflected', 'heb', 'ומנגב', '["u./mi./Ne.gev"]', '["and/ from/ [the] south"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3829}/[H3828]', 'inflected', 'heb', 'לְבוֹנָה', '["Lᵉbôwnâh"]', '["to/ Lebonah"]', '["n-pr-loc"]', 'Lebonah, a place in Palestine Lebonah.', 'the same as 3828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2342J}/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["to/ dance"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4246}/[H4234]', 'inflected', 'heb', 'מְחֹלָה', '["mᵉchôlâh"]', '["in <the>/ dances","with <the>/ dances"]', '["n-f"]', 'a dance company, dances(-cing).', 'feminine of 4234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2414}/[H2414]', 'inflected', 'heb', 'חָטַף', '["châṭaph"]', '["and/ you will seize"]', '["v"]', 'to clutch; hence, to seize as a prisoner catch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7378}/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["for/ conducting a case","to/ conduct a case","to/ contest a lawsuit","to/ make a complaint"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2603A}/H9035/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["may he show favor to/ us","show favor for to/ us","show favor to/ us"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0816}\/[H816]', 'inflected', 'heb', 'אָשַׁם', '["ʼâsham"]', '["you will be guilty"]', '["v"]', 'to be guilty; by implication to be punished or perish × certainly, be(-come, made) desolate, destroy, × greatly, be(-come, found, hold) guilty, offend (acknowledge offence), trespass.', 'or אָשֵׁם; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375U}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ he took","and/ they carried off","and/ they took"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4557}/H9028/[H5608]', 'inflected', 'heb', 'מִסְפָּר', '["miçpâr"]', '["to/ number/ their"]', '["n-m"]', 'a number, definite (arithmetical) or indefinite (large, innumerable; small, a few); also (abstractly) narration abundance, account, × all, × few, (in-) finite, (certain) number(-ed), tale, telling, time.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2342J}/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["the/ dancers"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4940}/H9023/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["and/ to/ clan/ his"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0458}/[H410]', 'lemma', 'heb', 'אֱלִימֶלֶךְ', '["ʼĔlîymelek"]', '["Elimelech","[was] Elimelech"]', '["n-pr-m"]', 'Elimelek, an Israelite Elimelech.', 'from 410 and 4428; God of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5281}/[H5278]', 'lemma', 'heb', 'נׇעֳמִי', '["Noʻŏmîy"]', '["Naomi","[was] Naomi"]', '["n-pr-f"]', 'Noömi, an Israelitess Naomi.', 'from 5278; pleasant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4248}/[H2470]', 'lemma', 'heb', 'מַחְלוֹן', '["Machlôwn"]', '["Mahlon","[was] Mahlon"]', '["n-pr-m"]', 'Machlon, an Israelite Mahlon.', 'from 2470; sick;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3630}/[H3631]', 'inflected', 'heb', 'כִּלְיוֹן', '["Kilyôwn"]', '["and/ Kilion"]', '["n-pr-m"]', 'Kiljon, an Israelite Chilion.', 'a form of 3631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0673H}/[H672]', 'lemma', 'heb', 'אֶפְרָתִי', '["ʼEphrâthîy"]', '["Ephrathites","an Ephrathite"]', '["a"]', 'an Ephrathite or an Ephraimite Ephraimite, Ephrathite.', 'patrial from 672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4125}/[H4124]', 'lemma', 'heb', 'מוֹאָבִי', '["Môwʼâbîy"]', '["Moabite","Moabite [women]"]', '["a"]', 'a Moabite or Moabitess, i.e. a descendant from Moab (woman) of Moab, Moabite(-ish, -ss).', 'feminine מוֹאָבִיָּה; or מוֹאָבִיתxlit Môwâbîyth corrected to Môwʼâbîyth; patronymical from 4124;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6204}/[H6203]', 'lemma', 'heb', 'עׇרְפָּה', '["ʻOrpâh"]', '["Orpah","[was] Orpah"]', '["n-pr-f"]', 'Orpah, a Moabitess Orpah.', 'feminine of 6203; mane;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7327}/[H7468]', 'lemma', 'heb', 'רוּת', '["Rûwth"]', '["Ruth","[am] Ruth","[was] Ruth"]', '["n-pr-f"]', 'Ruth, a Moabitess Ruth.', 'probably for 7468; friend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H0376H>/H9024', 'inflected', 'heb', 'ומאישה', '["u./me./''i.Sha/h"]', '["and/ from/ husband/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3618H}/H9024/[H3634]', 'inflected', 'heb', 'כַּלָּה', '["kallâh"]', '["and/ daughters-in-law/ her"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3618H}/H9024/[H3634]', 'inflected', 'heb', 'כַּלָּה', '["kallâh"]', '["daughter-in-law/ her","daughters-in-law/ her"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5973A}/H9030/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["and/ with/ me"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4672}/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["and/ [was] finding","and/ find","and/ he will be found out","and/ let them find"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6963A>/H9029', 'opaque', 'heb', 'קוֹל', '["qôwl"]', '["voice/ their"]', '["n-m"]', 'a voice or sound aloud, bleating, crackling, cry ( out), fame, lightness, lowing, noise, hold peace, (pro-) claim, proclamation, sing, sound, spark, thunder(-ing), voice, yell.', 'or קֹל; from an unused root meaning to call aloud;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5971A}/H9022/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["to/ people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4578>/H9020', 'inflected', 'heb', 'במעי', '["be./me.''A/i"]', '["in/ inward parts/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8615B}/[H6960]', 'lemma', 'heb', 'תִּקְוָה', '["tiqvâh"]', '["[is the] hope of","[is] hope","[the] hope of","hope"]', '["n-f"]', 'literally a cord (as an attachment); figuratively, expectancy expectation(-ted), hope, live, thing that I long for.', 'from 6960; (compare 6961)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3860}/[H2005]', 'inflected', 'heb', 'לָהֵן', '["lâhên"]', '["¿/ therefore"]', '["conj"]', 'properly for if; hence, therefore for them (by mistake for prepositional suffix).', 'from the prepositional prefix meaning to or for and 2005;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7663B}/[H7663]', 'lemma', 'heb', 'שָׂבַר', '["sâbar"]', '["I wait","they had hoped","they hope","they wait","will you wait"]', '["v"]', 'to scrutinize; by implication (of watching) to expect (with hope and patience) hope, tarry, view, wait.', 'erroneously שָׁבַר; (Nehemiah 2:13,15), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5702}/[H5702]', 'lemma', 'heb', 'עָגַן', '["ʻâgan"]', '["will you shut yourselves off"]', '["v"]', 'to debar, i.e. from marriage stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2545}/H9024/[H2524]', 'inflected', 'heb', 'חֲמוֹת', '["chămôwth"]', '["<to>/ mother-in-law/ her","to/ mother-in-law/ her"]', '["n-f"]', 'a mother-in-law mother in law.', 'or (shortened) חֲמֹת; feminine of 2524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7327}/[H7468]', 'inflected', 'heb', 'רוּת', '["Rûwth"]', '["and/ Ruth"]', '["n-pr-f"]', 'Ruth, a Moabitess Ruth.', 'probably for 7468; friend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2994}/H9022/[H2992]', 'inflected', 'heb', 'יְבֵמֶת', '["Yᵉbêmeth"]', '["sister-in-law/ your"]', '["n-f"]', 'a sister-in-law brother''s wife, sister in law.', 'feminine participle of 2992;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430J}/H9024/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["gods/ her","gods/ its"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5800A}/H9032/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["to/ abandon/ you"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0310A}/H9032/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["from/ after/ you"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0834B}/[H834]', 'inflected', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["and/ <in>/ [that] which","and/ at/ where"]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0430G}/H9022/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ God/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0996G}/H9032/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["and/ between/ you"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9049/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["came/ they","coming/ they"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0935G}/H9049/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ came/ they"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1949}/[H2000]', 'inflected', 'heb', 'הוּם', '["hûwm"]', '["and/ it was excited","and/ it was stirred"]', '["v"]', 'to make an uproar, or agitate greatly destroy, move, make a noise, put, ring again.', 'a primitive root (compare 2000);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2063}/[H2088]', 'inflected', 'heb', 'זֹאת', '["zôʼth"]', '["¿/ [is] this","¿/ this"]', '["d"]', 'this (often used adverb) hereby (-in, -with), it, likewise, the one (other, same), she, so (much), such (deed), that, therefore, these, this (thing), thus.', 'irregular feminine of 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4755}/[H4751]', 'lemma', 'heb', 'מָרָא', '["Mârâʼ"]', '["Mara"]', '["n-pr-f"]', 'Mara, a symbolic name of Naomi Mara.', 'for 4751 feminine; bitter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7387}/[H7386]', 'inflected', 'heb', 'רֵיקָם', '["rêyqâm"]', '["and/ empty"]', '["adv"]', 'emptily; figuratively (objective) ineffectually, (subjective) undeservedly without cause, empty, in vain, void.', 'from 7386;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725G}/H9030/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["he has brought back/ me","he made turn back/ me","restore/ me","to send back/ me","will you turn back?/ me","you make go back/ me","you will bring/ me"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7706}/[H7703]', 'inflected', 'heb', 'שַׁדַּי', '["Shadday"]', '["and/ [the] Almighty"]', '["n-m"]', 'the Almighty Almighty.', 'from 7703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4125}/[H4124]', 'inflected', 'heb', 'מוֹאָבִי', '["Môwʼâbîy"]', '["the/ Moabite","the/ Moabite [woman]","the/ Moabite[s]"]', '["a"]', 'a Moabite or Moabitess, i.e. a descendant from Moab (woman) of Moab, Moabite(-ish, -ss).', 'feminine מוֹאָבִיָּה; or מוֹאָבִיתxlit Môwâbîyth corrected to Môwʼâbîyth; patronymical from 4124;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5281}/[H5278]', 'inflected', 'heb', 'נׇעֳמִי', '["Noʻŏmîy"]', '["and/ [belonged] to/ Naomi"]', '["n-pr-f"]', 'Noömi, an Israelitess Naomi.', 'from 5278; pleasant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4129}/[H3045]', 'lemma', 'heb', 'מוֹדַע', '["môwdaʻ"]', '["a relative"]', '["n-m"]', 'an acquaintance kinswoman.', 'or rather מֹדָע; from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1162G>', 'opaque', 'heb', 'בֹּעַז', '["Bôʻaz"]', '["Boaz","[is] Boaz","[was] Boaz"]', '["n-pr-m"]', 'Boaz, the ancestor of David; also the name of a pillar in front of the temple Boaz.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3950}/[H3950]', 'inflected', 'heb', 'לָקַט', '["lâqaṭ"]', '["so/ I may glean"]', '["v"]', 'properly, to pick up, i.e. (generally) to gather; specifically, to glean gather (up), glean.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7641B}/[H7640]', 'inflected', 'heb', 'שִׁבֹּל', '["shibbôl"]', '["among the/ ears of grain"]', '["n-f"]', 'a stream (as flowing); also an ear of grain (as growing out); by analogy, a branch branch, channel, ear (of corn), (water-)flood, Shibboleth. Compare 5451.', 'or (feminine) שִׁבֹּלֶת; from the same as 7640;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7114B}/[H7114]', 'inflected', 'heb', 'קָצַר', '["qâtsar"]', '["the/ harvesters","the/ reaper"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4745}/H9024/[H7136]', 'inflected', 'heb', 'מִקְרֶה', '["miqreh"]', '["chance/ her"]', '["n-m"]', 'something met with, i.e. an accident or fortune something befallen, befalleth, chance, event, hap(-peneth).', 'from 7136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1162G>', 'inflected', 'heb', 'לבעז', '["le./Vo.''az"]', '["of/ Boaz","to/ Boaz"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6016A}/[H6014]', 'inflected', 'heb', 'עֹמֶר', '["ʻômer"]', '["among the/ sheaves"]', '["n-m"]', 'properly, a heap, i.e. a sheaf; also an omer, as a dry measure omer, sheaf.', 'from 6014;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3427}/H9044/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["sitting/ she"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5291}/H9020/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["female servants/ my"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869A}/H9022/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7114B}/H9013/[H7114]', 'inflected', 'heb', 'קָצַר', '["qâtsar"]', '["they are harvesting/ !"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5060}/H9032/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["to touch/ you"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7579}/H9013/[H7579]', 'inflected', 'heb', 'שָׁאַב', '["shâʼab"]', '["they will draw/ !"]', '["v"]', 'to bale up water (woman to) draw(-er, water).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5234A}/H9030/[H5234]', 'inflected', 'heb', 'נָכַר', '["nâkar"]', '["to/ pay regard to/ me"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2545}/H9022/[H2524]', 'inflected', 'heb', 'חֲמוֹת', '["chămôwth"]', '["mother-in-law/ your"]', '["n-f"]', 'a mother-in-law mother in law.', 'or (shortened) חֲמֹת; feminine of 2524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0517}/H9022/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["and/ mother/ your"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4138}/H9022/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["kindred/ your"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6467}/H9022/[H6466]', 'inflected', 'heb', 'פֹּעַל', '["pôʻal"]', '["deed[s]/ your"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4909}/H9022/[H7936]', 'inflected', 'heb', 'מַשְׂכֹּרֶת', '["maskôreth"]', '["wage[s]/ your"]', '["n-f"]', 'wages or a reward reward, wages.', 'from 7936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2620}/[H982]', 'inflected', 'heb', 'חָסָה', '["châçâh"]', '["for <the>/ [those who] take refuge","to/ take refuge"]', '["v"]', 'to flee for protection; figuratively, to confide in have hope, make refuge, (put) trust.', 'a primitive root; (compare 982)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5162G}/H9030/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["it will comfort/ me","may you comfort/ me","they comfort/ me","will you comfort/ me","you have comforted/ me"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8198>/H9021', 'opaque', 'heb', 'שִׁפְחָה', '["shiphchâh"]', '["maidservant/ your","maidservants/ your"]', '["n-f"]', 'a female slave (as a member of the household) (bond-, hand-) maid(-en, -servant), wench, bondwoman, womanservant.', 'feminine from an unused root meaning to spread out (as a family; see 4940);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6595A}/H9022/[H6626]', 'inflected', 'heb', 'פַּת', '["path"]', '["portion/ your"]', '["n-f"]', 'a bit meat, morsel, piece.', 'from 6626;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2558}/[H2556]', 'inflected', 'heb', 'חֹמֶץ', '["chômets"]', '["in the/ vinegar"]', '["n-m"]', 'vinegar vinegar.', 'from 2556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6642}/[H6642]', 'inflected', 'heb', 'צָבַט', '["tsâbaṭ"]', '["and/ he held out"]', '["v"]', 'to grasp, i.e. hand out reach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7039}/[H7033]', 'lemma', 'heb', 'קָלִי', '["qâlîy"]', '["roasted grain"]', '["n-m"]', 'roasted ears of grain parched corn.', 'or קָלִיא; from 7033;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3637}/H9034/[H3637]', 'inflected', 'heb', 'כָּלַם', '["kâlam"]', '["you must humiliate/ her"]', '["v"]', 'properly, to wound; but only figuratively, to taunt or insult be (make) ashamed, blush, be confounded, be put to confusion, hurt, reproach, (do, put to) shame.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7997A}/[H7997]', 'lemma', 'heb', 'שָׁלַל', '["shâlal"]', '["indeed <pull out>","you will pull out"]', '["v"]', 'to drop or strip; by implication, to plunder let fall, make self a prey, × of purpose, (make a, (take)) spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6653>', 'inflected', 'heb', 'הצבתים', '["ha./tze.va.Tim"]', '["the/ bundles of grain"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1605}/[H1605]', 'lemma', 'heb', 'גָּעַר', '["gâʻar"]', '["[am] about to rebuke","have you rebuked","may he rebuke","rebuke","you have rebuked","you must rebuke","you rebuke"]', '["v"]', 'to chide corrupt, rebuke, reprove.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2251}/[H2251]', 'inflected', 'heb', 'חָבַט', '["châbaṭ"]', '["and/ she beat out"]', '["v"]', 'to knock out or off beat (off, out), thresh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0374}/[H374]', 'inflected', 'heb', 'אֵיפָה', '["ʼêyphâh"]', '["about/ an ephah"]', '["n-f"]', 'an ephah or measure for grain; hence, a measure in general ephah, (divers) measure(-s).', 'or (shortened) אֵפָה ; of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2545}/H9024/[H2524]', 'inflected', 'heb', 'חֲמוֹת', '["chămôwth"]', '["mother-in-law/ her"]', '["n-f"]', 'a mother-in-law mother in law.', 'or (shortened) חֲמֹת; feminine of 2524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7648}/H9024/[H7646]', 'inflected', 'heb', 'שֹׂבַע', '["sôbaʻ"]', '["from/ abundance/ her"]', '["n-m"]', 'satisfaction (of food or [figuratively] joy) fill, full(-ness), satisfying, be satisfied.', 'from 7646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5234A}/H9032/[H5234]', 'inflected', 'heb', 'נָכַר', '["nâkar"]', '["[the one who] paid regard to/ you"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3618H}/H9024/[H3634]', 'inflected', 'heb', 'כַּלָּה', '["kallâh"]', '["to/ daughter-in-law/ her"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1350A}/H9025/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["[is] one of/ kinsman-redeemer[s]/ our"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5291}/H9023/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["female servants/ his"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5291}/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["with/ [the] female servants of"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2406>', 'inflected', 'heb', 'החטים', '["ha./chi.Tim"]', '["the/ wheat<s>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4130}/H9025/[H3045]', 'inflected', 'heb', 'מוֹדַעַת', '["môwdaʻath"]', '["relative/ our"]', '["n-f"]', 'acquaintance kindred.', 'from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5480}/[H5480]', 'inflected', 'heb', 'סוּךְ', '["çûwk"]', '["and/ he anointed himself","and/ you will anoint yourself"]', '["v"]', 'properly, to smear over (with oil), i.e. anoint anoint (self), × at all.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8071}/H9022/[H5566]', 'inflected', 'heb', 'שִׂמְלָה', '["simlâh"]', '["garments/ your"]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9032/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["[am] on/ you","[is] on/ you","at/ you","on/ you","on/ yourself","over/ you","to/ you","towards/ you"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615G}/H9043/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["finished/ he","finishes/ he","was complete/ it"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8354}/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["and/ to/ drink"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7901G}/H9043/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["when/ lies down/ he"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4772}/H9023/[H7272]', 'inflected', 'heb', 'מַרְגְלָה', '["margᵉlâh"]', '["feet/ his"]', '["n-f"]', '(plural for collective) a footpiece, i.e. (adverbially) at the foot, or (direct.) the foot itself feet. Compare 4763.', 'denominative from 7272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0559}/ /{H0413}/H9030/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["he said/ /to/ me","you are saying/ /to/ me"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7901G}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["to/ lie down"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6194}/[H6192]', 'inflected', 'heb', 'עָרֵם', '["ʻârêm"]', '["<the>/ heaps of grain","the/ heap","the/ heaps"]', '["n-f"]', 'a heap; specifically, a sheaf heap (of corn), sheaf.', '(Jeremiah 50:26) or (feminine) עֲרֵמָה; from 6192;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3909}/[H3814]', 'inflected', 'heb', 'לָט', '["lâṭ"]', '["in <the>/ secrecy"]', '["n-m"]', 'properly, covered, i.e. secret; by implication, incantation; also secrecy or (adverb) covertly enchantment, privily, secretly, softly.', 'a form of 3814 or else participle from 3874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3671}/H9021/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["skirt/ your","wings/ your"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6223}/[H6238]', 'lemma', 'heb', 'עָשִׁיר', '["ʻâshîyr"]', '["<of> [the] rich","[is] rich","[the] rich","[was] rich","a rich [person]","rich","rich [ones] of"]', '["n-m"]', 'rich, whether literal or figurative (noble) rich (man).', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8179H}/[H8176]', 'lemma', 'heb', 'שַׁעַר', '["shaʻar"]', '["[the] gate of"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428I}/[H2342]', 'lemma', 'heb', 'חַיִל', '["chayil"]', '["ability","wealth","worth"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0551}/[H544]', 'lemma', 'heb', 'אׇמְנָם', '["ʼomnâm"]', '["truly"]', '["adv"]', 'verily indeed, no doubt, surely, (it is, of a) true(-ly, -th).', 'adverb from 544;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1350A}/H9032/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["he will redeem/ you"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1350A}/H9032/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["to/ redeem/ you"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1350A}/H9032/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["and/ I will redeem/ you"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4304}/[H2946]', 'inflected', 'heb', 'מִטְפַּחַת', '["miṭpachath"]', '["the/ shawl"]', '["n-f"]', 'a wide cloak (for a woman) vail, wimple.', 'from 2946;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1162G>', 'inflected', 'heb', 'ובעז', '["u./Vo.''az"]', '["and/ Boaz"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6423}/[H6395]', 'lemma', 'heb', 'פְּלֹנִי', '["pᵉlônîy"]', '["a certain one"]', '["pron"]', 'such a one, i.e. a specified person such.', 'from 6395;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0492}/[H489]', 'lemma', 'heb', 'אַלְמֹנִי', '["ʼalmônîy"]', '["a certain one"]', '["a"]', 'some one (i.e. so and so, without giving the name of the person or place) one, and such.', 'from 489 in the sense of concealment;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1350A}/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["[is] to/ redeem","to the/ kinsman redeemer","to/ redeem [it]"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251H}/H9025/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["[belonged] to/ brother/ our"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0458}/[H410]', 'inflected', 'heb', 'אֱלִימֶלֶךְ', '["ʼĔlîymelek"]', '["[belonged] to/ Elimelech","to/ Elimelech"]', '["n-pr-m"]', 'Elimelek, an Israelite Elimelech.', 'from 410 and 4428; God of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0241I}/H9021/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["ear/ your"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5048}/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["and/ before"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2108}/H9031/[H2107]', 'inflected', 'heb', 'זוּלָה', '["zûwlâh"]', '["besides/ you","except/ you"]', '["n-f"]', 'probably scattering, i.e. removal; used adverbially, except beside, but, only, save.', 'from 2107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7069}/H9041/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["acquiring/ you"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5159}/H9020/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["[is] inheritance/ my","inheritance/ my","own inheritance/ my"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1353}/H9020/[H1350]', 'inflected', 'heb', 'גְּאֻלָּה', '["gᵉʼullâh"]', '["right of redemption/ my"]', '["n-f"]', 'redemption (including the right and the object); by implication, relationship kindred, redeem, redemption, right.', 'feminine passive participle of 1350;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1353}/[H1350]', 'inflected', 'heb', 'גְּאֻלָּה', '["gᵉʼullâh"]', '["<the>/ redemption","the/ redemption"]', '["n-f"]', 'redemption (including the right and the object); by implication, relationship kindred, redeem, redemption, right.', 'feminine passive participle of 1350;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8545}/[H4171]', 'inflected', 'heb', 'תְּמוּרָה', '["tᵉmûwrâh"]', '["the/ exchange"]', '["n-f"]', 'barter, compensation (ex-) change(-ing), recompense, restitution.', 'from 4171;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8584}/[H5749]', 'inflected', 'heb', 'תְּעוּדָה', '["tᵉʻûwdâh"]', '["[was] the/ attestation"]', '["n-f"]', 'attestation, i.e. a precept, usage testimony.', 'from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8025}/[H8025]', 'inflected', 'heb', 'שָׁלַף', '["shâlaph"]', '["and/ he took off"]', '["v"]', 'to pull out, up or off draw (off), grow up, pluck off.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3630}/[H3631]', 'inflected', 'heb', 'כִּלְיוֹן', '["Kilyôwn"]', '["[belonged] to/ Kilion"]', '["n-pr-m"]', 'Kiljon, an Israelite Chilion.', 'a form of 3631;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4248}/[H2470]', 'inflected', 'heb', 'מַחְלוֹן', '["Machlôwn"]', '["and/ Mahlon"]', '["n-pr-m"]', 'Machlon, an Israelite Mahlon.', 'from 2470; sick;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8179G}/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["and/ from/ [the] gate of"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2205G}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["and/ the/ elders"]', '["a"]', 'old aged, ancient (man), elder(-est), old (man, men and...women), senator.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7354}/[H7353]', 'inflected', 'heb', 'רָחֵל', '["Râchêl"]', '["like/ Rachel"]', '["n-pr-f"]', 'Rachel, a wife of Jacob Rachel.', 'the same as 7353;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3812}/[H3811]', 'inflected', 'heb', 'לֵאָה', '["Lêʼâh"]', '["and/ like/ Leah"]', '["n-pr-f"]', 'Leah, a wife of Jacob Leah.', 'from 3811; weary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0672H}/[H6509]', 'inflected', 'heb', 'אֶפְרָת', '["ʼEphrâth"]', '["in/ Ephrathah"]', '["n-pr"]', 'Ephrath, another name for Bethlehem; once (Psalm 132:6) perhaps for Ephraim; also of an Israelitish woman; Ephrath, Ephratah.', 'or אֶפְרָתָה; from 6509; fruitfulness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1004M}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["like/ [the] house of","like/ [the] household of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2032}/[H2029]', 'lemma', 'heb', 'הֵרוֹן', '["hêrôwn"]', '["conception"]', '["n-m"]', 'pregnancy conception.', 'or הֵרָיוֹן; from 2029;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3557}/[H3557]', 'inflected', 'heb', 'כּוּל', '["kûwl"]', '["and/ to/ sustain"]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7872}/H9022/[H7869]', 'inflected', 'heb', 'שֵׂיבָה', '["sêybâh"]', '["old age/ your"]', '["n-f"]', 'old age (be) gray (grey hoar,-y) hairs (head,-ed), old age.', 'feminine of 7869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3618H}/H9022/[H3634]', 'inflected', 'heb', 'כַּלָּה', '["kallâh"]', '["daughter-in-law/ your"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7651}/[H7650]', 'inflected', 'heb', 'שֶׁבַע', '["shebaʻ"]', '["more than/ seven","more than/ seven [people]"]', '["n"]', 'seven (as the sacred full one); also (adverbially) seven times; by implication, a week; by extension, an indefinite number ( by) seven(-fold),-s, (-teen, -teenth), -th, times). Compare 7658.', 'or (masculine) (שִׁבְעָה); from 7650; a primitive cardinal number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7896H}/H9033/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["and/ she placed/ him"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2436G>/H9024', 'inflected', 'heb', 'בחיקה', '["be./chei.Ka/h","ve./chei.Ka/h"]', '["in/ bosom/ her","on/ bosom/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0539}/[H541]', 'inflected', 'heb', 'אָמַן', '["ʼâman"]', '["<into>/ a nurse","of/ trusted [ones]"]', '["v"]', 'properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right.', 'a primitive root; (Isaiah 30:21; interchangeable with 541, to go to the right hand)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7934}/[H7931]', 'inflected', 'heb', 'שָׁכֵן', '["shâkên"]', '["the/ [female] neighbors"]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5281}/[H5278]', 'inflected', 'heb', 'נׇעֳמִי', '["Noʻŏmîy"]', '["to/ Naomi"]', '["n-pr-f"]', 'Noömi, an Israelitess Naomi.', 'from 5278; pleasant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5744G}/[H5647]', 'lemma', 'heb', 'עוֹבֵד', '["ʻÔwbêd"]', '["Obed"]', '["n-pr-m"]', 'Obed, the name of five Israelites Obed.', 'active participle of 5647; serving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3448}/[H3426]', 'lemma', 'heb', 'יִשַׁי', '["Yishay"]', '["Jesse","[was] Jesse"]', '["n-pr-m"]', 'Jishai, David''s father Jesse.', 'by Aramaic אִישַׁי; from the same as 3426; extant;');
