INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2696H}/[H2691]', 'inflected', 'heb', 'חֶצְרוֹן', '["Chetsrôwn"]', '["and/ Hezron"]', '["n-pr-m n-pr-loc"]', 'Chetsron, the name of a place in Palestine; also of two Israelites Hezron.', 'from 2691; court-yard;');
