INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7410G}/[H7311]', 'inflected', 'heb', 'רָם', '["Râm"]', '["and/ Ram"]', '["n-pr-m"]', 'Ram, the name of an Arabian and of an Israelite Ram. See also 1027.', 'active participle of 7311; high;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5992G}/[H5971]', 'inflected', 'heb', 'עַמִּינָדָב', '["ʻAmmîynâdâb"]', '["and/ Amminadab"]', '["n-pr-m"]', 'Amminadab, the name of four Israelites Amminadab.', 'from 5971 and 5068; people of liberality;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5177}/[H5172]', 'inflected', 'heb', 'נַחְשׁוֹן', '["Nachshôwn"]', '["and/ Nahshon"]', '["n-pr-m"]', 'Nachshon, an Israelite Naashon, Nahshon.', 'from 5172; enchanter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8009}/[H8008]', 'lemma', 'heb', 'שַׂלְמָה', '["Salmâh"]', '["Salmah"]', '["n-pr-m"]', 'Salmah, an Israelite Salmon. Compare 8012.', 'the same as 8008; clothing;');
