INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3448}/[H3426]', 'inflected', 'heb', 'יִשַׁי', '["Yishay"]', '["and/ Jesse"]', '["n-pr-m"]', 'Jishai, David''s father Jesse.', 'by Aramaic אִישַׁי; from the same as 3426; extant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1732}/[H1730]', 'lemma', 'heb', 'דָּוִד', '["Dâvid"]', '["David","O David","[is] David"]', '["n-pr-m"]', 'David, the youngest son of Jesse David.', 'rarely (fully); דָּוִיד; from the same as 1730; loving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7436}/[H7413]', 'inflected', 'heb', 'רָמָתַיִם צוֹפִים', '["Râmâthayim Tsôwphîym"]', '["<the>/ Ramathaim"]', '["n-pr-loc"]', 'Ramathajim-Tsophim, a place in Palestine Ramathaimzophim.', 'from the dual of 7413 and the plural of the active participle of 6822; double height of watchers;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7436}/[H7413]', 'lemma', 'heb', 'רָמָתַיִם צוֹפִים', '["Râmâthayim Tsôwphîym"]', '["Zophim"]', '["n-pr-loc"]', 'Ramathajim-Tsophim, a place in Palestine Ramathaimzophim.', 'from the dual of 7413 and the plural of the active participle of 6822; double height of watchers;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0511H}/[H410]', 'lemma', 'heb', 'אֶלְקָנָה', '["ʼElqânâh"]', '["Elkanah","[was] Elkanah"]', '["n-pr-m"]', 'Elkanah, the name of several Israelites Elkanah.', 'from 410 and 7069; God has obtained;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3395G}/[H7355]', 'lemma', 'heb', 'יְרֹחָם', '["Yᵉrôchâm"]', '["Jeroham"]', '["n-pr-m"]', 'Jerocham, the name of seven or eight Israelites Jeroham.', 'from 7355; compassionate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0453G}/[H410]', 'lemma', 'heb', 'אֱלִיהוּ', '["ʼĔlîyhûw"]', '["Elihu"]', '["n-pr-m"]', 'Elihu, the name of one of Job''s friends, and of three Israelites Elihu.', 'or (fully) אֱלִיהוּא; from 410 and 1931; God of him;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8459>', 'opaque', 'heb', 'תֹּחוּ', '["Tôchûw"]', '["Tohu"]', '["n-pr-m"]', 'Tochu, an Israelite Tohu.', 'from an unused root meaning to depress; abasement;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6689G}/[H6688]', 'lemma', 'heb', 'צוּף', '["Tsûwph"]', '["Zophai","Zuph"]', '["n-pr-m n-pr-loc"]', 'Tsuph or Tsophai or Tsiph, the name of an Israelite and of a place in Palestine Zophai, Zuph.', 'or צוֹפַי; or צִיף; from 6688; honey-comb;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0673G}/[H672]', 'lemma', 'heb', 'אֶפְרָתִי', '["ʼEphrâthîy"]', '["an Ephrathite"]', '["a"]', 'an Ephrathite or an Ephraimite Ephraimite, Ephrathite.', 'patrial from 672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2584}/[H2603]', 'lemma', 'heb', 'חַנָּה', '["Channâh"]', '["Hannah","O Hannah","[was] Hannah"]', '["n-pr-f"]', 'Channah, an Israelitess Hannah.', 'from 2603; favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6444}/[H6443]', 'lemma', 'heb', 'פְּנִנָּה', '["Pᵉninnâh"]', '["[was] Peninnah"]', '["n-pr-f"]', 'Peninnah, an Israelitess Peninnah.', 'probably feminine from 6443 contr.;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6444}/[H6443]', 'inflected', 'heb', 'פְּנִנָּה', '["Pᵉninnâh"]', '["to/ Peninnah"]', '["n-pr-f"]', 'Peninnah, an Israelitess Peninnah.', 'probably feminine from 6443 contr.;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3206}/[H3205]', 'lemma', 'heb', 'יֶלֶד', '["yeled"]', '["a child","a child of","a youth","boys","children","children of","youths"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2584}/[H2603]', 'inflected', 'heb', 'חַנָּה', '["Channâh"]', '["and/ [belonged] to/ Hannah","and/ to/ Hannah"]', '["n-pr-f"]', 'Channah, an Israelitess Hannah.', 'from 2603; favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2076}/[H2076]', 'inflected', 'heb', 'זָבַח', '["zâbach"]', '["and/ to the/ [one who] sacrifices","and/ to/ sacrifice"]', '["v"]', 'to slaughter an animal (usually in sacrifice) kill, offer, (do) sacrifice, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635B}/[H6633]', 'lemma', 'heb', 'צָבָא', '["tsâbâʼ"]', '["armies","hosts","of hosts"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5941}/[H5927]', 'lemma', 'heb', 'עֵלִי', '["ʻÊlîy"]', '["Eli"]', '["n-pr-m"]', 'Eli, an Israelite highpriest Eli.', 'from 5927; lofty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2652}/[H2651]', 'lemma', 'heb', 'חׇפְנִי', '["Chophnîy"]', '["Hophni"]', '["n-pr-m"]', 'Chophni, an Israelite Hophni.', 'from 2651; perhaps pugilist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6372H}/[H6310]', 'inflected', 'heb', 'פִּינְחָס', '["Pîynᵉchâç"]', '["and/ Phinehas"]', '["n-pr-m"]', 'Pinechas, the name of three Israelites Phinehas.', 'apparently from 6310 and a variation of 5175; mouth of a serpent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4490}/[H4487]', 'lemma', 'heb', 'מָנָה', '["mânâh"]', '["[is] [the] portion of","a portion","portions"]', '["n-f"]', 'properly, something weighed out, i.e. (generally) a division; specifically (of food) a ration; also a lot such things as belonged, part, portion.', 'from 4487;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3707}/H9034/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["and/ she provoked/ her"]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6869C}/H9024/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["rival/ her"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7481}/H9034/[H7481]', 'inflected', 'heb', 'רָעַם', '["râʻam"]', '["to disconcert/ her"]', '["v"]', 'to tumble, i.e. be violently agitated; specifically, to crash (of thunder); figuratively, to irritate (with anger) make to fret, roar, thunder, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927G}/H9044/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["went up/ she"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004Q}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[are] in/ [the] house of","[is] in/ [the] house of","[was] in/ [the] house of","[were] in/ [the] house of","in the/ house","in/ [the] house of","in/ [the] houses of","in/ a house","on/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3707}/H9034/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["she provoked/ her"]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3415}/[H3415]', 'lemma', 'heb', 'יָרַע', '["yâraʻ"]', '["is sad","it is trembling"]', '["v"]', 'properly, to be broken up (with any violent action) i.e. (figuratively) to fear be grevious (only Isaiah 15:4; the rest belong to 7489).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3824}/H9022/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["heart/ your"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6235}/[H6237]', 'inflected', 'heb', 'עֶשֶׂר', '["ʻeser"]', '["more than/ ten"]', '["n"]', 'ten (as an accumulation to the extent of the digits) ten, (fif-, seven-) teen.', 'masculine of term עֲשָׂרָה; from 6237;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5941}/[H5927]', 'inflected', 'heb', 'עֵלִי', '["ʻÊlîy"]', '["and/ Eli"]', '["n-pr-m"]', 'Eli, an Israelite highpriest Eli.', 'from 5927; lofty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3678I}/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["the/ seat"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1964G}/[H3201]', 'lemma', 'heb', 'הֵיכָל', '["hêykâl"]', '["[are] [the] temple of","[the] temple","[the] temple of","a temple"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6040}/[H6031]', 'inflected', 'heb', 'עֳנִי', '["ʻŏnîy"]', '["on/ [the] affliction of"]', '["n-m"]', 'depression, i.e. misery afflicted(-ion), trouble.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6419}/[H6419]', 'inflected', 'heb', 'פָּלַל', '["pâlal"]', '["to/ pray"]', '["v"]', 'to judge (officially or mentally); by extension, to intercede, pray intreat, judge(-ment), (make) pray(-er, -ing), make supplication.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2584}/[H2603]', 'inflected', 'heb', 'חַנָּה', '["Channâh"]', '["and/ Hannah"]', '["n-pr-f"]', 'Channah, an Israelitess Hannah.', 'from 2603; favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6963A>/H9024', 'inflected', 'heb', 'וקולה', '["ve./ko.La/h"]', '["and/ voice/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7910}/[H7937]', 'inflected', 'heb', 'שִׁכּוֹר', '["shikkôwr"]', '["to/ a drunken [woman]"]', '["a"]', 'intoxicated, as a state or a habit drunk(-ard, -en, -en man).', 'or שִׁכֹּר; from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7937}/H9013/[H7937]', 'inflected', 'heb', 'שָׁכַר', '["shâkar"]', '["they will become drunk/ !","will you be drunk/ !"]', '["v"]', 'to become tipsy; in a qualified sense, to satiate with a stimulating drink or (figuratively) influence (be filled with) drink (abundantly), (be, make) drunk(-en), be merry. (Superlative of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3196>/H9022', 'opaque', 'heb', 'יַיִן', '["yayin"]', '["wine/ your"]', '["n-m"]', 'wine (as fermented); by implication, intoxication banqueting, wine, wine(-bibber).', 'from an unused root meaning to effervesce;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5921A}/H9032/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["from/ on <the>/ you","from/ with <the>/ you"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440L}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7879}/H9020/[H7878]', 'inflected', 'heb', 'שִׂיחַ', '["sîyach"]', '["[is] complaint/ my","complaint/ my","meditation/ my"]', '["n-m"]', 'a contemplation; by implication, an utterance babbling, communication, complaint, meditation, prayer, talk.', 'from 7878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3708A}/H9020/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["and/ provocation/ my"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7596}/H9022/[H7592]', 'inflected', 'heb', 'שְׁאֵלָה', '["shᵉʼêlâh"]', '["[is] petition/ your","petition/ your"]', '["n-f"]', 'a petition; by implication, a loan loan, petition, request.', 'or שֵׁלָה; (1 Samuel 1:17), from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1870L}/H9024/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["to/ way/ her"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440H}/H9024/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ face/ her"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9028/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["home/ their","house/ their","houses/ their"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7414J}/H9011/[H7413]', 'inflected', 'heb', 'רָמָה', '["Râmâh"]', '["<the>/ Ramah/ towards","[was] <the>/ Ramah/ towards"]', '["n-pr-loc"]', 'Ramah, the name of four places in Palestine Ramah.', 'the same as 7413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2142}/H9034/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["and/ he remembered/ her"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8622}/[H5362]', 'inflected', 'heb', 'תְּקוּפָה', '["tᵉqûwphâh"]', '["to/ [the] circuit of"]', '["n-f"]', 'a revolution, i.e. (of the sun) course, (of time) lapse circuit, come about, end.', 'or תְּקֻפָה; from 5362;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8050G}/[H8085]', 'lemma', 'heb', 'שְׁמוּאֵל', '["Shᵉmûwʼêl"]', '["O Samuel","Samuel","[are] Samuel","[was] Samuel"]', '["n-pr-m"]', 'Shemuël, the name of three Israelites Samuel, Shemuel.', 'from the passive participle of 8085 and 410; heard of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3117I>', 'inflected', 'heb', 'הימים', '["hai./ya.Mim"]', '["the/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1580}/H9042/[H1580]', 'inflected', 'heb', 'גָּמַל', '["gâmal"]', '["wean/ you"]', '["v"]', 'to treat a person (well or ill), i.e. benefit or requite; by implication (of toil), to ripen, i.e. (specifically) to wean bestow on, deal bountifully, do (good), recompense, requite, reward, ripen, serve, mean, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3243H}/[H3243]', 'inflected', 'heb', 'יָנַק', '["yânaq"]', '["and/ she suckled"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1580}/H9044/[H1580]', 'inflected', 'heb', 'גָּמַל', '["gâmal"]', '["had weaned/ she"]', '["v"]', 'to treat a person (well or ill), i.e. benefit or requite; by implication (of toil), to ripen, i.e. (specifically) to wean bestow on, deal bountifully, do (good), recompense, requite, reward, ripen, serve, mean, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5927G}/H9033/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ he brought up/ him","and/ he took up/ him","and/ she brought up/ him"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1580}/H9033/[H1580]', 'inflected', 'heb', 'גָּמַל', '["gâmal"]', '["she feeds/ him","she had weaned/ him"]', '["v"]', 'to treat a person (well or ill), i.e. benefit or requite; by implication (of toil), to ripen, i.e. (specifically) to wean bestow on, deal bountifully, do (good), recompense, requite, reward, ripen, serve, mean, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5035A}/[H5034]', 'inflected', 'heb', 'נֶבֶל', '["nebel"]', '["and/ [the] waterskins of","and/ a skin of"]', '["n-m"]', 'a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol.', 'or נֵבֶל; from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7596}/H9020/[H7592]', 'inflected', 'heb', 'שְׁאֵלָה', '["shᵉʼêlâh"]', '["petition/ my"]', '["n-f"]', 'a petition; by implication, a loan loan, petition, request.', 'or שֵׁלָה; (1 Samuel 1:17), from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5970}/[H5970]', 'lemma', 'heb', 'עָלַץ', '["ʻâlats"]', '["it rejoices","let it exult","may they exult","they exult"]', '["v"]', 'to jump for joy, i.e. exult be joyful, rejoice, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7161A}/H9020/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["horn/ my"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3444}/H9021/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["at/ victory/ your","by/ victory/ your","in/ deliverance/ your","with/ salvation/ your"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1115}/H9031/[H1086]', 'inflected', 'heb', 'בִּלְתִּי', '["biltîy"]', '["[is] except/ you"]', '["np"]', 'properly, a failure of, i.e. (used only as a negative particle, usually with a prepositional prefix) not, except, without, unless, besides, because not, until, etc. because un(satiable), beside, but, continual, except, from, lest, neither, no more, none, not, nothing, save, that no, without.', 'constructive feminine of 1086 (equivalent to 1097);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0430G}/H9025/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["like/ God/ our"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6277}/[H6275]', 'lemma', 'heb', 'עָתָק', '["ʻâthâq"]', '["arrogance"]', '["a"]', 'impudent arrogancy, grievous (hard) things, stiff.', 'from 6275 in the sense of license;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1844}/[H1843]', 'lemma', 'heb', 'דֵּעָה', '["dêʻâh"]', '["knowledge","knowledge<s>"]', '["n-f"]', 'knowledge knowledge.', 'feminine of 1843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H9005}/H9033', 'inflected', 'heb', 'ולו', '["ve./l/o"]', '["and/ [belonged] to/ him","and/ by <the>/ him","and/ to <the>/ him"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8505}/[H8505]', 'lemma', 'heb', 'תָּכַן', '["tâkan"]', '["I put in order","[one who] weighs","are they correct","has he directed","has he marked off?","he has measured","is it correct","it is correct","they are measured"]', '["v"]', 'to balance, i.e. measure out (by weight or dimension); figuratively to arrange, equalize, through the idea of levelling (ment, estimate, test) bear up, direct, be (un-)equal, mete, ponder, tell, weigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2844B}/[H2865]', 'lemma', 'heb', 'חַת', '["chath"]', '["[are] shattered","[will be] terrified"]', '["n-m"]', 'concretely, crushed; also afraid; abstractly, terror broken, dismayed, dread, fear.', 'from 2865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3782}/[H3782]', 'inflected', 'heb', 'כָּשַׁל', '["kâshal"]', '["and/ [those who] stumble"]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0247}/[H247]', 'lemma', 'heb', 'אָזַר', '["ʼâzar"]', '["[was] girded","[who] gird on","[who] is girded","gird up","gird yourselves","he has girded himself","they gird on","you will gird"]', '["v"]', 'to belt bind (compass) about, gird (up, with).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7457}/[H7456]', 'inflected', 'heb', 'רָעֵב', '["râʻêb"]', '["and/ hungry","and/ hungry [people]"]', '["a"]', 'hungry (more or less intensely) hunger bitten, hungry.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0535}/[H535]', 'lemma', 'heb', 'אָמַל', '["ʼâmal"]', '["hot","it has languished","it has withered","she has grown feeble","she languishes","they are languishing","they have languished","they will languish"]', '["v"]', 'to droop; by implication to be sick, to mourn languish, be weak, wax feeble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6238}/[H6238]', 'inflected', 'heb', 'עָשַׁר', '["ʻâshar"]', '["and/ [is] making rich","so/ I may gain riches"]', '["v"]', 'properly, to accumulate; chiefly (specifically) to grow (causatively, make) rich be(-come, en-, make, make self, wax) rich, make (1 Kings 22:48 marg). See 6240.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8213}/[H8213]', 'lemma', 'heb', 'שָׁפֵל', '["shâphêl"]', '["I bring low","I will bring low","[he is] bringing low","[is] bringing low","he brings low","he will bring [it] low","it will become low","make low","people brought low","they will become low","to be lowly","to bring low","you bring [them] low","you bring low"]', '["v"]', 'to depress or sink (especially figuratively, to humiliate, intransitive or transitive) abase, bring (cast, put) down, debase, humble (self), be (bring, lay, make, put) low(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0830H}/[H827]', 'inflected', 'heb', 'אַשְׁפֹּת', '["ʼashpôth"]', '["from/ [the] ash heap"]', '["n-m"]', 'a heap of rubbish or filth dung (hill).', 'or אַשְׁפּוֹת; or שְׁפֹת; (contraction) plural of a noun of the same form as 827, from 8192 (in the sense of scraping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3678G}/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["and/ [the] throne of","and/ a throne of"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5157}/H9038/[H5157]', 'inflected', 'heb', 'נָחַל', '["nâchal"]', '["he makes inherit/ them","they will take possession of/ them"]', '["v"]', 'to inherit (as a (figurative) mode of descent), or (generally) to occupy; causatively, to bequeath, or (generally) distribute, instate divide, have (inheritance), take as a heritage, (cause to, give to, make to) inherit, (distribute for, divide (for, for an, by), give for, have, leave for, take (for)) inheritance, (have in, cause to, be made to) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4690}/[H6693]', 'lemma', 'heb', 'מָצוּק', '["mâtsûwq"]', '["[the] pillars of","a pillar"]', '["n-m"]', 'something narrow, i.e. a column or hilltop pillar, situate.', 'or מָצֻק; from 6693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8398}/[H2986]', 'lemma', 'heb', 'תֵּבֵל', '["têbêl"]', '["[the] world"]', '["n-f"]', 'the earth (as moist and therefore inhabited); by extension, the globe; by implication, its inhabitants; specifically, a particular land, as Babylonia, Palestine habitable part, world.', 'from 2986;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2623}/H9023/[H2616]', 'inflected', 'heb', 'חָסִיד', '["châçîyd"]', '["O faithful [people]/ his","faithful [people]/ his"]', '["a"]', 'properly, kind, i.e. (religiously) pious (a saint) godly (man), good, holy (one), merciful, saint, (un-) godly.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7563}/[H7561]', 'inflected', 'heb', 'רָשָׁע', '["râshâʻ"]', '["and/ [the] wicked","and/ a wicked [person]","and/ wicked [people]"]', '["a"]', 'morally wrong; concretely, an (actively) bad person condemned, guilty, ungodly, wicked (man), that did wrong.', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1826I}/[H1724]', 'lemma', 'heb', 'דָּמַם', '["dâmam"]', '["they will be silenced","you be destroyed"]', '["v"]', 'to be dumb; by implication, to be astonished, to stop; also to perish cease, be cut down (off), forbear, hold peace, quiet self, rest, be silent, keep (put to) silence, be (stand) still, tarry, wait.', 'a primitive root (compare 1724, 1820);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5181}/[H5181]', 'lemma', 'heb', 'נָחַת', '["nâchath"]', '["it goes deep","they descend","they have penetrated","they will be shattered","will he come down","you press down"]', '["v"]', 'to sink, i.e. descend; causatively, to press or lead down be broken, (cause to) come down, enter, go down, press sore, settle, stick fast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7481}/[H7481]', 'lemma', 'heb', 'רָעַם', '["râʻam"]', '["he thundered","he thunders","he will thunder","let it thunder","they have been disconcerted","will you thunder?"]', '["v"]', 'to tumble, i.e. be violently agitated; specifically, to crash (of thunder); figuratively, to irritate (with anger) make to fret, roar, thunder, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4428G}/H9023/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["to/ king/ his"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4899}/H9023\/[H4886]', 'inflected', 'heb', 'מָשִׁיחַ', '["mâshîyach"]', '["anointed/ his"]', '["n-m"]', 'anointed; usually a consecrated person (as a king, priest, or saint); specifically, the Messiah anointed, Messiah.', 'from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4941J}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ [the] custom of","and/ a custom","and/ custom"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1310}/[H1310]', 'inflected', 'heb', 'בָּשַׁל', '["bâshal"]', '["when/ boiled"]', '["v"]', 'properly, to boil up; hence, to be done in cooking; figuratively to ripen bake, boil, bring forth, roast, seethe, sod (be sodden).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H4207A>', 'inflected', 'heb', 'והמזלג', '["ve./ha./maz.Leg"]', '["and/ the/ fork"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8127J}/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["the/ prongs"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3595}/[H3564]', 'inflected', 'heb', 'כִּיּוֹר', '["kîyôwr"]', '["in the/ pot"]', '["n-m"]', 'properly, something round (as excavated or bored), i.e. a chafing-dish for coals or a caldron for cooking; hence (from similarity of form) a washbowl; also (for the same reason) a pulpit or platform hearth, laver, pan, scaffold.', 'or כִּיֹּר; from the same as 3564;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1731}/[H1730]', 'inflected', 'heb', 'דּוּד', '["dûwd"]', '["in <the>/ baskets","in the/ kettle"]', '["n-m"]', 'a pot (for boiling); also (by resemblance of shape) a basket basket, caldron, kettle, (seething) pot.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7037}/[H6747]', 'inflected', 'heb', 'קַלַּחַת', '["qallachath"]', '["in the/ caldron"]', '["n-f"]', 'a kettle caldron.', 'apparently but a form for 6747;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4207A>', 'inflected', 'heb', 'המזלג', '["ha./maz.Leg"]', '["the/ fork"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6999A}/H9013/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["let them make smoke/ !","they made smoke/ !"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2076}/[H2076]', 'inflected', 'heb', 'זָבַח', '["zâbach"]', '["those/ [who] sacrifice","who/ sacrificed","who/ was sacrificing"]', '["v"]', 'to slaughter an animal (usually in sacrifice) kill, offer, (do) sacrifice, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6740}/[H6740]', 'inflected', 'heb', 'צָלָה', '["tsâlâh"]', '["to/ roast"]', '["v"]', 'to roast roast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8050G}/[H8085]', 'inflected', 'heb', 'שְׁמוּאֵל', '["Shᵉmûwʼêl"]', '["and/ Samuel"]', '["n-pr-m"]', 'Shemuël, the name of three Israelites Samuel, Shemuel.', 'from the passive participle of 8085 and 410; heard of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6996B}/[H6962]', 'lemma', 'heb', 'קָטָן', '["qâṭân"]', '["[is] small","[the] small","[was too] small","[were] small","small","young"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5927G}/H9044/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["when/ went up/ she"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7596}/[H7592]', 'inflected', 'heb', 'שְׁאֵלָה', '["shᵉʼêlâh"]', '["the/ petition"]', '["n-f"]', 'a petition; by implication, a loan loan, petition, request.', 'or שֵׁלָה; (1 Samuel 1:17), from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7901I}/H9013/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["they were lying with/ !"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697O}/H9026/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["things/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8052}/[H8074]', 'inflected', 'heb', 'שְׁמוּעָה', '["shᵉmûwʻâh"]', '["the/ report"]', '["n-f"]', 'something heard, i.e. an announcement bruit, doctrine, fame, mentioned, news, report, rumor, tidings.', 'feminine passive participle of 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6419}/H9033/[H6419]', 'inflected', 'heb', 'פָּלַל', '["pâlal"]', '["and/ he will mediate for/ him"]', '["v"]', 'to judge (officially or mentally); by extension, to intercede, pray intreat, judge(-ment), (make) pray(-er, -ing), make supplication.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2895}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["and/ he was good"]', '["v"]', 'to be (transitively, do or make) good (or well) in the widest sense be (do) better, cheer, be (do, seem) good, (make) goodly, × please, (be, do, go, play) well.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0582}\/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["a man","people"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1540H}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["¿/ have they been revealed","¿/ really <to reveal>"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0977}/[H977]', 'inflected', 'heb', 'בָּחַר', '["bâchar"]', '["and/ I chose","and/ let them choose","and/ to choose","so/ you may choose"]', '["v"]', 'properly, to try, i.e. (by implication) select acceptable, appoint, choose (choice), excellent, join, be rather, require.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1163}/[H1163]', 'lemma', 'heb', 'בָּעַט', '["bâʻaṭ"]', '["do you kick"]', '["v"]', 'to trample down, i.e. (figuratively) despise kick.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2077}/H9020/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["at/ sacrifice/ my"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H4503G>/H9020', 'inflected', 'heb', 'ובמנחתי', '["u./ve./min.cha.T/i"]', '["and/ at/ offering/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4583}/[H5772]', 'lemma', 'heb', 'מָעוֹן', '["mâʻôwn"]', '["[the] habitation of","a dwelling place","a habitation of"]', '["n-m"]', 'an abode, of God (the Tabernacle or the Temple), men (their home) or animals (their lair); hence, a retreat (asylum) den, dwelling((-) place), habitation.', 'or מָעִין; (1 Chronicles 4:41), from the same as 5772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3513G}/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["and/ I will gain glory","and/ you honor"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1254B}/H9036/[H1254]', 'inflected', 'heb', 'בָּרָא', '["bârâʼ"]', '["by/ fattening/ yourselves"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7225H}/[H7218]', 'inflected', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["from/ [the] choicest of"]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3513G}/H9030/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["[those who] honor/ me","he honors/ me","honor/ me","it honors/ me","they have honored/ me","you have honored/ me"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0959}/H9030/[H959]', 'inflected', 'heb', 'בָּזָה', '["bâzâh"]', '["and/ [those who] despise/ me"]', '["v"]', 'to disesteem despise, disdain, contemn(-ptible), think to scorn, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1438}/[H1438]', 'inflected', 'heb', 'גָּדַע', '["gâdaʻ"]', '["and/ I cut up","and/ I will cut off","and/ he cut down","and/ it will be cut down","and/ they cut down","and/ they will be cut down","and/ they will be cut off"]', '["v"]', 'to fell a tree; generally, to destroy anything cut (asunder, in sunder, down, off), hew down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3615H}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["<to>/ finished","to/ cause to fail","to/ fulfill"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0109}/[H109]', 'inflected', 'heb', 'אָדַב', '["ʼâdab"]', '["and/ to/ cause to grieve"]', '["v"]', 'to languish grieve.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4768}/[H7235]', 'lemma', 'heb', 'מַרְבִּית', '["marbîyth"]', '["[the] greater part of","[the] greatness of","[the] increase of"]', '["n-f"]', 'a multitude; also offspring; specifically interest (on capital) greatest part, greatness, increase, multitude.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3824}/H9020/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["[is] in/ heart/ my","[was] in/ heart/ my","in/ heart/ my"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5315G}/H9020/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ in/ soul/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4899}/H9020/[H4886]', 'inflected', 'heb', 'מָשִׁיחַ', '["mâshîyach"]', '["anointed/ my"]', '["n-m"]', 'anointed; usually a consecrated person (as a king, priest, or saint); specifically, the Messiah anointed, Messiah.', 'from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0095}/[H94]', 'inflected', 'heb', 'אֲגוֹרָה', '["ʼăgôwrâh"]', '["for/ a payment of"]', '["n-f"]', 'properly, something gathered, i.e. perhaps a grain or berry; used only of a small (silver) coin piece (of) silver.', 'from the same as 94;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5596A}/H9030/[H5596]', 'inflected', 'heb', 'סָפַח', '["çâphach"]', '["attach/ me"]', '["v"]', 'properly, to scrape out, but in certain peculiar senses (of removal or association) abiding, gather together, cleave, smite with the scab.', 'or שָׂפַח; (Isaiah 3:17), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3550}/[H3547]', 'inflected', 'heb', 'כְּהֻנָּה', '["kᵉhunnâh"]', '["the/ priesthood","the/ priesthoods"]', '["n-f"]', 'priesthood priesthood, priest''s office.', 'from 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899H}\/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["bread"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3368}/[H3365]', 'lemma', 'heb', 'יָקָר', '["yâqâr"]', '["[a person] noble of","[is] precious","[is] weighty","[the] precious","costly","precious","preciousness of","prized","rare","splendid","splendid [ones]"]', '["a"]', 'valuable (objectively or subjectively) brightness, clear, costly, excellent, fat, honourable women, precious, reputation.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2377}/[H2372]', 'lemma', 'heb', 'חָזוֹן', '["châzôwn"]', '["[is] vision","[the] vision","[the] vision of","a vision","a vision of","vision","vision of","vision[s]"]', '["n-m"]', 'a sight (mentally), i.e. a dream, revelation, or oracle vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6555}\/[H6555]', 'inflected', 'heb', 'פָּרַץ', '["pârats"]', '["[was] spread out","they will burst open"]', '["v"]', 'to break out (in many applications, direct and indirect, literal and figurative) × abroad, (make a) breach, break (away, down, -er, forth, in, up), burst out, come (spread) abroad, compel, disperse, grow, increase, open, press, scatter, urge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4725}/H9023/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["[are] in/ place/ his","in/ place/ his","in/ place/ its"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5869H}/H9023/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ eyes/ his"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5216A}/[H5214]', 'inflected', 'heb', 'נִיר', '["nîyr"]', '["and/ [the] lamp of"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1964G}/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["<in>/ [the] temple of","[is] in/ [the] temple of","for/ [the] temple of","in the/ temple","in/ [the] temple of"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7901G}\/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ he lay down"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2962>', 'inflected', 'heb', 'וטרם', '["ve./Te.rem"]', '["and/ not yet"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7992}/[H7969]', 'inflected', 'heb', 'שְׁלִישִׁי', '["shᵉlîyshîy"]', '["at the/ third [time]","in the/ third [month]","in the/ thirds"]', '["a"]', 'third; feminine a third (part); by extension, a third (day, year or time); specifically, a third-story cell) third (part, rank, time), three (years old).', 'ordinal from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0995}/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["and/ I looked carefully","and/ he acted wisely","and/ he gave understanding","and/ he understood","and/ it has understood","and/ they understood","and/ you have considered carefully","and/ you will look carefully"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8050G}/[H8085]', 'inflected', 'heb', 'שְׁמוּאֵל', '["Shᵉmûwʼêl"]', '["to/ Samuel"]', '["n-pr-m"]', 'Shemuël, the name of three Israelites Samuel, Shemuel.', 'from the passive participle of 8085 and 410; heard of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5650}/H9021\/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["servant/ your"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085G}/H9033/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["[one who] hears/ it"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6750}/[H6750]', 'lemma', 'heb', 'צָלַל', '["tsâlal"]', '["they quivered","they will tingle"]', '["v"]', 'to tinkle, i.e. rattle together (as the ears in reddening with shame, or the teeth in chattering with fear) quiver, tingle.', 'a primitive root (identical with through the idea of vibration);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3543B}/[H3543]', 'lemma', 'heb', 'כָּהָה', '["kâhâh"]', '["he rebuked"]', '["v"]', 'to be weak, i.e. (figuratively) to despond (causatively, rebuke), or (of light, the eye) to grow dull darken, be dim, fail, faint, restrain, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3651C}/[H3559]', 'inflected', 'heb', 'כֵּן', '["kên"]', '["and/ <to>/ therefore"]', '["adv"]', 'properly, set upright; hence (figuratively as adjective) just; but usually (as adverb or conjunction) rightly or so (in various applications to manner, time and relation; often with other particles) after that (this, -ward, -wards), as... as, (for-) asmuch as yet, be (for which) cause, following, howbeit, in (the) like (manner, -wise), × the more, right, (even) so, state, straightway, such (thing), surely, there (where) -fore, this, thus, true, well, × you.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2077}/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["at the/ sacrifice","by/ sacrifice"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H4503G>', 'inflected', 'heb', 'ובמנחה', '["u./ve./min.Chah","u./ve./min.Chat"]', '["and/ at/ [the] offering of","and/ by/ an offering"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5046}/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["from/ telling"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4759A}/[H4758]', 'inflected', 'heb', 'מַרְאָה', '["marʼâh"]', '["the/ vision"]', '["n-f"]', 'a vision; also (causatively) a mirror looking glass, vision.', 'feminine of 4758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1835G}/[H1777]', 'inflected', 'heb', 'דָּן', '["Dân"]', '["from/ Dan"]', '["n-pr-m"]', 'Dan, one of the sons of Jacob; also the tribe descended from him, and its territory; likewise a place in Palestine colonized by them Daniel', 'from 1777; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5030}/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["for the/ prophet","of the/ prophets","to the/ prophet","to/ [the] prophets","to/ [the] prophets of","to/ a prophet","to/ prophet","to/ prophets"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0072}/[H68]', 'inflected', 'heb', 'אֶבֶן הָעֵזֶר', '["ʼEben hâ-ʻÊzer"]', '["<the>/ -ezer","<the>/ Eben-"]', '["n"]', 'Eben-ha-Ezer, a place in Palestine Ebenezer.', 'from 68 and 5828 with the article inserted; stone of the help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0072}/[H68]', 'lemma', 'heb', 'אֶבֶן הָעֵזֶר', '["ʼEben hâ-ʻÊzer"]', '["-ezer","Eben-"]', '["n"]', 'Eben-ha-Ezer, a place in Palestine Ebenezer.', 'from 68 and 5828 with the article inserted; stone of the help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0663G}/[H662]', 'inflected', 'heb', 'אֲפֵק', '["ʼĂphêq"]', '["at/ Aphek"]', '["n-pr-loc"]', 'Aphek (or Aphik), the name of three places in Palestine Aphek, Aphik.', 'or אֲפִיק; from 662 (in the sense of strength); fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0702}/[H7251]', 'inflected', 'heb', 'אַרְבַּע', '["ʼarbaʻ"]', '["about/ four","like/ [the] four"]', '["n"]', 'four four.', 'masculine אַרְבָּעָה; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5062}/H9035/[H5062]', 'inflected', 'heb', 'נָגַף', '["nâgaph"]', '["has he defeated/ us"]', '["v"]', 'to push, gore, defeat, stub (the toe), inflict (a disease) beat, dash, hurt, plague, slay, smite (down), strike, stumble, × surely, put to the worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3467}/H9035/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ he will save/ us","and/ save/ us","so/ he may deliver/ us","so/ it may deliver/ us"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0865}/[H853]', 'lemma', 'heb', 'אֶתְמוֹל', '["ʼethmôwl"]', '["yesterday"]', '["adv"]', 'heretofore; definitely yesterday before (that) time, heretofore, of late (old), times past, yester(day).', 'or אִתְמוֹל; or אֶתְמוּל; probably from 853 or 854 and 4136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0117}/[H142]', 'inflected', 'heb', 'אַדִּיר', '["ʼaddîyr"]', '["<the>/ mighty","the/ nobles"]', '["a"]', 'wide or (generally) large; figuratively, powerful excellent, famous, gallant, glorious, goodly, lordly, mighty(-ier one), noble, principal, worthy.', 'from 142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5680}/[H5677]', 'inflected', 'heb', 'עִבְרִי', '["ʻIbrîy"]', '["<to> the/ Hebrews"]', '["n-pr"]', 'an Eberite (i.e. Hebrew) or descendant of Eber Hebrew(-ess, woman).', 'patronymic from 5677;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0168H}/H9023/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["to/ own tents/ his","to/ tents/ his","to/ tents/ its"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4347}/[H5221]', 'inflected', 'heb', 'מַכָּה', '["makkâh"]', '["[are] the/ wounds","the/ slaughter","the/ wound","the/ wounds"]', '["n-f"]', 'a blow (in 2 Chronicles 2:10, of the flail); by implication, a wound; figuratively, carnage, also pestilence beaten, blow, plague, slaughter, smote, × sore, stripe, stroke, wound(-ed).', 'or (masculine) מַכֶּה; (plural only) from 5221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H4634}/[H4633]', 'inflected', 'heb', 'מַעֲרָכָה', '["maʻărâkâh"]', '["from/ the/ battle line"]', '["n-f"]', 'an arrangement; concretely, a pile; specifically a military array army, fight, be set in order, ordered place, rank, row.', 'feminine of 4633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4055}/H9023/[H4058]', 'inflected', 'heb', 'מַד', '["mad"]', '["and/ garments/ his"]', '["n-m"]', 'properly, extent, i.e. height; also a measure; by implication, a vesture (as measured); also a carpet armour, clothes, garment, judgment, measure, raiment, stature.', 'or מֵד; from 4058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0127G}/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["and/ earth","and/ ground","and/ land"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027J}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["[the] side of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2730}/[H2729]', 'lemma', 'heb', 'חָרֵד', '["chârêd"]', '["[person] trembling","trembling"]', '["a"]', 'fearful; also reverential afraid, trembling.', 'from 2729;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6818}/[H6817]', 'inflected', 'heb', 'צַעֲקָה', '["tsaʻăqâh"]', '["the/ outcry"]', '["n-f"]', 'a shriek cry(-ing).', 'from 6817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1995A}/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["the/ abundance","the/ multitude","the/ uproar"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5941}/[H5927]', 'inflected', 'heb', 'עֵלִי', '["ʻÊlîy"]', '["to/ Eli"]', '["n-pr-m"]', 'Eli, an Israelite highpriest Eli.', 'from 5927; lofty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5869A}/H9023/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ eyes/ his","and/ eyes/ its"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1319}/[H1319]', 'inflected', 'heb', 'בָּשַׂר', '["bâsar"]', '["the/ [women who] bear news","the/ bearer of news"]', '["v"]', 'properly, to be fresh, i.e. full (rosy, figuratively cheerful); to announce (glad news) messenger, preach, publish, shew forth, (bear, bring, carry, preach, good, tell good) tidings.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4046}/[H5062]', 'lemma', 'heb', 'מַגֵּפָה', '["maggêphâh"]', '["[the] plague of","a blow","a plague","a slaughter"]', '["n-f"]', 'a pestilence; by analogy, defeat (× be) plague(-d), slaughter, stroke.', 'from 5062;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947G}\/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["it has been taken","it will take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2142}/H9043/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["when/ brought to remembrance/ he"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4665}/H9023/[H6561]', 'inflected', 'heb', 'מִפְרֶקֶת', '["miphreqeth"]', '["neck/ his"]', '["n-f"]', 'properly, a fracture, i.e. joint (vertebrae) of the neck neck.', 'from 6561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3618H}/H9023/[H3634]', 'inflected', 'heb', 'כַּלָּה', '["kallâh"]', '["and/ daughter-in-law/ his"]', '["n-f"]', 'a bride (as if perfect); hence, a son''s wife bride, daughter-in-law, spouse.', 'from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6372H}/[H6310]', 'lemma', 'heb', 'פִּינְחָס', '["Pîynᵉchâç"]', '["Phinehas"]', '["n-pr-m"]', 'Pinechas, the name of three Israelites Phinehas.', 'apparently from 6310 and a variation of 5175; mouth of a serpent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3766}/[H3766]', 'inflected', 'heb', 'כָּרַע', '["kâraʻ"]', '["and/ he bowed down","and/ he sank down","and/ she bowed down","and/ they bowed down"]', '["v"]', 'to bend the knee; by implication, to sink, to prostrate bow (down, self), bring down (low), cast down, couch, fall, feeble, kneeling, sink, smite (stoop) down, subdue, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6735C}/H9024/[H6696]', 'inflected', 'heb', 'צִיר', '["tsîyr"]', '["pangs/ her"]', '["n-m"]', 'a hinge (as pressed in turning); also a throe (as a phys. or mental pressure); also a herald or errand-doer (as constrained by the principal) ambassador, hinge, messenger, pain, pang, sorrow. Compare 6736.', 'from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9044/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["dying/ she"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0350}/[H336]', 'lemma', 'heb', 'אִי־כָבוֹד', '["ʼÎy-kâbôwd"]', '["-chabod","I-","Ichabod"]', '["n-pr-m"]', 'Ikabod, a son of Phineas I-chabod.', 'from 336 and 3519; (there is) no glory, i.e. inglorious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0072}/[H68]', 'inflected', 'heb', 'אֶבֶן הָעֵזֶר', '["ʼEben hâ-ʻÊzer"]', '["from/ Eben-"]', '["n"]', 'Eben-ha-Ezer, a place in Palestine Ebenezer.', 'from 68 and 5828 with the article inserted; stone of the help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0795}/H9011/[H7703]', 'inflected', 'heb', 'אַשְׁדּוֹד', '["ʼAshdôwd"]', '["Ashdod/ towards"]', '["n-pr-loc"]', 'Ashdod, a place in Palestine Ahdod.', 'from 7703; ravager;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1712}/[H1709]', 'lemma', 'heb', 'דָּגוֹן', '["Dâgôwn"]', '["Dagon"]', '["n-pr-m"]', 'Dagon, a Philistine deity Dagon.', 'from 1709; the fish-god;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0796}/[H795]', 'lemma', 'heb', 'אַשְׁדּוֹדִי', '["ʼAshdôwdîy"]', '["Ashdodite","[the] Ashdodites"]', '["a"]', 'an Ashdodite (often collectively) or inhabitant of Asdod Ashdodites, of Ashdod.', 'patrial from 795;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4670}/[H6620]', 'inflected', 'heb', 'מִפְתָּן', '["miphtân"]', '["the/ threshold"]', '["n-m"]', 'a stretcher, i.e. a sill threshold.', 'from the same as 6620;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4670}/[H6620]', 'lemma', 'heb', 'מִפְתָּן', '["miphtân"]', '["[the] threshold of"]', '["n-m"]', 'a stretcher, i.e. a sill threshold.', 'from the same as 6620;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0795}/[H7703]', 'inflected', 'heb', 'אַשְׁדּוֹד', '["ʼAshdôwd"]', '["against/ Ashdod","in/ Ashdod"]', '["n-pr-loc"]', 'Ashdod, a place in Palestine Ahdod.', 'from 7703; ravager;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0796}/[H795]', 'inflected', 'heb', 'אַשְׁדּוֹדִי', '["ʼAshdôwdîy"]', '["the/ Ashdodites"]', '["a"]', 'an Ashdodite (often collectively) or inhabitant of Asdod Ashdodites, of Ashdod.', 'patrial from 795;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8074H}/H9038/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["and/ he devastated/ them"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2914>', 'inflected', 'heb', 'בטחרים', '["ba/t.cho.Rim"]', '["with <the>/ tumors","with the/ tumors"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1661}/[H1660]', 'lemma', 'heb', 'גַּת', '["Gath"]', '["Gath"]', '["n-pr-loc"]', 'Gath, a Philistine city Gath.', 'the same as 1660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6996H}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["from/ young"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1419K}/[H1431]', 'lemma', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["[the] old"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8368}/[H8368]', 'inflected', 'heb', 'שָׂתַר', '["sâthar"]', '["and/ they broke out"]', '["v"]', 'to break out (as an eruption) have in (one''s) secret parts.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2914>', 'opaque', 'heb', 'טְחֹר', '["ṭᵉchôr"]', '["[are] [the] tumors of","tumors","tumors of"]', '["n-m"]', 'a boil or ulcer (from the inflammation), especially a tumor in the anus or pudenda (the piles) emerod.', 'from an unused root meaning to burn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6139}/[H6138]', 'inflected', 'heb', 'עֶקְרוֹנִי', '["ʻEqrôwnîy"]', '["the/ Ekronites"]', '["a"]', 'an Ekronite or inhabitant of Ekron Ekronite.', 'or עֶקְרֹנִי; patrial from 6138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4191}/H9030/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["to/ cause to die/ me","to/ kill/ me","to/ put to death/ me"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7775}/[H7773]', 'lemma', 'heb', 'שַׁוְעָה', '["shavʻâh"]', '["[the] cry for help of"]', '["n-f"]', 'a hallooing crying.', 'feminine of 7773;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7080}/[H7080]', 'inflected', 'heb', 'קָסַם', '["qâçam"]', '["and/ <to> the/ diviners"]', '["v"]', 'properly, to distribute, i.e. determine by lot or magical scroll; by implication, to divine divine(-r, -ation), prudent, soothsayer, use (divination).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9035/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["[is] perceiving/ us","he knows/ us","make known to/ us"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5909}/[H5908]', 'lemma', 'heb', 'עַכְבָּר', '["ʻakbâr"]', '["[the] mice of","mice of"]', '["n-m"]', 'a mouse (as nibbling) mouse.', 'probably from the same as 5908 in the secondary sense of attacking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H5633A>/H9026', 'inflected', 'heb', 'ולסרניכם', '["u./le./sar.nei./Khem"]', '["and/ to/ rulers/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2914>/H9026', 'opaque', 'heb', 'טְחֹר', '["ṭᵉchôr"]', '["tumors/ your"]', '["n-m"]', 'a boil or ulcer (from the inflammation), especially a tumor in the anus or pudenda (the piles) emerod.', 'from an unused root meaning to burn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6754>', 'inflected', 'heb', 'וצלמי', '["ve./tzal.Mei"]', '["and/ [the] images of","and/ images of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5909}/H9026/[H5908]', 'inflected', 'heb', 'עַכְבָּר', '["ʻakbâr"]', '["mice/ your"]', '["n-m"]', 'a mouse (as nibbling) mouse.', 'probably from the same as 5908 in the secondary sense of attacking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5921A}/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["and/ from/ on","and/ from/ over","and/ from/ with"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430J}/H9026/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["gods/ your"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121H}/H9028/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["young ones/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0712}/[H7264]', 'inflected', 'heb', 'אַרְגָּז', '["ʼargâz"]', '["in the/ box"]', '["n-m"]', 'a box (as a pannier) coffer.', 'perhaps from 7264 (in the sense of being suspended),');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6654>/H9023', 'inflected', 'heb', 'מצדו', '["mi./tzi.D/o"]', '["from/ side/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4745}/[H7136]', 'lemma', 'heb', 'מִקְרֶה', '["miqreh"]', '["[is] an accident","[the] fate of","chance","fate"]', '["n-m"]', 'something met with, i.e. an accident or fortune something befallen, befalleth, chance, event, hap(-peneth).', 'from 7136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0631}/H9038/[H631]', 'inflected', 'heb', 'אָסַר', '["ʼâçar"]', '["and/ they harnessed/ them"]', '["v"]', 'to yoke or hitch; by analogy, to fasten in any sense, to join battle bind, fast, gird, harness, hold, keep, make ready, order, prepare, prison(-er), put in bonds, set in array, tie.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0712}/[H7264]', 'inflected', 'heb', 'אַרְגָּז', '["ʼargâz"]', '["the/ box"]', '["n-m"]', 'a box (as a pannier) coffer.', 'perhaps from 7264 (in the sense of being suspended),');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2914>/H9028', 'opaque', 'heb', 'טְחֹר', '["ṭᵉchôr"]', '["tumors/ their"]', '["n-m"]', 'a boil or ulcer (from the inflammation), especially a tumor in the anus or pudenda (the piles) emerod.', 'from an unused root meaning to burn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1600}/[H1600]', 'inflected', 'heb', 'גָּעָה', '["gâʻâh"]', '["and/ lowed"]', '["v"]', 'to bellow (as cattle) low.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1053G}/[H1004]', 'inflected', 'heb', 'בֵּית שֶׁמֶשׁ', '["Bêyth Shemesh"]', '["and/ Beth","and/ in Beth"]', '["n-pr-loc"]', 'Beth-Shemesh, a place in Palestine Beth-shemesh.', 'from 1004 and 8121; house of (the) sun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5699}/[H5696]', 'inflected', 'heb', 'עֲגָלָה', '["ʻăgâlâh"]', '["and/ the/ cart"]', '["n-f"]', 'something revolving, i.e. a wheeled vehicle cart, chariot, wagon', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3091H}/[H3068]', 'lemma', 'heb', 'יְהוֹשׁוּעַ', '["Yᵉhôwshûwaʻ"]', '["Joshua"]', '["n-pr-m"]', 'Jehoshua (i.e. Joshua), the Jewish leader Jehoshua, Jehoshuah, Joshua. Compare 1954, 3442.', 'or יְהוֹשֻׁעַ; from 3068 and 3467; Jehovah-saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1030}/[H1053]', 'lemma', 'heb', 'בֵּית הַשִּׁמְשִׁי', '["Bêyth hash-Shimshîy"]', '["[the] Beth"]', '["a"]', 'a Beth-shimshite, or inhabitant of Bethshemesh Bethshemite.', 'patrial from 1053 with the article inserted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1030}/[H1053]', 'inflected', 'heb', 'בֵּית הַשִּׁמְשִׁי', '["Bêyth hash-Shimshîy"]', '["<the>/ Shemeshite"]', '["a"]', 'a Beth-shimshite, or inhabitant of Bethshemesh Bethshemite.', 'patrial from 1053 with the article inserted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0795}/[H7703]', 'inflected', 'heb', 'אַשְׁדּוֹד', '["ʼAshdôwd"]', '["for/ Ashdod"]', '["n-pr-loc"]', 'Ashdod, a place in Palestine Ahdod.', 'from 7703; ravager;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5804}/[H5794]', 'inflected', 'heb', 'עַזָּה', '["ʻAzzâh"]', '["for/ Gaza"]', '["n-f"]', 'Azzah, a place in Palestine Azzah, Gaza.', 'feminine of 5794; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0831}/[H8254]', 'inflected', 'heb', 'אַשְׁקְלוֹן', '["ʼAshqᵉlôwn"]', '["for/ Ashkelon"]', '["n-pr-loc"]', 'Ashkelon, a place in Palestine Ashkelon, Askalon.', 'probably from 8254 in the sense of weighing-place (i.e. mart);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1661}/[H1660]', 'inflected', 'heb', 'גַּת', '["Gath"]', '["for/ Gath"]', '["n-pr-loc"]', 'Gath, a Philistine city Gath.', 'the same as 1660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6138}/[H6131]', 'inflected', 'heb', 'עֶקְרוֹן', '["ʻEqrôwn"]', '["for/ Ekron"]', '["n-pr-loc"]', 'Ekron, a place in Palestine Ekron.', 'from 6131; eradication;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5909}/[H5908]', 'inflected', 'heb', 'עַכְבָּר', '["ʻakbâr"]', '["and/ [the] mice of"]', '["n-m"]', 'a mouse (as nibbling) mouse.', 'probably from the same as 5908 in the secondary sense of attacking;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2568}/[H2568]', 'inflected', 'heb', 'חָמֵשׁ', '["châmêsh"]', '["for/ fif-","of/ [the] five"]', '["n"]', 'five fif(-teen), fifth, five (× apiece).', 'masculine חֲמִשָּׁה; a primitive numeral;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3724D}/[H3722]', 'lemma', 'heb', 'כֹּפֶר', '["kôpher"]', '["<the> village[s] of"]', '["n-m"]', 'properly, a cover, i.e. (literally) a village (as covered in); (specifically) bitumen (as used for coating), and the henna plant (as used for dyeing); figuratively, a redemption-price bribe, camphire, pitch, ransom, satisfaction, sum of money, village.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0059G}/[H58]', 'lemma', 'heb', 'אָבֵל', '["ʼÂbêl"]', '["Abel"]', '["n-pr-loc"]', 'Abel, the name of two places in Palestine. Abel.', 'from 58; a meadow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5921A}/H9035\/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["from/ on <the>/ us","from/ with <the>/ us"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0041G}/[H1]', 'lemma', 'heb', 'אֲבִינָדָב', '["ʼĂbîynâdâb"]', '["Abinadab"]', '["n-pr-m"]', 'Abinadab, the name of four Israelites Abinadab.', 'from 1 and 5068; father of generosity (i.e. liberal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1389I}/[H1387]', 'inflected', 'heb', 'גִּבְעָה', '["gibʻâh"]', '["[was] on the/ hill","on the/ hill","on/ [the] hill of"]', '["n-f"]', 'a hillock hill, little hill.', 'feminine from the same as 1387;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0499H}/[H410]', 'lemma', 'heb', 'אֶלְעָזָר', '["ʼElʻâzâr"]', '["Eleazar"]', '["n-pr-m"]', 'Elazar, the name of seven Israelites Eleazar.', 'from 410 and 5826; God (is) helper;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5091}/[H5091]', 'inflected', 'heb', 'נָהָה', '["nâhâh"]', '["and/ he will wail","and/ they mourned"]', '["v"]', 'to groan, i.e. bewail; hence (through the idea of crying aloud), to assemble (as if on proclamation) lament, wail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H8432>/H9026', 'inflected', 'heb', 'מתוככם', '["mi./tokh./Khem"]', '["from/ among/ you"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6252G}/[H6251]', 'inflected', 'heb', 'עַשְׁתָּרוֹת', '["ʻAshtârôwth"]', '["and/ the/ Ashtaroth"]', '["n-pr-f"]', 'Ashtaroth, the name of a Sidonian deity, and of a place East of the Jordan Asharoth, Astaroth. See also 1045, 6253, 6255.', 'or עַשְׁתָּרֹת; plural of 6251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3559J}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["and/ direct"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5647G}/H9033/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ serve/ him"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0905H}/H9033\/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["to/ only/ him"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4709G}/H9011/[H4708]', 'inflected', 'heb', 'מִצְפָּה', '["Mitspâh"]', '["<the>/ Mizpah/ towards"]', '["n-pr-f"]', 'Mitspah, the name of two places in Palestine Mitspah. (This seems rather to be only an orthographic variation of 4708 when ''in pause''.)', 'feminine of 4708;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1157}/H9036/[H5704]', 'inflected', 'heb', 'בְּעַד', '["bᵉʻad"]', '["for/ you","for/ yourselves"]', '["prep"]', 'in up to or over against; generally at, beside, among, behind, for, etc. about, at by (means of), for, over, through, up (-on), within.', 'from 5704 with prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2199}/[H2199]', 'inflected', 'heb', 'זָעַק', '["zâʻaq"]', '["from/ crying out"]', '["v"]', 'to shriek (from anguish or danger); by analogy, (as a herald) to announce or convene publicly assemble, call (together), (make a) cry (out), come with such a company, gather (together), cause to be proclaimed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2924}/[H2922]', 'lemma', 'heb', 'טָלֶה', '["ṭâleh"]', '["a lamb of"]', '["n-m"]', 'a lamb lamb.', 'by variation for 2922;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6030B}/H9033/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ he answered/ him"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7481}/[H7481]', 'inflected', 'heb', 'רָעַם', '["râʻam"]', '["and/ he thundered"]', '["v"]', 'to tumble, i.e. be violently agitated; specifically, to crash (of thunder); figuratively, to irritate (with anger) make to fret, roar, thunder, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963H>', 'inflected', 'heb', 'בקול', '["be./Kol","be./kol"]', '["<in>/ a sound","with/ [the] sound of","with/ a sound"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1033}/[H1004]', 'inflected', 'heb', 'בֵּית כַּר', '["Bêyth Kar"]', '["to/ Beth"]', '["n-pr-loc"]', 'Beth-Car, a place in Palestine Beth-car.', 'from 1004 and 3733; house of pasture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1033}/[H1004]', 'lemma', 'heb', 'בֵּית כַּר', '["Bêyth Kar"]', '["Car"]', '["n-pr-loc"]', 'Beth-Car, a place in Palestine Beth-car.', 'from 1004 and 3733; house of pasture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8129}/[H8127]', 'inflected', 'heb', 'שֵׁן', '["Shên"]', '["<the>/ Shen"]', '["n-pr-loc"]', 'Shen, a place in Palestine Shen.', 'the same as 8127; crag;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5826}/H9035/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["he has helped/ us","help/ us"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6430G}/[H6429]', 'inflected', 'heb', 'פְּלִשְׁתִּי', '["Pᵉlishtîy"]', '["<in> the/ Philistines","against the/ Philistines","among the/ Philistines","on the/ Philistines","with the/ Philistines"]', '["a"]', 'a Pelishtite or inhabitant of Pelesheth Philistine.', 'patrial from 6429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366H}/H9029/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["territory/ their"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1537G}/[H1536]', 'inflected', 'heb', 'גִּלְגָּל', '["Gilgâl"]', '["and/ <the>/ Gilgal"]', '["n-pr-loc"]', 'Gilgal, the name of three places in Palestine Gilgal. See also 1019.', 'the same as 1536 (with the article as a properly, noun);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4709G}/[H4708]', 'inflected', 'heb', 'מִצְפָּה', '["Mitspâh"]', '["and/ <the>/ Mizpah"]', '["n-pr-f"]', 'Mitspah, the name of two places in Palestine Mitspah. (This seems rather to be only an orthographic variation of 4708 when ''in pause''.)', 'feminine of 4708;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8666}/H9023/[H7725]', 'inflected', 'heb', 'תְּשׁוּבָה', '["tᵉshûwbâh"]', '["and/ return/ his"]', '["n-f"]', 'a recurrence (of time or place); a reply (as returned) answer, be expired, return.', 'or תְּשֻׁבָה; from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3100G}/[H3068]', 'lemma', 'heb', 'יוֹאֵל', '["Yôwʼêl"]', '["Joel"]', '["n-pr-m"]', 'Joel, the name of twelve Israelites Joel.', 'from 3068 and 410; Jehovah (is his) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4932H}/H9023/[H8138]', 'inflected', 'heb', 'מִשְׁנֶה', '["mishneh"]', '["second/ his"]', '["n-m"]', 'properly, a repetition, i.e. a duplicate (copy of a document), or a double (in amount); by implication, a second (in order, rank, age, quality or location) college, copy, double, fatlings, next, second (order), twice as much.', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0029G}/[H1]', 'lemma', 'heb', 'אֲבִיָּה', '["ʼĂbîyâh"]', '["[was] Abijah"]', '["n-pr-m"]', 'Abijah, the name of several Israelite men and two Israelitesses Abiah, Abijah.', 'or prolonged אֲבִיָּהוּ ; from 1 and 3050; father (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1215}/[H1214]', 'inflected', 'heb', 'בֶּצַע', '["betsaʻ"]', '["<the>/ unjust gain"]', '["n-m"]', 'plunder; by extension, gain (usually unjust) covetousness, (dishonest) gain, lucre, profit.', 'from 1214;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941H}\/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["justice"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870G}/H9021/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["in/ own way/ your","in/ ways/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760L}/H9012/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["appoint/ !"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8199}/H9035/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["to/ judge/ us"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4427A}/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["from/ reigning"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3117L>', 'inflected', 'heb', 'מיום', '["mi./Yom","mi./yOm"]', '["from/ [the] day","from/ a day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5927H}/H9040/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["brought up/ I"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963A>/H9028', 'inflected', 'heb', 'בקולם', '["be./ko.La/m"]', '["<in>/ voice/ their","to/ voice/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9038\/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["on/ them","over/ them","to/ them"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7592}/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["who/ were asking"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4818}/H9023/[H4817]', 'inflected', 'heb', 'מֶרְכָּבָה', '["merkâbâh"]', '["in/ chariot[s]/ his"]', '["n-f"]', 'a chariot chariot. See also 1024.', 'feminine of 4817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6571A}/H9023/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["and/ among/ horsemen/ his"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7760L}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ to/ appoint [them]"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2790A}/[H2790]', 'inflected', 'heb', 'חָרַשׁ', '["chârash"]', '["and/ to/ plow"]', '["v"]', 'to scratch, i.e. (by implication) to engrave, plough; hence (from the use of tools) to fabricate (of any material); figuratively, to devise (in a bad sense); hence (from the idea of secrecy) to be silent, to let alone; hence (by implication) to be deaf (as an accompaniment of dumbness) × altogether, cease, conceal, be deaf, devise, ear, graven, imagine, leave off speaking, hold peace, plow(-er, man), be quiet, rest, practise secretly, keep silence, be silent, speak not a word, be still, hold tongue, worker.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2758}/H9023/[H2790]', 'inflected', 'heb', 'חָרִישׁ', '["chârîysh"]', '["plowing/ his"]', '["n-m"]', 'ploughing or its season earing (time), ground.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7114B}/[H7114]', 'inflected', 'heb', 'קָצַר', '["qâtsar"]', '["and/ to/ harvest"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7105A}/H9023/[H7114]', 'inflected', 'heb', 'קָצִיר', '["qâtsîyr"]', '["harvest/ his"]', '["n-m"]', 'severed, i.e. harvest (as reaped), the crop, the time, the reaper, or figuratively; also a limb (of a tree, or simply foliage) bough, branch, harvest (man).', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6213H}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ to/ make"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7548}/[H7547]', 'inflected', 'heb', 'רַקָּחָה', '["raqqâchâh"]', '["to/ perfumers"]', '["n-f"]', 'a female perfumer confectioner.', 'feminine of 7547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2879}/[H2876]', 'inflected', 'heb', 'טַבָּחָה', '["ṭabbâchâh"]', '["and/ to/ cooks"]', '["n-f"]', 'a female cook cook.', 'feminine of 2876;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0644}/[H644]', 'inflected', 'heb', 'אָפָה', '["ʼâphâh"]', '["and/ to/ bakers"]', '["v"]', 'to cook, especially to bake bake(-r, (-meats)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704G>/H9026', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["fields/ your"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3754>/H9026', 'opaque', 'heb', 'כֶּרֶם', '["kerem"]', '["vineyards/ your"]', '["n-m"]', 'a garden or vineyard vines, (increase of the) vineyard(-s), vintage. See also 1021.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2132H>/H9026', 'inflected', 'heb', 'וזיתיכם', '["ve./zei.tei./Khem"]', '["and/ olive groves/ your","and/ olive trees/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5650}/H9023/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["to/ servants/ his"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2233G}/H9026/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ seed<s>/ your"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3754>/H9026', 'inflected', 'heb', 'וכרמיכם', '["ve./khar.mei./Khem"]', '["and/ vineyards/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H5631>/H9023', 'inflected', 'heb', 'לסריסיו', '["le./sa.ri.Sa/v"]', '["to/ officials/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5650}/H9023/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["and/ <to>/ servants/ his","and/ to/ servants/ his"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8198>/H9026', 'opaque', 'heb', 'שִׁפְחָה', '["shiphchâh"]', '["female servants/ your"]', '["n-f"]', 'a female slave (as a member of the household) (bond-, hand-) maid(-en, -servant), wench, bondwoman, womanservant.', 'feminine from an unused root meaning to spread out (as a family; see 4940);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0970}/H9026/[H977]', 'inflected', 'heb', 'בָּחוּר', '["bâchûwr"]', '["young men/ your"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2543}/H9026/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["donkeys/ your"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4399}/H9023/[H4397]', 'inflected', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["for/ work/ his"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H6440I}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<from>/ <to>/ because of"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428G}/H9026/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["[was] king/ your","king/ your","kings/ your"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8199}/H9035/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["and/ he will judge/ us"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428G}/H9025/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["[is] king/ our","king/ our","kings/ our"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4421}/H9025/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["battles/ our"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1696G}/H9038/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ he spoke/ them","and/ you will speak/ them"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5892B}/H9023\/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["to/ own city/ his"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7027G}/[H6983]', 'lemma', 'heb', 'קִישׁ', '["Qîysh"]', '["Kish","[was] Kish"]', '["n-pr-m"]', 'Kish, the name of five Israelites Kish.', 'from 6983; a bow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0022G}/[H1]', 'lemma', 'heb', 'אֲבִיאֵל', '["ʼĂbîyʼêl"]', '["Abiel"]', '["n-pr-m"]', 'Abiel, the name of two Israelites Abiel.', 'from 1 and 410; father (i.e. possessor) of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6872C}/[H6887]', 'lemma', 'heb', 'צְרוֹר', '["tsᵉrôwr"]', '["Zeror"]', '["n-m"]', 'a parcel (as packed up); also a kernel or particle (as if a package) bag, × bendeth, bundle, least grain, small stone.', 'or (shorter) צְרֹר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1064}/[H1062]', 'lemma', 'heb', 'בְּכוֹרַת', '["Bᵉkôwrath"]', '["Becorath"]', '["n-pr-m"]', 'Bekorath, an Israelite Bechorath.', 'feminine of 1062; primogeniture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0647}/[H6315]', 'lemma', 'heb', 'אֲפִיחַ', '["ʼĂphîyach"]', '["Aphiah"]', '["n-pr-m"]', 'Aphiach, an Israelite Aphiah.', 'perhaps from 6315; breeze;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3227B}/[H3225]', 'lemma', 'heb', 'יְמִינִי', '["yᵉmîynîy"]', '["[the] Jaminite[s]","a Jaminite"]', '["a"]', 'right (on the) right (hand).', 'for 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7586G}/[H7592]', 'lemma', 'heb', 'שָׁאוּל', '["Shâʼûwl"]', '["Saul","[are] Saul","[is] Saul","[was] Saul"]', '["n-pr-m"]', 'Shaul, the name of an Edomite and two Israelites Saul, Shaul.', 'passive participle of 7592; asked;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7926}/H9023/[H7925]', 'inflected', 'heb', 'שְׁכֶם', '["shᵉkem"]', '["from/ shoulder/ his"]', '["n-m"]', 'the neck (between the shoulders) as the place of burdens; figuratively, the spur of a hill back, × consent, portion, shoulder.', 'from 7925;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7027G}/[H6983]', 'inflected', 'heb', 'קִישׁ', '["Qîysh"]', '["of/ Kish"]', '["n-pr-m"]', 'Kish, the name of five Israelites Kish.', 'from 6983; a bow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5288}/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["from/ the/ young men"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8031}/[H8027]', 'lemma', 'heb', 'שָׁלִשָׁה', '["Shâlishâh"]', '["Shalisha"]', '["n-pr-f"]', 'Shalishah, a place in Palestine Shalisha.', 'feminine from 8027; trebled land;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8171}/[H7776]', 'lemma', 'heb', 'שַׁעֲלִים', '["Shaʻălîym"]', '["Shaalim"]', '["n-pr-loc"]', 'Shaalim, a place in Palestine Shalim.', 'plural of 7776; foxes;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6689H}/[H6688]', 'lemma', 'heb', 'צוּף', '["Tsûwph"]', '["Zuph"]', '["n-pr-m n-pr-loc"]', 'Tsuph or Tsophai or Tsiph, the name of an Israelite and of a place in Palestine Zophai, Zuph.', 'or צוֹפַי; or צִיף; from 6688; honey-comb;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7586G}/[H7592]', 'inflected', 'heb', 'שָׁאוּל', '["Shâʼûwl"]', '["and/ Saul"]', '["n-pr-m"]', 'Shaul, the name of an Edomite and two Israelites Saul, Shaul.', 'passive participle of 7592; asked;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1672}/[H1672]', 'inflected', 'heb', 'דָּאַג', '["dâʼag"]', '["and/ he is anxious","and/ he will be anxious"]', '["v"]', 'be anxious be afraid (careful, sorry), sorrow, take thought.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870J}/H9025/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["journey/ our"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3627}/H9025/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["from/ bags/ our"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8670}/[H7788]', 'inflected', 'heb', 'תְּשׁוּרָה', '["tᵉshûwrâh"]', '["and/ [is] a gift"]', '["n-f"]', 'a gift present.', 'from 7788 in the sense of arrival;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027I}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["by/ hand/ my","in/ hand/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1980G}/H9043/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["when/ went/ he"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7203A}/[H7200]', 'inflected', 'heb', 'רֹאֶה', '["rôʼeh"]', '["[am] the/ seer","the/ seer"]', '["n-m"]', 'a seer (as often rendered); but also (abstractly) a vision vision.', 'active participle of 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697H}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["word/ your","words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4608}/[H5927]', 'inflected', 'heb', 'מַעֲלֶה', '["maʻăleh"]', '["at the/ ascent","at/ [the] ascent of","on/ [the] ascent of"]', '["n-m"]', 'an elevation, i.e. (concretely) acclivity or platform; abstractly (the relation or state) a rise or (figuratively) priority ascent, before, chiefest, cliff, that goeth up, going up, hill, mounting up, stairs.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1116>', 'inflected', 'heb', 'בבמות', '["ba./ba.Mah","ba./ba.Mot","ba./ba.mOt"]', '["[were] in the/ high place","at the/ high place","at the/ high places"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1116>/H9011', 'inflected', 'heb', 'הבמתה', '["ha./ba.Ma.ta/h"]', '["the/ high place/ towards"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7121G}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["the/ [one who] called","the/ [one who] summons","those/ [who] were invited","who/ calls","who/ summons"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1116>\', 'inflected', 'heb', 'הבמה ס', '["ha./ba.Mah"]', '["the/ high place"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0241I}/[H238]', 'lemma', 'heb', 'אֹזֶן', '["ʼôzen"]', '["[the] ear of","ears"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4886}/H9033/[H4886]', 'inflected', 'heb', 'מָשַׁח', '["mâshach"]', '["and/ they anointed/ him","and/ you will anoint/ him"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5057}/[H5046]', 'inflected', 'heb', 'נָגִיד', '["nâgîyd"]', '["<into>/ ruler","to/ [the] ruler of","to/ leader","to/ ruler"]', '["n-m"]', 'a commander (as occupying the front), civil, military or religious; generally (abstractly, plural), honorable themes captain, chief, excellent thing, (chief) governor, leader, noble, prince, (chief) ruler.', 'or נָגִד; from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1116>', 'inflected', 'heb', 'הבמות', '["Ha./ba.mot","ha./ba.Mah","ha./ba.Mot","ha./ba.mOt"]', '["[is] the/ high place","[was] the/ high place","the/ high place","the/ high places"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971H}/H9031/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ I will send away/ you"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0860}/[H386]', 'inflected', 'heb', 'אָתוֹן', '["ʼâthôwn"]', '["and/ to the/ she-asses"]', '["n-f"]', 'a female donkey (from its docility) (she) ass.', 'probably from the same as 386 (in the sense of patience);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0006}/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["the/ lost [one]","those/ [who] were lost","which/ were lost"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2532A}/[H2531]', 'lemma', 'heb', 'חֶמְדָּה', '["chemdâh"]', '["<the> desirable thing of","[the] desire of","[the] precious thing of","desire","preciousness","preciousness of"]', '["n-f"]', 'delight desire, goodly, pleasant, precious.', 'feminine of 2531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9021\/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["father/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6996A}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["from/ [the] small of"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4940}/H9020/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["and/ [is] clan?/ my"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3957>/H9011', 'opaque', 'heb', 'לִשְׁכָּה', '["lishkâh"]', '["[the] room/ towards"]', '["n-f"]', 'a room in a building (whether for storage, eating, or lodging) chamber, parlour. Compare 5393.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2876}/[H2873]', 'inflected', 'heb', 'טַבָּח', '["ṭabbâch"]', '["to the/ cook"]', '["n-m"]', 'properly, a butcher; hence, a lifeguardsman (because he was acting as an executioner); also a cook (usually slaughtering the animal for food) cook, guard.', 'from 2873;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4490}/[H4487]', 'inflected', 'heb', 'מָנָה', '["mânâh"]', '["the/ portion"]', '["n-f"]', 'properly, something weighed out, i.e. (generally) a division; specifically (of food) a ration; also a lot such things as belonged, part, portion.', 'from 4487;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5921A}/H9034/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["and/ the/ on/ it"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/<H1116>', 'inflected', 'heb', 'מהבמה', '["me./ha./ba.Mah"]', '["from/ the/ high place"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8085I}/H9031/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["so/ I may make hear/ you"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6378}/[H6379]', 'lemma', 'heb', 'פַּךְ', '["pak"]', '["[the] flask of"]', '["n-m"]', 'a flask (from which a liquid may flow) box, vial.', 'from 6379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4886}/H9031/[H4886]', 'inflected', 'heb', 'מָשַׁח', '["mâshach"]', '["I anoint/ you","I anointed/ you","he has anointed/ you"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3467}/H9033/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["deliverer/ its","he delivered/ him","you deliver/ him"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0226H}/[H225]', 'inflected', 'heb', 'אוֹת', '["ʼôwth"]', '["[will be] the/ sign"]', '["n-f"]', 'a signal (literally or figuratively), as a flag, beacon, monument, omen, prodigy, evidence, etc. mark, miracle, (en-) sign, token.', 'probably from 225 (in the sense of appearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5978}/H9030/[H5973]', 'inflected', 'heb', 'עִמָּד', '["ʻimmâd"]', '["from/ with/ me"]', '["prep"]', 'along with against, by, from, + me, + mine, of, + that I take, unto, upon, with(-in.)', 'prolonged for 5973;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6766}/[H6738]', 'inflected', 'heb', 'צֶלְצַח', '["Tseltsach"]', '["at/ Zelzah"]', '["n-pr-loc"]', 'Tseltsach, a place in Palestine Zelzah.', 'from 6738 and 6703; clear shade;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1245}/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["to/ seek","to/ seek [him]"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5203}/[H5203]', 'lemma', 'heb', 'נָטַשׁ', '["nâṭash"]', '["I have abandoned","[they were] spread out","abandon","drawn","have you left","he has abandoned","he will abandon","he will leave","it will be forsaken","she has been abandoned","they are loose","they were spread out","you abandoned","you forsake","you have abandoned","you reject"]', '["v"]', 'properly, to pound, i.e. smite; by implication (as if beating out, and thus expanding) to disperse; also, to thrust off, down, out or upon (inclusively, reject, let alone, permit, remit, etc.) cast off, drawn, let fall, forsake, join (battle), leave (off), lie still, loose, spread (self) abroad, stretch out, suffer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8396H}/[H8406]', 'lemma', 'heb', 'תָּבוֹר', '["Tâbôwr"]', '["Tabor"]', '["n-pr"]', 'Tabor, a mountain in Palestine, also a city adjacent Tabor.', 'from a root corresponding to 8406; broken region;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5035A}/[H5034]', 'lemma', 'heb', 'נֶבֶל', '["nebel"]', '["a jar of","a skin of","jars of","wineskin"]', '["n-m"]', 'a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol.', 'or נֵבֶל; from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7965K}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["for/ [the] peace of","to/ [the] welfare of","to/ welfare"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0430I}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["<the>/ God"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0935G}/H9041/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ coming/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6440G}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ <to>/ before/ them","and/ [will be] <to>/ before/ them"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5035B}/[H5034]', 'lemma', 'heb', 'נֶבֶל', '["nebel"]', '["a lyre","lyre","lyres"]', '["n-m"]', 'a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol.', 'or נֵבֶל; from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8596}/[H8608]', 'inflected', 'heb', 'תֹּף', '["tôph"]', '["and/ tambourine"]', '["n-m"]', 'a tambourine tabret, timbrel.', 'from 8608 contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2485}/[H2490]', 'inflected', 'heb', 'חָלִיל', '["châlîyl"]', '["and/ flute"]', '["n-m"]', 'a flute (as perforated) pipe.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3658>', 'inflected', 'heb', 'וכנרות', '["ve./khi.Nor","ve./khi.no.Rot"]', '["and/ harp","and/ harps"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3176G}/[H3176]', 'lemma', 'heb', 'יָחַל', '["yâchal"]', '["I am waiting","I have waited","I waited","I will wait","it waits","may you wait","waiting","will I wait"]', '["v"]', 'to wait; by implication, to be patient, hope (cause to, have, make to) hope, be pained, stay, tarry, trust, wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6437G}/H9043/[H6437]', 'inflected', 'heb', 'פָּנָה', '["pânâh"]', '["when/ turned/ he"]', '["v"]', 'to turn; by implication, to face, i.e. appear, look, etc. appear, at (even-) tide, behold, cast out, come on, × corner, dawning, empty, go away, lie, look, mark, pass away, prepare, regard, (have) respect (to), (re-) turn (aside, away, back, face, self), × right (early).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0865}/[H853]', 'inflected', 'heb', 'אֶתְמוֹל', '["ʼethmôwl"]', '["from/ yesterday"]', '["adv"]', 'heretofore; definitely yesterday before (that) time, heretofore, of late (old), times past, yester(day).', 'or אִתְמוֹל; or אֶתְמוּל; probably from 853 or 854 and 4136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5030}/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["among the/ prophets","by <the>/ prophets","by the/ prophets"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5012}/[H5012]', 'inflected', 'heb', 'נָבָא', '["nâbâʼ"]', '["from/ prophesying"]', '["v"]', 'to prophesy, i.e. speak (or sing) by inspiration (in prediction or simple discourse) prophesy(-ing), make self a prophet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4410}/[H4427]', 'inflected', 'heb', 'מְלוּכָה', '["mᵉlûwkâh"]', '["<the>/ royalty","the/ kingship"]', '["n-f"]', 'something ruled, i.e. a realm kingsom, king''s, × royal.', 'feminine passive participle of 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8050G}\/[H8085]', 'inflected', 'heb', 'שְׁמוּאֵל', '["Shᵉmûwʼêl"]', '["Samuel"]', '["n-pr-m"]', 'Shemuël, the name of three Israelites Samuel, Shemuel.', 'from the passive participle of 8085 and 410; heard of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3905}/[H3905]', 'inflected', 'heb', 'לָחַץ', '["lâchats"]', '["that/ were oppressing"]', '["v"]', 'properly, to press, i.e. (figuratively) to distress afflict, crush, force, hold fast, oppress(-or), thrust self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451C}/H9026/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["calamities/ your"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6869B}/H9026/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["and/ troubles/ your"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0505H}/H9026/[H504]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["and/ to/ families/ your"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4309}/[H4305]', 'inflected', 'heb', 'מַטְרִי', '["Maṭrîy"]', '["<the>/ Matri"]', '["a"]', 'Matri, an Israelite Matri.', 'from 4305; rainy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1245}/H9033/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["and/ I sought/ him","and/ he sought/ him","and/ they sought/ him"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0376G>\', 'opaque', 'heb', 'אִישׁ', '["ʼîysh"]', '["[the] man","a man"]', '["n-m"]', 'a man as an individual or a male person; often used as an adjunct to a more definite term (and in such cases frequently not expressed in translation) also, another, any (man), a certain, champion, consent, each, every (one), fellow, (foot-, husband-) man, (good-, great, mighty) man, he, high (degree), him (that is), husband, man(-kind), none, one, people, person, steward, what (man) soever, whoso(-ever), worthy. Compare 802.', 'contracted for 582 (or perhaps rather from an unused root meaning to be extant);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1361}/[H1361]', 'inflected', 'heb', 'גָּבַהּ', '["gâbahh"]', '["and/ he was exalted","and/ he was tall","and/ he will be exalted","and/ it has been haughty","and/ it was high","and/ it was lofty","and/ they have become exalted","and/ they were haughty"]', '["v"]', 'to soar, i.e. be lofty; figuratively, to be haughty exalt, be haughty, be (make) high(-er), lift up, mount up, be proud, raise up great height, upward.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7200G}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["¿/ do you see","¿/ have you seen","¿/ seeing"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4428G}\/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["O/ king","the/ king","the/ kings"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3820A}/H9028/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["<in>/ heart/ their","[is] in/ heart/ their","by/ heart/ their","in/ heart/ their","in/ own heart/ their","with/ heart/ their"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0959}/H9033/[H959]', 'inflected', 'heb', 'בָּזָה', '["bâzâh"]', '["and/ he despised/ him","and/ they despised/ him"]', '["v"]', 'to disesteem despise, disdain, contemn(-ptible), think to scorn, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2790B}\/[H2790]', 'inflected', 'heb', 'חָרַשׁ', '["chârash"]', '["like/ [one who] kept silent"]', '["v"]', 'to scratch, i.e. (by implication) to engrave, plough; hence (from the use of tools) to fabricate (of any material); figuratively, to devise (in a bad sense); hence (from the idea of secrecy) to be silent, to let alone; hence (by implication) to be deaf (as an accompaniment of dumbness) × altogether, cease, conceal, be deaf, devise, ear, graven, imagine, leave off speaking, hold peace, plow(-er, man), be quiet, rest, practise secretly, keep silence, be silent, speak not a word, be still, hold tongue, worker.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5176G}/[H5175]', 'lemma', 'heb', 'נָחָשׁ', '["Nâchâsh"]', '["Nahash"]', '["n-pr-m"]', 'Nachash, the name of two persons apparently non-Israelite Nahash.', 'the same as 5175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5984H}/[H5983]', 'inflected', 'heb', 'עַמּוֹנִי', '["ʻAmmôwnîy"]', '["the/ Ammonite","the/ Ammonite [woman]","the/ Ammonite[s]","the/ Ammonites"]', '["a"]', 'an Ammonite or (the adjective) Ammonitish Ammonite(-s).', 'patronymically from 5983;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5647G}/H9031/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ we will serve/ you","so/ we may serve/ you"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5365}/[H5365]', 'inflected', 'heb', 'נָקַר', '["nâqar"]', '["by/ gouging out"]', '["v"]', 'to bore (penetrate, quarry) dig, pick out, pierce, put (thrust) out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760H}/H9034/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ I will make/ it","and/ I will put/ it"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7971G}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ [one who] spreads","and/ [who] sends","and/ he may send","and/ he sent","and/ let us send","and/ send","and/ send [him]","and/ sending","and/ they were sent","so/ I may send","so/ let me send","so/ let us send"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697K}/[H1696]', 'lemma', 'heb', 'דָּבָר', '["dâbâr"]', '["[the] matter of","[the] matters of","[the] words of","a matter","a thing","matters of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5408}/H9033/[H5408]', 'inflected', 'heb', 'נָתַח', '["nâthach"]', '["and/ he cut in pieces/ it"]', '["v"]', 'to dismember cut (in pieces), divide, hew in pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1241}/H9023/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["to/ ox[en]/ his"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6343}/[H6342]', 'lemma', 'heb', 'פַּחַד', '["pachad"]', '["[the] dread of","[the] fear of","[was] a fear","a fear","dread","dread of","dread<s>","fear","terror"]', '["n-m"]', 'a (sudden) alarm (properly, the object feared, by implication, the feeling) dread(-ful), fear, (thing) great (fear, -ly feared), terror.', 'from 6342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0966H}/[H965]', 'inflected', 'heb', 'בֶּזֶק', '["Bezeq"]', '["at/ Bezek"]', '["n-pr-loc"]', 'Bezek, a place in Palestine Bezek.', 'from 965; lightning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H4397G>', 'inflected', 'heb', 'למלאכים', '["la./mal.''a.Khim","le./mal.''a.Khei"]', '["to the/ messengers","to/ [the] messengers of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8668G}/[H7768]', 'lemma', 'heb', 'תְּשׁוּעָה', '["tᵉshûwʻâh"]', '["[the] deliverance of","[the] salvation of","a deliverance","a salvation of","deliverance","salvation"]', '["n-f"]', 'rescue (literal or figurative, persons, national or spiritual) deliverance, help, safety, salvation, victory.', 'or תְּשֻׁעָה; from 7768 in the sense of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869I}/H9026\/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2527}/[H2552]', 'lemma', 'heb', 'חֹם', '["chôm"]', '["[the] heat of","heat"]', '["n-m"]', 'heat heat, to be hot (warm).', 'from 2552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2318}/[H2318]', 'inflected', 'heb', 'חָדַשׁ', '["châdash"]', '["and/ you may renew","so/ we may renew"]', '["v"]', 'to be new; causatively, to rebuild renew, repair.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3966}\/[H181]', 'inflected', 'heb', 'מְאֹד', '["mᵉʼôd"]', '["exceedingly","muchness","very"]', '["a"]', 'properly, vehemence, i.e. (with or without preposition) vehemently; by implication, wholly, speedily, etc. (often with other words as an intensive or superlative; especially when repeated) diligently, especially, exceeding(-ly), far, fast, good, great(-ly), × louder and louder, might(-ily, -y), (so) much, quickly, (so) sore, utterly, very ( much, sore), well.', 'from the same as 181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7867}/[H7867]', 'inflected', 'heb', 'שִׂיב', '["sîyb"]', '["and/ I am gray haired"]', '["v"]', 'properly, to become aged, i.e. (by implication) to grow gray (be) grayheaded.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121A}/H9020/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ [is] son/ my","and/ son/ my","and/ sons/ my"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2009}/H9048/[H2005]', 'inflected', 'heb', 'הִנֵּה', '["hinnêh"]', '["here/ they","there/ they"]', '["dp"]', 'lo! behold, lo, see.', 'prolongation for 2005;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5271A}/H9020/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["since/ youth<s>/ my"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4899}/H9023/[H4886]', 'inflected', 'heb', 'מָשִׁיחַ', '["mâshîyach"]', '["anointed/ his"]', '["n-m"]', 'anointed; usually a consecrated person (as a king, priest, or saint); specifically, the Messiah anointed, Messiah.', 'from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7533}/[H7533]', 'lemma', 'heb', 'רָצַץ', '["râtsats"]', '["[is] crushed of","crushed","crushed [people]","have I crushed","he has crushed","he will be crushed","you crushed","you were crushed"]', '["v"]', 'to crack in pieces, literally or figuratively break, bruise, crush, discourage, oppress, struggle together.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3027G}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ from/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5956}/[H5956]', 'inflected', 'heb', 'עָלַם', '["ʻâlam"]', '["and/ [one who] hides","so/ I may hide"]', '["v"]', 'to veil from sight, i.e. conceal (literally or figuratively) × any ways, blind, dissembler, hide (self), secret (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725H}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I will restore","and/ it may return","and/ we may return","so/ I may restore [it]","so/ let me return","so/ let us return","so/ may it come back","so/ they may be restored"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6231}/H9035/[H6229]', 'inflected', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["you have oppressed/ us"]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7533}/H9035/[H7533]', 'inflected', 'heb', 'רָצַץ', '["râtsats"]', '["you have crushed/ us"]', '["v"]', 'to crack in pieces, literally or figuratively break, bruise, crush, discourage, oppress, struggle together.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5707}\/[H5749]', 'inflected', 'heb', 'עֵד', '["ʻêd"]', '["[he is] a witness"]', '["n-m"]', 'concretely, a witness; abstractly, testimony; specifically, a recorder, i.e. prince witness.', 'contracted from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3427}/H9038/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ I will cause to dwell/ them","and/ he has made sit/ them","and/ they caused to dwell/ them","and/ they had left behind/ them"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0917H}/[H5658]', 'lemma', 'heb', 'בְּדָן', '["Bᵉdân"]', '["Bedan"]', '["n-pr-m"]', 'Bedan, the name of two Israelites Bedan.', 'probably shortened for 5658; servile;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0001G}/H9026/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ on/ ancestors/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451I}/H9026/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["evil/ your","wicked deeds/ your","wickedness/ your"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403B}/H9025/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["[is] sin/ our","sins/ our"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H8414>', 'inflected', 'heb', 'התהו', '["ha./To.hu"]', '["<the>/ emptiness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3276}/[H3276]', 'lemma', 'heb', 'יָעַל', '["yâʻal"]', '["a [thing that] profits","anyone profits","does it profit","it profits","they benefit","they confer profit","they have profited","they profit","they profited","they will benefit","they will confer profit","to confer profit","to profit","will I profit","will we gain"]', '["v"]', 'properly, to ascend; figuratively, to be valuable (objectively; useful, subjectively; benefited) × at all, set forward, can do good, (be, have) profit, (able).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2308}/[H2308]', 'inflected', 'heb', 'חָדַל', '["châdal"]', '["from/ ceasing"]', '["v"]', 'properly, to be flabby, i.e. (by implication) desist; (figuratively) be lacking or idle cease, end, fall, forbear, forsake, leave (off), let alone, rest, be unoccupied, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870G}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["<in> the/ way","<in>/ [the] way","<in>/ [the] way of","[are] in/ [the] path of","in the/ way","in/ [the] manner of","in/ [the] way","in/ [the] way of","in/ [the] ways of","in/ a way","to/ a way"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7200H}/[H7200]', 'lemma', 'heb', 'רָאָה', '["râʼâh"]', '["[am] seeing","consider","it has seen","see","they saw","they will see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5595}\/[H5595]', 'inflected', 'heb', 'סָפָה', '["çâphâh"]', '["it will sweep away","you will be swept away"]', '["v"]', 'properly, to scrape (literally, to shave; but usually figuratively) together (i.e. to accumulate or increase) or away (i.e. to scatter, remove, or ruin; intransitively, to perish) add, augment, consume, destroy, heap, join, perish, put.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4427A}/H9043/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["when/ became king/ he"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4363}/[H3647]', 'inflected', 'heb', 'מִכְמָס', '["Mikmâç"]', '["at/ Micmash","in/ Micmash"]', '["n-pr-loc"]', 'Mikmas or Mikmash, a place in Palestine Mikmas, Mikmash.', '(Ezra 2:2 or מִכְמָשׁ; or מִכְמַשׁ; (Nehemiah 11:31), from 3647; hidden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3129N}/[H3083]', 'lemma', 'heb', 'יוֹנָתָן', '["Yôwnâthân"]', '["Jonathan","O Jonathan","[were] Jonathan"]', '["n-pr-m"]', 'Jonathan, the name of ten Israelites Jonathan.', 'a form of 3083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1387G}/[H1375]', 'inflected', 'heb', 'גֶּבַע', '["Gebaʻ"]', '["[was] at/ Geba","in/ Geba"]', '["n-pr-loc"]', 'Geba, a place in Palestine Gaba, Geba, Gibeah.', 'from the same as 1375, a hillock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5971K}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ [the] people of","and/ a people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H2336>', 'inflected', 'heb', 'ובחוחים', '["u./va./cha.va.Chim","u./ve./Cho.ach"]', '["and/ in <the>/ thickets","and/ with/ a hook"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H5553H>', 'inflected', 'heb', 'ובסלעים', '["u./va./se.la.''Im"]', '["and/ in <the>/ cliffs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6877}/[H6873]', 'inflected', 'heb', 'צְרִיחַ', '["tsᵉrîyach"]', '["and/ in <the>/ underground chambers"]', '["n-m"]', 'a citadel high place, hold.', 'from 6873 in the sense of clearness of vision;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0953A}/[H952]', 'inflected', 'heb', 'בּוֹר', '["bôwr"]', '["and/ in <the>/ cisterns","and/ in the/ cistern"]', '["n-m"]', 'a pit hole (especially one used as a cistern or a prison) cistern, dungeon, fountain, pit, well.', 'from 952 (in the sense of 877);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5680}/[H5677]', 'inflected', 'heb', 'עִבְרִי', '["ʻIbrîy"]', '["and/ Hebrews"]', '["n-pr"]', 'an Eberite (i.e. Hebrew) or descendant of Eber Hebrew(-ess, woman).', 'patronymic from 5677;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1568G}/[H1567]', 'inflected', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["and/ Gilead"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5066H}/[H5066]', 'lemma', 'heb', 'נָגַשׁ', '["nâgash"]', '["[is being] brought near","[they were] bringing","[were] bringing","[you are] bringing near","bring near","bringing near","did you bring near","let him bring near","let them bring [them] near","they brought","they were brought near","you bring near"]', '["v"]', 'to be or come (causatively, bring) near (for any purpose); euphemistically, to lie with a woman; as an enemy, to attack; religious to worship; causatively, to present; figuratively, to adduce an argument; by reversal, to stand back (make to) approach (nigh), bring (forth, hither, near), (cause to) come (hither, near, nigh), give place, go hard (up), (be, draw, go) near (nigh), offer, overtake, present, put, stand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1288}/H9033/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["to/ bless/ him"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4363}/[H3647]', 'lemma', 'heb', 'מִכְמָס', '["Mikmâç"]', '["Micmash"]', '["n-pr-loc"]', 'Mikmas or Mikmash, a place in Palestine Mikmas, Mikmash.', '(Ezra 2:2 or מִכְמָשׁ; or מִכְמַשׁ; (Nehemiah 11:31), from 3647; hidden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440L}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ [the] face of"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2470B}/[H2342]', 'lemma', 'heb', 'חָלָה', '["châlâh"]', '["I have entreated","entreat","he entreated","they entreat","they will entreat","we have entreated"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5930A}\/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["the/ burnt offering"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4467}/H9021/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["kingdom/ your"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3129N}/[H3083]', 'inflected', 'heb', 'יוֹנָתָן', '["Yôwnâthân"]', '["and/ Jonathan"]', '["n-pr-m"]', 'Jonathan, the name of ten Israelites Jonathan.', 'a form of 3083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4264}/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["from/ [the] camp of","from/ [the] camps of"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6084G}/[H6082]', 'lemma', 'heb', 'עׇפְרָה', '["ʻOphrâh"]', '["Ophrah"]', '["n-pr-m n-pr-loc"]', 'Ophrah, the name of an Israelite and of two places in Palestine Ophrah.', 'feminine of 6082; female fawn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7777A}/[H7776]', 'lemma', 'heb', 'שׁוּעָל', '["Shûwʻâl"]', '["Shual"]', '["n-pr-m n-pr-loc"]', 'Shual, the name of an Israelite and of a place in Palestine Shual.', 'the same as 7776;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1516I}/[H1466]', 'lemma', 'heb', 'גַּיְא', '["gayʼ"]', '["[the] valley of"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6650H}/[H6641]', 'inflected', 'heb', 'צְבֹעִים', '["Tsᵉbôʻîym"]', '["<the>/ Zeboim"]', '["n-pr-loc"]', 'Tseboim, a place in Palestine Zeboim.', 'plural of 6641; hyenas;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4057B}/H9011\/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["the/ wilderness/ towards"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2796}/[H2790]', 'inflected', 'heb', 'חָרָשׁ', '["chârâsh"]', '["and/ a craftsman","and/ craftsmen","and/ craftsmen of"]', '["n-m"]', 'a fabricator or any material artificer, ( ) carpenter, craftsman, engraver, maker, mason, skilful, ( ) smith, worker, workman, such as wrought.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2595}/[H2583]', 'lemma', 'heb', 'חֲנִית', '["chănîyth"]', '["[are] a spear","[is] [the] spear of","[is] a spear","[the] spear of","a spear","spear[s]"]', '["n-f"]', 'a lance (for thrusting, like pitching a tent) javelin, spear.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3913}/[H3913]', 'inflected', 'heb', 'לָטַשׁ', '["lâṭash"]', '["to/ sharpen"]', '["v"]', 'properly, to hammer out (an edge), i.e. to sharpen instructer, sharp(-en), whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4281}/H9023/[H2790]', 'inflected', 'heb', 'מַחֲרֵשָׁה', '["machărêshâh"]', '["plowshare/ his"]', '["n-f"]', 'probably a pick-axe mattock.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0855>/H9023', 'opaque', 'heb', 'אֵת', '["ʼêth"]', '["mattock/ his"]', '["n-m"]', 'a hoe or other digging implement coulter, plowshare.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7134}/H9023/[H6923]', 'inflected', 'heb', 'קַרְדֹּם', '["qardôm"]', '["axe/ his"]', '["n-m"]', 'an axe ax.', 'perhaps from 6923 in the sense of striking upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6477}/[H6484]', 'inflected', 'heb', 'פְּצִירָה', '["pᵉtsîyrâh"]', '["the/ charge"]', '["n-f"]', 'bluntness file.', 'from 6484;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310L}/[H6284]', 'lemma', 'heb', 'פֶּה', '["peh"]', '["a mouth of","two thirds of a shekel"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4281}/[H2790]', 'inflected', 'heb', 'מַחֲרֵשָׁה', '["machărêshâh"]', '["for the/ plowshares"]', '["n-f"]', 'probably a pick-axe mattock.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0855>', 'inflected', 'heb', 'ולאתים', '["ve./La./''e.Tim"]', '["and/ for the/ mattocks"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7969}/[H7969]', 'inflected', 'heb', 'שָׁלוֹשׁ', '["shâlôwsh"]', '["and/ for/ three"]', '["n"]', 'three; occasionally (ordinal) third, or (multiple) thrice fork, often(-times), third, thir(-teen, -teenth), three, thrice. Compare 7991.', 'or שָׁלֹשׁ; masculine שְׁלוֹשָׁה; or שְׁלֹשָׁה; a primitive number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7053>', 'opaque', 'heb', 'קִלְּשׁוֹן', '["qillᵉshôwn"]', '["fork"]', '["n-m"]', 'a prong, i.e. hay-fork fork.', 'from an unused root meaning to prick;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/H9009/{H7134}/[H6923]', 'inflected', 'heb', 'קַרְדֹּם', '["qardôm"]', '["and/ for/ the/ axes"]', '["n-m"]', 'an axe ax.', 'perhaps from 6923 in the sense of striking upon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5324}/[H5324]', 'inflected', 'heb', 'נָצַב', '["nâtsab"]', '["and/ to/ make straight"]', '["v"]', 'to station, in various applications (literally or figuratively) appointed, deputy, erect, establish, × Huzzah (by mistake for a proper name), lay, officer, pillar, present, rear up, set (over, up), settle, sharpen, establish, (make to) stand(-ing, still, up, upright), best state.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1861A>', 'inflected', 'heb', 'הדרבן', '["ha./da.re.Van"]', '["the/ goad[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2595}/[H2583]', 'inflected', 'heb', 'חֲנִית', '["chănîyth"]', '["and/ a spear","and/ spear"]', '["n-f"]', 'a lance (for thrusting, like pitching a tent) javelin, spear.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7586G}/[H7592]', 'inflected', 'heb', 'שָׁאוּל', '["Shâʼûwl"]', '["[belonged] to/ Saul","of/ Saul","to/ Saul"]', '["n-pr-m"]', 'Shaul, the name of an Edomite and two Israelites Saul, Shaul.', 'passive participle of 7592; asked;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3129N}/[H3083]', 'inflected', 'heb', 'יוֹנָתָן', '["Yôwnâthân"]', '["and/ to/ Jonathan"]', '["n-pr-m"]', 'Jonathan, the name of ten Israelites Jonathan.', 'a form of 3083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4363}\/[H3647]', 'inflected', 'heb', 'מִכְמָס', '["Mikmâç"]', '["Micmash"]', '["n-pr-loc"]', 'Mikmas or Mikmash, a place in Palestine Mikmas, Mikmash.', '(Ezra 2:2 or מִכְמָשׁ; or מִכְמַשׁ; (Nehemiah 11:31), from 3647; hidden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4051}/[H4048]', 'inflected', 'heb', 'מִגְרוֹן', '["Migrôwn"]', '["[is] in/ Migron","in/ Migron"]', '["n-pr-loc"]', 'Migron, a place in Palestine Migron.', 'from 4048; precipice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0281O}/[H251]', 'inflected', 'heb', 'אֲחִיָּה', '["ʼĂchîyâh"]', '["and/ Ahijah"]', '["n-pr-m"]', 'Achijah, the name of nine Israelites Ahiah, Ahijah.', 'or (prolonged) אֲחִיָּהוּ ; from 251 and 3050; brother (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0285G}/[H251]', 'lemma', 'heb', 'אֲחִיטוּב', '["ʼĂchîyṭûwb"]', '["Ahitub"]', '["n-pr-m"]', 'Achitub, the name of several priests Ahitub.', 'from 251 and 2898; brother of goodness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0996H}/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["and/ [were] between","and/ between"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8127I}/[H8150]', 'lemma', 'heb', 'שֵׁן', '["shên"]', '["[the] tooth of"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5676G}/[H5674]', 'inflected', 'heb', 'עֵבֶר', '["ʻêber"]', '["from/ the/ other side"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8127I}/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["and/ [the] tooth of"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0949}/[H948]', 'lemma', 'heb', 'בּוֹצֵץ', '["Bôwtsêts"]', '["[was] Bozez"]', '["n-pr-loc"]', 'Botsets, a rock near Michmash Bozez.', 'from the same as 948; shining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5573}/[H5572]', 'lemma', 'heb', 'סֶנֶה', '["Çeneh"]', '["[was] Seneh"]', '["n-pr-loc"]', 'Seneh, a crag in Palestine Seneh.', 'the same as 5572; thorn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8127I}/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["the/ tooth"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1387G}\/[H1375]', 'inflected', 'heb', 'גֶּבַע', '["Gebaʻ"]', '["Geba"]', '["n-pr-loc"]', 'Geba, a place in Palestine Gaba, Geba, Gibeah.', 'from the same as 1375, a hillock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3083H}/[H3068]', 'lemma', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4622}/[H6113]', 'lemma', 'heb', 'מַעְצוֹר', '["maʻtsôwr"]', '["a limitation"]', '["n-m"]', 'objectively, a hindrance restraint.', 'from 6113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7227A}/[H7231]', 'inflected', 'heb', 'רַב', '["rab"]', '["<in>/ many [people]","among the/ many [people]","by/ many","over the/ many [people]","with/ greatness of"]', '["a n-m"]', 'abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent).', 'by contracted from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4592}/[H4591]', 'inflected', 'heb', 'מְעַט', '["mᵉʻaṭ"]', '["by/ few","with/ fewness of"]', '["n-m"]', 'a little or few (often adverbial or comparative) almost (some, very) few(-er, -est), lightly, little (while), (very) small (matter, thing), some, soon, × very.', 'or מְעָט; from 4591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3824}/H9021\/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["according to/ heart/ your"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1540H}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["and/ I will uncover","and/ he has revealed himself","and/ it is revealed","and/ it will be revealed","and/ it will reveal","and/ they revealed themselves","and/ we will reveal ourselves"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5060}/H9045/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["reach/ we"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478I}/H9035/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["in place/ our"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2356}/[H2352]', 'inflected', 'heb', 'חוֹר', '["chôwr"]', '["the/ hole","the/ holes"]', '["n-m"]', 'a cavity, socket, den cave, hole.', 'or (shortened) חֹר; the same as 2352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4675}/[H4673]', 'inflected', 'heb', 'מַצָּבָה', '["matstsâbâh"]', '["the/ garrison"]', '["n-f"]', 'a military guard army, garrison.', 'or מִצָּבָה; feminine of 4673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697I}\/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["something"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5375W}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ [the] bearer of"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6242}/[H6235]', 'inflected', 'heb', 'עֶשְׂרִים', '["ʻesrîym"]', '["about/ twenty"]', '["n"]', 'twenty; also (ordinal) twentieth (six-) score, twenty(-ieth).', 'from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9003/{H2677}/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["about/ in/ half of"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4618}/[H6031]', 'lemma', 'heb', 'מַעֲנָה', '["maʻănâh"]', '["a furrow"]', '["n-f"]', 'a furrow acre, furrow.', 'from 6031, in the sense of depression or tilling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4673}/[H5324]', 'inflected', 'heb', 'מַצָּב', '["matstsâb"]', '["the/ garrison"]', '["n-m"]', 'a fixed spot; figuratively, an office, a military post garrison, station, place where...stood.', 'from 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7843}/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["and/ the/ destroyer"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2731}/[H2730]', 'inflected', 'heb', 'חֲרָדָה', '["chărâdâh"]', '["<into>/ a trembling of","<into>/ trembling"]', '["n-f"]', 'fear, anxiety care, × exceedingly, fear, quaking, trembling.', 'feminine of 2730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6822}/[H6822]', 'inflected', 'heb', 'צָפָה', '["tsâphâh"]', '["the/ watchman","the/ watchmen","who/ kept watch"]', '["v"]', 'properly, to lean forward, i.e. to peer into the distance; by implication, to observe, await behold, espy, look up (well), wait for, (keep the) watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1988}\/[H1973]', 'inflected', 'heb', 'הֲלֹם', '["hălôm"]', '["and/ here"]', '["adv"]', 'hither here, hither(-(to)), thither.', 'from the article (see 1973);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0281O}/[H251]', 'inflected', 'heb', 'אֲחִיָּה', '["ʼĂchîyâh"]', '["to/ Ahijah"]', '["n-pr-m"]', 'Achijah, the name of nine Israelites Ahiah, Ahijah.', 'or (prolonged) אֲחִיָּהוּ ; from 251 and 3050; brother (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1995A}/[H1993]', 'inflected', 'heb', 'הָמוֹן', '["hâmôwn"]', '["and/ the/ tumult"]', '["n-m"]', 'a noise, tumult, crowd; also disquietude, wealth abundance, company, many, multitude, multiply, noise, riches, rumbling, sounding, store, tumult.', 'or הָמֹן; (Ezekiel 5:7), from 1993;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7227A}\/[H7231]', 'inflected', 'heb', 'רַב', '["rab"]', '["and/ great"]', '["a n-m"]', 'abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent).', 'by contracted from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5680}/[H5677]', 'inflected', 'heb', 'עִבְרִי', '["ʻIbrîy"]', '["and/ <the>/ Hebrew [fem]","and/ the/ Hebrews"]', '["n-pr"]', 'an Eberite (i.e. Hebrew) or descendant of Eber Hebrew(-ess, woman).', 'patronymic from 5677;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6430G}/[H6429]', 'inflected', 'heb', 'פְּלִשְׁתִּי', '["Pᵉlishtîy"]', '["[belonged] to the/ Philistines","to the/ Philistines"]', '["a"]', 'a Pelishtite or inhabitant of Pelesheth Philistine.', 'patrial from 6429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0865}/[H853]', 'inflected', 'heb', 'אֶתְמוֹל', '["ʼethmôwl"]', '["as/ yesterday"]', '["adv"]', 'heretofore; definitely yesterday before (that) time, heretofore, of late (old), times past, yester(day).', 'or אִתְמוֹל; or אֶתְמוּל; probably from 853 or 854 and 4136;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2244}/[H2245]', 'inflected', 'heb', 'חָבָא', '["châbâʼ"]', '["who/ had hidden themselves"]', '["v"]', 'to secrete × held, hide (self), do secretly.', 'a primitive root (compare 2245);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0422}/[H422]', 'inflected', 'heb', 'אָלָה', '["ʼâlâh"]', '["and/ he had put under oath"]', '["v"]', 'properly, to adjure, i.e. (usually in a bad sense) imprecate adjure, curse, swear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5358}/[H5358]', 'inflected', 'heb', 'נָקַם', '["nâqam"]', '["and/ I will avenge","and/ I will avenge myself","and/ they avenged themselves","and/ they have avenged themselves"]', '["v"]', 'to grudge, i.e. avenge or punish avenge(-r, self), punish, revenge (self), × surely, take vengeance.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0341}/H9020/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["from/ enemies/ my","from/ enemy/ my","more than/ enemies/ my"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2938}/[H2938]', 'lemma', 'heb', 'טָעַם', '["ṭâʻam"]', '["I tasted","I will taste","certainly <to taste>","it tasted","it tastes","she perceives","taste","they taste","will he taste"]', '["v"]', 'to taste; figuratively, to perceive × but, perceive, taste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899G}\/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["food"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3293B>', 'inflected', 'heb', 'ביער', '["va/i.Ya.''ar"]', '["in the/ forest"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7704B>', 'inflected', 'heb', 'השדה', '["ha./sa.Deh"]', '["the/ field"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3293B>', 'inflected', 'heb', 'היער', '["hai./Ya.''ar"]', '["the/ forest"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1982}/[H1980]', 'lemma', 'heb', 'הֵלֶךְ', '["hêlek"]', '["a flowing of","a traveler"]', '["n-m"]', 'properly, a journey, i.e. (by implication) a wayfarer; also a flowing × dropped, traveller.', 'from 1980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7650}/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["when/ made to swear an oath"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3295}/[H3293]', 'inflected', 'heb', 'יַעֲרָה', '["yaʻărâh"]', '["in/ [the] honeycomb of"]', '["n-f"]', '(honey-) comb, forest.', 'feminine of 3293, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5971A}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["from/ the/ people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7998}/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["any of/ [the] plunder of","from/ [the] booty of"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4363}/[H3647]', 'inflected', 'heb', 'מִכְמָס', '["Mikmâç"]', '["from/ Micmash"]', '["n-pr-loc"]', 'Mikmas or Mikmash, a place in Palestine Mikmas, Mikmash.', '(Ezra 2:2 or מִכְמָשׁ; or מִכְמַשׁ; (Nehemiah 11:31), from 3647; hidden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0357}/H9011/[H354]', 'inflected', 'heb', 'אַיָּלוֹן', '["ʼAyâlôwn"]', '["Aijalon/ towards"]', '["n-pr-loc"]', 'Ajalon, the name of five places in Palestine Aijalon, Ajalon.', 'from 354; deer-field;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5860B}/[H5860]', 'inflected', 'heb', 'עִיט', '["ʻîyṭ"]', '["and/ did you rush?","and/ it rushed"]', '["v"]', 'to swoop down upon (literally or figuratively) fly, rail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0898}/[H898]', 'lemma', 'heb', 'בָּגַד', '["bâgad"]', '["I dealt treacherously with","[is] acting treacherously","[is] treacherous","[one who] acts treacherously","[those who] act treacherously","[those who] act treacherously of","anyone deal treacherously","certainly <to act treacherously>","certainly <to deal treacherously>","do we deal treacherously","it has acted treacherously","people have dealt treacherously","people will deal treacherously","she deals treacherously","they act treacherously","they dealt treacherously","they have acted treacherously","they have dealt treacherously","treacherous","treacherous [people]","you have acted treacherously","you have dealt treacherously","you will act treacherously"]', '["v"]', 'to cover (with a garment); figuratively, to act covertly; by implication, to pillage deal deceitfully (treacherously, unfaithfully), offend, transgress(-or), (depart), treacherous (dealer, -ly, man), unfaithful(-ly, man), × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027M}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["in/ hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0962}/[H962]', 'inflected', 'heb', 'בָּזַז', '["bâzaz"]', '["and/ certainly <to be plundered>","and/ let us plunder","and/ may they plunder"]', '["v"]', 'to plunder catch, gather, (take) for a prey, rob(-ber), spoil, take (away, spoil), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3381}/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["¿/ will I go down","¿/ will he come down"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5414G}/H9038/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["¿/ will you give/ them"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3467}/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["who/ delivers"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3129N}/[H3083]', 'inflected', 'heb', 'יוֹנָתָן', '["Yôwnâthân"]', '["[is] in/ Jonathan","in/ Jonathan"]', '["n-pr-m"]', 'Jonathan, the name of ten Israelites Jonathan.', 'a form of 3083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5676G}/[H5674]', 'inflected', 'heb', 'עֵבֶר', '["ʻêber"]', '["[was] to/ [the] side of","to/ a side"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5771G}/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["<of the>/ iniquity","the/ iniquity"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0224}/[H217]', 'lemma', 'heb', 'אוּרִים', '["ʼÛwrîym"]', '["Urim"]', '["n-m"]', 'Urim, the oracular brilliancy of the figures in the high-priest''s breastplate Urim.', 'plural of 217; lights;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8549J}/[H8552]', 'lemma', 'heb', 'תָּמִים', '["tâmîym"]', '["Thummim"]', '["a"]', 'entire (literally, figuratively or morally); also (as noun) integrity, truth without blemish, complete, full, perfect, sincerely (-ity), sound, without spot, undefiled, upright(-ly), whole.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3129N}/[H3083]', 'inflected', 'heb', 'יוֹנָתָן', '["Yôwnâthân"]', '["¿/ Jonathan"]', '["n-pr-m"]', 'Jonathan, the name of ten Israelites Jonathan.', 'a form of 3083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3444}/[H3467]', 'inflected', 'heb', 'יְשׁוּעָה', '["yᵉshûwʻâh"]', '["<the>/ deliverance","<the>/ salvation","the/ deliverance"]', '["n-f"]', 'something saved, i.e. (abstractly) deliverance; hence, aid, victory, prosperity deliverance, health, help(-ing), salvation, save, saving (health), welfare.', 'feminine passive participle of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8185}/[H8181]', 'inflected', 'heb', 'שַׂעֲרָה', '["saʻărâh"]', '["more than/ [the] hairs of","one of/ [the] hair[s] of"]', '["n-f"]', 'hairiness hair.', 'feminine of 8181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4124G}/[H1]', 'inflected', 'heb', 'מוֹאָב', '["Môwʼâb"]', '["[were] in/ Moab","against/ Moab","on/ Moab"]', '["n-pr-m n-pr-loc"]', 'Moab, an incestuous son of Lot; also his territory and descendants Moab.', 'from a prolonged form of the prepositional prefix m- and 1; from (her [the mother''s]) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1121G}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ against/ [the] people of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0123G}/[H122]', 'inflected', 'heb', 'אֱדֹם', '["ʼĔdôm"]', '["and/ against/ Edom","and/ in/ Edom"]', '["n-pr-m"]', 'Edom, the elder twin-brother of Jacob; hence the region (Idumaea) occupied by him Edom, Edomites, Idumea.', 'or (fully) אֱדוֹם ; from 122; red (see Genesis 25:25);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4428G}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["and/ against/ [the] kings of"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6678G>', 'opaque', 'heb', 'צוֹבָא', '["Tsôwbâʼ"]', '["Zobah"]', '["n-pr-loc"]', 'Zoba or Zobah, a region of Syria Zoba, Zobah.', 'or צוֹבָה; or צֹבָה; from an unused root meaning to station; a station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6430G}/[H6429]', 'inflected', 'heb', 'פְּלִשְׁתִּי', '["Pᵉlishtîy"]', '["and/ against the/ Philistines","and/ among the/ Philistines"]', '["a"]', 'a Pelishtite or inhabitant of Pelesheth Philistine.', 'patrial from 6429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7561}/[H7561]', 'lemma', 'heb', 'רָשַׁע', '["râshaʻ"]', '["I am guilty","I have acted wickedly","I will be guilty","he acted wickedly","he acts wickedly","he condemns as guilty","they condemn as guilty","we have acted wickedly","will he condemn [him] as guilty","will you condemn as guilty","you be wicked","you will condemn as guilty"]', '["v"]', 'to be (causatively, do or declare) wrong; by implication, to disturb, violate condemn, make trouble, vex, be (commit, deal, depart, do) wicked(-ly, -ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8154}/H9033\/[H8154]', 'inflected', 'heb', 'שָׁסָה', '["shâçâh"]', '["[those who] plundered/ it"]', '["v"]', 'to plunder destroyer, rob, spoil(-er).', 'or שָׁשָׂה; (Isaiah 10:13), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3440H}/[H7737]', 'inflected', 'heb', 'יִשְׁוִי', '["Yishvîy"]', '["and/ Ishvi"]', '["n-pr-m"]', 'Jishvi, the name of two Israelites Ishuai, Ishvi, Isui, Jesui.', 'from 7737; level;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4444}/[H4428]', 'inflected', 'heb', 'מַלְכִּישׁוּעַ', '["Malkîyshûwaʻ"]', '["and/ Malki-"]', '["n-pr-m"]', 'Malkishua, an Israelite Malchishua.', 'from 4428 and 7769; king of wealth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4444}/[H4428]', 'lemma', 'heb', 'מַלְכִּישׁוּעַ', '["Malkîyshûwaʻ"]', '["Malki-","Shua"]', '["n-pr-m"]', 'Malkishua, an Israelite Malchishua.', 'from 4428 and 7769; king of wealth;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4764}/[H7231]', 'lemma', 'heb', 'מֵרָב', '["Mêrâb"]', '["Merab","[was] Merab"]', '["n-pr-f"]', 'Merab, a daughter of Saul Merab.', 'from 7231; increase;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4324G}/[H4323]', 'lemma', 'heb', 'מִיכָל', '["Mîykâl"]', '["Michal","[was] Michal"]', '["n-pr-f"]', 'Mikal, Saul''s daughter Michal.', 'apparently the same as 4323; revulet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0293G}/[H251]', 'lemma', 'heb', 'אֲחִינֹעַם', '["ʼĂchîynôʻam"]', '["[was] Ahinoam"]', '["n-pr-f"]', 'Achinoam, the name of two Israelitesses Ahinoam.', 'from 251 and 5278; brother of pleasantness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0290G}/[H251]', 'lemma', 'heb', 'אֲחִימַעַץ', '["ʼĂchîymaʻats"]', '["Ahimaaz"]', '["n-pr-loc"]', 'Achimaats, the name of three Israelites Ahimaaz.', 'from 251 and the equivalent of 4619; brother of anger;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0074}/[H1]', 'lemma', 'heb', 'אַבְנֵר', '["ʼAbnêr"]', '["Abner","O Abner","[was] Abner"]', '["n-pr-m"]', 'Abner, an Israelite Abner.', 'or (fully) אֲבִינֵר ; from 1 and 5216; father of light (i.e. enlightening);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5369G}/[H5216]', 'lemma', 'heb', 'נֵר', '["Nêr"]', '["Ner"]', '["n-pr-m"]', 'Ner, an Israelite Ner.', 'the same as 5216; lamp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7027G}/[H6983]', 'inflected', 'heb', 'קִישׁ', '["Qîysh"]', '["and/ Kish"]', '["n-pr-m"]', 'Kish, the name of five Israelites Kish.', 'from 6983; a bow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5369G}/[H5216]', 'inflected', 'heb', 'נֵר', '["Nêr"]', '["and/ Ner"]', '["n-pr-m"]', 'Ner, an Israelite Ner.', 'the same as 5216; lamp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0022G}\/[H1]', 'inflected', 'heb', 'אֲבִיאֵל', '["ʼĂbîyʼêl"]', '["Abiel"]', '["n-pr-m"]', 'Abiel, the name of two Israelites Abiel.', 'from 1 and 410; father (i.e. possessor) of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4886}/H9031/[H4886]', 'inflected', 'heb', 'מָשַׁח', '["mâshach"]', '["to/ anoint/ you"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5768}/[H5763]', 'inflected', 'heb', 'עוֹלֵל', '["ʻôwlêl"]', '["from/ a child","from/ child"]', '["n-m"]', 'a suckling babe, (young) child, infant, little one.', 'or עֹלָל; from 5763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2543}\/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["a donkey"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8085I}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ I have proclaimed","and/ he summoned","and/ it will be heard","and/ they caused to hear","and/ they will make heard"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2923}/[H2922]', 'inflected', 'heb', 'טְלָאִים', '["Ṭᵉlâʼîym"]', '["at <the>/ Telaim"]', '["n-pr-loc"]', 'Telaim, a place in Palestine Telaim.', 'from the plural of 2922; lambs;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6003}/[H6002]', 'lemma', 'heb', 'עֲמָלֵקִי', '["ʻĂmâlêqîy"]', '["Amalekite","[am] an Amalekite","[the] Amalekite[s]","an Amalekite"]', '["a"]', 'an Amalekite (or collectively the Amalekites) or descendants of Amalek Amalekite(-s).', 'patronymically from 6002;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0622}/H9031/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["I should destroy/ you","[will] gather/ you","it will be rearguard/ your"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0090H>', 'opaque', 'heb', 'אֲגַג', '["ʼĂgag"]', '["Agag"]', '["n-pr-m"]', 'Agag, a title of Amalekitish kings Agag.', 'or אֲגָג; of uncertain derivation (compare 89); flame;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4932H}/[H8138]', 'inflected', 'heb', 'מִשְׁנֶה', '["mishneh"]', '["and/ the/ second"]', '["n-m"]', 'properly, a repetition, i.e. a duplicate (copy of a document), or a double (in amount); by implication, a second (in order, rank, age, quality or location) college, copy, double, fatlings, next, second (order), twice as much.', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3733C}/[H3769]', 'inflected', 'heb', 'כַּר', '["kar"]', '["the/ lambs"]', '["n-m"]', 'a ram (as full-grown and fat), including a battering-ram (as butting); hence, a meadow (as for sheep); also a pad or camel''s saddle (as puffed out) captain, furniture, lamb, (large) pasture, ram. See also 1033, 3746.', 'from 3769 in the sense of plumpness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5240}/[H959]', 'lemma', 'heb', 'נְמִבְזֶה', '["nᵉmibzeh"]', '["despised"]', '["a"]', 'despised vile.', 'from 959,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4549}/[H4549]', 'inflected', 'heb', 'מָסַס', '["mâçaç"]', '["and/ worthless"]', '["v"]', 'to liquefy; figuratively, to waste (with disease), to faint (with fatigue, fear or grief) discourage, faint, be loosed, melt (away), refuse, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2763A}\/[H2763]', 'inflected', 'heb', 'חָרַם', '["châram"]', '["they totally destroyed","we totally destroyed"]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3760G}/H9011/[H3759]', 'inflected', 'heb', 'כַּרְמֶל', '["Karmel"]', '["<the>/ Carmel/ towards"]', '["n-pr-loc"]', 'Karmel, the name of a hill and of a town in Palestine Carmel, fruitful (plentiful) field, (place).', 'the same as 3759;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241G}/H9020/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["in/ ears/ my"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6003}/[H6002]', 'inflected', 'heb', 'עֲמָלֵקִי', '["ʻĂmâlêqîy"]', '["from/ [the] Amalekite[s]"]', '["a"]', 'an Amalekite (or collectively the Amalekites) or descendants of Amalek Amalekite(-s).', 'patronymically from 6002;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3148}/[H3498]', 'inflected', 'heb', 'יוֹתֵר', '["yôwthêr"]', '["the/ rest"]', '["n-m"]', 'properly, redundant; hence, over and above, as adjective, noun, adverb or conjunction better, more(-over), over, profit.', 'active participle of 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1696G}\/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["I have spoken","he has spoken","he spoke","it has spoken","speak","speaking"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4886}/H9031/[H4886]', 'inflected', 'heb', 'מָשַׁח', '["mâshach"]', '["and/ he anointed/ you"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615H}/H9048/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["come to an end/ they","destroy/ they"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H7998}/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["any of/ the/ booty","from/ the/ plunder","some of/ the/ booty"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2656}/[H2654]', 'inflected', 'heb', 'חֵפֶץ', '["chêphets"]', '["¿/ [does] delight","¿/ [does] pleasure"]', '["n-m"]', 'pleasure; hence (abstractly) desire; concretely, a valuable thing; hence (by extension) a matter (as something in mind) acceptable, delight(-some), desire, things desired, matter, pleasant(-ure), purpose, willingly.', 'from 2654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5930A}/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["in/ burnt offerings","with/ burnt offerings"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8085H}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["like/ listening"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7181}/[H7181]', 'inflected', 'heb', 'קָשַׁב', '["qâshab"]', '["to/ make attend","to/ pay attention"]', '["v"]', 'to prick up the ears, i.e. hearken attend, (cause to) hear(-ken), give heed, incline, mark (well), regard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2459>', 'inflected', 'heb', 'מחלב', '["me./Che.lev"]', '["from/ [the] best of","from/ [the] fat of","from/ fat","more than/ [the] fat of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0205G>', 'inflected', 'heb', 'ואון', '["va./''A.ven","ve./''A.ven"]', '["and/ [is] wickedness","and/ wickedness"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6484}/[H6484]', 'lemma', 'heb', 'פָּצַר', '["pâtsar"]', '["presumption"]', '["v"]', 'to peck at, i.e. (figuratively) stun or dull press, urge, stubbornness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3988A}/H9031/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["and/ he has rejected/ you"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4428G}\/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["from/ king"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3671}/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["in/ [the] skirt of","on/ [the] corners of","on/ [the] skirt of"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4598}/H9023/[H4603]', 'inflected', 'heb', 'מְעִיל', '["mᵉʻîyl"]', '["robe/ his"]', '["n-m"]', 'a robe (i.e. upper and outer garment) cloke, coat, mantle, robe.', 'from 4603 in the sense of covering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5331}/[H5329]', 'lemma', 'heb', 'נֶצַח', '["netsach"]', '["[the] eminence of","perpetuities","perpetuity"]', '["n-m"]', 'properly, a goal, i.e. the bright object at a distance travelled towards; hence (figuratively), splendor, or (subjectively) truthfulness, or (objectively) confidence; but usually (adverbially), continually (i.e. to the most distant point of view) alway(-s), constantly, end, ( n-) ever(more), perpetual, strength, victory.', 'or נֵצַח; from 5329;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5162H}/[H5162]', 'inflected', 'heb', 'נָחַם', '["nâcham"]', '["to/ regret"]', '["v"]', 'properly, to sigh, i.e. breathe strongly; by implication, to be sorry, i.e. (in a favorable sense) to pity, console or (reflexively) rue; or (unfavorably) to avenge (oneself) comfort (self), ease (one''s self), repent(-er,-ing, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4575}/[H6029]', 'lemma', 'heb', 'מַעֲדַנָּה', '["maʻădannâh"]', '["[the] bonds of","bonds"]', '["n-f"]', 'a bond, i.e. group influence.', 'by transitive from 6029;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4194}\/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["<the>/ death"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8158}/[H8158]', 'inflected', 'heb', 'שָׁסַף', '["shâçaph"]', '["and/ he cut to pieces"]', '["v"]', 'to cut in pieces, i.e. slaughter hew in pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1537G}\/[H1536]', 'inflected', 'heb', 'גִּלְגָּל', '["Gilgâl"]', '["in <the>/ Gilgal"]', '["n-pr-loc"]', 'Gilgal, the name of three places in Palestine Gilgal. See also 1019.', 'the same as 1536 (with the article as a properly, noun);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0056}/[H56]', 'lemma', 'heb', 'אָבַל', '["ʼâbal"]', '["I caused mourning","[he was] mourning","[were] mourning","[who has been] mourning","he mourn","he mourned","he will mourn","it has dried up","it is in mourning","it will dry up","it will mourn","mourning","play [the] mourner","will it dry up","you mourn"]', '["v"]', 'to bewail lament, mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3988A}/H9033/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["I have rejected/ him"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7161A}/H9021/[H7160]', 'inflected', 'heb', 'קֶרֶן', '["qeren"]', '["horn/ your"]', '["n-f n-pr-loc"]', 'a horn (as projecting); by implication, a flask, cornet; by resemblance. an elephant''s tooth (i.e. ivory), a corner (of the altar), a peak (of a mountain), a ray (of light); figuratively, power × hill, horn.', 'from 7160;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1022}/[H1035]', 'lemma', 'heb', 'בֵּית הַלַּחְמִי', '["Bêyth hal-Lachmîy"]', '["[the] Beth-"]', '["a"]', 'a Beth-lechemite, or native of Bethlechem Bethlehemite.', 'patrial from 1035 with the article inserted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1022}/[H1035]', 'inflected', 'heb', 'בֵּית הַלַּחְמִי', '["Bêyth hal-Lachmîy"]', '["<the>/ -lehemite"]', '["a"]', 'a Beth-lechemite, or native of Bethlechem Bethlehemite.', 'patrial from 1035 with the article inserted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2026}/H9030\/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["and/ he will kill/ me"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027I}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["in/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3448}/[H3426]', 'inflected', 'heb', 'יִשַׁי', '["Yishay"]', '["<to>/ Jesse","of/ Jesse"]', '["n-pr-m"]', 'Jishai, David''s father Jesse.', 'by Aramaic אִישַׁי; from the same as 3426; extant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0446I}/[H410]', 'lemma', 'heb', 'אֱלִיאָב', '["ʼĔlîyʼâb"]', '["Eliab","[was] Eliab"]', '["n-pr-m"]', 'Eliab, the name of six Israelites Eliab.', 'from 410 and 1; God of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869I}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to the/ eyes"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3824}/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["to the/ heart"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0041I}/[H1]', 'lemma', 'heb', 'אֲבִינָדָב', '["ʼĂbîynâdâb"]', '["Abinadab","[was] Abinadab"]', '["n-pr-m"]', 'Abinadab, the name of four Israelites Abinadab.', 'from 1 and 5068; father of generosity (i.e. liberal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5674A}/H9033/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["and/ he made pass by/ him"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8048J}/[H8047]', 'lemma', 'heb', 'שַׁמָּה', '["Shammâh"]', '["Shammah","[was] Shammah"]', '["n-pr-m"]', 'Shammah, the name of an Edomite and four Israelites Shammah.', 'the same as 8047;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H8552}/[H8552]', 'inflected', 'heb', 'תָּמַם', '["tâmam"]', '["¿/ are they finished"]', '["v"]', 'to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3947G}/H9033/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ bring/ him","so/ I may capture/ him"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7210}\/[H7200]', 'inflected', 'heb', 'רֳאִי', '["rŏʼîy"]', '["appearance"]', '["n-m"]', 'sight, whether abstractly (vision) or concretely (a spectacle) gazingstock, look to, (that) see(-th).', 'from 7200;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4886}/H9033/[H4886]', 'inflected', 'heb', 'מָשַׁח', '["mâshach"]', '["I have anointed/ him","anoint/ him","he had anointed/ him"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/<H3117G>', 'inflected', 'heb', 'מהיום', '["me./hai./Yom"]', '["from/ the/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7414J}/H9011\/[H7413]', 'inflected', 'heb', 'רָמָה', '["Râmâh"]', '["<the>/ Ramah/ towards"]', '["n-pr-loc"]', 'Ramah, the name of four places in Palestine Ramah.', 'the same as 7413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1204}/H9033/[H1204]', 'inflected', 'heb', 'בָּעַת', '["bâʻath"]', '["and/ it terrified/ him"]', '["v"]', 'to fear affright, be (make) afraid, terrify, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1204}/H9031/[H1204]', 'inflected', 'heb', 'בָּעַת', '["bâʻath"]', '["[is] terrifying/ you","it will terrify/ you"]', '["v"]', 'to fear affright, be (make) afraid, terrify, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0113>/H9025', 'opaque', 'heb', 'אָדוֹן', '["ʼâdôwn"]', '["lord/ our","lord<s>/ our","master<s>/ our"]', '["n-m"]', 'sovereign, i.e. controller (human or divine) lord, master, owner. Compare also names beginning with ''Adoni-''.', 'or (shortened) אָדֹן; from an unused root (meaning to rule);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5059}/[H5059]', 'lemma', 'heb', 'נָגַן', '["nâgan"]', '["[was] playing an instrument","a musician","musicians","playing","to play","we will play"]', '["v"]', 'properly, to thrum, i.e. beat a tune with the fingers; expectation. to play on a stringed instrument; hence (generally), to make music player on instruments, sing to the stringed instruments, melody, ministrel, play(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3658>', 'inflected', 'heb', 'בכנרות', '["ba./ki.Nor","be./khi.Nor","be./khi.no.Rot","ve./khi.Nor"]', '["on the/ harp","with <the>/ harp","with/ a harp","with/ harp","with/ harps"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5059}/[H5059]', 'inflected', 'heb', 'נָגַן', '["nâgan"]', '["and/ he played","and/ he will play"]', '["v"]', 'properly, to thrum, i.e. beat a tune with the fingers; expectation. to play on a stringed instrument; hence (generally), to make music player on instruments, sing to the stringed instruments, melody, ministrel, play(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9032}\', 'inflected', 'heb', 'לך פ', '["La/kh"]', '["<for>/ yourself","<to>/ you","[will belong] to <the>/ you","for <the>/ you","for/ yourself","of/ you","to <the>/ you","to <the>/ you[?]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5059}/[H5059]', 'inflected', 'heb', 'נָגַן', '["nâgan"]', '["to/ play"]', '["v"]', 'properly, to thrum, i.e. beat a tune with the fingers; expectation. to play on a stringed instrument; hence (generally), to make music player on instruments, sing to the stringed instruments, melody, ministrel, play(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1368}/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["and/ [the] mighty [men] of","and/ a mighty [man] of","and/ a mighty [person]","and/ mighty"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1423}/[H1415]', 'inflected', 'heb', 'גְּדִי', '["gᵉdîy"]', '["and/ a kid of"]', '["n-m"]', 'a young goat (from browsing) kid.', 'from the same as 1415;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5975H}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ appoint","and/ he appointed","and/ he stationed","and/ he stood","and/ they appointed","and/ they stood","and/ we establish"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0157G}/H9033/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["and/ I loved/ him","and/ he loved/ him"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3658>', 'inflected', 'heb', 'הכנור', '["ha./ki.Nor"]', '["the/ harp"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7304}/[H7306]', 'inflected', 'heb', 'רָוַח', '["râvach"]', '["and/ it was relief"]', '["v"]', 'properly, to breathe freely, i.e. revive; by implication, to have ample room be refreshed, large.', 'a primitive root (identical with 7306);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7451A}\/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<the>/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0658}/[H657]', 'inflected', 'heb', 'אֶפֶס דַּמִּים', '["ʼEpheç Dammîym"]', '["in/ Ephes"]', '["n-pr-loc"]', 'Ephes-Dammim, a place in Palestine Ephes-dammim.', 'from 657 and the plural of 1818; boundary of blood-drops;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0658}/[H657]', 'lemma', 'heb', 'אֶפֶס דַּמִּים', '["ʼEpheç Dammîym"]', '["Dammim"]', '["n-pr-loc"]', 'Ephes-Dammim, a place in Palestine Ephes-dammim.', 'from 657 and the plural of 1818; boundary of blood-drops;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6010I}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["[are] in/ [the] valley of","in/ [the] valley of"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0425L}/[H424]', 'inflected', 'heb', 'אֵלָה', '["ʼÊlâh"]', '["<the>/ Elah"]', '["n-pr"]', 'Elah, the name of an Edomite, of four Israelites, and also of a place in Palestine Elah.', 'the same as 424;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1143}/[H996]', 'inflected', 'heb', 'בֵּנַיִם', '["bênayim"]', '["the/ champions"]', '["n-m"]', 'a double interval, i.e. the space between two armies + champion.', 'dual of 996;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1555}/[H1540]', 'lemma', 'heb', 'גׇּלְיַת', '["Golyath"]', '["Goliath","[was] Goliath"]', '["n-pr-m"]', 'Goljath, a Philistine Goliath.', 'perhaps from 1540; exile;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1661}/[H1660]', 'inflected', 'heb', 'גַּת', '["Gath"]', '["from/ Gath"]', '["n-pr-loc"]', 'Gath, a Philistine city Gath.', 'the same as 1660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1363}/H9023/[H1361]', 'inflected', 'heb', 'גֹּבַהּ', '["gôbahh"]', '["haughtiness/ its","height/ his"]', '["n-m"]', 'elation, grandeur, arrogance excellency, haughty, height, high, loftiness, pride.', 'from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3553>', 'inflected', 'heb', 'וכובעים', '["ve./Khoa''","ve./Khoa.''Im","ve./kho.Va''"]', '["and/ a helmet of","and/ helmet","and/ helmets"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8302B}/[H8281]', 'inflected', 'heb', 'שִׁרְיוֹן', '["shiryôwn"]', '["and/ body armor of","and/ body armor<s>"]', '["n-m n-f"]', 'a corslet (as if twisted) breastplate, coat of mail, habergeon, harness. See 5630.', 'or שִׁרְיֹן; and שִׁרְיָן; also (feminine) שִׁרְיָה; and שִׁרְיֹנָה; from 8281 in the original sense of turning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7193>', 'opaque', 'heb', 'קַשְׂקֶשֶׂת', '["qasqeseth"]', '["scales"]', '["n-f"]', 'a scale (of a fish); hence a coat of mail (as composed of or covered with jointed plates of metal) mail, scale.', 'by reduplication from an unused root meaning to shale off as bark;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4948}/[H8254]', 'inflected', 'heb', 'מִשְׁקָל', '["mishqâl"]', '["and/ [the] weight","and/ [the] weight of"]', '["n-m"]', 'weight (numerically estimated); hence, weighing (the act) (full) weight.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8302B}/[H8281]', 'inflected', 'heb', 'שִׁרְיוֹן', '["shiryôwn"]', '["the/ body armor"]', '["n-m n-f"]', 'a corslet (as if twisted) breastplate, coat of mail, habergeon, harness. See 5630.', 'or שִׁרְיֹן; and שִׁרְיָן; also (feminine) שִׁרְיָה; and שִׁרְיֹנָה; from 8281 in the original sense of turning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4697}/[H4696]', 'inflected', 'heb', 'מִצְחָה', '["mitschâh"]', '["and/ leg armor of"]', '["n-f"]', 'a shinpiece of armor (as prominent), only plural greaves.', 'from the same as 4696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3591}/[H3589]', 'inflected', 'heb', 'כִּידוֹן', '["kîydôwn"]', '["and/ a javelin","and/ a javelin of","and/ javelin"]', '["n-m"]', 'properly, something to strike with, i.e. a dart lance, shield, spear, target.', 'from the same as 3589; (perhaps smaller than 2595)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2595}/H9023/[H2583]', 'inflected', 'heb', 'חֲנִית', '["chănîyth"]', '["spear/ his"]', '["n-f"]', 'a lance (for thrusting, like pitching a tent) javelin, spear.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4500}/[H5214]', 'inflected', 'heb', 'מָנוֹר', '["mânôwr"]', '["[was] like/ a beam of","like/ a beam of"]', '["n-m"]', 'a yoke (properly, for plowing), i.e. the frame of a loom beam.', 'from 5214;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3852}/[H3851]', 'inflected', 'heb', 'לֶהָבָה', '["lehâbâh"]', '["and/ [the] blade of","and/ a flame","and/ flame"]', '["n-f"]', 'flame(-ming), head (of a spear).', 'or לַהֶבֶת; feminine of 3851, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6793C}/[H6791]', 'inflected', 'heb', 'צִנָּה', '["tsinnâh"]', '["of the/ body shield","the/ body shield"]', '["n-f"]', 'a hook (as pointed); also a (large) shield (as if guarding by prickliness); also cold (as piercing) buckler, cold, hook, shield, target.', 'feminine of 6791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4634}/[H4633]', 'lemma', 'heb', 'מַעֲרָכָה', '["maʻărâkâh"]', '["[the] battle lines of","a battle line","battle line"]', '["n-f"]', 'an arrangement; concretely, a pile; specifically a military array army, fight, be set in order, ordered place, rank, row.', 'feminine of 4633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1262}/[H1250]', 'lemma', 'heb', 'בָּרָה', '["bârâh"]', '["commission"]', '["v"]', 'to select; to feed; to render clear choose, (cause to) eat, manifest, (give) meat.', 'a primitive root; to select; also (as denominative from 1250) to feed; also (as equivalent to 1305) to render clear (Ecclesiastes 3:18)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2865}/[H2865]', 'inflected', 'heb', 'חָתַת', '["châthath"]', '["and/ I will shatter","and/ it will be shattered","and/ they were dismayed","and/ they will be dismayed","and/ they will be shattered"]', '["v"]', 'properly, to prostrate; hence, to break down, either (literally) by violence, or (figuratively) by confusion and fear abolish, affright, be (make) afraid, amaze, beat down, discourage, (cause to) dismay, go down, scare, terrify.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1732}/[H1730]', 'inflected', 'heb', 'דָּוִד', '["Dâvid"]', '["and/ David"]', '["n-pr-m"]', 'David, the youngest son of Jesse David.', 'rarely (fully); דָּוִיד; from the same as 1730; loving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4932H}/H9023/[H8138]', 'inflected', 'heb', 'מִשְׁנֶה', '["mishneh"]', '["and/ [was] second/ his","and/ second/ his"]', '["n-m"]', 'properly, a repetition, i.e. a duplicate (copy of a document), or a double (in amount); by implication, a second (in order, rank, age, quality or location) college, copy, double, fatlings, next, second (order), twice as much.', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7992}/[H7969]', 'inflected', 'heb', 'שְׁלִישִׁי', '["shᵉlîyshîy"]', '["and/ <the>/ third","and/ <the>/ third [extension]","and/ <the>/ third [part]","and/ [was] the/ third","and/ the/ third","and/ the/ third [face]","and/ the/ third [part]"]', '["a"]', 'third; feminine a third (part); by extension, a third (day, year or time); specifically, a third-story cell) third (part, rank, time), three (years old).', 'ordinal from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7586G}\/[H7592]', 'inflected', 'heb', 'שָׁאוּל', '["Shâʼûwl"]', '["Saul"]', '["n-pr-m"]', 'Shaul, the name of an Edomite and two Israelites Saul, Shaul.', 'passive participle of 7592; asked;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6150}/[H6148]', 'inflected', 'heb', 'עָרַב', '["ʻârab"]', '["and/ [the] evening darkened"]', '["v"]', 'to grow dusky at sundown be darkened, (toward) evening.', 'a primitive root (rather identical with 6148 through the idea of covering with a texture);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>\', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["day[s]","days"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1732}/[H1730]', 'inflected', 'heb', 'דָּוִד', '["Dâvid"]', '["[belonged] to/ David","[belongs] to/ David","for/ David","of/ David","to/ David"]', '["n-pr-m"]', 'David, the youngest son of Jesse David.', 'rarely (fully); דָּוִיד; from the same as 1730; loving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7039}/[H7033]', 'inflected', 'heb', 'קָלִי', '["qâlîy"]', '["<the>/ roasted grain"]', '["n-m"]', 'roasted ears of grain parched corn.', 'or קָלִיא; from 7033;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7323G}/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["and/ bring [them] quickly","so/ I may run"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2757}/[H2782]', 'lemma', 'heb', 'חָרִיץ', '["chârîyts"]', '["[the] portions of"]', '["n-m"]', 'properly, incisure or (passively) incised; hence, a threshing-sledge (with sharp teeth); also a slice (as cut) cheese, harrow.', 'or חֲרִץ; from 2782; (compare 2742)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6161}/H9028/[H6048]', 'inflected', 'heb', 'עֲרֻבָּה', '["ʻărubbâh"]', '["pledge/ their"]', '["n-f"]', 'something given as security, i.e. (literally) a token (of safety) or (metaphorically) a bondsman pledge, surety.', 'feminine passive participle of 6048 in the sense of a bargain or exchange;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4570}/H9011/[H5696]', 'inflected', 'heb', 'מַעְגָּל', '["maʻgâl"]', '["the/ camp/ towards"]', '["n-m"]', 'a track (literally or figuratively); also a rampart (as circular) going, path, trench, way(-side).', 'or feminine מַעְגָּלָה; from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2428A}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["and/ the/ army"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4634}/[H4633]', 'inflected', 'heb', 'מַעֲרָכָה', '["maʻărâkâh"]', '["from/ [the] battle lines of"]', '["n-f"]', 'an arrangement; concretely, a pile; specifically a military array army, fight, be set in order, ordered place, rank, row.', 'feminine of 4633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2778A}/[H2779]', 'inflected', 'heb', 'חָרַף', '["châraph"]', '["to/ defy","to/ taunt"]', '["v"]', 'to pull off, i.e. (by implication) to expose (as by stripping); specifically, to betroth (as if a surrender); figuratively, to carp at, i.e. defame; to spend the winter betroth, blaspheme, defy, jeopard, rail, reproach, upbraid.', 'a primitive root; also denominative (from 2779)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6238}/H9033/[H6238]', 'inflected', 'heb', 'עָשַׁר', '["ʻâshar"]', '["he will make rich/ him"]', '["v"]', 'properly, to accumulate; chiefly (specifically) to grow (causatively, make) rich be(-come, en-, make, make self, wax) rich, make (1 Kings 22:48 marg). See 6240.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6239}/[H6238]', 'lemma', 'heb', 'עֹשֶׁר', '["ʻôsher"]', '["[is] wealth","[the] wealth of","rich[es]","wealth"]', '["n-m"]', 'wealth × far (richer), riches.', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1732}/[H1730]', 'inflected', 'heb', 'דָּוִד', '["Dâvid"]', '["<in>/ David","<on>/ David","against/ David","in/ David","on/ David","with/ David"]', '["n-pr-m"]', 'David, the youngest son of Jesse David.', 'rarely (fully); דָּוִיד; from the same as 1730; loving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2007}/[H2004]', 'inflected', 'heb', 'הֵנָּה', '["hênnâh"]', '["<the>/ those"]', '["p"]', 'themselves (often used emphatic for the copula, also in indirect relation) × in, × such (and such things), their, (into) them, thence, therein, these, they (had), on this side, whose, wherein.', 'prolongation for 2004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2087}/H9021/[H2102]', 'inflected', 'heb', 'זָדוֹן', '["zâdôwn"]', '["arrogance/ your"]', '["n-m"]', 'arrogance presumptuously, pride, proud (man).', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0681}/H9033/[H680]', 'inflected', 'heb', 'אֵצֶל', '["ʼêtsel"]', '["from/ beside/ him"]', '["n-m"]', 'a side; (as a preposition) near at, (hard) by, (from) (beside), near (unto), toward, with. See also 1018.', 'from 680 (in the sense of joining);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725J}/H9033/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ they brought back/ him"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947H}/H9033/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ he sent for/ him","and/ he took/ him"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5271A}/H9023\/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["since/ youth<s>/ his"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0738A}/[H717]', 'inflected', 'heb', 'אֲרִי', '["ʼărîy"]', '["<the>/ lion","<the>/ lions","the/ lion"]', '["n-m"]', 'a lion (young) lion, pierce (from the margin).', 'or (prolonged) אַרְיֵה; from 717 (in the sense of violence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1677}/[H1680]', 'inflected', 'heb', 'דֹּב', '["dôb"]', '["the/ bear"]', '["n"]', 'the bear (as slow) bear.', 'or (fully) דּוֹב; from 1680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5739}/[H5737]', 'inflected', 'heb', 'עֵדֶר', '["ʻêder"]', '["from/ the/ flock"]', '["n-m"]', 'an arrangement, i.e. muster (of animals) drove, flock, herd.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2206}/H9023/[H2204]', 'inflected', 'heb', 'זָקָן', '["zâqân"]', '["on/ beard/ its"]', '["n-m"]', 'the beard (as indicating age) beard.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416A}\/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["living"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6959}/[H3553]', 'lemma', 'heb', 'קוֹבַע', '["qôwbaʻ"]', '["a helmet of"]', '["n-m"]', 'a helmet helmet.', 'a form collateral to 3553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8302B}/[H8281]', 'lemma', 'heb', 'שִׁרְיוֹן', '["shiryôwn"]', '["body armor"]', '["n-m n-f"]', 'a corslet (as if twisted) breastplate, coat of mail, habergeon, harness. See 5630.', 'or שִׁרְיֹן; and שִׁרְיָן; also (feminine) שִׁרְיָה; and שִׁרְיֹנָה; from 8281 in the original sense of turning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5493G}/H9038/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["and/ he removed/ them"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4731>/H9023', 'opaque', 'heb', 'מַקֵּל', '["maqqêl"]', '["stick/ his"]', '["n-m"]', 'a shoot, i.e. stick (with leaves on, or for walking, striking, guiding, divining) rod, (hand-)staff.', 'or (feminine) מַקְּלָה; from an unused root meaning apparently to germinate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2512}/[H2505]', 'lemma', 'heb', 'חַלֻּק', '["challuq"]', '["smooth [ones] of"]', '["n-m"]', 'smooth smooth.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3219}/[H3950]', 'inflected', 'heb', 'יַלְקוּט', '["yalqûwṭ"]', '["and/ in the/ pouch"]', '["n-m"]', 'a travelling pouch (as if for gleanings) scrip.', 'from 3950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7050A}/H9023/[H7049]', 'inflected', 'heb', 'קֶלַע', '["qelaʻ"]', '["and/ sling/ his"]', '["n-m"]', 'a sling; also a (door) screen (as if slung across), or the valve (of the door) itself hanging, leaf, sling.', 'from 7049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7131}/[H7126]', 'inflected', 'heb', 'קָרֵב', '["qârêb"]', '["and/ approaching"]', '["a"]', 'near approach, come (near, nigh), draw near.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0132}/[H119]', 'inflected', 'heb', 'אַדְמֹנִי', '["ʼadmônîy"]', '["and/ red"]', '["a"]', 'reddish (of the hair or the complexion) red, ruddy.', 'or (fully) אַדְמוֹנִי ; from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/<H3611>', 'inflected', 'heb', 'הכלב', '["ha./Khe.lev"]', '["¿/ a dog"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0430J}/H9023/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["by/ gods/ his"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7704G>\', 'inflected', 'heb', 'השדה ס', '["ha./sa.Deh"]', '["the/ field"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2595}/[H2583]', 'inflected', 'heb', 'חֲנִית', '["chănîyth"]', '["and/ by/ spear","and/ with/ spear"]', '["n-f"]', 'a lance (for thrusting, like pitching a tent) javelin, spear.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3591}/[H3589]', 'inflected', 'heb', 'כִּידוֹן', '["kîydôwn"]', '["and/ with/ javelin"]', '["n-m"]', 'properly, something to strike with, i.e. a dart lance, shield, spear, target.', 'from the same as 3589; (perhaps smaller than 2595)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5462}/H9031/[H5462]', 'inflected', 'heb', 'סָגַר', '["çâgar"]', '["he will deliver up/ you"]', '["v"]', 'to shut up; figuratively, to surrender close up, deliver (up), give over (up), inclose, × pure, repair, shut (in, self, out, up, up together), stop, × straitly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5221}/H9031/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["and/ I will strike down/ you","and/ it will strike down/ you"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7049A}/[H7049]', 'inflected', 'heb', 'קָלַע', '["qâlaʻ"]', '["and/ he slung [it]"]', '["v"]', 'to sling; also to carve (as if a circular motion, or into light forms) carve, sling (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2883}/[H2883]', 'inflected', 'heb', 'טָבַע', '["ṭâbaʻ"]', '["and/ he sank","and/ it sank"]', '["v"]', 'to sink drown, fasten, settle, sink.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4696>/H9023', 'inflected', 'heb', 'במצחו', '["be./mitz.Ch/o","ve./mitz.Ch/o"]', '["in/ forehead/ his","on/ forehead/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2388J}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ he prevailed","and/ he was strong","and/ he will prevail","and/ he will take hold of","and/ it prevailed","and/ it prevailed over"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7050A}/[H7049]', 'inflected', 'heb', 'קֶלַע', '["qelaʻ"]', '["with the/ sling"]', '["n-m"]', 'a sling; also a (door) screen (as if slung across), or the valve (of the door) itself hanging, leaf, sling.', 'from 7049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8025}/H9034/[H8025]', 'inflected', 'heb', 'שָׁלַף', '["shâlaph"]', '["and/ he drew out/ it"]', '["v"]', 'to pull out, up or off draw (off), grow up, pluck off.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8593}/H9024/[H6168]', 'inflected', 'heb', 'תַּעַר', '["taʻar"]', '["from/ sheath/ its"]', '["n"]', 'a knife or razor (as making bare); also a scabbard (as being bare, i.e. empty) (pen-) knife, razor, scabbard, shave, sheath.', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1368}/H9028/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["mighty [man]/ their"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1516P}/[H1466]', 'lemma', 'heb', 'גַּיְא', '["gayʼ"]', '["[to] Gath"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8189G}/[H8179]', 'lemma', 'heb', 'שַׁעֲרַיִם', '["Shaʻărayim"]', '["Shaaraim"]', '["n-pr-loc"]', 'Shaarajim, a place in Palestine Shaaraim.', 'dual of 8179; double gates;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1814}/[H1814]', 'inflected', 'heb', 'דָּלַק', '["dâlaq"]', '["from/ hotly pursuing"]', '["v"]', 'to flame (literally or figuratively) burning, chase, inflame, kindle, persecute(-or), pursue hotly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0168G}/H9023\/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["in/ own tent/ his"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7200G}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ just as/ saw"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5958}\/[H5956]', 'inflected', 'heb', 'עֶלֶם', '["ʻelem"]', '["[is] the/ youth"]', '["n-m"]', 'properly, something kept out of sight, i.e. a lad young man, stripling.', 'from 5956; (compare 5959)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7725G}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ just as/ returned"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315G}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ [the] appetite of","and/ [the] life of","and/ [the] self of","and/ [the] throat of","and/ a throat","and/ persons"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315G}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["in/ [the] self","with/ [the] self of","with/ a soul"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5315G}/H9023/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["like/ own self/ his"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2290A}/H9023/[H2296]', 'inflected', 'heb', 'חֲגוֹר', '["chăgôwr"]', '["belt/ his"]', '["n-m n-f"]', 'a belt (for the waist) apron, armour, gird(-le).', 'or חֲגֹר; and (feminine) חֲגוֹרָה; or חֲגֹרָה; from 2296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760L}/H9033/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ he appointed/ him"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7725G}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["when/ returned","when/ returns","when/ turn"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7891}/[H7788]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["for the/ singers","to/ sing"]', '["v"]', 'to sing behold (by mistake for 7789), sing(-er, -ing man, -ing woman).', 'or (the original form) שׁוּר; (1 Samuel 18:6), a primitive root (rather identical with 7788 through the idea of strolling minstrelsy);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4246}/[H4234]', 'inflected', 'heb', 'מְחֹלָה', '["mᵉchôlâh"]', '["and/ the/ dancing"]', '["n-f"]', 'a dance company, dances(-cing).', 'feminine of 4234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7991B}/[H7969]', 'inflected', 'heb', 'שָׁלִישׁ', '["shâlîysh"]', '["and/ with/ three-stringed instruments"]', '["n-m"]', 'a triple, i.e. (as a musical instrument) a triangle (or perhaps rather three-stringed lute); also (as an indefinite, great quantity) a three-fold measure (perhaps a treble ephah); also (as an officer) a general of the third rank (upward, i.e. the highest) captain, instrument of musick, (great) lord, (great) measure, prince, three (from the margin).', 'or שָׁלוֹשׁ; (1 Chronicles 11:11; 1 Chronicles 12:18), or שָׁלֹשׁ; (2 Samuel 23:13), from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7832}/[H7832]', 'inflected', 'heb', 'שָׂחַק', '["sâchaq"]', '["who/ were playing"]', '["v"]', 'to laugh (in pleasure or detraction); by implication, to play deride, have in derision, laugh, make merry, mock(-er), play, rejoice, (laugh to) scorn, be in (make) sport.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0505G}/H9023/[H504]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["<on>/ thousands/ his"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7233}/H9023/[H7231]', 'inflected', 'heb', 'רְבָבָה', '["rᵉbâbâh"]', '["<on>/ ten thousands/ his"]', '["n-f"]', 'abundance (in number), i.e. (specifically) a myriad (whether definite or indefinite) many, million, × multiply, ten thousand.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1697H}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["the/ matter","the/ word"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5770}/[H5869]', 'lemma', 'heb', 'עָוַן', '["ʻâvan"]', '["looking at"]', '["v"]', 'to watch (with jealosy) eye.', 'denominative from 5869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1973}\/[H1973]', 'inflected', 'heb', 'הָלְאָה', '["hâlᵉʼâh"]', '["and/ onwards"]', '["adv"]', 'to the distance, i.e. far away; also (of time) thus far back, beyond, (hence,-) forward, hitherto, thence, forth, yonder.', 'from the primitive form of the article (hal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H3117J>', 'inflected', 'heb', 'כיום', '["ke./Yom"]', '["as/ a day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3117J>', 'inflected', 'heb', 'ביום', '["be./Yom","be./yOm"]', '["in/ a day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2595}/[H2583]', 'inflected', 'heb', 'חֲנִית', '["chănîyth"]', '["and/ the/ spear"]', '["n-f"]', 'a lance (for thrusting, like pitching a tent) javelin, spear.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2904}/[H2904]', 'inflected', 'heb', 'טוּל', '["ṭûwl"]', '["and/ I will throw out","and/ he threw","and/ they threw"]', '["v"]', 'to pitch over or reel; hence (transitively) to cast down or out carry away, (utterly) cast (down, forth, out), send out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2595}/[H2583]', 'inflected', 'heb', 'חֲנִית', '["chănîyth"]', '["the/ spear","the/ spears"]', '["n-f"]', 'a lance (for thrusting, like pitching a tent) javelin, spear.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7023}/[H6979]', 'inflected', 'heb', 'קִיר', '["qîyr"]', '["and/ <on> the/ wall"]', '["n-m"]', 'a wall (as built in a trench) mason, side, town, × very, wall.', 'or קִר; (Isaiah 22:5), or (feminine) קִירָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5973B}/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["and/ from/ with"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5493G}/H9033/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["and/ he removed/ him"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6440L}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["of/ <before>/ him"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440G}/H9028\/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ them"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121K}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["<into>/ a son of","<into>/ sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6430G}\/[H6429]', 'inflected', 'heb', 'פְּלִשְׁתִּי', '["Pᵉlishtîy"]', '["[the] Philistines"]', '["a"]', 'a Pelishtite or inhabitant of Pelesheth Philistine.', 'patrial from 6429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416B}/H9020/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["[are] kinsfolk/ my"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5741}/[H5739]', 'inflected', 'heb', 'עַדְרִיאֵל', '["ʻAdrîyʼêl"]', '["to/ Adriel"]', '["n-pr-m"]', 'Adriel, an Israelite Adriel.', 'from 5739 and 410; flock of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4259}/[H65]', 'inflected', 'heb', 'מְחֹלָתִי', '["Mᵉchôlâthîy"]', '["the/ Meholathite"]', '["a"]', 'a Mecholathite or inhabitant of Abel-Mecholah Mecholathite.', 'patrial from 65;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7326}/[H7326]', 'lemma', 'heb', 'רוּשׁ', '["rûwsh"]', '["[is] poor","[one who] impoverishes himself","[was] poor","a poor [person]","a poor person","poor","poor [people]","they are in want"]', '["v"]', 'to be destitute lack, needy, (make self) poor (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7034}/[H7034]', 'inflected', 'heb', 'קָלָה', '["qâlâh"]', '["and/ lightly esteemed"]', '["v"]', 'to be light (as implied in rapid motion), but figuratively, only (be [causatively, hold] in contempt) base, contemn, despise, lightly esteem, set light, seem vile.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2656}/[H2654]', 'lemma', 'heb', 'חֵפֶץ', '["chêphets"]', '["[is] pleasure","delight","desire","matter","pleasure","pleasures"]', '["n-m"]', 'pleasure; hence (abstractly) desire; concretely, a valuable thing; hence (by extension) a matter (as something in mind) acceptable, delight(-some), desire, things desired, matter, pleasant(-ure), purpose, willingly.', 'from 2654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4119}/[H4117]', 'inflected', 'heb', 'מֹהַר', '["môhar"]', '["in/ bride-price"]', '["n-m"]', 'a price (for a wife) dowry.', 'from 4117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5358}/[H5358]', 'inflected', 'heb', 'נָקַם', '["nâqam"]', '["to/ avenge","to/ avenge himself","to/ avenge themselves"]', '["v"]', 'to grudge, i.e. avenge or punish avenge(-r, self), punish, revenge (self), × surely, take vengeance.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0341}/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["against/ [the] enemies of","on/ [the] enemies of"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2859B}/[H2859]', 'inflected', 'heb', 'חָתַן', '["châthan"]', '["to/ be son-in-law"]', '["v"]', 'to give (a daughter) away in marriage; hence (generally) to contract affinity by marriage join in affinity, father in law, make marriages, mother in law, son in law.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0582}/H9023/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["and/ men/ his"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4324G}/[H4323]', 'inflected', 'heb', 'מִיכָל', '["Mîykâl"]', '["and/ Michal"]', '["n-pr-f"]', 'Mikal, Saul''s daughter Michal.', 'apparently the same as 4323; revulet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3117J>\', 'inflected', 'heb', 'הימים ס', '["hai./ya.Mim"]', '["the/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318G}/H9048/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["went out/ they"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3365}/[H3365]', 'inflected', 'heb', 'יָקַר', '["yâqar"]', '["and/ it was esteemed"]', '["v"]', 'properly, apparently, to be heavy, i.e. (figuratively) valuable; causatively, to make rare (figuratively, to inhibit) be (make) precious, be prized, be set by, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3083H}/[H3068]', 'inflected', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["and/ Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4191}/H9031/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["to/ kill/ you"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3027K}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[was] to/ [the] side of","to/ [the] side of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5650}/H9023/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["against/ servant/ his","in/ servants/ his","with/ servants/ his"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2595}/H9023/[H2583]', 'inflected', 'heb', 'חֲנִית', '["chănîyth"]', '["and/ spear/ his"]', '["n-f"]', 'a lance (for thrusting, like pitching a tent) javelin, spear.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2595}/[H2583]', 'inflected', 'heb', 'חֲנִית', '["chănîyth"]', '["with the/ spear"]', '["n-f"]', 'a lance (for thrusting, like pitching a tent) javelin, spear.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6362}/[H6362]', 'inflected', 'heb', 'פָּטַר', '["pâṭar"]', '["and/ he escaped"]', '["v"]', 'to cleave or burst through, i.e. (causatively) to emit, whether literal or figurative (gape) dismiss, free, let (shoot) out, slip away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8104I}/H9033/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["to/ watch for/ him"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4191}/H9033/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ to/ kill/ him"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3523}/[H3527]', 'lemma', 'heb', 'כְּבִיר', '["kᵉbîyr"]', '["<the> quilt of"]', '["n-m"]', 'a matrass (of intertwined materials) pillow.', 'from 3527 in the original sense of plaiting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0899B}\/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["with the/ garment"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4296}/[H5186]', 'inflected', 'heb', 'מִטָּה', '["miṭṭâh"]', '["on the/ bed"]', '["n-f"]', 'a bed (as extended) for sleeping or eating; by analogy, a sofa, litter or bier bed(-chamber), bier.', 'from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3523}/[H3527]', 'inflected', 'heb', 'כְּבִיר', '["kᵉbîyr"]', '["and/ [the] quilt of"]', '["n-m"]', 'a matrass (of intertwined materials) pillow.', 'from 3527 in the original sense of plaiting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9032/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["will I kill/ you"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5121}/[H5115]', 'inflected', 'heb', 'נָוִית', '["Nâvîyth"]', '["[is] at/ Naioth","at/ Naioth"]', '["n-pr-loc"]', 'Navith, a place in Palestine Naioth (from the margin).', 'from 5115; residence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7414J}/[H7413]', 'inflected', 'heb', 'רָמָה', '["Râmâh"]', '["in <the>/ Ramah"]', '["n-pr-loc"]', 'Ramah, the name of four places in Palestine Ramah.', 'the same as 7413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3862>', 'opaque', 'heb', 'לַהֲקָה', '["lahăqâh"]', '["[the] company of"]', '["n-f"]', 'an assembly company.', 'probably from an unused root meaning to gather;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7906>', 'inflected', 'heb', 'בשכו', '["ba./Se.khu"]', '["[is] in <the>/ Secu"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5121}/[H5115]', 'lemma', 'heb', 'נָוִית', '["Nâvîyth"]', '["Naioth"]', '["n-pr-loc"]', 'Navith, a place in Palestine Naioth (from the margin).', 'from 5115; residence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5030}\/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["among the/ prophets"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5121}/[H5115]', 'inflected', 'heb', 'נָוִית', '["Nâvîyth"]', '["from/ Naioth"]', '["n-pr-loc"]', 'Navith, a place in Palestine Naioth (from the margin).', 'from 5115; residence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771H}/H9020/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["[is] iniquity/ my"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0241I}/H9020/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["ear/ my"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2416A}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["and/ [by] [the] life","and/ [by] [the] life of"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6587}/[H6585]', 'inflected', 'heb', 'פֶּשַׂע', '["pesaʻ"]', '["about/ a step"]', '["n-m"]', 'a stride step.', 'from 6585;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2320H}/[H2318]', 'lemma', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["a new moon","new moon"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971H}/H9030/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ you will let go/ me"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485K}/H9030/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["he will miss/ me"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7323G}/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["to/ run"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4940}/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["the/ clan","the/ clans","the/ family"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615I}/[H3615]', 'lemma', 'heb', 'כָּלָה', '["kâlâh"]', '["he accomplishes","it had been determined","it has been determined","it is exhausted","it was determined","they are exhausted"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9030/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["he killed/ me","put to death/ me","will you put to death/ me","you will kill/ me"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935P}/H9030\/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["will you bring/ me"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3083H}/[H3068]', 'inflected', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["of/ Jonathan","to/ Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3772I}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["when/ are cut off","when/ cut off","when/ cuts off"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7650}/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["to/ make swear an oath","to/ swear"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0160}/[H158]', 'lemma', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["O love","[is] love","[the] love of","leather","love"]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157G}/H9033\/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["he loved/ him"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6485K}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ it was empty","and/ they were missed","and/ you will be missed"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0237}/[H235]', 'inflected', 'heb', 'אֶזֶל', '["ʼezel"]', '["<the>/ Ezel"]', '["n-pr-loc"]', 'Ezel, a memorial stone in Palestine Ezel.', 'from 235; departure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2671}/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["the/ arrows"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6654>/H9011', 'opaque', 'heb', 'צַד', '["tsad"]', '["[its] side/ <towards>"]', '["n-m"]', 'a side; figuratively, an adversary (be-) side.', 'contr. from an unused root meaning to sidle off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4307H}/[H5201]', 'inflected', 'heb', 'מַטָּרָא', '["maṭṭârâʼ"]', '["to/ a target"]', '["n-f"]', 'a jail (as a guard-house); also an aim (as being closely watched) mark, prison.', 'or מַטָּרָה; from 5201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0935G}/H9012/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ come/ !","and/ let it come/ !"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5958}/[H5956]', 'inflected', 'heb', 'עֶלֶם', '["ʻelem"]', '["to the/ young man"]', '["n-m"]', 'properly, something kept out of sight, i.e. a lad young man, stripling.', 'from 5956; (compare 5959)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1697I}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ the/ matter","and/ the/ thing"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4186}/H9023/[H3427]', 'inflected', 'heb', 'מוֹשָׁב', '["môwshâb"]', '["seat/ his"]', '["n-m"]', 'a seat; figuratively, a site; abstractly, a session; by extension an abode (the place or the time); by implication, population assembly, dwell in, dwelling(-place), wherein (that) dwelt (in), inhabited place, seat, sitting, situation, sojourning.', 'or מֹשָׁב; from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3083H}/[H3068]', 'inflected', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["on/ Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5753B}/[H5753]', 'lemma', 'heb', 'עָוָה', '["ʻâvâh"]', '["<the> perverse [woman] of","I have done wrong","he did perversely","she did wrong","to iniquire","we have done wrong"]', '["v"]', 'to crook, literally or figuratively do amiss, bow down, make crooked, commit iniquity, pervert, (do) perverse(-ly), trouble, × turn, do wickedly, do wrong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4780}/[H4775]', 'inflected', 'heb', 'מַרְדּוּת', '["mardûwth"]', '["<the>/ rebelliousness"]', '["n-f"]', 'rebelliousness × rebellious.', 'from 4775;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1322}/H9021/[H954]', 'inflected', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["to/ own shame/ your"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1322}/[H954]', 'inflected', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["and/ to/ [the] shame of"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2425}/[H2421]', 'lemma', 'heb', 'חָיַי', '["châyay"]', '["he lives"]', '["v"]', 'to live; causatively to revive live, save life.', 'a primitive root (compare 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4438}/H9021/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["and/ kingdom/ your"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3637}/H9033/[H3637]', 'inflected', 'heb', 'כָּלַם', '["kâlam"]', '["he had put to shame/ him"]', '["v"]', 'properly, to wound; but only figuratively, to taunt or insult be (make) ashamed, blush, be confounded, be put to confusion, hurt, reproach, (do, put to) shame.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2678}/[H2671]', 'inflected', 'heb', 'חִצִּי', '["chitstsîy"]', '["[is] the/ arrow","the/ arrow"]', '["n-m"]', 'an arrow arrow.', 'or חֵצִי; prolongation from 2671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5674A}/H9033/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["to/ make [it] pass beyond/ him"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2363A}/H9012/[H2363]', 'inflected', 'heb', 'חוּשׁ', '["chûwsh"]', '["let it make haste/ !","make haste/ !"]', '["v"]', 'to hurry; figuratively, to be eager with excitement or enjoyment (make) haste(-n), ready.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0681}/[H680]', 'inflected', 'heb', 'אֵצֶל', '["ʼêtsel"]', '["from/ beside"]', '["n-m"]', 'a side; (as a preposition) near at, (hard) by, (from) (beside), near (unto), toward, with. See also 1018.', 'from 680 (in the sense of joining);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5045H>', 'inflected', 'heb', 'הנגב', '["ha./Ne.gev","ha./ne.Gev"]', '["the/ south"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2233H}/H9020/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["offspring/ my"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5011}/H9011/[H5108]', 'inflected', 'heb', 'נֹב', '["Nôb"]', '["Nob/ towards"]', '["n-pr-loc"]', 'Nob, a place in Palestine Nob.', 'the same as 5108; fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0288G}/[H251]', 'lemma', 'heb', 'אֲחִימֶלֶךְ', '["ʼĂchîymelek"]', '["Ahimelech","O Ahimelech"]', '["n-pr-m"]', 'Achimelek, the name of an Israelite and of a Hittite Ahimelech.', 'from 251 and 4428; brother of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0288G}/[H251]', 'inflected', 'heb', 'אֲחִימֶלֶךְ', '["ʼĂchîymelek"]', '["of/ Ahimelech","to/ Ahimelech"]', '["n-pr-m"]', 'Achimelek, the name of an Israelite and of a Hittite Ahimelech.', 'from 251 and 4428; brother of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027W}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027W}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["in/ hand/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2455}/[H2490]', 'lemma', 'heb', 'חֹל', '["chôl"]', '["[will be] a profane area","profaneness"]', '["n-m"]', 'properly, exposed; hence, profane common, profane (place), unholy.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027W}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0802G}\/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["from/ a woman"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5493G}/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["which/ had been removed"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947G}/H9043/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["was taken away/ it"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1673}/[H1672]', 'lemma', 'heb', 'דֹּאֵג', '["Dôʼêg"]', '["Doeg","[was] Doeg"]', '["n-pr-m"]', 'Doeg, an Edomite Doeg.', 'or (fully) דּוֹאֵג; active participle of 1672; anxious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0130}/[H123]', 'inflected', 'heb', 'אֱדֹמִי', '["ʼĔdômîy"]', '["the/ Edomite"]', '["a"]', 'an Edomite, or descendants from (or inhabitants of) Edom Edomite.', 'or (fully) אֱדוֹמִי ; patronymic from 123; See 726.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0047I}/[H46]', 'lemma', 'heb', 'אַבִּיר', '["ʼabbîyr"]', '["O [people] mighty of","[people] mighty of","[the] mighty","[the] mighty [one] of","mighty [ones]"]', '["a-m"]', 'angel, bull, chiefest, mighty (one), stout(-hearted), strong (one), valiant.', 'for 46');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0371}/[H369]', 'inflected', 'heb', 'אִין', '["ʼîyn"]', '["and/ where?"]', '["adv"]', 'is it not? not.', 'apparently a shortened form of 369; but (like 370) an interrogative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5169}\/[H5169]', 'inflected', 'heb', 'נָחַץ', '["nâchats"]', '["urgent"]', '["v"]', 'to be urgent require haste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3874}/[H3874]', 'lemma', 'heb', 'לוּט', '["lûwṭ"]', '["[is] wrapped"]', '["v"]', 'to wrap up cast, wrap.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8071}/[H5566]', 'inflected', 'heb', 'שִׂמְלָה', '["simlâh"]', '["in <the>/ cloak","in the/ cloak"]', '["n-f"]', 'a dress, especially a mantle apparel, cloth(-es, -ing), garment, raiment. Compare 8008.', 'perhaps by permutation for the feminine of 5566 (through the idea of a cover assuming the shape of the object beneath);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2108}/H9034/[H2107]', 'inflected', 'heb', 'זוּלָה', '["zûwlâh"]', '["except/ it"]', '["n-f"]', 'probably scattering, i.e. removal; used adverbially, except beside, but, only, save.', 'from 2107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0397>', 'opaque', 'heb', 'אֲכִישׁ', '["ʼĂkîysh"]', '["Achish"]', '["n-pr-m"]', 'Akish, a Philistine king Achish.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2088}/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["[belongs] to/ this [man]","[belongs] to/ this one","of/ this [one]"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760K}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ he put","and/ he set","and/ you will set"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8138A}/H9033/[H8138]', 'inflected', 'heb', 'שָׁנָה', '["shânâh"]', '["and/ he changed/ it"]', '["v"]', 'to fold, i.e. duplicate (literally or figuratively); by implication, to transmute (transitive or intransitive) do (speak, strike) again, alter, double, (be given to) change, disguise, (be) diverse, pervert, prefer, repeat, return, do the second time.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869J}/H9028/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ their"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1984C}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["and/ he pretended to be mad","and/ they will act like mad people"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8427}/[H8427]', 'inflected', 'heb', 'תָּוָה', '["tâvâh"]', '["and/ he made marks","and/ you will mark"]', '["v"]', 'to mark out, i.e. (primitive) scratch or (definite) imprint scrabble, set (a mark).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7388}/H9023/[H7325]', 'inflected', 'heb', 'רִיר', '["rîyr"]', '["spittle/ his"]', '["n-m"]', 'saliva; by resemblance, broth spittle, white (of an egg).', 'from 7325;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2638}/[H2637]', 'lemma', 'heb', 'חָסֵר', '["châçêr"]', '["[is] lacking","[is] lacking of","[one] lacking of","lacking","lacking of"]', '["a"]', 'lacking; hence, without destitute, fail, lack, have need, void, want.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7696}/[H7696]', 'inflected', 'heb', 'שָׁגַע', '["shâgaʻ"]', '["to/ behave like a madman"]', '["v"]', 'to rave through insanity (be, play the) mad (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9020\/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["house/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4689}/[H6693]', 'lemma', 'heb', 'מָצוֹק', '["mâtsôwq"]', '["distress"]', '["n-m"]', 'a narrow place, i.e. (abstractly and figuratively) confinement or disability anguish, distress, straitness.', 'from 6693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5378}/[H5377]', 'lemma', 'heb', 'נָשָׁא', '["nâshâʼ"]', '["a creditor"]', '["v"]', 'to lend on interest; by implication, to dun for debt × debt, exact, giver of usury.', 'a primitive root (perhaps identical with 5377, through the idea of imposition);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4708H}/[H4707]', 'lemma', 'heb', 'מִצְפֶּה', '["Mitspeh"]', '["Mizpah of"]', '["n-pr-loc"]', 'Mitspeh, the name of five places in Palestine Mizpeh, watch tower. Compare 4709.', 'the same as 4707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0517}/H9020/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["and/ O mother/ my","and/ mother/ my"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5148}/H9038/[H5148]', 'inflected', 'heb', 'נָחָה', '["nâchâh"]', '["and/ he guided/ them","and/ he led/ them"]', '["v"]', 'to guide; by implication, to transport (into exile, or as colonists) bestow, bring, govern, guide, lead (forth), put, straiten.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4686B}\/[H4685]', 'inflected', 'heb', 'מָצוּד', '["mâtsûwd"]', '["in the/ stronghold"]', '["n-f"]', 'a net, or (abstractly) capture; also a fastness castle, defense, fort(-ress), (strong) hold, be hunted, net, snare, strong place.', 'or (feminine) מְצוּדָה; or מְצֻדָה; for 4685;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1410H}/[H1464]', 'lemma', 'heb', 'גָּד', '["Gâd"]', '["Gad"]', '["n-pr-m"]', 'Gad, a son of Jacob, including his tribe and its territory; also a prophet Gad.', 'from 1464;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4686B}/[H4685]', 'inflected', 'heb', 'מָצוּד', '["mâtsûwd"]', '["[was] in the/ stronghold","in the/ stronghold"]', '["n-f"]', 'a net, or (abstractly) capture; also a fastness castle, defense, fort(-ress), (strong) hold, be hunted, net, snare, strong place.', 'or (feminine) מְצוּדָה; or מְצֻדָה; for 4685;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2802}\/[H2801]', 'inflected', 'heb', 'חֶרֶת', '["Chereth"]', '["Hereth"]', '["n-pr-loc"]', 'Chereth, a thicket in Palestine Hereth.', 'from 2801 (but equivalent to 2793); forest;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0815}/[H815]', 'inflected', 'heb', 'אֵשֶׁל', '["ʼêshel"]', '["the/ tamarisk tree"]', '["n-m"]', 'a tamarisk tree; by extension, a grove of any kind grove, tree.', 'from a root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7413}/[H7311]', 'inflected', 'heb', 'רָמָה', '["râmâh"]', '["at the/ high place"]', '["n-f"]', 'a height (as a seat of idolatry) high place.', 'feminine active participle of 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3605}/H9026/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["<to>/ all of/ you","to/ all of/ you"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3772H}/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["when/ made"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2470I}/[H2342]', 'lemma', 'heb', 'חָלָה', '["châlâh"]', '["[being] sick","[is] severe","[was] feeling pain","he made [him] sick","made sick","severe","they were sickened"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1540H}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["and/ opening"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0693}/[H693]', 'inflected', 'heb', 'אָרַב', '["ʼârab"]', '["to/ an ambusher"]', '["v"]', 'to lurk (lie in) ambush(-ment), lay (lie in) wait.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6720}/[H6718]', 'inflected', 'heb', 'צֵידָה', '["tsêydâh"]', '["and/ food"]', '["n-f"]', 'food meat, provision, venison, victuals.', 'or צֵדָה; feminine of 6718;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5011}/[H5108]', 'inflected', 'heb', 'נֹב', '["Nôb"]', '["[were] at/ Nob","at/ Nob"]', '["n-pr-loc"]', 'Nob, a place in Palestine Nob.', 'the same as 5108; fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6965J}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["to/ rise up"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1732}/[H1730]', 'inflected', 'heb', 'דָּוִד', '["Dâvid"]', '["[is] like/ David","like/ David"]', '["n-pr-m"]', 'David, the youngest son of Jesse David.', 'rarely (fully); דָּוִיד; from the same as 1730; loving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2860}/[H2859]', 'inflected', 'heb', 'חָתָן', '["châthân"]', '["and/ [the] son-in-law of"]', '["n-m"]', 'a relative by marriage (especially through the bride); figuratively, a circumcised child (as a species of religious espousal) bridegroom, husband, son in law.', 'from 2859;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4928}/H9021/[H4926]', 'inflected', 'heb', 'מִשְׁמַעַת', '["mishmaʻath"]', '["bodyguard/ your"]', '["n-f"]', 'audience, i.e. the royal court; also obedience, i.e. (concretely) a subject bidding, guard, obey.', 'feminine of 4926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7323H}/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["to the/ runners"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7971K}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["by/ stretching out","to/ stretch out"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6293}/[H6293]', 'inflected', 'heb', 'פָּגַע', '["pâgaʻ"]', '["to/ fall"]', '["v"]', 'to impinge, by accident or violence, or (figuratively) by importunity come (betwixt), cause to entreat, fall (upon), make intercession, intercessor, intreat, lay, light (upon), meet (together), pray, reach, run.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1673}/[H1672]', 'inflected', 'heb', 'דֹּאֵג', '["Dôʼêg"]', '["to/ Doeg"]', '["n-pr-m"]', 'Doeg, an Edomite Doeg.', 'or (fully) דּוֹאֵג; active participle of 1672; anxious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5011}/[H5108]', 'lemma', 'heb', 'נֹב', '["Nôb"]', '["Nob"]', '["n-pr-loc"]', 'Nob, a place in Palestine Nob.', 'the same as 5108; fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0054}/[H1]', 'lemma', 'heb', 'אֶבְיָתָר', '["ʼEbyâthâr"]', '["Abiathar","[was] Abiathar"]', '["n-pr-m"]', 'Ebjathar, an Israelite Abiathar.', 'contracted from 1 and 3498; father of abundance (i.e. liberal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0054}/[H1]', 'inflected', 'heb', 'אֶבְיָתָר', '["ʼEbyâthâr"]', '["of/ Abiathar","to/ Abiathar"]', '["n-pr-m"]', 'Ebjathar, an Israelite Abiathar.', 'contracted from 1 and 3498; father of abundance (i.e. liberal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7084}/[H7049]', 'inflected', 'heb', 'קְעִילָה', '["Qᵉʻîylâh"]', '["against/ Keilah"]', '["n-pr-loc"]', 'Keilah, a place in Palestine Keilah.', 'perhaps from 7049 in the sense of enclosing; citadel;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7084}/[H7049]', 'lemma', 'heb', 'קְעִילָה', '["Qᵉʻîylâh"]', '["Keilah"]', '["n-pr-loc"]', 'Keilah, a place in Palestine Keilah.', 'perhaps from 7049 in the sense of enclosing; citadel;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3068G}\/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["by/ Yahweh"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7084}\/[H7049]', 'inflected', 'heb', 'קְעִילָה', '["Qᵉʻîylâh"]', '["Keilah"]', '["n-pr-loc"]', 'Keilah, a place in Palestine Keilah.', 'perhaps from 7049 in the sense of enclosing; citadel;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1272}/[H1272]', 'inflected', 'heb', 'בָּרַח', '["bârach"]', '["when/ fled"]', '["v"]', 'to bolt, i.e. figuratively, to flee suddenly chase (away); drive away, fain, flee (away), put to flight, make haste, reach, run away, shoot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6696A}/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["to/ lay siege"]', '["v"]', 'to cramp, i.e. confine (in many applications, literally and figuratively, formative or hostile) adversary, assault, beset, besiege, bind (up), cast, distress, fashion, fortify, inclose, lay siege, put up in bags.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0646}\/[H646]', 'inflected', 'heb', 'אֵפוֹד', '["ʼêphôwd"]', '["the/ ephod"]', '["n-m"]', 'a girdle; specifically the ephod or highpriest''s shoulder-piece; also generally, an image ephod.', 'rarely אֵפֹד; probably of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5668}/H9030/[H5674]', 'inflected', 'heb', 'עָבוּר', '["ʻâbûwr"]', '["because/ of/ me"]', '["prep"]', 'properly, crossed, i.e. (abstractly) transit; used only adverbially, on account of, in order that because of, for (...''s sake), (intent) that, to.', 'or עָבֻר; passive participle of 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5462}/H9030/[H5462]', 'inflected', 'heb', 'סָגַר', '["çâgar"]', '["¿/ will they deliver up/ me"]', '["v"]', 'to shut up; figuratively, to surrender close up, deliver (up), give over (up), inclose, × pure, repair, shut (in, self, out, up, up together), stop, × straitly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5650}/H9021\/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["to/ servant/ your"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5462}/[H5462]', 'inflected', 'heb', 'סָגַר', '["çâgar"]', '["¿/ will they deliver up"]', '["v"]', 'to shut up; figuratively, to surrender close up, deliver (up), give over (up), inclose, × pure, repair, shut (in, self, out, up, up together), stop, × straitly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0582}/H9020/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["men/ my"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5462}\/[H5462]', 'inflected', 'heb', 'סָגַר', '["çâgar"]', '["they will deliver [you] up"]', '["v"]', 'to shut up; figuratively, to surrender close up, deliver (up), give over (up), inclose, × pure, repair, shut (in, self, out, up, up together), stop, × straitly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7084}/[H7049]', 'inflected', 'heb', 'קְעִילָה', '["Qᵉʻîylâh"]', '["from/ Keilah"]', '["n-pr-loc"]', 'Keilah, a place in Palestine Keilah.', 'perhaps from 7049 in the sense of enclosing; citadel;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7586G}/[H7592]', 'inflected', 'heb', 'שָׁאוּל', '["Shâʼûwl"]', '["and/ [belonged] to/ Saul","and/ to/ Saul"]', '["n-pr-m"]', 'Shaul, the name of an Edomite and two Israelites Saul, Shaul.', 'passive participle of 7592; asked;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4679}/[H6679]', 'inflected', 'heb', 'מְצַד', '["mᵉtsad"]', '["[are] in the/ strongholds","in the/ fortress","in the/ strongholds","in/ [the] strongholds of"]', '["n-f"]', 'a fastness (as a covert of ambush) castle, fort, (strong) hold, munition.', 'or מְצָד; or (feminine) מְצָדָה; from 6679;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2128H}/[H2203]', 'lemma', 'heb', 'זִיף', '["Zîyph"]', '["Ziph"]', '["n-pr-m n-pr-loc"]', 'Ziph, the name of a place in Palestine; also of an Israelite Ziph.', 'from the same as 2203; flowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2793G}\/[H2790]', 'inflected', 'heb', 'חֹרֶשׁ', '["chôresh"]', '["at <the>/ Horesh"]', '["n-m"]', 'a forest (perhaps as furnishing the material for fabric) bough, forest, shroud, wood.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2793G}/[H2790]', 'lemma', 'heb', 'חֹרֶשׁ', '["chôresh"]', '["Horesh"]', '["n-m"]', 'a forest (perhaps as furnishing the material for fabric) bough, forest, shroud, wood.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4672}/H9031/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["I have delivered/ you","I will find/ you","he will find/ you","it has found/ you","it will find/ you"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4932H}/[H8138]', 'inflected', 'heb', 'מִשְׁנֶה', '["mishneh"]', '["<into>/ second in rank","to/ double"]', '["n-m"]', 'properly, a repetition, i.e. a duplicate (copy of a document), or a double (in amount); by implication, a second (in order, rank, age, quality or location) college, copy, double, fatlings, next, second (order), twice as much.', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2793G}/[H2790]', 'inflected', 'heb', 'חֹרֶשׁ', '["chôresh"]', '["at <the>/ Horesh"]', '["n-m"]', 'a forest (perhaps as furnishing the material for fabric) bough, forest, shroud, wood.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004B}/H9023\/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["to/ house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2130}/[H2128]', 'lemma', 'heb', 'זִיפִי', '["Zîyphîy"]', '["Ziphites"]', '["n-m"]', 'a Ziphite or inhabitant of Ziph Ziphim, Ziphite.', 'patrial from 2128;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2444}/[H2447]', 'inflected', 'heb', 'חֲכִילָה', '["Chăkîylâh"]', '["<the>/ Hakilah"]', '["n-pr-loc"]', 'Chakilah, a hill in Palestine Hachilah.', 'from the same as 2447; dark;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3225H}/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["[is] from/ [the] south of","[were] from/ [the] south","from/ [the] right","from/ [the] south"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3452G}/[H3456]', 'inflected', 'heb', 'יְשִׁימוֹן', '["yᵉshîymôwn"]', '["<the>/ Jeshimon"]', '["n-m"]', 'a desolation desert, Jeshimon, solitary, wilderness.', 'from 3456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6191}/[H6191]', 'lemma', 'heb', 'עָרַם', '["ʻâram"]', '["certainly <to be crafty>","he is crafty","he is prudent","he will become prudent","they make crafty"]', '["v"]', 'properly, to be (or make) bare; but used only in the derivative sense (through the idea perhaps of smoothness) to be cunning (usually in a bad sense) × very, beware, take crafty (counsel), be prudent, deal subtilly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7200I}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ look at","and/ see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4224B}/[H2244]', 'inflected', 'heb', 'מַחֲבֵא', '["machăbêʼ"]', '["the/ hiding places"]', '["n-m"]', 'a refuge hiding (lurking) place.', 'or מַחֲבֹא; from 2244;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2128H}/H9011/[H2203]', 'inflected', 'heb', 'זִיף', '["Zîyph"]', '["Ziph/ towards"]', '["n-pr-m n-pr-loc"]', 'Ziph, the name of a place in Palestine; also of an Israelite Ziph.', 'from the same as 2203; flowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3225H}/[H3231]', 'lemma', 'heb', 'יָמִין', '["yâmîyn"]', '["[the] south of"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5849A}/[H5849]', 'lemma', 'heb', 'עָטַר', '["ʻâṭar"]', '["[were] surrounding"]', '["v"]', 'to encircle (for attack or protection); especially to crown (literally or figuratively) compass, crown.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8610}/H9038/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["to/ catch/ them"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4116A}/H9012/[H4116]', 'inflected', 'heb', 'מָהַר', '["mâhar"]', '["bring quickly/ !","make haste/ !"]', '["v"]', 'properly, to be liquid or flow easily, i.e. (by implication); to hurry (in a good or a bad sense); often used (with another verb) adverbially, promptly be carried headlong, fearful, (cause to make, in, make) haste(-n, -ily), (be) hasty, (fetch, make ready) × quickly, rash, × shortly, (be so) × soon, make speed, × speedily, × straightway, × suddenly, swift.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1980H}/H9012/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ come/ !"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7291}/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["from/ pursuing"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5555}/[H5553]', 'lemma', 'heb', 'סֶלַע הַמַּחְלְקוֹת', '["Çelaʻ ham-machlᵉqôwth"]', '["Hammahlekoth","Sela"]', '["n-pr-loc"]', 'Sela-ham-Machlekoth, a place in Palestine Sela-hammalekoth.', 'from 5553 and the plural of 4256 with the article interposed; rock of the divisions;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5872}\/[H5869]', 'inflected', 'heb', 'עֵין גֶּדִי', '["ʻÊyn Gedîy"]', '["Gedi"]', '["n-pr-loc"]', 'En-Gedi, a place in Palestine En-gedi.', 'from 5869 and 1423; fountain of a kid;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6697G}/[H6696]', 'lemma', 'heb', 'צוּר', '["tsûwr"]', '["[the] rocks of"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3277G}/[H3276]', 'inflected', 'heb', 'יָעֵל', '["yâʻêl"]', '["the/ mountain goats"]', '["n-m"]', 'an ibex (as climbing) wild goat.', 'from 3276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5526B}/[H5526]', 'inflected', 'heb', 'סָכַךְ', '["çâkak"]', '["to/ cover"]', '["v"]', 'properly, to entwine as a screen; by implication, to fence in, cover over, (figuratively) protect cover, defence, defend, hedge in, join together, set, shut up.', 'or שָׂכַךְ; (Exodus 33:22), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7586G}\/[H7592]', 'inflected', 'heb', 'שָׁאוּל', '["Shâʼûwl"]', '["[belonged] to/ Saul"]', '["n-pr-m"]', 'Shaul, the name of an Edomite and two Israelites Saul, Shaul.', 'passive participle of 7592; asked;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0582}/H9023/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["to/ men/ his"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4899}/[H4886]', 'inflected', 'heb', 'מָשִׁיחַ', '["mâshîyach"]', '["to/ [the] [one] anointed of"]', '["n-m"]', 'anointed; usually a consecrated person (as a king, priest, or saint); specifically, the Messiah anointed, Messiah.', 'from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4899}/[H4886]', 'lemma', 'heb', 'מָשִׁיחַ', '["mâshîyach"]', '["[is] [the] [one] anointed of","[the] [one] anointed of","[was] anointed","an anointed [one]"]', '["n-m"]', 'anointed; usually a consecrated person (as a king, priest, or saint); specifically, the Messiah anointed, Messiah.', 'from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H4631}/[H5783]', 'inflected', 'heb', 'מְעָרָה', '["mᵉʻârâh"]', '["from/ the/ cave"]', '["n-f"]', 'a cavern (as dark) cave, den, hole.', 'from 5783;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870L}\/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["on the/ way"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7812}\/[H7812]', 'inflected', 'heb', 'שָׁחָה', '["shâchâh"]', '["and/ he bowed down","and/ they bowed down"]', '["v"]', 'to depress, i.e. prostrate (especially reflexive, in homage to royalty or God) bow (self) down, crouch, fall down (flat), humbly beseech, do (make) obeisance, do reverence, make to stoop, worship.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451C}/H9021/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["calamity/ your","evil/ your","harm/ your"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2347}/[H2347]', 'inflected', 'heb', 'חוּס', '["chûwç"]', '["and/ it looked with compassion"]', '["v"]', 'properly, to cover, i.e. (figuratively) to compassionate pity, regard, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0113>/H9020', 'inflected', 'heb', 'באדני', '["ba./do.N/i"]', '["against/ lord/ my","on/ lord/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0001G}/H9020/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ O father/ my","and/ father/ my","and/ fathers/ my"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4598}/H9021/[H4603]', 'inflected', 'heb', 'מְעִיל', '["mᵉʻîyl"]', '["robe/ your"]', '["n-m"]', 'a robe (i.e. upper and outer garment) cloke, coat, mantle, robe.', 'from 4603 in the sense of covering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3772G}/H9040/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["when/ cut off/ I"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2026}/H9031/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["I killed/ you","killer/ your"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3947G}/H9034/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["to/ take away/ it","to/ take/ it"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5358}/H9030/[H5358]', 'inflected', 'heb', 'נָקַם', '["nâqam"]', '["and/ he will avenge/ me"]', '["v"]', 'to grudge, i.e. avenge or punish avenge(-r, self), punish, revenge (self), × surely, take vengeance.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3027G}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ hand/ my","and/ hands/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4912}/[H4910]', 'lemma', 'heb', 'מָשָׁל', '["mâshâl"]', '["[are] [the] proverbs of","[are] proverbs of","[the] proverb of","[the] proverbs of","a byword","a parable","a proverb","a saying","parables","proverb[s]","proverbs"]', '["n-m"]', 'properly, a pithy maxim, usually of metaphorical nature; hence, a simile (as an adage, poem, discourse) byword, like, parable, proverb.', 'apparently from 4910 in some original sense of superiority in mental action;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6931H}/[H6930]', 'inflected', 'heb', 'קַדְמוֹנִי', '["qadmôwnîy"]', '["the/ ancient[s]"]', '["a"]', '(of time) anterior or (of place) oriental ancient, they that went before, east, (thing of) old.', 'or קַדְמֹנִי; from 6930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7563}/[H7561]', 'inflected', 'heb', 'רָשָׁע', '["râshâʻ"]', '["from/ [the] wicked","from/ wicked [people]"]', '["a"]', 'morally wrong; concretely, an (actively) bad person condemned, guilty, ungodly, wicked (man), that did wrong.', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7562}/[H7561]', 'lemma', 'heb', 'רֶשַׁע', '["reshaʻ"]', '["wickedness"]', '["n-m"]', 'a wrong (especially moral) iniquity, wicked(-ness).', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6550}/[H6544]', 'lemma', 'heb', 'פַּרְעֹשׁ', '["parʻôsh"]', '["a flea"]', '["n-m"]', 'a flea (as the isolated insect) flea.', 'probably from 6544 and 6211;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1781}/[H1777]', 'inflected', 'heb', 'דַּיָּן', '["dayân"]', '["<into>/ a judge"]', '["n-m"]', 'a judge or advocate judge.', 'from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7378}/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["and/ may he conduct"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7379}/H9020/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["case/ my"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8199}/H9030/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["and/ may he vindicate/ me"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027H}/H9021\/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/<H6963A>/H9021', 'inflected', 'heb', 'הקולך', '["ha./ko.le./Cha","ha./kol./Cha"]', '["¿/ voice/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1580}/H9030/[H1580]', 'inflected', 'heb', 'גָּמַל', '["gâmal"]', '["he dealt with/ me","he has dealt with/ me","will he reward/ me","you have dealt out to/ me"]', '["v"]', 'to treat a person (well or ill), i.e. benefit or requite; by implication (of toil), to ripen, i.e. (specifically) to wean bestow on, deal bountifully, do (good), recompense, requite, reward, ripen, serve, mean, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5462}/H9030/[H5462]', 'inflected', 'heb', 'סָגַר', '["çâgar"]', '["he delivered up/ me","he delivers up/ me","you delivered up/ me","you will deliver up/ me"]', '["v"]', 'to shut up; figuratively, to surrender close up, deliver (up), give over (up), inclose, × pure, repair, shut (in, self, out, up, up together), stop, × straitly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971H}/H9033/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ I gave over/ it","and/ he has sent away/ him","and/ he let go/ him","and/ will he send away?/ him","and/ you will let go/ him"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7999A}/H9031/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["may he reward/ you"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4686B}\/[H4685]', 'inflected', 'heb', 'מָצוּד', '["mâtsûwd"]', '["the/ stronghold"]', '["n-f"]', 'a net, or (abstractly) capture; also a fastness castle, defense, fort(-ress), (strong) hold, be hunted, net, snare, strong place.', 'or (feminine) מְצוּדָה; or מְצֻדָה; for 4685;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6912}/H9033/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["and/ people buried/ him","and/ they buried/ him","and/ they had buried/ him","and/ you will bury/ him"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4584G}/[H4583]', 'inflected', 'heb', 'מָעוֹן', '["Mâʻôwn"]', '["[was] in/ Maon"]', '["n-pr-m n-pr-loc"]', 'Maon, the name of an Israelite and of a place in Palestine Maon, Maonites. Compare 1010, 4586.', 'the same as 4583; a residence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1494}/[H1468]', 'inflected', 'heb', 'גָּזַז', '["gazâz"]', '["when/ sheared"]', '["v"]', 'to cut off; specifically to shear a flock or shave the hair; figuratively to destroy an enemy cut off (down), poll, shave, (sheep-) shear(-er).', 'a primitive root (akin to 1468);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5037}/[H5036]', 'lemma', 'heb', 'נָבָל', '["Nâbâl"]', '["Nabal","[is] Nabal","[was] Nabal"]', '["n-pr-m"]', 'Nabal, an Israelite Nabal.', 'the same as 5036; dolt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0026G}/[H1]', 'lemma', 'heb', 'אֲבִיגַיִל', '["ʼĂbîygayil"]', '["Abigail","[was] Abigail"]', '["n-pr-f"]', 'Abigail or Abigal, the name of two Israelitesses Abigal.', 'or shorter אֲבִיגַל; from 1 and 1524; father (i.e. source) of joy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7922}/[H7919]', 'lemma', 'heb', 'שֶׂכֶל', '["sekel"]', '["[the] prudence of","[the] sense","an understanding","insight","understanding"]', '["n-m"]', 'intelligence; by implication, success discretion, knowledge, policy, prudence, sense, understanding, wisdom, wise.', 'or שֵׂכֶל; from 7919;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4611}/[H5953]', 'lemma', 'heb', 'מַעֲלָל', '["maʻălâl"]', '["[the] deeds of","deeds"]', '["n-m"]', 'an act (good or bad) doing, endeavour, invention, work.', 'from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3614}/[H3612]', 'lemma', 'heb', 'כָּלִבּוֹ', '["Kâlibbôw"]', '["[was] a Calebite"]', '["a"]', 'a Calebite or descendant of Caleb of the house of Caleb.', 'probably by erroneous transcription for כָּלֵבִי; patronymically from 3612;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3760G}/H9011/[H3759]', 'inflected', 'heb', 'כַּרְמֶל', '["Karmel"]', '["Carmel/ towards"]', '["n-pr-loc"]', 'Karmel, the name of a hill and of a town in Palestine Carmel, fruitful (plentiful) field, (place).', 'the same as 3759;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2416A}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["to the/ living [one]"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7965K}/[H7999]', 'lemma', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["[the] welfare of","peace"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3637}/H9038/[H3637]', 'inflected', 'heb', 'כָּלַם', '["kâlam"]', '["we have humiliated/ them"]', '["v"]', 'properly, to wound; but only figuratively, to taunt or insult be (make) ashamed, blush, be confounded, be put to confusion, hurt, reproach, (do, put to) shame.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6555}/[H6555]', 'inflected', 'heb', 'פָּרַץ', '["pârats"]', '["the/ [one who] breaks through","the/ broken down [parts]","which/ was broken down","who/ break away"]', '["v"]', 'to break out (in many applications, direct and indirect, literal and figurative) × abroad, (make a) breach, break (away, down, -er, forth, in, up), burst out, come (spread) abroad, compel, disperse, grow, increase, open, press, scatter, urge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3899H}/H9020/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["<of> food/ my","bread/ my","food/ my"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4325G}/H9020/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["water/ my"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2878}/H9020/[H2874]', 'inflected', 'heb', 'טִבְחָה', '["ṭibchâh"]', '["slaughter/ my"]', '["n-f"]', 'flesh, slaughter.', 'feminine of 2874 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1494}/H9030/[H1468]', 'inflected', 'heb', 'גָּזַז', '["gazâz"]', '["for/ shearers/ my"]', '["v"]', 'to cut off; specifically to shear a flock or shave the hair; figuratively to destroy an enemy cut off (down), poll, shave, (sheep-) shear(-er).', 'a primitive root (akin to 1468);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0026G}/[H1]', 'inflected', 'heb', 'אֲבִיגַיִל', '["ʼĂbîygayil"]', '["and/ to/ Abigail"]', '["n-pr-f"]', 'Abigail or Abigal, the name of two Israelitesses Abigal.', 'or shorter אֲבִיגַל; from 1 and 1524; father (i.e. source) of joy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5860A}/[H5860]', 'inflected', 'heb', 'עִיט', '["ʻîyṭ"]', '["and/ he shouted"]', '["v"]', 'to swoop down upon (literally or figuratively) fly, rail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1961}/H9045/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["when/ were/ we"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1961}/H9045/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["being/ we"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6778}/[H6784]', 'lemma', 'heb', 'צַמּוּק', '["tsammûwq"]', '["bunches of raisins"]', '["n-m"]', 'a cake of dried grapes bunch (cluster) of raisins.', 'from 6784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1690>', 'opaque', 'heb', 'דְּבֵלָה', '["dᵉbêlâh"]', '["a cake of","fig cake","fig cakes"]', '["n-f"]', 'a cake of pressed figs cake (lump) of figs.', 'from an unused root (akin to 2082) probably meaning to press together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5288}/H9024/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["to/ servants/ her"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H0376H>/H9024', 'inflected', 'heb', 'ולאישה', '["u./le./''i.Sha/h"]', '["and/ to/ husband/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122H}/H9034/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ her"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6298}/[H6298]', 'inflected', 'heb', 'פָּגַשׁ', '["pâgash"]', '["and/ she met","and/ they will meet"]', '["v"]', 'to come in contact with, whether by accident or violence; figuratively, to concur meet (with, together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0341}/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["<into>/ enemies","[belongs] to/ [the] enemy","into/ an enemy","to/ [the] enemies","to/ an enemy"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8366}/[H8366]', 'lemma', 'heb', 'שָׁתַן', '["shâthan"]', '["[one who] urinates"]', '["v"]', '(causatively) to make water, i.e. urinate piss.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0639I}/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["to/ [the] face of"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5771H}/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["the/ iniquity"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241I}/H9021/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["in/ ears/ your"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1100G}/[H1097]', 'inflected', 'heb', 'בְּלִיַּעַל', '["bᵉlîyaʻal"]', '["<the>/ worthlessness"]', '["n-m"]', 'without profit, worthlessness; by extension, destruction, wickedness Belial, evil, naughty, ungodly (men), wicked.', 'from 1097 and 3276;(often in connection with 376, 802, 1121, etc.)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8034}/H9023/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["like/ name/ his"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3467}/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ I have saved","and/ [from] delivering","and/ [is] a deliverer","and/ a deliverer","and/ be saved","and/ certainly <to deliver>","and/ victorious","and/ you may save","so/ let me be saved","so/ let us be delivered","so/ may he deliver","so/ we may be saved?"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5037}/[H5036]', 'inflected', 'heb', 'נָבָל', '["Nâbâl"]', '["like/ Nabal"]', '["n-pr-m"]', 'Nabal, an Israelite Nabal.', 'the same as 5036; dolt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1245}/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["and/ those/ [who] seek"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7272}/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["at/ [the] feet of","on/ foot","with/ a foot","with/ feet"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7451I}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["and/ [the] evil deeds of","and/ [the] harm of","and/ an evil","and/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3117G>/H9021', 'inflected', 'heb', 'מימיך', '["mi./ya.Mei./kha"]', '["from/ days/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7291}/H9031/[H7291]', 'inflected', 'heb', 'רָדַף', '["râdaph"]', '["to/ pursue/ you"]', '["v"]', 'to run after (usually with hostile intent; figuratively [of time] gone by) chase, put to flight, follow (after, on), hunt, (be under) persecute(-ion, -or), pursue(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1245}/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["and/ to/ request","and/ to/ seek"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6872A}/[H6887]', 'inflected', 'heb', 'צְרוֹר', '["tsᵉrôwr"]', '["in/ [the] bundle of","in/ a bag"]', '["n-m"]', 'a parcel (as packed up); also a kernel or particle (as if a package) bag, × bendeth, bundle, least grain, small stone.', 'or (shorter) צְרֹר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7049A}/H9034/[H7049]', 'inflected', 'heb', 'קָלַע', '["qâlaʻ"]', '["he will sling out/ it"]', '["v"]', 'to sling; also to carve (as if a circular motion, or into light forms) carve, sling (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7050A}/[H7049]', 'inflected', 'heb', 'קֶלַע', '["qelaʻ"]', '["<the>/ sling"]', '["n-m"]', 'a sling; also a (door) screen (as if slung across), or the valve (of the door) itself hanging, leaf, sling.', 'from 7049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6330}/[H6328]', 'inflected', 'heb', 'פּוּקָה', '["pûwqâh"]', '["<into>/ staggering"]', '["n-f"]', 'a stumbling-block grief.', 'from 6328;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4383}/[H3782]', 'inflected', 'heb', 'מִכְשׁוֹל', '["mikshôwl"]', '["and/ <into>/ stumbling of"]', '["n-m"]', 'a stumbling-block, literally or figuratively (obstacle, enticement (specifically an idol), scruple) caused to fall, offence, × (no-) thing offered, ruin, stumbling-block.', 'or מִכְשֹׁל; masculine from 3782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8210H}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["and/ <into>/ pouring out of"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3467}/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ to/ deliver"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0519}/H9021\/[H519]', 'inflected', 'heb', 'אָמָה', '["ʼâmâh"]', '["maidservant/ your"]', '["n-f"]', 'a maid-servant or female slave (hand-) bondmaid(-woman), maid(-servant).', 'apparently a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0026G}/[H1]', 'inflected', 'heb', 'אֲבִיגַיִל', '["ʼĂbîygayil"]', '["of/ Abigail","to/ Abigail"]', '["n-pr-f"]', 'Abigail or Abigal, the name of two Israelitesses Abigal.', 'or shorter אֲבִיגַל; from 1 and 1524; father (i.e. source) of joy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7971G}/H9032/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["he has sent/ you"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2940}/H9022/[H2938]', 'inflected', 'heb', 'טַעַם', '["ṭaʻam"]', '["discernment/ your"]', '["n-m"]', 'properly, a taste, i.e. (figuratively) perception; by implication, intelligence; transitively, a mandate advice, behaviour, decree, discretion, judgment, reason, taste, understanding.', 'from 2938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3607}/H9030/[H3607]', 'inflected', 'heb', 'כָּלָא', '["kâlâʼ"]', '["you have restrained/ me"]', '["v"]', 'to restrict, by act (hold back or in) or word (prohibit) finish, forbid, keep (back), refrain, restrain, retain, shut up, be stayed, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027I}/H9020/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ my","hands/ my"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4513}/H9030/[H4513]', 'inflected', 'heb', 'מָנַע', '["mânaʻ"]', '["he has restrained/ me","he will withhold/ me"]', '["v"]', 'to debar (negatively or positively) from benefit or injury deny, keep (back), refrain, restrain, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7489A}/[H7489]', 'inflected', 'heb', 'רָעַע', '["râʻaʻ"]', '["from/ doing harm to"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5037}/[H5036]', 'inflected', 'heb', 'נָבָל', '["Nâbâl"]', '["to/ Nabal"]', '["n-pr-m"]', 'Nabal, an Israelite Nabal.', 'the same as 5036; dolt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027H}/H9024/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ her"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963A>/H9022', 'inflected', 'heb', 'בקולך', '["ve./ko.Le/kh"]', '["to/ voice/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375Q}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ I have lifted up","and/ she bore"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440N}/H9022/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4960}/[H8354]', 'inflected', 'heb', 'מִשְׁתֶּה', '["mishteh"]', '["like/ [the] feast of"]', '["n-m"]', 'drink, by implication, drinking (the act); also (by implication) a banquet or (generally) feast banquet, drank, drink, feast((-ed), -ing).', 'from 8354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3820A}/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["and/ [is] heart","and/ [the] heart","and/ [the] heart of","and/ a heart","and/ a heart of","and/ heart"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7910}/[H7937]', 'lemma', 'heb', 'שִׁכּוֹר', '["shikkôwr"]', '["[the] drunkards of","[was] drunk","a drunkard","drunken"]', '["a"]', 'intoxicated, as a state or a habit drunk(-ard, -en, -en man).', 'or שִׁכֹּר; from 7937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1419A}/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["and/ [is] great","and/ [was] great","and/ a great [man]","and/ great","and/ great of","and/ large"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5037}/[H5036]', 'inflected', 'heb', 'נָבָל', '["Nâbâl"]', '["from/ Nabal"]', '["n-pr-m"]', 'Nabal, an Israelite Nabal.', 'the same as 5036; dolt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7451I}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["from/ [the] evil of","from/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0026G}/[H1]', 'inflected', 'heb', 'אֲבִיגַיִל', '["ʼĂbîygayil"]', '["with/ Abigail"]', '["n-pr-f"]', 'Abigail or Abigal, the name of two Israelitesses Abigal.', 'or shorter אֲבִיגַל; from 1 and 1524; father (i.e. source) of joy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3947I}/H9032/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["to/ take/ you"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5291}/H9024/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["female servants/ her","maids/ her","servant girls/ her"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7272}/H9024/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["to/ foot/ her"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0293H}/[H251]', 'lemma', 'heb', 'אֲחִינֹעַם', '["ʼĂchîynôʻam"]', '["Ahinoam"]', '["n-pr-f"]', 'Achinoam, the name of two Israelitesses Ahinoam.', 'from 251 and 5278; brother of pleasantness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3157G}/[H2232]', 'inflected', 'heb', 'יִזְרְעֵאל', '["Yizrᵉʻêʼl"]', '["from/ Jezreel"]', '["n-pr-m n-pr-loc"]', 'Jizreel, the name of two places in Palestine and of two Israelites Jezreel.', 'from 2232 and 410; God will sow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8147}/H9029/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["both of/ them"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6406H}/[H6403]', 'inflected', 'heb', 'פַּלְטִי', '["Palṭîy"]', '["to/ Palti"]', '["n-pr-m"]', 'Palti, the name of two Israelites Palti, Phalti.', 'from 6403; delivered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3919B}/[H3918]', 'lemma', 'heb', 'לַיִשׁ', '["Layish"]', '["Laish"]', '["n-pr-m n-pr-loc"]', 'Laish, the name of two places in Palestine Laish. Compare 3889.', 'the same as 3918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1554}/[H1530]', 'inflected', 'heb', 'גַּלִּים', '["Gallîym"]', '["[was] from/ Gallim"]', '["n-pr-loc"]', 'Gallim, a place in Palestine Gallim.', 'plural of 1530; springs;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2130}/[H2128]', 'inflected', 'heb', 'זִיפִי', '["Zîyphîy"]', '["the/ Ziphites"]', '["n-m"]', 'a Ziphite or inhabitant of Ziph Ziphim, Ziphite.', 'patrial from 2128;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0074}/[H1]', 'inflected', 'heb', 'אַבְנֵר', '["ʼAbnêr"]', '["and/ Abner"]', '["n-pr-m"]', 'Abner, an Israelite Abner.', 'or (fully) אֲבִינֵר ; from 1 and 5216; father of light (i.e. enlightening);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4570}/[H5696]', 'inflected', 'heb', 'מַעְגָּל', '["maʻgâl"]', '["in the/ camp","in/ tracks of"]', '["n-m"]', 'a track (literally or figuratively); also a rampart (as circular) going, path, trench, way(-side).', 'or feminine מַעְגָּלָה; from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439G}/H9033/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["[are] around/ him","[are] around/ it","[those] around/ him","around/ him","around/ it","circuits/ its"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0288H}/[H251]', 'lemma', 'heb', 'אֲחִימֶלֶךְ', '["ʼĂchîymelek"]', '["Ahimelech"]', '["n-pr-m"]', 'Achimelek, the name of an Israelite and of a Hittite Ahimelech.', 'from 251 and 4428; brother of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0052}/[H1]', 'lemma', 'heb', 'אֲבִישַׁי', '["ʼĂbîyshay"]', '["Abishai","Abshai"]', '["n-pr-m"]', 'Abishai, an Israelite Abishai.', 'or (shorter) אַבְשַׁי ; from 1 and 7862; father of a gift (i.e. probably generous);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6870}/[H6875]', 'lemma', 'heb', 'צְרוּיָה', '["Tsᵉrûwyâh"]', '["Zeruiah"]', '["n-pr-f"]', 'Tserujah, an Israelitess Zeruiah.', 'feminine passive participle from the same as 6875; wounded;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3097G}/[H3068]', 'lemma', 'heb', 'יוֹאָב', '["Yôwʼâb"]', '["Joab"]', '["n-pr-m"]', 'Joab, the name of three Israelites Joab.', 'from 3068 and 1; Jehovah-fathered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0052}/[H1]', 'inflected', 'heb', 'אֲבִישַׁי', '["ʼĂbîyshay"]', '["and/ Abishai"]', '["n-pr-m"]', 'Abishai, an Israelite Abishai.', 'or (shorter) אַבְשַׁי ; from 1 and 7862; father of a gift (i.e. probably generous);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3463}/[H3462]', 'lemma', 'heb', 'יָשֵׁן', '["yâshên"]', '["[is] sleeping","[was] sleeping","[were] sleeping","sleepers","sleeping"]', '["a"]', 'sleepy asleep, (one out of) sleep(-eth, -ing), slept.', 'from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4600}/[H4600]', 'lemma', 'heb', 'מָעַךְ', '["mâʻak"]', '["[was] thrust","they were handled"]', '["v"]', 'to press, i.e. to pierce, emasculate, handle bruised, stuck, be pressed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5439G}/H9033\/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["around/ him","around/ it"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H0776H>', 'inflected', 'heb', 'ובארץ', '["u./va./''A.retz"]', '["and/ in the/ ground"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7843}/H9033/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["you destroy/ him","you destroy/ it"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4899}/[H4886]', 'inflected', 'heb', 'מָשִׁיחַ', '["mâshîyach"]', '["on/ [the] [one] anointed of"]', '["n-m"]', 'anointed; usually a consecrated person (as a king, priest, or saint); specifically, the Messiah anointed, Messiah.', 'from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5352}\/[H5352]', 'inflected', 'heb', 'נָקָה', '["nâqâh"]', '["and/ will he be free from guilt?"]', '["v"]', 'to be (or make) clean (literally or figuratively); by implication (in an adverse sense) to be bare, i.e. extirpated acquit × at all, × altogether, be blameless, cleanse, (be) clear(-ing), cut off, be desolate, be free, be (hold) guiltless, be (hold) innocent, × by no means, be quit, be (leave) unpunished, × utterly, × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5062}/H9033/[H5062]', 'inflected', 'heb', 'נָגַף', '["nâgaph"]', '["he struck/ him","he will strike/ him"]', '["v"]', 'to push, gore, defeat, stub (the toe), inflict (a disease) beat, dash, hurt, plague, slay, smite (down), strike, stumble, × surely, put to the worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5595}/[H5595]', 'inflected', 'heb', 'סָפָה', '["çâphâh"]', '["and/ he will be carried away","and/ people will snatch away"]', '["v"]', 'properly, to scrape (literally, to shave; but usually figuratively) together (i.e. to accumulate or increase) or away (i.e. to scatter, remove, or ruin; intransitively, to perish) add, augment, consume, destroy, heap, join, perish, put.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7971K}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["from/ stretching out"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6835>', 'opaque', 'heb', 'צַפַּחַת', '["tsappachath"]', '["[the] jug of"]', '["n-f"]', 'a saucer (as flat) cruse.', 'from an unused root meaning to expand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7226}/[H7218]', 'lemma', 'heb', 'רַאֲשֹׁת', '["raʼăshôth"]', '["[at the] head of"]', '["n-f"]', 'a pillow (being for the head) bolster.', 'from 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6974}/[H3364]', 'lemma', 'heb', 'קוּץ', '["qûwts"]', '["I awoke","[was one who] awoke","awake","he has awakened","it has awakened","they will awake","will I awake"]', '["v"]', 'to awake (literally or figuratively) arise, (be) (a-) wake, watch.', 'a primitive root (identical with through the idea of abruptness in starting up from sleep (compare 3364));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5676G}/[H5674]', 'inflected', 'heb', 'עֵבֶר', '["ʻêber"]', '["the/ other side"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0113>/H9026', 'opaque', 'heb', 'אָדוֹן', '["ʼâdôwn"]', '["lord<s>/ your","master<s>/ your","masters/ your"]', '["n-m"]', 'sovereign, i.e. controller (human or divine) lord, master, owner. Compare also names beginning with ''Adoni-''.', 'or (shortened) אָדֹן; from an unused root (meaning to rule);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1644G}/H9030/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["they have driven out/ me"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5596A}/[H5596]', 'inflected', 'heb', 'סָפַח', '["çâphach"]', '["from/ having a share"]', '["v"]', 'properly, to scrape out, but in certain peculiar senses (of removal or association) abiding, gather together, cleave, smite with the scab.', 'or שָׂפַח; (Isaiah 3:17), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1818}/H9020/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["blood/ my"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7124}/[H7121]', 'inflected', 'heb', 'קֹרֵא', '["qôrêʼ"]', '["the/ partridge"]', '["n-m"]', 'a caller, i.e. partridge (from its cry) partridge. See also 6981.', 'properly, active participle of 7121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3365}/[H3365]', 'lemma', 'heb', 'יָקַר', '["yâqar"]', '["I was valued","I will make precious","it was precious","let it be precious","make rare","they are precious","you are precious"]', '["v"]', 'properly, apparently, to be heavy, i.e. (figuratively) valuable; causatively, to make rare (figuratively, to inhibit) be (make) precious, be prized, be set by, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7686}/[H7686]', 'inflected', 'heb', 'שָׁגָה', '["shâgâh"]', '["and/ I have gone astray"]', '["v"]', 'to stray (causatively, mislead), usually (figuratively) to mistake, especially (morally) to transgress; by extension (through the idea of intoxication) to reel, (figuratively) be enraptured (cause to) go astray, deceive, err, be ravished, sin through ignorance, (let, make to) wander.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3947G}/H9034/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ let him take/ it"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6666}/H9023/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["righteousness/ his","righteousness<es>/ his"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0530}/H9023/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["faithfulness/ his"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5337}/H9030/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ deliver/ me","and/ may he deliver/ me"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6869B}\/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["trouble"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4725}/H9023\/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["to/ own place/ his","to/ place/ his"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2976}/[H2976]', 'inflected', 'heb', 'יָאַשׁ', '["yâʼash"]', '["and/ he will desist"]', '["v"]', 'to desist, i.e. (figuratively) to despond (cause to) despair, one that is desperate, be no hope.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1245}/H9030/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["to/ seek/ me"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4582}/[H4600]', 'lemma', 'heb', 'מָעוֹךְ', '["Mâʻôwk"]', '["Maoch"]', '["n-pr-m"]', 'Maok, a Philistine Maoch.', 'from 4600; oppressed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3158G}/[H3157]', 'inflected', 'heb', 'יִזְרְעֵאלִי', '["Yizrᵉʻêʼlîy"]', '["the/ Jezreelite [woman]"]', '["a"]', 'a Jizreelite or native of Jizreel Jezreelite.', 'patronymically from 3157;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0026G}/[H1]', 'inflected', 'heb', 'אֲבִיגַיִל', '["ʼĂbîygayil"]', '["and/ Abigail"]', '["n-pr-f"]', 'Abigail or Abigal, the name of two Israelitesses Abigal.', 'or shorter אֲבִיגַל; from 1 and 1524; father (i.e. source) of joy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3761}/[H3760]', 'inflected', 'heb', 'כַּרְמְלִי', '["Karmᵉlîy"]', '["the/ Carmelite","the/ Carmelite [woman]"]', '["a"]', 'a Karmelite or inhabitant of Karmel (the town) Carmelite.', 'patron from 3760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1245}/H9033\/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["to/ seek/ him"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6860>', 'opaque', 'heb', 'צִקְלַג', '["Tsiqlag"]', '["Ziklag"]', '["n-pr-loc"]', 'Tsiklag or Tsikelag, a place in Palestine Ziklag.', 'or צִיקלַג; (1 Chronicles 12:1,20), of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1511}/[H1507]', 'inflected', 'heb', 'גִּזְרִי', '["Gizrîy"]', '["and/ the/ Gizrite[s]"]', '["a"]', 'a Grizite (collectively) or member of a native tribe in Palestine Gezrites.', '(in the m patrial from 1507; a Gezerite (collectively) or inhabitants of Gezer; but better (as in the text) bytransposition גִּזְרִיxlit Girzîy corrected to Gizrîy; patrial of 1630;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7793}/H9011/[H7791]', 'inflected', 'heb', 'שׁוּר', '["Shûwr"]', '["Shur/ towards"]', '["n-pr-loc"]', 'Shur, a region of the Desert Shur.', 'the same as 7791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3397}/[H3396]', 'inflected', 'heb', 'יְרַחְמְאֵלִי', '["Yᵉrachmᵉʼêlîy"]', '["the/ Jerahmeelite[s]"]', '["a"]', 'a Jerachmeelite or descendant of Jerachmeel Jerahmeelites.', 'patronymically from 3396;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941J}/H9023/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["plans/ its","practice/ his"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5971A}/H9023/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["[is] among/ people/ his","among/ people/ his","in/ people/ his","on/ people/ his"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0582}/H9021/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["and/ men/ your"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7218A>/H9020', 'inflected', 'heb', 'לראשי', '["le./ro.Sh/i"]', '["<to>/ head/ my","of/ head/ my","to/ head/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5892B}/H9023/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["<and>/ in/ own city/ his","and/ in/ cities/ its"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/<H0776G>', 'inflected', 'heb', 'מהארץ', '["me./ha./''A.retz"]', '["from/ the/ land"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7766}/[H7764]', 'inflected', 'heb', 'שׁוּנֵם', '["Shûwnêm"]', '["at/ Shunem"]', '["n-pr-loc"]', 'Shunem, a place in Pal Shunem.', 'probably from the same as 7764; quietly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1533G}/[H1530]', 'inflected', 'heb', 'גִּלְבֹּעַ', '["Gilbôaʻ"]', '["at <the>/ Gilboa","in <the>/ Gilboa","on <the>/ Gilboa"]', '["n-pr-loc"]', 'Gilboa, a mountain of Palestine Gilboa.', 'from 1530 and 1158; fountain of ebullition;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0224}/[H217]', 'inflected', 'heb', 'אוּרִים', '["ʼÛwrîym"]', '["by <the>/ Urim"]', '["n-m"]', 'Urim, the oracular brilliancy of the figures in the high-priest''s breastplate Urim.', 'plural of 217; lights;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1172}/[H1167]', 'lemma', 'heb', 'בַּעֲלָה', '["baʻălâh"]', '["[the] mistress of","[the] owner of","an owner of"]', '["n-f"]', 'a mistress that hath, mistress.', 'feminine of 1167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5874}/[H5869]', 'inflected', 'heb', 'עֵין־דֹּאר', '["ʻÊyn-Dôʼr"]', '["[is] in/ En-","at/ En-"]', '["n-pr-loc"]', 'En-Dor, a place in Palestine En-dor.', 'or עֵין דּוֹר; or עֵין־דֹּר; from 5869 and 1755; fountain of dwelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0178}/[H1]', 'inflected', 'heb', 'אוֹב', '["ʼôwb"]', '["by <the>/ necromancy"]', '["n-m"]', 'properly, a mumble, i.e. a water-skin (from its hollow sound); hence a necromancer (ventriloquist, as from a jar) bottle, familiar spirit.', 'from the same as 1 (apparently through the idea of prattling a father''s name);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315H}/H9020/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["on/ life/ my"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7136A}/H9032/[H7136]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["it will happen to/ you"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771I}/[H5753]', 'lemma', 'heb', 'עָוֺן', '["ʻâvôn"]', '["[is] iniquities of","[the] iniquity of","iniquity","punishment","punishment of"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8389}/H9023/[H8388]', 'inflected', 'heb', 'תֹּאַר', '["tôʼar"]', '["[is] appearance/ his"]', '["n-m"]', 'outline, i.e. figure or appearance beautiful, × comely, countenance, fair, × favoured, form, × goodly, × resemble, visage.', 'from 8388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7264}/H9030/[H7264]', 'inflected', 'heb', 'רָגַז', '["râgaz"]', '["have you disturbed/ me"]', '["v"]', 'to quiver (with any violent emotion, especially anger or fear) be afraid, stand in awe, disquiet, fall out, fret, move, provoke, quake, rage, shake, tremble, trouble, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5927H}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["by/ bringing up","to/ bring up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6030B}/H9030/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["[which] he will answer/ me","answer/ me","he answered/ me","he has answered/ me","it answers/ me","let him answer/ me","you answer/ me","you answered/ me","you have answered/ me","you will answer/ me"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7121G}/H9012/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ I have summoned/ !"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3045}/H9030/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["to/ [those who] know/ me","to/ make known to/ me"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7592}/H9030/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["ask/ me","do you ask/ me","they ask/ me"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6145}/H9021/[H5782]', 'inflected', 'heb', 'עָר', '["ʻâr"]', '["enemies/ your","enemy/ your"]', '["n-m"]', 'a foe (as watchful for mischief) enemy.', 'from 5782;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963J>/H9021', 'inflected', 'heb', 'בקולך', '["be./ko.Le./cha"]', '["to/ voice/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697I}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963L>', 'inflected', 'heb', 'בקול', '["be./Kol"]', '["to/ [the] voice of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/<H0776H>', 'inflected', 'heb', 'מהארץ', '["me./ha./''A.retz"]', '["from/ the/ ground"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0802G}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ [belonged] to the/ woman","and/ to/ a woman"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4770>', 'opaque', 'heb', 'מַרְבֵּק', '["marbêq"]', '["[the] stall"]', '["n-m"]', 'a stall (for cattle) × fat(-ted), stall.', 'from an unused root meaning to tie up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2076}/H9033/[H2076]', 'inflected', 'heb', 'זָבַח', '["zâbach"]', '["and/ he sacrificed/ it","and/ she slaughtered/ it"]', '["v"]', 'to slaughter an animal (usually in sacrifice) kill, offer, (do) sacrifice, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3888}/[H3888]', 'inflected', 'heb', 'לוּשׁ', '["lûwsh"]', '["and/ she kneaded [it]"]', '["v"]', 'to knead knead.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0644}/H9033/[H644]', 'inflected', 'heb', 'אָפָה', '["ʼâphâh"]', '["and/ she baked/ it"]', '["v"]', 'to cook, especially to bake bake(-r, (-meats)).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0663G}/H9011/[H662]', 'inflected', 'heb', 'אֲפֵק', '["ʼĂphêq"]', '["Aphek/ towards"]', '["n-pr-loc"]', 'Aphek (or Aphik), the name of three places in Palestine Aphek, Aphik.', 'or אֲפִיק; from 662 (in the sense of strength); fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869M}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["at the/ spring"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3157G}/[H2232]', 'inflected', 'heb', 'יִזְרְעֵאל', '["Yizrᵉʻêʼl"]', '["[is] in/ Jezreel"]', '["n-pr-m n-pr-loc"]', 'Jizreel, the name of two places in Palestine and of two Israelites Jezreel.', 'from 2232 and 410; God will sow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0505G}/[H504]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["and/ to/ thousands"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307H}/H9043/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["fell/ he"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6485J}/H9033/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["you assigned/ him"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7233}/H9023\/[H7231]', 'inflected', 'heb', 'רְבָבָה', '["rᵉbâbâh"]', '["<on>/ ten thousands/ his"]', '["n-f"]', 'abundance (in number), i.e. (specifically) a myriad (whether definite or indefinite) many, million, × multiply, ten thousand.', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0935G}/H9041/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ coming in/ you","and/ coming/ you"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H4397H>', 'inflected', 'heb', 'כמלאך', '["ke./mal.''Akh"]', '["[is] like/ [the] angel of","like/ [the] angel of","like/ an angel of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3157G}\/[H2232]', 'inflected', 'heb', 'יִזְרְעֵאל', '["Yizrᵉʻêʼl"]', '["Jezreel"]', '["n-pr-m n-pr-loc"]', 'Jizreel, the name of two places in Palestine and of two Israelites Jezreel.', 'from 2232 and 410; God will sow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6003}/[H6002]', 'inflected', 'heb', 'עֲמָלֵקִי', '["ʻĂmâlêqîy"]', '["and/ [the] Amalekite[s]"]', '["a"]', 'an Amalekite (or collectively the Amalekites) or descendants of Amalek Amalekite(-s).', 'patronymically from 6002;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1323G}/H9028/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ daughters/ their"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5619}/H9033/[H5619]', 'inflected', 'heb', 'סָקַל', '["çâqal"]', '["to/ stone/ him"]', '["v"]', 'properly, to be weighty; but used only in the sense of lapidation or its contrary (as if a delapidation) (cast, gather out, throw) stone(-s), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430G}/H9023\/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["God/ his"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1416}/[H1413]', 'inflected', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["<the>/ marauding band","the/ marauding band","the/ marauding band[s]","the/ troop"]', '["n-m"]', 'a crowd (especially of soldiers) army, band (of men), company, troop (of robbers).', 'from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5381}/H9033/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["¿/ will I overtake/ it"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1308}/[H1319]', 'inflected', 'heb', 'בְּשׂוֹר', '["Bᵉsôwr"]', '["<the>/ Besor"]', '["n"]', 'Besor, a stream of Palestine Besor.', 'from 1319; cheerful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6296}/[H6296]', 'lemma', 'heb', 'פָּגַר', '["pâgar"]', '["they had been [too] exhausted","they were [too] exhausted"]', '["v"]', 'to relax, i.e. become exhausted be faint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0335}/[H370]', 'inflected', 'heb', 'אַי', '["ʼay"]', '["and/ where?"]', '["adv"]', 'where? hence how? how, what, whence, where, whether, which (way).', 'perhaps from 370;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3774G}/[H3772]', 'inflected', 'heb', 'כְּרֵתִי', '["Kᵉrêthîy"]', '["the/ Kerethite[s]"]', '["a"]', 'a Kerethite or life-guardsman Cherethims, Cherethites.', 'probably from 3772 in the sense of executioner; (compare 2876) (only collectively in the singular as plural)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3381}/H9030/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["¿/ will you take down/ me"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3381}/H9031/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["and/ I will take down/ you"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3381}/H9033/[H3381]', 'inflected', 'heb', 'יָרַד', '["yârad"]', '["and/ he brought down/ him","and/ he took down/ him","and/ they brought down/ him"]', '["v"]', 'to descend (literally, to go downwards; or conventionally to a lower region, as the shore, a boundary, the enemy, etc.; or figuratively, to fall); causatively, to bring down (in all the above applications) × abundantly, bring down, carry down, cast down, (cause to) come(-ing) down, fall (down), get down, go(-ing) down(-ward), hang down, × indeed, let down, light (down), put down (off), (cause to, let) run down, sink, subdue, take down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5399}/[H5398]', 'inflected', 'heb', 'נֶשֶׁף', '["nesheph"]', '["from/ the/ twilight"]', '["n-m"]', 'properly, a breeze, i.e. (by implication) dusk (when the evening breeze prevails) dark, dawning of the day (morning), night, twilight.', 'from 5398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4283}/H9028/[H4279]', 'inflected', 'heb', 'מׇחֳרָת', '["mochŏrâth"]', '["of/ next day/ their"]', '["n-f"]', 'the morrow or (adverbially) tomorrow morrow, next day.', 'or מׇחֳרָתָם; (1 Samuel 30:17), feminine from the same as 4279;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5737C}/[H5737]', 'lemma', 'heb', 'עֲדַר', '["ʻădar"]', '["[was] missing","he fails","it was missing","it will be missing","lacking","they left lacking"]', '["v"]', 'to arrange, as a battle, a vineyard (to hoe); hence, to muster and so to miss (or find wanting) dig, fail, keep (rank), lack.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7998}/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["and/ from/ [the] booty","and/ from/ [the] plunder of"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1980N}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["for/ going"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7122G}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ to/ meet"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7965K}\/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["to/ welfare"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1100G}/[H1097]', 'inflected', 'heb', 'בְּלִיַּעַל', '["bᵉlîyaʻal"]', '["and/ a worthless person","and/ worthlessness"]', '["n-m"]', 'without profit, worthlessness; by extension, destruction, wickedness Belial, evil, naughty, ungodly (men), wicked.', 'from 1097 and 3276;(often in connection with 376, 802, 1121, etc.)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H0582}/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["from/ the/ men"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5090A}/[H5090]', 'inflected', 'heb', 'נָהַג', '["nâhag"]', '["so/ they may lead [them] away"]', '["v"]', 'to drive forth (a person, an animal or chariot), i.e. lead, carry away; reflexively, to proceed (i.e. impel or guide oneself); also (from the panting induced by effort), to sigh acquaint, bring (away), carry away, drive (away), lead (away, forth), (be) guide, lead (away, forth).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1980G}\/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ they may go"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H2506A}/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["and/ like/ [the] share of"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2505A}\/[H2505]', 'inflected', 'heb', 'חָלַק', '["châlaq"]', '["they will share"]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/<H3117L>', 'inflected', 'heb', 'מהיום', '["me./hai./Yom"]', '["from/ the/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4941G}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ <to>/ judgments","and/ into/ a judgment"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1008H}/[H1004]', 'inflected', 'heb', 'בֵּית־אֵל', '["Bêyth-ʼÊl"]', '["[were] in/ Beth-"]', '["n-pr-loc"]', 'Beth-El, a place in Palestine Beth-el.', 'from 1004 and 410; house of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1008H}/[H1004]', 'lemma', 'heb', 'בֵּית־אֵל', '["Bêyth-ʼÊl"]', '["-el"]', '["n-pr-loc"]', 'Beth-El, a place in Palestine Beth-el.', 'from 1004 and 410; house of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7418H}/[H7413]', 'inflected', 'heb', 'רָמוֹת', '["Râmôwth"]', '["[were] in/ Ramoth"]', '["n-pr-loc"]', 'Ramoth-Negeb or Ramath-Negeb, a place in Palestine south Ramoth, Ramath of the south.', 'or רָמַת נֶגֶב; from the plural or construct form of 7413 and 5045; heights (or height) of the South;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3492}/[H3498]', 'inflected', 'heb', 'יַתִּיר', '["Yattîyr"]', '["[were] in/ Jattir"]', '["n-pr-loc"]', 'Jattir, a place in Palestine Jattir.', 'from 3498; redundant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6177I}/[H6176]', 'inflected', 'heb', 'עֲרוֹעֵר', '["ʻĂrôwʻêr"]', '["[were] in/ Aroer"]', '["n-pr-loc"]', 'Aroër, the name of three places in or near Palestine Aroer.', 'or עֲרֹעֵר; or עַרְעוֹר; the same as 6176; nudity of situation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8224}/[H8221]', 'inflected', 'heb', 'שִׂפְמוֹת', '["Siphmôwth"]', '["[were] in/ Siphmoth"]', '["n-pr-loc"]', 'Siphmoth, a place in Palestine Siphmoth.', 'feminine plural of 8221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0851}\/[H8085]', 'inflected', 'heb', 'אֶשְׁתְּמֹעַ', '["ʼEshtᵉmôaʻ"]', '["[were] in/ Eshtemoa"]', '["n-pr"]', 'Eshtemoa or Eshtemoh, a place in Palestine Eshtemoa, Eshtemoh.', 'or אֶשְׁתְּמוֹעַ; or אֶשְׁתְּמֹה; from 8085 (in the sense of obedience);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7403}/[H7402]', 'inflected', 'heb', 'רָכָל', '["Râkâl"]', '["[were] in/ Racal"]', '["n-pr-loc"]', 'Rakal, a place in Palestine Rachal.', 'from 7402; merchant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2767}/[H2763]', 'inflected', 'heb', 'חׇרְמָה', '["Chormâh"]', '["[were] in/ Hormah"]', '["n-pr-loc"]', 'Chormah, a place in Palestine Hormah.', 'from 2763; devoted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3565}/[H3564]', 'inflected', 'heb', 'כּוֹר עָשָׁן', '["Kôwr ʻÂshân"]', '["[were] in/ Bor"]', '["n-pr-loc"]', 'Cor-Ashan, a place in Palestine Chorashan.', 'from 3564 and 6227; furnace of smoke;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3565}/[H3564]', 'lemma', 'heb', 'כּוֹר עָשָׁן', '["Kôwr ʻÂshân"]', '["Ashan"]', '["n-pr-loc"]', 'Cor-Ashan, a place in Palestine Chorashan.', 'from 3564 and 6227; furnace of smoke;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6269>', 'inflected', 'heb', 'בעתך', '["ba./''a.Takh"]', '["[were] in/ Athach"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0582}/H9023\/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["and/ men/ his"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1533H}/[H1530]', 'inflected', 'heb', 'גִּלְבֹּעַ', '["Gilbôaʻ"]', '["<the>/ Gilboa"]', '["n-pr-loc"]', 'Gilboa, a mountain of Palestine Gilboa.', 'from 1530 and 1158; fountain of ebullition;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0041H}/[H1]', 'lemma', 'heb', 'אֲבִינָדָב', '["ʼĂbîynâdâb"]', '["Abinadab"]', '["n-pr-m"]', 'Abinadab, the name of four Israelites Abinadab.', 'from 1 and 5068; father of generosity (i.e. liberal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3384A}/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["the/ archers","who/ throws"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7198}/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["by/ bow","on the/ bow","with <the>/ bow","with the/ bow","with/ bow"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H3384A}/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["from/ the/ archers"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5375W}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["to/ [the] bearer of"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1856}/H9030/[H1856]', 'inflected', 'heb', 'דָּקַר', '["dâqar"]', '["and/ pierce through/ me"]', '["v"]', 'to stab; by analogy, to starve; figuratively, to revile pierce, strike (thrust) through, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1856}/H9030/[H1856]', 'inflected', 'heb', 'דָּקַר', '["dâqar"]', '["and/ they will pierce through/ me"]', '["v"]', 'to stab; by analogy, to starve; figuratively, to revile pierce, strike (thrust) through, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H9039}\', 'inflected', 'heb', 'בהן ס', '["ba./Hen"]', '["in <the>/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6584}/[H6584]', 'inflected', 'heb', 'פָּשַׁט', '["pâshaṭ"]', '["to/ skin","to/ strip"]', '["v"]', 'to spread out (i.e. deploy in hostile array); by analogy, to strip (i.e. unclothe, plunder, flay, etc.) fall upon, flay, invade, make an invasion, pull off, put off, make a road, run upon, rush, set, spoil, spread selves (abroad), strip (off, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1319}/[H1319]', 'inflected', 'heb', 'בָּשַׂר', '["bâsar"]', '["to/ bear [the] news","to/ bear [the] news to","to/ bear news"]', '["v"]', 'properly, to be fresh, i.e. full (rosy, figuratively cheerful); to announce (glad news) messenger, preach, publish, shew forth, (bear, bring, carry, preach, good, tell good) tidings.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6091}/H9028/[H6087]', 'inflected', 'heb', 'עָצָב', '["ʻâtsâb"]', '["idols/ their"]', '["n-m"]', 'an (idolatrous) image idol, image.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6252G}/[H6251]', 'lemma', 'heb', 'עַשְׁתָּרוֹת', '["ʻAshtârôwth"]', '["Ashtaroth"]', '["n-pr-f"]', 'Ashtaroth, the name of a Sidonian deity, and of a place East of the Jordan Asharoth, Astaroth. See also 1045, 6253, 6255.', 'or עַשְׁתָּרֹת; plural of 6251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1472}/H9023/[H1465]', 'inflected', 'heb', 'גְּוִיָּה', '["gᵉvîyâh"]', '["corpse/ his"]', '["n-f"]', 'a body, whether alive or dead (dead) body, carcase, corpse.', 'prolonged for 1465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2346G>', 'inflected', 'heb', 'בחומת', '["ba./cho.Mah","be./Cho.mat","be./cho.Mah","be./cho.Mat","be./cho.Mot"]', '["<on> the/ wall","<on>/ [the] walls of","at/ [the] wall of","in the/ wall","in/ [the] wall of","in/ a wall","on/ [the] wall of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1472}/[H1465]', 'lemma', 'heb', 'גְּוִיָּה', '["gᵉvîyâh"]', '["[the] corpse of","[the] corpses of","corpses"]', '["n-f"]', 'a body, whether alive or dead (dead) body, carcase, corpse.', 'prolonged for 1465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2346G>', 'inflected', 'heb', 'מחומת', '["me./cho.Mat"]', '["from/ [the] wall of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3003G}/H9011/[H3002]', 'inflected', 'heb', 'יָבֵשׁ', '["Yâbêsh"]', '["Jabesh/ towards"]', '["n-pr-loc n-pr-m"]', 'Jobesh, the name of an Israelite and of a place in Palestine Jobesh (-Gilead).', 'the same as 3002 (also יָבֵישׁ; often with the addition of 1568, i.e. Jabesh of Gilad);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6106G}/H9028/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["bone/ their","bones/ their"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3003G}/H9011/[H3002]', 'inflected', 'heb', 'יָבֵשׁ', '["Yâbêsh"]', '["at/ Jabesh/ <towards>"]', '["n-pr-loc n-pr-m"]', 'Jobesh, the name of an Israelite and of a place in Palestine Jobesh (-Gilead).', 'the same as 3002 (also יָבֵישׁ; often with the addition of 1568, i.e. Jabesh of Gilad);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6002G>', 'inflected', 'heb', 'העמלק', '["ha./''a.ma.Lek"]', '["<the>/ Amalek"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6860>', 'inflected', 'heb', 'בצקלג', '["be./tzik.Lag"]', '["in/ Ziklag"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5046}/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["the/ [one who] told","the/ messenger","who/ had told"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8172}/[H8172]', 'lemma', 'heb', 'שָׁעַן', '["shâʻan"]', '["[is] supporting himself","[was] leaning","[who] was leaning","he supports himself","they depend","they depended","we depend","you depend","you depended"]', '["v"]', 'to support one''s self lean, lie, rely, rest (on, self), stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1167K}/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["and/ [the] owners of"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0270}/H9030/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["it has seized/ me","they have seized/ me","they seize/ me"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7661}/[H7660]', 'inflected', 'heb', 'שָׁבָץ', '["shâbâts"]', '["<the>/ dizziness"]', '["n-m"]', 'entanglement, i.e. (figuratively) perplexity anguish.', 'from 7660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4191}/H9033/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ I killed/ him","so/ we may put to death/ him"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307G}/H9043/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["had fallen/ he"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5145H}/[H5144]', 'inflected', 'heb', 'נֶזֶר', '["nezer"]', '["the/ crown"]', '["n-m"]', 'properly, something set apart, i.e. (abstractly) dedication (of a priet or Nazirite); hence (concretely) unshorn locks; also (by implication) a chaplet (especially of royalty) consecration, crown, hair, separation.', 'or נֵזֶר; from 5144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0685}/[H6807]', 'inflected', 'heb', 'אֶצְעָדָה', '["ʼetsʻâdâh"]', '["and/ an armlet"]', '["n-f"]', 'properly, a step-chain; by analogy, a bracelet bracelet, chain.', 'a variation from 6807;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7167}/H9038/[H7167]', 'inflected', 'heb', 'קָרַע', '["qâraʻ"]', '["and/ he tore/ them"]', '["v"]', 'to rend, literally or figuratively (revile, paint the eyes, as if enlarging them) cut out, rend, × surely, tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1818}/H9021/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["blood/ your"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6969}/[H6969]', 'inflected', 'heb', 'קוּן', '["qûwn"]', '["and/ he lamented","and/ he made a lament","and/ they will lament"]', '["v"]', 'to strike a musical note, i.e. chant or wail (at a funeral) lament, mourning woman.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7015}/[H6969]', 'inflected', 'heb', 'קִינָה', '["qîynâh"]', '["the/ lamentation","the/ lamentations"]', '["n-f"]', 'a dirge (as accompanied by beating the breasts or on instruments) lamentation.', 'from 6969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6643A}/[H6638]', 'inflected', 'heb', 'צְבִי', '["tsᵉbîy"]', '["<the>/ beauty","the/ beauty"]', '["n-m"]', 'splendor (as conspicuous) beautiful(-ty), glorious (-ry), goodly, pleasant, roe(-buck).', 'from 6638 in the sense of prominence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1116>/H9021', 'opaque', 'heb', 'בָּמָה', '["bâmâh"]', '["high places/ your"]', '["n-f"]', 'an elevation height, high place, wave.', 'from an unused root (meaning to be high);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1319}/[H1319]', 'lemma', 'heb', 'בָּשַׂר', '["bâsar"]', '["I have borne news","O bearer of news of","[is] bearing news","[one who] bears news","a bearer of news","bear news","he bore [the] news","let him receive [the] news","they will bear news","you bear news","you will bear [the] news"]', '["v"]', 'properly, to be fresh, i.e. full (rosy, figuratively cheerful); to announce (glad news) messenger, preach, publish, shew forth, (bear, bring, carry, preach, good, tell good) tidings.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5937}/[H5937]', 'lemma', 'heb', 'עָלַז', '["ʻâlaz"]', '["I will exult","I will triumph","let it exult","let them exult","they may celebrate","they should exult","will they exult","you are gloating","you will rejoice"]', '["v"]', 'to jump for joy, i.e. exult be joyful, rejoice, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7734}/[H7734]', 'lemma', 'heb', 'שׂוּג', '["sûwg"]', '["it turned back"]', '["v"]', 'to retreat turn back.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5273A}/[H5276]', 'inflected', 'heb', 'נָעִים', '["nâʻîym"]', '["and/ <the>/ pleasant"]', '["a"]', 'delightful (objective or subjective, literal or figurative) pleasant(-ure), sweet.', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2416E}/H9028/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["in/ lives/ their"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4194}/H9028/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["and/ in/ death/ their"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H5404>', 'inflected', 'heb', 'מנשרים', '["mi./ne.sha.Rim","mi./nish.Rei"]', '["more than/ [the] eagles of","more than/ eagles"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3847}/H9036/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["who/ clothed/ you"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5730A}/[H5727]', 'lemma', 'heb', 'עֵדֶן', '["ʻêden"]', '["luxuries"]', '["n-m"]', 'pleasure delicate, delight, pleasure. See also 1040.', 'or (feminine) עֶדְנָה; from 5727;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5716}/[H5710]', 'lemma', 'heb', 'עֲדִי', '["ʻădîy"]', '["ornament[s]","ornament[s] of","ornaments"]', '["n-m"]', 'finery; generally an outfit; specifically, a headstall × excellent, mouth, ornament.', 'from 5710 in the sense of trappings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3830}/H9027/[H3847]', 'inflected', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["clothing/ your"]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0160}/H9021/[H158]', 'inflected', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["love/ your"]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4421}\/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["battle","war","warfare"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5927G}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["¿/ does it go up","¿/ will I go up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0378}/[H376]', 'lemma', 'heb', 'אִישׁ־בֹּשֶׁת', '["ʼÎysh-Bôsheth"]', '["Ish-","bosheth"]', '["n-pr-m"]', 'Ish-Bosheth, a son of King Saul Ish-bosheth.', 'from 376 and 1322; man of shame;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5674C}/H9033/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["and/ he had brought over/ him","and/ they took away/ him"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4427A}/H9033/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["and/ he made king/ him","and/ they made king/ him"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0805B}/[H804]', 'inflected', 'heb', 'אֲשׁוּרִי', '["ʼĂshûwrîy"]', '["the/ Ashurite[s]"]', '["n-pr-m a"]', 'an Ashurite (collectively) or inhabitant of Ashur, a district in Palestine Asshurim, Ashurites.', 'or אַשּׁוּרִי; from a patrial word of the same form as 804;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3157H}/[H2232]', 'lemma', 'heb', 'יִזְרְעֵאל', '["Yizrᵉʻêʼl"]', '["Jezreel"]', '["n-pr-m n-pr-loc"]', 'Jizreel, the name of two places in Palestine and of two Israelites Jezreel.', 'from 2232 and 410; God will sow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3605}/H9023\/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["all of/ it"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2320G}\/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["months"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1391}/H9011/[H1387]', 'inflected', 'heb', 'גִּבְעוֹן', '["Gibʻôwn"]', '["Gibeon/ towards"]', '["n-pr-loc"]', 'Gibon, a place in Palestine Gibeon.', 'from the same as 1387; hilly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3097G}/[H3068]', 'inflected', 'heb', 'יוֹאָב', '["Yôwʼâb"]', '["and/ Joab"]', '["n-pr-m"]', 'Joab, the name of three Israelites Joab.', 'from 3068 and 1; Jehovah-fathered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6298}/H9038/[H6298]', 'inflected', 'heb', 'פָּגַשׁ', '["pâgash"]', '["and/ they met/ them"]', '["v"]', 'to come in contact with, whether by accident or violence; figuratively, to concur meet (with, together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1295H}/[H1288]', 'lemma', 'heb', 'בְּרֵכָה', '["bᵉrêkâh"]', '["[are] pools","[the] pool of","pools of"]', '["n-f"]', 'a reservoir (at which camels kneel as a resting-place) (fish-) pool.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1295H}/[H1288]', 'inflected', 'heb', 'בְּרֵכָה', '["bᵉrêkâh"]', '["the/ pool"]', '["n-f"]', 'a reservoir (at which camels kneel as a resting-place) (fish-) pool.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0378}/[H376]', 'inflected', 'heb', 'אִישׁ־בֹּשֶׁת', '["ʼÎysh-Bôsheth"]', '["and/ for/ Ish-"]', '["n-pr-m"]', 'Ish-Bosheth, a son of King Saul Ish-bosheth.', 'from 376 and 1322; man of shame;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6654>', 'inflected', 'heb', 'בצד', '["be./Tzad"]', '["[was] in/ [the] side of","with/ side"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2521}/[H2520]', 'lemma', 'heb', 'חֶלְקַת הַצֻּרִים', '["Chelqath hats-Tsurîym"]', '["Hazzurim","Helkath"]', '["n-pr-loc"]', 'Chelkath Hats-tsurim, a place in Palestine Helkath-hazzurim.', 'from 2520 and the plural of 6697, with the article inserted; smoothness of the rocks;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6214G}/[H6213]', 'inflected', 'heb', 'עֲשָׂהאֵל', '["ʻĂsâhʼêl"]', '["and/ Asah-","and/ Asahel"]', '["n-pr-m"]', 'Asahel, the name of four Israelites Asahel.', 'from 6213 and 410; God has made;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7031}/[H7043]', 'lemma', 'heb', 'קַל', '["qal"]', '["[is] swift","[was] swift","swift","swift [horse][s]"]', '["a"]', 'light; (by implication) rapid (also adverbial) light, swift(-ly).', 'contracted from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7704I>', 'inflected', 'heb', 'בשדה', '["ba./sa.Deh"]', '["[are] in the/ open country"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6214G}/[H6213]', 'lemma', 'heb', 'עֲשָׂהאֵל', '["ʻĂsâhʼêl"]', '["-el","Asah-","Asahel","O Asahel"]', '["n-pr-m"]', 'Asahel, the name of four Israelites Asahel.', 'from 6213 and 410; God has made;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8040G}/H9021/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["left/ your"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2488}/H9023/[H2503]', 'inflected', 'heb', 'חֲלִיצָה', '["chălîytsâh"]', '["spoils/ his"]', '["n-f"]', 'spoil armour.', 'from 2503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5493I}/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["to/ turn aside"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0310A}/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["with/ [the] back end<s> of"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2570>', 'inflected', 'heb', 'החמש', '["ha./Cho.mesh"]', '["the/ belly"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H8121>', 'inflected', 'heb', 'והשמש', '["ve./ha./She.mesh"]', '["and/ the/ sun"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0522}/[H520]', 'lemma', 'heb', 'אַמָּה', '["ʼAmmâh"]', '["Ammah"]', '["n-pr-loc"]', 'Ammah, a hill in Palestine Ammah.', 'the same as 520;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1520}/[H1518]', 'lemma', 'heb', 'גִּיחַ', '["Gîyach"]', '["Giah"]', '["n-pr-loc"]', 'Giach, a place in Palestine Giah.', 'from 1518; a fountain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0092>', 'inflected', 'heb', 'לאגדה', '["la./''a.gu.Dah"]', '["<into>/ a band"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H5331}/[H5329]', 'inflected', 'heb', 'נֶצַח', '["netsach"]', '["¿/ to/ perpetuity"]', '["n-m"]', 'properly, a goal, i.e. the bright object at a distance travelled towards; hence (figuratively), splendor, or (subjectively) truthfulness, or (objectively) confidence; but usually (adverbially), continually (i.e. to the most distant point of view) alway(-s), constantly, end, ( n-) ever(more), perpetual, strength, victory.', 'or נֵצַח; from 5329;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3045}/H9008/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["do you know/ ?"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H1242}/[H1239]', 'inflected', 'heb', 'בֹּקֶר', '["bôqer"]', '["from/ the/ morning"]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1338}/[H1334]', 'inflected', 'heb', 'בִּתְרוֹן', '["Bithrôwn"]', '["<the>/ Bitron"]', '["n-pr-loc"]', 'Bithron, a place East of the Jordan Bithron.', 'from 1334; (with the article) the craggy spot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0582}/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["and/ among/ [the] men of"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0752}/[H748]', 'lemma', 'heb', 'אָרֹךְ', '["ʼârôk"]', '["[is] long","[will be] a long [time]","long"]', '["a"]', 'long long.', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1800}\/[H1809]', 'inflected', 'heb', 'דַּל', '["dal"]', '["and/ weak"]', '["a"]', 'properly, dangling, i.e. (by implication) weak or thin lean, needy, poor (man), weaker.', 'from 1809;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0550G}/[H539]', 'lemma', 'heb', 'אַמְנוֹן', '["ʼAmnôwn"]', '["Amnon"]', '["n-m"]', 'Amnon (or Aminon), a son of David Amnon.', 'or אֲמִינוֹן; from 539; faithful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0293H}/[H251]', 'inflected', 'heb', 'אֲחִינֹעַם', '["ʼĂchîynôʻam"]', '["of/ Ahinoam","to/ Ahinoam"]', '["n-pr-f"]', 'Achinoam, the name of two Israelitesses Ahinoam.', 'from 251 and 5278; brother of pleasantness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3609}/[H3607]', 'lemma', 'heb', 'כִּלְאָב', '["Kilʼâb"]', '["Kileab"]', '["n-pr-m"]', 'Kilab, an Israelite Chileab.', 'apparently from 3607 and 1; restraint of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0053}/[H1]', 'lemma', 'heb', 'אֲבִישָׁלוֹם', '["ʼĂbîyshâlôwm"]', '["Abishalom","Absalom","O Absalom"]', '["n-pr-m"]', 'Abshalom, a son of David; also (the fuller form) a later Israelite Abishalom, Absalom.', 'or (shortened) אַבְשָׁלוֹם ; from 1 and 7965; father of peace (i.e. friendly);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4601I}/[H4600]', 'lemma', 'heb', 'מַעֲכָה', '["Maʻăkâh"]', '["Maacah"]', '["n-pr"]', 'Maakah (or Maakath), the name of a place in Syria, also of a Mesopotamian, of three Israelites, and of four Israelitesses and one Syrian woman Maachah, Maachathites. See also 1038.', 'or מַעֲכָת; (Joshua 13:13), from 4600; depression;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8526H}/[H8525]', 'lemma', 'heb', 'תַּלְמַי', '["Talmay"]', '["Talmai"]', '["n-pr-m"]', 'Talmai, the name of a Canaanite and a Syrian Talmai.', 'from 8525; ridged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7243}/[H7251]', 'inflected', 'heb', 'רְבִיעִי', '["rᵉbîyʻîy"]', '["and/ [was] the/ fourth","and/ the/ fourth [face]","and/ the/ fourth [king]"]', '["a"]', 'fourth; also (fractionally) a fourth foursquare, fourth (part).', 'or רְבִעִי; from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0138G}/[H113]', 'lemma', 'heb', 'אֲדֹנִיָּה', '["ʼĂdônîyâh"]', '["Adonijah"]', '["n-pr-m"]', 'Adonijah, the name of three Israelites Adonijah.', 'original (prolonged) אֲדֹנִיָּהוּ ; from 113 and 3050; lord (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2294}/[H2291]', 'lemma', 'heb', 'חַגִּית', '["Chaggîyth"]', '["Haggith"]', '["n-pr-f"]', 'Chaggith, a wife of David Haggith.', 'feminine of 2291; festive;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2549}/[H2568]', 'inflected', 'heb', 'חֲמִישִׁי', '["chămîyshîy"]', '["and/ [was] the/ fifth"]', '["a"]', 'fifth; also a fifth fifth (part).', 'or חֲמִשִּׁי; ordinal from 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8203G}/[H8199]', 'lemma', 'heb', 'שְׁפַטְיָה', '["Shᵉphaṭyâh"]', '["Shephatiah"]', '["n-pr-m"]', 'Shephatjah, the name of ten Israelites Shephatiah.', 'or שְׁפַטְיָהוּ; from 8199 and 3050; Jah has judged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0037}/[H1]', 'lemma', 'heb', 'אֲבִיטָל', '["ʼĂbîyṭâl"]', '["Abital"]', '["n-pr-f"]', 'Abital, a wife of King David Abital.', 'from 1 and 2919; father of dew (i.e. fresh);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8345}/[H8337]', 'inflected', 'heb', 'שִׁשִּׁי', '["shishshîy"]', '["and/ [was] the/ sixth"]', '["n"]', 'sixth, ordinal or (feminine) fractional sixth (part).', 'from 8337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3507}/[H3499]', 'lemma', 'heb', 'יִתְרְעָם', '["Yithrᵉʻâm"]', '["Ithream"]', '["n-pr-m"]', 'Jithream, a son of David Ithream.', 'from 3499 and 5971; excellence of people;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5698}/[H5697]', 'inflected', 'heb', 'עֶגְלָה', '["ʻEglâh"]', '["of/ Eglah","to/ Eglah"]', '["n-pr-f"]', 'Eglah, a wife of David Eglah.', 'the same as 5697;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2275A}\/[H2267]', 'inflected', 'heb', 'חֶבְרוֹן', '["Chebrôwn"]', '["at/ Hebron","in/ Hebron"]', '["n-pr-loc n-pr-m"]', 'Chebron, a place in Palestine, also the name of two Israelites Hebron.', 'from 2267; seat of association;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7532}/[H7531]', 'lemma', 'heb', 'רִצְפָּה', '["Ritspâh"]', '["Rizpah","[was] Rizpah"]', '["n-pr-f"]', 'Ritspah, an Israelitess Rizpah.', 'the same as 7531;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0345H}/[H344]', 'lemma', 'heb', 'אַיָּה', '["ʼAyâh"]', '["Aiah"]', '["n-pr-m"]', 'Ajah, the name of two Israelites Aiah, Ajah.', 'the same as 344;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0074}/[H1]', 'inflected', 'heb', 'אַבְנֵר', '["ʼAbnêr"]', '["<to>/ Abner","for/ Abner","to/ Abner"]', '["n-pr-m"]', 'Abner, an Israelite Abner.', 'or (fully) אֲבִינֵר ; from 1 and 5216; father of light (i.e. enlightening);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/<H7218A>', 'inflected', 'heb', 'הראש', '["ha./Rosh"]', '["¿/ [the] head of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5674C}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["to/ bring over","to/ take away"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6965I}/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ to/ establish"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725M}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["to/ bring back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3372G}/H9043/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["<from>/ because feared/ he"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3772H}/H9012/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["make/ !"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1285}/H9021/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["covenant/ your"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5437G}/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["to/ bring round","to/ turn over"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0854}/H9031/[H579]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["[is] from/ with <the>/ you","from/ with <the>/ you"]', '["prep"]', 'properly, nearness (used only as a preposition or an adverb), near; hence, generally, with, by, at, among, etc. against, among, before, by, for, from, in(-to), (out) of, with. Often with another prepositional prefix.', 'probably from 579;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440H}/H9020\/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ my"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6409H}/[H6404]', 'lemma', 'heb', 'פַּלְטִיאֵל', '["Palṭîyʼêl"]', '["Paltiel"]', '["n-pr-m"]', 'Paltiel, the name of two Israelites Paltiel, Phaltiel.', 'from the same as 6404 and 410; deliverance of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0980}/[H970]', 'lemma', 'heb', 'בַּחֻרִים', '["Bachurîym"]', '["Bahurim"]', '["n-pr-loc"]', 'Bachurim, a place in Palestine Bahurim.', 'or בַּחוּרִים; masculine plural of 970; young men;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0582}/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["and/ for/ [the] men"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H1416}/[H1413]', 'inflected', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["from/ the/ raid"]', '["n-m"]', 'a crowd (especially of soldiers) army, band (of men), company, troop (of robbers).', 'from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3097G}/[H3068]', 'inflected', 'heb', 'יוֹאָב', '["Yôwʼâb"]', '["to/ Joab"]', '["n-pr-m"]', 'Joab, the name of three Israelites Joab.', 'from 3068 and 1; Jehovah-fathered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6601B}/H9031/[H6601]', 'inflected', 'heb', 'פָּתָה', '["pâthâh"]', '["to/ deceive/ you"]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3045}/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["and/ to/ know"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4161}/H9021/[H3318]', 'inflected', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["exit/ your"]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4126}/H9021/[H3996]', 'inflected', 'heb', 'מוֹבָא', '["môwbâʼ"]', '["entrance/ your"]', '["n-m"]', 'an entrance coming.', 'by transp. for 3996;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0953B}/[H952]', 'inflected', 'heb', 'בּוֹר', '["bôwr"]', '["from/ [the] Cistern of"]', '["n-m"]', 'a pit hole (especially one used as a cistern or a prison) cistern, dungeon, fountain, pit, well.', 'from 952 (in the sense of 877);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5626}/[H5493]', 'inflected', 'heb', 'סִרָה', '["Çirâh"]', '["<the>/ Sirah"]', '["n-pr-loc"]', 'Sirah, a cistern so-called Sirah. See also 5518.', 'from 5493; departure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5186}/H9033/[H5186]', 'inflected', 'heb', 'נָטָה', '["nâṭâh"]', '["and/ he turned aside/ him","and/ he turned aside/ it","and/ she spread out/ it"]', '["v"]', 'to stretch or spread out; by implication, to bend away (including moral deflection); used in a great variety of application (as follows) afternoon, apply, bow (down, -ing), carry aside, decline, deliver, extend, go down, be gone, incline, intend, lay, let down, offer, outstretched, overthrown, pervert, pitch, prolong, put away, shew, spread (out), stretch (forth, out), take (aside), turn (aside, away), wrest, cause to yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7987}/[H7951]', 'inflected', 'heb', 'שְׁלִי', '["shᵉlîy"]', '["in <the>/ quietness"]', '["n-m"]', 'privacy quietly.', 'from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4467}/H9020/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["and/ kingdom/ my"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2342J}/[H2342]', 'lemma', 'heb', 'חוּל', '["chûwl"]', '["it causes labor pains to","it will whirl about","let them whirl","they writhe","whirling"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3772J}/[H3772]', 'lemma', 'heb', 'כָּרַת', '["kârath"]', '["I made","he be cut off","it will be cut off","we will cut off"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6879}/[H6879]', 'inflected', 'heb', 'צָרַע', '["tsâraʻ"]', '["and/ [one who] has a skin disease"]', '["v"]', 'to scourge, i.e. (intransitive and figurative) to be stricken with leprosy leper, leprous.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6418>', 'inflected', 'heb', 'בפלך', '["ba./Pe.lekh"]', '["on the/ spindle"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5307G}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ [one who] falls","and/ fall down","and/ he may fall","and/ it may fall","and/ prostrating himself","and/ they fall","and/ they fell","so/ it may fall","so/ let us fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2638}/[H2637]', 'inflected', 'heb', 'חָסֵר', '["châçêr"]', '["and/ [one] lacking of"]', '["a"]', 'lacking; hence, without destitute, fail, lack, have need, void, want.', 'from 2637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4421}\/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["in the/ battle"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2296}/[H2296]', 'inflected', 'heb', 'חָגַר', '["châgar"]', '["and/ gird","and/ gird yourselves","and/ they may girdethemselves"]', '["v"]', 'to gird on (as a belt, armor, etc.) be able to put on, be afraid, appointed, gird, restrain, × on every side.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5594}/[H5594]', 'inflected', 'heb', 'סָפַד', '["çâphad"]', '["and/ mourn","and/ you mourned"]', '["v"]', 'properly, to tear the hair and beat the breasts (as Orientals do in grief); generally to lament; by implication, to wail lament, mourn(-er), wail.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9004/{H4194}/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["¿/ like/ [the] death of"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5178A}/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["for the/ bronze","to/ [the] bronze of","to/ bronze fetters"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5307G}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["as/ falls"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5766B}/[H5765]', 'lemma', 'heb', 'עֶוֶל', '["ʻevel"]', '["<of> unrighteousness","[is] injustice","injustice","injustice<s>","unrighteousness"]', '["n-m"]', '(moral) evil iniquity, perverseness, unjust(-ly), unrighteousness(-ly); wicked(-ness).', 'or עָוֶל; and (feminine) עַוְלָה; or עוֹלָה; or עֹלָה; from 5765;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1262}/[H1250]', 'inflected', 'heb', 'בָּרָה', '["bârâh"]', '["for/ eating","to/ make to eat"]', '["v"]', 'to select; to feed; to render clear choose, (cause to) eat, manifest, (give) meat.', 'a primitive root; to select; also (as denominative from 1250) to feed; also (as equivalent to 1305) to render clear (Ecclesiastes 3:18)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H4428G}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["from/ the/ king"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5369G}\/[H5216]', 'inflected', 'heb', 'נֵר', '["Nêr"]', '["Ner"]', '["n-pr-m"]', 'Ner, an Israelite Ner.', 'the same as 5216; lamp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4886}/[H4886]', 'inflected', 'heb', 'מָשַׁח', '["mâshach"]', '["and/ [am] anointed","and/ he will smear [it]"]', '["v"]', 'to rub with oil, i.e. to anoint; by implication, to consecrate; also to paint anoint, paint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7451I}/H9023\/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["according to/ evil/ his"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1196G}/[H6031]', 'lemma', 'heb', 'בַּעֲנָה', '["Baʻănâh"]', '["Baanah","[was] Baanah"]', '["n-pr-m"]', 'Baanah, the name of four Israelites Baanah.', 'from a derivative of 6031 with prepositional prefix; in affliction');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7394G}/[H7392]', 'lemma', 'heb', 'רֵכָב', '["Rêkâb"]', '["Rechab","[was] Rechab"]', '["n-pr-m a"]', 'Rekab, the name of two Arabs and of two Israelites Rechab.', 'from 7392; rider;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7417B}/[H7416]', 'lemma', 'heb', 'רִמּוֹן', '["Rimmôwn"]', '["Rimmon"]', '["n-pr-m n-pr-loc"]', 'Rimmon, the name of a Syrian deity, also of five places in Palestine Remmon, Rimmon.', 'or (shorter) (רִמֹּן; or רִמּוֹנוֹ; (1 Chronicles 6:62 (77)), the same as 7416; in Joshua 19:13: הַמְּתֹאָר is mistaken for part of a name; article with the passive participle of 8388; the (one) marked off, i.e. which pertains).');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0886}/[H881]', 'inflected', 'heb', 'בְּאֵרֹתִי', '["Bᵉʼêrôthîy"]', '["the/ Beerothite","the/ Beerothites"]', '["a"]', 'a Beerothite or inhabitant of Beeroth Beerothite.', 'patrial from 881;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0881G}/[H875]', 'lemma', 'heb', 'בְּאֵרוֹת', '["Bᵉʼêrôwth"]', '["Beeroth"]', '["n-pr-loc"]', 'Beeroth, a place in Palestine Beeroth.', 'feminine plural of 875; wells;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1664}/H9011/[H1660]', 'inflected', 'heb', 'גִּתַּיִם', '["Gittayim"]', '["Gittaim/ towards"]', '["n-pr-loc"]', 'Gittajim, a place in Palestine Gittaim.', 'dual of 1660; double winepress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3083H}/[H3068]', 'inflected', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["and/ [belonged] to/ Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5223}/[H5223]', 'lemma', 'heb', 'נָכֶה', '["nâkeh"]', '["stricken of"]', '["a"]', 'smitten, i.e. (literally) maimed, or (figuratively) dejected contrite, lame.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8052}/[H8074]', 'lemma', 'heb', 'שְׁמוּעָה', '["shᵉmûwʻâh"]', '["[the] message","[the] report of","a report","new[s]","report"]', '["n-f"]', 'something heard, i.e. an announcement bruit, doctrine, fame, mentioned, news, report, rumor, tidings.', 'feminine passive participle of 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3157I}/[H2232]', 'inflected', 'heb', 'יִזְרְעֵאל', '["Yizrᵉʻêʼl"]', '["from/ Jezreel"]', '["n-pr-m n-pr-loc"]', 'Jizreel, the name of two places in Palestine and of two Israelites Jezreel.', 'from 2232 and 410; God will sow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0539}/H9033/[H541]', 'inflected', 'heb', 'אָמַן', '["ʼâman"]', '["nurse/ his"]', '["v"]', 'properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right.', 'a primitive root; (Isaiah 30:21; interchangeable with 541, to go to the right hand)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2648}/H9044/[H2648]', 'inflected', 'heb', 'חָפַז', '["châphaz"]', '["when/ hurried/ she"]', '["v"]', 'properly, to start up suddenly, i.e. (by implication) to hasten away, to fear (make) haste (away), tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6452B}/[H6452]', 'inflected', 'heb', 'פָּסַח', '["pâçach"]', '["and/ he became lame","and/ they limped around"]', '["v"]', 'to hop, i.e. (figuratively) skip over (or spare); by implication, to hesitate; also (literally) to limp, to dance halt, become lame, leap, pass over.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4648G}/[H6284]', 'lemma', 'heb', 'מְפִיבֹשֶׁת', '["Mᵉphîybôsheth"]', '["-bosheth","Mephi-","Mephibosheth","O Mephibosheth","[was] Mephibosheth"]', '["n-pr-m"]', 'Mephibosheth, the name of two Israelites Mephibosheth.', 'or מְפִבֹשֶׁת; probably from 6284 and 1322; dispeller of shame (i.e. of Baal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1196G}/[H6031]', 'inflected', 'heb', 'בַּעֲנָה', '["Baʻănâh"]', '["and/ Baanah"]', '["n-pr-m"]', 'Baanah, the name of four Israelites Baanah.', 'from a derivative of 6031 with prepositional prefix; in affliction');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6672A}/[H6671]', 'inflected', 'heb', 'צֹהַר', '["tsôhar"]', '["<the>/ noon<s>","the/ noontide<s>"]', '["n-m"]', 'a light (i.e. window); dual double light, i.e. noon midday, noon(-day, -tide), window.', 'from 6671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2007}/[H2004]', 'inflected', 'heb', 'הֵנָּה', '["hênnâh"]', '["and/ they","and/ they [fem]"]', '["p"]', 'themselves (often used emphatic for the copula, also in indirect relation) × in, × such (and such things), their, (into) them, thence, therein, these, they (had), on this side, whose, wherein.', 'prolongation for 2004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7394G}/[H7392]', 'inflected', 'heb', 'רֵכָב', '["Rêkâb"]', '["and/ Rechab"]', '["n-pr-m a"]', 'Rekab, the name of two Arabs and of two Israelites Rechab.', 'from 7392; rider;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4296}/H9023/[H5186]', 'inflected', 'heb', 'מִטָּה', '["miṭṭâh"]', '["bed/ his"]', '["n-f"]', 'a bed (as extended) for sleeping or eating; by analogy, a sofa, litter or bier bed(-chamber), bier.', 'from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4904}/H9023/[H7901]', 'inflected', 'heb', 'מִשְׁכָּב', '["mishkâb"]', '["bed/ his","lying down/ his","own bed/ his"]', '["n-m"]', 'a bed (figuratively, a bier); abstractly, sleep; by euphemism, carnal intercourse bed(-chamber), couch, lieth (lying) with.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7586G}/[H7592]', 'inflected', 'heb', 'שָׁאוּל', '["Shâʼûwl"]', '["from/ Saul"]', '["n-pr-m"]', 'Shaul, the name of an Edomite and two Israelites Saul, Shaul.', 'passive participle of 7592; asked;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2233H}/H9023\/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["and/ from/ offspring/ his"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1319}/[H1319]', 'inflected', 'heb', 'בָּשַׂר', '["bâsar"]', '["like/ a bearer of news"]', '["v"]', 'properly, to be fresh, i.e. full (rosy, figuratively cheerful); to announce (glad news) messenger, preach, publish, shew forth, (bear, bring, carry, preach, good, tell good) tidings.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0270}/H9012/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["and/ I took hold/ !"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5414G}/H9030/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["to/ give/ I"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1309}/[H1319]', 'lemma', 'heb', 'בְּשׂוֹרָה', '["bᵉsôwrâh"]', '["good news","news"]', '["n-f"]', 'glad tidings; by implication, reward for good news reward for tidings.', 'or (shortened) בְּשֹׂרָה; feminine from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027G}/H9026/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1197H}/[H1198]', 'inflected', 'heb', 'בָּעַר', '["bâʻar"]', '["and/ I will remove"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2026}/H9038/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["and/ he killed/ them","and/ it will kill/ them","and/ they killed/ them","and/ we will kill/ them"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6106G}/H9021/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["[are] bone/ your"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1320}/H9021/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["and/ flesh/ your"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0935P}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ the/ [one who] brought"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3389}/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["and/ in/ Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5493I}/H9031/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["he will turn aside/ you"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6455}/[H6452]', 'inflected', 'heb', 'פִּסֵּחַ', '["piççêach"]', '["and/ the/ lame [people]"]', '["a"]', 'lame lame.', 'from 6452;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4686B}/[H4685]', 'lemma', 'heb', 'מָצוּד', '["mâtsûwd"]', '["[the] stronghold of","strongholds"]', '["n-f"]', 'a net, or (abstractly) capture; also a fastness castle, defense, fort(-ress), (strong) hold, be hunted, net, snare, strong place.', 'or (feminine) מְצוּדָה; or מְצֻדָה; for 4685;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6726}/[H6725]', 'lemma', 'heb', 'צִיּוֹן', '["Tsîyôwn"]', '["<of> Zion","O Zion","Zion","[is] Zion"]', '["n-pr-loc"]', 'Tsijon (as a permanent capital), a mountain of Jerusalem Zion.', 'the same (regularly) as 6725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2983G}/[H2982]', 'lemma', 'heb', 'יְבוּסִי', '["Yᵉbûwçîy"]', '["<of> a Jebusite"]', '["n-m"]', 'a Jebusite or inhabitant of Jebus Jebusite(-s).', 'patrial from 2982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6794>', 'inflected', 'heb', 'בצנור', '["ba./tzi.Nor"]', '["by the/ water tunnel"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6455}/[H6452]', 'inflected', 'heb', 'פִּסֵּחַ', '["piççêach"]', '["the/ lame [animal]","the/ lame [people]"]', '["a"]', 'lame lame.', 'from 6452;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6455}/[H6452]', 'inflected', 'heb', 'פִּסֵּחַ', '["piççêach"]', '["and/ [the] lame","and/ a lame [person]"]', '["a"]', 'lame lame.', 'from 6452;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4407}/[H4390]', 'inflected', 'heb', 'מִלּוֹא', '["millôwʼ"]', '["the/ Millo"]', '["n-pr-m"]', 'a rampart (as filled in), i.e. the citadel Millo. See also 1037.', 'or מִלֹּא; (2 Kings 12:20), from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004O}/H9011/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ [the] inside/ towards"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2438G}/[H2361]', 'lemma', 'heb', 'חִירָם', '["Chîyrâm"]', '["Hiram"]', '["n-pr-m"]', 'Chiram or Chirom, the name of two Tyrians Hiram, Huram.', 'or חִירוֹםlemma חִירֹם missing vav, corrected to חִירוֹם; another form of 2361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6086K}/[H6095]', 'lemma', 'heb', 'עֵץ', '["ʻêts"]', '["wood","wood<s>"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559H}/H9033/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["establish/ it","he had appointed/ him"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3389}/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["[were] more than/ Jerusalem","from/ Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2275A}/[H2267]', 'inflected', 'heb', 'חֶבְרוֹן', '["Chebrôwn"]', '["from/ Hebron"]', '["n-pr-loc n-pr-m"]', 'Chebron, a place in Palestine, also the name of two Israelites Hebron.', 'from 2267; seat of association;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8051H}/[H8074]', 'lemma', 'heb', 'שַׁמּוּעַ', '["Shammûwaʻ"]', '["Shammua"]', '["n-pr-m"]', 'Shammua, the name of four Israelites Shammua, Shammuah.', 'from 8074; renowned;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7727G}/[H7726]', 'inflected', 'heb', 'שׁוֹבָב', '["Shôwbâb"]', '["and/ Shobab"]', '["n-pr-m"]', 'Shobab, the name of two Israelites Shobab.', 'the same as 7726; rebellious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5416G}/[H5414]', 'inflected', 'heb', 'נָתָן', '["Nâthân"]', '["and/ Nathan"]', '["n-pr-m"]', 'Nathan, the name of five Israelites Nathan.', 'from 5414; given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8010}/[H7965]', 'inflected', 'heb', 'שְׁלֹמֹה', '["Shᵉlômôh"]', '["and/ Solomon"]', '["n-pr-m"]', 'Shelomah, David''s successor Solomon.', 'from 7965; peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2984}/[H977]', 'inflected', 'heb', 'יִבְחַר', '["Yibchar"]', '["and/ Ibhar"]', '["n-pr-m"]', 'Jibchar, an Israelite Ibhar.', 'from 977; choice;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0474}/[H410]', 'inflected', 'heb', 'אֱלִישׁוּעַ', '["ʼĔlîyshûwaʻ"]', '["and/ Elishua"]', '["n-pr-m"]', 'Elishua, the son of King David Elishua.', 'from 410 and 7769; God of supplication (or of riches);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5298H>', 'inflected', 'heb', 'ונפג', '["ve./Ne.feg"]', '["and/ Nepheg"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3309I}/[H3313]', 'inflected', 'heb', 'יָפִיעַ', '["Yâphîyaʻ"]', '["and/ Japhia"]', '["n-pr-loc n-pr-m"]', 'Japhia, the name of a Canaanite, an Israelite, and a place in Palestine Japhia.', 'from 3313; bright;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0476H}/[H410]', 'inflected', 'heb', 'אֱלִישָׁמָע', '["ʼĔlîyshâmâʻ"]', '["and/ Elishama"]', '["n-pr-m"]', 'Elishama, the name of seven Israelites Elishama.', 'from 410 and 8085; God of hearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0450G}/[H410]', 'inflected', 'heb', 'אֶלְיָדָע', '["ʼElyâdâʻ"]', '["and/ Eliada"]', '["n-pr-m"]', 'Eljada, the name of two Israelites and of an Aramaean leader Eliada.', 'from 410 and 3045; God (is) knowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0467G}\/[H410]', 'inflected', 'heb', 'אֱלִיפֶלֶט', '["ʼĔlîypheleṭ"]', '["and/ Eliphelet"]', '["n-pr-m"]', 'Eliphelet or Elpelet, the name of six Israelites Eliphalet, Eliphelet, Elpalet.', 'or (shortened) אֱלְפֶּלֶט; from 410 and 6405; God of deliverance;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4686B}/[H4685]', 'inflected', 'heb', 'מָצוּד', '["mâtsûwd"]', '["the/ stronghold"]', '["n-f"]', 'a net, or (abstractly) capture; also a fastness castle, defense, fort(-ress), (strong) hold, be hunted, net, snare, strong place.', 'or (feminine) מְצוּדָה; or מְצֻדָה; for 4685;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1188}/[H1167]', 'inflected', 'heb', 'בַּעַל פְּרָצִים', '["Baʻal Pᵉrâtsîym"]', '["at/ Baal","in/ Baal"]', '["n-pr-loc"]', 'Baal-Peratsim, a place in Palestine Baal-perazim.', 'from 1167 and the plural of 6556; possessor of breaches;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1188}/[H1167]', 'lemma', 'heb', 'בַּעַל פְּרָצִים', '["Baʻal Pᵉrâtsîym"]', '["Baal","Perazim"]', '["n-pr-loc"]', 'Baal-Peratsim, a place in Palestine Baal-perazim.', 'from 1167 and the plural of 6556; possessor of breaches;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6556}/[H6555]', 'inflected', 'heb', 'פֶּרֶץ', '["perets"]', '["like/ a breach","like/ a bursting out of"]', '["n-m"]', 'a break (literally or figuratively) breach, breaking forth (in), × forth, gap.', 'from 6555;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1057}/[H1056]', 'lemma', 'heb', 'בָּכָא', '["bâkâʼ"]', '["[the] balsam trees"]', '["n-m"]', 'the weeping tree (some gum-distilling tree, perhaps the balsam) mulberry tree.', 'the same as 1056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8085G}/H9041/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["just as/ hearing/ you","when/ hearing/ you"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6807A}/[H6806]', 'lemma', 'heb', 'צְעָדָה', '["tsᵉʻâdâh"]', '["marching"]', '["n-f"]', 'a march; (concretely) an (ornamental) ankle-chain going, ornament of the legs.', 'feminine of 6806;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1057}/[H1056]', 'inflected', 'heb', 'בָּכָא', '["bâkâʼ"]', '["the/ balsam trees"]', '["n-m"]', 'the weeping tree (some gum-distilling tree, perhaps the balsam) mulberry tree.', 'the same as 1056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1387I}/[H1375]', 'inflected', 'heb', 'גֶּבַע', '["Gebaʻ"]', '["from/ Geba"]', '["n-pr-loc"]', 'Geba, a place in Palestine Gaba, Geba, Gibeah.', 'from the same as 1375, a hillock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1507}\/[H1506]', 'inflected', 'heb', 'גֶּזֶר', '["Gezer"]', '["Gezer"]', '["n-pr-loc"]', 'Gezer, a place in Palestine Gazer, Gezer.', 'the same as 1506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3063O}/[H3034]', 'lemma', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5798A}/[H5797]', 'inflected', 'heb', 'עֻזָּא', '["ʻUzzâʼ"]', '["and/ Uzzah"]', '["n-pr-m n-pr-loc"]', 'Uzza or Uzzah, the name of five Israelites Uzza, Uzzah.', 'or עֻזָּה; feminine of 5797; strength;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0283G}/[H251]', 'inflected', 'heb', 'אַחְיוֹ', '["ʼAchyôw"]', '["and/ Ahio"]', '["n-pr-m"]', 'Achio, the name of three Israelites Ahio.', 'prolonged from 251; brotherly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7832}/[H7832]', 'lemma', 'heb', 'שָׂחַק', '["sâchaq"]', '["I laughed","I will laugh","[were] making merry","[were] playing","he laughs","it laughs","jesting","laughing","merry makers","playing","they have laughed","they laughed","they play","they will laugh","you laugh","you will laugh"]', '["v"]', 'to laugh (in pleasure or detraction); by implication, to play deride, have in derision, laugh, make merry, mock(-er), play, rejoice, (laugh to) scorn, be in (make) sport.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1265>', 'opaque', 'heb', 'בְּרוֹשׁ', '["bᵉrôwsh"]', '["O cypress","[is] fir trees","[the] fir trees","a cypress","cypress","cypress<es>","cypress[es]","cypresses","fir trees","fir<s>"]', '["n-m"]', 'a cypress (?) tree; hence, a lance or a musical instrument (as made of that wood) fir (tree).', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5035B}/[H5034]', 'inflected', 'heb', 'נֶבֶל', '["nebel"]', '["and/ on/ lyres","and/ with/ lyres"]', '["n-m"]', 'a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol.', 'or נֵבֶל; from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8596}/[H8608]', 'inflected', 'heb', 'תֹּף', '["tôph"]', '["and/ on/ tambourines","and/ with/ tambourines"]', '["n-m"]', 'a tambourine tabret, timbrel.', 'from 8608 contracted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4517}/[H5128]', 'inflected', 'heb', 'מְנַעְנַע', '["mᵉnaʻnaʻ"]', '["and/ on/ rattles"]', '["n-m"]', 'a sistrum (so called from its rattling sound) cornet.', 'from 5128;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6767D}/[H6750]', 'inflected', 'heb', 'צְלָצַל', '["tsᵉlâtsal"]', '["and/ on/ cymbals"]', '["n-m"]', 'a clatter, i.e. (abstractly) whirring (of wings); (concretely) a cricket; also a harpoon (as rattling),a cymbal (as clanging) cymbal, locust, shadowing, spear.', 'from 6750 reduplicated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5225}/[H3559]', 'lemma', 'heb', 'נָכוֹן', '["Nâkôwn"]', '["Nacon"]', '["n-pr-m"]', 'Nakon, probably an Israelite Nachon.', 'from 3559; prepared;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5798A}/[H5797]', 'lemma', 'heb', 'עֻזָּא', '["ʻUzzâʼ"]', '["Uzzah"]', '["n-pr-m n-pr-loc"]', 'Uzza or Uzzah, the name of five Israelites Uzza, Uzzah.', 'or עֻזָּה; feminine of 5797; strength;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5798A}/[H5797]', 'inflected', 'heb', 'עֻזָּא', '["ʻUzzâʼ"]', '["against/ Uzzah","on/ Uzzah"]', '["n-pr-m n-pr-loc"]', 'Uzza or Uzzah, the name of five Israelites Uzza, Uzzah.', 'or עֻזָּה; feminine of 5797; strength;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7944}/[H7952]', 'inflected', 'heb', 'שַׁל', '["shal"]', '["the/ presumption"]', '["n-m"]', 'a fault error.', 'from 7952 abbreviated form;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6560H}/[H6556]', 'lemma', 'heb', 'פֶּרֶץ עֻזָּא', '["Perets ʻUzzâʼ"]', '["Perez","Uzzah"]', '["n-pr-loc"]', 'Perets-Uzza, a place in Palestine Perezuzza.', 'from 6556 and 5798; break of Uzza;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5654}/[H5647]', 'lemma', 'heb', 'עֹבֵד אֱדוֹם', '["ʻÔbêd ʼĔdôwm"]', '["Edom","Obed-"]', '["n-pr-m"]', 'Obed-Edom, the name of five Israelites Obed-edom.', 'from the active participle of 5647 and 123; worker of Edom;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6806}/[H6804]', 'lemma', 'heb', 'צַעַד', '["tsaʻad"]', '["[the] steps of","step","steps"]', '["n-m"]', 'a pace or regular step pace, step.', 'from 6804;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4806}/[H4754]', 'inflected', 'heb', 'מְרִיא', '["mᵉrîyʼ"]', '["and/ a fatling","and/ fatling"]', '["n-m"]', 'stall-fed; often (as noun) a beeve fat (fed) beast (cattle, -ling).', 'from 4754 in the sense of grossness, through the idea of domineering (compare 4756);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3769}/[H3769]', 'lemma', 'heb', 'כָּרַר', '["kârar"]', '["[was] dancing"]', '["v"]', 'to dance (i.e. whirl) dance(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8643}/[H7321]', 'inflected', 'heb', 'תְּרוּעָה', '["tᵉrûwʻâh"]', '["with/ a shout","with/ a shout of alarm","with/ a shout of joy","with/ a war cry","with/ shouting"]', '["n-f"]', 'clamor, i.e. acclamation of joy or a battle-cry; especially clangor of trumpets, as an alarum alarm, blow(-ing) (of, the) (trumpets), joy, jubile, loud noise, rejoicing, shout(-ing), (high, joyful) sound(-ing).', 'from 7321;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H6963H>', 'inflected', 'heb', 'ובקול', '["u./ve./Kol"]', '["and/ with/ [the] sound of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6339}/[H6338]', 'lemma', 'heb', 'פָּזַז', '["pâzaz"]', '["leaping"]', '["v"]', 'to solidify (as if by refining); also to spring (as if separating the limbs) leap, be made strong.', 'a primitive root (identical with 6338);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3769}/[H3769]', 'inflected', 'heb', 'כָּרַר', '["kârar"]', '["and/ dancing"]', '["v"]', 'to dance (i.e. whirl) dance(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3820A}/H9024/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["in/ heart/ her"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5927I}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["from/ offering up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0829>', 'inflected', 'heb', 'ואשפר', '["ve./''esh.Par"]', '["and/ a date-cake"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0809}/[H808]', 'inflected', 'heb', 'אֲשִׁישָׁה', '["ʼăshîyshâh"]', '["and/ a raisin-cake"]', '["n-f"]', 'something closely pressed together, i.e. a cake of raisins or other comfits flagon.', 'feminine of 808;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1540I}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["as/ uncovers himself"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0001G}/H9022/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["more than/ father/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5057}/[H5046]', 'lemma', 'heb', 'נָגִיד', '["nâgîyd"]', '["[the] leader of","[the] officer of","[the] officers of","[the] ruler of","[the] supervisor of","[was the] chief","[was] chief","a chief","a leader","a prince","a prince of","a ruler","an officer","commanders","leader","nobles","princely things","ruler","rulers"]', '["n-m"]', 'a commander (as occupying the front), civil, military or religious; generally (abstractly, plural), honorable themes captain, chief, excellent thing, (chief) governor, leader, noble, prince, (chief) ruler.', 'or נָגִד; from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7832}/[H7832]', 'inflected', 'heb', 'שָׂחַק', '["sâchaq"]', '["and/ I will play","and/ he laughs","and/ she laughed"]', '["v"]', 'to laugh (in pleasure or detraction); by implication, to play deride, have in derision, laugh, make merry, mock(-er), play, rejoice, (laugh to) scorn, be in (make) sport.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2063}/[H2088]', 'inflected', 'heb', 'זֹאת', '["zôʼth"]', '["more than/ this"]', '["d"]', 'this (often used adverb) hereby (-in, -with), it, likewise, the one (other, same), she, so (much), such (deed), that, therefore, these, this (thing), thus.', 'irregular feminine of 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4324G}/[H4323]', 'inflected', 'heb', 'מִיכָל', '["Mîykâl"]', '["and/ to/ Michal"]', '["n-pr-f"]', 'Mikal, Saul''s daughter Michal.', 'apparently the same as 4323; revulet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4194}/H9024\/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["death/ her"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004P}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["in/ house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5416H}/[H5414]', 'lemma', 'heb', 'נָתָן', '["Nâthân"]', '["Nathan"]', '["n-pr-m"]', 'Nathan, the name of five Israelites Nathan.', 'from 5414; given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/H9032\/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[is] with/ you","with/ you"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3427}/H9030/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["to/ dwell in/ I"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/<H3117L>', 'inflected', 'heb', 'למיום', '["Le./mi./yom"]', '["<to>/ from/ [the] day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4908}/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["and/ in/ a tabernacle","and/ in/ dwelling places of"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1697G}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["¿/ a word"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7626J>', 'opaque', 'heb', 'שֵׁבֶט', '["shêbeṭ"]', '["[the] tribes of"]', '["n-m"]', 'a scion, i.e. (literally) a stick (for punishing, writing, fighting, ruling, walking, etc.) or (figuratively) a clan × correction, dart, rod, sceptre, staff, tribe.', 'from an unused root probably meaning to branch off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5650}/H9020/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["<to>/ servant/ my","to/ servant/ my"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5116A}/[H5115]', 'inflected', 'heb', 'נָוֶה', '["nâveh"]', '["the/ pasture"]', '["n"]', '(adjectively) at home; hence (by implication of satisfaction) lovely; also (noun) a home, of God (temple), men (residence), flocks (pasture), or wild animals (den) comely, dwelling (place), fold, habitation, pleasant place, sheepcote, stable, tarried.', 'or (feminine) נָוָה; from 5115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3772I}/H9012/[H3772]', 'inflected', 'heb', 'כָּרַת', '["kârath"]', '["and/ I cut off/ !"]', '["v"]', 'to cut (off, down or asunder); by implication, to destroy or consume; specifically, to covenant (i.e. make an alliance or bargain, originally by cutting flesh and passing between the pieces) be chewed, be con-(feder-) ate, covenant, cut (down, off), destroy, fail, feller, be freed, hew (down), make a league (covenant), × lose, perish, × utterly, × want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5193}/H9033/[H5193]', 'inflected', 'heb', 'נָטַע', '["nâṭaʻ"]', '["and/ I will plant/ it","and/ he planted/ it"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4480A}/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["and/ <to>/ from"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3559H}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["and/ I will establish","and/ he established","and/ it was established","and/ it will be established","and/ they established","and/ you established","and/ you have directed","and/ you will direct"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5753B}/H9043/[H5753]', 'inflected', 'heb', 'עָוָה', '["ʻâvâh"]', '["when/ does wrong/ he"]', '["v"]', 'to crook, literally or figuratively do amiss, bow down, make crooked, commit iniquity, pervert, (do) perverse(-ly), trouble, × turn, do wickedly, do wrong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3198}/H9033/[H3198]', 'inflected', 'heb', 'יָכַח', '["yâkach"]', '["and/ I will reprove/ him"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5061}/[H5060]', 'inflected', 'heb', 'נֶגַע', '["negaʻ"]', '["and/ with/ plagues","and/ with/ wounds of"]', '["n-m"]', 'a blow (figuratively, infliction); also (by implication) a spot (concretely, a leprous person or dress) plague, sore, stricken, stripe, stroke, wound.', 'from 5060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2617A}/H9020/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["and/ covenant loyalty/ my"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4467}/H9021/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["and/ kingdom/ your"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3678G}/H9021/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["throne/ your"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2384}/[H2372]', 'inflected', 'heb', 'חִזָּיוֹן', '["chizzâyôwn"]', '["the/ vision"]', '["n-m"]', 'a revelation, expectation by dream vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6994}/[H6996]', 'inflected', 'heb', 'קָטֹן', '["qâṭôn"]', '["and/ it was small"]', '["v"]', 'to diminish, i.e. be (causatively, make) diminutive or (figuratively) of no account be a (make) small (thing), be not worthy.', 'a primitive root (rather denominative from 6996);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/{H7350}/[H7368]', 'inflected', 'heb', 'רָחוֹק', '["râchôwq"]', '["<to>/ from/ a distance","<to>/ from/ afar","<to>/ from/ distant [time]"]', '["a"]', 'remote, literally or figuratively, of place or time; specifically, precious; often used adverbially (with preposition) (a-) far (abroad, off), long ago, of old, space, great while to come.', 'or רָחֹק; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8452}/[H8448]', 'lemma', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["[is] [the] manner of"]', '["n-f"]', 'a custom manner.', 'probably feminine of 8448;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697J}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["word/ your","words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3820A}/H9021/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["and/ according to/ heart/ your","and/ according to/ own heart/ your"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1420}/[H1419]', 'inflected', 'heb', 'גְּדוּלָה', '["gᵉdûwlâh"]', '["<the>/ greatness","the/ greatness","the/ greatness<es>"]', '["n-f"]', 'greatness; (concretely) mighty acts dignity, great things(-ness), majesty.', 'or גְּדֻלָּה; (shortened) or (less accurately) גְּדוּלָּה; feminine of 1419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241G}/H9025/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["with/ ears/ our"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5971A}/H9021/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["[is] like/ people/ your","as/ people/ your","like/ people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3478}/[H8280]', 'inflected', 'heb', 'יִשְׂרָאֵל', '["Yisrâʼêl"]', '["like/ Israel"]', '["n-pr-m"]', 'he will rule as God; Jisraël, a symbolical name of Jacob; also (typically) of his posterity Israel.', 'from 8280 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6299}/[H6299]', 'inflected', 'heb', 'פָּדָה', '["pâdâh"]', '["to/ redeem"]', '["v"]', 'to sever, i.e. ransom; generally to release, preserve × at all, deliver, × by any means, ransom, (that are to be, let be) redeem(-ed), rescue, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7760A}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ to/ make"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0430J}/H9023/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ gods/ its"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8605}/[H6419]', 'inflected', 'heb', 'תְּפִלָּה', '["tᵉphillâh"]', '["the/ prayer"]', '["n-f"]', 'intercession, supplication; by implication, a hymn prayer.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1697G}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1293}/H9021/[H1288]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["and/ from/ blessing/ your"]', '["n-f"]', 'benediction; by implication prosperity blessing, liberal, pool, present.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3665}/H9038/[H3665]', 'inflected', 'heb', 'כָּנַע', '["kânaʻ"]', '["and/ he subdued/ them"]', '["v"]', 'properly, to bend the knee; hence, to humiliate, vanquish bring down (low), into subjection, under, humble (self), subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4965}/[H4964]', 'lemma', 'heb', 'מֶתֶג הָאַמָּה', '["Metheg hâ-ʼAmmâh"]', '["Metheg-"]', '["n-m"]', 'Metheg-ha-Ammah, an epithet of Gath Metheg-ammah.', 'from 4964 and 520 with the art. interposed; bit of the metropolis;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4965}/[H4964]', 'inflected', 'heb', 'מֶתֶג הָאַמָּה', '["Metheg hâ-ʼAmmâh"]', '["<the>/ -ammah"]', '["n-m"]', 'Metheg-ha-Ammah, an epithet of Gath Metheg-ammah.', 'from 4964 and 520 with the art. interposed; bit of the metropolis;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4058}/H9038/[H4058]', 'inflected', 'heb', 'מָדַד', '["mâdad"]', '["and/ he measured off/ them"]', '["v"]', 'properly, to stretch; by implication, to measure (as if by stretching a line); figuratively, to be extended measure, mete, stretch self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2256M}/[H2254]', 'inflected', 'heb', 'חֶבֶל', '["chebel"]', '["<the>/ measuring-line"]', '["n-m"]', 'a rope (as twisted), especially a measuring line; by implication, a district or inheritance (as measured); or a noose (as of cords); figuratively, a company (as if tied together); a throe (especially of parturition); also ruin band, coast, company, cord, country, destruction, line, lot, pain, pang, portion, region, rope, snare, sorrow, tackling.', 'or חֵבֶל; from 2254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1909}/[H1908]', 'lemma', 'heb', 'הֲדַדְעֶזֶר', '["Hădadʻezer"]', '["Hadadezer"]', '["n-pr-m"]', 'Hadadezer, a Syrian king Hadadezer. Compare 1928.', 'from 1908 and 5828; Hadad (is his) help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7340I}/[H7339]', 'lemma', 'heb', 'רְחֹב', '["Rᵉchôb"]', '["Rehob"]', '["n-pr-m n-pr-loc"]', 'Rechob, the name of a place in Syria, also of a Syrian and an Israelite Rehob.', 'or רְחוֹב; the same as 7339;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5104G}/H9014/{H6578}/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["at/ [the] river/-/Euphrates"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6131B}/[H6131]', 'inflected', 'heb', 'עָקַר', '["ʻâqar"]', '["and/ he hamstrung"]', '["v"]', 'to pluck up (especially by the roots); specifically, to hamstring; figuratively, to exterminate dig down, hough, pluck up, root up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1909}/[H1908]', 'inflected', 'heb', 'הֲדַדְעֶזֶר', '["Hădadʻezer"]', '["<to>/ Hadadezer"]', '["n-pr-m"]', 'Hadadezer, a Syrian king Hadadezer. Compare 1928.', 'from 1908 and 5828; Hadad (is his) help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0758I}/[H759]', 'inflected', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["among/ Aram","in/ Aram","on/ Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7982}/[H7980]', 'lemma', 'heb', 'שֶׁלֶט', '["sheleṭ"]', '["[the] shields of"]', '["n-m"]', 'probably a shield (as controlling, i.e. protecting the person) shield.', 'from 7980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0984}/[H983]', 'inflected', 'heb', 'בֶּטַח', '["Beṭach"]', '["and/ from/ Betah"]', '["n-pr-loc"]', 'Betach, a place in Syria Betah.', 'the same as 983;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1268B}/[H1266]', 'inflected', 'heb', 'בֵּרוֹתָה', '["Bêrôwthâh"]', '["and/ from/ Berothai"]', '["n-pr-loc"]', 'Berothah or Berothai, a place north of Palestine Berothah, Berothai.', 'or בֵּרֹתַי; probably from 1266; cypress or cypresslike;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8583}/[H8582]', 'lemma', 'heb', 'תֹּעוּ', '["Tôʻûw"]', '["Toi","Tou"]', '["n-pr-m"]', 'Tou or Toi, a Syrian king Toi, Tou.', 'or תֹּעִי; from 8582; error');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3141G}/[H3088]', 'lemma', 'heb', 'יוֹרָם', '["Yôwrâm"]', '["Joram"]', '["n-pr-m"]', 'Joram, the name of three Israelites and one Syrian Joram.', 'a form of 3088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1288}/H9033/[H1288]', 'inflected', 'heb', 'בָּרַךְ', '["bârak"]', '["and/ to/ bless/ him"]', '["v"]', 'to kneel; by implication to bless God (as an act of adoration), and (vice-versa) man (as a benefit); also (by euphemism) to curse (God or the king, as treason) × abundantly, × altogether, × at all, blaspheme, bless, congratulate, curse, × greatly, × indeed, kneel (down), praise, salute, × still, thank.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1909}/[H1908]', 'inflected', 'heb', 'הֲדַדְעֶזֶר', '["Hădadʻezer"]', '["against/ Hadadezer"]', '["n-pr-m"]', 'Hadadezer, a Syrian king Hadadezer. Compare 1928.', 'from 1908 and 5828; Hadad (is his) help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3027K}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ in/ hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0758M}/[H759]', 'inflected', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["from/ Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4124G}/[H1]', 'inflected', 'heb', 'מוֹאָב', '["Môwʼâb"]', '["and/ from/ Moab"]', '["n-pr-m n-pr-loc"]', 'Moab, an incestuous son of Lot; also his territory and descendants Moab.', 'from a prolonged form of the prepositional prefix m- and 1; from (her [the mother''s]) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6430G}/[H6429]', 'inflected', 'heb', 'פְּלִשְׁתִּי', '["Pᵉlishtîy"]', '["and/ from/ [the] Philistines"]', '["a"]', 'a Pelishtite or inhabitant of Pelesheth Philistine.', 'patrial from 6429;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H6002G>', 'inflected', 'heb', 'ומעמלק', '["u./Me./''a.ma.Lek","u./me./''a.ma.Lek"]', '["and/ from/ Amalek"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7725G}/H9043/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["when/ returned/ he"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5221}/H9043/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["from/ defeating/ he"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0758M}/[H759]', 'lemma', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1516J}/[H1466]', 'inflected', 'heb', 'גַּיְא', '["gayʼ"]', '["in/ [the] Valley of"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4417H}/[H4414]', 'lemma', 'heb', 'מֶלַח', '["melach"]', '["Salt"]', '["n-m"]', 'properly, powder, i.e. (specifically) salt (as easily pulverized and dissolved) salt(-pit).', 'from 4414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3092G}/[H3068]', 'inflected', 'heb', 'יְהוֹשָׁפָט', '["Yᵉhôwshâphâṭ"]', '["and/ Jehoshaphat"]', '["n-pr-m n-pr-loc"]', 'Jehoshaphat, the name of six Israelites; also of a valley near Jerusalem Jehoshaphat. Compare 3146.', 'from 3068 and 8199; Jehovah-judged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0286}/[H251]', 'lemma', 'heb', 'אֲחִילוּד', '["ʼĂchîylûwd"]', '["Ahilud"]', '["n-pr-m"]', 'Achilud, an Israelite Ahilud.', 'from 251 and 3205; brother of one born;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6659G}/[H6663]', 'inflected', 'heb', 'צָדוֹק', '["Tsâdôwq"]', '["and/ Zadok"]', '["n-pr-m"]', 'Tsadok, the name of eight or nine Israelites Zadok.', 'from 6663; just;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0285H}/[H251]', 'lemma', 'heb', 'אֲחִיטוּב', '["ʼĂchîyṭûwb"]', '["Ahitub"]', '["n-pr-m"]', 'Achitub, the name of several priests Ahitub.', 'from 251 and 2898; brother of goodness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0288I}/[H251]', 'inflected', 'heb', 'אֲחִימֶלֶךְ', '["ʼĂchîymelek"]', '["and/ Ahimelech"]', '["n-pr-m"]', 'Achimelek, the name of an Israelite and of a Hittite Ahimelech.', 'from 251 and 4428; brother of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8304G}/[H8280]', 'inflected', 'heb', 'שְׂרָיָה', '["Sᵉrâyâh"]', '["and/ Seraiah"]', '["n-pr-m"]', 'Serajah, the name of nine Israelites Seraiah.', 'or שְׂרָיָהוּ; from 8280 and 3050; Jah has prevailed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1141G}/[H1129]', 'inflected', 'heb', 'בְּנָיָה', '["Bᵉnâyâh"]', '["and/ Benaiah"]', '["n-pr-m"]', 'Benajah, the name of twelve Israelites Benaiah.', 'or בּנָיָהוּ; (prolonged) from 1129 and 3050; Jah has built;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3077G}/[H3068]', 'lemma', 'heb', 'יְהוֹיָדָע', '["Yᵉhôwyâdâʻ"]', '["Jehoiada"]', '["n-pr-m"]', 'Jehojada, the name of three Israelites Jehoiada. Compare 3111.', 'from 3068 and 3045; Jehovah-known;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3774H}/[H3772]', 'inflected', 'heb', 'כְּרֵתִי', '["Kᵉrêthîy"]', '["and/ the/ Kerethite[s]"]', '["a"]', 'a Kerethite or life-guardsman Cherethims, Cherethites.', 'probably from 3772 in the sense of executioner; (compare 2876) (only collectively in the singular as plural)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6432}/[H6431]', 'inflected', 'heb', 'פְּלֵתִי', '["Pᵉlêthîy"]', '["and/ the/ Pelethite[s]"]', '["a"]', 'a courier (collectively) or official messenger Pelethites.', 'from the same form as 6431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6717}/[H6678]', 'lemma', 'heb', 'צִיבָא', '["Tsîybâʼ"]', '["Ziba","[was] Ziba"]', '["n-pr-m"]', 'Tsiba, an Israelite Ziba.', 'from the same as 6678; station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0657A}/[H656]', 'inflected', 'heb', 'אֶפֶס', '["ʼepheç"]', '["¿/ [is] there not"]', '["n-m"]', 'cessation, i.e. an end (especially of the earth); often used adverb, no further; also the ankle (in the dual), as being the extremity of the leg or foot ankle, but (only), end, howbeit, less than nothing, nevertheless (where), no, none (beside), not (any, -withstanding), thing of nought, save(-ing), there, uttermost part, want, without (cause).', 'from 656; (sometimes like 6466)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4353H}/[H4376]', 'lemma', 'heb', 'מָכִיר', '["Mâkîyr"]', '["Makir"]', '["n-pr-m"]', 'Makir, an Israelite Machir.', 'from 4376; salesman;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5988H}/[H5971]', 'lemma', 'heb', 'עַמִּיאֵל', '["ʻAmmîyʼêl"]', '["Ammiel"]', '["n-pr-m"]', 'Ammiel, the name of three or four Israelites Ammiel.', 'from 5971 and 410; people of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3810}/[H3808]', 'inflected', 'heb', 'לֹא דְבַר', '["Lôʼ Dᵉbar"]', '["in/ Lo"]', '["n-pr-loc"]', 'Lo-Debar, a place in Palestine Debir, Lodebar.', 'or לוֹ דבַר; (Samuel 9:4,5), or לִדְבִר; (Joshua 13:26), (probably rather לֹדְבַר ); from 3808 and 1699; pastureless;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3810}/[H3808]', 'lemma', 'heb', 'לֹא דְבַר', '["Lôʼ Dᵉbar"]', '["Debar"]', '["n-pr-loc"]', 'Lo-Debar, a place in Palestine Debir, Lodebar.', 'or לוֹ דבַר; (Samuel 9:4,5), or לִדְבִר; (Joshua 13:26), (probably rather לֹדְבַר ); from 3808 and 1699; pastureless;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947J}/H9033/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ he took/ him"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3810}/[H3808]', 'inflected', 'heb', 'לֹא דְבַר', '["Lôʼ Dᵉbar"]', '["from/ Lo"]', '["n-pr-loc"]', 'Lo-Debar, a place in Palestine Debir, Lodebar.', 'or לוֹ דבַר; (Samuel 9:4,5), or לִדְבִר; (Joshua 13:26), (probably rather לֹדְבַר ); from 3808 and 1699; pastureless;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4648G}/[H6284]', 'inflected', 'heb', 'מְפִיבֹשֶׁת', '["Mᵉphîybôsheth"]', '["and/ Mephibosheth"]', '["n-pr-m"]', 'Mephibosheth, the name of two Israelites Mephibosheth.', 'or מְפִבֹשֶׁת; probably from 6284 and 1322; dispeller of shame (i.e. of Baal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6717}/[H6678]', 'inflected', 'heb', 'צִיבָא', '["Tsîybâʼ"]', '["and/ [belonged] to/ Ziba"]', '["n-pr-m"]', 'Tsiba, an Israelite Ziba.', 'from the same as 6678; station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4648G}/[H6284]', 'inflected', 'heb', 'מְפִיבֹשֶׁת', '["Mᵉphîybôsheth"]', '["and/ [belonged] to/ Mephibosheth"]', '["n-pr-m"]', 'Mephibosheth, the name of two Israelites Mephibosheth.', 'or מְפִבֹשֶׁת; probably from 6284 and 1322; dispeller of shame (i.e. of Baal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4316J}/[H4318]', 'lemma', 'heb', 'מִיכָא', '["Mîykâʼ"]', '["[was] Mica"]', '["n-pr-m"]', 'Mica, the name of two Israelites Micha.', 'a variation for 4318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4648G}/[H6284]', 'inflected', 'heb', 'מְפִיבֹשֶׁת', '["Mᵉphîybôsheth"]', '["[belonged] to/ Mephi-","of/ Mephibosheth"]', '["n-pr-m"]', 'Mephibosheth, the name of two Israelites Mephibosheth.', 'or מְפִבֹשֶׁת; probably from 6284 and 1322; dispeller of shame (i.e. of Baal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7272}/H9023\/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["feet/ his"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2586G}/[H2603]', 'lemma', 'heb', 'חָנוּן', '["Chânûwn"]', '["Hanun"]', '["n-pr-m"]', 'Chanun, the name of an Ammonite and of two Israelites Hanun.', 'from 2603; favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5176H}/[H5175]', 'lemma', 'heb', 'נָחָשׁ', '["Nâchâsh"]', '["Nahash"]', '["n-pr-m"]', 'Nachash, the name of two persons apparently non-Israelite Nahash.', 'the same as 5175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3513G}/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["¿/ [is] honoring","¿/ honoring"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7270}/H9034/[H7272]', 'inflected', 'heb', 'רָגַל', '["râgal"]', '["and/ to/ spy on/ it"]', '["v"]', 'to walk along; but only in specifically, applications, to reconnoiter, to be a tale-bearer (i.e. slander); to lead about backbite, search, slander, (e-) spy (out), teach to go, view.', 'a primitive root; also as denominative from 7272');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2015}/H9034/[H2015]', 'inflected', 'heb', 'הָפַךְ', '["hâphak"]', '["and/ to/ overthrow/ it"]', '["v"]', 'to turn about or over; by implication, to change, overturn, return, pervert × become, change, come, be converted, give, make (a bed), overthrow (-turn), perverse, retire, tumble, turn (again, aside, back, to the contrary, every way).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4063>/H9028', 'opaque', 'heb', 'מֶדֶו', '["medev"]', '["robes/ their"]', '["n-m"]', 'properly, extent, i.e. measure; by implication, a dress (as measured) garment.', 'from an unused root meaning to stretch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8357}/H9028/[H7896]', 'inflected', 'heb', 'שֵׁתָה', '["shêthâh"]', '["buttocks/ their"]', '["n-m"]', 'the seat (of the person) buttock.', 'from 7896;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2206}/H9026/[H2204]', 'inflected', 'heb', 'זָקָן', '["zâqân"]', '["beard/ your"]', '["n-m"]', 'the beard (as indicating age) beard.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4601R}/[H4600]', 'lemma', 'heb', 'מַעֲכָה', '["Maʻăkâh"]', '["Maacah"]', '["n-pr"]', 'Maakah (or Maakath), the name of a place in Syria, also of a Mesopotamian, of three Israelites, and of four Israelitesses and one Syrian woman Maachah, Maachathites. See also 1038.', 'or מַעֲכָת; (Joshua 13:13), from 4600; depression;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0758I}/[H759]', 'inflected', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["and/ Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7340K}/[H7339]', 'inflected', 'heb', 'רְחֹב', '["Rᵉchôb"]', '["and/ Rehob"]', '["n-pr-m n-pr-loc"]', 'Rechob, the name of a place in Syria, also of a Syrian and an Israelite Rehob.', 'or רְחוֹב; the same as 7339;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0268}/[H299]', 'inflected', 'heb', 'אָחוֹר', '["ʼâchôwr"]', '["and/ from/ behind"]', '["n-m"]', 'the hinder part; hence (adverb) behind, backward; also (as facing north) the West after(-ward), back (part, -side, -ward), hereafter, (be-) hind(-er part), time to come, without.', 'or (shortened) אָחֹר ; from 299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2388G}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ be strong","so/ he may become strong","so/ let us show ourselves strong","so/ we may show ourselves strong"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971A}/H9025/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["people/ our"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1928}/[H1924]', 'lemma', 'heb', 'הֲדַרְעֶזֶר', '["Hădarʻezer"]', '["Hadadezer"]', '["n-pr-m"]', 'Hadarezer, a Syrian king Hadarezer.', 'from 1924 and 5828; Hadar (i.e. Hadad, 1908) is his help; (i.e. Hadadezer, 1909)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2431}/[H2428]', 'lemma', 'heb', 'חֵילָם', '["Chêylâm"]', '["Helam"]', '["n-pr-m"]', 'Chelam, a place East of Palestine Helam.', 'or חֵלָאםxlit Chêlʼâm corrected to Chêlâʼm; from 2428; fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7731}/[H7730]', 'inflected', 'heb', 'שׁוֹבָךְ', '["Shôwbâk"]', '["and/ Shobach"]', '["n-pr-m"]', 'Shobak, a Syrian Shobach.', 'perhaps for 7730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1732}\/[H1730]', 'inflected', 'heb', 'דָּוִד', '["Dâvid"]', '["of/ David","to/ David"]', '["n-pr-m"]', 'David, the youngest son of Jesse David.', 'rarely (fully); דָּוִיד; from the same as 1730; loving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2431}/H9011/[H2428]', 'inflected', 'heb', 'חֵילָם', '["Chêylâm"]', '["Helam/ towards"]', '["n-pr-m"]', 'Chelam, a place East of Palestine Helam.', 'or חֵלָאםxlit Chêlʼâm corrected to Chêlâʼm; from 2428; fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0758I}/[H759]', 'inflected', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["of/ Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7731}/[H7730]', 'lemma', 'heb', 'שׁוֹבָךְ', '["Shôwbâk"]', '["Shobach"]', '["n-pr-m"]', 'Shobak, a Syrian Shobach.', 'perhaps for 7730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5983}\/[H5971]', 'inflected', 'heb', 'עַמּוֹן', '["ʻAmmôwn"]', '["Ammon"]', '["n-pr-m"]', 'Ammon, a son of Lot; also his posterity and their country Ammon, Ammonites.', 'from 5971; tribal, i.e. inbred;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8666}/[H7725]', 'inflected', 'heb', 'תְּשׁוּבָה', '["tᵉshûwbâh"]', '["to/ [the] return of"]', '["n-f"]', 'a recurrence (of time or place); a reply (as returned) answer, be expired, return.', 'or תְּשֻׁבָה; from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4397>', 'inflected', 'heb', 'המלאכים', '["ha./mali''.Khim"]', '["<the>/ messengers"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3389}\/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["<in>/ Jerusalem","in/ Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1339}/[H1323]', 'lemma', 'heb', 'בַּת־שֶׁבַע', '["Bath-Shebaʻ"]', '["-sheba","Bath-"]', '["n-pr-f"]', 'Bath-Sheba, the mother of Solomon Bath-sheba.', 'from 1323 and 7651 (in the sense of 7650); daughter of an oath;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0463G}/[H410]', 'lemma', 'heb', 'אֱלִיעָם', '["ʼĔlîyʻâm"]', '["Eliam"]', '["n-pr-m"]', 'Eliam, an Israelite Eliam.', 'from 410 and 5971; God of (the) people;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0223A}/[H217]', 'lemma', 'heb', 'אוּרִיָּה', '["ʼÛwrîyâh"]', '["Uriah"]', '["n-pr-m"]', 'Urijah, the name of one Hittite and five Israelites Uriah, Urijah.', 'or (prolonged) אוּרִיָּהוּ ; from 217 and 3050; flame of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2932}/H9024/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["from/ uncleanness/ her"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7965K}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["and/ to/ [the] welfare of"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0223A}/[H217]', 'inflected', 'heb', 'אוּרִיָּה', '["ʼÛwrîyâh"]', '["to/ Uriah"]', '["n-pr-m"]', 'Urijah, the name of one Hittite and five Israelites Uriah, Urijah.', 'or (prolonged) אוּרִיָּהוּ ; from 217 and 3050; flame of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004B}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["to/ house/ your","to/ household/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1870L}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["from/ [the] way of","from/ a journey"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7901G}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ to/ lie"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2416A}/H9021/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["[by] [the] life of/ you"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7937}/H9033/[H7937]', 'inflected', 'heb', 'שָׁכַר', '["shâkar"]', '["and/ he made drunk/ him"]', '["v"]', 'to become tipsy; in a qualified sense, to satiate with a stimulating drink or (figuratively) influence (be filled with) drink (abundantly), (be, make) drunk(-en), be merry. (Superlative of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5612A}/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["in the/ letter","in the/ letters","in the/ scroll","on the/ document","on/ [the] document of"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8104I}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["when/ watched"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3615G}/H9041/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["when/ finishing/ you"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3380}/[H7378]', 'lemma', 'heb', 'יְרֻבֶּשֶׁת', '["Yᵉrubbesheth"]', '["Jerub-Besheth"]', '["n-pr-m"]', 'Jerubbesheth, a symbolic name for Gideon Jerubbesheth.', 'from 7378 and 1322; shame (i.e. the idol) will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4421}/H9021/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["battle/ your","warfare/ your"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2040}/H9034/[H2040]', 'inflected', 'heb', 'הָרַס', '["hâraç"]', '["and/ tear down/ it"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0622}/H9034/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["and/ he gathered/ her"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6223}/[H6238]', 'inflected', 'heb', 'עָשִׁיר', '["ʻâshîyr"]', '["of the/ rich [person]","to/ [the] rich [man]","to/ a rich [person]"]', '["n-m"]', 'rich, whether literal or figurative (noble) rich (man).', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7326}/[H7326]', 'inflected', 'heb', 'רוּשׁ', '["rûwsh"]', '["and/ [belonged] to the/ poor [man]"]', '["v"]', 'to be destitute lack, needy, (make self) poor (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2421}/H9034/[H2331]', 'inflected', 'heb', 'חָיָה', '["châyâh"]', '["and/ he nourished/ it"]', '["v"]', 'to live, whether literally or figuratively; causatively, to revive keep (leave, make) alive, × certainly, give (promise) life, (let, suffer to) live, nourish up, preserve (alive), quicken, recover, repair, restore (to life), revive, (× God) save (alive, life, lives), × surely, be whole.', 'a primitive root (compare 2331, 2421);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6595A}/H9023/[H6626]', 'inflected', 'heb', 'פַּת', '["path"]', '["from/ morsel/ his"]', '["n-f"]', 'a bit meat, morsel, piece.', 'from 6626;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H3563A>/H9023', 'inflected', 'heb', 'ומכסו', '["u./mi./ko.S/o"]', '["and/ from/ cup/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H2436G>/H9023', 'inflected', 'heb', 'ובחיקו', '["u./ve./chei.K/o"]', '["and/ in/ bosom/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1323G}/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["like/ [the] daughters of","like/ a daughter"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6629G>/H9023', 'inflected', 'heb', 'מצאנו', '["mi./tzo.N/o"]', '["one of/ own sheep/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1241}/H9023/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["and/ one of/ own cattle/ his"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0732}/[H732]', 'inflected', 'heb', 'אָרַח', '["ʼârach"]', '["for the/ traveler"]', '["v"]', 'to travel go, wayfaring (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7326}/[H7326]', 'inflected', 'heb', 'רוּשׁ', '["rûwsh"]', '["<the>/ poor"]', '["v"]', 'to be destitute lack, needy, (make self) poor (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6213H}/H9034/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ he prepared/ it"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3535}/[H3532]', 'inflected', 'heb', 'כִּבְשָׂה', '["kibsâh"]', '["the/ ewe-lamb"]', '["n-f"]', 'a ewe (ewe) lamb.', 'or כַּבְשָׂה; feminine of 3532;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0706}/[H702]', 'lemma', 'heb', 'אַרְבַּעְתַּיִם', '["ʼarbaʻtayim"]', '["fourfold"]', '["adv"]', 'fourfold fourfold.', 'dual of 702;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5337}/H9031/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["I delivered/ you","I will deliver/ you","he will deliver/ you"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3254H}/[H3254]', 'inflected', 'heb', 'יָסַף', '["yâçaph"]', '["and/ I have increased","and/ I will add","and/ [who is] increased","and/ let him increase","and/ may he add","so/ may he increase","so/ someone may increase","so/ they may add"]', '["v"]', 'to add or augment (often adverbial, to continue to do a thing) add, × again, × any more, × cease, × come more, conceive again, continue, exceed, × further, × gather together, get more, give more-over, × henceforth, increase (more and more), join, × longer (bring, do, make, much, put), × (the, much, yet) more (and more), proceed (further), prolong, put, be (strong-) er, × yet, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H9039}', 'inflected', 'heb', 'וכהנה', '["ve./kha./He.nah"]', '["and/ like/ them","and/ like/ those"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004M}/H9021/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ house/ your","from/ own house/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0959}/H9030/[H959]', 'inflected', 'heb', 'בָּזָה', '["bâzâh"]', '["you despised/ me"]', '["v"]', 'to disesteem despise, disdain, contemn(-ptible), think to scorn, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H8121>\', 'inflected', 'heb', 'השמש ס', '["ha./Sha.mesh"]', '["the/ sun"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2403B}/H9021/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["sin/ your","sins/ your"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0605}/[H605]', 'inflected', 'heb', 'אָנַשׁ', '["ʼânash"]', '["and/ he was sick"]', '["v"]', 'to be frail, feeble, or (figuratively) melancholy desperate(-ly wicked), incurable, sick, woeful.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6685}/[H6684]', 'lemma', 'heb', 'צוֹם', '["tsôwm"]', '["[the] fast","[the] fast of","a fast","fasting"]', '["n-m"]', 'a fast fast(-ing).', 'or צֹם; from 6684;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8242}/[H8264]', 'inflected', 'heb', 'שַׂק', '["saq"]', '["in <the>/ sackcloth<s>","in the/ sackcloth","with <the>/ sackcloth","with <the>/ sackcloth<s>"]', '["n-m"]', 'properly, a mesh (as allowing a liquid to run through), i.e. coarse loose cloth or sacking (used in mourning and for bagging); hence, a bag (for grain, etc.) sack(-cloth, -clothes).', 'from 8264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6965I}/H9033/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["to/ raise/ him"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1254B}/[H1254]', 'lemma', 'heb', 'בָּרָא', '["bârâʼ"]', '["he ate"]', '["v"]', '(absolutely) to create; (qualified) to cut down (a wood), select, feed (as formative processes) choose, create (creator), cut down, dispatch, do, make (fat).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3907}/[H3907]', 'lemma', 'heb', 'לָחַשׁ', '["lâchash"]', '["[were] whispering to one another","charmers","they whisper to one another"]', '["v"]', 'to whisper; by implication, to mumble a spell (as a magician) charmer, whisper (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4191}/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["¿/ has he died","¿/ really <to put to death>"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6684}/[H6684]', 'lemma', 'heb', 'צוּם', '["tsûwm"]', '["I fasted","I will fast","fasting","have we fasted","they will fast","you fast","you fasted"]', '["v"]', 'to cover over (the mouth), i.e. to fast × at all, fast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2603A}/H9030/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["and/ he will show favor to/ me"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725G}/H9033/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["to/ bring back/ him"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8010}/[H7965]', 'lemma', 'heb', 'שְׁלֹמֹה', '["Shᵉlômôh"]', '["O Solomon","Solomon"]', '["n-pr-m"]', 'Shelomah, David''s successor Solomon.', 'from 7965; peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3041}/[H3039]', 'lemma', 'heb', 'יְדִידְיָה', '["Yᵉdîydᵉyâh"]', '["Jedidiah"]', '["n-pr-m"]', 'Jedidejah, a name of Solomon Jedidiah.', 'from 3039 and 3050; beloved of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3920}/H9034/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["and/ capture/ it"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7237}/H9011/[H7227]', 'inflected', 'heb', 'רַבָּה', '["Rabbâh"]', '["Rabbah/ towards"]', '["n-pr-loc"]', 'Rabbah, the name of two places in Palestine, East and West Rabbah, Rabbath.', 'feminine of 7227; great;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5850}/[H5849]', 'lemma', 'heb', 'עֲטָרָה', '["ʻăṭârâh"]', '["[are the] crown of","[is the] crown of","[is] [the] crown of","[is] a crown of","[the] crown of","a crown of","a crown<s>"]', '["n-f"]', 'a crown crown.', 'from 5849;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4948}/H9024/[H8254]', 'inflected', 'heb', 'מִשְׁקָל', '["mishqâl"]', '["and/ weight/ its"]', '["n-m"]', 'weight (numerically estimated); hence, weighing (the act) (full) weight.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4050}/[H1641]', 'inflected', 'heb', 'מְגֵרָה', '["mᵉgêrâh"]', '["at the/ saws","with <the>/ saw"]', '["n-f"]', 'a saw axe, saw.', 'from 1641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2757}/[H2782]', 'inflected', 'heb', 'חָרִיץ', '["chârîyts"]', '["and/ at/ [the] picks of","and/ with/ [the] sharp instruments of"]', '["n-m"]', 'properly, incisure or (passively) incised; hence, a threshing-sledge (with sharp teeth); also a slice (as cut) cheese, harrow.', 'or חֲרִץ; from 2782; (compare 2742)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4037}/[H1504]', 'inflected', 'heb', 'מַגְזֵרָה', '["magzêrâh"]', '["and/ at/ [the] axes of"]', '["n-f"]', 'a cutting implement, i.e. a blade axe.', 'from 1504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4404}/[H3835]', 'inflected', 'heb', 'מַלְבֵּן', '["malbên"]', '["in the/ brick mold[s]","in the/ brick-terrace"]', '["n-m"]', 'a brickkiln brickkiln.', 'from 3835 (denominative);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3389}\/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0053}/[H1]', 'inflected', 'heb', 'אֲבִישָׁלוֹם', '["ʼĂbîyshâlôwm"]', '["and/ [belonged] to/ Absalom"]', '["n-pr-m"]', 'Abshalom, a son of David; also (the fuller form) a later Israelite Abishalom, Absalom.', 'or (shortened) אַבְשָׁלוֹם ; from 1 and 7965; father of peace (i.e. friendly);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8559H}/[H8558]', 'lemma', 'heb', 'תָּמָר', '["Tâmâr"]', '["Tamar","[was] Tamar"]', '["n-pr"]', 'Tamar, the name of three women and a place Tamar.', 'the same as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0550G}/[H539]', 'inflected', 'heb', 'אַמְנוֹן', '["ʼAmnôwn"]', '["to/ Amnon"]', '["n-m"]', 'Amnon (or Aminon), a son of David Amnon.', 'or אֲמִינוֹן; from 539; faithful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2470H}/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["to/ make himself sick"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0550G}/[H539]', 'inflected', 'heb', 'אַמְנוֹן', '["ʼAmnôwn"]', '["and/ [belonged] to/ Amnon"]', '["n-m"]', 'Amnon (or Aminon), a son of David Amnon.', 'or אֲמִינוֹן; from 539; faithful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7453}/[H7462]', 'lemma', 'heb', 'רֵעַ', '["rêaʻ"]', '["O friends","[the] friends of","[was] [the] friend of","a companion","a friend","companions","friends","neighbor"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3122G}/[H3082]', 'lemma', 'heb', 'יוֹנָדָב', '["Yôwnâdâb"]', '["Jonadab","[was] Jonadab"]', '["n-pr-m"]', 'Jonadab, the name of an Israelite and of a Rechabite Jonadab.', 'a form of 3082;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8093}/[H8088]', 'lemma', 'heb', 'שִׁמְעָה', '["Shimʻâh"]', '["Shimeah"]', '["n-pr-m"]', 'Shimah, an Israelite Shimeah.', 'feminine of 8088; annunciation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3122G}/[H3082]', 'inflected', 'heb', 'יוֹנָדָב', '["Yôwnâdâb"]', '["and/ Jonadab"]', '["n-pr-m"]', 'Jonadab, the name of an Israelite and of a Rechabite Jonadab.', 'a form of 3082;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3082H}/[H3068]', 'lemma', 'heb', 'יְהוֹנָדָב', '["Yᵉhôwnâdâb"]', '["Jonadab"]', '["n-pr-m"]', 'Jehonadab, the name of an Israelite and of an Arab Jehonadab, Jonadab. Compare 3122.', 'from 3068 and 5068; Jehovah-largessed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2470H}/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["and/ I was sick","and/ a sick [animal]","and/ make yourself sick"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7200G}/H9031/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["to/ see/ you"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1262}/H9030/[H1250]', 'inflected', 'heb', 'בָּרָה', '["bârâh"]', '["and/ let her cause to eat/ me"]', '["v"]', 'to select; to feed; to render clear choose, (cause to) eat, manifest, (give) meat.', 'a primitive root; to select; also (as denominative from 1250) to feed; also (as equivalent to 1305) to render clear (Ecclesiastes 3:18)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5869H}/H9020/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["to/ eyes/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1279}/[H1262]', 'inflected', 'heb', 'בִּרְיָה', '["biryâh"]', '["the/ food"]', '["n-f"]', 'food meat.', 'feminine from 1262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027G}/H9024/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ her"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2470H}/[H2342]', 'inflected', 'heb', 'חָלָה', '["châlâh"]', '["and/ he became ill","and/ he made himself sick"]', '["v"]', 'properly, to be rubbed or worn; hence (figuratively) to be weak, sick, afflicted; or (causatively) to grieve, make sick; also to stroke (in flattering), entreat beseech, (be) diseased, (put to) grief, be grieved, (be) grievous, infirmity, intreat, lay to, put to pain, × pray, make prayer, be (fall, make) sick, sore, be sorry, make suit (× supplication), woman in travail, be (become) weak, be wounded.', 'a primitive root (compare 2342, 2470, 2490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7200G}/H9033/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["to/ see/ him"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3823B}/[H3823]', 'inflected', 'heb', 'לָבַב', '["lâbab"]', '["and/ let her make cakes"]', '["v"]', 'properly, to be enclosed (as if with fat); by implication (as denominative from 3824); to unheart; i.e. (in a good sense) transport (with love), or (in a bad sense) stultify; to make cakes make cakes, ravish, be wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3834}/[H3823]', 'lemma', 'heb', 'לָבִיבָה', '["lâbîybâh"]', '["cakes"]', '["n-f"]', 'a cake (either as fried or turned) cake.', 'or rather לְבִבָה; from 3823 in its original sense of fatness (or perhaps of folding);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1262}/[H1250]', 'inflected', 'heb', 'בָּרָה', '["bârâh"]', '["so/ I may eat"]', '["v"]', 'to select; to feed; to render clear choose, (cause to) eat, manifest, (give) meat.', 'a primitive root; to select; also (as denominative from 1250) to feed; also (as equivalent to 1305) to render clear (Ecclesiastes 3:18)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3823B}/[H3823]', 'inflected', 'heb', 'לָבַב', '["lâbab"]', '["and/ she made cakes"]', '["v"]', 'properly, to be enclosed (as if with fat); by implication (as denominative from 3824); to unheart; i.e. (in a good sense) transport (with love), or (in a bad sense) stultify; to make cakes make cakes, ravish, be wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3834}/[H3823]', 'inflected', 'heb', 'לָבִיבָה', '["lâbîybâh"]', '["the/ cakes"]', '["n-f"]', 'a cake (either as fried or turned) cake.', 'or rather לְבִבָה; from 3823 in its original sense of fatness (or perhaps of folding);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4958>', 'inflected', 'heb', 'המשרת', '["ha./mas.Ret"]', '["the/ pan"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3332I}/[H3332]', 'inflected', 'heb', 'יָצַק', '["yâtsaq"]', '["and/ she poured out","and/ they set down"]', '["v"]', 'properly, to pour out (transitive or intransitive); by implication, to melt or cast as metal; by extension, to place firmly, to stiffen or grow hard cast, cleave fast, be (as) firm, grow, be hard, lay out, molten, overflow, pour (out), run out, set down, stedfast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2315}/[H2314]', 'inflected', 'heb', 'חֶדֶר', '["cheder"]', '["the/ chamber"]', '["n-m"]', 'an apartment (usually literal) ((bed) inner) chamber, innermost(-ward) part, parlour, south, × within.', 'from 2314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027G}/H9022/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6031B}/H9030/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["you have afflicted/ me","you humble/ me"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5036}/[H5034]', 'inflected', 'heb', 'נָבָל', '["nâbâl"]', '["the/ foolish women","the/ fools"]', '["a"]', 'stupid; wicked (especially impious) fool(-ish, -ish man, -ish woman), vile person.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963L>/H9024', 'inflected', 'heb', 'בקולה', '["be./ko.La/h"]', '["to/ voice/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8135}/[H8130]', 'lemma', 'heb', 'שִׂנְאָה', '["sinʼâh"]', '["hatred"]', '["n-f"]', 'hate exceedingly, hate(-ful, -red).', 'from 8130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8135}/[H8130]', 'inflected', 'heb', 'שִׂנְאָה', '["sinʼâh"]', '["the/ hatred"]', '["n-f"]', 'hate exceedingly, hate(-ful, -red).', 'from 8130;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157G}/H9034/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["[those who] love/ it","he had loved/ her","he loves/ it","love/ her","lovers/ her"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0312}/[H309]', 'inflected', 'heb', 'אַחֵר', '["ʼachêr"]', '["[be] more than/ [the] other"]', '["a"]', 'properly, hinder; generally, next, other, etc. (an-) other man, following, next, strange.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7971G}/H9030/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["to/ send away/ me"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5274A}/[H5275]', 'inflected', 'heb', 'נָעַל', '["nâʻal"]', '["and/ lock"]', '["v"]', 'properly, to fasten up, i.e. with a bar or cord; hence, to sandal, i.e. furnish with slippers bolt, inclose, lock, shoe, shut up.', 'a primitive root; also denominative from 5275');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5921A}/H9034/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["and/ [was] on/ her","and/ over/ her","and/ over/ it"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0550G}/[H539]', 'inflected', 'heb', 'אַמְנוֹן', '["ʼAmnôwn"]', '["¿/ Amnon"]', '["n-m"]', 'Amnon (or Aminon), a son of David Amnon.', 'or אֲמִינוֹן; from 539; faithful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3820A}/H9022/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["heart/ your"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8076}/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["<and>/ a desolate [woman]"]', '["a"]', 'ruined desolate.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/{H7451A}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<to>/ from/ bad"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0269}/H9023\/[H251]', 'inflected', 'heb', 'אָחוֹת', '["ʼâchôwth"]', '["sister/ his"]', '["n-f"]', 'a sister (used very widely [like 251number 250, corrected to 251], literally and figuratively) (an-) other, sister, together.', 'irregular feminine of 251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0053}/[H1]', 'inflected', 'heb', 'אֲבִישָׁלוֹם', '["ʼĂbîyshâlôwm"]', '["<to>/ Absalom","for/ Absalom","to/ Absalom"]', '["n-pr-m"]', 'Abshalom, a son of David; also (the fuller form) a later Israelite Abishalom, Absalom.', 'or (shortened) אַבְשָׁלוֹם ; from 1 and 7965; father of peace (i.e. friendly);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1178}/[H1167]', 'inflected', 'heb', 'בַּעַל חָצוֹר', '["Baʻal Châtsôwr"]', '["at/ Baal"]', '["n-pr-loc"]', 'Baal-Chatsor, a place in Palestine Baal-hazor.', 'from 1167 and a modification of 2691; possessor of a village;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1178}/[H1167]', 'lemma', 'heb', 'בַּעַל חָצוֹר', '["Baʻal Châtsôwr"]', '["Hazor"]', '["n-pr-loc"]', 'Baal-Chatsor, a place in Palestine Baal-hazor.', 'from 1167 and a modification of 2691; possessor of a village;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0669L}/[H672]', 'lemma', 'heb', 'אֶפְרַיִם', '["ʼEphrayim"]', '["Ephraim"]', '["n-pr-m"]', 'Ephrajim, a son of Joseph; also the tribe descended from him, and its territory Ephraim, Ephraimites.', 'dual of masculine form of 672; double fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6505}/H9023/[H6504]', 'inflected', 'heb', 'פֶּרֶד', '["pered"]', '["mule/ his"]', '["n-m"]', 'a mule (perhaps from his lonely habits) mule.', 'from 6504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8052}/[H8074]', 'inflected', 'heb', 'שְׁמוּעָה', '["shᵉmûwʻâh"]', '["and/ the/ report"]', '["n-f"]', 'something heard, i.e. an announcement bruit, doctrine, fame, mentioned, news, report, rumor, tidings.', 'feminine passive participle of 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0899B}\/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["garments"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760B}/[H7760]', 'lemma', 'heb', 'שׂוּם', '["sûwm"]', '["determined"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6031B}/H9043/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["being afflicted/ he","humbled/ he"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2773}/[H2356]', 'lemma', 'heb', 'חֹרֹנַיִם', '["Chôrônayim"]', '["Horonaim"]', '["n-pr-m"]', 'Choronajim, a place in Moab Horonaim.', 'dual of a derivative from 2356; double cave-town;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1697H}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["according to/ [the] word of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0053}/[H1]', 'inflected', 'heb', 'אֲבִישָׁלוֹם', '["ʼĂbîyshâlôwm"]', '["and/ Absalom"]', '["n-pr-m"]', 'Abshalom, a son of David; also (the fuller form) a later Israelite Abishalom, Absalom.', 'or (shortened) אַבְשָׁלוֹם ; from 1 and 7965; father of peace (i.e. friendly);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5989J}/[H5971]', 'lemma', 'heb', 'עַמִּיהוּד', '["ʻAmmîyhûwd"]', '["Ammihud"]', '["n-pr-m"]', 'Ammihud, the name of three Israelites Ammihud.', 'from 5971 and 1935; people of splendor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3615I}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["and/ it [fem] completed"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8620}/H9011/[H8619]', 'inflected', 'heb', 'תְּקוֹעַ', '["Tᵉqôwaʻ"]', '["Tekoa/ towards"]', '["n-pr-m n-pr-loc"]', 'Tekoa, a place in Palestine Tekoa, Tekoah.', 'a form of 8619;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3847}/[H3847]', 'inflected', 'heb', 'לָבַשׁ', '["lâbash"]', '["and/ I will clothe","and/ put on"]', '["v"]', 'properly, wrap around, i.e. (by implication) to put on a garment or clothe (oneself, or another), literally or figuratively (in) apparel, arm, array (self), clothe (self), come upon, put (on, upon), wear.', 'or לָבֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8621}/[H8620]', 'inflected', 'heb', 'תְּקוֹעִי', '["Tᵉqôwʻîy"]', '["<the>/ Tekoite","the/ Tekoite","the/ Tekoites"]', '["a"]', 'a Tekoite or inhabitant of Tekoah Tekoite.', 'or תְּקֹעִי; patronymically from 8620;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639I}/H9024/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["face/ her"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3467}/H9012/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["save/ !"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H8198>/H9021', 'inflected', 'heb', 'ולשפחתך', '["u./le./shif.cha.te./Kha"]', '["and/ [belonged] to/ maidservant/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8045}/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["and/ let us destroy"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3423G}/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["the/ heir"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3518}/[H3518]', 'inflected', 'heb', 'כָּבָה', '["kâbâh"]', '["and/ they extinguished","and/ they will extinguish"]', '["v"]', 'to expire or (causatively) to extinguish (fire, light, anger) go (put) out, quench.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1513>/H9020', 'opaque', 'heb', 'גֶּחֶל', '["gechel"]', '["coal/ my"]', '["n-f"]', 'an ember (burning) coal.', 'or (feminine) גַּחֶלֶת; from an unused root meaning to glow or kindle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7611}/[H7604]', 'inflected', 'heb', 'שְׁאֵרִית', '["shᵉʼêrîyth"]', '["and/ a remnant"]', '["n-f"]', 'a remainder or residual (surviving, final) portion that had escaped, be left, posterity, remain(-der), remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3678G}/H9023/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["and/ throne/ his"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5355A}\/[H5352]', 'inflected', 'heb', 'נָקִי', '["nâqîy"]', '["[be] innocent"]', '["a"]', 'innocent blameless, clean, clear, exempted, free, guiltless, innocent, quit.', 'or נָקִיא; (Joel 4:19; Jonah 1:14), from 5352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7235A}/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["from/ increasing","from/ many"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1696I}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ <from>/ because has spoken"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0818}/[H816]', 'inflected', 'heb', 'אָשֵׁם', '["ʼâshêm"]', '["like/ a guilty [person]"]', '["a"]', 'guilty; hence, presenting a sin-offering one which is faulty, guilty.', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5080}/H9033/[H5080]', 'inflected', 'heb', 'נָדַח', '["nâdach"]', '["banished [son]/ his","she impels/ him"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4325G}/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["and/ [we are] like <the>/ waters"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5064}/[H5064]', 'inflected', 'heb', 'נָגַר', '["nâgar"]', '["which/ are spilled"]', '["v"]', 'to flow; figuratively, to stretch out; causatively, to pour out or down; figuratively, to deliver over fall, flow away, pour down (out), run, shed, spilt, trickle down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2803G}/[H2803]', 'inflected', 'heb', 'חָשַׁב', '["châshab"]', '["and/ he plans"]', '["v"]', 'properly, to plait or interpenetrate, i.e. (literally) to weave or (generally) to fabricate; figuratively, to plot or contrive (usually in a malicious sense); hence (from the mental effort) to think, regard, value, compute (make) account (of), conceive, consider, count, cunning (man, work, workman), devise, esteem, find out, forecast, hold, imagine, impute, invent, be like, mean, purpose, reckon(-ing be made), regard, think.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3372G}/H9030/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["they have made afraid/ me"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4496H}/[H4495]', 'inflected', 'heb', 'מְנוּחָה', '["mᵉnûwchâh"]', '["<into>/ rest"]', '["n-f"]', 'repose or (adverbially) peacefully; figuratively, consolation (specifically, matrimony); hence (concretely) an abode comfortable, ease, quiet, rest(-ing place), still.', 'or מְנֻחָה; feminine of 4495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7451B}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["and/ <the>/ bad"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0786}/[H784]', 'lemma', 'heb', 'אִשׁ', '["ʼish"]', '["there is"]', '["adv"]', 'entity, used only adverbially, there is or are are there, none can. Compare 3426.', 'identical (in origin and formation) with 784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3231}/[H3225]', 'inflected', 'heb', 'יָמַן', '["yâman"]', '["to/ go to [the] right"]', '["v"]', 'to be right-handed or take the right-hand side go (turn) to (on, use) the right hand.', 'a primitive root; to be (physically) right (i.e. firm); but used only as denominative from 3225 and transitive,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8041}/[H8040]', 'inflected', 'heb', 'שָׂמַאל', '["sâmaʼl"]', '["and/ to/ go to [the] left"]', '["v"]', 'to use the left hand or pass in that direction (go, turn) (on the, to the) left.', 'a primitive root (denominative from 8040);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5437K}/[H5437]', 'lemma', 'heb', 'סָבַב', '["çâbab"]', '["to change"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2451}/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["like/ [the] wisdom of"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0776G>\', 'inflected', 'heb', 'בארצות פ', '["ba./''A.retz","ba./''a.ra.Tzot"]', '["[is] in the/ land","among the/ lands","in the/ land","on the/ earth","over the/ land"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1650>/H9011', 'opaque', 'heb', 'גְּשׁוּר', '["Gᵉshûwr"]', '["Geshur/ towards"]', '["n-pr-m"]', 'Geshur, a district of Syria Geshur, Geshurite.', 'from an unused root (meaning to join); bridge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440G}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ face/ my"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440G}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ [the] face of"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0053}/[H1]', 'inflected', 'heb', 'אֲבִישָׁלוֹם', '["ʼĂbîyshâlôwm"]', '["and/ like/ Absalom"]', '["n-pr-m"]', 'Abshalom, a son of David; also (the fuller form) a later Israelite Abishalom, Absalom.', 'or (shortened) אַבְשָׁלוֹם ; from 1 and 7965; father of peace (i.e. friendly);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1984B}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["to/ praise"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6936}/H9023/[H6915]', 'inflected', 'heb', 'קׇדְקֹד', '["qodqôd"]', '["scalp/ his"]', '["n-m"]', 'the crown of the head (as the part most bowed) crown (of the head), pate, scalp, top of the head.', 'from 6915;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1548}/H9043/[H1548]', 'inflected', 'heb', 'גָּלַח', '["gâlach"]', '["and/ when/ shaved/ he"]', '["v"]', 'properly, to be bald, i.e. (causatively) to shave; figuratively to lay waste poll, shave (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1548}/H9033/[H1548]', 'inflected', 'heb', 'גָּלַח', '["gâlach"]', '["and/ he shaved/ it"]', '["v"]', 'properly, to be bald, i.e. (causatively) to shave; figuratively to lay waste poll, shave (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0068H}/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["by/ [the] weight of"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8559I}/[H8558]', 'lemma', 'heb', 'תָּמָר', '["Tâmâr"]', '["[was] Tamar"]', '["n-pr"]', 'Tamar, the name of three women and a place Tamar.', 'the same as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4758}\/[H7200]', 'inflected', 'heb', 'מַרְאֶה', '["marʼeh"]', '["appearance"]', '["n-m"]', 'a view (the act of seeing); also an appearance (the thing seen), whether (real) a shape (especially if handsome, comeliness; often plural the looks), or (mental) a vision × apparently, appearance(-reth), × as soon as beautiful(-ly), countenance, fair, favoured, form, goodly, to look (up) on (to), look(-eth), pattern, to see, seem, sight, visage, vision.', 'from 7200a;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3341}/H9034/[H3341]', 'inflected', 'heb', 'יָצַת', '["yâtsath"]', '["and/ set on fire/ it"]', '["v"]', 'to burn or set on fire; figuratively, to desolate burn (up), be desolate, set (on) fire (fire), kindle.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2513A}/[H2506]', 'inflected', 'heb', 'חֶלְקָה', '["chelqâh"]', '["<the>/ portion of land","the/ portion","the/ portion of land"]', '["n-f"]', 'properly, smoothness; figuratively, flattery; also an allotment field, flattering(-ry), ground, parcel, part, piece of land (ground), plat, portion, slippery place, smooth (thing).', 'feminine of 2506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1650>', 'inflected', 'heb', 'מגשור', '["mi./ge.Shur"]', '["from/ Geshur"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4191}/H9030/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ he will kill/ me"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639I}/H9023/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["face/ his","nose/ his"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0053}\/[H1]', 'inflected', 'heb', 'אֲבִישָׁלוֹם', '["ʼĂbîyshâlôwm"]', '["<to>/ Absalom","to/ Absalom"]', '["n-pr-m"]', 'Abshalom, a son of David; also (the fuller form) a later Israelite Abishalom, Absalom.', 'or (shortened) אַבְשָׁלוֹם ; from 1 and 7965; father of peace (i.e. friendly);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697L}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["matter/ your","words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5228}/[H5226]', 'inflected', 'heb', 'נָכֹחַ', '["nâkôach"]', '["and/ right"]', '["a"]', 'straightforward, i.e. (figuratively), equitable, correct, or (abstractly), integrity plain, right, uprightness.', 'from the same as 5226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5921A}/H9030/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["and/ [is] towards/ me","and/ on/ me","and/ to/ me","and/ towards/ me"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6663}/H9033/[H6663]', 'inflected', 'heb', 'צָדַק', '["tsâdaq"]', '["and/ I will do justice/ him"]', '["v"]', 'to be (causatively, make) right (in a moral or forensic sense) cleanse, clear self, (be, do) just(-ice, -ify, -ify self), (be turn to) righteous(-ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7126G}/[H7126]', 'inflected', 'heb', 'קָרַב', '["qârab"]', '["when/ drew near"]', '["v"]', 'to approach (causatively, bring near) for whatever purpose (cause to) approach, (cause to) bring (forth, near), (cause to) come (near, nigh), (cause to) draw near (nigh), go (near), be at hand, join, be near, offer, present, produce, make ready, stand, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5088}/H9020/[H5087]', 'inflected', 'heb', 'נֶדֶר', '["neder"]', '["vow/ my","vows/ my"]', '["n-m"]', 'a promise (to God); also (concretely) a thing promised vow(-ed).', 'or נֵדֶר; from 5087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3427}/H9040/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["when/ dwelt/ I"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1650>', 'inflected', 'heb', 'בגשור', '["vi/g.Shur"]', '["at/ Geshur"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725H}/H9030/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["he will bring back/ me"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2275A}/H9011\/[H2267]', 'inflected', 'heb', 'חֶבְרוֹן', '["Chebrôwn"]', '["Hebron/ towards"]', '["n-pr-loc n-pr-m"]', 'Chebron, a place in Palestine, also the name of two Israelites Hebron.', 'from 2267; seat of association;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8537}/H9028/[H8552]', 'inflected', 'heb', 'תֹּם', '["tôm"]', '["to/ innocence/ their"]', '["n-m"]', 'completeness; figuratively, prosperity; usually (morally) innocence full, integrity, perfect(-ion), simplicity, upright(-ly, -ness), at a venture. See 8550.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0302}/[H251]', 'lemma', 'heb', 'אֲחִיתֹפֶל', '["ʼĂchîythôphel"]', '["Ahithophel"]', '["n-pr-m"]', 'Achithophel, an Israelite Ahithophel.', 'from 251 and 8602; brother of folly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1526}/[H1542]', 'inflected', 'heb', 'גִּילֹנִי', '["Gîylônîy"]', '["the/ Gilonite"]', '["a"]', 'a Gilonite or inhabitant of Giloh Gilonite.', 'patrial from 1542;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3289}/[H3289]', 'lemma', 'heb', 'יָעַץ', '["yâʻats"]', '["I counsel","I have counseled","I have planned","I will counsel [you]","[is] a counselor","[is] planning","[the] counselor of","[those who] receive advice","[was] a counselor","a counselor","counseling","counselor[s]","counselors","did he plan","did he take counsel","has he planned","he counseled","he has counseled","he has planned","he plans","it has planned","let them take counsel","they have consulted","they have planned","you have counseled","you have planned"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1542}/[H1540]', 'inflected', 'heb', 'גִּלֹה', '["Gilôh"]', '["from/ Giloh"]', '["n-pr-loc"]', 'Giloh, a place in Palestine Giloh.', 'or (fully) גִּילֹה; from 1540; open;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2076}/H9043/[H2076]', 'inflected', 'heb', 'זָבַח', '["zâbach"]', '["when/ sacrificed/ he"]', '["v"]', 'to slaughter an animal (usually in sacrifice) kill, offer, (do) sacrifice, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7195}/[H7194]', 'inflected', 'heb', 'קֶשֶׁר', '["qesher"]', '["the/ conspiracy"]', '["n-m"]', 'an (unlawful) alliance confederacy, conspiracy, treason.', 'from 7194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0533}/[H553]', 'lemma', 'heb', 'אַמִּיץ', '["ʼammîyts"]', '["a strong [one]","strong"]', '["a"]', 'strong or (abstractly) strength courageous, mighty, strong (one).', 'or (shortened) אַמִּץ; from 553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1272}/[H1272]', 'inflected', 'heb', 'בָּרַח', '["bârach"]', '["so/ let us flee"]', '["v"]', 'to bolt, i.e. figuratively, to flee suddenly chase (away); drive away, fain, flee (away), put to flight, make haste, reach, run away, shoot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5381}/H9035/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["and/ he will overtake/ us"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4801}/[H7368]', 'inflected', 'heb', 'מֶרְחָק', '["merchâq"]', '["<the>/ distance","the/ distance"]', '["n-m"]', 'remoteness, i.e. (concretely) a distant place; often (adverbially) from afar (a-, dwell in, very) far (country, off). See also 1023.', '; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3774H}/[H3772]', 'inflected', 'heb', 'כְּרֵתִי', '["Kᵉrêthîy"]', '["the/ Kerethite[s]"]', '["a"]', 'a Kerethite or life-guardsman Cherethims, Cherethites.', 'probably from 3772 in the sense of executioner; (compare 2876) (only collectively in the singular as plural)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6432}/[H6431]', 'inflected', 'heb', 'פְּלֵתִי', '["Pᵉlêthîy"]', '["the/ Pelethite[s]"]', '["a"]', 'a courier (collectively) or official messenger Pelethites.', 'from the same form as 6431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0863G}/[H854]', 'lemma', 'heb', 'אִתַּי', '["ʼIttay"]', '["Ittai"]', '["n-pr-m"]', 'Ittai or Ithai, the name of a Gittite and of an Israelite Ithai, Ittai.', 'or אִיתַי; from 854; near;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4725}/H9021/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["to/ place/ your"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5128}/H9031/[H5128]', 'inflected', 'heb', 'נוּעַ', '["nûwaʻ"]', '["will I make wander?/ you"]', '["v"]', 'to waver, in a great variety of applications, literally and figuratively (as subjoined) continually, fugitive, × make, to (go) up and down, be gone away, (be) move(-able, -d), be promoted, reel, remove, scatter, set, shake, sift, stagger, to and fro, be vagabond, wag, (make) wander (up and down).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4194}/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["[are] for <the>/ death","for <the>/ death","for/ death","to <the>/ death"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5158A}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["at/ [the] wadi of","in/ [the] wadi of"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6939}/[H6937]', 'lemma', 'heb', 'קִדְרוֹן', '["Qidrôwn"]', '["Kidron"]', '["n-pr"]', 'Kidron, a brook near Jerusalem Kidron.', 'from 6937; dusky place;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6659G}/[H6663]', 'lemma', 'heb', 'צָדוֹק', '["Tsâdôwq"]', '["Zadok","[are] Zadok"]', '["n-pr-m"]', 'Tsadok, the name of eight or nine Israelites Zadok.', 'from 6663; just;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6659G}/[H6663]', 'inflected', 'heb', 'צָדוֹק', '["Tsâdôwq"]', '["<to>/ Zadok","of/ Zadok","to/ Zadok"]', '["n-pr-m"]', 'Tsadok, the name of eight or nine Israelites Zadok.', 'from 6663; just;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725G}/H9030/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ he brought back/ me","and/ he will bring back/ me"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5116A}/H9023/[H5115]', 'inflected', 'heb', 'נָוֶה', '["nâveh"]', '["estate/ his","habitation/ his","habitation/ its","pasture/ its"]', '["n"]', '(adjectively) at home; hence (by implication of satisfaction) lovely; also (noun) a home, of God (temple), men (residence), flocks (pasture), or wild animals (den) comely, dwelling (place), fold, habitation, pleasant place, sheepcote, stable, tarried.', 'or (feminine) נָוָה; from 5115;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7200L}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["¿/ a seer"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0290H}/[H251]', 'inflected', 'heb', 'אֲחִימַעַץ', '["ʼĂchîymaʻats"]', '["and/ Ahimaaz"]', '["n-pr-loc"]', 'Achimaats, the name of three Israelites Ahimaaz.', 'from 251 and the equivalent of 4619; brother of anger;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3083I}/[H3068]', 'inflected', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["and/ Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5973B}/H9036/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["from/ with <the>/ you"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0054}/[H1]', 'inflected', 'heb', 'אֶבְיָתָר', '["ʼEbyâthâr"]', '["and/ Abiathar"]', '["n-pr-m"]', 'Ebjathar, an Israelite Abiathar.', 'contracted from 1 and 3498; father of abundance (i.e. liberal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2132G>', 'inflected', 'heb', 'הזיתים', '["ha./ze.Tim","ha./zei.Tim"]', '["<the>/ Olives","the/ olive trees"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2645}/[H2644]', 'lemma', 'heb', 'חָפָה', '["châphâh"]', '["[are] covered","[was] covered","he overlaid","they covered","they have covered"]', '["v"]', 'to cover; by implication, to veil, to encase, protect ceil, cover, overlay.', 'a primitive root (compare 2644, 2653);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3182>', 'opaque', 'heb', 'יָחֵף', '["yâchêph"]', '["barefoot"]', '["a"]', 'unsandalled barefoot, being unshod.', 'from an unused root meaning to take off the shoes;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7194}/[H7194]', 'inflected', 'heb', 'קָשַׁר', '["qâshar"]', '["[is] among the/ conspirators"]', '["v"]', 'to tie, physically (gird, confine, compact) or mentally (in love, league) bind (up), (make a) conspire(-acy, -ator), join together, knit, stronger, work (treason).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7218I>', 'inflected', 'heb', 'הראש', '["ha./Rosh"]', '["the/ top"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2365}/[H2363]', 'lemma', 'heb', 'חוּשַׁי', '["Chûwshay"]', '["Hushai"]', '["n-pr-m"]', 'Chushai, an Israelite Hushai.', 'from 2363; hasty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4853A}/[H5375]', 'inflected', 'heb', 'מַשָּׂא', '["massâʼ"]', '["<into>/ a burden"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9008/{H3808}/[H3808]', 'inflected', 'heb', 'לֹא', '["lôʼ"]', '["and/ ¿/ not"]', '["adv"]', 'not (the simple or abs. negation); by implication, no; often used with other particles × before, or else, ere, except, ig(-norant), much, less, nay, neither, never, no((-ne), -r, (-thing)), (× as though...,(can-), for) not (out of), of nought, otherwise, out of, surely, as truly as, of a truth, verily, for want, whether, without.', 'or לוֹא; or לֹה; (Deuteronomy 3:11), a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0054}/[H1]', 'inflected', 'heb', 'אֶבְיָתָר', '["ʼEbyâthâr"]', '["and/ <to>/ Abiathar","and/ for/ Abiathar","and/ to/ Abiathar"]', '["n-pr-m"]', 'Ebjathar, an Israelite Abiathar.', 'contracted from 1 and 3498; father of abundance (i.e. liberal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0290H}/[H251]', 'lemma', 'heb', 'אֲחִימַעַץ', '["ʼĂchîymaʻats"]', '["Ahimaaz","[are] Ahimaaz"]', '["n-pr-loc"]', 'Achimaats, the name of three Israelites Ahimaaz.', 'from 251 and the equivalent of 4619; brother of anger;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027J}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["by/ hand/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7463}/[H7462]', 'lemma', 'heb', 'רֵעֶה', '["rêʻeh"]', '["[the] friend of"]', '["n-m"]', 'a (male) companion friend.', 'from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/<H7218I>', 'inflected', 'heb', 'מהראש', '["me./ha./Rosh"]', '["from/ the/ top"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7019}/[H6972]', 'lemma', 'heb', 'קַיִץ', '["qayits"]', '["summer","summer fruit"]', '["n-m"]', 'harvest (as the crop), whether the product (grain or fruit) or the (dry) season summer (fruit, house).', 'from 6972;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7392}/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["to the/ rider","to/ ride"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3899H}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["and/ the/ bread"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7019}/[H6972]', 'inflected', 'heb', 'קַיִץ', '["qayits"]', '["and/ the/ summer fruit"]', '["n-m"]', 'harvest (as the crop), whether the product (grain or fruit) or the (dry) season summer (fruit, house).', 'from 6972;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H3196>', 'inflected', 'heb', 'והיין', '["ve./hai./Ya.yin"]', '["and/ the/ wine"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6717}/[H6678]', 'inflected', 'heb', 'צִיבָא', '["Tsîybâʼ"]', '["to/ Ziba"]', '["n-pr-m"]', 'Tsiba, an Israelite Ziba.', 'from the same as 6678; station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8096H}/[H8088]', 'lemma', 'heb', 'שִׁמְעִי', '["Shimʻîy"]', '["Shimei","[was] Shimei"]', '["n-pr-m"]', 'Shimi, the name of twenty Israelites Shimeah (from the margin), Shimei, Shimhi, Shimi.', 'from 8088; famous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1617H}/[H1626]', 'lemma', 'heb', 'גֵּרָא', '["Gêrâʼ"]', '["Gera"]', '["n-pr-m"]', 'Gera, the name of six Israelites Gera.', 'perhaps from 1626; a grain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8040G}/H9023/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["and/ from/ left/ his"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7043}/H9043/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["when/ cursed/ he"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2005}/H9041/[H2005]', 'inflected', 'heb', 'הֵן', '["hên"]', '["and/ here/ you","and/ there/ you"]', '["prt"]', 'lo!; also (as expressing surprise) if behold, if, lo, though.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7451I}/H9021/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["[are] in/ calamity/ your"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218A>/H9023\', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ his"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3651C}\/[H3559]', 'inflected', 'heb', 'כֵּן', '["kên"]', '["thus"]', '["adv"]', 'properly, set upright; hence (figuratively as adjective) just; but usually (as adverb or conjunction) rightly or so (in various applications to manner, time and relation; often with other particles) after that (this, -ward, -wards), as... as, (for-) asmuch as yet, be (for which) cause, following, howbeit, in (the) like (manner, -wise), × the more, right, (even) so, state, straightway, such (thing), surely, there (where) -fore, this, thus, true, well, × you.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121G}/H9020/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["son/ my"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H4578>/H9020', 'inflected', 'heb', 'ממעי', '["mi./me.''A/i"]', '["from/ inward parts/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869K}/H9020/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["on/ sin/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7045}/H9023/[H7043]', 'inflected', 'heb', 'קְלָלָה', '["qᵉlâlâh"]', '["curse/ his"]', '["n-f"]', 'vilification (ac-) curse(-d, -ing).', 'from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870K}\/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["on the/ road"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8096H}/[H8088]', 'inflected', 'heb', 'שִׁמְעִי', '["Shimʻîy"]', '["and/ Shimei"]', '["n-pr-m"]', 'Shimi, the name of twenty Israelites Shimeah (from the margin), Shimei, Shimhi, Shimi.', 'from 8088; famous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6763}/[H6760]', 'inflected', 'heb', 'צֵלָע', '["tsêlâʻ"]', '["on/ [the] side of","with/ boards of"]', '["n-f"]', 'a rib (as curved), literally (of the body) or figuratively (of a door, i.e. leaf); hence, a side, literally (of a person) or figuratively (of an object or the sky, i.e. quarter); architecturally, a (especially floor or ceiling) timber or plank (single or collective, i.e. a flooring) beam, board, chamber, corner, leaf, plank, rib, side (chamber).', 'or (feminine) צַלְעָה; from 6760;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5980}/H9033/[H6004]', 'inflected', 'heb', 'עֻמָּה', '["ʻummâh"]', '["<to>/ parallel with/ him"]', '["n-f"]', 'conjunction, i.e. society; mostly adverb or preposition (with prepositional prefix), near, beside, along with (over) against, at, beside, hard by, in points.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6080}/[H6083]', 'inflected', 'heb', 'עָפַר', '["ʻâphar"]', '["and/ he dusted [them]"]', '["v"]', 'to be dust cast (dust).', '; a primitive root; meaning either to be gray or perhaps rather to pulverize; used only as denominative from 6083,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6083}\/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["with <the>/ dust"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5314}/[H5314]', 'inflected', 'heb', 'נָפַשׁ', '["nâphash"]', '["and/ he refreshed himself"]', '["v"]', 'to breathe; passively, to be breathed upon , i.e. (figuratively) refreshed (as if by a current of air) (be) refresh selves (-ed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0302}/[H251]', 'inflected', 'heb', 'אֲחִיתֹפֶל', '["ʼĂchîythôphel"]', '["and/ Ahithophel"]', '["n-pr-m"]', 'Achithophel, an Israelite Ahithophel.', 'from 251 and 8602; brother of folly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8145}/[H8138]', 'inflected', 'heb', 'שֵׁנִי', '["shênîy"]', '["and/ the/ second [thing]"]', '["n"]', 'properly, double, i.e. second; also adverbially, again again, either (of them), (an-) other, second (time).', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440L}/H9021\/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7592}/H9014/{H0376G}/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["he enquires/-/anyone"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3023}/[H3021]', 'lemma', 'heb', 'יָגֵעַ', '["yâgêaʻ"]', '["[are] wearisome","[will be] weary"]', '["a"]', 'tired; hence (transitive) tiresome full of labour, weary.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7504}/[H7503]', 'inflected', 'heb', 'רָפֶה', '["râpheh"]', '["and/ slack of"]', '["a"]', 'slack (in body or mind) weak. raphah, Raphah. See 7497, 7498. riphah. See 7383.', 'from 7503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0376H>', 'inflected', 'heb', 'האיש', '["ha./''Ish"]', '["the/ husband","the/ man"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2365}/[H2363]', 'inflected', 'heb', 'חוּשַׁי', '["Chûwshay"]', '["<to>/ Hushai"]', '["n-pr-m"]', 'Chushai, an Israelite Hushai.', 'from 2363; hasty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6310I}/H9023/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["[is] in/ mouth/ his"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6213A}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["¿/ will we do"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697H}/H9023/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["word/ his"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6098}/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["<the>/ counsel","[is] the/ plan","the/ counsel"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1677}/[H1680]', 'inflected', 'heb', 'דֹּב', '["dôb"]', '["like <the>/ bears","like/ a bear"]', '["n"]', 'the bear (as slow) bear.', 'or (fully) דּוֹב; from 1680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7909}/[H7921]', 'lemma', 'heb', 'שַׁכּוּל', '["shakkûwl"]', '["[was] bereaved","childless","robbed of cubs"]', '["a"]', 'bereaved barren, bereaved (robbed) of children (whelps).', 'or שַׁכֻּל; from 7921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6354>', 'inflected', 'heb', 'הפחתים', '["ha./Pa.chat","ha./pe.cha.Tim"]', '["the/ pit","the/ ravines"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5307J}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["when/ falls"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121K}/[H1129]', 'lemma', 'heb', 'בֵּן', '["bên"]', '["[the] son of","[was] a son of","a son of","sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3820A}/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["[is] like/ [the] heart of","like/ [the] heart of"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121K}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ [are] sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440L}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ face/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7128}/[H7126]', 'inflected', 'heb', 'קְרָב', '["qᵉrâb"]', '["in the/ battle"]', '["n-m"]', 'hostile encounter battle, war.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5498}/[H5498]', 'inflected', 'heb', 'סָחַב', '["çâchab"]', '["and/ we will drag"]', '["v"]', 'to trail along draw (out), tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6872B}\/[H6887]', 'inflected', 'heb', 'צְרוֹר', '["tsᵉrôwr"]', '["a pebble"]', '["n-m"]', 'a parcel (as packed up); also a kernel or particle (as if a package) bag, × bendeth, bundle, least grain, small stone.', 'or (shorter) צְרֹר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6098}/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["more than/ [the] counsel of"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1104}/[H1104]', 'lemma', 'heb', 'בָּלַע', '["bâlaʻ"]', '["I will confuse","I will swallow up","[were] confused","confuse","he has swallowed up","he swallows","he swallows [it]","he will be swallowed up","he will swallow up","it should be swallowed up","it swallows up","it was confused","it will be swallowed","they were confused","we have swallowed up","will you swallow up"]', '["v"]', 'to make away with (specifically by swallowing); generally, to destroy cover, destroy, devour, eat up, be at end, spend up, swallow down (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5883}/[H5869]', 'inflected', 'heb', 'עֵין רֹגֵל', '["ʻÊyn Rôgêl"]', '["at/ En"]', '["n-pr-loc"]', 'En-Rogel, a place near Jerusalem En-rogel.', 'from 5869 and the active participle of 7270; fountain of a traveller;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0980}/[H970]', 'inflected', 'heb', 'בַּחֻרִים', '["Bachurîym"]', '["in/ Bahurim"]', '["n-pr-loc"]', 'Bachurim, a place in Palestine Bahurim.', 'or בַּחוּרִים; masculine plural of 970; young men;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2691A}/H9023/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["in/ courtyard/ his"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7383}/[H7322]', 'inflected', 'heb', 'רִיפָה', '["rîyphâh"]', '["the/ grain<s>","the/ grain[s]"]', '["n-f"]', '(only plural), grits (as pounded) ground corn, wheat.', 'or רִפָה; from 7322;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4323}/[H3201]', 'lemma', 'heb', 'מִיכָל', '["mîykâl"]', '["[the] brook of"]', '["n-m"]', 'properly, a container, i.e. a streamlet brook.', 'from 3201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980G}/H9048/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["had gone/ they"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H0875}/[H874]', 'inflected', 'heb', 'בְּאֵר', '["bᵉʼêr"]', '["from/ the/ well"]', '["n-f"]', 'a pit; especially a well pit, well.', 'from 874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6098}/H9023/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["counsel/ his","own plan[s]/ his"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2614}/[H2596]', 'inflected', 'heb', 'חָנַק', '["chânaq"]', '["and/ he hanged himself"]', '["v"]', 'to be narrow; by implication, to throttle, or (reflex.) to choke oneself to death (by a rope) hang self, strangle.', 'a primitive root (compare 2596);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4266}/H9011/[H4264]', 'inflected', 'heb', 'מַחֲנַיִם', '["Machănayim"]', '["Mahanaim/ <towards>","Mahanaim/ towards"]', '["n-pr-loc"]', 'Machanajim, a place in Palestine Mahanaim.', 'dual of 4264; double camp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6021G}/[H6006]', 'lemma', 'heb', 'עֲמָשָׂא', '["ʻĂmâsâʼ"]', '["Amasa"]', '["n-pr-m"]', 'Amasa, the name of two Israelites Amasa.', 'from 6006; burden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6021G}/[H6006]', 'inflected', 'heb', 'עֲמָשָׂא', '["ʻĂmâsâʼ"]', '["and/ Amasa"]', '["n-pr-m"]', 'Amasa, the name of two Israelites Amasa.', 'from 6006; burden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3501}/[H3502]', 'lemma', 'heb', 'יִתְרָא', '["Yithrâʼ"]', '["[was] Jether"]', '["n-pr-m"]', 'Jithra, an Israelite (or Ishmaelite) Ithra.', 'by variation for 3502;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3481G}/[H3478]', 'inflected', 'heb', 'יִשְׂרְאֵלִי', '["Yisrᵉʼêlîy"]', '["the/ Israelite"]', '["a"]', 'a Jisreelite or descendant of Jisrael of Israel, Israelite.', 'patronymically from 3478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935L}/[H935]', 'lemma', 'heb', 'בּוֹא', '["bôwʼ"]', '["he had gone","they will go","you must go"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0026H}/[H1]', 'lemma', 'heb', 'אֲבִיגַיִל', '["ʼĂbîygayil"]', '["Abigail"]', '["n-pr-f"]', 'Abigail or Abigal, the name of two Israelitesses Abigal.', 'or shorter אֲבִיגַל; from 1 and 1524; father (i.e. source) of joy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5176I}/[H5175]', 'lemma', 'heb', 'נָחָשׁ', '["Nâchâsh"]', '["Nahash"]', '["n-pr-m"]', 'Nachash, the name of two persons apparently non-Israelite Nahash.', 'the same as 5175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1568G}\/[H1567]', 'inflected', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["<the>/ Gilead"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7629}/[H7617]', 'inflected', 'heb', 'שֹׁבִי', '["Shôbîy"]', '["and/ Shobi"]', '["n-pr-m"]', 'Shobi, an Ammonite Shobi.', 'from 7617; captor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5176J}/[H5175]', 'lemma', 'heb', 'נָחָשׁ', '["Nâchâsh"]', '["Nahash"]', '["n-pr-m"]', 'Nachash, the name of two persons apparently non-Israelite Nahash.', 'the same as 5175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7237}/[H7227]', 'inflected', 'heb', 'רַבָּה', '["Rabbâh"]', '["from/ Rabbah of"]', '["n-pr-loc"]', 'Rabbah, the name of two places in Palestine, East and West Rabbah, Rabbath.', 'feminine of 7227; great;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4353H}/[H4376]', 'inflected', 'heb', 'מָכִיר', '["Mâkîyr"]', '["and/ Makir"]', '["n-pr-m"]', 'Makir, an Israelite Machir.', 'from 4376; salesman;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1271G}/[H1270]', 'inflected', 'heb', 'בַּרְזִלַּי', '["Barzillay"]', '["and/ Barzillai"]', '["n-pr-m"]', 'Barzillai, the name of three Israelites Barzillai.', 'from 1270; iron-hearted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7274}/[H7270]', 'inflected', 'heb', 'רֹגְלִים', '["Rôgᵉlîym"]', '["from/ Rogelim"]', '["n-pr-loc"]', 'Rogelim, a place East of the Jordan Rogelim.', 'plural of active participle of 7270; fullers (as tramping the cloth in washing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5592A}/[H5605]', 'inflected', 'heb', 'סַף', '["çaph"]', '["and/ basins"]', '["n-m"]', 'a vestibule (as a limit); also a dish (for holding blood or wine) bason, bowl, cup, door (post), gate, post, threshold.', 'from 5605, in its original sense of containing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3335H}/[H3334]', 'lemma', 'heb', 'יָצַר', '["yâtsar"]', '["a potter","a potter of","potters"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
