INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8194}/[H8192]', 'inflected', 'heb', 'שָׁפָה', '["shâphâh"]', '["and/ cheese of"]', '["n-f"]', 'a cheese (as strained from the whey) cheese.', 'from 8192 in the sense of clarifying;');
