INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7457}/[H7456]', 'lemma', 'heb', 'רָעֵב', '["râʻêb"]', '["[are] hungry","[is] hungry","[the] hungry","hungry","hungry [people]"]', '["a"]', 'hungry (more or less intensely) hunger bitten, hungry.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5889}/[H5888]', 'inflected', 'heb', 'עָיֵף', '["ʻâyêph"]', '["and/ weary"]', '["a"]', 'languid faint, thirsty, weary.', 'from 5888;');
