INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8269}/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["O/ commander","O/ officials","[was] the/ commander","[were] the/ officials","the/ commander","the/ commanders","the/ leader","the/ leaders","the/ official","the/ officials","the/ prince","the/ princes"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
