INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6505}/[H6504]', 'inflected', 'heb', 'פֶּרֶד', '["pered"]', '["the/ mule"]', '["n-m"]', 'a mule (perhaps from his lonely habits) mule.', 'from 6504;');
