INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2290B}/[H2296]', 'inflected', 'heb', 'חֲגוֹר', '["chăgôwr"]', '["and/ a belt"]', '["n-m n-f"]', 'a belt (for the waist) apron, armour, gird(-le).', 'or חֲגֹר; and (feminine) חֲגוֹרָה; or חֲגֹרָה; from 2296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0241H}/H9025/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["in/ ears/ our"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5288}/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["<in> the/ young man","by/ [the] young men of"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0053}/[H1]', 'inflected', 'heb', 'אֲבִישָׁלוֹם', '["ʼĂbîyshâlôwm"]', '["<in>/ Absalom"]', '["n-pr-m"]', 'Abshalom, a son of David; also (the fuller form) a later Israelite Abishalom, Absalom.', 'or (shortened) אַבְשָׁלוֹם ; from 1 and 7965; father of peace (i.e. friendly);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7626I>', 'opaque', 'heb', 'שֵׁבֶט', '["shêbeṭ"]', '["spears"]', '["n-m"]', 'a scion, i.e. (literally) a stick (for punishing, writing, fighting, ruling, walking, etc.) or (figuratively) a clan × correction, dart, rod, sceptre, staff, tribe.', 'from an unused root probably meaning to branch off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8628}/H9038/[H8628]', 'inflected', 'heb', 'תָּקַע', '["tâqaʻ"]', '["and/ he thrust/ them"]', '["v"]', 'to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0168H}/H9023\/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["to/ tents/ his"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6010O}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["[is] in/ [the] valley of"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4678}/[H5324]', 'inflected', 'heb', 'מַצֶּבֶת', '["matstsebeth"]', '["<to> the/ pillar"]', '["n-f"]', 'something stationary, i.e. a monumental stone; also the stock of a tree pillar, substance.', 'from 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1319}/[H1319]', 'inflected', 'heb', 'בָּשַׂר', '["bâsar"]', '["and/ let me bear [the] news to"]', '["v"]', 'properly, to be fresh, i.e. full (rosy, figuratively cheerful); to announce (glad news) messenger, preach, publish, shew forth, (bear, bring, carry, preach, good, tell good) tidings.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8199}/H9033/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["he has vindicated/ him","they will judge/ it"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1319}/[H1319]', 'inflected', 'heb', 'בָּשַׂר', '["bâsar"]', '["and/ you will bear news"]', '["v"]', 'properly, to be fresh, i.e. full (rosy, figuratively cheerful); to announce (glad news) messenger, preach, publish, shew forth, (bear, bring, carry, preach, good, tell good) tidings.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921B}/H9014/{H3651B}/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["since/-/<thus>"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3569G}/[H3568]', 'inflected', 'heb', 'כּוּשִׁי', '["Kûwshîy"]', '["to the/ Cushite"]', '["a"]', 'a Cushite, or descendant of Cush Cushi, Cushite, Ethiopian(-s).', 'patronymically from 3568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7778}/[H8176]', 'inflected', 'heb', 'שׁוֹעֵר', '["shôwʻêr"]', '["[were] the/ gatekeepers","the/ gatekeeper","the/ gatekeepers"]', '["n-m"]', 'a janitor doorkeeper, porter.', 'or שֹׁעֵר active participle of 8176 (as denominative from 8179);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4794}/[H4793]', 'lemma', 'heb', 'מְרוּצָה', '["mᵉrûwtsâh"]', '["[the] running of"]', '["n-f"]', 'a race (the act), whether the manner or the progress course, running. Compare 4835.', 'or מְרֻצָה; feminine of 4793;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4794}/[H4793]', 'inflected', 'heb', 'מְרוּצָה', '["mᵉrûwtsâh"]', '["like/ [the] running of"]', '["n-f"]', 'a race (the act), whether the manner or the progress course, running. Compare 4835.', 'or מְרֻצָה; feminine of 4793;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776H>/H9011\', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["[the] ground/ towards"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8199}/H9031/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["I will judge/ you","he has vindicated/ you"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5288}/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["like the/ young man"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7451I}\/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["for/ harm"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5944}/[H5927]', 'lemma', 'heb', 'עֲלִיָּה', '["ʻălîyâh"]', '["[the] roof-chamber of","[the] upper room of","an upper room of"]', '["n-f"]', 'something lofty, i.e. a stair-way; also a second-story room (or even one on the roof); figuratively, the sky ascent, (upper) chamber, going up, loft, parlour.', 'feminine from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9040/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["died/ I"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478H}/H9031/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["in place of/ you"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0060}/[H56]', 'inflected', 'heb', 'אֵבֶל', '["ʼêbel"]', '["<into>/ mourning","into/ mourning"]', '["n-m"]', 'lamentation mourning.', 'from 56;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3637}/[H3637]', 'inflected', 'heb', 'כָּלַם', '["kâlam"]', '["who/ are ashamed","who/ were ashamed"]', '["v"]', 'properly, to wound; but only figuratively, to taunt or insult be (make) ashamed, blush, be confounded, be put to confusion, hurt, reproach, (do, put to) shame.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3813}/[H3813]', 'lemma', 'heb', 'לָאַט', '["lâʼaṭ"]', '["he covered"]', '["v"]', 'to muffle cover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121A}/H9020\/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["son/ my"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4422}/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["the/ [one who] escapes","who/ rescued"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6370>/H9021', 'opaque', 'heb', 'פִּילֶגֶשׁ', '["pîylegesh"]', '["concubines/ your"]', '["n-f"]', 'a concubine; also (masculine) a paramour concubine, paramour.', 'or פִּלֶגֶשׁ; of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8130}/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["and/ <to>/ [those who] hate","and/ by/ hating"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3605}/H9025/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["and/ all of/ us"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5271A}/H9021/[H5288]', 'inflected', 'heb', 'נָעוּר', '["nâʻûwr"]', '["since/ youth<s>/ your"]', '["n-m n-f"]', '(only in plural collective or emphatic form) youth, the state (juvenility) or the persons (young people) childhood, youth.', 'or נָעֻר; and (feminine) נְעֻרָה; properly, passive participle from 5288 as denominative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6258}\/[H6256]', 'inflected', 'heb', 'עַתָּה', '["ʻattâh"]', '["now"]', '["adv"]', 'at this time, whether adverb, conjunction or expletive henceforth, now, straightway, this time, whereas.', 'from 6256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4422}/H9035/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["he rescued/ us"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6021G}/[H6006]', 'inflected', 'heb', 'עֲמָשָׂא', '["ʻĂmâsâʼ"]', '["and/ to/ Amasa"]', '["n-pr-m"]', 'Amasa, the name of two Israelites Amasa.', 'from 6006; burden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0980}/[H970]', 'inflected', 'heb', 'בַּחֻרִים', '["Bachurîym"]', '["[was] from/ Bahurim","from/ Bahurim"]', '["n-pr-loc"]', 'Bachurim, a place in Palestine Bahurim.', 'or בַּחוּרִים; masculine plural of 970; young men;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6717}/[H6678]', 'inflected', 'heb', 'צִיבָא', '["Tsîybâʼ"]', '["and/ Ziba"]', '["n-pr-m"]', 'Tsiba, an Israelite Ziba.', 'from the same as 6678; station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5679}/[H5674]', 'inflected', 'heb', 'עֲבָרָה', '["ʻăbârâh"]', '["the/ ford"]', '["n-f"]', 'a crossing-place ferry, plain (from the margin).', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7760K}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["to/ put [it]"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H8478J}/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["¿/ in place of"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8222}/H9023/[H8193]', 'inflected', 'heb', 'שָׂפָם', '["sâphâm"]', '["moustache/ his"]', '["n-m"]', 'the beard (as a lip-piece) beard, (upper) lip.', 'from 8193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7392}/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["and/ [the] rider of","and/ riding","so/ I may ride"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7979}/H9021/[H7971]', 'inflected', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["<of> table/ your","table/ your"]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2199}/[H2199]', 'inflected', 'heb', 'זָעַק', '["zâʻaq"]', '["and/ to/ cry out"]', '["v"]', 'to shriek (from anguish or danger); by analogy, (as a herald) to announce or convene publicly assemble, call (together), (make a) cry (out), come with such a company, gather (together), cause to be proclaimed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9023\/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["house/ his","own house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7971G}/H9033/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["to/ [those who] send/ him","to/ [those who] sent/ him","to/ send off/ him"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7871}/H9023/[H3427]', 'inflected', 'heb', 'שִׁיבָה', '["shîybâh"]', '["in/ dwelling/ his"]', '["n-f"]', 'residence while...lay.', 'from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4266}/[H4264]', 'inflected', 'heb', 'מַחֲנַיִם', '["Machănayim"]', '["in/ Mahanaim"]', '["n-pr-loc"]', 'Machanajim, a place in Palestine Mahanaim.', 'dual of 4264; double camp;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1271G}/[H1270]', 'lemma', 'heb', 'בַּרְזִלַּי', '["Barzillay"]', '["Barzillai"]', '["n-pr-m"]', 'Barzillai, the name of three Israelites Barzillai.', 'from 1270; iron-hearted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7891}/[H7788]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["and/ [one who] sings","and/ female singers","and/ singers","so/ they may sing"]', '["v"]', 'to sing behold (by mistake for 7789), sing(-er, -ing man, -ing woman).', 'or (the original form) שׁוּר; (1 Samuel 18:6), a primitive root (rather identical with 7788 through the idea of strolling minstrelsy);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1578}/[H1576]', 'inflected', 'heb', 'גְּמוּלָה', '["gᵉmûwlâh"]', '["the/ reward"]', '["n-f"]', 'meaning the same deed, recompense, such a reward.', 'feminine of 1576;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5892B}/H9020/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["in/ own city/ my"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3643}/[H3642]', 'lemma', 'heb', 'כִּמְהָם', '["Kimhâm"]', '["Kimham"]', '["n-pr-m n-pr-loc"]', 'Kimham, an Israelite Chimham.', 'from 3642; pining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869I}/H9021\/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1271G}/[H1270]', 'inflected', 'heb', 'בַּרְזִלַּי', '["Barzillay"]', '["<to>/ Barzillai"]', '["n-pr-m"]', 'Barzillai, the name of three Israelites Barzillai.', 'from 1270; iron-hearted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3643}/[H3642]', 'inflected', 'heb', 'כִּמְהָם', '["Kimhâm"]', '["and/ Kimhan"]', '["n-pr-m n-pr-loc"]', 'Kimham, an Israelite Chimham.', 'from 3642; pining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1589}/H9031/[H1589]', 'inflected', 'heb', 'גָּנַב', '["gânab"]', '["did they steal/ you"]', '["v"]', 'to thieve (literally or figuratively); by implication, to deceive carry away, × indeed, secretly bring, steal (away), get by stealth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0398}/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["¿/ do I eat","¿/ is it eaten","¿/ really <to eat>"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5379}/[H5375]', 'lemma', 'heb', 'נִשֵּׂאת', '["nissêʼth"]', '["really <be taken away>"]', '["n-f"]', 'something taken, i.e. a present gift.', 'passive participle feminine of 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375X}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["has it been taken away"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H9035}\', 'inflected', 'heb', 'לנו ס', '["La./nu"]', '["by <the>/ us","for/ us"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7043}/H9030/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["did you treat with contempt/ me","he cursed/ me"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4428G}/H9020/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["O king/ my","[are] king/ my","[has been] king/ my","king/ my"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7652A}/[H7651]', 'lemma', 'heb', 'שֶׁבַע', '["shebaʻ"]', '["Sheba","[was] Sheba","[who is] Sheba"]', '["n-pr-m n-pr-loc"]', 'Sheba, the name of a place in Palestine, and of two Israelites Sheba.', 'the same as 7651; seven;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1075}/[H1069]', 'lemma', 'heb', 'בִּכְרִי', '["Bikrîy"]', '["Bicri"]', '["n-pr-m a"]', 'Bikri, an Israelite Bichri.', 'from 1069; youth-ful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3228G}/[H3226]', 'lemma', 'heb', 'יְמִינִי', '["Yᵉmîynîy"]', '["a Jaminite"]', '["a"]', 'a Jeminite (collectively) or descendants of Jamin Jaminites. See also 1145.', 'patronymically from 3226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1121A}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["among the/ sons","among/ [the] people of","among/ [the] sons of","in/ [the] son of","in/ a child of","on/ [the] child of","over/ a son"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4428G}/H9028/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["in/ king/ their","to/ king/ their"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3557}/H9038/[H3557]', 'inflected', 'heb', 'כּוּל', '["kûwl"]', '["and/ I supplied/ them","and/ he supplied/ them","and/ he sustained/ them"]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9049/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["died/ they"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0491}/[H488]', 'lemma', 'heb', 'אַלְמָנוּת', '["ʼalmânûwth"]', '["widowhood of"]', '["n-f"]', 'concrete, a widow; abstract, widowhood widow, widowhood.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2424}\/[H2421]', 'inflected', 'heb', 'חַיּוּת', '["chayûwth"]', '["living"]', '["n-f"]', 'life × living.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2199}/[H2199]', 'inflected', 'heb', 'זָעַק', '["zâʻaq"]', '["to/ summon"]', '["v"]', 'to shriek (from anguish or danger); by analogy, (as a herald) to announce or convene publicly assemble, call (together), (make a) cry (out), come with such a company, gather (together), cause to be proclaimed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4150G}/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["the/ appointed time"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3259}/H9033\/[H3259]', 'inflected', 'heb', 'יָעַד', '["yâʻad"]', '["he had appointed for/ him"]', '["v"]', 'to fix upon (by agreement or appointment); by implication, to meet (at a stated time), to summon (to trial), to direct (in a certain quarter or position), to engage (for marriage) agree,(maxke an) appoint(-ment, a time), assemble (selves), betroth, gather (selves, together), meet (together), set (a time).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869J}/H9025/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eye/ our"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2290A}/[H2296]', 'lemma', 'heb', 'חֲגוֹר', '["chăgôwr"]', '["a belt of"]', '["n-m n-f"]', 'a belt (for the waist) apron, armour, gird(-le).', 'or חֲגֹר; and (feminine) חֲגוֹרָה; or חֲגֹרָה; from 2296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6775}/[H6775]', 'lemma', 'heb', 'צָמַד', '["tsâmad"]', '["[was] fastened","it harnesses"]', '["v"]', 'to link, i.e. gird; figuratively, to serve, (mentally) contrive fasten, frame, join (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4975>/H9023', 'opaque', 'heb', 'מֹתֶן', '["môthen"]', '["hips/ his","loins/ his"]', '["n-m"]', 'properly, the waist or small of the back; only in plural the loins greyhound, loins, side.', 'from an unused root meaning to be slender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8593}/H9024/[H6168]', 'inflected', 'heb', 'תַּעַר', '["taʻar"]', '["in/ sheath/ its"]', '["n"]', 'a knife or razor (as making bare); also a scabbard (as being bare, i.e. empty) (pen-) knife, razor, scabbard, shave, sheath.', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5307G}\/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ it fell"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6021G}/[H6006]', 'inflected', 'heb', 'עֲמָשָׂא', '["ʻĂmâsâʼ"]', '["to/ Amasa"]', '["n-pr-m"]', 'Amasa, the name of two Israelites Amasa.', 'from 6006; burden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104I}/[H8104]', 'lemma', 'heb', 'שָׁמַר', '["shâmar"]', '["I will watch","[are] [the] watchers of","[is] watching","[one who] watches for","[those who] pay regard","do you watch?","he took heed","he watches","it watches for","they watch for","they will guard","watch","will he keep","you keep [them]","you will keep","you will watch"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4578>/H9023', 'opaque', 'heb', 'מֵעֶה', '["mêʻeh"]', '["bowels/ his","lower parts/ his"]', '["n-m"]', 'used only in plural the intestines, or (collectively) the abdomen, figuratively, sympathy; by implication, a vest; by extension the stomach, the uterus (or of men, the seat of generation), the heart (figuratively) belly, bowels, × heart, womb.', 'from an unused root probably meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3097G}/[H3068]', 'inflected', 'heb', 'יוֹאָב', '["Yôwʼâb"]', '["in/ Joab"]', '["n-pr-m"]', 'Joab, the name of three Israelites Joab.', 'from 3068 and 1; Jehovah-fathered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3014}/[H3013]', 'lemma', 'heb', 'יָגָה', '["yâgâh"]', '["he had removed [him]"]', '["v"]', 'to push away be removed.', 'a primitive root (probably rather the same as 3013 through the common idea of dissatisfaction);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0062}+/H9011/[H58]', 'inflected', 'heb', 'אָבֵל בֵּית־מֲעַכָה', '["ʼÂbêl Bêyth-Măʻakâh"]', '["Abel/ towards"]', '["n-pr-loc"]', 'Abel of Beth-maakah, a place in Palestine Abel-beth-maachah, Abel of Beth-maachah,', 'from 58 and 1004 and 4601; meadow of Beth-Maakah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0062}/[H58]', 'inflected', 'heb', 'אָבֵל בֵּית־מֲעַכָה', '["ʼÂbêl Bêyth-Măʻakâh"]', '["and/ Beth"]', '["n-pr-loc"]', 'Abel of Beth-maakah, a place in Palestine Abel-beth-maachah, Abel of Beth-maachah,', 'from 58 and 1004 and 4601; meadow of Beth-Maakah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0062}/[H58]', 'lemma', 'heb', 'אָבֵל בֵּית־מֲעַכָה', '["ʼÂbêl Bêyth-Măʻakâh"]', '["Abel","Beth","Maacah"]', '["n-pr-loc"]', 'Abel of Beth-maakah, a place in Palestine Abel-beth-maachah, Abel of Beth-maachah,', 'from 58 and 1004 and 4601; meadow of Beth-Maakah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1276>\', 'inflected', 'heb', 'הברים ס', '["ha./be.Rim"]', '["the/ Berites"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0062}+/H9011/[H58]', 'inflected', 'heb', 'אָבֵל בֵּית־מֲעַכָה', '["ʼÂbêl Bêyth-Măʻakâh"]', '["in/ Abel/ <towards>"]', '["n-pr-loc"]', 'Abel of Beth-maakah, a place in Palestine Abel-beth-maachah, Abel of Beth-maachah,', 'from 58 and 1004 and 4601; meadow of Beth-Maakah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0062}/[H58]', 'inflected', 'heb', 'אָבֵל בֵּית־מֲעַכָה', '["ʼÂbêl Bêyth-Măʻakâh"]', '["<the>/ Maacah"]', '["n-pr-loc"]', 'Abel of Beth-maakah, a place in Palestine Abel-beth-maachah, Abel of Beth-maachah,', 'from 58 and 1004 and 4601; meadow of Beth-Maakah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8210I}/[H8210]', 'inflected', 'heb', 'שָׁפַךְ', '["shâphak"]', '["and/ they poured out","and/ you will pour out"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5550}/[H5549]', 'lemma', 'heb', 'סֹלְלָה', '["çôlᵉlâh"]', '["a mound"]', '["n-f"]', 'a military mound, i.e. rampart of besiegers bank, mount.', 'or סוֹלְלָה; active participle feminine of 5549, but used passively;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2426}/[H2428]', 'inflected', 'heb', 'חֵיל', '["chêyl"]', '["by the/ rampart","in/ [the] rampart of"]', '["n-m"]', 'an army; also (by analogy,) an intrenchment army, bulwark, host, poor, rampart, trench, wall.', 'or (shortened) חֵל; a collateral form of 2428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5307G}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["to/ fall","to/ make fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0059H}/[H58]', 'inflected', 'heb', 'אָבֵל', '["ʼÂbêl"]', '["at/ Abel"]', '["n-pr-loc"]', 'Abel, the name of two places in Palestine. Abel.', 'from 58; a meadow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0517}/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["and/ a mother","and/ mother"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375R}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["he has lifted up","it will lift up","they will lift up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2451}/H9024/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["with/ wisdom/ her"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0151}/[H141]', 'inflected', 'heb', 'אֲדֹרָם', '["ʼĂdôrâm"]', '["and/ Adoram"]', '["n-pr-m"]', 'Adoram (or Adoniram), an Israelite Adoram.', 'contracted for 141;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4522}/[H4549]', 'inflected', 'heb', 'מַס', '["maç"]', '["the/ forced labor"]', '["n-m"]', 'properly, a burden (as causing to faint), i.e. a tax in the form of forced labor discomfited, levy, task(-master), tribute(-tary).', 'or מִס; from 4549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2142}/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["O those/ [who] cause to remember","[was] the/ recorder","the/ recorder"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7724H}/[H7723]', 'inflected', 'heb', 'שְׁוָא', '["Shᵉvâʼ"]', '["and/ Sheva"]', '["n-pr-m"]', 'Sheva, an Israelite Sheva.', 'from the same as 7723; false;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5896G}/[H5782]', 'lemma', 'heb', 'עִירָא', '["ʻÎyrâʼ"]', '["Ira"]', '["n-pr-m"]', 'Ira, the name of three Israelites Ira.', 'from 5782; wakefulness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2972}/[H2971]', 'inflected', 'heb', 'יָאִרִי', '["Yâʼirîy"]', '["the/ Jairite"]', '["n-m"]', 'a Jairite or descendant of Jair Jairite.', 'patronymically from 2971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1393}/[H1391]', 'inflected', 'heb', 'גִּבְעֹנִי', '["Gibʻônîy"]', '["the/ Gibeonite","the/ Gibeonites"]', '["a"]', 'a Gibonite, or inhabitant of Gibon Gibeonite.', 'patrial from 1391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1393}/[H1391]', 'inflected', 'heb', 'גִּבְעֹנִי', '["Gibʻônîy"]', '["<to> the/ Gibeonites"]', '["a"]', 'a Gibonite, or inhabitant of Gibon Gibeonite.', 'patrial from 1391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1393}/[H1391]', 'inflected', 'heb', 'גִּבְעֹנִי', '["Gibʻônîy"]', '["and/ the/ Gibeonites"]', '["a"]', 'a Gibonite, or inhabitant of Gibon Gibeonite.', 'patrial from 1391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615H}/H9035/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["he made an end of/ us"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3320}/[H3320]', 'inflected', 'heb', 'יָצַב', '["yâtsab"]', '["from/ standing","from/ when presented themselves"]', '["v"]', 'to place (any thing so as to stay); reflexively, to station, offer, continue present selves, remaining, resort, set (selves), (be able to, can, with-) stand (fast, forth, -ing, still, up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1121G}/H9023/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["from/ descendants/ his"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3363}/H9038/[H3363]', 'inflected', 'heb', 'יָקַע', '["yâqaʻ"]', '["and/ they impaled/ them","and/ we will impale/ them"]', '["v"]', 'properly, to sever oneself, i.e. (by implication) to be dislocated; figuratively, to abandon; causatively, to impale (and thus allow to drop to pieces by rotting) be alienated, depart, hang (up), be out of joint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0972}/[H977]', 'lemma', 'heb', 'בָּחִיר', '["bâchîyr"]', '["[the] chosen one of"]', '["n-m"]', 'select choose, chosen one, elect.', 'from 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0764}/[H759]', 'lemma', 'heb', 'אַרְמֹנִי', '["ʼArmônîy"]', '["Armoni"]', '["n-pr-m"]', 'Armoni, an Israelite Armoni.', 'from 759; palatial;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4648H}/[H6284]', 'lemma', 'heb', 'מְפִיבֹשֶׁת', '["Mᵉphîybôsheth"]', '["Mephibosheth"]', '["n-pr-m"]', 'Mephibosheth, the name of two Israelites Mephibosheth.', 'or מְפִבֹשֶׁת; probably from 6284 and 1322; dispeller of shame (i.e. of Baal);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4324H}/[H4323]', 'lemma', 'heb', 'מִיכָל', '["Mîykâl"]', '["Michal"]', '["n-pr-f"]', 'Mikal, Saul''s daughter Michal.', 'apparently the same as 4323; revulet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1271H}/[H1270]', 'lemma', 'heb', 'בַּרְזִלַּי', '["Barzillay"]', '["Barzillai"]', '["n-pr-m"]', 'Barzillai, the name of three Israelites Barzillai.', 'from 1270; iron-hearted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7651}/H9028/[H7650]', 'inflected', 'heb', 'שֶׁבַע', '["shebaʻ"]', '["[the] seven of/ them"]', '["n"]', 'seven (as the sacred full one); also (adverbially) seven times; by implication, a week; by extension, an indefinite number ( by) seven(-fold),-s, (-teen, -teenth), -th, times). Compare 7658.', 'or (masculine) (שִׁבְעָה); from 7650; a primitive cardinal number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8242}/[H8264]', 'inflected', 'heb', 'שַׂק', '["saq"]', '["<the>/ sackcloth","the/ sackcloth"]', '["n-m"]', 'properly, a mesh (as allowing a liquid to run through), i.e. coarse loose cloth or sacking (used in mourning and for bagging); hence, a bag (for grain, etc.) sack(-cloth, -clothes).', 'from 8264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8462}/[H2490]', 'inflected', 'heb', 'תְּחִלָּה', '["tᵉchillâh"]', '["from/ [the] beginning of"]', '["n-f"]', 'a commencement; relatively original (adverb, -ly) begin(-ning), first (time).', 'from 2490 in the sense of opening;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5117}/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["[was] to the/ free space","to/ cause to rest","to/ rest"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7339}/[H7337]', 'inflected', 'heb', 'רְחֹב', '["rᵉchôb"]', '["from/ [the] open places","from/ [the] open square of"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8511}/H9038/[H8511]', 'inflected', 'heb', 'תָּלָא', '["tâlâʼ"]', '["they had hung up/ them"]', '["v"]', 'to suspend; figuratively (through hesitation) to be uncertain; by implication (of mental dependence) to habituate be bent, hang (in doubt).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3363}/[H3363]', 'inflected', 'heb', 'יָקַע', '["yâqaʻ"]', '["the/ impaled [men]"]', '["v"]', 'properly, to sever oneself, i.e. (by implication) to be dislocated; figuratively, to abandon; causatively, to impale (and thus allow to drop to pieces by rotting) be alienated, depart, hang (up), be out of joint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6762}/[H6761]', 'inflected', 'heb', 'צֶלַע', '["Tselaʻ"]', '["at/ Zela"]', '["n-pr-loc"]', 'Tsela, a place in Palestine Zelah.', 'the same as 6761;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3430}/[H3427]', 'inflected', 'heb', 'יִשְׁבּוֹ בְּנֹב', '["Yishbôw bᵉ-Nôb"]', '["and/ Ishbi-"]', '["n-pr-m"]', 'Jishbo-be-Nob, a Philistine Ishbi-benob (from the margin).', 'from 3427 and 5011, with a pronominal suffix and a preposition interposed; his dwelling (is) in Nob;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3430}/[H3427]', 'lemma', 'heb', 'יִשְׁבּוֹ בְּנֹב', '["Yishbôw bᵉ-Nôb"]', '["Benob"]', '["n-pr-m"]', 'Jishbo-be-Nob, a Philistine Ishbi-benob (from the margin).', 'from 3427 and 5011, with a pronominal suffix and a preposition interposed; his dwelling (is) in Nob;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3211}/[H3205]', 'inflected', 'heb', 'יָלִיד', '["yâlîyd"]', '["[was] among/ those born of"]', '["a"]', 'born (home-) born, child, son.', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7497A}/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["the/ Raphah"]', '["n-pr-m"]', 'a giant giant, Rapha, Rephaim(-s). See also 1051.', 'or רָפָה; from 7495 in the sense of invigorating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7013}/H9023/[H6969]', 'inflected', 'heb', 'קַיִן', '["qayin"]', '["spear/ his"]', '["n-m"]', 'a lance (as striking fast) spear.', 'from 6969 in the original sense of fixity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1359}/[H1461]', 'inflected', 'heb', 'גֹּב', '["Gôb"]', '["at/ Gob"]', '["n-pr-loc"]', 'Gob, a place in Palestine Gob.', 'or (fully) גּוֹב; from 1461; pit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5444}/[H5440]', 'lemma', 'heb', 'סִבְּכַי', '["Çibbᵉkay"]', '["Sibbecai"]', '["n-pr-m"]', 'Sibbecai, an Israelite Sibbecai, Sibbechai.', 'from 5440; copse-like;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2843}/[H2364]', 'inflected', 'heb', 'חֻשָׁתִי', '["Chushâthîy"]', '["the/ Hushathite"]', '["n-m"]', 'a Chushathite or descendant of Chushah Hushathite.', 'patronymically from 2364;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5593}/[H5592]', 'lemma', 'heb', 'סַף', '["Çaph"]', '["Saph"]', '["n-pr-m"]', 'Saph, a Philistine Saph. Compare 5598.', 'the same as 5592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7497A}\/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["the/ Raphah"]', '["n-pr-m"]', 'a giant giant, Rapha, Rephaim(-s). See also 1051.', 'or רָפָה; from 7495 in the sense of invigorating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0445G}/[H410]', 'lemma', 'heb', 'אֶלְחָנָן', '["ʼElchânân"]', '["Elhanan"]', '["n-pr-m"]', 'Elchanan, an Israelite Elkanan.', 'from 410 and 2603; God (is) gracious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3296}/[H3293]', 'lemma', 'heb', 'יַעֲרֵי אֹרְגִים', '["Yaʻărêy ʼÔrᵉgîym"]', '["Jaare-","Oregim"]', '["n-pr-m"]', 'Jaare-Oregim, an Israelite Jaare-oregim.', 'from the plural of 3293 and the masculine plural active participle of 707; woods of weavers;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6086J}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["and/ [the] wood of"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0707}\/[H707]', 'inflected', 'heb', 'אָרַג', '["ʼârag"]', '["weavers"]', '["v"]', 'to plait or weave weaver(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4067}/[H4063]', 'lemma', 'heb', 'מָדוֹן', '["mâdôwn"]', '["stature"]', '["n-m"]', 'extensiveness, i.e. height stature.', 'from the same as 4063;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0676}/[H6648]', 'inflected', 'heb', 'אֶצְבַּע', '["ʼetsbaʻ"]', '["and/ [the] fingers of","and/ [the] toes of"]', '["n-f"]', 'something to sieze with, i.e. a finger; by analogy, a toe finger, toe.', 'from the same as 6648 (in the sense of grasping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9009/{H7497A}/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["to/ <the>/ Rapha","to/ the/ Raphah"]', '["n-pr-m"]', 'a giant giant, Rapha, Rephaim(-s). See also 1051.', 'or רָפָה; from 7495 in the sense of invigorating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2778A}/[H2779]', 'inflected', 'heb', 'חָרַף', '["châraph"]', '["and/ he taunted"]', '["v"]', 'to pull off, i.e. (by implication) to expose (as by stripping); specifically, to betroth (as if a surrender); figuratively, to carp at, i.e. defame; to spend the winter betroth, blaspheme, defy, jeopard, rail, reproach, upbraid.', 'a primitive root; also denominative (from 2779)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3083O}/[H3068]', 'lemma', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3709G}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["and/ from/ [the] hand of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5553H>/H9020', 'opaque', 'heb', 'סֶלַע', '["çelaʻ"]', '["[are] rock/ my","[is] rock/ my","rock/ my"]', '["n-m"]', 'a craggy rock, literally or figuratively (a fortress) (ragged) rock, stone(-ny), strong hold.', 'from an unused root meaning to be lofty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4686B}/H9020/[H4685]', 'inflected', 'heb', 'מָצוּד', '["mâtsûwd"]', '["and/ stronghold/ my"]', '["n-f"]', 'a net, or (abstractly) capture; also a fastness castle, defense, fort(-ress), (strong) hold, be hunted, net, snare, strong place.', 'or (feminine) מְצוּדָה; or מְצֻדָה; for 4685;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6403}/H9030/[H6403]', 'inflected', 'heb', 'פָּלַט', '["pâlaṭ"]', '["and/ deliverer/ my","and/ you will deliver/ me"]', '["v"]', 'to slip out, i.e. escape; causatively, to deliver calve, carry away safe, deliver, (cause to) escape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6697H}/H9020/[H6696]', 'inflected', 'heb', 'צוּר', '["tsûwr"]', '["O rock/ my","[is] rock/ my","rock/ my"]', '["n-m"]', 'properly, a cliff (or sharp rock, as compressed); generally, a rock or boulder; figuratively, a refuge; also an edge (as precipitous) edge, × (mighty) God (one), rock, × sharp, stone, × strength, × strong. See also 1049.', 'or צֻר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4043}/H9020/[H1598]', 'inflected', 'heb', 'מָגֵן', '["mâgên"]', '["shield/ my"]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3468}/H9020/[H3467]', 'inflected', 'heb', 'יֶשַׁע', '["yeshaʻ"]', '["salvation/ my"]', '["n-m"]', 'liberty, deliverance, prosperity safety, salvation, saving.', 'or יֵשַׁע; from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4869A}/H9020/[H7682]', 'inflected', 'heb', 'מִשְׂגָּב', '["misgâb"]', '["[is] refuge/ my","refuge/ my"]', '["n-m n-pr-loc"]', 'properly, a cliff (or other lofty or inaccessible place); abstractly, altitude; figuratively, a refuge; Misgab, a place in Moab defence, high fort (tower), refuge, Misgab.', 'from 7682;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4498}/H9020/[H5127]', 'inflected', 'heb', 'מָנוֹס', '["mânôwç"]', '["and/ place of escape/ my"]', '["n-m"]', 'a retreat (literally or figuratively); abstractly, a fleeing × apace, escape, way to flee, flight, refuge.', 'from 5127;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3467}/H9030/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["O deliverer/ my","he will save/ me","it saves/ me","save/ me","you deliver/ me"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2555}/[H2554]', 'inflected', 'heb', 'חָמָס', '["châmâç"]', '["from/ [the] violence of","from/ violence"]', '["n-m"]', 'violence; by implication, wrong; by metonymy unjust gain cruel(-ty), damage, false, injustice, × oppressor, unrighteous, violence (against, done), violent (dealing), wrong.', 'from 2554;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1984B}/[H1984]', 'lemma', 'heb', 'הָלַל', '["hâlal"]', '["I will praise","[is] to be praised","[the one] to be praised","[those] praising","he is praised","it will praise","it will praise [you]","let it praise","let them praise","may they praise","praise","she will be praised","they praise","they were praised","they will praise"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0341}/H9020/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["and/ from/ enemies/ my"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0661}/H9030/[H661]', 'inflected', 'heb', 'אָפַף', '["ʼâphaph"]', '["they encompassed/ me","they have encompassed/ me","they surrounded/ me"]', '["v"]', 'to surround compass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4867}/[H7665]', 'lemma', 'heb', 'מִשְׁבָּר', '["mishbâr"]', '["[the] breakers of"]', '["n-m"]', 'a breaker (of the sea) billow, wave.', 'from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1100H}/[H1097]', 'lemma', 'heb', 'בְּלִיַּעַל', '["bᵉlîyaʻal"]', '["worthlessness"]', '["n-m"]', 'without profit, worthlessness; by extension, destruction, wickedness Belial, evil, naughty, ungodly (men), wicked.', 'from 1097 and 3276;(often in connection with 376, 802, 1121, etc.)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1204}/H9030/[H1204]', 'inflected', 'heb', 'בָּעַת', '["bâʻath"]', '["it has overwhelmed/ me","it terrify/ me","they overwhelmed/ me","you will terrify/ me"]', '["v"]', 'to fear affright, be (make) afraid, terrify, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5437H}/H9030/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["it surrounds/ me","they have surrounded/ me","they surrounded/ me","you will surround/ me"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6923}/H9030/[H6923]', 'inflected', 'heb', 'קָדַם', '["qâdam"]', '["did they receive/ me","has he confronted/ me","he will meet/ me","they confronted/ me","they have confronted/ me"]', '["v"]', 'to project (one self), i.e. precede; hence, to anticipate, hasten, meet (usually for help) come (go, (flee)) before, disappoint, meet, prevent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1964G}/H9023/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["from/ temple/ his"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7775}/H9020/[H7773]', 'inflected', 'heb', 'שַׁוְעָה', '["shavʻâh"]', '["and/ cry for help/ my"]', '["n-f"]', 'a hallooing crying.', 'feminine of 7773;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1607}/[H1607]', 'inflected', 'heb', 'גָּעַשׁ', '["gâʻash"]', '["and/ it shook","and/ it shook back and forth","and/ they shook back and forth","and/ they will stagger to and fro"]', '["v"]', 'to agitate violently move, shake, toss, trouble.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7493}/[H7493]', 'inflected', 'heb', 'רָעַשׁ', '["râʻash"]', '["and/ I will shake","and/ it quaked","and/ it shook","and/ they have shaken","and/ they will shake"]', '["v"]', 'to undulate (as the earth, the sky, etc.; also a field of grain), particularly through fear; specifically, to spring (as a locust) make afraid, (re-) move, quake, (make to) shake, (make to) tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4146}/[H4144]', 'lemma', 'heb', 'מוֹסָדָה', '["môwçâdâh"]', '["[the] foundations of"]', '["n-f"]', 'a foundation foundation.', 'or מֹסָדָה; feminine of 4144;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5774A}/[H5775]', 'inflected', 'heb', 'עוּף', '["ʻûwph"]', '["and/ he flew","and/ they will fly"]', '["v n-f"]', 'to fly; also (by implication of dimness) to faint (from the darkness of swooning) brandish, be (wax) faint, flee away, fly (away), × set, shine forth, weary.', 'a primitive root; to cover (with wings or obscurity); hence (as denominative from 5775)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2841}/[H2840]', 'lemma', 'heb', 'חַשְׁרָה', '["chashrâh"]', '["a sieve of"]', '["n-f"]', 'properly, a combination or gathering, i.e. of watery clouds dark.', 'from the same as 2840;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5051}/[H5050]', 'inflected', 'heb', 'נֹגַהּ', '["nôgahh"]', '["from/ [the] brightness","from/ brightness"]', '["n-f"]', 'brilliancy (literally or figuratively) bright(-ness), light, (clear) shining.', 'from 5050;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5945B}/[H5927]', 'inflected', 'heb', 'עֶלְיוֹן', '["ʻelyôwn"]', '["and/ [the] Most High"]', '["n-m a"]', 'an elevation, i.e. (adj.) lofty (compar.); as title, the Supreme (Most, on) high(-er, -est), upper(-most).', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6327A}/H9038/[H6327]', 'inflected', 'heb', 'פּוּץ', '["pûwts"]', '["and/ I will scatter/ them","and/ he scattered/ them"]', '["v"]', 'to dash in pieces, literally or figuratively (especially to disperse) break (dash, shake) in (to) pieces, cast (abroad), disperse (selves), drive, retire, scatter (abroad), spread abroad.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0650}/[H622]', 'lemma', 'heb', 'אָפִיק', '["ʼâphîyq"]', '["[are] tubes of","[is] rows of","[the] channels of","[the] ravines of","channels of","strong people"]', '["n-m"]', 'properly, containing, i.e. a tube; also a bed or valley of a stream; also a strong thing or a hero brook, channel, mighty, river, scale, stream, strong piece.', 'from 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1606}/[H1605]', 'inflected', 'heb', 'גְּעָרָה', '["gᵉʻârâh"]', '["at/ [the] rebuke of"]', '["n-f"]', 'a chiding rebuke(-ing), reproof.', 'from 1605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5397}/[H5395]', 'inflected', 'heb', 'נְשָׁמָה', '["nᵉshâmâh"]', '["from/ [the] breath of","from/ [the] breathing of"]', '["n-f"]', 'a puff, i.e. wind, angry or vital breath, divine inspiration, intellect. or (concretely) an animal blast, (that) breath(-eth), inspiration, soul, spirit.', 'from 5395;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0639H}/H9023/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["nose/ his"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4791}/[H7311]', 'inflected', 'heb', 'מָרוֹם', '["mârôwm"]', '["from/ [the] height of","from/ a high place","from/ high places"]', '["n-m"]', 'altitude, i.e. concretely (an elevated place), abstractly (elevation, figuratively (elation), or adverbially (aloft) (far) above, dignity, haughty, height, (most, on) high (one, place), loftily, upward.', 'from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4871}/H9030/[H4871]', 'inflected', 'heb', 'מָשָׁה', '["mâshâh"]', '["he drew/ me"]', '["v"]', 'to pull out (literally or figuratively) draw(out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8130}/H9030/[H8130]', 'inflected', 'heb', 'שָׂנֵא', '["sânêʼ"]', '["from/ [those who] hate/ me"]', '["v"]', 'to hate (personally) enemy, foe, (be) hate(-ful, -r), odious, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0343}/H9020/[H181]', 'inflected', 'heb', 'אֵיד', '["ʼêyd"]', '["calamity/ my"]', '["n-m"]', 'oppression; by implication misfortune, ruin calamity, destruction.', 'from the same as 181 (in the sense of bending down);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4937A}/[H8172]', 'lemma', 'heb', 'מִשְׁעֵן', '["mishʻên"]', '["a support","support of"]', '["n-m"]', 'a support (concretely), i.e. (figuratively) a protector or sustenance stay.', 'or מִשְׁעָן; from 8172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4800}/[H7337]', 'inflected', 'heb', 'מֶרְחָב', '["merchâb"]', '["to <the>/ roomy place","to/ [the] expanses of"]', '["n-m"]', 'enlargement, either literally (an open space, usually in a good sense), or figuratively (liberty) breadth, large place (room).', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2502A}/H9030/[H2502]', 'inflected', 'heb', 'חָלַץ', '["châlats"]', '["he rescued/ me","rescue/ me"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6666}/H9020/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["according to/ righteousness/ my"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1252}/[H1305]', 'inflected', 'heb', 'בֹּר', '["bôr"]', '["according to/ [the] cleanness of"]', '["n-m"]', 'purity cleanness, pureness.', 'from 1305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0430G}/H9020/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["from/ God/ my"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8104H}/H9012/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ I kept myself/ !"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5771G}/H9020/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["from/ iniquity/ my"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1252}/H9020/[H1305]', 'inflected', 'heb', 'בֹּר', '["bôr"]', '["according to/ cleanness/ my"]', '["n-m"]', 'purity cleanness, pureness.', 'from 1305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5048}/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["[is] to/ before","[was] to/ before","to/ before"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2623}/[H2616]', 'lemma', 'heb', 'חָסִיד', '["châçîyd"]', '["[am] faithful","[the] faithful","a faithful [person]","faithful","faithful [people]","faithful [person]"]', '["a"]', 'properly, kind, i.e. (religiously) pious (a saint) godly (man), good, holy (one), merciful, saint, (un-) godly.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2616A}/[H2616]', 'lemma', 'heb', 'חָסַד', '["châçad"]', '["you show yourself faithful"]', '["v"]', 'properly, perhaps to bow (the neck only [compare 2603] in courtesy to an equal), i.e. to be kind; also (by euphemistically [compare 1288], but rarely) to reprove shew self merciful, put to shame.', 'a primitive root');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1305}/[H1305]', 'lemma', 'heb', 'בָּרַר', '["bârar"]', '["[one who] purifies himself","chosen","polished","purified","purify yourselves","sharpen","they will purge themselves","you show yourself pure"]', '["v"]', 'to clarify (i.e. brighten), examine, select make bright, choice, chosen, cleanse (be clean), clearly, polished, (shew self) pure(-ify), purge (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5216A}/H9020/[H5214]', 'inflected', 'heb', 'נִיר', '["nîyr"]', '["[are] lamp/ my","lamp/ my"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5050}/[H5050]', 'lemma', 'heb', 'נָגַהּ', '["nâgahh"]', '["he lightens","it shines","it will make shine","it will shine"]', '["v"]', 'to glitter; causatively, to illuminate (en-) lighten, (cause to) shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2822}/H9020/[H2821]', 'inflected', 'heb', 'חֹשֶׁךְ', '["chôshek"]', '["darkness/ my"]', '["n-m"]', 'the dark; hence (literally) darkness; figuratively, misery, destruction, death, ignorance, sorrow, wickedness dark(-ness), night, obscurity.', 'from 2821;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0430G}/H9020/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["by/ God/ my","in/ God/ my"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1801}/[H1801]', 'lemma', 'heb', 'דָּלַג', '["dâlag"]', '["I leap over","[is] leaping","he will leap"]', '["v"]', 'to spring leap.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0565A}/[H561]', 'lemma', 'heb', 'אִמְרָה', '["ʼimrâh"]', '["[are] words","[the] word of","[the] words of","word of"]', '["n-f"]', 'commandment, speech, word.', 'or אֶמְרָה; feminine of 561, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6884}/[H6884]', 'lemma', 'heb', 'צָרַף', '["tsâraph"]', '["[has been] refined","[is] refined","[is] refining","[one who] refines","a metalsmith","a refiner","metalsmith","refined","someone has refined","steadfastly <to refine>"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2620}/[H982]', 'inflected', 'heb', 'חָסָה', '["châçâh"]', '["those/ [who] seek refuge","those/ [who] take refuge"]', '["v"]', 'to flee for protection; figuratively, to confide in have hope, make refuge, (put) trust.', 'a primitive root; (compare 982)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4581}/H9020/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["[are] place of refuge/ my","[is] place of refuge/ my","refuge/ my"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5425B}/[H5425]', 'inflected', 'heb', 'נָתַר', '["nâthar"]', '["and/ he set free"]', '["v"]', 'to jump, i.e. be violently agitated; causatively, to terrify, shake off, untie drive asunder, leap, (let) loose, × make, move, undo.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870G}/H9020/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["[are those who] ways/ my","way/ my","ways/ my"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7737B}/[H7737]', 'lemma', 'heb', 'שָׁוָה', '["shâvâh"]', '["I have lain down","I have placed","[he has] made","[he is] making","he made","you place"]', '["v"]', 'properly, to level, i.e. equalize; figuratively, to resemble; by implication, to adjust (i.e. counterbalance, be suitable, compose, place, yield, etc.) avail, behave, bring forth, compare, countervail, (be, make) equal, lay, be (make, a-) like, make plain, profit, reckon.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7272}/H9020/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["feet/ my","foot/ my"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0355}/[H354]', 'inflected', 'heb', 'אַיָּלָה', '["ʼayâlâh"]', '["like <the>/ does"]', '["n-f"]', 'a doe or female deer hind.', 'feminine of 354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1116>/H9020', 'opaque', 'heb', 'בָּמָה', '["bâmâh"]', '["high places/ my"]', '["n-f"]', 'an elevation height, high place, wave.', 'from an unused root (meaning to be high);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5975G}/H9030/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["he has made stand firm/ me","he makes stand firm/ me"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5181}/[H5181]', 'inflected', 'heb', 'נָחַת', '["nâchath"]', '["and/ it has come down","and/ it will stretch"]', '["v"]', 'to sink, i.e. descend; causatively, to press or lead down be broken, (cause to) come down, enter, go down, press sore, settle, stick fast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5154}/[H5153]', 'lemma', 'heb', 'נְחוּשָׁה', '["nᵉchûwshâh"]', '["[was] bronze","bronze","copper"]', '["n-f"]', 'copper brass, steel. Compare 5176.', 'or נְחֻשָׁה; feminine of 5153;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2220}/H9020/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["arm/ my","arms/ my"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3468}/H9021/[H3467]', 'inflected', 'heb', 'יֶשַׁע', '["yeshaʻ"]', '["salvation/ your"]', '["n-m"]', 'liberty, deliverance, prosperity safety, salvation, saving.', 'or יֵשַׁע; from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6038}/H9021/[H6035]', 'inflected', 'heb', 'עֲנָוָה', '["ʻănâvâh"]', '["and/ answering/ your"]', '["n-f"]', 'condescension, human and subjective (modesty), or divine and objective (clemency) gentleness, humility, meekness.', 'from 6035;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7235A}/H9030/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["you have made great/ me","you make great/ me"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6806}/H9020/[H6804]', 'inflected', 'heb', 'צַעַד', '["tsaʻad"]', '["step[s]/ my","steps/ my"]', '["n-m"]', 'a pace or regular step pace, step.', 'from 6804;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478G}/H9030/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["under/ me"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4571}/[H4571]', 'lemma', 'heb', 'מָעַד', '["mâʻad"]', '["I will slip","it slips","make to shake","slipped","they have slipped","they slip"]', '["v"]', 'to waver make to shake, slide, slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7166}/H9020/[H7164]', 'inflected', 'heb', 'קַרְסֹל', '["qarçôl"]', '["ankles/ my"]', '["n-f"]', 'an ankle (as a protuberance or joint) foot.', 'from 7164;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615H}/H9038/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["I have made an end of/ them","brought to an end/ them","destroy/ them","destroyed/ them","they had destroyed/ them","you brought to an end/ them"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3615H}/H9038/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["and/ I brought to an end/ them"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4272}/H9038/[H4272]', 'inflected', 'heb', 'מָחַץ', '["mâchats"]', '["and/ I shattered/ them"]', '["v"]', 'to dash asunder; by implication, to crush, smash or violently plunge; figuratively, to subdue or destroy dip, pierce (through), smite (through), strike through, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965B}/H9013/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["they rise up/ !","they will rise/ !"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0247}/H9030/[H247]', 'inflected', 'heb', 'אָזַר', '["ʼâzar"]', '["and/ you girded/ me","and/ you have girded/ me"]', '["v"]', 'to belt bind (compass) about, gird (up, with).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6965J}/H9030/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["[those who] rise against/ me"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0341}/H9020/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["and/ enemies/ my"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6789}/H9038/[H6789]', 'inflected', 'heb', 'צָמַת', '["tsâmath"]', '["and/ I destroyed/ them"]', '["v"]', 'to extirpate (literally or figuratively) consume, cut off, destroy, vanish.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6030B}/H9038/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["I will answer/ them","he answered/ them","you answered/ them"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7833}/H9038/[H7833]', 'inflected', 'heb', 'שָׁחַק', '["shâchaq"]', '["and/ I beat fine/ them","and/ I crushed/ them"]', '["v"]', 'to comminate (by trituration or attrition) beat, wear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H2916>', 'inflected', 'heb', 'כטיט', '["ke./Tit","ke./tit"]', '["like/ [the] mud of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1854}/H9038/[H1915]', 'inflected', 'heb', 'דָּקַק', '["dâqaq"]', '["I pulverized/ them"]', '["v"]', 'to crush (or intransitively) crumble beat in pieces (small), bruise, make dust, (into) × powder, (be, very) small, stamp (small).', 'a primitive root (compare 1915);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7554}/H9038/[H7554]', 'inflected', 'heb', 'רָקַע', '["râqaʻ"]', '["I beat out/ them"]', '["v"]', 'to pound the earth (as a sign of passion); by analogy to expand (by hammering); by implication, to overlay (with thin sheets of metal) beat, make broad, spread abroad (forth, over, out, into plates), stamp, stretch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6403}/H9030/[H6403]', 'inflected', 'heb', 'פָּלַט', '["pâlaṭ"]', '["and/ you rescued/ me"]', '["v"]', 'to slip out, i.e. escape; causatively, to deliver calve, carry away safe, deliver, (cause to) escape.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7379}/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["from/ [the] strifes of","from/ [the] strivings of","from/ strife","from/ strife of"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104H}/H9030/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["he watched over/ me","keep/ me","protect/ me","you kept/ me"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647H}/H9030/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["they serve/ me","they served/ me","they will serve/ me"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0241H}/[H238]', 'lemma', 'heb', 'אֹזֶן', '["ʼôzen"]', '["an ear"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4526}/H9028/[H5462]', 'inflected', 'heb', 'מִסְגֶּרֶת', '["miçgereth"]', '["from/ strongholds/ their"]', '["n-f"]', 'something enclosing, i.e. a margin (of a region, of a panel); concretely, a stronghold border, close place, hole.', 'from 5462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3318H}/H9030/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ [is] bringing out/ me","and/ take out/ me"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6965B}/H9030/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ from/ [those who] rise against/ me"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7311A}/H9030/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["O [one who] raises/ me","he will raise up/ me","you have exalted/ me","you lift up/ me"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8034}/H9021/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["and/ to/ name/ your"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4024A}/[H4024]', 'lemma', 'heb', 'מִגְדּוֹל', '["Migdôwl"]', '["[the] tower"]', '["n-pr-m n-m"]', 'Migdol, a place in Egypt Migdol, tower.', 'or מִגְדֹּל; probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4899}/H9023/[H4886]', 'inflected', 'heb', 'מָשִׁיחַ', '["mâshîyach"]', '["to/ anointed/ his"]', '["n-m"]', 'anointed; usually a consecrated person (as a king, priest, or saint); specifically, the Messiah anointed, Messiah.', 'from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5920H}/[H5927]', 'lemma', 'heb', 'עַל', '["ʻal"]', '["a height","height"]', '["n-m"]', 'properly, the top; specifically, the Highest (i.e. God); also (adverb) aloft, to Jehovah above, high, most High.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5273B}/[H5276]', 'inflected', 'heb', 'נָעִים', '["nâʻîym"]', '["and/ [the] pleasant [one] of"]', '["a"]', 'delightful (objective or subjective, literal or figurative) pleasant(-ure), sweet.', 'from 5276;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2158}/[H2167]', 'lemma', 'heb', 'זָמִיר', '["zâmîyr"]', '["[the] song of","[the] songs of","songs"]', '["n-m"]', 'a song to be accompanied with instrumental music psalm(-ist), singing, song.', 'or זָמִר; and (feminine) זְמִרָה; from 2167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4405}/H9023/[H4448]', 'inflected', 'heb', 'מִלָּה', '["millâh"]', '["and/ speech/ his"]', '["n-f"]', 'a word; collectively, a discourse; figuratively, a topic answer, by-word, matter, any thing (what) to say, to speak(-ing), speak, talking, word.', 'from 4448 (plural masculine as if from מִלֶּה;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3956G}/H9020/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["tongue/ my"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0216}/[H215]', 'inflected', 'heb', 'אוֹר', '["ʼôwr"]', '["and/ like/ [the] light of"]', '["n-f"]', 'illumination or (concrete) luminary (in every sense, including lightning, happiness, etc.) bright, clear, day, light (-ning), morning, sun.', 'from 215;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4306}/[H4305]', 'inflected', 'heb', 'מָטַר', '["mâṭar"]', '["from/ rain"]', '["n-m"]', 'rain rain.', 'from 4305;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0776H>', 'inflected', 'heb', 'מארץ', '["me./''A.retz","me./''E.retz"]', '["from/ [the] earth","from/ [the] ground","from/ ground"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8104H}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["and/ [one who] keeps","and/ [one who] protects","and/ [who] keep","and/ keep [them]","and/ preserved"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6975}/[H6972]', 'inflected', 'heb', 'קוֹץ', '["qôwts"]', '["[is] like/ thorn[s]"]', '["n-m"]', 'a thorn thorn.', 'or קֹץ; from 6972 (in the sense of pricking);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5074}/[H5074]', 'lemma', 'heb', 'נָדַד', '["nâdad"]', '["[is] wandering","[surely] to flee","[which is] chased away","[which] wanders","[who] wanders","a fugitive","fluttering","fugitive[s]","it fled","it has fled","they flee","they had fled","they have fled","they will shudder","wanderers"]', '["v"]', 'properly, to wave to and fro (rarely to flap up and down); figuratively, to rove, flee, or (causatively) to drive away chase (away), × could not, depart, flee (× apace, away), (re-) move, thrust away, wander (abroad, -er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0784}/[H784]', 'inflected', 'heb', 'אֵשׁ', '["ʼêsh"]', '["and/ in/ [the] fire of","and/ with <the>/ fire"]', '["n-f"]', 'fire (literally or figuratively) burning, fiery, fire, flaming, hot.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7675}\/[H3427]', 'inflected', 'heb', 'שֶׁבֶת', '["shebeth"]', '["at the/ dwelling"]', '["n-f"]', 'properly, session; but used also concretely, an abode or locality place, seat. Compare 3429.', 'infinitive of 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3429}/[H3427]', 'lemma', 'heb', 'יֹשֵׁב בַּשֶּׁבֶת', '["Yôshêb bash-Shebeth"]', '["Basshebeth","Josheb-"]', '["n-pr-m"]', 'Joshebbash-Shebeth, an Israelite that sat in the seat.', 'from the active participle of 3427 and 7674, with a preposition and the article interposed; sitting in the seat;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8461}/[H2453]', 'lemma', 'heb', 'תַּחְכְּמֹנִי', '["Tachkᵉmônîy"]', '["a Tahkemonite"]', '["n-pr-m"]', 'Tachkemoni, an Israelite Tachmonite.', 'probably for 2453; sagacious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7991C}/[H7969]', 'inflected', 'heb', 'שָׁלִישׁ', '["shâlîysh"]', '["the/ officer","the/ officers","the/ three"]', '["n-m"]', 'a triple, i.e. (as a musical instrument) a triangle (or perhaps rather three-stringed lute); also (as an indefinite, great quantity) a three-fold measure (perhaps a treble ephah); also (as an officer) a general of the third rank (upward, i.e. the highest) captain, instrument of musick, (great) lord, (great) measure, prince, three (from the margin).', 'or שָׁלוֹשׁ; (1 Chronicles 11:11; 1 Chronicles 12:18), or שָׁלֹשׁ; (2 Samuel 23:13), from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5722}/[H5719]', 'lemma', 'heb', 'עֲדִינוֹ', '["ʻădîynôw"]', '["Adino"]', '["n-pr-m"]', 'his spear Adino.', 'probably from 5719 in the original sense of slender (i.e. a spear);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6112G>', 'inflected', 'heb', 'העצני', '["ha./''etz.ni"]', '["the/ Eznite"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0499I}/[H410]', 'lemma', 'heb', 'אֶלְעָזָר', '["ʼElʻâzâr"]', '["Eleazar"]', '["n-pr-m"]', 'Elazar, the name of seven Israelites Eleazar.', 'from 410 and 5826; God (is) helper;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1734H}/[H1730]', 'lemma', 'heb', 'דּוֹדוֹ', '["Dôwdôw"]', '["Dodo"]', '["n-pr-m"]', 'Dodo, the name of three Israelites Dodo.', 'from 1730; loving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0266}/[H264]', 'lemma', 'heb', 'אֲחוֹחִי', '["ʼĂchôwchîy"]', '["Ahoah"]', '["a"]', 'an Achochite or descendant of Achoach Ahohite.', 'patronymic from 264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2778A}/H9048/[H2779]', 'inflected', 'heb', 'חָרַף', '["châraph"]', '["when/ defied/ they"]', '["v"]', 'to pull off, i.e. (by implication) to expose (as by stripping); specifically, to betroth (as if a surrender); figuratively, to carp at, i.e. defame; to spend the winter betroth, blaspheme, defy, jeopard, rail, reproach, upbraid.', 'a primitive root; also denominative (from 2779)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8668H}/[H7768]', 'lemma', 'heb', 'תְּשׁוּעָה', '["tᵉshûwʻâh"]', '["a deliverance","deliverance","victory"]', '["n-f"]', 'rescue (literal or figurative, persons, national or spiritual) deliverance, help, safety, salvation, victory.', 'or תְּשֻׁעָה; from 7768 in the sense of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6584}\/[H6584]', 'inflected', 'heb', 'פָּשַׁט', '["pâshaṭ"]', '["to/ strip"]', '["v"]', 'to spread out (i.e. deploy in hostile array); by analogy, to strip (i.e. unclothe, plunder, flay, etc.) fall upon, flay, invade, make an invasion, pull off, put off, make a road, run upon, rush, set, spoil, spread selves (abroad), strip (off, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8037G}/[H8074]', 'lemma', 'heb', 'שַׁמָּא', '["Shammâʼ"]', '["Shamma"]', '["n-pr-m"]', 'Shamma, an Israelite Shamma.', 'from 8074; desolation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0089>', 'opaque', 'heb', 'אָגֵא', '["ʼÂgêʼ"]', '["Agee"]', '["n-pr-m"]', 'Age, an Israelite Agee.', 'of uncertain derivation (compare 90);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2043}/[H2042]', 'lemma', 'heb', 'הֲרָרִי', '["Hărârîy"]', '["[the] Hararite"]', '["a n-pr-m"]', 'Hararite.', 'or הָרָרִי; (2 Samuel 23:11), or הָארָרִי; (2 Samuel 23:34, last clause), apparently from 2042; a mountaineer');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2416D}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["to <the>/ Lehi"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5337}/H9034/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ he delivered/ it","and/ they defended/ it"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1419A}\/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["great"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H7970}/[H7969]', 'inflected', 'heb', 'שְׁלוֹשִׁים', '["shᵉlôwshîym"]', '["from/ the/ thirty"]', '["n-m"]', 'thirty; or (ordinal) thirtieth thirty, thirtieth. Compare 7991.', 'or שְׁלֹשִׁים; multiple of 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2416D}/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["and/ a community of"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4673}/[H5324]', 'inflected', 'heb', 'מַצָּב', '["matstsâb"]', '["and/ a garrison of"]', '["n-m"]', 'a fixed spot; figuratively, an office, a military post garrison, station, place where...stood.', 'from 5324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0183}/[H183]', 'inflected', 'heb', 'אָוָה', '["ʼâvâh"]', '["and/ he craved","and/ he desired","and/ they craved"]', '["v"]', 'to wish for covet, (greatly) desire, be desirous, long, lust (after).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0877}/[H874]', 'inflected', 'heb', 'בֹּאר', '["bôʼr"]', '["from/ [the] well of"]', '["n-m"]', 'a cistern cistern.', 'from 874;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8354}/H9038/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["to/ drink/ them"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6213A}/H9040/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["than/ to do/ I"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H1818}/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["¿/ [the] blood of"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1368}\/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["the/ mighty [men]","the/ warriors"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6467}/[H6466]', 'lemma', 'heb', 'פֹּעַל', '["pôʻal"]', '["[the] acquisition of","[the] deed[s]","[the] deed[s] of","[the] work of","a deed","deeds"]', '["n-m"]', 'an act or work (concretely) act, deed, do, getting, maker, work.', 'from 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6909}/[H6908]', 'inflected', 'heb', 'קַבְצְאֵל', '["Qabtsᵉʼêl"]', '["from/ Kabzeel"]', '["n-pr-loc"]', 'Kabtseel, a place in Palestine Kabzeel. Compare 3343.', 'from 6908 and 410; God has gathered;');
