INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7970}/[H7969]', 'inflected', 'heb', 'שְׁלוֹשִׁים', '["shᵉlôwshîym"]', '["the/ thirty"]', '["n-m"]', 'thirty; or (ordinal) thirtieth thirty, thirtieth. Compare 7991.', 'or שְׁלֹשִׁים; multiple of 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4928}/H9023\/[H4926]', 'inflected', 'heb', 'מִשְׁמַעַת', '["mishmaʻath"]', '["bodyguard/ his"]', '["n-f"]', 'audience, i.e. the royal court; also obedience, i.e. (concretely) a subject bidding, guard, obey.', 'feminine of 4926;');
