INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5820G}/[H5794]', 'lemma', 'heb', 'עַזְמָוֶת', '["ʻAzmâveth"]', '["Azmaveth"]', '["n-pr-m n-pr-loc"]', 'Azmaveth, the name of three Israelites and of a place in Palestine Azmaveth. See also 1041.', 'from 5794 and 4194; strong one of death;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1273}\/[H978]', 'inflected', 'heb', 'בַּרְחֻמִי', '["Barchumîy"]', '["the/ Barhumite"]', '["a"]', 'a Barchumite, or native of Bachurim Barhumite.', 'by transposition for 978;');
