INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8170}/[H8169]', 'inflected', 'heb', 'שַׁעַלְבֹנִי', '["Shaʻalbônîy"]', '["the/ Shaalbonite"]', '["n-pr-m"]', 'a Shaalbonite or inhabitant of Shaalbin Shaalbonite.', 'patrial from 8169;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3464}/[H3463]', 'lemma', 'heb', 'יָשֵׁן', '["Yâshên"]', '["Jashen"]', '["n-pr-m"]', 'Jashen, an Israelite Jashen.', 'the same as 3463;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3083J}\/[H3068]', 'inflected', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8048I}/[H8047]', 'lemma', 'heb', 'שַׁמָּה', '["Shammâh"]', '["Shammah"]', '["n-pr-m"]', 'Shammah, the name of an Edomite and four Israelites Shammah.', 'the same as 8047;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2043}/[H2042]', 'inflected', 'heb', 'הֲרָרִי', '["Hărârîy"]', '["the/ Hararite"]', '["a n-pr-m"]', 'Hararite.', 'or הָרָרִי; (2 Samuel 23:11), or הָארָרִי; (2 Samuel 23:34, last clause), apparently from 2042; a mountaineer');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0279}/[H251]', 'lemma', 'heb', 'אֲחִיאָם', '["ʼĂchîyʼâm"]', '["Ahiam"]', '["n-pr-m"]', 'Achiam, an Israelite Ahiam.', 'from 251 and 517; brother of the mother (i.e. uncle);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8325}/[H8324]', 'lemma', 'heb', 'שָׁרַר', '["Shârar"]', '["Sharar"]', '["n-pr-m"]', 'Sharar, an Israelite Sharar.', 'from 8324; hostile;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2043}\/[H2042]', 'inflected', 'heb', 'הֲרָרִי', '["Hărârîy"]', '["the/ Hararite"]', '["a n-pr-m"]', 'Hararite.', 'or הָרָרִי; (2 Samuel 23:11), or הָארָרִי; (2 Samuel 23:34, last clause), apparently from 2042; a mountaineer');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0467H}/[H410]', 'lemma', 'heb', 'אֱלִיפֶלֶט', '["ʼĔlîypheleṭ"]', '["Eliphelet"]', '["n-pr-m"]', 'Eliphelet or Elpelet, the name of six Israelites Eliphalet, Eliphelet, Elpalet.', 'or (shortened) אֱלְפֶּלֶט; from 410 and 6405; God of deliverance;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0308>', 'opaque', 'heb', 'אֲחַסְבַּי', '["ʼĂchaçbay"]', '["Ahasbai"]', '["n-pr-f"]', 'Achasbai, an Israelite Ahasbai.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4602}\/[H4601]', 'inflected', 'heb', 'מַעֲכָתִי', '["Maʻăkâthîy"]', '["the/ Maacathite"]', '["a"]', 'a Maakathite, or inhabitant of Maakah Maachathite.', 'patrial from 4601;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0463H}/[H410]', 'lemma', 'heb', 'אֱלִיעָם', '["ʼĔlîyʻâm"]', '["Eliam"]', '["n-pr-m"]', 'Eliam, an Israelite Eliam.', 'from 410 and 5971; God of (the) people;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1526}\/[H1542]', 'inflected', 'heb', 'גִּילֹנִי', '["Gîylônîy"]', '["the/ Gilonite"]', '["a"]', 'a Gilonite or inhabitant of Giloh Gilonite.', 'patrial from 1542;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2695}/[H2696]', 'lemma', 'heb', 'חֶצְרוֹ', '["Chetsrôw"]', '["Hezrai","Hezro"]', '["n-pr-m"]', 'Chetsro, an Israelite Hezro, Hezrai.', 'by an orthographical variation for 2696; enclosure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6474}/[H6473]', 'lemma', 'heb', 'פַּעֲרַי', '["Paʻăray"]', '["Paarai"]', '["n-pr-m"]', 'Paarai, an Israelite Paarai.', 'from 6473; yawning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0701}\/[H694]', 'inflected', 'heb', 'אַרְבִּי', '["ʼArbîy"]', '["the/ Arbite"]', '["a"]', 'an Arbite or native of Arab Arbite.', 'patrial from 694;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3008H}/[H1350]', 'lemma', 'heb', 'יִגְאָל', '["Yigʼâl"]', '["Igal"]', '["n-pr-m"]', 'Jigal, the name of three Israelites Igal, Igeal.', 'from 1350; avenger;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5416I}/[H5414]', 'lemma', 'heb', 'נָתָן', '["Nâthân"]', '["Nathan"]', '["n-pr-m"]', 'Nathan, the name of five Israelites Nathan.', 'from 5414; given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H6678G>\', 'inflected', 'heb', 'מצבה ס', '["mi./tzo.Vah"]', '["from/ Zobah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1137G}/[H1129]', 'lemma', 'heb', 'בָּנִי', '["Bânîy"]', '["Bani"]', '["n-pr-m"]', 'Bani, the name of five Israelites Bani.', 'from 1129; built;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1425}\/[H1410]', 'inflected', 'heb', 'גָּדִי', '["Gâdîy"]', '["the/ Gadite"]', '["a"]', 'a Gadite (collectively) or descendants of Gad Gadites, children of Gad.', 'patronymically from 1410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6768>', 'opaque', 'heb', 'צֶלֶק', '["Tseleq"]', '["Zelek"]', '["n-pr-m"]', 'Tselek, an Israelite Zelek.', 'from an unused root meaning to split; fissure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5984H}\/[H5983]', 'inflected', 'heb', 'עַמּוֹנִי', '["ʻAmmôwnîy"]', '["the/ Ammonite"]', '["a"]', 'an Ammonite or (the adjective) Ammonitish Ammonite(-s).', 'patronymically from 5983;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5171}/[H5170]', 'lemma', 'heb', 'נַחֲרַי', '["Nachăray"]', '["Naharai"]', '["n-pr-m"]', 'Nacharai or Nachrai, an Israelite Naharai, Nahari.', 'or נַחְרַי; from the same as 5170; snorer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6870}\/[H6875]', 'inflected', 'heb', 'צְרוּיָה', '["Tsᵉrûwyâh"]', '["Zeruiah"]', '["n-pr-f"]', 'Tserujah, an Israelitess Zeruiah.', 'feminine passive participle from the same as 6875; wounded;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5896I}/[H5782]', 'lemma', 'heb', 'עִירָא', '["ʻÎyrâʼ"]', '["Ira"]', '["n-pr-m"]', 'Ira, the name of three Israelites Ira.', 'from 5782; wakefulness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3505}/[H3500]', 'inflected', 'heb', 'יִתְרִי', '["Yithrîy"]', '["the/ Ithrite","the/ Ithrite[s]"]', '["a"]', 'a Jithrite or descendant of Jether Ithrite.', 'patronymically from 3500;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1619G}/[H1618]', 'lemma', 'heb', 'גָּרֵב', '["Gârêb"]', '["Gareb"]', '["n-pr-m n-pr-loc"]', 'Gareb, the name of an Israelite, also of a hill near Jerusalem Gareb.', 'from the same as 1618; scabby;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3505}\/[H3500]', 'inflected', 'heb', 'יִתְרִי', '["Yithrîy"]', '["the/ Ithrite"]', '["a"]', 'a Jithrite or descendant of Jether Ithrite.', 'patronymically from 3500;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7651}\/[H7650]', 'inflected', 'heb', 'שֶׁבַע', '["shebaʻ"]', '["and/ seven"]', '["n"]', 'seven (as the sacred full one); also (adverbially) seven times; by implication, a week; by extension, an indefinite number ( by) seven(-fold),-s, (-teen, -teenth), -th, times). Compare 7658.', 'or (masculine) (שִׁבְעָה); from 7650; a primitive cardinal number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2734}/[H2787]', 'inflected', 'heb', 'חָרָה', '["chârâh"]', '["to/ burn"]', '["v"]', 'to glow or grow warm; figuratively (usually) to blaze up, of anger, zeal, jealousy be angry, burn, be displeased, × earnestly, fret self, grieve, be (wax) hot, be incensed, kindle, × very, be wroth. See 8474.', 'a primitive root (compare 2787);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5496}/[H7898]', 'inflected', 'heb', 'סוּת', '["çûwth"]', '["and/ he incited"]', '["v"]', 'properly, to prick, i.e. (figuratively) stimulate; by implication, to seduce entice, move, persuade, provoke, remove, set on, stir up, take away.', 'perhaps denominative from 7898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H9038}', 'inflected', 'heb', 'כהם', '["ka./Hem","kha./Hem"]', '["like <the>/ them","like/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H9038}', 'inflected', 'heb', 'וכהם', '["ve./kha./Hem"]', '["and/ like <the>/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6485A}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["to/ enroll"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6177G}/[H6176]', 'inflected', 'heb', 'עֲרוֹעֵר', '["ʻĂrôwʻêr"]', '["at/ Aroer","in/ Aroer"]', '["n-pr-loc"]', 'Aroër, the name of three places in or near Palestine Aroer.', 'or עֲרֹעֵר; or עַרְעוֹר; the same as 6176; nudity of situation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1410G}/[H1464]', 'inflected', 'heb', 'גָּד', '["Gâd"]', '["<the>/ Gad"]', '["n-pr-m"]', 'Gad, a son of Jacob, including his tribe and its territory; also a prophet Gad.', 'from 1464;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1568G}/H9011/[H1567]', 'inflected', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["<the>/ Gilead/ towards"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8483}/[H8482]', 'lemma', 'heb', 'תַּחְתִּים חׇדְשִׁי', '["Tachtîym Chodshîy"]', '["Hodshi","Tahtim"]', '["n-pr-loc"]', 'Tachtim-Chodshi, a place in Palestine Tahtim-hodshi.', 'apparently from the plural masculine of 8482 or 8478 and 2320; lower (ones) monthly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1835G}/H9011/[H1777]', 'inflected', 'heb', 'דָּן', '["Dân"]', '["Dan/ towards"]', '["n-pr-m"]', 'Dan, one of the sons of Jacob; also the tribe descended from him, and its territory; likewise a place in Palestine colonized by them Daniel', 'from 1777; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1842}/[H1835]', 'lemma', 'heb', 'דָּן יַעַן', '["Dân Yaʻan"]', '["Jaan"]', '["n-pr-loc"]', 'Dan-Jaan, a place in Palestine Dan-jaan.', 'from 1835 and (apparently) 3282; judge of purpose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7751A}/[H7751]', 'inflected', 'heb', 'שׁוּט', '["shûwṭ"]', '["and/ they went about"]', '["v"]', 'properly, to push forth; (but used only figuratively) to lash, i.e. (the sea with oars) to row; by implication, to travel go (about, through, to and fro), mariner, rower, run to and fro.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4662H}/[H6485]', 'lemma', 'heb', 'מִפְקָד', '["miphqâd"]', '["[the] muster of"]', '["n-m"]', 'an appointment, i.e. mandate; concretely, a designated spot; specifically, a census appointed place, commandment, number.', 'from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1242}\/[H1239]', 'inflected', 'heb', 'בֹּקֶר', '["bôqer"]', '["in the/ morning"]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2374}/[H2372]', 'lemma', 'heb', 'חֹזֶה', '["chôzeh"]', '["O seer","[the] seer of","an agreement","seer"]', '["n-m"]', 'a beholder in vision; also a compact (as looked upon with approval) agreement, prophet, see that, seer, (star-) gazer.', 'active participle of 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5190}/[H5190]', 'lemma', 'heb', 'נָטַל', '["nâṭal"]', '["[am] laying","he has laid [it]","he lifts"]', '["v"]', 'to lift; by implication, to impose bear, offer, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5127}/H9041/[H5127]', 'inflected', 'heb', 'נוּס', '["nûwç"]', '["fleeing/ you"]', '["v"]', 'to flit, i.e. vanish away (subside, escape; causatively, chase, impel, deliver) × abate, away, be displayed, (make to) flee (away, -ing), put to flight, × hide, lift up a standard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7200J}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697H}\/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["word"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H4397H>', 'inflected', 'heb', 'למלאך', '["la./mal.''Akh"]', '["to the/ angel"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0728}/[H771]', 'inflected', 'heb', 'אֲרַוְנָה', '["ʼĂravnâh"]', '["<the>/ Araunah"]', '["n-pr-m"]', 'Aravnah (or Arnijah or Ornah), a Jebusite Araunah.', 'or (by transposition) אוֹרְנָה; or אַרְנִיָּהlemma אַנִיָּה missing resh, corrected to אַרְנִיָּה; all by orthographical variation for 771;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7200G}/H9043/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["when/ appears/ he","when/ saw/ he","when/ sees/ it","when/ showed/ he"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001G}/H9020\/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["father/ my"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0728}/[H771]', 'lemma', 'heb', 'אֲרַוְנָה', '["ʼĂravnâh"]', '["Araunah"]', '["n-pr-m"]', 'Aravnah (or Arnijah or Ornah), a Jebusite Araunah.', 'or (by transposition) אוֹרְנָה; or אַרְנִיָּהlemma אַנִיָּה missing resh, corrected to אַרְנִיָּה; all by orthographical variation for 771;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6113}/[H6113]', 'inflected', 'heb', 'עָצָר', '["ʻâtsâr"]', '["and/ shut up","and/ to restrain","so/ it may be restrained"]', '["v"]', 'to inclose; by analogy, to hold back; also to maintain, rule, assemble × be able, close up, detain, fast, keep (self close, still), prevail, recover, refrain, × reign, restrain, retain, shut (up), slack, stay, stop, withhold (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5927I}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["and/ let him offer up","and/ offering up","and/ to offer up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H4173>', 'inflected', 'heb', 'והמורגים', '["ve./ha/m.mo.ri.Gim"]', '["and/ the/ threshing-sledges"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4428G}\/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["of the/ king","to the/ king"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7521}/H9031/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["may he accept favorably/ you"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0853}/H9031/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["from/ <obj.>/ you"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4242>', 'inflected', 'heb', 'במחיר', '["bi/m.Chir","vi/m.Chir"]', '["for/ a price","for/ hire","for/ price"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0049}/[H1]', 'lemma', 'heb', 'אֲבִישַׁג', '["ʼĂbîyshag"]', '["Abishag"]', '["n-pr-f"]', 'Abishag, a concubine of David Abishag.', 'from 1 and 7686; father of error (i.e. blundering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7767}/[H7766]', 'inflected', 'heb', 'שׁוּנַמִּית', '["Shûwnammîyth"]', '["[is] the/ Shunammite [woman]","the/ Shunammite","the/ Shunammite [woman]"]', '["a"]', 'a Shunammitess, or female inhabitant of Shunem Shunamite.', 'patrial from 7766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8334}/H9033/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["and/ she served/ him"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0138G}/[H113]', 'inflected', 'heb', 'אֲדֹנִיָּה', '["ʼĂdônîyâh"]', '["and/ Adonijah"]', '["n-pr-m"]', 'Adonijah, the name of three Israelites Adonijah.', 'original (prolonged) אֲדֹנִיָּהוּ ; from 113 and 3050; lord (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6571B}/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["and/ horsemen","and/ warhorses"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6087A}/H9033/[H6087]', 'inflected', 'heb', 'עָצַב', '["ʻâtsab"]', '["he had rebuked/ him","they grieved/ him"]', '["v"]', 'properly, to carve, i.e. fabricate or fashion; hence (in a bad sense) to worry, pain or anger displease, grieve, hurt, make, be sorry, vex, worship, wrest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3117G>/H9023', 'inflected', 'heb', 'מימיו', '["mi./ya.Ma/v"]', '["from/ days/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697I}/H9023/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["parts/ its","words/ his"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5416H}/[H5414]', 'inflected', 'heb', 'נָתָן', '["Nâthân"]', '["and/ Nathan"]', '["n-pr-m"]', 'Nathan, the name of five Israelites Nathan.', 'from 5414; given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8096I}/[H8088]', 'inflected', 'heb', 'שִׁמְעִי', '["Shimʻîy"]', '["and/ Shimei"]', '["n-pr-m"]', 'Shimi, the name of twenty Israelites Shimeah (from the margin), Shimei, Shimhi, Shimi.', 'from 8088; famous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7472}/[H7453]', 'inflected', 'heb', 'רֵעִי', '["Rêʻîy"]', '["and/ Rei"]', '["n-pr-m"]', 'Rei, an Israelite Rei.', 'from 7453; social;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1368}/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["and/ the/ mighty [men]"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0068I}/[H1129]', 'lemma', 'heb', 'אֶבֶן', '["ʼeben"]', '["[the] stone of"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2120}/[H2119]', 'inflected', 'heb', 'זֹחֶלֶת', '["Zôcheleth"]', '["<the>/ Zoheleth"]', '["n-pr-f"]', 'Zocheleth, a boundary stone in. Palestine Zoheleth.', 'feminine active participle of 2119; crawling (i.e. serpent);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0113>/H9025', 'inflected', 'heb', 'ואדנינו', '["va./''a.do.Nei./nu"]', '["and/ lord<s>/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3289}/H9032/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["counselor/ your","let me counsel/ you"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4422}/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["and/ [a woman who] escapes","and/ he may deliver [them]","and/ save","and/ they were delivered"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315H}/H9022/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["life/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3678G}/H9020/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["[are] throne/ my","throne/ my"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5750}/H9042/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["still/ you"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310A}/H9032/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["after/ you","behind/ you"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697G}/H9022/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0049}/[H1]', 'inflected', 'heb', 'אֲבִישַׁג', '["ʼĂbîyshag"]', '["and/ Abishag"]', '["n-pr-f"]', 'Abishag, a concubine of David Abishag.', 'from 1 and 7686; father of error (i.e. blundering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3097G}/[H3068]', 'inflected', 'heb', 'יוֹאָב', '["Yôwʼâb"]', '["and/ <to>/ Joab","and/ for/ Joab"]', '["n-pr-m"]', 'Joab, the name of three Israelites Joab.', 'from 3068 and 1; Jehovah-fathered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8010}/[H7965]', 'inflected', 'heb', 'שְׁלֹמֹה', '["Shᵉlômôh"]', '["and/ <to>/ Solomon","and/ [belonged] to/ Solomon","and/ for/ Solomon","and/ to/ Solomon"]', '["n-pr-m"]', 'Shelomah, David''s successor Solomon.', 'from 7965; peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7901H}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["when/ lies down"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5750}/H9044/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["still/ she"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6659G}/[H6663]', 'inflected', 'heb', 'צָדוֹק', '["Tsâdôwq"]', '["and/ <to>/ Zadok"]', '["n-pr-m"]', 'Tsadok, the name of eight or nine Israelites Zadok.', 'from 6663; just;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1141G}/[H1129]', 'inflected', 'heb', 'בְּנָיָה', '["Bᵉnâyâh"]', '["and/ <to>/ Benaiah"]', '["n-pr-m"]', 'Benajah, the name of twelve Israelites Benaiah.', 'or בּנָיָהוּ; (prolonged) from 1129 and 3050; Jah has built;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1339}/[H1323]', 'inflected', 'heb', 'בַּת־שֶׁבַע', '["Bath-Shebaʻ"]', '["<to>/ Bath-"]', '["n-pr-f"]', 'Bath-Sheba, the mother of Solomon Bath-sheba.', 'from 1323 and 7651 (in the sense of 7650); daughter of an oath;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478H}/H9030/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["in place of/ me"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5416H}/[H5414]', 'inflected', 'heb', 'נָתָן', '["Nâthân"]', '["and/ <to>/ Nathan"]', '["n-pr-m"]', 'Nathan, the name of five Israelites Nathan.', 'from 5414; given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6506}/[H6505]', 'inflected', 'heb', 'פִּרְדָּה', '["pirdâh"]', '["the/ mule"]', '["n-f"]', 'a she-mule mule.', 'feminine of 6505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3678G}/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["more than/ [the] throne of"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6506}/[H6505]', 'lemma', 'heb', 'פִּרְדָּה', '["pirdâh"]', '["[the] mule of"]', '["n-f"]', 'a she-mule mule.', 'feminine of 6505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2490B}/[H2470]', 'lemma', 'heb', 'חָלַל', '["châlal"]', '["[were] playing [the] flute"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2485}/[H2490]', 'inflected', 'heb', 'חָלִיל', '["châlîyl"]', '["with <the>/ flute","with/ flutes"]', '["n-m"]', 'a flute (as perforated) pipe.', 'from 2490;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8056}/[H8055]', 'inflected', 'heb', 'שָׂמֵחַ', '["sâmêach"]', '["and/ [were] joyful","and/ joyful"]', '["a"]', 'blithe or gleeful (be) glad, joyful, (making) merry((-hearted), -ily), rejoice(-ing).', 'from 8055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8057}/[H8056]', 'lemma', 'heb', 'שִׂמְחָה', '["simchâh"]', '["[is] a joy","[is] joy","[the] joy of","[the] rejoicing of","a joy","gladness","gladness<es>","joy","joy of","pleasure"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6963H>/H9028', 'inflected', 'heb', 'בקולם', '["be./ko.La/m"]', '["by/ noise/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7151}/[H7136]', 'inflected', 'heb', 'קִרְיָה', '["qiryâh"]', '["the/ town"]', '["n-f"]', 'a city city.', 'from 7136 in the sense of flooring, i.e. building;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1993}/[H1949]', 'lemma', 'heb', 'הָמָה', '["hâmâh"]', '["[is] boisterous","[is] in turmoil","[is] noisy","[which] it roars","are you in turmoil","in an uproar","it will groan","moaning","noisy [places]","they are in a tumult","they growl","they make a sound","they were in a tumult","they were turbulent","they will be in an uproar","they will roar","turbulent","we growl"]', '["v"]', 'to make a loud sound (like English ''hum''); by implication, to be in great commotion or tumult, to rage, war, moan, clamor clamorous, concourse, cry aloud, be disquieted, loud, mourn, be moved, make a noise, rage, roar, sound, be troubled, make in tumult, tumultuous, be in an uproar.', 'a primitive root (compare 1949);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3129O}/[H3083]', 'lemma', 'heb', 'יוֹנָתָן', '["Yôwnâthân"]', '["Jonathan"]', '["n-pr-m"]', 'Jonathan, the name of ten Israelites Jonathan.', 'a form of 3083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2896B}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["and/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0138G}/[H113]', 'inflected', 'heb', 'אֲדֹנִיָּה', '["ʼĂdônîyâh"]', '["[belonged] to/ Adonijah","for/ Adonijah","to/ Adonijah"]', '["n-pr-m"]', 'Adonijah, the name of three Israelites Adonijah.', 'original (prolonged) אֲדֹנִיָּהוּ ; from 113 and 3050; lord (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1521}/[H1518]', 'inflected', 'heb', 'גִּיחוֹן', '["Gîychôwn"]', '["at/ Gihon"]', '["n-pr-m"]', 'Gichon, a river of Paradise; also a valley (or pool) near Jerusalem Gihon.', 'or (shortened) גִּחוֹן; from 1518; stream;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6963H>', 'inflected', 'heb', 'הקול', '["ha./Kol"]', '["[is] the/ noise"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8034}/H9021/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["more than/ name/ your"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3678G}/H9021/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["more than/ throne/ your"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5869A}/H9020/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["and/ eye/ my","and/ own eyes/ my"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8010}/[H7965]', 'inflected', 'heb', 'שְׁלֹמֹה', '["Shᵉlômôh"]', '["<to>/ Solomon","[belonged] to/ Solomon","[is] of/ Solomon","for/ Solomon","of/ Solomon","to/ Solomon"]', '["n-pr-m"]', 'Shelomah, David''s successor Solomon.', 'from 7965; peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8185}/H9023/[H8181]', 'inflected', 'heb', 'שַׂעֲרָה', '["saʻărâh"]', '["one of/ hair[s]/ his"]', '["n-f"]', 'hairiness hair.', 'feminine of 8181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004B}/H9021\/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["to/ house/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5715}/H9023/[H5707]', 'inflected', 'heb', 'עֵדוּת', '["ʻêdûwth"]', '["and/ testimonies/ his"]', '["n-f"]', 'testimony testimony, witness.', 'feminine of 5707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8451}/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["[is] in/ [the] law of","by the/ instruction","in the/ law","in/ [the] law of"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1870G}/H9028/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["[is] way/ their","conduct/ their","way/ their","ways/ their"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315G}/H9028/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["being/ their","life/ their","self/ their"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3500H}/[H3499]', 'lemma', 'heb', 'יֶתֶר', '["Yether"]', '["Jether"]', '["n-pr-m"]', 'Jether, the name of five or six Israelites and of one Midianite Jether, Jethro. Compare 3503.', 'the same as 3499;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2290B}/H9023/[H2296]', 'inflected', 'heb', 'חֲגוֹר', '["chăgôwr"]', '["on/ belt/ his"]', '["n-m n-f"]', 'a belt (for the waist) apron, armour, gird(-le).', 'or חֲגֹר; and (feminine) חֲגוֹרָה; or חֲגֹרָה; from 2296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5275}/H9023/[H5274]', 'inflected', 'heb', 'נַעַל', '["naʻal"]', '["and/ on/ sandal[s]/ his"]', '["n-f"]', 'properly, a sandal tongue; by extension a sandal or slipper (sometimes as a symbol of occupancy, a refusal to marry, or of something valueless) dryshod, (pair of) shoe((-latchet), -s).', 'or (feminine) נַעֲלָה; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2451}/H9021/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["according to/ wisdom/ your"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7872}/H9023/[H7869]', 'inflected', 'heb', 'שֵׂיבָה', '["sêybâh"]', '["grey hair/ his"]', '["n-f"]', 'old age (be) gray (grey hoar,-y) hairs (head,-ed), old age.', 'feminine of 7869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7585}\/[H7592]', 'inflected', 'heb', 'שְׁאוֹל', '["shᵉʼôwl"]', '["Sheol"]', '["n-f"]', 'hades or the world of the dead (as if a subterranean retreat), including its accessories and inmates grave, hell, pit.', 'or שְׁאֹל; from 7592;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1272}/H9040/[H1272]', 'inflected', 'heb', 'בָּרַח', '["bârach"]', '["when/ fled/ I"]', '["v"]', 'to bolt, i.e. figuratively, to flee suddenly chase (away); drive away, fain, flee (away), put to flight, make haste, reach, run away, shoot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4834}/[H4834]', 'lemma', 'heb', 'מָרַץ', '["mârats"]', '["[will be] grievous","grievous","they are painful"]', '["v"]', 'properly, to press, i.e. (figuratively) to be pungent or vehement; to irritate embolden, be forcible, grievous, sore.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980G}/H9040/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["went/ I"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5352}/H9033/[H5352]', 'inflected', 'heb', 'נָקָה', '["nâqâh"]', '["you leave unpunished/ him"]', '["v"]', 'to be (or make) clean (literally or figuratively); by implication (in an adverse sense) to be bare, i.e. extirpated acquit × at all, × altogether, be blameless, cleanse, (be) clear(-ing), cut off, be desolate, be free, be (hold) guiltless, be (hold) innocent, × by no means, be quit, be (leave) unpunished, × utterly, × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7901J}/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ he lay down","and/ he will be laid","and/ they lay"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7965G}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["¿/ peace"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4427A}/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["of/ [the] reigning of","to/ become king","to/ make [me] king","to/ make king"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251G}/H9020/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["to/ brother/ my","to/ brothers/ my"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725L}/[H7725]', 'lemma', 'heb', 'שׁוּב', '["shûwb"]', '["I will turn away","he will turn away","you turn away"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440G}/H9022/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ your"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0517}/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["for/ [the] mother of"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3225G}/H9023/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["[is] to/ right [hand]/ his","to/ right [hand]/ his"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559H}/H9030/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["he appointed/ me"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3427}/H9030/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ he made sit/ me"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H3117L>', 'inflected', 'heb', 'וביום', '["u./vai./Yom"]', '["and/ on the/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H7218A>', 'inflected', 'heb', 'ובראש', '["u./ve./Rosh"]', '["and/ on/ [the] head of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1732}/[H1730]', 'inflected', 'heb', 'דָּוִד', '["Dâvid"]', '["and/ to/ David"]', '["n-pr-m"]', 'David, the youngest son of Jesse David.', 'rarely (fully); דָּוִיד; from the same as 1730; loving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3678G}/H9023/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["and/ to/ throne/ his"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8096H}/[H8088]', 'inflected', 'heb', 'שִׁמְעִי', '["Shimʻîy"]', '["<to>/ Shimei","of/ Shimei","to/ Shimei"]', '["n-pr-m"]', 'Shimi, the name of twenty Israelites Shimeah (from the margin), Shimei, Shimhi, Shimi.', 'from 8088; famous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7218A>/H9021', 'inflected', 'heb', 'בראשך', '["be./ro.She./kha","ve./ro.She./kha"]', '["on/ head/ your","on/ own head/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4601Q}/[H4600]', 'lemma', 'heb', 'מַעֲכָה', '["Maʻăkâh"]', '["Maacah"]', '["n-pr"]', 'Maakah (or Maakath), the name of a place in Syria, also of a Mesopotamian, of three Israelites, and of four Israelitesses and one Syrian woman Maachah, Maachathites. See also 1038.', 'or מַעֲכָת; (Joshua 13:13), from 4600; depression;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1661}/H9011/[H1660]', 'inflected', 'heb', 'גַּת', '["Gath"]', '["Gath/ towards"]', '["n-pr-loc"]', 'Gath, a Philistine city Gath.', 'the same as 1660;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4467}/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["and/ the/ kingdom"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6547K}/[H6547]', 'lemma', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1992}\/[H1931]', 'inflected', 'heb', 'הֵם', '["hêm"]', '["<the>/ those"]', '["p"]', 'they (only used when emphatic) it, like, × (how, so) many (soever, more as) they (be), (the) same, × so, × such, their, them, these, they, those, which, who, whom, withal, ye.', 'or (prolonged) הֵמָּה; masculine plural from 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6999H}/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["and/ [are] making smoke","and/ [one who] makes smoke","and/ [were] making smoke","and/ [who] make smoke","and/ he made smoke","and/ make smoke","and/ making smoke","and/ will you make smoke?","so/ he may make smoke"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6666}/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["and/ in/ righteousness"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3483}/[H3477]', 'inflected', 'heb', 'יִשְׁרָה', '["yishrâh"]', '["and/ in/ uprightness of"]', '["n-f"]', 'rectitude uprightness.', 'feminine of 3477;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0995}/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["<to>/ a discerning [person]","[belongs] to the/ understanding","to the/ discerning [person]","to/ a discerning [person]","to/ distinguish","to/ teach","to/ understand"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7451B}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<to>/ evil","and/ evil","for <the>/ evil","for/ evil","for/ harm","of <the>/ evil","to <the>/ calamity","to <the>/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3515}/[H3513]', 'inflected', 'heb', 'כָּבֵד', '["kâbêd"]', '["<the>/ heavy","<the>/ massive"]', '["a"]', 'heavy; figuratively in a good sense (numerous) or in a bad sense (severe, difficult, stupid) (so) great, grievous, hard(-ened), (too) heavy(-ier), laden, much, slow, sore, thick.', 'from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8085K}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["to/ hear"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0310A}/H9031/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["and/ after/ you"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870G}/H9020/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["in/ ways/ my"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2706G}/H9020/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["decrees/ my","statutes/ my"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4687}/H9020/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["and/ commandments/ my"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/H9021\', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days/ your"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3205}/H9030/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["of/ giving birth/ my"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0681}/H9030/[H680]', 'inflected', 'heb', 'אֵצֶל', '["ʼêtsel"]', '["from/ beside/ me"]', '["n-m"]', 'a side; (as a preposition) near at, (hard) by, (from) (beside), near (unto), toward, with. See also 1018.', 'from 680 (in the sense of joining);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7901G}/H9033/[H7901]', 'inflected', 'heb', 'שָׁכַב', '["shâkab"]', '["and/ he made lie/ him","and/ she made lie/ him","and/ they made lie/ him"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2436G>/H9020', 'inflected', 'heb', 'בחיקי', '["be./che.K/i","ve./chei.K/i"]', '["in/ bosom/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3243H}/[H3243]', 'inflected', 'heb', 'יָנַק', '["yânaq"]', '["to/ suckle"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121A}/H9022/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ [is] son/ your","and/ children/ your","and/ son/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2416A}\/[H2421]', 'inflected', 'heb', 'חַי', '["chay"]', '["[is] the/ living one"]', '["a n-m n-f"]', 'alive; hence, raw (flesh); fresh (plant, water, year), strong; also (as noun, especially in the feminine singular and masculine plural) life (or living thing), whether literally or figuratively age, alive, appetite, (wild) beast, company, congregation, life(-time), live(-ly), living (creature, thing), maintenance, merry, multitude, (be) old, quick, raw, running, springing, troop.', 'from 2421;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1504}/[H1504]', 'lemma', 'heb', 'גָּזַר', '["gâzar"]', '["cut","he was cut off","it had been decreed","someone cuts off","they are cut off","we have been cut off"]', '["v"]', 'to cut down or off; (figuratively) to destroy, divide, exclude, or decide cut down (off), decree, divide, snatch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2677}/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["<the>/ half","the/ half"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7356B}/H9024/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["compassion<s>/ her"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5838G}/[H5826]', 'lemma', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0456}/[H410]', 'lemma', 'heb', 'אֱלִיחֹרֶף', '["ʼĔlîychôreph"]', '["Elihoreph"]', '["n-pr-m"]', 'Elichoreph, an Israelite Elihoreph.', 'from 410 and 2779; God of autumn;');
