INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0354}/[H352]', 'inflected', 'heb', 'אַיָּל', '["ʼayâl"]', '["from/ deer"]', '["n-m"]', 'a stag or male deer hart.', 'an intensive form of 352 (in the sense of ram);');
