INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0075}/[H75]', 'lemma', 'heb', 'אָבַס', '["ʼâbaç"]', '["fattened"]', '["v"]', 'to fodder fatted, stalled.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5676I}/[H5674]', 'lemma', 'heb', 'עֵבֶר', '["ʻêber"]', '["[the] other side of"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8607G}/[H6452]', 'inflected', 'heb', 'תִּפְסַח', '["Tiphçach"]', '["from/ Tiphsah"]', '["n-pr-loc"]', 'Tiphsach, a place in Mesopotamia Tipsah.', 'from 6452; ford;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7965G}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["and/ peace"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5676G}/H9023/[H5674]', 'inflected', 'heb', 'עֵבֶר', '["ʻêber"]', '["sides/ his","sides/ its"]', '["n-m"]', 'properly, a region across; but used only adverbially (with or without a preposition) on the opposite side (especially of the Jordan; ususally meaning the east) × against, beyond, by, × from, over, passage, quarter, (other, this) side, straight.', 'from 5674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1612>/H9023', 'opaque', 'heb', 'גֶּפֶן', '["gephen"]', '["own vine/ his"]', '["n-m"]', 'a vine (as twining), especially the grape vine, tree.', 'from an unused root meaning to bend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8384}/H9023/[H8384]', 'inflected', 'heb', 'תְּאֵן', '["tᵉʼên"]', '["own fig tree/ his"]', '["n-f"]', 'the fig (tree or fruit) fig (tree).', 'or (in the singular, feminine) תְּאֵנָה; perhaps of foreign derivation');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8010}\/[H7965]', 'inflected', 'heb', 'שְׁלֹמֹה', '["Shᵉlômôh"]', '["Solomon"]', '["n-pr-m"]', 'Shelomah, David''s successor Solomon.', 'from 7965; peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0723}/[H717]', 'lemma', 'heb', 'אֻרְוָה', '["ʼurvâh"]', '["stalls of"]', '["n-f"]', 'a herding-place for an animal stall.', 'or אֲרָיָה; from 717 (in the sense of feeding);');
