INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8401}/[H1129]', 'inflected', 'heb', 'תֶּבֶן', '["teben"]', '["and/ the/ straw"]', '["n-m"]', 'properly, material, i.e. (specifically) refuse haum or stalks of grain (as chopped in threshing and used for fodder) chaff, straw, stubble.', 'probably from 1129;');
