INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1709H}/[H1711]', 'inflected', 'heb', 'דָּג', '["dâg"]', '["the/ fish"]', '["n-m"]', 'a fish (often used collectively) fish.', 'or (fully) דָּאג; (Nehemiah 13:16), from 1711; a fish (as prolific); or perhaps rather from 1672 (as timid); but still better from 1672 (in the sense of squirming, i.e. moving by the vibratory action of the tail);');
