INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1702}/[H1696]', 'lemma', 'heb', 'דֹּבְרָה', '["dôbᵉrâh"]', '["rafts"]', '["n-f"]', 'a raft float.', 'feminine active participle of 1696 in the sense of driving (compare 1699);');
