INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2099>', 'opaque', 'heb', 'זִו', '["Ziv"]', '["Ziv"]', '["n-pr-m"]', 'Ziv (corresponding to Ijar or May) Zif.', 'probably from an unused root meaning to be prominent; properly, brightness (compare 2122), i.e. (figuratively) the month of flowers;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1004Q}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["the/ house"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0197J}/[H481]', 'inflected', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["and/ the/ porch"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
