INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8261}/[H8259]', 'lemma', 'heb', 'שָׁקֻף', '["shâquph"]', '["frames"]', '["n-m"]', 'an embrasure or opening with bevelled jam light, window.', 'passive participle of 8259; (compare 8260)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0331}/[H331]', 'lemma', 'heb', 'אָטַם', '["ʼâṭam"]', '["[one who] shuts","[which] it shuts","[who] shuts","closed","shut"]', '["v"]', 'to close (the lips or ears); by analology to contract (a window by bevelled jambs) narrow, shut, stop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3326B}/[H3331]', 'lemma', 'heb', 'יָצוּעַ', '["yâtsûwaʻ"]', '["an extension"]', '["n-m"]', 'spread, i.e. a bed; (architecture) an extension, i.e. wing or lean-to (a single story or collectively) bed, chamber, couch.', 'passive participle of 3331;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1964I}/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["<to> the/ temple","[belonged] to the/ temple"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
