INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8561}/[H8558]', 'inflected', 'heb', 'תִּמֹּר', '["timmôr"]', '["and/ a palm tree","and/ palm trees"]', '["n-f"]', '(architectural) a palm-like pilaster (i.e. umbellate) palm tree.', '(plural or (feminine) תִּמֹּרָה; (singular and plural), from the same root as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2435}/[H2434]', 'inflected', 'heb', 'חִיצוֹן', '["chîytsôwn"]', '["and/ to the/ outer"]', '["a"]', 'properly, the (outer) wall side; hence, exterior; figuratively, secular (as opposed to sacred) outer, outward, utter, without.', 'from 2434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6441}/[H6440]', 'inflected', 'heb', 'פְּנִימָה', '["pᵉnîymâh"]', '["to/ within"]', '["adv"]', 'faceward, i.e. indoors (with-) in(-ner part, -ward).', 'from 6440 with directive enclitic;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0352B}/[H193]', 'inflected', 'heb', 'אַיִל', '["ʼayil"]', '["the/ pillar","the/ pillars"]', '["n-m"]', 'properly, strength; hence, anything strong; specifically a chief (politically); also a ram (from his strength); a pilaster (as a strong support); an oak or other strong tree mighty (man), lintel, oak, post, ram, tree.', 'from the same as 193;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7049B}/[H7049]', 'inflected', 'heb', 'קָלַע', '["qâlaʻ"]', '["and/ he carved"]', '["v"]', 'to sling; also to carve (as if a circular motion, or into light forms) carve, sling (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7286}/[H7286]', 'inflected', 'heb', 'רָדַד', '["râdad"]', '["and/ he hammered out"]', '["v"]', 'to tread in pieces, i.e. (figuratively) to conquer, or (specifically) to overlay spend, spread, subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8561}/[H8558]', 'inflected', 'heb', 'תִּמֹּר', '["timmôr"]', '["the/ palm tree","the/ palm trees"]', '["n-f"]', '(architectural) a palm-like pilaster (i.e. umbellate) palm tree.', '(plural or (feminine) תִּמֹּרָה; (singular and plural), from the same root as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1550A}/[H1556]', 'lemma', 'heb', 'גָּלִיל', '["gâlîyl"]', '["[were] revolving"]', '["a"]', 'a valve of a folding door (as turning); also a ring (as round) folding, ring.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2707}/[H2707]', 'inflected', 'heb', 'חָקָה', '["châqâh"]', '["the/ carved [work]"]', '["v"]', 'to carve; by implication, to delineate; also to entrench carved work, portrayed, set a print.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2905>', 'inflected', 'heb', 'וטור', '["ve./Tur"]', '["and/ a row of","and/ a row of stones"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3773}/[H3772]', 'lemma', 'heb', 'כָּרֻתָה', '["kâruthâh"]', '["beams of"]', '["n-f"]', 'something cut, i.e. a hewn timber beam.', 'passive participle feminine of 3772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3245}/[H3245]', 'lemma', 'heb', 'יָסַד', '["yâçad"]', '["[are] [the] founding of","[when] it was founded","founded","he established","he founded","he had appointed","he has founded","he has laid","it founded","it was founded","they have founded","they seat themselves","you founded","you had established","you have established"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3391>', 'inflected', 'heb', 'בירח', '["be./Ye.rach"]', '["in/ [the] month of","in/ a month"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0945}/[H944]', 'lemma', 'heb', 'בּוּל', '["Bûwl"]', '["Bul"]', '["n-m"]', 'Bul, the eighth Hebrew month Bul.', 'the same as 944 (in the sense of rain);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1129}/H9033/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["and/ he built/ it"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004K}/[H1129]', 'lemma', 'heb', 'בַּיִת', '["bayith"]', '["[the] House of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3293I>', 'opaque', 'heb', 'יַעַר', '["yaʻar"]', '["[the] Forest of"]', '["n-m"]', 'a copse of bushes; hence, a forest; hence, honey in the comb (as hived in trees) (honey-) comb, forest, wood.', 'from an unused root probably meaning to thicken with verdure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3844J}/[H3825]', 'inflected', 'heb', 'לְבָנוֹן', '["Lᵉbânôwn"]', '["<the>/ Lebanon"]', '["n-pr-loc"]', 'Lebanon, a mountain range in Palestine Lebanon.', 'from 3825; (the) white mountain (from its snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3773}/[H3772]', 'inflected', 'heb', 'כָּרֻתָה', '["kâruthâh"]', '["and/ beams of"]', '["n-f"]', 'something cut, i.e. a hewn timber beam.', 'passive participle feminine of 3772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5603}/[H5603]', 'inflected', 'heb', 'סָפַן', '["çâphan"]', '["and/ [it was] paneled","and/ paneled"]', '["v"]', 'to hide by covering; specifically, to roof (passive participle as noun, a roof) or wainscot; figuratively, to reserve cieled, cover, seated.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8261}/[H8259]', 'inflected', 'heb', 'שָׁקֻף', '["shâquph"]', '["and/ window frames"]', '["n-m"]', 'an embrasure or opening with bevelled jam light, window.', 'passive participle of 8259; (compare 8260)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4237}/[H2372]', 'inflected', 'heb', 'מֶחֱזָה', '["mechĕzâh"]', '["and/ window"]', '["n-f"]', 'a window light.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4237}/[H2372]', 'lemma', 'heb', 'מֶחֱזָה', '["mechĕzâh"]', '["window"]', '["n-f"]', 'a window light.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4201}/[H2123]', 'inflected', 'heb', 'מְזוּזָה', '["mᵉzûwzâh"]', '["and/ the/ doorpost","and/ the/ doorposts"]', '["n-f"]', 'a door-post (as prominent) (door, side) post.', 'or מְזֻזָה; from the same as 2123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8260}/[H8259]', 'lemma', 'heb', 'שֶׁקֶף', '["sheqeph"]', '["frame-work"]', '["n-m"]', 'a loophole (for looking out), to admit light and air window.', 'from 8259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4136}/[H4135]', 'inflected', 'heb', 'מוּל', '["mûwl"]', '["and/ [the] front"]', '["n-m"]', 'properly, abrupt, i.e. a precipice; by implication, the front; used only adverbially (with prepositional prefix) opposite (over) against, before, (fore-) front, from, (God-) ward, toward, with.', 'or מוֹל; (Deuteronomy 1:1), or מוֹאל; (Nehemiah 12:38), or מֻל; (Numbers 22:5), from 4135;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0197G}/[H481]', 'lemma', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["[the] porch of"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5982H}/[H5975]', 'inflected', 'heb', 'עַמּוּד', '["ʻammûwd"]', '["the/ pillars"]', '["n-m"]', 'a column (as standing); also a stand, i.e. platform × apiece, pillar.', 'or עַמֻּד; from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0197G}/[H481]', 'inflected', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["and/ a porch"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440G}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ their","own faces/ their"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5646>', 'inflected', 'heb', 'ועב', '["ve./''Av"]', '["and/ a threshold","and/ a threshold of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0197I}/[H481]', 'inflected', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["and/ [the] porch of"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3678H}/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["the/ throne"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0197H}/[H481]', 'lemma', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["[the] porch of"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4941K}/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["<the>/ judgment"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H7172}/[H7167]', 'inflected', 'heb', 'קַרְקַע', '["qarqaʻ"]', '["from/ the/ floor"]', '["n-m"]', 'floor (as if a pavement of pieces or tesseræ), of a building or the sea bottom, (× one side of the) floor.', 'from 7167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004B}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ household/ his","and/ own house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0197G}/[H481]', 'inflected', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["to the/ porch"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0197G}/[H481]', 'inflected', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["like the/ porch"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4060A}/[H4055]', 'inflected', 'heb', 'מִדָּה', '["middâh"]', '["[were] according to the/ measurements","[were] like/ [the] measurement of","according to the/ measurements","according to/ measurements of","like/ [the] measurement of"]', '["n-f"]', 'properly, extension, i.e. height or breadth; also a measure (including its standard); hence a portion (as measured) or a vestment; specifically, tribute (as measured) garment, measure(-ing, meteyard, piece, size, (great) stature, tribute, wide.', 'feminine of 4055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4527}/[H3245]', 'inflected', 'heb', 'מַסַּד', '["maççad"]', '["and/ from/ [the] foundation"]', '["n-m"]', 'a foundation foundation.', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2947}/[H2946]', 'inflected', 'heb', 'טֵפַח', '["ṭêphach"]', '["the/ coping stone"]', '["n-m"]', 'a spread of the hand, i.e. a palm-breadth (not ''span'' of the fingers); architecturally, a corbel (as a supporting palm) coping, hand-breadth.', 'from 2946;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3245}/[H3245]', 'inflected', 'heb', 'יָסַד', '["yâçad"]', '["and/ [it was] founded","and/ [the] founding of","and/ [who] founded"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/H9005/{H4605}/H9011/[H5927]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["and/ [were] from/ to/ above/ <towards>"]', '["adv"]', 'properly,the upper part, used only adverbially with prefix upward, above, overhead, from the top, etc. above, exceeding(-ly), forward, on (× very) high, over, up(-on, -ward), very.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2691A}/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["and/ [the] court"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0197G}/[H481]', 'inflected', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["and/ to/ [the] porch of"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2438H}/[H2361]', 'lemma', 'heb', 'חִירָם', '["Chîyrâm"]', '["Hiram"]', '["n-pr-m"]', 'Chiram or Chirom, the name of two Tyrians Hiram, Huram.', 'or חִירוֹםlemma חִירֹם missing vav, corrected to חִירוֹם; another form of 2361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6865}/[H6864]', 'inflected', 'heb', 'צֹר', '["Tsôr"]', '["from/ Tyre"]', '["n-pr-loc"]', 'Tsor, a place in Palestine Tyre, Tyrus.', 'or צוֹר; the same as 6864; a rock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6876}/[H6865]', 'lemma', 'heb', 'צֹרִי', '["Tsôrîy"]', '["Tyrian"]', '["a"]', 'a Tsorite or inhabitant of Tsor (i.e. Syrian) (man) of Tyre.', 'patrial from 6865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2451}/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["<the>/ wisdom","the/ wisdom"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8394}/[H995]', 'inflected', 'heb', 'תָּבוּן', '["tâbûwn"]', '["the/ skill"]', '["n-m"]', 'intelligence; by implication, an argument; by extension, caprice discretion, reason, skilfulness, understanding, wisdom.', 'and (feminine) תְּבוּנָה; or תּוֹבֻנָה; from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2339>', 'inflected', 'heb', 'וחוט', '["ve./Chut"]', '["and/ a line of"]', NULL, NULL, NULL);
