INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4165}/[H5694]', 'lemma', 'heb', 'מוּצָק', '["mûwtsâq"]', '["a casting","cast [metal]","casting of"]', '["n-m"]', 'properly, fusion, i.e. literally, a casting (of metal); figuratively, a mass (of clay) casting, hardness.', 'from 5694;');
