INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7639}/[H7638]', 'lemma', 'heb', 'שְׂבָכָה', '["sᵉbâkâh"]', '["a network","networks"]', '["n-f"]', 'a net-work, i.e. (in hunting) a snare, (in architecture) a ballustrade; also a reticulated ornament to a pillar checker, lattice, network, snare, wreath(-enwork).', 'feminine of 7638;');
