INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3805}/[H3803]', 'inflected', 'heb', 'כֹתֶרֶת', '["kôthereth"]', '["and/ [the] capitals","and/ a capital"]', '["n-f"]', 'the capital of a column chapiter.', 'feminine active participle of 3803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7799}/[H7797]', 'lemma', 'heb', 'שׁוּשַׁן', '["shûwshan"]', '["<the> lily of","Shoshannim","[are] lilies","a lily","lili[es]","lilies","shushan-"]', '["n-m"]', 'a lily (from its whiteness), as a flower of architectural ornament; also a (straight) trumpet (from the tubular shape) lily, Shoshannim.', 'or שׁוֹשָׁן; or שֹׁשָׁן; and (feminine) שׁוֹשַׁנָּה; from 7797;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0197J}/[H481]', 'inflected', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["in the/ porch"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H5980}/[H6004]', 'inflected', 'heb', 'עֻמָּה', '["ʻummâh"]', '["from/ to/ near"]', '["n-f"]', 'conjunction, i.e. society; mostly adverb or preposition (with prepositional prefix), near, beside, along with (over) against, at, beside, hard by, in points.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H0990I>', 'inflected', 'heb', 'הבטן', '["ha./Be.ten"]', '["the/ bulge"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7416}/[H7426]', 'inflected', 'heb', 'רִמּוֹן', '["rimmôwn"]', '["and/ the/ pomegranate","and/ the/ pomegranates"]', '["n-m"]', 'a pomegranate, the tree (from its upright growth) or the fruit (also an artificial ornament) pomegranate.', 'or רִמֹּן; from 7426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0197J}/[H481]', 'inflected', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["[was] to/ [the] porch of","of/ [the] porch of","to/ [the] porch of"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1964G}/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["the/ temple"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3199H}/[H3559]', 'lemma', 'heb', 'יָכִין', '["Yâkîyn"]', '["Jakin"]', '["n-pr"]', 'Jakin, the name of three Israelites and of a temple pillar Jachin.', 'from 3559; he (or it) will establish;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8042H}/[H8040]', 'inflected', 'heb', 'שְׂמָאלִי', '["sᵉmâʼlîy"]', '["<the>/ north","the/ north [one]"]', '["a"]', 'situated on the left side left.', 'from 8040;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8193I}/H9023/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["from/ lip/ its"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5696>', 'opaque', 'heb', 'עָגֹל', '["ʻâgôl"]', '["[was] round","round"]', '["a"]', 'circular round.', 'or עָגוֹל; from an unused root meaning to revolve,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6957B}/[H6960]', 'inflected', 'heb', 'קַו', '["qav"]', '["and/ a measuring-line"]', '["n-m"]', 'a cord (as connecting), especially for measuring; figuratively, a rule; also a rim, a musical string or accord line. Compare 6978.', 'or קָו; from 6960 (compare 6961);');
