INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3332H}/[H3332]', 'lemma', 'heb', 'יָצַק', '["yâtsaq"]', '["[they were] cast","[was] cast","cast","hard"]', '["v"]', 'properly, to pour out (transitive or intransitive); by implication, to melt or cast as metal; by extension, to place firmly, to stiffen or grow hard cast, cleave fast, be (as) firm, grow, be hard, lay out, molten, overflow, pour (out), run out, set down, stedfast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3333}/H9023/[H3332]', 'inflected', 'heb', 'יְצֻקָה', '["yᵉtsuqâh"]', '["in/ casting/ its"]', '["n-f"]', 'poured out, i.e. run into a mould when it was cast.', 'passive participle feminine of 3332;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0268}/H9028/[H299]', 'inflected', 'heb', 'אָחוֹר', '["ʼâchôwr"]', '["backs/ their","hindquarters/ their"]', '["n-m"]', 'the hinder part; hence (adverb) behind, backward; also (as facing north) the West after(-ward), back (part, -side, -ward), hereafter, (be-) hind(-er part), time to come, without.', 'or (shortened) אָחֹר ; from 299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5672}/H9023/[H5666]', 'inflected', 'heb', 'עֲבִי', '["ʻăbîy"]', '["and/ thickness/ its"]', '["n-m"]', 'density, i.e. depth or width thick(-ness). Compare 5645.', 'or עֳבִי]; from 5666;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2947}/[H2946]', 'lemma', 'heb', 'טֵפַח', '["ṭêphach"]', '["[was] a hand breadth","handbreadths"]', '["n-m"]', 'a spread of the hand, i.e. a palm-breadth (not ''span'' of the fingers); architecturally, a corbel (as a supporting palm) coping, hand-breadth.', 'from 2946;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8193I}/H9023/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["and/ lip/ its"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1324}/[H1327]', 'lemma', 'heb', 'בַּת', '["bath"]', '["a bath","bath[s]","baths"]', '["n-m"]', 'a bath or Hebrew measure (as a means of division) of liquids bath.', 'probably from the same as 1327;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3557}\/[H3557]', 'inflected', 'heb', 'כּוּל', '["kûwl"]', '["it contained"]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4350}/[H4349]', 'inflected', 'heb', 'מְכוֹנָה', '["mᵉkôwnâh"]', '["the/ stand","the/ stands"]', '["n-f"]', 'a pedestal, also a spot base.', 'or מְכֹנָה; feminine of 4349;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4526}/[H5462]', 'inflected', 'heb', 'מִסְגֶּרֶת', '["miçgereth"]', '["and/ rims"]', '["n-f"]', 'something enclosing, i.e. a margin (of a region, of a panel); concretely, a stronghold border, close place, hole.', 'from 5462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7948}/[H7947]', 'inflected', 'heb', 'שָׁלָב', '["shâlâb"]', '["the/ cross bars"]', '["n-m"]', 'a spacer or raised interval, i.e. the stile in a frame or panel ledge.', 'from 7947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3653}/[H3651]', 'lemma', 'heb', 'כֵּן', '["kên"]', '["[the] base of","a base"]', '["n-m"]', 'a stand, i.e. pedestal or station base, estate, foot, office, place, well.', 'the same as 3651, used as a noun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0738A}/[H717]', 'inflected', 'heb', 'אֲרִי', '["ʼărîy"]', '["to/ [the] lions"]', '["n-m"]', 'a lion (young) lion, pierce (from the margin).', 'or (prolonged) אַרְיֵה; from 717 (in the sense of violence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1241}/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["and/ to the/ ox[en]"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3914}/[H3880]', 'lemma', 'heb', 'לֹיָה', '["lôyâh"]', '["garlands"]', '["n-f"]', 'a wreath addition.', 'a form of 3880;');
