INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4526}/[H5462]', 'inflected', 'heb', 'מִסְגֶּרֶת', '["miçgereth"]', '["to the/ rims"]', '["n-f"]', 'something enclosing, i.e. a margin (of a region, of a panel); concretely, a stronghold border, close place, hole.', 'from 5462;');
