INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4639G}/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["and/ [are] [the] work of","and/ [the] work of","and/ [were] [the] work of"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1354>/H9028', 'inflected', 'heb', 'וגביהם', '["ve./ga.be./Hem","ve./ga.bei./Hem","ve./ga.bo.Ta/m"]', '["and/ backs/ their","and/ rims/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2839}/H9028/[H2836]', 'inflected', 'heb', 'חִשֻּׁק', '["chishshuq"]', '["and/ spokes/ their"]', '["n-m"]', 'conjoined, i.e. a wheel-spoke or rod connecting the hub with the rim felloe.', 'from 2836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2840>/H9028', 'inflected', 'heb', 'וחשריהם', '["ve./chi.shu.rei./Hem"]', '["and/ hubs/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3802>/H9024', 'opaque', 'heb', 'כָּתֵף', '["kâthêph"]', '["supports/ its"]', '["n-f"]', 'the shoulder (proper, i.e. upper end of the arm; as being the spot where the garments hang); figuratively, side-piece or lateral projection of anything arm, corner, shoulder(-piece), side, undersetter.', 'from an unused root meaning to clothe;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H7218I>', 'inflected', 'heb', 'ובראש', '["u./ve./Rosh"]', '["and/ at/ [the] top of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4526}/H9024/[H5462]', 'inflected', 'heb', 'מִסְגֶּרֶת', '["miçgereth"]', '["and/ rims/ its"]', '["n-f"]', 'something enclosing, i.e. a margin (of a region, of a panel); concretely, a stronghold border, close place, hole.', 'from 5462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4526}/H9024/[H5462]', 'inflected', 'heb', 'מִסְגֶּרֶת', '["miçgereth"]', '["rims/ its"]', '["n-f"]', 'something enclosing, i.e. a margin (of a region, of a panel); concretely, a stronghold border, close place, hole.', 'from 5462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4629H}/[H6168]', 'inflected', 'heb', 'מַעֲרֶה', '["maʻăreh"]', '["according to/ [the] clear space of"]', '["n-m"]', 'a nude place, i.e. a common meadows.', 'from 6168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3914}/[H3880]', 'inflected', 'heb', 'לֹיָה', '["lôyâh"]', '["and/ garlands"]', '["n-f"]', 'a wreath addition.', 'a form of 3880;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7095}/[H7094]', 'lemma', 'heb', 'קֶצֶב', '["qetseb"]', '["a shape"]', '["n-m"]', 'shape (as if cut out); base (as if there cut off) bottom, size.', 'from 7094;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3605}/H9029\/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["for/ all of/ them"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6235}/[H6237]', 'inflected', 'heb', 'עֶשֶׂר', '["ʻeser"]', '["for/ [the] ten"]', '["n"]', 'ten (as an accumulation to the extent of the digits) ten, (fif-, seven-) teen.', 'masculine of term עֲשָׂרָה; from 6237;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8040G}/H9023/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["from/ left/ its"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H3802>', 'inflected', 'heb', 'מכתף', '["mi./Ke.tef"]', '["from/ [the] side of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5045H>\', 'opaque', 'heb', 'נֶגֶב', '["negeb"]', '["[the] south"]', '["n-m"]', 'the south (from its drought); specifically, the Negeb or southern district of Judah, occasionally, Egypt (as south to Palestine) south (country, side, -ward).', 'from an unused root meaning to be parched;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1543}/[H1556]', 'inflected', 'heb', 'גֻּלָּה', '["gullâh"]', '["and/ [the] bowls of","and/ a bowl"]', '["n-f"]', 'a fountain, bowl or globe (all as round) bowl, pommel, spring.', 'feminine from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7639}/[H7638]', 'inflected', 'heb', 'שְׂבָכָה', '["sᵉbâkâh"]', '["and/ the/ networks"]', '["n-f"]', 'a net-work, i.e. (in hunting) a snare, (in architecture) a ballustrade; also a reticulated ornament to a pillar checker, lattice, network, snare, wreath(-enwork).', 'feminine of 7638;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7639}/[H7638]', 'inflected', 'heb', 'שְׂבָכָה', '["sᵉbâkâh"]', '["[belonged] to the/ network","for the/ network"]', '["n-f"]', 'a net-work, i.e. (in hunting) a snare, (in architecture) a ballustrade; also a reticulated ornament to a pillar checker, lattice, network, snare, wreath(-enwork).', 'feminine of 7638;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3603H}/[H3769]', 'inflected', 'heb', 'כִּכָּר', '["kikkâr"]', '["for/ two talents","in/ [the] valley of"]', '["n-f"]', 'a circle, i.e. (by implication) a circumjacent tract or region, especially the Ghor or valley of the Jordan; also a (round) loaf; also a talent (or large [round] coin) loaf, morsel, piece, plain, talent.', 'from 3769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3332H}/H9038/[H3332]', 'inflected', 'heb', 'יָצַק', '["yâtsaq"]', '["he cast/ them"]', '["v"]', 'properly, to pour out (transitive or intransitive); by implication, to melt or cast as metal; by extension, to place firmly, to stiffen or grow hard cast, cleave fast, be (as) firm, grow, be hard, lay out, molten, overflow, pour (out), run out, set down, stedfast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4568}/[H5666]', 'inflected', 'heb', 'מַעֲבֶה', '["maʻăbeh"]', '["in/ [the] mold of"]', '["n-m"]', 'properly, compact (part of soil), i.e. loam clay.', 'from 5666;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6440G}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["the/ presence"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6525}/[H6524]', 'inflected', 'heb', 'פֶּרַח', '["perach"]', '["and/ the/ blossom"]', '["n-m"]', 'a calyx (natural or artificial); generally, bloom blossom, bud, flower.', 'from 6524;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5216A}/[H5214]', 'inflected', 'heb', 'נִיר', '["nîyr"]', '["and/ the/ lamps"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4457}/[H3947]', 'inflected', 'heb', 'מֶלְקָח', '["melqâch"]', '["and/ the/ tongs"]', '["n-m"]', '(only in dual) tweezers snuffers, tongs.', 'or מַלְקָח; from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5592A}/[H5605]', 'inflected', 'heb', 'סַף', '["çaph"]', '["and/ the/ basins"]', '["n-m"]', 'a vestibule (as a limit); also a dish (for holding blood or wine) bason, bowl, cup, door (post), gate, post, threshold.', 'from 5605, in its original sense of containing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4212}/[H2168]', 'inflected', 'heb', 'מְזַמְּרָה', '["mᵉzammᵉrâh"]', '["and/ the/ snuffers"]', '["n-f"]', 'a tweezer (only in the plural) snuffers.', 'from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4219}/[H2236]', 'inflected', 'heb', 'מִזְרָק', '["mizrâq"]', '["and/ the/ bowls"]', '["n-m"]', 'a bowl (as if for sprinkling) bason, bowl.', 'from 2236;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3709I}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["and/ the/ pans"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4289}/[H4288]', 'inflected', 'heb', 'מַחְתָּה', '["machtâh"]', '["and/ the/ fire-pans"]', '["n-f"]', 'a pan for live coals censer, firepan, snuffdish.', 'the same as 4288 in the sense of removal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H6596>', 'inflected', 'heb', 'והפתות', '["ve./ha./po.Tot"]', '["and/ the/ sockets"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1817C}/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["[belonged] to the/ doors","[belonged] to/ a door","for/ [the] doors of"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1964G}/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["of the/ temple"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2091>\', 'opaque', 'heb', 'זָהָב', '["zâhâb"]', '["gold"]', '["n-m"]', 'gold, figuratively, something gold-colored (i.e. yellow), as oil, a clear sky gold(-en), fair weather.', 'from an unused root meaning to shimmer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0214}/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["in/ [the] treasuries of","in/ storehouses"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0388}/[H386]', 'inflected', 'heb', 'אֵיתָנִים', '["ʼÊythânîym"]', '["<the>/ Ethanim"]', '["n-pr-m"]', 'Ethanim, the name of a month Ethanim.', 'plural of 386; always with the article; the permanent brooks;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1687}/[H1696]', 'lemma', 'heb', 'דְּבִיר', '["dᵉbîyr"]', '["[the] innermost room of"]', '["n-m"]', 'the shrine or innermost part of the sanctuary oracle.', 'or (shortened) דְּבִר; from 1696 (apparently in the sense of oracle);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6944H}/[H6942]', 'lemma', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["[is] [the] holy place of","[the] holy place of","a holy place of","holy places"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6205}/[H6201]', 'inflected', 'heb', 'עֲרָפֶל', '["ʻărâphel"]', '["in <the>/ thick darkness"]', '["n-m"]', 'gloom (as of a lowering sky) (gross, thick) dark (cloud, -ness).', 'probably from 6201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2073}/[H2082]', 'lemma', 'heb', 'זְבוּל', '["zᵉbûwl"]', '["loftiness"]', '["n-m"]', 'a residence dwell in, dwelling, habitation.', 'or זְבֻל; from 2082;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3027H}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ by/ hands/ his","and/ in/ hand/ his","and/ with/ hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697J}/H9023/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["word/ his"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3027H}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ [are] in/ hand/ your","and/ by/ hand/ your","and/ with/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H6440G}/H9020/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ to/ before/ me"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3557}/H9031/[H3557]', 'inflected', 'heb', 'כּוּל', '["kûwl"]', '["he will sustain/ you","they contain/ you","they will contain/ you"]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8605}/[H6419]', 'lemma', 'heb', 'תְּפִלָּה', '["tᵉphillâh"]', '["[am] prayer","[the] prayer of","[the] prayers of","a prayer","prayer","prayer of"]', '["n-f"]', 'intercession, supplication; by implication, a hymn prayer.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8467}/H9023/[H2603]', 'inflected', 'heb', 'תְּחִנָּה', '["tᵉchinnâh"]', '["supplication/ his"]', '["n-f"]', 'graciousness; causatively, entreaty favour, grace, supplication.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7440}/[H7442]', 'inflected', 'heb', 'רִנָּה', '["rinnâh"]', '["the/ cry","the/ cry of entreaty"]', '["n-f"]', 'properly, a creaking (or shrill sound), i.e. shout (of joy or grief) cry, gladness, joy, proclamation, rejoicing, shouting, sing(-ing), triumph.', 'from 7442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3427}/H9041/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["dwelling/ you","dwelling/ your"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5378}/[H5377]', 'inflected', 'heb', 'נָשָׁא', '["nâshâʼ"]', '["and/ he will impose"]', '["v"]', 'to lend on interest; by implication, to dun for debt × debt, exact, giver of usury.', 'a primitive root (perhaps identical with 5377, through the idea of imposition);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0422}/H9033/[H422]', 'inflected', 'heb', 'אָלָה', '["ʼâlâh"]', '["to/ put under an oath/ him"]', '["v"]', 'properly, to adjure, i.e. (usually in a bad sense) imprecate adjure, curse, swear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7561}/[H7561]', 'inflected', 'heb', 'רָשַׁע', '["râshaʻ"]', '["to/ act wickedly","to/ condemn as guilty"]', '["v"]', 'to be (causatively, do or declare) wrong; by implication, to disturb, violate condemn, make trouble, vex, be (commit, deal, depart, do) wicked(-ly, -ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6663}/[H6663]', 'inflected', 'heb', 'צָדַק', '["tsâdaq"]', '["and/ to/ declare righteous","and/ to/ vindicate"]', '["v"]', 'to be (causatively, make) right (in a moral or forensic sense) cleanse, clear self, (be, do) just(-ice, -ify, -ify self), (be turn to) righteous(-ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6666}/H9023\/[H6663]', 'inflected', 'heb', 'צְדָקָה', '["tsᵉdâqâh"]', '["according to/ righteousness/ his"]', '["n-f"]', 'rightness (abstractly), subjectively (rectitude), objectively (justice), morally (virtue) or figuratively (prosperity) justice, moderately, right(-eous) (act, -ly, -ness).', 'from 6663;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5062}/[H5062]', 'inflected', 'heb', 'נָגַף', '["nâgaph"]', '["when/ are defeated"]', '["v"]', 'to push, gore, defeat, stub (the toe), inflict (a disease) beat, dash, hurt, plague, slay, smite (down), strike, stumble, × surely, put to the worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2403B}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["<into>/ [the] sin of","<into>/ sin","<to>/ [the] sin of","[is] <to>/ sin","for/ sin"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725G}/H9038/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I will bring back/ them","and/ I will restore/ them","and/ they returned/ them","and/ you will bring back/ them"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0001G}/H9028\/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["to/ ancestors/ their"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6113}/[H6113]', 'inflected', 'heb', 'עָצָר', '["ʻâtsâr"]', '["when/ are shut up"]', '["v"]', 'to inclose; by analogy, to hold back; also to maintain, rule, assemble × be able, close up, detain, fast, keep (self close, still), prevail, recover, refrain, × reign, restrain, retain, shut (up), slack, stay, stop, withhold (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2403B}/H9028/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ from/ sin/ their"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725O}/H9013/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["they will turn back/ !"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6031B}/H9038/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["you will afflict/ them"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3384B}/H9038/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["you will direct/ them","you will teach/ them"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5159}\/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["for/ an inheritance","to/ an inheritance"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7711B}/[H7710]', 'lemma', 'heb', 'שְׁדֵפָה', '["shᵉdêphâh"]', '["blight"]', '["n-f n-m"]', 'blight blasted(-ing).', 'or שִׁדָּפוֹן; from 7710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3420}/[H3418]', 'lemma', 'heb', 'יֵרָקוֹן', '["yêrâqôwn"]', '["mildew"]', '["n-m"]', 'paleness, whether of persons (from fright), or of plants (from drought) greenish, yellow.', 'from 3418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2625}/[H2628]', 'lemma', 'heb', 'חָסִיל', '["châçîyl"]', '["locust[s]"]', '["n-m"]', 'the ravager, i.e. a locust caterpillar.', 'from 2628;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8179G}/H9023/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["gates/ his","gates/ its"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3372G}/H9031/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["people will fear/ you","they may fear/ you","they will fear/ you"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5971A}/H9021/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["[is] one of/ people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2220}/H9021/[H2232]', 'inflected', 'heb', 'זְרוֹעַ', '["zᵉrôwaʻ"]', '["and/ arm/ your"]', '["n-f"]', 'the arm (as stretched out), or (of animals) the foreleg; figuratively, force arm, help, mighty, power, shoulder, strength.', 'or (shortened) זְרֹעַ; and (feminine) זְרוֹעָה; or זְרֹעָה; from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8605}/H9028/[H6419]', 'inflected', 'heb', 'תְּפִלָּה', '["tᵉphillâh"]', '["prayer/ their"]', '["n-f"]', 'intercession, supplication; by implication, a hymn prayer.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8467}/H9028/[H2603]', 'inflected', 'heb', 'תְּחִנָּה', '["tᵉchinnâh"]', '["supplication/ their","supplications/ their"]', '["n-f"]', 'graciousness; causatively, entreaty favour, grace, supplication.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941H}/H9028/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["justice/ their","sentence/ their"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7617}/H9038/[H7617]', 'inflected', 'heb', 'שָׁבָה', '["shâbâh"]', '["and/ he took captive/ them","and/ he will take captive/ them","and/ they will take captive/ them"]', '["v"]', 'to transport into captivity (bring away, carry, carry away, lead, lead away, take) captive(-s), drive (take) away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7617}/H9038/[H7617]', 'inflected', 'heb', 'שָׁבָה', '["shâbâh"]', '["captors/ their"]', '["v"]', 'to transport into captivity (bring away, carry, carry away, lead, lead away, take) captive(-s), drive (take) away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0341}/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["the/ enemy"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725O}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ he turned away","and/ he will turn back","and/ it will return","and/ she has turned away","and/ they repented","and/ they returned","and/ they turned back","and/ they will repent","and/ they will return","and/ they will turn","and/ you turned back","and/ you will turn back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5753B}/[H5753]', 'inflected', 'heb', 'עָוָה', '["ʻâvâh"]', '["and/ we have committed iniquity","and/ we have done wrong"]', '["v"]', 'to crook, literally or figuratively do amiss, bow down, make crooked, commit iniquity, pervert, (do) perverse(-ly), trouble, × turn, do wickedly, do wrong.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6586}/[H6586]', 'lemma', 'heb', 'פָּשַׁע', '["pâshaʻ"]', '["O rebels","he has rebelled","he will transgress","it rebelled","rebels","they have rebelled","they have transgressed","they rebelled","they transgressed","transgressed","transgressors","we have transgressed","you have rebelled","you have transgressed"]', '["v"]', 'to break away (from just authority), i.e. trespass, apostatize, quarrel offend, rebel, revolt, transgress(-ion, -or).', 'a primitive root (identical with through the idea of expansion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7356B}/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["<to>/ compassion<s>","into/ [objects of] compassion","into/ compassion<s>","to/ compassion<s>"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7355}/H9038/[H7355]', 'inflected', 'heb', 'רָחַם', '["râcham"]', '["and/ I will have compassion on/ them","and/ he had compassion on/ them","and/ they will have compassion on/ them"]', '["v"]', 'to fondle; by implication, to love, especially to compassionate have compassion (on, upon), love, (find, have, obtain, shew) mercy(-iful, on, upon), (have) pity, Ruhamah, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3564>', 'opaque', 'heb', 'כּוּר', '["kûwr"]', '["[the] furnace of","a furnace"]', '["n-m"]', 'a pot or furnace (as if excavated) furnace. Compare 3600.', 'from an unused root meaning properly, to dig through;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7121G}/H9048/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["call out/ they","calling/ they"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0914}/H9038/[H914]', 'inflected', 'heb', 'בָּדַל', '["bâdal"]', '["you have separated/ them"]', '["v"]', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3069}\/[H3068]', 'inflected', 'heb', 'יְהֹוִה', '["Yᵉhôvih"]', '["Yahweh"]', '["n-pr"]', 'God.', 'a variation of 3068 [used after 136, and pronounced by Jews as 430, in order to prevent the repetition of the same sound, since they elsewhere pronounce 3068 as 136]');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8467}/[H2603]', 'inflected', 'heb', 'תְּחִנָּה', '["tᵉchinnâh"]', '["and/ the/ supplication"]', '["n-f"]', 'graciousness; causatively, entreaty favour, grace, supplication.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3766}/[H3766]', 'inflected', 'heb', 'כָּרַע', '["kâraʻ"]', '["from/ bowing down"]', '["v"]', 'to bend the knee; by implication, to sink, to prostrate bow (down, self), bring down (low), cast down, couch, fall, feeble, kneeling, sink, smite (stoop) down, subdue, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3709G}/H9023/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["and/ palms/ his"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5971A}/H9023/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["<to>/ people/ his","for/ people/ his","to/ people/ his"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800A}/H9035/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["do you abandon?/ us","he forsake/ us","he has abandoned/ us"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2706G}/H9023/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["in/ statutes/ his"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2596}/[H2614]', 'inflected', 'heb', 'חָנַךְ', '["chânak"]', '["and/ they dedicated"]', '["v"]', 'properly, to narrow; figuratively, to initiate or discipline dedicate, train up.', 'a primitive root; (compare 2614)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3557}/[H3557]', 'inflected', 'heb', 'כּוּל', '["kûwl"]', '["for/ containing"]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2282}/[H2287]', 'inflected', 'heb', 'חַג', '["chag"]', '["the/ festival"]', '["n-m"]', 'a festival, or a victim therefor (solemn) feast (day), sacrifice, solemnity.', 'or חָג; from 2287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0935O}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["from/ Lebo"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0168H}/H9028/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["to/ tents/ their"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2837}/[H2836]', 'lemma', 'heb', 'חֵשֶׁק', '["chêsheq"]', '["[the] desire of"]', '["n-m"]', 'delight desire, pleasure.', 'from 2836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6213H}\/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["to/ do"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8605}/H9021/[H6419]', 'inflected', 'heb', 'תְּפִלָּה', '["tᵉphillâh"]', '["prayer/ your"]', '["n-f"]', 'intercession, supplication; by implication, a hymn prayer.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8467}/H9021/[H2603]', 'inflected', 'heb', 'תְּחִנָּה', '["tᵉchinnâh"]', '["supplication/ your"]', '["n-f"]', 'graciousness; causatively, entreaty favour, grace, supplication.', 'from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3820A}/H9020/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["<and>/ heart/ my","and/ heart/ my"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4941G}/H9020/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ judgments/ my"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121G}/H9026/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ descendants/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8074H}/[H8074]', 'lemma', 'heb', 'שָׁמֵם', '["shâmêm"]', '["appalled","be appalled","he will be appalled","he will devastate","it is appalled","may they be appalled","they are appalled","they have been appalled","they were appalled"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8319}/[H8319]', 'inflected', 'heb', 'שָׁרַק', '["shâraq"]', '["and/ he will hiss","and/ he will whistle"]', '["v"]', 'properly, to be shrill, i.e. to whistle or hiss (as a call or in scorn) hiss.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0430J}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["among the/ gods","on/ gods"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1551}/[H1550]', 'inflected', 'heb', 'גָּלִיל', '["Gâlîyl"]', '["<the>/ Galilee"]', '["n-pr-loc"]', 'Galil (as a special circuit) in the North of Palestine Galilee.', 'or (prolonged) גָּלִילָה; the same as 1550; a circle (with the article);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3521H}/[H3525]', 'lemma', 'heb', 'כָּבוּל', '["Kâbûwl"]', '["Cabul"]', '["n-pr-loc"]', 'Cabul, the name of two places in Palestine Cabul.', 'from the same as 3525 in the sense of limitation; sterile;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8313}/H9034/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["and/ he had burned/ it","and/ he will burn/ it","and/ they burned/ it","and/ they will burn/ it"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7964}/[H7971]', 'lemma', 'heb', 'שִׁלּוּחַ', '["shillûwach"]', '["dowri<es>","parting gifts"]', '["n-m"]', '(only in plural) a dismissal, i.e. (of a wife) divorce (especially the document); also (of a daughter) dower presents, have sent back.', 'or שִׁלֻּחַ; from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1191H}/[H1172]', 'lemma', 'heb', 'בַּעֲלָת', '["Baʻălâth"]', '["Baalath"]', '["n-pr-loc"]', 'Baalath, a place in Palestine Baalath.', 'a modification of 1172; mistressship;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8412}/[H8558]', 'lemma', 'heb', 'תַּדְמֹר', '["Tadmôr"]', '["Tadmor"]', '["n-pr-loc"]', 'Tadmor, a place near Palestine Tadmor.', 'or תַּמֹּר; (1 Kings 9:18), apparently from 8558; palm-city;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4543}/[H3664]', 'inflected', 'heb', 'מִסְכְּנָה', '["miçkᵉnâh"]', '["<the>/ storage"]', '["n-f"]', 'a magazine store(-house), treasure.', 'by transp. from 3664;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3844G}/[H3825]', 'inflected', 'heb', 'לְבָנוֹן', '["Lᵉbânôwn"]', '["and/ in <the>/ Lebanon"]', '["n-pr-loc"]', 'Lebanon, a mountain range in Palestine Lebanon.', 'from 3825; (the) white mountain (from its snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4475}/H9023/[H4474]', 'inflected', 'heb', 'מֶמְשָׁלָה', '["memshâlâh"]', '["dominion/ his","dominion<s>/ his","imperial might/ his","realm/ his"]', '["n-f"]', 'rule; also (concretely in plural) a realm or a ruler dominion, government, power, to rule.', 'feminine of 4474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1121G}/H9028/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["descendants/ their","sons/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2763A}/H9038/[H2763]', 'inflected', 'heb', 'חָרַם', '["châram"]', '["by/ totally destroying/ them","to/ totally destroy/ them"]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8269}/H9023/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["and/ leaders/ its","and/ officials/ his"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7991C}/H9023/[H7969]', 'inflected', 'heb', 'שָׁלִישׁ', '["shâlîysh"]', '["and/ officers/ his"]', '["n-m"]', 'a triple, i.e. (as a musical instrument) a triangle (or perhaps rather three-stringed lute); also (as an indefinite, great quantity) a three-fold measure (perhaps a treble ephah); also (as an officer) a general of the third rank (upward, i.e. the highest) captain, instrument of musick, (great) lord, (great) measure, prince, three (from the margin).', 'or שָׁלוֹשׁ; (1 Chronicles 11:11; 1 Chronicles 12:18), or שָׁלֹשׁ; (2 Samuel 23:13), from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6571B}/H9023\/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["and/ horsemen/ his"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0590}/[H579]', 'inflected', 'heb', 'אֳנִי', '["ʼŏnîy"]', '["and/ ship[s]"]', '["n"]', 'a ship or (collectively) a fleet galley, navy (of ships).', 'probably from 579 (in the sense of conveyance);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0359B}/[H352]', 'lemma', 'heb', 'אֵילוֹת', '["ʼÊylôwth"]', '["Elath"]', '["n-pr-loc"]', 'Eloth or Elath, a place on the Red Sea Elath, Eloth.', 'or אֵילַת ; from 352; trees or a grove (i.e. palms);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0590}/[H579]', 'inflected', 'heb', 'אֳנִי', '["ʼŏnîy"]', '["in the/ ship[s]"]', '["n"]', 'a ship or (collectively) a fleet galley, navy (of ships).', 'probably from 579 (in the sense of conveyance);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0211H>/H9011', 'opaque', 'heb', 'אוֹפִיר', '["ʼÔwphîyr"]', '["Ophir/ towards"]', '["n-pr-m"]', 'Ophir, the name of a son of Joktan, and of a gold region in the East Ophir.', 'or (shortened) אֹפִיר; and אוֹפִר; of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4436G}/[H4428]', 'inflected', 'heb', 'מַלְכָּה', '["malkâh"]', '["and/ [the] queen of"]', '["n-f"]', 'a queen queen.', 'feminine of 4428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7614J>', 'opaque', 'heb', 'שְׁבָא', '["Shᵉbâʼ"]', '["Sheba"]', '["n-pr-m n-pr-loc"]', 'Sheba, the name of three early progenitors of tribes and of an Ethiopian district Sheba, Sabeans.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5254G}/H9033/[H5254]', 'inflected', 'heb', 'נָסָה', '["nâçâh"]', '["to/ put to [the] test/ him"]', '["v"]', 'to test; by implication, to attempt adventure, assay, prove, tempt, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3389}/H9011/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["Jerusalem/ towards"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2428H}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["with/ a retinue"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3824}/H9024/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["heart/ her"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697I}/H9024/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["words/ her"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4436G}/[H4428]', 'lemma', 'heb', 'מַלְכָּה', '["malkâh"]', '["[the] queen of"]', '["n-f"]', 'a queen queen.', 'feminine of 4428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1004P}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ the/ house"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3978}/[H398]', 'inflected', 'heb', 'מַאֲכָל', '["maʼăkâl"]', '["and/ [the] food of","and/ food"]', '["n-m"]', 'an eatable (includ. provender, flesh and fruit) food, fruit, (bake-)meat(-s), victual.', 'from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7979}/H9023/[H7971]', 'inflected', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["table/ his"]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4612}/[H5975]', 'inflected', 'heb', 'מַעֲמָד', '["maʻămâd"]', '["and/ [the] standing of"]', '["n-m"]', '(figuratively) a position attendance, office, place, state.', 'from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4403}/H9028/[H3847]', 'inflected', 'heb', 'מַלְבּוּשׁ', '["malbûwsh"]', '["and/ clothes/ their"]', '["n-m"]', 'a garment, or (collectively) clothing apparel, raiment, vestment.', 'or מַלְבֻּשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4945A}/H9023/[H8248]', 'inflected', 'heb', 'מַשְׁקֶה', '["mashqeh"]', '["and/ cup-bearers/ his"]', '["n-m"]', 'properly, causing to drink, i.e. a butler; by implication (intransitively), drink (itself); figuratively, a well-watered region butler(-ship), cupbearer, drink(-ing), fat pasture, watered.', 'from 8248;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5930A}/H9023/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["and/ burnt offering[s]/ his"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2451}/H9021/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["skill/ your","wisdom/ your"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1697G}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<to> the/ words","<to>/ a word","[belong] to/ words of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0835}/[H833]', 'lemma', 'heb', 'אֶשֶׁר', '["ʼesher"]', '["how blessed!"]', '["n-m"]', 'happiness; only in masculine plural construction as interjection, how happy! blessed, happy.', 'from 833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0582}/H9021/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["[are] people/ your"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5414H}/H9031/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["to/ put/ you"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0157G}/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["because/ loves"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760A}/H9031/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ I will make/ you","and/ he has appointed/ you"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1314}/[H1313]', 'inflected', 'heb', 'בֶּשֶׂם', '["besem"]', '["like the/ spice"]', '["n-m"]', 'fragrance; by implication, spicery; also the balsam plant smell, spice, sweet (odour).', 'or בֹּשֶׂם; from the same as 1313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0590}/[H579]', 'lemma', 'heb', 'אֳנִי', '["ʼŏnîy"]', '["[the] ship[s] of","a ship of"]', '["n"]', 'a ship or (collectively) a fleet galley, navy (of ships).', 'probably from 579 (in the sense of conveyance);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H0211H>', 'inflected', 'heb', 'מאופיר', '["me./''o.Fir"]', '["from/ Ophir"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0484}/[H484]', 'lemma', 'heb', 'אַלְמֻגִּים', '["ʼalmuggîym"]', '["almug<s>"]', '["n-m"]', 'almug (i.e. probably sandle-wood) sticks almug trees. Compare 418.', 'probably of foreign derivation (used thus only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0484}/[H484]', 'inflected', 'heb', 'אַלְמֻגִּים', '["ʼalmuggîym"]', '["the/ almug<s>"]', '["n-m"]', 'almug (i.e. probably sandle-wood) sticks almug trees. Compare 418.', 'probably of foreign derivation (used thus only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4552}/[H5582]', 'lemma', 'heb', 'מִסְעָד', '["miçʻâd"]', '["support[s]"]', '["n-m"]', 'a balustrade (for stairs) pillar.', ''' from 5582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1004P}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ for/ [the] house of","and/ to/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5035B}/[H5034]', 'inflected', 'heb', 'נֶבֶל', '["nebel"]', '["and/ lyre","and/ lyres"]', '["n-m"]', 'a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol.', 'or נֵבֶל; from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4436G}/[H4428]', 'inflected', 'heb', 'מַלְכָּה', '["malkâh"]', '["to/ [the] queen of"]', '["n-f"]', 'a queen queen.', 'feminine of 4428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2656}/H9024/[H2654]', 'inflected', 'heb', 'חֵפֶץ', '["chêphets"]', '["desire/ her"]', '["n-m"]', 'pleasure; hence (abstractly) desire; concretely, a valuable thing; hence (by extension) a matter (as something in mind) acceptable, delight(-some), desire, things desired, matter, pleasant(-ure), purpose, willingly.', 'from 2654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3027H}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["according to/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0776G>/H9024', 'inflected', 'heb', 'לארצה', '["le./''ar.Tza/h"]', '["to/ own land/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5650}/H9024\/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["and/ servants/ her"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4536}/[H5503]', 'inflected', 'heb', 'מִסְחָר', '["miçchâr"]', '["and/ [the] merchandise of"]', '["n-m"]', 'trade traffic.', 'from 5503;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7402}/[H7402]', 'inflected', 'heb', 'רָכַל', '["râkal"]', '["the/ traders"]', '["v"]', 'to travel for trading (spice) merchant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6152B}/[H6150]', 'inflected', 'heb', 'עֲרָב', '["ʻĂrâb"]', '["the/ Arab[s]"]', '["n-m"]', 'Arab (i.e. Arabia), a country East of Palestine Arabia.', 'or עֲרַב; from 6150 in the figurative sense of sterility;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6346>', 'inflected', 'heb', 'ופחוות', '["u./fa.Chot","u./fa.cha.Vot"]', '["and/ [the] governors of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6793C}/[H6791]', 'lemma', 'heb', 'צִנָּה', '["tsinnâh"]', '["[is] a shield","a body shield","body shield","body shield[s]","body shields","shield"]', '["n-f"]', 'a hook (as pointed); also a (large) shield (as if guarding by prickliness); also cold (as piercing) buckler, cold, hook, shield, target.', 'feminine of 6791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7820}/[H7819]', 'lemma', 'heb', 'שָׁחַט', '["shâchaṭ"]', '["beaten"]', '["v"]', 'to hammer out beat.', 'a primitive root (identical with 7819 through the idea of striking);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4488}/[H4487]', 'lemma', 'heb', 'מָנֶה', '["mâneh"]', '["minas"]', '["n-m"]', 'properly, a fixed weight or measured amount, i.e. (techn.) a maneh or mina maneh, pound.', 'from 4487;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4043}/[H1598]', 'inflected', 'heb', 'מָגֵן', '["mâgên"]', '["<the>/ shield[s]","the/ shield","the/ shields"]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3844J}\/[H3825]', 'inflected', 'heb', 'לְבָנוֹן', '["Lᵉbânôwn"]', '["<the>/ Lebanon"]', '["n-pr-loc"]', 'Lebanon, a mountain range in Palestine Lebanon.', 'from 3825; (the) white mountain (from its snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8127H}/[H8150]', 'lemma', 'heb', 'שֵׁן', '["shên"]', '["ivory"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6338}/[H6338]', 'lemma', 'heb', 'פָּזַז', '["pâzaz"]', '["refined"]', '["v"]', 'to refine (gold) best (gold).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4609B}/[H4608]', 'lemma', 'heb', 'מַעֲלָה', '["maʻălâh"]', '["[the] steps of","steps"]', '["n-f"]', 'elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story.', 'feminine of 4608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3678G}/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["[belonged] to the/ throne","to the/ throne","to/ a throne","to/ throne"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7218I>', 'inflected', 'heb', 'וראש', '["ve./rosh"]', '["and/ a top"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7675}/[H3427]', 'inflected', 'heb', 'שֶׁבֶת', '["shebeth"]', '["the/ sitting"]', '["n-f"]', 'properly, session; but used also concretely, an abode or locality place, seat. Compare 3429.', 'infinitive of 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3027G}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[is] the/ hand","the/ hands","the/ pairs of hands"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4609B}/[H4608]', 'inflected', 'heb', 'מַעֲלָה', '["maʻălâh"]', '["the/ ascents","the/ going up","the/ steps"]', '["n-f"]', 'elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story.', 'feminine of 4608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3972}/[H3971]', 'inflected', 'heb', 'מְאוּמָה', '["mᵉʼûwmâh"]', '["to/ anything"]', '["x"]', 'properly, a speck or point, i.e. (by implication) something; with negative, nothing fault, no(-ught), ought, somewhat, any (no-)thing.', 'apparently a form of 3971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8659H}/[H8658]', 'lemma', 'heb', 'תַּרְשִׁישׁ', '["Tarshîysh"]', '["Tarshish"]', '["n-pr-m n-pr-loc"]', 'Tarshish, a place on the Mediterranean, hence, the ephithet of a merchant vessel (as if for or from that port); also the name of a Persian and of an Israelite Tarshish, Tharshish.', 'probably the same as 8658 (as the region of the stone, or the reverse);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8143}/[H8127]', 'lemma', 'heb', 'שֶׁנְהַבִּים', '["shenhabbîym"]', '["ivori<es>"]', '["n-m"]', 'probably, tooth of elephants, i.e. ivory tusk ivory.', 'from 8127 and the plural apparently of a foreign word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6971>', 'inflected', 'heb', 'וקופים', '["ve./ko.Fim"]', '["and/ monkeys"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8500}/[H8500]', 'inflected', 'heb', 'תֻּכִּי', '["tukkîy"]', '["and/ apes"]', '["n-m"]', 'probably of foreign derivation; some imported creature, probably a peacock peacock.', 'or תּוּכִּי;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6239}/[H6238]', 'inflected', 'heb', 'עֹשֶׁר', '["ʻôsher"]', '["to/ wealth"]', '["n-m"]', 'wealth × far (richer), riches.', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2451}/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["and/ to/ wisdom"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2451}/H9023/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["wisdom/ his"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4503H>/H9023', 'opaque', 'heb', 'מִנְחָה', '["minchâh"]', '["gift/ his"]', '["n-f"]', 'a donation; euphemistically, tribute; specifically a sacrificial offering (usually bloodless and voluntary) gift, oblation, (meat) offering, present, sacrifice.', 'from an unused root meaning to apportion, i.e. bestow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5402}/[H5401]', 'inflected', 'heb', 'נֶשֶׁק', '["nesheq"]', '["and/ weaponry"]', '["n-m"]', 'military equipment, i.e. (collectively) arms (offensive or defensive), or (concretely) an arsenal armed men, armour(-y), battle, harness, weapon.', 'or נֵשֶׁק; from 5401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6505}/[H6504]', 'inflected', 'heb', 'פֶּרֶד', '["pered"]', '["and/ mule","and/ mules"]', '["n-m"]', 'a mule (perhaps from his lonely habits) mule.', 'from 6504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H8256>', 'inflected', 'heb', 'כשקמים', '["ka./shik.Mim"]', '["like the/ sycamores"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4161}/[H3318]', 'inflected', 'heb', 'מוֹצָא', '["môwtsâʼ"]', '["and/ [the] export of","and/ [the] utterance of","and/ springs of"]', '["n-m"]', 'a going forth, i.e. (the act) an egress, or (the place) an exit; hence, a source or product; specifically, dawn, the rising of the sun (the East), exportation, utterance, a gate, a fountain, a mine, a meadow (as producing grass) brought out, bud, that which came out, east, going forth, goings out, that which (thing that) is gone out, outgoing, proceeded out, spring, vein, (water-) course (springs).', 'or מֹצָאxlit môtsâ corrected to môtsâʼ; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5483M>', 'inflected', 'heb', 'הסוסים', '["Ha./sus","ha./Sus","ha./su.Sim"]', '["<the>/ horse","<the>/ horses","O/ horses","the/ horse","the/ horse[s]","the/ horses"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4723A}/[H6960]', 'inflected', 'heb', 'מִקְוֶה', '["miqveh"]', '["and/ from/ Que"]', '["n-pr-m n-m"]', 'something waited for, i.e. confidence (objective or subjective); also a collection, i.e. (of water) a pond, or (of men and horses) a caravan or drove abiding, gathering together, hope, linen yarn, plenty (of water), pool.', 'or מִקְוֵה; (1 Kings 10:28), or מִקְוֵאlemma מִּקְוֵא extra dagesh, corrected to מִקְוֵא; (2 Chronicles 1:16), from 6960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4723A}/[H6960]', 'inflected', 'heb', 'מִקְוֶה', '["miqveh"]', '["from/ Que"]', '["n-pr-m n-m"]', 'something waited for, i.e. confidence (objective or subjective); also a collection, i.e. (of water) a pond, or (of men and horses) a caravan or drove abiding, gathering together, hope, linen yarn, plenty (of water), pool.', 'or מִקְוֵה; (1 Kings 10:28), or מִקְוֵאlemma מִּקְוֵא extra dagesh, corrected to מִקְוֵא; (2 Chronicles 1:16), from 6960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8337}/[H7797]', 'inflected', 'heb', 'שֵׁשׁ', '["shêsh"]', '["for/ six","in/ six"]', '["n"]', 'six (as an overplus beyond five or the fingers of the hand); as ordinal sixth six(-teen, -teenth), sixth.', 'masculine שִׁשָּׁה; a primitive number; see 7797');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4428G}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["and/ for the/ king","and/ to the/ king","and/ to/ [the] kings of"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3318H}\/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["they brought [them] out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2850}/[H2845]', 'lemma', 'heb', 'חִתִּי', '["Chittîy"]', '["Hittite [women]","[was] a Hittite"]', '["n-m"]', 'a Chittite, or descendant of Cheth Hittite, Hittities.', 'patronymically from 2845;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0160}/[H158]', 'inflected', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["to/ love [them]"]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8282}/[H8269]', 'lemma', 'heb', 'שָׂרָה', '["sârâh"]', '["[the] noble ladies of","a princess","noble ladies"]', '["n-f"]', 'a mistress, i.e. female noble lady, princess, queen.', 'feminine of 8269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6370>', 'inflected', 'heb', 'ופילגשים', '["u./fi.lag.Shim"]', '["and/ concubines"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2209}/[H2205]', 'lemma', 'heb', 'זִקְנָה', '["ziqnâh"]', '["[the] old age of","old age"]', '["n-f"]', 'old age old (age).', 'feminine of 2205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3824}/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["like/ [the] heart of"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6253}/[H6251]', 'lemma', 'heb', 'עַשְׁתֹּרֶת', '["ʻAshtôreth"]', '["Astarte"]', '["n-pr-f"]', 'Ashtoreth, the Phoenician goddess of love (and increase) Ashtoreth.', 'probably for 6251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4445B}/[H4428]', 'lemma', 'heb', 'מַלְכָּם', '["Malkâm"]', '["Milcom"]', '["n-pr-m"]', 'Malcam or Milcom, the national idol of the Ammonites Malcham, Milcom.', 'or מִלְכּוֹם; from 4428 for 4432;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8251}/[H8262]', 'lemma', 'heb', 'שִׁקּוּץ', '["shiqqûwts"]', '["[the] abomination","[the] detestable thing of","[the] detestable things of","abomination<s>","detestable things"]', '["n-m"]', 'disgusting, i.e. filthy; especially idolatrous or (concretely) an idol abominable filth (idol, -ation), detestable (thing).', 'or שִׁקֻּץ; from 8262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H3645>', 'inflected', 'heb', 'לכמוש', '["li/kh.mo.Vosh"]', '["for/ Chemosh","to/ Chemosh"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4432}/[H4427]', 'inflected', 'heb', 'מֹלֶךְ', '["Môlek"]', '["and/ for/ Molech"]', '["n-pr-m"]', 'Molek (i.e. king), the chief deity of the Ammonites Molech. Compare 4445.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6999H}/[H6999]', 'lemma', 'heb', 'קָטַר', '["qâṭar"]', '["[are] making smoke","[were] making smoke","[who] made smoke","he made smoke","making smoke","people made smoke","she made smoke","they had made smoke","they made smoke","they make smoke","to make smoke","you made smoke","you will make smoke"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8010}/[H7965]', 'inflected', 'heb', 'שְׁלֹמֹה', '["Shᵉlômôh"]', '["<in>/ Solomon","with/ Solomon"]', '["n-pr-m"]', 'Shelomah, David''s successor Solomon.', 'from 7965; peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2708}/H9020/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["and/ statutes/ my"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3117G>/H9021', 'inflected', 'heb', 'בימיך', '["be./ya.Mei./kha"]', '["in/ days/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7167}/H9034/[H7167]', 'inflected', 'heb', 'קָרַע', '["qâraʻ"]', '["I will tear away/ it","he tore/ it"]', '["v"]', 'to rend, literally or figuratively (revile, paint the eyes, as if enlarging them) cut out, rend, × surely, tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1908I>', 'opaque', 'heb', 'הֲדַד', '["Hădad"]', '["Hadad"]', '["n-pr-m"]', 'Hadad, the name of an idol, and of several kings of Edom Hadad.', 'probably of foreign origin (compare 111);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0111}/[H2301]', 'lemma', 'heb', 'אֲדַד', '["ʼĂdad"]', '["Hadad"]', '["n-pr-m"]', 'Adad (or Hadad), an Edomite Hadad.', 'probably an orthographical variation for 2301;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1908I>', 'inflected', 'heb', 'והדד', '["va./ha.Dad"]', '["and/ Hadad"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4080H}/[H4079]', 'inflected', 'heb', 'מִדְיָן', '["Midyân"]', '["from/ Midian"]', '["n-pr-m n-pr-loc"]', 'Midjan, a son of Abraham; also his country and (collectively) his descendants Midian, Midianite.', 'the same as 4079;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6290G}/[H6286]', 'inflected', 'heb', 'פָּארָן', '["Pâʼrân"]', '["from/ Paran"]', '["n-pr-loc"]', 'Paran, a desert of Arabia Paran.', 'from 6286; ornamental;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8472}/[H8472]', 'lemma', 'heb', 'תַּחְפְּנֵיס', '["Tachpᵉnêyç"]', '["Tahpenes"]', '["n-pr-f"]', 'Tachpenes, an Egyptian woman Tahpenes.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1377}/[H1376]', 'inflected', 'heb', 'גְּבִירָה', '["gᵉbîyrâh"]', '["the/ queen","the/ queen-mother"]', '["n-f"]', 'a mistress queen.', 'feminine of 1376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1592}/[H1589]', 'lemma', 'heb', 'גְּנֻבַת', '["Gᵉnubath"]', '["Genubath"]', '["n-pr-m"]', 'Genubath, an Edomitish prince Genubath.', 'from 1589; theft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1580}/H9033/[H1580]', 'inflected', 'heb', 'גָּמַל', '["gâmal"]', '["and/ she weaned/ him"]', '["v"]', 'to treat a person (well or ill), i.e. benefit or requite; by implication (of toil), to ripen, i.e. (specifically) to wean bestow on, deal bountifully, do (good), recompense, requite, reward, ripen, serve, mean, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7901J}/[H7901]', 'lemma', 'heb', 'שָׁכַב', '["shâkab"]', '["I will lie down","[who] lie of","he had lain down","lay down","they lie","they will lie","you will lie"]', '["v"]', 'to lie down (for rest, sexual connection, decease or any other purpose) × at all, cast down, (lover-)lay (self) (down), (make to) lie (down, down to sleep, still with), lodge, ravish, take rest, sleep, stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7331}/[H7336]', 'lemma', 'heb', 'רְזוֹן', '["Rᵉzôwn"]', '["Rezon"]', '["n-pr-m"]', 'Rezon, a Syrian Rezon.', 'from 7336; prince;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0450H}/[H410]', 'lemma', 'heb', 'אֶלְיָדָע', '["ʼElyâdâʻ"]', '["Eliada"]', '["n-pr-m"]', 'Eljada, the name of two Israelites and of an Aramaean leader Eliada.', 'from 410 and 3045; God (is) knowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2026}/[H2026]', 'inflected', 'heb', 'הָרַג', '["hârag"]', '["on the/ killed ones","when/ is killed","when/ killed"]', '["v"]', 'to smite with deadly intent destroy, out of hand, kill, murder(-er), put to (death), make (slaughter), slay(-er), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H1834>', 'inflected', 'heb', 'בדרמשק', '["be./da.Ma.sek","be./da.Me.sek","be./dar.Me.sek","ve./da.Me.sek"]', '["[was] in/ Damascus","in/ Damascus"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0758I}\/[H759]', 'inflected', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3379G}/[H7378]', 'inflected', 'heb', 'יָרׇבְעָם', '["Yârobʻâm"]', '["and/ Jeroboam"]', '["n-pr-m"]', 'Jarobam, the name of two Israelite kings Jeroboam.', 'from 7378 and 5971; (the) people will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5028}/[H5027]', 'lemma', 'heb', 'נְבָט', '["Nᵉbâṭ"]', '["Nebat"]', '["n-pr-m"]', 'Nebat, the father of Jeroboam I Nebat.', 'from 5027; regard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6868G>', 'inflected', 'heb', 'הצרדה', '["ha./tze.re.Dah"]', '["<the>/ Zeredah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6871}/[H6879]', 'lemma', 'heb', 'צְרוּעָה', '["Tsᵉrûwʻâh"]', '["[was] Zeruah"]', '["n-pr-f"]', 'Tseruah, an Israelitess Zeruah.', 'feminine passive participle of 6879; leprous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3379G}/[H7378]', 'lemma', 'heb', 'יָרׇבְעָם', '["Yârobʻâm"]', '["Jeroboam","O Jeroboam"]', '["n-pr-m"]', 'Jarobam, the name of two Israelite kings Jeroboam.', 'from 7378 and 5971; (the) people will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5447}/[H5445]', 'lemma', 'heb', 'סֵבֶל', '["çêbel"]', '["[the] forced labor of"]', '["n-m"]', 'a load (literally or figuratively) burden, charge.', 'from 5445;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3130G}\/[H3254]', 'inflected', 'heb', 'יוֹסֵף', '["Yôwçêph"]', '["Joseph"]', '["n-pr-m"]', 'Joseph, the name of seven Israelites Joseph. Compare 3084.', 'future of 3254; let him add (or perhaps simply active participle adding);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0281H}/[H251]', 'lemma', 'heb', 'אֲחִיָּה', '["ʼĂchîyâh"]', '["Ahijah"]', '["n-pr-m"]', 'Achijah, the name of nine Israelites Ahiah, Ahijah.', 'or (prolonged) אֲחִיָּהוּ ; from 251 and 3050; brother (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7888}/[H7887]', 'inflected', 'heb', 'שִׁילוֹנִי', '["Shîylôwnîy"]', '["<the>/ Shilonite","the/ Shilonite","the/ Shilonite[s]"]', '["a"]', 'a Shilonite or inhabitant of Shiloh Shilonite.', 'or שִׁילֹנִי; or שִׁלֹנִי; from 7887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8008}/[H8071]', 'inflected', 'heb', 'שַׂלְמָה', '["salmâh"]', '["<in> the/ cloak","with/ a cloak"]', '["n-f"]', 'a dress clothes, garment, raiment.', 'transp. for 8071;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8147}/H9028/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["and/ [the] two of/ them"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2319H}/[H2318]', 'inflected', 'heb', 'חָדָשׁ', '["châdâsh"]', '["<the>/ new"]', '["a"]', 'new fresh, new thing.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7167}/H9034/[H7167]', 'inflected', 'heb', 'קָרַע', '["qâraʻ"]', '["and/ he tore/ it"]', '["v"]', 'to rend, literally or figuratively (revile, paint the eyes, as if enlarging them) cut out, rend, × surely, tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7168}/[H7167]', 'lemma', 'heb', 'קֶרַע', '["qeraʻ"]', '["pieces"]', '["n-m"]', 'a rag piece, rag.', 'from 7167;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3379G}/[H7378]', 'inflected', 'heb', 'יָרׇבְעָם', '["Yârobʻâm"]', '["of/ Jeroboam","to/ Jeroboam"]', '["n-pr-m"]', 'Jarobam, the name of two Israelite kings Jeroboam.', 'from 7378 and 5971; (the) people will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H7626H>', 'inflected', 'heb', 'והשבט', '["ve./ha./She.vet"]', '["and/ the/ tribe"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6253}/[H6251]', 'inflected', 'heb', 'עַשְׁתֹּרֶת', '["ʻAshtôreth"]', '["to/ Astarte"]', '["n-pr-f"]', 'Ashtoreth, the Phoenician goddess of love (and increase) Ashtoreth.', 'probably for 6251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4445B}/[H4428]', 'inflected', 'heb', 'מַלְכָּם', '["Malkâm"]', '["and/ to/ Milcom"]', '["n-pr-m"]', 'Malcam or Milcom, the national idol of the Ammonites Malcham, Milcom.', 'or מִלְכּוֹם; from 4428 for 4432;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7896G}/H9033/[H7896]', 'inflected', 'heb', 'שִׁית', '["shîyth"]', '["I will make/ him","they make/ it","you give/ him"]', '["v"]', 'to place (in a very wide application) apply, appoint, array, bring, consider, lay (up), let alone, × look, make, mark, put (on), regard, set, shew, be stayed, × take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5216B}/[H5214]', 'lemma', 'heb', 'נִיר', '["nîyr"]', '["[the] lamp of","a lamp"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0853}/H9031/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["and/ <obj.>/ you"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7895}/[H7895]', 'lemma', 'heb', 'שִׁישַׁק', '["Shîyshaq"]', '["Shishak"]', '["n-pr-m"]', 'Shishak, an Egyptian king Shishak.', 'or שׁוּשַׁק; of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2451}/H9023/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["and/ wisdom/ his"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7346}/[H7337]', 'lemma', 'heb', 'רְחַבְעָם', '["Rᵉchabʻâm"]', '["Rehoboam"]', '["n-pr-m"]', 'Rechabam, an Israelite king Rehoboam.', 'from 7337 and 5971; a people has enlarged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8478H}/H9033\/[H8430]', 'inflected', 'heb', 'תַּחַת', '["tachath"]', '["in place of/ him","in place/ his"]', '["n-m"]', 'the bottom (as depressed); only adverbially, below (often with prepositional prefix underneath), in lieu of, etc. as, beneath, × flat, in(-stead), (same) place (where...is), room, for...sake, stead of, under, × unto, × when...was mine, whereas, (where-) fore, with.', 'from the same as 8430;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5923}/H9025/[H5953]', 'inflected', 'heb', 'עֹל', '["ʻôl"]', '["yoke/ our"]', '["n-m"]', 'a yoke (as imposed on the neck), literally or figuratively yoke.', 'or עוֹל; from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5656G}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["some of/ [the] labor of","some of/ [the] service of"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5923}/H9023/[H5953]', 'inflected', 'heb', 'עֹל', '["ʻôl"]', '["and/ some of/ yoke/ his"]', '["n-m"]', 'a yoke (as imposed on the neck), literally or figuratively yoke.', 'or עוֹל; from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3289}/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["and/ he consulted","and/ he had taken counsel","and/ he took counsel","and/ they took counsel"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1961}/H9043/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["when/ is/ he","when/ was/ he","when/ was/ it"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6030B}/H9038/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ he answered/ them","and/ you will answer/ them"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3289}/H9033/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["[female] counselor/ his","they had counseled/ him"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725M}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ they may bring back","and/ we may bring back","so/ let me bring back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5923}/[H5953]', 'inflected', 'heb', 'עֹל', '["ʻôl"]', '["the/ yoke"]', '["n-m"]', 'a yoke (as imposed on the neck), literally or figuratively yoke.', 'or עוֹל; from 5953;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6995}/H9020/[H6994]', 'inflected', 'heb', 'קֹטֶן', '["qôṭen"]', '["little finger/ my"]', '["n-m"]', 'a pettiness, i.e. the little finger little finger.', 'from 6994;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6006}/[H6006]', 'lemma', 'heb', 'עָמַס', '["ʻâmaç"]', '["[are] carried","[were] carrying [it]","he carries a load","he loaded"]', '["v"]', 'to load, i.e. impose a burden (or figuratively, infliction) be borne, (heavy) burden (self), lade, load, put.', 'or עָמַשׂ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7752}/[H7751]', 'inflected', 'heb', 'שׁוֹט', '["shôwṭ"]', '["in/ [the] whip of","with <the>/ whips"]', '["n-m"]', 'a lash (literally or figuratively) scourge, whip.', 'from 7751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6137>', 'inflected', 'heb', 'בעקרבים', '["ba./''ak.ra.Bim"]', '["with <the>/ scorpions"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6098}/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["according to/ [the] counsel of"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5438}/[H5437]', 'lemma', 'heb', 'סִבָּה', '["çibbâh"]', '["a turn"]', '["n-f"]', 'a (providential) turn (of affairs) cause.', 'from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7346}\/[H7337]', 'inflected', 'heb', 'רְחַבְעָם', '["Rᵉchabʻâm"]', '["Rehoboam"]', '["n-pr-m"]', 'Rechabam, an Israelite king Rehoboam.', 'from 7337 and 5971; a people has enlarged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0151}/[H141]', 'lemma', 'heb', 'אֲדֹרָם', '["ʼĂdôrâm"]', '["Adoram"]', '["n-pr-m"]', 'Adoram (or Adoniram), an Israelite Adoram.', 'contracted for 141;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5927K}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["to/ go up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6586}/[H6586]', 'inflected', 'heb', 'פָּשַׁע', '["pâshaʻ"]', '["and/ he rebelled","and/ it has rebelled","and/ it rebelled","and/ they have rebelled"]', '["v"]', 'to break away (from just authority), i.e. trespass, apostatize, quarrel offend, rebel, revolt, transgress(-ion, -or).', 'a primitive root (identical with through the idea of expansion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7346}/[H7337]', 'inflected', 'heb', 'רְחַבְעָם', '["Rᵉchabʻâm"]', '["to/ Rehoboam"]', '["n-pr-m"]', 'Rechabam, an Israelite king Rehoboam.', 'from 7337 and 5971; a people has enlarged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8098A}/[H8085]', 'lemma', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3898A}/H9013/[H3898]', 'inflected', 'heb', 'לָחַם', '["lâcham"]', '["you must do battle/ !"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5927G}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["for/ going up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1835G}/[H1777]', 'inflected', 'heb', 'דָּן', '["Dân"]', '["in/ Dan"]', '["n-pr-m"]', 'Dan, one of the sons of Jacob; also the tribe descended from him, and its territory; likewise a place in Palestine colonized by them Daniel', 'from 1777; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2282}/[H2287]', 'inflected', 'heb', 'חַג', '["chag"]', '["like the/ festival"]', '["n-m"]', 'a festival, or a victim therefor (solemn) feast (day), sacrifice, solemnity.', 'or חָג; from 2287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5695}/[H5696]', 'inflected', 'heb', 'עֵגֶל', '["ʻêgel"]', '["to the/ calves"]', '["n-m"]', 'a (male) calf (as frisking round), especially one nearly grown (i.e. a steer) bullock, calf.', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5975J}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ he stationed"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0908}/[H908]', 'lemma', 'heb', 'בָּדָא', '["bâdâʼ"]', '["he had devised"]', '["v"]', '(figuratively) to invent devise, feign.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3820A}/H9023/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["from/ heart/ his","from/ own heart/ his"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6999H}\/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["to/ make smoke"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6999H}/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["by/ making smoke","to/ make smoke"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2977G}/[H803]', 'lemma', 'heb', 'יֹאשִׁיָּה', '["Yôʼshîyâh"]', '["Josiah","[will be] Josiah"]', '["n-pr-m"]', 'Joshijah, the name of two Israelites Josiah.', 'or יֹאשִׁיָּהוּ; from the same root as 803 and 3050; founded of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6999H}/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["who/ make smoke"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8610}/H9033/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["seize/ him"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3001}/[H3001]', 'inflected', 'heb', 'יָבֵשׁ', '["yâbêsh"]', '["and/ I will make dry","and/ it dried up","and/ it dries up","and/ it has withered","and/ it is dry","and/ it will be dry","and/ it will wither","and/ it withered","and/ they have dried up","and/ they will dry up"]', '["v"]', 'to be ashamed, confused or disappointed; also (as failing) to dry up (as water) or wither (as herbage) be ashamed, clean, be confounded, (make) dry (up), (do) shame(-fully), × utterly, wither (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725G}/H9034/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["to/ bring back/ it"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4159}/[H3302]', 'inflected', 'heb', 'מוֹפֵת', '["môwphêth"]', '["according to the/ sign","like/ a portent"]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/H9003/{H7223H}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["as/ at the/ former [time]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935G}/H9012/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["come/ !"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5582}/H9012/[H5582]', 'inflected', 'heb', 'סָעַד', '["çâʻad"]', '["and/ sustain/ !"]', '["v"]', 'to support (mostly figurative) comfort, establish, hold up, refresh self, strengthen, be upholden.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4991}/[H4976]', 'lemma', 'heb', 'מַתָּת', '["mattâth"]', '["[is] a gift of","[the] gift of","[will be] [the] gift of","a gift"]', '["n-f"]', 'a present gift.', 'feminine of 4976 abbreviated form;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1008G}\/[H1004]', 'inflected', 'heb', 'בֵּית־אֵל', '["Bêyth-ʼÊl"]', '["-el"]', '["n-pr-loc"]', 'Beth-El, a place in Palestine Beth-el.', 'from 1004 and 410; house of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5030}/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["and/ [the] prophets of","and/ a prophet","and/ prophet"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5608A}/H9038/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["and/ he counted out/ them","and/ they have recounted/ them","and/ they recounted/ them"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1870J}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["[is] the/ way","the/ way"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7979}\/[H7971]', 'inflected', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["the/ table"]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0398}/H9043/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["ate/ he"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8354}/H9043/[H8354]', 'inflected', 'heb', 'שָׁתָה', '["shâthâh"]', '["drank/ he"]', '["v"]', 'to imbibe (literally or figuratively) × assuredly, banquet, × certainly, drink(-er, -ing), drunk (× -ard), surely. (Prop. intensive of 8248.)', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2543}/[H2560]', 'inflected', 'heb', 'חֲמוֹר', '["chămôwr"]', '["and/ the/ donkey","and/ the/ donkey[s]"]', '["n-m"]', 'a male ass (from its dun red) (he) ass.', 'or (shortened) חֲמֹר; from 2560;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0738B}/[H717]', 'inflected', 'heb', 'אֲרִי', '["ʼărîy"]', '["and/ the/ lion"]', '["n-m"]', 'a lion (young) lion, pierce (from the margin).', 'or (prolonged) אַרְיֵה; from 717 (in the sense of violence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5038}/[H5034]', 'inflected', 'heb', 'נְבֵלָה', '["nᵉbêlâh"]', '["the/ corpse"]', '["n-f"]', 'a flabby thing, i.e. a carcase or carrion (human or bestial, often collectively); figuratively, an idol (dead) body, (dead) carcase, dead of itself, which died, (beast) that (which) dieth of itself.', 'from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0738B}/[H717]', 'inflected', 'heb', 'אֲרִי', '["ʼărîy"]', '["to the/ lion"]', '["n-m"]', 'a lion (young) lion, pierce (from the margin).', 'or (prolonged) אַרְיֵה; from 717 (in the sense of violence);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7665}/H9033/[H7665]', 'inflected', 'heb', 'שָׁבַר', '["shâbar"]', '["and/ he broke/ it","and/ it has mauled/ him"]', '["v"]', 'to burst (literally or figuratively) break (down, off, in pieces, up), broken (-hearted), bring to the birth, crush, destroy, hurt, quench, × quite, tear, view (by mistake for 7663).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725G}/H9033/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ he brought back/ him","and/ they brought back/ him"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6912}/H9033/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["and/ to/ bury/ him"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6913}/H9023/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["in/ own grave/ his","in/ own grave<s>/ his"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1945}/[H1930]', 'lemma', 'heb', 'הוֹי', '["hôwy"]', '["alas!","woe to!","woe!"]', '["inj"]', 'oh! ah, alas, ho, O, woe.', 'a prolonged form of 1930 (akin to 188);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4194}/H9020/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["at/ death/ my"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6106G}/H9023/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["bone/ his","bone/ its","bones/ his","bones/ its"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8111}\/[H8104]', 'inflected', 'heb', 'שֹׁמְרוֹן', '["Shômᵉrôwn"]', '["Samaria"]', '["n-pr-loc"]', 'Shomeron, a place in Palestine Samaria.', 'from the active participle of 8104; watch-station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725O}/[H7725]', 'lemma', 'heb', 'שׁוּב', '["shûwb"]', '["I will turn back","anyone will repent","he has turned away","he has turned back","he turned away","he turned back","he will turn","he will turn away","it will turn back","they may turn back","they turned back","they will return","to turn back","turn back","you will return","you will turn back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1870L}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["from/ way/ his"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2655}/[H2654]', 'inflected', 'heb', 'חָפֵץ', '["châphêts"]', '["<the>/ delighting","<the>/ desiring","the/ [one] desiring"]', '["a"]', 'pleased with delight in, desire, favour, please, have pleasure, whosoever would, willing, wish.', 'from 2654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3582}/[H3582]', 'inflected', 'heb', 'כָּחַד', '["kâchad"]', '["and/ to/ annihilate [it]"]', '["v"]', 'to secrete, by act or word; hence (intensively) to destroy conceal, cut down (off), desolate, hide.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0029H}/[H1]', 'lemma', 'heb', 'אֲבִיָּה', '["ʼĂbîyâh"]', '["Abijah"]', '["n-pr-m"]', 'Abijah, the name of several Israelite men and two Israelitesses Abiah, Abijah.', 'or prolonged אֲבִיָּהוּ ; from 1 and 3050; father (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8138A}/[H8138]', 'inflected', 'heb', 'שָׁנָה', '["shânâh"]', '["and/ he changed","and/ you will disguise yourself"]', '["v"]', 'to fold, i.e. duplicate (literally or figuratively); by implication, to transmute (transitive or intransitive) do (speak, strike) again, alter, double, (be given to) change, disguise, (be) diverse, pervert, prefer, repeat, return, do the second time.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027I}/H9022/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["in/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5350}/[H5348]', 'inflected', 'heb', 'נִקֻּד', '["niqqud"]', '["and/ cakes"]', '["n-m"]', 'a crumb (as broken to spots); also a biscuit (as pricked) cracknel, mouldy.', 'from the same as 5348;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1228}/[H1238]', 'inflected', 'heb', 'בַּקְבֻּק', '["baqbuq"]', '["and/ a jar of"]', '["n-m"]', 'a bottle (from the gurgling in emptying) bottle, cruse.', 'from 1238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0281H}/[H251]', 'inflected', 'heb', 'אֲחִיָּה', '["ʼĂchîyâh"]', '["and/ Ahijah"]', '["n-pr-m"]', 'Achijah, the name of nine Israelites Ahiah, Ahijah.', 'or (prolonged) אֲחִיָּהוּ ; from 251 and 3050; brother (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7869}/H9023\/[H7867]', 'inflected', 'heb', 'שֵׂיב', '["sêyb"]', '["from/ old age/ his"]', '["n-m"]', 'old age age.', 'from 7867;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0935G}/H9044/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ comes/ she"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7311A}/H9031/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["I raised up/ you","I will exalt/ you"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5650}/H9020/[H5647]', 'inflected', 'heb', 'עֶבֶד', '["ʻebed"]', '["like/ servant/ my"]', '["n-m"]', 'a servant × bondage, bondman, (bond-) servant, (man-) servant.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3707}/H9030/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["by/ provoking to anger/ me","to/ provoke to anger/ me"]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1458}/H9021\/[H1460]', 'inflected', 'heb', 'גַּו', '["gav"]', '["back/ your"]', '["n-m"]', 'the back back.', 'another form for 1460;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1557}/[H1556]', 'inflected', 'heb', 'גָּלָל', '["gâlâl"]', '["<the>/ dung"]', '["n-m"]', 'dung (as in balls) dung.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8552}/H9043/[H8552]', 'inflected', 'heb', 'תָּמַם', '["tâmam"]', '["is complete/ it"]', '["v"]', 'to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7272}/H9022/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["feet/ your","foot/ your"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5110}/[H5110]', 'lemma', 'heb', 'נוּד', '["nûwd"]', '["bemoaning itself","does he show sympathy","it sways","show sympathy","take flight","they will take flight","will he show sympathy","you shook yourself","you show sympathy","you will waver"]', '["v"]', 'to nod, i.e. waver; figuratively, to wander, flee, disappear; also (from shaking the head in sympathy), to console, deplore, or (from tossing the head in scorn) taunt bemoan, flee, get, mourn, make to move, take pity, remove, shake, skip for joy, be sorry, vagabond, way, wandering.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7070H}/[H7069]', 'inflected', 'heb', 'קָנֶה', '["qâneh"]', '["<the>/ reed","the/ reed"]', '["n-m"]', 'a reed (as erect); by resemblance a rod (especially for measuring), shaft, tube, stem, the radius (of the arm), beam (of a steelyard) balance, bone, branch, calamus, cane, reed, × spearman, stalk.', 'from 7069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5428}/[H5428]', 'inflected', 'heb', 'נָתַשׁ', '["nâthash"]', '["and/ I will pluck up","and/ he will pluck up","and/ it was plucked up"]', '["v"]', 'to tear away destroy, forsake, pluck (out, up, by the roots), pull up, root out (up), × utterly. s', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2219}/H9038/[H2114]', 'inflected', 'heb', 'זָרָה', '["zârâh"]', '["and/ I have winnowed/ them","and/ I will disperse/ them","and/ I will scatter/ them","and/ he will scatter/ them"]', '["v"]', 'to toss about; by implication, to diffuse, winnow cast away, compass, disperse, fan, scatter (away), spread, strew, winnow.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5104G}/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["of the/ River"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0842}/H9028/[H833]', 'inflected', 'heb', 'אֲשֵׁרָה', '["ʼăshêrâh"]', '["Asherah poles/ their"]', '["n-pr-f"]', 'Asherah (or Astarte) a Phoenician goddess; also an image of the same grove. Compare 6253.', 'or אֲשֵׁירָה; from 833; happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3707}/[H3707]', 'lemma', 'heb', 'כַּעַס', '["kaʻaç"]', '["I will be angry","[are] provoking to anger","he has provoked to anger","he provoked to anger","provoking","provoking to anger","they have provoked to anger","you have provoked to anger","you must provoke to anger"]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8656H}/H9011/[H7521]', 'inflected', 'heb', 'תִּרְצָה', '["Tirtsâh"]', '["Tirzah/ towards"]', '["n-pr-f"]', 'Tirtsah, a place in Palestine; also an Israelitess Tirzah.', 'from 7521; delightsomeness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5592B}/[H5605]', 'inflected', 'heb', 'סַף', '["çaph"]', '["[will be] on the/ threshold","at the/ thresholds","at/ [the] threshold of"]', '["n-m"]', 'a vestibule (as a limit); also a dish (for holding blood or wine) bason, bowl, cup, door (post), gate, post, threshold.', 'from 5605, in its original sense of containing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5070H}/[H5068]', 'lemma', 'heb', 'נָדָב', '["Nâdâb"]', '["Nadab"]', '["n-pr-m"]', 'Nadab, the name of four Israelites Nadab.', 'from 5068; liberal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7346}/[H7337]', 'inflected', 'heb', 'רְחַבְעָם', '["Rᵉchabʻâm"]', '["and/ Rehoboam"]', '["n-pr-m"]', 'Rechabam, an Israelite king Rehoboam.', 'from 7337 and 5971; a people has enlarged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5279A}/[H5277]', 'lemma', 'heb', 'נַעֲמָה', '["Naʻămâh"]', '["[was] Naamah"]', '["n-pr-f n-pr-loc"]', 'Naamah, the name of an antediluvian woman, of an Ammonitess, and of a place in Palestine Naamah.', 'feminine of 5277; pleasantness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2403B}/H9028/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["by/ sins/ their"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0842}/[H833]', 'inflected', 'heb', 'אֲשֵׁרָה', '["ʼăshêrâh"]', '["and/ Asherah poles"]', '["n-pr-f"]', 'Asherah (or Astarte) a Phoenician goddess; also an image of the same grove. Compare 6253.', 'or אֲשֵׁירָה; from 833; happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004P}/[H1129]', 'lemma', 'heb', 'בַּיִת', '["bayith"]', '["[the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7323H}/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["the/ runners"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8104G}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["who/ guarded","who/ keeps"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375H}/H9038/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["it will carry away/ them","they carried/ them","they carry off/ them","you will bear/ them"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8372}/[H8376]', 'lemma', 'heb', 'תָּא', '["tâʼ"]', '["[the] guardroom of"]', '["n-m"]', 'a room (as circumscribed) (little) chamber.', 'and (feminine) תָּאָה; (Ezekiel 40:12), from (the base of) 8376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4421}/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["and/ [the] wars of","and/ battle","and/ war","and/ warfare","and/ wars"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0038}/[H1]', 'lemma', 'heb', 'אֲבִיָּם', '["ʼĂbîyâm"]', '["Abijam"]', '["n-pr-m"]', 'Abijam (or Abijah), a king of Judah Abijam.', 'from 1 and 3220; father of (the) sea (i.e. seaman);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4601K}/[H4600]', 'lemma', 'heb', 'מַעֲכָה', '["Maʻăkâh"]', '["Maacah","[was] Maacah"]', '["n-pr"]', 'Maakah (or Maakath), the name of a place in Syria, also of a Mesopotamian, of three Israelites, and of four Israelitesses and one Syrian woman Maachah, Maachathites. See also 1038.', 'or מַעֲכָת; (Joshua 13:13), from 4600; depression;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0609G>', 'opaque', 'heb', 'אָסָא', '["ʼÂçâʼ"]', '["Asa","O Asa"]', '["n-pr-m"]', 'Asa, the name of a king and of a Levite Asa.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6945}/[H6942]', 'inflected', 'heb', 'קָדֵשׁ', '["qâdêsh"]', '["the/ cult prostitute[s]","the/ male cult prostitutes"]', '["n-m"]', 'a (quasi) sacred person, i.e. (technically) a (male) devotee (by prostitution) to licentious idolatry sodomite, unclean.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1544}/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["the/ idols"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5493G}/H9034/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["and/ he removed/ her"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1377}/[H1376]', 'inflected', 'heb', 'גְּבִירָה', '["gᵉbîyrâh"]', '["from/ queen-mother"]', '["n-f"]', 'a mistress queen.', 'feminine of 1376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4656}/[H6426]', 'lemma', 'heb', 'מִפְלֶצֶת', '["miphletseth"]', '["an abominable image"]', '["n-f"]', 'a terror, i.e. an idol idol.', 'from 6426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0842}/[H833]', 'inflected', 'heb', 'אֲשֵׁרָה', '["ʼăshêrâh"]', '["for <the>/ Asherah","to <the>/ Asherah pole","to/ an Asherah pole"]', '["n-pr-f"]', 'Asherah (or Astarte) a Phoenician goddess; also an image of the same grove. Compare 6253.', 'or אֲשֵׁירָה; from 833; happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4656}/H9024/[H6426]', 'inflected', 'heb', 'מִפְלֶצֶת', '["miphletseth"]', '["abominable image/ her"]', '["n-f"]', 'a terror, i.e. an idol idol.', 'from 6426;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H1116>', 'inflected', 'heb', 'והבמות', '["ve./Ha./ba.Mot","ve./ha./ba.Mot"]', '["and/ the/ high places"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6944G}/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["and/ [the] holy things","and/ [the] holy things of","and/ [the] sanctuary"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1201>', 'opaque', 'heb', 'בַּעְשָׁא', '["Baʻshâʼ"]', '["Baasha"]', '["n-pr-m"]', 'Basha, a king of Israel Baasha.', 'from an unused root meaning to stink; offensiveness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/H9028', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["day/ their","days/ their"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0609G>', 'inflected', 'heb', 'לאסא', '["le./''a.Sa''"]', '["of/ Asa","to/ Asa"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1130G}/[H1121]', 'lemma', 'heb', 'בֶּן־הֲדַד', '["Ben-Hădad"]', '["Ben","Hadad"]', '["n-pr-m"]', 'Ben-Hadad, the name of several Syrian kings Benhadad.', 'from 1121 and 1908; son of Hadad;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2886}/[H2895]', 'lemma', 'heb', 'טַבְרִמּוֹן', '["Ṭabrimmôwn"]', '["Tabrimmon"]', '["n-pr-m"]', 'Tabrimmon, a Syrian Tabrimmon.', 'from 2895 and 7417; pleasing (to) Rimmon;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2383}/[H2372]', 'lemma', 'heb', 'חֶזְיוֹן', '["Chezyôwn"]', '["Hezion"]', '["n-pr-m"]', 'Chezjon, a Syrian Hezion.', 'from 2372; vision;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6565A}/H9012/[H6565]', 'inflected', 'heb', 'פָּרַר', '["pârar"]', '["break/ !"]', '["v"]', 'to break up (usually figuratively), i.e. to violate, frustrate × any ways, break (asunder), cast off, cause to cease, × clean, defeat, disannul, disappoint, dissolve, divide, make of none effect, fail, frustrate, bring (come) to nought, × utterly, make void.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5859}/[H5856]', 'lemma', 'heb', 'עִיּוֹן', '["ʻÎyôwn"]', '["Ijon"]', '["n-pr-loc"]', 'Ijon, a place in Palestine Ijon.', 'from 5856; ruin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1129}/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["from/ building"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8656H}/[H7521]', 'inflected', 'heb', 'תִּרְצָה', '["Tirtsâh"]', '["in/ Tirzah"]', '["n-pr-f"]', 'Tirtsah, a place in Palestine; also an Israelitess Tirzah.', 'from 7521; delightsomeness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085I}/[H8085]', 'lemma', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["I will cause to hear [them]","[one who] proclaims","[was one who] proclaimed","[was] sounding aloud","did he proclaim","he has proclaimed","he made proclamation to","it has been heard","make [them] heard","make a proclamation","proclaim","sounding aloud","summon","they will make heard","they will make proclamation","will he proclaim?","you proclaimed"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6086G}/H9024/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["wood<s>/ its"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2209}/H9023/[H2205]', 'inflected', 'heb', 'זִקְנָה', '["ziqnâh"]', '["old age/ his"]', '["n-f"]', 'old age old (age).', 'feminine of 2205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3092I}/[H3068]', 'lemma', 'heb', 'יְהוֹשָׁפָט', '["Yᵉhôwshâphâṭ"]', '["Jehoshaphat"]', '["n-pr-m n-pr-loc"]', 'Jehoshaphat, the name of six Israelites; also of a valley near Jerusalem Jehoshaphat. Compare 3146.', 'from 3068 and 8199; Jehovah-judged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5070H}/[H5068]', 'inflected', 'heb', 'נָדָב', '["Nâdâb"]', '["and/ Nadab"]', '["n-pr-m"]', 'Nadab, the name of four Israelites Nadab.', 'from 5068; liberal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2403B}/H9023/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ for/ sin/ his","and/ in/ sin/ his"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0281I}/[H251]', 'lemma', 'heb', 'אֲחִיָּה', '["ʼĂchîyâh"]', '["Ahijah"]', '["n-pr-m"]', 'Achijah, the name of nine Israelites Ahiah, Ahijah.', 'or (prolonged) אֲחִיָּהוּ ; from 251 and 3050; brother (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1405}/[H1389]', 'inflected', 'heb', 'גִּבְּתוֹן', '["Gibbᵉthôwn"]', '["at/ Gibbethon"]', '["n-pr-loc"]', 'Gibbethon, a place in Palestine Gibbethon.', 'intensive from 1389; a hilly spot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4427A}/H9043/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["when/ became king/ he"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3708A}/H9023/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["by/ provocation/ his"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/H9028\', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days/ their"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3058G}/[H3068]', 'lemma', 'heb', 'יֵהוּא', '["Yêhûwʼ"]', '["Jehu"]', '["n-pr-m"]', 'Jehu, the name of five Israelites Jehu.', 'from 3068 and 1931; Jehovah (is) He;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2607G}/[H2603]', 'lemma', 'heb', 'חֲנָנִי', '["Chănânîy"]', '["Hanani"]', '["n-pr-m"]', 'Chanani, the name of six Israelites Hanani.', 'from 2603; gracious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1201>', 'inflected', 'heb', 'לבעשא', '["le./va''.Sha''"]', '["of/ Baasha"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1369}/H9023/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["and/ might/ his"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0425H}/[H424]', 'lemma', 'heb', 'אֵלָה', '["ʼÊlâh"]', '["Elah"]', '["n-pr"]', 'Elah, the name of an Edomite, of four Israelites, and also of a place in Palestine Elah.', 'the same as 424;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2174A}/[H2167]', 'lemma', 'heb', 'זִמְרִי', '["Zimrîy"]', '["O Zimri","Zimri"]', '["n-pr-m"]', 'Zimri, the name of five Israelites, and of an Arabian tribe Zimri.', 'from 2167; musical;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0777}/[H776]', 'lemma', 'heb', 'אַרְצָא', '["ʼartsâʼ"]', '["Arza"]', '["n-pr-m"]', 'Artsa, an Israelite Arza.', 'from 776; earthiness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1350I}/H9023/[H1350]', 'inflected', 'heb', 'גָּאַל', '["gâʼal"]', '["and/ kinsman redeemer/ his"]', '["v"]', 'to redeem (according to the Oriental law of kinship), i.e. to be the next of kin (and as such to buy back a relative''s property, marry his widow, etc.) × in any wise, × at all, avenger, deliver, (do, perform the part of near, next) kinsfolk(-man), purchase, ransom, redeem(-er), revenger.', 'a primitive root,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7453}/H9023/[H7462]', 'inflected', 'heb', 'רֵעַ', '["rêaʻ"]', '["and/ friend/ his"]', '["n-m"]', 'an associate (more or less close) brother, companion, fellow, friend, husband, lover, neighbour, × (an-) other.', 'or רֵיעַ; from 7462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2403B}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ [the] sin of","and/ [the] sins of","and/ sins"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3707}/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["to/ become angry","to/ provoke [him] to anger","to/ provoke anger","to/ provoke to anger"]', '["v"]', 'to trouble; by implication, to grieve, rage, be indignant be angry, be grieved, take indignation, provoke (to anger, unto wrath), have sorrow, vex, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6018G}/[H6014]', 'lemma', 'heb', 'עׇמְרִי', '["ʻOmrîy"]', '["Omri"]', '["n-pr-m"]', 'Omri, an Israelite Omri.', 'from 6014; heaping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1405}/[H1389]', 'inflected', 'heb', 'גִּבְּתוֹן', '["Gibbᵉthôwn"]', '["from/ Gibbethon"]', '["n-pr-loc"]', 'Gibbethon, a place in Palestine Gibbethon.', 'intensive from 1389; a hilly spot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0759G>', 'opaque', 'heb', 'אַרְמוֹן', '["ʼarmôwn"]', '["[the] fortress of","[the] fortresses of","[the] palace"]', '["n-m"]', 'a citadel (from its height) castle, palace. Compare 2038.', 'from an unused root (meaning to be elevated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7195}/H9023/[H7194]', 'inflected', 'heb', 'קֶשֶׁר', '["qesher"]', '["and/ conspiracy/ his"]', '["n-m"]', 'an (unlawful) alliance confederacy, conspiracy, treason.', 'from 7194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8402}/[H8401]', 'lemma', 'heb', 'תִּבְנִי', '["Tibnîy"]', '["Tibni"]', '["n-pr-m"]', 'Tibni, an Israelite Tibni.', 'from 8401; strawy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1527>', 'opaque', 'heb', 'גִּינַת', '["Gîynath"]', '["Ginath"]', '["n-pr-m"]', 'Ginath, an Israelite Ginath.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4427A}/H9033/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["of/ reigning/ his","to/ make king/ him"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2677}/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["and/ <the>/ half"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6018G}\/[H6014]', 'inflected', 'heb', 'עׇמְרִי', '["ʻOmrîy"]', '["Omri"]', '["n-pr-m"]', 'Omri, an Israelite Omri.', 'from 6014; heaping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8111}/[H8104]', 'lemma', 'heb', 'שֹׁמְרוֹן', '["Shômᵉrôwn"]', '["O Samaria","Samaria","[is it] Samaria","[is] Samaria","[was] Samaria"]', '["n-pr-loc"]', 'Shomeron, a place in Palestine Samaria.', 'from the active participle of 8104; watch-station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8106A}/[H8105]', 'lemma', 'heb', 'שֶׁמֶר', '["Shemer"]', '["Shemer"]', '["n-pr-m"]', 'Shemer, the name of three Israelites Shamer, Shemer.', 'the same as 8105;');
