INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0256G}/[H251]', 'lemma', 'heb', 'אַחְאָב', '["ʼAchʼâb"]', '["Ahab"]', '["n-pr-m"]', 'Achab, the name of a king of Israel and of a prophet at Babylon Ahab.', 'once (by contraction) אֶחָב (Jeremiah 29:22); from 251 and 1; brother (i.e. friend) of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0256G}/[H251]', 'inflected', 'heb', 'אַחְאָב', '["ʼAchʼâb"]', '["and/ Ahab"]', '["n-pr-m"]', 'Achab, the name of a king of Israel and of a prophet at Babylon Ahab.', 'once (by contraction) אֶחָב (Jeremiah 29:22); from 251 and 1; brother (i.e. friend) of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980I}/H9043/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["to walk/ he"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2403B}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["for/ [the] sins of","for/ sin","in/ [the] sins of","to/ [the] sins of"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0348}/[H336]', 'lemma', 'heb', 'אִיזֶבֶל', '["ʼÎyzebel"]', '["Jezebel"]', '["n-pr-f"]', 'Izebel, the wife of king Ahab Jezebel.', 'from 336 and 2083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0856}/[H854]', 'lemma', 'heb', 'אֶתְבַּעַל', '["ʼEthbaʻal"]', '["Ethbaal"]', '["n-pr-m"]', 'Ethbaal, a Phoenician king Ethbaal.', 'from 854 and 1168; with Baal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2419}/[H2416]', 'lemma', 'heb', 'חִיאֵל', '["Chîyʼêl"]', '["Hiel"]', '["n-pr-m"]', 'Chiel, an Israelite Hiel.', 'from 2416 and 410; living of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1017}/[H1008]', 'lemma', 'heb', 'בֵּית הָאֱלִי', '["Bêyth hâ-ʼĔlîy"]', '["[the] Beth-"]', '["a"]', 'a Beth-elite, or inhabitant of Bethel Bethelite.', 'patrial from 1008 with the article interposed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1017}/[H1008]', 'inflected', 'heb', 'בֵּית הָאֱלִי', '["Bêyth hâ-ʼĔlîy"]', '["<the>/ -elite"]', '["a"]', 'a Beth-elite, or inhabitant of Bethel Bethelite.', 'patrial from 1008 with the article interposed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0048H}/[H1]', 'inflected', 'heb', 'אֲבִירָם', '["ʼĂbîyrâm"]', '["by/ Abiram"]', '["n-pr-m"]', 'Abiram, the name of two Israelites Abiram.', 'from 1 and 7311; father of height (i.e. lofty);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7687G}/[H7682]', 'inflected', 'heb', 'שְׂגוּב', '["Sᵉgûwb"]', '["and/ by/ Segub"]', '["n-pr-m"]', 'Segub, the name of two Israelites Segub.', 'from 7682; aloft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6810}/H9023/[H6819]', 'inflected', 'heb', 'צָעִיר', '["tsâʻîyr"]', '["young [son]/ his"]', '["a"]', 'little; (in number) few; (in age) young, (in value) ignoble least, little (one), small (one), young(-er, -est).', 'or צָעוֹר; from 6819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0452G}/[H410]', 'lemma', 'heb', 'אֵלִיָּה', '["ʼÊlîyâh"]', '["Elijah","O Elijah","[was] Elijah"]', '["n-pr-m"]', 'Elijah, the name of the famous prophet and of two other Israelites Elijah, Eliah.', 'or prolonged אֵלִיָּהוּ; from 410 and 3050; God of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8664}/[H8664]', 'inflected', 'heb', 'תִּשְׁבִּי', '["Tishbîy"]', '["the/ Tishbite"]', '["n-pr"]', 'a Tishbite or inhabitant of Tishbeh (in Gilead) Tishbite.', 'patrial from an unused name meaning recourse;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8453A}/[H3427]', 'inflected', 'heb', 'תּוֹשָׁב', '["tôwshâb"]', '["one of/ [the] resident aliens of"]', '["n-m"]', 'a dweller but not outlandish [5237]; especially (as distinguished from a native citizen [active participle of 3427] and a temporary inmate [1616] or mere lodger [3885]) resident alien foreigner, inhabitant, sojourner, stranger.', 'or תֹּשָׁב; (1 Kings 17:1), from 3427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697G}/H9020\/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["word/ my"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3747}/[H3772]', 'lemma', 'heb', 'כְּרִית', '["Kᵉrîyth"]', '["Kerith"]', '["n"]', 'Kerith, a brook of Palestine Cherith.', 'from 3772; a cut;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5158A}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["from/ the/ wadi"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3557}/H9031/[H3557]', 'inflected', 'heb', 'כּוּל', '["kûwl"]', '["to/ supply/ you"]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6158}/[H6150]', 'inflected', 'heb', 'עֹרֵב', '["ʻôrêb"]', '["and/ the/ ravens"]', '["n-m"]', 'a raven (from its dusky hue) raven.', 'or עוֹרֵב; from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1653}/[H1652]', 'lemma', 'heb', 'גֶּשֶׁם', '["geshem"]', '["[is] rains","rain","rain of","rains of"]', '["n-m"]', 'a shower rain, shower.', 'from 1652;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6886}/H9011/[H6884]', 'inflected', 'heb', 'צָרְפַת', '["Tsârᵉphath"]', '["Zarephath/ towards"]', '["n-pr-loc"]', 'Tsarephath, a place in Palestine Zarephath.', 'from 6884; refinement;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6721H}/[H6679]', 'inflected', 'heb', 'צִידוֹן', '["Tsîydôwn"]', '["[belongs] to/ Sidon"]', '["n-pr-loc"]', 'Tsidon, the name of a son of Canaan, and of a place in Palestine Sidon, Zidon.', 'or צִידֹן; from 6679 in the sense of catching fish; fishery;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027G}/H9022/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["in/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4580}/[H5746]', 'lemma', 'heb', 'מָעוֹג', '["mâʻôwg"]', '["[is] food","cake"]', '["n-m"]', 'a cake of bread; parasite cake, feast.', 'from 5746; also with 3934 a table-buffoon, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3537>', 'inflected', 'heb', 'בכד', '["ba./Kad"]', '["in <the>/ jar"]', NULL, NULL, NULL);
