INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1121A}/H9022/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ for/ son/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0314}\/[H309]', 'inflected', 'heb', 'אַחֲרוֹן', '["ʼachărôwn"]', '["at the/ last"]', '["a"]', 'hinder; generally, late or last; specifically (as facing the east) western after (-ward), to come, following, hind(-er, -ermost, -most), last, latter, rereward, ut(ter) most.', 'or (shortened) אַחֲרֹן; from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3537>', 'opaque', 'heb', 'כַּד', '["kad"]', '["[the] jar","[the] jar of","jars"]', '["n-f"]', 'properly, a pail; but generally of earthenware; a jar for domestic purposes barrel, pitcher.', 'from an unused root meaning to deepen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7058>', 'inflected', 'heb', 'הקמח', '["ha./Ke.mach"]', '["<the>/ flour"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6835>', 'inflected', 'heb', 'וצפחת', '["ve./tza.Pa.chat"]', '["and/ [the] jug of","and/ a jug of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0127H}/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["the/ ground"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004M}/H9024/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ household/ her"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0452G}\/[H410]', 'inflected', 'heb', 'אֵלִיָּה', '["ʼÊlîyâh"]', '["Elijah"]', '["n-pr-m"]', 'Elijah, the name of the famous prophet and of two other Israelites Elijah, Eliah.', 'or prolonged אֵלִיָּהוּ; from 410 and 3050; God of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2483}/H9023/[H2470]', 'inflected', 'heb', 'חֳלִי', '["chŏlîy"]', '["sickness/ his"]', '["n-m"]', 'malady, anxiety, calamity disease, grief, (is) sick(-ness).', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771G}/H9020/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquities/ my","iniquity/ my"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4191}/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ to/ put to death"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2436G>/H9024', 'inflected', 'heb', 'מחיקה', '["me./chei.Ka/h"]', '["from/ bosom/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0490}/[H488]', 'inflected', 'heb', 'אַלְמָנָה', '["ʼalmânâh"]', '["the/ widow"]', '["n-f"]', 'a widow; also a desolate place desolate house (palace), widow.', 'feminine of 488;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7130G}/H9023/[H7126]', 'inflected', 'heb', 'קֶרֶב', '["qereb"]', '["inward part[s]/ his"]', '["n-m"]', 'properly, the nearest part, i.e. the center, whether literal, figurative or adverbial (especially with preposition) × among, × before, bowels, × unto charge, eat (up), × heart, × him, × in, inward (× -ly, part, -s, thought), midst, out of, purtenance, × therein, × through, × within self.', 'from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0571H}\/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["[is] truth"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5662G}/[H5647]', 'lemma', 'heb', 'עֹבַדְיָה', '["ʻÔbadyâh"]', '["Obadiah"]', '["n-pr-m"]', 'Obadjah, the name of thirteen Israelites Obadiah.', 'or עֹבַדְיָהוּ; active participle of 5647 and 3050; serving Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5662G}/[H5647]', 'inflected', 'heb', 'עֹבַדְיָה', '["ʻÔbadyâh"]', '["and/ Obadiah"]', '["n-pr-m"]', 'Obadjah, the name of thirteen Israelites Obadiah.', 'or עֹבַדְיָהוּ; active participle of 5647 and 3050; serving Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2244}/H9038/[H2245]', 'inflected', 'heb', 'חָבָא', '["châbâʼ"]', '["and/ he hid/ them"]', '["v"]', 'to secrete × held, hide (self), do secretly.', 'a primitive root (compare 2245);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2682A}/[H2681]', 'lemma', 'heb', 'חָצִיר', '["châtsîyr"]', '["[is] grass","[who] grass","grass","grass of","herbage"]', '["n-m"]', 'grass; also a leek (collectively) grass, hay, herb, leek.', 'perhaps originally the same as 2681, from the greenness of a courtyard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/<H0929>', 'inflected', 'heb', 'מהבהמה', '["me./ha./be.he.Mah"]', '["any of/ the/ livestock"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1870J}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["by the/ way","by/ a way","in/ a direction"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5234A}/H9033/[H5234]', 'inflected', 'heb', 'נָכַר', '["nâkar"]', '["and/ he recognized/ him"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0113>/H9021', 'inflected', 'heb', 'לאדניך', '["la./do.Nei./kha"]', '["to/ master<s>/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4467}/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["and/ a kingdom","and/ kingdom","and/ kingdoms","and/ kingship"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1245}/H9031/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["to/ seek/ you"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0256G}/[H251]', 'inflected', 'heb', 'אַחְאָב', '["ʼAchʼâb"]', '["of/ Ahab","to/ Ahab"]', '["n-pr-m"]', 'Achab, the name of a king of Israel and of a prophet at Babylon Ahab.', 'once (by contraction) אֶחָב (Jeremiah 29:22); from 251 and 1; brother (i.e. friend) of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5030}/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["from/ [the] prophet","from/ a prophet","from/ prophet","of/ [the] prophets of"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5800A}/H9046/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["because/ have forsaken/ you"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3760H}/[H3759]', 'inflected', 'heb', 'כַּרְמֶל', '["Karmel"]', '["<the>/ Carmel"]', '["n-pr-loc"]', 'Karmel, the name of a hill and of a town in Palestine Carmel, fruitful (plentiful) field, (place).', 'the same as 3759;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6452B}/[H6452]', 'lemma', 'heb', 'פָּסַח', '["pâçach"]', '["[be] limping"]', '["v"]', 'to hop, i.e. (figuratively) skip over (or spare); by implication, to hesitate; also (literally) to limp, to dance halt, become lame, leap, pass over.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5587A}/[H5586]', 'inflected', 'heb', 'סָעִף', '["çâʻiph"]', '["the/ crutches"]', '["n-f"]', 'divided (in mind), i.e. (abstractly) a sentiment opinion.', 'or שָׂעִף; from 5586;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5408}/H9033/[H5408]', 'inflected', 'heb', 'נָתַח', '["nâthach"]', '["and/ let them cut in pieces/ it"]', '["v"]', 'to dismember cut (in pieces), divide, hew in pieces.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7121G}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ call","and/ let them call out","and/ proclaim","and/ summon"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6030B}/H9035/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["answer/ us","may he answer/ us","you answer/ us"]', '["v"]', 'properly, to eye or (generally) to heed, i.e. pay attention; by implication, to respond; by extension to begin to speak; specifically to sing, shout, testify, announce give account, afflict (by mistake for 6031), (cause to, give) answer, bring low (by mistake for 6031), cry, hear, Leannoth, lift up, say, × scholar, (give a) shout, sing (together by course), speak, testify, utter, (bear) witness. See also 1042, 1043.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2048A}/[H2048]', 'inflected', 'heb', 'הָתַל', '["hâthal"]', '["and/ he mocked"]', '["v"]', 'to deride; by implication, to cheat deal deceitfully, deceive, mock.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7879}/[H7878]', 'lemma', 'heb', 'שִׂיחַ', '["sîyach"]', '["complaint","musing"]', '["n-m"]', 'a contemplation; by implication, an utterance babbling, communication, complaint, meditation, prayer, talk.', 'from 7878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7873}/[H7734]', 'lemma', 'heb', 'שִׂיג', '["sîyg"]', '["a going away"]', '["n-m"]', 'a withdrawal (into a private place) pursuing.', 'from 7734;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3364}/[H3364]', 'inflected', 'heb', 'יָקַץ', '["yâqats"]', '["and/ may they awake?","so/ he may awake"]', '["v"]', 'to awake (intransitive) (be) awake(-d).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1413}/[H1464]', 'inflected', 'heb', 'גָּדַד', '["gâdad"]', '["and/ they cut themselves"]', '["v"]', 'to crowd; also to gash (as if by pressing into) assemble (selves by troops), gather (selves together, self in troops), cut selves.', 'a primitive root (compare 1464);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4941J}/H9028/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["according to/ custom/ their"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H7420>', 'inflected', 'heb', 'וברמחים', '["u./va./re.ma.Chim","u./ve./Ro.mach"]', '["and/ with <the>/ lances","and/ with/ spear"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5674A}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["when/ passed","when/ passes by"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7182}/[H7181]', 'lemma', 'heb', 'קֶשֶׁב', '["qesheb"]', '["[was] attention","attentiveness"]', '["n-m"]', 'a hearkening × diligently, hearing, much heed, that regarded.', 'from 7181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2040}/[H2040]', 'inflected', 'heb', 'הָרַס', '["hâraç"]', '["that/ was torn down","the/ broken down [cities]"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8585A}/[H5927]', 'lemma', 'heb', 'תְּעָלָה', '["tᵉʻâlâh"]', '["[the] conduit of","a channel","a trench"]', '["n-f"]', 'a channel (into which water is raised for irrigation); also a bandage or plaster (as placed upon a wound) conduit, cured, healing, little river, trench, watercourse.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1004N}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["like/ a receptacle of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3332G}/[H3332]', 'inflected', 'heb', 'יָצַק', '["yâtsaq"]', '["and/ pour [it]"]', '["v"]', 'properly, to pour out (transitive or intransitive); by implication, to melt or cast as metal; by extension, to place firmly, to stiffen or grow hard cast, cleave fast, be (as) firm, grow, be hard, lay out, molten, overflow, pour (out), run out, set down, stedfast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8138B}/[H8138]', 'inflected', 'heb', 'שָׁנָה', '["shânâh"]', '["and/ they did again"]', '["v"]', 'to fold, i.e. duplicate (literally or figuratively); by implication, to transmute (transitive or intransitive) do (speak, strike) again, alter, double, (be given to) change, disguise, (be) diverse, pervert, prefer, repeat, return, do the second time.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8585A}/[H5927]', 'inflected', 'heb', 'תְּעָלָה', '["tᵉʻâlâh"]', '["the/ conduit","the/ trench"]', '["n-f"]', 'a channel (into which water is raised for irrigation); also a bandage or plaster (as placed upon a wound) conduit, cured, healing, little river, trench, watercourse.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5927I}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["[were] in/ offering up","when/ went up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1697G}/H9021/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ at/ word/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8585A}/[H5927]', 'inflected', 'heb', 'תְּעָלָה', '["tᵉʻâlâh"]', '["[was] in the/ trench","at/ [the] conduit of"]', '["n-f"]', 'a channel (into which water is raised for irrigation); also a bandage or plaster (as placed upon a wound) conduit, cured, healing, little river, trench, watercourse.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8610}/H9038/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["and/ he seized/ them","and/ they seized/ them"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0452G}/[H410]', 'inflected', 'heb', 'אֵלִיָּה', '["ʼÊlîyâh"]', '["and/ Elijah"]', '["n-pr-m"]', 'Elijah, the name of the famous prophet and of two other Israelites Elijah, Eliah.', 'or prolonged אֵלִיָּהוּ; from 410 and 3050; God of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1457}/[H1457]', 'inflected', 'heb', 'גָּהַר', '["gâhar"]', '["and/ he crouched"]', '["v"]', 'to prostrate oneself cast self down, stretch self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7637}/[H7657]', 'inflected', 'heb', 'שְׁבִיעִי', '["shᵉbîyʻîy"]', '["at the/ seventh [time]","in the/ seventh [month]"]', '["a"]', 'seventh seventh (time).', 'or שְׁבִעִי; ordinal from 7657;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3709G}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["like/ [the] hand of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6113}/H9031/[H6113]', 'inflected', 'heb', 'עָצָר', '["ʻâtsâr"]', '["it will hold back/ you"]', '["v"]', 'to inclose; by analogy, to hold back; also to maintain, rule, assemble × be able, close up, detain, fast, keep (self close, still), prevail, recover, refrain, × reign, restrain, retain, shut (up), slack, stay, stop, withhold (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H8064>', 'inflected', 'heb', 'והשמים', '["ve./ha./sha.Ma.yim"]', '["and/ the/ heavens"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6937}/[H6937]', 'lemma', 'heb', 'קָדַר', '["qâdar"]', '["I am in mourning","being dark","mourning","they are in mourning","they grew dark"]', '["v"]', 'to be ashy, i.e. dark-colored; by implication, to mourn (in sackcloth or sordid garments) be black(-ish), be (make) dark(-en), × heavily, (cause to) mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8151}/[H8151]', 'inflected', 'heb', 'שָׁנַס', '["shânaç"]', '["and/ he girded up"]', '["v"]', 'to compress (with a belt) gird up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0348}/[H336]', 'inflected', 'heb', 'אִיזֶבֶל', '["ʼÎyzebel"]', '["of/ Jezebel","to/ Jezebel"]', '["n-pr-f"]', 'Izebel, the wife of king Ahab Jezebel.', 'from 336 and 2083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3254H}/H9013/[H3254]', 'inflected', 'heb', 'יָסַף', '["yâçaph"]', '["may they add/ !"]', '["v"]', 'to add or augment (often adverbial, to continue to do a thing) add, × again, × any more, × cease, × come more, conceive again, continue, exceed, × further, × gather together, get more, give more-over, × henceforth, increase (more and more), join, × longer (bring, do, make, much, put), × (the, much, yet) more (and more), proceed (further), prolong, put, be (strong-) er, × yet, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5315H}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["like/ [the] life of"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7574}/[H7573]', 'lemma', 'heb', 'רֶתֶם', '["rethem"]', '["a broom plant","broom plants"]', '["n-m"]', 'the Spanish broom (from its pole-like stems) juniper (tree).', 'or רֹתֶם; from 7573;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0001G}/H9020/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["more than/ ancestors/ my"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7529}/[H7565]', 'lemma', 'heb', 'רֶצֶף', '["retseph"]', '["hot coals"]', '["n-m"]', 'a red-hot stone (for baking) coal.', 'for 7565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0396}/[H398]', 'inflected', 'heb', 'אֲכִילָה', '["ʼăkîylâh"]', '["the/ food"]', '["n-f"]', 'something eatable, i.e. food meat.', 'feminine from 398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2389}/[H2388]', 'inflected', 'heb', 'חָזָק', '["châzâq"]', '["and/ a strong [person]","and/ hard of","and/ strong"]', '["a"]', 'strong (usu. in a bad sense, hard, bold, violent) harder, hottest, impudent, loud, mighty, sore, stiff(-hearted), strong(-er).', 'from 2388;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7307H}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["O/ breath","the/ breath","the/ wind","the/ winds"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7494}/[H7493]', 'lemma', 'heb', 'רַעַשׁ', '["raʻash"]', '["a rattling","an earthquake","rumbling"]', '["n-m"]', 'vibration, bounding, uproar commotion, confused noise, earthquake, fierceness, quaking, rattling, rushing, shaking.', 'from 7493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7494}/[H7493]', 'inflected', 'heb', 'רַעַשׁ', '["raʻash"]', '["[was] in the/ earthquake","in/ quaking","with/ shaking"]', '["n-m"]', 'vibration, bounding, uproar commotion, confused noise, earthquake, fierceness, quaking, rattling, rushing, shaking.', 'from 7493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7494}/[H7493]', 'inflected', 'heb', 'רַעַשׁ', '["raʻash"]', '["the/ earthquake"]', '["n-m"]', 'vibration, bounding, uproar commotion, confused noise, earthquake, fierceness, quaking, rattling, rushing, shaking.', 'from 7493;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1827}/[H1826]', 'lemma', 'heb', 'דְּמָמָה', '["dᵉmâmâh"]', '["a whisper"]', '["n-f"]', 'quiet calm, silence, still.', 'feminine from 1826;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3874}/[H3874]', 'inflected', 'heb', 'לוּט', '["lûwṭ"]', '["and/ he wrapped"]', '["v"]', 'to wrap up cast, wrap.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0155}/H9023/[H117]', 'inflected', 'heb', 'אַדֶּרֶת', '["ʼaddereth"]', '["in/ cloak/ his"]', '["n-f"]', 'something ample (as a large vine, a wide dress) garment, glory, goodly, mantle, robe.', 'feminine of 117; ; also the same as 145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3947G}/H9034\/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["to/ take away/ it"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1870K}/H9021/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["to/ way/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2371}/[H2372]', 'lemma', 'heb', 'חֲזָאֵל', '["Chăzâʼêl"]', '["Hazael"]', '["n-pr-m"]', 'Chazael, a king of Syria Hazael.', 'or חֲזָהאֵל; from 2372 and 410; God has seen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3058H}/[H3068]', 'lemma', 'heb', 'יֵהוּא', '["Yêhûwʼ"]', '["Jehu","O Jehu"]', '["n-pr-m"]', 'Jehu, the name of five Israelites Jehu.', 'from 3068 and 1931; Jehovah (is) He;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5250}/[H4871]', 'lemma', 'heb', 'נִמְשִׁי', '["Nimshîy"]', '["Nimshi"]', '["n-pr-m"]', 'Nimshi, the (grand-) father of Jehu Nimshi.', 'probably from 4871; extricated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0477}/[H474]', 'lemma', 'heb', 'אֱלִישָׁע', '["ʼĔlîyshâʻ"]', '["Elisha","O Elisha"]', '["n-pr-m"]', 'Elisha, the famous prophet Elisha.', 'contracted for 474.;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8202H}/[H8199]', 'lemma', 'heb', 'שָׁפָט', '["Shâphâṭ"]', '["Shaphat"]', '["n-pr-m"]', 'Shaphat, the name of four Israelites Shaphat.', 'from 8199; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0065}/[H58]', 'inflected', 'heb', 'אָבֵל מְחוֹלָה', '["ʼÂbêl Mᵉchôwlâh"]', '["from/ Abel"]', '["n-pr-loc"]', 'Abel-Mecholah, a place in Palestine Abel-meholah.', 'from 58 and 4246; meadow of dancing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4422}/[H4422]', 'inflected', 'heb', 'מָלַט', '["mâlaṭ"]', '["and/ the/ [one who] escapes"]', '["v"]', 'properly, to be smooth, i.e. (by implication) to escape (as if by slipperiness); causatively, to release or rescue; specifically, to bring forth young, emit sparks deliver (self), escape, lay, leap out, let alone, let go, preserve, save, × speedily, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6310G}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["<the>/ mouth"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0155}/H9023/[H117]', 'inflected', 'heb', 'אַדֶּרֶת', '["ʼaddereth"]', '["cloak/ his"]', '["n-f"]', 'something ample (as a large vine, a wide dress) garment, glory, goodly, mantle, robe.', 'feminine of 117; ; also the same as 145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1980N}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ I will go","and/ will you walk?"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3627}/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["and/ in/ vessels of","and/ with/ [the] equipment of","and/ with/ [the] instruments of"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1310}/H9038/[H1310]', 'inflected', 'heb', 'בָּשַׁל', '["bâshal"]', '["he cooked/ them"]', '["v"]', 'properly, to boil up; hence, to be done in cooking; figuratively to ripen bake, boil, bring forth, roast, seethe, sod (be sodden).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8334}/H9033\/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["and/ he served/ him"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1130G}/[H1121]', 'inflected', 'heb', 'בֶּן־הֲדַד', '["Ben-Hădad"]', '["and/ Ben"]', '["n-pr-m"]', 'Ben-Hadad, the name of several Syrian kings Benhadad.', 'from 1121 and 1908; son of Hadad;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2091>/H9021', 'inflected', 'heb', 'וזהבך', '["u./ze.ha.ve./Kha"]', '["and/ gold/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4261}/[H2530]', 'lemma', 'heb', 'מַחְמָד', '["machmâd"]', '["<the> desirable thing of","[is] desirableness<es>","[the] delights of","[the] desire of","[the] precious things of","treasure"]', '["n-m"]', 'delightful; hence, a delight, i.e. object of affection or desire beloved, desire, goodly, lovely, pleasant (thing).', 'from 2530;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869I}/H9021/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eyes/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760I}/[H7760]', 'lemma', 'heb', 'שׂוּם', '["sûwm"]', '["set yourselves","they will put"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0802H}/H9020/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["for/ wives/ my","to/ wife/ my"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3701G}/H9020/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["and/ for/ silver/ my"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H2091>/H9020', 'inflected', 'heb', 'ולזהבי', '["ve./li/z.ha.V/i"]', '["and/ for/ gold/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5606B}/[H5606]', 'lemma', 'heb', 'סָפַק', '["çâphaq"]', '["it will suffice"]', '["v"]', 'to clap the hands (in token of compact, derision, grief, indignation, or punishment); by implication of satisfaction, to be enough; by implication of excess, to vomit clap, smite, strike, suffice, wallow.', 'or שָׂפַק; (1 Kings 20:10; Job 27:23; Isaiah 2:6), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H8168>', 'inflected', 'heb', 'לשעלים', '["li/sh.''a.Lim"]', '["for/ handfuls"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1984H}/[H1984]', 'lemma', 'heb', 'הָלַל', '["hâlal"]', '["[who] boasts","boast","do you boast","he boast","he boasts","he will boast","it will boast","let him boast","they boast","we have boasted","you boast"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6605A}/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["like/ [one who] loosens"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4310}/[H4100]', 'inflected', 'heb', 'מִי', '["mîy"]', '["by/ whom?"]', '["i"]', 'who? (occasionally, by a peculiar idiom, of things); also (indefinitely) whoever; often used in oblique construction with prefix or suffix any (man), × he, × him, O that! what, which, who(-m, -se, -soever), would to God.', 'an interrogative pronoun of persons, as 4100 is of things,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4082}/[H1777]', 'inflected', 'heb', 'מְדִינָה', '["mᵉdîynâh"]', '["the/ province","the/ provinces"]', '["n-f"]', 'properly, a judgeship, i.e. jurisdiction; by implication, a district (as ruled by a judge); generally, a region (× every) province.', 'from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0310A}/H9038/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["and/ after/ them"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5826}/[H5826]', 'lemma', 'heb', 'עָזַר', '["ʻâzar"]', '["[are] helping","[is] a helper","[one who] helps","[one who] is helped","[the] helpers of","[was] a helper","[who] helped of","[who] was helping","a helper","he helps","helping","they have helped","they help","they helped","they will be helped","they will help","you have helped"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8111}/[H8104]', 'inflected', 'heb', 'שֹׁמְרוֹן', '["Shômᵉrôwn"]', '["from/ Samaria"]', '["n-pr-loc"]', 'Shomeron, a place in Palestine Samaria.', 'from the active participle of 8104; watch-station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8610}/H9038/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["seize/ them"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0376G>/H9023', 'opaque', 'heb', 'אִישׁ', '["ʼîysh"]', '["man/ his"]', '["n-m"]', 'a man as an individual or a male person; often used as an adjunct to a more definite term (and in such cases frequently not expressed in translation) also, another, any (man), a certain, champion, consent, each, every (one), fellow, (foot-, husband-) man, (good-, great, mighty) man, he, high (degree), him (that is), husband, man(-kind), none, one, people, person, steward, what (man) soever, whoso(-ever), worthy. Compare 802.', 'contracted for 582 (or perhaps rather from an unused root meaning to be extant);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6346>', 'opaque', 'heb', 'פֶּחָה', '["pechâh"]', '["[the] governor","[the] governor of","[the] governors of","governors"]', '["n-m"]', 'a prefect (of a city or small district) captain, deputy, governor.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2428A}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["like the/ army"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0853}/H9032/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["from/ <obj.>/ you"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H5483M>', 'inflected', 'heb', 'כסוס', '["ka./Sus","ke./Sus"]', '["like <the>/ horse","like the/ horse","like/ [the] horse of","like/ a horse"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7393G}/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["like the/ chariotry"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0663I}/H9011/[H662]', 'inflected', 'heb', 'אֲפֵק', '["ʼĂphêq"]', '["Aphek/ towards"]', '["n-pr-loc"]', 'Aphek (or Aphik), the name of three places in Palestine Aphek, Aphik.', 'or אֲפִיק; from 662 (in the sense of strength); fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3557}/[H3557]', 'inflected', 'heb', 'כּוּל', '["kûwl"]', '["and/ has he contained?","and/ they were supplied"]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5048}/H9038/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["before/ them"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8147}/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["[are] like/ two","like/ two"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2835}/[H2834]', 'lemma', 'heb', 'חָשִׂף', '["châsiph"]', '["little flocks of"]', '["n-m"]', 'properly, drawn off, i.e. separated; hence, a small company (as divided from the rest) little flock.', 'from 2834;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6010R}/[H6009]', 'lemma', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["valleys"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2315}/[H2314]', 'lemma', 'heb', 'חֶדֶר', '["cheder"]', '["[the] chambers of","[the] room of","a room","rooms"]', '["n-m"]', 'an apartment (usually literal) ((bed) inner) chamber, innermost(-ward) part, parlour, south, × within.', 'from 2314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2315}\/[H2314]', 'inflected', 'heb', 'חֶדֶר', '["cheder"]', '["in/ a room"]', '["n-m"]', 'an apartment (usually literal) ((bed) inner) chamber, innermost(-ward) part, parlour, south, × within.', 'from 2314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4975>/H9025', 'inflected', 'heb', 'במתנינו', '["be./ma.te.Nei./nu","ve./ma.te.Nei./nu"]', '["on/ hips/ our","on/ loins/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4975>/H9028', 'inflected', 'heb', 'במתניהם', '["be./ma.te.nei./Hem"]', '["on/ hips/ their","on/ loins/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2480}/[H2480]', 'inflected', 'heb', 'חָלַט', '["châlaṭ"]', '["and/ they caught"]', '["v"]', 'to snatch at catch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4480A}/H9033/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["¿/ from/ him"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947J}/H9033/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["fetch/ him"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2351>', 'inflected', 'heb', 'וחוצות', '["Ve./chu.tzot","ve./chu.Tzot"]', '["and/ [the] open places","and/ streets"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7971H}/H9033\/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ he let go/ him"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2005}/H9041/[H2005]', 'inflected', 'heb', 'הֵן', '["hên"]', '["here/ you","there [are]/ you","there/ you"]', '["prt"]', 'lo!; also (as expressing surprise) if behold, if, lo, though.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6481}/[H6481]', 'inflected', 'heb', 'פָּצַע', '["pâtsaʻ"]', '["and/ wounded"]', '["v"]', 'to split, i.e. wound wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0666}/[H665]', 'inflected', 'heb', 'אֲפֵר', '["ʼăphêr"]', '["with <the>/ ashes"]', '["n-m"]', 'a turban ashes.', 'from the same as 665 (in the sense of covering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0666}/[H665]', 'inflected', 'heb', 'אֲפֵר', '["ʼăphêr"]', '["the/ bandage"]', '["n-m"]', 'a turban ashes.', 'from the same as 665 (in the sense of covering);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5030}/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["[was] one of/ the/ prophets"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2764A}/H9020/[H2763]', 'inflected', 'heb', 'חֵרֶם', '["chêrem"]', '["total destruction/ my"]', '["n-m"]', 'physical (as shutting in) a net (either literally or figuratively); usually a doomed object; abstractly extermination (ac-) curse(-d, -d thing), dedicated thing, things which should have been utterly destroyed, (appointed to) utter destruction, devoted (thing), net.', 'or (Zechariah 14:11) חֶרֶם; from 2763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004P}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5620}/[H5637]', 'lemma', 'heb', 'סַר', '["çar"]', '["sullen"]', '["a"]', 'peevish heavy, sad.', 'contracted from 5637;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2198}/[H2196]', 'inflected', 'heb', 'זָעֵף', '["zâʻêph"]', '["and/ furious"]', '["a"]', 'angry displeased.', 'from 2196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8111}/H9011\/[H8104]', 'inflected', 'heb', 'שֹׁמְרוֹן', '["Shômᵉrôwn"]', '["Samaria/ towards"]', '["n-pr-loc"]', 'Shomeron, a place in Palestine Samaria.', 'from the active participle of 8104; watch-station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5022}/[H5011]', 'inflected', 'heb', 'נָבוֹת', '["Nâbôwth"]', '["to/ Naboth"]', '["n-pr-f"]', 'Naboth, an Israelite Naboth.', 'feminine plural from the same as 5011; fruits;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3158H}/[H3157]', 'inflected', 'heb', 'יִזְרְעֵאלִי', '["Yizrᵉʻêʼlîy"]', '["the/ Jezreelite","the/ Jezreelite [woman]"]', '["a"]', 'a Jizreelite or native of Jizreel Jezreelite.', 'patronymically from 3157;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3157H}/[H2232]', 'inflected', 'heb', 'יִזְרְעֵאל', '["Yizrᵉʻêʼl"]', '["[was] in/ Jezreel","in/ Jezreel"]', '["n-pr-m n-pr-loc"]', 'Jizreel, the name of two places in Palestine and of two Israelites Jezreel.', 'from 2232 and 410; God will sow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1964H}/[H3201]', 'lemma', 'heb', 'הֵיכָל', '["hêykâl"]', '["[the] palace of","a palace","palaces","palaces of"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5022}/[H5011]', 'lemma', 'heb', 'נָבוֹת', '["Nâbôwth"]', '["Naboth"]', '["n-pr-f"]', 'Naboth, an Israelite Naboth.', 'feminine plural from the same as 5011; fruits;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3419}/[H3418]', 'lemma', 'heb', 'יָרָק', '["yârâq"]', '["vegetables"]', '["n-m"]', 'properly, green; concretely, a vegetable green, herbs.', 'from the same as 3418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004P}/H9020/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["house/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4242>', 'opaque', 'heb', 'מְחִיר', '["mᵉchîyr"]', '["[is] a price","[the] price of","price"]', '["n-m"]', 'price, payment, wages gain, hire, price, sold, worth.', 'from an unused root meaning to buy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307G}/H9021/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["[is] spirit/ your","spirit/ your"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0369}/H9041/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["and/ not/ you","and/ there not [will be]/ you"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2655}/[H2654]', 'lemma', 'heb', 'חָפֵץ', '["châphêts"]', '["[are] delighting","[are] desiring","[is one] desirous of","[the] [people] desirous of","desirous of","willing"]', '["a"]', 'pleased with delight in, desire, favour, please, have pleasure, whosoever would, willing, wish.', 'from 2654;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3754>/H9020', 'opaque', 'heb', 'כֶּרֶם', '["kerem"]', '["own vineyard/ my","vineyard/ my"]', '["n-m"]', 'a garden or vineyard vines, (increase of the) vineyard(-s), vintage. See also 1021.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4410}/[H4427]', 'lemma', 'heb', 'מְלוּכָה', '["mᵉlûwkâh"]', '["[will be that which] a kingship","kingship","royalty"]', '["n-f"]', 'something ruled, i.e. a realm kingsom, king''s, × royal.', 'feminine passive participle of 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2856}/[H2856]', 'inflected', 'heb', 'חָתַם', '["châtham"]', '["and/ I sealed [it]","and/ he sealed [it]","and/ she sealed [them]"]', '["v"]', 'to close up; especially to seal make an end, mark, seal (up), stop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2368}/H9023/[H2856]', 'inflected', 'heb', 'חוֹתָם', '["chôwthâm"]', '["with/ seal/ his"]', '["n-m"]', 'a signature-ring seal, signet.', 'or חֹתָם; from 2856;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2715}/[H2787]', 'inflected', 'heb', 'חֹר', '["chôr"]', '["the/ nobles"]', '["n-m"]', 'properly, white or pure (from the cleansing or shining power of fire); hence (figuratively) noble (in rank) noble.', 'or (fully) חוֹר; from 2787; (compare 2751)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5749B}/H9033/[H5749]', 'inflected', 'heb', 'עוּד', '["ʻûwd"]', '["and/ let them testify against/ him"]', '["v"]', 'to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3318H}/H9033/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ take out/ him"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5619}/H9033/[H5619]', 'inflected', 'heb', 'סָקַל', '["çâqal"]', '["and/ stone/ him"]', '["v"]', 'properly, to be weighty; but used only in the sense of lapidation or its contrary (as if a delapidation) (cast, gather out, throw) stone(-s), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2715}/[H2787]', 'inflected', 'heb', 'חֹר', '["chôr"]', '["and/ the/ nobles"]', '["n-m"]', 'properly, white or pure (from the cleansing or shining power of fire); hence (figuratively) noble (in rank) noble.', 'or (fully) חוֹר; from 2787; (compare 2751)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5749B}/H9033/[H5749]', 'inflected', 'heb', 'עוּד', '["ʻûwd"]', '["and/ they testified against/ him"]', '["v"]', 'to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3423H}/H9033\/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["to/ take possession of/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3423H}/H9033/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["to/ take possession of/ it"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7523}/[H7523]', 'inflected', 'heb', 'רָצַח', '["râtsach"]', '["¿/ have you murdered"]', '["v"]', 'properly, to dash in pieces, i.e. kill (a human being), especially to murder put to death, kill, (man-) slay(-er), murder(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H4672}/H9030/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["¿/ have you found/ me"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4376}/H9031/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["you having sold/ yourself"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H1004M}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ like/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3708A}/[H3707]', 'inflected', 'heb', 'כַּעַס', '["kaʻaç"]', '["the/ provocation","the/ provocations"]', '["n-m"]', 'vexation anger, angry, grief, indignation, provocation, provoking, × sore, sorrow, spite, wrath.', 'or (in Job) כַּעַשׂ; from 3707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0256G}/[H251]', 'inflected', 'heb', 'אַחְאָב', '["ʼAchʼâb"]', '["like/ Ahab"]', '["n-pr-m"]', 'Achab, the name of a king of Israel and of a prophet at Babylon Ahab.', 'once (by contraction) אֶחָב (Jeremiah 29:22); from 251 and 1; brother (i.e. friend) of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5496}/[H7898]', 'lemma', 'heb', 'סוּת', '["çûwth"]', '["[is] inciting","he mislead","he misleads","he should mislead","misleading","she incited"]', '["v"]', 'properly, to prick, i.e. (figuratively) stimulate; by implication, to seduce entice, move, persuade, provoke, remove, set on, stir up, take away.', 'perhaps denominative from 7898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8581}/[H8581]', 'inflected', 'heb', 'תַּעָב', '["taʻâb"]', '["and/ he abhorred","and/ he acted abominably","and/ you made abominable"]', '["v"]', 'to loathe, i.e. (morally) detest (make to be) abhor(-red), (be, commit more, do) abominable(-y), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0328B>\', 'opaque', 'heb', 'אַט', '["ʼaṭ"]', '["dejectedly"]', '["n-m adv"]', '(as a noun) a necromancer (from their soft incantations), (as an adverb) gently charmer, gently, secret, softly.', 'from an unused root perhaps meaning to move softly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7418G}/[H7413]', 'lemma', 'heb', 'רָמוֹת', '["Râmôwth"]', '["Ramoth"]', '["n-pr-loc"]', 'Ramoth-Negeb or Ramath-Negeb, a place in Palestine south Ramoth, Ramath of the south.', 'or רָמַת נֶגֶב; from the plural or construct form of 7413 and 5045; heights (or height) of the South;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3947G}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["from/ taking"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5971A}/H9020/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["as/ people/ my"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H5483M>/H9020', 'inflected', 'heb', 'כסוסי', '["ke./su.Sa/i"]', '["as/ horses/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H5483M>/H9021', 'inflected', 'heb', 'כסוסיך', '["ke./su.Sei./kha"]', '["as/ horses/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0853}/H9033/[H226]', 'inflected', 'heb', 'אֵת', '["ʼêth"]', '["from/ <obj.>/ him"]', '["prt"]', 'properly, self (but generally used to point out more definitely the object of a verb or preposition, even or namely) [as such unrepresented in English].', 'apparent contracted from 226 in the demonstrative sense of entity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4321G}/[H4322]', 'lemma', 'heb', 'מִיכָיְהוּ', '["Mîykâyᵉhûw"]', '["Micaiah","O Micaiah","[is] Micaiah"]', '["n-pr-m"]', 'Mikajah, the name of three Israelites Micah, Micaiah, Michaiah.', 'or מִכָיְהוּ; (Jeremiah 36:11), abbreviated form for 4322;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3229}/[H4390]', 'lemma', 'heb', 'יִמְלָא', '["Yimlâʼ"]', '["Imlah"]', '["n-pr-m"]', 'Jimla or Jimlah, an Israelite Imla, Imlah.', 'or יִמְלָה; from 4390; full;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3092I}/[H3068]', 'inflected', 'heb', 'יְהוֹשָׁפָט', '["Yᵉhôwshâphâṭ"]', '["and/ Jehoshaphat"]', '["n-pr-m n-pr-loc"]', 'Jehoshaphat, the name of six Israelites; also of a valley near Jerusalem Jehoshaphat. Compare 3146.', 'from 3068 and 8199; Jehovah-judged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6667G}/[H6664]', 'lemma', 'heb', 'צִדְקִיָּה', '["Tsidqîyâh"]', '["Zedekiah"]', '["n-pr-m"]', 'Tsidkijah, the name of six Israelites Zedekiah, Zidkijah.', 'or צִדְקִיָּהוּ; from 6664 and 3050; right of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3668G}/[H3667]', 'lemma', 'heb', 'כְּנַעֲנָה', '["Kᵉnaʻănâh"]', '["Kenaanah"]', '["n-pr-f"]', 'Kenaanah, the name of two Israelites Chenaanah.', 'feminine of 3667;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6743B}/[H6743]', 'inflected', 'heb', 'צָלַח', '["tsâlach"]', '["and/ succeed","so/ they may have success"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H4397G>', 'inflected', 'heb', 'והמלאך', '["ve./ha./mal.''Akh"]', '["and/ the/ messenger"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5307J}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ he may fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3541}/[H1931]', 'inflected', 'heb', 'כֹּה', '["kôh"]', '["by/ thus"]', '["prt"]', 'properly, like this, i.e. by implication, (of manner) thus (or so); also (of place) here (or hither); or (of time) now also, here, hitherto, like, on the other side, so (and much), such, on that manner, (on) this (manner, side, way, way and that way), mean while, yonder.', 'from the prefix k and 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6601B}/H9033/[H6601]', 'inflected', 'heb', 'פָּתָה', '["pâthâh"]', '["I will deceive/ him"]', '["v"]', 'to open, i.e. be (causatively, make) roomy; usually figuratively (in a mental or moral sense) to be (causatively, make) simple or (in a sinister way) delude allure, deceive, enlarge, entice, flatter, persuade, silly (one).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5030}/H9023/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["prophets/ his"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2247}/[H2245]', 'inflected', 'heb', 'חָבָה', '["châbâh"]', '["to/ hide themselves","to/ hide yourself"]', '["v"]', 'to secrete hide (self).', 'a primitive root (compare 2245);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725G}/H9033/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ return/ him","and/ take back/ him","and/ they returned/ it"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0526G}/[H525]', 'lemma', 'heb', 'אָמוֹן', '["ʼÂmôwn"]', '["Amon"]', '["n-pr-m"]', 'Amon, the name of three Israelites Amon.', 'the same as 525;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3101H}/[H3060]', 'lemma', 'heb', 'יוֹאָשׁ', '["Yôwʼâsh"]', '["Joash"]', '["n-pr-m"]', 'Joash, the name of six Israelites Joash.', 'or יֹאָשׁ; (2 Chronicles 24:1), a form of 3060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3608}/[H3607]', 'inflected', 'heb', 'כֶּלֶא', '["keleʼ"]', '["<the>/ imprisonment"]', '["n-m"]', 'a prison prison. Compare 3610, 3628.', 'from 3607;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3906}/[H3905]', 'lemma', 'heb', 'לַחַץ', '["lachats"]', '["[the] oppression of","oppression"]', '["n-m"]', 'distress affliction, oppression.', 'from 3905;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2664}/[H2664]', 'lemma', 'heb', 'חָפַשׂ', '["châphas"]', '["I will disguise myself","I will search","I will search for [them]","[it is] searching","he disguised himself","he is searched for","it disguises itself","let us examine","plotted","search","they plot","they will be plundered"]', '["v"]', 'to seek; causatively, to conceal oneself (i.e. let be sought), or mask change, (make) diligent (search), disquise self, hide, search (for, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0899B}/H9021/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["clothes/ your","own clothes/ your"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8537}/H9023/[H8552]', 'inflected', 'heb', 'תֹּם', '["tôm"]', '["to/ innocence/ his"]', '["n-m"]', 'completeness; figuratively, prosperity; usually (morally) innocence full, integrity, perfect(-ion), simplicity, upright(-ly, -ness), at a venture. See 8550.', 'from 8552;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1694}/[H1692]', 'inflected', 'heb', 'דֶּבֶק', '["debeq"]', '["the/ joints"]', '["n-m"]', 'a joint; by implication, solder joint, solder.', 'from 1692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7395}/H9023/[H7392]', 'inflected', 'heb', 'רַכָּב', '["rakkâb"]', '["to/ charioteer/ his"]', '["n-m"]', 'a charioteer chariot man, driver of a chariot, horseman.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2436I>', 'opaque', 'heb', 'חֵיק', '["chêyq"]', '["[the] bosom of","[the] bottom of"]', '["n-m"]', 'the bosom (literally or figuratively) bosom, bottom, lap, midst, within.', 'or חֵק; and חוֹק; from an unused root, apparently meaning to inclose;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3952}/[H3952]', 'inflected', 'heb', 'לָקַק', '["lâqaq"]', '["and/ they licked up"]', '["v"]', 'to lick or lap lap, lick.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2181}/[H2181]', 'inflected', 'heb', 'זָנָה', '["zânâh"]', '["and/ the/ prostitutes"]', '["v"]', 'to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish.', 'a primitive root [highly fed and therefore wanton];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8127H}/[H8150]', 'inflected', 'heb', 'שֵׁן', '["shên"]', '["<the>/ ivory"]', '["n-f"]', 'a tooth (as sharp); specifically ivory; figuratively, a cliff crag, × forefront, ivory, × sharp, tooth.', 'from 8150; compare 8143');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0274G}/[H270]', 'lemma', 'heb', 'אֲחַזְיָה', '["ʼĂchazyâh"]', '["Ahaziah"]', '["n-pr-m"]', 'Achazjah, the name of a Jewish and an Israelite king Ahaziah.', 'or (prolonged) אֲחַזְיָהוּ ; from 270 and 3050; Jah has seized;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5806G}/[H5805]', 'lemma', 'heb', 'עֲזוּבָה', '["ʻĂzûwbâh"]', '["[was] Azubah"]', '["n-pr-f"]', 'Azubah, the name of two Israelitesses Azubah.', 'the same as 5805;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7977}/[H7973]', 'lemma', 'heb', 'שִׁלְחִי', '["Shilchîy"]', '["Shilhi"]', '["n-pr-m"]', 'Shilchi, an Israelite Shilhi.', 'from 7973; missive, i.e. armed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7999B}/[H7999]', 'inflected', 'heb', 'שָׁלַם', '["shâlam"]', '["and/ he made peace","and/ they made peace"]', '["v"]', 'to be safe (in mind, body or estate); figuratively, to be (causatively, make) completed; by implication, to be friendly; by extension, to reciprocate (in various applications) make amends, (make an) end, finish, full, give again, make good, (re-) pay (again), (make) (to) (be at) peace(-able), that is perfect, perform, (make) prosper(-ous), recompense, render, requite, make restitution, restore, reward, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2091>', 'inflected', 'heb', 'לזהב', '["la./za.Hav","la./za.ho"]', '["<to> the/ gold","[is] for <the>/ gold","for <the>/ gold","for the/ gold","of <the>/ gold","of the/ gold"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3088G}/[H3068]', 'lemma', 'heb', 'יְהוֹרָם', '["Yᵉhôwrâm"]', '["Jehoram"]', '["n-pr-m"]', 'Jehoram, the name of a Syrian and of three Israelites Jehoram, Joram. Compare 3141.', 'from 3068 and 7311; Jehovah-raised;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3092I}/[H3068]', 'inflected', 'heb', 'יְהוֹשָׁפָט', '["Yᵉhôwshâphâṭ"]', '["of/ Jehoshaphat","to/ Jehoshaphat"]', '["n-pr-m n-pr-loc"]', 'Jehoshaphat, the name of six Israelites; also of a valley near Jerusalem Jehoshaphat. Compare 3146.', 'from 3068 and 8199; Jehovah-judged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1870G}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ in/ [the] way of","and/ in/ [the] ways of"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5944}/H9023/[H5927]', 'inflected', 'heb', 'עֲלִיָּה', '["ʻălîyâh"]', '["in/ upper room/ his"]', '["n-f"]', 'something lofty, i.e. a stair-way; also a second-story room (or even one on the roof); figuratively, the sky ascent, (upper) chamber, going up, loft, parlour.', 'feminine from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1176}/[H1168]', 'inflected', 'heb', 'בַּעַל זְבוּב', '["Baʻal Zᵉbûwb"]', '["<in>/ Baal"]', '["n-pr-m"]', 'Baal-Zebub, a special deity of the Ekronites Baal-zebub.', 'from 1168 and 2070; Baal of (the) Fly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1176}/[H1168]', 'lemma', 'heb', 'בַּעַל זְבוּב', '["Baʻal Zᵉbûwb"]', '["Zebub"]', '["n-pr-m"]', 'Baal-Zebub, a special deity of the Ekronites Baal-zebub.', 'from 1168 and 2070; Baal of (the) Fly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2483}/[H2470]', 'inflected', 'heb', 'חֳלִי', '["chŏlîy"]', '["from/ sickness"]', '["n-m"]', 'malady, anxiety, calamity disease, grief, (is) sick(-ness).', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2088}\/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["this"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7122G}/H9036/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["to/ meet/ you"]', '["v"]', 'to encounter, whether accidentally or in a hostile manner befall, (by) chance, (cause to) come (upon), fall out, happen, meet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1167J}/[H1166]', 'lemma', 'heb', 'בַּעַל', '["baʻal"]', '["[the] possessor of","[were] lords of","an owner of"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0232}/[H246]', 'inflected', 'heb', 'אֵזוֹר', '["ʼêzôwr"]', '["and/ a loincloth of"]', '["n-m"]', 'something girt; a belt, also a band girdle.', 'from 246;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2572}/H9023/[H2568]', 'inflected', 'heb', 'חֲמִשִּׁים', '["chămishshîym"]', '["and/ fifty [men]/ his"]', '["n"]', 'fifty fifty.', 'multiple of 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2572}/H9021/[H2568]', 'inflected', 'heb', 'חֲמִשִּׁים', '["chămishshîym"]', '["fifty [men]/ your"]', '["n"]', 'fifty fifty.', 'multiple of 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2572}/H9023/[H2568]', 'inflected', 'heb', 'חֲמִשִּׁים', '["chămishshîym"]', '["fifty [men]/ his"]', '["n"]', 'fifty fifty.', 'multiple of 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2572}/H9028/[H2568]', 'inflected', 'heb', 'חֲמִשִּׁים', '["chămishshîym"]', '["fifty [men]/ their"]', '["n"]', 'fifty fifty.', 'multiple of 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869H}/H9021\/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ your"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1697G}/H9023/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<in>/ word/ his","<in>/ words/ his","in/ words/ his"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3088I}/[H3068]', 'lemma', 'heb', 'יְהוֹרָם', '["Yᵉhôwrâm"]', '["Jehoram"]', '["n-pr-m"]', 'Jehoram, the name of a Syrian and of three Israelites Jehoram, Joram. Compare 3141.', 'from 3068 and 7311; Jehovah-raised;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3088I}/[H3068]', 'inflected', 'heb', 'יְהוֹרָם', '["Yᵉhôwrâm"]', '["of/ Jehoram"]', '["n-pr-m"]', 'Jehoram, the name of a Syrian and of three Israelites Jehoram, Joram. Compare 3141.', 'from 3068 and 7311; Jehovah-raised;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5927H}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["when/ took up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5591B}/[H5590]', 'inflected', 'heb', 'סַעַר', '["çaʻar"]', '["by the/ whirlwind","in the/ whirlwind","in/ [the] storm winds of"]', '["n-m"]', 'a hurricane storm(-y), tempest, whirlwind.', 'or (feminine) סְעָרָה; from 5590;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0477}/[H474]', 'inflected', 'heb', 'אֱלִישָׁע', '["ʼĔlîyshâʻ"]', '["and/ Elisha"]', '["n-pr-m"]', 'Elisha, the famous prophet Elisha.', 'contracted for 474.;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1537H}/[H1536]', 'inflected', 'heb', 'גִּלְגָּל', '["Gilgâl"]', '["<the>/ Gilgal"]', '["n-pr-loc"]', 'Gilgal, the name of three places in Palestine Gilgal. See also 1019.', 'the same as 1536 (with the article as a properly, noun);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218H>/H9021', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["head/ your"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1563}/[H1563]', 'inflected', 'heb', 'גָּלַם', '["gâlam"]', '["and/ he folded it up"]', '["v"]', 'to fold wrap together.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5674A}/H9048/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["when/ had passed over/ they"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7307G}/H9021/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["by/ spirit/ your","in/ spirit/ your"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1245}/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["and/ [is] seeking","and/ [one who] sought","and/ [those who] seek","and/ search","and/ they may seek","and/ to seek","so/ they may search for","so/ they may seek","so/ you may be sought"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7921C}/[H7921]', 'lemma', 'heb', 'שָׁכֹל', '["shâkôl"]', '["[is] causing abortions"]', '["v"]', 'properly, to miscarry, i.e. suffer abortion; by analogy, to bereave (literally or figuratively) bereave (of children), barren, cast calf (fruit, young), be (make) childless, deprive, destroy, × expect, lose children, miscarry, rob of children, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6746}/[H6743]', 'lemma', 'heb', 'צְלֹחִית', '["tsᵉlôchîyth"]', '["a jar"]', '["n-f"]', 'something prolonged or tall, i.e. a vial or salt-cellar cruse.', 'from 6743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7921C}/[H7921]', 'inflected', 'heb', 'שָׁכֹל', '["shâkôl"]', '["and/ abortion"]', '["v"]', 'properly, to miscarry, i.e. suffer abortion; by analogy, to bereave (literally or figuratively) bereave (of children), barren, cast calf (fruit, young), be (make) childless, deprive, destroy, × expect, lose children, miscarry, rob of children, spoil.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7046}/[H7046]', 'inflected', 'heb', 'קָלַס', '["qâlaç"]', '["and/ they derided"]', '["v"]', 'to disparage, i.e. ridicule mock, scoff, scorn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7043}/H9038/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["and/ I cursed/ them","and/ he cursed/ them"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1677}/[H1680]', 'lemma', 'heb', 'דֹּב', '["dôb"]', '["[female] bears","[is] a bear","a bear"]', '["n"]', 'the bear (as slow) bear.', 'or (fully) דּוֹב; from 1680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3088I}/[H3068]', 'inflected', 'heb', 'יְהוֹרָם', '["Yᵉhôwrâm"]', '["and/ Jehoram"]', '["n-pr-m"]', 'Jehoram, the name of a Syrian and of three Israelites Jehoram, Joram. Compare 3141.', 'from 3068 and 7311; Jehovah-raised;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0001G}/H9023/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["like/ father/ his"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0517}/H9023/[H517]', 'inflected', 'heb', 'אֵם', '["ʼêm"]', '["and/ like/ mother/ his"]', '["n-f"]', 'a mother (as the bond of the family); in a wide sense (both literally and figuratively [like father]) dam, mother, × parting.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4480A}/H9034\/[H4482]', 'inflected', 'heb', 'מִן', '["min"]', '["from/ it"]', '["prep"]', 'properly, a part of; hence (prepositionally), from or out of in many senses above, after, among, at, because of, by (reason of), from (among), in, × neither, × nor, (out) of, over, since, × then, through, × whether, with.', 'or מִנִּי; or מִנֵּי; (constructive plural) (Isaiah 30:11); for 4482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4338}/[H4337]', 'inflected', 'heb', 'מֵישַׁע', '["Mêyshaʻ"]', '["and/ Mesha"]', '["n-pr-m"]', 'Mesha, a Moabite Mesha.', 'a variation for 4337; safety;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5349}/[H5348]', 'lemma', 'heb', 'נֹקֵד', '["nôqêd"]', '["a sheep-breeder"]', '["n-m"]', 'a spotter (of sheep or cattle), i.e. the owner or tender (who thus marks them) herdman, sheepmaster.', 'active participle from the same as 5348;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5059}/[H5059]', 'inflected', 'heb', 'נָגַן', '["nâgan"]', '["when/ played"]', '["v"]', 'properly, to thrum, i.e. beat a tune with the fingers; expectation. to play on a stringed instrument; hence (generally), to make music player on instruments, sing to the stringed instruments, melody, ministrel, play(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5059}/[H5059]', 'inflected', 'heb', 'נָגַן', '["nâgan"]', '["the/ musician"]', '["v"]', 'properly, to thrum, i.e. beat a tune with the fingers; expectation. to play on a stringed instrument; hence (generally), to make music player on instruments, sing to the stringed instruments, melody, ministrel, play(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1356A}/[H1461]', 'lemma', 'heb', 'גֵּב', '["gêb"]', '["[the] cisterns","ditches"]', '["n-m"]', 'a log (as cut out); also well or cistern (as dug) beam, ditch, pit.', 'from 1461;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5158N}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["and/ the/ wadi"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0929>/H9026', 'inflected', 'heb', 'ובהמתכם', '["U./ve.hem.te./Khem"]', '["and/ animal[s]/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4004}/[H977]', 'lemma', 'heb', 'מִבְחוֹר', '["mibchôwr"]', '["[the] choice of","choice"]', '["n-m"]', 'select, i.e. well fortified choice.', 'from 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307M}/[H5307]', 'lemma', 'heb', 'נָפַל', '["nâphal"]', '["[was] making fall","it fell","it has fallen","they fell","they made fall","you will make fall"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5640A}/[H5640]', 'lemma', 'heb', 'סָתַם', '["çâtham"]', '["[are] kept secret","he stopped up","keep secret","secret [thing]","they stopped up","you will stop up"]', '["v"]', 'to stop up; by implication, to repair; figuratively, to keep secret closed up, hidden, secret, shut out (up), stop.', 'or שָׂתַם; (Numbers 24:15), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5927I}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["when/ went up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1818}/[H1826]', 'inflected', 'heb', 'דָּם', '["dâm"]', '["like <the>/ blood"]', '["n-m"]', 'blood (as that which when shed causes death) of man or an animal; by analogy, the juice of the grape; figuratively (especially in the plural) bloodshed (i.e. drops of blood) blood(-y, -guiltiness, (-thirsty), innocent.', 'from 1826 (compare 119);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2717C}/[H2717]', 'lemma', 'heb', 'חָרַב', '["chârab"]', '["certainly <to fight>","kill","they have fought one another"]', '["v"]', 'to parch (through drought) i.e. (by analogy,) to desolate, destroy, kill decay, (be) desolate, destroy(-er), (be) dry (up), slay, × surely, (lay, lie, make) waste.', 'or חֲרֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7998}/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["<into>/ plunder","to the/ plunder","to/ plunder"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4390}/H9034/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["and/ they filled/ it"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7025}/[H7023]', 'inflected', 'heb', 'קִיר חֶרֶשׂ', '["Qîyr Cheres"]', '["in <the>/ Kir"]', '["n-pr-loc"]', 'Kir-Cheres or Kir-Chareseth, a place in Moab Kir-haraseth, Kir-hareseth, Kirharesh, Kir-heres.', 'or (feminine of the latter word) קִיר חֲרֶשֶׂת; from 7023 and 2789; fortress of earthenware;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7025}/[H7023]', 'lemma', 'heb', 'קִיר חֶרֶשׂ', '["Qîyr Cheres"]', '["Hareseth","Heres","Kir"]', '["n-pr-loc"]', 'Kir-Cheres or Kir-Chareseth, a place in Moab Kir-haraseth, Kir-hareseth, Kirharesh, Kir-heres.', 'or (feminine of the latter word) קִיר חֲרֶשֶׂת; from 7023 and 2789; fortress of earthenware;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7051}/[H7049]', 'inflected', 'heb', 'קַלָּע', '["qallâʻ"]', '["the/ slingers"]', '["n-m"]', 'a slinger slinger.', 'intensive from 7049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388J}/[H2388]', 'lemma', 'heb', 'חָזַק', '["châzaq"]', '["he showed himself strong","it prevailed","it was [too] strong"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1234}/[H1234]', 'inflected', 'heb', 'בָּקַע', '["bâqaʻ"]', '["[about] to/ be broken into","to/ break through"]', '["v"]', 'to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0802H}/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["from/ [the] wife of","from/ [the] wives of","more than/ a woman of"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5383}/[H5382]', 'inflected', 'heb', 'נָשָׁה', '["nâshâh"]', '["and/ the/ creditor"]', '["v"]', 'to lend or (by reciprocity) borrow on security or interest creditor, exact, extortioner, lend, usurer, lend on (taker on) usury.', 'a primitive root (rather identical with 5382, in the sense of 5378);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H8198>/H9021', 'inflected', 'heb', 'לשפחתך', '["le./shif.cha.te./Kha"]', '["[belongs] to/ maidservant/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0610}/[H5480]', 'lemma', 'heb', 'אָסוּךְ', '["ʼâçûwk"]', '["a jar of"]', '["n-m"]', 'anointed, i.e. an oil-flask pot.', 'from 5480;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7934}/H9022/[H7931]', 'inflected', 'heb', 'שָׁכֵן', '["shâkên"]', '["neighbors/ your"]', '["a"]', 'a resident; by extension, a fellow-citizen inhabitant, neighbour, nigh.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1157}/H9032/[H5704]', 'inflected', 'heb', 'בְּעַד', '["bᵉʻad"]', '["behind/ you"]', '["prep"]', 'in up to or over against; generally at, beside, among, behind, for, etc. about, at by (means of), for, over, through, up (-on), within.', 'from 5704 with prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1157}/H9034/[H5704]', 'inflected', 'heb', 'בְּעַד', '["bᵉʻad"]', '["behind/ her","for/ it"]', '["prep"]', 'in up to or over against; generally at, beside, among, behind, for, etc. about, at by (means of), for, over, through, up (-on), within.', 'from 5704 with prepositional prefix;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4390}/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["when/ are completed","when/ were full"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5386}/H9022/[H5383]', 'inflected', 'heb', 'נְשִׁי', '["nᵉshîy"]', '["debt/ your"]', '["n-m"]', 'a debt debt.', 'from 5383;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3498}\/[H3498]', 'inflected', 'heb', 'יָתַר', '["yâthar"]', '["by the/ remainder"]', '["v"]', 'to jut over or exceed; by implication, to excel; (intransitively) to remain or be left; causatively to leave, cause to abound, preserve excel, leave (a remnant), left behind, too much, make plenteous, preserve, (be, let) remain(-der, -ing, -nant), reserve, residue, rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7766}/[H7764]', 'lemma', 'heb', 'שׁוּנֵם', '["Shûwnêm"]', '["Shunem"]', '["n-pr-loc"]', 'Shunem, a place in Pal Shunem.', 'probably from the same as 7764; quietly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2388I}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ she urged"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674A}/H9043/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["passed by/ he","passes by/ it"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6918H}/[H6942]', 'lemma', 'heb', 'קָדוֹשׁ', '["qâdôwsh"]', '["[the] holy [one] of","holy","holy [ones]"]', '["a"]', 'sacred (ceremonially or morally); (as noun) God (by eminence), an angel, a saint, a sanctuary holy (One), saint.', 'or קָדֹשׁ; from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4296}/[H5186]', 'lemma', 'heb', 'מִטָּה', '["miṭṭâh"]', '["[the] bed of","a bed","a couch","beds of","couches of"]', '["n-f"]', 'a bed (as extended) for sleeping or eating; by analogy, a sofa, litter or bier bed(-chamber), bier.', 'from 5186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7979}/[H7971]', 'inflected', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["and/ a table"]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3678I}/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["and/ a chair"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4501}/[H4500]', 'inflected', 'heb', 'מְנוֹרָה', '["mᵉnôwrâh"]', '["and/ [the] lampstand of","and/ a lampstand"]', '["n-f"]', 'a chandelier candlestick.', 'or מְנֹרָה; feminine of 4500 (in the original sense of 5216);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1522}/[H1516]', 'lemma', 'heb', 'גֵּיחֲזִי', '["Gêychăzîy"]', '["Gehazi","O Gehazi"]', '["n-pr-m"]', 'Gechazi, the servant of Elisha Gehazi.', 'or גֵּחֲזִי; apparently from 1516 and 2372; valley of a visionary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7767}/[H7766]', 'inflected', 'heb', 'שׁוּנַמִּית', '["Shûwnammîyth"]', '["<to> the/ Shunammite [woman]"]', '["a"]', 'a Shunammitess, or female inhabitant of Shunem Shunamite.', 'patrial from 7766;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2731}/[H2730]', 'inflected', 'heb', 'חֲרָדָה', '["chărâdâh"]', '["the/ care"]', '["n-f"]', 'fear, anxiety care, × exceedingly, fear, quaking, trembling.', 'feminine of 2730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2263}/[H2263]', 'lemma', 'heb', 'חָבַק', '["châbaq"]', '["[is] folding","[will be] embracing","they embrace","they have embraced"]', '["v"]', 'to clasp (the hands or in embrace) embrace, fold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3576}/[H3576]', 'lemma', 'heb', 'כָּזַב', '["kâzab"]', '["I will lie","[is] a liar","he tells lies","he told a lie","it is proved a lie","it will lie","they lied","they will fail","will I lie?","you tell a lie","you will lie"]', '["v"]', 'to lie (i.e. deceive), literally or figuratively fail, (be found a, make a) liar, lie, lying, be in vain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H8198>/H9021', 'inflected', 'heb', 'בשפחתך', '["be./shif.cha.Te./kha"]', '["to/ maidservant/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375G}/H9033/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ he carried/ him","and/ he will lift up/ him"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5288}/H9024/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["servant/ her"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1980L}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ go"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0376H>/H9022', 'inflected', 'heb', 'לאישך', '["le./''i.She/kh"]', '["[belong] to/ husband/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3206}/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["[belong] to the/ child"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1920}/H9034/[H1920]', 'inflected', 'heb', 'הָדַף', '["hâdaph"]', '["to/ drive away/ her"]', '["v"]', 'to push away or down cast away (out), drive, expel, thrust (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7592}/[H7592]', 'inflected', 'heb', 'שָׁאַל', '["shâʼal"]', '["¿/ did I ask for"]', '["v"]', 'to inquire; by implication, to request; by extension, to demand ask (counsel, on), beg, borrow, lay to charge, consult, demand, desire, × earnestly, enquire, greet, obtain leave, lend, pray, request, require, salute, × straitly, × surely, wish.', 'or שָׁאֵל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7952}/[H7953]', 'lemma', 'heb', 'שָׁלָה', '["shâlâh"]', '["you be negligent","you must deceive"]', '["v"]', 'to mislead deceive, be negligent.', 'a primitive root (probably identical with 7953 through the idea of educing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1522}/[H1516]', 'inflected', 'heb', 'גֵּיחֲזִי', '["Gêychăzîy"]', '["to/ Gehazi"]', '["n-pr-m"]', 'Gechazi, the servant of Elisha Gehazi.', 'or גֵּחֲזִי; apparently from 1516 and 2372; valley of a visionary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4975>/H9021', 'opaque', 'heb', 'מֹתֶן', '["môthen"]', '["hips/ your","loins/ your"]', '["n-m"]', 'properly, the waist or small of the back; only in plural the loins greyhound, loins, side.', 'from an unused root meaning to be slender;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4938B}/H9020/[H4937]', 'inflected', 'heb', 'מִשְׁעֵנָה', '["mishʻênâh"]', '["staff/ my"]', '["n-f"]', 'support (abstractly), i.e. (figuratively) sustenance or (concretely) a walking-stick staff.', 'or מִשְׁעֶנֶת; feminine of 4937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1522}/[H1516]', 'inflected', 'heb', 'גֵּיחֲזִי', '["Gêychăzîy"]', '["and/ Gehazi"]', '["n-pr-m"]', 'Gechazi, the servant of Elisha Gehazi.', 'or גֵּחֲזִי; apparently from 1516 and 2372; valley of a visionary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2237}/[H2114]', 'inflected', 'heb', 'זָרַר', '["zârar"]', '["and/ he sneezed"]', '["v"]', 'perhaps to diffuse, i.e. (specifically) to sneeze sneeze.', 'a primitive root (compare 2114);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7121G}/H9034/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ he summoned/ her"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318G}\/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ she went out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1537H}/H9011/[H1536]', 'inflected', 'heb', 'גִּלְגָּל', '["Gilgâl"]', '["<the>/ Gilgal/ towards"]', '["n-pr-loc"]', 'Gilgal, the name of three places in Palestine Gilgal. See also 1019.', 'the same as 1536 (with the article as a properly, noun);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8239}/[H8239]', 'lemma', 'heb', 'שָׁפַת', '["shâphath"]', '["put on","you will establish"]', '["v"]', 'to locate, i.e. (generally) hang on or (figuratively) establish, reduce bring, ordain, set on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1310}/[H1310]', 'inflected', 'heb', 'בָּשַׁל', '["bâshal"]', '["and/ cook"]', '["v"]', 'properly, to boil up; hence, to be done in cooking; figuratively to ripen bake, boil, bring forth, roast, seethe, sod (be sodden).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0219B}/[H216]', 'lemma', 'heb', 'אוֹרָה', '["ʼôwrâh"]', '["herbs"]', '["n-f"]', 'luminousness, i.e. (figuratively) prosperity; also a plant (as being bright) herb, light.', 'feminine of 216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704I>', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["[the] field"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6498}/[H6497]', 'lemma', 'heb', 'פַּקֻּעָה', '["paqquʻâh"]', '["gourds of"]', '["n-f"]', 'the wild cucumber (from splitting open to shed its seeds) gourd.', 'from the same as 6497;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6398}/[H6398]', 'inflected', 'heb', 'פָּלַח', '["pâlach"]', '["and/ he sliced [them]"]', '["v"]', 'to slice, i.e. break open or pierce bring forth, cleave, cut, shred, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5138}/[H2102]', 'inflected', 'heb', 'נָזִיד', '["nâzîyd"]', '["<the>/ cooked food","the/ cooked food"]', '["n-m"]', 'something boiled, i.e. soup pottage.', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0398}/H9048/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["when/ ate/ they"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5138}/[H2102]', 'inflected', 'heb', 'נָזִיד', '["nâzîyd"]', '["some of/ the/ cooked food"]', '["n-m"]', 'something boiled, i.e. soup pottage.', 'from 2102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5518A}/[H5518]', 'inflected', 'heb', 'סִיר', '["çîyr"]', '["[is] in the/ pot","in <the>/ pots","in the/ pot"]', '["n-m"]', 'a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn.', 'or (feminine) סִירָה; or סִרָה; (Jeremiah 52:18), from a primitive root meaning to boil up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5518A}\/[H5518]', 'inflected', 'heb', 'סִיר', '["çîyr"]', '["in the/ pot"]', '["n-m"]', 'a pot; also a thorn (as springing up rapidly); by implication, a hook caldron, fishhook, pan, (wash-)pot, thorn.', 'or (feminine) סִירָה; or סִרָה; (Jeremiah 52:18), from a primitive root meaning to boil up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1190}/[H1168]', 'inflected', 'heb', 'בַּעַל שָׁלִשָׁה', '["Baʻal Shâlishâh"]', '["from/ Baal"]', '["n-pr-loc"]', 'Baal of Shalishah, Baal-Shalishah, a place in Palestine Baal-shalisha.', 'from 1168 and 8031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1190}/[H1168]', 'lemma', 'heb', 'בַּעַל שָׁלִשָׁה', '["Baʻal Shâlishâh"]', '["Shalisha"]', '["n-pr-loc"]', 'Baal of Shalishah, Baal-Shalishah, a place in Palestine Baal-shalisha.', 'from 1168 and 8031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6861>/H9023', 'inflected', 'heb', 'בצקלנו', '["be./tzik.lo.N/o"]', '["in/ sack/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3498}/[H3498]', 'inflected', 'heb', 'יָתַר', '["yâthar"]', '["and/ they will have more than enough","and/ we have had more than enough"]', '["v"]', 'to jut over or exceed; by implication, to excel; (intransitively) to remain or be left; causatively to leave, cause to abound, preserve excel, leave (a remnant), left behind, too much, make plenteous, preserve, (be, let) remain(-der, -ing, -nant), reserve, residue, rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5283I}/[H5282]', 'inflected', 'heb', 'נַעֲמָן', '["Naʻămân"]', '["and/ Naaman"]', '["n-pr-m"]', 'Naaman, the name of an Israelite and of a Damascene Naaman.', 'the same as 5282;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5375Q}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ [one] uplifted of","and/ [you are] lifting up","and/ be lifted up","and/ lifted up of","and/ you may lift up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0758I}/[H759]', 'inflected', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["to/ Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5283I}/[H5282]', 'lemma', 'heb', 'נַעֲמָן', '["Naʻămân"]', '["Naaman"]', '["n-pr-m"]', 'Naaman, the name of an Israelite and of a Damascene Naaman.', 'the same as 5282;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0305}/[H253]', 'lemma', 'heb', 'אַחֲלַי', '["ʼachălay"]', '["would that!"]', '["inj"]', 'would that! O that, would God.', 'or אַחֲלֵי; prob from 253 and a variation of 3863;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6883}/H9023/[H6879]', 'inflected', 'heb', 'צָרַעַת', '["tsâraʻath"]', '["from/ skin disease/ his"]', '["n-f"]', 'leprosy leprosy.', 'from 6879;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5612A}/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["the/ document","the/ documents","the/ letter","the/ letters","the/ scroll"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7121J}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["when/ read aloud"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0430G}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["¿/ God","¿/ a God"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0622}/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["[is] to/ gather","to/ deliver","to/ gather"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5483M>/H9023', 'inflected', 'heb', 'בסוסיו', '["be./su.so/v"]', '["with/ horses/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7393G}/H9023/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["and/ with/ chariot[s]/ his"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0477}/[H474]', 'inflected', 'heb', 'אֱלִישָׁע', '["ʼĔlîyshâʻ"]', '["of/ Elisha"]', '["n-pr-m"]', 'Elisha, the famous prophet Elisha.', 'contracted for 474.;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0549H}/[H548]', 'lemma', 'heb', 'אֲמָנָה', '["ʼĂmânâh"]', '["[are] Amana"]', '["n-pr-loc"]', 'Amanah, a mountain near Damascus Amana.', 'the same as 548;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6554}/[H6565]', 'inflected', 'heb', 'פַּרְפַּר', '["Parpar"]', '["and/ Pharpar"]', '["n-pr"]', 'Parpar, a river of Syria Pharpar.', 'probably from 6565 in the sense of rushing; rapid;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1320}/[H1319]', 'inflected', 'heb', 'בָּשָׂר', '["bâsâr"]', '["[is] like/ [the] flesh of","like/ [the] flesh of"]', '["n-m"]', 'flesh (from its freshness); by extension, body, person; also (by euphemistically) the pudenda of a man body, (fat, lean) flesh(-ed), kin, (man-) kind, nakedness, self, skin.', 'from 1319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6505}/[H6504]', 'lemma', 'heb', 'פֶּרֶד', '["pered"]', '["mules"]', '["n-m"]', 'a mule (perhaps from his lonely habits) mule.', 'from 6504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7417A}/[H7416]', 'lemma', 'heb', 'רִמּוֹן', '["Rimmôwn"]', '["Rimmon"]', '["n-pr-m n-pr-loc"]', 'Rimmon, the name of a Syrian deity, also of five places in Palestine Remmon, Rimmon.', 'or (shorter) (רִמֹּן; or רִמּוֹנוֹ; (1 Chronicles 6:62 (77)), the same as 7416; in Joshua 19:13: הַמְּתֹאָר is mistaken for part of a name; article with the passive participle of 8388; the (one) marked off, i.e. which pertains).');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7812}/H9040/[H7812]', 'inflected', 'heb', 'שָׁחָה', '["shâchâh"]', '["when/ bow down/ I"]', '["v"]', 'to depress, i.e. prostrate (especially reflexive, in homage to royalty or God) bow (self) down, crouch, fall down (flat), humbly beseech, do (make) obeisance, do reverence, make to stoop, worship.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0776G>\', 'opaque', 'heb', 'אֶרֶץ', '["ʼerets"]', '["land"]', '["n-f"]', 'the earth (at large, or partitively a land) × common, country, earth, field, ground, land, × natins, way, + wilderness, world.', 'from an unused root probably meaning to be firm;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0761H}/[H758]', 'inflected', 'heb', 'אֲרַמִּי', '["ʼĂrammîy"]', '["the/ Aramean"]', '["a"]', 'an Aramite or Aramaean Syrian, Aramitess.', 'patrial from 758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3947H}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["from/ accepting"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2754}/[H2747]', 'lemma', 'heb', 'חָרִיט', '["chârîyṭ"]', '["bags"]', '["n-m"]', 'properly, cut out (or hollow), i.e. (by implication) a pocket bag, crisping pin.', 'or חָרִט; from the same as 2747;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6076A}/[H6075]', 'inflected', 'heb', 'עֹפֶל', '["ʻôphel"]', '["the/ hill"]', '["n-m"]', 'a tumor; also a mound, i.e. fortress emerod, fort, strong hold, tower.', 'from 6075;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6485L}/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ he deposited [them]"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H6256}/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["¿/ [does] a time","¿/ a time"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3947H}/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ to/ accept","and/ to/ take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6883}/[H6879]', 'inflected', 'heb', 'צָרַעַת', '["tsâraʻath"]', '["and/ [the] skin disease of"]', '["n-f"]', 'leprosy leprosy.', 'from 6879;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H6440G}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["from/ to/ before/ him"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7950}\/[H7949]', 'inflected', 'heb', 'שֶׁלֶג', '["sheleg"]', '["like <the>/ snow"]', '["n-m"]', 'snow (probably from its whiteness) snow(-y).', 'from 7949;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440H}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6982}/[H6979]', 'lemma', 'heb', 'קוֹרָה', '["qôwrâh"]', '["[the] beams of","a beam"]', '["n-f"]', 'a rafter (forming trenches as it were); by implication, a roof beam, roof.', 'or קֹרָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1504}/[H1504]', 'inflected', 'heb', 'גָּזַר', '["gâzar"]', '["and/ it devoured","and/ they cut down"]', '["v"]', 'to cut down or off; (figuratively) to destroy, divide, exclude, or decide cut down (off), decree, divide, snatch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6982}/[H6979]', 'inflected', 'heb', 'קוֹרָה', '["qôwrâh"]', '["the/ beam","the/ beams"]', '["n-f"]', 'a rafter (forming trenches as it were); by implication, a roof beam, roof.', 'or קֹרָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7094}/[H7094]', 'inflected', 'heb', 'קָצַב', '["qâtsab"]', '["and/ he cut off"]', '["v"]', 'to clip, or (generally) chop cut down, shorn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6687}/[H6687]', 'inflected', 'heb', 'צוּף', '["tsûwph"]', '["and/ he caused to float"]', '["v"]', 'to overflow (make to over-) flow, swim.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3947G}/H9033\/[H3947]', 'inflected', 'heb', 'לָקַח', '["lâqach"]', '["and/ he took/ it"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8466}/H9020/[H2583]', 'inflected', 'heb', 'תַּחֲנָה', '["tachănâh"]', '["encampments/ my"]', '["n-f"]', '(only plural collectively) an encampment camp.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5185}/[H5181]', 'lemma', 'heb', 'נָחֵת', '["nâchêth"]', '["[is] descending"]', '["a"]', 'descending come down.', 'from 5181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2094B}/H9033/[H2094]', 'inflected', 'heb', 'זָהַר', '["zâhar"]', '["and/ he warned/ him"]', '["v"]', 'to gleam; figuratively, to enlighten (by caution) admonish, shine, teach, (give) warn(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5590}/[H5590]', 'inflected', 'heb', 'סָעַר', '["çâʻar"]', '["and/ it was enraged"]', '["v"]', 'to rush upon; by implication, to toss (transitive or intransitive, literal or figurative) be (toss with) tempest(-uous), be sore, troubled, come out as a (drive with the, scatter with a) whirlwind.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9007/H9005/{H9035}', 'inflected', 'heb', 'משלנו', '["mi./she./La./nu"]', '["from/ [those] who/ [belong] to/ us"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0351}/[H349]', 'lemma', 'heb', 'אֵיכֹה', '["ʼêykôh"]', '["where?"]', '["adv"]', 'where where.', 'probably a variation for 349, but not as an interogative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2428A}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["and/ [the] army of","and/ an army"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5362B}/[H5362]', 'inflected', 'heb', 'נָקַף', '["nâqaph"]', '["and/ he has surrounded [me]","and/ they surrounded","and/ they will surround","and/ you will surround"]', '["v"]', 'to strike with more or less violence (beat, fell, corrode); by implication (of attack) to knock together, i.e. surround or circulate compass (about, -ing), cut down, destroy, go round (about), inclose, round.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6491}/[H6491]', 'lemma', 'heb', 'פָּקַח', '["pâqach"]', '["I will open","[are] opened","[is] opening","do you open","he opens","open","they are open","they will be opened"]', '["v"]', 'to open (the senses, especially the eyes); figuratively, to be observant open.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2090}/[H2088]', 'lemma', 'heb', 'זֹה', '["zôh"]', '["this"]', '["d"]', 'this or that as well as another, it, this, that, thus and thus.', 'for 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1245}/H9013/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["you seek/ !"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8111}/H9011/[H8104]', 'inflected', 'heb', 'שֹׁמְרוֹן', '["Shômᵉrôwn"]', '["Samaria/ towards"]', '["n-pr-loc"]', 'Shomeron, a place in Palestine Samaria.', 'from the active participle of 8104; watch-station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0935G}/H9048/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["when/ came/ they"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5221}/[H5221]', 'inflected', 'heb', 'נָכָה', '["nâkâh"]', '["¿/ will I strike [them] down"]', '["v"]', 'to strike (lightly or severely, literally or figuratively) beat, cast forth, clap, give (wounds), × go forward, × indeed, kill, make (slaughter), murderer, punish, slaughter, slay(-er, -ing), smite(-r, -ing), strike, be stricken, (give) stripes, × surely, wound.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H0834A}/[H834]', 'inflected', 'heb', 'אֲשֶׁר', '["ʼăsher"]', '["¿/ [those] whom"]', '["r"]', 'who, which, what, that; also (as an adverb and a conjunction) when, where, how, because, in order that, etc. × after, × alike, as (soon as), because, × every, for, + forasmuch, + from whence, + how(-soever), × if, (so) that ((thing) which, wherein), × though, + until, + whatsoever, when, where (+ -as, -in, -of, -on, -soever, -with), which, whilst, + whither(-soever), who(-m, -soever, -se). As it is indeclinable, it is often accompanied by the personal pronoun expletively, used to show the connection.', 'a primitive relative pronoun (of every gender and number);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7198}/H9021/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["and/ by/ bow/ your"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3739B}/[H3738]', 'inflected', 'heb', 'כָּרָה', '["kârâh"]', '["and/ he gave a feast"]', '["v"]', 'to purchase buy, prepare.', 'usually assigned as a primitive root, but probably only a special application of 3738 (through the common idea of planning implied in a bargain);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3740}/[H3739]', 'lemma', 'heb', 'כֵּרָה', '["kêrâh"]', '["a feast"]', '["n-f"]', 'a purchase provision.', 'from 3739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1130H}/[H1121]', 'lemma', 'heb', 'בֶּן־הֲדַד', '["Ben-Hădad"]', '["Ben","Hadad"]', '["n-pr-m"]', 'Ben-Hadad, the name of several Syrian kings Benhadad.', 'from 1121 and 1908; son of Hadad;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7255}/[H7251]', 'inflected', 'heb', 'רֹבַע', '["rôbaʻ"]', '["and/ [the] fourth part of"]', '["n-m"]', 'a quarter fourth participle', 'from 7251;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6894}/[H6895]', 'inflected', 'heb', 'קַב', '["qab"]', '["the/ kab"]', '["n-m"]', 'a hollow, i.e. vessel used as a (dry) measure cab.', 'from 6895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1686>', 'opaque', 'heb', 'דִּבְיוֹן', '["dibyôwn"]', '["quano<s>"]', '["n-m"]', 'probably some cheap vegetable, perhaps a bulbous root dove''s dung.', 'in the margin for the textual reading, חֶרְיוֹן; both, (in the plural only and) of uncertain derivation,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3467}/H9032/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["[am] deliverer/ your","deliverer/ your","he save/ you","will I save/ you"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7200I}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["¿/ do you see"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5429>', 'inflected', 'heb', 'וסאתים', '["u./se.''ah","ve./sa.Ta.yim"]', '["and/ a seah of","and/ two seahs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0699}/[H693]', 'lemma', 'heb', 'אֲרֻבָּה', '["ʼărubbâh"]', '["[the] windows of","windows"]', '["n-f"]', 'a lattice; (by implication) a window, dovecot (because of the pigeon-holes), chimney (with its apertures for smoke), sluice (with openings for water) chimney, window.', 'feminine participle passive of 693 (as if for lurking);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9035/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["they will put to death/ us","you kill/ us"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5399}/[H5398]', 'inflected', 'heb', 'נֶשֶׁף', '["nesheph"]', '["at <the>/ twilight","at/ twilight","in the/ twilight"]', '["n-m"]', 'properly, a breeze, i.e. (by implication) dusk (when the evening breeze prevails) dark, dawning of the day (morning), night, twilight.', 'from 5398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0136}/[H113]', 'inflected', 'heb', 'אֲדֹנָי', '["ʼĂdônây"]', '["and/ O Lord","and/ [the] Lord"]', '["n-m"]', 'the Lord (used as a proper name of God only) (my) Lord.', 'an emphatic form of 113;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5315H}/H9028/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["<of> life/ their","life/ their","own life/ their"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2442}/[H2707]', 'inflected', 'heb', 'חָכָה', '["châkâh"]', '["and/ I will wait","and/ we will delay"]', '["v"]', 'properly, to adhere to; hence, to await long, tarry, wait.', 'a primitive root (apparently akin to 2707 through the idea of piercing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4672}/H9035/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["and/ it will find/ us"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7778}/[H8176]', 'lemma', 'heb', 'שׁוֹעֵר', '["shôwʻêr"]', '["[the] gatekeeper of","[was] a gatekeeper of","[were] gatekeepers","gatekeepers"]', '["n-m"]', 'a janitor doorkeeper, porter.', 'or שֹׁעֵר active participle of 8176 (as denominative from 8179);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6963L>', 'inflected', 'heb', 'וקול', '["ve./Kol"]', '["and/ [the] sound of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8610}/H9038/[H8610]', 'inflected', 'heb', 'תָּפַשׂ', '["tâphas"]', '["and/ we will seize/ them"]', '["v"]', 'to manipulate, i.e. seize; chiefly to capture, wield, specifically, to overlay; figuratively, to use unwarrantably catch, handle, (lay, take) hold (on, over), stop, × surely, surprise, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2005}/H9048/[H2005]', 'inflected', 'heb', 'הֵן', '["hên"]', '["here [are]/ they","here/ they","there! [are]/ they","there/ they"]', '["prt"]', 'lo!; also (as expressing surprise) if behold, if, lo, though.', 'a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2648}/H9048/[H2648]', 'inflected', 'heb', 'חָפַז', '["châphaz"]', '["in/ hurrying/ of them"]', '["v"]', 'properly, to start up suddenly, i.e. (by implication) to hasten away, to fear (make) haste (away), tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7429}/H9033/[H7429]', 'inflected', 'heb', 'רָמַס', '["râmaç"]', '["and/ it trampled/ it","and/ they trampled/ him"]', '["v"]', 'to tread upon (as a potter, in walking or abusively) oppressor, stamp upon, trample (under feet), tread (down, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7429}/[H7429]', 'inflected', 'heb', 'רָמַס', '["râmaç"]', '["and/ it trampled","and/ they trampled"]', '["v"]', 'to tread upon (as a potter, in walking or abusively) oppressor, stamp upon, trample (under feet), tread (down, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004M}/H9022/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ household/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1481A}/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["and/ sojourn","and/ sojourners"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7458}/[H7456]', 'inflected', 'heb', 'רָעָב', '["râʻâb"]', '["[are] for the/ famine","for <the>/ famine","to <the>/ famine","to the/ famine"]', '["n-m"]', 'hunger (more or less extensive) dearth, famine, famished, hunger.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6817}/[H6817]', 'inflected', 'heb', 'צָעַק', '["tsâʻaq"]', '["to/ cry out"]', '["v"]', 'to shriek; (by implication) to proclaim (an assembly) × at all, call together, cry (out), gather (selves) (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704G>/H9024', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["field/ her"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5608A}/H9012/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["recount/ !"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1130H}/[H1121]', 'inflected', 'heb', 'בֶּן־הֲדַד', '["Ben-Hădad"]', '["and/ Ben"]', '["n-pr-m"]', 'Ben-Hadad, the name of several Syrian kings Benhadad.', 'from 1121 and 1908; son of Hadad;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4013}/H9028/[H1219]', 'inflected', 'heb', 'מִבְצָר', '["mibtsâr"]', '["fortifications/ their"]', '["n-m"]', 'a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold).', 'also (in plural) feminine (Daniel 11:l5) מִבְצָרָה; from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0970}/H9028/[H977]', 'inflected', 'heb', 'בָּחוּר', '["bâchûwr"]', '["and/ young men/ their"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5768}/H9028/[H5763]', 'inflected', 'heb', 'עוֹלֵל', '["ʻôwlêl"]', '["and/ children/ their"]', '["n-m"]', 'a suckling babe, (young) child, infant, little one.', 'or עֹלָל; from 5763;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7376}/[H7376]', 'lemma', 'heb', 'רָטַשׁ', '["râṭâsh"]', '["she was dashed in pieces","they will be dashed in pieces","they will dash in pieces","you will dash in pieces"]', '["v"]', 'to dash down dash (in pieces).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2030A}/H9028/[H2029]', 'inflected', 'heb', 'הָרֶה', '["hâreh"]', '["and/ pregnant [women]/ their"]', '["a-f"]', 'pregnant (be, woman) with child, conceive, × great.', 'or הָרִי; (Hosea 14:1), from 2029;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4346}/[H3527]', 'inflected', 'heb', 'מַכְבָּר', '["makbâr"]', '["the/ coverlet"]', '["n-m"]', 'a cloth (as netted) thick cloth.', 'from 3527 in the sense of covering; (compare 4345)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3141H}/[H3088]', 'inflected', 'heb', 'יוֹרָם', '["Yôwrâm"]', '["of/ Joram"]', '["n-pr-m"]', 'Joram, the name of three Israelites and one Syrian Joram.', 'a form of 3088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3141J}/[H3088]', 'lemma', 'heb', 'יוֹרָם', '["Yôwrâm"]', '["Joram"]', '["n-pr-m"]', 'Joram, the name of three Israelites and one Syrian Joram.', 'a form of 3088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6811}/H9011/[H6810]', 'inflected', 'heb', 'צָעִיר', '["Tsâʻîyr"]', '["Zair/ towards"]', '["n-pr-loc"]', 'Tsair, a place in Idumaea Zair.', 'the same as 6810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5437H}/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["which/ was surrounding","who/ go around"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0274H}/[H270]', 'lemma', 'heb', 'אֲחַזְיָה', '["ʼĂchazyâh"]', '["Ahaziah","O Ahaziah"]', '["n-pr-m"]', 'Achazjah, the name of a Jewish and an Israelite king Ahaziah.', 'or (prolonged) אֲחַזְיָהוּ ; from 270 and 3050; Jah has seized;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6271G}/[H6270]', 'lemma', 'heb', 'עֲתַלְיָה', '["ʻĂthalyâh"]', '["Athaliah","[was] Athaliah"]', '["n-pr-m n-pr-f"]', 'Athaljah, the name of an Israelitess and two Israelites Athaliah.', 'or עֲתַלְיָהוּ; from the same as 6270 and 3050; Jah has constrained;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3141H}/[H3088]', 'lemma', 'heb', 'יוֹרָם', '["Yôwrâm"]', '["Joram"]', '["n-pr-m"]', 'Joram, the name of three Israelites and one Syrian Joram.', 'a form of 3088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0761H}/[H758]', 'lemma', 'heb', 'אֲרַמִּי', '["ʼĂrammîy"]', '["[the] Arameans"]', '["a"]', 'an Aramite or Aramaean Syrian, Aramitess.', 'patrial from 758;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7414K}/[H7413]', 'inflected', 'heb', 'רָמָה', '["Râmâh"]', '["at <the>/ Ramah"]', '["n-pr-loc"]', 'Ramah, the name of four places in Palestine Ramah.', 'the same as 7413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3898A}/H9043/[H3898]', 'inflected', 'heb', 'לָחַם', '["lâcham"]', '["when/ fought/ he"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0274H}/[H270]', 'inflected', 'heb', 'אֲחַזְיָה', '["ʼĂchazyâh"]', '["and/ Ahaziah"]', '["n-pr-m"]', 'Achazjah, the name of a Jewish and an Israelite king Ahaziah.', 'or (prolonged) אֲחַזְיָהוּ ; from 270 and 3050; Jah has seized;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3092J}/[H3068]', 'lemma', 'heb', 'יְהוֹשָׁפָט', '["Yᵉhôwshâphâṭ"]', '["Jehoshaphat"]', '["n-pr-m n-pr-loc"]', 'Jehoshaphat, the name of six Israelites; also of a valley near Jerusalem Jehoshaphat. Compare 3146.', 'from 3068 and 8199; Jehovah-judged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6965B}/H9033/[H6965]', 'inflected', 'heb', 'קוּם', '["qûwm"]', '["and/ you will make rise/ him"]', '["v"]', 'to rise (in various applications, literal, figurative, intensive and causative) abide, accomplish, × be clearer, confirm, continue, decree, × be dim, endure, × enemy, enjoin, get up, make good, help, hold, (help to) lift up (again), make, × but newly, ordain, perform, pitch, raise (up), rear (up), remain, (a-) rise (up) (again, against), rouse up, set (up), (e-) stablish, (make to) stand (up), stir up, strengthen, succeed, (as-, make) sure(-ly), (be) up(-hold, -rising).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2442}/[H2707]', 'lemma', 'heb', 'חָכָה', '["châkâh"]', '["[those who] wait","he had waited","he is waiting","it waits","they waited","wait","you must delay"]', '["v"]', 'properly, to adhere to; hence, to await long, tarry, wait.', 'a primitive root (apparently akin to 2707 through the idea of piercing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3605}/H9025/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["from/ all of/ us"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2506A}/[H2505]', 'inflected', 'heb', 'חֵלֶק', '["chêleq"]', '["in/ [the] territory of"]', '["n-m"]', 'properly, smoothness (of the tongue); also an allotment flattery, inheritance, part, × partake, portion.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3058H}/[H3068]', 'inflected', 'heb', 'יֵהוּא', '["Yêhûwʼ"]', '["and/ Jehu"]', '["n-pr-m"]', 'Jehu, the name of five Israelites Jehu.', 'from 3068 and 1931; Jehovah (is) He;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7696}/[H7696]', 'inflected', 'heb', 'שָׁגַע', '["shâgaʻ"]', '["the/ mad [man]"]', '["v"]', 'to rave through insanity (be, play the) mad (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7879}/H9023/[H7878]', 'inflected', 'heb', 'שִׂיחַ', '["sîyach"]', '["complaint/ his","talk/ his"]', '["n-m"]', 'a contemplation; by implication, an utterance babbling, communication, complaint, meditation, prayer, talk.', 'from 7878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3141H}/[H3088]', 'inflected', 'heb', 'יוֹרָם', '["Yôwrâm"]', '["and/ Joram"]', '["n-pr-m"]', 'Joram, the name of three Israelites and one Syrian Joram.', 'a form of 3088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6822}/[H6822]', 'inflected', 'heb', 'צָפָה', '["tsâphâh"]', '["and/ the/ watchman"]', '["v"]', 'properly, to lean forward, i.e. to peer into the distance; by implication, to observe, await behold, espy, look up (well), wait for, (keep the) watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8229}/[H8228]', 'lemma', 'heb', 'שִׁפְעָה', '["shiphʻâh"]', '["[the] crowd of","a crowd","a multitude of"]', '["n-f"]', 'copiousness abundance, company, multitude.', 'feminine of 8228;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7395}/[H7392]', 'lemma', 'heb', 'רַכָּב', '["rakkâb"]', '["a horseman"]', '["n-m"]', 'a charioteer chariot man, driver of a chariot, horseman.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7965G}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["and/ for/ allies","and/ to/ peace"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4491}/[H5090]', 'inflected', 'heb', 'מִנְהָג', '["minhâg"]', '["and/ the/ driving"]', '["n-m"]', 'the driving (of a chariot) driving.', 'from 5090;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4491}/[H5090]', 'inflected', 'heb', 'מִנְהָג', '["minhâg"]', '["[is] like/ [the] driving of"]', '["n-m"]', 'the driving (of a chariot) driving.', 'from 5090;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7965G}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["<the>/ peace","[is] <the>/ peace"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2183}/[H2181]', 'lemma', 'heb', 'זָנוּן', '["zânûwn"]', '["[the] prostitutions of","prostitution<s>"]', '["n-m"]', 'adultery; figuratively, idolatry whoredom.', 'from 2181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3785}/H9024/[H3784]', 'inflected', 'heb', 'כֶּשֶׁף', '["kesheph"]', '["and/ sorceries/ her"]', '["n-m"]', 'magic sorcery, witchcraft.', 'from 3784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4820}/[H7411]', 'lemma', 'heb', 'מִרְמָה', '["mirmâh"]', '["[are] deceit","[is] deceit","deceit","deceit<s>","treachery"]', '["n-f"]', 'fraud craft, deceit(-ful, -fully), false, feigned, guile, subtilly, treachery.', 'from 7411 in the sense of deceiving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0920}/[H1856]', 'lemma', 'heb', 'בִּדְקַר', '["Bidqar"]', '["Bidkar"]', '["n-pr-m"]', 'Bidkar, an Israelite Bidkar.', 'probably from 1856 with a prepositional prefix; by stabbing, i.e. assassin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704B>', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["[the] field of","a field"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4853B}/[H5375]', 'inflected', 'heb', 'מַשָּׂא', '["massâʼ"]', '["the/ burden","the/ oracle"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004H}/[H1129]', 'lemma', 'heb', 'בַּיִת', '["bayith"]', '["Beth"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1588H}/[H1598]', 'lemma', 'heb', 'גַּן', '["gan"]', '["Haggan"]', '["n"]', 'a garden (as fenced) garden.', 'from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1483}/[H1482]', 'lemma', 'heb', 'גּוּר', '["Gûwr"]', '["Gur"]', '["n-pr-loc"]', 'Gur, a place in Palestine Gur.', 'the same as 1482;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6900}/H9023/[H6912]', 'inflected', 'heb', 'קְבוּרָה', '["qᵉbûwrâh"]', '["in/ grave/ his","in/ own grave/ his"]', '["n-f"]', 'sepulture; (concretely) a sepulchre burial, burying place, grave, sepulchre.', 'or קְבֻרָה; feminine passive participle of 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0348}/[H336]', 'inflected', 'heb', 'אִיזֶבֶל', '["ʼÎyzebel"]', '["and/ Jezebel"]', '["n-pr-f"]', 'Izebel, the wife of king Ahab Jezebel.', 'from 336 and 2083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6320>', 'inflected', 'heb', 'בפוך', '["ba./Pukh","ba./puKh","va./puKh"]', '["in <the>/ antimony","with <the>/ eye-paint"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6440N}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["face/ his"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8058}/H9034/[H8058]', 'inflected', 'heb', 'שָׁמַט', '["shâmaṭ"]', '["and/ they let fall/ her"]', '["v"]', 'to fling down; incipiently to jostle; figuratively, to let alone, desist, remit discontinue, overthrow, release, let rest, shake, stumble, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7429}/H9034/[H7429]', 'inflected', 'heb', 'רָמַס', '["râmaç"]', '["and/ he trampled/ her"]', '["v"]', 'to tread upon (as a potter, in walking or abusively) oppressor, stamp upon, trample (under feet), tread (down, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6912}/H9034/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["and/ bury/ her"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6912}/H9034/[H6912]', 'inflected', 'heb', 'קָבַר', '["qâbar"]', '["to/ bury/ her"]', '["v"]', 'to inter × in any wise, bury(-ier).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1538}/[H1556]', 'inflected', 'heb', 'גֻּלְגֹּלֶת', '["gulgôleth"]', '["the/ skull"]', '["n-f"]', 'a skull (as round); by implication, a head (in enumeration of persons) head, every man, poll, skull.', 'by reduplication from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7272}/[H7270]', 'inflected', 'heb', 'רֶגֶל', '["regel"]', '["and/ the/ feet"]', '["n-f"]', 'a foot (as used in walking); by implication, a step; by euphemistically the pudenda × be able to endure, × according as, × after, × coming, × follow, (broken-)foot(-ed, -stool), × great toe, × haunt, × journey, leg, piss, possession, time.', 'from 7270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3709G}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["and/ [the] palms of","and/ a hand"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H1828>', 'inflected', 'heb', 'כדמן', '["ke./Do.men"]', '["like/ dung"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0348}\/[H336]', 'inflected', 'heb', 'אִיזֶבֶל', '["ʼÎyzebel"]', '["[is] Jezebel"]', '["n-pr-f"]', 'Izebel, the wife of king Ahab Jezebel.', 'from 336 and 2083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0256G}/[H251]', 'inflected', 'heb', 'אַחְאָב', '["ʼAchʼâb"]', '["and/ [belonged] to/ Ahab"]', '["n-pr-m"]', 'Achab, the name of a king of Israel and of a prophet at Babylon Ahab.', 'once (by contraction) אֶחָב (Jeremiah 29:22); from 251 and 1; brother (i.e. friend) of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H5483M>', 'inflected', 'heb', 'והסוסים', '["ve./ha./Sus","ve./ha./su.Sim"]', '["and/ <the>/ horses","and/ the/ horse"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5402}/[H5401]', 'inflected', 'heb', 'נֶשֶׁק', '["nesheq"]', '["and/ <the>/ weaponry"]', '["n-m"]', 'military equipment, i.e. (collectively) arms (offensive or defensive), or (concretely) an arsenal armed men, armour(-y), battle, harness, weapon.', 'or נֵשֶׁק; from 5401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0539}/[H541]', 'inflected', 'heb', 'אָמַן', '["ʼâman"]', '["and/ the/ guardians"]', '["v"]', 'properly, to build up or support; to foster as a parent or nurse; figuratively to render (or be) firm or faithful, to trust or believe, to be permanent or quiet; morally to be true or certain; hence, assurance, believe, bring up, establish, fail, be faithful (of long continuance, stedfast, sure, surely, trusty, verified), nurse, (-ing father), (put), trust, turn to the right.', 'a primitive root; (Isaiah 30:21; interchangeable with 541, to go to the right hand)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H6963J>/H9020', 'inflected', 'heb', 'ולקלי', '["u./le./ko.L/i"]', '["and/ to/ voice/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6652}/[H6551]', 'lemma', 'heb', 'צִבֻּר', '["tsibbur"]', '["heaps"]', '["n-m"]', 'a pile heap.', 'from 6551;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1419A}/H9023/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["great [men]/ his"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3045}/H9023/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["and/ acquaintances/ his"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3548}/H9023/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["and/ priests/ his"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1044}/[H1004]', 'lemma', 'heb', 'בֵּית עֵקֶד', '["Bêyth ʻÊqed"]', '["Beth","Eked","Eked of","[was at] Beth"]', '["n-pr-loc"]', 'Beth-Eked, a place in Palestine shearing house.', 'from 1004 and a derivative of 6123; house of (the) binding (for sheep-shearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7462A}/[H7462]', 'lemma', 'heb', 'רָעָה', '["râʻâh"]', '["[the] Shepherds"]', '["v"]', 'to tend a flock; i.e. pasture it; intransitively, to graze (literally or figuratively); generally to rule; by extension, to associate with (as a friend) × break, companion, keep company with, devour, eat up, evil entreat, feed, use as a friend, make friendship with, herdman, keep (sheep) (-er), pastor, shearing house, shepherd, wander, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H9038}\', 'inflected', 'heb', 'מהם ס', '["me./Hem"]', '["from/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3082G}/[H3068]', 'lemma', 'heb', 'יְהוֹנָדָב', '["Yᵉhôwnâdâb"]', '["Jonadab"]', '["n-pr-m"]', 'Jehonadab, the name of an Israelite and of an Arab Jehonadab, Jonadab. Compare 3122.', 'from 3068 and 5068; Jehovah-largessed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7394H}/[H7392]', 'lemma', 'heb', 'רֵכָב', '["Rêkâb"]', '["Rechab"]', '["n-pr-m a"]', 'Rekab, the name of two Arabs and of two Israelites Rechab.', 'from 7392; rider;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3548}/H9023/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["priests/ his","priests/ its"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6122}/[H6117]', 'inflected', 'heb', 'עׇקְבָה', '["ʻoqbâh"]', '["with/ guile"]', '["n-f"]', 'trickery subtilty.', 'feminine of an unused form from 6117 meaning a trick;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310H}/[H6284]', 'lemma', 'heb', 'פֶּה', '["peh"]', '["[the] mouth of","mouth","mouths"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H4458>', 'inflected', 'heb', 'המלתחה', '["ha./mel.ta.Chah"]', '["the/ wardrobe"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3830}/[H3847]', 'lemma', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["<the> clothed of","[the] clothing of","clothing","clothing of"]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4403}/[H3847]', 'inflected', 'heb', 'מַלְבּוּשׁ', '["malbûwsh"]', '["the/ clothing"]', '["n-m"]', 'a garment, or (collectively) clothing apparel, raiment, vestment.', 'or מַלְבֻּשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3082G}/[H3068]', 'inflected', 'heb', 'יְהוֹנָדָב', '["Yᵉhôwnâdâb"]', '["and/ Jonadab"]', '["n-pr-m"]', 'Jehonadab, the name of an Israelite and of an Arab Jehonadab, Jonadab. Compare 3122.', 'from 3068 and 5068; Jehovah-largessed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027H}/H9026/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hands/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7991C}/[H7969]', 'inflected', 'heb', 'שָׁלִישׁ', '["shâlîysh"]', '["and/ to the/ officers"]', '["n-m"]', 'a triple, i.e. (as a musical instrument) a triangle (or perhaps rather three-stringed lute); also (as an indefinite, great quantity) a three-fold measure (perhaps a treble ephah); also (as an officer) a general of the third rank (upward, i.e. the highest) captain, instrument of musick, (great) lord, (great) measure, prince, three (from the margin).', 'or שָׁלוֹשׁ; (1 Chronicles 11:11; 1 Chronicles 12:18), or שָׁלֹשׁ; (2 Samuel 23:13), from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7991C}/[H7969]', 'inflected', 'heb', 'שָׁלִישׁ', '["shâlîysh"]', '["and/ the/ officers"]', '["n-m"]', 'a triple, i.e. (as a musical instrument) a triangle (or perhaps rather three-stringed lute); also (as an indefinite, great quantity) a three-fold measure (perhaps a treble ephah); also (as an officer) a general of the third rank (upward, i.e. the highest) captain, instrument of musick, (great) lord, (great) measure, prince, three (from the margin).', 'or שָׁלוֹשׁ; (1 Chronicles 11:11; 1 Chronicles 12:18), or שָׁלֹשׁ; (2 Samuel 23:13), from 7969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4163}/[H4161]', 'inflected', 'heb', 'מוֹצָאָה', '["môwtsâʼâh"]', '["<into>/ outhouses"]', '["n-f"]', 'a family descent; also a sewer draught house; going forth.', 'feminine of 4161; (marg.; compare 6675)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1835G}\/[H1777]', 'inflected', 'heb', 'דָּן', '["Dân"]', '["[were] in/ Dan"]', '["n-pr-m"]', 'Dan, one of the sons of Jacob; also the tribe descended from him, and its territory; likewise a place in Palestine colonized by them Daniel', 'from 1777; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7096}/[H7096]', 'inflected', 'heb', 'קָצָה', '["qâtsâh"]', '["to/ cut off"]', '["v"]', 'to cut off; (figuratively) to destroy; (partially) to scrape off cut off, cut short, scrape (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7206}/[H7205]', 'inflected', 'heb', 'רְאוּבֵנִי', '["Rᵉʼûwbênîy"]', '["and/ the/ Reubenite[s]"]', '["a"]', 'a Reubenite or descendant of Reuben children of Reuben, Reubenites.', 'patronymic from 7205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4520}/[H4519]', 'inflected', 'heb', 'מְנַשִּׁי', '["Mᵉnashshîy"]', '["and/ the/ Manassite[s]"]', '["a"]', 'a Menashshite or descendant of Menashsheh of Manasseh, Manassites.', 'from 4519;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3059G}/[H3068]', 'lemma', 'heb', 'יְהוֹאָחָז', '["Yᵉhôwʼâchâz"]', '["Jehoahaz"]', '["n-pr-m"]', 'Jehoachaz, the name of three Israelites Jehoahaz. Compare 3099.', 'from 3068 and 270; Jehovah-seized;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8111}\/[H8104]', 'inflected', 'heb', 'שֹׁמְרוֹן', '["Shômᵉrôwn"]', '["in/ Samaria"]', '["n-pr-loc"]', 'Shomeron, a place in Palestine Samaria.', 'from the active participle of 8104; watch-station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6271G}/[H6270]', 'inflected', 'heb', 'עֲתַלְיָה', '["ʻĂthalyâh"]', '["and/ Athaliah"]', '["n-pr-m n-pr-f"]', 'Athaljah, the name of an Israelitess and two Israelites Athaliah.', 'or עֲתַלְיָהוּ; from the same as 6270 and 3050; Jah has constrained;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3089}/[H3068]', 'lemma', 'heb', 'יְהוֹשֶׁבַע', '["Yᵉhôwshebaʻ"]', '["Jehosheba"]', '["n-pr-f"]', 'Jehosheba, an Israelitess Jehosheba. Compare 3090.', 'from 3068 and 7650; Jehovah-sworn;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3101I}/[H3060]', 'lemma', 'heb', 'יוֹאָשׁ', '["Yôwʼâsh"]', '["Joash"]', '["n-pr-m"]', 'Joash, the name of six Israelites Joash.', 'or יֹאָשׁ; (2 Chronicles 24:1), a form of 3060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3243I}/H9023/[H3243]', 'inflected', 'heb', 'יָנַק', '["yânaq"]', '["suckling-nurse/ his"]', '["v"]', 'to suck; causatively, to give milk milch, nurse(-ing mother), (give, make to) suck(-ing child, -ling).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3077H}/[H3068]', 'lemma', 'heb', 'יְהוֹיָדָע', '["Yᵉhôwyâdâʻ"]', '["Jehoiada"]', '["n-pr-m"]', 'Jehojada, the name of three Israelites Jehoiada. Compare 3111.', 'from 3068 and 3045; Jehovah-known;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3746}/[H3733]', 'inflected', 'heb', 'כָּרִי', '["kârîy"]', '["of the/ Carian[s]"]', '["a"]', 'a life-guardsman captains, Cherethites (from the margin).', 'perhaps an abridged plural of 3733 in the sense of leader (of the flock);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7323H}/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["and/ of the/ runners"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5495}/[H5494]', 'lemma', 'heb', 'סוּר', '["Çûwr"]', '["Sur"]', '["n"]', 'Sur, a gate of the temple Sur.', 'the same as 5494;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4535}/[H5255]', 'lemma', 'heb', 'מַסָּח', '["maççâch"]', '["by turns"]', '["n-m"]', 'a cordon, (adverbially) or (as a) military barrier broken down.', 'from 5255 in the sense of staving off;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3627}/H9023/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["and/ vessels/ its","and/ weapons/ his"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7713>', 'inflected', 'heb', 'השדרות', '["ha./se.de.Rot"]', '["the/ ranks"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0935G}/H9043/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ when/ came/ he","and/ when/ comes/ he","and/ when/ went/ he"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7982}/[H7980]', 'inflected', 'heb', 'שֶׁלֶט', '["sheleṭ"]', '["the/ shields"]', '["n-m"]', 'probably a shield (as controlling, i.e. protecting the person) shield.', 'from 7980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8269}/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["and/ the/ commanders","and/ the/ officials"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2689}/[H2690]', 'inflected', 'heb', 'חֲצֹצְרָה', '["chătsôtsᵉrâh"]', '["and/ the/ trumpets"]', '["n-f"]', 'a trumpet (from its sundered or quavering note) trumpet(-er).', 'by reduplication from 2690;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0899B}/H9024/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["clothes/ her"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7195}/[H7194]', 'lemma', 'heb', 'קֶשֶׁר', '["qesher"]', '["a conspiracy","a conspiracy of","conspiracy","treason"]', '["n-m"]', 'an (unlawful) alliance confederacy, conspiracy, treason.', 'from 7194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7195}\/[H7194]', 'inflected', 'heb', 'קֶשֶׁר', '["qesher"]', '["treason"]', '["n-m"]', 'an (unlawful) alliance confederacy, conspiracy, treason.', 'from 7194;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7713>', 'inflected', 'heb', 'לשדרת', '["la./se.de.Rot"]', '["to the/ ranks"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5422}/H9033/[H5422]', 'inflected', 'heb', 'נָתַץ', '["nâthats"]', '["and/ they pulled down/ it"]', '["v"]', 'to tear down beat down, break down (out), cast down, destroy, overthrow, pull down, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6754>/H9023', 'opaque', 'heb', 'צֶלֶם', '["tselem"]', '["images/ its"]', '["n-m"]', 'a phantom, i.e. (figuratively) illusion, resemblance; hence, a representative figure, especially an idol image, vain shew.', 'from an unused root meaning to shade;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4977G}/[H4976]', 'lemma', 'heb', 'מַתָּן', '["Mattân"]', '["Mattan"]', '["n-pr-m"]', 'Mattan, the name of a priest of Baal, and of an Israelite Mattan.', 'the same as 4976;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3746}/[H3733]', 'inflected', 'heb', 'כָּרִי', '["kârîy"]', '["the/ Carian[s]"]', '["a"]', 'a life-guardsman captains, Cherethites (from the margin).', 'perhaps an abridged plural of 3733 in the sense of leader (of the flock);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1004Q}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["from/ [the] house of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3060G}/[H3068]', 'lemma', 'heb', 'יְהוֹאָשׁ', '["Yᵉhôwʼâsh"]', '["Jehoash"]', '["n-pr-m"]', 'Jehoash, the name of two Israelite kings Jehoash. Compare 3101.', 'from 3068 and (perhaps) 784; Jehovah-fired;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4427A}/H9043\/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["when/ became king/ he"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3058H}/[H3068]', 'inflected', 'heb', 'יֵהוּא', '["Yêhûwʼ"]', '["of/ Jehu"]', '["n-pr-m"]', 'Jehu, the name of five Israelites Jehu.', 'from 3068 and 1931; Jehovah (is) He;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6645}/[H6646]', 'lemma', 'heb', 'צִבְיָּה', '["Tsibyâh"]', '["[was] Zibiah"]', '["n-pr-f"]', 'Tsibjah, an Israelite Zibiah.', 'for 6646;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3384B}/H9033/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["he instructed/ him","he teaches/ him"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4378}/H9023/[H5234]', 'inflected', 'heb', 'מַכָּר', '["makkâr"]', '["acquaintance/ his"]', '["n-m"]', 'an acquaintance acquaintance.', 'from 5234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0919}/[H918]', 'lemma', 'heb', 'בֶּדֶק', '["bedeq"]', '["[the] damage of"]', '["n-m"]', 'a gap or leak (in a building or a ship) breach, calker.', 'from 918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0919}\/[H918]', 'inflected', 'heb', 'בֶּדֶק', '["bedeq"]', '["damage"]', '["n-m"]', 'a gap or leak (in a building or a ship) breach, calker.', 'from 918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3077H}/[H3068]', 'inflected', 'heb', 'יְהוֹיָדָע', '["Yᵉhôwyâdâʻ"]', '["<to>/ Jehoiada"]', '["n-pr-m"]', 'Jehojada, the name of three Israelites Jehoiada. Compare 3111.', 'from 3068 and 3045; Jehovah-known;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4378}/H9026/[H5234]', 'inflected', 'heb', 'מַכָּר', '["makkâr"]', '["acquaintances/ your"]', '["n-m"]', 'an acquaintance acquaintance.', 'from 5234;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0919}/[H918]', 'inflected', 'heb', 'בֶּדֶק', '["bedeq"]', '["for/ [the] damage of"]', '["n-m"]', 'a gap or leak (in a building or a ship) breach, calker.', 'from 918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0225}/[H225]', 'inflected', 'heb', 'אוּת', '["ʼûwth"]', '["and/ they agreed"]', '["v"]', 'properly, to come, i.e. (implied) to assent consent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2356}/[H2352]', 'lemma', 'heb', 'חוֹר', '["chôwr"]', '["a hole","holes of"]', '["n-m"]', 'a cavity, socket, den cave, hole.', 'or (shortened) חֹר; the same as 2352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1817C}/H9023/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["in/ lid/ its"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4487}/[H4487]', 'inflected', 'heb', 'מָנָה', '["mânâh"]', '["and/ I will appoint","and/ he appointed","and/ he assigned","and/ they counted"]', '["v"]', 'properly, to weigh out; by implication, to allot or constitute officially; also to enumerate or enroll appoint, count, number, prepare, set, tell.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8505}/[H8505]', 'inflected', 'heb', 'תָּכַן', '["tâkan"]', '["<the>/ weighed out"]', '["v"]', 'to balance, i.e. measure out (by weight or dimension); figuratively to arrange, equalize, through the idea of levelling (ment, estimate, test) bear up, direct, be (un-)equal, mete, ponder, tell, weigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2796}/[H2790]', 'inflected', 'heb', 'חָרָשׁ', '["chârâsh"]', '["<to>/ craftsmen of","to the/ craftsmen","to/ [the] craftsmen of"]', '["n-m"]', 'a fabricator or any material artificer, ( ) carpenter, craftsman, engraver, maker, mason, skilful, ( ) smith, worker, workman, such as wrought.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6086K}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["<the>/ wood"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1129}/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["and/ to the/ builders","and/ to/ build","and/ to/ rebuild"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1443}/[H1443]', 'inflected', 'heb', 'גָּדַר', '["gâdar"]', '["and/ to the/ masons"]', '["v"]', 'to wall in or around close up, fence up, hedge, inclose, make up (a wall), mason, repairer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2672}/[H2672]', 'inflected', 'heb', 'חָצַב', '["châtsab"]', '["and/ to/ [the] cutters of"]', '["v"]', 'to cut or carve (wood, stone or other material); by implication, to hew, split, square, quarry, engrave cut, dig, divide, grave, hew (out, -er), made, mason.', 'or חָצֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7069}/[H7069]', 'inflected', 'heb', 'קָנָה', '["qânâh"]', '["and/ to/ acquire"]', '["v"]', 'to erect, i.e. create; by extension, to procure, especially by purchase (causatively, sell); by implication to own attain, buy(-er), teach to keep cattle, get, provoke to jealousy, possess(-or), purchase, recover, redeem, × surely, × verily.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4274}/[H2672]', 'lemma', 'heb', 'מַחְצֵב', '["machtsêb"]', '["hewing"]', '["n-m"]', 'properly, a hewing; concretely, a quarry hewed(-n).', 'from 2672;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5592A}/[H5605]', 'lemma', 'heb', 'סַף', '["çaph"]', '["a basin of","basins of"]', '["n-m"]', 'a vestibule (as a limit); also a dish (for holding blood or wine) bason, bowl, cup, door (post), gate, post, threshold.', 'from 5605, in its original sense of containing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4212}/[H2168]', 'lemma', 'heb', 'מְזַמְּרָה', '["mᵉzammᵉrâh"]', '["snuffers"]', '["n-f"]', 'a tweezer (only in the plural) snuffers.', 'from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5414N}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["to/ give"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0530}/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["[is] in/ faithfulness","in/ faithfulness","in/ truth"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3088G}/[H3068]', 'inflected', 'heb', 'יְהוֹרָם', '["Yᵉhôwrâm"]', '["and/ Jehoram"]', '["n-pr-m"]', 'Jehoram, the name of a Syrian and of three Israelites Jehoram, Joram. Compare 3141.', 'from 3068 and 7311; Jehovah-raised;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2371}/[H2372]', 'inflected', 'heb', 'חֲזָאֵל', '["Chăzâʼêl"]', '["to/ Hazael"]', '["n-pr-m"]', 'Chazael, a king of Syria Hazael.', 'or חֲזָהאֵל; from 2372 and 410; God has seen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5538}/[H5549]', 'lemma', 'heb', 'סִלָּא', '["Çillâʼ"]', '["Silla"]', '["n-m"]', 'Silla, a place in Jerusalem Silla.', 'from 5549; an embankment;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3107G}/[H3075]', 'inflected', 'heb', 'יוֹזָבָד', '["Yôwzâbâd"]', '["and/ Jozabad"]', '["n-pr-m"]', 'Jozabad, the name of ten Israelites Josabad, Jozabad.', 'a form of 3075;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8100}/[H8088]', 'lemma', 'heb', 'שִׁמְעַת', '["Shimʻath"]', '["Shimeath"]', '["n-pr-f"]', 'Shimath, an Ammonitess Shimath.', 'feminine of 8088; annunciation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3075G}/[H3068]', 'inflected', 'heb', 'יְהוֹזָבָד', '["Yᵉhôwzâbâd"]', '["and/ Jehozabad"]', '["n-pr-m"]', 'Jehozabad, the name of three Israelites Jehozabad. Compare 3107.', 'from 3068 and 2064; Jehovah-endowed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7763G}/[H8104]', 'lemma', 'heb', 'שׁוֹמֵר', '["Shôwmêr"]', '["Shomer"]', '["n-pr-m"]', 'Shomer, the name of two Israelites Shomer.', 'or שֹׁמֵר; active participle of 8104; keeper;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0558G}/[H553]', 'lemma', 'heb', 'אֲמַצְיָה', '["ʼĂmatsyâh"]', '["Amaziah"]', '["n-pr-m"]', 'Amatsjah, the name of four Israelites Amaziah.', 'or אֲמַצְיָהוּ; from 553 and 3050; strength of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3101I}/[H3060]', 'inflected', 'heb', 'יוֹאָשׁ', '["Yôwʼâsh"]', '["of/ Joash"]', '["n-pr-m"]', 'Joash, the name of six Israelites Joash.', 'or יֹאָשׁ; (2 Chronicles 24:1), a form of 3060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1130I}/[H1121]', 'lemma', 'heb', 'בֶּן־הֲדַד', '["Ben-Hădad"]', '["Ben","Hadad"]', '["n-pr-m"]', 'Ben-Hadad, the name of several Syrian kings Benhadad.', 'from 1121 and 1908; son of Hadad;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0168H}/H9028/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["in/ tents/ their"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2403B}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["from/ [the] sins of"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3059G}/[H3068]', 'inflected', 'heb', 'יְהוֹאָחָז', '["Yᵉhôwʼâchâz"]', '["to/ Jehoahaz"]', '["n-pr-m"]', 'Jehoachaz, the name of three Israelites Jehoahaz. Compare 3099.', 'from 3068 and 270; Jehovah-seized;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0006}/H9038/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["he had destroyed/ them","it will destroy/ them"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760A}/H9038/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ I will make/ them","and/ he had made/ them"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1758}/[H1758]', 'inflected', 'heb', 'דּוּשׁ', '["dûwsh"]', '["to/ thresh","to/ trample"]', '["v"]', 'to trample or thresh break, tear, thresh, tread out (down), at grass (Jeremiah 50:11, by mistake for 1877).', 'or דּוֹשׁ; or דִּישׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3101J}/[H3060]', 'lemma', 'heb', 'יוֹאָשׁ', '["Yôwʼâsh"]', '["Joash"]', '["n-pr-m"]', 'Joash, the name of six Israelites Joash.', 'or יֹאָשׁ; (2 Chronicles 24:1), a form of 3060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3060H}/[H3068]', 'lemma', 'heb', 'יְהוֹאָשׁ', '["Yᵉhôwʼâsh"]', '["Jehoash"]', '["n-pr-m"]', 'Jehoash, the name of two Israelite kings Jehoash. Compare 3101.', 'from 3068 and (perhaps) 784; Jehovah-fired;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3379H}/[H7378]', 'inflected', 'heb', 'יָרׇבְעָם', '["Yârobʻâm"]', '["and/ Jeroboam"]', '["n-pr-m"]', 'Jarobam, the name of two Israelite kings Jeroboam.', 'from 7378 and 5971; (the) people will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2671}/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["and/ an arrow","and/ an arrow of","and/ arrows"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0663I}/[H662]', 'inflected', 'heb', 'אֲפֵק', '["ʼĂphêq"]', '["in/ Aphek"]', '["n-pr-loc"]', 'Aphek (or Aphik), the name of three places in Palestine Aphek, Aphik.', 'or אֲפִיק; from 662 (in the sense of strength); fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1416}/[H1413]', 'inflected', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["and/ [the] marauding bands of"]', '["n-m"]', 'a crowd (especially of soldiers) army, band (of men), company, troop (of robbers).', 'from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2371}/[H2372]', 'inflected', 'heb', 'חֲזָאֵל', '["Chăzâʼêl"]', '["and/ Hazael"]', '["n-pr-m"]', 'Chazael, a king of Syria Hazael.', 'or חֲזָהאֵל; from 2372 and 410; God has seen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7993}/H9038/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["he threw/ them"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3101J}/[H3060]', 'inflected', 'heb', 'יוֹאָשׁ', '["Yôwʼâsh"]', '["of/ Joash"]', '["n-pr-m"]', 'Joash, the name of six Israelites Joash.', 'or יֹאָשׁ; (2 Chronicles 24:1), a form of 3060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3099H}/[H3059]', 'lemma', 'heb', 'יוֹאָחָז', '["Yôwʼâchâz"]', '["Jehoahaz"]', '["n-pr-m"]', 'Joachaz, the name of two Israelites Jehoahaz, Joahaz.', 'a form of 3059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3086}/[H3068]', 'lemma', 'heb', 'יְהוֹעַדִּין', '["Yᵉhôwʻaddîyn"]', '["[was] Jehoaddan"]', '["n-pr-f"]', 'Jehoaddin or Jehoaddan, an Israelitess Jehoaddan.', 'or יְהוֹעַדָּן; from 3068 and 5727; Jehovahpleased;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5554}/[H5553]', 'inflected', 'heb', 'סֶלַע', '["Çelaʻ"]', '["<the>/ Sela"]', '["n-pr-loc"]', 'Sela, the rock-city of Idumaea rock, Sela(-h).', 'the same as 5553;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3371H}/[H3348]', 'lemma', 'heb', 'יׇקְתְאֵל', '["Yoqthᵉʼêl"]', '["Joktheel"]', '["n-pr-loc"]', 'Joktheel, the name of a place in Palestine, and of one in Idumaea Joktheel.', 'probably from the same as 3348 and 410; veneration of God (compare 3354);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2336>', 'inflected', 'heb', 'החוחים', '["ha./Cho.ach","ha./cho.Chim"]', '["<the>/ thornbush","the/ thornbush","the/ thorns"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5414O}/H9012/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["give/ !"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375S}/H9031/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ it has lifted/ you"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7451C}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["[are] in/ trouble","in/ calamity","in/ distress","in/ trouble","on the/ evil","with/ harm","with/ troubles"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0558G}/[H553]', 'inflected', 'heb', 'אֲמַצְיָה', '["ʼĂmatsyâh"]', '["and/ Amaziah"]', '["n-pr-m"]', 'Amatsjah, the name of four Israelites Amaziah.', 'or אֲמַצְיָהוּ; from 553 and 3050; strength of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1053G}/[H1004]', 'inflected', 'heb', 'בֵּית שֶׁמֶשׁ', '["Bêyth Shemesh"]', '["at/ Beth"]', '["n-pr-loc"]', 'Beth-Shemesh, a place in Palestine Beth-shemesh.', 'from 1004 and 8121; house of (the) sun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0669H}/[H672]', 'lemma', 'heb', 'אֶפְרַיִם', '["ʼEphrayim"]', '["Ephraim"]', '["n-pr-m"]', 'Ephrajim, a son of Joseph; also the tribe descended from him, and its territory Ephraim, Ephraimites.', 'dual of masculine form of 672; double fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6438G}/[H6434]', 'inflected', 'heb', 'פִּנָּה', '["pinnâh"]', '["the/ corner"]', '["n-f"]', 'an angle; by implication, a pinnacle; figuratively, a chieftain bulwark, chief, corner, stay, tower.', 'feminine of 6434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0214}/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["and/ in/ [the] treasuries of"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8594}/[H6148]', 'inflected', 'heb', 'תַּעֲרֻבָה', '["taʻărubâh"]', '["the/ pledges"]', '["n-f"]', 'suretyship, i.e. (concretely) a pledge hostage.', 'from 6148;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3379H}/[H7378]', 'lemma', 'heb', 'יָרׇבְעָם', '["Yârobʻâm"]', '["Jeroboam"]', '["n-pr-m"]', 'Jarobam, the name of two Israelite kings Jeroboam.', 'from 7378 and 5971; (the) people will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5838x}', 'inflected', 'heb', 'עזריהו', '["''a.zar.Ya.hu","''a.zar.Yah"]', '["Azariah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0359A}/[H352]', 'lemma', 'heb', 'אֵילוֹת', '["ʼÊylôwth"]', '["Elath"]', '["n-pr-loc"]', 'Eloth or Elath, a place on the Red Sea Elath, Eloth.', 'or אֵילַת ; from 352; trees or a grove (i.e. palms);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725H}/H9034/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ he restored/ it"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0558G}/[H553]', 'inflected', 'heb', 'אֲמַצְיָה', '["ʼĂmatsyâh"]', '["of/ Amaziah"]', '["n-pr-m"]', 'Amatsjah, the name of four Israelites Amaziah.', 'or אֲמַצְיָהוּ; from 553 and 3050; strength of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3124}/[H3123]', 'lemma', 'heb', 'יוֹנָה', '["Yôwnâh"]', '["Jonah"]', '["n-pr-m"]', 'Jonah, an Israelite Jonah.', 'the same as 3123;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0573}/[H571]', 'lemma', 'heb', 'אֲמִתַּי', '["ʼĂmittay"]', '["Amittai"]', '["n-pr-m"]', 'Amittai, an Israelite Amittai.', 'from 571; veracious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1662}/[H1660]', 'inflected', 'heb', 'גַּת־הַחֵפֶר', '["Gath-ha-Chêpher"]', '["[was] from/ Gath"]', '["n-pr-loc"]', 'Gath-Chepher, a place in Palestine Gath-kephr, Gittah-kephr.', 'or (abridged) גִּתָּה־חֵפֶר; from 1660 and 2658 with the article inserted; wine-press of (the) well;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1662}/[H1660]', 'inflected', 'heb', 'גַּת־הַחֵפֶר', '["Gath-ha-Chêpher"]', '["<the>/ Hepher"]', '["n-pr-loc"]', 'Gath-Chepher, a place in Palestine Gath-kephr, Gittah-kephr.', 'or (abridged) גִּתָּה־חֵפֶר; from 1660 and 2658 with the article inserted; wine-press of (the) well;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4229A}/[H4229]', 'inflected', 'heb', 'מָחָה', '["mâchâh"]', '["to/ wipe out","to/ wiping out"]', '["v"]', 'properly, to stroke or rub; by implication, to erase; also to smooth (as if with oil), i.e. grease or make fat; also to touch, i.e. reach to abolish, blot out, destroy, full of marrow, put out, reach unto, × utterly, wipe (away, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148P}/[H2142]', 'lemma', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3379H}/[H7378]', 'inflected', 'heb', 'יָרׇבְעָם', '["Yârobʻâm"]', '["of/ Jeroboam"]', '["n-pr-m"]', 'Jarobam, the name of two Israelite kings Jeroboam.', 'from 7378 and 5971; (the) people will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3203}/[H3201]', 'lemma', 'heb', 'יְכׇלְיָה', '["Yᵉkolyâh"]', '["[was] Jecholiah"]', '["n-pr-f"]', 'Jekoljah or Jekiljah, an Israelitess Jecholiah, Jecoliah.', 'and יְכׇלְיָהוּ; or (2 Chronicles 26:3) יְכִילְיָה; from 3201 and 3050; Jah will enable;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2669}/[H2666]', 'inflected', 'heb', 'חׇפְשׁוּת', '["chophshûwth"]', '["<the>/ separateness"]', '["n-f"]', 'prostration by sickness several.', 'and חׇפְשִׁית; from 2666; (with 1004, a hospital)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3147H}/[H3068]', 'inflected', 'heb', 'יוֹתָם', '["Yôwthâm"]', '["and/ Jotham"]', '["n-pr-m"]', 'Jotham, the name of three Israelites Jotham.', 'from 3068 and 8535; Jehovah (is) perfect;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1004P}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["the/ house"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3147H}/[H3068]', 'lemma', 'heb', 'יוֹתָם', '["Yôwthâm"]', '["Jotham"]', '["n-pr-m"]', 'Jotham, the name of three Israelites Jotham.', 'from 3068 and 8535; Jehovah (is) perfect;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5838x}', 'inflected', 'heb', 'לעזריהו', '["la./''a.zar.Ya.hu","la./''a.zar.Yah"]', '["of/ Azariah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7967G}/[H7966]', 'lemma', 'heb', 'שַׁלּוּם', '["Shallûwm"]', '["Shallum"]', '["n-pr-m"]', 'Shallum, the name of fourteen Israelites Shallum.', 'or (shorter) שַׁלֻּם; the same as 7966;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3003H}/[H3002]', 'lemma', 'heb', 'יָבֵשׁ', '["Yâbêsh"]', '["Jabesh"]', '["n-pr-loc n-pr-m"]', 'Jobesh, the name of an Israelite and of a place in Palestine Jobesh (-Gilead).', 'the same as 3002 (also יָבֵישׁ; often with the addition of 1568, i.e. Jabesh of Gilad);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6905H}/[H6901]', 'lemma', 'heb', 'קָבָל', '["qâbâl"]', '["before"]', '["n-m"]', 'the presence, i.e. (adverbially) in front of before.', 'from 6901 in the sense of opposite (see 6904);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5971I}/[H6004]', 'lemma', 'heb', 'עַם', '["ʻam"]', '["[the] people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5818G}/[H5797]', 'inflected', 'heb', 'עֻזִּיָּה', '["ʻUzzîyâh"]', '["of/ Uzziah","to/ Uzziah"]', '["n-pr-m"]', 'Uzzijah, the name of five Israelites Uzziah.', 'or עֻזִּיָּהוּ; from 5797 and 3050; strength of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4505}/[H5162]', 'lemma', 'heb', 'מְנַחֵם', '["Mᵉnachêm"]', '["Menahem"]', '["n-pr-m"]', 'Menachem, an Israelite Menahem.', 'from 5162; comforter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1424}/[H1409]', 'lemma', 'heb', 'גָּדִי', '["Gâdîy"]', '["Gadi"]', '["n-pr-m"]', 'Gadi, an Israelite Gadi.', 'from 1409; fortunate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8656H}/[H7521]', 'inflected', 'heb', 'תִּרְצָה', '["Tirtsâh"]', '["from/ Tirzah"]', '["n-pr-f"]', 'Tirtsah, a place in Palestine; also an Israelitess Tirzah.', 'from 7521; delightsomeness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8607H}/[H6452]', 'lemma', 'heb', 'תִּפְסַח', '["Tiphçach"]', '["Tiphsah"]', '["n-pr-loc"]', 'Tiphsach, a place in Mesopotamia Tipsah.', 'from 6452; ford;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2030A}/H9024/[H2029]', 'inflected', 'heb', 'הָרֶה', '["hâreh"]', '["<the>/ pregnant [women]/ its"]', '["a-f"]', 'pregnant (be, woman) with child, conceive, × great.', 'or הָרִי; (Hosea 14:1), from 2029;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1234}\/[H1234]', 'inflected', 'heb', 'בָּקַע', '["bâqaʻ"]', '["he ripped open","they were split open","they will be ripped open"]', '["v"]', 'to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6322G>', 'opaque', 'heb', 'פּוּל', '["Pûwl"]', '["Pul"]', '["n-pr-m"]', 'Pul, the name of an Assyrian king and of an Ethiopian tribe Pul.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6322G>', 'inflected', 'heb', 'לפול', '["le./Ful"]', '["to/ Pul"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2388I}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["to/ strengthen"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027I}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["in/ hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6494}/[H6491]', 'lemma', 'heb', 'פְּקַחְיָה', '["Pᵉqachyâh"]', '["Pekahiah"]', '["n-pr-m"]', 'Pekachjah, an Israelite king Pekahiah.', 'from 6491 and 3050; Jah has observed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6492}/[H6491]', 'lemma', 'heb', 'פֶּקַח', '["Peqach"]', '["Pekah"]', '["n-pr-m"]', 'Pekach, an Israelite king Pekah.', 'from 6491; watch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7425>', 'opaque', 'heb', 'רְמַלְיָהוּ', '["Rᵉmalyâhûw"]', '["Remaliah"]', '["n-pr-m"]', 'Remaljah, an Israelite Remaliah.', 'from an unused root and 3050 (perhaps meaning to deck); Jah has bedecked;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0759G>', 'inflected', 'heb', 'בארמון', '["be./''ar.Mon"]', '["in/ [the] fortress of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0709H}/[H7263]', 'lemma', 'heb', 'אַרְגֹּב', '["ʼArgôb"]', '["Argob"]', '["n-pr-loc n-pr-m"]', 'Argob, a district of Palestine Argob.', 'from the same as 7263; stony;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0745}/[H738]', 'inflected', 'heb', 'אַרְיֵה', '["ʼAryêh"]', '["<the>/ Arieh"]', '["n-pr-m"]', 'Arjeh, an Israelite Arieh.', 'the same as 738; lion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1569}/[H1568]', 'lemma', 'heb', 'גִּלְעָדִי', '["Gilʻâdîy"]', '["[the] Gileadites"]', '["a"]', 'a Giladite or descendant of Gilad Gileadite.', 'patronymically from 1568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8407}/[H8407]', 'lemma', 'heb', 'תִּגְלַת פִּלְאֶסֶר', '["Tiglath Pilʼeçer"]', '["Tiglath-","pileser"]', '["n-pr-m"]', 'Tiglath-Pileser or Tilgath-pilneser, an Assyryrian king Tiglath-pileser, Tilgath-pilneser.', 'or תִּגְלַת פְּלֶסֶר; or תִּלְגַּת פִּלְנְאֶסֶר or תִּלְגַּת פִּלְנֶסֶר; of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3239A}/[H3240]', 'lemma', 'heb', 'יָנוֹחַ', '["Yânôwach"]', '["Janoah"]', '["n-pr-loc"]', 'Janoach, a place in Palestine Janoah, Janohah.', 'from 3240; quiet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1551}/H9011/[H1550]', 'inflected', 'heb', 'גָּלִיל', '["Gâlîyl"]', '["<the>/ Galilee/ towards"]', '["n-pr-loc"]', 'Galil (as a special circuit) in the North of Palestine Galilee.', 'or (prolonged) גָּלִילָה; the same as 1550; a circle (with the article);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1540K}/H9038/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["and/ he took into exile/ them","and/ he will take into exile/ them","and/ people took into exile/ them"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1954G}/[H3467]', 'lemma', 'heb', 'הוֹשֵׁעַ', '["Hôwshêaʻ"]', '["Hoshea"]', '["n-pr-m"]', 'Hoshea, the name of five Israelites Hosea, Hoshea, Oshea.', 'from 3467; deliverer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0425I}/[H424]', 'lemma', 'heb', 'אֵלָה', '["ʼÊlâh"]', '["Elah"]', '["n-pr"]', 'Elah, the name of an Edomite, of four Israelites, and also of a place in Palestine Elah.', 'the same as 424;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3147H}/[H3068]', 'inflected', 'heb', 'יוֹתָם', '["Yôwthâm"]', '["of/ Jotham"]', '["n-pr-m"]', 'Jotham, the name of three Israelites Jotham.', 'from 3068 and 8535; Jehovah (is) perfect;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5818G}/[H5797]', 'lemma', 'heb', 'עֻזִּיָּה', '["ʻUzzîyâh"]', '["O Uzziah","Uzziah"]', '["n-pr-m"]', 'Uzzijah, the name of five Israelites Uzziah.', 'or עֻזִּיָּהוּ; from 5797 and 3050; strength of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6492}/[H6491]', 'inflected', 'heb', 'פֶּקַח', '["Peqach"]', '["of/ Pekah"]', '["n-pr-m"]', 'Pekach, an Israelite king Pekah.', 'from 6491; watch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3388}/[H3423]', 'lemma', 'heb', 'יְרוּשָׁא', '["Yᵉrûwshâʼ"]', '["[was] Jerusha"]', '["n-pr-f"]', 'Jerusha or Jerushah, as Israelitess Jerusha, Jerushah.', 'or יְרוּשָׁה feminine passive participle of 3423; possessed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6659H}/[H6663]', 'lemma', 'heb', 'צָדוֹק', '["Tsâdôwq"]', '["Zadok"]', '["n-pr-m"]', 'Tsadok, the name of eight or nine Israelites Zadok.', 'from 6663; just;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7526G}/[H7522]', 'lemma', 'heb', 'רְצִין', '["Rᵉtsîyn"]', '["Rezin"]', '["n-pr-m"]', 'Retsin, the name of a Syrian and of an Israelite Rezin.', 'probably for 7522;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0271G}/[H270]', 'lemma', 'heb', 'אָחָז', '["ʼÂchâz"]', '["Ahaz"]', '["n-pr-m"]', 'Achaz, the name of a Jewish king and of an Israelite Ahaz.', 'from 270; possessor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6999H}/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["and/ he made smoke","and/ they have made smoke","and/ they made smoke"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6492}/[H6491]', 'inflected', 'heb', 'פֶּקַח', '["Peqach"]', '["and/ Pekah"]', '["n-pr-m"]', 'Pekach, an Israelite king Pekah.', 'from 6491; watch;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3064}/[H3063]', 'inflected', 'heb', 'יְהוּדִי', '["Yᵉhûwdîy"]', '["[are] the/ Jews","of the/ Jews","the/ Jew","the/ Jews"]', '["n-m"]', 'a Jehudite (i.e. Judaite or Jew), or descendant of Jehudah (i.e. Judah) Jew.', 'patronymically from 3063;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0359B}/[H352]', 'inflected', 'heb', 'אֵילוֹת', '["ʼÊylôwth"]', '["from/ Elath"]', '["n-pr-loc"]', 'Eloth or Elath, a place on the Red Sea Elath, Eloth.', 'or אֵילַת ; from 352; trees or a grove (i.e. palms);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0130}/[H123]', 'inflected', 'heb', 'אֱדֹמִי', '["ʼĔdômîy"]', '["and/ Edomites"]', '["a"]', 'an Edomite, or descendants from (or inhabitants of) Edom Edomite.', 'or (fully) אֱדוֹמִי ; patronymic from 123; See 726.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3467}/H9030/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ deliver/ me","and/ he will save/ me","and/ it saves/ me","and/ save/ me"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1540K}/H9034/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["and/ he took into exile/ it"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7024B}/H9011/[H7023]', 'inflected', 'heb', 'קִיר', '["Qîyr"]', '["Kir/ towards"]', '["n-pr-loc"]', 'Kir, a place in Assyrian; also one in Moab Kir. Compare 7025.', 'the same as 7023; fortress;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0223G}/[H217]', 'lemma', 'heb', 'אוּרִיָּה', '["ʼÛwrîyâh"]', '["Uriah"]', '["n-pr-m"]', 'Urijah, the name of one Hittite and five Israelites Uriah, Urijah.', 'or (prolonged) אוּרִיָּהוּ ; from 217 and 3050; flame of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1823}/[H1819]', 'lemma', 'heb', 'דְּמוּת', '["dᵉmûwth"]', '["[the] likeness of","a likeness","a likeness of","likeness"]', '["n-f"]', 'resemblance; concretely, model, shape; adverbially, like fashion, like (-ness, as), manner, similitude.', 'from 1819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8403}/H9023/[H1129]', 'inflected', 'heb', 'תַּבְנִית', '["tabnîyth"]', '["pattern/ its"]', '["n-f"]', 'structure; by implication, a model, resemblance figure, form, likeness, pattern, similitude.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1834>', 'inflected', 'heb', 'מדמשק', '["mi./da.Ma.sek","mi./da.Me.sek"]', '["from/ Damascus"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0996G}/[H995]', 'inflected', 'heb', 'בֵּין', '["bêyn"]', '["and/ from/ between"]', '["prep"]', 'between (repeated before each noun, often with other particles); also as a conjunction, either...or among, asunder, at, between (-twixt...and), + from (the widest), × in, out of, whether (it be...or), within.', '(sometimes in the plural masculine or feminine); properly, the constructive form of an otherwise unused noun from 995; a distinction; but used only as a preposition,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4196}/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["and/ [the] altar of"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1239}/[H1239]', 'inflected', 'heb', 'בָּקַר', '["bâqar"]', '["to/ consider","to/ consult"]', '["v"]', 'properly, to plough, or (generally) break forth, i.e. (figuratively) to inspect, admire, care for, consider (make) inquire (-ry), (make) search, seek out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4837}/[H7528]', 'lemma', 'heb', 'מַרְצֶפֶת', '["martsepheth"]', '["a pavement of"]', '["n-f"]', 'a pavement pavement.', 'from 7528;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4329}/[H5526]', 'lemma', 'heb', 'מֵיסָךְ', '["mêyçâk"]', '["[the] covered structure of"]', '["n-m"]', 'a portico (as covered) covert.', 'from 5526;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2435}/[H2434]', 'inflected', 'heb', 'חִיצוֹן', '["chîytsôwn"]', '["<the>/ external","<the>/ outer","<the>/ outside","the/ outer"]', '["a"]', 'properly, the (outer) wall side; hence, exterior; figuratively, secular (as opposed to sacred) outer, outward, utter, without.', 'from 2434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2396G}/[H2388]', 'lemma', 'heb', 'חִזְקִיָּה', '["Chizqîyâh"]', '["Hezekiah","[is] Hezekiah"]', '["n-pr-m"]', 'Chizkijah, a king of Judah, also the name of two other Israelites Hezekiah, Hizkiah, Hizkijah. Compare 3169.', 'or חִזְקִיָּהוּ; also יְחִזְקִיָּה; or יְחִזְקִיָּהוּ; from 2388 and 3050; strengthened of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0271G}/[H270]', 'inflected', 'heb', 'אָחָז', '["ʼÂchâz"]', '["of/ Ahaz"]', '["n-pr-m"]', 'Achaz, the name of a Jewish king and of an Israelite Ahaz.', 'from 270; possessor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4428G}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["like/ [the] kings of","like/ a king"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8022}/[H8022]', 'lemma', 'heb', 'שַׁלְמַנְאֶסֶר', '["Shalmanʼeçer"]', '["Shalmaneser"]', '["n-pr-m"]', 'Shalmaneser, an Assyrian king Shalmaneser. Comp 8020.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1954G}/[H3467]', 'inflected', 'heb', 'הוֹשֵׁעַ', '["Hôwshêaʻ"]', '["in/ Hoshea"]', '["n-pr-m"]', 'Hoshea, the name of five Israelites Hosea, Hoshea, Oshea.', 'from 3467; deliverer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5471}/[H5471]', 'lemma', 'heb', 'סוֹא', '["Çôwʼ"]', '["So"]', '["n-pr-m"]', 'So, an Egyptian king So.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8141}/[H8138]', 'inflected', 'heb', 'שָׁנֶה', '["shâneh"]', '["as/ a year","like/ [the] years of"]', '["n-f"]', 'a year (as a revolution of time) whole age, × long, old, year(× -ly).', '(in plural or (feminine) שָׁנָה; from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6113}/H9033/[H6113]', 'inflected', 'heb', 'עָצָר', '["ʻâtsâr"]', '["and/ he arrested/ him"]', '["v"]', 'to inclose; by analogy, to hold back; also to maintain, rule, assemble × be able, close up, detain, fast, keep (self close, still), prevail, recover, refrain, × reign, restrain, retain, shut (up), slack, stay, stop, withhold (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3608}/[H3607]', 'lemma', 'heb', 'כֶּלֶא', '["keleʼ"]', '["imprisonment","imprisonment<s>"]', '["n-m"]', 'a prison prison. Compare 3610, 3628.', 'from 3607;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1954G}/[H3467]', 'inflected', 'heb', 'הוֹשֵׁעַ', '["Hôwshêaʻ"]', '["of/ Hoshea"]', '["n-pr-m"]', 'Hoshea, the name of five Israelites Hosea, Hoshea, Oshea.', 'from 3467; deliverer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1540K}/[H1540]', 'inflected', 'heb', 'גָּלָה', '["gâlâh"]', '["and/ I will send into exile","and/ he took into exile","and/ he uncovered","and/ it went into exile","and/ they will go into exile","and/ you will go into exile"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2477>', 'inflected', 'heb', 'בחלח', '["ba/ch.Lach"]', '["in/ Halah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2249}/[H2266]', 'inflected', 'heb', 'חָבוֹר', '["Châbôwr"]', '["and/ on/ [the] Habor"]', '["n-pr-loc"]', 'Chabor, a river of Assyria Habor.', 'from 2266; united;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1470}/[H1468]', 'lemma', 'heb', 'גּוֹזָן', '["Gôwzân"]', '["Gozan"]', '["n-pr-loc"]', 'Gozan, a province of Assyria Gozan.', 'probably from 1468; a quarry (as a place of cutting stones);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4074I}\/[H4074]', 'inflected', 'heb', 'מָדַי', '["Mâday"]', '["Media"]', '["n-pr-m n-pr-loc"]', 'Madai, a country of central Asia Madai, Medes, Media.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2644}/[H2645]', 'inflected', 'heb', 'חָפָא', '["châphâʼ"]', '["and/ they did secretly"]', '["v"]', 'properly, to cover, i.e. (in a sinister sense) to act covertly do secretly.', 'an orthographical variation of 2645;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4026M}/[H1431]', 'inflected', 'heb', 'מִגְדָּל', '["migdâl"]', '["from/ a tower of"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1870G}/H9026/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["from/ ways/ your","more than/ ways/ your"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6203}/H9028/[H6202]', 'inflected', 'heb', 'עֹרֶף', '["ʻôreph"]', '["neck/ their"]', '["n-m"]', 'the nape or back of the neck (as declining); hence, the back generally (whether literal or figurative) back ((stiff-) neck((-ed).', 'from 6202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6203}/[H6202]', 'inflected', 'heb', 'עֹרֶף', '["ʻôreph"]', '["like/ [the] neck of"]', '["n-m"]', 'the nape or back of the neck (as declining); hence, the back generally (whether literal or figurative) back ((stiff-) neck((-ed).', 'from 6202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3988A}/[H3988]', 'inflected', 'heb', 'מָאַס', '["mâʼaç"]', '["and/ I will reject","and/ he rejected","and/ they have rejected","and/ they rejected","and/ you have rejected"]', '["v"]', 'to spurn; also (intransitively) to disappear abhor, cast away (off), contemn, despise, disdain, (become) loathe(some), melt away, refuse, reject, reprobate, × utterly, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5715}/H9023/[H5707]', 'inflected', 'heb', 'עֵדוּת', '["ʻêdûwth"]', '["testimonies/ his"]', '["n-f"]', 'testimony testimony, witness.', 'feminine of 5707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1892}/[H1891]', 'inflected', 'heb', 'הֶבֶל', '["hebel"]', '["<the>/ vanity"]', '["n-m"]', 'emptiness or vanity; figuratively, something transitory and unsatisfactory; often used as an adverb × altogether, vain, vanity.', 'or (rarely in the abs.) הֲבֵל; from 1891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1891}/[H1891]', 'inflected', 'heb', 'הָבַל', '["hâbal"]', '["and/ they became vain"]', '["v"]', 'to be vain in act, word, or expectation; specifically to lead astray be (become, make) vain.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7080}/[H7080]', 'inflected', 'heb', 'קָסַם', '["qâçam"]', '["and/ they divined"]', '["v"]', 'properly, to distribute, i.e. determine by lot or magical scroll; by implication, to divine divine(-r, -ation), prudent, soothsayer, use (divination).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5172}/[H5172]', 'inflected', 'heb', 'נָחַשׁ', '["nâchash"]', '["and/ he practiced divination","and/ they practiced divination"]', '["v"]', 'properly, to hiss, i.e. whisper a (magic) spell; generally, to prognosticate × certainly, divine, enchanter, (use) × enchantment, learn by experience, × indeed, diligently observe.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6031B}/H9038/[H6030]', 'inflected', 'heb', 'עָנָה', '["ʻânâh"]', '["and/ he afflicted/ them"]', '["v"]', 'to depress literally or figuratively, transitive or intransitive (in various applications, as follows) abase self, afflict(-ion, self), answer (by mistake for 6030), chasten self, deal hardly with, defile, exercise, force, gentleness, humble (self), hurt, ravish, sing (by mistake for 6030), speak (by mistake for 6030), submit self, weaken, × in any wise.', 'a primitive root (possibly rather identical with 6030 through the idea of looking down or browbeating);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2398}/H9038/[H2398]', 'inflected', 'heb', 'חָטָא', '["châṭâʼ"]', '["and/ he caused to sin/ them"]', '["v"]', 'properly, to miss; hence (figuratively and generally) to sin; by inference, to forfeit, lack, expiate, repent, (causatively) lead astray, condemn bear the blame, cleanse, commit (sin), by fault, harm he hath done, loss, miss, (make) offend(-er), offer for sin, purge, purify (self), make reconciliation, (cause, make) sin(-ful, -ness), trespass.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0894}/[H1101]', 'inflected', 'heb', 'בָּבֶל', '["Bâbel"]', '["from/ Babylon"]', '["n-pr-loc"]', 'Babel (i.e. Babylon), including Babylonia and the Babylonian empire Babel, Babylon.', 'from 1101; confusion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H3575>/H9011', 'inflected', 'heb', 'ומכותה', '["u./Mi./ku.ta/h"]', '["and/ from/ Cuthah/ <towards>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5755}/[H5754]', 'inflected', 'heb', 'עִוָּה', '["ʻIvvâh"]', '["and/ from/ Avva"]', '["n-pr-loc"]', 'Ivvah or Avva, a region of Assyria Ava, Ivah.', 'or עַוָּא; (2 Kings 17:24), for 5754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2574G}/[H2346]', 'inflected', 'heb', 'חֲמָת', '["Chămâth"]', '["and/ from/ Hamath"]', '["n-pr-loc n-pr-m"]', 'Chamath, a place in Syria Hamath, Hemath.', 'from the same as 2346; walled;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5617}/[H5617]', 'inflected', 'heb', 'סְפַרְוַיִם', '["Çᵉpharvayim"]', '["and/ Sepharvaim"]', '["n-pr-loc"]', 'Sepharvajim or Sepharim Sepharvaim.', '(dual); or סְפָרִים; of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5892B}/H9024/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["in/ cities/ its"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3427}/H9048/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["dwelling/ they"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4941I}/[H8199]', 'lemma', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["[the] custom of"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0369}/H9048/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["not/ they"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1980O}/[H3212]', 'lemma', 'heb', 'הָלַךְ', '["hâlak"]', '["[which were] going","take"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H3548}/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["from/ the/ priests","more than/ the/ priests","of/ the/ priests"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3384B}/H9038/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["so/ he may teach/ them"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430J}/H9023/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["gods/ his","own gods/ its"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8118}/[H8111]', 'inflected', 'heb', 'שֹׁמרֹנִי', '["Shômrônîy"]', '["the/ Samaritans"]', '["n-pr-m"]', 'a Shomeronite (collectively) or inhabitants of Shomeron Samaritans.', 'patrial from 8111;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5524}/[H5523]', 'lemma', 'heb', 'סֻכּוֹת בְּנוֹת', '["Çukkôwth bᵉnôwth"]', '["Benoth","Succoth"]', '["n"]', 'booths of (the) daughters; brothels, i.e. idoalatrous tents for impure purpose Succothbenoth.', 'from 5523 and the (irregular) plural of 1323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3575>', 'opaque', 'heb', 'כּוּת', '["Kûwth"]', '["Cuthah"]', '["n-pr-loc"]', 'Cuth or Cuthah, a province of Assyria Cuth.', 'or (feminine) כּוּתָה; of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5370>', 'opaque', 'heb', 'נֵרְגַּל', '["Nêrᵉgal"]', '["Nergal"]', '["n-pr-m"]', 'Nergal, a Cuthite deity Nergal.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0807>', 'opaque', 'heb', 'אַשִׁימָא', '["ʼAshîymâʼ"]', '["Ashima"]', '["n-pr-m"]', 'Ashima, a deity of Hamath Ashima.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5761I}/[H5757]', 'inflected', 'heb', 'עַוִּים', '["ʻAvvîym"]', '["and/ the/ Avvites"]', '["n-pr-m n-pr-loc"]', 'Avvim (as inhabited by Avvites), a place in Palestine (with the article prefix) Avim.', 'plural of 5757;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5026>', 'opaque', 'heb', 'נִבְחַז', '["Nibchaz"]', '["Nibhaz"]', '["n-pr-m"]', 'Nibchaz, a deity of the Avites Nibhaz.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8662}/[H8662]', 'lemma', 'heb', 'תַּרְתָּק', '["Tartâq"]', '["Tartak"]', '["n-pr"]', 'Tartak, a deity of the Avvites Tartak.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5616}/[H5617]', 'inflected', 'heb', 'סְפַרְוִי', '["Çᵉpharvîy"]', '["and/ the/ Sepharvites"]', '["a"]', 'a Sepharvite or inhabitant of Sepharvain Sepharvite.', 'patrial from 5617;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0152G}/[H142]', 'inflected', 'heb', 'אֲדְרַמֶּלֶךְ', '["ʼĂdrammelek"]', '["to/ Adrammelech"]', '["n-pr-m"]', 'Adrammelek, the name of an Assyrian idol, also of a son of Sennacherib Adrammelech.', 'from 142 and 4428; splendor of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6048>', 'inflected', 'heb', 'וענמלך', '["va./''a.na.Me.lekh"]', '["and/ Anammelech"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5617}/[H5617]', 'lemma', 'heb', 'סְפַרְוַיִם', '["Çᵉpharvayim"]', '["Sepharvaim"]', '["n-pr-loc"]', 'Sepharvajim or Sepharim Sepharvaim.', '(dual); or סְפָרִים; of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0369}/H9048/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["and/ not [are]/ they","and/ not/ they","and/ there not [are]/ they","and/ there not [will be]/ them"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2708}/H9028/[H2706]', 'inflected', 'heb', 'חֻקָּה', '["chuqqâh"]', '["according to/ statutes/ their"]', '["n-f"]', 'appointed, custom, manner, ordinance, site, statute.', 'feminine of 2706, and meaning substantially the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4941G}/H9028/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ according to/ judgment/ their"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H8451}/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["and/ according to the/ law"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4687}/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["and/ according to the/ commandment","and/ according to/ [the] command of"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7760M}/[H7760]', 'lemma', 'heb', 'שׂוּם', '["sûwm"]', '["he made"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1285}/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["and/ the/ covenant"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6456}/H9028/[H6458]', 'inflected', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["idols/ their"]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0021}/[H1]', 'lemma', 'heb', 'אֲבִי', '["ʼĂbîy"]', '["[was] Abi"]', '["n-pr-f"]', 'Abi, Hezekiah''s mother Abi.', 'from 1; fatherly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148C}/[H2142]', 'lemma', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5180}/[H5178]', 'lemma', 'heb', 'נְחֻשְׁתָּן', '["Nᵉchushtân"]', '["Nehushtan"]', '["n"]', 'something made of copper, i.e. the copper serpent of the Desert Nehushtan.', 'from 5178;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4775}/[H4775]', 'inflected', 'heb', 'מָרַד', '["mârad"]', '["and/ he rebelled","and/ they rebelled"]', '["v"]', 'to rebel rebel(-lious).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4013}\/[H1219]', 'inflected', 'heb', 'מִבְצָר', '["mibtsâr"]', '["fortification"]', '["n-m"]', 'a fortification, castle, or fortified city; figuratively, a defender (de-, most) fenced, fortress, (most) strong (hold).', 'also (in plural) feminine (Daniel 11:l5) מִבְצָרָה; from 1219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2396G}/[H2388]', 'inflected', 'heb', 'חִזְקִיָּה', '["Chizqîyâh"]', '["of/ Hezekiah","to/ Hezekiah"]', '["n-pr-m"]', 'Chizkijah, a king of Judah, also the name of two other Israelites Hezekiah, Hizkiah, Hizkijah. Compare 3169.', 'or חִזְקִיָּהוּ; also יְחִזְקִיָּה; or יְחִזְקִיָּהוּ; from 2388 and 3050; strengthened of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4074I}/[H4074]', 'lemma', 'heb', 'מָדַי', '["Mâday"]', '["Media"]', '["n-pr-m n-pr-loc"]', 'Madai, a country of central Asia Madai, Medes, Media.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5674D}/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["and/ they had transgressed"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5576>', 'opaque', 'heb', 'סַנְחֵרִיב', '["Çanchêrîyb"]', '["Sennacherib"]', '["n-pr-m"]', 'Sancherib, an Assyrian king Sennacherib.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1219}/[H1210]', 'inflected', 'heb', 'בָּצַר', '["bâtsar"]', '["<the>/ fortified"]', '["v"]', 'to gather grapes; also to be isolated (i.e. inaccessible by height or fortification) cut off, (de-) fenced, fortify, (grape) gather(-er), mighty things, restrain, strong, wall (up), withhold.', 'a primitive root; to clip off; specifically (as denominative from 1210)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0547}/[H544]', 'inflected', 'heb', 'אֹמְנָה', '["ʼômᵉnâh"]', '["the/ door-posts"]', '["n-f"]', 'a column pillar.', 'feminine active participle of 544 (in the original sense of supporting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0804G}\/[H833]', 'inflected', 'heb', 'אַשּׁוּר', '["ʼAshshûwr"]', '["Assyria"]', '["n-pr-m n-pr-loc"]', 'Ashshur, the second son of Shem; also his descendants and the country occupied by them (i.e. Assyria), its region and its empire Asshur, Assur, Assyria, Assyrians. See 838.', 'or אַשֻּׁר; apparently from 833 (in the sense of successful);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8661}/[H8661]', 'lemma', 'heb', 'תַּרְתָּן', '["Tartân"]', '["[the] commander in chief","[the] supreme commander"]', '["n-m"]', 'Tartan, an Assyrian Tartan.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7249G}/[H7227]', 'lemma', 'heb', 'רַב־סָרִיס', '["Rab-Çârîyç"]', '["[the] chief","court-official"]', '["n-pr-m"]', 'Rab-Saris, a Babylonian official Rab-saris.', 'from 7227 and a foreign word for a eunuch; chief chamberlain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7262}/[H7227]', 'lemma', 'heb', 'רַבְשָׁקֵה', '["Rabshâqêh"]', '["[the] chief","commander"]', '["n-m"]', 'Rabshakeh, a Babylonian official Rabshakeh.', 'from 7227 and 8248; chief butler;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2428A}/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["with/ an army","with/ an army of"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704H>', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["[the] field of"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3526G}/[H3526]', 'lemma', 'heb', 'כָּבַס', '["kâbaç"]', '["[the] washer"]', '["v"]', 'to trample; hence, to wash (properly, by stamping with the feet), whether literal (including the fulling process) or figurative fuller, wash(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0471G}/[H410]', 'lemma', 'heb', 'אֶלְיָקִים', '["ʼElyâqîym"]', '["Eliakim"]', '["n-pr-m"]', 'Eljakim, the name of four Israelites Eliakim.', 'from 410 and 6965; God of raising;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2518G}/[H2506]', 'lemma', 'heb', 'חִלְקִיָּה', '["Chilqîyâh"]', '["Hilkiah"]', '["n-pr-m"]', 'Chilhijah, the name of eight Israelites Hillkiah.', 'or חִלְקִיָּהוּ; from 2506 and 3050; portion of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7644>', 'inflected', 'heb', 'ושבנה', '["ve./shev.Na''","ve./shev.Nah"]', '["and/ Shebna"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5608B}/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["<the>/ scribe","the/ scribe"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3098G}/[H3068]', 'inflected', 'heb', 'יוֹאָח', '["Yôwʼâch"]', '["and/ Joah"]', '["n-pr-m"]', 'Joach, the name of four Israelites Joah.', 'from 3068 and 251; Jehovah-brothered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0623G}/[H622]', 'lemma', 'heb', 'אָסָף', '["ʼÂçâph"]', '["Asaph"]', '["n-pr-m"]', 'Asaph, the name of three Israelites, and of the family of the first Asaph.', 'from 622; collector;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0986}/[H982]', 'inflected', 'heb', 'בִּטָּחוֹן', '["biṭṭâchôwn"]', '["[is] the/ trust"]', '["n-m"]', 'trust confidence, hope.', 'from 982;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1369}/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["and/ might","and/ strength"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4938B}/[H4937]', 'lemma', 'heb', 'מִשְׁעֵנָה', '["mishʻênâh"]', '["[the] staff of","a staff of"]', '["n-f"]', 'support (abstractly), i.e. (figuratively) sustenance or (concretely) a walking-stick staff.', 'or מִשְׁעֶנֶת; feminine of 4937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7533}/[H7533]', 'inflected', 'heb', 'רָצַץ', '["râtsats"]', '["<the>/ crushed","who/ crush"]', '["v"]', 'to crack in pieces, literally or figuratively break, bruise, crush, discourage, oppress, struggle together.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5344A}/H9034/[H5344]', 'inflected', 'heb', 'נָקַב', '["nâqab"]', '["and/ it will pierce/ it"]', '["v"]', 'to puncture, literally (to perforate, with more or less violence) or figuratively (to specify, designate, libel) appoint, blaspheme, bore, curse, express, with holes, name, pierce, strike through.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6547L}/[H6547]', 'lemma', 'heb', 'פַּרְעֹה', '["Parʻôh"]', '["Pharaoh"]', '["n-m"]', 'Paroh, a general title of Egyptian kings Pharaoh.', 'of Egyptian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0982}/[H982]', 'inflected', 'heb', 'בָּטַח', '["bâṭach"]', '["the/ [ones who] trust","those/ [who] rely","those/ [who] trust","those/ relying","who/ trusts"]', '["v"]', 'properly, to hie for refuge (but not so precipitately as 2620); figuratively, to trust, be confident or sure be bold (confident, secure, sure), careless (one, woman), put confidence, (make to) hope, (put, make to) trust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1116>/H9023', 'opaque', 'heb', 'בָּמָה', '["bâmâh"]', '["high places/ his"]', '["n-f"]', 'an elevation height, high place, wave.', 'from an unused root (meaning to be high);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3389}/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["and/ <to>/ Jerusalem","and/ to/ Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7393G}/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["<to>/ chariotry","for/ chariotry"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6571B}/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["and/ <to>/ horsemen","and/ for/ horsemen"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9006/{H1107}/[H1077]', 'inflected', 'heb', 'בִּלְעֲדֵי', '["bilʻădêy"]', '["¿/ <from>/ without","¿/ from/ without"]', '["prt"]', 'except, without, besides beside, not (in), save, without.', 'or בַּלְעֲדֵי; constructive plural from 1077 and 5703, not till, i.e. (as preposition or adverb)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7843}/H9033/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["to/ destroy/ it"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7843}/H9034/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["and/ destroy/ it"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0762}/[H761]', 'lemma', 'heb', 'אֲרָמִית', '["ʼĂrâmîyth"]', '["Aramaic"]', '["adv"]', '(only adverbial) in Aramæan in the Syrian language (tongue), in Syriac.', 'feminine of 761;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3066}/[H3064]', 'lemma', 'heb', 'יְהוּדִית', '["Yᵉhûwdîyth"]', '["[in] Judean"]', '["a-f"]', 'the Jewish (used adverbially) language in the Jews'' language.', 'feminine of 3064;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5921A}/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["¿/ on","¿/ there-","¿/ to"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6675}/H9028/[H6674]', 'inflected', 'heb', 'צוֹאָה', '["tsôwʼâh"]', '["own excrement/ their"]', '["n-f"]', 'excrement; generally, dirt; figuratively, pollution dung, filth(-iness). Marg. for 2716.', 'or צֹאָה ; feminine of 6674;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4325G}/ /{H7272}/H9028/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["[the] water of/ /feet/ their"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5377}/[H5377]', 'lemma', 'heb', 'נָשָׁא', '["nâshâʼ"]', '["certainly <to deceive>","he deceive","he will deceive","it has deceived","they deceive","they have been deceived","you deceive","you have deceived"]', '["v"]', 'to lead astray, i.e. (mentally) to delude, or (morally) to seduce beguile, deceive, × greatly, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0953A}/H9023/[H952]', 'inflected', 'heb', 'בּוֹר', '["bôwr"]', '["own cistern/ his"]', '["n-m"]', 'a pit hole (especially one used as a cistern or a prison) cistern, dungeon, fountain, pit, well.', 'from 952 (in the sense of 877);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H0776G>/H9026', 'inflected', 'heb', 'כארצכם', '["ke./''ar.tze./Khem"]', '["like/ own land/ your"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5337}/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["¿/ did they deliver","¿/ have they delivered","¿/ really <to deliver>"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0774}/[H7502]', 'inflected', 'heb', 'אַרְפָּד', '["ʼArpâd"]', '["and/ Arpad"]', '["n-pr-loc"]', 'Arpad, a place in Syria Arpad, Arphad.', 'from 7502; spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2012}/[H2012]', 'lemma', 'heb', 'הֵנַע', '["Hênaʻ"]', '["Hena"]', '["n-pr-loc"]', 'Hena, a place apparently in Mesopotamia Hena.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5755}/[H5754]', 'inflected', 'heb', 'עִוָּה', '["ʻIvvâh"]', '["and/ Ivvah"]', '["n-pr-loc"]', 'Ivvah or Avva, a region of Assyria Ava, Ivah.', 'or עַוָּא; (2 Kings 17:24), for 5754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3470A}/[H3467]', 'lemma', 'heb', 'יְשַׁעְיָה', '["Yᵉshaʻyâh"]', '["Isaiah"]', '["n-pr-m"]', 'Jeshajah, the name of seven Israelites Isaiah, Jesaiah, Jeshaiah.', 'or יְשַׁעְיָהוּ; from 3467 and 3050; Jah has saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0531}/[H553]', 'lemma', 'heb', 'אָמוֹץ', '["ʼÂmôwts"]', '["Amoz"]', '["n-pr-m"]', 'Amots, an Israelite Amoz.', 'from 553; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8433A}/[H3198]', 'inflected', 'heb', 'תּוֹכֵחָה', '["tôwkêchâh"]', '["and/ rebuke"]', '["n-f"]', 'chastisement; figuratively (by words) correction, refutation, proof (even in defence) argument, × chastened, correction, reasoning, rebuke, reproof, × be (often) reproved.', 'and תּוֹכַחַת; from 3198;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5007A}/[H5006]', 'inflected', 'heb', 'נְאָצָה', '["nᵉʼâtsâh"]', '["and/ insult"]', '["n-f"]', 'scorn blasphemy.', 'or נֶאָצָה; from 5006;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4866}/[H7665]', 'lemma', 'heb', 'מִשְׁבֵּר', '["mishbêr"]', '["birth"]', '["n-m"]', 'the orifice of the womb (from which the fœtus breaks forth) birth, breaking forth.', 'from 7665;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7611}/[H7604]', 'inflected', 'heb', 'שְׁאֵרִית', '["shᵉʼêrîyth"]', '["the/ remainder","the/ remnant"]', '["n-f"]', 'a remainder or residual (surviving, final) portion that had escaped, be left, posterity, remain(-der), remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0776G>/H9023', 'inflected', 'heb', 'לארצו', '["le./''ar.Tz/o"]', '["for/ earth/ his","of/ land/ his","to/ own land/ his","to/ own land/ its"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5307J}/H9033/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ I will make fall/ him"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8640}/[H8640]', 'lemma', 'heb', 'תִּרְהָקָה', '["Tirhâqâh"]', '["Tirhakah"]', '["n-pr-m"]', 'Tirhakah, a king of Kush Tirhakah.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5377}/H9031/[H5377]', 'inflected', 'heb', 'נָשָׁא', '["nâshâʼ"]', '["he deceive/ you","it has deceived/ you","they will deceive/ you"]', '["v"]', 'to lead astray, i.e. (mentally) to delude, or (morally) to seduce beguile, deceive, × greatly, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7530}/[H7529]', 'inflected', 'heb', 'רֶצֶף', '["Retseph"]', '["and/ Rezeph"]', '["n-pr-loc"]', 'Retseph, a place in Assyria Rezeph.', 'the same as 7529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5729}/[H5727]', 'lemma', 'heb', 'עֶדֶן', '["ʻEden"]', '["Eden"]', '["n-pr-loc"]', 'Eden, a place in Mesopotamia Eden.', 'from 5727; pleasure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8515}/[H8515]', 'inflected', 'heb', 'תְּלַאשַּׂר', '["Tᵉlaʼssar"]', '["[were] in/ Telassar"]', '["n-pr-loc"]', 'Telassar, a region of Assyria Telassar.', 'or תְּלַשַּׂר; of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0335}/H9043/[H370]', 'inflected', 'heb', 'אַי', '["ʼay"]', '["where [is]?/ he"]', '["adv"]', 'where? hence how? how, what, whence, where, whether, which (way).', 'perhaps from 370;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0774}/[H7502]', 'lemma', 'heb', 'אַרְפָּד', '["ʼArpâd"]', '["Arpad"]', '["n-pr-loc"]', 'Arpad, a place in Syria Arpad, Arphad.', 'from 7502; spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7121J}/H9038/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ he read/ them"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6566}/H9033/[H6566]', 'inflected', 'heb', 'פָּרַשׂ', '["pâras"]', '["and/ he spread out/ it"]', '["v"]', 'to break apart, disperse, etc. break, chop in pieces, lay open, scatter, spread (abroad, forth, selves, out), stretch (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0241G}/H9021/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["ear/ your","ears/ your"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0905H}/H9031\/[H909]', 'inflected', 'heb', 'בַּד', '["bad"]', '["to/ alone/ you"]', '["n-m"]', 'properly, separation; by implication, a part of the body, branch of a tree, bar for carrying; figuratively, chief of a city; especially (with prepositional prefix) as an adverb, apart, only, besides alone, apart, bar, besides, branch, by self, of each alike, except, only, part, staff, strength.', 'from 909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3932}/[H3932]', 'lemma', 'heb', 'לָעַג', '["lâʻag"]', '["I will mock","[is] mocking","[one who] mocks","[which] it mocks","he mocks","she has mocked","stammering of","they mock","you mock","you will mock"]', '["v"]', 'to deride; by implication (as if imitating a foreigner) to speak unintelligibly have in derision, laugh (to scorn), mock (on), stammering.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1442}/[H1442]', 'inflected', 'heb', 'גָּדַף', '["gâdaph"]', '["and/ [one who] reviles","and/ have you blasphemed?"]', '["v"]', 'to hack (with words), i.e. revile blaspheme, reproach.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7230}/[H7231]', 'inflected', 'heb', 'רֹב', '["rôb"]', '["[is] in/ [the] multitude of","[is] in/ a multitude of","[is] in/ abundance of","by/ [the] abundance of","by/ [the] greatness of","by/ [the] multitude of","by/ greatness of","for/ [the] multitude of","in/ [the] abundance of","in/ [the] greatness of","in/ [the] multitude of","in/ a multitude of","in/ abundance of","with/ [the] abundance of","with/ [the] greatness of","with/ a multitude of","with/ abundance of"]', '["n-m"]', 'abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age).', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7393G}/H9020/[H7392]', 'inflected', 'heb', 'רֶכֶב', '["rekeb"]', '["chariotry/ my"]', '["n-m"]', 'a vehicle; by implication, a team; by extension, cavalry; by analogy a rider, i.e. the upper millstone chariot, (upper) millstone, multitude (from the margin), wagon.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3844G}/[H3825]', 'lemma', 'heb', 'לְבָנוֹן', '["Lᵉbânôwn"]', '["Lebanon","O Lebanon"]', '["n-pr-loc"]', 'Lebanon, a mountain range in Palestine Lebanon.', 'from 3825; (the) white mountain (from its snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0730}/H9023/[H729]', 'inflected', 'heb', 'אֶרֶז', '["ʼerez"]', '["cedars/ its"]', '["n-m"]', 'a cedar tree (from the tenacity of its roots) cedar (tree).', 'from 729;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1265>/H9023', 'opaque', 'heb', 'בְּרוֹשׁ', '["bᵉrôwsh"]', '["pines/ its"]', '["n-m"]', 'a cypress (?) tree; hence, a lance or a musical instrument (as made of that wood) fir (tree).', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4411}/[H3885]', 'lemma', 'heb', 'מָלוֹן', '["mâlôwn"]', '["[the] lodging place of","[will be] a lodging place","a lodging place of"]', '["n-m"]', 'a lodgment, i.e. caravanserai or encampment inn, place where...lodge, lodging (place).', 'from 3885;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7093}/H9023/[H7112]', 'inflected', 'heb', 'קֵץ', '["qêts"]', '["end/ his","end/ its"]', '["n-m"]', 'an extremity; adverbially (with prepositional prefix) after after, (utmost) border, end, (in-) finite, × process.', 'contracted from 7112;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3759}/H9023/[H3754]', 'inflected', 'heb', 'כַּרְמֶל', '["karmel"]', '["orchard/ its","plantation/ its"]', '["n-m"]', 'a planted field (garden, orchard, vineyard or park); by implication, garden produce full (green) ears (of corn), fruitful field (place), plentiful (field).', 'from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6979A}/[H7023]', 'lemma', 'heb', 'קוּר', '["qûwr"]', '["I have dug"]', '["v"]', 'to trench; by implication, to throw forth; to wall up, whether literal (to build a wall) or figurative (to estop) break down, cast out, destroy, dig.', 'a primitive root; also denominative from 7023');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2717A}/[H2717]', 'inflected', 'heb', 'חָרַב', '["chârab"]', '["so/ I may dry up","so/ it may be dried up"]', '["v"]', 'to parch (through drought) i.e. (by analogy,) to desolate, destroy, kill decay, (be) desolate, destroy(-er), (be) dry (up), slay, × surely, (lay, lie, make) waste.', 'or חֲרֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3709H}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["with/ [the] sole of"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6471}/H9020/[H6470]', 'inflected', 'heb', 'פַּעַם', '["paʻam"]', '["feet/ my","footsteps/ my"]', '["n-f"]', 'a stroke, literally or figuratively (in various applications, as follow) anvil, corner, foot(-step), going, (hundred-) fold, × now, (this) once, order, rank, step, thrice, (often-), second, this, two) time(-s), twice, wheel.', 'or (feminine) פַּעֲמָה; from 6470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2975H}/[H2975]', 'lemma', 'heb', 'יְאֹר', '["yᵉʼôr"]', '["[the] canals of","canals","shafts"]', '["n-m"]', 'a channel, e.g. a fosse, canal, shaft; specifically the Nile, as the one river of Egypt, including its collateral trenches; also the Tigris, as the main river of Assyria brook, flood, river, stream.', 'of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4693}/[H4692]', 'lemma', 'heb', 'מָצוֹר', '["mâtsôwr"]', '["Egypt"]', '["n-pr-loc"]', 'Egypt (as the border of Palestine) besieged places, defense, fortified.', 'the same as 4692 in the sense of a limit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3335I}/H9034/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["and/ I planned/ it"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7582}/[H7582]', 'inflected', 'heb', 'שָׁאָה', '["shâʼâh"]', '["[about] to/ make desolate"]', '["v"]', 'to rush; by implication, to desolate be desolate, (make a) rush(-ing), (lay) waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5327B}/[H5327]', 'lemma', 'heb', 'נָצָה', '["nâtsâh"]', '["ruined","they will fall in ruins"]', '["v"]', 'properly, to go forth, i.e. (by implication) to be expelled, and (consequently) desolate; causatively, to lay waste; also (specifically), to quarrel be laid waste, runinous, strive (together).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3427}/H9029/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ inhabitants/ their"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7116}/[H7114]', 'lemma', 'heb', 'קָצֵר', '["qâtsêr"]', '["[a person] short of","[is] short of","[were] short of"]', '["a"]', 'short (whether in size, number, life, strength or temper) few, hasty, small, soon.', 'from 7114;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0954}/[H954]', 'inflected', 'heb', 'בּוּשׁ', '["bûwsh"]', '["and/ it will be ashamed","and/ they have been ashamed","and/ they were ashamed","and/ they will be ashamed","and/ they will put to shame","and/ you will be ashamed"]', '["v"]', 'properly, to pale, i.e. by implication to be ashamed; also (by implication) to be disappointed or delayed (be, make, bring to, cause, put to, with, a-) shamed(-d), be (put to) confounded(-fusion), become dry, delay, be long.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3419}/[H3418]', 'inflected', 'heb', 'יָרָק', '["yârâq"]', '["and/ [the] greenery of","and/ greenery of"]', '["n-m"]', 'properly, green; concretely, a vegetable green, herbs.', 'from the same as 3418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7711A}/[H7710]', 'inflected', 'heb', 'שְׁדֵפָה', '["shᵉdêphâh"]', '["and/ scorching"]', '["n-f n-m"]', 'blight blasted(-ing).', 'or שִׁדָּפוֹן; from 7710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3427}/H9041/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ sitting down/ you","and/ sitting down/ your"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3318G}/H9041/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ going out/ you"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7264}/H9041/[H7264]', 'inflected', 'heb', 'רָגַז', '["râgaz"]', '["raging/ you"]', '["v"]', 'to quiver (with any violent emotion, especially anger or fear) be afraid, stand in awe, disquiet, fall out, fret, move, provoke, quake, rage, shake, tremble, trouble, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7600}/H9021/[H7599]', 'inflected', 'heb', 'שַׁאֲנָן', '["shaʼănân"]', '["and/ arrogance/ your"]', '["a"]', 'secure; in a bad sense, haughty that is at ease, quiet, tumult. Compare 7946.', 'from 7599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2397}/H9020/[H2336]', 'inflected', 'heb', 'חָח', '["châch"]', '["hook/ my"]', '["n-m"]', 'a ring for the nose (or lips) bracelet, chain, hook.', 'once (Ezekiel 29:4) חָחִי; from the same as 2336;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0639H}/H9021/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["in/ nose/ your"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4964>/H9020', 'inflected', 'heb', 'ומתגי', '["u./mit.G/i"]', '["and/ bridle/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8193G}/H9021/[H5595]', 'inflected', 'heb', 'שָׂפָה', '["sâphâh"]', '["on/ lips/ your","with/ lips/ your"]', '["n-f"]', 'the lip (as a natural boundary); by implication, language; by analogy, a margin (of a vessel, water, cloth, etc.) band, bank, binding, border, brim, brink, edge, language, lip, prating, (sea-)shore, side, speech, talk, (vain) words.', 'or (in dual and plural) שֶׂפֶת; probably from 5595 or 8192 through the idea of termination (compare 5490);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7823>', 'opaque', 'heb', 'שָׁחִיס', '["shâchîyç"]', '["self-seeded plant[s]"]', '["n-m"]', 'after-growth (that) which springeth of the same.', 'or סָחִישׁ; from an unused root apparently meaning to sprout;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7114B}/[H7114]', 'inflected', 'heb', 'קָצַר', '["qâtsar"]', '["and/ reap"]', '["v"]', 'to dock off, i.e. curtail (transitive or intransitive, literal or figurative); especially to harvest (grass or grain) × at all, cut down, much discouraged, grieve, harvestman, lothe, mourn, reap(-er), (be, wax) short(-en, -er), straiten, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5193}/[H5193]', 'inflected', 'heb', 'נָטַע', '["nâṭaʻ"]', '["and/ plant","so/ he may pitch"]', '["v"]', 'properly, to strike in, i.e. fix; specifically, to plant (literally or figuratively) fastened, plant(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6529}/H9028/[H6509]', 'inflected', 'heb', 'פְּרִי', '["pᵉrîy"]', '["descendant[s]/ their","fruit/ their"]', '["n-m"]', 'fruit (literally or figuratively) bough, (first-)fruit(-ful), reward.', 'from 6509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6413}/[H6412]', 'inflected', 'heb', 'פְּלֵיטָה', '["pᵉlêyṭâh"]', '["and/ [the] escaped remnant of","and/ an escaped remnant","and/ escape"]', '["n-f"]', 'deliverance; concretely, an escaped portion deliverance, (that is) escape(-d), remnant.', 'or פְּלֵטָה; feminine of 6412;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3068G}/ /{H6635B}/[H1961]', 'inflected', 'heb', 'יְהֹוָה', '["Yᵉhôvâh"]', '["Yahweh/ /of hosts"]', '["n-pr"]', '(the) self-Existent or Eternal; Jeho-vah, Jewish national name of God Jehovah, the Lord. Compare 3050, 3069.', 'from 1961;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2063}\/[H2088]', 'inflected', 'heb', 'זֹאת', '["zôʼth"]', '["this"]', '["d"]', 'this (often used adverb) hereby (-in, -with), it, likewise, the one (other, same), she, so (much), such (deed), that, therefore, these, this (thing), thus.', 'irregular feminine of 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6923}/H9034/[H6923]', 'inflected', 'heb', 'קָדַם', '["qâdam"]', '["he will confront/ it"]', '["v"]', 'to project (one self), i.e. precede; hence, to anticipate, hasten, meet (usually for help) come (go, (flee)) before, disappoint, meet, prevent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8210I}/[H8210]', 'lemma', 'heb', 'שָׁפַךְ', '["shâphak"]', '["he will pour out"]', '["v"]', 'to spill forth (blood, a libation, liquid metal; or even a solid, i.e. to mound up); also (figuratively) to expend (life, soul, complaint, money, etc.); intensively, to sprawl out cast (up), gush out, pour (out), shed(-der, out), slip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1598}/[H1598]', 'inflected', 'heb', 'גָּנַן', '["gânan"]', '["and/ I will defend"]', '["v"]', 'to hedge about, i.e. (generally) protect defend.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3467}/H9034/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["to/ deliver/ it"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4616}/H9030/[H6030]', 'inflected', 'heb', 'מַעַן', '["maʻan"]', '["for own sake/ my"]', '["prt"]', 'properly, heed, i.e. purpose; used only adverbially, on account of (as a motive or an aim), teleologically, in order that because of, to the end (intent) that, for (to,... ''s sake), lest, that, to.', 'from 6030;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H5210>', 'inflected', 'heb', 'בנינוה', '["be./Ni.ne.Veh","be./ni.ne.Veh"]', '["in/ Nineveh"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5268>', 'opaque', 'heb', 'נִסְרֹךְ', '["Niçrôk"]', '["Nisroch"]', '["n-pr-m"]', 'Nisrok, a Babylonian idol Nisroch.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0152H}/[H142]', 'inflected', 'heb', 'אֲדְרַמֶּלֶךְ', '["ʼĂdrammelek"]', '["and/ Adrammelech"]', '["n-pr-m"]', 'Adrammelek, the name of an Assyrian idol, also of a son of Sennacherib Adrammelech.', 'from 142 and 4428; splendor of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8272G}/ /{H1121A}/H9023/[H8272]', 'inflected', 'heb', 'שַׁרְאֶצֶר', '["Sharʼetser"]', '["and/ Sharezer/ /sons/ his"]', '["n-pr-m"]', 'Sharetser, the name of an Assyrian and an Israelite Sharezer.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0634}/[H634]', 'lemma', 'heb', 'אֵסַר־חַדּוֹן', '["ʼÊçar-Chaddôwn"]', '["-haddon","Esar-"]', '["n-pr-m"]', 'Esarchaddon, an Assyrian king Esar-haddon.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3824}/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["and/ with/ a heart"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1832}/H9021/[H1831]', 'inflected', 'heb', 'דִּמְעָה', '["dimʻâh"]', '["tear[s]/ your"]', '["n-f"]', 'weeping tears.', 'feminine of 1831;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6738}/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["the/ shadow"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6738}/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["for/ shade","to the/ shadow"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4609B}\/[H4608]', 'inflected', 'heb', 'מַעֲלָה', '["maʻălâh"]', '["steps"]', '["n-f"]', 'elevation, i.e. the act (literally, a journey to a higher place, figuratively, a thought arising), or (concretely) the condition (literally, a step or grade-mark, figuratively, a superiority of station); specifically a climactic progression (in certain Psalms) things that come up, (high) degree, deal, go up, stair, step, story.', 'feminine of 4608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1255}/[H4757]', 'lemma', 'heb', 'בְּרֹאדַךְ בַּלְאֲדָן', '["Bᵉrôʼdak Balʼădân"]', '["Baladan","Merodach-"]', '["n-pr-m"]', 'Berodak-Baladan, a Babylonian king Berodach-baladan.', 'a variation of 4757;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1081}/[H1078]', 'lemma', 'heb', 'בַּלְאֲדָן', '["Balʼădân"]', '["Baladan"]', '["n-pr-m"]', 'Baladan, the name of a Babylonian prince Baladan.', 'from 1078 and 113 (contracted); Bel (is his) lord;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4503H>', 'inflected', 'heb', 'ומנחה', '["u./min.Chah"]', '["and/ a gift"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8085L}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ he listened"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5238}/H9023/[H5219]', 'inflected', 'heb', 'נְכֹת', '["nᵉkôth"]', '["treasure/ his"]', '["n-f"]', 'spicery, i.e. (generally) valuables precious things.', 'probably for 5219;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0214}/H9023/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["in/ storehouses/ his"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004B}/H9020/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[is] in/ house/ my","in/ house/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0686}/[H686]', 'lemma', 'heb', 'אָצַר', '["ʼâtsar"]', '["it will be stored up","they have stored up","they stored up"]', '["v"]', 'to store up (lay up in) store, (make) treasure(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0894}/H9011/[H1101]', 'inflected', 'heb', 'בָּבֶל', '["Bâbel"]', '["Babylon/ towards"]', '["n-pr-loc"]', 'Babel (i.e. Babylon), including Babylonia and the Babylonian empire Babel, Babylon.', 'from 1101; confusion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1121G}/H9021/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ some of/ descendants/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1964H}/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["[is] in/ [the] palaces of","in/ [the] palace of","in/ [the] palaces of"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0571I}/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["and/ faithfulness","and/ stability"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3117G>/H9020', 'inflected', 'heb', 'בימי', '["ve./ya.Ma/i"]', '["in/ days/ my"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4519H}/[H5382]', 'lemma', 'heb', 'מְנַשֶּׁה', '["Mᵉnashsheh"]', '["Manasseh"]', '["n-pr-m"]', 'Menashsheh, a grandson of Jacob, also the tribe descended from him, and its territory Manasseh.', 'from 5382; causing to forget;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2657G}/[H2656]', 'lemma', 'heb', 'חֶפְצִי בָּהּ', '["Chephtsîy bâhh"]', '["-bah","[was] Hephzi-"]', '["n-pr-f"]', 'Cheptsi-bah, a fanciful name for Palestine Hephzi-bah.', 'from 2656 with suffixes; my delight (is) in her;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6049B}/[H6051]', 'inflected', 'heb', 'עָנַן', '["ʻânan"]', '["and/ he practiced soothsaying"]', '["v"]', 'figuratively, to act covertly, i.e. practise magic × bring, enchanter, Meonemin, observe(-r of) times, soothsayer, sorcerer.', 'a primitive root; to cover; used only as a denominative from 6051, to cloud over;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5110}/[H5110]', 'inflected', 'heb', 'נוּד', '["nûwd"]', '["for/ fluttering","to/ make wander","to/ show sympathy"]', '["v"]', 'to nod, i.e. waver; figuratively, to wander, flee, disappear; also (from shaking the head in sympathy), to console, deplore, or (from tossing the head in scorn) taunt bemoan, flee, get, mourn, make to move, take pity, remove, shake, skip for joy, be sorry, vagabond, way, wandering.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8582}/H9038/[H8582]', 'inflected', 'heb', 'תָּעָה', '["tâʻâh"]', '["and/ he made wander/ them","and/ he misled/ them","and/ they have misled/ them"]', '["v"]', 'to vacillate, i.e. reel or stray (literally or figuratively); also causative of both (cause to) go astray, deceive, dissemble, (cause to, make to) err, pant, seduce, (make to) stagger, (cause to) wander, be out of the way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1544}/H9023\/[H1556]', 'inflected', 'heb', 'גִּלּוּל', '["gillûwl"]', '["with/ idols/ his"]', '["n-m"]', 'properly, a log (as round); by implication, an idol idol.', 'or (shortened) גִּלֻּל; from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8085G}/H9034/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["[one who] hears of/ it","hear/ it","we heard of/ it","you will listen to/ it"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6957B}/[H6960]', 'lemma', 'heb', 'קַו', '["qav"]', '["[the] line of","[the] measuring-line of","a measuring-line","a measuring-line of"]', '["n-m"]', 'a cord (as connecting), especially for measuring; figuratively, a rule; also a rim, a musical string or accord line. Compare 6978.', 'or קָו; from 6960 (compare 6961);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4949}/[H4948]', 'lemma', 'heb', 'מִשְׁקֶלֶת', '["mishqeleth"]', '["[the] leveling tool of"]', '["n-f"]', 'a weight, i.e. a plummet (with line attached) plummet.', 'or מִשְׁקֹלֶת; feminine of 4948 or 4947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6747}/[H6743]', 'inflected', 'heb', 'צַלַּחַת', '["tsallachath"]', '["the/ bowl"]', '["n-f"]', 'something advanced or deep, i.e. a bowl; figuratively, the bosom bosom, dish.', 'from 6743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2015}/[H2015]', 'inflected', 'heb', 'הָפַךְ', '["hâphak"]', '["and/ [one who] is perverted","and/ [the one who] turns","and/ he turns [it] over","and/ it was reversed","and/ they may devastate"]', '["v"]', 'to turn about or over; by implication, to change, overturn, return, pervert × become, change, come, be converted, give, make (a bed), overthrow (-turn), perverse, retire, tumble, turn (again, aside, back, to the contrary, every way).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4933}/[H8155]', 'inflected', 'heb', 'מְשִׁסָּה', '["mᵉshiççâh"]', '["and/ <into>/ plunder"]', '["n-f"]', 'plunder booty, spoil.', 'from 8155;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2403B}/H9023/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ sin/ his"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1588G}/[H1598]', 'inflected', 'heb', 'גַּן', '["gan"]', '["in/ [the] garden of"]', '["n"]', 'a garden (as fenced) garden.', 'from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5798G}/[H5797]', 'lemma', 'heb', 'עֻזָּא', '["ʻUzzâʼ"]', '["Uzzah"]', '["n-pr-m n-pr-loc"]', 'Uzza or Uzzah, the name of five Israelites Uzza, Uzzah.', 'or עֻזָּה; feminine of 5797; strength;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0526H}/[H525]', 'lemma', 'heb', 'אָמוֹן', '["ʼÂmôwn"]', '["Amon"]', '["n-pr-m"]', 'Amon, the name of three Israelites Amon.', 'the same as 525;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4922}/[H4918]', 'lemma', 'heb', 'מְשֻׁלֶּמֶת', '["Mᵉshullemeth"]', '["[was] Meshullemeth"]', '["n-pr-f"]', 'Meshullemeth, an Israelitess Meshullemeth.', 'feminine of 4918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2743}/[H2742]', 'lemma', 'heb', 'חָרוּץ', '["Chârûwts"]', '["Haruz"]', '["n-pr-m"]', 'Charuts, an Israelite Haruz.', 'the same as 2742; earnest;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3192}/[H3190]', 'lemma', 'heb', 'יׇטְבָה', '["Yoṭbâh"]', '["Jotbah"]', '["n-pr-loc"]', 'Jotbah, a place in Palestine Jotbah.', 'from 3190; pleasantness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3040}/[H3039]', 'lemma', 'heb', 'יְדִידָה', '["Yᵉdîydâh"]', '["[was] Jedidah"]', '["n-pr-f"]', 'Jedidah, an Israelitess Jedidah.', 'feminine of 3039; beloved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5718G}/[H5710]', 'lemma', 'heb', 'עֲדָיָה', '["ʻĂdâyâh"]', '["Adaiah"]', '["n-pr-m"]', 'Adajah, the name of eight Israelites Adaiah.', 'or עֲדָיָהוּ; from 5710 and 3050; Jah has adorned;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1218}/[H1216]', 'inflected', 'heb', 'בׇּצְקַת', '["Botsqath"]', '["from/ Bozkath"]', '["n-pr-loc"]', 'Botscath, a place in Palestine Bozcath, Boskath.', 'from 1216; a swell of ground;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8040G}\/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["and/ left [hand]"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8083}/[H8082]', 'inflected', 'heb', 'שְׁמֹנֶה', '["shᵉmôneh"]', '["in/ eight-","with/ eight"]', '["n"]', 'a cardinal number, eight (as if a surplus above the ''perfect'' seven); also (as ordinal) eighth eight(-een, -eenth), eighth.', 'or שְׁמוֹנֶה; feminine שְׁמֹנָה; or שְׁמוֹנָה; apparently from 8082 through the idea of plumpness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8227B}/[H8226]', 'lemma', 'heb', 'שָׁפָן', '["shâphân"]', '["Shaphan"]', '["n-m n-pr-m"]', 'a species of rock-rabbit (from its hiding), i.e. probably the hyrax coney.', 'from 8226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0683}/[H680]', 'lemma', 'heb', 'אֲצַלְיָהוּ', '["ʼĂtsalyâhûw"]', '["Azaliah"]', '["n-pr-m"]', 'Atsaljah, an Israelite Azaliah.', 'from 680 and 3050 prolonged; Jah has reserved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4918G}/[H7999]', 'lemma', 'heb', 'מְשֻׁלָּם', '["Mᵉshullâm"]', '["Meshullam"]', '["n-pr-m"]', 'Meshullam, the name of seventeen Israelites Meshullam.', 'from 7999; allied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2518H}/[H2506]', 'lemma', 'heb', 'חִלְקִיָּה', '["Chilqîyâh"]', '["Hilkiah"]', '["n-pr-m"]', 'Chilhijah, the name of eight Israelites Hillkiah.', 'or חִלְקִיָּהוּ; from 2506 and 3050; portion of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8552}/[H8552]', 'inflected', 'heb', 'תָּמַם', '["tâmam"]', '["so/ he may complete"]', '["v"]', 'to complete, in a good or a bad sense, literal, or figurative, transitive or intransitive accomplish, cease, be clean (pass-) ed, consume, have done, (come to an, have an, make an) end, fail, come to the full, be all gone, × be all here, be (make) perfect, be spent, sum, be (shew self) upright, be wasted, whole.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5414G}/H9033/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will give/ it","and/ give/ him","and/ let them put/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5612H}/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["the/ scroll"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7121J}/H9033/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["and/ he read aloud/ it","and/ he read/ it"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0296}/[H251]', 'lemma', 'heb', 'אֲחִיקָם', '["ʼĂchîyqâm"]', '["Ahikam"]', '["n-pr-m"]', 'Achikam, an Israelite Ahikam.', 'from 251 and 6965; brother of rising (i.e. high);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5907H}/[H5909]', 'lemma', 'heb', 'עַכְבּוֹר', '["ʻAkbôwr"]', '["Achbor"]', '["n-pr-m"]', 'Akbor, the name of an Idumaean and of two Israelites Achbor.', 'probably for 5909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4320G}/[H4310]', 'lemma', 'heb', 'מִיכָיָה', '["Mîykâyâh"]', '["Micaiah"]', '["n-pr-m"]', 'Micajah, the name of two Israelites Micah, Michaiah. Compare 4318.', 'from 4310 and (the prefix derivative from) 3588 and 3050; who (is) like Jah?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6222G}/[H6213]', 'lemma', 'heb', 'עֲשָׂיָה', '["ʻĂsâyâh"]', '["Asaiah"]', '["n-pr-m"]', 'Asajah, the name of three or four Israelites Asaiah.', 'from 6213 and 3050; Jah has made;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0296}/[H251]', 'inflected', 'heb', 'אֲחִיקָם', '["ʼĂchîyqâm"]', '["and/ Ahikam"]', '["n-pr-m"]', 'Achikam, an Israelite Ahikam.', 'from 251 and 6965; brother of rising (i.e. high);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5907H}/[H5909]', 'inflected', 'heb', 'עַכְבּוֹר', '["ʻAkbôwr"]', '["and/ Achbor"]', '["n-pr-m"]', 'Akbor, the name of an Idumaean and of two Israelites Achbor.', 'probably for 5909;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8227B}/[H8226]', 'inflected', 'heb', 'שָׁפָן', '["shâphân"]', '["and/ Shaphan"]', '["n-m n-pr-m"]', 'a species of rock-rabbit (from its hiding), i.e. probably the hyrax coney.', 'from 8226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6222G}/[H6213]', 'inflected', 'heb', 'עֲשָׂיָה', '["ʻĂsâyâh"]', '["and/ Asaiah"]', '["n-pr-m"]', 'Asajah, the name of three or four Israelites Asaiah.', 'from 6213 and 3050; Jah has made;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2468}/[H2467]', 'lemma', 'heb', 'חֻלְדָּה', '["Chuldâh"]', '["Huldah"]', '["n-pr-f"]', 'Chuldah, an Israelitess Huldah.', 'feminine of 2467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7967H}/[H7966]', 'lemma', 'heb', 'שַׁלּוּם', '["Shallûwm"]', '["Shallum"]', '["n-pr-m"]', 'Shallum, the name of fourteen Israelites Shallum.', 'or (shorter) שַׁלֻּם; the same as 7966;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8616G}/[H8615]', 'lemma', 'heb', 'תִּקְוָה', '["Tiqvâh"]', '["Tikvah","Tokhath"]', '["n-pr-m"]', 'Tikvah, the name of two Israelites Tikvah.', 'the same as 8615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2745}/[H2775]', 'lemma', 'heb', 'חַרְחַס', '["Charchaç"]', '["Harhas"]', '["n-pr-m"]', 'Charchas, an Israelite Harhas.', 'from the same as 2775; perhaps shining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4932G}/[H8138]', 'inflected', 'heb', 'מִשְׁנֶה', '["mishneh"]', '["in the/ second district"]', '["n-m"]', 'properly, a repetition, i.e. a duplicate (copy of a document), or a double (in amount); by implication, a second (in order, rank, age, quality or location) college, copy, double, fatlings, next, second (order), twice as much.', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3427}/H9023/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["dwelling/ his","inhabitants/ its"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7971G}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["the/ [one who] sends","the/ [one who] sends forth","which/ sends","who/ sent"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8085G}/H9041/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["when/ hearing/ you"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8047G}/[H8074]', 'inflected', 'heb', 'שַׁמָּה', '["shammâh"]', '["<into>/ a horror","<into>/ a waste","into/ a horror","into/ a waste"]', '["n-f"]', 'ruin; by implication, consternation astonishment, desolate(-ion), waste, wonderful thing.', 'from 8074;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7045}/[H7043]', 'inflected', 'heb', 'קְלָלָה', '["qᵉlâlâh"]', '["and/ <into>/ a curse","and/ into/ a curse"]', '["n-f"]', 'vilification (ac-) curse(-d, -ing).', 'from 7043;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6913}/H9021/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["grave<s>/ your"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3389}/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["and/ Jerusalem","and/ [was] Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/{H6996B}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["<to>/ from/ [the] small"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1964G}/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["from/ [the] temple","from/ [the] temple of"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6213H}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["<the>/ made","the/ [one] made","which/ are done","which/ were made"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0842}/[H833]', 'inflected', 'heb', 'אֲשֵׁרָה', '["ʼăshêrâh"]', '["and/ for <the>/ Asherah"]', '["n-pr-f"]', 'Asherah (or Astarte) a Phoenician goddess; also an image of the same grove. Compare 6253.', 'or אֲשֵׁירָה; from 833; happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8313}/H9038/[H8313]', 'inflected', 'heb', 'שָׂרַף', '["sâraph"]', '["and/ he burned/ them","and/ he will burn/ them"]', '["v"]', 'to be (causatively, set) on fire (cause to, make a) burn((-ing), up) kindle, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3389}/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["<to>/ Jerusalem","for/ Jerusalem","of/ Jerusalem","to/ Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7709}/[H7704]', 'inflected', 'heb', 'שְׁדֵמָה', '["shᵉdêmâh"]', '["in/ [the] fields of"]', '["n-f"]', 'a cultivated field blasted, field.', 'apparently from 7704;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6083}/H9028/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["dust/ their"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3649}/[H3648]', 'inflected', 'heb', 'כָּמָר', '["kâmâr"]', '["the/ pagan priests"]', '["n-m"]', 'properly, an ascetic (as if shrunk with self-maceration), i.e. an idolatrous priest (only in plural) Chemarims (idolatrous) priests.', 'from 3648;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4524}/[H5437]', 'inflected', 'heb', 'מֵסַב', '["mêçab"]', '["and/ [the] surroundings of"]', '["n-m"]', 'a divan (as enclosing the room); abstractly (adverbial) around that compass about, (place) round about, at table.', 'plural masculine מְסִבִּים; or feminine מְסִבּוֹת; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6999A}/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["the/ [ones who] made smoke"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H8121>', 'inflected', 'heb', 'לשמש', '["la./Sha.mesh","la./She.mesh"]', '["for the/ sun","to the/ sun"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3394}/[H3391]', 'inflected', 'heb', 'יָרֵחַ', '["yârêach"]', '["and/ to the/ moon"]', '["n-m"]', 'the moon moon. Yrechow. See 3405.', 'from the same as 3391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4208}/[H5140]', 'inflected', 'heb', 'מַזָּלָה', '["mazzâlâh"]', '["and/ to the/ constellations"]', '["n-f"]', 'a constellation, i.e. Zodiacal sign (perhaps as affecting the weather) planet. Compare 4216.', 'apparently from 5140 in the sense of raining;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1854}/[H1915]', 'inflected', 'heb', 'דָּקַק', '["dâqaq"]', '["and/ he crushed [it]","and/ you will crush"]', '["v"]', 'to crush (or intransitively) crumble beat in pieces (small), bruise, make dust, (into) × powder, (be, very) small, stamp (small).', 'a primitive root (compare 1915);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6083}/H9024/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["dust/ its"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1387G}/[H1375]', 'inflected', 'heb', 'גֶּבַע', '["Gebaʻ"]', '["[were] from/ Geba","from/ Geba"]', '["n-pr-loc"]', 'Geba, a place in Palestine Gaba, Geba, Gibeah.', 'from the same as 1375, a hillock;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3091I}/[H3068]', 'lemma', 'heb', 'יְהוֹשׁוּעַ', '["Yᵉhôwshûwaʻ"]', '["Joshua"]', '["n-pr-m"]', 'Jehoshua (i.e. Joshua), the Jewish leader Jehoshua, Jehoshuah, Joshua. Compare 1954, 3442.', 'or יְהוֹשֻׁעַ; from 3068 and 3467; Jehovah-saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8612}/[H8611]', 'inflected', 'heb', 'תֹּפֶת', '["Tôpheth"]', '["<the>/ Topheth"]', '["n-pr-loc"]', 'Topheth, a place near Jerusalem Tophet, Topheth.', 'the same as 8611;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1516Q}/[H1466]', 'inflected', 'heb', 'גַּיְא', '["gayʼ"]', '["[is] in/ [the] valley of","[was] in/ [the] valley of","in/ [the] valley of"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0935I}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["from/ [the] going of","from/ coming"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3957>', 'opaque', 'heb', 'לִשְׁכָּה', '["lishkâh"]', '["[are] [the] rooms of","[the] room of","[the] rooms of","[the] store-rooms of","a room","rooms","rooms of"]', '["n-f"]', 'a room in a building (whether for storage, eating, or lodging) chamber, parlour. Compare 5393.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5419}/[H5414]', 'lemma', 'heb', 'נְתַן־מֶלֶךְ', '["Nᵉthan-Melek"]', '["Melech","Nathan"]', '["n-pr-m"]', 'Nethan-Melek, an Israelite Nathanmelech.', 'from 5414 and 4428; given of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5631>', 'inflected', 'heb', 'הסריסים', '["ha./Sa.ri.Sim","ha./sa.Ris","ha./sa.ri.Sim"]', '["the/ court-official","the/ court-officials","the/ eunuch","the/ eunuchs","the/ officials"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6503>', 'inflected', 'heb', 'בפרורים', '["ba./par.va.Rim"]', '["[was] in the/ Parbar"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7323I}/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["and/ he ran"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4889}/[H7843]', 'inflected', 'heb', 'מַשְׁחִית', '["mashchîyth"]', '["<the>/ destruction"]', '["n-m"]', 'destructive, i.e. (as noun) destruction, literally (specifically a snare) or figuratively (corruption) corruption, (to) destroy(-ing), destruction, trap, × utterly.', 'from 7843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H3645>', 'inflected', 'heb', 'ולכמוש', '["ve./li/kh.mo.Vosh"]', '["and/ to/ Chemosh"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6913}/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["the/ grave of","the/ graves"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6106G}/[H6105]', 'inflected', 'heb', 'עֶצֶם', '["ʻetsem"]', '["O/ bones","the/ bones"]', '["n-f"]', 'a bone (as strong); by extension, the body; figuratively, the substance, i.e. (as pron.) selfsame body, bone, × life, (self-) same, strength, × very.', 'from 6105;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6725}/[H6723]', 'inflected', 'heb', 'צִיּוּן', '["tsîyûwn"]', '["[is] the/ monument"]', '["n-m"]', 'a monumental or guiding pillar sign, title, waymark.', 'from the same as 6723 in the sense of conspicuousness (compare 5329);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6453}/[H6452]', 'inflected', 'heb', 'פֶּסַח', '["peçach"]', '["like the/ passover"]', '["n-m"]', 'a pretermission, i.e. exemption; used only techically of the Jewish Passover (the festival or the victim) passover (offering).', 'from 6452;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8251}/[H8262]', 'inflected', 'heb', 'שִׁקּוּץ', '["shiqqûwts"]', '["the/ abomination","the/ detestable things"]', '["n-m"]', 'disgusting, i.e. filthy; especially idolatrous or (concretely) an idol abominable filth (idol, -ation), detestable (thing).', 'or שִׁקֻּץ; from 8262;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3966}/H9023/[H181]', 'inflected', 'heb', 'מְאֹד', '["mᵉʼôd"]', '["strength/ his"]', '["a"]', 'properly, vehemence, i.e. (with or without preposition) vehemently; by implication, wholly, speedily, etc. (often with other words as an intensive or superlative; especially when repeated) diligently, especially, exceeding(-ly), far, fast, good, great(-ly), × louder and louder, might(-ily, -y), (so) much, quickly, (so) sore, utterly, very ( much, sore), well.', 'from the same as 181;');
