INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4023}/[H12]', 'inflected', 'heb', 'מְגִדּוֹן', '["Mᵉgiddôwn"]', '["at/ Megiddo"]', '["n-pr-loc"]', 'Megiddon or Megiddo, a place in Palestine Megiddo, Megiddon.', '(Zechariah 12) or מְגִדּוֹ; from 1413; rendezvous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7392}/H9033/[H7392]', 'inflected', 'heb', 'רָכַב', '["râkab"]', '["and/ he made ride/ him","and/ they made ride/ him","and/ they will make ride/ him"]', '["v"]', 'to ride (on an animal or in a vehicle); causatively, to place upon (for riding or generally), to despatch bring (on (horse-) back), carry, get (oneself) up, on (horse-) back, put, (cause to, make to) ride (in a chariot, on, -r), set.', 'a primitive root;');
