INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5437K}/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["and/ he changed"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3079}/[H3068]', 'lemma', 'heb', 'יְהוֹיָקִים', '["Yᵉhôwyâqîym"]', '["Jehoiakim"]', '["n-pr-m"]', 'Jehojakim, a Jewish king Jehoiakim. Compare 3113.', 'from 3068 abbreviated and 6965; Jehovah will raise;');
