INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6187}/H9023/[H6186]', 'inflected', 'heb', 'עֵרֶךְ', '["ʻêrek"]', '["according to/ valuation/ his"]', '["n-m"]', 'a pile, equipment, estimate equal, estimation, (things that are set in) order, price, proportion, × set at, suit, taxation, × valuest.', 'from 6186;');
