INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2080}/[H2064]', 'lemma', 'heb', 'זְבִידָה', '["Zᵉbîydâh"]', '["[was] Zebudah"]', '["n-pr-f"]', 'Zebidah, an Israelitess Zebudah.', 'feminine from 2064; giving;');
