INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5019}/[H5019]', 'lemma', 'heb', 'נְבוּכַדְנֶאצַּר', '["Nᵉbûwkadneʼtstsar"]', '["Nebuchadnezzar"]', '["n-pr-m"]', 'Nebukadnetstsar (or -retstsar, or -retstsor), king of Babylon Nebuchadnezzar, Nebuchadrezzar.', 'or נְבֻּכַדְנֶאצַּר; (2 Kings 24:1,10), or נְבוּכַדְנֶצַּר; (Esther 2:6; Daniel 1:18), or נְבוּכַדְרֶאצַּר; or נְבוּכַדְרֶאצּוֹר; (Ezra 2:1; Jeremiah 49:28), of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5545}/[H5545]', 'inflected', 'heb', 'סָלַח', '["çâlach"]', '["to/ forgive"]', '["v"]', 'to forgive forgive, pardon, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3078}/[H3068]', 'lemma', 'heb', 'יְהוֹיָכִין', '["Yᵉhôwyâkîyn"]', '["Jehoiachin"]', '["n-pr-m"]', 'Jehojakin, a Jewish king Jehoiachin. Compare 3112.', 'from 3068 and 3559; Jehovah will establish;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5158L}/[H5157]', 'inflected', 'heb', 'נַחַל', '["nachal"]', '["from/ [the] wadi of"]', '["n-m"]', 'a stream, especially a winter torrent; (by implication) a (narrow) valley (in which a brook runs); also a shaft (of a mine) brook, flood, river, stream, valley.', 'or (feminine) נַחְלָה; (Psalm 124:4), or נַחֲלָה; (Ezekiel 47:19; Ezekiel 48:28), from 5157 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5179}/[H5178]', 'lemma', 'heb', 'נְחֻשְׁתָּא', '["Nᵉchushtâʼ"]', '["[was] Nehushta"]', '["n-pr-f"]', 'Nechushta, an Israelitess Nehushta.', 'from 5178; copper;');
