INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1473}/[H1540]', 'lemma', 'heb', 'גּוֹלָה', '["gôwlâh"]', '["exile","exile[s]"]', '["n-f"]', 'exile; concretely and collectively exiles (carried away), captive(-ity), removing.', 'or (shortened) גֹּלָה; active participle feminine of 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2796}/[H2790]', 'inflected', 'heb', 'חָרָשׁ', '["chârâsh"]', '["<the>/ craftsman","the/ craftsman","the/ craftsmen"]', '["n-m"]', 'a fabricator or any material artificer, ( ) carpenter, craftsman, engraver, maker, mason, skilful, ( ) smith, worker, workman, such as wrought.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4525}/[H5462]', 'inflected', 'heb', 'מַסְגֵּר', '["maçgêr"]', '["and/ <the>/ smith","and/ the/ smith"]', '["n-m"]', 'a fastener, i.e. (of a person) a smith, (of a thing) a prison prison, smith.', 'from 5462;');
