INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7993}/H9043/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["cast out/ he","threw/ he"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
