INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0935I}/H9033/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ he brought/ him"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5018>', 'opaque', 'heb', 'נְבוּזַרְאֲדָן', '["Nᵉbûwzarʼădân"]', '["-adan","Nebuzar-","Nebuzaradan"]', '["n-pr-m"]', 'Nebuzaradan, a Babylonian general Nebuzaradan.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7227B}/[H7231]', 'lemma', 'heb', 'רַב', '["rab"]', '["<the> chief of","[the] chief of","[the] chiefs of","[was the] chief of"]', '["a n-m"]', 'abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent).', 'by contracted from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2876}/[H2873]', 'lemma', 'heb', 'טַבָּח', '["ṭabbâch"]', '["[the] bodyguards"]', '["n-m"]', 'properly, a butcher; hence, a lifeguardsman (because he was acting as an executioner); also a cook (usually slaughtering the animal for food) cook, guard.', 'from 2873;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5307H}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["those/ [who] fell","those/ [who] had fallen"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1803B}/[H1802]', 'inflected', 'heb', 'דַּלָּה', '["dallâh"]', '["and/ some of/ [the] poor people of"]', '["n-f"]', 'properly, something dangling, i.e. a loose thread or hair; figuratively, indigent hair, pining sickness, poor(-est sort).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3755}/[H3754]', 'inflected', 'heb', 'כֹּרֵם', '["kôrêm"]', '["to/ vinedressers"]', '["v"]', 'a vinedresser vine dresser (as one or two words).', 'active participle of an imaginary denominative from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3009}/[H3009]', 'inflected', 'heb', 'יָגַב', '["yâgab"]', '["and/ to/ ploughmen"]', '["v"]', 'to dig or plow husbandman.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5178A}/H9028/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["bronze/ their"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4212}/[H2168]', 'inflected', 'heb', 'מְזַמְּרָה', '["mᵉzammᵉrâh"]', '["the/ snuffers"]', '["n-f"]', 'a tweezer (only in the plural) snuffers.', 'from 2168;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4350}/[H4349]', 'inflected', 'heb', 'מְכוֹנָה', '["mᵉkôwnâh"]', '["and/ the/ stands"]', '["n-f"]', 'a pedestal, also a spot base.', 'or מְכֹנָה; feminine of 4349;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7639}/[H7638]', 'inflected', 'heb', 'שְׂבָכָה', '["sᵉbâkâh"]', '["and/ a network"]', '["n-f"]', 'a net-work, i.e. (in hunting) a snare, (in architecture) a ballustrade; also a reticulated ornament to a pillar checker, lattice, network, snare, wreath(-enwork).', 'feminine of 7638;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0428}/[H411]', 'inflected', 'heb', 'אֵלֶּה', '["ʼêl-leh"]', '["and/ like/ these","and/ like/ these [things]"]', '["d"]', 'these or those an-(the) other; one sort, so, some, such, them, these (same), they, this, those, thus, which, who(-m).', 'prolonged from 411;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8304H}/[H8280]', 'lemma', 'heb', 'שְׂרָיָה', '["Sᵉrâyâh"]', '["Seraiah"]', '["n-pr-m"]', 'Serajah, the name of nine Israelites Seraiah.', 'or שְׂרָיָהוּ; from 8280 and 3050; Jah has prevailed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7218H>', 'inflected', 'heb', 'הראש', '["ha./Rosh","ha./roSh"]', '["[is] the/ head","[was] the/ chief","[were] the/ chief","the/ chief","the/ head"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6846G}/[H6845]', 'lemma', 'heb', 'צְפַנְיָה', '["Tsᵉphanyâh"]', '["Zephaniah"]', '["n-pr-m"]', 'Tsephanjah, the name of four Israelites Zephaniah.', 'or צְפַנְיָהוּ; from 6845 and 3050; Jah has secreted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7200M}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["from/ [those who] saw"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1436B}/[H1431]', 'lemma', 'heb', 'גְּדַּלְיָה', '["Gᵉdalyâh"]', '["Gedaliah"]', '["n-pr-m"]', 'Gedaljah, the name of five Israelites Gedaliah.', 'or (prolonged) גְּדַלְיָהוּ; from 1431 and 3050; Jah has become great;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8227B}\/[H8226]', 'inflected', 'heb', 'שָׁפָן', '["shâphân"]', '["Shaphan"]', '["n-m n-pr-m"]', 'a species of rock-rabbit (from its hiding), i.e. probably the hyrax coney.', 'from 8226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3458H}/[H8085]', 'inflected', 'heb', 'יִשְׁמָעֵאל', '["Yishmâʻêʼl"]', '["and/ Ishmael"]', '["n-pr-m"]', 'Jishmael, the name of Abraham''s oldest son, and of five Israelites Ishmael.', 'from 8085 and 410; God will hear;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5418G}/[H5414]', 'lemma', 'heb', 'נְתַנְיָה', '["Nᵉthanyâh"]', '["Nethaniah"]', '["n-pr-m"]', 'Nethanjah, the name of four Israelites Nethaniah.', 'or נְתַנְיָהוּ; from 5414 and 3050; given of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3110G}/[H3076]', 'inflected', 'heb', 'יוֹחָנָן', '["Yôwchânân"]', '["and/ Johanan"]', '["n-pr-m"]', 'Jochanan, the name of nine Israelites Johanan.', 'a form of 3076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7143}/[H7139]', 'lemma', 'heb', 'קָרֵחַ', '["Qârêach"]', '["Kareah"]', '["n-pr-m"]', 'Kareach, an Israelite Careah, Kareah.', 'from 7139; bald;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8304I}/[H8280]', 'inflected', 'heb', 'שְׂרָיָה', '["Sᵉrâyâh"]', '["and/ Seraiah"]', '["n-pr-m"]', 'Serajah, the name of nine Israelites Seraiah.', 'or שְׂרָיָהוּ; from 8280 and 3050; Jah has prevailed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8576}/[H8575]', 'lemma', 'heb', 'תַּנְחֻמֶת', '["Tanchumeth"]', '["Tanhumeth"]', '["n-pr-m"]', 'Tanchumeth, an Israelite Tanhumeth.', 'for 8575 (feminine);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5200}/[H5199]', 'inflected', 'heb', 'נְטֹפָתִי', '["Nᵉṭôphâthîy"]', '["the/ Netophathite"]', '["a"]', 'a Netophathite, or inhabitant of Netophah Netophathite.', 'patronymic from 5199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2970J}/[H238]', 'inflected', 'heb', 'יַאֲזַנְיָה', '["Yaʼăzanyâh"]', '["and/ Jaazaniah","and/ Jezaniah"]', '["n-pr-m"]', 'Jaazanjah, the name of four Israelites Jaazaniah. Compare 3153.', 'or יַאֲזַנְיָהוּ; from 238 and 3050; heard of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0582}/H9028/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["and/ men/ their"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0582}/H9028/[H605]', 'inflected', 'heb', 'אֱנוֹשׁ', '["ʼĕnôwsh"]', '["and/ to/ men/ their"]', '["n-m"]', 'properly, a mortal (and thus differing from the more dignified 120); hence, a man in general (singly or collectively) another, × (blood-) thirsty, certain, chap(-man); divers, fellow, × in the flower of their age, husband, (certain, mortal) man, people, person, servant, some (× of them), stranger, those, their trade. It is often unexpressed in the English versions, especially when used in apposition with another word. Compare 376.', 'from 605;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3778}/[H3777]', 'inflected', 'heb', 'כַּשְׂדִּי', '["Kasdîy"]', '["the/ Chaldeans"]', '["n-pr-loc n-pr-m"]', 'a Kasdite, or descendant of Kesed; by implication, a Chaldaean (as if so descended); also an astrologer (as if proverbial of that people Chaldeans, Chaldees, inhabitants of Chaldea.', '(occasionally with enclitic) כַּשְׂדִּימָה; towards the Kasdites into Chaldea), patronymically from 3777 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3458H}/[H8085]', 'lemma', 'heb', 'יִשְׁמָעֵאל', '["Yishmâʻêʼl"]', '["Ishmael"]', '["n-pr-m"]', 'Jishmael, the name of Abraham''s oldest son, and of five Israelites Ishmael.', 'from 8085 and 410; God will hear;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0476I}/[H410]', 'lemma', 'heb', 'אֱלִישָׁמָע', '["ʼĔlîyshâmâʻ"]', '["Elishama"]', '["n-pr-m"]', 'Elishama, the name of seven Israelites Elishama.', 'from 410 and 8085; God of hearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3778}\/[H3777]', 'inflected', 'heb', 'כַּשְׂדִּי', '["Kasdîy"]', '["[the] Chaldeans"]', '["n-pr-loc n-pr-m"]', 'a Kasdite, or descendant of Kesed; by implication, a Chaldaean (as if so descended); also an astrologer (as if proverbial of that people Chaldeans, Chaldees, inhabitants of Chaldea.', '(occasionally with enclitic) כַּשְׂדִּימָה; towards the Kasdites into Chaldea), patronymically from 3777 (only in the plural);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1546}/[H1540]', 'inflected', 'heb', 'גָּלוּת', '["gâlûwth"]', '["of/ [the] exile of"]', '["n-f"]', 'captivity; concretely, exiles (collectively) (they that are carried away) captives(-ity).', 'feminine from 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0192}/[H192]', 'lemma', 'heb', 'אֱוִיל מְרֹדַךְ', '["ʼĔvîyl Mᵉrôdak"]', '["Evil-","Merodach"]', '["n-pr-m"]', 'Evil-Merodak, a Babylonian king Evil-merodach.', 'of Aramaic derivation and probably meaning soldier of Merodak;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4427A}/H9043/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["became king/ he"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0894}/[H1101]', 'inflected', 'heb', 'בָּבֶל', '["Bâbel"]', '["[are] in/ Babylon","in/ Babylon","on/ Babylon"]', '["n-pr-loc"]', 'Babel (i.e. Babylon), including Babylonia and the Babylonian empire Babel, Babylon.', 'from 1101; confusion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8132}/[H8132]', 'inflected', 'heb', 'שָׁנָא', '["shânâʼ"]', '["and/ he changed"]', '["v"]', 'to alter change.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3608}/H9023/[H3607]', 'inflected', 'heb', 'כֶּלֶא', '["keleʼ"]', '["imprisonment/ his"]', '["n-m"]', 'a prison prison. Compare 3610, 3628.', 'from 3607;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0737}/H9023/[H732]', 'inflected', 'heb', 'אֲרֻחָה', '["ʼăruchâh"]', '["and/ allowance/ his"]', '["n-f"]', 'a ration of food allowance, diet, dinner, victuals.', 'feminine passive participle of 732 (in the sense of appointing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0737}/[H732]', 'lemma', 'heb', 'אֲרֻחָה', '["ʼăruchâh"]', '["a food allowance","a portion of","an allowance of"]', '["n-f"]', 'a ration of food allowance, diet, dinner, victuals.', 'feminine passive participle of 732 (in the sense of appointing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3315}\/[H6601]', 'inflected', 'heb', 'יֶפֶת', '["Yepheth"]', '["and/ Japheth"]', '["n-pr-m"]', 'Jepheth, a son of Noah; also his posterity Japheth.', 'from 6601; expansion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8494}\/[H8494]', 'inflected', 'heb', 'תִּירָס', '["Tîyrâç"]', '["and/ Tiras"]', '["n-pr-m"]', 'Tiras, a son of Japheth Tiras.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7384A>', 'inflected', 'heb', 'ודיפת', '["ve./di.Fat"]', '["and/ Diphath"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8659G}/H9011/[H8658]', 'inflected', 'heb', 'תַּרְשִׁישׁ', '["Tarshîysh"]', '["and/ Tarshish/ <towards>"]', '["n-pr-m n-pr-loc"]', 'Tarshish, a place on the Mediterranean, hence, the ephithet of a merchant vessel (as if for or from that port); also the name of a Persian and of an Israelite Tarshish, Tharshish.', 'probably the same as 8658 (as the region of the stone, or the reverse);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1721>\', 'inflected', 'heb', 'ורודנים ס', '["ve./ro.da.Nim"]', '["and/ Rodanim"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6316G>', 'opaque', 'heb', 'פּוּט', '["Pûwṭ"]', '["Put"]', '["n-pr"]', 'Put, a son of Ham, also the name of his descendants or their region, and of a Persian tribe Phut, Put.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1719B>\', 'inflected', 'heb', 'ודדן ס', '["u./de.Dan"]', '["and/ Dedan"]', NULL, NULL, NULL);
