INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5780G}/[H5779]', 'inflected', 'heb', 'עוּץ', '["ʻÛwts"]', '["and/ Uz"]', '["n-pr-m n-pr-loc"]', 'Uts, a son of Aram, also a Seirite, and the regions settled by them. Uz.', 'apparently from 5779; consultation;');
