INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0326}/[H326]', 'lemma', 'heb', 'אֲחַשְׁתָּרִי', '["ʼăchashtârîy"]', '["Haahashtari"]', '["n-pr-m"]', 'an achastarite (i.e. courier); the designation (rather than name) of an Israelite Haakashtari (includ. the article).', 'probably of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6889}/[H6671]', 'lemma', 'heb', 'צֶרֶת', '["Tsereth"]', '["Zereth"]', '["n-pr-m"]', 'Tsereth, an Israelite Zereth.', 'perhaps from 6671; splendor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6714G}/[H6713]', 'inflected', 'heb', 'צֹחַר', '["Tsôchar"]', '["and/ Zohar"]', '["n-pr-m"]', 'Tsochar, the name of a Hittite and of an Israelite Zohar. Compare 3328.', 'from the same as 6713; whiteness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0869}/[H868]', 'inflected', 'heb', 'אֶתְנַן', '["ʼEthnan"]', '["and/ Ethnan"]', '["n-pr-m"]', 'Ethnan, an Israelite Ethnan.', 'the same as 868 in the sense of 867;');
