INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6036}/[H6025]', 'lemma', 'heb', 'עָנוּב', '["ʻÂnûwb"]', '["Anub"]', '["n-pr-m"]', 'Anub, an Israelite Anub.', 'passive participle from the same as 6025; borne (as fruit);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6637}/[H6632]', 'inflected', 'heb', 'צֹבֵבָה', '["Tsôbêbâh"]', '["the/ Zobebah [clans]"]', '["n-pr-m"]', 'Tsobebah, an Israelitess Zobebah.', 'feminine active participle of the same as 6632; the canopier (with the article);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0316}/[H310]', 'lemma', 'heb', 'אֲחַרְחֵל', '["ʼĂcharchêl"]', '["Aharhel"]', '["n-pr-m"]', 'Acharchel, an Israelite Aharhel,', 'from 310 and 2426; behind (the) intrenchment (i.e. safe);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2037}/[H2036]', 'lemma', 'heb', 'הָרֻם', '["Hârum"]', '["Harum"]', '["n-pr-m"]', 'Harum, an Israelite Harum.', 'passive participle of the same as 2036; high;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3258H>', 'opaque', 'heb', 'יַעְבֵּץ', '["Yaʻbêts"]', '["Jabez"]', '["n-pr-m n-pr-loc"]', 'Jabets, the name of an Israelite, and also of a place in Palestine Jabez.', 'from an unused root probably meaning to grieve; sorrowful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0251G}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["more than/ brothers/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6090A}/[H6089]', 'inflected', 'heb', 'עֹצֶב', '["ʻôtseb"]', '["in/ pain"]', '["n-m"]', 'an idol (as fashioned); also pain (bodily or mental) idol, sorrow, × wicked.', 'a variation of 6089;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1366G}/H9020/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["territory/ my"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7451C}/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["from/ harm"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6087A}/H9030/[H6087]', 'inflected', 'heb', 'עָצַב', '["ʻâtsab"]', '["to hurt/ me"]', '["v"]', 'properly, to carve, i.e. fabricate or fashion; hence (in a bad sense) to worry, pain or anger displease, grieve, hurt, make, be sorry, vex, worship, wrest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0935M}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ he brought","and/ he has brought [it]"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3620G}/[H3619]', 'inflected', 'heb', 'כְּלוּב', '["Kᵉlûwb"]', '["and/ Kelub"]', '["n-pr-m"]', 'Kelub, the name of two Israelites Chelub.', 'the same as 3619;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7746}/[H7745]', 'lemma', 'heb', 'שׁוּחָה', '["Shûwchâh"]', '["Shuhah"]', '["n-pr-m"]', 'Shuchah, an Israelite Shuah.', 'the same as 7745;');
