INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3433}/[H7725]', 'inflected', 'heb', 'יָשֻׁבִי לֶחֶם', '["Yâshubîy Lechem"]', '["and/ Jashubi"]', '["n-pr-m"]', 'Jashubi-Lechem, an Israelite Jashubi-lehem. (Prob. the text should be pointed יֹשְׁבֵי לֶחֶם and rendered ''(they were) inhabitants of Lechem,'' i.e. of Bethlehem (by contraction). Compare 3902).', 'from 7725 and 3899; returner of bread;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3433}/[H7725]', 'lemma', 'heb', 'יָשֻׁבִי לֶחֶם', '["Yâshubîy Lechem"]', '["Lehem"]', '["n-pr-m"]', 'Jashubi-Lechem, an Israelite Jashubi-lehem. (Prob. the text should be pointed יֹשְׁבֵי לֶחֶם and rendered ''(they were) inhabitants of Lechem,'' i.e. of Bethlehem (by contraction). Compare 3902).', 'from 7725 and 3899; returner of bread;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1697K}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ the/ words"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
