INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3335H}/[H3334]', 'inflected', 'heb', 'יָצַר', '["yâtsar"]', '["[were] the/ potters","the/ potter"]', '["v"]', 'to mould into a form; especially as a potter; figuratively, to determine (i.e. form a resolution) × earthen, fashion, form, frame, make(-r), potter, purpose.', 'probably identical with 3334 (through the squeezing into shape); (compare 3331);');
