INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3996}/[H935]', 'inflected', 'heb', 'מָבוֹא', '["mâbôwʼ"]', '["to/ [the] entrance of"]', '["n-m"]', 'an entrance (the place or the act); specifically sunset or the west; also (adverb with preposition) towards by which came, as cometh, in coming, as men enter into, entering, entrance into, entry, where goeth, going down, westward. Compare 4126.', 'from 935; (with or without 8121)');
