INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8252}/[H8252]', 'inflected', 'heb', 'שָׁקַט', '["shâqaṭ"]', '["and/ I may be at peace","and/ [has been] undisturbed","and/ [is] undisturbed","and/ at peace","and/ it was quiet","and/ show quietness"]', '["v"]', 'to repose (usually figurative) appease, idleness, (at, be at, be in, give) quiet(-ness), (be at, be in, give, have, take) rest, settle, be still.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7961}/[H7951]', 'inflected', 'heb', 'שָׁלֵו', '["shâlêv"]', '["and/ [people] at ease of","and/ at ease"]', '["a"]', 'tranquil; (in a bad sense) careless; abstractly, security (being) at ease, peaceable, (in) prosper(-ity), quiet(-ness), wealthy.', 'or שָׁלֵיו; feminine שְׁלֵוָה; from 7951;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2526H}/[H2525]', 'lemma', 'heb', 'חָם', '["Châm"]', '["Ham"]', '["n-pr-m n-pr-loc"]', 'Cham, a son of Noah; also (as a patronymic) his descendants or their country Ham.', 'the same as 2525; hot (from the tropical habitat);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4586G}/[H4584]', 'inflected', 'heb', 'מְעוּנִי', '["Mᵉʻûwnîy"]', '["the/ Meunites"]', '["n-pr-m"]', 'a Meunite, or inhabitant of Maon (only in plural) Mehunim(-s), Meunim.', 'or מְעִינִי; probably patrial from 4584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2763A}/H9038/[H2763]', 'inflected', 'heb', 'חָרַם', '["châram"]', '["and/ I will totally destroy/ them","and/ they totally destroyed/ them"]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H9038}', 'inflected', 'heb', 'ומהם', '["u./me./Hem"]', '["and/ from <the>/ them","and/ from/ them","and/ some of <the>/ them","and/ some of/ them"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6410H}/[H6403]', 'inflected', 'heb', 'פְּלַטְיָה', '["Pᵉlaṭyâh"]', '["and/ Pelatiah"]', '["n-pr-m"]', 'Pelatjah, the name of four Israelites Pelatiah.', 'or פְּלַטְיָהוּ; from 6403 and 3050; Jah has delivered;');
