INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5816H}/[H5797]', 'inflected', 'heb', 'עֻזִּיאֵל', '["ʻUzzîyʼêl"]', '["and/ Uzziel"]', '["n-pr-m"]', 'Uzziel, the name of six Israelites Uzziel.', 'from 5797 and 410; strength of God;');
