INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6002G>', 'inflected', 'heb', 'לעמלק', '["la./''a.ma.Lek"]', '["of/ Amalek"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2490H}/H9043/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["and/ when/ profaned/ he"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3326A}/[H3331]', 'lemma', 'heb', 'יָצוּעַ', '["yâtsûwaʻ"]', '["[the] beds of"]', '["n-m"]', 'spread, i.e. a bed; (architecture) an extension, i.e. wing or lean-to (a single story or collectively) bed, chamber, couch.', 'passive participle of 3331;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3187}/[H3188]', 'inflected', 'heb', 'יָחַשׂ', '["yâchas"]', '["for/ genealogical enrollment","to/ have themselves enrolled"]', '["v"]', 'to enroll by pedigree (number after, number throughout the) genealogy (to be reckoned), be reckoned by genealogies.', 'a primitive root; to sprout; used only as denominative from 3188;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1062}/[H1060]', 'inflected', 'heb', 'בְּכוֹרָה', '["bᵉkôwrâh"]', '["to the/ birthright"]', '["n-f"]', 'the firstling of man or beast; abstractly primogeniture birthright, firstborn(-ling).', 'or (short) בְּכֹרָה; feminine of 1060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0251G}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["<in>/ brother/ his","among/ brothers/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5057}/[H5046]', 'inflected', 'heb', 'נָגִיד', '["nâgîyd"]', '["and/ to/ a leader"]', '["n-m"]', 'a commander (as occupying the front), civil, military or religious; generally (abstractly, plural), honorable themes captain, chief, excellent thing, (chief) governor, leader, noble, prince, (chief) ruler.', 'or נָגִד; from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1062}/[H1060]', 'inflected', 'heb', 'בְּכוֹרָה', '["bᵉkôwrâh"]', '["and/ the/ birthright"]', '["n-f"]', 'the firstling of man or beast; abstractly primogeniture birthright, firstborn(-ling).', 'or (short) בְּכֹרָה; feminine of 1060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3130G}\/[H3254]', 'inflected', 'heb', 'יוֹסֵף', '["Yôwçêph"]', '["[belonged] to/ Joseph"]', '["n-pr-m"]', 'Joseph, the name of seven Israelites Joseph. Compare 3084.', 'future of 3254; let him add (or perhaps simply active participle adding);');
