INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1568J}/[H1567]', 'lemma', 'heb', 'גִּלְעָד', '["Gilʻâd"]', '["Gilead"]', '["n-pr-loc n-pr-m"]', 'Gilad, a region East of the Jordan; also the name of three Israelites Gilead, Gileadite.', 'probably from 1567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4317I}/[H4310]', 'lemma', 'heb', 'מִיכָאֵל', '["Mîykâʼêl"]', '["Michael"]', '["n-pr-m"]', 'Mikael, the name of an archangel and of nine Israelites Michael.', 'from 4310 and (the prefix derivative from) 3588 and 410; who (is) like God?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3454}/[H3453]', 'lemma', 'heb', 'יְשִׁישָׁי', '["Yᵉshîyshây"]', '["Jeshishai"]', '["n-pr-m"]', 'Jeshishai, an Israelite Jeshishai.', 'from 3453; aged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3163}/[H3162]', 'lemma', 'heb', 'יַחְדוֹ', '["Yachdôw"]', '["Jahdo"]', '["n-pr-m"]', 'Jachdo, an Israelite Jahdo.', 'from 3162 with pronominal suffix; his unity, i.e. (adverb) together;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0938H}/[H937]', 'lemma', 'heb', 'בּוּז', '["Bûwz"]', '["Buz"]', '["n-pr-m"]', 'Buz, the name of a son of Nahor, and of an Israelite Buz.', 'the same as 937;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0277G}/[H251]', 'lemma', 'heb', 'אֲחִי', '["ʼĂchîy"]', '["Ahi"]', '["n-pr-m"]', 'Achi, the name of two Israelites Ahi.', 'from 251; brotherly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5661}/[H5650]', 'lemma', 'heb', 'עַבְדִיאֵל', '["ʻAbdîyʼêl"]', '["Abdiel"]', '["n-pr-m"]', 'Abdiel, an Israelite Abdiel. Compare 5655.', 'from 5650 and 410; servant of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1476H}/[H1598]', 'lemma', 'heb', 'גּוּנִי', '["Gûwnîy"]', '["Guni"]', '["n-pr-m"]', 'Guni, the name of two Israelites Guni.', 'probably from 1598; protected;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8289H}/[H3474]', 'lemma', 'heb', 'שָׁרוֹן', '["Shârôwn"]', '["Sharon"]', '["n-pr"]', 'Sharon, the name of a place in Palestine Lasharon, Sharon.', 'probably abridged from 3474; plain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8444}/H9028/[H3318]', 'inflected', 'heb', 'תּוֹצָאָה', '["tôwtsâʼâh"]', '["extremities/ their"]', '["n-f"]', '(only in plural collective) exit, i.e. (geographical) boundary, or (figuratively) deliverance, (actively) source border(-s), going(-s) forth (out), issues, outgoings.', 'or תֹּצָאָה; from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3187}/[H3188]', 'lemma', 'heb', 'יָחַשׂ', '["yâchas"]', '["[the] genealogical enrolment","a genealogical list","they had themselves enrolled"]', '["v"]', 'to enroll by pedigree (number after, number throughout the) genealogy (to be reckoned), be reckoned by genealogies.', 'a primitive root; to sprout; used only as denominative from 3188;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1425}/[H1410]', 'inflected', 'heb', 'גָּדִי', '["Gâdîy"]', '["and/ [the] Gadite[s]"]', '["a"]', 'a Gadite (collectively) or descendants of Gad Gadites, children of Gad.', 'patronymically from 1410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1869}/[H1869]', 'inflected', 'heb', 'דָּרַךְ', '["dârak"]', '["and/ [one who] treads","and/ [the] treader of","and/ [those who] bend","and/ [who] bent"]', '["v"]', 'to tread; by implication, to walk; also to string a bow (by treading on it in bending) archer, bend, come, draw, go (over), guide, lead (forth), thresh, tread (down), walk.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3925G}/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["and/ I taught","and/ [who] were trained of","and/ teach","and/ teaching","so/ he may teach"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6213J}/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ he will act","and/ they did","and/ they made"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3195H}/[H2905]', 'inflected', 'heb', 'יְטוּר', '["Yᵉṭûwr"]', '["and/ Jetur"]', '["n-pr-m"]', 'Jetur, a son of Ishmael Jetur.', 'probably from the same as 2905; encircled (i.e. inclosed);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5305}/[H5314]', 'inflected', 'heb', 'נָפִישׁ', '["Nâphîysh"]', '["and/ Naphish"]', '["n-pr-m"]', 'Naphish, a son of Ishmael, and his posterity Naphish.', 'from 5314; refreshed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5114}/[H5068]', 'inflected', 'heb', 'נוֹדָב', '["Nôwdâb"]', '["and/ Nodab"]', '["n-pr-m"]', 'Nodab, an Arab tribe Nodab.', 'from 5068; noble;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5973A}/H9038/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["[those] who/ [were] with/ them"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H0430G}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["[was] from/ <the>/ God"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1473}\/[H1540]', 'inflected', 'heb', 'גּוֹלָה', '["gôwlâh"]', '["the/ exile","the/ exile[s]"]', '["n-f"]', 'exile; concretely and collectively exiles (carried away), captive(-ity), removing.', 'or (shortened) גֹּלָה; active participle feminine of 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1316>', 'inflected', 'heb', 'מבשן', '["mi./Ba.shon","mi./ba.Shan"]', '["from/ Bashan"]', NULL, NULL, NULL);
