INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1938H}/[H1935]', 'inflected', 'heb', 'הוֹדַוְיָה', '["Hôwdavyâh"]', '["and/ Hodaviah"]', '["n-pr-m"]', 'Hodavjah, the name of three Israelites Hodaviah.', 'from 1935 and 3050; majesty of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3164}/[H3162]', 'inflected', 'heb', 'יַחְדִּיאֵל', '["Yachdîyʼêl"]', '["and/ Jahdiel"]', '["n-pr-m"]', 'Jachdiel, an Israelite Jahdiel.', 'from 3162 and 410; unity of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5782}/[H5782]', 'inflected', 'heb', 'עוּר', '["ʻûwr"]', '["and/ I excited myself","and/ I will rouse","and/ he stirred up","and/ he will wield"]', '["v"]', 'to wake (literally or figuratively) (a-) wake(-n, up), lift up (self), × master, raise (up), stir up (self).', 'a primitive root (rather identical with through the idea of opening the eyes);');
