INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251G}/H9028/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ brothers/ their","and/ relatives/ their"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2918}/H9028/[H2905]', 'inflected', 'heb', 'טִירָה', '["ṭîyrâh"]', '["to/ encampments/ their"]', '["n-f"]', 'a wall; hence, a fortress or a hamlet (goodly) castle, habitation, palace, row.', 'feminine of (an equivalent to) 2905;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1366G}/H9028/[H1379]', 'inflected', 'heb', 'גְּבוּל', '["gᵉbûwl"]', '["in/ territory/ their"]', '["n-m"]', 'properly, a cord (as twisted), i.e. (by implication) a boundary; by extension the territory inclosed border, bound, coast, × great, landmark, limit, quarter, space.', 'or גְּבֻל; (shortened) from 1379;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3312G}\/[H6437]', 'inflected', 'heb', 'יְפֻנֶּה', '["Yᵉphunneh"]', '["Jephunneh"]', '["n-pr-m"]', 'Jephunneh, the name of two Israelites Jephunneh.', 'from 6437; he will be prepared;');
