INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4054}/H9024\/[H1644]', 'inflected', 'heb', 'מִגְרָשׁ', '["migrâsh"]', '["pasture lands/ its"]', '["n-m"]', 'a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb.', 'also (in plural) feminine (Ezekiel 27:28) מִגְרָשָׁה; from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5964G}/[H5956]', 'lemma', 'heb', 'עָלֶמֶת', '["ʻÂlemeth"]', '["Alemeth"]', '["n-pr-m"]', 'Alemeth, the name of a place in Palestine and of two Israelites Alameth, Alemeth.', 'from 5956; a covering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4940}/H9028\/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["in/ clans/ their"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4054}/H9028/[H1644]', 'inflected', 'heb', 'מִגְרָשׁ', '["migrâsh"]', '["pasture lands/ their"]', '["n-m"]', 'a suburb (i.e. open country whither flocks are driven from pasture); hence, the area around a building, or the margin of the sea cast out, suburb.', 'also (in plural) feminine (Ezekiel 27:28) מִגְרָשָׁה; from 1644;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8034}\/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["by/ names"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4940}/[H8192]', 'inflected', 'heb', 'מִשְׁפָּחָה', '["mishpâchâh"]', '["and/ some of/ [the] clans of"]', '["n-f"]', 'a family, i.e. circle of relatives; figuratively, a class (of persons), a species (of animals) or sort (of things); by extension a tribe or people family, kind(-red).', 'from 8192 (compare 8198);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3361H}/[H6965]', 'lemma', 'heb', 'יׇקְמְעָם', '["Yoqmᵉʻâm"]', '["Jokmeam"]', '["n-pr-loc"]', 'Jokmeam, a place in Palestine Jokmeam. Compare 3360, 3362.', 'from 6965 and 5971; (the) people will be raised;');
