INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6252H}/[H6251]', 'lemma', 'heb', 'עַשְׁתָּרוֹת', '["ʻAshtârôwth"]', '["Ashtaroth"]', '["n-pr-f"]', 'Ashtaroth, the name of a Sidonian deity, and of a place East of the Jordan Asharoth, Astaroth. See also 1045, 6253, 6255.', 'or עַשְׁתָּרֹת; plural of 6251;');
