INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2712B}/[H2710]', 'lemma', 'heb', 'חֻקֹּק', '["Chuqqôq"]', '["Hukok"]', '["n-pr-loc"]', 'Chukkok or Chukok, a place in Palestine Hukkok, Hukok.', 'or (fully) חוּקֹק; from 2710; appointed;');
