INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0289H}/[H251]', 'inflected', 'heb', 'אֲחִימַן', '["ʼĂchîyman"]', '["and/ Ahiman"]', '["n-pr-m"]', 'Achiman, the name of an Anakite and of an Israelite Ahiman.', 'or אֲחִימָן ; from 251 and 4480; brother of a portion (i.e. gift);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7967M}/[H7966]', 'inflected', 'heb', 'שַׁלּוּם', '["Shallûwm"]', '["and/ Shallum"]', '["n-pr-m"]', 'Shallum, the name of fourteen Israelites Shallum.', 'or (shorter) שַׁלֻּם; the same as 7966;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6981G}/[H7121]', 'lemma', 'heb', 'קוֹרֵא', '["Qôwrêʼ"]', '["Kore"]', '["n-pr-m"]', 'Kore, the name of two Israelites Kore.', 'or קֹרֵא; (1 Chronicles 26:1), active participle of 7121; crier;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3996}/[H935]', 'inflected', 'heb', 'מָבוֹא', '["mâbôwʼ"]', '["the/ entrance"]', '["n-m"]', 'an entrance (the place or the act); specifically sunset or the west; also (adverb with preposition) towards by which came, as cometh, in coming, as men enter into, entering, entrance into, entry, where goeth, going down, westward. Compare 4126.', 'from 935; (with or without 8121)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148A}/[H2142]', 'lemma', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4920}/[H7999]', 'lemma', 'heb', 'מְשֶׁלֶמְיָה', '["Mᵉshelemyâh"]', '["Meshelemiah"]', '["n-pr-m"]', 'Meshelemjah, an Israelite Meshelemiah.', 'or מְשֶׁלֶמְיָהוּ; from 7999 and 3050; ally of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1305}/[H1305]', 'inflected', 'heb', 'בָּרַר', '["bârar"]', '["those/ [who] had been chosen","who/ had been chosen"]', '["v"]', 'to clarify (i.e. brighten), examine, select make bright, choice, chosen, cleanse (be clean), clearly, polished, (shew self) pure(-ify), purge (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7778}/[H8176]', 'inflected', 'heb', 'שׁוֹעֵר', '["shôwʻêr"]', '["[will become] <into>/ [the] gatekeepers of","of/ gatekeepers","to/ gatekeepers"]', '["n-m"]', 'a janitor doorkeeper, porter.', 'or שֹׁעֵר active participle of 8176 (as denominative from 8179);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0530}/H9028/[H529]', 'inflected', 'heb', 'אֱמוּנָה', '["ʼĕmûwnâh"]', '["in/ faithfulness/ their"]', '["n-f"]', 'literally firmness; figuratively security; morally fidelity faith(-ful, -ly, -ness, (man)), set office, stability, steady, truly, truth, verily.', 'or (shortened) אֱמֻנָה; feminine of 529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121G}/H9028/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ descendants/ their","and/ sons/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307I}/[H7306]', 'lemma', 'heb', 'רוּחַ', '["rûwach"]', '["[the] side of","sides"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6256}/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["from/ [the] time","from/ time","more than/ a time"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H3957>', 'inflected', 'heb', 'הלשכות', '["Ha./le.sha.khot","ha./le.sha.Khot","ha./le.sha.khot","ha./lish.Kah","ha./lish.Khot"]', '["the/ room","the/ rooms","the/ rooms of","the/ store-rooms"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0214}/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["the/ store","the/ storehouse","the/ storehouses","the/ treasuries of","the/ treasury"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1242}/[H1239]', 'inflected', 'heb', 'בֹּקֶר', '["bôqer"]', '["and/ to the/ morning"]', '["n-m"]', 'properly, dawn (as the break of day); generally, morning ( ) day, early, morning, morrow.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4557}/[H5608]', 'inflected', 'heb', 'מִסְפָּר', '["miçpâr"]', '["and/ by/ number"]', '["n-m"]', 'a number, definite (arithmetical) or indefinite (large, innumerable; small, a few); also (abstractly) narration abundance, account, × all, × few, (in-) finite, (certain) number(-ed), tale, telling, time.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5560>', 'inflected', 'heb', 'הסלת', '["ha./So.let"]', '["the/ fine flour"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8081}/[H8080]', 'inflected', 'heb', 'שֶׁמֶן', '["shemen"]', '["and/ the/ oil"]', '["n-m"]', 'grease, especially liquid (as from the olive, often perfumed); figuratively, richness anointing, × fat (things), × fruitful, oil(-ed), ointment, olive, pine.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3828}/[H3836]', 'inflected', 'heb', 'לְבוֹנָה', '["lᵉbôwnâh"]', '["and/ the/ frankincense"]', '["n-f"]', 'frankincense (from its whiteness or perhaps that of its smoke) (frank-) incense.', 'or לְבֹנָה; from 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1314}/[H1313]', 'inflected', 'heb', 'בֶּשֶׂם', '["besem"]', '["and/ the/ spices"]', '["n-m"]', 'fragrance; by implication, spicery; also the balsam plant smell, spice, sweet (odour).', 'or בֹּשֶׂם; from the same as 1313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4842}/[H7543]', 'inflected', 'heb', 'מִרְקַחַת', '["mirqachath"]', '["<of> the/ mixture"]', '["n-f"]', 'an aromatic unguent; also an unguent-pot prepared by the apothecaries'' art, compound, ointment.', 'from 7543;');
