INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4993G}/[H4991]', 'inflected', 'heb', 'מַתִּתְיָה', '["Mattithyâh"]', '["and/ Mattithiah"]', '["n-pr-m"]', 'Mattithjah, the name of four Israelites Mattithiah. n', 'or מַתִּתְיָהוּ; from 4991 and 3050; gift of Jah;');
