INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3559A}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["to/ prepare","to/ prepare [it]"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7676}\/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["sabbath"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3957>', 'inflected', 'heb', 'בלשכת', '["ba./le.sha.Khot","be./lish.Kat","be./lish.Khot"]', '["[were] in the/ rooms","in/ [the] room of","in/ [the] rooms of","over/ [the] store-room of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6362}/[H6362]', 'lemma', 'heb', 'פָּטַר', '["pâṭar"]', '["[is one who] lets out","he dismissed","set free","they make a separation"]', '["v"]', 'to cleave or burst through, i.e. (causatively) to emit, whether literal or figurative (gape) dismiss, free, let (shoot) out, slip away.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3273P}/[H3261]', 'lemma', 'heb', 'יְעִיאֵל', '["Yᵉʻîyʼêl"]', '["Jeiel"]', '["n-pr-m"]', 'Jeiel, the name of six Israelites Jeiel, Jehiel. Compare 3262.', 'from 3261 and 410; carried away of God;');
