INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0682A}\/[H680]', 'inflected', 'heb', 'אָצֵל', '["ʼÂtsêl"]', '["Azel"]', '["n-pr-m n-pr-loc"]', 'Atsel, the name of an Israelite, and of a place in Palestine Azal, Azel.', 'from 680; noble;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1533H}/[H1530]', 'lemma', 'heb', 'גִּלְבֹּעַ', '["Gilbôaʻ"]', '["Gilboa"]', '["n-pr-loc"]', 'Gilboa, a mountain of Palestine Gilboa.', 'from 1530 and 1158; fountain of ebullition;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6584}/H9033/[H6584]', 'inflected', 'heb', 'פָּשַׁט', '["pâshaṭ"]', '["and/ they stripped/ him"]', '["v"]', 'to spread out (i.e. deploy in hostile array); by analogy, to strip (i.e. unclothe, plunder, flay, etc.) fall upon, flay, invade, make an invasion, pull off, put off, make a road, run upon, rush, set, spoil, spread selves (abroad), strip (off, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1712}\/[H1709]', 'inflected', 'heb', 'דָּגוֹן', '["Dâgôwn"]', '["Dagon"]', '["n-pr-m"]', 'Dagon, a Philistine deity Dagon.', 'from 1709; the fish-god;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1480}/[H1479]', 'lemma', 'heb', 'גּוּפָה', '["gûwphâh"]', '["[the] corpse of","[the] corpses of"]', '["n-f"]', 'a corpse (as closed to sense) body.', 'from 1479;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3003G}/[H3002]', 'inflected', 'heb', 'יָבֵשׁ', '["Yâbêsh"]', '["in/ Jabesh"]', '["n-pr-loc n-pr-m"]', 'Jobesh, the name of an Israelite and of a place in Palestine Jobesh (-Gilead).', 'the same as 3002 (also יָבֵישׁ; often with the addition of 1568, i.e. Jabesh of Gilad);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4604}/H9023/[H4603]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["for/ unfaithfulness/ his","in/ unfaithfulness/ his"]', '["n-m"]', 'treachery, i.e. sin falsehood, grievously, sore, transgression, trespass, × very.', 'from 4603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3448}\/[H3426]', 'inflected', 'heb', 'יִשַׁי', '["Yishay"]', '["Jesse"]', '["n-pr-m"]', 'Jishai, David''s father Jesse.', 'by Aramaic אִישַׁי; from the same as 3426; extant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5439G}/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["the/ surroundings"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7605}/[H7604]', 'lemma', 'heb', 'שְׁאָר', '["shᵉʼâr"]', '["[the] remainder of","[the] remnant of","a remnant"]', '["n-m"]', 'a remainder × other, remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2388G}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["who/ held strongly"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4438}/H9023/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["in/ kingdom/ his","in/ own kingdom/ his","in/ reign/ his"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3434G}/[H7725]', 'lemma', 'heb', 'יָשׇׁבְעָם', '["Yâshobʻâm"]', '["Jashobeam"]', '["n-pr-m"]', 'Jashobam, the name of two or three Israelites Jashobeam.', 'from 7725 and 5971; people will return;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2453G}/[H2449]', 'lemma', 'heb', 'חַכְמוֹנִי', '["Chakmôwnîy"]', '["a Hacmonite"]', '["n-pr-m"]', 'Chakmoni, an Israelite Hachmoni, Hachmonite.', 'from 2449; skilful;');
