INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8491}\/[H8491]', 'inflected', 'heb', 'תִּיצִי', '["Tîytsîy"]', '["the/ Tizite"]', '["n-pr-m"]', 'a Titsite or descendant or inhabitant of an unknown Tits Tizite.', 'patrial or patronymically from an unused noun of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0447J}/[H410]', 'lemma', 'heb', 'אֱלִיאֵל', '["ʼĔlîyʼêl"]', '["Eliel"]', '["n-pr-m"]', 'Eliel, the name of nine Israelites Eliel.', 'from 410 repeated; God of (his) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4233}/[H4233]', 'inflected', 'heb', 'מַחֲוִים', '["Machăvîym"]', '["the/ Mahavite"]', '["a"]', 'a Machavite or inhabitant of some place named Machaveh Mahavite.', 'apparently a patrial, but from an unknown place (in the plural only for a singular);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3403}/[H3401]', 'inflected', 'heb', 'יְרִיבַי', '["Yᵉrîybay"]', '["and/ Jeribai"]', '["n-pr-m"]', 'Jeribai, an Israelite Jeribai.', 'from 3401; contentious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3145}/[H3068]', 'inflected', 'heb', 'יוֹשַׁוְיָה', '["Yôwshavyâh"]', '["and/ Joshaviah"]', '["n-pr-m"]', 'Joshavjah, an Israelite Joshaviah. Compare 3144.', 'from 3068 and 7737; Jehovah-set;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0493}/[H410]', 'lemma', 'heb', 'אֶלְנַעַם', '["ʼElnaʻam"]', '["Elnaam"]', '["n-pr-m"]', 'Elnaam, an Israelite Elnaam.', 'from 410 and 5276; God (is his) delight;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3495}/[H3490]', 'inflected', 'heb', 'יִתְמָה', '["Yithmâh"]', '["and/ Ithmah"]', '["n-pr-m"]', 'Jithmah, an Israelite Ithmah.', 'from the same as 3490; orphanage;');
