INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5744I}/[H5647]', 'inflected', 'heb', 'עוֹבֵד', '["ʻÔwbêd"]', '["and/ Obed"]', '["n-pr-m"]', 'Obed, the name of five Israelites Obed.', 'active participle of 5647; serving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3300G}/[H6213]', 'inflected', 'heb', 'יַעֲשִׂיאֵל', '["Yaʻăsîyʼêl"]', '["and/ Jaasiel"]', '["n-pr-m"]', 'Jaasiel, an Israelite Jaasiel, Jasiel.', 'from 6213 and 410; made of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4677}\/[H4672]', 'inflected', 'heb', 'מְצֹבָיָה', '["Mᵉtsôbâyâh"]', '["the/ Mezobaite"]', '["n-pr"]', 'Metsobajah, a place in Palestine Mesobaite.', 'apparently from 4672 and 3050; found of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6860>', 'inflected', 'heb', 'לציקלג', '["le./Tzi.ke.Lag"]', '["to/ Ziklag"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5401B}/[H5400]', 'lemma', 'heb', 'נָשַׁק', '["nâshaq"]', '["[men] equipped of","[they were] equipped of","[were] equipped of"]', '["v"]', 'to kiss, literally or figuratively (touch); also (as a mode of attachment), to equip with weapons armed (men), rule, kiss, that touched.', 'a primitive root (identical with 5400, through the idea of fastening up; compare 2388, 2836);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3231}/[H3225]', 'lemma', 'heb', 'יָמַן', '["yâman"]', '["go to [the] right","using right [hand]"]', '["v"]', 'to be right-handed or take the right-hand side go (turn) to (on, use) the right hand.', 'a primitive root; to be (physically) right (i.e. firm); but used only as denominative from 3225 and transitive,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2671}/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["and/ with <the>/ arrows","and/ with/ arrows"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0251H}/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["some of/ [the] relatives of"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0295H}/[H251]', 'lemma', 'heb', 'אֲחִיעֶזֶר', '["ʼĂchîyʻezer"]', '["Ahiezer"]', '["n-pr-m"]', 'Achiezer, the name of two Israelites Ahiezer.', 'from 251 and 5828; brother of help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3101L}/[H3060]', 'inflected', 'heb', 'יוֹאָשׁ', '["Yôwʼâsh"]', '["and/ Joash"]', '["n-pr-m"]', 'Joash, the name of six Israelites Joash.', 'or יֹאָשׁ; (2 Chronicles 24:1), a form of 3060;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8094}/[H8093]', 'inflected', 'heb', 'שְׁמָעָה', '["Shᵉmâʻâh"]', '["the/ Shemaahite"]', '["n-pr-m"]', 'Shemaah, an Israelite Shemaah.', 'for 8093;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1395}/[H1390]', 'inflected', 'heb', 'גִּבְעָתִי', '["Gibʻâthîy"]', '["the/ Gibeathite"]', '["a"]', 'a Gibathite, or inhabitant of Gibath Gibeathite.', 'patrial from 1390;');
