INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6404H}/[H6403]', 'inflected', 'heb', 'פֶּלֶט', '["Peleṭ"]', '["and/ Pelet"]', '["n-pr-m"]', 'Pelet, the name of two Israelites Pelet. See also 1046.', 'from 6403; escape;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5820I}/[H5794]', 'lemma', 'heb', 'עַזְמָוֶת', '["ʻAzmâveth"]', '["Azmaveth"]', '["n-pr-m n-pr-loc"]', 'Azmaveth, the name of three Israelites and of a place in Palestine Azmaveth. See also 1041.', 'from 5794 and 4194; strong one of death;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1294G}/[H1293]', 'inflected', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["and/ Berachah"]', '["n-pr-m n-pr-loc"]', 'Berakah, the name of an Israelite, and also of a valley in Palestine Berachah.', 'the same as 1293;');
