INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3460G}/[H8085]', 'inflected', 'heb', 'יִשְׁמַעְיָה', '["Yishmaʻyâh"]', '["and/ Ishmaiah"]', '["n-pr-m"]', 'Jishmajah, the name of two Israelites Ishmaiah.', 'or יִשְׁמַעְיָהוּlemma יְשְׁמַעְיָהוּ first vowel, corrected to יִשְׁמַעְיָהוּ; from 8085 and 3050; Jah will hear;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3414I}/[H7311]', 'inflected', 'heb', 'יִרְמְיָה', '["Yirmᵉyâh"]', '["and/ Jeremiah"]', '["n-pr-m"]', 'Jirmejah, the name of eight or nine Israelites Jeremiah.', 'or יִרְמְיָהוּ; from 7311 and 3050; Jah will rise;');
