INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3076G}/[H3068]', 'inflected', 'heb', 'יְהוֹחָנָן', '["Yᵉhôwchânân"]', '["and/ Johanan"]', '["n-pr-m"]', 'Jehochanan, the name of eight Israelites Jehohanan, Johanan. Compare 3110.', 'from 3068 and 2603; Jehovah-favored;');
