INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0498}/[H410]', 'lemma', 'heb', 'אֶלְעוּזַי', '["ʼElʻûwzay"]', '["Eluzai"]', '["n-pr-m"]', 'Eluzai, an Israelite Eluzai.', 'from 410 and 5756 (in the sense of 5797); God (is) defensive;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3406J}/[H7311]', 'inflected', 'heb', 'יְרִימוֹת', '["Yᵉrîymôwth"]', '["and/ Jerimoth"]', '["n-pr-f"]', 'Jerimoth or Jeremoth, the name of twelve Israelites Jermoth, Jerimoth, and Ramoth (from the margin).', 'or יְרֵימוֹת; or יְרֵמוֹת; feminine plural from 7311; elevations;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1183}/[H1167]', 'inflected', 'heb', 'בְּעַלְיָה', '["Bᵉʻalyâh"]', '["and/ Bealiah"]', '["n-pr-m"]', 'Bealjah, an Israelite Bealiah.', 'from 1167 and 3050; Jah (is) master;');
