INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8203I}/[H8199]', 'inflected', 'heb', 'שְׁפַטְיָה', '["Shᵉphaṭyâh"]', '["and/ Shephatiah"]', '["n-pr-m"]', 'Shephatjah, the name of ten Israelites Shephatiah.', 'or שְׁפַטְיָהוּ; from 8199 and 3050; Jah has judged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2741}/[H2756]', 'inflected', 'heb', 'חֲרוּפִי', '["Chărûwphîy"]', '["the/ Haruphite"]', '["n-m"]', 'a Charuphite or inhabitant of Charuph (or Chariph) Haruphite.', 'a patrial from (probably) a collateral form of 2756;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0511L}/[H410]', 'lemma', 'heb', 'אֶלְקָנָה', '["ʼElqânâh"]', '["Elkanah"]', '["n-pr-m"]', 'Elkanah, the name of several Israelites Elkanah.', 'from 410 and 7069; God has obtained;');
