INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5832G}/[H5826]', 'inflected', 'heb', 'עֲזַרְאֵל', '["ʻĂzarʼêl"]', '["and/ Azarel"]', '["n-pr-m"]', 'Azarel, the name of five Israelites Azarael, Azareel.', 'from 5826 and 410; God has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3134}/[H3068]', 'inflected', 'heb', 'יוֹעֶזֶר', '["Yôwʻezer"]', '["and/ Joezer"]', '["n-pr-m"]', 'Joezer, an Israelite Joezer.', 'from 3068 and 5828; Jehovah (is his) help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3434H}/[H7725]', 'inflected', 'heb', 'יָשׇׁבְעָם', '["Yâshobʻâm"]', '["and/ Jashobeam"]', '["n-pr-m"]', 'Jashobam, the name of two or three Israelites Jashobeam.', 'from 7725 and 5971; people will return;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3132}/[H3276]', 'inflected', 'heb', 'יוֹעֵאלָה', '["Yôwʻêʼlâh"]', '["and/ Joelah"]', '["n-pr-f"]', 'Joelah, an Israelite Joelah.', 'perhaps feminine active participle of 3276; furthermore;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2069I}/[H2064]', 'inflected', 'heb', 'זְבַדְיָה', '["Zᵉbadyâh"]', '["and/ Zebadiah"]', '["n-pr-m"]', 'Zebadjah, the name of nine Israelites Zebadiah.', 'or זְבַדְיָהוּ; from 2064 and 3050; Jah has given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3395K}/[H7355]', 'lemma', 'heb', 'יְרֹחָם', '["Yᵉrôchâm"]', '["Jeroham"]', '["n-pr-m"]', 'Jerocham, the name of seven or eight Israelites Jeroham.', 'from 7355; compassionate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1446G}/[H1443]', 'inflected', 'heb', 'גְדֹר', '["Gᵉdôr"]', '["<the>/ Gedor"]', '["n-pr-m n-pr-loc"]', 'Gedor, a place in Palestine; also the name of three Israelites Gedor.', 'or (fully) גְּדוֹר; from 1443; inclosure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4679}/[H6679]', 'inflected', 'heb', 'מְצַד', '["mᵉtsad"]', '["to the/ fortress"]', '["n-f"]', 'a fastness (as a covert of ambush) castle, fort, (strong) hold, munition.', 'or מְצָד; or (feminine) מְצָדָה; from 6679;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440H}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ [the] face of","and/ [the] faces of","and/ [were] faces of","and/ faces"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6643B}/[H6638]', 'inflected', 'heb', 'צְבִי', '["tsᵉbîy"]', '["and/ like/ gazelles"]', '["n-m"]', 'splendor (as conspicuous) beautiful(-ty), glorious (-ry), goodly, pleasant, roe(-buck).', 'from 6638 in the sense of prominence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4116A}\/[H4116]', 'inflected', 'heb', 'מָהַר', '["mâhar"]', '["to/ hastening"]', '["v"]', 'properly, to be liquid or flow easily, i.e. (by implication); to hurry (in a good or a bad sense); often used (with another verb) adverbially, promptly be carried headlong, fearful, (cause to make, in, make) haste(-n, -ily), (be) hasty, (fetch, make ready) × quickly, rash, × shortly, (be so) × soon, make speed, × speedily, × straightway, × suddenly, swift.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5829H}/[H5828]', 'lemma', 'heb', 'עֵזֶר', '["ʻÊzer"]', '["Ezer"]', '["n-pr-m"]', 'Ezer, the name of four Israelites Ezer. Compare 5827.', 'the same as 5828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5662L}/[H5647]', 'lemma', 'heb', 'עֹבַדְיָה', '["ʻÔbadyâh"]', '["Obadiah"]', '["n-pr-m"]', 'Obadjah, the name of thirteen Israelites Obadiah.', 'or עֹבַדְיָהוּ; active participle of 5647 and 3050; serving Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0446J}/[H410]', 'lemma', 'heb', 'אֱלִיאָב', '["ʼĔlîyʼâb"]', '["Eliab"]', '["n-pr-m"]', 'Eliab, the name of six Israelites Eliab.', 'from 410 and 1; God of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4925}/[H8080]', 'lemma', 'heb', 'מִשְׁמַנָּה', '["Mishmannâh"]', '["Mishmannah"]', '["n-pr-m"]', 'Mashmannah, an Israelite Mishmannah.', 'from 8080; fatness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3414J}/[H7311]', 'lemma', 'heb', 'יִרְמְיָה', '["Yirmᵉyâh"]', '["Jeremiah"]', '["n-pr-m"]', 'Jirmejah, the name of eight or nine Israelites Jeremiah.', 'or יִרְמְיָהוּ; from 7311 and 3050; Jah will rise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6262H}/[H6261]', 'lemma', 'heb', 'עַתַּי', '["ʻAttay"]', '["Attai"]', '["n-pr-m"]', 'Attai, the name of three Israelites Attai.', 'for 6261;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0447L}/[H410]', 'lemma', 'heb', 'אֱלִיאֵל', '["ʼĔlîyʼêl"]', '["Eliel"]', '["n-pr-m"]', 'Eliel, the name of nine Israelites Eliel.', 'from 410 repeated; God of (his) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3076H}/[H3068]', 'lemma', 'heb', 'יְהוֹחָנָן', '["Yᵉhôwchânân"]', '["Johanan"]', '["n-pr-m"]', 'Jehochanan, the name of eight Israelites Jehohanan, Johanan. Compare 3110.', 'from 3068 and 2603; Jehovah-favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0443G}/[H410]', 'lemma', 'heb', 'אֶלְזָבָד', '["ʼElzâbâd"]', '["Elzabad"]', '["n-pr-m"]', 'Elzabad, the name of two Israelites Elzabad.', 'from 410 and 2064; God has bestowed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3414K}/[H7311]', 'lemma', 'heb', 'יִרְמְיָה', '["Yirmᵉyâh"]', '["Jeremiah"]', '["n-pr-m"]', 'Jirmejah, the name of eight or nine Israelites Jeremiah.', 'or יִרְמְיָהוּ; from 7311 and 3050; Jah will rise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6224}\/[H6235]', 'inflected', 'heb', 'עֲשִׂירִי', '["ʻăsîyrîy"]', '["the/ tenth"]', '["a"]', 'tenth; by abbreviation, tenth month or (feminine) part tenth (part).', 'from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4344}/[H4343]', 'lemma', 'heb', 'מַכְבַּנַּי', '["Makbannay"]', '["Machbannai"]', '["n-pr-m"]', 'a Macbannite or native of Macbena Machbanai.', 'patrial from 4343;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1419A}/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["and/ <the>/ great","and/ the/ great","and/ the/ great [person]"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4628}\/[H6150]', 'inflected', 'heb', 'מַעֲרָב', '["maʻărâb"]', '["and/ to the/ west"]', '["n-m"]', 'the west (as a region of the evening sun) west.', 'or (feminine) מַעֲרָבָה; from 6150, in the sense of shading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7965J}/[H7999]', 'inflected', 'heb', 'שָׁלוֹם', '["shâlôwm"]', '["to/ peace"]', '["n-m"]', 'safe, i.e. (figuratively) well, happy, friendly; also (abstractly) welfare, i.e. health, prosperity, peace × do, familiar, × fare, favour, friend, × great, (good) health, (× perfect, such as be at) peace(-able, -ably), prosper(-ity, -ous), rest, safe(-ty), salute, welfare, (× all is, be) well, × wholly.', 'or שָׁלֹם; from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5826}/H9030/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["[about] to/ help/ me","to/ help/ me"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3162A}/[H3161]', 'inflected', 'heb', 'יַחַד', '["yachad"]', '["for/ unity"]', '["n-m"]', 'properly, a unit, i.e. (adverb) unitedly alike, at all (once), both, likewise, only, (al-) together, withal.', 'from 3161;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7411B}/H9030/[H7411]', 'inflected', 'heb', 'רָמָה', '["râmâh"]', '["to/ betray/ me"]', '["v"]', 'to hurl; specifically, to shoot; figuratively, to delude or betray (as if causing to fall) beguile, betray, (bow-) man, carry, deceive, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3198}\/[H3198]', 'inflected', 'heb', 'יָכַח', '["yâkach"]', '["and/ may he judge"]', '["v"]', 'to be right (i.e. correct); reciprocal, to argue; causatively, to decide, justify or convict appoint, argue, chasten, convince, correct(-ion), daysman, dispute, judge, maintain, plead, reason (together), rebuke, reprove(-r), surely, in any wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6022H}/[H6006]', 'lemma', 'heb', 'עֲמָשַׂי', '["ʻĂmâsay"]', '["Amasai"]', '["n-pr-m"]', 'Amasai, the name of three Israelites Amasai.', 'from 6006; burdensome;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5973A}/H9031/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["and/ [are] with/ you","and/ [will be] with/ you","and/ with/ you"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5826}/H9031/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["[be] to/ [one who] helps/ you"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5826}/H9031/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["I have helped/ you","I will help/ you","he has helped/ you","he will help/ you"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6901}/H9038/[H6901]', 'inflected', 'heb', 'קָבַל', '["qâbal"]', '["and/ he received/ them"]', '["v"]', 'to admit, i.e. take (literally or figuratively) choose, (take) hold, receive, (under-) take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1416}\/[H1413]', 'inflected', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["the/ marauding band"]', '["n-m"]', 'a crowd (especially of soldiers) army, band (of men), company, troop (of robbers).', 'from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4519G}/[H5382]', 'inflected', 'heb', 'מְנַשֶּׁה', '["Mᵉnashsheh"]', '["and/ some of/ Manasseh"]', '["n-pr-m"]', 'Menashsheh, a grandson of Jacob, also the tribe descended from him, and its territory Manasseh.', 'from 5382; causing to forget;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5826}/H9038/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["they helped/ them","they supported/ them"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6098}/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["by/ [the] counsel of","by/ counsel","by/ plan","in/ [the] counsel of"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4519G}/[H5382]', 'inflected', 'heb', 'מְנַשֶּׁה', '["Mᵉnashsheh"]', '["some of/ Manasseh"]', '["n-pr-m"]', 'Menashsheh, a grandson of Jacob, also the tribe descended from him, and its territory Manasseh.', 'from 5382; causing to forget;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5734G}/[H5727]', 'lemma', 'heb', 'עַדְנָה', '["ʻAdnâh"]', '["Adnach"]', '["n-pr-m"]', 'Adnah, the name of two Israelites Adnah.', 'from 5727; pleasure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3107I}/[H3075]', 'inflected', 'heb', 'יוֹזָבָד', '["Yôwzâbâd"]', '["and/ Jozabad"]', '["n-pr-m"]', 'Jozabad, the name of ten Israelites Josabad, Jozabad.', 'a form of 3075;');
