INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4317M}/[H4310]', 'inflected', 'heb', 'מִיכָאֵל', '["Mîykâʼêl"]', '["and/ Michael"]', '["n-pr-m"]', 'Mikael, the name of an archangel and of nine Israelites Michael.', 'from 4310 and (the prefix derivative from) 3588 and 410; who (is) like God?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3107J}/[H3075]', 'inflected', 'heb', 'יוֹזָבָד', '["Yôwzâbâd"]', '["and/ Jozabad"]', '["n-pr-m"]', 'Jozabad, the name of ten Israelites Josabad, Jozabad.', 'a form of 3075;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0453H}/[H410]', 'inflected', 'heb', 'אֱלִיהוּ', '["ʼĔlîyhûw"]', '["and/ Elihu"]', '["n-pr-m"]', 'Elihu, the name of one of Job''s friends, and of three Israelites Elihu.', 'or (fully) אֱלִיהוּא; from 410 and 1931; God of him;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6769H}/[H6738]', 'inflected', 'heb', 'צִלְּתַי', '["Tsillᵉthay"]', '["and/ Zillethai"]', '["n-pr-m"]', 'Tsillethai, the name of two Israelites Zilthai.', 'from the feminine of 6738; shady;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5826}/H9033/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["to/ help/ him"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4264}/[H2583]', 'inflected', 'heb', 'מַחֲנֶה', '["machăneh"]', '["like/ [the] camp of"]', '["n-m"]', 'an encampment (of travellers or troops); hence, an army, whether literal (of soldiers) or figurative (of dancers, angels, cattle, locusts, stars; or even the sacred courts) army, band, battle, camp, company, drove, host, tents.', 'from 2583;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2502B}/[H2502]', 'inflected', 'heb', 'חָלַץ', '["châlats"]', '["the/ [man] equipped"]', '["v"]', 'to pull off; hence (intensively) to strip, (reflex.) to depart; by implication, to deliver, equip (for fight); present, strengthen arm (self), (go, ready) armed (× man, soldier), deliver, draw out, make fat, loose, (ready) prepared, put off, take away, withdraw self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6635A}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["for <the>/ war","to/ [the] host of"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4438}/[H4427]', 'lemma', 'heb', 'מַלְכוּת', '["malkûwth"]', '["[is] a kingdom of","[the] kingdom of","[the] reign of","a kingdom","kingdoms","royalty","royalty of"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6310I}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["according to/ [the] mouth of"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635A}\/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["war"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3077G}/[H3068]', 'inflected', 'heb', 'יְהוֹיָדָע', '["Yᵉhôwyâdâʻ"]', '["and/ Jehoiada"]', '["n-pr-m"]', 'Jehojada, the name of three Israelites Jehoiada. Compare 3111.', 'from 3068 and 3045; Jehovah-known;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5057}/[H5046]', 'inflected', 'heb', 'נָגִיד', '["nâgîyd"]', '["[was] the/ leader","the/ leader"]', '["n-m"]', 'a commander (as occupying the front), civil, military or religious; generally (abstractly, plural), honorable themes captain, chief, excellent thing, (chief) governor, leader, noble, prince, (chief) ruler.', 'or נָגִד; from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8147}\/[H8145]', 'inflected', 'heb', 'שְׁנַיִם', '["shᵉnayim"]', '["and/ two"]', '["n"]', 'two; also (as ordinal) twofold both, couple, double, second, twain, twelfth, twelve, twenty (sixscore) thousand, twice, two.', 'dual of 8145; feminine שְׁתַּיִם;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4768}/H9028/[H7235]', 'inflected', 'heb', 'מַרְבִּית', '["marbîyth"]', '["greater part/ their"]', '["n-f"]', 'a multitude; also offspring; specifically interest (on capital) greatest part, greatness, increase, multitude.', 'from 7235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0998}/[H995]', 'lemma', 'heb', 'בִּינָה', '["bîynâh"]', '["<of> understanding","[am] understanding","[is] understanding","[the] understanding of","understanding","understanding<s>"]', '["n-f"]', 'understanding knowledge, meaning, × perfectly, understanding, wisdom.', 'from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7218H>/H9028', 'opaque', 'heb', 'רֹאשׁ', '["rôʼsh"]', '["chiefs/ their"]', '["n-m"]', 'the head (as most easily shaken), whether literal or figurative (in many applications, of place, time, rank, itc.) band, beginning, captain, chapiter, chief(-est place, man, things), company, end, × every (man), excellent, first, forefront, (be-)head, height, (on) high(-est part, (priest)), × lead, × poor, principal, ruler, sum, top.', 'from an unused root apparently meaning to shake;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6310I}/H9028\/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["mouth/ their"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2074}/[H2082]', 'inflected', 'heb', 'זְבוּלוּן', '["Zᵉbûwlûwn"]', '["from/ Zebulun"]', '["n-pr-m n-pr-loc"]', 'Zebulon, a son of Jacob; also his territory and tribe Zebulun.', 'or זְבֻלוּן; or זְבוּלֻן; from 2082; habitation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5737A}/[H5737]', 'inflected', 'heb', 'עֲדַר', '["ʻădar"]', '["and/ to/ help"]', '["v"]', 'to arrange, as a battle, a vineyard (to hoe); hence, to muster and so to miss (or find wanting) dig, fail, keep (rank), lack.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3820A}\/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["and/ a heart"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5321G}/[H6617]', 'inflected', 'heb', 'נַפְתָּלִי', '["Naphtâlîy"]', '["and/ of/ Naphtali"]', '["n-pr-m n-pr-loc"]', 'Naphtali, a son of Jacob, with the tribe descended from him, and its territory Naphtali.', 'from 6617; my wrestling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5973A}/H9038/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["and/ [was] with/ them","and/ [were] with/ them","and/ with/ them"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6793C}/[H6791]', 'inflected', 'heb', 'צִנָּה', '["tsinnâh"]', '["with/ shield"]', '["n-f"]', 'a hook (as pointed); also a (large) shield (as if guarding by prickliness); also cold (as piercing) buckler, cold, hook, shield, target.', 'feminine of 6791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0836}/[H833]', 'inflected', 'heb', 'אָשֵׁר', '["ʼÂshêr"]', '["and/ of/ Asher"]', '["n-pr"]', 'Asher, a son of Jacob, and the tribe descended from him, with its territory; also a place in Palestine Asher', 'from 833, happy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5737A}/[H5737]', 'lemma', 'heb', 'עֲדַר', '["ʻădar"]', '["helpers of"]', '["v"]', 'to arrange, as a battle, a vineyard (to hoe); hence, to muster and so to miss (or find wanting) dig, fail, keep (rank), lack.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3824}/[H3823]', 'inflected', 'heb', 'לֵבָב', '["lêbâb"]', '["in/ [the] heart of","with/ a heart"]', '["n-m"]', 'the heart (as the most interior organ); bethink themselves, breast, comfortably, courage, ((faint), (tender-) heart(-ed), midst, mind, × unawares, understanding.', 'from 3823; used also like 3820');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1581}/[H1580]', 'inflected', 'heb', 'גָּמָל', '["gâmâl"]', '["and/ on <the>/ camels"]', '["n"]', 'a camel camel.', 'apparently from 1580 (in the sense of labor or burden-bearing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6505}/[H6504]', 'inflected', 'heb', 'פֶּרֶד', '["pered"]', '["and/ on <the>/ mules"]', '["n-m"]', 'a mule (perhaps from his lonely habits) mule.', 'from 6504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1241}/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["and/ on <the>/ ox[en]"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6778}/[H6784]', 'inflected', 'heb', 'צַמּוּק', '["tsammûwq"]', '["and/ bunches of raisins"]', '["n-m"]', 'a cake of dried grapes bunch (cluster) of raisins.', 'from 6784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5437I}/[H5437]', 'inflected', 'heb', 'סָבַב', '["çâbab"]', '["and/ let us bring round","and/ may you turn"]', '["v"]', 'to revolve, surround, or border; used in various applications, literally and figuratively bring, cast, fetch, lead, make, walk, × whirl, × round about, be about on every side, apply, avoid, beset (about), besiege, bring again, carry (about), change, cause to come about, × circuit, (fetch a) compass (about, round), drive, environ, × on every side, beset (close, come, compass, go, stand) round about, inclose, remove, return, set, sit down, turn (self) (about, aside, away, back).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7883H}/[H7835]', 'lemma', 'heb', 'שִׁיחוֹר', '["Shîychôwr"]', '["Shihor","[the] Shihor"]', '["n-pr-f"]', 'Shichor, a stream of Egypt Shihor, Sihor.', 'or שִׁחוֹר; or שִׁחֹר; probably from 7835; dark, i.e. turbid;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7157}/[H7151]', 'inflected', 'heb', 'קִרְיַת יְעָרִים', '["Qiryath Yᵉʻârîym"]', '["from/ Kiriath"]', '["n-pr-loc"]', 'Kirjath-Jearim or Kirjath-Arim, a place in Palestine Kirjath, Kirjath-jearim, Kirjath-arim.', 'or (Jeremiah 26:20) with the article interposed; or (Joshua 18:28) simply the former part of the word; or קִרְיַת עָרִים; from 7151 and the plural of 3293 or 5892; city of forests, or city of towns;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1173I}/H9011/[H1172]', 'inflected', 'heb', 'בַּעֲלָה', '["Baʻălâh"]', '["Baalah/ towards"]', '["n-pr-loc"]', 'Baalah, the name of three places in Palestine Baalah.', 'the same as 1172;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4700}/[H6750]', 'inflected', 'heb', 'מְצֵלֶת', '["mᵉtsêleth"]', '["and/ with/ [the] cymbals","and/ with/ cymbals"]', '["n-f"]', '(only dual) double tinklers, i.e. cymbals cymbals.', 'from 6750;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2689}/[H2690]', 'inflected', 'heb', 'חֲצֹצְרָה', '["chătsôtsᵉrâh"]', '["and/ with/ trumpets"]', '["n-f"]', 'a trumpet (from its sundered or quavering note) trumpet(-er).', 'by reduplication from 2690;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3592}/[H3591]', 'lemma', 'heb', 'כִּידוֹן', '["Kîydôwn"]', '["Kidon"]', '["n-pr"]', 'Kidon, a place in Palestine Chidon.', 'the same as 3591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0270}/[H270]', 'inflected', 'heb', 'אָחַז', '["ʼâchaz"]', '["to/ grasp","to/ take hold"]', '["v"]', 'to seize (often with the accessory idea of holding in possession) be affrighted, bar, (catch, lay, take) hold (back), come upon, fasten, handle, portion, (get, have or take) possess(-ion).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6560G}/[H6556]', 'lemma', 'heb', 'פֶּרֶץ עֻזָּא', '["Perets ʻUzzâʼ"]', '["Perez","Uzzah"]', '["n-pr-loc"]', 'Perets-Uzza, a place in Palestine Perezuzza.', 'from 6556 and 5798; break of Uzza;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1963}/[H349]', 'lemma', 'heb', 'הֵיךְ', '["hêyk"]', '["how?"]', '["adv"]', 'how? how.', 'another form for 349;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2361G}/[H2353]', 'lemma', 'heb', 'חוּרָם', '["Chûwrâm"]', '["Huram"]', '["n-pr-m"]', 'Churam, the name of an Israelite and two Syrians Huram. Compare 2438.', 'probably from 2353; whiteness, i.e. noble;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5416G}/[H5414]', 'lemma', 'heb', 'נָתָן', '["Nâthân"]', '["Nathan"]', '["n-pr-m"]', 'Nathan, the name of five Israelites Nathan.', 'from 5414; given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1182}/[H1168]', 'inflected', 'heb', 'בְּעֶלְיָדָע', '["Bᵉʻelyâdâʻ"]', '["and/ Beeliada"]', '["n-pr-m"]', 'Beeljada, an Israelite Beeliada.', 'from 1168 and 3045; Baal has known;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6807A}/[H6806]', 'inflected', 'heb', 'צְעָדָה', '["tsᵉʻâdâh"]', '["<the>/ marching"]', '["n-f"]', 'a march; (concretely) an (ornamental) ankle-chain going, ornament of the legs.', 'feminine of 6806;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1391}/[H1387]', 'inflected', 'heb', 'גִּבְעוֹן', '["Gibʻôwn"]', '["[was] from/ Gibeon","from/ Gibeon"]', '["n-pr-loc"]', 'Gibon, a place in Palestine Gibeon.', 'from the same as 1387; hilly;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1507}/H9011/[H1506]', 'inflected', 'heb', 'גֶּזֶר', '["Gezer"]', '["Gezer/ <towards>"]', '["n-pr-loc"]', 'Gezer, a place in Palestine Gazer, Gezer.', 'the same as 1506;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6343}/H9023/[H6342]', 'inflected', 'heb', 'פַּחַד', '["pachad"]', '["dread of/ him"]', '["n-m"]', 'a (sudden) alarm (properly, the object feared, by implication, the feeling) dread(-ful), fear, (thing) great (fear, -ly feared), terror.', 'from 6342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8334}/H9033/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["and/ to/ serve/ him"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0222H}/[H217]', 'lemma', 'heb', 'אוּרִיאֵל', '["ʼÛwrîyʼêl"]', '["Uriel"]', '["n-pr-m"]', 'Uriel, the name of two Israelites Uriel.', 'from 217 and 410; flame of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6242}\/[H6235]', 'inflected', 'heb', 'עֶשְׂרִים', '["ʻesrîym"]', '["and/ twenty"]', '["n"]', 'twenty; also (ordinal) twentieth (six-) score, twenty(-ieth).', 'from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6222K}/[H6213]', 'lemma', 'heb', 'עֲשָׂיָה', '["ʻĂsâyâh"]', '["Asaiah"]', '["n-pr-m"]', 'Asajah, the name of three or four Israelites Asaiah.', 'from 6213 and 3050; Jah has made;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3100N}/[H3068]', 'lemma', 'heb', 'יוֹאֵל', '["Yôwʼêl"]', '["Joel"]', '["n-pr-m"]', 'Joel, the name of twelve Israelites Joel.', 'from 3068 and 410; Jehovah (is his) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8098G}/[H8085]', 'lemma', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0447M}/[H410]', 'lemma', 'heb', 'אֱלִיאֵל', '["ʼĔlîyʼêl"]', '["Eliel"]', '["n-pr-m"]', 'Eliel, the name of nine Israelites Eliel.', 'from 410 repeated; God of (his) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8084}\/[H8083]', 'inflected', 'heb', 'שְׁמֹנִים', '["shᵉmônîym"]', '["eighty"]', '["a"]', 'eighty, also eightieth eighty(-ieth), fourscore.', 'or שְׁמוֹנִים; multiple from 8083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5992H}/[H5971]', 'lemma', 'heb', 'עַמִּינָדָב', '["ʻAmmîynâdâb"]', '["Amminadab"]', '["n-pr-m"]', 'Amminadab, the name of four Israelites Amminadab.', 'from 5971 and 5068; people of liberality;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0222H}/[H217]', 'inflected', 'heb', 'אוּרִיאֵל', '["ʼÛwrîyʼêl"]', '["<to>/ Uriel"]', '["n-pr-m"]', 'Uriel, the name of two Israelites Uriel.', 'from 217 and 410; flame of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3100N}/[H3068]', 'inflected', 'heb', 'יוֹאֵל', '["Yôwʼêl"]', '["and/ Joel"]', '["n-pr-m"]', 'Joel, the name of twelve Israelites Joel.', 'from 3068 and 410; Jehovah (is his) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0447M}/[H410]', 'inflected', 'heb', 'אֱלִיאֵל', '["ʼĔlîyʼêl"]', '["and/ Eliel"]', '["n-pr-m"]', 'Eliel, the name of nine Israelites Eliel.', 'from 410 repeated; God of (his) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5992H}/[H5971]', 'inflected', 'heb', 'עַמִּינָדָב', '["ʻAmmîynâdâb"]', '["and/ Amminadab"]', '["n-pr-m"]', 'Amminadab, the name of four Israelites Amminadab.', 'from 5971 and 5068; people of liberality;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251H}/H9026/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ relatives/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4100}/H9003/{H7223G}/[H4100]', 'inflected', 'heb', 'מָה', '["mâh"]', '["to/ what?/ at the/ first [time]"]', '["i"]', 'properly, interrogative what? (including how? why? when?); but also exclamation, what! (including how!), or indefinitely what (including whatever, and even relatively, that which); often used with prefixes in various adverbial or conjunctive senses how (long, oft, (-soever)), (no-) thing, what (end, good, purpose, thing), whereby(-fore, -in, -to, -with), (for) why.', 'or מַה; or מָ; or מַ; also מֶה; a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3802>/H9028', 'inflected', 'heb', 'בכתפם', '["bi/kh.te.Fa/m"]', '["on/ shoulders/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4133}/[H4132]', 'inflected', 'heb', 'מוֹטָה', '["môwṭâh"]', '["with <the>/ poles"]', '["n-f"]', 'a pole; by implication, an ox-bow; hence, a yoke (either literal or figurative) bands, heavy, staves, yoke.', 'feminine of 4132;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5975H}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["to/ appoint"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4700}/[H6750]', 'inflected', 'heb', 'מְצֵלֶת', '["mᵉtsêleth"]', '["and/ cymbals"]', '["n-f"]', '(only dual) double tinklers, i.e. cymbals cymbals.', 'from 6750;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7311A}/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["to/ lift up","to/ raise","to/ raise up","to/ rise"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8057}\/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["of/ joy"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1296H}\/[H1290]', 'inflected', 'heb', 'בֶּרֶכְיָה', '["Berekyâh"]', '["Berekiah"]', '["n-pr-m"]', 'Berekjah, the name of six Israelites Berachiah, Berechiah.', 'or בֶּרֶכְיָהוּ; from 1290 and 3050; knee (i.e. blessing) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6984}/[H6983]', 'lemma', 'heb', 'קוּשָׁיָהוּ', '["qûwshâyâhûw"]', '["Kushaiah"]', '["n-pr-m"]', 'Kushajah, an Israelite Kushaiah.', 'from the passive participle of 6983 and 3050; entrapped of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1122}/[H1121]', 'lemma', 'heb', 'בֵּן', '["Bên"]', '["Ben"]', '["n-pr-m"]', 'Ben, an Israelite Ben.', 'the same as 1121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3268}/[H3267]', 'inflected', 'heb', 'יַעֲזִיאֵל', '["Yaʻăzîyʼêl"]', '["and/ Jaaziel"]', '["n-pr-m"]', 'Jaaziel, an Israelite Jaaziel.', 'from 3267 and 410; emboldened of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8070G}/[H8034]', 'inflected', 'heb', 'שְׁמִירָמוֹת', '["Shᵉmîyrâmôwth"]', '["and/ Shemiramoth"]', '["n-pr-m"]', 'Shemiramoth, the name of two Israelites Shemiramoth.', 'or שְׁמָרִימוֹת; probably from 8034 and plural of 7413; name of heights;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3171G}/[H2421]', 'inflected', 'heb', 'יְחִיאֵל', '["Yᵉchîyʼêl"]', '["and/ Jehiel"]', '["n-pr-m"]', 'Jechiel (or Jechavel), the name of eight Israelites Jehiel.', 'or (2 Chronicles 29:14) יְחַוְאֵל; from 2421 and 410; God will live;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6042G}/[H6031]', 'inflected', 'heb', 'עֻנִּי', '["ʻUnnîy"]', '["and/ Unni"]', '["n-pr-m"]', 'Unni, the name of two Israelites Unni.', 'from 6031; afflicted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0446K}/[H410]', 'lemma', 'heb', 'אֱלִיאָב', '["ʼĔlîyʼâb"]', '["Eliab"]', '["n-pr-m"]', 'Eliab, the name of six Israelites Eliab.', 'from 410 and 1; God of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1141J}/[H1129]', 'inflected', 'heb', 'בְּנָיָה', '["Bᵉnâyâh"]', '["and/ Benaiah"]', '["n-pr-m"]', 'Benajah, the name of twelve Israelites Benaiah.', 'or בּנָיָהוּ; (prolonged) from 1129 and 3050; Jah has built;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4641G}/[H4639]', 'inflected', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["and/ Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4993H}/[H4991]', 'inflected', 'heb', 'מַתִּתְיָה', '["Mattithyâh"]', '["and/ Mattithiah"]', '["n-pr-m"]', 'Mattithjah, the name of four Israelites Mattithiah. n', 'or מַתִּתְיָהוּ; from 4991 and 3050; gift of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0466}/[H410]', 'inflected', 'heb', 'אֱלִיפְלֵהוּ', '["ʼĔlîyphᵉlêhûw"]', '["and/ Eliphelehu"]', '["n-pr-m"]', 'Eliphelehu, an Israelite Elipheleh.', 'from 410 and 6395; God of his distinction;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4737}/[H4735]', 'inflected', 'heb', 'מִקְנֵיָהוּ', '["Miqnêyâhûw"]', '["and/ Mikneiah"]', '["n-pr-m"]', 'Miknejah, an Israelite Mikneiah.', 'from 4735 and 3050; possession of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5654}/[H5647]', 'inflected', 'heb', 'עֹבֵד אֱדוֹם', '["ʻÔbêd ʼĔdôwm"]', '["and/ Obed-"]', '["n-pr-m"]', 'Obed-Edom, the name of five Israelites Obed-edom.', 'from the active participle of 5647 and 123; worker of Edom;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3273I}/[H3261]', 'inflected', 'heb', 'יְעִיאֵל', '["Yᵉʻîyʼêl"]', '["and/ Jeiel"]', '["n-pr-m"]', 'Jeiel, the name of six Israelites Jeiel, Jehiel. Compare 3262.', 'from 3261 and 410; carried away of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7891}/[H7788]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["and/ the/ female singers","and/ the/ singers"]', '["v"]', 'to sing behold (by mistake for 7789), sing(-er, -ing man, -ing woman).', 'or (the original form) שׁוּר; (1 Samuel 18:6), a primitive root (rather identical with 7788 through the idea of strolling minstrelsy);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0387J}/[H386]', 'inflected', 'heb', 'אֵיתָן', '["ʼÊythân"]', '["and/ Ethan"]', '["n-pr-m"]', 'Ethan, the name of four Israelites Ethan.', 'the same as 386; permanent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4700}/[H6750]', 'inflected', 'heb', 'מְצֵלֶת', '["mᵉtsêleth"]', '["with <the>/ cymbals","with/ cymbals"]', '["n-f"]', '(only dual) double tinklers, i.e. cymbals cymbals.', 'from 6750;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8085I}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["[were] to/ sound aloud","for/ [those who] sound aloud","to/ make heard"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2148A}/[H2142]', 'inflected', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["and/ Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5815}/[H5756]', 'inflected', 'heb', 'עֲזִיאֵל', '["ʻĂzîyʼêl"]', '["and/ Aziel"]', '["n-pr-m"]', 'Aziel, an Israelite Aziel. Compare 3268.', 'from 5756 and 410; strengthened of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0446K}/[H410]', 'inflected', 'heb', 'אֱלִיאָב', '["ʼĔlîyʼâb"]', '["and/ Eliab"]', '["n-pr-m"]', 'Eliab, the name of six Israelites Eliab.', 'from 410 and 1; God of (his) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5035B}/[H5034]', 'inflected', 'heb', 'נֶבֶל', '["nebel"]', '["with/ a lyre of","with/ lyre","with/ lyre of","with/ lyres"]', '["n-m"]', 'a skin-bag for liquids (from collapsing when empty); hence, a vase (as similar in shape when full); also a lyre (as having a body of like form) bottle, pitcher, psaltery, vessel, viol.', 'or נֵבֶל; from 5034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5961}/[H5959]', 'lemma', 'heb', 'עֲלָמוֹת', '["ʻĂlâmôwth"]', '["alamoth","alumoth"]', '["n-f"]', 'properly, girls, i.e. the soprano or female voice, perhaps falsetto Alamoth.', 'plural of 5959;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5812G}/[H5810]', 'inflected', 'heb', 'עֲזַזְיָהוּ', '["ʻĂzazyâhûw"]', '["and/ Azaziah"]', '["n-pr-m"]', 'Azazjah, the name of three Israelites Azaziah.', 'from 5810 and 3050; Jah has strengthened;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8067}/[H8066]', 'inflected', 'heb', 'שְׁמִינִית', '["shᵉmîynîyth"]', '["the/ sheminith"]', '["n-f"]', 'probably an eight-stringed lyre Sheminith.', 'feminine of 8066;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5329}/[H5331]', 'inflected', 'heb', 'נָצַח', '["nâtsach"]', '["[are] to/ act as overseers","to the/ choirmaster","to/ act as overseers"]', '["v"]', 'properly, to glitter from afar, i.e. to be eminent (as a superintendent, especially of the Temple services and its music); to be permanent excel, chief musician (singer), oversee(-r), set forward.', 'a primitive root; also as denominative from 5331');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3663}/[H3661]', 'inflected', 'heb', 'כְּנַנְיָה', '["Kᵉnanyâh"]', '["and/ Kenaniah"]', '["n-pr-m"]', 'Kenanjah, an Israelite Chenaniah.', 'or כְּנַנְיָהוּ; from 3661 and 3050; Jah has planted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1296H}/[H1290]', 'inflected', 'heb', 'בֶּרֶכְיָה', '["Berekyâh"]', '["and/ Berekiah"]', '["n-pr-m"]', 'Berekjah, the name of six Israelites Berachiah, Berechiah.', 'or בֶּרֶכְיָהוּ; from 1290 and 3050; knee (i.e. blessing) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0511M}/[H410]', 'inflected', 'heb', 'אֶלְקָנָה', '["ʼElqânâh"]', '["and/ Elkanah"]', '["n-pr-m"]', 'Elkanah, the name of several Israelites Elkanah.', 'from 410 and 7069; God has obtained;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7645G}/[H7644]', 'inflected', 'heb', 'שְׁבַנְיָה', '["Shᵉbanyâh"]', '["and/ Shebaniah"]', '["n-pr-m"]', 'Shebanjah, the name of three or four Israelites Shebaniah.', 'or שְׁבַנְיָהוּ; from the same as 7644 and 3050; Jah has grown (i.e. prospered);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3146H}/[H3092]', 'inflected', 'heb', 'יוֹשָׁפָט', '["Yôwshâphâṭ"]', '["and/ Joshaphat"]', '["n-pr-m"]', 'Joshaphat, an Israelite Joshaphat.', 'a form of 3092;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5417I}/[H5414]', 'inflected', 'heb', 'נְתַנְאֵל', '["Nᵉthanʼêl"]', '["and/ Nethanel"]', '["n-pr-m"]', 'Nethanel, the name of ten Israelites Nethaneel.', 'from 5414 and 410; given of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6022I}/[H6006]', 'inflected', 'heb', 'עֲמָשַׂי', '["ʻĂmâsay"]', '["and/ Amasai"]', '["n-pr-m"]', 'Amasai, the name of three Israelites Amasai.', 'from 6006; burdensome;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0461J}/[H410]', 'inflected', 'heb', 'אֱלִיעֶזֶר', '["ʼĔlîyʻezer"]', '["and/ Eliezer"]', '["n-pr-m"]', 'Eliezer, the name of a Damascene and of ten Israelites Eliezer.', 'from 410 and 5828; God of help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2690}/[H2689]', 'lemma', 'heb', 'חָצַר', '["châtsar"]', '["[were] blowing a trumpet","[who were] blowing a trumpet"]', '["v"]', 'to trumpet, i.e. blow on that instrument blow, sound, trumpeter.', 'a primitive root; properly, to surround with a stockade, and thus separate from the open country; but used only in the reduplicated form חֲצֹצֵר; or (2 Chronicles 5:12) חֲצֹרֵר; as dem. from 2689;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3174}/[H2421]', 'inflected', 'heb', 'יְחִיָּה', '["Yᵉchîyâh"]', '["and/ Jehiah"]', '["n-pr-m"]', 'Jechijah, an Israelite Jehiah.', 'from 2421 and 3050; Jah will live;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8057}\/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["with/ joy"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5826}/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["because/ helped"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3736}/[H3525]', 'lemma', 'heb', 'כַּרְבֵּל', '["karbêl"]', '["[was] wrapped"]', '["v"]', 'to gird or clothe clothed.', 'from the same as 3525;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4598}/[H4603]', 'inflected', 'heb', 'מְעִיל', '["mᵉʻîyl"]', '["in/ a robe of"]', '["n-m"]', 'a robe (i.e. upper and outer garment) cloke, coat, mantle, robe.', 'from 4603 in the sense of covering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0948>', 'opaque', 'heb', 'בּוּץ', '["bûwts"]', '["fine linen"]', '["n-m"]', 'probably cotton (of some sort) fine (white) linen.', 'from an unused root (of the same form) meaning to bleach, i.e. (intransitive) be white;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4853A}/[H5375]', 'inflected', 'heb', 'מַשָּׂא', '["massâʼ"]', '["the/ burden","the/ lifting up","the/ oracle"]', '["n-m n-pr-m"]', 'a burden; specifically, tribute, or (abstractly) porterage; figuratively, an utterance, chiefly a doom, especially singing; mental, desire burden, carry away, prophecy, × they set, song, tribute.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7540}/[H7540]', 'lemma', 'heb', 'רָקַד', '["râqad"]', '["dancing","they skipped about","they will leap about","to dance","you will skip about"]', '["v"]', 'properly, to stamp, i.e. to spring about (wildly or for joy) dance, jump, leap, skip.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3820A}/H9024\/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["in/ heart/ her"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2142}/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["and/ to/ [those who] remember","and/ to/ make remembrance"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3034}/[H3027]', 'inflected', 'heb', 'יָדָה', '["yâdâh"]', '["and/ to/ give thanks"]', '["v"]', 'physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving).', 'a primitive root; used only as denominative from 3027; literally, to use (i.e. hold out) the hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1984B}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["and/ to/ praise"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3273I}/[H3261]', 'lemma', 'heb', 'יְעִיאֵל', '["Yᵉʻîyʼêl"]', '["Jeiel"]', '["n-pr-m"]', 'Jeiel, the name of six Israelites Jeiel, Jehiel. Compare 3262.', 'from 3261 and 410; carried away of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0623H}/[H622]', 'inflected', 'heb', 'אָסָף', '["ʼÂçâph"]', '["and/ Asaph"]', '["n-pr-m"]', 'Asaph, the name of three Israelites, and of the family of the first Asaph.', 'from 622; collector;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3166H}/[H2372]', 'inflected', 'heb', 'יַחֲזִיאֵל', '["Yachăzîyʼêl"]', '["and/ Jahaziel"]', '["n-pr-m"]', 'Jachaziel, the name of five Israelites Jahaziel, Jahziel.', 'from 2372 and 410; beheld of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7218J>', 'inflected', 'heb', 'בראש', '["ba./Rosh","be./Rosh"]', '["[was] at/ [the] head of","at the/ first","at/ [the] beginning of","at/ [the] head of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3034}/[H3027]', 'inflected', 'heb', 'יָדָה', '["yâdâh"]', '["to/ give thanks","to/ give thanks to","to/ throw down"]', '["v"]', 'physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving).', 'a primitive root; used only as denominative from 3027; literally, to use (i.e. hold out) the hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0251H}/H9023\/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ relatives/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5949}/H9023/[H5953]', 'inflected', 'heb', 'עֲלִילָה', '["ʻălîylâh"]', '["deeds/ his"]', '["n-f"]', 'an exploit (of God), or a performance (of man, often in a bad sense); by implication, an opportunity act(-ion), deed, doing, invention, occasion, work.', 'or עֲלִלָה; from 5953 in the sense of effecting;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5797}/H9023/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["and/ strength/ his"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4159}/H9023/[H3302]', 'inflected', 'heb', 'מוֹפֵת', '["môwphêth"]', '["signs/ his","wonders/ his"]', '["n-m"]', 'a miracle; by implication, a token or omen miracle, sign, wonder(-ed at).', 'or מֹפֵת; from 3302 in the sense of conspicuousness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0972}/H9023/[H977]', 'inflected', 'heb', 'בָּחִיר', '["bâchîyr"]', '["chosen one/ his","chosen ones/ his"]', '["n-m"]', 'select choose, chosen one, elect.', 'from 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7621}/H9023/[H7650]', 'inflected', 'heb', 'שְׁבוּעָה', '["shᵉbûwʻâh"]', '["and/ oath/ his"]', '["n-f"]', 'properly, something sworn, i.e. an oath curse, oath, × sworn.', 'feminine passive participle of 7650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5975H}/H9034/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ he confirmed/ it"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5159}/H9026/[H5157]', 'inflected', 'heb', 'נַחֲלָה', '["nachălâh"]', '["inheritance/ your"]', '["n-f"]', 'properly, something inherited, i.e. (abstractly) occupancy, or (concretely) an heirloom; generally an estate, patrimony or portion heritage, to inherit, inheritance, possession. Compare 5158.', 'from 5157 (in its usual sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1961}/H9046/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["when/ are/ you","when/ were/ you"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1471A}/[H1465]', 'inflected', 'heb', 'גּוֹי', '["gôwy"]', '["from/ a nation","from/ nation","from/ nations"]', '["n-m n-pr-m"]', 'a foreign nation; hence, a Gentile; also (figuratively) a troop of animals, or a flight of locusts Gentile, heathen, nation, people.', 'rarely (shortened) גֹּי; apparently from the same root as 1465 (in the sense of massing);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4467}/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["and/ from/ a kingdom"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6231}/H9038/[H6229]', 'inflected', 'heb', 'עָשַׁק', '["ʻâshaq"]', '["to/ oppress/ them"]', '["v"]', 'to press upon, i.e. oppress, defraud, violate, overflow get deceitfully, deceive, defraud, drink up, (use) oppress(-ion), -or), do violence (wrong).', 'a primitive root (compare 6229);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4899}/H9020/[H4886]', 'inflected', 'heb', 'מָשִׁיחַ', '["mâshîyach"]', '["<in>/ anointed [ones]/ my"]', '["n-m"]', 'anointed; usually a consecrated person (as a king, priest, or saint); specifically, the Messiah anointed, Messiah.', 'from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5030}/H9020/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["and/ to/ prophets/ my"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7489A}\/[H7489]', 'inflected', 'heb', 'רָעַע', '["râʻaʻ"]', '["evil-doers","you do harm"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1984B}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["and/ I will praise","and/ [are] praising","and/ [is] to be praised","and/ [those who] praised","and/ [were] praising","and/ they praised","and/ to praise"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1935>', 'opaque', 'heb', 'הוֹד', '["hôwd"]', '["[is] splendor","[the] honor of","[the] majesty of","majesty","majesty of","splendor"]', '["n-m"]', 'grandeur (i.e. an imposing form and appearance) beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from an unused root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1926}/[H1921]', 'inflected', 'heb', 'הָדָר', '["hâdâr"]', '["and/ [the] splendor of","and/ honor","and/ majesty"]', '["n-m"]', 'magnificence, i.e. ornament or splendor beauty, comeliness, excellency, glorious, glory, goodly, honour, majesty.', 'from 1921;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2304}/[H2302]', 'inflected', 'heb', 'חֶדְוָה', '["chedvâh"]', '["and/ joy"]', '["n-f"]', 'rejoicing gladness, joy.', 'from 2302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5797}/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["and/ [the] strength of","and/ strength"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1927}/[H1926]', 'inflected', 'heb', 'הֲדָרָה', '["hădârâh"]', '["in/ adornment of"]', '["n-f"]', 'decoration beauty, honour.', 'feminine of 1926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2342A}/[H2342]', 'lemma', 'heb', 'חוּל', '["chûwl"]', '["do you tremble","he causes to tremble","it causes to tremble","it trembles","they are made to tremble","they twisted","tremble"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1077}/[H1086]', 'lemma', 'heb', 'בַּל', '["bal"]', '["<of> [which] not","[which] not","not"]', '["adv"]', 'properly, a failure; by implication nothing; usually (adverb) not at all; also lest lest, neither, no, none (that...), not (any), nothing.', 'from 1086;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1523}/[H1523]', 'inflected', 'heb', 'גִּיל', '["gîyl"]', '["and/ be glad","and/ he may be glad","and/ let it be glad","and/ may she rejoice","and/ rejoice"]', '["v"]', 'properly, to spin round (under the influence of any violent emotion), i.e. usually rejoice, or (as cringing) fear be glad, joy, be joyful, rejoice.', 'or (by permutation) גּוּל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4393}/H9023/[H4390]', 'inflected', 'heb', 'מְלֹא', '["mᵉlôʼ"]', '["and/ what fills/ it"]', '["n-m"]', 'fulness (literally or figuratively) × all along, × all that is (there-) in, fill, (× that whereof...was) full, fulness, (hand-) full, multitude.', 'rarely מְלוֹא; or מְלוֹ; (Ezekiel 41:8), from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3468}/H9025/[H3467]', 'inflected', 'heb', 'יֶשַׁע', '["yeshaʻ"]', '["salvation/ our"]', '["n-m"]', 'liberty, deliverance, prosperity safety, salvation, saving.', 'or יֵשַׁע; from 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6908}/H9035/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["and/ gather/ us"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5337}/H9035/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ deliver/ us"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7623B}/[H7623]', 'inflected', 'heb', 'שָׁבַח', '["shâbach"]', '["to/ boast"]', '["v"]', 'properly, to address in a loud tone, i.e. (specifically) loud; figuratively, to pacify (as if by words) commend, glory, keep in, praise, still, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8416}/H9021/[H1984]', 'inflected', 'heb', 'תְּהִלָּה', '["tᵉhillâh"]', '["in/ praise/ your"]', '["n-f"]', 'laudation; specifically (concretely) a hymn praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5769G}/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["<the>/ antiquity","<the>/ perpetuity"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0623H}/[H622]', 'inflected', 'heb', 'אָסָף', '["ʼÂçâph"]', '["<to>/ Asaph","for/ Asaph","of/ Asaph"]', '["n-pr-m"]', 'Asaph, the name of three Israelites, and of the family of the first Asaph.', 'from 622; collector;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0251H}/H9023/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ <to>/ relatives/ his"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1697M}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["for the/ matter","to/ [the] matter of","to/ anything"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3038G}/[H3034]', 'lemma', 'heb', 'יְדוּתוּן', '["Yᵉdûwthûwn"]', '["Jedithun","Jeduthun"]', '["n-pr-m"]', 'Jeduthun, an Israelite Jeduthun.', 'or יְדֻתוּן; or יְדִיתוּן; probably from 3034; laudatory;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2621H}/[H2620]', 'inflected', 'heb', 'חֹסָה', '["Chôçâh"]', '["and/ Hosah"]', '["n-pr-m n-pr-loc"]', 'Chosah, an Israelite; also a place in Palestine Hosah.', 'from 2620; hopeful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3038G}/[H3034]', 'inflected', 'heb', 'יְדוּתוּן', '["Yᵉdûwthûwn"]', '["and/ Jeduthun"]', '["n-pr-m"]', 'Jeduthun, an Israelite Jeduthun.', 'or יְדֻתוּן; or יְדִיתוּן; probably from 3034; laudatory;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7605}/[H7604]', 'inflected', 'heb', 'שְׁאָר', '["shᵉʼâr"]', '["and/ [the] remainder of","and/ [the] remnant of","and/ [the] rest of","and/ a remnant","and/ a remnant of","and/ remnant"]', '["n-m"]', 'a remainder × other, remnant, residue, rest.', 'from 7604;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H4908}/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["and/ from/ tabernacle"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1086}/H9033/[H1086]', 'inflected', 'heb', 'בָּלָה', '["bâlâh"]', '["to/ consume/ it"]', '["v"]', 'to fail; by implication to wear out, decay (causatively, consume, spend) consume, enjoy long, become (make, wax) old, spend, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/H9006/<H3117G>', 'inflected', 'heb', 'ולמימים', '["u./le./mi./ya.Mim"]', '["and/ <to>/ from/ days"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1121A}/H9021/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["one of/ descendants/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5975H}/H9033/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ I will appoint/ him"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004Q}/H9020/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["in/ house/ my"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4438}/H9020/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["and/ in/ kingdom/ my"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2377}/[H2372]', 'inflected', 'heb', 'חָזוֹן', '["châzôwn"]', '["[will be] the/ vision","the/ vision"]', '["n-m"]', 'a sight (mentally), i.e. a dream, revelation, or oracle vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8448}/[H8447]', 'inflected', 'heb', 'תּוֹר', '["tôwr"]', '["according to/ [the] order of"]', '["n-f"]', 'a manner (as a sort of turn) estate.', 'probably the same as 8447;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1420}/[H1419]', 'lemma', 'heb', 'גְּדוּלָה', '["gᵉdûwlâh"]', '["[the] greatness of","great things"]', '["n-f"]', 'greatness; (concretely) mighty acts dignity, great things(-ness), majesty.', 'or גְּדֻלָּה; (shortened) or (less accurately) גְּדוּלָּה; feminine of 1419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1644G}/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["by/ driving out"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6678H>', 'opaque', 'heb', 'צוֹבָא', '["Tsôwbâʼ"]', '["Zobah"]', '["n-pr-loc"]', 'Zoba or Zobah, a region of Syria Zoba, Zobah.', 'or צוֹבָה; or צֹבָה; from an unused root meaning to station; a station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2574H}/H9011/[H2346]', 'inflected', 'heb', 'חֲמָת', '["Chămâth"]', '["Hamath/ towards"]', '["n-pr-loc n-pr-m"]', 'Chamath, a place in Syria Hamath, Hemath.', 'from the same as 2346; walled;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5324}/[H5324]', 'inflected', 'heb', 'נָצַב', '["nâtsab"]', '["to/ establish"]', '["v"]', 'to station, in various applications (literally or figuratively) appointed, deputy, erect, establish, × Huzzah (by mistake for a proper name), lay, officer, pillar, present, rear up, set (over, up), settle, sharpen, establish, (make to) stand(-ing, still, up, upright), best state.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5104H}/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["at/ [the] river of","in the/ river","on the/ rivers"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1928}/[H1924]', 'inflected', 'heb', 'הֲדַרְעֶזֶר', '["Hădarʻezer"]', '["<to>/ Hadadezer"]', '["n-pr-m"]', 'Hadarezer, a Syrian king Hadarezer.', 'from 1924 and 5828; Hadar (i.e. Hadad, 1908) is his help; (i.e. Hadadezer, 1909)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2880}/[H2878]', 'inflected', 'heb', 'טִבְחַת', '["Ṭibchath"]', '["and/ from/ Tibhath"]', '["n-pr-loc"]', 'Tibchath, a place in Syria Tibhath.', 'from 2878; slaughter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3560}/[H3559]', 'inflected', 'heb', 'כּוּן', '["Kûwn"]', '["and/ from/ Kun"]', '["n-pr-loc"]', 'Kun, a place in Syria Chun.', 'probably from 3559; established;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5178A}\/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["<the>/ bronze","the/ bronze"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1913G}/[H1913]', 'lemma', 'heb', 'הֲדוֹרָם', '["Hădôwrâm"]', '["Hadoram"]', '["n-pr-m"]', 'Hadoram, a son of Joktan, and the tribe descended from him Hadoram.', 'or הֲדֹרָם; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1928}/[H1924]', 'inflected', 'heb', 'הֲדַרְעֶזֶר', '["Hădarʻezer"]', '["against/ Hadadezer"]', '["n-pr-m"]', 'Hadarezer, a Syrian king Hadarezer.', 'from 1924 and 5828; Hadar (i.e. Hadad, 1908) is his help; (i.e. Hadadezer, 1909)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0123G}/[H122]', 'inflected', 'heb', 'אֱדֹם', '["ʼĔdôm"]', '["from/ Edom"]', '["n-pr-m"]', 'Edom, the elder twin-brother of Jacob; hence the region (Idumaea) occupied by him Edom, Edomites, Idumea.', 'or (fully) אֱדוֹם ; from 122; red (see Genesis 25:25);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4417H}/[H4414]', 'inflected', 'heb', 'מֶלַח', '["melach"]', '["<the>/ Salt"]', '["n-m"]', 'properly, powder, i.e. (specifically) salt (as easily pulverized and dissolved) salt(-pit).', 'from 4414;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0040J}/[H1]', 'inflected', 'heb', 'אֲבִימֶלֶךְ', '["ʼĂbîymelek"]', '["and/ Abimelech"]', '["n-pr-m"]', 'Abimelek, the name of two Philistine kings and of two Israelites Abimelech.', 'from 1 and 4428; father of (the) king;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7798}/[H7797]', 'inflected', 'heb', 'שַׁוְשָׁא', '["Shavshâʼ"]', '["and/ Shavsha"]', '["n-pr-m"]', 'Shavsha, an Israelite Shavsha.', 'from 7797; joyful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7223I}/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["<the>/ chief","[were] the/ first","the/ former [sons]"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3027H}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["to/ [the] side of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2586G}/[H2603]', 'inflected', 'heb', 'חָנוּן', '["Chânûwn"]', '["to/ Hanun"]', '["n-pr-m"]', 'Chanun, the name of an Ammonite and of two Israelites Hanun.', 'from 2603; favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2713}/[H2713]', 'inflected', 'heb', 'חָקַר', '["châqar"]', '["to/ examine","to/ explore"]', '["v"]', 'properly, to penetrate; hence, to examine intimately find out, (make) search (out), seek (out), sound, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2015}/[H2015]', 'inflected', 'heb', 'הָפַךְ', '["hâphak"]', '["and/ to/ overthrow"]', '["v"]', 'to turn about or over; by implication, to change, overturn, return, pervert × become, change, come, be converted, give, make (a bed), overthrow (-turn), perverse, retire, tumble, turn (again, aside, back, to the contrary, every way).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7270}/[H7272]', 'inflected', 'heb', 'רָגַל', '["râgal"]', '["and/ to/ spy out"]', '["v"]', 'to walk along; but only in specifically, applications, to reconnoiter, to be a tale-bearer (i.e. slander); to lead about backbite, search, slander, (e-) spy (out), teach to go, view.', 'a primitive root; also as denominative from 7272');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/H9031\/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["to/ you"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1548}/H9038/[H1548]', 'inflected', 'heb', 'גָּלַח', '["gâlach"]', '["and/ he shaved/ them"]', '["v"]', 'properly, to be bald, i.e. (causatively) to shave; figuratively to lay waste poll, shave (off).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4667}/[H6585]', 'inflected', 'heb', 'מִפְשָׂעָה', '["miphsâʻâh"]', '["the/ buttock[s]"]', '["n-f"]', 'a stride, i.e. (by euphemism) the crotch buttocks.', 'from 6585;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7936B}/[H3739]', 'inflected', 'heb', 'שָׂכַר', '["sâkar"]', '["to/ hire"]', '["v"]', 'to hire earn wages, hire (out self), reward, × surely.', 'or (by permutation) סָכַר; (Ezra 4:5), a primitive root (apparently akin (by prosthesis) to 3739 through the idea of temporary purchase; compare 7937);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0758K}/[H759]', 'lemma', 'heb', 'אֲרָם', '["ʼĂrâm"]', '["Aram"]', '["n-pr-m n-m"]', 'Aram or Syria, and its inhabitants; also the name of the son of Shem, a grandson of Nahor, and of an Israelite Aram, Mesopotamia, Syria, Syrians.', 'from the same as 759; the highland;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4601H}/[H4600]', 'lemma', 'heb', 'מַעֲכָה', '["Maʻăkâh"]', '["Maacah"]', '["n-pr"]', 'Maakah (or Maakath), the name of a place in Syria, also of a Mesopotamian, of three Israelites, and of four Israelitesses and one Syrian woman Maachah, Maachathites. See also 1038.', 'or מַעֲכָת; (Joshua 13:13), from 4600; depression;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H6678G>', 'inflected', 'heb', 'ומצובה', '["u./mi./tzo.Vah"]', '["and/ from/ Zobah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5892B}/H9028/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["from/ cities/ their"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4421}\/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["for <the>/ battle"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0268}/[H299]', 'inflected', 'heb', 'אָחוֹר', '["ʼâchôwr"]', '["and/ back","and/ backwards","and/ behind"]', '["n-m"]', 'the hinder part; hence (adverb) behind, backward; also (as facing north) the West after(-ward), back (part, -side, -ward), hereafter, (be-) hind(-er part), time to come, without.', 'or (shortened) אָחֹר ; from 299;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8668G}\/[H7768]', 'inflected', 'heb', 'תְּשׁוּעָה', '["tᵉshûwʻâh"]', '["<into>/ deliverance"]', '["n-f"]', 'rescue (literal or figurative, persons, national or spiritual) deliverance, help, safety, salvation, victory.', 'or תְּשֻׁעָה; from 7768 in the sense of 3467;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3467}/H9031/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ I will deliver/ you"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7780}/[H8210]', 'inflected', 'heb', 'שׁוֹפָךְ', '["Shôwphâk"]', '["and/ Shophach"]', '["n-pr-m"]', 'Shophak, a Syrian Shophach.', 'from 8210; poured;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7780}/[H8210]', 'lemma', 'heb', 'שׁוֹפָךְ', '["Shôwphâk"]', '["Shophach"]', '["n-pr-m"]', 'Shophak, a Syrian Shophach.', 'from 8210; poured;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8666}/[H7725]', 'lemma', 'heb', 'תְּשׁוּבָה', '["tᵉshûwbâh"]', '["[the] return of","answers"]', '["n-f"]', 'a recurrence (of time or place); a reply (as returned) answer, be expired, return.', 'or תְּשֻׁבָה; from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2040}/H9034/[H2040]', 'inflected', 'heb', 'הָרַס', '["hâraç"]', '["and/ he overthrew/ it"]', '["v"]', 'to pull down or in pieces, break, destroy beat down, break (down, through), destroy, overthrow, pluck down, pull down, ruin, throw down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7787}/[H7786]', 'inflected', 'heb', 'שׂוּר', '["sûwr"]', '["and/ he sawed"]', '["v"]', 'to saw cut.', 'a primitive root (identical with 7786 through the idea of reducing to pieces; compare 4883);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4050}/[H1641]', 'inflected', 'heb', 'מְגֵרָה', '["mᵉgêrâh"]', '["and/ with <the>/ saws"]', '["n-f"]', 'a saw axe, saw.', 'from 1641;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0310A}/{H3651C}/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["after/ this"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5975I}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ he appointed","and/ he will arise","and/ he will raise up","and/ it arose","and/ they arose","and/ they rose up"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5598}/[H5592]', 'lemma', 'heb', 'סִפַּי', '["Çippay"]', '["Sippai"]', '["n-pr-m"]', 'Sippai, a Philistine Sippai. Compare 5593.', 'from 5592; bason-like;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3211}/[H3205]', 'inflected', 'heb', 'יָלִיד', '["yâlîyd"]', '["one of/ those born of"]', '["a"]', 'born (home-) born, child, son.', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7497H}/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["the/ Rephaites"]', '["n-pr-m"]', 'a giant giant, Rapha, Rephaim(-s). See also 1051.', 'or רָפָה; from 7495 in the sense of invigorating;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3265}/[H3293]', 'lemma', 'heb', 'יָעוּר', '["Yâʻûwr"]', '["Jair"]', '["n-pr-m"]', 'Jaur, an Israelite Jair(from the margin).', 'apparently the passive participle of the same as 3293; wooded;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3902}/[H3899]', 'lemma', 'heb', 'לַחְמִי', '["Lachmîy"]', '["Lahmi"]', '["n-pr-m"]', 'Lachmi, an Israelite; or rather probably a brief form Lahmi. See also 3433.', 'from 3899; foodful; (or perhaps erroneous transcription) for 1022');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4060G}/[H4055]', 'lemma', 'heb', 'מִדָּה', '["middâh"]', '["stature"]', '["n-f"]', 'properly, extension, i.e. height or breadth; also a measure (including its standard); hence a portion (as measured) or a vestment; specifically, tribute (as measured) garment, measure(-ing, meteyard, piece, size, (great) stature, tribute, wide.', 'feminine of 4055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0676}/H9023/[H6648]', 'inflected', 'heb', 'אֶצְבַּע', '["ʼetsbaʻ"]', '["and/ digits/ his"]', '["n-f"]', 'something to sieze with, i.e. a finger; by analogy, a toe finger, toe.', 'from the same as 6648 (in the sense of grasping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8092I}/[H8093]', 'lemma', 'heb', 'שִׁמְעָא', '["Shimʻâʼ"]', '["Shimea"]', '["n-pr-m"]', 'Shima, the name of four Israelites Shimea, Shimei, Shamma.', 'for 8093;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0411}/[H411]', 'lemma', 'heb', 'אֵל', '["ʼêl"]', '["these"]', '["d"]', 'these or those these, those. Compare 428.', 'a demonstrative particle (but only in a plural sense)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5381}/[H5381]', 'inflected', 'heb', 'נָשַׂג', '["nâsag"]', '["to/ overtaking [you]"]', '["v"]', 'to reach (literally or figuratively) ability, be able, attain (unto), (be able to, can) get, lay at, put, reach, remove, wax rich, × surely, (over-) take (hold of, on, upon).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1698}/[H1696]', 'inflected', 'heb', 'דֶּבֶר', '["deber"]', '["and/ pestilence"]', '["n-m"]', 'a pestilence murrain, pestilence, plague.', 'from 1696 (in the sense of destroying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7843}/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["and/ just as/ was destroying [it]"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0771}/[H766]', 'lemma', 'heb', 'אׇרְנָן', '["ʼOrnân"]', '["Ornan"]', '["n-pr-m"]', 'Ornan, a Jebusite Ornan. See 728.', 'probably from 766; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7489A}/[H7489]', 'inflected', 'heb', 'רָעַע', '["râʻaʻ"]', '["and/ doing evil","and/ exceedingly <do evil>","and/ you may do harm"]', '["v"]', 'properly, to spoil (literally, by breaking to pieces); figuratively, to make (or be) good for nothing, i.e. bad (physically, socially or morally) afflict, associate selves (by mistake for 7462), break (down, in pieces), displease, (be, bring, do) evil (doer, entreat, man), show self friendly (by mistake for 7462), do harm, (do) hurt, (behave self, deal) ill, × indeed, do mischief, punish, still, vex, (do) wicked (doer, -ly), be (deal, do) worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4046}\/[H5062]', 'inflected', 'heb', 'מַגֵּפָה', '["maggêphâh"]', '["to/ a plague"]', '["n-f"]', 'a pestilence; by analogy, defeat (× be) plague(-d), slaughter, stroke.', 'from 5062;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0771}/[H766]', 'inflected', 'heb', 'אׇרְנָן', '["ʼOrnân"]', '["and/ Ornan"]', '["n-pr-m"]', 'Ornan, a Jebusite Ornan. See 728.', 'probably from 766; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1758}/[H1758]', 'lemma', 'heb', 'דּוּשׁ', '["dûwsh"]', '["certainly <to thresh>","he threshed","it is threshed","threshing","you trample down","you will thresh"]', '["v"]', 'to trample or thresh break, tear, thresh, tread out (down), at grass (Jeremiah 50:11, by mistake for 1877).', 'or דּוֹשׁ; or דִּישׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0771}/[H766]', 'inflected', 'heb', 'אׇרְנָן', '["ʼOrnân"]', '["to/ Ornan"]', '["n-pr-m"]', 'Ornan, a Jebusite Ornan. See 728.', 'probably from 766; strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5084>/H9024', 'opaque', 'heb', 'נָדָן', '["nâdân"]', '["sheath/ its"]', '["n-m"]', 'a sheath (of a sword) sheath.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7200G}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["when/ saw"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4908}/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["and/ [the] tabernacle of"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1204}/[H1204]', 'lemma', 'heb', 'בָּעַת', '["bâʻath"]', '["I was terrified","he was terrified","will it terrify"]', '["v"]', 'to fear affright, be (make) afraid, terrify, trouble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3664}/[H3664]', 'inflected', 'heb', 'כָּנַס', '["kânaç"]', '["to/ gather"]', '["v"]', 'to collect; hence, to enfold gather (together), heap up, wrap self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2672}/[H2672]', 'inflected', 'heb', 'חָצַב', '["châtsab"]', '["to the/ masons","to/ cut","to/ dig"]', '["v"]', 'to cut or carve (wood, stone or other material); by implication, to hew, split, square, quarry, engrave cut, dig, divide, grave, hew (out, -er), made, mason.', 'or חָצֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4548}/[H5568]', 'inflected', 'heb', 'מַסְמֵר', '["maçmêr"]', '["for the/ nails","of/ nails"]', '["n-f"]', 'a peg (as bristling from the surface) nail.', 'or מִסְמֵר; also (feminine) מַסְמְרָה; or מִסְמְרָה; or even מַשְׂמְרָה; (Ecclesiastes 12:11), from 5568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4226}/[H2266]', 'inflected', 'heb', 'מְחַבְּרָה', '["mᵉchabbᵉrâh"]', '["and/ for the/ clamps"]', '["n-f"]', 'a joiner, i.e. brace or cramp coupling, joining.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0369}/[H369]', 'inflected', 'heb', 'אַיִן', '["ʼayin"]', '["<to>/ there not","and/ not","to/ [any whom] nothing","to/ not","to/ nothing","to/ there not"]', '["np"]', 'a nonentity; generally used as a negative particle else, except, fail, (father-) less, be gone, in(-curable), neither, never, no (where), none, nor, (any, thing), not, nothing, to nought, past, un(-searchable), well-nigh, without. Compare 370.', 'as if from a primitive root meaning to be nothing or not exist;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6722}/[H6721]', 'inflected', 'heb', 'צִידֹנִי', '["Tsîydônîy"]', '["the/ Sidonians"]', '["a"]', 'a Tsidonian or inhabitant of Tsidon Sidonian, of Sidon, Zidonian.', 'patrial from 6721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6876}/[H6865]', 'inflected', 'heb', 'צֹרִי', '["Tsôrîy"]', '["and/ the/ Tyrians"]', '["a"]', 'a Tsorite or inhabitant of Tsor (i.e. Syrian) (man) of Tyre.', 'patrial from 6865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1431}/[H1434]', 'inflected', 'heb', 'גָּדַל', '["gâdal"]', '["[is] to/ make great","to/ make great"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8253}/[H8252]', 'inflected', 'heb', 'שֶׁקֶט', '["sheqeṭ"]', '["and/ quietness"]', '["n-m"]', 'tranquillity quietness.', 'from 8252;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0998}/[H995]', 'inflected', 'heb', 'בִּינָה', '["bîynâh"]', '["and/ [the] understanding of","and/ understanding"]', '["n-f"]', 'understanding knowledge, meaning, × perfectly, understanding, wisdom.', 'from 995;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6680}/H9031/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["and/ he will appoint/ you"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5178A}/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["and/ [belongs] to the/ bronze","and/ of <the>/ bronze"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1270}/[H1269]', 'inflected', 'heb', 'בַּרְזֶל', '["barzel"]', '["and/ of <the>/ iron","and/ to the/ iron"]', '["n-m"]', 'iron (as cutting); by extension, an iron implement (ax) head, iron.', 'perhaps from the root of 1269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6086K}/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["and/ wood"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3701G}/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["[is] for <the>/ silver","for <the>/ silver","for the/ silver","for/ silver","of <the>/ silver","to/ silver"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5315G}/H9026/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ being/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7646}/[H7646]', 'inflected', 'heb', 'שָׂבַע', '["sâbaʻ"]', '["and/ [you are] satisfying","and/ he was satisfied","and/ we have been satisfied","so/ he may be satisfied","so/ they may be satisfied"]', '["v"]', 'to sate, i.e. fill to satisfaction (literally or figuratively) have enough, fill (full, self, with), be (to the) full (of), have plenty of, be satiate, satisfy (with), suffice, be weary of.', 'or שָׂבֵעַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2505A}/H9038/[H2505]', 'inflected', 'heb', 'חָלַק', '["châlaq"]', '["and/ he divided/ them","and/ they divided/ them","and/ you apportioned/ them","and/ you will divide/ them"]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4256}\/[H2505]', 'inflected', 'heb', 'מַחֲלֹקֶת', '["machălôqeth"]', '["divisions"]', '["n-f"]', 'a section (of Levites, people or soldiers) company, course, division, portion. See also 5555.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4847}\/[H4843]', 'inflected', 'heb', 'מְרָרִי', '["Mᵉrârîy"]', '["and/ Merari"]', '["n-pr-m"]', 'Merari, an Israelite Merari. See also 4848.', 'from 4843; bitter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3936H}/[H3935]', 'lemma', 'heb', 'לַעְדָּן', '["Laʻdân"]', '["Ladan"]', '["n-pr-m"]', 'Ladan, the name of two Israelites Laadan.', 'from the same as 3935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8096G}\/[H8088]', 'inflected', 'heb', 'שִׁמְעִי', '["Shimʻîy"]', '["and/ Shimei"]', '["n-pr-m"]', 'Shimi, the name of twenty Israelites Shimeah (from the margin), Shimei, Shimhi, Shimi.', 'from 8088; famous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3171H}/[H2421]', 'lemma', 'heb', 'יְחִיאֵל', '["Yᵉchîyʼêl"]', '["Jehiel"]', '["n-pr-m"]', 'Jechiel (or Jechavel), the name of eight Israelites Jehiel.', 'or (2 Chronicles 29:14) יְחַוְאֵל; from 2421 and 410; God will live;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2241}/[H2133]', 'inflected', 'heb', 'זֵתָם', '["Zêthâm"]', '["and/ Zetham"]', '["n-pr-m"]', 'Zetham, an Israelite Zetham.', 'apparently a variation for 2133;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3100O}/[H3068]', 'inflected', 'heb', 'יוֹאֵל', '["Yôwʼêl"]', '["and/ Joel"]', '["n-pr-m"]', 'Joel, the name of twelve Israelites Joel.', 'from 3068 and 410; Jehovah (is his) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7969}\/[H7969]', 'inflected', 'heb', 'שָׁלוֹשׁ', '["shâlôwsh"]', '["three"]', '["n"]', 'three; occasionally (ordinal) third, or (multiple) thrice fork, often(-times), third, thir(-teen, -teenth), three, thrice. Compare 7991.', 'or שָׁלֹשׁ; masculine שְׁלוֹשָׁה; or שְׁלֹשָׁה; a primitive number;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8019K}/[H7965]', 'lemma', 'heb', 'שְׁלֹמִית', '["Shᵉlômîyth"]', '["Shelomith"]', '["n-pr-m n-pr-f"]', 'Shelomith, the name of five Israelites and three Israelitesses Shelomith.', 'or שׁלוֹמִית; (Ezra 8:10), from 7965; peaceableness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2381}/[H2372]', 'inflected', 'heb', 'חֲזִיאֵל', '["Chăzîyʼêl"]', '["and/ Haziel"]', '["n-pr-m"]', 'Chaziel, a Levite Haziel.', 'from 2372 and 410; seen of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2039H}/[H2022]', 'inflected', 'heb', 'הָרָן', '["Hârân"]', '["and/ Haran"]', '["n-pr-m n-pr-loc"]', 'Haran, the name of two men Haran.', 'perhaps from 2022; mountaineer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3936H}\/[H3935]', 'inflected', 'heb', 'לַעְדָּן', '["Laʻdân"]', '["of/ Ladan"]', '["n-pr-m"]', 'Ladan, the name of two Israelites Laadan.', 'from the same as 3935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8096G}/[H8088]', 'lemma', 'heb', 'שִׁמְעִי', '["Shimʻîy"]', '["Shimei"]', '["n-pr-m"]', 'Shimi, the name of twenty Israelites Shimeah (from the margin), Shimei, Shimhi, Shimi.', 'from 8088; famous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3189H}/[H3161]', 'lemma', 'heb', 'יַחַת', '["Yachath"]', '["Jahath"]', '["n-pr-m"]', 'Jachath, the name of four Israelites Jahath.', 'from 3161; unity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2125}/[H2124]', 'lemma', 'heb', 'זִיזָה', '["Zîyzâh"]', '["Zina"]', '["n-pr-m"]', 'Zizah, an Israelite Zizah.', 'another form for 2124;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3266J}/[H5789]', 'inflected', 'heb', 'יְעוּשׁ', '["Yᵉʻûwsh"]', '["and/ Jeush"]', '["n-pr-m"]', 'Jeush, the name of an Edomite and of four Israelites Jehush, Jeush. Compare 3274.', 'from 5789; hasty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1283J}/[H7451]', 'inflected', 'heb', 'בְּרִיעָה', '["Bᵉrîyʻâh"]', '["and/ Beriah"]', '["n-pr-m"]', 'Beriah, the name of four Israelites Beriah.', 'apparently from the feminine of 7451 with a prepositional prefix; in trouble;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2125}/[H2124]', 'inflected', 'heb', 'זִיזָה', '["Zîyzâh"]', '["and/ Zizah"]', '["n-pr-m"]', 'Zizah, an Israelite Zizah.', 'another form for 2124;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6486}/[H6485]', 'inflected', 'heb', 'פְּקֻדָּה', '["pᵉquddâh"]', '["<into>/ a group"]', '["n-f"]', 'visitation (in many senses, chiefly official) account, (that have the) charge, custody, that which...laid up, numbers, office(-r), ordering, oversight, prison, reckoning, visitation.', 'feminine passive participle of 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6942H}/H9033/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["to/ consecrate/ it"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0461H}/[H410]', 'inflected', 'heb', 'אֱלִיעֶזֶר', '["ʼĔlîyʻezer"]', '["and/ Eliezer"]', '["n-pr-m"]', 'Eliezer, the name of a Damascene and of ten Israelites Eliezer.', 'from 410 and 5828; God of help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7619G}/[H7617]', 'lemma', 'heb', 'שְׁבוּאֵל', '["Shᵉbûwʼêl"]', '["Shebuel","Shubael"]', '["n-pr-m"]', 'Shebuel or Shubael, the name of two Israelites Shebuel, Shubael.', 'or שׁוּבָאֵל; from 7617 (abbreviated form) or 7725 and 410; captive (or returned) of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7345}/[H7337]', 'lemma', 'heb', 'רְחַבְיָה', '["Rᵉchabyâh"]', '["Rehabiah"]', '["n-pr-m"]', 'Rechabjah, an Israelite Rehabiah.', 'or רְחַבְיָהוּ; from 7337 and 3050; Jah has enlarged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0461H}/[H410]', 'inflected', 'heb', 'אֱלִיעֶזֶר', '["ʼĔlîyʻezer"]', '["to/ Eliezer"]', '["n-pr-m"]', 'Eliezer, the name of a Damascene and of ten Israelites Eliezer.', 'from 410 and 5828; God of help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8019A}/[H7965]', 'lemma', 'heb', 'שְׁלֹמִית', '["Shᵉlômîyth"]', '["Shelomith"]', '["n-pr-m n-pr-f"]', 'Shelomith, the name of five Israelites and three Israelitesses Shelomith.', 'or שׁלוֹמִית; (Ezra 8:10), from 7965; peaceableness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H7218H>\', 'inflected', 'heb', 'הראש ס', '["ha./Rosh"]', '["the/ chief"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3404G}/[H3384]', 'lemma', 'heb', 'יְרִיָּה', '["Yᵉrîyâh"]', '["Jeriah"]', '["n-pr-m"]', 'Jerijah, an Israelite Jeriah, Jerijah.', 'or יְרִיָּהוּ; from 3384 and 3050; Jah will throw;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0568I}/[H559]', 'lemma', 'heb', 'אֲמַרְיָה', '["ʼĂmaryâh"]', '["Amariah"]', '["n-pr-m"]', 'Amarjah, the name of nine Israelites Amariah.', 'or prolonged אֲמַרְיָהוּ; from 559 and 3050; Jah has said (i.e. promised);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3166I}/[H2372]', 'lemma', 'heb', 'יַחֲזִיאֵל', '["Yachăzîyʼêl"]', '["Jahaziel"]', '["n-pr-m"]', 'Jachaziel, the name of five Israelites Jahaziel, Jahziel.', 'from 2372 and 410; beheld of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3360}/[H6965]', 'inflected', 'heb', 'יְקַמְעָם', '["Yᵉqamʻâm"]', '["and/ Jekameam"]', '["n-pr-m"]', 'Jekamam, an Israelite Jekameam. Compare 3079, 3361.', 'from 6965 and 5971; (the) people will rise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4318J}/[H4320]', 'lemma', 'heb', 'מִיכָה', '["Mîykâh"]', '["Micah"]', '["n-pr-m"]', 'Micah, the name of seven Israelites Micah, Micaiah, Michah.', 'an abbreviated form of 4320;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3449I}/[H5383]', 'inflected', 'heb', 'יִשִּׁיָּה', '["Yishshîyâh"]', '["and/ Isshiah"]', '["n-pr-m"]', 'Jishshijah, the name of five Israelites Ishiah, Isshiah, Ishijah, Jesiah.', 'or יִשִּׁיָּהוּ; from 5383 and 3050; Jah will lend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8145}\/[H8138]', 'inflected', 'heb', 'שֵׁנִי', '["shênîy"]', '["the/ second"]', '["n"]', 'properly, double, i.e. second; also adverbially, again again, either (of them), (an-) other, second (time).', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0499J}/[H410]', 'lemma', 'heb', 'אֶלְעָזָר', '["ʼElʻâzâr"]', '["Eleazar"]', '["n-pr-m"]', 'Elazar, the name of seven Israelites Eleazar.', 'from 410 and 5826; God (is) helper;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7027H}/[H6983]', 'inflected', 'heb', 'קִישׁ', '["Qîysh"]', '["and/ Kish"]', '["n-pr-m"]', 'Kish, the name of five Israelites Kish.', 'from 6983; a bow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375U}/H9038/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ they took/ them"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7027H}/[H6983]', 'lemma', 'heb', 'קִישׁ', '["Qîysh"]', '["Kish"]', '["n-pr-m"]', 'Kish, the name of five Israelites Kish.', 'from 6983; a bow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5740A}/[H5739]', 'inflected', 'heb', 'עֵדֶר', '["ʻÊder"]', '["and/ Eder"]', '["n-pr-m n-pr-loc"]', 'Eder, the name of an Israelite and of two places in Palestine Edar, Eder.', 'the same as 5739;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3406K}/[H7311]', 'inflected', 'heb', 'יְרִימוֹת', '["Yᵉrîymôwth"]', '["and/ Jeremoth","and/ Jerimoth"]', '["n-pr-f"]', 'Jerimoth or Jeremoth, the name of twelve Israelites Jermoth, Jerimoth, and Ramoth (from the margin).', 'or יְרֵימוֹת; or יְרֵמוֹת; feminine plural from 7311; elevations;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5656H}/H9023/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["for/ service/ its"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4605}/H9011/[H5927]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["and/ <to>/ upwards/ <towards>"]', '["adv"]', 'properly,the upper part, used only adverbially with prefix upward, above, overhead, from the top, etc. above, exceeding(-ly), forward, on (× very) high, over, up(-on, -ward), very.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4612}/H9028/[H5975]', 'inflected', 'heb', 'מַעֲמָד', '["maʻămâd"]', '["function/ their","post/ their"]', '["n-m"]', '(figuratively) a position attendance, office, place, state.', 'from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2893}/[H2892]', 'lemma', 'heb', 'טׇהֳרָה', '["ṭohŏrâh"]', '["[the] purification"]', '["n-f"]', 'ceremonial purification; moral purity × is cleansed, cleansing, purification(-fying).', 'feminine of 2892;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3899H}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["and/ for <the>/ bread","and/ to/ [the] bread of"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
