INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7550}/[H7556]', 'inflected', 'heb', 'רָקִיק', '["râqîyq"]', '["and/ to/ [the] wafers of"]', '["n-m"]', 'a thin cake cake, wafer.', 'from, 7556 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4227}/[H2281]', 'inflected', 'heb', 'מַחֲבַת', '["machăbath"]', '["and/ to the/ baked cake"]', '["n-f"]', 'a pan for baking in pan.', 'from the same as 2281;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7246}/[H7246]', 'inflected', 'heb', 'רָבַךְ', '["râbak"]', '["and/ to the/ mixed [dough]"]', '["v"]', 'to soak (bread in oil) baken, (that which is) fried.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4884>', 'opaque', 'heb', 'מְשׂוּרָה', '["mᵉsûwrâh"]', '["measurement"]', '["n-f"]', 'a measure (for liquids) measure.', 'from an unused root meaning apparently to divide;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4060A}/[H4055]', 'inflected', 'heb', 'מִדָּה', '["middâh"]', '["and/ [the] measure of","and/ a measurement","and/ measurement"]', '["n-f"]', 'properly, extension, i.e. height or breadth; also a measure (including its standard); hence a portion (as measured) or a vestment; specifically, tribute (as measured) garment, measure(-ing, meteyard, piece, size, (great) stature, tribute, wide.', 'feminine of 4055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6153}/[H6150]', 'inflected', 'heb', 'עֶרֶב', '["ʻereb"]', '["to <the>/ evening","to the/ evening"]', '["n-m"]', 'dusk day, even(-ing, tide), night.', 'from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7676}/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["<to> the/ sabbath","for the/ sabbaths"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2320H}/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["for the/ new moons","to the/ new moons"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4150H}/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["and/ <into>/ appointed feasts","and/ for the/ appointed feasts","and/ for the/ appointed times","and/ for/ [the] appointed times of"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4256}/H9028/[H2505]', 'inflected', 'heb', 'מַחֲלֹקֶת', '["machălôqeth"]', '["[are] portions/ their","divisions/ their"]', '["n-f"]', 'a section (of Levites, people or soldiers) company, course, division, portion. See also 5555.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6486}/H9028/[H6485]', 'inflected', 'heb', 'פְּקֻדָּה', '["pᵉquddâh"]', '["to/ group/ their"]', '["n-f"]', 'visitation (in many senses, chiefly official) account, (that have the) charge, custody, that which...laid up, numbers, office(-r), ordering, oversight, prison, reckoning, visitation.', 'feminine passive participle of 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5656H}/H9028/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["by/ service/ their"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1121A}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ among/ [the] descendants of","and/ among/ [the] people of","and/ among/ [the] sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0385}\/[H339]', 'inflected', 'heb', 'אִיתָמָר', '["ʼÎythâmâr"]', '["Ithamar"]', '["n-pr-m"]', 'Ithamar, a son of Aaron Ithamar.', 'from 339 and 8558; coast of the palm-tree;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8098H}/[H8085]', 'lemma', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5417J}/[H5414]', 'lemma', 'heb', 'נְתַנְאֵל', '["Nᵉthanʼêl"]', '["Nethanel"]', '["n-pr-m"]', 'Nethanel, the name of ten Israelites Nethaneel.', 'from 5414 and 410; given of God;');
