INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5307I}/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["and/ he had cast","and/ it fell","and/ it will fall","and/ they cast"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6996A}\/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["<the>/ young"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6635I}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["the/ army"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
