INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5012}/[H5012]', 'inflected', 'heb', 'נָבָא', '["nâbâʼ"]', '["who/ are prophesying","who/ is prophesying","who/ prophesied","who/ prophesy"]', '["v"]', 'to prophesy, i.e. speak (or sing) by inspiration (in prediction or simple discourse) prophesy(-ing), make self a prophet.', 'a primitive root;');
