INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7922}/[H7919]', 'inflected', 'heb', 'שֶׂכֶל', '["sekel"]', '["with/ insight"]', '["n-m"]', 'intelligence; by implication, success discretion, knowledge, policy, prudence, sense, understanding, wisdom, wise.', 'or שֵׂכֶל; from 7919;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1486>/H9023', 'opaque', 'heb', 'גּוֹרָל', '["gôwrâl"]', '["lot/ his"]', '["n-m"]', 'properly, a pebble, i.e. a lot (small stones being used for that purpose); figuratively, a portion or destiny (as if determined by lot) lot.', 'or (shortened) גֹּרָל; from an unused root meaning to be rough (as stone);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6828G}/H9011\/[H6845]', 'inflected', 'heb', 'צָפוֹן', '["tsâphôwn"]', '["north/ -ward"]', '["n-f"]', 'properly, hidden, i.e. dark; used only of the north as a quarter (gloomy and unknown) north(-ern, side, -ward, wind).', 'or צָפֹן; from 6845;');
