INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8019J}/[H7965]', 'inflected', 'heb', 'שְׁלֹמִית', '["Shᵉlômîyth"]', '["and/ Shelomith"]', '["n-pr-m n-pr-f"]', 'Shelomith, the name of five Israelites and three Israelitesses Shelomith.', 'or שׁלוֹמִית; (Ezra 8:10), from 7965; peaceableness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8013H}/[H7965]', 'lemma', 'heb', 'שְׁלֹמוֹת', '["Shᵉlômôwth"]', '["Shelomoth"]', '["n-pr-m"]', 'Shelomoth, the name of two Israelites Shelomith (from the margin), Shelomoth. Compare 8019.', 'feminine plural of 7965; pacifications;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8019J}/[H7965]', 'lemma', 'heb', 'שְׁלֹמִית', '["Shᵉlômîyth"]', '["Shelomith"]', '["n-pr-m n-pr-f"]', 'Shelomith, the name of five Israelites and three Israelitesses Shelomith.', 'or שׁלוֹמִית; (Ezra 8:10), from 7965; peaceableness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3663}/[H3661]', 'lemma', 'heb', 'כְּנַנְיָה', '["Kᵉnanyâh"]', '["Kenaniah"]', '["n-pr-m"]', 'Kenanjah, an Israelite Chenaniah.', 'or כְּנַנְיָהוּ; from 3661 and 3050; Jah has planted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7860>', 'inflected', 'heb', 'לשטרים', '["le./sho.te.Rim"]', '["to/ officials"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8199}/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["and/ to the/ judges","and/ to/ judges"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2811J}/[H2803]', 'lemma', 'heb', 'חֲשַׁבְיָה', '["Chăshabyâh"]', '["Hashabiah"]', '["n-pr-m"]', 'Chashabjah, the name of nine Israelites Hashabiah.', 'or חֲשַׁבְיָהוּ; from 2803 and 3050; Jah has regarded;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4628}/H9011/[H6150]', 'inflected', 'heb', 'מַעֲרָב', '["maʻărâb"]', '["west/ -ward"]', '["n-m"]', 'the west (as a region of the evening sun) west.', 'or (feminine) מַעֲרָבָה; from 6150, in the sense of shading;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5656G}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["and/ to/ [the] service of"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3404H}/[H3384]', 'lemma', 'heb', 'יְרִיָּה', '["Yᵉrîyâh"]', '["Jeriah"]', '["n-pr-m"]', 'Jerijah, an Israelite Jeriah, Jerijah.', 'or יְרִיָּהוּ; from 3384 and 3050; Jah will throw;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8435}/H9023/[H3205]', 'inflected', 'heb', 'תּוֹלְדָה', '["tôwlᵉdâh"]', '["to/ generations/ his"]', '["n-f"]', '(plural only) descent, i.e. family; (figuratively) history birth, generations.', 'or תֹּלְדָה; from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4438}/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["<to> the/ queenhood","of/ [the] reign of"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3270G}/[H5826]', 'inflected', 'heb', 'יַעֲזֵיר', '["Yaʻăzêyr"]', '["at/ Jazer"]', '["n-pr-loc"]', 'Jaazer or Jazer, a place East of the Jordan Jaazer, Jazer.', 'or יַעְזֵר; from 5826; helpful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6485J}/H9038/[H6485]', 'inflected', 'heb', 'פָּקַד', '["pâqad"]', '["and/ he appointed/ them"]', '["v n-m"]', 'to visit (with friendly or hostile intent); by analogy, to oversee, muster, charge, care for, miss, deposit, etc. appoint, × at all, avenge, bestow, (appoint to have the, give a) charge, commit, count, deliver to keep, be empty, enjoin, go see, hurt, do judgment, lack, lay up, look, make, × by any means, miss, number, officer, (make) overseer, have (the) oversight, punish, reckon, (call to) remember(-brance), set (over), sum, × surely, visit, want.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1697K}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ [the] matter of","and/ [the] matters of","and/ [the] words of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7860>/H9028', 'inflected', 'heb', 'ושטריהם', '["ve./sho.te.rei./Hem"]', '["and/ officials/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8334}/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["[were] the/ [ones who] served","who/ serve","who/ served"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4256}/[H2505]', 'inflected', 'heb', 'מַחֲלֹקֶת', '["machălôqeth"]', '["the/ division","the/ divisions"]', '["n-f"]', 'a section (of Levites, people or soldiers) company, course, division, portion. See also 5555.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3318G}/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ the/ [one who] goes out","and/ which/ go out","and/ which/ goes out"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2068G}/[H2065]', 'lemma', 'heb', 'זַבְדִּיאֵל', '["Zabdîyʼêl"]', '["Zabdiel"]', '["n-pr-m"]', 'gift of God; Zabdiel, the name of two Israelites Zabdiel.', 'from 2065 and 410;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4256}/H9023/[H2505]', 'inflected', 'heb', 'מַחֲלֹקֶת', '["machălôqeth"]', '["division/ his"]', '["n-f"]', 'a section (of Levites, people or soldiers) company, course, division, portion. See also 5555.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6635B}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["<the>/ hosts","of <the>/ hosts","the/ armies"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1737}/[H1736]', 'lemma', 'heb', 'דּוֹדַי', '["Dôwday"]', '["Dodai"]', '["n-pr-m"]', 'Dodai, an Israelite Dodai.', 'formed like 1736; amatory;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4256}/H9023/[H2505]', 'inflected', 'heb', 'מַחֲלֹקֶת', '["machălôqeth"]', '["and/ division/ his"]', '["n-f"]', 'a section (of Levites, people or soldiers) company, course, division, portion. See also 5555.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4732H}/[H4731]', 'inflected', 'heb', 'מִקְלוֹת', '["Miqlôwth"]', '["and/ Mikloth"]', '["n-pr-m"]', 'Mikloth, a place in the Desert Mikloth.', '(or perhaps mik-kel-ohth'') plural of (feminine) 4731; rods;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5990}/[H5971]', 'lemma', 'heb', 'עַמִּיזָבָד', '["ʻAmmîyzâbâd"]', '["Ammizabad"]', '["n-pr-m"]', 'Ammizabad, an Israelite Ammizabad.', 'from 5971 and 2064; people of endowment;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2069K}/[H2064]', 'inflected', 'heb', 'זְבַדְיָה', '["Zᵉbadyâh"]', '["and/ Zebadiah"]', '["n-pr-m"]', 'Zebadjah, the name of nine Israelites Zebadiah.', 'or זְבַדְיָהוּ; from 2064 and 3050; Jah has given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8049}/[H8048]', 'lemma', 'heb', 'שַׁמְהוּת', '["Shamhûwth"]', '["Shamhuth"]', '["n-pr-m"]', 'Shamhuth, an Israelite Shamhuth.', 'for 8048; desolation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3155}/[H250]', 'inflected', 'heb', 'יִזְרָח', '["Yizrâch"]', '["the/ Izrahite"]', '["a"]', 'a Jizrach (i.e. Ezrachite or Zarchite) or descendant of Zerach Izrahite.', 'a variation for 250;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6397}/[H6395]', 'inflected', 'heb', 'פְּלוֹנִי', '["Pᵉlôwnîy"]', '["the/ Pelonite"]', '["a"]', 'a Pelonite or inhabitant of an unknown Palon Pelonite.', 'patronymically from an unused name (from 6395) meaning separate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2227}/[H2226]', 'inflected', 'heb', 'זַרְחִי', '["Zarchîy"]', '["of the/ Zerahite[s]"]', '["n-m"]', 'a Zarchite or descendant of Zerach Zarchite.', 'patronymically from 2226;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121G}/ /{H3227B}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["of the/ Ben/ /jaminite[s]"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2469H}/[H2466]', 'lemma', 'heb', 'חֶלְדַּי', '["Chelday"]', '["Heldai"]', '["n-pr-m"]', 'Cheldai, the name of two Israelites Heldai.', 'from 2466; worldliness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6274}/[H6273]', 'inflected', 'heb', 'עׇתְנִיאֵל', '["ʻOthnîyʼêl"]', '["of/ Othniel"]', '["n-pr-m"]', 'Othniel, an Israelite Othniel.', 'from the same as 6273 and 410; force of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0461K}/[H410]', 'lemma', 'heb', 'אֱלִיעֶזֶר', '["ʼĔlîyʻezer"]', '["Eliezer"]', '["n-pr-m"]', 'Eliezer, the name of a Damascene and of ten Israelites Eliezer.', 'from 410 and 5828; God of help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2147M}\/[H2142]', 'inflected', 'heb', 'זִכְרִי', '["Zikrîy"]', '["Zikri"]', '["n-pr-m"]', 'Zicri, the name of twelve Israelites Zichri.', 'from 2142; memorable;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8203J}/[H8199]', 'lemma', 'heb', 'שְׁפַטְיָה', '["Shᵉphaṭyâh"]', '["Shephatiah"]', '["n-pr-m"]', 'Shephatjah, the name of ten Israelites Shephatiah.', 'or שְׁפַטְיָהוּ; from 8199 and 3050; Jah has judged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4601P}\/[H4600]', 'inflected', 'heb', 'מַעֲכָה', '["Maʻăkâh"]', '["Maacah"]', '["n-pr"]', 'Maakah (or Maakath), the name of a place in Syria, also of a Mesopotamian, of three Israelites, and of four Israelitesses and one Syrian woman Maachah, Maachathites. See also 1038.', 'or מַעֲכָת; (Joshua 13:13), from 4600; depression;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2811K}/[H2803]', 'lemma', 'heb', 'חֲשַׁבְיָה', '["Chăshabyâh"]', '["Hashabiah"]', '["n-pr-m"]', 'Chashabjah, the name of nine Israelites Hashabiah.', 'or חֲשַׁבְיָהוּ; from 2803 and 3050; Jah has regarded;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7055I}/[H6965]', 'lemma', 'heb', 'קְמוּאֵל', '["Qᵉmûwʼêl"]', '["Kemuel"]', '["n-pr-m"]', 'Kemuel, the name of a relative of Abraham, and of two Israelites Kemuel.', 'from 6965 and 410; raised of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6659G}\/[H6663]', 'inflected', 'heb', 'צָדוֹק', '["Tsâdôwq"]', '["Zadok"]', '["n-pr-m"]', 'Tsadok, the name of eight or nine Israelites Zadok.', 'from 6663; just;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0453J}/[H410]', 'lemma', 'heb', 'אֱלִיהוּ', '["ʼĔlîyhûw"]', '["Elihu"]', '["n-pr-m"]', 'Elihu, the name of one of Job''s friends, and of three Israelites Elihu.', 'or (fully) אֱלִיהוּא; from 410 and 1931; God of him;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0251G}/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["more than/ a brother","one of/ [the] brothers of"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6018J}/[H6014]', 'lemma', 'heb', 'עׇמְרִי', '["ʻOmrîy"]', '["Omri"]', '["n-pr-m"]', 'Omri, an Israelite Omri.', 'from 6014; heaping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4317N}\/[H4310]', 'inflected', 'heb', 'מִיכָאֵל', '["Mîykâʼêl"]', '["Michael"]', '["n-pr-m"]', 'Mikael, the name of an archangel and of nine Israelites Michael.', 'from 4310 and (the prefix derivative from) 3588 and 410; who (is) like God?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3460H}/[H8085]', 'lemma', 'heb', 'יִשְׁמַעְיָה', '["Yishmaʻyâh"]', '["Ishmaiah"]', '["n-pr-m"]', 'Jishmajah, the name of two Israelites Ishmaiah.', 'or יִשְׁמַעְיָהוּlemma יְשְׁמַעְיָהוּ first vowel, corrected to יִשְׁמַעְיָהוּ; from 8085 and 3050; Jah will hear;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5662M}/[H5647]', 'lemma', 'heb', 'עֹבַדְיָה', '["ʻÔbadyâh"]', '["Obadiah"]', '["n-pr-m"]', 'Obadjah, the name of thirteen Israelites Obadiah.', 'or עֹבַדְיָהוּ; active participle of 5647 and 3050; serving Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3406M}/[H7311]', 'lemma', 'heb', 'יְרִימוֹת', '["Yᵉrîymôwth"]', '["Jerimoth"]', '["n-pr-f"]', 'Jerimoth or Jeremoth, the name of twelve Israelites Jermoth, Jerimoth, and Ramoth (from the margin).', 'or יְרֵימוֹת; or יְרֵמוֹת; feminine plural from 7311; elevations;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5837H}\/[H5828]', 'inflected', 'heb', 'עַזְרִיאֵל', '["ʻAzrîyʼêl"]', '["Azriel"]', '["n-pr-m"]', 'Azriel, the name of three Israelites Azriel.', 'from 5828 and 410; help of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1954H}/[H3467]', 'lemma', 'heb', 'הוֹשֵׁעַ', '["Hôwshêaʻ"]', '["Hoshea"]', '["n-pr-m"]', 'Hoshea, the name of five Israelites Hosea, Hoshea, Oshea.', 'from 3467; deliverer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5812H}/[H5810]', 'lemma', 'heb', 'עֲזַזְיָהוּ', '["ʻĂzazyâhûw"]', '["Azaziah"]', '["n-pr-m"]', 'Azazjah, the name of three Israelites Azaziah.', 'from 5810 and 3050; Jah has strengthened;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3100P}/[H3068]', 'lemma', 'heb', 'יוֹאֵל', '["Yôwʼêl"]', '["Joel"]', '["n-pr-m"]', 'Joel, the name of twelve Israelites Joel.', 'from 3068 and 410; Jehovah (is his) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6305I}\/[H6299]', 'inflected', 'heb', 'פְּדָיָה', '["Pᵉdâyâh"]', '["Pedaiah"]', '["n-pr-m"]', 'Pedajah, the name of six Israelites Pedaiah.', 'or פְּדָיָהוּ; from 6299 and 3050; Jah has ransomed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3035G}/[H3034]', 'lemma', 'heb', 'יִדּוֹ', '["Yiddôw"]', '["Iddo"]', '["n-pr-m"]', 'Jiddo, an Israelite Iddo.', 'from 3034; praised;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148G}\/[H2142]', 'inflected', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3300H}/[H6213]', 'lemma', 'heb', 'יַעֲשִׂיאֵל', '["Yaʻăsîyʼêl"]', '["Jaasiel"]', '["n-pr-m"]', 'Jaasiel, an Israelite Jaasiel, Jasiel.', 'from 6213 and 410; made of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0074}\/[H1]', 'inflected', 'heb', 'אַבְנֵר', '["ʼAbnêr"]', '["Abner"]', '["n-pr-m"]', 'Abner, an Israelite Abner.', 'or (fully) אֲבִינֵר ; from 1 and 5216; father of light (i.e. enlightening);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5832H}/[H5826]', 'lemma', 'heb', 'עֲזַרְאֵל', '["ʻĂzarʼêl"]', '["Azarel"]', '["n-pr-m"]', 'Azarel, the name of five Israelites Azarael, Azareel.', 'from 5826 and 410; God has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3395L}/[H7355]', 'lemma', 'heb', 'יְרֹחָם', '["Yᵉrôchâm"]', '["Jeroham"]', '["n-pr-m"]', 'Jerocham, the name of seven or eight Israelites Jeroham.', 'from 7355; compassionate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/{H1121L}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["<to>/ from/ a son of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4295}/[H5786]', 'inflected', 'heb', 'מַטָּה', '["maṭṭâh"]', '["and/ <to>/ downwards"]', '["adv"]', 'downward, below or beneath; often adverbially with or without prefixes beneath, down(-ward), less, very low, under(-neath).', 'from 5786 with directive enclitic appended;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7235A}/[H7235]', 'inflected', 'heb', 'רָבָה', '["râbâh"]', '["to/ abundance","to/ increase","to/ multiply"]', '["v"]', 'to increase (in whatever respect) (bring in) abundance (× -antly), archer (by mistake for 7232), be in authority, bring up, × continue, enlarge, excel, exceeding(-ly), be full of, (be, make) great(-er, -ly, × -ness), grow up, heap, increase, be long, (be, give, have, make, use) many (a time), (any, be, give, give the, have) more (in number), (ask, be, be so, gather, over, take, yield) much (greater, more), (make to) multiply, nourish, plenty(-eous), × process (of time), sore, store, thoroughly, very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4557}/[H5608]', 'inflected', 'heb', 'מִסְפָּר', '["miçpâr"]', '["the/ number"]', '["n-m"]', 'a number, definite (arithmetical) or indefinite (large, innumerable; small, a few); also (abstractly) narration abundance, account, × all, × few, (in-) finite, (certain) number(-ed), tale, telling, time.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5820J}/[H5794]', 'lemma', 'heb', 'עַזְמָוֶת', '["ʻAzmâveth"]', '["Azmaveth"]', '["n-pr-m n-pr-loc"]', 'Azmaveth, the name of three Israelites and of a place in Palestine Azmaveth. See also 1041.', 'from 5794 and 4194; strong one of death;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5717I}\/[H5716]', 'inflected', 'heb', 'עֲדִיאֵל', '["ʻĂdîyʼêl"]', '["Adiel"]', '["n-pr-m"]', 'Adiel, the name of three Israelites Adiel.', 'from 5716 and 410; ornament of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3723H}/[H3722]', 'inflected', 'heb', 'כָּפָר', '["kâphâr"]', '["and/ in the/ villages"]', '["n-m"]', 'a village (as protected by walls) village. Compare 3715.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4026M}/[H1431]', 'inflected', 'heb', 'מִגְדָּל', '["migdâl"]', '["and/ in the/ towers"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3083K}/[H3068]', 'lemma', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5818I}\/[H5797]', 'inflected', 'heb', 'עֻזִּיָּה', '["ʻUzzîyâh"]', '["Uzziah"]', '["n-pr-m"]', 'Uzzijah, the name of five Israelites Uzziah.', 'or עֻזִּיָּהוּ; from 5797 and 3050; strength of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5656I}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["for/ [the] labor of"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5836}/[H5828]', 'lemma', 'heb', 'עֶזְרִי', '["ʻEzrîy"]', '["Ezri"]', '["n-pr-m"]', 'Ezri, an Israelite Ezri.', 'from 5828; helpful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3620H}/[H3619]', 'lemma', 'heb', 'כְּלוּב', '["Kᵉlûwb"]', '["Kelub"]', '["n-pr-m"]', 'Kelub, the name of two Israelites Chelub.', 'the same as 3619;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8096O}/[H8088]', 'lemma', 'heb', 'שִׁמְעִי', '["Shimʻîy"]', '["Shimei"]', '["n-pr-m"]', 'Shimi, the name of twenty Israelites Shimeah (from the margin), Shimei, Shimhi, Shimi.', 'from 8088; famous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7435}/[H7414]', 'inflected', 'heb', 'רָמָתִי', '["Râmâthîy"]', '["the/ Ramathite"]', '["a"]', 'a Ramathite or inhabitant of Ramah Ramathite.', 'patronymic of 7414;');
