INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0214}/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["for the/ stores","for/ [the] storehouses of","to the/ storerooms","to the/ treasury","to/ [the] storehouses of","to/ [the] treasury of"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2067I}/[H2065]', 'lemma', 'heb', 'זַבְדִּי', '["Zabdîy"]', '["Zabdi"]', '["n-pr-m"]', 'Zabdi, the name of four Israelites Zabdi.', 'from 2065; giving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8225}\/[H8221]', 'inflected', 'heb', 'שִׁפְמִי', '["Shiphmîy"]', '["the/ Shiphmite"]', '["a"]', 'a Shiphmite or inhabitant of Shepham Shiphmite.', 'patrial from 8221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H8256>', 'inflected', 'heb', 'והשקמים', '["ve./ha./shik.Mim"]', '["and/ the/ sycamore-fig trees"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1177H}/[H1167]', 'lemma', 'heb', 'בַּעַל חָנָן', '["Baʻal Chânân"]', '["Baal-","Hanan"]', '["n-pr-m"]', 'Baal-Chanan, the name of an Edomite, also of an Israelite Baal-hanan.', 'from 1167 and 2603; possessor of grace;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1451}\/[H1445]', 'inflected', 'heb', 'גְּדֵרִי', '["Gᵉdêrîy"]', '["the/ Gederite"]', '["a"]', 'a Gederite, or inhabitant of Geder Gederite.', 'patrial from 1445;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3135H}\/[H3068]', 'inflected', 'heb', 'יוֹעָשׁ', '["Yôwʻâsh"]', '["Joash"]', '["n-pr-m"]', 'Joash, the name of two Israelites Joash.', 'from 3068 and 5789; Jehovahhastened;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8289I}/[H3474]', 'inflected', 'heb', 'שָׁרוֹן', '["Shârôwn"]', '["in <the>/ Sharon"]', '["n-pr"]', 'Sharon, the name of a place in Palestine Lasharon, Sharon.', 'probably abridged from 3474; plain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7861}/[H7860]', 'lemma', 'heb', 'שִׁטְרַי', '["Shiṭray"]', '["Shirtai"]', '["n-pr-m"]', 'Shitrai, an Israelite Shitrai.', 'from the same as 7860; magisterial;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8290}/[H8289]', 'inflected', 'heb', 'שָׁרוֹנִי', '["Shârôwnîy"]', '["the/ Sharonite"]', '["a"]', 'a Sharonite or inhabitant of Sharon Sharonite.', 'patrial from 8289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8202K}/[H8199]', 'lemma', 'heb', 'שָׁפָט', '["Shâphâṭ"]', '["Shaphat"]', '["n-pr-m"]', 'Shaphat, the name of four Israelites Shaphat.', 'from 8199; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5724>\', 'opaque', 'heb', 'עַדְלַי', '["ʻAdlay"]', '["Adlai"]', '["n-pr-m"]', 'Adlai, an Israelite Adlai.', 'probably from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0179}/[H56]', 'lemma', 'heb', 'אוֹבִיל', '["ʼôwbîyl"]', '["Obil"]', '["n-pr-m"]', 'Obil, an Ishmaelite Obil.', 'probably from 56; mournful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3165H}/[H3162]', 'lemma', 'heb', 'יֶחְדִּיָּהוּ', '["Yechdîyâhûw"]', '["Jehdeiah"]', '["n-pr-m"]', 'Jechdijah, the name of two Israelites Jehdeiah.', 'from 3162 and 3050; unity of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4824}\/[H4824]', 'inflected', 'heb', 'מֵרֹנֹתִי', '["Mêrônôthîy"]', '["the/ Meronothite"]', '["a"]', 'a Meronothite, or inhabitant of some (otherwise unknown) Meronoth. Meronothite.', 'patrial from an unused noun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3151}/[H2123]', 'lemma', 'heb', 'יָזִיז', '["Yâzîyz"]', '["Jaziz"]', '["n-pr-m"]', 'Jaziz, an Israelite Jaziz.', 'from the same as 2123; he will make prominent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3083O}/[H3068]', 'inflected', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["and/ Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5608B}/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["and/ a scribe"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3171I}/[H2421]', 'inflected', 'heb', 'יְחִיאֵל', '["Yᵉchîyʼêl"]', '["and/ Jehiel"]', '["n-pr-m"]', 'Jechiel (or Jechavel), the name of eight Israelites Jehiel.', 'or (2 Chronicles 29:14) יְחַוְאֵל; from 2421 and 410; God will live;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2453H}/[H2449]', 'lemma', 'heb', 'חַכְמוֹנִי', '["Chakmôwnîy"]', '["Hacmoni"]', '["n-pr-m"]', 'Chakmoni, an Israelite Hachmoni, Hachmonite.', 'from 2449; skilful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2365}/[H2363]', 'inflected', 'heb', 'חוּשַׁי', '["Chûwshay"]', '["and/ Hushai"]', '["n-pr-m"]', 'Chushai, an Israelite Hushai.', 'from 2363; hasty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3077I}/[H3068]', 'lemma', 'heb', 'יְהוֹיָדָע', '["Yᵉhôwyâdâʻ"]', '["Jehoiada"]', '["n-pr-m"]', 'Jehojada, the name of three Israelites Jehoiada. Compare 3111.', 'from 3068 and 3045; Jehovah-known;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1141K}/[H1129]', 'lemma', 'heb', 'בְּנָיָה', '["Bᵉnâyâh"]', '["Benaiah"]', '["n-pr-m"]', 'Benajah, the name of twelve Israelites Benaiah.', 'or בּנָיָהוּ; (prolonged) from 1129 and 3050; Jah has built;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3097G}\/[H3068]', 'inflected', 'heb', 'יוֹאָב', '["Yôwʼâb"]', '["Joab"]', '["n-pr-m"]', 'Joab, the name of three Israelites Joab.', 'from 3068 and 1; Jehovah-fathered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H1916>', 'inflected', 'heb', 'ולהדם', '["ve./la./ha.Dom"]', '["and/ to/ [the] footstool of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2691A}/H9020/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["and/ courts/ my"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0241H}/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["and/ in/ [the] ears of"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121G}/H9026/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["to/ descendants/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5647H}/H9033/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["and/ serve/ him"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5315G}/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["and/ with/ a being"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800A}/H9033/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["[those who] forsake/ him","he has forsaken/ him","he left/ him","he will abandon/ him","it will leave/ him","we have forsaken/ him","you will forsake/ him"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2186A}/H9031/[H2186]', 'inflected', 'heb', 'זָנַח', '["zânach"]', '["he will reject/ you"]', '["v"]', 'reject, forsake, fail cast away (off), remove far away (off).', 'a primitive root meaning to push aside, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5703}/[H5710]', 'inflected', 'heb', 'עַד', '["ʻad"]', '["for/ ever"]', '["n-m"]', 'properly, a (peremptory) terminus, i.e. (by implication) duration, in the sense of advance or perpetuity (substantially as a noun, either with or without a preposition) eternity, ever(-lasting, -more), old, perpetually, world without end.', 'from 5710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4720}/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["<into>/ a sanctuary","for the/ sanctuary","of the/ sanctuary"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6213A}\/[H6213]', 'inflected', 'heb', 'עָשָׂה', '["ʻâsâh"]', '["and/ act"]', '["v"]', 'to do or make, in the broadest sense and widest application accomplish, advance, appoint, apt, be at, become, bear, bestow, bring forth, bruise, be busy, × certainly, have the charge of, commit, deal (with), deck, displease, do, (ready) dress(-ed), (put in) execute(-ion), exercise, fashion, feast, (fight-) ing man, finish, fit, fly, follow, fulfill, furnish, gather, get, go about, govern, grant, great, hinder, hold (a feast), × indeed, be industrious, journey, keep, labour, maintain, make, be meet, observe, be occupied, offer, officer, pare, bring (come) to pass, perform, pracise, prepare, procure, provide, put, requite, × sacrifice, serve, set, shew, × sin, spend, × surely, take, × thoroughly, trim, × very, vex, be (warr-) ior, work(-man), yield, use.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0197J}/[H481]', 'inflected', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["the/ porch"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1597}/H9023/[H1595]', 'inflected', 'heb', 'גִּנְזַךְ', '["ginzak"]', '["and/ treasuries/ its"]', '["n-m"]', 'a treasury treasury.', 'prolonged from 1595;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5944}/H9023/[H5927]', 'inflected', 'heb', 'עֲלִיָּה', '["ʻălîyâh"]', '["and/ upper room/ his","and/ upper rooms/ his","and/ upper rooms/ its"]', '["n-f"]', 'something lofty, i.e. a stair-way; also a second-story room (or even one on the roof); figuratively, the sky ascent, (upper) chamber, going up, loft, parlour.', 'feminine from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2315}/H9023/[H2314]', 'inflected', 'heb', 'חֶדֶר', '["cheder"]', '["and/ rooms/ its"]', '["n-m"]', 'an apartment (usually literal) ((bed) inner) chamber, innermost(-ward) part, parlour, south, × within.', 'from 2314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8403}/[H1129]', 'inflected', 'heb', 'תַּבְנִית', '["tabnîyth"]', '["and/ [the] pattern of"]', '["n-f"]', 'structure; by implication, a model, resemblance figure, form, likeness, pattern, similitude.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7307G}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["by/ [the] spirit of","by/ a spirit of","in the/ spirit","in/ spirit","over the/ wind"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4256}/[H2505]', 'inflected', 'heb', 'מַחֲלֹקֶת', '["machălôqeth"]', '["and/ for/ [the] divisions of"]', '["n-f"]', 'a section (of Levites, people or soldiers) company, course, division, portion. See also 5555.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4501}/[H4500]', 'inflected', 'heb', 'מְנוֹרָה', '["mᵉnôwrâh"]', '["of/ [the] lampstands of","of/ a lampstand"]', '["n-f"]', 'a chandelier candlestick.', 'or מְנֹרָה; feminine of 4500 (in the original sense of 5216);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5216A}/H9028/[H5214]', 'inflected', 'heb', 'נִיר', '["nîyr"]', '["and/ lamps/ their"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5216A}/H9024/[H5214]', 'inflected', 'heb', 'נִיר', '["nîyr"]', '["and/ lamps/ its"]', '["n-m"]', 'a lamp (i.e. the burner) or light (literally or figuratively) candle, lamp, light.', 'or נִר; also נֵיר; or נֵר; or (feminine) נֵרָה; from a primitive root (see 5214; 5135) properly, meaning to glisten;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4501}/[H4500]', 'inflected', 'heb', 'מְנוֹרָה', '["mᵉnôwrâh"]', '["and/ of/ [the] lampstands of"]', '["n-f"]', 'a chandelier candlestick.', 'or מְנֹרָה; feminine of 4500 (in the original sense of 5216);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5656H}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["according to/ [the] service of"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7979}/[H7971]', 'inflected', 'heb', 'שֻׁלְחָן', '["shulchân"]', '["for/ [the] tables of","for/ a table"]', '["n-m"]', 'a table (as spread out); by implication, a meal table.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H4207B>', 'inflected', 'heb', 'והמזלגות', '["ve./ha./miz.la.Got"]', '["and/ the/ forks"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H7184>', 'inflected', 'heb', 'והקשות', '["ve./ha./ke.sa.Vot"]', '["and/ the/ jugs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3713A}/[H3722]', 'inflected', 'heb', 'כְּפוֹר', '["kᵉphôwr"]', '["and/ for/ [the] bowls of"]', '["n-m"]', 'properly, a cover, i.e. (by implication) a tankard (or covered goblet); also white frost (as covering the ground) bason, hoar(-y) frost.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3713A}/[H3722]', 'inflected', 'heb', 'כְּפוֹר', '["kᵉphôwr"]', '["for/ a bowl"]', '["n-m"]', 'properly, a cover, i.e. (by implication) a tankard (or covered goblet); also white frost (as covering the ground) bason, hoar(-y) frost.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3713A}/[H3722]', 'inflected', 'heb', 'כְּפוֹר', '["kᵉphôwr"]', '["and/ a bowl","and/ bowls of"]', '["n-m"]', 'properly, a cover, i.e. (by implication) a tankard (or covered goblet); also white frost (as covering the ground) bason, hoar(-y) frost.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2212}/[H2212]', 'lemma', 'heb', 'זָקַק', '["zâqaq"]', '["[which] people refine","purified","refined","they refine"]', '["v"]', 'to strain, (figuratively) extract, clarify fine, pour down, purge, purify, refine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8403}/[H1129]', 'inflected', 'heb', 'תַּבְנִית', '["tabnîyth"]', '["and/ <to>/ [the] pattern of"]', '["n-f"]', 'structure; by implication, a model, resemblance figure, form, likeness, pattern, similitude.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6566}/[H6566]', 'inflected', 'heb', 'פָּרַשׂ', '["pâras"]', '["for/ spreading out"]', '["v"]', 'to break apart, disperse, etc. break, chop in pieces, lay open, scatter, spread (abroad, forth, selves, out), stretch (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5526B}/[H5526]', 'inflected', 'heb', 'סָכַךְ', '["çâkak"]', '["and/ covering","and/ you may cover"]', '["v"]', 'properly, to entwine as a screen; by implication, to fence in, cover over, (figuratively) protect cover, defence, defend, hedge in, join together, set, shut up.', 'or שָׂכַךְ; (Exodus 33:22), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3791}/[H3789]', 'inflected', 'heb', 'כָּתָב', '["kâthâb"]', '["by/ [the] writing of","in/ a document","in/ writing","in/ writing of"]', '["n-m"]', 'something written, i.e. a writing, record or book register, scripture, writing.', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8403}\/[H1129]', 'inflected', 'heb', 'תַּבְנִית', '["tabnîyth"]', '["the/ pattern"]', '["n-f"]', 'structure; by implication, a model, resemblance figure, form, likeness, pattern, similitude.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3615G}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["<to>/ finished","<to>/ is complete","<to>/ was complete","to/ put an end to"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697G}/H9021\/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["words/ your"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H1002>', 'inflected', 'heb', 'הבירה', '["ha./bi.Rah"]', '["the/ citadel","the/ temple"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5178A}/[H5154]', 'inflected', 'heb', 'נְחֹשֶׁת', '["nᵉchôsheth"]', '["and/ the/ bronze"]', '["n-m"]', 'copper, hence, something made of that metal, i.e. coin, a fetter; figuratively, base (as compared with gold or silver) brasen, brass, chain, copper, fetter (of brass), filthiness, steel.', 'for 5154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1270}/[H1269]', 'inflected', 'heb', 'בַּרְזֶל', '["barzel"]', '["for the/ iron"]', '["n-m"]', 'iron (as cutting); by extension, an iron implement (ax) head, iron.', 'perhaps from the root of 1269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4394}/[H4390]', 'inflected', 'heb', 'מִלֻּא', '["milluʼ"]', '["and/ settings"]', '["n-m"]', 'a fulfilling (only in plural), i.e. (literally) a setting (of gems), or (technically) consecration (also concretely, a dedicatory sacrifice) consecration, be set.', 'from 4390;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6320>', 'opaque', 'heb', 'פּוּךְ', '["pûwk"]', '["antimony"]', '["n-m"]', 'dye (specifically, stibium for the eyes) fair colours, glistering, paint(-ed) (-ing).', 'from an unused root meaning to paint;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7553}/[H7551]', 'inflected', 'heb', 'רִקְמָה', '["riqmâh"]', '["and/ multicolored cloth","and/ variegated color"]', '["n-f"]', 'variegation of color; specifically, embroidery broidered (work), divers colours, (raiment of) needlework (on both sides).', 'from 7551;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7893>', 'opaque', 'heb', 'שַׁיִשׁ', '["shayish"]', '["alabaster"]', '["n-m"]', 'white, i.e. marble. marble', 'from an unused root meaning to bleach, i.e. whiten; See 8336.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7521}/H9040/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["because/ delight/ I"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H2091>', 'inflected', 'heb', 'מזהב', '["mi./za.Hav","mi./za.ho","mi./ze.Hav"]', '["from/ [the] gold of","more than/ gold","some of/ [the] gold of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0211H>', 'opaque', 'heb', 'אוֹפִיר', '["ʼÔwphîyr"]', '["Ophir","gold of Ophir"]', '["n-pr-m"]', 'Ophir, the name of a son of Joktan, and of a gold region in the East Ophir.', 'or (shortened) אֹפִיר; and אוֹפִר; of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2902A}/[H2902]', 'inflected', 'heb', 'טוּחַ', '["ṭûwach"]', '["to/ overlay"]', '["v"]', 'to smear, especially with lime daub, overlay, plaister, smut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3701G}/[H3700]', 'inflected', 'heb', 'כֶּסֶף', '["keçeph"]', '["and/ <to> the/ silver","and/ of <the>/ silver"]', '["n-m"]', 'silver (from its pale color); by implication, money money, price, silver(-ling).', 'from 3700;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3027I}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["by/ [the] hand of","in/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5068}/[H5068]', 'inflected', 'heb', 'נָדַב', '["nâdab"]', '["and/ they made a contribution"]', '["v"]', 'to impel; hence, to volunteer (as a soldier), to present spontaneously offer freely, be (give, make, offer self) willing(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0150}/[H150]', 'inflected', 'heb', 'אֲדַרְכֹּן', '["ʼădarkôn"]', '["and/ darics"]', '["n-m"]', 'a daric or Persian coin dram.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7239}/[H7231]', 'lemma', 'heb', 'רִבּוֹ', '["ribbôw"]', '["[is] twice ten thousand","ten thousand","ten thousands","tens of thousands"]', '["n-f"]', 'a myriad, i.e. indefinitely, large number great things, ten ((eight) -een, (for) -ty, sixscore, threescore, × twenty, (twen) -ty) thousand.', 'from 7231; or רִבּוֹא from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4672}/[H4672]', 'inflected', 'heb', 'מָצָא', '["mâtsâʼ"]', '["and/ <the>/ [what] was found","and/ the/ [one who] was found"]', '["v"]', 'properly, to come forth to, i.e. appear or exist; transitively, to attain, i.e. find or acquire; figuratively, to occur, meet or be present be able, befall, being, catch, × certainly, (cause to) come (on, to, to hand), deliver, be enough (cause to) find(-ing, occasion, out), get (hold upon), × have (here), be here, hit, be left, light (up-) on, meet (with), × occasion serve, (be) present, ready, speed, suffice, take hold on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5068}/H9048/[H5068]', 'inflected', 'heb', 'נָדַב', '["nâdab"]', '["had made a contribution/ they"]', '["v"]', 'to impel; hence, to volunteer (as a soldier), to present spontaneously offer freely, be (give, make, offer self) willing(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5769G}/[H5956]', 'inflected', 'heb', 'עוֹלָם', '["ʻôwlâm"]', '["[are] from/ long ago","from/ antiquity"]', '["n-m"]', 'properly, concealed, i.e. the vanishing point; generally, time out of mind (past or future), i.e. (practically) eternity; frequentatively, adverbial (especially with prepositional prefix) always alway(-s), ancient (time), any more, continuance, eternal, (for, (n-)) ever(-lasting, -more, of old), lasting, long (time), (of) old (time), perpetual, at any time, (beginning of the) world ( without end). Compare 5331, 5703.', 'or עֹלָם; from 5956;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1369}/[H1368]', 'inflected', 'heb', 'גְּבוּרָה', '["gᵉbûwrâh"]', '["and/ the/ strength"]', '["n-f"]', 'force (literally or figuratively); by implication, valor, victory force, mastery, might, mighty (act, power), power, strength.', 'feminine passive participle from the same as 1368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8597}/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["and/ the/ splendor"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5331}/[H5329]', 'inflected', 'heb', 'נֶצַח', '["netsach"]', '["and/ the/ eminence"]', '["n-m"]', 'properly, a goal, i.e. the bright object at a distance travelled towards; hence (figuratively), splendor, or (subjectively) truthfulness, or (objectively) confidence; but usually (adverbially), continually (i.e. to the most distant point of view) alway(-s), constantly, end, ( n-) ever(more), perpetual, strength, victory.', 'or נֵצַח; from 5329;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H1935>', 'inflected', 'heb', 'וההוד', '["ve./ha./Hod"]', '["and/ the/ majesty"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5375L}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ the/ [one who] raises himself"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6239}/[H6238]', 'inflected', 'heb', 'עֹשֶׁר', '["ʻôsher"]', '["and/ <the>/ wealth"]', '["n-m"]', 'wealth × far (richer), riches.', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3519}/[H3513]', 'inflected', 'heb', 'כָּבוֹד', '["kâbôwd"]', '["and/ <the>/ honor"]', '["n-m"]', 'properly, weight, but only figuratively in a good sense, splendor or copiousness glorious(-ly), glory, honour(-able).', 'rarely כָּבֹד; from 3513;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9005/{H6440L}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["[are] from/ <to>/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2388G}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ to/ make strong","and/ to/ repair","and/ to/ strengthen"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5068}/[H5068]', 'inflected', 'heb', 'נָדַב', '["nâdab"]', '["to/ make a contribution"]', '["v"]', 'to impel; hence, to volunteer (as a soldier), to present spontaneously offer freely, be (give, make, offer self) willing(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3027I}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ from/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6738}/[H6751]', 'inflected', 'heb', 'צֵל', '["tsêl"]', '["[are] like <the>/ shadow","[are] like/ a shadow","like <the>/ shadow","like/ [the] shadow of","like/ a shadow"]', '["n-m"]', 'shade, whether literal or figurative defence, shade(-ow).', 'from 6751;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117G>/H9025', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days/ our"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4723B}/[H6960]', 'lemma', 'heb', 'מִקְוֶה', '["miqveh"]', '["O hope of","[is] hope"]', '["n-pr-m n-m"]', 'something waited for, i.e. confidence (objective or subjective); also a collection, i.e. (of water) a pond, or (of men and horses) a caravan or drove abiding, gathering together, hope, linen yarn, plenty (of water), pool.', 'or מִקְוֵה; (1 Kings 10:28), or מִקְוֵאlemma מִּקְוֵא extra dagesh, corrected to מִקְוֵא; (2 Chronicles 1:16), from 6960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027H}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["[is] from/ hand/ your","from/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4339}/[H3474]', 'inflected', 'heb', 'מֵישָׁר', '["mêyshâr"]', '["and/ uprightness<es>"]', '["n-m"]', 'evenness, i.e. (figuratively) prosperity or concord; also straightness, i.e. (figuratively) rectitude (only in plural with singular sense; often adverbially) agreement, aright, that are equal, equity, (things that are) right(-eously, things), sweetly, upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3476}/[H3474]', 'inflected', 'heb', 'יֹשֶׁר', '["yôsher"]', '["in/ [the] uprightness of","in/ uprightness of"]', '["n-m"]', 'the right equity, meet, right, upright(-ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8104G}/H9012/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["keep/ !"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3336}/[H3335]', 'inflected', 'heb', 'יֵצֶר', '["yêtser"]', '["<to>/ [the] inclination of"]', '["n-m"]', 'a form; figuratively, conception (i.e. purpose) frame, thing framed, imagination, mind, work.', 'from 3335;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5715}/H9021/[H5707]', 'inflected', 'heb', 'עֵדוּת', '["ʻêdûwth"]', '["testimonies/ your"]', '["n-f"]', 'testimony testimony, witness.', 'feminine of 5707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2706G}/H9021/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["and/ decrees/ your"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559A}\/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["I have prepared"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4283}/[H4279]', 'inflected', 'heb', 'מׇחֳרָת', '["mochŏrâth"]', '["to the/ next day","to/ [the] next day of"]', '["n-f"]', 'the morrow or (adverbially) tomorrow morrow, next day.', 'or מׇחֳרָתָם; (1 Samuel 30:17), feminine from the same as 4279;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027X}/[H3027]', 'lemma', 'heb', 'יָד', '["yâd"]', '["a hand"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0314}/[H309]', 'inflected', 'heb', 'אַחֲרוֹן', '["ʼachărôwn"]', '["and/ <the>/ latter","and/ the/ latter [time]"]', '["a"]', 'hinder; generally, late or last; specifically (as facing the east) western after (-ward), to come, following, hind(-er, -ermost, -most), last, latter, rereward, ut(ter) most.', 'or (shortened) אַחֲרֹן; from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2374}/[H2372]', 'inflected', 'heb', 'חֹזֶה', '["chôzeh"]', '["the/ seer","the/ seers"]', '["n-m"]', 'a beholder in vision; also a compact (as looked upon with approval) agreement, prophet, see that, seer, (star-) gazer.', 'active participle of 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6256}/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["and/ the/ time","and/ the/ times"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1431}/H9033/[H1434]', 'inflected', 'heb', 'גָּדַל', '["gâdal"]', '["and/ he made great/ him"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H1116>', 'inflected', 'heb', 'לבמות', '["la./ba.Mah","la./ba.Mot","le./va.Mot"]', '["<into>/ high places of","for the/ high places","to the/ high place"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3559A}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["in <the>/ where he had prepared"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1875}/H9033/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["and/ he sought/ it"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6951}/[H6950]', 'inflected', 'heb', 'קָהָל', '["qâhâl"]', '["and/ of the/ assembly","and/ the/ assembly"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4427A}/H9030/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["and/ you have made king/ me"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4427A}/H9030/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["you have made king/ me"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4093}/[H3045]', 'inflected', 'heb', 'מַדָּע', '["maddâʻ"]', '["and/ knowledge"]', '["n-m"]', 'intelligence or consciousness knowledge, science, thought.', 'or מַדַּע; from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5233>', 'opaque', 'heb', 'נֶכֶס', '["nekeç"]', '["riches"]', '["n-m"]', 'treasure riches, wealth.', 'from an unused root meaning to accumulate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4427A}/H9031/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["I have made king/ you"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4093}/[H3045]', 'inflected', 'heb', 'מַדָּע', '["maddâʻ"]', '["and/ the/ knowledge"]', '["n-m"]', 'intelligence or consciousness knowledge, science, thought.', 'or מַדַּע; from 3045;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6239}/[H6238]', 'inflected', 'heb', 'עֹשֶׁר', '["ʻôsher"]', '["and/ rich[es]","and/ wealth"]', '["n-m"]', 'wealth × far (richer), riches.', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5233>', 'inflected', 'heb', 'ונכסים', '["u./ne.kha.Sim"]', '["and/ riches"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3947K}/[H3947]', 'lemma', 'heb', 'לָקַח', '["lâqach"]', '["they took [them]","we will take"]', '["v"]', 'to take (in the widest variety of applications) accept, bring, buy, carry away, drawn, fetch, get, infold, × many, mingle, place, receive(-ing), reserve, seize, send for, take (away, -ing, up), use, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4438}/H9023/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["for/ royalty/ his","of/ reign/ his","to/ kingdom/ his"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5329}/[H5331]', 'inflected', 'heb', 'נָצַח', '["nâtsach"]', '["and/ [were] acting as overseers","and/ overseers"]', '["v"]', 'properly, to glitter from afar, i.e. to be eminent (as a superintendent, especially of the Temple services and its music); to be permanent excel, chief musician (singer), oversee(-r), set forward.', 'a primitive root; also as denominative from 5331');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6942H}/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["to/ consecrate [it]"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4635}/[H6186]', 'inflected', 'heb', 'מַעֲרֶכֶת', '["maʻăreketh"]', '["and/ [the] row of"]', '["n-f"]', 'an arrangement, i.e. (concretely) a pile (of loaves) row, shewbread.', 'from 6186;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2320H}/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["and/ for the/ new moons"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3557}/H9033/[H3557]', 'inflected', 'heb', 'כּוּל', '["kûwl"]', '["they will contain/ him"]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0710}/[H713]', 'inflected', 'heb', 'אַרְגְּוָן', '["ʼargᵉvân"]', '["and/ in <the>/ purple"]', '["n-m"]', 'purple purple.', 'a variation for 713;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3758>', 'inflected', 'heb', 'וכרמיל', '["ve./khar.Mil"]', '["and/ crimson"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6605B}/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["to/ engrave"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0418}/[H484]', 'inflected', 'heb', 'אַלְגּוּמִּים', '["ʼalgûwmmîym"]', '["and/ algum<s>"]', '["n-m"]', 'sticks of algum wood algum (trees).', 'by transposition for 484;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H3844G}/[H3825]', 'inflected', 'heb', 'לְבָנוֹן', '["Lᵉbânôwn"]', '["from/ <the>/ Lebanon"]', '["n-pr-loc"]', 'Lebanon, a mountain range in Palestine Lebanon.', 'from 3825; (the) white mountain (from its snow);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3559A}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["and/ to/ prepare"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0160}/[H158]', 'inflected', 'heb', 'אַהֲבָה', '["ʼahăbâh"]', '["because/ loves","for <the>/ love"]', '["n-f"]', 'love.', 'feminine of 158 and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2361I}/[H2353]', 'inflected', 'heb', 'חוּרָם', '["Chûwrâm"]', '["<to>/ Huram"]', '["n-pr-m"]', 'Churam, the name of an Israelite and two Syrians Huram. Compare 2438.', 'probably from 2353; whiteness, i.e. noble;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0001H}/[H1]', 'lemma', 'heb', 'אָב', '["ʼâb"]', '["Abi"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1270}/[H1269]', 'inflected', 'heb', 'בַּרְזֶל', '["barzel"]', '["by/ iron","in <the>/ iron","with <the>/ iron [axe]"]', '["n-m"]', 'iron (as cutting); by extension, an iron implement (ax) head, iron.', 'perhaps from the root of 1269;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H0713>', 'inflected', 'heb', 'בארגמן', '["ba./''ar.ga.Man"]', '["in <the>/ purple"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H0948>', 'inflected', 'heb', 'ובבוץ', '["u./va./Butz"]', '["and/ in <the>/ fine linen"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H3758>', 'inflected', 'heb', 'ובכרמיל', '["u./va./kar.Mil"]', '["and/ in <the>/ crimson"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6605B}/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["and/ to/ engrave"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2450}/H9021/[H2449]', 'inflected', 'heb', 'חָכָם', '["châkâm"]', '["skilled [people]/ your","wise [people]/ your"]', '["a"]', 'wise, (i.e. intelligent, skilful or artful) cunning (man), subtil, (un-), wise((hearted), man).', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6878>/H9021', 'opaque', 'heb', 'צֹרֶךְ', '["tsôrek"]', '["need/ your"]', '["n-m"]', 'need need.', 'from an unused root meaning to need;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0935P}/H9038/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ we will bring/ them"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7513}/[H7511]', 'lemma', 'heb', 'רַפְסֹדָה', '["raphçôdâh"]', '["rafts"]', '["n-f"]', 'a raft (as flat on the water) flote.', 'from 7511;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5610}/[H5608]', 'inflected', 'heb', 'סְפָר', '["çᵉphâr"]', '["the/ census"]', '["n-m"]', 'a census numbering.', 'from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5608A}/H9038/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["I will count/ them","he had counted/ them"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5329}/[H5331]', 'lemma', 'heb', 'נָצַח', '["nâtsach"]', '["enduring","overseers"]', '["v"]', 'properly, to glitter from afar, i.e. to be eminent (as a superintendent, especially of the Temple services and its music); to be permanent excel, chief musician (singer), oversee(-r), set forward.', 'a primitive root; also as denominative from 5331');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8145}/[H8138]', 'inflected', 'heb', 'שֵׁנִי', '["shênîy"]', '["on the/ second [day]"]', '["n"]', 'properly, double, i.e. second; also adverbially, again again, either (of them), (an-) other, second (time).', 'from 8138;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0753}/[H748]', 'inflected', 'heb', 'אֹרֶךְ', '["ʼôrek"]', '["the/ length"]', '["n-m"]', 'length forever, length, long.', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1363}/[H1361]', 'inflected', 'heb', 'גֹּבַהּ', '["gôbahh"]', '["and/ the/ height"]', '["n-m"]', 'elation, grandeur, arrogance excellency, haughty, height, high, loftiness, pride.', 'from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2645}/H9033/[H2644]', 'inflected', 'heb', 'חָפָה', '["châphâh"]', '["and/ he overlaid/ it"]', '["v"]', 'to cover; by implication, to veil, to encase, protect ceil, cover, overlay.', 'a primitive root (compare 2644, 2653);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8561}/[H8558]', 'lemma', 'heb', 'תִּמֹּר', '["timmôr"]', '["palm trees"]', '["n-f"]', '(architectural) a palm-like pilaster (i.e. umbellate) palm tree.', '(plural or (feminine) תִּמֹּרָה; (singular and plural), from the same root as 8558;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8333}/[H8327]', 'inflected', 'heb', 'שַׁרְשְׁרָה', '["sharshᵉrâh"]', '["and/ chains"]', '["n-f"]', 'a chain; (architectural) probably a garland chain.', 'from 8327 (compare 8331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8597}/[H6286]', 'inflected', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["for/ beauty"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6516>', 'opaque', 'heb', 'פַּרְוַיִם', '["Parvayim"]', '["Parvaim"]', '["n-pr-loc"]', 'Parvajim, an Oriental region Parvaim.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2645}/[H2644]', 'inflected', 'heb', 'חָפָה', '["châphâh"]', '["and/ he overlaid","and/ they have covered"]', '["v"]', 'to cover; by implication, to veil, to encase, protect ceil, cover, overlay.', 'a primitive root (compare 2644, 2653);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7023}/H9023/[H6979]', 'inflected', 'heb', 'קִיר', '["qîyr"]', '["and/ sides/ its","and/ walls/ its"]', '["n-m"]', 'a wall (as built in a trench) mason, side, town, × very, wall.', 'or קִר; (Isaiah 22:5), or (feminine) קִירָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1817C}/H9023/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["and/ doors/ its"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7023}\/[H6979]', 'inflected', 'heb', 'קִיר', '["qîyr"]', '["the/ walls"]', '["n-m"]', 'a wall (as built in a trench) mason, side, town, × very, wall.', 'or קִר; (Isaiah 22:5), or (feminine) קִירָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7341}/H9023/[H7337]', 'inflected', 'heb', 'רֹחַב', '["rôchab"]', '["and/ breadth/ its"]', '["n-m"]', 'width (literally or figuratively) breadth, broad, largeness, thickness, wideness.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3603H}/[H3769]', 'inflected', 'heb', 'כִּכָּר', '["kikkâr"]', '["of/ talents","to/ talents"]', '["n-f"]', 'a circle, i.e. (by implication) a circumjacent tract or region, especially the Ghor or valley of the Jordan; also a (round) loaf; also a talent (or large [round] coin) loaf, morsel, piece, plain, talent.', 'from 3769;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8255}/[H8254]', 'inflected', 'heb', 'שֶׁקֶל', '["sheqel"]', '["to/ shekels"]', '["n-m"]', 'probably a weight; used as a commercial standard shekel.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5944}/[H5927]', 'inflected', 'heb', 'עֲלִיָּה', '["ʻălîyâh"]', '["and/ the/ upper rooms"]', '["n-f"]', 'something lofty, i.e. a stair-way; also a second-story room (or even one on the roof); figuratively, the sky ascent, (upper) chamber, going up, loft, parlour.', 'feminine from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6816>', 'opaque', 'heb', 'צַעְצֻעַ', '["tsaʻtsuaʻ"]', '["castings"]', '["n-m"]', 'sculpture image (work).', 'from an unused root meaning to bestrew with carvings;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0753}/H9028/[H748]', 'inflected', 'heb', 'אֹרֶךְ', '["ʼôrek"]', '["length/ their"]', '["n-m"]', 'length forever, length, long.', 'from 748;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0520A}/[H517]', 'inflected', 'heb', 'אַמָּה', '["ʼammâh"]', '["to/ cubits"]', '["n-f"]', 'properly, a mother (i.e. unit of measure, or the fore-arm (below the elbow), i.e. a cubit; also a door-base (as a bond of the entrance) cubit, + hundred (by exchange for 3967), measure, post.', 'prolonged from 517;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7023}/[H6979]', 'inflected', 'heb', 'קִיר', '["qîyr"]', '["<to>/ [the] wall of","to the/ walls"]', '["n-m"]', 'a wall (as built in a trench) mason, side, town, × very, wall.', 'or קִר; (Isaiah 22:5), or (feminine) קִירָה; from 6979;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3671}/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["and/ the/ wing"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3671}/[H3670]', 'inflected', 'heb', 'כָּנָף', '["kânâph"]', '["<to>/ [the] wing of","to/ [the] wing of"]', '["n-f"]', 'an edge or extremity; specifically (of a bird or army) a wing, (of a garment or bedclothing) a flap, (of the earth) a quarter, (of a building) a pinnacle bird, border, corner, end, feather(-ed), × flying, (one an-) other, overspreading, × quarters, skirt, × sort, uttermost part, wing(-ed).', 'from 3670;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1695}/[H1692]', 'lemma', 'heb', 'דָּבֵק', '["dâbêq"]', '["[was] clinging","cleaving"]', '["a"]', 'adhering cleave, joining, stick closer.', 'from 1692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1004O}\/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["[were] to the/ inside"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0948>', 'inflected', 'heb', 'ובוץ', '["u./Vutz"]', '["and/ fine linen"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3742>\', 'opaque', 'heb', 'כְּרוּב', '["kᵉrûwb"]', '["cherubim"]', '["n-m"]', 'a cherub or imaginary figure cherub, (plural) cherubims.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H6858>', 'inflected', 'heb', 'והצפת', '["ve./ha./Tze.fet"]', '["and/ the/ capital"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8333}/[H8327]', 'inflected', 'heb', 'שַׁרְשְׁרָה', '["sharshᵉrâh"]', '["on the/ chains"]', '["n-f"]', 'a chain; (architectural) probably a garland chain.', 'from 8327 (compare 8331);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H8040H}/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["from/ the/ north"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1162H>\', 'opaque', 'heb', 'בֹּעַז', '["Bôʻaz"]', '["Boaz"]', '["n-pr-m"]', 'Boaz, the ancestor of David; also the name of a pillar in front of the temple Boaz.', 'from an unused root of uncertain meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6967}/H9023\/[H6965]', 'inflected', 'heb', 'קוֹמָה', '["qôwmâh"]', '["height/ its"]', '["n-f"]', 'height × along, height, high, stature, tall.', 'from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1823}/[H1819]', 'inflected', 'heb', 'דְּמוּת', '["dᵉmûwth"]', '["and/ [the] likeness of","and/ a likeness"]', '["n-f"]', 'resemblance; concretely, model, shape; adverbially, like fashion, like (-ness, as), manner, similitude.', 'from 1819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4166}/H9023/[H3332]', 'inflected', 'heb', 'מוּצָקָה', '["mûwtsâqâh"]', '["in/ casting/ its"]', '["n-f"]', 'properly, something poured out, i.e. a casting (of metal); by implication, a tube (as cast) when it was cast, pipe.', 'or מֻצָקָה; from 3332;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1740}/[H1740]', 'lemma', 'heb', 'דּוּחַ', '["dûwach"]', '["he will cleanse","people rinse","people rinsed"]', '["v"]', 'to thrust away; figuratively, to cleanse cast out, purge, wash.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8040H}\/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["from/ [the] north"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5835}/[H5826]', 'inflected', 'heb', 'עֲזָרָה', '["ʻăzârâh"]', '["and/ the/ ledge","and/ the/ precinct"]', '["n-f"]', 'an inclosure; also a border court, settle.', 'from 5826 in its original meaning of surrounding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1817C}/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["and/ [the] doors of","and/ doors","and/ gates"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5835}/[H5826]', 'inflected', 'heb', 'עֲזָרָה', '["ʻăzârâh"]', '["for the/ precinct"]', '["n-f"]', 'an inclosure; also a border court, settle.', 'from 5826 in its original meaning of surrounding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1817C}/H9028/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["and/ doors/ their"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2361J}/[H2353]', 'lemma', 'heb', 'חוּרָם', '["Chûwrâm"]', '["Huram"]', '["n-pr-m"]', 'Churam, the name of an Israelite and two Syrians Huram. Compare 2438.', 'probably from 2353; whiteness, i.e. noble;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4219}\/[H2236]', 'inflected', 'heb', 'מִזְרָק', '["mizrâq"]', '["the/ bowls"]', '["n-m"]', 'a bowl (as if for sprinkling) bason, bowl.', 'from 2236;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1543}/[H1556]', 'inflected', 'heb', 'גֻּלָּה', '["gullâh"]', '["and/ the/ bowls"]', '["n-f"]', 'a fountain, bowl or globe (all as round) bowl, pommel, spring.', 'feminine from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3805}/[H3803]', 'inflected', 'heb', 'כֹתֶרֶת', '["kôthereth"]', '["and/ the/ capitals"]', '["n-f"]', 'the capital of a column chapiter.', 'feminine active participle of 3803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4838}/[H4838]', 'lemma', 'heb', 'מָרַק', '["mâraq"]', '["polish","polished"]', '["v"]', 'to polish; by implication, to sharpen; also to rinse bright, furbish, scour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5672}/[H5666]', 'inflected', 'heb', 'עֲבִי', '["ʻăbîy"]', '["in/ [the] thickness of","with/ [the] thickness of"]', '["n-m"]', 'density, i.e. depth or width thick(-ness). Compare 5645.', 'or עֳבִי]; from 5666;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6868H>', 'opaque', 'heb', 'צְרֵדָה', '["Tsᵉrêdâh"]', '["Zeredah"]', '["n-pr-loc"]', 'Tseredah, a place in Palestine Zereda, Zeredathah.', 'or צְרֵדָתָה; apparently from an unused root meaning to pierce; puncture;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1197A}/H9038/[H1198]', 'inflected', 'heb', 'בָּעַר', '["bâʻar"]', '["to/ burn/ they"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4357}/[H3615]', 'lemma', 'heb', 'מִכְלָה', '["miklâh"]', '["[was] perfection<s> of"]', '["n-f"]', 'completion (in plural concrete adverbial, wholly) perfect. Compare 4356.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1817C}/H9023/[H1802]', 'inflected', 'heb', 'דֶּלֶת', '["deleth"]', '["doors/ its"]', '["n-m n-f"]', 'something swinging, i.e. the valve of a door door (two-leaved), gate, leaf, lid. (Psalm 141:3).', 'from 1802;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1121A}/H9028/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ <to>/ sons/ their","and/ for/ children/ their","and/ for/ sons/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0251H}/H9028/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ <to>/ relatives/ their"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2690}/[H2689]', 'inflected', 'heb', 'חָצַר', '["châtsar"]', '["to the/ trumpeters"]', '["v"]', 'to trumpet, i.e. blow on that instrument blow, sound, trumpeter.', 'a primitive root; properly, to surround with a stockade, and thus separate from the open country; but used only in the reduplicated form חֲצֹצֵר; or (2 Chronicles 5:12) חֲצֹרֵר; as dem. from 2689;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7891}/[H7788]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["and/ to the/ singers"]', '["v"]', 'to sing behold (by mistake for 7789), sing(-er, -ing man, -ing woman).', 'or (the original form) שׁוּר; (1 Samuel 18:6), a primitive root (rather identical with 7788 through the idea of strolling minstrelsy);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7311A}/[H7311]', 'inflected', 'heb', 'רוּם', '["rûwm"]', '["and/ just as/ lifted up"]', '["v"]', 'to be high actively, to rise or raise (in various applications, literally or figuratively) bring up, exalt (self), extol, give, go up, haughty, heave (up), (be, lift up on, make on, set up on, too) high(-er, one), hold up, levy, lift(-er) up, (be) lofty, (× a-) loud, mount up, offer (up), presumptuously, (be) promote(-ion), proud, set up, tall(-er), take (away, off, up), breed worms.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7892A}/[H7891]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["<the>/ song","the/ song","the/ songs"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1984B}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["and/ when/ praised"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4349}/[H3559]', 'inflected', 'heb', 'מָכוֹן', '["mâkôwn"]', '["and/ a place"]', '["n-m"]', 'properly, a fixture, i.e. a basis; generally a place, especially as an abode foundation, habitation, (dwelling-, settled) place.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5835}/[H5826]', 'inflected', 'heb', 'עֲזָרָה', '["ʻăzârâh"]', '["the/ ledge","the/ precinct"]', '["n-f"]', 'an inclosure; also a border court, settle.', 'from 5826 in its original meaning of surrounding;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8469}/[H2603]', 'lemma', 'heb', 'תַּחֲנוּן', '["tachănûwn"]', '["[the] supplications of","supplications"]', '["n-m"]', 'earnest prayer intreaty, supplication.', 'or (feminine) תַּחֲנוּנָה; from 2603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4725}/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["from/ [the] place of","from/ a place"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0423}/H9023/[H422]', 'inflected', 'heb', 'אָלָה', '["ʼâlâh"]', '["to/ put under an oath/ him"]', '["n-f"]', 'an imprecation curse, cursing, execration, oath, swearing.', 'from 422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725K}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["to/ repay"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0001G}/H9028\/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ to/ ancestors/ their"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2403B}/H9028/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["from/ sin/ their"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3420}/[H3418]', 'inflected', 'heb', 'יֵרָקוֹן', '["yêrâqôwn"]', '["and/ mildew"]', '["n-m"]', 'paleness, whether of persons (from fright), or of plants (from drought) greenish, yellow.', 'from 3418;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2625}/[H2628]', 'inflected', 'heb', 'חָסִיל', '["châçîyl"]', '["and/ locust[s]"]', '["n-m"]', 'the ravager, i.e. a locust caterpillar.', 'from 2628;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4341}/H9023/[H3510]', 'inflected', 'heb', 'מַכְאֹב', '["makʼôb"]', '["and/ own pain/ his"]', '["n-m"]', 'anguish or (figuratively) affliction grief, pain, sorrow.', 'sometimes מַכְאוֹב; also (feminine Isaiah 53:3) מַכְאֹבָה; from 3510;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0001G}/H9025\/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["to/ ancestors/ our"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3027H}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4349}/[H3559]', 'inflected', 'heb', 'מָכוֹן', '["mâkôwn"]', '["from/ [the] place of"]', '["n-m"]', 'properly, a fixture, i.e. a basis; generally a place, especially as an abode foundation, habitation, (dwelling-, settled) place.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7628A}/H9028/[H7618]', 'inflected', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["captivity/ their"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7561}/[H7561]', 'inflected', 'heb', 'רָשַׁע', '["râshaʻ"]', '["and/ [one who] condemns as guilty","and/ [those who] act wickedly of","and/ we have acted wickedly"]', '["v"]', 'to be (causatively, do or declare) wrong; by implication, to disturb, violate condemn, make trouble, vex, be (commit, deal, depart, do) wicked(-ly, -ness).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0241G}/H9021/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["and/ ears/ your"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7183B}/[H7181]', 'lemma', 'heb', 'קַשָּׁב', '["qashshâb"]', '["attentive"]', '["a"]', 'hearkening attent(-ive).', 'or קַשֻּׁב; from 7181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8605}/[H6419]', 'inflected', 'heb', 'תְּפִלָּה', '["tᵉphillâh"]', '["to the/ prayer","to/ [the] prayer of"]', '["n-f"]', 'intercession, supplication; by implication, a hymn prayer.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5118}/H9021/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["to/ resting place/ your"]', '["n-m"]', 'quiet rest(-ed, -ing place).', 'or נוֹחַ; from 5117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5797}/H9021/[H5810]', 'inflected', 'heb', 'עֹז', '["ʻôz"]', '["strength/ your"]', '["n-m"]', 'strength in various applications (force, security, majesty, praise) boldness, loud, might, power, strength, strong.', 'or (fully) עוֹז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3548}/H9021/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["priests/ your"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2623}/H9021/[H2616]', 'inflected', 'heb', 'חָסִיד', '["châçîyd"]', '["and/ faithful [people]/ your"]', '["a"]', 'properly, kind, i.e. (religiously) pious (a saint) godly (man), good, holy (one), merciful, saint, (un-) godly.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2896B}/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["<in> the/ good","in <the>/ good","in the/ good","in/ good","on the/ good","on/ good","with <the>/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4899}/H9021/[H4886]', 'inflected', 'heb', 'מָשִׁיחַ', '["mâshîyach"]', '["anointed [one]/ your","anointed/ your"]', '["n-m"]', 'anointed; usually a consecrated person (as a king, priest, or saint); specifically, the Messiah anointed, Messiah.', 'from 4886;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2142}/H9012/[H2145]', 'inflected', 'heb', 'זָכַר', '["zâkar"]', '["remember/ !"]', '["v"]', 'properly, to mark (so as to be recognized), i.e. to remember; by implication, to mention; to be male × burn (incense), × earnestly, be male, (make) mention (of), be mindful, recount, record(-er), remember, make to be remembered, bring (call, come, keep, put) to (in) remembrance, × still, think on, × well.', 'a primitive root; also as denominative from 2145');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2617A}/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["<to>/ [the] covenant loyalti<es> of","<to>/ favor","for/ covenant loyalty"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3615G}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["and/ just as/ finish","and/ just as/ finished"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/<H8064>', 'inflected', 'heb', 'מהשמים', '["me./ha./sha.Ma.yim"]', '["from/ the/ heavens"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2077}/[H2076]', 'inflected', 'heb', 'זֶבַח', '["zebach"]', '["and/ the/ sacrifice","and/ the/ sacrifices"]', '["n-m"]', 'properly, a slaughter, i.e. the flesh of an animal; by implication, a sacrifice (the victim or the act) offer(-ing), sacrifice.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7531A}/[H7529]', 'inflected', 'heb', 'רִצְפָּה', '["ritspâh"]', '["the/ pavement"]', '["n-f"]', 'a hot stone; also a tessellated pavement live coal, pavement.', 'feminine of 7529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3034}/[H3027]', 'inflected', 'heb', 'יָדָה', '["yâdâh"]', '["and/ [am] confessing","and/ [one who] confesses","and/ [was] confessing","and/ give thanks","and/ giving thanks","and/ thanksgiving","and/ to give thanks","so/ I may give thanks to","so/ they may praise"]', '["v"]', 'physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving).', 'a primitive root; used only as denominative from 3027; literally, to use (i.e. hold out) the hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4931}/H9028/[H4929]', 'inflected', 'heb', 'מִשְׁמֶרֶת', '["mishmereth"]', '["duties/ their"]', '["n-f"]', 'watch, i.e. the act (custody), or (concretely) the sentry, the post; objectively preservation, or (concretely) safe; figuratively observance, i.e. (abstractly) duty or (objectively) a usage or party charge, keep, or to be kept, office, ordinace, safeguard, ward, watch.', 'feminine of 4929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1984B}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["when/ praised","with/ praising"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3557}/[H3557]', 'inflected', 'heb', 'כּוּל', '["kûwl"]', '["to/ contain","to/ endure"]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2282}/[H2287]', 'inflected', 'heb', 'חַג', '["chag"]', '["and/ the/ festival"]', '["n-m"]', 'a festival, or a victim therefor (solemn) feast (day), sacrifice, solemnity.', 'or חָג; from 2287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1004B}/H9023/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ in/ own house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2284>', 'opaque', 'heb', 'חָגָב', '["châgâb"]', '["[the] grasshopper"]', '["n-m"]', 'a locust locust.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3665}/[H3665]', 'inflected', 'heb', 'כָּנַע', '["kânaʻ"]', '["so/ they may humble themselves"]', '["v"]', 'properly, to bend the knee; hence, to humiliate, vanquish bring down (low), into subjection, under, humble (self), subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7725O}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ let him return","and/ let them turn back","and/ they may turn","and/ they may turn back","and/ they returned","and/ turn away","so/ they may turn","so/ they may turn back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1870G}/H9028/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["from/ way/ their","from/ ways/ their"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5545}/[H5545]', 'inflected', 'heb', 'סָלַח', '["çâlach"]', '["so/ I may forgive"]', '["v"]', 'to forgive forgive, pardon, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2403B}/H9028/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["<to>/ sin/ their"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0241G}/H9020/[H238]', 'inflected', 'heb', 'אֹזֶן', '["ʼôzen"]', '["and/ ears/ my"]', '["n-f"]', 'broadness. i.e. (concrete) the ear (from its form in man) advertise, audience, displease, ear, hearing, show.', 'from 238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6942G}/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["and/ I have consecrated","and/ consecrate","and/ consecrate yourselves","and/ we have consecrated"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2706G}/H9020/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["and/ statutes/ my"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4438}/H9021/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["kingdom/ your"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0127G}/H9020/[H119]', 'inflected', 'heb', 'אֲדָמָה', '["ʼădâmâh"]', '["land/ my"]', '["n-f"]', 'soil (from its general redness) country, earth, ground, husband(-man) (-ry), land.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5414I}/H9033/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ I will make/ it"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2578}/[H2574]', 'lemma', 'heb', 'חֲמַת צוֹבָה', '["Chămath Tsôwbâh"]', '["Zobah","to Hamath"]', '["n-pr-loc"]', 'Chamath-Tsobah Hamath-Zobah.', 'from 2574 and 6678; Chamath of Tsobah; probably the same as 2574');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2574G}/[H2346]', 'inflected', 'heb', 'חֲמָת', '["Chămâth"]', '["in/ Hamath"]', '["n-pr-loc n-pr-m"]', 'Chamath, a place in Syria Hamath, Hemath.', 'from the same as 2346; walled;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1697J}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ <in>/ a matter of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4687}/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["according to/ [the] command of","according to/ [the] commandment of"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8334}/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["and/ to/ serve"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1697J}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["for/ [the] matter of","to/ [the] matter of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4256}/H9028/[H2505]', 'inflected', 'heb', 'מַחֲלֹקֶת', '["machălôqeth"]', '["by/ divisions/ their"]', '["n-f"]', 'a section (of Levites, people or soldiers) company, course, division, portion. See also 5555.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8179G}/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["and/ [the] gate of","and/ [the] gates of","and/ a gate","and/ gates"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4143}/[H3245]', 'lemma', 'heb', 'מוּסָד', '["mûwçâd"]', '["[the] foundation of","a foundation"]', '["n-m"]', 'a foundation foundation.', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6100}/[H6096]', 'inflected', 'heb', 'עֶצְיוֹן גֶּבֶר', '["ʻEtsyôwn Geber"]', '["to/ Ezion"]', '["n-pr-loc"]', 'Etsjon-Geber, a place on the Red Sea Ezion-geber.', 'from 6096 and 1397; backbone-like of a man;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8010}/[H7965]', 'inflected', 'heb', 'שְׁלֹמֹה', '["Shᵉlômôh"]', '["from/ Solomon"]', '["n-pr-m"]', 'Shelomah, David''s successor Solomon.', 'from 7965; peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1697G}/H9028/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["<to>/ words/ their"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0835}/[H833]', 'inflected', 'heb', 'אֶשֶׁר', '["ʼesher"]', '["and/ how blessed!"]', '["n-m"]', 'happiness; only in masculine plural construction as interjection, how happy! blessed, happy.', 'from 833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5975G}/H9033/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["to/ erect/ it","to/ make stand/ it"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0418}/[H484]', 'lemma', 'heb', 'אַלְגּוּמִּים', '["ʼalgûwmmîym"]', '["algum<s>"]', '["n-m"]', 'sticks of algum wood algum (trees).', 'by transposition for 484;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0418}/[H484]', 'inflected', 'heb', 'אַלְגּוּמִּים', '["ʼalgûwmmîym"]', '["the/ algum<s>"]', '["n-m"]', 'sticks of algum wood algum (trees).', 'by transposition for 484;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4546}/[H5549]', 'lemma', 'heb', 'מְסִלָּה', '["mᵉçillâh"]', '["[the] highway of","[whom] highways","a highway","highways","tracks"]', '["n-f"]', 'a thoroughfare (as turnpiked), literally or figuratively; specifically a viaduct, a staircase causeway, course, highway, path, terrace.', 'from 5549;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5503}/[H5503]', 'inflected', 'heb', 'סָחַר', '["çâchar"]', '["and/ the/ traders"]', '["v"]', 'to travel round (specifically as a pedlar); intensively, to palpitate go about, merchant(-man), occupy with, pant, trade, traffick.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6152B}/[H6150]', 'lemma', 'heb', 'עֲרָב', '["ʻĂrâb"]', '["Arabia"]', '["n-m"]', 'Arab (i.e. Arabia), a country East of Palestine Arabia.', 'or עֲרַב; from 6150 in the figurative sense of sterility;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1004K}/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["in/ [the] House of"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3534}/[H3533]', 'inflected', 'heb', 'כֶּבֶשׁ', '["kebesh"]', '["and/ a footstool"]', '["n-m"]', 'a footstool (as trodden upon) footstool.', 'from 3533;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8500}\/[H8500]', 'inflected', 'heb', 'תֻּכִּי', '["tukkîy"]', '["and/ apes"]', '["n-m"]', 'probably of foreign derivation; some imported creature, probably a peacock peacock.', 'or תּוּכִּי;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2451}/[H2449]', 'inflected', 'heb', 'חׇכְמָה', '["chokmâh"]', '["and/ [the] wisdom of","and/ wisdom","and/ wisdom of"]', '["n-f"]', 'wisdom (in a good sense) skilful, wisdom, wisely, wit.', 'from 2449;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5402}/[H5401]', 'lemma', 'heb', 'נֶשֶׁק', '["nesheq"]', '["[the] weaponry of","weaponry"]', '["n-m"]', 'military equipment, i.e. (collectively) arms (offensive or defensive), or (concretely) an arsenal armed men, armour(-y), battle, harness, weapon.', 'or נֵשֶׁק; from 5401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4818}/[H4817]', 'inflected', 'heb', 'מֶרְכָּבָה', '["merkâbâh"]', '["and/ chariots"]', '["n-f"]', 'a chariot chariot. See also 1024.', 'feminine of 4817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5016}/[H5012]', 'lemma', 'heb', 'נְבוּאָה', '["nᵉbûwʼâh"]', '["[the] prophecy of"]', '["n-f"]', 'a prediction (spoken or written) prophecy.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2378}/[H2372]', 'inflected', 'heb', 'חָזוֹת', '["châzôwth"]', '["and/ in/ [the] visions"]', '["n-f"]', 'a revelation vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3260}/[H3259]', 'lemma', 'heb', 'יֶעְדִּי', '["Yeʻdîy"]', '["Iddo"]', '["n-pr-m"]', 'Jedi, an Israelite Iddo (from the margin) See 3035.', 'from 3259; appointed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9009/{H5971A}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["to/ the/ people"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7521}/H9038/[H7521]', 'inflected', 'heb', 'רָצָה', '["râtsâh"]', '["and/ you will be favorable to/ them"]', '["v"]', 'to be pleased with; specifically, to satisfy a debt (be) accept(-able), accomplish, set affection, approve, consent with, delight (self), enjoy, (be, have a) favour(-able), like, observe, pardon, (be, have, take) please(-ure), reconcile self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H6137>\', 'inflected', 'heb', 'בעקרבים ס', '["Ba./''ak.ra.Bim"]', '["with <the>/ scorpions"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5252}/[H5437]', 'lemma', 'heb', 'נְסִבָּה', '["nᵉçibbâh"]', '["a turn"]', '["n-f"]', 'properly, an environment, i.e. circumstance or turn of affairs cause.', 'feminine participle passive of 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0168G}/H9023\/[H166]', 'inflected', 'heb', 'אֹהֶל', '["ʼôhel"]', '["to/ tents/ its"]', '["n-m"]', 'a tent (as clearly conspicuous from a distance) covering, (dwelling) (place), home, tabernacle, tent.', 'from 166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1913B}/[H1913]', 'lemma', 'heb', 'הֲדוֹרָם', '["Hădôwrâm"]', '["Hadoram"]', '["n-pr-m"]', 'Hadoram, a son of Joktan, and the tribe descended from him Hadoram.', 'or הֲדֹרָם; probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7346}\/[H7337]', 'inflected', 'heb', 'רְחַבְעָם', '["Rᵉchabʻâm"]', '["to/ Rehoboam"]', '["n-pr-m"]', 'Rechabam, an Israelite king Rehoboam.', 'from 7337 and 5971; a people has enlarged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1980G}/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["from/ going","more than/ to go"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3379G}\/[H7378]', 'inflected', 'heb', 'יָרׇבְעָם', '["Yârobʻâm"]', '["Jeroboam"]', '["n-pr-m"]', 'Jarobam, the name of two Israelite kings Jeroboam.', 'from 7378 and 5971; (the) people will contend;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4692}/[H6696]', 'inflected', 'heb', 'מָצוֹר', '["mâtsôwr"]', '["to/ fortification"]', '["n-m"]', 'something hemming in, i.e. (objectively) a mound (of besiegers), (abstractly) a siege, (figuratively) distress; or (subjectively) a fastness besieged, bulwark, defence, fenced, fortress, siege, strong (hold), tower.', 'or מָצוּר; from 6696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5862I}/[H5861]', 'lemma', 'heb', 'עֵיטָם', '["ʻÊyṭâm"]', '["Etam"]', '["n-pr-loc"]', 'Etam, a place in Palestine Etam.', 'from 5861; hawk-ground;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4762G}/[H4761]', 'lemma', 'heb', 'מַרְאֵשָׁה', '["Marʼêshâh"]', '["Mareshah"]', '["n-pr-loc"]', 'Mareshah, the name of two Israelites and of a place in Palestine Mareshah.', 'or מַרֵשָׁה; formed like 4761; summit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0115}/[H142]', 'lemma', 'heb', 'אֲדוֹרַיִם', '["ʼĂdôwrayim"]', '["Adoraim"]', '["n-pr-loc"]', 'Adorajim, a place in Palestine Adoraim.', 'dual from 142 (in the sense of eminence); double mound;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4694}/[H4692]', 'lemma', 'heb', 'מְצוּרָה', '["mᵉtsûwrâh"]', '["fortification","fortifications"]', '["n-f"]', 'a hemming in, i.e. (objectively) a mound (of siege), or (subjectively) a rampart (of protection), (abstractly) fortification fenced (city, fort, munition, strong hold.', 'or מְצֻרָה; feminine of 4692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4694}/[H4692]', 'inflected', 'heb', 'מְצוּרָה', '["mᵉtsûwrâh"]', '["<the>/ fortifications","the/ fortifications"]', '["n-f"]', 'a hemming in, i.e. (objectively) a mound (of siege), or (subjectively) a rampart (of protection), (abstractly) fortification fenced (city, fort, munition, strong hold.', 'or מְצֻרָה; feminine of 4692;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2388G}/H9038/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ he encouraged/ them","and/ he made strong/ them","and/ he repaired/ them","and/ they helped/ them"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1144G}\/[H1121]', 'inflected', 'heb', 'בִּנְיָמִין', '["Binyâmîyn"]', '["and/ Benjamin"]', '["n-pr-m"]', 'Binjamin, youngest son of Jacob; also the tribe descended from him, and its territory Benjamin.', 'from 1121 and 3225; son of (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2186A}/H9038/[H2186]', 'inflected', 'heb', 'זָנַח', '["zânach"]', '["I had rejected/ them","he had rejected/ them"]', '["v"]', 'reject, forsake, fail cast away (off), remove far away (off).', 'a primitive root meaning to push aside, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3547}/[H3548]', 'inflected', 'heb', 'כָּהַן', '["kâhan"]', '["from/ serving as a priest","from/ serving as priests"]', '["v"]', 'to officiate as a priest; figuratively, to put on regalia deck, be (do the office of a, execute the, minister in the) priest(''s office).', 'a primitive root, apparently meaning to mediate in religious services; but used only as denominative from 3548;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8163C}/[H8175]', 'inflected', 'heb', 'שָׂעִיר', '["sâʻîyr"]', '["and/ for the/ goats"]', '["a n-m"]', 'shaggy; as noun, a he-goat; by analogy, a faun devil, goat, hairy, kid, rough, satyr.', 'or שָׂעִר; from 8175;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5695}/[H5696]', 'inflected', 'heb', 'עֵגֶל', '["ʻêgel"]', '["and/ for the/ calves"]', '["n-m"]', 'a (male) calf (as frisking round), especially one nearly grown (i.e. a steer) bullock, calf.', 'from the same as 5696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5414H}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["those/ [who] set"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4258H}/[H4257]', 'lemma', 'heb', 'מַחֲלַת', '["Machălath"]', '["Mahalath"]', '["n-pr-f"]', 'Machalath, the name of an Ishmaelitess and of an Israelitess Mahalath.', 'the same as 4257; sickness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3406N}/[H7311]', 'lemma', 'heb', 'יְרִימוֹת', '["Yᵉrîymôwth"]', '["Jerimoth"]', '["n-pr-f"]', 'Jerimoth or Jeremoth, the name of twelve Israelites Jermoth, Jerimoth, and Ramoth (from the margin).', 'or יְרֵימוֹת; or יְרֵמוֹת; feminine plural from 7311; elevations;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0032J}/[H1]', 'lemma', 'heb', 'אֲבִיהַיִל', '["ʼĂbîyhayil"]', '["Abihail"]', '["n-pr-m"]', 'Abihail or Abichail, the name of three Israelites and two Israelitesses Abihail.', 'or (more correctly) אֲבִיחַיִל ; from 1 and 2428; father (i.e. possessor) of might;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3266K}/[H5789]', 'lemma', 'heb', 'יְעוּשׁ', '["Yᵉʻûwsh"]', '["Jeush"]', '["n-pr-m"]', 'Jeush, the name of an Edomite and of four Israelites Jehush, Jeush. Compare 3274.', 'from 5789; hasty;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8114H}/[H8104]', 'lemma', 'heb', 'שְׁמַרְיָה', '["Shᵉmaryâh"]', '["Shemariah"]', '["n-pr-m"]', 'Shemarjah, the name of four Israelites Shamariah, Shemariah.', 'or שְׁמַרְיָהוּ; from 8104 and 3050; Jah has guarded;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2093}/[H2092]', 'lemma', 'heb', 'זַהַם', '["Zaham"]', '["Zaham"]', '["n-pr-m"]', 'Zaham, an Israelite Zaham.', 'from 2092; loathing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0310A}/H9034/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["and/ after/ her"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6262I}/[H6261]', 'lemma', 'heb', 'עַתַּי', '["ʻAttay"]', '["Attai"]', '["n-pr-m"]', 'Attai, the name of three Israelites Attai.', 'for 6261;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2124H}/[H2123]', 'lemma', 'heb', 'זִיזָא', '["Zîyzâʼ"]', '["Ziza"]', '["n-pr-m"]', 'Ziza, the name of two Israelites Ziza.', 'apparently from the same as 2123; prominence;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8019G}/[H7965]', 'lemma', 'heb', 'שְׁלֹמִית', '["Shᵉlômîyth"]', '["Shelomith"]', '["n-pr-m n-pr-f"]', 'Shelomith, the name of five Israelites and three Israelitesses Shelomith.', 'or שׁלוֹמִית; (Ezra 8:10), from 7965; peaceableness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375U}/[H5375]', 'lemma', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["he had taken","they had taken","they have taken","you take","you will take"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4202}/[H2109]', 'inflected', 'heb', 'מָזוֹן', '["mâzôwn"]', '["<the>/ food"]', '["n-m"]', 'food meat, victual.', 'from 2109;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3559H}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["when/ established"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H2393}/H9023/[H2391]', 'inflected', 'heb', 'חֶזְקָה', '["chezqâh"]', '["and/ according to/ strength/ his","and/ according to/ strengthening/ his"]', '["n-f"]', 'prevailing power strength(-en self), (was) strong.', 'feminine of 2391;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0505G}/[H504]', 'inflected', 'heb', 'אֶלֶף', '["ʼeleph"]', '["for/ a thousand","in/ thousands of","with/ one thousand"]', '["n-m"]', 'hence (the ox''s head being the first letter of the alphabet, and this eventually used as a numeral) a thousand thousand.', 'prop, the same as 504;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8346}/[H8337]', 'inflected', 'heb', 'שִׁשִּׁים', '["shishshîym"]', '["and/ with/ sixty"]', '["n"]', 'sixty sixty, three score.', 'multiple of 8337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3864>', 'opaque', 'heb', 'לוּבִי', '["Lûwbîy"]', '["Libyans"]', '["n"]', 'a Libyan or inhabitant of interior Africa (only in plural) Lubim(-s), Libyans.', 'or לֻבִּי; (Daniel 11:43), partrial from a name probably derived from an unused root meaning to thirst, i.e. a dry region; apparently');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5525}/[H5520]', 'lemma', 'heb', 'סֻכִּי', '["Çukkîy"]', '["Sukkites"]', '["n-pr-m"]', 'a Sukkite, or inhabitant of some place near Egypt (i.e. hut-dwellers) Sukkiims.', 'patrial from an unknown name (perhaps 5520);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3569G}/[H3568]', 'inflected', 'heb', 'כּוּשִׁי', '["Kûwshîy"]', '["and/ Cushites"]', '["a"]', 'a Cushite, or descendant of Cush Cushi, Cushite, Ethiopian(-s).', 'patronymically from 3568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8098A}/[H8085]', 'inflected', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["and/ Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7200G}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ when/ saw"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5656G}/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["and/ [the] service of"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3665}/H9043/[H3665]', 'inflected', 'heb', 'כָּנַע', '["kânaʻ"]', '["and/ when/ he humbled/ himself"]', '["v"]', 'properly, to bend the knee; hence, to humiliate, vanquish bring down (low), into subjection, under, humble (self), subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3617}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["for/ complete destruction","to/ complete destruction"]', '["n-f"]', 'a completion; adverb, completely; also destruction altogether, (be, utterly) consume(-d), consummation(-ption), was determined, (full, utter) end, riddance.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2896A}\/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1697K}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["in/ [the] words of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5714I}/[H5710]', 'inflected', 'heb', 'עִדּוֹ', '["ʻIddôw"]', '["and/ Iddo"]', '["n-pr-m"]', 'Iddo (or Iddi), the name of five Israelites Iddo. Compare 3035, 3260.', 'or עִדּוֹא; or עִדִּיא; from 5710; timely;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4322H}/[H4320]', 'lemma', 'heb', 'מִיכָיָהוּ', '["Mîykâyâhûw"]', '["[was] Micaiah"]', '["n-pr-m"]', 'Mikajah, the name of an Israelite and an Israelitess Michaiah.', 'for 4320;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0222I}/[H217]', 'lemma', 'heb', 'אוּרִיאֵל', '["ʼÛwrîyʼêl"]', '["Uriel"]', '["n-pr-m"]', 'Uriel, the name of two Israelites Uriel.', 'from 217 and 410; flame of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2428G}\/[H2342]', 'inflected', 'heb', 'חַיִל', '["chayil"]', '["strength"]', '["n-m"]', 'probably a force, whether of men, means or other resources; an army, wealth, virtue, valor, strength able, activity, ( ) army, band of men (soldiers), company, (great) forces, goods, host, might, power, riches, strength, strong, substance, train, ( ) valiant(-ly), valour, virtuous(-ly), war, worthy(-ily).', 'from 2342;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6787}/[H6785]', 'lemma', 'heb', 'צְמָרַיִם', '["Tsᵉmârayim"]', '["Zemaraim"]', '["n-pr-loc"]', 'Tsemarajim, a place in Palestine Zemaraim.', 'dual of 6785; double fleece;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440L}/H9028/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ them"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2388J}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["to/ show yourselves strong"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5973A}/H9036/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["and/ [are] with/ you","and/ with/ you"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5971A}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["as the/ people","like the/ peoples","like/ [the] peoples of"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3808}/[H3808]', 'inflected', 'heb', 'לֹא', '["lôʼ"]', '["<to>/ not","by/ [those who] not","to/ Not-","to/ not"]', '["adv"]', 'not (the simple or abs. negation); by implication, no; often used with other particles × before, or else, ere, except, ig(-norant), much, less, nay, neither, never, no((-ne), -r, (-thing)), (× as though...,(can-), for) not (out of), of nought, otherwise, out of, surely, as truly as, of a truth, verily, for want, whether, without.', 'or לוֹא; or לֹה; (Deuteronomy 3:11), a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0430J}\/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["gods"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7321}/[H7321]', 'inflected', 'heb', 'רוּעַ', '["rûwaʻ"]', '["to/ sound [the] battle signal"]', '["v"]', 'to mar (especially by breaking); figuratively, to split the ears (with sound), i.e. shout (for alarm or joy) blow an alarm, cry (alarm, aloud, out), destroy, make a joyful noise, smart, shout (for joy), sound an alarm, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3993}/[H693]', 'inflected', 'heb', 'מַאֲרָב', '["maʼărâb"]', '["and/ the/ ambush"]', '["n-m"]', 'an ambuscade lie in ambush, ambushment, lurking place, lying in wait.', 'from 693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7321}/[H7321]', 'inflected', 'heb', 'רוּעַ', '["rûwaʻ"]', '["when/ sounded [the] battle signal"]', '["v"]', 'to mar (especially by breaking); figuratively, to split the ears (with sound), i.e. shout (for alarm or joy) blow an alarm, cry (alarm, aloud, out), destroy, make a joyful noise, smart, shout (for joy), sound an alarm, triumph.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5971A}/H9023/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ people/ his"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3466G}/[H3465]', 'lemma', 'heb', 'יְשָׁנָה', '["Yᵉshânâh"]', '["Jeshanah"]', '["n-pr-f"]', 'Jeshanah, a place in Palestine Jeshanah.', 'feminine of 3465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6085I}/[H6081]', 'lemma', 'heb', 'עֶפְרוֹן', '["ʻEphrôwn"]', '["Ephrayin"]', '["n-pr-m n-pr-loc"]', 'Ephron, the name of a Canaanite and of two places in Palestine Ephron, Ephrain (from the margin).', 'from the same as 6081; fawn-like;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5062}/H9033/[H5062]', 'inflected', 'heb', 'נָגַף', '["nâgaph"]', '["and/ he struck/ him"]', '["v"]', 'to push, gore, defeat, stub (the toe), inflict (a disease) beat, dash, hurt, plague, slay, smite (down), strike, stumble, × surely, put to the worse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1323G}\/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["daughters"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1870G}/H9023/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["and/ way/ his","and/ ways/ his"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4097}/[H1875]', 'inflected', 'heb', 'מִדְרָשׁ', '["midrâsh"]', '["in/ [the] record of"]', '["n-m"]', 'properly, an investigation, i.e. (by implication) a treatise or elaborate compilation story.', 'from 1875;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5714I}/[H5710]', 'lemma', 'heb', 'עִדּוֹ', '["ʻIddôw"]', '["Iddo"]', '["n-pr-m"]', 'Iddo (or Iddi), the name of five Israelites Iddo. Compare 3035, 3260.', 'or עִדּוֹא; or עִדִּיא; from 5710; timely;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2553}/[H2535]', 'inflected', 'heb', 'חַמָּן', '["chammân"]', '["the/ incense altars"]', '["n-m"]', 'a sun-pillar idol, image.', 'from 2535;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5439I}/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["from/ round about"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6743B}\/[H6743]', 'inflected', 'heb', 'צָלַח', '["tsâlach"]', '["and/ they prospered"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1144G}/[H1121]', 'inflected', 'heb', 'בִּנְיָמִין', '["Binyâmîyn"]', '["and/ of/ Benjamin"]', '["n-pr-m"]', 'Binjamin, youngest son of Jacob; also the tribe descended from him, and its territory Benjamin.', 'from 1121 and 3225; son of (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2226K}/[H2225]', 'lemma', 'heb', 'זֶרַח', '["Zerach"]', '["Zerah"]', '["n-pr-m"]', 'Zerach, the name of three Israelites, also of an Idumaean and an Ethiopian prince Zarah, Zerah.', 'the same as 2225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1516L}/[H1466]', 'inflected', 'heb', 'גַּיְא', '["gayʼ"]', '["in/ [the] valley of"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6859}/[H6857]', 'lemma', 'heb', 'צְפָתָה', '["Tsᵉphâthâh"]', '["Zephathah"]', '["n-pr-loc"]', 'Tsephathah, a place in Palestine Zephathah.', 'the same as 6857;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4762G}/[H4761]', 'inflected', 'heb', 'מַרְאֵשָׁה', '["Marʼêshâh"]', '["to/ Mareshah"]', '["n-pr-loc"]', 'Mareshah, the name of two Israelites and of a place in Palestine Mareshah.', 'or מַרֵשָׁה; formed like 4761; summit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8034}/H9021/[H7760]', 'inflected', 'heb', 'שֵׁם', '["shêm"]', '["and/ in/ name/ your","and/ on/ name/ your"]', '["n-m"]', 'an appellation, as a mark or memorial of individuality; by implication honor, authority, character base, (in-) fame(-ous), named(-d), renown, report.', 'a primitive word [perhaps rather from 7760 through the idea of definite and conspicuous position; compare 8064];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1642}/[H1641]', 'inflected', 'heb', 'גְּרָר', '["Gᵉrâr"]', '["to/ Gerar"]', '["n-pr-loc"]', 'Gerar, a Philistine city Gerar.', 'probably from 1641; a rolling country;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3569G}/[H3568]', 'inflected', 'heb', 'כּוּשִׁי', '["Kûwshîy"]', '["of/ [the] Cushites"]', '["a"]', 'a Cushite, or descendant of Cush Cushi, Cushite, Ethiopian(-s).', 'patronymically from 3568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0961}/[H957]', 'lemma', 'heb', 'בִּזָּה', '["bizzâh"]', '["plunder"]', '["n-f"]', 'booty prey, spoil.', 'feminine of 957;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5838M}/[H5826]', 'inflected', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["and/ Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5752G}/[H5749]', 'lemma', 'heb', 'עוֹדֵד', '["ʻÔwdêd"]', '["Oded"]', '["n-pr-m"]', 'Oded, the name of two Israelites Oded.', 'or עֹדֵד; from 5749; reiteration;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3808}/[H3808]', 'inflected', 'heb', 'לֹא', '["lôʼ"]', '["and/ to/ not"]', '["adv"]', 'not (the simple or abs. negation); by implication, no; often used with other particles × before, or else, ere, except, ig(-norant), much, less, nay, neither, never, no((-ne), -r, (-thing)), (× as though...,(can-), for) not (out of), of nought, otherwise, out of, surely, as truly as, of a truth, verily, for want, whether, without.', 'or לוֹא; or לֹה; (Deuteronomy 3:11), a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2000}/H9038/[H1949]', 'inflected', 'heb', 'הָמַם', '["hâmam"]', '["he troubled/ them"]', '["v"]', 'properly, to put in commotion; by implication, to disturb, drive, destroy break, consume, crush, destroy, discomfit, trouble, vex.', 'a primitive root (compare 1949, 1993);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6468}/H9026\/[H6466]', 'inflected', 'heb', 'פְּעֻלָּה', '["pᵉʻullâh"]', '["for/ work/ your"]', '["n-f"]', '(abstractly) work labour, reward, wages, work.', 'feminine passive participle of 6466;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H8085G}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ just as/ heard"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H5016}/[H5012]', 'inflected', 'heb', 'נְבוּאָה', '["nᵉbûwʼâh"]', '["and/ the/ prophecy of"]', '["n-f"]', 'a prediction (spoken or written) prophecy.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5838M}/[H5826]', 'lemma', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2318}/[H2318]', 'inflected', 'heb', 'חָדַשׁ', '["châdash"]', '["and/ he renewed","and/ they will renew"]', '["v"]', 'to be new; causatively, to rebuild renew, repair.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0197J}/[H481]', 'lemma', 'heb', 'אוּלָם', '["ʼûwlâm"]', '["[the] porch of","a porch"]', '["n-m"]', 'a vestibule (as bound to the building) porch.', 'or (shortened), אֻלָם ; from 481 (in the sense of tying);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1481A}/[H1481]', 'inflected', 'heb', 'גּוּר', '["gûwr"]', '["and/ those/ [who] sojourned"]', '["v"]', 'properly, to turn aside from the road (for a lodging or any other purpose), i.e. sojourn (as a guest); also to shrink, fear (as in a strange place); also to gather for hostility (as afraid) abide, assemble, be afraid, dwell, fear, gather (together), inhabitant, remain, sojourn, stand in awe, (be) stranger, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H8095G}/[H8085]', 'inflected', 'heb', 'שִׁמְעוֹן', '["Shimʻôwn"]', '["and/ from/ Simeon"]', '["n-pr-m"]', 'Shimon, one of Jacob''s sons, also the tribe descended from him Simeon.', 'from 8085; hearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6996H}/[H6962]', 'lemma', 'heb', 'קָטָן', '["qâṭân"]', '["[the] young [one] of","small"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8643}/[H7321]', 'inflected', 'heb', 'תְּרוּעָה', '["tᵉrûwʻâh"]', '["and/ with/ a shout"]', '["n-f"]', 'clamor, i.e. acclamation of joy or a battle-cry; especially clangor of trumpets, as an alarum alarm, blow(-ing) (of, the) (trumpets), joy, jubile, loud noise, rejoicing, shout(-ing), (high, joyful) sound(-ing).', 'from 7321;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7782}/[H8231]', 'inflected', 'heb', 'שׁוֹפָר', '["shôwphâr"]', '["and/ with/ ram''s horns"]', '["n-m"]', 'a cornet (as giving a clear sound) or curved horn cornet, trumpet.', 'or שֹׁפָר; from 8231 in the original sense of incising;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7522}/H9028/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["will/ their"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6944G}/H9023/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["and/ own holy things/ his"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0609G>\', 'opaque', 'heb', 'אָסָא', '["ʼÂçâʼ"]', '["Asa"]', '["n-pr-m"]', 'Asa, the name of a king and of a Levite Asa.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0214}/[H686]', 'inflected', 'heb', 'אוֹצָר', '["ʼôwtsâr"]', '["from/ [the] treasuries of","more than/ treasure"]', '["n-m"]', 'a depository armory, cellar, garner, store(-house), treasure(-house) (-y).', 'from 686;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0066}/[H58]', 'lemma', 'heb', 'אַבֵל מַיִם', '["ʼAbêl Mayim"]', '["Abel","Maim"]', '["n-pr-loc"]', 'Abel-Majim, a place in Palestine Abel-maim.', 'from 58 and 4325; meadow of water;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4399}/H9023\/[H4397]', 'inflected', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["work/ his"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0609G>', 'inflected', 'heb', 'ואסא', '["ve./''a.Sa''"]', '["and/ Asa"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4709G}\/[H4708]', 'inflected', 'heb', 'מִצְפָּה', '["Mitspâh"]', '["<the>/ Mizpah"]', '["n-pr-f"]', 'Mitspah, the name of two places in Palestine Mitspah. (This seems rather to be only an orthographic variation of 4708 when ''in pause''.)', 'feminine of 4708;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8172}/H9041/[H8172]', 'inflected', 'heb', 'שָׁעַן', '["shâʻan"]', '["because/ depending/ you"]', '["v"]', 'to support one''s self lean, lie, rely, rest (on, self), stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3027I}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["from/ hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H3864>', 'inflected', 'heb', 'והלובים', '["ve./ha./lu.Vim"]', '["and/ the/ Libyans"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8172}/H9041/[H8172]', 'inflected', 'heb', 'שָׁעַן', '["shâʻan"]', '["and/ because/ depending/ you"]', '["v"]', 'to support one''s self lean, lie, rely, rest (on, self), stay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6258}/[H6256]', 'inflected', 'heb', 'עַתָּה', '["ʻattâh"]', '["from/ now","more than/ now"]', '["adv"]', 'at this time, whether adverb, conjunction or expletive henceforth, now, straightway, this time, whereas.', 'from 6256;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4115}/[H2015]', 'inflected', 'heb', 'מַהְפֶּכֶת', '["mahpeketh"]', '["the/ stock[s]"]', '["n-f"]', 'a wrench, i.e. the stocks prison, stocks.', 'from 2015;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2197}/[H2196]', 'inflected', 'heb', 'זַעַף', '["zaʻaph"]', '["in/ a rage","with/ rage of"]', '["n-m"]', 'anger indignation, rage(-ing), wrath.', 'from 2196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2456}/[H2470]', 'inflected', 'heb', 'חָלָא', '["châlâʼ"]', '["and/ he became sick"]', '["v"]', 'to be sick be diseased.', 'a primitive root (compare 2470);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2483}/H9023/[H2470]', 'inflected', 'heb', 'חֳלִי', '["chŏlîy"]', '["in/ sickness/ his"]', '["n-m"]', 'malady, anxiety, calamity disease, grief, (is) sick(-ness).', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7495}/[H7495]', 'inflected', 'heb', 'רָפָא', '["râphâʼ"]', '["<in> the/ physicians"]', '["v"]', 'properly, to mend (by stitching), i.e. (figuratively) to cure cure, (cause to) heal, physician, repair, × thoroughly, make whole. See 7503.', 'or רָפָה; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4904}/[H7901]', 'inflected', 'heb', 'מִשְׁכָּב', '["mishkâb"]', '["in the/ lying place"]', '["n-m"]', 'a bed (figuratively, a bier); abstractly, sleep; by euphemism, carnal intercourse bed(-chamber), couch, lieth (lying) with.', 'from 7901;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2177}/[H2109]', 'inflected', 'heb', 'זַן', '["zan"]', '["and/ kinds"]', '["n-m"]', 'properly, nourished (or fully developed), i.e. a form or sort divers kinds, × all manner of store.', 'from 2109;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4842}/[H7543]', 'inflected', 'heb', 'מִרְקַחַת', '["mirqachath"]', '["as/ ointment of"]', '["n-f"]', 'an aromatic unguent; also an unguent-pot prepared by the apothecaries'' art, compound, ointment.', 'from 7543;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3966}\/[H181]', 'inflected', 'heb', 'מְאֹד', '["mᵉʼôd"]', '["<to>/ muchness"]', '["a"]', 'properly, vehemence, i.e. (with or without preposition) vehemently; by implication, wholly, speedily, etc. (often with other words as an intensive or superlative; especially when repeated) diligently, especially, exceeding(-ly), far, fast, good, great(-ly), × louder and louder, might(-ily, -y), (so) much, quickly, (so) sore, utterly, very ( much, sore), well.', 'from the same as 181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5892B}/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["and/ in/ [the] cities of"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4687}/H9023/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["and/ in/ commandments/ his"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3063G}\/[H3034]', 'inflected', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["from/ Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8269}/H9023/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["<to>/ officials/ his"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1134}/[H1121]', 'inflected', 'heb', 'בֶּן־חַיִל', '["Ben-Chayil"]', '["<to>/ Ben-"]', '["n-pr-m"]', 'Ben-Chail, an Israelite Ben-hail.', 'from 1121 and 2428; son of might;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1134}/[H1121]', 'lemma', 'heb', 'בֶּן־חַיִל', '["Ben-Chayil"]', '["Hail"]', '["n-pr-m"]', 'Ben-Chail, an Israelite Ben-hail.', 'from 1121 and 2428; son of might;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5662N}/[H5647]', 'inflected', 'heb', 'עֹבַדְיָה', '["ʻÔbadyâh"]', '["and/ <to>/ Obadiah"]', '["n-pr-m"]', 'Obadjah, the name of thirteen Israelites Obadiah.', 'or עֹבַדְיָהוּ; active participle of 5647 and 3050; serving Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2148H}/[H2142]', 'inflected', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["and/ <to>/ Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5417L}/[H5414]', 'inflected', 'heb', 'נְתַנְאֵל', '["Nᵉthanʼêl"]', '["and/ <to>/ Nethanel"]', '["n-pr-m"]', 'Nethanel, the name of ten Israelites Nethaneel.', 'from 5414 and 410; given of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4322G}/[H4320]', 'inflected', 'heb', 'מִיכָיָהוּ', '["Mîykâyâhûw"]', '["and/ <to>/ Micaiah"]', '["n-pr-m"]', 'Mikajah, the name of an Israelite and an Israelitess Michaiah.', 'for 4320;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8098J}/[H8085]', 'lemma', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5418I}/[H5414]', 'inflected', 'heb', 'נְתַנְיָה', '["Nᵉthanyâh"]', '["and/ Nethaniah"]', '["n-pr-m"]', 'Nethanjah, the name of four Israelites Nethaniah.', 'or נְתַנְיָהוּ; from 5414 and 3050; given of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2069L}/[H2064]', 'inflected', 'heb', 'זְבַדְיָה', '["Zᵉbadyâh"]', '["and/ Zebadiah"]', '["n-pr-m"]', 'Zebadjah, the name of nine Israelites Zebadiah.', 'or זְבַדְיָהוּ; from 2064 and 3050; Jah has given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6214H}/[H6213]', 'inflected', 'heb', 'עֲשָׂהאֵל', '["ʻĂsâhʼêl"]', '["and/ Asahel"]', '["n-pr-m"]', 'Asahel, the name of four Israelites Asahel.', 'from 6213 and 410; God has made;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8070H}/[H8034]', 'inflected', 'heb', 'שְׁמִירָמוֹת', '["Shᵉmîyrâmôwth"]', '["and/ Shemiramoth"]', '["n-pr-m"]', 'Shemiramoth, the name of two Israelites Shemiramoth.', 'or שְׁמָרִימוֹת; probably from 8034 and plural of 7413; name of heights;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3083L}/[H3068]', 'inflected', 'heb', 'יְהוֹנָתָן', '["Yᵉhôwnâthân"]', '["and/ Jonathan"]', '["n-pr-m"]', 'Jehonathan, the name of four Israelites Jonathan. Compare 3129.', 'from 3068 and 5414; Jehovah-given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0138H}/[H113]', 'inflected', 'heb', 'אֲדֹנִיָּה', '["ʼĂdônîyâh"]', '["and/ Adonijah"]', '["n-pr-m"]', 'Adonijah, the name of three Israelites Adonijah.', 'original (prolonged) אֲדֹנִיָּהוּ ; from 113 and 3050; lord (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2900G}/[H2896]', 'inflected', 'heb', 'טוֹבִיָּה', '["Ṭôwbîyâh"]', '["and/ Tobijah"]', '["n-pr-m"]', 'Tobijah, the name of three Israelites and of one Samaritan Tobiah, Tobijah.', 'or טוֹבִיָּהוּ; from 2896 and 3050; goodness of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2899}/[H2896]', 'inflected', 'heb', 'טוֹב אֲדֹנִיָּהוּ', '["Ṭôwb ʼĂdônîyâhûw"]', '["and/ Tob-"]', '["n-pr-m"]', 'Tob-Adonijah, an Israelite Tob-adonijah.', 'from 2896 and 138; pleasing (to) Adonijah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2899}/[H2896]', 'lemma', 'heb', 'טוֹב אֲדֹנִיָּהוּ', '["Ṭôwb ʼĂdônîyâhûw"]', '["Adonijah"]', '["n-pr-m"]', 'Tob-Adonijah, an Israelite Tob-adonijah.', 'from 2896 and 138; pleasing (to) Adonijah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0476K}/[H410]', 'lemma', 'heb', 'אֱלִישָׁמָע', '["ʼĔlîyshâmâʻ"]', '["Elishama"]', '["n-pr-m"]', 'Elishama, the name of seven Israelites Elishama.', 'from 410 and 8085; God of hearing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3088H}/[H3068]', 'inflected', 'heb', 'יְהוֹרָם', '["Yᵉhôwrâm"]', '["and/ Jehoram"]', '["n-pr-m"]', 'Jehoram, the name of a Syrian and of three Israelites Jehoram, Joram. Compare 3141.', 'from 3068 and 7311; Jehovah-raised;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6163B}/[H6152]', 'inflected', 'heb', 'עֲרָבִי', '["ʻĂrâbîy"]', '["the/ Arab","the/ Arabs"]', '["n a"]', 'an Arabian or inhabitant of Arab (i.e. Arabia) Arabian.', 'or עַרְבִי; patrial from 6152;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1003}/[H1002]', 'lemma', 'heb', 'בִּירָנִית', '["bîyrânîyth"]', '["fortresses"]', '["n-f"]', 'a fortress castle.', 'from 1002;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4399}/[H4397]', 'inflected', 'heb', 'מְלָאכָה', '["mᵉlâʼkâh"]', '["and/ property"]', '["n-f"]', 'properly, deputyship, i.e. ministry; generally, employment (never servile) or work (abstractly or concretely); also property (as the result of labor) business, cattle, industrious, occupation, ( -pied), officer, thing (made), use, (manner of) work((-man), -manship).', 'from the same as 4397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5734H}/[H5727]', 'lemma', 'heb', 'עַדְנָה', '["ʻAdnâh"]', '["Adnah"]', '["n-pr-m"]', 'Adnah, the name of two Israelites Adnah.', 'from 5727; pleasure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027K}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3076J}/[H3068]', 'lemma', 'heb', 'יְהוֹחָנָן', '["Yᵉhôwchânân"]', '["Jehohanan"]', '["n-pr-m"]', 'Jehochanan, the name of eight Israelites Jehohanan, Johanan. Compare 3110.', 'from 3068 and 2603; Jehovah-favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6007}/[H6006]', 'lemma', 'heb', 'עֲמַסְיָה', '["ʻĂmaçyâh"]', '["Amasiah"]', '["n-pr-m"]', 'Amasjah, an Israelite Amasiah.', 'from 6006 and 3050; Jah has loaded;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2147N}/[H2142]', 'lemma', 'heb', 'זִכְרִי', '["Zikrîy"]', '["Zikri"]', '["n-pr-m"]', 'Zicri, the name of twelve Israelites Zichri.', 'from 2142; memorable;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0450I}/[H410]', 'lemma', 'heb', 'אֶלְיָדָע', '["ʼElyâdâʻ"]', '["Eliada"]', '["n-pr-m"]', 'Eljada, the name of two Israelites and of an Aramaean leader Eliada.', 'from 410 and 3045; God (is) knowing;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4043}/[H1598]', 'inflected', 'heb', 'מָגֵן', '["mâgên"]', '["and/ a shield","and/ shield","and/ shields"]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3075I}/[H3068]', 'lemma', 'heb', 'יְהוֹזָבָד', '["Yᵉhôwzâbâd"]', '["Jehozabad"]', '["n-pr-m"]', 'Jehozabad, the name of three Israelites Jehozabad. Compare 3107.', 'from 3068 and 2064; Jehovah-endowed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6635H}\/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["war"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7093}/[H7112]', 'inflected', 'heb', 'קֵץ', '["qêts"]', '["to the/ end","to/ [the] end of"]', '["n-m"]', 'an extremity; adverbially (with prepositional prefix) after after, (utmost) border, end, (in-) finite, × process.', 'contracted from 7112;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8111}/[H8104]', 'inflected', 'heb', 'שֹׁמְרוֹן', '["Shômᵉrôwn"]', '["to/ Samaria"]', '["n-pr-loc"]', 'Shomeron, a place in Palestine Samaria.', 'from the active participle of 8104; watch-station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5971A}/H9021/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ [will be] as/ people/ your"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3117K>/H9023', 'opaque', 'heb', 'יוֹם', '["yôwm"]', '["days/ his"]', '["n-m"]', 'a day (as the warm hours), whether literal (from sunrise to sunset, or from one sunset to the next), or figurative (a space of time defined by an associated term), (often used adverb) age, always, chronicals, continually(-ance), daily, ((birth-), each, to) day, (now a, two) days (agone), elder, × end, evening, (for) ever(-lasting, -more), × full, life, as (so) long as (... live), (even) now, old, outlived, perpetually, presently, remaineth, × required, season, × since, space, then, (process of) time, as at other times, in trouble, weather, (as) when, (a, the, within a) while (that), × whole ( age), (full) year(-ly), younger.', 'from an unused root meaning to be hot;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4321G}/[H4322]', 'inflected', 'heb', 'מִיכָיְהוּ', '["Mîykâyᵉhûw"]', '["<to>/ Micaiah"]', '["n-pr-m"]', 'Mikajah, the name of three Israelites Micah, Micaiah, Michaiah.', 'or מִכָיְהוּ; (Jeremiah 36:11), abbreviated form for 4322;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4318N}/[H4320]', 'lemma', 'heb', 'מִיכָה', '["Mîykâh"]', '["O Micah"]', '["n-pr-m"]', 'Micah, the name of seven Israelites Micah, Micaiah, Michah.', 'an abbreviated form of 4320;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7451B}\/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["<to>/ evil"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8040G}/H9023/[H8071]', 'inflected', 'heb', 'שְׂמֹאול', '["sᵉmôʼwl"]', '["and/ left [hand]/ his"]', '["n-m"]', 'properly, dark (as enveloped), i.e. the north; hence (by orientation), the left hand left (hand, side).', 'or שְׂמֹאל; a primitive word (rather perhaps from the same as 8071 (by insertion of the aleph) through the idea of wrapping up);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7307G}/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["<into>/ a spirit of"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7451C}\/[H7489]', 'inflected', 'heb', 'רַע', '["raʻ"]', '["calamity","trouble"]', '["a n-m n-f"]', 'bad or (as noun) evil (natural or moral) adversity, affliction, bad, calamity, displease(-ure), distress, evil((-favouredness), man, thing), exceedingly, × great, grief(-vous), harm, heavy, hurt(-ful), ill (favoured), mark, mischief(-vous), misery, naught(-ty), noisome, not please, sad(-ly), sore, sorrow, trouble, vex, wicked(-ly, -ness, one), worse(-st), wretchedness, wrong. (Incl. feminine raaah; as adjective or noun.).', 'from 7489;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2244}/[H2245]', 'inflected', 'heb', 'חָבָא', '["châbâʼ"]', '["to/ hide yourself"]', '["v"]', 'to secrete × held, hide (self), do secretly.', 'a primitive root (compare 2245);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7725G}/H9040/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["return/ I"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3605}/H9028\/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["all of/ them"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5826}/H9033/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["he helped/ him","helpers/ his"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5496}/H9038/[H7898]', 'inflected', 'heb', 'סוּת', '["çûwth"]', '["and/ he lured/ them"]', '["v"]', 'properly, to prick, i.e. (figuratively) stimulate; by implication, to seduce entice, move, persuade, provoke, remove, set on, stir up, take away.', 'perhaps denominative from 7898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7395}/[H7392]', 'inflected', 'heb', 'רַכָּב', '["rakkâb"]', '["to the/ charioteer"]', '["n-m"]', 'a charioteer chariot man, driver of a chariot, horseman.', 'from 7392;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H7563}/[H7561]', 'inflected', 'heb', 'רָשָׁע', '["râshâʻ"]', '["¿/ <to> the/ wicked"]', '["a"]', 'morally wrong; concretely, an (actively) bad person condemned, guilty, ungodly, wicked (man), that did wrong.', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2063}/[H2088]', 'inflected', 'heb', 'זֹאת', '["zôʼth"]', '["and/ by/ this"]', '["d"]', 'this (often used adverb) hereby (-in, -with), it, likewise, the one (other, same), she, so (much), such (deed), that, therefore, these, this (thing), thus.', 'irregular feminine of 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1197H}/[H1198]', 'lemma', 'heb', 'בָּעַר', '["bâʻar"]', '["you have consumed","you have removed"]', '["v"]', 'to kindle, i.e. consume (by fire or by eating); to be (-come) brutish be brutish, bring (put, take) away, burn, (cause to) eat (up), feed, heat, kindle, set (on fire), waste.', 'a primitive root; also as denominative from 1198');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725O}/H9038/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ he turned back/ them"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1697L}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["in/ a matter","in/ a matter of"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4856}/[H5375]', 'inflected', 'heb', 'מַשֹּׂא', '["massôʼ"]', '["and/ lifting up of"]', '["n-m"]', 'partiality (as a lifting up) respect.', 'from 5375;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4727}/[H3947]', 'inflected', 'heb', 'מִקָּח', '["miqqâch"]', '["and/ taking of"]', '["n-m"]', 'reception taking.', 'from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/<H7218H>', 'inflected', 'heb', 'ומראשי', '["u./me./ra.Shei"]', '["and/ some of/ [the] heads of","and/ some of/ [the] leaders of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7379}/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["and/ for <the>/ dispute[s]"]', '["n-m"]', 'a contest (personal or legal) adversary, cause, chiding, contend(-tion), controversy, multitude (from the margin), pleading, strife, strive(-ing), suit.', 'or רִב; from 7378;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3374}/[H3373]', 'inflected', 'heb', 'יִרְאָה', '["yirʼâh"]', '["[is] in/ [the] fear of","[will be] in/ [the] fear of","in/ [the] fear of","with/ [the] fear of","with/ fear"]', '["n-f"]', 'fear (also used as infinitive); morally, reverence × dreadful, × exceedingly, fear(-fulness).', 'feminine of 3373;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0251I}/H9026/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["from/ brothers/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4687}/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["and/ commandment"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0568J}/[H559]', 'lemma', 'heb', 'אֲמַרְיָה', '["ʼĂmaryâh"]', '["Amariah"]', '["n-pr-m"]', 'Amarjah, the name of nine Israelites Amariah.', 'or prolonged אֲמַרְיָהוּ; from 559 and 3050; Jah has said (i.e. promised);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2069M}/[H2064]', 'inflected', 'heb', 'זְבַדְיָה', '["Zᵉbadyâh"]', '["and/ Zebadiah"]', '["n-pr-m"]', 'Zebadjah, the name of nine Israelites Zebadiah.', 'or זְבַדְיָהוּ; from 2064 and 3050; Jah has given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3458J}/[H8085]', 'lemma', 'heb', 'יִשְׁמָעֵאל', '["Yishmâʻêʼl"]', '["Ishmael"]', '["n-pr-m"]', 'Jishmael, the name of Abraham''s oldest son, and of five Israelites Ishmael.', 'from 8085 and 410; God will hear;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2896A}\/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["the/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H5984G}/[H5983]', 'inflected', 'heb', 'עַמּוֹנִי', '["ʻAmmôwnîy"]', '["some of/ the/ Ammonites"]', '["a"]', 'an Ammonite or (the adjective) Ammonitish Ammonite(-s).', 'patronymically from 5983;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3320}/[H3320]', 'inflected', 'heb', 'יָצַב', '["yâtsab"]', '["to/ hold ground","to/ present himself","to/ present themselves"]', '["v"]', 'to place (any thing so as to stay); reflexively, to station, offer, continue present selves, remaining, resort, set (selves), (be able to, can, with-) stand (fast, forth, -ing, still, up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2233H}/[H2232]', 'inflected', 'heb', 'זֶרַע', '["zeraʻ"]', '["to/ [the] offspring of"]', '["n-m"]', 'seed; figuratively, fruit, plant, sowing-time, posterity × carnally, child, fruitful, seed(-time), sowing-time.', 'from 2232;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157H}/H9031/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["friend/ your","friends/ your"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8196}/[H8199]', 'lemma', 'heb', 'שְׁפוֹט', '["shᵉphôwṭ"]', '["judgment"]', '["n-m"]', 'a judicial sentence, i.e. punishment judgment.', 'or שְׁפוּט; from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7458}/[H7456]', 'inflected', 'heb', 'רָעָב', '["râʻâb"]', '["and/ famine"]', '["n-m"]', 'hunger (more or less extensive) dearth, famine, famished, hunger.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6440G}/H9021/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ <to>/ before/ you"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6869B}/H9025/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["from/ distress/ our"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4124G}/[H1]', 'inflected', 'heb', 'מוֹאָב', '["Môwʼâb"]', '["and/ Moab"]', '["n-pr-m n-pr-loc"]', 'Moab, an incestuous son of Lot; also his territory and descendants Moab.', 'from a prolonged form of the prepositional prefix m- and 1; from (her [the mother''s]) father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1644G}/H9035/[H1644]', 'inflected', 'heb', 'גָּרַשׁ', '["gârash"]', '["to/ drive out/ us"]', '["v"]', 'to drive out from a possession; especially to expatriate or divorce cast up (out), divorced (woman), drive away (forth, out), expel, × surely put away, trouble, thrust out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3425}/H9021/[H3423]', 'inflected', 'heb', 'יְרֻשָּׁה', '["yᵉrushshâh"]', '["from/ possession/ your"]', '["n-f"]', 'something occupied; a conquest; also a patrimony heritage, inheritance, possession.', 'from 3423;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3423G}/H9035/[H3423]', 'inflected', 'heb', 'יָרַשׁ', '["yârash"]', '["you caused to possess/ us"]', '["v"]', 'to occupy (by driving out previous tenants, and possessing in their place); by implication, to seize, to rob, to inherit; also to expel, to impoverish, to ruin cast out, consume, destroy, disinherit, dispossess, drive(-ing) out, enjoy, expel, × without fail, (give to, leave for) inherit(-ance, -or) magistrate, be (make) poor, come to poverty, (give to, make to) possess, get (have) in (take) possession, seize upon, succeed, × utterly.', 'or יָרֵשׁ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869A}/H9025/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["eyes/ our"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121A}/H9028\/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ children/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3166J}/[H2372]', 'inflected', 'heb', 'יַחֲזִיאֵל', '["Yachăzîyʼêl"]', '["and/ Jahaziel"]', '["n-pr-m"]', 'Jachaziel, the name of five Israelites Jahaziel, Jahziel.', 'from 2372 and 410; beheld of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148I}/[H2142]', 'lemma', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1141L}/[H1129]', 'lemma', 'heb', 'בְּנָיָה', '["Bᵉnâyâh"]', '["Benaiah"]', '["n-pr-m"]', 'Benajah, the name of twelve Israelites Benaiah.', 'or בּנָיָהוּ; (prolonged) from 1129 and 3050; Jah has built;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3273J}/[H3261]', 'lemma', 'heb', 'יְעִיאֵל', '["Yᵉʻîyʼêl"]', '["Jeiel"]', '["n-pr-m"]', 'Jeiel, the name of six Israelites Jeiel, Jehiel. Compare 3262.', 'from 3261 and 410; carried away of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4983I}/[H4976]', 'lemma', 'heb', 'מַתַּנְיָה', '["Mattanyâh"]', '["Mattaniah"]', '["n-pr-m"]', 'Mattanjah, the name of ten Israelites Mattaniah.', 'or מַתַּנְיָהוּ; from 4976 and 3050; gift of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7181}/[H7181]', 'lemma', 'heb', 'קָשַׁב', '["qâshab"]', '["I have paid attention","[are] listening","[is] paying attention","[was] an attentive [one]","[who] pays attention","has he paid attention to","he has paid attention","pay attention","pay attention to","they have paid attention","they paid attention","they will pay attention","we pay attention","we will pay attention","will he pay attention?","you cause to pay attention","you had paid attention"]', '["v"]', 'to prick up the ears, i.e. hearken attend, (cause to) hear(-ken), give heed, incline, mark (well), regard.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6732}/[H6731]', 'inflected', 'heb', 'צִיץ', '["Tsîyts"]', '["<the>/ Ziz"]', '["n-pr-loc"]', 'Tsits, a place in Palestine Ziz.', 'the same as 6731; bloom;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5490}/[H5486]', 'inflected', 'heb', 'סוֹף', '["çôwph"]', '["at/ [the] end of"]', '["n-m"]', 'a termination conclusion, end, hinder participle', 'from 5486;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3385}/[H3384]', 'lemma', 'heb', 'יְרוּאֵל', '["Yᵉrûwʼêl"]', '["Jeruel"]', '["n-pr-loc"]', 'Jeruel, a place in Palestine Jeruel.', 'from 3384 and 410; founded of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4057B}/[H1696]', 'inflected', 'heb', 'מִדְבָּר', '["midbâr"]', '["into/ a wilderness","into/ a wilderness of","of the/ wilderness","to/ [the] wilderness of"]', '["n-m"]', 'a pasture (i.e. open field, whither cattle are driven); by implication, a desert; also speech (including its organs) desert, south, speech, wilderness.', 'from 1696 in the sense of driving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3318G}/H9048/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ when/ go out/ they","and/ when/ went out/ they"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5030}/H9023/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["at/ prophets/ his","in/ prophets/ his"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1927}/[H1926]', 'inflected', 'heb', 'הֲדָרָה', '["hădârâh"]', '["to/ adornment of"]', '["n-f"]', 'decoration beauty, honour.', 'feminine of 1926;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7440}/[H7442]', 'inflected', 'heb', 'רִנָּה', '["rinnâh"]', '["with/ a shout of joy"]', '["n-f"]', 'properly, a creaking (or shrill sound), i.e. shout (of joy or grief) cry, gladness, joy, proclamation, rejoicing, shouting, sing(-ing), triumph.', 'from 7442;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8416}/[H1984]', 'inflected', 'heb', 'תְּהִלָּה', '["tᵉhillâh"]', '["and/ [the] praises of","and/ praise"]', '["n-f"]', 'laudation; specifically (concretely) a hymn praise.', 'from 1984;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2763A}/[H2763]', 'inflected', 'heb', 'חָרַם', '["châram"]', '["to/ totally destroy [them]"]', '["v"]', 'to seclude; specifically (by a ban) to devote to religious uses (especially destruction); physical and reflexive, to be blunt as to the nose make accursed, consecrate, (utterly) destroy, devote, forfeit, have a flat nose, utterly (slay, make away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3615G}/H9048/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["and/ just as/ had finished/ they"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4707}/[H6822]', 'inflected', 'heb', 'מִצְפֶּה', '["mitspeh"]', '["the/ watchtower"]', '["n-m"]', 'an observatory, especially for military purposes watch tower.', 'from 6822;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0962}/[H962]', 'inflected', 'heb', 'בָּזַז', '["bâzaz"]', '["to/ despoilers","to/ plunder","to/ take as plunder"]', '["v"]', 'to plunder catch, gather, (take) for a prey, rob(-ber), spoil, take (away, spoil), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7998}/H9028/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["booty/ their","prey/ their"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7399}/[H7408]', 'inflected', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["and/ property"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6297}/[H6296]', 'inflected', 'heb', 'פֶּגֶר', '["peger"]', '["and/ [the] corpses of","and/ corpses"]', '["n-m"]', 'a carcase (as limp), whether of man or beast; figuratively, an idolatrous image carcase, corpse, dead body.', 'from 6296;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2530B}/[H2530]', 'lemma', 'heb', 'חָמַד', '["châmad"]', '["[the] precious things of","precious","precious things"]', '["v"]', 'to delight in beauty, greatly beloved, covet, delectable thing, (× great) delight, desire, goodly, lust, (be) pleasant (thing), precious (thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6010H}/[H6009]', 'inflected', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["to/ [the] valley of"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1294H}/[H1293]', 'lemma', 'heb', 'בְּרָכָה', '["Bᵉrâkâh"]', '["Berachah"]', '["n-pr-m n-pr-loc"]', 'Berakah, the name of an Israelite, and also of a valley in Palestine Berachah.', 'the same as 1293;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6010H}/[H6009]', 'lemma', 'heb', 'עֵמֶק', '["ʻêmeq"]', '["[the] valley of"]', '["n-m"]', 'a vale (i.e. broad depression) dale, vale, valley (often used as a part of proper names). See also 1025.', 'from 6009;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8055}/H9038/[H8055]', 'inflected', 'heb', 'שָׂמַח', '["sâmach"]', '["he had made rejoice/ them"]', '["v"]', 'probably to brighten up, i.e. (figuratively) be (causatively, make) blithe or gleesome cheer up, be (make) glad, (have, make) joy(-ful), be (make) merry, (cause to, make to) rejoice, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0341}/H9028/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["from/ enemies/ their"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8085G}/H9048/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["when/ heard/ they"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5439G}\/[H5437]', 'inflected', 'heb', 'סָבִיב', '["çâbîyb"]', '["[are] from/ round about","from/ round about"]', '["adv"]', '(as noun) a circle, neighbour, or environs; but chiefly (as adverb, with or without preposition) around (place, round) about, circuit, compass, on every side.', 'or (feminine) סְבִיבָה; from 5437;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0310A}/{H3651C}/[H309]', 'inflected', 'heb', 'אַחַר', '["ʼachar"]', '["and/ after/ this"]', '["adv a"]', 'properly, the hind part; generally used as an adverb or conjunction, after (in various senses) after (that, -ward), again, at, away from, back (from, -side), behind, beside, by, follow (after, -ing), forasmuch, from, hereafter, hinder end, + out (over) live, + persecute, posterity, pursuing, remnant, seeing, since, thence(-forth), when, with.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2266}/H9033/[H2266]', 'inflected', 'heb', 'חָבַר', '["châbar"]', '["and/ he allied/ himself"]', '["v"]', 'to join (literally or figuratively); specifically (by means of spells) to fascinate charm(-er), be compact, couple (together), have fellowship with, heap up, join (self, together), league.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0461L}/[H410]', 'lemma', 'heb', 'אֱלִיעֶזֶר', '["ʼĔlîyʻezer"]', '["Eliezer"]', '["n-pr-m"]', 'Eliezer, the name of a Damascene and of ten Israelites Eliezer.', 'from 410 and 5828; God of help;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1735}/[H1730]', 'lemma', 'heb', 'דּוֹדָוָהוּ', '["Dôwdâvâhûw"]', '["Dodavahu"]', '["n-pr-m"]', 'Dodavah, an Israelite Dodavah.', 'from 1730 and 3050; love of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4762G}/[H4761]', 'inflected', 'heb', 'מַרְאֵשָׁה', '["Marʼêshâh"]', '["from/ Mareshah"]', '["n-pr-loc"]', 'Mareshah, the name of two Israelites and of a place in Palestine Mareshah.', 'or מַרֵשָׁה; formed like 4761; summit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2266}/H9041/[H2266]', 'inflected', 'heb', 'חָבַר', '["châbar"]', '["as/ making alliance/ you"]', '["v"]', 'to join (literally or figuratively); specifically (by means of spells) to fascinate charm(-er), be compact, couple (together), have fellowship with, heap up, join (self, together), league.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5838Q}/[H5826]', 'lemma', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3171J}/[H2421]', 'inflected', 'heb', 'יְחִיאֵל', '["Yᵉchîyʼêl"]', '["and/ Jehiel"]', '["n-pr-m"]', 'Jechiel (or Jechavel), the name of eight Israelites Jehiel.', 'or (2 Chronicles 29:14) יְחַוְאֵל; from 2421 and 410; God will live;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2148J}/[H2142]', 'inflected', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["and/ Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5838R}/[H5826]', 'inflected', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["and/ Azariahu"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4317O}/[H4310]', 'inflected', 'heb', 'מִיכָאֵל', '["Mîykâʼêl"]', '["and/ Michael"]', '["n-pr-m"]', 'Mikael, the name of an archangel and of nine Israelites Michael.', 'from 4310 and (the prefix derivative from) 3588 and 410; who (is) like God?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8203K}/[H8199]', 'inflected', 'heb', 'שְׁפַטְיָה', '["Shᵉphaṭyâh"]', '["and/ Shephatiah"]', '["n-pr-m"]', 'Shephatjah, the name of ten Israelites Shephatiah.', 'or שְׁפַטְיָהוּ; from 8199 and 3050; Jah has judged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H2091>', 'inflected', 'heb', 'ולזהב', '["u./le./za.Hav"]', '["and/ for/ gold","and/ to/ gold"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4030}/[H4022]', 'inflected', 'heb', 'מִגְדָּנָה', '["migdânâh"]', '["and/ to/ excellent things"]', '["n-f"]', 'preciousness, i.e. a gem precious thing, present.', 'from the same as 4022;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3088G}/[H3068]', 'inflected', 'heb', 'יְהוֹרָם', '["Yᵉhôwrâm"]', '["to/ Jehoram"]', '["n-pr-m"]', 'Jehoram, the name of a Syrian and of three Israelites Jehoram, Joram. Compare 3141.', 'from 3068 and 7311; Jehovah-raised;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1060}\/[H1069]', 'inflected', 'heb', 'בְּכוֹר', '["bᵉkôwr"]', '["[was] the/ firstborn"]', '["n-m"]', 'first-born; hence, chief eldest (son), firstborn(-ling).', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8269}/H9023/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["commanders/ his","commanders/ its","officials/ his","officials/ its"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0452G}/[H410]', 'inflected', 'heb', 'אֵלִיָּה', '["ʼÊlîyâh"]', '["from/ Elijah"]', '["n-pr-m"]', 'Elijah, the name of the famous prophet and of two other Israelites Elijah, Eliah.', 'or prolonged אֵלִיָּהוּ; from 410 and 3050; God of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2181}/[H2181]', 'inflected', 'heb', 'זָנָה', '["zânâh"]', '["as/ made [them] prostitute [themselves]","like <the>/ prostitute"]', '["v"]', 'to commit adultery (usually of the female, and less often of simple fornication, rarely of involuntary ravishment); figuratively, to commit idolatry (the Jewish people being regarded as the spouse of Jehovah) (cause to) commit fornication, × continually, × great, (be an, play the) harlot, (cause to be, play the) whore, (commit, fall to) whoredom, (cause to) go a-whoring, whorish.', 'a primitive root [highly fed and therefore wanton];');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1121A}/H9021/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ on/ sons/ your"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0802H}/H9021/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ on/ wives/ your"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7399}/H9021/[H7408]', 'inflected', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["property/ your"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2483}/[H2470]', 'inflected', 'heb', 'חֳלִי', '["chŏlîy"]', '["[will be] in/ sickness<es>"]', '["n-m"]', 'malady, anxiety, calamity disease, grief, (is) sick(-ness).', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4245A}/[H2470]', 'inflected', 'heb', 'מַחֲלֶה', '["machăleh"]', '["in/ [the] sickness of"]', '["n-m"]', 'sickness disease, infirmity, sickness.', 'or (feminine) מַחֲלָה; from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4578>/H9021', 'opaque', 'heb', 'מֵעֶה', '["mêʻeh"]', '["bowels/ your","inward parts/ your"]', '["n-m"]', 'used only in plural the intestines, or (collectively) the abdomen, figuratively, sympathy; by implication, a vest; by extension the stomach, the uterus (or of men, the seat of generation), the heart (figuratively) belly, bowels, × heart, womb.', 'from an unused root probably meaning to be soft;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2483}/[H2470]', 'inflected', 'heb', 'חֳלִי', '["chŏlîy"]', '["the/ sickness"]', '["n-m"]', 'malady, anxiety, calamity disease, grief, (is) sick(-ness).', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7307J}/[H7306]', 'lemma', 'heb', 'רוּחַ', '["rûwach"]', '["[the] spirit of","spirit"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6163B}/[H6152]', 'inflected', 'heb', 'עֲרָבִי', '["ʻĂrâbîy"]', '["and/ the/ Arabs"]', '["n a"]', 'an Arabian or inhabitant of Arab (i.e. Arabia) Arabian.', 'or עַרְבִי; patrial from 6152;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1234}/H9034/[H1234]', 'inflected', 'heb', 'בָּקַע', '["bâqaʻ"]', '["and/ they broke into/ it"]', '["v"]', 'to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3059I}/[H3068]', 'lemma', 'heb', 'יְהוֹאָחָז', '["Yᵉhôwʼâchâz"]', '["Jehoahaz"]', '["n-pr-m"]', 'Jehoachaz, the name of three Israelites Jehoahaz. Compare 3099.', 'from 3068 and 270; Jehovah-seized;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4578>/H9023', 'inflected', 'heb', 'במעיו', '["be./me.''A/v"]', '["in/ bowels/ his","in/ inward parts/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2483}/[H2470]', 'inflected', 'heb', 'חֳלִי', '["chŏlîy"]', '["[is] for/ sickness","to/ a sickness"]', '["n-m"]', 'malady, anxiety, calamity disease, grief, (is) sick(-ness).', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4832}/[H7495]', 'lemma', 'heb', 'מַרְפֵּא', '["marpêʼ"]', '["[is] healing","[was] healing","[will be] healing","calmness","healing","healing of","health"]', '["n-m"]', 'properly, curative, i.e. literally (concretely) a medicine, or (abstractly) a cure; figuratively (concretely) deliverance, or (abstractly) placidity (in-)cure(-able), healing(-lth), remedy, sound, wholesome, yielding.', 'from 7495;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7093}/[H7112]', 'inflected', 'heb', 'קֵץ', '["qêts"]', '["the/ end"]', '["n-m"]', 'an extremity; adverbially (with prepositional prefix) after after, (utmost) border, end, (in-) finite, × process.', 'contracted from 7112;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8463}/[H2456]', 'inflected', 'heb', 'תַּחֲלוּא', '["tachălûwʼ"]', '["in/ diseases"]', '["n-m"]', 'a malady disease, × grievous, (that are) sick(-ness).', 'or תַּחֲלֻא; from 2456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8316}/[H8313]', 'inflected', 'heb', 'שְׂרֵפָה', '["sᵉrêphâh"]', '["like/ [the] burning of"]', '["n-f"]', 'cremation burning.', 'from 8313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6163B}/[H6152]', 'inflected', 'heb', 'עֲרָבִי', '["ʻĂrâbîy"]', '["with the/ Arabs"]', '["n a"]', 'an Arabian or inhabitant of Arab (i.e. Arabia) Arabian.', 'or עַרְבִי; patrial from 6152;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6098}/H9028/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["by/ plan[s]/ their","in/ counsel/ their"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7421}/[H761]', 'inflected', 'heb', 'רַמִּי', '["rammîy"]', '["the/ Arameans"]', '["a"]', 'a Ramite, i.e. Aramaean Syrian.', 'for 761;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5838z}', 'inflected', 'heb', 'ועזריהו', '["va./''a.zar.Ya.hu"]', '["and/ Azariah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H0430G}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["and/ from/ God"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8395}/[H947]', 'lemma', 'heb', 'תְּבוּסָה', '["tᵉbûwçâh"]', '["[the] downfall of"]', '["n-f"]', 'a treading down, i.e. ruin destruction.', 'from 947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8199}/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["when/ entered into judgment"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0274H}/[H270]', 'inflected', 'heb', 'אֲחַזְיָה', '["ʼĂchazyâh"]', '["<to>/ Ahaziah"]', '["n-pr-m"]', 'Achazjah, the name of a Jewish and an Israelite king Ahaziah.', 'or (prolonged) אֲחַזְיָהוּ ; from 270 and 3050; Jah has seized;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3920}/H9033/[H3920]', 'inflected', 'heb', 'לָכַד', '["lâkad"]', '["and/ people captured/ him"]', '["v"]', 'to catch (in a net, trap or pit); generally, to capture or occupy; also to choose (by lot); figuratively, to cohere × at all, catch (self), be frozen, be holden, stick together, take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6113}/[H6113]', 'inflected', 'heb', 'עָצָר', '["ʻâtsâr"]', '["to/ retain"]', '["v"]', 'to inclose; by analogy, to hold back; also to maintain, rule, assemble × be able, close up, detain, fast, keep (self close, still), prevail, recover, refrain, × reign, restrain, retain, shut (up), slack, stay, stop, withhold (self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4467}/[H4427]', 'inflected', 'heb', 'מַמְלָכָה', '["mamlâkâh"]', '["<to>/ [the] kingdoms of","for/ kingship"]', '["n-f"]', 'dominion, i.e. (abstractly) the estate (rule) or (concretely) the country (realm) kingdom, king''s, reign, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1696H}/[H1696]', 'inflected', 'heb', 'דָבַר', '["dâbar"]', '["and/ he has subdued","and/ she destroyed"]', '["v"]', 'perhaps properly, to arrange; but used figuratively (of words), to speak; rarely (in a destructive sense) to subdue answer, appoint, bid, command, commune, declare, destroy, give, name, promise, pronounce, rehearse, say, speak, be spokesman, subdue, talk, teach, tell, think, use (entreaties), utter, × well, × work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3090}/[H3089]', 'lemma', 'heb', 'יְהוֹשַׁבְעַת', '["Yᵉhôwshabʻath"]', '["Jehoshabeath"]', '["n-pr-f"]', 'Jehoshabath, an Israelitess Jehoshabeath.', 'a form of 3089;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5641}/H9033/[H5641]', 'inflected', 'heb', 'סָתַר', '["çâthar"]', '["and/ she hid/ him"]', '["v"]', 'to hide (by covering), literally or figuratively be absent, keep close, conceal, hide (self), (keep) secret, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5838S}/[H5826]', 'inflected', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["to/ Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3395M}/[H7355]', 'lemma', 'heb', 'יְרֹחָם', '["Yᵉrôchâm"]', '["Jeroham"]', '["n-pr-m"]', 'Jerocham, the name of seven or eight Israelites Jeroham.', 'from 7355; compassionate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3458K}/[H8085]', 'inflected', 'heb', 'יִשְׁמָעֵאל', '["Yishmâʻêʼl"]', '["and/ to/ Ishmael"]', '["n-pr-m"]', 'Jishmael, the name of Abraham''s oldest son, and of five Israelites Ishmael.', 'from 8085 and 410; God will hear;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3076K}/[H3068]', 'lemma', 'heb', 'יְהוֹחָנָן', '["Yᵉhôwchânân"]', '["Jehohanan"]', '["n-pr-m"]', 'Jehochanan, the name of eight Israelites Jehohanan, Johanan. Compare 3110.', 'from 3068 and 2603; Jehovah-favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5838T}/[H5826]', 'inflected', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["and/ to/ Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5744K}/[H5647]', 'lemma', 'heb', 'עוֹבֵד', '["ʻÔwbêd"]', '["Obed"]', '["n-pr-m"]', 'Obed, the name of five Israelites Obed.', 'active participle of 5647; serving;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4641H}/[H4639]', 'lemma', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5718J}/[H5710]', 'lemma', 'heb', 'עֲדָיָה', '["ʻĂdâyâh"]', '["Adaiah"]', '["n-pr-m"]', 'Adajah, the name of eight Israelites Adaiah.', 'or עֲדָיָהוּ; from 5710 and 3050; Jah has adorned;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0478}/[H410]', 'lemma', 'heb', 'אֱלִישָׁפָט', '["ʼĔlîyshâphâṭ"]', '["Elishaphat"]', '["n-pr-m"]', 'Elishaphat, an Israelite Elishaphat.', 'from 410 and 8199; God of judgment;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2147O}/[H2142]', 'lemma', 'heb', 'זִכְרִי', '["Zikrîy"]', '["Zikri"]', '["n-pr-m"]', 'Zicri, the name of twelve Israelites Zichri.', 'from 2142; memorable;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3247G}/[H3245]', 'inflected', 'heb', 'יְסוֹד', '["yᵉçôwd"]', '["the/ foundation"]', '["n-f"]', 'a foundation (literally or figuratively) bottom, foundation, repairing', 'from 3245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8334}/[H8334]', 'inflected', 'heb', 'שָׁרַת', '["shârath"]', '["and/ those/ [who] are serving"]', '["v"]', 'to attend as a menial or worshipper; figuratively, to contribute to minister (unto), (do) serve(-ant, -ice, -itor), wait on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7973}/H9023/[H7971]', 'inflected', 'heb', 'שֶׁלַח', '["shelach"]', '["weapon/ his"]', '["n-m"]', 'a missile of attack, i.e. spear; also (figuratively) a shoot of growth; i.e. branch dart, plant, × put off, sword, weapon.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7323G}/[H7323]', 'inflected', 'heb', 'רוּץ', '["rûwts"]', '["<the>/ couriers","the/ couriers","the/ runners","who/ were running"]', '["v"]', 'to run (for whatever reason, especially to rush) break down, divide speedily, footman, guard, bring hastily, (make) run (away, through), post.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1984B}/[H1984]', 'inflected', 'heb', 'הָלַל', '["hâlal"]', '["and/ who/ were praising"]', '["v"]', 'to be clear (orig. of sound, but usually of color); to shine; hence, to make a show, to boast; and thus to be (clamorously) foolish; to rave; causatively, to celebrate; also to stultify (make) boast (self), celebrate, commend, (deal, make), fool(-ish, -ly), glory, give (light), be (make, feign self) mad (against), give in marriage, (sing, be worthy of) praise, rage, renowned, shine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3996}/[H935]', 'inflected', 'heb', 'מָבוֹא', '["mâbôwʼ"]', '["at the/ entrance","in the/ entrance"]', '["n-m"]', 'an entrance (the place or the act); specifically sunset or the west; also (adverb with preposition) towards by which came, as cometh, in coming, as men enter into, entering, entrance into, entry, where goeth, going down, westward. Compare 4126.', 'from 935; (with or without 8121)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4191}/H9034/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["you must put to death/ her"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4191}/H9034/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ I should make die/ her","and/ they put to death/ her"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2318}/[H2318]', 'inflected', 'heb', 'חָדַשׁ', '["châdash"]', '["to/ renew"]', '["v"]', 'to be new; causatively, to rebuild renew, repair.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3389}/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["and/ from/ Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4849}/[H7561]', 'inflected', 'heb', 'מִרְשַׁעַת', '["mirshaʻath"]', '["the/ wickedness"]', '["n-f"]', 'a female wicked doer wicked woman.', 'from 7561;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7200G}/H9048/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ just as/ saw/ they"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6496}/[H6485]', 'inflected', 'heb', 'פָּקִיד', '["pâqîyd"]', '["and/ [the] officer of","and/ [the] overseer of","and/ [was] overseer"]', '["n-m"]', 'a superintendent (civil, military or religious) which had the charge, governor, office, overseer, (that) was set.', 'from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6168}/[H6168]', 'inflected', 'heb', 'עָרָה', '["ʻârâh"]', '["and/ spreading himself","so/ they may pour out"]', '["v"]', 'to be (causatively, make) bare; hence, to empty, pour out, demolish leave destitute, discover, empty, make naked, pour (out), rase, spread self, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5375G}/H9033/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ they took/ it"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3077H}/[H3068]', 'inflected', 'heb', 'יְהוֹיָדָע', '["Yᵉhôwyâdâʻ"]', '["and/ Jehoiada"]', '["n-pr-m"]', 'Jehojada, the name of three Israelites Jehoiada. Compare 3111.', 'from 3068 and 3045; Jehovah-known;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0724}/[H748]', 'lemma', 'heb', 'אֲרוּכָה', '["ʼărûwkâh"]', '["[the] healing of","[the] repair","healing"]', '["n-f"]', 'wholeness (literally or figuratively) health, made up, perfected.', 'or אֲרֻכָה; feminine passive participle of 748 (in the sense of restoring to soundness);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4971}/H9023/[H8505]', 'inflected', 'heb', 'מַתְכֹנֶת', '["mathkôneth"]', '["measurement/ its"]', '["n-f"]', 'proportion (in size, number or ingredients) composition, measure, state, tale.', 'or מַתְכֻנֶת; from 8505 in the transferred sense of measuring;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0553}/H9033/[H553]', 'inflected', 'heb', 'אָמַץ', '["ʼâmats"]', '["and/ they strengthened/ it"]', '["v"]', 'to be alert, physically (on foot) or mentally (in courage) confirm, be courageous (of good courage, stedfastly minded, strong, stronger), establish, fortify, harden, increase, prevail, strengthen (self), make strong (obstinate, speed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8335}/[H8334]', 'lemma', 'heb', 'שָׁרֵת', '["shârêth"]', '["service"]', '["n-m"]', 'service (in the Temple) minister(-ry).', 'infinitive of 8334;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3709I}/[H3721]', 'inflected', 'heb', 'כַּף', '["kaph"]', '["and/ pans"]', '["n-f"]', 'the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.', 'from 3721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3077H}\/[H3068]', 'inflected', 'heb', 'יְהוֹיָדָע', '["Yᵉhôwyâdâʻ"]', '["Jehoiada"]', '["n-pr-m"]', 'Jehojada, the name of three Israelites Jehoiada. Compare 3111.', 'from 3068 and 3045; Jehovah-known;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2204}/[H2204]', 'inflected', 'heb', 'זָקֵן', '["zâqên"]', '["and/ he became old"]', '["v"]', 'to be old aged man, be (wax) old (man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004B}/H9023\/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ house/ his"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6091}/[H6087]', 'inflected', 'heb', 'עָצָב', '["ʻâtsâb"]', '["the/ idols"]', '["n-m"]', 'an (idolatrous) image idol, image.', 'from 6087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0819}/H9028/[H817]', 'inflected', 'heb', 'אַשְׁמָה', '["ʼashmâh"]', '["in/ guilt/ their"]', '["n-f"]', 'guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering).', 'feminine of 817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725G}/H9038/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["to/ bring back/ them"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0238}\/[H241]', 'inflected', 'heb', 'אָזַן', '["ʼâzan"]', '["they gave ear"]', '["v"]', 'to broaden out the ear (with the hand), i.e. (by implication) to listen give (perceive by the) ear, hear(-ken). See 239.', 'a primitive root; probably to expand; but used only as a denominative from 241;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148w}', 'inflected', 'heb', 'זכריה', '["ze.khar.Yah"]', '["Zechariah"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4687}/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["at/ [the] commandment of","by/ [the] command of","by/ [the] commandment of"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H4191}/H9043/[H4191]', 'inflected', 'heb', 'מוּת', '["mûwth"]', '["and/ when/ dying/ he"]', '["v"]', 'to die (literally or figuratively); causatively, to kill × at all, × crying, (be) dead (body, man, one), (put to, worthy of) death, destroy(-er), (cause to, be like to, must) die, kill, necro(-mancer), × must needs, slay, × surely, × very suddenly, × in (no) wise.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1875}\/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["and/ may he require"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4705}/[H6819]', 'inflected', 'heb', 'מִצְעָר', '["mitsʻâr"]', '["with/ smallness of"]', '["n-m"]', 'petty (in size or number); adverbially, a short (time) little one (while), small.', 'from 6819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1980G}/H9048/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ when/ went/ they"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4251}/[H2470]', 'inflected', 'heb', 'מַחְלֻי', '["machluy"]', '["with/ sicknesses"]', '["n-m"]', 'a disease disease.', 'from 2470;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2066M}/[H2064]', 'lemma', 'heb', 'זָבָד', '["Zâbâd"]', '["Zabad"]', '["n-pr-m"]', 'Zabad, the name of seven Israelites Zabad.', 'from 2064; giver;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8116}/[H8113]', 'lemma', 'heb', 'שִׁמְרִית', '["Shimrîyth"]', '["Shimrith"]', '["n-pr-f"]', 'Shimrith, a Moabitess Shimrith.', 'feminine of 8113; female guard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4097}/[H1875]', 'lemma', 'heb', 'מִדְרָשׁ', '["midrâsh"]', '["[the] record of"]', '["n-m"]', 'properly, an investigation, i.e. (by implication) a treatise or elaborate compilation story.', 'from 1875;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5975G}/H9038/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ I made stand/ them","and/ he appointed/ them","and/ he established/ them","and/ he set up/ them"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6793C}/[H6791]', 'inflected', 'heb', 'צִנָּה', '["tsinnâh"]', '["and/ body shield"]', '["n-f"]', 'a hook (as pointed); also a (large) shield (as if guarding by prickliness); also cold (as piercing) buckler, cold, hook, shield, target.', 'feminine of 6791;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3782}/H9031/[H3782]', 'inflected', 'heb', 'כָּשַׁל', '["kâshal"]', '["he will overthrow/ you"]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3782}/[H3782]', 'inflected', 'heb', 'כָּשַׁל', '["kâshal"]', '["and/ to/ overthrow"]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1416}/[H1413]', 'inflected', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["to/ [the] troop[s] of","to/ troop[s]"]', '["n-m"]', 'a crowd (especially of soldiers) army, band (of men), company, troop (of robbers).', 'from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0914}/H9038/[H914]', 'inflected', 'heb', 'בָּדַל', '["bâdal"]', '["and/ he separated/ them"]', '["v"]', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9009/{H1416}/[H1413]', 'inflected', 'heb', 'גְּדוּד', '["gᵉdûwd"]', '["<to>/ the/ troop[s]"]', '["n-m"]', 'a crowd (especially of soldiers) army, band (of men), company, troop (of robbers).', 'from 1413;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1516J}/[H1466]', 'lemma', 'heb', 'גַּיְא', '["gayʼ"]', '["[the] Valley of"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7218I>', 'inflected', 'heb', 'לראש', '["le./Rosh","le./roSh"]', '["to/ [the] head of","to/ [the] top of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5553G>', 'inflected', 'heb', 'הסלע', '["ha./Sa.la''","ha./Se.la''"]', '["<the>/ cliff","the/ cliff"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3605}/H9028/[H3634]', 'inflected', 'heb', 'כֹּל', '["kôl"]', '["and/ all of/ them"]', '["n-m"]', 'properly, the whole; hence, all, any or every (in the singular only, but often in a plural sense) (in) all (manner, (ye)), altogether, any (manner), enough, every (one, place, thing), howsoever, as many as, (no-) thing, ought, whatsoever, (the) whole, whoso(-ever).', 'or (Jeremiah 33:8) כּוֹל; from 3634;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0558G}/[H553]', 'inflected', 'heb', 'אֲמַצְיָה', '["ʼĂmatsyâh"]', '["on/ Amaziah"]', '["n-pr-m"]', 'Amatsjah, the name of four Israelites Amaziah.', 'or אֲמַצְיָהוּ; from 553 and 3050; strength of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/H9005/{H3289}/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["¿/ into/ a counselor"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7843}/H9031/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["to/ destroy/ you"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6098}/H9020\/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["to/ counsel/ my"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3513G}/[H3513]', 'inflected', 'heb', 'כָּבַד', '["kâbad"]', '["to/ become heavy"]', '["v"]', 'to be heavy, i.e. in a bad sense (burdensome, severe, dull) or in a good sense (numerous, rich, honorable); causatively, to make weighty (in the same two senses) abounding with, more grievously afflict, boast, be chargeable, × be dim, glorify, be (make) glorious (things), glory, (very) great, be grievous, harden, be (make) heavy, be heavier, lay heavily, (bring to, come to, do, get, be had in) honour (self), (be) honourable (man), lade, × more be laid, make self many, nobles, prevail, promote (to honour), be rich, be (go) sore, stop.', 'or כָּבֵד; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7200M}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["and/ they looked at one another"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6437H}/[H6437]', 'inflected', 'heb', 'פָּנָה', '["pânâh"]', '["the/ Corner"]', '["v"]', 'to turn; by implication, to face, i.e. appear, look, etc. appear, at (even-) tide, behold, cast out, come on, × corner, dawning, empty, go away, lie, look, mark, pass away, prepare, regard, (have) respect (to), (re-) turn (aside, away, back, face, self), × right (early).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H6256}/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["and/ from/ [the] time"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148L}/[H2142]', 'lemma', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7200L}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["in/ [the] seeing of"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1875}/H9043/[H1875]', 'inflected', 'heb', 'דָּרַשׁ', '["dârash"]', '["seeking/ he"]', '["v"]', 'properly, to tread or frequent; usually to follow (for pursuit or search); by implication, to seek or ask; specifically to worship ask, × at all, care for, × diligently, inquire, make inquisition, (necro-) mancer, question, require, search, seek (for, out), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6743B}/H9033/[H6743]', 'inflected', 'heb', 'צָלַח', '["tsâlach"]', '["he made prosper/ him"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2996}/[H1129]', 'lemma', 'heb', 'יַבְנֶה', '["Yabneh"]', '["Jabneh"]', '["n-pr-loc"]', 'Jabneh, a place in Palestine Jabneh.', 'from 1129; a building;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5826}/H9033/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["and/ he helped/ him","and/ they helped/ him"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1485}/[H1481]', 'inflected', 'heb', 'גּוּר־בַּעַל', '["Gûwr-Baʻal"]', '["in/ Gur"]', '["n-pr-loc"]', 'Gur-Baal, a place in Arabia Gur-baal.', 'from 1481 and 1168; dwelling of Baal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1485}/[H1481]', 'lemma', 'heb', 'גּוּר־בַּעַל', '["Gûwr-Baʻal"]', '["Baal"]', '["n-pr-loc"]', 'Gur-Baal, a place in Arabia Gur-baal.', 'from 1481 and 1168; dwelling of Baal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4586G}/[H4584]', 'inflected', 'heb', 'מְעוּנִי', '["Mᵉʻûwnîy"]', '["and/ the/ Meunites"]', '["n-pr-m"]', 'a Meunite, or inhabitant of Maon (only in plural) Mehunim(-s), Meunim.', 'or מְעִינִי; probably patrial from 4584;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1516M}/[H1466]', 'inflected', 'heb', 'גַּיְא', '["gayʼ"]', '["the/ valley"]', '["n"]', 'a gorge (from its lofty sides; hence, narrow, but not a gully or winter-torrent) valley.', 'or (shortened) גַּי; probably (by transmutation) from the same root as 1466 (abbreviated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4740G}/[H7106]', 'inflected', 'heb', 'מַקְצוֹעַ', '["maqtsôwaʻ"]', '["the/ buttress"]', '["n-m"]', 'an angle or recess corner, turning.', 'or מַקְצֹעַ; or (feminine) מַקְצֹעָה; from 7106 in the denominative sense of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2672}/[H2672]', 'inflected', 'heb', 'חָצַב', '["châtsab"]', '["and/ he dug"]', '["v"]', 'to cut or carve (wood, stone or other material); by implication, to hew, split, square, quarry, engrave cut, dig, divide, grave, hew (out, -er), made, mason.', 'or חָצֵב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4334}/[H3474]', 'inflected', 'heb', 'מִישׁוֹר', '["mîyshôwr"]', '["and/ in the/ plain","and/ in/ uprightness"]', '["n-m"]', 'a level, i.e. a plain (often used (with the article prefix) as a proper name of certain districts); figuratively, concord; also straightness, i.e. (figuratively) justice (sometimes adverbially, justly) equity, even place, plain, right(-eously), (made) straight, uprightness.', 'or מִישֹׁר; from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0406>', 'opaque', 'heb', 'אִכָּר', '["ʼikkâr"]', '["a farmer","farmers"]', '["n-m"]', 'a farmer husbandman, ploughman.', 'from an unused root meaning to dig;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3755}/[H3754]', 'inflected', 'heb', 'כֹּרֵם', '["kôrêm"]', '["and/ vinedressers"]', '["v"]', 'a vinedresser vine dresser (as one or two words).', 'active participle of an imaginary denominative from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3759}/[H3754]', 'inflected', 'heb', 'כַּרְמֶל', '["karmel"]', '["and/ in the/ orchards"]', '["n-m"]', 'a planted field (garden, orchard, vineyard or park); by implication, garden produce full (green) ears (of corn), fruitful field (place), plentiful (field).', 'from 3754;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3273K}/[H3261]', 'lemma', 'heb', 'יְעִיאֵל', '["Yᵉʻîyʼêl"]', '["Jeiel"]', '["n-pr-m"]', 'Jeiel, the name of six Israelites Jeiel, Jehiel. Compare 3262.', 'from 3261 and 410; carried away of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4641I}/[H4639]', 'inflected', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["and/ Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2608Q}/[H2603]', 'lemma', 'heb', 'חֲנַנְיָה', '["Chănanyâh"]', '["Hananiah"]', '["n-pr-m"]', 'Chananjah, the name of thirteen Israelites Hananiah.', 'or חֲנַנְיָהוּ; from 2603 and 3050; Jah has favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1368}/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["[belongs] to the/ mighty [men]","of/ mighty [men] of"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027H}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7198}/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["and/ bow","and/ bows"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0068G}/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["and/ <into>/ a stone of","and/ <to>/ stones of","and/ for/ stone[s]","and/ to <the>/ stone"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7050A}/[H7049]', 'lemma', 'heb', 'קֶלַע', '["qelaʻ"]', '["a sling","slings"]', '["n-m"]', 'a sling; also a (door) screen (as if slung across), or the valve (of the door) itself hanging, leaf, sling.', 'from 7049;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2810}/[H2803]', 'lemma', 'heb', 'חִשָּׁבוֹן', '["chishshâbôwn"]', '["schemes","war engines of"]', '["n-m"]', 'a contrivance, i.e. actual (a warlike machine) or mental (a machination) engine, invention.', 'from 2803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6438H}/[H6434]', 'inflected', 'heb', 'פִּנָּה', '["pinnâh"]', '["the/ corner","the/ corners"]', '["n-f"]', 'an angle; by implication, a pinnacle; figuratively, a chieftain bulwark, chief, corner, stay, tower.', 'feminine of 6434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3384A}/[H3384]', 'inflected', 'heb', 'יָרָה', '["yârâh"]', '["to/ shoot"]', '["v"]', 'properly, to flow as water (i.e. to rain); transitively, to lay or throw (especially an arrow, i.e. to shoot); figuratively, to point out (as if by aiming the finger), to teach ( ) archer, cast, direct, inform, instruct, lay, shew, shoot, teach(-er,-ing), through.', 'or (2 Chronicles 26:15) יָרָא; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2671}/[H2686]', 'inflected', 'heb', 'חֵץ', '["chêts"]', '["<in> the/ arrows","with <the>/ arrows"]', '["n-m"]', 'properly, a piercer, i.e. an arrow; by implication, a wound; figuratively, (of God) thunder-bolt; the shaft of a spear archer, arrow, dart, shaft, staff, wound.', 'from 2686; also by interchange for 6086');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1361}/[H1361]', 'lemma', 'heb', 'גָּבַהּ', '["gâbahh"]', '["I raise up","[one who] makes high","does it make high [its flight]","exalt","it has been haughty","it has been lofty","it is haughty","it was haughty","it was tall","make high","they are haughty","they are high","they make high","they may be lifted up","you be haughty","you were tall","you will make high"]', '["v"]', 'to soar, i.e. be lofty; figuratively, to be haughty exalt, be haughty, be (make) high(-er), lift up, mount up, be proud, raise up great height, upward.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5838N}/[H5826]', 'lemma', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6942G}/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["<the>/ consecrated","the/ consecrated [one]","who/ are consecrated","who/ consecrate themselves"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2196}/[H2196]', 'inflected', 'heb', 'זָעַף', '["zâʻaph"]', '["and/ he was enraged"]', '["v"]', 'properly, to boil up, i.e. (figuratively) to be peevish or angry fret, sad, worse liking, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3027G}/H9023/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["and/ [was] in/ hand/ his"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4730}/[H4729]', 'lemma', 'heb', 'מִקְטֶרֶת', '["miqṭereth"]', '["a censer"]', '["n-f"]', 'something to fume (incense) in, i.e. a coal-pan censer.', 'feminine of 4729;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2196}/H9043/[H2196]', 'inflected', 'heb', 'זָעַף', '["zâʻaph"]', '["and/ when/ enraging/ he"]', '["v"]', 'properly, to boil up, i.e. (figuratively) to be peevish or angry fret, sad, worse liking, be wroth.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6883}/[H6879]', 'inflected', 'heb', 'צָרַעַת', '["tsâraʻath"]', '["and/ <the>/ skin disease"]', '["n-f"]', 'leprosy leprosy.', 'from 6879;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0926}/H9033/[H926]', 'inflected', 'heb', 'בָּהַל', '["bâhal"]', '["and/ they hastened/ him"]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1765}/[H1765]', 'lemma', 'heb', 'דָּחַף', '["dâchaph"]', '["being hasty","he hurried himself"]', '["v"]', 'to urge, i.e. hasten (be) haste(-ned), pressed on.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5060}/H9033/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["he had struck/ him"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6900}/[H6912]', 'inflected', 'heb', 'קְבוּרָה', '["qᵉbûwrâh"]', '["<the>/ grave"]', '["n-f"]', 'sepulture; (concretely) a sepulchre burial, burying place, grave, sepulchre.', 'or קְבֻרָה; feminine passive participle of 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6077}/[H6076]', 'inflected', 'heb', 'עֹפֶל', '["ʻÔphel"]', '["<the>/ Ophel"]', '["n-pr-loc"]', 'Ophel, a ridge in Jerusalem Ophel.', 'the same as 6076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2793H}/[H2790]', 'inflected', 'heb', 'חֹרֶשׁ', '["chôresh"]', '["and/ in the/ wooded areas"]', '["n-m"]', 'a forest (perhaps as furnishing the material for fabric) bough, forest, shroud, wood.', 'from 2790;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3559J}/[H3559]', 'lemma', 'heb', 'כּוּן', '["kûwn"]', '["he had directed"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7633}/[H7628]', 'lemma', 'heb', 'שִׁבְיָה', '["shibyâh"]', '["a group of captives","captivity"]', '["n-f"]', 'exile (abstractly or concretely and collectively) captives(-ity).', 'feminine of 7628;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5800A}/H9048/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["because/ had forsaken/ they"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2147P}/[H2142]', 'lemma', 'heb', 'זִכְרִי', '["Zikrîy"]', '["Zikri"]', '["n-pr-m"]', 'Zicri, the name of twelve Israelites Zichri.', 'from 2142; memorable;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4641J}/[H4639]', 'lemma', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5840J}/[H5828]', 'lemma', 'heb', 'עַזְרִיקָם', '["ʻAzrîyqâm"]', '["Azrikam"]', '["n-pr-m"]', 'Azrikam, the name of four Israelites Azrikam.', 'from 5828 and active participle of 6965; help of an enemy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0511N}/[H410]', 'lemma', 'heb', 'אֶלְקָנָה', '["ʼElqânâh"]', '["Elkanah"]', '["n-pr-m"]', 'Elkanah, the name of several Israelites Elkanah.', 'from 410 and 7069; God has obtained;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0251H}/H9028/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["of/ brothers/ their","of/ relatives/ their"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8111}\/[H8104]', 'inflected', 'heb', 'שֹׁמְרוֹן', '["Shômᵉrôwn"]', '["to/ Samaria"]', '["n-pr-loc"]', 'Shomeron, a place in Palestine Samaria.', 'from the active participle of 8104; watch-station;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5752H}/[H5749]', 'lemma', 'heb', 'עוֹדֵד', '["ʻÔwdêd"]', '["[was] Oded"]', '["n-pr-m"]', 'Oded, the name of two Israelites Oded.', 'or עֹדֵד; from 5749; reiteration;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H8064>', 'inflected', 'heb', 'לשמים', '["la./sha.Ma.yim"]', '["<to> the/ heavens","to the/ heavens"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3533}/[H3533]', 'inflected', 'heb', 'כָּבַשׁ', '["kâbash"]', '["to/ subjugate","to/ violate"]', '["v"]', 'to tread down; hence, negatively, to disregard; positively, to conquer, subjugate, violate bring into bondage, force, keep under, subdue, bring into subjection.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7633}/[H7628]', 'inflected', 'heb', 'שִׁבְיָה', '["shibyâh"]', '["the/ group of captives"]', '["n-f"]', 'exile (abstractly or concretely and collectively) captives(-ity).', 'feminine of 7628;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0251H}/H9026/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["from/ relatives/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5921A}/H9036\/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["[is] towards/ you","on/ you"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H7218H>', 'inflected', 'heb', 'מראשי', '["me./ra.Shei"]', '["[were] of/ [the] leaders of","some of/ [the] leaders of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5838O}/[H5826]', 'lemma', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3076L}/[H3068]', 'lemma', 'heb', 'יְהוֹחָנָן', '["Yᵉhôwchânân"]', '["Jehohanan"]', '["n-pr-m"]', 'Jehochanan, the name of eight Israelites Jehohanan, Johanan. Compare 3110.', 'from 3068 and 2603; Jehovah-favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1296J}/[H1290]', 'lemma', 'heb', 'בֶּרֶכְיָה', '["Berekyâh"]', '["Berekiah"]', '["n-pr-m"]', 'Berekjah, the name of six Israelites Berachiah, Berechiah.', 'or בֶּרֶכְיָהוּ; from 1290 and 3050; knee (i.e. blessing) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4919G}/[H7999]', 'lemma', 'heb', 'מְשִׁלֵּמוֹת', '["Mᵉshillêmôwth"]', '["Meshillemoth"]', '["n-pr-m"]', 'Meshillemoth, an Israelite Meshillemoth. Compare 4921.', 'plural from 7999; reconciliations');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3169G}/[H3388]', 'inflected', 'heb', 'יְחִזְקִיָּה', '["Yᵉchizqîyâh"]', '["and/ Jechizkiah"]', '["n-pr-m"]', 'Jechizkijah, the name of five Israelites Hezekiah, Jehizkiah. Compare 2396.', 'or יְחִזְקִיָּהוּ; from 3388 and 3050; strengthened of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7967N}/[H7966]', 'lemma', 'heb', 'שַׁלּוּם', '["Shallûwm"]', '["Shallum"]', '["n-pr-m"]', 'Shallum, the name of fourteen Israelites Shallum.', 'or (shorter) שַׁלֻּם; the same as 7966;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6021H}/[H6006]', 'inflected', 'heb', 'עֲמָשָׂא', '["ʻĂmâsâʼ"]', '["and/ Amasa"]', '["n-pr-m"]', 'Amasa, the name of two Israelites Amasa.', 'from 6006; burden;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2311}/[H2309]', 'lemma', 'heb', 'חַדְלַי', '["Chadlay"]', '["Hadlai"]', '["n-pr-m"]', 'Chadlai, an Israelite Hadlai.', 'from 2309; idle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0819}/H9025/[H817]', 'inflected', 'heb', 'אַשְׁמָה', '["ʼashmâh"]', '["guilt/ our"]', '["n-f"]', 'guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering).', 'feminine of 817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2740}/[H2734]', 'inflected', 'heb', 'חָרוֹן', '["chârôwn"]', '["and/ [the] burning of","and/ burning of"]', '["n-m"]', 'a burning of anger sore displeasure, fierce(-ness), fury, (fierce) wrath(-ful).', 'or (shortened) חָרֹן; from 2734;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0961}/[H957]', 'inflected', 'heb', 'בִּזָּה', '["bizzâh"]', '["the/ plunder"]', '["n-f"]', 'booty prey, spoil.', 'feminine of 957;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4636}/H9028/[H6191]', 'inflected', 'heb', 'מַעֲרֹם', '["maʻărôm"]', '["naked people/ their"]', '["n-m"]', 'bare naked.', 'from 6191, in the sense of stripping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5274B}/H9038/[H5275]', 'inflected', 'heb', 'נָעַל', '["nâʻal"]', '["and/ they shod/ them"]', '["v"]', 'properly, to fasten up, i.e. with a bar or cord; hence, to sandal, i.e. furnish with slippers bolt, inclose, lock, shoe, shut up.', 'a primitive root; also denominative from 5275');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0398}/H9038/[H398]', 'inflected', 'heb', 'אָכַל', '["ʼâkal"]', '["and/ I ate/ them","and/ I will make eat/ them","and/ it consumed/ them","and/ it devoured/ them","and/ it will consume/ them","and/ they fed/ them","and/ they will consume/ them"]', '["v"]', 'to eat (literally or figuratively) × at all, burn up, consume, devour(-er, up), dine, eat(-er, up), feed (with), food, × freely, × in...wise(-deed, plenty), (lay) meat, × quite.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8248H}/H9038/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["and/ I will give to drink/ them","and/ I will make drink/ them","and/ they gave to drink/ them","and/ you have made drink/ them"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5480}/H9038/[H5480]', 'inflected', 'heb', 'סוּךְ', '["çûwk"]', '["and/ they anointed/ them"]', '["v"]', 'properly, to smear over (with oil), i.e. anoint anoint (self), × at all.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3782}/[H3782]', 'lemma', 'heb', 'כָּשַׁל', '["kâshal"]', '["[is one who] stumbles","[one who] stumbled","[one who] stumbles","[the] stumbling","[was one who] stumbled","certainly <to stumble>","he has made feeble","he will stumble","it has failed","it has stumbled","it will stumble","overthrown","stumbling","they bring injury","they have staggered","they stumble","they stumbled","they will stumble","we have stumbled","you have caused to stumble","you have stumbled","you will cause to stumble","you will stumble"]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1450}/[H1448]', 'inflected', 'heb', 'גְּדֵרוֹת', '["Gᵉdêrôwth"]', '["<the>/ Gederoth"]', '["n-pr-loc"]', 'Gederoth, a place in Palestine Gederoth.', 'plural of 1448; walls;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1579>', 'opaque', 'heb', 'גִּמְזוֹ', '["Gimzôw"]', '["Gimzo"]', '["n-pr-loc"]', 'Gimzo, a place in Palestine Gimzo.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4603}/[H4603]', 'inflected', 'heb', 'מָעַל', '["mâʻal"]', '["and/ he had acted unfaithfully"]', '["v"]', 'properly, to cover up; used only figuratively, to act covertly, i.e. treacherously transgress, (commit, do a) trespass(-ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388G}/H9033/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["I will make firm on/ him","he strengthened/ him"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3782}/H9033/[H3782]', 'inflected', 'heb', 'כָּשַׁל', '["kâshal"]', '["<into>/ causing overthrow/ his"]', '["v"]', 'to totter or waver (through weakness of the legs, especially the ankle); by implication, to falter, stumble, faint or fall bereave (from the margin), cast down, be decayed, (cause to) fail, (cause, make to) fall (down, -ing), feeble, be (the) ruin(-ed, of), (be) overthrown, (cause to) stumble, × utterly, be weak.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697K}/H9023/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["matters/ his"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6913}/[H6912]', 'inflected', 'heb', 'קֶבֶר', '["qeber"]', '["to the/ grave","to/ [the] grave<s>","to/ [the] graves of"]', '["n-m"]', 'a sepulchre burying place, grave, sepulchre.', 'or (feminine) קִבְרָה; from 6912;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0029N}/[H1]', 'lemma', 'heb', 'אֲבִיָּה', '["ʼĂbîyâh"]', '["[was] Abijah"]', '["n-pr-m"]', 'Abijah, the name of several Israelite men and two Israelitesses Abiah, Abijah.', 'or prolonged אֲבִיָּהוּ ; from 1 and 3050; father (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0622}/H9038/[H622]', 'inflected', 'heb', 'אָסַף', '["ʼâçaph"]', '["and/ he gathered/ them"]', '["v"]', 'to gather for any purpose; hence, to receive, take away, i.e. remove (destroy, leave behind, put up, restore, etc.) assemble, bring, consume, destroy, felch, gather (in, together, up again), × generally, get (him), lose, put all together, receive, recover (another from leprosy), (be) rereward, × surely, take (away, into, up), × utterly, withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7339}/[H7337]', 'inflected', 'heb', 'רְחֹב', '["rᵉchôb"]', '["to/ [the] open place of"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4217H}/[H2224]', 'inflected', 'heb', 'מִזְרָח', '["mizrâch"]', '["the/ east"]', '["n-m"]', 'sunrise, i.e. the east east (side, -ward), (sun-) rising (of the sun).', 'from 2224;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5800A}/H9033/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["and/ they forsook/ him"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H4908}/[H7931]', 'inflected', 'heb', 'מִשְׁכָּן', '["mishkân"]', '["away from/ [the] tabernacle of"]', '["n-m"]', 'a residence (including a shepherd''s hut, the lair of animals, figuratively, the grave; also the Temple); specifically, the Tabernacle (properly, its wooden walls) dwelleth, dwelling (place), habitation, tabernacle, tent.', 'from 7931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8322}/[H8319]', 'inflected', 'heb', 'שְׁרֵקָה', '["shᵉrêqâh"]', '["and/ into/ a hissing"]', '["n-f"]', 'a derision hissing.', 'from 8319;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1121A}/H9025/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ sons/ our"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1323G}/H9025/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ daughters/ our"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0802H}/H9025/[H376]', 'inflected', 'heb', 'אִשָּׁה', '["ʼishshâh"]', '["and/ wives/ our"]', '["n-f"]', 'a woman (adulter) ess, each, every, female, × many, none, one, together, wife, woman. Often unexpressed in English.', 'feminine of 376 or 582; irregular plural, נָשִׁים;(used in the same wide sense as 582)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1961}/[H1933]', 'inflected', 'heb', 'הָיָה', '["hâyâh"]', '["and/ to/ be"]', '["v"]', 'to exist, i.e. be or become, come to pass (always emphatic, and not a mere copula or auxiliary) beacon, × altogether, be(-come), accomplished, committed, like), break, cause, come (to pass), do, faint, fall, follow, happen, × have, last, pertain, quit (one-) self, require, × use.', 'a primitive root (compare 1933);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6999H}\/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["and/ makers of smoke"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4287G}/[H4229]', 'lemma', 'heb', 'מַחַת', '["Machath"]', '["Mahath"]', '["n-pr-m"]', 'Machath, the name of two Israelites Mahath.', 'probably from 4229; erasure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6022J}/[H6006]', 'lemma', 'heb', 'עֲמָשַׂי', '["ʻĂmâsay"]', '["Amasai"]', '["n-pr-m"]', 'Amasai, the name of three Israelites Amasai.', 'from 6006; burdensome;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3100Q}/[H3068]', 'inflected', 'heb', 'יוֹאֵל', '["Yôwʼêl"]', '["and/ Joel"]', '["n-pr-m"]', 'Joel, the name of twelve Israelites Joel.', 'from 3068 and 410; Jehovah (is his) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5838U}/[H5826]', 'lemma', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7027I}/[H6983]', 'lemma', 'heb', 'קִישׁ', '["Qîysh"]', '["Kish"]', '["n-pr-m"]', 'Kish, the name of five Israelites Kish.', 'from 6983; a bow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5660H}/[H5647]', 'lemma', 'heb', 'עַבְדִּי', '["ʻAbdîy"]', '["Abdi"]', '["n-pr-m"]', 'Abdi, the name of two Israelites Abdi.', 'from 5647; serviceable;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5838V}/[H5826]', 'inflected', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["and/ Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3094H}/[H1984]', 'lemma', 'heb', 'יְהַלֶּלְאֵל', '["Yᵉhallelʼêl"]', '["Jehallelel"]', '["n-pr-m"]', 'Jehallelel, the name of two Israelites Jehalellel, Jehalelel.', 'from 1984 and 410; praising God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3098K}/[H3068]', 'lemma', 'heb', 'יוֹאָח', '["Yôwʼâch"]', '["Joah"]', '["n-pr-m"]', 'Joach, the name of four Israelites Joah.', 'from 3068 and 251; Jehovah-brothered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2155H}/[H2154]', 'lemma', 'heb', 'זִמָּה', '["Zimmâh"]', '["Zimmah"]', '["n-pr-m"]', 'Zimmah, the name of two Israelites Zimmah.', 'the same as 2154;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5731A}/[H5730]', 'inflected', 'heb', 'עֵדֶן', '["ʻÊden"]', '["and/ Eden"]', '["n-pr-m n-pr-loc"]', 'Eden, the region of Adam''s home Eden.', 'the same as 5730 (masculine);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3098L}/[H3068]', 'lemma', 'heb', 'יוֹאָח', '["Yôwʼâch"]', '["Joah"]', '["n-pr-m"]', 'Joach, the name of four Israelites Joah.', 'from 3068 and 251; Jehovah-brothered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8113J}/[H8105]', 'lemma', 'heb', 'שִׁמְרִי', '["Shimrîy"]', '["Shimri"]', '["n-pr-m"]', 'Shimri, the name of four Israelites Shimri.', 'from 8105 in its original sense; watchful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3273L}/[H3261]', 'inflected', 'heb', 'יְעִיאֵל', '["Yᵉʻîyʼêl"]', '["and/ Jeiel"]', '["n-pr-m"]', 'Jeiel, the name of six Israelites Jeiel, Jehiel. Compare 3262.', 'from 3261 and 410; carried away of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148M}/[H2142]', 'lemma', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4983J}\/[H4976]', 'inflected', 'heb', 'מַתַּנְיָה', '["Mattanyâh"]', '["and/ Mattaniah"]', '["n-pr-m"]', 'Mattanjah, the name of ten Israelites Mattaniah.', 'or מַתַּנְיָהוּ; from 4976 and 3050; gift of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3171K}/[H2421]', 'lemma', 'heb', 'יְחִיאֵל', '["Yᵉchîyʼêl"]', '["Jehiel"]', '["n-pr-m"]', 'Jechiel (or Jechavel), the name of eight Israelites Jehiel.', 'or (2 Chronicles 29:14) יְחַוְאֵל; from 2421 and 410; God will live;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8096P}\/[H8088]', 'inflected', 'heb', 'שִׁמְעִי', '["Shimʻîy"]', '["and/ Shimei"]', '["n-pr-m"]', 'Shimi, the name of twenty Israelites Shimeah (from the margin), Shimei, Shimhi, Shimi.', 'from 8088; famous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8098K}/[H8085]', 'lemma', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5816K}/[H5797]', 'inflected', 'heb', 'עֻזִּיאֵל', '["ʻUzzîyʼêl"]', '["and/ Uzziel"]', '["n-pr-m"]', 'Uzziel, the name of six Israelites Uzziel.', 'from 5797 and 410; strength of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2932}/[H2930]', 'inflected', 'heb', 'טֻמְאָה', '["ṭumʼâh"]', '["<the>/ uncleanness","the/ uncleanness"]', '["n-f"]', 'religious impurity filthiness, unclean(-ness).', 'from 2930;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6901}/[H6901]', 'inflected', 'heb', 'קָבַל', '["qâbal"]', '["and/ he accepted","and/ they accepted","and/ they received","and/ they received [it]","and/ they took"]', '["v"]', 'to admit, i.e. take (literally or figuratively) choose, (take) hold, receive, (under-) take.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3615G}\/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["they finished"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2186A}/[H2186]', 'lemma', 'heb', 'זָנַח', '["zânach"]', '["do you reject","have you rejected [us]","he had rejected","he has rejected","he will reject","it has rejected","will he reject","you have rejected","you have spurned","you reject [us]"]', '["v"]', 'reject, forsake, fail cast away (off), remove far away (off).', 'a primitive root meaning to push aside, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6842}/[H6852]', 'inflected', 'heb', 'צָפִיר', '["tsâphîyr"]', '["and/ [the] he-goat of","and/ he-goats of"]', '["n-m"]', 'a male goat (as prancing) (he) goat.', 'from 6852;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2403H}/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["and/ the/ sin offering"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1410H}/[H1464]', 'inflected', 'heb', 'גָּד', '["Gâd"]', '["and/ Gad"]', '["n-pr-m"]', 'Gad, a son of Jacob, including his tribe and its territory; also a prophet Gad.', 'from 1464;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5030}/H9023\/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["prophets/ his"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2689}\/[H2690]', 'inflected', 'heb', 'חֲצֹצְרָה', '["chătsôtsᵉrâh"]', '["with/ trumpets"]', '["n-f"]', 'a trumpet (from its sundered or quavering note) trumpet(-er).', 'by reduplication from 2690;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9009/{H4196}/[H2076]', 'inflected', 'heb', 'מִזְבֵּחַ', '["mizbêach"]', '["to/ the/ altar"]', '["n-m"]', 'an altar altar.', 'from 2076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7892A}/[H7891]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["and/ the/ song"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8057}/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["into/ joy","to/ joy"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8426}/[H3034]', 'inflected', 'heb', 'תּוֹדָה', '["tôwdâh"]', '["and/ thank-offerings","and/ thanksgiving"]', '["n-f"]', 'properly, an extension of the hand, i.e. (by implication) avowal, or (usually) adoration; specifically, a choir of worshippers confession, (sacrifice of) praise, thanks(-giving, offering).', 'from 3034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6944G}/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["and/ the/ holy offerings","and/ the/ holy things","and/ the/ sanctuary"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4592}/[H4591]', 'inflected', 'heb', 'מְעַט', '["mᵉʻaṭ"]', '["<into>/ little","to/ fewness"]', '["n-m"]', 'a little or few (often adverbial or comparative) almost (some, very) few(-er, -est), lightly, little (while), (very) small (matter, thing), some, soon, × very.', 'or מְעָט; from 4591;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2459>', 'inflected', 'heb', 'בחלבי', '["be./chel.Vei"]', '["with/ [the] fat<s> of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5262}/[H5258]', 'inflected', 'heb', 'נֶסֶךְ', '["neçek"]', '["and/ with the/ drink offerings"]', '["n-m"]', 'a libation; also a cast idol cover, drink offering, molten image.', 'or נֵסֶךְ; from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3559I}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["and/ he establishes","and/ it was arranged","and/ they established"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3559A}/[H3559]', 'inflected', 'heb', 'כּוּן', '["kûwn"]', '["what/ he had prepared","who/ prepares"]', '["v n-m"]', 'properly, to be erect (i.e. stand perpendicular); hence (causatively) to set up, in a great variety of applications, whether literal (establish, fix, prepare, apply), or figurative (appoint, render sure, proper or prosperous) certain(-ty), confirm, direct, faithfulness, fashion, fasten, firm, be fitted, be fixed, frame, be meet, ordain, order, perfect, (make) preparation, prepare (self), provide, make provision, (be, make) ready, right, set (aright, fast, forth), be stable, (e-) stablish, stand, tarry, × very deed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6597}/[H6621]', 'inflected', 'heb', 'פִּתְאוֹם', '["pithʼôwm"]', '["in/ suddenness"]', '["adv"]', 'instantly straightway, sudden(-ly).', 'or פִּתְאֹם; from 6621;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1697I}\/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["the/ thing"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0107}/[H104]', 'lemma', 'heb', 'אִגֶּרֶת', '["ʼiggereth"]', '["[the] letter of","[the] letters of","letters"]', '["n-f"]', 'an epistle letter.', 'feminine of 104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4100}/{H1767}/[H4100]', 'inflected', 'heb', 'מָה', '["mâh"]', '["to/ <from> [what]/ [was] sufficiency"]', '["i"]', 'properly, interrogative what? (including how? why? when?); but also exclamation, what! (including how!), or indefinitely what (including whatever, and even relatively, that which); often used with prefixes in various adverbial or conjunctive senses how (long, oft, (-soever)), (no-) thing, what (end, good, purpose, thing), whereby(-fore, -in, -to, -with), (for) why.', 'or מַה; or מָ; or מַ; also מֶה; a primitive particle;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0107}/[H104]', 'inflected', 'heb', 'אִגֶּרֶת', '["ʼiggereth"]', '["with <the>/ letters"]', '["n-f"]', 'an epistle letter.', 'feminine of 104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0001G}/H9026/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["like/ ancestors/ your","like/ fathers/ your"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H0251G}/H9026/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ like/ brothers/ your"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6203}/H9026/[H6202]', 'inflected', 'heb', 'עֹרֶף', '["ʻôreph"]', '["neck/ your"]', '["n-m"]', 'the nape or back of the neck (as declining); hence, the back generally (whether literal or figurative) back ((stiff-) neck((-ed).', 'from 6202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4720}/H9023/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["to/ sanctuary/ his"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7725G}/H9046/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["when/ return/ you"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7349}/[H7355]', 'inflected', 'heb', 'רַחוּם', '["rachûwm"]', '["and/ [the] compassionate","and/ compassionate"]', '["a"]', 'compassionate full of compassion, merciful.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3932}/[H3932]', 'inflected', 'heb', 'לָעַג', '["lâʻag"]', '["and/ mocking"]', '["v"]', 'to deride; by implication (as if imitating a foreigner) to speak unintelligibly have in derision, laugh (to scorn), mock (on), stammering.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6999C}/[H6999]', 'inflected', 'heb', 'קָטַר', '["qâṭar"]', '["the/ incense altars"]', '["v n-m n-f"]', 'to smoke, i.e. turn into fragrance by fire (especially as an act of worship) burn (incense, sacrifice) (upon), (altar for) incense, kindle, offer (incense, a sacrifice).', 'a primitive root (identical with through the idea of fumigation in a close place and perhaps thus driving out the occupants);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5977}/H9028/[H5975]', 'inflected', 'heb', 'עֹמֶד', '["ʻômed"]', '["place/ their"]', '["n-m"]', 'a spot (as being fixed) place, ( where) stood, upright.', 'from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8451}/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["according to/ [the] law of"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7821}/[H7819]', 'lemma', 'heb', 'שְׁחִיטָה', '["shᵉchîyṭâh"]', '["[the] slaughter of"]', '["n-f"]', 'slaughter killing.', 'from 7819;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2893}/[H2892]', 'inflected', 'heb', 'טׇהֳרָה', '["ṭohŏrâh"]', '["according to/ [the] purification of"]', '["n-f"]', 'ceremonial purification; moral purity × is cleansed, cleansing, purification(-fying).', 'feminine of 2892;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6944G}\/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["<the>/ holiness","the/ holy place"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7919A}/[H7919]', 'inflected', 'heb', 'שָׂכַל', '["sâkal"]', '["the/ prudent [person]","those/ [who] have insight","who/ were understanding"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4150H}/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["the/ appointed feast"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6629G>\', 'opaque', 'heb', 'צֹאן', '["tsôʼn"]', '["sheep"]', '["n-f"]', 'a collective name for a flock (of sheep or goats); also figuratively (of men) (small) cattle, flock ( -s), lamb ( -s), sheep(-cote, -fold, -shearer, -herds).', 'or צאוֹן; (Psalm 144:13), from an unused root meaning to migrate;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4583}/[H5772]', 'inflected', 'heb', 'מָעוֹן', '["mâʻôwn"]', '["<into>/ a habitation of","to/ [the] dwelling of"]', '["n-m"]', 'an abode, of God (the Tabernacle or the Temple), men (their home) or animals (their lair); hence, a retreat (asylum) den, dwelling((-) place), habitation.', 'or מָעִין; (1 Chronicles 4:41), from the same as 5772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H8064>\', 'inflected', 'heb', 'לשמים פ', '["la./sha.Ma.yim"]', '["to the/ heavens"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0669G}/[H672]', 'inflected', 'heb', 'אֶפְרַיִם', '["ʼEphrayim"]', '["and/ in/ Ephraim"]', '["n-pr-m"]', 'Ephrajim, a son of Joseph; also the tribe descended from him, and its territory Ephraim, Ephraimites.', 'dual of masculine form of 672; double fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5892B}/H9028\/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["to/ cities/ their"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8002}/[H7999]', 'inflected', 'heb', 'שֶׁלֶם', '["shelem"]', '["and/ for/ peace offerings","and/ to/ peace offerings"]', '["n-m"]', 'properly, requital, i.e. a (voluntary) sacrifice in thanks peace offering.', 'from 7999;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4521}/[H4487]', 'inflected', 'heb', 'מְנָת', '["mᵉnâth"]', '["and/ [the] portion of"]', '["n-f"]', 'an allotment (by courtesy, law or providence) portion.', 'from 4487;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6153}/[H6150]', 'inflected', 'heb', 'עֶרֶב', '["ʻereb"]', '["and/ the/ evening"]', '["n-m"]', 'dusk day, even(-ing, tide), night.', 'from 6150;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4521}/[H4487]', 'lemma', 'heb', 'מְנָת', '["mᵉnâth"]', '["[the] portion of","[the] portions of"]', '["n-f"]', 'an allotment (by courtesy, law or providence) portion.', 'from 4487;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6555}/[H6555]', 'inflected', 'heb', 'פָּרַץ', '["pârats"]', '["and/ just as/ spread"]', '["v"]', 'to break out (in many applications, direct and indirect, literal and figurative) × abroad, (make a) breach, break (away, down, -er, forth, in, up), burst out, come (spread) abroad, compel, disperse, grow, increase, open, press, scatter, urge.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4643}/[H6240]', 'inflected', 'heb', 'מַעֲשֵׂר', '["maʻăsêr"]', '["and/ [the] tithe of","and/ a tithe of"]', '["n-m"]', 'a tenth; especially a tithe tenth (part), tithe(-ing).', 'or מַעֲשַׂר; and (in plural) feminine מַעַשְׂרָה; from 6240;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6194}/[H6192]', 'lemma', 'heb', 'עָרֵם', '["ʻârêm"]', '["[is] a heap of","a heap of","heaps"]', '["n-f"]', 'a heap; specifically, a sheaf heap (of corn), sheaf.', '(Jeremiah 50:26) or (feminine) עֲרֵמָה; from 6192;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6194}\/[H6192]', 'inflected', 'heb', 'עָרֵם', '["ʻârêm"]', '["heaps"]', '["n-f"]', 'a heap; specifically, a sheaf heap (of corn), sheaf.', '(Jeremiah 50:26) or (feminine) עֲרֵמָה; from 6192;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5838P}/[H5826]', 'lemma', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4643}/[H6240]', 'inflected', 'heb', 'מַעֲשֵׂר', '["maʻăsêr"]', '["and/ the/ tithe"]', '["n-m"]', 'a tenth; especially a tithe tenth (part), tithe(-ing).', 'or מַעֲשַׂר; and (in plural) feminine מַעַשְׂרָה; from 6240;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3562}/[H3559]', 'lemma', 'heb', 'כּוֹנַנְיָהוּ', '["Kôwnanyâhûw"]', '["Konaniah"]', '["n-pr-m"]', 'Conanjah, the name of two Israelites Conaniah, Cononiah. Compare 3663.', 'from 3559 and 3050; Jah has sustained;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8096Q}/[H8088]', 'inflected', 'heb', 'שִׁמְעִי', '["Shimʻîy"]', '["and/ Shimei"]', '["n-pr-m"]', 'Shimi, the name of twenty Israelites Shimeah (from the margin), Shimei, Shimhi, Shimi.', 'from 8088; famous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3171L}/[H2421]', 'inflected', 'heb', 'יְחִיאֵל', '["Yᵉchîyʼêl"]', '["and/ Jehiel"]', '["n-pr-m"]', 'Jechiel (or Jechavel), the name of eight Israelites Jehiel.', 'or (2 Chronicles 29:14) יְחַוְאֵל; from 2421 and 410; God will live;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5812I}/[H5810]', 'inflected', 'heb', 'עֲזַזְיָהוּ', '["ʻĂzazyâhûw"]', '["and/ Azaziah"]', '["n-pr-m"]', 'Azazjah, the name of three Israelites Azaziah.', 'from 5810 and 3050; Jah has strengthened;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5184H}/[H5183]', 'inflected', 'heb', 'נַחַת', '["Nachath"]', '["and/ Nahath"]', '["n-pr-m"]', 'Nachath, the name of an Edomite and of two Israelites Nahath.', 'the same as 5183; quiet;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6214I}/[H6213]', 'inflected', 'heb', 'עֲשָׂהאֵל', '["ʻĂsâhʼêl"]', '["and/ Asahel"]', '["n-pr-m"]', 'Asahel, the name of four Israelites Asahel.', 'from 6213 and 410; God has made;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3406O}/[H7311]', 'inflected', 'heb', 'יְרִימוֹת', '["Yᵉrîymôwth"]', '["and/ Jerimoth"]', '["n-pr-f"]', 'Jerimoth or Jeremoth, the name of twelve Israelites Jermoth, Jerimoth, and Ramoth (from the margin).', 'or יְרֵימוֹת; or יְרֵמוֹת; feminine plural from 7311; elevations;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3107K}/[H3075]', 'inflected', 'heb', 'יוֹזָבָד', '["Yôwzâbâd"]', '["and/ Jozabad"]', '["n-pr-m"]', 'Jozabad, the name of ten Israelites Josabad, Jozabad.', 'a form of 3075;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0447N}/[H410]', 'inflected', 'heb', 'אֱלִיאֵל', '["ʼĔlîyʼêl"]', '["and/ Eliel"]', '["n-pr-m"]', 'Eliel, the name of nine Israelites Eliel.', 'from 410 repeated; God of (his) God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3253}/[H5564]', 'inflected', 'heb', 'יִסְמַכְיָהוּ', '["Yiçmakyâhûw"]', '["and/ Ismachiah"]', '["n-pr-m"]', 'Jismakjah, an Israelite Ismachiah.', 'from 5564 and 3050; Jah will sustain;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4287H}/[H4229]', 'inflected', 'heb', 'מַחַת', '["Machath"]', '["and/ Mahath"]', '["n-pr-m"]', 'Machath, the name of two Israelites Mahath.', 'probably from 4229; erasure;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1141M}/[H1129]', 'inflected', 'heb', 'בְּנָיָה', '["Bᵉnâyâh"]', '["and/ Benaiah"]', '["n-pr-m"]', 'Benajah, the name of twelve Israelites Benaiah.', 'or בּנָיָהוּ; (prolonged) from 1129 and 3050; Jah has built;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4662H}/[H6485]', 'inflected', 'heb', 'מִפְקָד', '["miphqâd"]', '["by/ [the] appointment of","in/ [the] appointed place of"]', '["n-m"]', 'an appointment, i.e. mandate; concretely, a designated spot; specifically, a census appointed place, commandment, number.', 'from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5838P}/[H5826]', 'inflected', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["and/ Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6981H}/[H7121]', 'inflected', 'heb', 'קוֹרֵא', '["Qôwrêʼ"]', '["and/ Kore"]', '["n-pr-m"]', 'Kore, the name of two Israelites Kore.', 'or קֹרֵא; (1 Chronicles 26:1), active participle of 7121; crier;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3232H}/[H3231]', 'lemma', 'heb', 'יִמְנָה', '["Yimnâh"]', '["Imnah"]', '["n-pr"]', 'Jimnah, the name of two Israelites; also (with the article) of the posterity of one of them Imna, Imnah, Jimnah, Jimnites.', 'from 3231; prosperity (as betokened by the right hand);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4217H}/H9011/[H2224]', 'inflected', 'heb', 'מִזְרָח', '["mizrâch"]', '["to the/ east/ <towards>"]', '["n-m"]', 'sunrise, i.e. the east east (side, -ward), (sun-) rising (of the sun).', 'from 2224;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5731G}/[H5730]', 'lemma', 'heb', 'עֵדֶן', '["ʻÊden"]', '["Eden"]', '["n-pr-m n-pr-loc"]', 'Eden, the region of Adam''s home Eden.', 'the same as 5730 (masculine);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4509G}/[H4480]', 'inflected', 'heb', 'מִנְיָמִין', '["Minyâmîyn"]', '["and/ Miniamin"]', '["n-pr-m"]', 'Minjamin, the name of two Israelites Miniamin. Compare 4326.', 'from 4480 and 3225; from (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3442H}/[H3091]', 'inflected', 'heb', 'יֵשׁוּעַ', '["Yêshûwaʻ"]', '["and/ Jeshua"]', '["n-pr-m n-pr-loc"]', 'Jeshua, the name of ten Israelites, also of a place in Palestine Jeshua.', 'for 3091; he will save;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8098L}/[H8085]', 'inflected', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["and/ Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0568K}/[H559]', 'lemma', 'heb', 'אֲמַרְיָה', '["ʼĂmaryâh"]', '["Amariah"]', '["n-pr-m"]', 'Amarjah, the name of nine Israelites Amariah.', 'or prolonged אֲמַרְיָהוּ; from 559 and 3050; Jah has said (i.e. promised);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7935I}/[H7931]', 'inflected', 'heb', 'שְׁכַנְיָה', '["Shᵉkanyâh"]', '["and/ Shecaniah"]', '["n-pr-m"]', 'Shekanjah, the name of nine Israelites Shecaniah, Shechaniah.', 'or (prolonged) שְׁכַנְיָהוּ; from 7931 and 3050; Jah has dwelt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251H}/H9028/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["to/ brothers/ their"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4256}/[H2505]', 'inflected', 'heb', 'מַחֲלֹקֶת', '["machălôqeth"]', '["by/ divisions"]', '["n-f"]', 'a section (of Levites, people or soldiers) company, course, division, portion. See also 5555.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H6996A}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["as the/ small"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4931}/H9028/[H4929]', 'inflected', 'heb', 'מִשְׁמֶרֶת', '["mishmereth"]', '["by/ duties/ their"]', '["n-f"]', 'watch, i.e. the act (custody), or (concretely) the sentry, the post; objectively preservation, or (concretely) safe; figuratively observance, i.e. (abstractly) duty or (objectively) a usage or party charge, keep, or to be kept, office, ordinace, safeguard, ward, watch.', 'feminine of 4929;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3188}/[H3187]', 'lemma', 'heb', 'יַחַשׂ', '["yachas"]', '["[the] genealogical enrolment of"]', '["n-m"]', 'a pedigree or family list (as growing spontaneously) genealogy.', 'from 3187;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3188}/[H3187]', 'inflected', 'heb', 'יַחַשׂ', '["yachas"]', '["and/ to/ genealogical enrolment"]', '["n-m"]', 'a pedigree or family list (as growing spontaneously) genealogy.', 'from 3187;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3881}/[H3878]', 'inflected', 'heb', 'לֵוִיִּי', '["Lêvîyîy"]', '["among the/ Levites"]', '["a"]', 'a Levite or descendant of Levi Leviite.', 'or לֵוִי; patronymically from 3878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0571G}/[H539]', 'inflected', 'heb', 'אֶמֶת', '["ʼemeth"]', '["and/ <the>/ faithfulness","and/ the/ faithfulness"]', '["n-f"]', 'stability; (figuratively) certainty, truth, trustworthiness assured(-ly), establishment, faithful, right, sure, true (-ly, -th), verity.', 'contracted from 539;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8451}/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["and/ in the/ law"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4687}/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["and/ in the/ commandment"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6743B}\/[H6743]', 'inflected', 'heb', 'צָלַח', '["tsâlach"]', '["and/ he succeeded"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0935N}/[H935]', 'lemma', 'heb', 'בּוֹא', '["bôwʼ"]', '["he came"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1234}/H9038/[H1234]', 'inflected', 'heb', 'בָּקַע', '["bâqaʻ"]', '["to/ break into/ them"]', '["v"]', 'to cleave; generally, to rend, break, rip or open make a breach, break forth (into, out, in pieces, through, up), be ready to burst, cleave (asunder), cut out, divide, hatch, rend (asunder), rip up, tear, win.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6440H}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ face/ his"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1368}/H9023/[H1397]', 'inflected', 'heb', 'גִּבּוֹר', '["gibbôwr"]', '["and/ mighty [men]/ his"]', '["a"]', 'powerful; by implication, warrior, tyrant champion, chief, × excel, giant, man, mighty (man, one), strong (man), valiant man.', 'or גִּבֹּר; (shortened) intensive from the same as 1397;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5640A}/[H5640]', 'inflected', 'heb', 'סָתַם', '["çâtham"]', '["to/ be closed","to/ stop up"]', '["v"]', 'to stop up; by implication, to repair; figuratively, to keep secret closed up, hidden, secret, shut out (up), stop.', 'or שָׂתַם; (Numbers 24:15), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5640A}/[H5640]', 'inflected', 'heb', 'סָתַם', '["çâtham"]', '["and/ they stopped up"]', '["v"]', 'to stop up; by implication, to repair; figuratively, to keep secret closed up, hidden, secret, shut out (up), stop.', 'or שָׂתַם; (Numbers 24:15), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4599}/[H5869]', 'inflected', 'heb', 'מַעְיָן', '["maʻyân"]', '["the/ springs"]', '["n-m"]', 'a fountain (also collectively), figuratively, a source (of satisfaction) fountain, spring, well.', 'or מַעְיְנוֹ; (Psalm 114:8), or (feminine) מַעְיָנָה; from 5869 (as a denominative in the sense of a spring);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7857}/[H7857]', 'inflected', 'heb', 'שָׁטַף', '["shâṭaph"]', '["which/ flowed"]', '["v"]', 'to gush; by implication, to inundate, cleanse; by analogy, to gallop, conquer drown, (over-) flow(-whelm, rinse, run, rush, (throughly) wash (away).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2388K}/[H2388]', 'inflected', 'heb', 'חָזַק', '["châzaq"]', '["and/ he strengthened","and/ he strengthened himself"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H2351>/H9011', 'inflected', 'heb', 'ולחוצה', '["ve./la./Chu.tza/h"]', '["and/ to the/ outside/ <towards>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7973}/[H7971]', 'lemma', 'heb', 'שֶׁלַח', '["shelach"]', '["weapon[s]"]', '["n-m"]', 'a missile of attack, i.e. spear; also (figuratively) a shoot of growth; i.e. branch dart, plant, × put off, sword, weapon.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6908}/H9038/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["and/ I assembled/ them","and/ I will gather/ them","and/ he assembled/ them"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7339}/[H7337]', 'lemma', 'heb', 'רְחֹב', '["rᵉchôb"]', '["[the] open place of","[the] open places","an open place","open place"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/H9005/{H6440G}/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["and/ from/ <to>/ before"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5973A}/H9035/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["and/ [is] with/ us"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5826}/H9035/[H5826]', 'inflected', 'heb', 'עָזַר', '["ʻâzar"]', '["to/ help/ us"]', '["v"]', 'to surround, i.e. protect or aid help, succour.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3898A}/[H3898]', 'inflected', 'heb', 'לָחַם', '["lâcham"]', '["and/ to/ fight"]', '["v"]', 'to feed on; figuratively, to consume; by implication, to battle (as destruction) devour, eat, × ever, fight(-ing), overcome, prevail, (make) war(-ring).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5612A}/[H9]', 'inflected', 'heb', 'סֵפֶר', '["çêpher"]', '["and/ a document","and/ letters"]', '["n-m"]', 'properly, writing (the art or a document); by implication, a book bill, book, evidence, × learn(-ed) (-ing), letter, register, scroll.', 'or (feminine) סִפְרָה; (Psalm 56:8 (9)), from 5608;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0559}/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["and/ to/ say"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0430J}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["like/ [the] gods of"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3372G}/H9038/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["to/ make afraid/ them"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0926}/H9038/[H926]', 'inflected', 'heb', 'בָּהַל', '["bâhal"]', '["and/ to/ terrify/ them"]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H5921A}/[H5920]', 'inflected', 'heb', 'עַל', '["ʻal"]', '["as/ on"]', '["prep"]', 'above, over, upon, or against (yet always in this last relation with a downward aspect) in a great variety of applications above, according to(-ly), after, (as) against, among, and, × as, at, because of, beside (the rest of), between, beyond the time, × both and, by (reason of), × had the charge of, concerning for, in (that), (forth, out) of, (from) (off), (up-) on, over, than, through(-out), to, touching, × with.', 'properly, the same as 5920 used as a preposition (in the singular or plural often with prefix, or as conjunction with a particle following);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0120G}\/[H119]', 'inflected', 'heb', 'אָדָם', '["ʼâdâm"]', '["<the>/ humankind"]', '["n-m"]', 'ruddy i.e. a human being (an individual or the species, mankind, etc.) × another, hypocrite, common sort, × low, man (mean, of low degree), person.', 'from 119;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3470A}/[H3467]', 'inflected', 'heb', 'יְשַׁעְיָה', '["Yᵉshaʻyâh"]', '["and/ Isaiah"]', '["n-pr-m"]', 'Jeshajah, the name of seven Israelites Isaiah, Jesaiah, Jeshaiah.', 'or יְשַׁעְיָהוּ; from 3467 and 3050; Jah has saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H8064>\', 'inflected', 'heb', 'השמים פ', '["ha./sha.Ma.yim"]', '["the/ heavens"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5057}/[H5046]', 'inflected', 'heb', 'נָגִיד', '["nâgîyd"]', '["and/ officer"]', '["n-m"]', 'a commander (as occupying the front), civil, military or religious; generally (abstractly, plural), honorable themes captain, chief, excellent thing, (chief) governor, leader, noble, prince, (chief) ruler.', 'or נָגִד; from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1322}/[H954]', 'inflected', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["in/ shame","with/ shame of"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3329}/[H3318]', 'inflected', 'heb', 'יָצִיא', '["yâtsîyʼ"]', '["and/ some of/ [the] offspring<s> of"]', '["a"]', 'issue, i.e. offspring those that came forth.', 'from 3318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5307J}/H9033/[H5307]', 'inflected', 'heb', 'נָפַל', '["nâphal"]', '["they made fall/ him"]', '["v"]', 'to fall, in a great variety of applications (intransitive or causative, literal or figurative) be accepted, cast (down, self, (lots), out), cease, die, divide (by lot), (let) fail, (cause to, let, make, ready to) fall (away, down, -en, -ing), fell(-ing), fugitive, have (inheritance), inferior, be judged (by mistake for 6419), lay (along), (cause to) lie down, light (down), be (× hast) lost, lying, overthrow, overwhelm, perish, present(-ed, -ing), (make to) rot, slay, smite out, × surely, throw down.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375L}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ he was lifted up"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1363}/[H1361]', 'inflected', 'heb', 'גֹּבַהּ', '["gôbahh"]', '["in/ [the] haughtiness of"]', '["n-m"]', 'elation, grandeur, arrogance excellency, haughty, height, high, loftiness, pride.', 'from 1361;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1314}/[H1313]', 'inflected', 'heb', 'בֶּשֶׂם', '["besem"]', '["and/ for/ spices"]', '["n-m"]', 'fragrance; by implication, spicery; also the balsam plant smell, spice, sweet (odour).', 'or בֹּשֶׂם; from the same as 1313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4043}/[H1598]', 'inflected', 'heb', 'מָגֵן', '["mâgên"]', '["and/ for/ shields"]', '["n-m"]', 'a shield (i.e. the small one or buckler); figuratively, a protector; also the scaly hide of the crocodile × armed, buckler, defence, ruler, scale, shield.', 'also (in plural) feminine מְגִנָּה; from 1598;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4543}/[H3664]', 'inflected', 'heb', 'מִסְכְּנָה', '["miçkᵉnâh"]', '["and/ storehouses"]', '["n-f"]', 'a magazine store(-house), treasure.', 'by transp. from 3664;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8393}/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["for/ [the] yield of"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0723}/[H717]', 'inflected', 'heb', 'אֻרְוָה', '["ʼurvâh"]', '["and/ stalls"]', '["n-f"]', 'a herding-place for an animal stall.', 'or אֲרָיָה; from 717 (in the sense of feeding);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5739}/[H5737]', 'inflected', 'heb', 'עֵדֶר', '["ʻêder"]', '["and/ flocks"]', '["n-m"]', 'an arrangement, i.e. muster (of animals) drove, flock, herd.', 'from 5737;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0220}/[H723]', 'inflected', 'heb', 'אֲוֵרָה', '["ʼăvêrâh"]', '["for the/ stalls"]', '["n-f"]', 'a stall cote.', 'by transposition for 723;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3474}/H9038/[H3474]', 'inflected', 'heb', 'יָשַׁר', '["yâshar"]', '["and/ he directed/ them"]', '["v"]', 'to be straight or even; figuratively, to be (causatively, to make) right, pleasant, prosperous direct, fit, seem good (meet), please (will), be (esteem, go) right (on), bring (look, make, take the) straight (way), be upright(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3887}/[H3887]', 'inflected', 'heb', 'לוּץ', '["lûwts"]', '["in/ [the] envoys of"]', '["v"]', 'properly, to make mouths at, i.e. to scoff; hence (from the effort to pronounce a foreign language) to interpret, or (generally) intercede ambassador, have in derision, interpreter, make a mock, mocker, scorn(-er, -ful), teacher.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2617A}/H9023/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["and/ covenant loyalti<es>/ his","and/ covenant loyalty/ his"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2377}/[H2372]', 'inflected', 'heb', 'חָזוֹן', '["châzôwn"]', '["in the/ vision","in/ [the] vision of","in/ a vision"]', '["n-m"]', 'a sight (mentally), i.e. a dream, revelation, or oracle vision.', 'from 2372;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3784}/[H3784]', 'inflected', 'heb', 'כָּשַׁף', '["kâshaph"]', '["and/ he practiced sorcery"]', '["v"]', 'properly, to whisper a spell, i.e. to inchant or practise magic sorcerer, (use) witch(-craft).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5566>', 'inflected', 'heb', 'הסמל', '["ha./Se.mel"]', '["<the>/ sculpture","the/ image"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5865}/[H5769]', 'inflected', 'heb', 'עֵילוֹם', '["ʻêylôwm"]', '["for/ ever"]', '["n-m"]', 'ever.', 'for 5769');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H2336>', 'inflected', 'heb', 'בחחים', '["ba./cho.Chim"]', '["with <the>/ hooks"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1980J}/H9033/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["and/ he leads/ him","and/ they brought/ him"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6887B}/[H6887]', 'inflected', 'heb', 'צָרַר', '["tsârar"]', '["and/ just as/ harassed"]', '["v"]', 'to cramp, literally or figuratively, transitive or intransitive adversary, (be in) afflict(-ion), beseige, bind (up), (be in, bring) distress, enemy, narrower, oppress, pangs, shut up, be in a strait (trouble), vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2435}/[H2434]', 'lemma', 'heb', 'חִיצוֹן', '["chîytsôwn"]', '["outer"]', '["a"]', 'properly, the (outer) wall side; hence, exterior; figuratively, secular (as opposed to sacred) outer, outward, utter, without.', 'from 2434;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1521}/[H1518]', 'inflected', 'heb', 'גִּיחוֹן', '["Gîychôwn"]', '["of/ Gihon"]', '["n-pr-m"]', 'Gichon, a river of Paradise; also a valley (or pool) near Jerusalem Gihon.', 'or (shortened) גִּחוֹן; from 1518; stream;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0935I}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ to/ go"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1709G}/[H1711]', 'inflected', 'heb', 'דָּג', '["dâg"]', '["the/ fish","the/ fish<es>"]', '["n-m"]', 'a fish (often used collectively) fish.', 'or (fully) דָּאג; (Nehemiah 13:16), from 1711; a fish (as prolific); or perhaps rather from 1672 (as timid); but still better from 1672 (in the sense of squirming, i.e. moving by the vibratory action of the tail);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6077}/[H6076]', 'inflected', 'heb', 'עֹפֶל', '["ʻÔphel"]', '["<to> the/ Ophel"]', '["n-pr-loc"]', 'Ophel, a ridge in Jerusalem Ophel.', 'the same as 6076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1361}/H9034/[H1361]', 'inflected', 'heb', 'גָּבַהּ', '["gâbahh"]', '["and/ he made high/ it"]', '["v"]', 'to soar, i.e. be lofty; figuratively, to be haughty exalt, be haughty, be (make) high(-er), lift up, mount up, be proud, raise up great height, upward.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8605}/H9023/[H6419]', 'inflected', 'heb', 'תְּפִלָּה', '["tᵉphillâh"]', '["and/ prayer/ his"]', '["n-f"]', 'intercession, supplication; by implication, a hymn prayer.', 'from 6419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4604}/H9023/[H4603]', 'inflected', 'heb', 'מַעַל', '["maʻal"]', '["and/ unfaithfulness/ his"]', '["n-m"]', 'treachery, i.e. sin falsehood, grievously, sore, transgression, trespass, × very.', 'from 4603;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4725}/[H6965]', 'inflected', 'heb', 'מָקוֹם', '["mâqôwm"]', '["and/ the/ places"]', '["n-m"]', 'properly, a standing, i.e. a spot; but used widely of a locality (general or specific); also (figuratively) of a condition (of body or mind) country, × home, × open, place, room, space, × whither(-soever).', 'or מָקֹם; also (feminine) מְקוֹמָה; or מְקֹמָה; from 6965;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6456}/[H6458]', 'inflected', 'heb', 'פְּסִיל', '["pᵉçîyl"]', '["and/ the/ idols"]', '["n-m"]', 'an idol carved (graven) image, quarry.', 'from 6458;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3665}/H9043/[H3665]', 'inflected', 'heb', 'כָּנַע', '["kânaʻ"]', '["he humbled/ himself"]', '["v"]', 'properly, to bend the knee; hence, to humiliate, vanquish bring down (low), into subjection, under, humble (self), subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2335}/[H2374]', 'lemma', 'heb', 'חוֹזַי', '["Chôwzay"]', '["Hozai"]', '["n-m"]', 'Chozai, an Israelite the seers.', 'from 2374; visionary;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3665}/[H3665]', 'inflected', 'heb', 'כָּנַע', '["kânaʻ"]', '["as/ had humbled himself"]', '["v"]', 'properly, to bend the knee; hence, to humiliate, vanquish bring down (low), into subjection, under, humble (self), subdue.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8083}/[H8082]', 'inflected', 'heb', 'שְׁמֹנֶה', '["shᵉmôneh"]', '["and/ in/ eight"]', '["n"]', 'a cardinal number, eight (as if a surplus above the ''perfect'' seven); also (as ordinal) eighth eight(-een, -eenth), eighth.', 'or שְׁמוֹנֶה; feminine שְׁמֹנָה; or שְׁמוֹנָה; apparently from 8082 through the idea of plumpness;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4541A}/[H5258]', 'inflected', 'heb', 'מַסֵּכָה', '["maççêkâh"]', '["and/ the/ molten images"]', '["n-f"]', 'properly, a pouring over, i.e. fusion of metal (especially a cast image); by implication, a libation, i.e. league; concretely a coverlet (as if poured out) covering, molten (image), vail.', 'from 5258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2553}/[H2535]', 'inflected', 'heb', 'חַמָּן', '["chammân"]', '["and/ the/ incense altars"]', '["n-m"]', 'a sun-pillar idol, image.', 'from 2535;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1854}/[H1915]', 'inflected', 'heb', 'דָּקַק', '["dâqaq"]', '["and/ he pulverized [them]","so/ you may crush [them]"]', '["v"]', 'to crush (or intransitively) crumble beat in pieces (small), bruise, make dust, (into) × powder, (be, very) small, stamp (small).', 'a primitive root (compare 1915);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2719}/H9028/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["by/ sword/ their","with/ swords/ their"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3807}/[H3807]', 'lemma', 'heb', 'כָּתַת', '["kâthath"]', '["crushed","he crushed","it will be crushed","they are crushed to pieces","they will be crushed"]', '["v"]', 'to bruise or violently strike beat (down, to pieces), break in pieces, crushed, destroy, discomfit, smite, stamp. l', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1854}/[H1915]', 'inflected', 'heb', 'דָּקַק', '["dâqaq"]', '["to/ pulverize"]', '["v"]', 'to crush (or intransitively) crumble beat in pieces (small), bruise, make dust, (into) × powder, (be, very) small, stamp (small).', 'a primitive root (compare 1915);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3389}\/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["to/ Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4641K}/[H4639]', 'lemma', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3098J}/[H3068]', 'lemma', 'heb', 'יוֹאָח', '["Yôwʼâch"]', '["Joah"]', '["n-pr-m"]', 'Joach, the name of four Israelites Joah.', 'from 3068 and 251; Jehovah-brothered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3099G}/[H3059]', 'lemma', 'heb', 'יוֹאָחָז', '["Yôwʼâchâz"]', '["Joahaz"]', '["n-pr-m"]', 'Joachaz, the name of two Israelites Jehoahaz, Joahaz.', 'a form of 3059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0918}/[H919]', 'inflected', 'heb', 'בָּדַק', '["bâdaq"]', '["to/ mend"]', '["v"]', 'to mend a breach repair.', 'a primitive root; to gap open; used only as a denominative from 919;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4226}/[H2266]', 'inflected', 'heb', 'מְחַבְּרָה', '["mᵉchabbᵉrâh"]', '["for the/ clamps"]', '["n-f"]', 'a joiner, i.e. brace or cramp coupling, joining.', 'from 2266;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7136B}/[H7136]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["and/ to/ make beams for"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3189K}/[H3161]', 'lemma', 'heb', 'יַחַת', '["Yachath"]', '["Jahath"]', '["n-pr-m"]', 'Jachath, the name of four Israelites Jahath.', 'from 3161; unity;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5662O}/[H5647]', 'inflected', 'heb', 'עֹבַדְיָה', '["ʻÔbadyâh"]', '["and/ Obadiah"]', '["n-pr-m"]', 'Obadjah, the name of thirteen Israelites Obadiah.', 'or עֹבַדְיָהוּ; active participle of 5647 and 3050; serving Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2148N}/[H2142]', 'inflected', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["and/ Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4918N}/[H7999]', 'inflected', 'heb', 'מְשֻׁלָּם', '["Mᵉshullâm"]', '["and/ Meshullam"]', '["n-pr-m"]', 'Meshullam, the name of seventeen Israelites Meshullam.', 'from 7999; allied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5449}/[H5445]', 'inflected', 'heb', 'סַבָּל', '["çabbâl"]', '["the/ burden-bearer[s]","the/ burden-bearers"]', '["n-m"]', 'a porter (to bear, bearer of) burden(-s).', 'from 5445;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/H9009/{H3881}/[H3878]', 'inflected', 'heb', 'לֵוִיִּי', '["Lêvîyîy"]', '["and/ some of/ the/ Levites"]', '["a"]', 'a Levite or descendant of Levi Leviite.', 'or לֵוִי; patronymically from 3878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7778}/[H8176]', 'inflected', 'heb', 'שׁוֹעֵר', '["shôwʻêr"]', '["and/ gatekeepers"]', '["n-m"]', 'a janitor doorkeeper, porter.', 'or שֹׁעֵר active participle of 8176 (as denominative from 8179);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3318H}/H9048/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ when/ brought out/ they"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5413}/[H5413]', 'inflected', 'heb', 'נָתַךְ', '["nâthak"]', '["and/ I will melt","and/ it has poured forth","and/ it poured forth","and/ it will be melted","and/ they have poured out","and/ they poured forth","and/ you will be melted"]', '["v"]', 'to flow forth (literally or figuratively); by implication, to liquify drop, gather (together), melt, pour (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5658K}/[H5647]', 'lemma', 'heb', 'עַבְדוֹן', '["ʻAbdôwn"]', '["Abdon"]', '["n-pr-m n-pr-loc"]', 'Abdon, the name of a place in Palestine and of four Israelites Abdon. Compare 5683.', 'from 5647; servitude;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4318M}/[H4320]', 'lemma', 'heb', 'מִיכָה', '["Mîykâh"]', '["Micah"]', '["n-pr-m"]', 'Micah, the name of seven Israelites Micah, Micaiah, Michah.', 'an abbreviated form of 4320;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2641}/[H2637]', 'lemma', 'heb', 'חַסְרָה', '["Chaçrâh"]', '["Hasrah"]', '["n-pr-m"]', 'Chasrah, an Israelite Hasrah.', 'from 2637; want');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H2063}\/[H2088]', 'inflected', 'heb', 'זֹאת', '["zôʼth"]', '["like/ this"]', '["d"]', 'this (often used adverb) hereby (-in, -with), it, likewise, the one (other, same), she, so (much), such (deed), that, therefore, these, this (thing), thus.', 'irregular feminine of 2088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0413}/H9030\/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["to/ me"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5413}/[H5413]', 'inflected', 'heb', 'נָתַךְ', '["nâthak"]', '["so/ it may pour forth"]', '["v"]', 'to flow forth (literally or figuratively); by implication, to liquify drop, gather (together), melt, pour (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1697G}\/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["a word","word"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1419A}/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["from/ great"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5977}/H9023/[H5975]', 'inflected', 'heb', 'עֹמֶד', '["ʻômed"]', '["place/ his"]', '["n-m"]', 'a spot (as being fixed) place, ( where) stood, upright.', 'from 5975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1285}/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["according to/ [the] covenant of","like the/ covenant"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4256}/H9026/[H2505]', 'inflected', 'heb', 'מַחֲלֹקֶת', '["machălôqeth"]', '["according to/ divisions/ your"]', '["n-f"]', 'a section (of Levites, people or soldiers) company, course, division, portion. See also 5555.', 'from 2505;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4385}/[H3789]', 'inflected', 'heb', 'מִכְתָּב', '["miktâb"]', '["and/ by/ [the] writing of"]', '["n-m"]', 'a thing written, the characters, or a document (letter, copy, edict, poem) writing.', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2515}/[H2512]', 'inflected', 'heb', 'חֲלֻקָּה', '["chăluqqâh"]', '["and/ a division of"]', '["n-f"]', 'a distribution division.', 'feminine of 2512;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6453}/[H6452]', 'inflected', 'heb', 'פֶּסַח', '["peçach"]', '["for the/ passovers"]', '["n-m"]', 'a pretermission, i.e. exemption; used only techically of the Jewish Passover (the festival or the victim) passover (offering).', 'from 6452;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7399}/[H7408]', 'inflected', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["[were] from/ [the] property of"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2148O}/[H2142]', 'inflected', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["and/ Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3171M}/[H2421]', 'inflected', 'heb', 'יְחִיאֵל', '["Yᵉchîyʼêl"]', '["and/ Jehiel"]', '["n-pr-m"]', 'Jechiel (or Jechavel), the name of eight Israelites Jehiel.', 'or (2 Chronicles 29:14) יְחַוְאֵל; from 2421 and 410; God will live;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3562}/[H3559]', 'inflected', 'heb', 'כּוֹנַנְיָהוּ', '["Kôwnanyâhûw"]', '["and/ Konaniah"]', '["n-pr-m"]', 'Conanjah, the name of two Israelites Conaniah, Cononiah. Compare 3663.', 'from 3559 and 3050; Jah has sustained;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8098M}/[H8085]', 'inflected', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["and/ Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5417M}/[H5414]', 'inflected', 'heb', 'נְתַנְאֵל', '["Nᵉthanʼêl"]', '["and/ Nethanel"]', '["n-pr-m"]', 'Nethanel, the name of ten Israelites Nethaneel.', 'from 5414 and 410; given of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2811L}/[H2803]', 'inflected', 'heb', 'חֲשַׁבְיָה', '["Chăshabyâh"]', '["and/ Hashabiah"]', '["n-pr-m"]', 'Chashabjah, the name of nine Israelites Hashabiah.', 'or חֲשַׁבְיָהוּ; from 2803 and 3050; Jah has regarded;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3273M}/[H3261]', 'inflected', 'heb', 'יְעִיאֵל', '["Yᵉʻîyʼêl"]', '["and/ Jeiel"]', '["n-pr-m"]', 'Jeiel, the name of six Israelites Jeiel, Jehiel. Compare 3262.', 'from 3261 and 410; carried away of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3107L}/[H3075]', 'inflected', 'heb', 'יוֹזָבָד', '["Yôwzâbâd"]', '["and/ Jozabad"]', '["n-pr-m"]', 'Jozabad, the name of ten Israelites Josabad, Jozabad.', 'a form of 3075;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5414G}/H9038/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["to/ give/ them"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4653}/[H6385]', 'inflected', 'heb', 'מִפְלַגָּה', '["miphlaggâh"]', '["to/ [the] divisions"]', '["n-f"]', 'a classification division.', 'from 6385;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1241}/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["for the/ cattle"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1731}/[H1730]', 'inflected', 'heb', 'דּוּד', '["dûwd"]', '["and/ in <the>/ kettles"]', '["n-m"]', 'a pot (for boiling); also (by resemblance of shape) a basket basket, caldron, kettle, (seething) pot.', 'from the same as 1730;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6745}/[H6743]', 'inflected', 'heb', 'צֵלָחָה', '["tsêlâchâh"]', '["and/ in <the>/ pans"]', '["n-f"]', 'something protracted or flattened out, i.e. a platter pan.', 'from 6743;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H2459>', 'inflected', 'heb', 'והחלבים', '["ve./ha./cha.la.Vim"]', '["and/ the/ fat<s>"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5493H}/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["to/ turn aside"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5656G}/H9028/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["service/ their"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5224G}/[H5224]', 'lemma', 'heb', 'נְכוֹ', '["Nᵉkôw"]', '["Necho"]', '["n-pr-m"]', 'Neko, an Egyptian king Necho. Compare 6549.', 'probably of Egyptian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3751}/[H3751]', 'inflected', 'heb', 'כַּרְכְּמִישׁ', '["Karkᵉmîysh"]', '["at/ Carchemish"]', '["n-pr-loc"]', 'Karkemish, a place in Syria Carchemish.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4421}/H9020/[H3898]', 'inflected', 'heb', 'מִלְחָמָה', '["milchâmâh"]', '["battle/ my"]', '["n-f"]', 'a battle (i.e. the engagement); generally, war (i.e. war-fare) battle, fight(-ing), war(-rior).', 'from 3898 (in the sense of fighting);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0926}/H9030/[H926]', 'inflected', 'heb', 'בָּהַל', '["bâhal"]', '["to/ hurry/ I"]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0430G}/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["from/ God","from/ [the] God of","more than/ God"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674C}/H9030/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["take away/ me"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2977G}\/[H803]', 'inflected', 'heb', 'יֹאשִׁיָּה', '["Yôʼshîyâh"]', '["Josiah"]', '["n-pr-m"]', 'Joshijah, the name of two Israelites Josiah.', 'or יֹאשִׁיָּהוּ; from the same root as 803 and 3050; founded of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3414L}/[H7311]', 'lemma', 'heb', 'יִרְמְיָה', '["Yirmᵉyâh"]', '["Jeremiah","O Jeremiah"]', '["n-pr-m"]', 'Jirmejah, the name of eight or nine Israelites Jeremiah.', 'or יִרְמְיָהוּ; from 7311 and 3050; Jah will rise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7015}/H9028/[H6969]', 'inflected', 'heb', 'קִינָה', '["qîynâh"]', '["in/ lamentations/ their"]', '["n-f"]', 'a dirge (as accompanied by beating the breasts or on instruments) lamentation.', 'from 6969;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1697K}/H9023/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ matters/ his"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3099I}/[H3059]', 'lemma', 'heb', 'יוֹאָחָז', '["Yôwʼâchâz"]', '["Jehoahaz"]', '["n-pr-m"]', 'Joachaz, the name of two Israelites Jehoahaz, Joahaz.', 'a form of 3059;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1980J}/H9033/[H3212]', 'inflected', 'heb', 'הָלַךְ', '["hâlak"]', '["to/ take/ him"]', '["v"]', 'to walk (in a great variety of applications, literally and figuratively) (all) along, apace, behave (self), come, (on) continually, be conversant, depart, be eased, enter, exercise (self), follow, forth, forward, get, go (about, abroad, along, away, forward, on, out, up and down), greater, grow, be wont to haunt, lead, march, × more and more, move (self), needs, on, pass (away), be at the point, quite, run (along), send, speedily, spread, still, surely, tale-bearer, travel(-ler), walk (abroad, on, to and fro, up and down, to places), wander, wax, (way-) faring man, × be weak, whirl.', 'akin to 3212; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3627}/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["and/ some of/ [the] articles of"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1964H}/H9023/[H3201]', 'inflected', 'heb', 'הֵיכָל', '["hêykâl"]', '["in/ palace/ his"]', '["n-m"]', 'a large public building, such as a palace or temple palace, temple.', 'probably from 3201 (in the sense of capacity);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8441}/H9023/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["and/ abominations/ his"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H8666}/[H7725]', 'inflected', 'heb', 'תְּשׁוּבָה', '["tᵉshûwbâh"]', '["and/ to/ [the] return of"]', '["n-f"]', 'a recurrence (of time or place); a reply (as returned) answer, be expired, return.', 'or תְּשֻׁבָה; from 7725;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3389}\/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["and/ Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7650}/H9033/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["he had made swear an oath/ him"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7725I}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["from/ turning back"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H4397G>/H9023', 'opaque', 'heb', 'מַלְאָךְ', '["malʼâk"]', '["messengers/ his"]', '["n-m"]', 'a messenger; specifically, of God, i.e. an angel (also a prophet, priest or teacher) ambassador, angel, king, messenger.', 'from an unused root meaning to despatch as a deputy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4583}/H9023/[H5772]', 'inflected', 'heb', 'מָעוֹן', '["mâʻôwn"]', '["dwelling place/ his"]', '["n-m"]', 'an abode, of God (the Tabernacle or the Temple), men (their home) or animals (their lair); hence, a retreat (asylum) den, dwelling((-) place), habitation.', 'or מָעִין; (1 Chronicles 4:41), from the same as 5772;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3931}/[H3931]', 'lemma', 'heb', 'לָעַב', '["lâʻab"]', '["deriding"]', '["v"]', 'to deride mock.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H4397G>', 'inflected', 'heb', 'במלאכי', '["be./mal.''a.Khei"]', '["<in>/ [the] messengers of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0959}/[H959]', 'inflected', 'heb', 'בָּזָה', '["bâzâh"]', '["and/ [am] despised","and/ despised of","and/ despising"]', '["v"]', 'to disesteem despise, disdain, contemn(-ptible), think to scorn, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8591}/[H8591]', 'inflected', 'heb', 'תָּעַע', '["tâʻaʻ"]', '["and/ mocking"]', '["v"]', 'to cheat; by analogy, to maltreat deceive, misuse.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0970}/H9028/[H977]', 'inflected', 'heb', 'בָּחוּר', '["bâchûwr"]', '["young men/ their"]', '["n-m"]', 'properly, selected, i.e. a youth (often collective) (choice) young (man), chosen, × hole.', 'or בָּחֻר; participle passive of 977;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4720}/H9028/[H6942]', 'inflected', 'heb', 'מִקְדָּשׁ', '["miqdâsh"]', '["sanctuaries/ their","sanctuary/ their"]', '["n-m"]', 'a consecrated thing or place, especially, a palace, sanctuary (whether of Jehovah or of idols) or asylum chapel, hallowed part, holy place, sanctuary.', 'or מִקְּדָשׁ; (Exodus 15:17), from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H1330>', 'inflected', 'heb', 'ובתולה', '["u./ve.tu.Lah"]', '["and/ virgin","and/ young woman"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3486>', 'inflected', 'heb', 'וישש', '["ve./ya.Shesh"]', '["and/ [the] decrepit"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6996A}/[H6962]', 'inflected', 'heb', 'קָטָן', '["qâṭân"]', '["and/ <the>/ small"]', '["a"]', 'abbreviated, i.e. diminutive, literally (in quantity, size or number) or figuratively (in age or importance) least, less(-er), little (one), small(-est, one, quantity, thing), young(-er, -est).', 'or קָטֹן; from 6962;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0759G>/H9024', 'opaque', 'heb', 'אַרְמוֹן', '["ʼarmôwn"]', '["fortresses/ its","palaces/ its"]', '["n-m"]', 'a citadel (from its height) castle, palace. Compare 2038.', 'from an unused root (meaning to be elevated);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4261}/H9024/[H2530]', 'inflected', 'heb', 'מַחְמָד', '["machmâd"]', '["precious things/ her","preciousness<es>/ its"]', '["n-m"]', 'delightful; hence, a delight, i.e. object of affection or desire beloved, desire, goodly, lovely, pleasant (thing).', 'from 2530;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7843}\/[H7843]', 'inflected', 'heb', 'שָׁחַת', '["shâchath"]', '["to/ destroy"]', '["v"]', 'to decay, i.e. (causatively) ruin (literally or figuratively) batter, cast off, corrupt(-er, thing), destroy(-er, -uction), lose, mar, perish, spill, spoiler, × utterly, waste(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6539>', 'opaque', 'heb', 'פָּרַס', '["Pâraç"]', '["Persia"]', '["n-pr"]', 'Paras (i.e. Persia), an Eastern country, including its inhabitants Persia, Persians.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8074G}/H9024/[H8074]', 'inflected', 'heb', 'שָׁמֵם', '["shâmêm"]', '["the/ desolation/ of it"]', '["v"]', 'to stun (or intransitively, grow numb), i.e. devastate or (figuratively) stupefy (both usually in a passive sense) make amazed, be astonied, (be an) astonish(-ment), (be, bring into, unto, lay, lie, make) desolate(-ion, places), be destitute, destroy (self), (lay, lie, make) waste, wonder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3566}/[H3566]', 'inflected', 'heb', 'כּוֹרֶשׁ', '["Kôwresh"]', '["of/ Cyrus","to/ Cyrus"]', '["n-pr-m"]', 'Koresh (or Cyrus), the Persian king Cyrus.', 'or (Ezra 1:1 (last time),2) כֹּרֶשׁ; from the Persian;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3566}/[H3566]', 'lemma', 'heb', 'כּוֹרֶשׁ', '["Kôwresh"]', '["Cyrus"]', '["n-pr-m"]', 'Koresh (or Cyrus), the Persian king Cyrus.', 'or (Ezra 1:1 (last time),2) כֹּרֶשׁ; from the Persian;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4385}/[H3789]', 'inflected', 'heb', 'מִכְתָּב', '["miktâb"]', '["in/ writing"]', '["n-m"]', 'a thing written, the characters, or a document (letter, copy, edict, poem) writing.', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375K}/H9033/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["let them support/ him"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7399}/[H7408]', 'inflected', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["and/ with/ equipment","and/ with/ property"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5071}/[H5068]', 'inflected', 'heb', 'נְדָבָה', '["nᵉdâbâh"]', '["the/ freewill offering"]', '["n-f"]', 'properly (abstractly) spontaneity, or (adjectively) spontaneous; also (concretely) a spontaneous or (by inference, in plural) abundant gift free(-will) offering, freely, plentiful, voluntary(-ily, offering), willing(-ly), offering).', 'from 5068;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4030}/[H4022]', 'inflected', 'heb', 'מִגְדָּנָה', '["migdânâh"]', '["and/ with <the>/ precious things"]', '["n-f"]', 'preciousness, i.e. a gem precious thing, present.', 'from the same as 4022;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5068}\/[H5068]', 'inflected', 'heb', 'נָדַב', '["nâdab"]', '["ering of freewill offerings"]', '["v"]', 'to impel; hence, to volunteer (as a soldier), to present spontaneously offer freely, be (give, make, offer self) willing(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318H}/H9038/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ I brought out/ them","and/ I will bring out/ them","and/ he brought out/ them"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4990G}/[H4990]', 'lemma', 'heb', 'מִתְרְדָת', '["Mithrᵉdâth"]', '["Mithredath"]', '["n-pr-m"]', 'Mithredath, the name of two Persians Mithredath.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1489}/[H1489]', 'inflected', 'heb', 'גִּזְבָּר', '["gizbâr"]', '["the/ treasurer"]', '["n-m"]', 'treasurer treasurer.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8339}/[H8339]', 'inflected', 'heb', 'שֵׁשְׁבַּצַּר', '["Shêshᵉbatstsar"]', '["to/ Sheshbazzar"]', '["n-pr-m"]', 'Sheshbatstsar, Zerubbabel''s Persian name Sheshbazzar.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0105>', 'opaque', 'heb', 'אֲגַרְטָל', '["ʼăgarṭâl"]', '["basins of"]', '["n-m"]', 'a basin charger.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4252}/[H2498]', 'lemma', 'heb', 'מַחֲלָף', '["machălâph"]', '["knives"]', '["n-m"]', 'a (sacrificial) knife (as gliding through the flesh) knife.', 'from 2498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3713A}/[H3722]', 'lemma', 'heb', 'כְּפוֹר', '["kᵉphôwr"]', '["bowls of"]', '["n-m"]', 'properly, a cover, i.e. (by implication) a tankard (or covered goblet); also white frost (as covering the ground) bason, hoar(-y) frost.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8339}/[H8339]', 'lemma', 'heb', 'שֵׁשְׁבַּצַּר', '["Shêshᵉbatstsar"]', '["Sheshbazzar"]', '["n-pr-m"]', 'Sheshbatstsar, Zerubbabel''s Persian name Sheshbazzar.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1473}/[H1540]', 'inflected', 'heb', 'גּוֹלָה', '["gôwlâh"]', '["the/ exile","the/ exile[s]"]', '["n-f"]', 'exile; concretely and collectively exiles (carried away), captive(-ity), removing.', 'or (shortened) גֹּלָה; active participle feminine of 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7628A}/[H7618]', 'inflected', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["from/ [the] captivity of"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5892B}/H9023/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["to/ own city/ his"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
