INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6876}/[H6865]', 'inflected', 'heb', 'צֹרִי', '["Tsôrîy"]', '["and/ to the/ Tyrians"]', '["a"]', 'a Tsorite or inhabitant of Tsor (i.e. Syrian) (man) of Tyre.', 'patrial from 6865;');
