INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3442P}/[H3091]', 'inflected', 'heb', 'יֵשׁוּעַ', '["Yêshûwaʻ"]', '["and/ Jeshua"]', '["n-pr-m n-pr-loc"]', 'Jeshua, the name of ten Israelites, also of a place in Palestine Jeshua.', 'for 3091; he will save;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H7628A}/[H7618]', 'inflected', 'heb', 'שְׁבִי', '["shᵉbîy"]', '["from/ the/ captivity"]', '["n-m"]', 'exiled; captured; as noun, exile (abstractly or concretely and collectively); by extension, booty captive(-ity), prisoners, × take away, that was taken.', 'from 7618;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6934}/[H6924]', 'lemma', 'heb', 'קַדְמִיאֵל', '["Qadmîyʼêl"]', '["Kadmiel"]', '["n-pr-m"]', 'Kadmiel, the name of three Israelites Kadmiel.', 'from 6924 and 410; presence of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3063L}/[H3034]', 'lemma', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2582G}/[H2580]', 'lemma', 'heb', 'חֵנָדָד', '["Chênâdâd"]', '["Henadad"]', '["n-pr-m"]', 'Chenadad, an Israelite Henadad.', 'probably from 2580 and 1908; favor of Hadad;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3245}/[H3245]', 'inflected', 'heb', 'יָסַד', '["yâçad"]', '["and/ they founded"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3034}/[H3027]', 'inflected', 'heb', 'יָדָה', '["yâdâh"]', '["and/ with/ giving thanks"]', '["v"]', 'physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving).', 'a primitive root; used only as denominative from 3027; literally, to use (i.e. hold out) the hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3245}/H9033/[H3245]', 'inflected', 'heb', 'יָסַד', '["yâçad"]', '["when/ founded/ it"]', '["v"]', 'to set (literally or figuratively); intensively, to found; reflexively, to sit down together, i.e. settle, consult appoint, take counsel, establish, (lay the, lay for a) found(-ation), instruct, lay, ordain, set, × sure.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869H}/H9028/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["with/ own eyes/ their"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8057}/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["<the>/ gladness","<the>/ happiness","the/ rejoicing"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H6963H>', 'inflected', 'heb', 'לקול', '["le./Kol","le./kOl"]', '["to/ [the] sound","to/ [the] sound of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H6963H>', 'inflected', 'heb', 'והקול', '["ve./ha./Kol"]', '["and/ the/ sound"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/{H7350}\/[H7368]', 'inflected', 'heb', 'רָחוֹק', '["râchôwq"]', '["<to>/ from/ a distance"]', '["a"]', 'remote, literally or figuratively, of place or time; specifically, precious; often used adverbially (with preposition) (a-) far (abroad, off), long ago, of old, space, great while to come.', 'or רָחֹק; from 7368;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6862C}/[H6887]', 'lemma', 'heb', 'צַר', '["tsar"]', '["[the] opponent","[the] opponents of","an opponent","enemy","opponent","opponents"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0926}/[H926]', 'inflected', 'heb', 'בָּהַל', '["bâhal"]', '["and/ I am disturbed","and/ [were] terrifying","and/ they may be dismayed","and/ they may be disturbed"]', '["v"]', 'to tremble inwardly (or palpitate), i.e. (figuratively) be (causative, make) (suddenly) alarmed or agitated; by implication to hasten anxiously be (make) affrighted (afraid, amazed, dismayed, rash), (be, get, make) haste(-n, -y, -ily), (give) speedy(-ily), thrust out, trouble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7936A}/[H3739]', 'inflected', 'heb', 'שָׂכַר', '["sâkar"]', '["and/ [were] hiring"]', '["v"]', 'to hire earn wages, hire (out self), reward, × surely.', 'or (by permutation) סָכַר; (Ezra 4:5), a primitive root (apparently akin (by prosthesis) to 3739 through the idea of temporary purchase; compare 7937);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6098}/H9028/[H3289]', 'inflected', 'heb', 'עֵצָה', '["ʻêtsâh"]', '["plan/ their","purpose/ their"]', '["n-f"]', 'advice; by implication, plan; also prudence advice, advisement, counsel([-lor]), purpose.', 'from 3289;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1867H}/[H1867]', 'lemma', 'heb', 'דָּֽרְיָוֵשׁ', '["Dârᵉyâvêsh"]', '["Darius"]', '["n-pr-m"]', 'Darejavesh, a title (rather than name) of several Persian kings Darius.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4438}/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["and/ in/ [the] reign of"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0325}/[H325]', 'lemma', 'heb', 'אֲחַשְׁוֵרוֹשׁ', '["ʼĂchashvêrôwsh"]', '["Ahasuerus"]', '["n-pr-m"]', 'Achashverosh (i.e. Ahasuerus or Artaxerxes, but in this case Xerxes), the title (rather than name) of a Persian king Ahasuerus.', 'or (shortened) אַחַשְׁרֹשׁ (Esther 10:1); of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7855}/[H7853]', 'lemma', 'heb', 'שִׂטְנָה', '["siṭnâh"]', '["an accusation"]', '["n-f"]', 'opposition (by letter) accusation.', 'from 7853;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0783A>', 'opaque', 'heb', 'אַרְתַּחְשַׁשְׁתָּא', '["ʼArtachshashtâʼ"]', '["Artaxerxes"]', '["n-pr-m"]', 'Artachshasta (or Artaxerxes), a title (rather than name) of several Persian kings Artaxerxes.', 'or אַרְתַּחְשַׁשְׁתְּא; or by permutation אַרְתַּחְשַׁסְתְּא; of foreign origin;');
