INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4990H}/[H4990]', 'lemma', 'heb', 'מִתְרְדָת', '["Mithrᵉdâth"]', '["Mithredath"]', '["n-pr-m"]', 'Mithredath, the name of two Persians Mithredath.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2870A}/[H2895]', 'lemma', 'heb', 'טָבְאֵל', '["ṭâbᵉʼêl"]', '["Tabeel"]', '["n-pr-m"]', 'Tabeel, the name of a Syrian and of a Persian Tabeal, Tabeel.', 'from 2895 and 410; pleasing (to) God;');
