INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3791}/[H3789]', 'inflected', 'heb', 'כָּתָב', '["kâthâb"]', '["and/ [the] writing of"]', '["n-m"]', 'something written, i.e. a writing, record or book register, scripture, writing.', 'from 3789;');
