INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8638}/[H7275]', 'inflected', 'heb', 'תִּרְגַּם', '["tirgam"]', '["and/ [was] translated"]', '["v"]', 'to transfer, i.e. translate interpret.', 'a denominative from 7275 in the sense of throwing over;');
