INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0251I}/H9028/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["and/ for/ brothers/ their"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/H9009/{H1473}/[H1540]', 'inflected', 'heb', 'גּוֹלָה', '["gôwlâh"]', '["from/ the/ exile"]', '["n-f"]', 'exile; concretely and collectively exiles (carried away), captive(-ity), removing.', 'or (shortened) גֹּלָה; active participle feminine of 1540;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0914}/[H914]', 'inflected', 'heb', 'בָּדַל', '["bâdal"]', '["<the>/ [one who] had separated himself","<the>/ [one who] has separated himself"]', '["v"]', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027I}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ their","hands/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4438}/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["in the/ kingdom","in/ [the] kingdom of","in/ [the] reign of"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
