INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0259}/[H258]', 'inflected', 'heb', 'אֶחָד', '["ʼechâd"]', '["and/ in/ one","and/ on/ [day] one"]', '["a"]', 'properly, united, i.e. one; or (as an ordinal) first a, alike, alone, altogether, and, any(-thing), apiece, a certain, (dai-) ly, each (one), eleven, every, few, first, highway, a man, once, one, only, other, some, together,', 'a numeral from 258;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3925G}/[H3925]', 'inflected', 'heb', 'לָמַד', '["lâmad"]', '["and/ to/ teach"]', '["v"]', 'properly, to goad, i.e. (by implication) to teach (the rod being an Oriental incentive) (un-) accustomed, × diligently, expert, instruct, learn, skilful, teach(-er, -ing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4941G}\/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ judgment"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
