INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6286A}/[H6288]', 'inflected', 'heb', 'פָּאַר', '["pâʼar"]', '["to/ beautify","to/ glorify himself","to/ glorify myself"]', '["v"]', 'to gleam, i.e. (causatively) embellish; figuratively, to boast; also to explain (i.e. make clear) oneself; to shake a tree beautify, boast self, go over the boughs, glorify (self), glory, vaunt self.', 'a primitive root; also denominative from 6288,');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3289}/H9033/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["and/ counselors/ his"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6908}/H9012/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["and/ I assembled/ !"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5973A}/H9030\/[H6004]', 'inflected', 'heb', 'עִם', '["ʻim"]', '["with/ me"]', '["prep"]', 'adverb or preposition, with (i.e. in conjunction with), in varied applications; specifically, equally with; often with prepositional prefix (and then usually unrepresented in English) accompanying, against, and, as (× long as), before, beside, by (reason of), for all, from (among, between), in, like, more than, of, (un-) to, with(-al).', 'from 6004;');
