INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0494H}/[H410]', 'inflected', 'heb', 'אֶלְנָתָן', '["ʼElnâthân"]', '["and/ for/ Elnathan"]', '["n-pr-m"]', 'Elnathan, the name of four Israelites Elnathan.', 'from 410 and 5414; God (is the) giver;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3402G}/[H3401]', 'inflected', 'heb', 'יָרִיב', '["Yârîyb"]', '["and/ for/ Jarib"]', '["n-pr-m"]', 'Jarib, the name of three Israelites Jarib.', 'the same as 3401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0494I}/[H410]', 'inflected', 'heb', 'אֶלְנָתָן', '["ʼElnâthân"]', '["and/ for/ Elnathan"]', '["n-pr-m"]', 'Elnathan, the name of four Israelites Elnathan.', 'from 410 and 5414; God (is the) giver;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5416K}/[H5414]', 'inflected', 'heb', 'נָתָן', '["Nâthân"]', '["and/ for/ Nathan"]', '["n-pr-m"]', 'Nathan, the name of five Israelites Nathan.', 'from 5414; given;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2148S}/[H2142]', 'inflected', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["and/ for/ Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4918O}/[H7999]', 'inflected', 'heb', 'מְשֻׁלָּם', '["Mᵉshullâm"]', '["and/ for/ Meshullam"]', '["n-pr-m"]', 'Meshullam, the name of seventeen Israelites Meshullam.', 'from 7999; allied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3114H}/[H3080]', 'inflected', 'heb', 'יוֹיָרִיב', '["Yôwyârîyb"]', '["and/ for/ Joiarib"]', '["n-pr-m"]', 'Jojarib, the name of four Israelites Joiarib.', 'a form of 3080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0494J}/[H410]', 'inflected', 'heb', 'אֶלְנָתָן', '["ʼElnâthân"]', '["and/ for/ Elnathan"]', '["n-pr-m"]', 'Elnathan, the name of four Israelites Elnathan.', 'from 410 and 5414; God (is the) giver;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0112>', 'opaque', 'heb', 'אִדּוֹ', '["ʼIddôw"]', '["Iddo"]', '["n-pr-m"]', 'Iddo, an Israelite Iddo.', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3703}/[H3701]', 'inflected', 'heb', 'כָּסִפְיָא', '["Kâçiphyâʼ"]', '["in/ Casiphia"]', '["n-pr-loc"]', 'Casiphja, a place in Babylon Casiphia.', 'perhaps from 3701; silvery;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760H}/H9012/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ I put/ !"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8274G}/[H8273]', 'inflected', 'heb', 'שֵׁרֵבְיָה', '["Shêrêbᵉyâh"]', '["and/ Sherebiah"]', '["n-pr-m"]', 'Sherebjah, the name of two Israelites Sherebiah.', 'from 8273 and 3050; Jah has brought heat;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2811M}/[H2803]', 'lemma', 'heb', 'חֲשַׁבְיָה', '["Chăshabyâh"]', '["Hashabiah","[were] Hashabiah"]', '["n-pr-m"]', 'Chashabjah, the name of nine Israelites Hashabiah.', 'or חֲשַׁבְיָהוּ; from 2803 and 3050; Jah has regarded;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3470J}/[H3467]', 'lemma', 'heb', 'יְשַׁעְיָה', '["Yᵉshaʻyâh"]', '["Jeshaiah"]', '["n-pr-m"]', 'Jeshajah, the name of seven Israelites Isaiah, Jesaiah, Jeshaiah.', 'or יְשַׁעְיָהוּ; from 3467 and 3050; Jah has saved;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6242}\/[H6235]', 'inflected', 'heb', 'עֶשְׂרִים', '["ʻesrîym"]', '["twenty"]', '["n"]', 'twenty; also (ordinal) twentieth (six-) score, twenty(-ieth).', 'from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9007/{H5414H}/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["whom/ he had appointed"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5411}/[H5414]', 'lemma', 'heb', 'נָתִין', '["Nâthîyn"]', '["temple servants"]', '["n-m"]', 'the Nethinim, or Temple-servants (as given to that duty) Nethinims.', 'or נָתוּן (Ezra 8:17), (the proper form as passive participle), from 5414; one given, i.e. (in the plural only)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3477I}/[H3474]', 'lemma', 'heb', 'יָשָׁר', '["yâshâr"]', '["[were] straight","straight"]', '["a"]', 'straight (literally or figuratively) convenient, equity, Jasher, just, meet(-est), pleased well right(-eous), straight, (most) upright(-ly, -ness).', 'from 3474;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2945}/H9025/[H2952]', 'inflected', 'heb', 'טַף', '["ṭaph"]', '["and/ for/ little one[s]/ our"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7399}/H9025/[H7408]', 'inflected', 'heb', 'רְכוּשׁ', '["rᵉkûwsh"]', '["property/ our"]', '["n-m"]', 'property (as gathered) good, riches, substance.', 'or רְכֻשׁ; from passive participle of 7408;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0341}/[H340]', 'inflected', 'heb', 'אֹיֵב', '["ʼôyêb"]', '["[will be] from/ [the] enemies","from/ an enemy"]', '["n-m"]', 'hating; an adversary enemy, foe.', 'or (fully) אוֹיֵב; active participle of 340;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0639G}/H9023/[H599]', 'inflected', 'heb', 'אַף', '["ʼaph"]', '["and/ anger/ his"]', '["n-m"]', 'properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, × worthy, wrath.', 'from 599;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6684}/H9012/[H6684]', 'inflected', 'heb', 'צוּם', '["tsûwm"]', '["and/ we fasted/ !"]', '["v"]', 'to cover over (the mouth), i.e. to fast × at all, fast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1245}/H9012/[H1245]', 'inflected', 'heb', 'בָּקַשׁ', '["bâqash"]', '["and/ I sought/ !","and/ we sought/ !"]', '["v"]', 'to search out (by any method, specifically in worship or prayer); by implication, to strive after ask, beg, beseech, desire, enquire, get, make inquisition, procure, (make) request, require, seek (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0430G}/H9025/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["from/ God/ our"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0914}/H9012/[H914]', 'inflected', 'heb', 'בָּדַל', '["bâdal"]', '["and/ I set apart/ !"]', '["v"]', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8274G}/[H8273]', 'inflected', 'heb', 'שֵׁרֵבְיָה', '["Shêrêbᵉyâh"]', '["to/ Sherebiah"]', '["n-pr-m"]', 'Sherebjah, the name of two Israelites Sherebiah.', 'from 8273 and 3050; Jah has brought heat;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8254}/H9012/[H8254]', 'inflected', 'heb', 'שָׁקַל', '["shâqal"]', '["and/ I weighed out/ !"]', '["v"]', 'to suspend or poise (especially in trade) pay, receive(-r), spend, × throughly, weigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0150}/[H150]', 'inflected', 'heb', 'אֲדַרְכֹּן', '["ʼădarkôn"]', '["of/ darics"]', '["n-m"]', 'a daric or Persian coin dram.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6668}/[H6668]', 'lemma', 'heb', 'צָהַב', '["tsâhab"]', '["gleaming"]', '["v"]', 'to glitter, i.e. be golden in color × fine.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/<H2091>', 'inflected', 'heb', 'כזהב', '["ka./za.Hav"]', '["like <the>/ gold"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3627}/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["and/ the/ utensils","and/ the/ vessels"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8245}/[H8245]', 'lemma', 'heb', 'שָׁקַד', '["shâqad"]', '["I am wakeful","I kept watch","I will keep watch","[am] watching","[those who] lie in wait","[will be] watching","he has kept awake","someone will keep watch","watch"]', '["v"]', 'to be alert, i.e. sleepless; hence to be on the lookout (whether for good or ill) hasten, remain, wake, watch (for).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5265}/H9012/[H5265]', 'inflected', 'heb', 'נָסַע', '["nâçaʻ"]', '["and/ we set out/ !"]', '["v"]', 'properly, to pull up, especially the tent-pins, i.e. start on a journey cause to blow, bring, get, (make to) go (away, forth, forward, onward, out), (take) journey, march, remove, set aside (forward), × still, be on his (go their) way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5337}/H9035/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ he delivered/ us"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4822G}/[H7311]', 'lemma', 'heb', 'מְרֵמוֹת', '["Mᵉrêmôwth"]', '["Meremoth"]', '["n-pr-m"]', 'Meremoth, the name of two Israelites Meremoth.', 'plural from 7311; heights;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0223H}/[H217]', 'lemma', 'heb', 'אוּרִיָּה', '["ʼÛwrîyâh"]', '["Uriah"]', '["n-pr-m"]', 'Urijah, the name of one Hittite and five Israelites Uriah, Urijah.', 'or (prolonged) אוּרִיָּהוּ ; from 217 and 3050; flame of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0499K}/[H410]', 'lemma', 'heb', 'אֶלְעָזָר', '["ʼElʻâzâr"]', '["Eleazar"]', '["n-pr-m"]', 'Elazar, the name of seven Israelites Eleazar.', 'from 410 and 5826; God (is) helper;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6372I}/[H6310]', 'lemma', 'heb', 'פִּינְחָס', '["Pîynᵉchâç"]', '["Phinehas"]', '["n-pr-m"]', 'Pinechas, the name of three Israelites Phinehas.', 'apparently from 6310 and a variation of 5175; mouth of a serpent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3107M}/[H3075]', 'lemma', 'heb', 'יוֹזָבָד', '["Yôwzâbâd"]', '["Jozabad"]', '["n-pr-m"]', 'Jozabad, the name of ten Israelites Josabad, Jozabad.', 'a form of 3075;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3442K}/[H3091]', 'lemma', 'heb', 'יֵשׁוּעַ', '["Yêshûwaʻ"]', '["Jeshua"]', '["n-pr-m n-pr-loc"]', 'Jeshua, the name of ten Israelites, also of a place in Palestine Jeshua.', 'for 3091; he will save;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5129G}/[H3259]', 'inflected', 'heb', 'נוֹעַדְיָה', '["Nôwʻadyâh"]', '["and/ Noadiah"]', '["n-pr-m n-pr-f"]', 'Noadjah, the name of an Israelite, and a false prophetess Noadiah.', 'from 3259 and 3050; convened of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1131H}/[H1129]', 'lemma', 'heb', 'בִּנּוּי', '["Binnûwy"]', '["Binnui"]', '["n-pr-m"]', 'Binnui, an Israelite Binnui.', 'from 1129; built up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4948}/[H8254]', 'inflected', 'heb', 'מִשְׁקָל', '["mishqâl"]', '["the/ weight"]', '["n-m"]', 'weight (numerically estimated); hence, weighing (the act) (full) weight.', 'from 8254;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6842}/[H6852]', 'lemma', 'heb', 'צָפִיר', '["tsâphîyr"]', '["[the] he-goat of","he-goats of"]', '["n-m"]', 'a male goat (as prancing) (he) goat.', 'from 6852;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1881}/[H1881]', 'lemma', 'heb', 'דָּת', '["dâth"]', '["<of> law","[the] decrees of","[the] law","[the] laws of","law"]', '["n-f"]', 'a royal edict or statute commandment, commission, decree, law, manner.', 'of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0323}/[H323]', 'inflected', 'heb', 'אֲחַשְׁדַּרְפַּן', '["ʼăchashdarpan"]', '["to/ [the] satraps of"]', '["n-m"]', 'a satrap or governor of a main province (of Persia) lieutenant.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375K}/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ they supported"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8441}/H9028/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["according to/ abominations/ their"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H1323G}/H9028/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["any of/ daughters/ their","some of/ daughters/ their"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6148}/[H6148]', 'inflected', 'heb', 'עָרַב', '["ʻârab"]', '["and/ they have mixed themselves","and/ they mixed themselves"]', '["v"]', 'to braid, i.e. intermix; technically, to traffic (as if by barter); also or give to be security (as a kind of exchange) engage, (inter-) meddle (with), mingle (self), mortgage, occupy, give pledges, be(-come, put in) surety, undertake.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H5461>', 'inflected', 'heb', 'והסגנים', '["ve./ha./se.ga.Nim"]', '["and/ the/ officials"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7223I}\/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["first"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H8085G}/H9040/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["and/ just as/ heard/ I"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0899B}/H9020/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["clothes/ my","garment/ my","garments/ my"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4598}/H9020/[H4603]', 'inflected', 'heb', 'מְעִיל', '["mᵉʻîyl"]', '["and/ robe/ my"]', '["n-m"]', 'a robe (i.e. upper and outer garment) cloke, coat, mantle, robe.', 'from 4603 in the sense of covering;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4803}/H9012/[H4803]', 'inflected', 'heb', 'מָרַט', '["mâraṭ"]', '["and/ I pulled out/ !"]', '["v"]', 'to polish; by implication, to make bald (the head), to gall (the shoulder); also, to sharpen bright, furbish, (have his) hair (be) fallen off, peeled, pluck off (hair).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8181}/[H8175]', 'inflected', 'heb', 'שֵׂעָר', '["sêʻâr"]', '["some of/ [the] hair of"]', '["n-m"]', 'hair (as if tossed or bristling) hair(-y), × rough.', 'or שַׂעַר; (Isaiah 7:20), from 8175 in the sense of dishevelling;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2206}/H9020/[H2204]', 'inflected', 'heb', 'זָקָן', '["zâqân"]', '["and/ beard/ my"]', '["n-m"]', 'the beard (as indicating age) beard.', 'from 2204;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3427}/H9012/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["and/ I sat down/ !"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0413}/H9030/[H413]', 'inflected', 'heb', 'אֵל', '["ʼêl"]', '["and/ against/ me","and/ to/ me"]', '["prep"]', 'near, with or among; often in general, to about, according to, after, against, among, as for, at, because(-fore, -side), both...and, by, concerning, for, from, × hath, in(-to), near, (out) of, over, through, to(-ward), under, unto, upon, whether, with(-in).', '(but only used in the shortened constructive form אֶל ); a primitive particle; properly, denoting motion towards, but occasionally used of a quiescent position, i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8589}/H9020/[H6031]', 'inflected', 'heb', 'תַּעֲנִית', '["taʻănîyth"]', '["from/ humiliation/ my"]', '["n-f"]', 'affliction (of self), i.e. fasting heaviness.', 'from 6031;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7167}/H9040/[H7167]', 'inflected', 'heb', 'קָרַע', '["qâraʻ"]', '["and/ in/ tearing of/ my"]', '["v"]', 'to rend, literally or figuratively (revile, paint the eyes, as if enlarging them) cut out, rend, × surely, tear.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3766}/H9012/[H3766]', 'inflected', 'heb', 'כָּרַע', '["kâraʻ"]', '["and/ I bowed down/ !"]', '["v"]', 'to bend the knee; by implication, to sink, to prostrate bow (down, self), bring down (low), cast down, couch, fall, feeble, kneeling, sink, smite (stoop) down, subdue, × very.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H6566}/H9012/[H6566]', 'inflected', 'heb', 'פָּרַשׂ', '["pâras"]', '["and/ I spread out/ !"]', '["v"]', 'to break apart, disperse, etc. break, chop in pieces, lay open, scatter, spread (abroad, forth, selves, out), stretch (forth, out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3637}/[H3637]', 'inflected', 'heb', 'כָּלַם', '["kâlam"]', '["and/ I am humiliated","and/ be humiliated","and/ may they be humiliated","and/ they are humiliated","and/ they may be humiliated","and/ they may be put to shame","and/ to be ashamed","so/ they may be ashamed"]', '["v"]', 'properly, to wound; but only figuratively, to taunt or insult be (make) ashamed, blush, be confounded, be put to confusion, hurt, reproach, (do, put to) shame.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771G}/H9025/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["[is] iniquity/ our","iniquities/ our","iniquity/ our"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0819}/H9025/[H817]', 'inflected', 'heb', 'אַשְׁמָה', '["ʼashmâh"]', '["and/ guilt/ our"]', '["n-f"]', 'guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering).', 'feminine of 817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0819}/[H817]', 'inflected', 'heb', 'אַשְׁמָה', '["ʼashmâh"]', '["[have been] in/ guilt","by/ [the] guilt of"]', '["n-f"]', 'guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering).', 'feminine of 817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5771G}/H9025/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["and/ in/ iniquities/ our"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3548}/H9025/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["priests/ our"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0961}/[H957]', 'inflected', 'heb', 'בִּזָּה', '["bizzâh"]', '["and/ by <the>/ plunder","and/ by/ plunder","and/ on the/ plunder"]', '["n-f"]', 'booty prey, spoil.', 'feminine of 957;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H1322}/[H954]', 'inflected', 'heb', 'בֹּשֶׁת', '["bôsheth"]', '["and/ by/ shame of"]', '["n-f"]', 'shame (the feeling and the condition, as well as its cause); by implication (specifically) an idol ashamed, confusion, greatly, (put to) shame(-ful thing).', 'from 954;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7604}/[H7604]', 'inflected', 'heb', 'שָׁאַר', '["shâʼar"]', '["to/ leave"]', '["v"]', 'properly, to swell up, i.e. be (causatively, make) redundant leave, (be) left, let, remain, remnant, reserve, the rest.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5414G}/H9035/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ to/ give to/ us"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5659}/H9025/[H5647]', 'inflected', 'heb', 'עַבְדוּת', '["ʻabdûwth"]', '["in/ servitude/ our"]', '["n-f"]', 'servitude bondage.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5659}/H9025/[H5647]', 'inflected', 'heb', 'עַבְדוּת', '["ʻabdûwth"]', '["and/ in/ servitude/ our"]', '["n-f"]', 'servitude bondage.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5975I}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ to/ set up"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2723}/H9023/[H2721]', 'inflected', 'heb', 'חׇרְבָּה', '["chorbâh"]', '["ruins/ its"]', '["n-f"]', 'properly, drought, i.e. (by implication) a desolation decayed place, desolate (place, -tion), destruction, (laid) waste (place).', 'feminine of 2721;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3063N}/[H3034]', 'inflected', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["in/ Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3389}\/[H3390]', 'inflected', 'heb', 'יְרוּשָׁלִַ͏ם', '["Yᵉrûwshâlaim"]', '["and/ in/ Jerusalem"]', '["n-pr-loc"]', 'Jerushalaim or Jerushalem, the capital city of Palestine Jerusalem.', 'rarely יְרוּשָׁלַיִם; a dual (in allusion to its two main hills (the true pointing, at least of the former reading, seems to be that of 3390)); probably from (the passive participle of) 3384 and 7999; founded peaceful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8441}/H9028/[H8581]', 'inflected', 'heb', 'תּוֹעֵבַה', '["tôwʻêbah"]', '["by/ abominations/ their"]', '["n-f"]', 'properly, something disgusting (morally), i.e. (as noun) an abhorrence; especially idolatry or (concretely) an idol abominable (custom, thing), abomination.', 'or תֹּעֵבַה; feminine active participle of 8581;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4390}/H9034/[H4390]', 'inflected', 'heb', 'מָלֵא', '["mâlêʼ"]', '["they have filled/ it"]', '["v"]', 'to fill or (intransitively) be full of, in a wide application (literally and figuratively) accomplish, confirm, consecrate, be at an end, be expired, be fenced, fill, fulfil, (be, become, × draw, give in, go) full(-ly, -ly set, tale), (over-) flow, fulness, furnish, gather (selves, together), presume, replenish, satisfy, set, space, take a (hand-) full, have wholly.', 'or מָלָא; (Esther 7:5), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310H}/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["from/ mouth"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4639K}/H9025/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["by/ deeds/ our"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H0819}/H9025/[H817]', 'inflected', 'heb', 'אַשְׁמָה', '["ʼashmâh"]', '["and/ by/ guilt/ our"]', '["n-f"]', 'guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering).', 'feminine of 817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5771G}/H9025/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["from/ iniquities/ our","from/ iniquity/ our"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H7725J}/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["¿/ will we return"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2859B}/[H2859]', 'inflected', 'heb', 'חָתַן', '["châthan"]', '["and/ to/ intermarry"]', '["v"]', 'to give (a daughter) away in marriage; hence (generally) to contract affinity by marriage join in affinity, father in law, make marriages, mother in law, son in law.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6413}\/[H6412]', 'inflected', 'heb', 'פְּלֵיטָה', '["pᵉlêyṭâh"]', '["and/ an escaped remnant"]', '["n-f"]', 'deliverance; concretely, an escaped portion deliverance, (that is) escape(-d), remnant.', 'or פְּלֵטָה; feminine of 6412;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0819}/H9025/[H817]', 'inflected', 'heb', 'אַשְׁמָה', '["ʼashmâh"]', '["in/ guilt/ our"]', '["n-f"]', 'guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering).', 'feminine of 817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6419}/[H6419]', 'inflected', 'heb', 'פָּלַל', '["pâlal"]', '["and/ just as/ was praying"]', '["v"]', 'to judge (officially or mentally); by extension, to intercede, pray intreat, judge(-ment), (make) pray(-er, -ing), make supplication.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3034}/H9043/[H3027]', 'inflected', 'heb', 'יָדָה', '["yâdâh"]', '["and/ just as/ was confessing/ he"]', '["v"]', 'physically, to throw (a stone, an arrow) at or away; especially to revere or worship (with extended hands); intensively, to bemoan (by wringing the hands) cast (out), (make) confess(-ion), praise, shoot, (give) thank(-ful, -s, -sgiving).', 'a primitive root; used only as denominative from 3027; literally, to use (i.e. hold out) the hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1059}\/[H1058]', 'inflected', 'heb', 'בֶּכֶה', '["bekeh"]', '["weeping"]', '["n-m"]', 'a weeping × sore.', 'from 1058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7935L}/[H7931]', 'lemma', 'heb', 'שְׁכַנְיָה', '["Shᵉkanyâh"]', '["Shecaniah"]', '["n-pr-m"]', 'Shekanjah, the name of nine Israelites Shecaniah, Shechaniah.', 'or (prolonged) שְׁכַנְיָהוּ; from 7931 and 3050; Jah has dwelt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3171O}/[H2421]', 'lemma', 'heb', 'יְחִיאֵל', '["Yᵉchîyʼêl"]', '["Jehiel"]', '["n-pr-m"]', 'Jechiel (or Jechavel), the name of eight Israelites Jehiel.', 'or (2 Chronicles 29:14) יְחַוְאֵל; from 2421 and 410; God will live;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0430G}/H9025/[H433]', 'inflected', 'heb', 'אֱלֹהִים', '["ʼĕlôhîym"]', '["against/ God/ our"]', '["n-m"]', 'gods in the ordinary sense; but specifically used (in the plural thus, especially with the article) of the supreme God; occasionally applied by way of deference to magistrates; and sometimes as a superlative angels, × exceeding, God (gods) (-dess, -ly), × (very) great, judges, × mighty.', 'plural of 433;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3205}/[H3205]', 'inflected', 'heb', 'יָלַד', '["yâlad"]', '["and/ those/ born"]', '["v"]', 'to bear young; causatively, to beget; medically, to act as midwife; specifically, to show lineage bear, beget, birth(-day), born, (make to) bring forth (children, young), bring up, calve, child, come, be delivered (of a child), time of delivery, gender, hatch, labour, (do the office of a) midwife, declare pedigrees, be the son of, (woman in, woman that) travail(-eth, -ing woman).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H2730}/[H2729]', 'inflected', 'heb', 'חָרֵד', '["chârêd"]', '["and/ the/ [people] trembling"]', '["a"]', 'fearful; also reverential afraid, trembling.', 'from 2729;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3076M}/[H3068]', 'lemma', 'heb', 'יְהוֹחָנָן', '["Yᵉhôwchânân"]', '["Jehohanan"]', '["n-pr-m"]', 'Jehochanan, the name of eight Israelites Jehohanan, Johanan. Compare 3110.', 'from 3068 and 2603; Jehovah-favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0475I}/[H410]', 'lemma', 'heb', 'אֶלְיָשִׁיב', '["ʼElyâshîyb"]', '["Eliashib"]', '["n-pr-m"]', 'Eljashib, the name of six Israelites Eliashib.', 'from 410 and 7725; God will restore;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6908}/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["to/ assemble","to/ gather"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6951}/[H6950]', 'inflected', 'heb', 'קָהָל', '["qâhâl"]', '["from/ [the] assembly of"]', '["n-m"]', 'assemblage (usually concretely) assembly, company, congregation, multitude.', 'from 6950;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7460}/[H7460]', 'lemma', 'heb', 'רָעַד', '["râʻad"]', '["trembling"]', '["v"]', 'to shudder (more or less violently) tremble.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/H9009/{H1653}\/[H1652]', 'inflected', 'heb', 'גֶּשֶׁם', '["geshem"]', '["and/ from/ the/ rains"]', '["n-m"]', 'a shower rain, shower.', 'from 1652;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7522}/H9023/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["<of> will/ his","[are] delight/ his","[is] pleasure/ his","delight/ his","favor/ his","will/ his"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0914}/[H914]', 'inflected', 'heb', 'בָּדַל', '["bâdal"]', '["and/ separate yourselves"]', '["v"]', 'to divide (in variation senses literally or figuratively, separate, distinguish, differ, select, etc.) (make, put) difference, divide (asunder), (make) separate (self, -ation), sever (out), × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6586}/[H6586]', 'inflected', 'heb', 'פָּשַׁע', '["pâshaʻ"]', '["to/ transgress"]', '["v"]', 'to break away (from just authority), i.e. trespass, apostatize, quarrel offend, rebel, revolt, transgress(-ion, -or).', 'a primitive root (identical with through the idea of expansion);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8269}/H9025/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["leaders/ our"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5892B}/H9025/[H5782]', 'inflected', 'heb', 'עִיר', '["ʻîyr"]', '["[is] in <the>/ cities/ our"]', '["n-m"]', 'a city (a place guarded by waking or a watch) in the widest sense (even of a mere encampment or post) Ai (from margin), city, court (from margin), town.', 'or (in the plural) עָר; or עָיַר; (Judges 10:4), from 5782');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2163}/[H2163]', 'lemma', 'heb', 'זָמַן', '["zâman"]', '["appointed"]', '["v"]', 'to fix (a time) appoint.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8199}/H9034/[H8199]', 'inflected', 'heb', 'שָׁפַט', '["shâphaṭ"]', '["and/ judges/ its"]', '["v"]', 'to judge, i.e. pronounce sentence (for or against); by implication, to vindicate or punish; by extenssion, to govern; passively, to litigate (literally or figuratively) avenge, × that condemn, contend, defend, execute (judgment), (be a) judge(-ment), × needs, plead, reason, rule.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3129I}/[H3083]', 'lemma', 'heb', 'יוֹנָתָן', '["Yôwnâthân"]', '["Jonathan"]', '["n-pr-m"]', 'Jonathan, the name of ten Israelites Jonathan.', 'a form of 3083;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6214J}/[H6213]', 'lemma', 'heb', 'עֲשָׂהאֵל', '["ʻĂsâhʼêl"]', '["Asahel"]', '["n-pr-m"]', 'Asahel, the name of four Israelites Asahel.', 'from 6213 and 410; God has made;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3167}/[H2372]', 'inflected', 'heb', 'יַחְזְיָה', '["Yachzᵉyâh"]', '["and/ Jahzeiah"]', '["n-pr-m"]', 'Jachzejah, an Israelite Jahaziah.', 'from 2372 and 3050; Jah will behold;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8616H}/[H8615]', 'lemma', 'heb', 'תִּקְוָה', '["Tiqvâh"]', '["Tikvah"]', '["n-pr-m"]', 'Tikvah, the name of two Israelites Tikvah.', 'the same as 8615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4918P}/[H7999]', 'inflected', 'heb', 'מְשֻׁלָּם', '["Mᵉshullâm"]', '["and/ Meshullam"]', '["n-pr-m"]', 'Meshullam, the name of seventeen Israelites Meshullam.', 'from 7999; allied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7678G}/[H7676]', 'inflected', 'heb', 'שַׁבְּתַי', '["Shabbᵉthay"]', '["and/ Shabbethai"]', '["n-pr-m"]', 'Shabbethai, the name of three Israelites Shabbethai.', 'from 7676; restful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7223G}\/[H7221]', 'inflected', 'heb', 'רִאשׁוֹן', '["riʼshôwn"]', '["<the>/ first"]', '["a"]', 'first, in place, time or rank (as adjective or noun) ancestor, (that were) before(-time), beginning, eldest, first, fore(-father) (-most), former (thing), of old time, past.', 'or רִאשֹׁן; from 7221;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3136G}/[H3087]', 'lemma', 'heb', 'יוֹצָדָק', '["Yôwtsâdâq"]', '["Jozadak"]', '["n-pr-m"]', 'Jotsadak, an Israelite Jozadak.', 'a form of 3087;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4641L}/[H4639]', 'lemma', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0461N}/[H410]', 'inflected', 'heb', 'אֱלִיעֶזֶר', '["ʼĔlîyʻezer"]', '["and/ Eliezer"]', '["n-pr-m"]', 'Eliezer, the name of a Damascene and of ten Israelites Eliezer.', 'from 410 and 5828; God of help;');
