INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0818}/[H816]', 'inflected', 'heb', 'אָשֵׁם', '["ʼâshêm"]', '["and/ [being] guilty"]', '["a"]', 'guilty; hence, presenting a sin-offering one which is faulty, guilty.', 'from 816;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0819}/H9028\/[H817]', 'inflected', 'heb', 'אַשְׁמָה', '["ʼashmâh"]', '["guilt/ their"]', '["n-f"]', 'guiltiness, a fault, the presentation of a sin-offering offend, sin, (cause of) trespass(-ing, offering).', 'feminine of 817;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2607I}/[H2603]', 'lemma', 'heb', 'חֲנָנִי', '["Chănânîy"]', '["Hanani"]', '["n-pr-m"]', 'Chanani, the name of six Israelites Hanani.', 'from 2603; gracious;');
