INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8098P}/[H8085]', 'inflected', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["and/ Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
