INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5818J}/[H5797]', 'inflected', 'heb', 'עֻזִּיָּה', '["ʻUzzîyâh"]', '["and/ Uzziah"]', '["n-pr-m"]', 'Uzzijah, the name of five Israelites Uzziah.', 'or עֻזִּיָּהוּ; from 5797 and 3050; strength of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0454J}/[H413]', 'lemma', 'heb', 'אֶלְיְהוֹעֵינַי', '["ʼElyᵉhôwʻêynay"]', '["Elioenai"]', '["n-pr-m"]', 'Eljehoenai or Eljoenai, the name of seven Israelites Elihoenai, Elionai.', 'or (shortened) אֶלְיוֹעֵינַי; from 413 and 3068 and 5869; towards Jehovah (are) my eyes;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4641N}/[H4639]', 'lemma', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
