INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H0251I}/H9020/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["of/ brothers/ my"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4082}/[H1777]', 'inflected', 'heb', 'מְדִינָה', '["mᵉdîynâh"]', '["[were] in/ [the] provinces of","among the/ provinces","in the/ province"]', '["n-f"]', 'properly, a judgeship, i.e. jurisdiction; by implication, a district (as ruled by a judge); generally, a region (× every) province.', 'from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2781}/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["and/ in/ disgrace"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H2346G>', 'inflected', 'heb', 'וחומת', '["ve./cho.Mah","ve./cho.Mat"]', '["and/ [the] wall of","and/ wall"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8179G}/H9024/[H8176]', 'inflected', 'heb', 'שַׁעַר', '["shaʻar"]', '["and/ gates/ its"]', '["n-m"]', 'an opening, i.e. door or gate city, door, gate, port (× -er).', 'from 8176 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H8085G}/H9040/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["when/ heard/ I"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0056}/H9012/[H56]', 'inflected', 'heb', 'אָבַל', '["ʼâbal"]', '["and/ I mourned/ !"]', '["v"]', 'to bewail lament, mourn.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2617A}/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["and/ [the] covenant loyalty of","and/ covenant loyalty","and/ favor","and/ loyalty"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7183A}/[H7181]', 'lemma', 'heb', 'קַשָּׁב', '["qashshâb"]', '["attentive"]', '["a"]', 'hearkening attent(-ive).', 'or קַשֻּׁב; from 7181;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2254B}/[H2254]', 'lemma', 'heb', 'חָבַל', '["châbal"]', '["I will act corruptly","[which] ruin","he will be pledged","it is broken","it will destroy","surely <to act corruptly>","we have acted corruptly"]', '["v"]', 'to wind tightly (as a rope), i.e. to bind; specifically, by a pledge; figuratively, to pervert, destroy; also to writhe in pain (especially of parturition) × at all, band, bring forth, (deal) corrupt(-ly), destroy, offend, lay to (take a) pledge, spoil, travail, × very, withhold.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5080}/H9036/[H5080]', 'inflected', 'heb', 'נָדַח', '["nâdach"]', '["banished [one]/ your"]', '["v"]', 'to push off; used in a great variety of applications, literally and figuratively (to expel, mislead, strike, inflict, etc.) banish, bring, cast down (out), chase, compel, draw away, drive (away, out, quite), fetch a stroke, force, go away, outcast, thrust away (out), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6908}/H9038/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["I will gather/ them","[will be] gathering/ them","he has gathered/ them","it will gather/ them"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6743B}/H9012/[H6743]', 'inflected', 'heb', 'צָלַח', '["tsâlach"]', '["and/ grant success/ !"]', '["v"]', 'to push forward, in various senses (literal or figurative, transitive or intransitive) break out, come (mightily), go over, be good, be meet, be profitable, (cause to, effect, make to, send) prosper(-ity, -ous, -ously).', 'or צָלֵחַ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5212>', 'opaque', 'heb', 'נִיסָן', '["Nîyçân"]', '["Nisan"]', '["n"]', 'Nisan, the first month of the Jewish sacred year Nisan.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004A}/[H1129]', 'lemma', 'heb', 'בַּיִת', '["bayith"]', '["[the] house of","between"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2720B}/[H2717]', 'lemma', 'heb', 'חָרֵב', '["chârêb"]', '["[is] desolate"]', '["a"]', 'parched or ruined desolate, dry, waste.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1129}/H9034/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["and/ I will rebuild/ it"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7694}/[H7693]', 'inflected', 'heb', 'שֵׁגָל', '["shêgâl"]', '["and/ the/ queen-consort"]', '["n-f"]', 'a queen (from cohabitation) queen.', 'from 7693;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0681}/H9033/[H680]', 'inflected', 'heb', 'אֵצֶל', '["ʼêtsel"]', '["[was] beside/ him","beside/ him","beside/ it"]', '["n-m"]', 'a side; (as a preposition) near at, (hard) by, (from) (beside), near (unto), toward, with. See also 1018.', 'from 680 (in the sense of joining);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4109}/H9021/[H1980]', 'inflected', 'heb', 'מַהֲלָךְ', '["mahălâk"]', '["journey/ your"]', '["n-m"]', 'a walk, i.e. a passage or a distance journey, walk.', 'from 1980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H4970>', 'inflected', 'heb', 'ומתי', '["u./ma.Tai"]', '["and/ when?"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2165}/[H2163]', 'lemma', 'heb', 'זְמָן', '["zᵉmân"]', '["a time","an appointed time"]', '["n-m"]', 'an appointed occasion season, time.', 'from 2163;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5674A}/H9030/[H5674]', 'inflected', 'heb', 'עָבַר', '["ʻâbar"]', '["they will allow to pass through/ me"]', '["v"]', 'to cross over; used very widely of any transition (literal or figurative; transitive, intransitive, intensive, causative); specifically, to cover (in copulation) alienate, alter, × at all, beyond, bring (over, through), carry over, (over-) come (on, over), conduct (over), convey over, current, deliver, do away, enter, escape, fail, gender, get over, (make) go (away, beyond, by, forth, his way, in, on, over, through), have away (more), lay, meddle, overrun, make partition, (cause to, give, make to, over) pass(-age, along, away, beyond, by, -enger, on, out, over, through), (cause to, make) proclaim(-amation), perish, provoke to anger, put away, rage, raiser of taxes, remove, send over, set apart, shave, cause to (make) sound, × speedily, × sweet smelling, take (away), (make to) transgress(-or), translate, turn away, (way-) faring man, be wrath.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0107}/[H104]', 'inflected', 'heb', 'אִגֶּרֶת', '["ʼiggereth"]', '["and/ a letter"]', '["n-f"]', 'an epistle letter.', 'feminine of 104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0623J}/[H622]', 'lemma', 'heb', 'אָסָף', '["ʼÂçâph"]', '["Asaph"]', '["n-pr-m"]', 'Asaph, the name of three Israelites, and of the family of the first Asaph.', 'from 622; collector;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6508>', 'inflected', 'heb', 'הפרדס', '["ha./par.Des"]', '["the/ forest"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7136B}/[H7136]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["to/ make beams for"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H2346G>', 'inflected', 'heb', 'ולחומת', '["u./le./cho.Mat","u./le./cho.Mot"]', '["and/ for/ [the] wall of","and/ into/ walls of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6571B}\/[H6567]', 'inflected', 'heb', 'פָּרָשׁ', '["pârâsh"]', '["and/ horsemen"]', '["n-m"]', 'a steed (as stretched out to a vehicle, not single nor for mounting ); also (by implication) a driver (in a chariot), i.e. (collectively) cavalry horseman.', 'from 6567; (compare 5483)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H5571>', 'opaque', 'heb', 'סַנְבַלַּט', '["Çanballaṭ"]', '["Sanballat"]', '["n-pr-m"]', 'Sanballat, a Persian satrap of Samaria Sanballat.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2772}/[H2773]', 'inflected', 'heb', 'חֹרֹנִי', '["Chôrônîy"]', '["the/ Horonite"]', '["n-m"]', 'a Choronite or inhabitant of Choronaim Horonite.', 'patrial from 2773;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2900I}/[H2896]', 'inflected', 'heb', 'טוֹבִיָּה', '["Ṭôwbîyâh"]', '["and/ Tobiah"]', '["n-pr-m"]', 'Tobijah, the name of three Israelites and of one Samaritan Tobiah, Tobijah.', 'or טוֹבִיָּהוּ; from 2896 and 3050; goodness of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3318G}/H9012/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["and/ I went out/ !"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5869G}/[H5869]', 'lemma', 'heb', 'עַיִן', '["ʻayin"]', '["[the] Spring of"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8577B}/[H8565]', 'lemma', 'heb', 'תַּנִּין', '["tannîyn"]', '["[the] Dragons"]', '["n-m"]', 'a marine or land monster, i.e. sea-serpent or jackal dragon, sea-monster, serpent, whale.', 'or תַּנִּים; (Ezekiel 29:3), intensive from the same as 8565;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0830G}/[H827]', 'inflected', 'heb', 'אַשְׁפֹּת', '["ʼashpôth"]', '["the/ dung"]', '["n-m"]', 'a heap of rubbish or filth dung (hill).', 'or אַשְׁפּוֹת; or שְׁפֹת; (contraction) plural of a noun of the same form as 827, from 8192 (in the sense of scraping);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7663A}/[H7663]', 'lemma', 'heb', 'שָׂבַר', '["sâbar"]', '["examining"]', '["v"]', 'to scrutinize; by implication (of watching) to expect (with hope and patience) hope, tarry, view, wait.', 'erroneously שָׁבַר; (Nehemiah 2:13,15), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1992}/ /{H6555}/[H1931]', 'inflected', 'heb', 'הֵם', '["hêm"]', '["they/ /[were] broken down"]', '["p"]', 'they (only used when emphatic) it, like, × (how, so) many (soever, more as) they (be), (the) same, × so, × such, their, them, these, they, those, which, who, whom, withal, ye.', 'or (prolonged) הֵמָּה; masculine plural from 1931;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5869B}/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["the/ spring"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1295G}/[H1288]', 'lemma', 'heb', 'בְּרֵכָה', '["bᵉrêkâh"]', '["[the] pool of"]', '["n-f"]', 'a reservoir (at which camels kneel as a resting-place) (fish-) pool.', 'from 1288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4428J}/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["the/ king"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0929>', 'inflected', 'heb', 'לבהמה', '["la./be.he.Mah","li/v.he.Mah"]', '["for the/ animal","for the/ cattle","to/ animal[s]"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3064}/[H3063]', 'inflected', 'heb', 'יְהוּדִי', '["Yᵉhûwdîy"]', '["and/ to the/ Jews"]', '["n-m"]', 'a Jehudite (i.e. Judaite or Jew), or descendant of Jehudah (i.e. Judah) Jew.', 'patronymically from 3063;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H2715}/[H2787]', 'inflected', 'heb', 'חֹר', '["chôr"]', '["and/ to the/ nobles"]', '["n-m"]', 'properly, white or pure (from the cleansing or shining power of fire); hence (figuratively) noble (in rank) noble.', 'or (fully) חוֹר; from 2787; (compare 2751)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H5461>', 'inflected', 'heb', 'ולסגנים', '["ve./la./se.ga.Nim"]', '["and/ to the/ officials"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3499A}/[H3498]', 'inflected', 'heb', 'יֶתֶר', '["yether"]', '["and/ by/ [the] rest of","and/ to/ [the] rest","and/ to/ [the] rest of"]', '["n-m"]', 'properly, an overhanging, i.e. (by implication) an excess, superiority, remainder; also a small rope (as hanging free) abundant, cord, exceeding, excellancy(-ent), what they leave, that hath left, plentifully, remnant, residue, rest, string, with.', 'from 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2896C}\/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["for <the>/ good"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1654}/[H1653]', 'inflected', 'heb', 'גֶּשֶׁם', '["Geshem"]', '["and/ Gashmu","and/ Geshem"]', '["n-pr-m"]', 'Geshem or Gashmu, an Arabian Geshem, Gashmu.', 'or (prolonged) גַּשְׁמוּ; the same as 1653;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3932}/[H3932]', 'inflected', 'heb', 'לָעַג', '["lâʻag"]', '["and/ have you mocked?","and/ he mocked","and/ they mocked"]', '["v"]', 'to deride; by implication (as if imitating a foreigner) to speak unintelligibly have in derision, laugh (to scorn), mock (on), stammering.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2146}/[H2142]', 'inflected', 'heb', 'זִכְרוֹן', '["zikrôwn"]', '["and/ a memorial"]', '["n-m"]', 'a memento (or memorable thing, day or writing) memorial, record.', 'from 2142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0475M}/[H410]', 'lemma', 'heb', 'אֶלְיָשִׁיב', '["ʼElyâshîyb"]', '["Eliashib"]', '["n-pr-m"]', 'Eljashib, the name of six Israelites Eliashib.', 'from 410 and 7725; God will restore;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6629H>', 'inflected', 'heb', 'הצאן', '["ha./Tzon"]', '["the/ sheep"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6942G}/H9033/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["they consecrated/ it"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4026H}/[H1431]', 'lemma', 'heb', 'מִגְדָּל', '["migdâl"]', '["[the] tower of"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3968}/[H3967]', 'inflected', 'heb', 'מֵאָה', '["Mêʼâh"]', '["the/ hundred"]', '["n-f"]', 'Meah, a tower in Jerusalem Meah.', 'the same as 3967;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2606}\/[H2603]', 'inflected', 'heb', 'חֲנַנְאֵל', '["Chănanʼêl"]', '["Hananel"]', '["n-pr-m"]', 'Chananel, probably an Israelite, from whom a tower of Jerusalem was named Hananeel.', 'from 2603 and 410; God has favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2139L}/[H2142]', 'lemma', 'heb', 'זַכּוּר', '["Zakkûwr"]', '["Zaccur"]', '["n-pr-m"]', 'Zakkur, the name of seven Israelites Zaccur, Zacchur.', 'from 2142; mindful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0566H}\/[H564]', 'inflected', 'heb', 'אִמְרִי', '["ʼImrîy"]', '["Imri"]', '["n-pr-m"]', 'Imri, the name of two Israelites Imri.', 'from 564;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7136B}/H9033/[H7136]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["they made beams for/ it"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4514}/H9023/[H5274]', 'inflected', 'heb', 'מַנְעוּל', '["manʻûwl"]', '["bolts/ its"]', '["n-m"]', 'a bolt lock.', 'or מַנְעֻל; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1280}/H9023\/[H1272]', 'inflected', 'heb', 'בְּרִיחַ', '["bᵉrîyach"]', '["and/ bars/ its"]', '["n-m"]', 'a bolt bar, fugitive.', 'from 1272;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6976J}\/[H6975]', 'inflected', 'heb', 'קוֹץ', '["Qôwts"]', '["Hakkoz"]', '["n-pr-m"]', 'Kots, the name of two Israelites Koz, Hakkoz (including the article).', 'the same as 6975;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4918R}/[H7999]', 'lemma', 'heb', 'מְשֻׁלָּם', '["Mᵉshullâm"]', '["Meshullam"]', '["n-pr-m"]', 'Meshullam, the name of seventeen Israelites Meshullam.', 'from 7999; allied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1296K}/[H1290]', 'lemma', 'heb', 'בֶּרֶכְיָה', '["Berekyâh"]', '["Berekiah"]', '["n-pr-m"]', 'Berekjah, the name of six Israelites Berachiah, Berechiah.', 'or בֶּרֶכְיָהוּ; from 1290 and 3050; knee (i.e. blessing) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4898G}\/[H7804]', 'inflected', 'heb', 'מְשֵׁיזַבְאֵל', '["Mᵉshêyzabʼêl"]', '["Meshezabel"]', '["n-pr-m"]', 'Meshezabel, an Israelite Meshezabeel.', 'from an equiv. to 7804 and 410; delivered of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6659J}/[H6663]', 'lemma', 'heb', 'צָדוֹק', '["Tsâdôwq"]', '["Zadok"]', '["n-pr-m"]', 'Tsadok, the name of eight or nine Israelites Zadok.', 'from 6663; just;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1195I}\/[H1196]', 'inflected', 'heb', 'בַּעֲנָא', '["Baʻănâʼ"]', '["Baana"]', '["n-pr-m"]', 'Baana, the name of four Israelite Baana, Baanah.', 'the same as 1196;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0117}/H9028/[H142]', 'inflected', 'heb', 'אַדִּיר', '["ʼaddîyr"]', '["and/ noble [ones]/ their","and/ nobles/ their"]', '["a"]', 'wide or (generally) large; figuratively, powerful excellent, famous, gallant, glorious, goodly, lordly, mighty(-ier one), noble, principal, worthy.', 'from 142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0113>/H9028\', 'opaque', 'heb', 'אָדוֹן', '["ʼâdôwn"]', '["master<s>/ their"]', '["n-m"]', 'sovereign, i.e. controller (human or divine) lord, master, owner. Compare also names beginning with ''Adoni-''.', 'or (shortened) אָדֹן; from an unused root (meaning to rule);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3465G}/[H3462]', 'inflected', 'heb', 'יָשָׁן', '["yâshân"]', '["the/ Jeshanah"]', '["a"]', 'old old.', 'from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3111G}/[H3077]', 'lemma', 'heb', 'יוֹיָדָע', '["Yôwyâdâʻ"]', '["Joiada"]', '["n-pr-m"]', 'Jojada, the name of two Israelites Jehoiada, Joiada.', 'a form of 3077;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6454I}/[H6452]', 'lemma', 'heb', 'פָּסֵחַ', '["Pâçêach"]', '["Paseah"]', '["n-pr-m"]', 'Paseach, the name of two Israelites Paseah, Phaseah.', 'from 6452; limping;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4918S}/[H7999]', 'inflected', 'heb', 'מְשֻׁלָּם', '["Mᵉshullâm"]', '["and/ Meshullam"]', '["n-pr-m"]', 'Meshullam, the name of seventeen Israelites Meshullam.', 'from 7999; allied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1152}/[H5475]', 'lemma', 'heb', 'בְּסוֹדְיָה', '["Bᵉçôwdᵉyâh"]', '["Besodeiah"]', '["n-pr-m"]', 'Besodejah, an Israelite Besodeiah.', 'from 5475 and 3050 with prepositional prefix; in (the) counsel of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4514}/H9023/[H5274]', 'inflected', 'heb', 'מַנְעוּל', '["manʻûwl"]', '["and/ bolts/ its"]', '["n-m"]', 'a bolt lock.', 'or מַנְעֻל; from 5274;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4424}/[H4423]', 'lemma', 'heb', 'מְלַטְיָה', '["Mᵉlaṭyâh"]', '["Melatiah"]', '["n-pr-m"]', 'Melatjah, a Gibeonite Melatiah.', 'from 4423 and 3050; (whom) Jah has delivered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3036}/[H3034]', 'inflected', 'heb', 'יָדוֹן', '["Yâdôwn"]', '["and/ Jadon"]', '["n-pr-m"]', 'Jadon, an Israelite Jadon.', 'from 3034; thankful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4824}/[H4824]', 'inflected', 'heb', 'מֵרֹנֹתִי', '["Mêrônôthîy"]', '["the/ Meronothite"]', '["a"]', 'a Meronothite, or inhabitant of some (otherwise unknown) Meronoth. Meronothite.', 'patrial from an unused noun;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3678I}/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["<into>/ a seat of","<to>/ [the] seat of","to/ [the] seat of"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5104G}\/[H5102]', 'inflected', 'heb', 'נָהָר', '["nâhâr"]', '["the/ River"]', '["n-m"]', 'a stream (including the sea; expectation the Nile, Euphrates, etc.); figuratively, prosperity flood, river.', 'from 5102;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5816L}/[H5797]', 'lemma', 'heb', 'עֻזִּיאֵל', '["ʻUzzîyʼêl"]', '["Uzziel"]', '["n-pr-m"]', 'Uzziel, the name of six Israelites Uzziel.', 'from 5797 and 410; strength of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2736}/[H2734]', 'lemma', 'heb', 'חַרְהֲיָה', '["Charhăyâh"]', '["Harhaiah"]', '["n-pr-m"]', 'Charhajah, an Israelite Harhaiah.', '; from 2734 and 3050; fearing Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6884}\/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["goldsmiths"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2608S}/[H2603]', 'lemma', 'heb', 'חֲנַנְיָה', '["Chănanyâh"]', '["Hananiah"]', '["n-pr-m"]', 'Chananjah, the name of thirteen Israelites Hananiah.', 'or חֲנַנְיָהוּ; from 2603 and 3050; Jah has favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7546}/[H7543]', 'inflected', 'heb', 'רַקָּח', '["raqqâch"]', '["the/ perfumers"]', '["n-m"]', 'a male perfumer apothecary.', 'from 7543;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5800B}/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["and/ they restored"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H2346H>', 'inflected', 'heb', 'החומה', '["ha./cho.Mah"]', '["the/ wall"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7342G}\/[H7337]', 'inflected', 'heb', 'רָחָב', '["râchâb"]', '["<the>/ broad"]', '["a"]', 'roomy, in any (or every) direction, literally or figuratively broad, large, at liberty, proud, wide.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7509J}/[H7495]', 'lemma', 'heb', 'רְפָיָה', '["Rᵉphâyâh"]', '["Rephaiah"]', '["n-pr-m"]', 'Rephajah, the name of five Israelites Rephaiah.', 'from 7495 and 3050; Jah has cured;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2354I}/[H2353]', 'lemma', 'heb', 'חוּר', '["Chûwr"]', '["Hur"]', '["n-pr-m"]', 'Chur, the name of four Israelites and one Midianite Hur.', 'the same as 2353 or 2352;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6418>', 'opaque', 'heb', 'פֶּלֶךְ', '["pelek"]', '["[the] district of","[the] spindle"]', '["n-m"]', 'a circuit (i.e. district); also a spindle (as whirled); hence, a crutch (di-) staff, participle', 'from an unused root meaning to be round;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3042H}/[H3034]', 'lemma', 'heb', 'יְדָיָה', '["Yᵉdâyâh"]', '["Jedaiah"]', '["n-pr-m"]', 'Jedajah, the name of two Israelites Jedaiah.', 'from 3034 and 3050; praised of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2739}/[H2763]', 'lemma', 'heb', 'חֲרוּמַף', '["chărûwmaph"]', '["Harumaph"]', '["n-pr-m"]', 'Charumaph, an Israelite Harumaph.', 'from passive participle of 2763 and 639; snub-nosed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2407I>', 'opaque', 'heb', 'חַטּוּשׁ', '["Chaṭṭûwsh"]', '["Hattush"]', '["n-pr-m"]', 'Chattush, the name of four or five Israelites Hattush.', 'from an unused root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2813G}/[H2808]', 'lemma', 'heb', 'חֲשַׁבְנְיָה', '["Chăshabnᵉyâh"]', '["Hashabneiah"]', '["n-pr-m"]', 'Chashabnejah, the name of two Israelites Hashabniah.', 'from 2808 and 3050; thought of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4441M}/[H4428]', 'lemma', 'heb', 'מַלְכִּיָּה', '["Malkîyâh"]', '["Malkijah"]', '["n-pr-m"]', 'Malkijah, the name of ten Israelites Malchiah, Malchijah.', 'or מַלְכִּיָּהוּlemma מַלְכִּיָהוּ missing dagesh, corrected to מַלְכִּיָּהוּ; (Jeremiah 38:6), from 4428 and 3050; king of (i.e. appointed by) Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2766I}/[H2763]', 'lemma', 'heb', 'חָרִם', '["Chârim"]', '["Harim"]', '["n-pr-m"]', 'Charim, an Israelite Harim.', 'from 2763; snub-nosed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2815H}/[H2803]', 'inflected', 'heb', 'חַשּׁוּב', '["Chashshûwb"]', '["and/ Hasshub"]', '["n-pr-m"]', 'Chashshub, the name of two or three Israelites Hashub, Hasshub.', 'from 2803; intelligent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6355H}/[H6354]', 'lemma', 'heb', 'פַּחַת מוֹאָב', '["Pachath Môwʼâb"]', '["Moab","Pahath-"]', '["n-pr-m"]', 'Pachath-Moab, an Israelite Pahathmoab.', 'from 6354 and 4124; pit of Moab;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4026I}/[H1431]', 'lemma', 'heb', 'מִגְדָּל', '["migdâl"]', '["[the] tower of"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8574G}\/[H5216]', 'inflected', 'heb', 'תַּנּוּר', '["tannûwr"]', '["the/ ovens"]', '["n-m"]', 'a fire-pot furnace, oven.', 'from 5216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7967Q}/[H7966]', 'lemma', 'heb', 'שַׁלּוּם', '["Shallûwm"]', '["Shallum"]', '["n-pr-m"]', 'Shallum, the name of fourteen Israelites Shallum.', 'or (shorter) שַׁלֻּם; the same as 7966;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3873}/[H3907]', 'lemma', 'heb', 'לוֹחֵשׁ', '["Lôwchêsh"]', '["Hallohesh"]', '["n-pr-m"]', 'Lochesh, an Israelite Hallohesh, Haloshesh (includ. the article).', 'active participle of 3907; (the) enchanter;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1323G}/H9023\/[H1129]', 'inflected', 'heb', 'בַּת', '["bath"]', '["and/ daughters/ his"]', '["n-f"]', 'a daughter (used in the same wide sense as other terms of relationship, literally and figuratively) apple (of the eye), branch, company, daughter, × first, × old, owl, town, village.', 'from 1129 (as feminine of 1121);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2586H}/[H2603]', 'lemma', 'heb', 'חָנוּן', '["Chânûwn"]', '["Hanun"]', '["n-pr-m"]', 'Chanun, the name of an Ammonite and of two Israelites Hanun.', 'from 2603; favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1129}/H9033/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["builders/ its","he had built/ it","he rebuilt/ it","they rebuilt/ it"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4441N}/[H4428]', 'lemma', 'heb', 'מַלְכִּיָּה', '["Malkîyâh"]', '["Malkijah"]', '["n-pr-m"]', 'Malkijah, the name of ten Israelites Malchiah, Malchijah.', 'or מַלְכִּיָּהוּlemma מַלְכִּיָהוּ missing dagesh, corrected to מַלְכִּיָּהוּ; (Jeremiah 38:6), from 4428 and 3050; king of (i.e. appointed by) Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7394I}/[H7392]', 'lemma', 'heb', 'רֵכָב', '["Rêkâb"]', '["Rechab"]', '["n-pr-m a"]', 'Rekab, the name of two Arabs and of two Israelites Rechab.', 'from 7392; rider;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1021}/[H1004]', 'lemma', 'heb', 'בֵּית הַכֶּרֶם', '["Bêyth hak-Kerem"]', '["Beth","Hakkerem"]', '["n-pr-loc"]', 'Beth-hak-Kerem, a place in Palestine Beth-haccerem.', 'from 1004 and 3754 with the article interposed; house of the vineyard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7968}/[H7967]', 'lemma', 'heb', 'שַׁלּוּן', '["Shallûwn"]', '["Shallun"]', '["n-pr-m"]', 'Shallun, an Israelite Shallum.', 'probably for 7967;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3626G}/[H3605]', 'lemma', 'heb', 'כׇּל־חֹזֶה', '["Kol-Chôzeh"]', '["Col-","Hozeh"]', '["n-pr-m"]', 'Col-Chozeh, an Israelite Col-hozeh.', 'from 3605 and 2374; every seer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2926}/H9033/[H2926]', 'inflected', 'heb', 'טָלַל', '["ṭâlal"]', '["and/ he roofed over/ it"]', '["v"]', 'properly, to strew over, i.e. (by implication) to cover in or plate (with beams) cover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7975A}/[H7974]', 'inflected', 'heb', 'שִׁלֹחַ', '["Shilôach"]', '["<the>/ Shelah"]', '["n-pr-loc"]', 'Shiloach, a fountain of Jerusalem Shiloah, Siloah.', 'or (in imitation of 7974) שֶׁלַח; (Nehemiah 3:15), from 7971; rill;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5166I}/[H5162]', 'lemma', 'heb', 'נְחֶמְיָה', '["Nᵉchemyâh"]', '["Nehemiah"]', '["n-pr-m"]', 'Nechemjah, the name of three Israelites Nehemiah.', 'from 5162 and 3050; consolation of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5802}/[H5794]', 'lemma', 'heb', 'עַזְבּוּק', '["ʻAzbûwq"]', '["Azbuk"]', '["n-pr-m"]', 'Azbuk, an Israelite Azbuk.', 'from 5794 and the root of 950; stern depopulator;');
