INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1137L}/[H1129]', 'lemma', 'heb', 'בָּנִי', '["Bânîy"]', '["Bani"]', '["n-pr-m"]', 'Bani, the name of five Israelites Bani.', 'from 1129; built;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2811N}/[H2803]', 'lemma', 'heb', 'חֲשַׁבְיָה', '["Chăshabyâh"]', '["Hashabiah"]', '["n-pr-m"]', 'Chashabjah, the name of nine Israelites Hashabiah.', 'or חֲשַׁבְיָהוּ; from 2803 and 3050; Jah has regarded;');
