INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5829I}/[H5828]', 'lemma', 'heb', 'עֵזֶר', '["ʻÊzer"]', '["Ezer"]', '["n-pr-m"]', 'Ezer, the name of four Israelites Ezer. Compare 5827.', 'the same as 5828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3442L}/[H3091]', 'lemma', 'heb', 'יֵשׁוּעַ', '["Yêshûwaʻ"]', '["Jeshua"]', '["n-pr-m n-pr-loc"]', 'Jeshua, the name of ten Israelites, also of a place in Palestine Jeshua.', 'for 3091; he will save;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5402}/[H5401]', 'inflected', 'heb', 'נֶשֶׁק', '["nesheq"]', '["the/ armory"]', '["n-m"]', 'military equipment, i.e. (collectively) arms (offensive or defensive), or (concretely) an arsenal armed men, armour(-y), battle, harness, weapon.', 'or נֵשֶׁק; from 5401;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4740H}\/[H7106]', 'inflected', 'heb', 'מַקְצוֹעַ', '["maqtsôwaʻ"]', '["the/ buttress"]', '["n-m"]', 'an angle or recess corner, turning.', 'or מַקְצֹעַ; or (feminine) מַקְצֹעָה; from 7106 in the denominative sense of bending;');
