INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6976J}/[H6975]', 'lemma', 'heb', 'קוֹץ', '["Qôwts"]', '["Hakkoz"]', '["n-pr-m"]', 'Kots, the name of two Israelites Koz, Hakkoz (including the article).', 'the same as 6975;');
