INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1144J}/[H1121]', 'lemma', 'heb', 'בִּנְיָמִין', '["Binyâmîyn"]', '["Benjamin"]', '["n-pr-m"]', 'Binjamin, youngest son of Jacob; also the tribe descended from him, and its territory Benjamin.', 'from 1121 and 3225; son of (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2815I}/[H2803]', 'inflected', 'heb', 'חַשּׁוּב', '["Chashshûwb"]', '["and/ Hasshub"]', '["n-pr-m"]', 'Chashshub, the name of two or three Israelites Hashub, Hasshub.', 'from 2803; intelligent;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1004B}/H9028\/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["own house/ their"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5838W}/[H5826]', 'lemma', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4641P}/[H4639]', 'lemma', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6055G}/[H6049]', 'lemma', 'heb', 'עֲנַנְיָה', '["ʻĂnanyâh"]', '["Ananiah"]', '["n-pr-m n-pr-loc"]', 'Ananjah, the name of an Israelite and of a place in Palestine Ananiah.', 'from 6049 and 3050; Jah has covered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1131K}/[H1129]', 'lemma', 'heb', 'בִּנּוּי', '["Binnûwy"]', '["Binnui"]', '["n-pr-m"]', 'Binnui, an Israelite Binnui.', 'from 1129; built up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2582I}/[H2580]', 'lemma', 'heb', 'חֵנָדָד', '["Chênâdâd"]', '["Henadad"]', '["n-pr-m"]', 'Chenadad, an Israelite Henadad.', 'probably from 2580 and 1908; favor of Hadad;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6420}/[H6419]', 'lemma', 'heb', 'פָּלָל', '["Pâlâl"]', '["Palal"]', '["n-pr-m"]', 'Palal, an Israelite Palal.', 'from 6419; judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0186}/[H5813]', 'lemma', 'heb', 'אוּזַי', '["ʼÛwzay"]', '["Uzai"]', '["n-pr-m"]', 'Uzai, an Israelite Uzai.', 'perhaps by permutation for 5813, strong;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H4026M}/[H1431]', 'inflected', 'heb', 'מִגְדָּל', '["migdâl"]', '["and/ the/ tower"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4307H}/[H5201]', 'inflected', 'heb', 'מַטָּרָא', '["maṭṭârâʼ"]', '["the/ guard"]', '["n-f"]', 'a jail (as a guard-house); also an aim (as being closely watched) mark, prison.', 'or מַטָּרָה; from 5201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6305J}/[H6299]', 'lemma', 'heb', 'פְּדָיָה', '["Pᵉdâyâh"]', '["Pedaiah"]', '["n-pr-m"]', 'Pedajah, the name of six Israelites Pedaiah.', 'or פְּדָיָהוּ; from 6299 and 3050; Jah has ransomed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6551I}\/[H6550]', 'inflected', 'heb', 'פַּרְעֹשׁ', '["Parʻôsh"]', '["Parosh"]', '["n-pr-m"]', 'Parosh, the name of our Israelite Parosh, Pharosh.', 'the same as 6550;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6077}/[H6076]', 'inflected', 'heb', 'עֹפֶל', '["ʻÔphel"]', '["on <the>/ Ophel"]', '["n-pr-loc"]', 'Ophel, a ridge in Jerusalem Ophel.', 'the same as 6076;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4325H}/[H4325]', 'inflected', 'heb', 'מַיִם', '["mayim"]', '["the/ water"]', '["n-m"]', 'water; figuratively, juice; by euphemism, urine, semen piss, wasting, water(-ing, (-course, -flood, -spring)).', 'dual of a primitive noun (but used in a singular sense);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3318L}\/[H3318]', 'inflected', 'heb', 'יָצָא', '["yâtsâʼ"]', '["<the>/ projecting"]', '["v"]', 'to go (causatively, bring) out, in a great variety of applications, literally and figuratively, direct and proxim. × after, appear, × assuredly, bear out, × begotten, break out, bring forth (out, up), carry out, come (abroad, out, thereat, without), be condemned, depart(-ing, -ure), draw forth, in the end, escape, exact, fail, fall (out), fetch forth (out), get away (forth, hence, out), (able to, cause to, let) go abroad (forth, on, out), going out, grow, have forth (out), issue out, lay (lie) out, lead out, pluck out, proceed, pull out, put away, be risen, × scarce, send with commandment, shoot forth, spread, spring out, stand out, × still, × surely, take forth (out), at any time, × to (and fro), utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5483B>', 'inflected', 'heb', 'הסוסים', '["ha./su.Sim"]', '["the/ horses"]', NULL, NULL, NULL);
