INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0564J}/[H559]', 'lemma', 'heb', 'אִמֵּר', '["ʼImmêr"]', '["Immer"]', '["n-pr-m"]', 'Immer, the name of five Israelites Immer.', 'from 559; talkative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8098R}/[H8085]', 'lemma', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4217G}\/[H2224]', 'inflected', 'heb', 'מִזְרָח', '["mizrâch"]', '["the/ east"]', '["n-m"]', 'sunrise, i.e. the east east (side, -ward), (sun-) rising (of the sun).', 'from 2224;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2608G}/[H2603]', 'lemma', 'heb', 'חֲנַנְיָה', '["Chănanyâh"]', '["Hananiah"]', '["n-pr-m"]', 'Chananjah, the name of thirteen Israelites Hananiah.', 'or חֲנַנְיָהוּ; from 2603 and 3050; Jah has favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8018I}/[H8002]', 'lemma', 'heb', 'שֶׁלֶמְיָה', '["Shelemyâh"]', '["Shelemiah"]', '["n-pr-m"]', 'Shelemjah, the name of nine Israelites Shelemiah.', 'or שֶׁלֶמְיָהוּ; from 8002 and 3050; thank-offering of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2586I}/[H2603]', 'inflected', 'heb', 'חָנוּן', '["Chânûwn"]', '["and/ Hanun"]', '["n-pr-m"]', 'Chanun, the name of an Ammonite and of two Israelites Hanun.', 'from 2603; favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6764>', 'opaque', 'heb', 'צָלָף', '["Tsâlâph"]', '["Zalaph"]', '["n-pr-m"]', 'Tsalaph, an Israelite Zalaph.', 'from an unused root of unknown meaning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5393}/H9023\/[H3957]', 'inflected', 'heb', 'נִשְׁכָּה', '["nishkâh"]', '["room/ his"]', '["n-f"]', 'a cell chamber.', 'for 3957;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4441O}/[H4428]', 'lemma', 'heb', 'מַלְכִּיָּה', '["Malkîyâh"]', '["Malkijah"]', '["n-pr-m"]', 'Malkijah, the name of ten Israelites Malchiah, Malchijah.', 'or מַלְכִּיָּהוּlemma מַלְכִּיָהוּ missing dagesh, corrected to מַלְכִּיָּהוּ; (Jeremiah 38:6), from 4428 and 3050; king of (i.e. appointed by) Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6885}/[H6884]', 'inflected', 'heb', 'צֹרְפִי', '["Tsôrᵉphîy"]', '["the/ goldsmith[s]"]', '["n-m"]', 'Tsorephi (with the article), an Israelite goldsmith''s.', 'from 6884; refiner;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7402}/[H7402]', 'inflected', 'heb', 'רָכַל', '["râkal"]', '["and/ the/ traders"]', '["v"]', 'to travel for trading (spice) merchant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4662G}/[H6485]', 'inflected', 'heb', 'מִפְקָד', '["miphqâd"]', '["the/ muster"]', '["n-m"]', 'an appointment, i.e. mandate; concretely, a designated spot; specifically, a census appointed place, commandment, number.', 'from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6884}/[H6884]', 'inflected', 'heb', 'צָרַף', '["tsâraph"]', '["the/ goldsmiths"]', '["v"]', 'to fuse (metal), i.e. refine (literally or figuratively) cast, (re-) fine(-er), founder, goldsmith, melt, pure, purge away, try.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7402}\/[H7402]', 'inflected', 'heb', 'רָכַל', '["râkal"]', '["and/ the/ traders"]', '["v"]', 'to travel for trading (spice) merchant.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0537}/[H535]', 'inflected', 'heb', 'אֲמֵלָל', '["ʼămêlâl"]', '["<the>/ feeble"]', '["a"]', 'languid feeble.', 'from 535;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5800C}/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["¿/ will they restore"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H2076}/[H2076]', 'inflected', 'heb', 'זָבַח', '["zâbach"]', '["¿/ will they offer sacrifices"]', '["v"]', 'to slaughter an animal (usually in sacrifice) kill, offer, (do) sacrifice, slay.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H3615G}/[H3615]', 'inflected', 'heb', 'כָּלָה', '["kâlâh"]', '["¿/ will they finish"]', '["v"]', 'to end, whether intransitive (to cease, be finished, perish) or transitive (to complete, prepare, consume) accomplish, cease, consume (away), determine, destroy (utterly), be (when... were) done, (be an) end (of), expire, (cause to) fail, faint, finish, fulfil, × fully, × have, leave (off), long, bring to pass, wholly reap, make clean riddance, spend, quite take away, waste.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6194}/[H6192]', 'inflected', 'heb', 'עָרֵם', '["ʻârêm"]', '["from/ [the] heaps of"]', '["n-f"]', 'a heap; specifically, a sheaf heap (of corn), sheaf.', '(Jeremiah 50:26) or (feminine) עֲרֵמָה; from 6192;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0068G}/H9028\/[H1129]', 'inflected', 'heb', 'אֶבֶן', '["ʼeben"]', '["stones/ their"]', '["n-f"]', 'a stone carbuncle, mason, plummet, (chalk-, hail-, head-, sling-) stone(-ny), (divers) weight(-s).', 'from the root of 1129 through the meaning to build;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0939}/[H936]', 'lemma', 'heb', 'בּוּזָה', '["bûwzâh"]', '["contempt"]', '["n-f"]', 'something scorned; an object of contempt despised.', 'feminine passive participle of 936;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2781}/H9028/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["reproach/ their"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5414G}/H9038/[H5414]', 'inflected', 'heb', 'נָתַן', '["nâthan"]', '["and/ give/ them"]', '["v"]', 'to give, used with greatest latitude of application (put, make, etc.) add, apply, appoint, ascribe, assign, × avenge, × be (healed), bestow, bring (forth, hither), cast, cause, charge, come, commit, consider, count, cry, deliver (up), direct, distribute, do, × doubtless, × without fail, fasten, frame, × get, give (forth, over, up), grant, hang (up), × have, × indeed, lay (unto charge, up), (give) leave, lend, let (out), lie, lift up, make, O that, occupy, offer, ordain, pay, perform, place, pour, print, × pull, put (forth), recompense, render, requite, restore, send (out), set (forth), shew, shoot forth (up), sing, slander, strike, (sub-) mit, suffer, × surely, × take, thrust, trade, turn, utter, weep, willingly, withdraw, would (to) God, yield.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0961}/[H957]', 'inflected', 'heb', 'בִּזָּה', '["bizzâh"]', '["to/ plunder"]', '["n-f"]', 'booty prey, spoil.', 'feminine of 957;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5771H}/H9028/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["iniquities/ their","iniquity/ their"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2677}/H9024/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["middle/ its"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2346G>', 'inflected', 'heb', 'לחמות', '["la./cho.Mah","le./cho.Mat","le./cho.Mot"]', '["into/ a wall of","of the/ wall","of/ [the] walls of","to the/ wall"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8442}/[H8582]', 'lemma', 'heb', 'תּוֹעָה', '["tôwʻâh"]', '["confusion","error"]', '["n-f"]', 'mistake, i.e. (morally) impiety, or (political) injury error, hinder.', 'feminine active participle of 8582;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H6083}/[H6080]', 'inflected', 'heb', 'עָפָר', '["ʻâphâr"]', '["and/ the/ debris"]', '["n-m"]', 'dust (as powdered or gray); hence, clay, earth, mud ashes, dust, earth, ground, morter, powder, rubbish.', 'from 6080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6862C}/H9025/[H6887]', 'inflected', 'heb', 'צַר', '["tsar"]', '["opponents/ our"]', '["a n-m"]', 'narrow; (as a noun) a tight place (usually figuratively, i.e. trouble); also a pebble (as in 6864); (transitive) an opponent (as crowding) adversary, afflicted(-tion), anguish, close, distress, enemy, flint, foe, narrow, small, sorrow, strait, tribulation, trouble.', 'or צָר; from 6887;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H8432>/H9028', 'opaque', 'heb', 'תָּוֶךְ', '["tâvek"]', '["[the] midst of/ them"]', '["n-m"]', 'a bisection, i.e. (by implication) the centre among(-st), × between, half, × (there-, where-), in(-to), middle, mid(-night), midst (among), × out (of), × through, × with(-in).', 'from an unused root meaning to sever;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0681}/H9038/[H680]', 'inflected', 'heb', 'אֵצֶל', '["ʼêtsel"]', '["beside/ them"]', '["n-m"]', 'a side; (as a preposition) near at, (hard) by, (from) (beside), near (unto), toward, with. See also 1018.', 'from 680 (in the sense of joining);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8482}/[H8478]', 'inflected', 'heb', 'תַּחְתִּי', '["tachtîy"]', '["from/ [the] lower parts"]', '["a"]', 'lowermost; as noun (feminine plural) the depths (figuratively, a pit, the womb) low (parts, -er, -er parts, -est), nether (part).', 'from 8478;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6706}/[H6705]', 'inflected', 'heb', 'צְחִיחַ', '["tsᵉchîyach"]', '["in the/ open places"]', '["n-m"]', 'glaring, i.e. exposed to the bright sun higher place, top.', 'from 6705;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2719}/H9028/[H2717]', 'inflected', 'heb', 'חֶרֶב', '["chereb"]', '["sword/ their","swords/ their"]', '["n-f"]', 'drought; also a cutting instrument (from its destructive effect), as a knife, sword, or other sharp implement axe, dagger, knife, mattock, sword, tool.', 'from 2717;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7420>/H9028', 'opaque', 'heb', 'רֹמַח', '["rômach"]', '["spears/ their"]', '["n-m"]', 'a lance (as thrown); especially the iron point buckler, javelin, lancet, spear.', 'from an unused root meaning to hurl;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7198}/H9028/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["and/ bows/ their"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5461>', 'inflected', 'heb', 'הסגנים', '["ha./se.ga.Nim"]', '["the/ officials"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004B}/H9026\/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ houses/ your"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5288}/H9020/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["lads/ my","servants/ my","young men/ my"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2677}/H9028/[H2673]', 'inflected', 'heb', 'חֵצִי', '["chêtsîy"]', '["and/ half of/ them"]', '["n-m"]', 'the half or middle half, middle, mid(-night), midst, part, two parts.', 'from 2673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H7420>', 'inflected', 'heb', 'והרמחים', '["ve./ha./re.ma.Chim"]', '["and/ the/ spears"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H7198}/[H7185]', 'inflected', 'heb', 'קֶשֶׁת', '["qesheth"]', '["and/ the/ bows"]', '["n-f"]', 'a bow, for shooting (hence, figuratively, strength) or the iris × arch(-er), arrow, bow(-man, -shot).', 'from 7185 in the original sense (of 6983) of bending;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8302B}/[H8281]', 'inflected', 'heb', 'שִׁרְיוֹן', '["shiryôwn"]', '["and/ the/ body armor<s>"]', '["n-m n-f"]', 'a corslet (as if twisted) breastplate, coat of mail, habergeon, harness. See 5630.', 'or שִׁרְיֹן; and שִׁרְיָן; also (feminine) שִׁרְיָה; and שִׁרְיֹנָה; from 8281 in the original sense of turning;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5447}/[H5445]', 'inflected', 'heb', 'סֵבֶל', '["çêbel"]', '["in <the>/ burden"]', '["n-m"]', 'a load (literally or figuratively) burden, charge.', 'from 5445;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7973}/[H7971]', 'inflected', 'heb', 'שֶׁלַח', '["shelach"]', '["the/ weapon"]', '["n-m"]', 'a missile of attack, i.e. spear; also (figuratively) a shoot of growth; i.e. branch dart, plant, × put off, sword, weapon.', 'from 7971;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1129}/[H1129]', 'inflected', 'heb', 'בָּנָה', '["bânâh"]', '["and/ the/ builders"]', '["v"]', 'to build (literally and figuratively) (begin to) build(-er), obtain children, make, repair, set (up), × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8628}/[H8628]', 'inflected', 'heb', 'תָּקַע', '["tâqaʻ"]', '["and/ the/ [one who] gave a blast"]', '["v"]', 'to clatter, i.e. slap (the hands together), clang (an instrument); by analogy, to drive (a nail or tent-pin, a dart, etc.); by implication, to become bondsman by handclasping) blow (a trumpet), cast, clap, fasten, pitch (tent), smite, sound, strike, × suretiship, thrust.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7420>', 'inflected', 'heb', 'ברמחים', '["ba./re.ma.Chim"]', '["on <the>/ spears"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H5927L}/[H5927]', 'inflected', 'heb', 'עָלָה', '["ʻâlâh"]', '["from/ when came up"]', '["v"]', 'to ascend, intransitively (be high) or actively (mount); used in a great variety of senses, primary and secondary, literal and figurative arise (up), (cause to) ascend up, at once, break (the day) (up), bring (up), (cause to) burn, carry up, cast up, shew, climb (up), (cause to, make to) come (up), cut off, dawn, depart, exalt, excel, fall, fetch up, get up, (make to) go (away, up); grow (over) increase, lay, leap, levy, lift (self) up, light, (make) up, × mention, mount up, offer, make to pay, perfect, prefer, put (on), raise, recover, restore, (make to) rise (up), scale, set (up), shoot forth (up), (begin to) spring (up), stir up, take away (up), work.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5288}/H9020/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["and/ servants/ my"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4929}/[H8104]', 'inflected', 'heb', 'מִשְׁמָר', '["mishmâr"]', '["the/ guard","the/ watch"]', '["n-m"]', 'a guard (the man, the post or the prison); a deposit (figuratively); also (as observed) a usage (abstractly), or an example (concretely) diligence, guard, office, prison, ward, watch.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0899B}/H9025/[H898]', 'inflected', 'heb', 'בֶּגֶד', '["beged"]', '["clothes/ our"]', '["n-m"]', 'a covering, i.e. clothing; also treachery or pillage apparel, cloth(-es, ing), garment, lap, rag, raiment, robe, × very (treacherously), vesture, wardrobe.', 'from 898;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704G>/H9025', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["fields/ our"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3754>/H9025', 'inflected', 'heb', 'וכרמינו', '["u./khe.ra.Mei./nu"]', '["and/ vineyards/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004B}/H9025/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ houses/ our"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4060B}/[H4055]', 'inflected', 'heb', 'מִדָּה', '["middâh"]', '["for/ [the] tribute of"]', '["n-f"]', 'properly, extension, i.e. height or breadth; also a measure (including its standard); hence a portion (as measured) or a vestment; specifically, tribute (as measured) garment, measure(-ing, meteyard, piece, size, (great) stature, tribute, wide.', 'feminine of 4055;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1121A}/H9028/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["[are] like/ children/ their"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H7704G>/H9025', 'inflected', 'heb', 'ושדתינו', '["u./se.do.Tei./nu"]', '["and/ fields/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0312}/[H309]', 'inflected', 'heb', 'אַחֵר', '["ʼachêr"]', '["[belong] to/ others","[belonged] to the/ other [door]","for/ another","to/ another","to/ other [people]","to/ others"]', '["a"]', 'properly, hinder; generally, next, other, etc. (an-) other man, following, next, strange.', 'from 309;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2201}/H9028/[H2199]', 'inflected', 'heb', 'זַעַק', '["zaʻaq"]', '["outcry/ their"]', '["n-f"]', 'a shriek or outcry cry(-ing).', 'and (feminine) זְעָקָהxlit zᵉâqâh corrected to zᵉʻâqâh; from 2199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4427B}/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["and/ it considered"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7378}/H9012/[H7378]', 'inflected', 'heb', 'רִיב', '["rîyb"]', '["and/ I contended/ !"]', '["v"]', 'properly, to toss, i.e. grapple; mostly figuratively, to wrangle, i.e. hold a controversy; (by implication) to defend adversary, chide, complain, contend, debate, × ever, × lay wait, plead, rebuke, strive, × thoroughly.', 'or רוּב; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4855}/[H5383]', 'lemma', 'heb', 'מַשָּׁא', '["mashshâʼ"]', '["usury"]', '["n-m"]', 'a loan; by implication, interest on a debt exaction, usury.', 'from 5383;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4376}/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["the/ seller","who/ sold themselves"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H2781}/[H2778]', 'inflected', 'heb', 'חֶרְפָּה', '["cherpâh"]', '["from/ [the] reproach of"]', '["n-f"]', 'contumely, disgrace, the pudenda rebuke, reproach(-fully), shame.', 'from 2778;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4855}/[H5383]', 'inflected', 'heb', 'מַשָּׁא', '["mashshâʼ"]', '["the/ usury"]', '["n-m"]', 'a loan; by implication, interest on a debt exaction, usury.', 'from 5383;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H7704G>/H9028', 'opaque', 'heb', 'שָׂדֶה', '["sâdeh"]', '["fields/ their"]', '["n-m"]', 'a field (as flat) country, field, ground, land, soil, × wild.', 'or שָׂדַי; from an unused root meaning to spread out;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2132H>/H9028', 'opaque', 'heb', 'זַיִת', '["zayith"]', '["olive trees/ their"]', '["n-m"]', 'an olive (as yielding illuminating oil), the tree, the branch or the berry olive (tree, -yard), Olivet.', 'probably from an unused root (akin to 2099);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1004B}/H9028/[H1129]', 'inflected', 'heb', 'בַּיִת', '["bayith"]', '["and/ houses/ their"]', '["n-m"]', 'a house (in the greatest variation of applications, especially family, etc.) court, daughter, door, + dungeon, family, + forth of, × great as would contain, hangings, home(born), (winter) house(-hold), inside(-ward), palace, place, + prison, + steward, + tablet, temple, web, + within(-out).', 'probably from 1129 abbreviated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1715}/[H1711]', 'inflected', 'heb', 'דָּגָן', '["dâgân"]', '["and/ the/ grain"]', '["n-m"]', 'properly, increase, i.e. grain corn (floor), wheat.', 'from 1711;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8492}/[H3423]', 'inflected', 'heb', 'תִּירוֹשׁ', '["tîyrôwsh"]', '["the/ new wine"]', '["n-m"]', 'must or fresh grape-juice (as just squeezed out); by implication (rarely) fermented wine (new, sweet) wine.', 'or תִּירֹשׁ; from 3423 in the sense of expulsion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3323}/[H6671]', 'inflected', 'heb', 'יִצְהָר', '["yitshâr"]', '["and/ the/ fresh oil"]', '["n-m"]', 'oil (as producing light); figuratively, anointing anointed oil.', 'from 6671;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7650}/H9038/[H7651]', 'inflected', 'heb', 'שָׁבַע', '["shâbaʻ"]', '["and/ I made swear an oath/ them","and/ I made take an oath/ them"]', '["v"]', 'to seven oneself, i.e. swear (as if by repeating a declaration seven times) adjure, charge (by an oath, with an oath), feed to the full (by mistake for 7646), take an oath, × straitly, (cause to, make to) swear.', 'a primitive root; properly to be complete, but used only as a denominative from 7651;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2684}/H9020/[H2683]', 'inflected', 'heb', 'חֹצֶן', '["chôtsen"]', '["bosom/ my"]', '["n-m"]', 'arm, lap.', 'a collateral form of 2683, and meaning the same');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5287}/[H5286]', 'lemma', 'heb', 'נָעַר', '["nâʻar"]', '["I have been shaken off","I shook out","[one who] shakes out","may he shake out","shake yourself free","shaken out"]', '["v"]', 'to tumble about shake (off, out, self), overthrow, toss up and down.', 'a primitive root (probably identical with 5286, through the idea of the rustling of mane, which usually accompanies the lion''s roar);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H3018}/H9023/[H3021]', 'inflected', 'heb', 'יְגִיעַ', '["yᵉgîyaʻ"]', '["and/ from/ property/ his"]', '["n-m"]', 'toil; hence, a work, produce, property (as the result of labor) labour, work.', 'from 3021;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7386}/[H7324]', 'inflected', 'heb', 'רֵיק', '["rêyq"]', '["and/ [is] empty","and/ empty"]', '["a"]', 'empty; figuratively, worthless emptied(-ty), vain (fellow, man).', 'or (shorter) רֵק; from 7324;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6346>/H9028', 'opaque', 'heb', 'פֶּחָה', '["pechâh"]', '["governor/ their"]', '["n-m"]', 'a prefect (of a city or small district) captain, deputy, governor.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H6346>', 'inflected', 'heb', 'הפחות', '["ha./Pe.chah","ha./pa.Chot","ha./pe.Chah"]', '["the/ governor","the/ governors"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H6346>', 'inflected', 'heb', 'והפחות', '["ve./ha./pa.Chot","ve./ha./pa.chOt"]', '["and/ the/ governors"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3899I}/[H3898]', 'inflected', 'heb', 'לֶחֶם', '["lechem"]', '["<in>/ food"]', '["n-m"]', 'food (for man or beast), especially bread, or grain (for making it) (shew-) bread, × eat, food, fruit, loaf, meat, victuals.', 'from 3898; See also 1036');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5288}/H9028/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["servants/ their"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7980}/[H7980]', 'lemma', 'heb', 'שָׁלַט', '["shâlaṭ"]', '["he domineers","it have power","they domineered"]', '["v"]', 'to dominate, i.e. govern; by implication, to permit (bear, have) rule, have dominion, give (have) power.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2388K}/[H2388]', 'lemma', 'heb', 'חָזַק', '["châzaq"]', '["I kept hold","they will display strength"]', '["v"]', 'to fasten upon; hence, to seize, be strong (figuratively, courageous, causatively strengthen, cure, help, repair, fortify), obstinate; to bind, restrain, conquer aid, amend, × calker, catch, cleave, confirm, be constant, constrain, continue, be of good (take) courage(-ous, -ly), encourage (self), be established, fasten, force, fortify, make hard, harden, help, (lay) hold (fast), lean, maintain, play the man, mend, become (wax) mighty, prevail, be recovered, repair, retain, seize, be (wax) sore, strengthen (self), be stout, be (make, shew, wax) strong(-er), be sure, take (hold), be urgent, behave self valiantly, withstand.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3064}/[H3063]', 'inflected', 'heb', 'יְהוּדִי', '["Yᵉhûwdîy"]', '["and/ the/ Jews"]', '["n-m"]', 'a Jehudite (i.e. Judaite or Jew), or descendant of Jehudah (i.e. Judah) Jew.', 'patronymically from 3063;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6833}/[H6852]', 'inflected', 'heb', 'צִפּוֹר', '["tsippôwr"]', '["and/ bird[s] of","and/ poultry"]', '["n-f"]', 'a little bird (as hopping) bird, fowl, sparrow.', 'or צִפֹּר; from 6852;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H5571>', 'inflected', 'heb', 'לסנבלט', '["le./san.va.Lat"]', '["by/ Sanballat","of/ Sanballat"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1654}/[H1653]', 'inflected', 'heb', 'גֶּשֶׁם', '["Geshem"]', '["and/ by/ Geshem"]', '["n-pr-m"]', 'Geshem or Gashmu, an Arabian Geshem, Gashmu.', 'or (prolonged) גַּשְׁמוּ; the same as 1653;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6256}/[H5703]', 'inflected', 'heb', 'עֵת', '["ʻêth"]', '["<of> the/ times","the/ time","the/ times"]', '["n-f"]', 'time, especially (adverb with preposition) now, when, etc. after, (al-) ways, × certain, continually, evening, long, (due) season, so (long) as, (even-, evening-, noon-) tide, (meal-), what) time, when.', 'from 5703;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3259}/[H3259]', 'inflected', 'heb', 'יָעַד', '["yâʻad"]', '["so/ let us meet"]', '["v"]', 'to fix upon (by agreement or appointment); by implication, to meet (at a stated time), to summon (to trial), to direct (in a certain quarter or position), to engage (for marriage) agree,(maxke an) appoint(-ment, a time), assemble (selves), betroth, gather (selves, together), meet (together), set (a time).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3715B}/[H3722]', 'inflected', 'heb', 'כְּפִיר', '["kᵉphîyr"]', '["at <the>/ Kephirim"]', '["n-m"]', 'a village (as covered in by walls); also a young lion (perhaps as covered with a mane) (young) lion, village. Compare 3723.', 'from 3722;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7503}/H9034/[H7503]', 'inflected', 'heb', 'רָפָה', '["râphâh"]', '["I will let drop/ it","I will let go/ it"]', '["v"]', 'to slacken (in many applications, literal or figurative) abate, cease, consume, draw (toward evening), fail, (be) faint, be (wax) feeble, forsake, idle, leave, let alone (go, down), (be) slack, stay, be still, be slothful, (be) weak(-en). See 7495.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7121I}/[H7122]', 'inflected', 'heb', 'קָרָא', '["qârâʼ"]', '["by/ proclaiming","to/ proclaim"]', '["v"]', 'to call out to (i.e. properly, address by name, but used in a wide variety of applications) bewray (self), that are bidden, call (for, forth, self, upon), cry (unto), (be) famous, guest, invite, mention, (give) name, preach, (make) proclaim(-ation), pronounce, publish, read, renowned, say.', 'a primitive root (rather identical with 7122 through the idea of accosting a person met);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3289}/[H3289]', 'inflected', 'heb', 'יָעַץ', '["yâʻats"]', '["and/ counselor","and/ counselors of","so/ let us take counsel","so/ they may consult together"]', '["v"]', 'to advise; reflexively, to deliberate or resolve advertise, take advise, advise (well), consult, (give, take) counsel(-lor), determine, devise, guide, purpose.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3820A}/H9021/[H3824]', 'inflected', 'heb', 'לֵב', '["lêb"]', '["from/ heart/ your"]', '["n-m"]', 'the heart; also used (figuratively) very widely for the feelings, the will and even the intellect; likewise for the centre of anything care for, comfortably, consent, × considered, courag(-eous), friend(-ly), ((broken-), (hard-), (merry-), (stiff-), (stout-), double) heart(-ed), × heed, × I, kindly, midst, mind(-ed), × regard(-ed), × themselves, × unawares, understanding, × well, willingly, wisdom.', 'a form of 3824;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0908}/H9038/[H908]', 'inflected', 'heb', 'בָּדָא', '["bâdâʼ"]', '["[are] inventing/ them"]', '["v"]', '(figuratively) to invent devise, feign.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8098S}/[H8085]', 'lemma', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1806J}/[H1802]', 'lemma', 'heb', 'דְּלָיָה', '["Dᵉlâyâh"]', '["Delaiah"]', '["n-pr-m"]', 'Delajah, the name of five Israelites Dalaiah, Delaiah.', 'or (prolonged) דְּלָיָהוּxlit Dᵉlâyâhhûw corrected to Dᵉlâyâhûw; from 1802 and 3050; Jah has delivered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4105H}/[H3190]', 'lemma', 'heb', 'מְהֵיטַבְאֵל', '["Mᵉhêyṭabʼêl"]', '["Mehetabel"]', '["n-pr-m n-pr-f"]', 'Mehetabel, the name of an Edomitish man and woman Mehetabeel, Mehetabel.', 'from 3190 (augmented) and 410; bettered of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5234A}/H9012/[H5234]', 'inflected', 'heb', 'נָכַר', '["nâkar"]', '["and/ I recognized/ !"]', '["v"]', 'properly, to scrutinize, i.e. look intently at; hence (with recognition implied), to acknowledge, be acquainted with, care for, respect, revere, or (with suspicion implied), to disregard, ignore, be strange toward, reject, resign, dissimulate (as if ignorant or disowning) acknowledge, × could, deliver, discern, dissemble, estrange, feign self to be another, know, take knowledge (notice), perceive, regard, (have) respect, behave (make) self strange(-ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5016}/[H5012]', 'inflected', 'heb', 'נְבוּאָה', '["nᵉbûwʼâh"]', '["the/ prophecy"]', '["n-f"]', 'a prediction (spoken or written) prophecy.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5571>', 'inflected', 'heb', 'וסנבלט', '["ve./san.va.Lat"]', '["and/ Sanballat"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7936B}/H9033/[H3739]', 'inflected', 'heb', 'שָׂכַר', '["sâkar"]', '["he had hired/ him"]', '["v"]', 'to hire earn wages, hire (out self), reward, × surely.', 'or (by permutation) סָכַר; (Ezra 4:5), a primitive root (apparently akin (by prosthesis) to 3739 through the idea of temporary purchase; compare 7937);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2778A}/H9030\/[H2779]', 'inflected', 'heb', 'חָרַף', '["châraph"]', '["they may reproach/ me"]', '["v"]', 'to pull off, i.e. (by implication) to expose (as by stripping); specifically, to betroth (as if a surrender); figuratively, to carp at, i.e. defame; to spend the winter betroth, blaspheme, defy, jeopard, rail, reproach, upbraid.', 'a primitive root; also denominative (from 2779)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2900I}/[H2896]', 'inflected', 'heb', 'טוֹבִיָּה', '["Ṭôwbîyâh"]', '["[belonged] to/ Tobiah","for/ Tobiah","to/ Tobiah"]', '["n-pr-m"]', 'Tobijah, the name of three Israelites and of one Samaritan Tobiah, Tobijah.', 'or טוֹבִיָּהוּ; from 2896 and 3050; goodness of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/<H5571>', 'inflected', 'heb', 'ולסנבלט', '["u./le./san.va.Lat"]', '["and/ to/ Sanballat"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4639K}/H9023/[H6213]', 'inflected', 'heb', 'מַעֲשֶׂה', '["maʻăseh"]', '["according to/ work/ his","according to/ works/ his"]', '["n-m"]', 'an action (good or bad); generally, a transaction; abstractly, activity; by implication, a product (specifically, a poem) or (generally) property act, art, bakemeat, business, deed, do(-ing), labor, thing made, ware of making, occupation, thing offered, operation, possession, × well, (handy-, needle-, net-) work(ing, -manship), wrought.', 'from 6213;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5129H}/[H3259]', 'inflected', 'heb', 'נוֹעַדְיָה', '["Nôwʻadyâh"]', '["<to>/ Noadiah"]', '["n-pr-m n-pr-f"]', 'Noadjah, the name of an Israelite, and a false prophetess Noadiah.', 'from 3259 and 3050; convened of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0435}/[H435]', 'inflected', 'heb', 'אֱלוּל', '["ʼĔlûwl"]', '["of/ Elul"]', '["n"]', 'Elul, the sixth Jewish month Elul.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2572}/[H2568]', 'inflected', 'heb', 'חֲמִשִּׁים', '["chămishshîym"]', '["to/ fifty"]', '["n"]', 'fifty fifty.', 'multiple of 2568;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2715}/[H2787]', 'lemma', 'heb', 'חֹר', '["chôr"]', '["[the] nobles of","nobles"]', '["n-m"]', 'properly, white or pure (from the cleansing or shining power of fire); hence (figuratively) noble (in rank) noble.', 'or (fully) חוֹר; from 2787; (compare 2751)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0107}/H9028/[H104]', 'inflected', 'heb', 'אִגֶּרֶת', '["ʼiggereth"]', '["letters/ their"]', '["n-f"]', 'an epistle letter.', 'feminine of 104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2900I}/[H2896]', 'lemma', 'heb', 'טוֹבִיָּה', '["Ṭôwbîyâh"]', '["Tobiah"]', '["n-pr-m"]', 'Tobijah, the name of three Israelites and of one Samaritan Tobiah, Tobijah.', 'or טוֹבִיָּהוּ; from 2896 and 3050; goodness of Jehovah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7935M}/[H7931]', 'inflected', 'heb', 'שְׁכַנְיָה', '["Shᵉkanyâh"]', '["of/ Shecaniah"]', '["n-pr-m"]', 'Shekanjah, the name of nine Israelites Shecaniah, Shechaniah.', 'or (prolonged) שְׁכַנְיָהוּ; from 7931 and 3050; Jah has dwelt;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0733I}/[H732]', 'lemma', 'heb', 'אָרַח', '["ʼÂrach"]', '["Arah"]', '["n-pr-m"]', 'Arach, the name of three Israelites Arah.', 'from 732; way faring;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3076O}/[H3068]', 'inflected', 'heb', 'יְהוֹחָנָן', '["Yᵉhôwchânân"]', '["and/ Jehohanan"]', '["n-pr-m"]', 'Jehochanan, the name of eight Israelites Jehohanan, Johanan. Compare 3110.', 'from 3068 and 2603; Jehovah-favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2896C}/H9023/[H2895]', 'inflected', 'heb', 'טוֹב', '["ṭôwb"]', '["good deeds/ his"]', '["a n-m n-f"]', 'good (as an adjective) in the widest sense; used likewise as a noun, both in the masculine and the feminine, the singular and the plural (good, a good or good thing, a good man or woman; the good, goods or good things, good men or women), also as an adverb (well) beautiful, best, better, bountiful, cheerful, at ease, × fair (word), (be in) favour, fine, glad, good (deed, -lier, -liest, -ly, -ness, -s), graciously, joyful, kindly, kindness, liketh (best), loving, merry, × most, pleasant, pleaseth, pleasure, precious, prosperity, ready, sweet, wealth, welfare, (be) well(-favoured).', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1697G}/H9020/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["and/ words/ my"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3372G}/H9030/[H3372]', 'inflected', 'heb', 'יָרֵא', '["yârêʼ"]', '["to/ make afraid/ me"]', '["v"]', 'to fear; morally to revere; causatively to frighten affright, be (make) afraid, dread(-ful), (put in) fear(-ful, -fully, -ing), (be had in) reverence(-end), × see, terrible (act, -ness, thing).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2608H}/[H2603]', 'lemma', 'heb', 'חֲנַנְיָה', '["Chănanyâh"]', '["Hananiah"]', '["n-pr-m"]', 'Chananjah, the name of thirteen Israelites Hananiah.', 'or חֲנַנְיָהוּ; from 2603 and 3050; Jah has favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H7227A}/[H7231]', 'inflected', 'heb', 'רַב', '["rab"]', '["more than/ many [people]"]', '["a n-m"]', 'abundant (in quantity, size, age, number, rank, quality) (in) abound(-undance, -ant, -antly), captain, elder, enough, exceedingly, full, great(-ly, man, one), increase, long (enough, (time)), (do, have) many(-ifold, things, a time), (ship-)master, mighty, more, (too, very) much, multiply(-tude), officer, often(-times), plenteous, populous, prince, process (of time), suffice(-lent).', 'by contracted from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1479}/[H1479]', 'lemma', 'heb', 'גּוּף', '["gûwph"]', '["let them shut"]', '["v"]', 'properly, to hollow or arch, i.e. (figuratively) close; to shut shut.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4929}/H9023/[H8104]', 'inflected', 'heb', 'מִשְׁמָר', '["mishmâr"]', '["at/ guard post/ his"]', '["n-m"]', 'a guard (the man, the post or the prison); a deposit (figuratively); also (as observed) a usage (abstractly), or an example (concretely) diligence, guard, office, prison, ward, watch.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3188}/[H3187]', 'inflected', 'heb', 'יַחַשׂ', '["yachas"]', '["the/ genealogy"]', '["n-m"]', 'a pedigree or family list (as growing spontaneously) genealogy.', 'from 3187;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3063G}/[H3034]', 'inflected', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["and/ to/ Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5838X}/[H5826]', 'lemma', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7485}/[H7481]', 'lemma', 'heb', 'רַעַמְיָה', '["Raʻamyâh"]', '["Raamiah"]', '["n-pr-m"]', 'Raamjah, an Israelite Raamiah.', 'from 7481 and 3050; Jah has shaken;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5167}/[H5162]', 'lemma', 'heb', 'נַחֲמָנִי', '["Nachămânîy"]', '["Nahamani"]', '["n-pr-m"]', 'Nachamani, an Israelite Nahamani.', 'from 5162; consolatory;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4559}/[H4437]', 'lemma', 'heb', 'מִסְפֶּרֶת', '["Miçpereth"]', '["Mispereth"]', '["n-pr-f"]', 'Mispereth, an Israelite Mispereth. Compare 4458.', 'feminine of 4437; enumeration;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5149}/[H5162]', 'lemma', 'heb', 'נְחוּם', '["Nᵉchûwm"]', '["Nehum"]', '["n-pr-m"]', 'Nechum, an Israelite Nehum.', 'from 5162; comforted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3097I}/[H3068]', 'inflected', 'heb', 'יוֹאָב', '["Yôwʼâb"]', '["and/ Joab"]', '["n-pr-m"]', 'Joab, the name of three Israelites Joab.', 'from 3068 and 1; Jehovah-fathered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1131G}/[H1129]', 'lemma', 'heb', 'בִּנּוּי', '["Binnûwy"]', '["Binnui"]', '["n-pr-m"]', 'Binnui, an Israelite Binnui.', 'from 1129; built up;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2396I}/[H2388]', 'inflected', 'heb', 'חִזְקִיָּה', '["Chizqîyâh"]', '["of/ Hezekiah"]', '["n-pr-m"]', 'Chizkijah, a king of Judah, also the name of two other Israelites Hezekiah, Hizkiah, Hizkijah. Compare 3169.', 'or חִזְקִיָּהוּ; also יְחִזְקִיָּה; or יְחִזְקִיָּהוּ; from 2388 and 3050; strengthened of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2756H}/[H2778]', 'lemma', 'heb', 'חָרִיף', '["Chârîyph"]', '["Hariph"]', '["n-pr-m"]', 'Chariph, the name of two Israelites Hariph.', 'from 2778; autumnal;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5199}/[H5197]', 'inflected', 'heb', 'נְטֹפָה', '["Nᵉṭôphâh"]', '["and/ Netophah"]', '["n-pr-loc"]', 'Netophah, a place in Palestine Netophah.', 'from 5197; distillation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1041}/[H1004]', 'lemma', 'heb', 'בֵּית עַזְמָוֶת', '["Bêyth ʻAzmâveth"]', '["Azmaveth","Beth"]', '["n-pr-loc"]', 'house of Azmaveth, a place in Palestine Bethaz-maveth. Compare 5820.', 'from 1004 and 5820;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6934}/[H6924]', 'inflected', 'heb', 'קַדְמִיאֵל', '["Qadmîyʼêl"]', '["of/ Kadmiel"]', '["n-pr-m"]', 'Kadmiel, the name of three Israelites Kadmiel.', 'from 6924 and 410; presence of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1937}/[H1938]', 'inflected', 'heb', 'הוֹדְוָה', '["Hôwdᵉvâh"]', '["of/ Hodaviah"]', '["n-pr-m"]', 'Hodevah (or Hodevjah), an Israelite Hodevah.', 'a form of 1938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2286A}/[H2285]', 'lemma', 'heb', 'חֲגָבָא', '["Chăgâbâʼ"]', '["Hagabah"]', '["n-pr-m"]', 'Chagaba or Chagabah, one of the Nethinim Hagaba, Hagabah.', 'or חֲגָבָה; feminine of 2285; locust;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5300}/[H5304]', 'lemma', 'heb', 'נְפוּשְׁסִים', '["Nᵉphûwshᵉçîym"]', '["Nephissim"]', '["n"]', 'Nephushesim, a Temple-servant Nephisesim (from the margin).', 'for 5304;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5618}/[H5608]', 'lemma', 'heb', 'סֹפֶרֶת', '["Çôphereth"]', '["Sophereth"]', '["n-pr-f"]', 'Sophereth, a temple servant Sophereth.', 'feminine active participle of 5608; a scribe (properly, female);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0526I}/[H525]', 'lemma', 'heb', 'אָמוֹן', '["ʼÂmôwn"]', '["Amon"]', '["n-pr-m"]', 'Amon, the name of three Israelites Amon.', 'the same as 525;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0114}/[H113]', 'lemma', 'heb', 'אַדּוֹן', '["ʼAddôwn"]', '["Addon"]', '["a"]', 'Addon, apparently an Israelite Addon.', 'probably intensive for 113; powerful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0564I}/[H559]', 'inflected', 'heb', 'אִמֵּר', '["ʼImmêr"]', '["and/ Immer"]', '["n-pr-m"]', 'Immer, the name of five Israelites Immer.', 'from 559; talkative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8550}/[H8537]', 'inflected', 'heb', 'תֻּמִּים', '["Tummîym"]', '["and/ Thummim"]', '["n-pr-m"]', 'perfections, i.e. (techn.) one of the epithets of the objects in the high-priest''s breastplate as an emblem of complete Truth Thummim.', 'plural of 8537;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H7117}/[H7096]', 'inflected', 'heb', 'קְצָת', '["qᵉtsâth"]', '["and/ from/ [the] end of","and/ some of/ [the] end of"]', '["n-f"]', 'a termination (literally or figuratively); also (by implication) a portion; adverbially (with prepositional prefix) after end, part, × some.', 'from 7096;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7339}/[H7337]', 'inflected', 'heb', 'רְחֹב', '["rᵉchôb"]', '["the/ open places","the/ open space"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H0995}/[H995]', 'inflected', 'heb', 'בִּין', '["bîyn"]', '["and/ the/ [ones who] understood"]', '["v"]', 'to separate mentally (or distinguish), i.e.(generally) understand attend, consider, be cunning, diligently, direct, discern, eloquent, feel, inform, instruct, have intelligence, know, look well to, mark, perceive, be prudent, regard, (can) skill(-full), teach, think, (cause, make to, get, give, have) understand(-ing), view, (deal) wise(-ly, man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4993J}/[H4991]', 'lemma', 'heb', 'מַתִּתְיָה', '["Mattithyâh"]', '["Mattithiah"]', '["n-pr-m"]', 'Mattithjah, the name of four Israelites Mattithiah. n', 'or מַתִּתְיָהוּ; from 4991 and 3050; gift of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8087J}/[H8088]', 'inflected', 'heb', 'שֶׁמַע', '["Shemaʻ"]', '["and/ Shema"]', '["n-pr-m"]', 'Shema, the name of a place in Palestine and of four Israelites Shema.', 'for the same as 8088;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6043G}/[H6030]', 'inflected', 'heb', 'עֲנָיָה', '["ʻĂnâyâh"]', '["and/ Anaiah"]', '["n-pr-m"]', 'Anajah, the name of two Israelites Anaiah.', 'from 6030; Jah has answered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0223I}/[H217]', 'inflected', 'heb', 'אוּרִיָּה', '["ʼÛwrîyâh"]', '["and/ Uriah"]', '["n-pr-m"]', 'Urijah, the name of one Hittite and five Israelites Uriah, Urijah.', 'or (prolonged) אוּרִיָּהוּ ; from 217 and 3050; flame of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2518K}/[H2506]', 'inflected', 'heb', 'חִלְקִיָּה', '["Chilqîyâh"]', '["and/ Hilkiah"]', '["n-pr-m"]', 'Chilhijah, the name of eight Israelites Hillkiah.', 'or חִלְקִיָּהוּ; from 2506 and 3050; portion of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4641Q}/[H4639]', 'inflected', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["and/ Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6305K}/[H6299]', 'lemma', 'heb', 'פְּדָיָה', '["Pᵉdâyâh"]', '["Pedaiah"]', '["n-pr-m"]', 'Pedajah, the name of six Israelites Pedaiah.', 'or פְּדָיָהוּ; from 6299 and 3050; Jah has ransomed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4332H}/[H4310]', 'inflected', 'heb', 'מִישָׁאֵל', '["Mîyshâʼêl"]', '["and/ Mishael"]', '["n-pr-m"]', 'Mishael, the name of three Israelites Mishael.', 'from 4310 and 410 with the abbreviated form insep. relatively (see 834) interposed; who (is) what God (is) ?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4441P}/[H4428]', 'inflected', 'heb', 'מַלְכִּיָּה', '["Malkîyâh"]', '["and/ Malkijah"]', '["n-pr-m"]', 'Malkijah, the name of ten Israelites Malchiah, Malchijah.', 'or מַלְכִּיָּהוּlemma מַלְכִּיָהוּ missing dagesh, corrected to מַלְכִּיָּהוּ; (Jeremiah 38:6), from 4428 and 3050; king of (i.e. appointed by) Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2828H}/[H2831]', 'inflected', 'heb', 'חָשֻׁם', '["Châshum"]', '["and/ Hashum"]', '["n-pr-m"]', 'Chashum, the name of two or three Israelites Hashum.', 'from the same as 2831; enriched;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2806}/[H2803]', 'inflected', 'heb', 'חַשְׁבַּדָּנָה', '["Chashbaddânâh"]', '["and/ Hashbaddanah"]', '["n-pr-m"]', 'Chasbaddanah, an Israelite Hasbadana.', 'from 2803 and 1777; considerate judge;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148U}/[H2142]', 'lemma', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4918T}\/[H7999]', 'inflected', 'heb', 'מְשֻׁלָּם', '["Mᵉshullâm"]', '["Meshullam"]', '["n-pr-m"]', 'Meshullam, the name of seventeen Israelites Meshullam.', 'from 7999; allied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H6605A}/H9043/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["and/ just as/ opened [it]/ he"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4607}/[H5927]', 'inflected', 'heb', 'מֹעַל', '["môʻal"]', '["in/ [the] raising of"]', '["n-m"]', 'a raising (of the hands) lifting up.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3442J}/[H3091]', 'inflected', 'heb', 'יֵשׁוּעַ', '["Yêshûwaʻ"]', '["and/ Jeshua"]', '["n-pr-m n-pr-loc"]', 'Jeshua, the name of ten Israelites, also of a place in Palestine Jeshua.', 'for 3091; he will save;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1137M}/[H1129]', 'inflected', 'heb', 'בָּנִי', '["Bânîy"]', '["and/ Bani"]', '["n-pr-m"]', 'Bani, the name of five Israelites Bani.', 'from 1129; built;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3226I}/[H3225]', 'lemma', 'heb', 'יָמִין', '["Yâmîyn"]', '["Jamin"]', '["n-pr-m"]', 'Jamin, the name of three Israelites Jamin. See also 1144.', 'the same as 3225;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6126J}/[H6117]', 'lemma', 'heb', 'עַקּוּב', '["ʻAqqûwb"]', '["Akkub"]', '["n-pr-m"]', 'Akkub, the name of five Israelites Akkub.', 'from 6117; insidious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7678H}/[H7676]', 'lemma', 'heb', 'שַׁבְּתַי', '["Shabbᵉthay"]', '["Shabbethai"]', '["n-pr-m"]', 'Shabbethai, the name of three Israelites Shabbethai.', 'from 7676; restful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1941G}/[H1938]', 'lemma', 'heb', 'הוֹדִיָּה', '["Hôwdîyâh"]', '["Hodiah"]', '["n-pr-m"]', 'Hodijah, the name of three Israelites Hodijah.', 'a form of 1938;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4641R}/[H4639]', 'lemma', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7042G}/[H7038]', 'lemma', 'heb', 'קְלִיטָא', '["Qᵉlîyṭâʼ"]', '["Kelita"]', '["n-pr-m"]', 'Kelita, the name of three Israelites Kelita.', 'from 7038; maiming;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5838Y}/[H5826]', 'lemma', 'heb', 'עֲזַרְיָה', '["ʻĂzaryâh"]', '["Azariah"]', '["n-pr-m"]', 'Azarjah, the name of nineteen Israelites Azariah.', 'or עֲזַרְיָהוּ; from 5826 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3107P}/[H3075]', 'lemma', 'heb', 'יוֹזָבָד', '["Yôwzâbâd"]', '["Jozabad"]', '["n-pr-m"]', 'Jozabad, the name of ten Israelites Josabad, Jozabad.', 'a form of 3075;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2605K}/[H2603]', 'lemma', 'heb', 'חָנָן', '["Chânân"]', '["Hanan"]', '["n-pr-m"]', 'Chanan, the name of seven Israelites Canan.', 'from 2603; favor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6411A}/[H6381]', 'lemma', 'heb', 'פְּלָיָה', '["Pᵉlâyâh"]', '["Pelaiah"]', '["n-pr-m"]', 'Pelajah, the name of three Israelites Pelaiah.', 'or פְּלָאיָה; from 6381 and 3050; Jah has distinguished;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8451}/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["<to> the/ law","to/ [the] instruction"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7760M}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ they gave"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4744}\/[H7121]', 'inflected', 'heb', 'מִקְרָא', '["miqrâʼ"]', '["<in> the/ reading"]', '["n-m"]', 'something called out, i.e. a public meeting (the act, the persons, or the place); also a rehearsal assembly, calling, convocation, reading.', 'from 7121;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5830G}/[H5833]', 'inflected', 'heb', 'עֶזְרָא', '["ʻEzrâʼ"]', '["and/ Ezra"]', '["n-pr-m"]', 'Ezra, an Israelite Ezra.', 'a variation of 5833;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4924C}/[H8080]', 'lemma', 'heb', 'מַשְׁמָן', '["mashmân"]', '["fat foods"]', '["n-m"]', 'fat, i.e. (literally and abstractly) fatness; but usually (figuratively and concretely) a rich dish, a fertile field, a robust man fat (one, -ness, -test, -test place).', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4477}/[H4985]', 'lemma', 'heb', 'מַמְתַּק', '["mamtaq"]', '["[is] sweetness<es>","sweet things"]', '["n-m"]', 'something sweet (literally or figuratively) (most) sweet.', 'from 4985;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H0113>/H9025', 'inflected', 'heb', 'לאדנינו', '["la./''a.do.Nei./nu"]', '["to/ lord<s>/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2304}/[H2302]', 'lemma', 'heb', 'חֶדְוָה', '["chedvâh"]', '["[the] joy of"]', '["n-f"]', 'rejoicing gladness, joy.', 'from 2302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4581}/H9026/[H5810]', 'inflected', 'heb', 'מָעוֹז', '["mâʻôwz"]', '["[is] refuge/ your"]', '["n-m"]', 'a fortified place; figuratively, a defence force, fort(-ress), rock, strength(-en), (× most) strong (hold).', '(also מָעוּז ); or מָעֹז (also מָעֻז; from 5810;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7971G}/[H7971]', 'inflected', 'heb', 'שָׁלַח', '["shâlach"]', '["and/ to/ send"]', '["v"]', 'to send away, for, or out (in a great variety of applications) × any wise, appoint, bring (on the way), cast (away, out), conduct, × earnestly, forsake, give (up), grow long, lay, leave, let depart (down, go, loose), push away, put (away, forth, in, out), reach forth, send (away, forth, out), set, shoot (forth, out), sow, spread, stretch forth (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7919A}/[H7919]', 'inflected', 'heb', 'שָׂכַל', '["sâkal"]', '["and/ by/ giving attention","and/ to/ gain insight"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5929}/[H5927]', 'inflected', 'heb', 'עָלֶה', '["ʻâleh"]', '["and/ leaves of"]', '["n-m"]', 'a leaf (as coming up on a tree); collectively, foliage branch, leaf.', 'from 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1918>', 'opaque', 'heb', 'הֲדַס', '["hădaç"]', '["a myrtle tree","myrtle"]', '["n-m"]', 'the myrtle myrtle (tree).', 'of uncertain derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3789}\/[H3789]', 'inflected', 'heb', 'כָּתַב', '["kâthab"]', '["according to <the>/ [what] is written"]', '["v"]', 'to grave, by implication, to write (describe, inscribe, prescribe, subscribe) describe, record, prescribe, subscribe, write(-ing, -ten).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2691A}/H9028/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["and/ in/ courtyards/ their"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2691A}/[H2690]', 'inflected', 'heb', 'חָצֵר', '["châtsêr"]', '["and/ in/ [the] courtyards of"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7339}/[H7337]', 'inflected', 'heb', 'רְחֹב', '["rᵉchôb"]', '["and/ in the/ open places","and/ in/ [the] open space of"]', '["n-f"]', 'a width, i.e. (concretely) avenue or area broad place (way), street. See also 1050.', 'or רְחוֹב; from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0669I}/[H672]', 'lemma', 'heb', 'אֶפְרַיִם', '["ʼEphrayim"]', '["Ephraim"]', '["n-pr-m"]', 'Ephrajim, a son of Joseph; also the tribe descended from him, and its territory Ephraim, Ephraimites.', 'dual of masculine form of 672; double fruit;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3442O}/[H3091]', 'lemma', 'heb', 'יֵשׁוּעַ', '["Yêshûwaʻ"]', '["Jeshua"]', '["n-pr-m n-pr-loc"]', 'Jeshua, the name of ten Israelites, also of a place in Palestine Jeshua.', 'for 3091; he will save;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H3117J>', 'inflected', 'heb', 'וביום', '["u./vai./Yom"]', '["and/ on the/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H4941G}\/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["according to the/ ordinance"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6685}/[H6684]', 'inflected', 'heb', 'צוֹם', '["tsôwm"]', '["with <the>/ fasting","with/ fasting"]', '["n-m"]', 'a fast fast(-ing).', 'or צֹם; from 6684;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8242}/[H8264]', 'inflected', 'heb', 'שַׂק', '["saq"]', '["and/ in/ sackcloth<s>"]', '["n-m"]', 'properly, a mesh (as allowing a liquid to run through), i.e. coarse loose cloth or sacking (used in mourning and for bagging); hence, a bag (for grain, etc.) sack(-cloth, -clothes).', 'from 8264;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5771G}/[H5753]', 'inflected', 'heb', 'עָוֺן', '["ʻâvôn"]', '["and/ [the] iniquities of"]', '["n-m"]', 'perversity, i.e. (moral) evil fault, iniquity, mischeif, punishment (of iniquity), sin.', 'or עָווֹן; (2 Kings 7:9; Psalm 51:5 [7]), from 5753;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7645H}/[H7644]', 'lemma', 'heb', 'שְׁבַנְיָה', '["Shᵉbanyâh"]', '["Shebaniah"]', '["n-pr-m"]', 'Shebanjah, the name of three or four Israelites Shebaniah.', 'or שְׁבַנְיָהוּ; from the same as 7644 and 3050; Jah has grown (i.e. prospered);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1138G}/[H1129]', 'lemma', 'heb', 'בֻּנִּי', '["Bunnîy"]', '["Bunni"]', '["n-pr-m"]', 'Bunni or Buni, an Israelite Bunni.', 'or (fuller) בּוּנִי; from 1129; built;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8274G}/[H8273]', 'lemma', 'heb', 'שֵׁרֵבְיָה', '["Shêrêbᵉyâh"]', '["Sherebiah"]', '["n-pr-m"]', 'Sherebjah, the name of two Israelites Sherebiah.', 'from 8273 and 3050; Jah has brought heat;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1137M}/[H1129]', 'lemma', 'heb', 'בָּנִי', '["Bânîy"]', '["Bani"]', '["n-pr-m"]', 'Bani, the name of five Israelites Bani.', 'from 1129; built;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3662}/[H3661]', 'lemma', 'heb', 'כְּנָנִי', '["Kᵉnânîy"]', '["Kenani"]', '["n-pr-m"]', 'Kenani, an Israelite Chenani.', 'from 3661; planted;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2813H}/[H2808]', 'lemma', 'heb', 'חֲשַׁבְנְיָה', '["Chăshabnᵉyâh"]', '["Hashabneiah"]', '["n-pr-m"]', 'Chashabnejah, the name of two Israelites Hashabniah.', 'from 2808 and 3050; thought of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6611I}/[H6605]', 'lemma', 'heb', 'פְּתַחְיָה', '["Pᵉthachyâh"]', '["Pethahiah"]', '["n-pr-m"]', 'Pethachjah, the name of four Israelites Pethakiah.', 'from 6605 and 3050; Jah has opened;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6635A}/[H6633]', 'inflected', 'heb', 'צָבָא', '["tsâbâʼ"]', '["and/ [the] host of","and/ an army"]', '["n-m"]', 'a mass of persons (or figuratively, things), especially reg. organized for war (an army); by implication, a campaign, literally or figuratively (specifically, hardship, worship) appointed time, ( ) army, ( ) battle, company, host, service, soldiers, waiting upon, war(-fare).', 'or (feminine) צְבָאָה; from 6633;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0087}/[H48]', 'inflected', 'heb', 'אַבְרָם', '["ʼAbrâm"]', '["<in>/ Abram"]', '["n-pr-m"]', 'Abram, the original name of Abraham Abram.', 'contracted from 48; high father;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7760M}/[H7760]', 'inflected', 'heb', 'שׂוּם', '["sûwm"]', '["and/ he assigned","and/ you made"]', '["v"]', 'to put (used in a great variety of applications, literal, figurative, inferentially, and elliptically) × any wise, appoint, bring, call (a name), care, cast in, change, charge, commit, consider, convey, determine, disguise, dispose, do, get, give, heap up, hold, impute, lay (down, up), leave, look, make (out), mark, name, × on, ordain, order, paint, place, preserve, purpose, put (on), regard, rehearse, reward, (cause to) set (on, up), shew, stedfastly, take, × tell, tread down, (over-)turn, × wholly, work.', 'or שִׂים; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H8064>', 'inflected', 'heb', 'משמים', '["Mi./sha.ma.yim","mi./sha.Ma.yim","mi./sha.ma.Yim","mi./she.Mei"]', '["from/ [the] heavens","from/ [the] heavens of","from/ heaven"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8451}/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["and/ [the] instruction","and/ [the] law","and/ [the] law of","and/ a law","and/ instruction","and/ instruction of","and/ laws of"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4687}/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["and/ commandments"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2706G}/[H2710]', 'inflected', 'heb', 'חֹק', '["chôq"]', '["and/ a decree","and/ statutes"]', '["n-m"]', 'an enactment; hence, an appointment (of time, space, quantity, labor or usage) appointed, bound, commandment, convenient, custom, decree(-d), due, law, measure, × necessary, ordinance(-nary), portion, set time, statute, task.', 'from 2710;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7458}/H9028/[H7456]', 'inflected', 'heb', 'רָעָב', '["râʻâb"]', '["for/ hunger/ their"]', '["n-m"]', 'hunger (more or less extensive) dearth, famine, famished, hunger.', 'from 7456;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6772}/H9028/[H6770]', 'inflected', 'heb', 'צָמָא', '["tsâmâʼ"]', '["for/ thirst/ their"]', '["n-m"]', 'thirst (literally or figuratively) thirst(-y).', 'from 6770;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027S}/H9021/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ your"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H0001G}/H9025/[H1]', 'inflected', 'heb', 'אָב', '["ʼâb"]', '["and/ ancestors/ our"]', '["n-m"]', 'father, in a literal and immediate, or figurative and remote application chief, (fore-) father(-less), × patrimony, principal. Compare names in ''Abi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6381}/H9021/[H6381]', 'inflected', 'heb', 'פָּלָא', '["pâlâʼ"]', '["wonders/ your"]', '["v"]', 'properly, perhaps to separate, i.e. distinguish (literally or figuratively); by implication, to be (causatively, make) great, difficult, wonderful accomplish, (arise...too, be too) hard, hidden, things too high, (be, do, do a, shew) marvelous(-ly, -els, things, work), miracles, perform, separate, make singular, (be, great, make) wonderful(-ers, -ly, things, works), wondrous (things, works, -ly).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5659}/H9028/[H5647]', 'inflected', 'heb', 'עַבְדוּת', '["ʻabdûwth"]', '["to/ servitude/ their"]', '["n-f"]', 'servitude bondage.', 'from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4805H}/H9028/[H4784]', 'inflected', 'heb', 'מְרִי', '["mᵉrîy"]', '["in/ rebellion/ their"]', '["n-m"]', 'bitterness, i.e. (figuratively) rebellion; concretely, bitter, or rebellious bitter, (most) rebel(-lion, -lious).', 'from 4784;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5547}/[H5545]', 'lemma', 'heb', 'סְלִיחָה', '["çᵉlîychâh"]', '["forgiveness<es>"]', '["n-f"]', 'pardon forgiveness, pardon.', 'from 5545;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5800A}/H9038/[H5800]', 'inflected', 'heb', 'עָזַב', '["ʻâzab"]', '["I will abandon/ them","I will forsake/ them","you abandoned/ them"]', '["v"]', 'to loosen, i.e. relinquish, permit, etc. commit self, fail, forsake, fortify, help, leave (destitute, off), refuse, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5007B}/[H5006]', 'lemma', 'heb', 'נְאָצָה', '["nᵉʼâtsâh"]', '["blasphemies"]', '["n-f"]', 'scorn blasphemy.', 'or נֶאָצָה; from 5006;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7356B}/H9021/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["in/ compassion<s>/ your"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H3117G>/H9028', 'inflected', 'heb', 'בימיהם', '["be./yo.Ma/m","vi./mei./Hem"]', '["in/ days/ their","in/ daytime/ their"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/H9009/{H1870K}/[H1869]', 'inflected', 'heb', 'דֶּרֶךְ', '["derek"]', '["in/ the/ way"]', '["n-m"]', 'a road (as trodden); figuratively, a course of life or mode of action, often adverb along, away, because of, by, conversation, custom, (east-) ward, journey, manner, passenger, through, toward, (high-) (path-) way(-side), whither(-soever).', 'from 1869;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7307G}/H9021/[H7306]', 'inflected', 'heb', 'רוּחַ', '["rûwach"]', '["and/ spirit/ your"]', '["n-f"]', 'wind; by resemblance breath, i.e. a sensible (or even violent) exhalation; figuratively, life, anger, unsubstantiality; by extension, a region of the sky; by resemblance spirit, but only of a rational being (including its expression and functions) air, anger, blast, breath, × cool, courage, mind, × quarter, × side, spirit(-ual), tempest, × vain, (whirl-) wind(-y).', 'from 7306;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7919A}/H9038/[H7919]', 'inflected', 'heb', 'שָׂכַל', '["sâkal"]', '["to/ instruct/ them"]', '["v"]', 'to be (causatively, make or act) circumspect and hence, intelligent consider, expert, instruct, prosper, (deal) prudent(-ly), (give) skill(-ful), have good success, teach, (have, make to) understand(-ing), wisdom, (be, behave self, consider, make) wise(-ly), guide wittingly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4478A}/H9021/[H4100]', 'inflected', 'heb', 'מָן', '["mân"]', '["and/ manna/ your"]', '["n-m"]', 'literally a whatness (so to speak), i.e. manna (so called from the question about it) manna.', 'from 4100;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6310G}/H9028/[H6284]', 'inflected', 'heb', 'פֶּה', '["peh"]', '["from/ mouth/ their"]', '["n-m"]', 'the mouth (as the means of blowing), whether literal or figurative (particularly speech); specifically edge, portion or side; adverbially (with preposition) according to accord(-ing as, -ing to), after, appointment, assent, collar, command(-ment), × eat, edge, end, entry, file, hole, × in, mind, mouth, part, portion, × (should) say(-ing), sentence, skirt, sound, speech, × spoken, talk, tenor, × to, two-edged, wish, word.', 'from 6284;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3557}/H9038/[H3557]', 'inflected', 'heb', 'כּוּל', '["kûwl"]', '["you sustained/ them"]', '["v"]', 'properly, to keep in; hence, to measure; figuratively, to maintain (in various senses) (be able to, can) abide, bear, comprehend, contain, feed, forbearing, guide, hold(-ing in), nourish(-er), be present, make provision, receive, sustain, provide sustenance (victuals).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8008}/H9028/[H8071]', 'inflected', 'heb', 'שַׂלְמָה', '["salmâh"]', '["clothes/ their"]', '["n-f"]', 'a dress clothes, garment, raiment.', 'transp. for 8071;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5971A}/[H6004]', 'inflected', 'heb', 'עַם', '["ʻam"]', '["and/ [the] people","and/ [the] people of","and/ [the] peoples of","and/ a people","and/ a people of","and/ people","and/ peoples"]', '["n-m"]', 'a people (as a congregated unit); specifically, a tribe (as those of Israel); hence (collectively) troops or attendants; figuratively, a flock folk, men, nation, people.', 'from 6004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1121G}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["the/ children","the/ sons"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7522}/H9028/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["according to/ pleasure/ their","according to/ will/ their"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5727}/[H5727]', 'inflected', 'heb', 'עָדַן', '["ʻâdan"]', '["and/ they luxuriated"]', '["v"]', 'to be soft or pleasant; figuratively and reflexively, to live voluptuously delight self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2898}/H9021/[H2895]', 'inflected', 'heb', 'טוּב', '["ṭûwb"]', '["in/ goodness/ your"]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8451}/H9021/[H3384]', 'inflected', 'heb', 'תּוֹרָה', '["tôwrâh"]', '["<of> law/ your","law/ your"]', '["n-f"]', 'a precept or statute, especially the Decalogue or Pentateuch law.', 'or תֹּרָה; from 3384;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1458}/H9028/[H1460]', 'inflected', 'heb', 'גַּו', '["gav"]', '["back/ their"]', '["n-m"]', 'the back back.', 'another form for 1460;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7725O}/H9038/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["to/ bring back/ them"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6869B}/H9028/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["distress/ their","troubles/ their"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H7356B}/H9021/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["and/ according to/ compassion<s>/ your"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3467}/H9038/[H3467]', 'inflected', 'heb', 'יָשַׁע', '["yâshaʻ"]', '["and/ he saves/ them","and/ they delivered/ them"]', '["v"]', 'properly, to be open, wide or free, i.e. (by implication) to be safe; causatively, to free or succor × at all, avenging, defend, deliver(-er), help, preserve, rescue, be safe, bring (having) salvation, save(-iour), get victory.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H5117}/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["and/ just as/ was rest"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2199}/H9031/[H2199]', 'inflected', 'heb', 'זָעַק', '["zâʻaq"]', '["and/ they cried out to/ you"]', '["v"]', 'to shriek (from anguish or danger); by analogy, (as a herald) to announce or convene publicly assemble, call (together), (make a) cry (out), come with such a company, gather (together), cause to be proclaimed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5337}/H9038/[H5337]', 'inflected', 'heb', 'נָצַל', '["nâtsal"]', '["and/ you rescued/ them"]', '["v"]', 'to snatch away, whether in a good or a bad sense × at all, defend, deliver (self), escape, × without fail, part, pluck, preserve, recover, rescue, rid, save, spoil, strip, × surely, take (out).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7356B}/H9021/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["according to/ compassion<s>/ your"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4687}/H9021/[H6680]', 'inflected', 'heb', 'מִצְוָה', '["mitsvâh"]', '["for/ commandments/ your","to/ commandments/ your"]', '["n-f"]', 'a command, whether human or divine (collectively, the Law) (which was) commanded(-ment), law, ordinance, precept.', 'from 6680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4941G}/H9021/[H8199]', 'inflected', 'heb', 'מִשְׁפָּט', '["mishpâṭ"]', '["and/ in/ judgments/ your"]', '["n-m"]', 'properly, a verdict (favorable or unfavorable) pronounced judicially, especially a sentence or formal decree (human or (participant''s) divine law, individual or collective), including the act, the place, the suit, the crime, and the penalty; abstractly, justice, including a participant''s right or privilege (statutory or customary), or even a style adversary, ceremony, charge, × crime, custom, desert, determination, discretion, disposing, due, fashion, form, to be judged, judgment, just(-ice, -ly), (manner of) law(-ful), manner, measure, (due) order, ordinance, right, sentence, usest, × worthy, wrong.', 'from 8199;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6203}/H9028/[H6202]', 'inflected', 'heb', 'עֹרֶף', '["ʻôreph"]', '["and/ neck/ their"]', '["n-m"]', 'the nape or back of the neck (as declining); hence, the back generally (whether literal or figurative) back ((stiff-) neck((-ed).', 'from 6202;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7356B}/H9021/[H7355]', 'inflected', 'heb', 'רַחַם', '["racham"]', '["and/ in/ compassion<s>/ your"]', '["n-f"]', 'compassion (in the plural); by extension, the womb (as cherishing the fetus); by implication, a maiden bowels, compassion, damsel, tender love, (great, tender) mercy, pity, womb.', 'from 7355;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4428G}/H9025/[H4427]', 'inflected', 'heb', 'מֶלֶךְ', '["melek"]', '["to/ king/ our","to/ kings/ our"]', '["n-m"]', 'a king king, royal.', 'from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8269}/H9025/[H8323]', 'inflected', 'heb', 'שַׂר', '["sar"]', '["to/ leaders/ our"]', '["n-m"]', 'a head person (of any rank or class) captain (that had rule), chief (captain), general, governor, keeper, lord,(-task-)master, prince(-ipal), ruler, steward.', 'from 8323;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H3548}/H9025/[H3547]', 'inflected', 'heb', 'כֹּהֵן', '["kôhên"]', '["and/ to/ priests/ our"]', '["n-m"]', 'literally one officiating, a priest; also (by courtesy) an acting priest (although a layman) chief ruler, × own, priest, prince, principal officer.', 'active participle of 3547;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5030}/H9025/[H5012]', 'inflected', 'heb', 'נָבִיא', '["nâbîyʼ"]', '["and/ to/ prophets/ our"]', '["n-m"]', 'a prophet or (generally) inspired man prophecy, that prophesy, prophet.', 'from 5012;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5715}/H9021/[H5707]', 'inflected', 'heb', 'עֵדוּת', '["ʻêdûwth"]', '["and/ to/ testimonies/ your"]', '["n-f"]', 'testimony testimony, witness.', 'feminine of 5707;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4438}/H9028/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["in/ own kingdom/ their"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2898}/H9021/[H2895]', 'inflected', 'heb', 'טוּב', '["ṭûwb"]', '["and/ in/ goodness/ your"]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7342H}/[H7337]', 'inflected', 'heb', 'רָחָב', '["râchâb"]', '["<the>/ broad"]', '["a"]', 'roomy, in any (or every) direction, literally or figuratively broad, large, at liberty, proud, wide.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8082}/[H8080]', 'inflected', 'heb', 'שָׁמֵן', '["shâmên"]', '["and/ <the>/ fertile"]', '["a"]', 'greasy, i.e. gross; figuratively, rich fat, lusty, plenteous.', 'from 8080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5647H}/H9031/[H5647]', 'inflected', 'heb', 'עָבַד', '["ʻâbad"]', '["they served/ you"]', '["v"]', 'to work (in any sense); by implication, to serve, till, (causatively) enslave, etc. × be, keep in bondage, be bondmen, bond-service, compel, do, dress, ear, execute, husbandman, keep, labour(-ing man, bring to pass, (cause to, make to) serve(-ing, self), (be, become) servant(-s), do (use) service, till(-er), transgress (from margin), (set a) work, be wrought, worshipper,', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2898}/H9024/[H2895]', 'inflected', 'heb', 'טוּב', '["ṭûwb"]', '["good thing[s]/ its"]', '["n-m"]', 'good (as a noun), in the widest sense, especially goodness (superlative concretely, the best), beauty, gladness, welfare fair, gladness, good(-ness, thing, -s), joy, go well with.', 'from 2895;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8393}/H9024/[H935]', 'inflected', 'heb', 'תְּבוּאָה', '["tᵉbûwʼâh"]', '["and/ produce/ its"]', '["n-f"]', 'income, i.e. produce (literally or figuratively) fruit, gain, increase, revenue.', 'from 935;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H2403B}/H9025/[H2398]', 'inflected', 'heb', 'חַטָּאָה', '["chaṭṭâʼâh"]', '["in/ sins/ our"]', '["n-f"]', 'an offence (sometimes habitual sinfulness), and its penalty, occasion, sacrifice, or expiation; also (concretely) an offender punishment (of sin), purifying(-fication for sin), sin(-ner, offering).', 'or חַטָּאת; from 2398;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/<H0929>/H9025', 'inflected', 'heb', 'ובבהמתנו', '["u./vi/v.hem.Te./nu"]', '["and/ over/ cattle/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6869B}/[H6862]', 'inflected', 'heb', 'צָרָה', '["tsârâh"]', '["and/ [are] in/ distress"]', '["n-f"]', 'tightness (i.e. figuratively, trouble); transitively, a female rival adversary, adversity, affliction, anguish, distress, tribulation, trouble.', 'feminine of 6862;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0587}\/[H595]', 'inflected', 'heb', 'אֲנַחְנוּ', '["ʼănachnûw"]', '["we"]', '["p"]', 'we ourselves, us, we.', 'apparently from 595;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0548}/[H543]', 'lemma', 'heb', 'אֲמָנָה', '["ʼămânâh"]', '["a trustworthy arrangement"]', '["n-f"]', 'something fixed, i.e. a covenant. an allowance certain portion, sure.', 'feminine of 543;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2856}/[H2856]', 'inflected', 'heb', 'חָתַם', '["châtham"]', '["<the>/ sealed","the/ sealed [document]","the/ sealed [documents]","the/ sealed [one]"]', '["v"]', 'to close up; especially to seal make an end, mark, seal (up), stop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3881}/H9025/[H3878]', 'inflected', 'heb', 'לֵוִיִּי', '["Lêvîyîy"]', '["Levites/ our"]', '["a"]', 'a Levite or descendant of Levi Leviite.', 'or לֵוִי; patronymically from 3878;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6667J}/[H6664]', 'inflected', 'heb', 'צִדְקִיָּה', '["Tsidqîyâh"]', '["and/ Zedekiah"]', '["n-pr-m"]', 'Tsidkijah, the name of six Israelites Zedekiah, Zidkijah.', 'or צִדְקִיָּהוּ; from 6664 and 3050; right of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3414M}/[H7311]', 'lemma', 'heb', 'יִרְמְיָה', '["Yirmᵉyâh"]', '["Jeremiah"]', '["n-pr-m"]', 'Jirmejah, the name of eight or nine Israelites Jeremiah.', 'or יִרְמְיָהוּ; from 7311 and 3050; Jah will rise;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6583H}/[H6582]', 'lemma', 'heb', 'פַּשְׁחוּר', '["Pashchûwr"]', '["Pashhur"]', '["n-pr-m"]', 'Pashchur, the name of four Israelites Pashur.', 'probably from 6582; liberation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0568M}/[H559]', 'lemma', 'heb', 'אֲמַרְיָה', '["ʼĂmaryâh"]', '["Amariah"]', '["n-pr-m"]', 'Amarjah, the name of nine Israelites Amariah.', 'or prolonged אֲמַרְיָהוּ; from 559 and 3050; Jah has said (i.e. promised);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4441Q}/[H4428]', 'lemma', 'heb', 'מַלְכִּיָּה', '["Malkîyâh"]', '["Malkijah"]', '["n-pr-m"]', 'Malkijah, the name of ten Israelites Malchiah, Malchijah.', 'or מַלְכִּיָּהוּlemma מַלְכִּיָהוּ missing dagesh, corrected to מַלְכִּיָּהוּ; (Jeremiah 38:6), from 4428 and 3050; king of (i.e. appointed by) Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2407J>', 'opaque', 'heb', 'חַטּוּשׁ', '["Chaṭṭûwsh"]', '["Hattush"]', '["n-pr-m"]', 'Chattush, the name of four or five Israelites Hattush.', 'from an unused root of uncertain signification;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7645I}/[H7644]', 'lemma', 'heb', 'שְׁבַנְיָה', '["Shᵉbanyâh"]', '["Shebaniah"]', '["n-pr-m"]', 'Shebanjah, the name of three or four Israelites Shebaniah.', 'or שְׁבַנְיָהוּ; from the same as 7644 and 3050; Jah has grown (i.e. prospered);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4409J}/[H4427]', 'lemma', 'heb', 'מַלּוּךְ', '["Mallûwk"]', '["Malluch"]', '["n-pr-m"]', 'Malluk, the name of five Israelites Malluch, Melichu (from the margin).', 'or מַלּוּכִי; (Nehemiah 12:14), from 4427; regnant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2766K}/[H2763]', 'lemma', 'heb', 'חָרִם', '["Chârim"]', '["Harim"]', '["n-pr-m"]', 'Charim, an Israelite Harim.', 'from 2763; snub-nosed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5662Q}/[H5647]', 'lemma', 'heb', 'עֹבַדְיָה', '["ʻÔbadyâh"]', '["Obadiah"]', '["n-pr-m"]', 'Obadjah, the name of thirteen Israelites Obadiah.', 'or עֹבַדְיָהוּ; active participle of 5647 and 3050; serving Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1841G}/[H1840]', 'lemma', 'heb', 'דָּנִיֵּאל', '["Dânîyêʼl"]', '["Daniel"]', '["n-pr-m"]', 'Danijel, the Hebrew prophet Daniel.', '(Aramaic) corresponding to 1840;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1599}/[H1598]', 'lemma', 'heb', 'גִּנְּתוֹן', '["Ginnᵉthôwn"]', '["Ginnethoi","Ginnethon"]', '["n-pr-m"]', 'Ginnethon or Ginnetho, an Israelite Ginnetho, Ginnethon.', 'or גִּנְּתוֹ; from 1598; gardener;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1263H}/[H1288]', 'lemma', 'heb', 'בָּרוּךְ', '["Bârûwk"]', '["Baruch"]', '["n-pr-m"]', 'Baruk, the name of three Israelites Baruch.', 'passive participle from 1288; blessed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4918U}/[H7999]', 'lemma', 'heb', 'מְשֻׁלָּם', '["Mᵉshullâm"]', '["Meshullam"]', '["n-pr-m"]', 'Meshullam, the name of seventeen Israelites Meshullam.', 'from 7999; allied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0029M}/[H1]', 'lemma', 'heb', 'אֲבִיָּה', '["ʼĂbîyâh"]', '["Abijah"]', '["n-pr-m"]', 'Abijah, the name of several Israelite men and two Israelitesses Abiah, Abijah.', 'or prolonged אֲבִיָּהוּ ; from 1 and 3050; father (i.e. worshipper) of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4326I}/[H4509]', 'lemma', 'heb', 'מִיָּמִן', '["Mîyâmin"]', '["Mijamin"]', '["n-pr-m"]', 'Mijamin, the name of three Israelites Miamin, Mijamin.', 'a form for 4509;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4590H}/[H5756]', 'lemma', 'heb', 'מַעַזְיָה', '["Maʻazyâh"]', '["Maaziah"]', '["n-pr-m"]', 'Maazjah, the name of two Israelites Maaziah.', 'or מַעַזְיָהוּ; probably from 5756 (in the sense of protection) and 3050; rescue of Jah;');
