INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0117}/H9028/[H142]', 'inflected', 'heb', 'אַדִּיר', '["ʼaddîyr"]', '["noble [ones]/ their"]', '["a"]', 'wide or (generally) large; figuratively, powerful excellent, famous, gallant, glorious, goodly, lordly, mighty(-ier one), noble, principal, worthy.', 'from 142;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0423}/[H422]', 'inflected', 'heb', 'אָלָה', '["ʼâlâh"]', '["by/ a curse","in/ a curse","in/ an oath"]', '["n-f"]', 'an imprecation curse, cursing, execration, oath, swearing.', 'from 422;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H7621}/[H7650]', 'inflected', 'heb', 'שְׁבוּעָה', '["shᵉbûwʻâh"]', '["and/ in/ an oath"]', '["n-f"]', 'properly, something sworn, i.e. an oath curse, oath, × sworn.', 'feminine passive participle of 7650;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1121A}/H9025/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["for/ sons/ our"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4728}/[H3947]', 'inflected', 'heb', 'מַקָּחָה', '["maqqâchâh"]', '["<the>/ wares"]', '["n-f"]', 'something received, i.e. merchandise (purchased) ware.', 'from 3947;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4376}/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["to/ sell"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7676}/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["on the/ sabbath","on the/ sabbaths"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5203}/[H5203]', 'inflected', 'heb', 'נָטַשׁ', '["nâṭash"]', '["so/ we may leave"]', '["v"]', 'properly, to pound, i.e. smite; by implication (as if beating out, and thus expanding) to disperse; also, to thrust off, down, out or upon (inclusively, reject, let alone, permit, remit, etc.) cast off, drawn, let fall, forsake, join (battle), leave (off), lie still, loose, spread (self) abroad, stretch out, suffer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4855}/[H5383]', 'inflected', 'heb', 'מַשָּׁא', '["mashshâʼ"]', '["and/ usury of"]', '["n-m"]', 'a loan; by implication, interest on a debt exaction, usury.', 'from 5383;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5930A}/[H5927]', 'inflected', 'heb', 'עֹלָה', '["ʻôlâh"]', '["and/ for/ [the] burnt offering of","and/ to/ a burnt offering"]', '["n-f"]', 'a step or (collectively, stairs, as ascending); usually a holocaust (as going up in smoke) ascent, burnt offering (sacrifice), go up to. See also 5766.', 'or עוֹלָה; feminine active participle of 5927;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4150H}/[H3259]', 'inflected', 'heb', 'מוֹעֵד', '["môwʻêd"]', '["for the/ appointed feasts"]', '["n-m"]', 'properly, an appointment, i.e. a fixed time or season; specifically, a festival; conventionally a year; by implication, an assembly (as convened for a definite purpose); technically the congregation; by extension, the place of meeting; also a signal (as appointed beforehand) appointed (sign, time), (place of, solemn) assembly, congregation, (set, solemn) feast, (appointed, due) season, solemn(-ity), synogogue, (set) time (appointed).', 'or מֹעֵד; or (feminine) מוֹעָדָה; (2 Chronicles 8:13), from 3259;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6944G}/[H6942]', 'inflected', 'heb', 'קֹדֶשׁ', '["qôdesh"]', '["and/ for the/ holy offerings"]', '["n-m"]', 'a sacred place or thing; rarely abstract, sanctity consecrated (thing), dedicated (thing), hallowed (thing), holiness, (× most) holy (× day, portion, thing), saint, sanctuary.', 'from 6942;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H1486>', 'inflected', 'heb', 'והגורלות', '["ve./ha./go.ra.Lot"]', '["and/ the/ lots"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7133B}/[H7126]', 'lemma', 'heb', 'קׇרְבָּן', '["qorbân"]', '["[the] offering of"]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0935P}/[H935]', 'inflected', 'heb', 'בּוֹא', '["bôwʼ"]', '["and/ to/ bring"]', '["v"]', 'to go or come (in a wide variety of applications) abide, apply, attain, × be, befall, besiege, bring (forth, in, into, to pass), call, carry, × certainly, (cause, let, thing for) to come (against, in, out, upon, to pass), depart, × doubtless again, eat, employ, (cause to) enter (in, into, -tering, -trance, -try), be fallen, fetch, follow, get, give, go (down, in, to war), grant, have, × indeed, (in-) vade, lead, lift (up), mention, pull in, put, resort, run (down), send, set, × (well) stricken (in age), × surely, take (in), way.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1061}/[H1069]', 'inflected', 'heb', 'בִּכּוּר', '["bikkûwr"]', '["and/ [the] first-fruits of"]', '["n-m"]', 'the first-fruits of the crop first fruit (-ripe (figuratively)), hasty fruit.', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H0929>/H9025', 'inflected', 'heb', 'ובהמתינו', '["u./ve.hem.Tei./nu"]', '["and/ cattle/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1241}/H9025/[H1239]', 'inflected', 'heb', 'בָּקָר', '["bâqâr"]', '["herds/ our"]', '["n-m"]', 'a beeve or an animal of the ox family of either gender (as used for plowing); collectively, a herd beeve, bull ( -ock), calf, cow, great (cattle), heifer, herd, kine, ox.', 'from 1239;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H6629G>/H9025', 'inflected', 'heb', 'וצאנינו', '["ve./tzo.Nei./nu"]', '["and/ flocks/ our"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6182>/H9025', 'opaque', 'heb', 'עֲרִיסָה', '["ʻărîyçâh"]', '["dough/ our"]', '["n-f"]', 'meal dough.', 'from an unused root meaning to comminute;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8641}/H9025/[H7311]', 'inflected', 'heb', 'תְּרוּמָה', '["tᵉrûwmâh"]', '["and/ contributions/ our"]', '["n-f"]', 'a present (as offered up), especially in sacrifice or as tribute gift, heave offering (shoulder), oblation, offered(-ing).', 'or תְּרֻמָה; (Deuteronomy 12:11), from 7311;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6237}/[H6238]', 'inflected', 'heb', 'עָשַׂר', '["ʻâsar"]', '["[are] the/ [ones who] collect tithes"]', '["v"]', 'to tithe, i.e. to take or give a tenth × surely, give (take) the tenth, (have, take) tithe(-ing, -s), × truly.', 'a primitive root (identical with 6238); to accumulate; but used only as denominative from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5656I}/H9025/[H5647]', 'inflected', 'heb', 'עֲבֹדָה', '["ʻăbôdâh"]', '["labor/ our"]', '["n-f"]', 'work of any kind act, bondage, bondservant, effect, labour, ministering(-try), office, service(-ile, -itude), tillage, use, work, × wrought.', 'or עֲבוֹדָה; from 5647;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H6237}/[H6238]', 'inflected', 'heb', 'עָשַׂר', '["ʻâsar"]', '["when/ collect [the] tithes"]', '["v"]', 'to tithe, i.e. to take or give a tenth × surely, give (take) the tenth, (have, take) tithe(-ing, -s), × truly.', 'a primitive root (identical with 6238); to accumulate; but used only as denominative from 6235;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1715}/[H1711]', 'inflected', 'heb', 'דָּגָן', '["dâgân"]', '["<the>/ grain","the/ grain"]', '["n-m"]', 'properly, increase, i.e. grain corn (floor), wheat.', 'from 1711;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0272}/H9023/[H270]', 'inflected', 'heb', 'אֲחֻזָּה', '["ʼăchuzzâh"]', '["on/ own property/ his"]', '["n-f"]', 'something seized, i.e. a possession (especially of land) possession.', 'feminine passive participle from 270;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6265}/[H5790]', 'lemma', 'heb', 'עֲתָיָה', '["ʻĂthâyâh"]', '["Athaiah"]', '["n-pr-m"]', 'Athajah, an Israelite Athaiah.', 'from 5790 and 3050; Jah has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5818K}/[H5797]', 'lemma', 'heb', 'עֻזִּיָּה', '["ʻUzzîyâh"]', '["Uzziah"]', '["n-pr-m"]', 'Uzzijah, the name of five Israelites Uzziah.', 'or עֻזִּיָּהוּ; from 5797 and 3050; strength of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148V}/[H2142]', 'lemma', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0568N}/[H559]', 'lemma', 'heb', 'אֲמַרְיָה', '["ʼĂmaryâh"]', '["Amariah"]', '["n-pr-m"]', 'Amarjah, the name of nine Israelites Amariah.', 'or prolonged אֲמַרְיָהוּ; from 559 and 3050; Jah has said (i.e. promised);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8203N}/[H8199]', 'lemma', 'heb', 'שְׁפַטְיָה', '["Shᵉphaṭyâh"]', '["Shephatiah"]', '["n-pr-m"]', 'Shephatjah, the name of ten Israelites Shephatiah.', 'or שְׁפַטְיָהוּ; from 8199 and 3050; Jah has judged;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4111H}/[H4110]', 'lemma', 'heb', 'מַהֲלַלְאֵל', '["Mahălalʼêl"]', '["Mahalalel"]', '["n-pr-m"]', 'Mahalalel, the name of an antediluvian patriarch and of an Israelite Mahalaleel.', 'from 4110 and 410; praise of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4641T}/[H4639]', 'inflected', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["and/ Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1263I}/[H1288]', 'lemma', 'heb', 'בָּרוּךְ', '["Bârûwk"]', '["Baruch"]', '["n-pr-m"]', 'Baruk, the name of three Israelites Baruch.', 'passive participle from 1288; blessed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3626H}/[H3605]', 'lemma', 'heb', 'כׇּל־חֹזֶה', '["Kol-Chôzeh"]', '["Col-","Hozeh"]', '["n-pr-m"]', 'Col-Chozeh, an Israelite Col-hozeh.', 'from 3605 and 2374; every seer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2382}/[H2372]', 'lemma', 'heb', 'חֲזָיָה', '["Chăzâyâh"]', '["Hazaiah"]', '["n-pr-m"]', 'Chazajah, an Israelite Hazaiah.', 'from 2372 and 3050; Jah has seen;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5718M}/[H5710]', 'lemma', 'heb', 'עֲדָיָה', '["ʻĂdâyâh"]', '["Adaiah"]', '["n-pr-m"]', 'Adajah, the name of eight Israelites Adaiah.', 'or עֲדָיָהוּ; from 5710 and 3050; Jah has adorned;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3114I}/[H3080]', 'lemma', 'heb', 'יוֹיָרִיב', '["Yôwyârîyb"]', '["Joiarib"]', '["n-pr-m"]', 'Jojarib, the name of four Israelites Joiarib.', 'a form of 3080;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2148W}/[H2142]', 'lemma', 'heb', 'זְכַרְיָה', '["Zᵉkaryâh"]', '["Zechariah"]', '["n-pr-m"]', 'Zecarjah, the name of twenty-nine Israelites Zachariah, Zechariah.', 'or זְכַרְיָהוּ; from 2142 and 3050; Jah has remembered;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8023}/[H7888]', 'inflected', 'heb', 'שִׁלֹנִי', '["Shilônîy"]', '["the/ Shilonite"]', '["n-pr-m"]', 'Shiloni, an Israelite Shiloni.', 'the same as 7888;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5543G}/[H5541]', 'lemma', 'heb', 'סַלּוּ', '["Çallûw"]', '["Sallu"]', '["n-pr-m"]', 'Sallu or Sallai, the name of two Israelites Sallai, Sallu, Salu.', 'or סַלּוּא; or סָלוּא; or סַלַּי; from 5541; weighed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4918W}/[H7999]', 'lemma', 'heb', 'מְשֻׁלָּם', '["Mᵉshullâm"]', '["Meshullam"]', '["n-pr-m"]', 'Meshullam, the name of seventeen Israelites Meshullam.', 'from 7999; allied;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3133}/[H3259]', 'lemma', 'heb', 'יוֹעֵד', '["Yôwʻêd"]', '["Joed"]', '["n-pr-m"]', 'Joed, an Israelite Joed.', 'apparently the active participle of 3259; appointer;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6305L}/[H6299]', 'lemma', 'heb', 'פְּדָיָה', '["Pᵉdâyâh"]', '["Pedaiah"]', '["n-pr-m"]', 'Pedajah, the name of six Israelites Pedaiah.', 'or פְּדָיָהוּ; from 6299 and 3050; Jah has ransomed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6964G}/[H6963]', 'lemma', 'heb', 'קוֹלָיָה', '["Qôwlâyâh"]', '["Kolaiah"]', '["n-pr-m"]', 'Kolajah, the name of two Israelites Kolaiah.', 'from 6963 and 3050; voice of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4641U}/[H4639]', 'lemma', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0384G}/[H837]', 'lemma', 'heb', 'אִיתִיאֵל', '["ʼÎythîyʼêl"]', '["Ithiel"]', '["n-pr-m"]', 'Ithiel, the name of an Israelite, also of a symbolical person Ithiel.', 'perhaps from 837 and 410; God has arrived;');
