INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0624}/[H622]', 'inflected', 'heb', 'אָסֻף', '["ʼâçuph"]', '["at/ [the] storerooms of"]', '["n-m"]', 'collected (only in the plural), i.e. a collection of offerings threshold, Asuppim.', 'passive participle of 622;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5608B}\/[H5608]', 'inflected', 'heb', 'סָפַר', '["çâphar"]', '["the/ scribe"]', '["v n-m"]', 'properly, to score with a mark as a tally or record, i.e. (by implication) to inscribe, and also to enumerate; intensively, to recount, i.e. celebrate commune, (ac-) count; declare, number, penknife, reckon, scribe, shew forth, speak, talk, tell (out), writer.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2598}/[H2596]', 'inflected', 'heb', 'חֲנֻכָּה', '["chănukkâh"]', '["and/ at/ [the] dedication of"]', '["n-f"]', 'initiation, i.e. consecration dedicating(-tion).', 'from 2596;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8057}/[H8056]', 'inflected', 'heb', 'שִׂמְחָה', '["simchâh"]', '["and/ [the] gladness of","and/ gladness","and/ gladness of","and/ joy"]', '["n-f"]', 'blithesomeness or glee, (religious or festival) × exceeding(-ly), gladness, joy(-fulness), mirth, pleasure, rejoice(-ing).', 'from 8056;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8426}/[H3034]', 'inflected', 'heb', 'תּוֹדָה', '["tôwdâh"]', '["and/ with/ thanksgivings"]', '["n-f"]', 'properly, an extension of the hand, i.e. (by implication) avowal, or (usually) adoration; specifically, a choir of worshippers confession, (sacrifice of) praise, thanks(-giving, offering).', 'from 3034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4700}/[H6750]', 'lemma', 'heb', 'מְצֵלֶת', '["mᵉtsêleth"]', '["cymbals"]', '["n-f"]', '(only dual) double tinklers, i.e. cymbals cymbals.', 'from 6750;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2691B}/[H2690]', 'lemma', 'heb', 'חָצֵר', '["châtsêr"]', '["[the] villages","[the] villages of","villages"]', '["n-m"]', 'a yard (as inclosed by a fence); also a hamlet (as similarly surrounded with walls) court, tower, village.', '(masculine and feminine); from 2690 in its original sense;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1019}/[H1004]', 'inflected', 'heb', 'בֵּית הַגִּלְגָּל', '["Bêyth hag-Gilgâl"]', '["and/ from/ Beth"]', '["n-pr-loc"]', 'Beth-hag-Gilgal, a place in Palestine Beth-gilgal.', 'from 1004 and 1537 with the article interposed; house of Gilgal (or rolling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1019}/[H1004]', 'inflected', 'heb', 'בֵּית הַגִּלְגָּל', '["Bêyth hag-Gilgâl"]', '["<of the>/ Gilgal"]', '["n-pr-loc"]', 'Beth-hag-Gilgal, a place in Palestine Beth-gilgal.', 'from 1004 and 1537 with the article interposed; house of Gilgal (or rolling);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5820K}/[H5794]', 'inflected', 'heb', 'עַזְמָוֶת', '["ʻAzmâveth"]', '["and/ Azmaveth"]', '["n-pr-m n-pr-loc"]', 'Azmaveth, the name of three Israelites and of a place in Palestine Azmaveth. See also 1041.', 'from 5794 and 4194; strong one of death;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5975H}/H9012/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["and/ I appointed/ !","and/ I assigned/ !"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8418}/[H1980]', 'inflected', 'heb', 'תַּהֲלֻכָה', '["tahălukâh"]', '["and/ processions"]', '["n-f"]', 'a procession × went.', 'from 1980;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3225H}/[H3231]', 'inflected', 'heb', 'יָמִין', '["yâmîyn"]', '["to the/ right"]', '["n-f"]', 'the right hand or side (leg, eye) of a person or other object (as the stronger and more dexterous); locally, the south left-handed, right (hand, side), south.', 'from 3231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1955G}/[H3467]', 'lemma', 'heb', 'הוֹשַׁעְיָה', '["Hôwshaʻyâh"]', '["Hoshaiah"]', '["n-pr-m"]', 'Hoshajah, the name of two Israelites Hoshaiah.', 'from 3467 and 3050; Jah has saved;');
