INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8098V}/[H8085]', 'lemma', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5832J}/[H5826]', 'inflected', 'heb', 'עֲזַרְאֵל', '["ʻĂzarʼêl"]', '["and/ Azarel"]', '["n-pr-m"]', 'Azarel, the name of five Israelites Azarael, Azareel.', 'from 5826 and 410; God has helped;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4450}/[H4448]', 'lemma', 'heb', 'מִלֲלַי', '["Milălay"]', '["Milalai"]', '["n-pr-m"]', 'Milalai, an Israelite Milalai.', 'from 4448; talkative;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1562}/[H1561]', 'lemma', 'heb', 'גִּלֲלַי', '["Gilălay"]', '["Gilalai"]', '["n-pr-m"]', 'Gilalai, an Israelite Gilalai.', 'from 1561; dungy;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4597}/[H4578]', 'lemma', 'heb', 'מָעַי', '["Mâʻay"]', '["Maai"]', '["n-pr-m"]', 'Maai, an Israelite Maai.', 'probably from 4578; sympathetic;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5417P}/[H5414]', 'lemma', 'heb', 'נְתַנְאֵל', '["Nᵉthanʼêl"]', '["Nethanel"]', '["n-pr-m"]', 'Nethanel, the name of ten Israelites Nethaneel.', 'from 5414 and 410; given of God;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3063K}/[H3034]', 'inflected', 'heb', 'יְהוּדָה', '["Yᵉhûwdâh"]', '["and/ Judah"]', '["n-pr-m"]', 'Jehudah (or Judah), the name of five Israelites; also of the tribe descended from the first, and of its territory Judah.', 'from 3034; celebrated;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2607K}/[H2603]', 'lemma', 'heb', 'חֲנָנִי', '["Chănânîy"]', '["Hanani"]', '["n-pr-m"]', 'Chanani, the name of six Israelites Hanani.', 'from 2603; gracious;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5048}/H9038/[H5046]', 'inflected', 'heb', 'נֶגֶד', '["neged"]', '["and/ before/ themselves"]', '["prep"]', 'a front, i.e. part opposite; specifically a counterpart, or mate; usually (adverbial, especially with preposition) over against or before about, (over) against, × aloof, × far (off), × from, over, presence, × other side, sight, × to view.', 'from 5046;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8426}/[H3034]', 'inflected', 'heb', 'תּוֹדָה', '["tôwdâh"]', '["and/ the/ thanksgiving choir"]', '["n-f"]', 'properly, an extension of the hand, i.e. (by implication) avowal, or (usually) adoration; specifically, a choir of worshippers confession, (sacrifice of) praise, thanks(-giving, offering).', 'from 3034;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4136}/[H4135]', 'inflected', 'heb', 'מוּל', '["mûwl"]', '["to/ [the] front"]', '["n-m"]', 'properly, abrupt, i.e. a precipice; by implication, the front; used only adverbially (with prepositional prefix) opposite (over) against, before, (fore-) front, from, (God-) ward, toward, with.', 'or מוֹל; (Deuteronomy 1:1), or מוֹאל; (Nehemiah 12:38), or מֻל; (Numbers 22:5), from 4135;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9009/<H2346H>', 'inflected', 'heb', 'להחומה', '["le./ha./cho.Mah"]', '["to/ the/ wall"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4026M}/[H1431]', 'inflected', 'heb', 'מִגְדָּל', '["migdâl"]', '["to/ [the] tower of"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8574G}/[H5216]', 'inflected', 'heb', 'תַּנּוּר', '["tannûwr"]', '["the/ ovens"]', '["n-m"]', 'a fire-pot furnace, oven.', 'from 5216;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7342G}/[H7337]', 'inflected', 'heb', 'רָחָב', '["râchâb"]', '["<the>/ broad"]', '["a"]', 'roomy, in any (or every) direction, literally or figuratively broad, large, at liberty, proud, wide.', 'from 7337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3466H}/[H3465]', 'inflected', 'heb', 'יְשָׁנָה', '["Yᵉshânâh"]', '["<the>/ Jeshanah"]', '["n-pr-f"]', 'Jeshanah, a place in Palestine Jeshanah.', 'feminine of 3465;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4026G}/[H1431]', 'inflected', 'heb', 'מִגְדָּל', '["migdâl"]', '["and/ [the] tower of"]', '["n-m"]', 'a tower (from its size or height); by analogy, a rostrum; figuratively, a (pyramidal) bed of flowers castle, flower, tower. Compare the names following.', 'also (in plural) feminine מִגְדָּלָה; from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2606}/[H2603]', 'lemma', 'heb', 'חֲנַנְאֵל', '["Chănanʼêl"]', '["Hananel"]', '["n-pr-m"]', 'Chananel, probably an Israelite, from whom a tower of Jerusalem was named Hananeel.', 'from 2603 and 410; God has favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4307G}/[H5201]', 'inflected', 'heb', 'מַטָּרָא', '["maṭṭârâʼ"]', '["the/ guard"]', '["n-f"]', 'a jail (as a guard-house); also an aim (as being closely watched) mark, prison.', 'or מַטָּרָה; from 5201;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0471H}/[H410]', 'lemma', 'heb', 'אֶלְיָקִים', '["ʼElyâqîym"]', '["Eliakim"]', '["n-pr-m"]', 'Eljakim, the name of four Israelites Eliakim.', 'from 410 and 6965; God of raising;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4641V}/[H4639]', 'lemma', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4509H}/[H4480]', 'lemma', 'heb', 'מִנְיָמִין', '["Minyâmîyn"]', '["Miniamin"]', '["n-pr-m"]', 'Minjamin, the name of two Israelites Miniamin. Compare 4326.', 'from 4480 and 3225; from (the) right hand;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4320H}/[H4310]', 'lemma', 'heb', 'מִיכָיָה', '["Mîykâyâh"]', '["Micaiah"]', '["n-pr-m"]', 'Micajah, the name of two Israelites Micah, Michaiah. Compare 4318.', 'from 4310 and (the prefix derivative from) 3588 and 3050; who (is) like Jah?;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0454L}/[H413]', 'lemma', 'heb', 'אֶלְיְהוֹעֵינַי', '["ʼElyᵉhôwʻêynay"]', '["Elioenai"]', '["n-pr-m"]', 'Eljehoenai or Eljoenai, the name of seven Israelites Elihoenai, Elionai.', 'or (shortened) אֶלְיוֹעֵינַי; from 413 and 3068 and 5869; towards Jehovah (are) my eyes;');
