INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4641W}/[H4639]', 'inflected', 'heb', 'מַעֲשֵׂיָה', '["Maʻăsêyâh"]', '["and/ Maaseiah"]', '["n-pr-m"]', 'Maasejah, the name of sixteen Israelites Maaseiah.', 'or מַעֲשֵׂיָהוּ; from 4639 and 3050; work of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8098W}/[H8085]', 'inflected', 'heb', 'שְׁמַעְיָה', '["Shᵉmaʻyâh"]', '["and/ Shemaiah"]', '["n-pr-m"]', 'Shemajah, the name of twenty-five Israelites Shemaiah.', 'or שְׁמַעְיָהוּ; from 8085 and 3050; Jah has heard;');
