INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3076Q}/[H3068]', 'inflected', 'heb', 'יְהוֹחָנָן', '["Yᵉhôwchânân"]', '["and/ Jehohanan"]', '["n-pr-m"]', 'Jehochanan, the name of eight Israelites Jehohanan, Johanan. Compare 3110.', 'from 3068 and 2603; Jehovah-favored;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4441R}/[H4428]', 'inflected', 'heb', 'מַלְכִּיָּה', '["Malkîyâh"]', '["and/ Malkijah"]', '["n-pr-m"]', 'Malkijah, the name of ten Israelites Malchiah, Malchijah.', 'or מַלְכִּיָּהוּlemma מַלְכִּיָהוּ missing dagesh, corrected to מַלְכִּיָּהוּ; (Jeremiah 38:6), from 4428 and 3050; king of (i.e. appointed by) Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5867J}/[H5956]', 'inflected', 'heb', 'עֵילָם', '["ʻÊylâm"]', '["and/ Elam"]', '["n-pr-m n-pr-loc"]', 'Elam, a son of Shem and his descendants, with their country; also of six Israelites Elam.', 'or עוֹלָם; (Ezra 10:2; Jeremiah 49:36), probably from 5956; hidden, i.e. distant;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5829J}/[H5828]', 'inflected', 'heb', 'עֵזֶר', '["ʻÊzer"]', '["and/ Ezer"]', '["n-pr-m"]', 'Ezer, the name of four Israelites Ezer. Compare 5827.', 'the same as 5828;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H3156H}/[H2224]', 'inflected', 'heb', 'יִזְרַחְיָה', '["Yizrachyâh"]', '["and/ Izrahiah"]', '["n-pr-m"]', 'Jizrachjah, the name of two Israelites Izrahiah, Jezrahiah.', 'from 2224 and 3050; Jah will shine;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6496}/[H6485]', 'inflected', 'heb', 'פָּקִיד', '["pâqîyd"]', '["[was] the/ overseer"]', '["n-m"]', 'a superintendent (civil, military or religious) which had the charge, governor, office, overseer, (that) was set.', 'from 6485;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3206}/[H3205]', 'inflected', 'heb', 'יֶלֶד', '["yeled"]', '["and/ the/ children","and/ the/ youths"]', '["n-m"]', 'something born, i.e. a lad or offspring boy, child, fruit, son, young man (one).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H5393}/[H3957]', 'inflected', 'heb', 'נִשְׁכָּה', '["nishkâh"]', '["the/ rooms"]', '["n-f"]', 'a cell chamber.', 'for 3957;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7225G}/[H7218]', 'inflected', 'heb', 'רֵאשִׁית', '["rêʼshîyth"]', '["for the/ first [fruit]"]', '["n-f"]', 'the first, in place, time, order or rank (specifically, a firstfruit) beginning, chief(-est), first(-fruits, part, time), principal thing.', 'from the same as 7218;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H4643}/[H6240]', 'inflected', 'heb', 'מַעֲשֵׂר', '["maʻăsêr"]', '["and/ for the/ tithes"]', '["n-m"]', 'a tenth; especially a tithe tenth (part), tithe(-ing).', 'or מַעֲשַׂר; and (in plural) feminine מַעַשְׂרָה; from 6240;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7704G>', 'inflected', 'heb', 'לשדי', '["le./sa.Deh","li/s.Dei"]', '["to/ [the] fields of","to/ a field"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H2893}/[H2892]', 'inflected', 'heb', 'טׇהֳרָה', '["ṭohŏrâh"]', '["<the>/ purification"]', '["n-f"]', 'ceremonial purification; moral purity × is cleansed, cleansing, purification(-fying).', 'feminine of 2892;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H6924H}/[H6923]', 'inflected', 'heb', 'קֶדֶם', '["qedem"]', '["[are] from/ antiquity","from/ [the] beginnings of","from/ antiquity"]', '["n-m adv"]', 'the front, of place (absolutely, the fore part, relatively the East) or time (antiquity); often used adverbially (before, anciently, eastward) aforetime, ancient (time), before, east (end, part, side, -ward), eternal, × ever(-lasting), forward, old, past. Compare 6926.', 'or קֵדְמָה; from 6923;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7892A}/[H7891]', 'inflected', 'heb', 'שִׁיר', '["shîyr"]', '["and/ [the] song of"]', '["n-m n-f"]', 'a song; abstractly, singing musical(-ick), × sing(-er, -ing), song.', 'or feminine שִׁירָה; from 7891;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6942H}/[H6942]', 'inflected', 'heb', 'קָדַשׁ', '["qâdash"]', '["and/ [were] setting apart"]', '["v"]', 'to be (causatively, make, pronounce or observe as) clean (ceremonially or morally) appoint, bid, consecrate, dedicate, defile, hallow, (be, keep) holy(-er, place), keep, prepare, proclaim, purify, sanctify(-ied one, self), × wholly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7043}/H9033/[H7043]', 'inflected', 'heb', 'קָלַל', '["qâlal"]', '["to/ curse/ it"]', '["v"]', 'to be (causatively, make) light, literally (swift, small, sharp, etc.) or figuratively (easy, trifling, vile, etc.) abate, make bright, bring into contempt, (ac-) curse, despise, (be) ease(-y, -ier), (be a, make, make somewhat, move, seem a, set) light(-en, -er, -ly, -ly afflict, -ly esteem, thing), × slight(-ly), be swift(-er), (be, be more, make, re-) vile, whet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0475O}/[H410]', 'lemma', 'heb', 'אֶלְיָשִׁיב', '["ʼElyâshîyb"]', '["Eliashib"]', '["n-pr-m"]', 'Eljashib, the name of six Israelites Eliashib.', 'from 410 and 7725; God will restore;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7093}/[H7112]', 'inflected', 'heb', 'קֵץ', '["qêts"]', '["and/ to/ [the] end of"]', '["n-m"]', 'an extremity; adverbially (with prepositional prefix) after after, (utmost) border, end, (in-) finite, × process.', 'contracted from 7112;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5393}/[H3957]', 'lemma', 'heb', 'נִשְׁכָּה', '["nishkâh"]', '["a room"]', '["n-f"]', 'a cell chamber.', 'for 3957;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7993}/H9012/[H7993]', 'inflected', 'heb', 'שָׁלַךְ', '["shâlak"]', '["and/ I threw/ !"]', '["v"]', 'to throw out, down or away (literally or figuratively) adventure, cast (away, down, forth, off, out), hurl, pluck, throw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H7725G}/H9012/[H7725]', 'inflected', 'heb', 'שׁוּב', '["shûwb"]', '["and/ I brought back/ !","and/ I have turned back/ !"]', '["v"]', 'to turn back (hence, away) transitively or intransitively, literally or figuratively (not necessarily with the idea of return to the starting point); generally to retreat; often adverbial, again ((break, build, circumcise, dig, do anything, do evil, feed, lay down, lie down, lodge, make, rejoice, send, take, weep)) × again, (cause to) answer ( again), × in any case (wise), × at all, averse, bring (again, back, home again), call (to mind), carry again (back), cease, × certainly, come again (back), × consider, continually, convert, deliver (again), deny, draw back, fetch home again, × fro, get (oneself) (back) again, × give (again), go again (back, home), (go) out, hinder, let, (see) more, × needs, be past, × pay, pervert, pull in again, put (again, up again), recall, recompense, recover, refresh, relieve, render (again), requite, rescue, restore, retrieve, (cause to, make to) return, reverse, reward, say nay, send back, set again, slide back, still, × surely, take back (off), (cause to, make to) turn (again, self again, away, back, back again, backward, from, off), withdraw.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H3828}\/[H3836]', 'inflected', 'heb', 'לְבוֹנָה', '["lᵉbôwnâh"]', '["and/ the/ frankincense"]', '["n-f"]', 'frankincense (from its whiteness or perhaps that of its smoke) (frank-) incense.', 'or לְבֹנָה; from 3836;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3045}/H9012/[H3045]', 'inflected', 'heb', 'יָדַע', '["yâdaʻ"]', '["and/ I knew/ !","and/ I perceived/ !"]', '["v"]', 'to know (properly, to ascertain by seeing); used in a great variety of senses, figuratively, literally, euphemistically and inferentially (including observation, care, recognition; and causatively, instruction, designation, punishment, etc.) acknowledge, acquaintance(-ted with), advise, answer, appoint, assuredly, be aware, (un-) awares, can(-not), certainly, comprehend, consider, × could they, cunning, declare, be diligent, (can, cause to) discern, discover, endued with, familiar friend, famous, feel, can have, be (ig-) norant, instruct, kinsfolk, kinsman, (cause to let, make) know, (come to give, have, take) knowledge, have (knowledge), (be, make, make to be, make self) known, be learned, lie by man, mark, perceive, privy to, × prognosticator, regard, have respect, skilful, shew, can (man of) skill, be sure, of a surety, teach, (can) tell, understand, have (understanding), × will be, wist, wit, wot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H7704G>/H9023', 'inflected', 'heb', 'לשדהו', '["le./sa.De./hu"]', '["to/ own field/ his"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8492}/[H3423]', 'inflected', 'heb', 'תִּירוֹשׁ', '["tîyrôwsh"]', '["and/ the/ new wine"]', '["n-m"]', 'must or fresh grape-juice (as just squeezed out); by implication (rarely) fermented wine (new, sweet) wine.', 'or תִּירֹשׁ; from 3423 in the sense of expulsion;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H0686}/H9012/[H686]', 'inflected', 'heb', 'אָצַר', '["ʼâtsar"]', '["and/ I appointed as treasurers/ !"]', '["v"]', 'to store up (lay up in) store, (make) treasure(-r).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8018J}/[H8002]', 'lemma', 'heb', 'שֶׁלֶמְיָה', '["Shelemyâh"]', '["Shelemiah"]', '["n-pr-m"]', 'Shelemjah, the name of nine Israelites Shelemiah.', 'or שֶׁלֶמְיָהוּ; from 8002 and 3050; thank-offering of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6659M}/[H6663]', 'inflected', 'heb', 'צָדוֹק', '["Tsâdôwq"]', '["and/ Zadok"]', '["n-pr-m"]', 'Tsadok, the name of eight or nine Israelites Zadok.', 'from 6663; just;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6305M}/[H6299]', 'inflected', 'heb', 'פְּדָיָה', '["Pᵉdâyâh"]', '["and/ Pedaiah"]', '["n-pr-m"]', 'Pedajah, the name of six Israelites Pedaiah.', 'or פְּדָיָהוּ; from 6299 and 3050; Jah has ransomed;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3027K}/H9028/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["hand/ their","hands/ their"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2605N}/[H2603]', 'lemma', 'heb', 'חָנָן', '["Chânân"]', '["Hanan"]', '["n-pr-m"]', 'Chanan, the name of seven Israelites Canan.', 'from 2603; favor;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2139N}/[H2142]', 'lemma', 'heb', 'זַכּוּר', '["Zakkûwr"]', '["Zaccur"]', '["n-pr-m"]', 'Zakkur, the name of seven Israelites Zaccur, Zacchur.', 'from 2142; mindful;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4983P}/[H4976]', 'lemma', 'heb', 'מַתַּנְיָה', '["Mattanyâh"]', '["Mattaniah"]', '["n-pr-m"]', 'Mattanjah, the name of ten Israelites Mattaniah.', 'or מַתַּנְיָהוּ; from 4976 and 3050; gift of Jah;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2505A}/[H2505]', 'inflected', 'heb', 'חָלַק', '["châlaq"]', '["to/ distribute","to/ receive a portion"]', '["v"]', 'to be smooth (figuratively); by implication (as smooth stones were used for lots) to apportion or separate deal, distribute, divide, flatter, give, (have, im-) part(-ner), take away a portion, receive, separate self, (be) smooth(-er).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0251H}/H9028\/[H251]', 'inflected', 'heb', 'אָח', '["ʼâch"]', '["to/ brothers/ their"]', '["n-m"]', 'a brother (used in the widest sense of literal relationship and metaphorical affinity or resemblance [like 1]) another, brother(-ly); kindred, like, other. Compare also the proper names beginning with ''Ah-'' or ''Ahi-''.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2617A}/H9020/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["covenant loyalty/ my","loyalti<es>/ my"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4929}/H9023/[H8104]', 'inflected', 'heb', 'מִשְׁמָר', '["mishmâr"]', '["and/ in/ services/ its"]', '["n-m"]', 'a guard (the man, the post or the prison); a deposit (figuratively); also (as observed) a usage (abstractly), or an example (concretely) diligence, guard, office, prison, ward, watch.', 'from 8104;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1660}/[H5059]', 'lemma', 'heb', 'גַּת', '["gath"]', '["a winepress","winepresses"]', '["n-f"]', 'a wine-press (or vat for holding the grapes in pressing them) (wine-) press (fat).', 'probably from 5059 (in the sense of treading out grapes);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6006}/[H6006]', 'inflected', 'heb', 'עָמַס', '["ʻâmaç"]', '["and/ [some who] loaded [them]"]', '["v"]', 'to load, i.e. impose a burden (or figuratively, infliction) be borne, (heavy) burden (self), lade, load, put.', 'or עָמַשׂ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4376}/H9048/[H4376]', 'inflected', 'heb', 'מָכַר', '["mâkar"]', '["sold/ they"]', '["v"]', 'to sell, literally (as merchandise, a daughter in marriage, into slavery), or figuratively (to surrender) × at all, sell (away, -er, self).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6718B}/[H6679]', 'lemma', 'heb', 'צַיִד', '["tsayid"]', '["food"]', '["n-m"]', 'the chase; also game (thus taken) × catcheth, food, × hunter, (that which he took in) hunting, venison, victuals.', 'from a form of 6679 and meaning the same;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4377}/[H4376]', 'lemma', 'heb', 'מֶכֶר', '["meker"]', '["merchandise"]', '["n-m"]', 'merchandise; also value pay, price, ware.', 'from 4376;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2490H}/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["and/ [are] profaning","so/ I may profane"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2490H}/[H2470]', 'inflected', 'heb', 'חָלַל', '["châlal"]', '["by/ profaning","to/ profane"]', '["v"]', 'properly, to bore, i.e. (by implication) to wound, to dissolve; figuratively, to profane (a person, place or thing), to break (one''s word), to begin (as if by an ''opening wedge''); to play (the flute) begin (× men began), defile, × break, defile, × eat (as common things), × first, × gather the grape thereof, × take inheritance, pipe, player on instruments, pollute, (cast as) profane (self), prostitute, slay (slain), sorrow, stain, wound.', 'a primitive root (compare 2470); also denominative (from 2485)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6751}/[H6754]', 'lemma', 'heb', 'צָלַל', '["tsâlal"]', '["giving shade","they became dark"]', '["v"]', 'to shade, as twilight or an opaque object begin to be dark, shadowing.', 'a primitive root (identical with through the idea of hovering over (compare 6754));');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6605A}/H9038/[H6605]', 'inflected', 'heb', 'פָּתַח', '["pâthach"]', '["people will open/ them"]', '["v"]', 'to open wide (literally or figuratively); specifically, to loosen, begin, plough, carve appear, break forth, draw (out), let go free, (en-) grave(-n), loose (self), (be, be set) open(-ing), put off, ungird, unstop, have vent.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H5288}/H9020/[H5287]', 'inflected', 'heb', 'נַעַר', '["naʻar"]', '["and/ some of/ servants/ my"]', '["n-m"]', '(concretely) a boy (as active), from the age of infancy to adolescence; by implication, a servant; also (by interch. of sex), a girl (of similar latitude in age) babe, boy, child, damsel (from the margin), lad, servant, young (man).', 'from 5287;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5749B}/H9012/[H5749]', 'inflected', 'heb', 'עוּד', '["ʻûwd"]', '["and/ I warned/ !"]', '["v"]', 'to duplicate or repeat; by implication, to protest, testify (as by reiteration); intensively, to encompass, restore (as a sort of reduplication) admonish, charge, earnestly, lift up, protest, call (take) to record, relieve, rob, solemnly, stand upright, testify, give warning, (bear, call to, give, take to) witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H7676}\/[H7673]', 'inflected', 'heb', 'שַׁבָּת', '["shabbâth"]', '["on the/ sabbath"]', '["n"]', 'intermission, i.e (specifically) the Sabbath ( every) sabbath.', 'intensive from 7673;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2347}/H9012/[H2347]', 'inflected', 'heb', 'חוּס', '["chûwç"]', '["and/ have mercy/ !"]', '["v"]', 'properly, to cover, i.e. (figuratively) to compassionate pity, regard, spare.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7230}/[H7231]', 'inflected', 'heb', 'רֹב', '["rôb"]', '["according to/ [the] greatness of","when/ [it] became numerous"]', '["n-m"]', 'abundance (in any respect) abundance(-antly), all, × common (sort), excellent, great(-ly, -ness, number), huge, be increased, long, many, more in number, most, much, multitude, plenty(-ifully), × very (age).', 'from 7231;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2617A}/H9021\/[H2616]', 'inflected', 'heb', 'חֶסֶד', '["cheçed"]', '["covenant loyalty/ your"]', '["n-m"]', 'kindness; by implication (towards God) piety; rarely (by opposition) reproof, or (subject.) beauty favour, good deed(-liness, -ness), kindly, (loving-) kindness, merciful (kindness), mercy, pity, reproach, wicked thing.', 'from 2616;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0797}/[H796]', 'lemma', 'heb', 'אַשְׁדּוֹדִית', '["ʼAshdôwdîyth"]', '["Ashdodite"]', '["adv"]', '(only adverb) in the language of Ashdod in the speech of Ashdod.', 'feminine of 796;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/{H3956H}/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["and/ according to/ [the] language of"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4803}/H9038/[H4803]', 'inflected', 'heb', 'מָרַט', '["mâraṭ"]', '["and/ I pulled out beard/ their"]', '["v"]', 'to polish; by implication, to make bald (the head), to gall (the shoulder); also, to sharpen bright, furbish, (have his) hair (be) fallen off, peeled, pluck off (hair).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H1121A}/[H1129]', 'inflected', 'heb', 'בֵּן', '["bên"]', '["and/ from/ a child of","and/ one of/ [the] sons of"]', '["n-m"]', 'a son (as a builder of the family name), in the widest sense (of literal and figurative relationship, including grandson, subject, nation, quality or condition, etc., (like father or brother), etc.) afflicted, age, (Ahoh-) (Ammon-) (Hachmon-) (Lev-) ite, (anoint-) ed one, appointed to, ( ) arrow, (Assyr-) (Babylon-) (Egypt-) (Grec-) ian, one born, bough, branch, breed, (young) bullock, (young) calf, × came up in, child, colt, × common, × corn, daughter, × of first, firstborn, foal, very fruitful, postage, × in, kid, lamb, ( ) man, meet, mighty, nephew, old, ( ) people, rebel, robber, × servant born, × soldier, son, spark, steward, stranger, × surely, them of, tumultuous one, valiant(-est), whelp, worthy, young (one), youth.', 'from 1129;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H1272}/H9033/[H1272]', 'inflected', 'heb', 'בָּרַח', '["bârach"]', '["and/ I drove away/ him"]', '["v"]', 'to bolt, i.e. figuratively, to flee suddenly chase (away); drive away, fain, flee (away), put to flight, make haste, reach, run away, shoot.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1352}/[H1351]', 'lemma', 'heb', 'גֹּאֶל', '["gôʼel"]', '["[the] defilement<s> of"]', '["n-m"]', 'profanation defile.', 'from 1351;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1285}/[H1262]', 'inflected', 'heb', 'בְּרִית', '["bᵉrîyth"]', '["and/ [the] covenant of","and/ a covenant","and/ a covenant of"]', '["n-f"]', 'a compact (because made by passing between pieces of flesh) confederacy, (con-) feder(-ate), covenant, league.', 'from 1262 (in the sense of cutting [like 1254]);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2891}/H9038/[H2891]', 'inflected', 'heb', 'טָהֵר', '["ṭâhêr"]', '["and/ I purified/ them","and/ I will cleanse/ them","and/ it has cleansed/ them"]', '["v"]', 'to be pure (physical sound, clear, unadulterated; Levitically, uncontaminated; morally, innocent or holy) be (make, make self, pronounce) clean, cleanse (self), purge, purify(-ier, self).', 'a primitive root; properly, to be bright; i.e. (by implication)');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H7133B}/[H7126]', 'inflected', 'heb', 'קׇרְבָּן', '["qorbân"]', '["and/ for/ [the] offering of"]', '["n-m"]', 'something brought near the altar, i.e. a sacrificial present oblation, that is offered, offering.', 'or קֻרְבָּן; from 7126;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H1061}/[H1069]', 'inflected', 'heb', 'בִּכּוּר', '["bikkûwr"]', '["and/ for the/ first-fruits"]', '["n-m"]', 'the first-fruits of the crop first fruit (-ripe (figuratively)), hasty fruit.', 'from 1069;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4427A}/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["who/ is reigning","who/ made king","who/ reigned"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H1912>', 'inflected', 'heb', 'מהדו', '["me./Ho.du"]', '["[were] from/ India","from/ India"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4082}/[H1777]', 'lemma', 'heb', 'מְדִינָה', '["mᵉdîynâh"]', '["[the] province","[the] provinces of","province","province[s]"]', '["n-f"]', 'properly, a judgeship, i.e. jurisdiction; by implication, a district (as ruled by a judge); generally, a region (× every) province.', 'from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3427}/[H3427]', 'inflected', 'heb', 'יָשַׁב', '["yâshab"]', '["when/ sat"]', '["v"]', 'properly, to sit down (specifically as judge. in ambush, in quiet); by implication, to dwell, to remain; causatively, to settle, to marry (make to) abide(-ing), continue, (cause to, make to) dwell(-ing), ease self, endure, establish, × fail, habitation, haunt, (make to) inhabit(-ant), make to keep (house), lurking, × marry(-ing), (bring again to) place, remain, return, seat, set(-tle), (down-) sit(-down, still, -ting down, -ting (place) -uate), take, tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4074H}/[H4074]', 'inflected', 'heb', 'מָדַי', '["Mâday"]', '["and/ Media"]', '["n-pr-m n-pr-loc"]', 'Madai, a country of central Asia Madai, Medes, Media.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6579}/[H6579]', 'inflected', 'heb', 'פַּרְתַּם', '["partam"]', '["the/ nobles"]', '["n-m"]', 'a grandee (most) noble, prince.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3366}/[H3365]', 'lemma', 'heb', 'יְקָר', '["yᵉqâr"]', '["[the] honor of","honor","precious thing","preciousness"]', '["n-m"]', 'value, i.e. (concretely) wealth; abstractly, costliness, dignity honour, precious (things), price.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8597}/[H6286]', 'lemma', 'heb', 'תִּפְאָרָה', '["tiphʼârâh"]', '["[are] [the] splendor of","[the] glory of","[the] splendor of","beauty","glory","splendor"]', '["n-f"]', 'ornament (abstractly or concretely, literally or figuratively) beauty(-iful), bravery, comely, fair, glory(-ious), honour, majesty.', 'or תִּפְאֶרֶת; from 6286;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1420}/H9023/[H1419]', 'inflected', 'heb', 'גְּדוּלָה', '["gᵉdûwlâh"]', '["greatness/ his"]', '["n-f"]', 'greatness; (concretely) mighty acts dignity, great things(-ness), majesty.', 'or גְּדֻלָּה; (shortened) or (less accurately) גְּדוּלָּה; feminine of 1419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/H9006/{H1419A}/[H1431]', 'inflected', 'heb', 'גָּדוֹל', '["gâdôwl"]', '["<to>/ from/ great"]', '["a n-pr-m"]', 'great (in any sense); hence, older; also insolent aloud, elder(-est), exceeding(-ly), far, (man of) great (man, matter, thing,-er,-ness), high, long, loud, mighty, more, much, noble, proud thing, × sore, (×) very.', 'or גָּדֹל; (shortened) from 1431;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1594}/[H1593]', 'lemma', 'heb', 'גִּנָּה', '["ginnâh"]', '["[the] garden of","a garden of"]', '["n-f"]', 'garden.', 'another form for 1593');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1055}/[H1004]', 'lemma', 'heb', 'בִּיתָן', '["bîythân"]', '["[the] palace of"]', '["n-m"]', 'a palace (i.e. large house) palace.', 'probably from 1004;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2353}/[H2357]', 'lemma', 'heb', 'חוּר', '["chûwr"]', '["white material"]', '["n-m"]', 'white linen white.', 'from 2357;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H3768>', 'opaque', 'heb', 'כַּרְפַּס', '["karpaç"]', '["cotton"]', '["n-m"]', 'byssus or fine vegetable wool green.', 'of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1550B}/[H1556]', 'lemma', 'heb', 'גָּלִיל', '["gâlîyl"]', '["[are] rods of","rods of"]', '["a"]', 'a valve of a folding door (as turning); also a ring (as round) folding, ring.', 'from 1556;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8336A}/[H4897]', 'lemma', 'heb', 'שֵׁשׁ', '["shêsh"]', '["marble"]', '["n-m"]', 'bleached stuff, i.e. white linen or (by analogy) marble × blue, fine (twined) linen, marble, silk.', 'or (for alliteration with 4897) שְׁשִׁי; for 7893;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7531A}/[H7529]', 'lemma', 'heb', 'רִצְפָּה', '["ritspâh"]', '["[the] pavement","a pavement of"]', '["n-f"]', 'a hot stone; also a tessellated pavement live coal, pavement.', 'feminine of 7529;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H0923>', 'opaque', 'heb', 'בַּהַט', '["bahaṭ"]', '["porphyry"]', '["n-m"]', 'white marble or perhaps alabaster red (marble).', 'from an unused root (probably meaning to glisten);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8336A}/[H4897]', 'inflected', 'heb', 'שֵׁשׁ', '["shêsh"]', '["and/ marble"]', '["n-m"]', 'bleached stuff, i.e. white linen or (by analogy) marble × blue, fine (twined) linen, marble, silk.', 'or (for alliteration with 4897) שְׁשִׁי; for 7893;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1858}/[H1865]', 'inflected', 'heb', 'דַּר', '["dar"]', '["and/ mother-of-pearl"]', '["n-m"]', 'properly, a pearl (from its sheen as rapidly turned); by analogy, pearl-stone, i.e. mother-of-pearl or alabaster × white.', 'apparently from the same as 1865;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5508}/[H5507]', 'inflected', 'heb', 'סֹחֵרֶת', '["çôchêreth"]', '["and/ paving stone"]', '["n-f"]', 'probably a (black) tile (or tessara) for laying borders with black marble.', 'similar to 5507;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8248H}/[H8248]', 'inflected', 'heb', 'שָׁקָה', '["shâqâh"]', '["and/ they gave to drink"]', '["v"]', 'to quaff, i.e. (causatively) to irrigate or furnish a potion to cause to (give, give to, let, make to) drink, drown, moisten, water. See 7937, 8354.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H3627}/[H3615]', 'inflected', 'heb', 'כְּלִי', '["kᵉlîy"]', '["from/ [the] vessels of","from/ vessel","from/ vessels","more than/ weapons of"]', '["n-m"]', 'something prepared, i.e. any apparatus (as an implement, utensil, dress, vessel or weapon) armour(-bearer), artillery, bag, carriage, furnish, furniture, instrument, jewel, that is made of, × one from another, that which pertaineth, pot, psaltery, sack, stuff, thing, tool, vessel, ware, weapon, whatsoever.', 'from 3615;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8138A}/[H8138]', 'lemma', 'heb', 'שָׁנָה', '["shânâh"]', '["I change","I will change","[are] differing","[those who] change","[were] differing","[you are] changing"]', '["v"]', 'to fold, i.e. duplicate (literally or figuratively); by implication, to transmute (transitive or intransitive) do (speak, strike) again, alter, double, (be given to) change, disguise, (be) diverse, pervert, prefer, repeat, return, do the second time.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3027K}/[H3027]', 'inflected', 'heb', 'יָד', '["yâd"]', '["according to/ [the] hand of"]', '["n-f"]', 'a hand (the open one [indicating power, means, direction, etc.], in distinction from 3709, the closed one); used (as noun, adverb, etc.) in a great variety of applications, both literally and figuratively, both proximate and remote [as follows] ( be) able, × about, armholes, at, axletree, because of, beside, border, × bounty, broad, (broken-) handed, × by, charge, coast, consecrate, creditor, custody, debt, dominion, × enough, fellowship, force, × from, hand(-staves, -y work), × he, himself, × in, labour, large, ledge, (left-) handed, means, × mine, ministry, near, × of, × order, ordinance, × our, parts, pain, power, × presumptuously, service, side, sore, state, stay, draw with strength, stroke, swear, terror, × thee, × by them, × themselves, × thine own, × thou, through, × throwing, thumb, times, × to, × under, × us, × wait on, (way-) side, where, wide, × with (him, me, you), work, yield, × yourselves.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H8360}/[H8358]', 'inflected', 'heb', 'שְׁתִיָּה', '["shᵉthîyâh"]', '["and/ the/ drinking"]', '["n-f"]', 'potation drinking.', 'feminine of 8358;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H1881}/[H1881]', 'inflected', 'heb', 'דָּת', '["dâth"]', '["[is] according to the/ law","[was] according to the/ law","according to/ [the] law","according to/ [the] law of","according to/ [the] regulation of"]', '["n-f"]', 'a royal edict or statute commandment, commission, decree, law, manner.', 'of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0597}/[H597]', 'lemma', 'heb', 'אָנַס', '["ʼânaç"]', '["[was one who] compelled"]', '["v"]', 'to insist compel.', NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7522}/[H7521]', 'inflected', 'heb', 'רָצוֹן', '["râtsôwn"]', '["according to/ [the] pleasure of"]', '["n-m"]', 'delight (especially as shown) (be) acceptable(-ance, -ed), delight, desire, favour, (good) pleasure, (own, self, voluntary) will, as...(what) would.', 'or רָצֹן; from 7521;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2060}/[H2060]', 'lemma', 'heb', 'וַשְׁתִּי', '["Vashtîy"]', '["Vashti"]', '["n-pr-f"]', 'Vashti, the queen of Xerxes Vashti. z', 'of Persian origin;');
