INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4438}/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["<the>/ royalty","the/ kingdom"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0325}\/[H325]', 'inflected', 'heb', 'אֲחַשְׁוֵרוֹשׁ', '["ʼĂchashvêrôwsh"]', '["Ahasuerus"]', '["n-pr-m"]', 'Achashverosh (i.e. Ahasuerus or Artaxerxes, but in this case Xerxes), the title (rather than name) of a Persian king Ahasuerus.', 'or (shortened) אַחַשְׁרֹשׁ (Esther 10:1); of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4104}/[H4104]', 'inflected', 'heb', 'מְהוּמָן', '["Mᵉhûwmân"]', '["to/ Mehuman"]', '["n-pr-m"]', 'Mehuman, a eunuch of Xerxes Mehuman.', 'of Persian origin;');
