INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3308}/H9024/[H3302]', 'inflected', 'heb', 'יֳפִי', '["yŏphîy"]', '["beauty/ her"]', '["n-m"]', 'beauty beauty.', 'from 3302;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2534}/H9023/[H3179]', 'inflected', 'heb', 'חֵמָה', '["chêmâh"]', '["and/ rage/ his"]', '["n-f"]', 'heat; figuratively, anger, poison (from its fever) anger, bottles, hot displeasure, furious(-ly, -ry), heat, indignation, poison, rage, wrath(-ful). See 2529.', 'or (Daniel 11:44) חֵמָא; from 3179;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1779}/[H1777]', 'inflected', 'heb', 'דִּין', '["dîyn"]', '["and/ judgment","and/ judgment of"]', '["n-m"]', 'judgement (the suit, justice, sentence or tribunal); by implication also strife cause, judgement, plea, strife.', 'or (Job 19:29) דּוּן; from 1777;');
