INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4826}/[H4826]', 'lemma', 'heb', 'מַרְסְנָא', '["Marçᵉnâʼ"]', '["Marsena"]', '["n-pr-m"]', 'Marsena, a Persian Marsena.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4462}/[H4462]', 'lemma', 'heb', 'מְמוּכָן', '["Mᵉmûwkân"]', '["Memucan"]', '["n-pr-m"]', 'Memucan or Momucan, a Persian satrap Memucan.', 'or (transp.) מוֹמֻכָן; (Esther 1:16), of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4436H}/[H4428]', 'inflected', 'heb', 'מַלְכָּה', '["malkâh"]', '["with the/ queen"]', '["n-f"]', 'a queen queen.', 'feminine of 4428;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3982}/[H559]', 'lemma', 'heb', 'מַאֲמַר', '["maʼămar"]', '["[the] command of"]', '["n-m"]', 'something (authoritatively) said, i.e. an edict commandment, decree.', 'from 559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/<H5631>\', 'inflected', 'heb', 'הסריסים ס', '["ha./sa.ri.Sim"]', '["the/ eunuchs"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0959}/[H959]', 'inflected', 'heb', 'בָּזָה', '["bâzâh"]', '["to/ despise","to/ make despicable"]', '["v"]', 'to disesteem despise, disdain, contemn(-ptible), think to scorn, vile person.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1167H}/H9029/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["husbands/ their"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5869I}/H9029/[H5869]', 'inflected', 'heb', 'עַיִן', '["ʻayin"]', '["in/ view/ their"]', '["n-f"]', 'an eye (literally or figuratively); by analogy, a fountain (as the eye of the landscape) affliction, outward appearance, before, think best, colour, conceit, be content, countenance, displease, eye((-brow), (-d), -sight), face, favour, fountain, furrow (from the margin), × him, humble, knowledge, look, ( well), × me, open(-ly), (not) please, presence, regard, resemblance, sight, × thee, × them, think, × us, well, × you(-rselves).', 'probably a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0559}/H9048/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["because/ will say/ they","when/ say/ they"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/<H3117L>', 'inflected', 'heb', 'והיום', '["ve./hai./Yom"]', '["and/ the/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9004/<H1767>', 'inflected', 'heb', 'וכדי', '["u./khe./Dai"]', '["and/ [will be] as/ enough of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0963}/[H959]', 'lemma', 'heb', 'בִּזָּיוֹן', '["bizzâyôwn"]', '["contempt"]', '["n-m"]', 'disesteem contempt.', 'from 959');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7110A}/[H7107]', 'inflected', 'heb', 'קֶצֶף', '["qetseph"]', '["and/ anger"]', '["n-m"]', 'a splinter (as chipped off); figuratively, rage or strife foam, indignation, × sore, wrath.', 'from 7107;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1881}/[H1881]', 'inflected', 'heb', 'דָּת', '["dâth"]', '["in/ [the] laws of"]', '["n-f"]', 'a royal edict or statute commandment, commission, decree, law, manner.', 'of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4074I}/[H4074]', 'inflected', 'heb', 'מָדַי', '["Mâday"]', '["and/ Media"]', '["n-pr-m n-pr-loc"]', 'Madai, a country of central Asia Madai, Medes, Media.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4438}/H9024/[H4427]', 'inflected', 'heb', 'מַלְכוּת', '["malkûwth"]', '["and/ queenhood/ her"]', '["n-f"]', 'a rule; concretely, a dominion empire, kingdom, realm, reign, royal.', 'or מַלְכֻת; or (in plural) מַלְכֻיָּה; from 4427;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H7468}/H9024/[H7462]', 'inflected', 'heb', 'רְעוּת', '["rᵉʻûwth"]', '["to/ fellow woman/ her"]', '["n-f"]', 'a female associate; generally an additional one another, mate, neighbour.', 'from 7462 in the sense of 7453;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6599}/[H6599]', 'lemma', 'heb', 'פִּתְגָּם', '["pithgâm"]', '["[the] decree of","[the] sentence of"]', '["n-m"]', 'a (judicial) sentence decree, sentence.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H1167H}/H9029/[H1166]', 'inflected', 'heb', 'בַּעַל', '["baʻal"]', '["to/ husbands/ their"]', '["n-m"]', 'a master; hence, a husband, or (figuratively) owner (often used with another noun in modifications of this latter sense) archer, babbler, bird, captain, chief man, confederate, have to do, dreamer, those to whom it is due, furious, those that are given to it, great, hairy, he that hath it, have, horseman, husband, lord, man, married, master, person, sworn, they of.', 'from 1166;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4082}/[H1777]', 'inflected', 'heb', 'מְדִינָה', '["mᵉdîynâh"]', '["and/ province"]', '["n-f"]', 'properly, a judgeship, i.e. jurisdiction; by implication, a district (as ruled by a judge); generally, a region (× every) province.', 'from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3791}/H9024/[H3789]', 'inflected', 'heb', 'כָּתָב', '["kâthâb"]', '["according to/ writing/ its"]', '["n-m"]', 'something written, i.e. a writing, record or book register, scripture, writing.', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3956H}/H9023/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["according to/ language/ its"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H3956H}/[H3960]', 'inflected', 'heb', 'לָשׁוֹן', '["lâshôwn"]', '["according to/ [the] language of"]', '["n-m"]', 'the tongue (of man or animals), used literally (as the instrument of licking, eating, or speech), and figuratively (speech, an ingot, a fork of flame, a cove of water) babbler, bay, evil speaker, language, talker, tongue, wedge.', 'or לָשֹׁן; also (in plural) feminine לְשֹׁנָה; from 3960;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H7918}/[H7918]', 'inflected', 'heb', 'שָׁכַךְ', '["shâkak"]', '["as/ bend","when/ subsided"]', '["v"]', 'to weave (i.e. lay) a trap; figuratively, (through the idea of secreting) to allay (passions; physically, abate a flood) appease, assuage, make to cease, pacify, set.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7800}/[H7799]', 'lemma', 'heb', 'שׁוּשַׁן', '["Shûwshan"]', '["Susa"]', '["n-pr-loc"]', 'Shushan, a place in Persia Shushan.', 'the same as 7799;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1896}/[H1896]', 'lemma', 'heb', 'הֵגֵא', '["Hêgêʼ"]', '["Hegai"]', '["n-pr-m"]', 'Hege or Hegai, a eunuch of Xerxes Hegai, Hege.', 'or (by permutation) הֵגַי; probably of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8562}/H9029/[H4838]', 'inflected', 'heb', 'תַּמְרוּק', '["tamrûwq"]', '["rubbings/ their"]', '["n-m"]', 'properly, a scouring, i.e. soap or perfumery for the bath; figuratively, a detergent × cleanse, (thing for) purification(-fying).', 'or תַּמְרֻק; or תַּמְרִיק; from 4838;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3064}/[H3063]', 'lemma', 'heb', 'יְהוּדִי', '["Yᵉhûwdîy"]', '["Jewish","Jews","[was] a Jew"]', '["n-m"]', 'a Jehudite (i.e. Judaite or Jew), or descendant of Jehudah (i.e. Judah) Jew.', 'patronymically from 3063;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4782H}/[H4782]', 'lemma', 'heb', 'מׇרְדְּכַי', '["Mordᵉkay"]', '["Mordecai","[was] Mordecai"]', '["n-pr-m"]', 'Mordecai, an Israelite Mordecai.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2971J}/[H215]', 'lemma', 'heb', 'יָאִיר', '["Yâʼîyr"]', '["Jair"]', '["n-pr-m"]', 'Jair, the name of four Israelites Jair.', 'from 215; enlightener;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8096U}/[H8088]', 'lemma', 'heb', 'שִׁמְעִי', '["Shimʻîy"]', '["Shimei"]', '["n-pr-m"]', 'Shimi, the name of twenty Israelites Shimeah (from the margin), Shimei, Shimhi, Shimi.', 'from 8088; famous;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7027J}/[H6983]', 'lemma', 'heb', 'קִישׁ', '["Qîysh"]', '["Kish"]', '["n-pr-m"]', 'Kish, the name of five Israelites Kish.', 'from 6983; a bow;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1919}/[H1918]', 'lemma', 'heb', 'הֲדַסָּה', '["Hădaççâh"]', '["Hadassah"]', '["n-pr-f"]', 'Hadassah (or Esther) Hadassah.', 'feminine of 1918;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0635}/[H635]', 'lemma', 'heb', 'אֶסְתֵּר', '["ʼEçtêr"]', '["Esther","O Esther","[is] Esther"]', '["n-pr-f"]', 'Ester, the Jewish heroine Esther.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H4194}/[H4191]', 'inflected', 'heb', 'מָוֶת', '["mâveth"]', '["and/ at/ [the] death of"]', '["n-m"]', 'death (natural or violent); concretely, the dead, their place or state (hades); figuratively, pestilence, ruin (be) dead(-ly), death, die(-d).', 'from 4191;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H8085I}/[H8085]', 'inflected', 'heb', 'שָׁמַע', '["shâmaʻ"]', '["when/ were heard"]', '["v"]', 'to hear intelligently (often with implication of attention, obedience, etc.; causatively, to tell, etc.) × attentively, call (gather) together, × carefully, × certainly, consent, consider, be content, declare, × diligently, discern, give ear, (cause to, let, make to) hear(-ken, tell), × indeed, listen, make (a) noise, (be) obedient, obey, perceive, (make a) proclaim(-ation), publish, regard, report, shew (forth), (make a) sound, × surely, tell, understand, whosoever (heareth), witness.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1881}/H9023/[H1881]', 'inflected', 'heb', 'דָּת', '["dâth"]', '["and/ law/ his","and/ orders/ his"]', '["n-f"]', 'a royal edict or statute commandment, commission, decree, law, manner.', 'of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H6908}/[H6908]', 'inflected', 'heb', 'קָבַץ', '["qâbats"]', '["and/ when/ were gathered"]', '["v"]', 'to grasp, i.e. collect assemble (selves), gather (bring) (together, selves together, up), heap, resort, × surely, take up.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440N}/H9023/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ him"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8562}/H9024/[H4838]', 'inflected', 'heb', 'תַּמְרוּק', '["tamrûwq"]', '["rubbings/ her"]', '["n-m"]', 'properly, a scouring, i.e. soap or perfumery for the bath; figuratively, a detergent × cleanse, (thing for) purification(-fying).', 'or תַּמְרֻק; or תַּמְרִיק; from 4838;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4490}/H9024/[H4487]', 'inflected', 'heb', 'מָנָה', '["mânâh"]', '["portions/ her"]', '["n-f"]', 'properly, something weighed out, i.e. (generally) a division; specifically (of food) a ration; also a lot such things as belonged, part, portion.', 'from 4487;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H7200J}/[H7200]', 'inflected', 'heb', 'רָאָה', '["râʼâh"]', '["<the>/ chosen"]', '["v"]', 'to see, literally or figuratively (in numerous applications, direct and implied, transitive, intransitive and causative) advise self, appear, approve, behold, × certainly, consider, discern, (make to) enjoy, have experience, gaze, take heed, × indeed, × joyfully, lo, look (on, one another, one on another, one upon another, out, up, upon), mark, meet, × be near, perceive, present, provide, regard, (have) respect, (fore-, cause to, let) see(-r, -m, one another), shew (self), × sight of others, (e-) spy, stare, × surely, × think, view, visions.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H8138A}/H9034/[H8138]', 'inflected', 'heb', 'שָׁנָה', '["shânâh"]', '["and/ he moved/ her"]', '["v"]', 'to fold, i.e. duplicate (literally or figuratively); by implication, to transmute (transitive or intransitive) do (speak, strike) again, alter, double, (be given to) change, disguise, (be) diverse, pervert, prefer, repeat, return, do the second time.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4138}/H9024/[H3205]', 'inflected', 'heb', 'מוֹלֶדֶת', '["môwledeth"]', '["kindred/ her"]', '["n-f"]', 'nativity (plural birth-place); by implication, lineage, native country; also offspring, family begotten, born, issue, kindred, native(-ity).', 'from 3205;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H3117J>', 'inflected', 'heb', 'ויום', '["va./Yom"]', '["and/ a day","and/ day"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H5060}/[H5060]', 'inflected', 'heb', 'נָגַע', '["nâgaʻ"]', '["and/ when/ arrived"]', '["v"]', 'properly, to touch, i.e. lay the hand upon (for any purpose; euphemistically, to lie with a woman); by implication, to reach (figuratively, to arrive, acquire); violently, to strike (punish, defeat, destroy, etc.) beat, (× be able to) bring (down), cast, come (nigh), draw near (nigh), get up, happen, join, near, plague, reach (up), smite, strike, touch.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8447}/[H8446]', 'lemma', 'heb', 'תּוֹר', '["tôwr"]', '["[the] turn of","necklaces of"]', '["n-m"]', 'a succession, i.e. a string or (abstractly) order border, row, turn.', 'or תֹּר; from 8446;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5291}/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["and/ a young woman"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4795}/H9029/[H4838]', 'inflected', 'heb', 'מָרוּק', '["mârûwq"]', '["rubbings/ their"]', '["n-m"]', 'properly, rubbed; but used abstractly, a rubbing (with perfumery) purification.', 'from 4838;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H4753}/[H4843]', 'inflected', 'heb', 'מֹר', '["môr"]', '["<the>/ myrrh"]', '["n-m"]', 'myrrh (as distilling in drops, and also as bitter) myrrh.', 'or מוֹר; from 4843;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H1314}/[H1313]', 'inflected', 'heb', 'בֶּשֶׂם', '["besem"]', '["with <the>/ balsam oil"]', '["n-m"]', 'fragrance; by implication, spicery; also the balsam plant smell, spice, sweet (odour).', 'or בֹּשֶׂם; from the same as 1313;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H8562}/[H4838]', 'inflected', 'heb', 'תַּמְרוּק', '["tamrûwq"]', '["and/ with/ [the] rubbings of"]', '["n-m"]', 'properly, a scouring, i.e. soap or perfumery for the bath; figuratively, a detergent × cleanse, (thing for) purification(-fying).', 'or תַּמְרֻק; or תַּמְרִיק; from 4838;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H2088}/[H2088]', 'inflected', 'heb', 'זֶה', '["zeh"]', '["and/ in/ this [way]"]', '["d"]', 'the masculine demonstrative pronoun, this or that he, × hence, × here, it(-self), × now, × of him, the one...the other, × than the other, (× out of) the (self) same, such (a one) that, these, this (hath, man), on this side...on that side, × thus, very, which. Compare 2063, 2090, 2097, 2098.', 'a primitive word;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8190}/[H8190]', 'lemma', 'heb', 'שַׁעַשְׁגַּז', '["Shaʻashgaz"]', '["Shaashgaz"]', '["n-pr-m"]', 'Shaashgaz, a eunuch of Xerxes Shaashgaz.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0032K}/[H1]', 'lemma', 'heb', 'אֲבִיהַיִל', '["ʼĂbîyhayil"]', '["Abihail"]', '["n-pr-m"]', 'Abihail or Abichail, the name of three Israelites and two Israelitesses Abihail.', 'or (more correctly) אֲבִיחַיִל ; from 1 and 2428; father (i.e. possessor) of might;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2887}/[H2887]', 'lemma', 'heb', 'טֵבֶת', '["Ṭêbeth"]', '["Tebeth"]', '["n"]', 'Tebeth, the tenth Hebrew month Tebeth.', 'probably of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3804}/[H3803]', 'lemma', 'heb', 'כֶּתֶר', '["kether"]', '["a crown of","a head-dress of"]', '["n-m"]', 'properly, a circlet, i.e. a diadem crown.', 'from 3803;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/<H7218A>/H9024', 'inflected', 'heb', 'בראשה', '["be./ro.Sha/h"]', '["on/ head/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H4427A}/H9034/[H4427]', 'inflected', 'heb', 'מָלַךְ', '["mâlak"]', '["and/ he made queen/ her"]', '["v"]', 'to reign; inceptively, to ascend the throne; causatively, to induct into royalty; hence (by implication) to take counsel consult, × indeed, be (make, set a, set up) king, be (make) queen, (begin to, make to) reign(-ing), rule, × surely.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2010}/[H5117]', 'inflected', 'heb', 'הֲנָחָה', '["hănâchâh"]', '["and/ a holiday"]', '["n-f"]', 'permission of rest, i.e. quiet release.', 'from 5117;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4082}/[H1777]', 'inflected', 'heb', 'מְדִינָה', '["mᵉdîynâh"]', '["for the/ provinces"]', '["n-f"]', 'properly, a judgeship, i.e. jurisdiction; by implication, a district (as ruled by a judge); generally, a region (× every) province.', 'from 1777;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4782H}/[H4782]', 'inflected', 'heb', 'מׇרְדְּכַי', '["Mordᵉkay"]', '["and/ Mordecai"]', '["n-pr-m"]', 'Mordecai, an Israelite Mordecai.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H0545}/[H544]', 'inflected', 'heb', 'אׇמְנָה', '["ʼomnâh"]', '["in/ guardianship"]', '["n-f"]', 'tutelage brought up.', 'feminine of 544 (in the specific sense of training);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0904}/[H903]', 'lemma', 'heb', 'בִּגְתָן', '["Bigthân"]', '["Bigthan","Bigthana"]', '["n-pr-m"]', 'Bigthan or Bigthana, a eunuch of Xerxes Bigthan, Bigthana.', 'or בִּגְתָנָא; of similar derivation to 903;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8657}/[H8657]', 'inflected', 'heb', 'תֶּרֶשׁ', '["Teresh"]', '["and/ Teresh"]', '["n-pr-m"]', 'Teresh, a eunuch of Xerxes Teresh.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/{H8104H}/[H8104]', 'inflected', 'heb', 'שָׁמַר', '["shâmar"]', '["from/ [the] guards of","more than/ watchmen"]', '["v"]', 'properly, to hedge about (as with thorns), i.e. guard; generally, to protect, attend to, etc. beward, be circumspect, take heed (to self), keep(-er, self), mark, look narrowly, observe, preserve, regard, reserve, save (self), sure, (that lay) wait (for), watch(-man).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H4782H}/[H4782]', 'inflected', 'heb', 'מׇרְדְּכַי', '["Mordᵉkay"]', '["for/ Mordecai","to/ Mordecai"]', '["n-pr-m"]', 'Mordecai, an Israelite Mordecai.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0635}/[H635]', 'inflected', 'heb', 'אֶסְתֵּר', '["ʼEçtêr"]', '["to/ Esther"]', '["n-pr-f"]', 'Ester, the Jewish heroine Esther.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1697K}/[H1696]', 'inflected', 'heb', 'דָּבָר', '["dâbâr"]', '["the/ matter"]', '["n-m"]', 'a word; by implication, a matter (as spoken of) or thing; adverbially, a cause act, advice, affair, answer, × any such (thing), because of, book, business, care, case, cause, certain rate, chronicles, commandment, × commune(-ication), concern(-ing), confer, counsel, dearth, decree, deed, × disease, due, duty, effect, eloquent, errand, (evil favoured-) ness, glory, harm, hurt, iniquity, judgment, language, lying, manner, matter, message, (no) thing, oracle, × ought, × parts, pertaining, please, portion, power, promise, provision, purpose, question, rate, reason, report, request, × (as hast) said, sake, saying, sentence, sign, so, some (uncleanness), somewhat to say, song, speech, × spoken, talk, task, that, × there done, thing (concerning), thought, thus, tidings, what(-soever), wherewith, which, word, work.', 'from 1696;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6086J}/[H6095]', 'lemma', 'heb', 'עֵץ', '["ʻêts"]', '["a gallows"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2001}/[H2001]', 'lemma', 'heb', 'הָמָן', '["Hâmân"]', '["Haman"]', '["n-pr-m"]', 'Haman, a Persian vizier Haman.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H4099}/[H4099]', 'lemma', 'heb', 'מְדָתָא', '["Mᵉdâthâʼ"]', '["Hammedatha"]', '["n-pr-m"]', 'Medatha, the father of Haman Hammedatha (including the article).', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H0091}/[H90]', 'inflected', 'heb', 'אֲגָגִי', '["ʼĂgâgîy"]', '["the/ Agagite"]', '["a"]', 'an Agagite or descendent (subject) of Agag Agagite.', 'patrial or patronymic from 90;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H5375L}/H9033/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["and/ he exalted/ him"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3678I}/H9023/[H3680]', 'inflected', 'heb', 'כִּסֵּא', '["kiççêʼ"]', '["seat/ his"]', '["n-m"]', 'properly, covered, i.e. a throne (as canopied) seat, stool, throne.', 'or כִּסֵּה; from 3680;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2001}/[H2001]', 'inflected', 'heb', 'הָמָן', '["Hâmân"]', '["to/ Haman"]', '["n-pr-m"]', 'Haman, a Persian vizier Haman.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9004/{H0559}/H9048/[H559]', 'inflected', 'heb', 'אָמַר', '["ʼâmar"]', '["just as/ spoke/ they"]', '["v"]', 'to say (used with great latitude) answer, appoint, avouch, bid, boast self, call, certify, challenge, charge, (at the, give) command(-ment), commune, consider, declare, demand, × desire, determine, × expressly, × indeed, × intend, name, × plainly, promise, publish, report, require, say, speak (against, of), × still, × suppose, talk, tell, term, × that is, × think, use (speech), utter, × verily, × yet.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9008/{H5975G}/[H5975]', 'inflected', 'heb', 'עָמַד', '["ʻâmad"]', '["¿/ will it endure","¿/ will they stand"]', '["v"]', 'to stand, in various relations (literal and figurative, intransitive and transitive) abide (behind), appoint, arise, cease, confirm, continue, dwell, be employed, endure, establish, leave, make, ordain, be (over), place, (be) present (self), raise up, remain, repair, serve, set (forth, over, -tle, up), (make to, make to be at a, with-) stand (by, fast, firm, still, up), (be at a) stay (up), tarry.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4782H}/[H4782]', 'inflected', 'heb', 'מׇרְדְּכַי', '["Mordᵉkay"]', '["on/ Mordecai"]', '["n-pr-m"]', 'Mordecai, an Israelite Mordecai.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6332}/[H6331]', 'lemma', 'heb', 'פּוּר', '["Pûwr"]', '["Pur","Purim"]', '["n-m"]', 'a lot (as by means of a broken piece) Pur, Purim.', 'also (plural) פּוּרִים; or פֻּרִים; from 6331;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9006/{H2320G}/[H2318]', 'inflected', 'heb', 'חֹדֶשׁ', '["chôdesh"]', '["and/ from/ month"]', '["n-m"]', 'the new moon; by implication, a month month(-ly), new moon.', 'from 2318;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0143}\/[H143]', 'inflected', 'heb', 'אֲדָר', '["ʼĂdâr"]', '["Adar"]', '["n"]', 'Adar, the 12th Hebrew month Adar.', 'probably of foreign derivation; perhaps meaning fire;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6340}/[H6340]', 'lemma', 'heb', 'פָּזַר', '["pâzar"]', '["[is one who] scatters","he has scattered","he scatters","scattered","they have been scattered","you scattered"]', '["v"]', 'to scatter, whether in enmity or bounty disperse, scatter (abroad).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6504}/[H6504]', 'inflected', 'heb', 'פָּרַד', '["pârad"]', '["and/ separated","and/ they have become dislocated"]', '["v"]', 'to break through, i.e. spread or separate (oneself) disperse, divide, be out of joint, part, scatter (abroad), separate (self), sever self, stretch, sunder.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1881}/H9028/[H1881]', 'inflected', 'heb', 'דָּת', '["dâth"]', '["and/ laws/ their"]', '["n-f"]', 'a royal edict or statute commandment, commission, decree, law, manner.', 'of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7737A}/[H7737]', 'lemma', 'heb', 'שָׁוָה', '["shâvâh"]', '["I have made still","I have placed","[is] adequate","[is] appropriate","[is] equal","he has leveled","it was equal","she is like","they compare","will I make equal","you should become like"]', '["v"]', 'properly, to level, i.e. equalize; figuratively, to resemble; by implication, to adjust (i.e. counterbalance, be suitable, compose, place, yield, etc.) avail, behave, bring forth, compare, countervail, (be, make) equal, lay, be (make, a-) like, make plain, profit, reckon.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H5117}/H9038/[H5117]', 'inflected', 'heb', 'נוּחַ', '["nûwach"]', '["to/ let remain/ them"]', '["v"]', 'to rest, i.e. settle down; used in a great variety of applications, literal and figurative, intransitive, transitive and causative (to dwell, stay, let fall, place, let alone, withdraw, give comfort, etc.) cease, be confederate, lay, let down, (be) quiet, remain, (cause to, be at, give, have, make to) rest, set down. Compare 3241.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H0006}/H9038/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["to/ destroy/ them"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H1595>', 'opaque', 'heb', 'גֶּנֶז', '["genez"]', '["[the] treasuries of"]', '["n-m"]', 'treasure; by implication, a coffer chest, treasury.', 'from an unused root meaning to store;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0323}/[H323]', 'lemma', 'heb', 'אֲחַשְׁדַּרְפַּן', '["ʼăchashdarpan"]', '["[the] satraps of"]', '["n-m"]', 'a satrap or governor of a main province (of Persia) lieutenant.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2856}/[H2856]', 'inflected', 'heb', 'חָתַם', '["châtham"]', '["and/ [it was] sealed","and/ it is sealed","and/ seal [it]","and/ seal up","and/ sealed up","and/ they will seal [it]"]', '["v"]', 'to close up; especially to seal make an end, mark, seal (up), stop.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H0006}/[H6]', 'inflected', 'heb', 'אָבַד', '["ʼâbad"]', '["and/ to/ destroy"]', '["v"]', 'properly, to wander away, i.e. lose oneself; by implication to perish (causative, destroy) break, destroy(-uction), not escape, fail, lose, (cause to, make) perish, spend, × and surely, take, be undone, × utterly, be void of, have no way to flee.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2945}/[H2952]', 'lemma', 'heb', 'טַף', '["ṭaph"]', '["little one[s]"]', '["n-m"]', 'a family (mostly used collectively in the singular) (little) children (ones), families.', 'from 2952 (perhaps referring to the tripping gait of children);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0143}/[H143]', 'lemma', 'heb', 'אֲדָר', '["ʼĂdâr"]', '["Adar"]', '["n"]', 'Adar, the 12th Hebrew month Adar.', 'probably of foreign derivation; perhaps meaning fire;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H7998}/H9028/[H7997]', 'inflected', 'heb', 'שָׁלָל', '["shâlâl"]', '["and/ spoil/ their"]', '["n-m"]', 'booty prey, spoil.', 'from 7997;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H6572B>', 'opaque', 'heb', 'פַּרְשֶׁגֶן', '["parshegen"]', '["<the> copy of"]', '["n-m"]', 'a transcript copy.', 'or פַּתְשֶׁגֶן; of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3791}/[H3789]', 'inflected', 'heb', 'כָּתָב', '["kâthâb"]', '["the/ writing"]', '["n-m"]', 'something written, i.e. a writing, record or book register, scripture, writing.', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1540J}/[H1540]', 'lemma', 'heb', 'גָּלָה', '["gâlâh"]', '["[was] disclosed","being disclosed"]', '["v"]', 'to denude (especially in a disgraceful sense); by implication, to exile (captives being usually stripped); figuratively, to reveal advertise, appear, bewray, bring, (carry, lead, go) captive (into captivity), depart, disclose, discover, exile, be gone, open, × plainly, publish, remove, reveal, × shamelessly, shew, × surely, tell, uncover.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9009/{H1881}/[H1881]', 'inflected', 'heb', 'דָּת', '["dâth"]', '["and/ the/ law"]', '["n-f"]', 'a royal edict or statute commandment, commission, decree, law, manner.', 'of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2001}/[H2001]', 'inflected', 'heb', 'הָמָן', '["Hâmân"]', '["and/ Haman"]', '["n-pr-m"]', 'Haman, a Persian vizier Haman.', 'of foreign derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0943}\/[H943]', 'inflected', 'heb', 'בּוּךְ', '["bûwk"]', '["it was in confusion"]', '["v"]', 'to involve (literally or figuratively) be entangled, (perplexed).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3830}/[H3847]', 'inflected', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["in/ clothing of"]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H3064}/[H3063]', 'inflected', 'heb', 'יְהוּדִי', '["Yᵉhûwdîy"]', '["[belonged] to the/ Jews","for the/ Jews","to the/ Jews"]', '["n-m"]', 'a Jehudite (i.e. Judaite or Jew), or descendant of Jehudah (i.e. Judah) Jew.', 'patronymically from 3063;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6685}/[H6684]', 'inflected', 'heb', 'צוֹם', '["tsôwm"]', '["and/ [the] fast of","and/ fasting"]', '["n-m"]', 'a fast fast(-ing).', 'or צֹם; from 6684;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1065}/[H1058]', 'inflected', 'heb', 'בְּכִי', '["Bᵉkîy"]', '["and/ weeping"]', '["n-m"]', 'a weeping; by analogy, a dripping overflowing, × sore, (continual) weeping, wept.', 'from 1058;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H4553}/[H5594]', 'inflected', 'heb', 'מִסְפֵּד', '["miçpêd"]', '["and/ wailing"]', '["n-m"]', 'a lamentation lamentation, one mourneth, mourning, wailing.', 'from 5594;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3331}/[H3331]', 'lemma', 'heb', 'יַצַע', '["yatsaʻ"]', '["he spreads as a bed","it is spread as a bed","it was spread as a bed"]', '["v"]', 'to strew as a surface make (one''s) bed, × lie, spread.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/<H5631>/H9024', 'inflected', 'heb', 'וסריסיה', '["ve./sa.ri.Sei./ha"]', '["and/ eunuchs/ her"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H2342A}/[H2342]', 'inflected', 'heb', 'חוּל', '["chûwl"]', '["and/ it trembled","and/ she agonized"]', '["v"]', 'properly, to twist or whirl (in a circular or spiral manner), i.e. (specifically) to dance, to writhe in pain (especially of parturition) or fear; figuratively, to wait, to pervert bear, (make to) bring forth, (make to) calve, dance, drive away, fall grievously (with pain), fear, form, great, grieve, (be) grievous, hope, look, make, be in pain, be much (sore) pained, rest, shake, shapen, (be) sorrow(-ful), stay, tarry, travail (with pain), tremble, trust, wait carefully (patiently), be wounded.', 'or חִיל; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5493G}/[H5493]', 'inflected', 'heb', 'סוּר', '["çûwr"]', '["and/ to/ remove"]', '["v"]', 'to turn off (literally or figuratively) be(-head), bring, call back, decline, depart, eschew, get (you), go (aside), × grievous, lay away (by), leave undone, be past, pluck away, put (away, down), rebel, remove (to and fro), revolt, × be sour, take (away, off), turn (aside, away, in), withdraw, be without.', 'or שׂוּר; (Hosea 9:12), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/<H2047>', 'inflected', 'heb', 'להתך', '["la./ha.Takh"]', '["<to>/ Hathach","to/ Hathach"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9006/<H5631>', 'inflected', 'heb', 'מסריסי', '["mi./sa.ri.Sei"]', '["one of/ [the] eunuchs of"]', NULL, NULL, NULL);
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H6440G}/H9024/[H6437]', 'inflected', 'heb', 'פָּנִים', '["pânîym"]', '["<to>/ before/ her","<to>/ before/ it"]', '["n-m"]', 'the face (as the part that turns); used in a great variety of applications (literally and figuratively); also (with prepositional prefix) as a preposition (before, etc.) accept, a-(be-) fore(-time), against, anger, × as (long as), at, battle, because (of), beseech, countenance, edge, employ, endure, enquire, face, favour, fear of, for, forefront(-part), form(-er time, -ward), from, front, heaviness, × him(-self), honourable, impudent, in, it, look(-eth) (-s), × me, meet, × more than, mouth, of, off, (of) old (time), × on, open, out of, over against, the partial, person, please, presence, propect, was purposed, by reason of, regard, right forth, serve, × shewbread, sight, state, straight, street, × thee, × them(-selves), through ( -out), till, time(-s) past, (un-) to(-ward), upon, upside ( down), with(-in, -stand), × ye, × you.', 'plural (but always as singular) of an unused noun פָּנֶה; from 6437);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('<H2047>', 'opaque', 'heb', 'הֲתָךְ', '["Hăthâk"]', '["Hathach"]', '["n-pr-m"]', 'Hathak, a Persian eunuch Hatach.', 'probably of foreign origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7136A}/H9033/[H7136]', 'inflected', 'heb', 'קָרָה', '["qârâh"]', '["it had happened to/ him"]', '["v"]', 'to light upon (chiefly by accident); causatively, to bring about; specifically, to impose timbers (for roof or floor) appoint, lay (make) beams, befall, bring, come (to pass unto), floor, (hap) was, happen (unto), meet, send good speed.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6575}/[H6567]', 'lemma', 'heb', 'פָּרָשָׁה', '["pârâshâh"]', '["[the] exact amount of"]', '["n-f"]', 'exposition declaration, sum.', 'from 6567;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8254}/[H8254]', 'inflected', 'heb', 'שָׁקַל', '["shâqal"]', '["to/ weigh out"]', '["v"]', 'to suspend or poise (especially in trade) pay, receive(-r), spend, × throughly, weigh.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3064}/[H3063]', 'inflected', 'heb', 'יְהוּדִי', '["Yᵉhûwdîy"]', '["by/ a Jew","for the/ Jews","on the/ Jews"]', '["n-m"]', 'a Jehudite (i.e. Judaite or Jew), or descendant of Jehudah (i.e. Judah) Jew.', 'patronymically from 3063;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3791}/[H3789]', 'lemma', 'heb', 'כָּתָב', '["kâthâb"]', '["[the] writing of","a writing"]', '["n-m"]', 'something written, i.e. a writing, record or book register, scripture, writing.', 'from 3789;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H1881}/[H1881]', 'inflected', 'heb', 'דָּת', '["dâth"]', '["the/ law"]', '["n-f"]', 'a royal edict or statute commandment, commission, decree, law, manner.', 'of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8045}/H9038/[H8045]', 'inflected', 'heb', 'שָׁמַד', '["shâmad"]', '["to/ annihilate/ them","to/ be destroyed/ they","to/ destroy/ them"]', '["v"]', 'to desolate destory(-uction), bring to nought, overthrow, perish, pluck down, × utterly.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H5046}/[H5046]', 'inflected', 'heb', 'נָגַד', '["nâgad"]', '["and/ to/ tell"]', '["v"]', 'properly, to front, i.e. stand boldly out opposite; by implication (causatively), to manifest; figuratively, to announce (always by word of mouth to one present); specifically, to expose, predict, explain, praise bewray, × certainly, certify, declare(-ing), denounce, expound, × fully, messenger, plainly, profess, rehearse, report, shew (forth), speak, × surely, tell, utter.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9005/{H6680}/[H6680]', 'inflected', 'heb', 'צָוָה', '["tsâvâh"]', '["and/ to/ command"]', '["v"]', '(intensively) to constitute, enjoin appoint, (for-) bid, (give a) charge, (give a, give in, send with) command(-er, -ment), send a messenger, put, (set) in order.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H2603A}/[H2583]', 'inflected', 'heb', 'חָנַן', '["chânan"]', '["for/ [one who] shows favor to","to/ seek favor"]', '["v"]', 'properly, to bend or stoop in kindness to an inferior; to favor, bestow; causatively to implore (i.e. move to favor by petition) beseech, × fair, (be, find, shew) favour(-able), be (deal, give, grant (gracious(-ly), intreat, (be) merciful, have (shew) mercy (on, upon), have pity upon, pray, make supplication, × very.', 'a primitive root (compare 2583);');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1881}/H9023/[H1881]', 'inflected', 'heb', 'דָּת', '["dâth"]', '["law/ his"]', '["n-f"]', 'a royal edict or statute commandment, commission, decree, law, manner.', 'of uncertain (perhaps foreign) derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3447}/[H3447]', 'lemma', 'heb', 'יָשַׁט', '["yâshaṭ"]', '["he extends"]', '["v"]', 'to extend hold out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8275}/[H7626]', 'lemma', 'heb', 'שַׁרְבִיט', '["sharbîyṭ"]', '["[the] scepter of"]', '["n-m"]', 'a rod of empire sceptre.', 'for 7626;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0635}\/[H635]', 'inflected', 'heb', 'אֶסְתֵּר', '["ʼEçtêr"]', '["Esther"]', '["n-pr-f"]', 'Ester, the Jewish heroine Esther.', 'of Persian derivation;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H5315I}/H9022/[H5314]', 'inflected', 'heb', 'נֶפֶשׁ', '["nephesh"]', '["in/ self/ your"]', '["n-f"]', 'properly, a breathing creature, i.e. animal of (abstractly) vitality; used very widely in a literal, accommodated or figurative sense (bodily or mental) any, appetite, beast, body, breath, creature, × dead(-ly), desire, × (dis-) contented, × fish, ghost, greedy, he, heart(-y), (hath, × jeopardy of) life (× in jeopardy), lust, man, me, mind, mortally, one, own, person, pleasure, (her-, him-, my-, thy-) self, them (your) -selves, slay, soul, tablet, they, thing, (× she) will, × would have it.', 'from 5314;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H7305}/[H7304]', 'lemma', 'heb', 'רֶוַח', '["revach"]', '["relief"]', '["n-m"]', 'room, literally (an interval) or figuratively (deliverance) enlargement, space.', 'from 7304;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2020}/[H5337]', 'inflected', 'heb', 'הַצָּלָה', '["hatstsâlâh"]', '["and/ deliverance"]', '["n-f"]', 'rescue deliverance.', 'from 5337;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3664}/[H3664]', 'lemma', 'heb', 'כָּנַס', '["kânaç"]', '["I gathered","[he is] gathering","gather","he gathers","to gather"]', '["v"]', 'to collect; hence, to enfold gather (together), heap up, wrap self.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H6684}/[H6684]', 'inflected', 'heb', 'צוּם', '["tsûwm"]', '["and/ fast"]', '["v"]', 'to cover over (the mouth), i.e. to fast × at all, fast.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H5291}/H9020/[H5288]', 'inflected', 'heb', 'נַעֲרָה', '["naʻărâh"]', '["and/ maids/ my"]', '["n-f"]', 'a girl (from infancy to adolescence) damsel, maid(-en), young (woman).', 'feminine of 5288;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/H9003/{H3651C}/[H3559]', 'inflected', 'heb', 'כֵּן', '["kên"]', '["and/ in/ such"]', '["adv"]', 'properly, set upright; hence (figuratively as adjective) just; but usually (as adverb or conjunction) rightly or so (in various applications to manner, time and relation; often with other particles) after that (this, -ward, -wards), as... as, (for-) asmuch as yet, be (for which) cause, following, howbeit, in (the) like (manner, -wise), × the more, right, (even) so, state, straightway, such (thing), surely, there (where) -fore, this, thus, true, well, × you.', 'from 3559;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9001/{H3447}/[H3447]', 'inflected', 'heb', 'יָשַׁט', '["yâshaṭ"]', '["and/ he extended"]', '["v"]', 'to extend hold out.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H8275}\/[H7626]', 'inflected', 'heb', 'שַׁרְבִיט', '["sharbîyṭ"]', '["the/ scepter"]', '["n-m"]', 'a rod of empire sceptre.', 'for 7626;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1246}/H9022/[H1245]', 'inflected', 'heb', 'בַּקָּשָׁה', '["baqqâshâh"]', '["[is] request/ your"]', '["n-m"]', 'a petition request.', 'from 1245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H4960}/[H8354]', 'inflected', 'heb', 'מִשְׁתֶּה', '["mishteh"]', '["at/ [the] feast of"]', '["n-m"]', 'drink, by implication, drinking (the act); also (by implication) a banquet or (generally) feast banquet, drank, drink, feast((-ed), -ing).', 'from 8354;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1246}/H9020/[H1245]', 'inflected', 'heb', 'בַּקָּשָׁה', '["baqqâshâh"]', '["and/ request/ my"]', '["n-m"]', 'a petition request.', 'from 1245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1246}/H9020/[H1245]', 'inflected', 'heb', 'בַּקָּשָׁה', '["baqqâshâh"]', '["request/ my"]', '["n-m"]', 'a petition request.', 'from 1245;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2111}/[H2111]', 'lemma', 'heb', 'זוּעַ', '["zûwaʻ"]', '["he trembled"]', '["v"]', 'properly, to shake off, i.e. (figuratively) to agitate (as with fear) move, tremble, vex.', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H0157H}/H9033/[H157]', 'inflected', 'heb', 'אָהַב', '["ʼâhab"]', '["friends/ his"]', '["v"]', 'to have affection for (sexually or otherwise) (be-) love(-d, -ly, -r), like, friend.', 'or אָהֵב ; a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H2238}/[H2238]', 'lemma', 'heb', 'זֶרֶשׁ', '["Zeresh"]', '["Zeresh"]', '["n-pr-f"]', 'Zeresh, Haman''s wife Zeresh.', 'of Persian origin;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H6239}/H9023/[H6238]', 'inflected', 'heb', 'עֹשֶׁר', '["ʻôsher"]', '["[is] wealth/ his","rich[es]/ his","wealth/ his"]', '["n-m"]', 'wealth × far (richer), riches.', 'from 6238;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H1431}/H9033/[H1434]', 'inflected', 'heb', 'גָּדַל', '["gâdal"]', '["he had made great/ him","they made grow/ it","you had made grow/ it","you will make great/ him"]', '["v"]', 'to be (causatively make) large (in various senses, as in body, mind, estate or honor, also in pride) advance, boast, bring up, exceed, excellent, be(-come, do, give, make, wax), great(-er, come to... estate, things), grow(up), increase, lift up, magnify(-ifical), be much set by, nourish (up), pass, promote, proudly (spoken), tower.', 'a primitive root; properly, to twist (compare 1434), i.e.');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5375L}/H9033/[H5375]', 'inflected', 'heb', 'נָשָׂא', '["nâsâʼ"]', '["he had exalted/ him"]', '["v"]', 'to lift, in a great variety of applications, literal and figurative, absolute and relative accept, advance, arise, (able to, (armor), suffer to) bear(-er, up), bring (forth), burn, carry (away), cast, contain, desire, ease, exact, exalt (self), extol, fetch, forgive, furnish, further, give, go on, help, high, hold up, honorable ( man), lade, lay, lift (self) up, lofty, marry, magnify, × needs, obtain, pardon, raise (up), receive, regard, respect, set (up), spare, stir up, swear, take (away, up), × utterly, wear, yield.', 'or נָסָה; (Psalm 4:6 [7]), a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H8518}/[H8518]', 'inflected', 'heb', 'תָּלָה', '["tâlâh"]', '["so/ people may hang"]', '["v"]', 'to suspend (especially to gibbet) hang (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H6086J}\/[H6095]', 'inflected', 'heb', 'עֵץ', '["ʻêts"]', '["the/ gallows"]', '["n-m"]', 'a tree (from its firmness); hence, wood (plural sticks) carpenter, gallows, helve, pine, plank, staff, stalk, stick, stock, timber, tree, wood.', 'from 6095;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H8142}/[H3462]', 'lemma', 'heb', 'שֵׁנָה', '["shênâh"]', '["[the] sleep of","a sleep of","sleep","sleep<s>"]', '["n-f"]', 'sleep sleep.', 'or שֵׁנָא; (Psalm 127:2), from 3462;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H1420}/[H1419]', 'inflected', 'heb', 'גְּדוּלָה', '["gᵉdûwlâh"]', '["and/ greatness"]', '["n-f"]', 'greatness; (concretely) mighty acts dignity, great things(-ness), majesty.', 'or גְּדֻלָּה; (shortened) or (less accurately) גְּדוּלָּה; feminine of 1419;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9005/{H8518}/[H8518]', 'inflected', 'heb', 'תָּלָה', '["tâlâh"]', '["to/ hang"]', '["v"]', 'to suspend (especially to gibbet) hang (up).', 'a primitive root;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9003/{H3366}/H9023/[H3365]', 'inflected', 'heb', 'יְקָר', '["yᵉqâr"]', '["in/ honor/ his"]', '["n-m"]', 'value, i.e. (concretely) wealth; abstractly, costliness, dignity honour, precious (things), price.', 'from 3365;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H3148}/[H3498]', 'lemma', 'heb', 'יוֹתֵר', '["yôwthêr"]', '["advantage","excess","excessively"]', '["n-m"]', 'properly, redundant; hence, over and above, as adjective, noun, adverb or conjunction better, more(-over), over, profit.', 'active participle of 3498;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9009/{H3830}/[H3847]', 'inflected', 'heb', 'לְבוּשׁ', '["lᵉbûwsh"]', '["the/ clothing"]', '["n-m"]', 'a garment (literally or figuratively); by implication (euphemistically) a wife apparel, clothed with, clothing, garment, raiment, vestment, vesture.', 'or לְבֻשׁ; from 3847;');
INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('H9002/{H2645}/[H2644]', 'inflected', 'heb', 'חָפָה', '["châphâh"]', '["and/ covered of"]', '["v"]', 'to cover; by implication, to veil, to encase, protect ceil, cover, overlay.', 'a primitive root (compare 2644, 2653);');
