INSERT OR IGNORE INTO dstrongs_chains (dstrongs_chain, type, language, aleph_bet, sbl_transliterations, glosses, pos, bdb, source_note) VALUES ('{H5750}/H9048/[H5749]', 'inflected', 'heb', 'עוֹד', '["ʻôwd"]', '["still/ they"]', '["adv"]', 'properly, iteration or continuance; used only adverbially (with or without preposition), again, repeatedly, still, more again, × all life long, at all, besides, but, else, further(-more), henceforth, (any) longer, (any) more(-over), × once, since, (be) still, when, (good, the) while (having being), (as, because, whether, while) yet (within).', 'or עֹד; from 5749;');
